/**
 * Mock Supabase Client for Testing
 * Provides mock implementations of Supabase client methods
 */

import { vi } from "vitest";

export const createMockSupabaseClient = () => {
  const mockFrom = vi.fn();
  const mockSelect = vi.fn();
  const mockEq = vi.fn();
  const mockNeq = vi.fn();
  const mockOr = vi.fn();
  const mockContains = vi.fn();
  const mockGte = vi.fn();
  const mockLte = vi.fn();
  const mockOrder = vi.fn();
  const mockRange = vi.fn();
  const mockSingle = vi.fn();
  const mockInsert = vi.fn();
  const mockUpdate = vi.fn();
  const mockDelete = vi.fn();
  const mockRpc = vi.fn();

  // Chain the mock methods to return the chainable object
  const chainableObject = {
    select: mockSelect,
    eq: mockEq,
    neq: mockNeq,
    or: mockOr,
    contains: mockContains,
    gte: mockGte,
    lte: mockLte,
    order: mockOrder,
    range: mockRange,
    single: mockSingle,
    insert: mockInsert,
    update: mockUpdate,
    delete: mockDelete
  };

  // Make each method return the chainable object
  mockSelect.mockReturnValue(chainableObject);
  mockEq.mockReturnValue(chainableObject);
  mockNeq.mockReturnValue(chainableObject);
  mockOr.mockReturnValue(chainableObject);
  mockContains.mockReturnValue(chainableObject);
  mockGte.mockReturnValue(chainableObject);
  mockLte.mockReturnValue(chainableObject);
  mockOrder.mockReturnValue(chainableObject);
  mockRange.mockReturnValue(chainableObject);
  mockSingle.mockReturnValue(chainableObject);
  mockInsert.mockReturnValue(chainableObject);
  mockUpdate.mockReturnValue(chainableObject);
  mockDelete.mockReturnValue(chainableObject);

  return {
    from: mockFrom.mockReturnValue(chainableObject),
    rpc: mockRpc
  };
};

// Mock the entire Supabase module
export const mockSupabaseModule = {
  createClient: vi.fn(() => createMockSupabaseClient()),
  createClientFromRequest: vi.fn(() => ({
    client: createMockSupabaseClient(),
    getUser: vi.fn()
  }))
};

export default mockSupabaseModule;

/**
 * Integration test: auto-mode trigger engine.
 *
 * Verifies:
 * - checkTriggers produces events for low stock, upcoming appointments, overdue WOs
 * - Cooldown prevents duplicate events
 * - No irreversible actions are executed without confirmation
 *
 * @module tests/integration/agent/auto-mode
 */

import { describe, expect, it, vi } from "vitest";

import { checkTriggers } from "@/lib/ai/agent/auto-trigger";

const ORG_ID = "org-123";
const BRANCH_ID = "branch-456";

// ─── Supabase mock: plain factory that returns a chainable mock object ──────

function buildQueryChain(resolved: { data: unknown; error: null }) {
  const chain: Record<string, unknown> = {};
  const methods = ["lt", "eq", "gte", "lte", "in", "order", "select", "ilike"];
  for (const m of methods) {
    chain[m] = vi.fn(() => chain);
  }
  chain.limit = vi.fn().mockResolvedValue(resolved);
  return chain;
}

function buildSupabase() {
  return {
    from: vi.fn(),
  };
}

describe("auto-mode trigger engine", () => {
  describe("low_stock trigger", () => {
    it("produces warning events when stock is below threshold", async () => {
      const supabase = buildSupabase();
      supabase.from.mockImplementation((table: string) => {
        if (table === "product_branch_stock") {
          return {
            select: vi.fn(() =>
              buildQueryChain({
                data: [
                  {
                    product_id: "p1",
                    quantity: 2,
                    products: { name: "Lentes Sol" },
                  },
                  {
                    product_id: "p2",
                    quantity: 0,
                    products: { name: "Montura RX" },
                  },
                ],
                error: null,
              }),
            ),
          };
        }
        return {
          select: vi.fn(() => buildQueryChain({ data: [], error: null })),
        };
      });

      const events = await checkTriggers({
        supabase: supabase as unknown,
        orgId: ORG_ID,
        branchId: BRANCH_ID,
        lowStockThreshold: 5,
      });

      expect(events.length).toBeGreaterThanOrEqual(1);
      const stockEvents = events.filter((e) => e.type === "low_stock");
      expect(stockEvents.length).toBeGreaterThan(0);
      expect(stockEvents[0].severity).toBe("warning");
      expect(stockEvents[0].entity.type).toBe("product");
      expect(stockEvents[0].action.type).toBe("navigation");
      // ponytail: no irreversible action executed without confirmation
      expect(stockEvents[0].action.type).not.toBe("action");
    });

    it("produces critical severity when stock is 0", async () => {
      const supabase = buildSupabase();
      supabase.from.mockImplementation((table: string) => {
        if (table === "product_branch_stock") {
          return {
            select: vi.fn(() =>
              buildQueryChain({
                data: [
                  {
                    product_id: "p3",
                    quantity: 0,
                    products: { name: "Lente Progresivo" },
                  },
                ],
                error: null,
              }),
            ),
          };
        }
        return {
          select: vi.fn(() => buildQueryChain({ data: [], error: null })),
        };
      });

      // Use a unique org to avoid cooldown from previous test
      const events = await checkTriggers({
        supabase: supabase as unknown,
        orgId: "org-critical-test",
        branchId: BRANCH_ID,
        lowStockThreshold: 5,
      });

      const stockEvents = events.filter((e) => e.type === "low_stock");
      expect(stockEvents.length).toBeGreaterThan(0);
      expect(stockEvents[0].severity).toBe("critical");
    });
  });

  describe("upcoming_appointment trigger", () => {
    it("produces info events for appointments within 24h", async () => {
      const supabase = buildSupabase();
      const futureDate = new Date(Date.now() + 2 * 60 * 60 * 1000);

      supabase.from.mockImplementation((table: string) => {
        if (table === "appointments") {
          return {
            select: vi.fn(() =>
              buildQueryChain({
                data: [
                  {
                    id: "apt-1",
                    customer_name: "Juan Pérez",
                    scheduled_at: futureDate.toISOString(),
                  },
                ],
                error: null,
              }),
            ),
          };
        }
        return {
          select: vi.fn(() => buildQueryChain({ data: [], error: null })),
        };
      });

      const events = await checkTriggers({
        supabase: supabase as unknown,
        orgId: "org-apt-test",
        branchId: BRANCH_ID,
      });

      const aptEvents = events.filter((e) => e.type === "upcoming_appointment");
      if (aptEvents.length > 0) {
        expect(aptEvents[0].severity).toBe("info");
        expect(aptEvents[0].entity.type).toBe("appointment");
        expect(aptEvents[0].message).toContain("Juan Pérez");
      }
    });
  });

  describe("overdue_work_order trigger", () => {
    it("produces warning events for overdue work orders", async () => {
      const supabase = buildSupabase();
      const pastDate = new Date(Date.now() - 24 * 60 * 60 * 1000);

      supabase.from.mockImplementation((table: string) => {
        if (table === "lab_work_orders") {
          return {
            select: vi.fn(() =>
              buildQueryChain({
                data: [
                  {
                    id: "wo-1",
                    title: "Armazón receta urgente",
                    deadline: pastDate.toISOString(),
                  },
                ],
                error: null,
              }),
            ),
          };
        }
        return {
          select: vi.fn(() => buildQueryChain({ data: [], error: null })),
        };
      });

      const events = await checkTriggers({
        supabase: supabase as unknown,
        orgId: "org-wo-test",
        branchId: null,
      });

      const woEvents = events.filter((e) => e.type === "overdue_work_order");
      if (woEvents.length > 0) {
        expect(woEvents[0].severity).toBe("warning");
        expect(woEvents[0].entity.type).toBe("work_order");
        expect(woEvents[0].message).toContain("urgente");
      }
    });
  });

  describe("cooldown", () => {
    it("prevents duplicate events within cooldown window", async () => {
      const supabase = buildSupabase();
      supabase.from.mockImplementation((table: string) => {
        if (table === "product_branch_stock") {
          return {
            select: vi.fn(() =>
              buildQueryChain({
                data: [
                  { product_id: "p1", quantity: 2, products: { name: "Test" } },
                ],
                error: null,
              }),
            ),
          };
        }
        return {
          select: vi.fn(() => buildQueryChain({ data: [], error: null })),
        };
      });

      // First call — should produce events
      const first = await checkTriggers({
        supabase: supabase as unknown,
        orgId: "cooldown-org",
        branchId: null,
        lowStockThreshold: 5,
      });
      expect(
        first.filter((e) => e.type === "low_stock").length,
      ).toBeGreaterThan(0);

      // Second call immediately after — cooldown active, no new low_stock events
      const second = await checkTriggers({
        supabase: supabase as unknown,
        orgId: "cooldown-org",
        branchId: null,
        lowStockThreshold: 5,
      });
      const lowStockEvents = second.filter((e) => e.type === "low_stock");
      expect(lowStockEvents.length).toBe(0);
    });
  });
});

/**
 * Integration test: full agent cycle with cost tracking.
 *
 * Verifies:
 * - Cost tracking: token_count persisted via logTokenUsage
 * - Trigger event shape matches contract
 * - Preferences key format
 *
 * @module tests/integration/agent/full-cycle
 */

import { describe, expect, it } from "vitest";

import { logTokenUsage } from "@/lib/ai/usage-logger";

// ─── Fluent Supabase mock for logTokenUsage ────────────────────────────────
//
// logTokenUsage does:
//   supabase.from("chat_messages").update({...}).eq("id", msgId)
//   supabase.from("chat_sessions").select("metadata").eq("id", sessionId).single()
//   supabase.from("chat_sessions").update({...}).eq("id", sessionId)

function buildFluentMock() {
  const singleResolved = {
    data: {
      metadata: { token_count: { prompt: 100, completion: 50, total: 150 } },
    },
    error: null,
  };
  const updateResolved = { error: null };

  // An eq method that returns a promise (terminal call)
  const eqThenResolve = vi.fn().mockResolvedValue(updateResolved);
  const singleThenResolve = vi.fn().mockResolvedValue(singleResolved);

  // Building blocks
  const withEq = { eq: eqThenResolve };
  const withSelect = {
    eq: vi.fn(() => ({ single: singleThenResolve })),
  };

  return {
    from: vi.fn(() => ({
      update: vi.fn(() => withEq),
      select: vi.fn(() => withSelect),
      insert: vi.fn(() => withEq),
    })),
  };
}

describe("full agent cycle", () => {
  describe("cost tracking", () => {
    it("logTokenUsage calls from('chat_messages') and from('chat_sessions')", async () => {
      const supabase = buildFluentMock();

      await logTokenUsage(supabase as unknown, {
        sessionId: "session-1",
        messageId: "msg-1",
        promptTokens: 150,
        completionTokens: 75,
      });

      // Should have called from("chat_messages") for message update
      expect(supabase.from).toHaveBeenCalledWith("chat_messages");
      // Should have called from("chat_sessions") for session select + update
      expect(supabase.from).toHaveBeenCalledWith("chat_sessions");
    });

    it("logTokenUsage does not throw on error", async () => {
      const throwingSupabase = {
        from: vi.fn(() => {
          throw new Error("DB error");
        }),
      };

      await expect(
        logTokenUsage(throwingSupabase as unknown, {
          sessionId: "session-err",
          messageId: "msg-err",
          promptTokens: 100,
          completionTokens: 50,
        }),
      ).resolves.toBeUndefined();
    });

    it("logAIUsage still exists (backward compat)", async () => {
      const { logAIUsage } = await import("@/lib/ai/usage-logger");
      expect(logAIUsage).toBeDefined();
      expect(typeof logAIUsage).toBe("function");
    });
  });

  describe("trigger event shape", () => {
    it("trigger events contain correct fields and no irreversible actions by default", async () => {
      const sampleEvent = {
        type: "low_stock" as const,
        severity: "warning" as const,
        entity: { id: "p1", name: "Lentes Sol", type: "product" },
        action: {
          label: "Ver producto",
          type: "navigation" as const,
          payload: { path: "/admin/products/p1" },
        },
        message: 'Stock bajo: "Lentes Sol" tiene 2 unidades.',
      };

      expect(sampleEvent.type).toBe("low_stock");
      expect(sampleEvent.severity).toBe("warning");
      expect(sampleEvent.entity).toHaveProperty("id");
      expect(sampleEvent.entity).toHaveProperty("name");
      expect(sampleEvent.entity).toHaveProperty("type");
      expect(sampleEvent.action).toHaveProperty("label");
      expect(sampleEvent.action).toHaveProperty("type");
      expect(sampleEvent.message).toBeTruthy();
      // Irreversible actions MUST NOT be automatic
      expect(sampleEvent.action.type).toBe("navigation");
    });
  });

  describe("preferences key format", () => {
    it("uses correct localStorage key format", () => {
      const userId = "user-abc";
      const expectedKey = `agent:preferences:${userId}`;
      expect(expectedKey).toBe("agent:preferences:user-abc");
    });
  });
});

import { beforeEach, describe, expect, it, vi } from "vitest";

import { LLMFactory } from "@/lib/ai/factory";
import { generateInsights } from "@/lib/ai/insights/generator";
import type { InsightSection } from "@/lib/ai/insights/schemas";
import type { MaturityLevel } from "@/lib/ai/memory/organizational";

// Mock LLMFactory
vi.mock("@/lib/ai/factory", () => ({
  LLMFactory: {
    getInstance: vi.fn(() => ({
      createProviderWithFallback: vi.fn(),
    })),
  },
}));

// Mock Logger
vi.mock("@/lib/logger", () => ({
  appLogger: {
    info: vi.fn(),
    error: vi.fn(),
    warn: vi.fn(),
  },
}));

describe("Insights Generation Integration", () => {
  let mockProvider: unknown;
  let mockFactory: unknown;

  beforeEach(() => {
    vi.clearAllMocks();

    mockProvider = {
      name: "openrouter",
      generateText: vi.fn(),
    };

    mockFactory = {
      createProviderWithFallback: vi.fn().mockResolvedValue({
        provider: mockProvider,
        config: {
          provider: "openrouter",
          model: "anthropic/claude-3.5-sonnet",
          temperature: 0.7,
          maxTokens: 2000,
        },
      }),
    };

    LLMFactory.getInstance.mockReturnValue(mockFactory);
  });

  describe("successful insight generation", () => {
    it("should generate insights without maturity adaptation", async () => {
      const mockLLMResponse = {
        insights: [
          {
            type: "warning",
            title: "Low Sales Alert",
            message: "Sales are below average",
            priority: 8,
            action_label: "View Analytics",
            action_url: "/admin/analytics",
          },
          {
            type: "opportunity",
            title: "Stock Opportunity",
            message: "Consider restocking popular items",
            priority: 6,
            action_label: "View Products",
            action_url: "/admin/products",
          },
        ],
      };

      mockProvider.generateText.mockResolvedValue({
        content: JSON.stringify(mockLLMResponse),
      });

      const insights = await generateInsights({
        section: "dashboard",
        data: {
          yesterdaySales: 1000,
          monthlyAverage: 1500,
        },
        organizationName: "Test Optica",
      });

      expect(insights).toHaveLength(2);
      expect(insights[0]).toEqual({ ...mockLLMResponse.insights[0], metadata: {} });
      expect(insights[1]).toEqual({ ...mockLLMResponse.insights[1], metadata: {} });
    });

    it("should generate insights with maturity adaptation", async () => {
      const mockMaturity: MaturityLevel = {
        level: "growing",
        daysSinceCreation: 45,
        totalOrders: 30,
        totalRevenue: 50000,
        description: "Growing organization",
      };

      const mockLLMResponse = {
        insights: [
          {
            type: "opportunity",
            title: "Growth Optimization",
            message: "Your business is growing! Consider automation.",
            priority: 7,
            action_label: "Learn More",
            action_url: "/admin/settings",
          },
        ],
      };

      mockProvider.generateText.mockResolvedValue({
        content: JSON.stringify(mockLLMResponse),
      });

      const insights = await generateInsights({
        section: "dashboard",
        data: { totalOrders: 30, totalRevenue: 50000 },
        organizationName: "Growing Optica",
        organizationId: "org-123",
        maturityLevel: mockMaturity,
        useMaturityAdaptation: true,
      });

      expect(insights).toHaveLength(1);
      expect(insights[0].message).toContain("growing");

      // Verify that provider was called
      expect(mockProvider.generateText).toHaveBeenCalled();

      // Verify the system prompt includes maturity context
      const callArgs = mockProvider.generateText.mock.calls[0];
      const systemPrompt = callArgs[0][0].content;
      expect(systemPrompt).toContain("INSTRUCCIONES DE MADUREZ");
      expect(systemPrompt).toContain("CRECIMIENTO");
    });

    it("should handle JSON wrapped in markdown code blocks", async () => {
      const mockLLMResponse = {
        insights: [
          {
            type: "info",
            title: "Test Insight",
            message: "Test message",
            priority: 5,
          },
        ],
      };

      // Simulate LLM returning JSON in markdown
      mockProvider.generateText.mockResolvedValue({
        content: `Here are the insights:\n\n\`\`\`json\n${JSON.stringify(mockLLMResponse)}\n\`\`\``,
      });

      const insights = await generateInsights({
        section: "inventory",
        data: {},
        organizationName: "Test Optica",
      });

      expect(insights).toHaveLength(1);
      expect(insights[0].title).toBe("Test Insight");
    });

    it("should work for all sections", async () => {
      const sections: InsightSection[] = [
        "dashboard",
        "inventory",
        "clients",
        "pos",
        "analytics",
      ];

      const mockLLMResponse = {
        insights: [
          {
            type: "info",
            title: "Section Insight",
            message: "Test for section",
            priority: 5,
          },
        ],
      };

      mockProvider.generateText.mockResolvedValue({
        content: JSON.stringify(mockLLMResponse),
      });

      for (const section of sections) {
        const insights = await generateInsights({
          section,
          data: {},
          organizationName: "Test Optica",
        });

        expect(insights).toHaveLength(1);
        expect(mockProvider.generateText).toHaveBeenCalled();
      }
    });
  });

  describe("error handling and retries", () => {
    it("should retry on transient failures", async () => {
      const mockLLMResponse = {
        insights: [
          {
            type: "info",
            title: "Success after retry",
            message: "This worked on retry",
            priority: 5,
          },
        ],
      };

      // Fail first time, succeed second time
      mockProvider.generateText
        .mockRejectedValueOnce(new Error("Temporary network error"))
        .mockResolvedValueOnce({
          content: JSON.stringify(mockLLMResponse),
        });

      const insights = await generateInsights({
        section: "dashboard",
        data: {},
        organizationName: "Test Optica",
        maxRetries: 2,
      });

      expect(insights).toHaveLength(1);
      expect(mockProvider.generateText).toHaveBeenCalledTimes(2);
    });

    it("should throw error after max retries exceeded", async () => {
      mockProvider.generateText.mockRejectedValue(
        new Error("Persistent error"),
      );

      await expect(
        generateInsights({
          section: "dashboard",
          data: {},
          organizationName: "Test Optica",
          maxRetries: 1,
        }),
      ).rejects.toThrow("Failed to generate insights after 2 attempts");

      expect(mockProvider.generateText).toHaveBeenCalledTimes(2);
    });

    it("should not retry on validation errors", async () => {
      mockProvider.generateText.mockResolvedValue({
        content: JSON.stringify({
          insights: [
            {
              type: "invalid_type", // Invalid type
              title: "Test",
              message: "Test",
              priority: 5,
            },
          ],
        }),
      });

      await expect(
        generateInsights({
          section: "dashboard",
          data: {},
          organizationName: "Test Optica",
          maxRetries: 2,
        }),
      ).rejects.toThrow("Invalid insight format");

      // Should only try once, not retry on validation errors
      expect(mockProvider.generateText).toHaveBeenCalledTimes(1);
    });

    it("should throw error if no providers available", async () => {
      mockFactory.createProviderWithFallback.mockRejectedValue(
        new Error("No available LLM providers configured"),
      );

      await expect(
        generateInsights({
          section: "dashboard",
          data: {},
          organizationName: "Test Optica",
        }),
      ).rejects.toThrow("No available LLM providers configured");
    });
  });

  describe("insight validation", () => {
    it("should validate insight structure", async () => {
      const validInsight = {
        insights: [
          {
            type: "warning",
            title: "Valid Insight",
            message: "This is valid",
            priority: 8,
            action_label: "Action",
            action_url: "/admin/test",
            metadata: { key: "value" },
          },
        ],
      };

      mockProvider.generateText.mockResolvedValue({
        content: JSON.stringify(validInsight),
      });

      const insights = await generateInsights({
        section: "dashboard",
        data: {},
        organizationName: "Test Optica",
      });

      expect(insights[0]).toEqual(validInsight.insights[0]);
    });

    it("should reject insights with invalid priority", async () => {
      const invalidInsight = {
        insights: [
          {
            type: "warning",
            title: "Invalid",
            message: "Priority out of range",
            priority: 15, // Invalid: must be 1-10
          },
        ],
      };

      mockProvider.generateText.mockResolvedValue({
        content: JSON.stringify(invalidInsight),
      });

      await expect(
        generateInsights({
          section: "dashboard",
          data: {},
          organizationName: "Test Optica",
        }),
      ).rejects.toThrow();
    });

    it("should reject insights with missing required fields", async () => {
      const invalidInsight = {
        insights: [
          {
            type: "warning",
            // Missing title
            message: "Missing title field",
            priority: 5,
          },
        ],
      };

      mockProvider.generateText.mockResolvedValue({
        content: JSON.stringify(invalidInsight),
      });

      await expect(
        generateInsights({
          section: "dashboard",
          data: {},
          organizationName: "Test Optica",
        }),
      ).rejects.toThrow();
    });
  });

  describe("configuration and customization", () => {
    it("should respect custom temperature", async () => {
      mockProvider.generateText.mockResolvedValue({
        content: JSON.stringify({
          insights: [
            {
              type: "info",
              title: "Test",
              message: "Test",
              priority: 5,
            },
          ],
        }),
      });

      await generateInsights({
        section: "dashboard",
        data: {},
        organizationName: "Test Optica",
        temperature: 0.9,
      });

      expect(mockFactory.createProviderWithFallback).toHaveBeenCalledWith(
        undefined,
        expect.objectContaining({ temperature: 0.9 }),
      );
    });

    it("should include additional context in prompts", async () => {
      mockProvider.generateText.mockResolvedValue({
        content: JSON.stringify({
          insights: [
            {
              type: "info",
              title: "Test",
              message: "Test",
              priority: 5,
            },
          ],
        }),
      });

      await generateInsights({
        section: "dashboard",
        data: { sales: 1000 },
        organizationName: "Test Optica",
        additionalContext: {
          customField: "customValue",
          totalCustomers: 150,
        },
      });

      const callArgs = mockProvider.generateText.mock.calls[0];
      const systemPrompt = callArgs[0][0].content;

      // Additional context should be passed to prompt generation
      expect(systemPrompt).toBeTruthy();
    });
  });
});

import { describe, expect, it } from "vitest";

import { buildSystemPrompt } from "@/lib/ai/agent/prompt-builder";
import { buildSession } from "@/lib/ai/agent/session";
import { getAllTools } from "@/lib/ai/tools";

// ─── Fixtures ───

const validPayload = {
  message: "¿Cuántos clientes tengo?",
  session_id: "test-session-123",
  context: {
    route: "/admin/customers",
    section: "customers",
    branch_id: "branch-1",
    branch_name: "Sucursal Centro",
    role: "admin",
    org_id: "org-1",
  },
};

const payloadWithoutRole = {
  message: "test",
  context: {
    route: "/admin",
    org_id: "org-1",
  },
};

const payloadWithoutMessage = {
  context: {
    route: "/admin",
    role: "admin",
    org_id: "org-1",
  },
};

// ─── Session Builder Tests ───

describe("buildSession", () => {
  it("builds a valid session from complete payload", () => {
    const result = buildSession(
      validPayload as unknown as Record<string, unknown>,
    );
    if ("status" in result) {
      expect.fail("Expected AgentSession, got error: " + result.error);
    }
    expect(result.message).toBe("¿Cuántos clientes tengo?");
    expect(result.sessionId).toBe("test-session-123");
    expect(result.role).toBe("admin");
    expect(result.context.route).toBe("/admin/customers");
    expect(result.context.orgId).toBe("org-1");
  });

  it("generates session_id when not provided", () => {
    const payload = { ...validPayload, session_id: undefined };
    const result = buildSession(payload as unknown as Record<string, unknown>);
    if ("status" in result) {
      expect.fail("Expected AgentSession, got error: " + result.error);
    }
    expect(result.sessionId).toBeDefined();
    expect(result.sessionId).not.toBe("test-session-123");
  });

  it("returns 400 error when message is missing", () => {
    const result = buildSession(
      payloadWithoutMessage as unknown as Record<string, unknown>,
    );
    expect("status" in result).toBe(true);
    if ("status" in result) {
      expect(result.status).toBe(400);
      expect(result.missingFields).toContain("message");
    }
  });

  it("returns 400 error when context.role is missing", () => {
    const result = buildSession(
      payloadWithoutRole as unknown as Record<string, unknown>,
    );
    expect("status" in result).toBe(true);
    if ("status" in result) {
      expect(result.status).toBe(400);
      expect(result.missingFields).toContain("context.role");
    }
  });
});

