            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            name: "Updated Product",
            price: 25000,
          }),
        },
        userA.authToken,
        userA.sessionData,
      );

      // Should fail
      expect([403, 404]).toContain(response.status);
    });
  });

