} from "./test-setup";

// Sync check at module level — describe.skipIf evaluates eagerly
const hasSupabaseInfra = !!process.env.SUPABASE_SERVICE_ROLE_KEY;

interface PosSessionResult {
  id: string;
  branch_id: string;
  status: string;
  opening_time: string;
}

interface ProductBranchStockResult {
  id: string;
  product_id: string;
