    it("should handle low scores (< 4)", async () => {
      const insightId = "insight-789";
      const lowFeedback: InsightFeedback = { score: 2 };

      mockSupabase.eq.mockResolvedValue({ error: null });

      await expect(
        feedbackSystem.collectFeedback(insightId, lowFeedback),
