      const supabase = buildMockSupabase({
        fromSelectResolved: { data: null, error: null },
      });

      const facts = await getRecentContext(ORG_ID, supabase);
      expect(facts).toEqual([]);
    });

    it("returns formatted facts when supabase has data", async () => {
