    url: "http://localhost:3000/api/test",
    headers: new Headers(),
  } as NextRequest;

  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("should allow root user", async () => {
    const mockUser = {
      id: "root-user-id",
      email: "root@opttius.com",
    };

    const mockAdminUser = {
      role: "root",
    };

    // Mock createClient
    vi.mocked(createClient).mockResolvedValue({
      auth: {
        getUser: vi.fn().mockResolvedValue({
          data: { user: mockUser },
          error: null,
        }),
      },
    } as unknown);

    // Mock createRootAdminClient
    vi.mocked(createRootAdminClient).mockReturnValue({
      from: vi.fn().mockReturnValue({
        select: vi.fn().mockReturnValue({
          eq: vi.fn().mockReturnValue({
            single: vi.fn().mockResolvedValue({
              data: mockAdminUser,
              error: null,
            }),
          }),
        }),
      }),
    } as unknown);

    const result = await requireRoot(mockRequest);

    expect(result.userId).toBe(mockUser.id);
    expect(result.user.email).toBe(mockUser.email);
  });

  it("should allow dev user", async () => {
    const mockUser = {
      id: "dev-user-id",
      email: "dev@opttius.com",
    };

    const mockAdminUser = {
      role: "dev",
    };

    vi.mocked(createClient).mockResolvedValue({
      auth: {
        getUser: vi.fn().mockResolvedValue({
          data: { user: mockUser },
          error: null,
        }),
      },
    } as unknown);

    vi.mocked(createRootAdminClient).mockReturnValue({
      from: vi.fn().mockReturnValue({
        select: vi.fn().mockReturnValue({
          eq: vi.fn().mockReturnValue({
            single: vi.fn().mockResolvedValue({
              data: mockAdminUser,
              error: null,
            }),
          }),
        }),
      }),
    } as unknown);

    const result = await requireRoot(mockRequest);

    expect(result.userId).toBe(mockUser.id);
  });

  it("should throw AuthorizationError for non-root user", async () => {
    const mockUser = {
      id: "admin-user-id",
      email: "admin@organization.com",
    };

    const mockAdminUser = {
      role: "admin",
    };

    vi.mocked(createClient).mockResolvedValue({
      auth: {
        getUser: vi.fn().mockResolvedValue({
          data: { user: mockUser },
          error: null,
        }),
      },
    } as unknown);

    vi.mocked(createRootAdminClient).mockReturnValue({
      from: vi.fn().mockReturnValue({
        select: vi.fn().mockReturnValue({
          eq: vi.fn().mockReturnValue({
            single: vi.fn().mockResolvedValue({
              data: mockAdminUser,
              error: null,
            }),
          }),
        }),
      }),
    } as unknown);

    await expect(requireRoot(mockRequest)).rejects.toThrow(AuthorizationError);
    await expect(requireRoot(mockRequest)).rejects.toThrow(
      "Root access required",
    );
  });

  it("should throw AuthorizationError for unauthenticated user", async () => {
    vi.mocked(createClient).mockResolvedValue({
      auth: {
        getUser: vi.fn().mockResolvedValue({
          data: { user: null },
          error: new Error("Not authenticated"),
        }),
      },
    } as unknown);

    await expect(requireRoot(mockRequest)).rejects.toThrow(AuthorizationError);
    await expect(requireRoot(mockRequest)).rejects.toThrow("Unauthorized");
  });

  it("should throw AuthorizationError when admin user not found", async () => {
    const mockUser = {
      id: "user-id",
      email: "user@example.com",
    };

    vi.mocked(createClient).mockResolvedValue({
      auth: {
        getUser: vi.fn().mockResolvedValue({
          data: { user: mockUser },
          error: null,
        }),
      },
    } as unknown);

    vi.mocked(createRootAdminClient).mockReturnValue({
      from: vi.fn().mockReturnValue({
        select: vi.fn().mockReturnValue({
          eq: vi.fn().mockReturnValue({
            single: vi.fn().mockResolvedValue({
              data: null,
              error: new Error("Not found"),
            }),
          }),
        }),
      }),
    } as unknown);

    await expect(requireRoot(mockRequest)).rejects.toThrow(AuthorizationError);
  });
});

