/**
 * Unit tests for logger index.
 *
 * Tests appLogger wrapper methods: debug, info, warn, error.
 * Mocks pino to verify the underlying pino instance calls.
 */

import { beforeEach,describe, expect, it, vi } from "vitest";

interface MockPinoInstance {
  debug: ReturnType<typeof vi.fn>;
  info: ReturnType<typeof vi.fn>;
  warn: ReturnType<typeof vi.fn>;
  error: ReturnType<typeof vi.fn>;
}

const mockPinoInstance = vi.hoisted((): MockPinoInstance => ({
  debug: vi.fn(),
  info: vi.fn(),
  warn: vi.fn(),
  error: vi.fn(),
}));

vi.mock("pino", () => {
  const mockPino = vi.fn(() => mockPinoInstance);
  mockPino.stdTimeFunctions = { isoTime: "isoTime" };
  return { default: mockPino };
});

import { appLogger } from "@/lib/logger";

describe("appLogger", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe("debug", () => {
    it("calls pino.debug with message when no data", () => {
      appLogger.debug("debug message");
      expect(mockPinoInstance.debug).toHaveBeenCalledWith("debug message");
    });

    it("calls pino.debug with data then message when data provided", () => {
      appLogger.debug("debug message", { key: "value" });
      expect(mockPinoInstance.debug).toHaveBeenCalledWith(
        { key: "value" },
        "debug message",
      );
    });
  });

  describe("info", () => {
    it("calls pino.info with message when no data", () => {
      appLogger.info("info message");
      expect(mockPinoInstance.info).toHaveBeenCalledWith("info message");
    });

    it("calls pino.info with data then message when data provided", () => {
      appLogger.info("info message", { count: 42 });
      expect(mockPinoInstance.info).toHaveBeenCalledWith(
        { count: 42 },
        "info message",
      );
    });
  });

  describe("warn", () => {
    it("calls pino.warn with message when no data", () => {
      appLogger.warn("warn message");
      expect(mockPinoInstance.warn).toHaveBeenCalledWith("warn message");
    });

    it("calls pino.warn with data then message when data provided", () => {
      appLogger.warn("warn message", { threshold: "low" });
      expect(mockPinoInstance.warn).toHaveBeenCalledWith(
        { threshold: "low" },
        "warn message",
      );
    });
  });

  describe("error", () => {
    it("calls pino.error with message when message only", () => {
      appLogger.error("error message");
      expect(mockPinoInstance.error).toHaveBeenCalledWith("error message");
    });

    it("calls pino.error with structured err object when second arg is Error", () => {
      const err = new Error("something broke");
      appLogger.error("error message", err);
      expect(mockPinoInstance.error).toHaveBeenCalledWith(
        expect.objectContaining({
          err: expect.objectContaining({ message: "something broke" }),
        }),
        "error message",
      );
    });

    it("calls pino.error with merged data when Error and third arg provided", () => {
      const err = new Error("db failure");
      appLogger.error("error message", err, { context: "users" });
      expect(mockPinoInstance.error).toHaveBeenCalledWith(
        expect.objectContaining({
          err: expect.objectContaining({ message: "db failure" }),
          context: "users",
        }),
        "error message",
      );
    });

    it("calls pino.error with message when non-Error second arg with no third arg", () => {
      appLogger.error("error message", { key: "value" });
      expect(mockPinoInstance.error).toHaveBeenCalledWith("error message");
    });

    it("calls pino.error with third arg as data when second arg is not Error", () => {
      appLogger.error("error message", "some-string", { extra: true });
      expect(mockPinoInstance.error).toHaveBeenCalledWith(
        { extra: true },
        "error message",
      );
    });
  });
});

/**
 * Unit tests for enhanced-error-handler middleware
 *
 * Tests withEnhancedErrorHandling, withEnhancedValidation,
 * RateLimitError, and TimeoutError.
 *
 * @module __tests__/unit/lib/middleware/enhanced-error-handler.test
 */

import { NextRequest, NextResponse } from "next/server";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { z } from "zod";

// --- Mocks ---

vi.mock("@/lib/logger", () => ({
  appLogger: {
    error: vi.fn(),
    warn: vi.fn(),
    debug: vi.fn(),
    info: vi.fn(),
  },
}));

vi.mock("@/lib/error-reporting", () => ({
  reportApiError: vi.fn().mockResolvedValue(undefined),
}));

vi.mock("@/lib/errors/comprehensive-handler", () => ({
  ApplicationError: class AppError extends Error {
    code: string;
    statusCode: number;
    isOperational: boolean;
    details?: Record<string, unknown>;

    constructor(
      message: string,
      opts: {
        code: string;
        statusCode?: number;
        details?: Record<string, unknown>;
      },
    ) {
      super(message);
      this.name = this.constructor.name;
      this.code = opts.code;
      this.statusCode = opts.statusCode ?? 500;
      this.isOperational = true;
      this.details = opts.details;
    }
  },
  AuthenticationError: class AuthError extends Error {
    code = "AUTHENTICATION_ERROR";
    statusCode = 401;
    constructor(message = "Authentication required") {
      super(message);
      this.name = "AuthenticationError";
    }
  },
  AuthorizationError: class AuthzError extends Error {
    code = "AUTHORIZATION_ERROR";
    statusCode = 403;
    constructor(message = "Insufficient permissions") {
      super(message);
      this.name = "AuthorizationError";
    }
  },
  ValidationError: class ValError extends Error {
    code = "VALIDATION_ERROR";
    statusCode = 400;
    details?: Record<string, unknown>;
    constructor(message: string, details?: Record<string, unknown>) {
      super(message);
      this.name = "ValidationError";
      this.details = details;
    }
  },
  generateRequestId: vi.fn(() => "fixed-req-id"),
  handleApiError: vi.fn(),
}));

// --- Imports (after mocks) ---

import { reportApiError } from "@/lib/error-reporting";
import {
  handleApiError,
} from "@/lib/errors/comprehensive-handler";
import {
  RateLimitError,
  TimeoutError,
  withEnhancedErrorHandling,
  withEnhancedValidation,
} from "@/lib/middleware/enhanced-error-handler";

// --- Helpers ---

function makeRequest(overrides: Partial<NextRequest> = {}): NextRequest {
  return {
    url: "http://localhost:3000/api/test",
    headers: new Headers(),
    method: "GET",
    json: vi.fn(),
    ...overrides,
  } as unknown as NextRequest;
}

beforeEach(() => {
  vi.clearAllMocks();
});

// ---------------------------------------------------------------------------
// withEnhancedErrorHandling
// ---------------------------------------------------------------------------
describe("withEnhancedErrorHandling", () => {
  it("should return handler response on success", async () => {
    const handler = vi.fn().mockResolvedValue(NextResponse.json({ ok: true }));
    const wrapped = withEnhancedErrorHandling(handler);
    const request = makeRequest();

    const response = await wrapped(request);

    expect(response.status).toBe(200);
    const body = await response.json();
    expect(body).toEqual({ ok: true });
  });

  it("should add X-Request-ID header on success", async () => {
    const handler = vi.fn().mockResolvedValue(NextResponse.json({ ok: true }));
    const wrapped = withEnhancedErrorHandling(handler);
    const request = makeRequest();

    const response = await wrapped(request);

    expect(response.headers.get("X-Request-ID")).toBe("fixed-req-id");
  });

  it("should report errors with status >= 500 via reportApiError", async () => {
    vi.mocked(handleApiError).mockReturnValue({
      response: {
        error: {
          code: "INTERNAL_ERROR",
          message: "server error",
          timestamp: "2024-01-01T00:00:00.000Z",
          requestId: "fixed-req-id",
        },
      },
      statusCode: 500,
    });

    const handler = vi.fn().mockRejectedValue(new Error("server error"));
    const wrapped = withEnhancedErrorHandling(handler);
    const request = makeRequest();

    await wrapped(request);

    expect(reportApiError).toHaveBeenCalledOnce();
    expect(reportApiError).toHaveBeenCalledWith(
      expect.any(Error),
      expect.objectContaining({
        requestId: "fixed-req-id",
        endpoint: request.url,
        method: "GET",
        statusCode: 500,
      }),
    );
  });

  it("should NOT report client errors (4xx) by default", async () => {
    vi.mocked(handleApiError).mockReturnValue({
      response: {
        error: {
          code: "VALIDATION_ERROR",
          message: "bad request",
          timestamp: "2024-01-01T00:00:00.000Z",
          requestId: "fixed-req-id",
        },
      },
      statusCode: 400,
    });

    const handler = vi.fn().mockRejectedValue(new Error("bad request"));
    const wrapped = withEnhancedErrorHandling(handler);
    const request = makeRequest();

    await wrapped(request);

    expect(reportApiError).not.toHaveBeenCalled();
  });

  it("should respect custom reportThreshold", async () => {
    vi.mocked(handleApiError).mockReturnValue({
      response: {
        error: {
          code: "NOT_FOUND",
          message: "not found",
          timestamp: "2024-01-01T00:00:00.000Z",
          requestId: "fixed-req-id",
        },
      },
      statusCode: 404,
    });

    const handler = vi.fn().mockRejectedValue(new Error("not found"));
    const wrapped = withEnhancedErrorHandling(handler, {
      reportThreshold: 400,
    });
    const request = makeRequest();

    await wrapped(request);

    expect(reportApiError).toHaveBeenCalledOnce();
  });

  it("should handle AuthenticationError on missing auth header", async () => {
    vi.mocked(handleApiError).mockReturnValue({
      response: {
        error: {
          code: "AUTHENTICATION_ERROR",
          message: "Missing or invalid authorization header",
          timestamp: "2024-01-01T00:00:00.000Z",
          requestId: "fixed-req-id",
        },
      },
      statusCode: 401,
    });

    const handler = vi.fn();
    const wrapped = withEnhancedErrorHandling(handler, {
      requireAuth: true,
    });
    const request = makeRequest(); // No auth header

    const response = await wrapped(request);

    expect(response.status).toBe(401);
    expect(handler).not.toHaveBeenCalled();
  });

  it("should disable reporting when enableReporting is false", async () => {
    vi.mocked(handleApiError).mockReturnValue({
      response: {
        error: {
          code: "INTERNAL_ERROR",
          message: "server error",
          timestamp: "2024-01-01T00:00:00.000Z",
          requestId: "fixed-req-id",
        },
      },
      statusCode: 500,
    });

    const handler = vi.fn().mockRejectedValue(new Error("server error"));
    const wrapped = withEnhancedErrorHandling(handler, {
      enableReporting: false,
    });
    const request = makeRequest();

    await wrapped(request);

    expect(reportApiError).not.toHaveBeenCalled();
  });
});

// ---------------------------------------------------------------------------
// withEnhancedValidation
// ---------------------------------------------------------------------------
describe("withEnhancedValidation", () => {
  it("should validate and call handler on valid data", async () => {
    const schema = z.object({ name: z.string(), age: z.number() });
    const innerHandler = vi
      .fn()
      .mockResolvedValue(NextResponse.json({ ok: true }));
    const wrapped = withEnhancedValidation(schema, innerHandler);

    const request = makeRequest({
      method: "POST",
      json: vi.fn().mockResolvedValue({ name: "John", age: 30 }),
    });

    const response = await wrapped(request);

    expect(response.status).toBe(200);
    expect(innerHandler).toHaveBeenCalledWith(
      { name: "John", age: 30 },
      request,
      { requestId: "fixed-req-id" },
    );
  });

  it("should throw ValidationError on Zod parse failure", async () => {
    vi.mocked(handleApiError).mockReturnValue({
      response: {
        error: {
          code: "VALIDATION_ERROR",
          message: "Invalid request data",
          timestamp: "2024-01-01T00:00:00.000Z",
          requestId: "fixed-req-id",
        },
      },
      statusCode: 400,
    });

    const schema = z.object({ name: z.string() });
    const innerHandler = vi.fn();
    const wrapped = withEnhancedValidation(schema, innerHandler);

    const request = makeRequest({
      method: "POST",
      json: vi.fn().mockResolvedValue({ name: 123 }),
    });

    const response = await wrapped(request);

    expect(response.status).toBe(400);
    expect(innerHandler).not.toHaveBeenCalled();
  });

  it("should not report validation errors", async () => {
    vi.mocked(handleApiError).mockReturnValue({
      response: {
        error: {
          code: "VALIDATION_ERROR",
          message: "Invalid request data",
          timestamp: "2024-01-01T00:00:00.000Z",
          requestId: "fixed-req-id",
        },
      },
      statusCode: 400,
    });

    const schema = z.object({ name: z.string() });
    const wrapped = withEnhancedValidation(schema, vi.fn());

    const request = makeRequest({
      method: "POST",
      json: vi.fn().mockResolvedValue({ name: 123 }),
    });

    await wrapped(request);

    // Validation errors have enableReporting forced to false by default
    expect(reportApiError).not.toHaveBeenCalled();
  });
});

