      chain.single.mockResolvedValueOnce({ data: null, error: null });

      await expect(
        service.updatePaymentStatus("pay-001", "refunded"),
      ).rejects.toThrow("Payment update returned null");
    });
  });

  // -----------------------------------------------------------------------
  // getPaymentById
  // -----------------------------------------------------------------------
  describe("getPaymentById", () => {
    it("returns a payment when found", async () => {
      chain.single.mockResolvedValueOnce({ data: mockPayment, error: null });

      const result = await service.getPaymentById("pay-001");

      expect(result).not.toBeNull();
      expect(result!.id).toBe("pay-001");
    });

    it("returns null for PGRST116 (no rows)", async () => {
      chain.single.mockResolvedValueOnce({
        data: null,
        error: { code: "PGRST116", message: "No rows" },
      });

      const result = await service.getPaymentById("pay-999");

      expect(result).toBeNull();
    });

    it("throws on other error codes", async () => {
      chain.single.mockResolvedValueOnce({
        data: null,
        error: { code: "PGRST500", message: "internal" },
      });

      await expect(service.getPaymentById("pay-001")).rejects.toThrow(
        "Error fetching payment",
      );
    });
  });

  // -----------------------------------------------------------------------
  // getPaymentByGatewayPaymentIntentId
  // -----------------------------------------------------------------------
  describe("getPaymentByGatewayPaymentIntentId", () => {
    it("returns a payment when found", async () => {
      chain.single.mockResolvedValueOnce({ data: mockPayment, error: null });

      const result = await service.getPaymentByGatewayPaymentIntentId("pi-001");

      expect(result).not.toBeNull();
      expect(result!.id).toBe("pay-001");
      expect(chain.eq).toHaveBeenCalledWith("gateway_payment_intent_id", "pi-001");
    });

    it("returns null on PGRST116", async () => {
      chain.single.mockResolvedValueOnce({
        data: null,
        error: { code: "PGRST116", message: "No rows" },
      });

      const result = await service.getPaymentByGatewayPaymentIntentId("pi-999");

      expect(result).toBeNull();
    });
  });

  // -----------------------------------------------------------------------
  // updatePaymentFromWebhook
  // -----------------------------------------------------------------------
  describe("updatePaymentFromWebhook", () => {
    it("returns early when webhook event has no payment intent ID", async () => {
      const noIntent: WebhookEvent = {
        ...mockWebhookEvent,
        gatewayPaymentIntentId: undefined,
      };

      // The early return happens before any supabase.from() call
      // Create a fresh supabase mock to verify
      const freshMock = createMockSupabase();
      const freshService = new PaymentService(freshMock.supabase);

      await freshService.updatePaymentFromWebhook(noIntent);

      expect(freshMock.supabase.from).not.toHaveBeenCalled();
    });

    it("returns early when webhook event was already processed", async () => {
      // recordWebhookEvent finds existing processed event
      chain.single.mockResolvedValueOnce({
        data: { id: "we-001", processed: true },
        error: null,
      });

      await service.updatePaymentFromWebhook(mockWebhookEvent);

      // Should not have queried payments
      const fromCalls = chain.single.mock.calls.length;
      // Only 1 call for webhook_events select
      expect(fromCalls).toBe(1);
    });

    it("processes a new webhook event: payment succeeded, order fulfilled, org updated", async () => {
      // Sequence of .single() calls across the full flow:
      // 1. recordWebhookEvent → webhook_events select (no existing)
      chain.single.mockResolvedValueOnce({ data: null, error: null });
      // 2. getPaymentByGatewayPaymentIntentId → payments select
      chain.single.mockResolvedValueOnce({ data: mockPayment, error: null });
      // 3. updatePaymentStatus → payments update
      chain.single.mockResolvedValueOnce({
        data: { ...mockPayment, status: "succeeded" },
        error: null,
      });
      // 4. fulfillOrder → orders update
      chain.single.mockResolvedValueOnce({
        data: { id: "ord-001", status: "completed" },
        error: null,
      });
      // 5. applyPaymentSuccessToOrganization → org select (subscription_tier)
      chain.single.mockResolvedValueOnce({
        data: { subscription_tier: "basic" },
        error: null,
      });
      // 6. applyPaymentSuccessToOrganization → org select (email)
      chain.single.mockResolvedValueOnce({
        data: { name: "Test Org", owner_id: "user-001" },
        error: null,
      });
      // 7. applyPaymentSuccessToOrganization → profiles select (owner)
      chain.single.mockResolvedValueOnce({
        data: { email: "admin@test.com", first_name: "Admin" },
        error: null,
      });

      // .maybeSingle() for subscriptions select
      chain.maybeSingle.mockResolvedValueOnce({
        data: { id: "sub-001", status: "trial" },
        error: null,
      });

      // _directResult is used for insert/update calls without .single()
      // subscription_tiers query, webhook_events insert, org update,
      // subscriptions update, webhook_events markProcessed — all succeed
      chain._directResult = { data: null, error: null };

      await service.updatePaymentFromWebhook(mockWebhookEvent);

      // Order fulfilled
      expect(chain.update).toHaveBeenCalledWith(
        expect.objectContaining({ status: "completed" }),
      );

      // Organization tier updated
      expect(recordTierChange).toHaveBeenCalledWith(
        expect.objectContaining({
          organizationId: "org-001",
          toTier: "basic",
        }),
      );

      // Email notification sent
      expect(sendSaaSNotification).toHaveBeenCalledWith(
        "saas_subscription_success",
        "admin@test.com",
        expect.objectContaining({ plan_name: "BASIC" }),
      );
    });

    it("handles payment not found gracefully", async () => {
      // recordWebhookEvent: no existing event
      chain.single.mockResolvedValueOnce({ data: null, error: null });
      // getPaymentByGatewayPaymentIntentId: no payment found
      chain.single.mockResolvedValueOnce({
        data: null,
        error: { code: "PGRST116", message: "No rows" },
      });

      chain._directResult = { data: null, error: null };

      await service.updatePaymentFromWebhook(mockWebhookEvent);

      // Should not have called payment update or order fulfillment
      expect(recordTierChange).not.toHaveBeenCalled();
    });
  });

  // -----------------------------------------------------------------------
  // fulfillOrder
  // -----------------------------------------------------------------------
  describe("fulfillOrder", () => {
    it("marks order as completed", async () => {
      chain.single.mockResolvedValueOnce({
        data: { id: "ord-001", status: "completed" },
        error: null,
      });

      await service.fulfillOrder("ord-001");

      expect(chain.update).toHaveBeenCalledWith(
        expect.objectContaining({ status: "completed" }),
      );
      expect(chain.eq).toHaveBeenCalledWith("id", "ord-001");
    });

    it("throws on DB error", async () => {
      chain.single.mockResolvedValueOnce({
        data: null,
        error: { message: "orders table not found" },
      });

      await expect(service.fulfillOrder("ord-001")).rejects.toThrow(
        "Error fulfilling order",
      );
    });

    it("handles order not found gracefully", async () => {
      chain.single.mockResolvedValueOnce({ data: null, error: null });

      // Should not throw
      await expect(service.fulfillOrder("ord-999")).resolves.toBeUndefined();
    });
  });

  // -----------------------------------------------------------------------
  // applyPaymentSuccessToOrganization
  // -----------------------------------------------------------------------
  describe("applyPaymentSuccessToOrganization", () => {
    const succeededPayment: Payment = {
      ...mockPayment,
      status: "succeeded",
      gateway_transaction_id: "tx-001",
    };

    it("updates org tier from metadata, converts trial subscription, sends email", async () => {
      // 1. org select (subscription_tier)
      chain.single.mockResolvedValueOnce({
        data: { subscription_tier: "basic" },
        error: null,
      });
      // 2. org select (email info)
      chain.single.mockResolvedValueOnce({
        data: { name: "Opttius Test", owner_id: "owner-001" },
        error: null,
      });
      // 3. profiles select
      chain.single.mockResolvedValueOnce({
        data: { email: "owner@test.com", first_name: "Owner" },
        error: null,
      });

      // maybeSingle: existing subscription
      chain.maybeSingle.mockResolvedValueOnce({
        data: { id: "sub-001", status: "trial" },
        error: null,
      });

      // Tier query and direct awaits
      chain._directResult = { data: null, error: null };

      // Payment has metadata with subscription_tier
      const paymentWithMeta: Payment = {
        ...succeededPayment,
        metadata: { subscription_tier: "pro" } as Record<string, unknown>,
      };

      await service.applyPaymentSuccessToOrganization(
        "org-001",
        paymentWithMeta,
        "pi-001",
        "tx-001",
      );

      // Org updated to pro
      expect(recordTierChange).toHaveBeenCalledWith(
        expect.objectContaining({ toTier: "pro" }),
      );

      // Email sent
      expect(sendSaaSNotification).toHaveBeenCalledWith(
        "saas_subscription_success",
        "owner@test.com",
        expect.objectContaining({ plan_name: "PRO" }),
      );

      // Subscription updated (not created)
      const lastUpdateCall = chain.update.mock.calls.find(
        (c: unknown[]) =>
          typeof c[0] === "object" &&
          c[0] !== null &&
          "status" in (c[0] as Record<string, unknown>),
      );
      expect(lastUpdateCall).toBeDefined();
    });

    it("creates new subscription when none exists", async () => {
      // 1. org select (subscription_tier)
      chain.single.mockResolvedValueOnce({
        data: { subscription_tier: "basic" },
        error: null,
      });
      // 2. org select (email) — no owner_id to keep test simple
      chain.single.mockResolvedValueOnce({
        data: { name: "Opttius Test", owner_id: null },
        error: null,
      });

      // maybeSingle: no existing subscription
      chain.maybeSingle.mockResolvedValueOnce({ data: null, error: null });

      chain._directResult = { data: null, error: null };

      await service.applyPaymentSuccessToOrganization(
        "org-001",
        succeededPayment,
        "pi-001",
        "tx-001",
      );

      // Tier changed
      expect(recordTierChange).toHaveBeenCalled();
      // No email (no owner)
      expect(sendSaaSNotification).not.toHaveBeenCalled();
    });

    it("handles email failure gracefully (non-blocking)", async () => {
      const sendMock = vi.mocked(sendSaaSNotification);
      sendMock.mockRejectedValueOnce(new Error("SMTP down"));

      // 1. org select (subscription_tier)
      chain.single.mockResolvedValueOnce({
        data: { subscription_tier: "basic" },
        error: null,
      });
      // 2. org select (email)
      chain.single.mockResolvedValueOnce({
        data: { name: "Test", owner_id: "owner-001" },
        error: null,
      });
      // 3. profiles select
      chain.single.mockResolvedValueOnce({
        data: { email: "o@test.com", first_name: "O" },
        error: null,
      });

      chain.maybeSingle.mockResolvedValueOnce({ data: null, error: null });
      chain._directResult = { data: null, error: null };

      // Should not throw despite email failure
      await expect(
        service.applyPaymentSuccessToOrganization(
          "org-001",
          succeededPayment,
          "pi-001",
          "tx-001",
        ),
      ).resolves.toBeUndefined();
    });
  });

  // -----------------------------------------------------------------------
  // updateSubscriptionPaymentMethod
  // -----------------------------------------------------------------------
  describe("updateSubscriptionPaymentMethod", () => {
    it("updates payment method on existing subscription", async () => {
      chain.maybeSingle.mockResolvedValueOnce({
        data: { id: "sub-001" },
        error: null,
      });

      chain._directResult = { data: null, error: null };

      await service.updateSubscriptionPaymentMethod(
        "org-001",
        "cus-001",
        "pm-001",
      );

      expect(chain.update).toHaveBeenCalledWith(
        expect.objectContaining({
          gateway_customer_id: "cus-001",
          gateway_payment_method_id: "pm-001",
        }),
      );
    });

    it("does nothing when no subscription exists", async () => {
      chain.maybeSingle.mockResolvedValueOnce({ data: null, error: null });

      await service.updateSubscriptionPaymentMethod(
        "org-999",
        "cus-999",
        "pm-999",
      );

      expect(chain.update).not.toHaveBeenCalled();
    });

    it("throws on DB error", async () => {
      chain.maybeSingle.mockResolvedValueOnce({
        data: { id: "sub-001" },
        error: null,
      });

      chain._directResult = { data: null, error: { message: "DB error" } };
      // When update is awaited and errors, it destructures { error }
      // The then handler returns _directResult which has error set
      chain.then.mockImplementationOnce(
        (onfulfilled: (v: unknown) => unknown) =>
          Promise.resolve({ data: null, error: { message: "DB error" } }).then(onfulfilled),
      );

      await expect(
        service.updateSubscriptionPaymentMethod("org-001", "cus-001", "pm-001"),
      ).rejects.toThrow("Error updating subscription payment method");
    });
  });
});

import { describe, expect, it } from "vitest";

import { getProfileErrorMessage } from "@/lib/profile/error-messages";

describe("getProfileErrorMessage", () => {
  it("returns default message for null error", () => {
    expect(getProfileErrorMessage(null)).toBe("Error al actualizar el perfil.");
  });

  it("maps 23505 to duplicate value message", () => {
    expect(
      getProfileErrorMessage({ code: "23505", message: "duplicate key" }),
    ).toBe("El valor ya existe para otro usuario.");
  });

  it("maps PGRST116 to not found message", () => {
    expect(
      getProfileErrorMessage({ code: "PGRST116", message: "not found" }),
    ).toBe("No se encontró el perfil.");
  });

  it("maps 42501 to permission message", () => {
    expect(
      getProfileErrorMessage({ code: "42501", message: "permission denied" }),
    ).toBe("No tienes permiso para realizar esta acción.");
  });

  it("maps 42P01 to config error message", () => {
    expect(
      getProfileErrorMessage({ code: "42P01", message: "undefined table" }),
    ).toBe("Error de configuración. Contacta al administrador.");
  });

  it("maps 22P02 to invalid format message", () => {
    expect(
      getProfileErrorMessage({ code: "22P02", message: "invalid input" }),
    ).toBe("Formato de datos inválido.");
  });

  it("maps 23503 to invalid reference message", () => {
    expect(
      getProfileErrorMessage({ code: "23503", message: "foreign key" }),
    ).toBe("Referencia inválida. Verifica los datos.");
  });

  it("maps 23502 to required fields message", () => {
    expect(getProfileErrorMessage({ code: "23502", message: "not null" })).toBe(
      "Faltan campos requeridos.",
    );
  });

  it("returns error.message when code is not mapped", () => {
    const customMessage = "Custom database error";
    expect(
      getProfileErrorMessage({ code: "99999", message: customMessage }),
    ).toBe(customMessage);
  });

  it("returns default message when error has no code or message", () => {
    expect(getProfileErrorMessage({})).toBe("Error al actualizar el perfil.");
  });

  it("returns error.message when code is empty string", () => {
    expect(
      getProfileErrorMessage({ code: "", message: "Something went wrong" }),
    ).toBe("Something went wrong");
  });
});

import { NextRequest } from "next/server";
import { beforeEach, describe, expect, it, vi } from "vitest";

// ----------------------------------------------------------------
// Mocks — defined before all imports so vi.mock takes effect first
// ----------------------------------------------------------------
vi.mock("@/lib/redis/client", () => ({
  getRedisClient: vi.fn(),
}));

vi.mock("@/lib/logger", () => ({
  appLogger: {
    error: vi.fn(),
    warn: vi.fn(),
    info: vi.fn(),
    debug: vi.fn(),
  },
}));

// ----------------------------------------------------------------
// Subject under test
// ----------------------------------------------------------------
import { GENERAL_RATE_LIMIT } from "@/lib/rate-limiting/config";
import { __resetRedisHealth, withRateLimit } from "@/lib/rate-limiting/index";
// Spy targets
import * as redisRateLimiterModule from "@/lib/rate-limiting/redis-rate-limiter";
import { getRedisClient } from "@/lib/redis/client";

// ----------------------------------------------------------------
// Helpers
// ----------------------------------------------------------------
function createMockRequest(headers: Record<string, string> = {}): NextRequest {
  const h = new Headers();
  for (const [k, v] of Object.entries(headers)) h.set(k, v);
  return {
    url: "http://localhost:3000/api/test",
    headers: h,
    nextUrl: { pathname: "/api/test" },
  } as unknown as NextRequest;
}

function okHandler() {
  return vi.fn().mockResolvedValue(new Response("OK", { status: 200 }));
}

function makeMockRedis() {
  return { ping: vi.fn() };
}

function makeMockLimiter(
  overrides?: Partial<{ limited: boolean; remaining: number; current: number }>,
) {
  const now = Date.now();
  return {
    isRateLimited: vi.fn().mockResolvedValue({
      limited: false,
      remaining: 99,
      resetTime: now + 60_000,
      current: 1,
      ...overrides,
    }),
  };
}

// ----------------------------------------------------------------
// Tests
// ----------------------------------------------------------------
describe("withRateLimit", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    // Force Redis health to be re-evaluated on next call
    __resetRedisHealth();
  });

  // ─── Redis available ──────────────────────────────────────────
  it("should use RedisRateLimiter when Redis ping succeeds", async () => {
    const mockRedis = makeMockRedis();
    mockRedis.ping.mockResolvedValue("PONG");
    vi.mocked(getRedisClient).mockReturnValue(mockRedis as unknown);

    const limiter = makeMockLimiter();
    const getLimiterSpy = vi
      .spyOn(redisRateLimiterModule, "getRateLimiter")
      .mockReturnValue(limiter as unknown);

    const handler = okHandler();
    const response = await withRateLimit(GENERAL_RATE_LIMIT)(
      createMockRequest(),
      handler,
    );

    expect(response.status).toBe(200);
    expect(getLimiterSpy).toHaveBeenCalledTimes(1);
    expect(limiter.isRateLimited).toHaveBeenCalledTimes(1);
  });

  // ─── Redis unavailable ────────────────────────────────────────
  it("should fall back to in-memory Map when Redis ping fails", async () => {
    const mockRedis = makeMockRedis();
    mockRedis.ping.mockRejectedValue(new Error("ECONNREFUSED"));
    vi.mocked(getRedisClient).mockReturnValue(mockRedis as unknown);

    const getLimiterSpy = vi.spyOn(redisRateLimiterModule, "getRateLimiter");

    const handler = okHandler();
    const response = await withRateLimit(GENERAL_RATE_LIMIT)(
      createMockRequest(),
      handler,
    );

    expect(response.status).toBe(200);
    // Redis path must NOT be called
    expect(getLimiterSpy).not.toHaveBeenCalled();
    // Handler must still execute
    expect(handler).toHaveBeenCalledTimes(1);
  });

  // ─── Rate limit exceeded → 429 ────────────────────────────────
  it("should return 429 when rate limit is exceeded", async () => {
    const mockRedis = makeMockRedis();
    mockRedis.ping.mockResolvedValue("PONG");
    vi.mocked(getRedisClient).mockReturnValue(mockRedis as unknown);

    const limiter = makeMockLimiter({
      limited: true,
      remaining: 0,
      current: 100,
    });
    vi.spyOn(redisRateLimiterModule, "getRateLimiter").mockReturnValue(
      limiter as unknown,
    );

    const handler = okHandler();
    const response = await withRateLimit(GENERAL_RATE_LIMIT)(
      createMockRequest(),
      handler,
    );

    expect(response.status).toBe(429);
    // Handler must NOT be called when rate limited
    expect(handler).not.toHaveBeenCalled();
  });

  // ─── Organisation-scoped key ──────────────────────────────────
  it("should use organisation ID from header as rate-limit key", async () => {
    const mockRedis = makeMockRedis();
    mockRedis.ping.mockResolvedValue("PONG");
    vi.mocked(getRedisClient).mockReturnValue(mockRedis as unknown);

    const limiter = makeMockLimiter();
    vi.spyOn(redisRateLimiterModule, "getRateLimiter").mockReturnValue(
      limiter as unknown,
    );

    const handler = okHandler();
    const request = createMockRequest({ "x-organization-id": "org-abc-123" });
    await withRateLimit(GENERAL_RATE_LIMIT)(request, handler);

    const keyArg = limiter.isRateLimited.mock.calls[0][0] as string;
    expect(keyArg).toContain("org-abc-123");
  });

  // ─── IP-based key (no org header) ─────────────────────────────
  it("should fall back to IP-based key when no organisation header", async () => {
    const mockRedis = makeMockRedis();
    mockRedis.ping.mockResolvedValue("PONG");
    vi.mocked(getRedisClient).mockReturnValue(mockRedis as unknown);

    const limiter = makeMockLimiter();
    vi.spyOn(redisRateLimiterModule, "getRateLimiter").mockReturnValue(
      limiter as unknown,
    );

    const handler = okHandler();
    const request = createMockRequest({ "x-forwarded-for": "10.0.0.42" });
    await withRateLimit(GENERAL_RATE_LIMIT)(request, handler);

    const keyArg = limiter.isRateLimited.mock.calls[0][0] as string;
    expect(keyArg).toContain("10.0.0.42");
  });

  // ─── Fail-open: Redis crashes mid-check → falls to in-memory ─
  it("should fall back to in-memory when Redis check throws mid-flight", async () => {
    const mockRedis = makeMockRedis();
    mockRedis.ping.mockResolvedValue("PONG");
    vi.mocked(getRedisClient).mockReturnValue(mockRedis as unknown);

    // Simulate Redis being available but the rate limiter itself throwing
    const limiter = makeMockLimiter();
    limiter.isRateLimited.mockRejectedValue(new Error("Redis OOM"));
    vi.spyOn(redisRateLimiterModule, "getRateLimiter").mockReturnValue(
      limiter as unknown,
    );

    const handler = okHandler();
    const response = await withRateLimit(GENERAL_RATE_LIMIT)(
      createMockRequest(),
      handler,
    );

    // Should fall through and still work
    expect(response.status).toBe(200);
    expect(handler).toHaveBeenCalledTimes(1);
  });

  // ─── In-memory fallback rate limiting ─────────────────────────
  it("should return 429 from in-memory fallback when limit reached", async () => {
    const mockRedis = makeMockRedis();
    mockRedis.ping.mockRejectedValue(new Error("ECONNREFUSED"));
    vi.mocked(getRedisClient).mockReturnValue(mockRedis as unknown);

    // Use a very low limit to force 429
    const tightConfig = { ...GENERAL_RATE_LIMIT, limit: 1 };

    const handler = okHandler();
    const request = createMockRequest();

    // First call — should pass
    const res1 = await withRateLimit(tightConfig)(request, handler);
    expect(res1.status).toBe(200);

    // Second call — should hit the limit
    const res2 = await withRateLimit(tightConfig)(request, handler);
    expect(res2.status).toBe(429);
  });
});

/**
 * Unit tests for SaaS audit log module
 *
 * Tests recordAuditLog, getAuditLogsForTarget, getRecentAuditLogs,
 * and getClientInfoFromRequest.
 */

import { beforeEach, describe, expect, it, vi } from "vitest";

vi.mock("@/utils/supabase/server", () => ({
  createServiceRoleClient: vi.fn(),
}));

vi.mock("@/lib/logger", () => ({
  appLogger: { error: vi.fn(), info: vi.fn(), warn: vi.fn() },
}));

import type { Mock } from "vitest";

import {
  getAuditLogsForTarget,
  getClientInfoFromRequest,
  getRecentAuditLogs,
  recordAuditLog,
} from "@/lib/saas/audit-log";
import { createServiceRoleClient } from "@/utils/supabase/server";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function mockFrom(returnValue: unknown) {
  const chain = {
    insert: vi.fn().mockReturnThis(),
    select: vi.fn().mockReturnThis(),
    eq: vi.fn().mockReturnThis(),
    order: vi.fn().mockReturnThis(),
    range: vi.fn().mockReturnThis(),
    limit: vi.fn().mockReturnThis(),
    maybeSingle: vi.fn().mockResolvedValue(returnValue),
    single: vi.fn().mockResolvedValue(returnValue),
  };

  // Override .select / .insert etc. to return the chain, not undefined
  chain.select.mockReturnValue(chain);
  chain.order.mockReturnValue(chain);
  chain.eq.mockReturnValue(chain);
  chain.range.mockReturnValue(chain);
  chain.limit.mockReturnValue(chain);

  return chain;
}

function setupClient(mockReturn: Record<string, Mock> | undefined) {
  const from = mockReturn ?? {};
  (createServiceRoleClient as Mock).mockReturnValue({
    from: vi.fn((_table: string) => {
      return from[_table] ?? mockChainResult({ data: null, error: null });
    }),
  });
}

function mockChainResult(res: { data: unknown; error: unknown }) {
  const chain = mockFrom(res);
  chain.insert.mockResolvedValue(res);
  // For select chains
  return chain;
}

function setupInsert(error: unknown) {
  const insert = vi.fn().mockResolvedValue({ error });
  const chain = { insert };
  (createServiceRoleClient as Mock).mockReturnValue({
    from: vi.fn(() => chain),
  });
  return { insert, chain };
}

function setupSelect(response: {
  data: unknown[];
  count: number | null;
  error: unknown;
}) {
  const chain = {
    select: vi.fn().mockReturnThis(),
    eq: vi.fn().mockReturnThis(),
    order: vi.fn().mockReturnThis(),
    range: vi.fn().mockReturnThis(),
  };
  // @ts-expect-error - chaining mock
  chain.select.mockReturnValue(chain);
  chain.eq.mockReturnValue(chain);
  chain.order.mockReturnValue(chain);
  chain.range.mockResolvedValue(response);

  (createServiceRoleClient as Mock).mockReturnValue({
    from: vi.fn(() => chain),
  });
