describe("getClientInfoFromRequest", () => {
  it("extracts ip from cf-connecting-ip header", () => {
    const req = {
      headers: new Map([
        ["cf-connecting-ip", "203.0.113.1"],
        ["user-agent", "TestAgent/1.0"],
      ]),
    } as unknown as Request;

    const info = getClientInfoFromRequest(req);
    expect(info.ipAddress).toBe("203.0.113.1");
    expect(info.userAgent).toBe("TestAgent/1.0");
  });

  it("falls back to x-forwarded-for", () => {
    const req = {
      headers: new Map([
        ["x-forwarded-for", "198.51.100.1, 10.0.0.1"],
        ["user-agent", "curl/7.68"],
      ]),
    } as unknown as Request;

    const info = getClientInfoFromRequest(req);
    expect(info.ipAddress).toBe("198.51.100.1");
  });

  it("falls back to x-real-ip", () => {
    const req = {
      headers: new Map([["x-real-ip", "192.0.2.1"]]),
    } as unknown as Request;

    const info = getClientInfoFromRequest(req);
    expect(info.ipAddress).toBe("192.0.2.1");
  });

  it("returns 'unknown' when no ip headers present", () => {
    const req = { headers: new Map() } as unknown as Request;

    const info = getClientInfoFromRequest(req);
    expect(info.ipAddress).toBe("unknown");
    expect(info.userAgent).toBe("unknown");
  });
});

/**
 * Unit tests for getSubscriptionStatus
 *
 * Tests subscription status detection for organizations:
 * active, expired, past_due, cancelled, no subscription,
 * and the special demo/root org bypass.
 */

import { beforeEach, describe, expect, it, vi } from "vitest";

vi.mock("@/utils/supabase/root-admin", () => ({
  createRootAdminClient: vi.fn(),
}));

import type { Mock } from "vitest";

import {
  getSubscriptionStatus,
  isTrialExpired,
} from "@/lib/saas/subscription-status";
import { createRootAdminClient } from "@/utils/supabase/root-admin";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const DEMO_ORG = "00000000-0000-0000-0000-000000000001";
const ROOT_ORG = "00000000-0000-0000-0000-000000000010";
const ORG_ID = "org-123";

function mockChain(opts: {
  maybeSingleResult: { data: unknown; error: unknown };
}) {
  const chain = {
    select: vi.fn().mockReturnThis(),
    eq: vi.fn().mockReturnThis(),
    in: vi.fn().mockReturnThis(),
    order: vi.fn().mockReturnThis(),
    limit: vi.fn().mockReturnThis(),
    maybeSingle: vi.fn().mockResolvedValue(opts.maybeSingleResult),
  };
  // @ts-expect-error - chaining mock
  return chain;
}

function setupMocks(
  subResult: { data: unknown; error: unknown },
  orgResult?: { data: unknown; error: unknown },
) {
  const subChain = mockChain({ maybeSingleResult: subResult });
  const orgChain = orgResult
    ? mockChain({ maybeSingleResult: orgResult })
    : undefined;

  const fromMock = vi.fn().mockReturnValueOnce(subChain);
  if (orgChain) fromMock.mockReturnValueOnce(orgChain);

  (createRootAdminClient as Mock).mockReturnValue({ from: fromMock });
}

