    });
    expect(empty.success).toBe(false);
    if (!empty.success) {
      expect(
        empty.error.issues.some((i) => i.path.includes("total_amount")),
      ).toBe(true);
    }

    const invalid = createWorkOrderSchema.safeParse({
      ...validWorkOrder,
      total_amount: "invalid",
    });
