    expect(result.success).toBe(true);
  });

  it("accepts optional lab fields and assigned_to as null or undefined", () => {
    const result = createWorkOrderSchema.safeParse({
      ...validWorkOrder,
      lab_name: null,
      lab_contact: undefined,
      lab_order_number: null,
      assigned_to: undefined,
    });
    expect(result.success).toBe(true);
  });

  it("accepts internal_notes and customer_notes at max 5000 chars", () => {
    const result = createWorkOrderSchema.safeParse({
      ...validWorkOrder,
      internal_notes: "a".repeat(5000),
      customer_notes: "a".repeat(5000),
    });
    expect(result.success).toBe(true);
  });

  it("balance_amount accepts positive number", () => {
    const result = createWorkOrderSchema.safeParse({
      ...validWorkOrder,
      balance_amount: 100000,
    });
    expect(result.success).toBe(true);
  });
});

/**
 * Unit tests for Zod validation helpers (lib/validation/zod-helpers.ts)
 *
 * Tests parseAndValidateBody and parseAndValidateQuery functions.
 *
 * @module __tests__/unit/lib/validation/zod-helpers.test
 */

import { NextRequest } from "next/server";
import { describe, expect, it, vi } from "vitest";
import { z } from "zod";

import {
  parseAndValidateBody,
  parseAndValidateQuery,
  ValidationError,
} from "@/lib/validation/zod-helpers";

vi.mock("@/lib/logger", () => ({
  logger: {
    warn: vi.fn(),
    error: vi.fn(),
    debug: vi.fn(),
    info: vi.fn(),
  },
}));

function makeRequest(overrides: Partial<NextRequest> = {}): NextRequest {
  return {
    url: "http://localhost:3000/api/test",
    headers: new Headers(),
    ...overrides,
  } as NextRequest;
}

// ---------------------------------------------------------------------------
// parseAndValidateBody
// ---------------------------------------------------------------------------
describe("parseAndValidateBody", () => {
  const schema = z.object({
    name: z.string().min(1, "Name is required"),
    email: z.string().email("Must be a valid email"),
  });

  it("should parse and return validated data when body is valid", async () => {
    const request = {
      json: vi.fn().mockResolvedValue({ name: "John", email: "john@test.com" }),
      ...makeRequest(),
    } as unknown as NextRequest;

    const data = await parseAndValidateBody(request, schema);

    expect(data).toEqual({ name: "John", email: "john@test.com" });
    expect(request.json).toHaveBeenCalledOnce();
  });

  it("should throw ValidationError when body fails schema validation", async () => {
    const request = {
      json: vi.fn().mockResolvedValue({ name: "", email: "bad" }),
      ...makeRequest(),
    } as unknown as NextRequest;

    await expect(parseAndValidateBody(request, schema)).rejects.toThrow(
      ValidationError,
    );
  });

  it("should throw ValidationError with field-level details on invalid body", async () => {
    const request = {
      json: vi.fn().mockResolvedValue({ name: "", email: "bad" }),
      ...makeRequest(),
    } as unknown as NextRequest;

    try {
      await parseAndValidateBody(request, schema);
      expect.unreachable("Should have thrown");
    } catch (error) {
      expect(error).toBeInstanceOf(ValidationError);
      const ve = error as ValidationError;
      expect(ve.details).toBeInstanceOf(Array);
      expect((ve.details as Array<{ field: string }>).length).toBeGreaterThan(0);
    }
  });

  it("should throw ValidationError on empty body when fields are required", async () => {
    const request = {
      json: vi.fn().mockResolvedValue({}),
      ...makeRequest(),
    } as unknown as NextRequest;

    await expect(parseAndValidateBody(request, schema)).rejects.toThrow(
      ValidationError,
    );
  });

  it("should throw ValidationError when body is not valid JSON", async () => {
    const request = {
      json: vi.fn().mockRejectedValue(new SyntaxError("Unexpected token")),
      ...makeRequest(),
    } as unknown as NextRequest;

    await expect(parseAndValidateBody(request, schema)).rejects.toThrow(
      ValidationError,
    );
    await expect(parseAndValidateBody(request, schema)).rejects.toThrow(
      "Invalid JSON",
    );
  });

  it("should re-throw non-SyntaxError exceptions from request.json()", async () => {
    const request = {
      json: vi.fn().mockRejectedValue(new Error("network error")),
      ...makeRequest(),
    } as unknown as NextRequest;

    await expect(parseAndValidateBody(request, schema)).rejects.toThrow(
      "network error",
    );
  });
});

// ---------------------------------------------------------------------------
// parseAndValidateQuery
// ---------------------------------------------------------------------------
describe("parseAndValidateQuery", () => {
  const paginationSchema = z.object({
    page: z.coerce.number().int().min(1),
    limit: z.coerce.number().int().min(1).max(100),
  });

  function mockRequestWithQuery(urlString: string): NextRequest {
    const url = new URL(urlString);
    const request = makeRequest() as NextRequest;
    Object.defineProperty(request, "nextUrl", {
      value: { searchParams: url.searchParams },
      configurable: true,
    });
    return request;
  }

  it("should parse and return validated query params", () => {
    const request = mockRequestWithQuery(
      "http://localhost:3000/api/test?page=2&limit=20",
    );

    const data = parseAndValidateQuery(request, paginationSchema);

    expect(data).toEqual({ page: 2, limit: 20 });
  });

  it("should throw ValidationError when query params are out of range", () => {
    const request = mockRequestWithQuery(
      "http://localhost:3000/api/test?page=0&limit=999",
    );

    expect(() => parseAndValidateQuery(request, paginationSchema)).toThrow(
      ValidationError,
    );
  });

  it("should throw ValidationError when required query params are missing", () => {
    const request = mockRequestWithQuery("http://localhost:3000/api/test");

    expect(() => parseAndValidateQuery(request, paginationSchema)).toThrow(
      ValidationError,
    );
  });

  it("should handle optional query params with defaults", () => {
    const optionalSchema = z.object({
      search: z.string().optional(),
      page: z.coerce.number().default(1),
    });

    const request = mockRequestWithQuery("http://localhost:3000/api/test");

    const data = parseAndValidateQuery(request, optionalSchema);

    expect(data).toEqual({ page: 1 });
  });

  it("should collect duplicate query params as arrays", () => {
    const request = mockRequestWithQuery(
      "http://localhost:3000/api/test?filter=a&filter=b",
    );
    const arraySchema = z.object({
      filter: z.array(z.string()).optional(),
    });

    const data = parseAndValidateQuery(request, arraySchema);

    expect(data).toEqual({ filter: ["a", "b"] });
  });
});

/**
 * Unit tests for supabase server.ts
 *
 * @module __tests__/unit/supabase/server.test
 */

import { beforeEach,describe, expect, it, vi } from "vitest";

// --- Mocks ---

const mockGetAll = vi.fn(() => []);
const mockSet = vi.fn();

vi.mock("next/headers", () => ({
  cookies: vi.fn(() => Promise.resolve({ getAll: mockGetAll, set: mockSet })),
}));

vi.mock("@supabase/ssr", () => ({
  createServerClient: vi.fn(() => ({ server: true })),
}));

vi.mock("@supabase/supabase-js", () => ({
  createClient: vi.fn(() => ({
    auth: { getUser: vi.fn() },
  })),
}));

// --- Imports ---

import { createServerClient } from "@supabase/ssr";
import { createClient as createSupabaseClient } from "@supabase/supabase-js";

import {
  createClient as createSvrClient,
  createClientFromRequest,
  createServiceRoleClient,
} from "@/utils/supabase/server";

// --- Tests ---

describe("createClient (server)", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("returns a server client when env vars are set", async () => {
    vi.stubEnv("NEXT_PUBLIC_SUPABASE_URL", "https://test.supabase.co");
    vi.stubEnv("NEXT_PUBLIC_SUPABASE_ANON_KEY", "test-anon-key");

    const client = await createSvrClient();

    expect(client).toEqual({ server: true });
    expect(createServerClient).toHaveBeenCalledWith(
      "https://test.supabase.co",
      "test-anon-key",
      expect.objectContaining({
        cookies: expect.objectContaining({
          getAll: expect.any(Function),
          setAll: expect.any(Function),
        }),
      }),
    );

    vi.unstubAllEnvs();
  });

  it("falls back to empty strings when env vars are not set", async () => {
    vi.stubEnv("NEXT_PUBLIC_SUPABASE_URL", "");
    vi.stubEnv("NEXT_PUBLIC_SUPABASE_ANON_KEY", "");
    const client = await createSvrClient();

    expect(client).toEqual({ server: true });
    expect(createServerClient).toHaveBeenCalledWith(
      "",
      "",
      expect.objectContaining({
        cookies: expect.objectContaining({
          getAll: expect.any(Function),
          setAll: expect.any(Function),
        }),
      }),
    );

    vi.unstubAllEnvs();
  });

  it("catches setAll errors from Server Components", async () => {
    vi.stubEnv("NEXT_PUBLIC_SUPABASE_URL", "https://test.supabase.co");
    vi.stubEnv("NEXT_PUBLIC_SUPABASE_ANON_KEY", "test-anon-key");

    mockSet.mockImplementation(() => {
      throw new Error("Server Component");
    });

    // Capture the cookies config passed to createServerClient
    let capturedCookiesConfig: {
      getAll: () => unknown[];
      setAll: (cookies: { name: string; value: string; options: object }[]) => void;
    } | null = null;
    (createServerClient as unknown as import("vitest").Mock).mockImplementation(
      (_url: string, _key: string, config: { cookies: typeof capturedCookiesConfig }) => {
        capturedCookiesConfig = config.cookies;
        return { server: true };
      },
    );

    await createSvrClient();

    // setAll silently catches throws from cookieStore.set()
    expect(() =>
      capturedCookiesConfig!.setAll([{ name: "test", value: "val", options: {} }]),
    ).not.toThrow();
    expect(mockSet).toHaveBeenCalledWith("test", "val", {});

    vi.unstubAllEnvs();
  });
});

describe("createClientFromRequest", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("creates client from Bearer token", async () => {
    vi.stubEnv("NEXT_PUBLIC_SUPABASE_URL", "https://test.supabase.co");
    vi.stubEnv("NEXT_PUBLIC_SUPABASE_ANON_KEY", "test-anon-key");

    const mockGetUser = vi.fn().mockResolvedValue({
      data: { user: { id: "1" } },
      error: null,
    });
    (createSupabaseClient as unknown as import("vitest").Mock).mockReturnValue({
      auth: { getUser: mockGetUser },
    });

    const request = new Request("http://localhost", {
      headers: { Authorization: "Bearer test-jwt" },
    }) as unknown as Request;

    const result = await createClientFromRequest(request);

    expect(createSupabaseClient).toHaveBeenCalledWith(
      "https://test.supabase.co",
      "test-anon-key",
      {
        global: { headers: { Authorization: "Bearer test-jwt" } },
        auth: { autoRefreshToken: false, persistSession: false },
      },
    );
    // Bearer path should NOT use createServerClient
    expect(createServerClient).not.toHaveBeenCalled();

    await result.getUser();
    expect(mockGetUser).toHaveBeenCalledWith("test-jwt");

    vi.unstubAllEnvs();
  });

  it("falls back to cookie auth when no Authorization header", async () => {
    vi.stubEnv("NEXT_PUBLIC_SUPABASE_URL", "https://test.supabase.co");
    vi.stubEnv("NEXT_PUBLIC_SUPABASE_ANON_KEY", "test-anon-key");

    const request = new Request("http://localhost") as unknown as Request;

    await createClientFromRequest(request);

    // Falls through to createClient() which uses createServerClient
    expect(createServerClient).toHaveBeenCalled();
    // Should NOT use createSupabaseClient (that's the Bearer path)
    expect(createSupabaseClient).not.toHaveBeenCalled();

    vi.unstubAllEnvs();
  });

  it("falls back to cookie auth when request is undefined", async () => {
    vi.stubEnv("NEXT_PUBLIC_SUPABASE_URL", "https://test.supabase.co");
    vi.stubEnv("NEXT_PUBLIC_SUPABASE_ANON_KEY", "test-anon-key");

    await createClientFromRequest();

    expect(createServerClient).toHaveBeenCalled();

    vi.unstubAllEnvs();
  });

  it("ignores non-Bearer Authorization header (cookie fallback)", async () => {
    vi.stubEnv("NEXT_PUBLIC_SUPABASE_URL", "https://test.supabase.co");
    vi.stubEnv("NEXT_PUBLIC_SUPABASE_ANON_KEY", "test-anon-key");

    const request = new Request("http://localhost", {
      headers: { Authorization: "Basic base64stuff" },
    }) as unknown as Request;

    await createClientFromRequest(request);

    expect(createServerClient).toHaveBeenCalled();
    expect(createSupabaseClient).not.toHaveBeenCalled();

    vi.unstubAllEnvs();
  });

  it("getUser in cookie fallback path works", async () => {
    vi.stubEnv("NEXT_PUBLIC_SUPABASE_URL", "https://test.supabase.co");
    vi.stubEnv("NEXT_PUBLIC_SUPABASE_ANON_KEY", "test-anon-key");

    const mockGetUser = vi.fn().mockResolvedValue({
      data: { user: { id: "1" } },
      error: null,
    });
    (createServerClient as unknown as import("vitest").Mock).mockReturnValue({
      auth: { getUser: mockGetUser },
    });

    const result = await createClientFromRequest();

