                  <div className="font-medium text-sm capitalize mb-2 text-epoch-primary">
                    {resource.replace("_", " ")}
                  </div>
                  <div className="flex flex-wrap gap-1">
                    {actions.map((action) => (
                      <Badge
                        className="text-[10px] sm:text-xs border-epoch-primary/20"
                        key={action}
                        variant="outline"
                      >
                        {action}
                      </Badge>
                    ))}
                  </div>
                </div>
              ),
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

