          Editar Usuario
        </h1>
        <p className="text-sm sm:text-base text-epoch-primary/80 max-w-2xl">
          Modificar información del administrador
        </p>
      </div>

      {/* Form Card */}
      <Card className="rounded-xl border border-border">
        <CardHeader className="p-4 sm:p-6 pb-0">
          <CardTitle className="flex items-center gap-2 font-display text-epoch-primary text-base sm:text-lg">
            <Crown className="h-4 w-4 sm:h-5 sm:w-5 shrink-0" />
            <span className="truncate">{adminUser.email}</span>
          </CardTitle>
        </CardHeader>
        <CardContent className="p-4 sm:p-6 pt-4 space-y-4 sm:space-y-6">
          {/* Email (read-only) */}
          <div className="space-y-2">
            <Label
              className="text-xs sm:text-sm text-epoch-primary/80"
              htmlFor="email"
            >
              Email
            </Label>
            <Input
              disabled
              className="rounded-xl bg-epoch-background/50 border-epoch-primary/10 min-h-[44px]"
              id="email"
              type="email"
              value={adminUser.email}
            />
            <p className="text-xs sm:text-sm text-epoch-primary/70 mt-1">
              El email no puede ser modificado
            </p>
          </div>

          {/* Role (editable) */}
          <div className="space-y-2">
            <Label className="text-xs sm:text-sm text-epoch-primary/80">
              Rol
            </Label>
            <Select
              value={formData.role}
              onValueChange={(value) =>
                setFormData({ ...formData, role: value })
              }
            >
              <SelectTrigger className="rounded-xl focus:border-epoch-primary focus:ring-epoch-primary/20 min-h-[44px]">
                <SelectValue placeholder="Seleccionar rol" />
              </SelectTrigger>
              <SelectContent>
                {isSuperAdmin && (
                  <SelectItem value="super_admin">
                    <span className="flex items-center gap-2">
                      <Globe className="h-4 w-4" />
                      Super Administrador
                    </span>
                  </SelectItem>
                )}
                <SelectItem value="admin">
                  <span className="flex items-center gap-2">
                    <Crown className="h-4 w-4" />
                    Administrador
                  </span>
                </SelectItem>
                <SelectItem value="employee">
                  <span className="flex items-center gap-2">
                    <User className="h-4 w-4" />
                    Empleado
                  </span>
                </SelectItem>
                <SelectItem value="vendedor">
                  <span className="flex items-center gap-2">
                    <Building2 className="h-4 w-4" />
                    Vendedor
                  </span>
                </SelectItem>
              </SelectContent>
            </Select>
            <p className="text-xs sm:text-sm text-epoch-primary/70 mt-1">
              El rol define el nivel de acceso del usuario en la organización
            </p>
          </div>

          {/* Status */}
          <div className="space-y-2">
            <Label className="text-xs sm:text-sm text-epoch-primary/80">
              Estado
            </Label>
            <div className="flex flex-wrap items-center gap-4">
              <label className="flex items-center gap-2 cursor-pointer min-h-[44px]">
                <input
                  checked={formData.is_active}
                  className="h-4 w-4 rounded border-epoch-primary/30"
                  type="checkbox"
                  onChange={(e) =>
                    setFormData({ ...formData, is_active: e.target.checked })
                  }
                />
                <span className="text-sm text-epoch-primary">
                  {formData.is_active ? "Activo" : "Inactivo"}
                </span>
              </label>
              {formData.is_active ? (
                <Badge className="bg-epoch-primary text-white">Activo</Badge>
              ) : (
                <Badge variant="destructive">Inactivo</Badge>
              )}
            </div>
            <p className="text-xs sm:text-sm text-epoch-primary/70 mt-1">
              Los administradores inactivos no pueden acceder al panel
            </p>
          </div>

          {/* Permissions Info */}
          <div className="space-y-2">
            <Label className="text-xs sm:text-sm text-epoch-primary/80">
              Permisos
            </Label>
            <div className="p-4 rounded-xl border border-epoch-primary/10 bg-epoch-background/50">
              <p className="text-xs sm:text-sm text-epoch-primary/70">
                Los permisos granulares se pueden editar desde el menú de
                acciones del usuario en el listado de administradores (Editar
                Permisos).
              </p>
            </div>
          </div>

          {/* Actions - optimizado para móvil */}
          <div className="flex flex-col-reverse sm:flex-row justify-end gap-3 pt-4 border-t border-epoch-primary/10">
            <Link
              className="w-full sm:w-auto"
              href={`/admin/admin-users/${adminId}`}
            >
              <Button
                className="w-full rounded-xl border-epoch-primary/20 min-h-[44px]"
                type="button"
                variant="outline"
              >
                <X className="mr-2 h-4 w-4" />
                Cancelar
              </Button>
            </Link>
            <Button
              className="w-full sm:w-auto rounded-xl bg-epoch-primary hover:bg-epoch-surface text-white font-display font-bold text-[10px] tracking-[0.2em] uppercase min-h-[44px]"
              disabled={saving}
              onClick={handleSave}
            >
              <Save className="mr-2 h-4 w-4" />
              {saving ? "Guardando..." : "Guardar Cambios"}
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Branch Access Manager - Admin y Super Admin pueden asignar/editar sucursal */}
      <BranchAccessManager
        adminUserId={adminId}
        canEdit={true}
        isSuperAdmin={adminUser?.role === "super_admin"}
      />
    </div>
  );
}

"use client";

import { AlertTriangle, UserPlus } from "lucide-react";
import Link from "next/link";
import { useCallback, useEffect, useState } from "react";
import { toast } from "sonner";

import PermissionsEditor from "@/components/admin/PermissionsEditor";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { useBranch } from "@/hooks/useBranch";
import { appLogger } from '@/lib/logger';

import { AdminUsersFilters } from "./AdminUsersFilters";
import { AdminUsersStats } from "./AdminUsersStats";
import { AdminUsersTable } from "./AdminUsersTable";

interface AdminUser {
  id: string;
  email: string;
  role: string;
  permissions: Record<string, string[]>;
  is_active: boolean;
  last_login?: string;
  created_at: string;
  updated_at: string;
  is_super_admin?: boolean;
  branches?: Array<{
    id: string;
    name: string;
    code: string;
    is_primary: boolean;
  }>;
  profiles?: {
    first_name?: string;
    last_name?: string;
    phone?: string;
  };
  analytics?: {
    activityCount30Days: number;
    lastActivity?: string;
    fullName?: string;
  };
}

export default function AdminUsersContent() {
  const { isSuperAdmin } = useBranch();
  const [adminUsers, setAdminUsers] = useState<AdminUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Pagination state
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage, setItemsPerPage] = useState(20);
  const [totalCount, setTotalCount] = useState(0);

  // Filters
  const [searchTerm, setSearchTerm] = useState("");
  const [roleFilter, setRoleFilter] = useState("all");
  const [statusFilter, setStatusFilter] = useState("all");

  // Debounced search for server-side filtering
  const [debouncedSearchTerm, setDebouncedSearchTerm] = useState("");

  // Permissions editor state
  const [showPermissionsEditor, setShowPermissionsEditor] = useState(false);
  const [selectedUserForPermissions, setSelectedUserForPermissions] =
    useState<AdminUser | null>(null);

  useEffect(() => {
    const timer = setTimeout(
      () => setDebouncedSearchTerm(searchTerm.trim()),
      400,
    );
    return () => clearTimeout(timer);
  }, [searchTerm]);

  useEffect(() => {
    setCurrentPage(1);
  }, [debouncedSearchTerm]);

  const fetchAdminUsers = useCallback(async () => {
    try {
      setLoading(true);
      const offset = (currentPage - 1) * itemsPerPage;
      const params = new URLSearchParams({
        limit: itemsPerPage.toString(),
        offset: offset.toString(),
        ...(roleFilter !== "all" && { role: roleFilter }),
        ...(statusFilter !== "all" && { status: statusFilter }),
        ...(debouncedSearchTerm && { search: debouncedSearchTerm }),
      });

      const response = await fetch(`/api/admin/admin-users?${params}`);
      if (!response.ok) {
        if (response.status === 403) {
          throw new Error(
            "Acceso restringido: Solo administradores pueden ver esta sección",
          );
        }
        throw new Error("Failed to fetch admin users");
      }

      const data = await response.json();
      setAdminUsers(data.adminUsers || []);
      setTotalCount(data.pagination?.total || 0);
      setError(null);
    } catch (err) {
      appLogger.error("Error fetching admin users:", err);
      setError(err instanceof Error ? err.message : "Unknown error occurred");
    } finally {
      setLoading(false);
    }
  }, [currentPage, itemsPerPage, roleFilter, statusFilter, debouncedSearchTerm]);

  useEffect(() => {
    fetchAdminUsers();
  }, [fetchAdminUsers]);

  const handleToggleStatus = async (adminId: string, currentStatus: boolean) => {
    if (!isSuperAdmin) {
      toast.error(
        "Solo los super administradores pueden activar o desactivar otros administradores",
      );
      return;
    }

    if (
      !confirm(
        `¿Estás seguro de que quieres ${!currentStatus ? "activar" : "desactivar"} a este administrador?`,
      )
    ) {
      return;
    }

    try {
      const response = await fetch(`/api/admin/admin-users/${adminId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ is_active: !currentStatus }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || "Failed to update admin user");
      }

      toast.success(`Usuario ${!currentStatus ? "activado" : "desactivado"} exitosamente`);
      fetchAdminUsers();
    } catch (error) {
      appLogger.error("Error updating admin user:", error);
      toast.error(
        error instanceof Error ? error.message : "Error al actualizar usuario",
      );
    }
  };

  const handleDeleteAdmin = async (adminId: string, adminEmail: string) => {
    if (
      !confirm(
        `¿Estás seguro de que quieres eliminar al administrador ${adminEmail}? Esta acción no se puede deshacer.`,
      )
    ) {
      return;
    }

    try {
      const response = await fetch(`/api/admin/admin-users/${adminId}`, {
        method: "DELETE",
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || "Failed to delete admin user");
      }

      toast.success("Usuario administrador eliminado exitosamente");
      fetchAdminUsers();
    } catch (error) {
      appLogger.error("Error deleting admin user:", error);
      toast.error(
        error instanceof Error ? error.message : "Error al eliminar usuario",
      );
    }
  };

  const superAdminCount = adminUsers.filter((admin) => admin.is_super_admin).length;
  const activeCount = adminUsers.filter((admin) => admin.is_active).length;
  const active30dCount = adminUsers.filter(
    (admin) => admin.analytics?.activityCount30Days && admin.analytics.activityCount30Days > 0,
  ).length;

  if (loading) {
    return (
      <div className="space-y-4 sm:space-y-6 p-4 sm:p-6 bg-epoch-background min-h-screen">
        <div className="flex flex-col gap-4">
          <h1 className="text-xl sm:text-2xl md:text-3xl font-display font-bold text-epoch-primary">
            Gestión de Administradores
          </h1>
          <p className="text-sm text-epoch-primary/80">
            Cargando usuarios administradores...
          </p>
        </div>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3 sm:gap-4">
          {[...Array(4)].map((_, i) => (
            <Card className="rounded-xl border border-border animate-pulse" key={i}>
              <CardContent className="p-4 sm:p-6">
                <div className="h-3 bg-epoch-primary/10 rounded w-3/4 mb-2" />
                <div className="h-6 bg-epoch-primary/10 rounded w-1/2" />
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="space-y-4 sm:space-y-6 p-4 sm:p-6 bg-epoch-background min-h-screen">
        <div className="flex flex-col gap-4">
          <h1 className="text-xl sm:text-2xl md:text-3xl font-display font-bold text-epoch-primary">
            Gestión de Administradores
          </h1>
          <p className="text-sm text-epoch-primary/80">
            Error al cargar los datos
          </p>
        </div>
        <Card className="rounded-xl border border-border">
          <CardContent className="text-center py-8 sm:py-16">
            <AlertTriangle className="h-10 w-10 sm:h-12 sm:w-12 text-red-500 mx-auto mb-3 sm:mb-4" />
            <h3 className="text-base sm:text-lg font-semibold text-red-700 mb-2">
              Error al cargar administradores
            </h3>
            <p className="text-sm text-epoch-primary/80 mb-4">{error}</p>
            <Button
              className="rounded-xl bg-epoch-primary hover:bg-epoch-surface text-white min-h-[44px]"
              onClick={fetchAdminUsers}
            >
              Reintentar
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="space-y-4 sm:space-y-6 p-4 sm:p-6 bg-epoch-background min-h-screen">
      {/* Header */}
      <div className="flex flex-col gap-4 sm:gap-6">
        <h1 className="text-xl sm:text-2xl md:text-3xl font-display font-bold text-epoch-primary tracking-tight">
          Gestión de Administradores
        </h1>
        <p className="text-sm sm:text-base text-epoch-primary/80 max-w-2xl">
          Administra usuarios con acceso al panel de administración
        </p>
        <div className="flex justify-start sm:justify-end">
          <Link href="/admin/admin-users/register">
            <Button className="rounded-xl bg-epoch-primary hover:bg-epoch-surface text-white font-display font-bold text-[10px] tracking-[0.2em] uppercase min-h-[44px] px-6 w-full sm:w-auto">
              <UserPlus className="h-4 w-4 mr-2 shrink-0" />
              Registrar Nuevo Usuario
            </Button>
          </Link>
        </div>
      </div>

      <AdminUsersStats
        active30dCount={active30dCount}
        activeCount={activeCount}
        superAdminCount={superAdminCount}
        total={adminUsers.length}
      />

      <AdminUsersFilters
        searchTerm={searchTerm}
        statusFilter={statusFilter}
        onSearchChange={setSearchTerm}
        onStatusChange={setStatusFilter}
      />

      <AdminUsersTable
        adminUsers={adminUsers}
        currentPage={currentPage}
        isSuperAdmin={isSuperAdmin}
        itemsPerPage={itemsPerPage}
        loading={loading}
        totalCount={totalCount}
        onDelete={handleDeleteAdmin}
        onItemsPerPageChange={setItemsPerPage}
        onPageChange={setCurrentPage}
        onPermissionsEdit={(user) => {
          setSelectedUserForPermissions(user as AdminUser);
          setShowPermissionsEditor(true);
        }}
        onToggleStatus={handleToggleStatus}
      />

      {/* Permissions Editor Dialog */}
      {showPermissionsEditor && selectedUserForPermissions && (
        <PermissionsEditor
          currentPermissions={selectedUserForPermissions.permissions || {}}
          open={showPermissionsEditor}
          userId={selectedUserForPermissions.id}
          onOpenChange={setShowPermissionsEditor}
          onSave={() => {
            fetchAdminUsers();
            setSelectedUserForPermissions(null);
          }}
        />
      )}
    </div>
  );
}

import {
  AlertTriangle,
  Building2,
  CheckCircle,
  Clock,
  Crown,
  Edit,
  Eye,
  Globe,
  MoreVertical,
  Phone,
  Shield,
  Trash2,
  User,
  Users,
} from "lucide-react";
import Link from "next/link";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Pagination } from "@/components/ui/pagination";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { formatDate, formatTimeAgo } from "@/lib/utils";

interface AdminUser {
  id: string;
  email: string;
  role: string;
  permissions: Record<string, string[]>;
  is_active: boolean;
  last_login?: string;
  created_at: string;
  is_super_admin?: boolean;
  branches?: Array<{
    id: string;
    name: string;
    code: string;
    is_primary: boolean;
  }>;
  profiles?: {
    first_name?: string;
    last_name?: string;
    phone?: string;
  };
  analytics?: {
    activityCount30Days: number;
    lastActivity?: string;
    fullName?: string;
  };
}

interface AdminUsersTableProps {
  adminUsers: AdminUser[];
  loading: boolean;
  totalCount: number;
  currentPage: number;
  itemsPerPage: number;
  isSuperAdmin: boolean;
  onPageChange: (page: number) => void;
  onItemsPerPageChange: (items: number) => void;
  onToggleStatus: (id: string, currentStatus: boolean) => void;
  onDelete: (id: string, email: string) => void;
  onPermissionsEdit: (user: AdminUser) => void;
}

function getRoleBadge(admin: AdminUser) {
  if (admin.is_super_admin || admin.role === "super_admin") {
    return (
      <Badge className="flex items-center gap-1 bg-epoch-accent text-epoch-primary" variant="default">
        <Globe className="h-3 w-3" />
        Super Administrador
      </Badge>
    );
  }
  if (admin.role === "vendedor") {
    return (
      <Badge className="flex items-center gap-1" variant="secondary">
        <User className="h-3 w-3" />
        Vendedor
      </Badge>
    );
  }
  if (admin.role === "employee") {
    return (
      <Badge className="flex items-center gap-1" variant="secondary">
        <User className="h-3 w-3" />
        Empleado
      </Badge>
    );
  }
  return (
    <Badge className="flex items-center gap-1" variant="default">
      <Crown className="h-3 w-3" />
      Administrador
    </Badge>
  );
}

function getStatusBadge(isActive: boolean) {
  return <Badge variant={isActive ? "default" : "outline"}>{isActive ? "Activo" : "Inactivo"}</Badge>;
}

function formatLastActivity(dateString?: string) {
  if (!dateString) return "Nunca";
  return formatTimeAgo(dateString, "es-AR");
}

export function AdminUsersTable({
  adminUsers,
  loading,
  totalCount,
  currentPage,
  itemsPerPage,
  isSuperAdmin,
  onPageChange,
  onItemsPerPageChange,
  onToggleStatus,
  onDelete,
  onPermissionsEdit,
}: AdminUsersTableProps) {
  return (
    <Card className="rounded-xl border border-border">
      <CardHeader className="p-4 sm:p-6 pb-0">
        <CardTitle className="flex items-center gap-2 font-display text-epoch-primary text-base sm:text-lg">
          <Users className="h-4 w-4 sm:h-5 sm:w-5 shrink-0" />
          Usuarios Administradores ({totalCount})
        </CardTitle>
      </CardHeader>
      <CardContent className="p-4 sm:p-6 pt-4">
        <div className="overflow-x-auto -mx-4 px-4 md:mx-0 md:px-0">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Usuario</TableHead>
                <TableHead>Rol</TableHead>
                <TableHead>Sucursal</TableHead>
                <TableHead>Estado</TableHead>
                <TableHead>Última Actividad</TableHead>
                <TableHead>Actividad (30d)</TableHead>
                <TableHead>Fecha Registro</TableHead>
                <TableHead>Acciones</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {adminUsers.map((admin) => (
                <TableRow className="hover:bg-[#AE000025] transition-colors" key={admin.id}>
                  <TableCell>
                    <div>
                      <div className="font-medium text-epoch-primary text-sm">
                        {admin.analytics?.fullName || "Sin nombre"}
                      </div>
                      <div className="text-xs sm:text-sm text-epoch-primary/70">
                        {admin.email}
                      </div>
                      {admin.profiles?.phone && (
                        <div className="flex items-center text-[10px] sm:text-xs text-epoch-primary/70 mt-1">
                          <Phone className="h-3 w-3 mr-1 shrink-0" />
                          {admin.profiles.phone}
                        </div>
                      )}
                    </div>
                  </TableCell>
                  <TableCell>{getRoleBadge(admin)}</TableCell>
                  <TableCell>
                    {admin.is_super_admin ? (
                      <Badge className="flex items-center gap-1 w-fit" variant="outline">
                        <Globe className="h-3 w-3" />
                        Todas las sucursales
                      </Badge>
                    ) : admin.branches && admin.branches.length > 0 ? (
                      <div className="flex flex-col gap-1">
                        {admin.branches.slice(0, 2).map((branch) => (
                          <Badge className="flex items-center gap-1 w-fit text-xs" key={branch.id} variant="outline">
                            <Building2 className="h-3 w-3" />
                            {branch.name}
                            {branch.is_primary && <span className="text-epoch-accent">★</span>}
                          </Badge>
                        ))}
                        {admin.branches.length > 2 && (
                          <span className="text-[10px] sm:text-xs text-epoch-primary/70">
                            +{admin.branches.length - 2} más
                          </span>
                        )}
                      </div>
                    ) : (
                      <span className="text-xs sm:text-sm text-epoch-primary/70">Sin sucursales</span>
                    )}
                  </TableCell>
                  <TableCell>{getStatusBadge(admin.is_active)}</TableCell>
                  <TableCell>
                    <div className="flex items-center text-xs sm:text-sm text-epoch-primary/70">
                      <Clock className="h-3 w-3 mr-1 shrink-0" />
                      {formatLastActivity(admin.last_login)}
                    </div>
                  </TableCell>
                  <TableCell>
                    <div className="text-center">
                      <div className="font-medium text-epoch-primary text-sm">
                        {admin.analytics?.activityCount30Days || 0}
                      </div>
                      <div className="text-[10px] sm:text-xs text-epoch-primary/70">acciones</div>
                    </div>
                  </TableCell>
                  <TableCell className="text-xs sm:text-sm text-epoch-primary/70">
                    {formatDate(admin.created_at, { locale: "es-AR" })}
                  </TableCell>
                  <TableCell>
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button className="h-8 w-8 p-0 min-h-[44px] min-w-[44px] sm:min-h-8 sm:min-w-8" size="sm" variant="ghost">
                          <span className="sr-only">Abrir menú</span>
                          <MoreVertical className="h-4 w-4" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end">
                        <DropdownMenuLabel>Acciones</DropdownMenuLabel>
                        <DropdownMenuSeparator />
                        <DropdownMenuItem asChild>
                          <Link className="flex items-center cursor-pointer" href={`/admin/admin-users/${admin.id}`}>
                            <Eye className="mr-2 h-4 w-4" /> Ver detalles
                          </Link>
                        </DropdownMenuItem>
                        <DropdownMenuItem asChild>
                          <Link className="flex items-center cursor-pointer" href={`/admin/admin-users/${admin.id}/edit`}>
                            <Edit className="mr-2 h-4 w-4" /> Editar
                          </Link>
                        </DropdownMenuItem>
                        <DropdownMenuItem className="flex items-center cursor-pointer" onClick={() => onPermissionsEdit(admin)}>
                          <Shield className="mr-2 h-4 w-4" /> Editar Permisos
                        </DropdownMenuItem>
                        <DropdownMenuSeparator />
                        {isSuperAdmin && (
                          <DropdownMenuItem className="flex items-center cursor-pointer" onClick={() => onToggleStatus(admin.id, admin.is_active)}>
                            {admin.is_active ? (
                              <><AlertTriangle className="mr-2 h-4 w-4 text-red-500" /> Desactivar</>
                            ) : (
                              <><CheckCircle className="mr-2 h-4 w-4 text-green-500" /> Activar</>
                            )}
                          </DropdownMenuItem>
                        )}
                        <DropdownMenuSeparator />
                        <DropdownMenuItem className="flex items-center cursor-pointer text-red-500 focus:text-red-500" onClick={() => onDelete(admin.id, admin.email)}>
                          <Trash2 className="mr-2 h-4 w-4" /> Eliminar
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>

        {!loading && adminUsers.length > 0 && (
          <div className="mt-4">
            <Pagination
              currentPage={currentPage}
              itemsPerPage={itemsPerPage}
              itemsPerPageOptions={[10, 20, 50, 100]}
              totalItems={totalCount}
              totalPages={Math.ceil(totalCount / itemsPerPage)}
              onItemsPerPageChange={onItemsPerPageChange}
              onPageChange={onPageChange}
            />
          </div>
        )}

        {adminUsers.length === 0 && (
          <div className="text-center py-8 sm:py-12">
            <Users className="h-10 w-10 sm:h-12 sm:w-12 text-epoch-primary/40 mx-auto mb-3 sm:mb-4" />
            <h3 className="text-base sm:text-lg font-semibold text-epoch-primary mb-2">
              No se encontraron administradores
            </h3>
            <p className="text-sm text-epoch-primary/80">
              Ajusta los filtros o crea un nuevo administrador.
            </p>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import { ArrowLeft, Eye, EyeOff, Loader2, UserPlus } from "lucide-react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useBranch } from "@/hooks/useBranch";
import { appLogger } from '@/lib/logger';

interface Branch {
  id: string;
  name: string;
  code: string;
}

export default function RegisterUserPage() {
  const router = useRouter();
  const { isSuperAdmin } = useBranch();
  const [loading, setLoading] = useState(false);
  const [loadingBranches, setLoadingBranches] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [branches, setBranches] = useState<Branch[]>([]);
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [formData, setFormData] = useState({
    email: "",
    password: "",
    confirmPassword: "",
    firstName: "",
    lastName: "",
    role: "admin",
    branch_id: "",
  });

  // Cargar sucursales disponibles
  useEffect(() => {
    const fetchBranches = async () => {
      setLoadingBranches(true);
      try {
        const response = await fetch("/api/admin/branches");
        if (response.ok) {
          const data = await response.json();
          setBranches(data.branches || []);
        }
      } catch (err) {
        appLogger.error("Error fetching branches:", err);
      } finally {
        setLoadingBranches(false);
      }
    };

    fetchBranches();
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    // Validaciones
    if (!formData.email || !formData.password) {
      setError("Email y contraseña son requeridos");
      return;
    }

    if (formData.password !== formData.confirmPassword) {
      setError("Las contraseñas no coinciden");
      return;
    }

    if (formData.password.length < 8) {
      setError("La contraseña debe tener al menos 8 caracteres");
      return;
    }

    // Validar que si el rol requiere sucursal, se haya seleccionado una
    if (
      (formData.role === "admin" ||
        formData.role === "employee" ||
        formData.role === "vendedor") &&
      !formData.branch_id &&
      branches.length > 0
    ) {
      setError("Debes seleccionar una sucursal para este rol");
      return;
    }

    setLoading(true);

    try {
      const response = await fetch("/api/admin/admin-users/register", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          email: formData.email,
          password: formData.password,
          firstName: formData.firstName,
          lastName: formData.lastName,
          role: formData.role,
          branch_id: formData.branch_id || null,
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || "Error al registrar usuario");
      }

      toast.success("Usuario registrado exitosamente");
      router.push("/admin/admin-users");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Error desconocido");
    } finally {
      setLoading(false);
    }
  };

  // Determinar roles permitidos según el usuario actual
  const getAllowedRoles = () => {
    // En una implementación completa, verificar el rol del usuario actual
    // Por ahora, asumimos que admin puede crear admin y employee
    // Super admin puede crear admin, employee, super_admin
    // Root/dev puede crear cualquier rol (se valida en el backend)
    if (isSuperAdmin) {
      return [
        { value: "admin", label: "Administrador" },
        { value: "vendedor", label: "Vendedor" },
        { value: "employee", label: "Empleado" },
        { value: "super_admin", label: "Super Administrador" },
      ];
    }
    return [
      { value: "admin", label: "Administrador" },
      { value: "vendedor", label: "Vendedor" },
      { value: "employee", label: "Empleado" },
    ];
  };

  const requiresBranch =
    formData.role === "admin" ||
    formData.role === "employee" ||
    formData.role === "vendedor";

  return (
    <div className="space-y-4 sm:space-y-6 p-4 sm:p-6 bg-epoch-background min-h-screen">
      {/* Header - reorganizado en filas */}
      <div className="flex flex-col gap-4 sm:gap-6">
        <div className="flex items-center gap-3">
          <Link href="/admin/admin-users">
            <Button
              className="rounded-xl text-epoch-primary hover:bg-epoch-primary/10 min-h-[44px] shrink-0"
              size="sm"
              variant="ghost"
            >
              <ArrowLeft className="h-4 w-4 mr-2" />
              Volver
            </Button>
          </Link>
        </div>
        <h1 className="text-xl sm:text-2xl md:text-3xl font-display font-bold text-epoch-primary tracking-tight">
          Registrar Nuevo Usuario
        </h1>
        <p className="text-sm sm:text-base text-epoch-primary/80 max-w-2xl">
          El usuario será registrado con tu organización actual
        </p>
      </div>

      <Card className="rounded-xl border border-border">
        <CardHeader className="p-4 sm:p-6 pb-0">
          <CardTitle className="font-display text-epoch-primary text-base sm:text-lg">
            Información del Usuario
          </CardTitle>
          <CardDescription className="text-xs sm:text-sm text-epoch-primary/80">
            Completa los datos para registrar un nuevo usuario en tu
            organización
          </CardDescription>
        </CardHeader>
        <CardContent className="p-4 sm:p-6 pt-4">
          <form className="space-y-4" onSubmit={handleSubmit}>
            {error && (
              <Alert variant="destructive">
                <AlertDescription className="text-sm">{error}</AlertDescription>
              </Alert>
            )}

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label
                  className="text-xs sm:text-sm text-epoch-primary/80"
                  htmlFor="firstName"
                >
                  Nombre
                </Label>
                <Input
                  className="rounded-xl focus:border-epoch-primary focus:ring-epoch-primary/20 min-h-[44px]"
                  id="firstName"
                  value={formData.firstName}
                  onChange={(e) =>
                    setFormData({ ...formData, firstName: e.target.value })
                  }
                />
              </div>
              <div className="space-y-2">
                <Label
                  className="text-xs sm:text-sm text-epoch-primary/80"
                  htmlFor="lastName"
                >
                  Apellido
                </Label>
                <Input
                  className="rounded-xl focus:border-epoch-primary focus:ring-epoch-primary/20 min-h-[44px]"
                  id="lastName"
                  value={formData.lastName}
                  onChange={(e) =>
                    setFormData({ ...formData, lastName: e.target.value })
                  }
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label
                className="text-xs sm:text-sm text-epoch-primary/80"
                htmlFor="email"
              >
                Email *
              </Label>
              <Input
                required
                className="rounded-xl focus:border-epoch-primary focus:ring-epoch-primary/20 min-h-[44px]"
                id="email"
                type="email"
                value={formData.email}
                onChange={(e) =>
                  setFormData({ ...formData, email: e.target.value })
                }
              />
            </div>

            <div className="space-y-2">
              <Label
                className="text-xs sm:text-sm text-epoch-primary/80"
                htmlFor="role"
              >
                Rol *
              </Label>
              <Select
                value={formData.role}
                onValueChange={(value) => {
                  setFormData({ ...formData, role: value, branch_id: "" });
                }}
              >
                <SelectTrigger className="rounded-xl focus:border-epoch-primary focus:ring-epoch-primary/20 min-h-[44px]">
                  <SelectValue placeholder="Seleccionar rol" />
                </SelectTrigger>
                <SelectContent>
                  {getAllowedRoles().map((roleOption) => (
                    <SelectItem key={roleOption.value} value={roleOption.value}>
                      {roleOption.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <p className="text-xs sm:text-sm text-epoch-primary/70 mt-1">
                {formData.role === "employee"
                  ? "Acceso operativo sin permisos de administración"
                  : formData.role === "vendedor"
                    ? "Acceso a ventas y citas en la sucursal asignada"
                    : formData.role === "admin"
                      ? "Acceso completo a una sucursal"
                      : formData.role === "super_admin"
                        ? "Acceso completo a todas las sucursales de la organización"
                        : ""}
              </p>
            </div>

            {requiresBranch && (
              <div className="space-y-2">
                <Label
                  className="text-xs sm:text-sm text-epoch-primary/80"
                  htmlFor="branch_id"
                >
                  Sucursal {branches.length > 0 ? "*" : ""}
                </Label>
                {loadingBranches ? (
                  <div className="flex items-center gap-2 p-2">
                    <Loader2 className="h-4 w-4 animate-spin" />
                    <span className="text-xs sm:text-sm text-epoch-primary/70">
                      Cargando sucursales...
                    </span>
                  </div>
                ) : branches.length === 0 ? (
                  <Alert>
                    <AlertDescription>
                      No hay sucursales disponibles. El usuario puede ser
                      asignado a una sucursal después de la creación.
                    </AlertDescription>
                  </Alert>
                ) : (
                  <Select
                    value={formData.branch_id}
                    onValueChange={(value) =>
                      setFormData({ ...formData, branch_id: value })
                    }
                  >
                    <SelectTrigger className="rounded-xl focus:border-epoch-primary focus:ring-epoch-primary/20 min-h-[44px]">
                      <SelectValue placeholder="Seleccionar sucursal" />
                    </SelectTrigger>
                    <SelectContent>
                      {branches.map((branch) => (
                        <SelectItem key={branch.id} value={branch.id}>
                          {branch.name} ({branch.code})
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                )}
              </div>
            )}

            <div className="space-y-2">
              <Label
                className="text-xs sm:text-sm text-epoch-primary/80"
                htmlFor="password"
              >
                Contraseña *
              </Label>
              <div className="relative">
                <Input
                  required
                  className="pr-12 rounded-xl focus:border-epoch-primary focus:ring-epoch-primary/20 min-h-[44px]"
                  id="password"
                  minLength={8}
                  type={showPassword ? "text" : "password"}
                  value={formData.password}
                  onChange={(e) =>
                    setFormData({ ...formData, password: e.target.value })
                  }
                />
                <Button
                  className="absolute right-0 top-0 h-full px-3 py-2 hover:bg-transparent min-h-[44px] min-w-[44px]"
                  size="sm"
                  type="button"
                  variant="ghost"
                  onClick={() => setShowPassword(!showPassword)}
                >
                  {showPassword ? (
                    <EyeOff className="h-4 w-4 text-epoch-primary/70" />
                  ) : (
                    <Eye className="h-4 w-4 text-epoch-primary/70" />
                  )}
                </Button>
              </div>
              <p className="text-xs sm:text-sm text-epoch-primary/70 mt-1">
                Mínimo 8 caracteres
              </p>
            </div>

            <div className="space-y-2">
              <Label
                className="text-xs sm:text-sm text-epoch-primary/80"
                htmlFor="confirmPassword"
              >
                Confirmar Contraseña *
              </Label>
              <div className="relative">
                <Input
                  required
                  className="pr-12 rounded-xl focus:border-epoch-primary focus:ring-epoch-primary/20 min-h-[44px]"
                  id="confirmPassword"
                  minLength={8}
                  type={showConfirmPassword ? "text" : "password"}
                  value={formData.confirmPassword}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      confirmPassword: e.target.value,
                    })
                  }
                />
                <Button
                  className="absolute right-0 top-0 h-full px-3 py-2 hover:bg-transparent min-h-[44px] min-w-[44px]"
                  size="sm"
                  type="button"
                  variant="ghost"
                  onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                >
                  {showConfirmPassword ? (
                    <EyeOff className="h-4 w-4 text-epoch-primary/70" />
                  ) : (
                    <Eye className="h-4 w-4 text-epoch-primary/70" />
                  )}
                </Button>
              </div>
            </div>

            <div className="flex flex-col-reverse sm:flex-row gap-3 pt-4">
              <Button
                className="rounded-xl border-epoch-primary/20 min-h-[44px] w-full sm:w-auto order-2 sm:order-1"
                type="button"
                variant="outline"
                onClick={() => router.back()}
              >
                Cancelar
              </Button>
              <Button
                className="rounded-xl bg-epoch-primary hover:bg-epoch-surface text-white font-display font-bold text-[10px] tracking-[0.2em] uppercase min-h-[44px] w-full sm:w-auto order-1 sm:order-2"
                disabled={loading}
                type="submit"
              >
                {loading ? (
                  <>
                    <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                    Registrando...
                  </>
                ) : (
                  <>
                    <UserPlus className="h-4 w-4 mr-2" />
                    Registrar Usuario
                  </>
                )}
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import {
  ArrowLeft,
  Building2,
  DollarSign,
  Download,
  FileText,
  Loader2,
  Plus,
} from "lucide-react";
import Link from "next/link";
import { useParams } from "next/navigation";
import { useEffect, useState } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import type {
  Agreement,
  AgreementCustomer,
  AgreementInstitutionalBalance,
  AgreementInstitutionalInvoice,
} from "@/lib/api/services/agreementService";
import { agreementService } from "@/lib/api/services/agreementService";
import { handleApiError } from "@/lib/api/services/errorService";
import { formatCurrency, formatDate } from "@/lib/utils";

import { AgreementAnalyticsCards } from "./_components/AgreementAnalyticsCards";
import { AgreementCustomersCard } from "./_components/AgreementCustomersCard";
import { AgreementInvoicesCard } from "./_components/AgreementInvoicesCard";

export default function AgreementDetailContent() {
  const params = useParams();
  const id = params.id as string;

  const [agreement, setAgreement] = useState<Agreement | null>(null);
  const [balances, setBalances] = useState<AgreementInstitutionalBalance[]>([]);
  const [analytics, setAnalytics] = useState<{
    total_orders: number;
    unique_customers?: number;
    total_sales: number;
    total_copago: number;
    total_institutional: number;
    pending_amount: number;
    paid_amount: number;
    collection_efficiency: number;
  } | null>(null);
  const [invoices, setInvoices] = useState<AgreementInstitutionalInvoice[]>([]);
  const [customers, setCustomers] = useState<AgreementCustomer[]>([]);
  const [customersPagination, setCustomersPagination] = useState({
    page: 1,
    total: 0,
    totalPages: 1,
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (id) {
      fetchAgreement();
      fetchBalances();
      fetchAnalytics();
      fetchInvoices();
      fetchCustomers(1);
    }
  }, [id]);

  const fetchAgreement = async () => {
    try {
      setLoading(true);
      const data = await agreementService.getAgreement(id);
      setAgreement(data);
      setError(null);
    } catch (err) {
      const e = handleApiError(err, "Convenio");
      setError(e?.message || "Error al cargar convenio");
    } finally {
      setLoading(false);
    }
  };
  const fetchBalances = async () => {
    try {
      setBalances(await agreementService.getInstitutionalBalances(id));
    } catch {
      setBalances([]);
    }
  };
  const fetchAnalytics = async () => {
    try {
      setAnalytics(await agreementService.getAgreementAnalytics(id));
    } catch {
      setAnalytics(null);
    }
  };
  const fetchInvoices = async () => {
    try {
      const { data } = await agreementService.getAgreementInvoices(id, {
        limit: 5,
      });
      setInvoices(data);
    } catch {
      setInvoices([]);
    }
  };
  const fetchCustomers = async (page = 1) => {
    try {
      const { data, pagination } = await agreementService.getAgreementCustomers(
        id,
        { page, limit: 10 },
      );
      setCustomers(data);
      setCustomersPagination({
        page: pagination.page,
        total: pagination.total,
        totalPages: pagination.totalPages,
      });
    } catch {
      setCustomers([]);
    }
  };

  const handleExportPlanilla = () =>
    window.open(`/api/admin/agreements/${id}/export-planilla`, "_blank");

  const getStatusBadge = (status: string) => {
    const config: Record<
      string,
      {
        variant: "default" | "secondary" | "destructive" | "outline";
        label: string;
      }
    > = {
      active: { variant: "default", label: "Activo" },
      suspended: { variant: "secondary", label: "Suspendido" },
      expired: { variant: "outline", label: "Expirado" },
      cancelled: { variant: "destructive", label: "Cancelado" },
    };
    const c = config[status] || { variant: "outline" as const, label: status };
    return <Badge variant={c.variant}>{c.label}</Badge>;
  };

  const getTypeLabel = (type: string) =>
    ({ empresa: "Empresa", sindicato: "Sindicato", mutual: "Mutual" })[type] ||
    type;

  const pendingTotal = balances
    .filter((b) => b.status === "pending")
    .reduce((s, b) => s + b.amount, 0);

  if (loading && !agreement)
    return (
      <div className="flex items-center justify-center py-24">
        <Loader2 className="h-12 w-12 animate-spin text-admin-accent-primary" />
      </div>
    );
  if (error || !agreement)
    return (
      <div className="space-y-6">
        <Link href="/admin/agreements">
          <Button variant="ghost">
            <ArrowLeft className="h-4 w-4 mr-2" /> Volver
          </Button>
        </Link>
        <div className="rounded-lg border border-destructive/50 bg-destructive/10 p-4 text-destructive">
          {error || "Convenio no encontrado"}
        </div>
      </div>
    );

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div className="flex items-center gap-4">
          <Link href="/admin/agreements">
            <Button size="icon" variant="ghost">
              <ArrowLeft className="h-4 w-4" />
            </Button>
          </Link>
          <div>
            <h1 className="text-2xl font-bold text-admin-text-primary">
              {agreement.name}
            </h1>
            <p className="text-sm text-admin-text-tertiary">
              {getTypeLabel(agreement.agreement_type)} •{" "}
              {agreement.institution_name}
            </p>
          </div>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" onClick={handleExportPlanilla}>
            <Download className="h-4 w-4 mr-2" />
            Export planilla
          </Button>
          <Link href={`/admin/agreements/${id}/institutional-balances`}>
            <Button variant="default">
              <DollarSign className="h-4 w-4 mr-2" />
              Cobranza pendiente
            </Button>
          </Link>
        </div>
      </div>

      <AgreementAnalyticsCards analytics={analytics} />

      <div className="grid gap-4 md:grid-cols-2">
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Building2 className="h-5 w-5" />
              Datos del convenio
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-2">
            <p>
              <span className="text-admin-text-tertiary">Razón social:</span>{" "}
              {agreement.institution_name}
            </p>
            <p>
              <span className="text-admin-text-tertiary">RUT:</span>{" "}
              {agreement.institution_rut}
            </p>
            <div className="flex items-center gap-2">
              <span className="text-admin-text-tertiary">Estado:</span>{" "}
              {getStatusBadge(agreement.status)}
            </div>
            <p>
              <span className="text-admin-text-tertiary">Vigencia:</span>{" "}
              {formatDate(agreement.valid_from)}
              {agreement.valid_until
                ? ` - ${formatDate(agreement.valid_until)}`
                : " (indefinido)"}
            </p>
            {agreement.representative_name && (
              <p>
                <span className="text-admin-text-tertiary">Contacto:</span>{" "}
                {agreement.representative_name}
                {agreement.representative_email &&
                  ` (${agreement.representative_email})`}
              </p>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <DollarSign className="h-5 w-5" />
              Cobranza pendiente
            </CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-2xl font-bold text-admin-text-primary">
              {formatCurrency(pendingTotal)}
            </p>
            <p className="text-sm text-admin-text-tertiary">
              {balances.filter((b) => b.status === "pending").length} venta(s)
              pendiente(s)
            </p>
            <Link href={`/admin/agreements/${id}/institutional-balances`}>
              <Button className="mt-2" size="sm" variant="outline">
                Ver detalle
              </Button>
            </Link>
          </CardContent>
        </Card>
      </div>

      <AgreementInvoicesCard id={id} invoices={invoices} />

      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle className="flex items-center gap-2">
              <FileText className="h-5 w-5" />
              Órdenes de compra
            </CardTitle>
            <Link href={`/admin/agreements/${id}/purchase-orders/new`}>
              <Button size="sm" variant="outline">
                <Plus className="h-4 w-4 mr-2" />
                Registrar OC
              </Button>
            </Link>
          </div>
        </CardHeader>
        <CardContent>
          {agreement.purchase_orders && agreement.purchase_orders.length > 0 ? (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Número OC</TableHead>
                  <TableHead>Estado</TableHead>
                  <TableHead>Usado</TableHead>
                  <TableHead>Máximo</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {agreement.purchase_orders.map((po) => (
                  <TableRow key={po.id}>
                    <TableCell>{po.oc_number}</TableCell>
                    <TableCell>
                      <Badge variant="outline">{po.status}</Badge>
                    </TableCell>
                    <TableCell>{formatCurrency(po.used_amount)}</TableCell>
                    <TableCell>
                      {po.max_amount
                        ? formatCurrency(po.max_amount)
                        : "Sin límite"}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          ) : (
            <p className="text-admin-text-tertiary py-4">
              No hay órdenes de compra registradas.{" "}
              <Link
                className="text-admin-accent-primary hover:underline"
                href={`/admin/agreements/${id}/purchase-orders/new`}
              >
                Registrar primera OC
              </Link>
            </p>
          )}
        </CardContent>
      </Card>

      <AgreementCustomersCard
        customers={customers}
        page={customersPagination.page}
        totalPages={customersPagination.totalPages}
        onPageChange={fetchCustomers}
      />
    </div>
  );
}

