"use client";

import { ArrowLeft, Check, DollarSign, Loader2 } from "lucide-react";
import Link from "next/link";
import { useParams } from "next/navigation";
import { useEffect, useState } from "react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  AgreementInstitutionalBalance,
  agreementService,
} from "@/lib/api/services/agreementService";
import { handleApiError } from "@/lib/api/services/errorService";
import { success } from "@/lib/api/services/notificationService";
import { formatCurrency, formatDate } from "@/lib/utils";

export default function InstitutionalBalancesPage() {
  const params = useParams();
  const agreementId = params.id as string;

  const [balances, setBalances] = useState<AgreementInstitutionalBalance[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [reconcileOpen, setReconcileOpen] = useState(false);
  const [reconciling, setReconciling] = useState(false);
  const [paymentRef, setPaymentRef] = useState("");
  const [emitInvoice, setEmitInvoice] = useState(true);

  useEffect(() => {
    if (agreementId) fetchBalances();
  }, [agreementId]);

  const fetchBalances = async () => {
    try {
      setLoading(true);
      const data = await agreementService.getInstitutionalBalances(
        agreementId,
        "pending",
      );
      setBalances(data);
      setError(null);
    } catch (err) {
      const errorObj = handleApiError(err, "Cobranza pendiente");
      setError(errorObj?.message || "Error al cargar");
    } finally {
      setLoading(false);
    }
  };

  const toggleSelect = (id: string) => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const selectAll = () => {
    if (selectedIds.size === balances.length) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(balances.map((b) => b.id)));
    }
  };

  const handleReconcile = async () => {
    if (selectedIds.size === 0) return;
    setReconciling(true);
    try {
      const result = await agreementService.reconcileBalances({
        balance_ids: Array.from(selectedIds),
        paid_at: new Date().toISOString(),
        payment_reference: paymentRef || undefined,
        emit_invoice: emitInvoice,
      });
      success(
        result.invoice
          ? `Factura ${result.invoice.folio} generada. ${result.reconciled_count} balance(s) conciliado(s)`
          : `${result.reconciled_count} balance(s) conciliado(s)`,
      );
      setReconcileOpen(false);
      setSelectedIds(new Set());
      setPaymentRef("");
      setEmitInvoice(true);
      fetchBalances();
    } catch (err) {
      handleApiError(err, "Conciliar");
    } finally {
      setReconciling(false);
    }
  };

  const pendingTotal = balances.reduce((s, b) => s + b.amount, 0);

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div className="flex items-center gap-4">
          <Link href={`/admin/agreements/${agreementId}`}>
            <Button size="icon" variant="ghost">
              <ArrowLeft className="h-4 w-4" />
            </Button>
          </Link>
          <div>
            <h1 className="text-2xl font-bold text-admin-text-primary">
              Cobranza pendiente
            </h1>
            <p className="text-sm text-admin-text-tertiary">
              Ventas institucionales por cobrar
            </p>
          </div>
        </div>
        <Button
          disabled={selectedIds.size === 0}
          onClick={() => setReconcileOpen(true)}
        >
          <Check className="h-4 w-4 mr-2" />
          Conciliar seleccionados ({selectedIds.size})
        </Button>
      </div>

      {error && (
        <div className="rounded-lg border border-destructive/50 bg-destructive/10 p-4 text-destructive">
          {error}
        </div>
      )}

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <DollarSign className="h-5 w-5" />
            Total pendiente: {formatCurrency(pendingTotal)}
          </CardTitle>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="flex justify-center py-12">
              <Loader2 className="h-12 w-12 animate-spin text-admin-accent-primary" />
            </div>
          ) : balances.length === 0 ? (
            <p className="text-admin-text-tertiary py-8 text-center">
              No hay cobranza pendiente
            </p>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>
                    <input
                      checked={
                        selectedIds.size === balances.length &&
                        balances.length > 0
                      }
                      type="checkbox"
                      onChange={selectAll}
                    />
                  </TableHead>
                  <TableHead>Orden</TableHead>
                  <TableHead>Cliente</TableHead>
                  <TableHead>Monto</TableHead>
                  <TableHead>Fecha</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {balances.map((b) => (
                  <TableRow key={b.id}>
                    <TableCell>
                      <input
                        checked={selectedIds.has(b.id)}
                        type="checkbox"
                        onChange={() => toggleSelect(b.id)}
                      />
                    </TableCell>
                    <TableCell>{b.order_number || b.order_id}</TableCell>
                    <TableCell>{b.customer_name || "-"}</TableCell>
                    <TableCell>{formatCurrency(b.amount)}</TableCell>
                    <TableCell>
                      {b.order_created_at
                        ? formatDate(b.order_created_at)
                        : "-"}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      <Dialog open={reconcileOpen} onOpenChange={setReconcileOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Conciliar cobranza</DialogTitle>
          </DialogHeader>
          <p className="text-sm text-admin-text-tertiary">
            Marcar {selectedIds.size} balance(s) como pagado(s).
          </p>
          <div>
            <label className="text-sm font-medium">Referencia de pago</label>
            <input
              className="mt-1 w-full rounded border px-3 py-2"
              placeholder="Nº transferencia, cheque, etc."
              type="text"
              value={paymentRef}
              onChange={(e) => setPaymentRef(e.target.value)}
            />
          </div>
          <div className="flex items-center gap-2">
            <input
              checked={emitInvoice}
              id="emit-invoice"
              type="checkbox"
              onChange={(e) => setEmitInvoice(e.target.checked)}
            />
            <label className="text-sm" htmlFor="emit-invoice">
              Generar factura a institución
            </label>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setReconcileOpen(false)}>
              Cancelar
            </Button>
            <Button disabled={reconciling} onClick={handleReconcile}>
              {reconciling ? (
                <Loader2 className="h-4 w-4 animate-spin mr-2" />
              ) : null}
              Confirmar
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

import { ArrowLeft, Download, Loader2 } from "lucide-react";
import Link from "next/link";
import { useParams } from "next/navigation";
import { useEffect, useState } from "react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  AgreementInstitutionalInvoice,
  agreementService,
} from "@/lib/api/services/agreementService";
import { handleApiError } from "@/lib/api/services/errorService";
import { formatCurrency, formatDate } from "@/lib/utils";

export default function AgreementInvoiceDetailPage() {
  const params = useParams();
  const agreementId = params.id as string;
  const invoiceId = params.invoiceId as string;

  const [invoice, setInvoice] = useState<
    | (AgreementInstitutionalInvoice & {
        items?: Array<{
          balance_id: string;
          amount: number;
          order_number: string;
          oc_number: string | null;
          customer_name: string | null;
          order_created_at: string | null;
          subtotal?: number;
          tax_amount?: number;
        }>;
        institution_name?: string;
        institution_rut?: string;
        payment_reference?: string | null;
        subtotal?: number;
        tax_amount?: number;
      })
    | null
  >(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (agreementId && invoiceId) fetchInvoice();
  }, [agreementId, invoiceId]);

  const fetchInvoice = async () => {
    try {
      setLoading(true);
      const data = await agreementService.getAgreementInvoice(
        agreementId,
        invoiceId,
      );
      setInvoice(data);
      setError(null);
    } catch (err) {
      const errorObj = handleApiError(err, "Factura");
      setError(errorObj?.message || "Error al cargar");
    } finally {
      setLoading(false);
    }
  };

  const pdfUrl = invoice?.pdf_url
    ? invoice.pdf_url
    : `/api/admin/agreements/${agreementId}/invoices/${invoiceId}/pdf`;

  if (loading && !invoice) {
    return (
      <div className="flex justify-center py-24">
        <Loader2 className="h-12 w-12 animate-spin text-admin-accent-primary" />
      </div>
    );
  }

  if (error || !invoice) {
    return (
      <div className="space-y-6">
        <Link href={`/admin/agreements/${agreementId}`}>
          <Button variant="ghost">
            <ArrowLeft className="h-4 w-4 mr-2" />
            Volver
          </Button>
        </Link>
        <div className="rounded-lg border border-destructive/50 bg-destructive/10 p-4 text-destructive">
          {error || "Factura no encontrada"}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div className="flex items-center gap-4">
          <Link href={`/admin/agreements/${agreementId}/invoices`}>
            <Button size="icon" variant="ghost">
              <ArrowLeft className="h-4 w-4" />
            </Button>
          </Link>
          <div>
            <h1 className="text-2xl font-bold text-admin-text-primary">
              Factura {invoice.folio}
            </h1>
            <p className="text-sm text-admin-text-tertiary">
              {invoice.institution_name} • Período {invoice.period_from} -{" "}
              {invoice.period_to}
            </p>
          </div>
        </div>
        <a href={pdfUrl} rel="noopener noreferrer" target="_blank">
          <Button>
            <Download className="h-4 w-4 mr-2" />
            Descargar PDF
          </Button>
        </a>
      </div>

      <div className="grid gap-4 md:grid-cols-2">
        <Card>
          <CardHeader>
            <CardTitle>Datos de la factura</CardTitle>
          </CardHeader>
          <CardContent className="space-y-2">
            <p>
              <span className="text-admin-text-tertiary">Folio:</span>{" "}
              {invoice.folio}
            </p>
            <p>
              <span className="text-admin-text-tertiary">Estado:</span>{" "}
              <span className="capitalize">{invoice.status}</span>
            </p>
            <p>
              <span className="text-admin-text-tertiary">Fecha emisión:</span>{" "}
              {formatDate(invoice.emitted_at ?? invoice.created_at)}
            </p>
            <p>
              <span className="text-admin-text-tertiary">Período:</span>{" "}
              {invoice.period_from} - {invoice.period_to}
            </p>
            {invoice.payment_reference && (
              <p>
                <span className="text-admin-text-tertiary">Ref. pago:</span>{" "}
                {invoice.payment_reference}
              </p>
            )}
          </CardContent>
        </Card>
        <Card>
          <CardHeader>
            <CardTitle>Cliente (Institución)</CardTitle>
          </CardHeader>
          <CardContent className="space-y-2">
            <p>
              <span className="text-admin-text-tertiary">Razón social:</span>{" "}
              {invoice.institution_name}
            </p>
            <p>
              <span className="text-admin-text-tertiary">RUT:</span>{" "}
              {invoice.institution_rut}
            </p>
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Detalle</CardTitle>
        </CardHeader>
        <CardContent>
          {invoice.items && invoice.items.length > 0 ? (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Orden</TableHead>
                  <TableHead>OC</TableHead>
                  <TableHead>Cliente</TableHead>
                  <TableHead>Monto</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {invoice.items?.map((item, idx: number) => (
                  <TableRow key={idx}>
                    <TableCell>{item.order_number}</TableCell>
                    <TableCell>{item.oc_number ?? "-"}</TableCell>
                    <TableCell>{item.customer_name ?? "-"}</TableCell>
                    <TableCell>{formatCurrency(item.amount)}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          ) : (
            <p className="text-admin-text-tertiary py-4">
              No hay items en esta factura.
            </p>
          )}
          <div className="mt-4 flex justify-end gap-4 text-right">
            <p>
              <span className="text-admin-text-tertiary">Subtotal:</span>{" "}
              {formatCurrency(Number(invoice.subtotal))}
            </p>
            <p>
              <span className="text-admin-text-tertiary">IVA:</span>{" "}
              {formatCurrency(Number(invoice.tax_amount))}
            </p>
            <p className="font-bold">
              <span className="text-admin-text-tertiary">Total:</span>{" "}
              {formatCurrency(Number(invoice.total_amount))}
            </p>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { ArrowLeft, Download, Eye, Loader2, Receipt } from "lucide-react";
import Link from "next/link";
import { useParams } from "next/navigation";
import { useEffect, useState } from "react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  AgreementInstitutionalInvoice,
  agreementService,
} from "@/lib/api/services/agreementService";
import { handleApiError } from "@/lib/api/services/errorService";
import { formatCurrency, formatDate } from "@/lib/utils";

export default function AgreementInvoicesPage() {
  const params = useParams();
  const agreementId = params.id as string;

  const [invoices, setInvoices] = useState<AgreementInstitutionalInvoice[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (agreementId) fetchInvoices();
  }, [agreementId]);

  const fetchInvoices = async () => {
    try {
      setLoading(true);
      const { data } = await agreementService.getAgreementInvoices(
        agreementId,
        { limit: 50 },
      );
      setInvoices(data);
      setError(null);
    } catch (err) {
      const errorObj = handleApiError(err, "Facturas");
      setError(errorObj?.message || "Error al cargar");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div className="flex items-center gap-4">
          <Link href={`/admin/agreements/${agreementId}`}>
            <Button size="icon" variant="ghost">
              <ArrowLeft className="h-4 w-4" />
            </Button>
          </Link>
          <div>
            <h1 className="text-2xl font-bold text-admin-text-primary">
              Facturas a institución
            </h1>
            <p className="text-sm text-admin-text-tertiary">
              Facturas emitidas al convenio
            </p>
          </div>
        </div>
      </div>

      {error && (
        <div className="rounded-lg border border-destructive/50 bg-destructive/10 p-4 text-destructive">
          {error}
        </div>
      )}

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Receipt className="h-5 w-5" />
            Listado de facturas
          </CardTitle>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="flex justify-center py-12">
              <Loader2 className="h-12 w-12 animate-spin text-admin-accent-primary" />
            </div>
          ) : invoices.length === 0 ? (
            <p className="text-admin-text-tertiary py-8 text-center">
              No hay facturas emitidas
            </p>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Folio</TableHead>
                  <TableHead>Período</TableHead>
                  <TableHead>Fecha emisión</TableHead>
                  <TableHead>Monto</TableHead>
                  <TableHead>Estado</TableHead>
                  <TableHead />
                </TableRow>
              </TableHeader>
              <TableBody>
                {invoices.map((inv) => (
                  <TableRow key={inv.id}>
                    <TableCell className="font-medium">{inv.folio}</TableCell>
                    <TableCell className="text-admin-text-tertiary">
                      {inv.period_from} - {inv.period_to}
                    </TableCell>
                    <TableCell>
                      {formatDate(inv.emitted_at ?? inv.created_at)}
                    </TableCell>
                    <TableCell>{formatCurrency(inv.total_amount)}</TableCell>
                    <TableCell>
                      <span className="capitalize">{inv.status}</span>
                    </TableCell>
                    <TableCell>
                      <div className="flex gap-1">
                        <Link
                          href={`/admin/agreements/${agreementId}/invoices/${inv.id}`}
                        >
                          <Button size="sm" variant="outline">
                            <Eye className="h-4 w-4 mr-1" />
                            Ver
                          </Button>
                        </Link>
                        {inv.pdf_url && (
                          <a
                            href={inv.pdf_url}
                            rel="noopener noreferrer"
                            target="_blank"
                          >
                            <Button size="sm" variant="outline">
                              <Download className="h-4 w-4 mr-1" />
                              PDF
                            </Button>
                          </a>
                        )}
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { ArrowLeft, Loader2 } from "lucide-react";
import Link from "next/link";
import { useParams, useRouter } from "next/navigation";
import { useEffect, useState } from "react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { agreementService } from "@/lib/api/services/agreementService";
import { handleApiError } from "@/lib/api/services/errorService";
import { success } from "@/lib/api/services/notificationService";

export default function NewPurchaseOrderPage() {
  const params = useParams();
  const router = useRouter();
  const agreementId = params.id as string;

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [agreementName, setAgreementName] = useState("");

  const [ocNumber, setOcNumber] = useState("");
  const [issuedAt, setIssuedAt] = useState("");
  const [validUntil, setValidUntil] = useState("");
  const [maxAmount, setMaxAmount] = useState<number | "">("");
  const [notes, setNotes] = useState("");

  useEffect(() => {
    agreementService
      .getAgreement(agreementId)
      .then((a) => setAgreementName(a.name))
      .catch(() => {});
  }, [agreementId]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setLoading(true);

    try {
      await agreementService.createPurchaseOrder(agreementId, {
        oc_number: ocNumber,
        issued_at: issuedAt || undefined,
        valid_until: validUntil || undefined,
        max_amount: maxAmount !== "" ? maxAmount : undefined,
        notes: notes || undefined,
      });

      success("Orden de compra registrada");
      router.push(`/admin/agreements/${agreementId}`);
    } catch (err) {
      const errorObj = handleApiError(err, "Registrar OC");
      setError(errorObj?.message || "Error al registrar orden de compra");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Link href={`/admin/agreements/${agreementId}`}>
          <Button size="icon" variant="ghost">
            <ArrowLeft className="h-4 w-4" />
          </Button>
        </Link>
        <div>
          <h1 className="text-2xl font-bold text-admin-text-primary">
            Registrar orden de compra
          </h1>
          <p className="text-sm text-admin-text-tertiary">
            {agreementName || "Convenio"}
          </p>
        </div>
      </div>

      {error && (
        <div className="rounded-lg border border-destructive/50 bg-destructive/10 p-4 text-destructive">
          {error}
        </div>
      )}

      <form onSubmit={handleSubmit}>
        <Card>
          <CardHeader>
            <CardTitle>Datos de la OC</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div>
              <Label htmlFor="ocNumber">Número de OC *</Label>
              <Input
                required
                id="ocNumber"
                placeholder="OC-2025-001234"
                value={ocNumber}
                onChange={(e) => setOcNumber(e.target.value)}
              />
            </div>
            <div className="grid gap-4 sm:grid-cols-2">
              <div>
                <Label htmlFor="issuedAt">Fecha emisión</Label>
                <Input
                  id="issuedAt"
                  type="date"
                  value={issuedAt}
                  onChange={(e) => setIssuedAt(e.target.value)}
                />
              </div>
              <div>
                <Label htmlFor="validUntil">Vigencia hasta</Label>
                <Input
                  id="validUntil"
                  type="date"
                  value={validUntil}
                  onChange={(e) => setValidUntil(e.target.value)}
                />
              </div>
            </div>
            <div>
              <Label htmlFor="maxAmount">Monto máximo (opcional)</Label>
              <Input
                id="maxAmount"
                min={0}
                placeholder="Sin límite"
                type="number"
                value={maxAmount}
                onChange={(e) =>
                  setMaxAmount(
                    e.target.value === "" ? "" : Number(e.target.value),
                  )
                }
              />
            </div>
            <div>
              <Label htmlFor="notes">Notas</Label>
              <Input
                id="notes"
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
              />
            </div>
            <div className="flex gap-2">
              <Button disabled={loading} type="submit">
                {loading ? (
                  <Loader2 className="h-4 w-4 animate-spin mr-2" />
                ) : null}
                Registrar
              </Button>
              <Link href={`/admin/agreements/${agreementId}`}>
                <Button type="button" variant="outline">
                  Cancelar
                </Button>
              </Link>
            </div>
          </CardContent>
        </Card>
      </form>
    </div>
  );
}

"use client";

import { ArrowLeft, Loader2 } from "lucide-react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useState } from "react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useBranch } from "@/hooks/useBranch";
import { agreementService } from "@/lib/api/services/agreementService";
import { handleApiError } from "@/lib/api/services/errorService";
import { success } from "@/lib/api/services/notificationService";
import { formatRUT, formatRUTAsYouType } from "@/lib/utils/rut";

export default function NewAgreementPage() {
  const router = useRouter();
  const { currentBranchId } = useBranch();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [name, setName] = useState("");
  const [agreementType, setAgreementType] = useState<
    "empresa" | "sindicato" | "mutual"
  >("empresa");
  const [institutionName, setInstitutionName] = useState("");
  const [institutionRut, setInstitutionRut] = useState("");
  const [representativeName, setRepresentativeName] = useState("");
  const [representativeEmail, setRepresentativeEmail] = useState("");
  const [representativePhone, setRepresentativePhone] = useState("");
  const [validFrom, setValidFrom] = useState(
    new Date().toISOString().split("T")[0],
  );
  const [validUntil, setValidUntil] = useState("");
  const [copagoPercent, setCopagoPercent] = useState(20);
  const [discountPercent, setDiscountPercent] = useState<number | "">("");
  const [notes, setNotes] = useState("");

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setLoading(true);

    try {
      const agreement = await agreementService.createAgreement({
        name,
        agreement_type: agreementType,
        institution_name: institutionName,
        institution_rut: institutionRut,
        representative_name: representativeName || undefined,
        representative_email: representativeEmail || undefined,
        representative_phone: representativePhone || undefined,
        valid_from: validFrom,
        valid_until: validUntil || undefined,
        branch_id: currentBranchId || undefined,
        billing_rules: {
          copago_percent: copagoPercent,
          institutional_percent: 100 - copagoPercent,
          require_oc: true,
        },
        discount_percent: discountPercent !== "" ? discountPercent : undefined,
        notes: notes || undefined,
      });

      success("Convenio creado correctamente");
      router.push(`/admin/agreements/${agreement.id}`);
    } catch (err) {
      const errorObj = handleApiError(err, "Crear convenio");
      setError(errorObj?.message || "Error al crear convenio");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Link href="/admin/agreements">
          <Button size="icon" variant="ghost">
            <ArrowLeft className="h-4 w-4" />
          </Button>
        </Link>
        <div>
          <h1 className="text-2xl font-bold text-admin-text-primary">
            Nuevo convenio
          </h1>
          <p className="text-sm text-admin-text-tertiary">
            Crea un convenio con una empresa o institución
          </p>
        </div>
      </div>

      {error && (
        <div className="rounded-lg border border-destructive/50 bg-destructive/10 p-4 text-destructive">
          {error}
        </div>
      )}

      <form onSubmit={handleSubmit}>
        <Card>
          <CardHeader>
            <CardTitle>Datos del convenio</CardTitle>
          </CardHeader>
          <CardContent className="space-y-6">
            <div className="grid gap-4 sm:grid-cols-2">
              <div>
                <Label htmlFor="name">Nombre del convenio</Label>
                <Input
                  required
                  id="name"
                  minLength={2}
                  placeholder="Ej: Minera X - Sucursal Centro"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                />
              </div>
              <div>
                <Label htmlFor="agreementType">Tipo</Label>
                <Select
                  value={agreementType}
                  onValueChange={(v: "empresa" | "sindicato" | "mutual") =>
                    setAgreementType(v)
                  }
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="empresa">Empresa</SelectItem>
                    <SelectItem value="sindicato">Sindicato</SelectItem>
                    <SelectItem value="mutual">Mutual</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="grid gap-4 sm:grid-cols-2">
              <div>
                <Label htmlFor="institutionName">
                  Razón social institucional
                </Label>
                <Input
                  required
                  id="institutionName"
                  minLength={2}
                  placeholder="Ej: Minera Escondida Ltda."
                  value={institutionName}
                  onChange={(e) => setInstitutionName(e.target.value)}
                />
              </div>
              <div>
                <Label htmlFor="institutionRut">RUT institucional</Label>
                <Input
                  required
                  id="institutionRut"
                  placeholder="12.345.678-9"
                  value={institutionRut}
                  onBlur={(e) => {
                    const val = e.target.value.trim();
                    if (val) {
                      const formatted = formatRUT(val);
                      if (formatted) setInstitutionRut(formatted);
                    }
                  }}
                  onChange={(e) =>
                    setInstitutionRut(formatRUTAsYouType(e.target.value))
                  }
                />
              </div>
            </div>

            <div className="grid gap-4 sm:grid-cols-3">
              <div>
                <Label htmlFor="representativeName">Nombre del contacto</Label>
                <Input
                  id="representativeName"
                  placeholder="RR.HH."
                  value={representativeName}
                  onChange={(e) => setRepresentativeName(e.target.value)}
                />
              </div>
              <div>
                <Label htmlFor="representativeEmail">Email</Label>
                <Input
                  id="representativeEmail"
                  type="email"
                  value={representativeEmail}
                  onChange={(e) => setRepresentativeEmail(e.target.value)}
                />
              </div>
              <div>
                <Label htmlFor="representativePhone">Teléfono</Label>
                <Input
                  id="representativePhone"
                  value={representativePhone}
                  onChange={(e) => setRepresentativePhone(e.target.value)}
                />
              </div>
            </div>

            <div className="grid gap-4 sm:grid-cols-2">
              <div>
                <Label htmlFor="validFrom">Vigencia desde</Label>
                <Input
                  required
                  id="validFrom"
                  type="date"
                  value={validFrom}
                  onChange={(e) => setValidFrom(e.target.value)}
                />
              </div>
              <div>
                <Label htmlFor="validUntil">Vigencia hasta</Label>
                <Input
                  id="validUntil"
                  type="date"
                  value={validUntil}
                  onChange={(e) => setValidUntil(e.target.value)}
                />
              </div>
            </div>

            <div className="grid gap-4 sm:grid-cols-2">
              <div>
                <Label htmlFor="copagoPercent">% Copago (trabajador)</Label>
                <Input
                  id="copagoPercent"
                  max={100}
                  min={0}
                  type="number"
                  value={copagoPercent}
                  onChange={(e) => setCopagoPercent(Number(e.target.value))}
                />
                <p className="text-xs text-admin-text-tertiary mt-1">
                  Porcentaje que paga el trabajador en el POS
                </p>
              </div>
              <div>
                <Label htmlFor="discountPercent">% Descuento (opcional)</Label>
                <Input
                  id="discountPercent"
                  max={100}
                  min={0}
                  type="number"
                  value={discountPercent}
                  onChange={(e) =>
                    setDiscountPercent(
                      e.target.value === "" ? "" : Number(e.target.value),
                    )
                  }
                />
              </div>
            </div>

            <div>
              <Label htmlFor="notes">Notas</Label>
              <Input
                id="notes"
                placeholder="Notas internas"
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
              />
            </div>

            <div className="flex gap-2">
              <Button disabled={loading} type="submit">
                {loading ? (
                  <Loader2 className="h-4 w-4 animate-spin mr-2" />
                ) : null}
                Crear convenio
              </Button>
              <Link href="/admin/agreements">
                <Button type="button" variant="outline">
                  Cancelar
                </Button>
              </Link>
            </div>
          </CardContent>
        </Card>
      </form>
    </div>
  );
}

"use client";

import {
  ChevronLeft,
  ChevronRight,
  Eye,
  FileText,
  Loader2,
  Plus,
} from "lucide-react";
import Link from "next/link";
import { useEffect, useState } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { useBranch } from "@/hooks/useBranch";
import {
  Agreement,
  AgreementListParams,
  agreementService,
} from "@/lib/api/services/agreementService";
import { handleApiError } from "@/lib/api/services/errorService";
import { appLogger } from '@/lib/logger';
import { formatDate } from "@/lib/utils";

export default function AgreementsPage() {
  const { currentBranchId, isSuperAdmin } = useBranch();
  const isGlobalView = !currentBranchId && isSuperAdmin;

  const [agreements, setAgreements] = useState<Agreement[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [typeFilter, setTypeFilter] = useState<string>("all");
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [total, setTotal] = useState(0);

  useEffect(() => {
    fetchAgreements();
  }, [currentPage, statusFilter, typeFilter, currentBranchId, isGlobalView]);

  const fetchAgreements = async () => {
    try {
      setLoading(true);
      const params: AgreementListParams = {
        page: currentPage,
        limit: 20,
        branchId: isGlobalView ? undefined : currentBranchId || undefined,
      };
      if (statusFilter !== "all") {
        params.status = statusFilter as AgreementListParams["status"];
      }
      if (typeFilter !== "all") {
        params.agreement_type =
          typeFilter as AgreementListParams["agreement_type"];
      }

      const result = await agreementService.getAgreements(params);
      setAgreements(result.data);
      setTotalPages(result.pagination.totalPages || 1);
      setTotal(result.pagination.total || 0);
      setError(null);
    } catch (err) {
      appLogger.error("Error fetching agreements:", err);
      const errorObj = handleApiError(err, "Convenios");
      setError(errorObj?.message || "Error al cargar convenios");
    } finally {
      setLoading(false);
    }
  };

  const getStatusBadge = (status: string) => {
    const config: Record<
      string,
      {
        variant: "default" | "secondary" | "destructive" | "outline";
        label: string;
      }
    > = {
      active: { variant: "default", label: "Activo" },
      suspended: { variant: "secondary", label: "Suspendido" },
      expired: { variant: "outline", label: "Expirado" },
      cancelled: { variant: "destructive", label: "Cancelado" },
    };
    const c = config[status] || { variant: "outline" as const, label: status };
    return <Badge variant={c.variant}>{c.label}</Badge>;
  };

  const getTypeLabel = (type: string) => {
    const labels: Record<string, string> = {
      empresa: "Empresa",
      sindicato: "Sindicato",
      mutual: "Mutual",
    };
    return labels[type] || type;
  };

  if (loading && agreements.length === 0) {
    return (
      <div className="space-y-6">
        <h1 className="text-2xl sm:text-3xl font-bold text-admin-text-primary">
          Gestión de Convenios
        </h1>
        <div className="flex items-center justify-center py-24">
          <Loader2 className="h-12 w-12 animate-spin text-admin-accent-primary" />
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl sm:text-3xl font-bold text-admin-text-primary">
            Gestión de Convenios
          </h1>
          <p className="text-sm text-admin-text-tertiary mt-1">
            Convenios con empresas, sindicatos e instituciones
          </p>
        </div>
        <Link href="/admin/agreements/new">
          <Button className="gap-2" variant="default">
            <Plus className="h-4 w-4" />
            Nuevo convenio
          </Button>
        </Link>
      </div>

      {error && (
        <div className="rounded-lg border border-destructive/50 bg-destructive/10 p-4 text-destructive">
          {error}
        </div>
      )}

      <Card>
        <CardHeader>
          <div className="flex flex-col sm:flex-row gap-4 sm:items-center">
            <CardTitle className="flex items-center gap-2">
              <FileText className="h-5 w-5" />
              Convenios
            </CardTitle>
            <div className="flex flex-wrap gap-2">
              <Select value={statusFilter} onValueChange={setStatusFilter}>
                <SelectTrigger className="w-[140px]">
                  <SelectValue placeholder="Estado" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Todos</SelectItem>
                  <SelectItem value="active">Activos</SelectItem>
                  <SelectItem value="suspended">Suspendidos</SelectItem>
                  <SelectItem value="expired">Expirados</SelectItem>
                  <SelectItem value="cancelled">Cancelados</SelectItem>
                </SelectContent>
              </Select>
              <Select value={typeFilter} onValueChange={setTypeFilter}>
                <SelectTrigger className="w-[140px]">
                  <SelectValue placeholder="Tipo" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Todos</SelectItem>
                  <SelectItem value="empresa">Empresa</SelectItem>
                  <SelectItem value="sindicato">Sindicato</SelectItem>
                  <SelectItem value="mutual">Mutual</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          {agreements.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-16 text-center">
              <FileText className="h-16 w-16 text-admin-text-tertiary mb-4" />
              <p className="text-admin-text-secondary font-medium">
                No hay convenios aún
              </p>
              <p className="text-sm text-admin-text-tertiary mt-1 mb-4">
                Crea un convenio para gestionar ventas con empresas e
                instituciones
              </p>
              <Link href="/admin/agreements/new">
                <Button variant="outline">
                  <Plus className="h-4 w-4 mr-2" />
                  Crear primer convenio
                </Button>
              </Link>
            </div>
          ) : (
            <>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Nombre</TableHead>
                    <TableHead>Institución</TableHead>
                    <TableHead>Tipo</TableHead>
                    <TableHead>Estado</TableHead>
                    <TableHead>Vigencia</TableHead>
                    <TableHead className="text-right">Acciones</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {agreements.map((ag) => (
                    <TableRow key={ag.id}>
                      <TableCell>{ag.name}</TableCell>
                      <TableCell>
                        <span className="font-medium">
                          {ag.institution_name}
                        </span>
                        <br />
                        <span className="text-xs text-admin-text-tertiary">
                          {ag.institution_rut}
                        </span>
                      </TableCell>
                      <TableCell>{getTypeLabel(ag.agreement_type)}</TableCell>
                      <TableCell>{getStatusBadge(ag.status)}</TableCell>
                      <TableCell>
                        <span className="text-sm">
                          {formatDate(ag.valid_from)}
                          {ag.valid_until
                            ? ` - ${formatDate(ag.valid_until)}`
                            : ""}
                        </span>
                      </TableCell>
                      <TableCell className="text-right">
                        <Link href={`/admin/agreements/${ag.id}`}>
                          <Button size="sm" variant="ghost">
                            <Eye className="h-4 w-4 mr-1" />
                            Ver
                          </Button>
                        </Link>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>

              {totalPages > 1 && (
                <div className="flex items-center justify-between mt-4">
                  <p className="text-sm text-admin-text-tertiary">
                    {total} convenio(s) en total
                  </p>
                  <div className="flex gap-2">
                    <Button
                      disabled={currentPage <= 1}
                      size="sm"
                      variant="outline"
                      onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
                    >
                      <ChevronLeft className="h-4 w-4" />
                    </Button>
                    <span className="flex items-center px-2 text-sm">
                      {currentPage} / {totalPages}
                    </span>
                    <Button
                      disabled={currentPage >= totalPages}
                      size="sm"
                      variant="outline"
                      onClick={() =>
                        setCurrentPage((p) => Math.min(totalPages, p + 1))
                      }
                    >
                      <ChevronRight className="h-4 w-4" />
                    </Button>
                  </div>
                </div>
              )}
            </>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { AlertTriangle } from "lucide-react";
import { useState } from "react";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useBranch } from "@/hooks/useBranch";

import { useAnalytics } from "../../hooks/useAnalytics";
import { AnalyticsHeader } from "./AnalyticsHeader";
import { AnalyticsKPICards } from "./AnalyticsKPICards";
import { AnalyticsOverviewTab } from "./AnalyticsOverviewTab";
import { AnalyticsProductsTab } from "./AnalyticsProductsTab";
import { AnalyticsQuotesTab } from "./AnalyticsQuotesTab";
import { AnalyticsSalesTab } from "./AnalyticsSalesTab";
import { AnalyticsSupportTab } from "./AnalyticsSupportTab";
import type { AnalyticsData } from "./analyticsUtils";
import { AnalyticsWorkOrdersTab } from "./AnalyticsWorkOrdersTab";

export default function AnalyticsContent() {
  const {
    currentBranchId,
    isSuperAdmin,
    branches,
    isLoading: branchLoading,
  } = useBranch();
  const [period, setPeriod] = useState("30");

  // Chart type selectors - Changed defaults from "area" to "column"
  const [salesChartType, setSalesChartType] = useState<"column" | "line">(
    "column",
  );
  const [workOrdersChartType, setWorkOrdersChartType] = useState<
    "column" | "line"
  >("column");
  const [quotesChartType, setQuotesChartType] = useState<"column" | "line">(
    "column",
  );

  const isGlobalView = !currentBranchId && isSuperAdmin;

  const { data, isLoading, error, refetch, isRefetching } = useAnalytics({
    branchId: currentBranchId,
    period,
  });
  const analytics = data as AnalyticsData;

  if (isLoading && !analytics) {
    return (
      <div className="space-y-6">
        <div className="space-y-4">
          <h1 className="text-2xl sm:text-3xl font-bold text-epoch-primary">
            Analíticas y Reportes
          </h1>
          <p className="text-sm text-admin-text-tertiary">
            Cargando datos analíticos...
          </p>
        </div>
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 sm:gap-6">
          {[...Array(8)].map((_, i) => (
            <Card className="animate-pulse" key={i} rounded="none">
              <CardContent className="p-6">
                <div className="h-4 bg-gray-200 rounded w-3/4 mb-2" />
                <div className="h-8 bg-gray-200 rounded w-1/2" />
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    );
  }

  if (error || !analytics) {
    return (
      <div className="space-y-6">
        <div className="space-y-4">
          <h1 className="text-2xl sm:text-3xl font-bold text-epoch-primary">
            Analíticas y Reportes
          </h1>
          <p className="text-sm text-admin-text-tertiary">
            Error al cargar los datos
          </p>
        </div>
        <Card rounded="none">
          <CardContent className="text-center py-16">
            <AlertTriangle className="h-12 w-12 text-red-500 mx-auto mb-4" />
            <h3 className="text-lg font-semibold text-red-700 mb-2">
              Error al cargar analíticas
            </h3>
            <p className="text-admin-text-tertiary mb-4">
              {error?.message || "No se pudieron cargar los datos"}
            </p>
            <Button onClick={refetch}>Reintentar</Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <AnalyticsHeader
        description={
          isGlobalView
            ? `Métricas y análisis - Todas las sucursales - Últimos ${analytics.period.days} días`
            : `Métricas y análisis - Últimos ${analytics.period.days} días`
        }
        period={period}
        refreshing={isRefetching}
        title="Analíticas y Reportes"
        onPeriodChange={setPeriod}
        onRefresh={refetch}
      />

      <AnalyticsKPICards
        appointments={analytics.appointments}
        kpis={analytics.kpis}
        products={analytics.products}
        quotes={analytics.quotes}
        workOrders={analytics.workOrders}
      />

      {/* Analytics Tabs */}
      <Tabs className="space-y-6" defaultValue="overview">
        <div className="overflow-x-auto overflow-y-hidden -mx-4 px-4 sm:mx-0 sm:px-0 min-w-0 [scrollbar-width:thin] [&::-webkit-scrollbar]:h-1 [&::-webkit-scrollbar-track]:bg-transparent [&::-webkit-scrollbar-thumb]:rounded-full [&::-webkit-scrollbar-thumb]:bg-admin-border-primary/40">
          <TabsList className="inline-flex w-max min-w-full sm:min-w-0 sm:w-full flex-nowrap gap-1 sm:gap-2 p-1 h-auto rounded-md bg-muted">
            <TabsTrigger
              className="shrink-0 text-[10px] sm:text-sm px-2 sm:px-4 py-2 min-h-[44px]"
              value="overview"
            >
              Resumen
            </TabsTrigger>
            <TabsTrigger
              className="shrink-0 text-[10px] sm:text-sm px-2 sm:px-4 py-2 min-h-[44px]"
              value="work-orders"
            >
              Trabajos
            </TabsTrigger>
            <TabsTrigger
              className="shrink-0 text-[10px] sm:text-sm px-2 sm:px-4 py-2 min-h-[44px]"
              value="quotes"
            >
              Presupuestos
            </TabsTrigger>
            <TabsTrigger
              className="shrink-0 text-[10px] sm:text-sm px-2 sm:px-4 py-2 min-h-[44px]"
              value="sales"
            >
              Ventas
            </TabsTrigger>
            <TabsTrigger
              className="shrink-0 text-[10px] sm:text-sm px-2 sm:px-4 py-2 min-h-[44px]"
              value="products"
            >
              Productos
            </TabsTrigger>
            {analytics.support && (
              <TabsTrigger
                className="shrink-0 text-[10px] sm:text-sm px-2 sm:px-4 py-2 min-h-[44px]"
                value="support"
              >
                Incidentes
              </TabsTrigger>
            )}
          </TabsList>
        </div>

        <TabsContent className="space-y-4 sm:space-y-6" value="overview">
          <AnalyticsOverviewTab
            quotes={analytics.quotes}
            salesChartType={salesChartType}
            trends={analytics.trends}
            workOrders={analytics.workOrders}
            workOrdersChartType={workOrdersChartType}
            onSalesChartTypeChange={setSalesChartType}
            onWorkOrdersChartTypeChange={setWorkOrdersChartType}
          />
        </TabsContent>

        <TabsContent className="space-y-4 sm:space-y-6" value="work-orders">
          <AnalyticsWorkOrdersTab
            avgDeliveryDays={analytics.kpis.avgDeliveryDays}
            workOrders={analytics.workOrders}
            workOrdersTrend={analytics.trends.workOrders}
          />
        </TabsContent>

        <TabsContent className="space-y-4 sm:space-y-6" value="quotes">
          <AnalyticsQuotesTab
            avgQuoteValue={analytics.kpis.avgQuoteValue}
            quoteConversionRate={analytics.kpis.quoteConversionRate}
            quotes={analytics.quotes}
            quotesChartType={quotesChartType}
            quotesTrend={analytics.trends.quotes}
            onQuotesChartTypeChange={setQuotesChartType}
          />
        </TabsContent>

        <TabsContent className="space-y-4 sm:space-y-6" value="sales">
          <AnalyticsSalesTab
            categoryRevenue={analytics.products.categoryRevenue}
            kpis={{
              totalRevenue: analytics.kpis.totalRevenue,
              avgOrderValue: analytics.kpis.avgOrderValue,
              totalOrders: analytics.kpis.totalOrders,
              revenueGrowth: analytics.kpis.revenueGrowth,
            }}
            paymentMethods={analytics.paymentMethods}
          />
        </TabsContent>

        <TabsContent className="space-y-4 sm:space-y-6" value="products">
          <AnalyticsProductsTab products={analytics.products} />
        </TabsContent>

        {analytics.support && (
          <TabsContent className="space-y-4 sm:space-y-6" value="support">
            <AnalyticsSupportTab support={analytics.support} />
          </TabsContent>
        )}
      </Tabs>
    </div>
  );
}

"use client";

import {
  BarChart3,
  LineChart as LineChartIcon,
  PieChart as PieChartIcon,
  TrendingUp,
  Wrench,
} from "lucide-react";
import dynamic from "next/dynamic";

const EnhancedColumnChart = dynamic(
  () =>
    import("@/components/admin/charts/EnhancedColumnChart").then(
      (m) => m.EnhancedColumnChart,
    ),
  {
    loading: () => <Skeleton className="h-[300px] w-full rounded-xl" />,
    ssr: false,
  },
);
const EnhancedLineChart = dynamic(
  () =>
    import("@/components/admin/charts/EnhancedLineChart").then(
      (m) => m.EnhancedLineChart,
    ),
  {
    loading: () => <Skeleton className="h-[300px] w-full rounded-xl" />,
    ssr: false,
  },
);
const EnhancedPieChart = dynamic(
  () =>
    import("@/components/admin/charts/EnhancedPieChart").then(
      (m) => m.EnhancedPieChart,
    ),
  {
    loading: () => <Skeleton className="h-[300px] w-full rounded-xl" />,
    ssr: false,
  },
);
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";

import { formatPrice, getStatusLabel } from "./analyticsUtils";

interface AnalyticsOverviewTabProps {
  trends: {
    sales: Array<{ date: string; value: number; count: number }>;
    workOrders: Array<{ date: string; value: number; count: number }>;
  };
  workOrders: {
    byStatus: Record<string, number>;
  };
  quotes: {
    byStatus: Record<string, number>;
  };
  salesChartType: "column" | "line";
  workOrdersChartType: "column" | "line";
  onSalesChartTypeChange: (type: "column" | "line") => void;
  onWorkOrdersChartTypeChange: (type: "column" | "line") => void;
}

export function AnalyticsOverviewTab({
  trends,
  workOrders,
  quotes,
  salesChartType,
  workOrdersChartType,
  onSalesChartTypeChange,
  onWorkOrdersChartTypeChange,
}: AnalyticsOverviewTabProps) {
  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-4 sm:gap-6">
      {/* Revenue Trend */}
      <Card
        className="bg-admin-bg-tertiary border border-admin-border-primary shadow-soft hover:shadow-medium transition-all duration-300"
        rounded="none"
      >
        <CardHeader className="p-4 sm:p-6">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
            <div className="flex items-center gap-2 min-w-0">
              <TrendingUp className="h-4 w-4 sm:h-5 sm:w-5 shrink-0" />
              <CardTitle className="text-base sm:text-lg truncate">
                Tendencia de Ingresos
              </CardTitle>
            </div>
            <div className="flex gap-1 shrink-0">
              <Button
                className="h-8 sm:h-7 px-2 sm:px-3 text-xs min-h-[44px] sm:min-h-0"
                size="sm"
                variant={
                  salesChartType === "column" ? "default" : "outline"
                }
                onClick={() => onSalesChartTypeChange("column")}
              >
                <BarChart3 className="h-3 w-3 mr-1" />
                Barras
              </Button>
              <Button
                className="h-8 sm:h-7 px-2 sm:px-3 text-xs min-h-[44px] sm:min-h-0"
                size="sm"
                variant={
                  salesChartType === "line" ? "default" : "outline"
                }
                onClick={() => onSalesChartTypeChange("line")}
              >
                <LineChartIcon className="h-3 w-3 mr-1" />
                Líneas
              </Button>
            </div>
          </div>
        </CardHeader>
        <CardContent className="p-4 sm:p-6 pt-0">
          {salesChartType === "column" ? (
            <EnhancedColumnChart
              color="#C5A059"
              data={trends.sales}
              formatValue={formatPrice}
              height={250}
              title="Ingresos por Período"
            />
          ) : (
            <EnhancedLineChart
              color="#C5A059"
              data={trends.sales}
              formatValue={formatPrice}
              height={250}
              showGrid={true}
              title="Evolución de Ingresos"
            />
          )}
        </CardContent>
      </Card>

      {/* Work Orders Trend */}
      <Card
        className="bg-admin-bg-tertiary border border-admin-border-primary shadow-soft hover:shadow-medium transition-all duration-300"
        rounded="none"
      >
        <CardHeader className="p-4 sm:p-6">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
            <div className="flex items-center gap-2 min-w-0">
              <Wrench className="h-4 w-4 sm:h-5 sm:w-5 shrink-0" />
              <CardTitle className="text-base sm:text-lg truncate">
                Trabajos de Laboratorio
              </CardTitle>
            </div>
            <div className="flex gap-1 shrink-0">
              <Button
                className="h-8 sm:h-7 px-2 sm:px-3 text-xs min-h-[44px] sm:min-h-0"
                size="sm"
                variant={
                  workOrdersChartType === "column" ? "default" : "outline"
                }
                onClick={() => onWorkOrdersChartTypeChange("column")}
              >
                <BarChart3 className="h-3 w-3 mr-1" />
                Barras
              </Button>
              <Button
                className="h-8 sm:h-7 px-2 sm:px-3 text-xs min-h-[44px] sm:min-h-0"
                size="sm"
                variant={
                  workOrdersChartType === "line" ? "default" : "outline"
                }
                onClick={() => onWorkOrdersChartTypeChange("line")}
              >
                <LineChartIcon className="h-3 w-3 mr-1" />
                Líneas
              </Button>
            </div>
          </div>
        </CardHeader>
        <CardContent className="p-4 sm:p-6 pt-0">
          {workOrdersChartType === "column" ? (
            <EnhancedColumnChart
              color="#1A2B23"
              data={trends.workOrders}
              formatValue={(val) => Math.round(val).toString()}
              height={250}
              title="Trabajos por Período"
            />
          ) : (
            <EnhancedLineChart
              color="#1A2B23"
              data={trends.workOrders}
              formatValue={(val) => Math.round(val).toString()}
              height={250}
              showGrid={true}
              title="Evolución de Trabajos"
            />
          )}
        </CardContent>
      </Card>

      {/* Work Orders Status Distribution */}
      <Card
        className="bg-admin-bg-tertiary border border-admin-border-primary shadow-soft hover:shadow-medium transition-all duration-300"
        rounded="none"
      >
        <CardHeader className="p-4 sm:p-6">
          <div className="flex items-center gap-2 min-w-0">
            <PieChartIcon className="h-4 w-4 sm:h-5 sm:w-5 shrink-0" />
            <CardTitle className="text-base sm:text-lg truncate">
              Estados de Trabajos
            </CardTitle>
          </div>
        </CardHeader>
        <CardContent className="p-4 sm:p-6 pt-0">
          {Object.keys(workOrders.byStatus).length > 0 ? (
            <EnhancedPieChart
              data={Object.entries(workOrders.byStatus).map(
                ([status, count]) => ({
                  label: getStatusLabel(status),
                  value: count as number,
                }),
              )}
              formatValue={(val) => Math.round(val).toString()}
              height={250}
              showLegend={true}
              showPercentage={true}
              title="Distribución por Estado"
            />
          ) : (
            <div className="text-center py-8 text-admin-text-tertiary">
              No hay trabajos en este período
            </div>
          )}
        </CardContent>
      </Card>

      {/* Quotes Status Distribution */}
      <Card
        className="bg-admin-bg-tertiary border border-admin-border-primary shadow-soft hover:shadow-medium transition-all duration-300"
        rounded="none"
      >
        <CardHeader className="p-4 sm:p-6">
          <div className="flex items-center gap-2 min-w-0">
            <PieChartIcon className="h-4 w-4 sm:h-5 sm:w-5 shrink-0" />
            <CardTitle className="text-base sm:text-lg truncate">
              Estados de Presupuestos
            </CardTitle>
          </div>
        </CardHeader>
        <CardContent className="p-4 sm:p-6 pt-0">
          {Object.keys(quotes.byStatus).length > 0 ? (
            <EnhancedPieChart
              data={Object.entries(quotes.byStatus).map(
                ([status, count]) => ({
                  label: getStatusLabel(status),
                  value: count as number,
                }),
              )}
              formatValue={(val) => Math.round(val).toString()}
              height={250}
              showLegend={true}
              showPercentage={true}
              title="Distribución por Estado"
            />
          ) : (
            <div className="text-center py-8 text-admin-text-tertiary">
              No hay presupuestos en este período
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { AlertTriangle, BarChart3, Package } from "lucide-react";
import dynamic from "next/dynamic";

const EnhancedBarChart = dynamic(
  () =>
    import("@/components/admin/charts/EnhancedBarChart").then(
      (m) => m.EnhancedBarChart,
    ),
  {
    loading: () => <Skeleton className="h-[300px] w-full rounded-xl" />,
