import { formatPrice } from "./analyticsUtils";

interface AnalyticsProductsTabProps {
  products: {
    topProducts: Array<{
      id: string;
      name: string;
      category: string;
      revenue: number;
      quantity: number;
      orders: number;
    }>;
    lowStock: number;
