                <TableHeader>
                  <TableRow>
                    <TableHead>Producto</TableHead>
                    <TableHead>Ingresos</TableHead>
                    <TableHead>Cantidad</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {products.topProducts.slice(0, 8).map((product) => (
                    <TableRow key={product.id}>
                      <TableCell>
                        <div>
                          <div
                            className="font-medium truncate max-w-[150px]"
