                      "Lunes",
                      "Martes",
                      "Miércoles",
                      "Jueves",
                      "Viernes",
                      "Sábado",
                      "Domingo",
                    ].map((day) => {
                      const dayApts = data.byDay[day] || [];
                      if (dayApts.length === 0) return null;
                      const dateStr = dayApts[0]?.appointment_date;
                      return (
                        <div
                          className="border border-admin-border-primary/30 rounded-xl overflow-hidden"
