interface BlockedDatesCardProps {
  settings: ScheduleSettings;
  newBlockedDate: string;
  onNewBlockedDateChange: (value: string) => void;
  onAddBlockedDate: () => void;
  onRemoveBlockedDate: (date: string) => void;
