                    className="h-8 w-8 sm:h-7 sm:w-7 p-0 rounded-lg text-admin-text-tertiary hover:text-admin-error hover:bg-admin-error/5 transition-all shrink-0"
                    size="sm"
                    type="button"
                    variant="ghost"
                    onClick={() => onRemoveBlockedDate(date)}
