"use client";

import {
  Building2,
  CheckCircle,
  Edit,
  Loader2,
  Mail,
  MapPin,
  Phone,
  Plus,
  Trash2,
  XCircle,
} from "lucide-react";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogTrigger,
} from "@/components/ui/dialog";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { useBranch } from "@/hooks/useBranch";
import { appLogger } from '@/lib/logger';

import { BranchDeleteDialog } from "./BranchDeleteDialog";
import { BranchFormDialog } from "./BranchFormDialog";

interface Branch {
  id: string;
  name: string;
  code: string;
  address_line_1?: string;
  address_line_2?: string;
  city?: string;
  state?: string;
  postal_code?: string;
  country?: string;
  phone?: string;
  email?: string;
  is_active: boolean;
  settings?: unknown;
  created_at: string;
  updated_at: string;
}

export default function BranchesContent() {
  const { isSuperAdmin, refreshBranches } = useBranch();
  const [branches, setBranches] = useState<Branch[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
  const [selectedBranch, setSelectedBranch] = useState<Branch | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Form state
  const [formData, setFormData] = useState({
    name: "",
    code: "",
    address_line_1: "",
    address_line_2: "",
    city: "",
    state: "",
    postal_code: "",
    country: "Chile",
    phone: "",
    email: "",
    is_active: true,
  });

  useEffect(() => {
    fetchBranches();
  }, []);

  const fetchBranches = async () => {
    try {
      setIsLoading(true);
      const response = await fetch("/api/admin/branches");

      if (!response.ok) {
        throw new Error("Failed to fetch branches");
      }

      const data = await response.json();
      setBranches(data.branches || []);
    } catch (error: unknown) {
      appLogger.error("Error fetching branches:", error);
      toast.error("Error al cargar sucursales");
    } finally {
      setIsLoading(false);
    }
  };

  const handleOpenDialog = (branch?: Branch) => {
    if (branch) {
      setSelectedBranch(branch);
      setFormData({
        name: branch.name,
        code: branch.code,
        address_line_1: branch.address_line_1 || "",
        address_line_2: branch.address_line_2 || "",
        city: branch.city || "",
        state: branch.state || "",
        postal_code: branch.postal_code || "",
        country: branch.country || "Chile",
        phone: branch.phone || "",
        email: branch.email || "",
        is_active: branch.is_active,
      });
    } else {
      setSelectedBranch(null);
      setFormData({
        name: "",
        code: "",
        address_line_1: "",
        address_line_2: "",
        city: "",
        state: "",
        postal_code: "",
        country: "Chile",
        phone: "",
        email: "",
        is_active: true,
      });
    }
    setIsDialogOpen(true);
  };

  const handleCloseDialog = () => {
    setIsDialogOpen(false);
    setSelectedBranch(null);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.name || !formData.code) {
      toast.error("El nombre y código son obligatorios");
      return;
    }

    try {
      setIsSubmitting(true);
      const url = selectedBranch
        ? `/api/admin/branches/${selectedBranch.id}`
        : "/api/admin/branches";

      const method = selectedBranch ? "PUT" : "POST";

      const response = await fetch(url, {
        method,
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(formData),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || "Error al guardar sucursal");
      }

      toast.success(
        selectedBranch
          ? "Sucursal actualizada exitosamente"
          : "Sucursal creada exitosamente",
      );

      handleCloseDialog();
      fetchBranches();
      // Refresh branches in context so selector updates
      if (refreshBranches) {
        await refreshBranches();
      }
    } catch (error: unknown) {
      appLogger.error("Error saving branch:", error);
      const errorMessage =
        error instanceof Error ? error.message : "Error al guardar sucursal";
      toast.error(errorMessage);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDelete = async () => {
    if (!selectedBranch) return;

    try {
      setIsSubmitting(true);
      const response = await fetch(`/api/admin/branches/${selectedBranch.id}`, {
        method: "DELETE",
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || "Error al eliminar sucursal");
      }

      toast.success("Sucursal eliminada exitosamente");
      setIsDeleteDialogOpen(false);
      setSelectedBranch(null);
      fetchBranches();
      // Refresh branches in context so selector updates
      if (refreshBranches) {
        await refreshBranches();
      }
    } catch (error: unknown) {
      appLogger.error("Error deleting branch:", error);
      const errorMessage =
        error instanceof Error ? error.message : "Error al eliminar sucursal";
      toast.error(errorMessage);
    } finally {
      setIsSubmitting(false);
    }
  };

  // Check if user is super admin
  if (!isSuperAdmin) {
    return (
      <div className="p-4 sm:p-6 bg-epoch-background min-h-screen">
        <Card className="rounded-xl border border-border">
          <CardContent className="p-4 sm:p-6">
            <div className="text-center py-6 sm:py-8">
              <XCircle className="h-10 w-10 sm:h-12 sm:w-12 text-destructive mx-auto mb-3 sm:mb-4" />
              <h2 className="text-lg sm:text-xl font-bold text-epoch-primary mb-2">
                Acceso Restringido
              </h2>
              <p className="text-sm text-epoch-primary/80">
                Solo los super administradores pueden gestionar sucursales.
              </p>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="p-4 sm:p-6 bg-epoch-background min-h-screen space-y-4 sm:space-y-6">
      {/* Header - reorganizado en filas */}
      <div className="flex flex-col gap-4 sm:gap-6">
        <h1 className="text-xl sm:text-2xl md:text-3xl font-display font-bold text-epoch-primary tracking-tight">
          Gestión de Sucursales
        </h1>
        <p className="text-sm sm:text-base text-epoch-primary/80 max-w-2xl">
          Administra las sucursales de tu negocio
        </p>
        <div className="flex justify-start sm:justify-end">
          <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
            <DialogTrigger asChild>
              <Button
                className="rounded-xl bg-epoch-primary hover:bg-epoch-surface text-white font-display font-bold text-[10px] tracking-[0.2em] uppercase min-h-[44px] px-6 w-full sm:w-auto"
                onClick={() => handleOpenDialog()}
              >
                <Plus className="h-4 w-4 mr-2 shrink-0" />
                Nueva Sucursal
              </Button>
            </DialogTrigger>
            <DialogContent className="max-w-[calc(100vw-2rem)] sm:max-w-2xl max-h-[90vh] overflow-y-auto">
              <BranchFormDialog
                formData={formData}
                isEditing={!!selectedBranch}
                isSubmitting={isSubmitting}
                onCancel={handleCloseDialog}
                onFormDataChange={setFormData}
                onSubmit={handleSubmit}
              />
            </DialogContent>
          </Dialog>
        </div>
      </div>

      <Card className="rounded-xl border border-border">
        <CardHeader className="p-4 sm:p-6 pb-0">
          <CardTitle className="font-display text-epoch-primary text-base sm:text-lg">
            Sucursales
          </CardTitle>
          <CardDescription className="text-xs sm:text-sm text-epoch-primary/80">
            Lista de todas las sucursales del negocio
          </CardDescription>
        </CardHeader>
        <CardContent className="p-4 sm:p-6 pt-4">
          {isLoading ? (
            <div className="flex justify-center items-center py-8 sm:py-12">
              <Loader2 className="h-8 w-8 animate-spin text-epoch-primary" />
            </div>
          ) : branches.length === 0 ? (
            <div className="text-center py-8 sm:py-12">
              <Building2 className="h-10 w-10 sm:h-12 sm:w-12 text-epoch-primary/40 mx-auto mb-3 sm:mb-4" />
              <h3 className="text-base sm:text-lg font-semibold text-epoch-primary mb-2">
                No hay sucursales
              </h3>
              <p className="text-sm text-epoch-primary/80 mb-4">
                Crea tu primera sucursal para comenzar
              </p>
              <Button
                className="rounded-xl bg-epoch-primary hover:bg-epoch-surface text-white font-display font-bold text-[10px] tracking-[0.2em] uppercase min-h-[44px] px-6"
                onClick={() => handleOpenDialog()}
              >
                <Plus className="h-4 w-4 mr-2" />
                Crear Sucursal
              </Button>
            </div>
          ) : (
            <div className="overflow-x-auto -mx-4 px-4 md:mx-0 md:px-0">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead className="text-epoch-primary/80 text-xs sm:text-sm">
                      Nombre
                    </TableHead>
                    <TableHead className="text-epoch-primary/80 text-xs sm:text-sm">
                      Código
                    </TableHead>
                    <TableHead className="text-epoch-primary/80 text-xs sm:text-sm">
                      Ubicación
                    </TableHead>
                    <TableHead className="text-epoch-primary/80 text-xs sm:text-sm">
                      Contacto
                    </TableHead>
                    <TableHead className="text-epoch-primary/80 text-xs sm:text-sm">
                      Estado
                    </TableHead>
                    <TableHead className="text-right text-epoch-primary/80 text-xs sm:text-sm">
                      Acciones
                    </TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {branches.map((branch) => (
                    <TableRow key={branch.id}>
                      <TableCell className="font-medium text-epoch-primary text-xs sm:text-sm">
                        {branch.name}
                      </TableCell>
                      <TableCell>
                        <Badge
                          className="border-epoch-primary/20 text-epoch-primary font-medium text-[10px] sm:text-xs"
                          variant="outline"
                        >
                          {branch.code}
                        </Badge>
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center gap-2 text-xs sm:text-sm text-epoch-primary/80 min-w-0">
                          <MapPin className="h-3.5 w-3.5 sm:h-4 sm:w-4 text-epoch-accent shrink-0" />
                          <span className="truncate">
                            {branch.city || branch.state
                              ? `${branch.city || ""}${branch.city && branch.state ? ", " : ""}${branch.state || ""}`
                              : "Sin ubicación"}
                          </span>
                        </div>
                      </TableCell>
                      <TableCell>
                        <div className="space-y-1 min-w-0">
                          {branch.phone && (
                            <div className="flex items-center gap-2 text-xs sm:text-sm text-epoch-primary/80">
                              <Phone className="h-3 w-3 shrink-0" />
                              <span className="truncate">{branch.phone}</span>
                            </div>
                          )}
                          {branch.email && (
                            <div className="flex items-center gap-2 text-xs sm:text-sm text-epoch-primary/80">
                              <Mail className="h-3 w-3 shrink-0" />
                              <span className="truncate">{branch.email}</span>
                            </div>
                          )}
                          {!branch.phone && !branch.email && (
                            <span className="text-xs sm:text-sm text-epoch-primary/70">
                              Sin contacto
                            </span>
                          )}
                        </div>
                      </TableCell>
                      <TableCell>
                        {branch.is_active ? (
                          <Badge className="bg-epoch-primary text-white text-[10px] sm:text-xs">
                            <CheckCircle className="h-3 w-3 mr-1 shrink-0" />
                            Activa
                          </Badge>
                        ) : (
                          <Badge
                            className="border-epoch-primary/20 text-epoch-primary/70 text-[10px] sm:text-xs"
                            variant="outline"
                          >
                            <XCircle className="h-3 w-3 mr-1 shrink-0" />
                            Inactiva
                          </Badge>
                        )}
                      </TableCell>
                      <TableCell className="text-right">
                        <div className="flex justify-end gap-1 sm:gap-2">
                          <Button
                            className="min-h-[44px] min-w-[44px] sm:min-h-8 sm:min-w-8 rounded-xl"
                            size="sm"
                            variant="ghost"
                            onClick={() => handleOpenDialog(branch)}
                          >
                            <Edit className="h-4 w-4" />
                          </Button>
                          <Button
                            className="min-h-[44px] min-w-[44px] sm:min-h-8 sm:min-w-8 rounded-xl"
                            disabled={branch.code === "MAIN"}
                            size="sm"
                            variant="ghost"
                            onClick={() => {
                              setSelectedBranch(branch);
                              setIsDeleteDialogOpen(true);
                            }}
                          >
                            <Trash2 className="h-4 w-4 text-destructive" />
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>

      <BranchDeleteDialog
        branchCode={selectedBranch?.code || ""}
        branchName={selectedBranch?.name || ""}
        isSubmitting={isSubmitting}
        open={isDeleteDialogOpen}
        onDelete={handleDelete}
        onOpenChange={(open) => {
          setIsDeleteDialogOpen(open);
          if (!open) setSelectedBranch(null);
        }}
      />
    </div>
  );
}

"use client";

import { ArrowLeft, CheckCircle, DollarSign, RefreshCw } from "lucide-react";
import Link from "next/link";

import { Button } from "@/components/ui/button";
import { DialogFooter } from "@/components/ui/dialog";

interface ActionsSectionProps {
  isOperativoMode: boolean;
  fieldOperationIdFromUrl: string | null;
  effectiveBranchId: string | null;
  isSuperAdmin: boolean;
  closing: boolean;
  closingEnabled: boolean;
  handleCloseCashRegister: () => Promise<void>;
  setShowCloseDialog: (v: boolean) => void;
}

export function CashRegisterActionsSection(props: ActionsSectionProps) {
  const {
    isOperativoMode,
    fieldOperationIdFromUrl,
    effectiveBranchId,
    isSuperAdmin,
    closing,
    closingEnabled,
    handleCloseCashRegister,
    setShowCloseDialog,
  } = props;

  return (
    <>
      {/* Header Actions */}
      <div className="flex flex-wrap items-center gap-2">
        <Link
          href={
            isOperativoMode && fieldOperationIdFromUrl
              ? `/admin/pos?field_operation_id=${fieldOperationIdFromUrl}`
              : "/admin/pos"
          }
        >
          <Button className="shrink-0" size="sm" variant="outline">
            <ArrowLeft className="h-4 w-4 mr-2" />
            Volver al POS
          </Button>
        </Link>
        <Button
          className="shrink-0"
          disabled={!effectiveBranchId && !isSuperAdmin}
          onClick={() => setShowCloseDialog(true)}
        >
          <DollarSign className="h-4 w-4 mr-2" />
          Cerrar Caja
        </Button>
      </div>

      {/* Close Dialog Footer */}
      <DialogFooter className="flex-col-reverse sm:flex-row gap-2 sm:gap-0 pt-2">
        <div className="flex flex-wrap gap-2 w-full sm:w-auto order-2 sm:order-1">
          {isOperativoMode && fieldOperationIdFromUrl && (
            <Link
              className="inline-flex"
              href={`/admin/field-operations/${fieldOperationIdFromUrl}`}
            >
              <Button
                className="w-full sm:w-auto min-h-[44px] sm:min-h-0"
                variant="outline"
              >
                <ArrowLeft className="h-4 w-4 mr-2" />
                Volver al operativo
              </Button>
            </Link>
          )}
          <Button
            className="w-full sm:w-auto min-h-[44px] sm:min-h-0"
            variant="outline"
            onClick={() => setShowCloseDialog(false)}
          >
            Cancelar
          </Button>
        </div>
        <Button
          className="w-full sm:w-auto min-h-[44px] sm:min-h-0 order-1 sm:order-2"
          disabled={closing || !closingEnabled}
          onClick={handleCloseCashRegister}
        >
          {closing ? (
            <>
              <RefreshCw className="h-4 w-4 mr-2 animate-spin" />
              Cerrando...
            </>
          ) : (
            <>
              <CheckCircle className="h-4 w-4 mr-2" />
              Cerrar Caja
            </>
          )}
        </Button>
      </DialogFooter>
    </>
  );
}

"use client";

import {
  CheckCircle,
  Eye,
  FileText,
  RefreshCw,
  RotateCcw,
  TrendingDown,
  TrendingUp,
} from "lucide-react";
import Link from "next/link";
import type { ReactNode } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Pagination } from "@/components/ui/pagination";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { formatCurrency, formatDate } from "@/lib/utils";

import type { CashClosure } from "./cashRegister.types";

// ponytail: icon map inline — too few variants to justify extraction
const STATUS_ICONS: Record<
  string,
  React.ComponentType<{ className?: string }>
> = {
  draft: RefreshCw,
  confirmed: CheckCircle,
  reviewed: Eye,
  closed: CheckCircle,
  reopened: RefreshCw,
};

interface ClosureSectionProps {
  loading: boolean;
  closures: CashClosure[];
  closuresCurrentPage: number;
  closuresItemsPerPage: number;
  closuresTotalCount: number;
  effectiveBranchId: string | null;
  isOperativoMode: boolean;
  isSuperAdmin: boolean;
  reopening: boolean;
  getStatusBadge: (
    status: string,
    reopenedAt?: string | null,
    posSessionId?: string | null,
  ) => { variant: string; label: string; status: string };
  handleReopenCash: (sessionId: string) => Promise<void>;
  setClosuresCurrentPage: (v: number) => void;
  setClosuresItemsPerPage: (v: number) => void;
}

export function CashRegisterClosureSection(props: ClosureSectionProps) {
  const {
    loading,
    closures,
    closuresCurrentPage,
    closuresItemsPerPage,
    closuresTotalCount,
    effectiveBranchId,
    isOperativoMode,
    isSuperAdmin,
    reopening,
    getStatusBadge,
    handleReopenCash,
    setClosuresCurrentPage,
    setClosuresItemsPerPage,
  } = props;

  const renderStatusBadgeElement = (
    status: string,
    reopenedAt?: string | null,
    posSessionId?: string | null,
  ): ReactNode => {
    const {
      variant,
      label,
      status: st,
    } = getStatusBadge(status, reopenedAt, posSessionId);
    const Icon = STATUS_ICONS[st] || FileText;
    return (
      <Badge
        className="flex items-center gap-1"
        variant={variant as "default" | "secondary" | "destructive" | "outline"}
      >
        <Icon className="h-3 w-3" />
        {label}
      </Badge>
    );
  };

  return (
    <Card className="bg-admin-bg-tertiary shadow-[0_1px_3px_rgba(0,0,0,0.3)] min-w-0">
      <CardHeader>
        <CardTitle>Cierres de Caja</CardTitle>
      </CardHeader>
      <CardContent>
        {loading ? (
          <div className="text-center py-12">
            <RefreshCw className="h-8 w-8 animate-spin text-epoch-primary mx-auto mb-4" />
            <p className="text-admin-text-tertiary">Cargando cierres...</p>
          </div>
        ) : closures.length === 0 ? (
          <div className="text-center py-12">
            <FileText className="h-12 w-12 text-admin-text-tertiary mx-auto mb-4" />
            <h3 className="text-lg font-semibold text-epoch-primary mb-2">
              No hay cierres de caja
            </h3>
            <p className="text-admin-text-tertiary">
              {effectiveBranchId
                ? isOperativoMode
                  ? "Aún no se ha cerrado la caja para este operativo"
                  : "Aún no se ha cerrado la caja para esta sucursal"
                : "Seleccione una sucursal para ver sus cierres de caja"}
            </p>
          </div>
        ) : (
          <div className="w-full min-w-0 overflow-x-auto -mx-4 px-4 md:mx-0 md:px-0">
            <Table className="min-w-[800px]">
              <TableHeader>
                <TableRow>
                  {isSuperAdmin && <TableHead>Sucursal</TableHead>}
                  <TableHead>Fecha</TableHead>
                  <TableHead>Ventas Totales</TableHead>
                  <TableHead>Transacciones</TableHead>
                  <TableHead>Efectivo</TableHead>
                  <TableHead>Tarjeta Débito</TableHead>
                  <TableHead>Tarjeta Crédito</TableHead>
                  <TableHead>Transferencias</TableHead>
                  <TableHead>Diferencia</TableHead>
                  <TableHead>Estado</TableHead>
                  <TableHead>Cerrado por</TableHead>
                  <TableHead>Acciones</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {closures.map((closure) => {
                  const transferSales = closure.other_payment_sales || 0;
                  return (
                    <TableRow key={closure.id}>
                      {isSuperAdmin && (
                        <TableCell>{closure.branch?.name || "N/A"}</TableCell>
                      )}
                      <TableCell>{formatDate(closure.closure_date)}</TableCell>
                      <TableCell className="font-semibold">
                        {formatCurrency(closure.total_sales)}
                      </TableCell>
                      <TableCell>{closure.total_transactions}</TableCell>
                      <TableCell>
                        {formatCurrency(closure.cash_sales)}
                      </TableCell>
                      <TableCell>
                        {formatCurrency(closure.debit_card_sales)}
                      </TableCell>
                      <TableCell>
                        {formatCurrency(closure.credit_card_sales)}
                      </TableCell>
                      <TableCell>{formatCurrency(transferSales)}</TableCell>
                      <TableCell>
                        {closure.cash_difference !== null &&
                        closure.cash_difference !== undefined ? (
                          <div className="flex items-center gap-1">
                            {closure.cash_difference > 0 ? (
                              <>
                                <TrendingUp className="h-4 w-4 text-green-600" />
                                <span className="text-green-600 font-semibold">
                                  +
                                  {formatCurrency(
                                    Math.abs(closure.cash_difference),
                                  )}
                                </span>
                              </>
                            ) : closure.cash_difference < 0 ? (
                              <>
                                <TrendingDown className="h-4 w-4 text-red-600" />
                                <span className="text-red-600 font-semibold">
                                  {formatCurrency(closure.cash_difference)}
                                </span>
                              </>
                            ) : (
                              <span className="text-admin-text-tertiary">
                                $0
                              </span>
                            )}
                          </div>
                        ) : (
                          <span className="text-admin-text-tertiary">-</span>
                        )}
                      </TableCell>
                      <TableCell>
                        {renderStatusBadgeElement(
                          closure.status,
                          closure.reopened_at,
                          closure.pos_session_id,
                        )}
                      </TableCell>
                      <TableCell>
                        {closure.closed_by_user
                          ? `${closure.closed_by_user.first_name} ${closure.closed_by_user.last_name}`
                          : "N/A"}
                      </TableCell>
                      <TableCell className="space-x-2">
                        {isSuperAdmin &&
                          (closure.status === "closed" ||
                            closure.status === "draft") &&
                          closure.pos_session_id && (
                            <Button
                              disabled={reopening}
                              size="sm"
                              title="Solo superadmin puede reabrir cajas cerradas"
                              variant="outline"
                              onClick={() =>
                                handleReopenCash(closure.pos_session_id || "")
                              }
                            >
                              <RotateCcw className="h-4 w-4 mr-1" />
                              Reabrir
                            </Button>
                          )}
                        <Link href={`/admin/cash-register/${closure.id}`}>
                          <Button
                            size="sm"
                            title={
                              closure.reopened_at
                                ? `Caja reabierta${closure.reopen_count && closure.reopen_count > 1 ? ` ${closure.reopen_count} veces` : ""}${closure.reopen_notes ? `. Notas: ${closure.reopen_notes}` : ""}`
                                : undefined
                            }
                            variant="outline"
                          >
                            <Eye className="h-4 w-4 mr-1" />
                            Ver
                            {closure.reopened_at && (
                              <RefreshCw className="h-3 w-3 ml-1 text-blue-600" />
                            )}
                          </Button>
                        </Link>
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          </div>
        )}

        {/* Pagination */}
        {!loading && closures.length > 0 && (
          <div className="mt-4 w-full min-w-0 overflow-x-auto">
            <Pagination
              className="flex-wrap gap-y-2"
              currentPage={closuresCurrentPage}
              itemsPerPage={closuresItemsPerPage}
              itemsPerPageOptions={[10, 20, 50, 100]}
              totalItems={closuresTotalCount}
              totalPages={Math.ceil(closuresTotalCount / closuresItemsPerPage)}
              onItemsPerPageChange={setClosuresItemsPerPage}
              onPageChange={setClosuresCurrentPage}
            />
          </div>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import { RefreshCw } from "lucide-react";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { formatCurrency } from "@/lib/utils";

interface OrderDialogProps {
  orderActionDialog: "cancel" | "delete" | null;
  selectedOrderForAction: unknown;
  orderActionReason: string;
  refundMethod: string;
  processingOrderAction: boolean;
  setOrderActionDialog: (v: "cancel" | "delete" | null) => void;
  setSelectedOrderForAction: (v: unknown) => void;
  setOrderActionReason: (v: string) => void;
  setRefundMethod: (v: string) => void;
  handleCancelOrder: (
    orderId: string,
    reason: string,
    method: string,
  ) => Promise<void>;
  handleDeleteOrder: (orderId: string) => Promise<void>;
}

export function CashRegisterOrderDialog(props: OrderDialogProps) {
  const {
    orderActionDialog,
    selectedOrderForAction,
    orderActionReason,
    refundMethod,
    processingOrderAction,
    setOrderActionDialog,
    setSelectedOrderForAction,
    setOrderActionReason,
    setRefundMethod,
    handleCancelOrder,
    handleDeleteOrder,
  } = props;

  return (
    <Dialog
      open={orderActionDialog !== null}
      onOpenChange={(open) => {
        if (!open) {
          setOrderActionDialog(null);
          setSelectedOrderForAction(null);
          setOrderActionReason("");
          setRefundMethod("cash");
        }
      }}
    >
      <DialogContent
        aria-describedby={orderActionDialog ? "order-action-desc" : undefined}
      >
        <DialogHeader>
          <DialogTitle>
            {orderActionDialog === "cancel" ? "Anular Venta" : "Eliminar Venta"}
          </DialogTitle>
          <DialogDescription id="order-action-desc">
            {orderActionDialog === "cancel"
              ? "Confirma la anulación de esta venta. Se creará una nota de crédito, se revertirá el stock y se actualizará la caja."
              : "Esta acción eliminará la venta permanentemente del sistema."}
          </DialogDescription>
        </DialogHeader>
        <div className="space-y-4">
          {selectedOrderForAction && (
            <>
              <div className="bg-gray-50 p-3 rounded-lg space-y-2">
                <p>
                  <span className="font-semibold">Orden:</span>{" "}
                  {selectedOrderForAction.order_number}
                </p>
                <p>
                  <span className="font-semibold">Monto:</span>{" "}
                  {formatCurrency(selectedOrderForAction.total_amount)}
                </p>
                <p>
                  <span className="font-semibold">Cliente:</span>{" "}
                  {selectedOrderForAction.customer_email}
                </p>
              </div>

              {orderActionDialog === "cancel" && (
                <>
                  <p className="text-sm text-gray-600">
                    ¿Estás seguro de que deseas anular esta venta? Se creará una
                    nota de crédito, se revertirá el stock y se actualizará la
                    caja.
                  </p>
                  <div>
                    <Label>Razón de la anulación *</Label>
                    <Input
                      placeholder="Ej: Cliente solicitó cambio de producto"
                      value={orderActionReason}
                      onChange={(e) => setOrderActionReason(e.target.value)}
                    />
                  </div>
                  <div>
                    <Label>Método de reembolso *</Label>
                    <Select
                      value={refundMethod}
                      onValueChange={setRefundMethod}
                    >
                      <SelectTrigger>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="cash">Efectivo</SelectItem>
                        <SelectItem value="debit">Débito</SelectItem>
                        <SelectItem value="credit">Crédito</SelectItem>
                        <SelectItem value="transfer">Transferencia</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                </>
              )}

              {orderActionDialog === "delete" && (
                <div className="bg-red-50 border border-red-200 p-3 rounded-lg space-y-2">
                  <p className="text-sm font-semibold text-red-800">
                    ⚠️ Acción Irreversible
                  </p>
                  <p className="text-sm text-red-700">
                    ¿Estás seguro de que deseas ELIMINAR esta venta
                    permanentemente? Esta acción no se puede deshacer.
                  </p>
                </div>
              )}
            </>
          )}
        </div>
        <DialogFooter>
          <Button
            disabled={processingOrderAction}
            variant="outline"
            onClick={() => {
              setOrderActionDialog(null);
              setSelectedOrderForAction(null);
              setOrderActionReason("");
              setRefundMethod("cash");
            }}
          >
            Cancelar
          </Button>
          <Button
            disabled={
              processingOrderAction ||
              (orderActionDialog === "cancel" && !orderActionReason)
            }
            variant={orderActionDialog === "delete" ? "destructive" : "default"}
            onClick={() => {
              if (orderActionDialog === "cancel") {
                handleCancelOrder(
                  selectedOrderForAction.id,
                  orderActionReason,
                  refundMethod,
                );
              } else if (orderActionDialog === "delete") {
                handleDeleteOrder(selectedOrderForAction.id);
              }
            }}
          >
            {processingOrderAction ? (
              <>
                <RefreshCw className="h-4 w-4 mr-2 animate-spin" />
                Procesando...
              </>
            ) : orderActionDialog === "delete" ? (
              "Eliminar Permanentemente"
            ) : (
              "Anular Venta"
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { RefreshCw } from "lucide-react";

