          <div className="flex items-center justify-between">
            <CardTitle>Ventas / Órdenes</CardTitle>
            <Button size="sm" variant="outline" onClick={fetchOrders}>
              <RefreshCw className="h-4 w-4 mr-2" />
              Actualizar
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          <OrderFilters
            fetchOrders={fetchOrders}
