            }}
            onDeleteOrder={(order) => {
              setSelectedOrderForAction(order);
              setOrderActionDialog("delete");
            }}
          />
        </CardContent>
      </Card>

      <CreditNotesSection
        creditNotes={creditNotes}
        loadingCreditNotes={loadingCreditNotes}
      />
    </>
  );
}

