                  <TableRow key={cn.id}>
                    <TableCell className="font-mono font-medium">{cn.credit_note_number}</TableCell>
                    <TableCell>
                      {cn.order_id ? (
                        <Link href={`/admin/cash-register/orders/${cn.order_id}`}>
                          <Button className="p-0 h-auto" variant="link">{cn.order_number || "Ver orden"}</Button>
                        </Link>
