                    <TableCell className="font-semibold text-red-600">-{formatCurrency(cn.amount)}</TableCell>
                    <TableCell>
                      <Badge variant="outline">
                        {cn.refund_method === "cash" ? "Efectivo"
                          : cn.refund_method === "debit" ? "Débito"
                          : cn.refund_method === "credit" ? "Crédito"
                          : "Transferencia"}
