                    </TableCell>
                    <TableCell className="max-w-xs truncate">{cn.reason}</TableCell>
                    <TableCell>{formatDateTime(cn.created_at)}</TableCell>
                    <TableCell>
                      {cn.order_id && (
                        <Link href={`/admin/cash-register/orders/${cn.order_id}`}>
                          <Button size="sm" variant="outline"><Eye className="h-4 w-4 mr-1" />Ver orden</Button>
                        </Link>
                      )}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import { ChevronDown, ChevronUp, Search } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { getTodayInTimezone } from "@/lib/utils/date-timezone";

interface Filters {
  payment_status: string;
  payment_method: string;
  date_from: string;
  date_to: string;
}

interface OrderFiltersProps {
  orderSearchTerm: string;
  orderFilters: Filters;
  orderProductFilter: string;
  orderFiltersExpanded: boolean;
  setOrderSearchTerm: (v: string) => void;
  setOrderFilters: (
    v: Filters | ((prev: Filters) => Filters),
  ) => void;
  setOrderProductFilter: (v: string) => void;
  setOrderFiltersExpanded: (v: boolean) => void;
  fetchOrders: () => Promise<void>;
}

export function OrderFilters({
  orderSearchTerm,
  orderFilters,
  orderProductFilter,
  orderFiltersExpanded,
  setOrderSearchTerm,
  setOrderFilters,
  setOrderProductFilter,
  setOrderFiltersExpanded,
  fetchOrders,
}: OrderFiltersProps) {
  return (
    <div className="mb-4 space-y-3">
      <div className="flex flex-col gap-3">
        <div className="flex flex-col sm:flex-row gap-2 sm:gap-3">
          <div className="flex-1 min-w-0">
            <Label className="text-xs sm:text-sm">Buscar</Label>
            <div className="relative">
              <Search className="absolute left-2 top-2.5 h-4 w-4 text-gray-400" />
              <Input
                className="pl-8 text-sm"
                placeholder="Orden, email, cliente..."
                value={orderSearchTerm}
                onChange={(e) => {
                  setOrderSearchTerm(e.target.value);
                  fetchOrders();
                }}
              />
            </div>
          </div>
          <Button
            className="md:hidden w-full sm:w-auto flex items-center justify-center gap-2"
            size="sm"
            type="button"
            variant="outline"
            onClick={() => setOrderFiltersExpanded(!orderFiltersExpanded)}
          >
            <Search className="h-4 w-4" />
            Filtros
            {orderFiltersExpanded ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
          </Button>
        </div>
        <div
          className={`grid gap-3 transition-all md:grid md:grid-cols-2 lg:grid-cols-5 ${
            orderFiltersExpanded ? "grid" : "hidden md:grid"
          }`}
        >
          <div className="md:col-span-2 lg:col-span-1">
            <Label className="text-xs sm:text-sm">Estado de Pago</Label>
            <Select
              value={orderFilters.payment_status}
              onValueChange={(v) => setOrderFilters({ ...orderFilters, payment_status: v })}
            >
              <SelectTrigger className="h-9 text-sm">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Todos</SelectItem>
                <SelectItem value="paid">Pagado</SelectItem>
                <SelectItem value="partial">Parcial</SelectItem>
                <SelectItem value="pending">Pendiente</SelectItem>
                <SelectItem value="cancelled">Anulado</SelectItem>
                <SelectItem value="refunded">Reembolsado</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div>
            <Label className="text-xs sm:text-sm">Método de Pago</Label>
            <Select
              value={orderFilters.payment_method}
              onValueChange={(v) => setOrderFilters({ ...orderFilters, payment_method: v })}
            >
              <SelectTrigger className="h-9 text-sm">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Todos</SelectItem>
                <SelectItem value="cash">Efectivo</SelectItem>
                <SelectItem value="debit">Débito</SelectItem>
                <SelectItem value="credit">Crédito</SelectItem>
                <SelectItem value="transfer">Transferencia</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div>
            <Label className="text-xs sm:text-sm">Producto</Label>
            <Input
              className="text-sm h-9"
              placeholder="Ej: Kit Limpieza"
              value={orderProductFilter}
              onChange={(e) => setOrderProductFilter(e.target.value)}
            />
          </div>
          <div>
            <Label className="text-xs sm:text-sm">Fecha Desde</Label>
            <Input
              className="text-sm h-9"
              type="date"
              value={orderFilters.date_from}
              onChange={(e) => setOrderFilters({ ...orderFilters, date_from: e.target.value })}
            />
          </div>
          <div>
            <Label className="text-xs sm:text-sm">Fecha Hasta</Label>
            <Input
              className="text-sm h-9"
              type="date"
              value={orderFilters.date_to}
              onChange={(e) => setOrderFilters({ ...orderFilters, date_to: e.target.value })}
            />
          </div>
          <div className="flex items-end">
            <Button
              className="h-9 text-xs"
              size="sm"
              type="button"
              variant="outline"
              onClick={() => {
                const today = getTodayInTimezone("America/Santiago");
                setOrderFilters((prev) => ({ ...prev, date_from: today, date_to: today }));
              }}
            >
              Hoy
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { Eye, RefreshCw, ShoppingBag } from "lucide-react";
import Link from "next/link";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Pagination } from "@/components/ui/pagination";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { formatCurrency, formatDateTime } from "@/lib/utils";

interface OrderRow {
  id: string;
  order_number: string;
  total_amount: number;
  status: string;
  payment_method_type?: string;
  payment_status?: string;
  created_at?: string;
  customer_name?: string;
  email?: string;
  customer_email?: string;
  branch_name?: string;
  sii_business_name?: string;
  billing_first_name?: string;
  billing_last_name?: string;
  customer_phone?: string;
  billing_phone?: string;
  shipping_phone?: string;
  sii_rut?: string;
  order_items?: Array<{ product_name?: string; sku?: string; quantity: number }>;
  order_payments?: Array<{ amount: number; payment_method: string }>;
}

interface OrdersTableProps {
  orders: OrderRow[];
  loadingOrders: boolean;
  ordersCurrentPage: number;
  ordersItemsPerPage: number;
  ordersTotalCount: number;
  isGlobalView: boolean;
  isSuperAdmin: boolean;
  onCancelOrder: (order: OrderRow) => void;
  onDeleteOrder: (order: OrderRow) => void;
  setOrdersCurrentPage: (v: number) => void;
  setOrdersItemsPerPage: (v: number) => void;
}

export function OrdersTable({
  orders,
  loadingOrders,
  ordersCurrentPage,
  ordersItemsPerPage,
  ordersTotalCount,
  isGlobalView,
  isSuperAdmin,
  onCancelOrder,
  onDeleteOrder,
  setOrdersCurrentPage,
  setOrdersItemsPerPage,
}: OrdersTableProps) {
  if (loadingOrders) {
    return (
      <div className="text-center py-12">
        <RefreshCw className="h-8 w-8 animate-spin text-epoch-primary mx-auto mb-4" />
        <p className="text-admin-text-tertiary">Cargando órdenes...</p>
      </div>
    );
  }

  if (orders.length === 0) {
    return (
      <div className="text-center py-12">
        <ShoppingBag className="h-12 w-12 text-admin-text-tertiary mx-auto mb-4" />
        <h3 className="text-lg font-semibold text-epoch-primary mb-2">No hay órdenes</h3>
        <p className="text-admin-text-tertiary">
          {isGlobalView
            ? "Seleccione una sucursal para ver sus órdenes"
            : "No se encontraron órdenes con los filtros seleccionados"}
        </p>
      </div>
    );
  }

  return (
    <>
      <div className="w-full min-w-0 overflow-x-auto -mx-4 px-4 md:mx-0 md:px-0">
        <Table className="min-w-[700px]">
          <TableHeader>
            <TableRow>
              <TableHead>Número</TableHead>
              <TableHead>Cliente</TableHead>
              <TableHead>Productos</TableHead>
              <TableHead>Total</TableHead>
              <TableHead>Método de Pago</TableHead>
              <TableHead>Estado de Pago</TableHead>
              <TableHead>Fecha</TableHead>
              <TableHead>Acciones</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {orders.map((order: OrderRow) => (
              <TableRow key={order.id}>
                <TableCell className="font-medium">{order.order_number}</TableCell>
                <TableCell>
                  <div className="text-sm">
                    <div className="font-medium">
                      {order.customer_name ||
                        order.sii_business_name ||
                        (order.billing_first_name && order.billing_last_name
                          ? `${order.billing_first_name} ${order.billing_last_name}`.trim()
                          : order.customer_email || "Cliente no registrado")}
                    </div>
                    {order.sii_rut && (
                      <div className="text-xs text-admin-text-tertiary font-mono">{order.sii_rut}</div>
                    )}
                    {(order.customer_name || order.sii_business_name || (order.billing_first_name && order.billing_last_name)) && (
                      <>
                        {order.customer_email && <div className="text-xs text-admin-text-tertiary">{order.customer_email}</div>}
                        {(order.customer_phone || order.billing_phone || order.shipping_phone) && (
                          <div className="text-xs text-admin-text-tertiary">
                            {order.customer_phone || order.billing_phone || order.shipping_phone}
                          </div>
                        )}
                      </>
                    )}
                  </div>
                </TableCell>
                <TableCell>
                  <div className="max-w-xs">
                    {order.order_items && order.order_items.length > 0 ? (
                      <>
                        {order.order_items.slice(0, 2).map((item: { product_name?: string; sku?: string; quantity: number }, idx: number) => (
                          <div className="text-sm" key={idx}>
                            <span className="font-medium">{item.quantity}x</span>{" "}
                            <span>{item.product_name || "Producto"}</span>
                            {item.sku && <span className="text-xs text-admin-text-tertiary ml-1">({item.sku})</span>}
                          </div>
                        ))}
                        {order.order_items.length > 2 && (
                          <div className="text-xs text-gray-500">+{order.order_items.length - 2} más</div>
                        )}
                      </>
                    ) : (
                      <span className="text-sm text-admin-text-tertiary">Sin productos</span>
                    )}
                  </div>
                </TableCell>
                <TableCell>
                  <div className="font-semibold">{formatCurrency(order.total_amount)}</div>
                  {(() => {
                    const paid =
                      order.order_payments?.reduce(
                        (sum: number, p: { amount: number; payment_method: string }) => sum + Number(p.amount || 0), 0,
                      ) || 0;
                    const pending = Math.max(0, order.total_amount - paid);
                    if (pending > 0 && order.status !== "cancelled") {
                      return <div className="text-xs text-red-600 font-medium">Pdte: {formatCurrency(pending)}</div>;
                    }
                    return null;
                  })()}
                </TableCell>
                <TableCell>
                  {(() => {
                    const methodsFromPayments =
                      order.order_payments?.map((p) => p.payment_method) || [];
                    const uniqueMethods = Array.from(new Set(methodsFromPayments));
                    if (uniqueMethods.length > 0) {
                      return (
                        <div className="flex flex-wrap gap-1">
                          {uniqueMethods.map((method, idx: number) => (
                            <Badge className="text-[10px] px-1 h-5 capitalize" key={idx} variant="outline">
                              {method === "cash" ? "Efectivo" : method === "debit" ? "Débito" : method === "credit" ? "Crédito" : method === "transfer" ? "Transf." : method}
                            </Badge>
                          ))}
                        </div>
                      );
                    }
                    const pm = order.payment_method_type;
                    const pmMap: Record<string, string> = {
                      cash: "Efectivo", debit_card: "Débito", credit_card: "Crédito",
                      transfer: "Transf.", deposit: "Abono", installments: "Cuotas",
                    };
                    return <Badge className="text-[10px] px-1 h-5" variant="outline">{pm ? pmMap[pm] || pm : "N/A"}</Badge>;
                  })()}
                </TableCell>
                <TableCell>
                  <Badge
                    variant={
                      order.status === "cancelled" ? "destructive"
                      : order.payment_status === "paid" ? "default"
                      : order.payment_status === "partial" ? "secondary"
                      : order.payment_status === "refunded" ? "destructive"
                      : "outline"
                    }
                  >
                    {order.status === "cancelled" ? "Anulado"
                      : order.payment_status === "paid" ? "Pagado"
                      : order.payment_status === "partial" ? "Parcial"
                      : order.payment_status === "pending" ? "Pendiente"
                      : order.payment_status === "refunded" ? "Reembolsado" : ""}
                  </Badge>
                </TableCell>
                <TableCell>{formatDateTime(order.created_at)}</TableCell>
                <TableCell>
                  <div className="flex items-center gap-2">
                    <Link href={`/admin/cash-register/orders/${order.id}`}>
                      <Button size="sm" variant="outline">
                        <Eye className="h-4 w-4 mr-1" />Ver
                      </Button>
                    </Link>
                    {isSuperAdmin && order.status !== "cancelled" && (
                      <Button className="text-red-600 hover:text-red-700" size="sm" variant="outline"
                        onClick={() => onCancelOrder(order)}
                      >Anular</Button>
                    )}
                    {isSuperAdmin && order.status === "cancelled" && (
                      <Button className="text-red-600 hover:text-red-700" size="sm" variant="outline"
                        onClick={() => onDeleteOrder(order)}
                      >Eliminar</Button>
                    )}
                  </div>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </div>
      {orders.length > 0 && (
        <div className="mt-4 w-full min-w-0 overflow-x-auto">
          <Pagination
            className="flex-wrap gap-y-2"
            currentPage={ordersCurrentPage}
            itemsPerPage={ordersItemsPerPage}
            itemsPerPageOptions={[10, 20, 50, 100]}
            totalItems={ordersTotalCount}
            totalPages={Math.ceil(ordersTotalCount / ordersItemsPerPage)}
            onItemsPerPageChange={setOrdersItemsPerPage}
            onPageChange={setOrdersCurrentPage}
          />
        </div>
      )}
    </>
  );
}

/**
 * Payment-related utility functions for the cash register page.
 *
 * Extracted from page.tsx to enable independent testing and reuse.
 * Contains: payment method formatting, closure status badge config,
 * cash difference computation, and filter map constants.
 */

// ponytail: static map — add new payment methods here as they're needed
export const PAYMENT_METHOD_FILTER_MAP: Record<string, string[]> = {
  cash: ["cash"],
  debit: ["debit", "debit_card"],
  credit: ["credit", "credit_card"],
  transfer: ["transfer"],
};

export interface StatusBadgeInfo {
  variant: string;
  label: string;
}

/** Static config for closure status display labels and badge variants. */
export const STATUS_BADGE_CONFIG: Record<string, StatusBadgeInfo> = {
  draft: { variant: "secondary", label: "Abierta" },
  confirmed: { variant: "default", label: "Confirmado" },
  reviewed: { variant: "secondary", label: "Revisado" },
  closed: { variant: "default", label: "Cerrada" },
  reopened: { variant: "secondary", label: "Abierta" },
};

/**
 * Resolves the display status for a closure based on its current state
 * and whether it has an active POS session.
 */
export function resolveClosureStatus(
  status: string,
  posSessionId?: string | null,
): StatusBadgeInfo {
  if (status === "closed") {
    // closed always shows "Cerrada", even if reopened historically
    return STATUS_BADGE_CONFIG.closed;
  }
  if (status === "draft" && posSessionId) {
    // draft with session = currently open
    return STATUS_BADGE_CONFIG.reopened;
  }
  return (
    STATUS_BADGE_CONFIG[status] || {
      variant: "outline",
      label: status,
    }
  );
}

/** Maps payment method codes to human-readable Spanish labels. */
export function formatPaymentMethod(method: string): string {
  const map: Record<string, string> = {
    cash: "Efectivo",
    debit: "Débito",
    credit: "Crédito",
    transfer: "Transf.",
    deposit: "Abono",
    installments: "Cuotas",
  };
  return map[method] || method;
}

/**
 * Computes the cash difference between actual physical cash and expected cash.
 * Returns null when actualCash hasn't been entered yet.
 */
export function computeCashDifference(
  actualCash: number | null | undefined,
  expectedCash: number,
): number | null {
  if (actualCash === null || actualCash === undefined) return null;
  return actualCash - (expectedCash || 0);
}

