      {/* Header */}
      <div className="space-y-4">
        <div>
          <h1 className="text-2xl sm:text-3xl font-bold text-epoch-primary">
            {h.isOperativoMode && h.fieldOperation
              ? `Caja - ${h.fieldOperation.name}`
