/**
 * useCashRegisterMovements — movements, daily summary, credit notes.
 *
 * Extracted from useCashRegister.ts. Pure extraction — no behavioral changes.
 */

"use client";

import { useState } from "react";
import { toast } from "sonner";

import { appLogger } from '@/lib/logger';

import type { DailySummary, Movement } from "./cashRegister.types";

export function useCashRegisterMovements(effectiveHeaders: Record<string, string>) {
  const [dailySummary, setDailySummary] = useState<DailySummary | null>(null);
  const [loadingSummary, setLoadingSummary] = useState(false);
  const [movements, setMovements] = useState<Movement[]>([]);
  const [loadingMovements, setLoadingMovements] = useState(false);
  const [movementFilter, setMovementFilter] = useState<string>("all");
  const [movementTypeFilter, setMovementTypeFilter] = useState<string>("all");
  const [creditNotes, setCreditNotes] = useState<unknown[]>([]);
  const [loadingCreditNotes, setLoadingCreditNotes] = useState(false);

  const fetchDailySummary = async () => {
    setLoadingSummary(true);
    try {
      const { getTodayInTimezone } = await import("@/lib/utils/date-timezone");
      const today = getTodayInTimezone("America/Santiago");
      const response = await fetch(
        `/api/admin/cash-register/close?date=${today}`,
        { headers: effectiveHeaders as HeadersInit },
      );
      if (response.ok) {
        const data = await response.json();
        setDailySummary(data.summary);
        if (data.previous_closure) {
          return {
            summary: data.summary,
            previousClosure: data.previous_closure,
          };
        }
        return { summary: data.summary, previousClosure: null };
      } else {
        const error = await response.json();
        toast.error(error.error || "Error al cargar resumen del día");
      }
    } catch (error: unknown) {
      appLogger.error("Error fetching daily summary:", error);
      toast.error("Error al cargar resumen del día");
    } finally {
      setLoadingSummary(false);
    }
    return null;
  };

  const fetchMovements = async (sessionId: string) => {
    if (!sessionId) return;

    setLoadingMovements(true);
    try {
      const response = await fetch(
        `/api/admin/cash-register/session-movements?session_id=${sessionId}`,
        { headers: effectiveHeaders as HeadersInit, credentials: "include" },
      );

      if (response.ok) {
        const data = await response.json();
        setMovements(data.movements || []);
      } else {
        const errorData = await response.json();
        appLogger.error("Error fetching movements:", errorData);
      }
    } catch (error: unknown) {
      appLogger.error("Error fetching movements:", error);
    } finally {
      setLoadingMovements(false);
    }
  };

  const fetchCreditNotes = async () => {
    setLoadingCreditNotes(true);
    try {
      const { buildCreditNotesDateRange } = await import("./cashOpsUtils");
      const { date_from, date_to } = buildCreditNotesDateRange();
      const params = new URLSearchParams({ date_from, date_to, limit: "50", offset: "0" });
      const response = await fetch(`/api/admin/credit-notes?${params}`, {
        headers: effectiveHeaders as HeadersInit,
      });
      if (response.ok) {
        const data = await response.json();
        setCreditNotes(data.credit_notes || []);
      }
    } catch (err) {
      appLogger.error("Error fetching credit notes:", err);
    } finally {
      setLoadingCreditNotes(false);
    }
  };

  return {
    dailySummary,
    setDailySummary,
    loadingSummary,
    movements,
    setMovements,
    loadingMovements,
    movementFilter,
    setMovementFilter,
    movementTypeFilter,
    setMovementTypeFilter,
    creditNotes,
    setCreditNotes,
    loadingCreditNotes,
    fetchDailySummary,
    fetchMovements,
    fetchCreditNotes,
  };
}

/**
 * useCashRegisterOrders — orders and closures listing with actions.
 *
 * Extracted from useCashRegister.ts. Pure extraction — no behavioral changes.
 */

"use client";

import { useState } from "react";
import { toast } from "sonner";

import { extractDataFromResponse, extractTotalFromResponse } from "@/lib/api/response-helpers";
import { appLogger } from '@/lib/logger';

import { buildClosureParams, buildOrderParams, getTodayChileDate } from "./cashOpsUtils";
import { PAYMENT_METHOD_FILTER_MAP } from "./cashPaymentUtils";
import type { CashClosure } from "./cashRegister.types";

export function useCashRegisterOrders(
  effectiveHeaders: Record<string, string>,
  fieldOperationIdFromUrl?: string | null,
) {
  // Closures
  const [closures, setClosures] = useState<CashClosure[]>([]);
  const [loading, setLoading] = useState(true);
  const [closuresCurrentPage, setClosuresCurrentPage] = useState(1);
  const [closuresItemsPerPage, setClosuresItemsPerPage] = useState(20);
  const [closuresTotalCount, setClosuresTotalCount] = useState(0);

  // Orders
  const [orders, setOrders] = useState<unknown[]>([]);
  const [loadingOrders, setLoadingOrders] = useState(false);
  const [ordersTab, setOrdersTab] = useState(false);
  const [orderFilters, setOrderFilters] = useState(() => ({
    payment_status: "all",
    payment_method: "all",
    date_from: getTodayChileDate(),
    date_to: getTodayChileDate(),
  }));
  const [orderSearchTerm, setOrderSearchTerm] = useState("");
  const [orderProductFilter, setOrderProductFilter] = useState("");
  const [selectedOrderForAction, setSelectedOrderForAction] = useState<unknown>(null);
  const [orderActionDialog, setOrderActionDialog] = useState<"cancel" | "delete" | null>(null);
  const [orderActionReason, setOrderActionReason] = useState("");
  const [refundMethod, setRefundMethod] = useState("cash");
  const [processingOrderAction, setProcessingOrderAction] = useState(false);
  const [ordersCurrentPage, setOrdersCurrentPage] = useState(1);
  const [ordersItemsPerPage, setOrdersItemsPerPage] = useState(20);
  const [ordersTotalCount, setOrdersTotalCount] = useState(0);
  const [orderFiltersExpanded, setOrderFiltersExpanded] = useState(false);

  // Fetch closures
  const fetchClosures = async (page: number, perPage: number) => {
    setLoading(true);
    try {
      const params = buildClosureParams(page, perPage, fieldOperationIdFromUrl ?? undefined);
      const response = await fetch(`/api/admin/cash-register/closures?${params}`, {
        headers: effectiveHeaders as HeadersInit,
      });
      if (response.ok) {
        const data = await response.json();
        setClosures(data.closures || []);
        setClosuresTotalCount(data.pagination?.total || 0);
      } else {
        const error = await response.json();
        toast.error(error.error || "Error al cargar cierres de caja");
      }
    } catch (error: unknown) {
      appLogger.error("Error fetching closures:", error);
      toast.error("Error al cargar cierres de caja");
    } finally {
      setLoading(false);
    }
  };

  // Fetch orders
  const fetchOrders = async () => {
    setLoadingOrders(true);
    try {
      const params = buildOrderParams(orderFilters, ordersCurrentPage, ordersItemsPerPage);
      const response = await fetch(`/api/admin/orders?${params}`, {
        headers: effectiveHeaders as HeadersInit,
      });

      if (response.ok) {
        const data = await response.json();
        let filteredOrders = extractDataFromResponse(data) as Record<string, unknown>[];

        // Apply search filter (client-side)
        if (orderSearchTerm) {
          const term = orderSearchTerm.toLowerCase();
          filteredOrders = filteredOrders.filter(
            (order) =>
              ((order.order_number as string) || "").toLowerCase().includes(term) ||
              ((order.customer_email as string) || "").toLowerCase().includes(term) ||
              ((order.customer_name as string) || "").toLowerCase().includes(term) ||
              ((order.sii_business_name as string) || "").toLowerCase().includes(term),
          );
        }

        // Filter by payment method
        if (orderFilters.payment_method !== "all") {
          const allowed = PAYMENT_METHOD_FILTER_MAP[orderFilters.payment_method] || [];
          filteredOrders = filteredOrders.filter((order) => {
            const payments = (order.order_payments || []) as Array<Record<string, unknown>>;
            const hasMatch = payments.some((p) =>
              allowed.includes(((p as Record<string, unknown>).payment_method as string || "").toLowerCase()),
            );
            if (hasMatch) return true;
            const mp = ((order.mp_payment_method as string) || "").toLowerCase();
            return allowed.some((a: string) => mp.includes(a.replace("_", "")));
          });
        }

        // Filter by product name
        if (orderProductFilter.trim()) {
          const term = orderProductFilter.trim().toLowerCase();
          filteredOrders = filteredOrders.filter((order) => {
            const items = (order.order_items || []) as Array<Record<string, unknown>>;
            return items.some(
              (item) =>
                ((item as Record<string, unknown>).product_name as string || "").toLowerCase().includes(term) ||
                ((item as Record<string, unknown>).variant_title as string || "").toLowerCase().includes(term),
            );
          });
        }

        setOrders(filteredOrders);
        setOrdersTotalCount(extractTotalFromResponse(data) || filteredOrders.length);
      } else {
        const error = await response.json();
        toast.error(error.error || "Error al cargar órdenes");
      }
    } catch (error: unknown) {
      appLogger.error("Error fetching orders:", error);
      toast.error("Error al cargar órdenes");
    } finally {
      setLoadingOrders(false);
    }
  };

  const handleCancelOrder = async (
    orderId: string,
    reason: string,
    method: string,
    onSuccess?: () => void,
  ) => {
    setProcessingOrderAction(true);
    try {
      const response = await fetch(`/api/admin/orders/${orderId}/cancel`, {
        method: "POST",
        headers: { "Content-Type": "application/json", ...effectiveHeaders } as HeadersInit,
        body: JSON.stringify({ reason, refund_method: method }),
      });

      if (response.ok) {
        toast.success("Venta anulada correctamente");
        setOrderActionDialog(null);
        setSelectedOrderForAction(null);
        setOrderActionReason("");
        setRefundMethod("cash");
        await fetchOrders();
        if (onSuccess) onSuccess();
      } else {
        let msg = "Error al anular venta";
        try {
          const errData = await response.json();
          msg = errData.details
            ? `${errData.error || "Error"}: ${errData.details}`
            : errData.error || msg;
        } catch (_) {
          msg = `Error ${response.status}: ${response.statusText}`;
        }
        toast.error(msg);
      }
    } catch (error: unknown) {
      appLogger.error("Error cancelling order:", error);
      toast.error("Error al anular venta");
    } finally {
      setProcessingOrderAction(false);
    }
  };

  const handleDeleteOrder = async (orderId: string) => {
    setProcessingOrderAction(true);
    try {
      const response = await fetch(`/api/admin/orders/${orderId}/delete`, {
        method: "DELETE",
        headers: effectiveHeaders as HeadersInit,
      });

      if (response.ok) {
        toast.success("Venta eliminada correctamente");
        setOrderActionDialog(null);
        setSelectedOrderForAction(null);
        await fetchOrders();
      } else {
        const error = await response.json();
        toast.error(error.error || "Error al eliminar venta");
      }
    } catch (error: unknown) {
      appLogger.error("Error deleting order:", error);
      toast.error("Error al eliminar venta");
    } finally {
      setProcessingOrderAction(false);
    }
  };

  return {
    closures,
    setClosures,
    loading,
    setLoading,
    closuresCurrentPage,
    setClosuresCurrentPage,
    closuresItemsPerPage,
    setClosuresItemsPerPage,
    closuresTotalCount,
    setClosuresTotalCount,
    orders,
    setOrders,
    loadingOrders,
    setLoadingOrders,
    ordersTab,
    setOrdersTab,
    orderFilters,
    setOrderFilters,
    orderSearchTerm,
    setOrderSearchTerm,
    orderProductFilter,
    setOrderProductFilter,
    selectedOrderForAction,
    setSelectedOrderForAction,
    orderActionDialog,
    setOrderActionDialog,
    orderActionReason,
    setOrderActionReason,
    refundMethod,
    setRefundMethod,
    processingOrderAction,
    setProcessingOrderAction,
    ordersCurrentPage,
    setOrdersCurrentPage,
    ordersItemsPerPage,
    setOrdersItemsPerPage,
    ordersTotalCount,
    setOrdersTotalCount,
    orderFiltersExpanded,
    setOrderFiltersExpanded,
    fetchClosures,
    fetchOrders,
    handleCancelOrder,
    handleDeleteOrder,
  };
}

/**
 * useCashRegisterSession — cash register open/close/reopen state and actions.
 *
 * Extracted from useCashRegister.ts. Pure extraction — no behavioral changes.
 */

"use client";

import { useEffect, useState } from "react";
import { toast } from "sonner";

import { appLogger } from '@/lib/logger';


interface FieldOperation {
  id: string;
  name: string;
  branch_id: string;
}

interface UseCashRegisterSessionParams {
  fieldOperationIdFromUrl: string | null;
  effectiveBranchId: string | null;
  effectiveHeaders: Record<string, string>;
  isSuperAdmin: boolean;
  isGlobalView: boolean;
  onSessionChange: () => void;
}

export function useCashRegisterSession({
  fieldOperationIdFromUrl,
  effectiveBranchId,
  effectiveHeaders,
  isSuperAdmin,
  isGlobalView,
  onSessionChange,
}: UseCashRegisterSessionParams) {
  const [fieldOperation, setFieldOperation] = useState<FieldOperation | null>(null);
  const [loadingFieldOperation, setLoadingFieldOperation] = useState(false);
  const [isCashOpen, setIsCashOpen] = useState(false);
  const [checkingCashStatus, setCheckingCashStatus] = useState(true);
  const [openingCash, setOpeningCash] = useState(0);
  const [openingCashInput, setOpeningCashInput] = useState("");
  const [openingCashRegister, setOpeningCashRegister] = useState(false);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [showCloseDialog, setShowCloseDialog] = useState(false);
  const [closing, setClosing] = useState(false);
  const [reopening, setReopening] = useState(false);
  const [actualCash, setActualCash] = useState<number | null>(null);
  const [cardMachineDebit, setCardMachineDebit] = useState(0);
  const [cardMachineCredit, setCardMachineCredit] = useState(0);
  const [transferTotal, setTransferTotal] = useState(0);
  const [notes, setNotes] = useState("");
  const [discrepancies, setDiscrepancies] = useState("");

  // Fetch field operation
  useEffect(() => {
    if (!fieldOperationIdFromUrl) {
      setFieldOperation(null);
      return;
    }
    setLoadingFieldOperation(true);
    fetch(`/api/admin/field-operations/${fieldOperationIdFromUrl}`)
      .then((res) => (res.ok ? res.json() : null))
      .then((data: unknown) => {
        const payload = (data as Record<string, unknown>)?.data ?? data;
        const op = (payload as Record<string, unknown>)?.fieldOperation ?? payload;
        if ((op as Record<string, unknown>)?.id && (op as Record<string, unknown>)?.branch_id) {
          setFieldOperation({
            id: (op as Record<string, unknown>).id as string,
            name: ((op as Record<string, unknown>).name as string) || "Operativo",
            branch_id: (op as Record<string, unknown>).branch_id as string,
          });
        } else {
          setFieldOperation(null);
        }
      })
      .catch(() => setFieldOperation(null))
      .finally(() => setLoadingFieldOperation(false));
  }, [fieldOperationIdFromUrl]);

  const checkCashStatus = async () => {
    if (isGlobalView) {
      setCheckingCashStatus(false);
      return;
    }
    setCheckingCashStatus(true);
    try {
      const response = await fetch("/api/admin/cash-register/open", {
        headers: effectiveHeaders as HeadersInit,
      });
      if (response.ok) {
        const result = await response.json();
        const data = result.data || result;
        setIsCashOpen(data.isOpen);
        if (data.session) {
          setOpeningCash(data.session.opening_cash_amount || 0);
          setCurrentSessionId(data.session.id);
        } else {
          setCurrentSessionId(null);
        }
      }
    } catch (error: unknown) {
      appLogger.error("Error checking cash status:", error);
    } finally {
      setCheckingCashStatus(false);
    }
  };

  const handleOpenCashRegister = async () => {
    if (!openingCashInput || parseFloat(openingCashInput) < 0) {
      toast.error("Debe ingresar un monto inicial válido");
      return;
    }
    setOpeningCashRegister(true);
    try {
      const body: Record<string, unknown> = {
        opening_cash_amount: parseFloat(openingCashInput),
      };
      if (fieldOperationIdFromUrl) body.field_operation_id = fieldOperationIdFromUrl;

      const response = await fetch("/api/admin/cash-register/open", {
        method: "POST",
        headers: { "Content-Type": "application/json", ...effectiveHeaders } as HeadersInit,
        body: JSON.stringify(body),
      });

      if (response.ok) {
        const result = await response.json();
        const data = result.data || result;
        toast.success("Caja abierta exitosamente");
        setIsCashOpen(true);
        setOpeningCash(data.session?.opening_cash_amount || 0);
        setOpeningCashInput("");
        await checkCashStatus();
      } else {
        const error = await response.json();
        toast.error(error.error || "Error al abrir la caja");
      }
    } catch (error: unknown) {
      appLogger.error("Error opening cash register:", error);
      toast.error("Error al abrir la caja");
    } finally {
      setOpeningCashRegister(false);
    }
  };

  const fetchCurrentSessionId = async () => {
    try {
      const response = await fetch("/api/admin/cash-register/open", {
        headers: effectiveHeaders as HeadersInit,
      });
      if (response.ok) {
        const data = await response.json();
        if (data.session?.id) {
          setCurrentSessionId(data.session.id);
        }
      }
    } catch (error: unknown) {
      appLogger.error("Error fetching session ID:", error);
    }
  };

  const handleCloseCashRegisterCore = async (
    dailySummary: { expected_cash?: number; opening_cash_amount?: number } | null,
    onSuccess: () => void,
  ) => {
    if (!dailySummary) {
      toast.error("No hay datos del día para cerrar");
      return;
    }
    setClosing(true);
    try {
      if (actualCash === null || actualCash === undefined || actualCash < 0) {
        toast.error("Debe ingresar el monto de efectivo físico contado");
        setClosing(false);
        return;
      }
      if (isNaN(Number(actualCash)) || Number(actualCash) < 0) {
        toast.error("El monto de efectivo físico contado debe ser 0 o mayor");
        setClosing(false);
        return;
      }

      const { getTodayInTimezone } = await import("@/lib/utils/date-timezone");
      const { buildCloseCashBody } = await import("./cashOpsUtils");
      const today = getTodayInTimezone("America/Santiago");
      const actualCashValue = Number(actualCash);

      const closeBody = buildCloseCashBody({
        closure_date: `${today}T00:00:00`,
        opening_cash_amount: openingCash,
        actual_cash: actualCashValue,
        card_machine_debit_total: cardMachineDebit,
        card_machine_credit_total: cardMachineCredit,
        notes: notes || null,
        discrepancies: discrepancies || null,
        field_operation_id: fieldOperationIdFromUrl ?? undefined,
      });

      const response = await fetch("/api/admin/cash-register/close", {
        method: "POST",
        headers: { "Content-Type": "application/json", ...effectiveHeaders } as HeadersInit,
        body: JSON.stringify(closeBody),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(
          error.details
            ? `${error.error || "Error al cerrar la caja"}: ${error.details}`
            : error.error || "Error al cerrar la caja",
        );
      }

      toast.success("Caja cerrada exitosamente");
      setShowCloseDialog(false);
      onSuccess();

      setOpeningCash(0);
      setActualCash(null);
      setCardMachineDebit(0);
      setCardMachineCredit(0);
      setTransferTotal(0);
      setNotes("");
      setDiscrepancies("");
    } catch (error: unknown) {
      appLogger.error("Error closing cash register:", error);
      const err = error as Error;
      toast.error(err.message || "Error al cerrar la caja");
    } finally {
      setClosing(false);
    }
  };

  const handleReopenCash = async (sessionId: string) => {
    if (!isSuperAdmin) {
      toast.error("Solo superadmin puede reabrir cajas");
      return;
    }
    setReopening(true);
    try {
      const response = await fetch("/api/admin/cash-register/reopen", {
        method: "POST",
        headers: { "Content-Type": "application/json", ...effectiveHeaders } as HeadersInit,
        body: JSON.stringify({ session_id: sessionId }),
      });

      if (response.ok) {
        toast.success("Caja reabierta correctamente");
        await checkCashStatus();
        onSessionChange();
      } else {
        const error = await response.json();
        toast.error(error.error || "Error al reabrir la caja");
      }
    } catch (error: unknown) {
      appLogger.error("Error reopening cash register:", error);
      toast.error("Error al reabrir la caja");
    } finally {
      setReopening(false);
    }
  };

  return {
    fieldOperation,
    loadingFieldOperation,
    isCashOpen,
    checkingCashStatus,
    openingCash,
    setOpeningCash,
