      {/* Monthly Spending Chart */}
      {customer.analytics?.monthlySpending &&
        customer.analytics.monthlySpending.length > 0 && (
          <Card className="bg-admin-bg-tertiary shadow-[0_1px_3px_rgba(0,0,0,0.3)]">
