function getSegmentBadge(segment: string) {
  type BadgeVariant =
    | "default"
    | "secondary"
    | "outline"
    | "destructive"
    | "healty"
    | null
    | undefined;
  const variants: Record<
    string,
    {
      variant: BadgeVariant;
      label: string;
      icon: React.ComponentType<{ className?: string }>;
      color: string;
    }
  > = {
    new: {
      variant: "secondary",
      label: "Nuevo",
      icon: Star,
      color: "text-yellow-600",
    },
    "first-time": {
      variant: "outline",
      label: "Primera Compra",
      icon: Package,
      color: "text-blue-600",
    },
    regular: {
      variant: "default",
      label: "Regular",
      icon: CheckCircle,
      color: "text-green-600",
    },
    vip: {
      variant: "secondary",
      label: "VIP",
      icon: Crown,
      color: "text-purple-600",
    },
    "at-risk": {
      variant: "destructive",
      label: "En Riesgo",
      icon: AlertTriangle,
      color: "text-red-600",
    },
  };

  const config = variants[segment] || variants["new"];
  const Icon = config.icon;

  return (
    <Badge className="flex items-center gap-1" variant={config.variant}>
      <Icon className="h-3 w-3" />
      {config.label}
    </Badge>
  );
}

export function CustomerHeader({ customer, onBack }: CustomerHeaderProps) {
  const customerName =
    customer.first_name && customer.last_name
