"use client";

import { AlertTriangle, ArrowLeft, Save } from "lucide-react";
import { useParams, useRouter, useSearchParams } from "next/navigation";
import { useEffect, useState } from "react";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { FormFieldActionsExtended } from "@/components/ui/FormField";
import { useForm } from "@/hooks/useForm";
import { customerService } from "@/lib/api/services";
import { handleApiError } from "@/lib/api/services/errorService";
import {
  error as notifyError,
  success,
} from "@/lib/api/services/notificationService";
import { appLogger } from '@/lib/logger';
import { completeRUTIfNeeded, formatRUT } from "@/lib/utils/rut";
import { customerEditSchema } from "@/lib/validation/formValidation";

import { CustomerEditForm } from "./_components/CustomerEditForm";

interface FormCustomerData {
  first_name: string;
  last_name: string;
  email: string;
  phone: string;
  rut: string;
  address_line_1: string;
  address_line_2: string;
  city: string;
  state: string;
  postal_code: string;
  country: string;
  notes: string;
}

export default function CustomerEditPage() {
  const router = useRouter();
  const params = useParams();
  const searchParams = useSearchParams();
  const customerId = params.id as string;
  const returnTo = searchParams.get("return_to");

  const [customer, setCustomer] = useState<FormCustomerData | null>(null);
  const [loading, setLoading] = useState(true);
  const [fetchError, setFetchError] = useState<string | null>(null);

  const form = useForm({
    validationSchema: customerEditSchema,
    defaultValues: {
      first_name: "",
      last_name: "",
      email: "",
      phone: "",
      rut: "",
      address_line_1: "",
      address_line_2: "",
      city: "",
      state: "",
      postal_code: "",
      country: "Chile",
      notes: "",
    },
    onSubmit: async (data) => {
      const result = await customerService.updateCustomer(customerId, data);
      return result;
    },
    onSuccess: () => {
      success("Cliente actualizado exitosamente");
      router.push(returnTo || "/admin/customers");
    },
    onError: (err) => {
      const standardError = handleApiError(err, "CustomerEditPage");
      notifyError(standardError.userMessage);
    },
  });

  useEffect(() => {
    if (customerId) {
      fetchCustomer();
    }
  }, [customerId]);

  const fetchCustomer = async () => {
    try {
      setLoading(true);
      const customerData = await customerService.getCustomer(customerId);

      const rawRut = (customerData.rut || "").trim();
      const normalizedRut = rawRut
        ? formatRUT(completeRUTIfNeeded(rawRut) || rawRut)
        : "";

      const formData: FormCustomerData = {
        first_name: customerData.first_name || "",
        last_name: customerData.last_name || "",
        email: customerData.email || "",
        phone: customerData.phone || "",
        rut: normalizedRut,
        address_line_1: (customerData as unknown).address_line_1 || "",
        address_line_2: (customerData as unknown).address_line_2 || "",
        city: (customerData as unknown).city || "",
        state: (customerData as unknown).state || "",
        postal_code: (customerData as unknown).postal_code || "",
        country: (customerData as unknown).country || "Chile",
        notes: (customerData as unknown).notes || "",
      };

      setCustomer(formData);
      form.setFieldValues(formData);
      setFetchError(null);
    } catch (err) {
      appLogger.error("Error fetching customer:", err);
      setFetchError(
        err instanceof Error ? err.message : "Unknown error occurred",
      );
    } finally {
      setLoading(false);
    }
  };

  const handleRUTChange = (value: string) => {
    const formatted = formatRUT(value);
    form.setValue("rut", formatted);
  };

  const handleRUTBlur = (value: string) => {
    const formatted = formatRUT(value);
    if (formatted !== value) {
      form.setValue("rut", formatted);
    }
  };

  if (loading) {
    return (
      <div className="space-y-6">
        <div className="flex items-center space-x-4">
          <Button size="sm" variant="outline">
            <ArrowLeft className="h-4 w-4" />
          </Button>
          <div>
            <h1 className="text-3xl font-bold text-admin-text-primary">
              Cargando cliente...
            </h1>
            <p className="text-admin-text-tertiary">
              Obteniendo información del cliente
            </p>
          </div>
        </div>
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {[...Array(4)].map((_, i) => (
            <Card className="animate-pulse" key={i}>
              <CardContent className="p-6">
                <div className="h-4 bg-gray-200 rounded w-3/4 mb-2" />
                <div className="h-8 bg-gray-200 rounded w-1/2" />
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    );
  }

  if (fetchError || !customer) {
    return (
      <div className="space-y-6">
        <div className="flex items-center space-x-4">
          <Button size="sm" variant="outline" onClick={() => router.back()}>
            <ArrowLeft className="h-4 w-4" />
          </Button>
          <div>
            <h1 className="text-3xl font-bold text-admin-text-primary">
              Error
            </h1>
            <p className="text-admin-text-tertiary">
              No se pudo cargar la información del cliente
            </p>
          </div>
        </div>
        <Card>
          <CardContent className="text-center py-16">
            <AlertTriangle className="h-12 w-12 text-red-500 mx-auto mb-4" />
            <h3 className="text-lg font-semibold text-red-700 mb-2">
              Error al cargar cliente
            </h3>
            <p className="text-admin-text-tertiary mb-4">
              {fetchError || "Cliente no encontrado"}
            </p>
            <Button onClick={fetchCustomer}>Reintentar</Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  const customerName =
    customer.first_name && customer.last_name
      ? `${customer.first_name} ${customer.last_name}`
      : customer.first_name || customer.last_name || "Sin nombre";

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-4">
          <Button size="sm" variant="outline" onClick={() => router.back()}>
            <ArrowLeft className="h-4 w-4" />
          </Button>
          <div>
            <h1 className="text-3xl font-bold text-admin-text-primary">
              Editar Cliente
            </h1>
            <p className="text-admin-text-tertiary">{customerName}</p>
          </div>
        </div>

        <FormFieldActionsExtended
          isSubmitting={form.isSubmitting}
          submitIcon={<Save className="h-4 w-4 mr-2" />}
          submitLabel="Guardar Cambios"
          submittingLabel="Guardando..."
          onCancel={() => router.back()}
          onSubmit={form.handleSubmit}
        />
      </div>

      {form.formError && (
        <Card className="border-red-200 bg-admin-bg-tertiary">
          <CardContent className="p-4">
            <p className="text-red-700">{form.formError}</p>
          </CardContent>
        </Card>
      )}

      <CustomerEditForm
        errors={form.errors}
        handleRUTBlur={handleRUTBlur}
        handleRUTChange={handleRUTChange}
        handleSubmit={form.handleSubmit}
        setValue={form.setValue}
        values={form.values}
      />
    </div>
  );
}

"use client";

import FormField from "@/components/ui/FormField";
import { Input } from "@/components/ui/input";

interface Props {
  values: {
    address_line_1: string;
    address_line_2: string;
    city: string;
    state: string;
    postal_code: string;
    country: string;
  };
  errors: Record<string, { message?: string }>;
  onValueChange: (field: string, value: string) => void;
  size?: "normal" | "large";
}

export function CustomerAddressFields({
  values,
  errors,
  onValueChange,
  size = "normal",
}: Props) {
  const inputClass = size === "large" ? "h-12 sm:h-14" : "";
  return (
    <div className="space-y-4">
      <FormField error={errors.address_line_1?.message} label="Dirección">
        <Input
          aria-invalid={!!errors.address_line_1}
          className={inputClass}
          id="address_line_1"
          placeholder="Calle y número"
          value={values.address_line_1}
          onChange={(e) => onValueChange("address_line_1", e.target.value)}
        />
      </FormField>
      <FormField
        description="Opcional - Departamento, piso, etc."
        error={errors.address_line_2?.message}
        label="Dirección 2"
      >
        <Input
          aria-invalid={!!errors.address_line_2}
          className={inputClass}
          id="address_line_2"
          placeholder="Departamento, piso, etc."
          value={values.address_line_2}
          onChange={(e) => onValueChange("address_line_2", e.target.value)}
        />
      </FormField>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <FormField error={errors.city?.message} label="Ciudad">
          <Input
            aria-invalid={!!errors.city}
            className={inputClass}
            id="city"
            placeholder="Ciudad"
            value={values.city}
            onChange={(e) => onValueChange("city", e.target.value)}
          />
        </FormField>
        <FormField error={errors.state?.message} label="Provincia">
          <Input
            aria-invalid={!!errors.state}
            className={inputClass}
            id="state"
            placeholder="Provincia"
            value={values.state}
            onChange={(e) => onValueChange("state", e.target.value)}
          />
        </FormField>
      </div>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <FormField error={errors.postal_code?.message} label="Código Postal">
          <Input
            aria-invalid={!!errors.postal_code}
            className={inputClass}
            id="postal_code"
            placeholder="1234"
            value={values.postal_code}
            onChange={(e) => onValueChange("postal_code", e.target.value)}
          />
        </FormField>
        <FormField error={errors.country?.message} label="País">
          <Input
            aria-invalid={!!errors.country}
            className={inputClass}
            id="country"
            placeholder="País"
            value={values.country}
            onChange={(e) => onValueChange("country", e.target.value)}
          />
        </FormField>
      </div>
    </div>
  );
}

"use client";

import FormField from "@/components/ui/FormField";
import { Input } from "@/components/ui/input";

interface Props {
  values: {
    first_name: string;
    last_name: string;
    email: string;
    phone: string;
    rut: string;
  };
  errors: Record<string, { message?: string }>;
  onValueChange: (field: string, value: string) => void;
  onRUTChange?: (value: string) => void;
  onRUTBlur?: (value: string) => void;
  size?: "normal" | "large";
}

export function CustomerPersonalInfoFields({
  values,
  errors,
  onValueChange,
  onRUTChange,
  onRUTBlur,
  size = "normal",
}: Props) {
  const inputClass = size === "large" ? "h-12 sm:h-14" : "";
  return (
    <div className="space-y-4">
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <FormField required error={errors.first_name?.message} label="Nombre">
          <Input
            aria-invalid={!!errors.first_name}
            className={inputClass}
            id="first_name"
            placeholder="Nombre"
            value={values.first_name}
            onChange={(e) => onValueChange("first_name", e.target.value)}
          />
        </FormField>
        <FormField required error={errors.last_name?.message} label="Apellido">
          <Input
            aria-invalid={!!errors.last_name}
            className={inputClass}
            id="last_name"
            placeholder="Apellido"
            value={values.last_name}
            onChange={(e) => onValueChange("last_name", e.target.value)}
          />
        </FormField>
      </div>
      <FormField
        description="Opcional"
        error={errors.email?.message}
        label="Email"
      >
        <Input
          aria-invalid={!!errors.email}
          className={inputClass}
          id="email"
          placeholder="email@ejemplo.com"
          type="email"
          value={values.email}
          onChange={(e) => onValueChange("email", e.target.value)}
        />
      </FormField>
      <FormField
        description="Opcional"
        error={errors.phone?.message}
        label="Teléfono"
      >
        <Input
          aria-invalid={!!errors.phone}
          className={inputClass}
          id="phone"
          placeholder="+54 9 11 1234-5678"
          value={values.phone}
          onChange={(e) => onValueChange("phone", e.target.value)}
        />
      </FormField>
      <FormField
        description="Rol Único Tributario (opcional)"
        error={errors.rut?.message}
        label="RUT"
      >
        <Input
          aria-invalid={!!errors.rut}
          className={inputClass}
          id="rut"
          placeholder="12.345.678-9 o 123456789"
          value={values.rut}
          onBlur={(e) => onRUTBlur?.(e.target.value)}
          onChange={(e) => onRUTChange?.(e.target.value)}
        />
      </FormField>
    </div>
  );
}

"use client";

import { UserPlus } from "lucide-react";
import Link from "next/link";
import { useRouter, useSearchParams } from "next/navigation";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import type { Customer } from "@/lib/api/services/customerService";

import { useCustomers } from "../_hooks/useCustomers";
import { CustomersFilters } from "./CustomersFilters";
import { CustomersStatsCards } from "./CustomersStatsCards";
import { CustomersTable } from "./CustomersTable";

interface CustomersContentProps {
  initialCustomers: Customer[];
  currentBranchId: string | null;
  isSuperAdmin: boolean;
  organizationId: string | null;
}

export default function CustomersContent({
  initialCustomers,
}: CustomersContentProps) {
  const router = useRouter();
  const searchParams = useSearchParams();
  const fieldOperationIdFromUrl = searchParams.get("field_operation_id");

  const {
    customers,
    stats,
    loading,
    error,
    currentPage,
    totalPages,
    searchTerm,
    statusFilter,
    agreementFilter,
    agreements,
    operativoName,
    isGlobalView,
    currentBranchId,
    branches,
    setSearchTerm,
    setStatusFilter,
    setAgreementFilter,
    setCurrentPage,
    fetchCustomers,
  } = useCustomers(initialCustomers, fieldOperationIdFromUrl);

  if (loading && customers.length === 0) {
    return (
      <div className="space-y-6">
        <div className="space-y-4">
          <h1 className="text-2xl sm:text-3xl font-bold text-admin-text-primary">
            Gestión de Clientes
          </h1>
          <p className="text-sm text-admin-text-tertiary">
            Cargando información de clientes...
          </p>
        </div>
        <div className="grid grid-cols-2 sm:grid-cols-3 gap-4 sm:gap-6">
          {[...Array(4)].map((_, i) => (
            <Card className="animate-pulse" key={i}>
              <CardContent className="p-6">
                <div className="h-4 bg-gray-200 rounded w-3/4 mb-2" />
                <div className="h-8 bg-gray-200 rounded w-1/2" />
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Operativo mode banner */}
      {fieldOperationIdFromUrl && (
        <div className="flex items-center justify-between gap-2 px-4 py-2 rounded-xl bg-admin-accent-primary/20 border border-admin-accent-primary/30">
          <span className="text-sm font-medium text-admin-text-primary">
            Clientes del operativo: {operativoName || "..."}
          </span>
          <Link
            className="text-sm text-admin-accent-primary hover:underline font-medium"
            href={`/admin/field-operations/${fieldOperationIdFromUrl}`}
          >
            Volver al operativo
          </Link>
        </div>
      )}

      {/* Header */}
      <div className="space-y-4">
        <h1 className="text-2xl sm:text-3xl font-bold text-admin-text-primary">
          Gestión de Clientes
        </h1>
        <p className="text-sm text-admin-text-tertiary">
          {fieldOperationIdFromUrl
            ? "Clientes vinculados a este operativo"
            : "Administra los clientes de tu sucursal"}
        </p>
        <div className="flex justify-end">
          <Button
            className="min-h-[44px]"
            onClick={() =>
              router.push(
                fieldOperationIdFromUrl
                  ? `/admin/customers/new?field_operation_id=${fieldOperationIdFromUrl}`
                  : "/admin/customers/new",
              )
            }
          >
            <UserPlus className="h-4 w-4 mr-2" />
            Nuevo Cliente
          </Button>
        </div>
      </div>

      {/* Stats Cards */}
      {stats && (
        <CustomersStatsCards
          stats={stats}
          statsLabel={
            isGlobalView
              ? "Todas las sucursales"
              : `Sucursal: ${branches?.find((b) => b.id === currentBranchId)?.name ?? "seleccionada"}`
          }
        />
      )}

      {/* Filters */}
      <CustomersFilters
        agreementFilter={agreementFilter}
        agreements={agreements}
        searchTerm={searchTerm}
        statusFilter={statusFilter}
        onAgreementFilterChange={(v) => { setAgreementFilter(v); setCurrentPage(1); }}
        onSearchChange={(v) => { setSearchTerm(v); setCurrentPage(1); }}
        onSearchKeyDown={(e) => { if (e.key === "Enter") fetchCustomers(); }}
        onStatusFilterChange={setStatusFilter}
      />

      {/* Table */}
      <CustomersTable
        currentPage={currentPage}
        customers={customers}
        error={error}
        loading={loading}
        totalPages={totalPages}
        onPageChange={setCurrentPage}
        onRetry={fetchCustomers}
      />
    </div>
  );
}

