"use client";

import { ArrowLeft, Save } from "lucide-react";
import { useRouter, useSearchParams } from "next/navigation";
import { useEffect, useState } from "react";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { FormFieldActionsExtended } from "@/components/ui/FormField";
import { useBranch } from "@/hooks/useBranch";
import { useForm } from "@/hooks/useForm";
import { customerService } from "@/lib/api/services/customerService";
import { handleApiError } from "@/lib/api/services/errorService";
import {
  error as notifyError,
  success,
} from "@/lib/api/services/notificationService";
import { formatRUT } from "@/lib/utils/rut";
import { customerSchema } from "@/lib/validation/formValidation";

import { NewCustomerForm } from "./_components/NewCustomerForm";

export default function NewCustomerPage() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const fieldOperationIdFromUrl = searchParams.get("field_operation_id");
  const { currentBranchId } = useBranch();
  const [operativoBranchId, setOperativoBranchId] = useState<string | null>(
    null,
  );

  useEffect(() => {
    if (!fieldOperationIdFromUrl) {
      setOperativoBranchId(null);
      return;
    }
    fetch(`/api/admin/field-operations/${fieldOperationIdFromUrl}`)
      .then((r) => r.json())
      .then((j) => {
        const fo = j?.data?.fieldOperation;
        setOperativoBranchId(fo?.branch_id ?? null);
      })
      .catch(() => setOperativoBranchId(null));
  }, [fieldOperationIdFromUrl]);

  const form = useForm({
    validationSchema: customerSchema,
    defaultValues: {
      first_name: "",
      last_name: "",
      email: "",
      phone: "",
      rut: "",
      address_line_1: "",
      address_line_2: "",
      city: "",
      state: "",
      postal_code: "",
      country: "Chile",
      notes: "",
    },
    onSubmit: async (data) => {
      const requestBody = {
        first_name: data.first_name?.trim() || null,
        last_name: data.last_name?.trim() || null,
        email: data.email?.trim() || null,
        phone: data.phone?.trim() || null,
        rut: data.rut?.trim() || null,
        address_line_1: data.address_line_1?.trim() || null,
        address_line_2: data.address_line_2?.trim() || null,
        city: data.city?.trim() || null,
        state: data.state?.trim() || null,
        postal_code: data.postal_code?.trim() || null,
        country: data.country?.trim() || "Chile",
        notes: data.notes?.trim() || null,
        branch_id: operativoBranchId || currentBranchId || undefined,
        field_operation_id: fieldOperationIdFromUrl || undefined,
      };

      const customer = await customerService.createCustomer(requestBody);

      if (!customer || !customer.id) {
        throw new Error(
          "La respuesta del servidor no contiene información del cliente creado",
        );
      }

      return { customer };
    },
    onSuccess: () => {
      success("Cliente creado exitosamente");
      router.push(
        fieldOperationIdFromUrl
          ? `/admin/customers?field_operation_id=${fieldOperationIdFromUrl}`
          : "/admin/customers",
      );
    },
    onError: (err) => {
      const standardError = handleApiError(err, "NewCustomerPage");
      notifyError(standardError.userMessage);
    },
  });

  const handleRUTChange = (value: string) => {
    const formatted = formatRUT(value);
    form.setValue("rut", formatted);
  };

  const handleRUTBlur = (value: string) => {
    const formatted = formatRUT(value);
    if (formatted !== value) {
      form.setValue("rut", formatted);
    }
  };

  return (
    <div className="space-y-6">
      <div className="space-y-4">
        <div className="flex items-center gap-3">
          <Button
            className="min-h-[44px] shrink-0"
            size="sm"
            variant="outline"
            onClick={() => router.back()}
          >
            <ArrowLeft className="h-4 w-4" />
          </Button>
          <h1 className="text-2xl sm:text-3xl md:text-4xl font-display font-bold text-admin-text-primary tracking-tight uppercase">
            Nuevo Cliente
          </h1>
        </div>
        <p className="text-[9px] sm:text-[10px] font-serif italic text-admin-text-tertiary uppercase tracking-[0.3em]">
          Registro de Archivo en la Base de Datos
        </p>
        <FormFieldActionsExtended
          isSubmitting={form.isSubmitting}
          submitIcon={<Save className="h-4 w-4 mr-2" />}
          submitLabel="Crear Cliente"
          submittingLabel="Creando..."
          onCancel={() => router.back()}
          onSubmit={form.handleSubmit}
        />
      </div>

      {form.formError && (
        <Card className="border border-red-300 bg-admin-bg-tertiary">
          <CardContent className="p-4">
            <p className="text-red-700">{form.formError}</p>
          </CardContent>
        </Card>
      )}

      <NewCustomerForm
        errors={form.errors}
        handleRUTBlur={handleRUTBlur}
        handleRUTChange={handleRUTChange}
        handleSubmit={form.handleSubmit}
        setValue={form.setValue}
        values={form.values}
      />
    </div>
  );
}

"use client";

import { Database, RefreshCw, Shield, User } from "lucide-react";
import { useEffect, useState } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { useAuthContext } from "@/contexts/AuthContext";
import { createClient } from "@/utils/supabase/client";

export default function AdminDebugPage() {
  const { user, profile, loading, error } = useAuthContext();
  const [adminStatus, setAdminStatus] = useState<unknown>(null);
  const [dbConnection, setDbConnection] = useState<unknown>(null);
  const [debugInfo, setDebugInfo] = useState<unknown[]>([]);

  const addDebugLog = (message: string, data?: unknown) => {
    const timestamp = new Date().toLocaleTimeString();
    setDebugInfo((prev) => [...prev.slice(-20), { timestamp, message, data }]);
  };

  const checkAdminStatus = async () => {
    try {
      addDebugLog("🔍 Checking admin status...");
      const supabase = createClient();

      if (!user) {
        addDebugLog("❌ No user found");
        setAdminStatus({ isAdmin: false, error: "No user" });
        return;
      }

      addDebugLog("👤 User found", { email: user.email, id: user.id });

      const { data, error } = await supabase.rpc("is_admin", {
        user_id: user.id,
      });

      if (error) {
        addDebugLog("❌ Admin check error", error);
        setAdminStatus({ isAdmin: false, error: error.message });
      } else {
        addDebugLog("✅ Admin check result", { isAdmin: !!data });
        setAdminStatus({ isAdmin: !!data, error: null });
      }
    } catch (err) {
      addDebugLog("❌ Admin check exception", err);
      setAdminStatus({ isAdmin: false, error: "Exception occurred" });
    }
  };

  const checkDatabaseConnection = async () => {
    try {
      addDebugLog("🔍 Checking database connection...");
      const supabase = createClient();

      const { data, error } = await supabase
        .from("admin_users")
        .select("id, email, role")
        .limit(1);

      if (error) {
        addDebugLog("❌ Database error", error);
        setDbConnection({ connected: false, error: error.message });
      } else {
        addDebugLog("✅ Database connected", { adminCount: data?.length || 0 });
        setDbConnection({ connected: true, adminUsers: data });
      }
    } catch (err) {
      addDebugLog("❌ Database exception", err);
      setDbConnection({ connected: false, error: "Exception occurred" });
    }
  };

  useEffect(() => {
    addDebugLog("🚀 Debug page loaded");
    if (user) {
      addDebugLog("👤 User detected on load", { email: user.email });
      checkAdminStatus();
    }
    checkDatabaseConnection();
  }, [user]);

  const refreshAll = () => {
    addDebugLog("🔄 Manual refresh triggered");
    checkAdminStatus();
    checkDatabaseConnection();
  };

  return (
    <div className="container mx-auto px-4 py-8 max-w-6xl">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-3xl font-bold text-azul-profundo">
            Admin Debug Console
          </h1>
          <p className="text-tierra-media">
            Diagnostic tools for admin authentication issues
          </p>
        </div>

        <Button onClick={refreshAll}>
          <RefreshCw className="h-4 w-4 mr-2" />
          Refresh All
        </Button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-6">
        {/* Auth Status */}
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">
              Authentication Status
            </CardTitle>
            <User className="h-4 w-4 text-azul-profundo" />
          </CardHeader>
          <CardContent>
            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <span className="text-sm">Loading:</span>
                <Badge variant={loading ? "destructive" : "secondary"}>
                  {loading ? "Yes" : "No"}
                </Badge>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-sm">User:</span>
                <Badge variant={user ? "default" : "destructive"}>
                  {user ? "Logged In" : "Not Logged In"}
                </Badge>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-sm">Profile:</span>
                <Badge variant={profile ? "default" : "secondary"}>
                  {profile ? "Loaded" : "Not Loaded"}
                </Badge>
              </div>
              {user && (
                <div className="text-xs text-tierra-media mt-2">
                  Email: {user.email}
                </div>
              )}
              {error && (
                <div className="text-xs text-red-500 mt-2">
                  Error: {error.message}
                </div>
              )}
            </div>
          </CardContent>
        </Card>

        {/* Admin Status */}
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Admin Status</CardTitle>
            <Shield className="h-4 w-4 text-dorado" />
          </CardHeader>
          <CardContent>
            <div className="space-y-2">
              {adminStatus ? (
                <>
                  <div className="flex items-center justify-between">
                    <span className="text-sm">Is Admin:</span>
                    <Badge
                      variant={adminStatus.isAdmin ? "default" : "destructive"}
                    >
                      {adminStatus.isAdmin ? "Yes" : "No"}
                    </Badge>
                  </div>
                  {adminStatus.error && (
                    <div className="text-xs text-red-500 mt-2">
                      Error: {adminStatus.error}
                    </div>
                  )}
                </>
              ) : (
                <div className="text-sm text-tierra-media">
                  No admin check performed yet
                </div>
              )}
              <Button
                className="w-full mt-2"
                disabled={!user}
                size="sm"
                variant="outline"
                onClick={checkAdminStatus}
              >
                Check Admin Status
              </Button>
            </div>
          </CardContent>
        </Card>

        {/* Database Status */}
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">
              Database Status
            </CardTitle>
            <Database className="h-4 w-4 text-verde-suave" />
          </CardHeader>
          <CardContent>
            <div className="space-y-2">
              {dbConnection ? (
                <>
                  <div className="flex items-center justify-between">
                    <span className="text-sm">Connected:</span>
                    <Badge
                      variant={
                        dbConnection.connected ? "default" : "destructive"
                      }
                    >
                      {dbConnection.connected ? "Yes" : "No"}
                    </Badge>
                  </div>
                  {dbConnection.adminUsers && (
                    <div className="text-xs text-tierra-media mt-2">
                      Admin users found: {dbConnection.adminUsers.length}
                    </div>
                  )}
                  {dbConnection.error && (
                    <div className="text-xs text-red-500 mt-2">
                      Error: {dbConnection.error}
                    </div>
                  )}
                </>
              ) : (
                <div className="text-sm text-tierra-media">
                  Checking database connection...
                </div>
              )}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Debug Log */}
      <Card>
        <CardHeader>
          <CardTitle>Debug Log</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-2 max-h-96 overflow-y-auto">
            {debugInfo.length === 0 ? (
              <div className="text-tierra-media text-sm">
                No debug logs yet...
              </div>
            ) : (
              debugInfo.map((log, index) => (
                <div className="flex items-start gap-3 text-sm" key={index}>
                  <span className="text-xs text-tierra-media font-mono">
                    {log.timestamp}
                  </span>
                  <span className="flex-1">{log.message}</span>
                  {log.data && (
                    <pre className="text-xs bg-gray-100 p-1 rounded max-w-xs overflow-hidden">
                      {JSON.stringify(log.data, null, 2)}
                    </pre>
                  )}
                </div>
              ))
            )}
          </div>
        </CardContent>
      </Card>

      {/* Quick Actions */}
      <Card className="mt-6">
        <CardHeader>
          <CardTitle>Quick Actions</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex flex-wrap gap-3">
            <Button
              variant="outline"
              onClick={() => (window.location.href = "/login")}
            >
              Go to Login
            </Button>
            <Button
              variant="outline"
              onClick={() => (window.location.href = "/admin")}
            >
              Try Admin Dashboard
            </Button>
            <Button variant="outline" onClick={() => window.location.reload()}>
              Reload Page
            </Button>
            <Button
              variant="outline"
              onClick={() => {
                localStorage.clear();
                sessionStorage.clear();
                window.location.href = "/login";
              }}
            >
              Clear Storage & Login
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { AlertCircle, ArrowLeft, Home, RefreshCw } from "lucide-react";
import { useEffect } from "react";

import { Button } from "@/components/ui/button";
import { logger } from "@/lib/logger";

/**
 * Admin Error Page for Next.js App Router
 * This page is shown when an error occurs in admin routes
 */
export default function AdminError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  useEffect(() => {
    // Log error to logger
    logger.error("Admin error page triggered", error as unknown, {
      digest: error.digest,
      adminError: true,
      timestamp: new Date().toISOString(),
    });
  }, [error]);

  return (
    <div className="flex min-h-screen items-center justify-center bg-background p-4">
      <div className="w-full max-w-md space-y-6 rounded-lg border border-destructive/50 bg-card p-6 shadow-lg">
        <div className="flex items-center gap-3">
          <AlertCircle className="h-6 w-6 text-destructive" />
          <h1 className="text-2xl font-bold text-foreground">
            Error en Panel de Administración
          </h1>
        </div>

        <div className="space-y-2">
          <p className="text-sm text-muted-foreground">
            Ocurrió un error en el panel de administración. Por favor, intenta
            recargar la página o volver al inicio.
          </p>
          {process.env.NODE_ENV === "development" && (
            <details className="mt-4 rounded-md bg-muted p-3">
              <summary className="cursor-pointer text-sm font-medium text-foreground">
                Detalles del error (solo en desarrollo)
              </summary>
              <pre className="mt-2 overflow-auto text-xs text-muted-foreground">
                {error.message}
                {error.digest && `\n\nDigest: ${error.digest}`}
                {"\n\n"}
                {error.stack}
              </pre>
            </details>
          )}
        </div>

        <div className="flex flex-col gap-2 sm:flex-row">
          <Button className="flex-1" variant="default" onClick={reset}>
            <RefreshCw className="mr-2 h-4 w-4" />
            Intentar de nuevo
          </Button>
          <Button
            className="flex-1"
            variant="outline"
            onClick={() => {
              window.location.href = "/admin";
            }}
          >
            <ArrowLeft className="mr-2 h-4 w-4" />
            Volver al panel
          </Button>
          <Button
            className="flex-1"
            variant="ghost"
            onClick={() => {
              window.location.href = "/";
            }}
          >
            <Home className="mr-2 h-4 w-4" />
            Inicio
          </Button>
        </div>
      </div>
    </div>
  );
}

"use client";

import { RefreshCw, Truck } from "lucide-react";
import { type SetStateAction } from "react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { formatPrice } from "@/lib/utils";

interface WorkOrderItem {
  id: string;
  work_order_number: string;
  status: string;
  total_amount: number;
  payment_status?: string;
  frame_name?: string;
  lens_type?: string;
  lens_material?: string;
  lab_name?: string;
  customer?: { first_name?: string; last_name?: string; email?: string };
}

interface FieldOpDeliveryTabProps {
  readyForPickupOrders: WorkOrderItem[];
  deliverSelectedIds: Set<string>;
  deliverRecipient: string;
  deliverNotes: string;
  deliverLoading: boolean;
  onDeliverSelectedIdsChange: (
    updater: (prev: Set<string>) => Set<string>,
  ) => void;
  onDeliverRecipientChange: (value: SetStateAction<string>) => void;
  onDeliverNotesChange: (value: SetStateAction<string>) => void;
  onDeliver: () => Promise<void>;
}

export function FieldOpDeliveryTab({
  readyForPickupOrders,
  deliverSelectedIds,
  deliverRecipient,
  deliverNotes,
  deliverLoading,
  onDeliverSelectedIdsChange,
  onDeliverRecipientChange,
  onDeliverNotesChange,
  onDeliver,
}: FieldOpDeliveryTabProps) {
  return (
    <div className="rounded-xl border border-admin-border-primary/30 bg-admin-bg-tertiary shadow-[0_1px_3px_rgba(0,0,0,0.3)] p-4 sm:p-6">
      <h3 className="flex items-center gap-2 text-admin-text-primary font-semibold mb-4">
        <Truck className="h-5 w-5 shrink-0" />
        Entrega en empresa
      </h3>
      {readyForPickupOrders.length === 0 ? (
        <p className="text-admin-text-tertiary text-sm">
          No hay trabajos listos para retiro (ready_for_pickup). Los
          trabajos aparecerán aquí cuando estén listos para entrega.
        </p>
      ) : (
        <div className="space-y-4">
          <div>
            <Label className="text-admin-text-primary text-sm">
              Trabajos a entregar
            </Label>
            <div className="mt-2 space-y-2 max-h-48 overflow-y-auto border border-admin-border-primary/20 rounded-lg p-2">
              {readyForPickupOrders.map((wo) => (
                <label
                  className="flex items-center gap-3 p-2 rounded-lg hover:bg-[#AE000010] cursor-pointer"
                  key={wo.id}
                >
                  <input
                    checked={deliverSelectedIds.has(wo.id)}
                    className="rounded"
                    type="checkbox"
                    onChange={(e) => {
                      onDeliverSelectedIdsChange((prev) => {
                        const next = new Set(prev);
                        if (e.target.checked) next.add(wo.id);
                        else next.delete(wo.id);
                        return next;
                      });
                    }}
                  />
                  <span className="text-admin-text-primary text-sm">
                    {wo.work_order_number} —{" "}
                    {wo.customer
                      ? `${wo.customer.first_name || ""} ${wo.customer.last_name || ""}`.trim() ||
                        "—"
                      : "—"}{" "}
                    ({formatPrice(wo.total_amount)})
                  </span>
                </label>
              ))}
            </div>
          </div>
          <div>
            <Label className="text-admin-text-primary text-sm">
              Nombre del receptor *
            </Label>
            <Input
              className="mt-1 h-11 min-h-[44px] border-admin-border-primary/30"
              placeholder="Ej: Juan Pérez"
              value={deliverRecipient}
              onChange={(e) => onDeliverRecipientChange(e.target.value)}
            />
          </div>
          <div>
            <Label className="text-admin-text-primary text-sm">
              Notas (opcional)
            </Label>
            <Input
              className="mt-1 h-11 min-h-[44px] border-admin-border-primary/30"
              placeholder="Observaciones de la entrega"
              value={deliverNotes}
              onChange={(e) => onDeliverNotesChange(e.target.value)}
            />
          </div>
          <Button
            className="min-h-[44px] rounded-xl bg-admin-accent-primary hover:bg-admin-accent-secondary text-[#1A2B23]"
            disabled={
              deliverLoading ||
              deliverSelectedIds.size === 0 ||
              !deliverRecipient.trim()
            }
            onClick={onDeliver}
          >
            {deliverLoading ? (
              <RefreshCw className="h-4 w-4 animate-spin mr-2" />
            ) : null}
            Registrar entrega
          </Button>
        </div>
      )}
    </div>
  );
}

"use client";

import { RefreshCw } from "lucide-react";
import { useParams, useRouter, useSearchParams } from "next/navigation";
import { useEffect, useState } from "react";

import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useBranch } from "@/hooks/useBranch";
import type { Quote } from "@/lib/api/services";
import type { Customer } from "@/lib/api/services/customerService";

import { FieldOpDeliveryTab } from "./FieldOpDeliveryTab";
import * as DL from "./FieldOpDetailDataLayer";
import {
  AddCustomerDialog,
  ConfirmDeleteDialog,
  CreatePrescriptionDialog,
  CreateQuoteDialog,
  OpenCashDialog,
} from "./FieldOpDetailDialogs";
import type { FieldOperation, MobileStockItem, WorkOrderItem } from "./FieldOpDetailTypes";
import FieldOpHeader from "./FieldOpHeader";
import FieldOpInventorySection from "./FieldOpInventorySection";
import FieldOpPatientRegistrations from "./FieldOpPatientRegistrations";
import { FieldOpQuotesTab } from "./FieldOpQuotesTab";
import FieldOpStatsCards from "./FieldOpStatsCards";
import FieldOpSummarySection from "./FieldOpSummarySection";
import FieldOpWorkOrdersSection from "./FieldOpWorkOrdersSection";

export default function FieldOpDetailContent() {
  const params = useParams();
  const router = useRouter();
  const searchParams = useSearchParams();
  const id = params.id as string;
  const tabFromUrl = searchParams.get("tab");
  const defaultTab = [
    "resumen", "clientes", "presupuestos", "trabajos", "entrega", "stock",
  ].includes(tabFromUrl || "") ? tabFromUrl! : "resumen";
  const { currentBranchId } = useBranch();

  const [operation, setOperation] = useState<FieldOperation | null>(null);
  const [mobileStock, setMobileStock] = useState<MobileStockItem[]>([]);
  const [workOrders, setWorkOrders] = useState<WorkOrderItem[]>([]);
  const [workOrdersLoading, setWorkOrdersLoading] = useState(false);
  const [loading, setLoading] = useState(true);
  const [updatingStatus, setUpdatingStatus] = useState(false);
  const [deliverLoading, setDeliverLoading] = useState(false);
  const [deliverRecipient, setDeliverRecipient] = useState("");
  const [deliverNotes, setDeliverNotes] = useState("");
  const [deliverSelectedIds, setDeliverSelectedIds] = useState<Set<string>>(new Set());
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [quotes, setQuotes] = useState<Quote[]>([]);
  const [customersLoading, setCustomersLoading] = useState(false);
  const [quotesLoading, setQuotesLoading] = useState(false);
  const [showAddCustomer, setShowAddCustomer] = useState(false);
  const [showCreateQuote, setShowCreateQuote] = useState(false);
  const [quoteInitialCustomerId, setQuoteInitialCustomerId] = useState<string | undefined>(undefined);
  const [showCreatePrescription, setShowCreatePrescription] = useState(false);
  const [prescriptionCustomerId, setPrescriptionCustomerId] = useState<string | null>(null);
  const [deleteCustomerId, setDeleteCustomerId] = useState<string | null>(null);
  const [deletingCustomer, setDeletingCustomer] = useState(false);
  const [deleteQuoteId, setDeleteQuoteId] = useState<string | null>(null);
  const [deletingQuote, setDeletingQuote] = useState(false);
  const [cashStatus, setCashStatus] = useState<{ isOpen: boolean; session?: { opening_cash_amount?: number } } | null>(null);
  const [loadingCashStatus, setLoadingCashStatus] = useState(false);
  const [showOpenCashDialog, setShowOpenCashDialog] = useState(false);
  const [openingCashAmount, setOpeningCashAmount] = useState("");
  const [openingCash, setOpeningCash] = useState(false);
  const [returningStock, setReturningStock] = useState(false);

  const doFetchDetail = () =>
    DL.fetchDetail(id, currentBranchId, setOperation, setMobileStock, setLoading, () => router.push("/admin/field-operations"));

  useEffect(() => { if (id) doFetchDetail(); }, [id]);

  useEffect(() => { if (operation) DL.fetchWorkOrders(id, currentBranchId, setWorkOrders, setWorkOrdersLoading); }, [operation?.id]);

  useEffect(() => {
    if (operation) {
      DL.fetchCustomers(id, operation.branch_id, setCustomers, setCustomersLoading);
      DL.fetchQuotes(id, operation.branch_id, setQuotes, setQuotesLoading);
    }
  }, [operation?.id]);

  useEffect(() => {
    if (operation) DL.fetchCashStatus(operation.branch_id, id, setCashStatus, setLoadingCashStatus);
  }, [operation?.id, operation?.branch_id]);

  if (loading || !operation)
    return (
      <div className="flex min-h-[200px] items-center justify-center">
        <RefreshCw className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );

  const handleStatusChange = (newStatus: string) =>
    DL.handleStatusChange(newStatus, operation, id, currentBranchId, setUpdatingStatus, setOperation, doFetchDetail);
  const handleReturnStock = () =>
    DL.handleReturnStock(operation, id, mobileStock, setReturningStock, doFetchDetail);
  const handleDeliver = () =>
    DL.handleDeliver(deliverSelectedIds, deliverRecipient, deliverNotes, id, currentBranchId, setDeliverLoading, setDeliverRecipient, setDeliverNotes, setDeliverSelectedIds, () => { doFetchDetail(); DL.fetchWorkOrders(id, currentBranchId, setWorkOrders, setWorkOrdersLoading); });
  const handleDeleteCustomer = () =>
    DL.handleDeleteCustomer(deleteCustomerId!, setDeletingCustomer, setDeleteCustomerId, () => DL.fetchCustomers(id, operation.branch_id, setCustomers, setCustomersLoading));
  const handleDeleteQuoteClick = (quoteId: string) => setDeleteQuoteId(quoteId);
  const handleDeleteQuoteConfirm = () =>
    DL.handleDeleteQuote(deleteQuoteId!, setDeletingQuote, setDeleteQuoteId, () => DL.fetchQuotes(id, operation.branch_id, setQuotes, setQuotesLoading));

  const readyForPickupOrders = workOrders.filter((wo) => wo.status === "ready_for_pickup");
  const operativoReturnUrl = `/admin/field-operations/${id}?tab=clientes`;

  const statusLabels: Record<string, string> = {
    draft: "Borrador", prepared: "Preparado", in_progress: "En terreno", completed: "Completado", cancelled: "Cancelado",
  };
  const statusLabel = statusLabels[operation.status] || operation.status;

  return (
    <div className="space-y-6">
      <FieldOpHeader
        handleStatusChange={handleStatusChange}
        mobileStock={mobileStock}
        operation={operation}
        updatingStatus={updatingStatus}
      />

      <FieldOpStatsCards
        cashStatus={cashStatus}
        id={id}
        loadingCashStatus={loadingCashStatus}
        operation={operation}
        onAddCustomer={() => setShowAddCustomer(true)}
        onCreateQuote={() => setShowCreateQuote(true)}
        onOpenCash={() => setShowOpenCashDialog(true)}
      />

      <Tabs className="space-y-4 sm:space-y-6" defaultValue={defaultTab}>
        <TabsList className="flex w-full justify-start md:justify-center gap-1 sm:gap-2 h-auto p-1 overflow-x-auto overflow-y-hidden min-w-0 [scrollbar-width:thin] [&::-webkit-scrollbar]:h-1 [&::-webkit-scrollbar-track]:bg-transparent [&::-webkit-scrollbar-thumb]:rounded-full [&::-webkit-scrollbar-thumb]:bg-admin-accent-primary/30 rounded-xl border border-admin-border-primary/20 bg-admin-bg-tertiary/50">
          <TabsTrigger className="flex-shrink-0 text-xs sm:text-sm px-3 py-2 min-h-[44px]" value="resumen">Resumen</TabsTrigger>
          <TabsTrigger className="flex-shrink-0 text-xs sm:text-sm px-3 py-2 min-h-[44px]" value="clientes">Clientes</TabsTrigger>
          <TabsTrigger className="flex-shrink-0 text-xs sm:text-sm px-3 py-2 min-h-[44px]" value="presupuestos">Presupuestos</TabsTrigger>
          <TabsTrigger className="flex-shrink-0 text-xs sm:text-sm px-3 py-2 min-h-[44px]" value="trabajos">Trabajos</TabsTrigger>
          <TabsTrigger className="flex-shrink-0 text-xs sm:text-sm px-3 py-2 min-h-[44px]" value="entrega">Entrega</TabsTrigger>
          <TabsTrigger className="flex-shrink-0 text-xs sm:text-sm px-3 py-2 min-h-[44px]" value="stock">Stock Móvil</TabsTrigger>
        </TabsList>

        <TabsContent className="space-y-4 mt-4 sm:mt-6" value="resumen">
          <FieldOpSummarySection operation={operation} statusLabel={statusLabel} />
        </TabsContent>

        <TabsContent className="space-y-4 mt-4 sm:mt-6" value="clientes">
          <FieldOpPatientRegistrations
            customers={customers}
            customersLoading={customersLoading}
            operativoReturnUrl={operativoReturnUrl}
            onAddCustomer={() => setShowAddCustomer(true)}
            onDeleteCustomer={(customerId) => setDeleteCustomerId(customerId)}
            onPrescription={(customerId) => { setPrescriptionCustomerId(customerId); setShowCreatePrescription(true); }}
            onQuote={(customerId) => { setQuoteInitialCustomerId(customerId); setShowCreateQuote(true); }}
          />
        </TabsContent>

        <TabsContent className="space-y-4 mt-4 sm:mt-6" value="presupuestos">
          <FieldOpQuotesTab
            fieldOperationId={id}
            quotes={quotes}
            quotesLoading={quotesLoading}
            onCreateQuote={() => setShowCreateQuote(true)}
            onDeleteQuote={handleDeleteQuoteClick}
          />
        </TabsContent>

        <TabsContent className="space-y-4 mt-4 sm:mt-6" value="stock">
          <FieldOpInventorySection
            id={id}
            mobileStock={mobileStock}
            returningStock={returningStock}
            onReturnStock={handleReturnStock}
          />
        </TabsContent>

        <TabsContent className="space-y-4 mt-4 sm:mt-6" value="trabajos">
          <FieldOpWorkOrdersSection workOrders={workOrders} workOrdersLoading={workOrdersLoading} />
        </TabsContent>

        <TabsContent className="space-y-4 mt-4 sm:mt-6" value="entrega">
          <FieldOpDeliveryTab
            deliverLoading={deliverLoading}
            deliverNotes={deliverNotes}
            deliverRecipient={deliverRecipient}
            deliverSelectedIds={deliverSelectedIds}
            readyForPickupOrders={readyForPickupOrders}
            onDeliver={handleDeliver}
            onDeliverNotesChange={setDeliverNotes}
            onDeliverRecipientChange={setDeliverRecipient}
            onDeliverSelectedIdsChange={setDeliverSelectedIds}
          />
        </TabsContent>
      </Tabs>

      <ConfirmDeleteDialog
        description="Esta acción no se puede deshacer. El cliente será eliminado permanentemente."
        loading={deletingCustomer}
        open={deleteCustomerId !== null}
        title="¿Eliminar cliente?"
        onCancel={() => setDeleteCustomerId(null)}
        onConfirm={handleDeleteCustomer}
      />
      <ConfirmDeleteDialog
        description="Esta acción no se puede deshacer. El presupuesto será eliminado permanentemente."
        loading={deletingQuote}
        open={deleteQuoteId !== null}
        title="¿Eliminar presupuesto?"
        onCancel={() => setDeleteQuoteId(null)}
        onConfirm={handleDeleteQuoteConfirm}
      />
      <AddCustomerDialog
        branchId={operation.branch_id}
        fieldOperationId={id}
        open={showAddCustomer}
        onOpenChange={setShowAddCustomer}
        onSuccess={() => { setShowAddCustomer(false); DL.fetchCustomers(id, operation.branch_id, setCustomers, setCustomersLoading); }}
      />
      <CreateQuoteDialog
        branchId={operation.branch_id}
        fieldOperationId={id}
        initialCustomerId={quoteInitialCustomerId}
        open={showCreateQuote}
        onCancel={() => setQuoteInitialCustomerId(undefined)}
        onOpenChange={setShowCreateQuote}
        onSuccess={() => { setShowCreateQuote(false); setQuoteInitialCustomerId(undefined); DL.fetchQuotes(id, operation.branch_id, setQuotes, setQuotesLoading); DL.fetchWorkOrders(id, currentBranchId, setWorkOrders, setWorkOrdersLoading); }}
      />
      <OpenCashDialog
        amount={openingCashAmount}
        loading={openingCash}
        open={showOpenCashDialog}
        onAmountChange={setOpeningCashAmount}
        onConfirm={() => DL.handleOpenCash(openingCashAmount, id, operation.branch_id, setOpeningCash, setShowOpenCashDialog, setOpeningCashAmount, () => DL.fetchCashStatus(operation.branch_id, id, setCashStatus, setLoadingCashStatus))}
        onOpenChange={(o) => { setShowOpenCashDialog(o); if (!o) setOpeningCashAmount(""); }}
      />
      <CreatePrescriptionDialog
        customerId={prescriptionCustomerId}
        open={showCreatePrescription}
        onCancel={() => setPrescriptionCustomerId(null)}
        onOpenChange={(o) => { setShowCreatePrescription(o); if (!o) setPrescriptionCustomerId(null); }}
        onSuccess={() => { setShowCreatePrescription(false); setPrescriptionCustomerId(null); DL.fetchCustomers(id, operation.branch_id, setCustomers, setCustomersLoading); }}
      />
    </div>
  );
}

import { toast } from "sonner";

import { posService, type Quote,quoteService } from "@/lib/api/services";
import {
  type Customer,
  customerService,
} from "@/lib/api/services/customerService";
import { getBranchAndOperativoHeaders, getBranchHeader } from "@/lib/utils/branch";

import type { FieldOperation, MobileStockItem, WorkOrderItem } from "./FieldOpDetailTypes";

export async function fetchWorkOrders(
  id: string,
  currentBranchId: string | null | undefined,
  setWorkOrders: (items: WorkOrderItem[]) => void,
  setWorkOrdersLoading: (loading: boolean) => void,
) {
  setWorkOrdersLoading(true);
  try {
    const headers = getBranchHeader(currentBranchId);
    const res = await fetch(`/api/admin/field-operations/${id}/work-orders`, {
      headers,
    });
    if (!res.ok) throw new Error("Error al cargar trabajos");
    const json = await res.json();
    const items = json?.data ?? json ?? [];
    setWorkOrders(Array.isArray(items) ? items : []);
  } catch {
    toast.error("Error al cargar trabajos");
    setWorkOrders([]);
  } finally {
    setWorkOrdersLoading(false);
  }
}

export async function fetchCustomers(
  id: string,
  branchId: string,
  setCustomers: (items: Customer[]) => void,
  setCustomersLoading: (loading: boolean) => void,
) {
  setCustomersLoading(true);
  try {
    const { data } = await customerService.getCustomers({
      branchId,
      fieldOperationId: id,
      limit: 100,
    });
    setCustomers(data || []);
  } catch {
    toast.error("Error al cargar clientes");
    setCustomers([]);
  } finally {
    setCustomersLoading(false);
  }
}

export async function fetchQuotes(
  id: string,
  branchId: string | undefined,
  setQuotes: (items: Quote[]) => void,
  setQuotesLoading: (loading: boolean) => void,
) {
  setQuotesLoading(true);
  try {
    const result = await quoteService.getQuotes({
      branch_id: branchId,
      field_operation_id: id,
      limit: 100,
    });
    setQuotes(result.data || []);
  } catch {
    toast.error("Error al cargar presupuestos");
    setQuotes([]);
  } finally {
    setQuotesLoading(false);
  }
}

export async function fetchCashStatus(
  branchId: string,
  fieldOpId: string,
  setCashStatus: (
    status: { isOpen: boolean; session?: { opening_cash_amount?: number } } | null,
  ) => void,
  setLoadingCashStatus: (loading: boolean) => void,
) {
  setLoadingCashStatus(true);
  try {
    const status = await posService.getCashStatus(branchId, fieldOpId);
    setCashStatus({
      isOpen: status?.isOpen ?? false,
      session: status?.session,
    });
  } catch {
    setCashStatus(null);
  } finally {
    setLoadingCashStatus(false);
  }
}

export async function fetchDetail(
  id: string,
  currentBranchId: string | null | undefined,
  setOperation: (op: FieldOperation | null) => void,
  setMobileStock: (stock: MobileStockItem[]) => void,
  setLoading: (loading: boolean) => void,
  onError?: () => void,
) {
  try {
    setLoading(true);
    const headers = getBranchHeader(currentBranchId);
    const response = await fetch(`/api/admin/field-operations/${id}`, {
      headers,
    });
    if (!response.ok) throw new Error("Error al cargar operativo");
    const data = await response.json();
    setOperation(data?.data?.fieldOperation || null);
    setMobileStock(data?.data?.mobileStock || []);
  } catch {
    toast.error("Error al cargar operativo");
    onError?.();
  } finally {
    setLoading(false);
  }
}

export async function handleStatusChange(
  newStatus: string,
  operation: FieldOperation,
  id: string,
  currentBranchId: string | null | undefined,
  setUpdatingStatus: (v: boolean) => void,
  setOperation: (op: FieldOperation | null | ((prev: FieldOperation | null) => FieldOperation | null)) => void,
  onCompleted?: () => void,
) {
  if (newStatus === operation.status) return;
  setUpdatingStatus(true);
  try {
    const headers: HeadersInit = {
      "Content-Type": "application/json",
      ...(operation?.branch_id
        ? getBranchAndOperativoHeaders(operation.branch_id, id)
        : getBranchHeader(currentBranchId)),
    };
    const response = await fetch(`/api/admin/field-operations/${id}`, {
      method: "PUT",
      headers,
      body: JSON.stringify({ status: newStatus }),
    });
    if (!response.ok) throw new Error("Error al actualizar estado");
    setOperation((prev) => (prev ? { ...prev, status: newStatus } : null));
    toast.success("Estado actualizado");
    if (newStatus === "completed") onCompleted?.();
  } catch {
    toast.error("Error al actualizar estado");
  } finally {
    setUpdatingStatus(false);
  }
}

export async function handleOpenCash(
  openingCashAmount: string,
  id: string,
  branchId: string,
  setOpeningCash: (v: boolean) => void,
  setShowOpenCashDialog: (v: boolean) => void,
  setOpeningCashAmount: (v: string) => void,
  onCashOpened?: () => void,
) {
  const amount = parseFloat(openingCashAmount);
  if (isNaN(amount) || amount < 0) {
    toast.error("Ingrese un monto válido");
    return;
  }
  setOpeningCash(true);
  try {
    const headers = getBranchAndOperativoHeaders(branchId, id);
    const res = await fetch("/api/admin/cash-register/open", {
      method: "POST",
      headers: { ...headers, "Content-Type": "application/json" },
      body: JSON.stringify({
        opening_cash_amount: amount,
        field_operation_id: id,
      }),
    });
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      throw new Error(err?.error || "Error al abrir caja");
    }
    toast.success("Caja abierta");
    setShowOpenCashDialog(false);
    setOpeningCashAmount("");
    onCashOpened?.();
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error al abrir caja");
  } finally {
    setOpeningCash(false);
  }
}

export async function handleReturnStock(
  operation: FieldOperation,
  id: string,
  mobileStock: MobileStockItem[],
  setReturningStock: (v: boolean) => void,
  onComplete: () => void,
) {
  if (!operation?.branch_id || !id || mobileStock.length === 0) return;
  setReturningStock(true);
  try {
    const headers: HeadersInit = {
      "Content-Type": "application/json",
      ...getBranchAndOperativoHeaders(operation.branch_id, id),
    };
    const res = await fetch(
      `/api/admin/field-operations/${id}/return-stock`,
      {
        method: "POST",
        headers,
        body: JSON.stringify({
          items: mobileStock.map((m) => ({
            product_id: m.product_id,
            quantity: m.quantity,
          })),
        }),
      },
    );
    if (!res.ok) {
      const err = await res.json();
      throw new Error(err?.error || "Error al devolver stock");
    }
    toast.success("Stock sobrante devuelto a la sucursal");
    onComplete();
  } catch (e: unknown) {
    toast.error(e instanceof Error ? e.message : "Error al devolver stock");
  } finally {
    setReturningStock(false);
  }
}

export async function handleDeliver(
  deliverSelectedIds: Set<string>,
  deliverRecipient: string,
  deliverNotes: string,
  id: string,
  currentBranchId: string | null | undefined,
  setDeliverLoading: (v: boolean) => void,
  setDeliverRecipient: (v: string) => void,
  setDeliverNotes: (v: string) => void,
  setDeliverSelectedIds: (v: Set<string>) => void,
  onSettled?: () => void,
) {
  if (deliverSelectedIds.size === 0 || !deliverRecipient.trim()) {
    toast.error("Seleccione al menos un trabajo y el nombre del receptor");
    return;
  }
  setDeliverLoading(true);
  try {
    const headers: HeadersInit = {
      "Content-Type": "application/json",
      ...getBranchHeader(currentBranchId),
    };
    const res = await fetch(`/api/admin/field-operations/${id}/deliver`, {
      method: "POST",
      headers,
      body: JSON.stringify({
        work_order_ids: Array.from(deliverSelectedIds),
        recipient_name: deliverRecipient.trim(),
        notes: deliverNotes.trim() || null,
      }),
    });
    if (!res.ok) {
      const err = await res.json();
      throw new Error(err?.error || "Error al registrar entrega");
    }
    toast.success("Entrega registrada");
    setDeliverRecipient("");
    setDeliverNotes("");
    setDeliverSelectedIds(new Set());
    onSettled?.();
  } catch (e: unknown) {
    toast.error(e instanceof Error ? e.message : "Error al registrar entrega");
  } finally {
    setDeliverLoading(false);
  }
}

export async function handleDeleteCustomer(
  deleteCustomerId: string,
  setDeletingCustomer: (v: boolean) => void,
  setDeleteCustomerId: (v: string | null) => void,
  onDeleted: () => void,
) {
  setDeletingCustomer(true);
  try {
    await customerService.deleteCustomer(deleteCustomerId);
    toast.success("Cliente eliminado");
    setDeleteCustomerId(null);
    onDeleted();
  } catch (err: unknown) {
    toast.error(err instanceof Error ? err.message : "Error al eliminar cliente");
  } finally {
    setDeletingCustomer(false);
  }
}

export async function handleDeleteQuote(
  deleteQuoteId: string,
  setDeletingQuote: (v: boolean) => void,
  setDeleteQuoteId: (v: string | null) => void,
  onDeleted: () => void,
) {
  setDeletingQuote(true);
  try {
    await quoteService.deleteQuote(deleteQuoteId);
    toast.success("Presupuesto eliminado");
    setDeleteQuoteId(null);
    onDeleted();
  } catch (err: unknown) {
    toast.error(err instanceof Error ? err.message : "Error al eliminar presupuesto");
  } finally {
    setDeletingQuote(false);
  }
}

"use client";

import { RefreshCw, Trash2 } from "lucide-react";
import dynamic from "next/dynamic";

import AddCustomerForm from "@/components/admin/AddCustomerForm";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";

const CreateQuoteForm = dynamic(
  () => import("@/components/admin/CreateQuoteForm"),
  {
    loading: () => (
      <div className="flex justify-center py-12">
        <RefreshCw className="h-6 w-6 animate-spin text-admin-text-tertiary" />
      </div>
    ),
    ssr: false,
  },
);

const CreatePrescriptionForm = dynamic(
  () => import("@/components/admin/CreatePrescriptionForm"),
  {
    loading: () => (
      <div className="flex justify-center py-12">
        <RefreshCw className="h-6 w-6 animate-spin text-admin-text-tertiary" />
      </div>
    ),
    ssr: false,
  },
);

interface DeleteDialogProps {
  open: boolean;
  loading: boolean;
  title: string;
  description: string;
  onCancel: () => void;
  onConfirm: () => void;
  confirmLabel?: string;
}

function ConfirmDeleteDialog({
  open,
  loading,
  title,
  description,
  onCancel,
  onConfirm,
  confirmLabel = "Eliminar",
}: DeleteDialogProps) {
  return (
    <Dialog open={open} onOpenChange={(o) => !o && onCancel()}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>{title}</DialogTitle>
          <DialogDescription>{description}</DialogDescription>
        </DialogHeader>
        <DialogFooter>
          <Button disabled={loading} variant="outline" onClick={onCancel}>
            Cancelar
          </Button>
          <Button disabled={loading} variant="destructive" onClick={onConfirm}>
            {loading ? (
              <>
                <RefreshCw className="h-4 w-4 animate-spin mr-2" />
                Eliminando...
              </>
            ) : (
              <>
                <Trash2 className="h-4 w-4 mr-2" />
                {confirmLabel}
              </>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

interface AddCustomerDialogProps {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  branchId: string;
  fieldOperationId: string;
  onSuccess: () => void;
}

function AddCustomerDialog({
  open,
  onOpenChange,
  branchId,
  fieldOperationId,
  onSuccess,
}: AddCustomerDialogProps) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>Nuevo cliente del operativo</DialogTitle>
          <DialogDescription>
            El cliente quedará vinculado a este operativo en terreno.
          </DialogDescription>
        </DialogHeader>
        <AddCustomerForm
          branchId={branchId}
          fieldOperationId={fieldOperationId}
          onCancel={() => onOpenChange(false)}
          onSuccess={onSuccess}
        />
      </DialogContent>
    </Dialog>
  );
}

interface CreateQuoteDialogProps {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  branchId: string;
  fieldOperationId: string;
  initialCustomerId?: string;
  onCancel: () => void;
  onSuccess: () => void;
}

function CreateQuoteDialog({
  open,
  onOpenChange,
  branchId,
  fieldOperationId,
  initialCustomerId,
  onCancel,
  onSuccess,
}: CreateQuoteDialogProps) {
  return (
    <Dialog
      open={open}
      onOpenChange={(o) => {
        onOpenChange(o);
        if (!o) onCancel();
      }}
    >
      <DialogContent className="max-w-[calc(100vw-2rem)] sm:max-w-4xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Nuevo presupuesto</DialogTitle>
          <DialogDescription>
            {initialCustomerId
              ? "Presupuesto para el cliente seleccionado."
              : "Solo se mostrarán clientes vinculados a este operativo."}
          </DialogDescription>
        </DialogHeader>
        <CreateQuoteForm
          initialBranchId={branchId}
          initialCustomerId={initialCustomerId}
          initialFieldOperationId={fieldOperationId}
          onCancel={onCancel}
          onSuccess={onSuccess}
        />
      </DialogContent>
    </Dialog>
  );
}

interface OpenCashDialogProps {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  amount: string;
  onAmountChange: (v: string) => void;
  onConfirm: () => void;
  loading: boolean;
}

function OpenCashDialog({
  open,
  onOpenChange,
  amount,
  onAmountChange,
  onConfirm,
  loading,
}: OpenCashDialogProps) {
  return (
    <Dialog
      open={open}
      onOpenChange={(o) => {
        onOpenChange(o);
        if (!o) onAmountChange("");
      }}
    >
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>Abrir caja del operativo</DialogTitle>
          <DialogDescription>
            Ingrese el monto inicial de efectivo para abrir la caja.
          </DialogDescription>
        </DialogHeader>
        <div className="space-y-4 py-2">
          <div>
            <label
              className="text-sm font-medium text-admin-text-primary"
              htmlFor="opening-cash"
            >
              Monto inicial
            </label>
            <Input
              className="mt-1"
              id="opening-cash"
              min={0}
              placeholder="0"
              step={0.01}
              type="number"
              value={amount}
              onChange={(e) => onAmountChange(e.target.value)}
            />
          </div>
        </div>
        <DialogFooter>
          <Button
            disabled={loading}
            variant="outline"
            onClick={() => {
              onOpenChange(false);
              onAmountChange("");
            }}
          >
            Cancelar
          </Button>
          <Button disabled={loading} onClick={onConfirm}>
            {loading ? "Abriendo…" : "Abrir caja"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

interface CreatePrescriptionDialogProps {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  customerId: string | null;
  onCancel: () => void;
  onSuccess: () => void;
}

function CreatePrescriptionDialog({
  open,
  onOpenChange,
  customerId,
  onCancel,
  onSuccess,
}: CreatePrescriptionDialogProps) {
  return (
    <Dialog
      open={open}
      onOpenChange={(o) => {
        onOpenChange(o);
        if (!o) onCancel();
      }}
    >
      <DialogContent className="max-w-[calc(100vw-2rem)] sm:max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Nueva receta</DialogTitle>
          <DialogDescription>
            Crear receta para el cliente del operativo.
          </DialogDescription>
        </DialogHeader>
        {customerId && (
          <CreatePrescriptionForm
            customerId={customerId}
            onCancel={onCancel}
            onSuccess={onSuccess}
          />
        )}
      </DialogContent>
    </Dialog>
  );
}

export {
  AddCustomerDialog,
  ConfirmDeleteDialog,
  CreatePrescriptionDialog,
  CreateQuoteDialog,
  OpenCashDialog,
};

