"use client";

import {
  AlertCircle,
  CheckCircle,
  ClipboardList,
  Eye,
  Factory,
  Package,
  RefreshCw,
  XCircle,
} from "lucide-react";
import Link from "next/link";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { formatPrice } from "@/lib/utils";

interface WorkOrderItem {
  id: string;
  work_order_number: string;
  status: string;
  total_amount: number;
  payment_status?: string;
  frame_name?: string;
  lens_type?: string;
  lens_material?: string;
  lab_name?: string;
  customer?: { first_name?: string; last_name?: string; email?: string };
}

interface FieldOpWorkOrdersSectionProps {
  workOrders: WorkOrderItem[];
  workOrdersLoading: boolean;
}

function getWorkOrderStatusBadge(status: string) {
  const config: Record<
    string,
    {
      variant: "default" | "secondary" | "outline" | "destructive";
      label: string;
      icon: typeof Package;
    }
  > = {
    quote: { variant: "outline", label: "Presupuesto", icon: Package },
    ordered: { variant: "secondary", label: "Ordenado", icon: Package },
    sent_to_lab: {
      variant: "secondary",
      label: "Enviado al Lab",
      icon: Package,
    },
    in_progress_lab: {
      variant: "default",
      label: "En Laboratorio",
      icon: Factory,
    },
    ready_at_lab: {
      variant: "secondary",
      label: "Listo en Lab",
      icon: CheckCircle,
    },
    received_from_lab: {
      variant: "secondary",
      label: "Recibido",
      icon: Package,
    },
    mounted: { variant: "secondary", label: "Montado", icon: Package },
    quality_check: {
      variant: "secondary",
      label: "Control Calidad",
      icon: Package,
    },
    ready_for_pickup: {
      variant: "default",
      label: "Listo para Retiro",
      icon: CheckCircle,
    },
    delivered: {
      variant: "default",
      label: "Entregado",
      icon: CheckCircle,
    },
    cancelled: {
      variant: "destructive",
      label: "Cancelado",
      icon: XCircle,
    },
    returned: {
      variant: "destructive",
      label: "Devuelto",
      icon: AlertCircle,
    },
  };
  const c = config[status] || {
    variant: "outline" as const,
    label: status,
    icon: Package,
  };
  const Icon = c.icon;
  return (
    <Badge className="flex items-center gap-1 w-fit" variant={c.variant}>
      <Icon className="h-3 w-3" />
      {c.label}
    </Badge>
  );
}

function getPaymentStatusBadge(status: string) {
  const config: Record<
    string,
    {
      variant: "default" | "secondary" | "outline" | "destructive";
      label: string;
    }
  > = {
    pending: { variant: "outline", label: "Pendiente" },
    partial: { variant: "secondary", label: "Parcial" },
    paid: { variant: "default", label: "Pagado" },
    refunded: { variant: "destructive", label: "Reembolsado" },
  };
  const c = config[status] || { variant: "outline" as const, label: status };
  return <Badge variant={c.variant}>{c.label}</Badge>;
}

export default function FieldOpWorkOrdersSection({
  workOrders,
  workOrdersLoading,
}: FieldOpWorkOrdersSectionProps) {
  return (
    <div className="rounded-xl border border-admin-border-primary/30 bg-admin-bg-tertiary shadow-[0_1px_3px_rgba(0,0,0,0.3)] overflow-hidden">
      <div className="p-4 sm:p-6 border-b border-admin-border-primary/20">
        <h3 className="flex items-center gap-2 text-admin-text-primary font-semibold">
          <ClipboardList className="h-5 w-5 shrink-0" />
          Trabajos del operativo
        </h3>
      </div>
      <div className="overflow-x-auto">
        {workOrdersLoading ? (
          <div className="p-8 flex justify-center">
            <RefreshCw className="h-6 w-6 animate-spin text-admin-text-tertiary" />
          </div>
        ) : workOrders.length === 0 ? (
          <p className="p-6 text-admin-text-tertiary text-sm">
            No hay trabajos vinculados a este operativo.
          </p>
        ) : (
          <div className="overflow-x-auto -mx-4 px-4 md:mx-0 md:px-0">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="text-admin-text-tertiary font-semibold">
                    Número
                  </TableHead>
                  <TableHead className="text-admin-text-tertiary font-semibold">
                    Cliente
                  </TableHead>
                  <TableHead className="text-admin-text-tertiary font-semibold">
                    Marco
                  </TableHead>
                  <TableHead className="text-admin-text-tertiary font-semibold">
                    Lente
                  </TableHead>
                  <TableHead className="text-admin-text-tertiary font-semibold">
                    Laboratorio
                  </TableHead>
                  <TableHead className="text-admin-text-tertiary font-semibold">
                    Estado
                  </TableHead>
                  <TableHead className="text-admin-text-tertiary font-semibold">
                    Pago
                  </TableHead>
                  <TableHead className="text-admin-text-tertiary font-semibold text-right">
                    Total
                  </TableHead>
                  <TableHead className="text-admin-text-tertiary font-semibold">
                    Acciones
                  </TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {workOrders.map((wo) => (
                  <TableRow className="hover:bg-[#AE000025]" key={wo.id}>
                    <TableCell className="font-medium text-admin-text-primary">
                      {wo.work_order_number}
                    </TableCell>
                    <TableCell>
                      <div>
                        <div className="font-medium text-admin-text-primary">
                          {wo.customer
                            ? `${wo.customer.first_name || ""} ${wo.customer.last_name || ""}`.trim() ||
                              "—"
                            : "—"}
                        </div>
                        {wo.customer?.email && (
                          <div className="text-sm text-admin-text-tertiary">
                            {wo.customer.email}
                          </div>
                        )}
                      </div>
                    </TableCell>
                    <TableCell className="text-admin-text-primary">
                      {wo.frame_name || "-"}
                    </TableCell>
                    <TableCell>
                      <div>
                        <div className="font-medium text-admin-text-primary">
                          {wo.lens_type || "-"}
                        </div>
                        {wo.lens_material && (
                          <div className="text-sm text-admin-text-tertiary">
                            {wo.lens_material}
                          </div>
                        )}
                      </div>
                    </TableCell>
                    <TableCell>
                      {wo.lab_name ? (
                        <div className="flex items-center gap-1">
                          <Factory className="h-3 w-3" />
                          <span className="text-sm text-admin-text-primary">
                            {wo.lab_name}
                          </span>
                        </div>
                      ) : (
                        "-"
                      )}
                    </TableCell>
                    <TableCell>
                      {getWorkOrderStatusBadge(wo.status)}
                    </TableCell>
                    <TableCell>
                      {getPaymentStatusBadge(
                        wo.payment_status || "pending",
                      )}
                    </TableCell>
                    <TableCell className="text-right font-semibold text-admin-success">
                      {formatPrice(wo.total_amount)}
                    </TableCell>
                    <TableCell>
                      <Link href={`/admin/work-orders/${wo.id}`}>
                        <Button size="sm" variant="outline">
                          <Eye className="h-4 w-4 mr-1" />
                          Ver
                        </Button>
                      </Link>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { ArrowLeft, Package, RefreshCw } from "lucide-react";
import Link from "next/link";
import { useParams, useRouter } from "next/navigation";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { useBranch } from "@/hooks/useBranch";
import { appLogger } from '@/lib/logger';
import { getBranchHeader } from "@/lib/utils/branch";

interface Product {
  id: string;
  name: string;
  sku: string | null;
  product_type: string;
}

interface Operation {
  id: string;
  name: string;
  branch_id: string;
  status: string;
}

export default function PrepareFieldOperationPage() {
  const params = useParams();
  const router = useRouter();
  const id = params.id as string;
  const { currentBranchId } = useBranch();
  const [operation, setOperation] = useState<Operation | null>(null);
  const [products, setProducts] = useState<Product[]>([]);
  const [productStocks, setProductStocks] = useState<Record<string, number>>(
    {},
  );
  const [quantities, setQuantities] = useState<Record<string, number>>({});
  const [loading, setLoading] = useState(true);
  const [transferring, setTransferring] = useState(false);

  useEffect(() => {
    if (id) {
      fetchOperation();
    }
  }, [id]);

  useEffect(() => {
    if (operation?.branch_id) {
      fetchProductsWithStock();
    }
  }, [operation?.branch_id]);

  const fetchOperation = async () => {
    try {
      const headers = getBranchHeader(currentBranchId);
      const res = await fetch(`/api/admin/field-operations/${id}`, { headers });
      if (!res.ok) throw new Error("Operativo no encontrado");
      const data = await res.json();
      setOperation(data?.data?.fieldOperation || null);
    } catch {
      toast.error("Error al cargar operativo");
      router.push("/admin/field-operations");
    } finally {
      setLoading(false);
    }
  };

  const fetchProductsWithStock = async () => {
    if (!operation?.branch_id) return;
    try {
      const headers = getBranchHeader(operation.branch_id);
      const res = await fetch(
        `/api/admin/products?limit=200&branch_id=${operation.branch_id}&in_stock=true`,
        { headers },
      );
      if (!res.ok) return;
      const data = await res.json();
      const items = data?.data ?? data?.products ?? [];
      const frames = items.filter(
        (p: Product & { product_type?: string }) =>
          p.product_type === "frame" || !p.product_type,
      );
      setProducts(frames);

      const stocks: Record<string, number> = {};
      for (const p of frames) {
        const qty =
          (p as { total_available_quantity?: number })
            .total_available_quantity ??
          (p as { total_inventory_quantity?: number })
            .total_inventory_quantity ??
          0;
        if (qty > 0) stocks[p.id] = qty;
      }
      setProductStocks(stocks);
      setQuantities({});
    } catch (e) {
      appLogger.error("Error fetching products:", e);
    }
  };

  const setQuantity = (productId: string, value: number) => {
    setQuantities((prev) => ({
      ...prev,
      [productId]: Math.max(0, value),
    }));
  };

  const handleTransferAll = async (e: React.FormEvent) => {
    e.preventDefault();
    const items = Object.entries(quantities)
      .filter(([, qty]) => qty > 0)
      .map(([product_id, quantity]) => ({ product_id, quantity }));

    if (items.length === 0) {
      toast.error("Indica las cantidades a transferir");
      return;
    }

    for (const { product_id, quantity } of items) {
      const available = productStocks[product_id] ?? 0;
      if (quantity > available) {
        const p = products.find((x) => x.id === product_id);
        toast.error(
          `Stock insuficiente para ${p?.name ?? product_id}. Disponible: ${available}`,
        );
        return;
      }
    }

    setTransferring(true);
    try {
      const headers: HeadersInit = {
        "Content-Type": "application/json",
        ...getBranchHeader(currentBranchId),
      };

      const res = await fetch(
        `/api/admin/field-operations/${id}/transfer-stock`,
        {
          method: "POST",
          headers,
          body: JSON.stringify({ items }),
        },
      );

      const data = await res.json();

      if (!res.ok) {
        throw new Error(data?.error || "Error al transferir");
      }

      const successCount = data?.data?.successCount ?? items.length;
      toast.success(`${successCount} producto(s) transferido(s) correctamente`);
      setQuantities({});
      fetchOperation();
      fetchProductsWithStock();
    } catch (error) {
      toast.error(
        error instanceof Error ? error.message : "Error al transferir stock",
      );
    } finally {
      setTransferring(false);
    }
  };

  if (loading || !operation) {
    return (
      <div className="flex min-h-[200px] items-center justify-center">
        <RefreshCw className="h-8 w-8 animate-spin text-admin-text-tertiary" />
      </div>
    );
  }

  const productsWithStock = products.filter(
    (p) => (productStocks[p.id] ?? 0) > 0,
  );
  const hasItemsToTransfer = Object.values(quantities).some((q) => q > 0);

  return (
    <div className="space-y-6">
      <div className="space-y-4">
        <Link
          className="inline-flex items-center gap-2 text-sm text-admin-text-tertiary hover:text-admin-text-primary min-h-[44px] items-center"
          href={`/admin/field-operations/${id}`}
        >
          <ArrowLeft className="h-4 w-4 shrink-0" />
          <span className="truncate max-w-[calc(100vw-8rem)]">
            Volver a {operation.name}
          </span>
        </Link>
        <div>
          <h1 className="text-2xl sm:text-3xl font-bold text-admin-text-primary tracking-tight">
            Transferir stock a bodega móvil
          </h1>
          <p className="text-sm text-admin-text-tertiary mt-1">
            Indica las cantidades a trasladar desde la sucursal al operativo
          </p>
        </div>
      </div>

      <div className="rounded-xl border border-admin-border-primary/30 bg-admin-bg-tertiary shadow-[0_1px_3px_rgba(0,0,0,0.3)] overflow-hidden">
        <div className="p-4 sm:p-6 border-b border-admin-border-primary/20">
          <h3 className="flex items-center gap-2 text-admin-text-primary font-semibold">
            <Package className="h-5 w-5 shrink-0" />
            Productos con stock disponible
          </h3>
        </div>
        <div className="p-4 sm:p-6 pt-0">
          {productsWithStock.length === 0 ? (
            <p className="py-6 text-admin-text-tertiary text-sm">
              No hay productos con stock en la sucursal.{" "}
              <Link
                className="text-admin-accent-primary hover:underline"
                href={`/admin/field-operations/${id}`}
              >
                Volver al operativo
              </Link>
            </p>
          ) : (
            <form onSubmit={handleTransferAll}>
              <div className="overflow-x-auto">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead className="text-admin-text-tertiary font-semibold">
                        Producto
                      </TableHead>
                      <TableHead className="text-admin-text-tertiary font-semibold">
                        SKU
                      </TableHead>
                      <TableHead className="text-admin-text-tertiary font-semibold text-right">
                        Disponible
                      </TableHead>
                      <TableHead className="text-admin-text-tertiary font-semibold text-right w-32">
                        Cantidad
                      </TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {productsWithStock.map((p) => (
                      <TableRow className="hover:bg-[#AE000025]" key={p.id}>
                        <TableCell className="font-medium text-admin-text-primary">
                          {p.name}
                        </TableCell>
                        <TableCell className="text-admin-text-tertiary">
                          {p.sku || "—"}
                        </TableCell>
                        <TableCell className="text-right text-admin-text-primary">
                          {productStocks[p.id] ?? 0}
                        </TableCell>
                        <TableCell className="text-right">
                          <Input
                            className="h-11 sm:h-10 min-h-[44px] w-24 text-right"
                            max={productStocks[p.id] ?? 0}
                            min={0}
                            type="number"
                            value={quantities[p.id] ?? 0}
                            onChange={(e) =>
                              setQuantity(p.id, parseInt(e.target.value) || 0)
                            }
                          />
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>
              <div className="flex justify-end pt-4 sm:pt-6">
                <Button
                  className="min-h-[44px]"
                  disabled={transferring || !hasItemsToTransfer}
                  type="submit"
                >
                  {transferring ? "Transfiriendo..." : "Transferir todo"}
                </Button>
              </div>
            </form>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import {
  Calendar,
  ChevronLeft,
  ChevronRight,
  Eye,
  MapPin,
  Plus,
  RefreshCw,
} from "lucide-react";
import Link from "next/link";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { useBranch } from "@/hooks/useBranch";
import {
  extractDataFromResponse,
  extractPaginationFromResponse,
} from "@/lib/api/response-helpers";
import { appLogger } from '@/lib/logger';
import { formatDate } from "@/lib/utils";
import { getBranchHeader } from "@/lib/utils/branch";

interface FieldOperation {
  id: string;
  name: string;
  scheduled_date: string;
  location: string | null;
  branch_id: string;
  organization_id: string;
  status: string;
  created_at: string;
}

const STATUS_CONFIG: Record<
  string,
  {
    label: string;
    variant: "default" | "secondary" | "outline" | "destructive";
  }
> = {
  draft: { label: "Borrador", variant: "outline" },
  prepared: { label: "Preparado", variant: "secondary" },
  in_progress: { label: "En terreno", variant: "default" },
  completed: { label: "Completado", variant: "secondary" },
  cancelled: { label: "Cancelado", variant: "destructive" },
};

export default function FieldOperationsContent() {
  const {
    currentBranchId,
    isSuperAdmin,
    branches,
    isLoading: branchLoading,
  } = useBranch();
  const [operations, setOperations] = useState<FieldOperation[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [totalOperations, setTotalOperations] = useState(0);
  const perPage = 20;

  useEffect(() => {
    if (!branchLoading) {
      fetchOperations();
    }
  }, [currentPage, statusFilter, currentBranchId, branchLoading]);

  const fetchOperations = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams({
        page: currentPage.toString(),
        limit: perPage.toString(),
        ...(statusFilter !== "all" && { status: statusFilter }),
      });

      const headers: HeadersInit = {
        ...getBranchHeader(currentBranchId),
      };

      const response = await fetch(`/api/admin/field-operations?${params}`, {
        headers,
      });
      if (!response.ok) {
        throw new Error("Error al cargar operativos");
      }

      const data = await response.json();
      const pagination = extractPaginationFromResponse(data);
      setOperations(extractDataFromResponse<FieldOperation>(data));
      setTotalPages(pagination.totalPages || 1);
      setTotalOperations(pagination.total || 0);
    } catch (error) {
      appLogger.error("Error fetching field operations:", error);
      toast.error("Error al cargar operativos");
    } finally {
      setLoading(false);
    }
  };

  const getStatusBadge = (status: string) => {
    const config = STATUS_CONFIG[status] || {
      label: status,
      variant: "outline" as const,
    };
    return <Badge variant={config.variant}>{config.label}</Badge>;
  };

  const filteredOperations = operations.filter(
    (op) =>
      !searchTerm ||
      op.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (op.location?.toLowerCase().includes(searchTerm.toLowerCase()) ?? false),
  );

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="space-y-4">
        <h1 className="text-2xl sm:text-3xl font-bold text-admin-text-primary tracking-tight">
          Operativos en Terreno
        </h1>
        <p className="text-sm text-admin-text-tertiary">
          Gestiona operativos móviles y bodega temporal
        </p>
        <div className="flex justify-end">
          <Link href="/admin/field-operations/new">
            <Button className="min-h-[44px]">
              <Plus className="mr-2 h-4 w-4" />
              Nuevo operativo
            </Button>
          </Link>
        </div>
      </div>

      {/* Lista de operativos */}
      <Card className="bg-admin-bg-tertiary shadow-[0_1px_3px_rgba(0,0,0,0.3)] hover:shadow-[0_4px_12px_rgba(0,0,0,0.4)]">
        <CardHeader className="p-4 sm:p-6">
          <CardTitle className="flex items-center gap-2 text-admin-text-primary">
            <MapPin className="h-5 w-5 shrink-0" />
            Lista de operativos
          </CardTitle>
          <div className="flex flex-col gap-4 pt-4 sm:flex-row sm:items-center sm:gap-3">
            <div className="flex-1 min-w-0">
              <Input
                className="h-11 sm:h-10 w-full sm:max-w-sm"
                placeholder="Buscar por nombre o ubicación..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
            <Select
              value={statusFilter}
              onValueChange={(v) => {
                setStatusFilter(v);
                setCurrentPage(1);
              }}
            >
              <SelectTrigger className="h-11 sm:h-10 w-full sm:w-[180px] min-h-[44px]">
                <SelectValue placeholder="Estado" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Todos</SelectItem>
                {Object.entries(STATUS_CONFIG).map(([value, { label }]) => (
                  <SelectItem key={value} value={value}>
                    {label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <Button
              className="h-11 w-11 min-h-[44px] shrink-0"
              disabled={loading}
              size="icon"
              variant="outline"
              onClick={fetchOperations}
            >
              <RefreshCw
                className={`h-4 w-4 ${loading ? "animate-spin" : ""}`}
              />
            </Button>
          </div>
        </CardHeader>
        <CardContent className="p-4 sm:p-6 pt-0 sm:pt-0">
          {loading ? (
            <div className="flex items-center justify-center py-12">
              <RefreshCw className="h-8 w-8 animate-spin text-admin-text-tertiary" />
            </div>
          ) : filteredOperations.length === 0 ? (
            <div className="py-12 text-center text-admin-text-tertiary">
              No hay operativos.{" "}
              <Link
                className="text-primary underline"
                href="/admin/field-operations/new"
              >
                Crear uno
              </Link>
            </div>
          ) : (
            <>
              {/* Desktop: table | Mobile: cards */}
              <div className="hidden md:block overflow-x-auto -mx-4 px-4 md:mx-0 md:px-0">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Nombre</TableHead>
                      <TableHead>Fecha</TableHead>
                      <TableHead>Ubicación</TableHead>
                      <TableHead>Estado</TableHead>
                      <TableHead className="text-right">Acciones</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {filteredOperations.map((op) => (
                      <TableRow
                        className="hover:bg-[#AE000025] transition-colors"
                        key={op.id}
                      >
                        <TableCell className="font-medium">{op.name}</TableCell>
                        <TableCell>
                          <span className="flex items-center gap-1">
                            <Calendar className="h-4 w-4 text-admin-text-tertiary shrink-0" />
                            {formatDate(op.scheduled_date)}
                          </span>
                        </TableCell>
                        <TableCell className="text-admin-text-tertiary">
                          {op.location || "—"}
                        </TableCell>
                        <TableCell>{getStatusBadge(op.status)}</TableCell>
                        <TableCell className="text-right">
                          <Link href={`/admin/field-operations/${op.id}`}>
                            <Button
                              className="min-h-[44px]"
                              size="sm"
                              variant="ghost"
                            >
                              <Eye className="mr-1 h-4 w-4" />
                              Ver
                            </Button>
                          </Link>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>

              {/* Mobile: card list */}
              <div className="md:hidden space-y-3">
                {filteredOperations.map((op) => (
                  <Link
                    className="block"
                    href={`/admin/field-operations/${op.id}`}
                    key={op.id}
                  >
                    <div className="rounded-xl border border-border bg-card p-4 active:bg-muted/50 transition-colors">
                      <div className="flex items-start justify-between gap-3">
                        <div className="min-w-0 flex-1">
                          <p className="font-medium text-admin-text-primary truncate">
                            {op.name}
                          </p>
                          <p className="mt-1 flex items-center gap-1 text-sm text-admin-text-tertiary">
                            <Calendar className="h-3.5 w-3.5 shrink-0" />
                            {formatDate(op.scheduled_date)}
                          </p>
                          {op.location && (
                            <p className="mt-0.5 flex items-center gap-1 text-xs text-admin-text-tertiary truncate">
                              <MapPin className="h-3 w-3 shrink-0" />
                              {op.location}
                            </p>
                          )}
                        </div>
                        <div className="flex flex-col items-end gap-2 shrink-0">
                          {getStatusBadge(op.status)}
                          <span className="flex items-center gap-1 text-sm text-admin-text-tertiary">
                            <Eye className="h-4 w-4" />
                            Ver
                          </span>
                        </div>
                      </div>
                    </div>
                  </Link>
                ))}
              </div>

              {totalPages > 1 && (
                <div className="mt-4 flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-4">
                  <p className="text-sm text-admin-text-tertiary order-2 sm:order-1">
                    {totalOperations} operativo(s) en total
                  </p>
                  <div className="flex items-center justify-center sm:justify-end gap-2 order-1 sm:order-2">
                    <Button
                      className="min-h-[44px]"
                      disabled={currentPage <= 1}
                      size="sm"
                      variant="outline"
                      onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
                    >
                      <ChevronLeft className="h-4 w-4" />
                    </Button>
                    <span className="text-sm text-admin-text-primary min-w-[120px] text-center">
                      Página {currentPage} de {totalPages}
                    </span>
                    <Button
                      className="min-h-[44px]"
                      disabled={currentPage >= totalPages}
                      size="sm"
                      variant="outline"
                      onClick={() =>
                        setCurrentPage((p) => Math.min(totalPages, p + 1))
                      }
                    >
                      <ChevronRight className="h-4 w-4" />
                    </Button>
                  </div>
                </div>
              )}
            </>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { ArrowLeft } from "lucide-react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useBranch } from "@/hooks/useBranch";
import { getBranchHeader } from "@/lib/utils/branch";

export default function NewFieldOperationPage() {
  const router = useRouter();
  const { currentBranchId, branches, isSuperAdmin } = useBranch();
  const [loading, setLoading] = useState(false);
  const [name, setName] = useState("");
  const [scheduledDate, setScheduledDate] = useState("");
  const [location, setLocation] = useState("");
  const [branchId, setBranchId] = useState(currentBranchId || "");

  useEffect(() => {
    if (currentBranchId && !branchId) {
      setBranchId(currentBranchId);
    }
  }, [currentBranchId, branchId]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim() || !scheduledDate || !branchId) {
      toast.error("Nombre, fecha y sucursal son requeridos");
      return;
    }

    setLoading(true);
    try {
      const headers: HeadersInit = {
        "Content-Type": "application/json",
        ...getBranchHeader(currentBranchId),
      };

      const response = await fetch("/api/admin/field-operations", {
        method: "POST",
        headers,
        body: JSON.stringify({
          name: name.trim(),
          scheduled_date: scheduledDate,
          location: location.trim() || null,
          branch_id: branchId,
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || "Error al crear operativo");
      }

      const id = data?.data?.fieldOperation?.id;
      if (id) {
        toast.success("Operativo creado");
        router.push(`/admin/field-operations/${id}`);
      } else {
        toast.error("Respuesta inválida del servidor");
      }
    } catch (error) {
      toast.error(
        error instanceof Error ? error.message : "Error al crear operativo",
      );
    } finally {
      setLoading(false);
    }
  };

  const effectiveBranches = branches || [];

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="space-y-4">
        <Link
          className="inline-flex items-center gap-2 text-sm text-admin-text-tertiary hover:text-admin-text-primary min-h-[44px] items-center"
          href="/admin/field-operations"
        >
          <ArrowLeft className="h-4 w-4 shrink-0" />
          Volver a operativos
        </Link>
        <div>
          <h1 className="text-2xl sm:text-3xl font-bold text-admin-text-primary tracking-tight">
            Nuevo operativo
          </h1>
          <p className="text-sm text-admin-text-tertiary mt-1">
            Crea un operativo para preparar stock y gestionar ventas en terreno
          </p>
        </div>
      </div>

      {/* Form card - centered, max width for readability */}
      <div className="max-w-xl mx-auto">
