  requester_email: string;
  requester_name: string | null;
  assigned_to_user?: { email: string } | null;
}

const statusLabels: Record<string, string> = {
  open: "Abierto",
  assigned: "Asignado",
  in_progress: "En Progreso",
  waiting_customer: "Esperando Tu Respuesta",
  resolved: "Resuelto",
  closed: "Cerrado",
};

const statusColors: Record<string, string> = {
  open: "bg-blue-100 text-blue-800",
  assigned: "bg-yellow-100 text-yellow-800",
  in_progress: "bg-purple-100 text-purple-800",
  waiting_customer: "bg-orange-100 text-orange-800",
  resolved: "bg-green-100 text-green-800",
  closed: "bg-gray-100 text-gray-800",
};

const priorityLabels: Record<string, string> = {
  low: "Baja",
  medium: "Media",
  high: "Alta",
  urgent: "Urgente",
};

const categoryLabels: Record<string, string> = {
  technical: "Técnico",
  billing: "Facturación",
  feature_request: "Funcionalidad",
  bug_report: "Bug",
  account: "Cuenta",
  other: "Otro",
};

/**
 * Página de detalle de ticket de ayuda (Centro de Ayuda).
 * Renderiza el ticket directamente aquí - NO redirige a saas-management
 * (que requiere root y redirige a dashboard).
 */
export default function HelpTicketDetailPage() {
  const router = useRouter();
  const params = useParams();
  const ticketId = params.id as string;

  const [ticket, setTicket] = useState<Ticket | null>(null);
  const [messages, setMessages] = useState<TicketMessage[]>([]);
  const [loading, setLoading] = useState(true);
  const [sendingMessage, setSendingMessage] = useState(false);

  const {
    register,
    handleSubmit,
    formState: { errors },
    reset,
  } = useForm<MessageForm>({
    resolver: zodResolver(createSaasSupportMessageSchema),
    defaultValues: {
      message: "",
      is_internal: false,
      message_type: "message",
      attachments: [],
    },
  });

  useEffect(() => {
    fetchTicket();
    fetchMessages();
  }, [ticketId]);

  const fetchTicket = async () => {
    try {
      const response = await fetch(
        `/api/admin/saas-management/support/tickets/${ticketId}`,
      );

      if (!response.ok) {
        if (response.status === 403) {
          toast.error("No tienes acceso a este ticket");
          router.push("/admin/help");
          return;
        }
        throw new Error("Error al cargar el ticket");
      }

      const data = await response.json();
      setTicket(data.ticket);
    } catch (err) {
      toast.error("Error al cargar el ticket");
      router.push("/admin/help");
    } finally {
      setLoading(false);
    }
  };

  const fetchMessages = async () => {
    try {
      const response = await fetch(
        `/api/admin/saas-management/support/tickets/${ticketId}/messages`,
      );

      if (response.ok) {
        const data = await response.json();
        setMessages(data.messages || []);
      }
    } catch (err) {
      appLogger.error("Error fetching messages:", err);
    }
  };

  const onSubmitMessage: SubmitHandler<MessageForm> = async (data) => {
    setSendingMessage(true);
    try {
      const response = await fetch(
        `/api/admin/saas-management/support/tickets/${ticketId}/messages`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ ...data, is_internal: false }),
        },
      );

      if (!response.ok) {
        const result = await response.json();
        throw new Error(result.error || "Error al enviar mensaje");
      }

      toast.success("Mensaje enviado exitosamente");
      reset();
      fetchMessages();
      fetchTicket();
    } catch (err) {
      toast.error(
        err instanceof Error ? err.message : "Error al enviar mensaje",
      );
    } finally {
      setSendingMessage(false);
    }
  };

  const copyTicketNumber = () => {
    if (ticket?.ticket_number) {
      navigator.clipboard.writeText(ticket.ticket_number);
      toast.success("Número de ticket copiado");
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 py-12 px-4 sm:px-6 lg:px-8">
        <div className="max-w-4xl mx-auto">
          <div className="flex items-center justify-center py-12">
            <Loader2 className="h-8 w-8 animate-spin text-blue-600" />
          </div>
        </div>
      </div>
    );
  }

  if (!ticket) {
    return null;
  }

  return (
    <div className="space-y-6 p-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Button
            size="icon"
            variant="ghost"
            onClick={() => router.push("/admin/help")}
          >
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div>
            <div className="flex items-center gap-3">
              <h1 className="text-2xl font-bold text-gray-900">
                Ticket #{ticket.ticket_number}
              </h1>
              <Button
                size="icon"
                title="Copiar número de ticket"
                variant="ghost"
                onClick={copyTicketNumber}
              >
                <Copy className="h-4 w-4" />
              </Button>
            </div>
            <p className="text-gray-600 mt-1">{ticket.subject}</p>
          </div>
        </div>
        <div className="flex gap-2">
          <Badge className={statusColors[ticket.status]}>
            {statusLabels[ticket.status]}
          </Badge>
          <Badge variant="outline">{priorityLabels[ticket.priority]}</Badge>
          <Badge variant="outline">{categoryLabels[ticket.category]}</Badge>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Main Content */}
        <div className="lg:col-span-2 space-y-6">
          <Card>
            <CardHeader>
              <CardTitle>Detalles del Ticket</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div>
                <Label className="text-sm font-medium text-gray-700">
                  Descripción
                </Label>
                <p className="mt-1 text-gray-900 whitespace-pre-wrap">
                  {ticket.description}
                </p>
              </div>
              <div className="flex items-center gap-4 text-sm text-gray-500">
                <span className="flex items-center gap-1">
                  <Calendar className="h-4 w-4" />
                  {new Date(ticket.created_at).toLocaleString("es-CL")}
                </span>
                {ticket.assigned_to_user && (
                  <span>Asignado a: {ticket.assigned_to_user.email}</span>
                )}
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <MessageSquare className="h-5 w-5" />
                Conversación ({messages.length})
              </CardTitle>
            </CardHeader>
            <CardContent>
              {messages.length === 0 ? (
                <div className="text-center py-8 text-gray-500">
                  <MessageSquare className="h-12 w-12 mx-auto mb-4 text-gray-400" />
                  <p>No hay mensajes aún</p>
                </div>
              ) : (
                <div className="space-y-4">
                  {messages
                    .filter((m) => !m.is_internal)
                    .map((msg) => (
                      <div
                        className={`p-4 rounded-lg border ${
                          msg.is_from_customer
                            ? "bg-blue-50 border-blue-200"
                            : "bg-gray-50 border-gray-200"
                        }`}
                        key={msg.id}
                      >
                        <div className="flex items-start justify-between mb-2">
                          <div className="flex items-center gap-2">
                            <User className="h-4 w-4 text-gray-500" />
                            <span className="font-medium text-sm">
                              {msg.sender_name}
                            </span>
                          </div>
                          <span className="text-xs text-gray-500">
                            {new Date(msg.created_at).toLocaleString("es-CL")}
                          </span>
                        </div>
                        <p className="text-gray-900 whitespace-pre-wrap">
                          {msg.message}
                        </p>
                      </div>
                    ))}
                </div>
              )}
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle>Responder</CardTitle>
            </CardHeader>
            <CardContent>
              <form
                className="space-y-4"
                onSubmit={handleSubmit(onSubmitMessage)}
              >
                <div className="space-y-2">
                  <Label htmlFor="message">
                    Mensaje <span className="text-red-500">*</span>
                  </Label>
                  <Textarea
                    id="message"
                    {...register("message")}
                    className={errors.message ? "border-red-500" : ""}
                    placeholder="Escribe tu respuesta aquí..."
                    rows={6}
                  />
                  {errors.message && (
                    <p className="text-sm text-red-500">
                      {String(errors.message.message)}
                    </p>
                  )}
                </div>

                <Button
                  className="w-full"
                  disabled={sendingMessage}
                  type="submit"
                >
                  {sendingMessage ? (
                    <>
                      <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                      Enviando...
                    </>
                  ) : (
                    <>
                      <Send className="mr-2 h-4 w-4" />
                      Enviar Mensaje
                    </>
                  )}
                </Button>
              </form>
            </CardContent>
          </Card>
        </div>

        {/* Sidebar */}
        <div>
          <Card>
            <CardHeader>
              <CardTitle className="text-lg">Información</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div>
                <Label className="text-xs text-gray-500">Creado</Label>
                <p className="text-sm font-medium">
                  {new Date(ticket.created_at).toLocaleString("es-CL")}
                </p>
              </div>
              <div>
                <Label className="text-xs text-gray-500">Solicitante</Label>
                <p className="text-sm font-medium">
                  {ticket.requester_name || ticket.requester_email}
                </p>
                <p className="text-xs text-gray-500">
                  {ticket.requester_email}
                </p>
              </div>
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}

import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { renderHook, waitFor } from "@testing-library/react";
import type { PropsWithChildren } from "react";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { useAnalytics } from "../useAnalytics";

const mockFetch = vi.fn();
global.fetch = mockFetch;

function createWrapper() {
  const queryClient = new QueryClient({
    defaultOptions: { queries: { retry: false } },
  });
  const Wrapper = ({ children }: PropsWithChildren) => (
    <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>
  );
  Wrapper.displayName = "TestWrapper";
  return Wrapper;
}

describe("useAnalytics", () => {
  beforeEach(() => {
    mockFetch.mockReset();
  });

  it("fetches analytics data for a specific branch", async () => {
    const analyticsData = { kpis: { totalRevenue: 50000 } };
    mockFetch.mockResolvedValueOnce({
      ok: true,
      json: async () => ({ success: true, data: { analytics: analyticsData } }),
    });

    const { result } = renderHook(
      () => useAnalytics({ branchId: "branch-abc", period: "30" }),
      { wrapper: createWrapper() },
    );

    await waitFor(() => expect(result.current.isSuccess).toBe(true));

    expect(result.current.data).toEqual(analyticsData);
    expect(mockFetch).toHaveBeenCalledWith(
      "/api/admin/analytics/dashboard?period=30",
      expect.objectContaining({
        headers: expect.objectContaining({ "x-branch-id": "branch-abc" }),
      }),
    );
  });

  it("uses global header when branchId is null", async () => {
    const analyticsData = { kpis: { totalRevenue: 100000 } };
    mockFetch.mockResolvedValueOnce({
      ok: true,
      json: async () => ({ success: true, data: { analytics: analyticsData } }),
    });

    const { result } = renderHook(
      () => useAnalytics({ branchId: null, period: "90" }),
      { wrapper: createWrapper() },
    );

    await waitFor(() => expect(result.current.isSuccess).toBe(true));

    expect(result.current.data).toEqual(analyticsData);
    expect(mockFetch).toHaveBeenCalledWith(
      "/api/admin/analytics/dashboard?period=90",
      expect.objectContaining({
        headers: expect.objectContaining({ "x-branch-id": "global" }),
      }),
    );
  });

  it("falls back when analytics is at top level (no data wrapper)", async () => {
    const analyticsData = { kpis: { totalRevenue: 25000 } };
    mockFetch.mockResolvedValueOnce({
      ok: true,
      json: async () => ({ success: true, analytics: analyticsData }),
    });

    const { result } = renderHook(
      () => useAnalytics({ branchId: "branch-xyz", period: "30" }),
      { wrapper: createWrapper() },
    );

    await waitFor(() => expect(result.current.isSuccess).toBe(true));

    expect(result.current.data).toEqual(analyticsData);
  });

  it("throws when API returns success: false", async () => {
    mockFetch.mockResolvedValueOnce({
      ok: true,
      json: async () => ({
        success: false,
        error: { message: "No data for period" },
      }),
    });

    const { result } = renderHook(
      () => useAnalytics({ branchId: "branch-abc", period: "30" }),
      { wrapper: createWrapper() },
    );

    await waitFor(() => expect(result.current.isError).toBe(true));
    expect(result.current.error).toBeDefined();
  });

  it("throws on non-ok response", async () => {
    mockFetch.mockResolvedValueOnce({
      ok: false,
      status: 500,
      json: async () => ({}),
    });

    const { result } = renderHook(
      () => useAnalytics({ branchId: "branch-abc", period: "30" }),
      { wrapper: createWrapper() },
    );

    await waitFor(() => expect(result.current.isError).toBe(true));
    expect(result.current.error).toBeDefined();
  });

  it("has correct queryKey shape", () => {
    // QueryClientProvider hydration needed to observe queryKey via cache
    const client = new QueryClient({
      defaultOptions: { queries: { retry: false } },
    });
    const wrapper = ({ children }: PropsWithChildren) => (
      <QueryClientProvider client={client}>{children}</QueryClientProvider>
    );

    renderHook(
      () => useAnalytics({ branchId: "branch-1", period: "60" }),
      { wrapper },
    );

    const query = client.getQueryCache().find({ queryKey: ["admin", "analytics", "branch-1", "60"] });
    expect(query).toBeDefined();
    expect(query?.queryKey).toEqual(["admin", "analytics", "branch-1", "60"]);
  });
});

