"use client";

import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { useAuthContext } from "@/contexts/AuthContext";
import { useBranch } from "@/hooks/useBranch";
import { useRoot } from "@/hooks/useRoot";
import { appLogger } from '@/lib/logger';
import { createClient } from "@/utils/supabase/client";

export interface AdminNotification {
  id: string;
  type: string;
  priority: "low" | "medium" | "high" | "urgent";
  title: string;
  message: string;
  related_entity_type?: string;
  related_entity_id?: string;
  action_url?: string;
  action_label?: string;
  metadata?: unknown;
  is_read: boolean;
  created_at: string;
}

interface Filters {
  unreadOnly: boolean;
  type: string;
  priority: string;
}

export function useNotifications() {
  const router = useRouter();
  const { user, loading: authLoading } = useAuthContext();
  const { currentBranchId, isGlobalView, isSuperAdmin } = useBranch();
  const { isRoot } = useRoot();
  const [notifications, setNotifications] = useState<AdminNotification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [loading, setLoading] = useState(false);
  const [markingAsRead, setMarkingAsRead] = useState<string | null>(null);
  const [totalCount, setTotalCount] = useState(0);
  const [currentPage, setCurrentPage] = useState(0);
  const [filters, setFilters] = useState<Filters>({
    unreadOnly: false,
    type: "",
    priority: "",
  });
  const pageSize = 20;

  const fetchNotifications = async () => {
    if (!user || authLoading) return;
    try {
      setLoading(true);
      const params = new URLSearchParams({
        limit: pageSize.toString(),
        offset: (currentPage * pageSize).toString(),
      });
      if (!isRoot && currentBranchId && !isGlobalView) {
        params.set("branch_id", currentBranchId);
      }
      if (filters.unreadOnly) params.append("unread_only", "true");
      if (filters.type) params.append("type", filters.type);

      const response = await fetch(`/api/admin/notifications?${params}`);
      if (!response.ok) {
        if (response.status === 401) return;
        throw new Error("Failed to fetch notifications");
      }
      const data = await response.json();
      setNotifications(data.notifications || []);
      setUnreadCount(data.unreadCount || 0);
      setTotalCount(data.count || 0);
    } catch (error) {
      appLogger.error("Error fetching notifications:", error);
      toast.error("Error al cargar las notificaciones");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (!authLoading && user) {
      fetchNotifications();
      const supabase = createClient();
      const channel = supabase
        .channel("admin-notifications-page")
        .on(
          "postgres_changes",
          {
            event: "INSERT",
            schema: "public",
            table: "admin_notifications",
            ...(currentBranchId && !isGlobalView && !isRoot
              ? { filter: `branch_id=eq.${currentBranchId}` }
              : {}),
          },
          () => fetchNotifications(),
        )
        .subscribe();
      return () => {
        supabase.removeChannel(channel);
      };
    }
  }, [
    user,
    authLoading,
    currentPage,
    filters,
    currentBranchId,
    isGlobalView,
    isRoot,
  ]);

  const markAsRead = async (notificationId: string, actionUrl?: string) => {
    try {
      setMarkingAsRead(notificationId);
      const response = await fetch("/api/admin/notifications", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ notificationId }),
      });
      if (!response.ok) throw new Error("Failed to mark notification as read");
      setNotifications(
        notifications.map((n) =>
          n.id === notificationId ? { ...n, is_read: true } : n,
        ),
      );
      setUnreadCount(Math.max(0, unreadCount - 1));
      if (actionUrl) router.push(actionUrl);
    } catch (error) {
      appLogger.error("Error marking notification as read:", error);
      toast.error("Error al marcar la notificación");
    } finally {
      setMarkingAsRead(null);
    }
  };

  const markAllAsRead = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/admin/notifications", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ markAllRead: true }),
      });
      if (!response.ok) throw new Error("Failed to mark all as read");
      setNotifications(notifications.map((n) => ({ ...n, is_read: true })));
      setUnreadCount(0);
      toast.success("Todas las notificaciones marcadas como leídas");
    } catch (error) {
      appLogger.error("Error marking all as read:", error);
      toast.error("Error al marcar todas como leídas");
    } finally {
      setLoading(false);
    }
  };

  const filteredNotifications = notifications.filter((n) => {
    if (filters.priority && n.priority !== filters.priority) return false;
    return true;
  });

  const totalPages = Math.ceil(totalCount / pageSize);

  return {
    notifications,
    unreadCount,
    loading,
    markingAsRead,
    totalCount,
    currentPage,
    setCurrentPage,
    filters,
    setFilters,
    fetchNotifications,
    markAsRead,
    markAllAsRead,
    filteredNotifications,
    totalPages,
    isSuperAdmin,
    isRoot,
    currentBranchId,
    isGlobalView,
  };
}

"use client";

import { useCallback, useEffect, useState } from "react";

import { appLogger } from '@/lib/logger';


interface AdminNotification {
  id: string;
  type: string;
  title: string;
  message: string;
  is_read: boolean;
  priority: string;
  created_at: string;
  related_entity_type?: string;
  related_entity_id?: string;
  action_url?: string;
  action_label?: string;
}

export function useNotificationsList(fetchParams?: { limit?: number }) {
  const [notifications, setNotifications] = useState<AdminNotification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [loading, setLoading] = useState(false);
  const [markingAsRead, setMarkingAsRead] = useState<string | null>(null);
  const [totalCount, setTotalCount] = useState(0);

  const fetchNotifications = useCallback(async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams();
      if (fetchParams?.limit) params.set("limit", String(fetchParams.limit));
      const response = await fetch(`/api/admin/notifications?${params}`);
      if (response.ok) {
        const data = await response.json();
        setNotifications(data.notifications || []);
        setUnreadCount(data.unreadCount ?? 0);
        setTotalCount(data.totalCount ?? 0);
      }
    } catch (error) {
      appLogger.error("Error fetching notifications:", error);
    } finally {
      setLoading(false);
    }
  }, [fetchParams?.limit]);

  useEffect(() => {
    fetchNotifications();
  }, [fetchNotifications]);

  const markAsRead = async (notificationId: string) => {
    try {
      setMarkingAsRead(notificationId);
      const response = await fetch(
        `/api/admin/notifications/${notificationId}`,
        {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ is_read: true }),
        },
      );
      if (response.ok) {
        setNotifications((prev) =>
          prev.map((n) =>
            n.id === notificationId ? { ...n, is_read: true } : n,
          ),
        );
        setUnreadCount((prev) => Math.max(0, prev - 1));
      }
    } catch (error) {
      appLogger.error("Error marking notification as read:", error);
    } finally {
      setMarkingAsRead(null);
    }
  };

  const markAllAsRead = async () => {
    try {
      const response = await fetch("/api/admin/notifications", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ is_read: true }),
      });
      if (response.ok) {
        setNotifications((prev) => prev.map((n) => ({ ...n, is_read: true })));
        setUnreadCount(0);
      }
    } catch (error) {
      appLogger.error("Error marking all as read:", error);
    }
  };

  const deleteNotification = async (notificationId: string) => {
    try {
      const wasUnread =
        notifications.find((n) => n.id === notificationId)?.is_read === false;
      const response = await fetch(
        `/api/admin/notifications/${notificationId}`,
        { method: "DELETE" },
      );
      if (response.ok) {
        setNotifications((prev) => prev.filter((n) => n.id !== notificationId));
        if (wasUnread) setUnreadCount((prev) => Math.max(0, prev - 1));
      }
    } catch (error) {
      appLogger.error("Error deleting notification:", error);
    }
  };

  return {
    notifications,
    unreadCount,
    totalCount,
    loading,
    markingAsRead,
    fetchNotifications,
    markAsRead,
    markAllAsRead,
    deleteNotification,
  };
}

"use client";

import { AlertCircle, ArrowLeft, CreditCard, Loader2 } from "lucide-react";
import Link from "next/link";
import { useParams } from "next/navigation";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { useBranch } from "@/hooks/useBranch";
import { appLogger } from '@/lib/logger';
import { formatCurrency, formatDateTime } from "@/lib/utils";
import { getBranchHeader } from "@/lib/utils/branch";

export default function AdminOrderDetailContent() {
  const params = useParams();
  const orderId = params.id as string;
  const { currentBranchId } = useBranch();
  const [order, setOrder] = useState<unknown>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchOrderDetail();
  }, [orderId]);

  const fetchOrderDetail = async () => {
    try {
      setLoading(true);
      const headers = {
        ...getBranchHeader(currentBranchId),
      };

      const response = await fetch(`/api/admin/orders/${orderId}`, { headers });
      if (response.ok) {
        const data = await response.json();
        setOrder(data.order);
      } else {
        const error = await response.json();
        toast.error(error.error || "Error al cargar la orden");
      }
    } catch (error: unknown) {
      appLogger.error("Error fetching order:", error);
      toast.error("Error al cargar la orden");
    } finally {
      setLoading(false);
    }
  };

  const paidAmount =
    order?.order_payments?.reduce(
      (sum: number, p: unknown) => sum + Number(p.amount),
      0,
    ) || 0;
  const pendingAmount = Math.max(0, (order?.total_amount || 0) - paidAmount);

  const paymentMethodMap: Record<string, string> = {
    cash: "Efectivo",
    debit: "Tarjeta Débito",
    credit: "Tarjeta Crédito",
    transfer: "Transferencia",
    check: "Cheque",
  };

  const paymentMethodLabel =
    order?.order_payments && order.order_payments.length > 0
      ? Array.from(
          new Set(order.order_payments.map((p: unknown) => p.payment_method)),
        ).join(", ")
      : order?.mp_payment_method === "cash"
        ? "Efectivo"
        : order?.mp_payment_method === "debit"
          ? "Débito"
          : order?.mp_payment_method === "credit"
            ? "Crédito"
            : order?.mp_payment_method === "card"
              ? "Tarjeta"
              : order?.mp_payment_method === "transfer"
                ? "Transferencia"
                : order?.mp_payment_method || "N/A";

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[50vh] p-4">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (!order) {
    return (
      <div className="space-y-4 p-4 sm:p-6 pb-28 sm:pb-6">
        <div className="flex gap-2">
          <Link href="/admin/cash-register">
            <Button
              className="min-h-[44px] sm:min-h-0"
              size="sm"
              variant="outline"
            >
              <ArrowLeft className="h-4 w-4 mr-2" />
              Caja
            </Button>
          </Link>
        </div>
        <Card>
          <CardContent className="pt-6 text-center text-sm sm:text-base text-muted-foreground">
            No se encontró la orden
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="space-y-4 sm:space-y-6 p-4 sm:p-6 pb-28 sm:pb-6 lg:pb-6">
      <div className="flex gap-2">
        <Link href="/admin/cash-register">
          <Button
            className="min-h-[44px] sm:min-h-0"
            size="sm"
            variant="outline"
          >
            <ArrowLeft className="h-4 w-4 mr-2" />
            Caja
          </Button>
        </Link>
      </div>

      {/* Card 1: Orden #ORD-xxx */}
      <Card>
        <CardHeader className="pb-3">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
            <div className="min-w-0">
              <CardTitle className="text-base sm:text-lg truncate">
                Orden #{order.order_number}
              </CardTitle>
              <p className="text-xs sm:text-sm text-muted-foreground mt-1">
                {formatDateTime(order.created_at)}
              </p>
            </div>
            <div className="flex flex-wrap gap-2 shrink-0">
              <Badge
                variant={
                  order.status === "completed"
                    ? "default"
                    : order.status === "cancelled"
                      ? "destructive"
                      : "outline"
                }
              >
                {order.status === "completed" && "Completada"}
                {order.status === "cancelled" && "Anulada"}
                {order.status === "processing" && "Procesando"}
              </Badge>
              <Badge
                variant={
                  order.payment_status === "paid"
                    ? "default"
                    : order.payment_status === "partial"
                      ? "secondary"
                      : "outline"
                }
              >
                {order.payment_status === "paid" && "Pagada"}
                {order.payment_status === "partial" && "Parcial"}
                {order.payment_status === "pending" && "Pendiente"}
                {order.payment_status === "refunded" && "Reembolsada"}
              </Badge>
            </div>
          </div>
        </CardHeader>
      </Card>

      {/* Cancellation Reason */}
      {order.status === "cancelled" && order.cancellation_reason && (
        <Card className="border-red-200 bg-red-50 dark:border-red-900/50 dark:bg-red-950/30">
          <CardContent className="pt-4 sm:pt-6 space-y-2">
            <div className="flex items-start gap-3">
              <AlertCircle className="h-5 w-5 text-red-600 flex-shrink-0 mt-0.5" />
              <div className="min-w-0 flex-1">
                <p className="text-sm sm:text-base font-semibold text-red-900 dark:text-red-200">
                  Motivo de Anulación
                </p>
                <p className="text-xs sm:text-sm text-red-800 dark:text-red-300 mt-1 break-words">
                  {order.cancellation_reason}
                </p>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Card 2: Información */}
      <Card>
        <CardHeader className="pb-2">
          <CardTitle className="text-base sm:text-lg">Información</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div>
            <p className="text-xs sm:text-sm text-muted-foreground">Cliente</p>
            <p className="text-sm sm:text-base font-medium break-words">
              {order.customer_name || order.email || "N/A"}
            </p>
          </div>
          <div>
            <p className="text-xs sm:text-sm text-muted-foreground">Email</p>
            <p className="text-sm sm:text-base font-medium break-all">
              {order.email || "N/A"}
            </p>
          </div>
          <div>
            <p className="text-xs sm:text-sm text-muted-foreground">
              Método de Pago
            </p>
            <p className="text-sm sm:text-base font-medium">
              {paymentMethodLabel}
            </p>
          </div>
        </CardContent>
      </Card>

      {/* Card 3: Montos */}
      <Card>
        <CardHeader className="pb-2">
          <CardTitle className="text-base sm:text-lg">Montos</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div>
            <p className="text-xs sm:text-sm text-muted-foreground">Subtotal</p>
            <p className="text-sm sm:text-base font-medium">
              {formatCurrency(order.subtotal ?? order.total_amount)}
            </p>
          </div>
          <div>
            <p className="text-xs sm:text-sm text-muted-foreground">Total</p>
            <p className="text-base sm:text-lg font-semibold">
              {formatCurrency(order.total_amount)}
            </p>
          </div>
          <div className="pt-3 border-t space-y-2">
            <div className="flex justify-between text-sm sm:text-base">
              <span className="text-muted-foreground">Monto Pagado</span>
              <span className="font-medium text-green-600">
                {formatCurrency(paidAmount)}
              </span>
            </div>
            <div className="flex justify-between text-sm sm:text-base">
              <span className="text-muted-foreground">Saldo Pendiente</span>
              <span
                className={`font-bold ${pendingAmount > 0 ? "text-red-600" : "text-muted-foreground"}`}
              >
                {formatCurrency(pendingAmount)}
              </span>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Card 4: Historial de Pagos */}
      {order.order_payments && order.order_payments.length > 0 && (
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-base sm:text-lg flex items-center gap-2">
              <CreditCard className="h-4 w-4 sm:h-5 sm:w-5 shrink-0" />
