/**
 * POSAdvancedSale — Complete Optical Sale Form
 *
 * Handles "Venta Óptica" / "Crear Orden Completa" functionality.
 * State managed via usePOSAdvancedSale hook; rendering delegated to 4 tab components.
 */
"use client";

import { Glasses, Sparkles, Tag, User } from "lucide-react";

import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";

import type { POSAdvancedSaleProps } from "./POSAdvancedSale.types";
import { POSAdvancedSaleCustomerTab } from "./POSAdvancedSaleCustomerTab";
import { POSAdvancedSaleFrameTab } from "./POSAdvancedSaleFrameTab";
import { POSAdvancedSaleLensesTab } from "./POSAdvancedSaleLensesTab";
import { POSAdvancedSalePricingTab } from "./POSAdvancedSalePricingTab";
import { usePOSAdvancedSale } from "./usePOSAdvancedSale";

export function POSAdvancedSale(props: POSAdvancedSaleProps) {
  const s = usePOSAdvancedSale(props);

  return (
    <div className="h-full flex flex-col overflow-hidden">
      <Tabs
        className="flex flex-col h-full"
        value={s.orderFormTab}
        onValueChange={(v) => s.setOrderFormTab(v as typeof s.orderFormTab)}
      >
        <TabsList className="grid w-full grid-cols-4 gap-1 h-auto min-h-[44px] mx-4 mt-2 flex-shrink-0">
          <TabsTrigger className="text-xs sm:text-sm py-2" value="customer">
            <User className="h-4 w-4 mr-2" />
            Cliente
          </TabsTrigger>
          <TabsTrigger className="text-xs sm:text-sm py-2" value="frame">
            <Glasses className="h-4 w-4 mr-2" />
            Marco
          </TabsTrigger>
          <TabsTrigger className="text-xs sm:text-sm py-2" value="lenses">
            <Sparkles className="h-4 w-4 mr-2" />
            Lentes
          </TabsTrigger>
          <TabsTrigger className="text-xs sm:text-sm py-2" value="pricing">
            <Tag className="h-4 w-4 mr-2" />
            Precios
          </TabsTrigger>
        </TabsList>

        <div className="flex-1 overflow-y-auto overflow-x-hidden px-4 pb-4">
          <TabsContent className="h-auto m-0 p-4" value="customer">
            <POSAdvancedSaleCustomerTab
              customer={props.customer}
              externalPrescriptionData={s.externalPrescriptionData}
              loadingPrescriptions={s.loadingPrescriptions}
              orderFormData={s.orderFormData}
              prescriptions={s.prescriptions}
              quickCustomerEmail={props.quickCustomerEmail}
              quickCustomerName={props.quickCustomerName}
              quickCustomerPhone={props.quickCustomerPhone}
              quickCustomerRUT={props.quickCustomerRUT}
              selectedPrescription={s.selectedPrescription}
              setExternalPrescriptionData={s.setExternalPrescriptionData}
              setOrderFormData={s.setOrderFormData}
              setSelectedPrescription={s.setSelectedPrescription}
              setUseExternalPrescription={s.setUseExternalPrescription}
              suggestLensFamily={s.suggestLensFamily}
              useExternalPrescription={s.useExternalPrescription}
              onCustomerChange={props.onCustomerChange}
              onNextTab={() => s.setOrderFormTab("frame")}
            />
          </TabsContent>

          <TabsContent className="h-auto m-0 p-4" value="frame">
            <POSAdvancedSaleFrameTab
              customerOwnNearFrame={s.customerOwnNearFrame}
              frameLoading={s.frameLoading}
              frameResults={s.frameResults}
              frameSearchTerm={s.frameSearchTerm}
              nearFrameLoading={s.nearFrameLoading}
              nearFrameResults={s.nearFrameResults}
              nearFrameSearchTerm={s.nearFrameSearchTerm}
              orderFormData={s.orderFormData}
              selectedFrame={s.selectedFrame}
              selectedNearFrame={s.selectedNearFrame}
              setCustomerOwnNearFrame={s.setCustomerOwnNearFrame}
              setFrameSearchTerm={s.setFrameSearchTerm}
              setNearFrameSearchTerm={s.setNearFrameSearchTerm}
              setOrderFormData={s.setOrderFormData}
              setSelectedFrame={s.setSelectedFrame}
              setSelectedNearFrame={s.setSelectedNearFrame}
              onNextTab={() => s.setOrderFormTab("lenses")}
              onPrevTab={() => s.setOrderFormTab("customer")}
            />
          </TabsContent>

          <TabsContent className="h-auto m-0 p-4" value="lenses">
            <POSAdvancedSaleLensesTab
              branchId={props.branchId}
              contactLensConfig={s.contactLensConfig}
              customer={props.customer}
              filteredTreatments={s.filteredTreatments}
              handleUpdateTreatmentPrice={s.handleUpdateTreatmentPrice}
              lensFamilies={s.lensFamilies}
              nearLensPriceValue={s.nearLensPriceValue}
              orderFormData={s.orderFormData}
              selectedPrescription={s.selectedPrescription}
              setContactLensConfig={s.setContactLensConfig}
              setOrderFormData={s.setOrderFormData}
              toggleTreatment={s.toggleTreatment}
              onNextTab={() => s.setOrderFormTab("pricing")}
              onPrevTab={() => s.setOrderFormTab("frame")}
            />
          </TabsContent>

          <TabsContent className="h-auto m-0 p-4" value="pricing">
            <POSAdvancedSalePricingTab
              creatingQuote={s.creatingQuote}
              customer={props.customer}
              customerOwnNearFrame={s.customerOwnNearFrame}
              discountAmount={s.discountAmount}
              discountType={s.discountType}
              discountValue={s.discountValue}
              handleAddToCart={s.handleAddToCart}
              handleCreateQuote={s.handleCreateQuote}
              lensFamilies={s.lensFamilies}
              lensPrice={s.lensPrice}
              nearLensPriceValue={s.nearLensPriceValue}
              orderFormData={s.orderFormData}
              quickCustomerEmail={props.quickCustomerEmail}
              quickCustomerName={props.quickCustomerName}
              quickCustomerPhone={props.quickCustomerPhone}
              quickCustomerRUT={props.quickCustomerRUT}
              selectedFrame={s.selectedFrame}
              selectedNearFrame={s.selectedNearFrame}
              selectedPrescription={s.selectedPrescription}
              setDiscountType={s.setDiscountType}
              setDiscountValue={s.setDiscountValue}
              setOrderFormData={s.setOrderFormData}
              totalPrice={s.totalPrice}
              treatments={s.treatments}
              treatmentsPrice={s.treatmentsPrice}
              useExternalPrescription={s.useExternalPrescription}
              onPrevTab={() => s.setOrderFormTab("lenses")}
            />
          </TabsContent>
        </div>
      </Tabs>
    </div>
  );
}

/**
 * POSAdvancedSaleCustomerTab — Customer & Prescription tab for the Optical Sale form.
 *
 * Displays selected customer info, quick customer data, prescription selector,
 * external prescription form, and presbyopia solution selector.
 */
"use client";

import { User, X } from "lucide-react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import type { Prescription } from "@/lib/api/services/customerService";

import { POSPrescriptionDetail } from "./_components/POSPrescriptionDetail";
import { ExternalPrescriptionForm } from "./ExternalPrescriptionForm";
import type {
  ExternalPrescriptionData,
  OrderFormData,
  POSAdvancedSaleProps,
} from "./POSAdvancedSale.types";
import { PresbyopiaSolutionSelector } from "./PresbyopiaSolutionSelector";

export interface POSAdvancedSaleCustomerTabProps {
  customer: POSAdvancedSaleProps["customer"];
  onCustomerChange: POSAdvancedSaleProps["onCustomerChange"];
  quickCustomerName?: string | null;
  quickCustomerRUT?: string | null;
  quickCustomerEmail?: string | null;
  quickCustomerPhone?: string | null;
  prescriptions: Prescription[];
  selectedPrescription: Prescription | null;
  setSelectedPrescription: (v: Prescription | null) => void;
  loadingPrescriptions: boolean;
  useExternalPrescription: boolean;
  setUseExternalPrescription: (v: boolean) => void;
  externalPrescriptionData: ExternalPrescriptionData;
  setExternalPrescriptionData: React.Dispatch<
    React.SetStateAction<ExternalPrescriptionData>
  >;
  orderFormData: OrderFormData;
  setOrderFormData: React.Dispatch<React.SetStateAction<OrderFormData>>;
  suggestLensFamily: () => void;
  onNextTab: () => void;
}

export function POSAdvancedSaleCustomerTab({
  customer,
  onCustomerChange,
  quickCustomerName,
  quickCustomerRUT,
  quickCustomerEmail,
  quickCustomerPhone,
  prescriptions,
  selectedPrescription,
  setSelectedPrescription,
  loadingPrescriptions,
  useExternalPrescription,
  setUseExternalPrescription,
  externalPrescriptionData,
  setExternalPrescriptionData,
  orderFormData,
  setOrderFormData,
  suggestLensFamily,
  onNextTab,
}: POSAdvancedSaleCustomerTabProps) {
  const hasPrescriptionAddition =
    (selectedPrescription?.od_add ?? 0) > 0 ||
    (selectedPrescription?.os_add ?? 0) > 0;

  return (
    <Card>
      <CardHeader className="pb-3">
        <CardTitle className="text-lg">Cliente y Receta</CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Selected Customer */}
        <div>
          <Label>Cliente Seleccionado</Label>
          {customer ? (
            <div className="mt-1 p-3 border rounded-lg bg-muted/50 space-y-2">
              <div className="space-y-1">
                <div className="font-medium">
                  {customer.first_name && customer.last_name
                    ? `${customer.first_name} ${customer.last_name}`.trim()
                    : customer.name || customer.business_name || "Sin nombre"}
                </div>
                {customer.email && (
                  <div className="text-sm text-muted-foreground">
                    Email: {customer.email}
                  </div>
                )}
                {customer.rut && (
                  <div className="text-sm text-muted-foreground">
                    RUT: {customer.rut}
                  </div>
                )}
              </div>
              <Button
                className="text-destructive"
                size="sm"
                variant="ghost"
                onClick={() => onCustomerChange(null)}
              >
                <X className="h-4 w-4 mr-1" />
                Cambiar cliente
              </Button>
            </div>
          ) : (
            <div className="mt-1 p-3 border rounded-lg bg-muted/30 text-sm text-muted-foreground">
              Seleccione un cliente en el panel de búsqueda superior
            </div>
          )}
        </div>

        {/* Quick Customer Info */}
        {!customer && (quickCustomerName || quickCustomerRUT) && (
          <div className="mt-2 p-3 border border-blue-200 rounded-lg bg-blue-50 dark:bg-blue-900/20">
            <div className="flex items-center gap-2 mb-2">
              <User className="h-4 w-4 text-blue-600" />
              <span className="font-medium text-blue-800 dark:text-blue-200">
                Cliente Rápido
              </span>
            </div>
            <div className="space-y-1 text-sm">
              {quickCustomerName && (
                <div>
                  <span className="text-muted-foreground">Nombre: </span>
                  <span className="font-medium">{quickCustomerName}</span>
                </div>
              )}
              {quickCustomerRUT && (
                <div>
                  <span className="text-muted-foreground">RUT: </span>
                  <span className="font-medium">{quickCustomerRUT}</span>
                </div>
              )}
              {quickCustomerEmail && (
                <div>
                  <span className="text-muted-foreground">Email: </span>
                  <span className="font-medium">{quickCustomerEmail}</span>
                </div>
              )}
              {quickCustomerPhone && (
                <div>
                  <span className="text-muted-foreground">Teléfono: </span>
                  <span className="font-medium">{quickCustomerPhone}</span>
                </div>
              )}
            </div>
            <div className="mt-2 text-xs text-blue-600 dark:text-blue-400">
              Datos del cliente no registrado. Complete la receta externa para crear la venta.
            </div>
          </div>
        )}

        {/* Prescription Selection */}
        {customer && (
          <div className="space-y-3">
            <div className="flex gap-2">
              <Button
                size="sm"
                variant={!useExternalPrescription ? "default" : "outline"}
                onClick={() => setUseExternalPrescription(false)}
              >
                Receta del Cliente
              </Button>
              <Button
                size="sm"
                variant={useExternalPrescription ? "default" : "outline"}
                onClick={() => setUseExternalPrescription(true)}
              >
                Receta Externa
              </Button>
            </div>

            {!useExternalPrescription && (
              <div>
                <Label>Seleccionar Receta</Label>
                {loadingPrescriptions ? (
                  <div className="text-sm text-muted-foreground mt-1">
                    Cargando recetas...
                  </div>
                ) : prescriptions.length > 0 ? (
                  <Select
                    value={selectedPrescription?.id || ""}
                    onValueChange={(value) => {
                      const prescription = prescriptions.find(
                        (p) => p.id === value,
                      );
                      setSelectedPrescription(prescription || null);
                      if (prescription) suggestLensFamily();
                    }}
                  >
                    <SelectTrigger className="mt-1">
                      <SelectValue placeholder="Selecciona una receta" />
                    </SelectTrigger>
                    <SelectContent>
                      {prescriptions.map((rx) => (
                        <SelectItem key={rx.id} value={rx.id}>
                          <div className="flex justify-between items-center w-full gap-4">
                            <span>
                              {rx.prescription_number ||
                                `Receta ${rx.id.slice(0, 8)}`}
                              {rx.is_current && (
                                <Badge className="ml-2 text-xs" variant="secondary">
                                  Actual
                                </Badge>
                              )}
                            </span>
                            <span className="text-xs text-muted-foreground">
                              {new Date(rx.prescription_date).toLocaleDateString("es-CL")}
                            </span>
                          </div>
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                ) : (
                  <div className="text-sm text-muted-foreground mt-1 p-2 border rounded">
                    No hay recetas disponibles para este cliente
                  </div>
                )}

                {selectedPrescription && (
                  <POSPrescriptionDetail prescription={selectedPrescription} />
                )}

                {hasPrescriptionAddition && (
                  <PresbyopiaSolutionSelector
                    value={orderFormData.presbyopia_solution}
                    onChange={(value) =>
                      setOrderFormData((prev) => ({
                        ...prev,
                        presbyopia_solution: value as "single" | "two_separate" | "progressive",
                      }))
                    }
                  />
                )}
              </div>
            )}
          </div>
        )}

        {/* External Prescription Form */}
        {(useExternalPrescription ||
          (!customer && (quickCustomerName || quickCustomerRUT))) && (
          <ExternalPrescriptionForm
            data={externalPrescriptionData}
            presbyopiaValue={orderFormData.presbyopia_solution}
            onChange={setExternalPrescriptionData}
            onPresbyopiaChange={(value) =>
              setOrderFormData((prev) => ({
                ...prev,
                presbyopia_solution: value as "single" | "two_separate" | "progressive",
              }))
            }
          />
        )}

        {/* Next Button */}
        <div className="flex justify-end pt-4">
          <Button onClick={onNextTab}>Siguiente: Marco</Button>
        </div>
      </CardContent>
    </Card>
  );
}

/**
 * POSAdvancedSaleFrameTab — Frame Selection tab for the Optical Sale form.
 *
 * Handles distance frame search, near frame search, frame results display,
 * customer own frame toggle, and manual frame entry.
 */
"use client";

import { Search } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

import { FrameDetailsPanel } from "./_components/FrameDetailsPanel";
import { FrameSearchResults } from "./_components/FrameSearchResults";
import { ManualFrameEntry } from "./_components/ManualFrameEntry";
import type { OrderFormData,POSProduct } from "./POSAdvancedSale.types";

export interface POSAdvancedSaleFrameTabProps {
  orderFormData: OrderFormData;
  setOrderFormData: React.Dispatch<React.SetStateAction<OrderFormData>>;
  selectedFrame: POSProduct | null;
  setSelectedFrame: (v: POSProduct | null) => void;
  frameSearchTerm: string;
  setFrameSearchTerm: (v: string) => void;
  frameResults: POSProduct[];
  frameLoading: boolean;
  nearFrameSearchTerm: string;
  setNearFrameSearchTerm: (v: string) => void;
  nearFrameResults: POSProduct[];
  nearFrameLoading: boolean;
  selectedNearFrame: POSProduct | null;
  setSelectedNearFrame: (v: POSProduct | null) => void;
  customerOwnNearFrame: boolean;
  setCustomerOwnNearFrame: (v: boolean) => void;
  onPrevTab: () => void;
  onNextTab: () => void;
}

export function POSAdvancedSaleFrameTab({
  orderFormData,
  setOrderFormData,
  selectedFrame,
  setSelectedFrame,
  frameSearchTerm,
  setFrameSearchTerm,
  frameResults,
  frameLoading,
  nearFrameSearchTerm,
  setNearFrameSearchTerm,
  nearFrameResults,
  nearFrameLoading,
  selectedNearFrame,
  setSelectedNearFrame,
  customerOwnNearFrame,
  setCustomerOwnNearFrame,
  onPrevTab,
  onNextTab,
}: POSAdvancedSaleFrameTabProps) {
  return (
    <Card>
      <CardHeader className="pb-3">
        <CardTitle className="text-lg">Selección de Marco</CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Own Frame Toggle - Only show when NOT two_separate */}
        {orderFormData.presbyopia_solution !== "two_separate" && (
          <div className="flex items-center gap-2">
            <input
              checked={orderFormData.customer_own_frame}
              className="w-4 h-4"
              id="customerOwnFrame"
              type="checkbox"
              onChange={(e) =>
                setOrderFormData((prev) => ({
                  ...prev,
                  customer_own_frame: e.target.checked,
                }))
              }
            />
            <Label className="cursor-pointer" htmlFor="customerOwnFrame">
              El cliente trae su propio marco
            </Label>
          </div>
        )}

        {/* For two_separate solution, show checkboxes for each lens */}
        {orderFormData.presbyopia_solution === "two_separate" && (
          <div className="p-3 border border-blue-200 rounded-lg bg-blue-50 dark:bg-blue-900/20 mb-4">
            <div className="flex items-center gap-2 mb-3">
              <input
                checked={orderFormData.customer_own_frame}
                className="w-4 h-4"
                id="customerOwnFrameDistance"
                type="checkbox"
                onChange={(e) =>
                  setOrderFormData((prev) => ({
                    ...prev,
                    customer_own_frame: e.target.checked,
                  }))
                }
              />
              <Label
                className="cursor-pointer text-blue-700 dark:text-blue-300"
                htmlFor="customerOwnFrameDistance"
              >
                El cliente trae su propio marco para lejos
              </Label>
            </div>

            {!orderFormData.customer_own_frame && (
              <>
                <Label className="text-blue-700 dark:text-blue-300 font-medium block mb-2">
                  Marco para Visión Lejos
                </Label>
                <div>
                  <Label>Buscar Armazón para Lejos</Label>
                  <div className="relative mt-1">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                    <Input
                      className="pl-9"
                      placeholder="Buscar por nombre, marca, modelo..."
                      value={frameSearchTerm}
                      onChange={(e) => setFrameSearchTerm(e.target.value)}
                    />
                  </div>
                </div>

                {/* Frame Results - Distance */}
                {selectedFrame === null && frameSearchTerm.length >= 2 && (
                  <FrameSearchResults
                    loading={frameLoading}
                    results={frameResults}
                    onSelect={setSelectedFrame}
                  />
                )}
              </>
            )}
          </div>
        )}

        {/* For single/progressive solution - show frame search */}
        {orderFormData.presbyopia_solution !== "two_separate" &&
          !orderFormData.customer_own_frame && (
            <div>
              <Label>Buscar Armazón</Label>
              <div className="relative mt-1">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                <Input
                  className="pl-9"
                  placeholder="Buscar por nombre, marca, modelo..."
                  value={frameSearchTerm}
                  onChange={(e) => setFrameSearchTerm(e.target.value)}
                />
              </div>
            </div>
          )}

        {/* Show frame results for single/progressive */}
        {orderFormData.presbyopia_solution !== "two_separate" &&
          !orderFormData.customer_own_frame &&
          selectedFrame === null &&
          frameSearchTerm.length >= 2 && (
            <FrameSearchResults
              loading={frameLoading}
              results={frameResults}
              onSelect={setSelectedFrame}
            />
          )}

        {/* Frame for Near - Only for two_separate */}
        {orderFormData.presbyopia_solution === "two_separate" && (
          <div className="p-3 border border-green-200 rounded-lg bg-green-50 dark:bg-green-900/20">
            <div className="flex items-center gap-2 mb-3">
              <input
                checked={customerOwnNearFrame}
                className="w-4 h-4"
                id="customerOwnNearFrame"
                type="checkbox"
                onChange={(e) => setCustomerOwnNearFrame(e.target.checked)}
              />
              <Label
                className="cursor-pointer text-green-700 dark:text-green-300"
                htmlFor="customerOwnNearFrame"
              >
                El cliente trae su propio marco para cerca
              </Label>
            </div>

            {!customerOwnNearFrame && (
              <>
                <Label className="text-green-700 dark:text-green-300 font-medium block mb-2">
                  Marco para Visión Cercana (Cerca)
                </Label>
                <div>
                  <Label>Buscar Armazón para Cerca</Label>
                  <div className="relative mt-1">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                    <Input
                      className="pl-9"
                      placeholder="Buscar por nombre, marca, modelo..."
                      value={nearFrameSearchTerm}
                      onChange={(e) => setNearFrameSearchTerm(e.target.value)}
                    />
                  </div>
                </div>

                {/* Near Frame Results */}
                {selectedNearFrame === null &&
                  nearFrameSearchTerm.length >= 2 && (
                    <FrameSearchResults
                      loading={nearFrameLoading}
                      results={nearFrameResults}
                      onSelect={setSelectedNearFrame}
                    />
                  )}
              </>
            )}
          </div>
        )}

        {/* Selected Frame Display - Distance */}
        {selectedFrame && !orderFormData.customer_own_frame && (
          <FrameDetailsPanel
            frame={selectedFrame}
            title="Marco Seleccionado para Lejos"
            variant="blue"
            onRemove={() => {
              setSelectedFrame(null);
              setFrameSearchTerm("");
            }}
          />
        )}

        {/* Selected Frame Display - Near */}
        {orderFormData.presbyopia_solution === "two_separate" &&
          selectedNearFrame &&
          !customerOwnNearFrame && (
            <FrameDetailsPanel
              frame={selectedNearFrame}
              title="Marco Seleccionado para Cerca"
              variant="green"
              onRemove={() => {
                setSelectedNearFrame(null);
                setNearFrameSearchTerm("");
              }}
            />
          )}

        {/* Manual Frame Entry - For Distance */}
        {orderFormData.customer_own_frame && (
          <ManualFrameEntry
            nameValue={orderFormData.frame_name}
            skuValue={orderFormData.frame_sku}
            title={
              orderFormData.presbyopia_solution === "two_separate"
                ? "Datos del Marco para Lejos"
                : "Datos del Marco"
            }
            onNameChange={(v) =>
              setOrderFormData((prev) => ({ ...prev, frame_name: v }))
            }
            onSkuChange={(v) =>
              setOrderFormData((prev) => ({ ...prev, frame_sku: v }))
            }
          />
        )}

        {/* Manual Near Frame Entry - Only for two_separate */}
        {orderFormData.presbyopia_solution === "two_separate" &&
          customerOwnNearFrame && (
            <ManualFrameEntry
              nameValue={orderFormData.near_frame_name}
              skuValue={orderFormData.near_frame_sku}
              title="Datos del Marco para Cerca"
              titleClassName="text-green-700 dark:text-green-300"
              onNameChange={(v) =>
                setOrderFormData((prev) => ({ ...prev, near_frame_name: v }))
              }
              onSkuChange={(v) =>
                setOrderFormData((prev) => ({ ...prev, near_frame_sku: v }))
              }
            />
          )}

        {/* Navigation */}
        <div className="flex justify-between pt-4">
          <Button variant="outline" onClick={onPrevTab}>
            Atrás
          </Button>
          <Button onClick={onNextTab}>Siguiente: Lentes</Button>
        </div>
      </CardContent>
    </Card>
  );
}

/**
 * POSAdvancedSaleLensesTab — Lenses & Treatments tab for the Optical Sale form.
 *
 * Handles lens type toggle (vision/contact), presbyopia solution selector,
 * lens family selector (single/two_separate), sourcing type, and treatments grid.
 */
"use client";

import { Check } from "lucide-react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import type { Prescription } from "@/lib/api/services/customerService";
import { formatCurrency } from "@/lib/utils";

import { LensConfigurationPanel } from "./_components/LensConfigurationPanel";
import { LensTypeSelector } from "./_components/LensTypeSelector";
import {
  type ContactLensOrderConfig,
  ContactLensSelector,
} from "./ContactLensSelector";
import type {
  OrderFormData,
  POSAdvancedSaleProps,
  Treatment,
} from "./POSAdvancedSale.types";

export interface POSAdvancedSaleLensesTabProps {
  orderFormData: OrderFormData;
  setOrderFormData: React.Dispatch<React.SetStateAction<OrderFormData>>;
  lensFamilies: readonly {
    readonly id: string;
    readonly name: string;
    readonly lens_type: string;
  }[];
  filteredTreatments: Treatment[];
  toggleTreatment: (id: string) => void;
  handleUpdateTreatmentPrice: (id: string, price: number) => void;
  nearLensPriceValue: number;
  contactLensConfig: ContactLensOrderConfig | null;
  setContactLensConfig: (v: ContactLensOrderConfig | null) => void;
  selectedPrescription: Prescription | null;
  customer: POSAdvancedSaleProps["customer"];
  branchId: string | null;
  onPrevTab: () => void;
  onNextTab: () => void;
}

export function POSAdvancedSaleLensesTab({
  orderFormData,
  setOrderFormData,
  lensFamilies,
  filteredTreatments,
  toggleTreatment,
  handleUpdateTreatmentPrice,
  nearLensPriceValue,
  contactLensConfig,
  setContactLensConfig,
  selectedPrescription,
  customer,
  branchId,
  onPrevTab,
  onNextTab,
}: POSAdvancedSaleLensesTabProps) {
  return (
    <Card>
      <CardHeader className="pb-3">
        <CardTitle className="text-lg">Lentes y Tratamientos</CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Lens Type Selection */}
        <LensTypeSelector
          lensType={orderFormData.lens_type}
          onChange={(t) => {
            setOrderFormData((prev) => ({
              ...prev,
              lens_type: t,
            }));
            if (t === "vision") setContactLensConfig(null);
          }}
        />

        {orderFormData.lens_type === "contact" ? (
          <ContactLensSelector
            branchId={branchId}
            customer={customer}
            prescription={
              selectedPrescription
                ? {
                    sphere_od: selectedPrescription.od_sphere || 0,
                    cylinder_od: selectedPrescription.od_cylinder || 0,
                    axis_od: selectedPrescription.od_axis || null,
                    add_od: selectedPrescription.od_add || null,
                    base_curve_od: null,
                    diameter_od: null,
                    sphere_os: selectedPrescription.os_sphere || 0,
                    cylinder_os: selectedPrescription.os_cylinder || 0,
                    axis_os: selectedPrescription.os_axis || null,
                    add_os: selectedPrescription.os_add || null,
                    base_curve_os: null,
                    diameter_os: null,
                  }
                : null
            }
            selectedConfig={contactLensConfig}
            onSelect={(config) => setContactLensConfig(config)}
          />
        ) : (
          <>
            <LensConfigurationPanel
              lensFamilies={lensFamilies}
              nearLensPriceValue={nearLensPriceValue}
              orderFormData={orderFormData}
              setOrderFormData={setOrderFormData}
            />

            {/* Treatments */}
            <div>
              <Label>
                Tratamientos
                {(orderFormData as OrderFormData).lens_type === "contact" && (
                  <span className="text-xs text-muted-foreground ml-2">
                    (solo revestimientos)
                  </span>
                )}
              </Label>
              <div className="grid grid-cols-2 gap-2 mt-2">
                {filteredTreatments.map((treatment) => {
                  const isSelected = orderFormData.treatment_ids.includes(
                    treatment.id,
                  );
                  return (
                    <div
                      className={`p-2 border rounded-lg cursor-pointer transition-colors ${
                        isSelected
                          ? "border-primary bg-primary/5"
                          : "hover:border-muted-foreground"
                      }`}
                      key={treatment.id}
                      onClick={() => toggleTreatment(treatment.id)}
                    >
                      <div className="flex justify-between items-center">
                        <div className="flex-1">
                          <div className="text-sm font-medium">
                            {treatment.label}
                          </div>
                          <div className="text-xs text-muted-foreground">
                            {treatment.category === "coating"
                              ? "Revestimiento"
                              : "Tipo de lente"}
                          </div>
                        </div>
                        <div className="text-right">
                          {treatment.editable && isSelected ? (
                            <Input
                              className="h-8 w-20 text-right text-sm"
                              type="number"
                              value={treatment.cost}
                              onChange={(e) => {
                                e.stopPropagation();
                                handleUpdateTreatmentPrice(
                                  treatment.id,
                                  parseFloat(e.target.value) || 0,
                                );
                              }}
                              onClick={(e) => e.stopPropagation()}
                            />
                          ) : (
                            <div className="text-sm font-semibold">
                              {formatCurrency(treatment.cost)}
                            </div>
                          )}
                          {isSelected && (
                            <Badge className="mt-1" variant="secondary">
                              <Check className="h-3 w-3 mr-1" />
                              Seleccionado
                            </Badge>
                          )}
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Labor Cost */}
            <div>
              <Label>Mano de Obra</Label>
              <Input
                className="mt-1"
                placeholder="0"
                type="number"
                value={orderFormData.labor_cost || ""}
                onChange={(e) =>
                  setOrderFormData((prev) => ({
                    ...prev,
                    labor_cost: parseFloat(e.target.value) || 0,
                  }))
                }
              />
            </div>

            {/* Navigation */}
            <div className="flex justify-between pt-4">
              <Button variant="outline" onClick={onPrevTab}>
                Atrás
              </Button>
              <Button onClick={onNextTab}>Siguiente: Precios</Button>
            </div>
          </>
        )}
      </CardContent>
    </Card>
  );
}

/**
 * POSAdvancedSalePricingTab — Pricing & Cart tab for the Optical Sale form.
 *
 * Handles price summary, discount controls, notes field, add to cart button,
 * and create quote button.
 */
"use client";

import { Package, Tag } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Separator } from "@/components/ui/separator";
import type { Prescription } from "@/lib/api/services/customerService";
import { formatCurrency } from "@/lib/utils";

import { POSPriceSummarySection } from "./_components/POSPriceSummarySection";
import type {
  OrderFormData,
  POSAdvancedSaleProps,
  POSProduct,
  Treatment,
} from "./POSAdvancedSale.types";

export interface POSAdvancedSalePricingTabProps {
  customer: POSAdvancedSaleProps["customer"];
  quickCustomerName?: string | null;
  quickCustomerRUT?: string | null;
  quickCustomerEmail?: string | null;
  quickCustomerPhone?: string | null;
  selectedPrescription: Prescription | null;
  useExternalPrescription: boolean;
  orderFormData: OrderFormData;
  selectedFrame: POSProduct | null;
  customerOwnNearFrame: boolean;
  selectedNearFrame: POSProduct | null;
  lensFamilies: readonly {
    readonly id: string;
    readonly name: string;
    readonly lens_type: string;
  }[];
  treatments: Treatment[];
  lensPrice: () => number;
  nearLensPriceValue: number;
  treatmentsPrice: number;
  totalPrice: () => number;
  discountAmount: () => number;
  discountType: "none" | "percentage" | "fixed";
  setDiscountType: (v: "none" | "percentage" | "fixed") => void;
  discountValue: number;
  setDiscountValue: (v: number) => void;
  handleAddToCart: () => void;
  handleCreateQuote: () => Promise<void>;
  creatingQuote: boolean;
  setOrderFormData: React.Dispatch<React.SetStateAction<OrderFormData>>;
  onPrevTab: () => void;
}

export function POSAdvancedSalePricingTab({
  customer,
  quickCustomerName,
  quickCustomerRUT,
  quickCustomerEmail,
  quickCustomerPhone,
  selectedPrescription,
  useExternalPrescription,
  orderFormData,
  selectedFrame,
  customerOwnNearFrame,
  selectedNearFrame,
  lensFamilies,
  treatments,
  lensPrice,
  nearLensPriceValue,
  treatmentsPrice,
  totalPrice,
  discountAmount,
  discountType,
  setDiscountType,
  discountValue,
  setDiscountValue,
  handleAddToCart,
  handleCreateQuote,
  creatingQuote,
  setOrderFormData,
  onPrevTab,
}: POSAdvancedSalePricingTabProps) {
  return (
    <Card>
      <CardHeader className="pb-3">
        <CardTitle className="text-lg">Resumen y Precios</CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Summary */}
        <div className="space-y-3">
          <h4 className="font-medium">Resumen de la Orden</h4>

          {/* Customer */}
          <div className="flex flex-col text-sm">
            <div className="flex justify-between">
              <span className="text-muted-foreground">Cliente:</span>
              <span>
                {customer
                  ? customer.first_name && customer.last_name
                    ? `${customer.first_name} ${customer.last_name}`.trim()
                    : customer.name || customer.business_name || "Sin nombre"
                  : quickCustomerName || "Sin cliente"}
              </span>
            </div>
            {/* Show quick customer details */}
            {!customer &&
              (quickCustomerRUT ||
                quickCustomerEmail ||
                quickCustomerPhone) && (
                <div className="flex justify-between text-xs text-muted-foreground mt-1">
                  <span />
                  <span className="text-right">
                    {quickCustomerRUT && <span>RUT: {quickCustomerRUT} </span>}
                    {quickCustomerEmail && (
                      <span>Email: {quickCustomerEmail} </span>
                    )}
                    {quickCustomerPhone && (
                      <span>Tel: {quickCustomerPhone}</span>
                    )}
                  </span>
                </div>
              )}
          </div>

          {/* Prescription */}
          <div className="flex justify-between text-sm">
            <span className="text-muted-foreground">Receta:</span>
            <span>
              {selectedPrescription
                ? selectedPrescription.prescription_number ||
                  `Receta ${selectedPrescription.id.slice(0, 8)}`
                : useExternalPrescription
                  ? "Receta Externa"
                  : "Sin receta"}
            </span>
          </div>

          <POSPriceSummarySection
            customerOwnNearFrame={customerOwnNearFrame}
            lensFamilies={lensFamilies}
            lensPrice={lensPrice}
            orderFormData={orderFormData}
            selectedFrame={selectedFrame}
            selectedNearFrame={selectedNearFrame}
            treatments={treatments}
            treatmentsPrice={treatmentsPrice}
          />

          {/* Discount */}
          <div className="space-y-2 pt-2">
            <Label className="text-sm font-medium">Descuento</Label>
            <div className="flex gap-2">
              <Select
                value={discountType}
                onValueChange={(value) =>
                  setDiscountType(value as typeof discountType)
                }
              >
                <SelectTrigger className="w-[140px]">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="none">Sin descuento</SelectItem>
                  <SelectItem value="percentage">Porcentaje</SelectItem>
                  <SelectItem value="fixed">Monto fijo</SelectItem>
                </SelectContent>
              </Select>
              {discountType !== "none" && (
                <Input
                  className="flex-1"
                  max={discountType === "percentage" ? 100 : undefined}
                  min={0}
                  placeholder={
                    discountType === "percentage" ? "0-100" : "Monto"
                  }
                  type="number"
                  value={discountValue || ""}
                  onChange={(e) =>
                    setDiscountValue(parseFloat(e.target.value) || 0)
                  }
                />
              )}
            </div>
            {discountType === "percentage" && discountValue > 0 && (
              <div className="text-sm text-green-600">
                Descuento: -{formatCurrency(discountAmount())} ({discountValue}
                %)
              </div>
            )}
            {discountType === "fixed" && discountValue > 0 && (
              <div className="text-sm text-green-600">
                Descuento: -{formatCurrency(discountValue)}
              </div>
            )}
          </div>

          <Separator />

          {/* Total */}
          <div className="flex justify-between text-lg font-bold pt-2">
            <span>Total</span>
            <span>{formatCurrency(totalPrice())}</span>
          </div>
        </div>

        {/* Notes */}
        <div>
          <Label>Notas</Label>
          <Input
            className="mt-1"
            placeholder="Notas adicionales..."
            value={orderFormData.notes}
            onChange={(e) =>
              setOrderFormData((prev) => ({
                ...prev,
                notes: e.target.value,
              }))
            }
          />
        </div>

        {/* Action Buttons */}
        <div className="flex flex-col gap-2 pt-4">
          <Button
            className="w-full"
            disabled={
              !selectedFrame &&
              !orderFormData.lens_family_id &&
              orderFormData.labor_cost === 0
            }
            size="lg"
            onClick={handleAddToCart}
          >
            <Package className="h-5 w-5 mr-2" />
            Agregar al Carrito
          </Button>

          <Button
            className="w-full"
            disabled={
              (!customer && !quickCustomerName && !quickCustomerRUT) ||
              creatingQuote
            }
            size="lg"
            variant="secondary"
            onClick={handleCreateQuote}
          >
            {creatingQuote ? (
              "Creando..."
            ) : (
              <>
                <Tag className="h-5 w-5 mr-2" />
                {!customer && (quickCustomerName || quickCustomerRUT)
                  ? "Crear Cliente y Presupuesto"
                  : "Crear Presupuesto"}
              </>
            )}
          </Button>

          <Button className="w-full" variant="outline" onClick={onPrevTab}>
            Atrás
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import { Building2, Check, Search } from "lucide-react";
import { useState } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { cn } from "@/lib/utils";

interface Agreement {
  id: string;
  name: string;
  business_name?: string;
  discount_percentage?: number;
  status?: string;
}

interface POSAgreementSelectorProps {
  agreements: Agreement[];
  selectedAgreementId: string | null;
  onSelect: (agreement: Agreement | null) => void;
  disabled?: boolean;
  placeholder?: string;
}

export function POSAgreementSelector({
  agreements,
  selectedAgreementId,
  onSelect,
  disabled = false,
  placeholder = "Seleccionar convenio...",
}: POSAgreementSelectorProps) {
  const selectedAgreement = agreements.find(
    (a) => a.id === selectedAgreementId,
  );
  const [open, setOpen] = useState(false);

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          className={cn(
            "w-full justify-between gap-2",
            !selectedAgreement && "text-muted-foreground",
          )}
          disabled={disabled}
          role="combobox"
          variant="outline"
        >
          {selectedAgreement ? (
            <div className="flex items-center gap-2 truncate">
              <Building2 className="h-4 w-4 flex-shrink-0" />
              <span className="truncate">{selectedAgreement.name}</span>
              {selectedAgreement.discount_percentage && (
                <Badge className="ml-auto flex-shrink-0" variant="secondary">
                  -{selectedAgreement.discount_percentage}%
                </Badge>
              )}
            </div>
          ) : (
            <>
              <Search className="h-4 w-4" />
              <span>{placeholder}</span>
            </>
          )}
        </Button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-[300px] p-0">
        <Command>
          <CommandInput placeholder="Buscar convenios..." />
          <CommandList>
            <CommandEmpty>No se encontraron convenios</CommandEmpty>
            <CommandGroup heading="Convenios disponibles">
              {agreements.map((agreement) => (
                <CommandItem
                  key={agreement.id}
                  value={agreement.name}
                  onSelect={() => {
                    onSelect(agreement);
                    setOpen(false);
                  }}
                >
                  <Check
                    className={cn(
                      "mr-2 h-4 w-4",
                      selectedAgreementId === agreement.id
                        ? "opacity-100"
                        : "opacity-0",
                    )}
                  />
                  <div className="flex flex-col">
                    <span className="font-medium">{agreement.name}</span>
                    {agreement.business_name && (
                      <span className="text-xs text-muted-foreground">
                        {agreement.business_name}
                      </span>
                    )}
                  </div>
                  {agreement.discount_percentage && (
                    <Badge className="ml-auto" variant="secondary">
                      -{agreement.discount_percentage}%
                    </Badge>
                  )}
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}

"use client";

import { Scan } from "lucide-react";
import { useCallback, useEffect, useRef } from "react";

import { Input } from "@/components/ui/input";

interface POSBarcodeInputProps {
  value: string;
  onChange: (value: string) => void;
  onScan: (barcode: string) => void;
  onSearch?: (term: string) => void;
  onKeyDown?: (e: React.KeyboardEvent<HTMLInputElement>) => void;
  placeholder?: string;
  className?: string;
  autoFocus?: boolean;
  inputRef?: React.RefObject<HTMLInputElement | null>;
  /** Restore focus after successful scan/search (default: true) */
  restoreFocusOnSuccess?: boolean;
  /** Scan detection window in ms - chars+Enter within this = barcode (default: 150) */
  scanWindowMs?: number;
}

/**
 * POS Barcode Input - Detects barcode scanner input.
 * USB barcode scanners typically send characters + Enter in rapid succession (< 100ms).
 * When detected, prioritizes barcode lookup over general search.
 */
export function POSBarcodeInput({
  value,
  onChange,
  onScan,
  onSearch,
  onKeyDown: onKeyDownProp,
  placeholder = "Escanear código o buscar producto...",
  className,
  autoFocus = true,
  inputRef: inputRefProp,
  restoreFocusOnSuccess = true,
  scanWindowMs = 150,
}: POSBarcodeInputProps) {
  const internalRef = useRef<HTMLInputElement>(null);
  const inputRef = inputRefProp || internalRef;
  const lastKeyTimeRef = useRef<number>(0);
  const bufferRef = useRef<string>("");

  const restoreFocus = useCallback(() => {
    setTimeout(() => inputRef.current?.focus(), 50);
  }, [inputRef]);

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLInputElement>) => {
      const now = Date.now();
      const timeSinceLastKey = now - lastKeyTimeRef.current;

      if (e.key === "Enter") {
        e.preventDefault();

        // If we received Enter within scanWindowMs of previous key, treat as barcode scan
        const isLikelyScan =
          timeSinceLastKey < scanWindowMs && bufferRef.current.length > 0;

        if (isLikelyScan && bufferRef.current.trim()) {
          const barcode = bufferRef.current.trim();
          onScan(barcode);
          bufferRef.current = "";
          onChange("");
          if (restoreFocusOnSuccess) restoreFocus();
        } else if (value.trim()) {
          const term = value.trim();
          // Prioritize barcode lookup for long numeric strings (EAN-13, etc.)
          const isLongNumeric = /^\d{12,}$/.test(term);
          if (isLongNumeric) {
            onScan(term);
            bufferRef.current = "";
            onChange("");
          } else {
            onSearch?.(term);
          }
          if (restoreFocusOnSuccess) restoreFocus();
        }
        lastKeyTimeRef.current = now;
        return;
      }

      // Delegate other keys (ArrowDown, ArrowUp, Escape) to parent
      if (e.key === "ArrowDown" || e.key === "ArrowUp" || e.key === "Escape") {
        onKeyDownProp?.(e);
        return;
      }

      // Track rapid character input (scanner sends chars very fast)
      if (e.key.length === 1 && !e.ctrlKey && !e.metaKey && !e.altKey) {
        lastKeyTimeRef.current = now;
        bufferRef.current = value + e.key;
      }
    },
    [
      value,
      onChange,
      onScan,
      onSearch,
      onKeyDownProp,
      restoreFocus,
      restoreFocusOnSuccess,
      scanWindowMs,
    ],
  );

  const handleChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const newValue = e.target.value;
      onChange(newValue);
      bufferRef.current = newValue;
    },
    [onChange],
  );

  useEffect(() => {
    if (autoFocus && inputRef.current) {
      inputRef.current.focus();
    }
  }, [autoFocus]);

  return (
    <div className={`relative ${className || ""}`}>
      <Scan className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 h-4 w-4" />
      <Input
        autoComplete="off"
        autoFocus={autoFocus}
        className="pl-10"
        placeholder={placeholder}
        ref={inputRef as React.Ref<HTMLInputElement>}
        type="text"
        value={value}
        onChange={handleChange}
        onKeyDown={handleKeyDown}
      />
    </div>
  );
}

"use client";

import { AlertCircle, ChevronDown } from "lucide-react";
import { toast } from "sonner";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { useBranch } from "@/hooks/useBranch";

interface POSBranchSelectorProps {
  /**
   * Callback cuando se selecciona una sucursal
   */
  onBranchSelected?: () => void;
  /**
   * Si se debe mostrar como alerta (true) o como selector normal (false)
   * Por defecto: true para super admins en modo global
   */
  showAsAlert?: boolean;
}

/**
 * Componente para seleccionar sucursal en el POS.
 * Muestra una alerta prominente para super admins en modo global,
 * o un selector normal cuando ya hay sucursal seleccionada.
 */
export function POSBranchSelector({
  onBranchSelected,
  showAsAlert = true,
}: POSBranchSelectorProps) {
  const {
    currentBranchId,
    currentBranchName,
    branches,
    isSuperAdmin,
    setCurrentBranch,
    isLoading,
  } = useBranch();

  // No mostrar nada si no es super admin (ellos siempre tienen sucursal)
  if (!isSuperAdmin) {
    return null;
  }

  // Si ya hay sucursal seleccionada, mostrar selector normal (opcional)
  if (currentBranchId && !showAsAlert) {
    return (
      <div className="flex items-center gap-2">
        <span className="text-sm text-gray-600">Sucursal:</span>
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button className="gap-1" size="sm" variant="outline">
              {currentBranchName}
              <ChevronDown className="h-4 w-4" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            {branches.map((branch) => (
              <DropdownMenuItem
                key={branch.id}
                onClick={() => {
                  setCurrentBranch(branch.id);
                  toast.success(`Sucursal cambiada a: ${branch.name}`);
                  onBranchSelected?.();
                }}
              >
                {branch.name}
              </DropdownMenuItem>
            ))}
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    );
  }

  // Modo global (sin sucursal seleccionada) - mostrar alerta prominente
  if (!currentBranchId && showAsAlert) {
    return (
      <Alert className="mb-4 border-2" variant="destructive">
        <AlertCircle className="h-5 w-5" />
        <AlertTitle className="font-bold">
          Selecciona una sucursal para habilitar la caja
        </AlertTitle>
        <AlertDescription className="mt-2 space-y-3">
          <p className="text-sm">
            Como super administrador, estás en <strong>modo global</strong>.
            Para realizar ventas en el POS, debes seleccionar una sucursal
            específica.
          </p>
          <div className="flex flex-wrap gap-2">
            {isLoading ? (
              <Button disabled size="sm">
                Cargando sucursales...
              </Button>
            ) : (
              branches.map((branch) => (
                <Button
                  key={branch.id}
                  size="sm"
                  onClick={() => {
                    setCurrentBranch(branch.id);
                    toast.success(`Sucursal seleccionada: ${branch.name}`);
                    onBranchSelected?.();
                  }}
                >
                  {branch.name}
                </Button>
              ))
            )}
          </div>
          <p className="text-xs text-gray-600">
            La selección de sucursal afecta: inventario, caja, y reportes de
            ventas.
          </p>
        </AlertDescription>
      </Alert>
    );
  }

  return null;
}

"use client";

import { Minus, Percent, Plus, ShoppingCart, Trash2, X } from "lucide-react";
import { memo, useCallback, useState } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { formatCurrency } from "@/lib/utils";

import type { DiscountType } from "../hooks/usePOSDiscount";
import type { POSCartItem } from "../types";

interface POSCartProps {
  items: POSCartItem[];
  subtotal: number;
  taxAmount: number;
  total: number;
  onUpdateQuantity: (productId: string, quantity: number) => void;
  onRemove: (productId: string) => void;
  onClear?: () => void;
  // Discount props
  discountType?: DiscountType;
  discountValue?: number;
  discountAmount?: number;
  onDiscountTypeChange?: (type: DiscountType) => void;
  onDiscountValueChange?: (value: number) => void;
  onClearDiscount?: () => void;
}

// Memoized CartItem component for individual items
const CartItemRow = memo(function CartItemRow({
  item,
  onUpdateQuantity,
  onRemove,
}: {
  item: POSCartItem;
  onUpdateQuantity: (productId: string, quantity: number) => void;
  onRemove: (productId: string) => void;
}) {
  const handleDecrease = useCallback(
    () => onUpdateQuantity(item.product.id, item.quantity - 1),
    [onUpdateQuantity, item.product.id, item.quantity],
  );

  const handleIncrease = useCallback(
    () => onUpdateQuantity(item.product.id, item.quantity + 1),
    [onUpdateQuantity, item.product.id, item.quantity],
  );

  const handleRemove = useCallback(
    () => onRemove(item.product.id),
    [onRemove, item.product.id],
  );

  return (
    <div className="flex items-center justify-between p-2 rounded-lg bg-white dark:bg-gray-900 border">
      <div className="flex-1 min-w-0">
        <p className="font-medium text-sm truncate">{item.product.name}</p>
        <p className="text-xs text-gray-500">
          {formatCurrency(item.unitPrice)} × {item.quantity}
        </p>
      </div>
      <div className="flex items-center gap-1 ml-2">
        <Button
          className="h-7 w-7"
          size="icon"
          variant="ghost"
          onClick={handleDecrease}
        >
          <Minus className="h-3 w-3" />
        </Button>
        <span className="text-sm font-medium w-6 text-center">
          {item.quantity}
        </span>
        <Button
          className="h-7 w-7"
          size="icon"
          variant="ghost"
          onClick={handleIncrease}
        >
          <Plus className="h-3 w-3" />
        </Button>
        <Button
          className="h-7 w-7 text-red-600 hover:text-red-700"
          size="icon"
          variant="ghost"
          onClick={handleRemove}
        >
          <Trash2 className="h-3 w-3" />
        </Button>
      </div>
      <div className="text-sm font-semibold ml-2 w-20 text-right">
        {formatCurrency(item.subtotal)}
      </div>
    </div>
  );
});

CartItemRow.displayName = "CartItemRow";

export const POSCart = memo(function POSCart({
  items,
  subtotal,
  taxAmount,
  total,
  onUpdateQuantity,
  onRemove,
  // Discount props
  discountType = "percentage",
  discountValue = 0,
  discountAmount = 0,
  onDiscountTypeChange,
  onDiscountValueChange,
  onClearDiscount,
}: POSCartProps) {
  const [showDiscountInput, setShowDiscountInput] = useState(false);
  const [inputValue, setInputValue] = useState(discountValue.toString());

  const hasDiscount = discountAmount > 0;

  // Update local input when prop changes
  const handleApplyDiscount = () => {
    const value = parseFloat(inputValue) || 0;
    onDiscountValueChange?.(value);
    setShowDiscountInput(false);
  };

  const handleClearDiscount = () => {
    onClearDiscount?.();
    setInputValue("0");
  };
  return (
    <Card className="flex flex-col h-full bg-[var(--admin-bg-tertiary)]">
      <CardHeader className="pb-2 flex-shrink-0">
        <CardTitle className="flex items-center gap-2 text-lg">
          <ShoppingCart className="h-5 w-5" />
          Carrito
          {items.length > 0 && (
            <Badge className="ml-2" variant="secondary">
              {items.length}
            </Badge>
          )}
        </CardTitle>
      </CardHeader>
      <CardContent className="flex-1 overflow-y-auto p-0 flex flex-col min-h-0">
        {items.length === 0 ? (
          <div className="flex-1 flex items-center justify-center p-6 text-center text-gray-500">
            <div>
              <ShoppingCart className="h-12 w-12 mx-auto mb-2 opacity-40" />
              <p className="text-sm">El carrito está vacío</p>
              <p className="text-xs mt-1">Busca productos para agregar</p>
            </div>
          </div>
        ) : (
          <div className="space-y-2 p-2">
            {items.map((item, index) => (
              <CartItemRow
                item={item}
                key={`${item.product.id}-${index}`}
                onRemove={onRemove}
                onUpdateQuantity={onUpdateQuantity}
              />
            ))}
          </div>
        )}

        {items.length > 0 && (
          <div className="mt-auto p-4 border-t space-y-1 flex-shrink-0">
            {/* Subtotal */}
            <div className="flex justify-between text-sm">
              <span className="text-gray-600">Subtotal</span>
              <span>{formatCurrency(subtotal)}</span>
            </div>

            {/* Discount section */}
            {hasDiscount && (
              <div className="flex justify-between text-sm text-red-600">
                <span className="flex items-center gap-1">
                  <Percent className="h-3 w-3" />
                  Descuento
                </span>
                <span>-{formatCurrency(discountAmount)}</span>
              </div>
            )}

            {/* Discount input toggle */}
            <div className="flex justify-between text-sm">
              {!showDiscountInput ? (
                <Button
                  className="h-6 text-xs text-gray-500 -ml-2"
                  size="sm"
                  type="button"
                  variant="ghost"
                  onClick={() => setShowDiscountInput(true)}
                >
                  <Percent className="h-3 w-3 mr-1" />
                  Aplicar descuento
                </Button>
              ) : (
                <div className="flex items-center gap-2 w-full">
                  <Select
                    value={discountType}
                    onValueChange={(v) =>
                      onDiscountTypeChange?.(v as DiscountType)
                    }
                  >
                    <SelectTrigger className="h-7 w-20 text-xs">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="percentage">%</SelectItem>
                      <SelectItem value="amount">$</SelectItem>
                    </SelectContent>
                  </Select>
                  <Input
                    className="h-7 w-20 text-xs"
                    max={discountType === "percentage" ? 100 : undefined}
                    min={0}
                    placeholder={
                      discountType === "percentage" ? "0-100" : "Monto"
                    }
                    type="number"
                    value={inputValue}
                    onChange={(e) => setInputValue(e.target.value)}
                  />
                  <Button
                    className="h-7"
                    size="sm"
                    type="button"
                    onClick={handleApplyDiscount}
                  >
                    OK
                  </Button>
                  <Button
                    className="h-7"
                    size="sm"
                    type="button"
                    variant="ghost"
                    onClick={() => setShowDiscountInput(false)}
                  >
                    <X className="h-3 w-3" />
                  </Button>
                </div>
              )}
            </div>

            {/* Clear discount button */}
            {hasDiscount && !showDiscountInput && (
              <Button
                className="h-6 text-xs text-red-600 -ml-2"
                size="sm"
                type="button"
                variant="ghost"
                onClick={handleClearDiscount}
              >
                <X className="h-3 w-3 mr-1" />
                Quitar descuento
              </Button>
            )}

            {/* IVA */}
            <div className="flex justify-between text-sm">
              <span className="text-gray-600">IVA</span>
              <span>{formatCurrency(taxAmount)}</span>
            </div>

            {/* Total */}
            <div className="flex justify-between font-bold text-lg pt-2 border-t">
              <span>Total</span>
              <span>{formatCurrency(total)}</span>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
});

POSCart.displayName = "POSCart";

"use client";

import type { DiscountType } from "../hooks";
import type { POSCartItem } from "../types";
import { POMPaymentSection } from "./POMPaymentSection";
import { POSCart } from "./POSCart";

export interface POSCartPanelProps {
  cart: POSCartItem[];
  subtotal: number;
  taxAmount: number;
  total: number;
  change: number;
  paymentMethod: string;
  cashReceived: number;
  onUpdateQuantity: (productId: string, quantity: number) => void;
  onRemoveFromCart: (productId: string) => void;
  onClearCart: () => void;
  onPaymentMethodChange: (method: string) => void;
  onCashReceivedChange: (amount: number) => void;
  onQuickCash: (amount: number) => void;
  onOpenPaymentDialog: () => void;

  // Discount
