}

"use client";

import { Calculator, RotateCcw } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { formatCurrency } from "@/lib/utils";

interface POSCashInputProps {
  value: number;
  onChange: (value: number) => void;
  total: number;
  disabled?: boolean;
}

const quickAmounts = [10000, 20000];

export function POSCashInput({
  value,
  onChange,
  total,
  disabled = false,
}: POSCashInputProps) {
  const change = Math.max(0, value - total);
  const isSufficient = value >= total;

  const handleQuickAmount = (amount: number) => {
    onChange(amount);
  };

  const handleSetExact = () => {
    onChange(total);
  };

  const handleReset = () => {
    onChange(0);
  };

  return (
    <div className="space-y-4">
      {/* Quick amounts - only 10000 and 20000 in one row */}
      <div className="space-y-2">
        <Label className="text-xs text-muted-foreground">Montos rápidos</Label>
        <div className="flex gap-2">
          {quickAmounts.map((amount) => (
            <Button
              className="flex-1 font-mono"
              disabled={disabled}
              key={amount}
              size="lg"
              type="button"
              variant="outline"
              onClick={() => handleQuickAmount(amount)}
            >
              {formatCurrency(amount)}
            </Button>
          ))}
        </div>
      </div>

      {/* Action buttons - Exacto and Revertir */}
      <div className="flex gap-2">
        <Button
          className="flex-1 gap-2"
          disabled={disabled}
          size="lg"
          type="button"
          variant="secondary"
          onClick={handleSetExact}
        >
          <Calculator className="h-4 w-4" />
          Monto exacto
        </Button>
        <Button
          disabled={disabled}
          size="lg"
          title="Revertir"
          type="button"
          variant="ghost"
          onClick={handleReset}
        >
          <RotateCcw className="h-4 w-4" />
        </Button>
      </div>

      {/* Input */}
      <div className="space-y-2">
        <Label htmlFor="cash-received">Monto Recibido</Label>
        <div className="relative">
          <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">
            $
          </span>
          <Input
            className="pl-8 text-lg font-mono"
            disabled={disabled}
            id="cash-received"
            min={0}
            placeholder="0"
            step={100}
            type="number"
            value={value || ""}
            onChange={(e) => onChange(parseInt(e.target.value) || 0)}
          />
        </div>
      </div>

      {/* Change display */}
      <div
        className={`
          p-4 rounded-lg border-2 text-center transition-all
          ${
            isSufficient
              ? "bg-green-50 border-green-200 dark:bg-green-950/20"
              : "bg-muted/50 border-border"
          }
        `}
      >
        <p className="text-sm text-muted-foreground">Vuelto</p>
        <p
          className={`
            text-2xl font-bold font-mono
            ${isSufficient ? "text-green-600 dark:text-green-400" : "text-muted-foreground"}
          `}
        >
          {formatCurrency(change)}
        </p>
        {!isSufficient && (
          <p className="text-xs text-muted-foreground mt-1">
            Faltan {formatCurrency(total - value)}
          </p>
        )}
      </div>
    </div>
  );
}

"use client";

import { useCallback, useRef } from "react";

import { usePOS } from "../hooks";
import type { POSCustomer, POSProduct } from "../types";
import { POSAdvancedSale } from "./POSAdvancedSale";
import type { POSAdvancedSaleProps } from "./POSAdvancedSale.types";
import { POSCustomerSearch } from "./POSCustomerSearch";
import { POSProductSearch } from "./POSProductSearch";
import type { SaleMode } from "./POSSaleToggle";
import { POSSaleToggle } from "./POSSaleToggle";

export interface POSContentPanelProps {
  saleMode: SaleMode;
  onSaleModeChange: (mode: SaleMode) => void;
  selectedProductIndex: number;
  setSelectedProductIndex: (i: number) => void;
  onLoadQuote: (input: string) => Promise<void>;
  onProductKeyDown: (
    e: React.KeyboardEvent,
    products: POSProduct[],
    selectedIdx: number,
    addToCartFn: (p: POSProduct) => void,
    clearSearchFn: () => void,
    setSelectedIdxFn: (i: number) => void,
  ) => void;
}

export function POSContentPanel({
  saleMode,
  onSaleModeChange,
  selectedProductIndex,
  setSelectedProductIndex,
  onLoadQuote,
  onProductKeyDown,
}: POSContentPanelProps) {
  const searchInputRef = useRef<HTMLInputElement>(null);
  const suggestionsRef = useRef<HTMLDivElement>(null);
  const customerSearchInputRef = useRef<HTMLInputElement>(null);
  const customerSuggestionsRef = useRef<HTMLDivElement>(null);

  const handleCustomerKeyDown = useCallback((e: React.KeyboardEvent) => {
    if (e.key === "Enter") {
      // Handle customer selection - default behavior is fine
    }
  }, []);

  const {
    customerSearchTerm,
    setCustomerSearchTerm,
    customerResults,
    customerLoading,
    customer,
    setCustomer,
    customerBusinessName,
    setCustomerBusinessName,
    customerRUT,
    setCustomerRUT,
    customerEmail,
    setCustomerEmail,
    customerPhone,
    setCustomerPhone,
    clearCustomer,
    productSearchTerm,
    setProductSearchTerm,
    productResults,
    productLoading,
    handleSelectProduct,
    clearProductSearch,
    addToCart,
    quotes,
    selectedQuote,
    loadingQuotes,
    handleSelectQuote,
    branchId,
  } = usePOS();

  const handleCustomerSelect = useCallback(
    (c: POSCustomer) => {
      setCustomer(c);
      if (c?.rut) setCustomerRUT(c.rut);
      if (c?.business_name) setCustomerBusinessName(c.business_name);
    },
    [setCustomer, setCustomerRUT, setCustomerBusinessName],
  );

  const handleClearCustomer = useCallback(() => {
    clearCustomer();
    setCustomerRUT("");
    setCustomerBusinessName("");
    setCustomerEmail("");
    setCustomerPhone("");
  }, [
    clearCustomer,
    setCustomerRUT,
    setCustomerBusinessName,
    setCustomerEmail,
    setCustomerPhone,
  ]);

  const handleAdvancedCustomerChange = useCallback(
    (c: POSAdvancedSaleProps["customer"]) => {
      if (c) {
        setCustomer({
          id: c.id,
          name: c.name ?? undefined,
          first_name: c.first_name ?? undefined,
          last_name: c.last_name ?? undefined,
          email: c.email ?? undefined,
          rut: c.rut ?? undefined,
          business_name: c.business_name ?? undefined,
          phone: null,
        });
        if (c.rut) setCustomerRUT(c.rut);
        if (c.business_name) setCustomerBusinessName(c.business_name);
      } else {
        setCustomer(null);
        setCustomerRUT("");
        setCustomerBusinessName("");
      }
    },
    [setCustomer, setCustomerRUT, setCustomerBusinessName],
  );

  return (
    <div className="flex-1 flex flex-col overflow-hidden">
      {/* Customer section */}
      <div className="p-4 border-b">
        <POSCustomerSearch
          customerBusinessName={customerBusinessName}
          customerEmail={customerEmail}
          customerPhone={customerPhone}
          customerRUT={customerRUT}
          inputRef={customerSearchInputRef}
          loading={customerLoading}
          loadingQuotes={loadingQuotes}
          quotes={quotes}
          results={customerResults}
          searchTerm={customerSearchTerm}
          selectedCustomer={customer}
          selectedIndex={-1}
          selectedQuote={selectedQuote}
          suggestionsRef={customerSuggestionsRef}
          onBusinessNameChange={setCustomerBusinessName}
          onClearCustomer={handleClearCustomer}
          onCustomerEmailChange={setCustomerEmail}
          onCustomerPhoneChange={setCustomerPhone}
          onKeyDown={handleCustomerKeyDown}
          onLoadQuote={onLoadQuote}
          onRUTChange={setCustomerRUT}
          onSearchChange={setCustomerSearchTerm}
          onSelectCustomer={handleCustomerSelect}
          onSelectQuote={handleSelectQuote}
        />
      </div>

      {/* Sale mode toggle */}
      <div className="px-4 py-2 border-b">
        <POSSaleToggle mode={saleMode} onModeChange={onSaleModeChange} />
      </div>

      {/* Sale mode content */}
      {saleMode === "quick" ? (
        <div className="flex-1 p-4 overflow-y-auto">
          <POSProductSearch
            inputRef={searchInputRef}
            loading={productLoading}
            products={productResults}
            searchTerm={productSearchTerm}
            selectedIndex={selectedProductIndex}
            suggestionsRef={suggestionsRef}
            onKeyDown={(e) =>
              onProductKeyDown(
                e,
                productResults,
                selectedProductIndex,
                addToCart,
                clearProductSearch,
                setSelectedProductIndex,
              )
            }
            onSearchChange={setProductSearchTerm}
            onSelectProduct={(product) => {
              handleSelectProduct(product);
              setSelectedProductIndex(-1);
            }}
          />
        </div>
      ) : (
        <div className="flex-1 overflow-hidden">
          <POSAdvancedSale
            branchId={branchId}
            customer={
              customer
                ? {
                    id: customer.id,
                    name: customer.name || undefined,
                    first_name: customer.first_name || undefined,
                    last_name: customer.last_name || undefined,
                    email: customer.email || undefined,
                    rut: customer.rut || undefined,
                    business_name: customer.business_name || undefined,
                  }
                : null
            }
            quickCustomerEmail={customerEmail || null}
            quickCustomerName={customerBusinessName || null}
            quickCustomerPhone={customerPhone || null}
            quickCustomerRUT={customerRUT || null}
            onAddToCart={(items) => {
              items.forEach((item) => addToCart(item.product as POSProduct));
            }}
            onCustomerChange={handleAdvancedCustomerChange}
          />
        </div>
      )}
    </div>
  );
}

"use client";

import { Loader2, Search, X } from "lucide-react";
import { useEffect, useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";

import type { POSCustomer, POSQuote } from "../types";
import { POSQuickCustomerFields } from "./_components/POSQuickCustomerFields";
import { POSQuoteSelectionDialog } from "./_components/POSQuoteSelectionDialog";

interface POSCustomerSearchProps {
  searchTerm: string;
  onSearchChange: (value: string) => void;
  results: POSCustomer[];
  loading: boolean;
  selectedCustomer: POSCustomer | null;
  selectedIndex: number;
  onSelectCustomer: (customer: POSCustomer) => void;
  onHoverResult?: (index: number) => void;
  onClearCustomer: () => void;
  onKeyDown: (e: React.KeyboardEvent) => void;
  customerBusinessName: string;
  onBusinessNameChange: (value: string) => void;
  customerRUT: string;
  onRUTChange: (value: string) => void;
  customerEmail?: string;
  onCustomerEmailChange?: (value: string) => void;
  customerPhone?: string;
  onCustomerPhoneChange?: (value: string) => void;
  inputRef?: React.RefObject<HTMLInputElement | null>;
  suggestionsRef?: React.RefObject<HTMLDivElement | null>;
  // Quotes
  quotes?: POSQuote[];
  loadingQuotes?: boolean;
  selectedQuote?: POSQuote | null;
  onLoadQuote?: (quoteId: string) => void;
  onSelectQuote?: (quote: POSQuote) => void;
}

export function POSCustomerSearch({
  searchTerm,
  onSearchChange,
  results,
  loading,
  selectedCustomer,
  selectedIndex,
  onSelectCustomer,
  onHoverResult,
  onClearCustomer,
  onKeyDown,
  customerBusinessName,
  onBusinessNameChange,
  customerRUT,
  onRUTChange,
  customerEmail = "",
  onCustomerEmailChange,
  customerPhone = "",
  onCustomerPhoneChange,
  inputRef,
  suggestionsRef,
  quotes = [],
  loadingQuotes = false,
  selectedQuote,
  onLoadQuote,
  onSelectQuote,
}: POSCustomerSearchProps) {
  const quotesCount = quotes.length;
  const [quoteInput, setQuoteInput] = useState("");
  const [showQuoteDialog, setShowQuoteDialog] = useState(false);
  const [loadingQuote, setLoadingQuote] = useState(false);
  const [showQuickCustomerFields, setShowQuickCustomerFields] = useState(false);
  const quickCustomerRef = useRef<HTMLDivElement>(null);

  // Check if there's quick customer data entered
  const hasQuickCustomerData =
    customerBusinessName?.trim() ||
    customerRUT?.trim() ||
    customerEmail?.trim() ||
    customerPhone?.trim();

  // Close quick customer fields when clicking outside, only if no data entered
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        showQuickCustomerFields &&
        quickCustomerRef.current &&
        !quickCustomerRef.current.contains(event.target as Node) &&
        !hasQuickCustomerData
      ) {
        setShowQuickCustomerFields(false);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, [showQuickCustomerFields, hasQuickCustomerData]);

  const handleLoadQuote = async () => {
    if (!quoteInput.trim() || !onLoadQuote) return;

    setLoadingQuote(true);
    try {
      await onLoadQuote(quoteInput.trim());
      setShowQuoteDialog(false);
      setQuoteInput("");
    } finally {
      setLoadingQuote(false);
    }
  };

  // When customer is selected, show their name in the search input
  const displaySearchValue = selectedCustomer
    ? selectedCustomer.name || selectedCustomer.email || ""
    : searchTerm;

  return (
    <div className="space-y-3">
      {/* Customer search - hide when quick customer data is entered */}
      {!hasQuickCustomerData && (
        <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 h-4 w-4" />
          <Input
            autoComplete="off"
            className="pl-10"
            placeholder={
              selectedCustomer
                ? ""
                : "Buscar cliente (nombre, email, teléfono, RUT)..."
            }
            ref={inputRef as React.Ref<HTMLInputElement>}
            value={displaySearchValue}
            onChange={(e) => onSearchChange(e.target.value)}
            onKeyDown={onKeyDown}
          />
        </div>
      )}

      {/* Search results - hide when quick customer data is entered */}
      {searchTerm.trim().length > 0 &&
        !selectedCustomer &&
        !hasQuickCustomerData && (
          <div className="relative">
            {loading && (
              <div className="absolute inset-0 bg-white/80 dark:bg-gray-900/80 backdrop-blur-sm flex items-center justify-center z-10 rounded-lg border">
                <Loader2 className="h-5 w-5 animate-spin text-gray-400" />
              </div>
            )}

            {!loading && results.length > 0 && (
              <div
                className="max-h-60 overflow-y-auto border rounded-lg bg-white dark:bg-gray-900 shadow-lg z-20"
                ref={suggestionsRef as React.Ref<HTMLDivElement>}
              >
                {results.map((customer, index) => (
                  <button
                    className={`w-full p-3 text-left border-b last:border-b-0 flex justify-between items-center transition-colors ${
                      selectedIndex === index
                        ? "bg-blue-50 dark:bg-blue-900/30 border-blue-200"
                        : "hover:bg-gray-50 dark:hover:bg-gray-800"
                    }`}
                    key={customer.id}
                    type="button"
                    onClick={() => onSelectCustomer(customer)}
                    onMouseEnter={() => onHoverResult?.(index)}
                  >
                    <div className="flex-1 min-w-0">
                      <div className="font-semibold text-gray-900 dark:text-gray-100 truncate">
                        {customer.name ||
                          (customer.first_name && customer.last_name
                            ? `${customer.first_name} ${customer.last_name}`
                            : customer.email)}
                      </div>
                      <div className="text-xs text-gray-600 dark:text-gray-400 mt-1 flex flex-wrap gap-2">
                        {customer.email && <span>{customer.email}</span>}
                        {customer.phone && <span>Tel: {customer.phone}</span>}
                        {customer.rut && <span>RUT: {customer.rut}</span>}
                      </div>
                    </div>
                    {selectedIndex === index && (
                      <div className="text-xs text-blue-600 ml-2">Enter</div>
                    )}
                  </button>
                ))}
              </div>
            )}

            {!loading &&
              searchTerm.trim().length > 0 &&
              results.length === 0 && (
                <div className="border rounded-lg bg-white dark:bg-gray-900 p-3 text-center text-gray-500 text-sm">
                  <p>No se encontraron clientes</p>
                  <p className="text-xs mt-1">
                    Puedes continuar sin cliente o ingresar datos manualmente
                  </p>
                </div>
              )}
          </div>
        )}

      {selectedCustomer ? (
        <div className="space-y-2 p-3 bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-800 rounded-lg">
          <div className="flex items-center justify-between">
            <div className="flex-1">
              <div className="font-medium text-green-900 dark:text-green-100">
                {selectedCustomer.name || selectedCustomer.email}
              </div>
              {selectedCustomer.rut && (
                <div className="text-sm text-green-700 dark:text-green-300 mt-1">
                  RUT: {selectedCustomer.rut}
                </div>
              )}
            </div>
            <Button
              className="text-red-600 hover:text-red-700 hover:bg-red-50 dark:hover:bg-red-900/20"
              size="sm"
              variant="ghost"
              onClick={onClearCustomer}
            >
              <X className="h-4 w-4" />
            </Button>
          </div>
          {quotesCount > 0 && (
            <div className="mt-2 text-xs text-green-700 dark:text-green-300">
              {quotesCount} presupuesto(s) disponible(s)
            </div>
          )}
          {/* Quote Selection Dialog */}
          {selectedCustomer && quotes.length > 0 && (
            <POSQuoteSelectionDialog
              loadingQuotes={loadingQuotes}
              open={showQuoteDialog}
              quotes={quotes}
              selectedQuote={selectedQuote ?? null}
              onOpenChange={setShowQuoteDialog}
              onSelectQuote={(quote) => {
                onSelectQuote?.(quote);
                setShowQuoteDialog(false);
              }}
            />
          )}
          {/* Show message when no quotes available */}
          {selectedCustomer && quotes.length === 0 && !loadingQuotes && (
            <div className="mt-2 text-xs text-amber-600 dark:text-amber-400">
              <p>No hay presupuestos disponibles para este cliente</p>
              <p className="text-gray-500 mt-1">
                Puedes crear un nuevo presupuesto desde el módulo de
                Presupuestos
              </p>
            </div>
          )}
          {/* Manual Quote Input - only show when customer is selected but has no quotes and onLoadQuote is available */}
          {selectedCustomer &&
            quotes.length === 0 &&
            onLoadQuote &&
            loadingQuotes && (
              <div className="flex items-center justify-center py-2">
                <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
                <span className="ml-2 text-xs text-muted-foreground">
                  Cargando presupuestos...
                </span>
              </div>
            )}
        </div>
      ) : (
        <div className="space-y-2">
          <div className="text-xs text-gray-500">
            Cliente no seleccionado (opcional)
          </div>
          {/* Quick customer fields - progressive disclosure */}
          <div ref={quickCustomerRef}>
            <POSQuickCustomerFields
              customerBusinessName={customerBusinessName}
              customerEmail={customerEmail}
              customerPhone={customerPhone}
              customerRUT={customerRUT}
              showQuickCustomerFields={showQuickCustomerFields}
              onBusinessNameChange={onBusinessNameChange}
              onCustomerEmailChange={onCustomerEmailChange}
              onCustomerPhoneChange={onCustomerPhoneChange}
              onRUTChange={onRUTChange}
              onShowFieldsChange={setShowQuickCustomerFields}
            />
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import {
  AlertCircle,
  ArrowLeft,
  CreditCard,
  DollarSign,
  Loader2,
  X,
} from "lucide-react";
import Link from "next/link";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { formatCurrency } from "@/lib/utils";

import { POSBranchSelector } from "./POSBranchSelector";

export interface POSHeaderProps {
  // Branch
  currentBranchId?: string | null;
  isSuperAdmin?: boolean;
  branches?: Array<{ id: string; name: string }>;
  onBranchChange?: (branchId: string) => void;

  // Operativo
  operativo?: { id: string; name: string; branch_id: string } | null;
  fieldOperationIdFromUrl?: string | null;

  // Cash status
  isCashOpen?: boolean | null;
  checkingCashStatus?: boolean;
  effectiveBranchId?: string | null;

  // Cart totals
  cartLength?: number;
  total?: number;

  // Actions
  onOpenPendingBalance?: () => void;
  onClearCart?: () => void;

  // Loading states
  operativoLoading?: boolean;
}

export function POSHeader({
  currentBranchId,
  isSuperAdmin,
  branches = [],
  onBranchChange,
  operativo,
  fieldOperationIdFromUrl,
  isCashOpen,
  checkingCashStatus,
  effectiveBranchId,
  cartLength,
  total,
  onOpenPendingBalance,
  onClearCart,
  operativoLoading = false,
}: POSHeaderProps) {
  return (
    <>
      {/* Operativo mode banner */}
      {operativo && fieldOperationIdFromUrl && (
        <div className="flex-shrink-0 px-4 sm:px-6 py-2 bg-admin-accent-primary/20 border-b border-admin-accent-primary/30 flex items-center justify-between gap-2 flex-wrap">
          <span className="text-sm font-medium text-admin-text-primary">
            Modo operativo: {operativo.name}
          </span>
          <div className="flex items-center gap-3">
            <Link
              className="inline-flex items-center gap-1.5 text-sm text-admin-accent-primary hover:underline font-medium underline-offset-2"
              href={`/admin/field-operations/${fieldOperationIdFromUrl}`}
            >
              <ArrowLeft className="h-4 w-4" />
              Volver al operativo
            </Link>
            <Link
              className="text-sm text-admin-accent-primary hover:underline font-medium underline-offset-2"
              href="/admin/pos"
            >
              Salir del modo operativo
            </Link>
          </div>
        </div>
      )}

      {/* Header - title, subtitle, Caja | Saldos */}
      <div className="border-b px-4 sm:px-6 py-3 sm:py-4 bg-[var(--admin-bg-primary)] flex-shrink-0">
        <div className="flex flex-col gap-3">
          {/* Title and subtitle */}
          <div className="min-w-0">
            <h1
              className="text-lg sm:text-2xl font-bold text-gray-900 truncate"
              data-tour="pos-header"
            >
              Punto de Venta (POS)
            </h1>
            <p className="text-sm text-gray-600">
              {operativo
                ? `Sistema de ventas - ${operativo.name}`
                : !currentBranchId && isSuperAdmin
                  ? "Sistema de ventas - Todas las sucursales"
                  : "Sistema de ventas"}
            </p>
          </div>

          {/* Branch selector (desktop only when not in operativo) */}
          {!operativo && <POSBranchSelector />}

          {/* Action buttons */}
          <div className="flex items-center justify-between gap-2">
            <Link href="/admin/cash-register">
              <Button
                className="min-h-[44px] sm:min-h-0"
                size="sm"
                variant="outline"
              >
                <DollarSign className="h-4 w-4 mr-2" />
                Caja
              </Button>
            </Link>
            <Button
              className="min-h-[44px] sm:min-h-0"
              size="sm"
              title="Cobrar saldos pendientes de órdenes"
              variant="outline"
              onClick={onOpenPendingBalance}
            >
              <CreditCard className="h-4 w-4 mr-2" />
              <span className="hidden sm:inline">Saldos Pendientes</span>
              <span className="sm:hidden">Saldos</span>
            </Button>
          </div>

          {/* Desktop only: Total and Clear */}
          <div className="hidden lg:flex flex-row items-center justify-between gap-2">
            <Badge
              className="text-base sm:text-lg px-3 sm:px-4 py-1.5 sm:py-2"
              variant="outline"
            >
              Total: {formatCurrency(total)}
            </Badge>
            <Button
              className="min-h-[40px] sm:min-h-0"
              disabled={cartLength === 0}
              size="sm"
              variant="outline"
              onClick={onClearCart}
            >
              <X className="h-4 w-4 mr-2" />
              Limpiar
            </Button>
          </div>
        </div>
      </div>

      {/* Cash Status Alert */}
      {operativoLoading ? (
        <div className="hidden lg:block px-4 sm:px-6 py-3 bg-gray-50 border-b">
          <div className="flex items-center gap-2 text-sm text-gray-600">
            <Loader2 className="h-4 w-4 animate-spin" />
            Cargando operativo...
          </div>
        </div>
      ) : !effectiveBranchId && isSuperAdmin ? (
        <div className="hidden lg:block px-4 sm:px-6 py-3 bg-amber-50 border-b border-amber-200">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2">
            <div className="flex items-center gap-2 text-sm text-amber-800">
              <AlertCircle className="h-4 w-4 flex-shrink-0" />
              <span>
                <span className="font-semibold">Selecciona una sucursal</span>
                <span className="hidden sm:inline">
                  {" "}
                  - Debes seleccionar una sucursal para poder procesar ventas
                </span>
              </span>
            </div>
            <Select
              value={currentBranchId || ""}
              onValueChange={onBranchChange}
            >
              <SelectTrigger className="h-9 w-48 text-sm">
                <SelectValue placeholder="Seleccionar sucursal" />
              </SelectTrigger>
              <SelectContent>
                {branches?.map((branch) => (
                  <SelectItem key={branch.id} value={branch.id}>
                    {branch.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>
      ) : effectiveBranchId ? (
        <div
          className={`hidden lg:block px-4 sm:px-6 py-3 ${isCashOpen === false ? "bg-red-50 border-b border-red-200" : isCashOpen === true ? "bg-green-50 border-b border-green-200" : ""}`}
        >
          {checkingCashStatus ? (
            <div className="flex items-center gap-2 text-sm text-gray-600">
              <Loader2 className="h-4 w-4 animate-spin" />
              Verificando estado de caja...
            </div>
          ) : isCashOpen === false ? (
            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2">
              <div className="flex items-center gap-2 text-sm text-red-800">
                <AlertCircle className="h-4 w-4 flex-shrink-0" />
                <span>
                  <span className="font-semibold">
                    {fieldOperationIdFromUrl
                      ? "La caja del operativo está cerrada"
                      : "La caja está cerrada"}
                  </span>
                  <span className="hidden sm:inline">
                    {" "}
                    -{" "}
                    {fieldOperationIdFromUrl
                      ? "Abre la caja desde el operativo para poder cobrar"
                      : "Abre la caja para poder procesar ventas"}
                  </span>
                </span>
              </div>
              <Link href="/admin/cash-register">
                <Button size="sm" variant="default">
                  <DollarSign className="h-4 w-4 mr-2" />
                  Abrir Caja
                </Button>
              </Link>
            </div>
          ) : (
            <div className="flex items-center gap-2 text-sm text-green-800">
              <DollarSign className="h-4 w-4" />
              <span className="font-semibold">Caja abierta</span>
              {fieldOperationIdFromUrl && (
                <span className="hidden sm:inline"> - Operativo activo</span>
              )}
            </div>
          )}
        </div>
      ) : null}
    </>
  );
}

"use client";

import { AlertCircle,Loader2  } from "lucide-react";
import { useEffect } from "react";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { formatCurrency } from "@/lib/utils";

import type { POSCartItem, POSCustomer, POSPaymentMethod } from "../types";
import { PaymentForm } from "./_components/PaymentForm";
import { PaymentMethodFields } from "./_components/PaymentMethodFields";

interface POSPaymentDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;

  // Cart data
  items: POSCartItem[];
  subtotal: number;
  taxAmount: number;
  total: number;

  // Customer
  customer: POSCustomer | null;
  customerBusinessName?: string;
  customerRUT?: string;

  // Payment state
  paymentMethod: POSPaymentMethod;
  cashReceived: number;
  onPaymentMethodChange: (method: POSPaymentMethod) => void;
  onCashReceivedChange: (amount: number) => void;

  // Partial payment
  isPartialPayment: boolean;
  partialAmount: number;
  onPartialPaymentChange: (isPartial: boolean, amount?: number) => void;

  // Actions
  onConfirm: () => Promise<void>;
  onCancel?: () => void;

  // Cash register status
  isCashOpen?: boolean;

  // Loading
  isProcessing?: boolean;
  canProcess?: boolean;
}

export function POSPaymentDialog({
  open,
  onOpenChange,
  items,
  subtotal,
  taxAmount,
  total,
  customer,
  customerBusinessName,
  customerRUT,
  paymentMethod,
  cashReceived,
  onPaymentMethodChange,
  onCashReceivedChange,
  isPartialPayment,
  partialAmount,
  onPartialPaymentChange,
  onConfirm,
  onCancel,
  isCashOpen = true,
  isProcessing = false,
  canProcess = true,
}: POSPaymentDialogProps) {
  // Alert when cash register is closed
  useEffect(() => {
    if (open && !isCashOpen) {
      // We can't show toast here directly, but we disable the button
    }
  }, [open, isCashOpen]);

  const showAgreementFields = paymentMethod === "agreement";
  const showPaymentFields = !showAgreementFields;
  const showCashInput = paymentMethod === "cash";

  const handleClose = () => {
    if (!isProcessing) {
      onOpenChange(false);
      onCancel?.();
    }
  };

  const handleConfirm = async () => {
    await onConfirm();
  };

  // Calculate what should be paid
  const effectiveTotal = isPartialPayment ? partialAmount : total;
  const change = Math.max(0, cashReceived - effectiveTotal);
  const isPaymentSufficient = isPartialPayment
    ? cashReceived >= partialAmount
    : cashReceived >= total;

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-[600px] max-w-[95vw] max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Procesar Pago</DialogTitle>
        </DialogHeader>

        {/* Cash register closed alert */}
        {!isCashOpen && (
          <Alert className="m-4 mb-0" variant="destructive">
            <AlertCircle className="h-4 w-4" />
            <AlertDescription>
              La caja está cerrada. Debe abrir la caja para procesar pagos.
            </AlertDescription>
          </Alert>
        )}

        <PaymentForm
          cashReceived={cashReceived}
          change={change}
          customer={customer}
          customerBusinessName={customerBusinessName}
          customerRUT={customerRUT}
          effectiveTotal={effectiveTotal}
          isPartialPayment={isPartialPayment}
          isPaymentSufficient={isPaymentSufficient}
          items={items}
          partialAmount={partialAmount}
          showCashInput={showCashInput}
          showPaymentFields={showPaymentFields}
          subtotal={subtotal}
          taxAmount={taxAmount}
          total={total}
          onPartialPaymentChange={onPartialPaymentChange}
        />

        <PaymentMethodFields
          cashReceived={cashReceived}
          effectiveTotal={effectiveTotal}
          paymentMethod={paymentMethod}
          onCashReceivedChange={onCashReceivedChange}
          onChange={onPaymentMethodChange}
        />

        <DialogFooter>
          <Button
            disabled={isProcessing}
            variant="outline"
            onClick={handleClose}
          >
            Cancelar
          </Button>
          <Button
            disabled={
              !canProcess ||
              isProcessing ||
              !isCashOpen ||
              (!showAgreementFields && !isPaymentSufficient)
            }
            onClick={handleConfirm}
          >
            {isProcessing ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Procesando...
              </>
            ) : showAgreementFields ? (
              <>Confirmar Venta ({formatCurrency(effectiveTotal)})</>
            ) : (
              <>Confirmar Pago ({formatCurrency(effectiveTotal)})</>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { Banknote, Building2,CreditCard, Smartphone } from "lucide-react";
import { useCallback,useEffect } from "react";

import { Button } from "@/components/ui/button";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";

import type { POSPaymentMethod } from "../types";

interface POSPaymentMethodsProps {
  value: POSPaymentMethod;
  onChange: (method: POSPaymentMethod) => void;
  disabled?: boolean;
  showLabels?: boolean;
  compact?: boolean;
  enableKeyboardShortcuts?: boolean;
}

// Shortcut to payment method mapping
const shortcutToMethod: Record<string, POSPaymentMethod> = {
  F1: "cash",
  F2: "debit_card",
  F3: "credit_card",
  F4: "transfer",
  F5: "agreement",
};

const paymentMethods: {
  id: POSPaymentMethod;
  label: string;
  icon: typeof Banknote;
  shortcut?: string;
  description: string;
}[] = [
  {
    id: "cash",
    label: "Efectivo",
    icon: Banknote,
    shortcut: "F1",
    description: "Pago en efectivo",
  },
  {
    id: "debit_card",
    label: "Débito",
    icon: CreditCard,
    shortcut: "F2",
    description: "Tarjeta de débito",
  },
  {
    id: "credit_card",
    label: "Crédito",
    icon: CreditCard,
    shortcut: "F3",
    description: "Tarjeta de crédito",
  },
  {
    id: "transfer",
    label: "Transferencia",
    icon: Smartphone,
    shortcut: "F4",
    description: "Transferencia bancaria",
  },
  {
    id: "agreement",
    label: "Convenio",
    icon: Building2,
    shortcut: "F5",
    description: "Pago con convenio institucional",
  },
];

export function POSPaymentMethods({
  value,
  onChange,
  disabled = false,
  showLabels = true,
  compact = false,
  enableKeyboardShortcuts = true,
}: POSPaymentMethodsProps) {
  // Handle keyboard shortcuts
  const handleKeyDown = useCallback(
    (event: KeyboardEvent) => {
      if (!enableKeyboardShortcuts || disabled) return;

      const method = shortcutToMethod[event.key];
      if (method) {
        event.preventDefault();
        onChange(method);
      }
    },
    [enableKeyboardShortcuts, disabled, onChange],
  );

  // Set up keyboard listener
  useEffect(() => {
    if (enableKeyboardShortcuts && !disabled) {
      window.addEventListener("keydown", handleKeyDown);
      return () => {
        window.removeEventListener("keydown", handleKeyDown);
      };
    }
  }, [handleKeyDown, enableKeyboardShortcuts, disabled]);

  if (compact) {
    // Compact: single row of buttons
    return (
      <div className="flex gap-2">
        {paymentMethods.map((method) => {
          const Icon = method.icon;
          const isSelected = value === method.id;

          return (
            <TooltipProvider key={method.id}>
              <Tooltip>
                <TooltipTrigger asChild>
                  <Button
                    className={cn(
                      "flex-1 gap-2 transition-all",
                      isSelected && "ring-2 ring-primary ring-offset-2",
                    )}
                    disabled={disabled}
                    size="sm"
                    type="button"
                    variant={isSelected ? "default" : "outline"}
                    onClick={() => onChange(method.id)}
                  >
                    <Icon className="h-4 w-4" />
                    {showLabels && (
                      <span className="hidden sm:inline">{method.label}</span>
                    )}
                  </Button>
                </TooltipTrigger>
                <TooltipContent side="bottom">
                  <p className="font-medium">{method.label}</p>
                  <p className="text-xs text-muted-foreground">
                    {method.description}
                  </p>
                  {method.shortcut && (
                    <p className="text-xs text-muted-foreground mt-1">
                      Atajo: <kbd className="font-mono">{method.shortcut}</kbd>
                    </p>
                  )}
                </TooltipContent>
              </Tooltip>
            </TooltipProvider>
          );
        })}
      </div>
    );
  }

  // Full: grid layout with more details
  return (
    <TooltipProvider>
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        {paymentMethods.map((method) => {
          const Icon = method.icon;
          const isSelected = value === method.id;

          return (
            <Tooltip key={method.id}>
              <TooltipTrigger asChild>
                <button
                  className={cn(
                    "flex flex-col items-center justify-center gap-2 p-4 rounded-xl border-2 transition-all",
                    isSelected
                      ? "border-primary bg-primary/10"
                      : "border-border hover:border-primary/50 hover:bg-muted/50",
                    disabled && "opacity-50 cursor-not-allowed",
                  )}
                  disabled={disabled}
                  type="button"
                  onClick={() => onChange(method.id)}
                >
                  <Icon
                    className={cn(
                      "h-6 w-6",
                      isSelected ? "text-primary" : "text-muted-foreground",
                    )}
                  />
                  <span
                    className={cn(
                      "font-medium text-sm",
                      isSelected ? "text-primary" : "text-foreground",
                    )}
                  >
                    {method.label}
                  </span>
                  {method.shortcut && (
                    <kbd className="text-xs text-muted-foreground font-mono">
                      {method.shortcut}
                    </kbd>
                  )}
                </button>
              </TooltipTrigger>
              <TooltipContent side="bottom">
                <p className="font-medium">{method.label}</p>
                <p className="text-xs text-muted-foreground">
                  {method.description}
                </p>
              </TooltipContent>
            </Tooltip>
          );
        })}
      </div>
    </TooltipProvider>
  );
}

"use client";

import { CheckCircle2, CreditCard, Loader2, Search } from "lucide-react";
import { useEffect } from "react";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { formatCurrency } from "@/lib/utils";

import { POSPendingBalanceTable } from "./_components/POSPendingBalanceTable";

export interface PendingBalanceOrder {
  id: string;
  order_number: string;
  customer_name?: string;
  customer_email?: string;
  customer_rut?: string;
  total_amount: number;
  total_paid: number;
  pending_amount: number;
}

interface POSPendingBalanceDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  orders: PendingBalanceOrder[];
  allOrders: PendingBalanceOrder[];
  loading: boolean;
  selectedOrder: PendingBalanceOrder | null;
  pendingPaymentAmount: string;
  pendingPaymentMethod: string;
  pendingFiscalReference: string;
  processingPayment: boolean;
  searchTerm: string;
  onFetchOrders: () => void;
  onFilterSearch: (term: string) => void;
  onSelectOrder: (order: PendingBalanceOrder | null) => void;
  onPaymentAmountChange: (value: string) => void;
  onPaymentMethodChange: (value: string) => void;
  onFiscalReferenceChange: (value: string) => void;
  onProcessPayment: () => void;
  onRefundClick: (order: PendingBalanceOrder) => void;
}

export function POSPendingBalanceDialog({
  open,
  onOpenChange,
  orders,
  loading,
  selectedOrder,
  pendingPaymentAmount,
  pendingPaymentMethod,
  pendingFiscalReference,
  processingPayment,
  searchTerm,
  onFetchOrders,
  onFilterSearch,
  onSelectOrder,
  onPaymentAmountChange,
  onPaymentMethodChange,
  onFiscalReferenceChange,
  onProcessPayment,
  onRefundClick,
}: POSPendingBalanceDialogProps) {
  useEffect(() => {
    if (open) {
      onFetchOrders();
    }
    // Only fetch when dialog opens; onFetchOrders identity changes every render causing infinite loop
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  return (
    <Dialog
      open={open}
      onOpenChange={(o) => {
        onOpenChange(o);
        if (!o) {
          onSelectOrder(null);
          onPaymentAmountChange("");
          onFiscalReferenceChange("");
        }
      }}
    >
      <DialogContent className="max-w-[calc(100vw-2rem)] sm:max-w-3xl rounded-xl border-admin-border-primary">
        <DialogHeader>
          <DialogTitle className="font-display">
            Cobrar Saldos Pendientes
          </DialogTitle>
          <DialogDescription className="text-admin-text-secondary">
            Se cargan automáticamente todos los saldos pendientes de la
            sucursal. Usa el buscador para filtrar por cliente u orden.
          </DialogDescription>
        </DialogHeader>
        <div className="space-y-4">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-admin-text-tertiary h-5 w-5" />
            <Input
              className="pl-10 rounded-xl"
              placeholder="Filtrar por nombre, RUT, número de orden, email..."
              value={searchTerm}
              onChange={(e) => onFilterSearch(e.target.value)}
            />
          </div>

          {loading ? (
            <div className="flex justify-center py-8">
              <Loader2 className="h-6 w-6 animate-spin text-admin-text-tertiary" />
            </div>
          ) : orders.length > 0 ? (
            <>
              <POSPendingBalanceTable
                orders={orders}
                selectedOrder={selectedOrder}
                onPaymentAmountChange={onPaymentAmountChange}
                onRefundClick={onRefundClick}
                onSelectOrder={onSelectOrder}
              />

              {selectedOrder && (
                <Card className="bg-admin-info/5 border-admin-border-primary rounded-xl">
                  <CardContent className="pt-6 space-y-4">
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <Label className="text-xs text-admin-text-secondary">
                          Orden
                        </Label>
                        <div className="font-semibold text-lg">
                          {selectedOrder.order_number}
                        </div>
                      </div>
                      <div>
                        <Label className="text-xs text-admin-text-secondary">
                          Cliente
                        </Label>
                        <div className="font-semibold text-admin-text-primary">
                          {selectedOrder.customer_name ||
                            selectedOrder.customer_email ||
                            "Sin nombre"}
                        </div>
                        {selectedOrder.customer_rut && (
                          <div className="text-xs text-admin-text-secondary font-mono">
                            RUT: {selectedOrder.customer_rut}
                          </div>
                        )}
                        {selectedOrder.customer_email && (
                          <div className="text-xs text-admin-text-secondary">
                            {selectedOrder.customer_email}
                          </div>
                        )}
                      </div>
                      <div>
                        <Label className="text-xs text-admin-text-secondary">
                          Saldo Pendiente
                        </Label>
                        <div className="font-semibold text-lg text-admin-warning">
                          {formatCurrency(selectedOrder.pending_amount)}
                        </div>
                      </div>
                      <div>
                        <Label className="text-xs text-admin-text-secondary">
                          Método de Pago
                        </Label>
                        <Select
                          value={pendingPaymentMethod}
                          onValueChange={onPaymentMethodChange}
                        >
                          <SelectTrigger className="rounded-xl">
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="cash">Efectivo</SelectItem>
                            <SelectItem value="debit">Débito</SelectItem>
                            <SelectItem value="credit">Crédito</SelectItem>
                            <SelectItem value="transfer">
                              Transferencia
                            </SelectItem>
                          </SelectContent>
                        </Select>
                      </div>
                    </div>
                    <div>
                      <Label className="text-admin-text-primary">
                        Monto a Pagar *
                      </Label>
                      <Input
                        className="rounded-xl"
                        max={selectedOrder.pending_amount}
                        placeholder="0"
                        type="number"
                        value={pendingPaymentAmount}
                        onChange={(e) => onPaymentAmountChange(e.target.value)}
                      />
                      <p className="text-xs text-admin-text-secondary mt-1">
                        Máximo: {formatCurrency(selectedOrder.pending_amount)}
                      </p>
                    </div>
                    {(pendingPaymentMethod === "debit" ||
                      pendingPaymentMethod === "credit" ||
                      pendingPaymentMethod === "transfer") && (
                      <div>
                        <Label className="text-sm text-admin-text-secondary">
                          Número de referencia fiscal (opcional)
                        </Label>
                        <Input
                          className="mt-1 rounded-xl"
                          placeholder="Ej: Nº boleta, factura o transacción"
                          value={pendingFiscalReference}
                          onChange={(e) =>
                            onFiscalReferenceChange(e.target.value)
                          }
                        />
                        <p className="text-xs text-admin-warning mt-1">
                          Se recomienda registrar el número para trazabilidad
                          con documentos fiscales reales
                        </p>
                      </div>
                    )}
                  </CardContent>
                </Card>
              )}
            </>
          ) : (
            <div className="text-center py-8 text-admin-text-tertiary">
              <CreditCard className="h-12 w-12 mx-auto mb-2 text-admin-text-tertiary" />
              <p>
                {searchTerm
                  ? "No se encontraron resultados"
                  : "No hay órdenes con saldo pendiente"}
              </p>
            </div>
          )}
        </div>
        <DialogFooter>
          <Button
            className="rounded-xl"
            variant="outline"
            onClick={() => onOpenChange(false)}
          >
            Cerrar
          </Button>
          {selectedOrder && (
            <Button
              className="rounded-xl"
              disabled={processingPayment || !pendingPaymentAmount}
              onClick={onProcessPayment}
            >
              {processingPayment ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  Procesando...
                </>
              ) : (
                <>
                  <CheckCircle2 className="h-4 w-4 mr-2" />
                  Registrar Pago
                </>
              )}
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { Loader2, Search } from "lucide-react";

import { Input } from "@/components/ui/input";
import { formatCurrency } from "@/lib/utils";

import type { POSProduct } from "../types";

interface POSProductSearchProps {
  searchTerm: string;
  onSearchChange: (value: string) => void;
  products: POSProduct[];
  loading: boolean;
  selectedIndex: number;
  onSelectProduct: (product: POSProduct) => void;
  onKeyDown: (e: React.KeyboardEvent) => void;
  inputRef?: React.RefObject<HTMLInputElement | null>;
  suggestionsRef?: React.RefObject<HTMLDivElement | null>;
  placeholder?: string;
}

export function POSProductSearch({
  searchTerm,
  onSearchChange,
  products,
  loading,
  selectedIndex,
  onSelectProduct,
  onKeyDown,
  inputRef,
  suggestionsRef,
  placeholder = "Buscar productos por nombre, SKU o código...",
}: POSProductSearchProps) {
  return (
    <div className="space-y-2">
      <div className="relative">
        <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 h-4 w-4" />
        <Input
          autoComplete="off"
          className="pl-10"
          placeholder={placeholder}
          ref={inputRef as React.Ref<HTMLInputElement>}
          value={searchTerm}
          onChange={(e) => onSearchChange(e.target.value)}
          onKeyDown={onKeyDown}
        />
      </div>

      {searchTerm.trim().length > 0 && (
        <div className="relative">
          {loading && (
            <div className="absolute inset-0 bg-white/80 dark:bg-gray-900/80 backdrop-blur-sm flex items-center justify-center z-10 rounded-lg border">
              <Loader2 className="h-5 w-5 animate-spin text-gray-400" />
            </div>
          )}

          {!loading && products.length > 0 && (
            <div
              className="max-h-60 overflow-y-auto border rounded-lg bg-white dark:bg-gray-900 shadow-lg z-20"
              ref={suggestionsRef as React.Ref<HTMLDivElement>}
            >
              {products.map((product, index) => (
                <button
                  className={`w-full p-3 text-left border-b last:border-b-0 flex justify-between items-center transition-colors ${
                    selectedIndex === index
                      ? "bg-blue-50 dark:bg-blue-900/30 border-blue-200"
                      : "hover:bg-gray-50 dark:hover:bg-gray-800"
                  }`}
                  key={product.id}
                  type="button"
                  onClick={() => onSelectProduct(product)}
                >
                  <div className="flex-1 min-w-0">
                    <div className="font-medium truncate">{product.name}</div>
                    <div className="text-xs text-gray-500 mt-0.5">
                      {product.sku && <span>SKU: {product.sku}</span>}
                      {product.barcode && (
                        <span className="ml-2">Cód: {product.barcode}</span>
                      )}
                    </div>
                  </div>
                  <div className="text-sm font-semibold ml-2">
                    {formatCurrency(product.price)}
                  </div>
                </button>
              ))}
            </div>
          )}

          {!loading &&
            searchTerm.trim().length > 0 &&
            products.length === 0 && (
              <div className="border rounded-lg bg-white dark:bg-gray-900 p-3 text-center text-gray-500 text-sm">
                No se encontraron productos
              </div>
            )}
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";

import { Card, CardContent } from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { formatCurrency } from "@/lib/utils";

import type { POSCartItem, POSCustomer, POSProduct } from "../types";
import { POSCart } from "./POSCart";

// Inline simple search input component to avoid prop mismatch
function SimpleProductSearch({
  onProductSelect,
}: {
  onProductSelect: (product: POSProduct) => void;
}) {
  const [searchTerm, setSearchTerm] = useState("");

  return (
    <div className="space-y-2">
      <input
        className="w-full px-3 py-2 border rounded-md"
        placeholder="Buscar productos..."
        type="text"
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
      />
      <p className="text-sm text-muted-foreground">
        Use la búsqueda de productos en el panel principal
      </p>
    </div>
  );
}

// Inline simple customer search
function SimpleCustomerSearch({
  selectedCustomer,
  onCustomerSelect,
}: {
  selectedCustomer: POSCustomer | null;
  onCustomerSelect: (customer: POSCustomer | null) => void;
}) {
  return (
    <div className="space-y-2">
      {selectedCustomer ? (
        <div className="p-3 border rounded-md">
          <p className="font-medium">{selectedCustomer.name}</p>
          <button
            className="text-sm text-red-600"
            onClick={() => onCustomerSelect(null)}
          >
            Quitar
          </button>
        </div>
      ) : (
        <p className="text-sm text-muted-foreground">
          Use la búsqueda de clientes en el panel principal
        </p>
      )}
    </div>
  );
}

interface POSQuickSaleProps {
  // Cart
  cart: POSCartItem[];
  onAddToCart: (product: POSProduct) => void;
  onUpdateQuantity: (productId: string, quantity: number) => void;
  onRemoveFromCart: (productId: string) => void;
  onClearCart: () => void;

  // Customer
  customer: POSCustomer | null;
  onCustomerSelect: (customer: POSCustomer | null) => void;
  branchId?: string | null;

  // Totals
  subtotal: number;
  taxAmount: number;
  total: number;

  // Actions
  onCheckout?: () => void;
  canCheckout?: boolean;

  // Loading states
  isProcessing?: boolean;
}

export function POSQuickSale({
  cart,
  onAddToCart,
  onUpdateQuantity,
  onRemoveFromCart,
  onClearCart,
  customer,
  onCustomerSelect,
  branchId,
  subtotal,
  taxAmount,
  total,
  onCheckout,
