"use client";

import { Button } from "@/components/ui/button";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { formatCurrency } from "@/lib/utils";

import type { PendingBalanceOrder } from "../POSPendingBalanceDialog";

interface POSPendingBalanceTableProps {
  orders: PendingBalanceOrder[];
  selectedOrder: PendingBalanceOrder | null;
  onSelectOrder: (order: PendingBalanceOrder | null) => void;
  onPaymentAmountChange: (value: string) => void;
  onRefundClick: (order: PendingBalanceOrder) => void;
}

/**
 * POSPendingBalanceTable — orders table for the pending balance dialog.
 *
 * Extracted from POSPendingBalanceDialog.tsx.
 */
export function POSPendingBalanceTable({
  orders,
  selectedOrder,
  onSelectOrder,
  onPaymentAmountChange,
  onRefundClick,
}: POSPendingBalanceTableProps) {
  return (
    <div className="border border-admin-border-primary rounded-xl overflow-hidden">
      <Table>
        <TableHeader>
          <TableRow>
            <TableHead>Orden</TableHead>
            <TableHead>Cliente</TableHead>
            <TableHead className="text-right">Total</TableHead>
            <TableHead className="text-right">Pagado</TableHead>
            <TableHead className="text-right">Pendiente</TableHead>
            <TableHead>Acción</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {orders.map((order) => (
            <TableRow
              className={
                selectedOrder?.id === order.id
                  ? "bg-admin-accent/10"
                  : "cursor-pointer hover:bg-muted"
              }
              key={order.id}
              onClick={() => {
                onSelectOrder(order);
                onPaymentAmountChange(order.pending_amount.toString());
              }}
            >
              <TableCell className="font-mono font-semibold">
                {order.order_number}
              </TableCell>
              <TableCell>
                <div className="font-medium">
                  {order.customer_name ||
                    order.customer_email ||
                    "Sin nombre"}
                </div>
                {order.customer_rut && (
                  <div className="text-xs text-admin-text-secondary font-mono">
                    RUT: {order.customer_rut}
                  </div>
                )}
                {order.customer_email && (
                  <div className="text-xs text-admin-text-tertiary">
                    {order.customer_email}
                  </div>
                )}
              </TableCell>
              <TableCell className="text-right">
                {formatCurrency(order.total_amount)}
              </TableCell>
              <TableCell className="text-right text-admin-success">
                {formatCurrency(order.total_paid)}
              </TableCell>
              <TableCell className="text-right font-semibold text-admin-warning">
                {formatCurrency(order.pending_amount)}
              </TableCell>
              <TableCell>
                <div className="flex items-center gap-2">
                  <Button
                    className="rounded-xl"
                    size="sm"
                    variant={
                      selectedOrder?.id === order.id
                        ? "default"
                        : "outline"
                    }
                    onClick={(e) => {
                      e.stopPropagation();
                      onSelectOrder(order);
                      onPaymentAmountChange(
                        order.pending_amount.toString(),
                      );
                    }}
                  >
                    {selectedOrder?.id === order.id
                      ? "Seleccionado"
                      : "Seleccionar"}
                  </Button>
                  <Button
                    className="rounded-xl"
                    size="sm"
                    variant="outline"
                    onClick={(e) => {
                      e.stopPropagation();
                      onRefundClick(order);
                    }}
                  >
                    Devolución
                  </Button>
                </div>
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  );
}

"use client";

import { Badge } from "@/components/ui/badge";
import type { Prescription } from "@/lib/api/services/customerService";

interface POSPrescriptionDetailProps {
  prescription: Prescription;
}

/**
 * POSPrescriptionDetail — displays a selected prescription values.
 *
 * Extracted from POSAdvancedSaleCustomerTab.tsx.
 */
export function POSPrescriptionDetail({
  prescription,
}: POSPrescriptionDetailProps) {
  return (
    <div className="mt-3 p-3 border rounded-lg bg-muted/30">
      <div className="flex justify-between items-center mb-2">
        <h5 className="font-medium text-sm">Valores de Receta</h5>
        {prescription.is_current && (
          <Badge className="text-xs" variant="outline">
            Receta Vigente
          </Badge>
        )}
      </div>
      <div className="grid grid-cols-2 gap-3 text-sm">
        <div>
          <span className="font-medium">OD (Ojo Derecho):</span>
          <div className="text-muted-foreground">
            {prescription?.od_sphere != null
              ? `Esf: ${prescription!.od_sphere! >= 0 ? "+" : ""}${prescription!.od_sphere}`
              : "Sin dato"}
            {(prescription?.od_cylinder ?? 0) !== 0 &&
              ` Cil: ${prescription!.od_cylinder! >= 0 ? "+" : ""}${prescription!.od_cylinder}`}
            {(prescription?.od_axis ?? 0) !== 0 &&
              ` x ${prescription!.od_axis}°`}
            {(prescription?.od_add ?? 0) > 0 &&
              ` Ad: +${prescription!.od_add}`}
          </div>
        </div>
        <div>
          <span className="font-medium">OI (Ojo Izquierdo):</span>
          <div className="text-muted-foreground">
            {prescription?.os_sphere != null
              ? `Esf: ${prescription!.os_sphere! >= 0 ? "+" : ""}${prescription!.os_sphere}`
              : "Sin dato"}
            {(prescription?.os_cylinder ?? 0) !== 0 &&
              ` Cil: ${prescription!.os_cylinder! >= 0 ? "+" : ""}${prescription!.os_cylinder}`}
            {(prescription?.os_axis ?? 0) !== 0 &&
              ` x ${prescription!.os_axis}°`}
            {(prescription?.os_add ?? 0) > 0 &&
              ` Ad: +${prescription!.os_add}`}
          </div>
        </div>
      </div>
      {(prescription?.pd_distance ||
        prescription?.od_pd ||
        prescription?.os_pd) && (
        <div className="mt-2 text-xs text-muted-foreground">
          <div className="font-medium text-foreground">
            Distancia Pupilar (DP):
          </div>
          <div className="flex gap-4 mt-1">
            {(prescription?.od_pd || prescription?.pd_distance) && (
              <div>
                <span className="text-muted-foreground">Lejos:</span>{" "}
                <span className="font-medium">
                  {prescription?.pd_distance
                    ? `${prescription.pd_distance}mm`
                    : prescription?.od_pd && prescription?.os_pd
                      ? `${Number(prescription.od_pd) + Number(prescription.os_pd)}mm`
                      : prescription?.od_pd
                        ? `${prescription.od_pd}mm`
                        : ""}
                </span>
              </div>
            )}
            {prescription?.pd_near && (
              <div>
                <span className="text-muted-foreground">Cerca:</span>{" "}
                <span className="font-medium">{prescription?.pd_near}mm</span>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { Separator } from "@/components/ui/separator";
import { formatCurrency } from "@/lib/utils";

interface OrderFormData {
  presbyopia_solution: string;
  customer_own_frame: boolean;
  frame_name: string | null;
  near_frame_name: string | null;
  near_frame_sku: string | null;
  near_lens_family_id: string | null;
  near_lens_family_name: string | null;
  lens_family_id: string | null;
  lens_family_name: string | null;
  treatment_ids: string[];
  labor_cost: number;
}

interface FrameProduct {
  id: string;
  name: string;
  price: number;
}

interface Treatment {
  id: string;
  label: string;
  cost: number;
}

interface LensFamily {
  readonly id: string;
  readonly name: string;
  readonly lens_type: string;
}

interface POSPriceSummarySectionProps {
  orderFormData: OrderFormData;
  selectedFrame: FrameProduct | null;
  customerOwnNearFrame: boolean;
  selectedNearFrame: FrameProduct | null;
  lensFamilies: readonly LensFamily[];
  treatments: Treatment[];
  lensPrice: () => number;
  treatmentsPrice: number;
}

/**
 * POSPriceSummarySection — order summary with frame, lens, treatment rows.
 *
 * Extracted from POSAdvancedSalePricingTab.tsx.
 */
export function POSPriceSummarySection({
  orderFormData,
  selectedFrame,
  customerOwnNearFrame,
  selectedNearFrame,
  lensFamilies,
  treatments,
  lensPrice,
  treatmentsPrice,
}: POSPriceSummarySectionProps) {
  return (
    <>
      {orderFormData.presbyopia_solution === "two_separate" ? (
        <>
          {/* Distance Vision Section */}
          <div className="p-3 border rounded-lg bg-muted/30">
            <div className="font-medium mb-2">Visión Lejos</div>
            <div className="flex justify-between text-sm">
              <span className="text-muted-foreground">Marco:</span>
              <span>
                {orderFormData.customer_own_frame
                  ? orderFormData.frame_name || "Marco del cliente"
                  : selectedFrame?.name || "No seleccionado"}
              </span>
            </div>
            {selectedFrame && !orderFormData.customer_own_frame && (
              <div className="flex justify-between text-sm ml-4">
                <span className="text-muted-foreground">Precio:</span>
                <span>{formatCurrency(selectedFrame.price || 0)}</span>
              </div>
            )}
            <div className="flex justify-between text-sm mt-2">
              <span className="text-muted-foreground">Lente:</span>
              <span>
                {orderFormData.lens_family_id
                  ? orderFormData.lens_family_name || "Seleccionado"
                  : "No seleccionado"}
              </span>
            </div>
            <div className="flex justify-between text-sm ml-4">
              <span className="text-muted-foreground">Precio:</span>
              <span>{formatCurrency(80000)}</span>
            </div>
          </div>

          {/* Near Vision Section */}
          <div className="p-3 border rounded-lg bg-muted/30">
            <div className="font-medium mb-2">Visión Cerca</div>
            <div className="flex justify-between text-sm">
              <span className="text-muted-foreground">Marco:</span>
              <span>
                {customerOwnNearFrame
                  ? orderFormData.near_frame_name || "Marco del cliente"
                  : selectedNearFrame?.name || "No seleccionado"}
              </span>
            </div>
            {selectedNearFrame && !customerOwnNearFrame && (
              <div className="flex justify-between text-sm ml-4">
                <span className="text-muted-foreground">Precio:</span>
                <span>{formatCurrency(selectedNearFrame.price || 0)}</span>
              </div>
            )}
            <div className="flex justify-between text-sm mt-2">
              <span className="text-muted-foreground">Lente:</span>
              <span>
                {orderFormData.near_lens_family_id
                  ? orderFormData.near_lens_family_name || "Seleccionado"
                  : "No seleccionado"}
              </span>
            </div>
            <div className="flex justify-between text-sm ml-4">
              <span className="text-muted-foreground">Precio:</span>
              <span>{formatCurrency(35000)}</span>
            </div>
          </div>
        </>
      ) : (
        <>
          {/* Frame - Single/Progressive */}
          <div className="flex justify-between text-sm">
            <span className="text-muted-foreground">Marco:</span>
            <span>
              {orderFormData.customer_own_frame
                ? orderFormData.frame_name || "Marco del cliente"
                : selectedFrame?.name || "No seleccionado"}
            </span>
          </div>

          {selectedFrame && !orderFormData.customer_own_frame && (
            <div className="flex justify-between text-sm">
              <span className="text-muted-foreground ml-4">
                Precio Marco:
              </span>
              <span>{formatCurrency(selectedFrame.price || 0)}</span>
            </div>
          )}

          {/* Lens */}
          <div className="flex justify-between text-sm">
            <span className="text-muted-foreground">Lentes:</span>
            <span>
              {orderFormData.lens_family_id
                ? [...lensFamilies].find(
                    (f) => f.id === orderFormData.lens_family_id,
                  )?.name || "Seleccionado"
                : "No seleccionado"}
            </span>
          </div>

          {orderFormData.lens_family_id && (
            <div className="flex justify-between text-sm ml-4">
              <span className="text-muted-foreground">Precio Lentes:</span>
              <span>{formatCurrency(lensPrice())}</span>
            </div>
          )}
        </>
      )}

      {/* Treatments */}
      {orderFormData.treatment_ids.length > 0 && (
        <div className="ml-4 space-y-1">
          <div className="text-xs text-muted-foreground">Tratamientos:</div>
          {orderFormData.treatment_ids.map((id) => {
            const treatment = treatments.find((t) => t.id === id);
            return treatment ? (
              <div className="flex justify-between text-sm" key={id}>
                <span className="ml-2">- {treatment.label}</span>
                <span>{formatCurrency(treatment.cost)}</span>
              </div>
            ) : null;
          })}
        </div>
      )}

      {/* Labor */}
      {orderFormData.labor_cost > 0 && (
        <div className="flex justify-between text-sm">
          <span className="text-muted-foreground ml-4">Mano de Obra:</span>
          <span>{formatCurrency(orderFormData.labor_cost)}</span>
        </div>
      )}

      <Separator />
    </>
  );
}

"use client";

import { Input } from "@/components/ui/input";
import { formatRUTAsYouType } from "@/lib/utils/rut";

interface POSQuickCustomerFieldsProps {
  customerBusinessName: string;
  onBusinessNameChange: (value: string) => void;
  customerRUT: string;
  onRUTChange: (value: string) => void;
  customerEmail?: string;
  onCustomerEmailChange?: (value: string) => void;
  customerPhone?: string;
  onCustomerPhoneChange?: (value: string) => void;
