  discountAmount: () => number;
}

export async function handleCreateQuoteAction(
  params: CreateQuoteParams,
  onStateChange: {
    setCreatingQuote: (v: boolean) => void;
    onCustomerChange: (c: unknown) => void;
  },
): Promise<void> {
  const {
    customer,
    quickCustomerName,
    quickCustomerRUT,
    quickCustomerEmail,
    quickCustomerPhone,
    branchId,
    selectedPrescription,
    selectedFrame,
    selectedNearFrame,
    orderFormData,
    customerOwnNearFrame,
    lensPrice,
    treatmentsPrice,
    totalPrice,
    discountAmount,
  } = params;
  const { setCreatingQuote, onCustomerChange } = onStateChange;

  const isQuickCustomer = !customer && (quickCustomerName || quickCustomerRUT);

  if (!customer && !isQuickCustomer) {
    toast.error("Selecciona un cliente primero");
    return;
  }

  setCreatingQuote(true);
  try {
    let customerId = customer?.id;

    if (!branchId) {
      toast.error("Selecciona una sucursal primero");
      setCreatingQuote(false);
      return;
    }

    if (isQuickCustomer) {
      const trimmedName = (quickCustomerName || "").trim();
      if (!trimmedName) {
        toast.error("El nombre del cliente es requerido");
        setCreatingQuote(false);
        return;
      }

      try {
        const nameParts = trimmedName.split(" ");
        const firstName = nameParts[0];
        const lastName =
          nameParts.length > 1 ? nameParts.slice(1).join(" ") : null;

        const newCustomer = await createCustomer({
          first_name: firstName,
          last_name: lastName || undefined,
          email: quickCustomerEmail?.trim() || undefined,
          phone: quickCustomerPhone?.trim() || undefined,
          rut: quickCustomerRUT?.trim() || undefined,
          branch_id: branchId ?? undefined,
        });

        customerId = newCustomer.id;
        toast.success("Cliente creado exitosamente");
      } catch {
        toast.error("Error al crear el cliente");
        setCreatingQuote(false);
        return;
      }
    }

    if (!branchId) {
      toast.error("Selecciona una sucursal primero");
      setCreatingQuote(false);
      return;
    }

    const quoteData = {
      customer_id: customerId!,
      status: "draft" as const,
      subtotal: totalPrice(),
      tax_amount: 0,
      discount_amount: discountAmount(),
      total_amount: totalPrice() - discountAmount(),
      currency: "CLP",
      notes: orderFormData.notes || undefined,
      branch_id: branchId,
      prescription_id: selectedPrescription?.id || null,
      frame_product_id: selectedFrame?.id || null,
      customer_own_frame: orderFormData.customer_own_frame,
      frame_name: orderFormData.frame_name || selectedFrame?.name || null,
      frame_brand: selectedFrame?.brand || null,
      frame_model: selectedFrame?.name || null,
      frame_sku: orderFormData.frame_sku || selectedFrame?.sku || null,
      frame_price: selectedFrame?.price || 0,
      lens_family_id: orderFormData.lens_family_id,
      lens_family_name: orderFormData.lens_family_name,
      lens_type: orderFormData.lens_type,
      lens_treatments: orderFormData.treatment_ids,
      treatments_cost: treatmentsPrice,
      labor_cost: orderFormData.labor_cost,
      presbyopia_solution:
        orderFormData.presbyopia_solution === "single"
          ? ("bifocal" as const)
          : orderFormData.presbyopia_solution === "two_separate"
            ? ("two_separate" as const)
            : ("progressive" as const),
      far_lens_family_id: orderFormData.lens_family_id,
      near_lens_family_id: orderFormData.near_lens_family_id,
      far_lens_cost:
        orderFormData.presbyopia_solution === "two_separate"
          ? 45000
          : lensPrice(),
      near_lens_cost:
        orderFormData.presbyopia_solution === "two_separate"
          ? 35000
          : (undefined as number | undefined),
      near_frame_product_id: selectedNearFrame?.id || null,
      near_frame_name:
        orderFormData.near_frame_name || selectedNearFrame?.name || null,
      near_frame_brand: selectedNearFrame?.brand || null,
      near_frame_model: selectedNearFrame?.name || null,
      near_frame_sku:
        orderFormData.near_frame_sku || selectedNearFrame?.sku || null,
      near_frame_price: selectedNearFrame?.price || 0,
      customer_own_near_frame: customerOwnNearFrame,
    };

    const quote = await createQuote(quoteData);
    toast.success(
      isQuickCustomer
        ? "Cliente y presupuesto creados exitosamente"
        : "Presupuesto creado exitosamente",
    );
    window.open(`/admin/quotes/${quote.id}/print`, "_blank");
  } catch (error) {
    if (error instanceof Response) {
      error
        .json()
        .then((err) => {
          toast.error(err.error || "Error al crear el presupuesto");
        })
        .catch(() => {
          toast.error("Error al crear el presupuesto");
        });
    } else if (error instanceof Error) {
      toast.error(error.message || "Error al crear el presupuesto");
    } else {
      toast.error("Error al crear el presupuesto");
    }
  } finally {
    setCreatingQuote(false);
  }
}

/**
 * posDataLoader — Data loading hooks for the Optical Sale form.
 *
 * Contains hook-based data loading functions that interact with
 * Supabase services. Co-located here to reduce megafile size.
 */


import type { Prescription } from "@/lib/api/services/customerService";
import type { QuoteSettings } from "@/lib/api/services/quoteSettingsService";

import type { Treatment } from "./POSAdvancedSale.types";
import { type CreateQuoteParams,handleCreateQuoteAction } from "./posCreateQuote";

export type { CreateQuoteParams };
export { handleCreateQuoteAction };

export interface DataLoaderParams {
  customer: { id: string } | null;
  branchId: string | null;
  quoteSettingsService: { get: () => Promise<QuoteSettings | null> };
  getPrescriptions: (id: string) => Promise<Prescription[]>;
  searchProducts: (
    search: string,
    branchId: string,
    productType?: string,
  ) => Promise<unknown[]>;
  onSettingsLoaded: (settings: QuoteSettings) => void;
  onUpdateTreatments: (updater: (prev: Treatment[]) => Treatment[]) => void;
  onSetLaborCost: (cost: number) => void;
  onPrescriptionsLoaded: (prescriptions: Prescription[]) => void;
  onCurrentPrescriptionFound: (prescription: Prescription) => void;
  onSetLoadingPrescriptions: (loading: boolean) => void;
}

export async function loadSettingsAction(
  quoteSettingsService: { get: () => Promise<QuoteSettings | null> },
  onSettingsLoaded: (settings: QuoteSettings) => void,
  onUpdateTreatments: (updater: (prev: Treatment[]) => Treatment[]) => void,
  onSetLaborCost: (cost: number) => void,
): Promise<void> {
  const settings = await quoteSettingsService.get();
  if (!settings) return;

  onSettingsLoaded(settings);

  if (settings.treatment_prices) {
    const tp = settings.treatment_prices;
    onUpdateTreatments((prev) => {
      const updated = prev.map((t) => {
        const tpValue = tp[t.value as keyof typeof tp];
        const price =
          typeof tpValue === "number"
            ? tpValue
            : (tpValue as { price?: number })?.price;
        return price !== undefined && price > 0 ? { ...t, cost: price } : t;
      });

      if (tp.custom_service?.enabled) {
        updated.push({
          id: "t-custom",
          label: tp.custom_service.name || "Servicio Extra",
          value: "custom_service",
          cost: tp.custom_service.price || 0,
          category: "coating",
          editable: true,
        });
      }
      return updated;
    });
  }

  if (settings?.default_labor_cost && settings.default_labor_cost > 0) {
    onSetLaborCost(settings.default_labor_cost);
  }
}

export async function loadPrescriptionsAction(
  customerId: string | undefined,
  getPrescriptionsFn: (id: string) => Promise<Prescription[]>,
  onPrescriptionsLoaded: (prescriptions: Prescription[]) => void,
  onCurrentPrescriptionFound: (prescription: Prescription) => void,
  onSetLoadingPrescriptions: (loading: boolean) => void,
): Promise<void> {
  if (!customerId) {
    onPrescriptionsLoaded([]);
    return;
  }

  onSetLoadingPrescriptions(true);
  try {
    const data = await getPrescriptionsFn(customerId);
    onPrescriptionsLoaded(data || []);
    const current = data?.find((p) => p.is_current);
    if (current) {
      onCurrentPrescriptionFound(current);
    }
  } catch {
    onPrescriptionsLoaded([]);
  } finally {
    onSetLoadingPrescriptions(false);
  }
}

export function createSearchFramesAction(
  branchId: string | null,
  setResults: (results: unknown[]) => void,
  setLoading: (loading: boolean) => void,
  searchProductsFn: (
    search: string,
    branchId: string,
    productType?: string,
  ) => Promise<unknown[]>,
) {
  return async (search: string) => {
    if (!branchId || search.length < 2) {
      setResults([]);
      return;
    }

    setLoading(true);
    try {
      const products = await searchProductsFn(search, branchId, "frame");
      const frames = products.filter(
        (p: unknown) =>
          p.product_type === "frame" ||
          p.name?.toLowerCase().includes("marco") ||
          p.name?.toLowerCase().includes("armazón") ||
          p.name?.toLowerCase().includes("anteojo"),
      );
      setResults(frames);
    } catch {
      setResults([]);
    } finally {
      setLoading(false);
    }
  };
}

/**
 * posPricingUtils — Pure pricing logic for the Optical Sale form.
 *
 * These are stateless functions that take state in and return values out.
 * They do NOT use React hooks — the component wraps them in useMemo/useCallback.
 */

import type { POSProduct, Treatment } from "./POSAdvancedSale.types";
interface PrescriptionView {
  od_sphere?: number | null;
  os_sphere?: number | null;
  od_add?: number | null;
  os_add?: number | null;
}

export interface LensFamily {
  id: string;
  name: string;
  lens_type: "vision" | "contact";
  is_stock_available?: boolean;
}

/**
 * Suggest lens family and presbyopia solution based on prescription.
 * Returns suggested values or null if no change needed.
 */
export function suggestLensFamily(
  prescription: PrescriptionView | null,
  lensFamilies: readonly LensFamily[],
  currentLensType: "vision" | "contact",
): {
  lens_family_id: string;
  lens_family_name: string;
  near_lens_family_id: string | null;
  near_lens_family_name: string | null;
  presbyopia_solution: "single" | "two_separate" | "progressive";
} | null {
  if (!prescription) return null;

  const { od_sphere, os_sphere, od_add, os_add } = prescription;

  const hasAddition = (od_add && od_add > 0) || (os_add && os_add > 0);
  const maxSphere = Math.max(
    Math.abs(od_sphere || 0),
    Math.abs(os_sphere || 0),
  );
  const addValue = od_add || os_add || 0;
  const nearSphere = (od_sphere || 0) + addValue;
  const maxNearSphere = Math.max(
    Math.abs(nearSphere),
    Math.abs((os_sphere || 0) + addValue),
  );

  let suggestedFamily = "";
  let suggestedNearFamily = "";
  const suggestedSolution: "single" | "two_separate" | "progressive" = "single";

  if (hasAddition) {
    if (maxSphere > 4) {
      suggestedFamily = "lf-7";
    } else if (maxSphere > 2) {
      suggestedFamily = "lf-6";
    } else {
      suggestedFamily = "lf-5";
    }

    if (maxNearSphere > 4) {
      suggestedNearFamily = "lf-3";
    } else if (maxNearSphere > 3) {
      suggestedNearFamily = "lf-2";
    } else {
      suggestedNearFamily = "lf-1";
    }
  } else {
    if (maxSphere > 6) {
      suggestedFamily = "lf-3";
    } else if (maxSphere > 3) {
      suggestedFamily = "lf-2";
    } else {
      suggestedFamily = "lf-1";
    }
  }

  const family = lensFamilies.find((f) => f.id === suggestedFamily);
  const nearFamily = lensFamilies.find((f) => f.id === suggestedNearFamily);

  if (family && currentLensType === family.lens_type) {
    const newSolution = hasAddition ? "progressive" : "single";
    return {
      lens_family_id: suggestedFamily,
      lens_family_name: family.name,
      near_lens_family_id: hasAddition ? suggestedNearFamily : null,
      near_lens_family_name: hasAddition && nearFamily ? nearFamily.name : null,
      presbyopia_solution: newSolution,
    };
  }

  return {
    lens_family_id: suggestedFamily,
    lens_family_name: family?.name || "",
    near_lens_family_id: null,
    near_lens_family_name: null,
    presbyopia_solution: "single",
  };
}

/**
 * Compute total treatments price from selected IDs.
 */
export function computeTreatmentsPrice(
  treatmentIds: string[],
  treatments: Treatment[],
): number {
  return treatmentIds.reduce((total, id) => {
    const treatment = treatments.find((t) => t.id === id);
    return total + (treatment?.cost || 0);
  }, 0);
}

/**
 * Compute lens price based on family and solution type.
 */
export function computeLensPrice(
  lensFamilyId: string | null,
  presbyopiaSolution: string,
  lensFamilies: readonly LensFamily[],
): number {
  if (!lensFamilyId) return 0;
  const family = lensFamilies.find((f) => f.id === lensFamilyId);
  if (!family) return 0;
  if (family.lens_type === "contact") return 25000;

  switch (presbyopiaSolution) {
    case "progressive":
      return 120000;
    case "two_separate":
      return 80000;
    default:
      return 45000;
  }
}

/**
 * Compute near lens price for two_separate solution.
 */
export function computeNearLensPrice(
  nearLensFamilyId: string | null,
  lensFamilies: readonly LensFamily[],
): number {
  if (!nearLensFamilyId) return 0;
  const family = lensFamilies.find((f) => f.id === nearLensFamilyId);
  if (!family) return 0;
  return 35000;
}

/**
 * Compute total price including frame, lenses, treatments, labor, and discount.
 */
export function computeTotalPrice(
  selectedFrame: POSProduct | null,
  customerOwnFrame: boolean,
  lensPrice: number,
  treatmentsPrice: number,
  laborCost: number,
  discountType: "none" | "percentage" | "fixed",
  discountValue: number,
): number {
  let total = 0;

  if (selectedFrame && !customerOwnFrame) {
    total += selectedFrame.price || 0;
  }
  total += lensPrice;
  total += treatmentsPrice;
  total += laborCost;

  if (discountType === "percentage" && discountValue > 0) {
    total = total * (1 - discountValue / 100);
  } else if (discountType === "fixed" && discountValue > 0) {
    total = Math.max(0, total - discountValue);
  }

  return total;
}

/**
 * Calculate discount amount for display.
 */
export function computeDiscountAmount(
  selectedFrame: POSProduct | null,
  customerOwnFrame: boolean,
  lensPrice: number,
  treatmentsPrice: number,
  laborCost: number,
  discountType: "none" | "percentage" | "fixed",
  discountValue: number,
): number {
  let subtotal = 0;

  if (selectedFrame && !customerOwnFrame) {
    subtotal += selectedFrame.price || 0;
  }
  subtotal += lensPrice;
  subtotal += treatmentsPrice;
  subtotal += laborCost;

  if (discountType === "percentage" && discountValue > 0) {
    return subtotal * (discountValue / 100);
  } else if (discountType === "fixed" && discountValue > 0) {
    return discountValue;
  }
  return 0;
}

/**
 * Update a treatment's price in the treatments array.
 */
export function updateTreatmentPrice(
  treatments: Treatment[],
  treatmentId: string,
  newPrice: number,
): Treatment[] {
  return treatments.map((t) =>
    t.id === treatmentId ? { ...t, cost: newPrice } : t,
  );
}

/**
 * Filter treatments based on lens type.
 */
export function filterTreatmentsByLensType(
  treatments: Treatment[],
  lensType: "vision" | "contact",
): Treatment[] {
  if (lensType === "contact") {
    return treatments.filter(
      (t) =>
        t.category === "coating" &&
        !["photochromic", "polarized", "tint"].includes(t.value),
    );
  }
  return treatments;
}

/**
 * useContactLensSelector — state management hook for ContactLensSelector.
 *
 * Extracted from ContactLensSelector.tsx to reduce file size.
 */
import { useEffect, useMemo, useState } from "react";
import { toast } from "sonner";

import { contactLensEncargoService } from "@/lib/api/services/contactLensEncargoService";
import {
  type ContactLensFamily,
  contactLensFamilyService,
} from "@/lib/api/services/contactLensFamilyService";
import { contactLensInventoryService } from "@/lib/api/services/contactLensInventoryService";
import {  type ContactLensMatrixCalculationResult,
  contactLensMatrixService,
} from "@/lib/api/services/contactLensMatrixService";
import { appLogger } from '@/lib/logger';

export interface ContactLensPrescription {
  sphere_od: number;
  cylinder_od: number;
  axis_od: number | null;
  add_od: number | null;
  base_curve_od: number | null;
  diameter_od: number | null;
  sphere_os: number;
  cylinder_os: number;
  axis_os: number | null;
  add_os: number | null;
  base_curve_os: number | null;
  diameter_os: number | null;
}

export interface ContactLensOrderConfig {
  family_id: string;
  family_name: string;
  family_brand: string;
  modality: string;
  use_type: string;
  packaging: string;
  prescription: ContactLensPrescription;
  price: number;
  cost: number;
  inStock: boolean;
  availableQuantity: number;
  quantity: number;
  notes?: string;
}

export function useContactLensSelector(
  prescription: ContactLensPrescription | null | undefined,
  branchId: string | null,
  onSelect: (config: ContactLensOrderConfig | null) => void,
  customer?: {
    id: string;
    name?: string | null;
    first_name?: string | null;
    last_name?: string | null;
    rut?: string | null;
    phone?: string | null;
    email?: string | null;
  } | null,
) {
  const [families, setFamilies] = useState<ContactLensFamily[]>([]);

  const [loadingFamilies, setLoadingFamilies] = useState(true);
  const [selectedFamilyId, setSelectedFamilyId] = useState<string>("");
  const [manualPrescription, setManualPrescription] =
    useState<ContactLensPrescription>({
      sphere_od: 0,
      cylinder_od: 0,
      axis_od: null,
      add_od: null,
      base_curve_od: null,
      diameter_od: null,
      sphere_os: 0,
      cylinder_os: 0,
      axis_os: null,
      add_os: null,
      base_curve_os: null,
      diameter_os: null,
    });
  const [quantity, setQuantity] = useState(1);
  const [stockInfo, setStockInfo] = useState<{
    inStock: boolean;
    availableQuantity: number;
    odMessage?: string;
    osMessage?: string;
  }>({
    inStock: true,
    availableQuantity: 20,
  });
  const [loadingPrice, setLoadingPrice] = useState(false);
  const [priceResult, setPriceResult] =
    useState<ContactLensMatrixCalculationResult | null>(null);
  const [showEncargoDialog, setShowEncargoDialog] = useState(false);
  const [submittingEncargo, setSubmittingEncargo] = useState(false);

  // Load families on mount
  useEffect(() => {
    contactLensFamilyService
      .getAll()
      .then((data) => setFamilies(data || []))
      .catch((err) => {
        appLogger.error("Error loading families:", err);
        toast.error("Error al cargar familias");
      })
      .finally(() => setLoadingFamilies(false));
  }, []);

  // Active prescription
  const activePrescription = useMemo(() => {
    return prescription || manualPrescription;
  }, [prescription, manualPrescription]);

  // Selected family
  const selectedFamily = useMemo(() => {
    return families.find((f) => f.id === selectedFamilyId) || null;
  }, [families, selectedFamilyId]);

  // Handler
  const handleFamilySelect = (familyId: string) => {
    setSelectedFamilyId(familyId);
    setPriceResult(null);
  };

  // Load price when family changes
  useEffect(() => {
    if (!selectedFamily) return;

    const loadPrice = async () => {
      setLoadingPrice(true);
      try {
        const result = await contactLensMatrixService.calculate(
          selectedFamily.id,
          activePrescription.sphere_od,
          activePrescription.cylinder_od,
          activePrescription.axis_od,
          activePrescription.add_od,
        );

        if (result) {
          setPriceResult(result);
        } else {
          setPriceResult({
            price: 45000,
            cost: 22000,
            family_id: selectedFamily.id,
            family_name: selectedFamily.name,
            brand: selectedFamily.brand || "",
            sphere: activePrescription.sphere_od,
            cylinder: activePrescription.cylinder_od,
            axis: activePrescription.axis_od,
            addition: activePrescription.add_od,
          });
        }
      } catch (err) {
        appLogger.error("Error calculating price:", err);
        toast.error("Error al calcular precio");
      } finally {
        setLoadingPrice(false);
      }
    };

    loadPrice();
    // ponytail: depends on selectedFamilyId + selectedFamily?.id (subtle bug preserved)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedFamilyId, selectedFamily?.id]);

  // Check stock when family or prescription changes
  useEffect(() => {
    if (!selectedFamily || !branchId) return;

    const checkStock = async () => {
      const odStock = await contactLensInventoryService.checkStock(
        selectedFamily.id,
        branchId,
        activePrescription.sphere_od,
        activePrescription.cylinder_od,
      );

      const osStock = await contactLensInventoryService.checkStock(
        selectedFamily.id,
        branchId,
        activePrescription.sphere_os,
        activePrescription.cylinder_os,
      );

      const inStock = odStock.available && osStock.available;
      const availableQuantity = Math.min(odStock.quantity, osStock.quantity);

      setStockInfo({
        inStock,
        availableQuantity,
        odMessage: odStock.message,
        osMessage: osStock.message,
      });
    };

    checkStock();
  }, [
    selectedFamilyId,
    activePrescription.sphere_od,
    activePrescription.cylinder_od,
    activePrescription.sphere_os,
    activePrescription.cylinder_os,
    branchId,
  ]);

  // Notify parent when configuration changes
  useEffect(() => {
    if (!selectedFamily || !priceResult) {
      onSelect(null);
      return;
    }

    const config: ContactLensOrderConfig = {
      family_id: selectedFamily.id,
      family_name: selectedFamily.name,
      family_brand: selectedFamily.brand || "",
      modality: selectedFamily.modality || "spherical",
      use_type: selectedFamily.use_type || "monthly",
      packaging: selectedFamily.packaging || "box_6",
      prescription: activePrescription,
      price: priceResult.price * quantity,
      cost: (priceResult.cost || 0) * quantity,
      inStock: stockInfo.inStock,
      availableQuantity: stockInfo.availableQuantity,
      quantity,
    };
    onSelect(config);
    // ponytail: depends on selectedFamilyId, priceResult?.price, quantity (minimal deps)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedFamilyId, priceResult?.price, quantity]);

  // Handle create encargo
  const handleCreateEncargo = async (notes: string) => {
    if (!selectedFamily) return;

    setSubmittingEncargo(true);
    try {
      const customerName = customer
        ? `${customer.first_name || ""} ${customer.last_name || ""}`.trim() ||
          customer.name ||
          "Cliente no registrado"
        : "Cliente no registrado";

      await contactLensEncargoService.create({
        customer_id: customer?.id,
        customer_name: customerName,
        customer_rut: customer?.rut || undefined,
        customer_phone: customer?.phone || undefined,
        customer_email: customer?.email || undefined,
        contact_lens_family_id: selectedFamily.id,
        family_name: selectedFamily.name,
        family_brand: selectedFamily.brand || undefined,
        sphere_od: activePrescription.sphere_od,
        cylinder_od: activePrescription.cylinder_od,
        axis_od: activePrescription.axis_od || undefined,
        add_od: activePrescription.add_od || undefined,
        base_curve_od: activePrescription.base_curve_od || undefined,
        diameter_od: activePrescription.diameter_od || undefined,
        sphere_os: activePrescription.sphere_os,
        cylinder_os: activePrescription.cylinder_os,
        axis_os: activePrescription.axis_os || undefined,
        add_os: activePrescription.add_os || undefined,
        base_curve_os: activePrescription.base_curve_os || undefined,
        diameter_os: activePrescription.diameter_os || undefined,
        quantity,
        estimated_price: priceResult?.price,
        cost: priceResult?.cost,
        notes: notes || undefined,
      });

      toast.success("Encargo solicitado correctamente");
      setShowEncargoDialog(false);
    } catch (err) {
      appLogger.error("Error creating encargo:", err);
      toast.error("Error al crear encargo");
    } finally {
      setSubmittingEncargo(false);
    }
  };

  // Options generation
  const sphereOptions = useMemo(() => {
    const opts: number[] = [];
    for (let i = -12; i <= 8; i += 0.25) opts.push(i);
    return opts;
  }, []);

  const cylinderOptions = useMemo(() => {
    const opts: number[] = [];
    for (let i = 0; i >= -4; i -= 0.25) opts.push(i);
    return opts;
  }, []);

  const axisOptions = useMemo(() => {
    const opts: number[] = [];
    for (let i = 0; i <= 180; i += 5) opts.push(i);
    return opts;
  }, []);

  return {
    families,
    loadingFamilies,
    selectedFamilyId,
    handleFamilySelect,
