/**
 * usePOSAdvancedFrame — frame search state and effects for POSAdvancedSale.
 *
 * Extracted from usePOSAdvancedSale.ts to reduce file size.
 * Owns frame search state, debounced effects, and search action factories.
 */
"use client";

import { useCallback, useEffect, useState } from "react";

import { searchProducts } from "@/lib/api/services/productService";

import type { POSProduct } from "../types";
import { createSearchFramesAction } from "./posDataLoader";

export interface UsePOSAdvancedFrameProps {
  branchId: string | null;
}

export interface UsePOSAdvancedFrameReturn {
  frameSearchTerm: string;
  setFrameSearchTerm: (v: string) => void;
  frameResults: POSProduct[];
  frameLoading: boolean;
  selectedFrame: POSProduct | null;
  setSelectedFrame: (v: POSProduct | null) => void;
  nearFrameSearchTerm: string;
  setNearFrameSearchTerm: (v: string) => void;
  nearFrameResults: POSProduct[];
  nearFrameLoading: boolean;
  selectedNearFrame: POSProduct | null;
  setSelectedNearFrame: (v: POSProduct | null) => void;
  customerOwnNearFrame: boolean;
  setCustomerOwnNearFrame: (v: boolean) => void;
}

export function usePOSAdvancedFrame({
  branchId,
}: UsePOSAdvancedFrameProps): UsePOSAdvancedFrameReturn {
  const [frameSearchTerm, setFrameSearchTerm] = useState("");
  const [frameResults, setFrameResults] = useState<POSProduct[]>([]);
  const [frameLoading, setFrameLoading] = useState(false);
  const [selectedFrame, setSelectedFrame] = useState<POSProduct | null>(null);

  const [nearFrameSearchTerm, setNearFrameSearchTerm] = useState("");
  const [nearFrameResults, setNearFrameResults] = useState<POSProduct[]>([]);
  const [nearFrameLoading, setNearFrameLoading] = useState(false);
  const [selectedNearFrame, setSelectedNearFrame] = useState<POSProduct | null>(
    null,
  );
  const [customerOwnNearFrame, setCustomerOwnNearFrame] = useState(false);

  const searchFrames = useCallback(
    createSearchFramesAction(
      branchId,
      setFrameResults,
      setFrameLoading,
      searchProducts,
    ),
    [branchId],
  );

  useEffect(() => {
    const timer = setTimeout(() => {
      searchFrames(frameSearchTerm);
    }, 300);
    return () => clearTimeout(timer);
  }, [frameSearchTerm, searchFrames]);

  const searchNearFrames = useCallback(
    createSearchFramesAction(
      branchId,
      setNearFrameResults,
      setNearFrameLoading,
      searchProducts,
    ),
    [branchId],
  );

  useEffect(() => {
    const timer = setTimeout(() => {
      searchNearFrames(nearFrameSearchTerm);
    }, 300);
    return () => clearTimeout(timer);
  }, [nearFrameSearchTerm, searchNearFrames]);

  return {
    frameSearchTerm,
    setFrameSearchTerm,
    frameResults,
    frameLoading,
    selectedFrame,
    setSelectedFrame,
    nearFrameSearchTerm,
    setNearFrameSearchTerm,
    nearFrameResults,
    nearFrameLoading,
    selectedNearFrame,
    setSelectedNearFrame,
    customerOwnNearFrame,
    setCustomerOwnNearFrame,
  };
}

/**
 * usePOSAdvancedPrescription — prescription loading and external prescription state.
 *
 * Extracted from usePOSAdvancedSale.ts to reduce file size.
 * Delegates to posDataLoader actions for zero-behavior-change refactor.
 */
"use client";

import { useCallback, useEffect, useState } from "react";

import {
  getPrescriptions,
  type Prescription,
} from "@/lib/api/services/customerService";

import { DEFAULT_LENS_FAMILIES } from "./POSAdvancedSale.constants";
import type {
  ExternalPrescriptionData,
  OrderFormData,
} from "./POSAdvancedSale.types";
import { loadPrescriptionsAction } from "./posDataLoader";
import { suggestLensFamily as suggestLensFamilyPure } from "./posPricingUtils";

export interface UsePOSAdvancedPrescriptionProps {
  customerId: string | undefined;
  quickCustomerName?: string | null;
  quickCustomerRUT?: string | null;
  orderFormData: OrderFormData;
  setOrderFormData: React.Dispatch<React.SetStateAction<OrderFormData>>;
}

export interface UsePOSAdvancedPrescriptionReturn {
  prescriptions: Prescription[];
  selectedPrescription: Prescription | null;
  setSelectedPrescription: (v: Prescription | null) => void;
  loadingPrescriptions: boolean;
  externalPrescriptionData: ExternalPrescriptionData;
  setExternalPrescriptionData: React.Dispatch<
    React.SetStateAction<ExternalPrescriptionData>
  >;
  useExternalPrescription: boolean;
  setUseExternalPrescription: (v: boolean) => void;
  suggestLensFamily: () => void;
}

export function usePOSAdvancedPrescription({
  customerId,
  quickCustomerName,
  quickCustomerRUT,
  orderFormData,
  setOrderFormData,
}: UsePOSAdvancedPrescriptionProps): UsePOSAdvancedPrescriptionReturn {
  const [prescriptions, setPrescriptions] = useState<Prescription[]>([]);
  const [selectedPrescription, setSelectedPrescription] =
    useState<Prescription | null>(null);
  const [loadingPrescriptions, setLoadingPrescriptions] = useState(false);

  const [externalPrescriptionData, setExternalPrescriptionData] =
    useState<ExternalPrescriptionData>({
      prescription_date: "",
      expiration_date: "",
      prescription_number: "",
      issued_by: "",
      issued_by_license: "",
      od_sphere: "",
      od_cylinder: "",
      od_axis: "",
      od_add: "",
      os_sphere: "",
      os_cylinder: "",
      os_axis: "",
      os_add: "",
      pd: "",
      near_pd: "",
      frame_pd: "",
      height_segmentation: "",
    });
  const [useExternalPrescription, setUseExternalPrescription] = useState(false);

  // Auto-enable external prescription when quick customer but no registered customer
  useEffect(() => {
    if (!customerId && (quickCustomerName || quickCustomerRUT)) {
      setUseExternalPrescription(true);
    }
  }, [customerId, quickCustomerName, quickCustomerRUT]);

  // Load prescriptions when customer changes (delegates to posDataLoader for exact behavior)
  useEffect(() => {
    loadPrescriptionsAction(
      customerId,
      getPrescriptions,
      setPrescriptions,
      setSelectedPrescription,
      setLoadingPrescriptions,
    );
  }, [customerId]);

  const suggestLensFamily = useCallback(() => {
    const suggestion = suggestLensFamilyPure(
      selectedPrescription,
      DEFAULT_LENS_FAMILIES,
      orderFormData.lens_type,
    );
    if (!suggestion || !selectedPrescription) return;

    const hasAddition =
      (selectedPrescription.od_add && selectedPrescription.od_add > 0) ||
      (selectedPrescription.os_add && selectedPrescription.os_add > 0);

    setOrderFormData((prev) => ({
      ...prev,
      lens_family_id: suggestion.lens_family_id,
      lens_family_name: suggestion.lens_family_name,
      near_lens_family_id:
        prev.near_lens_family_id || suggestion.near_lens_family_id,
      near_lens_family_name:
        prev.near_lens_family_name || suggestion.near_lens_family_name,
      presbyopia_solution: hasAddition
        ? suggestion.presbyopia_solution
        : prev.presbyopia_solution,
    }));
  }, [selectedPrescription, orderFormData.lens_type, setOrderFormData]);

  return {
    prescriptions,
    selectedPrescription,
    setSelectedPrescription,
    loadingPrescriptions,
    externalPrescriptionData,
    setExternalPrescriptionData,
    useExternalPrescription,
    setUseExternalPrescription,
    suggestLensFamily,
  };
}

/**
 * usePOSAdvancedPricing — pricing calculations and discount state for POSAdvancedSale.
 *
 * Extracted from usePOSAdvancedSale.ts to reduce file size.
 * Pure computations + discount state; no side effects.
 */
"use client";

import { useCallback, useMemo, useState } from "react";

import type { POSProduct } from "../types";
import type { OrderFormData, Treatment } from "./POSAdvancedSale.types";
import type { LensFamily } from "./posPricingUtils";
import {
  computeDiscountAmount,
  computeLensPrice,
  computeNearLensPrice,
  computeTotalPrice,
  computeTreatmentsPrice,
  filterTreatmentsByLensType,
} from "./posPricingUtils";

export interface UsePOSAdvancedPricingProps {
  orderFormData: OrderFormData;
  treatments: Treatment[];
  lensFamilies: readonly LensFamily[];
  selectedFrame: POSProduct | null;
}

export interface UsePOSAdvancedPricingReturn {
  discountType: "none" | "percentage" | "fixed";
  setDiscountType: (v: "none" | "percentage" | "fixed") => void;
  discountValue: number;
  setDiscountValue: (v: number) => void;
  treatmentsPrice: number;
  lensPriceValue: number;
  nearLensPriceValue: number;
  lensPrice: () => number;
  totalPrice: () => number;
  discountAmount: () => number;
  filteredTreatments: Treatment[];
}

export function usePOSAdvancedPricing({
  orderFormData,
  treatments,
  lensFamilies,
  selectedFrame,
}: UsePOSAdvancedPricingProps): UsePOSAdvancedPricingReturn {
  const [discountType, setDiscountType] = useState<
    "none" | "percentage" | "fixed"
  >("none");
  const [discountValue, setDiscountValue] = useState(0);

  const treatmentsPrice = useMemo(
    () => computeTreatmentsPrice(orderFormData.treatment_ids, treatments),
    [orderFormData.treatment_ids, treatments],
  );

  const lensPriceValue = useMemo(
    () =>
      computeLensPrice(
        orderFormData.lens_family_id,
        orderFormData.presbyopia_solution,
        lensFamilies,
      ),
    [
      orderFormData.lens_family_id,
      orderFormData.presbyopia_solution,
      lensFamilies,
    ],
  );

  const nearLensPriceValue = useMemo(
    () => computeNearLensPrice(orderFormData.near_lens_family_id, lensFamilies),
    [orderFormData.near_lens_family_id, lensFamilies],
  );

  const lensPrice = useCallback(() => lensPriceValue, [lensPriceValue]);

  const totalPrice = useCallback(
    () =>
      computeTotalPrice(
        selectedFrame,
        orderFormData.customer_own_frame,
        lensPrice(),
        treatmentsPrice,
        orderFormData.labor_cost,
        discountType,
        discountValue,
      ),
    [
      selectedFrame,
      orderFormData.customer_own_frame,
      lensPrice,
      treatmentsPrice,
      orderFormData.labor_cost,
      discountType,
      discountValue,
    ],
  );

  const discountAmount = useCallback(
    () =>
      computeDiscountAmount(
        selectedFrame,
        orderFormData.customer_own_frame,
        lensPrice(),
        treatmentsPrice,
        orderFormData.labor_cost,
        discountType,
        discountValue,
      ),
    [
      selectedFrame,
      orderFormData.customer_own_frame,
      lensPrice,
      treatmentsPrice,
      orderFormData.labor_cost,
      discountType,
      discountValue,
    ],
  );

  const filteredTreatments = useMemo(
    () => filterTreatmentsByLensType(treatments, orderFormData.lens_type),
    [treatments, orderFormData.lens_type],
  );

  return {
    discountType,
    setDiscountType,
    discountValue,
    setDiscountValue,
    treatmentsPrice,
    lensPriceValue,
    nearLensPriceValue,
    lensPrice,
    totalPrice,
    discountAmount,
    filteredTreatments,
  };
}

"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { toast } from "sonner";

import { type QuoteSettings,quoteSettingsService } from "@/lib/api/services/quoteSettingsService";

import type { ContactLensOrderConfig } from "./ContactLensSelector";
import { DEFAULT_LENS_FAMILIES, DEFAULT_TREATMENTS } from "./POSAdvancedSale.constants";
import type { OrderFormData, POSAdvancedSaleProps, Treatment } from "./POSAdvancedSale.types";
import { buildCartItems, type CartBuilderInput } from "./posCartBuilder";
import { handleCreateQuoteAction, loadSettingsAction } from "./posDataLoader";
import { filterTreatmentsByLensType,updateTreatmentPrice as updateTreatmentPricePure } from "./posPricingUtils";
import { usePOSAdvancedFrame } from "./usePOSAdvancedFrame";
import { usePOSAdvancedPrescription } from "./usePOSAdvancedPrescription";
import { usePOSAdvancedPricing } from "./usePOSAdvancedPricing";

export function usePOSAdvancedSale({
  customer,
  onCustomerChange,
  onAddToCart,
  branchId,
  selectedQuote,
  quickCustomerName,
  quickCustomerRUT,
  quickCustomerEmail,
  quickCustomerPhone,
}: POSAdvancedSaleProps) {
  const [orderFormTab, setOrderFormTab] = useState<
    "customer" | "frame" | "lenses" | "pricing"
  >("customer");


  const [orderFormData, setOrderFormData] = useState<OrderFormData>({
    lens_family_id: null,
    lens_family_name: null,
    near_lens_family_id: null,
    near_lens_family_name: null,
    lens_type: "vision",
    lens_sourcing_type: "surfaced",
    presbyopia_solution: "single",
    treatment_ids: [],
    labor_cost: 0,
    frame_name: "",
    frame_sku: "",
    near_frame_name: "",
    near_frame_sku: "",
    customer_own_frame: false,
    notes: "",
  });

  const lensFamilies = DEFAULT_LENS_FAMILIES;
  const [treatments, setTreatments] = useState<Treatment[]>(DEFAULT_TREATMENTS);
  const [quoteSettings, setQuoteSettings] = useState<QuoteSettings | null>(null);
  const [creatingQuote, setCreatingQuote] = useState(false);
  const [contactLensConfig, setContactLensConfig] =
    useState<ContactLensOrderConfig | null>(null);



  const frame = usePOSAdvancedFrame({ branchId });
  const prescription = usePOSAdvancedPrescription({
    customerId: customer?.id,
    quickCustomerName,
    quickCustomerRUT,
    orderFormData,
    setOrderFormData,
  });
  const pricing = usePOSAdvancedPricing({
    orderFormData,
    treatments,
    lensFamilies,
    selectedFrame: frame.selectedFrame,
  });

  useEffect(() => {
    loadSettingsAction(
      quoteSettingsService,
      setQuoteSettings,
      (updater) => setTreatments((prev) => updater(prev)),
      (cost) => setOrderFormData((prev) => ({ ...prev, labor_cost: cost })),
    );
  }, []);

  useEffect(() => {
    if (selectedQuote) {
      setOrderFormData((prev) => ({
        ...prev,
        labor_cost: selectedQuote.labor_cost || prev.labor_cost,
      }));
      if (selectedQuote.lens_type) {
        setOrderFormData((prev) => ({
          ...prev,
          lens_type:
            selectedQuote.lens_type === "contact" ? "contact" : "vision",
        }));
      }
    }
  }, [selectedQuote]);

  // ── Handlers ──
  const handleCreateQuote = async () => {
    await handleCreateQuoteAction(
      {
        customer,
        quickCustomerName,
        quickCustomerRUT,
        quickCustomerEmail,
        quickCustomerPhone,
        branchId,
        selectedPrescription: prescription.selectedPrescription,
        selectedFrame: frame.selectedFrame,
        selectedNearFrame: frame.selectedNearFrame,
        orderFormData,
        customerOwnNearFrame: frame.customerOwnNearFrame,
        lensPrice: pricing.lensPrice,
        treatmentsPrice: pricing.treatmentsPrice,
        totalPrice: pricing.totalPrice,
        discountAmount: pricing.discountAmount,
      },
      { setCreatingQuote, onCustomerChange },
    );
  };

  const handleUpdateTreatmentPrice = useCallback(
    (treatmentId: string, newPrice: number) => {
      setTreatments((prev) =>
        updateTreatmentPricePure(prev, treatmentId, newPrice),
      );
    },
    [],
  );

  const filteredTreatments = useMemo(
    () =>
      filterTreatmentsByLensType(treatments, orderFormData.lens_type as "vision" | "contact"),
    [treatments, orderFormData.lens_type],
  );

  const toggleTreatment = useCallback(
    (treatmentId: string) => {
      setOrderFormData((prev) => ({
        ...prev,
        treatment_ids: prev.treatment_ids.includes(treatmentId)
          ? prev.treatment_ids.filter((id) => id !== treatmentId)
          : [...prev.treatment_ids, treatmentId],
      }));
    },
    [],
  );

  const handleAddToCart = useCallback(() => {
    const currentLensPrice = pricing.lensPrice();

    const items = buildCartItems({
      orderFormData,
      selectedFrame: frame.selectedFrame,
      selectedNearFrame: frame.selectedNearFrame,
      customerOwnNearFrame: frame.customerOwnNearFrame,
      lensFamilies,
      treatments,
      currentLensPrice,
      treatmentsPrice: pricing.treatmentsPrice,
      contactLensConfig: contactLensConfig as CartBuilderInput["contactLensConfig"],
      useExternalPrescription: prescription.useExternalPrescription,
      externalPrescriptionData: prescription.externalPrescriptionData,
    });

    if (items.length === 0) {
      toast.warning("Seleccione al menos un producto (armazón o lentes)");
      return;
    }

    onAddToCart(items);
    toast.success("Productos agregados al carrito");

    // Reset form
    frame.setSelectedFrame(null);
    frame.setFrameSearchTerm("");
    frame.setSelectedNearFrame(null);
    frame.setNearFrameSearchTerm("");
    frame.setCustomerOwnNearFrame(false);
    setOrderFormData({
      lens_family_id: null,
      lens_family_name: null,
      near_lens_family_id: null,
      near_lens_family_name: null,
      lens_type: "vision",
      lens_sourcing_type: "surfaced",
      presbyopia_solution: "single",
      treatment_ids: [],
      labor_cost: 0,
      frame_name: "",
      frame_sku: "",
      near_frame_name: "",
      near_frame_sku: "",
      customer_own_frame: false,
      notes: "",
    });
    prescription.setUseExternalPrescription(false);
    prescription.setExternalPrescriptionData({
      prescription_date: "",
      expiration_date: "",
      prescription_number: "",
      issued_by: "",
      issued_by_license: "",
      od_sphere: "",
      od_cylinder: "",
      od_axis: "",
      od_add: "",
      os_sphere: "",
      os_cylinder: "",
      os_axis: "",
      os_add: "",
      pd: "",
      near_pd: "",
      frame_pd: "",
      height_segmentation: "",
    });
  }, [
    orderFormData,
    frame.selectedFrame,
    frame.selectedNearFrame,
    frame.customerOwnNearFrame,
    frame.setSelectedFrame,
    frame.setFrameSearchTerm,
    frame.setSelectedNearFrame,
    frame.setNearFrameSearchTerm,
    frame.setCustomerOwnNearFrame,
    lensFamilies,
    treatments,
    pricing.lensPrice,
    pricing.treatmentsPrice,
    contactLensConfig,
    prescription.useExternalPrescription,
    prescription.externalPrescriptionData,
    prescription.setUseExternalPrescription,
    prescription.setExternalPrescriptionData,
    onAddToCart,
  ]);

  return {
    orderFormTab, setOrderFormTab,
    ...frame,
    lensFamilies, treatments, setTreatments, quoteSettings,
    ...prescription,
    discountType: pricing.discountType, setDiscountType: pricing.setDiscountType,
    discountValue: pricing.discountValue, setDiscountValue: pricing.setDiscountValue,
    treatmentsPrice: pricing.treatmentsPrice, lensPriceValue: pricing.lensPriceValue,
    nearLensPriceValue: pricing.nearLensPriceValue, lensPrice: pricing.lensPrice,
    totalPrice: pricing.totalPrice, discountAmount: pricing.discountAmount,
    handleUpdateTreatmentPrice, filteredTreatments,
    orderFormData, setOrderFormData,
    creatingQuote, contactLensConfig, setContactLensConfig,
    toggleTreatment, handleCreateQuote, handleAddToCart,
  };
}

"use client";

import React, { createContext, useContext, useMemo } from "react";

import type {
  POSCartItem,
  POSCustomer,
  POSPaymentMethod as PaymentMethod,
} from "../types";

export interface POSContextValue {
  branchId: string | null;
  cart: POSCartItem[];
  setCart: React.Dispatch<React.SetStateAction<POSCartItem[]>>;
  selectedCustomer: POSCustomer | null;
  setSelectedCustomer: React.Dispatch<React.SetStateAction<POSCustomer | null>>;
  paymentMethod: PaymentMethod;
  setPaymentMethod: React.Dispatch<React.SetStateAction<PaymentMethod>>;
  cashReceived: number;
  setCashReceived: React.Dispatch<React.SetStateAction<number>>;
  isCashOpen: boolean | null;
}

const POSContext = createContext<POSContextValue | null>(null);

export function usePOSContext() {
  const ctx = useContext(POSContext);
  if (!ctx) {
    throw new Error("usePOSContext must be used within POSProvider");
  }
  return ctx;
}

export function POSProvider({
  children,
  value,
}: {
  children: React.ReactNode;
  value: POSContextValue;
}) {
  const memoValue = useMemo(
    () => value,
    [
      value.branchId,
      value.cart,
      value.selectedCustomer,
      value.paymentMethod,
      value.cashReceived,
      value.isCashOpen,
    ],
  );

  return (
    <POSContext.Provider value={memoValue}>{children}</POSContext.Provider>
  );
}

/**
 * Tests for usePOSPayment — POS payment handling hook.
 *
 * Coverage:
 *   - Initial state: defaults
 *   - Totals calculation: with/without included tax, mixed, empty cart
 *   - Change calculation
 *   - Minimum deposit (30%)
 *   - isPaymentSufficient: cash full, cash partial, non-cash
 *   - Effective payment amount
 *   - Reset payment
 *   - Quick cash amounts (unique, rounding)
 *   - Handle payment: success, insufficient
 *   - Validate payment: cash, card, transfer
 */
import { act, renderHook } from "@testing-library/react";
import { describe, expect, it } from "vitest";

import type { POSCartItem } from "../../types";
import { usePOSPayment } from "../usePOSPayment";

// ─── Factory ──────────────────────────────────────────────────────────────────

function makeCartItem(
  overrides?: Partial<POSCartItem>,
): POSCartItem {
  return {
    product: { id: "p-1", name: "Product", price: 10000, inventory_quantity: 5 },
    quantity: 1,
    unitPrice: 10000,
    subtotal: 10000,
    priceIncludesTax: true,
    ...overrides,
  };
}

// ─── Tests ────────────────────────────────────────────────────────────────────

describe("usePOSPayment", () => {
  describe("initial state", () => {
    it("defaults to cash payment method", () => {
      const { result } = renderHook(() => usePOSPayment());
      expect(result.current.paymentMethod).toBe("cash");
    });

    it("initializes totals to zero with empty cart", () => {
      const { result } = renderHook(() => usePOSPayment({ cart: [] }));
      expect(result.current.totals).toEqual({ subtotal: 0, taxAmount: 0, total: 0 });
    });

    it("initializes cashReceived to 0", () => {
      const { result } = renderHook(() => usePOSPayment());
      expect(result.current.cashReceived).toBe(0);
    });

    it("initializes isPartial to false", () => {
      const { result } = renderHook(() => usePOSPayment());
      expect(result.current.isPartial).toBe(false);
    });
  });

  describe("totals calculation", () => {
    it("computes totals for cart items with tax included", () => {
      const cart = [
        makeCartItem({ unitPrice: 119000, subtotal: 119000, priceIncludesTax: true }),
      ];
      const { result } = renderHook(() => usePOSPayment({ cart }));

      // 119000 includes 19% IVA → base = 119000 / 1.19 = 100000, tax = 19000
      expect(result.current.totals.subtotal).toBe(100000);
      expect(result.current.totals.taxAmount).toBe(19000);
      expect(result.current.totals.total).toBe(119000);
    });

    it("computes totals for cart items without tax included", () => {
      const cart = [
        makeCartItem({ unitPrice: 100000, subtotal: 100000, priceIncludesTax: false }),
      ];
      const { result } = renderHook(() => usePOSPayment({ cart }));

      // 100000 without IVA → tax = 19000, total = 119000
      expect(result.current.totals.subtotal).toBe(100000);
      expect(result.current.totals.taxAmount).toBe(19000);
      expect(result.current.totals.total).toBe(119000);
    });

    it("handles mixed tax-included and non-tax items", () => {
      const cart = [
        makeCartItem({ unitPrice: 119000, quantity: 1, subtotal: 119000, priceIncludesTax: true }),
        makeCartItem({
          unitPrice: 50000,
          quantity: 1,
          subtotal: 50000,
          priceIncludesTax: false,
          product: { id: "p-2", name: "Labor", price: 50000, inventory_quantity: 0 },
        }),
      ];
      const { result } = renderHook(() => usePOSPayment({ cart }));

      // Item 1: base = 119000/1.19 = 100000, tax extracted = 19000
      // Item 2: base = 50000, tax added = 50000 * 0.19 = 9500
      // subtotal = 100000 + 50000 = 150000
      // tax = 19000 + 9500 = 28500
      // total = 150000 + 28500 = 178500
      expect(result.current.totals.subtotal).toBe(150000);
      expect(result.current.totals.taxAmount).toBe(28500);
      expect(result.current.totals.total).toBe(178500);
    });

    it("handles multiple quantities", () => {
      const cart = [
        makeCartItem({ unitPrice: 59500, quantity: 2, subtotal: 119000, priceIncludesTax: true }),
      ];
      const { result } = renderHook(() => usePOSPayment({ cart }));

      // 59500 * 2 = 119000 → base = 100000, tax = 19000
      expect(result.current.totals.subtotal).toBe(100000);
      expect(result.current.totals.taxAmount).toBe(19000);
    });
  });

  describe("change calculation", () => {
    it("returns 0 when cashReceived is less than total", () => {
      const cart = [makeCartItem({ unitPrice: 50000, subtotal: 50000, priceIncludesTax: true })];
      const { result } = renderHook(() => usePOSPayment({ cart }));

      act(() => result.current.setCashReceived(30000));
      expect(result.current.change).toBe(0);
    });

    it("calculates correct change when cashReceived exceeds total", () => {
      const cart = [makeCartItem({ unitPrice: 50000, subtotal: 50000, priceIncludesTax: true })];
      const { result } = renderHook(() => usePOSPayment({ cart }));

      // 50000 includes tax → base = ~42017, total = 50000
      act(() => result.current.setCashReceived(60000));
      expect(result.current.change).toBe(10000);
    });

    it("returns 0 when cashReceived equals total", () => {
      const cart = [makeCartItem({ unitPrice: 50000, subtotal: 50000, priceIncludesTax: true })];
      const { result } = renderHook(() => usePOSPayment({ cart }));

      act(() => result.current.setCashReceived(50000));
      expect(result.current.change).toBe(0);
    });
  });

  describe("minDeposit", () => {
    it("calculates 30% of total as minimum deposit", () => {
      const cart = [makeCartItem({ unitPrice: 119000, subtotal: 119000, priceIncludesTax: true })];
      const { result } = renderHook(() => usePOSPayment({ cart }));

      expect(result.current.minDeposit).toBe(35700); // 119000 * 0.3
    });
  });

  describe("isPaymentSufficient", () => {
    it("is true when cashReceived >= total for cash payment", () => {
      const cart = [makeCartItem({ unitPrice: 119000, subtotal: 119000, priceIncludesTax: true })];
      const { result } = renderHook(() => usePOSPayment({ cart }));

      act(() => result.current.setCashReceived(119000));
      expect(result.current.isPaymentSufficient).toBe(true);
    });

    it("is false when cashReceived < total for cash payment (non-partial)", () => {
      const cart = [makeCartItem({ unitPrice: 119000, subtotal: 119000, priceIncludesTax: true })];
      const { result } = renderHook(() => usePOSPayment({ cart }));

      act(() => result.current.setCashReceived(50000));
      expect(result.current.isPaymentSufficient).toBe(false);
    });

    it("is true for partial payment when partialAmount >= minDeposit", () => {
      const cart = [makeCartItem({ unitPrice: 119000, subtotal: 119000, priceIncludesTax: true })];
      const { result } = renderHook(() => usePOSPayment({ cart }));

      act(() => {
        result.current.setIsPartial(true);
        result.current.setPartialAmount(35700);
      });
      expect(result.current.isPaymentSufficient).toBe(true);
    });

    it("is false for partial payment when partialAmount < minDeposit", () => {
      const cart = [makeCartItem({ unitPrice: 119000, subtotal: 119000, priceIncludesTax: true })];
      const { result } = renderHook(() => usePOSPayment({ cart }));

      act(() => {
        result.current.setIsPartial(true);
        result.current.setPartialAmount(10000);
      });
      expect(result.current.isPaymentSufficient).toBe(false);
    });

    it("is always true for non-cash payment methods (card, transfer)", () => {
      const cart = [makeCartItem({ unitPrice: 119000, subtotal: 119000, priceIncludesTax: true })];
      const { result } = renderHook(() => usePOSPayment({ cart }));

      act(() => result.current.setPaymentMethod("debit_card"));
      expect(result.current.isPaymentSufficient).toBe(true);

      act(() => result.current.setPaymentMethod("credit_card"));
      expect(result.current.isPaymentSufficient).toBe(true);

      act(() => result.current.setPaymentMethod("transfer"));
      expect(result.current.isPaymentSufficient).toBe(true);
    });
  });

  describe("effectivePaymentAmount", () => {
    it("equals total when not partial", () => {
      const cart = [makeCartItem({ unitPrice: 50000, subtotal: 50000, priceIncludesTax: true })];
      const { result } = renderHook(() => usePOSPayment({ cart }));

      expect(result.current.effectivePaymentAmount).toBe(50000);
    });

    it("equals partialAmount when isPartial", () => {
      const cart = [makeCartItem({ unitPrice: 100000, subtotal: 100000, priceIncludesTax: true })];
      const { result } = renderHook(() => usePOSPayment({ cart }));

      act(() => {
        result.current.setIsPartial(true);
        result.current.setPartialAmount(40000);
      });
      expect(result.current.effectivePaymentAmount).toBe(40000);
    });
  });

  describe("effectiveChange", () => {
    it("calculates change against effective payment amount", () => {
      const cart = [makeCartItem({ unitPrice: 50000, subtotal: 50000, priceIncludesTax: true })];
      const { result } = renderHook(() => usePOSPayment({ cart }));

      act(() => {
        result.current.setIsPartial(true);
        result.current.setPartialAmount(30000);
        result.current.setCashReceived(50000);
      });
      expect(result.current.effectiveChange).toBe(20000); // 50000 - 30000
    });
  });

  describe("resetPayment", () => {
    it("resets all payment fields to defaults", () => {
      const { result } = renderHook(() => usePOSPayment());

      act(() => {
        result.current.setCashReceived(50000);
        result.current.setIsPartial(true);
        result.current.setPartialAmount(20000);
        result.current.setFiscalReference("FIS-123");
        result.current.setCardLastFour("1234");
        result.current.setCardBrand("Visa");
        result.current.setTransferReference("TRF-001");
      });

      act(() => result.current.resetPayment());

      expect(result.current.cashReceived).toBe(0);
      expect(result.current.isPartial).toBe(false);
      expect(result.current.partialAmount).toBe(0);
      expect(result.current.fiscalReference).toBe("");
      expect(result.current.cardLastFour).toBe("");
      expect(result.current.cardBrand).toBe("");
      expect(result.current.transferReference).toBe("");
    });
  });

  describe("handleQuickCash", () => {
    it("sets cash received to the given amount", () => {
      const { result } = renderHook(() => usePOSPayment());

      act(() => result.current.handleQuickCash(50000));
      expect(result.current.cashReceived).toBe(50000);
    });
  });

  describe("quickCashAmounts", () => {
    it("generates unique rounded amounts above total", () => {
      const cart = [makeCartItem({ unitPrice: 22300, subtotal: 22300, priceIncludesTax: true })];
      const { result } = renderHook(() => usePOSPayment({ cart }));

      // total = 22300, quick amounts should round up
      expect(result.current.quickCashAmounts.length).toBeGreaterThanOrEqual(1);
      expect(result.current.quickCashAmounts.every((a) => a >= 22300)).toBe(true);
      expect(new Set(result.current.quickCashAmounts).size).toBe(
        result.current.quickCashAmounts.length,
      );
    });
  });

  describe("handlePayment", () => {
    it("returns payment data when payment is sufficient", () => {
      const onSubmit = (): void => {};
      const cart = [makeCartItem({ unitPrice: 50000, subtotal: 50000, priceIncludesTax: true })];
      const { result } = renderHook(() => usePOSPayment({ cart, onPaymentSubmit: onSubmit }));

      act(() => result.current.setCashReceived(50000));

      let paymentData: ReturnType<typeof result.current.handlePayment> | undefined;
      act(() => {
        paymentData = result.current.handlePayment();
      });

      expect(paymentData?.method).toBe("cash");
      expect(paymentData?.cashReceived).toBe(50000);
      expect(paymentData?.change).toBe(0);
      expect(paymentData?.isPartial).toBe(false);
    });

    it("throws when payment is insufficient", () => {
      const cart = [makeCartItem({ unitPrice: 50000, subtotal: 50000, priceIncludesTax: true })];
      const { result } = renderHook(() => usePOSPayment({ cart }));

      act(() => result.current.setCashReceived(10000));

      expect(() => result.current.handlePayment()).toThrow("Monto insuficiente");
    });

    it("includes additional payment fields when set", () => {
      const cart = [makeCartItem({ unitPrice: 50000, subtotal: 50000, priceIncludesTax: true })];
      const { result } = renderHook(() => usePOSPayment({ cart }));

      act(() => {
        result.current.setPaymentMethod("transfer");
        result.current.setTransferReference("TRF-001");
      });

      let paymentData: ReturnType<typeof result.current.handlePayment> | undefined;
      act(() => {
        paymentData = result.current.handlePayment();
      });

      expect(paymentData?.method).toBe("transfer");
      expect(paymentData?.transferReference).toBe("TRF-001");
    });
  });

  describe("validatePayment", () => {
    it("returns null when cash is sufficient", () => {
      const cart = [makeCartItem({ unitPrice: 50000, subtotal: 50000, priceIncludesTax: true })];
      const { result } = renderHook(() => usePOSPayment({ cart }));

      act(() => result.current.setCashReceived(50000));

      expect(result.current.validatePayment()).toBeNull();
    });

    it("returns error when cash is insufficient and not partial", () => {
      const cart = [makeCartItem({ unitPrice: 50000, subtotal: 50000, priceIncludesTax: true })];
      const { result } = renderHook(() => usePOSPayment({ cart }));

      act(() => result.current.setCashReceived(10000));

      expect(result.current.validatePayment()).toBe("Monto en efectivo insuficiente");
    });

    it("returns null when cash is insufficient but isPartial", () => {
      const cart = [makeCartItem({ unitPrice: 50000, subtotal: 50000, priceIncludesTax: true })];
      const { result } = renderHook(() => usePOSPayment({ cart }));

      act(() => {
        result.current.setCashReceived(10000);
        result.current.setIsPartial(true);
      });

      // Partial bypasses the "cash insufficient" check
      expect(result.current.validatePayment()).toBeNull();
    });

    it("returns error when transfer reference is empty for transfer method", () => {
      const { result } = renderHook(() => usePOSPayment());

      act(() => result.current.setPaymentMethod("transfer"));

      expect(result.current.validatePayment()).toBe("Ingrese referencia de transferencia");
    });

    it("returns null for card payments without additional validation", () => {
      const { result } = renderHook(() => usePOSPayment());

      act(() => result.current.setPaymentMethod("debit_card"));

      expect(result.current.validatePayment()).toBeNull();
    });
  });
});

import { useCallback } from "react";

import type { POSCartItem, POSProduct } from "../types";

export interface UsePOSCartProps {
  cart: POSCartItem[];
  setCart: React.Dispatch<React.SetStateAction<POSCartItem[]>>;
}

export function usePOSCart({ cart, setCart }: UsePOSCartProps) {
  const addToCart = useCallback(
    (product: POSProduct) => {
      const existingItem = cart.find((item) => item.product.id === product.id);

      if (existingItem) {
        updateQuantity(product.id, existingItem.quantity + 1);
      } else {
        setCart((prev) => [
          ...prev,
          {
            product,
            quantity: 1,
            unitPrice: product.price,
            subtotal: product.price,
            priceIncludesTax: product.price_includes_tax ?? true,
          },
        ]);
      }
    },
    [cart, setCart],
  );

  const updateQuantity = useCallback(
    (productId: string, quantity: number) => {
      if (quantity <= 0) {
        removeFromCart(productId);
        return;
      }

      setCart((prev) =>
        prev.map((item) =>
          item.product.id === productId
            ? {
                ...item,
                quantity,
                subtotal: item.unitPrice * quantity,
              }
            : item,
        ),
      );
    },
    [setCart],
  );

  const removeFromCart = useCallback(
    (productId: string) => {
      setCart((prev) => prev.filter((item) => item.product.id !== productId));
    },
    [setCart],
  );

  const clearCart = useCallback(() => {
    setCart([]);
  }, [setCart]);

  return {
    addToCart,
    updateQuantity,
    removeFromCart,
    clearCart,
  };
}

/**
 * usePOSCustomer - Hook para gestión de clientes en el POS
 * Extraído de page.tsx para mejorar modularidad
 */

import { useCallback, useEffect, useRef, useState } from "react";

import { searchCustomers } from "@/lib/api/services";
import { appLogger } from '@/lib/logger';

import type { POSCustomer } from "../types";

interface UsePOSCustomerProps {
  branchId?: string | null;
  fieldOperationId?: string | null;
  onCustomerSelect?: (customer: POSCustomer | null) => void;
  onQuotesFetch?: (customerId: string) => void;
}

export function usePOSCustomer({
  branchId,
  fieldOperationId,
  onCustomerSelect,
  onQuotesFetch,
}: UsePOSCustomerProps = {}) {
  // States
  const [searchTerm, setSearchTerm] = useState("");
  const [results, setResults] = useState<POSCustomer[]>([]);
  const [selectedCustomer, setSelectedCustomer] = useState<POSCustomer | null>(
    null,
  );
  const [selectedIndex, setSelectedIndex] = useState(-1);
  const [loading, setLoading] = useState(false);
  const [businessName, setBusinessName] = useState("");
  const [rut, setRut] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");

  // Refs
  const searchInputRef = useRef<HTMLInputElement>(null);
  const suggestionsRef = useRef<HTMLDivElement>(null);
  const debounceRef = useRef<NodeJS.Timeout | null>(null);

  // Search customers with debounce
  useEffect(() => {
    if (searchTerm.trim().length < 2) {
      setResults([]);
      setLoading(false);
      return;
    }

    setLoading(true);

    if (debounceRef.current) {
      clearTimeout(debounceRef.current);
    }

    debounceRef.current = setTimeout(async () => {
      try {
        const searchResults = await searchCustomers(
          searchTerm,
          branchId || undefined,
          fieldOperationId || undefined,
        );
        // Map to POSCustomer
        const mappedResults: typeof results = (searchResults || []).map(
          (c) => ({
            id: c.id,
            email: c.email,
            first_name: c.first_name,
            last_name: c.last_name,
            name: c.name,
            rut: c.rut,
            business_name: undefined,
            address: undefined,
            phone: c.phone,
            is_convenio_client: undefined,
          }),
        );
        setResults(mappedResults);
        setSelectedIndex(-1);
      } catch (error) {
        appLogger.error("Error searching customers:", error);
        setResults([]);
      } finally {
        setLoading(false);
      }
    }, 300);

    return () => {
      if (debounceRef.current) {
        clearTimeout(debounceRef.current);
      }
    };
  }, [searchTerm, branchId, fieldOperationId]);

  // Handle keyboard navigation
  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === "Enter") {
        e.preventDefault();
        if (selectedIndex >= 0 && results[selectedIndex]) {
          handleSelectCustomer(results[selectedIndex]);
        } else if (results.length > 0) {
          handleSelectCustomer(results[0]);
        }
      } else if (e.key === "ArrowDown") {
        e.preventDefault();
        setSelectedIndex((prev) =>
          prev < results.length - 1 ? prev + 1 : prev,
        );
      } else if (e.key === "ArrowUp") {
        e.preventDefault();
        setSelectedIndex((prev) => (prev > 0 ? prev - 1 : -1));
      } else if (e.key === "Escape") {
        setResults([]);
        setSearchTerm("");
        setSelectedIndex(-1);
      }
    },
    [selectedIndex, results],
  );

  // Select customer
  const handleSelectCustomer = useCallback(
    (customer: POSCustomer) => {
      // Build full name from first_name + last_name if name is not set
      const fullName =
        customer.name ||
        (customer.first_name && customer.last_name
          ? `${customer.first_name} ${customer.last_name}`.trim()
          : customer.first_name || customer.email || "");

      setSelectedCustomer({
        ...customer,
        name: fullName, // Ensure name is always set
      });
      setSearchTerm(fullName);
      setResults([]);
      setSelectedIndex(-1);
      setBusinessName(customer.business_name || "");
      setRut(customer.rut || "");
      onCustomerSelect?.(customer);
      onQuotesFetch?.(customer.id);
    },
    [onCustomerSelect, onQuotesFetch],
  );

  // Clear customer selection
  const clearCustomer = useCallback(() => {
    setSelectedCustomer(null);
    setSearchTerm("");
    setResults([]);
    setSelectedIndex(-1);
    setBusinessName("");
    setRut("");
    setEmail("");
    setPhone("");
    onCustomerSelect?.(null);
  }, [onCustomerSelect]);

  // Update search term and clear selection if empty (but only if no customer is selected)
  const handleSearchChange = useCallback(
    (value: string) => {
      setSearchTerm(value);
      setSelectedIndex(-1);
      // Only clear customer if search is empty AND no customer is currently selected
      if (value.trim().length === 0 && !selectedCustomer) {
        clearCustomer();
      }
    },
    [clearCustomer, selectedCustomer],
  );

  return {
    // States
    searchTerm,
    setSearchTerm: handleSearchChange,
    results,
    selectedCustomer,
    selectedIndex,
    loading,
    businessName,
    setBusinessName,
    rut,
    setRut,
    email,
    setEmail,
    phone,
    setPhone,

    // Refs
    searchInputRef,
    suggestionsRef,

    // Methods
    handleSelectCustomer,
    handleKeyDown,
    clearCustomer,

    // Helpers
    hasResults: results.length > 0,
    isSearching: loading && searchTerm.trim().length >= 2,
  };
}

"use client";

import { useCallback, useMemo, useState } from "react";

export type DiscountType = "percentage" | "amount";

export interface UsePOSDiscountProps {
  /**
   * Subtotal base para calcular descuento
   */
  subtotal: number;
  /**
   * Callback opcional cuando cambia el descuento
   */
  onDiscountChange?: (discountAmount: number) => void;
}

export interface UsePOSDiscountReturn {
  /**
   * Tipo de descuento: porcentaje o monto fijo
   */
  discountType: DiscountType;
  /**
   * Valor del descuento (porcentaje o monto)
   */
  discountValue: number;
  /**
   * Monto de descuento calculado
   */
  discountAmount: number;
  /**
   * Subtotal después del descuento
   */
  effectiveSubtotal: number;
  /**
   * Si hay un descuento aplicado
   */
  hasDiscount: boolean;
  /**
   * Cambiar tipo de descuento
   */
  setDiscountType: (type: DiscountType) => void;
  /**
   * Establecer valor del descuento
   */
  setDiscountValue: (value: number) => void;
  /**
   * Aplicar descuento (calcula y notifica)
   */
  applyDiscount: (subtotal: number) => void;
  /**
   * Limpiar descuento
   */
  clearDiscount: () => void;
  /**
   * Validar que el descuento no exceda el subtotal
   */
  isValid: (subtotal: number) => boolean;
}

/**
 * Hook para gestionar descuentos en el carrito POS.
 *
 * @param subtotal - Subtotal base para cálculos
 * @param onDiscountChange - Callback opcional cuando cambia el descuento
 */
export function usePOSDiscount({
  subtotal,
  onDiscountChange,
}: UsePOSDiscountProps): UsePOSDiscountReturn {
  const [discountType, setDiscountType] = useState<DiscountType>("percentage");
  const [discountValue, setDiscountValue] = useState<number>(0);
  const [hasDiscount, setHasDiscount] = useState<boolean>(false);

  /**
   * Calcular monto de descuento
   */
  const discountAmount = useMemo(() => {
    if (!hasDiscount || discountValue <= 0 || subtotal <= 0) {
      return 0;
    }

    if (discountType === "percentage") {
      // Porcentaje: no puede exceder 100%
      const percentage = Math.min(discountValue, 100);
      return Math.round((subtotal * percentage) / 100);
    }

    // Monto fijo: no puede exceder el subtotal
    return Math.min(discountValue, subtotal);
  }, [discountType, discountValue, hasDiscount, subtotal]);

  /**
   * Subtotal después del descuento
   */
  const effectiveSubtotal = useMemo(() => {
    return Math.max(0, subtotal - discountAmount);
  }, [subtotal, discountAmount]);

  /**
   * Validar que el descuento no exceda el subtotal
   */
  const isValid = useCallback(
    (currentSubtotal: number): boolean => {
      if (!hasDiscount || discountValue <= 0 || currentSubtotal <= 0) {
        return true;
      }

      if (discountType === "percentage") {
        return discountValue <= 100;
      }

      return discountValue <= currentSubtotal;
    },
    [discountType, discountValue, hasDiscount],
  );

  /**
   * Aplicar descuento
   */
  const applyDiscount = useCallback(
    (currentSubtotal: number) => {
      if (!isValid(currentSubtotal)) {
        // No aplicar si es inválido
        return;
      }
      setHasDiscount(true);
      onDiscountChange?.(discountAmount);
    },
    [isValid, discountAmount, onDiscountChange],
  );

  /**
   * Limpiar descuento
   */
  const clearDiscount = useCallback(() => {
    setDiscountValue(0);
    setHasDiscount(false);
    onDiscountChange?.(0);
  }, [onDiscountChange]);

  /**
   * Establecer valor del descuento (para uso directo)
   */
  const setDiscountValueInternal = useCallback((value: number) => {
    const cleanValue = Math.max(0, value);
    setDiscountValue(cleanValue);
    if (cleanValue > 0) {
      setHasDiscount(true);
    }
  }, []);

  return {
    discountType,
    discountValue,
    discountAmount,
    effectiveSubtotal,
    hasDiscount,
    setDiscountType,
    setDiscountValue: setDiscountValueInternal,
    applyDiscount,
    clearDiscount,
    isValid,
  };
}

/**
 * usePOSKeyboardShortcuts - Keyboard shortcuts for POS system
 * Provides F1-F4 for payment methods and Ctrl+K for search
 */

import { useCallback, useEffect } from "react";




interface UsePOSKeyboardShortcutsProps {
  // Payment method actions
  onCashPayment?: () => void;
  onCardPayment?: () => void;
  onTransferPayment?: () => void;
  onOtherPayment?: () => void;

  // Search actions
  onOpenSearch?: () => void;
  onSearchCustomer?: () => void;
  onSearchProduct?: () => void;

  // Cart actions
  onClearCart?: () => void;
  onCompleteSale?: () => void;

  // Modal/Dialog actions
  onOpenPaymentDialog?: () => void;
  onCloseDialog?: () => void;

  // Focus targets
  searchInputRef?: React.RefObject<HTMLInputElement | null>;
  customerInputRef?: React.RefObject<HTMLInputElement | null>;
  productInputRef?: React.RefObject<HTMLInputElement | null>;

  // State
  isPaymentDialogOpen?: boolean;
  isSearchOpen?: boolean;
  disabled?: boolean;
}

interface KeyboardShortcut {
  key: string;
  ctrl?: boolean;
  alt?: boolean;
  shift?: boolean;
  action: () => void;
  description: string;
}

export function usePOSKeyboardShortcuts({
  onCashPayment,
  onCardPayment,
  onTransferPayment,
  onOtherPayment,
  onOpenSearch,
  onSearchCustomer,
  onSearchProduct,
  onClearCart,
  onCompleteSale,
  onOpenPaymentDialog,
  onCloseDialog,
  searchInputRef,
  customerInputRef,
  productInputRef,
  isPaymentDialogOpen = false,
  isSearchOpen = false,
  disabled = false,
}: UsePOSKeyboardShortcutsProps) {
  // Handle key press
  const handleKeyDown = useCallback(
    (event: KeyboardEvent) => {
      if (disabled) return;

      const target = event.target as HTMLElement;
      const isInput =
        target.tagName === "INPUT" ||
        target.tagName === "TEXTAREA" ||
        target.isContentEditable;

      // Escape always closes dialogs
      if (event.key === "Escape") {
        if (isPaymentDialogOpen) {
          onCloseDialog?.();
          event.preventDefault();
          return;
        }
      }

      // F1-F4: Payment methods (only when not in input)
      if (!isInput || target.classList.contains("pos-payment-trigger")) {
        switch (event.key) {
          case "F1":
            // Cash payment
            if (onCashPayment) {
              onCashPayment();
              event.preventDefault();
            }
            break;
          case "F2":
            // Card payment
            if (onCardPayment) {
              onCardPayment();
              event.preventDefault();
            }
            break;
          case "F3":
            // Transfer payment
            if (onTransferPayment) {
              onTransferPayment();
              event.preventDefault();
            }
            break;
          case "F4":
            // Other payment
            if (onOtherPayment) {
              onOtherPayment();
              event.preventDefault();
            }
            break;
        }
      }

      // Ctrl+K: Open global search
      if (event.ctrlKey && event.key === "k") {
        if (onOpenSearch) {
          onOpenSearch();
          event.preventDefault();
        }
      }

      // Ctrl+Shift+C: Clear cart
      if (event.ctrlKey && event.shiftKey && event.key === "C") {
        if (onClearCart) {
          onClearCart();
          event.preventDefault();
        }
      }

      // Ctrl+Enter: Complete sale / Open payment dialog
      if (event.ctrlKey && event.key === "Enter") {
        if (isPaymentDialogOpen) {
          if (onCompleteSale) {
            onCompleteSale();
            event.preventDefault();
          }
        } else {
          if (onOpenPaymentDialog) {
            onOpenPaymentDialog();
            event.preventDefault();
          }
        }
      }

      // 1-9: Quick quantity (when product is selected)
      if (!isInput && /^[1-9]$/.test(event.key)) {
        // This could trigger quantity update for selected item
        // Implementation depends on cart state
      }
    },
    [
      disabled,
      isPaymentDialogOpen,
      onCashPayment,
      onCardPayment,
      onTransferPayment,
      onOtherPayment,
      onOpenSearch,
      onCloseDialog,
      onClearCart,
      onCompleteSale,
      onOpenPaymentDialog,
    ],
  );

  // Focus search with keyboard
  const focusSearch = useCallback(() => {
    // Try to focus the most relevant input
    if (customerInputRef?.current) {
      customerInputRef.current.focus();
    } else if (productInputRef?.current) {
      productInputRef.current.focus();
    } else if (searchInputRef?.current) {
      searchInputRef.current.focus();
    }
  }, [customerInputRef, productInputRef, searchInputRef]);

  // Get available shortcuts (for help display)
  const getShortcuts = useCallback((): KeyboardShortcut[] => {
    const shortcuts: KeyboardShortcut[] = [];

    if (onCashPayment) {
      shortcuts.push({
        key: "F1",
        action: onCashPayment,
        description: "Pago en efectivo",
      });
    }
    if (onCardPayment) {
      shortcuts.push({
        key: "F2",
        action: onCardPayment,
        description: "Pago con tarjeta",
      });
    }
    if (onTransferPayment) {
      shortcuts.push({
        key: "F3",
        action: onTransferPayment,
        description: "Transferencia",
      });
    }
    if (onOtherPayment) {
      shortcuts.push({
        key: "F4",
        action: onOtherPayment,
        description: "Otro pago",
      });
    }
    if (onOpenSearch) {
      shortcuts.push({
        key: "Ctrl+K",
        action: onOpenSearch,
        description: "Buscar",
      });
    }
    if (onClearCart) {
      shortcuts.push({
        key: "Ctrl+Shift+C",
        action: onClearCart,
        description: "Limpiar carrito",
      });
    }
    if (onOpenPaymentDialog || onCompleteSale) {
      shortcuts.push({
        key: "Ctrl+Enter",
        action: onOpenPaymentDialog || onCompleteSale || (() => {}),
        description: "Completar venta",
      });
    }
    shortcuts.push({
      key: "Escape",
      action: onCloseDialog || (() => {}),
      description: "Cerrar diálogo",
    });

    return shortcuts;
  }, [
    onCashPayment,
    onCardPayment,
    onTransferPayment,
    onOtherPayment,
    onOpenSearch,
    onClearCart,
    onOpenPaymentDialog,
    onCompleteSale,
    onCloseDialog,
  ]);

  // Set up global keyboard listener
  useEffect(() => {
    window.addEventListener("keydown", handleKeyDown);
    return () => {
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, [handleKeyDown]);

  return {
    focusSearch,
    getShortcuts,
  };
}

/**
 * usePOSPageActions — collates handlers and callbacks for POSPageContent.
 *
 * Extracted from POSPageContent.tsx to reduce component size.
 * Uses usePOS() internally for shared state; accepts local state params.
 */
"use client";

import { useCallback } from "react";
import { toast } from "sonner";

import { appLogger } from '@/lib/logger';

import type { POSProduct } from "../types";
import { usePOS } from "./usePOSProvider";

export interface UsePOSPageActionsParams {
  // Dialogs
  setShowPaymentDialog: (open: boolean) => void;
  setShowPendingBalanceDialog: (open: boolean) => void;
  setShowRefundDialog: (open: boolean) => void;

  // Processing
  setProcessingPayment: (v: boolean) => void;
  setLastProcessedOrder: (v: unknown) => void;
}

export interface UsePOSPageActionsReturn {
  handlePaymentShortcut: (method: string) => void;
  handleSearchShortcut: () => void;
  handleClearCartShortcut: () => void;
  handleCompleteSaleShortcut: () => void;
  handleCloseDialogs: () => void;
  handleProcessPayment: () => Promise<void>;
  handleLoadQuote: (quoteInput: string) => Promise<void>;
  handlePartialPaymentChange: (
    isPartial: boolean,
    amount?: number,
    total?: number,
  ) => void;
  handleProductKeyDown: (
    e: React.KeyboardEvent,
    productResults: POSProduct[],
    selectedProductIndex: number,
    addToCart: (product: POSProduct) => void,
    clearProductSearch: () => void,
    setSelectedProductIndex: (i: number) => void,
  ) => void;
}

export function usePOSPageActions({
  setShowPaymentDialog,
  setShowPendingBalanceDialog,
  setShowRefundDialog,
  setProcessingPayment,
  setLastProcessedOrder,
}: UsePOSPageActionsParams): UsePOSPageActionsReturn {
  void setLastProcessedOrder; // ponytail: kept for API compatibility, used in handleProcessPayment
  const {
    branchId,
    cart,
    customer,
    customerBusinessName,
    setCustomerBusinessName,
    customerRUT,
    setCustomerRUT,
    customerEmail,
    setCustomerEmail,
    customerPhone,
    setCustomerPhone,
    setCustomer,
    addToCart,
    clearCart,
    paymentMethod,
    setPaymentMethod,
    cashReceived,
    paymentTotals,
    resetPayment,
    isPaymentSufficient,
  } = usePOS();

  const handlePaymentShortcut = useCallback(
    (method: string) => {
      if (cart.length === 0) {
        toast.warning("Agregue productos al carrito primero");
        return;
      }
      setPaymentMethod(method as typeof paymentMethod);
      setShowPaymentDialog(true);
    },
    [cart.length, setPaymentMethod, setShowPaymentDialog],
  );

  const handleSearchShortcut = useCallback(() => {
    // Focus handled by ref forwarding — this signals the intent
  }, []);

  const handleClearCartShortcut = useCallback(() => {
    if (cart.length === 0) return;
    clearCart();
    toast.info("Carrito limpiado");
  }, [cart.length, clearCart]);

  const handleCompleteSaleShortcut = useCallback(() => {
    if (cart.length === 0) return;
    setShowPaymentDialog(true);
  }, [cart.length, setShowPaymentDialog]);

  const handleCloseDialogs = useCallback(() => {
    setShowPaymentDialog(false);
    setShowPendingBalanceDialog(false);
    setShowRefundDialog(false);
  }, [setShowPaymentDialog, setShowPendingBalanceDialog, setShowRefundDialog]);

  const handleProcessPayment = useCallback(async () => {
    if (!branchId) {
      toast.error("Seleccione una sucursal");
      return;
    }
    if (cart.length === 0) {
      toast.error("El carrito está vacío");
      return;
    }

    setProcessingPayment(true);

    try {
      const idempotencyKey = `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

      const saleData = {
        customer_id: customer?.id,
        customer_name: customerBusinessName || customer?.name,
        customer_rut: customerRUT || customer?.rut,
        customer_email: customer?.email,
        customer_phone: customer?.phone,
        items: cart.map((item) => ({
          product_id: item.product.id,
          product_name: item.product.name,
          quantity: item.quantity,
          unit_price: item.unitPrice,
        })),
        payment_method: paymentMethod,
        cash_received: cashReceived,
        subtotal: paymentTotals.subtotal,
        discount_amount: 0,
        tax_amount: paymentTotals.taxAmount,
        total: paymentTotals.total,
        branch_id: branchId,
        idempotency_key: idempotencyKey,
      };

      appLogger.info("Processing sale:", saleData);

      // ponytail: mock implementation, replace with real API call when backend ready
      await new Promise((resolve) => setTimeout(resolve, 1000));

      setLastProcessedOrder({
        ...saleData,
        order_number: `ORD-${Date.now()}`,
      });
      toast.success("Venta procesada correctamente");

      clearCart();
      setCustomer(null);
      resetPayment();
      setShowPaymentDialog(false);
    } catch (error) {
      appLogger.error("Payment error:", error);
      toast.error("Error al procesar el pago");
    } finally {
      setProcessingPayment(false);
    }
  }, [
    branchId,
    cart,
    customer,
    customerBusinessName,
    customerRUT,
    paymentMethod,
    cashReceived,
    paymentTotals,
    clearCart,
    setCustomer,
    resetPayment,
    setShowPaymentDialog,
    setProcessingPayment,
    setLastProcessedOrder,
  ]);

  const handleLoadQuote = useCallback(
    async (quoteInput: string) => {
      if (!branchId) {
        toast.error("Seleccione una sucursal");
        return;
      }

      try {
        const isUUID =
          /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
            quoteInput,
          );
        const endpoint = isUUID
          ? `/api/admin/quotes/${quoteInput}/load-to-pos`
          : `/api/admin/quotes?quote_number=${encodeURIComponent(quoteInput)}`;

        const response = await fetch(endpoint, { method: "POST" });

        if (!response.ok) {
          const error = await response.json();
          throw new Error(error.message || "Presupuesto no encontrado");
        }

        const data = await response.json();

        if (data.success && data.data?.items) {
          data.data.items.forEach(
            (item: {
              product_id: string;
              product_name: string;
              quantity: number;
              unit_price: number;
            }) => {
              addToCart({
                id: item.product_id,
                name: item.product_name,
                price: item.unit_price,
              } as POSProduct);
            },
          );

          if (data.data.customer) {
            setCustomer(data.data.customer);
            if (data.data.customer.rut) setCustomerRUT(data.data.customer.rut);
            if (data.data.customer.business_name)
              setCustomerBusinessName(data.data.customer.business_name);
          }

          toast.success("Presupuesto cargado al carrito");
        }
      } catch (error) {
        appLogger.error("Quote load error:", error);
        toast.error(
          error instanceof Error
            ? error.message
            : "Error al cargar presupuesto",
        );
      }
    },
    [branchId, addToCart, setCustomer, setCustomerRUT, setCustomerBusinessName],
  );

  const handlePartialPaymentChange = useCallback(
    (isPartial: boolean, amount?: number, total?: number) => {
      if (isPartial && amount !== undefined) {
        // use provided amount
      } else if (isPartial && total) {
        // Default to 30% minimum
        // ponytail: per-org min-deposit config when needed
      }
    },
    [],
  );

  const handleProductKeyDown = useCallback(
    (
      e: React.KeyboardEvent,
      productResults: POSProduct[],
      selectedProductIndex: number,
      addToCartFn: (product: POSProduct) => void,
      clearProductSearchFn: () => void,
      setSelectedProductIndexFn: (i: number) => void,
    ) => {
      if (e.key === "Enter") {
        e.preventDefault();
        if (selectedProductIndex >= 0 && productResults[selectedProductIndex]) {
          addToCartFn(productResults[selectedProductIndex]);
        } else if (productResults.length > 0) {
          addToCartFn(productResults[0]);
        }
        return;
      }

      if (e.key === "ArrowDown") {
        e.preventDefault();
        setSelectedProductIndexFn(
          selectedProductIndex < productResults.length - 1
            ? selectedProductIndex + 1
            : selectedProductIndex,
        );
        return;
      }

      if (e.key === "ArrowUp") {
        e.preventDefault();
        setSelectedProductIndexFn(
          selectedProductIndex > 0 ? selectedProductIndex - 1 : -1,
        );
        return;
      }

      if (e.key === "Escape") {
        clearProductSearchFn();
        setSelectedProductIndexFn(-1);
      }
    },
    [],
  );

  return {
    handlePaymentShortcut,
    handleSearchShortcut,
    handleClearCartShortcut,
    handleCompleteSaleShortcut,
    handleCloseDialogs,
    handleProcessPayment,
    handleLoadQuote,
    handlePartialPaymentChange,
    handleProductKeyDown,
  };
}

/**
 * usePOSPayment - Hook para gestión de pagos en el POS
 * Maneja métodos de pago, cálculos de vuelto, y pagos parciales
 */

import { useCallback, useMemo, useState } from "react";

import type { POSCartItem,POSPaymentMethod } from "../types";

interface UsePOSPaymentProps {
  cart?: POSCartItem[];
  onPaymentSubmit?: (paymentData: PaymentData) => void;
}

export interface PaymentData {
  method: POSPaymentMethod;
  cashReceived: number;
  change: number;
  depositAmount?: number;
  isPartial?: boolean;
  fiscalReference?: string;
  cardLastFour?: string;
  cardBrand?: string;
  transferReference?: string;
}

export function usePOSPayment({
  cart = [],
  onPaymentSubmit,
}: UsePOSPaymentProps = {}) {
  // Payment method state
  const [paymentMethod, setPaymentMethod] = useState<POSPaymentMethod>("cash");
  const [cashReceived, setCashReceived] = useState(0);
  const [isPartial, setIsPartial] = useState(false);
  const [partialAmount, setPartialAmount] = useState(0);
  const [fiscalReference, setFiscalReference] = useState("");
  const [cardLastFour, setCardLastFour] = useState("");
  const [cardBrand, setCardBrand] = useState("");
  const [transferReference, setTransferReference] = useState("");

  // Calculate totals from cart
  const totals = useMemo(() => {
    const taxRate = 0.19; // IVA 19% Chile

    // Calculate the actual tax amount based on each item's priceIncludesTax flag
    // - If priceIncludesTax is true: the unitPrice already includes IVA, extract it (tax = price * 19 / 119)
    // - If priceIncludesTax is false: the unitPrice is without tax, calculate it (tax = price * 19 / 100)
    let taxAmount = 0;
    let totalBeforeTax = 0;

    for (const item of cart) {
      const itemSubtotal = item.unitPrice * item.quantity;

      if (item.priceIncludesTax) {
        // Price already includes tax - extract the IVA portion for display
        const extractedTax = (itemSubtotal * taxRate) / (1 + taxRate);
        taxAmount += extractedTax;
        // The base price (without tax) is the subtotal minus extracted tax
        totalBeforeTax += itemSubtotal - extractedTax;
      } else {
        // Price doesn't include tax - calculate IVA on top
        taxAmount += itemSubtotal * taxRate;
        totalBeforeTax += itemSubtotal;
      }
    }

    // Subtotal is the sum of base prices (without tax)
    const subtotal = Math.round(totalBeforeTax);
    // Total is what the customer pays (subtotal + tax for items without included tax)
    const total = Math.round(subtotal + taxAmount);

    return {
      subtotal,
      taxAmount: Math.round(taxAmount),
      total,
    };
  }, [cart]);

  // Calculate change
  const change = useMemo(() => {
    return Math.max(0, cashReceived - totals.total);
  }, [cashReceived, totals.total]);

  // Calculate minimum deposit (30% by default)
  const minDeposit = useMemo(() => {
    return totals.total * 0.3;
  }, [totals.total]);

  // Check if payment is sufficient - depends on payment method
  const isPaymentSufficient = useMemo(() => {
    // For cash payments, need to check cash received
    if (paymentMethod === "cash") {
      if (isPartial) {
        return partialAmount >= minDeposit;
      }
      return cashReceived >= totals.total;
    }
    // For non-cash payments (card, transfer, etc.), payment is always sufficient
    // because they don't use the cash input
    return true;
  }, [
    cashReceived,
    partialAmount,
    isPartial,
    totals.total,
    minDeposit,
    paymentMethod,
  ]);

  // Effective amount being paid
  const effectivePaymentAmount = useMemo(() => {
    return isPartial ? partialAmount : totals.total;
  }, [isPartial, partialAmount, totals.total]);

  // Effective change
  const effectiveChange = useMemo(() => {
    return Math.max(0, cashReceived - effectivePaymentAmount);
  }, [cashReceived, effectivePaymentAmount]);

  // Reset payment states
  const resetPayment = useCallback(() => {
    setCashReceived(0);
    setIsPartial(false);
    setPartialAmount(0);
    setFiscalReference("");
    setCardLastFour("");
    setCardBrand("");
    setTransferReference("");
  }, []);

  // Handle quick cash amounts
  const handleQuickCash = useCallback((amount: number) => {
    setCashReceived(amount);
  }, []);

  // Quick cash amounts for common values
  const quickCashAmounts = useMemo(() => {
    const total = totals.total;
    return [
      Math.ceil(total / 1000) * 1000, // Round up to nearest 1000
      Math.ceil(total / 5000) * 5000, // Round up to nearest 5000
      Math.ceil(total / 10000) * 10000, // Round up to nearest 10000
      Math.ceil(total / 20000) * 20000, // Round up to nearest 20000
    ].filter((amount, index, self) => self.indexOf(amount) === index); // Remove duplicates
  }, [totals.total]);

  // Handle payment submission
  const handlePayment = useCallback(() => {
    const paymentData: PaymentData = {
      method: paymentMethod,
      cashReceived,
      change: effectiveChange,
      depositAmount: isPartial ? partialAmount : undefined,
      isPartial,
      fiscalReference: fiscalReference || undefined,
      cardLastFour: cardLastFour || undefined,
      cardBrand: cardBrand || undefined,
      transferReference: transferReference || undefined,
    };

    if (!isPaymentSufficient) {
      throw new Error("Monto insuficiente");
    }

    onPaymentSubmit?.(paymentData);
    return paymentData;
  }, [
    paymentMethod,
    cashReceived,
    effectiveChange,
    isPartial,
    partialAmount,
    fiscalReference,
    cardLastFour,
    cardBrand,
    transferReference,
    isPaymentSufficient,
    onPaymentSubmit,
  ]);

  // Validate payment method specific fields
  const validatePayment = useCallback((): string | null => {
    if (paymentMethod === "cash" && cashReceived < totals.total && !isPartial) {
      return "Monto en efectivo insuficiente";
    }
    if (paymentMethod === "debit_card" || paymentMethod === "credit_card") {
      // Card validation if needed
    }
    if (paymentMethod === "transfer" && !transferReference.trim()) {
      return "Ingrese referencia de transferencia";
    }
    return null;
  }, [paymentMethod, cashReceived, totals.total, isPartial, transferReference]);

  return {
    // Payment method
    paymentMethod,
    setPaymentMethod,

    // Cash
    cashReceived,
    setCashReceived,
    change,

    // Partial payment
    isPartial,
    setIsPartial,
    partialAmount,
    setPartialAmount,
    minDeposit,

    // Additional fields
    fiscalReference,
    setFiscalReference,
    cardLastFour,
    setCardLastFour,
    cardBrand,
    setCardBrand,
    transferReference,
    setTransferReference,

    // Totals
    totals,

    // Computed
    isPaymentSufficient,
    effectivePaymentAmount,
    effectiveChange,

    // Quick actions
    handleQuickCash,
    quickCashAmounts,

    // Actions
    resetPayment,
    handlePayment,
    validatePayment,
  };
}

import { useCallback, useState } from "react";

import { type PendingBalanceOrder, posService } from "@/lib/api/services";
import { appLogger } from '@/lib/logger';

export function usePOSPendingBalance(branchId: string | null) {
  const [orders, setOrders] = useState<PendingBalanceOrder[]>([]);
  const [allOrders, setAllOrders] = useState<PendingBalanceOrder[]>([]);
  const [loading, setLoading] = useState(false);

  const fetchOrders = useCallback(
    async (searchTerm?: string) => {
      setLoading(true);
      try {
        const result = await posService.getPendingBalanceOrders(
          searchTerm,
          branchId || undefined,
          500,
        );
        setAllOrders(result || []);
        setOrders(result || []);
      } catch (error: unknown) {
        appLogger.error("Error fetching pending balance orders:", error);
        setOrders([]);
        setAllOrders([]);
      } finally {
        setLoading(false);
      }
    },
    [branchId],
  );

  const filterBySearch = useCallback(
    (searchTerm: string, ordersToFilter: PendingBalanceOrder[] = allOrders) => {
      const term = searchTerm.trim().toLowerCase();
      if (!term) {
        setOrders(ordersToFilter);
        return;
      }
      setOrders(
        ordersToFilter.filter((o) => {
          const name = (o.customer_name || "").toLowerCase();
          const orderNum = (o.order_number || "").toLowerCase();
          const rut = (o.customer_rut || "").toLowerCase();
          return (
            name.includes(term) || orderNum.includes(term) || rut.includes(term)
          );
        }),
      );
    },
    [allOrders],
  );

  return {
    orders,
    allOrders,
    loading,
    fetchOrders,
    filterBySearch,
    setOrders,
  };
}

/**
 * usePOSPrescription - Hook para gestión de recetas y presupuestos en el POS
 * Maneja prescripciones, presupuestos, y datos de lentes
 */

import { useCallback, useEffect, useState } from "react";

import { quoteService } from "@/lib/api/services";
import { appLogger } from '@/lib/logger';

import type { POSCustomer,POSQuote } from "../types";

interface UsePOSPrescriptionProps {
  customer?: POSCustomer | null;
  branchId?: string | null;
  onQuoteSelect?: (quote: POSQuote) => void;
}

export function usePOSPrescription({
  customer,
  branchId,
  onQuoteSelect,
}: UsePOSPrescriptionProps = {}) {
  // States
  const [quotes, setQuotes] = useState<POSQuote[]>([]);
  const [loadingQuotes, setLoadingQuotes] = useState(false);
  const [selectedQuote, setSelectedQuote] = useState<POSQuote | null>(null);
  const [prescriptions, setPrescriptions] = useState<unknown[]>([]);
  const [selectedPrescription, setSelectedPrescription] =
    useState<unknown>(null);
  const [loadingPrescriptions, setLoadingPrescriptions] = useState(false);

  // Fetch quotes when customer changes
  useEffect(() => {
    appLogger.info(
      "[usePOSPrescription] Fetching quotes - customer:",
      customer?.id,
      "branchId:",
      branchId,
    );

    if (!customer?.id || !branchId) {
      appLogger.info(
        "[usePOSPrescription] Skipping - missing customer.id or branchId",
      );
      setQuotes([]);
      return;
    }

    let cancelled = false;
    setLoadingQuotes(true);

    // Fetch quotes with multiple statuses (draft, sent, accepted) - not just "sent"
    // This ensures we show all available quotes for the customer
    const statuses = ["draft", "sent", "accepted"] as const;

    // Use Promise.all to fetch quotes with different statuses
    Promise.all(
      statuses.map((status) =>
        quoteService
          .getQuotes({
            customer_id: customer.id,
            branch_id: branchId,
            status,
          })
          .catch(() => ({ data: [] as never[], pagination: {} })),
      ),
    )
      .then((results) => {
        appLogger.info(
          "[usePOSPrescription] getQuotes results by status:",
          results,
        );
        if (!cancelled) {
          // Combine all quotes from different statuses
          const allQuotes = results.flatMap((r) => r.data || []);

          // Filter out rejected and expired, and remove duplicates by id
          const uniqueQuotes = allQuotes.filter(
            (q, index, self) =>
              q.status !== "rejected" &&
              q.status !== "expired" &&
              self.findIndex((q2) => q2.id === q.id) === index,
          );

          appLogger.info(
            "[usePOSPrescription] All unique active quotes:",
            uniqueQuotes,
          );
          setQuotes(uniqueQuotes);
        }
      })
      .catch((error) => {
        appLogger.error("[usePOSPrescription] Error fetching quotes:", error);
        if (!cancelled) setQuotes([]);
      })
      .finally(() => {
        if (!cancelled) setLoadingQuotes(false);
      });

    return () => {
      cancelled = true;
    };
  }, [customer?.id, branchId]);

  // Fetch prescriptions when customer changes
  useEffect(() => {
    if (!customer?.id || !branchId) {
      setPrescriptions([]);
      return;
    }

    let cancelled = false;
    setLoadingPrescriptions(true);

    // TODO: Replace with actual prescription service call when available
    // For now, we'll use a placeholder
    setPrescriptions([]);
    setLoadingPrescriptions(false);

    return () => {
      cancelled = true;
    };
  }, [customer?.id, branchId]);

  // Select quote
  const handleSelectQuote = useCallback(
    (quote: POSQuote) => {
      setSelectedQuote(quote);
      onQuoteSelect?.(quote);
    },
    [onQuoteSelect],
  );

  // Clear quote selection
  const clearQuote = useCallback(() => {
    setSelectedQuote(null);
    onQuoteSelect?.({} as POSQuote);
  }, [onQuoteSelect]);

  // Select prescription
  const handleSelectPrescription = useCallback((prescription: unknown) => {
    setSelectedPrescription(prescription);
  }, []);

  // Clear prescription selection
  const clearPrescription = useCallback(() => {
    setSelectedPrescription(null);
  }, []);

  // Refresh quotes
  const refreshQuotes = useCallback(async () => {
    if (!customer?.id || !branchId) {
      setQuotes([]);
      return;
    }

    setLoadingQuotes(true);
    try {
      const result = await quoteService.getQuotes({
        customer_id: customer.id,
        branch_id: branchId,
        status: "sent",
      });
      const activeQuotes = (result?.data || []).filter(
        (q) => q.status !== "rejected" && q.status !== "expired",
      );
      setQuotes(activeQuotes);
    } catch (error) {
      appLogger.error("Error refreshing quotes:", error);
    } finally {
      setLoadingQuotes(false);
    }
  }, [customer?.id, branchId]);

  return {
    // Quotes
    quotes,
    loadingQuotes,
    selectedQuote,
    handleSelectQuote,
    clearQuote,

    // Prescriptions
    prescriptions,
    loadingPrescriptions,
    selectedPrescription,
    handleSelectPrescription,
    clearPrescription,

    // Helpers
    hasQuotes: quotes.length > 0,
    hasPrescriptions: prescriptions.length > 0,
    quotesCount: quotes.length,

    // Actions
    refreshQuotes,
  };
}

/**
 * usePOSProducts - Hook para gestión de productos en el POS
 * Maneja búsqueda, código de barras, y resultados
 */

import { useCallback, useEffect, useRef, useState } from "react";

import { searchProducts } from "@/lib/api/services";
import { appLogger } from '@/lib/logger';

import type { POSProduct } from "../types";

interface UsePOSProductsProps {
  branchId?: string | null;
  onProductSelect?: (product: POSProduct) => void;
}

export function usePOSProducts({
  branchId,
  onProductSelect,
}: UsePOSProductsProps = {}) {
  // States
  const [searchTerm, setSearchTerm] = useState("");
  const [results, setResults] = useState<POSProduct[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(-1);
  const [barcode, setBarcode] = useState("");

  // Refs
  const searchInputRef = useRef<HTMLInputElement>(null);
  const suggestionsRef = useRef<HTMLDivElement>(null);
  const debounceRef = useRef<NodeJS.Timeout | null>(null);

  // Search products with debounce
  useEffect(() => {
    if (searchTerm.trim().length < 2) {
      setResults([]);
      setLoading(false);
      return;
    }

    setLoading(true);

    if (debounceRef.current) {
      clearTimeout(debounceRef.current);
    }

    debounceRef.current = setTimeout(async () => {
      try {
        const searchResults = await searchProducts(
          searchTerm,
          branchId || undefined,
        );
        // Map Product to POSProduct
        const mappedResults: POSProduct[] = (searchResults || []).map((p) => ({
          id: p.id,
          name: p.name,
          price: p.price,
          price_includes_tax: p.price_includes_tax,
          inventory_quantity: p.inventory_quantity ?? 0,
          sku: p.sku,
          barcode: p.barcode,
          featured_image: p.featured_image,
          brand: p.brand,
          product_type: p.product_type,
          category: p.category,
        }));
        setResults(mappedResults);
        setSelectedIndex(-1);
      } catch (error) {
        appLogger.error("Error searching products:", error);
        setResults([]);
      } finally {
        setLoading(false);
      }
    }, 300);

    return () => {
      if (debounceRef.current) {
        clearTimeout(debounceRef.current);
      }
    };
  }, [searchTerm, branchId]);

  // Search by barcode (uses search with barcode as query)
  const searchByBarcode = useCallback(
    async (barcodeValue: string) => {
      if (!barcodeValue.trim()) return null;

      try {
        setLoading(true);
        // Search by barcode using searchProducts
        const products = await searchProducts(
          barcodeValue,
          branchId || undefined,
        );
        const found = products.find((p) => p.barcode === barcodeValue);
        if (found) {
          // Map to POSProduct
          const product: POSProduct = {
            id: found.id,
            name: found.name,
            price: found.price,
            price_includes_tax: found.price_includes_tax,
            inventory_quantity: found.inventory_quantity ?? 0,
            sku: found.sku,
            barcode: found.barcode,
            featured_image: found.featured_image,
            brand: found.brand,
            product_type: found.product_type,
            category: found.category,
          };
          onProductSelect?.(product);
          return product;
        }
        return null;
      } catch (error) {
        appLogger.error("Error searching by barcode:", error);
        return null;
      } finally {
        setLoading(false);
      }
    },
    [branchId, onProductSelect],
  );

  // Handle barcode change
  const handleBarcodeChange = useCallback(
    (value: string) => {
      setBarcode(value);
      if (value.endsWith("\n") || value.endsWith("\r")) {
        // Enter pressed in barcode scanner
        const cleanBarcode = value.trim();
        if (cleanBarcode) {
          searchByBarcode(cleanBarcode);
          setBarcode("");
        }
      }
    },
    [searchByBarcode],
  );

  // Handle keyboard navigation
  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === "Enter") {
        e.preventDefault();
        if (selectedIndex >= 0 && results[selectedIndex]) {
          onProductSelect?.(results[selectedIndex]);
          setSearchTerm("");
          setResults([]);
          setSelectedIndex(-1);
        } else if (results.length > 0) {
          onProductSelect?.(results[0]);
          setSearchTerm("");
          setResults([]);
        }
      } else if (e.key === "ArrowDown") {
        e.preventDefault();
        setSelectedIndex((prev) =>
          prev < results.length - 1 ? prev + 1 : prev,
        );
      } else if (e.key === "ArrowUp") {
        e.preventDefault();
        setSelectedIndex((prev) => (prev > 0 ? prev - 1 : -1));
      } else if (e.key === "Escape") {
        setResults([]);
        setSearchTerm("");
        setSelectedIndex(-1);
      }
    },
    [selectedIndex, results, onProductSelect],
  );

  // Select product
  const handleSelectProduct = useCallback(
    (product: POSProduct) => {
      onProductSelect?.(product);
      setSearchTerm("");
      setResults([]);
      setSelectedIndex(-1);
    },
    [onProductSelect],
  );

  // Clear search
  const clearSearch = useCallback(() => {
    setSearchTerm("");
    setResults([]);
    setSelectedIndex(-1);
  }, []);

  // Update search term
  const handleSearchChange = useCallback((value: string) => {
    setSearchTerm(value);
    setSelectedIndex(-1);
  }, []);

  return {
    // States
    searchTerm,
    setSearchTerm: handleSearchChange,
    results,
    loading,
    selectedIndex,
    barcode,

    // Refs
    searchInputRef,
    suggestionsRef,

    // Methods
    handleSelectProduct,
    handleKeyDown,
    handleBarcodeChange,
    searchByBarcode,
    clearSearch,

    // Helpers
    hasResults: results.length > 0,
    isSearching: loading && searchTerm.trim().length >= 2,
  };
}

/**
 * usePOSProvider - Provider component that combines all POS hooks
 * Provides a unified interface for the POS page
 */

import React, { useMemo } from "react";

import { appLogger } from '@/lib/logger';

import type { POSCartItem, POSCustomer } from "../types";
import { POSContext, type POSState,usePOS } from "./posProviderTypes";
import { usePOSCart } from "./usePOSCart";
import { usePOSCashStatus } from "./usePOSCashStatus";
import { usePOSCustomer } from "./usePOSCustomer";
import { type PaymentData,usePOSPayment } from "./usePOSPayment";
import { usePOSPrescription } from "./usePOSPrescription";
import { usePOSProducts } from "./usePOSProducts";

export { usePOS };
export type { POSState };

interface UsePOSProviderProps {
  branchId?: string | null;
  isSuperAdmin?: boolean;
  onSaleComplete?: (order: unknown) => void;
}

export function POSProvider({
  children,
  branchId,
  isSuperAdmin = false,
  onSaleComplete,
}: {
  children: React.ReactNode;
} & UsePOSProviderProps) {
  // Cart hook
  const cartHook = usePOSCart({ cart: [], setCart: () => {} });

  // Create cart state at provider level
  const [cart, setCart] = React.useState<POSCartItem[]>([]);
  const cartWithState = usePOSCart({ cart, setCart });

  // Customer hook
  const customerHook = usePOSCustomer({
    onCustomerSelect: (customer) => {
      // Customer selected
    },
  });

  // Products hook
  const productHook = usePOSProducts({
    branchId,
    onProductSelect: (product) => {
      cartWithState.addToCart(product);
    },
  });

  // Payment hook
  const paymentHook = usePOSPayment({
    cart,
    onPaymentSubmit: async (paymentData: PaymentData) => {
      // This will be called when payment is submitted
      // The actual sale processing happens in the page component
      appLogger.info("Payment submitted:", paymentData);
    },
  });

  // Prescription hook
  const prescriptionHook = usePOSPrescription({
    customer: customerHook.selectedCustomer,
    branchId,
    onQuoteSelect: (quote) => {
      // Load quote items into cart
    },
  });

  // Debug: log when customer changes
  React.useEffect(() => {
    appLogger.info(
      "[usePOSProvider] customerHook.selectedCustomer:",
      customerHook.selectedCustomer,
    );
    appLogger.info("[usePOSProvider] branchId:", branchId);
  }, [customerHook.selectedCustomer, branchId]);

  // Cash status hook
  const cashStatusHook = usePOSCashStatus(
    branchId as string | null,
    isSuperAdmin,
  );

  // Customer setter wrapper - handles both null and customer
  const setCustomerWrapper = (customer: POSCustomer | null) => {
    if (customer) {
      customerHook.handleSelectCustomer(customer);
    } else {
      customerHook.clearCustomer();
    }
  };

  // Complete sale handler
  const completeSale = React.useCallback(async () => {
    if (!branchId) {
      throw new Error("Branch ID is required");
    }

    if (cart.length === 0) {
      throw new Error("Cart is empty");
    }

    // Prepare sale data
    const saleData = {
      customer_id: customerHook.selectedCustomer?.id,
      customer_name:
        customerHook.businessName || customerHook.selectedCustomer?.name,
      customer_rut: customerHook.rut || customerHook.selectedCustomer?.rut,
      customer_email: customerHook.selectedCustomer?.email,
      customer_phone: customerHook.selectedCustomer?.phone,
      items: cart.map((item) => ({
        product_id: item.product.id,
        product_name: item.product.name,
        quantity: item.quantity,
        unit_price: item.unitPrice,
      })),
      payment_method: paymentHook.paymentMethod,
      cash_received: paymentHook.cashReceived,
      subtotal: paymentHook.totals.subtotal,
      discount_amount: 0,
      tax_amount: paymentHook.totals.taxAmount,
      total: paymentHook.totals.total,
      branch_id: branchId,
    };

    // TODO: Call actual API to process sale
    appLogger.info("Processing sale:", saleData);

    // Reset after sale
    setCart([]);
    customerHook.clearCustomer();
    paymentHook.resetPayment();
    prescriptionHook.clearQuote();

    return saleData;
  }, [branchId, cart, customerHook, paymentHook, prescriptionHook]);

  // Memoized value
  const value = useMemo<POSState>(
    () => ({
      // Branch
      branchId: branchId || null,
      isSuperAdmin,

      // Cart
      cart,
      addToCart: cartWithState.addToCart,
      updateCartQuantity: cartWithState.updateQuantity,
      removeFromCart: cartWithState.removeFromCart,
      clearCart: cartWithState.clearCart,

      // Customer
      customer: customerHook.selectedCustomer,
      setCustomer: setCustomerWrapper,
      customerSearchTerm: customerHook.searchTerm,
      setCustomerSearchTerm: customerHook.setSearchTerm,
      customerResults: customerHook.results,
      customerLoading: customerHook.loading,
      customerBusinessName: customerHook.businessName,
      setCustomerBusinessName: customerHook.setBusinessName,
      customerRUT: customerHook.rut,
      setCustomerRUT: customerHook.setRut,
      customerEmail: customerHook.email,
      setCustomerEmail: customerHook.setEmail,
      customerPhone: customerHook.phone,
      setCustomerPhone: customerHook.setPhone,
      clearCustomer: customerHook.clearCustomer,

      // Products
      productSearchTerm: productHook.searchTerm,
      setProductSearchTerm: productHook.setSearchTerm,
      productResults: productHook.results,
      productLoading: productHook.loading,
      handleSelectProduct: productHook.handleSelectProduct,
      clearProductSearch: productHook.clearSearch,

      // Payment
      paymentMethod: paymentHook.paymentMethod,
      setPaymentMethod: paymentHook.setPaymentMethod,
      cashReceived: paymentHook.cashReceived,
      setCashReceived: paymentHook.setCashReceived,
      paymentChange: paymentHook.change,
      isPartialPayment: paymentHook.isPartial,
      setIsPartialPayment: paymentHook.setIsPartial,
      partialAmount: paymentHook.partialAmount,
      setPartialAmount: paymentHook.setPartialAmount,
      paymentTotals: paymentHook.totals,
      isPaymentSufficient: paymentHook.isPaymentSufficient,
      handleQuickCash: paymentHook.handleQuickCash,
      resetPayment: paymentHook.resetPayment,

      // Quotes & Prescriptions
      quotes: prescriptionHook.quotes,
      selectedQuote: prescriptionHook.selectedQuote,
      loadingQuotes: prescriptionHook.loadingQuotes,
      handleSelectQuote: prescriptionHook.handleSelectQuote,
      clearQuote: prescriptionHook.clearQuote,
      prescriptions: prescriptionHook.prescriptions,
      selectedPrescription: prescriptionHook.selectedPrescription,
      loadingPrescriptions: prescriptionHook.loadingPrescriptions,
      refreshQuotes: prescriptionHook.refreshQuotes,

      // Cash register
      isCashOpen: cashStatusHook.isOpen,
      isCashChecking: cashStatusHook.checking,
      refreshCashStatus: cashStatusHook.refresh,

      // Actions
      completeSale,
    }),
    [
      branchId,
      isSuperAdmin,
      cart,
      cartWithState,
      customerHook,
      productHook,
      paymentHook,
      prescriptionHook,
      cashStatusHook,
      completeSale,
    ],
  );

  return <POSContext.Provider value={value}>{children}</POSContext.Provider>;
}

"use client";

import { Pencil } from "lucide-react";
import dynamic from "next/dynamic";

import {
  type PrescriptionDisplayData,
  PrescriptionFullDisplay,
} from "@/components/admin/PrescriptionFullDisplay";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { formatDate } from "@/lib/utils";

const CreatePrescriptionForm = dynamic(
  () => import("@/components/admin/CreatePrescriptionForm"),
  {
    loading: () => (
      <div className="flex items-center justify-center py-8">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-admin-text-primary" />
      </div>
    ),
    ssr: false,
  },
);

interface PrescriptionWithRelations {
  id: string;
  customer_id: string;
  prescription_date: string;
  expiration_date?: string | null;
  prescription_number?: string | null;
  issued_by?: string | null;
  issued_by_license?: string | null;
  od_sphere?: number | null;
  od_cylinder?: number | null;
  od_axis?: number | null;
  od_add?: number | null;
  od_pd?: number | null;
  od_near_pd?: number | null;
  os_sphere?: number | null;
  os_cylinder?: number | null;
  os_axis?: number | null;
  os_add?: number | null;
  os_pd?: number | null;
  os_near_pd?: number | null;
  frame_pd?: number | null;
  height_segmentation?: number | null;
  prescription_type?: string | null;
  lens_type?: string | null;
  lens_material?: string | null;
  prism_od?: string | null;
  prism_os?: string | null;
  tint_od?: string | null;
  tint_os?: string | null;
  coatings?: string[] | null;
  notes?: string | null;
  observations?: string | null;
  recommendations?: string | null;
  is_active?: boolean | null;
  is_current?: boolean | null;
  customer?: {
    id: string;
    first_name?: string | null;
    last_name?: string | null;
    rut?: string | null;
    email?: string | null;
  } | null;
  work_orders_count?: number;
}

interface PrescriptionDialogsProps {
  viewPrescription: PrescriptionWithRelations | null;
  editPrescription: PrescriptionWithRelations | null;
  deletePrescription: PrescriptionWithRelations | null;
  deleting: boolean;
  onViewPrescriptionChange: (p: PrescriptionWithRelations | null) => void;
  onEditPrescriptionChange: (p: PrescriptionWithRelations | null) => void;
  onDeletePrescriptionChange: (p: PrescriptionWithRelations | null) => void;
  onEditFromView: () => void;
  onDelete: () => Promise<void>;
  onFetchPrescriptions: () => void;
}

export function PrescriptionDialogs({
  viewPrescription,
  editPrescription,
  deletePrescription,
  deleting,
  onViewPrescriptionChange,
  onEditPrescriptionChange,
  onDeletePrescriptionChange,
  onEditFromView,
  onDelete,
  onFetchPrescriptions,
}: PrescriptionDialogsProps) {
  return (
    <>
      {/* Ver receta */}
      <Dialog
        open={!!viewPrescription}
        onOpenChange={(open) => !open && onViewPrescriptionChange(null)}
      >
        <DialogContent className="max-w-[calc(100vw-2rem)] sm:max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Receta</DialogTitle>
            <DialogDescription>
              {viewPrescription?.customer &&
                `${viewPrescription.customer.first_name || ""} ${viewPrescription.customer.last_name || ""}`.trim()}
              {viewPrescription?.prescription_number &&
                ` · ${viewPrescription.prescription_number}`}
            </DialogDescription>
          </DialogHeader>
          {viewPrescription && (
            <PrescriptionFullDisplay
              prescription={viewPrescription as PrescriptionDisplayData}
              showCard={false}
              subtitle={
                <span className="text-sm text-admin-text-tertiary">
                  {formatDate(viewPrescription.prescription_date)}
                  {viewPrescription.issued_by &&
                    ` · ${viewPrescription.issued_by}`}
                </span>
              }
            />
          )}
          <DialogFooter className="flex-col-reverse sm:flex-row gap-2">
            <Button
              className="w-full sm:w-auto min-h-[44px] sm:min-h-0"
              variant="outline"
              onClick={() => onViewPrescriptionChange(null)}
            >
              Cerrar
            </Button>
            {viewPrescription && (
              <Button
                className="w-full sm:w-auto min-h-[44px] sm:min-h-0"
                onClick={onEditFromView}
              >
                <Pencil className="h-4 w-4 mr-2" />
                Modificar
              </Button>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Modificar receta */}
      <Dialog
        open={!!editPrescription}
        onOpenChange={(open) => !open && onEditPrescriptionChange(null)}
      >
        <DialogContent className="max-w-[calc(100vw-2rem)] sm:max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Modificar receta</DialogTitle>
            <DialogDescription>
              {editPrescription?.customer &&
                `${editPrescription.customer.first_name || ""} ${editPrescription.customer.last_name || ""}`.trim()}
            </DialogDescription>
          </DialogHeader>
          {editPrescription && (
            <CreatePrescriptionForm
              customerId={editPrescription.customer_id}
              initialData={editPrescription}
              onCancel={() => onEditPrescriptionChange(null)}
              onSuccess={() => {
                onEditPrescriptionChange(null);
                onFetchPrescriptions();
              }}
            />
          )}
        </DialogContent>
      </Dialog>

      {/* Eliminar receta */}
      <Dialog
        open={!!deletePrescription}
        onOpenChange={(open) =>
          !open && !deleting && onDeletePrescriptionChange(null)
        }
      >
        <DialogContent className="max-w-[calc(100vw-2rem)] sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Eliminar receta</DialogTitle>
            <DialogDescription>
              ¿Está seguro de eliminar esta receta?
              {deletePrescription?.customer && (
                <span className="block mt-2 font-medium">
                  {deletePrescription.customer.first_name || ""}{" "}
                  {deletePrescription.customer.last_name || ""} ·{" "}
                  {formatDate(deletePrescription.prescription_date)}
                </span>
              )}
              <span className="block mt-2 text-destructive text-sm">
                Esta acción no se puede deshacer.
              </span>
            </DialogDescription>
          </DialogHeader>
          <DialogFooter className="flex-col-reverse sm:flex-row gap-2">
            <Button
              className="w-full sm:w-auto min-h-[44px] sm:min-h-0"
              disabled={deleting}
              variant="outline"
              onClick={() => onDeletePrescriptionChange(null)}
            >
              Cancelar
            </Button>
            <Button
              className="w-full sm:w-auto min-h-[44px] sm:min-h-0"
              disabled={deleting}
              variant="destructive"
              onClick={onDelete}
            >
              {deleting ? "Eliminando..." : "Eliminar"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

