              <SelectTrigger>
                <SelectValue placeholder="Seleccionar material" />
              </SelectTrigger>
              <SelectContent>
                {(frameMaterials as unknown[]).map((material: unknown) => (
                  <SelectItem key={material.value} value={material.value}>
