                onFieldChange("low_stock_threshold", e.target.value)
              }
            />
            <p className="text-xs text-muted-foreground mt-1">
              Alerta cuando el stock disponible sea menor o igual a este valor.
            </p>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

