  price_includes_tax: boolean;
  category_id: string;
  featured_image: string;
  tags: string[];
  stock_quantity: string;
  low_stock_threshold: string;
  is_featured: boolean;
  status: string;
  product_type: string;
  sku: string;
  barcode: string;
  brand: string;
  manufacturer: string;
  model_number: string;
  short_description: string;
  [key: string]: unknown;
}

interface FrameMeasurements {
  lens_width: string;
  bridge_width: string;
  temple_length: string;
  lens_height: string;
  total_width: string;
}

interface PrescriptionRange {
  sph_min: string;
  sph_max: string;
  cyl_min: string;
  cyl_max: string;
  add_min: string;
  add_max: string;
}

function buildFrameMeasurements(measurements: FrameMeasurements) {
  return measurements.lens_width || measurements.bridge_width || measurements.temple_length
    ? {
        lens_width: measurements.lens_width ? parseInt(measurements.lens_width) : null,
        bridge_width: measurements.bridge_width ? parseInt(measurements.bridge_width) : null,
        temple_length: measurements.temple_length ? parseInt(measurements.temple_length) : null,
        lens_height: measurements.lens_height ? parseInt(measurements.lens_height) : null,
        total_width: measurements.total_width ? parseInt(measurements.total_width) : null,
      }
    : null;
}

function buildPrescriptionRange(prescriptionAvailable: boolean, range: PrescriptionRange) {
  return prescriptionAvailable &&
    (range.sph_min || range.sph_max || range.cyl_min || range.cyl_max || range.add_min || range.add_max)
    ? {
        sph_min: range.sph_min ? parseFloat(range.sph_min) : null,
        sph_max: range.sph_max ? parseFloat(range.sph_max) : null,
        cyl_min: range.cyl_min ? parseFloat(range.cyl_min) : null,
        cyl_max: range.cyl_max ? parseFloat(range.cyl_max) : null,
        add_min: range.add_min ? parseFloat(range.add_min) : null,
        add_max: range.add_max ? parseFloat(range.add_max) : null,
      }
    : null;
}

export async function handleProductSubmit(
  formData: FormData,
  currentBranchId: string | null,
  isSuperAdmin: boolean,
  status: string = "active",
) {
  if (!currentBranchId && !isSuperAdmin) {
    toast.error("Debes seleccionar una sucursal para crear productos");
    return;
  }

  const priceStr = String(formData.price || "").trim();
  const priceValue = priceStr ? parseFloat(priceStr) : NaN;

  if (!priceStr || isNaN(priceValue) || priceValue < 0) {
    toast.error("El precio es requerido y debe ser un número válido mayor o igual a 0");
    return;
  }

  const frameMeasurements = buildFrameMeasurements(formData.frame_measurements as FrameMeasurements);
  const prescriptionRange = buildPrescriptionRange(
    !!formData.prescription_available,
    formData.prescription_range as PrescriptionRange,
  );

  const productData: Record<string, unknown> = {
    name: formData.name,
    slug: formData.slug,
    short_description: formData.short_description || null,
    price: priceValue,
    cost_price: formData.cost_price ? parseFloat(String(formData.cost_price)) : null,
    price_includes_tax: formData.price_includes_tax || false,
    category_id: formData.category_id || null,
    branch_id: currentBranchId,
    stock_quantity: formData.stock_quantity ? parseInt(String(formData.stock_quantity)) : 0,
    low_stock_threshold: formData.low_stock_threshold ? parseInt(String(formData.low_stock_threshold)) : 5,
    status,
    featured_image: formData.featured_image || null,
    tags: formData.tags || [],
    is_featured: formData.is_featured || false,
    published_at: status === "active" ? new Date().toISOString() : null,
    product_type: formData.product_type || "frame",
    sku: formData.sku || null,
    barcode: formData.barcode || null,
    brand: formData.brand || null,
    manufacturer: formData.manufacturer || null,
    model_number: formData.model_number || null,
    frame_type: formData.frame_type || null,
    frame_material: formData.frame_material || null,
    frame_shape: formData.frame_shape || null,
    frame_color: formData.frame_color || null,
    frame_colors: (formData.frame_colors as string[]) || [],
    frame_brand: formData.frame_brand || null,
    frame_model: formData.frame_model || null,
    frame_sku: formData.frame_sku || null,
    frame_gender: formData.frame_gender || null,
    frame_age_group: formData.frame_age_group || null,
    frame_size: formData.frame_size || null,
    frame_features: (formData.frame_features as string[]) || [],
    frame_measurements: frameMeasurements,
    lens_type: formData.lens_type || null,
    lens_material: formData.lens_material || null,
    lens_index: formData.lens_index ? parseFloat(String(formData.lens_index)) : null,
    lens_coatings: (formData.lens_coatings as string[]) || [],
    lens_tint_options: (formData.lens_tint_options as string[]) || [],
    uv_protection: formData.uv_protection || null,
    blue_light_filter: formData.blue_light_filter || false,
    blue_light_filter_percentage: formData.blue_light_filter_percentage
      ? parseInt(String(formData.blue_light_filter_percentage))
      : null,
    photochromic: formData.photochromic || false,
    prescription_available: formData.prescription_available || false,
    prescription_range: prescriptionRange,
    requires_prescription: formData.requires_prescription || false,
    is_customizable: formData.is_customizable || false,
    warranty_months: formData.warranty_months ? parseInt(String(formData.warranty_months)) : null,
    warranty_details: formData.warranty_details || null,
  };

  Object.keys(productData).forEach((key) => {
    const value = productData[key];
    if (value === undefined) {
      delete productData[key];
    } else if (typeof value === "string" && value.trim() === "" && key !== "price") {
      productData[key] = null;
    }
  });

  if (productData.price === null || productData.price === undefined || isNaN(productData.price as number)) {
    toast.error("Error: El precio no es válido. Por favor, verifica el formulario.");
    return;
  }

  await productService.createProduct(productData as unknown as CreateProductData);
  toast.success("Producto creado exitosamente");
}

"use client";

import { AlertTriangle } from "lucide-react";

import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

interface BulkOperationFormProps {
  bulkOperation: string;
  selectedProducts: string[];
  categories: { id: string; name: string }[];
  bulkUpdates: Record<string, unknown>;
  onBulkUpdatesChange: (updates: Record<string, unknown>) => void;
}

export function BulkOperationForm({
  bulkOperation,
  selectedProducts,
  categories,
  bulkUpdates,
  onBulkUpdatesChange,
}: BulkOperationFormProps) {
  switch (bulkOperation) {
    case "update_status":
      return (
        <div className="space-y-4">
          <div>
            <Label htmlFor="status">Nuevo Estado</Label>
            <Select
              onValueChange={(value) =>
                onBulkUpdatesChange({ ...bulkUpdates, status: value })
              }
            >
              <SelectTrigger>
                <SelectValue placeholder="Seleccionar estado" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="active">Activo</SelectItem>
                <SelectItem value="draft">Borrador</SelectItem>
                <SelectItem value="archived">Archivado</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </div>
      );

    case "update_category":
      return (
        <div className="space-y-4">
          <div>
            <Label htmlFor="category">Nueva Categoría</Label>
            <Select
              onValueChange={(value) =>
                onBulkUpdatesChange({ ...bulkUpdates, category_id: value })
              }
            >
              <SelectTrigger>
                <SelectValue placeholder="Seleccionar categoría" />
              </SelectTrigger>
              <SelectContent>
                {categories.map((category) => (
                  <SelectItem key={category.id} value={category.id}>
                    {category.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>
      );

    case "update_pricing":
      return (
        <div className="space-y-4">
          <div>
            <Label htmlFor="adjustment_type">Tipo de Ajuste</Label>
            <Select
              onValueChange={(value) =>
                onBulkUpdatesChange({ ...bulkUpdates, adjustment_type: value })
              }
            >
              <SelectTrigger>
                <SelectValue placeholder="Tipo de ajuste" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="percentage">Porcentaje</SelectItem>
                <SelectItem value="fixed">Monto Fijo</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div>
            <Label htmlFor="price_adjustment">
              Ajuste{" "}
              {bulkUpdates.adjustment_type === "percentage" ? "(%)" : "($)"}
            </Label>
            <Input
              placeholder={
                bulkUpdates.adjustment_type === "percentage"
                  ? "ej: 10 para +10%"
                  : "ej: 500 para +$500"
              }
              step="0.01"
              type="number"
              onChange={(e) =>
                onBulkUpdatesChange({
                  ...bulkUpdates,
                  price_adjustment: parseFloat(e.target.value),
                })
              }
            />
          </div>
        </div>
      );

    case "update_inventory":
      return (
        <div className="space-y-4">
          <div>
            <Label htmlFor="inventory_adjustment_type">Tipo de Ajuste</Label>
            <Select
              onValueChange={(value) =>
                onBulkUpdatesChange({ ...bulkUpdates, adjustment_type: value })
              }
            >
              <SelectTrigger>
                <SelectValue placeholder="Tipo de ajuste" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="set">Establecer cantidad</SelectItem>
                <SelectItem value="add">Agregar/Quitar</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div>
            <Label htmlFor="inventory_adjustment">
              {bulkUpdates.adjustment_type === "set"
                ? "Nueva Cantidad"
                : "Ajuste (+/-)"}
            </Label>
            <Input
              placeholder={
                bulkUpdates.adjustment_type === "set"
                  ? "ej: 50"
                  : "ej: -10 o +20"
              }
              type="number"
              value={(bulkUpdates.inventory_adjustment as string) ?? ""}
              onChange={(e) => {
                const value = e.target.value;
                if (value === "") {
                  onBulkUpdatesChange({
                    ...bulkUpdates,
                    inventory_adjustment: undefined,
                  });
                } else {
                  const numValue = parseInt(value, 10);
                  if (!isNaN(numValue)) {
                    onBulkUpdatesChange({
                      ...bulkUpdates,
                      inventory_adjustment: numValue,
                    });
                  }
                }
              }}
            />
          </div>
        </div>
      );

    case "delete":
      return (
        <div className="space-y-4">
          <div className="flex items-center space-x-2 p-4 bg-red-50 border border-red-200 rounded-lg">
            <AlertTriangle className="h-5 w-5 text-red-600" />
            <div>
              <p className="font-medium text-red-800">
                Confirmar eliminación suave
              </p>
              <p className="text-sm text-red-600">
                Los {selectedProducts.length} productos seleccionados serán
                archivados (eliminación suave). Esta acción se puede deshacer
                cambiando el estado a &quot;Activo&quot;.
              </p>
            </div>
          </div>
        </div>
      );

    case "hard_delete":
      return (
        <div className="space-y-4">
          <div className="flex items-center space-x-2 p-4 bg-red-100 border border-red-300 rounded-lg">
            <AlertTriangle className="h-5 w-5 text-red-700" />
            <div>
              <p className="font-medium text-red-900">
                {"\u26A0\uFE0F"} ELIMINACIÓN PERMANENTE
              </p>
              <p className="text-sm text-red-700 font-medium">
                Los {selectedProducts.length} productos seleccionados serán
                ELIMINADOS PERMANENTEMENTE de la base de datos.
              </p>
              <p className="text-sm text-red-600 mt-2">
                {"\u26A0\uFE0F"} Esta acción NO se puede deshacer. Todos los
                datos del producto se perderán para siempre.
              </p>
            </div>
          </div>
          <div className="p-4 bg-yellow-50 border border-yellow-200 rounded-lg">
            <p className="text-sm text-yellow-800">
              <strong>Recomendación:</strong> Considera usar &quot;Eliminación
              suave&quot; (archivar) en su lugar, que permite recuperar los
              productos si es necesario.
            </p>
          </div>
        </div>
      );

    default:
      return null;
  }
}

"use client";

import { useQueryClient } from "@tanstack/react-query";
import { ArrowLeft, Download, Trash2, Upload } from "lucide-react";
import Link from "next/link";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { useBranch } from "@/hooks/useBranch";
import { extractDataFromResponse } from "@/lib/api/response-helpers";
import type { Product } from "@/lib/api/services";
import { productService } from "@/lib/api/services";
import { appLogger } from '@/lib/logger';

import { BulkActionDialog } from "./_components/BulkActionDialog";
import { BulkFiltersBar } from "./_components/BulkFiltersBar";
import { ImportProductsDialog } from "./ImportProductsDialog";
import { ProductsTable } from "./ProductsTable";

export default function BulkOperationsContent() {
  const { currentBranchId, isSuperAdmin } = useBranch();
  const queryClient = useQueryClient();

  const [products, setProducts] = useState<Product[]>([]);
  const [selectedProducts, setSelectedProducts] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [processing, setProcessing] = useState(false);
  const [categories, setCategories] = useState<{ id: string; name: string }[]>([]);

  // Filters
  const [searchTerm, setSearchTerm] = useState("");
  const [categoryFilter, setCategoryFilter] = useState("all");
  const [statusFilter, setStatusFilter] = useState("all");

  // Bulk operation states
  const [bulkOperation, setBulkOperation] = useState("");
  const [bulkUpdates, setBulkUpdates] = useState<Record<string, unknown>>({});
  const [showBulkDialog, setShowBulkDialog] = useState(false);
  const [showImportDialog, setShowImportDialog] = useState(false);
  const [isDeleteDialog, setIsDeleteDialog] = useState(false);

  useEffect(() => {
    fetchProducts();
    fetchCategories();
  }, [searchTerm, categoryFilter, statusFilter]);

  const fetchProducts = async () => {
    try {
      setLoading(true);
      const result = await productService.getProducts({
        search: searchTerm || undefined,
        category: categoryFilter !== "all" ? categoryFilter : undefined,
        status: statusFilter !== "all" ? statusFilter : undefined,
      });
      setProducts(result.data);
    } catch (error) {
      appLogger.error("Error fetching products:", error);
      toast.error("Error al cargar productos");
    } finally {
      setLoading(false);
    }
  };

  const fetchCategories = async () => {
    try {
      const response = await fetch("/api/categories");
      if (response.ok) {
        const data = await response.json();
        setCategories(extractDataFromResponse(data));
      }
    } catch (error) {
      appLogger.error("Error fetching categories:", error);
    }
  };

  const handleSelectProduct = (productId: string) => {
    setSelectedProducts((prev) =>
      prev.includes(productId)
        ? prev.filter((id) => id !== productId)
        : [...prev, productId],
    );
  };

  const handleSelectAll = () => {
    setSelectedProducts(
      selectedProducts.length === products.length
        ? []
        : products.map((p) => p.id),
    );
  };

  const handleBulkOperation = async () => {
    if (selectedProducts.length === 0) {
      toast.error("Selecciona al menos un producto");
      return;
    }

    if (!bulkOperation) {
      toast.error("Selecciona una operación");
      return;
    }

    // Validate inventory update specific fields
    if (bulkOperation === "update_inventory") {
      if (!bulkUpdates.adjustment_type) {
        toast.error(
          "Selecciona un tipo de ajuste (Establecer cantidad o Agregar/Quitar)",
        );
        return;
      }
      if (
        bulkUpdates.inventory_adjustment === undefined ||
        bulkUpdates.inventory_adjustment === null ||
        isNaN(Number(bulkUpdates.inventory_adjustment))
      ) {
        toast.error("Ingresa un valor válido para el ajuste de inventario");
        return;
      }
    }

    try {
      setProcessing(true);

      const result = await productService.bulkProducts({
        products: selectedProducts.map((id) => ({ id, ...bulkUpdates })),
        action: bulkOperation as "create" | "update" | "delete",
      });

      // Invalidate React Query cache to refresh the products list
      queryClient.invalidateQueries({ queryKey: ["products"] });
      queryClient.invalidateQueries({ queryKey: ["productStats"] });

      toast.success(
        `Operación completada: ${result.success.length} productos afectados`,
      );
      setShowBulkDialog(false);
      setIsDeleteDialog(false);
      setSelectedProducts([]);
      setBulkOperation("");
      setBulkUpdates({});
      fetchProducts();
    } catch (error) {
      appLogger.error("Error performing bulk operation:", error);
      const errorMessage =
        error instanceof Error
          ? error.message
          : "Error al realizar la operación masiva";
      toast.error(errorMessage);
    } finally {
      setProcessing(false);
    }
  };

  const handleExport = async () => {
    try {
      const blob = await productService.exportProducts("csv", {
        category: categoryFilter,
        status: statusFilter,
      });

      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `productos-${new Date().toISOString().split("T")[0]}.csv`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);

      toast.success("Productos exportados exitosamente");
    } catch (error) {
      appLogger.error("Error exporting products:", error);
      toast.error("Error al exportar productos");
    }
  };

  if (loading) {
    return (
      <div className="space-y-6">
        <div className="flex items-center space-x-4">
          <Button size="sm" variant="outline">
            <ArrowLeft className="h-4 w-4" />
          </Button>
          <div>
            <h1 className="text-3xl font-bold text-azul-profundo">
              Operaciones Masivas
            </h1>
            <p className="text-tierra-media">Cargando productos...</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-4">
          <Link href="/admin/products">
            <Button size="sm" variant="outline">
              <ArrowLeft className="h-4 w-4" />
            </Button>
          </Link>
          <div>
            <h1 className="text-3xl font-bold text-azul-profundo">
              Operaciones Masivas
            </h1>
            <p className="text-tierra-media">
              Gestiona múltiples productos de forma eficiente
            </p>
          </div>
        </div>

        <div className="flex space-x-2">
          <Button variant="outline" onClick={handleExport}>
            <Download className="h-4 w-4 mr-2" />
            Exportar CSV
          </Button>

          <Button
            variant="outline"
            onClick={() => setShowImportDialog(true)}
          >
            <Upload className="h-4 w-4 mr-2" />
            Importar CSV
          </Button>
          <ImportProductsDialog
            open={showImportDialog}
            onImportComplete={() => {
              setShowImportDialog(false);
              fetchProducts();
            }}
            onOpenChange={setShowImportDialog}
          />
        </div>
      </div>

      {/* Selection Actions */}
      {selectedProducts.length > 0 && (
        <Card className="border-dorado">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-4">
                <Badge variant="secondary">
                  {selectedProducts.length} productos seleccionados
                </Badge>
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => setSelectedProducts([])}
                >
                  Limpiar selección
                </Button>
              </div>

              <div className="flex space-x-2">
                <Button
                  variant="destructive"
                  onClick={() => {
                    setBulkOperation("delete");
                    setIsDeleteDialog(true);
                    setShowBulkDialog(true);
                  }}
                >
                  <Trash2 className="h-4 w-4 mr-2" />
                  Eliminar
                </Button>

                <BulkActionDialog
                  bulkOperation={bulkOperation}
                  bulkUpdates={bulkUpdates}
                  categories={categories}
                  isDeleteDialog={isDeleteDialog}
                  open={showBulkDialog}
                  processing={processing}
                  selectedProducts={selectedProducts}
                  onBulkOperationChange={(op) => { setIsDeleteDialog(false); setBulkOperation(op); }}
                  onBulkUpdatesChange={setBulkUpdates}
                  onExecute={handleBulkOperation}
                  onOpenChange={(open) => { setShowBulkDialog(open); if (!open) { setIsDeleteDialog(false); setBulkOperation(""); setBulkUpdates({}); } }}
                  onTriggerClick={() => { setIsDeleteDialog(false); setBulkOperation(""); setBulkUpdates({}); }}
                />
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      <BulkFiltersBar
        categories={categories} categoryFilter={categoryFilter} searchTerm={searchTerm}
        statusFilter={statusFilter}
        onCategoryChange={setCategoryFilter} onSearchChange={setSearchTerm} onStatusChange={setStatusFilter}
      />

      <ProductsTable
        products={products}
        selectedProducts={selectedProducts}
        onSelectAll={handleSelectAll}
        onSelectProduct={handleSelectProduct}
      />
    </div>
  );
}

"use client";

import { useRef, useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { productService } from "@/lib/api/services";

interface ImportResult {
  success: boolean;
  summary: {
    total_processed: number;
    created: number;
    updated: number;
    skipped: number;
    errors_count: number;
  };
  results?: {
    errors: string[];
  };
}

interface ImportProductsDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onImportComplete: () => void;
}

export function ImportProductsDialog({
  open,
  onOpenChange,
  onImportComplete,
}: ImportProductsDialogProps) {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [importMode, setImportMode] = useState<"create" | "update" | "skip">(
    "create",
  );
  const [importResults, setImportResults] = useState<ImportResult | null>(null);
  const [processing, setProcessing] = useState(false);

  const handleImport = async (file: File) => {
    if (!file) return;
    try {
      setProcessing(true);
      const result = await productService.importProductsFile(file, importMode);
      setImportResults(result);
      if (result.success) {
        toast.success(
          `Importación completada: ${result.summary.created} creados, ${result.summary.updated} actualizados`,
        );
        onImportComplete();
      } else {
        toast.error("Error en la importación");
      }
    } catch {
      toast.error("Error al importar productos");
    } finally {
      setProcessing(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-[calc(100vw-2rem)] sm:max-w-2xl">
        <DialogHeader>
          <DialogTitle>Importar Productos desde CSV</DialogTitle>
          <DialogDescription>
            Sube un archivo CSV para importar productos masivamente
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4">
          <div>
            <Label htmlFor="import_mode">Modo de Importación</Label>
            <Select
              value={importMode}
              onValueChange={(value) =>
                setImportMode(value as "create" | "update" | "skip")
              }
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="create">
                  Crear - Solo productos nuevos
                </SelectItem>
                <SelectItem value="update">
                  Actualizar - Solo productos existentes
                </SelectItem>
                <SelectItem value="upsert">
                  Crear/Actualizar - Ambos
                </SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div>
            <Label htmlFor="csv_file">Archivo CSV</Label>
            <Input
              accept=".csv"
              disabled={processing}
              ref={fileInputRef}
              type="file"
              onChange={(e) => {
                const file = e.target.files?.[0];
                if (file) handleImport(file);
              }}
            />
            <p className="text-sm text-tierra-media mt-1">
              Formatos soportados: nombre, descripción, precio, stock, estado,
              categoría, etc.
            </p>
          </div>

          {importResults && (
            <div className="mt-4 p-4 border rounded-lg">
              <h4 className="font-medium mb-2">Resultados de Importación</h4>
              <div className="grid grid-cols-2 gap-4 text-sm">
                <div>Procesados: {importResults.summary.total_processed}</div>
                <div>Creados: {importResults.summary.created}</div>
                <div>Actualizados: {importResults.summary.updated}</div>
                <div>Omitidos: {importResults.summary.skipped}</div>
              </div>

              {importResults.results?.errors &&
                importResults.results.errors.length > 0 && (
                  <div className="mt-2">
                    <h5 className="font-medium text-red-600">Errores:</h5>
                    <ul className="text-sm text-red-600 list-disc list-inside">
                      {importResults.results.errors
                        .slice(0, 5)
                        .map((error, index) => (
                          <li key={index}>{error}</li>
                        ))}
                      {importResults.results.errors.length > 5 && (
                        <li>
                          ... y {importResults.results.errors.length - 5} más
                        </li>
                      )}
                    </ul>
                  </div>
                )}
            </div>
          )}
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cerrar
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { AlertTriangle, Edit, Eye, Package } from "lucide-react";
import Link from "next/link";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import type { Product } from "@/lib/api/services";
import { formatCurrency, formatDate } from "@/lib/utils";

interface ProductsTableProps {
  products: Product[];
  selectedProducts: string[];
  onSelectProduct: (productId: string) => void;
  onSelectAll: () => void;
}

function getStatusBadge(status: string) {
  const config: Record<
    string,
    {
      variant: "default" | "secondary" | "outline" | "destructive";
      label: string;
    }
  > = {
    active: { variant: "default", label: "Activo" },
    draft: { variant: "secondary", label: "Borrador" },
    archived: { variant: "outline", label: "Archivado" },
  };
  const statusConfig = config[status] || config["draft"];
  return <Badge variant={statusConfig.variant}>{statusConfig.label}</Badge>;
}

export function ProductsTable({
  products,
  selectedProducts,
  onSelectProduct,
  onSelectAll,
}: ProductsTableProps) {
  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center justify-between">
          <div className="flex items-center">
            <Package className="h-5 w-5 mr-2" />
            Productos ({products.length})
          </div>
          <div className="flex items-center space-x-2">
            <input
              checked={
                selectedProducts.length === products.length &&
                products.length > 0
              }
              className="rounded border-gray-300"
              type="checkbox"
              onChange={onSelectAll}
            />
            <span className="text-sm text-tierra-media">
              Seleccionar todos
            </span>
          </div>
        </CardTitle>
      </CardHeader>
      <CardContent>
        {products.length === 0 ? (
          <div className="text-center py-12">
            <Package className="h-12 w-12 text-tierra-media mx-auto mb-4" />
            <h3 className="text-lg font-semibold text-azul-profundo mb-2">
              No se encontraron productos
            </h3>
            <p className="text-tierra-media">
              Ajusta los filtros o agrega nuevos productos.
            </p>
          </div>
        ) : (
          <div className="overflow-x-auto -mx-4 px-4 md:mx-0 md:px-0">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="w-12">
                    <input
                      checked={
                        selectedProducts.length === products.length &&
                        products.length > 0
                      }
                      className="rounded border-gray-300"
                      type="checkbox"
                      onChange={onSelectAll}
                    />
                  </TableHead>
                  <TableHead>Producto</TableHead>
                  <TableHead>Categoría</TableHead>
                  <TableHead>Precio</TableHead>
                  <TableHead>Stock</TableHead>
                  <TableHead>Estado</TableHead>
                  <TableHead>Fecha</TableHead>
                  <TableHead>Acciones</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {products.map((product) => (
                  <TableRow key={product.id}>
                    <TableCell>
                      <input
                        checked={selectedProducts.includes(product.id)}
                        className="rounded border-gray-300"
                        type="checkbox"
                        onChange={() => onSelectProduct(product.id)}
                      />
                    </TableCell>

                    <TableCell>
                      <div>
                        <div className="font-medium">{product.name}</div>
                        <div className="text-sm text-tierra-media">
                          {product.slug}
                        </div>
                        {product.is_featured && (
                          <Badge className="text-xs" variant="outline">
                            Destacado
                          </Badge>
                        )}
                      </div>
                    </TableCell>

                    <TableCell>
                      {product.category ? (
                        <Badge variant="outline">
                          {product.category.name}
                        </Badge>
                      ) : (
                        <span className="text-tierra-media">
                          Sin categoría
                        </span>
                      )}
                    </TableCell>

                    <TableCell className="font-medium">
                      {formatCurrency(product.price)}
                    </TableCell>

                    <TableCell>
                      <div className="flex items-center space-x-2">
                        <span>{product.inventory_quantity}</span>
                        {(product.inventory_quantity ?? 0) <= 5 && (
                          <AlertTriangle className="h-4 w-4 text-red-500" />
                        )}
                      </div>
                    </TableCell>

                    <TableCell>
                      {getStatusBadge(product.status ?? "")}
                    </TableCell>

                    <TableCell className="text-sm text-tierra-media">
                      {formatDate(product.created_at, { locale: "es-AR" })}
                    </TableCell>

                    <TableCell>
                      <div className="flex space-x-2">
                        <Link href={`/admin/products/${product.id}`}>
                          <Button size="sm" variant="outline">
                            <Eye className="h-3 w-3" />
                          </Button>
                        </Link>
                        <Link href={`/admin/products/edit/${product.id}`}>
                          <Button size="sm" variant="outline">
                            <Edit className="h-3 w-3" />
                          </Button>
                        </Link>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import { Edit, RefreshCw } from "lucide-react";

import { Button } from "@/components/ui/button";
import {
  Dialog, DialogContent, DialogDescription,
  DialogFooter, DialogHeader, DialogTitle, DialogTrigger,
} from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";

import { BulkOperationForm } from "../BulkOperationForm";

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  isDeleteDialog: boolean;
  selectedProducts: string[];
  categories: { id: string; name: string }[];
  bulkOperation: string;
  bulkUpdates: Record<string, unknown>;
  processing: boolean;
  onBulkOperationChange: (op: string) => void;
  onBulkUpdatesChange: (updates: Record<string, unknown>) => void;
  onExecute: () => void;
  onTriggerClick: () => void;
}

export function BulkActionDialog({
  open, onOpenChange, isDeleteDialog, selectedProducts, categories,
  bulkOperation, bulkUpdates, processing,
  onBulkOperationChange, onBulkUpdatesChange, onExecute, onTriggerClick,
}: Props) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogTrigger asChild>
        <Button onClick={onTriggerClick}>
          <Edit className="h-4 w-4 mr-2" />
          Operaciones Masivas
        </Button>
      </DialogTrigger>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>
            {bulkOperation === "delete" ? "Archivar Productos"
              : bulkOperation === "hard_delete" ? "⚠️ Eliminar Permanentemente"
              : "Operación Masiva"}
          </DialogTitle>
          <DialogDescription>
            {bulkOperation === "delete" ? `Archivar ${selectedProducts.length} productos seleccionados`
              : bulkOperation === "hard_delete" ? `ELIMINAR PERMANENTEMENTE ${selectedProducts.length} productos seleccionados`
              : `Aplicar cambios a ${selectedProducts.length} productos seleccionados`}
          </DialogDescription>
        </DialogHeader>
        <div className="space-y-4">
          {!isDeleteDialog && (
            <div>
              <Label htmlFor="operation">Operación</Label>
              <Select value={bulkOperation} onValueChange={onBulkOperationChange}>
                <SelectTrigger><SelectValue placeholder="Seleccionar operación" /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="update_status">Cambiar Estado</SelectItem>
                  <SelectItem value="update_category">Cambiar Categoría</SelectItem>
                  <SelectItem value="update_pricing">Ajustar Precios</SelectItem>
                  <SelectItem value="update_inventory">Ajustar Inventario</SelectItem>
                  <SelectItem value="duplicate">Duplicar Productos</SelectItem>
                  <SelectItem value="delete">Archivar Productos (Eliminación Suave)</SelectItem>
                  <SelectItem className="text-red-600 font-medium" value="hard_delete">⚠️ Eliminar Permanentemente</SelectItem>
                </SelectContent>
              </Select>
            </div>
          )}
          {bulkOperation && (
            <BulkOperationForm
              bulkOperation={bulkOperation}
              bulkUpdates={bulkUpdates}
              categories={categories}
              selectedProducts={selectedProducts}
              onBulkUpdatesChange={onBulkUpdatesChange}
            />
          )}
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={() => { onOpenChange(false); }}>Cancelar</Button>
          <Button disabled={processing || !bulkOperation}
            variant={bulkOperation === "delete" || bulkOperation === "hard_delete" ? "destructive" : "default"}
            onClick={onExecute}>
            {processing && <RefreshCw className="h-4 w-4 mr-2 animate-spin" />}
            {bulkOperation === "delete" ? "Archivar Productos"
              : bulkOperation === "hard_delete" ? "⚠️ ELIMINAR PERMANENTEMENTE"
              : "Aplicar Cambios"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import {
  AlertTriangle,
  Edit,
  Eye,
  Package,
  RefreshCw,
  Star,
  Trash2,
} from "lucide-react";
import Link from "next/link";
import { memo } from "react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";

import { Product } from "../hooks/useProducts";

interface ProductGridProps {
  products: Product[];
  selectedProducts: string[];
  onSelectProduct: (id: string) => void;
  onDelete: (product: Product) => void;
  formatPrice: (amount: number) => string;
  getStatusBadge: (status: string) => React.ReactNode;
  onRefresh?: () => void;
  isRefreshing?: boolean;
}

function ProductGridComponent({
  products,
  selectedProducts,
  onSelectProduct,
  onDelete,
  formatPrice,
  getStatusBadge,
  onRefresh,
  isRefreshing,
}: ProductGridProps) {
  if (products.length === 0) {
    return (
      <Card className="bg-admin-bg-tertiary shadow-[0_1px_3px_rgba(0,0,0,0.3)]">
        <CardContent className="p-24 text-center">
          <Package className="h-12 w-12 text-admin-text-tertiary mx-auto mb-4 opacity-20" />
          <h3 className="text-sm font-display font-bold text-admin-text-primary uppercase tracking-widest">
            Archivo de Inventario Vacío
          </h3>
          <p className="text-[10px] font-serif italic text-admin-text-tertiary uppercase tracking-wider mt-2">
            No se han encontrado registros que coincidan con los criterios de
            búsqueda
          </p>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-4">
      {onRefresh && (
        <div className="flex justify-end">
          <Button
            className="h-9 px-4 rounded-xl border-admin-border-primary/10 font-display font-bold text-[10px] tracking-widest uppercase"
            disabled={isRefreshing}
            size="sm"
            variant="outline"
            onClick={onRefresh}
          >
            <RefreshCw
              className={`h-4 w-4 mr-2 ${isRefreshing ? "animate-spin" : ""}`}
            />
            Actualizar
          </Button>
        </div>
      )}
      <div className="grid grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-2 sm:gap-4">
        {products.map((product) => {
          const stockQuantity =
            product.total_inventory_quantity !== undefined
              ? product.total_inventory_quantity
              : product.inventory_quantity || 0;
          const p = product as {
            low_stock_threshold?: number;
            total_low_stock_threshold?: number;
          };
          const threshold =
            p.total_low_stock_threshold ?? p.low_stock_threshold ?? 5;
          const isLowStock = stockQuantity <= threshold;
          const hasImage =
            (product as unknown).featured_image ||
            (product as unknown).gallery?.[0];

          return (
            <Card
              className="group relative flex flex-col transition-all duration-300 border border-admin-border-primary/20 bg-admin-bg-tertiary rounded-xl shadow-[0_1px_3px_rgba(0,0,0,0.3)] hover:shadow-lg transition-shadow duration-300 overflow-hidden"
              key={product.id}
            >
              {/* Checkbox - Top Right */}
              <div className="absolute top-4 right-4 z-10 opacity-0 group-hover:opacity-100 transition-opacity">
                <input
                  checked={selectedProducts.includes(product.id)}
                  className="w-4 h-4 rounded-xl border-admin-border-primary/20 cursor-pointer accent-epoch-primary"
                  type="checkbox"
                  onChange={() => onSelectProduct(product.id)}
                  onClick={(e) => e.stopPropagation()}
                />
              </div>

              {/* Featured Badge - Top Left */}
              {(product.featured || product.is_featured) && (
                <div className="absolute top-4 left-4 z-10">
                  <div className="bg-epoch-primary text-white text-[8px] font-display font-bold px-2 py-1 tracking-widest uppercase flex items-center gap-1">
                    <Star className="h-2 w-2 fill-current" />
                    PREMIUM
                  </div>
                </div>
              )}

              {/* Product Image or Placeholder */}
              <div className="relative w-full h-28 sm:h-40 md:h-48 lg:h-56 bg-admin-border-primary/5 overflow-hidden border-b border-admin-border-primary/10 shrink-0">
                {hasImage ? (
                  <img
                    alt={product.name || product.title || "Producto"}
                    className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700 opacity-90 group-hover:opacity-100"
                    src={
                      (product as unknown).featured_image ||
                      (product as unknown).gallery[0]
                    }
                  />
                ) : (
                  <div className="w-full h-full flex items-center justify-center">
                    <Package className="h-20 w-20 text-admin-text-tertiary/30" />
                  </div>
                )}
                {/* Status Badge Overlay */}
                <div className="absolute bottom-4 right-4">
                  <div className="bg-admin-bg-tertiary/95 backdrop-blur-sm px-3 py-1 border border-admin-border-primary/20 shadow-sm">
                    {getStatusBadge(product.status || "active")}
                  </div>
                </div>
              </div>

              <CardHeader className="p-3 sm:p-4 md:p-6 pb-2 space-y-1 bg-transparent">
                {/* Product Type Badge */}
                {product.product_type && product.product_type !== "frame" && (
                  <p className="text-[9px] font-display font-bold uppercase tracking-wider">
                    {product.product_type === "contact_lens" && (
                      <span className="text-blue-600">Lentes de Contacto</span>
                    )}
                    {product.product_type === "accessory" && (
                      <span className="text-green-600">Accesorio</span>
                    )}
                    {product.product_type === "service" && (
                      <span className="text-purple-600">Servicio</span>
                    )}
                    {product.product_type === "lens" && (
                      <span className="text-orange-600">Cristal</span>
                    )}
                  </p>
                )}

                {/* Category Badge */}
                <p className="text-[10px] font-serif italic text-admin-text-tertiary uppercase tracking-wider">
                  {product.categories?.name ||
                    product.category?.name ||
                    (typeof product.category === "string"
                      ? product.category
                      : "") ||
                    "Sin clasificación técnica"}
                </p>

                {/* Product Name */}
                <CardTitle className="text-xs sm:text-sm md:text-lg font-display font-bold text-admin-text-primary tracking-tight line-clamp-2 min-h-[2rem] sm:min-h-[2.5rem] md:min-h-[3.5rem] uppercase">
                  {product.name || product.title}
                </CardTitle>
              </CardHeader>

              <CardContent className="p-3 sm:p-4 md:p-6 pt-0 flex-1 flex flex-col justify-between bg-transparent min-h-0">
                <div className="space-y-2 sm:space-y-4">
                  {/* Price and Stock Section */}
                  <div className="flex items-end justify-between border-t border-admin-border-primary/10 pt-2 sm:pt-4 gap-2">
                    <div className="space-y-0.5 sm:space-y-1 min-w-0">
                      <p className="text-[8px] sm:text-[9px] font-display font-bold text-admin-text-tertiary uppercase tracking-widest">
                        Valor Unitario
                      </p>
                      <p className="text-xs sm:text-base md:text-lg lg:text-2xl font-display font-bold text-epoch-primary tracking-tighter truncate">
                        {formatPrice(product.price || 0)}
                      </p>
                    </div>

                    <div className="text-right space-y-0.5 sm:space-y-1 shrink-0">
                      <p className="text-[8px] sm:text-[9px] font-display font-bold text-admin-text-tertiary uppercase tracking-widest">
                        Existencias
                      </p>
                      <div className="flex items-center justify-end gap-1">
                        <span
                          className={`text-sm sm:text-lg font-display font-bold ${
                            isLowStock
                              ? "text-admin-error"
                              : "text-admin-text-primary"
                          }`}
                        >
                          {stockQuantity}
                        </span>
                        {isLowStock && (
                          <AlertTriangle className="h-3 w-3 sm:h-3.5 sm:w-3.5 text-admin-error animate-pulse" />
                        )}
                      </div>
                      <p className="text-[8px] sm:text-[9px] text-admin-text-tertiary">
                        Umbral: {threshold}
                      </p>
                    </div>
                  </div>

                  {/* Info Labels */}
                  {product.sku && (
                    <p className="text-[8px] sm:text-[9px] font-display font-bold text-admin-text-tertiary uppercase tracking-[0.2em] truncate">
                      REF:{" "}
                      <span className="text-admin-text-secondary ml-1">
                        {product.sku}
                      </span>
                    </p>
                  )}
                </div>

                {/* Action Buttons - fondo claro cuando tarjeta en hover para contraste */}
                <div className="product-grid-actions flex flex-wrap items-center gap-1.5 sm:gap-2 pt-3 sm:pt-4 mt-3 sm:mt-4 border-t border-admin-border-primary/10">
                  <Link
                    className="flex-1"
                    href={`/admin/products/${product.slug}`}
                  >
                    <Button
                      className="product-grid-card-btn w-full h-8 sm:h-9 rounded-lg sm:rounded-xl border-admin-border-primary/20 text-[8px] sm:text-[10px] font-display font-bold tracking-widest uppercase hover:bg-epoch-primary/10 hover:border-epoch-primary/30 text-epoch-primary transition-all"
                      size="sm"
                      variant="outline"
                    >
                      <Eye className="h-3 w-3 sm:h-3.5 sm:w-3.5 sm:mr-2" />
                      <span className="hidden sm:inline">ARCHIVO</span>
                    </Button>
                  </Link>
                  <Link
                    className="flex-1"
                    href={`/admin/products/edit/${product.id}`}
                  >
                    <Button
                      className="product-grid-card-btn w-full h-8 sm:h-9 rounded-lg sm:rounded-xl border-admin-border-primary/20 text-[8px] sm:text-[10px] font-display font-bold tracking-widest uppercase hover:bg-epoch-primary/10 hover:border-epoch-primary/30 text-epoch-primary transition-all"
                      size="sm"
                      variant="outline"
                    >
                      <Edit className="h-3 w-3 sm:h-3.5 sm:w-3.5 sm:mr-2" />
                      <span className="hidden sm:inline">EDITAR</span>
                    </Button>
                  </Link>
                  <Button
                    className="product-grid-card-btn product-grid-card-btn-delete h-8 sm:h-9 px-2 sm:px-4 rounded-lg sm:rounded-xl border-admin-error/30 text-admin-error hover:bg-admin-error/10 hover:border-admin-error/50 transition-all shrink-0"
                    size="sm"
                    variant="outline"
                    onClick={() => onDelete(product)}
                  >
                    <Trash2 className="h-3.5 w-3.5" />
                  </Button>
                </div>
              </CardContent>
            </Card>
          );
        })}
      </div>
    </div>
  );
}

// Memoize ProductGrid to prevent unnecessary re-renders
export default memo(ProductGridComponent);

"use client";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

interface ProductPaginationProps {
  currentPage: number;
  totalPages: number;
  totalProducts: number;
  itemsPerPage: number;
  onPageChange: (page: number) => void;
  onItemsPerPageChange: (items: number) => void;
}

export default function ProductPagination({
  currentPage,
  totalPages,
  totalProducts,
  itemsPerPage,
  onPageChange,
  onItemsPerPageChange,
}: ProductPaginationProps) {
  // Show pagination if there are products or if we have more than 1 page
  if (totalPages <= 1 && totalProducts === 0) {
    return null;
  }

  const startItem = (currentPage - 1) * itemsPerPage + 1;
  const endItem = Math.min(currentPage * itemsPerPage, totalProducts);

  return (
    <Card className="bg-admin-bg-tertiary shadow-[0_1px_3px_rgba(0,0,0,0.3)] hover:shadow-[0_4px_12px_rgba(0,0,0,0.4)]">
      <CardContent className="p-3 sm:p-4">
        <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3">
          <div className="text-xs sm:text-sm text-tierra-media text-center sm:text-left order-2 sm:order-1">
            {startItem} - {endItem} de {totalProducts}
          </div>

          <div className="flex flex-wrap items-center justify-center sm:justify-end gap-2 order-1 sm:order-2">
            <Button
              className="h-8 sm:h-9 text-xs px-2 sm:px-3"
              disabled={currentPage === 1}
              size="sm"
              variant="outline"
              onClick={() => onPageChange(Math.max(1, currentPage - 1))}
            >
              Ant
            </Button>

            <div className="flex items-center gap-0.5 sm:gap-1 flex-wrap justify-center">
              {/* First page */}
              {currentPage > 3 && (
                <>
                  <Button
                    size="sm"
                    variant={currentPage === 1 ? "default" : "outline"}
                    onClick={() => onPageChange(1)}
                  >
                    1
                  </Button>
                  {currentPage > 4 && <span className="px-2">...</span>}
                </>
              )}

              {/* Pages around current */}
              {Array.from({ length: totalPages }, (_, i) => i + 1)
                .filter((page) => {
                  return (
                    page === currentPage ||
                    page === currentPage - 1 ||
                    page === currentPage + 1 ||
                    (page === currentPage - 2 && currentPage <= 3) ||
                    (page === currentPage + 2 && currentPage >= totalPages - 2)
                  );
                })
                .map((page) => (
                  <Button
                    className="h-8 w-8 sm:h-9 sm:w-9 p-0 min-w-0"
                    key={page}
                    size="sm"
                    variant={currentPage === page ? "default" : "outline"}
                    onClick={() => onPageChange(page)}
                  >
                    {page}
                  </Button>
                ))}

              {/* Last page */}
              {currentPage < totalPages - 2 && (
                <>
                  {currentPage < totalPages - 3 && (
                    <span className="px-2">...</span>
                  )}
                  <Button
                    size="sm"
                    variant={currentPage === totalPages ? "default" : "outline"}
                    onClick={() => onPageChange(totalPages)}
                  >
                    {totalPages}
                  </Button>
                </>
              )}
            </div>

            <Button
              className="h-8 sm:h-9 text-xs px-2 sm:px-3"
              disabled={currentPage === totalPages}
              size="sm"
              variant="outline"
              onClick={() =>
                onPageChange(Math.min(totalPages, currentPage + 1))
              }
            >
              Sig
            </Button>

            <Select
              value={itemsPerPage.toString()}
              onValueChange={(value) => {
                onItemsPerPageChange(parseInt(value));
                onPageChange(1);
              }}
            >
              <SelectTrigger className="w-[70px] sm:w-[100px] h-8 sm:h-9 text-xs">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="12">12 / pág</SelectItem>
                <SelectItem value="24">24 / pág</SelectItem>
                <SelectItem value="48">48 / pág</SelectItem>
                <SelectItem value="100">100 / pág</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import { useQueryClient } from "@tanstack/react-query";
import { AlertTriangle, ArrowLeft } from "lucide-react";
import Link from "next/link";
import { useParams, useRouter } from "next/navigation";
import { useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { useBranch } from "@/hooks/useBranch";
import { useProductOptions } from "@/hooks/useProductOptions";

import { ProductBasicInfo } from "./ProductBasicInfo";
import { ProductEditHeader } from "./ProductEditHeader";
import { ProductFrameSpecs } from "./ProductFrameSpecs";
import { ProductImagesSection } from "./ProductImagesSection";
import { ProductInventorySection } from "./ProductInventorySection";
import { ProductLensSpecs } from "./ProductLensSpecs";
import { useProductOptions as useFormattedOptions } from "./productOptions";
import { ProductPricingSection } from "./ProductPricingSection";
import { handleSubmitProduct } from "./productSubmitHandler";
import { ProductWarrantySection } from "./ProductWarrantySection";
import { defaultFormState, type FormState } from "./types";
import { useProductData } from "./useProductData";

export default function EditProductContent() {
  const router = useRouter();
  const params = useParams();
  const productId = params.id as string;
  const { currentBranchId, isSuperAdmin } = useBranch();
  const queryClient = useQueryClient();

  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [categories, setCategories] = useState<unknown[]>([]);
  const { options: productOptions, loading: optionsLoading } =
    useProductOptions();

  const [formData, setFormData] = useState<FormState>(defaultFormState);
  const [hasChanges, setHasChanges] = useState(false);
  const [initialData, setInitialData] = useState<FormState | null>(null);

  const {
    productTypes,
    frameTypes,
    frameMaterials,
    frameShapes,
    frameGenders,
    frameSizes,
    frameFeatures,
    lensTypes,
    lensMaterials,
    lensCoatings,
    uvProtectionLevels,
  } = useFormattedOptions(productOptions, optionsLoading);

  useProductData(
    productId,
    currentBranchId,
    isSuperAdmin,
    setFormData,
    setInitialData,
    setCategories,
    setError,
    setLoading,
  );

  const updateFormData = (updates: Record<string, unknown>) => {
    setFormData((prev) => {
      const newData = { ...prev, ...updates } as FormState;

      if (initialData) {
        const hasFormChanges =
          JSON.stringify(newData) !== JSON.stringify(initialData);
        setHasChanges(hasFormChanges);
      }

      return newData;
    });
  };

  const handleInputChange = (field: string, value: unknown) => {
    updateFormData({
      [field]: value,
    });
  };

  const addToArray = (field: string, value: string) => {
    const currentArray = formData[field as keyof typeof formData] as string[];
    if (!currentArray.includes(value)) {
      updateFormData({
        [field]: [...currentArray, value],
      });
    }
  };

  const removeFromArray = (field: string, value: string) => {
    const currentArray = formData[field as keyof typeof formData] as string[];
    updateFormData({
      [field]: currentArray.filter((item) => item !== value),
    });
  };

  const updateFrameMeasurement = (field: string, value: string) => {
    updateFormData({
      frame_measurements: {
        ...formData.frame_measurements,
        [field]: value,
      },
    });
  };

  const updatePrescriptionRange = (field: string, value: string) => {
    updateFormData({
      prescription_range: {
        ...formData.prescription_range,
        [field]: value,
      },
    });
  };

  const handleSubmit = async (e?: React.FormEvent, status?: string) => {
    void handleSubmitProduct(
      e,
      status,
      formData,
      productId,
      currentBranchId,
      isSuperAdmin,
      queryClient,
      () => {
        toast.success("Producto actualizado exitosamente");
        router.push("/admin/products");
      },
      (msg) => toast.error(msg),
      setSaving,
    );
  };

  if (loading) {
    return (
      <div className="container mx-auto px-4 py-8 max-w-4xl">
        <div className="animate-pulse space-y-6">
          <div className="h-8 bg-gray-200 rounded w-64" />
          <div className="h-96 bg-gray-200 rounded" />
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="container mx-auto px-4 py-8 max-w-4xl">
        <div className="flex items-center gap-3 mb-6">
          <Button asChild size="sm" variant="ghost">
            <Link href="/admin/products">
              <ArrowLeft className="h-4 w-4 mr-2" />
              Volver a Productos
            </Link>
          </Button>
        </div>

        <Card>
          <CardContent className="p-6">
            <div className="text-center">
              <AlertTriangle className="h-12 w-12 text-red-500 mx-auto mb-4" />
              <h3 className="text-lg font-semibold text-red-600 mb-2">
                Error al cargar producto
              </h3>
              <p className="text-gray-600 mb-4">{error}</p>
              <Button onClick={() => window.location.reload()}>
                Reintentar
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="container mx-auto px-3 sm:px-4 py-6 sm:py-8 max-w-4xl min-w-0">
      <ProductEditHeader
        hasChanges={hasChanges}
        name={formData.name}
        saving={saving}
        onSave={handleSubmit}
      />

      <form className="space-y-6 min-w-0" onSubmit={handleSubmit}>
        <ProductBasicInfo
          barcode={formData.barcode}
          brand={formData.brand}
          categories={categories}
          categoryId={formData.category_id}
          description={formData.description}
          manufacturer={formData.manufacturer}
          modelNumber={formData.model_number}
          name={formData.name}
          productType={formData.product_type}
          productTypes={productTypes}
          shortDescription={formData.short_description}
          sku={formData.sku}
          slug={formData.slug}
          status={formData.status}
          onFieldChange={handleInputChange}
        />

        <ProductPricingSection
          price={formData.price}
          priceIncludesTax={formData.price_includes_tax}
          onFieldChange={handleInputChange}
        />

        <ProductInventorySection
          currentBranchId={currentBranchId}
          lowStockThreshold={formData.low_stock_threshold}
          stockQuantity={formData.stock_quantity}
          onFieldChange={handleInputChange}
        />

        <ProductImagesSection
          featuredImage={formData.featured_image}
          onFieldChange={handleInputChange}
        />

        {formData.product_type === "frame" && (
          <ProductFrameSpecs
            frameColor={formData.frame_color}
            frameFeatures={formData.frame_features}
            frameFeaturesOptions={frameFeatures}
            frameGender={formData.frame_gender}
            frameGenders={frameGenders}
            frameMaterial={formData.frame_material}
            frameMaterials={frameMaterials}
            frameMeasurements={formData.frame_measurements}
            frameShape={formData.frame_shape}
            frameShapes={frameShapes}
            frameSize={formData.frame_size}
            frameSizes={frameSizes}
            frameType={formData.frame_type}
            frameTypes={frameTypes}
            onAddToArray={addToArray}
            onFieldChange={handleInputChange}
            onRemoveFromArray={removeFromArray}
            onUpdateFrameMeasurement={updateFrameMeasurement}
          />
        )}

        {formData.product_type === "lens" && (
          <ProductLensSpecs
            blueLightFilter={formData.blue_light_filter}
            blueLightFilterPercentage={formData.blue_light_filter_percentage}
            lensCoatingOptions={lensCoatings}
            lensCoatings={formData.lens_coatings}
            lensIndex={formData.lens_index}
            lensMaterial={formData.lens_material}
            lensMaterials={lensMaterials}
            lensType={formData.lens_type}
            lensTypes={lensTypes}
            photochromic={formData.photochromic}
            prescriptionAvailable={formData.prescription_available}
            prescriptionRange={formData.prescription_range}
            uvProtection={formData.uv_protection}
            uvProtectionLevels={uvProtectionLevels}
            onAddToArray={addToArray}
            onFieldChange={handleInputChange}
            onRemoveFromArray={removeFromArray}
            onUpdatePrescriptionRange={updatePrescriptionRange}
          />
        )}

        <ProductWarrantySection
          isCustomizable={formData.is_customizable}
          requiresPrescription={formData.requires_prescription}
          warrantyDetails={formData.warranty_details}
          warrantyMonths={formData.warranty_months}
          onFieldChange={handleInputChange}
        />
      </form>
    </div>
  );
}

