import type { QueryClient } from "@tanstack/react-query";

import type { UpdateProductData } from "@/lib/api/services";
import { productService } from "@/lib/api/services";
import { appLogger } from '@/lib/logger';

import type { FormState } from "./types";
export async function handleSubmitProduct(
  e: React.FormEvent | undefined,
  status: string | undefined,
  formData: FormState,
  productId: string,
  currentBranchId: string | null | undefined,
  isSuperAdmin: boolean,
  queryClient: QueryClient,
  onSuccess: () => void,
  onError: (msg: string) => void,
  setSaving: (v: boolean) => void,
) {
  if (e && e.preventDefault) e.preventDefault();
  setSaving(true);

  try {
    const frameMeasurements =
      formData.frame_measurements.lens_width ||
      formData.frame_measurements.bridge_width ||
      formData.frame_measurements.temple_length
        ? {
            lens_width: formData.frame_measurements.lens_width
              ? parseInt(formData.frame_measurements.lens_width)
              : null,
            bridge_width: formData.frame_measurements.bridge_width
              ? parseInt(formData.frame_measurements.bridge_width)
              : null,
            temple_length: formData.frame_measurements.temple_length
              ? parseInt(formData.frame_measurements.temple_length)
              : null,
            lens_height: formData.frame_measurements.lens_height
              ? parseInt(formData.frame_measurements.lens_height)
              : null,
            total_width: formData.frame_measurements.total_width
              ? parseInt(formData.frame_measurements.total_width)
              : null,
          }
        : null;

    const prescriptionRange =
      formData.prescription_available &&
      (formData.prescription_range.sph_min ||
        formData.prescription_range.sph_max ||
        formData.prescription_range.cyl_min ||
        formData.prescription_range.cyl_max ||
        formData.prescription_range.add_min ||
        formData.prescription_range.add_max)
        ? {
            sph_min: formData.prescription_range.sph_min
              ? parseFloat(formData.prescription_range.sph_min)
              : null,
            sph_max: formData.prescription_range.sph_max
              ? parseFloat(formData.prescription_range.sph_max)
              : null,
            cyl_min: formData.prescription_range.cyl_min
              ? parseFloat(formData.prescription_range.cyl_min)
              : null,
            cyl_max: formData.prescription_range.cyl_max
              ? parseFloat(formData.prescription_range.cyl_max)
              : null,
            add_min: formData.prescription_range.add_min
              ? parseFloat(formData.prescription_range.add_min)
              : null,
            add_max: formData.prescription_range.add_max
              ? parseFloat(formData.prescription_range.add_max)
              : null,
          }
        : null;

    const isGlobalMode = !currentBranchId || currentBranchId === "global";
    const productData = {
      ...formData,
      status: status || formData.status,
      price: parseFloat(formData.price),
      price_includes_tax: formData.price_includes_tax === true,
      ...(isGlobalMode
        ? {}
        : {
            stock_quantity: formData.stock_quantity
              ? parseInt(String(formData.stock_quantity))
              : 0,
            low_stock_threshold: formData.low_stock_threshold
              ? parseInt(String(formData.low_stock_threshold))
              : 5,
            branch_id: currentBranchId,
          }),
      frame_measurements: frameMeasurements,
      prescription_range: prescriptionRange,
      lens_index: formData.lens_index ? parseFloat(formData.lens_index) : null,
      warranty_months: formData.warranty_months
        ? parseInt(formData.warranty_months)
        : null,
      blue_light_filter_percentage: formData.blue_light_filter_percentage
        ? parseInt(formData.blue_light_filter_percentage)
        : null,
      optical_category: undefined,
      skin_type: undefined,
      benefits: undefined,
      certifications: undefined,
      ingredients: undefined,
      usage_instructions: undefined,
      precautions: undefined,
      package_characteristics: undefined,
    };

    // ponytail: direct cast to UpdateProductData fails due to FormState structural
    // mismatch (string vs number fields). Using double cast to document intent.
    await productService.updateProduct(
      productId,
      productData as unknown as UpdateProductData,
      currentBranchId || (isSuperAdmin ? "global" : undefined),
    );

    queryClient.invalidateQueries({ queryKey: ["products"] });
    queryClient.invalidateQueries({ queryKey: ["productStats"] });

    onSuccess();
  } catch (error) {
    appLogger.error("Error:", error);
    const errorMessage =
      error instanceof Error
        ? error.message
        : "Error al actualizar el producto";
    onError(errorMessage);
  } finally {
    setSaving(false);
  }
}

import { useEffect } from "react";

import type { Category } from "@/app/admin/products/hooks/useCategories";
import { productService } from "@/lib/api/services";
import { appLogger } from '@/lib/logger';

import type { FormState } from "./types";
export function useProductData(
  productId: string | undefined,
  currentBranchId: string | null | undefined,
  isSuperAdmin: boolean,
  setFormData: (data: FormState) => void,
  setInitialData: (data: FormState) => void,
  setCategories: (categories: Category[]) => void,
  setError: (err: string | null) => void,
  setLoading: (v: boolean) => void,
) {
  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);

        const productData = await productService.getProduct(
          productId!,
          currentBranchId || undefined,
        );

        const categoriesResponse = await fetch("/api/categories");
        if (!categoriesResponse.ok) {
          throw new Error("Failed to fetch categories");
        }
        const categoriesData = await categoriesResponse.json();

        const product = productData;

        let stockQuantity = "0";
        let lowStockThreshold = "5";
        if (
          product.product_branch_stock &&
          Array.isArray(product.product_branch_stock) &&
          product.product_branch_stock.length > 0
        ) {
          const stockRecord = product.product_branch_stock[0];
          const stockQty = stockRecord.quantity;
          stockQuantity =
            stockQty !== null && stockQty !== undefined
              ? stockQty.toString()
              : "0";
          lowStockThreshold =
            stockRecord.low_stock_threshold !== null &&
            stockRecord.low_stock_threshold !== undefined
              ? stockRecord.low_stock_threshold.toString()
              : "5";
        } else if (
          product.inventory_quantity !== undefined &&
          product.inventory_quantity !== null
        ) {
          stockQuantity = product.inventory_quantity.toString();
        }

        const transformedFrameMeasurements = {
          lens_width: product.frame_measurements?.lens_width?.toString() || "",
          bridge_width:
            product.frame_measurements?.bridge_width?.toString() || "",
          temple_length:
            product.frame_measurements?.temple_length?.toString() || "",
          lens_height:
            product.frame_measurements?.lens_height?.toString() || "",
          total_width:
            product.frame_measurements?.total_width?.toString() || "",
        };

        const transformedPrescriptionRange = {
          sph_min: product.prescription_range?.sph_min?.toString() || "",
          sph_max: product.prescription_range?.sph_max?.toString() || "",
          cyl_min: product.prescription_range?.cyl_min?.toString() || "",
          cyl_max: product.prescription_range?.cyl_max?.toString() || "",
          add_min: product.prescription_range?.add_min?.toString() || "",
          add_max: product.prescription_range?.add_max?.toString() || "",
        };

        const uvProtectionValue =
          typeof product.uv_protection === "string"
            ? product.uv_protection
            : product.uv_protection
              ? "true"
              : "";

        const initialFormData: FormState = {
          name: product.name || "",
          slug: product.slug || "",
          short_description: product.short_description || "",
          description: product.description || "",
          price: product.price?.toString() || "",
          price_includes_tax: product.price_includes_tax === true,
          category_id: product.category_id || "",
          featured_image: product.featured_image || "",
          gallery: product.gallery || [],
          stock_quantity: stockQuantity,
          low_stock_threshold: lowStockThreshold,
          is_featured: product.is_featured || false,
          status: product.status || "active",
          product_type: product.product_type || "frame",
          sku: product.sku || "",
          barcode: product.barcode || "",
          brand: product.brand || "",
          manufacturer: product.manufacturer || "",
          model_number: product.model_number || "",
          frame_type: product.frame_type || "",
          frame_material: product.frame_material || "",
          frame_shape: product.frame_shape || "",
          frame_color: product.frame_color || "",
          frame_colors: product.frame_colors || [],
          frame_brand: product.frame_brand || "",
          frame_model: product.frame_model || "",
          frame_sku: product.frame_sku || "",
          frame_gender: product.frame_gender || "",
          frame_age_group: product.frame_age_group || "",
          frame_size: product.frame_size || "",
          frame_features: product.frame_features || [],
          frame_measurements: transformedFrameMeasurements,
          lens_type: product.lens_type || "",
          lens_material: product.lens_material || "",
          lens_index: product.lens_index?.toString() || "",
          lens_coatings: product.lens_coatings || [],
          lens_tint_options: product.lens_tint_options || [],
          uv_protection: uvProtectionValue,
          blue_light_filter: product.blue_light_filter || false,
          blue_light_filter_percentage:
            product.blue_light_filter_percentage?.toString() || "",
          photochromic: product.photochromic || false,
          prescription_available: product.prescription_available || false,
          prescription_range: transformedPrescriptionRange,
          requires_prescription: product.requires_prescription || false,
          is_customizable: product.is_customizable || false,
          warranty_months: product.warranty_months?.toString() || "",
          warranty_details: product.warranty_details || "",
        };

        setFormData(initialFormData);
        setInitialData(initialFormData);
        setCategories(categoriesData.categories || []);
        setError(null);
      } catch (err) {
        appLogger.error("Error fetching data:", err);
        setError(err instanceof Error ? err.message : "Unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    if (productId) {
      fetchData();
    }
  }, [productId, currentBranchId, isSuperAdmin]);
}

"use client";

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";

export interface Category {
  id: string;
  name: string;
  slug: string;
  description?: string;
  sort_order?: number | null;
  parent_id?: string | null;
}

const fetchCategories = async (): Promise<Category[]> => {
  const response = await fetch("/api/categories");
  if (!response.ok) {
    throw new Error("Failed to fetch categories");
  }
  const data = await response.json();
  return data.categories || [];
};

export function useCategories() {
  const queryClient = useQueryClient();

  const query = useQuery({
    queryKey: ["categories"],
    queryFn: fetchCategories,
    staleTime: 5 * 60 * 1000, // 5 minutes
  });

  const createMutation = useMutation({
    mutationFn: async (data: {
      name: string;
      slug: string;
      description?: string;
    }) => {
      const response = await fetch("/api/categories", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || "Failed to create category");
      }

      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["categories"] });
      toast.success("Categoría creada exitosamente");
    },
    onError: (error: Error) => {
      toast.error(error.message || "Error al crear categoría");
    },
  });

  const updateMutation = useMutation({
    mutationFn: async ({
      id,
      data,
    }: {
      id: string;
      data: Partial<Category>;
    }) => {
      const response = await fetch(`/api/categories/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || "Failed to update category");
      }

      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["categories"] });
      toast.success("Categoría actualizada exitosamente");
    },
    onError: (error: Error) => {
      toast.error(error.message || "Error al actualizar categoría");
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      const response = await fetch(`/api/categories/${id}`, {
        method: "DELETE",
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || "Failed to delete category");
      }

      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["categories"] });
      toast.success("Categoría eliminada exitosamente");
    },
    onError: (error: Error) => {
      toast.error(error.message || "Error al eliminar categoría");
    },
  });

  return {
    categories: query.data || [],
    isLoading: query.isLoading,
    error: query.error,
    refetch: query.refetch,
    createCategory: createMutation.mutateAsync,
    updateCategory: updateMutation.mutateAsync,
    deleteCategory: deleteMutation.mutateAsync,
    isCreating: createMutation.isPending,
    isUpdating: updateMutation.isPending,
    isDeleting: deleteMutation.isPending,
  };
}

"use client";

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";

import {
  extractDataFromResponse,
  extractPaginationFromResponse,
} from "@/lib/api/response-helpers";
import { getBranchHeader } from "@/lib/utils/branch";

export interface Product {
  id: string;
  name: string;
  slug: string;
  price: number;
  status: string;
  inventory_quantity: number; // Legacy field, deprecated
  total_inventory_quantity?: number; // Stock for current branch
  total_available_quantity?: number; // Available stock (quantity - reserved) for current branch
  total_reserved_quantity?: number; // Reserved stock for current branch
  category?: { name: string };
  categories?: { name: string };
  is_featured: boolean;
  featured?: boolean;
  title?: string;
  created_at: string;
  sku?: string;
  brand?: string;
  barcode?: string;
  product_type?: string; // frame, lens, accessory, service, contact_lens
  contact_lens_family_id?: string; // FK to contact_lens_families
}

interface ProductsResponse {
  products?: Product[];
  data?: Product[];
  pagination?: {
    total: number;
    totalPages: number;
    page?: number;
  };
  total?: number;
  success?: boolean;
  meta?: { pagination?: { total: number; totalPages: number; page: number } };
}

interface FetchProductsParams {
  page: number;
  itemsPerPage: number;
  categoryFilter: string;
  statusFilter: string;
  searchTerm?: string;
  showLowStockOnly?: boolean;
  currentBranchId: string | null;
  isGlobalView: boolean;
  isSuperAdmin: boolean;
}

const fetchProducts = async ({
  page,
  itemsPerPage,
  categoryFilter,
  statusFilter,
  searchTerm,
  showLowStockOnly,
  currentBranchId,
  isGlobalView,
  isSuperAdmin,
}: FetchProductsParams): Promise<ProductsResponse> => {
  const offset = (page - 1) * itemsPerPage;

  const params = new URLSearchParams({
    limit: itemsPerPage.toString(),
    offset: offset.toString(),
  });

  if (statusFilter !== "all") {
    params.append("status", statusFilter);
  } else {
    params.append("include_archived", "true");
  }

  if (categoryFilter !== "all") {
    params.append("category", categoryFilter);
  }

  if (searchTerm && searchTerm.trim()) {
    params.append("search", searchTerm.trim());
  }

  if (showLowStockOnly) {
    params.append("low_stock_only", "true");
  }

  const headers: HeadersInit = {
    "Content-Type": "application/json",
  };

  if (currentBranchId) {
    headers["x-branch-id"] = currentBranchId;
  } else if (isGlobalView && isSuperAdmin) {
    headers["x-branch-id"] = "global";
  }

  const response = await fetch(`/api/admin/products?${params}`, { headers });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`API Error: ${response.status} - ${errorText}`);
  }

  const json = await response.json();
  // Support both legacy { products, pagination } and standardized { success, data, meta }
  return {
    products: extractDataFromResponse<Product>(json) || json.products,
    pagination: extractPaginationFromResponse(json) || json.pagination,
  };
};

export function useProducts(params: FetchProductsParams) {
  const queryClient = useQueryClient();

  const query = useQuery({
    queryKey: [
      "products",
      params.page,
      params.itemsPerPage,
      params.categoryFilter,
      params.statusFilter,
      params.searchTerm,
      params.showLowStockOnly,
      params.currentBranchId,
      params.isGlobalView,
    ],
    queryFn: () => fetchProducts(params),
    staleTime: 5 * 60 * 1000, // 5 minutes
  });

  const createMutation = useMutation({
    mutationFn: async (data: unknown) => {
      const headers: HeadersInit = {
        "Content-Type": "application/json",
        ...getBranchHeader(params.currentBranchId),
      };

      const response = await fetch("/api/admin/products", {
        method: "POST",
        headers,
        body: JSON.stringify(data),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || "Failed to create product");
      }

      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["products"] });
      queryClient.invalidateQueries({ queryKey: ["productStats"] });
      toast.success("Producto creado exitosamente");
    },
    onError: (error: Error) => {
      toast.error(error.message || "Error al crear producto");
    },
  });

  const updateMutation = useMutation({
    mutationFn: async ({ id, data }: { id: string; data: unknown }) => {
      const headers: HeadersInit = {
        "Content-Type": "application/json",
        ...getBranchHeader(params.currentBranchId),
      };

      const response = await fetch(`/api/admin/products/${id}`, {
        method: "PUT",
        headers,
        body: JSON.stringify(data),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || "Failed to update product");
      }

      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["products"] });
      queryClient.invalidateQueries({ queryKey: ["productStats"] });
      toast.success("Producto actualizado exitosamente");
    },
    onError: (error: Error) => {
      toast.error(error.message || "Error al actualizar producto");
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      const headers: HeadersInit = {
        ...getBranchHeader(params.currentBranchId),
      };

      const response = await fetch(`/api/admin/products/${id}`, {
        method: "DELETE",
        headers,
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || "Failed to delete product");
      }

      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["products"] });
      queryClient.invalidateQueries({ queryKey: ["productStats"] });
      toast.success("Producto eliminado exitosamente");
    },
    onError: (error: Error) => {
      toast.error(error.message || "Error al eliminar producto");
    },
  });

  const pagination = query.data?.pagination;
  return {
    products: query.data?.products || [],
    pagination,
    total: pagination?.total ?? query.data?.total ?? 0,
    isLoading: query.isLoading,
    error: query.error,
    refetch: query.refetch,
    createProduct: createMutation.mutateAsync,
    updateProduct: updateMutation.mutateAsync,
    deleteProduct: deleteMutation.mutateAsync,
    isCreating: createMutation.isPending,
    isUpdating: updateMutation.isPending,
    isDeleting: deleteMutation.isPending,
  };
}

"use client";

import { Package, PackagePlus,Plus } from "lucide-react";
import { useRouter, useSearchParams } from "next/navigation";
import { useEffect, useState } from "react";

import ContactLensFamiliesList from "@/components/admin/lenses/ContactLensFamiliesList";
import ContactLensInventoryManager from "@/components/admin/lenses/ContactLensInventoryManager";
import LensFamiliesList from "@/components/admin/lenses/LensFamiliesList";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useBranch } from "@/hooks/useBranch";
import { appLogger } from '@/lib/logger';

import QuickActions from "./components/QuickActions";
import { useProductStats } from "./hooks/useProductStats";
import CategoriesManagementSection from "./sections/CategoriesManagementSection";
import ProductListingSection from "./sections/ProductListingSection";

const VALID_TABS = [
  "products",
  "categories",
  "lens-families",
  "contact-lens-families",
] as const;

// Sub-tabs for Contactología
const VALID_CONTACT_LENS_SUBTABS = ["families", "inventory"] as const;

type ContactLensSubTab = (typeof VALID_CONTACT_LENS_SUBTABS)[number];

export default function ProductsPage() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const { currentBranchId, isSuperAdmin, branches } = useBranch();
  const isGlobalView = !currentBranchId && isSuperAdmin;

  // Tabs management state - read ?tab= from URL on mount
  const tabParam = searchParams.get("tab");
  const isValidTab = VALID_TABS.includes(
    tabParam as (typeof VALID_TABS)[number],
  );
  const initialTab = isValidTab
    ? (tabParam as (typeof VALID_TABS)[number])
    : "products";

  const [activeTab, setActiveTab] = useState<
    "products" | "categories" | "lens-families" | "contact-lens-families"
  >(initialTab);

  // Sub-tab for Contactología (families or inventory)
  const contactLensSubTabParam = searchParams.get("contactLensSubTab");
  const isValidSubTab = VALID_CONTACT_LENS_SUBTABS.includes(
    contactLensSubTabParam as ContactLensSubTab,
  );
  const initialContactLensSubTab: ContactLensSubTab = isValidSubTab
    ? (contactLensSubTabParam as ContactLensSubTab)
    : "families";

  const [contactLensSubTab, setContactLensSubTab] = useState<ContactLensSubTab>(
    initialContactLensSubTab,
  );

  // Contact lens families for inventory manager
  const [contactLensFamilies, setContactLensFamilies] = useState<
    { id: string; name: string; brand: string | null }[]
  >([]);

  useEffect(() => {
    if (tabParam && isValidTab) {
      setActiveTab(tabParam as (typeof VALID_TABS)[number]);
    }
  }, [tabParam, isValidTab]);

  // Load contact lens families for inventory
  useEffect(() => {
    if (currentBranchId) {
      fetch("/api/admin/contact-lens-families")
        .then((res) => res.json())
        .then((data) => {
          setContactLensFamilies(data.data || data.families || []);
        })
        .catch((err) => appLogger.error("Error loading families:", err));
    }
  }, [currentBranchId]);

  const { stats } = useProductStats({
    currentBranchId,
    isGlobalView,
    isSuperAdmin,
  });

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      {/* Header - multi-row layout */}
      <div className="flex flex-col gap-4 sm:gap-6 pb-6 border-b border-admin-border-primary/20">
        <div>
          <h1 className="text-xl sm:text-2xl md:text-4xl font-display font-bold text-admin-text-primary tracking-tight uppercase">
            Control de Inventario
          </h1>
          <p className="text-[9px] sm:text-[10px] font-serif italic text-admin-text-tertiary uppercase tracking-[0.2em] sm:tracking-[0.3em] mt-1">
            Gestión de Catálogo y Registro de Existencias
          </p>
        </div>
        <div className="flex justify-end">
          {activeTab === "products" && (
            <Button
              className="h-10 sm:h-11 px-4 sm:px-8 bg-admin-accent-primary hover:bg-admin-accent-secondary text-[#1A2B23] font-display font-black text-[9px] sm:text-[10px] tracking-[0.2em] uppercase rounded-xl transition-all shadow-premium-sm flex items-center gap-2 border border-admin-accent-secondary/20"
              onClick={() => router.push("/admin/products/add")}
            >
              <Plus className="h-4 w-4 sm:mr-0" />
              Agregar producto
            </Button>
          )}
          {activeTab === "lens-families" && (
            <Button
              className="h-10 sm:h-11 px-4 sm:px-8 bg-admin-accent-primary hover:bg-admin-accent-secondary text-[#1A2B23] font-display font-black text-[9px] sm:text-[10px] tracking-[0.2em] uppercase rounded-xl transition-all shadow-premium-sm flex items-center gap-2 border border-admin-accent-secondary/20"
              onClick={() => router.push("/admin/lens-families/new")}
            >
              <Plus className="h-4 w-4 sm:mr-0" />
              Nueva Familia Óptica
            </Button>
          )}
          {activeTab === "contact-lens-families" && (
            <Button
              className="h-10 sm:h-11 px-4 sm:px-8 bg-admin-accent-primary hover:bg-admin-accent-secondary text-[#1A2B23] font-display font-black text-[9px] sm:text-[10px] tracking-[0.2em] uppercase rounded-xl transition-all shadow-premium-sm flex items-center gap-2 border border-admin-accent-secondary/20"
              onClick={() => router.push("/admin/contact-lens-families/new")}
            >
              <Plus className="h-4 w-4 sm:mr-0" />
              Nueva Familia Contacto
            </Button>
          )}
        </div>
      </div>

      {/* Quick Actions - Comandos de Administración (solo en tab productos) */}
      {activeTab === "products" && (
        <QuickActions
          hasLowStock={stats.lowStockCount > 0}
          lowStockCount={stats.lowStockCount}
          onShowCategories={() =>
            router.replace("/admin/products?tab=categories", {
              scroll: false,
            })
          }
          onShowLowStock={() =>
            router.replace("/admin/products?filter=low_stock", {
              scroll: false,
            })
          }
        />
      )}

      {/* Warning if no branch selected */}
      {!currentBranchId && !isSuperAdmin && (
        <Card className="bg-amber-50 border-amber-200">
          <CardContent className="p-4">
            <div className="flex items-center gap-2">
              <Package className="h-5 w-5 text-amber-600" />
              <p className="text-sm text-amber-800">
                Debes seleccionar una sucursal para ver y gestionar productos.
              </p>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Tabs for Products, Categories, Lens Families, and Contact Lens Families */}
      <Tabs
        className="w-full"
        value={activeTab}
        onValueChange={(value) => {
          const tab = value as (typeof VALID_TABS)[number];
          setActiveTab(tab);
          // Reset sub-tab when leaving contactología
          if (tab !== "contact-lens-families") {
            setContactLensSubTab("families");
          }
          const url =
            tab === "products"
              ? "/admin/products"
              : tab === "contact-lens-families"
                ? `/admin/products?tab=${tab}&contactLensSubTab=${contactLensSubTab}`
                : `/admin/products?tab=${tab}`;
          router.replace(url, { scroll: false });
        }}
      >
        <TabsList className="flex items-center bg-transparent border-b border-admin-border-primary/20 w-full justify-start rounded-xl h-auto p-0 gap-2 sm:gap-4 md:gap-8 overflow-x-auto overflow-y-hidden min-w-0 [scrollbar-width:none] [-ms-overflow-style:none] [&::-webkit-scrollbar]:hidden">
          <TabsTrigger
            className="rounded-xl border-b-2 border-transparent data-[state=active]:border-admin-accent-primary data-[state=active]:bg-transparent bg-transparent text-admin-text-tertiary data-[state=active]:text-admin-text-primary px-2 sm:px-0 pb-3 sm:pb-4 font-display font-bold text-[9px] sm:text-[10px] tracking-[0.15em] sm:tracking-[0.2em] uppercase transition-all shrink-0"
            value="products"
          >
            Productos
          </TabsTrigger>
          <TabsTrigger
            className="rounded-xl border-b-2 border-transparent data-[state=active]:border-admin-accent-primary data-[state=active]:bg-transparent bg-transparent text-admin-text-tertiary data-[state=active]:text-admin-text-primary px-2 sm:px-0 pb-3 sm:pb-4 font-display font-bold text-[9px] sm:text-[10px] tracking-[0.15em] sm:tracking-[0.2em] uppercase transition-all shrink-0"
            value="categories"
          >
            Categorías
          </TabsTrigger>
          <TabsTrigger
            className="rounded-xl border-b-2 border-transparent data-[state=active]:border-admin-accent-primary data-[state=active]:bg-transparent bg-transparent text-admin-text-tertiary data-[state=active]:text-admin-text-primary px-2 sm:px-0 pb-3 sm:pb-4 font-display font-bold text-[9px] sm:text-[10px] tracking-[0.15em] sm:tracking-[0.2em] uppercase transition-all shrink-0"
            value="lens-families"
          >
            Oftálmicos
          </TabsTrigger>
          <TabsTrigger
            className="rounded-xl border-b-2 border-transparent data-[state=active]:border-admin-accent-primary data-[state=active]:bg-transparent bg-transparent text-admin-text-tertiary data-[state=active]:text-admin-text-primary px-2 sm:px-0 pb-3 sm:pb-4 font-display font-bold text-[9px] sm:text-[10px] tracking-[0.15em] sm:tracking-[0.2em] uppercase transition-all shrink-0"
            value="contact-lens-families"
          >
            Contactología
          </TabsTrigger>
        </TabsList>

        <TabsContent className="space-y-6 mt-6" value="products">
          <ProductListingSection
            branches={branches}
            currentBranchId={currentBranchId}
            isGlobalView={isGlobalView}
            isSuperAdmin={isSuperAdmin}
          />
        </TabsContent>

        <TabsContent className="space-y-6 mt-6" value="categories">
          <CategoriesManagementSection />
        </TabsContent>

        <TabsContent className="space-y-6 mt-6" value="lens-families">
          <LensFamiliesList />
        </TabsContent>

        <TabsContent className="space-y-6 mt-6" value="contact-lens-families">
          <div className="space-y-4">
            {/* Sub-tabs for Contactología */}
            <div className="flex gap-2 border-b border-admin-border-primary/20 pb-2">
              <Button
                className="rounded-lg text-xs uppercase tracking-wide"
                size="sm"
                variant={contactLensSubTab === "families" ? "default" : "ghost"}
                onClick={() => {
                  setContactLensSubTab("families");
                  router.replace(
                    "/admin/products?tab=contact-lens-families&contactLensSubTab=families",
                    { scroll: false },
                  );
                }}
              >
                Familias
              </Button>
              <Button
                className="rounded-lg text-xs uppercase tracking-wide"
                size="sm"
                variant={
                  contactLensSubTab === "inventory" ? "default" : "ghost"
                }
                onClick={() => {
                  setContactLensSubTab("inventory");
                  router.replace(
                    "/admin/products?tab=contact-lens-families&contactLensSubTab=inventory",
                    { scroll: false },
                  );
                }}
              >
                <PackagePlus className="h-3 w-3 mr-1" />
                Inventario
              </Button>
            </div>

            {/* Show families or inventory based on sub-tab */}
            {contactLensSubTab === "families" ? (
              <ContactLensFamiliesList />
            ) : (
              <ContactLensInventoryManager
                branchId={currentBranchId}
                families={contactLensFamilies}
              />
            )}
          </div>
        </TabsContent>
      </Tabs>
    </div>
  );
}

"use client";

import { ArrowLeft } from "lucide-react";
import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { appLogger } from '@/lib/logger';

import { AddOptionValueDialog } from "./_components/AddOptionValueDialog";
import { EditOptionValueDialog } from "./_components/EditOptionValueDialog";
import { OptionFieldCard } from "./_components/OptionFieldCard";
import type { OptionField, OptionValue } from "./types";

export default function ProductOptionsContent() {
  const router = useRouter();
  const [loading, setLoading] = useState(true);
  const [fields, setFields] = useState<OptionField[]>([]);
  const [selectedField, setSelectedField] = useState<OptionField | null>(null);
  const [showAddValueDialog, setShowAddValueDialog] = useState(false);
  const [showEditValueDialog, setShowEditValueDialog] = useState(false);
  const [editingValue, setEditingValue] = useState<OptionValue | null>(null);
  const [newValue, setNewValue] = useState({
    value: "",
    label: "",
    is_default: false,
  });
  const [categories] = useState([
    { value: "general", label: "General" },
    { value: "frame", label: "Armazón" },
    { value: "lens", label: "Lente" },
    { value: "accessory", label: "Accesorio" },
  ]);

  useEffect(() => {
    fetchFields();
  }, []);

  const fetchFields = async () => {
    try {
      setLoading(true);
      const response = await fetch(
        "/api/admin/product-options?form_type=product&include_inactive=true",
      );
      const data = await response.json();
      if (response.ok) {
        setFields(data.fields || []);
      } else {
        toast.error(data.error || "Error al cargar opciones");
      }
    } catch (error) {
      appLogger.error("Error fetching fields:", error);
      toast.error("Error al cargar opciones");
    } finally {
      setLoading(false);
    }
  };

  const handleAddValue = async () => {
    if (!selectedField || !newValue.value || !newValue.label) {
      toast.error("Completa todos los campos");
      return;
    }

    try {
      const response = await fetch("/api/admin/product-options", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          type: "value",
          valueData: {
            field_id: selectedField.id,
            value: newValue.value.toLowerCase().replace(/\s+/g, "_"),
            label: newValue.label,
            is_default: newValue.is_default,
            display_order: (selectedField.values?.length || 0) + 1,
          },
        }),
      });

      const data = await response.json();
      if (response.ok) {
        toast.success("Opción agregada exitosamente");
        setShowAddValueDialog(false);
        setNewValue({ value: "", label: "", is_default: false });
        fetchFields();
      } else {
        toast.error(data.error || "Error al agregar opción");
      }
    } catch (error) {
      appLogger.error("Error adding value:", error);
      toast.error("Error al agregar opción");
    }
  };

  const handleEditValue = async () => {
    if (!editingValue || !newValue.label) {
      toast.error("Completa todos los campos");
      return;
    }

    try {
      const response = await fetch("/api/admin/product-options", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          type: "value",
          id: editingValue.id,
          data: {
            label: newValue.label,
            is_default: newValue.is_default,
            is_active: true,
          },
        }),
      });

      const data = await response.json();
      if (response.ok) {
        toast.success("Opción actualizada exitosamente");
        setShowEditValueDialog(false);
        setEditingValue(null);
        setNewValue({ value: "", label: "", is_default: false });
        fetchFields();
      } else {
        toast.error(data.error || "Error al actualizar opción");
      }
    } catch (error) {
      appLogger.error("Error updating value:", error);
      toast.error("Error al actualizar opción");
    }
  };

  const handleDeleteValue = async (value: OptionValue) => {
    if (!confirm(`¿Estás seguro de eliminar "${value.label}"?`)) {
      return;
    }

    try {
      const response = await fetch(
        `/api/admin/product-options?type=value&id=${value.id}`,
        { method: "DELETE" },
      );

      const data = await response.json();
      if (response.ok) {
        toast.success("Opción eliminada exitosamente");
        fetchFields();
      } else {
        toast.error(data.error || "Error al eliminar opción");
      }
    } catch (error) {
      appLogger.error("Error deleting value:", error);
      toast.error("Error al eliminar opción");
    }
  };

  const handleToggleValueActive = async (value: OptionValue) => {
    try {
      const response = await fetch("/api/admin/product-options", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          type: "value",
          id: value.id,
          data: { is_active: !value.is_active },
        }),
      });

      if (response.ok) {
        toast.success(
          value.is_active ? "Opción desactivada" : "Opción activada",
        );
        fetchFields();
      } else {
        toast.error("Error al actualizar opción");
      }
    } catch (error) {
      appLogger.error("Error toggling value:", error);
      toast.error("Error al actualizar opción");
    }
  };

  const openEditDialog = (value: OptionValue) => {
    setEditingValue(value);
    setNewValue({
      value: value.value,
      label: value.label,
      is_default: value.is_default,
    });
    setShowEditValueDialog(true);
  };

  const openAddDialog = (field: OptionField) => {
    setSelectedField(field);
    setNewValue({ value: "", label: "", is_default: false });
    setShowAddValueDialog(true);
  };

  const groupedFields = categories.map((cat) => ({
    ...cat,
    fields: fields.filter((f) => f.field_category === cat.value),
  }));

  if (loading) {
    return (
      <div className="container mx-auto px-4 py-8">
        <div className="animate-pulse space-y-4">
          <div className="h-8 bg-gray-200 rounded w-64" />
          <div className="h-32 bg-gray-200 rounded" />
        </div>
      </div>
    );
  }

  return (
    <div className="container mx-auto px-3 sm:px-4 py-4 sm:py-8 max-w-6xl">
      <div className="flex flex-col sm:flex-row justify-between items-stretch sm:items-center gap-4 mb-4 sm:mb-6">
        <div>
          <h1 className="text-xl sm:text-2xl md:text-3xl font-bold text-admin-text-primary">
            Personalizar Opciones de Productos
          </h1>
        </div>
        <Button
          className="h-10 w-10 sm:h-auto sm:w-auto sm:px-4 shrink-0"
          variant="outline"
          onClick={() => router.back()}
        >
          <ArrowLeft className="h-4 w-4 sm:mr-2" />
          <span className="hidden sm:inline">Volver</span>
        </Button>
      </div>

      <div className="mb-4 sm:mb-6">
        <p className="text-sm text-admin-text-secondary">
          Personaliza las opciones disponibles en los menús desplegables del
          formulario de productos. Puedes agregar, editar, eliminar y
          activar/desactivar opciones.
        </p>
      </div>

      <div className="space-y-4 sm:space-y-6">
        {groupedFields.map((category) => (
          <Card
            className="bg-admin-bg-tertiary overflow-hidden"
            key={category.value}
          >
            <CardHeader className="px-4 sm:px-6 py-4 sm:py-6">
              <CardTitle className="text-base sm:text-lg">
                {category.label}
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4 px-4 sm:px-6 pb-4 sm:pb-6">
              {category.fields.length === 0 ? (
                <p className="text-gray-500 text-sm">
                  No hay campos en esta categoría
                </p>
              ) : (
                category.fields.map((field) => (
                  <OptionFieldCard
                    field={field}
                    key={field.id}
                    onAddValue={openAddDialog}
                    onDeleteValue={handleDeleteValue}
                    onEditValue={openEditDialog}
                    onToggleValue={handleToggleValueActive}
                  />
                ))
              )}
            </CardContent>
          </Card>
        ))}
      </div>

      <AddOptionValueDialog
        newValue={newValue}
        open={showAddValueDialog}
        selectedField={selectedField}
        onAdd={handleAddValue}
        onNewValueChange={setNewValue}
        onOpenChange={setShowAddValueDialog}
      />
      <EditOptionValueDialog
        editingValue={editingValue}
        newValue={newValue}
        open={showEditValueDialog}
        onNewValueChange={setNewValue}
        onOpenChange={setShowEditValueDialog}
        onSave={handleEditValue}
      />
    </div>
  );
}

"use client";

import { Glasses, Layers, Plus, Tag } from "lucide-react";
import { useMemo, useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { appLogger } from '@/lib/logger';

import type { Category } from "../hooks/useCategories";
import { useCategories } from "../hooks/useCategories";
import { CategorySection } from "./_components/_components/CategoryCard";
import { CategoryDialog } from "./_components/_components/CategoryDialog";

const SORT_ORDER_THRESHOLD = 10;

function groupCategories(categories: Category[]) {
  return {
    principales: categories.filter((c) => c.sort_order == null || c.sort_order < SORT_ORDER_THRESHOLD),
    especializadas: categories.filter((c) => c.sort_order != null && c.sort_order >= SORT_ORDER_THRESHOLD),
  };
}

export default function CategoriesManagementSection() {
  const {
    categories,
    isLoading: categoriesLoading,
    createCategory,
    updateCategory,
    deleteCategory,
  } = useCategories();

  const [categoryDialogOpen, setCategoryDialogOpen] = useState(false);
  const [editingCategory, setEditingCategory] = useState<Category | null>(null);
  const [categoryFormData, setCategoryFormData] = useState({
    name: "",
    slug: "",
    description: "",
  });
  const [categoryFormLoading, setCategoryFormLoading] = useState(false);

  const { principales, especializadas } = useMemo(
    () => groupCategories(categories),
    [categories],
  );

  const generateSlug = (name: string) => {
    return name
      .toLowerCase()
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/[^a-z0-9\s-]/g, "")
      .replace(/\s+/g, "-")
      .replace(/-+/g, "-")
      .trim();
  };

  const handleCategoryInputChange = (field: string, value: string) => {
    setCategoryFormData((prev) => ({
      ...prev,
      [field]: value,
    }));

    if (field === "name") {
      setCategoryFormData((prev) => ({
        ...prev,
        name: value,
        slug: generateSlug(value),
      }));
    }
  };

  const openCreateCategoryDialog = () => {
    setEditingCategory(null);
    setCategoryFormData({ name: "", slug: "", description: "" });
    setCategoryDialogOpen(true);
  };

  const openEditCategoryDialog = (category: Category) => {
    setEditingCategory(category);
    setCategoryFormData({
      name: category.name,
      slug: category.slug,
      description: category.description || "",
    });
    setCategoryDialogOpen(true);
  };

  const handleCategorySubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!categoryFormData.name.trim()) {
      toast.error("El nombre de la categoría es requerido");
      return;
    }

    try {
      setCategoryFormLoading(true);

      if (editingCategory) {
        await updateCategory({
          id: editingCategory.id,
          data: categoryFormData,
        });
      } else {
        await createCategory(categoryFormData);
      }

      setCategoryDialogOpen(false);
      setCategoryFormData({ name: "", slug: "", description: "" });
    } catch (error) {
      appLogger.error("Error saving category:", error);
    } finally {
      setCategoryFormLoading(false);
    }
  };

  const handleDeleteCategory = async (category: Category) => {
    if (
      !confirm(
        `¿Estás seguro de que deseas eliminar la categoría "${category.name}"?`,
      )
    ) {
      return;
    }

    try {
      await deleteCategory(category.id);
    } catch (error) {
      appLogger.error("Error deleting category:", error);
    }
  };

  if (categoriesLoading) {
    return (
      <Card className="border border-admin-border-primary/20 bg-admin-bg-tertiary rounded-xl shadow-none overflow-hidden">
        <CardHeader className="p-6 border-b border-admin-border-primary/10">
          <Skeleton className="h-6 w-48" />
          <Skeleton className="h-4 w-64 mt-2" />
        </CardHeader>
        <CardContent className="p-6 space-y-8">
          <div>
            <Skeleton className="h-5 w-40 mb-4" />
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
              {[...Array(6)].map((_, i) => (
                <Skeleton className="h-24 rounded-xl" key={i} />
              ))}
            </div>
          </div>
          <div>
            <Skeleton className="h-5 w-48 mb-4" />
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
              {[...Array(6)].map((_, i) => (
                <Skeleton className="h-24 rounded-xl" key={i} />
              ))}
            </div>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (categories.length === 0) {
    return (
      <Card className="border border-admin-border-primary/20 bg-admin-bg-tertiary rounded-xl shadow-none overflow-hidden">
        <CardHeader className="p-6 border-b border-admin-border-primary/10">
          <h3 className="text-sm font-display font-bold text-admin-text-primary uppercase tracking-[0.15em]">
            Organización de Categorías
          </h3>
          <p className="text-[10px] font-serif italic text-admin-text-tertiary mt-1">
            Estructura tu catálogo en categorías principales y especializadas
          </p>
        </CardHeader>
        <CardContent className="p-12 text-center">
          <Tag className="h-16 w-16 text-admin-text-tertiary mx-auto mb-6 opacity-20" />
          <h4 className="text-sm font-display font-bold text-admin-text-primary uppercase tracking-widest mb-2">
            Sin categorías definidas
          </h4>
          <p className="text-[10px] font-serif italic text-admin-text-tertiary mb-8 max-w-sm mx-auto">
            Crea categorías principales (Marcos, Lentes de sol, Accesorios,
            Servicios) y especializadas (Monofocales, Progresivos, etc.) para
            organizar tu inventario.
          </p>
          <Button
            className="bg-epoch-primary hover:bg-epoch-primary/90 text-white rounded-xl text-[10px] font-display font-bold tracking-widest uppercase px-8 py-4 h-auto"
            onClick={openCreateCategoryDialog}
          >
            <Plus className="h-4 w-4 mr-2" />
            Crear primera categoría
          </Button>
        </CardContent>
      </Card>
    );
  }

  return (
    <>
      <Card className="border border-admin-border-primary/20 bg-admin-bg-tertiary rounded-xl shadow-none overflow-hidden">
        <CardHeader className="bg-admin-bg-tertiary/50 border-b border-admin-border-primary/10 py-4 sm:py-6 px-4 sm:px-6">
          <div className="flex flex-col sm:flex-row justify-between items-stretch sm:items-center gap-4">
            <div className="flex flex-col gap-1">
              <h3 className="text-xs sm:text-sm font-display font-bold text-admin-text-primary uppercase tracking-[0.15em] sm:tracking-[0.2em]">
                Organización de Categorías
              </h3>
              <p className="text-[9px] sm:text-[10px] font-serif italic text-admin-text-tertiary uppercase tracking-widest">
                Estructura visual: principales (productos) y especializadas
                (lentes)
              </p>
            </div>
            <Button
              className="bg-epoch-primary hover:bg-epoch-primary/90 text-white rounded-xl text-[9px] sm:text-[10px] font-display font-bold tracking-widest uppercase px-4 sm:px-6 py-3 sm:py-4 h-auto border-none shadow-premium-sm shrink-0"
              onClick={openCreateCategoryDialog}
            >
              <Plus className="h-4 w-4 sm:mr-2" />
              <span className="hidden sm:inline">Nueva categoría</span>
            </Button>
          </div>
        </CardHeader>
        <CardContent className="p-4 sm:p-6 md:p-8 space-y-10 sm:space-y-12">
          <CategorySection
            categories={principales}
            icon={Layers}
            subtitle="Productos generales: marcos, lentes de sol, accesorios y servicios"
            title="Categorías principales"
            onDelete={handleDeleteCategory}
            onEdit={openEditCategoryDialog}
          />
          <CategorySection
            categories={especializadas}
            icon={Glasses}
            subtitle="Tipos de productos ópticos: lectura, ocupacional, deportivo, lentes de contacto"
            title="Categorías especializadas de lentes"
            onDelete={handleDeleteCategory}
            onEdit={openEditCategoryDialog}
          />
        </CardContent>
      </Card>

      <CategoryDialog
        editingCategory={editingCategory}
        formData={categoryFormData}
        loading={categoryFormLoading}
        open={categoryDialogOpen}
        onFormChange={handleCategoryInputChange}
        onOpenChange={setCategoryDialogOpen}
        onSubmit={handleCategorySubmit}
      />
    </>
  );
}

"use client";

import { useQueryClient } from "@tanstack/react-query";
import { useSearchParams } from "next/navigation";
import { useEffect, useRef, useState } from "react";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";
import { productService } from "@/lib/api/services";
import { appLogger } from '@/lib/logger';
import { formatCurrency } from "@/lib/utils";

import ProductFilters from "../components/ProductFilters";
import ProductList from "../components/ProductList";
import ProductPagination from "../components/ProductPagination";
import ProductStats from "../components/ProductStats";
import { useCategories } from "../hooks/useCategories";
import { useProductFilters } from "../hooks/useProductFilters";
import { useProducts } from "../hooks/useProducts";
import { useProductStats } from "../hooks/useProductStats";
import { ProductDeleteDialog } from "./_components/_components/ProductDeleteDialog";
import { ProductListingErrorState,ProductListingSkeleton } from "./_components/_components/ProductListingStates";
import ProductBulkActions from "./_components/ProductBulkActions";

interface ProductListingSectionProps {
  currentBranchId: string | null;
  isSuperAdmin: boolean;
  isGlobalView: boolean;
  branches: unknown[];
}

export default function ProductListingSection({
  currentBranchId,
  isSuperAdmin,
  isGlobalView,
  branches,
}: ProductListingSectionProps) {
  const queryClient = useQueryClient();

  // View state
  const [viewMode, setViewMode] = useState<"grid" | "table">("grid");
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage, setItemsPerPage] = useState(12);

  // Filters - MUST be declared before any effects that use it
  const { filters, updateFilter, resetFilters, applyFilters } =
    useProductFilters();

  // Load view mode from localStorage
  useEffect(() => {
    const savedViewMode = localStorage.getItem("admin-products-view-mode");
    if (savedViewMode === "grid" || savedViewMode === "table") {
      setViewMode(savedViewMode);
    }
    const savedItemsPerPage = localStorage.getItem(
      "admin-products-items-per-page",
    );
    if (savedItemsPerPage) {
      setItemsPerPage(parseInt(savedItemsPerPage));
    }
  }, []);

  // Categories
  const { categories, isLoading: categoriesLoading } = useCategories();

  // Product stats
  const { stats, isLoading: statsLoading } = useProductStats({
    currentBranchId,
    isGlobalView,
    isSuperAdmin,
  });

  // Products with React Query - NO searchTerm, fetch all for client-side filtering
  const {
    products,
    total,
    isLoading: productsLoading,
    error: productsError,
    refetch: refetchProducts,
  } = useProducts({
    page: 1, // Always fetch from page 1
    itemsPerPage: 1000, // Fetch all products for client-side filtering
    categoryFilter: filters.categoryFilter,
    statusFilter: filters.statusFilter,
    searchTerm: "", // No server-side search
    showLowStockOnly: filters.showLowStockOnly,
    currentBranchId,
    isGlobalView,
    isSuperAdmin,
  });

  // Client-side filtering for search (instant, no reload)
  const filteredProducts = products.filter((product) => {
    // Search filter
    if (filters.searchTerm) {
      const searchLower = filters.searchTerm.toLowerCase();
      if (
        !product.name.toLowerCase().includes(searchLower) &&
        !(product.sku || "").toLowerCase().includes(searchLower) &&
        !(product.brand || "").toLowerCase().includes(searchLower) &&
        !(product.barcode || "").toLowerCase().includes(searchLower)
      ) {
        return false;
      }
    }

    // Product type filter
    if (filters.productTypeFilter !== "all") {
      if (product.product_type !== filters.productTypeFilter) {
        return false;
      }
    }

    return true;
  });

  // Calculate total pages based on filtered results
  const totalPages = Math.ceil(filteredProducts.length / itemsPerPage);

  // Paginate the filtered products
  const paginatedProducts = filteredProducts.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage,
  );

  // Selection for bulk operations
  const [selectedProducts, setSelectedProducts] = useState<string[]>([]);

  // Single product delete
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [productToDelete, setProductToDelete] = useState<{ id: string; name: string } | null>(null);
  const [deleteLoading, setDeleteLoading] = useState(false);

  // URL state: apply filter=low_stock when coming from QuickActions (run once on mount)
  const searchParams = useSearchParams();
  const hasAppliedLowStockFilter = useRef(false);
  useEffect(() => {
    if (
      searchParams.get("filter") === "low_stock" &&
      !hasAppliedLowStockFilter.current
    ) {
      hasAppliedLowStockFilter.current = true;
      updateFilter("showLowStockOnly", true);
      setCurrentPage(1);
    }
  }, [searchParams.get("filter"), updateFilter]);

  // Reset page when filters change (including search)
  useEffect(() => {
    setCurrentPage(1);
  }, [
    filters.searchTerm,
    filters.categoryFilter,
    filters.statusFilter,
    filters.showLowStockOnly,
  ]);

  // Save view mode to localStorage
  const handleViewModeChange = (mode: "grid" | "table") => {
    setViewMode(mode);
    localStorage.setItem("admin-products-view-mode", mode);
  };

  // Save items per page to localStorage
  const handleItemsPerPageChange = (items: number) => {
    setItemsPerPage(items);
    localStorage.setItem("admin-products-items-per-page", items.toString());
    setCurrentPage(1);
  };

  // Selection handlers
  const handleSelectProduct = (productId: string) => {
    setSelectedProducts((prev) =>
      prev.includes(productId)
        ? prev.filter((id) => id !== productId)
        : [...prev, productId],
    );
  };

  const handleSelectAll = () => {
    setSelectedProducts(
      selectedProducts.length === paginatedProducts.length
        ? []
        : paginatedProducts.map((p) => p.id),
    );
  };

  // Single product delete
  const handleDeleteProduct = async () => {
    if (!productToDelete) return;

    try {
      setDeleteLoading(true);
      await productService.deleteProduct(productToDelete.id);
      setDeleteDialogOpen(false);
      setProductToDelete(null);
      toast.success("Producto eliminado exitosamente");
      refetchProducts();
    } catch (error) {
      appLogger.error("Error deleting product:", error);
      toast.error("Error al eliminar el producto");
    } finally {
      setDeleteLoading(false);
    }
  };

  const openDeleteDialog = (product: { id: string; name: string }) => {
    setProductToDelete(product);
    setDeleteDialogOpen(true);
  };

  // Utility functions
  const formatPrice = (price: number | null | undefined): string => {
    return formatCurrency(price || 0);
  };

  const getStatusBadge = (status: string) => {
    const config: Record<string, { variant: "default" | "secondary" | "outline" | "destructive"; label: string }> = {
      active: { variant: "default", label: "Activo" },
      draft: { variant: "secondary", label: "Borrador" },
      archived: { variant: "outline", label: "Archivado" },
    };
    return <Badge variant={(config[status] || config["draft"]).variant}>{(config[status] || config["draft"]).label}</Badge>;
  };

  if (productsLoading && products.length === 0) return <ProductListingSkeleton />;
  if (productsError) return <ProductListingErrorState error={productsError} onRetry={refetchProducts} />;

  // Calculate stats label
  const branchesList = branches as Array<{ id: string; name: string }>;
  const currentBranch = branchesList?.find((b) => b.id === currentBranchId);
  const statsLabel = isGlobalView
    ? "Todas las sucursales"
    : currentBranch
      ? `Sucursal: ${currentBranch.name}`
      : "Sucursal seleccionada";

  const handleRefresh = () => {
    refetchProducts();
    queryClient.invalidateQueries({ queryKey: ["productStats"] });
    toast.success("Datos actualizados");
  };

  return (
    <>
      {/* Stats Cards */}
      <ProductStats
        formatPrice={formatPrice}
        stats={stats}
        statsLabel={statsLabel}
      />

      {/* Search and Filters */}
      <ProductFilters
        categories={categories}
        categoryFilter={filters.categoryFilter}
        productTypeFilter={filters.productTypeFilter}
        searchTerm={filters.searchTerm}
        showLowStockOnly={filters.showLowStockOnly}
        statusFilter={filters.statusFilter}
        viewMode={viewMode}
        onCategoryChange={(category) =>
          updateFilter("categoryFilter", category)
        }
        onLowStockToggle={() =>
          updateFilter("showLowStockOnly", !filters.showLowStockOnly)
        }
        onProductTypeChange={(type) => updateFilter("productTypeFilter", type)}
        onSearchChange={(term) => updateFilter("searchTerm", term)}
        onStatusChange={(status) => updateFilter("statusFilter", status)}
        onViewModeChange={handleViewModeChange}
      />

      {/* Bulk Operations Panel */}
      {selectedProducts.length > 0 && (
        <ProductBulkActions
          categories={categories}
          selectedProducts={selectedProducts}
          onClearSelection={() => {
            setSelectedProducts([]);
            refetchProducts();
          }}
          onSuccess={refetchProducts}
        />
      )}

      {/* Products Display */}
      <ProductList
        formatPrice={formatPrice}
        getStatusBadge={getStatusBadge}
        isRefreshing={productsLoading}
        products={paginatedProducts}
        selectedProducts={selectedProducts}
        viewMode={viewMode}
        onDelete={openDeleteDialog}
        onRefresh={handleRefresh}
        onSelectAll={handleSelectAll}
        onSelectProduct={handleSelectProduct}
      />

      {/* Pagination - Show if there are products or if totalPages > 1 */}
      {(filteredProducts.length > 0 || totalPages > 1) && (
        <ProductPagination
          currentPage={currentPage}
          itemsPerPage={itemsPerPage}
          totalPages={totalPages}
          totalProducts={filteredProducts.length}
          onItemsPerPageChange={handleItemsPerPageChange}
          onPageChange={setCurrentPage}
        />
      )}

      <ProductDeleteDialog
        deleteLoading={deleteLoading}
        open={deleteDialogOpen}
        productToDelete={productToDelete as { id: string; name: string } | null}
        onConfirm={handleDeleteProduct}
        onOpenChange={(open) => { setDeleteDialogOpen(open); if (!open) setProductToDelete(null); }}
      />
    </>
  );
}

"use client";

import { Edit, RefreshCw } from "lucide-react";
import { useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import { bulkProductOperations } from "@/lib/api/services";
import { appLogger } from '@/lib/logger';
import { cn } from "@/lib/utils";

import { BulkOperationFormRenderer } from "./_components/BulkOperationFormRenderer";

interface ProductBulkActionsProps {
  selectedProducts: string[];
  categories: unknown[];
  onClearSelection: () => void;
  onSuccess: () => void;
}

export default function ProductBulkActions({
  selectedProducts,
  categories,
  onClearSelection,
  onSuccess,
}: ProductBulkActionsProps) {
  const [bulkOperation, setBulkOperation] = useState("");
  const [bulkUpdates, setBulkUpdates] = useState<unknown>({});
  const [isDeleteDialog] = useState(false);
  const [processing, setProcessing] = useState(false);
  const [forceDelete, setForceDelete] = useState(false);

  const handleBulkOperation = async () => {
    if (selectedProducts.length === 0) {
      toast.error("Selecciona al menos un producto");
      return;
    }

    if (!bulkOperation) {
      toast.error("Selecciona una operación");
      return;
    }

    try {
      setProcessing(true);

      const result = await bulkProductOperations({
        operation: bulkOperation,
        product_ids: selectedProducts,
        updates: {
          ...(bulkUpdates as Record<string, unknown>),
          force_delete: forceDelete,
        },
      });

      const affectedCount = result?.success?.length ?? selectedProducts.length;
      toast.success(
        `Operación completada: ${affectedCount} productos afectados`,
      );
      setBulkOperation("");
      setBulkUpdates({});
      setForceDelete(false);
      onClearSelection();
      onSuccess();
    } catch (error) {
      appLogger.error("Error performing bulk operation:", error);
      const errorMessage =
        error instanceof Error
          ? error.message
          : "Error al realizar la operación masiva";
      toast.error(errorMessage);
    } finally {
      setProcessing(false);
    }
  };

  const handleClose = () => {
    setBulkOperation("");
    setBulkUpdates({});
    setForceDelete(false);
    onClearSelection();
  };

  return (
    <Card
      data-bulk-panel
      className="w-full bg-admin-bg-tertiary border border-admin-border-primary/20 shadow-premium-xl rounded-xl animate-in slide-in-from-top-4 duration-500 overflow-hidden sticky top-6 z-40"
      style={{ position: "relative" }}
    >
      <div className="absolute top-0 left-0 w-1 h-full bg-admin-accent-primary" />
      <CardContent className="pt-6 pb-6">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center space-x-4">
            <div className="p-3 bg-admin-accent-primary/10 border border-admin-accent-primary/20 rounded-xl">
              <Edit className="h-5 w-5 text-admin-accent-primary" />
            </div>
            <div>
              <h3 className="text-[10px] font-display font-black text-admin-text-primary tracking-[0.2em] uppercase leading-none mb-1">
                Operaciones de Archivo
              </h3>
              <p className="text-[11px] font-serif italic text-admin-text-tertiary">
                {selectedProducts.length}{" "}
                {selectedProducts.length === 1
                  ? "registro seleccionado"
                  : "registros seleccionados"}{" "}
                en cola técnica
              </p>
            </div>
          </div>
          <Button
            className="h-7 w-7 p-0 text-admin-text-tertiary hover:text-admin-text-primary"
            size="sm"
            variant="ghost"
            onClick={handleClose}
          >
            <svg
              className="h-3.5 w-3.5"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              viewBox="0 0 24 24"
              xmlns="http://www.w3.org/2000/svg"
            >
              <line x1="18" x2="6" y1="6" y2="18" />
              <line x1="6" x2="18" y1="6" y2="18" />
            </svg>
          </Button>
        </div>

        {!isDeleteDialog && (
          <div className="mb-4">
            <Label
              className="text-[10px] font-display font-bold text-admin-text-primary uppercase tracking-widest mb-2 block"
              htmlFor="operation"
            >
              Seleccionar Operación
            </Label>
            <Select
              value={bulkOperation ?? ""}
              onValueChange={setBulkOperation}
            >
              <SelectTrigger className="mt-1.5 h-11 bg-admin-bg-tertiary border-admin-border-primary/10 rounded-xl font-display text-[10px] tracking-widest uppercase">
                <SelectValue placeholder="Seleccionar operación" />
              </SelectTrigger>
              <SelectContent className="rounded-xl border-admin-border-primary/20">
                <SelectItem value="update_status">Cambiar Estado</SelectItem>
                <SelectItem value="update_category">
                  Cambiar Categoría
                </SelectItem>
                <SelectItem value="update_pricing">Ajustar Precios</SelectItem>
                <SelectItem value="update_inventory">
                  Ajustar Inventario
                </SelectItem>
                <SelectItem value="duplicate">Duplicar Productos</SelectItem>
                <SelectItem value="delete">
                  Archivar Productos (Eliminación Suave)
                </SelectItem>
                <SelectItem
                  className="text-admin-error font-display font-bold"
                  value="hard_delete"
                >
                  ⚠️ Eliminar Permanentemente
                </SelectItem>
              </SelectContent>
            </Select>
          </div>
        )}

          {bulkOperation && (
          <div className="pt-2 border-t border-admin-border-primary/20 mb-4">
            {BulkOperationFormRenderer(
              bulkOperation,
              bulkUpdates,
              setBulkUpdates,
              categories,
              forceDelete,
              setForceDelete,
            )}
          </div>
        )}

        <div className="flex items-center justify-end space-x-4 pt-6 mt-4 border-t border-admin-border-primary/10">
          <Button
            className="text-admin-text-tertiary hover:text-admin-text-primary uppercase text-[10px] font-bold tracking-widest"
            disabled={processing}
            variant="ghost"
            onClick={handleClose}
          >
            Cancelar
          </Button>
          <Button
            className={cn(
              "min-w-[180px] h-12 rounded-xl font-display font-black text-[10px] tracking-[0.2em] uppercase transition-all shadow-premium-sm",
              bulkOperation !== "delete" &&
                bulkOperation !== "hard_delete" &&
                "bg-admin-accent-primary text-[#1A2B23] hover:bg-admin-accent-secondary",
            )}
            disabled={
              processing ||
              !bulkOperation ||
              (bulkOperation === "hard_delete" && !forceDelete)
            }
            variant={
              bulkOperation === "delete" || bulkOperation === "hard_delete"
                ? "destructive"
                : "default"
            }
            onClick={handleBulkOperation}
          >
            {processing ? (
              <>
                <RefreshCw className="h-4 w-4 mr-2 animate-spin" />
                Procesando Operación...
              </>
            ) : bulkOperation === "delete" ? (
              "Archivar Registros"
            ) : bulkOperation === "hard_delete" ? (
              "⚠️ ELIMINAR PERMANENTEMENTE"
            ) : (
              "Ejecutar Cambios"
            )}
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import { CheckCircle, Package, Tag } from "lucide-react";

import type { Category } from "@/app/admin/products/hooks/useCategories";
import { Button } from "@/components/ui/button";
import {
  Dialog, DialogContent, DialogDescription,
  DialogFooter, DialogHeader, DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  editingCategory: Category | null;
  formData: { name: string; slug: string; description: string };
  loading: boolean;
  onFormChange: (field: string, value: string) => void;
  onSubmit: (e: React.FormEvent) => void;
}

export function CategoryDialog({ open, onOpenChange, editingCategory, formData, loading, onFormChange, onSubmit }: Props) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-[calc(100vw-2rem)] sm:max-w-[450px] p-0 rounded-xl border-2 border-admin-border-primary/20 bg-white">
        <DialogHeader className="p-8 pb-4 bg-admin-bg-tertiary/50 border-b border-admin-border-primary/10">
          <DialogTitle className="text-xl font-display font-bold text-admin-text-primary uppercase tracking-[0.2em]">
            {editingCategory ? "Editar categoría" : "Nueva categoría"}
          </DialogTitle>
          <DialogDescription className="text-[10px] font-serif italic text-admin-text-tertiary uppercase tracking-widest mt-1">
            Complete los datos de la categoría
          </DialogDescription>
        </DialogHeader>
        <form className="p-8 space-y-6" onSubmit={onSubmit}>
          <div className="space-y-4">
            <div className="space-y-2">
              <Label className="text-[10px] font-display font-bold text-admin-text-tertiary uppercase tracking-widest" htmlFor="category-name">
                Nombre *
              </Label>
              <Input required className="rounded-xl border-admin-border-primary/20 focus:border-epoch-primary focus:ring-0 p-6 text-sm font-display"
                id="category-name" placeholder="Ej: Marcos"
                value={formData.name}
                onChange={(e) => onFormChange("name", e.target.value)}
              />
            </div>
            <div className="space-y-2">
              <Label className="text-[10px] font-display font-bold text-admin-text-tertiary uppercase tracking-widest" htmlFor="category-slug">
                Slug
              </Label>
              <div className="relative">
                <Input className="rounded-xl border-admin-border-primary/20 bg-admin-bg-tertiary/30 focus:border-epoch-primary focus:ring-0 p-6 pl-10 text-xs font-mono lowercase"
                  id="category-slug" placeholder="marcos"
                  value={formData.slug}
                  onChange={(e) => onFormChange("slug", e.target.value)}
                />
                <Tag className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-admin-text-tertiary opacity-30" />
              </div>
            </div>
            <div className="space-y-2">
              <Label className="text-[10px] font-display font-bold text-admin-text-tertiary uppercase tracking-widest" htmlFor="category-description">
                Descripción
              </Label>
              <Textarea className="rounded-xl border-admin-border-primary/20 focus:border-epoch-primary focus:ring-0 p-4 text-xs font-serif italic resize-none"
                id="category-description" placeholder="Descripción opcional..." rows={3}
                value={formData.description}
                onChange={(e) => onFormChange("description", e.target.value)}
              />
            </div>
          </div>
          <DialogFooter className="gap-2 sm:gap-0 pt-4 border-t border-admin-border-primary/10">
            <Button className="rounded-xl text-[10px] font-display font-bold tracking-widest uppercase hover:bg-admin-bg-tertiary"
              disabled={loading} type="button" variant="ghost"
              onClick={() => onOpenChange(false)}>
              Cancelar
            </Button>
            <Button className="bg-epoch-primary hover:bg-epoch-primary/90 text-white rounded-xl text-[10px] font-display font-bold tracking-widest uppercase px-8 border-none shadow-premium-sm"
              disabled={loading} type="submit">
              {loading ? <Package className="h-3 w-3 mr-2 animate-spin" /> : <CheckCircle className="h-3 w-3 mr-2" />}
              {editingCategory ? "Actualizar" : "Crear"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { ArrowLeft } from "lucide-react";
import { useRouter } from "next/navigation";

import { QuoteActionsCard } from "@/components/admin/QuoteActionsCard";
import { QuoteInfoCard } from "@/components/admin/QuoteInfoCard";
import { QuoteItemsCard } from "@/components/admin/QuoteItemsCard";
import { Button } from "@/components/ui/button";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useQuote } from "@/hooks/useQuote";

export default function QuoteDetailPage() {
  const router = useRouter();
  const {
    quote,
    loading,
    loadingToPos,
