"use client";

import { FileText, Plus, RefreshCw, Search, Settings } from "lucide-react";
import dynamic from "next/dynamic";
import Link from "next/link";
import { useSearchParams } from "next/navigation";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useBranch } from "@/hooks/useBranch";

const CreateQuoteForm = dynamic(() => import("@/components/admin/CreateQuoteForm"), {
  loading: () => (
    <div className="flex items-center justify-center py-12">
      <div className="text-center space-y-4">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-epoch-primary mx-auto" />
        <p className="text-admin-text-tertiary">Cargando formulario...</p>
      </div>
    </div>
  ),
  ssr: false,
});

import { quoteService } from "@/lib/api/services";
import type { Quote, UpdateQuoteData } from "@/lib/api/services/quoteService";
import { appLogger } from '@/lib/logger';

import { DeleteQuoteDialog } from "./_components/DeleteQuoteDialog";
import { QuotesTable } from "./_components/QuotesTable";

export default function QuotesContent() {
  const searchParams = useSearchParams();
  const fieldOperationIdFromUrl = searchParams.get("field_operation_id");
  const { currentBranchId, isSuperAdmin, branches } = useBranch();
  const isGlobalView = !currentBranchId && isSuperAdmin;
  const [operativoName, setOperativoName] = useState<string | null>(null);
  const [operativoBranchId, setOperativoBranchId] = useState<string | null>(
    null,
  );

  useEffect(() => {
    if (!fieldOperationIdFromUrl) {
      setOperativoName(null);
      setOperativoBranchId(null);
      return;
    }
    fetch(`/api/admin/field-operations/${fieldOperationIdFromUrl}`)
      .then((r) => r.json())
      .then((j) => {
        const fo = j?.data?.fieldOperation;
        setOperativoName(fo?.name ?? null);
        setOperativoBranchId(fo?.branch_id ?? null);
      })
      .catch(() => {
        setOperativoName(null);
        setOperativoBranchId(null);
      });
  }, [fieldOperationIdFromUrl]);

  const [quotes, setQuotes] = useState<Quote[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [showCreateQuote, setShowCreateQuote] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [totalQuotes, setTotalQuotes] = useState(0);
  const quotesPerPage = 20;
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [quoteToDelete, setQuoteToDelete] = useState<string | null>(null);
  const [deleting, setDeleting] = useState(false);

  useEffect(() => {
    fetchQuotes();
  }, [
    currentPage,
    statusFilter,
    currentBranchId,
    isGlobalView,
    fieldOperationIdFromUrl,
  ]);

  const fetchQuotes = async () => {
    try {
      setLoading(true);

      const result = await quoteService.getQuotes({
        page: currentPage,
        limit: quotesPerPage,
        status: statusFilter !== "all" ? statusFilter : undefined,
        branch_id:
          isGlobalView && isSuperAdmin
            ? "global"
            : currentBranchId || undefined,
        search: searchTerm || undefined,
        field_operation_id: fieldOperationIdFromUrl || undefined,
      });

      setQuotes(result.data);
      setTotalPages(result.pagination.totalPages || 1);
      setTotalQuotes(result.pagination.total || 0);
    } catch (error) {
      appLogger.error("Error fetching quotes:", error);
      toast.error("Error al cargar presupuestos");
    } finally {
      setLoading(false);
    }
  };

  const filteredQuotes = quotes.filter((quote) => {
    if (searchTerm) {
      const searchLower = searchTerm.toLowerCase();
      return (
        quote.quote_number.toLowerCase().includes(searchLower) ||
        quote.customer?.email?.toLowerCase().includes(searchLower) ||
        `${quote.customer?.first_name || ""} ${quote.customer?.last_name || ""}`
          .toLowerCase()
          .includes(searchLower) ||
        quote.frame_name?.toLowerCase().includes(searchLower)
      );
    }
    return true;
  });

  const handleQuoteCreated = () => {
    setShowCreateQuote(false);
    fetchQuotes();
  };

  const handleDeleteClick = (quoteId: string) => {
    setQuoteToDelete(quoteId);
    setDeleteDialogOpen(true);
  };

  const handleDeleteConfirm = async () => {
    if (!quoteToDelete) return;

    setDeleting(true);
    try {
      await quoteService.deleteQuote(quoteToDelete);

      toast.success("Presupuesto eliminado exitosamente");
      setDeleteDialogOpen(false);
      setQuoteToDelete(null);
      fetchQuotes();
    } catch (error: unknown) {
      appLogger.error("Error deleting quote:", error);
      toast.error(error instanceof Error ? error.message : "Error al eliminar presupuesto");
    } finally {
      setDeleting(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* Operativo mode banner */}
      {fieldOperationIdFromUrl && (
        <div className="flex items-center justify-between gap-2 px-4 py-2 rounded-xl bg-admin-accent-primary/20 border border-admin-accent-primary/30">
          <span className="text-sm font-medium text-admin-text-primary">
            Presupuestos del operativo: {operativoName || "..."}
          </span>
          <Link
            className="text-sm text-admin-accent-primary hover:underline font-medium"
            href={`/admin/field-operations/${fieldOperationIdFromUrl}`}
          >
            Volver al operativo
          </Link>
        </div>
      )}

      {/* Header - multi-row */}
      <div className="flex flex-col gap-2 sm:gap-3">
        <div>
          <h1
            className="text-xl sm:text-2xl lg:text-3xl font-bold text-epoch-primary"
            data-tour="quotes-header"
          >
            Presupuestos
          </h1>
          <p className="text-xs sm:text-sm text-admin-text-tertiary">
            {isGlobalView
              ? "Gestiona presupuestos de todas las sucursales"
              : "Gestiona presupuestos para trabajos de lentes"}
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <Link href="/admin/quotes/settings">
            <Button
              aria-label="Configuración"
              className="h-9 w-9 sm:w-auto sm:px-3"
              size="sm"
              variant="outline"
            >
              <Settings className="h-4 w-4 sm:mr-2 shrink-0" />
              <span className="hidden sm:inline">Configuración</span>
            </Button>
          </Link>
          <Button
            className="h-9 gap-1.5"
            size="sm"
            onClick={() => setShowCreateQuote(true)}
          >
            <Plus className="h-4 w-4 shrink-0" />
            <span className="text-xs sm:text-sm">Nuevo Presupuesto</span>
          </Button>
        </div>
      </div>

      {/* Filters - search wider, filter smaller on mobile */}
      <Card className="bg-admin-bg-tertiary shadow-[0_1px_3px_rgba(0,0,0,0.3)]">
        <CardContent className="p-4 sm:p-6">
          <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-3 sm:gap-4">
            <div className="flex-1 min-w-0">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-admin-text-tertiary" />
                <Input
                  className="pl-10 w-full"
                  placeholder="Buscar por número, cliente, email..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
              </div>
            </div>
            <div className="w-[140px] sm:w-[160px] md:w-[180px] shrink-0">
              <Select value={statusFilter} onValueChange={setStatusFilter}>
                <SelectTrigger className="w-full">
                  <SelectValue placeholder="Estado" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Todos los estados</SelectItem>
                  <SelectItem value="draft">Borrador</SelectItem>
                  <SelectItem value="sent">Enviado</SelectItem>
                  <SelectItem value="accepted">Aceptado</SelectItem>
                  <SelectItem value="rejected">Rechazado</SelectItem>
                  <SelectItem value="expired">Expirado</SelectItem>
                  <SelectItem value="converted_to_work">Convertido</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Quotes Table */}
      <Card className="bg-admin-bg-tertiary shadow-[0_1px_3px_rgba(0,0,0,0.3)]">
        <CardHeader>
          <CardTitle>Presupuestos ({totalQuotes})</CardTitle>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="text-center py-12">
              <RefreshCw className="h-8 w-8 animate-spin text-epoch-primary mx-auto mb-4" />
              <p className="text-admin-text-tertiary">
                Cargando presupuestos...
              </p>
            </div>
          ) : filteredQuotes.length === 0 ? (
            <div className="text-center py-12">
              <FileText className="h-12 w-12 text-admin-text-tertiary mx-auto mb-4" />
              <h3 className="text-lg font-semibold text-epoch-primary mb-2">
                No hay presupuestos
              </h3>
              <p className="text-admin-text-tertiary mb-4">
                {searchTerm
                  ? "No se encontraron presupuestos que coincidan con la búsqueda"
                  : "Comienza creando tu primer presupuesto"}
              </p>
              {!searchTerm && (
                <Button onClick={() => setShowCreateQuote(true)}>
                  <Plus className="h-4 w-4 mr-2" />
                  Crear Presupuesto
                </Button>
              )}
            </div>
          ) : (
            <QuotesTable
              currentPage={currentPage}
              fieldOperationIdFromUrl={fieldOperationIdFromUrl}
              filteredQuotes={filteredQuotes}
              totalPages={totalPages}
              totalQuotes={totalQuotes}
              onDeleteClick={handleDeleteClick}
              onPageChange={setCurrentPage}
              onStatusChange={async (quoteId, newStatus) => {
                try {
                  await quoteService.updateQuote(quoteId, { status: newStatus as UpdateQuoteData["status"] });
                  setQuotes((prev) => prev.map((q) => q.id === quoteId ? { ...q, status: newStatus as Quote["status"] } : q));
                  toast.success("Estado actualizado");
                } catch (error) {
                  toast.error(error instanceof Error ? error.message : "Error al actualizar estado");
                }
              }}
            />
          )}
        </CardContent>
      </Card>

      {/* Create Quote Dialog */}
      <Dialog open={showCreateQuote} onOpenChange={setShowCreateQuote}>
        <DialogContent className="max-w-[calc(100vw-2rem)] sm:max-w-4xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Nuevo Presupuesto</DialogTitle>
            <DialogDescription>
              Crea un presupuesto para un trabajo de lentes
            </DialogDescription>
          </DialogHeader>
          <CreateQuoteForm
            initialBranchId={operativoBranchId ?? undefined}
            initialFieldOperationId={fieldOperationIdFromUrl || undefined}
            onCancel={() => setShowCreateQuote(false)}
            onSuccess={handleQuoteCreated}
          />
        </DialogContent>
      </Dialog>

      <DeleteQuoteDialog
        deleting={deleting}
        open={deleteDialogOpen}
        onConfirm={handleDeleteConfirm}
        onOpenChange={(open) => { setDeleteDialogOpen(open); if (!open) setQuoteToDelete(null); }}
      />
    </div>
  );
}

"use client";

import { CheckCircle, ChevronLeft, ChevronRight, Clock, Eye, FileText, RefreshCw, Send, ShoppingCart, Trash2, XCircle } from "lucide-react";
import Link from "next/link";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Quote } from "@/lib/api/services";
import { formatCurrency, formatDate } from "@/lib/utils";

function getStatusBadge(status: string) {
  const config: Record<string, { variant: unknown; label: string; icon: unknown }> = {
    draft: { variant: "outline", label: "Borrador", icon: FileText },
    sent: { variant: "secondary", label: "Enviado", icon: Send },
    accepted: { variant: "default", label: "Aceptado", icon: CheckCircle },
    rejected: { variant: "destructive", label: "Rechazado", icon: XCircle },
    expired: { variant: "outline", label: "Expirado", icon: Clock },
    converted_to_work: { variant: "default", label: "Convertido", icon: RefreshCw },
  };
  const c = config[status] || { variant: "outline", label: status, icon: FileText };
  const Icon = c.icon as React.ElementType;
  return <Badge className="flex items-center gap-1" variant={c.variant as "outline" | "default" | "secondary" | "destructive"}><Icon className="h-3 w-3" />{c.label}</Badge>;
}

interface Props {
  filteredQuotes: Quote[];
  currentPage: number;
  totalPages: number;
  totalQuotes: number;
  fieldOperationIdFromUrl: string | null;
  onPageChange: (page: number) => void;
  onDeleteClick: (id: string) => void;
  onStatusChange: (quoteId: string, newStatus: string) => void;
}

export function QuotesTable({ filteredQuotes, currentPage, totalPages, totalQuotes, fieldOperationIdFromUrl, onPageChange, onDeleteClick, onStatusChange }: Props) {
  return (
    <>
      <div className="overflow-x-auto -mx-4 px-4 md:mx-0 md:px-0">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Número</TableHead><TableHead>Cliente</TableHead><TableHead>Marco</TableHead><TableHead>Lente</TableHead>
              <TableHead>Total</TableHead><TableHead>Estado</TableHead><TableHead>Convertido</TableHead><TableHead>Fecha</TableHead><TableHead>Acciones</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {filteredQuotes.map((quote) => {
              const isConverted = quote.status === "accepted" && !!quote.converted_to_work_order_id;
              return (
                <TableRow key={quote.id}>
                  <TableCell className="font-medium">{quote.quote_number}</TableCell>
                  <TableCell>
                    <div>
                      <div className="font-medium">{quote.customer?.first_name || ""} {quote.customer?.last_name || ""}</div>
                      <div className="text-sm text-admin-text-tertiary">{quote.customer?.email}</div>
                    </div>
                  </TableCell>
                  <TableCell>{quote.frame_name || "-"}</TableCell>
                  <TableCell>
                    <div><div className="font-medium">{quote.lens_type || "-"}</div><div className="text-sm text-admin-text-tertiary">{quote.lens_material || ""}</div></div>
                  </TableCell>
                  <TableCell className="font-semibold text-admin-success">{formatCurrency(quote.total_amount)}</TableCell>
                  <TableCell>
                    <Select
                      disabled={isConverted}
                      value={quote.status}
                      onValueChange={(value) => onStatusChange(quote.id, value)}
                    >
                      <SelectTrigger className="w-auto border-0 p-0 h-auto bg-transparent hover:bg-transparent focus:ring-0 focus:ring-offset-0 shadow-none [&>svg]:hidden [&_svg]:hidden [&_[data-radix-select-icon]]:hidden">
                        <SelectValue asChild>
                          <div className={`cursor-pointer ${isConverted ? "cursor-not-allowed opacity-75" : ""}`}>{getStatusBadge(quote.status)}</div>
                        </SelectValue>
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="draft"><div className="flex items-center gap-2"><FileText className="h-3 w-3" /> Borrador</div></SelectItem>
                        <SelectItem value="sent"><div className="flex items-center gap-2"><Send className="h-3 w-3" /> Enviado</div></SelectItem>
                        <SelectItem value="accepted"><div className="flex items-center gap-2"><CheckCircle className="h-3 w-3" /> Aceptado</div></SelectItem>
                        <SelectItem value="rejected"><div className="flex items-center gap-2"><XCircle className="h-3 w-3" /> Rechazado</div></SelectItem>
                        <SelectItem value="expired"><div className="flex items-center gap-2"><Clock className="h-3 w-3" /> Expirado</div></SelectItem>
                      </SelectContent>
                    </Select>
                  </TableCell>
                  <TableCell>
                    {quote.converted_to_work_order_id ? (
                      <Badge className="flex items-center gap-1 bg-green-600" variant="default"><RefreshCw className="h-3 w-3" /> Convertido</Badge>
                    ) : (<span className="text-admin-text-tertiary text-sm">-</span>)}
                  </TableCell>
                  <TableCell>
                    <div>
                      <div>{formatDate(quote.quote_date)}</div>
                      {quote.expiration_date && (
                        <div className={`text-xs ${new Date(quote.expiration_date) < new Date() ? "text-red-500" : "text-admin-text-tertiary"}`}>
                          Exp: {formatDate(quote.expiration_date)}
                        </div>
                      )}
                    </div>
                  </TableCell>
                  <TableCell>
                    <div className="flex items-center gap-2">
                      <Link href={`/admin/quotes/${quote.id}`}><Button size="sm" variant="outline"><Eye className="h-4 w-4 mr-1" />Ver</Button></Link>
                      {quote.status !== "accepted" && !quote.converted_to_work_order_id && (
                        <Link href={fieldOperationIdFromUrl ? `/admin/pos?quoteId=${quote.id}&field_operation_id=${fieldOperationIdFromUrl}` : `/admin/pos?quoteId=${quote.id}`}>
                          <Button className="text-green-600 hover:text-green-700 hover:bg-green-50" size="sm" variant="outline"><ShoppingCart className="h-4 w-4 mr-1" />Cargar al POS</Button>
                        </Link>
                      )}
                      <Button className="text-red-600 hover:text-red-700 hover:bg-red-50"
                        disabled={quote.status === "accepted" || !!quote.converted_to_work_order_id}
                        size="sm" variant="outline"
                        onClick={() => onDeleteClick(quote.id)}
                      ><Trash2 className="h-4 w-4" /></Button>
                    </div>
                  </TableCell>
                </TableRow>
              );
            })}
          </TableBody>
        </Table>
      </div>
      {totalPages > 1 && (
        <div className="flex items-center justify-between mt-4">
          <div className="text-sm text-admin-text-tertiary">Página {currentPage} de {totalPages}</div>
          <div className="flex gap-2">
            <Button disabled={currentPage === 1} size="sm" variant="outline" onClick={() => onPageChange(Math.max(1, currentPage - 1))}>
              <ChevronLeft className="h-4 w-4" />
            </Button>
            <Button disabled={currentPage === totalPages} size="sm" variant="outline" onClick={() => onPageChange(Math.min(totalPages, currentPage + 1))}>
              <ChevronRight className="h-4 w-4" />
            </Button>
          </div>
        </div>
      )}
    </>
  );
}

"use client";

import { Percent, Plus, X } from "lucide-react";

import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

interface VolumeDiscount {
  min_amount: number;
  discount_percentage: number;
}

interface QuoteDiscountsTabProps {
  volumeDiscounts: VolumeDiscount[];
  onAddDiscount: () => void;
  onUpdateDiscount: (
    index: number,
    field: "min_amount" | "discount_percentage",
    value: number,
  ) => void;
  onRemoveDiscount: (index: number) => void;
}

export function QuoteDiscountsTab({
  volumeDiscounts,
  onAddDiscount,
  onUpdateDiscount,
  onRemoveDiscount,
}: QuoteDiscountsTabProps) {
  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center">
          <Percent className="h-5 w-5 mr-2" />
          Descuentos por Volumen
        </CardTitle>
        <CardDescription>
          Configura descuentos automáticos según el monto total del
          presupuesto. Los descuentos se aplicarán automáticamente cuando
          el monto alcance el mínimo configurado.
        </CardDescription>
      </CardHeader>
      <CardContent>
        <div className="space-y-4">
          {volumeDiscounts?.length === 0 ? (
            <div className="text-center py-8 border-2 border-dashed rounded-lg">
              <Percent className="h-12 w-12 mx-auto mb-4 text-admin-text-tertiary" />
              <p className="text-admin-text-tertiary mb-2">
                No hay descuentos configurados
              </p>
              <p className="text-xs text-admin-text-tertiary mb-4">
                Agrega descuentos por volumen para aplicar automáticamente
                según el monto del presupuesto
              </p>
              <Button variant="outline" onClick={onAddDiscount}>
                <Plus className="h-4 w-4 mr-2" />
                Agregar Primer Descuento
              </Button>
            </div>
          ) : (
            <>
              {volumeDiscounts?.map((discount, index) => (
                <div
                  className="flex items-center gap-4 p-4 border rounded-lg hover:bg-gray-50 transition-colors"
                  key={index}
                >
                  <div className="flex-1 grid grid-cols-2 gap-4">
                    <div>
                      <Label>Monto Mínimo (CLP)</Label>
                      <Input
                        className="mt-1"
                        type="number"
                        value={discount.min_amount}
                        onChange={(e) =>
                          onUpdateDiscount(
                            index,
                            "min_amount",
                            parseFloat(e.target.value) || 0,
                          )
                        }
                      />
                    </div>
                    <div>
                      <Label>Descuento (%)</Label>
                      <Input
                        className="mt-1"
                        step="0.1"
                        type="number"
                        value={discount.discount_percentage}
                        onChange={(e) =>
                          onUpdateDiscount(
                            index,
                            "discount_percentage",
                            parseFloat(e.target.value) || 0,
                          )
                        }
                      />
                    </div>
                  </div>
                  <Button
                    className="text-red-500 hover:text-red-700 hover:bg-red-50"
                    size="icon"
                    variant="ghost"
                    onClick={() => onRemoveDiscount(index)}
                  >
                    <X className="h-4 w-4" />
                  </Button>
                </div>
              ))}
              <Button variant="outline" onClick={onAddDiscount}>
                <Plus className="h-4 w-4 mr-2" />
                Agregar Descuento
              </Button>
            </>
          )}
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import {
  AlertCircle,
  ArrowLeft,
  Eye,
  FileText,
  Loader2,
  Percent,
  Save,
  Settings,
} from "lucide-react";
import Link from "next/link";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { BranchSelector } from "@/components/admin/BranchSelector";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
} from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useBranch } from "@/hooks/useBranch";
import { QuoteSettings, quoteSettingsService } from "@/lib/api/services";
import { appLogger } from '@/lib/logger';

import { QuoteDiscountsTab } from "./QuoteDiscountsTab";
import { QuoteGeneralTab } from "./QuoteGeneralTab";
import { QuoteTermsTab } from "./QuoteTermsTab";
import { QuoteTreatmentsTab } from "./QuoteTreatmentsTab";

interface TreatmentPrice {
  price: number;
  enabled: boolean;
}

// Extended QuoteSettings type for form state with additional UI-specific fields
interface FormQuoteSettings extends Omit<QuoteSettings, "treatment_prices"> {
  treatment_prices: {
    // Tratamientos que se aplican en laboratorio local
    anti_reflective: TreatmentPrice | number;
    scratch_resistant: TreatmentPrice | number;
    tint: TreatmentPrice | number;
    // Servicio personalizado
    custom_service?: {
      enabled: boolean;
      name: string;
      price: number;
    };
  };
}

export default function QuoteSettingsContent() {
  const {
    currentBranchId,
    isSuperAdmin,
    branches,
    isLoading: branchLoading,
  } = useBranch();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [settings, setSettings] = useState<FormQuoteSettings | null>(null);
  const [hasChanges, setHasChanges] = useState(false);
  const [activeTab, setActiveTab] = useState("general");

  useEffect(() => {
    if (!branchLoading) {
      fetchSettings();
    }
  }, [currentBranchId, branchLoading]);

  const fetchSettings = async () => {
    try {
      setLoading(true);
      const fetchedSettings = await quoteSettingsService.get();
      if (fetchedSettings) {
        setSettings(fetchedSettings as FormQuoteSettings);
      } else {
        setSettings(null);
      }
      setHasChanges(false);
    } catch (error) {
      appLogger.error("Error fetching settings:", error);
      toast.error("Error al cargar configuración");
    } finally {
      setLoading(false);
    }
  };

  const isGlobalView = !currentBranchId && isSuperAdmin;

  const handleSave = async () => {
    if (!settings) return;

    if (isGlobalView) {
      const confirmGlobal = window.confirm(
        "¿Está seguro de que desea guardar esta configuración GLOBALMENTE? Se aplicará a todas las sucursales existentes y futuras.",
      );
      if (!confirmGlobal) return;
    }

    try {
      setSaving(true);
      await quoteSettingsService.update(settings as never);

      setHasChanges(false);

      // Notify other tabs/windows about the settings update
      if (typeof window !== "undefined") {
        window.localStorage.setItem(
          "quote-settings-updated",
          Date.now().toString(),
        );
        window.dispatchEvent(new Event("quote-settings-updated"));
      }

      if (currentBranchId) {
        toast.success("Configuración guardada exitosamente", {
          description:
            "Los cambios se aplicarán automáticamente a los nuevos presupuestos en esta sucursal",
          duration: 5000,
        });
      } else {
        toast.success("Configuración GLOBAL guardada exitosamente", {
          description:
            "Los cambios se han aplicado a TODAS las sucursales de la organización",
          duration: 7000,
        });
      }
    } catch (error) {
      appLogger.error("Error saving settings:", error);
      toast.error("Error al guardar configuración");
    } finally {
      setSaving(false);
    }
  };

  const updateSetting = <K extends keyof QuoteSettings>(
    key: K,
    value: QuoteSettings[K],
  ) => {
    if (!settings) return;
    setSettings({
      ...settings,
      [key]: value,
    });
    setHasChanges(true);
  };

  const updateNestedSetting = <
    K extends keyof QuoteSettings,
    NK extends string,
  >(
    key: K,
    nestedKey: NK,
    value: unknown,
  ) => {
    if (!settings) return;
    const current = settings[key] as Record<string, unknown>;
    setSettings({
      ...settings,
      [key]: {
        ...current,
        [nestedKey]: value,
      },
    });
    setHasChanges(true);
  };

  // Helper functions to normalize treatment price format (backward compatibility)
  const getTreatmentPrice = (value: TreatmentPrice | number): number => {
    return typeof value === "number" ? value : value.price;
  };

  const getTreatmentEnabled = (value: TreatmentPrice | number): boolean => {
    return typeof value === "number" ? true : value.enabled;
  };

  const normalizeTreatmentValue = (
    value: TreatmentPrice | number,
    price?: number,
    enabled?: boolean,
  ): TreatmentPrice => {
    const currentPrice = price ?? getTreatmentPrice(value);
    const currentEnabled = enabled ?? getTreatmentEnabled(value);
    return { price: currentPrice, enabled: currentEnabled };
  };

  const updateTreatmentPrice = (treatment: string, price: number) => {
    if (!settings) return;
    const currentValue =
      settings.treatment_prices[
        treatment as keyof QuoteSettings["treatment_prices"]
      ];
    const normalized = normalizeTreatmentValue(currentValue, price);
    updateNestedSetting(
      "treatment_prices",
      treatment as keyof QuoteSettings["treatment_prices"],
      normalized,
    );
  };

  const updateTreatmentEnabled = (treatment: string, enabled: boolean) => {
    if (!settings) return;
    const currentValue =
      settings.treatment_prices[
        treatment as keyof QuoteSettings["treatment_prices"]
      ];
    const normalized = normalizeTreatmentValue(
      currentValue,
      undefined,
      enabled,
    );
    updateNestedSetting(
      "treatment_prices",
      treatment as keyof QuoteSettings["treatment_prices"],
      normalized,
    );
  };

  const addVolumeDiscount = () => {
    if (!settings) return;
    updateSetting("volume_discounts", [
      ...(settings.volume_discounts || []),
      { min_amount: 0, discount_percentage: 0 },
    ]);
  };

  const updateVolumeDiscount = (
    index: number,
    field: "min_amount" | "discount_percentage",
    value: number,
  ) => {
    if (!settings) return;
    const updated = [...(settings.volume_discounts || [])];
    updated[index] = { ...updated[index], [field]: value };
    updateSetting("volume_discounts", updated);
  };

  const removeVolumeDiscount = (index: number) => {
    if (!settings) return;
    updateSetting(
      "volume_discounts",
      (settings.volume_discounts || []).filter((_, i) => i !== index),
    );
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <Loader2 className="h-8 w-8 animate-spin text-epoch-primary" />
      </div>
    );
  }

  if (!settings) {
    return (
      <div className="p-6">
        <Card>
          <CardContent className="py-12 text-center">
            <AlertCircle className="h-12 w-12 mx-auto mb-4 text-red-500" />
            <p className="text-admin-text-tertiary">
              Error al cargar configuración
            </p>
            <Button className="mt-4" onClick={fetchSettings}>
              Reintentar
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  const treatmentLabels: Record<string, string> = {
    // Tratamientos de laboratorio local
    anti_reflective: "Anti-reflejante",
    scratch_resistant: "Anti-rayas",
    tint: "Tinte",
    // Servicio personalizado
    custom_service: "Servicio Personalizado",
  };

  // Lista de treatments a mostrar (solo los que se aplican en laboratorio)
  const TREATMENT_KEYS = ["anti_reflective", "scratch_resistant", "tint"];

  return (
    <div className="p-6 space-y-6 max-w-7xl mx-auto">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-epoch-primary">
            Configuración de Presupuestos {isGlobalView && "(VISTA GLOBAL)"}
          </h1>
          <p className="text-admin-text-tertiary mt-2">
            {isGlobalView
              ? "Configura los parámetros predeterminados para todas las sucursales de la organización"
              : "Personaliza los valores por defecto y parámetros del sistema de presupuestos"}
          </p>
        </div>
        <div className="flex items-center gap-2">
          {isSuperAdmin && <BranchSelector />}
          <Link href="/admin/quotes">
            <Button size="sm" variant="outline">
              <ArrowLeft className="h-4 w-4 mr-2" />
              Volver
            </Button>
          </Link>
          <Button
            className="min-w-[140px]"
            disabled={saving || !hasChanges}
            onClick={handleSave}
          >
            {saving ? (
              <>
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                Guardando...
              </>
            ) : (
              <>
                <Save className="h-4 w-4 mr-2" />
                Guardar Cambios
              </>
            )}
          </Button>
        </div>
      </div>

      {/* Changes indicator */}
      {hasChanges && (
        <Alert className="border-amber-200 bg-amber-50">
          <AlertCircle className="h-4 w-4 text-amber-600" />
          <AlertDescription className="text-amber-800">
            Tienes cambios sin guardar. Recuerda guardar para que se apliquen a
            los nuevos presupuestos.
          </AlertDescription>
        </Alert>
      )}

      {/* Main Content with Tabs */}
      <Tabs
        className="space-y-6"
        value={activeTab}
        onValueChange={setActiveTab}
      >
        <TabsList className="grid w-full grid-cols-4">
          <TabsTrigger value="general">
            <Settings className="h-4 w-4 mr-2" />
            General
          </TabsTrigger>
          <TabsTrigger value="treatments">
            <Eye className="h-4 w-4 mr-2" />
            Tratamientos
          </TabsTrigger>
          <TabsTrigger value="discounts">
            <Percent className="h-4 w-4 mr-2" />
            Descuentos
          </TabsTrigger>
          <TabsTrigger value="terms">
            <FileText className="h-4 w-4 mr-2" />
            Términos
          </TabsTrigger>
        </TabsList>

        {/* Tab 1: General Settings */}
        <TabsContent className="space-y-6" value="general">
          <QuoteGeneralTab
            defaultExpirationDays={settings.default_expiration_days}
            defaultLaborCost={settings.default_labor_cost}
            defaultTaxPercentage={settings.default_tax_percentage}
            laborCostIncludesTax={settings.labor_cost_includes_tax ?? true}
            lensCostIncludesTax={settings.lens_cost_includes_tax ?? true}
            treatmentsCostIncludesTax={settings.treatments_cost_includes_tax ?? true}
            onUpdateSetting={updateSetting}
          />
        </TabsContent>

        {/* Tab 2: Treatments */}
        <TabsContent className="space-y-6" value="treatments">
          <QuoteTreatmentsTab
            getTreatmentEnabled={getTreatmentEnabled}
            getTreatmentPrice={getTreatmentPrice}
            TREATMENT_KEYS={TREATMENT_KEYS}
            treatmentLabels={treatmentLabels}
            treatmentPrices={settings.treatment_prices as Record<string, TreatmentPrice | number>}
            updateNestedSetting={updateNestedSetting as (key: string, nestedKey: string, value: unknown) => void}
            updateTreatmentEnabled={updateTreatmentEnabled}
            updateTreatmentPrice={updateTreatmentPrice}
          />
        </TabsContent>

        {/* Tab 3: Volume Discounts */}
        <TabsContent className="space-y-6" value="discounts">
          <QuoteDiscountsTab
            volumeDiscounts={settings.volume_discounts ?? []}
            onAddDiscount={addVolumeDiscount}
            onRemoveDiscount={removeVolumeDiscount}
            onUpdateDiscount={updateVolumeDiscount}
          />
        </TabsContent>

        {/* Tab 4: Terms and Conditions */}
        <TabsContent className="space-y-6" value="terms">
          <QuoteTermsTab
            notesTemplate={settings.notes_template || ""}
            termsAndConditions={settings.terms_and_conditions || ""}
            onUpdateSetting={updateSetting}
          />
        </TabsContent>
      </Tabs>
    </div>
  );
}

