                      <Button
                        className="text-red-500 hover:text-red-600 hover:bg-red-50"
                        size="icon"
                        title="Eliminar permanentemente"
                        variant="ghost"
                        onClick={() =>
                          setDeleteBackupConfirmFileName(backup.name)
                        }
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      <CreateBackupDialog
        isGenerating={isGenerating}
        open={createBackupConfirmOpen}
        onConfirm={handleCreateBackup}
        onOpenChange={setCreateBackupConfirmOpen}
      />

      <DeleteBackupDialog
        open={deleteBackupConfirmFileName !== null}
        onConfirm={handleDeleteBackup}
        onOpenChange={(open) => !open && setDeleteBackupConfirmFileName(null)}
      />
    </div>
  );
}

"use client";

import { Copy, Key, Link2, Loader2, Trash2 } from "lucide-react";
import { useCallback, useEffect, useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

interface OpticasToken {
  id: string;
  token_preview: string;
  expires_at: string;
  label: string | null;
  created_at: string;
}

export function OpticasTokensSection() {
  const [opticasTokens, setOpticasTokens] = useState<OpticasToken[]>([]);
  const [tokensLoading, setTokensLoading] = useState(false);
  const [generatingToken, setGeneratingToken] = useState(false);
  const [newTokenModal, setNewTokenModal] = useState<{ open: boolean; url: string }>({ open: false, url: "" });

  const fetchOpticasTokens = useCallback(async () => {
    setTokensLoading(true);
    try {
      const res = await fetch("/api/admin/opticas-access-tokens");
      const data = await res.json();
      if (res.ok) setOpticasTokens(data.tokens ?? []);
    } catch {
      toast.error("Error al cargar tokens");
    } finally {
      setTokensLoading(false);
    }
  }, []);

  useEffect(() => { fetchOpticasTokens(); }, [fetchOpticasTokens]);

  const handleGenerate = async (label?: string) => {
    setGeneratingToken(true);
    try {
      const res = await fetch("/api/admin/opticas-access-tokens", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ label: label || null, expires_in_days: 90 }),
      });
      const data = await res.json();
      if (!res.ok) { toast.error(data.error || "Error al generar enlace"); return; }
      setNewTokenModal({ open: true, url: data.url });
      fetchOpticasTokens();
      toast.success("Enlace generado. Cópialo ahora; no se mostrará de nuevo.");
    } catch { toast.error("Error de conexión"); }
    finally { setGeneratingToken(false); }
  };

  const handleCopyUrl = async (id: string) => {
    try {
      const res = await fetch(`/api/admin/opticas-access-tokens/${id}`);
      const data = await res.json();
      if (!res.ok) { toast.error(data.error || "Error al obtener URL"); return; }
      await navigator.clipboard.writeText(data.url);
      toast.success("URL copiada al portapapeles");
    } catch { toast.error("Error al copiar"); }
  };

  const handleRevoke = async (id: string) => {
    try {
      const res = await fetch(`/api/admin/opticas-access-tokens/${id}`, { method: "DELETE" });
      if (!res.ok) { const data = await res.json(); toast.error(data.error || "Error al revocar"); return; }
      toast.success("Token revocado");
      fetchOpticasTokens();
    } catch { toast.error("Error de conexión"); }
  };

  return (
    <>
      <Card className="admin-card">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Key className="h-5 w-5" />
            Acceso ópticas conocidas
          </CardTitle>
          <p className="text-sm text-muted-foreground">
            Genera enlaces únicos para ópticas de confianza. Cada enlace es revocable y tiene expiración.
          </p>
        </CardHeader>
        <CardContent className="space-y-4">
          <Button disabled={generatingToken} onClick={() => handleGenerate()}>
            {generatingToken ? <><Loader2 className="h-4 w-4 animate-spin mr-2" /> Generando...</> : <><Link2 className="h-4 w-4 mr-2" /> Generar enlace único</>}
          </Button>

          {tokensLoading ? (
            <div className="flex items-center gap-2 text-sm text-muted-foreground"><Loader2 className="h-4 w-4 animate-spin" /> Cargando tokens…</div>
          ) : opticasTokens.length > 0 ? (
            <div className="border rounded-lg overflow-hidden">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Label</TableHead>
                    <TableHead>Vista previa</TableHead>
                    <TableHead>Expira</TableHead>
                    <TableHead className="text-right">Acciones</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {opticasTokens.map((t) => (
                    <TableRow key={t.id}>
                      <TableCell>{t.label || "—"}</TableCell>
                      <TableCell><code className="text-xs">{t.token_preview}</code></TableCell>
                      <TableCell>{new Date(t.expires_at).toLocaleDateString()}</TableCell>
                      <TableCell className="text-right space-x-2">
                        <Button size="sm" variant="outline" onClick={() => handleCopyUrl(t.id)}><Copy className="h-3 w-3 mr-1" /> Copiar URL</Button>
                        <Button size="sm" variant="outline" onClick={() => handleRevoke(t.id)}><Trash2 className="h-3 w-3 mr-1" /> Revocar</Button>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          ) : null}
        </CardContent>
      </Card>

      <Dialog open={newTokenModal.open} onOpenChange={(open) => setNewTokenModal((prev) => ({ ...prev, open }))}>
        <DialogContent>
          <DialogHeader><DialogTitle>Enlace generado</DialogTitle></DialogHeader>
          <p className="text-sm text-muted-foreground">Copia este enlace ahora. No se mostrará de nuevo.</p>
          <div className="flex gap-2">
            <Input readOnly className="font-mono text-sm" value={newTokenModal.url} />
            <Button variant="outline" onClick={() => { navigator.clipboard.writeText(newTokenModal.url); toast.success("URL copiada"); }}>
              <Copy className="h-4 w-4" />
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
}

"use client";

import {
  ArrowLeft,
  Calendar,
  Loader2,
  Save,
  Users,
} from "lucide-react";
import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";

import { OpticasTokensSection } from "./_components/OpticasTokensSection";

export default function SaasConfigPage() {
  const router = useRouter();
  const [trialDays, setTrialDays] = useState<string>("7");
  const [signupEnabled, setSignupEnabled] = useState(false);
  const [onboardingStageMode, setOnboardingStageMode] = useState(true);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [savingOnboarding, setSavingOnboarding] = useState(false);

  useEffect(() => {
    fetch("/api/admin/system/config")
      .then((res) => res.json())
      .then((data) => {
        const configs = data.configs || [];
        const trial = configs.find(
          (c: { config_key: string }) =>
            c.config_key === "membership_trial_days",
        );
        if (trial?.config_value != null) {
          setTrialDays(String(trial.config_value));
        }
        const signup = configs.find(
          (c: { config_key: string }) => c.config_key === "signup_enabled",
        );
        if (signup?.config_value != null) {
          setSignupEnabled(
            signup.config_value === true ||
              signup.config_value === "true" ||
              signup.config_value === 1,
          );
        }
        const stage = configs.find(
          (c: { config_key: string }) =>
            c.config_key === "onboarding_stage_mode",
        );
        if (stage?.config_value != null) {
          setOnboardingStageMode(
            stage.config_value === true ||
              stage.config_value === "true" ||
              stage.config_value === 1,
          );
        }
      })
      .catch(() => toast.error("Error al cargar configuración"))
      .finally(() => setLoading(false));
  }, []);

  const handleSave = async () => {
    const num = parseInt(trialDays, 10);
    if (isNaN(num) || num < 1 || num > 365) {
      toast.error("Ingresa un número entre 1 y 365 días.");
      return;
    }
    setSaving(true);
    try {
      const res = await fetch("/api/admin/system/config", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          updates: [{ config_key: "membership_trial_days", config_value: num }],
        }),
      });
      const data = await res.json();
      if (!res.ok) {
        toast.error(data.error || "Error al guardar");
        return;
      }
      const result = data.results?.[0];
      if (result?.error) {
        toast.error(result.error);
        return;
      }
      toast.success("Período de prueba por defecto actualizado.");
    } catch {
      toast.error("Error de conexión");
    } finally {
      setSaving(false);
    }
  };

  const handleSaveOnboarding = async () => {
    setSavingOnboarding(true);
    try {
      const res = await fetch("/api/admin/system/config", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          updates: [
            { config_key: "signup_enabled", config_value: signupEnabled },
            {
              config_key: "onboarding_stage_mode",
              config_value: onboardingStageMode,
            },
          ],
        }),
      });
      const data = await res.json();
      if (!res.ok) {
        toast.error(data.error || "Error al guardar");
        return;
      }
      const results = data.results || [];
      const hasError = results.some((r: { error?: string }) => r.error);
      if (hasError) {
        const firstError = results.find((r: { error?: string }) => r.error);
        toast.error(firstError?.error || "Error al guardar");
        return;
      }
      toast.success("Configuración de onboarding actualizada.");
    } catch {
      toast.error("Error de conexión");
    } finally {
      setSavingOnboarding(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[40vh]">
        <Loader2 className="h-8 w-8 animate-spin text-blue-600" />
      </div>
    );
  }

  return (
    <div className="space-y-6 p-6">
      <div className="flex items-center gap-4">
        <Button
          size="icon"
          title="Volver al dashboard"
          variant="ghost"
          onClick={() => router.push("/admin/saas-management/dashboard")}
        >
          <ArrowLeft className="h-5 w-5" />
        </Button>
        <div>
          <h1 className="text-3xl font-display font-bold text-epoch-primary tracking-tight">
            Configuración SaaS
          </h1>
          <p className="text-muted-foreground mt-2">
            Parámetros por defecto del período de prueba y suscripciones
          </p>
        </div>
      </div>

      <Card className="admin-card">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Calendar className="h-5 w-5" />
            Período de prueba por defecto
          </CardTitle>
          <p className="text-sm text-muted-foreground">
            Número de días de prueba gratuita que se asignan a cada nueva
            organización al completar el onboarding. Este valor se usa cuando no
            se define un override por organización.
          </p>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex flex-wrap items-end gap-4">
            <div className="space-y-2 w-40">
              <Label htmlFor="trial_days">Días de prueba</Label>
              <Input
                id="trial_days"
                max={365}
                min={1}
                type="number"
                value={trialDays}
                onChange={(e) => setTrialDays(e.target.value)}
              />
            </div>
            <Button disabled={saving} onClick={handleSave}>
              {saving ? (
                <Loader2 className="h-4 w-4 animate-spin mr-2" />
              ) : (
                <Save className="h-4 w-4 mr-2" />
              )}
              Guardar
            </Button>
          </div>
        </CardContent>
      </Card>

      <Card className="admin-card">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Users className="h-5 w-5" />
            Flujos de onboarding (Etapa 1)
          </CardTitle>
          <p className="text-sm text-muted-foreground">
            Controla el signup público y el modo de flujos duales (ópticas
            conocidas vs orgánicos). Durante la etapa 1, el signup suele estar
            deshabilitado; las ópticas conocidas usan /acceso-opticas.
          </p>
        </CardHeader>
        <CardContent className="space-y-6">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
            <div>
              <Label className="text-base font-medium">
                Signup público habilitado
              </Label>
              <p className="text-sm text-muted-foreground">
                Si está activo, cualquiera puede registrarse en /signup. Si está
                desactivado, se redirige a /solicitar-demo.
              </p>
            </div>
            <Switch
              checked={signupEnabled}
              disabled={savingOnboarding}
              onCheckedChange={setSignupEnabled}
            />
          </div>
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
            <div>
              <Label className="text-base font-medium">
                Modo etapa 1 (flujos duales)
              </Label>
              <p className="text-sm text-muted-foreground">
                Indica que estamos en etapa 1: ópticas conocidas vía
                /acceso-opticas, orgánicos vía aprobación root.
              </p>
            </div>
            <Switch
              checked={onboardingStageMode}
              disabled={savingOnboarding}
              onCheckedChange={setOnboardingStageMode}
            />
          </div>
          <Button
            className="mt-2"
            disabled={savingOnboarding}
            onClick={handleSaveOnboarding}
          >
            {savingOnboarding ? (
              <Loader2 className="h-4 w-4 animate-spin mr-2" />
            ) : (
              <Save className="h-4 w-4 mr-2" />
            )}
            Guardar configuración onboarding
          </Button>
        </CardContent>
      </Card>

      <OpticasTokensSection />
    </div>
  );
}

"use client";

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";

interface SaasMetrics {
  totalOrganizations: number;
  activeOrganizations: number;
  totalUsers: number;
  activeUsers: number;
  totalSubscriptions: number;
  activeSubscriptions: number;
  monthlyRevenue: number;
  annualRevenue: number;
  organizationGrowth: number;
  trialConversionRate: number;
  tierDistribution?: Record<string, number>;
  organizationsLast30Days?: number;
}

interface SaaSChartsProps {
  metrics: SaasMetrics;
}

export function SaaSCharts({ metrics }: SaaSChartsProps) {
  return (
    <>
      {/* Distribución por tier */}
      {metrics.tierDistribution && (
        <Card className="bg-white/5 border-white/10">
          <CardHeader>
            <CardTitle className="text-white">
              Distribución por Tier
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              {Object.entries(metrics.tierDistribution).map(([tier, count]) => (
                <div
                  className="p-4 border border-white/10 rounded-lg text-center bg-white/5"
                  key={tier}
                >
                  <div className="text-2xl font-bold text-white">{count}</div>
                  <div className="text-sm text-white/50 mt-1">
                    {tier === "basic"
                      ? "Básico"
                      : tier === "pro"
