          <CardContent>
            <div className="space-y-4">
              <div>
                <div className="text-sm text-white/50">
                  Organizaciones creadas (últimos 30 días)
                </div>
                <div className="text-2xl font-bold text-white">
                  {metrics.organizationsLast30Days}
                </div>
              </div>
              <div>
                <div className="text-sm text-white/50">
                  Crecimiento mensual
                </div>
                <div className="text-2xl font-bold text-emerald-400">
                  {metrics.organizationGrowth > 0 ? "+" : ""}
                  {metrics.organizationGrowth.toFixed(1)}%
                </div>
              </div>
            </div>
          </CardContent>
        </Card>
      )}
    </>
  );
}

"use client";

import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Card, CardContent } from "@/components/ui/card";
import { useAuthContext } from "@/contexts/AuthContext";
import { appLogger } from "@/lib/logger";
import { useTelemetry } from "@/lib/telemetry/hooks/use-telemetry";

import { SaaSCharts } from "./SaaSCharts";
import { SaaSRecentActivity } from "./SaaSRecentActivity";
import { SaaSStatsCards } from "./SaaSStatsCards";

interface SaasMetrics {
  totalOrganizations: number;
  activeOrganizations: number;
  totalUsers: number;
  activeUsers: number;
  totalSubscriptions: number;
  activeSubscriptions: number;
  monthlyRevenue: number;
  annualRevenue: number;
  organizationGrowth: number;
  trialConversionRate: number;
  tierDistribution?: Record<string, number>;
  organizationsLast30Days?: number;
}

export default function SaaSDashboardContent({
  initialUser,
}: {
  initialUser: { id: string; email?: string } | null;
}) {
  const [loading, setLoading] = useState(true);
  const [metrics, setMetrics] = useState<SaasMetrics | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isAuthorized, setIsAuthorized] = useState<boolean | null>(
    initialUser ? true : null,
  );
  const [telemetryEnabled, setTelemetryEnabled] = useState(true);
  const [updatingTelemetry, setUpdatingTelemetry] = useState(false);
  const [showResetDemoDialog, setShowResetDemoDialog] = useState(false);
  const [resettingDemo, setResettingDemo] = useState(false);
  const { trackFeatureUsage } = useTelemetry("saas-dashboard");
  const { user } = useAuthContext();
  const router = useRouter();

  useEffect(() => {
    if (user === undefined) return;
    const authorized = !!user;
    if (isAuthorized !== authorized) {
      setIsAuthorized(authorized);
    }
    if (!user && isAuthorized !== false) {
      router.push("/unauthorized");
    }
  }, [user, isAuthorized, router]);

  useEffect(() => {
    if (!isAuthorized) return;

    const fetchTelemetryConfig = async () => {
      try {
        const response = await fetch(
          "/api/admin/saas-management/telemetry-config",
        );
        if (response.ok) {
          const data = await response.json();
          setTelemetryEnabled(data.enabled);
        }
      } catch (err) {
        appLogger.error("Error fetching telemetry config:", err);
      }
    };

    fetchTelemetryConfig();
  }, [isAuthorized]);

  const handleResetDemo = async () => {
    try {
      setResettingDemo(true);
      const response = await fetch("/api/admin/saas-management/reset-demo", {
        method: "POST",
      });
      if (response.ok) {
        toast.success("Óptica Demo reseteada correctamente");
        setShowResetDemoDialog(false);
        trackFeatureUsage("admin_reset_demo");
      } else {
        const data = await response.json();
        toast.error(
          data.details || data.error || "Error al resetear la Óptica Demo",
        );
      }
    } catch (err) {
      toast.error("Error al resetear la Óptica Demo");
      appLogger.error(err);
    } finally {
      setResettingDemo(false);
    }
  };

  const handleToggleTelemetry = async (enabled: boolean) => {
    try {
      setUpdatingTelemetry(true);
      const response = await fetch(
        "/api/admin/saas-management/telemetry-config",
        {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ enabled }),
        },
      );

      if (response.ok) {
        setTelemetryEnabled(enabled);
        toast.success(
          `Telemetría ${enabled ? "activada" : "desactivada"} globalmente`,
        );
        trackFeatureUsage("admin_telemetry_toggle", { enabled });
      } else {
        throw new Error("Error al actualizar configuración");
      }
    } catch (err) {
      toast.error("No se pudo actualizar la configuración de telemetría");
      appLogger.error(err);
    } finally {
      setUpdatingTelemetry(false);
    }
  };

  useEffect(() => {
    if (!isAuthorized) return;
    if (typeof window !== "undefined") {
      trackFeatureUsage("usage_dashboard_view");
    }
  }, [trackFeatureUsage, isAuthorized]);

  useEffect(() => {
    if (!isAuthorized) return;

    const fetchMetrics = async () => {
      try {
        setLoading(true);
        const response = await fetch("/api/admin/saas-management/analytics");

        if (!response.ok) {
          throw new Error("Error al cargar métricas");
        }

        const data = await response.json();
        setMetrics(data.metrics);
      } catch (err) {
        setError(err instanceof Error ? err.message : "Error desconocido");
      } finally {
        setLoading(false);
      }
    };

    fetchMetrics();
  }, [isAuthorized]);

  if (loading || isAuthorized === null) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center space-y-4">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-epoch-primary mx-auto" />
          <p className="text-epoch-primary/70">Cargando métricas del SaaS...</p>
        </div>
      </div>
    );
  }

  if (isAuthorized === false) {
    return (
      <div className="p-6">
        <Alert variant="destructive">
          <AlertDescription>
            Access denied. You don&apos;t have permission to view this
            dashboard.
          </AlertDescription>
        </Alert>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-6">
        <Card className="admin-card">
          <CardContent className="pt-6">
            <div className="text-center text-red-600">
              <p>Error: {error}</p>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="space-y-6 p-6">
      <div>
        <h1 className="text-3xl font-display font-bold text-white tracking-tight">
          SaaS Engine
        </h1>
        <p className="text-white/50 mt-2">
          Dashboard principal con métricas del sistema completo
        </p>
      </div>

      {metrics && <SaaSStatsCards metrics={metrics} />}

      {metrics && <SaaSCharts metrics={metrics} />}

      <SaaSRecentActivity
        resettingDemo={resettingDemo}
        showResetDemoDialog={showResetDemoDialog}
        telemetryEnabled={telemetryEnabled}
        updatingTelemetry={updatingTelemetry}
        onResetDemo={handleResetDemo}
        onShowResetDemoDialogChange={setShowResetDemoDialog}
        onToggleTelemetry={handleToggleTelemetry}
      />
    </div>
  );
}

import { Menu } from "lucide-react";
import { redirect } from "next/navigation";
import { ReactNode } from "react";

import { SaasManagementSidebar } from "@/components/admin/saas-management/SaasManagementSidebar";
import { Button } from "@/components/ui/button";
import { Sheet, SheetContent, SheetTrigger } from "@/components/ui/sheet";
import { createRootAdminClient } from "@/utils/supabase/root-admin";
import { createClient } from "@/utils/supabase/server";

interface SaasManagementLayoutProps {
  children: ReactNode;
}

export default async function SaasManagementLayout({
  children,
}: SaasManagementLayoutProps) {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();

  if (!user) {
    redirect("/login");
  }

  // Verificar si el usuario es root/dev usando service role
  const supabaseServiceRole = createRootAdminClient();
  const { data: adminUser } = await supabaseServiceRole
    .from("admin_users")
    .select("role, email")
    .eq("id", user.id)
    .single();

  const isRoot = adminUser?.role === "root" || adminUser?.role === "dev";

  if (!isRoot) {
    redirect("/admin");
  }

  return (
    <div className="flex h-screen bg-[#0D1117]">
      {/* Sidebar - Desktop */}
      <aside className="hidden lg:flex w-[280px] flex-shrink-0">
        <SaasManagementSidebar />
      </aside>

      {/* Contenido Principal */}
      <main className="flex-1 flex flex-col min-h-0 overflow-hidden">
        {/* Mobile Header */}
        <header className="lg:hidden flex items-center justify-between px-4 py-3 border-b border-white/10 bg-[#0D1117]">
          {/* Mobile Menu Button */}
          <Sheet>
            <SheetTrigger asChild>
              <Button
                className="text-white hover:bg-white/10"
                size="icon"
                variant="ghost"
              >
                <Menu className="h-5 w-5" />
              </Button>
            </SheetTrigger>
            <SheetContent
              className="p-0 w-[300px] bg-[#0D1117] border-r border-white/10"
              side="left"
            >
              <SaasManagementSidebar />
            </SheetContent>
          </Sheet>

          <div className="flex items-center gap-2">
            <div className="h-8 w-8 rounded-lg bg-gradient-to-br from-[#C5A059] to-[#8B7355] flex items-center justify-center">
              <svg
                className="text-[#0D1117]"
                fill="none"
                height="18"
                stroke="currentColor"
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth="2.5"
                viewBox="0 0 24 24"
                width="18"
                xmlns="http://www.w3.org/2000/svg"
              >
                <polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2" />
              </svg>
            </div>
            <span className="text-white font-bold font-display">
              SaaS Engine
            </span>
          </div>

          {/* Spacer for balance */}
          <div className="w-10" />
        </header>

        {/* Page Content */}
        <div className="flex-1 overflow-y-auto">{children}</div>
      </main>
    </div>
  );
}

"use client";

import { Trash2 } from "lucide-react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";

import { STAGE_COLORS, STAGE_LABELS } from "./constants";
import type { DemoRequest, FunnelStage } from "./types";

interface FunnelForm {
  meeting_url: string;
  meeting_scheduled_at: string;
  notes: string;
  offer_type: string;
  lost_reason: string;
}

interface FunnelDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  selectedRequest: DemoRequest | null;
  funnelForm: FunnelForm;
  onFormChange: (field: keyof FunnelForm, value: string) => void;
  onFunnelUpdate: (
    id: string,
    stage: FunnelStage,
    extra?: Record<string, unknown>,
  ) => void;
  onDeleteClick: (r: DemoRequest) => void;
  actioning: string | null;
}

export function FunnelDialog({
  open,
  onOpenChange,
  selectedRequest,
  funnelForm,
  onFormChange,
  onFunnelUpdate,
  onDeleteClick,
  actioning,
}: FunnelDialogProps) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle>Detalle del lead</DialogTitle>
        </DialogHeader>
        {selectedRequest && (
          <div className="space-y-4">
            <div>
              <p className="text-sm font-medium">Email</p>
              <p className="text-white/50">{selectedRequest.email}</p>
            </div>
            <div>
              <p className="text-sm font-medium">Nombre / Óptica</p>
              <p className="text-white/50">
                {selectedRequest.full_name || "—"} /{" "}
                {selectedRequest.optica_name || "—"}
              </p>
            </div>
            <div>
              <p className="text-sm font-medium">Etapa actual</p>
              <Badge
                className={
                  STAGE_COLORS[selectedRequest.funnel_stage || "pending"] || ""
                }
                variant="secondary"
              >
                {STAGE_LABELS[selectedRequest.funnel_stage || "pending"]}
              </Badge>
            </div>
            <div>
              <p className="text-sm font-medium">URL de reunión</p>
              <input
                className="w-full px-3 py-2 border rounded-md text-sm"
                placeholder="https://meet.google.com/..."
                type="url"
                value={funnelForm.meeting_url}
                onChange={(e) =>
                  onFormChange("meeting_url", e.target.value)
                }
              />
            </div>
            <div>
              <p className="text-sm font-medium">Notas</p>
              <textarea
                className="w-full px-3 py-2 border rounded-md text-sm min-h-[80px]"
                placeholder="Notas del lead..."
                value={funnelForm.notes}
                onChange={(e) => onFormChange("notes", e.target.value)}
              />
            </div>
            <div className="flex flex-wrap gap-2 pt-4">
              {["approved", "demo_expiring", "demo_expired"].includes(
                selectedRequest.funnel_stage || "",
              ) && (
                <Button
                  disabled={actioning === selectedRequest.id}
                  size="sm"
                  onClick={() => {
                    const url =
                      funnelForm.meeting_url?.trim() ||
                      (typeof window !== "undefined"
                        ? `${window.location.origin}/contacto`
                        : "https://www.opttius.cl/contacto");
                    onFunnelUpdate(
                      selectedRequest.id,
                      "meeting_scheduled",
                      {
                        meeting_url: url,
                        meeting_scheduled_at:
                          funnelForm.meeting_scheduled_at ||
                          new Date().toISOString(),
                      },
                    );
                  }}
                >
                  Agendar reunión
                </Button>
              )}
              {selectedRequest.funnel_stage === "meeting_scheduled" && (
                <Button
                  disabled={actioning === selectedRequest.id}
                  size="sm"
                  onClick={() =>
                    onFunnelUpdate(selectedRequest.id, "post_meeting", {
                      notes: funnelForm.notes || undefined,
                    })
                  }
                >
                  Reunión completada
                </Button>
              )}
              {selectedRequest.funnel_stage === "post_meeting" && (
                <Button
                  disabled={actioning === selectedRequest.id}
                  size="sm"
                  onClick={() =>
                    onFunnelUpdate(selectedRequest.id, "negotiation", {
                      notes: funnelForm.notes || undefined,
                    })
                  }
                >
                  Enviar oferta
                </Button>
              )}
              {selectedRequest.funnel_stage === "negotiation" && (
                <Button
                  disabled={actioning === selectedRequest.id}
                  size="sm"
                  onClick={() =>
                    onFunnelUpdate(selectedRequest.id, "migration", {
                      notes: funnelForm.notes || undefined,
                    })
                  }
                >
                  Iniciar migración
                </Button>
              )}
              {selectedRequest.funnel_stage === "migration" && (
                <Button
                  disabled={actioning === selectedRequest.id}
                  size="sm"
                  variant="default"
                  onClick={() =>
                    onFunnelUpdate(selectedRequest.id, "converted", {
                      notes: funnelForm.notes || undefined,
                    })
                  }
                >
                  Marcar convertido
                </Button>
              )}
              {[
                "demo_expired",
                "meeting_scheduled",
                "post_meeting",
                "negotiation",
              ].includes(selectedRequest.funnel_stage || "") && (
                <Button
                  disabled={actioning === selectedRequest.id}
                  size="sm"
                  variant="destructive"
                  onClick={() => {
                    const reason = prompt("Motivo de pérdida:");
                    if (reason !== null)
                      onFunnelUpdate(selectedRequest.id, "lost", {
                        lost_reason: reason || "Sin especificar",
                        notes: funnelForm.notes || undefined,
                      });
                  }}
                >
                  Marcar perdido
                </Button>
              )}
              <Button
                className="ml-auto"
                disabled={actioning === selectedRequest.id}
                size="sm"
                variant="destructive"
                onClick={() => {
                  onOpenChange(false);
                  onDeleteClick(selectedRequest);
                }}
              >
                <Trash2 className="h-4 w-4 mr-1" />
                Eliminar solicitud
              </Button>
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { ArrowLeft } from "lucide-react";
import { useRouter } from "next/navigation";

import {
  LeadAIGeneratorModal,
  type LeadAIGeneratorModalProps,
} from "@/components/admin/saas-management/leads/LeadAIGeneratorModal";
import {
  type LeadDetail,
  LeadDetailPanel,
} from "@/components/admin/saas-management/leads/LeadDetailPanel";
import {
  LeadEmailModal,
  type LeadEmailModalProps,
} from "@/components/admin/saas-management/leads/LeadEmailModal";
import { Button } from "@/components/ui/button";

import { DeleteConfirmDialog } from "./DeleteConfirmDialog";
import { FunnelDialog } from "./FunnelDialog";
import { PipelineSection } from "./PipelineSection";
import { StatsCards } from "./StatsCards";
import { useNewUsersFlow } from "./useNewUsersFlow";

export default function NewUsersFlowContent() {
  const router = useRouter();
  const {
    requests,
    stats,
    loading,
    actioning,
    tab,
    viewMode,
    selectedRequest,
    funnelModalOpen,
    funnelForm,
    deleteConfirmOpen,
    requestToDelete,
    detailPanelOpen,
    emailModalOpen,
    aiModalOpen,
    setTab,
    setViewMode,
    setFunnelModalOpen,
    setFunnelForm,
    setDeleteConfirmOpen,
    setRequestToDelete,
    setDetailPanelOpen,
    setEmailModalOpen,
    setAiModalOpen,
    handleApprove,
    handleDeleteClick,
    handleDeleteConfirm,
    handleReject,
    handleFunnelUpdate,
    handleKanbanStageChange,
    openLeadModal,
    openLegacyModal,
    handleSendEmail,
    handleGenerateAIEmail,
  } = useNewUsersFlow();

  return (
    <div className="min-h-screen bg-[#0D1117] space-y-6 p-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-display font-bold text-white tracking-tight">
            Pipeline de Leads
          </h1>
          <p className="text-white/50 mt-1">
            Gestiona tus leads y sigue el funnel de ventas
          </p>
        </div>
        <Button
          size="icon"
          title="Volver al dashboard"
          variant="outline"
          onClick={() => router.push("/admin/saas-management/dashboard")}
        >
          <ArrowLeft className="h-5 w-5" />
        </Button>
      </div>

      {stats && <StatsCards stats={stats} />}

      <PipelineSection
        actioning={actioning}
        loading={loading}
        requests={requests}
        tab={tab}
        viewMode={viewMode}
        onApprove={handleApprove}
        onDeleteClick={handleDeleteClick}
        onOpenLeadModal={openLegacyModal}
        onReject={handleReject}
        onStageChange={handleKanbanStageChange}
        onTabChange={setTab}
        onViewModeChange={setViewMode}
      />

      <FunnelDialog
        actioning={actioning}
        funnelForm={funnelForm}
        open={funnelModalOpen}
        selectedRequest={selectedRequest}
        onDeleteClick={handleDeleteClick}
        onFormChange={(field, value) =>
          setFunnelForm((f) => ({ ...f, [field]: value }))
        }
        onFunnelUpdate={handleFunnelUpdate}
        onOpenChange={setFunnelModalOpen}
      />

      <DeleteConfirmDialog
        actioning={actioning}
        open={deleteConfirmOpen}
        requestToDelete={requestToDelete}
        onCancel={() => {
          setDeleteConfirmOpen(false);
          setRequestToDelete(null);
        }}
        onDeleteConfirm={handleDeleteConfirm}
        onOpenChange={setDeleteConfirmOpen}
      />

      <LeadDetailPanel
        actioning={actioning}
        lead={selectedRequest as LeadDetail}
        open={detailPanelOpen}
        onApprove={handleApprove}
        onGenerateAIEmail={() => {
          setDetailPanelOpen(false);
          setAiModalOpen(true);
        }}
        onOpenChange={setDetailPanelOpen}
        onReject={handleReject}
        onSendEmail={() => {
          setDetailPanelOpen(false);
          setEmailModalOpen(true);
        }}
        onUpdateStage={handleFunnelUpdate}
      />

      <LeadEmailModal
        lead={selectedRequest as LeadEmailModalProps["lead"]}
        open={emailModalOpen}
        onOpenChange={setEmailModalOpen}
        onSend={handleSendEmail}
      />

      <LeadAIGeneratorModal
        lead={selectedRequest as LeadAIGeneratorModalProps["lead"]}
        open={aiModalOpen}
        onGenerate={handleGenerateAIEmail}
        onOpenChange={setAiModalOpen}
        onSend={handleSendEmail}
      />
    </div>
  );
}

"use client";

import {
  CheckCircle2,
  FileText,
  LayoutGrid,
  List,
  Loader2,
  Target,
  Trash2,
  Video,
  XCircle,
} from "lucide-react";

import { LeadKanbanBoard } from "@/components/admin/saas-management/leads/LeadKanbanBoard";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";

import { STAGE_COLORS, STAGE_LABELS } from "./constants";
import type { DemoRequest, FunnelStage } from "./types";

interface PipelineSectionProps {
  requests: DemoRequest[];
  loading: boolean;
  tab: "activos" | "convertidos" | "perdidos";
  onTabChange: (tab: "activos" | "convertidos" | "perdidos") => void;
  viewMode: "kanban" | "table";
  onViewModeChange: (mode: "kanban" | "table") => void;
  onApprove: (id: string) => void;
  onReject: (id: string) => void;
  onOpenLeadModal: (r: DemoRequest) => void;
  onDeleteClick: (r: DemoRequest) => void;
  onStageChange: (leadId: string, newStage: FunnelStage) => void;
  actioning: string | null;
}

function formatDate(s: string | null) {
  if (!s) return "—";
  const d = new Date(s);
  return d.toLocaleDateString("es-CL", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
}

function daysInDemo(r: DemoRequest) {
  if (!r.demo_started_at || !r.demo_expires_at) return null;
  const start = new Date(r.demo_started_at);
  const end = new Date(r.demo_expires_at);
  const now = new Date();
  if (now > end)
    return {
      days: Math.ceil((end.getTime() - start.getTime()) / 86400000),
      expired: true,
    };
  return {
    days: Math.ceil((now.getTime() - start.getTime()) / 86400000),
    expired: false,
  };
}

export function PipelineSection({
  requests,
  loading,
  tab,
  onTabChange,
  viewMode,
  onViewModeChange,
  onApprove,
  onReject,
  onOpenLeadModal,
  onDeleteClick,
  onStageChange,
  actioning,
}: PipelineSectionProps) {
  return (
    <Card className="bg-white/5 border-white/10">
      <CardHeader>
        <CardTitle className="flex items-center gap-2 text-white">
          <Target className="h-5 w-5 text-amber-400" />
          Pipeline de Ventas
        </CardTitle>
        <p className="text-sm text-white/50">
          Gestiona cada etapa del funnel hasta la conversión.
        </p>
        <div className="flex gap-2 mt-4">
          {(["activos", "convertidos", "perdidos"] as const).map((t) => (
            <Button
              key={t}
              size="sm"
              variant={tab === t ? "default" : "outline"}
              onClick={() => onTabChange(t)}
            >
              {t === "activos" && "Activos"}
              {t === "convertidos" && "Convertidos"}
              {t === "perdidos" && "Perdidos/Rechazados"}
            </Button>
          ))}
          <div className="ml-auto flex gap-1 border rounded-md p-1">
            <Button
              size="sm"
              title="Vista Kanban"
              variant={viewMode === "kanban" ? "default" : "ghost"}
              onClick={() => onViewModeChange("kanban")}
            >
              <LayoutGrid className="h-4 w-4" />
            </Button>
            <Button
              size="sm"
              title="Vista Tabla"
              variant={viewMode === "table" ? "default" : "ghost"}
              onClick={() => onViewModeChange("table")}
            >
              <List className="h-4 w-4" />
            </Button>
          </div>
        </div>
      </CardHeader>
      <CardContent>
        {loading ? (
          <div className="flex justify-center py-12">
            <Loader2 className="h-8 w-8 animate-spin text-white/50" />
          </div>
        ) : requests.length === 0 ? (
          <p className="text-center py-8 text-white/50">
            No hay solicitudes en esta categoría
          </p>
        ) : viewMode === "kanban" ? (
          <LeadKanbanBoard
            leads={requests}
            loading={loading}
            onLeadClick={(lead) => onOpenLeadModal(lead as DemoRequest)}
            onStageChange={(leadId, newStage) =>
              onStageChange(leadId, newStage as FunnelStage)
            }
          />
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-white/10">
                  <th className="text-left py-3 px-2 text-white/70">Email</th>
                  <th className="text-left py-3 px-2 text-white/70">
                    Nombre / Óptica
                  </th>
                  <th className="text-left py-3 px-2 text-white/70">Etapa</th>
                  <th className="text-left py-3 px-2 text-white/70">Score</th>
                  <th className="text-left py-3 px-2 text-white/70">
                    Último contacto
                  </th>
                  <th className="text-right py-3 px-2 text-white/70">
                    Acciones
                  </th>
                </tr>
              </thead>
              <tbody>
                {requests.map((r) => {
                  const stage = r.funnel_stage || "pending";
                  const days = daysInDemo(r);
                  return (
                    <tr
                      className="border-b border-white/10 hover:bg-white/5 cursor-pointer"
                      key={r.id}
                      onClick={() => onOpenLeadModal(r)}
                    >
                      <td className="py-3 px-2 text-white">{r.email}</td>
                      <td className="py-3 px-2">
                        <div className="text-white">
                          {r.full_name || "—"}
                        </div>
                        {r.optica_name && (
                          <div className="text-xs text-white/50">
                            {r.optica_name}
                          </div>
                        )}
                      </td>
                      <td className="py-3 px-2">
                        <Badge
                          className={`${STAGE_COLORS[stage] || ""} bg-opacity-20 text-white border-0`}
                          variant="secondary"
                        >
                          {STAGE_LABELS[stage] || stage}
                        </Badge>
                      </td>
                      <td className="py-3 px-2">
                        {r.lead_score !== undefined && r.lead_score > 0 ? (
                          <span className="text-amber-400 font-medium">
                            {r.lead_score}
                          </span>
                        ) : (
                          <span className="text-white/30">—</span>
                        )}
                      </td>
                      <td className="py-3 px-2 text-white/70">
                        {formatDate(r.last_contact_at || r.created_at)}
                      </td>
                      <td
                        className="py-3 px-2 text-right"
                        onClick={(e) => e.stopPropagation()}
                      >
                        <div className="flex gap-2 justify-end">
                          {stage === "pending" && (
                            <>
                              <Button
                                disabled={actioning === r.id}
                                size="sm"
                                variant="default"
                                onClick={() => onApprove(r.id)}
                              >
                                {actioning === r.id ? (
                                  <Loader2 className="h-4 w-4 animate-spin" />
                                ) : (
                                  <>
                                    <CheckCircle2 className="h-4 w-4 mr-1" />
                                    Aprobar
                                  </>
                                )}
                              </Button>
                              <Button
                                disabled={actioning === r.id}
                                size="sm"
                                variant="outline"
                                onClick={() => onReject(r.id)}
                              >
                                <XCircle className="h-4 w-4 mr-1" />
                                Rechazar
                              </Button>
                            </>
                          )}
                          {[
                            "approved",
                            "demo_expiring",
                            "demo_expired",
                          ].includes(stage) && (
                            <Button
                              size="sm"
                              variant="outline"
                              onClick={() => onOpenLeadModal(r)}
                            >
                              <Video className="h-4 w-4 mr-1" />
                              Reunión
                            </Button>
                          )}
                          {[
                            "meeting_scheduled",
                            "post_meeting",
                            "negotiation",
                            "migration",
                          ].includes(stage) && (
                            <Button
                              size="sm"
                              variant="outline"
                              onClick={() => onOpenLeadModal(r)}
                            >
                              <FileText className="h-4 w-4 mr-1" />
                              Ver
                            </Button>
                          )}
                          <Button
                            className="text-destructive hover:text-destructive hover:bg-destructive/10"
                            disabled={actioning === r.id}
                            size="sm"
                            title="Eliminar solicitud"
                            variant="ghost"
                            onClick={(e) => {
                              e.stopPropagation();
                              onDeleteClick(r);
                            }}
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import { useCallback, useEffect, useState } from "react";
import { toast } from "sonner";

import type { DemoRequest, FunnelStage, Stats } from "./types";

const ACTIVE_STAGES =
  "pending,approved,demo_expiring,demo_expired,meeting_scheduled,post_meeting,negotiation,migration";
const CONVERTED_STAGES = "converted";
const LOST_STAGES = "rejected,lost";

export function useNewUsersFlow() {
  const [requests, setRequests] = useState<DemoRequest[]>([]);
  const [stats, setStats] = useState<Stats | null>(null);
  const [loading, setLoading] = useState(true);
  const [actioning, setActioning] = useState<string | null>(null);
  const [tab, setTab] = useState<"activos" | "convertidos" | "perdidos">(
    "activos",
  );
  const [viewMode, setViewMode] = useState<"kanban" | "table">("kanban");
  const [selectedRequest, setSelectedRequest] = useState<DemoRequest | null>(
    null,
  );
  const [funnelModalOpen, setFunnelModalOpen] = useState(false);
  const [funnelForm, setFunnelForm] = useState({
    meeting_url: "",
    meeting_scheduled_at: "",
    notes: "",
    offer_type: "",
    lost_reason: "",
  });
  const [deleteConfirmOpen, setDeleteConfirmOpen] = useState(false);
  const [requestToDelete, setRequestToDelete] = useState<DemoRequest | null>(
    null,
  );
  const [detailPanelOpen, setDetailPanelOpen] = useState(false);
  const [emailModalOpen, setEmailModalOpen] = useState(false);
  const [aiModalOpen, setAiModalOpen] = useState(false);

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const stagesParam =
        tab === "activos"
          ? `funnel_stages=${ACTIVE_STAGES}`
          : tab === "convertidos"
            ? `funnel_stages=${CONVERTED_STAGES}`
            : `funnel_stages=${LOST_STAGES}`;

      const [reqRes, statsRes] = await Promise.all([
        fetch(
          `/api/admin/saas-management/demo-requests?${stagesParam}&limit=100`,
        ),
        fetch("/api/admin/saas-management/new-users-flow/stats"),
      ]);

      if (reqRes.ok) {
        const data = await reqRes.json();
        setRequests(data.requests ?? []);
      } else {
        const errorData = await reqRes.json();
        toast.error(errorData.error || "Error al cargar solicitudes");
      }
      if (statsRes.ok) {
        const data = await statsRes.json();
        setStats(data);
      }
    } catch {
      toast.error("Error al cargar datos");
    } finally {
      setLoading(false);
    }
  }, [tab]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const handleApprove = useCallback(
    async (id: string) => {
      setActioning(id);
      try {
        const res = await fetch(
          `/api/admin/saas-management/demo-requests/${id}/approve`,
          { method: "POST" },
        );
        const data = await res.json();
        if (res.ok) {
          toast.success(data.message ?? "Demo aprobada");
          fetchData();
        } else {
          toast.error(
            data.details
              ? `${data.error ?? "Error"}: ${data.details}`
              : (data.error ?? "Error al aprobar"),
          );
        }
      } catch {
        toast.error("Error al aprobar");
      } finally {
        setActioning(null);
      }
    },
    [fetchData],
  );

  const handleDeleteClick = useCallback((r: DemoRequest) => {
    setRequestToDelete(r);
    setDeleteConfirmOpen(true);
  }, []);

  const handleDeleteConfirm = useCallback(async () => {
    if (!requestToDelete) return;
    setActioning(requestToDelete.id);
    try {
      const res = await fetch(
        `/api/admin/saas-management/demo-requests/${requestToDelete.id}/delete`,
        { method: "DELETE" },
      );
      const data = await res.json();
      if (res.ok) {
        toast.success(data.message ?? "Solicitud eliminada");
        setDeleteConfirmOpen(false);
        setRequestToDelete(null);
        setFunnelModalOpen(false);
        setSelectedRequest(null);
        fetchData();
      } else {
        toast.error(
          data.details
            ? `${data.error ?? "Error"}: ${data.details}`
            : (data.error ?? "Error al eliminar"),
        );
      }
    } catch {
      toast.error("Error al eliminar");
    } finally {
      setActioning(null);
    }
  }, [requestToDelete, fetchData]);

  const handleReject = useCallback(
    async (id: string) => {
      setActioning(id);
      try {
        const res = await fetch(
          `/api/admin/saas-management/demo-requests/${id}/reject`,
          { method: "POST" },
        );
        const data = await res.json();
        if (res.ok) {
          toast.success("Solicitud rechazada");
          fetchData();
        } else {
          toast.error(data.error ?? "Error al rechazar");
        }
      } catch {
        toast.error("Error al rechazar");
      } finally {
        setActioning(null);
      }
    },
    [fetchData],
  );

  const handleFunnelUpdate = useCallback(
    async (
      id: string,
      funnel_stage: FunnelStage,
      extra?: Record<string, unknown>,
    ) => {
      setActioning(id);
      try {
        const res = await fetch(
          `/api/admin/saas-management/demo-requests/${id}/funnel`,
          {
            method: "PATCH",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ funnel_stage, ...extra }),
          },
        );
        const data = await res.json();
        if (res.ok) {
          toast.success(data.message ?? "Etapa actualizada");
          setFunnelModalOpen(false);
          setSelectedRequest(null);
          fetchData();
        } else {
          toast.error(data.error ?? "Error al actualizar");
        }
      } catch {
        toast.error("Error al actualizar");
      } finally {
        setActioning(null);
      }
    },
    [fetchData],
  );

  const handleKanbanStageChange = useCallback(
    async (leadId: string, newStage: FunnelStage) => {
      await handleFunnelUpdate(leadId, newStage);
    },
    [handleFunnelUpdate],
  );

  const openLeadModal = useCallback((r: DemoRequest) => {
    setSelectedRequest(r);
    setDetailPanelOpen(true);
  }, []);

  const openLegacyModal = useCallback((r: DemoRequest) => {
    setSelectedRequest(r);
    setFunnelForm({
      meeting_url: r.meeting_url ?? "",
      meeting_scheduled_at: r.meeting_scheduled_at
        ? r.meeting_scheduled_at.slice(0, 16)
        : "",
      notes: r.notes ?? "",
      offer_type: r.offer_type ?? "",
      lost_reason: r.lost_reason ?? "",
    });
    setFunnelModalOpen(true);
  }, []);

  const handleSendEmail = useCallback(
    async (leadId: string, subject: string, body: string) => {
      const res = await fetch(
        `/api/admin/saas-management/leads/${leadId}/email/send`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ subject, body }),
        },
      );
      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.error || "Error al enviar");
      }
      toast.success("Email enviado correctamente");
      fetchData();
    },
    [fetchData],
  );

  const handleGenerateAIEmail = useCallback(
    async (leadId: string, prompt: string) => {
      const res = await fetch(
        `/api/admin/saas-management/leads/${leadId}/email/generate`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ prompt }),
        },
      );
      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.error || "Error al generar");
      }
      return { subject: data.subject, body: data.body };
    },
    [],
  );

  return {
    requests,
    stats,
    loading,
    actioning,
    tab,
    viewMode,
    selectedRequest,
    funnelModalOpen,
    funnelForm,
    deleteConfirmOpen,
    requestToDelete,
    detailPanelOpen,
    emailModalOpen,
    aiModalOpen,
    setTab,
    setViewMode,
    setSelectedRequest,
    setFunnelModalOpen,
    setFunnelForm,
    setDeleteConfirmOpen,
    setRequestToDelete,
    setDetailPanelOpen,
    setEmailModalOpen,
    setAiModalOpen,
    fetchData,
    handleApprove,
    handleDeleteClick,
    handleDeleteConfirm,
    handleReject,
    handleFunnelUpdate,
    handleKanbanStageChange,
    openLeadModal,
    openLegacyModal,
    handleSendEmail,
    handleGenerateAIEmail,
  };
}

"use client";

import { AlertTriangle } from "lucide-react";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";

interface BranchFormData {
  name: string;
  code: string;
  address_line_1: string;
  city: string;
  phone: string;
  email: string;
  is_active: boolean;
}

interface OrgBranchDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  editingBranch: unknown;
  branchFormData: BranchFormData;
  onFormChange: (data: Partial<BranchFormData>) => void;
  onSave: () => void;
}

export function OrgBranchDialog({
  open,
  onOpenChange,
  editingBranch,
  branchFormData,
  onFormChange,
  onSave,
}: OrgBranchDialogProps) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-[calc(100vw-2rem)] sm:max-w-2xl">
        <DialogHeader>
          <DialogTitle>
            {editingBranch ? "Editar Sucursal" : "Nueva Sucursal"}
          </DialogTitle>
          <DialogDescription>
            {editingBranch
              ? "Modifica los datos de la sucursal"
