        </DialogHeader>
        <div className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-sm font-medium">Nombre *</label>
              <Input
                placeholder="Nombre sucursal"
                value={branchFormData.name}
                onChange={(e) => onFormChange({ name: e.target.value })}
              />
            </div>
            <div>
              <label className="text-sm font-medium">Código *</label>
              <Input
                placeholder="Ej: SUC-001"
                value={branchFormData.code}
                onChange={(e) => onFormChange({ code: e.target.value })}
              />
            </div>
          </div>
          <div>
            <label className="text-sm font-medium">Dirección</label>
            <Input
              placeholder="Dirección"
              value={branchFormData.address_line_1}
              onChange={(e) => onFormChange({ address_line_1: e.target.value })}
            />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-sm font-medium">Ciudad</label>
              <Input
                placeholder="Ciudad"
                value={branchFormData.city}
                onChange={(e) => onFormChange({ city: e.target.value })}
              />
            </div>
            <div>
              <label className="text-sm font-medium">Teléfono</label>
              <Input
                placeholder="Teléfono"
                value={branchFormData.phone}
                onChange={(e) => onFormChange({ phone: e.target.value })}
              />
            </div>
          </div>
          <div>
            <label className="text-sm font-medium">Email</label>
            <Input
              placeholder="email@sucursal.cl"
              type="email"
              value={branchFormData.email}
              onChange={(e) => onFormChange({ email: e.target.value })}
            />
          </div>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancelar
          </Button>
          <Button onClick={onSave}>
            {editingBranch ? "Guardar Cambios" : "Crear Sucursal"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

export function OrgBranchDeleteDialog({
  open,
  onOpenChange,
  onConfirm,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onConfirm: () => void;
}) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-[calc(100vw-2rem)] sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <AlertTriangle className="h-5 w-5 text-red-500" />
            Eliminar sucursal
          </DialogTitle>
          <DialogDescription>
            ¿Estás seguro de eliminar esta sucursal? Esta acción no se puede
            deshacer.
          </DialogDescription>
        </DialogHeader>
        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancelar
          </Button>
          <Button variant="destructive" onClick={onConfirm}>
            Eliminar
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { Edit, Plus, Trash2 } from "lucide-react";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

import { OrgBranchDeleteDialog,OrgBranchDialog } from "./OrgBranchDialog";

interface BranchFormData {
  name: string;
  code: string;
  address_line_1: string;
  city: string;
  phone: string;
  email: string;
  is_active: boolean;
}

interface OrgBranchesTabProps {
  orgId: string;
  onOrgUpdate?: () => void;
}

export default function OrgBranchesTab({
  orgId,
  onOrgUpdate,
}: OrgBranchesTabProps) {
  const [branches, setBranches] = useState<Array<unknown>>([]);
  const [showBranchDialog, setShowBranchDialog] = useState(false);
  const [editingBranch, setEditingBranch] = useState<unknown>(null);
  const [branchFormData, setBranchFormData] = useState({
    name: "",
    code: "",
    address_line_1: "",
    city: "",
    phone: "",
    email: "",
    is_active: true,
  });
  const [deleteBranchConfirmId, setDeleteBranchConfirmId] = useState<
    string | null
  >(null);

  useEffect(() => {
    fetchBranches();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [orgId]);

  const fetchBranches = async () => {
    try {
      const response = await fetch(
        `/api/admin/saas-management/organizations/${orgId}/branches`,
      );
      if (!response.ok) throw new Error("Error al cargar sucursales");
      const data = await response.json();
      setBranches(data.branches || []);
    } catch {
      toast.error("Error al cargar sucursales");
    }
  };

  const handleCreateBranch = async () => {
    try {
      const response = await fetch(
        `/api/admin/saas-management/organizations/${orgId}/branches`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(branchFormData),
        },
      );

      const data = await response.json();
      if (!response.ok)
        throw new Error(data.error || "Error al crear sucursal");

      toast.success("Sucursal creada exitosamente");
      setShowBranchDialog(false);
      setBranchFormData({
        name: "",
        code: "",
        address_line_1: "",
        city: "",
        phone: "",
        email: "",
        is_active: true,
      });
      fetchBranches();
      onOrgUpdate?.();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Error desconocido");
    }
  };

  const handleUpdateBranch = async () => {
    if (!editingBranch) return;
    try {
      const response = await fetch(
        `/api/admin/saas-management/organizations/${orgId}/branches/${editingBranch.id}`,
        {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(branchFormData),
        },
      );

      const data = await response.json();
      if (!response.ok)
        throw new Error(data.error || "Error al actualizar sucursal");

      toast.success("Sucursal actualizada exitosamente");
      setShowBranchDialog(false);
      setEditingBranch(null);
      setBranchFormData({
        name: "",
        code: "",
        address_line_1: "",
        city: "",
        phone: "",
        email: "",
        is_active: true,
      });
      fetchBranches();
      onOrgUpdate?.();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Error desconocido");
    }
  };

  const handleDeleteBranchClick = (branchId: string) => {
    setDeleteBranchConfirmId(branchId);
  };

  const handleDeleteBranchConfirm = async () => {
    if (!deleteBranchConfirmId) return;

    try {
      const response = await fetch(
        `/api/admin/saas-management/organizations/${orgId}/branches/${deleteBranchConfirmId}`,
        {
          method: "DELETE",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ confirm: true }),
        },
      );

      const data = await response.json();
      if (!response.ok)
        throw new Error(data.error || "Error al eliminar sucursal");

      toast.success("Sucursal eliminada exitosamente");
      setDeleteBranchConfirmId(null);
      fetchBranches();
      onOrgUpdate?.();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Error desconocido");
    }
  };

  return (
    <>
      <Card className="admin-card">
        <CardHeader className="flex flex-row items-center justify-between">
          <CardTitle>Sucursales</CardTitle>
          <Button
            onClick={() => {
              setEditingBranch(null);
              setBranchFormData({
                name: "",
                code: "",
                address_line_1: "",
                city: "",
                phone: "",
                email: "",
                is_active: true,
              });
              setShowBranchDialog(true);
            }}
          >
            <Plus className="h-4 w-4 mr-2" />
            Nueva Sucursal
          </Button>
        </CardHeader>
        <CardContent>
          {branches.length === 0 ? (
            <p className="text-gray-500 text-center py-4">
              No hay sucursales registradas
            </p>
          ) : (
            <div className="overflow-x-auto -mx-4 px-4 md:mx-0 md:px-0">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Nombre</TableHead>
                    <TableHead>Código</TableHead>
                    <TableHead>Dirección</TableHead>
                    <TableHead>Teléfono</TableHead>
                    <TableHead>Estado</TableHead>
                    <TableHead className="text-right">Acciones</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {branches.map((branch) => (
                    <TableRow key={branch.id}>
                      <TableCell className="font-medium">
                        {branch.name}
                      </TableCell>
                      <TableCell>{branch.code}</TableCell>
                      <TableCell>
                        {branch.address_line_1 && branch.city
                          ? `${branch.address_line_1}, ${branch.city}`
                          : "-"}
                      </TableCell>
                      <TableCell>{branch.phone || "-"}</TableCell>
                      <TableCell>
                        {branch.is_active ? (
                          <Badge variant="default">Activa</Badge>
                        ) : (
                          <Badge variant="secondary">Inactiva</Badge>
                        )}
                      </TableCell>
                      <TableCell className="text-right">
                        <div className="flex justify-end gap-2">
                          <Button
                            size="sm"
                            variant="ghost"
                            onClick={() => {
                              setEditingBranch(branch);
                              setBranchFormData({
                                name: branch.name,
                                code: branch.code,
                                address_line_1: branch.address_line_1 || "",
                                city: branch.city || "",
                                phone: branch.phone || "",
                                email: branch.email || "",
                                is_active: branch.is_active,
                              });
                              setShowBranchDialog(true);
                            }}
                          >
                            <Edit className="h-4 w-4" />
                          </Button>
                          <Button
                            size="sm"
                            variant="ghost"
                            onClick={() =>
                              handleDeleteBranchClick(branch.id)
                            }
                          >
                            <Trash2 className="h-4 w-4 text-red-600" />
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>

      <OrgBranchDialog
        branchFormData={branchFormData}
        editingBranch={editingBranch}
        open={showBranchDialog}
        onFormChange={(data) => setBranchFormData((f) => ({ ...f, ...data }))}
        onOpenChange={(open) => {
          setShowBranchDialog(open);
          if (!open) setEditingBranch(null);
        }}
        onSave={editingBranch ? handleUpdateBranch : handleCreateBranch}
      />

      <OrgBranchDeleteDialog
        open={deleteBranchConfirmId !== null}
        onConfirm={handleDeleteBranchConfirm}
        onOpenChange={(open) => !open && setDeleteBranchConfirmId(null)}
      />
    </>
  );
}

"use client";

import { AlertTriangle, Loader2, Trash2 } from "lucide-react";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

interface EditDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  editData: {
    name: string;
    slug: string;
    subscription_tier: string;
    status: string;
  };
  onEditDataChange: (data: EditDialogProps["editData"]) => void;
  saving: boolean;
  onSave: () => void;
}

export function OrgEditDialog({
  open,
  onOpenChange,
  editData,
  onEditDataChange,
  saving,
  onSave,
}: EditDialogProps) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Editar Organización</DialogTitle>
          <DialogDescription>
            Modifica los datos de la organización
          </DialogDescription>
        </DialogHeader>
        <div className="space-y-4">
          <div>
            <label className="text-sm font-medium">Nombre</label>
            <input
              className="w-full mt-1 px-3 py-2 border rounded-md"
              type="text"
              value={editData.name}
              onChange={(e) =>
                onEditDataChange({ ...editData, name: e.target.value })
              }
            />
          </div>
          <div>
            <label className="text-sm font-medium">Slug</label>
            <input
              className="w-full mt-1 px-3 py-2 border rounded-md"
              type="text"
              value={editData.slug}
              onChange={(e) =>
                onEditDataChange({
                  ...editData,
                  slug: e.target.value.toLowerCase().replace(/\s+/g, "-"),
                })
              }
            />
          </div>
          <div>
            <label className="text-sm font-medium">Tier</label>
            <Select
              value={editData.subscription_tier}
              onValueChange={(v) =>
                onEditDataChange({ ...editData, subscription_tier: v })
              }
            >
              <SelectTrigger className="rounded-xl">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="basic">Básico</SelectItem>
                <SelectItem value="pro">Pro</SelectItem>
                <SelectItem value="premium">Premium</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div>
            <label className="text-sm font-medium">Estado</label>
            <Select
              value={editData.status}
              onValueChange={(v) =>
                onEditDataChange({ ...editData, status: v })
              }
            >
              <SelectTrigger className="rounded-xl">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="active">Activa</SelectItem>
                <SelectItem value="suspended">Suspendida</SelectItem>
                <SelectItem value="cancelled">Cancelada</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancelar
          </Button>
          <Button disabled={saving} onClick={onSave}>
            {saving ? (
              <>
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                Guardando...
              </>
            ) : (
              "Guardar"
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

interface DeleteDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  deleting: boolean;
  orgName: string;
  stats: {
    totalUsers: number;
    activeUsers: number;
    branches: number;
    orders: number;
    products: number;
  };
  onDelete: () => void;
}

export function OrgDeleteDialog({
  open,
  onOpenChange,
  deleting,
  orgName,
  stats,
  onDelete,
}: DeleteDialogProps) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-[calc(100vw-2rem)] sm:max-w-lg">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <AlertTriangle className="h-5 w-5 text-red-500" />
            Confirmar Eliminación de Organización
          </DialogTitle>
          <DialogDescription>
            <div className="space-y-4 mt-4">
              <p className="font-semibold text-lg">
                ¿Estás seguro de que deseas eliminar la organización{" "}
                <span className="text-red-600">&quot;{orgName}&quot;</span>?
              </p>
              <div className="p-4 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg">
                <div className="flex items-start gap-3">
                  <AlertTriangle className="h-5 w-5 text-red-600 flex-shrink-0 mt-0.5" />
                  <div className="flex-1">
                    <p className="font-semibold text-red-800 dark:text-red-300 mb-2">
                      ⚠️ Esta acción es IRREVERSIBLE
                    </p>
                    <p className="text-sm text-red-700 dark:text-red-400 mb-3">
                      Se eliminará <strong>PERMANENTEMENTE</strong>:
                    </p>
                    <ul className="text-sm text-red-700 dark:text-red-400 list-disc list-inside space-y-1">
                      <li>La organización y todos sus datos</li>
                      <li>Todas las sucursales ({stats.branches || 0})</li>
                      <li>
                        Todos los usuarios asociados ({stats.activeUsers || 0})
                      </li>
                      <li>Todas las suscripciones</li>
                      <li>Todos los productos ({stats.products || 0})</li>
                      <li>Todos los clientes</li>
                      <li>Todas las órdenes ({stats.orders || 0})</li>
                      <li>
                        Todos los presupuestos, trabajos de laboratorio, pagos
                      </li>
                    </ul>
                  </div>
                </div>
              </div>
              <p className="text-sm text-gray-600 dark:text-gray-400">
                Esta acción no se puede deshacer.
              </p>
            </div>
          </DialogDescription>
        </DialogHeader>
        <DialogFooter>
          <Button
            disabled={deleting}
            variant="outline"
            onClick={() => onOpenChange(false)}
          >
            Cancelar
          </Button>
          <Button disabled={deleting} variant="destructive" onClick={onDelete}>
            {deleting ? (
              <>
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                Eliminando...
              </>
            ) : (
              <>
                <Trash2 className="h-4 w-4 mr-2" />
                Sí, Eliminar Permanentemente
              </>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { AlertTriangle } from "lucide-react";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

interface OrgUserDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  editingUser: unknown;
  userFormData: {
    email: string;
    password: string;
    first_name: string;
    last_name: string;
    role: string;
    branch_id: string;
  };
  onFormChange: (data: Partial<OrgUserDialogProps["userFormData"]>) => void;
  branches: Array<{ id: string; name: string; code: string }>;
  onSave: () => void;
}

export function OrgUserDialog({
  open,
  onOpenChange,
  editingUser,
  userFormData,
  onFormChange,
  branches,
  onSave,
}: OrgUserDialogProps) {
  const isEditing = !!editingUser;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-[calc(100vw-2rem)] sm:max-w-2xl">
        <DialogHeader>
          <DialogTitle>
            {isEditing ? "Editar Usuario" : "Nuevo Usuario"}
          </DialogTitle>
          <DialogDescription>
            {isEditing
              ? "Modifica los datos del usuario"
              : "Completa los datos para crear un nuevo usuario"}
          </DialogDescription>
        </DialogHeader>
        <div className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-sm font-medium">Nombre</label>
              <Input
                placeholder="Nombre"
                value={userFormData.first_name}
                onChange={(e) => onFormChange({ first_name: e.target.value })}
              />
            </div>
            <div>
              <label className="text-sm font-medium">Apellido</label>
              <Input
                placeholder="Apellido"
                value={userFormData.last_name}
                onChange={(e) => onFormChange({ last_name: e.target.value })}
              />
            </div>
          </div>
          <div>
            <label className="text-sm font-medium">Email *</label>
            <Input
              disabled={isEditing}
              placeholder="email@ejemplo.com"
              type="email"
              value={userFormData.email}
              onChange={(e) => onFormChange({ email: e.target.value })}
            />
          </div>
          {!isEditing && (
            <div>
              <label className="text-sm font-medium">Contraseña *</label>
              <Input
                placeholder="Mínimo 8 caracteres"
                type="password"
                value={userFormData.password}
                onChange={(e) => onFormChange({ password: e.target.value })}
              />
            </div>
          )}
          <div>
            <label className="text-sm font-medium">Rol</label>
            <Select
              value={userFormData.role}
              onValueChange={(value) => onFormChange({ role: value })}
            >
              <SelectTrigger className="rounded-xl">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="super_admin">Super Admin</SelectItem>
                <SelectItem value="admin">Admin</SelectItem>
                <SelectItem value="employee">Empleado</SelectItem>
                <SelectItem value="vendedor">Vendedor</SelectItem>
              </SelectContent>
            </Select>
          </div>
          {!isEditing && (
            <div>
              <label className="text-sm font-medium">Sucursal (Opcional)</label>
              <Select
                value={userFormData.branch_id || "__none__"}
                onValueChange={(value) =>
                  onFormChange({ branch_id: value === "__none__" ? "" : value })
                }
              >
                <SelectTrigger className="rounded-xl">
                  <SelectValue placeholder="Seleccionar sucursal" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="__none__">
                    Sin sucursal específica
                  </SelectItem>
                  {(branches || []).map(
                    (branch: { id: string; name: string; code: string }) => (
                      <SelectItem key={branch.id} value={branch.id}>
                        {branch.name} ({branch.code})
                      </SelectItem>
                    ),
                  )}
                </SelectContent>
              </Select>
            </div>
          )}
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancelar
          </Button>
          <Button onClick={onSave}>
            {isEditing ? "Guardar Cambios" : "Crear Usuario"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

export function OrgUserDeleteDialog({
  open,
  onOpenChange,
  onConfirm,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onConfirm: () => void;
}) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-[calc(100vw-2rem)] sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <AlertTriangle className="h-5 w-5 text-red-500" />
            Eliminar usuario
          </DialogTitle>
          <DialogDescription>
            ¿Estás seguro de eliminar este usuario? Esta acción no se puede
            deshacer.
          </DialogDescription>
        </DialogHeader>
        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancelar
          </Button>
          <Button variant="destructive" onClick={onConfirm}>
            Eliminar
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { Edit, Plus, Trash2 } from "lucide-react";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { extractDataFromResponse } from "@/lib/api/response-helpers";

import { OrgUserDeleteDialog,OrgUserDialog } from "./OrgUserDialog";

interface OrgUsersTabProps {
  orgId: string;
  onOrgUpdate?: () => void;
}

export default function OrgUsersTab({ orgId, onOrgUpdate }: OrgUsersTabProps) {
  const [users, setUsers] = useState<Array<unknown>>([]);
  const [branches, setBranches] = useState<Array<unknown>>([]);
  const [showUserDialog, setShowUserDialog] = useState(false);
  const [editingUser, setEditingUser] = useState<unknown>(null);
  const [userFormData, setUserFormData] = useState({
    email: "",
    password: "",
    first_name: "",
    last_name: "",
    role: "admin",
    branch_id: "",
  });
  const [deleteUserConfirmId, setDeleteUserConfirmId] = useState<
    string | null
  >(null);

  useEffect(() => {
    fetchUsers();
    fetchBranches();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [orgId]);

  const fetchBranches = async () => {
    try {
      const response = await fetch(
        `/api/admin/saas-management/organizations/${orgId}/branches`,
      );
      if (!response.ok) return;
      const data = await response.json();
      setBranches(data.branches || []);
    } catch {
      // swallow — branch selector is optional
    }
  };

  const fetchUsers = async () => {
    try {
      const response = await fetch(
        `/api/admin/saas-management/organizations/${orgId}/users`,
      );
      if (!response.ok) throw new Error("Error al cargar usuarios");
      const data = await response.json();
      setUsers(extractDataFromResponse(data));
    } catch {
      toast.error("Error al cargar usuarios");
    }
  };

  const handleCreateUser = async () => {
    try {
      const response = await fetch(
        `/api/admin/saas-management/organizations/${orgId}/users`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(userFormData),
        },
      );

      const data = await response.json();
      if (!response.ok) throw new Error(data.error || "Error al crear usuario");

      toast.success("Usuario creado exitosamente");
      setShowUserDialog(false);
      setUserFormData({
        email: "",
        password: "",
        first_name: "",
        last_name: "",
        role: "admin",
        branch_id: "",
      });
      fetchUsers();
      onOrgUpdate?.();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Error desconocido");
    }
  };

  const handleUpdateUser = async () => {
    if (!editingUser) return;
    try {
      const response = await fetch(
        `/api/admin/saas-management/users/${editingUser.id}`,
        {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            role: userFormData.role,
            is_active: editingUser.is_active,
          }),
        },
      );

      const data = await response.json();
      if (!response.ok)
        throw new Error(data.error || "Error al actualizar usuario");

      toast.success("Usuario actualizado exitosamente");
      setShowUserDialog(false);
      setEditingUser(null);
      setUserFormData({
        email: "",
        password: "",
        first_name: "",
        last_name: "",
        role: "admin",
        branch_id: "",
      });
      fetchUsers();
      onOrgUpdate?.();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Error desconocido");
    }
  };

  const handleDeleteUserClick = (userId: string) => {
    setDeleteUserConfirmId(userId);
  };

  const handleDeleteUserConfirm = async () => {
    if (!deleteUserConfirmId) return;

    try {
      const response = await fetch(
        `/api/admin/saas-management/users/${deleteUserConfirmId}`,
        {
          method: "DELETE",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ confirm: true }),
        },
      );

      const data = await response.json();
      if (!response.ok)
        throw new Error(data.error || "Error al eliminar usuario");

      toast.success("Usuario eliminado exitosamente");
      setDeleteUserConfirmId(null);
      fetchUsers();
      onOrgUpdate?.();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Error desconocido");
    }
  };

  return (
    <>
      <Card className="admin-card">
        <CardHeader className="flex flex-row items-center justify-between">
          <CardTitle>Usuarios</CardTitle>
          <Button
            onClick={() => {
              setEditingUser(null);
              setUserFormData({
                email: "",
                password: "",
                first_name: "",
                last_name: "",
                role: "admin",
                branch_id: "",
              });
              setShowUserDialog(true);
            }}
          >
            <Plus className="h-4 w-4 mr-2" />
            Nuevo Usuario
          </Button>
        </CardHeader>
        <CardContent>
          {users.length === 0 ? (
            <p className="text-gray-500 text-center py-4">
              No hay usuarios registrados
            </p>
          ) : (
            <div className="overflow-x-auto -mx-4 px-4 md:mx-0 md:px-0">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Nombre</TableHead>
                    <TableHead>Email</TableHead>
                    <TableHead>Rol</TableHead>
                    <TableHead>Estado</TableHead>
                    <TableHead className="text-right">Acciones</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {users.map((user) => (
                    <TableRow key={user.id}>
                      <TableCell className="font-medium">
                        {user.profiles?.first_name}{" "}
                        {user.profiles?.last_name}
                      </TableCell>
                      <TableCell>{user.email}</TableCell>
                      <TableCell>
                        <Badge variant="outline">{user.role}</Badge>
                      </TableCell>
                      <TableCell>
                        {user.is_active ? (
                          <Badge variant="default">Activo</Badge>
                        ) : (
                          <Badge variant="secondary">Inactivo</Badge>
                        )}
                      </TableCell>
                      <TableCell className="text-right">
                        <div className="flex justify-end gap-2">
                          <Button
                            size="sm"
                            variant="ghost"
                            onClick={() => {
                              setEditingUser(user);
                              setUserFormData({
                                email: user.email,
                                password: "",
                                first_name: user.profiles?.first_name || "",
                                last_name: user.profiles?.last_name || "",
                                role: user.role,
                                branch_id: "",
                              });
                              setShowUserDialog(true);
                            }}
                          >
                            <Edit className="h-4 w-4" />
                          </Button>
                          <Button
                            size="sm"
                            variant="ghost"
                            onClick={() => handleDeleteUserClick(user.id)}
                          >
                            <Trash2 className="h-4 w-4 text-red-600" />
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>

      <OrgUserDialog
        branches={branches as Array<{ id: string; name: string; code: string }>}
        editingUser={editingUser}
        open={showUserDialog}
        userFormData={userFormData}
        onFormChange={(data) => setUserFormData((f) => ({ ...f, ...data }))}
        onOpenChange={(open) => {
          setShowUserDialog(open);
          if (!open) setEditingUser(null);
        }}
        onSave={editingUser ? handleUpdateUser : handleCreateUser}
      />

      <OrgUserDeleteDialog
        open={deleteUserConfirmId !== null}
        onConfirm={handleDeleteUserConfirm}
        onOpenChange={(open) => !open && setDeleteUserConfirmId(null)}
      />
    </>
  );
}

"use client";

import { Building2, Loader2, MapPin, Users } from "lucide-react";
import Link from "next/link";
import { useParams, useRouter } from "next/navigation";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";

import OrgActivityLog from "../components/OrgActivityLog";
import OrgBasicInfo from "../components/OrgBasicInfo";
import OrgDetailHeader from "../components/OrgDetailHeader";
import OrgSubscriptionInfo from "../components/OrgSubscriptionInfo";
import OrgBranchesTab from "./OrgBranchesTab";
import { OrgDeleteDialog, OrgEditDialog } from "./OrgDialogs";
import OrgUsersTab from "./OrgUsersTab";

interface OrganizationDetails {
  id: string;
  name: string;
  slug: string;
  subscription_tier: string;
  status: string;
  owner_id?: string;
  metadata?: unknown;
  created_at: string;
  updated_at: string;
  stats: {
    totalUsers: number;
    activeUsers: number;
    branches: number;
    orders: number;
    products: number;
  };
  subscriptions?: Array<{
    id: string;
    status: string;
    current_period_start?: string;
    current_period_end?: string;
    gateway_subscription_id?: string;
  }>;
  owner?: {
    id: string;
    email: string;
    first_name?: string;
    last_name?: string;
    phone?: string;
  };
  recentUsers?: Array<{
    id: string;
    email: string;
    role: string;
    is_active: boolean;
    last_login?: string;
    created_at: string;
    profiles?: {
      first_name?: string;
      last_name?: string;
    };
  }>;
}

export default function OrganizationDetailsContent() {
  const params = useParams();
  const router = useRouter();
  const orgId = params.id as string;

  const [organization, setOrganization] = useState<OrganizationDetails | null>(
    null,
  );
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [showEditDialog, setShowEditDialog] = useState(false);
  const [editing, setEditing] = useState(false);
  const [editData, setEditData] = useState({
    name: "",
    slug: "",
    subscription_tier: "basic",
    status: "active",
  });
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [activeTab, setActiveTab] = useState("overview");

  useEffect(() => {
    fetchOrganizationDetails();
  }, [orgId]);

  const fetchOrganizationDetails = async () => {
    try {
      setLoading(true);
      const response = await fetch(
        `/api/admin/saas-management/organizations/${orgId}`,
      );

      if (!response.ok) {
        throw new Error("Error al cargar detalles de la organización");
      }

      const data = await response.json();
      setOrganization(data.organization);
      setEditData({
        name: data.organization.name,
        slug: data.organization.slug,
        subscription_tier: data.organization.subscription_tier,
        status: data.organization.status,
      });
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Error desconocido");
      toast.error("Error al cargar detalles");
    } finally {
      setLoading(false);
    }
  };

  const handleUpdate = async () => {
    setEditing(true);
    try {
      const response = await fetch(
        `/api/admin/saas-management/organizations/${orgId}`,
        {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(editData),
        },
      );

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || "Error al actualizar organización");
      }

      toast.success("Organización actualizada exitosamente");
      setShowEditDialog(false);
      fetchOrganizationDetails();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Error desconocido");
    } finally {
      setEditing(false);
    }
  };

  const handleAction = async (
    action: "suspend" | "activate" | "cancel" | "change_tier",
    value?: string,
  ) => {
    try {
      const response = await fetch(
        `/api/admin/saas-management/organizations/${orgId}/actions`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ action, value }),
        },
      );

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || "Error al realizar acción");
      }

      toast.success("Acción realizada exitosamente");
      fetchOrganizationDetails();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Error desconocido");
    }
  };

  const handleDeleteConfirm = async () => {
    setDeleting(true);
    try {
      const response = await fetch(
        `/api/admin/saas-management/organizations/${orgId}`,
        {
          method: "DELETE",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ confirm: true }),
        },
      );

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || "Error al eliminar organización");
      }

      toast.success(
        `Organización "${organization?.name}" eliminada completamente junto con todos sus datos relacionados`,
      );
      router.push("/admin/saas-management/organizations");
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Error desconocido");
      setDeleting(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <Loader2 className="h-8 w-8 animate-spin text-blue-600" />
      </div>
    );
  }

  if (error || !organization) {
    return (
      <div className="p-6">
        <Card className="admin-card">
          <CardContent className="pt-6">
            <div className="text-center text-red-600">
              <p>Error: {error || "Organización no encontrada"}</p>
              <Link href="/admin/saas-management/organizations">
                <Button className="mt-4" variant="outline">
                  Volver a organizaciones
                </Button>
              </Link>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="space-y-6 p-6">
      <OrgDetailHeader
        name={organization.name}
        slug={organization.slug}
        status={organization.status}
        subscriptionTier={organization.subscription_tier}
        onAction={handleAction}
        onDelete={() => setDeleteDialogOpen(true)}
        onEdit={() => setShowEditDialog(true)}
      />

      <OrgSubscriptionInfo
        orgId={orgId}
        stats={organization.stats}
        subscriptions={organization.subscriptions}
      />

      {/* Tabs para gestión detallada */}
      <Tabs
        className="space-y-6"
        value={activeTab}
        onValueChange={setActiveTab}
      >
        <TabsList className="grid w-full grid-cols-3">
          <TabsTrigger value="overview">
            <Building2 className="h-4 w-4 mr-2" />
            Resumen
          </TabsTrigger>
          <TabsTrigger value="branches">
            <MapPin className="h-4 w-4 mr-2" />
            Sucursales ({organization.stats.branches})
          </TabsTrigger>
          <TabsTrigger value="users">
            <Users className="h-4 w-4 mr-2" />
            Usuarios ({organization.stats.totalUsers})
          </TabsTrigger>
        </TabsList>

        {/* Tab: Resumen */}
        <TabsContent className="space-y-6" value="overview">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <OrgBasicInfo
              createdAt={organization.created_at}
              name={organization.name}
              owner={organization.owner || null}
              slug={organization.slug}
              updatedAt={organization.updated_at}
            />

            <OrgActivityLog recentUsers={organization.recentUsers} />
          </div>
        </TabsContent>

        {/* Tab: Sucursales */}
        <TabsContent className="space-y-6" value="branches">
          <OrgBranchesTab
            orgId={orgId}
            onOrgUpdate={fetchOrganizationDetails}
          />
        </TabsContent>

        {/* Tab: Usuarios */}
        <TabsContent className="space-y-6" value="users">
          <OrgUsersTab orgId={orgId} onOrgUpdate={fetchOrganizationDetails} />
        </TabsContent>
      </Tabs>

      <OrgEditDialog
        editData={editData}
        open={showEditDialog}
        saving={editing}
        onEditDataChange={setEditData}
        onOpenChange={setShowEditDialog}
        onSave={handleUpdate}
      />
      <OrgDeleteDialog
        deleting={deleting}
        open={deleteDialogOpen}
        orgName={organization?.name || ""}
        stats={{
          totalUsers: organization?.stats?.totalUsers || 0,
          activeUsers: organization?.stats?.activeUsers || 0,
          branches: organization?.stats?.branches || 0,
          orders: organization?.stats?.orders || 0,
          products: organization?.stats?.products || 0,
        }}
        onDelete={handleDeleteConfirm}
        onOpenChange={setDeleteDialogOpen}
      />
    </div>
  );
}

