import { Alert, AlertDescription, AlertTitle } from "./_components/AlertComponents";

"use client";

import { ArrowLeft, Loader2, Pencil, Trash2 } from "lucide-react";
import { useParams, useRouter } from "next/navigation";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { appLogger } from '@/lib/logger';

import {
  SubscriptionDeleteDialog,
  SubscriptionEditForm,
} from "./SubscriptionDialogs";
import {  SubscriptionDetails,
  SubscriptionInfoCards,
} from "./SubscriptionInfoCards";

export default function SubscriptionDetailsContent() {
  const params = useParams();

  const router = useRouter();
  const subscriptionId = params.id as string;

  const [subscription, setSubscription] = useState<SubscriptionDetails | null>(
    null,
  );
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [editing, setEditing] = useState(false);
  const [editStatus, setEditStatus] = useState("");
  const [editPeriodEnd, setEditPeriodEnd] = useState("");
  const [editTrialEndsAt, setEditTrialEndsAt] = useState("");
  const [saveLoading, setSaveLoading] = useState(false);
  const [deleteLoading, setDeleteLoading] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  useEffect(() => {
    if (subscriptionId) {
      fetchSubscriptionDetails();
    }
  }, [subscriptionId]);

  useEffect(() => {
    if (subscription) {
      setEditStatus(subscription.status);
      setEditPeriodEnd(subscription.current_period_end || "");
      setEditTrialEndsAt(
        subscription.trial_ends_at
          ? subscription.trial_ends_at.slice(0, 16)
          : "",
      );
    }
  }, [subscription]);

  const handleSaveEdit = async () => {
    if (!subscription) return;
    setSaveLoading(true);
    try {
      const res = await fetch(
        `/api/admin/saas-management/subscriptions/${subscriptionId}`,
        {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            status: editStatus,
            current_period_end: editPeriodEnd || undefined,
            trial_ends_at: editTrialEndsAt || undefined,
          }),
        },
      );
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Error al guardar");
      toast.success("Suscripción actualizada.");
      setEditing(false);
      fetchSubscriptionDetails();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Error desconocido");
    } finally {
      setSaveLoading(false);
    }
  };

  const handleDelete = async () => {
    setDeleteLoading(true);
    try {
      const res = await fetch(
        `/api/admin/saas-management/subscriptions/${subscriptionId}`,
        { method: "DELETE" },
      );
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Error al eliminar");
      toast.success("Suscripción eliminada.");
      setShowDeleteConfirm(false);
      router.push("/admin/saas-management/subscriptions");
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Error desconocido");
    } finally {
      setDeleteLoading(false);
    }
  };

  const fetchSubscriptionDetails = async () => {
    try {
      setLoading(true);
      const response = await fetch(
        `/api/admin/saas-management/subscriptions/${subscriptionId}`,
      );

      if (!response.ok) {
        if (response.status === 404) {
          throw new Error("Suscripción no encontrada");
        }
        throw new Error("Error al cargar detalles de la suscripción");
      }

      const data = await response.json();
      const sub = data.subscription;

      const today = new Date();
      let daysUntilExpiry: number | null = null;
      const endSource =
        sub.status === "trialing" && sub.trial_ends_at
          ? sub.trial_ends_at
          : sub.current_period_end;
      if (endSource) {
        const endDate = new Date(endSource);
        const diffTime = endDate.getTime() - today.getTime();
        daysUntilExpiry = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      }

      setSubscription({
        ...sub,
        daysUntilExpiry,
        isExpiringSoon:
          daysUntilExpiry !== null &&
          daysUntilExpiry <= 7 &&
          daysUntilExpiry >= 0,
        isExpired: daysUntilExpiry !== null && daysUntilExpiry < 0,
      });
      setError(null);
    } catch (err) {
      appLogger.error("Error fetching subscription details:", err);
      setError(err instanceof Error ? err.message : "Error desconocido");
      toast.error(
        err instanceof Error
          ? err.message
          : "Error al cargar detalles de la suscripción",
      );
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center">
          <Loader2 className="h-8 w-8 animate-spin text-blue-600 mx-auto mb-4" />
          <p className="text-admin-text-tertiary">
            Cargando detalles de la suscripción...
          </p>
        </div>
      </div>
    );
  }

  if (error || !subscription) {
    return (
      <div className="space-y-6 p-6">
        <div className="flex items-center gap-4">
          <Button
            size="icon"
            title="Volver a suscripciones"
            variant="ghost"
            onClick={() => router.push("/admin/saas-management/subscriptions")}
          >
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div>
            <h1 className="text-3xl font-display font-bold text-epoch-primary tracking-tight">
              Error
            </h1>
          </div>
        </div>
        <Card>
          <CardContent className="pt-6">
            <div className="text-center py-12 text-red-600">
              {error || "Suscripción no encontrada"}
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="space-y-6 p-6">
      {/* Header */}
      <div className="flex items-center justify-between flex-wrap gap-4">
        <div className="flex items-center gap-4">
          <Button
            size="icon"
            title="Volver a suscripciones"
            variant="ghost"
            onClick={() => router.push("/admin/saas-management/subscriptions")}
          >
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div>
            <h1 className="text-3xl font-display font-bold text-epoch-primary tracking-tight">
              Detalles de la Suscripción
            </h1>
            <p className="text-admin-text-tertiary mt-2">
              Información completa de la suscripción
            </p>
          </div>
        </div>
        <div className="flex gap-2">
          <Button
            size="sm"
            variant={editing ? "default" : "outline"}
            onClick={() => setEditing(!editing)}
          >
            <Pencil className="h-4 w-4 mr-2" />
            {editing ? "Cancelar edición" : "Editar"}
          </Button>
          <Button
            disabled={deleteLoading}
            size="sm"
            variant="destructive"
            onClick={() => setShowDeleteConfirm(true)}
          >
            {deleteLoading ? (
              <Loader2 className="h-4 w-4 animate-spin mr-2" />
            ) : (
              <Trash2 className="h-4 w-4 mr-2" />
            )}
            Eliminar
          </Button>
        </div>
      </div>

      <SubscriptionInfoCards subscription={subscription} />

      {editing && (
        <SubscriptionEditForm
          editPeriodEnd={editPeriodEnd}
          editStatus={editStatus}
          editTrialEndsAt={editTrialEndsAt}
          saveLoading={saveLoading}
          onEditPeriodEndChange={setEditPeriodEnd}
          onEditStatusChange={setEditStatus}
          onEditTrialEndsAtChange={setEditTrialEndsAt}
          onSave={handleSaveEdit}
        />
      )}

      <SubscriptionDeleteDialog
        deleteLoading={deleteLoading}
        open={showDeleteConfirm}
        onDelete={handleDelete}
        onOpenChange={setShowDeleteConfirm}
      />
    </div>
  );
}

"use client";

import { AlertCircle, Loader2, Pencil, Save, Trash2 } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

interface EditProps {
  editStatus: string;
  editPeriodEnd: string;
  editTrialEndsAt: string;
  onEditStatusChange: (v: string) => void;
  onEditPeriodEndChange: (v: string) => void;
  onEditTrialEndsAtChange: (v: string) => void;
  onSave: () => void;
  saveLoading: boolean;
}

export function SubscriptionEditForm({
  editStatus,
  editPeriodEnd,
  editTrialEndsAt,
  onEditStatusChange,
  onEditPeriodEndChange,
  onEditTrialEndsAtChange,
  onSave,
  saveLoading,
}: EditProps) {
  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Pencil className="h-5 w-5" />
          Editar suscripción
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="space-y-2">
            <Label>Estado</Label>
            <Select value={editStatus} onValueChange={onEditStatusChange}>
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="active">Activa</SelectItem>
                <SelectItem value="trialing">Trial</SelectItem>
                <SelectItem value="past_due">Vencida</SelectItem>
                <SelectItem value="incomplete">Incompleta</SelectItem>
                <SelectItem value="cancelled">Cancelada</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div className="space-y-2">
            <Label htmlFor="period_end">Fin del período (YYYY-MM-DD)</Label>
            <Input
              id="period_end"
              type="date"
              value={editPeriodEnd}
              onChange={(e) => onEditPeriodEndChange(e.target.value)}
            />
          </div>
          <div className="space-y-2 md:col-span-2">
            <Label htmlFor="trial_ends">
              Fin del trial (fecha y hora, opcional)
            </Label>
            <Input
              id="trial_ends"
              type="datetime-local"
              value={editTrialEndsAt}
              onChange={(e) => onEditTrialEndsAtChange(e.target.value)}
            />
          </div>
        </div>
        <Button disabled={saveLoading} onClick={onSave}>
          {saveLoading ? (
            <Loader2 className="h-4 w-4 animate-spin mr-2" />
          ) : (
            <Save className="h-4 w-4 mr-2" />
          )}
          Guardar cambios
        </Button>
      </CardContent>
    </Card>
  );
}

interface DeleteProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  deleteLoading: boolean;
  onDelete: () => void;
}

export function SubscriptionDeleteDialog({
  open,
  onOpenChange,
  deleteLoading,
  onDelete,
}: DeleteProps) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <div className="mx-auto bg-red-100 dark:bg-red-500/20 p-4 rounded-3xl w-fit mb-4">
            <AlertCircle className="h-10 w-10 text-red-600 dark:text-red-500" />
          </div>
          <DialogTitle>¿Eliminar esta suscripción?</DialogTitle>
          <DialogDescription>
            Esta acción no se puede deshacer. Se eliminará el registro de
            suscripción.
          </DialogDescription>
        </DialogHeader>
        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Volver
          </Button>
          <Button
            disabled={deleteLoading}
            variant="destructive"
            onClick={onDelete}
          >
            {deleteLoading ? (
              <Loader2 className="h-4 w-4 animate-spin mr-2" />
            ) : (
              <Trash2 className="h-4 w-4 mr-2" />
            )}
            Eliminar
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import {
  AlertTriangle,
  Building2,
  Calendar,
  CheckCircle2,
  Clock,
  CreditCard,
  DollarSign,
  XCircle,
} from "lucide-react";
import Link from "next/link";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { formatDate } from "@/lib/utils";

function getStatusBadge(
  status: string,
  isExpiringSoon?: boolean,
  isExpired?: boolean,
) {
  const variants: Record<string, "default" | "secondary" | "destructive"> = {
    active: "default",
    trialing: "secondary",
    past_due: "destructive",
    cancelled: "destructive",
    incomplete: "secondary",
  };
  const icons: Record<string, typeof CheckCircle2> = {
    active: CheckCircle2,
    trialing: Clock,
    past_due: AlertTriangle,
    cancelled: XCircle,
    incomplete: Clock,
  };
  const Icon = icons[status] || CheckCircle2;
  const variant = variants[status] || "default";
  let className = "";
  if (isExpired) className = "bg-red-100 text-red-800";
  else if (isExpiringSoon) className = "bg-yellow-100 text-yellow-800";
  return (
    <Badge className={className} variant={variant}>
      <Icon className="h-3 w-3 mr-1" />
      {status === "active"
        ? "Activa"
        : status === "trialing"
          ? "Trial"
          : status === "past_due"
            ? "Vencida"
            : status === "cancelled"
              ? "Cancelada"
              : status === "incomplete"
                ? "Incompleta"
                : status}
    </Badge>
  );
}

export interface SubscriptionDetails {
  id: string;
  organization_id: string;
  status: string;
  trial_ends_at?: string | null;
  current_period_start?: string;
  current_period_end?: string;
  cancel_at?: string;
  canceled_at?: string;
  gateway_subscription_id?: string;
  gateway_customer_id?: string;
  created_at: string;
  updated_at: string;
  organization?: {
    id: string;
    name: string;
    slug: string;
    subscription_tier: string;
    status: string;
    owner_id?: string;
    created_at: string;
  };
  daysUntilExpiry?: number;
  isExpiringSoon?: boolean;
  isExpired?: boolean;
}

interface Props {
  subscription: SubscriptionDetails;
}

export function SubscriptionInfoCards({ subscription }: Props) {
  return (
    <>
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-3">
            <CreditCard className="h-5 w-5" />
            Información de la Suscripción
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="text-sm font-medium text-gray-500">
                Estado
              </label>
              <div className="mt-1">
                {getStatusBadge(
                  subscription.status,
                  subscription.isExpiringSoon,
                  subscription.isExpired,
                )}
              </div>
            </div>
            {subscription.daysUntilExpiry !== null && (
              <div>
                <label className="text-sm font-medium text-gray-500">
                  Días hasta vencimiento
                </label>
                <p
                  className={`text-lg font-semibold ${subscription.isExpired ? "text-red-600" : subscription.isExpiringSoon ? "text-yellow-600" : ""}`}
                >
                  {subscription.daysUntilExpiry != null &&
                  subscription.daysUntilExpiry < 0
                    ? `Vencida hace ${Math.abs(subscription.daysUntilExpiry)} días`
                    : subscription.daysUntilExpiry != null
                      ? `${subscription.daysUntilExpiry} días`
                      : "N/A"}
                </p>
              </div>
            )}
            {subscription.current_period_start && (
              <div>
                <label className="text-sm font-medium text-gray-500">
                  Inicio del período
                </label>
                <p className="text-lg flex items-center gap-2">
                  <Calendar className="h-4 w-4" />
                  {formatDate(subscription.current_period_start)}
                </p>
              </div>
            )}
            {subscription.current_period_end && (
              <div>
                <label className="text-sm font-medium text-gray-500">
                  Fin del período
                </label>
                <p className="text-lg flex items-center gap-2">
                  <Calendar className="h-4 w-4" />
                  {formatDate(subscription.current_period_end)}
                </p>
              </div>
            )}
            {subscription.cancel_at && (
              <div>
                <label className="text-sm font-medium text-gray-500">
                  Cancelación programada
                </label>
                <p className="text-lg flex items-center gap-2">
                  <Calendar className="h-4 w-4" />
                  {formatDate(subscription.cancel_at)}
                </p>
              </div>
            )}
            {subscription.canceled_at && (
              <div>
                <label className="text-sm font-medium text-gray-500">
                  Fecha de cancelación
                </label>
                <p className="text-lg flex items-center gap-2">
                  <Calendar className="h-4 w-4" />
                  {formatDate(subscription.canceled_at)}
                </p>
              </div>
            )}
            {subscription.trial_ends_at && (
              <div>
                <label className="text-sm font-medium text-gray-500">
                  Fin del período de prueba
                </label>
                <p className="text-lg flex items-center gap-2">
                  <Calendar className="h-4 w-4" />
                  {formatDate(subscription.trial_ends_at)}
                </p>
              </div>
            )}
          </div>
        </CardContent>
      </Card>

      {(subscription.gateway_subscription_id ||
        subscription.gateway_customer_id) && (
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-3">
              <DollarSign className="h-5 w-5" />
              Información de Stripe
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {subscription.gateway_subscription_id && (
                <div>
                  <label className="text-sm font-medium text-gray-500">
                    ID de Suscripción Stripe
                  </label>
                  <p className="text-sm font-mono text-gray-600">
                    {subscription.gateway_subscription_id}
                  </p>
                </div>
              )}
              {subscription.gateway_customer_id && (
                <div>
                  <label className="text-sm font-medium text-gray-500">
                    ID de Cliente
                  </label>
                  <p className="text-sm font-mono text-gray-600">
                    {subscription.gateway_customer_id}
                  </p>
                </div>
              )}
            </div>
          </CardContent>
        </Card>
      )}

      {subscription.organization && (
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-3">
              <Building2 className="h-5 w-5" />
              Organización
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="flex items-center justify-between">
              <div>
                <p className="text-lg font-semibold">
                  {subscription.organization.name}
                </p>
                <p className="text-sm text-gray-500">
                  Slug: {subscription.organization.slug}
                </p>
                <div className="flex gap-2 mt-2">
                  <Badge>{subscription.organization.subscription_tier}</Badge>
                  <Badge
                    variant={
                      subscription.organization.status === "active"
                        ? "default"
                        : "secondary"
                    }
                  >
                    {subscription.organization.status}
                  </Badge>
                </div>
              </div>
              <Link
                href={`/admin/saas-management/organizations/${subscription.organization.id}`}
              >
                <Button size="sm" variant="outline">
                  Ver organización
                </Button>
              </Link>
            </div>
          </CardContent>
        </Card>
      )}

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-3">
            <Clock className="h-5 w-5" />
            Información del Sistema
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="text-sm font-medium text-gray-500">
                Fecha de creación
              </label>
              <p className="text-lg">{formatDate(subscription.created_at)}</p>
            </div>
            <div>
              <label className="text-sm font-medium text-gray-500">
                Última actualización
              </label>
              <p className="text-lg">{formatDate(subscription.updated_at)}</p>
            </div>
            <div>
              <label className="text-sm font-medium text-gray-500">
                ID de la Suscripción
              </label>
              <p className="text-sm font-mono text-gray-600">
                {subscription.id}
              </p>
            </div>
          </div>
        </CardContent>
      </Card>
    </>
  );
}

"use client";

import { Loader2 } from "lucide-react";
import { useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

interface Organization {
  id: string;
  name: string;
  slug: string;
}

interface CreateSubscriptionDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  organizations: Organization[];
  onCreated: () => void;
}

export function CreateSubscriptionDialog({
  open,
  onOpenChange,
  organizations,
  onCreated,
}: CreateSubscriptionDialogProps) {
  const [createOrgId, setCreateOrgId] = useState("");
  const [createStatus, setCreateStatus] = useState("trialing");
  const [createTrialDays, setCreateTrialDays] = useState("7");
  const [createLoading, setCreateLoading] = useState(false);

  const handleCreate = async () => {
    const orgId = createOrgId?.trim();
    if (!orgId) {
      toast.error("Selecciona una organización.");
      return;
    }
    const trialDaysNum = parseInt(createTrialDays, 10);
    if (isNaN(trialDaysNum) || trialDaysNum < 1) {
      toast.error("Días de prueba debe ser un número mayor a 0.");
      return;
    }
    setCreateLoading(true);
    try {
      const res = await fetch("/api/admin/saas-management/subscriptions", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          organization_id: orgId,
          status: createStatus,
          trial_days: trialDaysNum,
        }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Error al crear suscripción");
      toast.success("Suscripción creada.");
      onOpenChange(false);
      setCreateOrgId("");
      setCreateStatus("trialing");
      setCreateTrialDays("7");
      onCreated();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Error desconocido");
    } finally {
      setCreateLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Nueva suscripción</DialogTitle>
          <DialogDescription>
            Crea una suscripción para una organización. Se asignará período de
            prueba según los días indicados.
          </DialogDescription>
        </DialogHeader>
        <div className="grid gap-4 py-4">
          <div className="space-y-2">
            <Label>Organización</Label>
            <Select value={createOrgId} onValueChange={setCreateOrgId}>
              <SelectTrigger className="rounded-xl">
                <SelectValue placeholder="Selecciona organización" />
              </SelectTrigger>
              <SelectContent>
                {organizations.map((org) => (
                  <SelectItem key={org.id} value={org.id}>
                    {org.name} ({org.slug})
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div className="space-y-2">
            <Label>Estado</Label>
            <Select value={createStatus} onValueChange={setCreateStatus}>
              <SelectTrigger className="rounded-xl">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="trialing">Trial</SelectItem>
                <SelectItem value="active">Activa</SelectItem>
                <SelectItem value="past_due">Vencida</SelectItem>
                <SelectItem value="incomplete">Incompleta</SelectItem>
                <SelectItem value="cancelled">Cancelada</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div className="space-y-2">
            <Label htmlFor="trial_days">Días de prueba (si es trial)</Label>
            <Input
              id="trial_days"
              min={1}
              type="number"
              value={createTrialDays}
              onChange={(e) => setCreateTrialDays(e.target.value)}
            />
          </div>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancelar
          </Button>
          <Button disabled={createLoading} onClick={handleCreate}>
            {createLoading ? (
              <Loader2 className="h-4 w-4 animate-spin mr-2" />
            ) : null}
            Crear
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import {
  AlertTriangle,
  Ban,
  CheckCircle2,
  Clock,
  Play,
  Trash2,
  XCircle,
} from "lucide-react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

export function getStatusBadge(
  status: string,
  isExpiringSoon?: boolean,
  isExpired?: boolean,
) {
  if (isExpired)
    return (
      <Badge variant="destructive">
        <XCircle className="h-3 w-3 mr-1" />
        Vencida
      </Badge>
    );
  if (isExpiringSoon)
    return (
      <Badge className="bg-yellow-100 text-yellow-800" variant="secondary">
        <AlertTriangle className="h-3 w-3 mr-1" />
        Por vencer
      </Badge>
    );
  const variants: Record<string, "default" | "secondary" | "destructive"> = {
    active: "default",
    trialing: "secondary",
    past_due: "destructive",
    cancelled: "destructive",
    incomplete: "secondary",
  };
  const icons: Record<string, typeof CheckCircle2> = {
    active: CheckCircle2,
    trialing: Clock,
    past_due: AlertTriangle,
    cancelled: XCircle,
    incomplete: Clock,
  };
  const Icon = icons[status] || CheckCircle2;
  return (
    <Badge variant={variants[status] || "default"}>
      <Icon className="h-3 w-3 mr-1" />
      {status === "active"
        ? "Activa"
        : status === "trialing"
          ? "Trial"
          : status === "past_due"
            ? "Vencida"
            : status === "cancelled"
              ? "Cancelada"
              : status === "incomplete"
                ? "Incompleta"
                : status}
    </Badge>
  );
}

export function getTierBadge(tier: string) {
  const colors: Record<string, string> = {
    basic: "bg-gray-100 text-gray-800",
    pro: "bg-blue-100 text-blue-800",
    premium: "bg-purple-100 text-purple-800",
  };
  return (
    <Badge className={colors[tier] || colors.basic}>
      {tier === "basic"
        ? "Básico"
        : tier === "pro"
          ? "Pro"
          : tier === "premium"
            ? "Premium"
            : tier}
    </Badge>
  );
}

interface ActionMenuProps {
  status: string;
  onView: () => void;
  onCancel?: () => void;
  onReactivate?: () => void;
  onDelete?: () => void;
}

export function SubscriptionActionMenu({
  status,
  onView,
  onCancel,
  onReactivate,
  onDelete,
}: ActionMenuProps) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button size="sm" variant="ghost">
          <Ban className="h-4 w-4" />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end">
        <DropdownMenuItem onClick={onView}>
          <Ban className="h-4 w-4 mr-2" />
          Ver detalles
        </DropdownMenuItem>
        <DropdownMenuSeparator />
        {status === "cancelled" ? (
          <DropdownMenuItem onClick={onReactivate}>
            <Play className="h-4 w-4 mr-2" />
            Reactivar
          </DropdownMenuItem>
        ) : (
          <DropdownMenuItem onClick={onCancel}>
            <Ban className="h-4 w-4 mr-2" />
            Cancelar
          </DropdownMenuItem>
        )}
        <DropdownMenuSeparator />
        <DropdownMenuItem
          className="text-destructive focus:text-destructive"
          onClick={onDelete}
        >
          <Trash2 className="h-4 w-4 mr-2" />
          Eliminar
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

"use client";

import { AlertTriangle, ArrowLeft, Plus } from "lucide-react";
import { useRouter, useSearchParams } from "next/navigation";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { appLogger } from '@/lib/logger';

import { CreateSubscriptionDialog } from "./CreateSubscriptionDialog";
import { SubscriptionsDialogs } from "./SubscriptionsDialogs";
import { SubscriptionsFilterBar } from "./SubscriptionsFilterBar";
import { SubscriptionsTable } from "./SubscriptionsTable";

interface Subscription {
  id: string;
  organization_id: string;
  status: string;
  current_period_start?: string;
  current_period_end?: string;
  cancel_at?: string;
  canceled_at?: string;
  gateway_subscription_id?: string;
  gateway_customer_id?: string;
  created_at: string;
  daysUntilExpiry?: number | null;
  isExpiringSoon?: boolean;
  isExpired?: boolean;
  organization?: {
    id: string;
    name: string;
    slug: string;
    subscription_tier: string;
    status: string;
  };
}

interface Organization {
  id: string;
  name: string;
  slug: string;
}

export default function SubscriptionsContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const orgIdFromUrl = searchParams.get("organization_id") || "";

  const [subscriptions, setSubscriptions] = useState<Subscription[]>([]);
  const [organizations, setOrganizations] = useState<Organization[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Confirmaciones con UI del programa (no window.confirm)
  const [cancelConfirmId, setCancelConfirmId] = useState<string | null>(null);
  const [deleteConfirmId, setDeleteConfirmId] = useState<string | null>(null);

  // Filtros - organization_id from URL pre-filters when navigating from org detail
  const [organizationFilter, setOrganizationFilter] = useState(
    orgIdFromUrl || "all",
  );
  const [statusFilter, setStatusFilter] = useState("all");
  const [tierFilter, setTierFilter] = useState("all");

  // Paginación
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [totalCount, setTotalCount] = useState(0);

  // Crear suscripción
  const [createOpen, setCreateOpen] = useState(false);

  // Eliminar
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [deleteLoading, setDeleteLoading] = useState(false);

  // Sync organization filter when URL param changes (e.g. from org detail "Gestionar suscripciones")
  useEffect(() => {
    if (orgIdFromUrl && organizationFilter !== orgIdFromUrl) {
      setOrganizationFilter(orgIdFromUrl);
    }
  }, [orgIdFromUrl]);

  useEffect(() => {
    fetchOrganizations();
    fetchSubscriptions();
  }, [currentPage, organizationFilter, statusFilter, tierFilter]);

  const fetchOrganizations = async () => {
    try {
      const response = await fetch(
        "/api/admin/saas-management/organizations?limit=1000",
      );
      if (response.ok) {
        const data = await response.json();
        setOrganizations(data.organizations || []);
      }
    } catch (err) {
      appLogger.error("Error fetching organizations:", err);
    }
  };

  const fetchSubscriptions = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams({
        page: currentPage.toString(),
        limit: "20",
      });

      if (organizationFilter !== "all") {
        params.append("organization_id", organizationFilter);
      }
      if (statusFilter !== "all") {
        params.append("status", statusFilter);
      }
      if (tierFilter !== "all") {
        params.append("tier", tierFilter);
      }

      const response = await fetch(
        `/api/admin/saas-management/subscriptions?${params}`,
      );

      if (!response.ok) {
        throw new Error("Error al cargar suscripciones");
      }

      const data = await response.json();
      setSubscriptions(data.subscriptions || []);
      setTotalPages(data.pagination?.totalPages || 1);
      setTotalCount(data.pagination?.total || 0);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Error desconocido");
      toast.error("Error al cargar suscripciones");
    } finally {
      setLoading(false);
    }
  };

  const handleAction = async (
    subscriptionId: string,
    action: "cancel" | "reactivate" | "extend",
    value?: unknown,
  ) => {
    try {
      const response = await fetch(
        `/api/admin/saas-management/subscriptions/${subscriptionId}/actions`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ action, value }),
        },
      );

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || "Error al realizar acción");
      }

      toast.success(data.message || "Acción realizada exitosamente");
      setCancelConfirmId(null);
      fetchSubscriptions();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Error desconocido");
    }
  };

  const handleDelete = async (subscriptionId: string) => {
    setDeleteId(subscriptionId);
    setDeleteLoading(true);
    try {
      const res = await fetch(
        `/api/admin/saas-management/subscriptions/${subscriptionId}`,
        { method: "DELETE" },
      );
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Error al eliminar");
      toast.success("Suscripción eliminada.");
      setDeleteConfirmId(null);
      fetchSubscriptions();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Error desconocido");
    } finally {
      setDeleteId(null);
      setDeleteLoading(false);
    }
  };

  return (
    <div className="space-y-6 p-6">
      <div className="flex items-center justify-between gap-4 flex-wrap">
        <div className="flex items-center gap-4">
          <Button
            className="text-white hover:bg-white/10"
            size="icon"
            title="Volver al dashboard"
            variant="ghost"
            onClick={() => router.push("/admin/saas-management/dashboard")}
          >
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div>
            <h1 className="text-3xl font-display font-bold text-white tracking-tight">
              Gestión de Suscripciones
            </h1>
            <p className="text-white/50 mt-2">
              Administra todas las suscripciones del sistema
            </p>
          </div>
        </div>
        <Button
          className="bg-[#C5A059] hover:bg-[#C5A059]/90"
          onClick={() => setCreateOpen(true)}
        >
          <Plus className="h-4 w-4 mr-2" />
          Nueva suscripción
        </Button>
        <CreateSubscriptionDialog
          open={createOpen}
          organizations={organizations}
          onCreated={fetchSubscriptions}
          onOpenChange={setCreateOpen}
        />
      </div>

      {/* Alertas */}
      {subscriptions.some((sub) => sub.isExpiringSoon || sub.isExpired) && (
        <Card className="admin-card border-yellow-200 bg-yellow-50">
          <CardContent className="pt-6">
            <div className="flex items-center gap-2">
              <AlertTriangle className="h-5 w-5 text-yellow-600" />
              <p className="text-sm text-yellow-800">
                Hay suscripciones próximas a vencer o vencidas. Revisa la lista
                para más detalles.
              </p>
            </div>
          </CardContent>
        </Card>
      )}

      <SubscriptionsFilterBar
        organizationFilter={organizationFilter}
        organizations={organizations}
        statusFilter={statusFilter}
        tierFilter={tierFilter}
        onOrganizationFilterChange={setOrganizationFilter}
        onStatusFilterChange={setStatusFilter}
        onTierFilterChange={setTierFilter}
      />

      <SubscriptionsTable
        currentPage={currentPage}
        error={error}
        loading={loading}
        subscriptions={subscriptions}
        totalCount={totalCount}
        totalPages={totalPages}
        onCancelClick={setCancelConfirmId}
        onDeleteClick={setDeleteConfirmId}
        onPageChange={setCurrentPage}
        onReactivate={(id) => handleAction(id, "reactivate")}
        onViewDetails={(id) =>
          router.push(`/admin/saas-management/subscriptions/${id}`)
        }
      />

      <SubscriptionsDialogs
        cancelConfirmId={cancelConfirmId}
        deleteConfirmId={deleteConfirmId}
        deleteId={deleteId}
        deleteLoading={deleteLoading}
        onCancel={(id) => handleAction(id, "cancel")}
        onCancelConfirmIdChange={setCancelConfirmId}
        onDelete={handleDelete}
        onDeleteConfirmIdChange={setDeleteConfirmId}
      />
    </div>
  );
}

"use client";

import { AlertCircle, Loader2 } from "lucide-react";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";

interface SubscriptionsDialogsProps {
  // Cancel
  cancelConfirmId: string | null;
  // Delete
  deleteConfirmId: string | null;
  deleteId: string | null;
  deleteLoading: boolean;

  onCancelConfirmIdChange: (id: string | null) => void;
  onCancel: (id: string) => Promise<void>;
  onDeleteConfirmIdChange: (id: string | null) => void;
  onDelete: (id: string) => Promise<void>;
}

export function SubscriptionsDialogs({
  cancelConfirmId,
  deleteConfirmId,
  deleteId,
  deleteLoading,
  onCancelConfirmIdChange,
  onCancel,
  onDeleteConfirmIdChange,
  onDelete,
}: SubscriptionsDialogsProps) {
  return (
    <>
      {/* Cancel Confirmation Dialog */}
      <Dialog
        open={cancelConfirmId !== null}
        onOpenChange={(open) => !open && onCancelConfirmIdChange(null)}
      >
        <DialogContent className="max-w-[calc(100vw-2rem)] sm:max-w-md">
          <DialogHeader>
            <div className="mx-auto bg-red-100 dark:bg-red-500/20 p-4 rounded-3xl w-fit mb-4">
              <AlertCircle className="h-10 w-10 text-red-600 dark:text-red-500" />
            </div>
            <DialogTitle>¿Cancelar suscripción?</DialogTitle>
            <DialogDescription>
              La organización mantendrá el acceso hasta el final del periodo
              actual. Después la suscripción quedará cancelada.
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button variant="outline" onClick={() => onCancelConfirmIdChange(null)}>
              Volver
            </Button>
            <Button
              disabled={!cancelConfirmId}
              variant="destructive"
              onClick={() =>
                cancelConfirmId && onCancel(cancelConfirmId)
              }
            >
              Confirmar cancelación
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Delete Confirmation Dialog */}
      <Dialog
        open={deleteConfirmId !== null}
        onOpenChange={(open) => !open && onDeleteConfirmIdChange(null)}
      >
        <DialogContent className="max-w-[calc(100vw-2rem)] sm:max-w-md">
          <DialogHeader>
            <div className="mx-auto bg-red-100 dark:bg-red-500/20 p-4 rounded-3xl w-fit mb-4">
              <AlertCircle className="h-10 w-10 text-red-600 dark:text-red-500" />
            </div>
            <DialogTitle>¿Eliminar esta suscripción?</DialogTitle>
            <DialogDescription>
              Esta acción no se puede deshacer. Se eliminará el registro de
              suscripción.
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button variant="outline" onClick={() => onDeleteConfirmIdChange(null)}>
              Volver
            </Button>
            <Button
              disabled={!deleteConfirmId || deleteLoading}
              variant="destructive"
              onClick={() => deleteConfirmId && onDelete(deleteConfirmId)}
            >
              {deleteLoading && deleteId === deleteConfirmId ? (
                <Loader2 className="h-4 w-4 animate-spin mr-2" />
              ) : null}
              Eliminar
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

"use client";

import { Card, CardContent } from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

interface Organization {
  id: string;
  name: string;
  slug: string;
}

interface SubscriptionsFilterBarProps {
  organizationFilter: string;
  statusFilter: string;
  tierFilter: string;
  organizations: Organization[];
  onOrganizationFilterChange: (value: string) => void;
  onStatusFilterChange: (value: string) => void;
  onTierFilterChange: (value: string) => void;
}

export function SubscriptionsFilterBar({
  organizationFilter,
  statusFilter,
  tierFilter,
  organizations,
  onOrganizationFilterChange,
  onStatusFilterChange,
  onTierFilterChange,
}: SubscriptionsFilterBarProps) {
  return (
    <Card className="admin-card">
      <CardContent className="pt-6">
        <div className="flex flex-col md:flex-row gap-4">
          <Select
            value={organizationFilter}
            onValueChange={onOrganizationFilterChange}
          >
            <SelectTrigger className="rounded-xl w-[200px]">
              <SelectValue placeholder="Filtrar por organización" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">Todas las organizaciones</SelectItem>
              {organizations.map((org) => (
                <SelectItem key={org.id} value={org.id}>
                  {org.name}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>

          <Select
            value={statusFilter}
            onValueChange={onStatusFilterChange}
          >
            <SelectTrigger className="rounded-xl w-[180px]">
              <SelectValue placeholder="Filtrar por estado" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">Todos los estados</SelectItem>
              <SelectItem value="active">Activa</SelectItem>
              <SelectItem value="trialing">Trial</SelectItem>
              <SelectItem value="past_due">Vencida</SelectItem>
              <SelectItem value="cancelled">Cancelada</SelectItem>
              <SelectItem value="incomplete">Incompleta</SelectItem>
            </SelectContent>
          </Select>

          <Select value={tierFilter} onValueChange={onTierFilterChange}>
            <SelectTrigger className="rounded-xl w-[180px]">
              <SelectValue placeholder="Filtrar por tier" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">Todos los tiers</SelectItem>
              <SelectItem value="basic">Básico</SelectItem>
              <SelectItem value="pro">Pro</SelectItem>
              <SelectItem value="premium">Premium</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import { Loader2 } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { formatDate } from "@/lib/utils";

import {
  getStatusBadge,
  getTierBadge,
  SubscriptionActionMenu,
} from "./SubscriptionStatusBadge";

interface Subscription {
  id: string;
  organization_id: string;
  status: string;
  current_period_start?: string;
  current_period_end?: string;
  cancel_at?: string;
  canceled_at?: string;
  gateway_subscription_id?: string;
  gateway_customer_id?: string;
  created_at: string;
  daysUntilExpiry?: number | null;
  isExpiringSoon?: boolean;
  isExpired?: boolean;
  organization?: {
    id: string;
    name: string;
    slug: string;
    subscription_tier: string;
    status: string;
  };
}

interface SubscriptionsTableProps {
  subscriptions: Subscription[];
  loading: boolean;
  error: string | null;
  totalCount: number;
  currentPage: number;
  totalPages: number;
  onPageChange: (page: number) => void;
  onViewDetails: (id: string) => void;
  onCancelClick: (id: string) => void;
  onReactivate: (id: string) => void;
  onDeleteClick: (id: string) => void;
}

export function SubscriptionsTable({
  subscriptions,
  loading,
  error,
  totalCount,
  currentPage,
  totalPages,
  onPageChange,
  onViewDetails,
  onCancelClick,
  onReactivate,
  onDeleteClick,
}: SubscriptionsTableProps) {
  return (
    <Card className="admin-card">
      <CardHeader>
        <CardTitle>Suscripciones ({totalCount})</CardTitle>
      </CardHeader>
      <CardContent>
        {loading ? (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="h-8 w-8 animate-spin text-blue-600" />
          </div>
        ) : error ? (
          <div className="text-center py-12 text-red-600">{error}</div>
        ) : subscriptions.length === 0 ? (
          <div className="text-center py-12 text-gray-500">
            No se encontraron suscripciones
          </div>
        ) : (
          <>
            <div className="overflow-x-auto -mx-4 px-4 md:mx-0 md:px-0">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Organización</TableHead>
                    <TableHead>Tier</TableHead>
                    <TableHead>Estado</TableHead>
                    <TableHead>Período</TableHead>
                    <TableHead>Días restantes</TableHead>
                    <TableHead>Stripe ID</TableHead>
                    <TableHead className="text-right">Acciones</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {subscriptions.map((sub) => (
                    <TableRow
                      className={
                        sub.isExpiringSoon || sub.isExpired
                          ? "bg-yellow-50"
                          : ""
                      }
                      key={sub.id}
                    >
                      <TableCell>
                        {sub.organization ? (
                          <div>
                            <div className="font-medium">
                              {sub.organization.name}
                            </div>
                            <div className="text-xs text-gray-500">
                              {sub.organization.slug}
                            </div>
                          </div>
                        ) : (
                          <span className="text-gray-400">
                            Sin organización
                          </span>
                        )}
                      </TableCell>
                      <TableCell>
                        {sub.organization
                          ? getTierBadge(sub.organization.subscription_tier)
                          : "-"}
                      </TableCell>
                      <TableCell>
                        {getStatusBadge(
                          sub.status,
                          sub.isExpiringSoon,
                          sub.isExpired,
                        )}
                      </TableCell>
                      <TableCell>
                        {sub.current_period_start && sub.current_period_end ? (
                          <div className="text-sm">
                            <div>{formatDate(sub.current_period_start)}</div>
                            <div className="text-gray-500">
                              hasta {formatDate(sub.current_period_end)}
                            </div>
                          </div>
                        ) : (
                          <span className="text-gray-400">-</span>
                        )}
                      </TableCell>
                      <TableCell>
                        {sub.daysUntilExpiry !== null ? (
                          <div
                            className={
                              sub.isExpiringSoon || sub.isExpired
                                ? "font-semibold text-yellow-600"
                                : ""
                            }
                          >
                            {sub.daysUntilExpiry != null &&
                            sub.daysUntilExpiry > 0
                              ? `${sub.daysUntilExpiry} días`
                              : sub.daysUntilExpiry != null &&
                                  sub.daysUntilExpiry === 0
                                ? "Hoy"
                                : sub.daysUntilExpiry != null
                                  ? `Vencida hace ${Math.abs(sub.daysUntilExpiry)} días`
                                  : "N/A"}
                          </div>
                        ) : (
                          <span className="text-gray-400">-</span>
                        )}
                      </TableCell>
                      <TableCell>
                        {sub.gateway_subscription_id ? (
                          <code className="text-xs bg-gray-100 px-2 py-1 rounded">
                            {sub.gateway_subscription_id.substring(0, 20)}...
                          </code>
                        ) : (
                          <span className="text-gray-400">-</span>
                        )}
                      </TableCell>
                      <TableCell className="text-right">
                        <SubscriptionActionMenu
                          status={sub.status}
                          onCancel={
                            sub.status !== "cancelled"
                              ? () => onCancelClick(sub.id)
                              : undefined
                          }
                          onDelete={() => onDeleteClick(sub.id)}
                          onReactivate={
                            sub.status === "cancelled"
                              ? () => onReactivate(sub.id)
                              : undefined
                          }
                          onView={() => onViewDetails(sub.id)}
                        />
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>

            {totalPages > 1 && (
              <div className="flex items-center justify-between mt-4">
                <div className="text-sm text-gray-600">
                  Página {currentPage} de {totalPages}
                </div>
                <div className="flex gap-2">
                  <Button
                    disabled={currentPage === 1}
                    size="sm"
                    variant="outline"
                    onClick={() => onPageChange(Math.max(1, currentPage - 1))}
                  >
                    Anterior
                  </Button>
                  <Button
                    disabled={currentPage === totalPages}
                    size="sm"
                    variant="outline"
                    onClick={() =>
                      onPageChange(Math.min(totalPages, currentPage + 1))
                    }
                  >
                    Siguiente
                  </Button>
                </div>
              </div>
            )}
          </>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import { ArrowLeft, MessageSquare, Search } from "lucide-react";
import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { SupportMetrics } from "@/components/admin/saas-support/SupportMetrics";
import { Button } from "@/components/ui/button";
import {
  extractDataFromResponse,
  extractPaginationFromResponse,
} from "@/lib/api/response-helpers";

import { SupportSearchResults } from "./SupportSearchResults";
import { SupportTicketFilters } from "./SupportTicketFilters";
import { SupportTicketList } from "./SupportTicketList";

interface SearchResult {
  organizations: Array<{
    id: string;
    name: string;
    slug: string;
    status: string;
    subscription_tier: string;
  }>;
  users: Array<{
    id: string;
    email: string;
    role: string;
    is_active: boolean;
    organization_id?: string;
    organization?: { id: string; name: string; slug: string };
    profiles?: { first_name?: string; last_name?: string };
  }>;
}

interface Ticket {
  id: string;
  ticket_number: string;
  subject: string;
  category: string;
  priority: string;
  status: string;
  created_at: string;
  organization?: { id: string; name: string; slug: string } | null;
  assigned_to_user?: { id: string; email: string; role: string } | null;
}

const statusLabels: Record<string, string> = {
  open: "Abierto",
  assigned: "Asignado",
  in_progress: "En Progreso",
  waiting_customer: "Esperando Cliente",
  resolved: "Resuelto",
  closed: "Cerrado",
};

const statusColors: Record<string, string> = {
  open: "bg-blue-100 text-blue-800",
  assigned: "bg-yellow-100 text-yellow-800",
  in_progress: "bg-purple-100 text-purple-800",
  waiting_customer: "bg-orange-100 text-orange-800",
  resolved: "bg-green-100 text-green-800",
  closed: "bg-gray-100 text-gray-800",
};

const priorityColors: Record<string, string> = {
  low: "bg-gray-100 text-gray-800",
  medium: "bg-blue-100 text-blue-800",
  high: "bg-orange-100 text-orange-800",
  urgent: "bg-red-100 text-red-800",
};

const categoryLabels: Record<string, string> = {
  technical: "Técnico",
  billing: "Facturación",
  feature_request: "Funcionalidad",
  bug_report: "Bug",
  account: "Cuenta",
  other: "Otro",
};

export default function SupportContent() {
  const router = useRouter();
  const [activeTab, setActiveTab] = useState<"tickets" | "metrics" | "search">(
    "tickets",
  );

  // Search state
  const [searchQuery, setSearchQuery] = useState("");
  const [searchResults, setSearchResults] = useState<SearchResult>({
    organizations: [],
    users: [],
  });
  const [searching, setSearching] = useState(false);
  const [hasSearched, setHasSearched] = useState(false);

  // Tickets state
  const [tickets, setTickets] = useState<Ticket[]>([]);
  const [loadingTickets, setLoadingTickets] = useState(true);
  const [filters, setFilters] = useState({
    status: "all",
    priority: "all",
    category: "all",
    search: "",
  });
  const [pagination, setPagination] = useState({
    page: 1,
    limit: 20,
    total: 0,
    totalPages: 0,
  });

  // Load tickets
  useEffect(() => {
    loadTickets();
  }, [filters, pagination.page]);

  const loadTickets = async () => {
    setLoadingTickets(true);
    try {
      const params = new URLSearchParams({
        page: pagination.page.toString(),
        limit: pagination.limit.toString(),
      });

      if (filters.status && filters.status !== "all") {
        params.append("status", filters.status);
      }
      if (filters.priority && filters.priority !== "all") {
        params.append("priority", filters.priority);
      }
      if (filters.category && filters.category !== "all") {
        params.append("category", filters.category);
      }
      if (filters.search) {
        params.append("search", filters.search);
      }

      const response = await fetch(
        `/api/admin/saas-management/support/tickets?${params.toString()}`,
      );

      if (!response.ok) {
        throw new Error("Error al cargar tickets");
      }

      const data = await response.json();
      const paginationData = extractPaginationFromResponse(data);
      setTickets(extractDataFromResponse(data));
      setPagination((prev) => ({
        ...prev,
        total: paginationData.total || 0,
        totalPages: paginationData.totalPages || 0,
      }));
    } catch (err) {
      toast.error("Error al cargar tickets");
    } finally {
      setLoadingTickets(false);
    }
  };

  // Search functionality
  useEffect(() => {
    const timeoutId = setTimeout(() => {
      if (searchQuery.length >= 2) {
        performSearch();
      } else {
        setSearchResults({ organizations: [], users: [] });
        setHasSearched(false);
      }
    }, 300);

    return () => clearTimeout(timeoutId);
  }, [searchQuery]);

  const performSearch = async () => {
    setSearching(true);
    setHasSearched(true);
    try {
      const response = await fetch(
        `/api/admin/saas-management/support/search?q=${encodeURIComponent(searchQuery)}`,
      );

      if (!response.ok) {
        throw new Error("Error en la búsqueda");
      }

      const data = await response.json();
      setSearchResults(data);
    } catch (err) {
      toast.error("Error al realizar búsqueda");
      setSearchResults({ organizations: [], users: [] });
    } finally {
      setSearching(false);
    }
  };

  return (
    <div className="space-y-6 p-6 bg-[#0D1117] min-h-screen">
      <div className="flex items-center gap-4">
        <Button
          className="rounded-xl text-white hover:bg-white/10"
          size="icon"
          title="Volver al dashboard"
          variant="ghost"
          onClick={() => router.push("/admin/saas-management/dashboard")}
        >
          <ArrowLeft className="h-5 w-5" />
        </Button>
        <div>
          <h1 className="text-3xl font-display font-bold text-white tracking-tight">
            Panel de Soporte
          </h1>
          <p className="text-white/50 mt-2">
            Gestión de tickets de soporte SaaS y búsqueda rápida
          </p>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex gap-2 border-b border-white/10">
        <Button
          className={`rounded-xl rounded-b-none ${activeTab === "tickets" ? "bg-epoch-primary hover:bg-epoch-surface text-white font-display font-bold text-[10px] tracking-[0.2em] uppercase" : "text-epoch-primary"}`}
          variant={activeTab === "tickets" ? "default" : "ghost"}
          onClick={() => setActiveTab("tickets")}
        >
          <MessageSquare className="h-4 w-4 mr-2" />
          Tickets de Soporte
        </Button>
        <Button
          className={`rounded-xl rounded-b-none ${activeTab === "search" ? "bg-epoch-primary hover:bg-epoch-surface text-white font-display font-bold text-[10px] tracking-[0.2em] uppercase" : "text-epoch-primary"}`}
          variant={activeTab === "search" ? "default" : "ghost"}
          onClick={() => setActiveTab("search")}
        >
          <Search className="h-4 w-4 mr-2" />
          Búsqueda Rápida
        </Button>
      </div>

      {/* Metrics Tab */}
      {activeTab === "metrics" && (
        <div className="space-y-6">
          <SupportMetrics />
        </div>
      )}

      {/* Tickets Tab */}
      {activeTab === "tickets" && (
        <div className="space-y-6">
          <SupportTicketFilters
            categoryLabels={categoryLabels}
            filters={filters}
            statusLabels={statusLabels}
            onFilterChange={(updates) =>
              setFilters((prev) => ({ ...prev, ...updates, page: 1 }))
            }
            onRefresh={loadTickets}
          />

          <SupportTicketList
            categoryLabels={categoryLabels}
            loading={loadingTickets}
            page={pagination.page}
            priorityColors={priorityColors}
            statusColors={statusColors}
            statusLabels={statusLabels}
            tickets={tickets}
            total={pagination.total}
            totalPages={pagination.totalPages}
            onPageChange={(page) =>
              setPagination((prev) => ({ ...prev, page }))
            }
          />
        </div>
      )}

      {/* Search Tab */}
      {activeTab === "search" && (
        <SupportSearchResults
          hasSearched={hasSearched}
          searching={searching}
          searchQuery={searchQuery}
          searchResults={searchResults}
          onSearchQueryChange={setSearchQuery}
        />
      )}
    </div>
  );
}

import {
  ArrowRight,
  Building2,
  CheckCircle2,
  Search,
  User,
  XCircle,
} from "lucide-react";
import Link from "next/link";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";

interface SearchResult {
  organizations: Array<{
    id: string;
    name: string;
    slug: string;
    status: string;
    subscription_tier: string;
  }>;
  users: Array<{
    id: string;
    email: string;
    role: string;
    is_active: boolean;
    organization_id?: string;
    organization?: { id: string; name: string; slug: string };
    profiles?: { first_name?: string; last_name?: string };
  }>;
}

interface SupportSearchResultsProps {
  searchQuery: string;
  onSearchQueryChange: (value: string) => void;
  searchResults: SearchResult;
  searching: boolean;
  hasSearched: boolean;
}

function getStatusBadge(status: string) {
  const variants: Record<string, "default" | "secondary" | "destructive"> = {
    active: "default",
    suspended: "secondary",
    cancelled: "destructive",
  };
  const Icon = status === "active" ? CheckCircle2 : XCircle;
  return (
    <Badge variant={variants[status] || "default"}>
      <Icon className="h-3 w-3 mr-1" />
      {status === "active" ? "Activa" : status === "suspended" ? "Suspendida" : "Cancelada"}
    </Badge>
  );
}

export function SupportSearchResults({
  searchQuery,
  onSearchQueryChange,
  searchResults,
  searching,
  hasSearched,
}: SupportSearchResultsProps) {
  return (
    <div className="space-y-6">
      <Card className="admin-card">
        <CardContent className="pt-6">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-epoch-accent" />
            <Input
              className="pl-10 rounded-xl focus:border-epoch-primary focus:ring-epoch-primary/20"
              placeholder="Buscar por nombre, slug, email..."
              value={searchQuery}
              onChange={(e) => onSearchQueryChange(e.target.value)}
            />
          </div>
          {searching && (
            <div className="flex items-center gap-2 mt-4 text-sm text-epoch-primary/80">
              Buscando...
            </div>
          )}
        </CardContent>
      </Card>

      {/* Resultados */}
      {hasSearched && !searching && (
        <div className="space-y-6">
          {searchResults.organizations.length > 0 && (
            <Card className="admin-card">
              <CardHeader>
                <CardTitle className="flex items-center gap-2 font-display text-epoch-primary">
                  <Building2 className="h-5 w-5 text-epoch-accent" />
                  Organizaciones ({searchResults.organizations.length})
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-3">
                  {searchResults.organizations.map((org) => (
                    <div
                      className="flex items-center justify-between p-4 border rounded-xl hover:bg-epoch-primary/5 transition-colors"
                      key={org.id}
                    >
                      <div className="flex-1">
                        <div className="flex items-center gap-2">
                          <h3 className="font-medium text-epoch-primary">{org.name}</h3>
                          {getStatusBadge(org.status)}
                          <Badge variant="outline">{org.subscription_tier}</Badge>
                        </div>
                        <p className="text-sm text-epoch-primary/70 mt-1">{org.slug}</p>
                      </div>
                      <Link href={`/admin/saas-management/organizations/${org.id}`}>
                        <Button className="rounded-xl border-admin-border-primary/20" size="sm" variant="outline">
                          Ver detalles
                          <ArrowRight className="h-4 w-4 ml-2" />
                        </Button>
                      </Link>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          )}

          {searchResults.users.length > 0 && (
            <Card className="admin-card">
              <CardHeader>
                <CardTitle className="flex items-center gap-2 font-display text-epoch-primary">
                  <User className="h-5 w-5 text-epoch-accent" />
                  Usuarios ({searchResults.users.length})
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-3">
                  {searchResults.users.map((user) => (
                    <div
                      className="flex items-center justify-between p-4 border rounded-xl hover:bg-epoch-primary/5 transition-colors"
                      key={user.id}
                    >
                      <div className="flex-1">
                        <div className="flex items-center gap-2">
                          <h3 className="font-medium text-epoch-primary">
                            {user.profiles?.first_name} {user.profiles?.last_name}
                          </h3>
                          <Badge variant="outline">{user.role}</Badge>
                          {user.is_active ? (
                            <Badge variant="default">
                              <CheckCircle2 className="h-3 w-3 mr-1" />
                              Activo
                            </Badge>
                          ) : (
                            <Badge variant="secondary">
                              <XCircle className="h-3 w-3 mr-1" />
                              Inactivo
                            </Badge>
                          )}
                        </div>
                        <p className="text-sm text-epoch-primary/70 mt-1">{user.email}</p>
                        {user.organization && (
                          <p className="text-xs text-epoch-primary/60 mt-1">
                            Organización: {user.organization.name}
                          </p>
                        )}
                      </div>
                      <Link href={`/admin/saas-management/users/${user.id}`}>
                        <Button className="rounded-xl border-admin-border-primary/20" size="sm" variant="outline">
                          Ver detalles
                          <ArrowRight className="h-4 w-4 ml-2" />
                        </Button>
                      </Link>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          )}

          {searchResults.organizations.length === 0 &&
            searchResults.users.length === 0 && (
              <Card className="admin-card">
                <CardContent className="pt-6">
                  <div className="text-center py-8 text-epoch-primary/70">
                    No se encontraron resultados para &ldquo;{searchQuery}&rdquo;
                  </div>
                </CardContent>
              </Card>
            )}
        </div>
      )}

      {!hasSearched && (
        <Card className="admin-card">
          <CardContent className="pt-6">
            <div className="text-center py-8 text-epoch-primary/70">
              <Search className="h-12 w-12 mx-auto mb-4 text-epoch-accent" />
              <p className="text-lg font-medium mb-2">Busca organizaciones o usuarios</p>
              <p className="text-sm">Ingresa al menos 2 caracteres para comenzar la búsqueda</p>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import { Filter, RefreshCw } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

interface Filters {
  status: string;
  priority: string;
  category: string;
  search: string;
}

interface SupportTicketFiltersProps {
  filters: Filters;
  onFilterChange: (updates: Partial<Filters>) => void;
  onRefresh: () => void;
  statusLabels: Record<string, string>;
  priorityLabels?: Record<string, string>;
  categoryLabels: Record<string, string>;
}

export function SupportTicketFilters({
  filters,
  onFilterChange,
  onRefresh,
  statusLabels,
  categoryLabels,
}: SupportTicketFiltersProps) {
  return (
    <Card className="admin-card">
      <CardHeader>
        <CardTitle className="flex items-center gap-2 font-display text-epoch-primary">
          <Filter className="h-5 w-5 text-epoch-accent" />
          Filtros
        </CardTitle>
      </CardHeader>
      <CardContent>
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div className="space-y-2">
            <label className="text-sm font-medium">Estado</label>
            <Select
              value={filters.status}
              onOpenChange={() => {}}
              onValueChange={(value) =>
                onFilterChange({ status: value, ...(value !== filters.status && {} ) })
              }
            >
              <SelectTrigger className="rounded-xl focus:border-epoch-primary focus:ring-epoch-primary/20">
                <SelectValue placeholder="Todos los estados" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Todos los estados</SelectItem>
                {Object.entries(statusLabels).map(([value, label]) => (
                  <SelectItem key={value} value={value}>
                    {label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium">Prioridad</label>
            <Select
              value={filters.priority}
              onValueChange={(value) =>
                onFilterChange({ priority: value })
              }
            >
              <SelectTrigger className="rounded-xl focus:border-epoch-primary focus:ring-epoch-primary/20">
                <SelectValue placeholder="Todas las prioridades" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Todas las prioridades</SelectItem>
                <SelectItem value="low">Baja</SelectItem>
                <SelectItem value="medium">Media</SelectItem>
                <SelectItem value="high">Alta</SelectItem>
                <SelectItem value="urgent">Urgente</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium">Categoría</label>
            <Select
              value={filters.category}
              onValueChange={(value) =>
                onFilterChange({ category: value })
              }
            >
              <SelectTrigger className="rounded-xl focus:border-epoch-primary focus:ring-epoch-primary/20">
                <SelectValue placeholder="Todas las categorías" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Todas las categorías</SelectItem>
                {Object.entries(categoryLabels).map(([value, label]) => (
                  <SelectItem key={value} value={value}>
                    {label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium">Buscar</label>
            <div className="flex gap-2">
              <Input
                className="rounded-xl focus:border-epoch-primary focus:ring-epoch-primary/20"
                placeholder="Ticket #, asunto, email..."
                value={filters.search}
                onChange={(e) =>
                  onFilterChange({ search: e.target.value })
                }
              />
              <Button
                className="rounded-xl border-admin-border-primary/20"
                size="icon"
                title="Refrescar"
                variant="outline"
                onClick={onRefresh}
              >
                <RefreshCw className="h-4 w-4" />
              </Button>
            </div>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

import {
  ArrowRight,
  Building2,
  Loader2,
  MessageSquare,
  User,
} from "lucide-react";
import Link from "next/link";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";

interface Ticket {
  id: string;
  ticket_number: string;
  subject: string;
  category: string;
  priority: string;
  status: string;
  created_at: string;
  organization?: { id: string; name: string; slug: string } | null;
  assigned_to_user?: { id: string; email: string; role: string } | null;
}

interface SupportTicketListProps {
  tickets: Ticket[];
  loading: boolean;
  total: number;
  page: number;
  totalPages: number;
  onPageChange: (page: number) => void;
  statusLabels: Record<string, string>;
  statusColors: Record<string, string>;
  priorityColors: Record<string, string>;
  categoryLabels: Record<string, string>;
}

export function SupportTicketList({
  tickets,
  loading,
  total,
  page,
  totalPages,
  onPageChange,
  statusLabels,
  statusColors,
  priorityColors,
  categoryLabels,
}: SupportTicketListProps) {
  return (
    <Card className="admin-card">
      <CardHeader>
        <CardTitle className="font-display text-epoch-primary">
          Tickets ({total})
        </CardTitle>
      </CardHeader>
      <CardContent>
        {loading ? (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="h-8 w-8 animate-spin text-epoch-primary" />
          </div>
        ) : tickets.length === 0 ? (
          <div className="text-center py-12 text-epoch-primary/70">
            <MessageSquare className="h-12 w-12 mx-auto mb-4 text-epoch-accent" />
            <p>No hay tickets que coincidan con los filtros</p>
          </div>
        ) : (
          <div className="space-y-2">
            {tickets.map((ticket) => (
              <Link
                href={`/admin/saas-management/support/tickets/${ticket.id}`}
                key={ticket.id}
              >
                <div className="flex items-center justify-between p-4 border rounded-xl hover:bg-epoch-primary/5 cursor-pointer transition-colors">
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-1">
                      <span className="font-mono font-semibold text-sm">
                        {ticket.ticket_number}
                      </span>
                      <Badge className={statusColors[ticket.status]}>
                        {statusLabels[ticket.status]}
                      </Badge>
                      <Badge className={priorityColors[ticket.priority]}>
                        {ticket.priority}
                      </Badge>
                      <Badge variant="outline">
                        {categoryLabels[ticket.category]}
                      </Badge>
                    </div>
                    <h3 className="font-medium text-epoch-primary">
                      {ticket.subject}
                    </h3>
                    <div className="flex items-center gap-4 mt-2 text-sm text-epoch-primary/70">
                      {ticket.organization && (
                        <span className="flex items-center gap-1">
                          <Building2 className="h-4 w-4" />
                          {ticket.organization.name}
                        </span>
                      )}
                      {ticket.assigned_to_user && (
                        <span className="flex items-center gap-1">
                          <User className="h-4 w-4" />
                          {ticket.assigned_to_user.email}
                        </span>
                      )}
                      <span>
                        {new Date(ticket.created_at).toLocaleDateString("es-CL")}
                      </span>
                    </div>
                  </div>
                  <ArrowRight className="h-5 w-5 text-epoch-accent" />
                </div>
              </Link>
            ))}
          </div>
        )}

        {totalPages > 1 && (
          <div className="flex items-center justify-between mt-6 pt-4 border-t">
            <p className="text-sm text-epoch-primary/80">
              Página {page} de {totalPages}
            </p>
            <div className="flex gap-2">
              <Button
                className="rounded-xl border-admin-border-primary/20"
                disabled={page === 1}
                size="sm"
                variant="outline"
                onClick={() => onPageChange(Math.max(1, page - 1))}
              >
                Anterior
              </Button>
              <Button
                className="rounded-xl border-admin-border-primary/20"
                disabled={page === totalPages}
                size="sm"
                variant="outline"
                onClick={() => onPageChange(Math.min(totalPages, page + 1))}
              >
                Siguiente
              </Button>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import {
