  const {
    ticket,
    messages,
    templates,
    loading,
    sendingMessage,
    updatingTicket,
    showAssignDialog,
    showStatusDialog,
    showTemplateDialog,
    newStatus,
    newPriority,
    newResolution,
    register,
    errors,
    handleSubmit,
    setShowAssignDialog,
    setShowStatusDialog,
    setShowTemplateDialog,
    setNewStatus,
    setNewPriority,
