        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Main Content */}
          <div className="lg:col-span-2 space-y-6">
            <Card className="rounded-xl border border-border">
              <CardHeader>
                <CardTitle>Detalles del Ticket</CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <Label className="text-sm font-medium text-gray-700">
                      Solicitante
                    </Label>
                    <p className="mt-1">
                      {ticket.requester_name || ticket.requester_email}
                    </p>
                    <p className="text-sm text-gray-500">
                      {ticket.requester_email}
                    </p>
                  </div>
                  {ticket.organization && (
                    <div>
                      <Label className="text-sm font-medium text-gray-700">
                        Organización
                      </Label>
                      <p className="mt-1">{ticket.organization.name}</p>
                    </div>
                  )}
                </div>
                <div>
                  <Label className="text-sm font-medium text-gray-700">
                    Descripción
                  </Label>
                  <p className="mt-1 text-gray-900 whitespace-pre-wrap">
                    {ticket.description}
                  </p>
                </div>
                {ticket.resolution && (
                  <div>
                    <Label className="text-sm font-medium text-gray-700">
                      Resolución
                    </Label>
                    <p className="mt-1 text-gray-900 whitespace-pre-wrap">
                      {ticket.resolution}
                    </p>
                  </div>
                )}
              </CardContent>
            </Card>

            <TicketMessagesList messages={messages} />

            <TicketMessageForm
              errors={errors}
              register={register}
              sendingMessage={sendingMessage}
              onSubmit={handleSubmit(onSubmitMessage)}
              onUseTemplate={() => setShowTemplateDialog(true)}
            />
          </div>

          {/* Sidebar */}
          <div className="space-y-6">
            <Card className="rounded-xl border border-border">
              <CardHeader>
                <CardTitle className="text-lg">Acciones Rápidas</CardTitle>
              </CardHeader>
              <CardContent className="space-y-2">
                <Button
                  className="w-full justify-start"
                  variant="outline"
                  onClick={() => setShowStatusDialog(true)}
                >
                  <Edit className="h-4 w-4 mr-2" />
                  Cambiar Estado/Prioridad
                </Button>
                <Button
                  className="w-full justify-start"
                  variant="outline"
                  onClick={() => setShowAssignDialog(true)}
                >
                  <UserPlus className="h-4 w-4 mr-2" />
                  Asignar Ticket
                </Button>
              </CardContent>
            </Card>

            <TicketInfoPanel ticket={ticket} />
          </div>
        </div>

        <TicketStatusDialog
          open={showStatusDialog}
          priority={newPriority}
          resolution={newResolution}
          status={newStatus}
          statusLabels={statusLabels}
          updating={updatingTicket}
          onOpenChange={setShowStatusDialog}
          onPriorityChange={setNewPriority}
          onResolutionChange={setNewResolution}
          onSave={handleUpdateStatus}
          onStatusChange={setNewStatus}
        />

        <TicketTemplateDialog
          categoryLabels={categoryLabels}
          open={showTemplateDialog}
          templates={templates}
          onOpenChange={setShowTemplateDialog}
          onSelect={(template) => handleUseTemplate(template as unknown)}
        />
      </div>
    </div>
  );
}

import { FileText, Loader2, Send } from "lucide-react";
// eslint-disable-next-line @typescript-eslint/no-explicit-any
import type { FieldErrors,UseFormRegister } from "react-hook-form";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";

interface TicketMessageFormProps {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  register: UseFormRegister<any>;
  errors: FieldErrors;
  sendingMessage: boolean;
  onSubmit: React.FormEventHandler;
  onUseTemplate: () => void;
}

export function TicketMessageForm({
  register,
  errors,
  sendingMessage,
  onSubmit,
  onUseTemplate,
}: TicketMessageFormProps) {
  return (
    <Card className="rounded-xl border border-border">
      <CardHeader>
        <div className="flex items-center justify-between">
          <CardTitle>Responder</CardTitle>
          <Button size="sm" variant="outline" onClick={onUseTemplate}>
            <FileText className="h-4 w-4 mr-2" />
            Usar Template
          </Button>
        </div>
      </CardHeader>
      <CardContent>
        <form className="space-y-4" onSubmit={onSubmit}>
          <div className="flex items-center gap-2">
            <input
              id="is_internal"
              type="checkbox"
              {...register("is_internal")}
              className="rounded"
            />
            <Label className="text-sm" htmlFor="is_internal">
              Mensaje interno (no visible para el cliente)
            </Label>
          </div>

          <div className="space-y-2">
            <Label htmlFor="message">
              Mensaje <span className="text-red-500">*</span>
            </Label>
            <Textarea
              id="message"
              {...register("message")}
              className={errors.message ? "border-red-500" : ""}
              placeholder="Escribe tu respuesta aquí..."
              rows={6}
            />
            {errors.message && (
              <p className="text-sm text-red-500">
                {String(errors.message.message)}
              </p>
            )}
          </div>

          <Button className="w-full" disabled={sendingMessage} type="submit">
            {sendingMessage ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Enviando...
              </>
            ) : (
              <>
                <Send className="mr-2 h-4 w-4" />
                Enviar Mensaje
              </>
            )}
          </Button>
        </form>
      </CardContent>
    </Card>
  );
}

import { MessageSquare, User } from "lucide-react";

import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";

interface TicketMessage {
  id: string;
  message: string;
  sender_name: string;
  is_from_customer: boolean;
  is_internal: boolean;
  created_at: string;
}

interface TicketMessagesListProps {
  messages: TicketMessage[];
}

export function TicketMessagesList({ messages }: TicketMessagesListProps) {
  return (
    <Card className="rounded-xl border border-border">
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <MessageSquare className="h-5 w-5" />
          Conversación ({messages.length})
        </CardTitle>
      </CardHeader>
      <CardContent>
        {messages.length === 0 ? (
          <div className="text-center py-8 text-gray-500">
            <MessageSquare className="h-12 w-12 mx-auto mb-4 text-gray-400" />
            <p>No hay mensajes aún</p>
          </div>
        ) : (
          <div className="space-y-4">
            {messages.map((msg) => (
              <div
                className={`p-4 rounded-lg border ${
                  msg.is_internal
                    ? "bg-yellow-50 border-yellow-200"
                    : msg.is_from_customer
                      ? "bg-blue-50 border-blue-200"
                      : "bg-gray-50 border-gray-200"
