  const {
    register,
    handleSubmit,
    formState: { errors },
    reset,
    setValue,
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
  } = useForm<any>({
    resolver: zodResolver(createSaasSupportMessageSchema),
    defaultValues: {
      is_internal: false,
      message_type: "message",
    },
  });

  const fetchTicket = useCallback(async () => {
    try {
      const response = await fetch(
        `/api/admin/saas-management/support/tickets/${ticketId}`,
      );
      if (!response.ok) throw new Error("Error al cargar el ticket");
      const data = await response.json();
      setTicket(data.ticket);
      setNewStatus(data.ticket.status);
      setNewPriority(data.ticket.priority);
    } catch {
      toast.error("Error al cargar el ticket");
    } finally {
      setLoading(false);
    }
  }, [ticketId]);

  const fetchMessages = useCallback(async () => {
    try {
      const response = await fetch(
        `/api/admin/saas-management/support/tickets/${ticketId}/messages`,
      );
      if (response.ok) {
        const data = await response.json();
        setMessages(data.messages || []);
      }
    } catch (err) {
      appLogger.error("Error fetching messages:", err);
    }
  }, [ticketId]);

  const fetchTemplates = useCallback(async () => {
    try {
      const response = await fetch(
        `/api/admin/saas-management/support/templates?is_active=true`,
      );
      if (response.ok) {
        const data = await response.json();
        setTemplates(data.templates || []);
      }
    } catch (err) {
      appLogger.error("Error fetching templates:", err);
    }
  }, []);

  useEffect(() => {
    fetchTicket();
    fetchMessages();
    fetchTemplates();
  }, [fetchTicket, fetchMessages, fetchTemplates]);

  const onSubmitMessage: SubmitHandler<unknown> = useCallback(
    async (data) => {
      setSendingMessage(true);
      try {
        const response = await fetch(
          `/api/admin/saas-management/support/tickets/${ticketId}/messages`,
          {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(data),
          },
        );
        if (!response.ok) {
          const result = await response.json();
          throw new Error(result.error || "Error al enviar mensaje");
        }
        toast.success("Mensaje enviado exitosamente");
        reset();
        fetchMessages();
        fetchTicket();
      } catch (err) {
        toast.error(
          err instanceof Error ? err.message : "Error al enviar mensaje",
        );
      } finally {
        setSendingMessage(false);
      }
    },
    [ticketId, reset, fetchMessages, fetchTicket],
  );

  const handleUpdateStatus = useCallback(async () => {
    setUpdatingTicket(true);
    try {
      const updates: Record<string, unknown> = {
        status: newStatus,
        priority: newPriority,
      };
      if (newStatus === "resolved" || newStatus === "closed") {
        updates.resolution = newResolution || null;
      }
      const response = await fetch(
        `/api/admin/saas-management/support/tickets/${ticketId}`,
        {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(updates),
        },
      );
      if (!response.ok) {
        const result = await response.json();
        throw new Error(result.error || "Error al actualizar ticket");
      }
      toast.success("Ticket actualizado exitosamente");
      setShowStatusDialog(false);
      fetchTicket();
    } catch (err) {
      toast.error(
        err instanceof Error ? err.message : "Error al actualizar ticket",
      );
    } finally {
      setUpdatingTicket(false);
    }
  }, [ticketId, newStatus, newPriority, newResolution, fetchTicket]);

  const handleUseTemplate = useCallback(
    (template: Template) => {
      setValue("message", template.content);
      setShowTemplateDialog(false);
    },
    [setValue],
  );

  const copyTicketNumber = useCallback(() => {
    if (ticket?.ticket_number) {
      navigator.clipboard.writeText(ticket.ticket_number);
      toast.success("Número de ticket copiado");
    }
  }, [ticket]);

  return {
    ticketId,
    ticket,
    messages,
    templates,
    loading,
    sendingMessage,
    updatingTicket,
    showAssignDialog,
    showStatusDialog,
    showTemplateDialog,
    newStatus,
    newPriority,
    newResolution,
    register,
    errors,
    handleSubmit,
    setShowAssignDialog,
    setShowStatusDialog,
    setShowTemplateDialog,
    setNewStatus,
    setNewPriority,
    setNewResolution,
    onSubmitMessage,
    handleUpdateStatus,
    handleUseTemplate,
    copyTicketNumber,
  };
}

"use client";

import { Loader2 } from "lucide-react";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { TIER_FEATURE_LABELS } from "@/lib/saas/tier-constants";

interface EditData {
  price_monthly: number;
  max_branches: number;
  max_users: number;
  max_customers: number;
  max_products: number;
  features: Record<string, boolean>;
}

interface TierEditDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  tierName: string;
  editData: EditData;
  onEditDataChange: (data: Partial<EditData>) => void;
  onSave: () => void;
  saving: boolean;
}

export function TierEditDialog({
  open,
  onOpenChange,
  tierName,
  editData,
  onEditDataChange,
  onSave,
  saving,
}: TierEditDialogProps) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-[calc(100vw-2rem)] sm:max-w-2xl">
        <DialogHeader>
          <DialogTitle>Editar Tier: {tierName}</DialogTitle>
          <DialogDescription>
            Modifica los límites y características del tier
          </DialogDescription>
        </DialogHeader>
        <div className="space-y-4">
          <div>
            <Label>Precio Mensual (CLP)</Label>
            <Input
              type="number"
              value={editData.price_monthly}
              onChange={(e) =>
                onEditDataChange({
                  price_monthly: parseFloat(e.target.value) || 0,
                })
              }
            />
          </div>
          <div className="grid grid-cols-2 gap-4">
            {(
              [
                "max_branches",
                "max_users",
                "max_customers",
                "max_products",
              ] as const
            ).map((key) => (
              <div key={key}>
                <Label>
                  Máx.{" "}
                  {key.replace("max_", "").charAt(0).toUpperCase() +
                    key.replace("max_", "").slice(1)}{" "}
                  (0 = ilimitado)
                </Label>
                <Input
                  type="number"
                  value={editData[key]}
                  onChange={(e) =>
                    onEditDataChange({ [key]: parseInt(e.target.value) || 0 })
                  }
                />
              </div>
            ))}
          </div>
          <div>
            <Label>Features</Label>
            <div className="grid grid-cols-2 gap-2 mt-2">
              {Object.keys(TIER_FEATURE_LABELS).map((key) => (
                <label
                  className="flex items-center gap-2 cursor-pointer"
                  key={key}
                >
                  <input
                    checked={editData.features[key] || false}
                    type="checkbox"
                    onChange={(e) =>
                      onEditDataChange({
                        features: {
                          ...editData.features,
                          [key]: e.target.checked,
                        },
                      })
                    }
                  />
                  <span className="text-sm">
                    {
                      TIER_FEATURE_LABELS[
                        key as keyof typeof TIER_FEATURE_LABELS
                      ]
                    }
                  </span>
                </label>
              ))}
            </div>
          </div>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancelar
          </Button>
          <Button disabled={saving} onClick={onSave}>
            {saving ? (
              <>
                <Loader2 className="h-4 w-4 mr-2 animate-spin" /> Guardando...
              </>
            ) : (
              "Guardar"
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

export function formatPrice(value: number) {
  return new Intl.NumberFormat("es-CL", {
    style: "currency",
    currency: "CLP",
  }).format(value);
}

export function getTierColor(name: string) {
  const colors: Record<string, string> = {
    basic: "bg-gray-100 text-gray-800 border-gray-300",
    pro: "bg-blue-100 text-blue-800 border-blue-300",
    premium: "bg-purple-100 text-purple-800 border-purple-300",
  };
  return colors[name] || colors.basic;
}

export function toLimitPayload(v: number) {
  return v === 0 ? null : v;
}

"use client";

import { useCallback, useEffect, useState } from "react";
import { toast } from "sonner";

import { toLimitPayload } from "./tierHelpers";
import type { Tier, TierEditData } from "./types";

export function useTiersPage() {
  const [tiers, setTiers] = useState<Tier[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [showEditDialog, setShowEditDialog] = useState(false);
  const [selectedTier, setSelectedTier] = useState<Tier | null>(null);
  const [editing, setEditing] = useState(false);
  const [editData, setEditData] = useState<TierEditData>({
    price_monthly: 0,
    max_branches: 0,
    max_users: 0,
    max_customers: 0,
    max_products: 0,
    features: {},
  });

  const fetchTiers = useCallback(async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/admin/saas-management/tiers");
      if (!response.ok) throw new Error("Error al cargar tiers");
      const data = await response.json();
      setTiers(data.tiers || []);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Error desconocido");
      toast.error("Error al cargar tiers");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchTiers();
  }, [fetchTiers]);

  const handleEdit = useCallback((tier: Tier) => {
    setSelectedTier(tier);
    setEditData({
      price_monthly: tier.price_monthly,
      max_branches: tier.max_branches || 0,
      max_users: tier.max_users || 0,
      max_customers: tier.max_customers || 0,
      max_products: tier.max_products || 0,
      features: tier.features || {},
    });
    setShowEditDialog(true);
  }, []);

  const handleUpdate = useCallback(async () => {
    if (!selectedTier) return;
    setEditing(true);
    try {
      const payload = {
        name: selectedTier.name,
        price_monthly: editData.price_monthly,
        max_branches: toLimitPayload(editData.max_branches),
        max_users: toLimitPayload(editData.max_users),
        max_customers: toLimitPayload(editData.max_customers),
        max_products: toLimitPayload(editData.max_products),
        features: editData.features,
      };
      const response = await fetch("/api/admin/saas-management/tiers", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });
      const data = await response.json();
      if (!response.ok)
        throw new Error(data.error || "Error al actualizar tier");
      toast.success("Tier actualizado exitosamente");
      setShowEditDialog(false);
      setSelectedTier(null);
      fetchTiers();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Error desconocido");
    } finally {
      setEditing(false);
    }
  }, [selectedTier, editData, fetchTiers]);

  return {
    tiers,
    loading,
    error,
    showEditDialog,
    selectedTier,
    editing,
    editData,
    setShowEditDialog,
    setEditData,
    handleEdit,
    handleUpdate,
  };
}

"use client";

