                  </div>
                )}
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      <TierEditDialog
        editData={editData}
        open={showEditDialog}
        saving={editing}
        tierName={
          selectedTier
            ? (TIER_DISPLAY_NAMES[
                selectedTier.name as keyof typeof TIER_DISPLAY_NAMES
              ] ?? selectedTier.name)
            : ""
        }
        onEditDataChange={(data) => setEditData((d) => ({ ...d, ...data }))}
        onOpenChange={(open) => {
          setShowEditDialog(open);
          if (!open) setSelectedTier(null);
        }}
        onSave={handleUpdate}
      />
    </div>
  );
}

