  );
}

export function UserBranchesCard({ user }: { user: UserDetails }) {
  const isSuperAdmin = user.admin_branch_access?.some(
    (a) => a.branch_id === null,
  );
  const branches =
    user.admin_branch_access
      ?.filter((a) => a.branch_id !== null)
      .map((a) => a.branches)
      .filter(Boolean) || [];
  return (
    <Card className="admin-card">
      <CardHeader>
        <CardTitle className="flex items-center gap-3">
          <MapPin className="h-5 w-5" />
          Acceso a Sucursales
        </CardTitle>
      </CardHeader>
      <CardContent>
        {isSuperAdmin ? (
          <div className="flex items-center gap-2">
            <Crown className="h-5 w-5 text-purple-600" />
            <span className="font-semibold">
              Super Admin - Acceso a todas las sucursales
            </span>
          </div>
        ) : branches.length > 0 ? (
          <div className="space-y-2">
            {branches.map((b) => (
              <div
                className="flex items-center justify-between p-3 border rounded-lg"
                key={b?.id}
              >
                <div>
                  <p className="font-semibold">{b?.name}</p>
                  <p className="text-sm text-gray-500">Código: {b?.code}</p>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className="text-gray-500">
            No tiene acceso a sucursales específicas
          </p>
        )}
      </CardContent>
    </Card>
  );
}

export function UserActivityCard({ user }: { user: UserDetails }) {
  if (!user.recentActivity || user.recentActivity.length === 0) return null;
  return (
    <Card className="admin-card">
      <CardHeader>
        <CardTitle className="flex items-center gap-3">
          <Activity className="h-5 w-5" />
          Actividad Reciente
        </CardTitle>
      </CardHeader>
      <CardContent>
        <div className="space-y-2">
          {user.recentActivity.slice(0, 10).map((a) => (
            <div
              className="flex items-center justify-between p-3 border rounded-lg"
              key={a.id}
            >
              <div>
                <p className="font-semibold">{a.action}</p>
                <p className="text-sm text-gray-500">
                  {a.resource_type} - {a.resource_id}
                </p>
              </div>
              <p className="text-sm text-gray-500">
                {formatDate(a.created_at)}
              </p>
            </div>
          ))}
        </div>
      </CardContent>
    </Card>
  );
}

export function UserSystemInfoCard({ user }: { user: UserDetails }) {
  return (
    <Card className="admin-card">
      <CardHeader>
        <CardTitle className="flex items-center gap-3">
          <Shield className="h-5 w-5" />
          Información del Sistema
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="text-sm font-medium text-gray-500">
              Fecha de creación
            </label>
            <p className="text-lg">{formatDate(user.created_at)}</p>
          </div>
          <div>
            <label className="text-sm font-medium text-gray-500">
              Última actualización
            </label>
            <p className="text-lg">{formatDate(user.updated_at)}</p>
          </div>
          <div>
            <label className="text-sm font-medium text-gray-500">
              ID del Usuario
            </label>
            <p className="text-sm font-mono text-gray-600">{user.id}</p>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import { ArrowLeft, Loader2, Trash2 } from "lucide-react";
import { useParams, useRouter } from "next/navigation";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { appLogger } from '@/lib/logger';

import { UserDeleteDialog } from "./UserDeleteDialog";
import {  UserActivityCard,
  UserBranchesCard,
  UserOrgCard,
  UserPersonalCard,
  UserSystemInfoCard,
} from "./UserDetailCards";

interface UserDetails {
  id: string;
  email: string;
  role: string;
  is_active: boolean;
  organization_id?: string;
  created_at: string;
  updated_at: string;
  last_login?: string;
  permissions?: Record<string, string[]>;
  organization?: {
    id: string;
    name: string;
    slug: string;
    subscription_tier: string;
    status: string;
  };
  profiles?: {
    id: string;
    email: string;
    first_name?: string;
    last_name?: string;
    phone?: string;
    created_at: string;
  };
  admin_branch_access?: Array<{
    id: string;
    branch_id: string | null;
    role?: string;
    is_primary?: boolean;
    branches?: {
      id: string;
      name: string;
      code: string;
      organization_id: string;
    };
  }>;
  recentActivity?: Array<{
    id: string;
    action: string;
    resource_type: string;
    resource_id: string;
    created_at: string;
  }>;
}

export default function UserDetailsPage() {
  const params = useParams();

  const router = useRouter();
  const userId = params.id as string;

  const [user, setUser] = useState<UserDetails | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [deleting, setDeleting] = useState(false);

  useEffect(() => {
    if (userId) {
      fetchUserDetails();
    }
  }, [userId]);

  const fetchUserDetails = async () => {
    try {
      setLoading(true);
      const response = await fetch(
        `/api/admin/saas-management/users/${userId}`,
      );

      if (!response.ok) {
        if (response.status === 404) {
          throw new Error("Usuario no encontrado");
        }
        throw new Error("Error al cargar detalles del usuario");
      }

      const data = await response.json();
      setUser(data.user);
      setError(null);
    } catch (err) {
      appLogger.error("Error fetching user details:", err);
      setError(err instanceof Error ? err.message : "Error desconocido");
      toast.error(
        err instanceof Error
          ? err.message
          : "Error al cargar detalles del usuario",
      );
    } finally {
      setLoading(false);
    }
  };

  const isSuperAdmin = user?.admin_branch_access?.some(
    (access) => access.branch_id === null,
  );

  const handleDeleteUser = async () => {
    if (!user) return;
    try {
      setDeleting(true);
      const response = await fetch(
        `/api/admin/saas-management/users/${user.id}`,
        {
          method: "DELETE",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ confirm: true }),
        },
      );

      const data = await response.json();

      if (!response.ok) {
        throw new Error(
          data.error || data.details || "Error al eliminar usuario",
        );
      }

      toast.success("Usuario eliminado correctamente");
      router.push("/admin/saas-management/users");
    } catch (err) {
      toast.error(
        err instanceof Error ? err.message : "Error al eliminar usuario",
      );
    } finally {
      setDeleting(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center">
          <Loader2 className="h-8 w-8 animate-spin text-blue-600 mx-auto mb-4" />
          <p className="text-muted-foreground">
            Cargando detalles del usuario...
          </p>
        </div>
      </div>
    );
  }

  if (error || !user) {
    return (
      <div className="space-y-6 p-6">
        <div className="flex items-center gap-4">
          <Button
            size="icon"
            title="Volver a usuarios"
            variant="ghost"
            onClick={() => router.push("/admin/saas-management/users")}
          >
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div>
            <h1 className="text-3xl font-display font-bold text-epoch-primary tracking-tight">
              Error
            </h1>
          </div>
        </div>
        <Card className="admin-card">
          <CardContent className="pt-6">
            <div className="text-center py-12 text-red-600">
              {error || "Usuario no encontrado"}
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  const fullName = user.profiles
    ? `${user.profiles.first_name || ""} ${user.profiles.last_name || ""}`.trim() ||
      user.email
    : user.email;

  return (
    <div className="space-y-6 p-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Button
            size="icon"
            title="Volver a usuarios"
            variant="ghost"
            onClick={() => router.push("/admin/saas-management/users")}
          >
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div>
            <h1 className="text-3xl font-display font-bold text-epoch-primary tracking-tight">
              Detalles del Usuario
            </h1>
            <p className="text-muted-foreground mt-2">
              Información completa del usuario del sistema
            </p>
          </div>
        </div>
        {user.role !== "root" && user.role !== "dev" && (
          <Button
            variant="destructive"
            onClick={() => setDeleteDialogOpen(true)}
          >
            <Trash2 className="h-4 w-4 mr-2" />
            Eliminar usuario
          </Button>
        )}
      </div>

      <UserPersonalCard user={user} />
      <UserOrgCard user={user} />
      <UserBranchesCard user={user} />
      <UserActivityCard user={user} />
      <UserSystemInfoCard user={user} />

      <UserDeleteDialog
        deleting={deleting}
        email={user.email}
        fullName={fullName}
        open={deleteDialogOpen}
        onDelete={handleDeleteUser}
        onOpenChange={setDeleteDialogOpen}
      />
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

interface ChangeOrgDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  organizations: Array<{ id: string; name: string; slug: string }>;
  user: { id: string; email: string; organization_id?: string } | null;
  onChangeOrg: (userId: string, orgId: string) => Promise<void>;
}

export function ChangeOrgDialog({
  open,
  onOpenChange,
  organizations,
  user,
  onChangeOrg,
}: ChangeOrgDialogProps) {
  const [selectedOrgId, setSelectedOrgId] = useState("");

  useEffect(() => {
    if (user) {
      setSelectedOrgId(user.organization_id || "");
    }
  }, [user]);

  const handleSave = async () => {
    if (!user || !selectedOrgId) {
      toast.error("Selecciona una organización");
      return;
    }
    await onChangeOrg(user.id, selectedOrgId);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Cambiar Organización</DialogTitle>
          <DialogDescription>
            Asigna una nueva organización al usuario {user?.email}
          </DialogDescription>
        </DialogHeader>
        <div className="space-y-4">
          <div>
            <label className="text-sm font-medium">Organización</label>
            <Select
              value={selectedOrgId ? selectedOrgId : "__none__"}
              onValueChange={(v) =>
                setSelectedOrgId(v === "__none__" ? "" : v)
              }
            >
              <SelectTrigger className="rounded-xl">
                <SelectValue placeholder="Seleccionar organización" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="__none__">Sin organización</SelectItem>
                {organizations.map((org) => (
                  <SelectItem key={org.id} value={org.id}>
                    {org.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>
        <DialogFooter>
          <Button
            variant="outline"
            onClick={() => onOpenChange(false)}
          >
            Cancelar
          </Button>
          <Button onClick={handleSave}>Guardar</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { Loader2 } from "lucide-react";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

interface CreateUserDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  organizations: Array<{ id: string; name: string; slug: string }>;
  onUserCreated: () => void;
}

const initialForm = {
  email: "",
  password: "",
  first_name: "",
  last_name: "",
  role: "admin",
  organization_id: "",
  branch_id: "",
};

export function CreateUserDialog({
  open,
  onOpenChange,
  organizations,
  onUserCreated,
}: CreateUserDialogProps) {
  const [form, setForm] = useState(initialForm);
  const [branchesForOrg, setBranchesForOrg] = useState<
    Array<{ id: string; name: string; code: string }>
  >([]);
  const [creating, setCreating] = useState(false);

  useEffect(() => {
    if (!open) {
      setForm(initialForm);
      setBranchesForOrg([]);
      setCreating(false);
    }
  }, [open]);

  const loadBranchesForOrg = async (orgId: string) => {
    if (!orgId) {
      setBranchesForOrg([]);
      return;
    }
    try {
      const res = await fetch(
        `/api/admin/saas-management/organizations/${orgId}`,
      );
      if (res.ok) {
        const data = await res.json();
        setBranchesForOrg(data.organization?.branches || []);
      } else {
        setBranchesForOrg([]);
      }
    } catch {
      setBranchesForOrg([]);
    }
  };

  const handleCreate = async () => {
    if (!form.email || !form.password) {
      toast.error("Email y contraseña son requeridos");
      return;
    }
    if (form.password.length < 8) {
      toast.error("La contraseña debe tener al menos 8 caracteres");
      return;
    }
    setCreating(true);
    try {
      const res = await fetch("/api/admin/saas-management/users", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          email: form.email,
          password: form.password,
          first_name: form.first_name || undefined,
          last_name: form.last_name || undefined,
          role: form.role,
          organization_id: form.organization_id || undefined,
          branch_id: form.branch_id || undefined,
        }),
      });
      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.error || "Error al crear usuario");
      }
      toast.success("Usuario creado correctamente");
      onOpenChange(false);
      onUserCreated();
    } catch (err) {
      toast.error(
        err instanceof Error ? err.message : "Error al crear usuario",
      );
    } finally {
      setCreating(false);
    }
  };

  return (
    <Dialog
      open={open}
      onOpenChange={(open) => {
        onOpenChange(open);
        if (!open) {
          setForm(initialForm);
          setBranchesForOrg([]);
        }
      }}
    >
      <DialogContent className="max-w-[calc(100vw-2rem)] sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Crear usuario</DialogTitle>
          <DialogDescription>
            Crea un nuevo usuario y asígnale organización y rol (solo root/dev).
          </DialogDescription>
        </DialogHeader>
        <div className="space-y-4">
          <div>
            <Label>Email *</Label>
            <Input
              placeholder="usuario@ejemplo.com"
              type="email"
              value={form.email}
              onChange={(e) =>
                setForm((f) => ({ ...f, email: e.target.value }))
              }
            />
          </div>
          <div>
            <Label>Contraseña * (mín. 8 caracteres)</Label>
            <Input
              placeholder="••••••••"
              type="password"
              value={form.password}
              onChange={(e) =>
                setForm((f) => ({ ...f, password: e.target.value }))
              }
            />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label>Nombre</Label>
              <Input
                placeholder="Nombre"
                value={form.first_name}
                onChange={(e) =>
                  setForm((f) => ({ ...f, first_name: e.target.value }))
                }
              />
            </div>
            <div>
              <Label>Apellido</Label>
              <Input
                placeholder="Apellido"
                value={form.last_name}
                onChange={(e) =>
                  setForm((f) => ({ ...f, last_name: e.target.value }))
                }
              />
            </div>
          </div>
          <div>
            <Label>Rol</Label>
            <Select
              value={form.role}
              onValueChange={(v) => setForm((f) => ({ ...f, role: v }))}
            >
              <SelectTrigger className="rounded-xl">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="root">Root</SelectItem>
                <SelectItem value="dev">Dev</SelectItem>
                <SelectItem value="super_admin">Super Admin</SelectItem>
                <SelectItem value="admin">Admin</SelectItem>
                <SelectItem value="vendedor">Vendedor</SelectItem>
                <SelectItem value="employee">Empleado</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div>
            <Label>Organización</Label>
            <Select
              value={form.organization_id ? form.organization_id : "__none__"}
              onValueChange={(v) => {
                const orgId = v === "__none__" ? "" : v;
                setForm((f) => ({
                  ...f,
                  organization_id: orgId,
                  branch_id: "",
                }));
                loadBranchesForOrg(orgId);
              }}
            >
              <SelectTrigger className="rounded-xl">
                <SelectValue placeholder="Sin organización" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="__none__">Sin organización</SelectItem>
                {organizations.map((org) => (
                  <SelectItem key={org.id} value={org.id}>
                    {org.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          {(form.role === "admin" ||
            form.role === "vendedor" ||
            form.role === "employee") &&
            branchesForOrg.length > 0 && (
              <div>
                <Label>Sucursal (opcional)</Label>
                <Select
                  value={form.branch_id}
                  onValueChange={(v) =>
                    setForm((f) => ({ ...f, branch_id: v }))
                  }
                >
                  <SelectTrigger className="rounded-xl">
                    <SelectValue placeholder="Seleccionar sucursal" />
                  </SelectTrigger>
                  <SelectContent>
                    {branchesForOrg.map((b) => (
                      <SelectItem key={b.id} value={b.id}>
                        {b.name} ({b.code})
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancelar
          </Button>
          <Button disabled={creating} onClick={handleCreate}>
            {creating ? (
              <>
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                Creando...
              </>
            ) : (
              "Crear usuario"
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { AlertTriangle, Loader2, Trash2 } from "lucide-react";
import { useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";

interface DeleteUserDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  user: { id: string; email: string; fullName?: string } | null;
  onUserDeleted: () => void;
}

export function DeleteUserDialog({
  open,
  onOpenChange,
  user,
  onUserDeleted,
}: DeleteUserDialogProps) {
  const [deleting, setDeleting] = useState(false);

  const handleDelete = async () => {
    if (!user) return;
    setDeleting(true);
    try {
      const response = await fetch(
        `/api/admin/saas-management/users/${user.id}`,
        {
          method: "DELETE",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ confirm: true }),
        },
      );

      const data = await response.json();

      if (!response.ok) {
        throw new Error(
          data.error || data.details || "Error al eliminar usuario",
        );
      }

      toast.success("Usuario eliminado correctamente");
      onOpenChange(false);
      onUserDeleted();
    } catch (err) {
      toast.error(
        err instanceof Error ? err.message : "Error al eliminar usuario",
      );
    } finally {
      setDeleting(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-[calc(100vw-2rem)] sm:max-w-lg">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <AlertTriangle className="h-5 w-5 text-red-500" />
            Confirmar Eliminación de Usuario
          </DialogTitle>
          <DialogDescription>
            <div className="space-y-4 mt-4">
              <p className="font-semibold text-lg">
                ¿Estás seguro de que deseas eliminar al usuario{" "}
                <span className="text-red-600">
                  &quot;{user?.fullName || user?.email}&quot;
                </span>{" "}
                ({user?.email})?
              </p>

              <div className="p-4 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg">
                <div className="flex items-start gap-3">
                  <AlertTriangle className="h-5 w-5 text-red-600 flex-shrink-0 mt-0.5" />
                  <div className="flex-1">
                    <p className="font-semibold text-red-800 dark:text-red-300 mb-2">
                      Esta acción es IRREVERSIBLE
                    </p>
                    <p className="text-sm text-red-700 dark:text-red-400 mb-3">
                      Se eliminará permanentemente el usuario, su perfil y
                      acceso al sistema.
                    </p>
                    <p className="text-sm text-red-700 dark:text-red-400">
                      Si el usuario tiene una organización asignada, la
                      organización permanecerá (sin owner). La organización se
                      elimina desde la sección Organizaciones.
                    </p>
                  </div>
                </div>
              </div>

              <p className="text-sm text-gray-600 dark:text-gray-400">
                Esta acción no se puede deshacer.
              </p>
            </div>
          </DialogDescription>
        </DialogHeader>
        <DialogFooter>
          <Button
            disabled={deleting}
            variant="outline"
            onClick={() => onOpenChange(false)}
          >
            Cancelar
          </Button>
          <Button
            disabled={deleting}
            variant="destructive"
            onClick={handleDelete}
          >
            {deleting ? (
              <>
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                Eliminando...
              </>
            ) : (
              <>
                <Trash2 className="h-4 w-4 mr-2" />
                Sí, Eliminar Permanentemente
              </>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { ArrowLeft, UserPlus } from "lucide-react";
import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import {
  extractDataFromResponse,
  extractPaginationFromResponse,
} from "@/lib/api/response-helpers";
import { appLogger } from '@/lib/logger';

import { ChangeOrgDialog } from "./ChangeOrgDialog";
import { CreateUserDialog } from "./CreateUserDialog";
import { DeleteUserDialog } from "./DeleteUserDialog";
import { UsersFilters } from "./UsersFilters";
import { UsersTable } from "./UsersTable";

interface User {
  id: string;
  email: string;
  role: string;
  is_active: boolean;
  organization_id?: string;
  created_at: string;
  last_login?: string;
  is_super_admin?: boolean;
  branches?: Array<{ id: string; name: string; code: string }>;
  organization?: {
    id: string;
    name: string;
    slug: string;
  };
  fullName?: string;
}

interface Organization {
  id: string;
  name: string;
  slug: string;
}

export default function UsersManagementContent() {
  const router = useRouter();
  const [users, setUsers] = useState<User[]>([]);
  const [organizations, setOrganizations] = useState<Organization[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Filters
  const [searchTerm, setSearchTerm] = useState("");
  const [organizationFilter, setOrganizationFilter] = useState("all");
  const [roleFilter, setRoleFilter] = useState("all");
  const [statusFilter, setStatusFilter] = useState("all");

  // Pagination
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [totalCount, setTotalCount] = useState(0);

  // Dialogs
  const [showChangeOrgDialog, setShowChangeOrgDialog] = useState(false);
  const [showCreateUserDialog, setShowCreateUserDialog] = useState(false);
  const [selectedUser, setSelectedUser] = useState<User | null>(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [userToDelete, setUserToDelete] = useState<User | null>(null);

  useEffect(() => {
    fetchOrganizations();
    fetchUsers();
  }, [currentPage, organizationFilter, roleFilter, statusFilter, searchTerm]);

  const fetchOrganizations = async () => {
    try {
      const response = await fetch(
        "/api/admin/saas-management/organizations?limit=1000",
      );
      if (response.ok) {
        const data = await response.json();
        setOrganizations(data.organizations || []);
      }
    } catch (err) {
      appLogger.error("Error fetching organizations:", err);
    }
  };

  const fetchUsers = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams({
        page: currentPage.toString(),
        limit: "20",
      });

      if (organizationFilter !== "all") {
        params.append("organization_id", organizationFilter);
      }
      if (roleFilter !== "all") {
        params.append("role", roleFilter);
      }
      if (statusFilter !== "all") {
        params.append("status", statusFilter);
      }
      if (searchTerm) {
        params.append("search", searchTerm);
      }

      const response = await fetch(
        `/api/admin/saas-management/users?${params}`,
      );

      if (!response.ok) {
        throw new Error("Error al cargar usuarios");
      }

      const data = await response.json();
      const pagination = extractPaginationFromResponse(data);
      setUsers(extractDataFromResponse(data));
      setTotalPages(pagination.totalPages || 1);
      setTotalCount(pagination.total || 0);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Error desconocido");
      toast.error("Error al cargar usuarios");
    } finally {
      setLoading(false);
    }
  };

  const handleAction = async (
    userId: string,
    action:
      | "activate"
      | "deactivate"
      | "change_organization"
      | "reset_password",
    value?: string,
  ) => {
    try {
      const response = await fetch(
        `/api/admin/saas-management/users/${userId}/actions`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ action, value }),
        },
      );

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || "Error al realizar acción");
      }

      toast.success("Acción realizada exitosamente");
      fetchUsers();
      setShowChangeOrgDialog(false);
      setSelectedUser(null);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Error desconocido");
    }
  };

  const handleOrgChanged = async (userId: string, orgId: string) => {
    await handleAction(userId, "change_organization", orgId);
  };

  const handleUserDeleted = () => {
    setDeleteDialogOpen(false);
    setUserToDelete(null);
    fetchUsers();
  };

  const handleUserCreated = () => {
    setShowCreateUserDialog(false);
    fetchUsers();
  };

  return (
    <div className="space-y-6 p-6">
      <div className="flex items-center gap-4">
        <Button
          className="text-white hover:bg-white/10"
          size="icon"
          title="Volver al dashboard"
          variant="ghost"
          onClick={() => router.push("/admin/saas-management/dashboard")}
        >
          <ArrowLeft className="h-5 w-5" />
        </Button>
        <div className="flex-1">
          <h1 className="text-3xl font-display font-bold text-white tracking-tight">
            Gestión de Usuarios
          </h1>
          <p className="text-white/50 mt-2">
            Administra todos los usuarios del sistema
          </p>
        </div>
        <Button
          className="bg-[#C5A059] hover:bg-[#C5A059]/90"
          onClick={() => setShowCreateUserDialog(true)}
        >
          <UserPlus className="h-4 w-4 mr-2" />
          Nuevo usuario
        </Button>
      </div>

      <UsersFilters
        organizationFilter={organizationFilter}
        organizations={organizations}
        roleFilter={roleFilter}
        searchTerm={searchTerm}
        statusFilter={statusFilter}
        onOrganizationFilterChange={setOrganizationFilter}
        onRoleFilterChange={setRoleFilter}
        onSearchChange={(value) => {
          setSearchTerm(value);
          setCurrentPage(1);
        }}
        onStatusFilterChange={setStatusFilter}
      />

      <UsersTable
        currentPage={currentPage}
        error={error}
        loading={loading}
        totalCount={totalCount}
        totalPages={totalPages}
        users={users}
        onActivate={(userId) => handleAction(userId, "activate")}
        onChangeOrgClick={(user) => {
          setSelectedUser(user);
          setShowChangeOrgDialog(true);
        }}
        onDeactivate={(userId) => handleAction(userId, "deactivate")}
        onDeleteClick={(user) => {
          setUserToDelete(user);
          setDeleteDialogOpen(true);
        }}
        onPageChange={setCurrentPage}
        onResetPassword={(userId) => handleAction(userId, "reset_password")}
        onViewUser={(userId) =>
          router.push(`/admin/saas-management/users/${userId}`)
        }
      />

      <CreateUserDialog
        open={showCreateUserDialog}
        organizations={organizations}
        onOpenChange={setShowCreateUserDialog}
        onUserCreated={handleUserCreated}
      />

      <ChangeOrgDialog
        open={showChangeOrgDialog}
        organizations={organizations}
        user={selectedUser}
        onChangeOrg={handleOrgChanged}
        onOpenChange={(open) => {
          setShowChangeOrgDialog(open);
          if (!open) setSelectedUser(null);
        }}
      />

      <DeleteUserDialog
        open={deleteDialogOpen}
        user={userToDelete}
        onOpenChange={(open) => {
          setDeleteDialogOpen(open);
          if (!open) setUserToDelete(null);
        }}
        onUserDeleted={handleUserDeleted}
      />
    </div>
  );
}

"use client";

import {
  Building2,
  CheckCircle2,
  Eye,
  Loader2,
  MapPin,
  MoreVertical,
  Trash2,
  XCircle,
} from "lucide-react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { formatDate } from "@/lib/utils";

import type { User } from "./types";
import { getActiveBadge, getRoleBadge } from "./userBadgeHelpers";

interface UsersTableProps {
  users: User[];
  loading: boolean;
  error: string | null;
  totalCount: number;
  currentPage: number;
  totalPages: number;
  onPageChange: (page: number) => void;
  onViewUser: (userId: string) => void;
  onActivate: (userId: string) => void;
  onDeactivate: (userId: string) => void;
  onChangeOrgClick: (user: User) => void;
  onResetPassword: (userId: string) => void;
  onDeleteClick: (user: User) => void;
}

export function UsersTable({
  users,
  loading,
  error,
  totalCount,
  currentPage,
  totalPages,
  onPageChange,
  onViewUser,
  onActivate,
  onDeactivate,
  onChangeOrgClick,
  onResetPassword,
  onDeleteClick,
}: UsersTableProps) {
  return (
    <Card className="admin-card">
      <CardHeader>
        <CardTitle>Usuarios ({totalCount})</CardTitle>
      </CardHeader>
      <CardContent>
        {loading ? (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="h-8 w-8 animate-spin text-blue-600" />
          </div>
        ) : error ? (
          <div className="text-center py-12 text-red-600">{error}</div>
        ) : users.length === 0 ? (
          <div className="text-center py-12 text-gray-500">
            No se encontraron usuarios
          </div>
        ) : (
          <>
            <div className="overflow-x-auto -mx-4 px-4 md:mx-0 md:px-0">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Usuario</TableHead>
                    <TableHead>Rol</TableHead>
                    <TableHead>Organización</TableHead>
                    <TableHead>Sucursales</TableHead>
                    <TableHead>Estado</TableHead>
                    <TableHead>Último acceso</TableHead>
                    <TableHead className="text-right">Acciones</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {users.map((user) => (
                    <TableRow key={user.id}>
                      <TableCell>
                        <div>
                          <div className="font-medium">
                            {user.fullName || user.email}
                          </div>
                          <div className="text-sm text-gray-500">
                            {user.email}
                          </div>
                        </div>
                      </TableCell>
                      <TableCell>{getRoleBadge(user.role)}</TableCell>
                      <TableCell>
                        {user.organization ? (
                          <div>
                            <div className="font-medium">
                              {user.organization.name}
                            </div>
                            <div className="text-xs text-gray-500">
                              {user.organization.slug}
                            </div>
                          </div>
                        ) : (
                          <span className="text-gray-400">
                            Sin organización
                          </span>
                        )}
                      </TableCell>
                      <TableCell>
                        {user.branches && user.branches.length > 0 ? (
                          <div className="flex items-center gap-1">
                            <MapPin className="h-4 w-4 text-gray-400" />
                            <span>{user.branches.length}</span>
                          </div>
                        ) : user.is_super_admin ? (
                          <Badge variant="outline">Todas</Badge>
                        ) : (
                          <span className="text-gray-400">-</span>
                        )}
                      </TableCell>
                      <TableCell>{getActiveBadge(user.is_active)}</TableCell>
                      <TableCell className="text-sm text-gray-500">
                        {user.last_login
                          ? formatDate(user.last_login)
                          : "Nunca"}
                      </TableCell>
                      <TableCell className="text-right">
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button size="sm" variant="ghost">
                              <MoreVertical className="h-4 w-4" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
                            <DropdownMenuItem
                              onClick={() => onViewUser(user.id)}
                            >
                              <Eye className="h-4 w-4 mr-2" />
                              Ver detalles
                            </DropdownMenuItem>
                            <DropdownMenuSeparator />
                            {user.is_active ? (
                              <DropdownMenuItem
                                onClick={() => onDeactivate(user.id)}
                              >
                                <XCircle className="h-4 w-4 mr-2" />
                                Desactivar
                              </DropdownMenuItem>
                            ) : (
                              <DropdownMenuItem
                                onClick={() => onActivate(user.id)}
                              >
                                <CheckCircle2 className="h-4 w-4 mr-2" />
                                Activar
                              </DropdownMenuItem>
                            )}
                            <DropdownMenuItem
                              onClick={() => onChangeOrgClick(user)}
                            >
                              <Building2 className="h-4 w-4 mr-2" />
                              Cambiar organización
                            </DropdownMenuItem>
                            <DropdownMenuItem
                              onClick={() => onResetPassword(user.id)}
                            >
                              Resetear contraseña
                            </DropdownMenuItem>
                            {user.role !== "root" && user.role !== "dev" && (
                              <>
                                <DropdownMenuSeparator />
                                <DropdownMenuItem
                                  className="text-red-600 focus:text-red-600"
                                  onClick={() => onDeleteClick(user)}
                                >
                                  <Trash2 className="h-4 w-4 mr-2" />
                                  Eliminar
                                </DropdownMenuItem>
                              </>
                            )}
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>

            {totalPages > 1 && (
              <div className="flex items-center justify-between mt-4">
                <div className="text-sm text-gray-600">
                  Página {currentPage} de {totalPages}
                </div>
                <div className="flex gap-2">
                  <Button
                    disabled={currentPage === 1}
                    size="sm"
                    variant="outline"
                    onClick={() => onPageChange(Math.max(1, currentPage - 1))}
                  >
                    Anterior
                  </Button>
                  <Button
                    disabled={currentPage === totalPages}
                    size="sm"
                    variant="outline"
                    onClick={() =>
                      onPageChange(Math.min(totalPages, currentPage + 1))
                    }
                  >
                    Siguiente
                  </Button>
                </div>
              </div>
            )}
          </>
        )}
      </CardContent>
    </Card>
  );
}

import { CheckCircle2, Crown, Shield, User, XCircle } from "lucide-react";

import { Badge } from "@/components/ui/badge";

export function getRoleBadge(role: string) {
  const colors: Record<string, string> = {
    root: "bg-red-100 text-red-800",
    dev: "bg-orange-100 text-orange-800",
    super_admin: "bg-purple-100 text-purple-800",
    admin: "bg-blue-100 text-blue-800",
    employee: "bg-gray-100 text-gray-800",
    vendedor: "bg-green-100 text-green-800",
  };

  const icons: Record<string, typeof Shield> = {
    root: Shield,
    dev: Shield,
    super_admin: Crown,
    admin: User,
    employee: User,
    vendedor: User,
  };

  const Icon = icons[role] || User;

  return (
    <Badge className={colors[role] || colors.admin}>
      <Icon className="h-3 w-3 mr-1" />
      {role === "root"
        ? "Root"
        : role === "dev"
          ? "Dev"
          : role === "super_admin"
            ? "Super Admin"
            : role === "admin"
              ? "Admin"
              : role === "vendedor"
                ? "Vendedor"
                : role === "employee"
                  ? "Empleado"
                  : role}
    </Badge>
  );
}

export function getActiveBadge(is_active: boolean) {
  return is_active ? (
    <Badge variant="default">
      <CheckCircle2 className="h-3 w-3 mr-1" />
      Activo
    </Badge>
  ) : (
    <Badge variant="secondary">
      <XCircle className="h-3 w-3 mr-1" />
      Inactivo
    </Badge>
  );
}

"use client";

import { AlertCircle, CheckCircle, Loader2, MessageCircle, Send } from "lucide-react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";

interface Organization { id: string; name: string; slug: string; }
interface WhatsAppNumber { id: string; organization_id: string; phone_number_id: string; waba_id: string; display_phone_number: string | null; organization?: { name: string; slug: string } | null; }

interface WhatsAppConnectionFormProps {
  organizations: Organization[];
  selectedOrgId: string;
  onSelectedOrgChange: (id: string) => void;
  form: { waba_id: string; phone_number_id: string; display_phone_number: string; };
  onFormChange: (data: Partial<WhatsAppConnectionFormProps["form"]>) => void;
  onSubmit: (e: React.FormEvent) => void;
  saving: boolean;
  loading: boolean;
  numbers: WhatsAppNumber[];
}

export function WhatsAppConnectionForm({
  organizations,
  selectedOrgId,
  onSelectedOrgChange,
  form,
  onFormChange,
  onSubmit,
  saving,
  loading,
  numbers,
}: WhatsAppConnectionFormProps) {
  return (
    <Card className="admin-card">
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <MessageCircle className="h-5 w-5" />
          Configuración de números
        </CardTitle>
        <p className="text-sm text-muted-foreground">
          Asocia un número de WhatsApp a cada organización. El número principal de Opttius debe ir en
          la organización &quot;Opttius Platform&quot;.
        </p>
      </CardHeader>
      <CardContent className="space-y-6">
        <form className="space-y-4" onSubmit={onSubmit}>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="org">Organización</Label>
              <Select value={selectedOrgId} onValueChange={onSelectedOrgChange}>
                <SelectTrigger id="org"><SelectValue placeholder="Selecciona organización" /></SelectTrigger>
                <SelectContent>
                  {organizations.map((org) => (
                    <SelectItem key={org.id} value={org.id}>{org.name} ({org.slug})</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label htmlFor="waba_id">WABA ID (Business Account ID)</Label>
              <Input id="waba_id" placeholder="Ej: 123456789012345" value={form.waba_id}
                onChange={(e) => onFormChange({ waba_id: e.target.value })} />
            </div>
            <div className="space-y-2">
              <Label htmlFor="phone_number_id">Phone Number ID</Label>
              <Input id="phone_number_id" placeholder="Ej: 987654321098765" value={form.phone_number_id}
                onChange={(e) => onFormChange({ phone_number_id: e.target.value })} />
            </div>
            <div className="space-y-2">
              <Label htmlFor="display_phone_number">Número mostrado (opcional)</Label>
              <Input id="display_phone_number" placeholder="+56912345678" value={form.display_phone_number}
                onChange={(e) => onFormChange({ display_phone_number: e.target.value })} />
            </div>
          </div>
          <Button disabled={saving} type="submit">
            {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : <><Send className="h-4 w-4 mr-2" /> Conectar WhatsApp</>}
          </Button>
        </form>

        {loading ? (
          <div className="flex items-center gap-2 text-muted-foreground"><Loader2 className="h-4 w-4 animate-spin" /> Cargando...</div>
