        ) : (
          <div className="flex items-center gap-2 text-muted-foreground"><AlertCircle className="h-4 w-4" /> No hay números configurados</div>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import { ChevronRight, Loader2, X } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";

interface Organization { id: string; name: string; slug: string; }
interface Conversation { id: string; title: string | null; wa_id: string | null; organization_id: string | null; message_count: number | null; last_message_preview: string | null; updated_at: string; organization?: { name: string; slug: string } | null; }
interface ChatMessage { id: string; role: string; content: string; created_at: string; }

interface WhatsAppConversationsPanelProps {
  organizations: Organization[];
  filterOrgId: string;
  onFilterChange: (id: string) => void;
  conversations: Conversation[];
  conversationsLoading: boolean;
  selectedSessionId: string | null;
  onSessionSelect: (id: string | null) => void;
  messages: ChatMessage[];
  messagesLoading: boolean;
  onRefresh: () => void;
  formatDate: (date: string) => string;
}

export function WhatsAppConversationsPanel({
  organizations,
  filterOrgId,
  onFilterChange,
  conversations,
  conversationsLoading,
  selectedSessionId,
  onSessionSelect,
  messages,
  messagesLoading,
  onRefresh,
  formatDate,
}: WhatsAppConversationsPanelProps) {
  return (
    <Card className="admin-card">
      <CardHeader>
        <CardTitle>Conversaciones WhatsApp</CardTitle>
        <p className="text-sm text-muted-foreground">Historial de mensajes recibidos por canal WhatsApp</p>
      </CardHeader>
      <CardContent>
        <div className="flex items-center gap-4 mb-4">
          <Label>Filtrar por organización</Label>
          <Select value={filterOrgId} onValueChange={onFilterChange}>
            <SelectTrigger className="w-[240px]"><SelectValue /></SelectTrigger>
            <SelectContent>
              <SelectItem value="all">Todas</SelectItem>
              {organizations.map((org) => (
                <SelectItem key={org.id} value={org.id}>{org.name}</SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Button disabled={conversationsLoading} size="sm" variant="outline" onClick={onRefresh}>
            {conversationsLoading ? <Loader2 className="h-4 w-4 animate-spin" /> : "Actualizar"}
          </Button>
        </div>

        <div className="flex gap-4 min-h-[400px]">
          <div className="flex-1 space-y-2 overflow-y-auto max-h-[500px]">
            {conversationsLoading ? (
              <div className="flex items-center justify-center py-12"><Loader2 className="h-8 w-8 animate-spin text-muted-foreground" /></div>
            ) : conversations.length === 0 ? (
              <div className="text-center py-12 text-muted-foreground">No hay conversaciones</div>
            ) : (
              conversations.map((c) => (
                <div className={`p-4 rounded-lg border cursor-pointer transition-colors ${selectedSessionId === c.id ? "bg-epoch-primary/10 border-epoch-primary" : "hover:bg-muted/50"}`}
                  key={c.id} onClick={() => onSessionSelect(c.id)}>
                  <div className="flex items-center justify-between">
                    <span className="font-medium">{c.wa_id ?? c.title ?? "Sin contacto"}</span>
                    <ChevronRight className="h-4 w-4" />
                  </div>
                  <p className="text-sm text-muted-foreground truncate mt-1">{c.organization?.name ?? "—"} • {c.message_count ?? 0} mensajes</p>
                  <p className="text-xs text-muted-foreground mt-1">{c.last_message_preview ? c.last_message_preview.length > 50 ? `${c.last_message_preview.slice(0, 50)}...` : c.last_message_preview : "—"} • {formatDate(c.updated_at)}</p>
                </div>
              ))
            )}
          </div>

          {selectedSessionId && (
            <div className="w-[400px] border rounded-lg flex flex-col">
              <div className="p-2 border-b flex items-center justify-between">
                <span className="font-medium">Mensajes</span>
                <Button size="icon" variant="ghost" onClick={() => onSessionSelect(null)}><X className="h-4 w-4" /></Button>
              </div>
              <div className="flex-1 overflow-y-auto p-4 space-y-4 max-h-[400px]">
                {messagesLoading ? (
                  <div className="flex justify-center py-8"><Loader2 className="h-6 w-6 animate-spin" /></div>
                ) : (
                  messages.map((m) => (
                    <div className={`flex ${m.role === "user" ? "justify-end" : "justify-start"}`} key={m.id}>
                      <div className={`max-w-[85%] rounded-lg px-3 py-2 ${m.role === "user" ? "bg-epoch-primary text-white" : "bg-muted"}`}>
                        <p className="text-sm whitespace-pre-wrap">{m.content}</p>
                        <p className="text-xs opacity-70 mt-1">{formatDate(m.created_at)}</p>
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>
          )}
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import { ArrowLeft } from "lucide-react";
import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";

import { WhatsAppConnectionForm } from "./_components/WhatsAppConnectionForm";
import { WhatsAppConversationsPanel } from "./_components/WhatsAppConversationsPanel";

interface Organization {
  id: string;
  name: string;
  slug: string;
}

interface WhatsAppNumber {
  id: string;
  organization_id: string;
  phone_number_id: string;
  waba_id: string;
  display_phone_number: string | null;
  organization?: { name: string; slug: string } | null;
}

interface Conversation {
  id: string;
  title: string | null;
  wa_id: string | null;
  organization_id: string | null;
  message_count: number | null;
  last_message_preview: string | null;
  updated_at: string;
  organization?: { name: string; slug: string } | null;
}

interface ChatMessage {
  id: string;
  role: string;
  content: string;
  created_at: string;
}

export default function SaasWhatsAppPage() {
  const router = useRouter();
  const [organizations, setOrganizations] = useState<Organization[]>([]);
  const [selectedOrgId, setSelectedOrgId] = useState<string>("");
  const [form, setForm] = useState({
    waba_id: "",
    phone_number_id: "",
    display_phone_number: "",
  });
  const [numbers, setNumbers] = useState<WhatsAppNumber[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [conversationsLoading, setConversationsLoading] = useState(false);
  const [filterOrgId, setFilterOrgId] = useState<string>("all");
  const [selectedSessionId, setSelectedSessionId] = useState<string | null>(
    null,
  );
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [messagesLoading, setMessagesLoading] = useState(false);

  const fetchOrganizations = async () => {
    try {
      const res = await fetch(
        "/api/admin/saas-management/organizations?limit=500",
      );
      const data = await res.json();
      if (res.ok && data.organizations) {
        setOrganizations(data.organizations);
        if (data.organizations.length > 0 && !selectedOrgId) {
          setSelectedOrgId(data.organizations[0].id);
        }
      }
    } catch {
      toast.error("Error al cargar organizaciones");
    }
  };

  const fetchStatus = async () => {
    try {
      const res = await fetch("/api/admin/saas-management/whatsapp/status");
      const data = await res.json();
      if (res.ok) {
        setNumbers(data.numbers || []);
      }
    } catch {
      toast.error("Error al cargar estado de WhatsApp");
    } finally {
      setLoading(false);
    }
  };

  const fetchConversations = async () => {
    setConversationsLoading(true);
    try {
      const params = new URLSearchParams();
      if (filterOrgId && filterOrgId !== "all") {
        params.set("organization_id", filterOrgId);
      }
      const res = await fetch(
        `/api/admin/saas-management/whatsapp/conversations?${params}`,
      );
      const data = await res.json();
      if (res.ok) {
        setConversations(data.sessions || []);
      }
    } catch {
      toast.error("Error al cargar conversaciones");
    } finally {
      setConversationsLoading(false);
    }
  };

  const fetchMessages = async (sessionId: string) => {
    setMessagesLoading(true);
    try {
      const res = await fetch(
        `/api/admin/saas-management/whatsapp/conversations/${sessionId}/messages`,
      );
      const data = await res.json();
      if (res.ok) {
        setMessages(data.messages || []);
      }
    } catch {
      toast.error("Error al cargar mensajes");
    } finally {
      setMessagesLoading(false);
    }
  };

  useEffect(() => {
    fetchOrganizations();
    fetchStatus();
  }, []);

  useEffect(() => {
    fetchConversations();
  }, [filterOrgId]);

  useEffect(() => {
    if (selectedSessionId) {
      fetchMessages(selectedSessionId);
    } else {
      setMessages([]);
    }
  }, [selectedSessionId]);

  const handleConnect = async (e: React.FormEvent) => {
    e.preventDefault();
    if (
      !selectedOrgId ||
      !form.waba_id.trim() ||
      !form.phone_number_id.trim()
    ) {
      toast.error(
        "Selecciona organización e ingresa WABA ID y Phone Number ID",
      );
      return;
    }
    setSaving(true);
    try {
      const res = await fetch("/api/admin/saas-management/whatsapp/connect", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          organization_id: selectedOrgId,
          waba_id: form.waba_id.trim(),
          phone_number_id: form.phone_number_id.trim(),
          display_phone_number: form.display_phone_number.trim() || null,
        }),
      });
      const data = await res.json();
      if (!res.ok) {
        toast.error(data.error || "Error al conectar");
        return;
      }
      toast.success(data.message);
      setForm({ waba_id: "", phone_number_id: "", display_phone_number: "" });
      fetchStatus();
    } catch {
      toast.error("Error al conectar WhatsApp");
    } finally {
      setSaving(false);
    }
  };

  const formatDate = (dateStr: string) => {
    const d = new Date(dateStr);
    return d.toLocaleDateString("es-CL", {
      day: "2-digit",
      month: "short",
      hour: "2-digit",
      minute: "2-digit",
    });
  };

  return (
    <div className="space-y-6 p-6">
      <div className="flex items-center gap-4">
        <Button
          className="rounded-xl text-epoch-primary hover:bg-epoch-primary/10"
          size="icon"
          title="Volver al dashboard"
          variant="ghost"
          onClick={() => router.push("/admin/saas-management/dashboard")}
        >
          <ArrowLeft className="h-5 w-5" />
        </Button>
        <div>
          <h1 className="text-3xl font-display font-bold text-epoch-primary tracking-tight">
            WhatsApp Business
          </h1>
          <p className="text-muted-foreground mt-2">
            Configurar números y ver conversaciones del canal WhatsApp
          </p>
        </div>
      </div>

      <WhatsAppConnectionForm
        form={form}
        loading={loading}
        numbers={numbers}
        organizations={organizations}
        saving={saving}
        selectedOrgId={selectedOrgId}
        onFormChange={(data) => setForm((f) => ({ ...f, ...data }))}
        onSelectedOrgChange={setSelectedOrgId}
        onSubmit={handleConnect}
      />

      <WhatsAppConversationsPanel
        conversations={conversations}
        conversationsLoading={conversationsLoading}
        filterOrgId={filterOrgId}
        formatDate={formatDate}
        messages={messages}
        messagesLoading={messagesLoading}
        organizations={organizations}
        selectedSessionId={selectedSessionId}
        onFilterChange={setFilterOrgId}
        onRefresh={fetchConversations}
        onSessionSelect={setSelectedSessionId}
      />
    </div>
  );
}

"use client";

import { AlertCircle, CreditCard, MessageCircle } from "lucide-react";
import Link from "next/link";
import { useEffect, useState } from "react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";

const PAYFLOW_ENABLED = process.env.NEXT_PUBLIC_PAYFLOW_ENABLED !== "false";

type Reason = "trial_expired" | "subscription_expired" | null;

export default function SubscriptionRequiredPage() {
  const [reason, setReason] = useState<Reason>(null);

  useEffect(() => {
    fetch("/api/admin/subscription-status", { credentials: "include" })
      .then((res) => res.json())
      .then((data) => {
        if (data.isTrialExpired) {
          setReason("trial_expired");
        } else if (data.isExpired && data.status !== "none") {
          setReason("subscription_expired");
        } else {
          setReason("trial_expired");
        }
      })
      .catch(() => setReason("trial_expired"));
  }, []);

  const isTrialExpired = reason === "trial_expired";
  const title = isTrialExpired
    ? "Período de prueba finalizado"
    : "Suscripción vencida";
  const description = isTrialExpired
    ? "Tu período de prueba gratuita ha terminado. Para continuar utilizando todas las funcionalidades de Opttius, necesitas una suscripción activa."
    : "Tu suscripción ha vencido o hay un problema con el pago. Renueva o actualiza tu método de pago para seguir usando Opttius.";

  return (
    <div className="min-h-[60vh] flex items-center justify-center p-6">
      <Card className="max-w-lg w-full border-2 border-amber-200 bg-amber-50/30 dark:bg-amber-950/20 dark:border-amber-800/50">
        <CardHeader>
          <div className="flex items-center gap-3">
            <div className="h-12 w-12 rounded-full bg-amber-500/20 flex items-center justify-center">
              <AlertCircle className="h-6 w-6 text-amber-600 dark:text-amber-400" />
            </div>
            <div>
              <CardTitle className="text-xl">
                {reason ? title : "Suscripción requerida"}
              </CardTitle>
              <p className="text-sm text-muted-foreground mt-1">
                Suscríbete para seguir usando Opttius
              </p>
            </div>
          </div>
        </CardHeader>
        <CardContent className="space-y-6">
          <p className="text-sm text-muted-foreground">
            {reason ? description : "Cargando..."}
          </p>

          <div className="flex flex-col gap-3">
            {PAYFLOW_ENABLED ? (
              <Link className="w-full" href="/checkout">
                <Button className="w-full h-12 font-bold" size="lg">
                  <CreditCard className="h-5 w-5 mr-2" />
                  Suscribirme ahora
                </Button>
              </Link>
            ) : null}

            <Link
              className={PAYFLOW_ENABLED ? "w-full" : ""}
              href="/admin/help"
            >
              <Button
                className="w-full h-12"
                size="lg"
                variant={PAYFLOW_ENABLED ? "outline" : "default"}
              >
                <MessageCircle className="h-5 w-5 mr-2" />
                Contactar soporte
              </Button>
            </Link>
          </div>

          {!PAYFLOW_ENABLED && (
            <p className="text-xs text-muted-foreground text-center">
              El pago en línea no está disponible. Contacta a soporte para
              realizar tu suscripción.
            </p>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { zodResolver } from "@hookform/resolvers/zod";
import { Loader2, Send } from "lucide-react";
import { useEffect, useState } from "react";
import { useForm } from "react-hook-form";
import type { z } from "zod";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { createOpticalInternalSupportTicketSchema } from "@/lib/api/validation/zod-schemas";

import { CustomerSearchField } from "./CustomerSearchField";
import { categoryLabels, priorityLabels } from "./supportConstants";

type TicketForm = z.infer<typeof createOpticalInternalSupportTicketSchema>;

interface CreateTicketDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  currentBranchId: string | null;
  isGlobalView: boolean;
  isSuperAdmin: boolean;
  onSubmit: (data: TicketForm) => Promise<void>;
}

export function CreateTicketDialog({
  open,
  onOpenChange,
  currentBranchId,
  isGlobalView,
  isSuperAdmin,
  onSubmit,
}: CreateTicketDialogProps) {
  const [creatingTicket, setCreatingTicket] = useState(false);
  const [selectedCustomer, setSelectedCustomer] = useState<{
    id: string;
    first_name?: string;
    last_name?: string;
    email: string;
  } | null>(null);

  const {
    register,
    handleSubmit,
    formState: { errors },
    reset,
    watch,
    setValue,
  } = useForm<TicketForm>({
    resolver: zodResolver(createOpticalInternalSupportTicketSchema) as unknown,
    defaultValues: {
      priority: "medium",
      category: "other",
      branch_id: currentBranchId || undefined,
    },
  });

  useEffect(() => {
    if (!open) {
      setSelectedCustomer(null);
    } else if (currentBranchId && !isGlobalView) {
      setValue("branch_id", currentBranchId);
    }
  }, [open, currentBranchId, isGlobalView, setValue]);

  const handleCustomerChange = (
    customer: {
      id: string;
      first_name?: string;
      last_name?: string;
      email: string;
    } | null,
  ) => {
    setSelectedCustomer(customer);
    setValue("customer_id", customer?.id || undefined);
    setValue(
      "customer_name",
      customer
        ? [customer.first_name, customer.last_name].filter(Boolean).join(" ") ||
            undefined
        : undefined,
    );
    setValue("customer_email", customer?.email || undefined);
  };

  const handleFormSubmit = handleSubmit(async (data) => {
    setCreatingTicket(true);
    try {
      const branchId =
        isSuperAdmin && isGlobalView
          ? data.branch_id
          : currentBranchId || data.branch_id;
      await onSubmit({
        ...data,
        branch_id: branchId || undefined,
      } as TicketForm);
      reset();
    } finally {
      setCreatingTicket(false);
    }
  });

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-[calc(100vw-2rem)] sm:max-w-3xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Registrar Incidente</DialogTitle>
          <DialogDescription>
            Registra un incidente o problema relacionado con un cliente (lente,
            entrega, pago, etc.) para análisis y mejora del servicio
          </DialogDescription>
        </DialogHeader>
        <form className="space-y-4" onSubmit={handleFormSubmit}>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="category">
                Categoría <span className="text-red-500">*</span>
              </Label>
              <Select
                value={watch("category")}
                onValueChange={(v) =>
                  setValue("category", v as TicketForm["category"])
                }
              >
                <SelectTrigger
                  className={`rounded-xl focus:border-epoch-primary focus:ring-epoch-primary/20 ${errors.category ? "border-red-500" : ""}`}
                  id="category"
                >
                  <SelectValue placeholder="Selecciona una categoría" />
                </SelectTrigger>
                <SelectContent>
                  {Object.entries(categoryLabels).map(([value, label]) => (
                    <SelectItem key={value} value={value}>
                      {label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              {errors.category && (
                <p className="text-sm text-red-500">
                  {String(errors.category.message)}
                </p>
              )}
            </div>
            <div className="space-y-2">
              <Label htmlFor="priority">
                Prioridad <span className="text-red-500">*</span>
              </Label>
              <Select
                value={watch("priority")}
                onValueChange={(v) =>
                  setValue("priority", v as TicketForm["priority"])
                }
              >
                <SelectTrigger
                  className={`rounded-xl focus:border-epoch-primary focus:ring-epoch-primary/20 ${errors.priority ? "border-red-500" : ""}`}
                  id="priority"
                >
                  <SelectValue placeholder="Selecciona una prioridad" />
                </SelectTrigger>
                <SelectContent>
                  {Object.entries(priorityLabels).map(([value, label]) => (
                    <SelectItem key={value} value={value}>
                      {label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              {errors.priority && (
                <p className="text-sm text-red-500">
                  {String(errors.priority.message)}
                </p>
              )}
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="customer_search">Cliente (opcional)</Label>
            <CustomerSearchField
              currentBranchId={currentBranchId}
              value={selectedCustomer}
              onChange={handleCustomerChange}
            />
            <p className="text-xs text-gray-500">
              Busca por nombre, RUT o email. Si el problema está relacionado con
              un cliente específico.
            </p>
          </div>

          <div className="space-y-2">
            <Label htmlFor="subject">
              Asunto <span className="text-red-500">*</span>
            </Label>
            <Input
              id="subject"
              {...register("subject")}
              className={`rounded-xl focus:border-epoch-primary focus:ring-epoch-primary/20 ${errors.subject ? "border-red-500" : ""}`}
              placeholder="Resumen breve del problema"
            />
            {errors.subject && (
              <p className="text-sm text-red-500">
                {String(errors.subject.message)}
              </p>
            )}
          </div>

          <div className="space-y-2">
            <Label htmlFor="description">
              Descripción <span className="text-red-500">*</span>
            </Label>
            <Textarea
              id="description"
              {...register("description")}
              className={`rounded-xl focus:border-epoch-primary focus:ring-epoch-primary/20 ${errors.description ? "border-red-500" : ""}`}
              placeholder="Describe el problema en detalle..."
              rows={6}
            />
            {errors.description && (
              <p className="text-sm text-red-500">
                {String(errors.description.message)}
              </p>
            )}
            <p className="text-xs text-gray-500">
              Mínimo 10 caracteres. Describe el problema y cómo se resolvió o se
              está resolviendo.
            </p>
          </div>

          <DialogFooter>
            <Button
              className="rounded-xl border-admin-border-primary/20"
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
            >
              Cancelar
            </Button>
            <Button
              className="rounded-xl bg-epoch-primary hover:bg-epoch-surface text-white font-display font-bold text-[10px] tracking-[0.2em] uppercase"
              disabled={creatingTicket}
              type="submit"
            >
              {creatingTicket ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" /> Creando...
                </>
              ) : (
                <>
                  <Send className="mr-2 h-4 w-4" /> Crear Ticket
                </>
              )}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { Loader2, Search, X } from "lucide-react";
import { useCallback, useEffect, useState } from "react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { getBranchHeader } from "@/lib/utils/branch";

interface CustomerResult {
  id: string;
  first_name?: string;
  last_name?: string;
  email: string;
  rut?: string;
}

interface SelectedCustomer {
  id: string;
  first_name?: string;
  last_name?: string;
  email: string;
}

interface CustomerSearchFieldProps {
  currentBranchId: string | null;
  value: SelectedCustomer | null;
  onChange: (customer: SelectedCustomer | null) => void;
}

export function CustomerSearchField({
  currentBranchId,
  value,
  onChange,
}: CustomerSearchFieldProps) {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState<CustomerResult[]>([]);
  const [loading, setLoading] = useState(false);

  const searchCustomers = useCallback(
    async (q: string) => {
      if (q.length < 2) {
        setResults([]);
        return;
      }
      try {
        setLoading(true);
        const params = new URLSearchParams({ q });
        if (currentBranchId) params.set("branch_id", currentBranchId);
        const headers = getBranchHeader(currentBranchId || null);
        const response = await fetch(`/api/admin/customers/search?${params}`, {
          headers,
        });
        if (response.ok) {
          const res = await response.json();
          const list =
            res?.data ?? res?.customers ?? (Array.isArray(res) ? res : []);
          setResults(Array.isArray(list) ? list.slice(0, 15) : []);
        } else {
          setResults([]);
        }
      } catch {
        setResults([]);
      } finally {
        setLoading(false);
      }
    },
    [currentBranchId],
  );

  useEffect(() => {
    const t = setTimeout(() => searchCustomers(query), 300);
    return () => clearTimeout(t);
  }, [query, searchCustomers]);

  if (value) {
    return (
      <div className="flex items-center justify-between p-3 border rounded-xl bg-epoch-background">
        <div>
          <div className="font-medium">
            {value.first_name} {value.last_name}
          </div>
          <div className="text-sm text-gray-600">{value.email}</div>
        </div>
        <Button
          className="rounded-xl border-admin-border-primary/20"
          size="sm"
          type="button"
          variant="outline"
          onClick={() => onChange(null)}
        >
          <X className="h-4 w-4 mr-1" />
          Cambiar
        </Button>
      </div>
    );
  }

  return (
    <div className="relative">
      <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
      <Input
        className="pl-10 rounded-xl focus:border-epoch-primary focus:ring-epoch-primary/20"
        placeholder="Buscar por nombre, RUT o email..."
        value={query}
        onChange={(e) => setQuery(e.target.value)}
      />
      {query.length >= 2 && (
        <div className="absolute z-50 w-full mt-1 bg-white border rounded-lg shadow-lg max-h-60 overflow-y-auto">
          {loading ? (
            <div className="p-4 text-center">
              <Loader2 className="h-4 w-4 animate-spin mx-auto" />
            </div>
          ) : results.length > 0 ? (
            results.map((c) => (
              <button
                className="w-full text-left p-3 hover:bg-gray-100 border-b last:border-b-0"
                key={c.id}
                type="button"
                onClick={() => {
                  onChange({
                    id: c.id,
                    first_name: c.first_name,
                    last_name: c.last_name,
                    email: c.email,
                  });
                  setQuery("");
                  setResults([]);
                }}
              >
                <div className="font-medium">
                  {c.first_name} {c.last_name}
                </div>
                <div className="text-sm text-gray-600">
                  {c.email}
                  {c.rut ? ` • RUT: ${c.rut}` : ""}
                </div>
              </button>
            ))
          ) : (
            <div className="p-4 text-center text-gray-500 text-sm">
              No se encontraron clientes
            </div>
          )}
        </div>
      )}
    </div>
  );
}

"use client";

import { Plus } from "lucide-react";
import { useRouter } from "next/navigation";
import { useCallback, useEffect, useState } from "react";
import { toast } from "sonner";
import type { z } from "zod";

import { Button } from "@/components/ui/button";
import { useBranch } from "@/hooks/useBranch";
import {
  extractDataFromResponse,
  extractPaginationFromResponse,
} from "@/lib/api/response-helpers";
import type { createOpticalInternalSupportTicketSchema } from "@/lib/api/validation/zod-schemas";
import { appLogger } from '@/lib/logger';
import { getBranchHeader } from "@/lib/utils/branch";

import { CreateTicketDialog } from "./CreateTicketDialog";
import type { FiltersState, PaginationState, Ticket } from "./supportConstants";
import { TicketFilters } from "./TicketFilters";
import { TicketList } from "./TicketList";
import { TicketStats } from "./TicketStats";

type TicketForm = z.infer<typeof createOpticalInternalSupportTicketSchema>;

export default function OpticalInternalSupportContent() {
  const router = useRouter();
  const { currentBranchId, isGlobalView, isSuperAdmin, branches } = useBranch();
  const [tickets, setTickets] = useState<Ticket[]>([]);
  const [loadingTickets, setLoadingTickets] = useState(true);
  const [showCreateDialog, setShowCreateDialog] = useState(false);
  const [customers, setCustomers] = useState<
    Array<{ id: string; first_name: string; last_name: string; email: string }>
  >([]);
  const [loadingCustomers, setLoadingCustomers] = useState(false);
  const [filters, setFilters] = useState<FiltersState>({
    status: "all",
    priority: "all",
    category: "all",
    branch_id: "all",
    customer_id: "all",
    search: "",
  });
  const [pagination, setPagination] = useState<PaginationState>({
    page: 1,
    limit: 20,
    total: 0,
    totalPages: 0,
  });

  useEffect(() => {
    loadCustomers();
  }, []);

  useEffect(() => {
    loadTickets();
  }, [filters, pagination.page, currentBranchId]);

  const handleFiltersChange = useCallback(
    (updates: Partial<FiltersState>) => {
      setFilters((prev) => ({ ...prev, ...updates }));
      setPagination((prev) => ({ ...prev, page: 1 }));
    },
    [],
  );

  const loadCustomers = async () => {
    setLoadingCustomers(true);
    try {
      const response = await fetch("/api/admin/customers?limit=100");
      if (response.ok) {
        const data = await response.json();
        setCustomers(
          extractDataFromResponse<{
            id: string;
            first_name: string;
            last_name: string;
            email: string;
          }>(data),
        );
      }
    } catch (err) {
      appLogger.error("Error loading customers:", err);
    } finally {
      setLoadingCustomers(false);
    }
  };

  const loadTickets = useCallback(async () => {
    setLoadingTickets(true);
    try {
      const params = new URLSearchParams({
        page: pagination.page.toString(),
        limit: pagination.limit.toString(),
      });

      if (filters.status && filters.status !== "all")
        params.append("status", filters.status);
      if (filters.priority && filters.priority !== "all")
        params.append("priority", filters.priority);
      if (filters.category && filters.category !== "all")
        params.append("category", filters.category);
      if (filters.customer_id && filters.customer_id !== "all")
        params.append("customer_id", filters.customer_id);
      if (filters.search) params.append("search", filters.search);

      if (!isSuperAdmin && currentBranchId) {
        params.append("branch_id", currentBranchId);
      } else if (isSuperAdmin && !isGlobalView && currentBranchId) {
        params.append("branch_id", currentBranchId);
      } else if (
        isSuperAdmin &&
        isGlobalView &&
        filters.branch_id &&
        filters.branch_id !== "all"
      ) {
        params.append("branch_id", filters.branch_id);
      }

      const headers = getBranchHeader(
        isSuperAdmin && isGlobalView ? null : currentBranchId,
      );
      const response = await fetch(
        `/api/admin/optical-support/tickets?${params.toString()}`,
        { headers },
      );

      if (!response.ok) {
        throw new Error("Error al cargar tickets");
      }

      const data = await response.json();
      const tickets = extractDataFromResponse<Ticket>(data);
      const paginationData = extractPaginationFromResponse(data);
      setTickets(tickets);
      setPagination((prev) => ({
        ...prev,
        total: paginationData.total || 0,
        totalPages: paginationData.totalPages || 0,
      }));
    } catch {
      toast.error("Error al cargar tickets");
    } finally {
      setLoadingTickets(false);
    }
  }, [filters, pagination.page, currentBranchId, isSuperAdmin, isGlobalView]);

  const handleCreateTicket = useCallback(
    async (data: TicketForm) => {
      const branchId =
        isSuperAdmin && isGlobalView
          ? data.branch_id
          : currentBranchId || data.branch_id;
      const payload = { ...data, branch_id: branchId || undefined };

      const headers: Record<string, string> = {
        "Content-Type": "application/json",
        ...getBranchHeader(
          isSuperAdmin && isGlobalView ? null : currentBranchId,
        ),
      };
      const response = await fetch("/api/admin/optical-support/tickets", {
        method: "POST",
        headers,
        body: JSON.stringify(payload),
      });

      if (!response.ok) {
        const result = await response.json();
        throw new Error(result.error || "Error al crear ticket");
      }

      const result = await response.json();
      toast.success("Ticket creado exitosamente");
      setShowCreateDialog(false);
      loadTickets();
      if (result.ticket?.id) {
        router.push(`/admin/support/tickets/${result.ticket.id}`);
      }
    },
    [isSuperAdmin, isGlobalView, currentBranchId, loadTickets, router],
  );

  const openTicketsCount = tickets.filter(
    (t) => t.status !== "resolved" && t.status !== "closed",
  ).length;
  const inProgressCount = tickets.filter(
    (t) => t.status === "in_progress",
  ).length;
  const resolvedCount = tickets.filter(
    (t) => t.status === "resolved" || t.status === "closed",
  ).length;

  return (
    <div className="space-y-4 sm:space-y-6 p-4 sm:p-6 bg-epoch-background min-h-screen">
      {/* Header */}
      <div className="flex flex-col gap-4 sm:gap-6">
        <h1 className="text-xl sm:text-2xl md:text-3xl font-display font-bold text-epoch-primary tracking-tight">
          Registro de Incidentes
        </h1>
        <p className="text-sm sm:text-base text-epoch-primary/80 max-w-2xl">
          Registra incidentes y problemas con clientes para análisis y mejora
          del servicio (lentes, entregas, pagos, etc.)
        </p>
        <div className="flex justify-start sm:justify-end">
          <Button
            className="rounded-xl bg-epoch-primary hover:bg-epoch-surface text-white font-display font-bold text-[10px] tracking-[0.2em] uppercase min-h-[44px] px-6 w-full sm:w-auto"
            onClick={() => setShowCreateDialog(true)}
          >
            <Plus className="h-4 w-4 mr-2 shrink-0" />
            Crear Ticket
          </Button>
        </div>
      </div>

      <TicketStats
        inProgressCount={inProgressCount}
        openTicketsCount={openTicketsCount}
        resolvedCount={resolvedCount}
        total={pagination.total}
      />

      <TicketFilters
        branches={branches}
        customers={customers}
        filters={filters}
        isGlobalView={isGlobalView}
        isSuperAdmin={isSuperAdmin}
        onFiltersChange={handleFiltersChange}
        onRefresh={loadTickets}
      />

      <TicketList
        filters={filters}
        loading={loadingTickets}
        pagination={pagination}
        tickets={tickets}
        onPageChange={(page) =>
          setPagination((prev) => ({ ...prev, page }))
        }
        onShowCreateDialog={() => setShowCreateDialog(true)}
      />

      <CreateTicketDialog
        currentBranchId={currentBranchId}
        isGlobalView={isGlobalView}
        isSuperAdmin={isSuperAdmin}
        open={showCreateDialog}
        onOpenChange={setShowCreateDialog}
        onSubmit={handleCreateTicket}
      />
    </div>
  );
}

