"use client";

import { zodResolver } from "@hookform/resolvers/zod";
import {
  CheckCircle2,
  Loader2,
  MessageSquare,
  Send,
  User,
} from "lucide-react";
import { useParams } from "next/navigation";
import { useState } from "react";
import { SubmitHandler, useForm } from "react-hook-form";
import { toast } from "sonner";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { createOpticalInternalSupportMessageSchema } from "@/lib/api/validation/zod-schemas";

interface TicketMessage {
  id: string;
  message: string;
  sender_name: string;
  sender_email: string;
  sender_role: string | null;
  is_internal: boolean;
  created_at: string;
  message_type: string;
  sender?: {
    id: string;
    email: string;
    role: string;
  } | null;
}

interface TicketMessagesProps {
  messages: TicketMessage[];
  ticketStatus: string;
  onMessageSent: () => void;
}

export default function TicketMessages({
  messages,
  ticketStatus,
  onMessageSent,
}: TicketMessagesProps) {
  const params = useParams();
  const ticketId = params.id as string;
  const [sendingMessage, setSendingMessage] = useState(false);

  const {
    register: registerMessage,
    handleSubmit: handleSubmitMessage,
    formState: { errors: messageErrors },
    reset: resetMessage,
  } = useForm<unknown>({
    resolver: zodResolver(createOpticalInternalSupportMessageSchema),
    defaultValues: {
      is_internal: true,
      message_type: "message",
      attachments: [],
    },
  });

  const onSubmitMessage: SubmitHandler<unknown> = async (data) => {
    setSendingMessage(true);
    try {
      const response = await fetch(
        `/api/admin/optical-support/tickets/${ticketId}/messages`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(data),
        },
      );

      if (!response.ok) {
        const result = await response.json();
        throw new Error(result.error || "Error al enviar mensaje");
      }

      toast.success("Mensaje enviado exitosamente");
      resetMessage();
      onMessageSent();
    } catch (err) {
      toast.error(
        err instanceof Error ? err.message : "Error al enviar mensaje",
      );
    } finally {
      setSendingMessage(false);
    }
  };

  const isClosed = ticketStatus === "resolved" || ticketStatus === "closed";

  return (
    <>
      <Card className="rounded-xl border border-border">
        <CardHeader className="p-4 sm:p-6 pb-0">
          <CardTitle className="flex items-center gap-2 font-display text-epoch-primary text-base sm:text-lg">
            <MessageSquare className="h-4 w-4 sm:h-5 sm:w-5 text-epoch-accent shrink-0" />
            Conversación ({messages.length})
          </CardTitle>
        </CardHeader>
        <CardContent className="p-4 sm:p-6 pt-4">
          {messages.length === 0 ? (
            <div className="text-center py-6 sm:py-8 text-epoch-primary/70">
              <MessageSquare className="h-10 w-10 sm:h-12 sm:w-12 mx-auto mb-3 sm:mb-4 text-gray-400" />
              <p className="text-sm sm:text-base">No hay mensajes aún</p>
            </div>
          ) : (
            <div className="space-y-3 sm:space-y-4">
              {messages.map((msg) => (
                <div
                  className="p-3 sm:p-4 rounded-xl border bg-white border-epoch-primary/20 text-epoch-primary"
                  key={msg.id}
                >
                  <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-1 sm:gap-2 mb-2">
                    <div className="flex flex-wrap items-center gap-1.5 sm:gap-2">
                      <User className="h-3.5 w-3.5 sm:h-4 sm:w-4 text-epoch-primary/70 shrink-0" />
                      <span className="font-medium text-xs sm:text-sm text-epoch-primary">
                        {msg.sender_name}
                      </span>
                      {msg.message_type === "status_change" && (
                        <Badge
                          className="text-[10px] sm:text-xs px-1.5 py-0"
                          variant="outline"
                        >
                          Cambio de Estado
                        </Badge>
                      )}
                      {msg.message_type === "assignment" && (
                        <Badge
                          className="text-[10px] sm:text-xs px-1.5 py-0"
                          variant="outline"
                        >
                          Asignación
                        </Badge>
                      )}
                      {msg.message_type === "resolution" && (
                        <Badge
                          className="text-[10px] sm:text-xs px-1.5 py-0"
                          variant="outline"
                        >
                          Resolución
                        </Badge>
                      )}
                    </div>
                    <span className="text-[10px] sm:text-xs text-epoch-primary/70 shrink-0">
                      {new Date(msg.created_at).toLocaleString("es-CL")}
                    </span>
                  </div>
                  <p className="text-epoch-primary whitespace-pre-wrap text-xs sm:text-sm">
                    {msg.message}
                  </p>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      {!isClosed && (
        <Card className="rounded-xl border border-border">
          <CardHeader className="p-4 sm:p-6 pb-0">
            <CardTitle className="font-display text-epoch-primary text-base sm:text-lg">
              Agregar Mensaje
            </CardTitle>
            <CardDescription className="text-xs sm:text-sm">
              Agrega información adicional o notas sobre la resolución del
              problema
            </CardDescription>
          </CardHeader>
          <CardContent className="p-4 sm:p-6 pt-4">
            <form
              className="space-y-4"
              onSubmit={handleSubmitMessage(onSubmitMessage)}
            >
              <div className="space-y-2">
                <Label className="text-xs sm:text-sm" htmlFor="message">
                  Mensaje <span className="text-red-500">*</span>
                </Label>
                <Textarea
                  id="message"
                  {...registerMessage("message")}
                  className={`rounded-xl focus:border-epoch-primary focus:ring-epoch-primary/20 bg-white text-epoch-primary placeholder:text-epoch-primary/50 text-sm sm:text-base min-h-[120px] ${messageErrors.message ? "border-red-500" : ""}`}
                  placeholder="Escribe tu mensaje aquí..."
                  rows={5}
                />
                {messageErrors.message && (
                  <p className="text-xs sm:text-sm text-red-500">
                    {String(messageErrors.message.message)}
                  </p>
                )}
              </div>

              <Button
                className="w-full rounded-xl bg-epoch-primary hover:bg-epoch-surface text-white font-display font-bold text-[10px] tracking-[0.2em] uppercase min-h-[44px]"
                disabled={sendingMessage}
                type="submit"
              >
                {sendingMessage ? (
                  <>
                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                    Enviando...
                  </>
                ) : (
                  <>
                    <Send className="mr-2 h-4 w-4" />
                    Enviar Mensaje
                  </>
                )}
              </Button>
            </form>
          </CardContent>
        </Card>
      )}

      {isClosed && (
        <Alert className="py-3 sm:py-4">
          <CheckCircle2 className="h-4 w-4 shrink-0" />
          <AlertDescription className="text-xs sm:text-sm">
            Este ticket está{" "}
            {ticketStatus === "resolved" ? "resuelto" : "cerrado"}. Si
            necesitas agregar más información, puedes crear un nuevo
            ticket.
          </AlertDescription>
        </Alert>
      )}
    </>
  );
}

"use client";

import { zodResolver } from "@hookform/resolvers/zod";
import { CheckCircle2, Loader2 } from "lucide-react";
import { useParams } from "next/navigation";
import { useEffect, useState } from "react";
import { SubmitHandler, useForm } from "react-hook-form";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { updateOpticalInternalSupportTicketSchema } from "@/lib/api/validation/zod-schemas";

interface TicketAdminUser {
  id: string;
  email: string;
  role: string;
}

interface TicketStatusData {
  id: string;
  status: string;
  priority: string;
  assigned_to: string | null;
  resolution: string | null;
  resolution_notes: string | null;
}

interface TicketStatusActionsProps {
  ticket: TicketStatusData;
  adminUsers: TicketAdminUser[];
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onTicketUpdated: () => void;
}

const statusLabels: Record<string, string> = {
  open: "Abierto",
  assigned: "Asignado",
  in_progress: "En Progreso",
  waiting_customer: "Esperando Cliente",
  resolved: "Resuelto",
  closed: "Cerrado",
};

const priorityLabels: Record<string, string> = {
  low: "Baja",
  medium: "Media",
  high: "Alta",
  urgent: "Urgente",
};

export default function TicketStatusActions({
  ticket,
  adminUsers,
  open,
  onOpenChange,
  onTicketUpdated,
}: TicketStatusActionsProps) {
  const params = useParams();
  const ticketId = params.id as string;
  const [updatingTicket, setUpdatingTicket] = useState(false);

  const {
    register: registerUpdate,
    handleSubmit: handleSubmitUpdate,
    reset: resetUpdate,
    watch: watchUpdate,
    setValue: setUpdateValue,
  } = useForm<unknown>({
    resolver: zodResolver(updateOpticalInternalSupportTicketSchema),
  });

  useEffect(() => {
    if (open) {
      setUpdateValue("status", ticket.status as unknown);
      setUpdateValue("priority", ticket.priority as unknown);
      setUpdateValue("assigned_to", ticket.assigned_to || undefined);
      setUpdateValue("resolution", ticket.resolution || undefined);
      setUpdateValue("resolution_notes", ticket.resolution_notes || undefined);
    }
  }, [open, ticket, setUpdateValue]);

  const onSubmitUpdate: SubmitHandler<unknown> = async (data) => {
    setUpdatingTicket(true);
    try {
      const response = await fetch(
        `/api/admin/optical-support/tickets/${ticketId}`,
        {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(data),
        },
      );

      if (!response.ok) {
        const result = await response.json();
        throw new Error(result.error || "Error al actualizar ticket");
      }

      toast.success("Ticket actualizado exitosamente");
      onOpenChange(false);
      resetUpdate();
      onTicketUpdated();
    } catch (err) {
      toast.error(
        err instanceof Error ? err.message : "Error al actualizar ticket",
      );
    } finally {
      setUpdatingTicket(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-[calc(100vw-2rem)] sm:max-w-2xl max-h-[90vh] overflow-y-auto rounded-xl">
        <DialogHeader>
          <DialogTitle>Actualizar Ticket</DialogTitle>
          <DialogDescription>
            Cambia el estado, prioridad o asignación del ticket
          </DialogDescription>
        </DialogHeader>
        <form
          className="space-y-4"
          onSubmit={handleSubmitUpdate(onSubmitUpdate)}
        >
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="status">Estado</Label>
              <Select
                value={watchUpdate("status") || ticket.status}
                onValueChange={(value) =>
                  setUpdateValue("status", value as unknown)
                }
              >
                <SelectTrigger
                  className="rounded-xl focus:border-epoch-primary focus:ring-epoch-primary/20"
                  id="status"
                >
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {Object.entries(statusLabels).map(([value, label]) => (
                    <SelectItem key={value} value={value}>
                      {label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="priority">Prioridad</Label>
              <Select
                value={watchUpdate("priority") || ticket.priority}
                onValueChange={(value) =>
                  setUpdateValue("priority", value as unknown)
                }
              >
                <SelectTrigger
                  className="rounded-xl focus:border-epoch-primary focus:ring-epoch-primary/20"
                  id="priority"
                >
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {Object.entries(priorityLabels).map(([value, label]) => (
                    <SelectItem key={value} value={value}>
                      {label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="assigned_to">Asignar a</Label>
            <Select
              value={watchUpdate("assigned_to") || "__none__"}
              onValueChange={(value) =>
                setUpdateValue(
                  "assigned_to",
                  value === "__none__" ? undefined : value,
                )
              }
            >
              <SelectTrigger
                className="rounded-xl focus:border-epoch-primary focus:ring-epoch-primary/20"
                id="assigned_to"
              >
                <SelectValue placeholder="Sin asignar" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="__none__">Sin asignar</SelectItem>
                {adminUsers.map((user) => (
                  <SelectItem key={user.id} value={user.id}>
                    {user.email} ({user.role})
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-2">
            <Label htmlFor="resolution">Resolución</Label>
            <Textarea
              id="resolution"
              {...registerUpdate("resolution")}
              className="rounded-xl focus:border-epoch-primary focus:ring-epoch-primary/20"
              placeholder="Describe cómo se resolvió el problema..."
              rows={4}
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="resolution_notes">Notas de Resolución</Label>
            <Textarea
              id="resolution_notes"
              {...registerUpdate("resolution_notes")}
              className="rounded-xl focus:border-epoch-primary focus:ring-epoch-primary/20"
              placeholder="Notas adicionales sobre la resolución..."
              rows={3}
            />
          </div>

          <DialogFooter className="flex-col sm:flex-row gap-2">
            <Button
              className="rounded-xl border-admin-border-primary/20 w-full sm:w-auto min-h-[44px]"
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
            >
              Cancelar
            </Button>
            <Button
              className="rounded-xl bg-epoch-primary hover:bg-epoch-surface text-white font-display font-bold text-[10px] tracking-[0.2em] uppercase w-full sm:w-auto min-h-[44px]"
              disabled={updatingTicket}
              type="submit"
            >
              {updatingTicket ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  Actualizando...
                </>
              ) : (
                <>
                  <CheckCircle2 className="mr-2 h-4 w-4" />
                  Actualizar
                </>
              )}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { Mail, Phone, Search, User } from "lucide-react";
import { useEffect, useState } from "react";

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { extractDataFromResponse } from "@/lib/api/response-helpers";
import { appLogger } from '@/lib/logger';

import type { Customer } from "./types";

interface CustomerSearchCardProps {
  email: string;
  name: string;
  onSelect: (customer: Customer) => void;
  onChangeEmail: (email: string) => void;
  onChangeName: (name: string) => void;
}

export function CustomerSearchCard({
  email,
  name,
  onSelect,
  onChangeEmail,
  onChangeName,
}: CustomerSearchCardProps) {
  const [customerSearch, setCustomerSearch] = useState("");
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [searching, setSearching] = useState(false);
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(
    null,
  );

  useEffect(() => {
    if (customerSearch.length >= 3) {
      searchCustomers();
    } else {
      setCustomers([]);
    }
  }, [customerSearch]);

  const searchCustomers = async () => {
    try {
      setSearching(true);
      const response = await fetch(
        `/api/admin/customers?search=${encodeURIComponent(customerSearch)}&limit=10`,
      );
      if (response.ok) {
        const data = await response.json();
        setCustomers(extractDataFromResponse(data));
      }
    } catch (err) {
      appLogger.error("Error searching customers:", err);
    } finally {
      setSearching(false);
    }
  };

  const handleSelect = (customer: Customer) => {
    setSelectedCustomer(customer);
    onSelect(customer);
    setCustomerSearch(
      `${customer.first_name || ""} ${customer.last_name || ""}`.trim() ||
        customer.email,
    );
    setCustomers([]);
  };

  return (
    <Card className="bg-admin-bg-tertiary shadow-[0_1px_3px_rgba(0,0,0,0.3)]">
      <CardHeader>
        <CardTitle className="flex items-center">
          <User className="h-5 w-5 mr-2" />
          Información del Cliente
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div>
          <label className="block text-sm font-medium text-admin-text-tertiary mb-2">
            Buscar Cliente
          </label>
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-admin-text-tertiary h-4 w-4" />
            <Input
              className="pl-10"
              placeholder="Buscar por nombre o email..."
              value={customerSearch}
              onChange={(e) => setCustomerSearch(e.target.value)}
            />
          </div>
          {searching && (
            <p className="text-sm text-admin-text-tertiary mt-2">
              Buscando clientes...
            </p>
          )}
          {customers.length > 0 && (
            <div className="mt-2 border rounded-md max-h-48 overflow-y-auto">
              {customers.map((customer) => (
                <button
                  className="w-full text-left p-3 hover:bg-gray-50 border-b border-gray-100 last:border-b-0"
                  key={customer.id}
                  type="button"
                  onClick={() => handleSelect(customer)}
                >
                  <div className="font-medium">
                    {customer.first_name && customer.last_name
                      ? `${customer.first_name} ${customer.last_name}`
                      : customer.email}
                  </div>
                  <div className="text-sm text-admin-text-tertiary">
                    {customer.email}
                  </div>
                  {customer.is_member && (
                    <div className="text-xs text-admin-success">
                      Miembro {customer.membership_tier}
                    </div>
                  )}
                </button>
              ))}
            </div>
          )}
        </div>

        <div>
          <label className="block text-sm font-medium text-admin-text-tertiary mb-2">
            Email del Cliente <span className="text-red-500">*</span>
          </label>
          <Input
            required
            placeholder="cliente@ejemplo.com"
            type="email"
            value={email}
            onChange={(e) => onChangeEmail(e.target.value)}
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-admin-text-tertiary mb-2">
            Nombre del Cliente
          </label>
          <Input
            placeholder="Nombre completo"
            value={name}
            onChange={(e) => onChangeName(e.target.value)}
          />
        </div>

        {selectedCustomer && (
          <div className="p-3 bg-blue-50 rounded-lg border border-blue-200">
            <h4 className="font-medium text-blue-900 mb-2">
              Cliente Seleccionado:
            </h4>
            <div className="space-y-1 text-sm">
              <div className="flex items-center gap-2">
                <Mail className="h-3 w-3" />
                {selectedCustomer.email}
              </div>
              {selectedCustomer.phone && (
                <div className="flex items-center gap-2">
                  <Phone className="h-3 w-3" />
                  {selectedCustomer.phone}
                </div>
              )}
              {selectedCustomer.is_member && (
                <div className="text-admin-success font-medium">
                  Miembro {selectedCustomer.membership_tier}
                </div>
              )}
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import { Package, Search } from "lucide-react";
import { useEffect, useState } from "react";

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { extractDataFromResponse } from "@/lib/api/response-helpers";
import { appLogger } from '@/lib/logger';

import type { Order } from "./types";

interface OrderSearchCardProps {
  onSelect: (order: Order) => void;
}

export function OrderSearchCard({ onSelect }: OrderSearchCardProps) {
  const [orderSearch, setOrderSearch] = useState("");
  const [orders, setOrders] = useState<Order[]>([]);
  const [searching, setSearching] = useState(false);
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);

  useEffect(() => {
    if (orderSearch.length >= 3) {
      searchOrders();
    } else {
      setOrders([]);
    }
  }, [orderSearch]);

  const searchOrders = async () => {
    try {
      setSearching(true);
      const response = await fetch(
        `/api/admin/orders?search=${encodeURIComponent(orderSearch)}&limit=10`,
      );
      if (response.ok) {
        const data = await response.json();
        setOrders(extractDataFromResponse(data));
      }
    } catch (err) {
      appLogger.error("Error searching orders:", err);
    } finally {
      setSearching(false);
    }
  };

  const handleSelect = (order: Order) => {
    setSelectedOrder(order);
    onSelect(order);
    setOrderSearch(order.order_number);
    setOrders([]);
  };

  const formatPrice = (amount: number) =>
    new Intl.NumberFormat("es-AR", {
      style: "currency",
      currency: "ARS",
    }).format(amount);

  return (
    <Card className="bg-admin-bg-tertiary shadow-[0_1px_3px_rgba(0,0,0,0.3)]">
      <CardHeader>
        <CardTitle className="flex items-center">
          <Package className="h-5 w-5 mr-2" />
          Pedido Relacionado (Opcional)
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div>
          <label className="block text-sm font-medium text-admin-text-tertiary mb-2">
            Buscar Pedido
          </label>
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-admin-text-tertiary h-4 w-4" />
            <Input
              className="pl-10"
              placeholder="Buscar por número de pedido..."
              value={orderSearch}
              onChange={(e) => setOrderSearch(e.target.value)}
            />
          </div>
          {searching && (
            <p className="text-sm text-admin-text-tertiary mt-2">
              Buscando pedidos...
            </p>
          )}
          {orders.length > 0 && (
            <div className="mt-2 border rounded-md max-h-48 overflow-y-auto">
              {orders.map((order) => (
                <button
                  className="w-full text-left p-3 hover:bg-gray-50 border-b border-gray-100 last:border-b-0"
                  key={order.id}
                  type="button"
                  onClick={() => handleSelect(order)}
                >
                  <div className="font-medium">#{order.order_number}</div>
                  <div className="text-sm text-admin-text-tertiary">
                    {formatPrice(order.total_amount)} • {order.status}
                  </div>
                  <div className="text-xs text-admin-text-tertiary">
                    {new Date(order.created_at).toLocaleDateString("es-AR")}
                  </div>
                </button>
              ))}
            </div>
          )}
        </div>

        {selectedOrder && (
          <div className="p-3 bg-green-50 rounded-lg border border-green-200">
            <h4 className="font-medium text-green-900 mb-2">
              Pedido Seleccionado:
            </h4>
            <div className="space-y-1 text-sm">
              <div>
                <strong>#{selectedOrder.order_number}</strong>
              </div>
              <div>Total: {formatPrice(selectedOrder.total_amount)}</div>
              <div>Estado: {selectedOrder.status}</div>
              <div>
                Fecha:{" "}
                {new Date(selectedOrder.created_at).toLocaleDateString("es-AR")}
              </div>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import { AlertTriangle, ArrowLeft, MessageSquare, Plus } from "lucide-react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { extractDataFromResponse } from "@/lib/api/response-helpers";
import { appLogger } from '@/lib/logger';

import { CustomerSearchCard } from "./_components/CustomerSearchCard";
import { OrderSearchCard } from "./_components/OrderSearchCard";
import type {
  Category,
  Customer,
  NewTicketForm,
  Order,
} from "./_components/types";

export default function NewTicketPage() {
  const router = useRouter();
  const [loading, setLoading] = useState(false);
  const [categories, setCategories] = useState<Category[]>([]);
  const [adminUsers, setAdminUsers] = useState<unknown[]>([]);

  const [form, setForm] = useState<NewTicketForm>({
    title: "",
    description: "",
    priority: "medium",
    category_id: "",
    customer_email: "",
    customer_name: "",
    order_id: "",
    assigned_to: "unassigned",
  });

  useEffect(() => {
    fetchCategories();
    fetchAdminUsers();
  }, []);

  const fetchCategories = async () => {
    try {
      const response = await fetch("/api/admin/support/categories");
      if (response.ok) {
        const data = await response.json();
        setCategories(data.categories || []);
      }
    } catch (err) {
      appLogger.error("Error fetching categories:", err);
    }
  };

  const fetchAdminUsers = async () => {
    try {
      const response = await fetch("/api/admin/users");
      if (response.ok) {
        const data = await response.json();
        setAdminUsers(extractDataFromResponse(data));
      }
    } catch (err) {
      appLogger.error("Error fetching admin users:", err);
    }
  };

  const handleSelectCustomer = (customer: Customer) => {
    setForm((prev) => ({
      ...prev,
      customer_email: customer.email,
      customer_name:
        `${customer.first_name || ""} ${customer.last_name || ""}`.trim(),
    }));
  };

  const handleSelectOrder = (order: Order) => {
    setForm((prev) => ({ ...prev, order_id: order.id }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (
      !form.title.trim() ||
      !form.description.trim() ||
      !form.customer_email.trim()
    ) {
      alert("Por favor, completa todos los campos obligatorios.");
      return;
    }
    try {
      setLoading(true);
      const response = await fetch("/api/admin/support/tickets", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          title: form.title.trim(),
          description: form.description.trim(),
          priority: form.priority,
          category_id: form.category_id || null,
          customer_email: form.customer_email.trim(),
          customer_name: form.customer_name.trim() || null,
          order_id: form.order_id || null,
          assigned_to:
            form.assigned_to && form.assigned_to !== "unassigned"
              ? form.assigned_to
              : null,
          created_by_admin: true,
        }),
      });
      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(
          errorData.details
            ? `${errorData.error}: ${errorData.details}`
            : errorData.error || "Failed to create ticket",
        );
      }
      const data = await response.json();
      toast.success("Ticket creado exitosamente", {
        description: `Número de ticket: ${data.ticket?.ticket_number || "N/A"}`,
      });
      if (data.ticket?.id) {
        router.push(`/admin/support/tickets/${data.ticket.id}`);
      } else {
        router.push("/admin/support");
      }
    } catch (err) {
      appLogger.error("Error creating ticket:", err);
      toast.error("Error al crear el ticket", {
        description:
          err instanceof Error ? err.message : "Error al crear el ticket.",
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Link href="/admin/support">
          <Button size="sm" variant="outline">
            <ArrowLeft className="h-4 w-4 mr-2" />
            Volver
          </Button>
        </Link>
        <div>
          <h1 className="text-3xl font-bold text-epoch-primary">
            Crear Nuevo Ticket
          </h1>
          <p className="text-admin-text-tertiary">
            Crea un ticket de soporte en nombre de un cliente
          </p>
        </div>
      </div>

      <form
        className="grid grid-cols-1 lg:grid-cols-3 gap-6"
        onSubmit={handleSubmit}
      >
        <div className="lg:col-span-2 space-y-6">
          <Card className="bg-admin-bg-tertiary shadow-[0_1px_3px_rgba(0,0,0,0.3)]">
            <CardHeader>
              <CardTitle className="flex items-center">
                <MessageSquare className="h-5 w-5 mr-2" />
                Detalles del Ticket
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-admin-text-tertiary mb-2">
                  Título <span className="text-red-500">*</span>
                </label>
                <Input
                  required
                  placeholder="Describe brevemente el problema..."
                  value={form.title}
                  onChange={(e) =>
                    setForm((prev) => ({ ...prev, title: e.target.value }))
                  }
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-admin-text-tertiary mb-2">
                  Descripción <span className="text-red-500">*</span>
                </label>
                <Textarea
                  required
                  placeholder="Describe el problema en detalle..."
                  rows={6}
                  value={form.description}
                  onChange={(e) =>
                    setForm((prev) => ({
                      ...prev,
                      description: e.target.value,
                    }))
                  }
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-admin-text-tertiary mb-2">
                    Prioridad
                  </label>
                  <Select
                    value={form.priority}
                    onValueChange={(value) =>
                      setForm((prev) => ({ ...prev, priority: value }))
                    }
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="low">Baja</SelectItem>
                      <SelectItem value="medium">Media</SelectItem>
                      <SelectItem value="high">Alta</SelectItem>
                      <SelectItem value="urgent">Urgente</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-admin-text-tertiary mb-2">
                    Categoría
                  </label>
                  <Select
                    value={form.category_id}
                    onValueChange={(value) =>
                      setForm((prev) => ({ ...prev, category_id: value }))
                    }
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Seleccionar categoría" />
                    </SelectTrigger>
                    <SelectContent>
                      {categories.map((category) => (
                        <SelectItem key={category.id} value={category.id}>
                          {category.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-admin-text-tertiary mb-2">
                  Asignar a
                </label>
                <Select
                  value={form.assigned_to}
                  onValueChange={(value) =>
                    setForm((prev) => ({
                      ...prev,
                      assigned_to: value === "unassigned" ? "" : value,
                    }))
                  }
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Sin asignar" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="unassigned">Sin asignar</SelectItem>
                    {adminUsers.map((admin) => (
                      <SelectItem
                        key={(admin as Record<string, string>).id}
                        value={(admin as Record<string, string>).id}
                      >
                        {(admin as Record<string, string>).email ||
                          (admin as Record<string, string>).name ||
                          `Admin ${String((admin as Record<string, string>).id).slice(0, 8)}`}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </CardContent>
          </Card>
        </div>

        <div className="space-y-6">
          <CustomerSearchCard
            email={form.customer_email}
            name={form.customer_name}
            onChangeEmail={(email) =>
              setForm((prev) => ({ ...prev, customer_email: email }))
            }
            onChangeName={(name) =>
              setForm((prev) => ({ ...prev, customer_name: name }))
            }
            onSelect={handleSelectCustomer}
          />
          <OrderSearchCard onSelect={handleSelectOrder} />

          <Card className="bg-admin-bg-tertiary shadow-[0_1px_3px_rgba(0,0,0,0.3)]">
            <CardContent className="p-6">
              <div className="space-y-3">
                <Button className="w-full" disabled={loading} type="submit">
                  <Plus className="h-4 w-4 mr-2" />
                  {loading ? "Creando Ticket..." : "Crear Ticket"}
                </Button>
                <Link href="/admin/support">
                  <Button className="w-full" variant="outline">
                    Cancelar
                  </Button>
                </Link>
              </div>
              <div className="mt-4 p-3 bg-yellow-50 rounded-lg border border-yellow-200">
                <div className="flex items-start gap-2">
                  <AlertTriangle className="h-4 w-4 text-yellow-600 mt-0.5" />
                  <div>
                    <p className="text-sm font-medium text-yellow-900">
                      Nota Importante
                    </p>
                    <p className="text-xs text-yellow-800 mt-1">
                      Este ticket será creado en nombre del cliente. Se enviará
                      una notificación por email automáticamente.
                    </p>
                  </div>
                </div>
              </div>
            </CardContent>
          </Card>
        </div>
      </form>
    </div>
  );
}

