      />
      <SystemStatusDialog
        setShowSystemStatusDialog={setShowSystemStatusDialog}
        showSystemStatusDialog={showSystemStatusDialog}
        systemStatusReport={systemStatusReport}
      />
      <BackupDialog
        backupResult={backupResult}
        handleDownloadBackup={handleDownloadBackup}
        setShowBackupDialog={setShowBackupDialog}
        showBackupDialog={showBackupDialog}
      />
      <RestoreDialog
        confirmRestoreBackup={confirmRestoreBackup}
        isRestoring={isRestoring}
        selectedBackup={selectedBackup}
        setShowRestoreDialog={setShowRestoreDialog}
        showRestoreDialog={showRestoreDialog}
      />
      <RestoreResultsDialog
        restoreResults={restoreResults}
        setShowRestoreResultsDialog={setShowRestoreResultsDialog}
        showRestoreResultsDialog={showRestoreResultsDialog}
      />
      <DeleteBackupDialog
        confirmDeleteBackup={confirmDeleteBackup}
        isDeleting={isDeleting}
        selectedBackup={selectedBackup}
        setShowDeleteBackupDialog={setShowDeleteBackupDialog}
        showDeleteBackupDialog={showDeleteBackupDialog}
      />
    </div>
  );
}

"use client";

import { AlertTriangle, Clock, Monitor, XCircle } from "lucide-react";

import { Badge } from "@/components/ui/badge";
import { Card, CardContent } from "@/components/ui/card";

interface HealthStatus {
  status: string;
  warnings: number;
  criticals: number;
  last_check: string;
}

function getHealthStatusBadge(status: string) {
  const config: Record<string, { label: string; className: string }> = {
    healthy: {
      label: "Saludable",
      className:
        "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400 border-green-200 dark:border-green-800",
    },
    warning: {
      label: "Advertencias",
      className:
        "bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-400 border-yellow-200 dark:border-yellow-800",
    },
    critical: {
      label: "Crítico",
      className:
        "bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400 border-red-200 dark:border-red-800",
    },
  };
  const cfg = config[status] || {
    label: status,
    className:
      "bg-gray-100 text-gray-800 dark:bg-gray-900/30 dark:text-gray-400 border-gray-200 dark:border-gray-800",
  };
  return (
    <Badge className={`${cfg.className} border text-xs px-2 py-0.5`}>
      {cfg.label}
    </Badge>
  );
}

interface SystemHealthCardsProps {
  healthStatus: HealthStatus | null;
}

