"use client";

import { AlertTriangle, CheckCircle, XCircle } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";

interface RestoreResultsDialogProps {
  showRestoreResultsDialog: boolean;
  setShowRestoreResultsDialog: (open: boolean) => void;
  restoreResults: unknown | null;
}

export function RestoreResultsDialog({
  showRestoreResultsDialog,
  setShowRestoreResultsDialog,
  restoreResults,
}: RestoreResultsDialogProps) {
  return (
    <Dialog
      open={showRestoreResultsDialog}
      onOpenChange={setShowRestoreResultsDialog}
    >
      <DialogContent className="max-w-[calc(100vw-2rem)] sm:max-w-3xl max-h-[80vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <CheckCircle className="h-5 w-5 text-green-600" />
            Resultados de Restauración
          </DialogTitle>
          <DialogDescription>
            Restauración de backup completada
          </DialogDescription>
        </DialogHeader>

        {restoreResults && (
          <div className="space-y-4">
            {/* Success Message */}
            <div className="p-4 bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-800 rounded-lg">
              <div className="flex items-center gap-2">
                <CheckCircle className="h-5 w-5 text-green-600" />
                <span className="font-semibold text-green-800 dark:text-green-300">
                  Restauración completada exitosamente
                </span>
              </div>
              <p className="text-sm text-green-700 dark:text-green-400 mt-2">
                {restoreResults.total_records_restored} registros restaurados
                en {restoreResults.tables_restored} tablas
              </p>
            </div>

            {/* Summary Information */}
            <Card className="bg-admin-bg-tertiary">
              <CardContent className="p-4">
                <div className="space-y-2 text-sm">
                  <div className="flex justify-between">
                    <span className="text-admin-text-tertiary">
                      Backup restaurado:
                    </span>
                    <span className="font-medium">
                      {restoreResults.backup_file}
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-admin-text-tertiary">
                      Backup ID:
                    </span>
                    <span className="font-mono text-xs">
                      {restoreResults.backup_id}
                    </span>
                  </div>
                  {restoreResults.safety_backup_id && (
                    <div className="flex justify-between">
                      <span className="text-admin-text-tertiary">
                        Backup de seguridad creado:
                      </span>
                      <span className="font-mono text-xs">
                        {restoreResults.safety_backup_id}
                      </span>
                    </div>
                  )}
                  <div className="flex justify-between">
                    <span className="text-admin-text-tertiary">
                      Tablas restauradas:
                    </span>
                    <span className="font-medium">
                      {restoreResults.tables_restored}
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-admin-text-tertiary">
                      Total de registros:
                    </span>
                    <span className="font-medium">
                      {restoreResults.total_records_restored.toLocaleString()}
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-admin-text-tertiary">
                      Tiempo de ejecución:
                    </span>
                    <span className="font-medium">
                      {restoreResults.duration_seconds}s
                    </span>
                  </div>
                  {restoreResults.errors > 0 && (
                    <div className="flex justify-between">
                      <span className="text-admin-text-tertiary">
                        Errores:
                      </span>
                      <span className="font-medium text-red-600">
                        {restoreResults.errors}
                      </span>
                    </div>
                  )}
                </div>
              </CardContent>
            </Card>

            {/* Detailed Results by Table */}
            {restoreResults.restore_results && (
              <Card className="bg-admin-bg-tertiary">
                <CardContent className="p-4">
                  <div className="space-y-2">
                    {Object.entries(restoreResults.restore_results).map(
                      ([tableName, result]: [string, unknown]) => (
                        <div
                          className={`p-3 rounded-lg border ${
                            result.status === "success"
                              ? "bg-green-50 dark:bg-green-900/20 border-green-200 dark:border-green-800"
                              : result.status === "error"
                                ? "bg-red-50 dark:bg-red-900/20 border-red-200 dark:border-red-800"
                                : "bg-yellow-50 dark:bg-yellow-900/20 border-yellow-200 dark:border-yellow-800"
                          }`}
                          key={tableName}
                        >
                          <div className="flex items-center justify-between">
                            <div className="flex items-center gap-2">
                              {result.status === "success" && (
                                <CheckCircle className="h-4 w-4 text-green-600" />
                              )}
                              {result.status === "error" && (
                                <XCircle className="h-4 w-4 text-red-600" />
                              )}
                              {(result.status === "partial" ||
                                result.status === "skipped") && (
                                <AlertTriangle className="h-4 w-4 text-yellow-600" />
                              )}
                              <span className="font-medium text-sm capitalize">
                                {tableName}
                              </span>
                            </div>
                            <div className="text-xs text-admin-text-tertiary">
                              {result.status === "success" && (
                                <span className="text-green-700 dark:text-green-400">
                                  {result.records_restored} registros
                                </span>
                              )}
                              {result.status === "partial" && (
                                <span className="text-yellow-700 dark:text-yellow-400">
                                  {result.records_restored}/
                                  {result.records_total} registros
                                </span>
                              )}
                              {result.status === "skipped" && (
                                <span className="text-admin-text-tertiary">
                                  {result.reason}
                                </span>
                              )}
                              {result.status === "error" && (
                                <span className="text-red-700 dark:text-red-400">
                                  Error
                                </span>
                              )}
                            </div>
                          </div>
                          {result.note && (
                            <div className="mt-2 ml-6 p-2 bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded text-xs text-blue-700 dark:text-blue-400">
                              ℹ️ {result.note}
                            </div>
                          )}
                          {result.error && (
                            <p className="text-xs text-red-600 dark:text-red-400 mt-1 ml-6">
                              {result.error}
                            </p>
                          )}
                          {result.error_message && (
                            <p className="text-xs text-red-600 dark:text-red-400 mt-1 ml-6 font-semibold">
                              Error: {result.error_message}
                            </p>
                          )}
                        </div>
                      ),
                    )}
                  </div>
                </CardContent>
              </Card>
            )}
          </div>
        )}

        <DialogFooter>
          <Button onClick={() => setShowRestoreResultsDialog(false)}>
            Cerrar
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { AlertTriangle, CheckCircle, Shield } from "lucide-react";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";

interface SecurityAuditDialogProps {
  showSecurityAuditDialog: boolean;
  setShowSecurityAuditDialog: (open: boolean) => void;
  securityAuditResults: {
    issues: string[];
    issues_count: number;
  } | null;
}

export function SecurityAuditDialog({
  showSecurityAuditDialog,
  setShowSecurityAuditDialog,
  securityAuditResults,
}: SecurityAuditDialogProps) {
  return (
    <Dialog
      open={showSecurityAuditDialog}
      onOpenChange={setShowSecurityAuditDialog}
    >
      <DialogContent className="max-w-[calc(100vw-2rem)] sm:max-w-2xl">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Shield className="h-5 w-5" />
            Resultados de Auditoría de Seguridad
          </DialogTitle>
          <DialogDescription>
            La auditoría revisa: administradores inactivos, cantidad mínima de
            admins activos y otras políticas de seguridad.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4">
          {securityAuditResults && securityAuditResults.issues_count > 0 ? (
            <>
              <div className="p-4 bg-yellow-50 dark:bg-yellow-900/20 border border-yellow-200 dark:border-yellow-800 rounded-lg">
                <div className="flex items-center gap-2 mb-2">
                  <AlertTriangle className="h-5 w-5 text-yellow-600" />
                  <span className="font-semibold text-yellow-800 dark:text-yellow-300">
                    Se encontraron {securityAuditResults.issues_count}{" "}
                    {securityAuditResults.issues_count === 1
                      ? "problema"
                      : "problemas"}
                  </span>
                </div>
              </div>

              <div className="space-y-2">
                <h4 className="font-medium text-sm">Problemas Detectados:</h4>
                <ul className="list-disc list-inside space-y-1">
                  {securityAuditResults.issues.map((issue, index) => (
                    <li
                      className="text-sm text-admin-text-tertiary pl-2"
                      key={index}
                    >
                      {issue}
                    </li>
                  ))}
                </ul>
              </div>
            </>
          ) : (
            <div className="p-4 bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-800 rounded-lg">
              <div className="flex items-center gap-2">
                <CheckCircle className="h-5 w-5 text-green-600" />
                <span className="font-semibold text-green-800 dark:text-green-300">
                  No se encontraron problemas de seguridad
                </span>
              </div>
              <p className="text-sm text-green-700 dark:text-green-400 mt-2">
                El sistema está configurado correctamente desde el punto de
                vista de seguridad.
              </p>
            </div>
          )}
        </div>

        <DialogFooter>
          <Button onClick={() => setShowSecurityAuditDialog(false)}>
            Cerrar
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useSearchParams } from "next/navigation";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { useBranch } from "@/hooks/useBranch";

import { BackupResult, useBackups } from "../hooks/useBackups";
import { useSystemConfig } from "../hooks/useSystemConfig";
import { useSystemHealth } from "../hooks/useSystemHealth";

export function useSystemAdmin() {
  const searchParams = useSearchParams();
  const tabFromUrl = searchParams.get("tab");
  const {
    currentBranchId,
    isSuperAdmin,
    branches,
    organizationId,
    currentBranchName,
  } = useBranch();

  const validTabs = [
    "overview",
    "config",
    "email",
    "notifications",
    "billing",
    "formularios",
    "whatsapp",
    "encuestas",
    "health",
    "maintenance",
  ];

  const [configScope, setConfigScope] = useState<"global" | "branch">("global");
  const [activeTab, setActiveTab] = useState(
    tabFromUrl && validTabs.includes(tabFromUrl) ? tabFromUrl : "overview",
  );

  useEffect(() => {
    if (tabFromUrl && validTabs.includes(tabFromUrl)) setActiveTab(tabFromUrl);
  }, [tabFromUrl]);

  const configBranchId =
    configScope === "branch" && currentBranchId ? currentBranchId : null;

  const {
    configs,
    isLoading: configsLoading,
    updateConfig,
    isUpdating,
  } = useSystemConfig({ branchId: configBranchId });

  const {
    healthMetrics,
    healthStatus,
    isLoading: healthLoading,
    refreshHealth,
    clearMemory,
    refreshing,
    clearingMemory,
  } = useSystemHealth();

  const {
    backups,
    isLoading: backupsLoading,
    refetch: refetchBackups,
    createBackup,
    restoreBackup: restoreBackupMutation,
    deleteBackup: deleteBackupMutation,
    getBackupDetails,
    isRestoring,
    isDeleting,
  } = useBackups();

  const [showSecurityAuditDialog, setShowSecurityAuditDialog] = useState(false);
  const [securityAuditResults, setSecurityAuditResults] = useState<{
    issues: string[];
    issues_count: number;
  } | null>(null);
  const [showSystemStatusDialog, setShowSystemStatusDialog] = useState(false);
  const [systemStatusReport, setSystemStatusReport] = useState<unknown>(null);
  const [showBackupDialog, setShowBackupDialog] = useState(false);
  const [backupResult, setBackupResult] = useState<BackupResult | null>(null);
  const [showRestoreDialog, setShowRestoreDialog] = useState(false);
  const [selectedBackup, setSelectedBackup] = useState<unknown | null>(null);
  const [showRestoreResultsDialog, setShowRestoreResultsDialog] =
    useState(false);
  const [restoreResults, setRestoreResults] = useState<unknown | null>(null);
  const [showDeleteBackupDialog, setShowDeleteBackupDialog] = useState(false);

  const handleMaintenanceAction = async (action: string) => {
    try {
      const body: { action: string; branch_id?: string } = { action };
      if (
        (action === "backup_database" || action === "system_status") &&
        currentBranchId
      )
        body.branch_id = currentBranchId;
      const response = await fetch("/api/admin/system/maintenance", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      });
      if (!response.ok)
        throw new Error(
          (await response.json()).error || "Error al ejecutar acción",
        );
      const data = await response.json();
      toast.success(data.message || "Acción completada");

      if (action === "security_audit" && data.issues) {
        setSecurityAuditResults({
          issues: data.issues || [],
          issues_count: data.issues_count || 0,
        });
        setShowSecurityAuditDialog(true);
      } else if (action === "system_status" && data.report) {
        setSystemStatusReport(data.report);
        setShowSystemStatusDialog(true);
      } else if (action === "backup_database" && data.backup_id) {
        setBackupResult({
          backup_id: data.backup_id,
          backup_file: data.backup_file,
          download_url: data.download_url || null,
          download_url_expires_at: data.download_url_expires_at || null,
          tables_count: data.tables_count || 0,
          total_records: data.total_records || 0,
          backup_size_mb: data.backup_size_mb || "0",
          duration_seconds: data.duration_seconds || "0",
        });
        setShowBackupDialog(true);
      }
      refreshHealth();
      refetchBackups();
    } catch (error) {
      toast.error(
        error instanceof Error ? error.message : "Error al ejecutar acción",
      );
    }
  };

  const handleCreateBackup = async () => {
    try {
      const result = await createBackup();
      setBackupResult(result as BackupResult);
      setShowBackupDialog(true);
    } catch {
      /* handled */
    }
  };
  const handleViewBackupDetails = async (backup: unknown) => {
    try {
      const result = await getBackupDetails(backup);
      setBackupResult(result as BackupResult);
      setShowBackupDialog(true);
    } catch {
      /* handled */
    }
  };
  const handleRestoreBackup = (backup: unknown) => {
    setSelectedBackup(backup);
    setShowRestoreDialog(true);
  };
  const confirmRestoreBackup = async () => {
    if (!selectedBackup) return;
    try {
      setShowRestoreDialog(false);
      const result = await restoreBackupMutation(selectedBackup);
      setRestoreResults(result);
      setShowRestoreResultsDialog(true);
      setSelectedBackup(null);
    } catch {
      setSelectedBackup(null);
    }
  };
  const handleDeleteBackup = (backup: unknown) => {
    setSelectedBackup(backup);
    setShowDeleteBackupDialog(true);
  };
  const confirmDeleteBackup = async () => {
    if (!selectedBackup) return;
    try {
      await deleteBackupMutation(selectedBackup);
      setShowDeleteBackupDialog(false);
      setSelectedBackup(null);
    } catch {
      /* handled */
    }
  };
  const handleDownloadBackup = (downloadUrl: string, fileName: string) => {
    if (!downloadUrl) {
      toast.error("URL de descarga no disponible");
      return;
    }
    const link = document.createElement("a");
    link.href = downloadUrl;
    link.download = fileName;
    link.target = "_blank";
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    toast.success("Descarga iniciada");
  };

  return {
    configScope,
    setConfigScope,
    activeTab,
    setActiveTab,
    currentBranchId,
    isSuperAdmin,
    branches,
    organizationId,
    currentBranchName,
    configs,
    configsLoading,
    updateConfig,
    isUpdating,
    healthMetrics,
    healthStatus,
    healthLoading,
    refreshHealth,
    clearMemory,
    refreshing,
    clearingMemory,
    backups,
    backupsLoading,
    refetchBackups,
    showSecurityAuditDialog,
    setShowSecurityAuditDialog,
    securityAuditResults,
    showSystemStatusDialog,
    setShowSystemStatusDialog,
    systemStatusReport,
    showBackupDialog,
    setShowBackupDialog,
    backupResult,
    showRestoreDialog,
    setShowRestoreDialog,
    selectedBackup,
    confirmRestoreBackup,
    isRestoring,
    showRestoreResultsDialog,
    setShowRestoreResultsDialog,
    restoreResults,
    showDeleteBackupDialog,
    setShowDeleteBackupDialog,
    isDeleting,
    handleMaintenanceAction,
    handleCreateBackup,
    handleViewBackupDetails,
    handleRestoreBackup,
    handleDeleteBackup,
    confirmDeleteBackup,
    handleDownloadBackup,
  };
}

"use client";

import { Building2, Copy, FileText, Save, Sparkles } from "lucide-react";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import ImageUpload from "@/components/ui/ImageUpload";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { useBranch } from "@/hooks/useBranch";
import { appLogger } from '@/lib/logger';
import { getBranchHeader } from "@/lib/utils/branch";

interface BillingSettings {
  id?: string;
  branch_id: string;
  business_name: string;
  business_rut: string;
  business_address?: string;
  business_phone?: string;
  business_email?: string;
  logo_url?: string;
  header_text?: string;
  footer_text?: string;
  terms_and_conditions?: string;
  default_document_type: "boleta" | "factura";
}

export default function BillingSettingsPage() {
  const { currentBranchId, isSuperAdmin } = useBranch();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [settings, setSettings] = useState<BillingSettings>({
    branch_id: currentBranchId || "",
    business_name: "",
    business_rut: "",
    business_address: "",
    business_phone: "",
    business_email: "",
    logo_url: "",
    header_text: "",
    footer_text: "",
    terms_and_conditions: "",
    default_document_type: "boleta",
  });

  useEffect(() => {
    if (currentBranchId || isSuperAdmin) {
      fetchSettings();
    }
  }, [currentBranchId, isSuperAdmin]);

  const fetchSettings = async () => {
    setLoading(true);
    try {
      const headers = {
        ...getBranchHeader(currentBranchId),
      };

      const response = await fetch("/api/admin/billing/settings", {
        headers,
        credentials: "include",
      });

      if (response.ok) {
        const data = await response.json();
        if (data.settings) {
          setSettings(data.settings);
        }
      } else if (response.status !== 404) {
        const error = await response.json();
        toast.error(error.error || "Error al cargar configuración");
      }
    } catch (error: unknown) {
      appLogger.error("Error fetching settings:", error);
      toast.error("Error al cargar configuración");
    } finally {
      setLoading(false);
    }
  };

  const handleSave = async () => {
    if (!settings.business_name || !settings.business_rut) {
      toast.error("Nombre y RUT de la empresa son requeridos");
      return;
    }

    setSaving(true);
    try {
      const headers = {
        "Content-Type": "application/json",
        ...getBranchHeader(currentBranchId),
      };

      const response = await fetch("/api/admin/billing/settings", {
        method: "PUT",
        headers,
        credentials: "include",
        body: JSON.stringify(settings),
      });

      if (response.ok) {
        toast.success("Configuración guardada exitosamente");
        await fetchSettings();
      } else {
        const error = await response.json();
        toast.error(error.error || "Error al guardar configuración");
      }
    } catch (error: unknown) {
      appLogger.error("Error saving settings:", error);
      toast.error("Error al guardar configuración");
    } finally {
      setSaving(false);
    }
  };

  const handleReuseMainLogo = async () => {
    try {
      const response = await fetch("/api/admin/organizations/current");
      if (response.ok) {
        const data = await response.json();
        if (data.organization?.logo_url) {
          setSettings((prev) => ({
            ...prev,
            logo_url: data.organization.logo_url,
          }));
          toast.success("Logo de la óptica copiado correctamente");
        } else {
          toast.error("No se ha configurado un logo para la óptica aún");
        }
      }
    } catch (error) {
      appLogger.error("Error fetching main logo:", error);
      toast.error("Error al obtener el logo de la óptica");
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-epoch-primary mx-auto mb-4" />
          <p className="text-admin-text-tertiary">Cargando configuración...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-epoch-primary">
            Configuración de Boletas
          </h1>
          <p className="text-admin-text-tertiary mt-1">
            Personaliza tus boletas y facturas
          </p>
        </div>
        <Button disabled={saving} onClick={handleSave}>
          {saving ? (
            <>
              <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2" />
              Guardando...
            </>
          ) : (
            <>
              <Save className="h-4 w-4 mr-2" />
              Guardar
            </>
          )}
        </Button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Business Information */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Building2 className="h-5 w-5" />
              Información de la Empresa
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div>
              <Label>Nombre de la Empresa *</Label>
              <Input
                placeholder="Ej: Óptica Central"
                value={settings.business_name}
                onChange={(e) =>
                  setSettings({ ...settings, business_name: e.target.value })
                }
              />
            </div>
            <div>
              <Label>RUT de la Empresa *</Label>
              <Input
                className="font-mono"
                placeholder="Ej: 76.123.456-7"
                value={settings.business_rut}
                onChange={(e) =>
                  setSettings({ ...settings, business_rut: e.target.value })
                }
              />
            </div>
            <div>
              <Label>Dirección</Label>
              <Input
                placeholder="Dirección completa"
                value={settings.business_address || ""}
                onChange={(e) =>
                  setSettings({ ...settings, business_address: e.target.value })
                }
              />
            </div>
            <div>
              <Label>Teléfono</Label>
              <Input
                placeholder="+56 9 1234 5678"
                value={settings.business_phone || ""}
                onChange={(e) =>
                  setSettings({ ...settings, business_phone: e.target.value })
                }
              />
            </div>
            <div>
              <Label>Email</Label>
              <Input
                placeholder="contacto@empresa.cl"
                type="email"
                value={settings.business_email || ""}
                onChange={(e) =>
                  setSettings({ ...settings, business_email: e.target.value })
                }
              />
            </div>
          </CardContent>
        </Card>

        {/* Document Customization */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <FileText className="h-5 w-5" />
              Personalización
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div>
              <Label className="text-sm font-bold text-epoch-primary mb-2 block">
                Logo de la Empresa (Boleta/Factura)
              </Label>
              <div className="bg-blue-50/50 border border-blue-100 rounded-lg p-3 mb-4">
                <p className="text-xs text-blue-800 font-medium flex items-center gap-2">
                  <Sparkles className="h-3 w-3" />
                  Dimensiones Requeridas:
                </p>
                <ul className="text-[11px] text-blue-700/80 list-disc list-inside mt-1 space-y-0.5">
                  <li>
                    Formato horizontal:{" "}
                    <strong>400px ancho × 120px alto</strong>
                  </li>
                  <li>
                    Fondo sugerido: <strong>Transparente (PNG)</strong> o{" "}
                    <strong>Blanco</strong>
                  </li>
                  <li>
                    Este logo aparecerá en el encabezado de sus documentos
                    fiscales.
                  </li>
                </ul>
              </div>

              <div className="space-y-4">
                <ImageUpload
                  folder="billing"
                  value={settings.logo_url || ""}
                  onChange={(url) =>
                    setSettings({ ...settings, logo_url: url })
                  }
                />

                <Button
                  className="w-full text-xs"
                  size="sm"
                  type="button"
                  variant="outline"
                  onClick={handleReuseMainLogo}
                >
                  <Copy className="h-3 w-3 mr-2" />
                  Reutilizar Logo de la Óptica (Header)
                </Button>
              </div>
            </div>
            <div>
              <Label>Tipo de Documento por Defecto</Label>
              <select
                className="w-full px-3 py-2 border rounded-md"
                value={settings.default_document_type}
                onChange={(e) =>
                  setSettings({
                    ...settings,
                    default_document_type: e.target.value as unknown,
                  })
                }
              >
                <option value="boleta">Boleta</option>
                <option value="factura">Factura</option>
              </select>
            </div>
            <div>
              <Label>Texto de Encabezado (opcional)</Label>
              <Textarea
                placeholder="Texto que aparecerá en el encabezado de las boletas"
                rows={3}
                value={settings.header_text || ""}
                onChange={(e) =>
                  setSettings({ ...settings, header_text: e.target.value })
                }
              />
            </div>
            <div>
              <Label>Texto de Pie de Página (opcional)</Label>
              <Textarea
                placeholder="Texto que aparecerá en el pie de página"
                rows={3}
                value={settings.footer_text || ""}
                onChange={(e) =>
                  setSettings({ ...settings, footer_text: e.target.value })
                }
              />
            </div>
            <div>
              <Label>Términos y Condiciones (opcional)</Label>
              <Textarea
                placeholder="Términos y condiciones que aparecerán en las boletas"
                rows={4}
                value={settings.terms_and_conditions || ""}
                onChange={(e) =>
                  setSettings({
                    ...settings,
                    terms_and_conditions: e.target.value,
                  })
                }
              />
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

"use client";

import {
  Calendar,
  Clock,
  Database,
  Eye,
  FileText,
  RefreshCw,
  RotateCcw,
  Trash2,
} from "lucide-react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";

import { Backup } from "../hooks/useBackups";

interface BackupManagerProps {
  backups: Backup[];
  loading: boolean;
  onRefresh: () => void;
  onCreateBackup: () => Promise<unknown>;
  onRestoreBackup: (backup: Backup) => Promise<void>;
  onDeleteBackup: (backup: Backup) => Promise<void>;
  onViewBackupDetails: (backup: Backup) => Promise<void>;
  restoring: boolean;
  deleting: boolean;
}

export default function BackupManager({
  backups,
  loading,
  onRefresh,
  onCreateBackup,
  onRestoreBackup,
  onDeleteBackup,
  onViewBackupDetails,
  restoring,
  deleting,
}: BackupManagerProps) {
  return (
    <Card className="rounded-xl border border-border overflow-hidden">
      <CardHeader className="p-4 sm:p-6 pb-0">
        <CardTitle className="flex items-center justify-between font-display text-epoch-primary text-base sm:text-lg">
          <div className="flex items-center min-w-0">
            <FileText className="h-4 w-4 sm:h-5 sm:w-5 mr-2 shrink-0" />
            <span className="truncate">Backups Disponibles</span>
          </div>
          <Button
            className="rounded-xl min-h-[44px] min-w-[44px] shrink-0"
            disabled={loading}
            size="sm"
            variant="ghost"
            onClick={onRefresh}
          >
            <RefreshCw className={`h-4 w-4 ${loading ? "animate-spin" : ""}`} />
          </Button>
        </CardTitle>
      </CardHeader>
      <CardContent className="p-4 sm:p-6 pt-4">
        {loading ? (
          <div className="text-center py-6 sm:py-8">
            <RefreshCw className="h-8 w-8 text-epoch-primary/40 mx-auto mb-4 animate-spin" />
            <p className="text-xs sm:text-sm text-epoch-primary/80">
              Cargando backups...
            </p>
          </div>
        ) : backups.length === 0 ? (
          <div className="text-center py-6 sm:py-8">
            <FileText className="h-10 w-10 sm:h-12 sm:w-12 text-epoch-primary/40 mx-auto mb-3 sm:mb-4 opacity-50" />
            <p className="text-xs sm:text-sm text-epoch-primary/80 mb-2">
              No hay backups disponibles
            </p>
            <p className="text-[10px] sm:text-xs text-epoch-primary/70">
              Crea un backup usando el botón &quot;Backup Base de Datos&quot;
            </p>
          </div>
        ) : (
          <div className="space-y-3">
            {backups.map((backup) => (
              <div
                className="p-3 sm:p-4 rounded-xl border border-border hover:border-epoch-primary/30 transition-colors overflow-hidden"
                key={backup.id}
              >
                <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-3">
                  <div className="flex-1 min-w-0">
                    <div className="flex flex-wrap items-center gap-2 mb-2">
                      <Database className="h-4 w-4 text-epoch-primary shrink-0" />
                      <span className="font-semibold text-xs sm:text-sm text-epoch-primary truncate">
                        {backup.id}
                      </span>
                      {backup.filename.includes("safety_backup") && (
                        <Badge
                          className="text-[10px] sm:text-xs shrink-0"
                          variant="outline"
                        >
                          Backup de Seguridad
                        </Badge>
                      )}
                    </div>
                    <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 text-[10px] sm:text-xs text-epoch-primary/70">
                      <div className="flex items-center gap-1">
                        <Calendar className="h-3 w-3" />
                        <span>
                          {backup.created_at
                            ? new Date(backup.created_at).toLocaleDateString(
                                "es-AR",
                                {
                                  day: "2-digit",
                                  month: "2-digit",
                                  year: "numeric",
                                },
                              )
                            : "N/A"}
                        </span>
                      </div>
                      <div className="flex items-center gap-1">
                        <FileText className="h-3 w-3" />
                        <span>{backup.size_mb} MB</span>
                      </div>
                      <div className="flex items-center gap-1">
                        <Clock className="h-3 w-3" />
                        <span>
                          {backup.created_at
                            ? new Date(backup.created_at).toLocaleTimeString(
                                "es-AR",
                                {
                                  hour: "2-digit",
                                  minute: "2-digit",
                                },
                              )
                            : "N/A"}
                        </span>
                      </div>
                      <div className="flex items-center gap-1 col-span-2 sm:col-span-1">
                        <span className="font-mono text-[10px] sm:text-xs truncate">
                          {backup.filename}
                        </span>
                      </div>
                    </div>
                  </div>
                  <div className="flex items-center gap-1.5 sm:gap-2 sm:ml-4 shrink-0 flex-wrap sm:flex-nowrap">
                    <Button
                      className="h-9 w-9 p-0 rounded-lg border-epoch-primary/20 shrink-0"
                      disabled={restoring || deleting}
                      size="sm"
                      title="Ver detalles y descargar"
                      variant="outline"
                      onClick={() => onViewBackupDetails(backup)}
                    >
                      <Eye className="h-4 w-4" />
                    </Button>
                    <Button
                      className="h-9 px-2 sm:px-3 text-xs rounded-lg border-epoch-primary/20 shrink-0"
                      disabled={restoring || deleting}
                      size="sm"
                      variant="outline"
                      onClick={() => onRestoreBackup(backup)}
                    >
                      <RotateCcw
                        className={`h-3.5 w-3.5 mr-1 shrink-0 ${restoring ? "animate-spin" : ""}`}
                      />
                      Restaurar
                    </Button>
                    <Button
                      className="h-9 w-9 p-0 text-red-600 hover:text-red-700 hover:bg-red-50 dark:hover:bg-red-900/20 border-red-200 dark:border-red-800 rounded-lg shrink-0"
                      disabled={restoring || deleting}
                      size="sm"
                      title="Eliminar backup"
                      variant="outline"
                      onClick={() => onDeleteBackup(backup)}
                    >
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import { Edit2, Eye, EyeOff, FileText, GripVertical, Plus, Trash2 } from "lucide-react";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { appLogger } from '@/lib/logger';

import { AddOptionValueDialog } from "./_dialogs/AddOptionValueDialog";
import { EditOptionValueDialog } from "./_dialogs/EditOptionValueDialog";

const FORM_TYPES = [
  {
    value: "product",
    label: "Productos",
    description: "Opciones del formulario de productos",
  },
  {
    value: "customer",
    label: "Clientes",
    description: "Género, método de contacto, etc.",
  },
  { value: "appointment", label: "Citas", description: "Tipo de cita" },
  {
    value: "quote",
    label: "Presupuestos",
    description: "Opciones de lentes y presbicia",
  },
  {
    value: "prescription",
    label: "Recetas",
    description: "Opciones del formulario de recetas (tipo, material, etc.)",
  },
  { value: "pos", label: "POS", description: "Opciones del punto de venta" },
  {
    value: "global",
    label: "Global",
    description: "Parámetros usados en múltiples formularios",
  },
] as const;

const CATEGORIES = [
  { value: "general", label: "General" },
  { value: "frame", label: "Armazón" },
  { value: "lens", label: "Lente" },
  { value: "accessory", label: "Accesorio" },
];

interface OptionValue {
  id: string;
  field_id: string;
  value: string;
  label: string;
  display_order: number;
  is_active: boolean;
  is_default: boolean;
}

interface OptionField {
  id: string;
  field_key: string;
  field_label: string;
  field_category: string;
  form_type?: string;
  is_array: boolean;
  is_active: boolean;
  display_order: number;
  values?: OptionValue[];
}

/**
 * Configuración de opciones de formularios (productos, clientes, citas, presupuestos, POS).
 * Gestiona product_option_fields y product_option_values vía /api/admin/product-options.
 */
export default function FormOptionsConfig() {
  const [loading, setLoading] = useState(true);
  const [fieldsByFormType, setFieldsByFormType] = useState<
    Record<string, OptionField[]>
  >({});
  const [selectedFormType, setSelectedFormType] = useState<string>("product");
  const [selectedField, setSelectedField] = useState<OptionField | null>(null);
  const [showAddValueDialog, setShowAddValueDialog] = useState(false);
  const [showEditValueDialog, setShowEditValueDialog] = useState(false);
  const [editingValue, setEditingValue] = useState<OptionValue | null>(null);
  const [newValue, setNewValue] = useState({
    value: "",
    label: "",
    is_default: false,
  });

  const fetchAllFields = async () => {
    try {
      setLoading(true);
      const allFields: OptionField[] = [];
      for (const ft of FORM_TYPES) {
        const res = await fetch(
          `/api/admin/product-options?form_type=${ft.value}&include_inactive=true`,
        );
        const data = await res.json();
        if (res.ok && data.fields) {
          allFields.push(...data.fields);
        }
      }
      const grouped: Record<string, OptionField[]> = {};
      FORM_TYPES.forEach((ft) => {
        grouped[ft.value] = allFields.filter(
          (f) => (f.form_type || "product") === ft.value,
        );
      });
      setFieldsByFormType(grouped);
    } catch (error) {
      appLogger.error("Error fetching form options:", error);
      toast.error("Error al cargar opciones de formularios");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchAllFields();
  }, []);

  const handleAddValue = async () => {
    if (!selectedField || !newValue.value || !newValue.label) {
      toast.error("Completa todos los campos");
      return;
    }

    try {
      const response = await fetch("/api/admin/product-options", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          type: "value",
          valueData: {
            field_id: selectedField.id,
            value: newValue.value.toLowerCase().replace(/\s+/g, "_"),
            label: newValue.label,
            is_default: newValue.is_default,
            display_order: (selectedField.values?.length || 0) + 1,
          },
        }),
      });

      const data = await response.json();
      if (response.ok) {
        toast.success("Opción agregada exitosamente");
        setShowAddValueDialog(false);
        setNewValue({ value: "", label: "", is_default: false });
        fetchAllFields();
      } else {
        toast.error(data.error || "Error al agregar opción");
      }
    } catch (error) {
      appLogger.error("Error adding value:", error);
      toast.error("Error al agregar opción");
    }
  };

  const handleEditValue = async () => {
    if (!editingValue || !newValue.label) {
      toast.error("Completa todos los campos");
      return;
    }

    try {
      const response = await fetch("/api/admin/product-options", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          type: "value",
          id: editingValue.id,
          data: {
            label: newValue.label,
            is_default: newValue.is_default,
            is_active: true,
          },
        }),
      });

      const data = await response.json();
      if (response.ok) {
        toast.success("Opción actualizada exitosamente");
        setShowEditValueDialog(false);
        setEditingValue(null);
        setNewValue({ value: "", label: "", is_default: false });
        fetchAllFields();
      } else {
        toast.error(data.error || "Error al actualizar opción");
      }
    } catch (error) {
      appLogger.error("Error updating value:", error);
      toast.error("Error al actualizar opción");
    }
  };

  const handleDeleteValue = async (value: OptionValue) => {
    if (!confirm(`¿Estás seguro de eliminar "${value.label}"?`)) return;

    try {
      const response = await fetch(
        `/api/admin/product-options?type=value&id=${value.id}`,
        { method: "DELETE" },
      );

      const data = await response.json();
      if (response.ok) {
        toast.success("Opción eliminada exitosamente");
        fetchAllFields();
      } else {
        toast.error(data.error || "Error al eliminar opción");
      }
    } catch (error) {
      appLogger.error("Error deleting value:", error);
      toast.error("Error al eliminar opción");
    }
  };

  const handleToggleValueActive = async (value: OptionValue) => {
    try {
      const response = await fetch("/api/admin/product-options", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          type: "value",
          id: value.id,
          data: { is_active: !value.is_active },
        }),
      });

      if (response.ok) {
        toast.success(
          value.is_active ? "Opción desactivada" : "Opción activada",
        );
        fetchAllFields();
      } else {
        toast.error("Error al actualizar opción");
      }
    } catch (error) {
      appLogger.error("Error toggling value:", error);
      toast.error("Error al actualizar opción");
    }
  };

  const openEditDialog = (value: OptionValue) => {
    setEditingValue(value);
    setNewValue({
      value: value.value,
      label: value.label,
      is_default: value.is_default,
    });
    setShowEditValueDialog(true);
  };

  const openAddDialog = (field: OptionField) => {
    setSelectedField(field);
    setNewValue({ value: "", label: "", is_default: false });
    setShowAddValueDialog(true);
  };

  const currentFields = fieldsByFormType[selectedFormType] || [];
  const formTypeInfo = FORM_TYPES.find((ft) => ft.value === selectedFormType);

  if (loading) {
    return (
      <div className="space-y-4">
        <div className="animate-pulse space-y-4">
          <div className="h-8 bg-admin-border-primary/30 rounded-xl w-64" />
          <div className="h-32 bg-admin-border-primary/20 rounded-xl" />
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-4 sm:space-y-6">
      <div className="flex flex-col gap-2 sm:gap-4">
        <h2 className="text-xl sm:text-2xl font-display font-bold text-epoch-primary tracking-tight uppercase">
          Configuración de Formularios
        </h2>
        <p className="text-[10px] sm:text-xs text-epoch-primary/80 uppercase tracking-wider">
          Personaliza las opciones de los menús desplegables en cada formulario
          del sistema.
        </p>
      </div>

      <div className="flex flex-col sm:flex-row gap-4">
        <div className="w-full sm:w-56 flex-shrink-0 space-y-2">
          <Label className="text-[10px] font-display font-bold text-epoch-primary uppercase tracking-widest">
            Formulario
          </Label>
          <Select value={selectedFormType} onValueChange={setSelectedFormType}>
            <SelectTrigger className="h-11 min-h-[44px] w-full sm:w-56 bg-epoch-background/50 border-border rounded-xl font-display text-[10px] tracking-widest uppercase">
              <SelectValue />
            </SelectTrigger>
            <SelectContent className="rounded-xl border-admin-border-primary/20">
              {FORM_TYPES.map((ft) => (
                <SelectItem
                  className="font-display text-[10px] tracking-widest uppercase"
                  key={ft.value}
                  value={ft.value}
                >
                  {ft.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </div>

      <Card className="rounded-xl border border-border overflow-hidden">
        <CardHeader className="p-4 sm:p-6">
          <CardTitle className="flex flex-col sm:flex-row sm:items-center gap-2 text-base sm:text-lg font-display font-bold text-epoch-primary uppercase tracking-tight">
            <span className="flex items-center gap-2">
              <FileText className="h-4 w-4 sm:h-5 sm:w-5 shrink-0" />
              {formTypeInfo?.label}
            </span>
          </CardTitle>
          <p className="text-[10px] sm:text-xs text-epoch-primary/80 uppercase tracking-wider mt-1">
            {formTypeInfo?.description}
          </p>
        </CardHeader>
        <CardContent className="p-4 sm:p-6 pt-0 space-y-4">
          {currentFields.length === 0 ? (
            <p className="text-epoch-primary/70 text-[10px] sm:text-xs py-3 sm:py-4">
              No hay campos configurados para este formulario.
            </p>
          ) : (
            currentFields.map((field) => (
              <div
                className="border border-border rounded-lg p-2 sm:p-3 bg-epoch-background/30 overflow-hidden"
                key={field.id}
              >
                <div className="flex flex-col sm:flex-row sm:justify-between sm:items-start gap-2 sm:gap-3 mb-2 sm:mb-3">
                  <div className="min-w-0 flex-1">
                    <h3 className="font-display font-bold text-epoch-primary text-xs sm:text-sm uppercase tracking-tight break-words">
                      {field.field_label}
                    </h3>
                    <p className="text-[9px] sm:text-[10px] text-epoch-primary/70 mt-0.5">
                      Campo:{" "}
                      <code className="bg-epoch-background/50 border border-border px-1 py-0.5 rounded text-epoch-primary/80 font-display text-[9px]">
                        {field.field_key}
                      </code>
                      {field.is_array && (
                        <Badge
                          className="ml-1.5 rounded text-[8px] font-display font-bold uppercase tracking-wider"
                          variant="secondary"
                        >
                          Múltiples valores
                        </Badge>
                      )}
                    </p>
                  </div>
                  <Button
                    className="flex items-center gap-1.5 h-8 px-2 sm:px-3 rounded-lg border-border font-display font-bold text-[9px] sm:text-[10px] tracking-widest uppercase w-full sm:w-auto shrink-0"
                    size="sm"
                    onClick={() => openAddDialog(field)}
                  >
                    <Plus className="h-3.5 w-3.5" />
                    Agregar Opción
                  </Button>
                </div>

                <div className="space-y-1.5">
                  {field.values && field.values.length > 0 ? (
                    field.values.map((value) => (
                      <div
                        className={`flex items-center justify-between gap-2 p-2 sm:p-2.5 rounded-lg border border-border overflow-hidden min-w-0 ${
                          !value.is_active
                            ? "bg-epoch-background/20 opacity-60"
                            : "bg-epoch-background/40"
                        }`}
                        key={value.id}
                      >
                        <div className="flex items-center gap-1.5 sm:gap-2 flex-1 min-w-0 overflow-hidden">
                          <GripVertical className="h-3.5 w-3.5 text-epoch-primary/50 shrink-0" />
                          <span className="font-display font-bold text-epoch-primary text-[10px] sm:text-xs uppercase tracking-tight truncate">
                            {value.label}
                          </span>
                          <code className="text-[8px] sm:text-[9px] bg-epoch-background/60 border border-border px-1 py-0.5 rounded text-epoch-primary/80 font-display shrink-0 max-w-[80px] sm:max-w-none truncate">
                            {value.value}
                          </code>
                          {value.is_default && (
                            <Badge className="text-[7px] sm:text-[8px] font-display font-bold uppercase tracking-wider rounded shrink-0">
                              Por defecto
                            </Badge>
                          )}
                          {!value.is_active && (
                            <Badge
                              className="text-[7px] sm:text-[8px] font-display font-bold uppercase rounded shrink-0"
                              variant="secondary"
                            >
                              Inactivo
                            </Badge>
                          )}
                        </div>
                        <div className="flex items-center gap-0.5 sm:gap-1 shrink-0">
                          <Button
                            className="text-epoch-primary/70 hover:text-epoch-primary hover:bg-epoch-primary/10 rounded h-7 w-7 p-0 min-w-7"
                            size="sm"
                            title={value.is_active ? "Desactivar" : "Activar"}
                            variant="ghost"
                            onClick={() => handleToggleValueActive(value)}
                          >
                            {value.is_active ? (
                              <Eye className="h-3.5 w-3.5" />
                            ) : (
                              <EyeOff className="h-3.5 w-3.5" />
                            )}
                          </Button>
                          <Button
                            className="text-epoch-primary/70 hover:text-epoch-primary hover:bg-epoch-primary/10 rounded h-7 w-7 p-0 min-w-7"
                            size="sm"
                            title="Editar"
                            variant="ghost"
                            onClick={() => openEditDialog(value)}
                          >
                            <Edit2 className="h-3.5 w-3.5" />
                          </Button>
                          <Button
                            className="text-red-600 hover:text-red-700 hover:bg-red-500/10 rounded h-7 w-7 p-0 min-w-7"
                            size="sm"
                            title="Eliminar"
                            variant="ghost"
                            onClick={() => handleDeleteValue(value)}
                          >
                            <Trash2 className="h-3.5 w-3.5" />
                          </Button>
                        </div>
                      </div>
                    ))
                  ) : (
                    <p className="text-epoch-primary/70 text-[9px] sm:text-[10px] py-2">
                      No hay opciones configuradas
                    </p>
                  )}
                </div>
              </div>
            ))
          )}
        </CardContent>
      </Card>

      <AddOptionValueDialog
        fieldLabel={selectedField?.field_label}
        isDefault={newValue.is_default}
        label={newValue.label}
        open={showAddValueDialog}
        value={newValue.value}
        onDefaultChange={(d) => setNewValue({ ...newValue, is_default: d })}
        onLabelChange={(l) => setNewValue({ ...newValue, label: l })}
        onOpenChange={setShowAddValueDialog}
        onSave={handleAddValue}
        onValueChange={(v) => setNewValue({ ...newValue, value: v })}
      />

      <EditOptionValueDialog
        editingLabel={editingValue?.label}
        isDefault={newValue.is_default}
        label={newValue.label}
        open={showEditValueDialog}
        value={newValue.value}
        onDefaultChange={(d) => setNewValue({ ...newValue, is_default: d })}
        onLabelChange={(l) => setNewValue({ ...newValue, label: l })}
        onOpenChange={setShowEditValueDialog}
        onSave={handleEditValue}
      />
    </div>
  );
}

"use client";

import { Settings } from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { appLogger } from '@/lib/logger';

import { SystemConfig as SystemConfigType } from "../hooks/useSystemConfig";
import ConfigItem from "./_components/ConfigItem";
import OrganizationInfoCard from "./_components/OrganizationInfoCard";
import SystemConfigCategoryCards from "./SystemConfigCategoryCards";
import SystemConfigFilters from "./SystemConfigFilters";
import {
  CATEGORY_NAMES,
  EXCLUDED_CATEGORIES,
  getCategoryIcon,
  getContactPlaceholder,
  REDUNDANCY_KEYS,
} from "./systemConfigHelpers";
import PrescriptionsConfig from "./SystemConfigPrescriptions";

interface SystemConfigProps {
  configs: SystemConfigType[];
  onUpdateConfig: (key: string, value: unknown) => Promise<void>;
  isUpdating?: boolean;
  configScope?: "global" | "branch";
  onConfigScopeChange?: (scope: "global" | "branch") => void;
  currentBranchId?: string | null;
  hasMultipleBranches?: boolean;
}

/**
 * UI de configuración del sistema por categorías.
 * Muestra system_config con filtros, scope global/branch, e información de la óptica.
 *
 * @param props.configs - Lista de configuraciones a mostrar
 * @param props.onUpdateConfig - Callback para guardar una config por clave
 * @param props.configScope - "global" (todas sucursales) o "branch" (sucursal actual)
 * @param props.onConfigScopeChange - Callback al cambiar scope (solo si hasMultipleBranches)
 */
export default function SystemConfig({
  configs,
  onUpdateConfig,
  isUpdating = false,
  configScope = "global",
  onConfigScopeChange,
  currentBranchId,
  hasMultipleBranches = false,
}: SystemConfigProps) {
  const [categoryFilter, setCategoryFilter] = useState("all");
  const [showSensitive, setShowSensitive] = useState(false);

  // Local state for config values (to prevent page reload on input)
  const [localConfigValues, setLocalConfigValues] = useState<
    Record<string, unknown>
  >({});
  const [savingConfigKeys, setSavingConfigKeys] = useState<Set<string>>(
    new Set(),
  );

  const filteredConfigs = useMemo(() => {
    return configs.filter((config) => {
      if (EXCLUDED_CATEGORIES.includes(config.category)) return false;
      if (REDUNDANCY_KEYS.includes(config.config_key)) return false;

      if (categoryFilter !== "all" && config.category !== categoryFilter)
        return false;
      if (config.is_sensitive && !showSensitive) return false;
      return true;
    });
  }, [configs, categoryFilter, showSensitive]);

  const configsByCategory = useMemo(() => {
    return filteredConfigs.reduce((acc: unknown, config) => {
      if (!acc[config.category]) {
        acc[config.category] = [];
      }
      acc[config.category].push(config);
      return acc;
    }, {});
  }, [filteredConfigs]);

  const uniqueCategories = Array.from(
    new Set(
      configs
        .filter((c) => !EXCLUDED_CATEGORIES.includes(c.category))
        .map((c) => c.category),
    ),
  );

  // Initialize local config values from props
  useEffect(() => {
    const initialValues: Record<string, unknown> = {};
    configs.forEach((config) => {
      initialValues[config.config_key] = config.config_value;
    });
    // Default for prescription_expiration_months when not in DB (before migration)
    if (
      !configs.some((c) => c.config_key === "prescription_expiration_months")
    ) {
      initialValues["prescription_expiration_months"] = 6;
    }
    setLocalConfigValues(initialValues);
  }, [configs]);

  // Handle save config
  const handleSaveConfig = async (configKey: string) => {
    const value = localConfigValues[configKey];
    if (value === undefined) return;

    try {
      setSavingConfigKeys((prev) => new Set(prev).add(configKey));
      await onUpdateConfig(configKey, value);
      toast.success("Configuración guardada correctamente");
    } catch (error) {
      appLogger.error("Error saving config:", error);
      toast.error("Error al guardar la configuración");
    } finally {
      setSavingConfigKeys((prev) => {
        const newSet = new Set(prev);
        newSet.delete(configKey);
        return newSet;
      });
    }
  };

  return (
    <div className="space-y-4 sm:space-y-6">
      {/* Header con información */}
      <Card className="rounded-xl border border-border">
        <CardHeader className="p-4 sm:p-6 pb-0">
          <CardTitle className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2 font-display text-epoch-primary text-base sm:text-lg">
            <div className="flex items-center">
              <Settings className="h-4 w-4 sm:h-5 sm:w-5 mr-2 shrink-0" />
              Configuración del Sistema
            </div>
            <Badge className="text-[10px] sm:text-xs w-fit" variant="outline">
              {configs.length}{" "}
              {configs.length === 1 ? "configuración" : "configuraciones"}
            </Badge>
          </CardTitle>
        </CardHeader>
        <CardContent className="p-4 sm:p-6 pt-4">
          <p className="text-xs sm:text-sm text-epoch-primary/80">
            Gestiona las configuraciones del sistema. Usa el botón
            &quot;Guardar&quot; para aplicar los cambios.
          </p>
        </CardContent>
      </Card>

      <SystemConfigFilters
        categoryFilter={categoryFilter}
        categoryNames={CATEGORY_NAMES}
        configScope={configScope}
        hasMultipleBranches={hasMultipleBranches}
        showSensitive={showSensitive}
        uniqueCategories={uniqueCategories}
        onCategoryFilterChange={setCategoryFilter}
        onConfigScopeChange={onConfigScopeChange}
        onToggleSensitive={() => setShowSensitive(!showSensitive)}
      />

      {categoryFilter === "all" || categoryFilter === "general" ? (
        <OrganizationInfoCard />
      ) : null}

      {/* Contacto - siempre antes de Recetas */}
      {configsByCategory.contact &&
        (categoryFilter === "all" || categoryFilter === "contact") &&
        (() => {
          const Icon = getCategoryIcon("contact");
          const categoryConfigs =
            configsByCategory.contact as SystemConfigType[];
          return (
            <Card className="rounded-xl border border-border" key="contact">
              <CardHeader className="p-4 sm:p-6 pb-0">
                <CardTitle className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2 font-display text-epoch-primary text-base sm:text-lg">
                  <div className="flex items-center">
                    <Icon className="h-4 w-4 sm:h-5 sm:w-5 mr-2 shrink-0" />
                    {CATEGORY_NAMES.contact}
                  </div>
                  <Badge
                    className="text-[10px] sm:text-xs w-fit"
                    variant="default"
                  >
                    {categoryConfigs.length}{" "}
                    {categoryConfigs.length === 1
                      ? "configuración"
                      : "configuraciones"}
                  </Badge>
                </CardTitle>
              </CardHeader>
              <CardContent className="p-4 sm:p-6 pt-4">
                <div className="space-y-3 sm:space-y-4">
                  {categoryConfigs.map((config) => {
                    const localValue = localConfigValues[config.config_key];
                    const hasChanges = localValue !== config.config_value;
                    const isSaving = savingConfigKeys.has(config.config_key);
                    return (
                      <ConfigItem
                        config={config}
                        hasChanges={hasChanges}
                        isSaving={isSaving}
                        isUpdating={isUpdating}
                        key={config.id}
                        localValue={localValue}
                        placeholder={getContactPlaceholder(config.config_key)}
                        onSave={handleSaveConfig}
                        onValueChange={(key, value) =>
                          setLocalConfigValues((prev) => ({
                            ...prev,
                            [key]: value,
                          }))
                        }
                      />
                    );
                  })}
                </div>
              </CardContent>
            </Card>
          );
        })()}

      {categoryFilter === "all" || categoryFilter === "prescriptions" ? (
        <PrescriptionsConfig
          hasChanges={
            localConfigValues["prescription_expiration_months"] !==
              configs.find(
                (c) => c.config_key === "prescription_expiration_months",
              )?.config_value &&
            !!configs.find(
              (c) => c.config_key === "prescription_expiration_months",
            )
          }
          isSaving={savingConfigKeys.has("prescription_expiration_months")}
          isUpdating={isUpdating}
          localValue={
            (localConfigValues["prescription_expiration_months"] as number) ??
            (configs.find(
              (c) => c.config_key === "prescription_expiration_months",
            )?.config_value as number) ??
            6
          }
          onSave={() => handleSaveConfig("prescription_expiration_months")}
          onValueChange={(value) =>
            setLocalConfigValues((prev) => ({
              ...prev,
              prescription_expiration_months: value,
            }))
          }
        />
      ) : null}

      <SystemConfigCategoryCards
        configsByCategory={configsByCategory}
        isUpdating={isUpdating}
        localConfigValues={localConfigValues}
        savingConfigKeys={savingConfigKeys}
        onSave={handleSaveConfig}
        onValueChange={(key, value) =>
          setLocalConfigValues((prev) => ({ ...prev, [key]: value }))
        }
      />
    </div>
  );
}

"use client";

import { Settings } from "lucide-react";

import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";

import type { SystemConfig as SystemConfigType } from "../hooks/useSystemConfig";
import ConfigItem from "./_components/ConfigItem";
import { CATEGORY_NAMES, getCategoryIcon } from "./systemConfigHelpers";

interface CategoryCardsProps {
  configsByCategory: Record<string, SystemConfigType[]>;
  localConfigValues: Record<string, unknown>;
  savingConfigKeys: Set<string>;
  isUpdating: boolean;
  onSave: (key: string) => void;
  onValueChange: (key: string, value: unknown) => void;
}

export default function SystemConfigCategoryCards({
  configsByCategory,
  localConfigValues,
  savingConfigKeys,
  isUpdating,
  onSave,
  onValueChange,
}: CategoryCardsProps) {
  const entries = Object.entries(configsByCategory).filter(
    ([category]) => !["contact", "prescriptions"].includes(category),
  );

  if (entries.length === 0) {
    return (
      <Card className="rounded-xl border border-border">
        <CardContent className="p-6 sm:p-12 text-center">
          <Settings className="h-10 w-10 sm:h-12 sm:w-12 text-epoch-primary/40 mx-auto mb-4 opacity-50" />
          <p className="text-epoch-primary/80">
            No se encontraron configuraciones con los filtros seleccionados
          </p>
        </CardContent>
      </Card>
    );
  }

  return entries.map(([category, categoryConfigs]) => {
    const Icon = getCategoryIcon(category);
    return (
      <Card className="rounded-xl border border-border" key={category}>
        <CardHeader className="p-4 sm:p-6 pb-0">
          <CardTitle className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2 font-display text-epoch-primary text-base sm:text-lg">
            <div className="flex items-center">
              <Icon className="h-4 w-4 sm:h-5 sm:w-5 mr-2 shrink-0" />
