"use client";

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";

export interface Backup {
  id: string;
  filename: string;
  size_mb: number;
  created_at: string;
}

export interface BackupResult {
  backup_id: string;
  backup_file: string;
  download_url: string | null;
  download_url_expires_at: string | null;
  tables_count: number;
  total_records: number;
  backup_size_mb: string;
  duration_seconds: string;
}

export interface RestoreResult {
  success: boolean;
  message: string;
  tables_restored: number;
  total_records_restored: number;
  duration_seconds: string;
  errors: number;
  restore_results?: Record<string, unknown>;
}

const fetchBackups = async (): Promise<Backup[]> => {
  const response = await fetch("/api/admin/system/backups");
  if (!response.ok) {
    // Silently fail if endpoint doesn't exist (403/404)
    if (response.status === 403 || response.status === 404) {
      return [];
    }
    throw new Error("Error al cargar backups");
  }
  const data = await response.json();
  return data.backups || [];
};

export function useBackups() {
  const queryClient = useQueryClient();

  const query = useQuery({
    queryKey: ["systemBackups"],
    queryFn: fetchBackups,
    staleTime: 2 * 60 * 1000, // 2 minutes
  });

  const createBackupMutation = useMutation({
    mutationFn: async (): Promise<BackupResult> => {
      const response = await fetch("/api/admin/system/maintenance", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ action: "backup_database" }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || "Error al crear backup");
      }

      const data = await response.json();
      return {
        backup_id: data.backup_id,
        backup_file: data.backup_file,
        download_url: data.download_url || null,
        download_url_expires_at: data.download_url_expires_at || null,
        tables_count: data.tables_count || 0,
        total_records: data.total_records || 0,
        backup_size_mb: data.backup_size_mb || "0",
        duration_seconds: data.duration_seconds || "0",
      };
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["systemBackups"] });
      toast.success("Backup creado exitosamente");
    },
    onError: (error: Error) => {
      toast.error(error.message || "Error al crear backup");
    },
  });

  const restoreBackupMutation = useMutation({
    mutationFn: async (backup: Backup): Promise<RestoreResult> => {
      const response = await fetch("/api/admin/system/backups", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          backup_filename: backup.filename,
          create_safety_backup: true,
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || "Error al restaurar backup");
      }

      const data = await response.json();
      toast.success(data.message || "Backup restaurado exitosamente");
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["systemBackups"] });
      queryClient.invalidateQueries({ queryKey: ["systemConfig"] });
      queryClient.invalidateQueries({ queryKey: ["systemHealth"] });
    },
    onError: (error: Error) => {
      toast.error(error.message || "Error al restaurar backup");
    },
  });

  const deleteBackupMutation = useMutation({
    mutationFn: async (backup: Backup): Promise<void> => {
      const response = await fetch(
        `/api/admin/system/backups?filename=${encodeURIComponent(backup.filename)}`,
        {
          method: "DELETE",
        },
      );

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || "Error al eliminar backup");
      }

      const data = await response.json();
      toast.success(data.message || "Backup eliminado exitosamente");
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["systemBackups"] });
    },
    onError: (error: Error) => {
      toast.error(error.message || "Error al eliminar backup");
    },
  });

  const getBackupDetailsMutation = useMutation({
    mutationFn: async (backup: Backup): Promise<BackupResult> => {
      const response = await fetch(
        `/api/admin/system/backups?filename=${encodeURIComponent(backup.filename)}&action=details`,
      );

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(
          errorData.error || "Error al cargar detalles del backup",
        );
      }

      const data = await response.json();
      return {
        backup_id: data.backup_id,
        backup_file: data.backup_file,
        download_url: data.download_url || null,
        download_url_expires_at: data.download_url_expires_at || null,
        tables_count: data.tables_count || 0,
        total_records: data.total_records || 0,
        backup_size_mb: data.backup_size_mb || "0",
        duration_seconds: "N/A",
      };
    },
    onError: (error: Error) => {
      toast.error(error.message || "Error al cargar detalles del backup");
    },
  });

  return {
    backups: query.data || [],
    isLoading: query.isLoading,
    error: query.error,
    refetch: query.refetch,
    createBackup: createBackupMutation.mutateAsync,
    restoreBackup: restoreBackupMutation.mutateAsync,
    deleteBackup: deleteBackupMutation.mutateAsync,
    getBackupDetails: getBackupDetailsMutation.mutateAsync,
    isCreating: createBackupMutation.isPending,
    isRestoring: restoreBackupMutation.isPending,
    isDeleting: deleteBackupMutation.isPending,
    isLoadingDetails: getBackupDetailsMutation.isPending,
  };
}

"use client";

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";

export interface SystemConfig {
  id: string;
  config_key: string;
  config_value: unknown;
  description?: string;
  category: string;
  is_public: boolean;
  is_sensitive: boolean;
  value_type: string;
  updated_at: string;
}

const fetchConfigs = async (
  branchId?: string | null,
): Promise<SystemConfig[]> => {
  const path = branchId
    ? `/api/admin/system/config?branch_id=${encodeURIComponent(branchId)}`
    : "/api/admin/system/config";
  const response = await fetch(path, {
    headers: branchId ? { "x-branch-id": branchId } : undefined,
  });
  if (!response.ok) {
    throw new Error("Failed to fetch system config");
  }
  const data = await response.json();
  return data.configs || [];
};

export interface UseSystemConfigOptions {
  /** When "branch", fetch/update config for this branch. When null/undefined, use org-level (all branches). */
  branchId?: string | null;
}

/**
 * Hook para obtener y actualizar la configuración del sistema.
 * Soporta scope global (org-level) o por sucursal según branchId.
 *
 * @param options - Opciones del hook
 * @param options.branchId - Si se proporciona, fetch/update aplica a la sucursal. Null = org-level (todas las sucursales).
 * @returns configs, isLoading, error, refetch, updateConfig, isUpdating
 */
export function useSystemConfig(options?: UseSystemConfigOptions) {
  const branchId = options?.branchId ?? null;
  const queryClient = useQueryClient();

  const query = useQuery({
    queryKey: ["systemConfig", branchId ?? "global"],
    queryFn: () => fetchConfigs(branchId ?? undefined),
    staleTime: 5 * 60 * 1000, // 5 minutes
  });

  const updateMutation = useMutation({
    mutationFn: async ({
      configKey,
      newValue,
    }: {
      configKey: string;
      newValue: unknown;
    }) => {
      const headers: Record<string, string> = {
        "Content-Type": "application/json",
      };
      if (branchId) {
        headers["x-branch-id"] = branchId;
      }
      const response = await fetch("/api/admin/system/config", {
        method: "PUT",
        headers,
        body: JSON.stringify({
          updates: [{ config_key: configKey, config_value: newValue }],
          branch_id: branchId || undefined,
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to update config");
      }

      const data = await response.json();
      const result = data.results[0];

      if (!result.success) {
        throw new Error(result.error);
      }

      return result;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["systemConfig"] });
      toast.success("Configuración actualizada exitosamente");
    },
    onError: (error: Error) => {
      toast.error(error.message || "Error al actualizar configuración");
    },
  });

  return {
    configs: query.data || [],
    isLoading: query.isLoading,
    error: query.error,
    refetch: query.refetch,
    updateConfig: async (key: string, value: unknown) => {
      await updateMutation.mutateAsync({ configKey: key, newValue: value });
    },
    isUpdating: updateMutation.isPending,
  };
}

"use client";

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";

export interface HealthMetric {
  id: string;
  metric_name: string;
  metric_value: number;
  metric_unit?: string;
  category: string;
  is_healthy: boolean;
  collected_at: string;
  threshold_warning?: number;
  threshold_critical?: number;
}

export interface HealthStatus {
  status: "healthy" | "warning" | "critical";
  warnings: number;
  criticals: number;
  warning_metrics: HealthMetric[];
  critical_metrics: HealthMetric[];
  last_check: number | null;
}

interface HealthResponse {
  latest: HealthMetric[];
  health_status: HealthStatus;
}

const fetchHealthMetrics = async (): Promise<HealthResponse> => {
  const response = await fetch("/api/admin/system/health");
  if (!response.ok) {
    throw new Error("Failed to fetch health metrics");
  }
  return response.json();
};

export function useSystemHealth() {
  const queryClient = useQueryClient();

  const query = useQuery({
    queryKey: ["systemHealth"],
    queryFn: fetchHealthMetrics,
    staleTime: 30 * 1000, // 30 seconds
  });

  const refreshMutation = useMutation({
    mutationFn: async () => {
      // First collect new metrics
      const collectResponse = await fetch("/api/admin/system/health", {
        method: "POST",
      });
      if (!collectResponse.ok) {
        const errorData = await collectResponse.json();
        throw new Error(errorData.error || "Failed to collect health metrics");
      }

      const collectData = await collectResponse.json();
      toast.success(
        `Métricas recolectadas: ${collectData.metrics_collected || 0} nuevas métricas`,
      );

      // Then fetch the updated metrics
      return fetchHealthMetrics();
    },
    onSuccess: (data) => {
      queryClient.setQueryData(["systemHealth"], data);
      queryClient.invalidateQueries({ queryKey: ["systemHealth"] });
    },
    onError: (error: Error) => {
      toast.error(error.message || "Error al actualizar métricas de salud");
    },
  });

  const clearMemoryMutation = useMutation({
    mutationFn: async () => {
      const response = await fetch("/api/admin/system/maintenance", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ action: "clear_memory" }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || "Error al limpiar memoria");
      }

      const data = await response.json();
      toast.success(data.message || "Memoria limpiada exitosamente");

      // Refresh health metrics to see updated memory usage
      return fetchHealthMetrics();
    },
    onSuccess: (data) => {
      queryClient.setQueryData(["systemHealth"], data);
      queryClient.invalidateQueries({ queryKey: ["systemHealth"] });
    },
    onError: (error: Error) => {
      toast.error(error.message || "Error al limpiar memoria");
    },
  });

  return {
    healthMetrics: query.data?.latest || [],
    healthStatus: query.data?.health_status || null,
    isLoading: query.isLoading,
    error: query.error,
    refetch: query.refetch,
    refreshHealth: refreshMutation.mutateAsync,
    clearMemory: clearMemoryMutation.mutateAsync,
    refreshing: refreshMutation.isPending,
    clearingMemory: clearMemoryMutation.isPending,
  };
}

