          </div>
        </CardContent>
      </Card>
    </TabsContent>
  );
}

"use client";

import { useState } from "react";
import { toast } from "sonner";

import { appLogger } from '@/lib/logger';
import { getBranchHeader } from "@/lib/utils/branch";

import type { BillingSettings, POSSettings } from "./types";

const DEFAULT_POS: POSSettings = {
  min_deposit_percent: 50,
  min_deposit_amount: null,
};

const DEFAULT_BILLING: BillingSettings = {
  branch_id: "",
  business_name: "",
  business_rut: "",
  business_address: "",
  business_phone: "",
  business_email: "",
  logo_url: "",
  header_text: "",
  footer_text: "",
  terms_and_conditions: "",
  default_document_type: "boleta",
  printer_type: "thermal",
  printer_width_mm: 80,
  printer_height_mm: 297,
};

export function usePOSBillingSettings(currentBranchId: string | null) {
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [posSettings, setPosSettings] = useState<POSSettings>(DEFAULT_POS);
  const [billingSettings, setBillingSettings] =
    useState<BillingSettings>(DEFAULT_BILLING);

  const fetchAllSettings = async () => {
    setLoading(true);
    try {
      const headers = { ...getBranchHeader(currentBranchId) };
      const posResponse = await fetch("/api/admin/pos/settings", {
        headers,
        credentials: "include",
      });
      if (posResponse.ok) {
        const posData = await posResponse.json();
        if (posData.settings) {
          setPosSettings({
            min_deposit_percent: posData.settings.min_deposit_percent || 50,
            min_deposit_amount: posData.settings.min_deposit_amount || null,
          });
        }
      }
      const billingResponse = await fetch("/api/admin/billing/settings", {
        headers,
        credentials: "include",
      });
      if (billingResponse.ok) {
        const billingData = await billingResponse.json();
        const settings = billingData.data ?? billingData.settings;
        if (settings) {
          setBillingSettings({
            ...settings,
            printer_type: settings.printer_type || "thermal",
            printer_width_mm: settings.printer_width_mm || 80,
            printer_height_mm: settings.printer_height_mm || 297,
          });
        }
      } else if (billingResponse.status !== 404) {
        const error = await billingResponse.json();
        toast.error(error.error || "Error al cargar configuración de boletas");
      }
    } catch (error: unknown) {
      appLogger.error("Error fetching settings:", error);
      toast.error("Error al cargar configuraciones");
    } finally {
      setLoading(false);
    }
  };

  const handleSavePOS = async (
    isGlobalView: boolean,
    isSuperAdmin: boolean,
  ) => {
    if (isGlobalView && !isSuperAdmin) {
      toast.error("Debe seleccionar una sucursal para configurar el POS");
      return;
    }
    if (isGlobalView) {
      const confirmGlobal = window.confirm(
        "¿Está seguro de que desea guardar esta configuración GLOBALMENTE?",
      );
      if (!confirmGlobal) return;
    }
    if (
      posSettings.min_deposit_percent < 0 ||
      posSettings.min_deposit_percent > 100
    ) {
      toast.error("El porcentaje de depósito debe estar entre 0 y 100");
      return;
    }
    if (posSettings.min_deposit_amount && posSettings.min_deposit_amount < 0) {
      toast.error("El monto mínimo de depósito debe ser positivo");
      return;
    }
    setSaving(true);
    try {
      const headers = {
        "Content-Type": "application/json",
        ...getBranchHeader(currentBranchId),
      };
      const response = await fetch("/api/admin/pos/settings", {
        method: "PUT",
        headers,
        credentials: "include",
        body: JSON.stringify({
          min_deposit_percent: posSettings.min_deposit_percent,
          min_deposit_amount: posSettings.min_deposit_amount,
        }),
      });
      if (response.ok) {
        toast.success("Configuración POS guardada exitosamente");
      } else {
        const error = await response.json();
        toast.error(error.error || "Error al guardar configuración POS");
      }
    } catch (error: unknown) {
      appLogger.error("Error saving POS settings:", error);
      toast.error("Error al guardar configuración POS");
    } finally {
      setSaving(false);
    }
  };

  const handleSaveBilling = async (
    isGlobalView: boolean,
    isSuperAdmin: boolean,
  ) => {
    if (isGlobalView && !isSuperAdmin) {
      toast.error("Debe seleccionar una sucursal para configurar las boletas");
      return;
    }
    if (isGlobalView) {
      const confirmGlobal = window.confirm(
        "¿Está seguro de que desea guardar esta configuración GLOBALMENTE?",
      );
      if (!confirmGlobal) return;
    }
    if (!billingSettings.business_name || !billingSettings.business_rut) {
      toast.error("Nombre y RUT de la empresa son requeridos");
      return;
    }
    setSaving(true);
    try {
      const headers = {
        "Content-Type": "application/json",
        ...getBranchHeader(currentBranchId),
      };
      const response = await fetch("/api/admin/billing/settings", {
        method: "PUT",
        headers,
        credentials: "include",
        body: JSON.stringify(billingSettings),
      });
      if (response.ok) {
        toast.success("Configuración de boletas guardada exitosamente");
        await fetchAllSettings();
      } else {
        const error = await response.json();
        toast.error(error.error || "Error al guardar configuración de boletas");
      }
    } catch (error: unknown) {
      appLogger.error("Error saving billing settings:", error);
      toast.error("Error al guardar configuración de boletas");
    } finally {
      setSaving(false);
    }
  };

  const handleReuseMainLogo = async () => {
    try {
      const response = await fetch("/api/admin/organizations/current");
      if (response.ok) {
        const data = await response.json();
        if (data.organization?.logo_url) {
          setBillingSettings((prev) => ({
            ...prev,
            logo_url: data.organization.logo_url,
          }));
          toast.success("Logo de la óptica copiado correctamente");
        } else {
          toast.error("No se ha configurado un logo para la óptica aún");
        }
      }
    } catch (error) {
      appLogger.error("Error fetching main logo:", error);
      toast.error("Error al obtener el logo de la óptica");
    }
  };

  const handlePrinterTypeChange = (type: string) => {
    const printerConfigs: Record<string, { width: number; height: number }> = {
      thermal: { width: 80, height: 297 },
      a4: { width: 210, height: 297 },
      letter: { width: 216, height: 279 },
    };
    const config = printerConfigs[type] || { width: 80, height: 297 };
    setBillingSettings((prev) => ({
      ...prev,
      printer_type: type as "thermal" | "a4" | "letter" | "custom",
      printer_width_mm: config.width,
      printer_height_mm: config.height,
    }));
  };

  return {
    posSettings,
    setPosSettings,
    billingSettings,
    setBillingSettings,
    loading,
    saving,
    fetchAllSettings,
    handleSavePOS,
    handleSaveBilling,
    handleReuseMainLogo,
    handlePrinterTypeChange,
  };
}

"use client";

import { RefreshCw, Trash2 } from "lucide-react";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";

interface WorkOrderDeleteDialogProps {
  deleteDialogOpen: boolean;
  setDeleteDialogOpen: (open: boolean) => void;
  handleDelete: () => void;
  deleting: boolean;
  workOrder: { quote?: unknown } | null;
}

export function WorkOrderDeleteDialog({
  deleteDialogOpen,
  setDeleteDialogOpen,
  handleDelete,
  deleting,
  workOrder,
}: WorkOrderDeleteDialogProps) {
  return (
    <Dialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>¿Eliminar trabajo?</DialogTitle>
          <DialogDescription>
            Esta acción no se puede deshacer. El trabajo será eliminado
            permanentemente de la base de datos.
            {workOrder?.quote ? (
              <span className="block mt-2 text-orange-600 font-medium">
                ⚠️ El presupuesto relacionado también será eliminado.
              </span>
            ) : null}
          </DialogDescription>
        </DialogHeader>
        <DialogFooter>
          <Button
            disabled={deleting}
            variant="outline"
            onClick={() => setDeleteDialogOpen(false)}
          >
            Cancelar
          </Button>
          <Button
            disabled={deleting}
            variant="destructive"
            onClick={handleDelete}
          >
            {deleting ? (
              <>
                <RefreshCw className="h-4 w-4 mr-2 animate-spin" />
                Eliminando...
              </>
            ) : (
              <>
                <Trash2 className="h-4 w-4 mr-2" />
                Eliminar
              </>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import {
  AlertCircle,
  ArrowLeft,
  CheckCircle,
  Factory,
  FileText,
  Package,
  Send,
  Truck,
  XCircle,
} from "lucide-react";
import { useRouter } from "next/navigation";

import { DeliveryDialog } from "@/components/admin/DeliveryDialog";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useWorkOrder } from "@/hooks/useWorkOrder";

import { WorkOrderDeleteDialog } from "./WorkOrderDeleteDialog";
import { WorkOrderDetailsTab } from "./WorkOrderDetailsTab";
import { WorkOrderHeader } from "./WorkOrderHeader";
import { WorkOrderHistoryTab } from "./WorkOrderHistoryTab";
import { WorkOrderOverviewTab } from "./WorkOrderOverviewTab";
import { WorkOrderPricingTab } from "./WorkOrderPricingTab";
import { WorkOrderTimeline } from "./WorkOrderTimeline";

/* Orchestrator — delegates to sub-components for individual sections */
export default function WorkOrderDetailContent() {
  const router = useRouter();

  const {
    workOrder,
    statusHistory,
    loading,
    updatingStatus,
    showStatusDialog,
    newStatus,
    statusDialogOpenedFromTimeline,
    statusNotes,
    labInfo,
    deleteDialogOpen,
    deleting,
    deliveryDialogOpen,
    delivering,
    deliveryError,
    setShowStatusDialog,
    setNewStatus,
    setStatusDialogOpenedFromTimeline,
    setStatusNotes,
    setLabInfo,
    setDeleteDialogOpen,
    setDeliveryDialogOpen,
    setDeliveryError,
    handleStatusUpdate,
    handleDeliver,
    handleDelete,
    handlePrint,
    getAllStatuses,
    getStatusLabel,
  } = useWorkOrder();

  const getStatusBadge = (status: string) => {
    const config: Record<
      string,
      { variant: unknown; label: string; icon: React.ElementType; color: string }
    > = {
      quote: {
        variant: "outline",
        label: "Presupuesto",
        icon: FileText,
        color: "text-gray-600",
      },
      ordered: {
        variant: "secondary",
        label: "Ordenado",
        icon: Package,
        color: "text-blue-600",
      },
      sent_to_lab: {
        variant: "default",
        label: "Enviado al Lab",
        icon: Send,
        color: "text-purple-600",
      },
      in_progress_lab: {
        variant: "default",
        label: "En Lab",
        icon: Factory,
        color: "text-orange-600",
      },
      ready_at_lab: {
        variant: "default",
        label: "Listo en Lab",
        icon: CheckCircle,
        color: "text-green-600",
      },
      received_from_lab: {
        variant: "secondary",
        label: "Recibido",
        icon: Truck,
        color: "text-blue-600",
      },
      mounted: {
        variant: "default",
        label: "Montado",
        icon: Package,
        color: "text-indigo-600",
      },
      quality_check: {
        variant: "secondary",
        label: "Control Calidad",
        icon: CheckCircle,
        color: "text-yellow-600",
      },
      ready_for_pickup: {
        variant: "default",
        label: "Listo para Retiro",
        icon: CheckCircle,
        color: "text-green-600",
      },
      delivered: {
        variant: "default",
        label: "Entregado",
        icon: CheckCircle,
        color: "text-green-600",
      },
      cancelled: {
        variant: "destructive",
        label: "Cancelado",
        icon: XCircle,
        color: "text-red-600",
      },
      returned: {
        variant: "destructive",
        label: "Devuelto",
        icon: AlertCircle,
        color: "text-red-600",
      },
    };

    const statusConfig = config[status] || {
      variant: "outline",
      label: status,
      icon: Package,
      color: "text-gray-600",
    };
    const Icon = statusConfig.icon;

    return (
      <Badge className="flex items-center gap-1" variant={statusConfig.variant}>
        <Icon className="h-3 w-3" />
        {statusConfig.label}
      </Badge>
    );
  };

  const getPaymentStatusBadge = (status: string) => {
    const config: Record<string, { variant: unknown; label: string }> = {
      pending: { variant: "outline", label: "Pendiente" },
      partial: { variant: "secondary", label: "Parcial" },
      paid: { variant: "default", label: "Pagado" },
      refunded: { variant: "destructive", label: "Reembolsado" },
    };

    const statusConfig = config[status] || {
      variant: "outline",
      label: status,
    };
    return <Badge variant={statusConfig.variant}>{statusConfig.label}</Badge>;
  };

  if (loading) {
    return (
      <div className="space-y-6">
        <div className="flex items-center space-x-4">
          <Button size="sm" variant="outline">
            <ArrowLeft className="h-4 w-4" />
          </Button>
          <div>
            <h1 className="text-3xl font-bold text-epoch-primary">
              Cargando...
            </h1>
          </div>
        </div>
      </div>
    );
  }

  if (!workOrder) {
    return (
      <div className="space-y-6">
        <div className="flex items-center space-x-4">
          <Button size="sm" variant="outline" onClick={() => router.back()}>
            <ArrowLeft className="h-4 w-4" />
          </Button>
          <div>
            <h1 className="text-3xl font-bold text-epoch-primary">
              Trabajo no encontrado
            </h1>
          </div>
        </div>
      </div>
    );
  }

  const customerName =
    workOrder.customer?.first_name && workOrder.customer?.last_name
      ? `${workOrder.customer.first_name} ${workOrder.customer.last_name}`
      : "Sin nombre";

  // Get all available statuses except the current one (for "Cambiar Estado" button)
  const availableStatuses = getAllStatuses().filter(
    (s) => s.value !== workOrder.status,
  );
  // When opened from timeline, show all statuses including current (for view/edit)
  const statusOptions = statusDialogOpenedFromTimeline
    ? getAllStatuses()
    : availableStatuses;

  return (
    <div className="space-y-6">
      <WorkOrderHeader
        customerName={customerName}
        workOrder={workOrder}
        workOrderNumber={workOrder.work_order_number}
        onBack={() => router.back()}
        onDelete={() => setDeleteDialogOpen(true)}
        onPrint={handlePrint}
      />

      <WorkOrderTimeline
        setDeliveryDialogOpen={setDeliveryDialogOpen}
        setNewStatus={setNewStatus}
        setShowStatusDialog={setShowStatusDialog}
        setStatusDialogOpenedFromTimeline={setStatusDialogOpenedFromTimeline}
        workOrder={workOrder}
      />

      {/* Main Content */}
      <Tabs className="space-y-6" defaultValue="overview">
        <TabsList>
          <TabsTrigger value="overview">Resumen</TabsTrigger>
          <TabsTrigger value="details">Detalles</TabsTrigger>
          <TabsTrigger value="pricing">Precios</TabsTrigger>
          <TabsTrigger value="history">Historial</TabsTrigger>
        </TabsList>

        <TabsContent className="space-y-6" value="overview">
          <WorkOrderOverviewTab
            customerName={customerName}
            getPaymentStatusBadge={getPaymentStatusBadge}
            workOrder={workOrder}
          />
        </TabsContent>

        <TabsContent className="space-y-6" value="details">
          <WorkOrderDetailsTab workOrder={workOrder} />
        </TabsContent>

        <TabsContent className="space-y-6" value="pricing">
          <WorkOrderPricingTab workOrder={workOrder} />
        </TabsContent>

        <TabsContent className="space-y-6" value="history">
          <WorkOrderHistoryTab
            currentStatus={workOrder.status}
            getStatusLabel={getStatusLabel}
            statusHistory={statusHistory}
          />
        </TabsContent>
      </Tabs>

      {/* Delete Confirmation Dialog */}
      <WorkOrderDeleteDialog
        deleteDialogOpen={deleteDialogOpen}
        deleting={deleting}
        handleDelete={handleDelete}
        setDeleteDialogOpen={setDeleteDialogOpen}
        workOrder={workOrder}
      />

      {/* Delivery Dialog with Balance Check */}
      <DeliveryDialog
        delivering={delivering}
        deliveryDialogOpen={deliveryDialogOpen}
        deliveryError={deliveryError}
        handleDeliver={handleDeliver}
        setDeliveryDialogOpen={setDeliveryDialogOpen}
        setDeliveryError={setDeliveryError}
        workOrder={workOrder}
      />
    </div>
  );
}

