} from "lucide-react";
import Link from "next/link";
import { useState } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { formatCurrency } from "@/lib/utils";

interface WorkOrder {
  id: string;
  work_order_number: string;
  customer: {
    id: string;
    first_name?: string;
    last_name?: string;
    email?: string;
  };
  frame_name?: string;
  lens_type?: string;
  lens_material?: string;
  status: string;
  lab_name?: string;
  total_amount: number;
  payment_status: string;
}

interface WorkOrderTableProps {
  workOrders: WorkOrder[];
  loading: boolean;
  currentPage: number;
  totalPages: number;
  filteredLength: number;
  totalWorkOrders: number;
  searchTerm: string;
  onPageChange: (page: number) => void;
  onDeleteClick: (id: string) => void;
  onPaymentStatusChange: (id: string, newStatus: string) => void;
}

const getStatusBadge = (status: string) => {
  const config: Record<
    string,
    { variant: unknown; label: string; icon: unknown; color: string }
  > = {
    quote: { variant: "outline", label: "Presupuesto", icon: FileText, color: "text-gray-600" },
    ordered: { variant: "secondary", label: "Ordenado", icon: Package, color: "text-blue-600" },
    sent_to_lab: { variant: "default", label: "Enviado al Lab", icon: Send, color: "text-purple-600" },
    received_from_lab: { variant: "secondary", label: "Recibido", icon: Truck, color: "text-blue-600" },
    mounted: { variant: "default", label: "Montado", icon: Package, color: "text-indigo-600" },
    quality_check: { variant: "secondary", label: "Control Calidad", icon: CheckCircle, color: "text-yellow-600" },
    ready_for_pickup: { variant: "default", label: "Listo para Retiro", icon: CheckCircle, color: "text-green-600" },
    delivered: { variant: "default", label: "Entregado", icon: CheckCircle, color: "text-green-600" },
    cancelled: { variant: "destructive", label: "Cancelado", icon: XCircle, color: "text-red-600" },
    returned: { variant: "destructive", label: "Devuelto", icon: AlertCircle, color: "text-red-600" },
  };

  const statusConfig = config[status] || {
    variant: "outline",
    label: status,
    icon: Package,
    color: "text-gray-600",
  };
  const Icon = statusConfig.icon as React.ElementType;

  return (
    <Badge className="flex items-center gap-1" variant={statusConfig.variant as "default" | "secondary" | "destructive" | "outline"}>
      <Icon className="h-3 w-3" />
      {statusConfig.label}
    </Badge>
  );
};

const getPaymentStatusBadge = (status: string) => {
  const config: Record<string, { variant: unknown; label: string }> = {
    pending: { variant: "outline", label: "Pendiente" },
    partial: { variant: "secondary", label: "Parcial" },
    paid: { variant: "default", label: "Pagado" },
    refunded: { variant: "destructive", label: "Reembolsado" },
  };

  const statusConfig = config[status] || { variant: "outline", label: status };
  return <Badge variant={statusConfig.variant as "default" | "secondary" | "destructive" | "outline"}>{statusConfig.label}</Badge>;
};

export function WorkOrderTable({
  workOrders,
  loading,
  currentPage,
  totalPages,
  filteredLength,
  totalWorkOrders,
  searchTerm,
  onPageChange,
  onDeleteClick,
  onPaymentStatusChange,
}: WorkOrderTableProps) {
  const [editingPaymentStatus, setEditingPaymentStatus] = useState<string | null>(null);
  const [updatingPaymentStatus, setUpdatingPaymentStatus] = useState<string | null>(null);

  const handlePaymentChange = async (workOrderId: string, newStatus: string) => {
    setUpdatingPaymentStatus(workOrderId);
    setEditingPaymentStatus(null);
    await onPaymentStatusChange(workOrderId, newStatus);
    setUpdatingPaymentStatus(null);
  };

  return (
    <Card className="bg-admin-bg-tertiary shadow-[0_1px_3px_rgba(0,0,0,0.3)]">
      <CardHeader>
        <CardTitle>Trabajos ({totalWorkOrders})</CardTitle>
      </CardHeader>
      <CardContent>
        {loading ? (
          <div className="text-center py-12">
            <RefreshCw className="h-8 w-8 animate-spin text-epoch-primary mx-auto mb-4" />
            <p className="text-admin-text-tertiary">Cargando trabajos...</p>
          </div>
        ) : filteredLength === 0 ? (
          <div className="text-center py-12">
            <Package className="h-12 w-12 text-admin-text-tertiary mx-auto mb-4" />
            <h3 className="text-lg font-semibold text-epoch-primary mb-2">
              No hay trabajos
            </h3>
            <p className="text-admin-text-tertiary mb-4">
              {searchTerm
                ? "No se encontraron trabajos que coincidan con la búsqueda"
                : "Los trabajos se crean automáticamente desde el POS al procesar una venta"}
            </p>
          </div>
        ) : (
          <>
            <div className="overflow-x-auto -mx-4 px-4 md:mx-0 md:px-0">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Número</TableHead>
                    <TableHead>Cliente</TableHead>
                    <TableHead>Marco</TableHead>
                    <TableHead>Lente</TableHead>
                    <TableHead>Laboratorio</TableHead>
                    <TableHead>Estado</TableHead>
                    <TableHead>Pago</TableHead>
                    <TableHead>Total</TableHead>
                    <TableHead>Acciones</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {workOrders.map((workOrder) => (
                    <TableRow key={workOrder.id}>
                      <TableCell className="font-medium">
                        {workOrder.work_order_number}
                      </TableCell>
                      <TableCell>
                        <div>
                          <div className="font-medium">
                            {workOrder.customer?.first_name || ""}{" "}
                            {workOrder.customer?.last_name || ""}
                          </div>
                          <div className="text-sm text-admin-text-tertiary">
                            {workOrder.customer?.email}
                          </div>
                        </div>
                      </TableCell>
                      <TableCell>{workOrder.frame_name || "-"}</TableCell>
                      <TableCell>
                        <div>
                          <div className="font-medium">
                            {workOrder.lens_type || "-"}
                          </div>
                          <div className="text-sm text-admin-text-tertiary">
                            {workOrder.lens_material || ""}
                          </div>
                        </div>
                      </TableCell>
                      <TableCell>
                        {workOrder.lab_name ? (
                          <div className="flex items-center gap-1">
                            <Factory className="h-3 w-3" />
                            <span className="text-sm">{workOrder.lab_name}</span>
                          </div>
                        ) : (
                          "-"
                        )}
                      </TableCell>
                      <TableCell>{getStatusBadge(workOrder.status)}</TableCell>
                      <TableCell>
                        {editingPaymentStatus === workOrder.id ? (
                          <div className="flex items-center gap-2">
                            <Select
                              disabled={updatingPaymentStatus === workOrder.id}
                              open={true}
                              value={workOrder.payment_status}
                              onOpenChange={(open) => {
                                if (!open) setEditingPaymentStatus(null);
                              }}
                              onValueChange={(value) => {
                                handlePaymentChange(workOrder.id, value);
                              }}
                            >
                              <SelectTrigger className="w-[140px] h-7">
                                <SelectValue />
                              </SelectTrigger>
                              <SelectContent>
                                <SelectItem value="pending">Pendiente</SelectItem>
                                <SelectItem value="partial">Parcial</SelectItem>
                                <SelectItem value="paid">Pagado</SelectItem>
                                <SelectItem value="refunded">Reembolsado</SelectItem>
                              </SelectContent>
                            </Select>
                            {updatingPaymentStatus === workOrder.id && (
                              <RefreshCw className="h-4 w-4 animate-spin text-epoch-primary" />
                            )}
                          </div>
                        ) : (
                          <div
                            className="cursor-pointer hover:opacity-80 transition-opacity inline-block group"
                            title="Haz clic para editar el estado de pago"
                            onClick={() => setEditingPaymentStatus(workOrder.id)}
                          >
                            <div className="flex items-center gap-1">
                              {getPaymentStatusBadge(workOrder.payment_status)}
                              <span className="opacity-0 group-hover:opacity-50 text-xs text-admin-text-tertiary">
                                ✎
                              </span>
                            </div>
                          </div>
                        )}
                      </TableCell>
                      <TableCell className="font-semibold text-admin-success">
                        {formatCurrency(workOrder.total_amount)}
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center gap-2">
                          <Link href={`/admin/work-orders/${workOrder.id}`}>
                            <Button size="sm" variant="outline">
                              <Eye className="h-4 w-4 mr-1" />
                              Ver
                            </Button>
                          </Link>
                          <Button
                            className="text-red-600 hover:text-red-700 hover:bg-red-50"
                            disabled={
                              workOrder.status === "delivered" ||
                              workOrder.payment_status === "paid" ||
                              workOrder.payment_status === "partial"
                            }
                            size="sm"
                            variant="outline"
                            onClick={() => onDeleteClick(workOrder.id)}
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>

            {/* Pagination */}
            {totalPages > 1 && (
              <div className="flex items-center justify-between mt-4">
                <div className="text-sm text-admin-text-tertiary">
                  Página {currentPage} de {totalPages}
                </div>
                <div className="flex gap-2">
                  <Button
                    disabled={currentPage === 1}
                    size="sm"
                    variant="outline"
                    onClick={() => onPageChange(Math.max(1, currentPage - 1))}
                  >
                    <ChevronLeft className="h-4 w-4" />
                  </Button>
                  <Button
                    disabled={currentPage === totalPages}
                    size="sm"
                    variant="outline"
                    onClick={() => onPageChange(Math.min(totalPages, currentPage + 1))}
                  >
                    <ChevronRight className="h-4 w-4" />
                  </Button>
                </div>
              </div>
            )}
          </>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import { useEffect, useState } from "react";
import { toast } from "sonner";

import { useBranch } from "@/hooks/useBranch";
import {
  extractDataFromResponse,
  extractPaginationFromResponse,
} from "@/lib/api/response-helpers";
import { appLogger } from '@/lib/logger';
import { getBranchHeader } from "@/lib/utils/branch";

import { DeleteWorkOrderDialog } from "./DeleteWorkOrderDialog";
import { WorkOrderFilters } from "./WorkOrderFilters";
import { WorkOrderStats } from "./WorkOrderStats";
import { WorkOrderTable } from "./WorkOrderTable";

interface WorkOrder {
  id: string;
  work_order_number: string;
  work_order_date: string;
  customer: {
    id: string;
    first_name?: string;
    last_name?: string;
    email?: string;
  };
  prescription?: unknown;
  frame_name?: string;
  lens_type?: string;
  lens_material?: string;
  status: string;
  lab_name?: string;
  total_amount: number;
  payment_status: string;
  created_at: string;
  ordered_at?: string;
  sent_to_lab_at?: string;
  lab_completed_at?: string;
  mounted_at?: string;
  ready_at?: string;
  delivered_at?: string;
}

export default function WorkOrdersContent() {
  const {
    currentBranchId,
    isSuperAdmin,
    branches,
    isLoading: branchLoading,
  } = useBranch();
  const [workOrders, setWorkOrders] = useState<WorkOrder[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [totalWorkOrders, setTotalWorkOrders] = useState(0);
  const workOrdersPerPage = 20;
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [workOrderToDelete, setWorkOrderToDelete] = useState<string | null>(
    null,
  );
  const [deleting, setDeleting] = useState(false);

  const isGlobalView = !currentBranchId && isSuperAdmin;

  useEffect(() => {
    if (!branchLoading) {
      fetchWorkOrders();
    }
  }, [currentPage, statusFilter, currentBranchId, branchLoading]);

  const fetchWorkOrders = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams({
        page: currentPage.toString(),
        limit: workOrdersPerPage.toString(),
        ...(statusFilter !== "all" && { status: statusFilter }),
      });

      const headers: HeadersInit = {
        ...getBranchHeader(currentBranchId),
      };

      const response = await fetch(`/api/admin/work-orders?${params}`, {
        headers,
      });
      if (!response.ok) {
        throw new Error("Failed to fetch work orders");
      }

      const data = await response.json();
      const pagination = extractPaginationFromResponse(data);
      setWorkOrders(extractDataFromResponse(data));
      setTotalPages(pagination.totalPages || 1);
      setTotalWorkOrders(pagination.total || 0);
    } catch (error) {
      appLogger.error("Error fetching work orders:", error);
      toast.error("Error al cargar trabajos");
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteClick = (workOrderId: string) => {
    setWorkOrderToDelete(workOrderId);
    setDeleteDialogOpen(true);
  };

  const handleDeleteConfirm = async () => {
    if (!workOrderToDelete) return;

    setDeleting(true);
    try {
      const response = await fetch(
        `/api/admin/work-orders/${workOrderToDelete}`,
        {
          method: "DELETE",
          credentials: "include",
        },
      );

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || "Error al eliminar trabajo");
      }

      toast.success("Trabajo eliminado exitosamente");
      setDeleteDialogOpen(false);
      setWorkOrderToDelete(null);
      fetchWorkOrders();
    } catch (error: unknown) {
      appLogger.error("Error deleting work order:", error);
      toast.error((error as Error).message || "Error al eliminar trabajo");
    } finally {
      setDeleting(false);
    }
  };

  const handlePaymentStatusChange = async (
    workOrderId: string,
    newStatus: string,
  ) => {
    try {
      const headers: HeadersInit = {
        "Content-Type": "application/json",
        ...getBranchHeader(currentBranchId),
      };

      const response = await fetch(`/api/admin/work-orders/${workOrderId}`, {
        method: "PUT",
        headers,
        body: JSON.stringify({
          payment_status: newStatus,
        }),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || "Error al actualizar estado de pago");
      }

      setWorkOrders((prev) =>
        prev.map((wo) =>
          wo.id === workOrderId ? { ...wo, payment_status: newStatus } : wo,
        ),
      );

      toast.success("Estado de pago actualizado");
    } catch (error: unknown) {
      appLogger.error("Error updating payment status:", error);
      toast.error((error as Error).message || "Error al actualizar estado de pago");
      fetchWorkOrders();
    }
  };

  const inLabCount = workOrders.filter((w) =>
    ["sent_to_lab", "in_progress_lab", "ready_at_lab"].includes(w.status),
  ).length;
  const readyForPickupCount = workOrders.filter(
    (w) => w.status === "ready_for_pickup",
  ).length;
  const deliveredCount = workOrders.filter(
    (w) => w.status === "delivered",
  ).length;

  const filteredWorkOrders = workOrders.filter((workOrder) => {
    if (searchTerm) {
      const searchLower = searchTerm.toLowerCase();
      return (
        workOrder.work_order_number.toLowerCase().includes(searchLower) ||
        workOrder.customer?.email?.toLowerCase().includes(searchLower) ||
        `${workOrder.customer?.first_name || ""} ${workOrder.customer?.last_name || ""}`
          .toLowerCase()
          .includes(searchLower) ||
        workOrder.frame_name?.toLowerCase().includes(searchLower) ||
        workOrder.lab_name?.toLowerCase().includes(searchLower)
      );
    }
    return true;
  });

  return (
    <div className="space-y-6 pb-20 lg:pb-0">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1
            className="text-2xl sm:text-3xl font-bold text-epoch-primary"
            data-tour="work-orders-header"
          >
            Trabajos
          </h1>
          <p className="text-sm text-admin-text-tertiary">
            {isGlobalView
              ? "Gestión de trabajos de laboratorio - Todas las sucursales"
              : "Gestión de trabajos de laboratorio"}
          </p>
        </div>
      </div>

      <WorkOrderStats
        deliveredCount={deliveredCount}
        inLabCount={inLabCount}
        readyForPickupCount={readyForPickupCount}
        totalWorkOrders={totalWorkOrders}
      />

      <WorkOrderFilters
        searchTerm={searchTerm}
        statusFilter={statusFilter}
        onSearchChange={setSearchTerm}
        onStatusChange={setStatusFilter}
      />

      <WorkOrderTable
        currentPage={currentPage}
        filteredLength={filteredWorkOrders.length}
        loading={loading}
        searchTerm={searchTerm}
        totalPages={totalPages}
        totalWorkOrders={totalWorkOrders}
        workOrders={filteredWorkOrders}
        onDeleteClick={handleDeleteClick}
        onPageChange={setCurrentPage}
        onPaymentStatusChange={handlePaymentStatusChange}
      />

      <DeleteWorkOrderDialog
        deleting={deleting}
        open={deleteDialogOpen}
        onCancel={() => {
          setDeleteDialogOpen(false);
          setWorkOrderToDelete(null);
        }}
        onDeleteConfirm={handleDeleteConfirm}
        onOpenChange={setDeleteDialogOpen}
      />
    </div>
  );
}

"use client";

import React, { useEffect, useState } from "react";

import { appLogger } from '@/lib/logger';
import { useTelemetry } from "@/lib/telemetry/hooks/use-telemetry";

interface DashboardData {
  overview: {
    totalUsers: number;
    activeUsers: number;
    totalEvents: number;
    avgSessionDuration: number;
  };
  trends: {
    dailyActiveUsers: Array<{ date: string; count: number }>;
    featureUsage: Array<{ feature: string; usage: number }>;
    performanceMetrics: Array<{
      metric: string;
      value: number;
      trend: "up" | "down";
    }>;
  };
  topFeatures: Array<{ name: string; usage: number; growth: number }>;
  errorRates: Array<{ type: string; rate: number; change: number }>;
}

export default function UsageAnalyticsDashboard() {
  const [dashboardData, setDashboardData] = useState<DashboardData | null>(
    null,
  );
  const [loading, setLoading] = useState(true);
  const [timeRange, setTimeRange] = useState("7d");
  const { trackFeatureUsage } = useTelemetry("UsageAnalyticsDashboard");

  useEffect(() => {
    // Track dashboard usage (only after component mounts)
    if (typeof window !== "undefined") {
      trackFeatureUsage("usage_dashboard_view", { timeRange });
    }
  }, [timeRange, trackFeatureUsage]);

  useEffect(() => {
    // Fetch dashboard data
    const fetchDashboardData = async () => {
      try {
        setLoading(true);
        const response = await fetch(
          `/api/telemetry/dashboard?days=${timeRange === "7d" ? 7 : timeRange === "30d" ? 30 : 90}`,
        );
        const data = await response.json();
        setDashboardData(data);
      } catch (error) {
        appLogger.error("Failed to fetch dashboard data:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchDashboardData();
  }, [timeRange]);

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600" />
      </div>
    );
  }

  if (!dashboardData && !loading) {
    return (
      <div className="p-6">
        <div className="bg-red-50 border border-red-200 rounded-lg p-4">
          <h3 className="text-red-800 font-medium">Error Loading Dashboard</h3>
          <p className="text-red-600 mt-1">
            Unable to fetch usage analytics data.
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 max-w-7xl mx-auto">
      <div className="mb-6">
        <h1 className="text-3xl font-bold text-gray-900">
          Usage Analytics Dashboard
        </h1>
        <p className="text-gray-600 mt-2">
          Monitor system performance and user behavior patterns
        </p>

        <div className="flex gap-2 mt-4">
          {["7d", "30d", "90d"].map((range) => (
            <button
              className={`px-4 py-2 rounded-lg ${
                timeRange === range
                  ? "bg-blue-600 text-white"
                  : "bg-gray-100 text-gray-700 hover:bg-gray-200"
              }`}
              key={range}
              onClick={() => setTimeRange(range)}
            >
              {range}
            </button>
          ))}
        </div>
      </div>

