import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import type {
  GetAdminRoleParams,
  GetAdminRoleResult,
} from "@/types/supabase-rpc";
import { createRootAdminClient } from "@/utils/supabase/root-admin";
import { createClient } from "@/utils/supabase/server";

// GET: Get branch access for an admin user
export const dynamic = "force-dynamic";
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params;
  try {
    const supabase = await createClient();
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    // Check if requester is super admin or admin
    const branchContext = await getBranchContext(request, user.id);
    const { data: adminRole } = (await supabase.rpc("get_admin_role", {
      user_id: user.id,
    } as GetAdminRoleParams)) as {
      data: GetAdminRoleResult | null;
      error: Error | null;
    };

    const isAdmin = adminRole === "admin" || adminRole === "super_admin";
    if (!branchContext.isSuperAdmin && !isAdmin) {
      return NextResponse.json(
        { error: "Only super admins and admins can view branch access" },
        { status: 403 },
      );
    }

    // Use service role so admins can view any user's branch access (RLS only allows viewing own)
    const supabaseServiceRole = createRootAdminClient();
    const { data: branchAccess, error } = await supabaseServiceRole
      .from("admin_branch_access")
      .select(
        `
        id,
        branch_id,
        role,
        is_primary,
        branches (
          id,
          name,
          code
        )
      `,
      )
      .eq("admin_user_id", id)
      .order("is_primary", { ascending: false });

    if (error) {
      logger.error("Error fetching branch access:", { error, adminUserId: id });
      return NextResponse.json(
        { error: "Failed to fetch branch access" },
        { status: 500 },
      );
    }

    return NextResponse.json({ branchAccess: branchAccess || [] });
  } catch (error: unknown) {
    logger.error("Error in GET branch access:", { error, adminUserId: id });
    return NextResponse.json(
      { error: error.message || "Internal server error" },
      { status: 500 },
    );
  }
}

// POST: Assign branch access to an admin user
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params;
  try {
    const body = await request.json();
    const { branch_id, role = "manager", is_primary = false } = body;

    const supabase = await createClient();
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    // Check if requester is super admin or admin
    const branchContext = await getBranchContext(request, user.id);
    const { data: adminRole } = (await supabase.rpc("get_admin_role", {
      user_id: user.id,
    } as GetAdminRoleParams)) as {
      data: GetAdminRoleResult | null;
      error: Error | null;
    };

    const isAdmin = adminRole === "admin" || adminRole === "super_admin";
    if (!branchContext.isSuperAdmin && !isAdmin) {
      return NextResponse.json(
        { error: "Only super admins and admins can assign branch access" },
        { status: 403 },
      );
    }

    // Only super admins can assign super admin access (branch_id = null)
    if (branch_id === null && !branchContext.isSuperAdmin) {
      return NextResponse.json(
        { error: "Only super admins can assign super admin access" },
        { status: 403 },
      );
    }

    // Validate input
    if (branch_id === undefined) {
      return NextResponse.json(
        { error: "branch_id is required (use null for super admin)" },
        { status: 400 },
      );
    }

    // Check if admin user exists
    const { data: adminUser } = await supabase
      .from("admin_users")
      .select("id")
      .eq("id", id)
      .single();

    if (!adminUser) {
      return NextResponse.json(
        { error: "Admin user not found" },
        { status: 404 },
      );
    }

    // Use service role for writes (RLS on admin_branch_access only allows super_admin to INSERT/UPDATE/DELETE)
    const supabaseServiceRole = createRootAdminClient();

    // If assigning super admin (branch_id = null), remove all other access
    if (branch_id === null) {
      await supabaseServiceRole
        .from("admin_branch_access")
        .delete()
        .eq("admin_user_id", id);

      const { data: newAccess, error: insertError } = await supabaseServiceRole
        .from("admin_branch_access")
        .insert({
          admin_user_id: id,
          branch_id: null,
          role: "manager",
          is_primary: true,
        })
        .select()
        .single();

      if (insertError) {
        logger.error("Error creating super admin access:", {
          error: insertError,
          adminUserId: id,
        });
        return NextResponse.json(
          {
            error: "Failed to assign super admin access",
            details: insertError.message,
          },
          { status: 500 },
        );
      }

      return NextResponse.json({ branchAccess: newAccess });
    }

    // Validate branch exists
    const { data: branch } = await supabase
      .from("branches")
      .select("id")
      .eq("id", branch_id)
      .single();

    if (!branch) {
      return NextResponse.json({ error: "Branch not found" }, { status: 404 });
    }

    // If setting as primary, unset other primary flags
    if (is_primary) {
      await supabaseServiceRole
        .from("admin_branch_access")
        .update({ is_primary: false })
        .eq("admin_user_id", id);
    }

    // Upsert branch access (service role bypasses RLS)
    const { data: branchAccess, error: upsertError } = await supabaseServiceRole
      .from("admin_branch_access")
      .upsert(
        {
          admin_user_id: id,
          branch_id,
          role,
          is_primary,
        },
        {
          onConflict: "admin_user_id,branch_id",
        },
      )
      .select()
      .single();

    if (upsertError) {
      logger.error("Error assigning branch access:", {
        error: upsertError,
        adminUserId: id,
        branchId: branch_id,
      });
      return NextResponse.json(
        {
          error: "Failed to assign branch access",
          details: upsertError.message,
        },
        { status: 500 },
      );
    }

    return NextResponse.json({ branchAccess });
  } catch (error: unknown) {
    logger.error("Error in POST branch access:", { error, adminUserId: id });
    return NextResponse.json(
      { error: error.message || "Internal server error" },
      { status: 500 },
    );
  }
}

// DELETE: Remove branch access from an admin user
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params;
  try {
    const { searchParams } = new URL(request.url);
    const branch_id = searchParams.get("branch_id");

    const supabase = await createClient();
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    // Check if requester is super admin or admin
    const branchContext = await getBranchContext(request, user.id);
    const { data: adminRole } = (await supabase.rpc("get_admin_role", {
      user_id: user.id,
    } as GetAdminRoleParams)) as {
      data: GetAdminRoleResult | null;
      error: Error | null;
    };

    const isAdmin = adminRole === "admin" || adminRole === "super_admin";
    if (!branchContext.isSuperAdmin && !isAdmin) {
      return NextResponse.json(
        { error: "Only super admins and admins can remove branch access" },
        { status: 403 },
      );
    }

    // Only super admins can remove super admin access (branch_id = null)
    if (branch_id === "null" && !branchContext.isSuperAdmin) {
      return NextResponse.json(
        { error: "Only super admins can remove super admin access" },
        { status: 403 },
      );
    }

    if (!branch_id) {
      return NextResponse.json(
        { error: "branch_id is required" },
        { status: 400 },
      );
    }

    const supabaseServiceRole = createRootAdminClient();
    const deleteQuery = supabaseServiceRole
      .from("admin_branch_access")
      .delete()
      .eq("admin_user_id", id);

    const { error: deleteError } =
      branch_id === "null"
        ? await deleteQuery.is("branch_id", null)
        : await deleteQuery.eq("branch_id", branch_id);

    if (deleteError) {
      logger.error("Error removing branch access:", {
        error: deleteError,
        adminUserId: id,
        branchId: branch_id,
      });
      return NextResponse.json(
        { error: "Failed to remove branch access" },
        { status: 500 },
      );
    }

    return NextResponse.json({ success: true });
  } catch (error: unknown) {
    logger.error("Error in DELETE branch access:", { error, adminUserId: id });
    return NextResponse.json(
      { error: error.message || "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import { createClient } from "@/utils/supabase/server";

import { checkAuth, getActivityByDay, getAdminRole, getMostFrequentActions, verifyAdmin } from "../_helpers/adminUserHelpers";

export const dynamic = "force-dynamic";

export async function GET(request: NextRequest, { params }: { params: { id: string } }) {
  try {
    const supabase = await createClient();
    const auth = await checkAuth(supabase);
    if (auth.error) return auth.error;
    const adminCheck = await verifyAdmin(supabase, auth.user!.id);
    if (adminCheck) return adminCheck;

    const { data: adminUser, error: adminError } = await supabase.from("admin_users").select("id, email, role, permissions, is_active, last_login, created_at, updated_at, admin_branch_access (id, branch_id, role, is_primary, branches (id, name, code))").eq("id", params.id).single();
    if (adminError || !adminUser) return NextResponse.json({ error: "Admin user not found" }, { status: 404 });

    const { data: profile } = await supabase.from("profiles").select("first_name, last_name, phone").eq("id", params.id).single();
    const branchAccess = adminUser.admin_branch_access || [];
    const branches = branchAccess.filter((a: unknown) => a.branch_id !== null).map((a: unknown) => ({ id: a.branch_id, name: a.branches?.name || "N/A", code: a.branches?.code || "N/A", is_primary: a.is_primary }));

    const { data: activityHistory } = await supabase.from("admin_activity_log").select("action, resource_type, resource_id, details, created_at").eq("admin_user_id", params.id).order("created_at", { ascending: false }).limit(50);

    const now = new Date();
    const recentActivity = (activityHistory || []).filter((a: unknown) => new Date(a.created_at) >= new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000));
    const weeklyActivity = (activityHistory || []).filter((a: unknown) => new Date(a.created_at) >= new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000));

    return NextResponse.json({
      adminUser: {
        ...adminUser, profiles: profile || null, is_super_admin: branchAccess.some((a: unknown) => a.branch_id === null), branches,
        activityHistory: activityHistory || [],
        analytics: { totalActions: activityHistory?.length || 0, actionsLast30Days: recentActivity.length, actionsLast7Days: weeklyActivity.length, lastActivity: adminUser.last_login, activityByDay: getActivityByDay(recentActivity, now), mostFrequentActions: getMostFrequentActions(recentActivity), activityCount30Days: recentActivity.length, fullName: profile ? `${profile.first_name || ""} ${profile.last_name || ""}`.trim() || adminUser.email : adminUser.email },
      },
    });
  } catch (error) {
    logger.error("Error in admin user detail API", error);
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

export async function PUT(request: NextRequest, { params }: { params: { id: string } }) {
  try {
    const supabase = await createClient();
    const auth = await checkAuth(supabase);
    if (auth.error) return auth.error;
    const adminCheck = await verifyAdmin(supabase, auth.user!.id);
    if (adminCheck) return adminCheck;

    const body = await request.json();
    const { role, permissions, is_active } = body;
    const allowedRoles = ["admin", "super_admin", "employee", "vendedor"];
    const branchContext = await getBranchContext(request, auth.user!.id);
    const isRequesterSuperAdmin = branchContext.isSuperAdmin || (await getAdminRole(supabase, auth.user!.id)) === "super_admin";

    if (is_active !== undefined && !isRequesterSuperAdmin) return NextResponse.json({ error: "Solo los super administradores pueden activar o desactivar otros administradores" }, { status: 403 });
    if (auth.user!.id === params.id && role && role !== "super_admin") return NextResponse.json({ error: "No puedes cambiar tu propio rol de Super Administrador" }, { status: 400 });
    if (auth.user!.id === params.id && is_active === false) return NextResponse.json({ error: "Cannot deactivate your own account" }, { status: 400 });
    if (role !== undefined) {
      if (!allowedRoles.includes(role)) return NextResponse.json({ error: `Rol inválido. Permitidos: ${allowedRoles.join(", ")}` }, { status: 400 });
      if (role === "super_admin" && !isRequesterSuperAdmin) return NextResponse.json({ error: "Solo los super administradores pueden asignar rol Super Administrador" }, { status: 403 });
    }

    const { data: currentAdmin } = await supabase.from("admin_users").select("email, role, organization_id").eq("id", params.id).single();
    if (!currentAdmin) return NextResponse.json({ error: "Admin user not found" }, { status: 404 });
    const { data: requester } = await supabase.from("admin_users").select("organization_id, role").eq("id", auth.user!.id).single();
    if (!["root", "dev"].includes(requester?.role || "") && requester?.organization_id !== currentAdmin.organization_id) return NextResponse.json({ error: "No tienes permiso para modificar usuarios de otra organización" }, { status: 403 });

    const updateData: unknown = { updated_at: new Date().toISOString() };
    if (role !== undefined) updateData.role = role;
    if (permissions !== undefined) updateData.permissions = permissions;
    if (is_active !== undefined) updateData.is_active = is_active;

    const { data: updatedAdmin, error: updateError } = await supabase.from("admin_users").update(updateData).eq("id", params.id).select("id, email, role, permissions, is_active, last_login, created_at, updated_at").single();
    if (updateError) { logger.error("Error updating admin user", updateError); return NextResponse.json({ error: "Failed to update admin user" }, { status: 500 }); }

    await supabase.rpc("log_admin_activity", { action: "update_admin_user", resource_type: "admin_user", resource_id: params.id, details: { target_admin_email: currentAdmin.email, changes: Object.keys(updateData).filter((k) => k !== "updated_at"), previous_role: currentAdmin.role, new_role: role, updated_by: auth.user!.email } });
    return NextResponse.json({ adminUser: updatedAdmin });
  } catch (error) {
    logger.error("Error in admin user update API", error);
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

export async function DELETE(request: NextRequest, { params }: { params: { id: string } }) {
  try {
    const supabase = await createClient();
    const auth = await checkAuth(supabase);
    if (auth.error) return auth.error;
    const adminCheck = await verifyAdmin(supabase, auth.user!.id);
    if (adminCheck) return adminCheck;

    if (auth.user!.id === params.id) return NextResponse.json({ error: "Cannot delete your own admin account" }, { status: 400 });

    const { data: adminUser } = await supabase.from("admin_users").select("email, role, organization_id").eq("id", params.id).single();
    if (!adminUser) return NextResponse.json({ error: "Admin user not found" }, { status: 404 });
    const { data: requester } = await supabase.from("admin_users").select("organization_id, role").eq("id", auth.user!.id).single();
    if (!["root", "dev"].includes(requester?.role || "") && requester?.organization_id !== adminUser.organization_id) return NextResponse.json({ error: "No tienes permiso para eliminar usuarios de otra organización" }, { status: 403 });

    if (adminUser.organization_id) {
      const { count } = await supabase.from("admin_users").select("*", { count: "exact", head: true }).eq("organization_id", adminUser.organization_id).eq("is_active", true).in("role", ["admin", "super_admin"]);
      if ((count || 0) <= 1) return NextResponse.json({ error: "No se puede eliminar al último administrador. Debe quedar al menos un administrador activo en la organización." }, { status: 400 });
    }

    const { error: deleteError } = await supabase.from("admin_users").delete().eq("id", params.id);
    if (deleteError) { logger.error("Error deleting admin user", deleteError); return NextResponse.json({ error: "Failed to delete admin user" }, { status: 500 }); }

    await supabase.rpc("log_admin_activity", { action: "delete_admin_user", resource_type: "admin_user", resource_id: params.id, details: { deleted_admin_email: adminUser.email, deleted_role: adminUser.role, deleted_by: auth.user!.email } });
    return NextResponse.json({ success: true });
  } catch (error) {
    logger.error("Error in admin user delete API", error);
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";

import { getDefaultPermissions } from "@/lib/admin/permissions";
import { appLogger as logger } from "@/lib/logger";
import type {
  GetAdminRoleParams,
  GetAdminRoleResult,
} from "@/types/supabase-rpc";
import { createRootAdminClient } from "@/utils/supabase/root-admin";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";
export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const {
      email,
      password,
      firstName,
      lastName,
      role = "admin",
      branch_id,
    } = body;

    const supabase = await createClient();
    const supabaseServiceRole = createRootAdminClient();

    // Verificar autenticación
    const {
      data: { user: currentUser },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !currentUser) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    // Verificar que el usuario actual tiene permisos para crear usuarios
    const { data: adminRole } = (await supabase.rpc("get_admin_role", {
      user_id: currentUser.id,
    } as GetAdminRoleParams)) as {
      data: GetAdminRoleResult | null;
      error: Error | null;
    };

    // Verificar permisos según rol del usuario actual
    const { data: currentAdminUser } = await supabaseServiceRole
      .from("admin_users")
      .select("role, organization_id")
      .eq("id", currentUser.id)
      .single();

    const isRoot =
      currentAdminUser?.role === "root" || currentAdminUser?.role === "dev";
    const isSuperAdmin = currentAdminUser?.role === "super_admin";
    const isAdmin = adminRole === "admin";

    // Validar que el usuario tiene permisos para crear usuarios
    if (!isRoot && !isSuperAdmin && !isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    // Validar que el rol a crear es permitido
    // Root/dev puede crear cualquier rol
    // Super admin puede crear: admin, employee, vendedor, super_admin (de su org)
    // Admin puede crear: admin, employee, vendedor
    if (!isRoot) {
      const allowedRoles = isSuperAdmin
        ? ["admin", "employee", "vendedor", "super_admin"]
        : ["admin", "employee", "vendedor"];

      if (!allowedRoles.includes(role)) {
        return NextResponse.json(
          { error: `No tienes permisos para crear usuarios con rol ${role}` },
          { status: 403 },
        );
      }
    }

    // Obtener organization_id del usuario actual (excepto root/dev)
    let organizationId: string | null = null;
    if (!isRoot) {
      if (!currentAdminUser?.organization_id) {
        return NextResponse.json(
          { error: "No tienes una organización asignada" },
          { status: 400 },
        );
      }
      organizationId = currentAdminUser.organization_id;
    }
    // Root/dev puede crear usuarios sin organization_id (para otros root/dev)

    // Validar límite de usuarios del tier cuando se crea usuario en una organización
    if (organizationId) {
      const { validateTierLimit } = await import("@/lib/saas/tier-validator");
      const userLimit = await validateTierLimit(organizationId, "users");
      if (!userLimit.allowed) {
        return NextResponse.json(
          {
            error:
              userLimit.reason ??
              "Límite de usuarios alcanzado para tu plan. Considera actualizar tu suscripción.",
            code: "TIER_LIMIT",
            currentCount: userLimit.currentCount,
            maxAllowed: userLimit.maxAllowed,
          },
          { status: 403 },
        );
      }
    }

    // Validar inputs
    if (!email || !password) {
      return NextResponse.json(
        { error: "Email y contraseña son requeridos" },
        { status: 400 },
      );
    }

    if (password.length < 8) {
      return NextResponse.json(
        { error: "La contraseña debe tener al menos 8 caracteres" },
        { status: 400 },
      );
    }

    // Verificar si el usuario ya existe
    const { data: existingUser } = await supabaseServiceRole
      .from("profiles")
      .select("id, email")
      .eq("email", email)
      .maybeSingle();

    if (existingUser) {
      return NextResponse.json(
        {
          error:
            "El usuario ya existe. Usa la opción 'Crear Administrador' en su lugar.",
        },
        { status: 400 },
      );
    }

    // Crear usuario en auth.users usando service role
    const { data: newAuthUser, error: createAuthError } =
      await supabaseServiceRole.auth.admin.createUser({
        email,
        password,
        email_confirm: true, // Auto-confirmar email
        user_metadata: {
          first_name: firstName,
          last_name: lastName,
        },
      });

    if (createAuthError || !newAuthUser.user) {
      logger.error("Error creating auth user", {
        error: createAuthError,
        email,
        userId: currentUser.id,
      });
      return NextResponse.json(
        {
          error: "Error al crear usuario en el sistema de autenticación",
          details:
            createAuthError?.message || "Error desconocido al crear usuario",
        },
        { status: 500 },
      );
    }

    // Verificar si el perfil ya existe (puede ser creado por trigger on_auth_user_created)
    // Esperar un momento para que el trigger se ejecute si existe
    await new Promise((resolve) => setTimeout(resolve, 300));

    const { data: existingProfile } = await supabaseServiceRole
      .from("profiles")
      .select("id")
      .eq("id", newAuthUser.user.id)
      .maybeSingle();

    // Crear o actualizar perfil
    let profileError;
    if (existingProfile) {
      // El perfil ya existe (creado por trigger), actualizarlo
      const { error: updateError } = await supabaseServiceRole
        .from("profiles")
        .update({
          email,
          first_name: firstName,
          last_name: lastName,
        })
        .eq("id", newAuthUser.user.id);

      profileError = updateError;
    } else {
      // El perfil no existe, crearlo
      const { error: insertError } = await supabaseServiceRole
        .from("profiles")
        .insert({
          id: newAuthUser.user.id,
          email,
          first_name: firstName,
          last_name: lastName,
        });

      profileError = insertError;
    }

    if (profileError) {
      logger.error("Error creating/updating profile", {
        error: profileError,
        userId: newAuthUser.user.id,
        email,
        code: profileError.code,
        details: profileError.details,
        hint: profileError.hint,
        message: profileError.message,
      });
      // Intentar eliminar el usuario de auth si falla el perfil
      try {
        await supabaseServiceRole.auth.admin.deleteUser(newAuthUser.user.id);
      } catch (deleteError) {
        logger.warn(
          "Failed to cleanup auth user after profile error",
          deleteError,
        );
      }
      return NextResponse.json(
        {
          error: "Error al crear perfil del usuario",
          details:
            profileError.message ||
            profileError.hint ||
            profileError.details ||
            "Error desconocido al crear perfil",
        },
        { status: 500 },
      );
    }

    // Crear admin_user con organization_id heredado (o null para root/dev)
    const { data: newAdmin, error: adminError } = await supabaseServiceRole
      .from("admin_users")
      .insert({
        id: newAuthUser.user.id,
        email,
        role: role,
        permissions: getDefaultPermissions(role),
        is_active: true,
        organization_id: organizationId, // HEREDADO o null para root/dev
        created_by: currentUser.id,
      })
      .select()
      .single();

    if (adminError) {
      logger.error("Error creating admin user", {
        error: adminError,
        userId: newAuthUser.user.id,
        email,
        role,
        organizationId,
      });
      // Rollback: eliminar usuario y perfil
      try {
        await supabaseServiceRole.auth.admin.deleteUser(newAuthUser.user.id);
        await supabaseServiceRole
          .from("profiles")
          .delete()
          .eq("id", newAuthUser.user.id);
      } catch (rollbackError) {
        logger.warn("Failed to rollback user creation", rollbackError);
      }
      return NextResponse.json(
        {
          error: "Error al crear registro de administrador",
          details:
            adminError.message || "Error desconocido al crear administrador",
        },
        { status: 500 },
      );
    }

    // Asignación de sucursal cuando se proporciona branch_id
    if (branch_id && organizationId) {
      const branchId =
        typeof branch_id === "string" && branch_id.trim() !== ""
          ? branch_id.trim()
          : null;
      if (branchId) {
        const { data: branch, error: branchError } = await supabaseServiceRole
          .from("branches")
          .select("id, organization_id")
          .eq("id", branchId)
          .eq("organization_id", organizationId)
          .maybeSingle();

        if (branchError) {
          logger.error("Error checking branch", branchError);
          return NextResponse.json(
            {
              error: "Error al verificar la sucursal",
              details: branchError.message,
            },
            { status: 500 },
          );
        }
        if (!branch) {
          return NextResponse.json(
            {
              error:
                "La sucursal no existe o no pertenece a tu organización. Elige otra sucursal.",
            },
            { status: 400 },
          );
        }

        const { error: accessError } = await supabaseServiceRole
          .from("admin_branch_access")
          .insert({
            admin_user_id: newAdmin.id,
            branch_id: branchId,
            role:
              role === "employee" || role === "vendedor" ? "staff" : "manager",
            is_primary: true,
          });

        if (accessError) {
          logger.error(
            "Error assigning branch access on register",
            accessError,
          );
          return NextResponse.json(
            {
              error: "El usuario se creó pero no se pudo asignar la sucursal",
              details: accessError.message,
            },
            { status: 500 },
          );
        }
      }
    } else if (
      role !== "root" &&
      role !== "dev" &&
      role !== "super_admin" &&
      organizationId
    ) {
      // Si no hay branch_id y el rol requiere sucursal (admin, employee)
      // registrar pero sin acceso aún - el usuario puede asignar sucursal después
      logger.info(
        `User ${newAdmin.id} created without branch access. Can be assigned later.`,
      );
    }

    // Si es super_admin, crear acceso global (branch_id = null)
    if (role === "super_admin") {
      const { error: accessError } = await supabaseServiceRole
        .from("admin_branch_access")
        .insert({
          admin_user_id: newAdmin.id,
          branch_id: null,
          role: "manager",
          is_primary: true,
        });

      if (accessError) {
        logger.warn(
          "Error assigning super admin access (non-critical)",
          accessError,
        );
      }
    }

    // Log actividad
    try {
      await supabaseServiceRole.rpc("log_admin_activity", {
        action: "register_user_with_org",
        resource_type: "admin_user",
        resource_id: newAdmin.id,
        details: {
          new_user_email: email,
          role: role,
          organization_id: organizationId,
          branch_id: branch_id || null,
          created_by: currentUser.email,
        },
      });
    } catch (logError) {
      logger.warn("Error logging activity (non-critical)", logError);
    }

    return NextResponse.json({
      success: true,
      user: {
        id: newAdmin.id,
        email: newAdmin.email,
        role: newAdmin.role,
        organization_id: newAdmin.organization_id,
      },
    });
  } catch (error) {
    logger.error("Error in register user API", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { getDefaultPermissions } from "@/lib/admin/permissions";
import { getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import { createClient } from "@/utils/supabase/server";

import { checkAuth, verifyAdmin } from "./_helpers/adminUserHelpers";

export const dynamic = "force-dynamic";

export async function GET(request: NextRequest) {
  try {
    const supabase = await createClient();
    const auth = await checkAuth(supabase);
    if (auth.error) return auth.error;
    const adminCheck = await verifyAdmin(supabase, auth.user!.id);
    if (adminCheck) return adminCheck;

    const { searchParams } = new URL(request.url);
    const role = searchParams.get("role") || "";
    const status = searchParams.get("status") || "";
    const search = searchParams.get("search") || "";
    const limit = Math.min(Math.max(1, parseInt(searchParams.get("limit") || "20", 10)), 100);
    const offset = Math.max(0, parseInt(searchParams.get("offset") || "0", 10));

    const { data: currentAdmin } = await supabase.from("admin_users").select("role, organization_id").eq("id", auth.user!.id).single();
    if (!currentAdmin) return NextResponse.json({ error: "Failed to verify user permissions" }, { status: 500 });

    const isRoot = currentAdmin.role === "root" || currentAdmin.role === "dev";
    const { data: isSuperAdmin } = await supabase.rpc("is_super_admin", { user_id: auth.user!.id }) as unknown;
    const { data: userOrgId } = await supabase.rpc("get_user_organization_id", { user_id: auth.user!.id });
    const effectiveOrgId = userOrgId || currentAdmin.organization_id;

    let query = supabase.from("admin_users").select("id, email, role, permissions, is_active, last_login, created_at, updated_at, organization_id, admin_branch_access (id, branch_id, role, is_primary, branches (id, name, code))", { count: "exact" });

    if (!isRoot && effectiveOrgId) query = query.eq("organization_id", effectiveOrgId);
    else if (!isRoot && !effectiveOrgId) return NextResponse.json({ adminUsers: [], pagination: { total: 0, page: 1, limit: 20, totalPages: 0 } });

    if (role && role !== "all") query = query.eq("role", role);
    if (status && status !== "all") query = query.eq("is_active", status === "active");
    if (search.trim()) {
      const pattern = `%${search.trim()}%`;
      const { data: matchingProfiles } = await supabase.from("profiles").select("id").or(`email.ilike.${pattern},first_name.ilike.${pattern},last_name.ilike.${pattern}`);
      if (matchingProfiles && matchingProfiles.length > 0) query = query.in("id", matchingProfiles.map((p) => p.id));
      else query = query.eq("id", "00000000-0000-0000-0000-000000000000");
    }

    const { data: adminUsers, error, count } = await query.order("created_at", { ascending: false }).range(offset, offset + limit - 1);
    if (error) { logger.error("Error fetching admin users", error); return NextResponse.json({ error: "Failed to fetch admin users" }, { status: 500 }); }

    const { data: activityStats } = await supabase.from("admin_activity_log").select("admin_user_id, created_at").gte("created_at", new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString());
    const activityMap = (activityStats || []).reduce((acc: unknown, a: unknown) => { acc[a.admin_user_id] = (acc[a.admin_user_id] || 0) + 1; return acc; }, {});
    const adminIds = (adminUsers || []).map((a: unknown) => a.id);
    const { data: profiles } = await supabase.from("profiles").select("id, first_name, last_name, phone").in("id", adminIds);
    const profilesMap = (profiles || []).reduce((acc: unknown, p: unknown) => { acc[p.id] = p; return acc; }, {});

    const adminUsersWithStats = (adminUsers || []).map((admin: unknown) => {
      const branchAccess = admin.admin_branch_access || [];
      const profile = profilesMap[admin.id];
      return { ...admin, is_super_admin: branchAccess.some((a: unknown) => a.branch_id === null), branches: branchAccess.filter((a: unknown) => a.branch_id !== null).map((a: unknown) => ({ id: a.branch_id, name: a.branches?.name || "N/A", code: a.branches?.code || "N/A", is_primary: a.is_primary })), analytics: { activityCount30Days: activityMap[admin.id] || 0, lastActivity: admin.last_login, fullName: profile ? `${profile.first_name || ""} ${profile.last_name || ""}`.trim() || null : null }, profiles: profile ? { first_name: profile.first_name, last_name: profile.last_name, phone: profile.phone } : null };
    });

    const total = count ?? adminUsersWithStats.length;
    return NextResponse.json({ adminUsers: adminUsersWithStats, pagination: { total, page: Math.floor(offset / limit) + 1, limit, totalPages: Math.ceil(total / limit) } });
  } catch (error) {
    logger.error("Error in admin users API GET", error);
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

export async function POST(request: NextRequest) {
  try {
    const supabase = await createClient();
    const auth = await checkAuth(supabase);
    if (auth.error) return auth.error;
    const adminCheck = await verifyAdmin(supabase, auth.user!.id);
    if (adminCheck) return adminCheck;

    const body = await request.json();
    const { email, role, permissions, is_active = true, is_super_admin = false, branch_ids = [] } = body;
    const branchContext = await getBranchContext(request, auth.user!.id);

    if (is_super_admin && !branchContext.isSuperAdmin) return NextResponse.json({ error: "Solo los super administradores pueden otorgar permisos de super administrador" }, { status: 403 });
    if (!is_super_admin && (!branch_ids || branch_ids.length === 0)) return NextResponse.json({ error: "Debe asignar al menos una sucursal al administrador" }, { status: 400 });
    if (!email) return NextResponse.json({ error: "Email is required" }, { status: 400 });

    const { data: existingUser } = await supabase.from("profiles").select("id, email").eq("email", email).maybeSingle();
    if (!existingUser) return NextResponse.json({ error: "User must be registered first. The user needs to sign up before being granted admin access." }, { status: 400 });

    const { data: existingAdmin } = await supabase.from("admin_users").select("id, email").eq("email", email).maybeSingle();
    if (existingAdmin) return NextResponse.json({ error: "User is already an admin" }, { status: 400 });

    const { data: newAdmin, error: createError } = await supabase.from("admin_users").insert({ id: existingUser.id, email: existingUser.email, role: "admin", permissions: permissions || getDefaultPermissions("admin"), is_active }).select("id, email, role, permissions, is_active, created_at, updated_at").single();
    if (createError) { logger.error("Error creating admin user", createError); return NextResponse.json({ error: "Failed to create admin user", details: createError.message }, { status: 500 }); }

    if (is_super_admin) {
      const { error: ae } = await supabase.from("admin_branch_access").insert({ admin_user_id: newAdmin.id, branch_id: null, role: "manager", is_primary: true });
      if (ae) { await supabase.from("admin_users").delete().eq("id", newAdmin.id); return NextResponse.json({ error: "Failed to assign super admin access", details: ae.message }, { status: 500 }); }
    } else if (branch_ids.length > 0) {
      const { error: ae } = await supabase.from("admin_branch_access").insert(branch_ids.map((bid: string, i: number) => ({ admin_user_id: newAdmin.id, branch_id: bid, role: "manager", is_primary: i === 0 })));
      if (ae) { await supabase.from("admin_users").delete().eq("id", newAdmin.id); return NextResponse.json({ error: "Failed to assign branch access", details: ae.message }, { status: 500 }); }
    }

    try { await supabase.rpc("log_admin_activity", { action: "create_admin_user", resource_type: "admin_user", resource_id: newAdmin.id, details: { new_admin_email: email, role: "admin", is_super_admin, branch_ids: is_super_admin ? null : branch_ids, created_by: auth.user!.email } }); } catch { }
    return NextResponse.json({ adminUser: newAdmin });
  } catch (error) {
    logger.error("Error in create admin user API", error);
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { id: agreementId } = await params;
    const supabase = await createClient();
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    const { data: agreement } = await supabase
      .from("agreements")
      .select("id")
      .eq("id", agreementId)
      .single();

    if (!agreement) {
      return NextResponse.json(
        { error: "Convenio no encontrado" },
        { status: 404 },
      );
    }

    const searchParams = request.nextUrl.searchParams;
    const fromDate = searchParams.get("from");
    const toDate = searchParams.get("to");

    let ordersQuery = supabase
      .from("orders")
      .select(
        "id, customer_id, total_amount, copago_amount, institutional_amount, created_at",
      )
      .eq("agreement_id", agreementId);

    if (fromDate) {
      ordersQuery = ordersQuery.gte("created_at", fromDate);
    }
    if (toDate) {
      ordersQuery = ordersQuery.lte("created_at", toDate + "T23:59:59.999Z");
    }

    const { data: orders } = await ordersQuery;

    const totalSales = (orders || []).reduce(
      (s, o) => s + (o.total_amount || 0),
      0,
    );
    const totalCopago = (orders || []).reduce(
      (s, o) => s + (o.copago_amount || 0),
      0,
    );
    const totalInstitutional = (orders || []).reduce(
      (s, o) => s + (o.institutional_amount || 0),
      0,
    );

    const { data: balances } = await supabase
      .from("agreement_institutional_balances")
      .select("amount, status")
      .eq("agreement_id", agreementId);

    const pendingAmount = (balances || [])
      .filter((b) => b.status === "pending")
      .reduce((s, b) => s + (b.amount || 0), 0);
    const paidAmount = (balances || [])
      .filter((b) => b.status === "paid")
      .reduce((s, b) => s + (b.amount || 0), 0);

    const uniqueCustomers = new Set(
      (orders || []).map((o: unknown) => o.customer_id).filter(Boolean),
    ).size;

    return NextResponse.json({
      success: true,
      data: {
        total_orders: orders?.length ?? 0,
        unique_customers: uniqueCustomers,
        total_sales: totalSales,
        total_copago: totalCopago,
        total_institutional: totalInstitutional,
        pending_amount: pendingAmount,
        paid_amount: paidAmount,
        collection_efficiency:
          totalInstitutional > 0
            ? Math.round((paidAmount / totalInstitutional) * 100)
            : 100,
      },
    });
  } catch (error) {
    logger.error("Analytics GET error", { error });
    return NextResponse.json(
      { error: "Error al obtener analítica" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import {
  createApiErrorResponse,
  createPaginatedResponse,
 extractPaginationParams } from "@/lib/api/response";
import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { id: agreementId } = await params;
    const supabase = await createClient();

    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    const { data: agreement } = await supabase
      .from("agreements")
      .select("id")
      .eq("id", agreementId)
      .single();

    if (!agreement) {
      return NextResponse.json(
        { error: "Convenio no encontrado" },
        { status: 404 },
      );
    }

    const { page, limit } = extractPaginationParams(request.url);
    const offset = (page - 1) * limit;

    let items: Array<{
      customer_id: string;
      first_name: string | null;
      last_name: string | null;
      email: string | null;
      phone: string | null;
      rut: string | null;
      order_count: number;
      last_order_at: string;
      total_copago: number;
      total_institutional: number;
    }> = [];
    let total = 0;

    try {
      // Get total count (table may not exist if migration not run)
      const { count, error: countError } = await supabase
        .from("agreement_customers")
        .select("*", { count: "exact", head: true })
        .eq("agreement_id", agreementId);

      if (countError) {
        logger.warn("agreement_customers query failed (table may not exist)", {
          error: countError,
          code: (countError as unknown)?.code,
        });
        return createPaginatedResponse([], { page, limit, total: 0 });
      }

      total = count ?? 0;

      // Get agreement_customers
      const { data: acRows, error: acError } = await supabase
        .from("agreement_customers")
        .select(
          "customer_id, order_count, last_order_at, total_copago, total_institutional",
        )
        .eq("agreement_id", agreementId)
        .order("last_order_at", { ascending: false })
        .range(offset, offset + limit - 1);

      if (acError) {
        logger.warn("agreement_customers fetch failed", { error: acError });
        return createPaginatedResponse([], { page, limit, total: 0 });
      }

      const paginatedRows = acRows ?? [];

      // Fetch customer details in a separate query
      const customerIds = paginatedRows
        .map((r: unknown) => r.customer_id)
        .filter(Boolean);
      const customersMap: Record<
        string,
        {
          first_name?: string;
          last_name?: string;
          email?: string;
          phone?: string;
          rut?: string;
        }
      > = {};
      if (customerIds.length > 0) {
        const { data: customers } = await supabase
          .from("customers")
          .select("id, first_name, last_name, email, phone, rut")
          .in("id", customerIds);
        (customers || []).forEach((c: unknown) => {
          customersMap[c.id] = c;
        });
      }

      items = paginatedRows.map((r: unknown) => {
        const cust = customersMap[r.customer_id];
        return {
          customer_id: r.customer_id,
          first_name: cust?.first_name ?? null,
          last_name: cust?.last_name ?? null,
          email: cust?.email ?? null,
          phone: cust?.phone ?? null,
          rut: cust?.rut ?? null,
          order_count: r.order_count,
          last_order_at: r.last_order_at,
          total_copago: Number(r.total_copago ?? 0),
          total_institutional: Number(r.total_institutional ?? 0),
        };
      });
    } catch (innerError) {
      logger.warn("agreement_customers error (returning empty)", {
        error: innerError,
      });
      return createPaginatedResponse([], { page, limit, total: 0 });
    }

    return createPaginatedResponse(items, { page, limit, total });
  } catch (error) {
    logger.error("Agreement customers GET error", { error });
    return createApiErrorResponse(error as Error);
  }
}

import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { id: agreementId } = await params;
    const supabase = await createClient();
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
