import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import { createClient } from "@/utils/supabase/server";

/**
 * GET /api/admin/ai/usage
 * Get AI usage and cost metrics for the current organization.
 * Query params: days (default 30), organizationId (super_admin only)
 */
export const dynamic = "force-dynamic";

// Rough cost per 1K tokens (USD) - update as needed
const MODEL_COSTS: Record<string, { input: number; output: number }> = {
  "gpt-4o": { input: 0.0025, output: 0.01 },
  "gpt-4o-mini": { input: 0.00015, output: 0.0006 },
  "gpt-4-turbo": { input: 0.01, output: 0.03 },
  "gpt-4-turbo-preview": { input: 0.01, output: 0.03 },
  "gpt-3.5-turbo": { input: 0.0005, output: 0.0015 },
  "claude-3-5-sonnet": { input: 0.003, output: 0.015 },
  "claude-3-opus": { input: 0.015, output: 0.075 },
  "gemini-2.5-flash": { input: 0.00015, output: 0.0006 },
  "gemini-2.5-pro": { input: 0.00125, output: 0.005 },
  "deepseek-chat": { input: 0.00014, output: 0.00028 },
  default: { input: 0.001, output: 0.002 },
};

function getModelCost(model: string) {
  const key = Object.keys(MODEL_COSTS).find((k) =>
    model.toLowerCase().includes(k.toLowerCase()),
  );
  return MODEL_COSTS[key || "default"];
}

export async function GET(request: NextRequest) {
  try {
    const supabase = await createClient();
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: adminUser } = await supabase
      .from("admin_users")
      .select("organization_id, role")
      .eq("id", user.id)
      .eq("is_active", true)
      .single();

    if (!adminUser?.organization_id) {
      return NextResponse.json(
        { error: "Organization not found" },
        { status: 404 },
      );
    }

    const searchParams = request.nextUrl.searchParams;
    const daysParam = searchParams.get("days");
    const days = Math.min(
      90,
      Math.max(1, parseInt(daysParam || "30", 10) || 30),
    );
    const targetOrgId = searchParams.get("organizationId");

    let orgId = adminUser.organization_id;
    if (
      targetOrgId &&
      ["super_admin", "root", "dev"].includes(adminUser.role)
    ) {
      orgId = targetOrgId;
    }

    const startDate = new Date();
    startDate.setDate(startDate.getDate() - days);

    const { data: logs, error } = await supabase
      .from("ai_usage_log")
      .select(
        "provider, model, prompt_tokens, completion_tokens, endpoint, created_at",
      )
      .eq("organization_id", orgId)
      .gte("created_at", startDate.toISOString())
      .order("created_at", { ascending: false });

    if (error) {
      // Table may not exist yet (migration not applied) - return empty data
      if (error.code === "42P01" || error.message?.includes("does not exist")) {
        logger.warn("ai_usage_log table not found, returning empty data", {
          hint: "Run migration 20260302000001_create_ai_usage_log",
        });
        return NextResponse.json({
          organizationId: orgId,
          period: { days, startDate: startDate.toISOString() },
          summary: {
            totalPromptTokens: 0,
            totalCompletionTokens: 0,
            totalTokens: 0,
            estimatedCostUsd: 0,
            requestCount: 0,
          },
          byModel: [],
          recentLogs: [],
        });
      }
      logger.error("Failed to fetch AI usage", { error });
      return NextResponse.json(
        { error: "Failed to fetch usage" },
        { status: 500 },
      );
    }

    let totalPromptTokens = 0;
    let totalCompletionTokens = 0;
    let estimatedCost = 0;

    const byModel: Record<
      string,
      { promptTokens: number; completionTokens: number; count: number }
    > = {};

    for (const row of logs || []) {
      totalPromptTokens += row.prompt_tokens || 0;
      totalCompletionTokens += row.completion_tokens || 0;
      const cost = getModelCost(row.model);
      estimatedCost +=
        ((row.prompt_tokens || 0) / 1000) * cost.input +
        ((row.completion_tokens || 0) / 1000) * cost.output;

      const key = `${row.provider}:${row.model}`;
      if (!byModel[key]) {
        byModel[key] = { promptTokens: 0, completionTokens: 0, count: 0 };
      }
      byModel[key].promptTokens += row.prompt_tokens || 0;
      byModel[key].completionTokens += row.completion_tokens || 0;
      byModel[key].count += 1;
    }

    return NextResponse.json({
      organizationId: orgId,
      period: { days, startDate: startDate.toISOString() },
      summary: {
        totalPromptTokens,
        totalCompletionTokens,
        totalTokens: totalPromptTokens + totalCompletionTokens,
        estimatedCostUsd: Math.round(estimatedCost * 10000) / 10000,
        requestCount: logs?.length || 0,
      },
      byModel: Object.entries(byModel).map(([key, v]) => ({
        model: key,
        ...v,
        totalTokens: v.promptTokens + v.completionTokens,
      })),
      recentLogs: (logs || []).slice(0, 50),
    });
  } catch (err: unknown) {
    logger.error("AI usage API error", { error: err?.message });
    return NextResponse.json(
      { error: err?.message || "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest } from "next/server";

import { parseAnalyticsPeriod } from "@/lib/analytics/analytics-service";
import { getBranchContext } from "@/lib/api/branch-middleware";
import { AuthenticationError, AuthorizationError } from "@/lib/api/errors";
import { createApiErrorResponse, createApiSuccessResponse } from "@/lib/api/response";
import { computeDashboardAnalytics } from "@/lib/api/services/dashboardAnalyticsService";
import { appLogger as logger } from "@/lib/logger";
import { createClientFromRequest } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";

function getLocalDateString(date: Date): string {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

export async function GET(request: NextRequest) {
  const requestId = crypto.randomUUID();

  try {
    logger.debug("Analytics Dashboard API called", { requestId });

    const { client: supabase, getUser } = await createClientFromRequest(request);

    // Auth check
    const { data: { user } = {}, error: userError } = (await getUser()) as unknown;
    if (userError || !user) {
      return createApiErrorResponse(new AuthenticationError("Unauthorized"));
    }

    const { data: isAdmin } = await supabase.rpc("is_admin", { user_id: user.id });
    if (!isAdmin) {
      return createApiErrorResponse(new AuthorizationError("Admin access required"));
    }

    // Tier feature check
    const { data: adminUser } = await supabase
      .from("admin_users")
      .select("organization_id")
      .eq("id", user.id)
      .single();
    if (adminUser?.organization_id) {
      const { validateFeature } = await import("@/lib/saas/tier-validator");
      const hasAdvancedAnalytics = await validateFeature(adminUser.organization_id, "advanced_analytics");
      if (!hasAdvancedAnalytics) {
        return createApiErrorResponse(
          new AuthorizationError("Analíticas avanzadas no están incluidas en tu plan. Actualiza a Pro o Premium."),
        );
      }
    }

    // Branch context
    const branchContext = await getBranchContext(request, user.id);
    const { searchParams } = new URL(request.url);
    const period = parseAnalyticsPeriod(searchParams);

    // Date ranges
    const endDate = new Date();
    const startDate = new Date();
    startDate.setDate(endDate.getDate() - period);
    const startStr = startDate.toISOString();
    const endStr = endDate.toISOString();
    const periodStartStr = getLocalDateString(startDate);
    const periodEndStr = getLocalDateString(endDate);
    const prevPeriodStart = new Date(startDate);
    prevPeriodStart.setDate(prevPeriodStart.getDate() - period);

    // Org branch IDs for global view
    let orgBranchIds: string[] = [];
    if (branchContext.isSuperAdmin && !branchContext.branchId && branchContext.organizationId) {
      const { data: branches } = await supabase
        .from("branches")
        .select("id")
        .eq("organization_id", branchContext.organizationId);
      orgBranchIds = (branches || []).map((b: { id: string }) => b.id);
    }

    const analytics = await computeDashboardAnalytics({
      orgId: branchContext.organizationId,
      branchId: branchContext.branchId,
      isSuperAdmin: branchContext.isSuperAdmin,
      organizationId: branchContext.organizationId,
      orgBranchIds,
      period,
      startDate,
      endDate,
      startStr,
      endStr,
      periodStartStr,
      periodEndStr,
      prevPeriodStartStr: getLocalDateString(prevPeriodStart),
    });

    logger.info("Analytics calculated successfully", { period, branchId: branchContext.branchId, requestId });
    return createApiSuccessResponse({ analytics }, { requestId });
  } catch (error) {
    logger.error("Analytics API error:", { error, requestId });
    return createApiErrorResponse(
      error instanceof Error ? error : new Error("Failed to fetch analytics data"),
      { requestId },
    );
  }
}

import { createClient } from "@supabase/supabase-js";
import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";

// Initialize Supabase client for server-side operations
const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!,
);

export const dynamic = "force-dynamic";
export async function POST(request: NextRequest) {
  try {
    const events = await request.json();

    if (!Array.isArray(events)) {
      return NextResponse.json(
        { error: "Invalid event format" },
        { status: 400 },
      );
    }

    // Check if telemetry is enabled globally using the service role client
    // initialized at the top of the file to avoid shadowing and redundant calls.
    const { data: config } = await supabase
      .from("system_config")
      .select("config_value")
      .eq("config_key", "telemetry_enabled")
      .maybeSingle();

    let enabled = true;
    if (config) {
      try {
        enabled =
          typeof config.config_value === "string"
            ? JSON.parse(config.config_value)
            : config.config_value;
      } catch (e) {
        enabled = !!config.config_value;
      }
    }

    if (!enabled) {
      return NextResponse.json({
        success: true,
        message: "Telemetry is globally disabled",
        processed: 0,
        stored: 0,
      });
    }

    // Map all events to database schema with validation
    const uuidRegex =
      /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

    const dbEvents = events.map((event) => {
      // Validate IDs
      const userId =
        event.userId && uuidRegex.test(event.userId) ? event.userId : null;
      const orgId =
        event.context?.organizationId &&
        uuidRegex.test(event.context.organizationId)
          ? event.context.organizationId
          : null;

      // Parse duration safely
      let duration = null;
      const rawDuration =
        event.payload?.duration || event.metadata?.performance?.responseTime;
      if (rawDuration !== undefined && rawDuration !== null) {
        duration = Math.round(Number(rawDuration));
      }

      return {
        event_type: event.eventType || "server_event",
        event_name:
          event.eventName || event.eventType || "unnamed_server_event",
        timestamp: event.timestamp || new Date().toISOString(),
        user_id: userId,
        organization_id: orgId,
        session_id: event.sessionId || null,
        payload: event.payload || {},
        user_agent: request.headers.get("user-agent") || null,
        ip_address:
          request.headers.get("x-forwarded-for") ||
          request.headers.get("x-real-ip") ||
          null,
        device_type: null,
        browser: null,
        os: null,
        screen_size: null,
        page_url: event.metadata?.pageUrl || null,
        referrer: event.metadata?.referrer || null,
        duration: duration,
        performance_data: event.metadata?.performance || null,
      };
    });

    // Insert into database in bulk
    const { data: insertedData, error } = await supabase
      .from("telemetry_events")
      .insert(dbEvents)
      .select();

    if (error) {
      logger.error("Failed to store server telemetry events:", error);
      // Return more detail in development/internal logs
      return NextResponse.json(
        {
          error: "Failed to store telemetry events",
          details: error.message,
          code: error.code,
        },
        { status: 500 },
      );
    }

    const storedEventsCount = insertedData ? insertedData.length : 0;

    return NextResponse.json({
      success: true,
      processed: events.length,
      stored: storedEventsCount,
      totalReceived: events.length,
    });
  } catch (error) {
    logger.error("Server telemetry error:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import type {
  GetAvailableTimeSlotsParams,
  GetAvailableTimeSlotsResult,
  IsAdminParams,
  IsAdminResult,
  TimeSlot,
} from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    // Get branch context
    const branchContext = await getBranchContext(request, user.id);

    const searchParams = request.nextUrl.searchParams;
    const date = searchParams.get("date");
    const duration = parseInt(searchParams.get("duration") || "30");
    const staffId = searchParams.get("staff_id");

    if (!date) {
      return NextResponse.json(
        { error: "Date parameter is required" },
        { status: 400 },
      );
    }

    // Get available time slots
    logger.debug("Fetching availability for:", {
      date,
      duration,
      staffId,
      branchId: branchContext.branchId,
    });

    const { data: slots, error } = (await supabase.rpc(
      "get_available_time_slots",
      {
        p_date: date,
        p_duration_minutes: duration,
        p_staff_id: staffId || null,
        p_branch_id: branchContext.branchId || null,
      } as GetAvailableTimeSlotsParams,
    )) as { data: GetAvailableTimeSlotsResult; error: Error | null };

    if (error) {
      logger.error("Error fetching available slots:", {
        error,
        date,
        duration,
        staffId,
        branchId: branchContext.branchId,
      });
      return NextResponse.json(
        {
          error: "Failed to fetch available slots",
          details: error.message,
        },
        { status: 500 },
      );
    }

    logger.debug("Available slots returned:", {
      count: slots?.length || 0,
      date,
      duration,
    });

    if (!slots || slots.length === 0) {
      logger.warn("No slots returned from RPC function", {
        date,
        duration,
        staffId,
        branchId: branchContext.branchId,
      });
      return NextResponse.json({
        date,
        duration,
        slots: [],
      });
    }

    // Ensure slots are properly formatted
    const formattedSlots = (slots || [])
      .map((slot: TimeSlot) => {
        let timeSlot = "";

        // Handle different TIME formats from PostgreSQL
        if (typeof slot.time_slot === "string") {
          timeSlot = slot.time_slot;
        } else if (slot.time_slot) {
          // If it's a TIME object, convert to string
          const timeValue = slot.time_slot as unknown;
          if (
            typeof timeValue === "object" &&
            timeValue !== null &&
            "hours" in timeValue &&
            "minutes" in timeValue
          ) {
            timeSlot = `${String(timeValue.hours).padStart(2, "0")}:${String(timeValue.minutes).padStart(2, "0")}`;
          } else {
            timeSlot = String(timeValue);
          }
        }

        // Format time to HH:MM (remove seconds if present)
        if (timeSlot.includes(":")) {
          const parts = timeSlot.split(":");
          timeSlot = `${parts[0]}:${parts[1]}`;
        }

        // Handle boolean availability (PostgreSQL returns 't'/'f' as strings sometimes)
        let isAvailable = true;
        if (typeof slot.available === "boolean") {
          isAvailable = slot.available;
        } else if (typeof slot.available === "string") {
          isAvailable = slot.available === "t" || slot.available === "true";
        } else if (slot.available !== undefined && slot.available !== null) {
          isAvailable = Boolean(slot.available);
        }

        return {
          time_slot: timeSlot,
          available: isAvailable,
        };
      })
      .filter((slot) => slot.time_slot); // Filter out empty time slots

    logger.debug("Formatted slots:", {
      sample: formattedSlots.slice(0, 5),
      total: formattedSlots.length,
    });

    return NextResponse.json({
      date,
      duration,
      slots: formattedSlots,
    });
  } catch (error) {
    logger.error("Error in availability API:", { error });
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { createApiSuccessResponse } from "@/lib/api/response";
import { appLogger as logger } from "@/lib/logger";
import { rateLimitConfigs, withRateLimit } from "@/lib/rate-limiting";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

const billingSettingsSchema = z.object({
  business_name: z.string().optional().nullable(),
  business_rut: z.string().optional().nullable(),
  business_address: z.string().optional().nullable(),
  business_phone: z.string().optional().nullable(),
  business_email: z.string().optional().nullable(),
  logo_url: z.string().optional().nullable(),
  header_text: z.string().optional().nullable(),
  footer_text: z.string().optional().nullable(),
  terms_and_conditions: z.string().optional().nullable(),
  default_document_type: z.enum(["boleta", "factura"]).optional(),
  printer_type: z.enum(["thermal", "a4", "letter", "custom"]).optional(),
  printer_width_mm: z.number().optional(),
  printer_height_mm: z.number().optional(),
  auto_print_receipt: z.boolean().optional().default(true),
});

export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    return await (withRateLimit(rateLimitConfigs.general) as unknown)(
      request,
      async () => {
        const supabase = await createClient();

        // Check admin authorization
        const {
          data: { user },
          error: userError,
        } = await supabase.auth.getUser();
        if (userError || !user) {
          return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        const { data: isAdmin } = (await supabase.rpc("is_admin", {
          user_id: user.id,
        } as IsAdminParams)) as {
          data: IsAdminResult | null;
          error: Error | null;
        };
        if (!isAdmin) {
          return NextResponse.json(
            { error: "Admin access required" },
            { status: 403 },
          );
        }

        // Get branch context
        const branchContext = await getBranchContext(request, user.id);

        // Get settings for the branch
        let branchSettings = null;
        if (branchContext.branchId) {
          const { data, error: settingsError } = await supabase
            .from("pos_settings")
            .select("*")
            .eq("branch_id", branchContext.branchId)
            .maybeSingle();

          if (settingsError && settingsError.code !== "PGRST116") {
            logger.error(
              "Error fetching branch billing settings",
              settingsError,
            );
          } else {
            branchSettings = data;
          }
        }

        // Get organization-level settings
        const { data: orgSettings } = await supabase
          .from("organization_settings")
          .select("*")
          .eq("organization_id", branchContext.organizationId!)
          .maybeSingle();

        // Merge logic: Branch settings > Organization settings > Defaults
        const getMergedValue = (
          field: string,
          defaultValue: unknown = null,
        ) => {
          if (
            branchSettings &&
            branchSettings[field] !== null &&
            branchSettings[field] !== undefined &&
            branchSettings[field] !== ""
          ) {
            return branchSettings[field];
          }
          if (
            orgSettings &&
            orgSettings[field] !== null &&
            orgSettings[field] !== undefined &&
            orgSettings[field] !== ""
          ) {
            return orgSettings[field];
          }
          return defaultValue;
        };

        const mergedSettings = {
          business_name: getMergedValue("business_name"),
          business_rut: getMergedValue("business_rut"),
          business_address: getMergedValue("business_address"),
          business_phone: getMergedValue("business_phone"),
          business_email: getMergedValue("business_email"),
          logo_url: getMergedValue("logo_url"),
          header_text: getMergedValue("header_text"),
          footer_text: getMergedValue("footer_text"),
          terms_and_conditions: getMergedValue("terms_and_conditions"),
          default_document_type: getMergedValue(
            "default_document_type",
            "boleta",
          ),
          printer_type: getMergedValue("printer_type", "thermal"),
          printer_width_mm: getMergedValue("printer_width_mm", 80),
          printer_height_mm: getMergedValue("printer_height_mm", 297),
          auto_print_receipt: getMergedValue("auto_print_receipt", true),
        };

        return createApiSuccessResponse(mergedSettings);
      },
    );
  } catch (error) {
    logger.error("Error in Billing settings GET API", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

export async function PUT(request: NextRequest) {
  try {
    return await (withRateLimit(rateLimitConfigs.modification) as unknown)(
      request,
      async () => {
        const supabase = await createClient();

        // Check admin authorization
        const {
          data: { user },
          error: userError,
        } = await supabase.auth.getUser();
        if (userError || !user) {
          return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        const { data: isAdmin } = (await supabase.rpc("is_admin", {
          user_id: user.id,
        } as IsAdminParams)) as {
          data: IsAdminResult | null;
          error: Error | null;
        };
        if (!isAdmin) {
          return NextResponse.json(
            { error: "Admin access required" },
            { status: 403 },
          );
        }

        // Get branch context
        const branchContext = await getBranchContext(request, user.id);

        // Parse and validate request body
        const body = await request.json();
        const validatedData = billingSettingsSchema.parse(body);

        let result;

        // GLOBAL UPDATE LOGIC for Super Admins
        if (!branchContext.branchId && branchContext.isSuperAdmin) {
          logger.info("Global Billing settings update initiated", {
            organizationId: branchContext.organizationId,
          });

          // 1. Update organization-level settings
          const { data: orgSettings, error: orgError } = await supabase
            .from("organization_settings")
            .upsert(
              {
                organization_id: branchContext.organizationId,
                ...validatedData,
                updated_at: new Date().toISOString(),
              },
              { onConflict: "organization_id" },
            )
            .select()
            .single();

          if (orgError) {
            logger.error(
              "Error updating global organization billing settings",
              orgError,
            );
            return NextResponse.json(
              { error: "Error al actualizar configuración global de boletas" },
              { status: 500 },
            );
          }

          // 2. Sync ALL branches of the organization
          const { data: branches } = await supabase
            .from("branches")
            .select("id")
            .eq("organization_id", branchContext.organizationId!);

          if (branches && branches.length > 0) {
            const branchIds = branches.map((b) => b.id);

            for (const bId of branchIds) {
              await supabase.from("pos_settings").upsert(
                {
                  branch_id: bId,
                  ...validatedData,
                  updated_at: new Date().toISOString(),
                },
                { onConflict: "branch_id" },
              );
            }
          }

          result = orgSettings;
        } else if (branchContext.branchId) {
          // BRANCH-SPECIFIC UPDATE
          const { data: updatedSettings, error: updateError } = await supabase
            .from("pos_settings")
            .upsert(
              {
                branch_id: branchContext.branchId,
                ...validatedData,
                updated_at: new Date().toISOString(),
              },
              { onConflict: "branch_id" },
            )
            .select()
            .single();

          if (updateError) {
            logger.error("Error updating branch billing settings", updateError);
            return NextResponse.json(
              { error: "Error al actualizar configuración de sucursal" },
              { status: 500 },
            );
          }

          result = updatedSettings;
        } else {
          return NextResponse.json(
            {
              error: "Debe seleccionar una sucursal o ser super administrador",
            },
            { status: 400 },
          );
        }

        return createApiSuccessResponse(result);
      },
    );
  } catch (error) {
    if (error instanceof z.ZodError) {
      return NextResponse.json(
        { error: "Validation failed", details: error.errors },
        { status: 400 },
      );
    }

    logger.error("Error in Billing settings PUT API", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { validateBranchAccess } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { id } = await params;
    const supabase = await createClient();
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    // Check access (super admin or has access to this branch)
    const canAccess = await validateBranchAccess(
      user.id,
      id === "global" ? null : id,
    );

    if (!canAccess) {
      return NextResponse.json(
        { error: "Access denied to this branch" },
        { status: 403 },
      );
    }

    if (id === "global") {
      // Return global view info
      return NextResponse.json({
        id: "global",
        name: "Vista Global",
        code: "GLOBAL",
        is_global: true,
      });
    }

    // Fetch branch details
    const { data: branch, error } = await supabase
      .from("branches")
      .select("*")
      .eq("id", id)
      .single();

    if (error || !branch) {
      return NextResponse.json({ error: "Branch not found" }, { status: 404 });
    }

    return NextResponse.json({ branch });
  } catch (error: unknown) {
    logger.error("Error in GET /api/admin/branches/[id]", error);
    return NextResponse.json(
      { error: error.message || "Internal server error" },
      { status: 500 },
    );
  }
}

export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { id } = await params;
    const supabase = await createClient();
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    // Check if user is super admin
    const { data: isSuperAdmin } = await supabase.rpc("is_super_admin", {
      user_id: user.id,
    });

    if (!isSuperAdmin) {
      return NextResponse.json(
        { error: "Only super admins can update branches" },
        { status: 403 },
      );
    }

    if (id === "global") {
      return NextResponse.json(
        { error: "Cannot update global view" },
        { status: 400 },
      );
    }

    const body = await request.json();
    const {
      name,
      code,
      address_line_1,
      address_line_2,
      city,
      state,
      postal_code,
      country,
      phone,
      email,
      is_active,
      settings,
    } = body;

    // Check if code is being changed and if it conflicts
    if (code) {
      const { data: existingBranch } = await supabase
        .from("branches")
        .select("id")
        .eq("code", code)
        .neq("id", id)
        .single();

      if (existingBranch) {
        return NextResponse.json(
          { error: "Branch code already exists" },
          { status: 400 },
        );
      }
    }

    // Update branch
    const updateData: unknown = {};
    if (name !== undefined) updateData.name = name;
    if (code !== undefined) updateData.code = code;
    if (address_line_1 !== undefined)
      updateData.address_line_1 = address_line_1;
    if (address_line_2 !== undefined)
      updateData.address_line_2 = address_line_2;
    if (city !== undefined) updateData.city = city;
    if (state !== undefined) updateData.state = state;
    if (postal_code !== undefined) updateData.postal_code = postal_code;
    if (country !== undefined) updateData.country = country;
    if (phone !== undefined) updateData.phone = phone;
    if (email !== undefined) updateData.email = email;
    if (is_active !== undefined) updateData.is_active = is_active;
    if (settings !== undefined) updateData.settings = settings;

    const { data: updatedBranch, error } = await supabase
      .from("branches")
      .update(updateData)
      .eq("id", id)
      .select()
      .single();

    if (error) {
      logger.error("Error updating branch", error);
      return NextResponse.json(
        { error: "Failed to update branch" },
        { status: 500 },
      );
    }

    return NextResponse.json({ branch: updatedBranch });
  } catch (error: unknown) {
    logger.error("Error in PUT /api/admin/branches/[id]", error);
    return NextResponse.json(
      { error: error.message || "Internal server error" },
      { status: 500 },
    );
  }
}

export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { id } = await params;
    const supabase = await createClient();
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    // Check if user is super admin
    const { data: isSuperAdmin } = await supabase.rpc("is_super_admin", {
      user_id: user.id,
    });

    if (!isSuperAdmin) {
      return NextResponse.json(
        { error: "Only super admins can delete branches" },
        { status: 403 },
      );
    }

    if (id === "global") {
      return NextResponse.json(
        { error: "Cannot delete global view" },
        { status: 400 },
      );
    }

    // Check if branch has associated data (orders, products, etc.)
    // This is a soft check - in production you might want to check more thoroughly
    const { data: hasOrders } = await supabase
      .from("orders")
      .select("id")
      .eq("branch_id", id)
      .limit(1)
      .single();

    if (hasOrders) {
      return NextResponse.json(
        {
          error:
            "Cannot delete branch with associated orders. Deactivate it instead.",
        },
        { status: 400 },
      );
    }

    // Delete branch
    const { error } = await supabase.from("branches").delete().eq("id", id);

    if (error) {
      logger.error("Error deleting branch", error);
      return NextResponse.json(
        { error: "Failed to delete branch" },
        { status: 500 },
      );
    }

    return NextResponse.json({ success: true });
  } catch (error: unknown) {
    logger.error("Error in DELETE /api/admin/branches/[id]", error);
    return NextResponse.json(
      { error: error.message || "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { validateBranchAccess } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import type {
  IsSuperAdminParams,
  IsSuperAdminResult,
} from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params;
  try {
    const supabase = await createClient();
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    // Check if user is super admin
    const { data: isSuperAdmin } = (await supabase.rpc("is_super_admin", {
      user_id: user.id,
    } as IsSuperAdminParams)) as {
      data: IsSuperAdminResult | null;
      error: Error | null;
    };

    // Check access
    const branchId = id === "global" ? null : id;
    const canAccess = await validateBranchAccess(user.id, branchId);

    if (!canAccess) {
      return NextResponse.json(
        { error: "Access denied to this branch" },
        { status: 403 },
      );
    }

    // Build queries with branch filter
    const branchFilter = (query: unknown) => {
      if (id === "global" && isSuperAdmin) {
        return query; // Super admin sees all
      }
      if (branchId) {
        return query.eq("branch_id", branchId);
      }
      return query.is("branch_id", null);
    };

    // Get statistics
    const [
      appointmentsCount,
      quotesCount,
      workOrdersCount,
      ordersCount,
      todayRevenue,
      pendingQuotes,
      inProgressWorkOrders,
      todayAppointments,
    ] = await Promise.all([
      // Total appointments
      branchFilter(
        supabase
          .from("appointments")
          .select("id", { count: "exact", head: true }),
      ),

      // Total quotes
      branchFilter(
        supabase.from("quotes").select("id", { count: "exact", head: true }),
      ),

      // Total work orders
      branchFilter(
        supabase
          .from("lab_work_orders")
          .select("id", { count: "exact", head: true }),
      ),

      // Total orders
      branchFilter(
        supabase.from("orders").select("id", { count: "exact", head: true }),
      ),

      // Today's revenue
      branchFilter(
        supabase
          .from("orders")
          .select("total_amount")
          .eq("status", "completed")
          .gte("created_at", new Date().toISOString().split("T")[0]),
      ),

      // Pending quotes
      branchFilter(
        supabase
          .from("quotes")
          .select("id", { count: "exact", head: true })
          .eq("status", "sent"),
      ),

      // In progress work orders
      branchFilter(
        supabase
          .from("lab_work_orders")
          .select("id", { count: "exact", head: true })
          .in("status", ["in_progress_lab", "mounted", "quality_check"]),
      ),

      // Today's appointments
      branchFilter(
        supabase
          .from("appointments")
          .select("id", { count: "exact", head: true })
          .eq("appointment_date", new Date().toISOString().split("T")[0])
          .in("status", ["scheduled", "confirmed"]),
      ),
    ]);

    // Calculate today's revenue
    const revenueData = await todayRevenue;
    const todayRevenueAmount =
      revenueData.data?.reduce(
        (sum: number, order: unknown) =>
          sum + (parseFloat(order.total_amount) || 0),
        0,
      ) || 0;

    const stats = {
      branch_id: branchId,
      is_global: id === "global",
      appointments: {
        total: appointmentsCount.count || 0,
        today: todayAppointments.count || 0,
      },
      quotes: {
        total: quotesCount.count || 0,
        pending: pendingQuotes.count || 0,
      },
      work_orders: {
        total: workOrdersCount.count || 0,
        in_progress: inProgressWorkOrders.count || 0,
      },
      orders: {
        total: ordersCount.count || 0,
      },
      revenue: {
        today: todayRevenueAmount,
      },
    };

    return NextResponse.json({ stats });
  } catch (error: unknown) {
    logger.error("Error in GET /api/admin/branches/[id]/stats:", {
      error,
      branchId: id,
    });
    return NextResponse.json(
      { error: error.message || "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { validateBranchAccess } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    const supabase = await createClient();
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    // Only super admins can access global stats
    const canAccess = await validateBranchAccess(user.id, null);

    if (!canAccess) {
      return NextResponse.json(
        { error: "Only super admins can access global statistics" },
        { status: 403 },
      );
    }

    // Get all branches
    const { data: branches } = await supabase
      .from("branches")
      .select("id, name, code")
      .eq("is_active", true)
      .order("name");

    // Get global statistics
    const [
      totalAppointments,
      totalQuotes,
      totalWorkOrders,
      totalOrders,
      totalRevenue,
      branchesStats,
    ] = await Promise.all([
      // Total appointments across all branches
      supabase
        .from("appointments")
        .select("id", { count: "exact", head: true }),

      // Total quotes
      supabase.from("quotes").select("id", { count: "exact", head: true }),

      // Total work orders
      supabase
        .from("lab_work_orders")
        .select("id", { count: "exact", head: true }),

      // Total orders
      supabase.from("orders").select("id", { count: "exact", head: true }),

      // Total revenue
      supabase.from("orders").select("total_amount").eq("status", "completed"),

      // Stats per branch
      Promise.all(
        (branches || []).map(async (branch) => {
          const [appointments, quotes, workOrders, orders, revenue] =
            await Promise.all([
              supabase
                .from("appointments")
                .select("id", { count: "exact", head: true })
                .eq("branch_id", branch.id),
              supabase
                .from("quotes")
                .select("id", { count: "exact", head: true })
                .eq("branch_id", branch.id),
              supabase
                .from("lab_work_orders")
                .select("id", { count: "exact", head: true })
                .eq("branch_id", branch.id),
              supabase
                .from("orders")
                .select("id", { count: "exact", head: true })
                .eq("branch_id", branch.id),
              supabase
                .from("orders")
                .select("total_amount")
                .eq("branch_id", branch.id)
                .eq("status", "completed"),
            ]);

          const revenueData = await revenue;
          const branchRevenue =
            revenueData.data?.reduce(
              (sum: number, order: unknown) =>
                sum + (parseFloat(order.total_amount) || 0),
              0,
            ) || 0;

          return {
            branch_id: branch.id,
            branch_name: branch.name,
            branch_code: branch.code,
            appointments: (await appointments).count || 0,
            quotes: (await quotes).count || 0,
            work_orders: (await workOrders).count || 0,
            orders: (await orders).count || 0,
            revenue: branchRevenue,
          };
        }),
      ),
    ]);

    // Calculate total revenue
    const revenueData = await totalRevenue;
    const globalRevenue =
      revenueData.data?.reduce(
        (sum: number, order: unknown) =>
          sum + (parseFloat(order.total_amount) || 0),
        0,
      ) || 0;

    const globalStats = {
      is_global: true,
      branches_count: branches?.length || 0,
      appointments: {
        total: totalAppointments.count || 0,
      },
      quotes: {
        total: totalQuotes.count || 0,
      },
      work_orders: {
        total: totalWorkOrders.count || 0,
      },
      orders: {
        total: totalOrders.count || 0,
      },
      revenue: {
        total: globalRevenue,
      },
      branches: await branchesStats,
    };

    return NextResponse.json({ stats: globalStats });
  } catch (error: unknown) {
    logger.error("Error in GET /api/admin/branches/global/stats:", { error });
    return NextResponse.json(
      { error: error.message || "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import { validateTierLimit } from "@/lib/saas/tier-validator";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    const supabase = await createClient();
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    // Get branch context
    const branchContext = await getBranchContext(request, user.id);

    // Get user's organization_id to filter branches appropriately
    const { data: adminUser } = await supabase
      .from("admin_users")
      .select("organization_id")
      .eq("id", user.id)
      .single();

    const userOrganizationId = adminUser?.organization_id;

    // Get all branches (super admin) or user's accessible branches
    let branches;

    if (branchContext.isSuperAdmin) {
      // Super admin: filter by organization if user belongs to one
      // Only true global super admins (no organization) see all branches
      let query = supabase.from("branches").select("*");

      if (userOrganizationId) {
        // Super admin with organization: only show branches from their organization
        query = query.eq("organization_id", userOrganizationId);
      }
      // If no organization_id, show all branches (true global super admin)
      // We'll filter out the global "Sucursal Principal" (code='MAIN' without organization_id) after fetching

      const { data, error } = await query.order("name");

      if (error) {
        logger.error("Error fetching branches", error);
        return NextResponse.json(
          { error: "Failed to fetch branches" },
          { status: 500 },
        );
      }

      // Filter out the global "Sucursal Principal" (legacy branch without organization_id)
      // This branch should only be visible to true global super admins managing legacy data
      branches = (data || []).filter(
        (b) => !(b.code === "MAIN" && !b.organization_id),
      );
    } else {
      // Regular admin sees only their accessible branches
      branches = branchContext.accessibleBranches.map((b) => ({
        id: b.id,
        name: b.name,
        code: b.code,
        role: b.role,
        is_primary: b.isPrimary,
      }));

      // Fetch full branch details
      if (branches.length > 0) {
        const branchIds = branches.map((b) => b.id);
        const { data: branchDetails, error } = await supabase
          .from("branches")
          .select("*")
          .in("id", branchIds)
          .order("name");

        if (!error && branchDetails) {
          // Merge with access info
          branches = branchDetails.map((bd) => {
            const access = branchContext.accessibleBranches.find(
              (a) => a.id === bd.id,
            );
            return {
              ...bd,
              role: access?.role,
              is_primary: access?.isPrimary,
            };
          });
        }
      }
    }

    return NextResponse.json({
      branches: branches || [],
      currentBranch: branchContext.branchId,
      isGlobalView: branchContext.isGlobalView,
      isSuperAdmin: branchContext.isSuperAdmin,
      organizationId: userOrganizationId ?? null,
    });
  } catch (error: unknown) {
    logger.error("Error in GET /api/admin/branches", error);
    return NextResponse.json(
      { error: error.message || "Internal server error" },
      { status: 500 },
    );
  }
}

export async function POST(request: NextRequest) {
  try {
    const supabase = await createClient();
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const body = await request.json();

    // Handle branch selection (set_branch action)
    if (body.action === "set_branch") {
      // This is just a notification, no need to do anything server-side
      // The branch context is managed client-side via localStorage
      return NextResponse.json({ success: true });
    }

    // Check if user is super admin for branch creation
    const { data: isSuperAdminRPC } = await supabase.rpc("is_super_admin", {
      user_id: user.id,
    });
    if (!isSuperAdminRPC) {
      return NextResponse.json(
        { error: "Only super admins can create branches" },
        { status: 403 },
      );
    }

    const {
      name,
      code,
      address_line_1,
      address_line_2,
      city,
      state,
      postal_code,
      country,
      phone,
      email,
      settings,
    } = body;

    // Validate required fields
    if (!name || !code) {
      return NextResponse.json(
        { error: "Name and code are required" },
        { status: 400 },
      );
    }

    // Resolve organization_id for the new branch (required for tier validation and insert)
    const { data: adminUserForOrg } = await supabase
      .from("admin_users")
      .select("organization_id")
      .eq("id", user.id)
      .single();
    const organizationId =
      body.organization_id ?? adminUserForOrg?.organization_id;

    if (organizationId) {
      const branchLimit = await validateTierLimit(organizationId, "branches");
      if (!branchLimit.allowed) {
        return NextResponse.json(
          {
            error:
              branchLimit.reason ??
              "Límite de sucursales alcanzado para tu plan",
            code: "TIER_LIMIT",
            currentCount: branchLimit.currentCount,
            maxAllowed: branchLimit.maxAllowed,
          },
          { status: 403 },
        );
      }
    }

    // Check if code already exists (scoped by organization if applicable)
    let codeQuery = supabase.from("branches").select("id").eq("code", code);
    if (organizationId) {
      codeQuery = codeQuery.eq("organization_id", organizationId);
    }
    const { data: existingBranch } = await codeQuery.single();

    if (existingBranch) {
      return NextResponse.json(
        { error: "Branch code already exists" },
        { status: 400 },
      );
    }

    // Create branch (with organization_id when available)
    const insertPayload: Record<string, unknown> = {
      name,
      code,
      address_line_1,
      address_line_2,
      city,
      state,
      postal_code,
      country,
      phone,
      email,
      settings: settings || {},
      is_active: true,
    };
    if (organizationId) {
      insertPayload.organization_id = organizationId;
    }

    const { data: newBranch, error } = await supabase
      .from("branches")
      .insert(insertPayload)
      .select()
      .single();

    if (error) {
      logger.error("Error creating branch", error);
      return NextResponse.json(
        { error: "Failed to create branch" },
        { status: 500 },
      );
    }

    return NextResponse.json({ branch: newBranch }, { status: 201 });
  } catch (error: unknown) {
    logger.error("Error in POST /api/admin/branches", error);
    return NextResponse.json(
      { error: error.message || "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { handleClosureError } from "@/lib/cash-register/_helpers/closure-types";
import {
  alignDateWithSession,
  calculateCashInflowsOutflows,
  calculateOrderTotals,
} from "@/lib/cash-register/_helpers/closure-utils";
import {
  aggregateClosurePayments,
  getClosureContext,
  getClosureOrders,
  getOpenSession,
  getPreviousClosure,
  getSessionPayments,
  resolveGetSession,
} from "@/lib/cash-register/closure-service";
import type { PaymentAggregatorInput } from "@/lib/cash-register/payment-aggregator";
import { appLogger as logger } from "@/lib/logger";

/**
 * GET /api/admin/cash-register/close
 * Get daily sales summary for cash register closure
 */
export async function GET(request: NextRequest) {
  try {
    const ctx = await getClosureContext(request);

    // Parse date from query params (default to today)
    const { searchParams } = new URL(request.url);
    const dateParam = searchParams.get("date");
    const closureDate = dateParam ? new Date(dateParam) : new Date();
    let dateStr = closureDate.toISOString().split("T")[0];

    // Align summary date with the currently open session if it differs
    const openSession = await getOpenSession(ctx);
    const alignedDate = alignDateWithSession(dateStr, openSession);
    if (alignedDate !== dateStr) {
      logger.warn("Summary date does not match open session date", {
        requestedDate: dateStr,
        sessionDate: alignedDate,
        branchId: ctx.effectiveBranchId,
      });
      dateStr = alignedDate;
    }

    // Regular admin without branch selected — return empty summary
    if (!ctx.effectiveBranchId && !ctx.isSuperAdmin) {
      return NextResponse.json({
        summary: {
          date: dateStr,
          branch_id: null,
          total_sales: 0,
          total_transactions: 0,
          cash_sales: 0,
          debit_card_sales: 0,
          credit_card_sales: 0,
          installments_sales: 0,
          other_payment_sales: 0,
          total_subtotal: 0,
          total_tax: 0,
          total_discounts: 0,
          orders: [],
        },
      });
    }

    // Fetch POS orders of the day
    const orders = await getClosureOrders(ctx, dateStr);

    // Session fallback: open → any session for this date
    const { sessionId } = await resolveGetSession(ctx, dateStr);

    // Payments + opening cash for resolved session
    let openingCash = 0;
    let sessionPayments: PaymentAggregatorInput["sessionPayments"] = [];
    if (sessionId) {
      const sd = await getSessionPayments(ctx, sessionId);
      openingCash = sd.openingCash;
      sessionPayments = sd.sessionPayments;
    }

    // Build summary
    const summary = {
      date: dateStr,
      branch_id: ctx.effectiveBranchId,
      field_operation_id: ctx.fieldOperationId || null,
      total_sales: 0,
      total_transactions:
        sessionPayments.length > 0 ? sessionPayments.length : orders.length,
      cash_sales: 0,
      debit_card_sales: 0,
      credit_card_sales: 0,
      transfer_sales: 0,
      installments_sales: 0,
      other_payment_sales: 0,
      total_subtotal: 0,
      total_tax: 0,
      total_discounts: 0,
      orders,
    };

    // Order totals (exclude cancelled)
    const orderTotals = calculateOrderTotals(orders);
    summary.total_sales = orderTotals.totalSales;
    summary.total_subtotal = orderTotals.totalSubtotal;
    summary.total_tax = orderTotals.totalTax;
    summary.total_discounts = orderTotals.totalDiscounts;

    // Cash inflows/outflows tracking
    const { cashInflows, cashOutflows } =
      sessionPayments.length > 0
        ? calculateCashInflowsOutflows(sessionPayments)
        : { cashInflows: 0, cashOutflows: 0 };

    // 3-tier payment aggregation
    const ps = await aggregateClosurePayments(ctx, sessionPayments, orders);
    summary.cash_sales = ps.cash_sales;
    summary.debit_card_sales = ps.debit_card_sales;
    summary.credit_card_sales = ps.credit_card_sales;
    summary.transfer_sales = ps.transfer_sales;
    summary.installments_sales = ps.installments_sales;
    summary.other_payment_sales = ps.other_payment_sales;

    // Previous closure (draft / reopened)
    const previousClosure = await getPreviousClosure(ctx, dateStr);

    return NextResponse.json({
      summary: {
        ...summary,
        opening_cash_amount: openingCash,
        expected_cash: openingCash + summary.cash_sales,
        session_payments_count: sessionPayments.length,
        cash_inflows: cashInflows,
        cash_outflows: cashOutflows,
      },
      previous_closure: previousClosure,
    });
  } catch (error: unknown) {
    return handleClosureError(error);
  }
}

import { NextRequest, NextResponse } from "next/server";

import {
