    if (opening_cash_amount === undefined || opening_cash_amount === null) {
      return NextResponse.json(
        { error: "El monto inicial de caja es requerido" },
        { status: 400 },
      );
    }

    let dateStr = closure_date.split("T")[0];

    // Branch validation
    if (!ctx.effectiveBranchId && !ctx.isSuperAdmin) {
      return NextResponse.json(
        { error: "Debe seleccionar una sucursal para cerrar la caja" },
        { status: 400 },
      );
    }

    // Open session + date alignment
    const openSession = await getOpenSession(ctx);
    const alignedDate = alignDateWithSession(dateStr, openSession);
    if (alignedDate !== dateStr) {
      logger.warn("Closure date does not match session date", {
        requestedDate: dateStr,
        sessionDate: alignedDate,
        sessionId: openSession?.id,
        branchId: ctx.effectiveBranchId,
      });
      dateStr = alignedDate;
    }

    // Resolve session ID
    let sessionIdForClosure = openSession?.id || null;

    if (!sessionIdForClosure && ctx.effectiveBranchId) {
      let existingClosureQuery = ctx.supabaseServiceRole
        .from("cash_register_closures")
        .select("pos_session_id")
        .eq("branch_id", ctx.effectiveBranchId)
        .eq("closure_date", dateStr);

      if (ctx.fieldOperationId) {
        existingClosureQuery = existingClosureQuery.eq(
          "field_operation_id",
          ctx.fieldOperationId,
        );
      } else {
        existingClosureQuery = existingClosureQuery.is(
          "field_operation_id",
          null,
        );
      }

      const { data: existingClosure } =
        await existingClosureQuery.maybeSingle();

      if (existingClosure?.pos_session_id) {
        sessionIdForClosure = existingClosure.pos_session_id;
        logger.info("Using session from existing closure", {
          sessionId: sessionIdForClosure,
        });
      }
    }

    // Close the open session
    if (openSession) {
      const { error: closeSessionError } = await ctx.supabaseServiceRole
        .from("pos_sessions")
        .update({
          status: "closed",
          closing_time: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        })
        .eq("id", openSession.id)
        .eq("status", "open");

      if (closeSessionError) {
        logger.error("Error closing POS session", closeSessionError);
      } else {
        logger.info("Closed POS session", {
          sessionId: openSession.id,
          reopenCount: openSession.reopen_count,
        });
      }
    }

    // Orders + payments
    const orders = await getClosureOrders(ctx, dateStr);

    let sessionPayments: PaymentAggregatorInput["sessionPayments"] = [];
    if (sessionIdForClosure) {
      const sd = await getSessionPayments(ctx, sessionIdForClosure, {
        includeOrderDetails: true,
      });
      sessionPayments = sd.sessionPayments;
    }

    // Order totals
    const orderTotals = calculateOrderTotals(orders);

    // Payment aggregation
    const pr = await aggregateClosurePayments(ctx, sessionPayments, orders);
    const cashSales = pr.cash_sales;
    const debitCardSales = pr.debit_card_sales;
    const creditCardSales = pr.credit_card_sales;
    const transferSales = pr.transfer_sales;
    const installmentsSales = pr.installments_sales;
    const otherPaymentSales = pr.other_payment_sales;

    // Differences
    const expectedCash = Number(opening_cash_amount) + cashSales;
    const actualCashValue =
      actual_cash !== undefined && actual_cash !== null
        ? Number(actual_cash)
        : null;
    const cashDifference =
      actualCashValue !== null ? actualCashValue - expectedCash : 0;

    logger.info("Cash difference calculation", {
      opening_cash_amount: Number(opening_cash_amount),
      cashSales,
      expectedCash,
      actual_cash: actualCashValue,
      cashDifference,
    });

    const cardMachineDebitDifference =
      card_machine_debit_total !== undefined &&
      card_machine_debit_total !== null
        ? Number(card_machine_debit_total) - debitCardSales
        : 0;
    const cardMachineCreditDifference =
      card_machine_credit_total !== undefined &&
      card_machine_credit_total !== null
        ? Number(card_machine_credit_total) - creditCardSales
        : 0;
    const cardMachineDifference =
      cardMachineDebitDifference + cardMachineCreditDifference;

    const openedAt = openSession?.opening_time
      ? new Date(openSession.opening_time)
      : new Date(`${dateStr}T00:00:00`);

    // Pre-insert validations
    if (!ctx.effectiveBranchId) {
      logger.error("branch_id is null when trying to create closure", {
        isSuperAdmin: ctx.isSuperAdmin,
        branchId: ctx.effectiveBranchId,
      });
      return NextResponse.json(
        { error: "Debe seleccionar una sucursal para cerrar la caja" },
        { status: 400 },
      );
    }
    if (!ctx.userId) {
      logger.error("user.id is null when trying to create closure");
      return NextResponse.json(
        { error: "Error de autenticación" },
        { status: 401 },
      );
    }

    // Check existing closure
    let existingClosureQuery = ctx.supabaseServiceRole
      .from("cash_register_closures")
      .select("id, status, pos_session_id")
      .eq("branch_id", ctx.effectiveBranchId)
      .eq("closure_date", dateStr);

    if (ctx.fieldOperationId) {
      existingClosureQuery = existingClosureQuery.eq(
        "field_operation_id",
        ctx.fieldOperationId,
      );
    } else {
      existingClosureQuery = existingClosureQuery.is("field_operation_id", null);
    }

    const { data: existingClosure, error: existingClosureError } =
      await existingClosureQuery.maybeSingle();

    if (existingClosureError) {
      logger.error("Error checking existing closure:", {
        error: existingClosureError.message || existingClosureError,
        code: existingClosureError.code,
        details: existingClosureError.details,
        branchId: ctx.effectiveBranchId,
        dateStr,
      });
      return NextResponse.json(
        {
          error: "Error al verificar cierres existentes",
          details: existingClosureError.message,
        },
        { status: 500 },
      );
    }

    const canUpdateClosedClosure =
      existingClosure &&
      existingClosure.status === "closed" &&
      openSession &&
      (!existingClosure.pos_session_id ||
        existingClosure.pos_session_id === openSession.id);

    if (existingClosure && existingClosure.status === "closed") {
      if (!canUpdateClosedClosure) {
        return NextResponse.json(
          { error: "Ya existe un cierre de caja para esta fecha y sucursal" },
          { status: 400 },
        );
      }
      logger.warn("Updating a closed closure due to open session", {
        closureId: existingClosure.id,
        sessionId: openSession?.id,
        branchId: ctx.effectiveBranchId,
        dateStr,
      });
    }

    // Build closure payload
    const closureParams = buildClosureInput({
      branch_id: ctx.effectiveBranchId,
      closure_date: dateStr,
      closed_by: ctx.userId,
      pos_session_id: sessionIdForClosure || null,
      field_operation_id: ctx.fieldOperationId || undefined,
      opening_cash_amount: Number(opening_cash_amount),
      totalSales: orderTotals.totalSales,
      totalTransactions:
        sessionPayments.length > 0
          ? sessionPayments.length
          : orders.length,
      cashSales,
      debitCardSales,
      creditCardSales,
      installmentsSales,
      otherPaymentSales,
      transferSales,
      expectedCash,
      actual_cash,
      cashDifference,
      card_machine_debit_total,
      card_machine_credit_total,
      cardMachineDifference,
      totalSubtotal: orderTotals.totalSubtotal,
      totalTax: orderTotals.totalTax,
      totalDiscounts: orderTotals.totalDiscounts,
      notes: notes || null,
      discrepancies: discrepancies || null,
      openedAt: openedAt.toISOString(),
    });
    const closureData = buildClosurePayload(closureParams);

    logger.info("Preparing to create/update closure", {
      existingClosure: existingClosure
        ? { id: existingClosure.id, status: existingClosure.status }
        : null,
      closureData: {
        ...closureData,
        closed_by: ctx.userId.substring(0, 8) + "...",
      },
    });

    // Create or update closure
    let closureResponse;
    if (existingClosure && existingClosure.status !== "closed") {
      logger.info("Updating existing closure", {
        closureId: existingClosure.id,
        currentStatus: existingClosure.status,
        newStatus: "closed",
      });
      closureResponse = await ctx.supabaseServiceRole
        .from("cash_register_closures")
        .update(closureData)
        .eq("id", existingClosure.id)
        .select()
        .single();
    } else if (canUpdateClosedClosure && existingClosure) {
      closureResponse = await ctx.supabaseServiceRole
        .from("cash_register_closures")
        .update(closureData)
        .eq("id", existingClosure.id)
        .select()
        .single();
    } else {
      logger.info("Inserting new closure", {
        branchId: ctx.effectiveBranchId,
        fieldOperationId: ctx.fieldOperationId || undefined,
        closureDate: dateStr,
      });
      closureResponse = await ctx.supabaseServiceRole
        .from("cash_register_closures")
        .insert(closureData)
        .select()
        .single();
    }

    const { data: closure, error: closureError } = closureResponse;

    if (closureError) {
      logger.error("Error creating cash register closure:", {
        error: closureError.message || closureError,
        code: closureError.code,
        details: closureError.details,
        hint: closureError.hint,
        closureDate: closure_date,
        branchId: ctx.effectiveBranchId,
        existingClosure: existingClosure
          ? { id: existingClosure.id, status: existingClosure.status }
          : null,
        closureData: {
          ...closureData,
          closed_by: ctx.userId.substring(0, 8) + "...",
        },
      });
      return NextResponse.json(
        {
          error: "Error al crear el cierre de caja",
          details: closureError.message,
          code: closureError.code,
          hint: closureError.hint,
        },
        { status: 500 },
      );
    }

    return NextResponse.json({ success: true, closure });
  } catch (error: unknown) {
    logger.error("Error in cash register closure POST API:", { error });
    return NextResponse.json(
      {
        error: "Internal server error",
        details: (error as Error).message,
      },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import {
  getBranchContext,
  validateBranchAccess,
} from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

/**
 * GET /api/admin/cash-register/closures/[id]
 * Get a specific cash register closure with details
 */
export const dynamic = "force-dynamic";
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params;
  try {
    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    // Get closure
    const { data: closure, error } = await supabase
      .from("cash_register_closures")
      .select(
        `
        *,
        branch:branches(id, name, code)
      `,
      )
      .eq("id", id)
      .single<Record<string, unknown>>();

    if (error || !closure) {
      return NextResponse.json(
        {
          error: "Cierre de caja no encontrado",
        },
        { status: 404 },
      );
    }

    // Fetch user profile separately
    let closedByUser = null;
    if (closure.closed_by) {
      const { data: profile } = await supabase
        .from("profiles")
        .select("id, first_name, last_name")
        .eq("id", closure.closed_by)
        .single<{ id: string; first_name: string | null; last_name: string | null }>();

      closedByUser = profile;
    }

    const closureWithUser = {
      ...closure,
      closed_by_user: closedByUser,
    };

    // Validate branch access
    const branchContext = await getBranchContext(request, user.id);
    const hasAccess = await validateBranchAccess(user.id, closure.branch_id);

    if (!hasAccess) {
      return NextResponse.json(
        {
          error: "No tiene acceso a este cierre de caja",
        },
        { status: 403 },
      );
    }

    // Get orders for this closure date
    const dateStr = closure.closure_date;
    const ordersQuery = supabase
      .from("orders")
      .select(
        `
        *,
        order_items(*)
      `,
      )
      .eq("is_pos_sale", true)
      .eq("branch_id", closure.branch_id)
      .gte("created_at", `${dateStr}T00:00:00`)
      .lt("created_at", `${dateStr}T23:59:59`)
      .order("created_at", { ascending: false })
      .returns<Record<string, unknown>[]>();

    const { data: orders } = await ordersQuery;

    return NextResponse.json({
      closure: closureWithUser,
      orders: orders || [],
    });
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : "Unknown error";
    logger.error("Error fetching cash register closure:", {
      error,
      closureId: id,
    });
    return NextResponse.json(
      {
        error: "Internal server error",
        details: message,
      },
      { status: 500 },
    );
  }
}

/**
 * PUT /api/admin/cash-register/closures/[id]
 * Update a cash register closure (e.g., confirm, add notes)
 */
export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params;
  try {
    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    const body = await request.json();

    // Get existing closure
    const { data: existingClosure } = await supabase
      .from("cash_register_closures")
      .select("branch_id, status")
      .eq("id", id)
      .single<{ branch_id: string; status: string }>();

    if (!existingClosure) {
      return NextResponse.json(
        { error: "Cierre de caja no encontrado" },
        { status: 404 },
      );
    }

    // Validate branch access
    const branchContext = await getBranchContext(request, user.id);
    const hasAccess = await validateBranchAccess(
      user.id,
      existingClosure.branch_id,
    );

    if (!hasAccess) {
      return NextResponse.json(
        {
          error: "No tiene acceso a este cierre de caja",
        },
        { status: 403 },
      );
    }

    // Prepare update data
    const updateData: unknown = {
      updated_at: new Date().toISOString(),
    };

    if (body.actual_cash !== undefined)
      updateData.actual_cash = Number(body.actual_cash);
    if (body.card_machine_debit_total !== undefined)
      updateData.card_machine_debit_total = Number(
        body.card_machine_debit_total,
      );
    if (body.card_machine_credit_total !== undefined)
      updateData.card_machine_credit_total = Number(
        body.card_machine_credit_total,
      );
    if (body.notes !== undefined) updateData.notes = body.notes;
    if (body.discrepancies !== undefined)
      updateData.discrepancies = body.discrepancies;
    if (body.status !== undefined) {
      updateData.status = body.status;
      if (body.status === "confirmed") {
        updateData.confirmed_at = new Date().toISOString();
      }
    }

    // Recalculate differences if cash amounts changed
    if (
      body.actual_cash !== undefined ||
      body.card_machine_debit_total !== undefined ||
      body.card_machine_credit_total !== undefined
    ) {
      const expectedCash =
        Number((existingClosure as unknown).opening_cash_amount || 0) +
        Number((existingClosure as unknown).cash_sales || 0);
      if (updateData.actual_cash !== undefined) {
        updateData.cash_difference =
          Number(updateData.actual_cash) - expectedCash;
        updateData.closing_cash_amount = Number(updateData.actual_cash);
      }

      if (
        updateData.card_machine_debit_total !== undefined ||
        updateData.card_machine_credit_total !== undefined
      ) {
        const debitTotal =
          updateData.card_machine_debit_total !== undefined
            ? Number(updateData.card_machine_debit_total)
            : Number(
                (existingClosure as unknown).card_machine_debit_total || 0,
              );
        const creditTotal =
          updateData.card_machine_credit_total !== undefined
            ? Number(updateData.card_machine_credit_total)
            : Number(
                (existingClosure as unknown).card_machine_credit_total || 0,
              );
        const expectedDebit = Number(
          (existingClosure as unknown).debit_card_sales || 0,
        );
        const expectedCredit = Number(
          (existingClosure as unknown).credit_card_sales || 0,
        );
        updateData.card_machine_difference =
          debitTotal - expectedDebit + (creditTotal - expectedCredit);
      }
    }

    // Update closure
    const { data: updatedClosure, error: updateError } =
      await supabase
        .from("cash_register_closures")
        .update(updateData)
        .eq("id", id)
        .select(
          `
        *,
        branch:branches(id, name, code)
      `,
        )
        .single<Record<string, unknown>>();

    if (updateError) {
      logger.error("Error updating closure:", {
        error: updateError,
        closureId: id,
      });
      return NextResponse.json(
        {
          error: "Error al actualizar el cierre de caja",
          details: updateError.message,
        },
        { status: 500 },
      );
    }

    // Fetch user profile separately
    let closedByUser = null;
    if (updatedClosure.closed_by) {
      const { data: profile } = await supabase
        .from("profiles")
        .select("id, first_name, last_name")
        .eq("id", updatedClosure.closed_by)
        .single<{ id: string; first_name: string | null; last_name: string | null }>();

      closedByUser = profile;
    }

    const closureWithUser = {
      ...updatedClosure,
      closed_by_user: closedByUser,
    };

    return NextResponse.json({
      success: true,
      closure: closureWithUser,
    });
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : "Unknown error";
    logger.error("Error updating cash register closure:", {
      error,
      closureId: id,
    });
    return NextResponse.json(
      {
        error: "Internal server error",
        details: message,
      },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import {
  getBranchContext,
  getFieldOperationFromRequest,
  validateBranchAccess,
} from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

/**
 * GET /api/admin/cash-register/closures
 * Get list of cash register closures
 */
export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    // Get branch context and optional operativo context
    const branchContext = await getBranchContext(request, user.id);
    const fieldOperationId =
      getFieldOperationFromRequest(request) ||
      new URL(request.url).searchParams.get("field_operation_id");

    let effectiveBranchId = branchContext.branchId;
    if (fieldOperationId) {
      const { data: fieldOp } = await supabase
        .from("field_operations")
        .select("id, branch_id")
        .eq("id", fieldOperationId)
        .single<{ id: string; branch_id: string }>();
      if (!fieldOp) {
        return NextResponse.json({
          closures: [],
          pagination: { page: 1, limit: 50, total: 0, totalPages: 0 },
        });
      }
      const hasAccess = await validateBranchAccess(user.id, fieldOp.branch_id);
      if (!hasAccess) {
        return NextResponse.json({
          closures: [],
          pagination: { page: 1, limit: 50, total: 0, totalPages: 0 },
        });
      }
      effectiveBranchId = fieldOp.branch_id;
    }

    // Get query params
    const { searchParams } = new URL(request.url);
    const limit = parseInt(searchParams.get("limit") || "50");
    const offset = parseInt(searchParams.get("offset") || "0");
    const startDate = searchParams.get("start_date");
    const endDate = searchParams.get("end_date");

    // Build query
    let query = supabase
      .from("cash_register_closures")
      .select(
        `
        *,
        branch:branches(id, name, code)
      `,
        { count: "exact" },
      )
      .order("closure_date", { ascending: false })
      .order("closed_at", { ascending: false });

    // Apply branch filter
    if (effectiveBranchId) {
      query = query.eq("branch_id", effectiveBranchId);
      if (fieldOperationId) {
        query = query.eq("field_operation_id", fieldOperationId);
      } else {
        query = query.is("field_operation_id", null);
      }
    } else if (!branchContext.isSuperAdmin) {
      // Regular admin without branch - return empty
      return NextResponse.json({
        closures: [],
        pagination: {
          page: 1,
          limit,
          total: 0,
          totalPages: 0,
        },
      });
    }

    // Apply date filters
    if (startDate) {
      query = query.gte("closure_date", startDate);
    }
    if (endDate) {
      query = query.lte("closure_date", endDate);
    }

    const {
      data: closures,
      error,
      count,
    } = await query.range(offset, offset + limit - 1);

    if (error) {
      logger.error("Error fetching closures:", {
        error,
        branchId: branchContext.branchId,
      });
      return NextResponse.json(
        {
          error: "Error al obtener cierres de caja",
          details: error.message,
        },
        { status: 500 },
      );
    }

    // Fetch user profiles separately
    const closuresWithUsers = await Promise.all(
      (closures || []).map(async (closure: unknown) => {
        if (closure.closed_by) {
          const { data: profile } = await supabase
            .from("profiles")
            .select("id, first_name, last_name")
            .eq("id", closure.closed_by)
            .single<{ id: string; first_name: string | null; last_name: string | null }>();

          return {
            ...closure,
            closed_by_user: profile || null,
          };
        }
        return {
          ...closure,
          closed_by_user: null,
        };
      }),
    );

    return NextResponse.json({
      closures: closuresWithUsers,
      pagination: {
        page: Math.floor(offset / limit) + 1,
        limit,
        total: count || 0,
        totalPages: Math.ceil((count || 0) / limit),
      },
    });
  } catch (error: unknown) {
    logger.error("Error in cash register closures API:", { error });
    return NextResponse.json(
      {
        error: "Internal server error",
        details: error.message,
      },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";

