export const dynamic = "force-dynamic";
export async function POST(request: NextRequest) {
  try {
    return await (withRateLimit(rateLimitConfigs.modification) as unknown)(
      request,
      async () => {
        const supabase = await createClient();

        // Check admin authorization
        const {
          data: { user },
          error: userError,
        } = await supabase.auth.getUser();
        if (userError || !user) {
          return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        const { data: isAdmin } = (await supabase.rpc("is_admin", {
          user_id: user.id,
        } as IsAdminParams)) as {
          data: IsAdminResult | null;
          error: Error | null;
        };
        if (!isAdmin) {
          return NextResponse.json(
            { error: "Admin access required" },
            { status: 403 },
          );
        }

        // Get branch context and optional operativo context
        const branchContext = await getBranchContext(request, user.id);
        let body: Record<string, unknown> = {};
        try {
          body = await request.json();
        } catch {
          // Empty body ok
        }
        const fieldOperationId =
          getFieldOperationFromRequest(request) ||
          (body?.field_operation_id as string | undefined) ||
          null;

        let effectiveBranchId = branchContext.branchId;

        // Operativo mode: resolve branch from field_operations
        if (fieldOperationId) {
          const { data: fieldOp, error: fieldOpError } =
            await supabase
              .from("field_operations")
              .select("id, branch_id")
              .eq("id", fieldOperationId)
              .single();

          if (fieldOpError || !fieldOp) {
            return NextResponse.json(
              { error: "Operativo no encontrado" },
              { status: 404 },
            );
          }

          const hasAccess = await validateBranchAccess(
            user.id,
            fieldOp.branch_id,
          );
          if (!hasAccess) {
            return NextResponse.json(
              { error: "No tiene acceso a este operativo" },
              { status: 403 },
            );
          }
          effectiveBranchId = fieldOp.branch_id;
        }

        // Validate branch for non-super admins
        if (!branchContext.isSuperAdmin && !effectiveBranchId) {
          return NextResponse.json(
            {
              error: fieldOperationId
                ? "Operativo inválido"
                : "Debe seleccionar una sucursal para abrir la caja",
            },
            { status: 400 },
          );
        }

        // Parse and validate request body
        const validatedData = openCashRegisterSchema.parse(body);

        // Build session query: branch + optional field_operation_id
        let sessionQuery = supabase
          .from("pos_sessions")
          .select("id, status, opening_time")
          .eq("branch_id", effectiveBranchId!)
          .eq("status", "open");

        if (fieldOperationId) {
          sessionQuery = sessionQuery.eq(
            "field_operation_id",
            fieldOperationId,
          );
        } else {
          sessionQuery = sessionQuery.is("field_operation_id", null);
        }

        const { data: existingSession, error: checkError } = await sessionQuery
          .order("opening_time", { ascending: false })
          .limit(1)
          .maybeSingle();

        if (checkError && checkError.code !== "PGRST116") {
          logger.error("Error checking existing session", checkError);
          return NextResponse.json(
            { error: "Error al verificar sesión existente" },
            { status: 500 },
          );
        }

        if (existingSession) {
          return NextResponse.json(
            {
              error: fieldOperationId
                ? "Ya existe una caja abierta para este operativo"
                : "Ya existe una caja abierta para esta sucursal",
              session: existingSession,
            },
            { status: 400 },
          );
        }

        const todayStr = new Date().toISOString().split("T")[0];
        let closureQuery = supabase
          .from("cash_register_closures")
          .select("id, status")
          .eq("branch_id", effectiveBranchId!)
          .eq("closure_date", todayStr);

        if (fieldOperationId) {
          closureQuery = closureQuery.eq(
            "field_operation_id",
            fieldOperationId,
          );
        } else {
          closureQuery = closureQuery.is("field_operation_id", null);
        }

        const { data: existingClosure, error: closureError } =
          await closureQuery.maybeSingle();

        if (closureError && closureError.code !== "PGRST116") {
          logger.error("Error checking existing closure", closureError);
          return NextResponse.json(
            { error: "Error al verificar cierres existentes" },
            { status: 500 },
          );
        }

        if (existingClosure?.status === "closed") {
          return NextResponse.json(
            {
              error:
                "La caja ya fue cerrada hoy. Debe reabrirla para continuar.",
            },
            { status: 400 },
          );
        }

        // Create new POS session
        const insertData: Record<string, unknown> = {
          cashier_id: user.id,
          branch_id: effectiveBranchId!,
          opening_cash_amount: validatedData.opening_cash_amount,
          status: "open",
          opening_time: new Date().toISOString(),
        };
        if (fieldOperationId) {
          insertData.field_operation_id = fieldOperationId;
        }

        const { data: newSession, error: sessionError } =
          await supabase
            .from("pos_sessions")
            .insert(insertData)
            .select()
            .single();

        if (sessionError) {
          logger.error("Error creating POS session", sessionError);
          return NextResponse.json(
            { error: "Error al abrir la caja" },
            { status: 500 },
          );
        }

        logger.info("Cash register opened successfully", {
          sessionId: newSession.id,
          branchId: effectiveBranchId,
          fieldOperationId: fieldOperationId || undefined,
          openingCash: validatedData.opening_cash_amount,
        });

        return createApiSuccessResponse({
          session: newSession,
          message: "Caja abierta exitosamente",
        });
      },
    );
  } catch (error) {
    if (error instanceof z.ZodError) {
      return NextResponse.json(
        {
          error: "Validation failed",
          details: error.errors,
        },
        { status: 400 },
      );
    }

    logger.error("Error in cash register open API", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

export async function GET(request: NextRequest) {
  try {
    return await (withRateLimit(rateLimitConfigs.modification) as unknown)(
      request,
      async () => {
        const supabase = await createClient();

        // Check admin authorization
        const {
          data: { user },
          error: userError,
        } = await supabase.auth.getUser();
        if (userError || !user) {
          return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        const { data: isAdmin } = (await supabase.rpc("is_admin", {
          user_id: user.id,
        } as IsAdminParams)) as {
          data: IsAdminResult | null;
          error: Error | null;
        };
        if (!isAdmin) {
          return NextResponse.json(
            { error: "Admin access required" },
            { status: 403 },
          );
        }

        // Get branch context and optional operativo context
        const branchContext = await getBranchContext(request, user.id);
        const fieldOperationId = getFieldOperationFromRequest(request);

        let effectiveBranchId = branchContext.branchId;

        // Operativo mode: resolve branch from field_operations
        if (fieldOperationId) {
          const { data: fieldOp, error: fieldOpError } =
            await supabase
              .from("field_operations")
              .select("id, branch_id")
              .eq("id", fieldOperationId)
              .single();

          if (fieldOpError || !fieldOp) {
            return createApiSuccessResponse({
              isOpen: false,
              session: null,
            });
          }

          const hasAccess = await validateBranchAccess(
            user.id,
            fieldOp.branch_id,
          );
          if (!hasAccess) {
            return createApiSuccessResponse({
              isOpen: false,
              session: null,
            });
          }
          effectiveBranchId = fieldOp.branch_id;
        }

        // No branch: return closed state so POS can load
        if (!effectiveBranchId) {
          return createApiSuccessResponse({
            isOpen: false,
            session: null,
          });
        }

        // Check if there's an open session (branch or operativo)
        let sessionQuery = supabase
          .from("pos_sessions")
          .select(
            "id, status, opening_time, opening_cash_amount, branch_id, field_operation_id",
          )
          .eq("branch_id", effectiveBranchId)
          .eq("status", "open");

        if (fieldOperationId) {
          sessionQuery = sessionQuery.eq(
            "field_operation_id",
            fieldOperationId,
          );
        } else {
          sessionQuery = sessionQuery.is("field_operation_id", null);
        }

        const { data: openSession, error: sessionError } = await sessionQuery
          .order("opening_time", { ascending: false })
          .limit(1)
          .maybeSingle();

        if (sessionError) {
          logger.error("Error checking open session", sessionError);
          return NextResponse.json(
            {
              error: "Error al verificar estado de caja",
              details:
                process.env.NODE_ENV === "development"
                  ? sessionError.message
                  : undefined,
            },
            { status: 500 },
          );
        }

        return createApiSuccessResponse({
          isOpen: !!openSession,
          session: openSession || null,
        });
      },
    );
  } catch (error: unknown) {
    logger.error("Error in cash register open GET API", error);
    const message =
      error instanceof Error ? error.message : "Internal server error";
    return NextResponse.json(
      {
        error: "Internal server error",
        ...(process.env.NODE_ENV === "development" && { details: message }),
      },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import type {
  GetAdminRoleParams,
  GetAdminRoleResult,
  IsAdminParams,
  IsAdminResult,
} from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

/**
 * POST /api/admin/cash-register/reopen
 * Reopen a closed cash register session (admin or super_admin)
 */
export const dynamic = "force-dynamic";
export async function POST(request: NextRequest) {
  try {
    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    const { data: adminRole } = (await supabase.rpc("get_admin_role", {
      user_id: user.id,
    } as GetAdminRoleParams)) as {
      data: GetAdminRoleResult | null;
      error: Error | null;
    };
    const canReopen =
      adminRole === "super_admin" ||
      adminRole === "admin" ||
      adminRole === "root" ||
      adminRole === "dev";
    if (!canReopen) {
      return NextResponse.json(
        {
          error:
            "Solo administradores o super administradores pueden reabrir cajas",
        },
        { status: 403 },
      );
    }

    // Get branch context (for non-super-admins we'll validate branch access after loading session)
    const branchContext = await getBranchContext(request, user.id);

    const body = await request.json();
    const { session_id } = body;

    if (!session_id) {
      return NextResponse.json(
        { error: "session_id is required" },
        { status: 400 },
      );
    }

    // Get the session to check its branch and operativo
    const { data: session, error: sessionError } = await supabase
      .from("pos_sessions")
      .select(
        "id, branch_id, field_operation_id, status, reopen_count, opening_time",
      )
      .eq("id", session_id)
      .single();

    if (sessionError || !session) {
      logger.error("Error fetching session for reopen", sessionError);
      return NextResponse.json(
        {
          error: "Sesión no encontrada",
          details: sessionError?.message,
        },
        { status: 404 },
      );
    }

    // Non-super-admin must have access to the session's branch
    if (!branchContext.isSuperAdmin) {
      const hasAccess = branchContext.accessibleBranches.some(
        (b) => b.id === session.branch_id,
      );
      if (!hasAccess) {
        return NextResponse.json(
          {
            error: "No tienes acceso a la sucursal de esta caja",
          },
          { status: 403 },
        );
      }
    }

    // Check if there's already an open session for this branch (and operativo if applicable)
    let openSessionsQuery = supabase
      .from("pos_sessions")
      .select("id, opening_time")
      .eq("branch_id", session.branch_id)
      .eq("status", "open");
    if (session.field_operation_id) {
      openSessionsQuery = openSessionsQuery.eq(
        "field_operation_id",
        session.field_operation_id,
      );
    } else {
      openSessionsQuery = openSessionsQuery.is("field_operation_id", null);
    }
    const { data: openSessions, error: openSessionsError } =
      await openSessionsQuery;

    if (openSessionsError) {
      logger.error("Error checking open sessions", openSessionsError);
      return NextResponse.json(
        {
          error: "Error al verificar sesiones abiertas",
          details: openSessionsError.message,
        },
        { status: 500 },
      );
    }

    // Filter out the current session if it's already open
    const otherOpenSessions = (openSessions || []).filter(
      (s) => s.id !== session_id,
    );

    if (otherOpenSessions.length > 0) {
      return NextResponse.json(
        {
          error:
            "Ya existe una caja abierta para esta sucursal. Debe cerrarla antes de reabrir otra.",
        },
        { status: 400 },
      );
    }

    // Get the closure associated with this session (fallback by branch/date)
    let closure = null;
    const { data: closureBySession, error: closureError } =
      await supabase
        .from("cash_register_closures")
        .select("id, status, reopen_count, pos_session_id")
        .eq("pos_session_id", session_id)
        .maybeSingle();

    if (closureBySession) {
      closure = closureBySession;
    } else if (session.opening_time) {
      const sessionDateStr = session.opening_time.split("T")[0];
      let closureByDateQuery = supabase
        .from("cash_register_closures")
        .select("id, status, reopen_count, pos_session_id")
        .eq("branch_id", session.branch_id)
        .eq("closure_date", sessionDateStr);
      if (session.field_operation_id) {
        closureByDateQuery = closureByDateQuery.eq(
          "field_operation_id",
          session.field_operation_id,
        );
      } else {
        closureByDateQuery = closureByDateQuery.is("field_operation_id", null);
      }
      const { data: closureByDate } = await closureByDateQuery.maybeSingle();
      closure = closureByDate || null;
    }

    if (closureError && closureError.code !== "PGRST116") {
      logger.error("Error fetching closure for reopen", closureError);
      // Continue anyway - closure might not exist yet
    }

    // Update pos_session to reopen
    const reopenCount = (session.reopen_count || 0) + 1;
    const { data: updatedSession, error: updateError } =
      await supabase
        .from("pos_sessions")
        .update({
          status: "open",
          reopened_at: new Date().toISOString(),
          reopened_by: user.id,
          reopen_count: reopenCount,
          updated_at: new Date().toISOString(),
        })
        .eq("id", session_id)
        .select()
        .single();

    if (updateError) {
      logger.error("Error reopening cash session", updateError);
      return NextResponse.json(
        {
          error: "Error al reabrir la caja",
          details: updateError.message,
        },
        { status: 500 },
      );
    }

    // Update closure if it exists - change status to 'draft' to allow modifications
    if (closure) {
      const closureReopenCount = (closure.reopen_count || 0) + 1;
      const { error: closureUpdateError } = await supabase
        .from("cash_register_closures")
        .update({
          status: "draft", // Change to draft so it can be modified and closed again
          reopened_at: new Date().toISOString(),
          reopened_by: user.id,
          reopen_count: closureReopenCount,
          reopen_notes: `Reabierta por ${user.email} el ${new Date().toLocaleString("es-CL")}`,
          pos_session_id: session_id,
          updated_at: new Date().toISOString(),
        })
        .eq("id", closure.id);

      if (closureUpdateError) {
        logger.error("Error updating closure on reopen", closureUpdateError);
        // Log but don't fail - the session is already reopened
      }
    }

    logger.info("Cash session reopened successfully", {
      session_id,
      branch_id: session.branch_id,
      reopened_by: user.email,
      reopen_count: reopenCount,
      closure_id: closure?.id,
    });

    return NextResponse.json({
      success: true,
      session: updatedSession,
      message: "Caja reabierta correctamente",
    });
  } catch (error: unknown) {
    logger.error("Error in reopen cash register API:", { error });
    return NextResponse.json(
      {
        error: "Internal server error",
        details: error.message,
      },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

/**
 * GET /api/admin/cash-register/session-movements
 * Get all movements (payments) for a POS session
 */
export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    // Get branch context
    const branchContext = await getBranchContext(request, user.id);

    // Get session_id from query params
    const { searchParams } = new URL(request.url);
    const sessionId = searchParams.get("session_id");

    if (!sessionId) {
      return NextResponse.json(
        { error: "session_id is required" },
        { status: 400 },
      );
    }

    // Verify session belongs to user's branch (if not super admin)
    if (!branchContext.isSuperAdmin && branchContext.branchId) {
      const { data: session } = await supabase
        .from("pos_sessions")
        .select("branch_id")
        .eq("id", sessionId)
        .single<{ branch_id: string }>();

      if (!session || session.branch_id !== branchContext.branchId) {
        return NextResponse.json(
          { error: "Session not found or access denied" },
          { status: 404 },
        );
      }
    }

    // Get all payments for this session with order information
    const { data: payments, error: paymentsError } = await supabase
      .from("order_payments")
      .select(
        `
        id,
        amount,
        payment_method,
        paid_at,
        notes,
        created_at,
        order_id,
        order:orders!inner(
          id,
          order_number,
          total_amount,
          payment_status,
          created_at,
          email,
          billing_first_name,
          billing_last_name,
          sii_business_name,
          sii_rut
        )
      `,
      )
      .eq("pos_session_id", sessionId)
      .order("paid_at", { ascending: true });

    if (paymentsError) {
      logger.error("Error fetching session movements:", paymentsError);
      return NextResponse.json(
        {
          error: "Error al obtener movimientos de la sesión",
          details: paymentsError.message,
        },
        { status: 500 },
      );
    }

    // Get credit note movements (refunds) for this session
    const { data: creditNoteMovements } = await supabase
      .from("credit_note_movements")
      .select(
        `
        id,
        amount,
        refund_method,
        created_at,
        credit_notes(
          id,
          credit_note_number,
          order_id
        )
      `,
      )
      .eq("pos_session_id", sessionId)
      .order("created_at", { ascending: true })
      .returns<{ id: string; amount: number; refund_method: string; created_at: string; credit_notes: { id: string; credit_note_number: string; order_id: string } | null }[]>();

    // Fetch order details for credit notes that have order_id
    const orderIds = (creditNoteMovements || [])
      .map((cnm: unknown) => cnm.credit_notes?.order_id)
      .filter(Boolean);
    let ordersMap: Record<string, unknown> = {};
    if (orderIds.length > 0) {
      const { data: orders } = await supabase
        .from("orders")
        .select(
          "id, order_number, billing_first_name, billing_last_name, sii_business_name, sii_rut, email",
        )
        .in("id", orderIds)
        .returns<{ id: string; order_number: string; billing_first_name: string | null; billing_last_name: string | null; sii_business_name: string | null; sii_rut: string | null; email: string | null }[]>();
      if (orders) {
        ordersMap = Object.fromEntries(orders.map((o: unknown) => [o.id, o]));
      }
    }

    const paymentMethodMap: Record<string, string> = {
      cash: "Efectivo",
      debit: "Tarjeta Débito",
      credit: "Tarjeta Crédito",
      transfer: "Transferencia",
      check: "Cheque",
    };

    // Transform credit note movements into movement format
    const cnMovements = (creditNoteMovements || []).map((cnm: unknown) => {
      const order = cnm.credit_notes?.order_id
        ? ordersMap[cnm.credit_notes.order_id]
        : null;
      const customerName =
        order?.sii_business_name ||
        (order?.billing_first_name && order?.billing_last_name
          ? `${order.billing_first_name} ${order.billing_last_name}`.trim()
          : null) ||
        order?.email ||
        "Cliente no registrado";
      return {
        id: cnm.id,
        movement_type: "credit_note",
        order_id: order?.id || cnm.credit_notes?.order_id,
        order_number:
          order?.order_number || cnm.credit_notes?.credit_note_number || "N/A",
        customer_name: customerName,
        customer_rut: order?.sii_rut || null,
        payment_method:
          paymentMethodMap[cnm.refund_method] || cnm.refund_method,
        payment_method_code: cnm.refund_method,
        amount: Number(cnm.amount) || 0, // Already negative
        payment_status: "Reembolso",
        paid_at: cnm.created_at,
        notes: `Nota de crédito ${cnm.credit_notes?.credit_note_number || ""}`,
        order_total: Math.abs(Number(cnm.amount)) || 0,
        order_payment_status: null,
      };
    });

    // Transform payments into movements with additional info
    const paymentMovements = (payments || []).map((payment: unknown) => {
      const order = payment.order;

      // Extract customer information from order fields
      const customerName =
        order?.sii_business_name ||
        (order?.billing_first_name && order?.billing_last_name
          ? `${order.billing_first_name} ${order.billing_last_name}`.trim()
          : null) ||
        order?.email ||
        "Cliente no registrado";
      const customerRut = order?.sii_rut || null;

      // Determine movement type
      let movementType = "sale";
      const orderCreatedAt = new Date(order?.created_at);
      const paymentPaidAt = new Date(payment.paid_at);
      const timeDiff = paymentPaidAt.getTime() - orderCreatedAt.getTime();

      // If payment was made more than 5 minutes after order creation, OR notes indicate so, it's likely a pending balance payment
      if (
        timeDiff > 5 * 60 * 1000 ||
        payment.notes?.toLowerCase().includes("saldo pendiente") ||
        payment.notes?.toLowerCase().includes("pending balance") ||
        payment.notes?.toLowerCase().includes("abono")
      ) {
        movementType = "partial_payment";
      }

      // Determine payment status
      const paymentStatus =
        order?.payment_status === "paid" ? "Completo" : "Parcial";

      // Format payment method
      const paymentMethodMap: Record<string, string> = {
        cash: "Efectivo",
        debit: "Tarjeta Débito",
        credit: "Tarjeta Crédito",
        transfer: "Transferencia",
        check: "Cheque",
      };

      return {
        id: payment.id,
        movement_type: movementType,
        order_id: order?.id,
        order_number: order?.order_number || "N/A",
        customer_name: customerName,
        customer_rut: customerRut,
        payment_method:
          paymentMethodMap[payment.payment_method] || payment.payment_method,
        payment_method_code: payment.payment_method,
        amount: Number(payment.amount) || 0,
        payment_status: paymentStatus,
        paid_at: payment.paid_at,
        notes: payment.notes || null,
        order_total: Number(order?.total_amount) || 0,
        order_payment_status: order?.payment_status || null,
      };
    });

    // Merge and sort by date
    const movements = [...paymentMovements, ...cnMovements].sort(
      (a, b) => new Date(a.paid_at).getTime() - new Date(b.paid_at).getTime(),
    );

    return NextResponse.json({
      movements,
      total_movements: movements.length,
      total_amount: movements.reduce((sum, m) => sum + m.amount, 0),
    });
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : "Unknown error";
    logger.error("Error in session movements API:", error);
    return NextResponse.json(
      { error: "Internal server error", details: message },
      { status: 500 },
    );
  }
}

import { createAgent } from "@/lib/ai/agent/core";

export async function buildAgentContext(supabase: unknown, userId: string, adminUser: unknown, currentBranchId: string | null) {
  const { data: orgData } = await supabase.from("organizations").select("name").eq("id", adminUser?.organization_id).single();
  const orgName = orgData?.name || "tu óptica";

  let branchName = "";
  let branchContext = "";
  if (currentBranchId && currentBranchId !== "global") {
    const { data: branchData } = await supabase.from("branches").select("name").eq("id", currentBranchId).single();
    if (branchData) { branchName = branchData.name; branchContext = `SUCURSAL ACTUAL: ${branchName} (ID: ${currentBranchId})`; }
  } else if (currentBranchId === "global") branchContext = "MODO: Vista Global (Todas las sucursales)";

  const { data: userData } = await supabase.from("admin_users").select("role, full_name").eq("id", userId).single();
  let userName = userData?.full_name?.trim() || supabase.user?.email?.split("@")[0] || "Usuario";
  if (!userData?.full_name?.trim()) {
    const { data: profile } = await supabase.from("profiles").select("full_name").eq("id", userId).single();
    if (profile?.full_name?.trim()) userName = profile.full_name.trim();
  }
  const isSuperAdmin = userData?.role === "super_admin";

  return { orgName, branchContext, userName, isSuperAdmin, userData };
}

export function buildEnhancedPrompt(orgName: string, userName: string, isSuperAdmin: boolean, branchContext: string, section: string | null, systemPrompt: string, currentBranchId: string | null) {
  const specializedIdentity = `Eres el Agente de Inteligencia de ${orgName}. Habla con propiedad sobre "nuestros productos", "nuestros clientes" y "nuestras ventas". Tu objetivo es el éxito total de ${orgName}.\n\nIMPORTANTE: Te estás comunicando con ${userName} (${isSuperAdmin ? "Super Admin" : "Administrador"}). ${isSuperAdmin ? "NOTA SUPER ADMIN: Estás hablando con un Super Admin. Tienes permisos totales." : ""}`;
  const branchInstruction = isSuperAdmin && (currentBranchId === "global" || !currentBranchId) ? "\n\nIMPORTANTE SUCURSAL: El usuario tiene vista global. Para cualquier acción que afecte una sucursal, DEBES preguntar primero en qué sucursal realizarla." : "";
  const today = new Date().toISOString().split("T")[0];
  const dateContext = `FECHA ACTUAL: ${today} (YYYY-MM-DD). Usa SIEMPRE esta fecha para citas y cualquier referencia temporal. NO preguntes "para qué año".`;
  const sectionMap: Record<string, string> = { dashboard: "Dashboard", inventory: "Inventario", clients: "Clientes", pos: "Punto de Venta", analytics: "Analíticas" };
  const sectionContext = section ? `\n\nESTADO ACTUAL: El usuario está navegando en la sección de ${sectionMap[section] || section}.` : "";
  return `${specializedIdentity}\n\n${dateContext}${sectionContext}\n${branchContext}${branchInstruction}\n${systemPrompt}`;
}

export async function resolveOrgId(supabase: unknown, adminUser: unknown, currentBranchId: string | null): Promise<string | null> {
  let resolvedOrgId = adminUser?.organization_id;
  if (!resolvedOrgId && currentBranchId && currentBranchId !== "global") {
    const { data: branchRow } = await supabase.from("branches").select("organization_id").eq("id", currentBranchId).single();
    if (branchRow?.organization_id) resolvedOrgId = branchRow.organization_id;
  }
  return resolvedOrgId;
}

export async function createAndStreamAgent(supabase: unknown, userId: string, provider: string | undefined, model: string | undefined, sessionId: string | null, organizationId: string | null, context: string | undefined, baseConfig: unknown, enhancedPrompt: string, currentBranchId: string | null, userData: unknown, isSuperAdmin: boolean, userName: string, message: string, controller: ReadableStreamDefaultController, encoder: TextEncoder): Promise<{ content: string; toolCalls: unknown[]; success: boolean }> {
  let content = "";
  const toolCalls: unknown[] = [];

  const agent = await createAgent({
    userId, provider: provider as unknown, model, sessionId: sessionId || undefined, organizationId, context,
    config: { ...baseConfig, systemPrompt: enhancedPrompt },
    currentBranchId, supabase,
    userData: { role: userData?.role, isSuperAdmin, name: userName },
  });

  if (sessionId) await agent.loadSessionHistory(sessionId);

  const msgToSend = message; // File attachment handling simplified
  for await (const chunk of agent.streamChat(msgToSend)) {
    if (chunk.content) { content += chunk.content; controller.enqueue(encoder.encode(`data: ${JSON.stringify({ content: chunk.content, done: false })}\n\n`)); }
    if (chunk.toolCalls) toolCalls.push(...chunk.toolCalls);
    if (chunk.done) {
      if (sessionId && content) {
        await supabase.from("chat_messages").insert({ session_id: sessionId, role: "assistant", content, metadata: toolCalls.length > 0 ? { toolCalls } : null });
      }
      controller.enqueue(encoder.encode(`data: ${JSON.stringify({ done: true, sessionId })}\n\n`));
      controller.close();
      return { content, toolCalls, success: true };
    }
  }
  return { content, toolCalls, success: true };
}

import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    const supabase = await createClient();

    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    const { searchParams } = new URL(request.url);
    const sessionId = searchParams.get("sessionId");
    const limit = parseInt(searchParams.get("limit") || "50");
    const offset = parseInt(searchParams.get("offset") || "0");

    if (sessionId) {
      const { data: messages, error } = await supabase
        .from("chat_messages")
        .select("*")
        .eq("session_id", sessionId)
        .order("created_at", { ascending: true })
        .range(offset, offset + limit - 1);

      if (error) {
        return NextResponse.json({ error: error.message }, { status: 500 });
      }

      return NextResponse.json({ messages: messages || [] });
    } else {
      const { data: sessions, error } = await supabase
        .from("chat_sessions")
        .select("*")
        .eq("user_id", user.id)
        .gt("message_count", 0)
        .order("updated_at", { ascending: false })
        .range(offset, offset + limit - 1);

      if (error) {
        return NextResponse.json({ error: error.message }, { status: 500 });
      }

      return NextResponse.json({ sessions: sessions || [] });
    }
  } catch (error) {
    logger.error("Chat history API error", { error });
    return NextResponse.json(
      {
        error: error instanceof Error ? error.message : "Internal server error",
      },
      { status: 500 },
    );
  }
}

