import { NextRequest, NextResponse } from "next/server";

import { getAllTools, getToolByName, getToolsByCategory } from "@/lib/ai/tools";
import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    const supabase = await createClient();

    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    const { searchParams } = new URL(request.url);
    const toolName = searchParams.get("name");
    const category = searchParams.get("category");

    if (toolName) {
      const tool = getToolByName(toolName);
      if (!tool) {
        return NextResponse.json({ error: "Tool not found" }, { status: 404 });
      }
      return NextResponse.json({ tool });
    }

    if (category) {
      const tools = getToolsByCategory(category);
      return NextResponse.json({ tools });
    }

    const allTools = getAllTools();

    const toolsByCategory = allTools.reduce(
      (acc, tool) => {
        const category = tool.category || "other";
        if (!acc[category]) {
          acc[category] = [];
        }
        acc[category].push({
          name: tool.name,
          description: tool.description,
          category: category,
          parameters: tool.parameters,
          requiresConfirmation: tool.requiresConfirmation || false,
        });
        return acc;
      },
      {} as Record<
        string,
        Array<{
          name: string;
          description: string;
          category: string;
          parameters: unknown;
          requiresConfirmation: boolean;
        }>
      >,
    );

    return NextResponse.json({
      tools: allTools.map((tool) => ({
        name: tool.name,
        description: tool.description,
        category: tool.category,
        parameters: tool.parameters,
        requiresConfirmation: tool.requiresConfirmation,
      })),
      categories: Object.keys(toolsByCategory),
      toolsByCategory,
    });
  } catch (error) {
    logger.error("Tools API error", { error });
    return NextResponse.json(
      {
        error: error instanceof Error ? error.message : "Internal server error",
      },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient, createServiceRoleClient } from "@/utils/supabase/server";

const MAX_FILE_SIZE = 5 * 1024 * 1024; // 5MB
const ALLOWED_TYPES = [
  "text/csv",
  "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
  "application/vnd.ms-excel",
];

/**
 * POST /api/admin/chat/upload-import-file
 * Upload CSV/Excel for AI-assisted bulk import.
 * Returns fileId (storage path), filename, rowCount, headers.
 */
export const dynamic = "force-dynamic";

function parseCSVHeaders(text: string): {
  headers: string[];
  rowCount: number;
} {
  const lines = text.split("\n").filter((l) => l.trim());
  if (lines.length === 0) return { headers: [], rowCount: 0 };
  const headers = lines[0]
    .split(",")
    .map((h) => h.trim().replace(/^"|"$/g, ""));
  return { headers, rowCount: Math.max(0, lines.length - 1) };
}

export async function POST(request: NextRequest) {
  try {
    const supabase = await createClient();

    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    const { data: adminUser } = await supabase
      .from("admin_users")
      .select("organization_id")
      .eq("id", user.id)
      .eq("is_active", true)
      .single();

    if (!adminUser?.organization_id) {
      return NextResponse.json(
        { error: "Organization not found" },
        { status: 404 },
      );
    }

    const formData = await request.formData();
    const file = formData.get("file") as File;

    if (!file) {
      return NextResponse.json({ error: "No file provided" }, { status: 400 });
    }

    if (file.size > MAX_FILE_SIZE) {
      return NextResponse.json(
        { error: "File too large. Maximum 5MB." },
        { status: 400 },
      );
    }

    const mimeType = file.type;
    const isCSV =
      mimeType === "text/csv" || file.name.toLowerCase().endsWith(".csv");
    const isExcel =
      mimeType ===
        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" ||
      mimeType === "application/vnd.ms-excel" ||
      file.name.toLowerCase().endsWith(".xlsx") ||
      file.name.toLowerCase().endsWith(".xls");

    if (!isCSV && !isExcel) {
      return NextResponse.json(
        { error: "Only CSV and Excel (.xlsx, .xls) files are allowed" },
        { status: 400 },
      );
    }

    const fileId = crypto.randomUUID();
    const ext = isCSV
      ? "csv"
      : file.name.toLowerCase().endsWith(".xls")
        ? "xls"
        : "xlsx";
    const storagePath = `${adminUser.organization_id}/${fileId}.${ext}`;

    const arrayBuffer = await file.arrayBuffer();
    const buffer = new Uint8Array(arrayBuffer);

    const storageClient = createServiceRoleClient();
    const { error: uploadError } = await storageClient.storage
      .from("import-temp")
      .upload(storagePath, buffer, {
        contentType: mimeType,
        upsert: false,
      });

    if (uploadError) {
      logger.error("Upload import file failed", {
        error: uploadError,
        message: uploadError.message,
        bucket: "import-temp",
      });
      return NextResponse.json(
        { error: "Failed to upload file" },
        { status: 500 },
      );
    }

    let headers: string[] = [];
    let rowCount = 0;

    if (isCSV) {
      const text = new TextDecoder().decode(buffer);
      const parsed = parseCSVHeaders(text);
      headers = parsed.headers;
      rowCount = parsed.rowCount;
    } else {
      try {
        const XLSX = await import("xlsx");
        const workbook = XLSX.read(buffer, { type: "array" });
        const sheet = workbook.Sheets[workbook.SheetNames[0]];
        const data = XLSX.utils.sheet_to_json<string[]>(sheet, {
          header: 1,
          defval: "",
        });
        if (data.length > 0 && Array.isArray(data[0])) {
          headers = (data[0] as string[]).map((h) => String(h || "").trim());
        }
        rowCount = Math.max(0, data.length - 1);
      } catch (e) {
        logger.warn("Could not parse Excel for preview", { e });
      }
    }

    return NextResponse.json({
      fileId: storagePath,
      filename: file.name,
      rowCount,
      headers,
    });
  } catch (err: unknown) {
    logger.error("Upload import file error", { error: err?.message });
    return NextResponse.json(
      { error: err?.message || "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import { getOrganizationFeatures } from "@/lib/saas/tier-validator";
import type {
  GetAdminRoleParams,
  GetAdminRoleResult,
  IsAdminParams,
  IsAdminResult,
  IsRootUserParams,
  IsRootUserResult,
  IsSuperAdminParams,
  IsSuperAdminResult,
} from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

const DEMO_ORG_ID =
  process.env.NEXT_PUBLIC_DEMO_ORG_ID || "00000000-0000-0000-0000-000000000001";

export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    const supabase = await createClient();

    // Get current user
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user) {
      return NextResponse.json({
        authenticated: false,
        error: "Not authenticated",
      });
    }

    // Check if user is admin
    const { data: isAdmin, error: adminError } = (await supabase.rpc(
      "is_admin",
      {
        user_id: user.id,
      } as IsAdminParams,
    )) as { data: IsAdminResult | null; error: Error | null };

    // Get admin role
    const { data: adminRole, error: roleError } = (await supabase.rpc(
      "get_admin_role",
      {
        user_id: user.id,
      } as GetAdminRoleParams,
    )) as { data: GetAdminRoleResult | null; error: Error | null };

    // Check if user is super admin (has global branch access)
    const { data: isSuperAdminRPC, error: superAdminError } =
      (await supabase.rpc("is_super_admin", {
        user_id: user.id,
      } as IsSuperAdminParams)) as {
        data: IsSuperAdminResult | null;
        error: Error | null;
      };

    // Check admin_users table directly
    const { data: adminRecord, error: adminRecordError } = await supabase
      .from("admin_users")
      .select("*")
      .eq("id", user.id)
      .single();

    // Get organization_id from admin_users
    const organizationId = adminRecord?.organization_id || null;
    // isSuperAdmin puede venir del role O de la función is_super_admin (acceso global)
    const isSuperAdmin = adminRole === "super_admin" || !!isSuperAdminRPC;
    // Check if user is root/dev (no necesita organización)
    const { data: isRoot, error: rootError } = (await supabase.rpc(
      "is_root_user",
      {
        user_id: user.id,
      } as IsRootUserParams,
    )) as {
      data: IsRootUserResult | null;
      error: Error | null;
    };
    const isRootUser = !!isRoot;

    let isDemoMode = organizationId === DEMO_ORG_ID;
    let showActivateBanner = isDemoMode;

    if (organizationId && organizationId !== DEMO_ORG_ID) {
      const { data: orgMeta } = await supabase
        .from("organizations")
        .select("metadata")
        .eq("id", organizationId)
        .single();
      const meta = orgMeta?.metadata as Record<string, unknown> | null;
      if (meta?.is_demo === true) {
        isDemoMode = true;
        showActivateBanner = meta?.demo_type !== "organic";
      }
    }

    // Get organization details if exists
    let organizationName = null;
    let organizationLogo = null;
    let organizationSlogan = null;
    let ownerId = null;
    let isOwner = isRootUser;

    if (organizationId) {
      const { data: orgData } = await supabase
        .from("organizations")
        .select("name, logo_url, slogan, owner_id")
        .eq("id", organizationId)
        .single();
      organizationName = orgData?.name || null;
      organizationLogo = orgData?.logo_url || null;
      organizationSlogan = orgData?.slogan || null;
      ownerId = orgData?.owner_id || null;
      isOwner = ownerId === user.id || isRootUser;
    }

    // Determine if onboarding is required
    const onboardingRequired =
      isAdmin && !organizationId && !isSuperAdmin && !isRootUser;

    // Get tier features for sidebar filtering (root users get all features)
    let tierFeatures: Record<string, boolean> = {};
    if (organizationId && !isRootUser) {
      tierFeatures = await getOrganizationFeatures(organizationId);
    } else if (isRootUser) {
      // Root users see all features
      tierFeatures = {
        field_operations: true,
        agreements: true,
        whatsapp: true,
        chat_ia: true,
        advanced_analytics: true,
        prescriptions: true,
        custom_branding: true,
        pos: true,
        appointments: true,
        quotes: true,
        work_orders: true,
      };
    }

    // Test products query
    const {
      data: products,
      count,
      error: productsError,
    } = await supabase
      .from("products")
      .select("*", { count: "exact" })
      .limit(5);

    return NextResponse.json({
      authenticated: true,
      user: {
        id: user.id,
        email: user.email,
      },
      adminCheck: {
        isAdmin: isAdmin,
        adminError: adminError?.message,
        role: adminRole,
        roleError: roleError?.message,
        adminRecord: adminRecord,
        adminRecordError: adminRecordError?.message,
        isOwner,
      },
      organization: {
        organizationId,
        organizationName,
        organizationLogo,
        organizationSlogan,
        ownerId,
        hasOrganization: !!organizationId,
        isDemoMode,
        showActivateBanner,
        isSuperAdmin,
        isRootUser,
        isOwner,
        onboardingRequired,
        tierFeatures,
      },
      productsTest: {
        count: count,
        productsReturned: products?.length,
        error: productsError?.message,
        firstProduct: products?.[0],
      },
    });
  } catch (error) {
    logger.error("Check status error", { error });
    return NextResponse.json(
      {
        error: "Internal server error",
        details: error instanceof Error ? error.message : "Unknown error",
      },
      { status: 500 },
    );
  }
}

import { NextRequest } from "next/server";

