      customer_name,
      customer_rut,
      customer_phone,
      customer_email,
      contact_lens_family_id,
      family_name,
      family_brand,
      sphere_od,
      cylinder_od,
      axis_od,
      add_od,
      base_curve_od,
      diameter_od,
      sphere_os,
      cylinder_os,
      axis_os,
      add_os,
      base_curve_os,
      diameter_os,
      quantity,
      estimated_price,
      cost,
      notes,
