/**
 * POST /api/admin/contact-lens-matrices/calculate
 * Calculates contact lens price based on family, sphere, cylinder, axis, and optional addition
 *
 * Body:
 * - contact_lens_family_id: UUID of the contact lens family (required)
 * - sphere: Sphere value (required)
 * - cylinder: Cylinder value (default: 0)
 * - axis: Axis value for toric lenses (optional)
 * - addition: Addition value for multifocal lenses (optional)
 */
export const dynamic = "force-dynamic";
export async function POST(request: NextRequest) {
  try {
    const supabase = await createClient();

    // Check authentication
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return createApiErrorResponse(
        new APIError("Unauthorized", 401, "UNAUTHORIZED"),
      );
    }

    // Check admin status
    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return createApiErrorResponse(
        new APIError("Admin access required", 403, "FORBIDDEN"),
      );
    }

    // Get user's organization_id
    const { data: adminUser } = await supabase
      .from("admin_users")
      .select("organization_id")
      .eq("id", user.id)
      .single();

    const userOrganizationId = (
      adminUser as {
        organization_id?: string;
      }
    )?.organization_id;

    // Parse body
    const body = await request.json();
    const {
      contact_lens_family_id,
      sphere,
      cylinder = 0,
      axis = null,
      addition = null,
    } = body;

    // Validate required parameters
    if (!contact_lens_family_id) {
      return createApiErrorResponse(
        new APIError("contact_lens_family_id is required", 400, "BAD_REQUEST"),
      );
    }

    if (sphere === undefined || sphere === null) {
      return createApiErrorResponse(
        new APIError("sphere is required", 400, "BAD_REQUEST"),
      );
    }

    // Validate sphere is a number
    const sphereNum = parseFloat(sphere);
    if (isNaN(sphereNum)) {
      return createApiErrorResponse(
        new APIError("sphere must be a valid number", 400, "BAD_REQUEST"),
      );
    }

    // Validate cylinder is a number if provided
    const cylinderNum =
      cylinder !== null && cylinder !== undefined ? parseFloat(cylinder) : 0;
    if (isNaN(cylinderNum)) {
      return createApiErrorResponse(
        new APIError("cylinder must be a valid number", 400, "BAD_REQUEST"),
      );
    }

    // Validate axis is an integer between 0-180 if provided
    const axisInt = axis !== null && axis !== undefined ? parseInt(axis) : null;
    if (axisInt !== null && (isNaN(axisInt) || axisInt < 0 || axisInt > 180)) {
      return createApiErrorResponse(
        new APIError(
          "axis must be an integer between 0 and 180",
          400,
          "BAD_REQUEST",
        ),
      );
    }

    // Validate addition is a number if provided
    const additionNum =
      addition !== null && addition !== undefined ? parseFloat(addition) : null;
    if (additionNum !== null && isNaN(additionNum)) {
      return createApiErrorResponse(
        new APIError("addition must be a valid number", 400, "BAD_REQUEST"),
      );
    }

    // Call the SQL function to calculate contact lens price
    const { data: calculation, error } = await supabase.rpc(
      "calculate_contact_lens_price",
      {
        p_contact_lens_family_id: contact_lens_family_id,
        p_sphere: sphereNum,
        p_cylinder: cylinderNum,
        p_axis: axisInt,
        p_addition: additionNum,
        p_organization_id: userOrganizationId || null,
      },
    );

    if (error) {
      logger.error("Error calculating contact lens price", error);
      return createApiErrorResponse(
        new Error(
          `Error al calcular el precio del lente de contacto: ${error.message}`,
        ),
      );
    }

    // Si no hay resultado: configuración de la familia (matrices) o la receta no cae en ningún rango
    if (!calculation || calculation.length === 0) {
      return createApiErrorResponse(
        new APIError(
          "No se encontró una matriz de precios para esta familia y receta. Comprueba que existan matrices de precios para esta familia (Productos → Lentes de contacto → Matrices) y que los valores de la receta (esfera, cilindro, eje, adición) entren en algún rango configurado.",
          422,
          "NO_PRICE_MATRIX_MATCH",
        ),
      );
    }

    // The RPC function returns an array, get the first result
    const result = Array.isArray(calculation) ? calculation[0] : calculation;

    return createApiSuccessResponse({
      calculation: {
        price: parseFloat(result.price),
        cost: parseFloat(result.cost),
        base_curve: result.base_curve ? parseFloat(result.base_curve) : null,
        diameter: result.diameter ? parseFloat(result.diameter) : null,
      },
    });
  } catch (error) {
    logger.error("Error in contact lens price calculation API", error);
    return createApiErrorResponse(
      error instanceof Error ? error : new Error("Internal server error"),
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";

import { ValidationError } from "@/lib/api/errors";
import {
  parseAndValidateBody,
  validationErrorResponse,
} from "@/lib/api/validation/zod-helpers";
import { createContactLensPriceMatrixSchema } from "@/lib/api/validation/zod-schemas";
import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    const supabase = await createClient();

    // Check authentication
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    // Check admin status
    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    // Get user's organization_id for filtering
    const { data: adminUser } = await supabase
      .from("admin_users")
      .select("organization_id, role")
      .eq("id", user.id)
      .single();

    const userOrganizationId = (
      adminUser as {
        organization_id?: string;
        role?: string;
      }
    )?.organization_id;
    const isSuperAdmin =
      (adminUser as { role?: string })?.role === "super_admin";

    const { searchParams } = new URL(request.url);
    const familyId = searchParams.get("family_id");
    const includeInactive = searchParams.get("include_inactive") === "true";

    // Build query
    let query = supabase
      .from("contact_lens_price_matrices")
      .select(
        `
        *,
        contact_lens_families (
          id,
          name,
          brand,
          use_type,
          modality,
          packaging
        )
      `,
      )
      .order("created_at", { ascending: false });

    // Filter by organization_id (multi-tenancy isolation)
    // Even super admins should only see matrices from their organization (unless root/dev)
    if (userOrganizationId) {
      query = query.eq("organization_id", userOrganizationId);
    } else if (!isSuperAdmin) {
      return NextResponse.json({ matrices: [] });
    }

    // Filter by family if provided
    if (familyId && familyId !== "all") {
      query = query.eq("contact_lens_family_id", familyId);
    }

    // Filter by active status if needed
    if (!includeInactive) {
      query = query.eq("is_active", true);
    }

    const { data: matrices, error } = await query;

    if (error) {
      logger.error("Error fetching contact lens price matrices", error);
      return NextResponse.json(
        { error: "Error al cargar matrices de precios de lentes de contacto" },
        { status: 500 },
      );
    }

    return NextResponse.json({ matrices: matrices || [] });
  } catch (error) {
    logger.error("Error in contact lens matrices API GET", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

export async function POST(request: NextRequest) {
  try {
    const supabase = await createClient();

    // Check authentication
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    // Check admin status
    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    // Get user's organization_id
    const { data: adminUser } = await supabase
      .from("admin_users")
      .select("organization_id")
      .eq("id", user.id)
      .single();

    const userOrganizationId = (
      adminUser as {
        organization_id?: string;
      }
    )?.organization_id;

    if (!userOrganizationId) {
      return NextResponse.json(
        { error: "Organization not found" },
        { status: 404 },
      );
    }

    // Validate body
    const body = await parseAndValidateBody(
      request,
      createContactLensPriceMatrixSchema,
    );

    // Insert price matrix with organization_id
    const { data: matrix, error } = await supabase
      .from("contact_lens_price_matrices")
      .insert({
        ...body,
        organization_id: userOrganizationId,
      })
      .select(
        `
        *,
        contact_lens_families (
          id,
          name,
          brand,
          use_type,
          modality,
          packaging
        )
      `,
      )
      .single();

    if (error) {
      logger.error("Error creating contact lens price matrix", error);
      return NextResponse.json(
        { error: "Error al crear matriz de precios de lentes de contacto" },
        { status: 500 },
      );
    }

    return NextResponse.json({ matrix }, { status: 201 });
  } catch (error) {
    if (error instanceof ValidationError || error instanceof z.ZodError) {
      return validationErrorResponse(error);
    }
    logger.error("Error in contact lens matrices API POST", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

/**
 * GET /api/admin/credit-notes
 * List credit notes with optional filters
 */
export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    const supabase = await createClient();

    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    const branchContext = await getBranchContext(request, user.id);

    const { searchParams } = new URL(request.url);
    const dateFrom = searchParams.get("date_from");
    const dateTo = searchParams.get("date_to");
    const limit = parseInt(searchParams.get("limit") || "50");
    const offset = parseInt(searchParams.get("offset") || "0");

    let query = supabase
      .from("credit_notes")
      .select(
        `
        id,
        credit_note_number,
        order_id,
        branch_id,
        amount,
        reason,
        refund_method,
        created_at,
        branches(id, name, code)
      `,
        { count: "exact" },
      )
      .order("created_at", { ascending: false })
      .range(offset, offset + limit - 1);

    if (branchContext.branchId) {
      query = query.eq("branch_id", branchContext.branchId);
    } else if (branchContext.organizationId) {
      // Global view or no branch: scope to user's organization
      query = query.eq("organization_id", branchContext.organizationId);
    }
    // When both null (e.g. super_admin without org): no filter, show all

    // Date filter: use wide range to avoid timezone/year mismatches with "antiguas"
    if (dateFrom && dateTo) {
      query = query
        .gte("created_at", `${dateFrom}T00:00:00.000Z`)
        .lt("created_at", `${dateTo}T23:59:59.999Z`);
    }

    const { data: creditNotes, error, count } = await query;

    if (error) {
      logger.error("Error fetching credit notes:", error);
      return NextResponse.json(
        { error: "Error al obtener notas de crédito", details: error.message },
        { status: 500 },
      );
    }

    // Fetch order numbers for credit notes that have order_id
    const orderIds = (creditNotes || [])
      .map((cn: unknown) => cn.order_id)
      .filter(Boolean);
    let orderNumbersMap: Record<string, string> = {};
    if (orderIds.length > 0) {
      const { data: orders } = await supabase
        .from("orders")
        .select("id, order_number")
        .in("id", orderIds);
      if (orders) {
        orderNumbersMap = Object.fromEntries(
          orders.map((o: unknown) => [o.id, o.order_number]),
        );
      }
    }

    const notes = (creditNotes || []).map((cn: unknown) => ({
      ...cn,
      order_number: cn.order_id ? orderNumbersMap[cn.order_id] || null : null,
      branch_name: cn.branches?.name || null,
    }));

    return NextResponse.json({
      credit_notes: notes,
      pagination: {
        total: count ?? 0,
        limit,
        offset,
      },
    });
  } catch (error: unknown) {
    logger.error("Error in credit notes API:", error);
    return NextResponse.json(
      { error: "Internal server error", details: error.message },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import { NotificationService } from "@/lib/notifications/notification-service";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

// GET - Get all appointments for a customer
export const dynamic = "force-dynamic";
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { id } = await params;
    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    const { searchParams } = new URL(request.url);
    const status = searchParams.get("status");
    const upcoming = searchParams.get("upcoming") === "true";

    let query = supabase.from("appointments").select("*").eq("customer_id", id);

    if (status) {
      query = query.eq("status", status);
    }

    if (upcoming) {
      query = query.gte(
        "appointment_date",
        new Date().toISOString().split("T")[0],
      );
    }

    const { data: appointments, error } = await query
      .order("appointment_date", { ascending: true })
      .order("appointment_time", { ascending: true });

    if (error) {
      logger.error("Error fetching appointments", error);
      return NextResponse.json(
        { error: "Failed to fetch appointments" },
        { status: 500 },
      );
    }

    return NextResponse.json({ appointments: appointments || [] });
  } catch (error) {
    logger.error("Error in appointments API GET", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

// POST - Create a new appointment
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { id } = await params;
    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    const body = await request.json();
    const branchContext = await getBranchContext(request, user.id);

    const branchId = body.branch_id ?? branchContext.branchId;
    if (!branchContext.isSuperAdmin && !branchId) {
      return NextResponse.json(
        { error: "Debe seleccionar una sucursal para crear una cita" },
        { status: 400 },
      );
    }

    const { data: appointment, error } = await supabase
      .from("appointments")
      .insert({
        customer_id: id,
        appointment_date: body.appointment_date,
        appointment_time: body.appointment_time,
        duration_minutes: body.duration_minutes || 30,
        appointment_type: body.appointment_type || "consultation",
        status: body.status || "scheduled",
        assigned_to: body.assigned_to || null,
        notes: body.notes || null,
        reason: body.reason || null,
        outcome: body.outcome || null,
        follow_up_required: body.follow_up_required || false,
        follow_up_date: body.follow_up_date || null,
        prescription_id: body.prescription_id || null,
        order_id: body.order_id || null,
        created_by: user.id,
        branch_id: branchId,
        organization_id: branchContext.organizationId,
      })
      .select(
        `
        *,
        customer:profiles!appointments_customer_id_fkey(id, first_name, last_name, email, phone)
      `,
      )
      .single();

    if (error) {
      logger.error("Error creating appointment", error);
      return NextResponse.json(
        { error: "Failed to create appointment" },
        { status: 500 },
      );
    }

    // Create notification for new appointment (non-blocking)
    if (appointment) {
      const customerName = appointment.customer
        ? `${appointment.customer.first_name || ""} ${appointment.customer.last_name || ""}`.trim() ||
          appointment.customer.email ||
          "Cliente"
        : "Cliente";

      NotificationService.notifyNewAppointment(
        appointment.id,
        customerName,
        appointment.appointment_date,
        appointment.appointment_time,
        appointment.branch_id ??
          branchId ??
          branchContext.branchId ??
          undefined,
      ).catch((err) => logger.warn("Error creating notification", err));
    }

    return NextResponse.json({ appointment }, { status: 201 });
  } catch (error) {
    logger.error("Error in create appointment API", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

/**
 * Customer Detail GET service — fetches customer + orders + prescriptions + analytics.
 * Extracted from route.ts to reduce file size. No behavioral changes.
 */
import { NextRequest } from "next/server";

import {
  createApiErrorResponse,
  createApiSuccessResponse,
} from "@/lib/api/response";
import { appLogger as logger } from "@/lib/logger";

import {
  authenticateAndGetContext,
  buildBranchFilter,
} from "./customersDetailShared";

export async function handleGetCustomer(
  request: NextRequest,
  params: { id: string },
) {
  try {
    const { context, supabase } = await authenticateAndGetContext(
      request,
      "GET",
    );
    const applyBranchFilter = buildBranchFilter(context);

    // Get customer
    const customerQuery = applyBranchFilter(
      supabase.from("customers").select("*").eq("id", params.id),
    );
    const { data: customer, error: customerError } =
      await customerQuery.single();
    if (customerError || !customer) {
      logger.error("Error fetching customer", customerError);
      return createApiErrorResponse(new Error("Customer not found"));
    }

    // Get orders
    let ordersQuery = applyBranchFilter(
      supabase
        .from("orders")
        .select(
          `*, order_items (*, products:product_id (id, name, featured_image))`,
        ),
    );
    if (customer.email) {
      ordersQuery = ordersQuery.or(
        `customer_id.eq.${params.id},email.eq.${customer.email}`,
      );
    } else {
      ordersQuery = ordersQuery.eq("customer_id", params.id);
    }
    const { data: orders } = await ordersQuery.order("created_at", {
      ascending: false,
    });

    // Get prescriptions
    const { data: prescriptions } = await applyBranchFilter(
      supabase
        .from("prescriptions")
        .select("*")
        .eq("customer_id", params.id)
        .order("is_current", { ascending: false, nullsFirst: false })
        .order("created_at", { ascending: false }),
    );

    // Get appointments
    const { data: appointments } = await applyBranchFilter(
      supabase
        .from("appointments")
        .select("*")
        .eq("customer_id", params.id)
        .order("appointment_date", { ascending: false })
        .order("appointment_time", { ascending: false }),
    );

    // Get lens purchases
    const { data: lensPurchases } = await supabase
      .from("customer_lens_purchases")
      .select("*")
      .eq("customer_id", params.id)
      .order("purchase_date", { ascending: false });

    // Get quotes
    const { data: quotes } = await applyBranchFilter(
      supabase
        .from("quotes")
        .select("*")
        .eq("customer_id", params.id)
        .order("created_at", { ascending: false }),
    );

    // Get agreement usage
    const { data: acRows } = await supabase
      .from("agreement_customers")
      .select(
        "agreement_id, order_count, last_order_at, total_copago, total_institutional, agreements:agreement_id(name)",
      )
      .eq("customer_id", params.id);
    const agreement_usage = (acRows || []).map((r: unknown) => ({
      agreement_id: r.agreement_id,
      agreement_name: r.agreements?.name ?? null,
      order_count: r.order_count,
      last_order_at: r.last_order_at,
      total_copago: Number(r.total_copago ?? 0),
      total_institutional: Number(r.total_institutional ?? 0),
    }));

    // Analytics
    const totalSpent =
      orders?.reduce(
        (sum: number, order: unknown) => sum + (order.total_amount || 0),
        0,
      ) || 0;
    const orderCount = orders?.length || 0;
    const avgOrderValue = orderCount > 0 ? totalSpent / orderCount : 0;
    const lastOrderDate = orders?.[0]?.created_at || null;

    let segment = "new";
    if (orderCount > 10) segment = "vip";
    else if (orderCount > 3) segment = "regular";
    else if (orderCount > 0) segment = "first-time";
    if (
      orderCount > 0 &&
      lastOrderDate &&
      new Date(lastOrderDate) < new Date(Date.now() - 180 * 24 * 60 * 60 * 1000)
    ) {
      segment = "at-risk";
    }

    const orderStatusCounts =
      orders?.reduce((acc: Record<string, number>, order: unknown) => {
        acc[order.status] = (acc[order.status] || 0) + 1;
        return acc;
      }, {}) || {};

    const productCounts =
      orders?.reduce((acc: Record<string, unknown>, order: unknown) => {
        order.order_items?.forEach((item: unknown) => {
          const product = item.products || item.product;
          if (product) {
            const productId = product.id;
            if (!acc[productId])
              acc[productId] = { product, quantity: 0, totalSpent: 0 };
            acc[productId].quantity += item.quantity;
            acc[productId].totalSpent += item.total_price;
          } else if (item.product_name) {
            const pk = `product_${item.product_id}`;
            if (!acc[pk])
              acc[pk] = {
                product: {
                  id: item.product_id,
                  name: item.product_name,
                  featured_image: null,
                },
                quantity: 0,
                totalSpent: 0,
              };
            acc[pk].quantity += item.quantity;
            acc[pk].totalSpent += item.total_price;
          }
        });
        return acc;
      }, {}) || {};
    const favoriteProducts = Object.values(productCounts)
      .sort((a: unknown, b: unknown) => b.quantity - a.quantity)
      .slice(0, 5);

    // Monthly spending (last 12 months)
    const monthlySpending = [];
    const now = new Date();
    for (let i = 11; i >= 0; i--) {
      const month = new Date(now.getFullYear(), now.getMonth() - i, 1);
      const nextMonth = new Date(now.getFullYear(), now.getMonth() - i + 1, 1);
      const monthOrders =
        orders?.filter((order: unknown) => {
          const od = new Date(order.created_at);
          return od >= month && od < nextMonth;
        }) || [];
      monthlySpending.push({
        month: month.toLocaleDateString("es-AR", {
          month: "short",
          year: "2-digit",
        }),
        amount: monthOrders.reduce(
          (s: number, o: unknown) => s + (o.total_amount || 0),
          0,
        ),
        orders: monthOrders.length,
      });
    }

    return createApiSuccessResponse({
      ...customer,
      agreement_usage,
      is_convenio_client: agreement_usage.length > 0,
      orders: orders || [],
      prescriptions: prescriptions || [],
      appointments: appointments || [],
      lensPurchases: lensPurchases || [],
      quotes: quotes || [],
      analytics: {
        totalSpent,
        orderCount,
        lastOrderDate,
        avgOrderValue,
        segment,
        lifetimeValue: totalSpent,
        orderStatusCounts,
        favoriteProducts,
        monthlySpending,
      },
    });
  } catch (error) {
    logger.error("Error in customer detail API GET", error);
    return createApiErrorResponse(
      error instanceof Error ? error : new Error(String(error)),
    );
  }
}

/**
 * Customer Detail UPDATE service — PUT handler for updating a customer.
 * Extracted from route.ts to reduce file size. No behavioral changes.
 */
import { NextRequest } from "next/server";

import {
  createApiErrorResponse,
  createApiSuccessResponse,
} from "@/lib/api/response";
import { appLogger as logger } from "@/lib/logger";

import {
  authenticateAndGetContext,
  buildBranchFilter,
} from "./customersDetailShared";

export async function handleUpdateCustomer(
  request: NextRequest,
  params: { id: string },
) {
  try {
    const { context, supabase } = await authenticateAndGetContext(
      request,
      "PUT",
    );
    const applyBranchFilter = buildBranchFilter(context);

    const body = await request.json();

    const updateData: Record<string, unknown> = {
      first_name: body.first_name || null,
      last_name: body.last_name || null,
      email: body.email || null,
      phone: body.phone || null,
      rut: body.rut || null,
      date_of_birth: body.date_of_birth || null,
      gender: body.gender || null,
      address_line_1: body.address_line_1 || null,
      address_line_2: body.address_line_2 || null,
      city: body.city || null,
      state: body.state || null,
      postal_code: body.postal_code || null,
      country: body.country || "Chile",
      medical_conditions: body.medical_conditions || null,
      allergies: body.allergies || null,
      medications: body.medications || null,
      medical_notes: body.medical_notes || null,
      last_eye_exam_date: body.last_eye_exam_date || null,
      next_eye_exam_due: body.next_eye_exam_due || null,
      preferred_contact_method: body.preferred_contact_method || null,
      emergency_contact_name: body.emergency_contact_name || null,
      emergency_contact_phone: body.emergency_contact_phone || null,
      insurance_provider: body.insurance_provider || null,
      insurance_policy_number: body.insurance_policy_number || null,
      notes: body.notes || null,
      tags: body.tags || null,
      is_active: body.is_active !== undefined ? body.is_active : true,
      updated_at: new Date().toISOString(),
    };

    // Verify customer exists and user has access
    const { data: existingCustomer } = await applyBranchFilter(
      supabase.from("customers").select("id, branch_id").eq("id", params.id),
    ).single();
    if (!existingCustomer) {
      return createApiErrorResponse(
        new Error("Customer not found or access denied"),
      );
    }

    const { data: updatedCustomer, error: updateError } = await supabase
      .from("customers")
      .update({ ...updateData, updated_by: context.userId } as unknown)
      .eq("id", params.id)
      .select()
      .single();

    if (updateError || !updatedCustomer) {
      logger.error("Error updating customer", updateError);
      return createApiErrorResponse(new Error("Failed to update customer"));
    }

    return createApiSuccessResponse(updatedCustomer);
  } catch (error) {
    logger.error("Error in customer update API PUT", error);
    return createApiErrorResponse(
      error instanceof Error ? error : new Error(String(error)),
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient , createServiceRoleClient } from "@/utils/supabase/server";


export const dynamic = "force-dynamic";
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string; prescriptionId: string }> },
) {
  try {
    const supabase = await createClient();
    const supabaseServiceRole = createServiceRoleClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    const { id: customerId, prescriptionId } = await params;

    // Get prescription
    const { data: prescription, error } = await supabaseServiceRole
      .from("prescriptions")
      .select("*")
      .eq("id", prescriptionId)
      .eq("customer_id", customerId)
      .single();

    if (error) {
      logger.error("Error fetching prescription", error);
      return NextResponse.json(
        {
          error: "Prescription not found",
          details: error.message,
        },
        { status: 404 },
      );
    }

    return NextResponse.json({
      success: true,
      prescription,
    });
  } catch (error) {
    logger.error("Error in prescription get API", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string; prescriptionId: string }> },
) {
  try {
    const supabase = await createClient();
    const supabaseServiceRole = createServiceRoleClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    const { id: customerId, prescriptionId } = await params;
    const body = await request.json();

    // If setting as current, unset other current prescriptions
    if (body.is_current) {
      await supabaseServiceRole
        .from("prescriptions")
        .update({ is_current: false })
        .eq("customer_id", customerId)
        .neq("id", prescriptionId);
    }

    // Update prescription
    const { data: updatedPrescription, error } = await supabaseServiceRole
      .from("prescriptions")
      .update({
        prescription_date: body.prescription_date,
        expiration_date: body.expiration_date || null,
        prescription_number: body.prescription_number || null,
        issued_by: body.issued_by || null,
        issued_by_license: body.issued_by_license || null,
        od_sphere: body.od_sphere || null,
        od_cylinder: body.od_cylinder || null,
        od_axis: body.od_axis || null,
        od_add: body.od_add || null,
        od_pd: body.od_pd || null,
        od_near_pd: body.od_near_pd || null,
        os_sphere: body.os_sphere || null,
        os_cylinder: body.os_cylinder || null,
        os_axis: body.os_axis || null,
        os_add: body.os_add || null,
        os_pd: body.os_pd || null,
        os_near_pd: body.os_near_pd || null,
        frame_pd: body.frame_pd || null,
        height_segmentation: body.height_segmentation || null,
        prescription_type: body.prescription_type || null,
        lens_type: body.lens_type || null,
        lens_material: body.lens_material || null,
        prism_od: body.prism_od || null,
        prism_os: body.prism_os || null,
        tint_od: body.tint_od || null,
        tint_os: body.tint_os || null,
        coatings: body.coatings || [],
        notes: body.notes || null,
        observations: body.observations || null,
        recommendations: body.recommendations || null,
        is_active: body.is_active !== undefined ? body.is_active : true,
        is_current: body.is_current !== undefined ? body.is_current : false,
        updated_at: new Date().toISOString(),
      })
      .eq("id", prescriptionId)
      .eq("customer_id", customerId)
      .select()
      .single();

    if (error) {
      logger.error("Error updating prescription", error);
      return NextResponse.json(
        {
          error: "Failed to update prescription",
          details: error.message,
        },
        { status: 500 },
      );
    }

    return NextResponse.json({
      success: true,
      prescription: updatedPrescription,
    });
  } catch (error) {
    logger.error("Error in prescription update API", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

