/**
 * Customers Create Service — POST customer creation logic.
 *
 * Extracted from route.ts to reduce file size. No behavioral changes.
 */

import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";

import { getBranchContext } from "@/lib/api/branch-middleware";
import {
  AuthorizationError,
  NotFoundError,
  ValidationError,
} from "@/lib/api/errors";
import { createApiErrorResponse } from "@/lib/api/response";
import {
  validateBody,
  validationErrorResponse,
} from "@/lib/api/validation/zod-helpers";
import { createCustomerSchema } from "@/lib/api/validation/zod-schemas";
import { appLogger as logger } from "@/lib/logger";
import { NotificationService } from "@/lib/notifications/notification-service";
import { createClientFromRequest } from "@/utils/supabase/server";

export async function handleCreateCustomer(
  request: NextRequest,
  body: unknown,
) {
  logger.info("Customers API POST called (create new customer)");

  const { client: supabase, getUser } = await createClientFromRequest(request);

  const user = (await getUser()).data?.user as { id: string } | undefined;
  if (!user) {
    return createApiErrorResponse(new AuthorizationError("Unauthorized"));
  }

  const { createServiceRoleClient } = await import("@/utils/supabase/server");
  const serviceSupabase = createServiceRoleClient();

  const { data: isAdminResult } = await serviceSupabase.rpc("is_admin", {
    user_id: user.id,
  });
  if (!isAdminResult) {
    return createApiErrorResponse(
      new AuthorizationError("Admin access required"),
    );
  }

  const { data: adminUser } = await supabase
    .from("admin_users")
    .select("organization_id")
    .eq("id", user.id)
    .single();

  const userOrgId = (adminUser as { organization_id: string } | null)
    ?.organization_id;
  if (!userOrgId) {
    return NextResponse.json(
      { error: "User organization not found" },
      { status: 500 },
    );
  }

  let validatedBody: Record<string, unknown>;
  try {
    validatedBody = validateBody(body, createCustomerSchema) as Record<
      string,
      unknown
    >;
  } catch (error: unknown) {
    if (error instanceof ValidationError) return validationErrorResponse(error);
    if (error instanceof z.ZodError) {
      const errors = error.errors.map((err: z.ZodIssue) => ({
        field: err.path.join("."),
        message: err.message,
      }));
      return NextResponse.json(
        { error: "Validation failed", details: errors },
        { status: 400 },
      );
    }
    throw error;
  }

  const branchContext = await getBranchContext(request, user.id, supabase);

  // Determine customer branch_id
  let customerBranchId: string | null = null;

  if (validatedBody.field_operation_id && validatedBody.branch_id) {
    const { data: fieldOp } = await serviceSupabase
      .from("field_operations")
      .select("id, branch_id, organization_id")
      .eq("id", validatedBody.field_operation_id as string)
      .single();
    const fieldOpRecord = fieldOp as {
      id: string;
      branch_id: string;
      organization_id: string;
    } | null;
    if (!fieldOpRecord)
      return createApiErrorResponse(new NotFoundError("Operativo"));
    if (
      fieldOpRecord.organization_id !== userOrgId &&
      !branchContext.isSuperAdmin
    ) {
      return createApiErrorResponse(
        new AuthorizationError("No tienes acceso a este operativo"),
      );
    }
    if (fieldOpRecord.branch_id !== validatedBody.branch_id) {
      return createApiErrorResponse(
        new ValidationError("La sucursal no coincide con el operativo"),
      );
    }
    customerBranchId = validatedBody.branch_id as string;
  } else if (branchContext.branchId) {
    customerBranchId = branchContext.branchId;
  } else if (validatedBody.branch_id) {
    const { data: branch } = await supabase
      .from("branches")
      .select("id, organization_id")
      .eq("id", validatedBody.branch_id as string)
      .single();
    const branchRecord = branch as {
      id: string;
      organization_id: string;
    } | null;
    if (!branchRecord)
      return NextResponse.json(
        { error: "Sucursal no encontrada" },
        { status: 404 },
      );
    if (
      branchRecord.organization_id !== userOrgId &&
      !branchContext.isSuperAdmin
    ) {
      return createApiErrorResponse(
        new AuthorizationError("No tienes acceso a esta sucursal"),
      );
    }
    customerBranchId = validatedBody.branch_id as string;
  } else if (branchContext.isGlobalView && branchContext.isSuperAdmin) {
    return NextResponse.json(
      {
        error:
          "Como super administrador en vista global, debe especificar la sucursal para el cliente",
      },
      { status: 400 },
    );
  } else {
    return NextResponse.json(
      { error: "Debe seleccionar una sucursal para crear un cliente" },
      { status: 400 },
    );
  }

  if (!customerBranchId) {
    return NextResponse.json(
      { error: "Debe especificar una sucursal para el cliente" },
      { status: 400 },
    );
  }

  const { validateTierLimit } = await import("@/lib/saas/tier-validator");
  const customerLimit = await validateTierLimit(userOrgId, "customers");
  if (!customerLimit.allowed) {
    return createApiErrorResponse(
      new AuthorizationError(
        customerLimit.reason ??
          "Límite de clientes alcanzado para tu plan. Considera actualizar tu suscripción.",
      ),
      {
        details: {
          code: "TIER_LIMIT",
          currentCount: customerLimit.currentCount,
          maxAllowed: customerLimit.maxAllowed,
        },
      },
    );
  }

  const existingCustomerQuery = supabase
    .from("customers")
    .select("id")
    .eq("branch_id", customerBranchId);

  if (validatedBody.email) {
    const { data: existingByEmail } = await existingCustomerQuery
      .eq("email", validatedBody.email as string)
      .maybeSingle();
    if (existingByEmail) {
      return NextResponse.json(
        { error: "Ya existe un cliente con este email en esta sucursal." },
        { status: 400 },
      );
    }
  }

  if (validatedBody.rut) {
    const { data: existingByRut } = await existingCustomerQuery
      .eq("rut", validatedBody.rut as string)
      .maybeSingle();
    if (existingByRut) {
      return NextResponse.json(
        { error: "Ya existe un cliente con este RUT en esta sucursal." },
        { status: 400 },
      );
    }
  }

  const customerData: Record<string, unknown> = {
    organization_id: userOrgId,
    branch_id: customerBranchId,
    field_operation_id: validatedBody.field_operation_id || null,
    first_name: validatedBody.first_name || null,
    last_name: validatedBody.last_name || null,
    email: validatedBody.email || null,
    phone: validatedBody.phone || null,
    rut: validatedBody.rut || null,
    date_of_birth: validatedBody.date_of_birth || null,
    gender: validatedBody.gender || null,
    address_line_1: validatedBody.address_line_1 || null,
    address_line_2: validatedBody.address_line_2 || null,
    city: validatedBody.city || null,
    state: validatedBody.state || null,
    postal_code: validatedBody.postal_code || null,
    country: validatedBody.country || "Chile",
    medical_conditions: validatedBody.medical_conditions || null,
    allergies: validatedBody.allergies || null,
    medications: validatedBody.medications || null,
    medical_notes: validatedBody.medical_notes || null,
    last_eye_exam_date: validatedBody.last_eye_exam_date || null,
    next_eye_exam_due: validatedBody.next_eye_exam_due || null,
    preferred_contact_method: validatedBody.preferred_contact_method || null,
    emergency_contact_name: validatedBody.emergency_contact_name || null,
    emergency_contact_phone: validatedBody.emergency_contact_phone || null,
    insurance_provider: validatedBody.insurance_provider || null,
    insurance_policy_number: validatedBody.insurance_policy_number || null,
    notes: validatedBody.notes || null,
    tags: validatedBody.tags || null,
    is_active:
      validatedBody.is_active !== undefined ? validatedBody.is_active : true,
    created_by: user.id,
  };

  const { data: newCustomer, error: customerError } = await supabase
    .from("customers")
    .insert(customerData)
    .select()
    .single();

  if (customerError) {
    return NextResponse.json(
      { error: `Error al crear cliente: ${customerError.message}` },
      { status: 500 },
    );
  }
  if (!newCustomer) {
    return NextResponse.json(
      { error: "Failed to create customer" },
      { status: 500 },
    );
  }

  const newCustomerRecord = newCustomer as Record<string, unknown>;
  const customerName =
    `${validatedBody.first_name || ""} ${validatedBody.last_name || ""}`.trim() ||
    "Cliente";

  NotificationService.notifyNewCustomer(
    newCustomerRecord.id as string,
    customerName,
    (validatedBody.email as string) || undefined,
    (newCustomerRecord.branch_id as string) ??
      customerBranchId ??
      branchContext.branchId ??
      undefined,
  ).catch((err) => logger.error("Error creating notification", err));

  const customerEmail = validatedBody.email as string | undefined;
  if (customerEmail) {
    import("@/lib/email/notifications")
      .then(({ sendAccountWelcome }) =>
        sendAccountWelcome(customerName, customerEmail, userOrgId),
      )
      .catch((err) => logger.error("Error sending account welcome email", err));
  }

  return NextResponse.json({ data: newCustomer }, { status: 201 });
}

/**
 * Customers Service — GET list/search + POST analytics summary.
 *
 * Extracted from route.ts to reduce file size. No behavioral changes.
 */

import { NextRequest } from "next/server";

import {
  addBranchFilter,
  getBranchContext,
  getFieldOperationFromRequest,
} from "@/lib/api/branch-middleware";
import {
  AuthenticationError,
  AuthorizationError,
  ValidationError,
} from "@/lib/api/errors";
import {
  createApiErrorResponse,
  createPaginatedResponse,
  extractPaginationParams,
} from "@/lib/api/response";
import { parseAndValidateQuery } from "@/lib/api/validation/zod-helpers";
import {
  paginationSchema,
  searchCustomerSchema,
} from "@/lib/api/validation/zod-schemas";
import { appLogger as logger } from "@/lib/logger";
import { createClientFromRequest } from "@/lib/supabase/server";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";

export async function handleGetCustomers(
  request: NextRequest,
  requestId: string,
) {
  logger.info("Customers API GET called", { requestId });

  let queryParams: Record<string, unknown>;
  try {
    const combinedSchema = paginationSchema.merge(searchCustomerSchema);
    queryParams = parseAndValidateQuery(request, combinedSchema) as Record<
      string,
      unknown
    >;
  } catch (error) {
    if (error instanceof ValidationError) {
      return createApiErrorResponse(error, { requestId });
    }
    throw error;
  }

  const search = (queryParams.q || queryParams.search || "") as string;
  const status =
    queryParams.is_active !== undefined
      ? (queryParams.is_active as boolean)
        ? "active"
        : "inactive"
      : "";
  const agreementId = (queryParams.agreement_id ?? null) as string | null;
  const { page, limit } = extractPaginationParams(request.url);
  const offset = (page - 1) * limit;

  const { client: supabase, getUser } = await createClientFromRequest(request);
  const user = (await getUser()).data?.user as
    | { id: string; email?: string }
    | undefined;
  if (!user) throw new AuthenticationError("Unauthorized");

  const { data: isAdminResult } = (await supabase.rpc("is_admin", {
    user_id: user.id,
  } as IsAdminParams)) as { data: IsAdminResult | null };
  if (!isAdminResult) throw new AuthorizationError("Admin access required");

  const branchContext = await getBranchContext(request, user.id, supabase);
  const fieldOperationId = getFieldOperationFromRequest(request);
  let effectiveBranchId = branchContext.branchId;

  if (fieldOperationId) {
    const { createServiceRoleClient } = await import("@/lib/supabase/server");
    const serviceSupabase = createServiceRoleClient();
    const { data: fieldOp } = await serviceSupabase
      .from("field_operations")
      .select("id, branch_id, organization_id")
      .eq("id", fieldOperationId)
      .single();
    if (fieldOp) {
      effectiveBranchId = (fieldOp as { branch_id: string }).branch_id;
    }
  }

  const { data: adminUser } = await supabase
    .from("admin_users")
    .select("organization_id")
    .eq("id", user.id)
    .single();

  const userOrganizationId = (
    adminUser as { organization_id: string | null } | null
  )?.organization_id;

  const applyBranchFilter = (query: unknown) => {
    if (userOrganizationId) {
      query = query.eq("organization_id", userOrganizationId);
      if (effectiveBranchId) query = query.eq("branch_id", effectiveBranchId);
      if (fieldOperationId)
        query = query.eq("field_operation_id", fieldOperationId);
    } else if (branchContext.isSuperAdmin) {
      if (effectiveBranchId) query = query.eq("branch_id", effectiveBranchId);
      if (fieldOperationId)
        query = query.eq("field_operation_id", fieldOperationId);
    } else {
      query = addBranchFilter(
        query,
        effectiveBranchId ?? branchContext.branchId,
        branchContext.isSuperAdmin,
        branchContext.organizationId,
      );
      if (fieldOperationId)
        query = query.eq("field_operation_id", fieldOperationId);
    }
    return query;
  };

  // Agreement customer IDs filter
  let agreementCustomerIds: string[] = [];
  if (agreementId) {
    const { data: acRows } = await supabase
      .from("agreement_customers")
      .select("customer_id")
      .eq("agreement_id", agreementId);
    agreementCustomerIds = ((acRows || []) as { customer_id: string }[]).map(
      (r) => r.customer_id,
    );
    if (agreementCustomerIds.length === 0) {
      return createPaginatedResponse(
        [],
        { page, limit, total: 0 },
        { requestId },
      );
    }
  }

  let query = applyBranchFilter(supabase.from("customers").select("*"));
  if (search) {
    query = query.or(
      `first_name.ilike.%${search}%,last_name.ilike.%${search}%,email.ilike.%${search}%,phone.ilike.%${search}%,rut.ilike.%${search}%`,
    );
  }
  if (status === "active") query = query.eq("is_active", true);
  else if (status === "inactive") query = query.eq("is_active", false);
  if (agreementId && agreementCustomerIds.length > 0) {
    query = query.in("id", agreementCustomerIds);
  }

  let countQuery = applyBranchFilter(
    supabase.from("customers").select("*", { count: "exact", head: true }),
  );
  if (search) {
    countQuery = countQuery.or(
      `first_name.ilike.%${search}%,last_name.ilike.%${search}%,email.ilike.%${search}%,phone.ilike.%${search}%,rut.ilike.%${search}%`,
    );
  }
  if (status === "active") countQuery = countQuery.eq("is_active", true);
  else if (status === "inactive")
    countQuery = countQuery.eq("is_active", false);
  if (agreementId && agreementCustomerIds.length > 0) {
    countQuery = countQuery.in("id", agreementCustomerIds);
  }

  const { count, error: countError } = await countQuery;
  if (countError) throw new Error("Failed to count customers");

  const { data: customers, error } = await query
    .range(offset, offset + limit - 1)
    .order("created_at", { ascending: false });
  if (error) throw new Error("Failed to fetch customers");

  // Fetch order aggregates
  const customersArr = (customers || []) as Record<string, unknown>[];
  const customerIds = customersArr.map((c) => c.id as string);
  const orderStatsMap: Record<
    string,
    { totalSpent: number; orderCount: number; lastOrderDate: string | null }
  > = {};

  if (customerIds.length > 0) {
    const { createServiceRoleClient } = await import("@/lib/supabase/server");
    const serviceSupabase = createServiceRoleClient();

    const { data: ordersById } = await serviceSupabase
      .from("orders")
      .select("id, customer_id, email, total_amount, created_at")
      .in("customer_id", customerIds);

    const customerEmailsList = [
      ...new Set(customersArr.map((c) => c.email as string).filter(Boolean)),
    ];
    const { data: ordersByEmail } =
      customerEmailsList.length > 0
        ? await serviceSupabase
            .from("orders")
            .select("id, customer_id, email, total_amount, created_at")
            .is("customer_id", null)
            .in("email", customerEmailsList)
        : { data: [] };

    const ordersByIdArr = (ordersById || []) as Record<string, unknown>[];
    const ordersByEmailArr = (ordersByEmail || []) as Record<string, unknown>[];

    for (const c of customersArr) {
      const byId = ordersByIdArr.filter((o) => o.customer_id === c.id);
      const byEmail = ordersByEmailArr.filter(
        (o) =>
          o.email &&
          (o.email as string).toLowerCase().trim() ===
            ((c.email as string) || "").toLowerCase().trim(),
      );
      const allOrders = [...byId, ...byEmail];

      const totalSpent = allOrders.reduce(
        (s, o) => s + ((o.total_amount as number) || 0),
        0,
      );
      const orderCount = allOrders.length;
      const lastOrder =
        allOrders.length > 0
          ? [...allOrders].sort(
              (a, b) =>
                new Date(b.created_at as string).getTime() -
                new Date(a.created_at as string).getTime(),
            )[0]
          : null;

      orderStatsMap[c.id as string] = {
        totalSpent,
        orderCount,
        lastOrderDate: lastOrder
          ? (lastOrder.created_at as string) || null
          : null,
      };
    }
  }

  // Fetch is_convenio_client
  const convenioCustomerIds = new Set<string>();
  if (customerIds.length > 0) {
    const { data: acRows } = await supabase
      .from("agreement_customers")
      .select("customer_id")
      .in("customer_id", customerIds);
    ((acRows || []) as { customer_id: string }[]).forEach((r) =>
      convenioCustomerIds.add(r.customer_id),
    );
  }

  const customerStats = customersArr.map((c) => {
    const stats = orderStatsMap[c.id as string] || {
      totalSpent: 0,
      orderCount: 0,
      lastOrderDate: null,
    };
    const { totalSpent, orderCount, lastOrderDate } = stats;
    const avgOrderValue = orderCount > 0 ? totalSpent / orderCount : 0;

    let segment = "new";
    if (orderCount > 10) segment = "vip";
    else if (orderCount > 3) segment = "regular";
    else if (orderCount > 0) segment = "first-time";

    return {
      ...c,
      is_convenio_client: convenioCustomerIds.has(c.id as string),
      analytics: {
        totalSpent,
        orderCount,
        lastOrderDate,
        avgOrderValue,
        segment,
        lifetimeValue: totalSpent,
      },
    };
  });

  return createPaginatedResponse(
    customerStats,
    { page, limit, total: (count as number) || 0 },
    { requestId },
  );
}

export { handleCustomersAnalytics } from "./customersAnalyticsService";

import { NextRequest, NextResponse } from "next/server";

import { AuthenticationError, RateLimitError } from "@/lib/api/errors";
import { createApiErrorResponse } from "@/lib/api/response";
import { appLogger as logger } from "@/lib/logger";
import { rateLimitConfigs, withRateLimit } from "@/lib/rate-limiting";
import { createClientFromRequest } from "@/utils/supabase/server";

import { handleCreateCustomer } from "./customersCreateService";
import {
  handleCustomersAnalytics,
  handleGetCustomers,
} from "./customersService";

export const dynamic = "force-dynamic";

export async function GET(request: NextRequest) {
  const requestId = crypto.randomUUID();

  try {
    return await handleGetCustomers(request, requestId);
  } catch (error) {
    logger.error("Error in customers API GET", { error, requestId });
    return createApiErrorResponse(
      error instanceof Error ? error : new Error("Internal server error"),
      { requestId },
    );
  }
}

export async function POST(request: NextRequest) {
  const requestId = crypto.randomUUID();

  try {
    return await (withRateLimit(rateLimitConfigs.modification) as unknown)(
      request,
      async () => {
        try {
          const { getUser } = await createClientFromRequest(request);
          const { data, error: userError } = await getUser();
          const user = data?.user;
          if (userError || !user) {
            return createApiErrorResponse(
              new AuthenticationError("Unauthorized"),
            );
          }

          let body: unknown;
          try {
            body = await request.json();
          } catch {
            return NextResponse.json(
              { error: "Invalid JSON in request body" },
              { status: 400 },
            );
          }

          const bodyRecord = body as Record<string, unknown>;
          const isCustomerCreation =
            "first_name" in bodyRecord ||
            "last_name" in bodyRecord ||
            bodyRecord.first_name ||
            bodyRecord.last_name;

          if (isCustomerCreation) {
            return await handleCreateCustomer(request, body);
          }

          return await handleCustomersAnalytics(request, requestId);
        } catch (error) {
          if (error instanceof RateLimitError) {
            return NextResponse.json({ error: error.message }, { status: 429 });
          }
          return createApiErrorResponse(
            error instanceof Error ? error : new Error(String(error)),
          );
        }
      },
    );
  } catch (error) {
    if (error instanceof RateLimitError) {
      return NextResponse.json({ error: error.message }, { status: 429 });
    }
    return createApiErrorResponse(
      error instanceof Error ? error : new Error(String(error)),
    );
  }
}

/**
 * Search helpers for customer search route.
 * Extracted from route.ts to reduce file size. No behavioral changes.
 */
import {
  getBranchContext,
  getFieldOperationFromRequest,
} from "@/lib/api/branch-middleware";
import { createServiceRoleClient } from "@/utils/supabase/server";

export async function resolveBranchContext(
  request: unknown,
  user: unknown,
  supabase: unknown,
) {
  const branchContext = await getBranchContext(request, user.id, supabase);
  const supabaseServiceRole = createServiceRoleClient();

  let orgBranchIds: string[] | null = null;
  if (
    !branchContext.branchId &&
    branchContext.isSuperAdmin &&
    branchContext.organizationId
  ) {
    const { data: branches } = await supabaseServiceRole
      .from("branches")
      .select("id")
      .eq("organization_id", branchContext.organizationId);
    orgBranchIds = branches?.map((b: unknown) => b.id) || [];
  }

  const fieldOperationId = getFieldOperationFromRequest(request);
  let operativoBranchId: string | null = null;
  if (fieldOperationId) {
    const { data: fo } = await supabaseServiceRole
      .from("field_operations")
      .select("branch_id")
      .eq("id", fieldOperationId)
      .single();
    operativoBranchId = (fo as unknown)?.branch_id ?? null;
  }

  return { branchContext, orgBranchIds, fieldOperationId, operativoBranchId };
}

export function buildSearchQuery(
  supabase: unknown,
  branchContext: unknown,
  orgBranchIds: string[] | null,
  fieldOperationId: string | null,
  operativoBranchId: string | null,
) {
  return () => {
    const q = supabase
      .from("customers")
      .select("id, first_name, last_name, email, phone, rut");
    const { branchId, isSuperAdmin, organizationId, accessibleBranches } =
      branchContext;
    if (fieldOperationId && operativoBranchId)
      return q
        .eq("branch_id", operativoBranchId)
        .eq("field_operation_id", fieldOperationId);
    if (branchId) return q.eq("branch_id", branchId);
    if (isSuperAdmin && orgBranchIds && orgBranchIds.length > 0)
      return q.in("branch_id", orgBranchIds);
    if (isSuperAdmin && organizationId)
      return q.eq("branch_id", "00000000-0000-0000-0000-000000000000");
    const primary =
      accessibleBranches.find((b: unknown) => b.isPrimary)?.id ||
      accessibleBranches[0]?.id;
    return q.eq("branch_id", primary || "00000000-0000-0000-0000-000000000000");
  };
}

export function getRpcBranchParams(
  branchContext: unknown,
  orgBranchIds: string[] | null,
  fieldOperationId: string | null,
  operativoBranchId: string | null,
) {
  let rpcBranchId: string | null = null;
  let rpcBranchIds: string[] | null = null;
  if (fieldOperationId && operativoBranchId) rpcBranchId = operativoBranchId;
  else if (branchContext.branchId) rpcBranchId = branchContext.branchId;
  else if (branchContext.isSuperAdmin && branchContext.organizationId)
    rpcBranchIds = orgBranchIds;
  else if (!branchContext.isSuperAdmin) rpcBranchIds = [];
  return { rpcBranchId, rpcBranchIds };
}

export function buildOrQuery(
  searchTerm: string,
  normalizedSearchTerm: string,
  formattedSearchTerm: string,
  isRutSearch: boolean,
) {
  let orQuery = `first_name.ilike.%${searchTerm}%,last_name.ilike.%${searchTerm}%,email.ilike.%${searchTerm}%,phone.ilike.%${searchTerm}%`;
  if (isRutSearch) {
    orQuery += `,rut.ilike.%${searchTerm}%,rut.ilike.%${normalizedSearchTerm}%,rut.ilike.%${formattedSearchTerm}%`;
  } else {
    orQuery += `,rut.ilike.%${searchTerm}%`;
  }
  return orQuery;
}

export async function searchByRut(
  supabase: unknown,
  searchTerm: string,
  normalizedSearchTerm: string,
  rpcBranchId: string | null,
  rpcBranchIds: string[] | null,
) {
  try {
    const params = (term: string) => {
      const p: Record<string, unknown> = { rut_search_term: term };
      if (rpcBranchIds && rpcBranchIds.length === 0) return null;
      if (rpcBranchId) p.p_branch_id = rpcBranchId;
      else if (rpcBranchIds && rpcBranchIds.length > 0)
        p.p_branch_ids = rpcBranchIds;
      return p;
    };

    const p1 = params(searchTerm);
    const p2 = params(normalizedSearchTerm);
    if (p1 === null || p2 === null) return [];

    const [{ data: r1 }, { data: r2 }] = await Promise.all([
      supabase.rpc("search_customers_by_rut", p1).catch(() => ({ data: [] })),
      supabase.rpc("search_customers_by_rut", p2).catch(() => ({ data: [] })),
    ]);

    const map = new Map();
    [...(r1 || []), ...(r2 || [])].forEach((c: unknown) => {
      if (!map.has(c.id)) map.set(c.id, c);
    });
    return Array.from(map.values());
  } catch {
    return [];
  }
}

import { NextRequest, NextResponse } from "next/server";

import { RateLimitError } from "@/lib/api/errors";
import { createApiErrorResponse, createApiSuccessResponse } from "@/lib/api/response";
import { appLogger as logger } from "@/lib/logger";
import { rateLimitConfigs, withRateLimit } from "@/lib/rate-limiting";
import { formatRUT, normalizeRUT } from "@/lib/utils/rut";
import { createClientFromRequest } from "@/utils/supabase/server";

import { buildOrQuery, buildSearchQuery, getRpcBranchParams, resolveBranchContext, searchByRut } from "../searchHelpers";

export const dynamic = "force-dynamic";

export async function GET(request: NextRequest) {
  const requestId = crypto.randomUUID();
  try {
    return await (withRateLimit(rateLimitConfigs.search) as unknown)(request, async () => {
      try {
        const { client: supabase, getUser } = await createClientFromRequest(request);
        const { data: userData } = await getUser();
        const user = userData?.user as { id: string } | undefined;
        if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

        const { data: isAdmin } = await supabase.rpc("is_admin", { user_id: user.id });
        if (!isAdmin) return NextResponse.json({ error: "Admin access required" }, { status: 403 });

        const { branchContext, orgBranchIds, fieldOperationId, operativoBranchId } = await resolveBranchContext(request, user, supabase);
        const { rpcBranchId, rpcBranchIds } = getRpcBranchParams(branchContext, orgBranchIds, fieldOperationId, operativoBranchId);
        const buildFilteredCustomersQuery = buildSearchQuery(supabase, branchContext, orgBranchIds, fieldOperationId, operativoBranchId);

        const query = (request.nextUrl.searchParams.get("q") || "").trim();
        if (query.length < 1) return createApiSuccessResponse([], { requestId });

        const normalizedSearchTerm = normalizeRUT(query);
        const formattedSearchTerm = formatRUT(normalizedSearchTerm);
        const isRutSearch = /^[\d.\-Kk\s]+$/.test(query) && normalizedSearchTerm.length >= 2;

        let customers: unknown[] = [];

        // Approach 1: RUT search via SQL function
        if (isRutSearch && !fieldOperationId) {
          const rutCustomers = await searchByRut(supabase, query, normalizedSearchTerm, rpcBranchId, rpcBranchIds);
          customers.push(...rutCustomers);
        }

        // Approach 2: Standard ilike search
        try {
          const orQuery = buildOrQuery(query, normalizedSearchTerm, formattedSearchTerm, isRutSearch);
          const result = await buildFilteredCustomersQuery().or(orQuery).limit(20);

          const existingIds = new Set(customers.map((c: unknown) => c.id));
          (result.data || []).forEach((c: unknown) => { if (!existingIds.has(c.id)) { customers.push(c); existingIds.add(c.id); } });

          if (result.error) throw result.error;
        } catch (orError: unknown) {
          logger.warn("OR query failed, trying alternative approach", orError);
          try {
            const searchPattern = `%${query}%`;
            const normalizedPattern = `%${normalizedSearchTerm}%`;
            const formattedPattern = `%${formattedSearchTerm}%`;

            const queries: Promise<unknown>[] = [
              buildFilteredCustomersQuery().or(`first_name.ilike.${searchPattern},last_name.ilike.${searchPattern}`).limit(20) as unknown,
              buildFilteredCustomersQuery().ilike("email", searchPattern).limit(20) as unknown,
              buildFilteredCustomersQuery().ilike("phone", searchPattern).limit(20) as unknown,
            ];
            if (isRutSearch) {
              queries.push(buildFilteredCustomersQuery().ilike("rut", searchPattern).limit(20) as unknown);
              queries.push(buildFilteredCustomersQuery().ilike("rut", normalizedPattern).limit(20) as unknown);
              queries.push(buildFilteredCustomersQuery().ilike("rut", formattedPattern).limit(20) as unknown);
            } else {
              queries.push(buildFilteredCustomersQuery().ilike("rut", searchPattern).limit(20) as unknown);
            }

            const results = await Promise.all(queries);
            const existingIds = new Set(customers.map((c: unknown) => c.id));
            results.forEach((r: unknown) => { if (r.data) r.data.forEach((c: unknown) => { if (!existingIds.has(c.id)) { customers.push(c); existingIds.add(c.id); } }); });
            customers = customers.slice(0, 20);
          } catch (fallbackError: unknown) {
            logger.error("Fallback search also failed", fallbackError);
            throw fallbackError;
          }
        }

        return createApiSuccessResponse(customers, { requestId });
      } catch (error) {
        if (error instanceof RateLimitError) {
          return NextResponse.json({ error: error.message }, { status: 429 });
        }
        const err = error instanceof Error ? error : new Error(String(error));
        logger.error("Error in customer search API", err);
        return createApiErrorResponse(err, { requestId });
      }
    });
  } catch (error) {
    if (error instanceof RateLimitError) {
      return NextResponse.json({ error: error.message }, { status: 429 });
    }
    logger.error("Unexpected error in GET handler", error instanceof Error ? error : new Error(String(error)));
    return NextResponse.json({ error: error instanceof Error ? error.message : "Internal server error" }, { status: 500 });
  }
}

import { NextRequest } from "next/server";

import { computeInventoryMetrics } from "@/lib/analytics/analytics-service";
import { computeDashboardKpis } from "@/lib/analytics/compute-dashboard-kpis";
import { getBranchContext } from "@/lib/api/branch-middleware";
import { AuthenticationError, AuthorizationError } from "@/lib/api/errors";
import { createApiErrorResponse, createApiSuccessResponse } from "@/lib/api/response";
import { appLogger as logger } from "@/lib/logger";
import { createClientFromRequest } from "@/utils/supabase/server";

import { buildApplyBranchFilter, buildLegacyScope, buildOrgBranchIdsQuery, computeStatusDistribution, getLocalDateString, processTopProducts } from "./_helpers/dashboardHelpers";

export const dynamic = "force-dynamic";

export async function GET(request: NextRequest) {
  try {
    const { client: supabase, getUser } = await createClientFromRequest(request);
    const { data: userData, error: userError } = await getUser();
    if (userError || !userData?.user) return createApiErrorResponse(new AuthenticationError("Unauthorized"));

    const { data: isAdmin } = await supabase.rpc("is_admin", { user_id: userData.user.id });
    if (!isAdmin) return createApiErrorResponse(new AuthorizationError("Admin access required"));

    const branchContext = await getBranchContext(request, userData.user.id);
    const { searchParams } = new URL(request.url);
    const periodDays = Math.min(365, Math.max(7, parseInt(searchParams.get("period") || "7", 10) || 7));

    const now = new Date();
    const todayStr = getLocalDateString(now);
    const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
    const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
    const startOfLastMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    const trendStart = new Date(now.getTime() - periodDays * 24 * 60 * 60 * 1000);
    const mvStartDate = startOfLastMonth < trendStart ? startOfLastMonth : trendStart;

    const applyBranchFilter = buildApplyBranchFilter(branchContext);
    const orgBranchIds = await buildOrgBranchIdsQuery(supabase, branchContext);
    const legacyScope = buildLegacyScope(supabase, branchContext, orgBranchIds, applyBranchFilter);

    const [productsResult, mvResult, customersResult, pbsResult, ordersAggResult, quotesAggResult, topProductsResult] = await Promise.all([
      supabase.from("products").select("*").eq("status", "active").then((r: unknown) => {
        let q = r; const bc = branchContext;
        if (bc.branchId) q = q.eq("organization_id", bc.organizationId || "00000000-0000-0000-0000-000000000000");
        else if (bc.isSuperAdmin && bc.organizationId) q = q.eq("organization_id", bc.organizationId);
        else q = applyBranchFilter(q);
        return q;
      }),
      (() => {
        let q = supabase.from("mv_daily_kpis").select("*").gte("day", getLocalDateString(mvStartDate)).lte("day", todayStr);
        if (branchContext.organizationId) q = q.eq("organization_id", branchContext.organizationId);
        if (branchContext.branchId) q = q.eq("branch_id", branchContext.branchId);
        return q;
      })(),
      applyBranchFilter(supabase.from("customers").select("*")),
      (() => {
        let q = supabase.from("product_branch_stock").select("product_id, branch_id, quantity, low_stock_threshold");
        if (branchContext.branchId) q = q.eq("branch_id", branchContext.branchId);
        else if (orgBranchIds.length > 0) q = q.in("branch_id", orgBranchIds);
        else q = q.limit(0);
        return q;
      })(),
      legacyScope(supabase.from("orders").select("status, created_at, total_amount, payment_status").gte("created_at", startOfLastMonth.toISOString())),
      legacyScope(supabase.from("quotes").select("id, status, converted_to_work_order_id")),
      legacyScope(supabase.from("orders").select("order_items (product_name, total_price, quantity)").or("status.eq.completed,payment_status.eq.paid").gte("created_at", startOfLastMonth.toISOString())),
    ]);

    const products = (productsResult as unknown)?.data || [];
    const mvRows = (mvResult as unknown)?.data || [];
    const customers = (customersResult as unknown)?.data || [];
    const productBranchStock = (pbsResult as unknown)?.data || [];
    const ordersLight = (ordersAggResult as unknown)?.data || [];
    const quotesLight = (quotesAggResult as unknown)?.data || [];
    const topProductsData = (topProductsResult as unknown)?.data || [];

    const activeProducts = products.filter((p: unknown) => p.status === "active");
    const productIds = new Set(activeProducts.map((p: unknown) => p.id));
    const inventoryMetrics = computeInventoryMetrics(productBranchStock, productIds, { products: activeProducts.map((p: unknown) => ({ id: p.id, name: p.name, slug: p.slug })), maxLowStockList: 5 });

    return createApiSuccessResponse({
      branch: { id: branchContext.branchId, is_global: branchContext.isGlobalView, is_super_admin: branchContext.isSuperAdmin },
      kpis: {
        products: { total: activeProducts.length, lowStock: inventoryMetrics.lowStock, outOfStock: inventoryMetrics.outOfStock },
        orders: { total: computeDashboardKpis(mvRows, now).orders.total, pending: ordersLight.filter((o: unknown) => o.status === "pending").length, processing: ordersLight.filter((o: unknown) => o.status === "processing").length, completed: ordersLight.filter((o: unknown) => o.status === "completed").length, failed: ordersLight.filter((o: unknown) => o.status === "failed").length },
        revenue: computeDashboardKpis(mvRows, now).revenue,
        customers: { total: customers.length, new: customers.filter((c: unknown) => new Date(c.created_at) >= thirtyDaysAgo).length, returning: Math.max(0, customers.length - customers.filter((c: unknown) => new Date(c.created_at) >= thirtyDaysAgo).length) },
        appointments: await computeAppointments(supabase, branchContext, orgBranchIds, todayStr, applyBranchFilter),
        workOrders: computeDashboardKpis(mvRows, now).workOrders,
        quotes: { total: computeDashboardKpis(mvRows, now).quotes.total, pending: quotesLight.filter((q: unknown) => ["draft", "sent"].includes(q.status) && !q.converted_to_work_order_id).length, converted: quotesLight.filter((q: unknown) => q.status === "accepted" || q.converted_to_work_order_id).length },
      },
      todayAppointments: await computeTodayAppointmentsList(supabase, branchContext, orgBranchIds, todayStr, applyBranchFilter),
      lowStockProducts: inventoryMetrics.lowStockProductsList ?? [],
      charts: { revenueTrend: computeDashboardKpis(mvRows, now).charts.revenueTrend, ordersStatus: computeStatusDistribution(ordersLight, thirtyDaysAgo), topProducts: processTopProducts(topProductsData) },
    });
  } catch (error) {
    logger.error("Dashboard API error", error as Error);
    return createApiErrorResponse(error instanceof Error ? error : new Error(String(error)));
  }
}

async function computeAppointments(supabase: unknown, bc: unknown, orgBranchIds: string[], todayStr: string, applyFilter: unknown) {
  const q = buildApptQuery(supabase, bc, orgBranchIds, todayStr, applyFilter);
  const { data: appointments } = await q;
  const a = appointments || [];
  return { today: a.length, scheduled: a.filter((x: unknown) => x.status === "scheduled").length, confirmed: a.filter((x: unknown) => x.status === "confirmed").length, pending: a.filter((x: unknown) => x.status === "scheduled" || x.status === "pending").length };
}

async function computeTodayAppointmentsList(supabase: unknown, bc: unknown, orgBranchIds: string[], todayStr: string, applyFilter: unknown) {
  const q = buildApptQuery(supabase, bc, orgBranchIds, todayStr, applyFilter).order("appointment_time", { ascending: true }).limit(10);
  const { data: todayData } = await q;
  const customerIds = [...new Set((todayData || []).map((a: unknown) => a.customer_id).filter(Boolean))];
  const { data: customersForAppts } = customerIds.length > 0 ? await supabase.from("customers").select("id, first_name, last_name, email, phone").in("id", customerIds) : { data: [] };
  return (todayData || []).map((apt: unknown) => {
    const c = customersForAppts?.find((x: unknown) => x.id === apt.customer_id);
    return { id: apt.id, customer_name: c ? `${c.first_name || ""} ${c.last_name || ""}`.trim() || c.email || "Cliente" : "Cliente", customer_email: c?.email || null, appointment_time: apt.appointment_time, appointment_type: apt.appointment_type || "consultation", status: apt.status, duration_minutes: apt.duration_minutes || 30, notes: apt.notes };
  });
}

function buildApptQuery(supabase: unknown, bc: unknown, orgBranchIds: string[], todayStr: string, applyFilter: unknown) {
  if (bc.isSuperAdmin && !bc.branchId && bc.organizationId && orgBranchIds.length > 0) {
    return supabase.from("appointments").select("*").eq("appointment_date", todayStr).or(`organization_id.eq.${bc.organizationId},branch_id.in.(${orgBranchIds.join(",")})`);
  }
  if (bc.branchId) return supabase.from("appointments").select("*").eq("appointment_date", todayStr).or(`branch_id.eq.${bc.branchId},branch_id.is.null`);
  return applyFilter(supabase.from("appointments").select("*").eq("appointment_date", todayStr));
}

import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import { createClient } from "@/utils/supabase/server";

interface RouteParams {
  params: Promise<{ id: string }>;
}

// GET /api/admin/drivers/[id] - Get specific driver
export const dynamic = "force-dynamic";
export async function GET(req: NextRequest, { params }: RouteParams) {
  try {
    const supabase = await createClient();
    const { id } = await params;

    // Get user
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user)
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

    // Get branch context
    const branchContext = await getBranchContext(req, user.id, supabase);
    if (!branchContext.branchId && !branchContext.isGlobalView) {
      return NextResponse.json({ error: "No branch access" }, { status: 403 });
    }

    const { data: driver, error } = await supabase
      .from("drivers")
      .select("*")
      .eq("id", id)
      .eq("organization_id", branchContext.organizationId)
      .single();

    if (error) {
      if (error.code === "PGRST116") {
        return NextResponse.json(
          { error: "Driver not found" },
          { status: 404 },
        );
      }
      logger.error("Failed to fetch driver", { error: error.message });
      return NextResponse.json(
        { error: "Failed to fetch driver" },
        { status: 500 },
      );
    }

    return NextResponse.json(driver);
  } catch (error) {
    logger.error("Driver detail error", { error });
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

// PUT /api/admin/drivers/[id] - Update driver
export async function PUT(req: NextRequest, { params }: RouteParams) {
  try {
    const supabase = await createClient();
    const { id } = await params;

    // Get user
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user)
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

    // Get branch context
    const branchContext = await getBranchContext(req, user.id, supabase);
    if (!branchContext.branchId && !branchContext.isGlobalView) {
      return NextResponse.json({ error: "No branch access" }, { status: 403 });
    }

    const body = await req.json();
    const { name, license_number, phone, email, is_active } = body;

    // Validation
    if (license_number) {
      // Check if another driver has this license number
      const { data: existingDriver } = await supabase
        .from("drivers")
        .select("id")
        .eq("license_number", license_number)
        .eq("organization_id", branchContext.organizationId)
        .neq("id", id)
        .maybeSingle();

      if (existingDriver) {
        return NextResponse.json(
          { error: "Another driver with this license number already exists" },
          { status: 400 },
        );
      }
    }

    // Prepare update data
    const updateData: unknown = {};

    if (name !== undefined) updateData.name = name;
    if (license_number !== undefined)
      updateData.license_number = license_number;
    if (phone !== undefined) updateData.phone = phone;
    if (email !== undefined) updateData.email = email;
    if (is_active !== undefined) updateData.is_active = is_active;

    const { data: driver, error } = await supabase
      .from("drivers")
      .update(updateData)
      .eq("id", id)
      .eq("organization_id", branchContext.organizationId)
      .select()
      .single();

    if (error) {
      logger.error("Failed to update driver", { error: error.message });
      return NextResponse.json(
        { error: "Failed to update driver" },
        { status: 500 },
      );
    }

    if (!driver) {
      return NextResponse.json({ error: "Driver not found" }, { status: 404 });
    }

    logger.info("Driver updated", {
      driverId: id,
      userId: user.id,
    });

    return NextResponse.json(driver);
  } catch (error) {
    logger.error("Driver update error", { error });
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

// DELETE /api/admin/drivers/[id] - Delete driver
export async function DELETE(req: NextRequest, { params }: RouteParams) {
  try {
    const supabase = await createClient();
    const { id } = await params;

    // Get user
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user)
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

    // Get branch context
    const branchContext = await getBranchContext(req, user.id, supabase);
    if (!branchContext.branchId && !branchContext.isGlobalView) {
      return NextResponse.json({ error: "No branch access" }, { status: 403 });
    }

    // Check if driver is assigned to any active orders
    const { data: assignedOrders } = await supabase
      .from("internal_orders")
      .select("id")
      .eq("assigned_driver_id", id)
      .in("status", ["pending", "confirmed", "in_transit"])
      .maybeSingle();

    if (assignedOrders) {
      return NextResponse.json(
        { error: "Cannot delete driver assigned to active orders" },
        { status: 400 },
      );
    }

    const { error } = await supabase
      .from("drivers")
      .delete()
      .eq("id", id)
      .eq("organization_id", branchContext.organizationId);

    if (error) {
      logger.error("Failed to delete driver", { error: error.message });
      return NextResponse.json(
        { error: "Failed to delete driver" },
        { status: 500 },
      );
    }

    logger.info("Driver deleted", {
      driverId: id,
      userId: user.id,
    });

    return NextResponse.json({ message: "Driver deleted successfully" });
  } catch (error) {
    logger.error("Driver deletion error", { error });
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import { createClient } from "@/utils/supabase/server";

// GET /api/admin/drivers/available - Get available drivers (not assigned to active orders)
export const dynamic = "force-dynamic";
export async function GET(req: NextRequest) {
  try {
    const supabase = await createClient();

    // Get user
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user)
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

    // Get branch context
    const branchContext = await getBranchContext(req, user.id, supabase);
    if (!branchContext.branchId && !branchContext.isGlobalView) {
      return NextResponse.json({ error: "No branch access" }, { status: 403 });
    }

    // Get drivers not assigned to active orders
    const { data: activeOrderDrivers, error: ordersError } = await supabase
      .from("internal_orders")
      .select("assigned_driver_id")
      .eq("organization_id", branchContext.organizationId)
      .in("status", ["pending", "confirmed", "in_transit"])
      .not("assigned_driver_id", "is", null);

    if (ordersError) {
      logger.error("Failed to fetch active orders", {
        error: ordersError.message,
      });
      return NextResponse.json(
        { error: "Failed to fetch data" },
        { status: 500 },
      );
    }

    const assignedDriverIds =
      activeOrderDrivers?.map((o: unknown) => o.assigned_driver_id) || [];

    // Get available drivers
    let query = supabase
      .from("drivers")
      .select("*")
      .eq("organization_id", branchContext.organizationId)
      .eq("is_active", true);

    if (assignedDriverIds.length > 0) {
      query = query.not("id", "in", `(${assignedDriverIds.join(",")})`);
    }

    const { data: drivers, error } = await query.order("name");

    if (error) {
      logger.error("Failed to fetch available drivers", {
        error: error.message,
      });
      return NextResponse.json(
        { error: "Failed to fetch available drivers" },
        { status: 500 },
      );
    }

    return NextResponse.json(drivers);
  } catch (error) {
    logger.error("Available drivers error", { error });
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import { createClient } from "@/utils/supabase/server";

// GET /api/admin/drivers - List drivers
export const dynamic = "force-dynamic";
export async function GET(req: NextRequest) {
  try {
    const supabase = await createClient();

    // Get user
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user)
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

    // Get branch context
    const branchContext = await getBranchContext(req, user.id, supabase);
    if (!branchContext.branchId && !branchContext.isGlobalView) {
      return NextResponse.json({ error: "No branch access" }, { status: 403 });
    }

    const { searchParams } = new URL(req.url);
    const isActive = searchParams.get("is_active");
    const page = parseInt(searchParams.get("page") || "1");
    const limit = parseInt(searchParams.get("limit") || "20");

    const offset = (page - 1) * limit;

    // Build query
    let query = supabase
      .from("drivers")
      .select("*", { count: "exact" })
      .eq("organization_id", branchContext.organizationId);

    // Apply filters
    if (isActive !== null) {
      query = query.eq("is_active", isActive === "true");
    }

    // Execute query with pagination
    const {
      data: drivers,
      error,
      count,
    } = await query.order("name").range(offset, offset + limit - 1);

    if (error) {
      logger.error("Failed to fetch drivers", { error: error.message });
      return NextResponse.json(
        { error: "Failed to fetch drivers" },
        { status: 500 },
      );
    }

    return NextResponse.json({
      drivers,
      pagination: {
        page,
        limit,
        total: count,
        totalPages: Math.ceil(count! / limit),
      },
    });
  } catch (error) {
    logger.error("Drivers list error", { error });
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

// POST /api/admin/drivers - Create new driver
export async function POST(req: NextRequest) {
  try {
    const supabase = await createClient();

    // Get user
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user)
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

    // Get branch context
    const branchContext = await getBranchContext(req, user.id, supabase);
    if (!branchContext.branchId && !branchContext.isGlobalView) {
      return NextResponse.json({ error: "No branch access" }, { status: 403 });
    }

    const body = await req.json();
    const { name, license_number, phone, email, is_active = true } = body;

    // Validation
    if (!name || !license_number) {
      return NextResponse.json(
        { error: "Name and license number are required" },
        { status: 400 },
      );
    }

    // Check if license number already exists
    const { data: existingDriver } = await supabase
      .from("drivers")
      .select("id")
      .eq("license_number", license_number)
      .eq("organization_id", branchContext.organizationId)
      .maybeSingle();

    if (existingDriver) {
      return NextResponse.json(
        { error: "Driver with this license number already exists" },
        { status: 400 },
      );
    }

    // Create driver
    const { data: driver, error } = await supabase
      .from("drivers")
      .insert({
        name,
        license_number,
        phone,
        email,
        is_active,
        organization_id: branchContext.organizationId,
      })
      .select()
      .single();

    if (error) {
      logger.error("Failed to create driver", { error: error.message });
      return NextResponse.json(
        { error: "Failed to create driver" },
        { status: 500 },
      );
    }

    logger.info("Driver created", {
      driverId: driver.id,
      licenseNumber: driver.license_number,
      userId: user.id,
    });

    return NextResponse.json(driver, { status: 201 });
  } catch (error) {
    logger.error("Driver creation error", { error });
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { LLMFactory } from "@/lib/ai/factory";
import type { LLMProvider } from "@/lib/ai/types";
import { buildVariablesPromptForAgent } from "@/lib/email/ai-template-variables";
import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

/**
 * POST /api/admin/email-templates/ai-assist
 * AI-assisted email template generation.
 * Receives: { type, organizationId?, userPrompt }
 * Returns: { subject, content }
 *
 * El agente usa las variables definidas en ai-template-variables.ts,
 * alineadas con notifications.ts y optica.ts. Usar organization_name (no company_name).
 */
export const dynamic = "force-dynamic";

export async function POST(request: NextRequest) {
  try {
    const supabase = await createClient();
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    const body = await request.json();
    const { type, organizationId, userPrompt } = body;

    if (!userPrompt || typeof userPrompt !== "string") {
      return NextResponse.json(
        { error: "userPrompt is required" },
        { status: 400 },
      );
    }

    const templateType = type || "custom";
    const variablesPrompt = buildVariablesPromptForAgent(templateType);

    let orgInfo: { name?: string; primary_color?: string } | null = null;
    if (organizationId) {
      const { data: org } = await supabase
        .from("organizations")
        .select("name, metadata")
        .eq("id", organizationId)
        .single();
      orgInfo = org
        ? {
            name: org.name,
            primary_color: (org.metadata as { primary_color?: string })
              ?.primary_color,
          }
        : null;
    }

    const systemPrompt = `Eres un asistente que genera plantillas de email para una óptica. El usuario describe lo que quiere y tú devuelves un subject (asunto) y content (HTML del cuerpo del email).

Tipo de plantilla: ${templateType}

Variables disponibles (OBLIGATORIO usar solo estas, con sintaxis {{variable_name}}):
${variablesPrompt}

REGLAS CRÍTICAS:
- NUNCA uses customer_first_name; usa customer_name para el saludo.
- Usa organization_name para el nombre de la óptica (company_name es alias, mismo valor).
${orgInfo?.name ? `Nombre de la óptica en este contexto: ${orgInfo.name}` : ""}
${orgInfo?.primary_color ? `Color primario sugerido: ${orgInfo.primary_color}` : ""}

Responde ÚNICAMENTE con un JSON válido en este formato exacto, sin markdown ni texto adicional:
{"subject":"Asunto del email","content":"<html>...</html>"}

El content debe ser HTML completo, con estilos inline o en <style>. Usa las variables con doble llave {{variable_name}}. Mantén el diseño limpio y profesional.`;

    const factory = LLMFactory.getInstance();
    const { provider, config } = await factory.createProviderWithFallback(
      "deepseek" as LLMProvider,
      { temperature: 0.7, maxTokens: 4000 },
    );

    const response = await provider.generateText(
      [
        { role: "system", content: systemPrompt },
        { role: "user", content: userPrompt },
      ],
      undefined,
      config,
    );

    const text = response?.content?.trim() || "";
    const jsonMatch = text.match(/\{[\s\S]*\}/);
    const jsonStr = jsonMatch ? jsonMatch[0] : text;

    let parsed: { subject?: string; content?: string };
    try {
      parsed = JSON.parse(jsonStr);
    } catch {
      logger.warn("AI assist: failed to parse LLM response as JSON", {
        response: text.slice(0, 200),
      });
      return NextResponse.json(
        {
          error: "No se pudo generar la plantilla. Intenta de nuevo.",
          subject: "",
          content: "",
        },
        { status: 200 },
      );
    }

    return NextResponse.json({
      subject: parsed.subject || "",
      content: parsed.content || "",
    });
  } catch (error) {
    logger.error("Email template AI assist error", { error });
    return NextResponse.json(
      {
        error: "Error al generar plantilla",
        details: error instanceof Error ? error.message : "Unknown error",
      },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { validateBranchAccess } from "@/lib/api/branch-middleware";
import { AuthenticationError, AuthorizationError , ValidationError } from "@/lib/api/errors";
import {
  createApiErrorResponse,
  createApiSuccessResponse,
} from "@/lib/api/response";
import {
  parseAndValidateBody,
  validationErrorResponse,
} from "@/lib/api/validation/zod-helpers";
import { deliverFieldOperationSchema } from "@/lib/api/validation/zod-schemas";
import { sendDeliveryCompletionEmail } from "@/lib/email/send-delivery-completion-email";
import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const requestId = crypto.randomUUID();

  try {
    const supabase = await createClient();

    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      throw new AuthenticationError("Unauthorized");
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      throw new AuthorizationError("Admin access required");
    }

    const { id: fieldOperationId } = await params;

    const { data: operation, error: opError } = await supabase
      .from("field_operations")
      .select("id, branch_id")
      .eq("id", fieldOperationId)
      .single();

    if (opError || !operation) {
      return NextResponse.json(
        { error: "Operativo no encontrado" },
        { status: 404 },
      );
    }

    const hasAccess = await validateBranchAccess(user.id, operation.branch_id);
    if (!hasAccess) {
      return NextResponse.json(
        { error: "No tiene acceso a este operativo" },
        { status: 403 },
      );
    }

    let validatedBody;
    try {
      validatedBody = await parseAndValidateBody(
        request,
        deliverFieldOperationSchema,
      );
    } catch (error) {
      if (error instanceof ValidationError) {
        return validationErrorResponse(error);
      }
      throw error;
    }

    const deliveredAt = validatedBody.delivered_at
      ? validatedBody.delivered_at.toISOString()
      : new Date().toISOString();

    const updated: string[] = [];
    const failed: { id: string; error: string }[] = [];

    for (const workOrderId of validatedBody.work_order_ids) {
      const { data: wo } = await supabase
        .from("lab_work_orders")
        .select("id, field_operation_id, status, pos_order_id")
        .eq("id", workOrderId)
        .single();

      if (!wo || wo.field_operation_id !== fieldOperationId) {
        failed.push({
          id: workOrderId,
          error: "Trabajo no encontrado o no pertenece a este operativo",
        });
        continue;
      }

      if (wo.status === "delivered") {
        failed.push({ id: workOrderId, error: "Trabajo ya entregado" });
        continue;
      }

      if (wo.pos_order_id) {
        const { data: balance } = await supabase.rpc(
          "calculate_order_balance",
          { p_order_id: wo.pos_order_id },
        );
        if ((balance ?? 0) > 0) {
          failed.push({
            id: workOrderId,
            error: `Saldo pendiente: $${(balance as number).toLocaleString("es-CL")}`,
          });
          continue;
        }
      }

      const { error: statusError } = await supabase.rpc(
        "update_work_order_status",
        {
          p_work_order_id: workOrderId,
          p_new_status: "delivered",
          p_changed_by: user.id,
          p_notes: `Entrega en empresa: ${validatedBody.recipient_name}. ${validatedBody.notes || ""}`,
        },
      );

      if (statusError) {
        failed.push({
          id: workOrderId,
          error: statusError.message,
        });
        continue;
      }

      await supabase
        .from("lab_work_orders")
        .update({
          operativo_delivered_at: deliveredAt,
          operativo_recipient_name: validatedBody.recipient_name,
          updated_at: new Date().toISOString(),
        })
        .eq("id", workOrderId);

      updated.push(workOrderId);
    }

    // Send delivery completion email with survey link for each delivered work order (non-blocking)
    for (const workOrderId of updated) {
      (async () => {
        try {
          const { data: wo } = await supabase
            .from("lab_work_orders")
            .select(
              `
              id,
              organization_id,
              branch_id,
              work_order_number,
              customer_id,
              customer:customers!lab_work_orders_customer_id_fkey(id, first_name, last_name, email)
            `,
            )
            .eq("id", workOrderId)
            .single();

          if (!wo || !wo.customer) return;

          let orgId = (wo as { organization_id?: string }).organization_id;
          if (!orgId && wo.branch_id) {
            const { data: branch } = await supabase
              .from("branches")
              .select("organization_id")
              .eq("id", wo.branch_id)
              .single();
            orgId = branch?.organization_id ?? undefined;
          }

          const customer = wo.customer as {
            first_name?: string;
            last_name?: string;
            email?: string;
          };
          const customerEmail = customer?.email;
          if (!orgId || !customerEmail) return;

          const customerName =
            `${customer?.first_name || ""} ${customer?.last_name || ""}`.trim() ||
            customer?.email ||
            "Cliente";

          await sendDeliveryCompletionEmail({
            workOrderId,
            organizationId: orgId,
            customerId: wo.customer_id ?? null,
            customerEmail,
            customerName,
            workOrderNumber: wo.work_order_number || "",
          });
        } catch (err) {
          logger.warn(
            "Error sending delivery completion email for field operation",
            {
              workOrderId,
              error: err,
            },
          );
        }
      })();
    }

    return createApiSuccessResponse(
      {
        updated,
        failed,
        deliveredAt,
        recipientName: validatedBody.recipient_name,
      },
      { requestId },
    );
  } catch (error) {
    logger.error("Error in field-operations deliver API", { error, requestId });
    return createApiErrorResponse(
      error instanceof Error ? error : new Error("Internal server error"),
      { requestId },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import {
  getBranchContext,
  validateBranchAccess,
} from "@/lib/api/branch-middleware";
import { AuthenticationError, AuthorizationError , ValidationError } from "@/lib/api/errors";
import {
  createApiErrorResponse,
  createApiSuccessResponse,
} from "@/lib/api/response";
import {
  validateBody,
  validationErrorResponse,
} from "@/lib/api/validation/zod-helpers";
import {
  returnStockBulkSchema,
  returnStockSchema,
} from "@/lib/api/validation/zod-schemas";
import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const requestId = crypto.randomUUID();

  try {
    const supabase = await createClient();
    const supabaseServiceRole = createServiceRoleClient();

    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      throw new AuthenticationError("Unauthorized");
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      throw new AuthorizationError("Admin access required");
    }

    const { id: fieldOperationId } = await params;

    const { data: operation, error: opError } = await supabaseServiceRole
      .from("field_operations")
      .select("id, branch_id, organization_id, status")
      .eq("id", fieldOperationId)
      .single();

    if (opError || !operation) {
      return NextResponse.json(
        { error: "Operativo no encontrado" },
        { status: 404 },
      );
    }

    let hasAccess = await validateBranchAccess(user.id, operation.branch_id);
    if (!hasAccess) {
      const branchContext = await getBranchContext(request, user.id);
      if (
        branchContext.isSuperAdmin &&
        branchContext.organizationId &&
        operation.organization_id === branchContext.organizationId
      ) {
        hasAccess = true;
      }
    }
    if (!hasAccess) {
      return NextResponse.json(
        { error: "No tiene acceso a este operativo" },
        { status: 403 },
      );
    }

    let items: { product_id: string; quantity: number }[];
    try {
      const body = (await request.json()) as unknown;
      if (
        body &&
        typeof body === "object" &&
        "items" in body &&
        Array.isArray((body as { items: unknown }).items)
      ) {
        const validated = validateBody(body, returnStockBulkSchema);
        items = validated.items;
      } else {
        const validated = validateBody(body, returnStockSchema);
        items = [
          { product_id: validated.product_id, quantity: validated.quantity },
        ];
      }
    } catch (err) {
      if (err instanceof ValidationError) {
        return validationErrorResponse(err);
      }
      if (err && typeof err === "object" && "errors" in err) {
        return validationErrorResponse(err as unknown as ValidationError);
      }
      throw err;
    }

    const branchId = operation.branch_id;
    const results: {
      product_id: string;
      quantity: number;
      success: boolean;
      error?: string;
    }[] = [];

    for (const item of items) {
      try {
        const { data: mobileStock } = await supabaseServiceRole
          .from("operativo_mobile_stock")
          .select("id, quantity")
          .eq("field_operation_id", fieldOperationId)
          .eq("product_id", item.product_id)
          .single();

        if (!mobileStock || mobileStock.quantity < item.quantity) {
          results.push({
            product_id: item.product_id,
            quantity: item.quantity,
            success: false,
            error: "Stock insuficiente en bodega móvil",
          });
          continue;
        }

        const { error: stockError } = await supabaseServiceRole.rpc(
          "update_product_stock",
          {
            p_product_id: item.product_id,
            p_branch_id: branchId,
            p_quantity_change: item.quantity,
            p_reserve: false,
            p_movement_type: "receipt",
            p_reference_type: "field_operation_return",
            p_reference_id: fieldOperationId,
            p_created_by: user.id,
          },
        );

        if (stockError) {
          results.push({
            product_id: item.product_id,
            quantity: item.quantity,
            success: false,
            error: stockError.message,
          });
          continue;
        }

        const newQuantity = mobileStock.quantity - item.quantity;
        if (newQuantity <= 0) {
          await supabaseServiceRole
            .from("operativo_mobile_stock")
            .delete()
            .eq("id", mobileStock.id);
        } else {
          await supabaseServiceRole
            .from("operativo_mobile_stock")
            .update({
              quantity: newQuantity,
              updated_at: new Date().toISOString(),
            })
            .eq("id", mobileStock.id);
        }

        results.push({
          product_id: item.product_id,
          quantity: item.quantity,
          success: true,
        });
      } catch (err) {
        results.push({
          product_id: item.product_id,
          quantity: item.quantity,
          success: false,
          error: err instanceof Error ? err.message : "Error desconocido",
        });
      }
    }

    const { data: remainingStock } = await supabaseServiceRole
      .from("operativo_mobile_stock")
      .select("id")
      .eq("field_operation_id", fieldOperationId);

    const allReturned = !remainingStock || remainingStock.length === 0;
    if (allReturned && results.some((r) => r.success)) {
      await supabaseServiceRole
        .from("field_operations")
        .update({
          status: "completed",
          updated_at: new Date().toISOString(),
        })
        .eq("id", fieldOperationId);
    }

    const successCount = results.filter((r) => r.success).length;
    const failCount = results.filter((r) => !r.success).length;

    return createApiSuccessResponse(
      {
        results,
        successCount,
        failCount,
        statusUpdated: allReturned && successCount > 0,
      },
      { requestId },
    );
  } catch (error) {
    logger.error("Error in return-stock API", { error, requestId });
    return createApiErrorResponse(
      error instanceof Error ? error : new Error("Internal server error"),
      { requestId },
    );
  }
}

