export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const requestId = crypto.randomUUID();

  try {
    const supabase = await createClient();

    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      throw new AuthenticationError("Unauthorized");
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      throw new AuthorizationError("Admin access required");
    }

    const { id } = await params;

    const { data: existing } = await supabase
      .from("field_operations")
      .select("id, branch_id, organization_id")
      .eq("id", id)
      .single();

    if (!existing) {
      return NextResponse.json(
        { error: "Operativo no encontrado" },
        { status: 404 },
      );
    }

    let hasAccess = await validateBranchAccess(user.id, existing.branch_id);
    if (!hasAccess) {
      const branchContext = await getBranchContext(request, user.id);
      if (
        branchContext.isSuperAdmin &&
        branchContext.organizationId &&
        existing.organization_id === branchContext.organizationId
      ) {
        hasAccess = true;
      }
    }
    if (!hasAccess) {
      return NextResponse.json(
        { error: "No tiene acceso a este operativo" },
        { status: 403 },
      );
    }

    let validatedBody;
    try {
      validatedBody = await parseAndValidateBody(
        request,
        updateFieldOperationSchema,
      );
    } catch (error) {
      if (error instanceof ValidationError) {
        return validationErrorResponse(error);
      }
      throw error;
    }

    // Auto-return remaining mobile stock when status changes to completed
    if (validatedBody.status === "completed") {
      const { data: mobileStockRows } = await supabase
        .from("operativo_mobile_stock")
        .select("id, product_id, quantity")
        .eq("field_operation_id", id);

      if (mobileStockRows && mobileStockRows.length > 0) {
        const branchId = existing.branch_id;
        for (const row of mobileStockRows) {
          const qty = row.quantity ?? 0;
          if (qty <= 0) continue;
          const { error: stockError } = await supabase.rpc(
            "update_product_stock",
            {
              p_product_id: row.product_id,
              p_branch_id: branchId,
              p_quantity_change: qty,
              p_reserve: false,
              p_movement_type: "receipt",
              p_reference_type: "field_operation_return",
              p_reference_id: id,
              p_created_by: user.id,
            },
          );
          if (stockError) {
            logger.warn("Auto-return stock failed for product", {
              product_id: row.product_id,
              error: stockError.message,
              requestId,
            });
          } else {
            await supabase
              .from("operativo_mobile_stock")
              .delete()
              .eq("id", row.id);
          }
        }
      }
    }

    const updateData: Record<string, unknown> = {
      updated_at: new Date().toISOString(),
    };

    if (validatedBody.name !== undefined) updateData.name = validatedBody.name;
    if (validatedBody.location !== undefined)
      updateData.location = validatedBody.location;
    if (validatedBody.status !== undefined)
      updateData.status = validatedBody.status;
    if (validatedBody.scheduled_date !== undefined) {
      updateData.scheduled_date =
        validatedBody.scheduled_date instanceof Date
          ? validatedBody.scheduled_date.toISOString().slice(0, 10)
          : new Date(validatedBody.scheduled_date).toISOString().slice(0, 10);
    }

    const { data: updated, error: updateError } = await supabase
      .from("field_operations")
      .update(updateData)
      .eq("id", id)
      .select()
      .single();

    if (updateError) {
      logger.error("Error updating field operation", {
        updateError,
        requestId,
      });
      return NextResponse.json(
        {
          error: "Error al actualizar operativo",
          details: updateError.message,
        },
        { status: 500 },
      );
    }

    return createApiSuccessResponse({ fieldOperation: updated }, { requestId });
  } catch (error) {
    logger.error("Error in field operations API PUT [id]", {
      error,
      requestId,
    });
    return createApiErrorResponse(
      error instanceof Error ? error : new Error("Internal server error"),
      { requestId },
    );
  }
}

