          logger.warn("Stock transfer failed for product", {
            product_id: item.product_id,
            error: stockError.message,
            requestId,
          });
          results.push({
            product_id: item.product_id,
            quantity: item.quantity,
            success: false,
            error: stockError.message,
          });
          continue;
        }

        const { data: existing } = await supabaseServiceRole
          .from("operativo_mobile_stock")
          .select("id, quantity")
          .eq("field_operation_id", fieldOperationId)
          .eq("product_id", item.product_id)
          .single();

        if (existing) {
          await supabaseServiceRole
            .from("operativo_mobile_stock")
            .update({
              quantity: existing.quantity + item.quantity,
              updated_at: new Date().toISOString(),
            })
            .eq("id", existing.id);
        } else {
          await supabaseServiceRole.from("operativo_mobile_stock").insert({
            field_operation_id: fieldOperationId,
            product_id: item.product_id,
            quantity: item.quantity,
            reserved_quantity: 0,
          });
        }

        results.push({
          product_id: item.product_id,
          quantity: item.quantity,
          success: true,
        });
      } catch (err) {
        results.push({
          product_id: item.product_id,
          quantity: item.quantity,
          success: false,
          error: err instanceof Error ? err.message : "Error desconocido",
        });
      }
    }

    if (operation.status === "draft" && results.some((r) => r.success)) {
      await supabaseServiceRole
        .from("field_operations")
        .update({
          status: "prepared",
          updated_at: new Date().toISOString(),
        })
        .eq("id", fieldOperationId);
    }

    const successCount = results.filter((r) => r.success).length;
    const failCount = results.filter((r) => !r.success).length;

    return createApiSuccessResponse(
      {
        results,
        successCount,
        failCount,
        statusUpdated: operation.status === "draft" && successCount > 0,
      },
      { requestId },
    );
  } catch (error) {
    if (error instanceof ValidationError) {
      return validationErrorResponse(error);
    }
    logger.error("Error in transfer-stock API", { error, requestId });
    return createApiErrorResponse(
      error instanceof Error ? error : new Error("Internal server error"),
      { requestId },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import {
  getBranchContext,
  validateBranchAccess,
} from "@/lib/api/branch-middleware";
import { AuthenticationError, AuthorizationError } from "@/lib/api/errors";
import {
  createApiErrorResponse,
  createPaginatedResponse,
} from "@/lib/api/response";
import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const requestId = crypto.randomUUID();

  try {
    const supabase = await createClient();
    const supabaseServiceRole = createServiceRoleClient();

    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      throw new AuthenticationError("Unauthorized");
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      throw new AuthorizationError("Admin access required");
    }

    const { id: fieldOperationId } = await params;

    const { data: operation, error: opError } = await supabaseServiceRole
      .from("field_operations")
      .select("id, branch_id, organization_id")
      .eq("id", fieldOperationId)
      .single();

    if (opError || !operation) {
      return NextResponse.json(
        { error: "Operativo no encontrado" },
        { status: 404 },
      );
    }

    let hasAccess = await validateBranchAccess(user.id, operation.branch_id);
    if (!hasAccess) {
      const branchContext = await getBranchContext(request, user.id);
      if (
        branchContext.isSuperAdmin &&
        branchContext.organizationId &&
        operation.organization_id === branchContext.organizationId
      ) {
        hasAccess = true;
      }
    }
    if (!hasAccess) {
      return NextResponse.json(
        { error: "No tiene acceso a este operativo" },
        { status: 403 },
      );
    }

    const searchParams = request.nextUrl.searchParams;
    const status = searchParams.get("status") || "all";
    const page = parseInt(searchParams.get("page") || "1");
    const limit = parseInt(searchParams.get("limit") || "20");

    let query = supabaseServiceRole
      .from("lab_work_orders")
      .select(
        `
        *,
        customer:customers!lab_work_orders_customer_id_fkey(id, first_name, last_name, email, phone),
        prescription:prescriptions!lab_work_orders_prescription_id_fkey(id)
      `,
        { count: "exact" },
      )
      .eq("field_operation_id", fieldOperationId)
      .order("created_at", { ascending: false });

    if (status !== "all") {
      query = query.eq("status", status);
    }

    const from = (page - 1) * limit;
    const to = from + limit - 1;

    const { data: workOrders, error, count } = await query.range(from, to);

    if (error) {
      logger.error("Error fetching work orders for field operation", {
        error,
        fieldOperationId,
        requestId,
      });
      throw new Error(`Failed to fetch work orders: ${error.message}`);
    }

    return createPaginatedResponse(
      workOrders || [],
      { page, limit, total: count || 0 },
      { requestId },
    );
  } catch (error) {
    logger.error("Error in field-operations work-orders API GET", {
      error,
      requestId,
    });
    return createApiErrorResponse(
      error instanceof Error ? error : new Error("Internal server error"),
      { requestId },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { addBranchFilter, getBranchContext } from "@/lib/api/branch-middleware";
import { AuthenticationError, AuthorizationError , ValidationError } from "@/lib/api/errors";
import {
  createApiErrorResponse,
  createApiSuccessResponse,
  createPaginatedResponse,
} from "@/lib/api/response";
import {
  parseAndValidateBody,
  validationErrorResponse,
} from "@/lib/api/validation/zod-helpers";
import { createFieldOperationSchema } from "@/lib/api/validation/zod-schemas";
import { appLogger as logger } from "@/lib/logger";
import { validateFeature } from "@/lib/saas/tier-validator";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";

export async function GET(request: NextRequest) {
  const requestId = crypto.randomUUID();

  try {
    const supabase = await createClient();

    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      throw new AuthenticationError("Unauthorized");
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      throw new AuthorizationError("Admin access required");
    }

    const branchContext = await getBranchContext(request, user.id);
    const { data: adminUser } = await supabase
      .from("admin_users")
      .select("organization_id")
      .eq("id", user.id)
      .single();
    const orgId = branchContext.organizationId ?? adminUser?.organization_id;
    if (orgId) {
      const hasFieldOps = await validateFeature(orgId, "field_operations");
      if (!hasFieldOps) {
        return NextResponse.json(
          {
            error:
              "Operativos en Terreno requiere el plan Óptica Avanzada. Upgrade para habilitar.",
          },
          { status: 403 },
        );
      }
    }

    const searchParams = request.nextUrl.searchParams;
    const status = searchParams.get("status") || "all";
    const page = parseInt(searchParams.get("page") || "1");
    const limit = parseInt(searchParams.get("limit") || "20");

    let query = supabase
      .from("field_operations")
      .select("*", { count: "exact" })
      .order("scheduled_date", { ascending: false });

    query = addBranchFilter(
      query,
      branchContext.branchId,
      branchContext.isSuperAdmin,
      branchContext.organizationId,
    );

    if (status !== "all") {
      query = query.eq("status", status);
    }

    const from = (page - 1) * limit;
    const to = from + limit - 1;

    const { data: operations, error, count } = await query.range(from, to);

    if (error) {
      logger.error("Error fetching field operations", { error, requestId });
      throw new Error(`Failed to fetch field operations: ${error.message}`);
    }

    return createPaginatedResponse(
      operations || [],
      { page, limit, total: count || 0 },
      { requestId },
    );
  } catch (error) {
    logger.error("Error in field operations API GET", { error, requestId });
    return createApiErrorResponse(
      error instanceof Error ? error : new Error("Internal server error"),
      { requestId },
    );
  }
}

export async function POST(request: NextRequest) {
  const requestId = crypto.randomUUID();

  try {
    const supabase = await createClient();

    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      throw new AuthenticationError("Unauthorized");
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      throw new AuthorizationError("Admin access required");
    }

    let validatedBody;
    try {
      validatedBody = await parseAndValidateBody(
        request,
        createFieldOperationSchema,
      );
    } catch (error) {
      if (error instanceof ValidationError) {
        return validationErrorResponse(error);
      }
      throw error;
    }

    const branchContext = await getBranchContext(request, user.id);

    if (!branchContext.isSuperAdmin && !branchContext.branchId) {
      return NextResponse.json(
        { error: "Debe seleccionar una sucursal para crear operativos" },
        { status: 400 },
      );
    }

    const branchId = validatedBody.branch_id || branchContext.branchId;
    if (!branchId) {
      return NextResponse.json(
        { error: "branch_id es requerido" },
        { status: 400 },
      );
    }

    const { data: branch } = await supabase
      .from("branches")
      .select("organization_id")
      .eq("id", branchId)
      .single();

    if (!branch?.organization_id) {
      return NextResponse.json(
        { error: "Sucursal no encontrada o sin organización" },
        { status: 400 },
      );
    }

    const hasFieldOps = await validateFeature(
      branch.organization_id,
      "field_operations",
    );
    if (!hasFieldOps) {
      return NextResponse.json(
        {
          error:
            "Operativos en Terreno requiere el plan Óptica Avanzada. Upgrade para habilitar.",
        },
        { status: 403 },
      );
    }

    const scheduledDate =
      validatedBody.scheduled_date instanceof Date
        ? validatedBody.scheduled_date.toISOString().slice(0, 10)
        : new Date(validatedBody.scheduled_date).toISOString().slice(0, 10);

    const { data: newOperation, error: insertError } = await supabase
      .from("field_operations")
      .insert({
        name: validatedBody.name,
        scheduled_date: scheduledDate,
        location: validatedBody.location ?? null,
        branch_id: branchId,
        organization_id: branch.organization_id,
        status: "prepared",
        created_by: user.id,
      })
      .select()
      .single();

    if (insertError) {
      logger.error("Error creating field operation", {
        insertError,
        requestId,
      });
      return NextResponse.json(
        {
          error: "Error al crear operativo",
          details: insertError.message,
        },
        { status: 500 },
      );
    }

    logger.info("Field operation created", {
      id: newOperation.id,
      name: newOperation.name,
      requestId,
    });

    return createApiSuccessResponse(
      { fieldOperation: newOperation },
      { requestId },
    );
  } catch (error) {
    logger.error("Error in field operations API POST", { error, requestId });
    return createApiErrorResponse(
      error instanceof Error ? error : new Error("Internal server error"),
      { requestId },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import { createClient } from "@/utils/supabase/server";

interface RouteParams {
  params: Promise<{ id: string }>;
}

// GET /api/admin/internal-orders/[id] - Get specific internal order
export const dynamic = "force-dynamic";
export async function GET(req: NextRequest, { params }: RouteParams) {
  try {
    const supabase = await createClient();
    const { id } = await params;

    // Get user
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user)
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

    // Get branch context
    const branchContext = await getBranchContext(req, user.id, supabase);
    if (!branchContext.branchId && !branchContext.isGlobalView) {
      return NextResponse.json({ error: "No branch access" }, { status: 403 });
    }

    // Fetch order with all relations
    const { data: order, error } = await supabase
      .from("internal_orders")
      .select(
        `
        *,
        origin_branch:branches!internal_orders_origin_branch_id_fkey(name, code, address_line_1, phone),
        destination_branch:branches!internal_orders_destination_branch_id_fkey(name, code, address_line_1, phone),
        created_by_user:admin_users!internal_orders_created_by_fkey(first_name, last_name, email),
        assigned_driver:drivers(name, license_number, phone, email),
        assigned_vehicle:vehicles(plate_number, model, capacity),
        items:internal_order_items(
          *,
          product:products(name, sku, description)
        ),
        status_history:internal_order_status_history(
          *,
          changed_by_user:admin_users!internal_order_status_history_changed_by_fkey(first_name, last_name)
        )
      `,
      )
      .eq("id", id)
      .eq("organization_id", branchContext.organizationId)
      .single();

    if (error) {
      if (error.code === "PGRST116") {
        return NextResponse.json(
          { error: "Internal order not found" },
          { status: 404 },
        );
      }
      logger.error("Failed to fetch internal order", { error: error.message });
      return NextResponse.json(
        { error: "Failed to fetch internal order" },
        { status: 500 },
      );
    }

    // Check branch access
    if (!branchContext.isSuperAdmin) {
      const userBranches = await supabase
        .from("admin_branch_access")
        .select("branch_id")
        .eq("admin_user_id", user.id);

      const accessibleBranchIds =
        userBranches.data?.map((b: unknown) => b.branch_id) || [];

      if (
        !accessibleBranchIds.includes(order.origin_branch_id) &&
        !accessibleBranchIds.includes(order.destination_branch_id)
      ) {
        return NextResponse.json({ error: "Access denied" }, { status: 403 });
      }
    }

    return NextResponse.json(order);
  } catch (error) {
    logger.error("Internal order detail error", { error });
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

// PUT /api/admin/internal-orders/[id] - Update internal order
export async function PUT(req: NextRequest, { params }: RouteParams) {
  try {
    const supabase = await createClient();
    const { id } = await params;

    // Get user
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user)
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

    // Get branch context
    const branchContext = await getBranchContext(req, user.id, supabase);
    if (!branchContext.branchId && !branchContext.isGlobalView) {
      return NextResponse.json({ error: "No branch access" }, { status: 403 });
    }

    const body = await req.json();
    const {
      priority,
      scheduled_date,
      notes,
      assigned_driver_id,
      assigned_vehicle_id,
      items, // Only for adding new items, not updating existing ones
    } = body;

    // Fetch existing order to check access
    const { data: existingOrder, error: fetchError } = await supabase
      .from("internal_orders")
      .select("origin_branch_id, destination_branch_id, status")
      .eq("id", id)
      .eq("organization_id", branchContext.organizationId)
      .single();

    if (fetchError) {
      if (fetchError.code === "PGRST116") {
        return NextResponse.json(
          { error: "Internal order not found" },
          { status: 404 },
        );
      }
      logger.error("Failed to fetch internal order for update", {
        error: fetchError.message,
      });
      return NextResponse.json(
        { error: "Failed to fetch internal order" },
        { status: 500 },
      );
    }

    // Check branch access
    if (!branchContext.isSuperAdmin) {
      const userBranches = await supabase
        .from("admin_branch_access")
        .select("branch_id")
        .eq("admin_user_id", user.id);

      const accessibleBranchIds =
        userBranches.data?.map((b: unknown) => b.branch_id) || [];

      if (
        !accessibleBranchIds.includes(existingOrder.origin_branch_id) &&
        !accessibleBranchIds.includes(existingOrder.destination_branch_id)
      ) {
        return NextResponse.json({ error: "Access denied" }, { status: 403 });
      }
    }

    // Prevent updates to delivered/cancelled orders
    if (
      existingOrder.status === "delivered" ||
      existingOrder.status === "cancelled"
    ) {
      return NextResponse.json(
        { error: "Cannot update delivered or cancelled orders" },
        { status: 400 },
      );
    }

    // Prepare update data
    const updateData: unknown = {};

    if (priority !== undefined) updateData.priority = priority;
    if (scheduled_date !== undefined)
      updateData.scheduled_date = scheduled_date;
    if (notes !== undefined) updateData.notes = notes;
    if (assigned_driver_id !== undefined)
      updateData.assigned_driver_id = assigned_driver_id;
    if (assigned_vehicle_id !== undefined)
      updateData.assigned_vehicle_id = assigned_vehicle_id;

    // Update order
    const { data: updatedOrder, error: updateError } = await supabase
      .from("internal_orders")
      .update(updateData)
      .eq("id", id)
      .eq("organization_id", branchContext.organizationId)
      .select()
      .single();

    if (updateError) {
      logger.error("Failed to update internal order", {
        error: updateError.message,
      });
      return NextResponse.json(
        { error: "Failed to update internal order" },
        { status: 500 },
      );
    }

    // Add new items if provided
    if (items && Array.isArray(items) && items.length > 0) {
      const orderItems = items.map((item: unknown) => ({
        internal_order_id: id,
        product_id: item.product_id,
        quantity: item.quantity,
        notes: item.notes,
      }));

      const { error: itemsError } = await supabase
        .from("internal_order_items")
        .insert(orderItems);

      if (itemsError) {
        logger.error("Failed to add order items", {
          error: itemsError.message,
        });
        // Note: We don't rollback the order update as it was successful
        return NextResponse.json(
          { error: "Order updated but failed to add items" },
          { status: 500 },
        );
      }
    }

    // Fetch complete updated order
    const { data: completeOrder } = await supabase
      .from("internal_orders")
      .select(
        `
        *,
        origin_branch:branches!internal_orders_origin_branch_id_fkey(name, code),
        destination_branch:branches!internal_orders_destination_branch_id_fkey(name, code),
        created_by_user:admin_users!internal_orders_created_by_fkey(first_name, last_name),
        assigned_driver:drivers(name, license_number),
        assigned_vehicle:vehicles(plate_number, model),
        items:internal_order_items(
          *,
          product:products(name, sku)
        )
      `,
      )
      .eq("id", id)
      .single();

    logger.info("Internal order updated", {
      orderId: id,
      userId: user.id,
    });

    return NextResponse.json(completeOrder);
  } catch (error) {
    logger.error("Internal order update error", { error });
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

// DELETE /api/admin/internal-orders/[id] - Delete internal order
export async function DELETE(req: NextRequest, { params }: RouteParams) {
  try {
    const supabase = await createClient();
    const { id } = await params;

    // Get user
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user)
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

    // Get branch context
    const branchContext = await getBranchContext(req, user.id, supabase);
    if (!branchContext.branchId && !branchContext.isGlobalView) {
      return NextResponse.json({ error: "No branch access" }, { status: 403 });
    }

    // Fetch existing order to check access and status
    const { data: existingOrder, error: fetchError } = await supabase
      .from("internal_orders")
      .select("origin_branch_id, destination_branch_id, status")
      .eq("id", id)
      .eq("organization_id", branchContext.organizationId)
      .single();

    if (fetchError) {
      if (fetchError.code === "PGRST116") {
        return NextResponse.json(
          { error: "Internal order not found" },
          { status: 404 },
        );
      }
      logger.error("Failed to fetch internal order for deletion", {
        error: fetchError.message,
      });
      return NextResponse.json(
        { error: "Failed to fetch internal order" },
        { status: 500 },
      );
    }

    // Check branch access
    if (!branchContext.isSuperAdmin) {
      const userBranches = await supabase
        .from("admin_branch_access")
        .select("branch_id")
        .eq("admin_user_id", user.id);

      const accessibleBranchIds =
        userBranches.data?.map((b: unknown) => b.branch_id) || [];

      if (
        !accessibleBranchIds.includes(existingOrder.origin_branch_id) &&
        !accessibleBranchIds.includes(existingOrder.destination_branch_id)
      ) {
        return NextResponse.json({ error: "Access denied" }, { status: 403 });
      }
    }

    // Only allow deletion of pending orders
    if (existingOrder.status !== "pending") {
      return NextResponse.json(
        { error: "Only pending orders can be deleted" },
        { status: 400 },
      );
    }

    // Delete order (cascades to items and status history)
    const { error: deleteError } = await supabase
      .from("internal_orders")
      .delete()
      .eq("id", id)
      .eq("organization_id", branchContext.organizationId);

    if (deleteError) {
      logger.error("Failed to delete internal order", {
        error: deleteError.message,
      });
      return NextResponse.json(
        { error: "Failed to delete internal order" },
        { status: 500 },
      );
    }

    logger.info("Internal order deleted", {
      orderId: id,
      userId: user.id,
    });

    return NextResponse.json({ message: "Order deleted successfully" });
  } catch (error) {
    logger.error("Internal order deletion error", { error });
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import { createClient } from "@/utils/supabase/server";

interface RouteParams {
  params: Promise<{ id: string }>;
}

// PATCH /api/admin/internal-orders/[id]/status - Update order status
export const dynamic = "force-dynamic";
export async function PATCH(req: NextRequest, { params }: RouteParams) {
  try {
    const supabase = await createClient();
    const { id } = await params;

    // Get user
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user)
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

    // Get branch context
    const branchContext = await getBranchContext(req, user.id, supabase);
    if (!branchContext.branchId && !branchContext.isGlobalView) {
      return NextResponse.json({ error: "No branch access" }, { status: 403 });
    }

    const body = await req.json();
    const { status, notes } = body;

    // Validation
    if (!status) {
      return NextResponse.json(
        { error: "Status is required" },
        { status: 400 },
      );
    }

    const validStatuses = [
      "pending",
      "confirmed",
      "in_transit",
      "delivered",
      "cancelled",
    ];
    if (!validStatuses.includes(status)) {
      return NextResponse.json(
        {
          error: `Invalid status. Must be one of: ${validStatuses.join(", ")}`,
        },
        { status: 400 },
      );
    }

    // Fetch existing order
    const { data: existingOrder, error: fetchError } = await supabase
      .from("internal_orders")
      .select("origin_branch_id, destination_branch_id, status")
      .eq("id", id)
      .eq("organization_id", branchContext.organizationId)
      .single();

    if (fetchError) {
      if (fetchError.code === "PGRST116") {
        return NextResponse.json(
          { error: "Internal order not found" },
          { status: 404 },
        );
      }
      logger.error("Failed to fetch internal order for status update", {
        error: fetchError.message,
      });
      return NextResponse.json(
        { error: "Failed to fetch internal order" },
        { status: 500 },
      );
    }

    // Check branch access
    if (!branchContext.isSuperAdmin) {
      const userBranches = await supabase
        .from("admin_branch_access")
        .select("branch_id")
        .eq("admin_user_id", user.id);

      const accessibleBranchIds =
        userBranches.data?.map((b: unknown) => b.branch_id) || [];

      if (
        !accessibleBranchIds.includes(existingOrder.origin_branch_id) &&
        !accessibleBranchIds.includes(existingOrder.destination_branch_id)
      ) {
        return NextResponse.json({ error: "Access denied" }, { status: 403 });
      }
    }

    // Validate status transitions
    const currentStatus = existingOrder.status;
    const validTransitions: Record<string, string[]> = {
      pending: ["confirmed", "cancelled"],
      confirmed: ["in_transit", "cancelled"],
      in_transit: ["delivered", "cancelled"],
      delivered: [],
      cancelled: [],
    };

    if (currentStatus !== "pending" && status === "pending") {
      return NextResponse.json(
        { error: "Cannot revert to pending status" },
        { status: 400 },
      );
    }

    if (!validTransitions[currentStatus].includes(status)) {
      return NextResponse.json(
        {
          error: `Invalid status transition from ${currentStatus} to ${status}`,
        },
        { status: 400 },
      );
    }

    // Update status
    const updateData: unknown = { status };

    // Set delivery date if transitioning to delivered
    if (status === "delivered") {
      updateData.actual_delivery_date = new Date().toISOString();
    }

    const { data: updatedOrder, error: updateError } = await supabase
      .from("internal_orders")
      .update(updateData)
      .eq("id", id)
      .eq("organization_id", branchContext.organizationId)
      .select()
      .single();

    if (updateError) {
      logger.error("Failed to update order status", {
        error: updateError.message,
      });
      return NextResponse.json(
        { error: "Failed to update order status" },
        { status: 500 },
      );
    }

    // The status history is automatically logged by the database trigger

    logger.info("Internal order status updated", {
      orderId: id,
      fromStatus: currentStatus,
      toStatus: status,
      userId: user.id,
    });

    // Fetch complete updated order
    const { data: completeOrder } = await supabase
      .from("internal_orders")
      .select(
        `
        *,
        origin_branch:branches!internal_orders_origin_branch_id_fkey(name, code),
        destination_branch:branches!internal_orders_destination_branch_id_fkey(name, code),
        created_by_user:admin_users!internal_orders_created_by_fkey(first_name, last_name),
        assigned_driver:drivers(name, license_number),
        assigned_vehicle:vehicles(plate_number, model)
      `,
      )
      .eq("id", id)
      .single();

    return NextResponse.json(completeOrder);
  } catch (error) {
    logger.error("Order status update error", { error });
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import { createClient } from "@/utils/supabase/server";

// GET /api/admin/internal-orders - List internal orders
export const dynamic = "force-dynamic";
export async function GET(req: NextRequest) {
  try {
    const supabase = await createClient();

    // Get user
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user)
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

    // Get branch context
    const branchContext = await getBranchContext(req, user.id, supabase);
    if (!branchContext.branchId && !branchContext.isGlobalView) {
      return NextResponse.json({ error: "No branch access" }, { status: 403 });
    }

    const { searchParams } = new URL(req.url);
    const page = parseInt(searchParams.get("page") || "1");
    const limit = parseInt(searchParams.get("limit") || "20");
    const status = searchParams.get("status");
    const priority = searchParams.get("priority");
    const originBranch = searchParams.get("origin_branch_id");
    const destinationBranch = searchParams.get("destination_branch_id");

    const offset = (page - 1) * limit;

    // Build query
    let query = supabase
      .from("internal_orders")
      .select(
        `
        *,
        origin_branch:branches!internal_orders_origin_branch_id_fkey(name, code),
        destination_branch:branches!internal_orders_destination_branch_id_fkey(name, code),
        created_by_user:admin_users!internal_orders_created_by_fkey(first_name, last_name),
        assigned_driver:drivers(name, license_number),
        assigned_vehicle:vehicles(plate_number, model),
        items:internal_order_items(
          *,
          product:products(name, sku)
        )
      `,
        { count: "exact" },
      )
      .eq("organization_id", branchContext.organizationId);

    // Apply filters
    if (status) {
      query = query.eq("status", status);
    }

    if (priority) {
      query = query.eq("priority", priority);
    }

    if (originBranch) {
      query = query.eq("origin_branch_id", originBranch);
    }

    if (destinationBranch) {
      query = query.eq("destination_branch_id", destinationBranch);
    }

    // Apply branch context filter (orders involving user's branch)
    if (!branchContext.isSuperAdmin) {
      query = query.or(
        `origin_branch_id.eq.${branchContext.branchId},destination_branch_id.eq.${branchContext.branchId}`,
      );
    }

    // Execute query with pagination
    const {
      data: orders,
      error,
      count,
    } = await query
      .order("created_at", { ascending: false })
      .range(offset, offset + limit - 1);

    if (error) {
      logger.error("Failed to fetch internal orders", { error: error.message });
      return NextResponse.json(
        { error: "Failed to fetch internal orders" },
        { status: 500 },
      );
    }

    return NextResponse.json({
      orders,
      pagination: {
        page,
        limit,
        total: count,
        totalPages: Math.ceil(count! / limit),
      },
    });
  } catch (error) {
    logger.error("Internal orders list error", { error });
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

// POST /api/admin/internal-orders - Create new internal order
export async function POST(req: NextRequest) {
  try {
    const supabase = await createClient();

    // Get user
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user)
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

    // Get branch context
    const branchContext = await getBranchContext(req, user.id, supabase);
    if (!branchContext.branchId && !branchContext.isGlobalView) {
      return NextResponse.json({ error: "No branch access" }, { status: 403 });
    }

    const body = await req.json();
    const {
      origin_branch_id,
      destination_branch_id,
      priority = "medium",
      scheduled_date,
      notes,
      items,
    } = body;

    // Validation
    if (!origin_branch_id || !destination_branch_id) {
      return NextResponse.json(
        { error: "Origin and destination branches are required" },
        { status: 400 },
      );
    }

    if (origin_branch_id === destination_branch_id) {
      return NextResponse.json(
        { error: "Origin and destination branches must be different" },
        { status: 400 },
      );
    }

    if (!items || !Array.isArray(items) || items.length === 0) {
      return NextResponse.json(
        { error: "At least one item is required" },
        { status: 400 },
      );
    }

    // Verify branch access
    if (!branchContext.isSuperAdmin) {
      const userBranches = await supabase
        .from("admin_branch_access")
        .select("branch_id")
        .eq("admin_user_id", user.id);

      const accessibleBranchIds =
        userBranches.data?.map((b: unknown) => b.branch_id) || [];

      if (
        !accessibleBranchIds.includes(origin_branch_id) &&
        !accessibleBranchIds.includes(destination_branch_id)
      ) {
        return NextResponse.json(
          { error: "Access denied to one or both branches" },
          { status: 403 },
        );
      }
    }

    // Generate order number
    const { data: orderNumberData, error: orderNumberError } =
      await supabase.rpc("generate_internal_order_number", {
        org_id: branchContext.organizationId,
      });

    if (orderNumberError) {
      logger.error("Failed to generate order number", {
        error: orderNumberError.message,
      });
      return NextResponse.json(
        { error: "Failed to generate order number" },
        { status: 500 },
      );
    }

    // Create internal order
    const { data: order, error: orderError } = await supabase
      .from("internal_orders")
      .insert({
        order_number: orderNumberData,
        origin_branch_id,
        destination_branch_id,
        status: "pending",
        priority,
        scheduled_date,
        notes,
        created_by: user.id,
        organization_id: branchContext.organizationId,
      })
      .select()
      .single();

    if (orderError) {
      logger.error("Failed to create internal order", {
        error: orderError.message,
      });
      return NextResponse.json(
        { error: "Failed to create internal order" },
        { status: 500 },
      );
    }

    // Create order items
    const orderItems = items.map((item: unknown) => ({
      internal_order_id: order.id,
      product_id: item.product_id,
      quantity: item.quantity,
      notes: item.notes,
    }));

    const { error: itemsError } = await supabase
      .from("internal_order_items")
      .insert(orderItems);

    if (itemsError) {
      logger.error("Failed to create order items", {
        error: itemsError.message,
      });
      // Rollback - delete the order
      await supabase.from("internal_orders").delete().eq("id", order.id);
      return NextResponse.json(
        { error: "Failed to create order items" },
        { status: 500 },
      );
    }

    // Fetch complete order with relations
    const { data: completeOrder } = await supabase
      .from("internal_orders")
      .select(
        `
        *,
        origin_branch:branches!internal_orders_origin_branch_id_fkey(name, code),
        destination_branch:branches!internal_orders_destination_branch_id_fkey(name, code),
        created_by_user:admin_users!internal_orders_created_by_fkey(first_name, last_name),
        items:internal_order_items(
          *,
          product:products(name, sku)
        )
      `,
      )
      .eq("id", order.id)
      .single();

    logger.info("Internal order created", {
      orderId: order.id,
      orderNumber: order.order_number,
      userId: user.id,
    });

    return NextResponse.json(completeOrder, { status: 201 });
  } catch (error) {
    logger.error("Internal order creation error", { error });
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import {
  parseAndValidateBody,
  ValidationError,
