import { NextRequest } from "next/server";

import { APIError } from "@/lib/api/errors";
import {
  createApiErrorResponse,
  createApiSuccessResponse,
} from "@/lib/api/response";
import { validationErrorResponse } from "@/lib/api/validation/zod-helpers";
import {
  createLensFamilyFullSchema,
  createLensFamilySchema,
} from "@/lib/api/validation/zod-schemas";
import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    const supabase = await createClient();

    // Check authentication
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return createApiErrorResponse(
        new APIError("Unauthorized", 401, "UNAUTHORIZED"),
      );
    }

    // Check admin status
    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return createApiErrorResponse(
        new APIError("Admin access required", 403, "FORBIDDEN"),
      );
    }

    // Get user's organization_id for multi-tenancy
    const { data: adminUser } = await supabase
      .from("admin_users")
      .select("organization_id, role")
      .eq("id", user.id)
      .single();

    const userOrganizationId = (
      adminUser as { organization_id?: string; role?: string }
    )?.organization_id;
    const isSuperAdmin =
      (adminUser as { role?: string })?.role === "super_admin";

    const { searchParams } = new URL(request.url);
    const includeInactive = searchParams.get("include_inactive") === "true";
    const categorySlug = searchParams.get("category_slug");
    const categoryId = searchParams.get("category_id");
    const lensType = searchParams.get("lens_type");
    const search = searchParams.get("search")?.trim();

    // Build query - include category for display (FK category_id -> categories)
    let query = supabase
      .from("lens_families")
      .select("*, categories:category_id(id, name, slug)")
      .order("created_at", { ascending: false });

    // CRITICAL: Filter by organization_id (each organization has its own lens families)
    // Even super admins should only see families from their organization (unless root/dev)
    if (userOrganizationId) {
      // Filter by organization_id - this ensures multi-tenancy isolation
      query = query.eq("organization_id", userOrganizationId);
    } else if (!isSuperAdmin) {
      // If no organization_id and not super admin, return empty (no families)
      return createApiSuccessResponse([]);
    }
    // Note: Root/dev users (super_admin role) without organization_id can see all families
    // This is intentional for platform administration

    // Filter by active status if needed
    if (!includeInactive) {
      query = query.eq("is_active", true);
    }

    // Filter by category_id (direct)
    if (categoryId) {
      query = query.eq("category_id", categoryId);
    }

    // Filter by category_slug (supports comma-separated: monofocales,lectura,ocupacional)
    if (categorySlug && !categoryId) {
      const slugs = categorySlug
        .split(",")
        .map((s) => s.trim())
        .filter(Boolean);
      if (slugs.length > 0) {
        const { data: cats } = await supabase
          .from("categories")
          .select("id")
          .in("slug", slugs);
        const ids = (cats ?? []).map((c) => c.id).filter(Boolean);
        if (ids.length > 0) {
          query = query.in("category_id", ids);
        }
      }
    }

    // Filter by lens_type (comma-separated: single_vision,progressive,reading)
    if (lensType) {
      const types = lensType
        .split(",")
        .map((s) => s.trim())
        .filter(Boolean);
      if (types.length > 0) {
        query = query.in("lens_type", types);
      }
    }

    // Filter by search (name or brand ILIKE)
    if (search) {
      query = query.or(`name.ilike.%${search}%,brand.ilike.%${search}%`);
    }

    const { data: families, error } = await query;

    if (error) {
      logger.error("Error fetching lens families", error);
      return createApiErrorResponse(
        new Error("Error al cargar familias de lentes"),
      );
    }

    return createApiSuccessResponse(families || []);
  } catch (error) {
    logger.error("Error in lens families API GET", error);
    return createApiErrorResponse(
      error instanceof Error ? error : new Error("Internal server error"),
    );
  }
}

export async function POST(request: NextRequest) {
  try {
