    // Check admin status
    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    // Validate body
    const body = await parseAndValidateBody(
      request,
      createLensPriceMatrixSchema,
    );

    // Ensure the lens_family belongs to user's organization
    const { data: adminUser } = await supabase
      .from("admin_users")
      .select("organization_id, role")
      .eq("id", user.id)
      .single();

    const userOrganizationId = (
      adminUser as { organization_id?: string; role?: string }
    )?.organization_id;
    const isSuperAdmin =
      (adminUser as { role?: string })?.role === "super_admin";

    if (!isSuperAdmin && userOrganizationId) {
      const { data: family } = await supabase
        .from("lens_families")
        .select("id")
        .eq("id", body.lens_family_id)
        .eq("organization_id", userOrganizationId)
        .maybeSingle();
      if (!family) {
        return NextResponse.json(
          {
            error:
              "La familia de lentes no existe o no pertenece a tu organización",
          },
          { status: 403 },
        );
      }
    }

    // Insert price matrix
    const { data: matrix, error } = await supabase
      .from("lens_price_matrices")
      .insert(body)
      .select(
        `
        *,
        lens_families (
          id,
          name,
          brand,
          lens_type,
          lens_material
        )
      `,
      )
      .single();

    if (error) {
      logger.error("Error creating lens price matrix", error);
      return NextResponse.json(
        { error: "Error al crear matriz de precios" },
        { status: 500 },
      );
    }

    return NextResponse.json({ matrix }, { status: 201 });
  } catch (error: unknown) {
    if (error instanceof ValidationError) {
      return validationErrorResponse(error as unknown);
    } else {
      logger.error("Error in lens matrices API POST", error);
      return NextResponse.json(
        { error: "Internal server error" },
        { status: 500 },
      );
    }
  }
}

import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      // Silently return 401 - this is expected when user is not authenticated
      // Don't log as error since this happens during initial page load
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin, error: adminCheckError } = await supabase.rpc(
      "is_admin",
      { user_id: user.id },
    );
    if (adminCheckError) {
      logger.error("Admin check error", adminCheckError);
      return NextResponse.json(
        { error: "Admin verification failed" },
        { status: 500 },
      );
    }
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    // Check if user is root/dev
    const { data: isRootUser } = await supabase.rpc("is_root_user", {
      user_id: user.id,
    });

    const url = new URL(request.url);
    const limit = parseInt(url.searchParams.get("limit") || "20");
    const offset = parseInt(url.searchParams.get("offset") || "0");
    const unreadOnly = url.searchParams.get("unread_only") === "true";
    const type = url.searchParams.get("type");
    const branchId = url.searchParams.get("branch_id") || undefined;

    // RLS policies handle filtering by organization_id and branch_id automatically.
    // When branch_id is provided (user has a branch selected), filter to that branch only.
    // When not provided (global view), RLS shows all accessible branches for the user.
    let query = supabase
      .from("admin_notifications")
      .select("*", { count: "exact" })
      .eq("is_archived", false)
      .order("created_at", { ascending: false })
      .range(offset, offset + limit - 1);

    // Filter by branch when user has a specific branch selected (multi-sucursal isolation)
    if (branchId) {
      query = query.eq("branch_id", branchId);
    }

    // Apply filters
    if (unreadOnly) {
      query = query.eq("is_read", false);
    }

    if (type) {
      query = query.eq("type", type);
    }

    const { data: notifications, error, count } = await query;

    if (error) {
      logger.error("Error fetching notifications", error);
      return NextResponse.json(
        { error: "Failed to fetch notifications" },
        { status: 500 },
      );
    }

    // Unread count - apply same branch filter as main query
    let unreadQuery = supabase
      .from("admin_notifications")
      .select("id", { count: "exact", head: true })
      .eq("is_archived", false)
      .eq("is_read", false);
    if (branchId) {
      unreadQuery = unreadQuery.eq("branch_id", branchId);
    }
    const { count: unreadCount } = await unreadQuery;

    return NextResponse.json({
      notifications: notifications || [],
      count: count || 0,
      unreadCount,
    });
  } catch (error) {
    logger.error("Error in notifications API GET", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

// Mark notification as read
export async function PATCH(request: NextRequest) {
  try {
    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      logger.error("Auth error in notifications PATCH", userError);
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin, error: adminCheckError } = await supabase.rpc(
      "is_admin",
      { user_id: user.id },
    );
    if (adminCheckError) {
      logger.error("Admin check error", adminCheckError);
      return NextResponse.json(
        { error: "Admin verification failed" },
        { status: 500 },
      );
    }
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    const { notificationId, markAllRead } = await request.json();

    if (markAllRead) {
      // Mark all notifications as read
      await supabase.rpc("mark_all_notifications_read");

      return NextResponse.json({
        success: true,
        message: "All notifications marked as read",
      });
    }

    if (notificationId) {
      // Mark specific notification as read
      await supabase.rpc("mark_notification_read", {
        notification_id: notificationId,
      });

      return NextResponse.json({
        success: true,
        message: "Notification marked as read",
      });
    }

    return NextResponse.json({ error: "Invalid request" }, { status: 400 });
  } catch (error) {
    logger.error("Error updating notification", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

export async function batchUpdateSettingsHandler(request: NextRequest) {
  const supabase = await createClient();

  const {
    data: { user },
    error: userError,
  } = await supabase.auth.getUser();
  if (userError || !user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const { data: isAdmin } = (await supabase.rpc("is_admin", {
    user_id: user.id,
  } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
  if (!isAdmin) {
    return NextResponse.json(
      { error: "Admin access required" },
      { status: 403 },
    );
  }

  const body = await request.json();
  const { updates, organization_id, branch_id } = body;

  if (!Array.isArray(updates) || updates.length === 0) {
    return NextResponse.json(
      { error: "Updates array is required" },
      { status: 400 },
    );
  }

  const orgId = organization_id || null;
  const brId = branch_id || null;

  const results = [];
  for (const update of updates) {
    const { notification_type, ...updateData } = update;

    if (!notification_type) {
      results.push({
        notification_type: null,
        success: false,
        error: "Notification type is required",
      });
      continue;
    }

    let query = supabase
      .from("notification_settings")
      .select("*")
      .eq("notification_type", notification_type);

    if (orgId) {
      query = query.eq("organization_id", orgId);
    } else {
      query = query.is("organization_id", null);
    }
    if (brId) {
      query = query.eq("branch_id", brId);
    } else {
      query = query.is("branch_id", null);
    }

    const { data: existing } = await query.maybeSingle();

    const payload = {
      ...updateData,
      organization_id: orgId,
      branch_id: brId,
      updated_at: new Date().toISOString(),
    };

    let data;
    let error;

    if (existing) {
      const res = await supabase
        .from("notification_settings")
        .update(payload)
        .eq("id", existing.id)
        .select()
        .single();
      data = res.data;
      error = res.error;
    } else {
      const res = await supabase
        .from("notification_settings")
        .insert({
          notification_type,
          ...payload,
          created_at: new Date().toISOString(),
        })
        .select()
        .single();
      data = res.data;
      error = res.error;
    }

    if (error) {
      results.push({ notification_type, success: false, error: error.message });
    } else {
      results.push({ notification_type, success: true, setting: data });
    }
  }

  return NextResponse.json({ success: true, results });
}

