import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

import { batchUpdateSettingsHandler } from "./_handlers/batchUpdateSettings";
import { upsertSettingHandler } from "./_handlers/upsertSetting";

const ALL_NOTIFICATION_TYPES = [
  "quote_new",
  "quote_status_change",
  "quote_converted",
  "work_order_new",
  "work_order_status_change",
  "work_order_completed",
  "appointment_new",
  "appointment_cancelled",
  "new_customer",
  "sale_new",
  "order_new",
  "order_status_change",
  "low_stock",
  "out_of_stock",
  "payment_received",
  "payment_failed",
  "support_ticket_new",
  "support_ticket_update",
  "system_alert",
  "system_update",
  "security_alert",
  "custom",
] as const;

export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    const url = new URL(request.url);
    const organizationId = url.searchParams.get("organization_id") || undefined;
    const branchId = url.searchParams.get("branch_id") || undefined;

    const queries = [
      supabase
        .from("notification_settings")
        .select("*")
        .is("organization_id", null)
        .is("branch_id", null),
      ...(organizationId
        ? [
            supabase
              .from("notification_settings")
              .select("*")
              .eq("organization_id", organizationId)
              .is("branch_id", null),
            ...(branchId
              ? [
                  supabase
                    .from("notification_settings")
                    .select("*")
                    .eq("organization_id", organizationId)
                    .eq("branch_id", branchId),
                ]
              : []),
          ]
        : []),
    ];

    const results = (await Promise.all(queries)) as {
      data: unknown[] | null;
      error: unknown;
    }[];
    const error = results.find((r) => r.error)?.error as
      | { code?: string; message?: string }
      | undefined;
    const rawSettings = results.flatMap((r) => r.data || []);

    if (error) {
      logger.error("Error fetching notification settings:", { error });

      if (
        error.code === "PGRST205" ||
        error.message?.includes("Could not find the table")
      ) {
        return NextResponse.json(
          {
            error: "Table not found",
            message:
              "The notification_settings table does not exist. Please run the database migration: 20250129000000_add_optical_notification_types.sql",
            settings: [],
          },
          { status: 500 },
        );
      }

      return NextResponse.json(
        { error: "Failed to fetch settings", details: error.message },
        { status: 500 },
      );
    }

    const rows = (rawSettings || []) as Array<{
      id: string;
      notification_type: string;
      enabled: boolean;
      priority: string | null;
      organization_id: string | null;
      branch_id: string | null;
      [key: string]: unknown;
    }>;

    const effectiveMap = new Map<
      string,
      {
        id: string;
        enabled: boolean;
        priority: string | null;
        [key: string]: unknown;
      }
    >();

    for (const type of ALL_NOTIFICATION_TYPES) {
      const branchRow = branchId
        ? rows.find(
            (r) =>
              r.notification_type === type &&
              r.organization_id === organizationId &&
              r.branch_id === branchId,
          )
        : null;
      const orgRow = organizationId
        ? rows.find(
            (r) =>
              r.notification_type === type &&
              r.organization_id === organizationId &&
              r.branch_id === null,
          )
        : null;
      const globalRow = rows.find(
        (r) =>
          r.notification_type === type &&
          r.organization_id === null &&
          r.branch_id === null,
      );

      const effective = branchRow ?? orgRow ?? globalRow;
      if (effective) {
        effectiveMap.set(type, {
          ...effective,
          enabled: effective.enabled,
          priority: effective.priority,
        });
      } else {
        effectiveMap.set(type, {
          id: "",
          notification_type: type,
          enabled: true,
          priority: null,
          organization_id: organizationId || null,
          branch_id: branchId || null,
        });
      }
    }

    const settings = Array.from(effectiveMap.values());

    return NextResponse.json({
      settings,
      scope: {
        organization_id: organizationId || null,
        branch_id: branchId || null,
      },
    });
  } catch (error) {
    logger.error("Error in notification settings GET API:", { error });
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

export async function PUT(request: NextRequest) {
  return upsertSettingHandler(request);
}

export async function PATCH(request: NextRequest) {
  return batchUpdateSettingsHandler(request);
}

import { NextRequest, NextResponse } from "next/server";

import { parseAndValidateBody } from "@/lib/api/validation/zod-helpers";
import { updateOpticalInternalSupportTicketSchema } from "@/lib/api/validation/zod-schemas";
import { appLogger as logger } from "@/lib/logger";
// eslint-disable-next-line no-restricted-imports
import { createRootAdminClient } from "@/utils/supabase/root-admin";
import { createClient } from "@/utils/supabase/server";

export async function updateTicketHandler(
  request: NextRequest,
  ticketId: string,
) {
  const supabase = await createClient();
  const supabaseServiceRole = createRootAdminClient();

  const {
    data: { user },
    error: userError,
  } = await supabase.auth.getUser();

  if (userError || !user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const { data: adminUser } = await supabaseServiceRole
    .from("admin_users")
    .select("id, email, role, organization_id")
    .eq("id", user.id)
    .single();

  const isRoot = adminUser?.role === "root" || adminUser?.role === "dev";
  let organizationId = adminUser?.organization_id;
  if (!organizationId && isRoot) {
    organizationId =
      (process.env.NEXT_PUBLIC_ROOT_ORG_ID as string) || undefined;
  }
  if (!adminUser || !organizationId) {
    return NextResponse.json(
      { error: "No organization assigned" },
      { status: 403 },
    );
  }

  const { data: currentTicket, error: currentError } = await supabaseServiceRole
    .from("optical_internal_support_tickets")
    .select("id, organization_id, status, assigned_to, resolved_at, created_at")
    .eq("id", ticketId)
    .eq("organization_id", organizationId)
    .single();

  if (currentError || !currentTicket) {
    return NextResponse.json({ error: "Ticket not found" }, { status: 404 });
  }

  const body = await parseAndValidateBody(
    request,
    updateOpticalInternalSupportTicketSchema,
  );

  const updateData: Record<string, unknown> = {
    updated_at: new Date().toISOString(),
  };

  if (body.status !== undefined) {
    updateData.status = body.status;

    if (body.status === "resolved" || body.status === "closed") {
      if (!currentTicket.resolved_at) {
        const resolvedAt = new Date();
        updateData.resolved_at = resolvedAt.toISOString();
        updateData.resolved_by = adminUser.id;
        const createdAt = new Date(currentTicket.created_at);
        updateData.resolution_time_minutes = Math.round(
          (resolvedAt.getTime() - createdAt.getTime()) / (1000 * 60),
        );
      }
    }
  }

  if (body.priority !== undefined) {
    updateData.priority = body.priority;
  }

  if (body.assigned_to !== undefined) {
    updateData.assigned_to = body.assigned_to;
    if (body.assigned_to && currentTicket.assigned_to !== body.assigned_to) {
      updateData.assigned_at = new Date().toISOString();
    }
  }

  if (body.resolution !== undefined) {
    updateData.resolution = body.resolution;
  }

  if (body.resolution_notes !== undefined) {
    updateData.resolution_notes = body.resolution_notes;
  }

  const { data: ticket, error: ticketError } = await supabaseServiceRole
    .from("optical_internal_support_tickets")
    .update(updateData)
    .eq("id", ticketId)
    .select(
      `
        *,
        customer:customers(id, first_name, last_name, email),
        assigned_to_user:admin_users!optical_internal_support_tickets_assigned_to_fkey(id, email, role),
        created_by_user:admin_users!optical_internal_support_tickets_created_by_user_id_fkey(id, email, role),
        resolved_by_user:admin_users!optical_internal_support_tickets_resolved_by_fkey(id, email, role),
        branch:branches(id, name, code)
      `,
    )
    .single();

  if (ticketError) {
    logger.error("Error updating optical internal support ticket", ticketError);
    return NextResponse.json(
      { error: "Failed to update ticket" },
      { status: 500 },
    );
  }

  if (body.status && body.status !== currentTicket.status) {
    await supabaseServiceRole.from("optical_internal_support_messages").insert({
      ticket_id: ticketId,
      message: `Estado cambiado a: ${body.status}`,
      is_internal: true,
      sender_id: adminUser.id,
      sender_name: user.email?.split("@")[0] || "Sistema",
      sender_email: adminUser.email || user.email || "",
      sender_role: adminUser.role,
      message_type: "status_change",
    });
  }

  if (
    body.assigned_to !== undefined &&
    body.assigned_to !== currentTicket.assigned_to
  ) {
    const assignedUserName = body.assigned_to
      ? (
          await supabaseServiceRole
            .from("admin_users")
            .select("email")
            .eq("id", body.assigned_to)
            .single()
        ).data?.email || "Usuario"
      : "Sin asignar";

    await supabaseServiceRole.from("optical_internal_support_messages").insert({
      ticket_id: ticketId,
      message: `Ticket asignado a: ${assignedUserName}`,
      is_internal: true,
      sender_id: adminUser.id,
      sender_name: user.email?.split("@")[0] || "Sistema",
      sender_email: adminUser.email || user.email || "",
      sender_role: adminUser.role,
      message_type: "assignment",
    });
  }

  const hasResolution =
    (body.resolution && body.resolution.trim()) ||
    (body.resolution_notes && body.resolution_notes.trim());
  if (hasResolution) {
    const resolutionParts: string[] = [];
    if (body.resolution?.trim()) {
      resolutionParts.push(`Resolución: ${body.resolution.trim()}`);
    }
    if (body.resolution_notes?.trim()) {
      resolutionParts.push(`Notas: ${body.resolution_notes.trim()}`);
    }

    await supabaseServiceRole.from("optical_internal_support_messages").insert({
      ticket_id: ticketId,
      message: resolutionParts.join("\n\n"),
      is_internal: true,
      sender_id: adminUser.id,
      sender_name: user.email?.split("@")[0] || "Sistema",
      sender_email: adminUser.email || user.email || "",
      sender_role: adminUser.role,
      message_type: "resolution",
    });
  }

  return NextResponse.json({
    success: true,
    ticket,
  });
}

import { NextRequest, NextResponse } from "next/server";

import { parseAndValidateBody } from "@/lib/api/validation/zod-helpers";
import { createOpticalInternalSupportMessageSchema } from "@/lib/api/validation/zod-schemas";
import { appLogger as logger } from "@/lib/logger";
import { createRootAdminClient } from "@/utils/supabase/root-admin";
import { createClient } from "@/utils/supabase/server";

/**
 * GET /api/admin/optical-support/tickets/[id]/messages
 * Obtener mensajes de un ticket
 */
export const dynamic = "force-dynamic";
export async function GET(
  request: NextRequest,
  { params }: { params: { id: string } },
) {
  try {
    const supabase = await createClient();
    const supabaseServiceRole = createRootAdminClient();

    // Obtener usuario autenticado
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    // Obtener información del usuario admin
    const { data: adminUser } = await supabaseServiceRole
      .from("admin_users")
      .select("id, role, organization_id")
      .eq("id", user.id)
      .single();

    const isRoot = adminUser?.role === "root" || adminUser?.role === "dev";
    let organizationId = adminUser?.organization_id;
    if (!organizationId && isRoot) {
      organizationId = (process.env.NEXT_PUBLIC_ROOT_ORG_ID as string) || null;
    }
    if (!adminUser || !organizationId) {
      return NextResponse.json(
        { error: "No organization assigned" },
        { status: 403 },
      );
    }

    // Obtener ticket para verificar permisos
    const { data: ticket, error: ticketError } = await supabaseServiceRole
      .from("optical_internal_support_tickets")
      .select("id, organization_id")
      .eq("id", params.id)
      .eq("organization_id", organizationId)
      .single();

    if (ticketError || !ticket) {
      return NextResponse.json({ error: "Ticket not found" }, { status: 404 });
    }

    // Obtener mensajes
    const { data: messages, error: messagesError } = await supabaseServiceRole
      .from("optical_internal_support_messages")
      .select(
        `
        *,
        sender:admin_users!optical_internal_support_messages_sender_id_fkey(id, email, role)
      `,
      )
      .eq("ticket_id", params.id)
      .order("created_at", { ascending: true });

    if (messagesError) {
      logger.error(
        "Error fetching optical internal support messages",
        messagesError,
      );
      return NextResponse.json(
        { error: "Failed to fetch messages" },
        { status: 500 },
      );
    }

    return NextResponse.json({ messages: messages || [] });
  } catch (error) {
    logger.error(
      "Unexpected error in GET /api/admin/optical-support/tickets/[id]/messages",
      error,
    );
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

/**
 * POST /api/admin/optical-support/tickets/[id]/messages
 * Crear nuevo mensaje en un ticket
 */
export async function POST(
  request: NextRequest,
  { params }: { params: { id: string } },
) {
  try {
    const supabase = await createClient();
    const supabaseServiceRole = createRootAdminClient();

    // Obtener usuario autenticado
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    // Obtener información del usuario admin
    const { data: adminUser, error: adminError } = await supabaseServiceRole
      .from("admin_users")
      .select("id, email, role, organization_id")
      .eq("id", user.id)
      .single();

    if (adminError || !adminUser) {
      return NextResponse.json({ error: "User not found" }, { status: 404 });
    }

    const isRootPost = adminUser.role === "root" || adminUser.role === "dev";
    let organizationIdPost = adminUser.organization_id;
    if (!organizationIdPost && isRootPost) {
      organizationIdPost =
        (process.env.NEXT_PUBLIC_ROOT_ORG_ID as string) || null;
    }
    if (!organizationIdPost) {
      return NextResponse.json(
        { error: "No organization assigned" },
        { status: 403 },
      );
    }

    // Verificar que el ticket existe y pertenece a la organización
    const { data: ticket, error: ticketError } = await supabaseServiceRole
      .from("optical_internal_support_tickets")
      .select("id, organization_id, status")
      .eq("id", params.id)
      .eq("organization_id", organizationIdPost)
      .single();

    if (ticketError || !ticket) {
      return NextResponse.json({ error: "Ticket not found" }, { status: 404 });
    }

    // Validar body
    const body = await parseAndValidateBody(
      request,
      createOpticalInternalSupportMessageSchema,
    );

    // Crear mensaje
    const { data: message, error: messageError } = await supabaseServiceRole
      .from("optical_internal_support_messages")
      .insert({
        ticket_id: params.id,
        message: body.message,
        is_internal: body.is_internal ?? true,
        sender_id: adminUser.id,
        sender_name: user.email?.split("@")[0] || "Usuario",
        sender_email: adminUser.email || user.email || "",
        sender_role: adminUser.role,
        message_type: body.message_type || "message",
        attachments: body.attachments || [],
      })
      .select(
        `
        *,
        sender:admin_users!optical_internal_support_messages_sender_id_fkey(id, email, role)
      `,
      )
      .single();

    if (messageError) {
      logger.error(
        "Error creating optical internal support message",
        messageError,
      );
      return NextResponse.json(
        { error: "Failed to create message" },
        { status: 500 },
      );
    }

    // Actualizar last_response_at del ticket
    await supabaseServiceRole
      .from("optical_internal_support_tickets")
      .update({
        last_response_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      })
      .eq("id", params.id);

    // Si el ticket estaba cerrado y se agrega un mensaje, cambiar a "waiting_customer"
    if (ticket.status === "closed" || ticket.status === "resolved") {
      await supabaseServiceRole
        .from("optical_internal_support_tickets")
        .update({
          status: "waiting_customer",
          updated_at: new Date().toISOString(),
        })
        .eq("id", params.id);
    }

    logger.info("Optical internal support message created", {
      messageId: message?.id,
      ticketId: params.id,
    });

    return NextResponse.json({
      success: true,
      message,
    });
  } catch (error) {
    logger.error(
      "Unexpected error in POST /api/admin/optical-support/tickets/[id]/messages",
      error,
    );
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

