import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { parseAndValidateBody } from "@/lib/api/validation/zod-helpers";
import { createOpticalInternalSupportTicketSchema } from "@/lib/api/validation/zod-schemas";
import { appLogger as logger } from "@/lib/logger";
// eslint-disable-next-line no-restricted-imports
import { createRootAdminClient } from "@/utils/supabase/root-admin";
import { createClient } from "@/utils/supabase/server";

export async function createTicketHandler(request: NextRequest) {
  const supabase = await createClient();
  const supabaseServiceRole = createRootAdminClient();

  const {
    data: { user },
    error: userError,
  } = await supabase.auth.getUser();

  if (userError || !user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const { data: adminUser, error: adminError } = await supabaseServiceRole
    .from("admin_users")
    .select("id, email, role, organization_id")
    .eq("id", user.id)
    .single();

  if (adminError || !adminUser) {
    return NextResponse.json({ error: "User not found" }, { status: 404 });
  }

  const isRoot = adminUser.role === "root" || adminUser.role === "dev";
  let organizationId = adminUser.organization_id;

  if (!organizationId && isRoot) {
    organizationId =
      (process.env.NEXT_PUBLIC_ROOT_ORG_ID as string) || undefined;
  }

  if (!organizationId) {
    return NextResponse.json(
      { error: "No organization assigned" },
      { status: 403 },
    );
  }

  const body = await parseAndValidateBody(
    request,
    createOpticalInternalSupportTicketSchema,
  );

  const branchContext = await getBranchContext(request, user.id);
  const branchId = body.branch_id || branchContext.branchId || null;

  if (branchId) {
    const { data: branch } = await supabaseServiceRole
      .from("branches")
      .select("id, organization_id")
      .eq("id", branchId)
      .single();

    if (!branch || branch.organization_id !== organizationId) {
      return NextResponse.json(
        { error: "Branch does not belong to your organization" },
        { status: 403 },
      );
    }
  }

  if (body.customer_id) {
    const { data: customer } = await supabaseServiceRole
      .from("customers")
      .select("id, organization_id, first_name, last_name, email, phone")
      .eq("id", body.customer_id)
      .single();

    if (!customer || customer.organization_id !== organizationId) {
      return NextResponse.json(
        { error: "Customer does not belong to your organization" },
        { status: 403 },
      );
    }

    body.customer_name =
      body.customer_name ||
      `${customer.first_name || ""} ${customer.last_name || ""}`.trim() ||
      undefined;
    body.customer_email = body.customer_email || customer.email || undefined;
    body.customer_phone = body.customer_phone || customer.phone || undefined;
  }

  const { data: ticket, error: ticketError } = await supabaseServiceRole
    .from("optical_internal_support_tickets")
    .insert({
      organization_id: organizationId,
      branch_id: branchId,
      customer_id: body.customer_id || null,
      customer_name: body.customer_name || null,
      customer_email: body.customer_email || null,
      customer_phone: body.customer_phone || null,
      related_order_id: body.related_order_id || null,
      related_work_order_id: body.related_work_order_id || null,
      related_appointment_id: body.related_appointment_id || null,
      related_quote_id: body.related_quote_id || null,
      created_by_user_id: adminUser.id,
      created_by_name: user.email?.split("@")[0] || "Usuario",
      created_by_role: adminUser.role,
      subject: body.subject,
      description: body.description,
      category: body.category,
      priority: body.priority || "medium",
      status: "open",
      assigned_to: body.assigned_to || null,
      metadata: body.metadata || {},
    })
    .select(
      `
        *,
        customer:customers(id, first_name, last_name, email),
        assigned_to_user:admin_users!optical_internal_support_tickets_assigned_to_fkey(id, email, role),
        created_by_user:admin_users!optical_internal_support_tickets_created_by_user_id_fkey(id, email, role),
        branch:branches(id, name, code)
      `,
    )
    .single();

  if (ticketError) {
    logger.error("Error creating optical internal support ticket", ticketError);
    return NextResponse.json(
      {
        error: "Failed to create ticket",
        details: ticketError.message,
      },
      { status: 500 },
    );
  }

  if (ticket) {
    await supabaseServiceRole.from("optical_internal_support_messages").insert({
      ticket_id: ticket.id,
      message: body.description,
      is_internal: false,
      sender_id: adminUser.id,
      sender_name: user.email?.split("@")[0] || "Usuario",
      sender_email: adminUser.email || user.email || "",
      sender_role: adminUser.role,
      message_type: "message",
    });
  }

  logger.info("Optical internal support ticket created", {
    ticketId: ticket?.id,
    ticketNumber: ticket?.ticket_number,
  });

  return NextResponse.json({
    success: true,
    ticket,
  });
}

import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { opticalInternalSupportTicketFiltersSchema } from "@/lib/api/validation/zod-schemas";
import { appLogger as logger } from "@/lib/logger";
// eslint-disable-next-line no-restricted-imports
import { createRootAdminClient } from "@/utils/supabase/root-admin";
import { createClient } from "@/utils/supabase/server";

import { createTicketHandler } from "./_handlers/createTicket";

/**
 * GET /api/admin/optical-support/tickets
 * Listar tickets de soporte interno de la óptica con filtros
 * - Usuarios normales: solo tickets de su sucursal
 * - Super Admin: todos los tickets de la org (vista global) o de la sucursal seleccionada
 */
export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    const supabase = await createClient();
    const supabaseServiceRole = createRootAdminClient();

    // Obtener usuario autenticado
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    // Obtener información del usuario admin y su organización
    const { data: adminUser, error: adminError } = await supabaseServiceRole
      .from("admin_users")
      .select("id, role, organization_id")
      .eq("id", user.id)
      .single();

    if (adminError || !adminUser) {
      return NextResponse.json({ error: "User not found" }, { status: 404 });
    }

    // Resolver organization_id: usuarios normales usan el suyo; root/dev sin org usan optica-root para testing
    const isRoot = adminUser.role === "root" || adminUser.role === "dev";
    let organizationId = adminUser.organization_id;

    if (!organizationId && isRoot) {
      organizationId =
        (process.env.NEXT_PUBLIC_ROOT_ORG_ID as string) || undefined;
    }

    if (!organizationId) {
      return NextResponse.json(
        { error: "No organization assigned" },
        { status: 403 },
      );
    }

    // Obtener contexto de sucursal: Super Admin puede ver todas; usuarios normales solo su sucursal
    const branchContext = await getBranchContext(request, user.id);
    const { branchId, isSuperAdmin, isGlobalView } = branchContext;

    const { searchParams } = new URL(request.url);
    const queryBranchId = searchParams.get("branch_id");

    // Determinar branch_id efectivo para el filtro
    let effectiveBranchId: string | null = null;
    if (isSuperAdmin) {
      // Super Admin: si hay branch en query/header y no es "global", filtrar por esa sucursal
      if (queryBranchId && queryBranchId !== "global") {
        effectiveBranchId = queryBranchId;
      } else if (!isGlobalView && branchId) {
        effectiveBranchId = branchId;
      }
      // Si isGlobalView o branch_id=global: effectiveBranchId queda null → mostrar todas las sucursales
    } else {
      // Usuario normal: SIEMPRE filtrar por sucursal (solo ve la suya)
      effectiveBranchId = branchId || queryBranchId || null;
      if (!effectiveBranchId) {
        const primaryBranch = branchContext.accessibleBranches.find(
          (b: { isPrimary?: boolean }) => b.isPrimary,
        );
        effectiveBranchId =
          primaryBranch?.id || branchContext.accessibleBranches[0]?.id || null;
      }
      if (!effectiveBranchId) {
        return NextResponse.json(
          { error: "Debe seleccionar una sucursal para ver los tickets" },
          { status: 400 },
        );
      }
    }

    // Validar y parsear filtros
    const filters = opticalInternalSupportTicketFiltersSchema.parse({
      branch_id: queryBranchId || undefined,
      customer_id: searchParams.get("customer_id") || undefined,
      status: searchParams.get("status") || undefined,
      priority: searchParams.get("priority") || undefined,
      category: searchParams.get("category") || undefined,
      assigned_to: searchParams.get("assigned_to") || undefined,
      search: searchParams.get("search") || undefined,
      page: searchParams.get("page") || "1",
      limit: searchParams.get("limit") || "20",
      sort_by: searchParams.get("sort_by") || "created_at",
      sort_order: searchParams.get("sort_order") || "desc",
    });

    const offset = ((filters.page ?? 1) - 1) * (filters.limit ?? 20);

    // Construir query base
    let query = supabaseServiceRole
      .from("optical_internal_support_tickets")
      .select(
        `
        *,
        customer:customers(id, first_name, last_name, email),
        assigned_to_user:admin_users!optical_internal_support_tickets_assigned_to_fkey(id, email, role),
        created_by_user:admin_users!optical_internal_support_tickets_created_by_user_id_fkey(id, email, role),
        branch:branches(id, name, code),
        related_order:orders(id, order_number),
        related_work_order:lab_work_orders(id, work_order_number),
        related_appointment:appointments(id, appointment_date, appointment_time),
        related_quote:quotes(id, quote_number)
      `,
        { count: "exact" },
      )
      .eq("organization_id", organizationId) // Solo tickets de su organización
      .order((filters.sort_by || "created_at") as unknown, {
        ascending: filters.sort_order === "asc",
      });

    // Filtro por sucursal (obligatorio para usuarios normales; opcional para Super Admin)
    if (effectiveBranchId) {
      query = query.eq("branch_id", effectiveBranchId);
    }

    if (filters.customer_id) {
      query = query.eq("customer_id", filters.customer_id);
    }

    if (filters.status) {
      query = query.eq("status", filters.status);
    }

    if (filters.priority) {
      query = query.eq("priority", filters.priority);
    }

    if (filters.category) {
      query = query.eq("category", filters.category);
    }

    if (filters.assigned_to) {
      query = query.eq("assigned_to", filters.assigned_to);
    }

    if (filters.search) {
      query = query.or(
        `subject.ilike.%${filters.search}%,description.ilike.%${filters.search}%,ticket_number.ilike.%${filters.search}%`,
      );
    }

    // Aplicar paginación
    query = query.range(offset, offset + (filters.limit ?? 20) - 1);

    const { data: tickets, error, count } = await query;

    if (error) {
      logger.error("Error fetching optical internal support tickets", error);
      return NextResponse.json(
        { error: "Failed to fetch tickets" },
        { status: 500 },
      );
    }

    return NextResponse.json({
      tickets: tickets || [],
      pagination: {
        total: count || 0,
        page: filters.page,
        limit: filters.limit ?? 20,
        totalPages: Math.ceil((count || 0) / (filters.limit ?? 20)),
      },
    });
  } catch (error) {
    logger.error(
      "Unexpected error in GET /api/admin/optical-support/tickets",
      error,
    );
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

/**
 * POST /api/admin/optical-support/tickets
 * Crear nuevo ticket de soporte interno
 */
export async function POST(request: NextRequest) {
  return createTicketHandler(request);
}

/**
 * POST /api/admin/opticas-access-tokens - Create token
 * GET /api/admin/opticas-access-tokens - List active tokens
 *
 * Root only. Tokens for /acceso-opticas?token=XXX
 */
import { randomBytes } from "crypto";
import { NextRequest, NextResponse } from "next/server";

import { AuthorizationError } from "@/lib/api/errors";
import { requireRoot } from "@/lib/api/root-middleware";
import { appLogger as logger } from "@/lib/logger";
import { createRootAdminClient } from "@/utils/supabase/root-admin";

export const dynamic = "force-dynamic";

/** Generate token: opticas_ + 48 hex chars */
function generateToken(): string {
  return `opticas_${randomBytes(24).toString("hex")}`;
}

/**
 * POST - Create new token
 * Body: { expires_in_days?: number, label?: string } (default 90 days)
 */
export async function POST(request: NextRequest) {
  try {
    const { userId } = await requireRoot(request);
    const supabase = createRootAdminClient();

    let body: { expires_in_days?: number; label?: string } = {};
    try {
      body = await request.json();
    } catch {
      // empty body ok
    }

    const expiresInDays = body.expires_in_days ?? 90;
    const label = body.label ?? null;

    const expiresAt = new Date();
    expiresAt.setDate(expiresAt.getDate() + expiresInDays);

    const token = generateToken();

    const { data, error } = await supabase
      .from("opticas_access_tokens")
      .insert({
        token,
        expires_at: expiresAt.toISOString(),
        created_by: userId,
        label,
      })
      .select("id, token, expires_at")
      .single();

    if (error) {
      logger.error("Error creating opticas access token", error);
      return NextResponse.json(
        { error: "Error al crear token", details: error.message },
        { status: 500 },
      );
    }

    const origin =
      request.headers.get("x-forwarded-host") ||
      request.headers.get("host") ||
      "";
    const protocol = request.headers.get("x-forwarded-proto") || "https";
    const baseUrl = `${protocol}://${origin}`;
    const url = `${baseUrl}/acceso-opticas?token=${token}`;

    logger.info("Opticas access token created", { id: data.id });

    return NextResponse.json({
      id: data.id,
      token,
      url,
      expires_at: data.expires_at,
    });
  } catch (err) {
    if (err instanceof AuthorizationError) {
      return NextResponse.json({ error: err.message }, { status: 403 });
    }
    logger.error("Error in POST opticas-access-tokens", err);
    return NextResponse.json(
      { error: "Error interno del servidor" },
      { status: 500 },
    );
  }
}

/**
 * GET - List active (non-expired) tokens
 */
export async function GET(request: NextRequest) {
  try {
    await requireRoot(request);
    const supabase = createRootAdminClient();

    const { data, error } = await supabase
      .from("opticas_access_tokens")
      .select("id, token, expires_at, label, created_at")
      .gt("expires_at", new Date().toISOString())
      .order("created_at", { ascending: false });

    if (error) {
      logger.error("Error listing opticas access tokens", error);
      return NextResponse.json(
        { error: "Error al listar tokens", details: error.message },
        { status: 500 },
      );
    }

    const tokens = (data ?? []).map((row) => ({
      id: row.id,
      token_preview: `${row.token.slice(0, 8)}...`,
      expires_at: row.expires_at,
      label: row.label,
      created_at: row.created_at,
    }));

    return NextResponse.json({ tokens });
  } catch (err) {
    if (err instanceof AuthorizationError) {
      return NextResponse.json({ error: err.message }, { status: 403 });
    }
    logger.error("Error in GET opticas-access-tokens", err);
    return NextResponse.json(
      { error: "Error interno del servidor" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import type {
  GetAdminRoleParams,
  GetAdminRoleResult,
  IsAdminParams,
  IsAdminResult,
} from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

/**
 * POST /api/admin/orders/[id]/cancel
 * Cancel/void an order (Admin or SuperAdmin; Admin only for orders in their branch)
 */
export const dynamic = "force-dynamic";
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { id: orderId } = await params;
    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    const { data: adminRole } = (await supabase.rpc("get_admin_role", {
      user_id: user.id,
    } as GetAdminRoleParams)) as {
      data: GetAdminRoleResult | null;
      error: Error | null;
    };
    const canCancel =
      adminRole === "super_admin" ||
      adminRole === "admin" ||
      adminRole === "root" ||
      adminRole === "dev";
    if (!canCancel) {
      return NextResponse.json(
        { error: "Solo administradores pueden anular ventas" },
        { status: 403 },
      );
    }

    // Get branch context (for non-super-admin we validate order's branch access below)
    const branchContext = await getBranchContext(request, user.id);

    const body = await request.json();
    const { reason, refund_method } = body;

    if (!reason) {
      return NextResponse.json(
        { error: "Reason is required" },
        { status: 400 },
      );
    }

    // All cancellations require credit note: revert stock + register in caja
    if (!refund_method) {
      return NextResponse.json(
        {
          error:
            "refund_method is required (cash, debit, credit, transfer) - todas las anulaciones crean nota de crédito para revertir stock y actualizar caja",
        },
        { status: 400 },
      );
    }

    const validRefundMethods = ["cash", "debit", "credit", "transfer"];
    if (!validRefundMethods.includes(refund_method)) {
      return NextResponse.json(
        {
          error: `refund_method must be one of: ${validRefundMethods.join(", ")}`,
        },
        { status: 400 },
      );
    }

    // Get order
    const { data: order, error: orderError } = await supabase
      .from("orders")
      .select("*")
      .eq("id", orderId)
      .single();

    if (orderError || !order) {
      return NextResponse.json({ error: "Order not found" }, { status: 404 });
    }

    // Non-super-admin can only cancel orders in their accessible branches
    if (!branchContext.isSuperAdmin && order.branch_id) {
      const hasAccess = branchContext.accessibleBranches.some(
        (b) => b.id === order.branch_id,
      );
      if (!hasAccess) {
        return NextResponse.json(
          { error: "No tienes acceso a la sucursal de esta orden" },
          { status: 403 },
        );
      }
    }

    // Require open cash register (caja) to cancel orders and create credit notes
    if (order.branch_id) {
      const { data: openSession } = await supabase
        .from("pos_sessions")
        .select("id")
        .eq("branch_id", order.branch_id)
        .eq("status", "open")
        .limit(1)
        .maybeSingle();

      if (!openSession) {
        return NextResponse.json(
          {
            error:
              "La caja debe estar abierta para anular ventas y crear notas de crédito. Abre la caja de esta sucursal e intenta nuevamente.",
          },
          { status: 400 },
        );
      }
    }

    let creditNoteId: string | null = null;
    let posSessionId: string | null = null;

    // All cancellations: revert stock + create credit note (for caja consistency)
    if (order.branch_id) {
      try {
        // Get total_paid from order_payments (for partial payments, refund only what was paid)
        const { data: payments } = await supabase
          .from("order_payments")
          .select("amount")
          .eq("order_id", orderId);
        const totalPaid = (payments || []).reduce(
          (sum: number, p: { amount: number }) => sum + Number(p.amount || 0),
          0,
        );
        const refundAmount =
          totalPaid > 0
            ? Math.min(totalPaid, Number(order.total_amount))
            : Number(order.total_amount);

        // Revert stock for order items with product_id
        const { data: orderItems } = await supabase
          .from("order_items")
          .select("id, product_id, quantity")
          .eq("order_id", orderId);
        for (const oi of orderItems || []) {
          if (oi.product_id && order.branch_id) {
            try {
              const { error: stockErr } = await supabase.rpc(
                "update_product_stock",
                {
                  p_product_id: oi.product_id,
                  p_branch_id: order.branch_id,
                  p_quantity_change: parseInt(String(oi.quantity), 10) || 0,
                  p_reserve: false,
                  p_movement_type: "refund",
                  p_reference_type: "order_cancel",
                  p_reference_id: orderId,
                  p_created_by: user.id,
                },
              );
              if (stockErr) {
                logger.warn("Stock revert failed for item, continuing", {
                  order_item_id: oi.id,
                  product_id: oi.product_id,
                  error: stockErr.message,
                });
              }
            } catch (stockEx: unknown) {
              logger.warn("Stock revert exception, continuing", {
                order_item_id: oi.id,
                error: stockEx?.message,
              });
            }
          }
        }

        // Get open POS session for this branch
        const { data: openSession } = await supabase
          .from("pos_sessions")
          .select("id")
          .eq("branch_id", order.branch_id)
          .eq("status", "open")
          .order("opening_time", { ascending: false })
          .limit(1)
          .maybeSingle();

        posSessionId = openSession?.id ?? null;

        // Generate credit note number
        const { data: cnNumberRaw, error: cnNumError } =
          await supabase.rpc("generate_credit_note_number");

        const cnNumber =
          typeof cnNumberRaw === "string"
            ? cnNumberRaw
            : Array.isArray(cnNumberRaw) && cnNumberRaw[0]
              ? cnNumberRaw[0]
              : cnNumberRaw;

        if (cnNumError || !cnNumber || typeof cnNumber !== "string") {
          logger.error("Error generating credit note number", {
            error: cnNumError,
            raw: cnNumberRaw,
          });
          return NextResponse.json(
            {
              error: "Error al generar número de nota de crédito",
              details: cnNumError?.message || "Número de nota inválido",
            },
            { status: 500 },
          );
        }

        // Get organization_id from branch
        const { data: branchRow } = await supabase
          .from("branches")
          .select("organization_id")
          .eq("id", order.branch_id)
          .single();

        const { data: newCreditNote, error: cnError } =
          await supabase
            .from("credit_notes")
            .insert({
              credit_note_number: cnNumber,
              order_id: orderId,
              branch_id: order.branch_id,
              organization_id: (branchRow as unknown)?.organization_id ?? null,
              amount: refundAmount,
              reason,
              refund_method,
              pos_session_id: posSessionId,
              created_by: user.id,
            })
            .select("id")
            .single();

        if (cnError) {
          logger.error("Error creating credit note", cnError);
          return NextResponse.json(
            {
              error: "Error al crear nota de crédito",
              details: cnError.message,
            },
            { status: 500 },
          );
        }
        creditNoteId = newCreditNote?.id ?? null;

        // Create movement only if we have a session (caja abierta)
        if (posSessionId && creditNoteId) {
          const { error: movError } = await supabase
            .from("credit_note_movements")
            .insert({
              credit_note_id: creditNoteId,
              pos_session_id: posSessionId,
              amount: -refundAmount,
              refund_method,
            });

          if (movError) {
            logger.error("Error creating credit note movement", movError);
            // Don't fail the whole operation - credit note was created
          }
        }
      } catch (creditNoteErr: unknown) {
        logger.error("Error in credit note block", creditNoteErr);
        return NextResponse.json(
          {
            error: "Error al crear nota de crédito",
            details: creditNoteErr?.message ?? String(creditNoteErr),
          },
          { status: 500 },
        );
      }
    }

    // Update order status to cancelled
    const { error: updateError } = await supabase
      .from("orders")
      .update({
        status: "cancelled",
        payment_status: "refunded",
        cancellation_reason: reason,
        updated_at: new Date().toISOString(),
      })
      .eq("id", orderId);

    if (updateError) {
      logger.error("Error cancelling order", updateError);
      return NextResponse.json(
        {
          error: "Error al anular la venta",
          details: updateError.message,
        },
        { status: 500 },
      );
    }

    logger.info("Order cancelled", {
      order_id: orderId,
      cancelled_by: user.email,
      reason,
      original_amount: order.total_amount,
    });

    return NextResponse.json({
      success: true,
      message: "Venta anulada correctamente",
      order_id: orderId,
      credit_note_id: creditNoteId ?? undefined,
      credit_note_movement_registered: !!posSessionId,
    });
  } catch (error: unknown) {
    const errMsg = error?.message ?? String(error);
    const errStack = error?.stack;
    logger.error("Error in cancel order API", {
      message: errMsg,
      stack: errStack,
    });
    logger.error("[cancel] Unhandled error:", { message: errMsg, stack: errStack });
    return NextResponse.json(
      {
        error: "Internal server error",
        details: errMsg,
      },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import type {
  GetAdminRoleParams,
  GetAdminRoleResult,
  IsAdminParams,
  IsAdminResult,
} from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

/**
 * DELETE /api/admin/orders/[id]
 * Delete an order permanently (Admin or SuperAdmin, for cancelled orders only)
 */
export const dynamic = "force-dynamic";
export async function DELETE(
  request: NextRequest,
  { params }: { params: { id: string } },
) {
  try {
    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    const { data: adminRole } = (await supabase.rpc("get_admin_role", {
      user_id: user.id,
    } as GetAdminRoleParams)) as {
      data: GetAdminRoleResult | null;
      error: Error | null;
    };
    const canDelete =
      adminRole === "super_admin" ||
      adminRole === "admin" ||
      adminRole === "root" ||
      adminRole === "dev";
    if (!canDelete) {
      return NextResponse.json(
        { error: "Solo administradores pueden eliminar ventas anuladas" },
        { status: 403 },
      );
    }

    // Get branch context (for non-super-admin we validate order's branch access below)
    const branchContext = await getBranchContext(request, user.id);

    // Get order to verify it's cancelled
    const { data: order, error: orderError } = await supabase
      .from("orders")
      .select("*")
      .eq("id", params.id)
      .single();

    if (orderError || !order) {
      return NextResponse.json({ error: "Order not found" }, { status: 404 });
    }

    // Non-super-admin can only delete orders in their accessible branches
    if (!branchContext.isSuperAdmin && order.branch_id) {
      const hasAccess = branchContext.accessibleBranches.some(
        (b) => b.id === order.branch_id,
      );
      if (!hasAccess) {
        return NextResponse.json(
          { error: "No tienes acceso a la sucursal de esta orden" },
          { status: 403 },
        );
      }
    }

    // Only allow deleting cancelled/refunded orders
    if (order.status !== "cancelled" && order.payment_status !== "refunded") {
      return NextResponse.json(
        {
          error: "Solo se pueden eliminar ventas anuladas",
          current_status: order.status,
        },
        { status: 400 },
      );
    }

    // Delete order items first (foreign key constraint)
    const { error: deleteItemsError } = await supabase
      .from("order_items")
      .delete()
      .eq("order_id", params.id);

    if (deleteItemsError) {
      logger.error("Error deleting order items", deleteItemsError);
      return NextResponse.json(
        {
          error: "Error al eliminar items de la venta",
          details: deleteItemsError.message,
        },
        { status: 500 },
      );
    }

    // Delete order payments
    const { error: deletePaymentsError } = await supabase
      .from("order_payments")
      .delete()
      .eq("order_id", params.id);

    if (deletePaymentsError) {
      logger.error("Error deleting order payments", deletePaymentsError);
      // Don't fail, continue to delete order
    }

    // Delete order
    const { error: deleteError } = await supabase
      .from("orders")
      .delete()
      .eq("id", params.id);

    if (deleteError) {
      logger.error("Error deleting order", deleteError);
      return NextResponse.json(
        {
          error: "Error al eliminar la venta",
          details: deleteError.message,
        },
        { status: 500 },
      );
    }

    logger.info("Order deleted permanently", {
      order_id: params.id,
      deleted_by: user.email,
      order_number: order.order_number,
      original_amount: order.total_amount,
    });

    return NextResponse.json({
      success: true,
      message: "Venta eliminada correctamente",
      order_id: params.id,
    });
  } catch (error: unknown) {
    logger.error("Error in delete order API", { error });
    return NextResponse.json(
      {
        error: "Internal server error",
        details: error.message,
      },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { sendOrderConfirmation } from "@/lib/email/notifications";
import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";
export async function POST(
  request: NextRequest,
  { params }: { params: { id: string } },
) {
  try {
    logger.debug("Sending notification for order", { orderId: params.id });
    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    // Get order details
    const { data: order, error: orderError } = await supabase
      .from("orders")
      .select(
        `
        *,
        order_items (
          id,
          product_name,
          variant_title,
          quantity,
          unit_price,
          total_price
        )
      `,
      )
      .eq("id", params.id)
      .single();

    if (orderError || !order) {
      logger.error("Error fetching order", orderError);
      return NextResponse.json({ error: "Order not found" }, { status: 404 });
    }

    // Customer name: prefer orders.customer_name (POS), fallback to shipping names (e-commerce)
    const customerName =
      order.customer_name?.trim() ||
      (order.shipping_first_name && order.shipping_last_name
        ? `${order.shipping_first_name} ${order.shipping_last_name}`.trim()
        : null) ||
      "Cliente";

    // Payment method: POS uses payment_method_type, e-commerce uses mp_payment_method
    const paymentMethod =
      order.payment_method_type || order.mp_payment_method || "N/A";

    // Prepare order data for email
    const emailOrder = {
      id: order.id,
      order_number: order.order_number,
      user_email: order.email,
      email: order.email,
      customer_name: customerName,
      currency: order.currency,
      items:
        order.order_items?.map((item: unknown) => ({
          id: item.id,
          name: item.product_name,
          quantity: item.quantity,
          price: item.unit_price,
          variant_title: item.variant_title,
        })) || [],
      total_amount: order.total_amount,
      payment_method: paymentMethod,
      created_at: order.created_at,
      payment_id: order.mp_payment_id,
      status: order.status,
      organization_id: order.organization_id,
    };

    // Send email notification
    const result =
      await sendOrderConfirmation(emailOrder);

    if (!result.success) {
      logger.error("Error sending email", result.error);
      return NextResponse.json(
        { error: "Failed to send notification", details: result.error },
        { status: 500 },
      );
    }

    logger.info("Notification sent successfully", { orderId: params.id });

    return NextResponse.json({
      success: true,
      message: "Notification sent successfully",
    });
  } catch (error) {
    logger.error("Notification API error", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import { rateLimitConfigs, withRateLimit } from "@/lib/rate-limiting";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    return await (withRateLimit(rateLimitConfigs.payment) as unknown)(
      request,
      async () => {
        const { id } = await params;
        const supabase = await createClient();

        // Check admin authorization
        const {
          data: { user },
          error: userError,
        } = await supabase.auth.getUser();
        if (userError || !user) {
          return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        const { data: isAdmin } = (await supabase.rpc("is_admin", {
          user_id: user.id,
        } as IsAdminParams)) as {
          data: IsAdminResult | null;
          error: Error | null;
        };
        if (!isAdmin) {
          return NextResponse.json(
            { error: "Admin access required" },
            { status: 403 },
          );
        }

        // Get branch context
        const branchContext = await getBranchContext(request, user.id);

        // Verify order exists and belongs to branch (if applicable)
        const orderQuery = supabase
          .from("orders")
          .select("id, branch_id")
          .eq("id", id)
          .single();

        const { data: order, error: orderError } = await orderQuery;

        if (orderError || !order) {
          return NextResponse.json(
            { error: "Orden no encontrada" },
            { status: 404 },
          );
        }

        // Check branch access
        if (
          branchContext.branchId &&
          order.branch_id !== branchContext.branchId &&
          !branchContext.isSuperAdmin
        ) {
          return NextResponse.json(
            { error: "No tiene acceso a esta orden" },
            { status: 403 },
          );
        }

        // Get payments for this order
        const { data: payments, error: paymentsError } =
          await supabase
            .from("order_payments")
            .select("*")
            .eq("order_id", id)
            .order("paid_at", { ascending: false });

        if (paymentsError) {
          logger.error("Error fetching payments", paymentsError);
          return NextResponse.json(
            { error: "Error al cargar pagos" },
            { status: 500 },
          );
        }

        return NextResponse.json({
          success: true,
          payments: payments || [],
        });
      },
    );
  } catch (error) {
    logger.error("Error in orders [id] payments GET API", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import {
  createClient,
  createClientFromRequest,
} from "@/utils/supabase/server";

export const dynamic = "force-dynamic";
export async function PATCH(
  request: NextRequest,
  { params }: { params: { id: string } },
) {
  try {
    logger.info("Admin Orders PATCH called for order", { orderId: params.id });
    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    const body = await request.json();
    const { status, payment_status, tracking_number, carrier } = body;

    logger.debug("Updating order with", {
      status,
      payment_status,
      tracking_number,
      carrier,
    });

    // Get current order to check status changes
    const { data: currentOrder } = await supabase
      .from("orders")
      .select("status, shipped_at, delivered_at")
      .eq("id", params.id)
      .single();

    // Build update object dynamically to only update provided fields
    const updateData: {
      updated_at: string;
      status?: string;
      shipped_at?: string;
      delivered_at?: string;
      payment_status?: string;
      tracking_number?: string | null;
      carrier?: string | null;
      [key: string]: unknown;
    } = {
      updated_at: new Date().toISOString(),
    };

    if (status !== undefined) {
      updateData.status = status;

      // Set timestamps for status changes
      if (status === "shipped" && !currentOrder?.shipped_at) {
        updateData.shipped_at = new Date().toISOString();
      }
      if (status === "delivered" && !currentOrder?.delivered_at) {
        updateData.delivered_at = new Date().toISOString();
      }
    }

    if (payment_status !== undefined) {
      updateData.payment_status = payment_status;
    }

    if (tracking_number !== undefined) {
      updateData.tracking_number = tracking_number;
    }

    if (carrier !== undefined) {
      updateData.carrier = carrier;
    }

    // Update the order
    const { data: updatedOrder, error: updateError } = await supabase
      .from("orders")
      .update(updateData)
      .eq("id", params.id)
      .select(
        `
        *,
        order_items (
          id,
          product_name,
          variant_title,
          quantity,
          unit_price,
          total_price
        )
      `,
      )
      .single();

    if (updateError) {
      logger.error("Error updating order", updateError);
      return NextResponse.json(
        { error: "Failed to update order" },
        { status: 500 },
      );
    }

    logger.info("Order updated successfully", { orderId: params.id });

    // Send email notifications based on status changes
    if (status && status !== currentOrder?.status) {
      try {
        // Get full order details for email
        const { data: fullOrder } = await supabase
          .from("orders")
          .select(
            `
            *,
            organization_id,
            order_items (
              id,
              product_name,
              variant_title,
              quantity,
              unit_price,
              total_price
            ),
            profiles (
              id,
              full_name,
              email
            )
          `,
          )
          .eq("id", params.id)
          .single();

        if (fullOrder) {
          // Prepare order data for email service
          const emailOrder = {
            id: fullOrder.id,
            order_number: fullOrder.order_number,
            user_email: fullOrder.email,
            email: fullOrder.email,
            customer_name:
              fullOrder.shipping_first_name && fullOrder.shipping_last_name
                ? `${fullOrder.shipping_first_name} ${fullOrder.shipping_last_name}`
                : fullOrder.profiles?.full_name || "Cliente",
            items:
              fullOrder.order_items?.map(
                (item: {
                  id: string;
                  product_name: string;
                  variant_title?: string | null;
                  quantity: number;
                  unit_price: number;
                  total_price: number;
                }) => ({
                  id: item.id,
                  name: item.product_name,
                  quantity: item.quantity,
                  price: item.unit_price,
                  variant_title: item.variant_title,
                }),
              ) || [],
            total_amount: fullOrder.total_amount,
            payment_method: fullOrder.mp_payment_method || "MercadoPago",
            status: fullOrder.status,
            created_at: fullOrder.created_at,
            payment_id: fullOrder.mp_payment_id,
            tracking_number: fullOrder.tracking_number,
            carrier: fullOrder.carrier,
            shipped_at: fullOrder.shipped_at,
            delivered_at: fullOrder.delivered_at,
            organization_id: fullOrder.organization_id,
            profiles: fullOrder.profiles,
          };

          // Send appropriate email based on status
          // TODO: Habilitar cuando flujo de envío esté implementado
          // if (status === "shipped") {
          //   await EmailNotificationService.sendShippingNotification(emailOrder);
          //   logger.info("Shipping notification email sent", {
          //     orderId: params.id,
          //   });
          // } else if (status === "delivered") {
          //   await EmailNotificationService.sendDeliveryConfirmation(emailOrder);
          //   logger.info("Delivery confirmation email sent", {
          //     orderId: params.id,
          //   });
          // }
        }
      } catch (emailError) {
        logger.warn(
          "Error sending status change email (non-critical)",
          emailError,
        );
        // Don't fail the request if email fails
      }
    }

    return NextResponse.json({
      success: true,
      order: updatedOrder,
    });
  } catch (error) {
    logger.error("Admin order update error", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { id } = await params;
    logger.info("Admin Orders GET single order", { orderId: id });
    const { client: supabase, getUser } =
      await createClientFromRequest(request);

    // Check admin authorization
    const { data, error: userError } = await getUser();
    const user = data?.user;
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    // Get branch context for multi-tenancy
    const branchContext = await getBranchContext(request, user.id, supabase);

    // Get user's organization_id for filtering
    const { data: adminUser } = await supabase
      .from("admin_users")
      .select("organization_id")
      .eq("id", user.id)
      .single();

    const userOrganizationId = (adminUser as unknown)?.organization_id;

    // Get order details
    let query = supabase
      .from("orders")
      .select(
        `
        *,
        order_items (
          id,
          product_id,
          product_name,
          variant_title,
          quantity,
          unit_price,
          total_price
        ),
        order_payments (
          id,
          amount,
          payment_method,
          paid_at,
          notes,
          payment_reference
        )
      `,
      )
      .eq("id", id);

    // Filter by organization_id for multi-tenancy
    if (userOrganizationId && !branchContext.isSuperAdmin) {
      query = query.eq("organization_id", userOrganizationId);
    }

    const { data: order, error: orderError } = await query.single();

    if (orderError) {
      logger.error("Error fetching order", orderError);
      // If order not found or doesn't belong to user's organization, return 404
      if (
        orderError.code === "PGRST116" ||
        orderError.message.includes("No rows")
      ) {
        return NextResponse.json({ error: "Order not found" }, { status: 404 });
      }
      return NextResponse.json(
        { error: "Failed to fetch order" },
        { status: 500 },
      );
    }

    // Additional check: if order exists but doesn't belong to user's organization
    if (
      userOrganizationId &&
      !branchContext.isSuperAdmin &&
      order.organization_id !== userOrganizationId
    ) {
      return NextResponse.json({ error: "Order not found" }, { status: 404 });
    }

    return NextResponse.json({
      success: true,
      data: order,
      order, // backward compatibility for pages using data.order
    });
  } catch (error) {
    logger.error("Admin order fetch error", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

export async function DELETE(
  request: NextRequest,
  { params }: { params: { id: string } },
) {
  try {
    logger.warn("Admin Orders DELETE called for order", { orderId: params.id });
    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    // First, delete all order items for this order
    const { error: itemsError } = await supabase
      .from("order_items")
      .delete()
      .eq("order_id", params.id);

    if (itemsError) {
      logger.error("Error deleting order items", itemsError);
      return NextResponse.json(
        { error: "Failed to delete order items", details: itemsError.message },
        { status: 500 },
      );
    }

    // Then, delete the order
    const { error: orderError } = await supabase
      .from("orders")
      .delete()
      .eq("id", params.id);

    if (orderError) {
      logger.error("Error deleting order", orderError);
      return NextResponse.json(
        { error: "Failed to delete order", details: orderError.message },
        { status: 500 },
      );
    }

    logger.warn("Order deleted successfully", { orderId: params.id });
    return NextResponse.json({
      success: true,
      message: "Order deleted successfully",
    });
  } catch (error) {
    logger.error("Admin order delete error", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

/**
 * API Route: Get Organization Tier Limits
 *
 * Returns the current tier limits and usage for an organization
 */

import { NextRequest, NextResponse } from "next/server";

import { requireAuth } from "@/lib/api/middleware";
import { appLogger as logger } from "@/lib/logger";
import { getTierConfig, SubscriptionTier } from "@/lib/saas/tier-config";
import { validateTierLimit } from "@/lib/saas/tier-validator";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    // Authenticate user
    const { userId } = await requireAuth(request);

    // Get user's organization
    const supabase = await createClient();
    const { data: adminUser, error: adminError } = await supabase
      .from("admin_users")
      .select("organization_id")
      .eq("id", userId)
      .eq("is_active", true)
      .single();

    if (adminError || !adminUser?.organization_id) {
      return NextResponse.json(
        { error: "User does not belong to an organization" },
        { status: 403 },
      );
    }

    const organizationId = adminUser.organization_id;

    // Get organization details
    const { data: organization, error: orgError } = await supabase
      .from("organizations")
      .select("id, name, subscription_tier, status")
      .eq("id", organizationId)
      .single();

    if (orgError || !organization) {
      return NextResponse.json(
        { error: "Organization not found" },
        { status: 404 },
      );
    }

    const tier = organization.subscription_tier as SubscriptionTier;
    const tierConfig = getTierConfig(tier);

    // Get current usage for each limit type
    const [
      branchesValidation,
      usersValidation,
      customersValidation,
      productsValidation,
    ] = await Promise.all([
      validateTierLimit(organizationId, "branches"),
      validateTierLimit(organizationId, "users"),
      validateTierLimit(organizationId, "customers"),
      validateTierLimit(organizationId, "products"),
    ]);

    // Build response
    const limits = {
      tier: {
        name: tierConfig.name,
        tier: tier,
        price: tierConfig.price,
      },
      limits: {
        branches: {
          current: branchesValidation.currentCount,
          max: branchesValidation.maxAllowed,
          available: branchesValidation.allowed,
        },
        users: {
          current: usersValidation.currentCount,
          max: usersValidation.maxAllowed,
          available: usersValidation.allowed,
        },
        customers: {
          current: customersValidation.currentCount,
          max: customersValidation.maxAllowed,
          available: customersValidation.allowed,
        },
        products: {
          current: productsValidation.currentCount,
          max: productsValidation.maxAllowed,
          available: productsValidation.allowed,
        },
      },
      features: tierConfig.features,
      organization: {
        id: organization.id,
        name: organization.name,
        status: organization.status,
      },
    };

    return NextResponse.json(limits);
  } catch (error: unknown) {
    logger.error("Error getting organization limits:", error);
    return NextResponse.json(
      { error: error.message || "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { organizationSlugSchema } from "@/lib/api/validation/organization-schemas";
import { appLogger as logger } from "@/lib/logger";
import { createClient } from "@/utils/supabase/server";

/**
 * GET /api/admin/organizations/check-slug
 *
 * Verifica si un slug está disponible para usar en una nueva organización.
 *
 * Query params:
 * - slug: string (requerido) - El slug a verificar
 *
 * Returns:
 * - { available: boolean, slug: string }
 */
export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    const supabase = await createClient();

    // Verificar autenticación
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user) {
      return NextResponse.json({ error: "No autenticado" }, { status: 401 });
    }

    // Obtener slug de query params
    const { searchParams } = new URL(request.url);
    const slug = searchParams.get("slug");

    if (!slug) {
      return NextResponse.json(
        { error: "El parámetro 'slug' es requerido" },
        { status: 400 },
      );
    }

    // Validar formato del slug
    const validationResult = organizationSlugSchema.safeParse(slug);
    if (!validationResult.success) {
      return NextResponse.json(
        {
          available: false,
          slug,
          error:
            validationResult.error.errors[0]?.message ||
            "Formato de slug inválido",
        },
        { status: 400 },
      );
    }

    const normalizedSlug = validationResult.data;

    // Verificar si el slug ya existe
    const { data: existingOrg, error: checkError } = await supabase
      .from("organizations")
      .select("id, slug")
      .eq("slug", normalizedSlug)
      .single();

    if (checkError && checkError.code !== "PGRST116") {
      // PGRST116 = no rows returned (slug disponible)
      logger.error("Error checking slug availability", checkError);
      return NextResponse.json(
        { error: "Error al verificar disponibilidad del slug" },
        { status: 500 },
      );
    }

    const available = !existingOrg;

    return NextResponse.json({
      available,
      slug: normalizedSlug,
    });
  } catch (error) {
    logger.error("Error in check-slug endpoint", { error });
    return NextResponse.json(
      { error: "Error interno del servidor" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { createApiSuccessResponse } from "@/lib/api/response";
import { appLogger as logger } from "@/lib/logger";
import { createClient } from "@/utils/supabase/server";

/**
 * GET /api/admin/organizations/current
 * Obtiene la información completa de la organización del usuario actual
 */
export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    const supabase = await createClient();

    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    // Obtener organization_id del usuario
    const { data: adminUser } = await supabase
      .from("admin_users")
      .select("organization_id")
      .eq("id", user.id)
      .maybeSingle();

    if (!adminUser?.organization_id) {
      return NextResponse.json(
        { error: "No tienes una organización asignada" },
        { status: 404 },
      );
    }

    // Obtener información completa de la organización
    const { data: organization, error: orgError } = await supabase
      .from("organizations")
      .select(
        "id, name, slug, logo_url, slogan, subscription_tier, status, metadata",
      )
      .eq("id", adminUser.organization_id)
      .single();

    if (orgError || !organization) {
      logger.error("Error fetching organization", orgError);
      return NextResponse.json(
        { error: "Error al obtener información de la organización" },
        { status: 500 },
      );
    }

    return createApiSuccessResponse(organization);
  } catch (error) {
    logger.error("Error in GET /api/admin/organizations/current", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

/**
 * PATCH /api/admin/organizations/current
 * Actualiza la información de la organización del usuario actual
 * Permite actualizar: name, logo_url, slogan
 */
export async function PATCH(request: NextRequest) {
  try {
    const supabase = await createClient();

    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    // Verificar que el usuario es admin
    const { data: isAdmin } = await supabase.rpc("is_admin", {
      user_id: user.id,
    });
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    // Obtener organization_id del usuario
    const { data: adminUser } = await supabase
      .from("admin_users")
      .select("organization_id")
      .eq("id", user.id)
      .maybeSingle();

    if (!adminUser?.organization_id) {
      return NextResponse.json(
        { error: "No tienes una organización asignada" },
        { status: 404 },
      );
    }

    const body = await request.json();
    const { name, logo_url, slogan, metadata } = body;

    // Preparar updates
    const updates: Record<string, unknown> = {};
    if (name !== undefined) updates.name = name;
    if (logo_url !== undefined) updates.logo_url = logo_url;
    if (slogan !== undefined) updates.slogan = slogan;
    if (metadata !== undefined) {
      const { data: currentOrg } = await supabase
        .from("organizations")
        .select("metadata")
        .eq("id", adminUser.organization_id)
        .single();
      const currentMeta =
        (currentOrg?.metadata as Record<string, unknown>) || {};
      updates.metadata = { ...currentMeta, ...metadata };
    }

    if (Object.keys(updates).length === 0) {
      return NextResponse.json(
        { error: "No se proporcionaron campos para actualizar" },
        { status: 400 },
      );
    }

    // Actualizar organización
    const { data: updatedOrg, error: updateError } = await supabase
      .from("organizations")
      .update(updates)
      .eq("id", adminUser.organization_id)
      .select(
        "id, name, slug, logo_url, slogan, subscription_tier, status, metadata",
      )
      .single();

    if (updateError) {
      logger.error("Error updating organization", updateError);
      return NextResponse.json(
        {
          error: "Error al actualizar la organización",
          details: updateError.message,
        },
        { status: 500 },
      );
    }

    logger.info(`Organization updated: ${adminUser.organization_id}`);

    return createApiSuccessResponse(updatedOrg);
  } catch (error) {
    logger.error("Error in PATCH /api/admin/organizations/current", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { createOrganizationSchema } from "@/lib/api/validation/organization-schemas";
import {
  parseAndValidateBody,
  ValidationError,
  validationErrorResponse,
} from "@/lib/api/validation/zod-helpers";
import { appLogger as logger } from "@/lib/logger";
import { createRootAdminClient } from "@/utils/supabase/root-admin";
import { createClient } from "@/utils/supabase/server";

export async function handleGET(request: NextRequest) {
  try {
    const supabase = await createClient();
    const supabaseServiceRole = createRootAdminClient();
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user || !user.email)
      return NextResponse.json({ error: "No autenticado" }, { status: 401 });

    const { data: adminUser } = await supabaseServiceRole
      .from("admin_users")
      .select("organization_id")
      .eq("id", user.id)
      .maybeSingle();
    if (!adminUser?.organization_id)
      return NextResponse.json(
        { error: "No tienes una organización asignada" },
        { status: 404 },
      );

    const { data: organization, error: orgError } = await supabaseServiceRole
      .from("organizations")
      .select("id, name, slug, logo_url, slogan, subscription_tier, status")
      .eq("id", adminUser.organization_id)
      .single();
    if (orgError || !organization)
      return NextResponse.json(
        { error: "Error al obtener información de la organización" },
        { status: 500 },
      );

    return NextResponse.json({
      organization: {
        id: organization.id,
        name: organization.name,
        slug: organization.slug,
        logo_url: organization.logo_url,
        slogan: organization.slogan,
        subscription_tier: organization.subscription_tier,
        status: organization.status,
      },
    });
  } catch (error) {
    logger.error("Error in GET /api/admin/organizations", error);
    return NextResponse.json(
      { error: "Error interno del servidor" },
      { status: 500 },
    );
  }
}

export async function handlePOST(request: NextRequest) {
  try {
    const supabase = await createClient();
    const supabaseServiceRole = createRootAdminClient();
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user || !user.email)
      return NextResponse.json({ error: "No autenticado" }, { status: 401 });

    const isDevelopment = process.env.NODE_ENV === "development";
    if (!isDevelopment && !user.email_confirmed_at)
      return NextResponse.json(
        { error: "Debes confirmar tu email antes de continuar" },
        { status: 403 },
      );

    let validatedBody;
    try {
      validatedBody = await parseAndValidateBody(
        request,
        createOrganizationSchema,
      );
    } catch (error) {
      if (error instanceof ValidationError)
        return validationErrorResponse(error);
      throw error;
    }

    const { name, slug, subscription_tier, branchName } = validatedBody;

    const { data: existingAdminUser } = await supabaseServiceRole
      .from("admin_users")
      .select("organization_id")
      .eq("id", user.id)
      .maybeSingle();
    if (existingAdminUser?.organization_id)
      return NextResponse.json(
        {
          error: "Ya tienes una organización asignada",
          organizationId: existingAdminUser.organization_id,
        },
        { status: 400 },
      );

    const { data: existingOrg } = await supabaseServiceRole
      .from("organizations")
      .select("id")
      .eq("slug", slug)
      .maybeSingle();
    if (existingOrg)
      return NextResponse.json(
        { error: "Ese identificador ya está en uso. Elige otro." },
        { status: 400 },
      );

    const { data: newOrganization, error: orgError } = await supabaseServiceRole
      .from("organizations")
      .insert({
        name,
        slug,
        owner_id: user.id,
        subscription_tier,
        status: "active",
      })
      .select()
      .single();
    if (orgError || !newOrganization)
      return NextResponse.json(
        { error: "Error al crear la organización" },
        { status: 500 },
      );

    const organizationId = newOrganization.id;
    const adminUserData = {
      id: user.id,
      email: user.email,
      role: "super_admin",
      organization_id: organizationId,
      is_active: true,
      permissions: {
        orders: ["read", "create", "update", "delete"],
        products: ["read", "create", "update", "delete"],
        customers: ["read", "create", "update", "delete"],
        analytics: ["read"],
        settings: ["read", "create", "update", "delete"],
        admin_users: ["read", "create", "update", "delete"],
        support: ["read", "create", "update", "delete"],
        bulk_operations: ["read", "create", "update", "delete"],
        branches: ["read", "create", "update", "delete"],
      },
    };
    const { data: adminUser, error: adminError } = await supabaseServiceRole
      .from("admin_users")
      .upsert(adminUserData, { onConflict: "id" })
      .select()
      .single();
    if (adminError || !adminUser) {
      await supabaseServiceRole
        .from("organizations")
        .delete()
        .eq("id", organizationId);
      return NextResponse.json(
        { error: "Error al asignar organización al usuario" },
        { status: 500 },
      );
    }

    const finalBranchName = branchName || "Sucursal Principal";
    const branchCode = `${slug.toUpperCase().substring(0, 8)}-001`;
    const { data: newBranch } = await supabaseServiceRole
      .from("branches")
      .insert({
        name: finalBranchName,
        code: branchCode,
        organization_id: organizationId,
        is_active: true,
      })
      .select()
      .single();

    if (newBranch) {
      await supabaseServiceRole
        .from("admin_branch_access")
        .insert({
          admin_user_id: user.id,
          branch_id: null,
          role: "manager",
          is_primary: true,
        });
      await supabaseServiceRole
        .from("admin_branch_access")
        .insert({
          admin_user_id: user.id,
          branch_id: newBranch.id,
          role: "manager",
          is_primary: false,
        });
    }

    let trialDays = 7;
    const { data: trialConfig } = await supabaseServiceRole
      .from("system_config")
      .select("config_value")
      .eq("config_key", "membership_trial_days")
      .maybeSingle();
    if (trialConfig?.config_value != null) {
      const parsed = parseInt(
        String(trialConfig.config_value).replace(/"/g, ""),
        10,
      );
      if (!isNaN(parsed) && parsed > 0) trialDays = parsed;
    }
    const trialEndsAt = new Date();
    trialEndsAt.setDate(trialEndsAt.getDate() + trialDays);
    await supabaseServiceRole
      .from("subscriptions")
      .insert({
        organization_id: organizationId,
        status: "trialing",
        trial_ends_at: trialEndsAt.toISOString(),
        current_period_end: trialEndsAt.toISOString().split("T")[0],
      });

    return NextResponse.json({
      organization: {
        id: newOrganization.id,
        name: newOrganization.name,
        slug: newOrganization.slug,
        subscription_tier: newOrganization.subscription_tier,
      },
      branch: newBranch
        ? { id: newBranch.id, name: newBranch.name, code: newBranch.code }
        : null,
    });
  } catch (error) {
    logger.error("Error in POST /api/admin/organizations", {
      error,
      message: error instanceof Error ? error.message : "Unknown error",
    });
    return NextResponse.json(
      { error: "Error interno del servidor" },
      { status: 500 },
    );
  }
}

/**
 * POST /api/admin/payments/create-intent
 * Creates a payment intent (Flow order, Mercado Pago preference, PayPal order, etc.) and a payment record in DB.
 * Requires admin auth and organization context.
 */

import { NextRequest, NextResponse } from "next/server";

import { ValidationError } from "@/lib/api/errors";
import {
  parseAndValidateBody,
  validationErrorResponse,
} from "@/lib/api/validation/zod-helpers";
import { createPaymentIntentSchema } from "@/lib/api/validation/zod-schemas";
import { appLogger as logger } from "@/lib/logger";
import type { PaymentGatewayType } from "@/lib/payments";
import { PaymentGatewayFactory, PaymentService } from "@/lib/payments";
import { rateLimitConfigs, withRateLimit } from "@/lib/rate-limiting";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClientFromRequest } from "@/utils/supabase/server";

const paymentRateLimitConfig =
  process.env.NODE_ENV === "development"
    ? { ...rateLimitConfigs.payment, maxRequests: 50 }
    : rateLimitConfigs.payment;

export const dynamic = "force-dynamic";
export async function POST(request: NextRequest) {
  return (
    withRateLimit(paymentRateLimitConfig) as (
      req: NextRequest,
      handler: () => Promise<NextResponse>,
    ) => Promise<NextResponse>
  )(request, async () => {
    try {
      logger.info("Payments create-intent API called");

      const { client: supabase, getUser } =
        await createClientFromRequest(request);

      const { data: userData, error: userError } = await getUser();
      const user = userData?.user;
      if (userError || !user) {
        logger.error("User authentication failed", userError);
        return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
      }

      const { data: isAdmin, error: adminError } = (await supabase.rpc(
        "is_admin",
        { user_id: user.id } as IsAdminParams,
      )) as { data: IsAdminResult | null; error: Error | null };
      if (adminError || !isAdmin) {
        logger.warn("Admin check failed or user is not admin", { adminError });
        return NextResponse.json(
          { error: "Admin access required" },
          { status: 403 },
        );
      }

      const { data: adminUser, error: adminUserError } = await supabase
        .from("admin_users")
        .select("organization_id")
        .eq("id", user.id)
        .single();

      const orgId =
        adminUser && "organization_id" in adminUser
          ? (adminUser as { organization_id: string | null }).organization_id
          : null;
      if (adminUserError || !orgId) {
        logger.warn("User has no organization_id", { adminUserError });
        return NextResponse.json(
          {
            error:
              "Organization context required for payments. Your user must belong to an organization.",
          },
          { status: 403 },
        );
      }

      const organizationId = orgId;

      let body: {
        amount: number;
        currency: string;
        gateway: PaymentGatewayType;
        order_id?: string | null;
      };
      try {
        body = await parseAndValidateBody(request, createPaymentIntentSchema);
      } catch (error) {
        if (error instanceof ValidationError) {
          return validationErrorResponse(error);
        }
        throw error;
      }

      const { amount, currency, gateway, order_id: orderId } = body;

      const paymentService = new PaymentService(supabase);
      const gatewayInstance = PaymentGatewayFactory.getGateway(gateway);

      const paymentRecord = await paymentService.createPayment({
        order_id: orderId ?? null,
        organization_id: organizationId,
        user_id: user.id,
        amount,
        currency,
        status: "pending",
        gateway,
      });

      const intentResponse = await gatewayInstance.createPaymentIntent(
        orderId ?? null,
        amount,
        currency,
        user.id,
        organizationId,
      );

      await paymentService.updatePaymentStatus(
        paymentRecord.id,
        intentResponse.status,
        undefined,
        undefined,
        intentResponse.gatewayPaymentIntentId,
      );

      return NextResponse.json({
        paymentId: paymentRecord.id,
        clientSecret: intentResponse.clientSecret,
        preferenceId: intentResponse.preferenceId,
        approvalUrl: intentResponse.approvalUrl,
        gatewayPaymentIntentId: intentResponse.gatewayPaymentIntentId,
        status: intentResponse.status,
      });
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : typeof error === "object" && error !== null && "message" in error
            ? String((error as { message: unknown }).message)
            : "Internal server error";
      logger.error(
        "Payments create-intent error",
        error instanceof Error ? error : new Error(message),
      );
      return NextResponse.json(
        {
          error:
            typeof message === "string" ? message : "Internal server error",
        },
        { status: 500 },
      );
    }
  });
}

import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { ValidationError } from "@/lib/api/errors";
import { createApiSuccessResponse } from "@/lib/api/response";
import {
  parseAndValidateBody,
  validationErrorResponse,
} from "@/lib/api/validation/zod-helpers";
import { pendingBalancePaySchema } from "@/lib/api/validation/zod-schemas";
import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

/**
 * POST /api/admin/pos/pending-balance/pay
 * Record payment for pending balance order
 */
export const dynamic = "force-dynamic";
export async function POST(request: NextRequest) {
  try {
    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    // Get branch context
    const branchContext = await getBranchContext(request, user.id);

    let body: z.infer<typeof pendingBalancePaySchema>;
    try {
      body = await parseAndValidateBody(request, pendingBalancePaySchema);
    } catch (error) {
      if (error instanceof ValidationError) {
        return validationErrorResponse(error);
      }
      throw error;
    }

    const {
      order_id,
      payment_amount,
      payment_method,
      notes,
      fiscal_reference,
    } = body;

    // Get order with branch filter
    let orderQuery = supabase
      .from("orders")
      .select(
        `
        id,
        order_number,
        total_amount,
        payment_status,
        branch_id,
        order_payments (
          id,
          amount
        )
      `,
      )
      .eq("id", order_id);

    // Apply branch filter if branch is selected
    if (branchContext.branchId) {
      orderQuery = orderQuery.eq("branch_id", branchContext.branchId);
    }

    const { data: order, error: orderError } = await orderQuery.single();

    if (orderError || !order) {
      logger.error("Error fetching order", {
        error: orderError,
        order_id,
        branchId: branchContext.branchId,
      });
      return NextResponse.json({ error: "Order not found" }, { status: 404 });
    }

    // Calculate total paid so far
    const totalPaid = (order.order_payments || []).reduce(
      (sum: number, payment: unknown) => sum + (payment.amount || 0),
      0,
    );
    const newTotal = totalPaid + payment_amount;
    const stillPending = order.total_amount > newTotal;

    // Get current POS session for this branch (simplified to find ANY open session)
    let posSessionId = null;
    if (branchContext.branchId) {
      const { data: openSession } = await supabase
        .from("pos_sessions")
        .select("id")
        .eq("branch_id", branchContext.branchId)
        .eq("status", "open")
        .order("opening_time", { ascending: false })
        .limit(1)
        .maybeSingle();

      if (openSession) {
        posSessionId = openSession.id;
      }
    } else if (branchContext.isSuperAdmin) {
      // For super admin in global view, try to find any open session
      // This is a fallback and might not be accurate if multiple branches have open sessions
      const { data: activeSession } = await supabase
        .from("pos_sessions")
        .select("id")
        .eq("status", "open")
        .order("opening_time", { ascending: false })
        .limit(1)
        .maybeSingle();

      if (activeSession) {
        posSessionId = activeSession.id;
      }
    }

    // Create payment record
    const { data: payment, error: paymentError } = await supabase
      .from("order_payments")
      .insert({
        order_id: order_id,
        amount: payment_amount,
        payment_method: payment_method,
        pos_session_id: posSessionId, // Asociar pago a la sesión de caja actual
        payment_reference: fiscal_reference?.trim() || null,
        paid_at: new Date().toISOString(),
        created_by: user.id,
        notes: notes || "Pago de saldo pendiente",
      })
      .select()
      .single();

    if (paymentError) {
      logger.error("Error creating payment", paymentError);
      return NextResponse.json(
        {
          error: "Error al registrar pago",
          details: paymentError.message,
        },
        { status: 500 },
      );
    }

    // Update order payment status
    let newPaymentStatus = order.payment_status;
    if (!stillPending && newTotal >= order.total_amount) {
      newPaymentStatus = "paid";
    } else if (
      stillPending &&
      newPaymentStatus !== "partial" &&
      newPaymentStatus !== "on_hold_payment"
    ) {
      // Ensure status is partial if there's still pending amount
      newPaymentStatus = "partial";
    }

    const { error: updateOrderError } = await supabase
      .from("orders")
      .update({
        payment_status: newPaymentStatus,
        updated_at: new Date().toISOString(),
      })
      .eq("id", order_id);

    if (updateOrderError) {
      logger.error("Error updating order", updateOrderError);
      // Don't fail, log the error
    }

    // Update associated work orders if exists (work_orders have pos_order_id that references orders)
    const { data: workOrders } = await supabase
      .from("lab_work_orders")
      .select(
        "id, status, total_amount, deposit_amount, balance_amount, payment_status",
      )
      .eq("pos_order_id", order_id);

    if (workOrders && workOrders.length > 0) {
      // Calculate new values for each work order
      // The work order total should match the order total, so we use the same calculation
      const newPendingAmount = Math.max(0, order.total_amount - newTotal);
      const newDepositAmount = newTotal; // Total paid so far

      // Determine new payment status for work orders
      const newWorkOrderPaymentStatus =
        newPaymentStatus === "paid" ? "paid" : "partial";

      // Update all work orders with new payment information
      for (const workOrder of workOrders) {
        const updateData: unknown = {
          deposit_amount: newDepositAmount,
          balance_amount: newPendingAmount,
          payment_status: newWorkOrderPaymentStatus,
          updated_at: new Date().toISOString(),
        };

        // Only update status to delivered if payment is complete
        if (newPaymentStatus === "paid") {
          updateData.status = "delivered";
        }

        const { error: updateWorkOrderError } = await supabase
          .from("lab_work_orders")
          .update(updateData)
          .eq("id", workOrder.id);

        if (updateWorkOrderError) {
          logger.error("Error updating work order", {
            error: updateWorkOrderError,
            work_order_id: workOrder.id,
            order_id,
          });
          // Don't fail, log the error and continue with other work orders
        } else {
          logger.info("Work order updated with payment", {
            work_order_id: workOrder.id,
            new_deposit_amount: newDepositAmount,
            new_balance_amount: newPendingAmount,
            new_payment_status: newWorkOrderPaymentStatus,
            order_id,
          });
        }
      }
    }

    logger.info("Pending balance payment recorded", {
      order_id,
      payment_amount,
      payment_method,
      new_status: newPaymentStatus,
    });

    return createApiSuccessResponse({
      payment,
      order_status: newPaymentStatus,
      message: stillPending
        ? "Pago registrado. Saldo aún pendiente"
        : "Pago completado. Orden finalizada",
    });
  } catch (error: unknown) {
    logger.error("Error in pending balance payment API", { error });
    return NextResponse.json(
      {
        error: "Internal server error",
        details: error.message,
      },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { createApiSuccessResponse } from "@/lib/api/response";
import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

/**
 * GET /api/admin/pos/pending-balance
 * Get orders with pending balance for payment collection
 */
export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    // Get branch context
    const branchContext = await getBranchContext(request, user.id);

    // Validate branch access
    if (!branchContext.branchId && !branchContext.isSuperAdmin) {
      return NextResponse.json(
        { error: "Debe seleccionar una sucursal" },
        { status: 400 },
      );
    }

    const url = new URL(request.url);
    const searchTerm = url.searchParams.get("search") || "";
    const limit = parseInt(url.searchParams.get("limit") || "500");

    // Query for orders with pending balance (payment_status = 'partial' or 'on_hold_payment')
    // Exclude cancelled/refunded orders (they should not appear after devolution)
    // NOTE: We don't include customers/work_orders relationships here because they may not exist
    let query = supabase
      .from("orders")
      .select(
        `
        id,
        order_number,
        email,
        user_id,
        branch_id,
        total_amount,
        payment_status,
        status,
        created_at,
        order_payments (
          id,
          amount,
          payment_method
        )
      `,
      )
      .in("payment_status", ["partial", "on_hold_payment"])
      .neq("status", "cancelled")
      .order("created_at", { ascending: false })
      .limit(limit);

    // Apply branch filter
    if (branchContext.branchId) {
      query = query.eq("branch_id", branchContext.branchId);
    }

    // Apply search filter - search across main order fields only
    // NOTE: We don't use Supabase .or() filter - filter in-memory instead for reliability
    // if (searchTerm && searchTerm.trim()) {
    //   query = query.or(
    //     `order_number.ilike.%${searchTerm.trim()}%,email.ilike.%${searchTerm.trim()}%`,
    //   );
    // }

    const { data: orders, error: ordersError } = await query;

    if (ordersError) {
      logger.error("[PENDING-BALANCE-API] Supabase error:", {
        message: ordersError.message,
        code: ordersError.code,
        details: ordersError,
      });
      logger.error("Error fetching pending balance orders", ordersError);
      return NextResponse.json(
        {
          error: "Error al obtener órdenes con saldo pendiente",
          details: ordersError.message,
        },
        { status: 500 },
      );
    }

    // Fetch customer information for search and display
    const uniqueEmails = [
      ...new Set((orders || []).map((o: unknown) => o.email).filter(Boolean)),
    ];
    const customerMapByEmail = new Map();
    const { data: customersByEmail } =
      uniqueEmails.length > 0
        ? await supabase
            .from("customers")
            .select("id, email, first_name, last_name, rut")
            .in("email", uniqueEmails)
            .returns<{ id: string; email: string; first_name: string | null; last_name: string | null; rut: string | null }[]>()
        : { data: null };

    (customersByEmail || []).forEach((customer: unknown) => {
      if (customer.email) {
        customerMapByEmail.set(customer.email.toLowerCase(), customer);
      }
    });

    // Filter results by related data if search term is provided
    let filteredOrders = orders || [];
    if (searchTerm) {
      const searchLower = searchTerm.toLowerCase();
      try {
        filteredOrders = filteredOrders.filter((order: unknown) => {
          // Check main fields
          if (
            order.order_number?.toLowerCase().includes(searchLower) ||
            order.email?.toLowerCase().includes(searchLower)
          ) {
            return true;
          }

          // Check customer info from map (orders use email, not customer_id)
          const customer =
            (order.email &&
              customerMapByEmail.get(order.email.toLowerCase())) ||
            null;
          if (customer) {
            const fullName =
              `${customer.first_name || ""} ${customer.last_name || ""}`.toLowerCase();
            const rut = (customer.rut || "").toLowerCase();
            if (
              fullName.includes(searchLower) ||
              rut.includes(searchLower) ||
              (customer.email || "").toLowerCase().includes(searchLower)
            ) {
              return true;
            }
          }

          return false;
        });
      } catch (filterError) {
        logger.error("[PENDING-BALANCE-API] Filter error:", filterError);
        throw filterError;
      }
    }

    // Calculate pending amount for each order using customer info already fetched
    let ordersWithBalance: unknown[] = [];
    try {
      ordersWithBalance = filteredOrders.map((order: unknown) => {
        const totalPaid = (order.order_payments || []).reduce(
          (sum: number, payment: unknown) => sum + (payment.amount || 0),
          0,
        );
        const pendingAmount = Math.max(0, order.total_amount - totalPaid);

        // Get customer info from map (orders use email, not customer_id)
        const customer = order.email
          ? customerMapByEmail.get(order.email.toLowerCase())
          : null;
        const customerName = customer
          ? `${customer.first_name || ""} ${customer.last_name || ""}`.trim() ||
            order.email
          : order.email || "Sin nombre";
        const customerRUT = customer?.rut || null;

        return {
          id: order.id,
          order_number: order.order_number,
          branch_id: order.branch_id,
          customer_email: order.email,
          customer_name: customerName,
          customer_rut: customerRUT,
          total_amount: order.total_amount,
          total_paid: totalPaid,
          pending_amount: pendingAmount,
          payment_status: order.payment_status,
          created_at: order.created_at,
          work_orders: [],
        };
      });
    } catch (mapError) {
      logger.error("[PENDING-BALANCE-API] Map error:", mapError);
      throw mapError;
    }

    logger.debug("Pending balance orders fetched", {
      count: ordersWithBalance.length,
      branch: branchContext.branchId,
    });

    return createApiSuccessResponse(ordersWithBalance);
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : "Unknown error";
    logger.error("[PENDING-BALANCE-API] Catch block error:", {
      message,
      stack: error instanceof Error ? error.stack : undefined,
      name: error instanceof Error ? error.name : undefined,
    });
    logger.error("Error in pending balance API", {
      error: message,
      stack: error instanceof Error ? error.stack : undefined,
    });
    return NextResponse.json(
      {
        error: "Internal server error",
        details: message,
      },
      { status: 500 },
    );
  }
}

/**
 * Process Auth & Session — auth check, branch context, SII invoice, POS session.
 *
 * Extracted from processSaleHandler.ts. No behavioral changes.
 */

import { NextRequest, NextResponse } from "next/server";

import { getBranchContext, getFieldOperationFromRequest } from "@/lib/api/branch-middleware";
import { createClient } from "@/utils/supabase/server";

export interface AuthSessionResult {
  user: { id: string; email?: string };
  effectiveBranchId: string | null;
  fieldOperationId: string | null;
  posSessionId: string | null;
  siiInvoiceNumber: string | null;
  branchContext: {
    branchId: string | null;
    organizationId: string | null;
    isSuperAdmin: boolean;
    isGlobalView: boolean;
    accessibleBranches: { id: string }[];
  };
}

export async function handleAuthSession(
  request: NextRequest,
  validatedBody: Record<string, unknown>,
): Promise<AuthSessionResult | NextResponse> {
  const supabase = await createClient();

  // Check admin authorization
  const {
    data: { user },
    error: userError,
  } = await supabase.auth.getUser();
  if (userError || !user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 }) as NextResponse;
  }

  const { data: isAdmin } = (await supabase.rpc("is_admin", {
    user_id: user.id,
  } as Record<string, unknown>)) as { data: boolean | null };
  if (!isAdmin) {
    return NextResponse.json({ error: "Admin access required" }, { status: 403 }) as NextResponse;
  }

  // Branch context
  const branchContext = await getBranchContext(request, user.id);
  const fieldOperationId: string | null = getFieldOperationFromRequest(request);
  let effectiveBranchId = branchContext.branchId;

  if (fieldOperationId) {
    const { data: fieldOp, error: fieldOpError } = await supabase
      .from("field_operations")
      .select("id, branch_id, organization_id")
      .eq("id", fieldOperationId)
      .single();

    if (fieldOpError || !fieldOp) {
      return NextResponse.json(
        { error: "Operativo no encontrado" },
        { status: 404 },
      ) as NextResponse;
    }
    const fieldOpRecord = fieldOp as { id: string; branch_id: string; organization_id: string };
    if (branchContext.organizationId && fieldOpRecord.organization_id !== branchContext.organizationId) {
      return NextResponse.json(
        { error: "No tiene acceso a este operativo" },
        { status: 403 },
      ) as NextResponse;
    }
    effectiveBranchId = fieldOpRecord.branch_id;
    if (!branchContext.isSuperAdmin &&
      !branchContext.accessibleBranches.some((b: { id: string }) => b.id === fieldOpRecord.branch_id)) {
      return NextResponse.json(
        { error: "No tiene acceso a la sucursal del operativo" },
        { status: 403 },
      ) as NextResponse;
    }
  }

  if (!branchContext.isSuperAdmin && !effectiveBranchId) {
    return NextResponse.json(
      { error: "Debe seleccionar una sucursal para realizar ventas POS" },
      { status: 400 },
    ) as NextResponse;
  }

  // SII invoice number
  const sii_invoice_type = validatedBody.sii_invoice_type as string | undefined;
  let siiInvoiceNumber: string | null = null;
  if (sii_invoice_type && sii_invoice_type !== "none") {
    const { data: invoiceNum } = await supabase.rpc("generate_sii_invoice_number", {
      invoice_type: sii_invoice_type,
    });
    if (invoiceNum) siiInvoiceNumber = invoiceNum as string;
  }

  // POS session validation
  const fieldOperationIdFromBody = validatedBody.field_operation_id as string | null;
  let posSessionId: string | null = null;
  if (!branchContext.isSuperAdmin && effectiveBranchId) {
    const todayStart = new Date().toISOString().slice(0, 10);
    let sessionQuery = supabase
      .from("pos_sessions")
      .select("id")
      .eq("branch_id", effectiveBranchId)
      .eq("status", "open")
      .gte("opening_time", todayStart);
    if (fieldOperationIdFromBody) {
      sessionQuery = sessionQuery.eq("field_operation_id", fieldOperationIdFromBody);
    } else {
      sessionQuery = sessionQuery.is("field_operation_id", null);
    }
    const { data: openSession } = await sessionQuery.maybeSingle();
    if (!openSession) {
      return NextResponse.json(
        {
          error: fieldOperationIdFromBody
            ? "Debe abrir la caja del operativo antes de realizar ventas. Abra la caja desde la página del operativo."
            : "Debe abrir la caja antes de realizar ventas. Por favor, abra la caja desde la sección Caja.",
        },
        { status: 400 },
      ) as NextResponse;
    }
    posSessionId = (openSession as { id: string }).id;
  } else {
    let query = supabase
      .from("pos_sessions")
      .select("id")
      .eq("cashier_id", user.id)
      .eq("status", "open");
    query = effectiveBranchId
      ? query.eq("branch_id", effectiveBranchId).eq("field_operation_id", fieldOperationIdFromBody || null)
      : query.is("branch_id", null);
    const { data: activeSession } = await query
      .order("opening_time", { ascending: false })
      .limit(1)
      .maybeSingle();
    if (activeSession) {
      posSessionId = (activeSession as { id: string }).id;
    } else if (branchContext.isSuperAdmin) {
      const { data: newSession } = await supabase
        .from("pos_sessions")
        .insert({
          cashier_id: user.id,
          branch_id: effectiveBranchId,
          opening_cash_amount: 0,
          status: "open",
        })
        .select()
        .single();
      if (newSession) posSessionId = (newSession as { id: string }).id;
    }
  }

  return {
    user,
    effectiveBranchId,
    fieldOperationId,
    posSessionId,
    siiInvoiceNumber,
    branchContext: {
      branchId: branchContext.branchId,
      organizationId: branchContext.organizationId,
      isSuperAdmin: branchContext.isSuperAdmin,
      isGlobalView: branchContext.isGlobalView,
      accessibleBranches: branchContext.accessibleBranches,
    },
  };
}

/**
 * Legacy path handler for process-sale.
 *
 * Extracted from route.ts `else` branch. Uses sequential inserts for
 * operativo/mobile-stock sales. Now delegates to focused sub-modules:
 * - processLegacyOrderCreate.ts  → order, items, payments, POS transaction
 * - processLegacyWorkOrder.ts    → work order creation, billing, notifications
 * - processResponseBuilder.ts    → response construction
 * - processPaymentUtils.ts       → amount/status computation
 */
import { NextResponse } from "next/server";

import {
  createApiErrorResponse,
  createApiSuccessResponse,
} from "@/lib/api/response";
import { BillingFactory } from "@/lib/billing/BillingFactory";
import { appLogger as logger } from "@/lib/logger";

import { createLegacyOrder } from "./processLegacyOrderCreate";
import {
  createLegacyWorkOrder,
  handleNonWorkOrderPath,
  sendWorkOrderNotifications,
  updateQuoteStatus,
} from "./processLegacyWorkOrder";
import type { OrderItem } from "./processResponseBuilder";
import { buildBillingOrder, buildBillingResponse, buildFullOrderResponse } from "./processResponseBuilder";
import type { ProcessSaleContext } from "./processSaleTypes";
import { reduceContactLensStock,reduceStock } from "./processStockReduction";

export async function handleLegacyPath(
  ctx: ProcessSaleContext,
): Promise<NextResponse> {
  // 1. Create order + items + payments + POS transaction
  const newOrder = await createLegacyOrder(ctx);
  if (!newOrder) {
    return NextResponse.json(
      { error: "Failed to create order", details: "Order creation returned null" },
      { status: 500 },
    );
  }

  // 2. Emit billing document
  let billingResult: Record<string, unknown> | null = null;
  try {
    const billingConfig = await BillingFactory.getBillingConfig(
      ctx.effectiveBranchId || "",
    );
    const billingAdapter = BillingFactory.createAdapter(billingConfig);

    let ocNumber: string | null = null;
    if (ctx.purchase_order_id && ctx.purchaseOrder) {
      const { data: po } = await ctx.supabase
        .from("agreement_purchase_orders")
        .select("oc_number")
        .eq("id", ctx.purchase_order_id)
        .single();
      ocNumber = (po as Record<string, unknown> | null)?.oc_number as string | null;
    }

    const billingOrder = buildBillingOrder({
      orderId: newOrder.id as string,
      orderNumber: newOrder.order_number as string,
      customerId: ctx.customer_id,
      branchId: ctx.effectiveBranchId ?? "",
      totalAmount: ctx.total_amount,
      subtotal: ctx.subtotal,
      taxAmount: ctx.tax_amount || 0,
      items: ctx.orderItems as unknown as OrderItem[],
      customer: ctx.customer as Record<string, unknown> | null,
      createdAt: newOrder.created_at as string,
      ocNumber,
      purchaseOrderId: ctx.purchase_order_id,
      agreementId: ctx.agreement_id,
      customerName: ctx.customer_name,
      email: ctx.email,
      customerRut: ctx.customer_rut,
      siiBusinessName: ctx.sii_business_name,
    });

    billingResult = (await billingAdapter.emitDocument(billingOrder)) as unknown as Record<string, unknown>;
    logger.info("Billing document emitted", {
      folio: billingResult?.folio,
      type: billingResult?.type,
    });
  } catch (billingError) {
    logger.error("Error emitting billing document", billingError);
  }

  // 3. Stock reduction
  const stockOk = await reduceStock(ctx, newOrder.id as string);
  if (!stockOk) {
    return createApiErrorResponse(
      new (await import("@/lib/api/errors")).APIError(
        "Error al actualizar stock",
        400,
        "INSUFFICIENT_STOCK",
      ),
    );
  }
  await reduceContactLensStock(ctx);

  // 4. Non-work-order path (no lab work needed)
  if (!ctx.actuallyRequiresWorkOrder) {
    await handleNonWorkOrderPath(ctx, newOrder, billingResult, {});

    const successResponse = {
      order: { ...newOrder, order_items: ctx.orderItems },
      work_order: null,
      billing: billingResult
        ? { folio: billingResult.folio, pdfUrl: billingResult.pdfUrl, type: billingResult.type }
        : null,
    };

    await saveIdempotency(ctx, newOrder.id as string, null, successResponse);
    return createApiSuccessResponse(successResponse);
  }

  // 5. Work order path (Cash-First)
  const woResult = await createLegacyWorkOrder(ctx, newOrder);

  if ("error" in woResult) {
    return NextResponse.json(
      { error: woResult.error },
      { status: woResult.status },
    );
  }

  const { workOrder, balance } = woResult;
  billingResult = woResult.billingResult || billingResult;

  // 6. Notifications
  await sendWorkOrderNotifications(ctx, newOrder, workOrder!);

  // 7. Update quote status
  await updateQuoteStatus(ctx, newOrder, workOrder?.id as string | null);

  // 8. Build response
  const fullOrder = buildFullOrderResponse(
    newOrder as Parameters<typeof buildFullOrderResponse>[0],
    ctx.orderItems as unknown as OrderItem[],
    ctx.paymentAmount,
    ctx.dbPaymentMethod,
    ctx.siiInvoiceNumber,
    ctx.customerName,
    ctx.billingFirstName,
    ctx.billingLastName,
  );

  const successResponse = {
    order: fullOrder,
    work_order: {
      ...workOrder,
      sii_invoice_number: ctx.siiInvoiceNumber,
    },
    billing: buildBillingResponse(billingResult),
  };

  await saveIdempotency(ctx, newOrder.id as string, workOrder?.id as string | null, successResponse);
  return createApiSuccessResponse(successResponse);
}

async function saveIdempotency(
  ctx: ProcessSaleContext,
  orderId: string,
  workOrderId: string | null,
  response: Record<string, unknown>,
): Promise<void> {
  if (!ctx.idempotency_key) return;

  await ctx.supabase.from("pos_sale_idempotency").upsert(
    {
      idempotency_key: ctx.idempotency_key,
      order_id: orderId,
      work_order_id: workOrderId,
      response_snapshot: response,
    },
    { onConflict: "idempotency_key" },
  );
}

/**
 * processLegacyOrderCreate — creates order, order_items, payments, and POS transaction.
 *
 * Extracted from processLegacyHandler.ts to reduce file size.
 */

import { appLogger as logger } from "@/lib/logger";
import { PAYMENT_METHOD_MAP } from "@/lib/payments/constants";

import type { ProcessSaleContext } from "./processSaleTypes";

export interface LegacyOrderResult {
  order: Record<string, unknown>;
  orderError: boolean;
}

export async function createLegacyOrder(
  ctx: ProcessSaleContext,
): Promise<Record<string, unknown> | null> {
  const { data: newOrderData, error: orderError } = await ctx.supabase
    .from("orders")
    .insert({
      order_number: ctx.orderNumber,
      email: ctx.email || (ctx.customer?.email as string) || "venta@pos.local",
      status: "processing",
      payment_status: ctx.payment_status || "paid",
      subtotal: ctx.subtotal,
      tax_amount: ctx.tax_amount || 0,
      discount_amount: 0,
      total_amount: ctx.total_amount,
      currency: ctx.currency || "CLP",
      mp_payment_method: ctx.payment_method_type,
      branch_id: ctx.effectiveBranchId,
      organization_id: ctx.orderOrganizationId,
      field_operation_id: ctx.fieldOperationId,
      customer_notes: null,
      is_pos_sale: true,
      pos_session_id: ctx.posSessionId || null,
      customer_name: ctx.customerName,
      billing_first_name: ctx.billingFirstName,
      billing_last_name: ctx.billingLastName,
      sii_rut:
        ctx.customer_rut ||
        ctx.sii_rut ||
        (ctx.customer?.rut as string) ||
        null,
      sii_business_name: ctx.sii_business_name || null,
      customer_id: ctx.customer_id || null,
      agreement_id: ctx.agreement_id || null,
      purchase_order_id: ctx.purchase_order_id || null,
      copago_amount: ctx.copagoAmount ?? null,
      institutional_amount: ctx.institutionalAmount ?? null,
    })
    .select()
    .single();

  if (orderError) {
    logger.error("Error creating order", orderError);
    return null;
  }

  const newOrder = newOrderData as Record<string, unknown>;

  // Insert order_items
  if (ctx.orderItems.length > 0) {
    const { error: itemsError } = await ctx.supabase.from("order_items").insert(
      ctx.orderItems.map((item: Record<string, unknown>) => ({
        order_id: newOrder.id,
        product_id: (item.product_id as string) || null,
        product_name: (item.product_name as string) || "Producto",
        quantity: item.quantity as number,
        unit_price: item.unit_price as number,
        total_price: (item.unit_price as number) * (item.quantity as number),
        sku: (item as Record<string, unknown>).sku as string | null,
      })),
    );

    if (itemsError) {
      logger.error("Error creating order items", itemsError);
    }
  }

  // Register payment(s)
  if (ctx.agreement_id && ctx.copagoAmount != null) {
    await registerAgreementPayment(ctx, newOrder);
  } else if (ctx.paymentsArray && ctx.paymentsArray.length > 0) {
    await registerSplitPayments(ctx, newOrder);
  } else {
    await registerSinglePayment(ctx, newOrder);
  }

  // Create POS transaction
  if (ctx.posSessionId) {
    const { error: txError } = await ctx.supabase
      .from("pos_transactions")
      .insert({
        order_id: newOrder.id,
        pos_session_id: ctx.posSessionId,
        transaction_type: "sale",
        payment_method: ctx.dbPaymentMethod,
        amount: ctx.total_amount,
        change_amount: ctx.change_amount ?? null,
        notes: `Venta POS - ${newOrder.order_number as string}`,
      });

    if (txError) {
      logger.warn("Could not create pos_transaction for sale", {
        txError,
        order_id: newOrder.id,
      });
    }
  }

  // Update order's mp_payment_method
  const { error: updatePaymentMethodError } = await ctx.supabase
    .from("orders")
    .update({ mp_payment_method: ctx.dbPaymentMethod })
    .eq("id", newOrder.id);

  if (updatePaymentMethodError) {
    logger.error("Error updating payment method", updatePaymentMethodError);
  }

  return newOrder;
}

async function registerAgreementPayment(
  ctx: ProcessSaleContext,
  newOrder: Record<string, unknown>,
): Promise<void> {
  const { error: paymentError } = await ctx.supabase
    .from("order_payments")
    .insert({
      order_id: newOrder.id,
      amount: ctx.copagoAmount,
      payment_method: ctx.dbPaymentMethod,
      pos_session_id: ctx.posSessionId || null,
      payment_reference:
        ctx.fiscal_reference?.trim() || ctx.siiInvoiceNumber || null,
      created_by: ctx.user.id,
      notes: `Copago convenio - ${ctx.payment_method_type}`,
    });

  if (paymentError) {
    logger.error("Error creating payment record", paymentError);
  }

  if (ctx.institutionalAmount != null && ctx.institutionalAmount > 0) {
    const { error: balanceErr } = await ctx.supabase
      .from("agreement_institutional_balances")
      .insert({
        agreement_id: ctx.agreement_id,
        order_id: newOrder.id,
        purchase_order_id: ctx.purchase_order_id || null,
        amount: ctx.institutionalAmount,
        status: "pending",
      });

    if (balanceErr) {
      logger.error("Error creating institutional balance", balanceErr);
    }

    if (ctx.purchase_order_id) {
      await ctx.supabase
        .from("agreement_purchase_orders")
        .update({
          used_amount:
            ((ctx.purchaseOrder?.used_amount as number) || 0) +
            ctx.institutionalAmount,
        })
        .eq("id", ctx.purchase_order_id);
    }
  }
}

async function registerSplitPayments(
  ctx: ProcessSaleContext,
  newOrder: Record<string, unknown>,
): Promise<void> {
  for (let i = 0; i < ctx.paymentsArray.length; i++) {
    const p = ctx.paymentsArray[i] as Record<string, unknown>;
    const dbMethod =
      PAYMENT_METHOD_MAP[p.method as keyof typeof PAYMENT_METHOD_MAP] ||
      p.method;
    const { error: payErr } = await ctx.supabase.from("order_payments").insert({
      order_id: newOrder.id,
      amount: p.amount as number,
      payment_method: dbMethod,
      pos_session_id: ctx.posSessionId || null,
      payment_reference:
        i === 0
          ? ctx.fiscal_reference?.trim() || ctx.siiInvoiceNumber || null
          : null,
      created_by: ctx.user.id,
      notes:
        ctx.paymentsArray.length > 1
          ? `Pago ${i + 1}/${ctx.paymentsArray.length} - ${dbMethod}`
          : `Pago - ${dbMethod}`,
    });
    if (payErr) {
      logger.error("Error creating payment record", payErr);
    }
  }
}

async function registerSinglePayment(
  ctx: ProcessSaleContext,
  newOrder: Record<string, unknown>,
): Promise<void> {
  const { error: paymentError } = await ctx.supabase
    .from("order_payments")
    .insert({
      order_id: newOrder.id,
      amount: ctx.paymentAmount,
      payment_method: ctx.dbPaymentMethod,
      pos_session_id: ctx.posSessionId || null,
      payment_reference:
        ctx.fiscal_reference?.trim() || ctx.siiInvoiceNumber || null,
      created_by: ctx.user.id,
      notes: `Pago inicial - Método: ${ctx.payment_method_type}`,
    });

  if (paymentError) {
    logger.error("Error creating payment record", paymentError);
  }
}

/**
 * processLegacyWorkOrder — creates work order, notifications, and updates quote.
 *
 * Extracted from processLegacyHandler.ts to reduce file size.
 * Handles the Cash-First work order creation path.
 */

import { appLogger as logger } from "@/lib/logger";

import { computeCashAmount, computeWorkOrderStatus, type PaymentEntry } from "./processPaymentUtils";
import { type OrderItem } from "./processResponseBuilder";
import type { ProcessSaleContext } from "./processSaleTypes";
import { computeMinDepositFallback } from "./processSaleValidation";
import { reduceContactLensStock,reduceStock } from "./processStockReduction";

export interface LegacyWorkOrderResult {
  workOrder: Record<string, unknown> | null;
  balance: number;
  billingResult: Record<string, unknown> | null;
}

export async function createLegacyWorkOrder(
  ctx: ProcessSaleContext,
  newOrder: Record<string, unknown>,
): Promise<LegacyWorkOrderResult | { error: string; status: number }> {
  // Calculate balance
  const { data: balanceData, error: balanceError } = await ctx.supabase.rpc(
    "calculate_order_balance",
    { p_order_id: newOrder.id as string },
  );
  const balance = balanceError
    ? ctx.total_amount - ctx.paymentAmount
    : (balanceData as number) || 0;

  // Emit billing document
  const billingResult = await emitBilling(ctx, newOrder);

  // Stock reduction
  const stockOk = await reduceStock(ctx, newOrder.id as string);
  if (!stockOk) {
    const { APIError } = await import("@/lib/api/errors");
    return {
      error: "Error al actualizar stock",
      status: 400,
    };
  }
  await reduceContactLensStock(ctx);

  // Cash-First: determine work order status
  const { data: minDepositData } = await ctx.supabase.rpc("get_min_deposit", {
    p_order_total: ctx.total_amount,
    p_branch_id: ctx.effectiveBranchId,
  });
  const minDeposit =
    minDepositData ?? computeMinDepositFallback(ctx.total_amount);

  const { status: workOrderStatus, paymentStatus: workOrderPaymentStatus } =
    computeWorkOrderStatus(
      ctx.paymentAmount,
      minDeposit,
      ctx.total_amount,
      balance,
    );

  if (ctx.paymentAmount < minDeposit) {
    logger.info("Insufficient deposit", {
      paid: ctx.paymentAmount,
      required: minDeposit,
      total: ctx.total_amount,
    });
  }

  // Generate work order number
  const { data: workOrderNumber, error: workOrderNumberError } =
    await ctx.supabase.rpc("generate_work_order_number");

  if (workOrderNumberError || !workOrderNumber) {
    logger.error("Error generating work order number", workOrderNumberError);
    await ctx.supabase.from("orders").delete().eq("id", newOrder.id);
    return { error: "Failed to generate work order number", status: 500 };
  }

  // Build and create work order
  const lensCost =
    ctx.presbyopia_solution === "two_separate"
      ? (ctx.far_lens_cost || 0) + (ctx.near_lens_cost || 0)
      : ctx.contact_lens_cost || ctx.lensInfo.lens_cost || 0;

  const workOrderData: Record<string, unknown> = {
    work_order_number: workOrderNumber,
    branch_id: ctx.effectiveBranchId,
    field_operation_id: ctx.fieldOperationId,
    operativo_batch_id: ctx.fieldOperationId,
    customer_id: ctx.customer_id || null,
    prescription_id: ctx.lensInfo.prescription_id || null,
    quote_id: ctx.quote_id || null,
    frame_product_id: ctx.frameInfo.frame_product_id,
    frame_name: ctx.frameInfo.frame_name,
    frame_brand: ctx.frameInfo.frame_brand,
    frame_model: ctx.frameInfo.frame_model,
    frame_color: ctx.frameInfo.frame_color,
    frame_size: ctx.frameInfo.frame_size,
    frame_sku: ctx.frameInfo.frame_sku,
    frame_serial_number: null,
    lens_family_id:
      ctx.presbyopia_solution === "two_separate"
        ? null
        : ctx.lensInfo.lens_family_id || null,
    lens_type: ctx.lensInfo.lens_type,
    lens_sourcing_type:
      (ctx.lensInfo as unknown as Record<string, unknown>).lens_sourcing_type ||
      "surfaced",
    lens_material: ctx.lensInfo.lens_material,
    lens_index: ctx.lensInfo.lens_index,
    lens_treatments: ctx.lensInfo.lens_treatments,
    lens_tint_color: ctx.lensInfo.lens_tint_color,
    lens_tint_percentage: ctx.lensInfo.lens_tint_percentage,
    presbyopia_solution: ctx.presbyopia_solution || "none",
    far_lens_family_id:
      ctx.presbyopia_solution === "two_separate"
        ? ctx.far_lens_family_id || null
        : null,
    near_lens_family_id:
      ctx.presbyopia_solution === "two_separate"
        ? ctx.near_lens_family_id || null
        : null,
    far_lens_cost:
      ctx.presbyopia_solution === "two_separate" ? ctx.far_lens_cost || 0 : null,
    near_lens_cost:
      ctx.presbyopia_solution === "two_separate" ? ctx.near_lens_cost || 0 : null,
    contact_lens_family_id: ctx.contact_lens_family_id || null,
    contact_lens_rx_sphere_od: ctx.contact_lens_rx_sphere_od || null,
    contact_lens_rx_cylinder_od: ctx.contact_lens_rx_cylinder_od || null,
    contact_lens_rx_axis_od: ctx.contact_lens_rx_axis_od || null,
    contact_lens_rx_add_od: ctx.contact_lens_rx_add_od || null,
    contact_lens_rx_base_curve_od: ctx.contact_lens_rx_base_curve_od || null,
    contact_lens_rx_diameter_od: ctx.contact_lens_rx_diameter_od || null,
    contact_lens_rx_sphere_os: ctx.contact_lens_rx_sphere_os || null,
    contact_lens_rx_cylinder_os: ctx.contact_lens_rx_cylinder_os || null,
    contact_lens_rx_axis_os: ctx.contact_lens_rx_axis_os || null,
    contact_lens_rx_add_os: ctx.contact_lens_rx_add_os || null,
    contact_lens_rx_base_curve_os: ctx.contact_lens_rx_base_curve_os || null,
    contact_lens_rx_diameter_os: ctx.contact_lens_rx_diameter_os || null,
    contact_lens_quantity: ctx.contact_lens_family_id
      ? ctx.contact_lens_quantity || 1
      : null,
    contact_lens_cost: ctx.contact_lens_cost || null,
    prescription_snapshot: null,
    lab_name: null,
    lab_contact: null,
    lab_order_number: null,
    lab_estimated_delivery_date: null,
    status: workOrderStatus,
    frame_cost: ctx.frameInfo.frame_cost,
    lens_cost: lensCost,
    treatments_cost: ctx.treatmentsCost,
    labor_cost: ctx.laborCost,
    lab_cost: 0,
    subtotal: ctx.subtotal,
    tax_amount: ctx.tax_amount || 0,
    discount_amount: 0,
    total_amount: ctx.total_amount,
    currency: ctx.currency || "CLP",
    payment_status: workOrderPaymentStatus,
    payment_method: ctx.payment_method_type,
    deposit_amount: ctx.paymentAmount,
    balance_amount: balance,
    pos_order_id: newOrder.id,
    agreement_id: ctx.agreement_id || null,
    internal_notes: `Venta POS - Método: ${ctx.payment_method_type}${billingResult ? ` - Folio: ${billingResult.folio}` : ""} - Depósito: ${ctx.paymentAmount}/${ctx.total_amount} - Saldo: ${balance}${ctx.presbyopia_solution && ctx.presbyopia_solution !== "none" ? ` - Presbicia: ${ctx.presbyopia_solution}` : ""}${ctx.lensInfo.lens_family_id ? ` - Familia: ${(ctx.lensFamily?.name as string) || ctx.lensInfo.lens_family_id}` : ""}`,
    customer_notes: null,
    assigned_to: ctx.user.id,
    created_by: ctx.user.id,
  };

  const { data: newWorkOrder, error: workOrderError } = await ctx.supabase
    .from("lab_work_orders")
    .insert(workOrderData)
    .select()
    .single();

  if (workOrderError) {
    logger.error("Error creating work order", workOrderError);
    return { error: "Failed to create work order", status: 500 };
  }

  // Update status dates
  if (workOrderData.status && workOrderData.status !== "quote") {
    await ctx.supabase.rpc("update_work_order_status", {
      p_work_order_id: (newWorkOrder as Record<string, unknown>).id,
      p_new_status: workOrderData.status as string,
      p_changed_by: ctx.user.id,
      p_notes: "Work order created from POS sale",
    });
  }

  // Update POS session cash
  const cashAmount = computeCashAmount(
    (ctx.paymentsArray || []) as PaymentEntry[],
    ctx.payment_method_type,
    ctx.cash_received,
    ctx.total_amount,
  );
  if (cashAmount > 0 && ctx.posSessionId) {
    const { error: cashError } = await ctx.supabase.rpc(
      "update_pos_session_cash",
      { session_id: ctx.posSessionId, cash_amount: cashAmount },
    );
    if (cashError) {
      logger.error("Error updating POS session cash", cashError);
    }
  }

  return {
    workOrder: newWorkOrder as Record<string, unknown>,
    balance,
    billingResult,
  };
}

export async function handleNonWorkOrderPath(
  ctx: ProcessSaleContext,
  newOrder: Record<string, unknown>,
  billingResult: Record<string, unknown> | null,
  successResponse: Record<string, unknown>,
): Promise<void> {
  const { NotificationService } = await import(
    "@/lib/notifications/notification-service"
  );
  NotificationService.notifyNewSale(
    newOrder.id as string,
    newOrder.order_number as string,
    (newOrder.email as string) || "venta@pos.local",
    newOrder.total_amount as number,
    (newOrder.branch_id as string) ?? ctx.effectiveBranchId ?? undefined,
  ).catch((err: unknown) =>
    logger.error("Error creating sale notification", err),
  );
}

export async function sendWorkOrderNotifications(
  ctx: ProcessSaleContext,
  newOrder: Record<string, unknown>,
  newWorkOrder: Record<string, unknown>,
): Promise<void> {
  const { NotificationService } = await import(
    "@/lib/notifications/notification-service"
  );

  NotificationService.notifyNewSale(
    newOrder.id as string,
    newOrder.order_number as string,
    (newOrder.email as string) || "venta@pos.local",
    newOrder.total_amount as number,
    (newOrder.branch_id as string) ?? ctx.effectiveBranchId ?? undefined,
  ).catch((err: unknown) =>
    logger.error("Error creating sale notification", err),
  );

  const customerName = ctx.customer
    ? `${(ctx.customer.first_name as string) || ""} ${(ctx.customer.last_name as string) || ""}`.trim() ||
      (ctx.customer.email as string) || "Cliente"
    : "Cliente";

  NotificationService.notifyNewWorkOrder(
    newWorkOrder.id as string,
    newWorkOrder.work_order_number as string,
    customerName,
    newWorkOrder.total_amount as number,
    (newWorkOrder.branch_id as string) ?? ctx.effectiveBranchId ?? undefined,
  ).catch((err: unknown) =>
    logger.error("Error creating work order notification", err),
  );
}

export async function updateQuoteStatus(
  ctx: ProcessSaleContext,
  newOrder: Record<string, unknown>,
  workOrderId: string | null,
): Promise<void> {
  if (!ctx.quote_id || !ctx.quote) return;

  const { error: quoteUpdateError } = await ctx.supabase
    .from("quotes")
    .update({
      status: "accepted",
      converted_to_work_order_id: workOrderId,
      updated_at: new Date().toISOString(),
    })
    .eq("id", ctx.quote_id);

  if (quoteUpdateError) {
    logger.error("Error updating quote status", quoteUpdateError);
  } else {
    logger.info("Quote marked as accepted", {
      quote_id: ctx.quote_id,
      work_order_id: workOrderId,
      order_id: newOrder.id,
    });
  }
}

async function emitBilling(
  ctx: ProcessSaleContext,
  newOrder: Record<string, unknown>,
): Promise<Record<string, unknown> | null> {
  let billingResult: Record<string, unknown> | null = null;
  try {
    const { BillingFactory } = await import("@/lib/billing/BillingFactory");
    const billingConfig = await BillingFactory.getBillingConfig(
      ctx.effectiveBranchId || "",
    );
    const billingAdapter = BillingFactory.createAdapter(billingConfig);

    let ocNumber: string | null = null;
    if (ctx.purchase_order_id && ctx.purchaseOrder) {
      const { data: po } = await ctx.supabase
        .from("agreement_purchase_orders")
        .select("oc_number")
        .eq("id", ctx.purchase_order_id)
        .single();
      ocNumber = (po as Record<string, unknown> | null)?.oc_number as
        | string
        | null;
    }

    const { buildBillingOrder } = await import("./processResponseBuilder");
    const billingOrder = buildBillingOrder({
      orderId: newOrder.id as string,
      orderNumber: newOrder.order_number as string,
      customerId: ctx.customer_id,
      branchId: ctx.effectiveBranchId ?? "",
      totalAmount: ctx.total_amount,
      subtotal: ctx.subtotal,
      taxAmount: ctx.tax_amount || 0,
      items: ctx.orderItems as unknown as OrderItem[],
      customer: ctx.customer as Record<string, unknown> | null,
      createdAt: newOrder.created_at as string,
      ocNumber,
      purchaseOrderId: ctx.purchase_order_id,
      agreementId: ctx.agreement_id,
      customerName: ctx.customer_name,
      email: ctx.email,
      customerRut: ctx.customer_rut,
      siiBusinessName: ctx.sii_business_name,
    });

    billingResult = (await billingAdapter.emitDocument(billingOrder)) as unknown as Record<
      string,
      unknown
    >;
    logger.info("Billing document emitted", {
      folio: billingResult?.folio,
      type: billingResult?.type,
    });
  } catch (billingError) {
    logger.error("Error emitting billing document", billingError);
  }
  return billingResult;
}

/**
 * Process Payment Utils — pure functions for payment amount computation,
 * method resolution, work order payment status, and stock reduction.
 *
 * Extracted from process-sale/route.ts T-122. All functions are pure
 * (no side effects, no DB calls).
 */

import { PAYMENT_METHOD_MAP } from "@/lib/payments/constants";

// ─── Types ───────────────────────────────────────────────────────────────────

export interface PaymentEntry {
  amount: number;
  method: string;
  [key: string]: unknown;
}

export interface PaymentAmountParams {
  agreementId: string | null;
  copagoAmount: number | null;
  paymentsArray: PaymentEntry[];
  depositAmount: number | null;
  cashReceived: number | null;
  totalAmount: number;
}

export interface DbPaymentMethodParams {
  agreementId: string | null;
  copagoAmount: number | null;
  paymentMethodType: string;
  paymentsArray: PaymentEntry[];
}

export interface WorkOrderStatusResult {
  status: string;
  paymentStatus: string;
}

export interface OrderPaymentsPayloadParams {
  agreementId: string | null;
  copagoAmount: number | null;
  dbPaymentMethod: string;
  paymentsArray: PaymentEntry[];
  paymentMethodType: string;
  fiscalReference: string | null;
  siiInvoiceNumber: string | null;
}

export interface StockReductionItem {
  product_id: string;
  branch_id: string | null;
  quantity: number;
}

export interface ProductInfo {
  id: string;
  name?: string;
  product_type?: string;
  [key: string]: unknown;
}

// ─── Payment Amount ──────────────────────────────────────────────────────────

export function computePaymentAmount(params: PaymentAmountParams): number {
  const {
    agreementId,
    copagoAmount,
    paymentsArray,
    depositAmount,
    cashReceived,
    totalAmount,
  } = params;

  if (agreementId && copagoAmount != null) {
    return copagoAmount;
  }
  if (paymentsArray.length > 0) {
    return paymentsArray.reduce((s, p) => s + p.amount, 0);
  }
  return depositAmount || cashReceived || totalAmount;
}

// ─── DB Payment Method ───────────────────────────────────────────────────────

export function computeDbPaymentMethod(params: DbPaymentMethodParams): string {
  const { agreementId, copagoAmount, paymentMethodType, paymentsArray } =
    params;

  if (agreementId && copagoAmount != null) {
    return PAYMENT_METHOD_MAP[paymentMethodType] || paymentMethodType;
  }
  if (paymentsArray.length > 0) {
    return (
      PAYMENT_METHOD_MAP[paymentsArray[0].method] ||
      paymentsArray[0].method ||
      "cash"
    );
  }
  return PAYMENT_METHOD_MAP[paymentMethodType] || paymentMethodType;
}

// ─── Work Order Payment Status (Cash-First Logic) ────────────────────────────

export function computeWorkOrderStatus(
  paymentAmount: number,
  minDeposit: number,
  totalAmount: number,
  balance: number,
): WorkOrderStatusResult {
  if (paymentAmount < minDeposit) {
    return { status: "on_hold_payment", paymentStatus: "pending" };
  }
  if (balance === 0) {
    return { status: "ordered", paymentStatus: "paid" };
  }
  return { status: "ordered", paymentStatus: "partial" };
}

// ─── Lens Cost ───────────────────────────────────────────────────────────────

export function computeLensCost(
  presbyopiaSolution: string | null | undefined,
  farLensCost: number | null | undefined,
  nearLensCost: number | null | undefined,
  contactLensCost: number | null | undefined,
  lensCost: number,
): number {
  if (presbyopiaSolution === "two_separate") {
    return (farLensCost || 0) + (nearLensCost || 0);
  }
  return contactLensCost || lensCost || 0;
}

// ─── Cash Amount ─────────────────────────────────────────────────────────────

export function computeCashAmount(
  paymentsArray: PaymentEntry[],
  paymentMethodType: string,
  cashReceived: number | null | undefined,
  totalAmount: number,
): number {
  if (paymentsArray.length > 0) {
    return paymentsArray
      .filter((p) => p.method === "cash")
      .reduce((s, p) => s + p.amount, 0);
  }
  if (paymentMethodType === "cash") {
    return cashReceived || totalAmount;
  }
  return 0;
}

// ─── Order Payments Payload ──────────────────────────────────────────────────

export function buildOrderPaymentsPayload(
  params: OrderPaymentsPayloadParams,
): Array<{
  amount: number;
  payment_method: string;
  payment_reference: string | null;
  notes: string;
}> {
  const {
    agreementId,
    copagoAmount,
    dbPaymentMethod,
    paymentsArray,
    paymentMethodType,
    fiscalReference,
    siiInvoiceNumber,
  } = params;

  if (agreementId && copagoAmount != null) {
    return [
      {
        amount: copagoAmount,
        payment_method: dbPaymentMethod,
        payment_reference: fiscalReference?.trim() || siiInvoiceNumber || null,
        notes: `Copago convenio - ${paymentMethodType}`,
      },
    ];
  }

  if (paymentsArray.length > 0) {
    return paymentsArray.map((p, i) => ({
      amount: p.amount,
      payment_method: PAYMENT_METHOD_MAP[p.method] || p.method,
      payment_reference:
        i === 0 ? fiscalReference?.trim() || siiInvoiceNumber || null : null,
      notes:
        paymentsArray.length > 1
          ? `Pago ${i + 1}/${paymentsArray.length} - ${PAYMENT_METHOD_MAP[p.method] || p.method}`
          : `Pago - ${PAYMENT_METHOD_MAP[p.method] || p.method}`,
    }));
  }

  return [
    {
      amount: computePaymentAmount({
        agreementId,
        copagoAmount,
        paymentsArray,
        depositAmount: null,
        cashReceived: null,
        totalAmount: paymentsArray.reduce((s, p) => s + p.amount, 0) || 0,
      }),
      payment_method: dbPaymentMethod,
      payment_reference: fiscalReference?.trim() || siiInvoiceNumber || null,
      notes: `Pago inicial - Método: ${paymentMethodType}`,
    },
  ];
}

// ─── Stock Reduction Items ───────────────────────────────────────────────────

export function buildStockReductionItems(
  items: Array<{ product_id?: string; quantity: number }>,
  productsForStockCheck: ProductInfo[],
  effectiveBranchId: string | null,
): StockReductionItem[] {
  return items
    .filter(
      (item) =>
        item.product_id &&
        !item.product_id.includes("frame-manual") &&
        !item.product_id.includes("lens-") &&
        !item.product_id.includes("treatments-") &&
        !item.product_id.includes("labor-") &&
        !item.product_id.includes("discount-"),
    )
    .filter((item) => {
      const product = productsForStockCheck.find(
        (p) => p.id === item.product_id,
      );
      return product?.product_type === "frame" ||
        product?.product_type === "accessory"
        ? true
        : false;
    })
    .map((item) => ({
      product_id: item.product_id!,
      branch_id: effectiveBranchId,
      quantity: item.quantity,
    }));
}

/**
 * Process Response Builder — pure functions for API response formatting.
 *
 * Extracted from process-sale/route.ts T-123. All functions are pure
 * (no side effects, no DB calls).
 */

import type { Order as BillingOrder } from "@/lib/billing/adapters/BillingAdapter";

// ─── Types ───────────────────────────────────────────────────────────────────

export interface OrderItem {
  id: string;
  product_id: string | null;
  product_name: string;
  quantity: number;
  unit_price: number;
  total_price: number;
  sku: string | null;
}

export interface CustomerNameResult {
  customerName: string | null;
  billingFirstName: string | null;
  billingLastName: string | null;
}

export interface BuildCustomerNameParams {
  customer: {
    id?: string | null;
    first_name?: string | null;
    last_name?: string | null;
    email?: string | null;
  } | null;
  customerName: string | null;
  siiBusinessName: string | null;
  customerId: string | null;
}

export interface BuildFullOrderResponseParams {
  id: string;
  order_number: string;
  [key: string]: unknown;
}

export interface BuildBillingOrderParams {
  orderId: string;
  orderNumber: string;
  customerId: string | null | undefined;
  branchId: string;
  totalAmount: number;
  subtotal: number;
  taxAmount: number;
  items: OrderItem[];
  customer: {
    id?: string;
    first_name?: string;
    last_name?: string;
    email?: string;
    phone?: string;
    rut?: string;
  } | null;
  createdAt: string | undefined;
  ocNumber: string | null;
  purchaseOrderId: string | null | undefined;
  agreementId: string | null | undefined;
  customerName: string | null;
  email: string | null;
  customerRut: string | null;
  siiBusinessName: string | null;
}

export interface BillingResult {
  folio?: string;
  pdfUrl?: string;
  type?: string;
}

// ─── Build Order Items ───────────────────────────────────────────────────────

export function buildOrderItems(
  items: Array<{
    product_id?: string | null;
    product_name?: string;
    quantity: number;
    unit_price: number;
    sku?: string | null;
  }>,
): OrderItem[] {
  return items.map((item, idx) => ({
    id: `item-${idx}`,
    product_id: item.product_id || null,
    product_name: item.product_name || "Producto",
    quantity: item.quantity,
    unit_price: item.unit_price,
    total_price: item.unit_price * item.quantity,
    sku: item.sku || null,
  }));
}

// ─── Build Customer Name ─────────────────────────────────────────────────────

export function buildCustomerName(
  params: BuildCustomerNameParams,
): CustomerNameResult {
  const { customer, customerName, siiBusinessName, customerId } = params;

  if (customerId && customer) {
    // Registered customer
    const name =
      customer.first_name && customer.last_name
        ? `${customer.first_name} ${customer.last_name}`.trim()
        : customer.email || null;
    return {
      customerName: name,
      billingFirstName: customer.first_name || null,
      billingLastName: customer.last_name || null,
    };
  }

  if (customerName) {
    // Unregistered customer with name
    const nameParts = customerName.split(" ");
    return {
      customerName,
      billingFirstName: nameParts[0] || null,
      billingLastName: nameParts.slice(1).join(" ") || null,
    };
  }

  if (siiBusinessName) {
    // Company (SII)
    return {
      customerName: siiBusinessName,
      billingFirstName: null,
      billingLastName: null,
    };
  }

  return {
    customerName: null,
    billingFirstName: null,
    billingLastName: null,
  };
}

// ─── Build Full Order Response ───────────────────────────────────────────────

export function buildFullOrderResponse(
  order: BuildFullOrderResponseParams,
  orderItems: OrderItem[],
  paymentAmount: number,
  dbPaymentMethod: string,
  siiInvoiceNumber: string | null,
  customerName: string | null,
  billingFirstName: string | null,
  billingLastName: string | null,
): Record<string, unknown> {
  return {
    ...order,
    order_items: orderItems,
    order_payments: [
      { amount: paymentAmount, payment_method: dbPaymentMethod },
    ],
    sii_invoice_number: siiInvoiceNumber,
    customer_name: customerName,
    billing_first_name: billingFirstName,
    billing_last_name: billingLastName,
  };
}

// ─── Build Work Order Response ───────────────────────────────────────────────

export function buildWorkOrderResponse(
  workOrderId: string | null,
  workOrderNumber: string | null | undefined,
  siiInvoiceNumber: string | null,
): Record<string, unknown> | null {
  if (!workOrderId) return null;
  return {
    id: workOrderId,
    work_order_number: workOrderNumber,
    sii_invoice_number: siiInvoiceNumber,
  };
}

// ─── Build Billing Response ──────────────────────────────────────────────────

export function buildBillingResponse(
  billingResult: BillingResult | null,
): Record<string, unknown> | null {
  if (!billingResult) return null;
  return {
    folio: billingResult.folio,
    pdfUrl: billingResult.pdfUrl,
    type: billingResult.type,
  };
}

// ─── Build Billing Order ─────────────────────────────────────────────────────

export function buildBillingOrder(
  params: BuildBillingOrderParams,
): BillingOrder {
  const {
    orderId,
    orderNumber,
    customerId,
    branchId,
    totalAmount,
    subtotal,
    taxAmount,
    items,
    customer,
    createdAt,
    ocNumber,
    purchaseOrderId,
    agreementId,
    customerName,
    email,
    customerRut,
    siiBusinessName,
  } = params;

  return {
    id: orderId,
    order_number: orderNumber,
    customer_id: customerId ?? undefined,
    branch_id: branchId,
    total_amount: totalAmount,
    subtotal: subtotal,
    tax_amount: taxAmount,
    discount_amount: 0,
    items: items.map((i) => ({
      id: i.id,
      product_id: i.product_id || undefined,
      product_name: i.product_name,
      quantity: i.quantity,
      unit_price: i.unit_price,
      total_price: i.total_price,
      sku: i.sku || undefined,
    })),
    customer: customer
      ? {
          id: customer.id ?? "",
          first_name: customer.first_name ?? undefined,
          last_name: customer.last_name ?? undefined,
          email: customer.email ?? undefined,
          phone: customer.phone ?? undefined,
          rut: customer.rut ?? undefined,
          business_name: undefined,
        }
      : {
          id: "",
          first_name: customerName?.split(" ")[0] ?? undefined,
          last_name: customerName?.split(" ").slice(1).join(" ") ?? undefined,
          email: email ?? undefined,
          phone: undefined,
          rut: customerRut ?? undefined,
          business_name: siiBusinessName ?? undefined,
        },
    created_at: createdAt ?? new Date().toISOString(),
    oc_number: ocNumber ?? undefined,
    purchase_order_id: purchaseOrderId ?? undefined,
    agreement_id: agreementId ?? undefined,
  };
}

/**
 * RPC path handler for process-sale.
 *
 * Extracted from route.ts `if (useRpc)` branch (lines 919-1324).
 * Uses the transactional process_pos_sale RPC for branch-mode sales.
 */
import { NextResponse } from "next/server";

import { APIError } from "@/lib/api/errors";
import {
  createApiErrorResponse,
  createApiSuccessResponse,
} from "@/lib/api/response";
import { appLogger as logger } from "@/lib/logger";

import {
  buildOrderPaymentsPayload,
  buildStockReductionItems,
  computeLensCost,
  computeWorkOrderStatus,
} from "./processPaymentUtils";
import {
  buildRpcSuccessResponse,
  handlePostRpcProcessing,
} from "./processRpcPostProcessing";
import type { ProcessSaleContext } from "./processSaleTypes";
import { computeMinDepositFallback } from "./processSaleValidation";

export async function handleRpcPath(
  ctx: ProcessSaleContext,
): Promise<NextResponse> {
  const { data: minDepositData } = await ctx.supabase.rpc(
    "get_min_deposit",
    {
      p_order_total: ctx.total_amount,
      p_branch_id: ctx.effectiveBranchId,
    },
  );
  const minDeposit =
    minDepositData ?? computeMinDepositFallback(ctx.total_amount);
  const { status: workOrderStatus, paymentStatus: workOrderPaymentStatus } =
    computeWorkOrderStatus(
      ctx.paymentAmount,
      minDeposit,
      ctx.total_amount,
      ctx.balance,
    );

  const orderPayload: Record<string, unknown> = {
    order_number: ctx.orderNumber,
    email: ctx.email || (ctx.customer?.email as string) || "venta@pos.local",
    status: "processing",
    payment_status: ctx.payment_status || "paid",
    subtotal: ctx.subtotal,
    tax_amount: ctx.tax_amount || 0,
    discount_amount: 0,
    total_amount: ctx.total_amount,
    currency: ctx.currency || "CLP",
    mp_payment_method: ctx.dbPaymentMethod,
    branch_id: ctx.effectiveBranchId,
    organization_id: ctx.orderOrganizationId,
    field_operation_id: ctx.fieldOperationId,
    pos_session_id: ctx.posSessionId,
    customer_name: ctx.customerName,
    billing_first_name: ctx.billingFirstName,
    billing_last_name: ctx.billingLastName,
    sii_rut:
      ctx.customer_rut || ctx.sii_rut || (ctx.customer?.rut as string) || null,
    sii_business_name: ctx.sii_business_name || null,
    customer_id: ctx.customer_id || null,
    agreement_id: ctx.agreement_id || null,
    purchase_order_id: ctx.purchase_order_id || null,
    copago_amount: ctx.copagoAmount ?? null,
    institutional_amount: ctx.institutionalAmount ?? null,
  };

  const orderItemsPayload = ctx.items.map((item: Record<string, unknown>) => ({
    product_id: (item.product_id as string) || null,
    product_name: (item.product_name as string) || "Producto",
    quantity: item.quantity as number,
    unit_price: item.unit_price as number,
    total_price: (item.unit_price as number) * (item.quantity as number),
    sku: (item as Record<string, unknown>).sku as string | null,
  }));

  const orderPaymentsPayload = buildOrderPaymentsPayload({
    agreementId: ctx.agreement_id,
    copagoAmount: ctx.copagoAmount,
    dbPaymentMethod: ctx.dbPaymentMethod,
    paymentsArray: ctx.paymentsArray || [],
    paymentMethodType: ctx.payment_method_type,
    fiscalReference: ctx.fiscal_reference?.trim() || null,
    siiInvoiceNumber: ctx.siiInvoiceNumber,
  });

  let stockReductionsPayload = buildStockReductionItems(
    ctx.items,
    ctx.productsForStockCheck,
    ctx.effectiveBranchId,
  );

  // Ensure frame from work order is reduced when not already in items
  const uuidRegex =
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  if (
    ctx.actuallyRequiresWorkOrder &&
    ctx.frameInfo.frame_product_id &&
    uuidRegex.test(ctx.frameInfo.frame_product_id) &&
    !ctx.frameInfo.frame_product_id.includes("frame-manual") &&
    !stockReductionsPayload.some(
      (r: { product_id: string }) =>
        r.product_id === ctx.frameInfo.frame_product_id,
    )
  ) {
    const frameProduct = ctx.productsForStockCheck.find(
      (p: Record<string, unknown>) => p.id === ctx.frameInfo.frame_product_id,
    );
    if (
      (frameProduct as Record<string, unknown> | undefined)?.product_type !==
      "service"
    ) {
      stockReductionsPayload = [
        ...stockReductionsPayload,
        {
          product_id: ctx.frameInfo.frame_product_id,
          branch_id: ctx.effectiveBranchId,
          quantity: 1,
        },
      ];
    }
  }

  const lensCost = computeLensCost(
    ctx.presbyopia_solution,
    ctx.far_lens_cost,
    ctx.near_lens_cost,
    ctx.contact_lens_cost,
    ctx.lensInfo.lens_cost,
  );

  const workOrderPayload = ctx.actuallyRequiresWorkOrder
    ? {
        field_operation_id: ctx.fieldOperationId,
        customer_id: ctx.customer_id || null,
        prescription_id: ctx.lensInfo.prescription_id || null,
        quote_id: ctx.quote_id || null,
        frame_product_id: ctx.frameInfo.frame_product_id,
        frame_name: ctx.frameInfo.frame_name,
        frame_brand: ctx.frameInfo.frame_brand,
        frame_model: ctx.frameInfo.frame_model,
        frame_color: ctx.frameInfo.frame_color,
        frame_size: ctx.frameInfo.frame_size,
        frame_sku: ctx.frameInfo.frame_sku,
        lens_family_id:
          ctx.presbyopia_solution === "two_separate"
            ? null
            : ctx.lensInfo.lens_family_id || null,
        lens_type: ctx.lensInfo.lens_type,
        lens_material: ctx.lensInfo.lens_material,
        lens_index: ctx.lensInfo.lens_index,
        lens_treatments: ctx.lensInfo.lens_treatments,
        lens_tint_color: ctx.lensInfo.lens_tint_color,
        lens_tint_percentage: ctx.lensInfo.lens_tint_percentage,
        presbyopia_solution: ctx.presbyopia_solution || "none",
        far_lens_family_id:
          ctx.presbyopia_solution === "two_separate"
            ? ctx.far_lens_family_id || null
            : null,
        near_lens_family_id:
          ctx.presbyopia_solution === "two_separate"
            ? ctx.near_lens_family_id || null
            : null,
        far_lens_cost:
          ctx.presbyopia_solution === "two_separate"
            ? ctx.far_lens_cost || 0
            : null,
        near_lens_cost:
          ctx.presbyopia_solution === "two_separate"
            ? ctx.near_lens_cost || 0
            : null,
        contact_lens_family_id: ctx.contact_lens_family_id || null,
        contact_lens_quantity: ctx.contact_lens_family_id
          ? ctx.contact_lens_quantity || 1
          : null,
        contact_lens_cost: ctx.contact_lens_cost || null,
        frame_cost: ctx.frameInfo.frame_cost,
        lens_cost: lensCost,
        treatments_cost: ctx.treatmentsCost,
        labor_cost: ctx.laborCost,
        lab_cost: 0,
        subtotal: ctx.subtotal,
        tax_amount: ctx.tax_amount || 0,
        discount_amount: 0,
        total_amount: ctx.total_amount,
        currency: ctx.currency || "CLP",
        status: workOrderStatus,
        payment_status: workOrderPaymentStatus,
        deposit_amount: ctx.paymentAmount,
        balance_amount: ctx.balance,
        agreement_id: ctx.agreement_id || null,
        internal_notes: `Venta POS - Método: ${ctx.payment_method_type}`,
      }
    : null;

  const posTransactionPayload = ctx.posSessionId
    ? {
        payment_method: ctx.dbPaymentMethod,
        amount: ctx.total_amount,
        change_amount: ctx.change_amount ?? 0,
        notes: `Venta POS - ${ctx.orderNumber}`,
      }
    : null;

  const rpcPayload = {
    order: orderPayload,
    order_items: orderItemsPayload,
    order_payments: orderPaymentsPayload,
    stock_reductions: stockReductionsPayload,
    work_order: workOrderPayload,
    pos_transaction: posTransactionPayload,
  };

  const { data: rpcResult, error: rpcError } =
    await ctx.supabase.rpc("process_pos_sale", {
      p_payload: JSON.stringify(rpcPayload),
      p_user_id: ctx.user.id,
    });

  if (rpcError) {
    logger.error("process_pos_sale RPC error", rpcError);
    return createApiErrorResponse(
      new APIError(
        `Error al procesar la venta: ${rpcError.message}`,
        500,
        "RPC_ERROR",
      ),
    );
  }

  const orderId = (rpcResult as Record<string, unknown> | null)?.order_id as
    | string
    | undefined;
  const workOrderId = (rpcResult as Record<string, unknown> | null)
    ?.work_order_id as string | undefined;
  if (!orderId) {
    logger.error("RPC returned no order_id", rpcResult);
    return createApiErrorResponse(
      new APIError(
        "Error al procesar la venta: la operación no devolvió un ID de orden",
        500,
        "RPC_ERROR",
      ),
    );
  }

  const { data: fetchedOrder } = await ctx.supabase
    .from("orders")
    .select("*")
    .eq("id", orderId)
    .single();

  const billingResult = await handlePostRpcProcessing(ctx, orderId, rpcResult, fetchedOrder, workOrderId);

  const successResponse = buildRpcSuccessResponse(ctx, orderId, rpcResult, fetchedOrder, workOrderId, billingResult);

  if (ctx.idempotency_key) {
    await ctx.supabase.from("pos_sale_idempotency").upsert(
      {
        idempotency_key: ctx.idempotency_key,
        order_id: orderId,
        work_order_id: workOrderId || null,
        response_snapshot: successResponse,
      },
      { onConflict: "idempotency_key" },
    );
  }

  return createApiSuccessResponse(successResponse);
}

/**
 * Post-RPC processing for the process-sale RPC handler.
 *
 * Extracted from processRpcHandler.ts to reduce module size.
 * Handles agreement balances, billing, cash updates, notifications, and quote status.
 */
import { BillingFactory } from "@/lib/billing/BillingFactory";
import { appLogger as logger } from "@/lib/logger";

import {
  buildBillingOrder,
  buildBillingResponse,
  buildFullOrderResponse,
  buildWorkOrderResponse,
} from "./processResponseBuilder";
import type { ProcessSaleContext } from "./processSaleTypes";

export async function handlePostRpcProcessing(
  ctx: ProcessSaleContext,
  orderId: string,
  rpcResult: Record<string, unknown> | null,
  fetchedOrder: Record<string, unknown> | null,
  workOrderId: string | undefined,
): Promise<Record<string, unknown> | null> {
  // Agreement post-processing
  if (
    ctx.agreement_id &&
    ctx.institutionalAmount != null &&
    ctx.institutionalAmount > 0
  ) {
    await ctx.supabase.from("agreement_institutional_balances").insert({
      agreement_id: ctx.agreement_id,
      order_id: orderId,
      purchase_order_id: ctx.purchase_order_id || null,
      amount: ctx.institutionalAmount,
      status: "pending",
    });
    if (ctx.purchase_order_id) {
      await ctx.supabase
        .from("agreement_purchase_orders")
        .update({
          used_amount:
            ((ctx.purchaseOrder?.used_amount as number) || 0) +
            ctx.institutionalAmount,
        })
        .eq("id", ctx.purchase_order_id);
    }
  }

  // Billing
  let billingResult: Record<string, unknown> | null = null;
  try {
    const billingConfig = await BillingFactory.getBillingConfig(
      ctx.effectiveBranchId || "",
    );
    const billingAdapter = BillingFactory.createAdapter(billingConfig);
    let ocNumber: string | null = null;
    if (ctx.purchase_order_id && ctx.purchaseOrder) {
      const { data: po } = await ctx.supabase
        .from("agreement_purchase_orders")
        .select("oc_number")
        .eq("id", ctx.purchase_order_id)
        .single();
      ocNumber = (po as Record<string, unknown> | null)?.oc_number as
        | string
        | null;
    }
    const billingOrder = buildBillingOrder({
      orderId,
      orderNumber:
        ((rpcResult as Record<string, unknown>)?.order_number as string) || "",
      customerId: ctx.customer_id,
      branchId: ctx.effectiveBranchId ?? "",
      totalAmount: ctx.total_amount,
      subtotal: ctx.subtotal,
      taxAmount: ctx.tax_amount || 0,
      items: ctx.orderItems,
      customer: ctx.customer as Record<string, unknown> | null,
      createdAt: (fetchedOrder as Record<string, unknown> | null)
        ?.created_at as string,
      ocNumber,
      purchaseOrderId: ctx.purchase_order_id,
      agreementId: ctx.agreement_id,
      customerName: ctx.customer_name,
      email: ctx.email,
      customerRut: ctx.customer_rut,
      siiBusinessName: ctx.sii_business_name,
    });
    billingResult = (await billingAdapter.emitDocument(billingOrder)) as Record<
      string,
      unknown
    >;
  } catch (billingError) {
    logger.error("Error emitting billing document (RPC path)", billingError);
  }

  // Cash update
  const { computeCashAmount } = await import("./processPaymentUtils");
  const cashAmount = computeCashAmount(
    ctx.paymentsArray || [],
    ctx.payment_method_type,
    ctx.cash_received,
    ctx.total_amount,
  );
  if (cashAmount > 0 && ctx.posSessionId) {
    await ctx.supabase.rpc("update_pos_session_cash", {
      session_id: ctx.posSessionId,
      cash_amount: cashAmount,
    });
  }

  // Notifications
  const { NotificationService } = await import(
    "@/lib/notifications/notification-service"
  );
  NotificationService.notifyNewSale(
    orderId,
    ((rpcResult as Record<string, unknown>)?.order_number as string) || "",
    ctx.email || "venta@pos.local",
    ctx.total_amount,
    ctx.effectiveBranchId ?? undefined,
  ).catch((err: unknown) =>
    logger.error("Error creating sale notification", err),
  );

  if (workOrderId) {
    const customerNameForNotif = ctx.customer
      ? `${(ctx.customer.first_name as string) || ""} ${(ctx.customer.last_name as string) || ""}`.trim() ||
        (ctx.customer.email as string) ||
        "Cliente"
      : "Cliente";
    NotificationService.notifyNewWorkOrder(
      workOrderId,
      ((rpcResult as Record<string, unknown>)?.work_order_number as string) ||
        "",
      customerNameForNotif,
      ctx.total_amount,
      ctx.effectiveBranchId ?? undefined,
    ).catch((err: unknown) =>
      logger.error("Error creating work order notification", err),
    );
  }

  // Quote status update
  if (ctx.quote_id && ctx.quote) {
    await ctx.supabase
      .from("quotes")
      .update({
        status: "accepted",
        converted_to_work_order_id: workOrderId || null,
        updated_at: new Date().toISOString(),
      })
      .eq("id", ctx.quote_id);
  }

  return billingResult;
}

export function buildRpcSuccessResponse(
  ctx: ProcessSaleContext,
  orderId: string,
  rpcResult: Record<string, unknown> | null,
  fetchedOrder: Record<string, unknown> | null,
  workOrderId: string | undefined,
  billingResult: Record<string, unknown> | null,
): Record<string, unknown> {
  const newOrder = {
    ...(fetchedOrder as Record<string, unknown>),
    id: orderId,
    order_number:
      ((rpcResult as Record<string, unknown>)?.order_number as string) ||
      ((fetchedOrder as Record<string, unknown> | null)
        ?.order_number as string),
  };
  const fullOrder = buildFullOrderResponse(
    newOrder,
    ctx.orderItems,
    ctx.paymentAmount,
    ctx.dbPaymentMethod,
    ctx.siiInvoiceNumber,
    ctx.customerName,
    ctx.billingFirstName,
    ctx.billingLastName,
  );
  return {
    order: fullOrder,
    work_order: buildWorkOrderResponse(
      workOrderId || null,
      (rpcResult as Record<string, unknown>)?.work_order_number as
        | string
        | null,
      ctx.siiInvoiceNumber,
    ),
    billing: buildBillingResponse(billingResult),
  };
}

