/**
 * Agreement and purchase order lookup logic for process-sale.
 *
 * Extracted from processSaleBusinessLookups.ts to reduce file size.
 */
import type { SupabaseClient } from "@supabase/supabase-js";
import { NextResponse } from "next/server";

export interface AgreementLookupResult {
  agreement: Record<string, unknown> | null;
  purchaseOrder: Record<string, unknown> | null;
  copagoAmount: number | null;
  institutionalAmount: number | null;
}

export async function handleAgreementLookups(
  supabase: SupabaseClient,
  agreementId: string | undefined,
  purchaseOrderId: string | undefined,
  totalAmount: number | undefined,
): Promise<AgreementLookupResult | NextResponse> {
  if (!agreementId) {
    return {
      agreement: null,
      purchaseOrder: null,
      copagoAmount: null,
      institutionalAmount: null,
    };
  }

  const { data: agreementData } = await supabase
    .from("agreements")
    .select("id, status, valid_from, valid_until, billing_rules")
    .eq("id", agreementId as string)
    .single();
  if (!agreementData) {
    return NextResponse.json(
      { error: "Convenio no encontrado" },
      { status: 404 },
    ) as NextResponse;
  }
  const agreement = agreementData as Record<string, unknown>;

  if (agreement.status !== "active") {
    return NextResponse.json(
      { error: "El convenio no está activo" },
      { status: 400 },
    ) as NextResponse;
  }
  const today = new Date().toISOString().split("T")[0];
  const validFrom = agreement.valid_from as string;
  const validUntil = agreement.valid_until as string | undefined;
  if (validFrom > today) {
    return NextResponse.json(
      { error: "El convenio aún no está vigente" },
      { status: 400 },
    ) as NextResponse;
  }
  if (validUntil && validUntil < today) {
    return NextResponse.json(
      { error: "El convenio ha expirado" },
      { status: 400 },
    ) as NextResponse;
  }

  if (!purchaseOrderId) {
    return NextResponse.json(
      {
        error:
          "La orden de compra (OC) es obligatoria para ventas bajo convenio",
      },
      { status: 400 },
    ) as NextResponse;
  }

  const { data: poData } = await supabase
    .from("agreement_purchase_orders")
    .select("id, status, max_amount, used_amount")
    .eq("id", purchaseOrderId as string)
    .eq("agreement_id", agreementId as string)
    .single();
  if (!poData) {
    return NextResponse.json(
      { error: "Orden de compra no encontrada o no pertenece al convenio" },
      { status: 404 },
    ) as NextResponse;
  }
  const purchaseOrder = poData as Record<string, unknown>;
  if (purchaseOrder.status !== "active") {
    return NextResponse.json(
      { error: "La orden de compra no está activa" },
      { status: 400 },
    ) as NextResponse;
  }

  const rules = (agreement.billing_rules || {}) as Record<string, unknown>;
  const copagoPercent = (rules.copago_percent as number) ?? 20;
  const _institutionalPercent = (rules.institutional_percent as number) ?? 80;
  const copagoAmount =
    Math.round((totalAmount as number) * (copagoPercent / 100) * 100) / 100;
  const institutionalAmount =
    Math.round(((totalAmount as number) - copagoAmount) * 100) / 100;

  if (purchaseOrder.max_amount != null) {
    const newUsed =
      ((purchaseOrder.used_amount as number) || 0) + institutionalAmount;
    if (newUsed > (purchaseOrder.max_amount as number)) {
      return NextResponse.json(
        { error: "La OC excede el monto máximo autorizado" },
        { status: 400 },
      ) as NextResponse;
    }
  }

  return { agreement, purchaseOrder, copagoAmount, institutionalAmount };
}

/**
 * Process Sale Business Lookups — customer, agreement, quote, lens, prescription, order number.
 *
 * Extracted from processSaleHandler.ts. No behavioral changes.
 */

import type { SupabaseClient } from "@supabase/supabase-js";
import { NextResponse } from "next/server";

import { buildCustomerName,buildOrderItems } from "./processResponseBuilder";
import { handleAgreementLookups } from "./processSaleAgreementLookups";
import { computeOrderNumber } from "./processSaleValidation";

export interface BusinessLookupParams {
  supabase: SupabaseClient;
  validatedBody: Record<string, unknown>;
  effectiveBranchId: string | null;
  user: { id: string };
}

export interface BusinessLookupResult {
  customer: Record<string, unknown> | null;
  agreement: Record<string, unknown> | null;
  purchaseOrder: Record<string, unknown> | null;
  copagoAmount: number | null;
  institutionalAmount: number | null;
  quote: Record<string, unknown> | null;
  lensFamily: Record<string, unknown> | null;
  lensInfo: Record<string, unknown>;
  orderNumber: string;
  orderItems: Array<Record<string, unknown>>;
  customerName: string | null;
  billingFirstName: string | null;
  billingLastName: string | null;
  orderOrganizationId: string | null;
  frameInfo: Record<string, unknown>;
  treatmentsCost: number;
  laborCost: number;
  productsForStockCheck: Array<Record<string, unknown>>;
}

export async function handleBusinessLookups(
  params: BusinessLookupParams,
): Promise<BusinessLookupResult | NextResponse> {
  const { supabase, validatedBody, effectiveBranchId, user } = params;

  const {
    email,
    customer_id,
    customer_name,
    customer_rut,
    sii_business_name,
    items,
    lens_data,
    frame_data,
    agreement_id,
    purchase_order_id,
    quote_id,
    total_amount,
  } = validatedBody as Record<string, unknown>;

  const itemsArr = (items || []) as Array<Record<string, unknown>>;

  // Frame and lens info
  const validationModule = await import("./processSaleValidation");
  const frameInfo = validationModule.extractFrameInfo(
    frame_data as Record<string, unknown> | null | undefined,
    itemsArr as unknown,
  );
  const lensInfo = validationModule.extractLensInfo(
    lens_data as Record<string, unknown> | null | undefined,
    itemsArr as unknown,
  );
  const treatmentsCost = validationModule.extractTreatmentsCost(itemsArr as unknown);
  const laborCost = validationModule.extractLaborCost(itemsArr as unknown);

  // Customer lookup
  let customer: Record<string, unknown> | null = null;
  if (customer_id) {
    const { data: customerData } = await supabase
      .from("customers")
      .select("id, first_name, last_name, email, phone, rut")
      .eq("id", customer_id as string)
      .single();
    if (!customerData) {
      return NextResponse.json({ error: "Customer not found" }, { status: 404 }) as NextResponse;
    }
    customer = customerData as Record<string, unknown>;
  } else {
    customer = {
      id: null,
      first_name: ((customer_name as string) || "").split(" ")[0] || null,
      last_name: ((customer_name as string) || "").split(" ").slice(1).join(" ") || null,
      email: email || null,
      phone: null,
      rut: customer_rut || null,
    };
  }

  // Agreement + purchase order validation
  const agreementResult = await handleAgreementLookups(
    supabase,
    agreement_id as string | undefined,
    purchase_order_id as string | undefined,
    total_amount as number | undefined,
  );
  if (agreementResult instanceof NextResponse) {
    return agreementResult;
  }
  const { agreement, purchaseOrder, copagoAmount, institutionalAmount } = agreementResult;

  // Quote validation
  let quote: Record<string, unknown> | null = null;
  if (quote_id) {
    const { data: quoteData } = await supabase
      .from("quotes")
      .select("id, status, converted_to_work_order_id, customer_id")
      .eq("id", quote_id as string)
      .single();
    if (!quoteData) {
      return NextResponse.json({ error: "Presupuesto no encontrado" }, { status: 404 }) as NextResponse;
    }
    quote = quoteData as Record<string, unknown>;
    if (quote.status === "converted_to_work" || quote.converted_to_work_order_id) {
      return NextResponse.json({ error: "Este presupuesto ya fue utilizado" }, { status: 400 }) as NextResponse;
    }
  }

  // Lens family validation
  const lensInfoRecord = lensInfo as unknown;
  let lensFamily: Record<string, unknown> | null = null;
  if (lensInfoRecord.lens_family_id) {
    const { data: family } = await supabase
      .from("lens_families")
      .select("id, name, lens_type, lens_material, is_active")
      .eq("id", lensInfoRecord.lens_family_id as string)
      .single();
    if (!family) {
      return NextResponse.json({ error: "Familia de lentes no encontrada" }, { status: 400 }) as NextResponse;
    }
    lensFamily = family as Record<string, unknown>;
    if (!lensFamily.is_active) {
      return NextResponse.json({ error: "La familia de lentes está desactivada" }, { status: 400 }) as NextResponse;
    }
    if (lensInfoRecord.lens_type && lensInfoRecord.lens_type !== lensFamily.lens_type) {
      lensInfoRecord.lens_type = lensFamily.lens_type;
    }
    if (lensInfoRecord.lens_material && lensInfoRecord.lens_material !== lensFamily.lens_material) {
      lensInfoRecord.lens_material = lensFamily.lens_material;
    }
  }

  // Prescription validation
  if (lensInfoRecord.prescription_id) {
    const { data: prescription } = await supabase
      .from("prescriptions")
      .select("id, customer_id, od_sphere, od_cylinder, os_sphere, os_cylinder")
      .eq("id", lensInfoRecord.prescription_id as string)
      .single();
    if (!prescription) {
      return NextResponse.json({ error: "Receta no encontrada" }, { status: 400 }) as NextResponse;
    }
    const prescRecord = prescription as Record<string, unknown>;
    if (customer_id && prescRecord.customer_id !== customer_id) {
      return NextResponse.json(
        { error: "La receta no pertenece al cliente seleccionado" },
        { status: 400 },
      ) as NextResponse;
    }

    if (lensInfoRecord.lens_family_id) {
      const sphere =
        Math.abs(prescRecord.od_sphere as number || 0) >=
        Math.abs(prescRecord.os_sphere as number || 0)
          ? prescRecord.od_sphere || 0
          : prescRecord.os_sphere || 0;
      const cylinder =
        Math.abs(prescRecord.od_cylinder as number || 0) >=
        Math.abs(prescRecord.os_cylinder as number || 0)
          ? prescRecord.od_cylinder || 0
          : prescRecord.os_cylinder || 0;

      const { data: priceMatrix } = await supabase.rpc(
        "calculate_lens_price",
        { p_lens_family_id: lensInfoRecord.lens_family_id, p_sphere: sphere, p_cylinder: cylinder || 0 },
      );
      if (priceMatrix && (priceMatrix as Array<unknown>).length > 0 && (lensInfoRecord.lens_cost as number) > 0) {
        const expectedPrice = (priceMatrix as Array<Record<string, unknown>>)[0].price as number;
        const diff = Math.abs((lensInfoRecord.lens_cost as number) - expectedPrice);
        if (diff > expectedPrice * 0.05) {
          const { appLogger } = await import("@/lib/logger");
          appLogger.warn("Lens price differs significantly from matrix", { expected: expectedPrice, actual: lensInfoRecord.lens_cost });
        }
      }
    }
  }

  // Order number
  const dateStr = new Date().toISOString().slice(0, 10).replace(/-/g, "");
  const { data: lastOrder } = await supabase
    .from("orders")
    .select("order_number")
    .like("order_number", `ORD-${dateStr}-%`)
    .order("created_at", { ascending: false })
    .limit(1)
    .maybeSingle();
  const orderNumber = computeOrderNumber(
    (lastOrder as Record<string, unknown> | null)?.order_number as string | null,
  );

  const orderItems = buildOrderItems(itemsArr as unknown) as Array<Record<string, unknown>>;

  const { customerName, billingFirstName, billingLastName } = buildCustomerName({
    customer: customer as Record<string, unknown> | null,
    customerName: customer_name as string | null,
    siiBusinessName: sii_business_name as string | null,
    customerId: customer_id as string | null,
  });

  // Organization ID resolution
  let orderOrganizationId: string | null = null;
  if (effectiveBranchId) {
    const { data: branchRow } = await supabase
      .from("branches")
      .select("organization_id")
      .eq("id", effectiveBranchId)
      .single();
    orderOrganizationId = (branchRow as Record<string, unknown> | null)?.organization_id as string | null;
  }
  if (!orderOrganizationId) {
    const { data: adminRow } = await supabase
      .from("admin_users")
      .select("organization_id")
      .eq("id", user.id)
      .single();
    orderOrganizationId = (adminRow as Record<string, unknown> | null)?.organization_id as string | null;
  }

  // Products for stock
  const productIdsForStock = itemsArr
    .map((item) => item.product_id as string)
    .filter(
      (id) =>
        !!id &&
        !id.includes("frame-manual") &&
        !id.includes("lens-") &&
        !id.includes("treatments-") &&
        !id.includes("labor-") &&
        !id.includes("discount-"),
    );

  let productsForStockCheck: Array<Record<string, unknown>> = [];
  if (productIdsForStock.length > 0) {
    const { data: products } = await supabase
      .from("products")
      .select("id, name, product_type")
      .in("id", productIdsForStock);
    productsForStockCheck = (products || []) as Array<Record<string, unknown>>;
  }

  return {
    customer,
    agreement,
    purchaseOrder,
    copagoAmount,
    institutionalAmount,
    quote,
    lensFamily,
    lensInfo: lensInfoRecord as Record<string, unknown>,
    orderNumber,
    orderItems,
    customerName,
    billingFirstName,
    billingLastName,
    orderOrganizationId,
    frameInfo: frameInfo as Record<string, unknown>,
    treatmentsCost,
    laborCost,
    productsForStockCheck,
  };
}

/**
 * Process Sale Handler — orchestrates validation, lookups, stock, and dispatch.
 *
 * Thin composer: delegates to extracted services for auth/session, business
 * lookups, stock/work-order, and payment computation. Pure extraction —
 * no behavioral changes.
 */

import { NextRequest, NextResponse } from "next/server";

import { ValidationError } from "@/lib/api/errors";
import {
  createApiSuccessResponse,
} from "@/lib/api/response";
import {
  parseAndValidateBody,
  validationErrorResponse,
} from "@/lib/api/validation/zod-helpers";
import { processSaleSchema } from "@/lib/api/validation/zod-schemas";
import { appLogger as logger } from "@/lib/logger";
import { createClient } from "@/utils/supabase/server";

import { handleAuthSession } from "./processAuthSession";
import { handleLegacyPath } from "./processLegacyHandler";
import {
  computeDbPaymentMethod,
  computePaymentAmount,
} from "./processPaymentUtils";
import { handleRpcPath } from "./processRpcHandler";
import { handleBusinessLookups } from "./processSaleBusinessLookups";
import { handleStockAndWorkOrder } from "./processSaleStockAndWorkOrder";
import type { ProcessSaleContext } from "./processSaleTypes";

export async function handleProcessSale(
  request: NextRequest,
): Promise<NextResponse> {
  logger.info("POS Process Sale API called");

  // Validate request body
  let validatedBody: Record<string, unknown>;
  try {
    validatedBody = await parseAndValidateBody(request, processSaleSchema);
  } catch (error) {
    if (error instanceof ValidationError) return validationErrorResponse(error);
    throw error;
  }

  // 1. Auth + Session
  const authResult = await handleAuthSession(request, validatedBody);
  if (authResult instanceof NextResponse) return authResult;

  const {
    user,
    effectiveBranchId,
    fieldOperationId,
    posSessionId,
    siiInvoiceNumber,
  } = authResult;

  const supabase = await createClient();

  // Idempotency check
  const idempotency_key = validatedBody.idempotency_key as string | undefined;
  if (idempotency_key) {
    const { data: existing } = await supabase
      .from("pos_sale_idempotency")
      .select("response_snapshot")
      .eq("idempotency_key", idempotency_key)
      .maybeSingle();
    if ((existing as Record<string, unknown> | null)?.response_snapshot) {
      const existingRecord = existing as Record<string, unknown>;
      logger.info("Idempotency hit", { idempotency_key });
      return createApiSuccessResponse(existingRecord.response_snapshot);
    }
  }

  // 2. Business lookups
  const lookupResult = await handleBusinessLookups({
    supabase,
    validatedBody,
    effectiveBranchId,
    user,
  });
  if (lookupResult instanceof NextResponse) return lookupResult;

  const {
    customer,
    purchaseOrder,
    copagoAmount,
    institutionalAmount,
    quote,
    lensFamily,
    lensInfo,
    orderNumber,
    orderItems,
    customerName,
    billingFirstName,
    billingLastName,
    orderOrganizationId,
    frameInfo,
    treatmentsCost,
    laborCost,
    productsForStockCheck,
  } = lookupResult;

  // 3. Stock + Work order
  const stockResult = await handleStockAndWorkOrder({
    validatedBody,
    effectiveBranchId,
    fieldOperationId,
    productsForStockCheck,
  });
  if (stockResult instanceof NextResponse) return stockResult;

  const { actuallyRequiresWorkOrder } = stockResult;

  // Payment computation
  const {
    agreement_id,
    deposit_amount,
    cash_received,
    total_amount,
    payment_method_type,
    payments: paymentsArray,
    subtotal,
    tax_amount,
    currency,
    payment_status,
    email,
    customer_id,
    customer_name,
    customer_rut,
    sii_rut,
    sii_business_name,
    fiscal_reference,
    change_amount,
    quote_id,
    presbyopia_solution,
    far_lens_family_id,
    near_lens_family_id,
    far_lens_cost,
    near_lens_cost,
    contact_lens_family_id,
    contact_lens_quantity,
    contact_lens_cost,
    contact_lens_rx_sphere_od,
    contact_lens_rx_cylinder_od,
    contact_lens_rx_axis_od,
    contact_lens_rx_add_od,
    contact_lens_rx_base_curve_od,
    contact_lens_rx_diameter_od,
    contact_lens_rx_sphere_os,
    contact_lens_rx_cylinder_os,
    contact_lens_rx_axis_os,
    contact_lens_rx_add_os,
    contact_lens_rx_base_curve_os,
    contact_lens_rx_diameter_os,
  } = validatedBody as Record<string, unknown>;

  const paymentAmount = computePaymentAmount({
    agreementId: agreement_id as string | null,
    copagoAmount,
    paymentsArray: (paymentsArray || []) as Array<{ amount: number; method: string }>,
    depositAmount: deposit_amount as number | null,
    cashReceived: cash_received as number | null,
    totalAmount: total_amount as number,
  });
  const dbPaymentMethod = computeDbPaymentMethod({
    agreementId: agreement_id as string | null,
