/**
 * Process Sale Stock & Work Order — stock validation and work order decision.
 *
 * Extracted from processSaleHandler.ts. No behavioral changes.
 */

import { NextResponse } from "next/server";

import { APIError } from "@/lib/api/errors";
import { createApiErrorResponse } from "@/lib/api/response";
import { createClient } from "@/utils/supabase/server";

export interface StockAndWorkOrderParams {
  validatedBody: Record<string, unknown>;
  effectiveBranchId: string | null;
  fieldOperationId: string | null;
  productsForStockCheck: Array<Record<string, unknown>>;
}

export interface StockAndWorkOrderResult {
  actuallyRequiresWorkOrder: boolean;
  hasOnlyNonWorkOrderProducts: boolean;
}

export async function handleStockAndWorkOrder(
  params: StockAndWorkOrderParams,
): Promise<StockAndWorkOrderResult | NextResponse> {
  const { validatedBody, effectiveBranchId, fieldOperationId, productsForStockCheck } = params;
  const supabase = await createClient();

  const {
    items,
    lens_data,
    contact_lens_family_id,
    contact_lens_cost,
    presbyopia_solution,
    customer_id,
  } = validatedBody as Record<string, unknown>;

  const itemsArr = (items || []) as Array<Record<string, unknown>>;
  const useMobileStock = !!fieldOperationId;

  // Stock validation
  if (effectiveBranchId || (useMobileStock && fieldOperationId)) {
    const { getOperativoMobileAvailableQuantity } = await import(
      "@/lib/inventory/operativo-mobile-stock-helpers"
    );
    const { getAvailableQuantity } = await import(
      "@/lib/inventory/stock-helpers"
    );

    for (const item of itemsArr) {
      const pid = item.product_id as string | undefined;
      if (
        pid &&
        !pid.includes("frame-manual") &&
        !pid.includes("lens-") &&
        !pid.includes("treatments-") &&
        !pid.includes("labor-") &&
        !pid.includes("discount-")
      ) {
        const product = productsForStockCheck.find((p) => p.id === pid);
        if ((product as Record<string, unknown> | undefined)?.product_type === "service") continue;

        const availableQty = useMobileStock
          ? await getOperativoMobileAvailableQuantity(pid, fieldOperationId!, supabase)
          : await getAvailableQuantity(pid, effectiveBranchId!, supabase);

        if (availableQty < (item.quantity as number)) {
          const productName = (product as Record<string, unknown> | undefined)?.name || pid;
          const msg = useMobileStock
            ? `Stock insuficiente en bodega móvil para ${productName}. Disponible: ${availableQty}, solicitado: ${item.quantity}`
            : `Stock insuficiente para ${productName}. Disponible: ${availableQty}, solicitado: ${item.quantity}`;
          return createApiErrorResponse(new APIError(msg, 400, "INSUFFICIENT_STOCK")) as NextResponse;
        }
      }
    }
  }

  // Work order decision
  const hasTemporaryLensItems = itemsArr.some(
    (item) =>
      !item.product_id ||
      (item.product_id as string).includes("lens-") ||
      (item.product_id as string).includes("treatments-") ||
      (item.product_id as string).includes("labor-") ||
      (item.product_id as string).includes("frame-manual-"),
  );

  let hasFrameInItems = false;
  let productTypesInItems: string[] = [];
  let productCategories: Array<Record<string, unknown>> = [];
  const productIds = itemsArr
    .map((item) => item.product_id as string)
    .filter(
      (id) =>
        !!id &&
        !id.includes("lens-") &&
        !id.includes("treatments-") &&
        !id.includes("labor-") &&
        !id.includes("frame-manual-") &&
        !id.includes("discount-"),
    );
  if (productIds.length > 0) {
    const { data: products } = await supabase
      .from("products")
      .select("id, product_type, category_id, categories:category_id(name)")
      .in("id", productIds);
    const typedProducts = (products || []) as Array<Record<string, unknown>>;
    hasFrameInItems = typedProducts.some((p) => p.product_type === "frame");
    productTypesInItems = typedProducts.map((p) => (p.product_type as string) || "");
    productCategories = typedProducts.map((p) => {
      const cat = Array.isArray(p.categories)
        ? (p.categories as Array<Record<string, unknown>>)[0]
        : (p.categories as Record<string, unknown>);
      return { id: p.id, category_name: cat?.name ?? null };
    });
  }

  const { haveOnlyNonWorkOrderProducts, hasLensDataForMounting, computeWorkOrderDecision } = await import(
    "./processSaleValidation"
  );

  const hasOnlyNonWorkOrderProductTypes = haveOnlyNonWorkOrderProducts(productTypesInItems);
  const nonWorkOrderCategoryNames = [
    "accesorio", "accesorios", "lente de sol", "lentes de sol", "servicio", "servicios",
  ];
  const hasOnlyNonWorkOrderProductCategories =
    productCategories.length > 0 &&
    productCategories.every((cat) => {
      if (!cat.category_name) return false;
      return nonWorkOrderCategoryNames.some((n) =>
        (cat.category_name as string).toLowerCase().includes(n),
      );
    });
  const hasOnlyNonWorkOrderProds =
    hasOnlyNonWorkOrderProductTypes || hasOnlyNonWorkOrderProductCategories;
  const lensDataForMounting = hasLensDataForMounting(
    lens_data as Record<string, unknown> | null | undefined,
    contact_lens_family_id as string | null,
    contact_lens_cost as number | null,
    presbyopia_solution as string | null,
  );
  const actuallyRequiresWorkOrder = computeWorkOrderDecision({
    hasTemporaryLensItems,
    hasFrameInItems,
    hasLensDataForMounting: lensDataForMounting,
    customerId: customer_id as string | null,
    hasOnlyNonWorkOrderProducts: hasOnlyNonWorkOrderProds,
  });

  if (actuallyRequiresWorkOrder && !customer_id) {
    return NextResponse.json(
      { error: "Se requiere un cliente registrado para crear trabajos de laboratorio" },
      { status: 400 },
    ) as NextResponse;
  }

  return { actuallyRequiresWorkOrder, hasOnlyNonWorkOrderProducts: hasOnlyNonWorkOrderProds };
}

/**
 * Process Sale Validation — pure functions for request validation and data extraction.
 *
 * Extracted from process-sale/route.ts T-121. All functions are pure
 * (no side effects, no DB calls) — just shape transformations and boolean logic.
 */

// ─── Types ───────────────────────────────────────────────────────────────────

export interface FrameInfo {
  frame_product_id: string | null;
  frame_name: string;
  frame_brand: string | null;
  frame_model: string | null;
  frame_color: string | null;
  frame_size: string | null;
  frame_sku: string | null;
  frame_cost: number;
  customer_own_frame: boolean;
}

export interface LensInfo {
  lens_family_id: string | null;
  lens_type: string;
  lens_material: string;
  lens_index: number | null;
  lens_treatments: string[];
  lens_tint_color: string | null;
  lens_tint_percentage: number | null;
  lens_cost: number;
  prescription_id: string | null;
}

export interface WorkOrderDecisionParams {
  hasTemporaryLensItems: boolean;
  hasFrameInItems: boolean;
  hasLensDataForMounting: boolean;
  customerId: string | null;
  hasOnlyNonWorkOrderProducts: boolean;
}

export interface Item {
  product_id?: string;
  product_name: string;
  unit_price: number;
  quantity: number;
  [key: string]: unknown;
}

export interface FrameData {
  frame_product_id?: string | null;
  frame_name?: string | null;
  frame_brand?: string | null;
  frame_model?: string | null;
  frame_color?: string | null;
  frame_size?: string | null;
  frame_sku?: string | null;
  customer_own_frame?: boolean | null;
  [key: string]: unknown;
}

export interface LensData {
  lens_family_id?: string | null;
  lens_type?: string | null;
  lens_material?: string | null;
  lens_index?: number | null;
  lens_treatments?: string[];
  lens_tint_color?: string | null;
  lens_tint_percentage?: number | null;
  prescription_id?: string | null;
  [key: string]: unknown;
}

// ─── Frame Info Extraction ───────────────────────────────────────────────────

export function extractFrameInfo(
  frameData: FrameData | null | undefined,
  items: Item[],
): FrameInfo {
  const result: FrameInfo = {
    frame_product_id: null,
    frame_name: "Marco",
    frame_brand: null,
    frame_model: null,
    frame_color: null,
    frame_size: null,
    frame_sku: null,
    frame_cost: 0,
    customer_own_frame: false,
  };

  // Use structured data if available (preferred method)
  if (frameData) {
    result.frame_product_id = frameData.frame_product_id || null;
    result.frame_name = frameData.frame_name || "Marco";
    result.frame_brand = frameData.frame_brand || null;
    result.frame_model = frameData.frame_model || null;
    result.frame_color = frameData.frame_color || null;
    result.frame_size = frameData.frame_size || null;
    result.frame_sku = frameData.frame_sku || null;
    result.frame_cost = 0; // Will be extracted from items
    result.customer_own_frame = frameData.customer_own_frame || false;
  }

  // Extract cost and fallback data from items
  for (const item of items) {
    const itemName = item.product_name.toLowerCase();
    const itemId = item.product_id || "";

    if (
      itemId.includes("frame") ||
      itemName.includes("marco") ||
      itemName.includes("frame")
    ) {
      if (!frameData) {
        result.frame_name = item.product_name;
        result.frame_cost = item.unit_price;
        if (
          item.product_id &&
          !item.product_id.includes("frame-manual") &&
          !item.product_id.includes("-")
        ) {
          result.frame_product_id = item.product_id;
        }
      } else {
        result.frame_cost = item.unit_price;
      }
    }
  }

  return result;
}

// ─── Lens Info Extraction ────────────────────────────────────────────────────

export function extractLensInfo(
  lensData: LensData | null | undefined,
  items: Item[],
): LensInfo {
  const result: LensInfo = {
    lens_family_id: null,
    lens_type: "single_vision",
    lens_material: "cr39",
    lens_index: null,
    lens_treatments: [],
    lens_tint_color: null,
    lens_tint_percentage: null,
    lens_cost: 0,
    prescription_id: null,
  };

  if (lensData) {
    result.lens_family_id = lensData.lens_family_id || null;
    result.lens_type = lensData.lens_type || "single_vision";
    result.lens_material = lensData.lens_material || "cr39";
    result.lens_index = lensData.lens_index || null;
    result.lens_treatments = lensData.lens_treatments || [];
    result.lens_tint_color = lensData.lens_tint_color || null;
    result.lens_tint_percentage = lensData.lens_tint_percentage || null;
    result.lens_cost = 0; // Will be extracted from items
    result.prescription_id = lensData.prescription_id || null;
  }

  for (const item of items) {
    const itemName = item.product_name.toLowerCase();
    const itemId = item.product_id || "";

    if (
      itemId.includes("lens") ||
      itemName.includes("lente") ||
      itemName.includes("lens")
    ) {
      if (!lensData) {
        result.lens_cost = item.unit_price;
        const lensMatch = item.product_name.match(/lente\s+(\w+)\s+(\w+)/i);
        if (lensMatch) {
          result.lens_type = lensMatch[1];
          result.lens_material = lensMatch[2];
        }
      } else {
        result.lens_cost = item.unit_price;
      }
    }
  }

  return result;
}

// ─── Cost Extractors ─────────────────────────────────────────────────────────

export function extractTreatmentsCost(items: Item[]): number {
  return items.reduce((sum, item) => {
    const itemId = item.product_id || "";
    const itemName = item.product_name.toLowerCase();
    if (
      itemId.includes("treatments") ||
      itemName.includes("tratamiento") ||
      itemName.includes("treatment")
    ) {
      return sum + item.unit_price;
    }
    return sum;
  }, 0);
}

export function extractLaborCost(items: Item[]): number {
  return items.reduce((sum, item) => {
    const itemId = item.product_id || "";
    const itemName = item.product_name.toLowerCase();
    if (
      itemId.includes("labor") ||
      itemName.includes("mano de obra") ||
      itemName.includes("montaje")
    ) {
      return sum + item.unit_price;
    }
    return sum;
  }, 0);
}

// ─── Order Number Generation ─────────────────────────────────────────────────

export function computeOrderNumber(
  lastOrderNumber: string | null,
  now: Date = new Date(),
): string {
  const dateStr = now.toISOString().slice(0, 10).replace(/-/g, "");
  if (lastOrderNumber) {
    const match = lastOrderNumber.match(/-(\d+)$/);
    const lastNum = match ? parseInt(match[1], 10) : 0;
    return `ORD-${dateStr}-${String(lastNum + 1).padStart(4, "0")}`;
  }
  return `ORD-${dateStr}-0001`;
}

// ─── Work Order Decision ─────────────────────────────────────────────────────

export function computeWorkOrderDecision(
  params: WorkOrderDecisionParams,
): boolean {
  const {
    hasTemporaryLensItems,
    hasFrameInItems,
    hasLensDataForMounting,
    hasOnlyNonWorkOrderProducts,
  } = params;

  return (
    !hasOnlyNonWorkOrderProducts &&
    (hasTemporaryLensItems || (hasFrameInItems && hasLensDataForMounting))
  );
}

// ─── Min Deposit ─────────────────────────────────────────────────────────────

export function computeMinDepositFallback(totalAmount: number): number {
  return totalAmount * 0.5;
}

// ponytail: order_total based 50% fallback, per-branch config if custom thresholds needed

// ─── Non-Work-Order Product Types ────────────────────────────────────────────

const NON_WORK_ORDER_TYPES = ["accessory", "sunglasses", "service", "lens"];

export function isNonWorkOrderItem(
  productType: string | undefined | null,
): boolean {
  if (!productType) return false;
  return NON_WORK_ORDER_TYPES.includes(productType);
}

export function haveOnlyNonWorkOrderProducts(
  productTypesInItems: string[],
): boolean {
  return (
    productTypesInItems.length > 0 &&
    productTypesInItems.every((type) => !type || isNonWorkOrderItem(type))
  );
}

export function hasLensDataForMounting(
  lensData: LensData | null | undefined,
  contactLensFamilyId: string | null | undefined,
  contactLensCost: number | null | undefined,
  presbyopiaSolution: string | null | undefined,
): boolean {
  return !!(
    (lensData &&
      (lensData.lens_family_id ||
        lensData.lens_type ||
        lensData.lens_material ||
        lensData.prescription_id)) ||
    presbyopiaSolution !== "none" ||
    contactLensFamilyId ||
    contactLensCost
  );
}

/**
 * Stock Reduction Helpers for POS Legacy Sale
 * Extracted from processLegacyHandler.ts
 */
import { DEFAULT_LOW_STOCK_THRESHOLD } from "@/lib/inventory/constants";
import {
  reduceOperativoMobileStock,
} from "@/lib/inventory/operativo-mobile-stock-helpers";
import { appLogger as logger } from "@/lib/logger";

import type { ProcessSaleContext } from "./processSaleTypes";

export async function reduceStock(ctx: ProcessSaleContext, orderId: string): Promise<boolean> {
  const useMobileStock = !!ctx.fieldOperationId;

  for (const item of ctx.items) {
    const pid = item.product_id as string | undefined;
    if (!pid || pid.includes("frame-manual") || pid.includes("lens-") ||
        pid.includes("treatments-") || pid.includes("labor-") || pid.includes("discount-")) {
      continue;
    }

    const product = ctx.productsForStockCheck.find((p: Record<string, unknown>) => p.id === pid);
    if ((product as Record<string, unknown> | undefined)?.product_type === "service") {
      logger.info("Skipping stock update for service product", { product_id: pid });
      continue;
    }

    if (useMobileStock && ctx.fieldOperationId) {
      const reduceResult = await reduceOperativoMobileStock(pid, ctx.fieldOperationId, item.quantity as number, ctx.supabase);
      if (!reduceResult.success) {
        logger.error(`Error reducing operativo mobile stock for product ${pid}`, { error: reduceResult.error });
        return false;
      }
      logger.info("Operativo mobile stock reduced", { product_id: pid, quantity_decreased: item.quantity });
    } else {
      const branchId = ctx.effectiveBranchId;
      if (!branchId) {
        logger.warn(`Cannot update inventory: no branch_id for product ${pid}`);
        continue;
      }

      const { data: currentStock } = await ctx.supabase
        .from("product_branch_stock").select("quantity").eq("product_id", pid).eq("branch_id", branchId).maybeSingle();
      const currentQuantity = (currentStock as { quantity?: number } | null)?.quantity || 0;

      if (!currentStock && currentQuantity === 0) {
        await ctx.supabase.from("product_branch_stock").insert({
          product_id: pid, branch_id: branchId, quantity: 0, reserved_quantity: 0, low_stock_threshold: DEFAULT_LOW_STOCK_THRESHOLD,
        });
      }

      const { error: inventoryError } = await ctx.supabase.rpc("update_product_stock", {
        p_product_id: pid, p_branch_id: branchId, p_quantity_change: -(item.quantity as number),
        p_reserve: false, p_movement_type: "sale", p_reference_type: "order", p_reference_id: orderId, p_created_by: ctx.user.id,
      });
      if (inventoryError) {
        logger.error(`Error updating inventory for product ${pid}`, { error: inventoryError });
      }
    }
  }
  return true;
}

export async function reduceContactLensStock(ctx: ProcessSaleContext): Promise<void> {
  if (!ctx.contact_lens_family_id || !(ctx.contact_lens_quantity || 0)) return;

  const branchId = ctx.effectiveBranchId;
  if (ctx.contact_lens_rx_sphere_od != null) {
    const odReduction = await ctx.supabase.rpc("reduce_contact_lens_stock", {
      p_contact_lens_family_id: ctx.contact_lens_family_id, p_branch_id: branchId,
      p_sphere: ctx.contact_lens_rx_sphere_od, p_cylinder: ctx.contact_lens_rx_cylinder_od || 0,
      p_quantity: ctx.contact_lens_quantity,
    });
    if (odReduction.error) logger.error("Error reducing contact lens stock (OD)", { error: odReduction.error });
  }
  if (ctx.contact_lens_rx_sphere_os != null) {
    const osReduction = await ctx.supabase.rpc("reduce_contact_lens_stock", {
      p_contact_lens_family_id: ctx.contact_lens_family_id, p_branch_id: branchId,
      p_sphere: ctx.contact_lens_rx_sphere_os, p_cylinder: ctx.contact_lens_rx_cylinder_os || 0,
      p_quantity: ctx.contact_lens_quantity,
    });
    if (osReduction.error) logger.error("Error reducing contact lens stock (OS)", { error: osReduction.error });
  }
}

/**
 * Stock reversal logic for POS refund.
 *
 * Extracted from route.ts to reduce file size.
 */
import type { SupabaseClient } from "@supabase/supabase-js";

import { appLogger as logger } from "@/lib/logger";

export async function reverseRefundStock(
  supabase: SupabaseClient,
  items: { order_item_id: string; quantity: number }[],
  orderItems: {
    id: string;
    product_id: string | null;
    product_name: string;
    quantity: number;
  }[],
  branchId: string,
  orderId: string,
  userId: string,
): Promise<string | null> {
  const itemMap = new Map(orderItems.map((oi) => [oi.id, oi]));

  for (const refItem of items) {
    const oi = itemMap.get(refItem.order_item_id);
    if (!oi?.product_id) continue;

    const { error: stockError } = await supabase.rpc("update_product_stock", {
      p_product_id: oi.product_id,
      p_branch_id: branchId,
      p_quantity_change: refItem.quantity,
      p_reserve: false,
      p_movement_type: "refund",
      p_reference_type: "refund",
      p_reference_id: orderId,
      p_created_by: userId,
    });

    if (stockError) {
      logger.error("Error reversing stock on refund", {
        product_id: oi.product_id,
        quantity: refItem.quantity,
        error: stockError,
      });
      return `Error al revertir stock para ${oi.product_name}: ${stockError.message}`;
    }
  }

  return null;
}

