export const dynamic = "force-dynamic";

export async function POST(request: NextRequest) {
  try {
    logger.info("POS Refund API called");

    const supabase = await createClient();

    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return createApiErrorResponse(
        new APIError("Unauthorized", 401, "UNAUTHORIZED"),
      );
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null };
    if (!isAdmin) {
      return createApiErrorResponse(
        new APIError("Admin access required", 403, "FORBIDDEN"),
      );
    }

    const branchContext = await getBranchContext(request, user.id);
    if (!branchContext.isSuperAdmin && !branchContext.branchId) {
      return createApiErrorResponse(
        new APIError(
          "Debe seleccionar una sucursal para realizar devoluciones",
          400,
          "BAD_REQUEST",
        ),
      );
    }

    const body = await request.json();
    const parseResult = refundSchema.safeParse(body);
    if (!parseResult.success) {
      return NextResponse.json(
        { error: "Datos inválidos", details: parseResult.error.flatten() },
        { status: 400 },
      );
    }

    const { order_id, items, reason, refund_type, refund_method } =
      parseResult.data;

    // Fetch order and validate
    const { data: order, error: orderError } = await supabase
      .from("orders")
      .select("id, branch_id, organization_id, status, total_amount")
      .eq("id", order_id)
      .single();

    if (orderError || !order) {
      return createApiErrorResponse(
        new APIError("Orden no encontrada", 404, "NOT_FOUND"),
      );
    }

    // Validate branch access
    if (
      !branchContext.isSuperAdmin &&
      branchContext.branchId &&
      order.branch_id !== branchContext.branchId
    ) {
      return createApiErrorResponse(
        new APIError(
          "La orden no pertenece a la sucursal seleccionada",
          403,
          "FORBIDDEN",
        ),
      );
    }

    const branchId = order.branch_id;
    if (!branchId) {
      return createApiErrorResponse(
        new APIError("La orden no tiene sucursal asociada", 400, "BAD_REQUEST"),
      );
    }

    // Fetch order items to validate
    const orderItemIds = items.map((i) => i.order_item_id);
    const { data: rawOrderItems, error: itemsError } = await supabase
      .from("order_items")
      .select("id, product_id, quantity, unit_price, total_price, product_name")
      .eq("order_id", order_id)
      .in("id", orderItemIds);

    if (itemsError || !rawOrderItems || rawOrderItems.length === 0) {
      return createApiErrorResponse(
        new APIError("No se encontraron los ítems de la orden", 400, "BAD_REQUEST"),
      );
    }

    const orderItems = rawOrderItems as OrderItemEntry[];
    const validationError = validateRefundItems(items, orderItems);
    if (validationError) {
      return createApiErrorResponse(new APIError(validationError, 400, "BAD_REQUEST"));
    }

    // Get total_paid and session
    const { data: payments } = await supabase
      .from("order_payments")
      .select("amount")
      .eq("order_id", order_id);
    const totalPaid = (payments || []).reduce(
      (sum: number, p: { amount: number }) => sum + Number(p.amount || 0), 0,
    );
    const orderTotal = Number(order.total_amount) || 0;

    const { data: session } = await supabase
      .from("pos_sessions")
      .select("id")
      .eq("branch_id", branchId)
      .eq("status", "open")
      .order("opening_time", { ascending: false })
      .limit(1)
      .maybeSingle();
    const posSessionId = session?.id ?? null;

    // Reverse stock
    const stockErrorMsg = await reverseRefundStock(
      supabase,
      items,
      orderItems as { id: string; product_id: string | null; product_name: string; quantity: number }[],
      branchId,
      order_id,
      user.id,
    );
    if (stockErrorMsg) {
      return createApiErrorResponse(
        new APIError(stockErrorMsg, 500, "INTERNAL_ERROR"),
      );
    }

    // Calculate refund amount (capped at total_paid)
    const refundAmount = calculateRefundAmount(items, orderItems, totalPaid, orderTotal);

    // Create credit_note and credit_note_movement for caja integration
    let creditNoteId: string | null = null;
    if (posSessionId && refundAmount > 0) {
      const { data: cnNumberRaw, error: cnNumError } =
        await supabase.rpc("generate_credit_note_number");
      const cnNumber =
        typeof cnNumberRaw === "string"
          ? cnNumberRaw
          : Array.isArray(cnNumberRaw) && cnNumberRaw[0]
            ? cnNumberRaw[0]
            : cnNumberRaw;
      if (!cnNumError && cnNumber && typeof cnNumber === "string") {
        const { data: branchRow } = await supabase
          .from("branches")
          .select("organization_id")
          .eq("id", branchId)
          .single();
        const { data: newCreditNote, error: cnError } =
          await supabase
            .from("credit_notes")
            .insert({
              credit_note_number: cnNumber,
              order_id,
              branch_id: branchId,
              organization_id: (branchRow as unknown)?.organization_id ?? null,
              amount: refundAmount,
              reason,
              refund_method: refund_method ?? "cash",
              pos_session_id: posSessionId,
              created_by: user.id,
            })
            .select("id")
            .single();
        if (!cnError && newCreditNote) {
          creditNoteId = newCreditNote.id;
          await supabase.from("credit_note_movements").insert({
            credit_note_id: creditNoteId,
            pos_session_id: posSessionId,
            amount: -refundAmount,
            refund_method: refund_method ?? "cash",
          });
        }
      }
    }

    // Update order status to cancelled/refunded (removes from pending balance)
    await supabase
      .from("orders")
      .update({
        status: "cancelled",
        payment_status: "refunded",
        cancellation_reason: reason,
        updated_at: new Date().toISOString(),
      })
      .eq("id", order_id);

    // Create pos_transaction for refund (legacy/traceability)
    const { error: txError } = await supabase
      .from("pos_transactions")
      .insert({
        order_id,
        pos_session_id: posSessionId,
        transaction_type: "refund",
        payment_method: refund_method ?? "cash",
        amount: -refundAmount,
        change_amount: null,
        notes: `${reason} | Items: ${items.map((i) => i.order_item_id).join(", ")}`,
      });

    if (txError) {
      logger.warn("Could not create pos_transaction for refund", { txError });
    }

    logger.info("Refund processed successfully", {
      order_id,
      refund_amount: refundAmount,
      items_count: items.length,
      credit_note_id: creditNoteId,
    });

    return createApiSuccessResponse({
      success: true,
      message: "Devolución procesada correctamente",
      refund_amount: refundAmount,
      items_refunded: items.length,
      credit_note_id: creditNoteId ?? undefined,
    });
  } catch (error) {
    logger.error("Error in POS Refund API", error);
    return createApiErrorResponse(
      error instanceof Error ? error : new Error(String(error)),
    );
  }
}

/**
 * Shared helpers for POS settings route.
 *
 * Extracted from route.ts to reduce file size.
 */
import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { rateLimitConfigs, withRateLimit } from "@/lib/rate-limiting";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

export interface AuthContext {
  user: { id: string };
  isSuperAdmin: boolean;
  branchId: string | null;
  organizationId: string | null;
  supabase: Awaited<ReturnType<typeof createClient>>;
}

export async function withPOSAuth(
  request: NextRequest,
  errorPrefix: string,
): Promise<AuthContext | NextResponse> {
  const supabase = await createClient();

  const {
    data: { user },
    error: userError,
  } = await supabase.auth.getUser();
  if (userError || !user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const { data: isAdmin } = (await supabase.rpc("is_admin", {
    user_id: user.id,
  } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
  if (!isAdmin) {
    return NextResponse.json(
      { error: "Admin access required" },
      { status: 403 },
    );
  }

  const branchContext = await getBranchContext(request, user.id);

  if (!branchContext.isSuperAdmin && !branchContext.branchId) {
    return NextResponse.json(
      { error: `Debe seleccionar una sucursal para ${errorPrefix}` },
      { status: 400 },
    );
  }

  return {
    user,
    isSuperAdmin: branchContext.isSuperAdmin,
    branchId: branchContext.branchId,
    organizationId: branchContext.organizationId,
    supabase,
  };
}

export async function withRateLimitWrapper(
  request: NextRequest,
  configName: "general" | "modification",
  handler: () => Promise<NextResponse>,
): Promise<NextResponse> {
  return (await (withRateLimit(rateLimitConfigs[configName]) as unknown)(
    request,
    handler,
  )) as NextResponse;
}

export function getMergedValue(
  settings: Record<string, unknown> | null,
  orgSettings: Record<string, unknown> | null,
  field: string,
  defaultValue: unknown = null,
): unknown {
  if (settings && settings[field] !== null && settings[field] !== undefined) {
    return settings[field];
  }
  if (
    orgSettings &&
    orgSettings[field] !== null &&
    orgSettings[field] !== undefined
  ) {
    return orgSettings[field];
  }
  return defaultValue;
}

import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";

import { createApiSuccessResponse } from "@/lib/api/response";
import { appLogger as logger } from "@/lib/logger";

import {
  getMergedValue,
  withPOSAuth,
  withRateLimitWrapper,
} from "./posSettingsHandler";

const posSettingsSchema = z.object({
  min_deposit_percent: z.number().min(0).max(100).optional(),
  min_deposit_amount: z.number().min(0).optional().nullable(),
  // Billing/Boleta fields
  business_name: z.string().optional().nullable(),
  business_rut: z.string().optional().nullable(),
  business_address: z.string().optional().nullable(),
  business_phone: z.string().optional().nullable(),
  business_email: z.string().optional().nullable(),
  logo_url: z.string().optional().nullable(),
  header_text: z.string().optional().nullable(),
  footer_text: z.string().optional().nullable(),
  terms_and_conditions: z.string().optional().nullable(),
  default_document_type: z.string().optional().nullable(),
  printer_type: z.string().optional().nullable(),
  printer_width_mm: z.number().optional().nullable(),
  printer_height_mm: z.number().optional().nullable(),
  auto_print_receipt: z.boolean().optional().default(true),
});

export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    return await withRateLimitWrapper(request, "general", async () => {
      const auth = await withPOSAuth(request, "ver la configuración del POS");
      if (auth instanceof NextResponse) return auth;
      const { supabase, branchId, organizationId } = auth;

      let settings = null;
      if (branchId) {
        const { data, error: settingsError } = await supabase
          .from("pos_settings")
          .select("*")
          .eq("branch_id", branchId)
          .maybeSingle();
        if (settingsError && settingsError.code !== "PGRST116") {
          logger.error("Error fetching POS settings", settingsError);
        } else {
          settings = data;
        }
      }

      const { data: orgSettings } = await supabase
        .from("organization_settings")
        .select("*")
        .eq("organization_id", organizationId!)
        .maybeSingle();

      return createApiSuccessResponse({
        min_deposit_percent: getMergedValue(settings, orgSettings, "min_deposit_percent", 50.0),
        min_deposit_amount: getMergedValue(settings, orgSettings, "min_deposit_amount", null),
        business_name: getMergedValue(settings, orgSettings, "business_name"),
        business_rut: getMergedValue(settings, orgSettings, "business_rut"),
        business_address: getMergedValue(settings, orgSettings, "business_address"),
        business_phone: getMergedValue(settings, orgSettings, "business_phone"),
        business_email: getMergedValue(settings, orgSettings, "business_email"),
        logo_url: getMergedValue(settings, orgSettings, "logo_url"),
        header_text: getMergedValue(settings, orgSettings, "header_text"),
        footer_text: getMergedValue(settings, orgSettings, "footer_text"),
        terms_and_conditions: getMergedValue(settings, orgSettings, "terms_and_conditions"),
        default_document_type: getMergedValue(settings, orgSettings, "default_document_type", "boleta"),
        printer_type: getMergedValue(settings, orgSettings, "printer_type", "thermal"),
        printer_width_mm: getMergedValue(settings, orgSettings, "printer_width_mm", 80),
        printer_height_mm: getMergedValue(settings, orgSettings, "printer_height_mm", 297),
        auto_print_receipt: getMergedValue(settings, orgSettings, "auto_print_receipt", true),
      });
    });
  } catch (error) {
    logger.error("Error in POS settings GET API", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

export async function PUT(request: NextRequest) {
  try {
    return await withRateLimitWrapper(request, "modification", async () => {
      const auth = await withPOSAuth(request, "actualizar la configuración del POS");
      if (auth instanceof NextResponse) return auth;
      const { supabase, branchId, organizationId, isSuperAdmin } = auth;

      const body = await request.json();
      const validatedData = posSettingsSchema.parse(body);

      let result;

      // GLOBAL UPDATE for Super Admins
      if (!branchId && isSuperAdmin) {
        logger.info("Global POS settings update initiated", { organizationId });

        const { data: orgSettings, error: orgError } = await supabase
          .from("organization_settings")
          .upsert(
            { organization_id: organizationId, ...validatedData, updated_at: new Date().toISOString() },
            { onConflict: "organization_id" },
          )
          .select()
          .single();

        if (orgError) {
          logger.error("Error updating global organization settings", orgError);
          return NextResponse.json(
            { error: "Error al actualizar configuración global de organización" },
            { status: 500 },
          );
        }

        // Sync all branches
        const { data: branches } = await supabase
          .from("branches")
          .select("id")
          .eq("organization_id", organizationId!);
        if (branches && branches.length > 0) {
          for (const b of branches) {
            await supabase.from("pos_settings").upsert(
              { branch_id: b.id, organization_id: organizationId, ...validatedData, updated_at: new Date().toISOString() },
              { onConflict: "branch_id" },
            );
          }
        }

        result = orgSettings;
      } else {
        // BRANCH-SPECIFIC UPDATE
        const { data: existingSettings } = await supabase
          .from("pos_settings")
          .select("id")
          .eq("branch_id", branchId!)
          .maybeSingle();

        if (existingSettings) {
          const { data: updatedSettings, error: updateError } = await supabase
            .from("pos_settings")
            .update({ ...validatedData, updated_at: new Date().toISOString() })
            .eq("branch_id", branchId!)
            .select()
            .single();
          if (updateError) {
            logger.error("Error updating POS settings", updateError);
            return NextResponse.json({ error: "Error al actualizar configuración" }, { status: 500 });
          }
          result = updatedSettings;
        } else {
          const { data: newSettings, error: insertError } = await supabase
            .from("pos_settings")
            .insert({ branch_id: branchId!, organization_id: organizationId, ...validatedData })
            .select()
            .single();
          if (insertError) {
            logger.error("Error creating POS settings", insertError);
            return NextResponse.json({ error: "Error al crear configuración" }, { status: 500 });
          }
          result = newSettings;
        }
      }

      logger.info("POS settings updated successfully", {
        branchId: branchId || "GLOBAL",
        organizationId,
      });

      return createApiSuccessResponse(result);
    });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return NextResponse.json({ error: "Validation failed", details: error.errors }, { status: 400 });
    }
    logger.error("Error in POS settings PUT API", error);
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

import { NextRequest } from "next/server";
import { z } from "zod";

import { addBranchFilter, getBranchContext } from "@/lib/api/branch-middleware";
import { AuthenticationError, AuthorizationError } from "@/lib/api/errors";
import { appLogger as logger } from "@/lib/logger";
import { formatRUT } from "@/lib/utils/rut";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";

const MAX_EXPORT_ROWS = 10000;

const exportQuerySchema = z.object({
  format: z
    .string()
    .transform((v) => (v ? v.toLowerCase().trim() : "csv"))
    .refine((v) => v === "csv" || v === "xlsx", {
      message: "format must be csv or xlsx",
    })
    .transform((v) => v as "csv" | "xlsx"),
  date_from: z
    .union([z.string(), z.null(), z.undefined()])
    .optional()
    .transform((v) =>
      v && typeof v === "string" && /^\d{4}-\d{2}-\d{2}$/.test(v.trim())
        ? v.trim()
        : undefined,
    ),
  date_to: z
    .union([z.string(), z.null(), z.undefined()])
    .optional()
    .transform((v) =>
      v && typeof v === "string" && /^\d{4}-\d{2}-\d{2}$/.test(v.trim())
        ? v.trim()
        : undefined,
    ),
  branch_id: z
    .union([z.string(), z.null(), z.undefined()])
    .optional()
    .transform((v) =>
      v &&
      typeof v === "string" &&
      v.trim() !== "" &&
      /^[0-9a-f-]{36}$/i.test(v.trim())
        ? v.trim()
        : undefined,
    ),
});

export async function GET(request: NextRequest) {
  const requestId = crypto.randomUUID();

  try {
    logger.info("Prescriptions export API GET called", { requestId });

    const supabase = await createClient();

    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      throw new AuthenticationError("Unauthorized");
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      throw new AuthorizationError("Admin access required");
    }

    const branchContext = await getBranchContext(request, user.id);

    const searchParams = request.nextUrl.searchParams;
    const formatParam = searchParams.get("format") || "csv";
    const parsed = exportQuerySchema.safeParse({
      format: formatParam,
      date_from: searchParams.get("date_from"),
      date_to: searchParams.get("date_to"),
      branch_id: searchParams.get("branch_id"),
    });

    if (!parsed.success) {
      return new Response(
        JSON.stringify({
          success: false,
          error: {
            message: "Invalid parameters",
            details: parsed.error.errors,
          },
        }),
        { status: 400, headers: { "Content-Type": "application/json" } },
      );
    }

    const {
      format,
      date_from,
      date_to,
      branch_id: queryBranchId,
    } = parsed.data;

    const effectiveBranchId = queryBranchId ?? branchContext.branchId;

    if (!branchContext.isSuperAdmin && effectiveBranchId === null) {
      return new Response(
        JSON.stringify({
          success: false,
          error: {
            message:
              "Seleccione una sucursal. Solo super administradores en vista global pueden exportar todas las sucursales.",
          },
        }),
        { status: 403, headers: { "Content-Type": "application/json" } },
      );
    }

    let query = supabase
      .from("prescriptions")
      .select("*")
      .order("prescription_date", { ascending: false })
      .limit(MAX_EXPORT_ROWS);

    query = addBranchFilter(
      query,
      effectiveBranchId,
      branchContext.isSuperAdmin,
      branchContext.organizationId,
    );

    if (date_from) query = query.gte("prescription_date", date_from);
    if (date_to) query = query.lte("prescription_date", date_to);

    const { data: prescriptions, error } = await query;

    if (error) {
      logger.error("Error fetching prescriptions for export", {
        error,
        requestId,
      });
      throw new Error(`Failed to fetch prescriptions: ${error.message}`);
    }

    const items = prescriptions || [];

    if (items.length === 0) {
      const dateStr = new Date().toISOString().split("T")[0];
      const ext = format === "csv" ? "csv" : "xlsx";
      const filename = `libro-recetas-${dateStr}.${ext}`;

      if (format === "csv") {
        const csv =
          "Fecha;RUT;Nombre;Profesional;OD Esf;OD Cil;OD Eje;OD Add;OD PD;OS Esf;OS Cil;OS Eje;OS Add;OS PD;Tipo;Nº Receta;Sucursal\n";
        const bom = "\uFEFF";
        return new Response(bom + csv, {
          status: 200,
          headers: {
            "Content-Disposition": `attachment; filename="${filename}"`,
            "Content-Type": "text/csv; charset=utf-8",
          },
        });
      }

      const XLSX = await import("xlsx");
      const worksheet = XLSX.utils.json_to_sheet([]);
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, worksheet, "Libro de Recetas");
      const xlsxBuffer = XLSX.write(workbook, {
        type: "buffer",
        bookType: "xlsx",
      });
      return new Response(xlsxBuffer, {
        status: 200,
        headers: {
          "Content-Disposition": `attachment; filename="${filename}"`,
          "Content-Type":
            "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        },
      });
    }

    const customerIds = [
      ...new Set(items.map((p: { customer_id: string }) => p.customer_id)),
    ];
    const { data: customers } =
      customerIds.length > 0
        ? await supabase
            .from("customers")
            .select("id, first_name, last_name, rut")
            .in("id", customerIds)
        : { data: [] };

    const branchIds = [
      ...new Set(
        items.map((p: { branch_id?: string }) => p.branch_id).filter(Boolean),
      ),
    ];
    const { data: branches } =
      branchIds.length > 0
        ? await supabase
            .from("branches")
            .select("id, name")
            .in("id", branchIds)
        : { data: [] };

    const customerMap = new Map(
      (customers || []).map(
        (c: {
          id: string;
          first_name?: string;
          last_name?: string;
          rut?: string;
        }) => [c.id, c],
      ),
    );
    const branchMap = new Map(
      (branches || []).map((b: { id: string }) => [b.id, b]),
    );

    const rows = items.map((p: Record<string, unknown>) => {
      const c = customerMap.get(p.customer_id as string);
      const b = branchMap.get(p.branch_id as string);
      const fullName = c
        ? `${c.first_name || ""} ${c.last_name || ""}`.trim()
        : "";
      const rutFormatted = c?.rut ? formatRUT(c.rut) : "";
      return {
        fecha: p.prescription_date || "",
        rut: rutFormatted,
        nombre: fullName,
        profesional: p.issued_by || "",
        od_esf: p.od_sphere ?? "",
        od_cil: p.od_cylinder ?? "",
        od_eje: p.od_axis ?? "",
        od_add: p.od_add ?? "",
        od_pd: p.od_pd ?? "",
        os_esf: p.os_sphere ?? "",
        os_cil: p.os_cylinder ?? "",
        os_eje: p.os_axis ?? "",
        os_add: p.os_add ?? "",
        os_pd: p.os_pd ?? "",
        tipo: p.prescription_type || "",
        numero_receta: p.prescription_number || "",
        sucursal: (b as { name?: string })?.name || "",
      };
    });

    const dateStr = new Date().toISOString().split("T")[0];
    const filename = `libro-recetas-${dateStr}.${format === "csv" ? "csv" : "xlsx"}`;

    if (format === "csv") {
      const headers = [
        "Fecha",
        "RUT",
        "Nombre",
        "Profesional",
        "OD Esf",
        "OD Cil",
        "OD Eje",
        "OD Add",
        "OD PD",
        "OS Esf",
        "OS Cil",
        "OS Eje",
        "OS Add",
        "OS PD",
        "Tipo",
        "Nº Receta",
        "Sucursal",
      ];
      const csvRows = [
        headers.join(";"),
        ...rows.map((r) =>
          [
            r.fecha,
            r.rut,
            `"${String(r.nombre).replace(/"/g, '""')}"`,
            `"${String(r.profesional).replace(/"/g, '""')}"`,
            r.od_esf,
            r.od_cil,
            r.od_eje,
            r.od_add,
            r.od_pd,
            r.os_esf,
            r.os_cil,
            r.os_eje,
            r.os_add,
            r.os_pd,
            r.tipo,
            r.numero_receta,
            `"${String(r.sucursal).replace(/"/g, '""')}"`,
          ].join(";"),
        ),
      ];
      const csv = csvRows.join("\n");
      const bom = "\uFEFF";
      const buffer = Buffer.from(bom + csv, "utf-8");

      return new Response(buffer, {
        status: 200,
        headers: {
          "Content-Disposition": `attachment; filename="${filename}"`,
          "Content-Type": "text/csv; charset=utf-8",
        },
      });
    }

    const XLSX = await import("xlsx");
    const worksheet = XLSX.utils.json_to_sheet(rows);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Libro de Recetas");
    const xlsxBuffer = XLSX.write(workbook, {
      type: "buffer",
      bookType: "xlsx",
    });

    return new Response(xlsxBuffer, {
      status: 200,
      headers: {
        "Content-Disposition": `attachment; filename="${filename}"`,
        "Content-Type":
          "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
      },
    });
  } catch (error) {
    logger.error("Error in prescriptions export API", { error, requestId });
    return new Response(
      JSON.stringify({
        success: false,
        error: {
          message:
            error instanceof Error ? error.message : "Internal server error",
        },
      }),
      { status: 500, headers: { "Content-Type": "application/json" } },
    );
  }
}

import { NextRequest } from "next/server";

import { addBranchFilter, getBranchContext } from "@/lib/api/branch-middleware";
import {
  APIError,
  AuthenticationError,
  AuthorizationError,
} from "@/lib/api/errors";
import {
  createApiErrorResponse,
  createPaginatedResponse,
} from "@/lib/api/response";
import {
  parseAndValidateQuery,
  validationErrorResponse,
} from "@/lib/api/validation/zod-helpers";
import { prescriptionListQuerySchema } from "@/lib/api/validation/zod-schemas";
import { appLogger as logger } from "@/lib/logger";
import { normalizeRUT } from "@/lib/utils/rut";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";

export async function GET(request: NextRequest) {
  const requestId = crypto.randomUUID();

  try {
    logger.info("Prescriptions API GET called", { requestId });

    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      logger.error("User authentication failed", {
        error: userError,
        requestId,
      });
      throw new AuthenticationError("Unauthorized");
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      logger.warn("User is not admin", { email: user.email, requestId });
      throw new AuthorizationError("Admin access required");
    }

    // Get branch context
    const branchContext = await getBranchContext(request, user.id);

    // Parse and validate query params
    let queryParams;
    try {
      queryParams = parseAndValidateQuery(request, prescriptionListQuerySchema);
    } catch (error) {
      return validationErrorResponse(
        error as Parameters<typeof validationErrorResponse>[0],
      );
    }

    const {
      q,
      search,
      rut,
      date_from,
      date_to,
      issued_by,
      branch_id: queryBranchId,
      page,
      limit,
    } = queryParams;

    const searchTerm = (q || search || "").trim();
    const normalizedRut = rut ? normalizeRUT(rut) : "";

    // Resolve branch filter: query param overrides header.
    // Only super admin in global view (branchId=null) can see all branches.
    const effectiveBranchId = queryBranchId ?? branchContext.branchId;

    if (!branchContext.isSuperAdmin && effectiveBranchId === null) {
      return createApiErrorResponse(
        new APIError(
          "Seleccione una sucursal para ver las recetas. Solo super administradores en vista global pueden ver todas las sucursales.",
          403,
          "FORBIDDEN",
        ),
        { requestId },
      );
    }

    // Build base query
    let query = supabase
      .from("prescriptions")
      .select("*", { count: "exact" })
      .order("prescription_date", { ascending: false });

    // Apply branch filter (prescriptions has organization_id and branch_id)
    query = addBranchFilter(
      query,
      effectiveBranchId,
      branchContext.isSuperAdmin,
      branchContext.organizationId,
    );

    // Filter by customer search (q or rut)
    if (searchTerm || normalizedRut) {
      const { data: adminUser } = await supabase
        .from("admin_users")
        .select("organization_id")
        .eq("id", user.id)
        .single();

      const userOrganizationId =
        adminUser?.organization_id || branchContext.organizationId;

      if (userOrganizationId) {
        let customersQuery = supabase
          .from("customers")
          .select("id, rut, first_name, last_name, email")
          .eq("organization_id", userOrganizationId)
          .limit(1000);

        if (effectiveBranchId) {
          customersQuery = customersQuery.eq("branch_id", effectiveBranchId);
        } else if (branchContext.isSuperAdmin && branchContext.organizationId) {
          const { data: branches } = await supabase
            .from("branches")
            .select("id")
            .eq("organization_id", branchContext.organizationId);
          const branchIds = branches?.map((b: { id: string }) => b.id) || [];
          if (branchIds.length > 0) {
            customersQuery = customersQuery.in("branch_id", branchIds);
          }
        }

        const { data: customersInOrg } = await customersQuery;

        const matchingIds = (customersInOrg || [])
          .filter(
            (c: {
              rut?: string | null;
              first_name?: string | null;
              last_name?: string | null;
              email?: string | null;
            }) => {
              if (normalizedRut) {
                if (!c.rut) return false;
                const customerRutNorm = normalizeRUT(c.rut);
                return (
                  customerRutNorm === normalizedRut ||
                  customerRutNorm.includes(normalizedRut) ||
                  normalizedRut.includes(customerRutNorm)
                );
              }
              if (searchTerm) {
                const term = searchTerm.toLowerCase();
                const fullName =
                  `${c.first_name || ""} ${c.last_name || ""}`.toLowerCase();
                const rutStr = (c.rut || "").toLowerCase();
                const email = (c.email || "").toLowerCase();
                return (
                  fullName.includes(term) ||
                  rutStr.includes(term) ||
                  email.includes(term)
                );
              }
              return false;
            },
          )
          .map((c: { id: string }) => c.id);

        if (matchingIds.length > 0) {
          query = query.in("customer_id", matchingIds);
        } else {
          query = query.eq(
            "customer_id",
            "00000000-0000-0000-0000-000000000000",
          );
        }
      }
    }

    if (date_from) {
      query = query.gte("prescription_date", date_from);
    }
    if (date_to) {
      query = query.lte("prescription_date", date_to);
    }
    if (issued_by?.trim()) {
      query = query.ilike("issued_by", `%${issued_by.trim()}%`);
    }

    const from = (page - 1) * limit;
    const to = from + limit - 1;

    const { data: prescriptions, error, count } = await query.range(from, to);

    if (error) {
      logger.error("Error fetching prescriptions", {
        error,
        requestId,
      });
      throw new Error(`Failed to fetch prescriptions: ${error.message}`);
    }

    let prescriptionsWithRelations = prescriptions || [];

    if (prescriptionsWithRelations.length > 0) {
      const customerIds = [
        ...new Set(
          prescriptionsWithRelations
            .map((p: { customer_id: string }) => p.customer_id)
            .filter(Boolean),
        ),
      ];

      const { data: customers } =
        customerIds.length > 0
          ? await supabase
              .from("customers")
              .select("id, first_name, last_name, rut, email")
              .in("id", customerIds)
          : { data: [] };

      const prescriptionIds = prescriptionsWithRelations.map(
        (p: { id: string }) => p.id,
      );

      const { data: workOrders } =
        prescriptionIds.length > 0
          ? await supabase
              .from("lab_work_orders")
              .select("prescription_id")
              .in("prescription_id", prescriptionIds)
          : { data: [] };

      const workOrdersCountByPrescription: Record<string, number> = {};
      (workOrders || []).forEach((wo: { prescription_id: string }) => {
        if (wo.prescription_id) {
          workOrdersCountByPrescription[wo.prescription_id] =
            (workOrdersCountByPrescription[wo.prescription_id] || 0) + 1;
        }
      });

      prescriptionsWithRelations = prescriptionsWithRelations.map(
        (p: Record<string, unknown>) => ({
          ...p,
          customer:
            customers?.find((c: { id: string }) => c.id === p.customer_id) ||
            null,
          work_orders_count: workOrdersCountByPrescription[p.id as string] || 0,
        }),
      );
    }

    logger.debug("Prescriptions fetched successfully", {
      count: prescriptionsWithRelations.length,
      total: count,
      requestId,
    });

    return createPaginatedResponse(
      prescriptionsWithRelations,
      {
        page,
        limit,
        total: count || 0,
      },
      { requestId },
    );
  } catch (error) {
    logger.error("Error in prescriptions API GET", { error, requestId });
    return createApiErrorResponse(
      error instanceof Error ? error : new Error("Internal server error"),
      { requestId },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import { createClient } from "@/utils/supabase/server";

// GET - Fetch options for a specific field key
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ fieldKey: string }> },
) {
  const { fieldKey } = await params;
  try {
    const supabase = await createClient();
    const { searchParams } = new URL(request.url);
    const includeInactive = searchParams.get("include_inactive") === "true";

    const { data: field, error: fieldError } = await supabase
      .from("product_option_fields")
      .select("*")
      .eq("field_key", fieldKey)
      .single();

    if (fieldError || !field) {
      return NextResponse.json(
        { error: "Campo no encontrado" },
        { status: 404 },
      );
    }

    let valuesQuery = supabase
      .from("product_option_values")
      .select("*")
      .eq("field_id", field.id)
      .order("display_order", { ascending: true });

    if (!includeInactive) {
      valuesQuery = valuesQuery.eq("is_active", true);
    }

    const { data: values, error: valuesError } = await valuesQuery;

    if (valuesError) {
      logger.error("Error fetching option values:", {
        error: valuesError,
        fieldKey,
      });
      return NextResponse.json(
        { error: "Error al obtener valores de opción" },
        { status: 500 },
      );
    }

    return NextResponse.json({
      field,
      values: values || [],
    });
  } catch (error) {
    logger.error("Error in GET /api/admin/product-options/[fieldKey]:", {
      error,
      fieldKey,
    });
    return NextResponse.json(
      { error: "Error interno del servidor" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import { createClient } from "@/utils/supabase/server";

// GET - Fetch all option fields with their values
export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    const supabase = await createClient();
    const { searchParams } = new URL(request.url);
    const fieldKey = searchParams.get("field_key");
    const category = searchParams.get("category");
    const formType = searchParams.get("form_type");
    const includeInactive = searchParams.get("include_inactive") === "true";

    let query = supabase
      .from("product_option_fields")
      .select(
        `
        *,
        values:product_option_values(*)
      `,
      )
      .order("display_order", { ascending: true });

    if (fieldKey) {
      query = query.eq("field_key", fieldKey);
    }

    if (category) {
      query = query.eq("field_category", category);
    }

    if (formType) {
      query = query.eq("form_type", formType);
    }

    if (!includeInactive) {
      query = query.eq("is_active", true);
    }

    const { data: fields, error } = await query;

    if (error) {
      logger.error("Error fetching product option fields:", { error });
      return NextResponse.json(
        { error: "Error al obtener campos de opciones" },
        { status: 500 },
      );
    }

    // Sort values by display_order and filter inactive if needed
    const fieldsWithSortedValues = fields?.map((field) => ({
      ...field,
      values:
        field.values
          ?.filter((v: unknown) => includeInactive || v.is_active)
          .sort(
            (a: unknown, b: unknown) => a.display_order - b.display_order,
          ) || [],
    }));

    return NextResponse.json({ fields: fieldsWithSortedValues || [] });
  } catch (error) {
    logger.error("Error in GET /api/admin/product-options:", { error });
    return NextResponse.json(
      { error: "Error interno del servidor" },
      { status: 500 },
    );
  }
}

// POST - Create a new option field or value
export async function POST(request: NextRequest) {
  try {
    const supabase = await createClient();
    const body = await request.json();
    const { type, fieldData, valueData } = body;

    if (type === "field") {
      // Create new option field
      const { data, error } = await supabase
        .from("product_option_fields")
        .insert(fieldData)
        .select()
        .single();

      if (error) {
        logger.error("Error creating option field:", { error, fieldData });
        return NextResponse.json(
          { error: "Error al crear campo de opción" },
          { status: 500 },
        );
      }

      return NextResponse.json({ field: data });
    } else if (type === "value") {
      // Create new option value
      const { data, error } = await supabase
        .from("product_option_values")
        .insert(valueData)
        .select()
        .single();

      if (error) {
        logger.error("Error creating option value:", { error, valueData });
        return NextResponse.json(
          { error: "Error al crear valor de opción" },
          { status: 500 },
        );
      }

      return NextResponse.json({ value: data });
    }

    return NextResponse.json({ error: "Tipo inválido" }, { status: 400 });
  } catch (error) {
    logger.error("Error in POST /api/admin/product-options:", { error });
    return NextResponse.json(
      { error: "Error interno del servidor" },
      { status: 500 },
    );
  }
}

// PUT - Update an option field or value
export async function PUT(request: NextRequest) {
  try {
    const supabase = await createClient();
    const body = await request.json();
    const { type, id, data } = body;

    if (type === "field") {
      const { data: updated, error } = await supabase
        .from("product_option_fields")
        .update(data)
        .eq("id", id)
        .select()
        .single();

      if (error) {
        logger.error("Error updating option field:", { error, id, data });
        return NextResponse.json(
          { error: "Error al actualizar campo de opción" },
          { status: 500 },
        );
      }

      return NextResponse.json({ field: updated });
    } else if (type === "value") {
      const { data: updated, error } = await supabase
        .from("product_option_values")
        .update(data)
        .eq("id", id)
        .select()
        .single();

      if (error) {
        logger.error("Error updating option value:", { error, id, data });
        return NextResponse.json(
          { error: "Error al actualizar valor de opción" },
          { status: 500 },
        );
      }

      return NextResponse.json({ value: updated });
    }

    return NextResponse.json({ error: "Tipo inválido" }, { status: 400 });
  } catch (error) {
    logger.error("Error in PUT /api/admin/product-options:", { error });
    return NextResponse.json(
      { error: "Error interno del servidor" },
      { status: 500 },
    );
  }
}

// DELETE - Delete an option field or value
export async function DELETE(request: NextRequest) {
  try {
    const supabase = await createClient();
    const { searchParams } = new URL(request.url);
    const type = searchParams.get("type");
    const id = searchParams.get("id");
    const checkUsage = searchParams.get("check_usage") === "true";

    if (!type || !id) {
      return NextResponse.json(
        { error: "Tipo e ID son requeridos" },
        { status: 400 },
      );
    }

    if (type === "value") {
      // Check if value is being used in products
      if (checkUsage) {
        // This would require checking the products table for the field_key and value
        // For now, we'll allow deletion but could add this check later
      }

      const { error } = await supabase
        .from("product_option_values")
        .delete()
        .eq("id", id);

      if (error) {
        logger.error("Error deleting option value:", { error, id, type });
        return NextResponse.json(
          { error: "Error al eliminar valor de opción" },
          { status: 500 },
        );
      }

      return NextResponse.json({ success: true });
    } else if (type === "field") {
      // Deleting a field will cascade delete all its values
      const { error } = await supabase
        .from("product_option_fields")
        .delete()
        .eq("id", id);

      if (error) {
        logger.error("Error deleting option field:", { error, id, type });
        return NextResponse.json(
          { error: "Error al eliminar campo de opción" },
          { status: 500 },
        );
      }

      return NextResponse.json({ success: true });
    }

    return NextResponse.json({ error: "Tipo inválido" }, { status: 400 });
  } catch (error) {
    logger.error("Error in DELETE /api/admin/product-options:", { error });
    return NextResponse.json(
      { error: "Error interno del servidor" },
      { status: 500 },
    );
  }
}

/**
 * Bulk products API — Export (CSV / JSON).
 *
 * @module app/api/admin/products/bulk/_helpers/export
 */

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import { createClient } from "@/lib/supabase/server";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";

export async function handleExport(
  request: NextRequest,
): Promise<NextResponse | Response> {
  try {
    const { searchParams } = new URL(request.url);
    const format = searchParams.get("format") || "csv";
    const category_id = searchParams.get("category_id");
    const status = searchParams.get("status");

    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    // Get branch context for stock
    const branchContext = await getBranchContext(request, user.id);
    const branchId = branchContext.branchId;

    // Build query - include stock from product_branch_stock if branch is selected
    const selectFields = branchId
      ? `id,
        name,
        slug,
        description,
        price,
        compare_at_price,
        status,
        is_featured,
        sku,
        weight,
        skin_type,
        benefits,
        certifications,
        usage_instructions,
        category:categories(name),
        created_at,
        updated_at,
        product_branch_stock!inner (
          quantity,
          available_quantity
        )`
      : `id,
        name,
        slug,
        description,
        price,
        compare_at_price,
        inventory_quantity,
        status,
        is_featured,
        sku,
        weight,
        skin_type,
        benefits,
        certifications,
        usage_instructions,
        category:categories(name),
        created_at,
        updated_at`;

    let query = supabase
      .from("products")
      .select(selectFields as unknown) as Record<string, unknown>;

    if (branchId) {
      query = query.eq("product_branch_stock.branch_id", branchId);
    }

    if (category_id && category_id !== "all") {
      query = query.eq("category_id", category_id);
    }

    if (status && status !== "all") {
      query = query.eq("status", status);
    }

    const { data: products, error } = await query.order("created_at", {
      ascending: false,
    });

    if (error) {
      throw error;
    }

    if (format === "csv") {
      // Generate CSV
      const headers = [
        "ID",
        "Nombre",
        "Slug",
        "Descripción",
        "Precio",
        "Precio Comparación",
        "Stock",
        "Estado",
        "Destacado",
        "SKU",
        "Peso",
        "Tipos de Piel",
        "Beneficios",
        "Certificaciones",
        "Instrucciones",
        "Categoría",
        "Fecha Creación",
      ];

      const csvRows = [
        headers.join(","),
        ...(products || []).map((product: Record<string, unknown>) =>
          [
            product.id,
            `"${product.name || ""}"`,
            `"${product.slug || ""}"`,
            `"${(product.description || "").replace(/"/g, '""')}"`,
            product.price || 0,
            product.compare_at_price || "",
            // Use stock from product_branch_stock if available, otherwise fallback to deprecated inventory_quantity
            (() => {
              const stock = product.product_branch_stock as Array<Record<string, unknown>> | undefined;
              return (
                stock?.[0]?.available_quantity ??
                stock?.[0]?.quantity ??
                product.inventory_quantity ??
                0
              );
            })(),
            product.status || "",
            product.is_featured ? "Sí" : "No",
            `"${product.sku || ""}"`,
            product.weight || "",
            `"${Array.isArray(product.skin_type) ? product.skin_type.join("; ") : ""}"`,
            `"${Array.isArray(product.benefits) ? product.benefits.join("; ") : ""}"`,
            `"${Array.isArray(product.certifications) ? product.certifications.join("; ") : ""}"`,
            `"${(product.usage_instructions || "").replace(/"/g, '""')}"`,
            `"${(() => {
              if (Array.isArray(product.category)) {
                return product.category.length > 0
                  ? product.category[0]?.name || ""
                  : "";
              }
              return product.category?.name || "";
            })()}"`,
          ].join(","),
        ),
      ];

      const csvContent = csvRows.join("\n");

      return new Response(csvContent, {
        headers: {
          "Content-Type": "text/csv; charset=utf-8",
          "Content-Disposition": `attachment; filename="productos-${new Date().toISOString().split("T")[0]}.csv"`,
        },
      });
    }

    // Return JSON format
    if (format === "json") {
      const jsonString = JSON.stringify(products, null, 2);

      return new Response(jsonString, {
        headers: {
          "Content-Type": "application/json; charset=utf-8",
          "Content-Disposition": `attachment; filename="productos-${new Date().toISOString().split("T")[0]}.json"`,
        },
      });
    }

    return NextResponse.json({ products });
  } catch (error) {
    logger.error("Error in export products API", { error });
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

/**
 * Bulk products API — Delete (soft / hard / force) operation handler.
 *
 * @module app/api/admin/products/bulk/_helpers/operations/delete
 */

import type { SupabaseClient } from "@supabase/supabase-js";
import { NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";

export async function handleDelete(
  supabase: SupabaseClient,
  product_ids: string[],
): Promise<unknown[]> {
  // Soft delete by setting status to archived
  const { data: deletedProducts, error: deleteError } = await supabase
    .from("products")
    .update({
      status: "archived",
      updated_at: new Date().toISOString(),
    })
    .in("id", product_ids)
    .select("id, name, status");

  if (deleteError) {
    throw deleteError;
  }
  return (deletedProducts ?? []) as unknown[];
}

export async function handleHardDelete(
  supabase: SupabaseClient,
  product_ids: string[],
  updates: Record<string, unknown>,
): Promise<unknown[] | NextResponse> {
  // Hard delete - permanently remove from database
  try {
    // First, get the products to be deleted for logging
    const { data: productsToDelete, error: fetchError } =
      await supabase
        .from("products")
        .select("id, name")
        .in("id", product_ids);

    if (fetchError) {
      logger.error("Error fetching products for hard delete", {
        error: fetchError,
      });
      throw new Error(`Failed to fetch products: ${fetchError.message}`);
    }

    // Check if any products have orders (foreign key constraint)
    const { data: orderItems, error: orderCheckError } = await supabase
      .from("order_items")
      .select("product_id")
      .in("product_id", product_ids)
      .limit(1);

    if (orderCheckError) {
      logger.error("Error checking order items", {
        error: orderCheckError,
      });
      throw new Error(
        `Failed to check order dependencies: ${orderCheckError.message}`,
      );
    }

    if (orderItems && orderItems.length > 0) {
      // Products have orders - check if force delete is requested
      const forceDelete = updates?.force_delete === true;

      if (!forceDelete) {
        // Products have orders - cannot hard delete without force
        const orderedProductIds = orderItems.map(
          (item) => item.product_id,
        );
        const orderedProducts =
          productsToDelete?.filter((p) =>
            orderedProductIds.includes(p.id),
          ) || [];

        return NextResponse.json(
          {
            error: `Cannot hard delete products that have been ordered: ${orderedProducts.map((p) => p.name).join(", ")}. Use soft delete (archive) instead, or enable force delete to remove orders and products.`,
            success: false,
            operation: "hard_delete",
            affected_count: 0,
            results: [],
          },
          { status: 400 },
        );
      }

      // Force delete: First delete order items, then products
      logger.info("Force deleting products with orders", {
        productIds: product_ids,
      });

      // Delete order items first
      const { error: orderItemsDeleteError } = await supabase
        .from("order_items")
        .delete()
        .in("product_id", product_ids);

      if (orderItemsDeleteError) {
        logger.error("Error deleting order items", {
          error: orderItemsDeleteError,
        });
        throw new Error(
          `Failed to delete order items: ${orderItemsDeleteError.message}`,
        );
      }

      logger.info("Order items deleted successfully", {
        productIds: product_ids,
      });
    }

    // Perform the hard delete (no foreign key constraints)
    const { data: hardDeletedProducts, error: hardDeleteError } =
      await supabase
        .from("products")
        .delete()
        .in("id", product_ids)
        .select("id, name");

    if (hardDeleteError) {
      logger.error("Error during hard delete", {
        error: hardDeleteError,
      });
      throw new Error(
        `Failed to delete products: ${hardDeleteError.message}`,
      );
    }

    return (hardDeletedProducts || productsToDelete || []) as unknown[];
  } catch (hardDeleteErr) {
    logger.error("Hard delete operation failed", {
      error: hardDeleteErr,
    });
    throw new Error(
      `Hard delete failed: ${hardDeleteErr instanceof Error ? hardDeleteErr.message : "Unknown error"}`,
    );
  }
}

/**
 * Bulk products API — Update inventory operation handler.
 *
 * @module app/api/admin/products/bulk/_helpers/operations/updateInventory
 */

import type { SupabaseClient } from "@supabase/supabase-js";
import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";

export async function handleUpdateInventory(
  supabase: SupabaseClient,
  product_ids: string[],
  updates: Record<string, unknown>,
  request: NextRequest,
  userId: string,
): Promise<unknown[] | NextResponse> {
  // Validate inventory_adjustment
  if (
    updates.inventory_adjustment === undefined ||
    updates.inventory_adjustment === null ||
    isNaN(Number(updates.inventory_adjustment))
  ) {
    return NextResponse.json(
      {
        error:
          "El ajuste de inventario es requerido y debe ser un número válido",
      },
      { status: 400 },
    );
  }

  // Validate adjustment_type
  if (
    !updates.adjustment_type ||
    !["set", "add"].includes(updates.adjustment_type as string)
  ) {
    return NextResponse.json(
      { error: "El tipo de ajuste debe ser 'set' o 'add'" },
      { status: 400 },
    );
  }

  // Get branch context for stock updates
  const branchContext = await getBranchContext(request, userId);
  let branchId = branchContext.branchId;

  // If superadmin in global view, try to get first accessible branch
  if (!branchId && branchContext.isSuperAdmin) {
    if (branchContext.accessibleBranches.length > 0) {
      branchId = branchContext.accessibleBranches[0].id;
      logger.warn(
        "SuperAdmin in global view - using first accessible branch for stock update",
        {
          branchId,
        },
      );
    } else {
      return NextResponse.json(
        {
          error:
            "Debe seleccionar una sucursal para actualizar inventario. No hay sucursales disponibles.",
        },
        { status: 400 },
      );
    }
  }

  if (!branchId) {
    return NextResponse.json(
      {
        error: "Debe seleccionar una sucursal para actualizar inventario",
      },
      { status: 400 },
    );
  }

  // Get current stock from product_branch_stock
  const { data: currentStock, error: stockFetchError } = await supabase
    .from("product_branch_stock")
    .select("product_id, quantity")
    .in("product_id", product_ids)
    .eq("branch_id", branchId)
    .returns<{ product_id: string; quantity: number }[]>();

  if (stockFetchError) {
    logger.error("Error fetching stock", stockFetchError);
    throw stockFetchError;
  }

  // Create a map of current stock
  const stockMap = new Map(
    currentStock?.map((s) => [s.product_id, s.quantity || 0]) || [],
  );

  // Parse inventory_adjustment as number
  const inventoryAdjustment = Number(updates.inventory_adjustment);
  if (isNaN(inventoryAdjustment)) {
    return NextResponse.json(
      { error: "El ajuste de inventario debe ser un número válido" },
      { status: 400 },
    );
  }

  // Calculate new inventory and update using update_product_stock function
  const inventoryUpdatePromises = product_ids.map(
    async (productId: string) => {
      const currentQuantity = stockMap.get(productId) || 0;
      let newQuantity = currentQuantity;

      if (updates.adjustment_type === "set") {
        newQuantity = Math.max(0, inventoryAdjustment);
      } else if (updates.adjustment_type === "add") {
        newQuantity = Math.max(0, currentQuantity + inventoryAdjustment);
      }

      const quantityChange = newQuantity - currentQuantity;

      if (quantityChange !== 0) {
        // Use update_product_stock function
        const { error: updateError } = await supabase.rpc(
          "update_product_stock",
          {
            p_product_id: productId,
            p_branch_id: branchId,
            p_quantity_change: quantityChange,
            p_reserve: false,
          },
        );

        if (updateError) {
          logger.error(
            `Error updating stock for product ${productId}`,
            updateError,
          );
          return null;
        }
      }

      // Get product name for response
      const { data: product } = await supabase
        .from("products")
        .select("id, name")
        .eq("id", productId)
        .single<{ id: string; name: string }>();

      return {
        id: productId,
        name: product?.name,
        quantity: Math.max(0, newQuantity),
      };
    },
  );

  const inventoryResults = await Promise.all(inventoryUpdatePromises);
  return inventoryResults.filter(Boolean) as unknown[];
}

import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";

import { handleExport } from "./_helpers/export";
import { handleDelete,handleHardDelete  } from "./_helpers/operations/delete";
import { handleDuplicate } from "./_helpers/operations/duplicate";
import { handleUpdateCategory } from "./_helpers/operations/updateCategory";
import { handleUpdateInventory } from "./_helpers/operations/updateInventory";
import { handleUpdatePricing } from "./_helpers/operations/updatePricing";
import { handleUpdateStatus } from "./_helpers/operations/updateStatus";
import { checkAdminAuth, validateBulkRequest } from "./_helpers/validation";

export const dynamic = "force-dynamic";

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();

    const auth = await checkAdminAuth(request);
    if (auth instanceof NextResponse) return auth;

    const parsed = validateBulkRequest(body);
    if (parsed instanceof NextResponse) return parsed;

    const { operation, product_ids, updates } = parsed;
    let results: unknown[] | NextResponse;

    switch (operation) {
      case "update_status":
        results = await handleUpdateStatus(auth.supabase, product_ids, updates);
        break;
      case "update_category":
        results = await handleUpdateCategory(auth.supabase, product_ids, updates);
        break;
      case "update_pricing":
        results = await handleUpdatePricing(auth.supabase, product_ids, updates);
        break;
      case "update_inventory":
        results = await handleUpdateInventory(
          auth.supabase,
          product_ids,
          updates,
          request,
          auth.user.id,
        );
        break;
      case "delete":
        results = await handleDelete(auth.supabase, product_ids);
        break;
      case "hard_delete":
        results = await handleHardDelete(auth.supabase, product_ids, updates);
        break;
      case "duplicate":
        results = await handleDuplicate(auth.supabase, product_ids);
        break;
      default:
        return NextResponse.json(
          { error: "Invalid bulk operation" },
          { status: 400 },
        );
    }

    if (results instanceof NextResponse) return results;

    await auth.supabase.rpc("log_admin_activity", {
      p_action: `bulk_${operation}`,
      p_resource_type: "product",
      p_resource_id: product_ids.join(","),
      p_details: JSON.stringify({
        operation,
        product_count: product_ids.length,
        updates,
      }),
    });

    const successIds = (results as { id?: string; product_id?: string }[])
      .map((r) => r.id ?? r.product_id)
      .filter(Boolean) as string[];

    return NextResponse.json({
      success: true,
      data: { success: successIds, failed: [] },
    });
  } catch (error) {
    logger.error("Error in bulk operations API", { error });
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

export async function GET(request: NextRequest) {
  try {
    return await handleExport(request);
  } catch (error) {
    logger.error("Error in export products API", { error });
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { createClient } from "@/utils/supabase/server";

interface ProductImport {
  name: string;
  slug?: string;
  price: number;
  category_id?: string;
  category?: string | { name: string; slug?: string };
  short_description?: string;
  description?: string;
  compare_at_price?: number;
  inventory_quantity?: number;
  featured_image?: string;
  gallery?: string[];
  is_featured?: boolean;
  status?: string;
  skin_type?: string[];
  benefits?: string[];
  certifications?: string[];
  ingredients?: Array<{ name: string; percentage?: number }>;
  usage_instructions?: string;
  precautions?: string;
  weight?: number;
  dimensions?: string;
  package_characteristics?: string;
  [key: string]: unknown;
}

export function generateSlug(name: string) {
  return name
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9\s-]/g, "")
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-")
    .trim();
}

export async function resolveCategoryId(product: ProductImport) {
  if (product.category_id) return product.category_id;
  if (!product.category) return null;

  const categoryName =
    typeof product.category === "string"
      ? product.category
      : product.category.name;
  if (!categoryName) return null;

  const supabase = await createClient();
  const { data: categories } = await supabase
    .from("categories")
    .select("id, name, slug")
    .limit(100);
  const match = categories?.find(
    (cat) =>
      cat.name.toLowerCase() === categoryName.toLowerCase() ||
      cat.slug.toLowerCase() ===
        categoryName.toLowerCase().replace(/\s+/g, "-") ||
      cat.name.toLowerCase().includes(categoryName.toLowerCase()) ||
      categoryName.toLowerCase().includes(cat.name.toLowerCase()),
  );
  return match?.id || null;
}

export function buildProductInsertData(product: ProductImport, slug: string) {
  return {
    name: product.name,
    slug,
    short_description: product.short_description || null,
    description: product.description || null,
    price: product.price,
    compare_at_price: product.compare_at_price || null,
    inventory_quantity: product.inventory_quantity || 0,
    featured_image: product.featured_image || null,
    gallery: product.gallery || [],
    skin_type: product.skin_type || [],
    benefits: product.benefits || [],
    certifications: product.certifications || [],
    ingredients: product.ingredients || [],
    usage_instructions: product.usage_instructions || null,
    precautions: product.precautions || null,
    weight: product.weight || null,
    dimensions: product.dimensions || null,
    package_characteristics: product.package_characteristics || null,
    is_featured: product.is_featured || false,
    status: product.status || "active",
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
}

import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

interface ProductImport {
  name: string;
  slug?: string;
  short_description?: string;
  description?: string;
  price: number;
  compare_at_price?: number;
  inventory_quantity?: number;
  category_id?: string;
  category?: string | { name: string; slug?: string };
  featured_image?: string;
  gallery?: string[];
  skin_type?: string[];
  benefits?: string[];
  certifications?: string[];
  ingredients?: Array<{ name: string; percentage?: number }>;
  usage_instructions?: string;
  precautions?: string;
  weight?: number;
  dimensions?: string;
  package_characteristics?: string;
  is_featured?: boolean;
  status?: "active" | "draft" | "archived";
}

export const dynamic = "force-dynamic";
export async function POST(request: NextRequest) {
  try {
    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    // Parse JSON from request body
    const body = await request.json();
    const products: ProductImport[] = body.products || body;
    const mode = body.mode || "create";

    if (!Array.isArray(products)) {
      return NextResponse.json(
        { error: "Expected an array of products" },
        { status: 400 },
      );
    }

    if (products.length === 0) {
      return NextResponse.json(
        { error: "No products provided" },
        { status: 400 },
      );
    }

    const results = [];
    const errors = [];

    for (let i = 0; i < products.length; i++) {
      const product = products[i];

      try {
        // Validate required fields
        if (!product.name || !product.price) {
          errors.push({
            index: i,
            product: product.name || "Unknown",
            error: "Missing required fields: name or price",
          });
          continue;
        }

        // Handle category - check if it's category_id or category object
        let categoryId = product.category_id;
        if (!categoryId && product.category) {
          // Try to find category by name
          const categoryName =
            typeof product.category === "string"
              ? product.category
              : product.category.name;
          if (typeof categoryName === "string") {
            // Get categories to find the ID
            const { data: categories } = await supabase
              .from("categories")
              .select("id, name, slug")
              .limit(100);

            const matchingCategory = categories?.find(
              (cat) =>
                cat.name.toLowerCase() === categoryName.toLowerCase() ||
                cat.slug.toLowerCase() ===
                  categoryName.toLowerCase().replace(/\s+/g, "-") ||
                cat.name.toLowerCase().includes(categoryName.toLowerCase()) ||
                categoryName.toLowerCase().includes(cat.name.toLowerCase()),
            );

            if (matchingCategory) {
              categoryId = matchingCategory.id;
            } else {
              errors.push({
                index: i,
                product: product.name,
                error: `Category not found: ${categoryName}`,
              });
              continue;
            }
          }
        }

        if (!categoryId) {
          errors.push({
            index: i,
            product: product.name,
            error: "Missing category_id or valid category name",
          });
          continue;
        }

        // Generate slug if not provided
        let slug = product.slug;
        if (!slug) {
          slug = product.name
            .toLowerCase()
            .normalize("NFD")
            .replace(/[\u0300-\u036f]/g, "") // Remove accents
            .replace(/[^a-z0-9\s-]/g, "") // Remove special characters
            .replace(/\s+/g, "-") // Replace spaces with hyphens
            .replace(/-+/g, "-") // Replace multiple hyphens with single
            .trim();
        }

        // Check if product already exists (by slug or name)
        const { data: existingProduct } = await supabase
          .from("products")
          .select("id, name, slug")
          .or(`slug.eq.${slug},name.eq.${product.name}`)
          .single();

        // Prepare product data
        const productData = {
          name: product.name,
          slug,
          short_description: product.short_description || null,
          description: product.description || null,
          price: product.price,
          compare_at_price: product.compare_at_price || null,
          inventory_quantity: product.inventory_quantity || 0,
          category_id: categoryId,
          featured_image: product.featured_image || null,
          gallery: product.gallery || [],
          skin_type: product.skin_type || [],
          benefits: product.benefits || [],
          certifications: product.certifications || [],
          ingredients: product.ingredients || [],
          usage_instructions: product.usage_instructions || null,
          precautions: product.precautions || null,
          weight: product.weight || null,
          dimensions: product.dimensions || null,
          package_characteristics: product.package_characteristics || null,
          is_featured: product.is_featured || false,
          status: product.status || "active",
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        };

        // Handle different import modes
        let operation = "";
        let newProduct = null;
        let error = null;

        if (existingProduct) {
          // Product exists - handle based on mode
          if (mode === "create") {
            // Skip existing products in create mode
            results.push({
              index: i,
              product: product.name,
              action: "skipped",
              reason: "Product already exists",
            });
            continue;
          } else if (mode === "update" || mode === "upsert") {
            // Update existing product
            const { data: updatedProduct, error: updateError } = await supabase
              .from("products")
              .update({
                ...productData,
                updated_at: new Date().toISOString(),
              })
              .eq("id", existingProduct.id)
              .select()
              .single();

            if (updateError) {
              error = updateError;
            } else {
              newProduct = updatedProduct;
              operation = "updated";
            }
          } else if (mode === "skip_duplicates") {
            // Skip duplicates
            results.push({
              index: i,
              product: product.name,
              action: "skipped",
              reason: "Duplicate product skipped",
            });
            continue;
          }
        } else {
          // Product doesn't exist - handle based on mode
          if (mode === "update") {
            // Skip non-existing products in update mode
            results.push({
              index: i,
              product: product.name,
              action: "skipped",
              reason: "Product does not exist",
            });
            continue;
          } else if (
            mode === "create" ||
            mode === "upsert" ||
            mode === "skip_duplicates"
          ) {
            // Create new product
            const { data: createdProduct, error: insertError } = await supabase
              .from("products")
              .insert(productData)
              .select()
              .single();

            if (insertError) {
              error = insertError;
            } else {
              newProduct = createdProduct;
              operation = "created";
            }
          }
        }

        if (error) {
          errors.push({
            index: i,
            product: product.name,
            error: error.message,
          });
          continue;
        }

        if (newProduct) {
          results.push({
            index: i,
            product: product.name,
            id: newProduct.id,
            slug: newProduct.slug,
            action: operation,
          });
        }
      } catch (error) {
        errors.push({
          index: i,
          product: product.name || "Unknown",
          error: error instanceof Error ? error.message : "Unknown error",
        });
      }
    }

    // Calculate summary statistics
    const created = results.filter((r) => r.action === "created").length;
    const updated = results.filter((r) => r.action === "updated").length;
    const skipped = results.filter((r) => r.action === "skipped").length;

    return NextResponse.json(
      {
        success: true,
        total: products.length,
        successful: results.length,
        failed: errors.length,
        summary: {
          created,
          updated,
          skipped,
          total_processed: products.length,
        },
        results,
        errors,
      },
      {
        headers: {
          Sunset: "Sat, 01 Nov 2026 00:00:00 GMT",
          Deprecation: "true",
        },
      },
    );
  } catch (error) {
    logger.error("JSON import error", { error });
    return NextResponse.json(
      {
        error: "Failed to import products",
        details: error instanceof Error ? error.message : "Unknown error",
      },
      { status: 500 },
    );
  }
}

