/**
 * Product Creation Helpers
 * Extracted data construction and stock handling for product creation
 */
import { DEFAULT_LOW_STOCK_THRESHOLD } from "@/lib/inventory/constants";
import { appLogger as logger } from "@/lib/logger";
import { createServiceRoleClient } from "@/utils/supabase/server";

export const VALID_PRODUCT_COLUMNS = [
  "name", "slug", "description", "short_description", "price", "compare_at_price",
  "cost_price", "price_includes_tax", "category_id", "branch_id", "status",
  "featured_image", "gallery", "tags", "is_featured", "published_at",
  "product_type", "optical_category", "sku", "barcode", "brand", "manufacturer",
  "model_number", "frame_type", "frame_material", "frame_shape", "frame_color",
  "frame_size", "lens_type", "lens_material", "weight", "dimensions",
  "package_characteristics", "shelf_life_months", "video_url", "meta_title",
  "meta_description", "search_keywords", "collections", "vendor", "currency",
  "track_inventory", "created_at", "updated_at",
];

export function buildProductPayload(
  validatedBody: Record<string, unknown>,
  body: Record<string, unknown>,
  productBranchId: string | null,
  organizationId: string,
  slug?: string,
): Record<string, unknown> {
  if (!slug) {
    slug = validatedBody.slug?.trim() || validatedBody.name.toLowerCase().normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]+/g, "-")
      .replace(/(^-|-$)/g, "") || `product-${Date.now()}`;
  }

  const productData: Record<string, unknown> = {
    name: validatedBody.name.trim(),
    slug,
    description: validatedBody.description || null,
    short_description: validatedBody.short_description || null,
    price: typeof validatedBody.price === "number" ? validatedBody.price : parseFloat(String(validatedBody.price)),
    compare_at_price: validatedBody.compare_at_price || null,
    cost_price: validatedBody.cost_price || null,
    price_includes_tax: validatedBody.price_includes_tax ?? false,
    category_id: validatedBody.category_id || null,
    branch_id: productBranchId,
    status: validatedBody.status || "draft",
    featured_image: validatedBody.featured_image || null,
    gallery: validatedBody.gallery || [],
    tags: validatedBody.tags || [],
    is_featured: validatedBody.is_featured || false,
    published_at: validatedBody.published_at || (validatedBody.status === "active" ? new Date().toISOString() : null),
    product_type: validatedBody.product_type || "frame",
    optical_category: validatedBody.optical_category || null,
    sku: validatedBody.sku || null,
    barcode: validatedBody.barcode || null,
    brand: validatedBody.brand || null,
    manufacturer: validatedBody.manufacturer || null,
    model_number: validatedBody.model_number || null,
    frame_type: validatedBody.frame_type || null,
    frame_material: validatedBody.frame_material || null,
    frame_shape: validatedBody.frame_shape || null,
    frame_color: validatedBody.frame_color || null,
    frame_size: validatedBody.frame_size || null,
    lens_type: validatedBody.lens_type || null,
    lens_material: validatedBody.lens_material || null,
    frame_colors: body.frame_colors || [],
    frame_brand: body.frame_brand || null,
    frame_model: body.frame_model || null,
    frame_sku: body.frame_sku || null,
    frame_gender: body.frame_gender || null,
    frame_age_group: body.frame_age_group || null,
    frame_features: body.frame_features || [],
    frame_measurements: body.frame_measurements || null,
    lens_index: body.lens_index ? parseFloat(body.lens_index) : null,
    lens_coatings: body.lens_coatings || [],
    lens_tint_options: body.lens_tint_options || [],
    uv_protection: body.uv_protection || null,
    blue_light_filter: body.blue_light_filter || false,
    blue_light_filter_percentage: body.blue_light_filter_percentage ? parseInt(body.blue_light_filter_percentage) : null,
    photochromic: body.photochromic || false,
    prescription_available: body.prescription_available || false,
    prescription_range: body.prescription_range || null,
    requires_prescription: body.requires_prescription || false,
    is_customizable: body.is_customizable || false,
    warranty_months: body.warranty_months ? parseInt(body.warranty_months) : null,
    warranty_details: body.warranty_details || null,
  };

  // Add optional fields
  if (body.weight != null && body.weight !== "") productData.weight = parseFloat(body.weight) || null;
  if (body.dimensions != null && typeof body.dimensions === "object") productData.dimensions = body.dimensions;
  if (body.shelf_life_months != null) productData.shelf_life_months = parseInt(String(body.shelf_life_months)) || null;
  if (body.sku != null && body.sku !== "") productData.sku = body.sku;
  if (body.barcode != null && body.barcode !== "") productData.barcode = body.barcode;
  if (body.video_url != null && body.video_url !== "") productData.video_url = body.video_url;
  if (body.meta_title != null && body.meta_title !== "") productData.meta_title = body.meta_title;
  if (body.meta_description != null && body.meta_description !== "") productData.meta_description = body.meta_description;
  if (body.search_keywords != null && Array.isArray(body.search_keywords)) productData.search_keywords = body.search_keywords;
  if (body.collections != null && Array.isArray(body.collections)) productData.collections = body.collections;
  if (body.vendor != null && body.vendor !== "") productData.vendor = body.vendor;
  if (body.package_characteristics != null && body.package_characteristics !== "") productData.package_characteristics = body.package_characteristics;

  // Filter to valid columns only
  const filtered: Record<string, unknown> = {};
  Object.keys(productData).forEach((key) => {
    if (VALID_PRODUCT_COLUMNS.includes(key)) {
      let val = productData[key];
      if (typeof val === "string" && val.trim() === "") val = null;
      filtered[key] = val;
    } else {
      logger.debug(`Skipping invalid product column: ${key}`);
    }
  });
  filtered.organization_id = organizationId;
  return filtered;
}

export async function handleProductStock(
  createdProduct: Record<string, unknown>,
  body: Record<string, unknown>,
  productBranchId: string | null,
  branchContext: { isSuperAdmin: boolean },
  organizationId: string,
): Promise<void> {
  const stockQty = parseInt(String(body.stock_quantity)) || 0;
  const lowStockThreshold = body.low_stock_threshold !== undefined
    ? parseInt(String(body.low_stock_threshold)) || DEFAULT_LOW_STOCK_THRESHOLD
    : DEFAULT_LOW_STOCK_THRESHOLD;

  if (productBranchId && (body.stock_quantity !== undefined || body.low_stock_threshold !== undefined)) {
    const svc = createServiceRoleClient();
    if (stockQty > 0) {
      const { error: stockError } = await svc.rpc("update_product_stock", {
        p_product_id: createdProduct.id, p_branch_id: productBranchId,
        p_quantity_change: stockQty, p_reserve: false,
      });
      if (stockError) {
        logger.error("Error creating product stock", stockError);
        const { error: fallbackError } = await svc.from("product_branch_stock").upsert(
          { product_id: createdProduct.id, branch_id: productBranchId, quantity: stockQty, reserved_quantity: 0, low_stock_threshold: lowStockThreshold },
          { onConflict: "product_id,branch_id" },
        );
        if (fallbackError) logger.error("Error in fallback stock creation", fallbackError);
      }
    }
    if (lowStockThreshold !== DEFAULT_LOW_STOCK_THRESHOLD || stockQty === 0) {
      const { error: thresholdError } = await svc.from("product_branch_stock").upsert(
        { product_id: createdProduct.id, branch_id: productBranchId, quantity: stockQty, reserved_quantity: 0, low_stock_threshold: lowStockThreshold },
        { onConflict: "product_id,branch_id" },
      );
      if (thresholdError) logger.warn("Could not set low_stock_threshold", { productId: createdProduct.id, branchId: productBranchId, error: thresholdError });
    }
  }

  // Super admin global view: create stock for all org branches
  if (!productBranchId && branchContext.isSuperAdmin) {
    const svc = createServiceRoleClient();
    const { data: orgBranches } = await svc.from("branches").select("id").eq("organization_id", organizationId);
    if (orgBranches && orgBranches.length > 0) {
      const threshold = body.low_stock_threshold !== undefined
        ? parseInt(String(body.low_stock_threshold)) || DEFAULT_LOW_STOCK_THRESHOLD
        : DEFAULT_LOW_STOCK_THRESHOLD;
      for (const branch of orgBranches) {
        const { error: insertError } = await svc.from("product_branch_stock").upsert(
          { product_id: createdProduct.id, branch_id: branch.id, quantity: 0, reserved_quantity: 0, low_stock_threshold: threshold },
          { onConflict: "product_id,branch_id" },
        );
        if (insertError) logger.warn("Could not create stock for branch (org-wide product)", { productId: createdProduct.id, branchId: branch.id, error: insertError });
      }
    }
  }
}

import type { SupabaseClient } from "@supabase/supabase-js";
import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { RateLimitError, ValidationError } from "@/lib/api/errors";
import {
  validateBody,
  validationErrorResponse,
} from "@/lib/api/validation/zod-helpers";
import { createProductSchema } from "@/lib/api/validation/zod-schemas";
import { appLogger as logger } from "@/lib/logger";
import { rateLimitConfigs, withRateLimit } from "@/lib/rate-limiting";
import { createServiceRoleClient } from "@/utils/supabase/server";

import { buildProductPayload, handleProductStock } from "./productsCreateHelpers";

export async function createProduct(
  request: NextRequest,
  supabase: SupabaseClient,
  organizationId: string,
): Promise<NextResponse> {
  try {
    return await (withRateLimit(rateLimitConfigs.modification) as unknown)(
      request,
      async () => {
        try {
          const { data: { user } } = await supabase.auth.getUser();

          // Get branch context
          const branchContext = await getBranchContext(
            request,
            user!.id,
            supabase,
          );

          // Get request body first (needed for fields not in Zod schema)
          let body: unknown;
          try {
            body = await request.json();
            logger.debug("Request body parsed successfully for product", {
              bodyKeys: Object.keys(body || {}),
              bodyType: typeof body,
              hasName: !!body.name,
              hasPrice: !!body.price,
            });
          } catch (error) {
            logger.error(
              "Failed to parse request body",
              error instanceof Error ? error : new Error(String(error)),
            );
            return NextResponse.json(
              { error: "Invalid JSON in request body" },
              { status: 400 },
            );
          }

          // Validate request body with Zod (body already parsed)
          let validatedBody;
          try {
            logger.debug("Starting Zod validation for product", {
              bodyKeys: Object.keys(body || {}),
              price: body.price,
              priceType: typeof body.price,
              name: body.name,
            });
            validatedBody = validateBody(body, createProductSchema);
            logger.debug("Zod validation successful for product");
          } catch (error: unknown) {
            if (error instanceof ValidationError) {
              logger.warn("ValidationError detected", {
                message: error.message,
                details: error.details,
              });
              return validationErrorResponse(error);
            }
            // For ZodError that wasn't caught as ValidationError
            if (error instanceof z.ZodError) {
              logger.warn("ZodError not wrapped in ValidationError", {
                errors: error.errors.map((e) => ({
                  path: e.path.join("."),
                  message: e.message,
                  code: e.code,
                })),
              });
              const errors = error.errors.map((err: z.ZodIssue) => ({
                field: err.path.join("."),
                message: err.message,
              }));
              return NextResponse.json(
                {
                  error: "Validation failed",
                  details: errors,
                },
                { status: 400 },
              );
            }
            // Log and re-throw unexpected errors
            logger.error(
              "Unexpected error in validation",
              error instanceof Error ? error : new Error(String(error)),
            );
            throw error;
          }

          // Debug: Log branch context
          logger.debug("Branch context for product creation", {
            body_branch_id: validatedBody.branch_id,
            context_branch_id: branchContext.branchId,
            is_super_admin: branchContext.isSuperAdmin,
            accessible_branches: branchContext.accessibleBranches.map(
              (b) => b.id,
            ),
          });

          // Use branch_id from body, or current branch context, or null for super admin
          const productBranchId =
            validatedBody.branch_id || branchContext.branchId || null;

          // Validate branch_id is provided (required for product creation, except for super admins)
          if (!productBranchId && !branchContext.isSuperAdmin) {
            logger.warn(
              "Validation failed: No branch_id provided and user is not super admin",
            );
            return NextResponse.json(
              {
                error:
                  "branch_id is required. Debes seleccionar una sucursal para crear productos.",
                field: "branch_id",
              },
              { status: 400 },
            );
          }

          // If not super admin, validate they have access to the branch
          if (!branchContext.isSuperAdmin && productBranchId) {
            const hasAccess = branchContext.accessibleBranches.some(
              (b) => b.id === productBranchId,
            );
            if (!hasAccess) {
              return NextResponse.json(
                {
                  error: "No tienes acceso a esta sucursal",
                  field: "branch_id",
                },
                { status: 403 },
              );
            }
          }

          // Validar límite de productos del tier
          const { validateTierLimit } = await import(
            "@/lib/saas/tier-validator"
          );
          const productLimit = await validateTierLimit(
            organizationId,
            "products",
          );
          if (!productLimit.allowed) {
            return NextResponse.json(
              {
                error:
                  productLimit.reason ??
                  "Límite de productos alcanzado para tu plan. Considera actualizar tu suscripción.",
                code: "TIER_LIMIT",
                currentCount: productLimit.currentCount,
                maxAllowed: productLimit.maxAllowed,
              },
              { status: 403 },
            );
          }

          logger.debug("Creating product with data", {
            name: validatedBody.name,
            product_type: validatedBody.product_type,
            has_optical_fields: !!validatedBody.optical_category,
            has_frame_fields: !!validatedBody.frame_type,
            has_lens_fields: !!validatedBody.lens_type,
          });

          // Price ya está validado por Zod
          logger.debug("Price validation", {
            price: validatedBody.price,
            type: typeof validatedBody.price,
          });

          // Generate unique slug
          let productSlug = validatedBody.slug?.trim();
          if (!productSlug) {
            productSlug = validatedBody.name.toLowerCase().normalize("NFD")
              .replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]+/g, "-")
              .replace(/(^-|-$)/g, "") || `product-${Date.now()}`;
          }
          const { data: existingSlug } = await supabase.from("products").select("id").eq("slug", productSlug).limit(1);
          if (existingSlug && existingSlug.length > 0) productSlug = `${productSlug}-${Date.now()}`;

          const filteredProductData = buildProductPayload(validatedBody, body as Record<string, unknown>, productBranchId, organizationId, productSlug);

          logger.debug("Prepared product data (sample)", {
            name: filteredProductData.name,
            product_type: filteredProductData.product_type,
            sku: filteredProductData.sku,
            filteredKeys: Object.keys(filteredProductData).length,
          });

          // Try with regular client first, fallback to service role if it fails
          let data, error;
          const result = await supabase
            .from("products")
            .insert([filteredProductData])
            .select();

          data = result.data;
          error = result.error;

          // If any error occurs, try with service role client (RLS, PGRST204, etc.)
          if (error) {
            logger.debug(
              "Error with regular client, retrying with service role client",
              {
                code: error.code,
                message: error.message,
              },
            );
            const serviceSupabase = createServiceRoleClient();
            const serviceResult = await serviceSupabase
              .from("products")
              .insert([filteredProductData])
              .select();

            data = serviceResult.data;
            error = serviceResult.error;
          }

          if (error) {
            logger.error("Database error creating product", error, {
              code: error.code,
              details: error.details,
              hint: error.hint,
              productData: filteredProductData,
            });
            return NextResponse.json(
              {
                error: error.message || "Failed to create product",
                details: error.details,
                hint: error.hint,
              },
              { status: 500 },
            );
          }

          if (!data || data.length === 0) {
            return NextResponse.json(
              { error: "Product was not created - no data returned" },
              { status: 500 },
            );
          }

          const createdProduct = data[0];

          // Handle stock creation
          await handleProductStock(createdProduct, body as Record<string, unknown>, productBranchId, branchContext, organizationId);

          logger.info("Product created successfully", {
            productId: createdProduct?.id,
          });
          return NextResponse.json(
            { product: createdProduct },
            { status: 201 },
          );
        } catch (error) {
          logger.error(
            "Error in product creation handler",
            error instanceof Error ? error : new Error(String(error)),
          );
          if (error instanceof RateLimitError) {
            logger.warn("Rate limit exceeded for product creation", {
              error: error.message,
            });
            return NextResponse.json(
              { error: error.message },
              { status: 429 },
            );
          }

          // Log full error details for debugging
          if (error instanceof Error) {
            logger.error("API error creating product", error, {
              message: error.message,
              stack: error.stack,
              name: error.name,
            });
          } else {
            logger.error(
              "API error creating product",
              new Error(String(error)),
              {
                error: String(error),
              },
            );
          }

          return NextResponse.json(
            {
              error:
                error instanceof Error
                  ? error.message
                  : "Internal server error",
              ...(process.env.NODE_ENV === "development" &&
              error instanceof Error
                ? { details: error.stack }
                : {}),
            },
            { status: 500 },
          );
        }
      },
    );
  } catch (error) {
    // Catch any errors from withRateLimit itself (e.g., RateLimitError thrown before try-catch)
    if (error instanceof RateLimitError) {
      logger.warn("Rate limit exceeded", { error: error.message });
      return NextResponse.json({ error: error.message }, { status: 429 });
    }

    // Log and return error response for any other unexpected errors
    logger.error(
      "Unexpected error in POST handler",
      error instanceof Error ? error : new Error(String(error)),
    );
    return NextResponse.json(
      {
        error:
          error instanceof Error ? error.message : "Internal server error",
      },
      { status: 500 },
    );
  }
}

import type { SupabaseClient } from "@supabase/supabase-js";
import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { createPaginatedResponse } from "@/lib/api/response";
import { DEFAULT_LOW_STOCK_THRESHOLD } from "@/lib/inventory/constants";
import { appLogger as logger } from "@/lib/logger";

export async function listProducts(
  request: NextRequest,
  supabase: SupabaseClient,
  organizationId: string,
): Promise<NextResponse> {
  try {
    const { data: { user } } = await supabase.auth.getUser();

    const { searchParams } = new URL(request.url);

    // Check if branch_id was explicitly requested in the request
    const requestedBranchId =
      request.headers.get("x-branch-id") || searchParams.get("branch_id");

    // Get branch context
    const branchContext = await getBranchContext(request, user!.id, supabase);

    // Pagination - Accept both page and offset parameters
    const limit = parseInt(searchParams.get("limit") || "12");
    const offsetParam = searchParams.get("offset");
    const pageParam = searchParams.get("page");

    // Use offset if provided, otherwise calculate from page
    const offset = offsetParam
      ? parseInt(offsetParam)
      : (parseInt(pageParam || "1") - 1) * limit;
    const page = offsetParam
      ? Math.floor(offset / limit) + 1
      : parseInt(pageParam || "1");

    // Filters
    const category = searchParams.get("category");
    const search = searchParams.get("search");
    const skinType = searchParams.get("skin_type");
    const minPrice = searchParams.get("min_price");
    const maxPrice = searchParams.get("max_price");
    const featured = searchParams.get("featured");
    const inStock = searchParams.get("in_stock");
    const lowStockOnly = searchParams.get("low_stock_only") === "true";
    const status = searchParams.get("status");
    const includeArchived = searchParams.get("include_archived") === "true";

    // Sort
    const sortBy = searchParams.get("sort_by") || "created_at";
    const sortOrder = searchParams.get("sort_order") || "desc";

    // Build query with count option
    // Include stock from product_branch_stock for the current branch
    // IMPORTANT: Only use currentBranchId for filtering if branch_id was explicitly requested
    // When searching without branch_id, we want to show all products from the organization
    // This ensures that search results include products from all branches within the organization
    const currentBranchId = requestedBranchId ? branchContext.branchId : null;

    // Build select string with proper filtering for nested relations
    // Note: Use left join syntax (!inner) to avoid errors when no stock exists
    let selectString = `
        *,
        categories:category_id (
          id,
          name,
          slug
        ),
        product_variants (
          id,
          title,
          price,
          inventory_quantity,
          option1,
          option2,
          option3,
          is_default
        )`;

    // Add product_branch_stock with branch filter if branch is selected
    // Note: Without !inner, this is a left join - products without stock will still be returned
    // We'll filter by branch_id in post-processing since Supabase doesn't support filtering nested relations directly
    // Note: product_branch_stock table only has: id, product_id, branch_id, quantity, reserved_quantity, low_stock_threshold, created_at, updated_at
    if (currentBranchId) {
      selectString += `,
        product_branch_stock (
          quantity,
          reserved_quantity,
          low_stock_threshold,
          branch_id
        )`;
    }

    let query = supabase
      .from("products")
      .select(selectString, { count: "exact" });

    // IMPORTANT: Apply organization filter BEFORE search to ensure multi-tenancy isolation
    // Product visibility by branch:
    // - Regular admin + branch selected: only products where branch_id = that branch (branch-local)
    // - Super admin + branch selected: products where branch_id = branch OR branch_id IS NULL (branch-local + org-wide)
    // - Super admin + global view: all products of the organization
    if (organizationId && !branchContext.isSuperAdmin) {
      query = query.eq("organization_id", organizationId);
      logger.debug("Filtering by organization_id", { organizationId });

      // Regular admin with branch selected: only products created in that branch (branch-local catalog)
      if (currentBranchId) {
        query = query.eq("branch_id", currentBranchId);
        logger.debug("Filtering by branch_id (branch-local)", {
          currentBranchId,
        });
      }
    } else if (branchContext.isSuperAdmin) {
      if (currentBranchId) {
        // Super admin with branch selected: branch-local + org-wide products
        const orgId = branchContext.organizationId;
        let resolvedOrgId = orgId;
        if (!resolvedOrgId) {
          const { data: branchData } = await supabase
            .from("branches")
            .select("organization_id")
            .eq("id", currentBranchId)
            .single();
          resolvedOrgId =
            branchData?.organization_id ??
            "00000000-0000-0000-0000-000000000000";
        }
        query = query.eq("organization_id", resolvedOrgId);
        query = query.or(`branch_id.eq.${currentBranchId},branch_id.is.null`);
        logger.debug("Filtering by branch (super admin)", {
          currentBranchId,
          filter: "branch_id = branch OR branch_id IS NULL",
        });
      } else if (branchContext.organizationId) {
        // Super admin in global view: all products of the organization
        query = query.eq("organization_id", branchContext.organizationId);
        logger.debug("Filtering by organization (super admin global)", {
          organizationId: branchContext.organizationId,
        });
      }
    } else {
      // Fallback: no organization_id - get org from branch when branch selected
      if (currentBranchId) {
        const { data: branchData } = await supabase
          .from("branches")
          .select("organization_id")
          .eq("id", currentBranchId)
          .single();
        query = query.eq(
          "organization_id",
          branchData?.organization_id ?? "00000000-0000-0000-0000-000000000000",
        );
      } else {
        // Regular admin without branch selected - show only their accessible branches
        const accessibleBranchIds = branchContext.accessibleBranches.map(
          (b) => b.id,
        );
        if (accessibleBranchIds.length > 0) {
          // Show global products OR products from accessible branches
          const branchConditions = accessibleBranchIds
            .map((id) => `branch_id.eq.${id}`)
            .join(",");
          try {
            query = query.or(`branch_id.is.null,${branchConditions}`);
          } catch (error) {
            logger.warn(
              "Error using .or() filter, will filter in post-processing",
              { error },
            );
          }
        } else {
          // No accessible branches - return empty
          return createPaginatedResponse([], {
            page: 1,
            limit: parseInt(searchParams.get("limit") || "12"),
            total: 0,
          });
        }
      }
    }

    // Apply filters
    if (category && category !== "all") {
      query = query.eq("category_id", category);
    }

    if (search) {
      // Apply search filter - must be applied after organization filter
      // Use ilike for case-insensitive search
      // Supabase PostgREST syntax: field.ilike.pattern (pattern should include %)
      // Escape special characters in search term to prevent SQL injection
      // Note: We escape % and _ because they are special characters in SQL LIKE patterns
      const escapedSearch = search.replace(/%/g, "\\%").replace(/_/g, "\\_");
      // Build OR condition for search across multiple fields
      // Note: .or() creates an OR condition between the specified fields
      // IMPORTANT: This .or() will override any previous .or() (like branch_id filter)
      // That's why we apply branch_id filter in post-processing when search is present
      // IMPORTANT: The .eq() filters (like organization_id) are NOT overridden by .or()
      // They are combined with AND, so organization_id filter remains active
      const searchCondition = `name.ilike.%${escapedSearch}%,description.ilike.%${escapedSearch}%,sku.ilike.%${escapedSearch}%,barcode.ilike.%${escapedSearch}%`;
      query = query.or(searchCondition);

      // Re-apply organization filter after search to ensure it's not lost
      // This is a safety measure - .eq() filters should persist, but we ensure it here
      if (organizationId && !branchContext.isSuperAdmin) {
        query = query.eq("organization_id", organizationId);
      }

      // Shared catalog: no branch_id filter - search returns all org products

      logger.debug("Applied search filter", {
        search,
        escapedSearch,
        searchCondition,
        hasBranchFilter: !!currentBranchId,
        organizationId,
        organizationFilterReapplied: !!(
          organizationId && !branchContext.isSuperAdmin
        ),
      });
    }

    if (skinType) {
      query = query.contains("skin_type", [skinType]);
    }

    if (minPrice) {
      query = query.gte("price", parseFloat(minPrice));
    }

    if (maxPrice) {
      query = query.lte("price", parseFloat(maxPrice));
    }

    if (featured === "true") {
      query = query.eq("is_featured", true);
    }

    // Stock filtering - will be done in post-processing since we can't filter nested relations directly
    // Store filter flags for post-processing
    const stockFilters = {
      inStock: inStock === "true",
      lowStockOnly: lowStockOnly,
    };

    // Status filtering - Admin can see all products
    // IMPORTANT: When searching, don't apply default status filter to avoid filtering out products
    // that might match the search but have a different status
    if (status && status !== "all") {
      query = query.eq("status", status);
    } else if (!includeArchived && !search) {
      // Default to active products if no specific status requested
      // BUT: Skip this default filter when searching to ensure search results are not limited
      query = query.eq("status", "active");
    }
    // If includeArchived is true, show all products regardless of status

    // Apply sorting
    const sortColumn = getSortColumn(sortBy);
    const order = getSortOrder(sortBy);
    query = query.order(sortColumn, { ascending: order === "asc" });

    // Execute query with pagination and get count
    // Note: range() must come AFTER select() for count to work properly
    const {
      data: products,
      count,
      error,
    } = await query.range(offset, offset + limit - 1);

    // Debug logging for search queries
    if (search) {
      logger.debug("Search query results - BEFORE post-processing", {
        search,
        productsCount: products?.length || 0,
        totalCount: count,
        currentBranchId,
        requestedBranchId,
        organizationId,
        productIds:
          products?.map((p: unknown) => ({
            id: p.id,
            name: p.name,
            branch_id: p.branch_id,
            organization_id: p.organization_id,
            status: p.status,
            nameMatches: p.name?.toLowerCase().includes(search.toLowerCase()),
          })) || [],
      });
    }

    if (error) {
      // Log error with all available information
      const errorInfo = {
        message: error.message,
        code: error.code,
        hint: error.hint,
        details: error.details,
        status: error.status,
      };

      logger.error("Database error fetching products", {
        error: errorInfo,
        selectString,
        currentBranchId,
        branchContext: {
          branchId: branchContext.branchId,
          isSuperAdmin: branchContext.isSuperAdmin,
        },
        queryString: query.toString ? query.toString() : "N/A",
      });

      // Return detailed error in development, generic in production
      const isDevelopment = process.env.NODE_ENV === "development";
      return NextResponse.json(
        {
          error: "Failed to fetch products",
          details: isDevelopment ? error.message : "Database error occurred",
          code: error.code,
          hint: isDevelopment ? error.hint : undefined,
          ...(isDevelopment && { fullError: errorInfo }),
        },
        { status: 500 },
      );
    }

    // Post-process products to handle stock data and apply stock filters
    // If branch is selected and we have stock data, filter and format it properly
    // Also filter products by branch_id and organization_id (we do this in post-processing to avoid conflicts with search .or())
    let processedProducts =
      products
        ?.map((product: unknown) => {
          // CRITICAL: Filter by organization_id in post-processing when there's a search query
          // This ensures multi-tenancy isolation even if the .or() search filter somehow interferes
          // with the organization filter in the query
          if (search && organizationId && !branchContext.isSuperAdmin) {
            if (product.organization_id !== organizationId) {
              return null; // Filter out products from other organizations
            }
          }

          // Shared catalog: when branch is selected, show ALL products of the organization
          // (no branch_id filter - Providencia sees same products as Casa Matriz)
          // Stock is filtered by branch via product_branch_stock below
          // This ensures that when searching without a specific branch, we see all products from the organization

          if (currentBranchId) {
            // Filter stock by branch_id - ONLY use this branch's stock (no fallback to other branches)
            let stockData = null;
            if (product.product_branch_stock) {
              if (Array.isArray(product.product_branch_stock)) {
                stockData = product.product_branch_stock.find(
                  (s: unknown) => s.branch_id === currentBranchId,
                );
              } else if (
                product.product_branch_stock.branch_id === currentBranchId
              ) {
                stockData = product.product_branch_stock;
              }
            }

            if (stockData) {
              const quantity = stockData.quantity || 0;
              const reservedQuantity = stockData.reserved_quantity || 0;
              // Calculate available_quantity as quantity - reserved_quantity
              const availableQuantity = Math.max(
                0,
                quantity - reservedQuantity,
              );

              product.total_inventory_quantity = quantity;
              product.total_available_quantity = availableQuantity;
              product.total_reserved_quantity = reservedQuantity;
              product.total_low_stock_threshold =
                stockData.low_stock_threshold ?? DEFAULT_LOW_STOCK_THRESHOLD;
            } else {
              // No stock record for this branch - check if product has legacy inventory_quantity
              // This handles products that were created before the stock refactor
              const legacyQuantity = product.inventory_quantity || 0;
              product.total_inventory_quantity = legacyQuantity;
              product.total_available_quantity = legacyQuantity;
              product.total_reserved_quantity = 0;
              product.total_low_stock_threshold = DEFAULT_LOW_STOCK_THRESHOLD;
            }
          } else {
            // No branch selected - use legacy inventory_quantity if available
            const legacyQuantity = product.inventory_quantity || 0;
            product.total_inventory_quantity = legacyQuantity;
            product.total_available_quantity = legacyQuantity;
            product.total_reserved_quantity = 0;
            product.total_low_stock_threshold = DEFAULT_LOW_STOCK_THRESHOLD;
          }
          return product;
        })
        .filter((p: unknown) => p !== null) || [];

    // Debug logging for search queries after post-processing
    if (search) {
      logger.debug("Search query results - AFTER post-processing", {
        search,
        processedProductsCount: processedProducts.length,
        processedProductIds: processedProducts.map((p: unknown) => ({
          id: p.id,
          name: p.name,
          branch_id: p.branch_id,
          organization_id: p.organization_id,
          nameMatches: p.name?.toLowerCase().includes(search.toLowerCase()),
        })),
      });
    }

    // Apply stock filters in post-processing
    if (stockFilters.inStock && currentBranchId) {
      processedProducts = processedProducts.filter(
        (p: unknown) => (p.total_available_quantity || 0) > 0,
      );
    }

    if (stockFilters.lowStockOnly && currentBranchId) {
      processedProducts = processedProducts.filter(
        (p: unknown) =>
          (p.total_available_quantity || 0) <=
          (p.total_low_stock_threshold ?? DEFAULT_LOW_STOCK_THRESHOLD),
      );
    }

    // Adjust count if we filtered in post-processing
    // Note: This is not perfect but necessary since we can't filter nested relations in Supabase
    let adjustedCount = count;
    if (
      (stockFilters.inStock || stockFilters.lowStockOnly) &&
      currentBranchId
    ) {
      // We filtered after fetching, so the count is now the filtered array length
      // For accurate pagination, we'd need to do a separate count query, but for now
      // we'll use the filtered length as an approximation
      adjustedCount = processedProducts.length;
    }

    // Calculate pagination info
    const totalPages = Math.ceil((adjustedCount || 0) / limit);
    const hasMore = page < totalPages;

    return createPaginatedResponse(processedProducts, {
      page,
      limit,
      total: adjustedCount || 0,
    });
  } catch (error) {
    logger.error("API error in products GET", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

function getSortColumn(sortBy: string): string {
  switch (sortBy) {
    case "price_asc":
    case "price_desc":
      return "price";
    case "name":
      return "name";
    case "newest":
      return "created_at";
    case "featured":
      return "is_featured";
    default:
      return "created_at";
  }
}

function getSortOrder(sort: string) {
  switch (sort) {
    case "price_asc":
      return "asc";
    case "price_desc":
      return "desc";
    case "name":
      return "asc";
    case "newest":
      return "desc";
    case "featured":
      return "desc";
    default:
      return "desc";
  }
}

import { NextRequest } from "next/server";

import {
  getBranchContext,
  getFieldOperationFromRequest,
} from "@/lib/api/branch-middleware";
import { APIError, RateLimitError } from "@/lib/api/errors";
import {
  createApiErrorResponse,
  createApiSuccessResponse,
} from "@/lib/api/response";
import { appLogger as logger } from "@/lib/logger";
import { rateLimitConfigs, withRateLimit } from "@/lib/rate-limiting";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  return await (withRateLimit(rateLimitConfigs.search) as unknown)(
    request,
    async () => {
      try {
        const supabase = await createClient();

        // Check admin authorization
        const {
          data: { user },
          error: userError,
        } = await supabase.auth.getUser();
        if (userError || !user) {
          return createApiErrorResponse(
            new APIError("Unauthorized", 401, "UNAUTHORIZED"),
          );
        }

        const { data: isAdmin } = (await supabase.rpc("is_admin", {
          user_id: user.id,
        } as IsAdminParams)) as {
          data: IsAdminResult | null;
          error: Error | null;
        };
        if (!isAdmin) {
          return createApiErrorResponse(
            new APIError("Admin access required", 403, "FORBIDDEN"),
          );
        }

        // Get branch context
        const branchContext = await getBranchContext(request, user.id);

        const { searchParams } = new URL(request.url);
        const query = searchParams.get("q") || "";
        const type = searchParams.get("type") || "";
        const limit = parseInt(searchParams.get("limit") || "20");

        if (!query || query.trim().length === 0) {
          return createApiSuccessResponse([]);
        }

        const trimmedQuery = query.trim();

        // Build search conditions - search by name, description, SKU, or barcode
        let searchConditions = `name.ilike.%${trimmedQuery}%,description.ilike.%${trimmedQuery}%`;

        if (/^[A-Z0-9]+$/i.test(trimmedQuery)) {
          searchConditions += `,sku.ilike.%${trimmedQuery}%,barcode.ilike.%${trimmedQuery}%`;
        }

        const fieldOperationId = getFieldOperationFromRequest(request);
        let operativoBranchId: string | null = null;
        if (fieldOperationId) {
          const { data: fo } = await supabase
            .from("field_operations")
            .select("branch_id")
            .eq("id", fieldOperationId)
            .single();
          operativoBranchId = fo?.branch_id ?? null;
        }

        const currentBranchId = operativoBranchId ?? branchContext.branchId;
        const selectFields = currentBranchId
          ? `id, name, price, price_includes_tax, status, featured_image, sku, barcode, product_type, category_id, inventory_quantity, frame_brand, frame_model, frame_color, frame_size,
           product_branch_stock (
             quantity,
             available_quantity,
             reserved_quantity,
             low_stock_threshold,
             branch_id
           )`
          : "id, name, price, price_includes_tax, category_id, inventory_quantity, status, featured_image, sku, barcode, product_type, frame_brand, frame_model, frame_color, frame_size";

        const baseQuery: unknown = supabase.from("products");
        const selectedQuery: unknown = baseQuery.select(selectFields);
        let productsQuery: unknown = selectedQuery.eq("status", "active");

        if (branchContext.organizationId) {
          productsQuery = productsQuery.eq(
            "organization_id",
            branchContext.organizationId,
          );
          // Shared catalog: no branch_id filter - show all org products
        } else if (!branchContext.isSuperAdmin) {
          return createApiSuccessResponse([]);
        }

        productsQuery = productsQuery.or(searchConditions);

        if (type && type !== "frame") {
          productsQuery = productsQuery.eq("product_type", type);
        }

        const { data: products, error: searchError } = await productsQuery
          .order("name", { ascending: true })
          .limit(limit);

        if (searchError) {
          logger.error("Error searching products", {
            error: searchError,
            query: trimmedQuery,
            type,
          });
          return createApiErrorResponse(
            new Error(`Failed to search products: ${searchError.message}`),
          );
        }

        let filteredProducts = products || [];
        if (type === "frame") {
          const { data: marcosCategory } = await supabase
            .from("categories")
            .select("id")
            .eq("slug", "marcos")
            .eq("is_active", true)
            .single();

          // Filter only by category - product_type has DEFAULT 'frame' so it's unreliable
          filteredProducts = (products || []).filter(
            (product: unknown) =>
              marcosCategory && product.category_id === marcosCategory.id,
          );
        }

        // When in operativo context: only products with stock in bodega móvil
        const mobileStockMap: Map<
          string,
          { quantity: number; reserved: number }
        > = new Map();
        if (fieldOperationId) {
          const { data: mobileStock } = await supabase
            .from("operativo_mobile_stock")
            .select("product_id, quantity, reserved_quantity")
            .eq("field_operation_id", fieldOperationId)
            .gt("quantity", 0);

          if (mobileStock && mobileStock.length > 0) {
            mobileStock.forEach((row: unknown) => {
              mobileStockMap.set(row.product_id, {
                quantity: row.quantity ?? 0,
                reserved: row.reserved_quantity ?? 0,
              });
            });
            filteredProducts = filteredProducts.filter((p: unknown) =>
              mobileStockMap.has(p.id),
            );
          } else {
            filteredProducts = [];
          }
        }

        if (currentBranchId) {
          logger.info("Product search branch context", {
            currentBranchId,
            organizationId: branchContext.organizationId,
            isSuperAdmin: branchContext.isSuperAdmin,
          });
        }

        const processedProducts = filteredProducts.map((product: unknown) => {
          let processedProduct = { ...product };

          if (fieldOperationId && mobileStockMap.has(product.id)) {
            const ms = mobileStockMap.get(product.id)!;
            const available = Math.max(0, ms.quantity - ms.reserved);
            processedProduct = {
              ...product,
              available_quantity: available,
              quantity: ms.quantity,
              reserved_quantity: ms.reserved,
              inventory_quantity: ms.quantity,
            };
            delete processedProduct.product_branch_stock;
          } else if (currentBranchId && product.product_branch_stock) {
            const branchStock = Array.isArray(product.product_branch_stock)
              ? product.product_branch_stock.find(
                  (stock: unknown) => stock.branch_id === currentBranchId,
                )
              : product.product_branch_stock.branch_id === currentBranchId
                ? product.product_branch_stock
                : null;

            if (branchStock) {
              processedProduct = {
                ...product,
                available_quantity: branchStock.available_quantity ?? 0,
                quantity: branchStock.quantity ?? 0,
                reserved_quantity: branchStock.reserved_quantity ?? 0,
                inventory_quantity: branchStock.quantity ?? 0,
              };
            } else {
              // Fallback to global inventory if no branch-specific entry found
              processedProduct = {
                ...product,
                available_quantity: product.inventory_quantity || 0,
                quantity: product.inventory_quantity || 0,
                reserved_quantity: 0,
                inventory_quantity: product.inventory_quantity || 0,
              };
            }
            delete processedProduct.product_branch_stock;
          } else if (!currentBranchId) {
            processedProduct.inventory_quantity =
              product.inventory_quantity || 0;
            processedProduct.available_quantity =
              product.inventory_quantity || 0;
          } else {
            processedProduct.inventory_quantity =
              product.inventory_quantity || 0;
            processedProduct.available_quantity =
              product.inventory_quantity || 0;
          }

          return processedProduct;
        });

        logger.info("Processed search results", {
          count: processedProducts.length,
          hasBranchStock: processedProducts.some(
            (p: unknown) => p.available_quantity > 0,
          ),
        });

        return createApiSuccessResponse(processedProducts);
      } catch (error) {
        if (error instanceof RateLimitError) {
          return createApiErrorResponse(error);
        }
        logger.error("Product search API error", error);
        return createApiErrorResponse(
          error instanceof Error ? error : new Error("Internal server error"),
        );
      }
    },
  );
}

import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    // Get categories for reference
    const { data: categories } = await supabase
      .from("categories")
      .select("id, name, slug")
      .order("name");

    // Create CSV template with all product fields
    const csvHeaders = [
      "name", // Nombre del Producto *
      "slug", // URL (slug) - auto-generated if empty
      "short_description", // Descripción Corta
      "description", // Descripción Detallada
      "price", // Precio *
      "compare_at_price", // Precio Comparado
      "inventory_quantity", // Cantidad en Stock
      "category_id", // Categoría (use category name or ID)
      "featured_image", // Imagen Principal (URL)
      "gallery_1", // Galería Imagen 1 (URL)
      "gallery_2", // Galería Imagen 2 (URL)
      "gallery_3", // Galería Imagen 3 (URL)
      "gallery_4", // Galería Imagen 4 (URL)
      "skin_type", // Tipos de Piel (separated by semicolon: dry;oily;combination)
      "benefits", // Beneficios (separated by semicolon: Hidratante;Anti-edad;Regenerador)
      "certifications", // Certificaciones (separated by semicolon: organic;cruelty-free;vegan)
      "ingredients", // Ingredientes (JSON format: [{"name":"Rosa Mosqueta","percentage":15},{"name":"Vitamina E","percentage":5}])
      "usage_instructions", // Instrucciones de Uso
      "precautions", // Precauciones
      "weight", // Peso (gramos)
      "dimensions", // Dimensiones
      "package_characteristics", // Características del Empaque
      "is_featured", // Destacado (true/false)
      "status", // Estado (active/draft/archived)
    ];

    // Create sample data row
    const sampleRow = [
      "Crema Hidratante de Rosa Mosqueta", // name
      "crema-hidratante-rosa-mosqueta", // slug
      "Crema hidratante natural con extracto de rosa mosqueta", // short_description
      "Crema hidratante natural con extracto de rosa mosqueta, ideal para pieles secas y sensibles.", // description
      "2500.00", // price
      "3000.00", // compare_at_price
      "50", // inventory_quantity
      "Cremas", // category_id (use category name)
      "https://example.com/featured-image.jpg", // featured_image
      "https://example.com/gallery1.jpg", // gallery_1
      "https://example.com/gallery2.jpg", // gallery_2
      "https://example.com/gallery3.jpg", // gallery_3
      "https://example.com/gallery4.jpg", // gallery_4
      "dry;sensitive", // skin_type
      "Hidratante;Regenerador;Nutritivo", // benefits
      "organic;cruelty-free;vegan", // certifications
      '[{"name":"Rosa Mosqueta","percentage":15},{"name":"Vitamina E","percentage":5}]', // ingredients
      "Aplicar sobre la piel limpia y seca, masajear suavemente hasta absorción completa.", // usage_instructions
      "Evitar contacto con ojos. Mantener fuera del alcance de niños.", // precautions
      "500", // weight
      "15x10x5 cm", // dimensions
      "Tubo de plástico reciclable con tapa de rosca", // package_characteristics
      "true", // is_featured
      "active", // status
    ];

    // Create CSV content
    const csvContent = [
      csvHeaders.join(","),
      sampleRow.join(","),
      // Add empty row for user to fill
      csvHeaders.map(() => "").join(","),
    ].join("\n");

    // Add categories reference as comments
    const categoriesReference = categories
      ? `\n\n# CATEGORIES REFERENCE:\n# ${categories.map((cat) => `${cat.name} (ID: ${cat.id})`).join("\n# ")}`
      : "";

    const fullCsvContent = csvContent + categoriesReference;

    return new Response(fullCsvContent, {
      headers: {
        "Content-Type": "text/csv; charset=utf-8",
        "Content-Disposition": 'attachment; filename="productos-template.csv"',
      },
    });
  } catch (error) {
    logger.error("Error generating CSV template", { error });
    return NextResponse.json(
      { error: "Failed to generate CSV template" },
      { status: 500 },
    );
  }
}

import { NextRequest } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { APIError } from "@/lib/api/errors";
import {
