      );
    }

    const body = await request.json();

    // Get branch context
    const branchContext = await getBranchContext(request, user.id);

    if (!branchContext.organizationId) {
      return createApiErrorResponse(
        new Error("No se encontró la ID de la organización"),
      );
    }

    // Check if settings exist for this branch/org
    let existingQuery = supabase
      .from("quote_settings")
      .select("id")
      .eq("organization_id", branchContext.organizationId);

    if (branchContext.branchId) {
      existingQuery = existingQuery.eq("branch_id", branchContext.branchId);
    } else {
      existingQuery = existingQuery.is("branch_id", null);
    }

    const { data: existingSettings } = await existingQuery
      .limit(1)
      .maybeSingle();

    const updateData: unknown = {
      updated_at: new Date().toISOString(),
      updated_by: user.id,
    };

    if (body.treatment_prices !== undefined)
      updateData.treatment_prices = body.treatment_prices;
    if (body.lens_type_base_costs !== undefined)
      updateData.lens_type_base_costs = body.lens_type_base_costs;
    if (body.lens_material_multipliers !== undefined)
      updateData.lens_material_multipliers = body.lens_material_multipliers;
    if (body.default_labor_cost !== undefined)
      updateData.default_labor_cost = body.default_labor_cost;
    if (body.default_tax_percentage !== undefined)
      updateData.default_tax_percentage = body.default_tax_percentage;
    if (body.default_expiration_days !== undefined)
      updateData.default_expiration_days = body.default_expiration_days;
    if (body.default_margin_percentage !== undefined)
      updateData.default_margin_percentage = body.default_margin_percentage;
    if (body.labor_cost_includes_tax !== undefined)
      updateData.labor_cost_includes_tax = body.labor_cost_includes_tax;
    if (body.lens_cost_includes_tax !== undefined)
      updateData.lens_cost_includes_tax = body.lens_cost_includes_tax;
    if (body.treatments_cost_includes_tax !== undefined)
      updateData.treatments_cost_includes_tax =
        body.treatments_cost_includes_tax;
    if (body.volume_discounts !== undefined)
      updateData.volume_discounts = body.volume_discounts;
    if (body.currency !== undefined) updateData.currency = body.currency;
    if (body.terms_and_conditions !== undefined)
      updateData.terms_and_conditions = body.terms_and_conditions;
    if (body.notes_template !== undefined)
      updateData.notes_template = body.notes_template;

    let result;

    // 1. Update/Insert the specific record found (Global or Branch)
    if (existingSettings) {
      // Update existing
      const { data, error } = await supabase
        .from("quote_settings")
        .insert({
          ...updateData,
          organization_id: branchContext.organizationId,
          branch_id: branchContext.branchId || null,
        })
        .select()
        .single();

      if (error) {
        logger.error("Error creating quote settings", error);
        return createApiErrorResponse(
          new Error(`Error al crear configuración: ${error.message}`),
        );
      }
      result = data;
    }

    // 2. If GLOBAL update by Super Admin, SYNC to all branches
    if (!branchContext.branchId && branchContext.isSuperAdmin) {
      logger.info("Syncing Global settings to all branches", {
        organizationId: branchContext.organizationId,
      });

      const { data: branches } = await supabase
        .from("branches")
        .select("id")
        .eq("organization_id", branchContext.organizationId);

      if (branches && branches.length > 0) {
        for (const branch of branches) {
          // Sync using upsert on branch_id which has idx_quote_settings_branch_unique
          // Although we could use manual check+insert/update here too for consistency
          await supabase.from("quote_settings").upsert(
            {
              organization_id: branchContext.organizationId,
              branch_id: branch.id,
              ...updateData,
            },
            { onConflict: "branch_id" },
          );
        }
      }
    }

    return createApiSuccessResponse(result);
  } catch (error) {
    logger.error("Error in quote settings PUT API", error);
    return createApiErrorResponse(
      error instanceof Error ? error : new Error("Internal server error"),
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { addBranchFilter, getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import { NotificationService } from "@/lib/notifications/notification-service";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient , createServiceRoleClient } from "@/utils/supabase/server";


export const dynamic = "force-dynamic";
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const supabase = await createClient();
    const supabaseServiceRole = createServiceRoleClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    const { id } = await params;

    // Get branch context
    const branchContext = await getBranchContext(request, user.id);

    // Build branch filter function
    const applyBranchFilter = (query: ReturnType<typeof supabase.from>) => {
      return addBranchFilter(
        query,
        branchContext.branchId,
        branchContext.isSuperAdmin,
        branchContext.organizationId,
      );
    };

    // Fetch quote with branch access check
    const { data: quote, error: quoteError } = await applyBranchFilter(
      supabaseServiceRole.from("quotes").select("*") as unknown,
    )
      .eq("id", id)
      .single();

    if (quoteError || !quote) {
      return NextResponse.json(
        { error: "Presupuesto no encontrado o sin acceso" },
        { status: 404 },
      );
    }

    // Generate work order number
    const { data: workOrderNumber, error: workOrderNumberError } =
      await supabaseServiceRole.rpc("generate_work_order_number");

    if (workOrderNumberError || !workOrderNumber) {
      logger.error("Error generating work order number", workOrderNumberError);
      return NextResponse.json(
        { error: "Failed to generate work order number" },
        { status: 500 },
      );
    }

    // Get prescription snapshot if prescription_id is provided
    let prescriptionSnapshot = null;
    if (quote.prescription_id) {
      const { data: prescription } = await supabaseServiceRole
        .from("prescriptions")
        .select("*")
        .eq("id", quote.prescription_id)
        .single();

      if (prescription) {
        prescriptionSnapshot = prescription;
      }
    }

    // Compute lens_cost: for two_separate use far+near, otherwise single lens or contact
    const lensCost =
      quote.presbyopia_solution === "two_separate"
        ? (quote.far_lens_cost || 0) + (quote.near_lens_cost || 0)
        : quote.contact_lens_family_id
          ? quote.contact_lens_cost || 0
          : quote.lens_cost || 0;

    // Create work order from quote
    const { data: newWorkOrder, error: workOrderError } =
      await supabaseServiceRole
        .from("lab_work_orders")
        .insert({
          work_order_number: workOrderNumber,
          customer_id: quote.customer_id,
          prescription_id: quote.prescription_id || null,
          quote_id: quote.id,
          branch_id: quote.branch_id,
          organization_id: quote.organization_id || null,
          frame_product_id: quote.frame_product_id || null,
          frame_name: quote.frame_name,
          frame_brand: quote.frame_brand,
          frame_model: quote.frame_model,
          frame_color: quote.frame_color,
          frame_size: quote.frame_size,
          frame_sku: quote.frame_sku,
          customer_own_frame: quote.customer_own_frame ?? false,
          lens_family_id: quote.lens_family_id || null,
          lens_type: quote.lens_type,
          lens_sourcing_type: quote.lens_sourcing_type || "surfaced",
          lens_material: quote.lens_material,
          lens_index: quote.lens_index,
          lens_treatments: quote.lens_treatments || [],
          lens_tint_color: quote.lens_tint_color,
          lens_tint_percentage: quote.lens_tint_percentage,
          presbyopia_solution: quote.presbyopia_solution || "none",
          far_lens_family_id: quote.far_lens_family_id || null,
          near_lens_family_id: quote.near_lens_family_id || null,
          far_lens_cost: quote.far_lens_cost ?? null,
          near_lens_cost: quote.near_lens_cost ?? null,
          contact_lens_family_id: quote.contact_lens_family_id || null,
          contact_lens_rx_sphere_od: quote.contact_lens_rx_sphere_od ?? null,
          contact_lens_rx_cylinder_od:
            quote.contact_lens_rx_cylinder_od ?? null,
          contact_lens_rx_axis_od: quote.contact_lens_rx_axis_od ?? null,
          contact_lens_rx_add_od: quote.contact_lens_rx_add_od ?? null,
          contact_lens_rx_base_curve_od:
            quote.contact_lens_rx_base_curve_od ?? null,
          contact_lens_rx_diameter_od:
            quote.contact_lens_rx_diameter_od ?? null,
          contact_lens_rx_sphere_os: quote.contact_lens_rx_sphere_os ?? null,
          contact_lens_rx_cylinder_os:
            quote.contact_lens_rx_cylinder_os ?? null,
          contact_lens_rx_axis_os: quote.contact_lens_rx_axis_os ?? null,
          contact_lens_rx_add_os: quote.contact_lens_rx_add_os ?? null,
          contact_lens_rx_base_curve_os:
            quote.contact_lens_rx_base_curve_os ?? null,
          contact_lens_rx_diameter_os:
            quote.contact_lens_rx_diameter_os ?? null,
          contact_lens_quantity: quote.contact_lens_quantity ?? null,
          contact_lens_cost: quote.contact_lens_cost ?? null,
          near_frame_product_id: quote.near_frame_product_id ?? null,
          near_frame_name: quote.near_frame_name ?? null,
          near_frame_brand: quote.near_frame_brand ?? null,
          near_frame_model: quote.near_frame_model ?? null,
          near_frame_color: quote.near_frame_color ?? null,
          near_frame_size: quote.near_frame_size ?? null,
          near_frame_sku: quote.near_frame_sku ?? null,
          near_frame_price: quote.near_frame_price ?? null,
          near_frame_price_includes_tax:
            quote.near_frame_price_includes_tax ?? false,
          near_frame_cost: quote.near_frame_cost ?? null,
          customer_own_near_frame: quote.customer_own_near_frame ?? false,
          prescription_snapshot: prescriptionSnapshot,
          frame_cost: quote.frame_cost || 0,
          lens_cost: quote.lens_cost || 0,
          treatments_cost: quote.treatments_cost || 0,
          labor_cost: quote.labor_cost || 0,
          lab_cost: 0,
          subtotal: quote.subtotal || 0,
          tax_amount: quote.tax_amount || 0,
          discount_amount: quote.discount_amount || 0,
          total_amount: quote.total_amount,
          currency: quote.currency || "CLP",
          payment_status: "pending",
          deposit_amount: 0,
          balance_amount: quote.total_amount,
          customer_notes: quote.customer_notes,
          status: "ordered",
          created_by: user.id,
        })
        .select(
          `
        *,
        customer:customers!lab_work_orders_customer_id_fkey(id, first_name, last_name, email, phone),
        prescription:prescriptions!lab_work_orders_prescription_id_fkey(*)
      `,
        )
        .single();

    if (workOrderError) {
      logger.error("Error creating work order", workOrderError);
      return NextResponse.json(
        {
          error: "Failed to create work order",
          details: workOrderError.message,
        },
        { status: 500 },
      );
    }

    // Update quote status to accepted (since converting to work order means the quote was accepted)
    // Also preserve original status and link to work order
    await supabaseServiceRole
      .from("quotes")
      .update({
        status: "accepted", // Always change to accepted when converted to work order
        original_status: quote.status, // Preserve original status before conversion
        converted_to_work_order_id: newWorkOrder.id,
        updated_at: new Date().toISOString(),
      })
      .eq("id", id);

    // Create notification for quote conversion (non-blocking)
    NotificationService.notifyQuoteConverted(
      id,
      quote.quote_number,
      newWorkOrder.id,
      newWorkOrder.work_order_number,
      quote.branch_id ?? newWorkOrder.branch_id ?? undefined,
    ).catch((err) => logger.warn("Error creating notification", err));

    // Also notify about new work order
    const customerName = newWorkOrder.customer
      ? `${newWorkOrder.customer.first_name || ""} ${newWorkOrder.customer.last_name || ""}`.trim() ||
        newWorkOrder.customer.email ||
        "Cliente"
      : "Cliente";

    NotificationService.notifyNewWorkOrder(
      newWorkOrder.id,
      newWorkOrder.work_order_number,
      customerName,
      newWorkOrder.total_amount,
      newWorkOrder.branch_id ?? undefined,
    ).catch((err) => logger.warn("Error creating notification", err));

    return NextResponse.json({
      success: true,
      workOrder: newWorkOrder,
    });
  } catch (error) {
    logger.error("Error converting quote to work order", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

export function buildFrameItem(quote: Record<string, unknown>) {
  const hasFrameData = quote.frame_product_id || quote.frame_name ||
    (quote.frame_brand && quote.frame_model) || quote.frame_price !== null;

  if (!hasFrameData) return null;

  if (quote.customer_own_frame) {
    return {
      type: "product", id: `frame-customer-own-${quote.id}`,
      name: quote.frame_name || "Marco del cliente", price: 0,
      sku: "FRAME-CUSTOMER-OWN", quantity: 1, customer_own_frame: true,
      frame_brand: quote.frame_brand, frame_model: quote.frame_model,
      frame_color: quote.frame_color, frame_size: quote.frame_size,
    };
  }

  const framePrice = (quote.frame_price as number) > 0
    ? quote.frame_price : (quote.frame_product as Record<string, unknown>)?.price as number > 0
      ? (quote.frame_product as Record<string, unknown>)?.price : 0;
  const frameId = quote.frame_product_id || `frame-manual-${quote.id}`;

  return {
    type: "product", id: frameId,
    name: quote.frame_name || (quote.frame_product as Record<string, unknown>)?.name ||
      (quote.frame_brand && quote.frame_model ? `${quote.frame_brand} ${quote.frame_model}` : "Marco"),
    price: framePrice, sku: quote.frame_sku || (quote.frame_product as Record<string, unknown>)?.sku || "FRAME",
    barcode: (quote.frame_product as Record<string, unknown>)?.barcode,
    featured_image: (quote.frame_product as Record<string, unknown>)?.featured_image,
    inventory_quantity: (quote.frame_product as Record<string, unknown>)?.inventory_quantity || 0,
    quantity: 1,
    frame_brand: quote.frame_brand, frame_model: quote.frame_model,
    frame_color: quote.frame_color, frame_size: quote.frame_size, customer_own_frame: false,
  };
}

export function buildNearFrameItem(quote: Record<string, unknown>) {
  const isTwoSeparate = quote.presbyopia_solution === "two_separate";
  if (!isTwoSeparate) return null;

  const hasData = quote.near_frame_product_id || quote.near_frame_name ||
    (quote.near_frame_brand && quote.near_frame_model) ||
    ((quote.near_frame_price as number) !== null && (quote.near_frame_price as number) > 0);
  if (!hasData) return null;

  if (quote.customer_own_near_frame) {
    return {
      type: "product", id: `near-frame-customer-own-${quote.id}`,
      name: quote.near_frame_name || "Marco de cerca del cliente", price: 0,
      sku: "NEAR-FRAME-CUSTOMER-OWN", quantity: 1, inventory_quantity: 999,
      customer_own_frame: true, customer_own_near_frame: true,
      frame_brand: quote.near_frame_brand, frame_model: quote.near_frame_model,
      frame_color: quote.near_frame_color, frame_size: quote.near_frame_size, is_near_frame: true,
    };
  }

  const price = (quote.near_frame_price as number) > 0 ? quote.near_frame_price : (quote.near_frame_cost || 0);
  return {
    type: "product", id: quote.near_frame_product_id || `near-frame-manual-${quote.id}`,
    name: quote.near_frame_name || (quote.near_frame_brand && quote.near_frame_model
      ? `${quote.near_frame_brand} ${quote.near_frame_model} (Cerca)` : "Marco de Cerca"),
    price, sku: quote.near_frame_sku || "FRAME-NEAR", quantity: 1, inventory_quantity: 999,
    frame_brand: quote.near_frame_brand, frame_model: quote.near_frame_model,
    frame_color: quote.near_frame_color, frame_size: quote.near_frame_size,
    customer_own_frame: false, is_near_frame: true,
  };
}

export function buildLensItems(quote: Record<string, unknown>) {
  const items: unknown[] = [];
  const isTwoSeparate = quote.presbyopia_solution === "two_separate";

  if (!quote.lens_type || quote.lens_type === "Lentes de contacto" || !quote.lens_material) {
    return items;
  }

  if (isTwoSeparate && quote.far_lens_family_id) {
    items.push({
      type: "lens_complete", id: `lens-far-${quote.id}`,
      name: `Lente Lejos ${quote.lens_type} ${quote.lens_material}`,
      price: quote.far_lens_cost || 0, quantity: 1,
      lens_family_id: quote.far_lens_family_id, lens_type: quote.lens_type,
      lens_material: quote.lens_material, lens_index: quote.lens_index,
      lens_treatments: quote.lens_treatments || [], lens_tint_color: quote.lens_tint_color,
      lens_tint_percentage: quote.lens_tint_percentage, treatments_cost: 0, labor_cost: 0,
      prescription_id: quote.prescription_id, is_far_lens: true,
    });
  }
  if (isTwoSeparate && quote.near_lens_family_id) {
    items.push({
      type: "lens_complete", id: `lens-near-${quote.id}`,
      name: `Lente Cerca ${quote.lens_type} ${quote.lens_material}`,
      price: quote.near_lens_cost || 0, quantity: 1,
      lens_family_id: quote.near_lens_family_id, lens_type: quote.lens_type || "reading",
      lens_material: quote.lens_material, lens_index: quote.lens_index,
      lens_treatments: quote.lens_treatments || [], lens_tint_color: quote.lens_tint_color,
      lens_tint_percentage: quote.lens_tint_percentage, treatments_cost: 0, labor_cost: 0,
      prescription_id: quote.prescription_id, is_near_lens: true,
    });
  }
  if (!isTwoSeparate) {
    items.push({
      type: "lens_complete", id: `lens-${quote.id}`,
      name: `Lente ${quote.lens_type} ${quote.lens_material}`,
      price: quote.lens_cost || 0, quantity: 1,
      lens_family_id: quote.lens_family_id, lens_type: quote.lens_type,
      lens_material: quote.lens_material, lens_index: quote.lens_index,
      lens_treatments: quote.lens_treatments || [], lens_tint_color: quote.lens_tint_color,
      lens_tint_percentage: quote.lens_tint_percentage,
      treatments_cost: quote.treatments_cost || 0, labor_cost: quote.labor_cost || 0,
      prescription_id: quote.prescription_id,
    });
  } else if (!quote.far_lens_family_id && !quote.near_lens_family_id) {
    items.push({
      type: "lens_complete", id: `lens-${quote.id}`,
      name: `Lente ${quote.lens_type} ${quote.lens_material}`,
      price: quote.lens_cost || 0, quantity: 1,
      lens_family_id: quote.lens_family_id, lens_type: quote.lens_type,
      lens_material: quote.lens_material, lens_index: quote.lens_index,
      lens_treatments: quote.lens_treatments || [], lens_tint_color: quote.lens_tint_color,
      lens_tint_percentage: quote.lens_tint_percentage,
      treatments_cost: quote.treatments_cost || 0, labor_cost: quote.labor_cost || 0,
      prescription_id: quote.prescription_id,
    });
  }
  return items;
}

export function buildContactLensItem(quote: Record<string, unknown>) {
  if (quote.lens_type !== "Lentes de contacto" && !quote.contact_lens_family_id) return null;
  return {
    type: "contact_lens", id: `contact-lens-${quote.id}`,
    name: `Lentes de Contacto${(quote.contact_lens_quantity as number) > 1 ? ` - ${quote.contact_lens_quantity} caja(s)` : ""}`,
    price: quote.contact_lens_price ?? quote.contact_lens_cost ?? 0, quantity: 1,
    contact_lens_family_id: quote.contact_lens_family_id,
    contact_lens_quantity: quote.contact_lens_quantity || 1,
    prescription_id: quote.prescription_id,
  };
}

export function buildTreatmentsLaborItems(quote: Record<string, unknown>) {
  const items: unknown[] = [];
  const isTwoSeparate = quote.presbyopia_solution === "two_separate";
  if (isTwoSeparate && (quote.treatments_cost as number) > 0) {
    items.push({
      type: "product", id: `treatments-two-separate-${quote.id}`,
      name: `Tratamientos: ${(quote.lens_treatments as string[])?.join(", ") || "Varios"}`,
      price: quote.treatments_cost || 0, sku: "TREATMENTS", quantity: 1, inventory_quantity: 999,
    });
  }
  if (isTwoSeparate && (quote.labor_cost as number) > 0) {
    items.push({
      type: "product", id: `labor-two-separate-${quote.id}`,
      name: "Mano de obra (montaje)", price: quote.labor_cost || 0,
      sku: "LABOR", quantity: 1, inventory_quantity: 999,
    });
  }
  return items;
}

import { NextRequest, NextResponse } from "next/server";

import { addBranchFilter, getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient, createServiceRoleClient } from "@/utils/supabase/server";

import { buildContactLensItem, buildFrameItem, buildLensItems, buildNearFrameItem, buildTreatmentsLaborItems } from "./_helpers/buildItems";


/**
 * Endpoint para cargar un presupuesto al POS
 * Retorna los datos del presupuesto en formato compatible con el carrito del POS
 * Permite que el presupuesto sea editado antes de procesar el pago
 */
export const dynamic = "force-dynamic";
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const supabase = await createClient();
    const supabaseServiceRole = createServiceRoleClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    const { id } = await params;

    // Get branch context
    const branchContext = await getBranchContext(request, user.id);

    // Build branch filter function
    const applyBranchFilter = (query: ReturnType<typeof supabase.from>) => {
      return addBranchFilter(
        query,
        branchContext.branchId,
        branchContext.isSuperAdmin,
        branchContext.organizationId,
      );
    };

    // Fetch quote with branch access check
    const { data: quote, error: quoteError } = await applyBranchFilter(
      supabaseServiceRole.from("quotes").select(`
        *,
        customer:customers!quotes_customer_id_fkey(id, first_name, last_name, email, phone),
        prescription:prescriptions!quotes_prescription_id_fkey(*),
        frame_product:products!quotes_frame_product_id_fkey(id, name, sku, price, featured_image, barcode)
      `) as unknown,
    )
      .eq("id", id)
      .single();

    if (quoteError || !quote) {
      return NextResponse.json(
        { error: "Presupuesto no encontrado o sin acceso" },
        { status: 404 },
      );
    }

    // Validate that quote is not already used (accepted or converted)
    if (
      quote.status === "accepted" ||
      quote.status === "converted_to_work" ||
      quote.converted_to_work_order_id
    ) {
      return NextResponse.json(
        {
          error:
            "Este presupuesto ya fue utilizado y no puede usarse nuevamente",
          workOrderId: quote.converted_to_work_order_id,
          status: quote.status,
        },
        { status: 400 },
      );
    }

    // Build items array for POS cart
    const items: unknown[] = [];
    const frameItem = buildFrameItem(quote as Record<string, unknown>);
    if (frameItem) items.push(frameItem);
    items.push(...buildLensItems(quote as Record<string, unknown>));
    const nearFrameItem = buildNearFrameItem(quote as Record<string, unknown>);
    if (nearFrameItem) items.push(nearFrameItem);
    items.push(...buildTreatmentsLaborItems(quote as Record<string, unknown>));
    const contactLensItem = buildContactLensItem(quote as Record<string, unknown>);
    if (contactLensItem) items.push(contactLensItem);

    // Return data in format compatible with POS
    return NextResponse.json({
      success: true,
      quoteId: quote.id,
      quoteNumber: quote.quote_number,
      customerId: quote.customer_id,
      customer: quote.customer,
      prescriptionId: quote.prescription_id,
      prescription: quote.prescription,
      items,
      totals: {
        subtotal: quote.subtotal || 0,
        tax: quote.tax_amount || 0,
        discount: quote.discount_amount || 0,
        discount_percentage: quote.discount_percentage || 0,
        total: quote.total_amount || 0,
      },
      notes: quote.customer_notes || null,
      internalNotes: quote.notes || null,
      // Include original quote data for reference (form pre-fill)
      originalQuote: {
        frame_cost: quote.frame_cost || 0,
        lens_cost: quote.lens_cost || 0,
        treatments_cost: quote.treatments_cost || 0,
        labor_cost: quote.labor_cost || 0,
        contact_lens_family_id: quote.contact_lens_family_id || null,
        contact_lens_quantity: quote.contact_lens_quantity || 1,
        contact_lens_cost: quote.contact_lens_cost || 0,
        contact_lens_price: quote.contact_lens_price || 0,
        presbyopia_solution: quote.presbyopia_solution || "none",
        far_lens_family_id: quote.far_lens_family_id || null,
        near_lens_family_id: quote.near_lens_family_id || null,
        far_lens_cost: quote.far_lens_cost ?? 0,
        near_lens_cost: quote.near_lens_cost ?? 0,
        near_frame_product_id: quote.near_frame_product_id || null,
        near_frame_name: quote.near_frame_name || null,
        near_frame_brand: quote.near_frame_brand || null,
        near_frame_model: quote.near_frame_model || null,
        near_frame_color: quote.near_frame_color || null,
        near_frame_size: quote.near_frame_size || null,
        near_frame_sku: quote.near_frame_sku || null,
        near_frame_price: quote.near_frame_price ?? 0,
        near_frame_cost: quote.near_frame_cost ?? 0,
        customer_own_near_frame: quote.customer_own_near_frame ?? false,
      },
    });
  } catch (error) {
    logger.error("Error loading quote to POS", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest } from "next/server";

import { addBranchFilter, getBranchContext } from "@/lib/api/branch-middleware";
import {
  APIError,
  AuthenticationError,
  AuthorizationError,
  NotFoundError,
  ValidationError,
} from "@/lib/api/errors";
import {
  createApiErrorResponse,
  createApiSuccessResponse,
} from "@/lib/api/response";
import { sendQuoteEmailToClient } from "@/lib/email/send-quote-email";
import { appLogger as logger } from "@/lib/logger";
import { sendQuoteWhatsApp } from "@/lib/whatsapp/notifications-b2b";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient, createServiceRoleClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";
export async function POST(
  request: NextRequest,
  { params }: { params: { id: string } },
) {
  try {
    const supabase = await createClient();
    const supabaseServiceRole = createServiceRoleClient();

    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return createApiErrorResponse(new AuthenticationError("No autorizado"));
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return createApiErrorResponse(
        new AuthorizationError("Se requiere acceso de administrador"),
      );
    }

    const { id } = params;
    const branchContext = await getBranchContext(request, user.id);

    const applyBranchFilter = (query: unknown) => {
      return addBranchFilter(
        query,
        branchContext.branchId,
        branchContext.isSuperAdmin,
        branchContext.organizationId,
      );
    };

    const body = await request.json();
    const { email } = body;

    if (!email || !email.includes("@")) {
      return createApiErrorResponse(
        new ValidationError("Email válido requerido"),
      );
    }

    const { data: quoteData, error: quoteError } = await applyBranchFilter(
      supabaseServiceRole.from("quotes").select("id, organization_id"),
    )
      .eq("id", id)
      .single();

    if (quoteError || !quoteData) {
      logger.error("Quote not found or access denied for sending", {
        quoteId: id,
        error: quoteError,
        branchId: branchContext.branchId,
      });
      return createApiErrorResponse(new NotFoundError("Presupuesto"));
    }

    const result = await sendQuoteEmailToClient(id, email, {
      organizationId: quoteData.organization_id,
    });

    if (!result.success) {
      return createApiErrorResponse(
        new APIError(result.error || "Error al enviar email", 500),
      );
    }

    const { data: quoteForWhatsApp } = await supabaseServiceRole
      .from("quotes")
      .select("customer_id, quote_number, total_amount, currency")
      .eq("id", id)
      .single();

    if (quoteForWhatsApp?.customer_id) {
      const { data: customerData } = await supabaseServiceRole
        .from("customers")
        .select("phone, preferred_contact_method")
        .eq("id", quoteForWhatsApp.customer_id)
        .maybeSingle();

      const customer = customerData as {
        phone?: string;
        preferred_contact_method?: string;
      } | null;
      if (
        customer?.phone &&
        customer?.preferred_contact_method === "whatsapp"
      ) {
        sendQuoteWhatsApp(
          customer.phone,
          quoteForWhatsApp.quote_number,
          quoteForWhatsApp.total_amount,
          quoteForWhatsApp.currency ?? "CLP",
        ).catch((err) => logger.warn("WhatsApp quote send failed", err));
      }
    }

    return createApiSuccessResponse({
      message: "Presupuesto enviado exitosamente",
      emailId: result.emailId,
    });
  } catch (error: unknown) {
    logger.error("Error sending quote", error);
    return createApiErrorResponse(
      error instanceof Error ? error : new Error("Error interno del servidor"),
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { addBranchFilter, getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import { NotificationService } from "@/lib/notifications/notification-service";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient, createServiceRoleClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";
export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      logger.error("Auth error in quote status update", userError);
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin, error: adminCheckError } = (await supabase.rpc(
      "is_admin",
      { user_id: user.id } as IsAdminParams,
    )) as { data: IsAdminResult | null; error: Error | null };
    if (adminCheckError) {
      logger.error("Admin check error", adminCheckError);
      return NextResponse.json(
        { error: "Admin verification failed" },
        { status: 500 },
      );
    }
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    const { id } = await params;

    // Get branch context
    const branchContext = await getBranchContext(request, user.id);

    // Build branch filter function
    const applyBranchFilter = (query: ReturnType<typeof supabase.from>) => {
      return addBranchFilter(
        query,
        branchContext.branchId,
        branchContext.isSuperAdmin,
        branchContext.organizationId,
      );
    };

    const supabaseServiceRole = createServiceRoleClient();
    const body = await request.json();

    if (!body.status) {
      return NextResponse.json(
        { error: "Status is required" },
        { status: 400 },
      );
    }

    // Check if quote is already converted (with branch access check)
    const { data: existingQuote, error: fetchError } = await applyBranchFilter(
      supabaseServiceRole
        .from("quotes")
        .select("status, converted_to_work_order_id") as unknown,
    )
      .eq("id", id)
      .single();

    if (fetchError || !existingQuote) {
      return NextResponse.json(
        { error: "Presupuesto no encontrado o sin acceso" },
        { status: 404 },
      );
    }

    if (
      existingQuote?.status === "converted_to_work" ||
      existingQuote?.converted_to_work_order_id
    ) {
      return NextResponse.json(
        {
          error: "Cannot change status of a converted quote",
        },
        { status: 400 },
      );
    }

    // Valid statuses (excluding converted_to_work as it can only be set via convert endpoint)
    const validStatuses = ["draft", "sent", "accepted", "rejected", "expired"];
    if (!validStatuses.includes(body.status)) {
      return NextResponse.json({ error: "Invalid status" }, { status: 400 });
    }

    // Get old status before update
    const oldStatus = existingQuote?.status || "draft";

    // Update status
    const { data: updatedQuote, error } = await supabaseServiceRole
      .from("quotes")
      .update({
        status: body.status,
        updated_at: new Date().toISOString(),
      })
      .eq("id", id)
      .select("quote_number, status, branch_id")
      .single();

    if (error) {
      logger.error("Error updating quote status", error);
      return NextResponse.json(
        {
          error: "Failed to update quote status",
          details: error.message,
        },
        { status: 500 },
      );
    }

    // Create notification for status change (non-blocking)
    if (updatedQuote && oldStatus !== body.status) {
      NotificationService.notifyQuoteStatusChange(
        id,
        updatedQuote.quote_number,
        oldStatus,
        body.status,
        updatedQuote.branch_id ?? undefined,
      ).catch((err) => logger.warn("Error creating notification", err));
    }

    return NextResponse.json({
      success: true,
      quote: updatedQuote,
    });
  } catch (error) {
    logger.error("Error in quote status API", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { AuthorizationError } from "@/lib/api/errors";
import { requireRoot } from "@/lib/api/root-middleware";
import { appLogger as logger } from "@/lib/logger";
import { createRootAdminClient } from "@/utils/supabase/root-admin";

export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    // Verificar que el usuario es root/dev
    await requireRoot(request);

    const supabaseServiceRole = createRootAdminClient();

    // Obtener métricas básicas del sistema
    // Total de organizaciones
    const { count: totalOrgs } = await supabaseServiceRole
      .from("organizations")
      .select("*", { count: "exact", head: true });

    const { count: activeOrgs } = await supabaseServiceRole
      .from("organizations")
      .select("*", { count: "exact", head: true })
      .eq("status", "active");

    // Total de usuarios admin
    const { count: totalUsers } = await supabaseServiceRole
      .from("admin_users")
      .select("*", { count: "exact", head: true });

    const { count: activeUsers } = await supabaseServiceRole
      .from("admin_users")
      .select("*", { count: "exact", head: true })
      .eq("is_active", true);

    // Total de suscripciones
    const { count: totalSubs } = await supabaseServiceRole
      .from("subscriptions")
      .select("*", { count: "exact", head: true });

    const { count: activeSubs } = await supabaseServiceRole
      .from("subscriptions")
      .select("*", { count: "exact", head: true })
      .eq("status", "active");

    // Calcular ingresos desde subscriptions activas
    const { data: activeSubscriptions } = await supabaseServiceRole
      .from("subscriptions")
      .select(
        "organization_id, organization:organizations!inner(subscription_tier)",
      )
      .eq("status", "active");

    // Obtener precios de tiers
    const { data: tiers } = await supabaseServiceRole
      .from("subscription_tiers")
      .select("name, price_monthly");

    const tierPrices: Record<string, number> = {};
    tiers?.forEach((tier) => {
      tierPrices[tier.name] = tier.price_monthly || 0;
    });

    // Calcular ingresos mensuales
    let monthlyRevenue = 0;
    activeSubscriptions?.forEach((sub: unknown) => {
      const tier = sub.organization?.subscription_tier;
      if (tier && tierPrices[tier]) {
        monthlyRevenue += tierPrices[tier];
      }
    });

    const annualRevenue = monthlyRevenue * 12;

    // Calcular crecimiento de organizaciones (últimos 30 días vs anteriores 30 días)
    const thirtyDaysAgo = new Date();
    thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
    const sixtyDaysAgo = new Date();
    sixtyDaysAgo.setDate(sixtyDaysAgo.getDate() - 60);

    const { count: orgsLast30Days } = await supabaseServiceRole
      .from("organizations")
      .select("*", { count: "exact", head: true })
      .gte("created_at", thirtyDaysAgo.toISOString());

    const { count: orgsPrevious30Days } = await supabaseServiceRole
      .from("organizations")
      .select("*", { count: "exact", head: true })
      .gte("created_at", sixtyDaysAgo.toISOString())
      .lt("created_at", thirtyDaysAgo.toISOString());

    const organizationGrowth =
      orgsPrevious30Days && orgsPrevious30Days > 0
        ? ((orgsLast30Days || 0) / orgsPrevious30Days - 1) * 100
        : orgsLast30Days && orgsLast30Days > 0
          ? 100
          : 0;

    // Calcular tasa de conversión de trials
    const { count: totalTrials } = await supabaseServiceRole
      .from("subscriptions")
      .select("*", { count: "exact", head: true })
      .eq("status", "trialing");

    const { count: convertedTrials } = await supabaseServiceRole
      .from("subscriptions")
      .select("*", { count: "exact", head: true })
      .eq("status", "active")
      .not("gateway_subscription_id", "is", null);

    const trialConversionRate =
      totalTrials && totalTrials > 0
        ? ((convertedTrials || 0) / totalTrials) * 100
        : 0;

    // Distribución por tier
    const { data: orgsByTier } = await supabaseServiceRole
      .from("organizations")
      .select("subscription_tier")
      .eq("status", "active");

    const tierDistribution: Record<string, number> = {};
    orgsByTier?.forEach((org) => {
      const tier = org.subscription_tier || "unknown";
      tierDistribution[tier] = (tierDistribution[tier] || 0) + 1;
    });

    const metrics = {
      totalOrganizations: totalOrgs || 0,
      activeOrganizations: activeOrgs || 0,
      totalUsers: totalUsers || 0,
      activeUsers: activeUsers || 0,
      totalSubscriptions: totalSubs || 0,
      activeSubscriptions: activeSubs || 0,
      monthlyRevenue: Math.round(monthlyRevenue * 100) / 100,
      annualRevenue: Math.round(annualRevenue * 100) / 100,
      organizationGrowth: Math.round(organizationGrowth * 100) / 100,
      trialConversionRate: Math.round(trialConversionRate * 100) / 100,
      tierDistribution,
      organizationsLast30Days: orgsLast30Days || 0,
    };

    return NextResponse.json({ metrics });
  } catch (error) {
    if (error instanceof AuthorizationError) {
      return NextResponse.json({ error: error.message }, { status: 403 });
    }
    logger.error("Error fetching SaaS metrics", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

/**
 * POST /api/admin/saas-management/demo-requests/[id]/approve
 * Approve a demo request: create user (invite) if needed, create demo org, send email (root only)
 */
import { NextRequest, NextResponse } from "next/server";

import { requireRoot } from "@/lib/api/root-middleware";
import { sendDemoApprovedEmail } from "@/lib/email/templates/saas";
import { appLogger as logger } from "@/lib/logger";
import { createRootAdminClient } from "@/utils/supabase/root-admin";

export const dynamic = "force-dynamic";

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { userId } = await requireRoot(request);
    const { id } = await params;
    const supabase = createRootAdminClient();

    const { data: req, error: fetchError } = await supabase
      .from("demo_requests")
      .select("*")
      .eq("id", id)
      .single();

    if (fetchError || !req) {
      return NextResponse.json(
        { error: "Solicitud no encontrada" },
        { status: 404 },
      );
    }

    if (req.status !== "pending") {
      return NextResponse.json(
        { error: "La solicitud ya fue procesada" },
        { status: 400 },
      );
    }

    const email = (req.email as string).trim().toLowerCase();

    let targetUserId: string | null = null;
    let isExistingUser = false;

    const { data: existingId } = await supabase.rpc(
      "get_auth_user_id_by_email",
      {
        p_email: email,
      },
    );
    if (existingId) {
      targetUserId =
        typeof existingId === "string"
          ? existingId
          : ((existingId as { id?: string })?.id ?? null);
      isExistingUser = true;
    }
    if (!targetUserId) {
      // Usar invitación por email de Supabase - funciona en producción
      // En local, los emails van a Inbucket
      const { data: inviteData, error: inviteError } =
        await supabase.auth.admin.inviteUserByEmail(email, {
          redirectTo: `${process.env.NEXT_PUBLIC_APP_URL || "https://www.opttius.cl"}/reset-password`,
        });
      if (inviteError) {
        logger.error("Error inviting user for demo", {
          error: inviteError,
          email,
        });
        return NextResponse.json(
          {
            error:
              "No se pudo crear el usuario. Verifica que el email sea válido.",
            details: inviteError.message,
          },
          { status: 500 },
        );
      }
      targetUserId = inviteData?.user?.id ?? null;
    }

    if (!targetUserId) {
      return NextResponse.json(
        { error: "No se pudo obtener el ID del usuario" },
        { status: 500 },
      );
    }

    const { data: orgId, error: rpcError } = await supabase.rpc(
      "create_demo_organization_for_user",
      { p_user_id: targetUserId, p_demo_type: "organic" },
    );

    if (rpcError) {
      logger.error("Error creating demo org for approved request", {
        error: rpcError,
        requestId: id,
      });
      return NextResponse.json(
        {
          error: "Error al crear la organización demo",
          details: rpcError.message,
        },
        { status: 500 },
      );
    }

    const now = new Date().toISOString();
    const demoExpires = new Date();
    demoExpires.setDate(demoExpires.getDate() + 7);

    await supabase
      .from("demo_requests")
      .update({
        status: "approved",
        funnel_stage: "approved",
        reviewed_at: now,
        reviewed_by: userId,
        organization_id: orgId,
        demo_started_at: now,
        demo_expires_at: demoExpires.toISOString(),
        last_contact_at: now,
      })
      .eq("id", id);

    logger.info("Demo request approved", {
      requestId: id,
      email,
      organizationId: orgId,
    });

    if (isExistingUser) {
      const loginUrl = `${process.env.NEXT_PUBLIC_APP_URL || "https://www.opttius.cl"}/login`;
      const emailResult = await sendDemoApprovedEmail({
        email,
        fullName: (req.full_name as string) || null,
        loginUrl,
      });
      if (!emailResult.success) {
        logger.warn("Demo approved email failed to send", {
          email,
          error: emailResult.error,
        });
      }
    }

    return NextResponse.json({
      success: true,
      organizationId: orgId,
      message:
        "Demo aprobada. El usuario puede acceder con su email. Si era nuevo, recibirá un enlace de invitación.",
    });
  } catch (err) {
    if (err && typeof err === "object" && "statusCode" in err) {
      return NextResponse.json(
        { error: "No autorizado" },
        { status: (err as { statusCode: number }).statusCode },
      );
    }
    logger.error("Error in POST demo-requests approve", err);
    return NextResponse.json(
      { error: "Error interno del servidor" },
      { status: 500 },
    );
  }
}

