      subject,
      content,
      variables = [],
      is_active = true,
    } = body;

    if (!name || !type || !subject || !content) {
      return NextResponse.json(
        { error: "Name, type, subject, and content are required" },
        { status: 400 },
      );
    }

    const supabase = createServiceRoleClient();

    const { data: template, error: templateError } = await supabase
      .from("system_email_templates")
      .insert({
        name,
        type,
        subject,
        content,
        variables: Array.isArray(variables) ? JSON.stringify(variables) : "[]",
        is_active: Boolean(is_active),
        is_system: false,
        category: "saas",
        created_by: userId,
      })
      .select()
      .single();

    if (templateError) {
      logger.error("Error creating SaaS email template", {
        error: templateError,
      });
      return NextResponse.json(
        { error: templateError.message || "Failed to create template" },
        { status: 500 },
      );
    }

    logger.info("SaaS email template created", {
      templateId: template.id,
      templateName: template.name,
      createdBy: userId,
    });

    return NextResponse.json({ template });
  } catch (error) {
    if (error && typeof error === "object" && "statusCode" in error) {
      const err = error as { statusCode?: number; message?: string };
      return NextResponse.json(
        { error: err.message || "Unauthorized" },
        { status: err.statusCode || 401 },
      );
    }
    logger.error("Error in SaaS email templates POST", { error });
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

/**
 * GET /api/admin/saas-management/leads/[id]/activities
 * Obtiene el historial de actividades de un lead
 *
 * POST /api/admin/saas-management/leads/[id]/activities
 * Registra una nueva actividad para el lead
 */
import { NextRequest, NextResponse } from "next/server";

import { requireRoot } from "@/lib/api/root-middleware";
import { appLogger as logger } from "@/lib/logger";
import { createRootAdminClient } from "@/utils/supabase/root-admin";

export const dynamic = "force-dynamic";

interface RouteParams {
  params: Promise<{ id: string }>;
}

// GET - Obtener actividades del lead
export async function GET(request: NextRequest, { params }: RouteParams) {
  const startTime = Date.now();

  try {
    await requireRoot(request);
    const supabase = createRootAdminClient();
    const { id } = await params;

    logger.info("Fetching lead activities", { leadId: id, startTime });

    const { searchParams } = new URL(request.url);
    const limit = Math.min(
      parseInt(searchParams.get("limit") || "20", 10),
      100,
    );
    const offset = parseInt(searchParams.get("offset") || "0", 10);
    const activityType = searchParams.get("activity_type");

    // Simplified query without complex joins
    let query = supabase
      .from("lead_activities")
      .select("*", { count: "exact" })
      .eq("lead_id", id)
      .order("created_at", { ascending: false })
      .range(offset, offset + limit - 1);

    if (activityType) {
      query = query.eq("activity_type", activityType);
    }

    const { data, error, count } = await query;

    if (error) {
      logger.error("Error fetching lead activities", {
        error: error.message,
        code: error.code,
        details: error.details,
        hint: error.hint,
        leadId: id,
        duration: Date.now() - startTime,
      });
      return NextResponse.json(
        { error: "Error al obtener actividades", details: error.message },
        { status: 500 },
      );
    }

    // Obtener info del lead
    const { data: lead } = await supabase
      .from("demo_requests")
      .select("id, email, full_name, optica_name, lead_score, priority_level")
      .eq("id", id)
      .single();

    logger.info("Lead activities fetched successfully", {
      leadId: id,
      count: count ?? 0,
      duration: Date.now() - startTime,
    });

    return NextResponse.json({
      activities: data ?? [],
      total: count ?? 0,
      lead: lead,
    });
  } catch (err) {
    const errorMessage = err instanceof Error ? err.message : String(err);
    logger.error("Error in GET lead activities", {
      error: errorMessage,
      leadId: (await params).id,
      duration: Date.now() - startTime,
    });

    if (err && typeof err === "object" && "statusCode" in err) {
      return NextResponse.json(
        { error: "No autorizado" },
        { status: (err as { statusCode: number }).statusCode },
      );
    }
    return NextResponse.json(
      { error: "Error interno del servidor", details: errorMessage },
      { status: 500 },
    );
  }
}

// POST - Registrar nueva actividad
export async function POST(request: NextRequest, { params }: RouteParams) {
  try {
    await requireRoot(request);
    const supabase = createRootAdminClient();
    const { id } = await params;

    const body = await request.json();
    const { activity_type, description, metadata } = body;

    // Validar tipo de actividad
    const validTypes = [
      "lead_created",
      "email_sent",
      "email_opened",
      "email_clicked",
      "email_bounced",
      "demo_accessed",
      "demo_login",
      "meeting_scheduled",
      "meeting_completed",
      "meeting_cancelled",
      "call_logged",
      "note_added",
      "stage_changed",
      "score_updated",
      "assigned",
      "outbound_call",
      "pricing_sent",
      "proposal_viewed",
      "manual_email_sent",
    ];

    if (!activity_type || !validTypes.includes(activity_type)) {
      return NextResponse.json(
        { error: "Tipo de actividad inválido", valid_types: validTypes },
        { status: 400 },
      );
    }

    // Obtener usuario actual
    const {
      data: { user },
    } = await supabase.auth.getUser();

    // Insertar actividad usando la función
    const { data: activity, error } = await supabase.rpc(
      "record_lead_activity",
      {
        p_lead_id: id,
        p_activity_type: activity_type,
        p_description: description,
        p_metadata: metadata || {},
        p_created_by: user?.id,
      },
    );

    if (error) {
      logger.error("Error recording lead activity", error);
      return NextResponse.json(
        { error: "Error al registrar actividad", details: error.message },
        { status: 500 },
      );
    }

    // Obtener lead actualizado
    const { data: lead } = await supabase
      .from("demo_requests")
      .select("lead_score, priority_level, score_last_calculated_at")
      .eq("id", id)
      .single();

    return NextResponse.json({
      success: true,
      activity_id: activity,
      lead_score: lead?.lead_score ?? 0,
      priority_level: lead?.priority_level ?? "cold",
    });
  } catch (err) {
    if (err && typeof err === "object" && "statusCode" in err) {
      return NextResponse.json(
        { error: "No autorizado" },
        { status: (err as { statusCode: number }).statusCode },
      );
    }
    logger.error("Error in POST lead activity", err);
    return NextResponse.json(
      { error: "Error interno del servidor" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { createRootAdminClient } from "@/utils/supabase/root-admin";

// eslint-disable-next-line no-restricted-imports
export async function generateEmailHandler(
  request: NextRequest,
  leadId: string,
) {
  const supabase = createRootAdminClient();

  const {
    data: { user },
    error: userError,
  } = await supabase.auth.getUser();
  if (userError || !user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const { data: adminUser } = await supabase
    .from("admin_users")
    .select("role")
    .eq("id", user.id)
    .single();

  if (!adminUser || (adminUser.role !== "root" && adminUser.role !== "dev")) {
    return NextResponse.json(
      { error: "Root/Dev access required" },
      { status: 403 },
    );
  }

  const { data: lead } = await supabase
    .from("saas_leads")
    .select("*")
    .eq("id", leadId)
    .single();

  if (!lead) {
    return NextResponse.json({ error: "Lead not found" }, { status: 404 });
  }

  const body = await request.json();
  const { template, customizations } = body;

  // Generate email content based on lead data and template
  const emailContent = generateFromTemplate(template, lead, customizations);

  return NextResponse.json({ success: true, email: emailContent });
}

function generateFromTemplate(
  template: string,
  lead: Record<string, unknown>,
  customizations?: Record<string, string>,
) {
  const vars: Record<string, string> = {
    company:
      (lead.company_name as string) || (lead.organization_name as string) || "",
    name:
      `${lead.contact_first_name || ""} ${lead.contact_last_name || ""}`.trim() ||
      (lead.contact_name as string) ||
      "",
    email: (lead.contact_email as string) || "",
    phone: (lead.contact_phone as string) || "",
    plan:
      (lead.plan_interest as string) || (lead.tier_interest as string) || "",
    employees: String(lead.employee_count || lead.branch_count || ""),
    ...customizations,
  };

  return Object.entries(vars).reduce(
    (text, [key, val]) => text.replace(new RegExp(`{{${key}}}`, "g"), val),
    template,
  );
}

import { NextRequest, NextResponse } from "next/server";

import { LLMFactory } from "@/lib/ai/factory";
import type { LLMConfig } from "@/lib/ai/types";
import { requireRoot } from "@/lib/api/root-middleware";
import { appLogger as logger } from "@/lib/logger";

export const dynamic = "force-dynamic";

interface RouteParams {
  params: Promise<{ id: string }>;
}

const LEAD_EMAIL_SYSTEM_PROMPT = [
  "Eres un asistente de ventas profesional especializado en ópticas.",
  "Contexto: Opttius software de gestión para ópticas. Target: dueños, óptometristas.",
  "Tono: profesional, cercano, eficiente. Evita jerga excesiva, tono agresivo.",
  "Instrucciones: analiza lead, genera subject atractivo, cuerpo breve (<150 palabras)",
  "con problema, CTA claro, formato básico. Personaliza por etapa del funnel.",
  "Idioma: español chileno natural.",
  'Responde JSON: { "subject": "...", "body": "..." }',
].join(" ");

export async function POST(request: NextRequest, { params }: RouteParams) {
  const startTime = Date.now();

  try {
    await requireRoot(request);
    const { id } = await params;

    logger.info("Generating lead email with AI", { leadId: id, startTime });

    const body = await request.json();
    const { prompt, context } = body;

    if (!prompt) {
      return NextResponse.json(
        { error: "Prompt es requerido" },
        { status: 400 },
      );
    }

    // Get lead info for context
    const { createRootAdminClient } = await import(
      "@/utils/supabase/root-admin"
    );
    const supabase = createRootAdminClient();

    const { data: lead, error: leadError } = await supabase
      .from("demo_requests")
      .select(
        "id, email, full_name, optica_name, phone, funnel_stage, lead_score, notes",
      )
      .eq("id", id)
      .single();

    if (leadError || !lead) {
      logger.error("Lead not found", { leadId: id, error: leadError });
      return NextResponse.json(
        { error: "Lead no encontrado" },
        { status: 404 },
      );
    }

    // Build context for the AI
    const leadContext = `
Lead: ${lead.full_name || "Sin nombre"}
Email: ${lead.email}
Óptica: ${lead.optica_name || "No especificada"}
Teléfono: ${lead.phone || "No especificado"}
Etapa del funnel: ${lead.funnel_stage || "pending"}
Score: ${lead.lead_score || 0}
Notas: ${lead.notes || "Sin notas"}
${context ? `Contexto adicional: ${context}` : ""}
`;

    const fullPrompt = `${LEAD_EMAIL_SYSTEM_PROMPT}

Información del lead:
${leadContext}

Solicitud del usuario:
${prompt}

Genera el email:`;

    // Generate with AI - use kilocode first, then openrouter as fallback
    try {
      const factory = LLMFactory.getInstance();

      logger.info("Creating LLM provider", { leadId: id });

      // Try kilocode first
      let provider, config;

      const orConfig: Partial<LLMConfig> = {
        model: "minimax/minimax-m2.5:free",
        maxTokens: 500,
        temperature: 0.7,
      };
      try {
        const result = await factory.createProviderWithFallback("kilocode", {
          maxTokens: 500,
          temperature: 0.7,
        });
        provider = result.provider;
        config = result.config;
      } catch {
        logger.warn("Kilocode init failed, trying openrouter");
        const result = await factory.createProviderWithFallback(
          "openrouter",
          orConfig,
        );
        provider = result.provider;
        config = result.config;
      }

      const userMsg = {
        role: "user" as const,
        content: `Información del lead:\n${leadContext}\n\nSolicitud:\n${prompt}`,
      };
      const genOpts = { maxTokens: 500, temperature: 0.7 };

      let response;
      try {
        response = await provider.generateText(
          [{ role: "system", content: LEAD_EMAIL_SYSTEM_PROMPT }, userMsg],
          undefined,
          genOpts,
        );
      } catch (genError) {
        if (config.provider === "kilocode") {
          logger.warn(
            "Kilocode generateText failed, trying openrouter fallback",
          );
          const orResult = await factory.createProviderWithFallback(
            "openrouter",
            orConfig,
          );
          provider = orResult.provider;
          config = orResult.config;
          response = await provider.generateText(
            [{ role: "system", content: LEAD_EMAIL_SYSTEM_PROMPT }, userMsg],
            undefined,
            genOpts,
          );
        } else {
          throw genError;
        }
      }
      try {
        response = await provider.generateText(
          [
            { role: "system", content: LEAD_EMAIL_SYSTEM_PROMPT },
            {
              role: "user",
              content: `Información del lead:\n${leadContext}\n\nSolicitud:\n${prompt}`,
            },
          ],
          undefined,
          {
            maxTokens: 500,
            temperature: 0.7,
          },
        );
      } catch (genError: unknown) {
        const msg =
          genError && typeof genError === "object" && "message" in genError
            ? (genError as { message: string }).message
            : String(genError);
        logger.error("Provider generateText failed", {
          error: msg,
          provider: config.provider,
          model: config.model,
          leadId: id,
        });
        throw new Error("AI generation failed: " + msg);
      }

      logger.info("AI response received", {
        leadId: id,
        contentLength: response.content?.length,
        hasToolCalls: !!response.toolCalls,
      });

      let parsed: { subject: string; body: string };
      try {
        parsed = JSON.parse(response.content);
      } catch {
        const jsonMatch = response.content.match(
          /```(?:json)?\s*([\s\S]*?)```/,
        );
        if (jsonMatch) {
          parsed = JSON.parse(jsonMatch[1]);
        } else {
          const match = response.content.match(/\{[\s\S]*\}/);
          if (match) {
            parsed = JSON.parse(match[0]);
          } else {
            const lines = response.content
              .split("\n")
              .filter((l: string) => l.trim());
            parsed = {
              subject: lines[0]?.replace(/^#+\s*/, "") || "Seguimiento",
              body: lines.slice(1).join("\n").trim() || response.content,
            };
          }
        }
      }

      logger.info("AI email generated successfully", {
        leadId: id,
        subjectLength: parsed.subject.length,
        bodyLength: parsed.body?.length,
        duration: Date.now() - startTime,
      });

      // Log the generation (don't fail if this fails)
      try {
        await supabase.from("lead_activities").insert({
          lead_id: id,
          activity_type: "ai_email_generated",
          description: `Email generado con IA: ${parsed.subject.substring(0, 50)}...`,
          metadata: {
            prompt: prompt.substring(0, 200),
            generated_subject: parsed.subject,
            generated_body_length: parsed.body?.length,
          },
        });
      } catch (logError) {
        logger.warn("Failed to log AI email generation", {
          leadId: id,
          error:
            logError instanceof Error ? logError.message : String(logError),
        });
      }

      return NextResponse.json({
        success: true,
        subject: parsed.subject,
        body: parsed.body,
      });
    } catch (aiError) {
      const errorMessage =
        aiError instanceof Error ? aiError.message : String(aiError);
      const errorStack = aiError instanceof Error ? aiError.stack : undefined;

      logger.error("AI generation error", {
        error: errorMessage,
        errorType: aiError?.constructor?.name,
        stack: errorStack,
        leadId: id,
        duration: Date.now() - startTime,
      });

      return NextResponse.json(
        {
          error: "Error al generar email con IA",
          details: errorMessage,
        },
        { status: 500 },
      );
    }
  } catch (err) {
    const errorMessage = err instanceof Error ? err.message : String(err);
    logger.error("Error in POST lead email generate", {
      error: errorMessage,
      stack: err instanceof Error ? err.stack : undefined,
      leadId: (await params).id,
      duration: Date.now() - startTime,
    });

    if (err && typeof err === "object" && "statusCode" in err) {
      return NextResponse.json(
        { error: "No autorizado" },
        { status: (err as { statusCode: number }).statusCode },
      );
    }

    return NextResponse.json(
      { error: "Error interno del servidor", details: errorMessage },
      { status: 500 },
    );
  }
}

/**
 * POST /api/admin/saas-management/leads/[id]/email/send
 * Envía un email manual a un lead
 */
import { NextRequest, NextResponse } from "next/server";

import { requireRoot } from "@/lib/api/root-middleware";
import { sendEmail } from "@/lib/email/client";
import { appLogger as logger } from "@/lib/logger";
import { createRootAdminClient } from "@/utils/supabase/root-admin";

export const dynamic = "force-dynamic";

interface RouteParams {
  params: Promise<{ id: string }>;
}

export async function POST(request: NextRequest, { params }: RouteParams) {
  try {
    await requireRoot(request);
    const { id } = await params;

    const body = await request.json();
    const { subject, body: emailBody } = body;

    if (!subject || !emailBody) {
      return NextResponse.json(
        { error: "Subject y body son requeridos" },
        { status: 400 },
      );
    }

    const supabase = createRootAdminClient();

    // Get lead info
    const { data: lead, error: leadError } = await supabase
      .from("demo_requests")
      .select("id, email, full_name, optica_name")
