      });

      if (!result.success) {
        logger.error("Failed to send email", result.error);
        return NextResponse.json(
          { error: "Error al enviar email", details: result.error },
          { status: 500 },
        );
      }

      // Record activity
      await supabase.from("lead_activities").insert({
        lead_id: id,
        activity_type: "manual_email_sent",
        description: `Email enviado: ${subject.substring(0, 50)}...`,
        metadata: {
          subject,
          body_length: emailBody.length,
          sent_to: lead.email,
        },
      });

      // Update last_contact_at
      await supabase
        .from("demo_requests")
        .update({
          last_contact_at: new Date().toISOString(),
        })
        .eq("id", id);

      return NextResponse.json({
        success: true,
        message: "Email enviado correctamente",
        emailId: result.id,
      });
    } catch (emailError) {
      logger.error("Email sending error", emailError);
      return NextResponse.json(
        {
          error: "Error al enviar email",
          details:
            emailError instanceof Error ? emailError.message : "Unknown error",
        },
        { status: 500 },
      );
    }
  } catch (err) {
    if (err && typeof err === "object" && "statusCode" in err) {
      return NextResponse.json(
        { error: "No autorizado" },
        { status: (err as { statusCode: number }).statusCode },
      );
    }
    logger.error("Error in POST lead email send", err);
    return NextResponse.json(
      { error: "Error interno del servidor" },
      { status: 500 },
    );
  }
}

/**
 * GET /api/admin/saas-management/leads/[id]/score
 * Obtiene el score y prioridad de un lead
 *
 * POST /api/admin/saas-management/leads/[id]/score
 * Recalcula el score de un lead
 */
import { NextRequest, NextResponse } from "next/server";

import { requireRoot } from "@/lib/api/root-middleware";
import { appLogger as logger } from "@/lib/logger";
import { createRootAdminClient } from "@/utils/supabase/root-admin";

export const dynamic = "force-dynamic";

interface RouteParams {
  params: Promise<{ id: string }>;
}

// GET - Obtener score del lead
export async function GET(request: NextRequest, { params }: RouteParams) {
  try {
    await requireRoot(request);
    const supabase = createRootAdminClient();
    const { id } = await params;

    const { data: lead, error } = await supabase
      .from("demo_requests")
      .select(
        `
        id,
        email,
        full_name,
        optica_name,
        funnel_stage,
        lead_score,
        priority_level,
        score_last_calculated_at,
        created_at,
        last_contact_at,
        demo_started_at,
        demo_expires_at,
        meeting_scheduled_at,
        next_followup_at
      `,
      )
      .eq("id", id)
      .single();

    if (error || !lead) {
      return NextResponse.json(
        { error: "Lead no encontrado" },
        { status: 404 },
      );
    }

    // Obtener desglose de score
    const { data: scoreBreakdown } = await supabase
      .from("lead_activities")
      .select(
        `
        activity_type,
        created_at
      `,
      )
      .eq("lead_id", id)
      .order("created_at", { ascending: false })
      .limit(50);

    // Obtener reglas de scoring
    const { data: rules } = await supabase
      .from("lead_scoring_rules")
      .select("*")
      .eq("is_active", true);

    // Calcular desglose
    const breakdown: Record<string, { count: number; points: number }> = {};
    if (scoreBreakdown) {
      for (const activity of scoreBreakdown) {
        const rule = rules?.find(
          (r) => r.activity_type === activity.activity_type,
        );
        if (rule) {
          if (!breakdown[activity.activity_type]) {
            breakdown[activity.activity_type] = { count: 0, points: 0 };
          }
          breakdown[activity.activity_type].count += 1;
          breakdown[activity.activity_type].points += rule.points;
        }
      }
    }

    return NextResponse.json({
      lead: {
        id: lead.id,
        email: lead.email,
        full_name: lead.full_name,
        optica_name: lead.optica_name,
        funnel_stage: lead.funnel_stage,
