/**
 * GET /api/admin/saas-management/new-users-flow/stats
 * Stats for new-users-flow dashboard (root only)
 */
import { NextRequest, NextResponse } from "next/server";

import { requireRoot } from "@/lib/api/root-middleware";
import { appLogger as logger } from "@/lib/logger";
import { createRootAdminClient } from "@/utils/supabase/root-admin";

export const dynamic = "force-dynamic";

export async function GET(request: NextRequest) {
  try {
    await requireRoot(request);
    const supabase = createRootAdminClient();

    const monthStart = new Date();
    monthStart.setDate(1);
    monthStart.setHours(0, 0, 0, 0);

    const now = new Date();
    const expiringEnd = new Date(now);
    expiringEnd.setDate(expiringEnd.getDate() + 2);

    const [
      pendingRes,
      approvedRes,
      demoOrgsRes,
      convertedRes,
      totalApprovedRes,
      expiringRes,
      stageCounts,
    ] = await Promise.all([
      supabase
        .from("demo_requests")
        .select("id", { count: "exact", head: true })
        .eq("funnel_stage", "pending"),
      supabase
        .from("demo_requests")
        .select("id", { count: "exact", head: true })
        .eq("funnel_stage", "approved")
        .gte("reviewed_at", monthStart.toISOString()),
      supabase
        .from("organizations")
        .select("id", { count: "exact", head: true })
        .contains("metadata", { is_demo: true }),
      supabase
        .from("demo_requests")
        .select("id", { count: "exact", head: true })
        .eq("funnel_stage", "converted"),
      supabase
        .from("demo_requests")
        .select("id", { count: "exact", head: true })
        .in("funnel_stage", [
          "approved",
          "demo_expiring",
          "demo_expired",
          "meeting_scheduled",
          "post_meeting",
          "negotiation",
          "migration",
          "converted",
        ]),
      supabase
        .from("demo_requests")
        .select("id", { count: "exact", head: true })
        .in("funnel_stage", ["approved", "demo_expiring"])
        .gte("demo_expires_at", now.toISOString())
        .lte("demo_expires_at", expiringEnd.toISOString()),
      supabase
        .from("demo_requests")
        .select("funnel_stage")
        .in("funnel_stage", [
          "pending",
          "approved",
          "demo_expiring",
          "demo_expired",
          "meeting_scheduled",
          "post_meeting",
          "negotiation",
          "migration",
          "converted",
          "rejected",
          "lost",
        ]),
    ]);

    const totalApproved = totalApprovedRes.count ?? 0;
    const totalConverted = convertedRes.count ?? 0;
    const conversionRate =
      totalApproved > 0
        ? Math.round((totalConverted / totalApproved) * 100)
        : 0;

    const stageMap: Record<string, number> = {};
    for (const row of stageCounts.data ?? []) {
      const s = row.funnel_stage as string;
      stageMap[s] = (stageMap[s] ?? 0) + 1;
    }

    return NextResponse.json({
      pendingRequests: pendingRes.count ?? 0,
      approvedThisMonth: approvedRes.count ?? 0,
      activeDemos: demoOrgsRes.count ?? 0,
      conversionRate,
      totalConverted,
      totalApproved,
      expiringSoon: expiringRes.count ?? 0,
      byStage: stageMap,
    });
  } catch (err) {
    if (err && typeof err === "object" && "statusCode" in err) {
      return NextResponse.json(
        { error: "No autorizado" },
        { status: (err as { statusCode: number }).statusCode },
      );
    }
    logger.error("Error in GET new-users-flow stats", err);
    return NextResponse.json(
      { error: "Error interno del servidor" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { AuthorizationError } from "@/lib/api/errors";
import { requireRoot } from "@/lib/api/root-middleware";
import { appLogger as logger } from "@/lib/logger";
import { getClientInfoFromRequest,recordAuditLog } from "@/lib/saas/audit-log";
import { recordTierChange } from "@/lib/saas/tier-change-audit";
import { createRootAdminClient } from "@/utils/supabase/root-admin";

/**
 * POST /api/admin/saas-management/organizations/[id]/actions
 * Acciones sobre organizaciones: suspender, activar, cambiar tier
 */
export const dynamic = "force-dynamic";
export async function POST(
  request: NextRequest,
  { params }: { params: { id: string } },
) {
  try {
    const { userId, user } = await requireRoot(request);
    const supabaseServiceRole = createRootAdminClient();

    const { id } = params;
    const body = await request.json();
    const { action, value } = body;

    // Verificar que la organización existe
    const { data: organization } = await supabaseServiceRole
      .from("organizations")
      .select("id, name, status, subscription_tier")
      .eq("id", id)
      .single();

    if (!organization) {
      return NextResponse.json(
        { error: "Organization not found" },
        { status: 404 },
      );
    }

    const updateData: unknown = {};

    switch (action) {
      case "suspend":
        updateData.status = "suspended";
        break;

      case "activate":
        updateData.status = "active";
        break;

      case "cancel":
        updateData.status = "cancelled";
        break;

      case "change_tier":
        if (!value || !["basic", "pro", "premium"].includes(value)) {
          return NextResponse.json(
            { error: "Tier inválido. Debe ser: basic, pro, o premium" },
            { status: 400 },
          );
        }
        updateData.subscription_tier = value;
        break;

      default:
        return NextResponse.json(
          { error: `Acción inválida: ${action}` },
          { status: 400 },
        );
    }

    const { data: updatedOrg, error: updateError } = await supabaseServiceRole
      .from("organizations")
      .update(updateData)
      .eq("id", id)
      .select()
      .single();

    if (updateError) {
      logger.error("Error performing action on organization", updateError);
      return NextResponse.json(
        { error: "Failed to perform action", details: updateError.message },
        { status: 500 },
      );
    }

    if (action === "change_tier") {
      await recordTierChange({
        organizationId: id,
        fromTier: organization.subscription_tier || "basic",
        toTier: value,
        changedByUserId: userId,
        source: "root",
      });
    }

    // Record audit log
    const { ipAddress, userAgent } = getClientInfoFromRequest(request);
    await recordAuditLog({
      userId,
      userEmail: user?.email,
      action: action as "suspend" | "activate" | "cancel" | "change_tier",
      targetType: "organization",
      targetId: id,
      targetName: updatedOrg?.name || null,
      oldValue: {
        status: organization.status,
        subscription_tier: organization.subscription_tier,
      },
      newValue: {
        status: updatedOrg?.status,
        subscription_tier: updatedOrg?.subscription_tier,
      },
      ipAddress,
      userAgent,
    });

    logger.info(`Organization action performed: ${action} on ${id}`);

    return NextResponse.json({
      success: true,
      organization: updatedOrg,
      action,
    });
  } catch (error) {
    if (error instanceof AuthorizationError) {
      return NextResponse.json({ error: error.message }, { status: 403 });
    }
    logger.error("Error in organization action", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

