    await requireRoot(request);
    const supabaseServiceRole = createRootAdminClient();

    const { searchParams } = new URL(request.url);
    const format = searchParams.get("format") || "csv";
    const startDate = searchParams.get("start_date") || undefined;
    const endDate = searchParams.get("end_date") || undefined;
    const status = searchParams.get("status") || undefined;
    const priority = searchParams.get("priority") || undefined;
    const category = searchParams.get("category") || undefined;
    const limit = Math.min(
      parseInt(searchParams.get("limit") || "5000", 10),
      10000,
    );

    if (format !== "csv") {
      return NextResponse.json(
        { error: "Unsupported format. Use format=csv" },
        { status: 400 },
      );
    }

    let query = supabaseServiceRole
      .from("saas_support_tickets")
      .select(
        `
        ticket_number,
        subject,
        status,
        priority,
        category,
        requester_name,
        requester_email,
        created_at,
        first_response_at,
        resolved_at,
        resolution_time_minutes,
        customer_satisfaction_rating,
        organization:organizations(name)
      `,
      )
      .order("created_at", { ascending: false })
      .limit(limit);

    if (startDate) query = query.gte("created_at", startDate);
    if (endDate) query = query.lte("created_at", endDate);
    if (status) query = query.eq("status", status);
    if (priority) query = query.eq("priority", priority);
    if (category) query = query.eq("category", category);

    const result = await query;
    const tickets = result.data ?? [];
    const err = result.error;

    if (err) {
      logger.error("Error exporting SaaS support tickets", err);
      return NextResponse.json(
        { error: "Failed to export tickets" },
        { status: 500 },
      );
    }

    const rows = tickets.map((t: unknown) => ({
      ticket_number: t.ticket_number,
      subject: t.subject,
      status: t.status,
      priority: t.priority,
      category: t.category,
      requester_name: t.requester_name ?? "",
      requester_email: t.requester_email,
      organization_name: t.organization?.name ?? "",
      created_at: t.created_at ?? "",
      first_response_at: t.first_response_at ?? "",
      resolved_at: t.resolved_at ?? "",
      resolution_time_minutes: t.resolution_time_minutes ?? "",
      customer_satisfaction_rating: t.customer_satisfaction_rating ?? "",
    }));

    const headerRow = CSV_HEADERS.join(",");
    const dataRows = rows.map((r) => rowToCsv(r));
    const csv = [headerRow, ...dataRows].join("\n");

    const filename = `soporte-saas-tickets-${new Date().toISOString().slice(0, 10)}.csv`;

    return new NextResponse(csv, {
      status: 200,
      headers: {
        "Content-Type": "text/csv; charset=utf-8",
        "Content-Disposition": `attachment; filename="${filename}"`,
      },
    });
  } catch (error) {
    if (error instanceof AuthorizationError) {
      return NextResponse.json({ error: error.message }, { status: 403 });
    }
    logger.error(
      "Unexpected error in GET /api/admin/saas-management/support/export",
      error,
    );
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { AuthorizationError } from "@/lib/api/errors";
import { requireRoot } from "@/lib/api/root-middleware";
import { appLogger as logger } from "@/lib/logger";
import { createRootAdminClient } from "@/utils/supabase/root-admin";

/**
 * GET /api/admin/saas-management/support/metrics
 * Obtener métricas de soporte SaaS (solo root/dev)
 */
export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    await requireRoot(request);
    const supabaseServiceRole = createRootAdminClient();

    const { searchParams } = new URL(request.url);
    const startDate = searchParams.get("start_date");
    const endDate = searchParams.get("end_date");

    // Total tickets
    let totalQuery = supabaseServiceRole
      .from("saas_support_tickets")
      .select("*", { count: "exact", head: true });

    if (startDate) {
      totalQuery = totalQuery.gte("created_at", startDate);
    }
    if (endDate) {
      totalQuery = totalQuery.lte("created_at", endDate);
    }

    const { count: totalTickets } = await totalQuery;

    // Tickets by status
    let statusQuery = supabaseServiceRole
      .from("saas_support_tickets")
      .select("status");

    if (startDate) {
      statusQuery = statusQuery.gte("created_at", startDate);
    }
    if (endDate) {
      statusQuery = statusQuery.lte("created_at", endDate);
    }

    const { data: ticketsByStatus } = await statusQuery;

    const statusCounts = {
      open: 0,
      assigned: 0,
      in_progress: 0,
      waiting_customer: 0,
      resolved: 0,
      closed: 0,
    };

    ticketsByStatus?.forEach((ticket: unknown) => {
      if (ticket.status in statusCounts) {
        statusCounts[ticket.status as keyof typeof statusCounts]++;
      }
    });

    // Tickets by priority
    let ticketsByPriorityQuery = supabaseServiceRole
      .from("saas_support_tickets")
      .select("priority");

    if (startDate) {
      ticketsByPriorityQuery = ticketsByPriorityQuery.gte(
        "created_at",
        startDate,
      );
    }
    if (endDate) {
      ticketsByPriorityQuery = ticketsByPriorityQuery.lte(
        "created_at",
        endDate,
      );
    }

    const { data: ticketsByPriority } = await ticketsByPriorityQuery;

    const priorityCounts = {
      low: 0,
      medium: 0,
      high: 0,
      urgent: 0,
    };

    ticketsByPriority?.forEach((ticket: unknown) => {
      if (ticket.priority in priorityCounts) {
        priorityCounts[ticket.priority as keyof typeof priorityCounts]++;
      }
    });

    // Tickets by category
    let categoryQuery = supabaseServiceRole
      .from("saas_support_tickets")
      .select("category");

    if (startDate) {
      categoryQuery = categoryQuery.gte("created_at", startDate);
    }
    if (endDate) {
      categoryQuery = categoryQuery.lte("created_at", endDate);
    }

    const { data: ticketsByCategory } = await categoryQuery;

    const categoryCounts: Record<string, number> = {};
    ticketsByCategory?.forEach((ticket: unknown) => {
      categoryCounts[ticket.category] =
        (categoryCounts[ticket.category] || 0) + 1;
    });

    // Average response time
    let responseTimeQuery = supabaseServiceRole
      .from("saas_support_tickets")
      .select("response_time_minutes")
      .not("response_time_minutes", "is", null);

    if (startDate) {
      responseTimeQuery = responseTimeQuery.gte("created_at", startDate);
    }
    if (endDate) {
      responseTimeQuery = responseTimeQuery.lte("created_at", endDate);
    }

    const { data: ticketsWithResponseTime } = await responseTimeQuery;

    const avgResponseTime =
      ticketsWithResponseTime && ticketsWithResponseTime.length > 0
        ? ticketsWithResponseTime.reduce(
            (sum: number, ticket: unknown) =>
              sum + (ticket.response_time_minutes || 0),
            0,
          ) / ticketsWithResponseTime.length
        : null;

    // Average resolution time
    let resolutionTimeQuery = supabaseServiceRole
      .from("saas_support_tickets")
      .select("resolution_time_minutes")
      .not("resolution_time_minutes", "is", null);

    if (startDate) {
      resolutionTimeQuery = resolutionTimeQuery.gte("created_at", startDate);
    }
    if (endDate) {
      resolutionTimeQuery = resolutionTimeQuery.lte("created_at", endDate);
    }

    const { data: ticketsWithResolutionTime } = await resolutionTimeQuery;

    const avgResolutionTime =
      ticketsWithResolutionTime && ticketsWithResolutionTime.length > 0
        ? ticketsWithResolutionTime.reduce(
            (sum: number, ticket: unknown) =>
              sum + (ticket.resolution_time_minutes || 0),
            0,
          ) / ticketsWithResolutionTime.length
        : null;

    // Customer satisfaction
    let ratingQuery = supabaseServiceRole
      .from("saas_support_tickets")
      .select("customer_satisfaction_rating")
      .not("customer_satisfaction_rating", "is", null);

    if (startDate) {
      ratingQuery = ratingQuery.gte("created_at", startDate);
    }
    if (endDate) {
      ratingQuery = ratingQuery.lte("created_at", endDate);
    }

    const { data: ticketsWithRating } = await ratingQuery;

    const avgSatisfaction =
      ticketsWithRating && ticketsWithRating.length > 0
        ? ticketsWithRating.reduce(
            (sum: number, ticket: unknown) =>
              sum + (ticket.customer_satisfaction_rating || 0),
            0,
          ) / ticketsWithRating.length
        : null;

    // Tickets created per day (last 30 days)
    const thirtyDaysAgo = new Date();
    thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

    const { data: recentTickets } = await supabaseServiceRole
      .from("saas_support_tickets")
      .select("created_at")
      .gte("created_at", thirtyDaysAgo.toISOString())
      .order("created_at", { ascending: true });

    const ticketsPerDay: Record<string, number> = {};
    recentTickets?.forEach((ticket: unknown) => {
      const date = new Date(ticket.created_at).toISOString().split("T")[0];
      ticketsPerDay[date] = (ticketsPerDay[date] || 0) + 1;
    });

    // Top organizations by ticket count
    let orgQuery = supabaseServiceRole
      .from("saas_support_tickets")
      .select("organization_id, organizations(name)")
      .not("organization_id", "is", null);

    if (startDate) {
      orgQuery = orgQuery.gte("created_at", startDate);
    }
    if (endDate) {
      orgQuery = orgQuery.lte("created_at", endDate);
    }

    const { data: ticketsByOrg } = await orgQuery;

    const orgTicketCounts: Record<string, { name: string; count: number }> = {};
    ticketsByOrg?.forEach((ticket: unknown) => {
      const orgId = ticket.organization_id;
      if (orgId) {
        if (!orgTicketCounts[orgId]) {
          orgTicketCounts[orgId] = {
            name: ticket.organizations?.name || "Unknown",
            count: 0,
          };
        }
        orgTicketCounts[orgId].count++;
      }
    });

    const topOrganizations = Object.entries(orgTicketCounts)
      .map(([id, data]) => ({ id, ...data }))
      .sort((a, b) => b.count - a.count)
      .slice(0, 10);

    return NextResponse.json({
      metrics: {
        totalTickets: totalTickets || 0,
        statusCounts,
        priorityCounts,
        categoryCounts,
        averageResponseTimeMinutes: avgResponseTime
          ? Math.round(avgResponseTime)
          : null,
        averageResolutionTimeMinutes: avgResolutionTime
          ? Math.round(avgResolutionTime)
          : null,
        averageSatisfactionRating: avgSatisfaction
          ? Number(avgSatisfaction.toFixed(2))
          : null,
        ticketsPerDay,
        topOrganizations,
      },
    });
  } catch (error) {
    if (error instanceof AuthorizationError) {
      return NextResponse.json({ error: error.message }, { status: 403 });
    }

    logger.error(
      "Unexpected error in GET /api/admin/saas-management/support/metrics",
      error,
    );
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { AuthorizationError } from "@/lib/api/errors";
import { requireRoot } from "@/lib/api/root-middleware";
import { appLogger as logger } from "@/lib/logger";
import { createRootAdminClient } from "@/utils/supabase/root-admin";

/**
 * GET /api/admin/saas-management/support/search
 * Búsqueda rápida de organizaciones y usuarios para soporte
 */
export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    await requireRoot(request);
    const supabaseServiceRole = createRootAdminClient();

    const { searchParams } = new URL(request.url);
    const query = searchParams.get("q");

    if (!query || query.length < 2) {
      return NextResponse.json({
        organizations: [],
        users: [],
      });
    }

    const searchTerm = `%${query}%`;

    // Buscar organizaciones
    const { data: organizations } = await supabaseServiceRole
      .from("organizations")
      .select("id, name, slug, status, subscription_tier")
      .or(`name.ilike.${searchTerm},slug.ilike.${searchTerm}`)
      .limit(10);

    // Buscar usuarios
    const { data: users } = await supabaseServiceRole
      .from("admin_users")
      .select(
        `
        id,
        email,
        role,
        is_active,
        organization_id,
        organization:organizations (
          id,
          name,
          slug
        ),
        profiles (
          first_name,
          last_name
        )
      `,
      )
      .or(`email.ilike.${searchTerm}`)
      .limit(10);

    // Buscar también por nombre en profiles
    const { data: profiles } = await supabaseServiceRole
      .from("profiles")
      .select("id, first_name, last_name, email")
      .or(
        `first_name.ilike.${searchTerm},last_name.ilike.${searchTerm},email.ilike.${searchTerm}`,
      )
      .limit(10);

    // Obtener usuarios admin asociados a los profiles encontrados
    const profileIds = profiles?.map((p) => p.id) || [];
    let additionalUsers: unknown[] = [];
    if (profileIds.length > 0) {
      const { data: usersFromProfiles } = await supabaseServiceRole
        .from("admin_users")
        .select(
          `
          id,
          email,
          role,
          is_active,
          organization_id,
          organization:organizations (
            id,
            name,
            slug
          ),
          profiles (
            first_name,
            last_name
          )
        `,
        )
        .in("id", profileIds);

      additionalUsers = usersFromProfiles || [];
    }

    // Combinar y deduplicar usuarios
    const allUsers = [
      ...(users || []),
      ...additionalUsers.filter(
        (u) => !users?.some((existing) => existing.id === u.id),
      ),
    ];

    return NextResponse.json({
      organizations: organizations || [],
      users: allUsers.slice(0, 10),
    });
  } catch (error) {
    if (error instanceof AuthorizationError) {
      return NextResponse.json({ error: error.message }, { status: 403 });
    }
    logger.error("Error in support search", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { AuthorizationError } from "@/lib/api/errors";
import { requireRoot } from "@/lib/api/root-middleware";
import { parseAndValidateBody } from "@/lib/api/validation/zod-helpers";
import { updateSaasSupportTemplateSchema } from "@/lib/api/validation/zod-schemas";
import { appLogger as logger } from "@/lib/logger";
import { createRootAdminClient } from "@/utils/supabase/root-admin";

/**
 * PATCH /api/admin/saas-management/support/templates/[id]
 * Actualizar template (solo root/dev)
 */
export const dynamic = "force-dynamic";
export async function PATCH(
  request: NextRequest,
  { params }: { params: { id: string } },
) {
  try {
    await requireRoot(request);
    const supabaseServiceRole = createRootAdminClient();

    // Validar body
    const body = await parseAndValidateBody(
      request,
      updateSaasSupportTemplateSchema,
    );

    // Preparar actualización
    const updates: Record<string, unknown> = {};

    if (body.name !== undefined) {
      updates.name = body.name;
    }

    if (body.subject !== undefined) {
      updates.subject = body.subject;
    }

    if (body.content !== undefined) {
      updates.content = body.content;
    }

    if (body.category !== undefined) {
      updates.category = body.category;
    }

    if (body.variables !== undefined) {
      updates.variables = body.variables;
    }

    if (body.is_active !== undefined) {
      updates.is_active = body.is_active;
    }

    // Actualizar template
    const { data: template, error: updateError } = await supabaseServiceRole
      .from("saas_support_templates")
      .update(updates)
      .eq("id", params.id)
      .select(
        `
        *,
        created_by_user:admin_users!saas_support_templates_created_by_fkey(id, email, role)
      `,
      )
      .single();

    if (updateError) {
      if (updateError.code === "PGRST116") {
        return NextResponse.json(
          { error: "Template not found" },
          { status: 404 },
        );
      }

      logger.error("Error updating SaaS support template", updateError);
      return NextResponse.json(
        { error: "Failed to update template" },
        { status: 500 },
      );
    }

    logger.info(`SaaS support template updated: ${template.id}`);

    return NextResponse.json({ template });
  } catch (error) {
    if (error instanceof AuthorizationError) {
      return NextResponse.json({ error: error.message }, { status: 403 });
    }

    logger.error(
      "Unexpected error in PATCH /api/admin/saas-management/support/templates/[id]",
      error,
    );
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { parseAndValidateBody } from "@/lib/api/validation/zod-helpers";
import { createSaasSupportMessageSchema } from "@/lib/api/validation/zod-schemas";
import { appLogger as logger } from "@/lib/logger";
import { createRootAdminClient } from "@/utils/supabase/root-admin";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";
export async function GET(
  request: NextRequest,
  { params }: { params: { id: string } },
) {
  try {
    const supabase = await createClient();
    const supabaseServiceRole = createRootAdminClient();

    // Obtener usuario autenticado
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: adminUser } = await supabaseServiceRole
      .from("admin_users")
      .select("id, role, organization_id")
      .eq("id", user.id)
      .single();

    const isRoot = adminUser?.role === "root" || adminUser?.role === "dev";

    const { data: ticket, error: ticketError } = await supabaseServiceRole
      .from("saas_support_tickets")
      .select("*")
      .eq("id", params.id)
      .single();

    if (ticketError || !ticket) {
      return NextResponse.json({ error: "Ticket not found" }, { status: 404 });
    }

    if (!isRoot && ticket.organization_id !== adminUser?.organization_id) {
      return NextResponse.json({ error: "Forbidden" }, { status: 403 });
    }

    let query = supabaseServiceRole
      .from("saas_support_messages")
      .select(
        `
        *,
        sender:admin_users!saas_support_messages_sender_id_fkey(id, email, role)
      `,
      )
      .eq("ticket_id", params.id)
      .order("created_at", { ascending: true });

    // Si no es root, filtrar mensajes internos
    if (!isRoot) {
      query = query.eq("is_internal", false);
    }

    const { data: messages, error: messagesError } = await query;

    if (messagesError) {
      logger.error("Error fetching SaaS support messages", messagesError);
      return NextResponse.json(
        { error: "Failed to fetch messages" },
        { status: 500 },
      );
    }

    return NextResponse.json({ messages: messages || [] });
  } catch (error) {
    logger.error(
      "Unexpected error in GET /api/admin/saas-management/support/tickets/[id]/messages",
      error,
    );
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

export async function POST(
  request: NextRequest,
  { params }: { params: { id: string } },
) {
  try {
    const supabase = await createClient();
    const supabaseServiceRole = createRootAdminClient();

    // Obtener usuario autenticado
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    // Obtener información del usuario admin
    const { data: adminUser, error: adminError } = await supabaseServiceRole
      .from("admin_users")
      .select("id, email, role, organization_id")
      .eq("id", user.id)
      .single();

    if (adminError || !adminUser) {
      return NextResponse.json({ error: "User not found" }, { status: 404 });
    }

    const isRoot = adminUser.role === "root" || adminUser.role === "dev";

    // Obtener ticket para verificar permisos
    const { data: ticket, error: ticketError } = await supabaseServiceRole
      .from("saas_support_tickets")
      .select(
        "id, organization_id, status, first_response_at, last_response_at",
      )
      .eq("id", params.id)
      .single();

    if (ticketError || !ticket) {
      return NextResponse.json({ error: "Ticket not found" }, { status: 404 });
    }

    // Verificar permisos
    if (!isRoot && ticket.organization_id !== adminUser.organization_id) {
      return NextResponse.json({ error: "Forbidden" }, { status: 403 });
    }

    // Validar body
    const body = await parseAndValidateBody(
      request,
      createSaasSupportMessageSchema,
    );

    // Determinar si el mensaje es del cliente o del soporte
    const isFromCustomer = !isRoot || body.is_internal === false;

    // Crear mensaje
    const { data: message, error: messageError } = await supabaseServiceRole
      .from("saas_support_messages")
      .insert({
        ticket_id: params.id,
        message: body.message,
        is_internal: body.is_internal || false,
        is_from_customer: isFromCustomer,
        sender_id: adminUser.id,
        sender_name: adminUser.email?.split("@")[0] || "Usuario",
        sender_email: adminUser.email || user.email || "",
        message_type: body.message_type || "message",
        attachments: body.attachments || [],
      })
      .select(
        `
        *,
        sender:admin_users!saas_support_messages_sender_id_fkey(id, email, role)
      `,
      )
      .single();

    if (messageError) {
      logger.error("Error creating SaaS support message", messageError);
      return NextResponse.json(
        { error: "Failed to create message" },
        { status: 500 },
      );
    }

    // Actualizar ticket: last_response_at y first_response_at si es la primera respuesta
    const now = new Date().toISOString();
    const updates: Record<string, unknown> = {
      last_response_at: now,
    };

    if (!(ticket as unknown)?.first_response_at && !isFromCustomer) {
      updates.first_response_at = now;

      // Calcular tiempo de primera respuesta
      if ((ticket as unknown)?.created_at) {
        const created = new Date((ticket as unknown).created_at);
        const firstResponse = new Date();
        const diffMinutes = Math.floor(
          (firstResponse.getTime() - created.getTime()) / (1000 * 60),
        );
        updates.response_time_minutes = diffMinutes;
      }
    }

    // Si el mensaje es del soporte y el ticket está en "waiting_customer", cambiar a "in_progress"
    if (!isFromCustomer && ticket.status === "waiting_customer") {
      updates.status = "in_progress";
    }

    // Si el mensaje es del cliente y el ticket está resuelto o cerrado, cambiar a "waiting_customer"
    if (
      isFromCustomer &&
      (ticket.status === "resolved" || ticket.status === "closed")
    ) {
      updates.status = "waiting_customer";
    }

    await supabaseServiceRole
      .from("saas_support_tickets")
      .update(updates)
      .eq("id", params.id);

    logger.info(`SaaS support message created for ticket: ${params.id}`);

    // Send email notification if message is from support (not internal, not from customer)
    if (!body.is_internal && !isFromCustomer) {
      try {
        if (process.env.RESEND_API_KEY) {
          // Get full ticket details for email
          const { data: fullTicket } = await supabaseServiceRole
            .from("saas_support_tickets")
            .select(
              `
              *,
              organization:organizations(id, name, slug)
            `,
            )
            .eq("id", params.id)
            .single();

          if (fullTicket) {
            const { sendSaasNewResponseEmail } = await import(
              "@/lib/email/templates/saas-support"
            );
            await sendSaasNewResponseEmail(
              {
                id: fullTicket.id,
                ticket_number: fullTicket.ticket_number,
                subject: fullTicket.subject,
                description: fullTicket.description,
                status: fullTicket.status,
                priority: fullTicket.priority,
                category: fullTicket.category,
                requester_name: fullTicket.requester_name,
                requester_email: fullTicket.requester_email,
                organization: fullTicket.organization as unknown,
              },
              {
                message: body.message,
                created_at: message.created_at,
                sender_name: message.sender_name,
                sender_email: message.sender_email,
                is_from_customer: false,
              },
            );
            logger.info("New response email sent successfully");
          }
        } else {
          logger.debug("Resend not configured, skipping email notification");
        }
      } catch (emailError) {
        logger.warn("Failed to send new response email", emailError);
        // Don't fail the request if email fails
      }
    }

    // Push notification for root/dev when customer adds message
    if (isFromCustomer) {
      try {
        const { NotificationService } = await import(
          "@/lib/notifications/notification-service"
        );
        await NotificationService.notifySaasSupportNewMessage(
          params.id,
          (ticket as unknown)?.ticket_number,
          (ticket as unknown)?.subject,
          true,
        );
      } catch (pushErr) {
        logger.warn("Failed to create support push notification", pushErr);
      }
    }

    return NextResponse.json({ message }, { status: 201 });
  } catch (error) {
    logger.error(
      "Unexpected error in POST /api/admin/saas-management/support/tickets/[id]/messages",
      error,
    );
    return NextResponse.json(
      { error: "Internal server error" },
