          ticket_number: ticket.ticket_number,
          subject: ticket.subject,
          description: body.description,
          status: ticket.status,
          priority: body.priority || "medium",
          category: body.category,
          requester_name: adminUser.email?.split("@")[0] || "Usuario",
          requester_email: adminUser.email || user.email || "",
          organization: ticket.organization as unknown,
        });
        logger.info("Ticket creation email sent successfully");
      } else {
        logger.debug("Resend not configured, skipping email notification");
      }
    } catch (emailError) {
      logger.warn("Failed to send ticket creation email", emailError);
      // Don't fail the request if email fails
    }

    // Push notification for root/dev (non-blocking)
    try {
      const { NotificationService } = await import(
        "@/lib/notifications/notification-service"
      );
      await NotificationService.notifySaasSupportTicketNew(
        ticket.id,
        ticket.ticket_number,
        ticket.subject,
        ticket.requester_email,
        ticket.organization?.name,
      );
    } catch (notifError) {
      logger.warn("Failed to create support notification", notifError);
    }

    return NextResponse.json({ ticket }, { status: 201 });
  } catch (error) {
    logger.error(
      "Unexpected error in POST /api/admin/saas-management/support/tickets",
      error,
    );
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { AuthorizationError } from "@/lib/api/errors";
import { requireRoot } from "@/lib/api/root-middleware";
import { appLogger as logger } from "@/lib/logger";
import { createRootAdminClient } from "@/utils/supabase/root-admin";

/**
 * GET /api/admin/saas-management/telemetry-config
 * Returns the global telemetry configuration (root/dev only)
 */
export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    await requireRoot(request);
    const supabase = createRootAdminClient();

    // Get telemetry state from system_config
    const { data: config, error: configError } = await supabase
      .from("system_config")
      .select("config_value")
      .eq("config_key", "telemetry_enabled")
      .maybeSingle();

    if (configError) {
      logger.error("Error fetching telemetry config:", configError);
      return NextResponse.json(
        { error: "Failed to fetch config" },
        { status: 500 },
      );
    }

    // If not found, default to true
    let enabled = true;
    if (config) {
      try {
        enabled =
          typeof config.config_value === "string"
            ? JSON.parse(config.config_value)
            : config.config_value;
      } catch (e) {
        enabled = !!config.config_value;
      }
    } else {
      // Initialize if not exists
      await supabase.from("system_config").insert({
        config_key: "telemetry_enabled",
        config_value: JSON.stringify(true),
        category: "telemetry",
        description:
          "Global toggle for usage tracking and performance monitoring",
        value_type: "boolean",
      });
    }

    return NextResponse.json({ enabled });
  } catch (error) {
    if (error instanceof AuthorizationError) {
      return NextResponse.json({ error: error.message }, { status: 403 });
    }
    logger.error("Internal error in telemetry config GET:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

/**
 * PUT /api/admin/saas-management/telemetry-config
 * Updates the global telemetry configuration (root/dev only)
 */
export async function PUT(request: NextRequest) {
  try {
    const { userId } = await requireRoot(request);
    const { enabled } = await request.json();
    const supabase = createRootAdminClient();

    // Update or Insert configuration
    const { error: updateError } = await supabase.from("system_config").upsert(
      {
        config_key: "telemetry_enabled",
        config_value: JSON.stringify(enabled),
        category: "telemetry",
        description:
          "Global toggle for usage tracking and performance monitoring",
        value_type: "boolean",
        updated_at: new Date().toISOString(),
        last_modified_by: userId,
      },
      { onConflict: "config_key" },
    );

    if (updateError) {
      logger.error("Error updating telemetry config:", updateError);
      return NextResponse.json(
        { error: "Failed to update config" },
        { status: 500 },
      );
    }

    return NextResponse.json({ success: true, enabled });
  } catch (error) {
    if (error instanceof AuthorizationError) {
      return NextResponse.json({ error: error.message }, { status: 403 });
    }
    logger.error("Internal error in telemetry config PUT:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { AuthorizationError, ValidationError } from "@/lib/api/errors";
import { requireRoot } from "@/lib/api/root-middleware";
import {
  parseAndValidateBody,
  validationErrorResponse,
} from "@/lib/api/validation/zod-helpers";
import { tierUpdateSchema } from "@/lib/api/validation/zod-schemas";
import { appLogger as logger } from "@/lib/logger";
import { createRootAdminClient } from "@/utils/supabase/root-admin";

/**
 * GET /api/admin/saas-management/tiers
 * Listar todos los tiers con estadísticas
 */
export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    await requireRoot(request);
    const supabaseServiceRole = createRootAdminClient();

    // Obtener todos los tiers
    const { data: tiers, error } = await supabaseServiceRole
      .from("subscription_tiers")
      .select("*")
      .order("price_monthly", { ascending: true });

    if (error) {
      logger.error("Error fetching tiers", error);
      return NextResponse.json(
        { error: "Failed to fetch tiers" },
        { status: 500 },
      );
    }

    // Obtener estadísticas por tier
    const tiersWithStats = await Promise.all(
      (tiers || []).map(async (tier) => {
        // Contar organizaciones por tier
        const { count: orgCount } = await supabaseServiceRole
          .from("organizations")
          .select("*", { count: "exact", head: true })
          .eq("subscription_tier", tier.name);

        // Contar organizaciones activas
        const { count: activeOrgCount } = await supabaseServiceRole
          .from("organizations")
          .select("*", { count: "exact", head: true })
          .eq("subscription_tier", tier.name)
          .eq("status", "active");

        // Calcular ingresos mensuales estimados (precio * organizaciones activas)
        const monthlyRevenue =
          (tier.price_monthly || 0) * (activeOrgCount || 0);

        return {
          ...tier,
          stats: {
            totalOrganizations: orgCount || 0,
            activeOrganizations: activeOrgCount || 0,
            estimatedMonthlyRevenue: monthlyRevenue,
          },
        };
      }),
    );

    return NextResponse.json({ tiers: tiersWithStats });
  } catch (error) {
    if (error instanceof AuthorizationError) {
      return NextResponse.json({ error: error.message }, { status: 403 });
    }
    logger.error("Error in tiers API GET", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

/**
 * PATCH /api/admin/saas-management/tiers/[name]
 * Actualizar tier existente
 */
export async function PATCH(request: NextRequest) {
  try {
    await requireRoot(request);
    const supabaseServiceRole = createRootAdminClient();

    let body;
    try {
      body = await parseAndValidateBody(request, tierUpdateSchema);
    } catch (error) {
      if (error instanceof ValidationError) {
        return validationErrorResponse(error);
      }
      throw error;
    }

    const {
      name,
      price_monthly,
      max_branches,
      max_users,
      max_customers,
      max_products,
      features,
    } = body;

    // Validar que el tier existe
    const { data: existingTier } = await supabaseServiceRole
      .from("subscription_tiers")
      .select("name")
      .eq("name", name)
      .single();

    if (!existingTier) {
      return NextResponse.json({ error: "Tier not found" }, { status: 404 });
    }

    // Preparar updates
    const updates: unknown = {};

    if (price_monthly !== undefined) {
      if (price_monthly < 0) {
        return NextResponse.json(
          { error: "price_monthly debe ser mayor o igual a 0" },
          { status: 400 },
        );
      }
      updates.price_monthly = price_monthly;
    }

    // NULL = unlimited; 0, null, undefined from client -> store NULL in DB
    const toLimitValue = (v: number | null | undefined) =>
      v == null || v === 0 ? null : v;

    if (max_branches !== undefined) {
      updates.max_branches = toLimitValue(max_branches);
    }

    if (max_users !== undefined) {
      updates.max_users = toLimitValue(max_users);
    }

    if (max_customers !== undefined) {
      updates.max_customers = toLimitValue(max_customers);
    }

    if (max_products !== undefined) {
      updates.max_products = toLimitValue(max_products);
    }

    if (features !== undefined) {
      updates.features = features;
    }

    // Actualizar
    const { data: updatedTier, error: updateError } = await supabaseServiceRole
      .from("subscription_tiers")
      .update(updates)
      .eq("name", name)
      .select()
      .single();

    if (updateError) {
      logger.error("Error updating tier", updateError);
      return NextResponse.json(
        { error: "Failed to update tier", details: updateError.message },
        { status: 500 },
      );
    }

    logger.info(`Tier updated: ${name}`);

    return NextResponse.json({ tier: updatedTier });
  } catch (error) {
    if (error instanceof AuthorizationError) {
      return NextResponse.json({ error: error.message }, { status: 403 });
    }
    logger.error("Error updating tier", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { AuthorizationError } from "@/lib/api/errors";
import { requireRoot } from "@/lib/api/root-middleware";
import { appLogger as logger } from "@/lib/logger";
import { createRootAdminClient } from "@/utils/supabase/root-admin";

/**
 * POST /api/admin/saas-management/users/[id]/actions
 * Acciones sobre usuarios: cambiar organización, activar/desactivar, resetear contraseña
 */
export const dynamic = "force-dynamic";
export async function POST(
  request: NextRequest,
  { params }: { params: { id: string } },
) {
  try {
    await requireRoot(request);
    const supabaseServiceRole = createRootAdminClient();

    const { id } = params;
    const body = await request.json();
    const { action, value } = body;

    // Verificar que el usuario existe
    const { data: user } = await supabaseServiceRole
      .from("admin_users")
      .select("id, email, is_active, organization_id")
      .eq("id", id)
      .single();

    if (!user) {
      return NextResponse.json({ error: "User not found" }, { status: 404 });
    }

    const updateData: unknown = {};

    switch (action) {
      case "activate":
        updateData.is_active = true;
        break;

      case "deactivate":
        updateData.is_active = false;
        break;

      case "change_organization":
        if (!value) {
          return NextResponse.json(
            { error: "organization_id es requerido" },
            { status: 400 },
          );
        }

        // Validar que la organización existe
        const { data: org } = await supabaseServiceRole
          .from("organizations")
          .select("id")
          .eq("id", value)
          .maybeSingle();

        if (!org) {
          return NextResponse.json(
            { error: "Organization not found" },
            { status: 400 },
          );
        }

        updateData.organization_id = value;
        break;

      case "reset_password":
        // Enviar email de reset de contraseña usando Supabase Auth Admin API
        const { error: resetError } =
          await supabaseServiceRole.auth.admin.generateLink({
            type: "recovery",
            email: user.email,
          });

        if (resetError) {
          logger.error("Error generating password reset link", resetError);
          return NextResponse.json(
            {
              error: "Failed to generate password reset link",
              details: resetError.message,
            },
            { status: 500 },
          );
        }

        return NextResponse.json({
          success: true,
          message: "Password reset link generated. Check user email.",
        });

      default:
        return NextResponse.json(
          { error: `Acción inválida: ${action}` },
          { status: 400 },
        );
    }

    // Aplicar actualización si hay cambios
    if (Object.keys(updateData).length > 0) {
      const { data: updatedUser, error: updateError } =
        await supabaseServiceRole
          .from("admin_users")
          .update(updateData)
          .eq("id", id)
          .select()
          .single();

      if (updateError) {
        logger.error("Error performing action on user", updateError);
        return NextResponse.json(
          { error: "Failed to perform action", details: updateError.message },
          { status: 500 },
        );
      }

      logger.info(`User action performed: ${action} on ${id}`);

      return NextResponse.json({
        success: true,
        user: updatedUser,
        action,
      });
    }

    return NextResponse.json({ success: true });
  } catch (error) {
    if (error instanceof AuthorizationError) {
      return NextResponse.json({ error: error.message }, { status: 403 });
    }
    logger.error("Error in user action", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { AuthorizationError } from "@/lib/api/errors";
import { requireRoot } from "@/lib/api/root-middleware";
import { updateSaasUserSchema } from "@/lib/api/validation/zod-schemas";
import { appLogger as logger } from "@/lib/logger";
import { createRootAdminClient } from "@/utils/supabase/root-admin";

export const dynamic = "force-dynamic";
export async function GET(
  request: NextRequest,
  { params }: { params: { id: string } },
) {
  try {
    await requireRoot(request);
    const supabaseServiceRole = createRootAdminClient();

    const { id } = params;

    const { data: user, error } = await supabaseServiceRole
      .from("admin_users")
      .select("*")
      .eq("id", id)
      .single();

    if (error || !user) {
      logger.error("Error fetching user", error);
      return NextResponse.json(
        { error: "User not found", details: error?.message },
        { status: 404 },
      );
    }

    const [organization, profile, branchAccess] = await Promise.all([
      user.organization_id
        ? supabaseServiceRole.from("organizations").select("id, name, slug, subscription_tier, status").eq("id", user.organization_id).maybeSingle().then(r => r.data)
        : null,
      supabaseServiceRole.from("profiles").select("id, email, first_name, last_name, phone, created_at").eq("id", user.id).maybeSingle().then(r => r.data),
      supabaseServiceRole.from("admin_branch_access").select("id, branch_id, role, is_primary").eq("admin_user_id", id).then(r => r.data),
    ]);

    const enrichedBranchAccess = await Promise.all(
      (branchAccess || []).map(async (access: unknown) => {
        if (!access.branch_id) return access;
        const { data: branch } = await supabaseServiceRole
          .from("branches")
          .select("id, name, code, organization_id")
          .eq("id", access.branch_id)
          .maybeSingle();
        return { ...access, branches: branch };
      }),
    );

    const { data: recentActivity } = await supabaseServiceRole
      .from("admin_activity_log")
      .select("*")
      .eq("admin_user_id", id)
      .order("created_at", { ascending: false })
      .limit(20);

    return NextResponse.json({
      user: {
        ...user,
        organization: organization || null,
        profiles: profile || null,
        admin_branch_access: enrichedBranchAccess || [],
        recentActivity: recentActivity || [],
      },
    });
  } catch (error) {
    if (error instanceof AuthorizationError) {
      return NextResponse.json({ error: error.message }, { status: 403 });
    }
    logger.error("Error fetching user details", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

export async function PATCH(
  request: NextRequest,
  { params }: { params: { id: string } },
) {
  try {
    await requireRoot(request);
    const supabaseServiceRole = createRootAdminClient();

    const { id } = params;
    const body = await request.json();
    const parseResult = updateSaasUserSchema.safeParse(body);
    if (!parseResult.success) {
      const firstError = parseResult.error.errors[0];
      return NextResponse.json(
        { error: firstError?.message || "Datos inválidos" },
        { status: 400 },
      );
    }
    const { organization_id, role, is_active, permissions } = parseResult.data;

    // Verificar que el usuario existe
    const { data: existingUser } = await supabaseServiceRole
      .from("admin_users")
      .select("id, organization_id")
      .eq("id", id)
      .single();

    if (!existingUser) {
      return NextResponse.json({ error: "User not found" }, { status: 404 });
    }

    // Preparar updates
    const updates: unknown = {};

    if (organization_id !== undefined) {
      // Validar que la organización existe si se proporciona
      if (organization_id) {
        const { data: org } = await supabaseServiceRole
          .from("organizations")
          .select("id")
          .eq("id", organization_id)
          .maybeSingle();

        if (!org) {
          return NextResponse.json(
            { error: "Organization not found" },
            { status: 400 },
          );
        }
      }
      updates.organization_id = organization_id;
    }

    if (role !== undefined) updates.role = role;

    if (is_active !== undefined) {
      updates.is_active = is_active;
    }

    if (permissions !== undefined) {
      updates.permissions = permissions;
    }

    // Actualizar
    const { data: updatedUser, error: updateError } = await supabaseServiceRole
      .from("admin_users")
      .update(updates)
      .eq("id", id)
      .select()
      .single();

    if (updateError) {
      logger.error("Error updating user", updateError);
      return NextResponse.json(
        { error: "Failed to update user", details: updateError.message },
        { status: 500 },
      );
    }

    logger.info(`User updated: ${id}`);

    return NextResponse.json({ user: updatedUser });
  } catch (error) {
    if (error instanceof AuthorizationError) {
      return NextResponse.json({ error: error.message }, { status: 403 });
    }
    logger.error("Error updating user", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

export async function DELETE(
  request: NextRequest,
  { params }: { params: { id: string } },
) {
  try {
    await requireRoot(request);
    const supabaseServiceRole = createRootAdminClient();

    const { id } = params;

    // Verificar que el usuario existe
    const { data: existingUser } = await supabaseServiceRole
      .from("admin_users")
      .select("id, email, role, organization_id")
      .eq("id", id)
      .single();

    if (!existingUser) {
      return NextResponse.json({ error: "User not found" }, { status: 404 });
    }

    // Prevenir eliminación de usuarios root/dev
    if (existingUser.role === "root" || existingUser.role === "dev") {
      return NextResponse.json(
        {
          error: "Cannot delete root or dev users",
          details: "Root and dev users are protected and cannot be deleted",
        },
        { status: 403 },
      );
    }

    // Verificar confirmación en el body (requerido para consistencia con organizations)
    let body: { confirm?: boolean } = {};
    try {
      const bodyText = await request.text();
      if (bodyText) {
        body = JSON.parse(bodyText);
      }
    } catch {
      // Si no hay body o no es JSON válido
    }

    if (body.confirm !== true) {
      return NextResponse.json(
        {
          error: "Confirmación requerida",
          details:
            "Debe enviar { confirm: true } en el body para eliminar el usuario",
        },
        { status: 400 },
      );
    }

    logger.info(`Deleting user ${id} (${existingUser.email})`);

    // Eliminar admin_branch_access primero
    await supabaseServiceRole
      .from("admin_branch_access")
      .delete()
      .eq("admin_user_id", id);

    // Eliminar admin_users (esto activará CASCADE en admin_activity_log)
    await supabaseServiceRole.from("admin_users").delete().eq("id", id);

    // Eliminar el usuario de auth.users (esto activará CASCADE en profiles)
    const { error: deleteAuthError } =
      await supabaseServiceRole.auth.admin.deleteUser(id);

    if (deleteAuthError) {
      logger.error("Error deleting auth user", deleteAuthError);
      // No hacer rollback porque admin_users ya fue eliminado
      return NextResponse.json(
        {
          error: "Failed to delete auth user",
          details: deleteAuthError.message,
          warning:
            "User admin record was deleted but auth user deletion failed",
        },
        { status: 500 },
      );
    }

    logger.info(`User deleted successfully: ${id} (${existingUser.email})`);

    return NextResponse.json({
      success: true,
      message: "Usuario eliminado completamente",
      deleted: {
        userId: id,
        email: existingUser.email,
      },
    });
  } catch (error) {
    if (error instanceof AuthorizationError) {
      return NextResponse.json({ error: error.message }, { status: 403 });
    }
    logger.error("Error deleting user", error);
    return NextResponse.json(
      {
        error: "Internal server error",
        details: error instanceof Error ? error.message : "Unknown error",
      },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { AuthorizationError } from "@/lib/api/errors";
import { requireRoot } from "@/lib/api/root-middleware";
import { appLogger as logger } from "@/lib/logger";
import { createRootAdminClient } from "@/utils/supabase/root-admin";

export async function handleGET(request: NextRequest) {
  try {
    await requireRoot(request);
    const supabaseServiceRole = createRootAdminClient();
    const { searchParams } = new URL(request.url);
    const organizationId = searchParams.get("organization_id");
    const role = searchParams.get("role");
    const status = searchParams.get("status");
    const search = searchParams.get("search");
    const page = parseInt(searchParams.get("page") || "1");
    const limit = parseInt(searchParams.get("limit") || "20");
    const offset = (page - 1) * limit;

    let query = supabaseServiceRole.from("admin_users").select("*", { count: "exact" }).order("created_at", { ascending: false });
    if (organizationId && organizationId !== "all") query = query.eq("organization_id", organizationId);
    if (role && role !== "all") query = query.eq("role", role);
    if (status && status !== "all") query = query.eq("is_active", status === "active");
    if (search) query = query.or("email.ilike.%".concat(search, "%"));
    query = query.range(offset, offset + limit - 1);

    const { data: users, error, count } = await query;
    if (error) return NextResponse.json({ error: "Failed to fetch users", details: error.message }, { status: 500 });

    const usersWithDetails = await Promise.all(
      (users || []).map(async (user: unknown) => {
        const { data: profile } = await supabaseServiceRole.from("profiles").select("id, first_name, last_name, phone").eq("id", user.id).maybeSingle();
        let organization = null;
        if (user.organization_id) {
          const { data: org } = await supabaseServiceRole.from("organizations").select("id, name, slug").eq("id", user.organization_id).maybeSingle();
          organization = org;
        }
        const { data: branchAccess } = await supabaseServiceRole.from("admin_branch_access").select("id, branch_id, branches(id, name, code)").eq("admin_user_id", user.id);
        const isSuperAdmin = branchAccess?.some((a: unknown) => a.branch_id === null) ?? false;
        const branches = (branchAccess || []).filter((a: unknown) => a.branch_id !== null).map((a: unknown) => ({ id: a.branch_id, name: a.branches?.[0]?.name ?? "N/A", code: a.branches?.[0]?.code ?? "N/A" }));
        return { ...user, profiles: profile, organization, is_super_admin: isSuperAdmin, branches, fullName: profile ? (profile.first_name + " " + (profile.last_name || "")).trim() || null : null };
      }),
    );

    let filteredUsers = usersWithDetails;
    if (search) {
      const searchLower = search.toLowerCase();
      filteredUsers = usersWithDetails.filter((u: unknown) => u.email?.toLowerCase().includes(searchLower) || u.fullName?.toLowerCase().includes(searchLower));
    }

    return NextResponse.json({ users: filteredUsers, pagination: { page, limit, total: search ? filteredUsers.length : count || 0, totalPages: search ? 1 : Math.ceil((count || 0) / limit) } });
  } catch (error) {
    if (error instanceof AuthorizationError) return NextResponse.json({ error: error.message }, { status: 403 });
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

export async function handlePOST(request: NextRequest) {
  try {
    await requireRoot(request);
    const supabaseServiceRole = createRootAdminClient();
    const body = await request.json();
    const email = body.email, password = body.password, first_name = body.first_name, last_name = body.last_name;
    const role = body.role ?? "admin", organization_id = body.organization_id, branch_id = body.branch_id;

    if (!email || !password) return NextResponse.json({ error: "Email y contraseña son requeridos" }, { status: 400 });
    if (password.length < 8) return NextResponse.json({ error: "La contraseña debe tener al menos 8 caracteres" }, { status: 400 });
    const validRoles = ["root", "dev", "super_admin", "admin", "employee", "vendedor"];
    if (!validRoles.includes(role)) return NextResponse.json({ error: "Rol inválido. Permitidos: " + validRoles.join(", ") }, { status: 400 });

    if (organization_id) {
      const { data: org } = await supabaseServiceRole.from("organizations").select("id").eq("id", organization_id).maybeSingle();
      if (!org) return NextResponse.json({ error: "Organización no encontrada" }, { status: 400 });
      const { validateTierLimit } = await import("@/lib/saas/tier-validator");
      const userLimit = await validateTierLimit(organization_id, "users");
      if (!userLimit.allowed) return NextResponse.json({ error: userLimit.reason ?? "Límite de usuarios alcanzado.", code: "TIER_LIMIT" }, { status: 403 });
    }

    const { data: newAuthUser, error: createError } = await supabaseServiceRole.auth.admin.createUser({ email, password, email_confirm: true });
    if (createError || !newAuthUser?.user) return NextResponse.json({ error: "Error al crear usuario" }, { status: 500 });

    await supabaseServiceRole.from("profiles").upsert({ id: newAuthUser.user.id, first_name: first_name ?? null, last_name: last_name ?? null }, { onConflict: "id" });
    const { data: newAdmin, error: adminError } = await supabaseServiceRole.from("admin_users").insert({ id: newAuthUser.user.id, email, role, permissions: {}, is_active: true, organization_id: organization_id || null }).select().single();
    if (adminError) {
      try { await supabaseServiceRole.auth.admin.deleteUser(newAuthUser.user.id); } catch (e) { logger.warn("Rollback delete auth user", e); }
      return NextResponse.json({ error: "Error al crear registro de administrador" }, { status: 500 });
    }

    if (organization_id && branch_id) {
      const { data: branch } = await supabaseServiceRole.from("branches").select("id, organization_id").eq("id", branch_id).eq("organization_id", organization_id).maybeSingle();
      if (branch) await supabaseServiceRole.from("admin_branch_access").insert({ admin_user_id: newAdmin.id, branch_id, role: role === "employee" || role === "vendedor" ? "staff" : "manager", is_primary: true });
    } else if (role === "super_admin") {
      await supabaseServiceRole.from("admin_branch_access").insert({ admin_user_id: newAdmin.id, branch_id: null, role: "manager", is_primary: true });
    }

    return NextResponse.json({ success: true, user: { id: newAdmin.id, email: newAdmin.email, role: newAdmin.role, organization_id: newAdmin.organization_id } }, { status: 201 });
  } catch (error) {
    if (error instanceof AuthorizationError) return NextResponse.json({ error: error.message }, { status: 403 });
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

/**
 * POST /api/admin/saas-management/whatsapp/connect
 * Guarda waba_id y phone_number_id para una organización (root solo)
 * Body: { organization_id, waba_id, phone_number_id, display_phone_number? }
 */

import { NextRequest, NextResponse } from "next/server";

import { requireRoot } from "@/lib/api/root-middleware";
import { appLogger as logger } from "@/lib/logger";
import { createRootAdminClient } from "@/utils/supabase/root-admin";

export const dynamic = "force-dynamic";

export async function POST(request: NextRequest) {
  try {
    await requireRoot(request);
    const supabase = createRootAdminClient();

    const body = await request.json();
    const { organization_id, waba_id, phone_number_id, display_phone_number } =
      body;

    if (!organization_id || !waba_id || !phone_number_id) {
      return NextResponse.json(
        { error: "organization_id, waba_id y phone_number_id son requeridos" },
        { status: 400 },
      );
    }

    const { data: org, error: orgError } = await supabase
      .from("organizations")
      .select("id")
      .eq("id", organization_id)
      .single();

    if (orgError || !org) {
      return NextResponse.json(
        { error: "Organización no encontrada" },
        { status: 404 },
      );
    }

    const { data: existing } = await supabase
      .from("whatsapp_phone_numbers")
      .select("id")
      .eq("organization_id", organization_id)
      .maybeSingle();

    const payload = {
      organization_id: String(organization_id),
      phone_number_id: String(phone_number_id),
      waba_id: String(waba_id),
      display_phone_number: display_phone_number
        ? String(display_phone_number).trim()
        : null,
      updated_at: new Date().toISOString(),
    };

    if (existing) {
      const { error: updateError } = await supabase
        .from("whatsapp_phone_numbers")
        .update(payload)
        .eq("id", existing.id);

      if (updateError) {
        if (updateError.code === "23505") {
          return NextResponse.json(
            {
              error:
                "Este número ya está conectado a otra organización. Usa un número distinto.",
            },
            { status: 409 },
          );
        }
        logger.error("WhatsApp connect update failed", {
          error: updateError.message,
          organizationId: organization_id,
        });
        return NextResponse.json(
          { error: "Error al actualizar configuración" },
          { status: 500 },
        );
      }
      return NextResponse.json({
        success: true,
        message: "WhatsApp actualizado",
        updated: true,
      });
    }

    const { error: insertError } = await supabase
      .from("whatsapp_phone_numbers")
      .insert(payload);

    if (insertError) {
      if (insertError.code === "23505") {
        return NextResponse.json(
          {
            error:
              "Este número ya está conectado a otra organización. Usa un número distinto.",
          },
          { status: 409 },
        );
      }
      logger.error("WhatsApp connect insert failed", {
        error: insertError.message,
        organizationId: organization_id,
      });
      return NextResponse.json(
        { error: "Error al conectar WhatsApp" },
        { status: 500 },
      );
    }

    return NextResponse.json({
      success: true,
      message: "WhatsApp conectado correctamente",
    });
  } catch (error) {
    const err = error instanceof Error ? error : new Error(String(error));
    logger.error("WhatsApp connect error", err);
    return NextResponse.json(
      { error: err.message || "Error interno del servidor" },
      { status: 500 },
    );
  }
}

/**
 * GET /api/admin/saas-management/whatsapp/conversations/[sessionId]/messages
 * Lista mensajes de una sesión WhatsApp (root solo)
 */

import { NextRequest, NextResponse } from "next/server";

import { requireRoot } from "@/lib/api/root-middleware";
import { appLogger as logger } from "@/lib/logger";
import { createRootAdminClient } from "@/utils/supabase/root-admin";

export const dynamic = "force-dynamic";

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ sessionId: string }> },
) {
  try {
    await requireRoot(request);
    const supabase = createRootAdminClient();
    const { sessionId } = await params;

    if (!sessionId) {
      return NextResponse.json(
        { error: "sessionId es requerido" },
        { status: 400 },
      );
    }

    const { data: session, error: sessionError } = await supabase
      .from("chat_sessions")
      .select("id, metadata")
      .eq("id", sessionId)
      .single();

    if (sessionError || !session) {
      return NextResponse.json(
        { error: "Sesión no encontrada" },
        { status: 404 },
      );
    }

    const metadata = session.metadata as Record<string, unknown> | null;
    if (metadata?.channel !== "whatsapp") {
      return NextResponse.json(
        { error: "Sesión no es de WhatsApp" },
        { status: 400 },
      );
    }

    const { data: messages, error } = await supabase
      .from("chat_messages")
      .select("id, role, content, created_at, metadata")
      .eq("session_id", sessionId)
      .order("created_at", { ascending: true });

    if (error) {
      logger.error("WhatsApp messages fetch error", {
        error: error.message,
        sessionId,
      });
      return NextResponse.json(
        { error: "Error al obtener mensajes" },
        { status: 500 },
      );
    }

    return NextResponse.json({ messages: messages || [] });
  } catch (error) {
    const err = error instanceof Error ? error : new Error(String(error));
    logger.error("WhatsApp messages error", err);
    return NextResponse.json(
      { error: err.message || "Error interno" },
      { status: 500 },
    );
  }
}

/**
 * GET /api/admin/saas-management/whatsapp/conversations
 * Lista sesiones WhatsApp (root solo)
 * Query: ?organization_id=uuid&limit=50&offset=0
 */

import { NextRequest, NextResponse } from "next/server";

import { requireRoot } from "@/lib/api/root-middleware";
import { appLogger as logger } from "@/lib/logger";
import { createRootAdminClient } from "@/utils/supabase/root-admin";

export const dynamic = "force-dynamic";

export async function GET(request: NextRequest) {
  try {
    await requireRoot(request);
    const supabase = createRootAdminClient();

    const { searchParams } = new URL(request.url);
    const organizationId = searchParams.get("organization_id");
    const limit = Math.min(parseInt(searchParams.get("limit") || "50"), 100);
    const offset = parseInt(searchParams.get("offset") || "0");

    let query = supabase
      .from("chat_sessions")
      .select(
        "id, title, metadata, organization_id, message_count, last_message_preview, updated_at, created_at",
      )
      .eq("metadata->>channel", "whatsapp")
      .order("updated_at", { ascending: false })
      .range(offset, offset + limit - 1);

    if (organizationId) {
      query = query.eq("organization_id", organizationId);
    }

    const { data: sessions, error } = await query;

    if (error) {
      logger.error("WhatsApp conversations fetch error", {
        error: error.message,
      });
      return NextResponse.json(
        { error: "Error al obtener conversaciones" },
        { status: 500 },
      );
    }

    const orgIds = [
      ...new Set(
        (sessions || [])
          .map((s) => s.organization_id)
          .filter(Boolean) as string[],
      ),
    ];
    let organizations: Record<string, { name: string; slug: string }> = {};

    if (orgIds.length > 0) {
      const { data: orgs } = await supabase
        .from("organizations")
        .select("id, name, slug")
        .in("id", orgIds);
      organizations = (orgs || []).reduce(
        (acc, o) => {
          acc[o.id] = { name: o.name, slug: o.slug };
          return acc;
        },
        {} as Record<string, { name: string; slug: string }>,
      );
    }

    const sessionsWithOrg = (sessions || []).map((s) => ({
      ...s,
      wa_id: (s.metadata as Record<string, unknown>)?.wa_id ?? null,
      organization:
        s.organization_id && organizations[s.organization_id]
          ? organizations[s.organization_id]
          : null,
    }));

    return NextResponse.json({
      sessions: sessionsWithOrg,
    });
  } catch (error) {
    const err = error instanceof Error ? error : new Error(String(error));
    logger.error("WhatsApp conversations error", err);
    return NextResponse.json(
      { error: err.message || "Error interno" },
      { status: 500 },
    );
  }
}

