import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { createApiSuccessResponse } from "@/lib/api/response";
import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

import { DEFAULT_SCHEDULE_SETTINGS } from "./_helpers/defaultSettings";

export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    // Get branch context
    const branchContext = await getBranchContext(request, user.id);

    if (!branchContext.organizationId) {
      return NextResponse.json(
        { error: "Organization ID not found" },
        { status: 404 },
      );
    }

    // Get schedule settings for current branch (or default if no branch selected)
    // RLS handles org security for the 'supabase' client
    let query = supabase
      .from("schedule_settings")
      .select("*")
      .eq("organization_id", branchContext.organizationId);

    if (branchContext.branchId) {
      query = query.eq("branch_id", branchContext.branchId);
    } else {
      query = query.is("branch_id", null);
    }

    const { data: settings, error } = await query.limit(1).maybeSingle();

    if (error && error.code !== "PGRST116") {
      // PGRST116 = no rows returned
      logger.error("Error fetching schedule settings:", {
        error,
        branchId: branchContext.branchId,
      });
      return NextResponse.json(
        {
          error: "Failed to fetch schedule settings",
          details: error.message,
        },
        { status: 500 },
      );
    }

    // Return default settings if none exist
    const defaultSettings = DEFAULT_SCHEDULE_SETTINGS;

    const settingsToReturn = settings ?? defaultSettings;
    return createApiSuccessResponse(settingsToReturn);
  } catch (error) {
    logger.error("Error in schedule settings API:", { error });
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

export async function PUT(request: NextRequest) {
  try {
    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    // Get branch context
    const branchContext = await getBranchContext(request, user.id);

    if (!branchContext.organizationId) {
      return NextResponse.json(
        { error: "Organization ID not found" },
        { status: 404 },
      );
    }

    const body = (await request.json().catch(() => ({}))) as Record<
      string,
      unknown
    >;

    // Check if settings exist for this branch/org
    // Use service role to bypass RLS, so MUST filter by organization_id
    let existingQuery = supabase
      .from("schedule_settings")
      .select("id")
      .eq("organization_id", branchContext.organizationId);

    if (branchContext.branchId) {
      existingQuery = existingQuery.eq("branch_id", branchContext.branchId);
    } else {
      existingQuery = existingQuery.is("branch_id", null);
    }

    const { data: existingSettings } = await existingQuery
      .limit(1)
      .maybeSingle();

    const updateData: unknown = {
      updated_at: new Date().toISOString(),
      // updated_by will be set only if user.id is valid (FK constraint may fail)
    };

    // Only add updated_by if we have a valid user id (FK constraint)
    if (user.id) {
      updateData.updated_by = user.id;
    }

    if (body.slot_duration_minutes !== undefined)
      updateData.slot_duration_minutes = body.slot_duration_minutes;
    if (body.default_appointment_duration !== undefined)
      updateData.default_appointment_duration =
        body.default_appointment_duration;
    if (body.buffer_time_minutes !== undefined)
      updateData.buffer_time_minutes = body.buffer_time_minutes;
    if (body.working_hours !== undefined)
      updateData.working_hours = body.working_hours;
    if (body.blocked_dates !== undefined)
      updateData.blocked_dates = body.blocked_dates;
    if (body.min_advance_booking_hours !== undefined)
      updateData.min_advance_booking_hours = body.min_advance_booking_hours;
    if (body.max_advance_booking_days !== undefined)
      updateData.max_advance_booking_days = body.max_advance_booking_days;
    if (body.staff_specific_settings !== undefined)
      updateData.staff_specific_settings = body.staff_specific_settings;

    let result;

    // 1. Update or Insert the specific record
    if (existingSettings) {
      // Update existing
      const { data, error } = await supabase
        .from("schedule_settings")
        .update({
          ...updateData,
          organization_id: branchContext.organizationId,
        })
        .eq("id", existingSettings.id)
        .select()
        .single();

      if (error) {
        logger.error("Error updating schedule settings:", {
          error,
          branchId: branchContext.branchId,
          settingsId: existingSettings.id,
        });
        return NextResponse.json(
          {
            error: "Failed to update schedule settings",
            details: error.message,
          },
          { status: 500 },
        );
      }
      result = data;
    } else {
      // Insert new
      const { data, error } = await supabase
        .from("schedule_settings")
        .insert({
          ...updateData,
          organization_id: branchContext.organizationId,
          branch_id: branchContext.branchId || null,
        })
        .select()
        .single();

      if (error) {
        logger.error("Error creating schedule settings:", {
          error,
          branchId: branchContext.branchId,
        });
        return NextResponse.json(
          {
            error: "Failed to create schedule settings",
            details: error.message,
          },
          { status: 500 },
        );
      }
      result = data;
    }

    // 2. If GLOBAL update by Super Admin, SYNC to all branches
    if (!branchContext.branchId && branchContext.isSuperAdmin) {
      logger.info("Syncing Global schedule settings to all branches", {
        organizationId: branchContext.organizationId,
      });

      const { data: branches } = await supabase
        .from("branches")
        .select("id")
        .eq("organization_id", branchContext.organizationId);

      if (branches && branches.length > 0) {
        for (const branch of branches) {
          await supabase.from("schedule_settings").upsert(
            {
              organization_id: branchContext.organizationId,
              branch_id: branch.id,
              ...updateData,
            },
            { onConflict: "organization_id,branch_id" },
          );
        }
      }
    }

    return NextResponse.json({
      success: true,
      settings: result,
    });
  } catch (error) {
    logger.error("Error in schedule settings PUT API:", { error });
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

/**
 * POST /api/admin/subscription/actions
 * Acciones sobre la suscripción de la organización del usuario actual (cancelar, etc.)
 */
import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";
export async function POST(request: NextRequest) {
  try {
    const supabase = await createClient();
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user) {
      return NextResponse.json({ error: "No autenticado" }, { status: 401 });
    }

    const { data: adminUser } = await supabase
      .from("admin_users")
      .select("organization_id")
      .eq("id", user.id)
      .maybeSingle();

    const organizationId = adminUser?.organization_id;
    if (!organizationId) {
      return NextResponse.json(
        { error: "No tienes una organización asignada" },
        { status: 400 },
      );
    }

    const body = await request.json();
    const { action } = body;

    if (!action) {
      return NextResponse.json(
        { error: "Se requiere el campo action" },
        { status: 400 },
      );
    }

    if (action === "cancel") {
      const { data: sub } = await supabase
        .from("subscriptions")
        .select("id, status, current_period_end")
        .eq("organization_id", organizationId)
        .in("status", ["active", "trialing", "past_due", "incomplete"])
        .order("created_at", { ascending: false })
        .limit(1)
        .maybeSingle();

      if (!sub) {
        return NextResponse.json(
          { error: "No hay suscripción activa para cancelar" },
          { status: 404 },
        );
      }

      // Set cancel_at to current_period_end (access until end of paid period)
      // If no current_period_end, use today + 30 days as fallback
      const cancelAt = sub.current_period_end
        ? new Date(sub.current_period_end).toISOString().split("T")[0]
        : new Date(Date.now() + 30 * 24 * 60 * 60 * 1000)
            .toISOString()
            .split("T")[0];

      const { error: updateError } = await supabase
        .from("subscriptions")
        .update({
          status: "cancelled",
          cancel_at: cancelAt,
          canceled_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        })
        .eq("id", sub.id);

      if (updateError) {
        logger.error("Error cancelling subscription", updateError);
        return NextResponse.json(
          { error: "Error al cancelar la suscripción" },
          { status: 500 },
        );
      }

      return NextResponse.json({
        success: true,
        message: `Suscripción cancelada. Tendrás acceso completo hasta ${cancelAt}.`,
        cancelAt,
      });
    }

    if (action === "reactivate") {
      const { data: sub } = await supabase
        .from("subscriptions")
        .select("id, status")
        .eq("organization_id", organizationId)
        .eq("status", "cancelled")
        .order("created_at", { ascending: false })
        .limit(1)
        .maybeSingle();

      if (!sub) {
        return NextResponse.json(
          { error: "No hay suscripción cancelada para reactivar" },
          { status: 404 },
        );
      }

      const { error: updateError } = await supabase
        .from("subscriptions")
        .update({
          status: "active",
          cancel_at: null,
          canceled_at: null,
          updated_at: new Date().toISOString(),
        })
        .eq("id", sub.id);

      if (updateError) {
        logger.error("Error reactivating subscription", updateError);
        return NextResponse.json(
          { error: "Error al reactivar la suscripción" },
          { status: 500 },
        );
      }

      return NextResponse.json({
        success: true,
        message: "Suscripción reactivada.",
      });
    }

    return NextResponse.json(
      { error: `Acción no permitida: ${action}` },
      { status: 400 },
    );
  } catch (error) {
    logger.error("Error in subscription actions API", error);
    return NextResponse.json(
      { error: "Error interno del servidor" },
      { status: 500 },
    );
  }
}

/**
 * POST /api/admin/subscription/change-plan
 * Cambia el plan de suscripción de la organización del usuario actual.
 * Maneja upgrade/downgrade de forma justa:
 * - Upgrade: cambio inmediato, prorrateo del costo restante del periodo actual
 * - Downgrade: cambio al final del periodo actual (sin prorrateo)
 */
import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import { getSubscriptionStatus } from "@/lib/saas/subscription-status";
import { recordTierChange } from "@/lib/saas/tier-change-audit";
import type { SubscriptionTier } from "@/lib/saas/tier-config";
import { canUpgrade } from "@/lib/saas/tier-config";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";
export async function POST(request: NextRequest) {
  try {
    const supabase = await createClient();
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user) {
      return NextResponse.json({ error: "No autenticado" }, { status: 401 });
    }

    const { data: adminUser } = await supabase
      .from("admin_users")
      .select("organization_id")
      .eq("id", user.id)
      .maybeSingle();

    const organizationId = adminUser?.organization_id;
    if (!organizationId) {
      return NextResponse.json(
        { error: "No tienes una organización asignada" },
        { status: 400 },
      );
    }

    const body = await request.json();
    const { newTier, immediate = false } = body;

    if (!newTier || !["basic", "pro", "premium"].includes(newTier)) {
      return NextResponse.json(
        { error: "Tier inválido. Debe ser: basic, pro, o premium" },
        { status: 400 },
      );
    }

    // Get current organization and subscription status
    const { data: org } = await supabase
      .from("organizations")
      .select("id, subscription_tier")
      .eq("id", organizationId)
      .single();

    if (!org) {
      return NextResponse.json(
        { error: "Organización no encontrada" },
        { status: 404 },
      );
    }

    const currentTier = (org.subscription_tier || "basic") as SubscriptionTier;
    const targetTier = newTier as SubscriptionTier;

    if (currentTier === targetTier) {
      return NextResponse.json(
        { error: "Ya estás en ese plan" },
        { status: 400 },
      );
    }

    const subscriptionStatus = await getSubscriptionStatus(organizationId);
    const isUpgrade = canUpgrade(currentTier, targetTier);

    // For upgrades: immediate change (user pays difference)
    // For downgrades: schedule change at end of current period (unless immediate=true)
    const shouldChangeImmediately = immediate || isUpgrade;

    if (shouldChangeImmediately) {
      // Immediate change: update organization tier now
      const { error: updateError } = await supabase
        .from("organizations")
        .update({
          subscription_tier: targetTier,
          updated_at: new Date().toISOString(),
        })
        .eq("id", organizationId);

      if (updateError) {
        logger.error("Error updating organization tier", updateError);
        return NextResponse.json(
          { error: "Error al actualizar el plan" },
          { status: 500 },
        );
      }

      await recordTierChange({
        organizationId,
        fromTier: currentTier,
        toTier: targetTier,
        changedByUserId: user.id,
        source: "org_user",
      });

      logger.info("Plan changed immediately", {
        organizationId,
        fromTier: currentTier,
        toTier: targetTier,
        isUpgrade,
      });

      return NextResponse.json({
        success: true,
        message: `Plan actualizado a ${targetTier}. ${
          isUpgrade
            ? "El cambio es efectivo inmediatamente."
            : "El cambio es efectivo ahora."
        }`,
        newTier: targetTier,
        effectiveDate: new Date().toISOString(),
      });
    } else {
      // Scheduled downgrade: store in scheduled_tier, apply at end of period
      const effectiveAt =
        subscriptionStatus.currentPeriodEnd ||
        subscriptionStatus.trialEndsAt ||
        new Date(Date.now() + 30 * 24 * 60 * 60 * 1000); // fallback: 30 days

      const { error: updateError } = await supabase
        .from("organizations")
        .update({
          scheduled_tier: targetTier,
          scheduled_tier_effective_at: effectiveAt.toISOString(),
          updated_at: new Date().toISOString(),
        })
        .eq("id", organizationId);

      if (updateError) {
        logger.error("Error scheduling tier change", updateError);
        return NextResponse.json(
          { error: "Error al programar el cambio de plan" },
          { status: 500 },
        );
      }

      logger.info("Plan change scheduled", {
        organizationId,
        fromTier: currentTier,
        toTier: targetTier,
        effectiveDate: effectiveAt,
      });

      return NextResponse.json({
        success: true,
        message: `Plan programado para cambiar a ${targetTier} al final del período actual (${effectiveAt.toLocaleDateString("es-CL")}).`,
        newTier: targetTier,
        effectiveDate: effectiveAt.toISOString(),
        scheduled: true,
      });
    }
  } catch (error) {
    logger.error("Error in change-plan API", error);
    return NextResponse.json(
      { error: "Error interno del servidor" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    logger.debug("Support Categories API GET called");
    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      logger.error("User authentication failed", userError);
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }
    logger.debug("User authenticated", { email: user.email });

    const { data: isAdmin, error: adminError } = (await supabase.rpc(
      "is_admin",
      { user_id: user.id } as IsAdminParams,
    )) as { data: IsAdminResult | null; error: Error | null };
    if (adminError) {
      logger.error("Admin check error", adminError);
      return NextResponse.json(
        { error: "Admin verification failed" },
        { status: 500 },
      );
    }
    if (!isAdmin) {
      logger.warn("User is not admin", { email: user.email });
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }
    logger.debug("Admin access confirmed", { email: user.email });

    // Get branch context
    const branchContext = await getBranchContext(request, user.id);

    // Get all support categories from database
    let query = supabase
      .from("support_categories")
      .select("*")
      .eq("is_active", true)
      .order("sort_order", { ascending: true });

    // Apply branch filter (include global categories - branch_id IS NULL)
    if (branchContext.branchId) {
      query = query.or(
        `branch_id.eq.${branchContext.branchId},branch_id.is.null`,
      );
    } else if (!branchContext.isSuperAdmin) {
      // Regular admin without branch - only global categories
      query = query.is("branch_id", null);
    }

    const { data: categories, error: fetchError } = await query;

    if (fetchError) {
