import { NextRequest, NextResponse } from "next/server";

import {
  getBranchContext,
  validateBranchAccess,
} from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

import { updateTicketHandler } from "./_handlers/updateTicket";

export const dynamic = "force-dynamic";
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { id: ticketId } = await params;

    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    // Get ticket with full details (without customer join to avoid null issues)
    const { data: ticket, error: ticketError } = await supabase
      .from("support_tickets")
      .select(
        `
        *,
        category:support_categories(
          id,
          name,
          description
        ),
        assigned_admin:admin_users!assigned_to(
          id,
          email
        ),
        resolved_admin:admin_users!resolved_by(
          id,
          email
        ),
        order:orders!order_id(
          id,
          order_number,
          total_amount,
          status,
          created_at
        )
      `,
      )
      .eq("id", ticketId)
      .single();

    if (ticketError || !ticket) {
      logger.error("Error fetching ticket", ticketError);
      return NextResponse.json(
        {
          error: "Ticket not found",
          details: ticketError?.message,
        },
        { status: 404 },
      );
    }

    // Validate branch access
    const branchContext = await getBranchContext(request, user.id);
    const hasAccess = await validateBranchAccess(user.id, ticket.branch_id);

    if (!hasAccess) {
      return NextResponse.json(
        {
          error: "No tiene acceso a este ticket de soporte",
        },
        { status: 403 },
      );
    }

    // Fetch customer separately if customer_id exists (use customers table)
    let customerProfile = null;
    if (ticket.customer_id && ticket.branch_id) {
      const { data: customer } = await supabase
        .from("customers")
        .select("id, first_name, last_name, email, phone")
        .eq("id", ticket.customer_id)
        .eq("branch_id", ticket.branch_id)
        .maybeSingle();

      customerProfile = customer;
    }

    // Attach customer data
    ticket.customer = customerProfile;

    // Get ticket messages
    const { data: messages, error: messagesError } = await supabase
      .from("support_messages")
      .select("*")
      .eq("ticket_id", ticketId)
      .order("created_at", { ascending: true });

    if (messagesError) {
      logger.warn("Error fetching ticket messages", messagesError);
    }

    // Calculate ticket analytics
    const createdAt = new Date(ticket.created_at);
    const now = new Date();
    const ageHours = Math.floor(
      (now.getTime() - createdAt.getTime()) / (1000 * 60 * 60),
    );

    const customerMessages =
      messages?.filter((msg) => msg.is_from_customer) || [];
    const adminMessages =
      messages?.filter((msg) => !msg.is_from_customer && !msg.is_internal) ||
      [];
    const internalNotes = messages?.filter((msg) => msg.is_internal) || [];

    const needsResponse = customerMessages.length > adminMessages.length;
    const lastCustomerMessage = customerMessages[customerMessages.length - 1];
    const lastAdminMessage = adminMessages[adminMessages.length - 1];

    let responseTime = null;
    if (ticket.first_response_at) {
      const firstResponseTime =
        new Date(ticket.first_response_at).getTime() - createdAt.getTime();
      responseTime = Math.floor(firstResponseTime / (1000 * 60 * 60)); // hours
    }

    const ticketWithAnalytics = {
      ...ticket,
      messages: messages || [],
      analytics: {
        ageHours,
        responseTimeHours: responseTime,
        messageCount: messages?.length || 0,
        customerMessageCount: customerMessages.length,
        adminMessageCount: adminMessages.length,
        internalNoteCount: internalNotes.length,
        needsResponse,
        lastCustomerMessageAt: lastCustomerMessage?.created_at,
        lastAdminMessageAt: lastAdminMessage?.created_at,
      },
    };

    return NextResponse.json({ ticket: ticketWithAnalytics });
  } catch (error) {
    logger.error("Error in ticket detail API", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id: ticketId } = await params;
  return updateTicketHandler(request, ticketId);
}

export async function DELETE(
  request: NextRequest,
  { params }: { params: { id: string } },
) {
  try {
    const ticketId = params.id;

    const supabase = await createClient();

    // Check admin authorization (only super admin can delete tickets)
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: adminRole } = await supabase.rpc("get_admin_role", {
      user_id: user.id,
    });
    if (adminRole !== "admin") {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    // Delete the ticket (messages will be cascade deleted)
    const { error: deleteError } = await supabase
      .from("support_tickets")
      .delete()
      .eq("id", ticketId);

    if (deleteError) {
      logger.error("Error deleting support ticket", deleteError);
      return NextResponse.json(
        { error: "Failed to delete support ticket" },
        { status: 500 },
      );
    }

    // Log admin activity
    await supabase.rpc("log_admin_activity", {
      action: "delete_support_ticket",
      resource_type: "support_ticket",
      resource_id: ticketId,
      details: { deleted_by: user.email },
    });

    return NextResponse.json({ success: true });
  } catch (error) {
    logger.error("Error in ticket delete API", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import { createClient } from "@/utils/supabase/server";

export async function createTicketHandler(request: NextRequest) {
  logger.info("Support Tickets API POST called (create ticket)");
  const supabase = await createClient();

  const {
    data: { user },
    error: userError,
  } = await supabase.auth.getUser();
  if (userError || !user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const { data: isAdmin } = await supabase.rpc("is_admin", {
    user_id: user.id,
  });
  if (!isAdmin) {
    return NextResponse.json(
      { error: "Admin access required" },
      { status: 403 },
    );
  }

  const branchContext = await getBranchContext(request, user.id);

  if (!branchContext.isSuperAdmin && !branchContext.branchId) {
    return NextResponse.json(
      {
        error: "Debe seleccionar una sucursal para crear tickets de soporte",
      },
      { status: 400 },
    );
  }

  const body = await request.json();
  const {
    title,
    description,
    priority = "medium",
    category_id,
    customer_email,
    customer_name,
    order_id,
    assigned_to,
    created_by_admin,
  } = body;

  logger.info("Creating new ticket", { customer_email, title, priority });

  if (!title || !description || !customer_email) {
    return NextResponse.json(
      {
        error: "Missing required fields: title, description, customer_email",
      },
      { status: 400 },
    );
  }

  const { data: latestTicket } = await supabase
    .from("support_tickets")
    .select("ticket_number")
    .order("created_at", { ascending: false })
    .limit(1)
    .single();

  let ticketNumber = "SUP-001";
  if (latestTicket?.ticket_number) {
    const match = latestTicket.ticket_number.match(/SUP-(\d+)/);
    if (match) {
      const nextNumber = parseInt(match[1]) + 1;
      ticketNumber = `SUP-${nextNumber.toString().padStart(3, "0")}`;
    }
  }

  let customer_id = null;
  if (branchContext.branchId) {
    const { data: customer } = await supabase
      .from("customers")
      .select("id")
      .eq("email", customer_email)
      .eq("branch_id", branchContext.branchId)
      .maybeSingle();

    if (customer) {
      customer_id = customer.id;
    }
  }

  const ticketData = {
    ticket_number: ticketNumber,
    subject: title,
    description,
    priority,
    status: "open",
    branch_id: branchContext.branchId,
    customer_id,
    customer_email,
    customer_name: customer_name || null,
    category_id: category_id || null,
    order_id: order_id || null,
    assigned_to: assigned_to || null,
    assigned_at: assigned_to ? new Date().toISOString() : null,
  };

  logger.debug("Attempting to insert ticket with data", { ticketData });

  const { data: newTicket, error: createError } = await supabase
    .from("support_tickets")
    .insert(ticketData)
    .select(
      `
        *,
        category:support_categories(id, name),
        assigned_admin:admin_users!assigned_to(id, email),
        order:orders!order_id(id, order_number)
      `,
    )
    .single();

  if (createError) {
    logger.error("Error creating ticket", createError, {
      errorDetails: JSON.stringify(createError, null, 2),
      ticketData: JSON.stringify(ticketData, null, 2),
    });
    return NextResponse.json(
      {
        error: "Failed to create ticket",
        details: createError.message,
        code: createError.code,
        hint: createError.hint,
      },
      { status: 500 },
    );
  }

  logger.info("Ticket created successfully", {
    ticketNumber: newTicket.ticket_number,
  });

  try {
    await supabase.from("support_messages").insert({
      ticket_id: newTicket.id,
      message: `Ticket created by admin${created_by_admin ? " on behalf of customer" : ""}`,
      is_internal: true,
      is_from_customer: false,
      sender_id: user.id,
      message_type: "note",
    });
    logger.debug("System message created");
  } catch (msgError) {
    logger.warn("Failed to create system message", msgError);
  }

  try {
    await supabase.rpc("log_admin_activity", {
      action: "create_support_ticket",
      resource_type: "support_ticket",
      resource_id: newTicket.id,
      details: {
        ticket_number: newTicket.ticket_number,
        customer_email,
        priority,
      },
    });
  } catch (logError) {
    logger.warn("Failed to log admin activity", logError);
  }

  try {
    if (process.env.RESEND_API_KEY) {
      const { sendTicketCreatedEmail } = await import(
        "@/lib/email/templates/support"
      );
      await sendTicketCreatedEmail({
        id: newTicket.id,
        ticket_number: newTicket.ticket_number,
        subject: title,
        description,
        status: newTicket.status,
        priority: newTicket.priority,
        customer_name: customer_name,
        customer_email: customer_email,
      });
      logger.info("Ticket creation email sent successfully");
    } else {
      logger.debug("Resend not configured, skipping email notification");
    }
  } catch (emailError) {
    logger.warn("Failed to send ticket creation email", emailError);
  }

  try {
    const priorityMap = {
      low: "low" as const,
      medium: "medium" as const,
      high: "high" as const,
      urgent: "urgent" as const,
    };

    await supabase.from("admin_notifications").insert({
      type: "support_ticket_new",
      priority: priorityMap[priority as keyof typeof priorityMap] || "medium",
      title: "Nuevo Ticket de Soporte",
      message: `${customer_name || customer_email} ha creado un nuevo ticket: ${title}`,
      related_entity_type: "ticket",
      related_entity_id: newTicket.id,
      action_url: `/admin/support/tickets/${newTicket.id}`,
      action_label: "Ver Ticket",
      metadata: {
        ticket_number: newTicket.ticket_number,
        customer_email: customer_email,
        customer_name: customer_name,
        priority: priority,
        category_id: category_id,
      },
      target_admin_id: assigned_to || null,
      is_read: false,
    });
    logger.debug("Admin notification created for new ticket");
  } catch (notificationError) {
    logger.warn("Failed to create admin notification", notificationError);
  }

  return NextResponse.json({
    ticket: newTicket,
    success: true,
  });
}

import { NextRequest, NextResponse } from "next/server";

import { addBranchFilter, getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

import { createTicketHandler } from "./_handlers/createTicket";

export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    logger.info("Support Tickets API GET called");
    const { searchParams } = new URL(request.url);
    const status = searchParams.get("status") || "";
    const priority = searchParams.get("priority") || "";
    const assigned_to = searchParams.get("assigned_to") || "";
    const category_id = searchParams.get("category_id") || "";
    const search = searchParams.get("search") || "";
    const page = parseInt(searchParams.get("page") || "1");
    const limit = parseInt(searchParams.get("limit") || "20");
    const offset = (page - 1) * limit;

    logger.debug("Query params", {
      status,
      priority,
      assigned_to,
      category_id,
      search,
      page,
      limit,
    });

    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      logger.error("User authentication failed", userError);
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }
    logger.debug("User authenticated", { email: user.email });

    const { data: isAdmin, error: adminError } = (await supabase.rpc(
      "is_admin",
      { user_id: user.id } as IsAdminParams,
    )) as { data: IsAdminResult | null; error: Error | null };
    if (adminError) {
      logger.error("Admin check error", adminError);
      return NextResponse.json(
        { error: "Admin verification failed" },
        { status: 500 },
      );
    }
    if (!isAdmin) {
      logger.warn("User is not admin", { email: user.email });
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }
    logger.debug("Admin access confirmed", { email: user.email });

    // Get branch context
    const branchContext = await getBranchContext(request, user.id);

    // Build the base query
    let query = supabase.from("support_tickets").select(
      `
        *,
        category:support_categories(
          id,
          name
        ),
        assigned_admin:admin_users!assigned_to(
          id,
          email
        ),
        order:orders!order_id(
          id,
          order_number
        )
      `,
      { count: "exact" },
    );

    // Apply branch filter
    query = addBranchFilter(
      query,
      branchContext.branchId,
      branchContext.isSuperAdmin,
      branchContext.organizationId,
    );

    // Apply filters
    if (status && status !== "all") {
      query = query.eq("status", status);
    }

    if (priority && priority !== "all") {
      query = query.eq("priority", priority);
    }

    if (assigned_to && assigned_to !== "all") {
      if (assigned_to === "unassigned") {
        query = query.is("assigned_to", null);
      } else if (assigned_to === "assigned") {
        query = query.not("assigned_to", "is", null);
      }
    }

    if (category_id && category_id !== "all") {
      query = query.eq("category_id", category_id);
    }

    // Apply ordering (newest first)
    query = query.order("created_at", { ascending: false });

    // Apply pagination
    query = query.range(offset, offset + limit - 1);

    // Execute query
    const { data: tickets, error: ticketsError, count } = await query;

    if (ticketsError) {
      logger.error("Error fetching tickets", ticketsError);
      return NextResponse.json(
        { error: "Failed to fetch support tickets" },
        { status: 500 },
      );
    }

    logger.debug("Support tickets returned", {
      returned: tickets?.length || 0,
      total: count || 0,
    });

    // For each ticket, fetch customer profile and message stats
    const ticketsWithStats = await Promise.all(
      (tickets || []).map(async (ticket) => {
        // Get customer if customer_id exists (try customers table first, then profiles as fallback)
        let customerProfile = null;
        if (ticket.customer_id && ticket.branch_id) {
          // Try customers table first (new structure)
          const { data: customer } = await supabase
            .from("customers")
            .select("id, first_name, last_name, email")
            .eq("id", ticket.customer_id)
            .eq("branch_id", ticket.branch_id)
            .maybeSingle();

          if (customer) {
            customerProfile = customer;
          } else {
            // Fallback to profiles for legacy tickets
            const { data: profile } = await supabase
              .from("profiles")
              .select("id, first_name, last_name, email")
              .eq("id", ticket.customer_id)
              .maybeSingle();
            customerProfile = profile;
          }
        } else if (ticket.customer_id) {
          // Legacy tickets without branch_id - use profiles
          const { data: profile } = await supabase
            .from("profiles")
            .select("id, first_name, last_name, email")
            .eq("id", ticket.customer_id)
            .maybeSingle();
          customerProfile = profile;
        }

        // Get messages for this ticket
        const { data: messages } = await supabase
          .from("support_messages")
          .select("id, is_from_customer, is_internal, created_at")
          .eq("ticket_id", ticket.id)
          .order("created_at", { ascending: false });

        const customerMessages =
          messages?.filter((msg) => msg.is_from_customer) || [];
        const adminMessages =
          messages?.filter(
            (msg) => !msg.is_from_customer && !msg.is_internal,
          ) || [];
        const allMessages = messages || [];

        // Calculate age in hours
        const createdAt = new Date(ticket.created_at);
        const now = new Date();
        const ageHours = Math.floor(
          (now.getTime() - createdAt.getTime()) / (1000 * 60 * 60),
        );

        // Determine if needs response (customer has sent more messages than admin)
        const needsResponse = customerMessages.length > adminMessages.length;

        // Get last message timestamp for "last activity"
        const lastMessage = allMessages[0]; // First one since we ordered desc
        const lastResponseAt = lastMessage
          ? lastMessage.created_at
          : ticket.updated_at;

        return {
          ...ticket,
          // Add customer data
          customer: customerProfile,
          customer_name: customerProfile
            ? `${customerProfile.first_name || ""} ${customerProfile.last_name || ""}`.trim()
            : ticket.customer_name || "",
          // Use email from profile if available, otherwise from ticket
          customer_email: customerProfile?.email || ticket.customer_email || "",
          last_response_at: lastResponseAt,
          stats: {
            messageCount: allMessages.length,
            customerMessageCount: customerMessages.length,
            adminMessageCount: adminMessages.length,
            ageHours,
            needsResponse,
          },
        };
      }),
    );

    return NextResponse.json({
      tickets: ticketsWithStats,
      pagination: {
        page,
        limit,
        total: count || 0,
        totalPages: Math.ceil((count || 0) / limit),
      },
    });
  } catch (error) {
    logger.error("Error in support tickets API GET", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

export async function POST(request: NextRequest) {
  return createTicketHandler(request);
}

import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import { createClient,createServiceRoleClient  } from "@/utils/supabase/server";


/**
 * GET /api/admin/system/backups
 * List all available backups from Supabase Storage for the user's organization.
 * @requires admin | super_admin | root | dev
 * @requires organization_id (usuarios sin org reciben 400)
 */
export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const filename = searchParams.get("filename");
    const action = searchParams.get("action");

    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: adminRole } = await supabase.rpc("get_admin_role", {
      user_id: user.id,
    });
    if (
      !["admin", "super_admin", "root", "dev"].includes(adminRole as string)
    ) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    // Get user's organization_id
    const { data: adminUser } = await supabase
      .from("admin_users")
      .select("organization_id")
      .eq("id", user.id)
      .single();

    const userOrganizationId = adminUser?.organization_id;

    if (!userOrganizationId) {
      return NextResponse.json(
        { error: "Organization not found" },
        { status: 400 },
      );
    }

    const supabaseService = createServiceRoleClient();

    // If filename and action=details, return backup details
    if (filename && action === "details") {
      // Security: Ensure requested filename belongs to the user or starts with their org ID
      // Backups are now stored as org-id/backup-id.json
      if (!filename.startsWith(userOrganizationId)) {
        return NextResponse.json(
          { error: "Access denied to this backup" },
          { status: 403 },
        );
      }

      const { data: backupFile, error: downloadError } =
        await supabaseService.storage
          .from("database-backups")
          .download(filename);

      if (downloadError || !backupFile) {
        return NextResponse.json(
          {
            error: "Error al descargar backup",
            details: downloadError?.message,
          },
          { status: 500 },
        );
      }

      const backupText = await backupFile.text();
      let backupData: unknown;
      try {
        backupData = JSON.parse(backupText);
      } catch (parseError) {
        return NextResponse.json(
          {
            error: "Error al parsear archivo de backup",
            details: "El archivo no es un JSON válido",
          },
          { status: 400 },
        );
      }

      // Check organization_id inside JSON for extra safety
      if (backupData.organization_id !== userOrganizationId) {
        return NextResponse.json(
          { error: "Data isolation breach detected" },
          { status: 403 },
        );
      }

      // Get file metadata
      const { data: fileInfo } = await supabaseService.storage
        .from("database-backups")
        .list(userOrganizationId, {
          search: filename.split("/").pop(),
        });

      const file = fileInfo?.[0];
      const fileSize = file?.metadata?.size || file?.metadata?.size_bytes || 0;

      const { data: signedUrlData } = await supabaseService.storage
        .from("database-backups")
        .createSignedUrl(filename, 3600);

      const totalRecords = backupData.tables
        ? Object.values(backupData.tables).reduce(
            (sum: number, table: unknown) => {
              return sum + (table.record_count || 0);
            },
            0,
          )
        : 0;

      return NextResponse.json({
        success: true,
        backup_id: backupData.backup_id,
        backup_file: filename,
        download_url: signedUrlData?.signedUrl || null,
        tables_count: Object.keys(backupData.tables).length,
        total_records: totalRecords,
        backup_size_mb: (fileSize / 1024 / 1024).toFixed(2),
        created_at: backupData.created_at,
        created_by: backupData.created_by,
      });
    }

    // List files in the organization's folder
    const { data: files, error: listError } = await supabaseService.storage
      .from("database-backups")
      .list(userOrganizationId, {
        limit: 100,
        offset: 0,
        sortBy: { column: "created_at", order: "desc" },
      });

    if (listError) {
      logger.error("Error listing backups:", { error: listError });
      return NextResponse.json(
        { error: "Error al listar backups" },
        { status: 500 },
      );
    }

    const backups = (files || []).map((file) => ({
      id: file.name.replace(".json", ""),
      filename: `${userOrganizationId}/${file.name}`,
      size: file.metadata?.size || file.metadata?.size_bytes || 0,
      size_mb: (
        (file.metadata?.size || file.metadata?.size_bytes || 0) /
        1024 /
        1024
      ).toFixed(2),
      created_at: file.created_at,
    }));

    return NextResponse.json({
      success: true,
      backups: backups,
      count: backups.length,
    });
  } catch (error) {
    logger.error("Error in backups GET API:", { error });
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

/**
 * POST /api/admin/system/backups
 * Restore a specific backup for the user's organization.
 * @requires admin | super_admin | root | dev
 * @requires organization_id
 */
export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { backup_filename } = body;

    if (!backup_filename) {
      return NextResponse.json(
        { error: "backup_filename es requerido" },
        { status: 400 },
      );
    }

    const supabase = await createClient();

    // Authorization
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user)
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

    const { data: adminRole } = await supabase.rpc("get_admin_role", {
      user_id: user.id,
    });
    if (
      !["admin", "super_admin", "root", "dev"].includes(adminRole as string)
    ) {
      return NextResponse.json({ error: "Forbidden" }, { status: 403 });
    }

    const { data: adminUser } = await supabase
      .from("admin_users")
      .select("organization_id")
      .eq("id", user.id)
      .single();

    const userOrganizationId = adminUser?.organization_id;
    if (!userOrganizationId)
      return NextResponse.json({ error: "Org not found" }, { status: 400 });

    // Security: Ensure the file path belongs to the organization
    if (!backup_filename.startsWith(userOrganizationId)) {
      return NextResponse.json(
        { error: "Access denied to this backup file" },
        { status: 403 },
      );
    }

    logger.info("Starting backup restoration", {
      backup_filename,
      organizationId: userOrganizationId,
    });

    const supabaseService = createServiceRoleClient();

    const { data: backupFile, error: downloadError } =
      await supabaseService.storage
        .from("database-backups")
        .download(backup_filename);

    if (downloadError || !backupFile) {
      return NextResponse.json(
        { error: "Error downloading backup" },
        { status: 500 },
      );
    }

    const backupText = await backupFile.text();
    const backupData = JSON.parse(backupText);

    // Call Restore service
    const { BackupService } = await import("@/lib/backup-service");
    const result = await BackupService.restoreBackup(
      userOrganizationId,
      backupData,
    );

    // Log the restoration activity
    await supabase.rpc("log_admin_activity", {
      action: "maintenance_restore_database",
      resource_type: "system",
      resource_id: null,
      details: {
        action: "restore_database",
        file: backup_filename,
        organization_id: userOrganizationId,
        success: result.success,
        stats: result.total_records_restored,
      },
    });

    return NextResponse.json(result);
  } catch (error) {
    logger.error("Error in restore backup API:", { error });
    return NextResponse.json(
      { error: "Error al restaurar backup" },
      { status: 500 },
    );
  }
}

/**
 * DELETE /api/admin/system/backups
 * Delete a specific backup file. Solo backups de la org del usuario.
