      .single();

    const userOrganizationId = adminUser?.organization_id;
    if (!userOrganizationId)
      return NextResponse.json({ error: "Org not found" }, { status: 400 });

    // Security
    if (!filename.startsWith(userOrganizationId)) {
      return NextResponse.json({ error: "Forbidden" }, { status: 403 });
    }

    const supabaseService = createServiceRoleClient();
    const { error: deleteError } = await supabaseService.storage
      .from("database-backups")
      .remove([filename]);

    if (deleteError) throw deleteError;

    await supabase.rpc("log_admin_activity", {
      action: "maintenance_delete_backup",
      resource_type: "system",
      resource_id: null,
      details: {
        action: "delete_backup",
        file: filename,
        organization_id: userOrganizationId,
      },
    });

    return NextResponse.json({
      success: true,
      message: "Backup eliminado exitosamente",
    });
  } catch (error) {
    logger.error("Error in delete backup API:", { error });
    return NextResponse.json(
      { error: "Error al eliminar backup" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { createClient } from "@/utils/supabase/server";

export async function handleUpdateTemplate(request: NextRequest, params: { id: string }) {
  const body = await request.json();
  const { name, subject, content, is_active, variables } = body;

  const supabase = await createClient();
  const { data: { user }, error: userError } = await supabase.auth.getUser();
  if (userError || !user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const { data: adminUser } = await supabase.from("admin_users").select("organization_id, role").eq("id", user.id).single();
  if (!adminUser) return NextResponse.json({ error: "Unauthorized" }, { status: 403 });

  const { data: existingTemplate } = await supabase
    .from("system_email_templates").select("organization_id, is_system, type, name, subject, content, variables")
    .eq("id", params.id).single();
  if (!existingTemplate) return NextResponse.json({ error: "Template not found" }, { status: 404 });

  const isOnlyToggleActive = Object.keys(body).filter((k) => k !== "is_active").length === 0 && is_active !== undefined;

  let isGlobalAdmin = ["super_admin", "root", "dev"].includes(adminUser.role);
  if (!isGlobalAdmin) {
    const { data: isSuperAdminRpc } = await supabase.rpc("is_super_admin", { user_id: user.id });
    isGlobalAdmin = !!isSuperAdminRpc;
  }

  const canUpdate = isGlobalAdmin || existingTemplate.organization_id === adminUser.organization_id
    || (existingTemplate.organization_id === null && !existingTemplate.is_system)
    || (existingTemplate.organization_id === null && existingTemplate.is_system && adminUser.organization_id && isOnlyToggleActive);
  if (!canUpdate) return NextResponse.json({ error: "Forbidden" }, { status: 403 });

  // Org admin toggling is_active on system template: create/delete org override
  if (!isGlobalAdmin && existingTemplate.is_system && adminUser.organization_id && is_active !== undefined) {
    const orgId = adminUser.organization_id;
    const { data: orgOverride } = await supabase
      .from("system_email_templates").select("id").eq("type", existingTemplate.type)
      .eq("organization_id", orgId).is("is_system", false).maybeSingle();

    if (is_active === false) {
      if (!orgOverride) {
        const { data: created, error: insertErr } = await supabase.from("system_email_templates").insert({
          name: existingTemplate.name, type: existingTemplate.type, subject: existingTemplate.subject,
          content: existingTemplate.content, variables: existingTemplate.variables ?? [],
          is_active: false, is_system: false, organization_id: orgId,
        }).select().single();
        if (!insertErr && created) return NextResponse.json({ success: true, template: { ...created, _is_override: true } });
      } else {
        const { data: updated, error: updErr } = await supabase.from("system_email_templates")
          .update({ is_active: false, updated_at: new Date().toISOString() }).eq("id", orgOverride.id).select().single();
        if (!updErr && updated) return NextResponse.json({ success: true, template: { ...updated, _is_override: true } });
      }
    } else {
      if (orgOverride) {
        await supabase.from("system_email_templates").delete().eq("id", orgOverride.id);
        return NextResponse.json({ success: true, template: { ...existingTemplate, is_active: true } });
      }
    }
  }

  if (!isGlobalAdmin && existingTemplate.is_system) {
    return NextResponse.json({ error: "Cannot modify system templates. Create a custom one instead." }, { status: 403 });
  }

  const updateData: Record<string, unknown> = { updated_at: new Date().toISOString() };
  if (name !== undefined) updateData.name = name;
  if (subject !== undefined) updateData.subject = subject;
  if (content !== undefined) updateData.content = content;
  if (is_active !== undefined) updateData.is_active = is_active;
  if (variables !== undefined) updateData.variables = Array.isArray(variables) ? variables : JSON.parse(variables || "[]");

  const { data: template, error } = await supabase.from("system_email_templates").update(updateData)
    .eq("id", params.id).select().maybeSingle();
  if (error) return NextResponse.json({ error: "Failed to update email template", details: error.message }, { status: 500 });
  if (!template) return NextResponse.json({ error: "Template not found or update had no effect" }, { status: 404 });

  return NextResponse.json({ success: true, template });
}

import { NextRequest, NextResponse } from "next/server";

import { sendEmail } from "@/lib/email/client";
import { wrapInModernLayout } from "@/lib/email/layout";
import { replaceTemplateVariables } from "@/lib/email/template-utils";
import { appLogger as logger } from "@/lib/logger";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";

const DEFAULT_VARIABLES: Record<string, string> = {
  customer_name: "Cliente de Prueba",
  order_number: "ORD-12345",
  order_total: "$1,000.00",
  order_date: new Date().toLocaleDateString("es-AR"),
  company_name: "Nuestra Óptica",
  organization_name: "Nuestra Óptica",
  support_email: "soporte@opttius.cl",
  ...Object.fromEntries(
    [
      "order_items",
      "order_items_text",
      "appointment_date",
      "appointment_time",
      "professional_name",
      "branch_name",
      "quote_number",
      "quote_total",
      "work_order_number",
      "low_stock_products",
      "low_stock_products_text",
      "product_count",
    ].map((k) => [k, "(ejemplo)"]),
  ),
};

export async function POST(
  request: NextRequest,
  { params }: { params: { id: string } },
) {
  try {
    const { id } = params;
    const body = await request.json();
    const { testEmail, variables = {} } = body;

    if (!testEmail) {
      return NextResponse.json(
        { error: "Test email address is required" },
        { status: 400 },
      );
    }

    const supabase = await createClient();

    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: adminUser } = await supabase
      .from("admin_users")
      .select("organization_id, role")
      .eq("id", user.id)
      .single();

    if (!adminUser) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 403 });
    }

    const { data: template, error: templateError } = await supabase
      .from("system_email_templates")
      .select("*")
      .eq("id", id)
      .single();

    if (templateError || !template) {
      return NextResponse.json(
        { error: "Template not found" },
        { status: 404 },
      );
    }

    const allVariables = { ...DEFAULT_VARIABLES, ...variables };
    const subject = replaceTemplateVariables(
      template.subject || "",
      allVariables,
    );
    let content = replaceTemplateVariables(
      template.content || "",
      allVariables,
    );

    let organizationName = "Nuestra Óptica";
    let organizationColor = "#1A2B23";

    if (template.organization_id) {
      const { data: org } = await supabase
        .from("organizations")
        .select("name, metadata")
        .eq("id", template.organization_id)
        .single();
      if (org) {
        organizationName = org.name || organizationName;
        organizationColor =
          (org.metadata as { primary_color?: string })?.primary_color ||
          organizationColor;
      }
    }

    content = wrapInModernLayout(content, {
      organizationName,
      organizationColor,
      previewText: subject,
    });

    const text = content
      .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, "")
      .replace(/<[^>]+>/g, "")
      .replace(/\n\s*\n/g, "\n")
      .trim();

    const result = await sendEmail({
      to: testEmail,
      subject: `[TEST] ${subject}`,
      html: content,
      text,
    });

    if (!result.success) {
      logger.error("Error sending test email", { error: result.error });
      return NextResponse.json(
        {
          success: false,
          error: result.error || "Error al enviar el email de prueba",
        },
        { status: 500 },
      );
    }

    return NextResponse.json({
      success: true,
      message: `Email de prueba enviado a ${testEmail}`,
    });
  } catch (error) {
    logger.error("Error in test email template API", { error });
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const type = searchParams.get("type") || "";
    const active_only = searchParams.get("active_only") === "true";
    const category = searchParams.get("category") || "organization";

    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: adminUser } = await supabase
      .from("admin_users")
      .select("organization_id, role")
      .eq("id", user.id)
      .single();

    if (!adminUser) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    const isGlobalAdmin =
      adminUser.role === "root" ||
      adminUser.role === "dev" ||
      adminUser.role === "super_admin";

    // Auth already verified — RLS scopes access
    const dbClient = supabase;

    // Build the query for system email templates
    let query = dbClient.from("system_email_templates").select(`
        id,
        name,
        type,
        subject,
        content,
        variables,
        is_active,
        is_system,
        category,
        organization_id,
        usage_count,
        created_by,
        created_at,
        updated_at
      `);

    // Multi-tenant filtering:
    // 1. If global admin (root/dev/super_admin), they can see everything or filter by category
    // 2. If organization admin, they see: system templates (org_id is null AND category='organization')
    //    OR their own templates.
    if (isGlobalAdmin) {
      if (category && category !== "all") {
        query = query.eq("category", category);
      }
    } else {
      // Organization admin
      const orgId = adminUser.organization_id;
      if (orgId) {
        query = query.or(
          `organization_id.eq.${orgId},and(organization_id.is.null,category.eq.organization)`,
        );
      } else {
        query = query
          .is("organization_id", null)
          .eq("category", "organization");
      }
    }

    // Apply filters
    if (active_only) {
      query = query.eq("is_active", true);
    }

    if (type && type !== "all") {
      query = query.eq("type", type);
    }

    // Order by organization_id (to put custom/override first) then type
    const { data: rawTemplates, error } = await query
      .order("organization_id", { ascending: false, nullsFirst: false })
      .order("type", { ascending: true });

    if (error) {
      logger.error("Error fetching email templates", { error });
      return NextResponse.json(
        { error: "Failed to fetch email templates" },
        { status: 500 },
      );
    }

    // For org admins: deduplicate by type - org override takes precedence over system template
    let templates = rawTemplates || [];
    if (!isGlobalAdmin && adminUser.organization_id) {
      const byType = new Map<string, (typeof templates)[0]>();
      for (const t of templates) {
        if (!byType.has(t.type)) byType.set(t.type, t);
      }
      templates = Array.from(byType.values()).sort((a, b) =>
        (a.type || "").localeCompare(b.type || ""),
      );
    }

    return NextResponse.json({ templates });
  } catch (error) {
    logger.error("Error in email templates API", { error });
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

