import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import type {
  GetAdminRoleParams,
  GetAdminRoleResult,
} from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

/**
 * GET /api/admin/users/search
 * Search registered users by email or name (for admin user creation)
 */
export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    const searchParams = request.nextUrl.searchParams;
    const query = searchParams.get("q") || "";

    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: adminRole } = (await supabase.rpc("get_admin_role", {
      user_id: user.id,
    } as GetAdminRoleParams)) as {
      data: GetAdminRoleResult | null;
      error: Error | null;
    };
    if (adminRole !== "admin") {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    // Search in profiles table (which has user info and is linked to auth.users)
    let usersQuery = supabase
      .from("profiles")
      .select("id, email, first_name, last_name")
      .order("email", { ascending: true })
      .limit(10);

    // Add search filter if query is provided
    if (query.trim()) {
      usersQuery = usersQuery.or(
        `email.ilike.%${query}%,first_name.ilike.%${query}%,last_name.ilike.%${query}%`,
      );
    }

    const { data: users, error: usersError } = await usersQuery;

    if (usersError) {
      logger.error("Error searching users:", { error: usersError, query });
      return NextResponse.json(
        { error: "Failed to search users" },
        { status: 500 },
      );
    }

    // Check which users are already admins
    const { data: existingAdmins } = await supabase
      .from("admin_users")
      .select("id")
      .in(
        "id",
        (users || []).map((u) => u.id),
      );

    const adminIds = new Set(existingAdmins?.map((a) => a.id) || []);

    // Filter out users who are already admins and format response
    const availableUsers = (users || [])
      .filter((user) => !adminIds.has(user.id))
      .map((user) => ({
        id: user.id,
        email: user.email,
        fullName:
          [user.first_name, user.last_name].filter(Boolean).join(" ") ||
          user.email,
        firstName: user.first_name,
        lastName: user.last_name,
      }));

    return NextResponse.json({ users: availableUsers });
  } catch (error) {
    logger.error("Error in users search API:", { error });
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import { createClient } from "@/utils/supabase/server";

interface RouteParams {
  params: Promise<{ id: string }>;
}

// GET /api/admin/vehicles/[id] - Get specific vehicle
export const dynamic = "force-dynamic";
export async function GET(req: NextRequest, { params }: RouteParams) {
  try {
    const supabase = await createClient();
    const { id } = await params;

    // Get user
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user)
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

    // Get branch context
    const branchContext = await getBranchContext(req, user.id, supabase);
    if (!branchContext.branchId && !branchContext.isGlobalView) {
      return NextResponse.json({ error: "No branch access" }, { status: 403 });
    }

    const { data: vehicle, error } = await supabase
      .from("vehicles")
      .select("*")
      .eq("id", id)
      .eq("organization_id", branchContext.organizationId)
      .single();

    if (error) {
      if (error.code === "PGRST116") {
        return NextResponse.json(
          { error: "Vehicle not found" },
          { status: 404 },
        );
      }
      logger.error("Failed to fetch vehicle", { error: error.message });
      return NextResponse.json(
        { error: "Failed to fetch vehicle" },
        { status: 500 },
      );
    }

    return NextResponse.json(vehicle);
  } catch (error) {
    logger.error("Vehicle detail error", { error });
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

// PUT /api/admin/vehicles/[id] - Update vehicle
export async function PUT(req: NextRequest, { params }: RouteParams) {
  try {
    const supabase = await createClient();
    const { id } = await params;

    // Get user
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user)
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

    // Get branch context
    const branchContext = await getBranchContext(req, user.id, supabase);
    if (!branchContext.branchId && !branchContext.isGlobalView) {
      return NextResponse.json({ error: "No branch access" }, { status: 403 });
    }

    const body = await req.json();
    const { plate_number, model, capacity, is_active } = body;

    // Validation
    if (plate_number) {
      // Check if another vehicle has this plate number
      const { data: existingVehicle } = await supabase
        .from("vehicles")
        .select("id")
        .eq("plate_number", plate_number)
        .eq("organization_id", branchContext.organizationId)
        .neq("id", id)
        .maybeSingle();

      if (existingVehicle) {
        return NextResponse.json(
          { error: "Another vehicle with this plate number already exists" },
          { status: 400 },
        );
      }
    }

    // Prepare update data
    const updateData: unknown = {};

    if (plate_number !== undefined) updateData.plate_number = plate_number;
    if (model !== undefined) updateData.model = model;
    if (capacity !== undefined) updateData.capacity = capacity;
    if (is_active !== undefined) updateData.is_active = is_active;

    const { data: vehicle, error } = await supabase
      .from("vehicles")
      .update(updateData)
      .eq("id", id)
      .eq("organization_id", branchContext.organizationId)
      .select()
      .single();

    if (error) {
      logger.error("Failed to update vehicle", { error: error.message });
      return NextResponse.json(
        { error: "Failed to update vehicle" },
        { status: 500 },
      );
    }

    if (!vehicle) {
      return NextResponse.json({ error: "Vehicle not found" }, { status: 404 });
    }

    logger.info("Vehicle updated", {
