// DELETE /api/admin/vehicles/[id] - Delete vehicle
export async function DELETE(req: NextRequest, { params }: RouteParams) {
  try {
    const supabase = await createClient();
    const { id } = await params;

    // Get user
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user)
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

    // Get branch context
    const branchContext = await getBranchContext(req, user.id, supabase);
    if (!branchContext.branchId && !branchContext.isGlobalView) {
      return NextResponse.json({ error: "No branch access" }, { status: 403 });
    }

    // Check if vehicle is assigned to any active orders
    const { data: assignedOrders } = await supabase
      .from("internal_orders")
      .select("id")
      .eq("assigned_vehicle_id", id)
      .in("status", ["pending", "confirmed", "in_transit"])
      .maybeSingle();

    if (assignedOrders) {
      return NextResponse.json(
        { error: "Cannot delete vehicle assigned to active orders" },
        { status: 400 },
      );
    }

    const { error } = await supabase
      .from("vehicles")
      .delete()
      .eq("id", id)
      .eq("organization_id", branchContext.organizationId);

    if (error) {
      logger.error("Failed to delete vehicle", { error: error.message });
      return NextResponse.json(
        { error: "Failed to delete vehicle" },
        { status: 500 },
      );
    }

    logger.info("Vehicle deleted", {
      vehicleId: id,
      userId: user.id,
    });

    return NextResponse.json({ message: "Vehicle deleted successfully" });
  } catch (error) {
    logger.error("Vehicle deletion error", { error });
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import { createClient } from "@/utils/supabase/server";

// GET /api/admin/vehicles/available - Get available vehicles (not assigned to active orders)
export const dynamic = "force-dynamic";
export async function GET(req: NextRequest) {
  try {
    const supabase = await createClient();

    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user)
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

    // Get branch context
    const branchContext = await getBranchContext(req, user.id, supabase);
    if (!branchContext.branchId && !branchContext.isGlobalView) {
      return NextResponse.json({ error: "No branch access" }, { status: 403 });
    }

    // Get vehicles not assigned to active orders
    const { data: activeOrderVehicles, error: ordersError } = await supabase
      .from("internal_orders")
      .select("assigned_vehicle_id")
      .eq("organization_id", branchContext.organizationId)
      .in("status", ["pending", "confirmed", "in_transit"])
      .not("assigned_vehicle_id", "is", null);

    if (ordersError) {
      logger.error("Failed to fetch active orders", {
        error: ordersError.message,
      });
      return NextResponse.json(
        { error: "Failed to fetch data" },
        { status: 500 },
      );
    }

    const assignedVehicleIds =
      activeOrderVehicles?.map((o: unknown) => o.assigned_vehicle_id) || [];

    // Get available vehicles
    let query = supabase
      .from("vehicles")
      .select("*")
      .eq("organization_id", branchContext.organizationId)
      .eq("is_active", true);

    if (assignedVehicleIds.length > 0) {
      query = query.not("id", "in", `(${assignedVehicleIds.join(",")})`);
    }

    const { data: vehicles, error } = await query.order("plate_number");

    if (error) {
      logger.error("Failed to fetch available vehicles", {
        error: error.message,
      });
      return NextResponse.json(
        { error: "Failed to fetch available vehicles" },
        { status: 500 },
      );
    }

    return NextResponse.json(vehicles);
  } catch (error) {
    logger.error("Available vehicles error", { error });
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import { createClient } from "@/utils/supabase/server";

// GET /api/admin/vehicles - List vehicles
export const dynamic = "force-dynamic";
export async function GET(req: NextRequest) {
  try {
    const supabase = await createClient();
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user)
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

    // Get branch context
    const branchContext = await getBranchContext(req, user.id, supabase);
    if (!branchContext.branchId && !branchContext.isGlobalView) {
      return NextResponse.json({ error: "No branch access" }, { status: 403 });
    }

    const { searchParams } = new URL(req.url);
    const isActive = searchParams.get("is_active");
    const page = parseInt(searchParams.get("page") || "1");
    const limit = parseInt(searchParams.get("limit") || "20");

    const offset = (page - 1) * limit;

    // Build query
    let query = supabase
      .from("vehicles")
      .select("*", { count: "exact" })
      .eq("organization_id", branchContext.organizationId);

    // Apply filters
    if (isActive !== null) {
      query = query.eq("is_active", isActive === "true");
    }

    // Execute query with pagination
    const {
      data: vehicles,
      error,
      count,
    } = await query.order("plate_number").range(offset, offset + limit - 1);

    if (error) {
      logger.error("Failed to fetch vehicles", { error: error.message });
      return NextResponse.json(
        { error: "Failed to fetch vehicles" },
        { status: 500 },
      );
    }

    return NextResponse.json({
      vehicles,
      pagination: {
        page,
        limit,
        total: count,
        totalPages: Math.ceil(count! / limit),
      },
    });
  } catch (error) {
    logger.error("Vehicles list error", { error });
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

// POST /api/admin/vehicles - Create new vehicle
export async function POST(req: NextRequest) {
  try {
    const supabase = await createClient();

    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user)
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

    // Get branch context
    const branchContext = await getBranchContext(req, user.id, supabase);
    if (!branchContext.branchId && !branchContext.isGlobalView) {
      return NextResponse.json({ error: "No branch access" }, { status: 403 });
    }

    const body = await req.json();
    const { plate_number, model, capacity = 0, is_active = true } = body;

    // Validation
    if (!plate_number) {
      return NextResponse.json(
        { error: "Plate number is required" },
        { status: 400 },
      );
    }

    // Check if plate number already exists
    const { data: existingVehicle } = await supabase
      .from("vehicles")
      .select("id")
      .eq("plate_number", plate_number)
      .eq("organization_id", branchContext.organizationId)
      .maybeSingle();

    if (existingVehicle) {
      return NextResponse.json(
        { error: "Vehicle with this plate number already exists" },
        { status: 400 },
      );
    }

    // Create vehicle
    const { data: vehicle, error } = await supabase
      .from("vehicles")
      .insert({
        plate_number,
        model,
        capacity,
        is_active,
        organization_id: branchContext.organizationId,
