export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    const { id } = await params;

    // Get branch context
    const branchContext = await getBranchContext(request, user.id);

    // Check if request body contains allowDelivered flag (for admin deletion from detail page)
    let allowDelivered = false;
    try {
      const body = await request.json();
      allowDelivered = body.allowDelivered === true;
    } catch {
      // If no body or invalid JSON, continue with default behavior (allowDelivered = false)
    }

    // First, check if the work order exists and get quote_id if it exists
    const { data: workOrder, error: fetchError } = await supabase
      .from("lab_work_orders")
      .select("id, status, payment_status, quote_id, branch_id")
      .eq("id", id)
      .single();

    if (fetchError || !workOrder) {
      return NextResponse.json(
        { error: "Work order not found" },
        { status: 404 },
      );
    }

    // Validate branch access
    const hasAccess = await validateBranchAccess(user.id, workOrder.branch_id);
    if (!hasAccess) {
      return NextResponse.json(
        {
          error: "No tiene acceso a este trabajo",
        },
        { status: 403 },
      );
    }

    // Prevent deletion of delivered work orders unless allowDelivered is true (from detail page)
    if (workOrder.status === "delivered" && !allowDelivered) {
      return NextResponse.json(
        {
          error: "No se puede eliminar un trabajo que ya ha sido entregado",
        },
        { status: 400 },
      );
    }

    // Prevent deletion of work orders with payments unless allowDelivered is true (from detail page)
    if (
      (workOrder.payment_status === "paid" ||
        workOrder.payment_status === "partial") &&
      !allowDelivered
    ) {
      return NextResponse.json(
        {
          error: "No se puede eliminar un trabajo con pagos registrados",
        },
        { status: 400 },
      );
    }

    // Store quote_id before deletion
    const quoteId = workOrder.quote_id;

    // Delete the work order (this will cascade delete status history due to ON DELETE CASCADE)
    const { error: deleteError } = await supabase
      .from("lab_work_orders")
      .delete()
      .eq("id", id);

    if (deleteError) {
      logger.error("Error deleting work order", deleteError);
      return NextResponse.json(
        { error: "Failed to delete work order" },
        { status: 500 },
      );
    }

    // If the work order was converted from a quote, delete the quote as well
    if (quoteId) {
      const { error: quoteDeleteError } = await supabase
        .from("quotes")
        .delete()
        .eq("id", quoteId);

      if (quoteDeleteError) {
        logger.warn("Error deleting related quote", quoteDeleteError);
        // Don't fail the request if quote deletion fails, just log it
      }
    }

    return NextResponse.json({
      success: true,
      message: "Trabajo eliminado exitosamente",
    });
  } catch (error) {
    logger.error("Error deleting work order", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { validateBranchAccess } from "@/lib/api/branch-middleware";
import { sendWorkOrderReady } from "@/lib/email/notifications";
import { sendDeliveryCompletionEmail } from "@/lib/email/send-delivery-completion-email";
import { appLogger as logger } from "@/lib/logger";
import { NotificationService } from "@/lib/notifications/notification-service";
import { sendWorkOrderReadyWhatsApp } from "@/lib/whatsapp/notifications-b2b";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";
export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    const { id } = await params;
    const body = await request.json();
    const { status, notes, ...additionalData } = body;

    if (!status) {
      return NextResponse.json(
        { error: "Status is required" },
        { status: 400 },
      );
    }

    // Get old status and branch_id before update
    const { data: workOrderBeforeUpdate } = await supabase
      .from("lab_work_orders")
      .select("status, work_order_number, branch_id")
      .eq("id", id)
      .single();

    if (!workOrderBeforeUpdate) {
      return NextResponse.json(
        { error: "Work order not found" },
        { status: 404 },
      );
    }

    // Validate branch access
    const hasAccess = await validateBranchAccess(
      user.id,
      workOrderBeforeUpdate.branch_id,
    );
    if (!hasAccess) {
      return NextResponse.json(
        {
          error: "No tiene acceso a este trabajo",
        },
        { status: 403 },
      );
    }

    const oldStatus = workOrderBeforeUpdate.status || "quote";
    const workOrderNumber = workOrderBeforeUpdate.work_order_number || "";

    // Update work order status using the function
    const { error: statusError } = await supabase.rpc(
      "update_work_order_status",
      {
        p_work_order_id: id,
        p_new_status: status,
        p_changed_by: user.id,
        p_notes: notes || null,
      },
    );

    if (statusError) {
      logger.error("Error updating work order status", statusError);
      return NextResponse.json(
        {
          error: "Failed to update status",
          details: statusError.message,
        },
        { status: 500 },
      );
    }

    // Update additional fields if provided
    if (Object.keys(additionalData).length > 0) {
      const updateData: unknown = {
        updated_at: new Date().toISOString(),
      };

      // Add lab-specific fields
      if (additionalData.lab_name)
        updateData.lab_name = additionalData.lab_name;
      if (additionalData.lab_contact)
        updateData.lab_contact = additionalData.lab_contact;
      if (additionalData.lab_order_number)
        updateData.lab_order_number = additionalData.lab_order_number;
      if (additionalData.lab_estimated_delivery_date)
        updateData.lab_estimated_delivery_date =
          additionalData.lab_estimated_delivery_date;
      if (additionalData.lab_notes)
        updateData.lab_notes = additionalData.lab_notes;
      if (additionalData.quality_notes)
        updateData.quality_notes = additionalData.quality_notes;
      if (additionalData.internal_notes)
        updateData.internal_notes = additionalData.internal_notes;
      if (additionalData.customer_notes)
        updateData.customer_notes = additionalData.customer_notes;
      if (additionalData.assigned_to)
        updateData.assigned_to = additionalData.assigned_to;
      if (additionalData.lab_contact_person)
        updateData.lab_contact_person = additionalData.lab_contact_person;

      const { error: updateError } = await supabase
        .from("lab_work_orders")
        .update(updateData)
        .eq("id", id);

      if (updateError) {
        logger.warn("Error updating work order", updateError);
        // Don't fail, status was already updated
      }
    }

    // Fetch updated work order
    const { data: updatedWorkOrder, error: fetchError } =
      await supabase
        .from("lab_work_orders")
        .select(
          `
        *,
        customer:customers!lab_work_orders_customer_id_fkey(id, first_name, last_name, email, phone, preferred_contact_method),
        prescription:prescriptions!lab_work_orders_prescription_id_fkey(*)
      `,
        )
        .eq("id", id)
        .single();

    if (fetchError) {
      logger.error("Error fetching updated work order", fetchError);
      return NextResponse.json(
        {
          error: "Status updated but failed to fetch updated work order",
        },
        { status: 500 },
      );
    }

    // Create notification for status change (non-blocking)
    if (updatedWorkOrder && oldStatus !== status) {
      NotificationService.notifyWorkOrderStatusChange(
        id,
        updatedWorkOrder.work_order_number,
        oldStatus,
        status,
        updatedWorkOrder.branch_id ?? undefined,
      ).catch((err) => logger.warn("Error creating notification", err));

      // If status is delivered, also create completion notification and send survey email
      if (status === "delivered") {
        const customerName = updatedWorkOrder.customer
          ? `${updatedWorkOrder.customer.first_name || ""} ${updatedWorkOrder.customer.last_name || ""}`.trim() ||
            updatedWorkOrder.customer.email ||
            "Cliente"
          : "Cliente";

        NotificationService.notifyWorkOrderCompleted(
          id,
          updatedWorkOrder.work_order_number,
          customerName,
          updatedWorkOrder.branch_id ?? undefined,
        ).catch((err) => logger.warn("Error creating notification", err));

        // Send delivery completion email with survey link (non-blocking)
        let orgId = (updatedWorkOrder as { organization_id?: string })
          .organization_id;
        if (!orgId && updatedWorkOrder.branch_id) {
          const { data: branch } = await supabase
            .from("branches")
            .select("organization_id")
            .eq("id", updatedWorkOrder.branch_id)
            .single();
          orgId = branch?.organization_id ?? undefined;
        }
        const customerEmail = (updatedWorkOrder.customer as { email?: string })
          ?.email;
        if (orgId && customerEmail) {
          sendDeliveryCompletionEmail({
            workOrderId: id,
            organizationId: orgId,
            customerId: updatedWorkOrder.customer_id ?? null,
            customerEmail,
            customerName,
            workOrderNumber: updatedWorkOrder.work_order_number || "",
          }).catch((err) =>
            logger.warn("Error sending delivery completion email", err),
          );
        }
      }

      // If status is ready_for_pickup, send email and optionally WhatsApp to customer
      if (status === "ready_for_pickup") {
        (async () => {
          try {
            const customer = updatedWorkOrder.customer as {
              email?: string;
              phone?: string;
              preferred_contact_method?: string;
              first_name?: string;
              last_name?: string;
            } | null;
            const hasEmail =
              customer?.email || (updatedWorkOrder as unknown).email;

            if (hasEmail) {
              const { data: adminUser } = await supabase
                .from("admin_users")
                .select("organization_id")
                .eq("id", user.id)
                .single();

              const organizationId = adminUser?.organization_id;

              await sendWorkOrderReady(
                {
                  customer_name:
                    `${customer?.first_name || ""} ${customer?.last_name || ""}`.trim() ||
                    "Cliente",
                  customer_email:
                    customer?.email || (updatedWorkOrder as unknown).email,
                  work_order_number: updatedWorkOrder.work_order_number,
                },
                organizationId ?? undefined,
              );
            }

            if (
              customer?.phone &&
              customer?.preferred_contact_method === "whatsapp"
            ) {
              const { data: branch } = await supabase
                .from("branches")
                .select("name")
                .eq("id", updatedWorkOrder.branch_id)
                .single();
              await sendWorkOrderReadyWhatsApp(
                customer.phone,
                updatedWorkOrder.work_order_number,
                branch?.name ?? undefined,
              );
            }
          } catch (err) {
            logger.error("Error sending work order ready notification", err);
          }
        })();
      }
    }

    return NextResponse.json({
      success: true,
      workOrder: updatedWorkOrder,
    });
  } catch (error) {
    logger.error("Error in work order status update API", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { addBranchFilter, getBranchContext } from "@/lib/api/branch-middleware";
import {
  AuthenticationError,
  AuthorizationError,
  ValidationError,
} from "@/lib/api/errors";
import {
  createApiErrorResponse,
  createPaginatedResponse,
} from "@/lib/api/response";
import {
  parseAndValidateBody,
  validationErrorResponse,
} from "@/lib/api/validation/zod-helpers";
import { createWorkOrderSchema } from "@/lib/api/validation/zod-schemas";
import { appLogger as logger } from "@/lib/logger";
import { NotificationService } from "@/lib/notifications/notification-service";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient, createServiceRoleClient } from "@/utils/supabase/server";


export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  const requestId = crypto.randomUUID();

  try {
    logger.info("Work Orders API GET called", { requestId });

    const supabase = await createClient();

    // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      logger.error("User authentication failed", {
        error: userError,
        requestId,
      });
      throw new AuthenticationError("Unauthorized");
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      logger.warn("User is not admin", { email: user.email, requestId });
      throw new AuthorizationError("Admin access required");
    }

    // Get branch context
    const branchContext = await getBranchContext(request, user.id);

    const searchParams = request.nextUrl.searchParams;
    const status = searchParams.get("status") || "all";
    const customerId = searchParams.get("customer_id");
    const page = parseInt(searchParams.get("page") || "1");
    const limit = parseInt(searchParams.get("limit") || "20");

    // Build base query with branch filter
    let query = supabase
      .from("lab_work_orders")
      .select("*", { count: "exact" })
      .order("created_at", { ascending: false });

    // Apply branch filter
    query = addBranchFilter(
      query,
      branchContext.branchId,
      branchContext.isSuperAdmin,
      branchContext.organizationId,
    );

    if (status !== "all") {
      query = query.eq("status", status);
    }

    if (customerId) {
      query = query.eq("customer_id", customerId);
    }

    const from = (page - 1) * limit;
    const to = from + limit - 1;

    const { data: workOrders, error, count } = await query.range(from, to);

    if (error) {
      logger.error("Error fetching work orders", {
        error,
        errorDetails: JSON.stringify(error, null, 2),
        errorCode: error.code,
        errorMessage: error.message,
        errorHint: error.hint,
        requestId,
      });
      throw new Error(`Failed to fetch work orders: ${error.message}`);
    }

    // Fetch related data using batch queries to avoid N+1
    let workOrdersWithRelations = workOrders || [];
    if (workOrdersWithRelations.length > 0) {
      // Fetch customers (from customers table)
      const customerIds = [
        ...new Set(
          workOrdersWithRelations.map((wo) => wo.customer_id).filter(Boolean),
        ),
      ];
      const { data: customers } =
        customerIds.length > 0
          ? await supabase
              .from("customers")
              .select("id, first_name, last_name, email, phone")
              .in("id", customerIds)
          : { data: [] };

      // Fetch prescriptions
      const prescriptionIds = [
        ...new Set(
          workOrdersWithRelations
            .map((wo) => wo.prescription_id)
            .filter(Boolean),
        ),
      ];
      const { data: prescriptions } =
        prescriptionIds.length > 0
          ? await supabase
              .from("prescriptions")
              .select("*")
              .in("id", prescriptionIds)
          : { data: [] };

      // Fetch quotes
      const quoteIds = [
        ...new Set(
          workOrdersWithRelations.map((wo) => wo.quote_id).filter(Boolean),
        ),
      ];
      const { data: quotes } =
        quoteIds.length > 0
          ? await supabase.from("quotes").select("*").in("id", quoteIds)
          : { data: [] };

      // Fetch products
      const productIds = [
        ...new Set(
          workOrdersWithRelations
            .map((wo) => wo.frame_product_id)
            .filter(Boolean),
        ),
      ];
      const { data: products } =
        productIds.length > 0
          ? await supabase
              .from("products")
              .select("id, name, price, frame_brand, frame_model")
              .in("id", productIds)
          : { data: [] };

      // Fetch assigned staff
      const staffIds = [
        ...new Set(
          workOrdersWithRelations.map((wo) => wo.assigned_to).filter(Boolean),
        ),
      ];
      const { data: staff } =
        staffIds.length > 0
          ? await supabase
              .from("profiles")
              .select("id, first_name, last_name")
              .in("id", staffIds)
          : { data: [] };

      // Map relations to work orders
      workOrdersWithRelations = workOrdersWithRelations.map((workOrder) => ({
        ...workOrder,
        customer:
          customers?.find((c) => c.id === workOrder.customer_id) || null,
        prescription:
          prescriptions?.find((p) => p.id === workOrder.prescription_id) ||
          null,
        quote: quotes?.find((q) => q.id === workOrder.quote_id) || null,
        frame_product:
          products?.find((p) => p.id === workOrder.frame_product_id) || null,
        assigned_staff:
          staff?.find((s) => s.id === workOrder.assigned_to) || null,
      }));
    }

    logger.debug("Work orders fetched successfully", {
      count: workOrdersWithRelations.length,
      total: count,
      requestId,
    });

    // Use standardized paginated response
    return createPaginatedResponse(
      workOrdersWithRelations,
      {
        page,
        limit,
        total: count || 0,
      },
      { requestId },
    );
  } catch (error) {
    logger.error("Error in work orders API GET", { error, requestId });
    return createApiErrorResponse(
      error instanceof Error ? error : new Error("Internal server error"),
      { requestId },
    );
  }
}

export async function POST(request: NextRequest) {
  try {
        const supabase = await createClient();

        // Check admin authorization
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Admin access required" },
        { status: 403 },
      );
    }

    // Validate request body with Zod
    let validatedBody;
    try {
      validatedBody = await parseAndValidateBody(
        request,
        createWorkOrderSchema,
      );
    } catch (error) {
      if (error instanceof ValidationError) {
        return validationErrorResponse(error);
      }
      throw error;
    }

    // Get branch context
    const branchContext = await getBranchContext(request, user.id);

    // Validate branch access for non-super admins
    if (!branchContext.isSuperAdmin && !branchContext.branchId) {
      return NextResponse.json(
        {
          error: "Debe seleccionar una sucursal para crear trabajos",
        },
        { status: 400 },
      );
    }

    // Generate work order number (needs service_role for global sequence)
    const serviceSupabase = createServiceRoleClient();
    const { data: workOrderNumber, error: workOrderNumberError } =
      await serviceSupabase.rpc("generate_work_order_number");

    if (workOrderNumberError || !workOrderNumber) {
      logger.error("Error generating work order number", workOrderNumberError);
      return NextResponse.json(
        { error: "Failed to generate work order number" },
        { status: 500 },
      );
    }

    // Get prescription snapshot if prescription_id is provided
    let prescriptionSnapshot = null;
    if (validatedBody.prescription_id) {
      const { data: prescription } = await supabase
        .from("prescriptions")
        .select("*")
        .eq("id", validatedBody.prescription_id)
        .single();

      if (prescription) {
        prescriptionSnapshot = prescription;
      }
    }

    // Prepare insert data - ensure no undefined values
    // Usar validatedBody para campos validados por Zod
    const insertData: Record<string, unknown> = {
      work_order_number: workOrderNumber,
      branch_id: branchContext.branchId,
      customer_id: validatedBody.customer_id,
      prescription_id: validatedBody.prescription_id ?? null,
      quote_id: (validatedBody as unknown).quote_id ?? null,
      frame_product_id: validatedBody.frame_product_id ?? null,
      frame_name: validatedBody.frame_name.trim(),
      frame_brand: validatedBody.frame_brand ?? null,
      frame_model: validatedBody.frame_model ?? null,
      frame_color: validatedBody.frame_color ?? null,
      frame_size: validatedBody.frame_size ?? null,
      frame_sku: validatedBody.frame_sku ?? null,
      frame_serial_number:
        (validatedBody as unknown).frame_serial_number ?? null,
      lens_type: validatedBody.lens_type.trim(),
      lens_material: validatedBody.lens_material.trim(),
      lens_index: validatedBody.lens_index ?? null,
      lens_treatments: validatedBody.lens_treatments || [],
      lens_tint_color: validatedBody.lens_tint_color ?? null,
      lens_tint_percentage: validatedBody.lens_tint_percentage ?? null,
      prescription_snapshot: prescriptionSnapshot,
      lab_name: validatedBody.lab_name ?? null,
      lab_contact: validatedBody.lab_contact ?? null,
      lab_order_number: validatedBody.lab_order_number ?? null,
      lab_estimated_delivery_date:
        validatedBody.lab_estimated_delivery_date ?? null,
      status: validatedBody.status || "quote",
      frame_cost:
        typeof validatedBody.frame_cost === "number"
          ? validatedBody.frame_cost
          : validatedBody.frame_cost || 0,
      lens_cost:
        typeof validatedBody.lens_cost === "number"
          ? validatedBody.lens_cost
          : validatedBody.lens_cost || 0,
      treatments_cost:
        typeof validatedBody.treatments_cost === "number"
          ? validatedBody.treatments_cost
          : validatedBody.treatments_cost || 0,
      labor_cost:
        typeof validatedBody.labor_cost === "number"
          ? validatedBody.labor_cost
          : validatedBody.labor_cost || 0,
      lab_cost:
        typeof validatedBody.lab_cost === "number"
          ? validatedBody.lab_cost
          : validatedBody.lab_cost || 0,
      subtotal:
        typeof validatedBody.subtotal === "number"
          ? validatedBody.subtotal
          : validatedBody.subtotal || 0,
      tax_amount:
        typeof validatedBody.tax_amount === "number"
          ? validatedBody.tax_amount
          : validatedBody.tax_amount || 0,
      discount_amount:
        typeof validatedBody.discount_amount === "number"
          ? validatedBody.discount_amount
          : validatedBody.discount_amount || 0,
      total_amount:
        typeof validatedBody.total_amount === "number"
          ? validatedBody.total_amount
          : parseFloat(String(validatedBody.total_amount)),
      currency: validatedBody.currency || "CLP",
      payment_status: validatedBody.payment_status || "pending",
      payment_method: validatedBody.payment_method ?? null,
      deposit_amount:
        typeof validatedBody.deposit_amount === "number"
          ? validatedBody.deposit_amount
          : validatedBody.deposit_amount || 0,
      balance_amount:
        validatedBody.balance_amount ?? validatedBody.total_amount,
      pos_order_id: validatedBody.pos_order_id ?? null,
      internal_notes: validatedBody.internal_notes ?? null,
      customer_notes: validatedBody.customer_notes ?? null,
      assigned_to: validatedBody.assigned_to || user.id,
      created_by: user.id,
    };

    // Log insert data for debugging (remove sensitive data)
    logger.debug("Creating work order with data", {
      work_order_number: insertData.work_order_number,
      branch_id: insertData.branch_id,
      customer_id: insertData.customer_id,
      frame_name: insertData.frame_name,
      lens_type: insertData.lens_type,
      lens_material: insertData.lens_material,
      total_amount: insertData.total_amount,
    });

    // Create work order
    const { data: newWorkOrder, error: workOrderError } =
      await supabase
        .from("lab_work_orders")
        .insert(insertData)
        .select(
          `
        *,
        customer:customers!lab_work_orders_customer_id_fkey(id, first_name, last_name, email, phone),
        prescription:prescriptions!lab_work_orders_prescription_id_fkey(*)
      `,
        )
        .single();

    if (workOrderError) {
      logger.error("Error creating work order", workOrderError, {
        errorDetails: JSON.stringify(workOrderError, null, 2),
        insertData: JSON.stringify(insertData, null, 2),
      });
      return NextResponse.json(
        {
          error: "Failed to create work order",
          details: workOrderError.message,
          code: workOrderError.code,
          hint: workOrderError.hint,
        },
        { status: 500 },
      );
    }

    // If status is not 'quote', update status dates
    if (validatedBody.status && validatedBody.status !== "quote") {
      await supabase.rpc("update_work_order_status", {
        p_work_order_id: newWorkOrder.id,
        p_new_status: validatedBody.status,
        p_changed_by: user.id,
        p_notes: "Work order created",
      });
    }

    // Create notification for new work order (non-blocking)
    if (newWorkOrder) {
      const customerName = newWorkOrder.customer
        ? `${newWorkOrder.customer.first_name || ""} ${newWorkOrder.customer.last_name || ""}`.trim() ||
          newWorkOrder.customer.email ||
          "Cliente"
        : "Cliente";

      NotificationService.notifyNewWorkOrder(
        newWorkOrder.id,
        newWorkOrder.work_order_number,
        customerName,
        newWorkOrder.total_amount,
        newWorkOrder.branch_id ?? branchContext.branchId ?? undefined,
      ).catch((err) => logger.error("Error creating notification", err));
    }

    return NextResponse.json({
      success: true,
      workOrder: newWorkOrder,
    });
  } catch (error) {
    logger.error("Error in work orders POST API", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

/**
 * POST /api/agent/chat — Agent chat endpoint with structured Block[] responses via SSE.
 *
 * Parallel to the legacy /api/admin/chat — does NOT modify it.
 *
 * Flow:
 *   1. Auth validation
 *   2-8. Rate-limited handler body (withRateLimit, 30 req/min)
 *   3. Tier quota check → 429/403
 *   4. Build AgentSession from body
 *   5. Execute memory loop (agent-loop.ts)
 *   6. Build 4-layer prompt + tools filtered by role
 *   7. Call agent.streamChatStructured() with SSE stream
 *   8. Events: event: block, event: done
 *
 * @module api/agent/chat
 */

import { NextRequest, NextResponse } from "next/server";

import { createAgent } from "@/lib/ai/agent/core";
import { buildSystemPrompt } from "@/lib/ai/agent/prompt-builder";
import { buildSession } from "@/lib/ai/agent/session";
import { executeMemoryLoop } from "@/lib/ai/memory/agent-loop";
import { getAllTools } from "@/lib/ai/tools";
import { appLogger as logger } from "@/lib/logger";
import { withRateLimit } from "@/lib/rate-limiting";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";

export async function POST(request: NextRequest) {
  try {
    const supabase = await createClient();

    // 1. Auth validation
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      return NextResponse.json({ error: "No autorizado" }, { status: 401 });
    }

    const { data: isAdmin } = (await supabase.rpc("is_admin", {
      user_id: user.id,
    } as IsAdminParams)) as { data: IsAdminResult | null; error: Error | null };
    if (!isAdmin) {
      return NextResponse.json(
        { error: "Acceso de administrador requerido" },
        { status: 403 },
      );
    }

    const { data: adminUser } = await supabase
      .from("admin_users")
      .select("organization_id, role, full_name")
      .eq("id", user.id)
      .single();

    // 2-8. Rate-limited handler body
    return withRateLimit({ limit: 30, windowMs: 60_000, keyPrefix: "agent" })(
      request,
      async () => {
        // 3. Tier quota check
        if (adminUser?.organization_id) {
          const { validateFeature } = await import("@/lib/saas/tier-validator");
          const hasChatIa = await validateFeature(
            adminUser.organization_id,
            "chat_ia",
          );
          if (!hasChatIa) {
            return NextResponse.json(
              {
                error:
                  "Chat IA no está incluido en tu plan. Actualiza a Pro o Premium para usar esta función.",
                code: "FEATURE_NOT_AVAILABLE",
              },
              { status: 403 },
            );
          }
        }

        // 4. Parse body and build session
        const body = await request.json();
        const sessionResult = buildSession(body);

        if ("status" in sessionResult && sessionResult.status === 400) {
          return NextResponse.json(
            { error: sessionResult.error },
            { status: 400 },
          );
        }

        // Narrow type after validation
        const session =
          sessionResult as import("@/lib/ai/agent/session").AgentSession;

        // 5. Execute memory loop (parallel) — using auth'd supabase from line 35
        const memoryContext = await executeMemoryLoop({
          message: session.message,
          orgId: session.context.orgId,
          supabase,
        });

        // 6. Filter tools by role + build prompt
        const tools = getAllTools(session.role);
        const systemPrompt = buildSystemPrompt({
          session,
          memoryContext,
          tools,
        });

        // 7. Resolve org ID and create agent with 30s LLM timeout
        const resolvedOrgId =
          adminUser?.organization_id || session.context.orgId;

        const agent = await createAgent({
          userId: user.id,
          sessionId: session.sessionId,
          organizationId: resolvedOrgId,
          config: {
            systemPrompt,
            enableToolCalling: true,
            maxTokens: 2048,
            // ponytail: hard 30s timeout — make configurable if per-provider needs differ
            temperature: 0.7,
          },
          currentBranchId: session.context.branchId,
          supabase,
          userData: {
            role: adminUser?.role || session.role,
            name: adminUser?.full_name || undefined,
          },
        });

        // 8. SSE stream with timeout
        const stream = new ReadableStream({
          async start(controller) {
            const encoder = new TextEncoder();
            let hasContent = false;

            // ponytail: 30s timeout — abort signal pattern if per-request cancellation needed
            const timeoutId = setTimeout(() => {
              logger.warn("Agent stream timed out after 30s", {
                sessionId: session.sessionId,
              });
              const errData = JSON.stringify({
                type: "error",
                content:
                  "Lo siento, no pude procesar tu solicitud. Intenta de nuevo.",
              });
              controller.enqueue(
                encoder.encode(`event: block\ndata: ${errData}\n\n`),
              );
              controller.enqueue(
                encoder.encode(
                  `event: done\ndata: ${JSON.stringify({ session_id: session.sessionId })}\n\n`,
                ),
              );
              controller.close();
            }, 30_000);

            try {
              for await (const result of agent.streamChatStructured(
                session.message,
                session.context,
              )) {
                clearTimeout(timeoutId);

                if (result.blocks && result.blocks.length > 0) {
                  hasContent = true;
                  for (const block of result.blocks) {
                    const data = JSON.stringify(block);
                    controller.enqueue(
                      encoder.encode(`event: block\ndata: ${data}\n\n`),
                    );
                  }
                }

                if (result.done) {
                  const doneData = JSON.stringify({
                    session_id: session.sessionId,
                  });
                  controller.enqueue(
                    encoder.encode(`event: done\ndata: ${doneData}\n\n`),
                  );
                  controller.close();
                  return;
                }
              }

              // Fallback if generator finished without emitting done
              if (!hasContent) {
                const data = JSON.stringify({
                  type: "text",
                  content: "Procesado.",
                });
                controller.enqueue(
                  encoder.encode(`event: block\ndata: ${data}\n\n`),
                );
              }
              controller.enqueue(
                encoder.encode(
                  `event: done\ndata: ${JSON.stringify({ session_id: session.sessionId })}\n\n`,
                ),
              );
              controller.close();
            } catch (err) {
              clearTimeout(timeoutId);
              logger.error("Agent stream error", { error: err });
              const errData = JSON.stringify({
                type: "error",
                content:
                  "Ocurrió un error al procesar tu solicitud. Intenta de nuevo.",
              });
              controller.enqueue(
                encoder.encode(`event: block\ndata: ${errData}\n\n`),
              );
              controller.enqueue(
                encoder.encode(
                  `event: done\ndata: ${JSON.stringify({ session_id: session.sessionId })}\n\n`,
                ),
              );
              controller.close();
            }
          },
        });

        return new NextResponse(stream, {
          headers: {
            "Content-Type": "text/event-stream",
            "Cache-Control": "no-cache",
            Connection: "keep-alive",
          },
        });
      },
    );
  } catch (error) {
    logger.error("Agent chat API error", { error });
    return NextResponse.json(
      { error: "Error interno del servidor" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import { rateLimitConfigs, withRateLimit } from "@/lib/rate-limiting";
import { createClientFromRequest } from "@/utils/supabase/server";

/**
 * POST /api/ai/insights/:id/dismiss
 * Dismiss an insight
 */
export const dynamic = "force-dynamic";
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  return withRateLimit(rateLimitConfigs.modification)(request, async () => {
    try {
      const { id } = await params;

      const { client: supabase, getUser } =
        await createClientFromRequest(request);

      // Check authentication
      const { data, error: userError } = await getUser();
      const user = data?.user;
      if (userError || !user) {
        logger.error("User authentication failed", userError);
        return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
      }

      // Get user's organization
      const { data: adminUser, error: adminError } = await supabase
        .from("admin_users")
        .select("organization_id")
        .eq("id", user.id)
        .eq("is_active", true)
        .single();

      if (adminError || !adminUser?.organization_id) {
        logger.error("Organization not found", { userId: user.id });
        return NextResponse.json(
          { error: "Organization not found" },
          { status: 404 },
        );
      }

      // Update insight to dismissed
      const { data: insight, error: updateError } = await supabase
        .from("ai_insights")
        .update({ is_dismissed: true })
        .eq("id", id)
        .eq("organization_id", adminUser.organization_id)
        .select()
        .single();

      if (updateError) {
        logger.error("Error dismissing insight", {
          error: updateError,
          insightId: id,
        });
        return NextResponse.json(
          { error: "Failed to dismiss insight" },
          { status: 500 },
        );
      }

      if (!insight) {
        return NextResponse.json(
          { error: "Insight not found" },
          { status: 404 },
        );
      }

      logger.info("Insight dismissed", { insightId: id, userId: user.id });

      return NextResponse.json({ success: true, insight });
    } catch (error: unknown) {
      logger.error("Dismiss insight API error", { error: error.message });
      return NextResponse.json(
        { error: "Internal server error" },
        { status: 500 },
      );
    }
  });
}

import { NextRequest, NextResponse } from "next/server";

import { InsightFeedbackSchema } from "@/lib/ai/insights/schemas";
import { parseAndValidateBody } from "@/lib/api/validation/zod-helpers";
import { appLogger as logger } from "@/lib/logger";
import { rateLimitConfigs, withRateLimit } from "@/lib/rate-limiting";
import { createClientFromRequest } from "@/utils/supabase/server";

/**
 * POST /api/ai/insights/:id/feedback
 * Submit feedback for an insight
 */
export const dynamic = "force-dynamic";
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  return withRateLimit(rateLimitConfigs.modification)(request, async () => {
    try {
      const { id } = await params;

      // Validate body
      const { score, comment } = await parseAndValidateBody(
        request,
        InsightFeedbackSchema,
      );

      const { client: supabase, getUser } =
        await createClientFromRequest(request);

      // Check authentication
      const { data, error: userError } = await getUser();
      const user = data?.user;
      if (userError || !user) {
        logger.error("User authentication failed", userError);
        return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
      }

      // Get user's organization
      const { data: adminUser, error: adminError } = await supabase
        .from("admin_users")
        .select("organization_id")
        .eq("id", user.id)
        .eq("is_active", true)
        .single();

      if (adminError || !adminUser?.organization_id) {
        logger.error("Organization not found", { userId: user.id });
        return NextResponse.json(
          { error: "Organization not found" },
          { status: 404 },
        );
      }

      // Update insight with feedback
      const { data: insight, error: updateError } = await supabase
        .from("ai_insights")
        .update({
          feedback_score: score,
          feedback_comment: comment ?? null,
          updated_at: new Date().toISOString(),
        })
        .eq("id", id)
        .eq("organization_id", adminUser.organization_id)
        .select()
        .single();

      if (updateError) {
        logger.error("Error submitting feedback", {
          error: updateError,
          insightId: id,
        });
        return NextResponse.json(
          { error: "Failed to submit feedback" },
          { status: 500 },
        );
      }

      if (!insight) {
        return NextResponse.json(
          { error: "Insight not found" },
          { status: 404 },
        );
      }

      logger.info("Feedback submitted", {
        insightId: id,
        score,
        userId: user.id,
      });

      return NextResponse.json({ success: true, insight });
    } catch (error: unknown) {
      logger.error("Feedback API error", { error: error.message });
      return NextResponse.json(
        { error: "Internal server error" },
        { status: 500 },
      );
    }
  });
}

import { NextRequest, NextResponse } from "next/server";

import { generateInsights } from "@/lib/ai/insights/generator";
import { prepareInsightData } from "@/lib/ai/insights/prepare-data";
import type { InsightSection } from "@/lib/ai/insights/schemas";
import { createOrganizationalMemory } from "@/lib/ai/memory/organizational";
import { getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import { rateLimitConfigs, withRateLimit } from "@/lib/rate-limiting";
import { createClientFromRequest } from "@/utils/supabase/server";

const ALL_SECTIONS: InsightSection[] = [
  "dashboard",
  "inventory",
  "clients",
  "pos",
  "analytics",
];

/**
 * POST /api/ai/insights/generate-all
 * Generate insights for ALL sections. Used when user clicks "Regenerar insights".
 */
export const dynamic = "force-dynamic";
export const maxDuration = 120; // 2 min for multiple LLM calls

export async function POST(request: NextRequest) {
  return withRateLimit(rateLimitConfigs.general)(request, async () => {
    try {
      const { client: supabase, getUser } =
        await createClientFromRequest(request);

      const { data: userData, error: userError } = await getUser();
      const user = userData?.user;
      if (userError || !user) {
        logger.error("User authentication failed", userError);
        return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
      }

      const { data: adminUser, error: adminError } = await supabase
        .from("admin_users")
        .select("organization_id")
        .eq("id", user.id)
        .eq("is_active", true)
        .single();

      if (adminError || !adminUser?.organization_id) {
        logger.error("Organization not found", { userId: user.id });
        return NextResponse.json(
          { error: "Organization not found" },
          { status: 404 },
        );
      }

      const branchContext = await getBranchContext(request, user.id);

      const { data: organization, error: orgError } = await supabase
        .from("organizations")
        .select("name, created_at")
        .eq("id", adminUser.organization_id)
        .single();

      if (orgError || !organization) {
        logger.error("Failed to fetch organization", { error: orgError });
        return NextResponse.json(
          { error: "Failed to fetch organization" },
          { status: 500 },
        );
      }

      const orgMemory = createOrganizationalMemory(
        adminUser.organization_id,
        supabase,
      );
      const maturityLevel = await orgMemory.getMaturityLevel();

      const orgCreatedAt = new Date(organization.created_at);
      const now = new Date();
      const organizationAge = Math.floor(
        (now.getTime() - orgCreatedAt.getTime()) / (1000 * 60 * 60 * 24),
      );

      const { count: totalCustomers } = await supabase
        .from("customers")
        .select("*", { count: "exact", head: true })
        .eq("organization_id", adminUser.organization_id);

      const { count: totalProducts } = await supabase
        .from("products")
        .select("*", { count: "exact", head: true })
        .eq("organization_id", adminUser.organization_id);

      const { count: totalOrders } = await supabase
        .from("orders")
        .select("*", { count: "exact", head: true })
        .eq("organization_id", adminUser.organization_id);

      const isNewOrganization =
        organizationAge < 7 ||
        (totalOrders || 0) === 0 ||
        (totalCustomers || 0) < 5;

      const enhancedContext = {
        organizationAge,
        isNewOrganization,
        totalCustomers: totalCustomers || 0,
        totalProducts: totalProducts || 0,
        totalOrders: totalOrders || 0,
      };

      // Prepare data for ALL sections
      const { data: preparedData } = await prepareInsightData(
        supabase,
        adminUser.organization_id,
        organization.name,
        null,
        branchContext,
      );

      let totalCount = 0;
      const sectionCounts: Record<string, number> = {};

      for (const section of ALL_SECTIONS) {
        try {
          const sectionData =
            preparedData[section as keyof typeof preparedData];
          if (!sectionData) {
            logger.warn("No data for section, skipping", { section });
            continue;
          }

          const insights = await generateInsights({
            section,
            data: sectionData,
            organizationName: organization.name,
            organizationId: adminUser.organization_id,
            maturityLevel,
            additionalContext: enhancedContext,
            temperature: 0.7,
            useMaturityAdaptation: true,
            supabase,
          });

          const insightsToInsert = insights.map((insight) => ({
            organization_id: adminUser.organization_id,
            section,
            ...insight,
          }));

          const { error: insertError } = await supabase
            .from("ai_insights")
            .insert(insightsToInsert);

          if (insertError) {
            logger.error("Failed to save insights", {
              section,
              error: insertError,
            });
            continue;
          }

          sectionCounts[section] = insights.length;
          totalCount += insights.length;

          await new Promise((r) => setTimeout(r, 300));
        } catch (err: unknown) {
          logger.error("Insight generation failed for section", {
            section,
            error: err,
          });
        }
      }

      logger.info("Generate-all insights completed", {
        organizationId: adminUser.organization_id,
        totalCount,
        sectionCounts,
      });

      return NextResponse.json({
        success: true,
        count: totalCount,
        sectionCounts,
      });
    } catch (error: unknown) {
      logger.error("Generate-all insights API error", { error });

      if (
        error instanceof Error &&
        error.message.includes("No available LLM providers")
      ) {
        return NextResponse.json(
          {
            error:
              "AI service is not configured. Please configure at least one LLM provider.",
          },
          { status: 503 },
        );
      }

      return NextResponse.json(
        {
          error:
            error instanceof Error ? error.message : "Internal server error",
        },
        { status: 500 },
      );
    }
  });
}

import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";

import { generateInsights } from "@/lib/ai/insights/generator";
import { InsightSectionSchema } from "@/lib/ai/insights/schemas";
import { createOrganizationalMemory } from "@/lib/ai/memory/organizational";
import {
  parseAndValidateBody,
  parseAndValidateQuery,
} from "@/lib/api/validation/zod-helpers";
import { appLogger as logger } from "@/lib/logger";
import { rateLimitConfigs, withRateLimit } from "@/lib/rate-limiting";
import { createClientFromRequest } from "@/utils/supabase/server";

const generateQuerySchema = z.object({
  section: InsightSectionSchema.optional(),
});

const generateBodySchema = z.object({
  section: InsightSectionSchema,
  data: z.any(), // Data to analyze
  additionalContext: z.record(z.any()).optional(),
  forceRegenerate: z.boolean().optional().default(false),
});

/**
 * POST /api/ai/insights/generate
 * Generate insights for a specific section
 * This endpoint is used by cron jobs or manual triggers
 */
export const dynamic = "force-dynamic";
export async function POST(request: NextRequest) {
  return withRateLimit(rateLimitConfigs.general)(request, async () => {
    try {
      // Validate body
      const body = await parseAndValidateBody(request, generateBodySchema);
      const { section, data, additionalContext, forceRegenerate } = body;

      const { client: supabase, getUser } =
        await createClientFromRequest(request);

      // Check authentication
      const { data: userData, error: userError } = await getUser();
      const user = userData?.user;
      if (userError || !user) {
        logger.error("User authentication failed", userError);
        return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
      }

      // Get user's organization
      const { data: adminUser, error: adminError } = await supabase
        .from("admin_users")
        .select("organization_id")
        .eq("id", user.id)
        .eq("is_active", true)
        .single();

      if (adminError || !adminUser?.organization_id) {
        logger.error("Organization not found", { userId: user.id });
        return NextResponse.json(
          { error: "Organization not found" },
          { status: 404 },
        );
      }

      // Get organization name and metadata
      const { data: organization, error: orgError } = await supabase
        .from("organizations")
        .select("name, created_at")
        .eq("id", adminUser.organization_id)
        .single();

      if (orgError || !organization) {
        logger.error("Failed to fetch organization", { error: orgError });
        return NextResponse.json(
          { error: "Failed to fetch organization" },
          { status: 500 },
        );
      }

      // Use organizational memory to get maturity level and context
      const orgMemory = createOrganizationalMemory(
        adminUser.organization_id,
        supabase,
      );
      const maturityLevel = await orgMemory.getMaturityLevel();

      logger.info("Organization maturity calculated", {
        organizationId: adminUser.organization_id,
        maturityLevel: maturityLevel.level,
        daysSinceCreation: maturityLevel.daysSinceCreation,
        totalOrders: maturityLevel.totalOrders,
      });

      // Calculate organization age (for backward compatibility)
      const orgCreatedAt = new Date(organization.created_at);
      const now = new Date();
      const organizationAge = Math.floor(
        (now.getTime() - orgCreatedAt.getTime()) / (1000 * 60 * 60 * 24),
      );

      // Get basic stats to determine organization state
      const { count: totalCustomers } = await supabase
        .from("customers")
        .select("*", { count: "exact", head: true })
        .eq("organization_id", adminUser.organization_id);

      const { count: totalProducts } = await supabase
        .from("products")
        .select("*", { count: "exact", head: true })
        .eq("organization_id", adminUser.organization_id);

      const { count: totalOrders } = await supabase
        .from("orders")
        .select("*", { count: "exact", head: true })
        .eq("organization_id", adminUser.organization_id);

      // Determine if organization is new
      const isNewOrganization =
        organizationAge < 7 ||
        (totalOrders || 0) === 0 ||
        (totalCustomers || 0) < 5;

      // Enhance additional context with organization state
      const enhancedContext = {
        ...additionalContext,
        organizationAge,
        isNewOrganization,
        totalCustomers: totalCustomers || 0,
        totalProducts: totalProducts || 0,
        totalOrders: totalOrders || 0,
      };

      // Cache check: return existing insights if recent (< 24h) and not forceRegenerate
      if (!forceRegenerate) {
        const twentyFourHoursAgo = new Date();
        twentyFourHoursAgo.setHours(twentyFourHoursAgo.getHours() - 24);

        const { data: recentInsights } = await supabase
          .from("ai_insights")
          .select(
            "id, section, type, title, message, priority, action_label, action_url, metadata, is_dismissed, feedback_score, created_at, updated_at",
          )
          .eq("organization_id", adminUser.organization_id)
          .eq("section", section)
          .eq("is_dismissed", false)
          .gte("created_at", twentyFourHoursAgo.toISOString())
          .order("priority", { ascending: false })
          .order("created_at", { ascending: false })
          .limit(20);

        if (recentInsights && recentInsights.length > 0) {
          logger.info("Returning cached insights", {
            section,
            count: recentInsights.length,
            organizationId: adminUser.organization_id,
          });
          return NextResponse.json({
            success: true,
            insights: recentInsights,
            count: recentInsights.length,
            fromCache: true,
          });
        }
      }

      // Generate insights using LLM with maturity adaptation
      logger.info("Generating insights with maturity adaptation", {
        section,
        organizationId: adminUser.organization_id,
        maturityLevel: maturityLevel.level,
        organizationAge,
        isNewOrganization,
      });

      const insights = await generateInsights({
        section,
        data,
        organizationName: organization.name,
        organizationId: adminUser.organization_id,
        maturityLevel: maturityLevel,
        additionalContext: enhancedContext,
        temperature: 0.7,
        useMaturityAdaptation: true,
        supabase,
      });

      // Save insights to database
      const insightsToInsert = insights.map((insight) => ({
        organization_id: adminUser.organization_id,
        section,
        ...insight,
      }));

      const { data: insertedInsights, error: insertError } = await supabase
        .from("ai_insights")
        .insert(insightsToInsert)
        .select();

      if (insertError) {
        logger.error("Error saving insights", { error: insertError, section });
        return NextResponse.json(
          { error: "Failed to save insights" },
          { status: 500 },
        );
      }

      logger.info("Insights generated and saved", {
        section,
        count: insertedInsights?.length || 0,
        organizationId: adminUser.organization_id,
      });

      return NextResponse.json({
        success: true,
        insights: insertedInsights || [],
        count: insertedInsights?.length || 0,
      });
    } catch (error: unknown) {
      logger.error("Generate insights API error", {
        error: error.message,
        stack: error.stack,
      });

      // Return user-friendly error message
      if (error.message.includes("No available LLM providers")) {
        return NextResponse.json(
          {
            error:
              "AI service is not configured. Please configure at least one LLM provider.",
          },
          { status: 503 },
        );
      }

      return NextResponse.json(
        { error: error.message || "Internal server error" },
        { status: 500 },
      );
    }
  });
}

/**
 * GET /api/ai/insights/generate
 * Get information about insight generation (for debugging/monitoring)
 */
export async function GET(request: NextRequest) {
  return withRateLimit(rateLimitConfigs.general)(request, async () => {
    try {
      const queryParams = parseAndValidateQuery(request, generateQuerySchema);
      const section = queryParams.section;

      const { client: supabase, getUser } =
        await createClientFromRequest(request);

      // Check authentication
      const { data, error: userError } = await getUser();
      const user = data?.user;
      if (userError || !user) {
        return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
      }

      // Get user's organization
      const { data: adminUser } = await supabase
        .from("admin_users")
        .select("organization_id")
        .eq("id", user.id)
        .eq("is_active", true)
        .single();

      if (!adminUser?.organization_id) {
        return NextResponse.json(
          { error: "Organization not found" },
          { status: 404 },
        );
      }

      // Get latest insights generation info
      let query = supabase
        .from("ai_insights")
        .select("section, created_at, count")
        .eq("organization_id", adminUser.organization_id)
        .order("created_at", { ascending: false })
        .limit(10);

      if (section) {
        query = query.eq("section", section);
      }

      const { data: recentInsights, error } = await query;

      if (error) {
        logger.error("Error fetching insight generation info", { error });
        return NextResponse.json(
          { error: "Failed to fetch generation info" },
          { status: 500 },
        );
      }

      return NextResponse.json({
        recentGenerations: recentInsights || [],
      });
    } catch (error: unknown) {
      logger.error("Get generation info error", { error: error.message });
      return NextResponse.json(
        { error: "Internal server error" },
        { status: 500 },
      );
    }
  });
}

import { NextRequest, NextResponse } from "next/server";

import { prepareInsightData } from "@/lib/ai/insights/prepare-data";
import type { InsightSection } from "@/lib/ai/insights/schemas";
import { getBranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import { rateLimitConfigs, withRateLimit } from "@/lib/rate-limiting";
import { createClientFromRequest } from "@/utils/supabase/server";

/**
 * POST /api/ai/insights/prepare-data
 * Prepare data with optional POS context (prescription, customerHistory from form)
 * Used by POS OnBlur to get data enriched with current prescription/customer
 */
export async function POST(request: NextRequest) {
  return withRateLimit(rateLimitConfigs.general)(request, async () => {
    try {
      const { client: supabase, getUser } =
        await createClientFromRequest(request);

      const { data: userData, error: userError } = await getUser();
      const user = userData?.user;
      if (userError || !user) {
        return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
      }

      const { data: adminUser, error: adminError } = await supabase
        .from("admin_users")
        .select("organization_id")
        .eq("id", user.id)
        .eq("is_active", true)
        .single();

      if (adminError || !adminUser?.organization_id) {
        return NextResponse.json(
          { error: "Organization not found" },
          { status: 404 },
        );
      }

      const branchContext = await getBranchContext(request, user.id);

      const { data: organization, error: orgError } = await supabase
        .from("organizations")
        .select("name")
        .eq("id", adminUser.organization_id)
        .single();

      if (orgError || !organization) {
        return NextResponse.json(
          { error: "Failed to fetch organization" },
          { status: 500 },
        );
      }

      const body = await request.json().catch(() => ({}));
      const section = (body.section as InsightSection) || null;
      const posContext = body.posContext as
        | {
            prescription?: Record<string, unknown>;
            customerHistory?: Record<string, unknown>;
          }
        | undefined;

      const result = await prepareInsightData(
        supabase,
        adminUser.organization_id,
        organization.name,
        section,
        branchContext,
      );

      if (
        posContext &&
        (posContext.prescription || posContext.customerHistory)
      ) {
        result.data.pos = {
          prescription: posContext.prescription || {},
          customerHistory: posContext.customerHistory || {},
        };
      }

      return NextResponse.json({
        success: true,
        organizationName: result.organizationName,
        section: result.section,
        data: result.data,
      });
    } catch (error: unknown) {
      logger.error("Prepare data POST error", { error: error.message });
      return NextResponse.json(
        { error: "Internal server error" },
        { status: 500 },
      );
    }
  });
}

