/**
 * POST /api/checkout/confirm-payment
 * Confirms a payment using MercadoPago Bricks token (Checkout API)
 */
import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";

import { ValidationError } from "@/lib/api/errors";
import {
  parseAndValidateBody,
  validationErrorResponse,
} from "@/lib/api/validation/zod-helpers";
import { appLogger as logger } from "@/lib/logger";
import { PaymentGatewayFactory, PaymentService } from "@/lib/payments";
import { rateLimitConfigs, withRateLimit } from "@/lib/rate-limiting";
import { createClientFromRequest } from "@/utils/supabase/server";

const confirmPaymentSchema = z.object({
  token: z.string().min(1, "Token es requerido"),
  paymentId: z.string().uuid("Payment ID inválido"),
  payerEmail: z.string().email("Email inválido"),
  payment_method_id: z.string().min(1, "payment_method_id es requerido"),
  issuer_id: z.string().optional(),
  description: z.string().optional(),
  saveCard: z.boolean().optional(),
});

const paymentRateLimitConfig =
  process.env.NODE_ENV === "development"
    ? { ...rateLimitConfigs.payment, maxRequests: 50 }
    : rateLimitConfigs.payment;

export const dynamic = "force-dynamic";
export async function POST(request: NextRequest) {
  return (
    withRateLimit(paymentRateLimitConfig) as (
      req: NextRequest,
      handler: () => Promise<NextResponse>,
    ) => Promise<NextResponse>
  )(request, async () => {
    try {
      logger.info("Checkout confirm-payment API called");

      const { client: supabase, getUser } =
        await createClientFromRequest(request);

      const { data: userData, error: userError } = await getUser();
      const user = userData?.user;
      if (userError || !user) {
        logger.error("User authentication failed", userError);
        return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
      }

      // Get user's organization
      const { data: adminUser, error: adminUserError } = await supabase
        .from("admin_users")
        .select("organization_id")
        .eq("id", user.id)
        .single();

      const orgId =
        adminUser && "organization_id" in adminUser
          ? (adminUser as { organization_id: string | null }).organization_id
          : null;
      if (adminUserError || !orgId) {
        logger.warn("User has no organization_id", { adminUserError });
        return NextResponse.json(
          {
            error: "Organization context required for payments.",
          },
          { status: 403 },
        );
      }

      const organizationId = orgId;

      // Parse body once (request body stream can only be read once)
      let body: z.infer<typeof confirmPaymentSchema>;
      try {
        body = await parseAndValidateBody(request, confirmPaymentSchema);
      } catch (error) {
        if (error instanceof ValidationError) {
          return validationErrorResponse(error);
        }
        throw error;
      }

      const {
        token,
        paymentId: bodyPaymentId,
        payerEmail,
        payment_method_id,
        issuer_id,
        description,
        saveCard,
      } = body;

      // Get payment record
      const paymentService = new PaymentService(supabase);
      const payment = await paymentService.getPaymentById(bodyPaymentId);

      if (!payment) {
        return NextResponse.json(
          { error: "Payment not found" },
          { status: 404 },
        );
      }

      if (payment.organization_id !== organizationId) {
        return NextResponse.json({ error: "Unauthorized" }, { status: 403 });
      }

      if (payment.gateway !== "mercadopago") {
        return NextResponse.json(
          {
            error:
              "Este método de pago requiere completar el pago en la ventana externa. Si fuiste redirigido, verifica el estado en el panel de suscripción.",
          },
          { status: 400 },
        );
      }

      // Create payment with MercadoPago (only MP supports Bricks/token flow)
      const gatewayInstance = PaymentGatewayFactory.getGateway("mercadopago");
      if (!gatewayInstance.createPaymentWithToken) {
        return NextResponse.json(
          { error: "Gateway does not support token payments" },
          { status: 400 },
        );
      }

      const mpPayment = await gatewayInstance.createPaymentWithToken(
        token,
        payment.amount,
        payment.currency,
        user.id,
        organizationId,
        payerEmail,
        payment_method_id,
        issuer_id ?? undefined,
        description || (payment.metadata?.description as string | undefined),
        payment.metadata as Record<string, unknown> | undefined,
      );

      // Update payment record
      await paymentService.updatePaymentStatus(
        payment.id,
        mpPayment.status,
        mpPayment.id,
        payment.metadata,
        mpPayment.id,
      );

      // If payment succeeded, apply to organization
      if (mpPayment.status === "succeeded") {
        await paymentService.applyPaymentSuccessToOrganization(
          organizationId,
          {
            ...payment,
            status: "succeeded",
            gateway_transaction_id: mpPayment.id,
            gateway_payment_intent_id: mpPayment.id,
          },
          mpPayment.id,
          mpPayment.id,
        );
        // Phase C: optionally save card (create MP customer + add card, store in subscription)
        const mpGateway = gatewayInstance as {
          createCustomerAndAddCard?: (
            email: string,
            token: string,
          ) => Promise<{ customerId: string; cardId: string }>;
        };
        if (saveCard && mpGateway.createCustomerAndAddCard) {
          try {
            const { customerId, cardId } =
              await mpGateway.createCustomerAndAddCard(payerEmail, token);
            await paymentService.updateSubscriptionPaymentMethod(
              organizationId,
              customerId,
              cardId,
            );
          } catch (saveError) {
            logger.warn("Failed to save card (non-blocking)", {
              error:
                saveError instanceof Error
                  ? saveError.message
                  : String(saveError),
              organizationId,
            });
            // Do not fail the response; payment already succeeded
          }
        }
      }

      return NextResponse.json({
        success: true,
        paymentId: payment.id,
        status: mpPayment.status,
        gatewayPaymentId: mpPayment.id,
      });
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : typeof error === "string"
            ? error
            : "Error desconocido al confirmar pago";
      logger.error(
        "Error in checkout confirm-payment",
        error instanceof Error ? error : new Error(message),
      );
      return NextResponse.json({ error: message }, { status: 500 });
    }
  });
}

/**
 * POST /api/checkout/create-intent
 * Creates a payment intent for checkout (public route with authentication)
 */
import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";

import { ValidationError } from "@/lib/api/errors";
import {
  parseAndValidateBody,
  validationErrorResponse,
} from "@/lib/api/validation/zod-helpers";
import { appLogger as logger } from "@/lib/logger";
import { PaymentGatewayFactory, PaymentService } from "@/lib/payments";
import { rateLimitConfigs, withRateLimit } from "@/lib/rate-limiting";
import { createClientFromRequest } from "@/utils/supabase/server";

const createCheckoutIntentSchema = z.object({
  amount: z.number().positive("El monto debe ser positivo"),
  currency: z.string().default("CLP"),
  gateway: z
    .enum(["flow", "mercadopago", "paypal", "nowpayments"])
    .default("mercadopago"),
  subscription_tier: z.enum(["basic", "pro", "premium"]).optional(),
  isUpgrade: z.boolean().optional(),
  isDowngrade: z.boolean().optional(),
});

const paymentRateLimitConfig =
  process.env.NODE_ENV === "development"
    ? { ...rateLimitConfigs.payment, maxRequests: 50 }
    : rateLimitConfigs.payment;

export const dynamic = "force-dynamic";
export async function POST(request: NextRequest) {
  return (
    withRateLimit(paymentRateLimitConfig) as (
      req: NextRequest,
      handler: () => Promise<NextResponse>,
    ) => Promise<NextResponse>
  )(request, async () => {
    try {
      logger.info("Checkout create-intent API called");

      let supabase: Awaited<
        ReturnType<typeof createClientFromRequest>
      >["client"];
      let getUser: Awaited<
        ReturnType<typeof createClientFromRequest>
      >["getUser"];
      try {
        const created = await createClientFromRequest(request);
        supabase = created.client;
        getUser = created.getUser;
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        logger.error(
          "createClientFromRequest failed",
          err instanceof Error ? err : new Error(msg),
        );
        return NextResponse.json(
          {
            error:
              "Error de sesión. Intenta recargar o iniciar sesión de nuevo.",
          },
          { status: 500 },
        );
      }

      const { data: userData, error: userError } = await getUser();
      const user = userData?.user;
      if (userError || !user) {
        logger.error("User authentication failed", userError);
        return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
      }

      // Get user's organization
      const { data: adminUser, error: adminUserError } = await supabase
        .from("admin_users")
        .select("organization_id")
        .eq("id", user.id)
        .single();

      const orgId =
        adminUser && "organization_id" in adminUser
          ? (adminUser as { organization_id: string | null }).organization_id
          : null;
      if (adminUserError || !orgId) {
        logger.warn("User has no organization_id", { adminUserError });
        return NextResponse.json(
          {
            error:
              "Organization context required for payments. Your user must belong to an organization.",
          },
          { status: 403 },
        );
      }

      const organizationId = orgId;

      let body: z.infer<typeof createCheckoutIntentSchema>;
      try {
        body = await parseAndValidateBody(request, createCheckoutIntentSchema);
      } catch (error) {
        if (error instanceof ValidationError) {
          return validationErrorResponse(error);
        }
        throw error;
      }

      const { amount, currency, gateway, subscription_tier } = body;
      let amountNum = Number(amount);

      // NOWPayments normalization: Convert CLP to USD because NOWPayments doesn't support CLP fiat price
      if (gateway === "nowpayments" && currency === "CLP") {
        const CLP_TO_USD_RATE =
          Number(process.env.NOWPAYMENTS_CLP_TO_USD_RATE || "950") || 950;
        const originalAmount = amountNum;
        amountNum = Math.round((amountNum / CLP_TO_USD_RATE) * 100) / 100;
        currency = "USD";
        logger.info("NOWPayments Currency Normalization Applied", {
          original: `${originalAmount} CLP`,
          normalized: `${amountNum} USD`,
          rate: CLP_TO_USD_RATE,
        });
      }
      if (!Number.isFinite(amountNum) || amountNum <= 0) {
        return NextResponse.json(
          { error: "El monto debe ser un número positivo." },
          { status: 400 },
        );
      }

      const paymentService = new PaymentService(supabase);
      const gatewayInstance = PaymentGatewayFactory.getGateway(gateway);

      // Create payment record with metadata
      const metadata: Record<string, unknown> = {
        subscription_tier: subscription_tier || undefined,
        is_upgrade: body.isUpgrade || false,
        is_downgrade: body.isDowngrade || false,
      };

      let paymentRecord;
      try {
        paymentRecord = await paymentService.createPayment({
          order_id: null,
          organization_id: organizationId,
          user_id: user.id,
          amount: amountNum,
          currency,
          status: "pending",
          gateway,
          metadata,
        });
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        logger.error(
          "createPayment failed",
          err instanceof Error ? err : new Error(msg),
          { organizationId },
        );
        return NextResponse.json(
          {
            error:
              "No se pudo crear el registro de pago. Revisa permisos o contacta soporte.",
          },
          { status: 500 },
        );
      }

      let intentResponse;
      try {
        intentResponse = await gatewayInstance.createPaymentIntent(
          paymentRecord.id,
          amountNum,
          currency,
          user.id,
          organizationId,
        );
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        logger.error(
          "createPaymentIntent (gateway) failed",
          err instanceof Error ? err : new Error(msg),
          {
            gateway,
            amount: amountNum,
          },
        );
        return NextResponse.json(
          {
            error:
              process.env.NODE_ENV === "development"
                ? msg
                : "Error al conectar con la pasarela de pago. Revisa la configuración (Mercado Pago) o intenta más tarde.",
          },
          { status: 500 },
        );
      }

      try {
        await paymentService.updatePaymentStatus(
          paymentRecord.id,
          intentResponse.status,
          undefined,
          metadata,
          intentResponse.gatewayPaymentIntentId,
        );
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        logger.error(
          "updatePaymentStatus failed",
          err instanceof Error ? err : new Error(msg),
          {
            paymentId: paymentRecord.id,
          },
        );
        return NextResponse.json(
          {
            error:
              "Pago creado pero no se pudo actualizar el estado. Guarda el ID: " +
              paymentRecord.id,
          },
          { status: 500 },
        );
      }

      return NextResponse.json({
        paymentId: paymentRecord.id,
        clientSecret: intentResponse.clientSecret,
        preferenceId: intentResponse.preferenceId,
        approvalUrl: intentResponse.approvalUrl || intentResponse.invoiceUrl,
        invoiceUrl: intentResponse.invoiceUrl,
        gatewayPaymentIntentId: intentResponse.gatewayPaymentIntentId,
        status: intentResponse.status,
      });
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : typeof error === "string"
            ? error
            : "Error desconocido al crear intento de pago";
      const isDev = process.env.NODE_ENV === "development";
      logger.error(
        "Error in checkout create-intent",
        error instanceof Error ? error : new Error(message),
        isDev && error instanceof Error ? { stack: error.stack } : undefined,
      );
      return NextResponse.json(
        {
          error: isDev
            ? message
            : "Error al crear intento de pago. Intenta de nuevo.",
        },
        { status: 500 },
      );
    }
  });
}

/**
 * POST /api/checkout/create-preapproval
 * Creates a Mercado Pago PreApproval (recurring subscription) for the given tier.
 * MP will charge automatically each period; sync status via webhooks.
 */
import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";

import { ValidationError } from "@/lib/api/errors";
import {
  parseAndValidateBody,
  validationErrorResponse,
} from "@/lib/api/validation/zod-helpers";
import { appLogger as logger } from "@/lib/logger";
import { PaymentGatewayFactory } from "@/lib/payments";
import { rateLimitConfigs, withRateLimit } from "@/lib/rate-limiting";
import {
  createClientFromRequest,
} from "@/utils/supabase/server";

const createPreapprovalSchema = z.object({
  tier: z.enum(["basic", "pro", "premium"]),
  payerEmail: z.string().email("Email inválido"),
  cardTokenId: z.string().min(1, "Token de tarjeta es requerido"),
});

const paymentRateLimitConfig =
  process.env.NODE_ENV === "development"
    ? { ...rateLimitConfigs.payment, maxRequests: 30 }
    : rateLimitConfigs.payment;

const baseUrl =
  process.env.NEXT_PUBLIC_BASE_URL ||
  process.env.NEXT_PUBLIC_APP_URL ||
  "http://localhost:3000";
const backUrl = `${baseUrl.replace(/\/$/, "")}/checkout/result`;

export const dynamic = "force-dynamic";
export async function POST(request: NextRequest) {
  return (
    withRateLimit(paymentRateLimitConfig) as (
      req: NextRequest,
      handler: () => Promise<NextResponse>,
    ) => Promise<NextResponse>
  )(request, async () => {
    try {
      const { client: supabase, getUser } =
        await createClientFromRequest(request);
      const { data: userData, error: userError } = await getUser();
      const user = userData?.user;
      if (userError || !user) {
        return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
      }

      const { data: adminUser } = await supabase
        .from("admin_users")
        .select("organization_id")
        .eq("id", user.id)
        .single();

      const orgId =
        adminUser && "organization_id" in adminUser
          ? (adminUser as { organization_id: string | null }).organization_id
          : null;
      if (!orgId) {
        return NextResponse.json(
          { error: "Organization context required." },
          { status: 403 },
        );
      }

      let body: z.infer<typeof createPreapprovalSchema>;
      try {
        body = await parseAndValidateBody(request, createPreapprovalSchema);
      } catch (error) {
        if (error instanceof ValidationError) {
          return validationErrorResponse(error);
        }
        throw error;
      }

      const { tier, payerEmail, cardTokenId } = body;

      const { data: tierRow, error: tierError } = await supabase
        .from("subscription_tiers")
        .select("name, price_monthly, gateway_plan_id")
        .eq("name", tier)
        .single();

      if (tierError || !tierRow?.gateway_plan_id) {
        logger.warn("Recurring plan not found or missing gateway_plan_id", {
          tier,
        });
        return NextResponse.json(
          {
            error:
              "Plan recurrente no disponible para este tier. Use pago único.",
          },
          { status: 400 },
        );
      }

      const gateway = PaymentGatewayFactory.getGateway("mercadopago");
      if (!("createPreApproval" in gateway)) {
        return NextResponse.json(
          { error: "Recurring subscriptions not supported" },
          { status: 400 },
        );
      }

      const preapproval = await (
        gateway as {
          createPreApproval: (
            planId: string,
            payerEmail: string,
            cardTokenId: string,
            reason: string,
            externalRef: string,
            backUrl: string,
          ) => Promise<{ id: string; status: string }>;
        }
      ).createPreApproval(
        tierRow.gateway_plan_id,
        payerEmail,
        cardTokenId,
        `Opttius ${tierRow.name}`,
        orgId,
        backUrl,
      );

      const now = new Date();
      const periodEnd = new Date(now);
      periodEnd.setMonth(periodEnd.getMonth() + 1);

      const { data: existing } = await supabase
        .from("subscriptions")
        .select("id")
        .eq("organization_id", orgId)
        .order("created_at", { ascending: false })
        .limit(1)
        .maybeSingle();

      if (existing) {
        await supabase
          .from("subscriptions")
          .update({
            status: "active",
            gateway: "mercadopago",
            gateway_subscription_id: preapproval.id,
            current_period_start: now.toISOString().slice(0, 10),
            current_period_end: periodEnd.toISOString().slice(0, 10),
            cancel_at: null,
            canceled_at: null,
            updated_at: now.toISOString(),
          })
          .eq("id", existing.id);
      } else {
        await supabase.from("subscriptions").insert({
          organization_id: orgId,
          gateway: "mercadopago",
          status: "active",
          gateway_subscription_id: preapproval.id,
          current_period_start: now.toISOString().slice(0, 10),
          current_period_end: periodEnd.toISOString().slice(0, 10),
        });
      }

      await supabase
        .from("organizations")
        .update({
          subscription_tier: tier,
          updated_at: now.toISOString(),
        })
        .eq("id", orgId);

      return NextResponse.json({
        success: true,
        preapprovalId: preapproval.id,
        status: preapproval.status,
      });
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : typeof error === "string"
            ? error
            : "Error al crear suscripción recurrente";
      logger.error(
        "Error in create-preapproval",
        error instanceof Error ? error : new Error(message),
      );
      return NextResponse.json({ error: message }, { status: 500 });
    }
  });
}

/**
 * GET /api/checkout/recurring-plans
 * Returns subscription tiers with Mercado Pago PreApproval Plan ids (for recurring).
 * Creates MP plans on first request if gateway_plan_id is missing (lazy init).
 */
import { NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import { PaymentGatewayFactory } from "@/lib/payments";
import { createClient } from "@/utils/supabase/server";

function getBackUrl(): string {
  const base =
    process.env.NEXT_PUBLIC_BASE_URL ||
    process.env.NEXT_PUBLIC_APP_URL ||
    "http://localhost:3000";
  return `${base.replace(/\/$/, "")}/checkout/result`;
}

export const dynamic = "force-dynamic";
export async function GET() {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const { data: tiers, error } = await supabase
    .from("subscription_tiers")
    .select("name, price_monthly, gateway_plan_id")
    .order("price_monthly", { ascending: true });

  if (error) {
    logger.error("Error fetching recurring plans", error);
    return NextResponse.json(
      { error: "Error al cargar planes recurrentes", details: error.message },
      { status: 500 },
    );
  }

  const gateway = PaymentGatewayFactory.getGateway("mercadopago");
  if (!("createPreApprovalPlan" in gateway)) {
    return NextResponse.json({
      recurringPlans: (tiers || []).map(
        (t: {
          name: string;
          price_monthly: number;
          gateway_plan_id: string | null;
        }) => ({
          name: t.name,
          price_monthly: Number(t.price_monthly),
          plan_id: t.gateway_plan_id,
        }),
      ),
    });
  }

  const backUrl = getBackUrl();
  const results: Array<{
    name: string;
    price_monthly: number;
    plan_id: string | null;
  }> = [];

  for (const tier of tiers || []) {
    let planId = tier.gateway_plan_id as string | null;
    if (!planId) {
      try {
        const created = await (
          gateway as {
            createPreApprovalPlan: (
              reason: string,
              amount: number,
              currency: string,
              backUrl: string,
            ) => Promise<{ id: string }>;
          }
        ).createPreApprovalPlan(
          `Opttius Plan ${tier.name}`,
          Number(tier.price_monthly),
          "CLP",
          backUrl,
        );
        planId = created.id;
        await supabase
          .from("subscription_tiers")
          .update({ gateway_plan_id: planId })
          .eq("name", tier.name);
      } catch (err) {
        logger.warn("Failed to create MP plan for tier", {
          tier: tier.name,
          err,
        });
      }
    }
    results.push({
      name: tier.name,
      price_monthly: Number(tier.price_monthly),
      plan_id: planId,
    });
  }

  return NextResponse.json({ recurringPlans: results });
}

import { NextRequest, NextResponse } from "next/server";

import { sendAppointmentFollowUpReminder } from "@/lib/email/templates/optica";
import { appLogger as logger } from "@/lib/logger";
import { createCronClient } from "@/utils/supabase/cron";

/**
 * GET /api/cron/appointment-follow-up-reminders
 * Triggered by Vercel Cron. Sends follow-up reminder emails for appointments
 * with "Requiere Seguimiento" where follow_up_date is in 7 days.
 * Runs daily at 6:30 UTC.
 *
 * Requires CRON_SECRET for authorization.
 */
export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  const authHeader = request.headers.get("authorization");

  if (
    process.env.CRON_SECRET &&
    authHeader !== `Bearer ${process.env.CRON_SECRET}` &&
    request.headers.get("x-cron-secret") !== process.env.CRON_SECRET
  ) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    const supabase = createCronClient();

    const in7Days = new Date();
    in7Days.setDate(in7Days.getDate() + 7);
    const targetDateStr = in7Days.toISOString().split("T")[0];

    const { data: appointments } = await supabase
      .from("appointments")
      .select(
        `
        id,
        follow_up_date,
        follow_up_required,
        customer_id,
        guest_email,
        guest_first_name,
        guest_last_name,
        branch_id,
        organization_id,
        branch:branches(id, name, organization_id),
        customer:customers(id, first_name, last_name, email)
      `,
      )
      .eq("follow_up_required", true)
      .eq("follow_up_date", targetDateStr);

    if (!appointments || appointments.length === 0) {
      return NextResponse.json({
        success: true,
        message: "No follow-up reminders to send",
        sent: 0,
      });
    }

    let totalSent = 0;

    for (const apt of appointments) {
      const customerEmail =
        (apt.customer as { email?: string } | null)?.email ||
        (apt as { guest_email?: string }).guest_email;

      if (!customerEmail) continue;

      const customer = apt.customer as {
        first_name?: string;
        last_name?: string;
      } | null;
      const guestFirst = (apt as { guest_first_name?: string })
        .guest_first_name;
      const guestLast = (apt as { guest_last_name?: string }).guest_last_name;

      const customerName = customer
        ? `${customer.first_name || ""} ${customer.last_name || ""}`.trim() ||
          "Cliente"
        : `${guestFirst || ""} ${guestLast || ""}`.trim() || "Cliente";

      const branch = apt.branch as {
        name?: string;
        phone?: string;
        email?: string;
      } | null;
      const followUpDate =
        typeof apt.follow_up_date === "string"
          ? apt.follow_up_date
          : apt.follow_up_date?.toISOString?.()?.split("T")[0] || "";

      const appointmentData = {
        id: apt.id,
        customer_name: customerName,
        customer_first_name: customer?.first_name || guestFirst || "Cliente",
        customer_email: customerEmail,
        follow_up_date: followUpDate,
        branch_name: branch?.name || "Nuestra Óptica",
        branch_phone: branch?.phone || "",
        branch_email: branch?.email || "",
      };

      const result = await sendAppointmentFollowUpReminder(
        appointmentData,
        apt.organization_id as string | undefined,
      );

      if (result.success) totalSent++;
    }

    logger.info("Appointment follow-up reminders cron completed", {
      total: appointments.length,
      sent: totalSent,
    });

    return NextResponse.json({
      success: true,
      message: "Follow-up reminders sent",
      sent: totalSent,
    });
  } catch (error) {
    logger.error("Appointment follow-up reminders cron error", { error });
    return NextResponse.json(
      {
        error: "Internal Server Error",
        details: error instanceof Error ? error.message : "Unknown error",
      },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { sendAppointmentReminder2h } from "@/lib/email/templates/optica";
import { appLogger as logger } from "@/lib/logger";
import { sendAppointmentReminderWhatsApp } from "@/lib/whatsapp/notifications-b2b";
import { createCronClient } from "@/utils/supabase/cron";

/**
 * GET /api/cron/appointment-reminders-2h
 * Triggered by Vercel Cron. Sends 2h reminder emails for appointments in ~2 hours.
 * Runs every hour. Finds appointments where date+time is approximately 2h from now.
 *
 * Requires CRON_SECRET for authorization.
 */
export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  const authHeader = request.headers.get("authorization");

  if (
    process.env.CRON_SECRET &&
    authHeader !== `Bearer ${process.env.CRON_SECRET}` &&
    request.headers.get("x-cron-secret") !== process.env.CRON_SECRET
  ) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    const supabase = createCronClient();

    const now = new Date();
    const in2h = new Date(now.getTime() + 2 * 60 * 60 * 1000);
    const targetDateStr = in2h.toISOString().split("T")[0];
    const targetHour = in2h.getHours();
    const timeStart = `${String(targetHour).padStart(2, "0")}:00:00`;
    const timeEnd = `${String(targetHour).padStart(2, "0")}:59:59`;

    const { data: appointments } = await supabase
      .from("appointments")
      .select(
        `
        id,
        appointment_date,
        appointment_time,
        status,
        customer_id,
        guest_email,
        guest_phone,
        guest_first_name,
        guest_last_name,
        branch_id,
        organization_id,
        branch:branches(id, name, organization_id),
        customer:customers(id, first_name, last_name, email, phone, preferred_contact_method)
      `,
      )
      .eq("appointment_date", targetDateStr)
      .gte("appointment_time", timeStart)
      .lte("appointment_time", timeEnd)
      .in("status", ["scheduled", "confirmed"]);

    if (!appointments || appointments.length === 0) {
      return NextResponse.json({
        success: true,
        message: "No appointments to remind (2h)",
        sent: 0,
      });
    }

    let totalSent = 0;

    for (const apt of appointments) {
      const customerEmail =
        (apt.customer as { email?: string } | null)?.email ||
        (apt as { guest_email?: string }).guest_email;

      if (!customerEmail) continue;

      const customer = apt.customer as {
        first_name?: string;
        last_name?: string;
        phone?: string;
        preferred_contact_method?: string;
      } | null;
      const guestFirst = (apt as { guest_first_name?: string })
        .guest_first_name;
      const guestLast = (apt as { guest_last_name?: string }).guest_last_name;

      const customerName = customer
        ? `${customer.first_name || ""} ${customer.last_name || ""}`.trim() ||
          "Cliente"
        : `${guestFirst || ""} ${guestLast || ""}`.trim() || "Cliente";

      const branch = apt.branch as { name?: string } | null;
      const timeStr =
        typeof apt.appointment_time === "string"
          ? apt.appointment_time.substring(0, 5)
          : apt.appointment_time;

      const appointmentData = {
        id: apt.id,
        customer_name: customerName,
        customer_first_name: customer?.first_name || guestFirst || "Cliente",
        customer_email: customerEmail,
        date: apt.appointment_date,
        time: timeStr,
        branch_name: branch?.name || "Nuestra Óptica",
      };

      const result = await sendAppointmentReminder2h(
        appointmentData,
        apt.organization_id as string | undefined,
      );

      if (result.success) totalSent++;

      const guestPhone = (apt as { guest_phone?: string }).guest_phone;
      const phone = customer?.phone || guestPhone;
      const preferWhatsApp =
        customer?.preferred_contact_method === "whatsapp" ||
        (!customerEmail && !!phone);
      if (phone && preferWhatsApp) {
        const msg = `Recordatorio: Tu cita en ${appointmentData.branch_name} es hoy a las ${appointmentData.time}. Te esperamos.`;
        const waSent = await sendAppointmentReminderWhatsApp(phone, msg);
        if (waSent) totalSent++;
      }
    }

    logger.info("Appointment reminders 2h cron completed", {
      total: appointments.length,
      sent: totalSent,
    });

    return NextResponse.json({
      success: true,
      message: "Appointment reminders (2h) sent",
      sent: totalSent,
    });
  } catch (error) {
    logger.error("Appointment reminders 2h cron error", { error });
    return NextResponse.json(
      {
        error: "Internal Server Error",
        details: error instanceof Error ? error.message : "Unknown error",
      },
      { status: 500 },
    );
  }
}

