import { NextRequest, NextResponse } from "next/server";

import { BackupService } from "@/lib/backup-service";
import { appLogger as logger } from "@/lib/logger";
import { createCronClient } from "@/utils/supabase/cron";

/**
 * GET /api/cron/backups
 * Triggered by Vercel Cron or external scheduler
 * Backs up all active organizations.
 */
export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  const authHeader = request.headers.get("authorization");

  // Basic security check - in production use CRON_SECRET
  if (
    process.env.CRON_SECRET &&
    authHeader !== `Bearer ${process.env.CRON_SECRET}` &&
    request.headers.get("x-cron-secret") !== process.env.CRON_SECRET
  ) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const supabase = createCronClient();
  const startTime = Date.now();
  const results = {
    success: 0,
    failed: 0,
    errors: [] as string[],
  };

  try {
    // Fetch all active organizations
    const { data: organizations, error: orgsError } = await supabase
      .from("organizations")
      .select("id, name, slug")
      .eq("status", "active");

    if (orgsError) {
      throw new Error(`Failed to fetch organizations: ${orgsError.message}`);
    }

    if (!organizations || organizations.length === 0) {
      return NextResponse.json({ message: "No active organizations found" });
    }

    logger.info(
      `Starting scheduled backup for ${organizations.length} organizations`,
    );

    // Process sequentially to be gentle on DB, even if slower.
    for (const org of organizations) {
      try {
        logger.info(`Backing up org: ${org.slug} (${org.id})`);

        const backupData = await BackupService.generateBackup(
          org.id,
          "system-cron",
        );
        const backupJson = JSON.stringify(backupData, null, 2);
        const backupBuffer = Buffer.from(backupJson, "utf-8");
        // Guardar en carpeta específica de la organización
        const backupFileName = `${org.id}/${backupData.backup_id}.json`;

        // Upload to Supabase Storage
        const { error: uploadError } = await supabase.storage
          .from("database-backups")
          .upload(backupFileName, backupBuffer, {
            contentType: "application/json",
            cacheControl: "3600",
            upsert: false,
          });

        if (uploadError) {
          throw new Error(uploadError.message);
        }

        results.success++;
      } catch (e: unknown) {
        logger.error(`Backup failed for org ${org.slug}`, { error: e });
        results.failed++;
        results.errors.push(`${org.slug}: ${e.message}`);
      }
    }

    const duration = (Date.now() - startTime) / 1000;

    return NextResponse.json({
      success: true,
      processed: organizations.length,
      results,
      duration_seconds: duration,
    });
  } catch (error: unknown) {
    logger.error("Cron backup job failed", { error });
    return NextResponse.json(
      { error: "Internal Server Error", details: error.message },
      { status: 500 },
    );
  }
}

/**
 * GET /api/cron/cleanup-pending-payments
 * Triggered by Vercel Cron. Marks payments with status=pending and created_at > 24h ago.
 * Sends saas_payment_failed email to org owner when applicable.
 * Requires CRON_SECRET for authorization.
 */
import { NextRequest, NextResponse } from "next/server";

import { sendSaaSPaymentFailed } from "@/lib/email/templates/saas";
import { appLogger as logger } from "@/lib/logger";
import { createCronClient } from "@/utils/supabase/cron";

export const dynamic = "force-dynamic";
export const maxDuration = 60;

export async function GET(request: NextRequest) {
  try {
    const authHeader = request.headers.get("authorization");
    if (
      process.env.CRON_SECRET &&
      authHeader !== `Bearer ${process.env.CRON_SECRET}` &&
      request.headers.get("x-cron-secret") !== process.env.CRON_SECRET
    ) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const supabase = createCronClient();
    const cutoff = new Date();
    cutoff.setHours(cutoff.getHours() - 24);
    const cutoffIso = cutoff.toISOString();

    const { data: updated, error } = await supabase
      .from("payments")
      .update({
        status: "failed",
        updated_at: new Date().toISOString(),
      })
      .eq("status", "pending")
      .lt("created_at", cutoffIso)
      .select("id, organization_id, amount, currency, created_at");

    if (error) {
      logger.error("Cleanup pending payments failed", error);
      return NextResponse.json(
        { error: "Cleanup failed", details: error.message },
        { status: 500 },
      );
    }

    let emailsSent = 0;
    if (updated && updated.length > 0 && process.env.RESEND_API_KEY) {
      for (const payment of updated) {
        try {
          const { data: org } = await supabase
            .from("organizations")
            .select("id, name, owner_id")
            .eq("id", payment.organization_id)
            .single();

          if (!org?.owner_id) continue;

          const { data: owner } = await supabase
            .from("profiles")
            .select("email")
            .eq("id", org.owner_id)
            .single();

          if (!owner?.email) continue;

          const dueDate = new Date(payment.created_at);
          dueDate.setDate(dueDate.getDate() + 1);

          const result = await sendSaaSPaymentFailed({
            organization_id: payment.organization_id,
            organization_name: org.name || "Tu organización",
            amount: payment.amount,
            currency: payment.currency || "CLP",
            invoice_number: `PAY-${String(payment.id).slice(0, 8)}`,
            invoice_date: payment.created_at.split("T")[0],
            due_date: dueDate.toLocaleDateString("es-CL"),
            status: "failed",
            payment_url: `${process.env.NEXT_PUBLIC_APP_URL}/admin/saas-management/billing`,
            admin_email: owner.email,
          });

          if (result.success) emailsSent++;
        } catch (emailErr) {
          logger.warn("Failed to send payment failed email", {
            paymentId: payment.id,
            error: emailErr,
          });
        }
      }
    }

    const count = updated?.length ?? 0;
    if (count > 0) {
      logger.info("Cleanup pending payments", {
        count,
        cutoff: cutoffIso,
        emailsSent,
      });
    }

    return NextResponse.json({
      success: true,
      expiredCount: count,
      emailsSent,
    });
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    logger.error(
      "Cleanup pending payments error",
      err instanceof Error ? err : new Error(msg),
    );
    return NextResponse.json({ error: msg }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";

import { sendDemoExpiredEmail } from "@/lib/email/templates/saas";
import { appLogger as logger } from "@/lib/logger";
import { createCronClient } from "@/utils/supabase/cron";

/**
 * GET /api/cron/demo-expired-followup
 * Triggered by Vercel Cron daily at 08:30 UTC.
 * Sends "demo expired" emails to demo_requests with funnel_stage in (approved, demo_expiring)
 * and demo_expires_at < NOW().
 * Updates funnel_stage to demo_expired and last_email_sent.
 * Requires CRON_SECRET for authorization.
 */
export const dynamic = "force-dynamic";

async function getDefaultMeetingUrl(
  supabase: ReturnType<typeof createCronClient>,
): Promise<string> {
  const { data } = await supabase
    .from("system_config")
    .select("config_value")
    .eq("config_key", "demo_funnel_meeting_url")
    .is("organization_id", null)
    .is("branch_id", null)
    .maybeSingle();
  const val = data?.config_value;
  if (typeof val === "string" && val.startsWith("http")) return val;
  return process.env.NEXT_PUBLIC_APP_URL
    ? `${process.env.NEXT_PUBLIC_APP_URL}/contacto`
    : "https://www.opttius.cl/contacto";
}

export async function GET(request: NextRequest) {
  if (
    process.env.CRON_SECRET &&
    request.headers.get("authorization") !==
      `Bearer ${process.env.CRON_SECRET}` &&
    request.headers.get("x-cron-secret") !== process.env.CRON_SECRET
  ) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    const supabase = createCronClient();
    const now = new Date().toISOString();

    const { data: requests, error } = await supabase
      .from("demo_requests")
      .select("id, email, full_name, meeting_url")
      .in("funnel_stage", ["approved", "demo_expiring"])
      .lt("demo_expires_at", now);

    if (error) {
      logger.error("Demo expired followup cron: fetch failed", { error });
      return NextResponse.json(
        { error: "Failed to fetch", details: error.message },
        { status: 500 },
      );
    }

    if (!requests || requests.length === 0) {
      return NextResponse.json({
        success: true,
        message: "No expired demos to follow up",
        sent: 0,
      });
    }

    const defaultMeetingUrl = await getDefaultMeetingUrl(supabase);
    let sent = 0;

    for (const req of requests) {
      const meetingUrl = (req.meeting_url as string) || defaultMeetingUrl;

      const result = await sendDemoExpiredEmail({
        email: req.email as string,
        fullName: (req.full_name as string) || null,
        meetingUrl,
      });

      if (result.success) {
        sent++;
        await supabase
          .from("demo_requests")
          .update({
            funnel_stage: "demo_expired",
            last_email_sent: "demo_expired",
            last_email_sent_at: new Date().toISOString(),
            last_contact_at: new Date().toISOString(),
          })
          .eq("id", req.id);
      } else {
        logger.warn("Demo expired email failed", {
          id: req.id,
          error: result.error,
        });
      }
    }

    logger.info("Demo expired followup cron completed", {
      total: requests.length,
      sent,
    });

    return NextResponse.json({
      success: true,
      message: "Demo expired followup emails sent",
      sent,
      total: requests.length,
    });
  } catch (err) {
    logger.error("Demo expired followup cron error", { error: err });
    return NextResponse.json(
      {
        error: "Internal Server Error",
        details: err instanceof Error ? err.message : "Unknown error",
      },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { sendDemoExpiringEmail } from "@/lib/email/templates/saas";
import { appLogger as logger } from "@/lib/logger";
import { createCronClient } from "@/utils/supabase/cron";

/**
 * GET /api/cron/demo-expiring
 * Triggered by Vercel Cron daily at 08:00 UTC.
 * Sends "demo expiring soon" emails to demo_requests with funnel_stage=approved
 * and demo_expires_at in the next 2 days.
 * Updates funnel_stage to demo_expiring and last_email_sent.
 * Requires CRON_SECRET for authorization.
 */
export const dynamic = "force-dynamic";

async function getDefaultMeetingUrl(
  supabase: ReturnType<typeof createCronClient>,
): Promise<string> {
  const { data } = await supabase
    .from("system_config")
    .select("config_value")
    .eq("config_key", "demo_funnel_meeting_url")
    .is("organization_id", null)
    .is("branch_id", null)
    .maybeSingle();
  const val = data?.config_value;
  if (typeof val === "string" && val.startsWith("http")) return val;
  const fallback = process.env.NEXT_PUBLIC_APP_URL
    ? `${process.env.NEXT_PUBLIC_APP_URL}/contacto`
    : "https://www.opttius.cl/contacto";
  return fallback;
}

export async function GET(request: NextRequest) {
  if (
    process.env.CRON_SECRET &&
    request.headers.get("authorization") !==
      `Bearer ${process.env.CRON_SECRET}` &&
    request.headers.get("x-cron-secret") !== process.env.CRON_SECRET
  ) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    const supabase = createCronClient();
    const now = new Date();
    const expiringEnd = new Date(now);
    expiringEnd.setDate(expiringEnd.getDate() + 2);

    const { data: requests, error } = await supabase
      .from("demo_requests")
      .select("id, email, full_name, demo_expires_at, meeting_url")
      .eq("funnel_stage", "approved")
      .gte("demo_expires_at", now.toISOString())
      .lte("demo_expires_at", expiringEnd.toISOString());

    if (error) {
      logger.error("Demo expiring cron: fetch failed", { error });
      return NextResponse.json(
        { error: "Failed to fetch", details: error.message },
        { status: 500 },
      );
    }

    if (!requests || requests.length === 0) {
      return NextResponse.json({
        success: true,
        message: "No demos expiring soon",
        sent: 0,
      });
    }

    const defaultMeetingUrl = await getDefaultMeetingUrl(supabase);
    let sent = 0;

    for (const req of requests) {
      const expiresAt = req.demo_expires_at
        ? new Date(req.demo_expires_at)
        : null;
      const daysRemaining = expiresAt
        ? Math.max(
            1,
            Math.ceil(
              (expiresAt.getTime() - now.getTime()) / (1000 * 60 * 60 * 24),
            ),
          )
        : 1;

      const meetingUrl = (req.meeting_url as string) || defaultMeetingUrl;

      const result = await sendDemoExpiringEmail({
        email: req.email as string,
        fullName: (req.full_name as string) || null,
        daysRemaining,
        meetingUrl,
      });

      if (result.success) {
        sent++;
        await supabase
          .from("demo_requests")
          .update({
            funnel_stage: "demo_expiring",
            last_email_sent: "demo_expiring",
            last_email_sent_at: new Date().toISOString(),
            last_contact_at: new Date().toISOString(),
          })
          .eq("id", req.id);
      } else {
        logger.warn("Demo expiring email failed", {
          id: req.id,
          error: result.error,
        });
      }
    }

    logger.info("Demo expiring cron completed", {
      total: requests.length,
      sent,
    });

    return NextResponse.json({
      success: true,
      message: "Demo expiring emails sent",
      sent,
      total: requests.length,
    });
  } catch (err) {
    logger.error("Demo expiring cron error", { error: err });
    return NextResponse.json(
      {
        error: "Internal Server Error",
        details: err instanceof Error ? err.message : "Unknown error",
      },
      { status: 500 },
    );
  }
}

