import { NextRequest, NextResponse } from "next/server";

import { generateInsights } from "@/lib/ai/insights/generator";
import { prepareInsightData } from "@/lib/ai/insights/prepare-data";
import type { InsightSection } from "@/lib/ai/insights/schemas";
import { createOrganizationalMemory } from "@/lib/ai/memory/organizational";
import type { BranchContext } from "@/lib/api/branch-middleware";
import { appLogger as logger } from "@/lib/logger";
import { createCronClient } from "@/utils/supabase/cron";

/**
 * GET /api/cron/generate-insights
 * Triggered by Vercel Cron. Generates AI insights for all active organizations.
 * - dashboard: daily
 * - inventory: Mondays only
 * - clients: daily
 *
 * Requires CRON_SECRET for authorization.
 */
export const dynamic = "force-dynamic";
export const maxDuration = 300; // 5 min for processing multiple orgs

export async function GET(request: NextRequest) {
  const authHeader = request.headers.get("authorization");

  if (
    process.env.CRON_SECRET &&
    authHeader !== `Bearer ${process.env.CRON_SECRET}` &&
    request.headers.get("x-cron-secret") !== process.env.CRON_SECRET
  ) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    const supabase = createCronClient();
    const searchParams = request.nextUrl.searchParams;
    const sectionParam = searchParams.get("section") as InsightSection | null;

    // Get active organizations
    const { data: organizations, error: orgError } = await supabase
      .from("organizations")
      .select("id, name, created_at")
      .eq("status", "active");

    if (orgError) {
      logger.error("Failed to fetch organizations for insights cron", {
        error: orgError,
      });
      return NextResponse.json(
        { error: "Failed to fetch organizations", details: orgError.message },
        { status: 500 },
      );
    }

    if (!organizations || organizations.length === 0) {
      return NextResponse.json({
        success: true,
        message: "No active organizations to process",
        processed: 0,
      });
    }

    const now = new Date();
    const isMonday = now.getDay() === 1;
    const yesterday = new Date(now);
    yesterday.setDate(yesterday.getDate() - 1);
    const yesterdayStr = yesterday.toISOString().split("T")[0];

    const sectionsToProcess: Array<InsightSection | "daily_summary"> =
      sectionParam
        ? [sectionParam as InsightSection]
        : [
            "daily_summary",
            "dashboard",
            "clients",
            ...(isMonday ? (["inventory"] as const) : []),
          ];

    let totalInsights = 0;
    const results: Array<{
      orgId: string;
      orgName: string;
      sections: string[];
      insightsCount: number;
      errors?: string[];
    }> = [];

    for (const org of organizations) {
      const orgErrors: string[] = [];
      let orgInsightsCount = 0;

      const globalBranchContext: BranchContext = {
        branchId: null,
        isGlobalView: true,
        isSuperAdmin: true,
        organizationId: org.id,
        accessibleBranches: [],
      };

      for (const section of sectionsToProcess) {
        try {
          const effectiveSection =
            section === "daily_summary" ? "dashboard" : section;
          const { data } = await prepareInsightData(
            supabase,
            org.id,
            org.name,
            effectiveSection,
            globalBranchContext,
          );

          const orgMemory = createOrganizationalMemory(org.id, supabase);
          const maturityLevel = await orgMemory.getMaturityLevel();

          const orgCreatedAt = new Date(org.created_at);
          const organizationAge = Math.floor(
            (now.getTime() - orgCreatedAt.getTime()) / (1000 * 60 * 60 * 24),
          );

          const { count: totalCustomers } = await supabase
            .from("customers")
            .select("*", { count: "exact", head: true })
            .eq("organization_id", org.id);

          const { count: totalProducts } = await supabase
            .from("products")
            .select("*", { count: "exact", head: true })
            .eq("organization_id", org.id);

          const { count: totalOrders } = await supabase
            .from("orders")
            .select("*", { count: "exact", head: true })
            .eq("organization_id", org.id);

          const isNewOrganization =
            organizationAge < 7 ||
            (totalOrders || 0) === 0 ||
            (totalCustomers || 0) < 5;

          const enhancedContext = {
            organizationAge,
            isNewOrganization,
            totalCustomers: totalCustomers || 0,
            totalProducts: totalProducts || 0,
            totalOrders: totalOrders || 0,
          };

          const sectionData =
            section === "daily_summary"
              ? data.dashboard
              : data[effectiveSection as keyof typeof data];
          if (!sectionData) continue;

          const insights = await generateInsights({
            section: effectiveSection,
            data: sectionData,
            organizationName: org.name,
            organizationId: org.id,
            maturityLevel,
            additionalContext: enhancedContext,
            temperature: 0.7,
            useMaturityAdaptation: section !== "daily_summary",
            supabase,
            ...(section === "daily_summary" && {
              variant: "daily_summary" as const,
              variantDate: yesterdayStr,
            }),
          });

          const insightsToInsert = insights.map((insight) => ({
            organization_id: org.id,
            section: effectiveSection,
            ...insight,
            metadata: {
              ...(insight.metadata || {}),
              ...(section === "daily_summary" && {
                type: "daily_summary",
                date: yesterdayStr,
              }),
            },
          }));

          const { error: insertError } = await supabase
            .from("ai_insights")
            .insert(insightsToInsert);

          if (insertError) {
            orgErrors.push(`${section}: ${insertError.message}`);
            logger.error("Failed to save insights", {
              orgId: org.id,
              section,
              error: insertError,
            });
          } else {
            orgInsightsCount += insights.length;
            totalInsights += insights.length;
          }

          // Small delay between LLM calls to avoid rate limits
          await new Promise((r) => setTimeout(r, 500));
        } catch (err: unknown) {
          orgErrors.push(`${section}: ${err?.message || "Unknown error"}`);
          logger.error("Insight generation failed for org/section", {
            orgId: org.id,
            section,
            error: err,
          });
        }
      }

      results.push({
        orgId: org.id,
        orgName: org.name,
        sections: sectionsToProcess,
        insightsCount: orgInsightsCount,
        ...(orgErrors.length > 0 && { errors: orgErrors }),
      });
    }

    logger.info("Insights cron completed", {
      organizationsProcessed: organizations.length,
      totalInsights,
      results,
    });

    return NextResponse.json({
      success: true,
      message: "Insight generation completed",
      processed: organizations.length,
      totalInsights,
      results,
    });
  } catch (error: unknown) {
    logger.error("Generate insights cron error", { error });
    return NextResponse.json(
      {
        error: "Internal Server Error",
        details: error instanceof Error ? error.message : "Unknown error",
      },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { sendLowStockAlert } from "@/lib/email/notifications";
import { appLogger as logger } from "@/lib/logger";
import { sendLowStockAlertWhatsApp } from "@/lib/whatsapp/notifications-b2b";
import { createCronClient } from "@/utils/supabase/cron";

/**
 * GET /api/cron/low-stock-alerts
 * Triggered by Vercel Cron. Sends low stock alert emails to org admins/owners.
 * Runs daily at 7:00 UTC.
 *
 * Requires CRON_SECRET for authorization.
 */
export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  const authHeader = request.headers.get("authorization");

  if (
    process.env.CRON_SECRET &&
    authHeader !== `Bearer ${process.env.CRON_SECRET}` &&
    request.headers.get("x-cron-secret") !== process.env.CRON_SECRET
  ) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    const supabase = createCronClient();

    const { data: orgs } = await supabase
      .from("organizations")
      .select("id, owner_id, metadata")
      .eq("status", "active");

    if (!orgs || orgs.length === 0) {
      return NextResponse.json({
        success: true,
        message: "No organizations to process",
        sent: 0,
      });
    }

    let totalSent = 0;

    for (const org of orgs) {
      const { data: orgConfig } = await supabase
        .from("system_config")
        .select("config_value")
        .eq("config_key", "auto_low_stock_alerts")
        .eq("organization_id", org.id)
        .maybeSingle();

      const { data: globalConfig } = await supabase
        .from("system_config")
        .select("config_value")
        .eq("config_key", "auto_low_stock_alerts")
        .is("organization_id", null)
        .maybeSingle();

      const configValue = orgConfig?.config_value ?? globalConfig?.config_value;
      const autoAlerts =
        configValue === false || configValue === "false" ? false : true;
      if (!autoAlerts) continue;

      const { data: branches } = await supabase
        .from("branches")
        .select("id")
        .eq("organization_id", org.id);

      const branchIds = (branches || []).map((b) => b.id);
      if (branchIds.length === 0) continue;

      const { data: stockRows } = await supabase
        .from("product_branch_stock")
        .select("product_id, branch_id, quantity, low_stock_threshold")
        .in("branch_id", branchIds);

      const lowStock = (stockRows || []).filter(
        (r: {
          quantity: number;
          low_stock_threshold: number | null;
          product_id: string;
        }) => {
          const qty = r.quantity ?? 0;
          const threshold = r.low_stock_threshold ?? 5;
          return qty <= threshold && qty >= 0;
        },
      );

      if (lowStock.length === 0) continue;

      const productIds = [...new Set(lowStock.map((r) => r.product_id))];
      const { data: productsData } = await supabase
        .from("products")
        .select("id, name")
        .in("id", productIds);

      const productMap = new Map(
        (productsData || []).map((p) => [p.id, p.name]),
      );

      const products = lowStock.map(
        (r: {
          quantity: number;
          low_stock_threshold: number | null;
          product_id: string;
        }) => ({
          name: productMap.get(r.product_id) || "Producto",
          current_stock: r.quantity ?? 0,
          min_stock: r.low_stock_threshold ?? 5,
        }),
      );

      // Prefer optica email (contact_email or support_email) over admin emails
      let recipientEmails: string[] = [];

      const { data: contactConfig } = await supabase
        .from("system_config")
        .select("config_value")
        .eq("config_key", "contact_email")
        .eq("organization_id", org.id)
        .maybeSingle();

      const { data: globalContactConfig } = contactConfig
        ? { data: null }
        : await supabase
            .from("system_config")
            .select("config_value")
            .eq("config_key", "contact_email")
            .is("organization_id", null)
            .maybeSingle();

      const contactEmailRow = contactConfig ?? globalContactConfig;
      const contactEmail =
        contactEmailRow?.config_value != null
          ? typeof contactEmailRow.config_value === "string"
            ? contactEmailRow.config_value
            : String(contactEmailRow.config_value)
          : "";

      const meta = (org.metadata as Record<string, unknown>) || {};
      const supportEmail = (meta.support_email as string) || "";

      const opticaEmail = (contactEmail || supportEmail || "").trim();
      if (opticaEmail) {
        recipientEmails = [opticaEmail];
      } else {
        const { data: admins } = await supabase
          .from("admin_users")
          .select("id")
          .eq("organization_id", org.id)
          .eq("is_active", true)
          .in("role", ["admin", "super_admin"]);

        const adminIds = (admins || []).map((a) => a.id);
        if (org.owner_id && !adminIds.includes(org.owner_id)) {
          adminIds.push(org.owner_id);
        }

        if (adminIds.length === 0) continue;

        const { data: profiles } = await supabase
          .from("profiles")
          .select("email")
          .in("id", adminIds);

        recipientEmails = (profiles || [])
          .map((p) => p.email)
          .filter((e): e is string => !!e);
      }

      if (recipientEmails.length === 0) continue;

      const result = await sendLowStockAlert(
        recipientEmails,
        products,
        org.id,
      );

      if (result.success) totalSent++;

      const whatsappSent = await sendLowStockAlertWhatsApp(
        org.id,
        products,
        supabase,
      );
      if (whatsappSent) totalSent++;
    }

    logger.info("Low stock alerts cron completed", { totalSent });

    return NextResponse.json({
      success: true,
      message: "Low stock alerts sent",
      sent: totalSent,
    });
  } catch (error) {
    logger.error("Low stock alerts cron error", { error });
    return NextResponse.json(
      {
        error: "Internal Server Error",
        details: error instanceof Error ? error.message : "Unknown error",
      },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { sendPrescriptionExpiring } from "@/lib/email/templates/optica";
import { appLogger as logger } from "@/lib/logger";
import { createCronClient } from "@/utils/supabase/cron";

/**
 * GET /api/cron/prescription-expiring
 * Triggered by Vercel Cron. Sends prescription expiring emails for prescriptions
 * where expiration_date is in 30 days. Uses each prescription's specific expiration_date.
 * Runs daily at 6:00 UTC.
 *
 * Requires CRON_SECRET for authorization.
 */
export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  const authHeader = request.headers.get("authorization");

  if (
    process.env.CRON_SECRET &&
    authHeader !== `Bearer ${process.env.CRON_SECRET}` &&
    request.headers.get("x-cron-secret") !== process.env.CRON_SECRET
  ) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    const supabase = createCronClient();

    const in30Days = new Date();
    in30Days.setDate(in30Days.getDate() + 30);
    const targetDateStr = in30Days.toISOString().split("T")[0];

    const { data: prescriptions } = await supabase
      .from("prescriptions")
      .select(
        `
        id,
        prescription_number,
        prescription_date,
        expiration_date,
        customer_id,
        organization_id,
        branch_id,
        customer:customers(id, first_name, last_name, email),
        branch:branches(name, phone, email, address_line_1)
      `,
      )
      .eq("expiration_date", targetDateStr)
      .eq("is_active", true);

    if (!prescriptions || prescriptions.length === 0) {
      return NextResponse.json({
        success: true,
        message: "No prescriptions expiring soon",
        sent: 0,
      });
    }

    let totalSent = 0;

    for (const rx of prescriptions) {
      const customer = rx.customer as {
        first_name?: string;
        last_name?: string;
        email?: string;
      } | null;

      const customerEmail = customer?.email;
      if (!customerEmail) continue;

      const customerName =
        `${customer?.first_name || ""} ${customer?.last_name || ""}`.trim() ||
        "Cliente";

      const branch = rx.branch as {
        name?: string;
        phone?: string;
        email?: string;
        address_line_1?: string;
      } | null;

      const expiryDateStr =
        typeof rx.expiration_date === "string"
          ? rx.expiration_date
          : rx.expiration_date?.toISOString?.()?.split("T")[0] || "";
      const prescriptionDateStr =
        typeof rx.prescription_date === "string"
          ? rx.prescription_date
          : rx.prescription_date?.toISOString?.()?.split("T")[0] || "";

      const prescriptionData = {
        id: rx.id,
        customer_name: customerName,
        customer_first_name: customer?.first_name || "Cliente",
        customer_email: customerEmail,
        prescription_number:
          rx.prescription_number || `REC-${String(rx.id).slice(0, 8)}`,
        date: prescriptionDateStr,
        expiry_date: expiryDateStr,
        branch_name: branch?.name || "Nuestra Óptica",
        branch_address: branch?.address_line_1 || "",
        branch_phone: branch?.phone || "",
        branch_email: branch?.email || "",
      };

      const result = await sendPrescriptionExpiring(
        prescriptionData,
        rx.organization_id as string | undefined,
      );

      if (result.success) totalSent++;
    }

    logger.info("Prescription expiring cron completed", {
      total: prescriptions.length,
      sent: totalSent,
    });

    return NextResponse.json({
      success: true,
      message: "Prescription expiring emails sent",
      sent: totalSent,
    });
  } catch (error) {
    logger.error("Prescription expiring cron error", { error });
    return NextResponse.json(
      {
        error: "Internal Server Error",
        details: error instanceof Error ? error.message : "Unknown error",
      },
      { status: 500 },
    );
  }
}

