}

import { NextRequest, NextResponse } from "next/server";

import { sendSaaSPaymentReminder } from "@/lib/email/templates/saas";
import { appLogger as logger } from "@/lib/logger";
import { createCronClient } from "@/utils/supabase/cron";

/**
 * GET /api/cron/saas-payment-reminder
 * Triggered by Vercel Cron. Sends payment reminder emails for subscriptions
 * with status past_due. Runs daily at 7:00 UTC.
 *
 * Requires CRON_SECRET for authorization.
 */
export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  const authHeader = request.headers.get("authorization");

  if (
    process.env.CRON_SECRET &&
    authHeader !== `Bearer ${process.env.CRON_SECRET}` &&
    request.headers.get("x-cron-secret") !== process.env.CRON_SECRET
  ) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  if (!process.env.RESEND_API_KEY) {
    return NextResponse.json({
      success: true,
      message: "Resend not configured",
      sent: 0,
    });
  }

  try {
    const supabase = createCronClient();

    const { data: subscriptions, error: subError } = await supabase
      .from("subscriptions")
      .select("id, organization_id, current_period_end, current_period_start")
      .eq("status", "past_due");

    if (subError || !subscriptions || subscriptions.length === 0) {
      return NextResponse.json({
        success: true,
        message: "No past_due subscriptions",
        sent: 0,
      });
    }

    let totalSent = 0;

    for (const sub of subscriptions) {
      try {
        const { data: org } = await supabase
          .from("organizations")
          .select("id, name, owner_id")
          .eq("id", sub.organization_id)
          .single();

        if (!org?.owner_id) continue;

        const { data: owner } = await supabase
          .from("profiles")
          .select("email")
          .eq("id", org.owner_id)
          .single();

        if (!owner?.email) continue;

        const dueDate = sub.current_period_end
          ? new Date(sub.current_period_end)
          : new Date();

        const result = await sendSaaSPaymentReminder({
          organization_id: sub.organization_id,
          organization_name: org.name || "Tu organización",
          amount: 0,
          currency: "CLP",
          invoice_number: "",
          invoice_date: sub.current_period_start?.split("T")[0] || "",
          due_date: dueDate.toLocaleDateString("es-CL"),
          status: "pending",
          payment_url: `${process.env.NEXT_PUBLIC_APP_URL}/admin/saas-management/billing`,
          admin_email: owner.email,
        });

        if (result.success) totalSent++;
      } catch (emailErr) {
        logger.warn("Failed to send payment reminder", {
          subscriptionId: sub.id,
          error: emailErr,
        });
      }
    }

    logger.info("SaaS payment reminder cron completed", {
      total: subscriptions.length,
      sent: totalSent,
    });

    return NextResponse.json({
      success: true,
      message: "Payment reminder emails sent",
      sent: totalSent,
    });
  } catch (error) {
    logger.error("SaaS payment reminder cron error", { error });
    return NextResponse.json(
      {
        error: "Internal Server Error",
        details: error instanceof Error ? error.message : "Unknown error",
      },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { sendSaaSTrialEnding } from "@/lib/email/templates/saas";
import { appLogger as logger } from "@/lib/logger";
import { createCronClient } from "@/utils/supabase/cron";

const DAYS_BEFORE = parseInt(
  process.env.SAAS_TRIAL_ENDING_DAYS_BEFORE || "3",
  10,
);

/**
 * GET /api/cron/saas-trial-ending
 * Triggered by Vercel Cron. Sends trial ending emails for subscriptions
 * expiring in the next N days (configurable via SAAS_TRIAL_ENDING_DAYS_BEFORE).
 * Runs daily at 6:30 UTC.
 *
 * Requires CRON_SECRET for authorization.
 */
export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  const authHeader = request.headers.get("authorization");

  if (
    process.env.CRON_SECRET &&
    authHeader !== `Bearer ${process.env.CRON_SECRET}` &&
    request.headers.get("x-cron-secret") !== process.env.CRON_SECRET
  ) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    const supabase = createCronClient();

    const now = new Date();
    const todayStart = new Date(
      now.getFullYear(),
      now.getMonth(),
      now.getDate(),
    );
    const futureEnd = new Date(todayStart);
    futureEnd.setDate(futureEnd.getDate() + DAYS_BEFORE);

    const todayStr = todayStart.toISOString().split("T")[0];
    const futureStr = futureEnd.toISOString().split("T")[0];

    const { data: subscriptions, error: subError } = await supabase
      .from("subscriptions")
      .select(
        `
        id,
        organization_id,
        trial_ends_at,
        current_period_start,
        current_period_end
      `,
      )
      .eq("status", "trialing")
      .not("trial_ends_at", "is", null)
      .gte("trial_ends_at", todayStr)
      .lte("trial_ends_at", futureStr);

    if (subError) {
      logger.error("Error fetching trialing subscriptions", subError);
      return NextResponse.json(
        { error: "Failed to fetch subscriptions" },
        { status: 500 },
      );
    }

    if (!subscriptions || subscriptions.length === 0) {
      return NextResponse.json({
        success: true,
        message: "No trials ending soon",
        sent: 0,
      });
    }

    let totalSent = 0;

    for (const sub of subscriptions) {
      const trialEndsAt = sub.trial_ends_at;
      if (!trialEndsAt) continue;

      const { data: org } = await supabase
        .from("organizations")
        .select("id, name, owner_id")
        .eq("id", sub.organization_id)
        .single();

      if (!org?.owner_id) {
        logger.warn("Organization has no owner, skipping trial ending email", {
          organizationId: sub.organization_id,
        });
        continue;
      }

      const { data: owner } = await supabase
        .from("profiles")
        .select("email, first_name")
        .eq("id", org.owner_id)
        .single();

      const adminEmail = owner?.email;
      if (!adminEmail) {
        logger.warn("Owner has no email, skipping trial ending email", {
          organizationId: sub.organization_id,
        });
        continue;
      }

      const trialEndDate = new Date(trialEndsAt);
      const daysRemaining = Math.ceil(
        (trialEndDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24),
      );

      const trialData = {
        organization_id: sub.organization_id,
        organization_name: org.name || "Tu organización",
        trial_start_date:
          sub.current_period_start?.split("T")[0] ||
          trialEndDate.toISOString().split("T")[0],
        trial_end_date: trialEndDate.toLocaleDateString("es-CL", {
          year: "numeric",
          month: "long",
          day: "numeric",
        }),
        days_remaining: Math.max(0, daysRemaining),
        plan_name: "Trial",
        admin_email: adminEmail,
      };

      const result = await sendSaaSTrialEnding(trialData);

      if (result.success) {
        totalSent++;
      } else {
        logger.warn("Failed to send trial ending email", {
          organizationId: sub.organization_id,
          error: result.error,
        });
      }
    }

    logger.info("SaaS trial ending cron completed", {
      total: subscriptions.length,
      sent: totalSent,
      daysBefore: DAYS_BEFORE,
    });

    return NextResponse.json({
      success: true,
      message: "Trial ending emails sent",
      sent: totalSent,
    });
  } catch (error) {
    logger.error("SaaS trial ending cron error", { error });
    return NextResponse.json(
      {
        error: "Internal Server Error",
        details: error instanceof Error ? error.message : "Unknown error",
      },
      { status: 500 },
    );
  }
}

/**
 * GET /api/landing/tiers
 * Public endpoint: returns subscription tiers (name, price, limits) for the landing pricing section.
 * Values are the same as in Gestión SaaS Opttius so the landing always reflects current pricing.
 * Uses service role when available; falls back to anon (RLS allows public read via policy).
 */
import { createClient } from "@supabase/supabase-js";
import { NextResponse } from "next/server";

export const dynamic = "force-dynamic";
export const revalidate = 0;

function getSupabaseClient() {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
  const serviceKey = process.env.SUPABASE_SERVICE_ROLE_KEY;
  const anonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;
  if (!url) return null;
  const key = serviceKey || anonKey;
  if (!key) return null;
  return createClient(url, key, {
    auth: { autoRefreshToken: false, persistSession: false },
  });
}

export async function GET() {
  try {
    const supabase = getSupabaseClient();
    if (!supabase) {
      return NextResponse.json(
        { error: "Database not configured", tiers: [] },
        { status: 503, headers: { "Cache-Control": "no-store" } },
      );
    }

    const { data: tiers, error } = await supabase
      .from("subscription_tiers")
      .select(
        "name, price_monthly, max_branches, max_users, max_customers, max_products, features",
      )
      .order("price_monthly", { ascending: true });

    if (error) {
      return NextResponse.json(
        { error: "Error al cargar planes", details: error.message },
        { status: 500 },
      );
    }

    let trialDays = 7;
    const trialRes = await supabase
      .from("system_config")
      .select("config_value")
      .eq("config_key", "membership_trial_days")
      .is("organization_id", null)
      .is("branch_id", null)
      .maybeSingle();
    if (!trialRes.error && trialRes.data?.config_value != null) {
      const parsed = parseInt(
        String(trialRes.data.config_value).replace(/"/g, ""),
        10,
      );
      if (!isNaN(parsed) && parsed > 0) trialDays = parsed;
    }

    return NextResponse.json(
      { tiers: tiers || [], trial_days: trialDays },
      {
        headers: {
          "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0",
        },
      },
    );
  } catch (err) {
    return NextResponse.json(
      { error: "Error al cargar planes" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { activateRealOrgSchema } from "@/lib/api/validation/organization-schemas";
import {
  parseAndValidateBody,
  ValidationError,
  validationErrorResponse,
} from "@/lib/api/validation/zod-helpers";
import { appLogger as logger } from "@/lib/logger";
import { createRootAdminClient } from "@/utils/supabase/root-admin";
import { createClient } from "@/utils/supabase/server";

const DEMO_ORG_ID =
  process.env.NEXT_PUBLIC_DEMO_ORG_ID || "00000000-0000-0000-0000-000000000001";

/**
 * POST /api/onboarding/activate-real-org
 *
 * Activa la organización real del usuario desde modo demo.
 * Crea la nueva organización y cambia el organization_id del usuario.
 *
 * Body:
 * - name: string (requerido) - Nombre de la organización
 * - slug: string (requerido) - Identificador único URL-friendly
 * - branchName: string (opcional) - Nombre de la primera sucursal
 *
 * Returns:
 * - { organization: {...}, branch: {...} }
 */
export const dynamic = "force-dynamic";
export async function POST(request: NextRequest) {
  try {
    const supabase = await createClient();
    const supabaseServiceRole = createRootAdminClient();

    // Verificar autenticación
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user || !user.email) {
      return NextResponse.json({ error: "No autenticado" }, { status: 401 });
    }

    // Validar body
    let validatedBody;
    try {
      validatedBody = await parseAndValidateBody(
        request,
        activateRealOrgSchema,
      );
    } catch (error) {
      if (error instanceof ValidationError) {
        return validationErrorResponse(error);
      }
      throw error;
    }

    const { name, slug, branchName } = validatedBody;

    const { data: currentAdminUser } = await supabaseServiceRole
      .from("admin_users")
      .select("organization_id")
      .eq("id", user.id)
      .single();

    const currentOrgId = currentAdminUser?.organization_id;
    if (!currentOrgId) {
      return NextResponse.json(
        { error: "Solo puedes activar tu organización real desde modo demo" },
        { status: 400 },
      );
    }

    if (currentOrgId !== DEMO_ORG_ID) {
      const { data: org } = await supabaseServiceRole
        .from("organizations")
        .select("metadata")
        .eq("id", currentOrgId)
        .single();
      const meta = org?.metadata as Record<string, unknown> | null;
      if (meta?.demo_type === "organic") {
        return NextResponse.json(
          {
            error:
              "La activación de tu óptica debe gestionarse a través de soporte.",
          },
          { status: 403 },
        );
      }
      if (meta?.is_demo !== true) {
        return NextResponse.json(
          { error: "Solo puedes activar tu organización real desde modo demo" },
          { status: 400 },
        );
      }
    }

    // Verificar que el slug no exista
    const { data: existingOrg } = await supabaseServiceRole
      .from("organizations")
      .select("id")
      .eq("slug", slug)
      .single();

    if (existingOrg) {
      return NextResponse.json(
        { error: "Ese identificador ya está en uso. Elige otro." },
        { status: 400 },
      );
    }

    // Crear nueva organización
    const { data: newOrganization, error: orgError } = await supabaseServiceRole
      .from("organizations")
      .insert({
        name,
        slug,
        owner_id: user.id,
        subscription_tier: "pro", // Default tier for trial period (7 days)
        status: "active",
      })
      .select()
      .single();

    if (orgError || !newOrganization) {
      logger.error("Error creating organization", orgError);
      return NextResponse.json(
        { error: "Error al crear la organización", details: orgError?.message },
        { status: 500 },
      );
    }

    const organizationId = newOrganization.id;

    // Actualizar admin_users con la nueva organization_id y rol super_admin
    // El usuario que activa su organización real es el dueño de la óptica, por lo tanto debe ser super_admin
    const { data: adminUser, error: adminError } = await supabaseServiceRole
      .from("admin_users")
      .update({
        organization_id: organizationId,
        role: "super_admin",
        updated_at: new Date().toISOString(),
      })
      .eq("id", user.id)
      .select()
      .single();

    if (adminError || !adminUser) {
      logger.error("Error updating admin_users", adminError);
      // Rollback: eliminar organización creada
      await supabaseServiceRole
        .from("organizations")
        .delete()
        .eq("id", organizationId);
      return NextResponse.json(
        {
          error: "Error al actualizar organización del usuario",
          details: adminError?.message,
        },
        { status: 500 },
      );
    }

    // Super admin: acceso global (branch_id null) para ver todas las sucursales de la nueva org
    await supabaseServiceRole
      .from("admin_branch_access")
      .delete()
      .eq("admin_user_id", user.id);
    await supabaseServiceRole.from("admin_branch_access").insert({
      admin_user_id: user.id,
      branch_id: null,
      role: "manager",
      is_primary: true,
    });

    // Crear primera sucursal (siempre se crea una, por defecto "Sucursal Principal")
    const finalBranchName = branchName || "Sucursal Principal";
    const branchCode = `${slug.toUpperCase().substring(0, 8)}-001`;

    const { data: newBranch, error: branchError } = await supabaseServiceRole
      .from("branches")
      .insert({
        name: finalBranchName,
        code: branchCode,
        organization_id: organizationId,
        is_active: true,
      })
      .select()
      .single();

    let branch = null;
    if (branchError || !newBranch) {
      logger.error("Error creating branch", branchError);
    } else {
      branch = newBranch;
    }

    // ===== LIMPIAR DATOS CREADOS POR EL USUARIO DURANTE EL DEMO =====
    // Eliminar cualquier dato que el usuario haya creado durante el demo
    // Esto asegura que la demo sea completamente temporal y no queden datos residuales
    // IMPORTANTE: Solo eliminamos datos creados por este usuario, NO los datos seed de la demo

    logger.info("Cleaning up demo data created by user", { userId: user.id });

    // Obtener todas las sucursales de la demo para filtrar por branch_id también
    const { data: demoBranches } = await supabaseServiceRole
      .from("branches")
      .select("id")
      .eq("organization_id", currentOrgId);

    const demoBranchIds = demoBranches?.map((b) => b.id) || [];

    // Eliminar datos creados por el usuario en la demo (solo los que creó él, no los datos seed)
    // Usamos created_by cuando está disponible para identificar datos del usuario

    // 1. Clientes creados por el usuario en la demo
    if (demoBranchIds.length > 0) {
      await supabaseServiceRole
        .from("customers")
        .delete()
        .eq("organization_id", currentOrgId)
        .in("branch_id", demoBranchIds)
        .eq("created_by", user.id);
    }

    // 2. Órdenes creadas por el usuario en la demo (a través de order_payments.created_by)
    if (demoBranchIds.length > 0) {
      // Primero obtener IDs de órdenes con pagos creados por el usuario
      const { data: userOrderPayments } = await supabaseServiceRole
        .from("order_payments")
        .select("order_id")
        .eq("created_by", user.id);

      const userOrderIds =
        userOrderPayments?.map((p: unknown) => p.order_id) || [];

      if (userOrderIds.length > 0) {
        await supabaseServiceRole
          .from("orders")
          .delete()
          .eq("organization_id", currentOrgId)
          .in("id", userOrderIds);
      }
    }

    // 3. Presupuestos creados por el usuario en la demo
    if (demoBranchIds.length > 0) {
      await supabaseServiceRole
        .from("quotes")
        .delete()
        .eq("organization_id", currentOrgId)
        .in("branch_id", demoBranchIds);
      // Nota: quotes puede no tener created_by, así que eliminamos todos los de la demo del usuario
      // Esto es seguro porque cuando el usuario cambia de organización, ya no los verá de todas formas
    }

    // 4. Trabajos de laboratorio creados por el usuario en la demo
    if (demoBranchIds.length > 0) {
      await supabaseServiceRole
        .from("lab_work_orders")
        .delete()
        .eq("organization_id", currentOrgId)
        .in("branch_id", demoBranchIds)
        .eq("created_by", user.id);
    }

    // 5. Citas creadas por el usuario en la demo
    if (demoBranchIds.length > 0) {
      await supabaseServiceRole
        .from("appointments")
        .delete()
        .eq("organization_id", currentOrgId)
        .in("branch_id", demoBranchIds);
    }

    // 6. Pagos creados por el usuario en la demo
    await supabaseServiceRole
      .from("payments")
      .delete()
      .eq("organization_id", currentOrgId)
      .eq("user_id", user.id);

    // 7. Pagos de órdenes creados por el usuario en la demo
    await supabaseServiceRole
      .from("order_payments")
      .delete()
      .eq("created_by", user.id);

    // 8. Documentos de facturación creados por el usuario en la demo
    if (demoBranchIds.length > 0) {
      await supabaseServiceRole
        .from("billing_documents")
        .delete()
        .in("branch_id", demoBranchIds)
        .eq("emitted_by", user.id);
    }

    // 9. Sesiones POS creadas por el usuario en la demo
    if (demoBranchIds.length > 0) {
      await supabaseServiceRole
        .from("pos_sessions")
        .delete()
        .in("branch_id", demoBranchIds)
        .eq("cashier_id", user.id);
    }

    // 10. Transacciones POS creadas por el usuario en la demo
    if (demoBranchIds.length > 0) {
      await supabaseServiceRole
        .from("pos_transactions")
        .delete()
        .in("branch_id", demoBranchIds)
        .eq("cashier_id", user.id);
    }

    // 11. Cierres de caja creados por el usuario en la demo
    if (demoBranchIds.length > 0) {
      await supabaseServiceRole
        .from("cash_register_sessions")
        .delete()
        .in("branch_id", demoBranchIds)
        .eq("cashier_id", user.id);
    }

    // 12. Recetas creadas por el usuario en la demo
    if (demoBranchIds.length > 0) {
      await supabaseServiceRole
        .from("prescriptions")
        .delete()
        .in("branch_id", demoBranchIds)
        .eq("created_by", user.id);
    }

    // 13. Notificaciones admin creadas para el usuario en la demo
    await supabaseServiceRole
      .from("admin_notifications")
      .delete()
      .eq("target_admin_id", user.id);

    // 14. Logs de actividad del usuario (todos, no solo de la demo)
    // Esto limpia el historial completo del usuario antes de empezar con su organización real
    await supabaseServiceRole
      .from("admin_activity_log")
      .delete()
      .eq("admin_user_id", user.id);

    // 15. Progreso del tour del usuario en la demo
    await supabaseServiceRole
      .from("user_tour_progress")
      .delete()
      .eq("user_id", user.id)
      .eq("organization_id", currentOrgId);

    // 16. Historial de chat del usuario en la demo
    await supabaseServiceRole
      .from("chat_sessions")
      .delete()
      .eq("user_id", user.id);

    logger.info("Demo data cleanup completed", {
      userId: user.id,
      demoBranchesCleaned: demoBranchIds.length,
    });

    // Crear acceso de super_admin (branch_id = null) para acceso global a todas las sucursales
    // Primero eliminar cualquier acceso existente (esto ya limpia los accesos a la demo)
    await supabaseServiceRole
      .from("admin_branch_access")
      .delete()
      .eq("admin_user_id", user.id);

    // Crear acceso de super_admin con branch_id = null
    const { error: accessError } = await supabaseServiceRole
      .from("admin_branch_access")
      .insert({
        admin_user_id: user.id,
        branch_id: null, // null = acceso global a todas las sucursales (super_admin)
        role: "manager",
        is_primary: true,
      });

    if (accessError) {
      logger.error("Error creating super admin branch access", accessError);
      // Crítico: el usuario podría no tener acceso global
    }

    // Crear subscription inicial con periodo de prueba de 7 días
    const trialEndsAt = new Date();
    trialEndsAt.setDate(trialEndsAt.getDate() + 7);

    const { error: subscriptionError } = await supabaseServiceRole
      .from("subscriptions")
      .insert({
        organization_id: organizationId,
        status: "trialing",
        trial_ends_at: trialEndsAt.toISOString(),
      });

    if (subscriptionError) {
      logger.warn(
        "Error creating subscription (non-critical)",
        subscriptionError,
      );
    }

    logger.info("Real organization activated successfully", {
      organizationId,
      userId: user.id,
      slug,
    });

    return NextResponse.json({
      organization: {
        id: newOrganization.id,
        name: newOrganization.name,
        slug: newOrganization.slug,
        subscription_tier: newOrganization.subscription_tier,
      },
      branch: branch
        ? {
            id: branch.id,
            name: branch.name,
            code: branch.code,
          }
        : null,
    });
  } catch (error) {
    logger.error("Error in POST /api/onboarding/activate-real-org", error);
    return NextResponse.json(
      {
        error: "Error interno del servidor",
        details: error instanceof Error ? error.message : "Unknown error",
      },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import { createRootAdminClient } from "@/utils/supabase/root-admin";
import { createClient } from "@/utils/supabase/server";

const DEMO_ORG_ID =
  process.env.NEXT_PUBLIC_DEMO_ORG_ID || "00000000-0000-0000-0000-000000000001";

/**
 * POST /api/onboarding/assign-demo
 *
 * Crea una organización demo dedicada (7 días) para el usuario (flujo ópticas conocidas).
 * Clona estructura Mirada Clara. Banner y botón activar visibles.
 *
 * Returns:
 * - { success: boolean, organizationId: string }
 */
export const dynamic = "force-dynamic";
export async function POST(request: NextRequest) {
  try {
    const supabase = await createClient();
    const supabaseServiceRole = createRootAdminClient();

    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user || !user.email) {
      return NextResponse.json({ error: "No autenticado" }, { status: 401 });
    }

    const { data: existingAdminUser, error: adminUserError } =
      await supabaseServiceRole
        .from("admin_users")
        .select("organization_id")
        .eq("id", user.id)
        .maybeSingle();

    if (adminUserError && adminUserError.code !== "PGRST116") {
      logger.warn("Error checking existing admin user", adminUserError);
    }

    if (existingAdminUser?.organization_id) {
      const orgId = existingAdminUser.organization_id;

      if (orgId !== DEMO_ORG_ID) {
        const { data: org } = await supabaseServiceRole
          .from("organizations")
          .select("metadata")
          .eq("id", orgId)
          .single();

        const meta = org?.metadata as Record<string, unknown> | null;
        const isOwnDemo =
          meta?.owner_user_id === user.id && meta?.is_demo === true;

        if (isOwnDemo) {
          return NextResponse.json({
            success: true,
            organizationId: orgId,
            alreadyAssigned: true,
          });
        }

        return NextResponse.json(
          {
            error: "Ya tienes una organización asignada",
            organizationId: orgId,
          },
          { status: 400 },
        );
      }
    }

    const { data: newOrgId, error: rpcError } = await supabaseServiceRole.rpc(
      "create_demo_organization_for_user",
      { p_user_id: user.id, p_demo_type: "known_optica" },
    );

    if (rpcError) {
      logger.error("Error creating demo organization", {
        error: rpcError,
        userId: user.id,
      });
      return NextResponse.json(
        {
          error: "Error al crear organización demo",
          details: rpcError.message,
        },
        { status: 500 },
      );
    }

    const { data: demoOrg } = await supabaseServiceRole
      .from("organizations")
      .select("id, name")
      .eq("id", newOrgId)
      .single();

    logger.info("Demo organization created and assigned", {
      userId: user.id,
      organizationId: newOrgId,
    });

    return NextResponse.json({
      success: true,
      organizationId: newOrgId,
      organization: {
        id: demoOrg?.id ?? newOrgId,
        name: demoOrg?.name ?? "Óptica Demo",
      },
    });
  } catch (error) {
    logger.error("Error in POST /api/onboarding/assign-demo", error);
    return NextResponse.json(
      {
        error: "Error interno del servidor",
        details: error instanceof Error ? error.message : "Unknown error",
      },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import { createRootAdminClient } from "@/utils/supabase/root-admin";
import { createClient } from "@/utils/supabase/server";

/**
 * POST /api/onboarding/ensure-admin-user
 *
 * Asegura que el usuario actual tenga un registro en admin_users.
 * Si no existe, lo crea con role 'store_manager'.
 * Esto permite que usuarios nuevos puedan acceder al onboarding.
 */
export const dynamic = "force-dynamic";
export async function POST(request: NextRequest) {
  try {
    const supabase = await createClient();
    const supabaseServiceRole = createRootAdminClient();

    // Verificar autenticación
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user || !user.email) {
      return NextResponse.json({ error: "No autenticado" }, { status: 401 });
    }

    // Verificar si ya existe en admin_users
    const { data: existingAdminUser, error: checkError } =
      await supabaseServiceRole
        .from("admin_users")
        .select("id, role, organization_id")
        .eq("id", user.id)
        .maybeSingle();

    if (checkError && checkError.code !== "PGRST116") {
      logger.error("Error checking admin_users", checkError);
      return NextResponse.json(
        {
          error: "Error al verificar usuario admin",
          details: checkError?.message,
        },
        { status: 500 },
      );
    }

    // Si ya existe, retornar éxito
    if (existingAdminUser) {
      return NextResponse.json({
        success: true,
        adminUser: existingAdminUser,
        created: false,
      });
    }

    // Crear registro en admin_users
    // Nota: Después de la migración 20250210000001, el rol debe ser 'admin' (simplificado)
    const { data: newAdminUser, error: createError } = await supabaseServiceRole
      .from("admin_users")
      .insert({
        id: user.id,
        email: user.email,
        role: "admin", // Sistema simplificado usa solo 'admin'
        is_active: true,
        permissions: {
          orders: ["read", "create", "update", "delete"],
          products: ["read", "create", "update", "delete"],
          customers: ["read", "create", "update", "delete"],
          analytics: ["read"],
          settings: ["read", "create", "update", "delete"],
          admin_users: ["read", "create", "update", "delete"],
          support: ["read", "create", "update", "delete"],
          bulk_operations: ["read", "create", "update", "delete"],
        },
      })
      .select()
      .single();

    if (createError || !newAdminUser) {
      logger.error("Error creating admin_users record", createError);
      return NextResponse.json(
        {
          error: "Error al crear registro de usuario admin",
          details: createError?.message,
        },
        { status: 500 },
      );
    }

    logger.info("Admin user record created", {
      userId: user.id,
      email: user.email,
    });

    return NextResponse.json({
      success: true,
      adminUser: newAdminUser,
      created: true,
    });
  } catch (error) {
    logger.error("Error in POST /api/onboarding/ensure-admin-user", error);
    return NextResponse.json(
      {
        error: "Error interno del servidor",
        details: error instanceof Error ? error.message : "Unknown error",
      },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import { createClientFromRequest } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";
export async function POST(
  request: NextRequest,
  { params }: { params: { step: string } },
) {
  try {
    const { getUser } = await createClientFromRequest(request);
    const { data: userData, error: userError } = await getUser();

    if (userError || !userData || !("user" in userData) || !userData.user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const user = userData.user;

    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const stepIndex = parseInt(params.step, 10);
    if (isNaN(stepIndex) || stepIndex < 0) {
      return NextResponse.json(
        { error: "Invalid step index" },
        { status: 400 },
      );
    }

    const { client: supabaseClient } = await createClientFromRequest(request);

    // Obtener organización del usuario
    const { data: adminUser } = await supabaseClient
      .from("admin_users")
      .select("organization_id")
      .eq("id", user.id)
      .single();

    const organizationId = adminUser?.organization_id || null;

    // Obtener progreso actual
    const { data: progress, error: fetchError } = await supabaseClient
      .from("user_tour_progress")
      .select("*")
      .eq("user_id", user.id)
      .eq("organization_id", organizationId)
      .maybeSingle();

    if (fetchError && fetchError.code !== "PGRST116") {
      logger.error("Error fetching tour progress:", fetchError);
      return NextResponse.json(
        { error: "Failed to fetch tour progress" },
        { status: 500 },
      );
    }

    if (!progress || progress.status !== "in_progress") {
      return NextResponse.json({ error: "Tour not started" }, { status: 400 });
    }

    // Actualizar paso actual y agregar a completados
    const completedSteps = [...(progress.completed_steps || [])];
    if (!completedSteps.includes(stepIndex)) {
      completedSteps.push(stepIndex);
    }
    const nextStep = stepIndex + 1;

    const { data: updatedProgress, error } = await supabaseClient
      .from("user_tour_progress")
      .update({
        current_step: nextStep,
        completed_steps: completedSteps,
        last_accessed_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      })
      .eq("user_id", user.id)
      .eq("organization_id", organizationId)
      .select()
      .single();

    if (error) {
      logger.error("Error updating step:", error);
      return NextResponse.json(
        { error: "Failed to update step", details: error.message },
        { status: 500 },
      );
    }

    return NextResponse.json(updatedProgress);
  } catch (error) {
    logger.error("Step completion error:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import { createClientFromRequest } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    const { getUser } = await createClientFromRequest(request);
    const { data: userData, error: userError } = await getUser();

    if (userError || !userData || !("user" in userData) || !userData.user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const user = userData.user;

    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    // Obtener progreso del tour desde la base de datos
    const supabase = await createClientFromRequest(request);

    // Obtener organización del usuario
    const { data: adminUser } = await supabase.client
      .from("admin_users")
      .select("organization_id")
      .eq("id", user.id)
      .single();

    const organizationId = adminUser?.organization_id || null;

    const { data: progress, error } = await supabase.client
      .from("user_tour_progress")
      .select("*")
      .eq("user_id", user.id)
      .eq("organization_id", organizationId)
      .maybeSingle();

    if (error && error.code !== "PGRST116") {
      // PGRST116 = no rows returned (esto es normal)
      logger.error("Error fetching tour progress:", error);
      return NextResponse.json(
        { error: "Failed to fetch tour progress" },
        { status: 500 },
      );
    }

    // Si no existe, retornar estado inicial
    if (!progress) {
      return NextResponse.json({
        status: "not_started",
        current_step: 0,
        completed_steps: [],
        skip_on_next_login: false,
      });
    }

    return NextResponse.json(progress);
  } catch (error) {
    logger.error("Tour progress error:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

export async function POST(request: NextRequest) {
  try {
    const { getUser } = await createClientFromRequest(request);
    const { data: userData, error: userError } = await getUser();

    if (userError || !userData || !("user" in userData) || !userData.user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const user = userData.user;

    if (userError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const body = await request.json();
    const { action } = body;

    const supabase = await createClientFromRequest(request);

    // Obtener organización del usuario
    const { data: adminUser } = await supabase.client
      .from("admin_users")
      .select("organization_id")
      .eq("id", user.id)
      .single();

    const organizationId = adminUser?.organization_id || null;

    let updateData: unknown = {};

    switch (action) {
      case "start":
        updateData = {
          status: "in_progress",
          current_step: 0,
          completed_steps: [],
          started_at: new Date().toISOString(),
          last_accessed_at: new Date().toISOString(),
          skip_on_next_login: false,
        };
        break;
      case "complete":
        updateData = {
          status: "completed",
          completed_at: new Date().toISOString(),
          last_accessed_at: new Date().toISOString(),
        };
        break;
      case "skip":
        updateData = {
          status: "disabled",
          skip_on_next_login: true,
          last_accessed_at: new Date().toISOString(),
        };
        break;
      case "restart":
        updateData = {
          status: "in_progress",
          current_step: 0,
          completed_steps: [],
          started_at: new Date().toISOString(),
          last_accessed_at: new Date().toISOString(),
          skip_on_next_login: false,
        };
        break;
      default:
        return NextResponse.json({ error: "Invalid action" }, { status: 400 });
    }

    // Upsert tour progress
    const { data, error } = await supabase.client
      .from("user_tour_progress")
      .upsert(
        {
          user_id: user.id,
          organization_id: organizationId,
          ...updateData,
          updated_at: new Date().toISOString(),
        },
        {
          onConflict: "user_id,organization_id",
        },
      )
      .select()
      .single();

    if (error) {
      logger.error("Error updating tour progress:", error);
      return NextResponse.json(
        { error: "Failed to update tour progress", details: error.message },
        { status: 500 },
      );
    }

    return NextResponse.json(data);
  } catch (error) {
    logger.error("Tour action error:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { profileUpdateSchema } from "@/lib/api/validation/profile-schemas";
import { appLogger as logger } from "@/lib/logger";
import { getProfileErrorMessage } from "@/lib/profile/error-messages";
import { createClient } from "@/utils/supabase/server";

export const dynamic = "force-dynamic";

/**
 * PATCH /api/profile
 *
 * Actualiza el perfil del usuario autenticado.
 * Validación server-side con Zod.
 */
export async function PATCH(request: NextRequest) {
  try {
    const supabase = await createClient();

    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser();

    if (authError || !user) {
      return NextResponse.json({ error: "No autenticado" }, { status: 401 });
    }

    const body = await request.json();
    const parsed = profileUpdateSchema.safeParse(body);

    if (!parsed.success) {
      const firstError = parsed.error.errors[0];
      const message = firstError?.message ?? "Datos inválidos";
      return NextResponse.json(
        { error: message, details: parsed.error.flatten() },
        { status: 400 },
      );
    }

    const updates = parsed.data;
    const cleanUpdates: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(updates)) {
      if (value !== undefined) {
        cleanUpdates[key] = value;
      }
    }

    if (Object.keys(cleanUpdates).length === 0) {
      return NextResponse.json(
        { error: "No hay campos para actualizar" },
        { status: 400 },
      );
    }

    const { data, error } = await supabase
      .from("profiles")
      .update(cleanUpdates)
      .eq("id", user.id)
      .select()
      .single();

    if (error) {
      const message = getProfileErrorMessage(error);
      return NextResponse.json({ error: message }, { status: 400 });
    }

    return NextResponse.json(data);
  } catch (err) {
    logger.error("Profile PATCH error:", err);
    return NextResponse.json(
      { error: "Error interno al actualizar el perfil" },
      { status: 500 },
    );
  }
}

/**
 * Security System Validation API
 *
 * REST API endpoint for testing and validating Phase 3 security implementations
 * in development and staging environments.
 *
 * Uses dynamic imports to avoid circular dependency issues at build time.
 *
 * @module app/api/security/validate/route
 */

import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";

// Test scenarios
const TEST_SCENARIOS = {
  normalUser: {
    name: "Normal User Behavior",
    description: "Simulate typical user activity patterns",
    actions: [
      { actionType: "login", resourceId: "dashboard" },
      { actionType: "view_reports", resourceId: "sales_report" },
      { actionType: "logout", resourceId: null },
    ],
  },
  suspiciousActivity: {
    name: "Suspicious Activity",
    description: "Simulate potentially malicious behavior",
    actions: [
      { actionType: "failed_login", resourceId: null },
      { actionType: "failed_login", resourceId: null },
      { actionType: "failed_login", resourceId: null },
      { actionType: "admin_access", resourceId: "user_management" },
    ],
  },
  dataExfiltration: {
    name: "Data Exfiltration Attempt",
    description: "Simulate unauthorized data access patterns",
    actions: [
      { actionType: "view_sensitive_data", resourceId: "customer_records" },
      { actionType: "data_export", resourceId: "full_database_dump" },
      { actionType: "file_download", resourceId: "confidential_documents.zip" },
    ],
  },
};

export const dynamic = "force-dynamic";

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const scenario = searchParams.get("scenario") || "health";
    const format = searchParams.get("format") || "json";

    logger.info("Security validation API called", { scenario, format });

    switch (scenario) {
      case "health":
        return await healthCheck();

      case "comprehensive":
        return await comprehensiveTest();

      case "performance":
        return await performanceTest();

      case "simulate":
        const simulationType = searchParams.get("type") || "normalUser";
        return await simulateScenario(simulationType);

      default:
        return NextResponse.json(
          {
            error: "Invalid scenario",
            availableScenarios: Object.keys(TEST_SCENARIOS),
          },
          { status: 400 },
        );
    }
  } catch (error) {
    logger.error("Security validation API error", { error });
    return NextResponse.json(
      {
        error: "Internal server error",
        message: error instanceof Error ? error.message : "Unknown error",
      },
      { status: 500 },
    );
  }
}

async function healthCheck() {
  // Dynamic import to avoid circular dependency at build time
  const {
    threatDetector,
    incidentResponse,
    phase3Security,
    behavioralAnalytics,
  } = await import("@/lib/security");

  const results = {
    timestamp: new Date().toISOString(),
    systemStatus: "healthy",
    components: {
      behavioralAnalytics: {
        status: "operational",
        version: "1.0.0",
      },
      threatDetection: threatDetector.getStatus(),
      incidentResponse: {
        status: "operational",
        activeIncidents: incidentResponse.getActiveIncidents().length,
      },
      orchestration: {
        status: "operational",
        uptime: process.uptime(),
      },
    },
    metrics: await getBasicMetrics(),
  };

  return NextResponse.json(results);
}

async function comprehensiveTest() {
  const { phase3Security } = await import("@/lib/security");

  const startTime = Date.now();
  const testResults: {
    timestamp: string;
    testSuite: string;
    results: Record<string, unknown>;
    summary: {
      totalTests: number;
      passed: number;
      failed: number;
      duration: number;
    };
    successRate?: number;
  } = {
    timestamp: new Date().toISOString(),
    testSuite: "comprehensive",
    results: {},
    summary: {
      totalTests: 0,
      passed: 0,
      failed: 0,
      duration: 0,
    },
  };

  try {
    testResults.summary.duration = Date.now() - startTime;
    testResults.successRate = Math.round(
      (testResults.summary.passed / testResults.summary.totalTests) * 100,
    );

    return NextResponse.json(testResults);
  } catch (error) {
    return NextResponse.json(
      {
        error: "Test execution failed",
        message: error instanceof Error ? error.message : "Unknown error",
        timestamp: new Date().toISOString(),
      },
      { status: 500 },
    );
  }
}

async function performanceTest() {
  const { phase3Security } = await import("@/lib/security");

  const startTime = Date.now();
  const eventCount = 1000;

  // Generate test events
  const testEvents = Array.from({ length: eventCount }, (_, i) => ({
    id: `perf-${i}`,
    userId: `perf-user-${i % 50}`,
    actionType: "api_request",
    timestamp: Date.now() + i,
    ipAddress: `192.168.1.${100 + (i % 100)}`,
    severity: "low",
    eventType: "data.access_normal",
    source: "load-test",
    resourceId: `resource-${i % 20}`,
  }));

  // Process events
  await phase3Security.processSecurityEvents(testEvents);

  const duration = Date.now() - startTime;
  const eventsPerSecond = Math.round((eventCount / duration) * 1000);

  return NextResponse.json({
    timestamp: new Date().toISOString(),
    testType: "performance",
    eventCount,
    durationMs: duration,
    eventsPerSecond,
    performanceRating:
      eventsPerSecond > 500
        ? "excellent"
        : eventsPerSecond > 200
          ? "good"
          : "needs_improvement",
  });
}

async function simulateScenario(scenarioType: string) {
  const {
    behavioralAnalytics,
    threatDetector,
    incidentResponse,
    phase3Security,
  } = await import("@/lib/security");

  const scenario = TEST_SCENARIOS[scenarioType as keyof typeof TEST_SCENARIOS];

  if (!scenario) {
    return NextResponse.json(
      {
        error: "Invalid scenario type",
        availableTypes: Object.keys(TEST_SCENARIOS),
      },
      { status: 400 },
    );
  }

  const userId = `sim-${scenarioType}-${Date.now()}`;
  const baseTime = Date.now();

  const actions = scenario.actions.map((action, index) => ({
    userId,
    actionType: action.actionType,
    timestamp: new Date(baseTime + index * 1000),
    ipAddress: "192.168.1.100",
    userAgent: "Security Test Agent",
    resourceId: action.resourceId ?? undefined,
    metadata: {
      testScenario: scenarioType,
      sequence: index,
    },
  }));

  // Process through behavioral analytics
  for (const action of actions) {
    await behavioralAnalytics.recordUserAction(action);
  }

  // Analyze for threats
  const threats = await threatDetector.analyzeUserBehavior(userId, actions);

  // Process as security events
  const securityEvents = actions.map((action) => ({
    id: `sim-event-${action.actionType}-${Date.now()}`,
    timestamp: action.timestamp.toISOString(),
    eventType: `sim.${action.actionType}`,
    severity: action.actionType.includes("failed") ? "high" : "medium",
    source: "simulation",
    userId: action.userId,
    ipAddress: action.ipAddress,
    details: action.metadata,
  }));

  const incidents =
    await incidentResponse.processSecurityEvents(securityEvents);

  // Get final assessment
  const baseline = await behavioralAnalytics.getUserBaseline(userId);
  const orchestrationStatus = phase3Security.getStatus();

  return NextResponse.json({
    timestamp: new Date().toISOString(),
    scenario: scenarioType,
    description: scenario.description,
    userId,
    actionsProcessed: actions.length,
    threatsDetected: threats.length,
    incidentsCreated: incidents.length,
    userRiskProfile: {
      baselineRisk: baseline?.riskProfile.baselineRisk,
      recentActivityScore: baseline?.riskProfile.recentActivityScore,
      totalAnomalies: baseline?.riskProfile.anomalyHistory.length,
    },
    systemMetrics: {
      activeIncidents: orchestrationStatus.metrics.activeIncidents,
      threatDetections: orchestrationStatus.metrics.threatDetections,
      anomalyEvents: orchestrationStatus.metrics.anomalyEvents,
    },
  });
}

async function getBasicMetrics() {
  const { phase3Security } = await import("@/lib/security");

  const status = phase3Security.getStatus();
  return {
    activeIncidents: status.metrics.activeIncidents,
    threatDetections: status.metrics.threatDetections,
    anomalyEvents: status.metrics.anomalyEvents,
    responseTimeAvg: status.metrics.responseTimeAvg,
    complianceScore: status.metrics.complianceScore,
  };
}

import { NextRequest, NextResponse } from "next/server";

import { parseAndValidateBody } from "@/lib/api/validation/zod-helpers";
import { createPublicSaasSupportTicketSchema } from "@/lib/api/validation/zod-schemas";
import { appLogger as logger } from "@/lib/logger";
import { createRootAdminClient } from "@/utils/supabase/root-admin";

/**
 * POST /api/support/create-ticket
 * Crear ticket de soporte SaaS desde portal público (sin autenticación)
 */
export const dynamic = "force-dynamic";
export async function POST(request: NextRequest) {
  try {
    const supabaseServiceRole = createRootAdminClient();

    // Validar body
    const body = await parseAndValidateBody(
      request,
      createPublicSaasSupportTicketSchema,
    );

    // Intentar encontrar organización por nombre si se proporciona
    let organizationId: string | null = null;
    if (body.organization_name) {
      const { data: org } = await supabaseServiceRole
        .from("organizations")
        .select("id")
        .ilike("name", `%${body.organization_name}%`)
        .limit(1)
        .maybeSingle();

      if (org) {
        organizationId = org.id;
      }
    }

    // Crear ticket público
    const { data: ticket, error: ticketError } = await supabaseServiceRole
      .from("saas_support_tickets")
      .insert({
        organization_id: organizationId,
        created_by_user_id: null, // Ticket público, sin usuario autenticado
        requester_email: body.requester_email,
        requester_name: body.requester_name,
        requester_role: null, // No hay rol para tickets públicos
        subject: body.subject,
        description: body.description,
        category: body.category,
        priority: body.priority || "medium",
        status: "open",
        metadata: {
          ...(body.metadata || {}),
          is_public: true,
          organization_name: body.organization_name || null,
        },
      })
      .select(
        `
        id,
        ticket_number,
        subject,
        status,
        created_at,
        organization:organizations(id, name, slug)
      `,
      )
      .single();

    if (ticketError) {
      logger.error("Error creating public SaaS support ticket", ticketError);
      return NextResponse.json(
        { error: "Failed to create ticket. Please try again." },
        { status: 500 },
      );
    }

    logger.info(`Public SaaS support ticket created: ${ticket.ticket_number}`);

    // Send email notification to requester (non-blocking)
    try {
      if (process.env.RESEND_API_KEY) {
        const { sendSaasTicketCreatedEmail } = await import(
          "@/lib/email/templates/saas-support"
        );
        await sendSaasTicketCreatedEmail({
          id: ticket.id,
          ticket_number: ticket.ticket_number,
          subject: ticket.subject,
          description: body.description,
          status: ticket.status,
          priority: body.priority || "medium",
          category: body.category,
          requester_name: body.requester_name,
          requester_email: body.requester_email,
          organization: Array.isArray(ticket.organization)
            ? ticket.organization[0] || null
            : ticket.organization,
        });
        logger.info("Ticket creation email sent successfully");
      } else {
        logger.debug("Resend not configured, skipping email notification");
      }
    } catch (emailError) {
      logger.warn("Failed to send ticket creation email", emailError);
      // Don't fail the request if email fails
    }

    // Push notification for root/dev (non-blocking)
    try {
      const { NotificationService } = await import(
        "@/lib/notifications/notification-service"
      );
      await NotificationService.notifySaasSupportTicketNew(
        ticket.id,
        ticket.ticket_number,
        ticket.subject,
        body.requester_email,
        Array.isArray(ticket.organization)
          ? (ticket.organization[0] as unknown)?.name
          : (ticket.organization as unknown)?.name,
      );
    } catch (notifError) {
      logger.warn("Failed to create support notification", notifError);
    }

    return NextResponse.json(
      {
        ticket: {
          id: ticket.id,
          ticket_number: ticket.ticket_number,
          subject: ticket.subject,
          status: ticket.status,
          created_at: ticket.created_at,
        },
        message:
          "Ticket creado exitosamente. Te hemos enviado un email de confirmación.",
      },
      { status: 201 },
    );
  } catch (error) {
    logger.error("Unexpected error in POST /api/support/create-ticket", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import { createRootAdminClient } from "@/utils/supabase/root-admin";

/**
 * GET /api/support/ticket/[ticketNumber]
 * Obtener información de un ticket público por su número
 */
export const dynamic = "force-dynamic";
export async function GET(
  request: NextRequest,
  { params }: { params: { ticketNumber: string } },
) {
  try {
    const supabaseServiceRole = createRootAdminClient();

    // Obtener ticket por número
    const { data: ticket, error: ticketError } = await supabaseServiceRole
      .from("saas_support_tickets")
      .select(
        `
        id,
        ticket_number,
        subject,
        description,
        category,
        priority,
        status,
        created_at,
        updated_at,
        first_response_at,
        last_response_at,
        organization:organizations(id, name, slug)
      `,
      )
      .eq("ticket_number", params.ticketNumber)
      .single();

    if (ticketError || !ticket) {
      return NextResponse.json({ error: "Ticket not found" }, { status: 404 });
    }

    // Obtener mensajes públicos (sin mensajes internos)
    const { data: messages, error: messagesError } = await supabaseServiceRole
      .from("saas_support_messages")
      .select(
        `
        id,
        message,
        sender_name,
        sender_email,
        is_from_customer,
        created_at,
        message_type
      `,
      )
      .eq("ticket_id", ticket.id)
      .eq("is_internal", false) // Solo mensajes públicos
      .order("created_at", { ascending: true });

    if (messagesError) {
      logger.error("Error fetching ticket messages", messagesError);
      // Continuar sin mensajes si hay error
    }

    return NextResponse.json({
      ticket: {
        ...ticket,
        messages: messages || [],
      },
    });
  } catch (error) {
    logger.error(
      "Unexpected error in GET /api/support/ticket/[ticketNumber]",
      error,
    );
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

/**
 * POST /api/support/ticket/[ticketNumber]
 * Agregar mensaje a un ticket público
 */
export async function POST(
  request: NextRequest,
  { params }: { params: { ticketNumber: string } },
) {
  try {
    const supabaseServiceRole = createRootAdminClient();

    const body = await request.json();
    const { message, requester_email, requester_name } = body;

    if (!message || !requester_email) {
      return NextResponse.json(
        { error: "Message and email are required" },
        { status: 400 },
      );
    }

    // Obtener ticket por número
    const { data: ticket, error: ticketError } = await supabaseServiceRole
      .from("saas_support_tickets")
      .select("id, requester_email, status")
      .eq("ticket_number", params.ticketNumber)
      .single();

    if (ticketError || !ticket) {
      return NextResponse.json({ error: "Ticket not found" }, { status: 404 });
    }

    // Verificar que el email coincida (seguridad básica)
    if (
      ticket.requester_email.toLowerCase() !== requester_email.toLowerCase()
    ) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 403 });
    }

    // Crear mensaje
    const { data: newMessage, error: messageError } = await supabaseServiceRole
      .from("saas_support_messages")
      .insert({
        ticket_id: ticket.id,
        message: message.trim(),
        is_internal: false,
        is_from_customer: true,
        sender_id: null, // No hay usuario autenticado
        sender_name: requester_name || requester_email.split("@")[0],
        sender_email: requester_email,
        message_type: "message",
        attachments: [],
      })
      .select()
      .single();

    if (messageError) {
      logger.error("Error creating message", messageError);
      return NextResponse.json(
        { error: "Failed to create message" },
        { status: 500 },
      );
    }

    // Actualizar ticket: last_response_at y cambiar estado si estaba resuelto/cerrado
    const updates: Record<string, unknown> = {
      last_response_at: new Date().toISOString(),
    };

    if (ticket.status === "resolved" || ticket.status === "closed") {
      updates.status = "waiting_customer";
    }

    await supabaseServiceRole
      .from("saas_support_tickets")
      .update(updates)
      .eq("id", ticket.id);

    logger.info(`Message added to public ticket: ${params.ticketNumber}`);

    // Push notification for root/dev when customer adds message
    try {
      const { data: fullTicket } = await supabaseServiceRole
        .from("saas_support_tickets")
        .select("id, ticket_number, subject")
        .eq("id", ticket.id)
        .single();
      if (fullTicket) {
        const { NotificationService } = await import(
          "@/lib/notifications/notification-service"
        );
        await NotificationService.notifySaasSupportNewMessage(
          fullTicket.id,
          fullTicket.ticket_number,
          fullTicket.subject,
          true,
        );
      }
    } catch (notifError) {
      // Non-blocking
    }

    return NextResponse.json({ message: newMessage }, { status: 201 });
  } catch (error) {
    logger.error(
      "Unexpected error in POST /api/support/ticket/[ticketNumber]",
      error,
    );
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";

import { appLogger as logger } from "@/lib/logger";
import { createServiceRoleClient } from "@/utils/supabase/server";

const surveySubmitSchema = z.object({
  token: z.string().min(1, "Token requerido"),
  score: z.number().int().min(1).max(5, "La puntuación debe ser entre 1 y 5"),
  comment: z.string().max(1000).optional(),
});

/**
 * POST /api/surveys/submit
 * Public endpoint - submit satisfaction survey response (no auth required)
 */
export const dynamic = "force-dynamic";
export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const parsed = surveySubmitSchema.safeParse(body);

    if (!parsed.success) {
      return NextResponse.json(
        { error: "Datos inválidos", details: parsed.error.flatten() },
        { status: 400 },
      );
    }

    const { token, score, comment } = parsed.data;
    const supabase = createServiceRoleClient();

    // Find invitation by token
    const { data: invitation, error: invError } = await supabase
      .from("survey_invitations")
      .select(
        "id, organization_id, work_order_id, customer_id, used_at, expires_at",
      )
      .eq("token", token)
      .single();

    if (invError || !invitation) {
      return NextResponse.json(
        { error: "Enlace inválido o expirado" },
        { status: 404 },
      );
    }

    if (invitation.used_at) {
      return NextResponse.json(
        { error: "Esta encuesta ya fue respondida" },
        { status: 400 },
      );
    }

    const now = new Date();
    const expiresAt = new Date(invitation.expires_at);
    if (expiresAt < now) {
      return NextResponse.json(
        { error: "Este enlace ha expirado" },
        { status: 400 },
      );
    }

    // Insert survey response
    const { error: insertError } = await supabase
      .from("customer_satisfaction_surveys")
      .insert({
        organization_id: invitation.organization_id,
        work_order_id: invitation.work_order_id,
        customer_id: invitation.customer_id,
        score,
        comment: comment || null,
        token_used: token,
      });

    if (insertError) {
      logger.error("Error inserting survey response", insertError);
      return NextResponse.json(
        { error: "Error al guardar la respuesta" },
        { status: 500 },
      );
    }

    // Mark invitation as used
    await supabase
      .from("survey_invitations")
      .update({ used_at: now.toISOString() })
      .eq("id", invitation.id);

    return NextResponse.json({ success: true });
  } catch (error) {
    logger.error("Survey submit error", error);
    return NextResponse.json({ error: "Error interno" }, { status: 500 });
  }
}

import { createClient } from "@supabase/supabase-js";
import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";

// Initialize Supabase client for server-side operations
const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!,
);

export const dynamic = "force-dynamic";
export async function POST(request: NextRequest) {
  try {
    const events = await request.json();

    // Validate events structure
    if (!Array.isArray(events)) {
      return NextResponse.json(
        { error: "Invalid event format" },
        { status: 400 },
      );
    }

    // Store events in PostgreSQL database
    const storedEvents = [];

    for (const event of events) {
      try {
        // Map telemetry event to database schema
        const dbEvent = {
          event_type: event.eventType || "unknown",
          event_name: event.eventName || event.eventType || "unnamed_event",
          timestamp: event.timestamp || new Date().toISOString(),
          user_id: event.userId ? event.userId : null,
          organization_id: event.context?.organizationId
            ? event.context.organizationId
            : null,
          session_id: event.sessionId || null,
          payload: event.payload || {},
          user_agent:
            event.metadata?.userAgent ||
            request.headers.get("user-agent") ||
            null,
          ip_address:
            request.headers.get("x-forwarded-for") ||
            request.headers.get("x-real-ip") ||
            null,
          device_type: event.metadata?.deviceInfo?.deviceType || null,
          browser: event.metadata?.deviceInfo?.browser || null,
          os: event.metadata?.deviceInfo?.os || null,
          screen_size: event.metadata?.deviceInfo
            ? `${event.metadata.deviceInfo.screenWidth}x${event.metadata.deviceInfo.screenHeight}`
            : null,
          page_url: event.metadata?.pageUrl || null,
          referrer: event.metadata?.referrer || null,
          duration: event.payload?.duration || null,
          performance_data: event.metadata?.performance || null,
        };

        // Insert into database
        const { data, error } = await supabase
          .from("telemetry_events")
          .insert([dbEvent])
          .select();

        if (error) {
          logger.error("Failed to store telemetry event:", error);
          logger.error("Event data:", JSON.stringify(dbEvent, null, 2));
          // Continue with other events even if one fails
          continue;
        }

        if (data && data.length > 0) {
          storedEvents.push(data[0]);
        }
      } catch (eventError) {
        logger.error("Error processing individual event:", eventError);
        // Continue processing other events
      }
    }

    // Process events (basic processing since processBatch doesn't exist)
    const processedEvents = events.length;

    return NextResponse.json({
      success: true,
      processed: processedEvents,
      stored: storedEvents.length,
      totalReceived: events.length,
    });
  } catch (error) {
    logger.error("Telemetry processing error:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

