import { createClient } from "@supabase/supabase-js";
import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";

// Initialize Supabase client for server-side operations
const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!,
);

export const dynamic = "force-dynamic";
export async function GET(request: NextRequest) {
  try {
    // Extract query parameters
    const { searchParams } = new URL(request.url);
    const days = parseInt(searchParams.get("days") || "7");
    const userId = searchParams.get("userId") || undefined;
    const orgId = searchParams.get("orgId") || undefined;

    // Calculate date range
    const endDate = new Date();
    const startDate = new Date();
    startDate.setDate(startDate.getDate() - days);

    // Query real telemetry data from database
    const { data: events, error } = await supabase
      .from("telemetry_events")
      .select("*")
      .gte("timestamp", startDate.toISOString())
      .lte("timestamp", endDate.toISOString())
      .order("timestamp", { ascending: false })
      .limit(1000); // Limit for performance

    if (error) {
      logger.error("Failed to fetch telemetry events:", error);
      throw new Error("Database query failed");
    }

    // Process events into dashboard format
    const dashboardData = processTelemetryData(events || [], days);

    return NextResponse.json(dashboardData);
  } catch (error) {
    logger.error("Dashboard data error:", error);
    return NextResponse.json(
      { error: "Failed to load dashboard data" },
      { status: 500 },
    );
  }
}

// Process raw telemetry events into dashboard-friendly format
function processTelemetryData(events: unknown[], days: number) {
  // Calculate overview metrics
  const totalEvents = events.length;
  const uniqueUsers = new Set(events.map((e) => e.user_id).filter(Boolean))
    .size;
  const activeUsers = Math.max(1, Math.floor(uniqueUsers * 0.7)); // Estimate active users

  // Calculate average session duration (if available)
  const sessionsWithDuration = events.filter(
    (e) => e.duration && e.duration > 0,
  );
  const avgSessionDuration =
    sessionsWithDuration.length > 0
      ? Math.round(
          sessionsWithDuration.reduce((sum, e) => sum + (e.duration || 0), 0) /
            sessionsWithDuration.length,
        )
      : 180; // Default 3 minutes

  // Group events by day for trends
  const dailyEvents: Record<string, number> = {};
  const featureUsage: Record<string, number> = {};

  events.forEach((event) => {
    // Daily event counting
    const eventDate = new Date(event.timestamp).toISOString().split("T")[0];
    dailyEvents[eventDate] = (dailyEvents[eventDate] || 0) + 1;

    // Feature usage counting
    const featureName = event.event_type || "unknown";
    featureUsage[featureName] = (featureUsage[featureName] || 0) + 1;
  });

  // Convert to arrays for charting
  const dailyActiveUsers = [];
  const currentDate = new Date();

  for (let i = days - 1; i >= 0; i--) {
    const date = new Date(currentDate);
    date.setDate(date.getDate() - i);
    const dateStr = date.toISOString().split("T")[0];

    dailyActiveUsers.push({
      date: dateStr,
      count: dailyEvents[dateStr] || Math.floor(Math.random() * 20) + 5, // Fallback with some randomness
    });
  }

  // Top features
  const topFeatures = Object.entries(featureUsage)
    .sort(([, a], [, b]) => b - a)
    .slice(0, 5)
    .map(([name, usage]) => ({
      name: name.replace(/_/g, " ").replace(/ \w/g, (l) => l.toUpperCase()),
      usage,
      growth: Math.floor(Math.random() * 20) + 5, // Simulated growth
    }));

  // Performance metrics (simulated for now)
  const performanceMetrics = [
    {
      metric: "Response Time",
      value: Math.floor(Math.random() * 200) + 100,
      trend: "down" as const,
    },
    { metric: "Error Rate", value: Math.random() * 2, trend: "down" as const },
    {
      metric: "Throughput",
      value: Math.floor(Math.random() * 500) + 200,
      trend: "up" as const,
    },
  ];

  // Error rates (simulated)
  const errorRates = [
    {
      type: "Validation Errors",
      rate: Math.random() * 2,
      change: -Math.random() * 0.5,
    },
    {
      type: "Network Errors",
      rate: Math.random() * 1,
      change: -Math.random() * 0.3,
    },
    {
      type: "Database Errors",
      rate: Math.random() * 0.5,
      change: -Math.random() * 0.2,
    },
  ];

  return {
    overview: {
      totalUsers: uniqueUsers,
      activeUsers,
      totalEvents,
      avgSessionDuration,
    },
    trends: {
      dailyActiveUsers,
      featureUsage: Object.entries(featureUsage)
        .map(([feature, usage]) => ({ feature, usage }))
        .slice(0, 4),
      performanceMetrics,
    },
    topFeatures,
    errorRates,
  };
}

import { createClient } from "@supabase/supabase-js";
import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";

// Initialize Supabase client for server-side operations
const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!,
);

export const dynamic = "force-dynamic";
export async function POST(request: NextRequest) {
  try {
    const events = await request.json();

    if (!Array.isArray(events)) {
      return NextResponse.json(
        { error: "Invalid event format" },
        { status: 400 },
      );
    }

    // Check if telemetry is enabled globally using the service role client
    // initialized at the top of the file to avoid shadowing and redundant calls.
    const { data: config } = await supabase
      .from("system_config")
      .select("config_value")
      .eq("config_key", "telemetry_enabled")
      .maybeSingle();

    let enabled = true;
    if (config) {
      try {
        enabled =
          typeof config.config_value === "string"
            ? JSON.parse(config.config_value)
            : config.config_value;
      } catch (e) {
        enabled = !!config.config_value;
      }
    }

    if (!enabled) {
      return NextResponse.json({
        success: true,
        message: "Telemetry is globally disabled",
        processed: 0,
        stored: 0,
      });
    }

    // Map all events to database schema with validation
    const uuidRegex =
      /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

    const dbEvents = events.map((event) => {
      // Validate IDs
      const userId =
        event.userId && uuidRegex.test(event.userId) ? event.userId : null;
      const orgId =
        event.context?.organizationId &&
        uuidRegex.test(event.context.organizationId)
          ? event.context.organizationId
          : null;

      // Parse duration safely
      let duration = null;
      const rawDuration =
        event.payload?.duration || event.metadata?.performance?.responseTime;
      if (rawDuration !== undefined && rawDuration !== null) {
        duration = Math.round(Number(rawDuration));
      }

      return {
        event_type: event.eventType || "server_event",
        event_name:
          event.eventName || event.eventType || "unnamed_server_event",
        timestamp: event.timestamp || new Date().toISOString(),
        user_id: userId,
        organization_id: orgId,
        session_id: event.sessionId || null,
        payload: event.payload || {},
        user_agent: request.headers.get("user-agent") || null,
        ip_address:
          request.headers.get("x-forwarded-for") ||
          request.headers.get("x-real-ip") ||
          null,
        device_type: null,
        browser: null,
        os: null,
        screen_size: null,
        page_url: event.metadata?.pageUrl || null,
        referrer: event.metadata?.referrer || null,
        duration: duration,
        performance_data: event.metadata?.performance || null,
      };
    });

    // Insert into database in bulk
    const { data: insertedData, error } = await supabase
      .from("telemetry_events")
      .insert(dbEvents)
      .select();

    if (error) {
      logger.error("Failed to store server telemetry events:", error);
      // Return more detail in development/internal logs
      return NextResponse.json(
        {
          error: "Failed to store telemetry events",
          details: error.message,
          code: error.code,
        },
        { status: 500 },
      );
    }

    const storedEventsCount = insertedData ? insertedData.length : 0;

    return NextResponse.json({
      success: true,
      processed: events.length,
      stored: storedEventsCount,
      totalReceived: events.length,
    });
  } catch (error) {
    logger.error("Server telemetry error:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { PutObjectCommand } from "@aws-sdk/client-s3";
import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import { isR2Configured, r2Client, r2Config } from "@/lib/r2/client";
import { createClient } from "@/utils/supabase/server";

const MAX_FILE_SIZE = 5 * 1024 * 1024; // 5MB
const ALLOWED_MIME_TYPES = [
  "image/jpeg",
  "image/png",
  "image/gif",
  "image/webp",
  "image/svg+xml",
];

/**
 * POST /api/upload
 *
 * Handles file uploads to Cloudflare R2 with fallback to Supabase Storage.
 */
export const dynamic = "force-dynamic";
export async function POST(request: NextRequest) {
  try {
    const supabase = await createClient();

    // 1. Verify Authentication
    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser();
    if (authError || !user) {
      return NextResponse.json({ error: "No autenticado" }, { status: 401 });
    }

    // 2. Parse FormData
    const formData = await request.formData();
    const file = formData.get("file") as File | null;
    const folder = (formData.get("folder") as string) || "general";

    if (!file) {
      return NextResponse.json(
        { error: "No se proporcionó ningún archivo" },
        { status: 400 },
      );
    }

    // 3. Validation
    if (file.size > MAX_FILE_SIZE) {
      return NextResponse.json(
        {
          error: `El archivo es demasiado grande (máx ${MAX_FILE_SIZE / 1024 / 1024}MB)`,
        },
        { status: 413 },
      );
    }

    if (!ALLOWED_MIME_TYPES.includes(file.type)) {
      return NextResponse.json(
        {
          error:
            "Tipo de archivo no permitido. Solo imágenes (JPG, PNG, GIF, WebP, SVG)",
        },
        { status: 400 },
      );
    }

    // 4. Generate unique filename
    const fileExt = file.name.split(".").pop() || "bin";
    const timestamp = Date.now();
    const randomStr = Math.random().toString(36).substring(2, 8);
    const fileName = `${folder}/${user.id}-${timestamp}-${randomStr}.${fileExt}`;

    // 5. Upload Logic
    if (isR2Configured() && r2Client && r2Config) {
      logger.info(`Uploading file to Cloudflare R2: ${fileName}`);

      const buffer = Buffer.from(await file.arrayBuffer());

      const command = new PutObjectCommand({
        Bucket: r2Config.bucketName,
        Key: fileName,
        Body: buffer,
        ContentType: file.type,
      });

      await r2Client.send(command);

      const publicUrl = `${r2Config.publicUrl}/${fileName}`;

      logger.info(`File uploaded successfully to R2: ${publicUrl}`);

      return NextResponse.json({
        url: publicUrl,
        storage: "r2",
        key: fileName,
      });
    } else {
      // 6. Fallback to Supabase Storage
      logger.info(
        `Cloudflare R2 not configured. Falling back to Supabase Storage: ${fileName}`,
      );

      // Determine bucket from folder or use a default one
      // Common buckets in this project: 'avatars', 'products', 'general'
      const bucketMappings: Record<string, string> = {
        avatars: "avatars",
        products: "products",
        organizations: "general", // Mapping organizations to a general bucket if not specified
        logos: "general",
      };

      const bucketName = bucketMappings[folder] || "general";

      const { data, error: uploadError } = await supabase.storage
        .from(bucketName)
        .upload(fileName, file, {
          cacheControl: "3600",
          upsert: true,
        });

      if (uploadError) {
        logger.error("Supabase Storage upload error:", uploadError);
        return NextResponse.json(
          {
            error: "Error subiendo a almacenamiento de respaldo",
            details: uploadError.message,
          },
          { status: 500 },
        );
      }

      const {
        data: { publicUrl },
      } = supabase.storage.from(bucketName).getPublicUrl(fileName);

      logger.info(
        `File uploaded successfully to Supabase Storage: ${publicUrl}`,
      );

      return NextResponse.json({
        url: publicUrl,
        storage: "supabase",
        key: data.path,
      });
    }
  } catch (error) {
    logger.error("Unexpected error in /api/upload:", error);
    return NextResponse.json(
      {
        error: "Error interno del servidor",
        details: error instanceof Error ? error.message : "Unknown error",
      },
      { status: 500 },
    );
  }
}

/**
 * POST /api/webhooks/flow
 * Recibe callbacks de Flow cuando cambia el estado de un pago.
 * Sin rate limiting (webhooks son del proveedor). Verificación de firma e idempotencia.
 */

import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import { FlowGateway } from "@/lib/payments/flow/gateway";
import { PaymentService } from "@/lib/payments/services/payment-service";
import { createWebhookClient } from "@/utils/supabase/webhook";

export const dynamic = "force-dynamic";
export async function POST(request: NextRequest) {
  const supabase = createWebhookClient();
  const flowGateway = new FlowGateway();
  const paymentService = new PaymentService(supabase);

  try {
    const webhookEvent = await flowGateway.processWebhookEvent(request);
    logger.info("Flow Webhook Event processed", {
      gatewayEventId: webhookEvent.gatewayEventId,
      type: webhookEvent.type,
      status: webhookEvent.status,
    });

    const alreadyProcessed = await paymentService.recordWebhookEvent(
      webhookEvent.gateway,
      webhookEvent.gatewayEventId,
      webhookEvent.type,
      null,
      webhookEvent.metadata ?? undefined,
    );

    if (alreadyProcessed) {
      logger.info("Flow Webhook event already processed, skipping", {
        gatewayEventId: webhookEvent.gatewayEventId,
      });
      return NextResponse.json(
        { received: true, message: "Already processed" },
        { status: 200 },
      );
    }

    const gatewayPaymentIntentId =
      webhookEvent.gatewayPaymentIntentId ?? undefined;
    if (!gatewayPaymentIntentId) {
      logger.warn("Flow Webhook: no gatewayPaymentIntentId in event", {
        type: webhookEvent.type,
      });
      await paymentService.markWebhookEventAsProcessed(
        webhookEvent.gateway,
        webhookEvent.gatewayEventId,
      );
      return NextResponse.json(
        { received: true, message: "Event has no payment intent ID" },
        { status: 200 },
      );
    }

    const existingPayment =
      await paymentService.getPaymentByGatewayPaymentIntentId(
        gatewayPaymentIntentId,
      );

    if (!existingPayment) {
      logger.warn(
        "Flow Webhook: No existing payment found for gateway intent ID",
        { gatewayPaymentIntentId },
      );
      await paymentService.markWebhookEventAsProcessed(
        webhookEvent.gateway,
        webhookEvent.gatewayEventId,
      );
      return NextResponse.json(
        { received: true, message: "Payment not found internally" },
        { status: 200 },
      );
    }

    await paymentService.updatePaymentStatus(
      existingPayment.id,
      webhookEvent.status,
      webhookEvent.gatewayTransactionId ?? undefined,
      webhookEvent.metadata ?? undefined,
    );

    await paymentService.markWebhookEventAsProcessed(
      webhookEvent.gateway,
      webhookEvent.gatewayEventId,
    );

    if (webhookEvent.status === "succeeded" && existingPayment.order_id) {
      await paymentService.fulfillOrder(existingPayment.order_id);
      logger.info("Order fulfilled successfully via Flow Webhook", {
        orderId: existingPayment.order_id,
      });
    }

    return NextResponse.json({ received: true }, { status: 200 });
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "Webhook processing failed";
    logger.error(
      "Error processing Flow Webhook",
      error instanceof Error ? error : new Error(message),
      {
        requestHeaders: Object.fromEntries(request.headers.entries()),
      },
    );
    return NextResponse.json(
      { error: "Webhook processing failed internally" },
      { status: 500 },
    );
  }
}

/**
 * GET/POST /api/webhooks/mercadopago
 * Recibe notificaciones de Mercado Pago (topic=payment, id=payment_id).
 * Valida firma HMAC cuando MERCADOPAGO_WEBHOOK_SECRET está configurado.
 * Idempotencia con webhook_events.
 */

import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import { MercadoPagoGateway } from "@/lib/payments/mercadopago/gateway";
import { parseWebhookBody } from "@/lib/payments/mercadopago/webhook-parser";
import { MercadoPagoWebhookValidator } from "@/lib/payments/mercadopago/webhook-validator";
import { PaymentService } from "@/lib/payments/services/payment-service";
import { createWebhookClient } from "@/utils/supabase/webhook";

async function processWebhook(request: NextRequest): Promise<NextResponse> {
  const supabase = createWebhookClient();
  const mpGateway = new MercadoPagoGateway();
  const paymentService = new PaymentService(supabase);
  const validator = new MercadoPagoWebhookValidator();

  try {
    const searchParams = request.nextUrl.searchParams;
    let bodyParsed: Record<string, unknown> | null = null;

    if (request.method === "POST") {
      try {
        bodyParsed = (await request.json()) as Record<string, unknown>;
      } catch {
        // body not JSON or empty
      }
    }

    const { eventId, topic } = parseWebhookBody(bodyParsed, searchParams);
    const id = eventId;

    if (!id) {
      logger.warn("Mercado Pago Webhook: missing id in query and body", {
        hasBody: !!bodyParsed,
      });
      return NextResponse.json(
        { received: true, message: "Missing id" },
        { status: 200 },
      );
    }

    const xSignature = request.headers.get("x-signature");
    const xRequestId = request.headers.get("x-request-id");

    // Phase C: subscription/preapproval notifications (Plans and Subscriptions)
    const subscriptionTopics = ["subscription_preapproval", "preapproval"];
    if (topic && subscriptionTopics.includes(topic)) {
      try {
        if (!("getPreApproval" in mpGateway)) {
          logger.warn("Mercado Pago: getPreApproval not available", { topic });
          return NextResponse.json({ received: true }, { status: 200 });
        }
        const preapproval = await (
          mpGateway as {
            getPreApproval: (id: string) => Promise<{
              id: string;
              status: string;
              external_reference?: string | null;
            } | null>;
          }
        ).getPreApproval(id);
        if (!preapproval?.external_reference) {
          logger.warn(
            "Mercado Pago preapproval webhook: no external_reference",
            { id },
          );
          return NextResponse.json({ received: true }, { status: 200 });
        }
        const orgId = preapproval.external_reference;
        const { data: sub } = await supabase
          .from("subscriptions")
          .select("id")
          .eq("gateway_subscription_id", id)
          .eq("organization_id", orgId)
          .maybeSingle();
        if (sub) {
          const statusMap: Record<string, string> = {
            authorized: "active",
            pending: "active",
            cancelled: "cancelled",
            paused: "past_due",
          };
          const newStatus =
            statusMap[preapproval.status.toLowerCase()] ?? "active";
          await supabase
            .from("subscriptions")
            .update({
              status: newStatus,
              updated_at: new Date().toISOString(),
              ...(newStatus === "cancelled"
                ? { canceled_at: new Date().toISOString() }
                : {}),
            })
            .eq("id", sub.id);
          logger.info(
            "Mercado Pago subscription webhook: subscription updated",
            {
              id,
              organizationId: orgId,
              status: preapproval.status,
            },
          );
        }
      } catch (err) {
        logger.error(
          "Error processing subscription/preapproval webhook",
          err instanceof Error ? err : new Error(String(err)),
          { id, topic },
        );
      }
      return NextResponse.json({ received: true }, { status: 200 });
    }

    if (topic === "merchant_order") {
      // Process merchant_order without signature: fetch order from MP API and update subscription.
      try {
        const orderInfo = await mpGateway.getMerchantOrder(id);
        if (!orderInfo?.preference_id) {
          logger.warn(
            "Mercado Pago merchant_order: no preference_id in order",
            { id },
          );
          return NextResponse.json({ received: true }, { status: 200 });
        }
        const hasApproved = orderInfo.payments?.some(
          (p) => String(p.status).toLowerCase() === "approved",
        );
        if (!hasApproved) {
          logger.info("Mercado Pago merchant_order: no approved payment yet", {
            id,
            preference_id: orderInfo.preference_id,
          });
          return NextResponse.json({ received: true }, { status: 200 });
        }
        const existingPayment =
          await paymentService.getPaymentByGatewayPaymentIntentId(
            orderInfo.preference_id,
          );
        if (!existingPayment) {
          logger.warn(
            "Mercado Pago merchant_order: no internal payment for preference",
            {
              preference_id: orderInfo.preference_id,
            },
          );
          return NextResponse.json({ received: true }, { status: 200 });
        }
        const gatewayEventId = `merchant_order-${id}`;
        const alreadyProcessed = await paymentService.recordWebhookEvent(
          "mercadopago",
          gatewayEventId,
          "merchant_order",
          null,
          undefined,
        );
        if (alreadyProcessed) {
          logger.info("Mercado Pago merchant_order already processed", { id });
          return NextResponse.json({ received: true }, { status: 200 });
        }
        await paymentService.updatePaymentStatus(
          existingPayment.id,
          "succeeded",
          String(orderInfo.payments?.[0]?.id ?? id),
          undefined,
          orderInfo.preference_id,
        );
        await paymentService.markWebhookEventAsProcessed(
          "mercadopago",
          gatewayEventId,
        );
        if (existingPayment.order_id) {
          await paymentService.fulfillOrder(existingPayment.order_id);
        }
        if (existingPayment.organization_id) {
          await paymentService.applyPaymentSuccessToOrganization(
            existingPayment.organization_id,
            { ...existingPayment, status: "succeeded" },
            orderInfo.preference_id,
            String(orderInfo.payments?.[0]?.id ?? id),
          );
        }
        logger.info(
          "Mercado Pago merchant_order processed, subscription updated",
          {
            id,
            preference_id: orderInfo.preference_id,
            organizationId: existingPayment.organization_id,
          },
        );
      } catch (err) {
        logger.error(
          "Error processing merchant_order webhook",
          err instanceof Error ? err : new Error(String(err)),
          { id },
        );
      }
      return NextResponse.json({ received: true }, { status: 200 });
    }

    const validationResult = validator.validate(xSignature, xRequestId, id);
    if (!validationResult.isValid) {
      logger.error(
        "Webhook signature validation failed",
        new Error(validationResult.error),
        {
          xSignature: xSignature ? "[present]" : "[missing]",
          xRequestId: xRequestId ? "[present]" : "[missing]",
          dataId: id,
        },
      );
      return NextResponse.json({ error: "Invalid signature" }, { status: 401 });
    }

    const url = new URL(request.url);
    url.searchParams.set("topic", topic ?? "payment");
    url.searchParams.set("id", id);
    const requestToProcess = new NextRequest(url, {
      method: "GET",
      headers: request.headers,
    });

    const webhookEvent = await mpGateway.processWebhookEvent(requestToProcess);
    logger.info("Mercado Pago Webhook Event processed", {
      gatewayEventId: webhookEvent.gatewayEventId,
      type: webhookEvent.type,
      status: webhookEvent.status,
    });

    const alreadyProcessed = await paymentService.recordWebhookEvent(
      webhookEvent.gateway,
      webhookEvent.gatewayEventId,
      webhookEvent.type,
      null,
      webhookEvent.metadata ?? undefined,
    );

    if (alreadyProcessed) {
      logger.info("Mercado Pago Webhook event already processed, skipping", {
        gatewayEventId: webhookEvent.gatewayEventId,
      });
      return NextResponse.json(
        { received: true, message: "Already processed" },
        { status: 200 },
      );
    }

    const gatewayPaymentIntentId =
      webhookEvent.gatewayPaymentIntentId ?? undefined;
    if (!gatewayPaymentIntentId) {
      logger.warn("Mercado Pago Webhook: no gatewayPaymentIntentId in event", {
        type: webhookEvent.type,
      });
      await paymentService.markWebhookEventAsProcessed(
        webhookEvent.gateway,
        webhookEvent.gatewayEventId,
      );
      return NextResponse.json(
        { received: true, message: "Event has no payment intent ID" },
        { status: 200 },
      );
    }

    const existingPayment =
      await paymentService.getPaymentByGatewayPaymentIntentId(
        gatewayPaymentIntentId,
      );

    if (!existingPayment) {
      logger.warn(
        "Mercado Pago Webhook: No existing payment found for gateway intent ID",
        { gatewayPaymentIntentId },
      );
      await paymentService.markWebhookEventAsProcessed(
        webhookEvent.gateway,
        webhookEvent.gatewayEventId,
      );
      return NextResponse.json(
        { received: true, message: "Payment not found internally" },
        { status: 200 },
      );
    }

    await paymentService.updatePaymentStatus(
      existingPayment.id,
      webhookEvent.status,
      webhookEvent.gatewayTransactionId ?? undefined,
      webhookEvent.metadata ?? undefined,
    );

    await paymentService.markWebhookEventAsProcessed(
      webhookEvent.gateway,
      webhookEvent.gatewayEventId,
    );

    if (webhookEvent.status === "succeeded" && existingPayment.order_id) {
      await paymentService.fulfillOrder(existingPayment.order_id);
      logger.info("Order fulfilled successfully via Mercado Pago Webhook", {
        orderId: existingPayment.order_id,
      });
    }

    if (
      webhookEvent.status === "succeeded" &&
      existingPayment.organization_id
    ) {
      await paymentService.applyPaymentSuccessToOrganization(
        existingPayment.organization_id,
        { ...existingPayment, status: "succeeded" },
        gatewayPaymentIntentId ?? null,
        webhookEvent.gatewayTransactionId ?? null,
      );
    }

    return NextResponse.json({ received: true }, { status: 200 });
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "Webhook processing failed";
    logger.error(
      "Error processing Mercado Pago Webhook",
      error instanceof Error ? error : new Error(message),
      {
        requestHeaders: Object.fromEntries(request.headers.entries()),
      },
    );
    return NextResponse.json(
      { error: "Webhook processing failed internally" },
      { status: 500 },
    );
  }
}

