                    </Link>
                  </div>
                  <div className="relative group">
                    <Input
                      id="password"
                      placeholder="••••••••"
                      type={showPassword ? "text" : "password"}
                      {...register("password")}
                      className={cn(
                        "h-14 rounded-xl border-epoch-primary/10 bg-epoch-background/50 pl-14 pr-14 focus:bg-white transition-all font-body text-epoch-primary shadow-inner",
                        errors.password &&
                          "border-red-900 focus-visible:ring-red-900",
                      )}
                      disabled={loading}
                    />
                    <Lock className="absolute left-5 top-1/2 -translate-y-1/2 h-5 w-5 text-epoch-primary/30 group-focus-within:text-epoch-primary transition-colors stroke-[1px]" />
                    <Button
                      className="absolute right-3 top-1/2 -translate-y-1/2 h-10 w-10 p-0 rounded-xl hover:bg-epoch-primary/5 text-epoch-primary/30"
                      disabled={loading}
                      size="sm"
                      type="button"
                      variant="ghost"
                      onClick={() => setShowPassword(!showPassword)}
                    >
                      {showPassword ? (
                        <EyeOff className="h-4 w-4 stroke-[1px]" />
                      ) : (
                        <Eye className="h-4 w-4 stroke-[1px]" />
                      )}
                    </Button>
                  </div>
                </div>

                <Button
                  className="w-full h-16 rounded-xl bg-epoch-primary hover:bg-epoch-surface text-white font-display font-bold uppercase text-[10px] sm:text-xs tracking-[0.2em] sm:tracking-[0.4em] group overflow-hidden transition-all duration-500 shadow-xl"
                  disabled={loading}
                  size="lg"
                  type="submit"
                >
                  {loading ? (
                    <Loader2 className="h-5 w-5 animate-spin" />
                  ) : (
                    <span className="flex items-center justify-center gap-2 sm:gap-3">
                      <span className="sm:hidden">Acceder</span>
                      <span className="hidden sm:inline">Iniciar sesión</span>
                      <ArrowRight className="h-4 w-4 transition-transform group-hover:translate-x-2 shrink-0" />
                    </span>
                  )}
                </Button>
              </form>

              <div className="mt-12 text-center pt-8 border-t border-epoch-primary/5">
                <p className="text-[10px] font-display font-bold text-epoch-primary/40 uppercase tracking-widest mb-6">
                  ¿Primera vez aquí?
                </p>
                <Link
                  className="inline-flex items-center gap-4 px-10 py-4 border border-epoch-primary/10 text-xs font-display font-bold text-epoch-primary uppercase tracking-[0.3em] hover:bg-epoch-primary hover:text-white transition-all duration-500 hover:-translate-y-1"
                  href={signupEnabled ? "/signup" : "/solicitar-demo"}
                >
                  {signupEnabled ? "Crear cuenta" : "Solicitar demo"}
                  <ArrowRight className="h-3 w-3" />
                </Link>
              </div>
            </CardContent>
          </Card>

          <div className="mt-12 flex justify-center gap-8 text-[9px] font-display font-bold text-epoch-primary/30 uppercase tracking-[0.3em]">
            <Link
              className="hover:text-epoch-accent transition-colors"
              href="#"
            >
              Soporte
            </Link>
            <Link
              className="hover:text-epoch-accent transition-colors"
              href="#"
            >
              Privacidad
            </Link>
            <Link
              className="hover:text-epoch-accent transition-colors"
              href="#"
            >
              Legales
            </Link>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import {
  ArrowRight,
  Building2,
  CheckCircle2,
  Loader2,
  Sparkles,
} from "lucide-react";
import Image from "next/image";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { useAuthContext } from "@/contexts/AuthContext";
import { appLogger } from '@/lib/logger';

export default function OnboardingChoicePage() {
  const router = useRouter();
  const { user, loading: authLoading, refetchAdminStatus } = useAuthContext();
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [hasOrganization, setHasOrganization] = useState<boolean | null>(null);

  // Redirigir a login si no hay usuario (en efecto, no durante render)
  useEffect(() => {
    if (authLoading) return;
    if (!user) {
      router.push("/login");
    }
  }, [user, authLoading, router]);

  // Verificar si el usuario ya tiene organización
  useEffect(() => {
    const checkOrganization = async () => {
      if (!user || authLoading) return;

      try {
        const response = await fetch("/api/admin/check-status", {
          credentials: "include",
        });
        const data = await response.json();

        // Root/dev users: ir directo al dashboard SaaS (no necesitan organización)
        if (data.organization?.isRootUser) {
          router.push("/admin/saas-management/dashboard");
          return;
        }

        if (data.organization?.hasOrganization) {
          // Ya tiene organización, redirigir al admin
          router.push("/admin");
          return;
        }

        setHasOrganization(false);
      } catch (err) {
        appLogger.error("Error checking organization status:", err);
        setHasOrganization(false);
      }
    };

    checkOrganization();
  }, [user, authLoading, router]);

  const handleDemoChoice = async () => {
    setIsLoading(true);
    setError(null);

    try {
      const response = await fetch("/api/onboarding/assign-demo", {
        method: "POST",
        credentials: "include",
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || "Error al asignar organización demo");
      }

      // Refrescar rol admin para que isSuperAdmin se reconozca sin reload
      await refetchAdminStatus();

      // Redirigir al admin con organización demo
      router.push("/admin");
    } catch (err: unknown) {
      setError(err.message || "Error al asignar organización demo");
      setIsLoading(false);
    }
  };

  const handleRealChoice = () => {
    router.push("/onboarding/create");
  };

  // Mostrar loading mientras se verifica autenticación
  if (authLoading || hasOrganization === null) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-epoch-background">
        <div className="text-center space-y-4">
          <Loader2 className="h-8 w-8 animate-spin mx-auto text-epoch-accent" />
          <p className="text-[10px] font-display font-bold text-epoch-primary/40 uppercase tracking-widest">
            Verificando identidad...
          </p>
        </div>
      </div>
    );
  }

  // Si no está autenticado, mostrar nada mientras el useEffect redirige
  if (!user) {
    return null;
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-epoch-background relative overflow-hidden px-4 py-12">
      {/* Premium Background Elements */}
      <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none z-0">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-epoch-accent/10 rounded-full blur-[120px] animate-premium-float" />
        <div
          className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-epoch-primary/5 rounded-full blur-[120px] animate-premium-float"
          style={{ animationDelay: "-2s" }}
        />
      </div>

      <div className="w-full max-w-5xl relative z-10">
        {/* Header */}
        <div className="text-center mb-16 animate-in fade-in slide-in-from-bottom-4 duration-1000">
          <div className="inline-flex items-center justify-center mb-10 relative group">
            <Image
              alt="Opttius"
              className="h-14 sm:h-16 md:h-20 w-auto max-w-[240px] relative z-10 transition-transform duration-500 group-hover:scale-105 object-contain"
              height={53}
              src="/OpttiusTextCentered-on-light.svg"
              width={240}
            />
          </div>
          <h1 className="text-5xl md:text-6xl font-display font-bold text-epoch-primary mb-4 tracking-tight uppercase">
            BIENVENIDO A{" "}
            <span className="text-epoch-accent italic font-serif lowercase tracking-normal">
              la orden
            </span>
          </h1>
          <p className="text-[11px] font-display font-bold text-epoch-primary/40 uppercase tracking-[0.5em] max-w-xl mx-auto">
            Configuración de Infraestructura Digital
          </p>
        </div>

        {error && (
          <Alert
            className="mb-8 animate-in zoom-in-95 duration-300"
            variant="destructive"
          >
            <AlertDescription>{error}</AlertDescription>
          </Alert>
        )}

        {/* Choice Cards */}
        <div className="grid md:grid-cols-2 gap-10 h-full">
          {/* Demo Option */}
          <Card
            className="flex flex-col h-full group bg-white border border-epoch-primary/5 rounded-xl shadow-premium hover:shadow-premium-xl hover:border-epoch-accent/30 transition-all duration-500 overflow-hidden"
            variant="interactive"
          >
            <div className="h-2 w-full bg-epoch-primary group-hover:bg-epoch-accent transition-colors duration-500" />
            <CardHeader
              className="border-b border-epoch-primary/5"
              padding="lg"
            >
              <div className="flex items-center justify-between mb-6">
                <div className="p-4 bg-epoch-primary/5 rounded-xl group-hover:bg-epoch-primary group-hover:text-white transition-all duration-500 shadow-sm">
                  <Sparkles className="h-8 w-8 text-epoch-primary group-hover:text-epoch-accent" />
                </div>
                <Badge className="bg-epoch-accent/10 text-epoch-accent border border-epoch-accent/20 px-3 py-1 font-display font-bold text-[9px] tracking-[0.2em] uppercase rounded-xl">
                  EXPERIENCIA INICIAL
                </Badge>
              </div>
              <CardTitle
                className="text-2xl font-display font-bold text-epoch-primary tracking-tight uppercase"
                size="lg"
              >
                Entorno de Prueba
              </CardTitle>
              <CardDescription
                className="mt-4 font-serif italic text-epoch-primary/60 text-[15px] leading-relaxed"
                size="lg"
              >
                Acceda al sistema con una arquitectura pre-configurada. Ideal
                para conocer la suite técnica de Opttius en segundos.
              </CardDescription>
            </CardHeader>
            <CardContent className="flex-1" padding="lg" spacing="relaxed">
              <div className="space-y-5 mb-10">
                {[
                  "Dashboard con analíticas realistas",
                  "Catálogo completo de armazones y micas",
                  "Flujo integrado de ventas y agenda",
                  "Sin compromiso, migre cuando esté listo",
                ].map((item, i) => (
                  <div className="flex items-start gap-4" key={i}>
                    <div className="mt-1 bg-epoch-accent/10 rounded-full p-1 border border-epoch-accent/20">
                      <CheckCircle2 className="h-3 w-3 text-epoch-accent" />
                    </div>
                    <span className="text-sm text-epoch-primary/70 font-medium">
                      {item}
                    </span>
                  </div>
                ))}
              </div>

              <Button
                className="w-full bg-epoch-primary hover:bg-epoch-surface text-white rounded-xl font-display font-bold uppercase text-[10px] tracking-[0.3em] h-14 transition-all shadow-xl group/btn overflow-hidden relative"
                disabled={isLoading}
                size="lg"
                onClick={handleDemoChoice}
              >
                <span className="relative z-10 flex items-center justify-center">
                  {isLoading ? (
                    <>
                      <Loader2 className="mr-2 h-5 w-5 animate-spin" />
                      SINCRONIZANDO...
                    </>
                  ) : (
                    <>
                      COMENZAR DEMO
                      <ArrowRight className="ml-2 h-5 w-5 group-hover/btn:translate-x-2 transition-transform" />
                    </>
                  )}
                </span>
                <div className="absolute inset-0 bg-epoch-accent translate-y-full group-hover/btn:translate-y-0 transition-transform duration-500 opacity-10" />
              </Button>
            </CardContent>
          </Card>

          {/* Real Option */}
          <Card
            className="flex flex-col h-full group bg-white border border-epoch-primary/5 rounded-xl shadow-premium hover:shadow-premium-xl hover:border-epoch-accent/30 transition-all duration-500 overflow-hidden"
            variant="interactive"
          >
            <div className="h-2 w-full bg-epoch-accent" />
            <CardHeader
              className="border-b border-epoch-primary/5"
              padding="lg"
            >
              <div className="flex items-center justify-between mb-6">
                <div className="p-4 bg-epoch-accent/5 rounded-xl group-hover:bg-epoch-accent group-hover:text-white transition-all duration-500 shadow-sm border border-epoch-accent/10">
                  <Building2 className="h-8 w-8 text-epoch-accent group-hover:text-epoch-primary" />
                </div>
                <Badge className="bg-epoch-primary/10 text-epoch-primary border border-epoch-primary/20 px-3 py-1 font-display font-bold text-[9px] tracking-[0.2em] uppercase rounded-xl">
                  PRODUCCIÓN REAL
                </Badge>
              </div>
              <CardTitle
                className="text-2xl font-display font-bold text-epoch-primary tracking-tight uppercase"
                size="lg"
              >
                Configurar mi Óptica
              </CardTitle>
              <CardDescription
                className="mt-4 font-serif italic text-epoch-primary/60 text-[15px] leading-relaxed"
                size="lg"
              >
                Inicie hoy mismo con su propia infraestructura digital.
                Configure su marca, sucursales y equipo de trabajo profesional.
              </CardDescription>
            </CardHeader>
            <CardContent className="flex-1" padding="lg" spacing="relaxed">
              <div className="space-y-5 mb-10">
                {[
                  "Firma e identidad única de su marca",
                  "Configuración de sedes y laboratorios",
                  "Personalización total de flujos de trabajo",
                  "Arquitectura escalable para crecimiento",
                ].map((item, i) => (
                  <div className="flex items-start gap-4" key={i}>
                    <div className="mt-1 bg-epoch-accent/10 rounded-full p-1 border border-epoch-accent/20">
                      <CheckCircle2 className="h-3 w-3 text-epoch-accent" />
                    </div>
                    <span className="text-sm text-epoch-primary/70 font-medium">
                      {item}
                    </span>
                  </div>
                ))}
              </div>

              <Button
                className="w-full bg-epoch-primary hover:bg-epoch-surface text-white rounded-xl font-display font-bold uppercase text-[10px] tracking-[0.3em] h-14 transition-all shadow-xl group/btn overflow-hidden relative"
                disabled={isLoading}
                size="lg"
                onClick={handleRealChoice}
              >
                <span className="relative z-10 flex items-center justify-center">
                  INICIAR PROTOCOLO
                  <ArrowRight className="ml-2 h-5 w-5 group-hover/btn:translate-x-2 transition-transform" />
                </span>
                <div className="absolute inset-0 bg-epoch-accent translate-y-full group-hover/btn:translate-y-0 transition-transform duration-500 opacity-10" />
              </Button>
            </CardContent>
          </Card>
        </div>

        {/* Footer */}
        <div className="mt-16 text-center animate-in fade-in duration-1000 delay-500">
          <p className="text-[10px] font-display font-bold text-epoch-primary/40 uppercase tracking-[0.3em] flex items-center justify-center gap-3">
            ¿Requiere asistencia especializada?{" "}
            <Link
              className="text-epoch-accent hover:text-epoch-primary transition-colors hover:underline underline-offset-4"
              href="/support"
            >
              Contactar Soporte de Élite
            </Link>
          </p>
        </div>
      </div>
    </div>
  );
}

"use client";

import { ArrowRight, Building2, CheckCircle2, Loader2 } from "lucide-react";
import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";

import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { useAuthContext } from "@/contexts/AuthContext";
import { appLogger } from '@/lib/logger';

export default function OnboardingCompletePage() {
  const router = useRouter();
  const { user, loading: authLoading, refetchAdminStatus } = useAuthContext();
  const [isLoading, setIsLoading] = useState(true);
  const [organizationInfo, setOrganizationInfo] = useState<{
    name: string;
    slug: string;
  } | null>(null);

  useEffect(() => {
    const fetchOrganizationInfo = async () => {
      if (!user || authLoading) return;

      try {
        const response = await fetch("/api/admin/check-status");
        const data = await response.json();

        if (data.organization?.hasOrganization) {
          // Obtener información de la organización usando el endpoint GET
          const orgResponse = await fetch("/api/admin/organizations");
          if (orgResponse.ok) {
            const orgData = await orgResponse.json();
            if (orgData.organization) {
              setOrganizationInfo({
                name: orgData.organization.name,
                slug: orgData.organization.slug,
              });
            }
          } else {
            appLogger.warn(
              "Could not fetch organization details:",
              orgResponse.status,
            );
          }
        }

        setIsLoading(false);
      } catch (err) {
        appLogger.error("Error fetching organization info:", err);
        setIsLoading(false);
      }
    };

    fetchOrganizationInfo();
  }, [user, authLoading]);

  const handleGoToAdmin = async () => {
    // Refrescar rol admin para que isSuperAdmin se reconozca sin reload
    await refetchAdminStatus();
    // Usar router.push en lugar de full reload para preservar la sesión.
    // router.refresh() invalida la caché de Next.js (branches, notifications).
    router.refresh();
    router.push("/admin");
  };

  // Mostrar loading mientras se verifica autenticación
  if (authLoading || isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[var(--admin-bg-primary)]">
        <div className="text-center space-y-4">
          <Loader2 className="h-8 w-8 animate-spin mx-auto text-blue-600" />
          <p className="text-gray-600">Preparando tu entorno...</p>
        </div>
      </div>
    );
  }

  // Si no está autenticado, redirigir a login
  if (!user) {
    router.push("/login");
    return null;
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-[var(--admin-bg-primary)] px-4 py-12">
      <div className="w-full max-w-md">
        <Card className="border-0 shadow-2xl">
          <CardHeader className="space-y-1 pb-6 text-center">
            <div className="inline-flex items-center justify-center w-20 h-20 bg-green-100 rounded-full mb-4">
              <CheckCircle2 className="h-10 w-10 text-green-600" />
            </div>
            <CardTitle className="text-2xl font-bold text-gray-900">
              ¡Tu óptica está lista!
            </CardTitle>
            <CardDescription className="text-gray-600 text-base">
              Ya puedes usar el panel de administración
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-6">
            {organizationInfo && (
              <div className="bg-[var(--admin-border-primary)] border border-[var(--accent-foreground)] rounded-lg p-4 space-y-2">
                <div className="flex items-center gap-2 text-blue-900">
                  <Building2 className="h-5 w-5" />
                  <span className="font-semibold">{organizationInfo.name}</span>
                </div>
                <p className="text-sm text-blue-700">
                  Identificador:{" "}
                  <code className="bg-blue-100 px-1 rounded">
                    {organizationInfo.slug}
                  </code>
                </p>
              </div>
            )}

            <div className="space-y-3">
              <p className="text-sm text-gray-600 text-center">
                Tu organización ha sido creada exitosamente. Ahora puedes:
              </p>
              <ul className="text-sm text-gray-600 space-y-2">
                <li className="flex items-start">
                  <CheckCircle2 className="h-4 w-4 text-green-500 mr-2 mt-0.5 flex-shrink-0" />
                  <span>Gestionar productos e inventario</span>
                </li>
                <li className="flex items-start">
                  <CheckCircle2 className="h-4 w-4 text-green-500 mr-2 mt-0.5 flex-shrink-0" />
                  <span>Crear y gestionar clientes</span>
                </li>
                <li className="flex items-start">
                  <CheckCircle2 className="h-4 w-4 text-green-500 mr-2 mt-0.5 flex-shrink-0" />
                  <span>Agendar citas y crear presupuestos</span>
                </li>
                <li className="flex items-start">
                  <CheckCircle2 className="h-4 w-4 text-green-500 mr-2 mt-0.5 flex-shrink-0" />
                  <span>Procesar ventas en el punto de venta</span>
                </li>
              </ul>
            </div>

            <Button
              className="w-full bg-[var(--accent-foreground)]"
              size="lg"
              onClick={handleGoToAdmin}
            >
              Ir al panel
              <ArrowRight className="ml-2 h-4 w-4" />
            </Button>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

"use client";

import { zodResolver } from "@hookform/resolvers/zod";
import {
  AlertCircle,
  ArrowRight,
  Building2,
  CheckCircle2,
  Loader2,
  XCircle,
} from "lucide-react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";
import { useForm } from "react-hook-form";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useAuthContext } from "@/contexts/AuthContext";
import { useSlugValidation } from "@/hooks/useSlugValidation";
import {
  type CreateOrganizationInput,
  createOrganizationSchema,
} from "@/lib/api/validation/organization-schemas";
import { appLogger } from '@/lib/logger';
import { cn } from "@/lib/utils";
import { generateSlug } from "@/lib/utils/slug-generator";

export default function CreateOrganizationPage() {
  const router = useRouter();
  const { user, loading: authLoading } = useAuthContext();
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [hasOrganization, setHasOrganization] = useState<boolean | null>(null);

  const {
    register,
    handleSubmit,
    watch,
    setValue,
    getValues,
    formState: { errors },
  } = useForm<CreateOrganizationInput>({
    resolver: zodResolver(createOrganizationSchema),
    defaultValues: {
      subscription_tier: "pro",
      branchName: "Casa Matriz",
    },
  });

  const slug = watch("slug");

  // Validación en vivo del slug
  const slugValidation = useSlugValidation(slug || "");

  // Generar slug solo cuando el usuario termina de escribir en "Nombre comercial" (onBlur)
  const handleNameBlur = () => {
    const name = getValues("name");
    if (name && name.trim().length > 0) {
      const autoSlug = generateSlug(name);
      if (autoSlug && autoSlug.length > 0) {
        setValue("slug", autoSlug);
      }
    }
  };

  // Verificar si el usuario ya tiene organización
  useEffect(() => {
    const checkOrganization = async () => {
      if (!user || authLoading) return;

      try {
        const response = await fetch("/api/admin/check-status");
        const data = await response.json();

        if (
          data.organization?.hasOrganization &&
          !data.organization?.isDemoMode
        ) {
          // Ya tiene organización real, redirigir al admin
          router.push("/admin");
          return;
        }

        setHasOrganization(data.organization?.hasOrganization || false);
      } catch (err) {
        appLogger.error("Error checking organization status:", err);
        setHasOrganization(false);
      }
    };

    checkOrganization();
  }, [user, authLoading, router]);

  const onSubmit = async (data: CreateOrganizationInput) => {
    // Validar que el slug esté disponible antes de enviar
    if (slugValidation.isAvailable === false) {
      setError("El identificador no está disponible. Por favor, elige otro.");
      return;
    }

    if (slugValidation.isValidating) {
      setError("Espera a que termine la validación del identificador.");
      return;
    }

    setIsSubmitting(true);
    setError(null);

    try {
      const endpoint = hasOrganization
        ? "/api/onboarding/activate-real-org"
        : "/api/admin/organizations";

      const response = await fetch(endpoint, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(data),
      });

      const result = await response.json();

      if (!response.ok) {
        // Mostrar detalles del error si están disponibles
        const errorMessage = result.details
          ? `${result.error}: ${result.details}`
          : result.error || "Error al crear la organización";

        appLogger.error("❌ Error creating organization:", {
          status: response.status,
          error: result.error,
          details: result.details,
          code: result.code,
          hint: result.hint,
          fullResponse: result,
        });

        throw new Error(errorMessage);
      }

      // Redirigir a página de completado
      router.push("/onboarding/complete");
    } catch (err: unknown) {
      setError(err.message || "Error al crear la organización");
      setIsSubmitting(false);
    }
  };

  // Mostrar loading mientras se verifica autenticación
  if (authLoading || hasOrganization === null) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-slate-50 via-blue-50 to-indigo-100">
        <div className="text-center space-y-4">
          <Loader2 className="h-8 w-8 animate-spin mx-auto text-blue-600" />
          <p className="text-gray-600">Verificando estado...</p>
        </div>
      </div>
    );
  }

  // Si no está autenticado, redirigir a login
  if (!user) {
    router.push("/login");
    return null;
  }

  const isSlugValid = slugValidation.isAvailable === true;
  const isSlugInvalid = slugValidation.isAvailable === false;
  const showSlugValidation = slug && slug.length >= 2;

  return (
    <div className="min-h-screen flex items-center justify-center bg-[var(--admin-bg-primary)] relative overflow-hidden px-4 py-12">
      {/* Premium Background Elements */}
      <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none z-0">
        <div className="absolute top-[-10%] right-[-10%] w-[40%] h-[40%] bg-primary/5 rounded-full blur-[120px] animate-premium-float" />
        <div
          className="absolute bottom-[-10%] left-[-10%] w-[40%] h-[40%] bg-indigo-500/5 rounded-full blur-[120px] animate-premium-float"
          style={{ animationDelay: "-2s" }}
        />
      </div>

      <div className="w-full max-w-2xl relative z-10">
        {/* Header */}
        <div className="text-center mb-10 animate-in fade-in slide-in-from-bottom-4 duration-700">
          <div className="inline-flex items-center justify-center w-20 h-20 bg-[var(--admin-border-primary)] rounded-[2rem] shadow-2xl mb-6 relative group">
            <div className="absolute inset-0 bg-[var(--admin-bg-tertiary)] rounded-[2rem] scale-90 group-hover:scale-110 transition-transform duration-500" />
            <Building2 className="h-10 w-10 text-primary relative z-10" />
          </div>
          <h1 className="text-4xl font-bold text-slate-900 dark:text-white mb-3 tracking-tight">
            {hasOrganization ? "Activar tu Óptica" : "Configura tu Óptica"}
          </h1>
          <p className="text-slate-600 dark:text-slate-400 max-w-md mx-auto">
            {hasOrganization
              ? "Estamos a un paso de comenzar. Completa los detalles finales para activar tu entorno profesional."
              : "Definamos la identidad de tu organización en el sistema Opttius."}
          </p>
        </div>

        <Card
          className="border-0 shadow-2xl overflow-visible"
          variant="elevated"
        >
          <CardHeader padding="lg">
            <CardTitle size="lg" theme="modern">
              Identidad de la Organización
            </CardTitle>
            <CardDescription className="text-accent-foreground" size="lg">
              Esta información será la base de tu perfil empresarial y aparecerá
              en tus documentos oficiales.
            </CardDescription>
          </CardHeader>
          <CardContent padding="lg" spacing="relaxed">
            <form className="space-y-8" onSubmit={handleSubmit(onSubmit)}>
              {error && (
                <Alert
                  className="animate-in zoom-in-95 duration-300"
                  variant="destructive"
                >
                  <AlertCircle className="h-4 w-4" />
                  <AlertDescription>{error}</AlertDescription>
                </Alert>
              )}

              <div className="grid gap-8">
                {/* Nombre de la organización */}
                <div className="space-y-3">
                  <Label
                    className="text-sm font-bold text-slate-700 dark:text-slate-300"
                    htmlFor="name"
                  >
                    Nombre comercial <span className="text-red-500">*</span>
                  </Label>
                  <div className="relative group">
                    <Input
                      id="name"
                      {...register("name", {
                        onBlur: handleNameBlur,
                      })}
                      className={cn(
                        "h-12 bg-[var(--admin-bg-primary)] border-[var(--admin-border-secondary)] transition-all focus:ring-4 focus:ring-primary/10",
                        errors.name && "border-red-500 focus:ring-red-500/10",
                      )}
                      disabled={isSubmitting}
                      placeholder="Ej. Óptica Visión Premium"
                    />
                  </div>
                  {errors.name && (
                    <p className="text-xs font-medium text-red-500 flex items-center gap-1">
                      <XCircle className="h-3 w-3" />{" "}
                      {String(errors.name.message)}
                    </p>
                  )}
                </div>

                {/* Slug */}
                <div className="space-y-3">
                  <div className="flex items-center justify-between">
                    <Label
                      className="text-sm font-bold text-slate-700 dark:text-slate-300"
                      htmlFor="slug"
                    >
                      Identificador de URL (slug){" "}
                      <span className="text-red-500">*</span>
                    </Label>
                    {isSlugValid && (
                      <Badge
                        className="bg-green-500/10 text-green-600 border-none px-2 text-[10px]"
                        variant="healty"
                      >
                        ✓ Disponible
                      </Badge>
                    )}
                  </div>
                  <div className="relative">
                    <Input
                      id="slug"
                      {...register("slug")}
                      className={cn(
                        "h-12 bg-[var(--admin-bg-primary)] border-[var(--admin-border-secondary)] transition-all focus:ring-4 focus:ring-primary/10 pr-12",
                        (errors.slug || isSlugInvalid) &&
                          "border-red-500 focus:ring-red-500/10",
                        isSlugValid &&
                          "border-green-500/50 focus:ring-green-500/5",
                      )}
                      disabled={isSubmitting}
                      placeholder="vision-premium"
                    />
                    {showSlugValidation && (
                      <div className="absolute right-4 top-1/2 -translate-y-1/2 transition-all">
                        {slugValidation.isValidating ? (
                          <Loader2 className="h-5 w-5 animate-spin text-primary" />
                        ) : isSlugValid ? (
                          <CheckCircle2 className="h-5 w-5 text-green-500" />
                        ) : isSlugInvalid ? (
                          <XCircle className="h-5 w-5 text-red-500" />
                        ) : null}
                      </div>
                    )}
                  </div>
                  {errors.slug && (
                    <p className="text-xs font-medium text-red-500">
                      {String(errors.slug.message)}
                    </p>
                  )}
                  {slugValidation.error && (
                    <p className="text-xs font-medium text-red-500">
                      {slugValidation.error}
                    </p>
                  )}
                  <p className="text-[11px] text-slate-500 font-medium leading-relaxed">
                    Tu acceso será:{" "}
                    <span className="text-primary font-bold">
                      opttius.com/{slug || "..."}
                    </span>
                    . Solo letras minúsculas y guiones.
                  </p>
                </div>

                {/* Nombre de primera sucursal */}
                <div className="space-y-3">
                  <Label
                    className="text-sm font-bold text-slate-700 dark:text-slate-300"
                    htmlFor="branchName"
                  >
                    Nombre de tu primera sucursal
                  </Label>
                  <Input
                    id="branchName"
                    {...register("branchName")}
                    className="h-12 bg-[var(--admin-bg-primary)] border-[var(--admin-border-secondary)] transition-all focus:ring-4 focus:ring-primary/10"
                    disabled={isSubmitting}
                    placeholder="Ej. Sucursal Central o Casa Matriz"
                  />
                  <p className="text-[11px] text-slate-500 font-medium italic">
                    Puedes crear más sucursales después en la configuración.
                  </p>
                </div>
              </div>

              {/* Botones */}
              <div className="flex flex-col sm:flex-row gap-4 pt-6">
                <Button
                  className="flex-1 min-w-0 h-12 border-2 bg-[var(--admin-bg-tertiary)] border-[var(--admin-accent-primary)]"
                  disabled={isSubmitting}
                  type="button"
                  variant="outline"
                  onClick={() => router.back()}
                >
                  Regresar
                </Button>
                <Button
                  shimmer
                  className="flex-1 min-w-0 h-12 shadow-xl shadow-primary/20 overflow-hidden"
                  disabled={
                    isSubmitting ||
                    slugValidation.isValidating ||
                    slugValidation.isAvailable === false
                  }
                  type="submit"
                >
                  {isSubmitting ? (
                    <>
                      <Loader2 className="mr-2 h-5 w-5 shrink-0 animate-spin" />
                      Procesando...
                    </>
                  ) : (
                    <>
                      <span className="min-w-0 truncate">
                        {hasOrganization
                          ? "Activar Ahora"
                          : "Crear Organización"}
                      </span>
                      <ArrowRight className="ml-2 h-5 w-5 shrink-0" />
                    </>
                  )}
                </Button>
              </div>
            </form>
          </CardContent>
        </Card>

        {/* Footer */}
        <div className="mt-10 text-center animate-in fade-in duration-1000 delay-300">
          <p className="text-sm text-slate-500 dark:text-slate-500 font-medium">
            ¿Solo quieres dar un vistazo?{" "}
            <Link
              className="text-primary hover:text-primary/80 font-bold hover:underline transition-all"
              href="/onboarding/choice"
            >
              Explorar demo primero
            </Link>
          </p>
        </div>
      </div>
    </div>
  );
}

"use client";

import {
  AlertTriangle,
  ArrowLeft,
  CheckCircle,
  Eye,
  Package,
} from "lucide-react";
import Image from "next/image";
import Link from "next/link";
import { useParams, useRouter } from "next/navigation";
import { useEffect, useState } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { appLogger } from '@/lib/logger';

interface Product {
  id: string;
  name: string;
  slug: string;
  description: string | null;
  short_description: string | null;
  price: number;
  compare_at_price: number | null;
  inventory_quantity: number;
  status: string;
  featured_image: string | null;
  gallery: string[];
  is_featured: boolean;
  category?: { name: string; slug: string };
  categories?: { name: string; slug: string };
  product_type?: string;
  frame_type?: string;
  frame_material?: string;
  frame_shape?: string;
  frame_color?: string;
  lens_type?: string;
  lens_material?: string;
  sku?: string;
  brand?: string;
  created_at: string;
}

export default function ProductPage() {
  const params = useParams();
  const router = useRouter();
  const slug = params?.slug as string;

  const [product, setProduct] = useState<Product | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);

  useEffect(() => {
    if (slug) {
      fetchProduct();
    }
  }, [slug]);

  const fetchProduct = async () => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetch(`/api/products/${slug}`);

      if (!response.ok) {
        if (response.status === 404) {
          setError("Producto no encontrado");
        } else {
          setError("Error al cargar el producto");
        }
        return;
      }

      const data = await response.json();
      setProduct(data.product);

      // Set initial selected image
      if (data.product.featured_image) {
        setSelectedImage(data.product.featured_image);
      } else if (data.product.gallery && data.product.gallery.length > 0) {
        setSelectedImage(data.product.gallery[0]);
      }
    } catch (err) {
      appLogger.error("Error fetching product:", err);
      setError("Error al cargar el producto");
    } finally {
      setLoading(false);
    }
  };

  const formatPrice = (price: number) => {
    return new Intl.NumberFormat("es-AR", {
      style: "currency",
      currency: "ARS",
    }).format(price);
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-b from-admin-bg-primary to-admin-bg-secondary p-6">
        <div className="max-w-7xl mx-auto">
          <div className="flex items-center justify-center min-h-[60vh]">
            <div className="text-center">
              <Package className="h-12 w-12 text-azul-profundo animate-pulse mx-auto mb-4" />
              <p className="text-tierra-media">Cargando producto...</p>
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (error || !product) {
    return (
      <div className="min-h-screen bg-gradient-to-b from-admin-bg-primary to-admin-bg-secondary p-6">
        <div className="max-w-7xl mx-auto">
          <Button
            className="mb-6"
            variant="outline"
            onClick={() => router.back()}
          >
            <ArrowLeft className="h-4 w-4 mr-2" />
            Volver
          </Button>

          <Card className="bg-admin-bg-tertiary">
            <CardContent className="p-12 text-center">
              <AlertTriangle className="h-16 w-16 text-red-500 mx-auto mb-4" />
              <h1 className="text-2xl font-bold text-azul-profundo mb-2">
                {error || "Producto no encontrado"}
              </h1>
              <p className="text-tierra-media mb-6">
                El producto que buscas no existe o no está disponible.
              </p>
              <Button onClick={() => router.push("/")}>Ir al inicio</Button>
            </CardContent>
          </Card>
        </div>
      </div>
    );
  }

  const categoryName =
    product.categories?.name || product.category?.name || "Sin categoría";
  const hasDiscount =
    product.compare_at_price && product.compare_at_price > product.price;
  const discountPercentage = hasDiscount
    ? Math.round(
        ((product.compare_at_price! - product.price) /
          product.compare_at_price!) *
          100,
      )
    : 0;
  const inStock = product.inventory_quantity > 0;

  return (
    <div className="min-h-screen bg-gradient-to-b from-admin-bg-primary to-admin-bg-secondary p-6">
      <div className="max-w-7xl mx-auto">
        {/* Back Button */}
        <Button
          className="mb-6"
          variant="outline"
          onClick={() => router.back()}
        >
          <ArrowLeft className="h-4 w-4 mr-2" />
          Volver
        </Button>

        {/* Product Details */}
        <Card className="bg-admin-bg-tertiary shadow-lg">
          <CardContent className="p-6">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              {/* Images Section */}
              <div className="space-y-4">
                {/* Main Image */}
                <div className="relative aspect-square bg-white rounded-lg overflow-hidden border-2 border-gray-200">
                  {selectedImage ? (
                    <Image
                      fill
                      priority
                      alt={product.name}
                      className="object-contain p-4"
                      src={selectedImage}
                    />
                  ) : (
                    <div className="flex items-center justify-center h-full">
                      <Package className="h-24 w-24 text-gray-300" />
                    </div>
                  )}
                </div>

                {/* Gallery Thumbnails */}
                {product.gallery && product.gallery.length > 0 && (
                  <div className="grid grid-cols-4 gap-2">
                    {product.featured_image && (
                      <button
                        className={`relative aspect-square rounded-lg overflow-hidden border-2 ${
                          selectedImage === product.featured_image
                            ? "border-azul-profundo"
                            : "border-gray-200"
                        }`}
                        onClick={() =>
                          setSelectedImage(product.featured_image!)
                        }
                      >
                        <Image
                          fill
                          alt={product.name}
                          className="object-cover"
                          src={product.featured_image}
                        />
                      </button>
                    )}
                    {product.gallery.map((image, index) => (
                      <button
                        className={`relative aspect-square rounded-lg overflow-hidden border-2 ${
                          selectedImage === image
                            ? "border-azul-profundo"
                            : "border-gray-200"
                        }`}
                        key={index}
                        onClick={() => setSelectedImage(image)}
                      >
                        <Image
                          fill
                          alt={`${product.name} - Imagen ${index + 1}`}
                          className="object-cover"
                          src={image}
                        />
                      </button>
                    ))}
                  </div>
                )}
              </div>

              {/* Product Info Section */}
              <div className="space-y-6">
                {/* Category & Featured Badge */}
                <div className="flex items-center gap-2 flex-wrap">
                  <Badge variant="outline">{categoryName}</Badge>
                  {product.is_featured && (
                    <Badge className="bg-dorado text-azul-profundo">
                      Destacado
                    </Badge>
                  )}
                  {hasDiscount && (
                    <Badge variant="destructive">
                      -{discountPercentage}% OFF
                    </Badge>
                  )}
                </div>

                {/* Product Name */}
                <h1 className="text-3xl font-bold text-azul-profundo">
                  {product.name}
                </h1>

                {/* Short Description */}
                {product.short_description && (
                  <p className="text-lg text-tierra-media">
                    {product.short_description}
                  </p>
                )}

                {/* Price */}
                <div className="space-y-2">
                  <div className="flex items-baseline gap-3">
                    <span className="text-4xl font-bold text-verde-suave">
                      {formatPrice(product.price)}
                    </span>
                    {hasDiscount && (
                      <span className="text-xl text-tierra-media line-through">
                        {formatPrice(product.compare_at_price!)}
                      </span>
                    )}
                  </div>
                </div>

                {/* Stock Status */}
                <div className="flex items-center gap-2">
                  {inStock ? (
                    <>
                      <CheckCircle className="h-5 w-5 text-verde-suave" />
                      <span className="text-verde-suave font-medium">
                        En stock ({product.inventory_quantity} unidades
                        disponibles)
                      </span>
                    </>
                  ) : (
                    <>
                      <AlertTriangle className="h-5 w-5 text-red-500" />
                      <span className="text-red-500 font-medium">
                        Sin stock
                      </span>
                    </>
                  )}
                </div>

                {/* SKU & Brand */}
                <div className="grid grid-cols-2 gap-4 text-sm">
                  {product.sku && (
                    <div>
                      <span className="text-tierra-media">SKU: </span>
                      <span className="font-medium">{product.sku}</span>
                    </div>
                  )}
                  {product.brand && (
                    <div>
                      <span className="text-tierra-media">Marca: </span>
                      <span className="font-medium">{product.brand}</span>
                    </div>
                  )}
                </div>

                {/* Product Type Specific Info */}
                {product.product_type === "frame" && (
                  <div className="space-y-2 p-4 bg-white/50 rounded-lg">
                    <h3 className="font-semibold text-azul-profundo mb-2">
                      Especificaciones del Marco
                    </h3>
                    <div className="grid grid-cols-2 gap-2 text-sm">
                      {product.frame_type && (
                        <div>
                          <span className="text-tierra-media">Tipo: </span>
                          <span className="font-medium">
                            {product.frame_type}
                          </span>
                        </div>
                      )}
                      {product.frame_material && (
                        <div>
                          <span className="text-tierra-media">Material: </span>
                          <span className="font-medium">
                            {product.frame_material}
                          </span>
                        </div>
                      )}
                      {product.frame_shape && (
                        <div>
                          <span className="text-tierra-media">Forma: </span>
                          <span className="font-medium">
                            {product.frame_shape}
                          </span>
                        </div>
                      )}
                      {product.frame_color && (
                        <div>
                          <span className="text-tierra-media">Color: </span>
                          <span className="font-medium">
                            {product.frame_color}
                          </span>
                        </div>
                      )}
                    </div>
                  </div>
                )}

                {product.product_type === "lens" && (
                  <div className="space-y-2 p-4 bg-white/50 rounded-lg">
                    <h3 className="font-semibold text-azul-profundo mb-2">
                      Especificaciones de la Lente
                    </h3>
                    <div className="grid grid-cols-2 gap-2 text-sm">
                      {product.lens_type && (
                        <div>
                          <span className="text-tierra-media">Tipo: </span>
                          <span className="font-medium">
                            {product.lens_type}
                          </span>
                        </div>
                      )}
                      {product.lens_material && (
                        <div>
                          <span className="text-tierra-media">Material: </span>
                          <span className="font-medium">
                            {product.lens_material}
                          </span>
                        </div>
                      )}
                    </div>
                  </div>
                )}

                {/* Actions */}
                <div className="flex gap-4 pt-4">
                  <Button
                    asChild
                    className="w-full"
                    size="lg"
                    variant="outline"
                  >
                    <Link href={`/admin/products/edit/${product.id}`}>
                      <Eye className="h-5 w-5 mr-2" />
                      Ver en Admin
                    </Link>
                  </Button>
                </div>
              </div>
            </div>

            {/* Description Section */}
            {product.description && (
              <div className="mt-8 pt-8 border-t border-gray-200">
                <h2 className="text-2xl font-bold text-azul-profundo mb-4">
                  Descripción
                </h2>
                <div
                  className="prose max-w-none text-tierra-media"
                  dangerouslySetInnerHTML={{ __html: product.description }}
                />
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

"use client";

import { zodResolver } from "@hookform/resolvers/zod";
import {
  ArrowLeft,
  ArrowRight,
  CheckCircle2,
  Loader2,
  Lock,
  Mail,
  ShieldCheck,
} from "lucide-react";
import Image from "next/image";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";
import { useForm } from "react-hook-form";
import * as z from "zod";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useAuthContext } from "@/contexts/AuthContext";
import { cn } from "@/lib/utils";
import { createClient } from "@/utils/supabase/client";

const requestSchema = z.object({
  email: z.string().email("Por favor ingresa un email válido"),
});

const updateSchema = z
  .object({
    password: z
      .string()
      .min(6, "La contraseña debe tener al menos 6 caracteres"),
    confirmPassword: z.string(),
  })
  .refine((data) => data.password === data.confirmPassword, {
    message: "Las contraseñas no coinciden",
    path: ["confirmPassword"],
  });

type RequestForm = z.infer<typeof requestSchema>;
type UpdateForm = z.infer<typeof updateSchema>;

export default function ResetPasswordPage() {
  const router = useRouter();
  const { resetPassword, loading: authLoading } = useAuthContext();
  const [step, setStep] = useState<"request" | "sent" | "update">("request");
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<boolean>(false);
  const [isUpdating, setIsUpdating] = useState(false);
  const [isInviteFlow, setIsInviteFlow] = useState(false);
  const [isEstablishingSession, setIsEstablishingSession] = useState(false);

  // Check if we are in recovery or invite mode (set password flow)
  useEffect(() => {
    const checkRecoveryOrInvite = async () => {
      const supabase = createClient();
      const hash = window.location.hash;
      const isRecovery = hash.includes("type=recovery");
      const isInvite = hash.includes("type=invite");

      // Hash with tokens: establish session explicitly before showing form
      if (isRecovery || isInvite) {
        const params = new URLSearchParams(hash.substring(1));
        const accessToken = params.get("access_token");
        const refreshToken = params.get("refresh_token");

        if (!accessToken || !refreshToken) {
          setError(
            "Enlace inválido o expirado. Solicita uno nuevo desde la página de recuperación.",
          );
          return;
        }

        setIsEstablishingSession(true);
        setError(null);

        const { error: setSessionError } = await supabase.auth.setSession({
          access_token: accessToken,
          refresh_token: refreshToken,
        });

        setIsEstablishingSession(false);

        if (setSessionError) {
          setError(
            "Enlace inválido o expirado. Solicita uno nuevo desde la página de recuperación.",
          );
          return;
        }

        setIsInviteFlow(isInvite);
        setStep("update");
        // Clear hash from URL to avoid token exposure in history
        window.history.replaceState(null, "", window.location.pathname);
        return;
      }

      // No hash: check if session already exists (e.g. PASSWORD_RECOVERY already processed)
      const {
        data: { session },
      } = await supabase.auth.getSession();
      if (session && !session.user.is_anonymous) {
        setIsInviteFlow(false);
        setStep("update");
      }
    };

    checkRecoveryOrInvite();

    const supabase = createClient();
    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange(async (event) => {
      if (event === "PASSWORD_RECOVERY") {
        setIsInviteFlow(false);
        setStep("update");
      }
      if (
        event === "SIGNED_IN" &&
        window.location.hash.includes("type=invite")
      ) {
        setIsInviteFlow(true);
        setStep("update");
      }
    });

    return () => {
      subscription.unsubscribe();
    };
  }, []);

  const requestForm = useForm<RequestForm>({
    resolver: zodResolver(requestSchema),
  });

  const updateForm = useForm<UpdateForm>({
    resolver: zodResolver(updateSchema),
  });

  const onRequestSubmit = async (data: RequestForm) => {
    try {
      setError(null);
      await resetPassword(data.email);
      setStep("sent");
    } catch (err: unknown) {
      setError(err.message || "Error al enviar el correo de recuperación");
    }
  };

  const onUpdateSubmit = async (data: UpdateForm) => {
    try {
      setError(null);
      setIsUpdating(true);
      const supabase = createClient();

      const {
        data: { session },
      } = await supabase.auth.getSession();
      if (!session) {
        setError("La sesión ha expirado. Por favor, solicita un nuevo enlace.");
        return;
      }

      const { error } = await supabase.auth.updateUser({
        password: data.password,
      });

      if (error) throw error;

      setSuccess(true);
      setTimeout(() => {
        router.push(isInviteFlow ? "/admin" : "/login");
      }, 3000);
    } catch (err: unknown) {
      setError(err.message || "Error al actualizar la contraseña");
    } finally {
      setIsUpdating(false);
    }
  };

  return (
    <div className="min-h-screen min-h-[100dvh] flex flex-col md:flex-row bg-epoch-background overflow-hidden relative">
      {/* Visual Side (Desktop) - matches login */}
      <div className="relative hidden lg:flex lg:w-1/2 xl:w-7/12 overflow-hidden items-center justify-center bg-epoch-surface">
        <div className="absolute inset-0 z-0">
          <Image
            fill
            priority
            alt="Vintage Optics"
            className="object-cover opacity-30 grayscale"
            src="/images/landing/Hero.webp"
          />
          <div className="absolute inset-0 bg-gradient-to-tr from-epoch-primary via-epoch-primary/40 to-transparent" />
        </div>

        <div className="relative z-10 p-12 xl:p-20 w-full h-full flex flex-col justify-between">
          <Link className="group flex flex-col items-start w-fit" href="/">
            <div className="relative mb-1 group-hover:scale-110 transition-transform duration-500">
              <Image
                alt="Opttius"
                className="h-14 w-48 opacity-100 object-contain object-left"
                height={56}
                src="/logo-text-default.svg"
                width={192}
              />
            </div>
          </Link>

          <div className="max-w-xl animate-in fade-in slide-in-from-left-10 duration-1000">
            <h2 className="text-5xl xl:text-6xl font-display font-bold text-white leading-tight tracking-tight mb-8">
              Recupera tu
              <br />
              <span className="text-epoch-accent italic font-serif lowercase tracking-normal">
                acceso seguro
              </span>
            </h2>
            <div className="w-24 h-[1px] bg-epoch-accent mb-8" />
            <p className="text-lg xl:text-xl text-white/70 font-serif italic tracking-wide leading-relaxed">
              Restablece tu contraseña de forma segura y vuelve a gestionar tu
              óptica.
            </p>
          </div>

          <div className="flex items-center gap-8 text-white/30 text-[9px] font-display uppercase tracking-[0.4em]">
            <span className="flex items-center gap-2">
              <div className="w-1 h-1 rounded-full bg-epoch-accent animate-pulse" />
              SISTEMA DE ÉLITE
            </span>
            <span>V3.0.0</span>
          </div>
        </div>
      </div>

      {/* Form Side - mobile-first, touch-optimized */}
      <div className="flex-1 flex flex-col justify-center items-center p-4 sm:p-6 md:p-12 lg:p-20 relative z-10 overflow-y-auto min-h-0">
        <div className="w-full max-w-md animate-in fade-in slide-in-from-bottom-10 duration-700 py-4 sm:py-0">
          {/* Mobile logo - visible when left panel hidden */}
          <div className="lg:hidden mb-8 flex justify-center">
            <Link className="group" href="/">
              <Image
                alt="Opttius"
                className="h-12 w-40 sm:h-14 sm:w-48 opacity-100 object-contain group-hover:opacity-90 transition-opacity"
                height={48}
                src="/logo-text-default.svg"
                width={160}
              />
            </Link>
          </div>

          <div className="text-center mb-8 sm:mb-10 lg:text-left space-y-3">
            <div className="inline-flex items-center gap-4 px-4 sm:px-6 py-2 border border-epoch-primary/10 rounded-full text-epoch-primary/60 text-[10px] font-display tracking-[0.3em] sm:tracking-[0.4em] uppercase">
              {step === "update"
                ? isInviteFlow
                  ? "Tu demo está lista"
                  : "Actualizar contraseña"
                : "Recuperación de cuenta"}
            </div>
            <h1 className="text-2xl sm:text-3xl md:text-4xl lg:text-5xl font-display font-bold text-epoch-primary tracking-tight">
              {step === "sent"
                ? "Correo enviado"
                : step === "update"
                  ? isInviteFlow
                    ? "Crea tu contraseña"
                    : "Nueva contraseña"
                  : "¿Olvidaste tu contraseña?"}
            </h1>
            <p className="text-epoch-primary/60 font-display font-bold uppercase text-[10px] tracking-[0.2em] sm:tracking-widest leading-relaxed">
              {step === "sent"
                ? "Revisa tu bandeja de entrada para continuar."
                : step === "update"
                  ? isInviteFlow
                    ? "Tu demo de Opttius está lista. Crea una contraseña para acceder."
                    : "Ingresa tu nueva contraseña para restablecer el acceso."
                  : "Ingresa tu email para recibir un enlace de recuperación."}
            </p>
          </div>

          <Card className="border-epoch-primary/5 bg-white shadow-2xl rounded-xl">
            <CardContent className="p-4 sm:p-6 md:p-8 lg:p-12">
              {error && (
                <Alert
                  className="mb-6 bg-red-500/10 border-red-500/20 rounded-xl animate-in shake-in duration-500"
                  variant="destructive"
                >
                  <AlertDescription className="text-red-950 font-serif italic text-xs">
                    {error}
                  </AlertDescription>
                </Alert>
              )}

              {success && (
                <Alert className="mb-6 bg-emerald-500/10 border-emerald-500/20 rounded-xl">
                  <CheckCircle2 className="h-4 w-4 text-emerald-500 shrink-0" />
                  <AlertDescription className="text-emerald-700 font-serif italic text-xs">
                    ¡Contraseña actualizada! Redirigiendo...
                  </AlertDescription>
                </Alert>
              )}

              {isEstablishingSession && (
                <div className="flex flex-col items-center justify-center py-12 space-y-6">
                  <Loader2 className="h-12 w-12 text-epoch-primary animate-spin" />
                  <p className="text-epoch-primary/80 font-body text-sm text-center">
                    Verificando enlace...
                  </p>
                </div>
              )}

              {!isEstablishingSession && step === "request" && (
                <form
                  className="space-y-6"
                  onSubmit={requestForm.handleSubmit(onRequestSubmit)}
                >
                  <div className="space-y-3">
                    <Label
                      className="text-[10px] font-display font-bold text-epoch-primary/40 uppercase tracking-[0.3em] ml-1"
                      htmlFor="email"
                    >
                      Email
                    </Label>
                    <div className="relative group">
                      <Input
                        id="email"
                        placeholder="admin@opttius.com"
                        type="email"
                        {...requestForm.register("email")}
                        className={cn(
                          "h-14 min-h-[44px] rounded-xl border-epoch-primary/10 bg-epoch-background/50 pl-14 focus:bg-white transition-all font-body text-epoch-primary shadow-inner",
                          requestForm.formState.errors.email &&
                            "border-red-900 focus-visible:ring-red-900",
                        )}
                        disabled={authLoading}
                      />
                      <Mail className="absolute left-5 top-1/2 -translate-y-1/2 h-5 w-5 text-epoch-primary/30 group-focus-within:text-epoch-primary transition-colors stroke-[1px]" />
                    </div>
                    {requestForm.formState.errors.email && (
                      <p className="text-[10px] text-red-900 font-display italic tracking-[0.1em] ml-1 uppercase">
                        {requestForm.formState.errors.email.message}
                      </p>
                    )}
                  </div>

                  <Button
                    className="w-full h-14 min-h-[44px] sm:h-16 rounded-xl bg-epoch-primary hover:bg-epoch-surface text-white font-display font-bold uppercase text-[10px] sm:text-xs tracking-[0.2em] sm:tracking-[0.4em] group overflow-hidden transition-all duration-500 shadow-xl"
                    disabled={authLoading}
                    size="lg"
                    type="submit"
                  >
                    {authLoading ? (
                      <Loader2 className="h-5 w-5 animate-spin" />
                    ) : (
                      <>
                        Enviar enlace
                        <ArrowRight className="ml-3 h-5 w-5 transition-transform group-hover:translate-x-1" />
                      </>
                    )}
                  </Button>

                  <Link
                    className="flex items-center justify-center gap-2 py-3 min-h-[44px] text-[10px] font-display font-bold text-epoch-primary/60 hover:text-epoch-primary uppercase tracking-widest transition-colors"
                    href="/login"
                  >
                    <ArrowLeft className="h-3 w-3 shrink-0" />
                    Volver al login
                  </Link>
                </form>
              )}

              {!isEstablishingSession && step === "sent" && (
                <div className="text-center space-y-6">
                  <div className="w-16 h-16 sm:w-20 sm:h-20 bg-emerald-500/10 rounded-2xl sm:rounded-3xl flex items-center justify-center mx-auto">
                    <Mail className="h-8 w-8 sm:h-10 sm:w-10 text-emerald-500" />
                  </div>
                  <p className="text-epoch-primary/80 font-body text-sm sm:text-base">
                    Hemos enviado un enlace de recuperación a:
                    <br />
                    <span className="font-bold text-epoch-primary">
                      {requestForm.getValues("email")}
                    </span>
                  </p>
                  <Button
                    className="w-full h-14 min-h-[44px] rounded-xl border-2 border-epoch-primary/20 font-display font-bold hover:bg-epoch-primary/5 hover:border-epoch-primary/30"
                    variant="outline"
                    onClick={() => setStep("request")}
                  >
                    Intentar con otro correo
                  </Button>
                  <Link
                    className="flex items-center justify-center gap-2 py-3 min-h-[44px] text-[10px] font-display font-bold text-epoch-accent hover:text-epoch-primary uppercase tracking-widest transition-colors"
                    href="/login"
                  >
                    <ArrowLeft className="h-3 w-3 shrink-0" />
                    Regresar al login
                  </Link>
                </div>
              )}

              {!isEstablishingSession && step === "update" && (
                <form
                  className="space-y-6"
                  onSubmit={updateForm.handleSubmit(onUpdateSubmit)}
                >
                  <div className="space-y-3">
                    <Label
                      className="text-[10px] font-display font-bold text-epoch-primary/40 uppercase tracking-[0.3em] ml-1"
                      htmlFor="password"
                    >
                      {isInviteFlow ? "Contraseña" : "Nueva contraseña"}
                    </Label>
                    <div className="relative group">
                      <Input
                        id="password"
                        placeholder="••••••••"
                        type="password"
                        {...updateForm.register("password")}
                        className={cn(
                          "h-14 min-h-[44px] rounded-xl border-epoch-primary/10 bg-epoch-background/50 pl-14 focus:bg-white transition-all font-body text-epoch-primary shadow-inner",
                          updateForm.formState.errors.password &&
                            "border-red-900 focus-visible:ring-red-900",
                        )}
                        disabled={isUpdating}
                      />
                      <Lock className="absolute left-5 top-1/2 -translate-y-1/2 h-5 w-5 text-epoch-primary/30" />
                    </div>
                    {updateForm.formState.errors.password && (
                      <p className="text-[10px] text-red-900 font-display italic tracking-[0.1em] ml-1 uppercase">
                        {updateForm.formState.errors.password.message}
                      </p>
                    )}
                  </div>

                  <div className="space-y-3">
                    <Label
                      className="text-[10px] font-display font-bold text-epoch-primary/40 uppercase tracking-[0.3em] ml-1"
                      htmlFor="confirmPassword"
                    >
                      Confirmar contraseña
                    </Label>
                    <div className="relative group">
                      <Input
                        id="confirmPassword"
                        placeholder="••••••••"
                        type="password"
                        {...updateForm.register("confirmPassword")}
                        className={cn(
                          "h-14 min-h-[44px] rounded-xl border-epoch-primary/10 bg-epoch-background/50 pl-14 focus:bg-white transition-all font-body text-epoch-primary shadow-inner",
                          updateForm.formState.errors.confirmPassword &&
                            "border-red-900 focus-visible:ring-red-900",
                        )}
                        disabled={isUpdating}
                      />
                      <ShieldCheck className="absolute left-5 top-1/2 -translate-y-1/2 h-5 w-5 text-epoch-primary/30" />
                    </div>
                    {updateForm.formState.errors.confirmPassword && (
                      <p className="text-[10px] text-red-900 font-display italic tracking-[0.1em] ml-1 uppercase">
                        {updateForm.formState.errors.confirmPassword.message}
                      </p>
                    )}
                  </div>

                  <Button
                    className="w-full h-14 min-h-[44px] sm:h-16 rounded-xl bg-epoch-primary hover:bg-epoch-surface text-white font-display font-bold uppercase text-xs sm:text-sm tracking-normal sm:tracking-[0.2em] px-6 overflow-hidden transition-all duration-500 shadow-xl"
                    disabled={isUpdating}
                    size="lg"
                    type="submit"
                  >
                    {isUpdating ? (
                      <Loader2 className="h-5 w-5 animate-spin" />
                    ) : isInviteFlow ? (
                      <>
                        Crear contraseña
                        <span className="hidden sm:inline"> y acceder</span>
                      </>
                    ) : (
                      "Restablecer contraseña"
                    )}
                  </Button>
                </form>
              )}
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}

import type { MetadataRoute } from "next";

const baseUrl = process.env.NEXT_PUBLIC_APP_URL || "https://opttius.cl";

export default function robots(): MetadataRoute.Robots {
  const isProduction = process.env.NODE_ENV === "production";

  if (!isProduction) {
    return {
      rules: { userAgent: "*", allow: "/", disallow: "/" },
      sitemap: undefined,
    };
  }

  return {
    rules: [
      {
        userAgent: "*",
        allow: "/",
        disallow: [
          "/admin/",
          "/api/",
          "/onboarding/",
          "/checkout/",
          "/profile/",
          "/reset-password/",
        ],
      },
      {
        userAgent: "GPTBot",
        allow: "/",
        disallow: [
          "/admin/",
          "/api/",
          "/onboarding/",
          "/checkout/",
          "/profile/",
        ],
      },
      {
        userAgent: "ChatGPT-User",
        allow: "/",
        disallow: [
          "/admin/",
          "/api/",
          "/onboarding/",
          "/checkout/",
          "/profile/",
        ],
      },
      {
        userAgent: "ClaudeBot",
        allow: "/",
        disallow: [
          "/admin/",
          "/api/",
          "/onboarding/",
          "/checkout/",
          "/profile/",
        ],
      },
    ],
    sitemap: `${baseUrl}/sitemap.xml`,
  };
}

"use client";

import { zodResolver } from "@hookform/resolvers/zod";
import { ArrowRight, Eye, EyeOff, Loader2, Lock, Mail, Phone, User } from "lucide-react";
import Link from "next/link";
import { useRouter, useSearchParams } from "next/navigation";
import { useEffect, useState } from "react";
import { useForm } from "react-hook-form";
import * as z from "zod";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useAuthContext } from "@/contexts/AuthContext";
import { cn } from "@/lib/utils";

import { SignupBrandingSide, SignupSuccessView } from "./_components/SignupBranding";

const signupSchema = z.object({
  firstName: z.string().min(2, "El nombre debe tener al menos 2 caracteres"),
  lastName: z.string().min(2, "El apellido debe tener al menos 2 caracteres"),
  email: z.string().email("Por favor ingresa un email válido"),
  phone: z.string().optional().or(z.literal("")),
  password: z.string().min(6, "La contraseña debe tener al menos 6 caracteres").regex(/[A-Z]/, "Debe contener al menos una mayúscula").regex(/[a-z]/, "Debe contener al menos una minúscula").regex(/[0-9]/, "Debe contener al menos un número"),
  confirmPassword: z.string(),
}).refine((data) => data.password === data.confirmPassword, { message: "Las contraseñas no coinciden", path: ["confirmPassword"] });

type SignupForm = z.infer<typeof signupSchema>;

export default function SignupPage() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const { signUp, loading } = useAuthContext();
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [configChecked, setConfigChecked] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isSuccess, setIsSuccess] = useState(false);
  const [requiresEmailConfirmation, setRequiresEmailConfirmation] = useState(false);

  useEffect(() => {
    const checkConfig = async () => {
      try {
        const res = await fetch("/api/landing/onboarding-config");
        const data = await res.json();
        if (data.signupEnabled === false && searchParams.get("access") !== "opticas") { router.replace("/solicitar-demo"); return; }
      } catch { }
      setConfigChecked(true);
    };
    checkConfig();
  }, [router, searchParams]);

  const { register, handleSubmit, formState: { errors } } = useForm<SignupForm>({ resolver: zodResolver(signupSchema) });

  const onSubmit = async (data: SignupForm) => {
    try {
      setError(null);
      const result = await signUp(data.email, data.password, { firstName: data.firstName, lastName: data.lastName, phone: data.phone });
      if (result.error) { setError(result.error.message || "Signup failed"); return; }
      const needsConfirm = !result.data?.session && result.data?.user;
      setRequiresEmailConfirmation(needsConfirm);
      setIsSuccess(true);
      if (needsConfirm) {
        try { (await import("@/utils/supabase/client")).createClient().auth.signOut(); } catch { }
        return;
      }
      setTimeout(() => router.push("/onboarding/choice"), 1500);
    } catch (err: unknown) { setError(err.message || "An error occurred during signup"); }
  };

  if (!configChecked) return <div className="min-h-screen flex items-center justify-center bg-epoch-background"><div className="animate-spin rounded-full h-8 w-8 border-b-2 border-epoch-primary" /></div>;
  if (isSuccess) return <SignupSuccessView requiresEmailConfirmation={requiresEmailConfirmation} onContinue={() => router.push("/onboarding/choice")} onGoToLogin={() => router.push("/login")} />;

  return (
    <div className="min-h-screen flex flex-col lg:flex-row bg-epoch-background overflow-hidden relative">
      <SignupBrandingSide />
      <div className="flex-1 flex flex-col justify-center items-center p-6 md:p-12 xl:p-24 bg-epoch-background relative z-10 overflow-y-auto">
        <div className="w-full max-w-2xl animate-in fade-in slide-in-from-bottom-10 duration-700">
          <div className="mb-12">
            <h1 className="text-5xl font-display font-bold text-epoch-primary tracking-tight leading-none">Cree su cuenta en<br /><span className="text-epoch-accent italic font-serif lowercase tracking-normal">Opttius</span></h1>
            <p className="mt-4 text-epoch-primary/60 font-body text-sm">El sistema de gestión diseñado para su óptica.</p>
          </div>
          <Card className="border-epoch-primary/5 bg-white shadow-2xl rounded-xl">
            <CardContent className="p-8 sm:p-12">
              <form className="space-y-8" onSubmit={handleSubmit(onSubmit)}>
                {error && <Alert className="bg-red-500/10 border-red-500/20 rounded-xl" variant="destructive"><AlertDescription className="text-red-950 font-serif italic text-xs">{error}</AlertDescription></Alert>}
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-8">
                  <Field error={errors.firstName} icon={<User className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-epoch-primary/30" />} label="Nombre">
                    <Input placeholder="Alejandro" {...register("firstName")} className={cn("h-14 rounded-xl border-epoch-primary/10 bg-epoch-background/50 pl-12 focus:bg-white transition-all font-body text-epoch-primary shadow-inner", errors.firstName && "border-red-900")} disabled={loading} />
                  </Field>
                  <Field error={errors.lastName} icon={<User className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-epoch-primary/30" />} label="Apellido">
                    <Input placeholder="Valdivia" {...register("lastName")} className={cn("h-14 rounded-xl border-epoch-primary/10 bg-epoch-background/50 pl-12 focus:bg-white transition-all font-body text-epoch-primary shadow-inner", errors.lastName && "border-red-900")} disabled={loading} />
                  </Field>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-8">
                  <Field error={errors.email} icon={<Mail className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-epoch-primary/30" />} label="Email Corporativo">
                    <Input placeholder="directorio@optica.com" type="email" {...register("email")} className={cn("h-14 rounded-xl border-epoch-primary/10 bg-epoch-background/50 pl-12 focus:bg-white transition-all font-body text-epoch-primary shadow-inner", errors.email && "border-red-900")} disabled={loading} />
                  </Field>
                  <Field icon={<Phone className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-epoch-primary/30" />} label="Teléfono Móvil">
                    <Input placeholder="+1 555-0100" type="tel" {...register("phone")} className="h-14 rounded-xl border-epoch-primary/10 bg-epoch-background/50 pl-12 focus:bg-white transition-all font-body text-epoch-primary shadow-inner" disabled={loading} />
                  </Field>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-8">
                  <PasswordField disabled={loading} error={errors.password} label="Contraseña" register={register("password")} show={showPassword} onToggle={() => setShowPassword(!showPassword)} />
                  <PasswordField disabled={loading} error={errors.confirmPassword} label="Confirmar contraseña" register={register("confirmPassword")} show={showConfirmPassword} onToggle={() => setShowConfirmPassword(!showConfirmPassword)} />
                </div>
                <Button className="w-full h-16 rounded-xl bg-epoch-primary hover:bg-epoch-surface text-white font-display font-bold uppercase text-xs tracking-[0.4em] transition-all shadow-xl" disabled={loading} size="lg" type="submit">
                  {loading ? <Loader2 className="h-5 w-5 animate-spin" /> : <span className="flex items-center gap-3">Crear cuenta<ArrowRight className="h-4 w-4 transition-transform group-hover:translate-x-3" /></span>}
                </Button>
              </form>
              <div className="mt-12 text-center pt-8 border-t border-epoch-primary/5">
                <p className="text-[10px] font-display font-bold text-epoch-primary/40 uppercase tracking-widest mb-4">¿Ya tiene cuenta?</p>
                <Link className="inline-flex items-center gap-2 text-xs font-display font-bold text-epoch-accent uppercase tracking-[0.2em] hover:text-epoch-primary transition-all group" href="/login">Iniciar sesión<ArrowRight className="h-4 w-4 transition-transform group-hover:translate-x-1" /></Link>
              </div>
            </CardContent>
          </Card>
          <p className="mt-12 text-center text-[8px] font-display font-bold text-epoch-primary/30 uppercase tracking-[0.2em] max-w-lg mx-auto leading-relaxed">Al registrarse en Opttius, usted acepta nuestros <Link className="underline hover:text-epoch-primary" href="#">Términos de uso</Link> y <Link className="underline hover:text-epoch-primary" href="#">Política de Privacidad</Link>.</p>
        </div>
      </div>
    </div>
  );
}

function Field({ children, label, error, icon }: { children: React.ReactNode; label: string; error?: unknown; icon?: React.ReactNode }) {
  return (<div className="space-y-3"><Label className="text-[10px] font-display font-bold text-epoch-primary/40 uppercase tracking-widest ml-1">{label}</Label><div className="relative group">{children}{icon && <div className="pointer-events-none">{icon}</div>}</div>{error && <p className="text-xs text-red-500 ml-1">{error.message}</p>}</div>);
}

function PasswordField({ label, error, show, onToggle, register, disabled }: { label: string; error?: unknown; show: boolean; onToggle: () => void; register: unknown; disabled?: boolean }) {
  return (<div className="space-y-3"><Label className="text-[10px] font-display font-bold text-epoch-primary/40 uppercase tracking-widest ml-1">{label}</Label><div className="relative group">
    <Input placeholder="••••••••" type={show ? "text" : "password"} {...register} className={cn("h-14 rounded-xl border-epoch-primary/10 bg-epoch-background/50 pl-12 pr-12 focus:bg-white transition-all font-body text-epoch-primary shadow-inner", error && "border-red-900")} disabled={disabled} />
    <Lock className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-epoch-primary/30" />
    <Button className="absolute right-2 top-1/2 -translate-y-1/2 h-10 w-10 hover:bg-transparent text-epoch-primary/30" size="sm" type="button" variant="ghost" onClick={onToggle}>{show ? <EyeOff className="h-4 w-4 stroke-[1px]" /> : <Eye className="h-4 w-4 stroke-[1px]" />}</Button>
  </div>{error && <p className="text-xs text-red-500 ml-1">{error.message}</p>}</div>);
}

"use client";

import { zodResolver } from "@hookform/resolvers/zod";
import {
  ArrowLeft,
  Building2,
  HelpCircle,
  Loader2,
  Mail,
  MessageSquare,
  User,
} from "lucide-react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { type SubmitHandler, useForm } from "react-hook-form";
import type { z } from "zod";

import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { createPublicSaasSupportTicketSchema } from "@/lib/api/validation/zod-schemas";
import { appLogger } from '@/lib/logger';

type SupportForm = z.infer<typeof createPublicSaasSupportTicketSchema>;

const categoryLabels: Record<string, string> = {
  technical: "Problema Técnico",
  billing: "Facturación/Suscripción",
  feature_request: "Solicitud de Funcionalidad",
  bug_report: "Reporte de Bug",
  account: "Gestión de Cuenta",
  other: "Otro",
};

const priorityLabels: Record<string, string> = {
  low: "Baja",
  medium: "Media",
  high: "Alta",
  urgent: "Urgente",
};

interface SupportTicketFormProps {
  onSuccess: (ticketNumber: string) => void;
}

export function SupportTicketForm({ onSuccess }: SupportTicketFormProps) {
  const router = useRouter();

  const {
    register,
    handleSubmit,
    formState: { errors },
    setValue,
    watch,
  } = useForm<SupportForm>({
    resolver: zodResolver(createPublicSaasSupportTicketSchema),
    defaultValues: {
      requester_name: "",
      requester_email: "",
      subject: "",
      description: "",
      priority: "medium",
      category: "technical",
      metadata: {},
    },
  });

  const category = watch("category");
  const priority = watch("priority");

  const onSubmit: SubmitHandler<SupportForm> = async (data) => {
    try {
      const response = await fetch("/api/support/create-ticket", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data),
      });
      const result = await response.json();
      if (!response.ok)
        throw new Error(result.error || "Error al crear el ticket");
      onSuccess(result.ticket?.ticket_number || "");
    } catch (error) {
      appLogger.error("Error creating ticket:", error);
