"use client";

import { User } from "lucide-react";
import { useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { customerService } from "@/lib/api/services/customerService";
import { formatRUT, formatRUTAsYouType } from "@/lib/utils/rut";

interface AddCustomerFormProps {
  fieldOperationId: string;
  branchId: string;
  onSuccess: () => void;
  onCancel: () => void;
}

export default function AddCustomerForm({
  fieldOperationId,
  branchId,
  onSuccess,
  onCancel,
}: AddCustomerFormProps) {
  const [formData, setFormData] = useState({
    first_name: "",
    last_name: "",
    email: "",
    phone: "",
    rut: "",
  });
  const [saving, setSaving] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});

  const validate = () => {
    const err: Record<string, string> = {};
    if (!formData.first_name?.trim()) err.first_name = "Nombre requerido";
    if (!formData.last_name?.trim()) err.last_name = "Apellido requerido";
    if (!formData.phone?.trim()) err.phone = "Teléfono requerido";
    setErrors(err);
    return Object.keys(err).length === 0;
  };

  const handleRUTChange = (value: string) => {
    setFormData((prev) => ({ ...prev, rut: formatRUTAsYouType(value) }));
  };

  const handleRUTBlur = (value: string) => {
    if (value.trim()) {
      const formatted = formatRUT(value);
      if (formatted) {
        setFormData((prev) => ({ ...prev, rut: formatted }));
      }
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!validate()) return;
    setSaving(true);
    try {
      await customerService.createCustomer({
        first_name: formData.first_name.trim() || null,
        last_name: formData.last_name.trim() || null,
        email: formData.email.trim() || null,
        phone: formData.phone.trim() || null,
        rut: formData.rut.trim() || null,
        branch_id: branchId,
        field_operation_id: fieldOperationId,
      });
      toast.success("Cliente creado");
      onSuccess();
    } catch (err: unknown) {
      toast.error(err?.message || "Error al crear cliente");
    } finally {
      setSaving(false);
    }
  };

  return (
    <form className="space-y-4" onSubmit={handleSubmit}>
      <div className="flex items-center gap-2 text-admin-text-primary font-semibold mb-4">
        <User className="h-5 w-5" />
        Nuevo cliente del operativo
      </div>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div>
          <Label className="text-admin-text-primary text-sm">Nombre *</Label>
          <Input
            className="mt-1 h-11 border-admin-border-primary/30"
            placeholder="Nombre"
            value={formData.first_name}
            onChange={(e) =>
              setFormData((prev) => ({ ...prev, first_name: e.target.value }))
            }
          />
          {errors.first_name && (
            <p className="text-sm text-red-500 mt-1">{errors.first_name}</p>
          )}
        </div>
        <div>
          <Label className="text-admin-text-primary text-sm">Apellido *</Label>
          <Input
            className="mt-1 h-11 border-admin-border-primary/30"
            placeholder="Apellido"
            value={formData.last_name}
            onChange={(e) =>
              setFormData((prev) => ({ ...prev, last_name: e.target.value }))
            }
          />
          {errors.last_name && (
            <p className="text-sm text-red-500 mt-1">{errors.last_name}</p>
          )}
        </div>
      </div>
      <div>
        <Label className="text-admin-text-primary text-sm">Teléfono *</Label>
        <Input
          className="mt-1 h-11 border-admin-border-primary/30"
          placeholder="+56 9 1234 5678"
          value={formData.phone}
          onChange={(e) =>
            setFormData((prev) => ({ ...prev, phone: e.target.value }))
          }
        />
        {errors.phone && (
          <p className="text-sm text-red-500 mt-1">{errors.phone}</p>
        )}
      </div>
      <div>
        <Label className="text-admin-text-primary text-sm">Email</Label>
        <Input
          className="mt-1 h-11 border-admin-border-primary/30"
          placeholder="email@ejemplo.com"
          type="email"
          value={formData.email}
          onChange={(e) =>
            setFormData((prev) => ({ ...prev, email: e.target.value }))
          }
        />
      </div>
      <div>
        <Label className="text-admin-text-primary text-sm">RUT</Label>
        <Input
          className="mt-1 h-11 border-admin-border-primary/30 font-mono"
          placeholder="12.345.678-9"
          value={formData.rut}
          onBlur={(e) => handleRUTBlur(e.target.value)}
          onChange={(e) => handleRUTChange(e.target.value)}
        />
      </div>
      <div className="flex gap-2 pt-2">
        <Button
          className="min-h-[44px]"
          disabled={saving}
          type="button"
          variant="outline"
          onClick={onCancel}
        >
          Cancelar
        </Button>
        <Button
          className="min-h-[44px] bg-admin-accent-primary hover:bg-admin-accent-secondary text-[#1A2B23]"
          disabled={saving}
          type="submit"
        >
          {saving ? "Creando..." : "Crear cliente"}
        </Button>
      </div>
    </form>
  );
}

"use client";

import { Bell, CheckCheck, X } from "lucide-react";

import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@/components/ui/sheet";

import { NotificationListPanel } from "./_components/NotificationListPanel";
import { useNotificationDropdown } from "./_hooks/useNotificationDropdown";

interface AdminNotificationDropdownProps {
  variant?: "dropdown" | "sheet";
}

export default function AdminNotificationDropdown({
  variant = "dropdown",
}: AdminNotificationDropdownProps) {
  const {
    notifications,
    unreadCount,
    loading,
    isOpen,
    setIsOpen,
    markAsRead,
    markAllAsRead,
  } = useNotificationDropdown();

  const triggerButton = (
    <Button
      className="relative group h-10 w-10 rounded-xl hover:bg-admin-accent-primary/10 transition-all duration-300 focus:outline-none focus:ring-0 focus-visible:ring-0 focus-visible:ring-offset-0"
      size="icon"
      variant="ghost"
    >
      <Bell className="h-5 w-5 text-admin-text-secondary group-hover:text-admin-accent-primary transition-colors duration-300" />
      {unreadCount > 0 && (
        <span className="absolute top-1.5 right-1.5 h-4 w-4 bg-admin-accent-secondary flex items-center justify-center text-[10px] font-black text-[#1A2B23] shadow-lg shadow-black/20 border border-admin-bg-secondary leading-none">
          {unreadCount > 9 ? "9+" : unreadCount}
        </span>
      )}
    </Button>
  );

  if (variant === "sheet") {
    return (
      <Sheet open={isOpen} onOpenChange={setIsOpen}>
        <SheetTrigger asChild>{triggerButton}</SheetTrigger>
        <SheetContent
          elevateZIndex
          hideDefaultClose
          overlayExcludeBottomNav
          className="!h-[calc(100dvh-4rem-env(safe-area-inset-bottom))] !max-h-[calc(100dvh-4rem-env(safe-area-inset-bottom))] !bottom-[calc(4rem+env(safe-area-inset-bottom))] !top-auto !w-full !max-w-full !rounded-t-2xl flex flex-col p-0 bg-white border border-admin-border-primary/50 shadow-2xl shadow-black/10 overflow-hidden"
          side="bottom"
        >
          <SheetHeader className="flex flex-row items-center justify-between p-4 bg-admin-bg-tertiary/50 border-b border-admin-border-primary/50 shrink-0 space-y-0">
            <div>
              <SheetTitle className="text-base font-bold text-admin-text-primary">
                Notificaciones
              </SheetTitle>
              <p className="text-[11px] font-medium text-admin-text-tertiary uppercase tracking-wider mt-0.5">
                {unreadCount > 0
                  ? `${unreadCount} pendientes`
                  : "Sistema actualizado"}
              </p>
            </div>
            <div className="flex items-center gap-2">
              {unreadCount > 0 && (
                <Button
                  className="h-8 px-3 text-[11px] font-bold hover:bg-admin-accent-primary/10 text-admin-accent-primary rounded-lg"
                  disabled={loading}
                  size="sm"
                  variant="ghost"
                  onClick={markAllAsRead}
                >
                  <CheckCheck className="h-3.5 w-3.5 mr-1.5" />
                  Marcar todo
                </Button>
              )}
              <Button
                aria-label="Cerrar"
                className="shrink-0"
                size="icon"
                variant="ghost"
                onClick={() => setIsOpen(false)}
              >
                <X className="h-5 w-5" />
              </Button>
            </div>
          </SheetHeader>
          <div className="flex-1 min-h-0 flex flex-col overflow-hidden">
            <NotificationListPanel
              notifications={notifications}
              variant="sheet"
              onClose={() => setIsOpen(false)}
              onMarkAsRead={markAsRead}
            />
          </div>
        </SheetContent>
      </Sheet>
    );
  }

  return (
    <DropdownMenu open={isOpen} onOpenChange={setIsOpen}>
      <DropdownMenuTrigger asChild>{triggerButton}</DropdownMenuTrigger>
      <DropdownMenuContent
        align="end"
        className="w-[380px] p-0 bg-white border border-admin-border-primary/50 shadow-2xl shadow-black/10 rounded-2xl overflow-hidden"
        sideOffset={12}
      >
        <div className="flex items-center justify-between p-4 bg-admin-bg-tertiary/50 border-b border-admin-border-primary/50">
          <div>
            <h3 className="font-bold text-sm text-admin-text-primary tracking-tight">
              Notificaciones
            </h3>
            <p className="text-[11px] font-medium text-admin-text-tertiary uppercase tracking-wider mt-0.5">
              {unreadCount > 0
                ? `${unreadCount} pendientes`
                : "Sistema actualizado"}
            </p>
          </div>
          {unreadCount > 0 && (
            <Button
              className="h-8 px-3 text-[11px] font-bold hover:bg-admin-accent-primary/10 text-admin-accent-primary rounded-lg transition-all"
              disabled={loading}
              size="sm"
              variant="ghost"
              onClick={markAllAsRead}
            >
              <CheckCheck className="h-3.5 w-3.5 mr-1.5" />
              Marcar todo
            </Button>
          )}
        </div>
        <NotificationListPanel
          notifications={notifications}
          variant="dropdown"
          onMarkAsRead={markAsRead}
        />
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

"use client";

import { ChevronDown, HelpCircle, LogOut, User, X } from "lucide-react";
import Image from "next/image";
import Link from "next/link";
import { useRouter } from "next/navigation";

import { useTheme } from "@/components/theme-provider";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { SheetClose } from "@/components/ui/sheet";
import { createNavigationGroups } from "@/config/admin-navigation";
import { useAuthContext } from "@/contexts/AuthContext";
import { useBranch } from "@/hooks/useBranch";
import { useRoot } from "@/hooks/useRoot";
import { cn } from "@/lib/utils";

interface AdminSidebarProps {
  pathname: string;
  onNavigate?: () => void;
  stats: {
    todayOrders: number;
    totalOrders: number;
    revenue: number;
    lowStock: number;
    newWorkOrders: number;
    inProgressWorkOrders: number;
    pendingQuotes: number;
    todayAppointments: number;
    openTickets: number;
  };
  onChatbotClick?: () => void;
  organizationState?: {
    hasOrganization: boolean | null;
    organizationName: string | null;
    organizationLogo: string | null;
    organizationSlogan: string | null;
    isDemoMode: boolean;
    onboardingRequired: boolean;
    isChecking: boolean;
    tierFeatures?: Record<string, boolean>;
  };
  adminRole?: string | null;
  expandedGroups: Record<string, boolean>;
  setExpandedGroups: React.Dispatch<
    React.SetStateAction<Record<string, boolean>>
  >;
}

export default function AdminSidebar({
  pathname,
  onNavigate,
  stats,
  onChatbotClick,
  organizationState,
  adminRole,
  expandedGroups,
  setExpandedGroups,
}: AdminSidebarProps) {
  const { isSuperAdmin } = useBranch();
  const { isRoot } = useRoot();
  const { user, profile, signOut } = useAuthContext();
  const { theme } = useTheme();
  const router = useRouter();

  const handleSignOut = async () => {
    await signOut();
    router.push("/");
  };

  return (
    <div className="admin-sidebar flex flex-col h-full w-full overflow-y-auto overflow-x-hidden relative min-h-0">
      <div className="absolute inset-0 opacity-[0.03] pointer-events-none" />
      <div className="admin-sidebar-header relative z-10 border-b border-admin-border-primary/10 flex-shrink-0">
        <div className="flex items-center justify-between py-4 px-4">
          <Link
            className="admin-sidebar-logo group flex items-center justify-center gap-3"
            href="/"
            onClick={onNavigate}
          >
            <Image
              alt="Opttius"
              className="h-10 w-10 flex-shrink-0 object-contain"
              height={44}
              src="/logo-opttius.svg"
              width={44}
            />
            <Image
              alt="Opttius"
              className="h-9 w-36 object-contain object-left"
              height={40}
              src="/logo-text-default.svg"
              width={176}
            />
          </Link>
          {onNavigate && (
            <SheetClose asChild>
              <Button
                className="rounded-xl text-[#F9F7F2] hover:bg-white/10 hover:text-white shrink-0"
                size="icon"
                variant="ghost"
              >
                <X className="h-5 w-5" />
              </Button>
            </SheetClose>
          )}
        </div>
      </div>
      <nav className="admin-sidebar-nav flex-1 min-h-0 overflow-y-auto">
        <ul className="space-y-2 px-2" role="list">
          {createNavigationGroups(
            stats.newWorkOrders,
            stats.openTickets,
            isRoot,
            organizationState?.tierFeatures,
          ).map((group) => {
            const filteredItems = group.items.filter((item) => {
              if (item.superAdminOnly && !isSuperAdmin) return false;
              if (item.rootOnly && !isRoot) return false;
              if (
                item.adminOrSuperAdminOnly &&
                adminRole != null &&
                !["admin", "super_admin", "root", "dev"].includes(adminRole)
              )
                return false;
              if (
                item.onboardingOnly &&
                organizationState?.hasOrganization &&
                !organizationState?.onboardingRequired
              )
                return false;
              return true;
            });
            if (filteredItems.length === 0) return null;
            const isExpanded =
              expandedGroups[group.id] ?? group.defaultExpanded ?? false;
            const hasBadge = filteredItems.some((item) => item.badge);
            const isGroupActive = filteredItems.some(
              (item) =>
                pathname === item.href ||
                (item.href !== "/admin" && pathname.startsWith(item.href)),
            );
            return (
              <li key={group.id}>
                {group.collapsible ? (
                  <button
                    className={cn(
                      "w-full flex items-center gap-2 px-3 py-2 rounded-xl",
                      "text-[#F9F7F2]/70 hover:text-[#F9F7F2] hover:bg-white/5",
                      "transition-all duration-200 text-left",
                      isGroupActive && "text-[#F9F7F2] bg-white/5",
                    )}
                    onClick={() =>
                      setExpandedGroups((prev) => ({
                        ...prev,
                        [group.id]: !prev[group.id],
                      }))
                    }
                  >
                    <group.icon className="h-4 w-4 shrink-0" />
                    <span className="flex-1 text-[10px] font-display uppercase tracking-widest font-medium">
                      {group.label}
                    </span>
                    {hasBadge && (
                      <Badge
                        className="bg-admin-accent-secondary/20 text-admin-accent-secondary rounded-lg px-1.5 py-0.5 text-[9px] font-display font-bold"
                        variant="secondary"
                      >
                        {filteredItems
                          .filter((i) => i.badge)
                          .map((i) => i.badge)
                          .reduce(
                            (a, b) =>
                              (
                                parseInt(a || "0") + parseInt(b || "0")
                              ).toString(),
                            "0",
                          )}
                      </Badge>
                    )}
                    <ChevronDown
                      className={cn(
                        "h-3.5 w-3.5 shrink-0 transition-transform duration-200",
                        !isExpanded && "-rotate-90",
                      )}
                    />
                  </button>
                ) : (
                  <div
                    className={cn(
                      "flex items-center gap-2 px-3 py-2 rounded-xl",
                      "text-[#F9F7F2]/50 pointer-events-none",
                    )}
                  >
                    <group.icon className="h-4 w-4 shrink-0" />
                    <span className="flex-1 text-[10px] font-display uppercase tracking-widest font-medium">
                      {group.label}
                    </span>
                  </div>
                )}
                <ul
                  className={cn(
                    "mt-1 space-y-0.5 overflow-hidden transition-all duration-300",
                    isExpanded
                      ? "max-h-[500px] opacity-100"
                      : "max-h-0 opacity-0",
                  )}
                  role="list"
                >
                  {filteredItems.map((item) => {
                    const isActive =
                      pathname === item.href ||
                      (item.href !== "/admin" &&
                        pathname.startsWith(item.href));
                    return (
                      <li key={item.href}>
                        <Link
                          className={cn(
                            "admin-nav-item rounded-xl relative group overflow-hidden transition-all duration-300 ml-2",
                            isActive
                              ? "active"
                              : "text-[#F9F7F2]/70 hover:text-[#F9F7F2]",
                          )}
                          href={item.href}
                          onClick={onNavigate}
                        >
                          <div
                            className={cn(
                              "absolute inset-y-0 left-0 w-[2px] bg-admin-accent-secondary transition-transform duration-300",
                              isActive
                                ? "scale-y-100"
                                : "scale-y-0 group-hover:scale-y-50",
                            )}
                          />
                          <item.icon
                            className={cn(
                              "h-4 w-4 transition-transform duration-300 group-hover:scale-110",
                              isActive
                                ? "text-inherit"
                                : "text-inherit opacity-70",
                            )}
                          />
                          <div className="flex-1">
                            <div className="flex items-center justify-between">
                              <span
                                className={cn(
                                  "truncate font-display uppercase tracking-widest text-[9px]",
                                  isActive ? "font-bold" : "font-medium",
                                )}
                              >
                                {item.label}
                              </span>
                              {item.badge && (
                                <Badge
                                  className="admin-sidebar-badge bg-admin-accent-secondary text-[#1A2B23] rounded-lg px-1.5 py-0.5 text-[9px] font-display font-black leading-none shadow-[0_2px_4px_rgba(0,0,0,0.2)]"
                                  variant="secondary"
                                >
                                  {item.badge}
                                </Badge>
                              )}
                            </div>
                          </div>
                        </Link>
                      </li>
                    );
                  })}
                </ul>
              </li>
            );
          })}
        </ul>
      </nav>
      <div className="flex-shrink-0 mt-auto p-3 space-y-3 border-t border-white/10 bg-black/5">
        <div className="flex items-center gap-2 p-3 bg-white/5 border border-white/10 rounded-xl relative overflow-hidden group">
          <div className="absolute inset-0 bg-gradient-to-br from-admin-accent-secondary/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
          <div className="h-9 w-9 rounded-lg bg-admin-accent-primary/10 border border-admin-accent-secondary/20 flex items-center justify-center text-admin-accent-secondary font-display font-bold text-sm relative z-10 overflow-hidden shrink-0">
            {profile?.avatar_url ? (
              <img
                alt=""
                className="w-full h-full object-cover"
                src={profile.avatar_url}
              />
            ) : (
              profile?.first_name?.[0] || user?.email?.[0]?.toUpperCase() || "U"
            )}
          </div>
          <div className="flex-1 min-w-0 relative z-10">
            <p className="text-[10px] font-display font-bold uppercase tracking-wider truncate text-[#F9F7F2]">
              {profile?.first_name
                ? `${profile.first_name} ${profile.last_name || ""}`.trim()
                : user?.email?.split("@")[0]}
            </p>
            <p className="text-[7px] font-serif italic text-[#F9F7F2]/60 tracking-widest uppercase">
              {isRoot
                ? "Archivista Root"
                : isSuperAdmin
                  ? "Guardián de Orden"
                  : "Administrador"}
            </p>
          </div>
          <Link className="relative z-10" href="/admin/profile">
            <Button
              className="rounded-lg hover:bg-white/10 text-[#F9F7F2] h-8 w-8"
              size="icon-sm"
              variant="ghost"
            >
              <User className="h-3.5 w-3.5" />
            </Button>
          </Link>
        </div>
        <div className="grid grid-cols-2 gap-2 relative z-10">
          <Link className="w-full" href="/admin/help">
            <Button
              className="w-full text-[8px] font-display uppercase tracking-widest gap-1 h-8 bg-transparent border-white/20 text-[#F9F7F2] rounded-lg"
              size="sm"
              variant="outline"
            >
              <HelpCircle className="h-3 w-3 text-admin-accent-secondary transition-colors" />{" "}
              Auxilio
            </Button>
          </Link>
          <Button
            className="admin-logout-button w-full text-[8px] font-display uppercase tracking-widest gap-1 h-8 bg-transparent border-red-300/30 text-red-200 rounded-lg"
            size="sm"
            variant="outline"
            onClick={handleSignOut}
          >
            <LogOut className="h-3 w-3 transition-colors" /> Retiro
          </Button>
        </div>
        <p className="text-center text-[8px] text-[#F9F7F2]/75 pt-1">
          &copy; {new Date().getFullYear()} Opttius
        </p>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";

import type { Appointment, ScheduleSettings } from "./_components/appointmentCalendarHelpers";
import {
  generateTimeSlots,
  getMonthDays,
  getWeekDays,
} from "./_components/appointmentCalendarHelpers";
import CalendarDayView from "./_components/CalendarDayView";
import CalendarMonthView from "./_components/CalendarMonthView";
import CalendarWeekView from "./_components/CalendarWeekView";

export type { Appointment, ScheduleSettings };

interface AppointmentCalendarProps {
  view: "day" | "week" | "month";
  currentDate: Date;
  appointments: Appointment[];
  onAppointmentClick: (appointment: Appointment) => void;
  onDateChange: (date: Date) => void;
  onSlotClick?: (date: Date, time: string) => void;
  scheduleSettings?: ScheduleSettings | null;
  lastRefresh?: number;
}

export default function AppointmentCalendar({
  view,
  currentDate,
  appointments,
  onAppointmentClick,
  onDateChange,
  onSlotClick,
  scheduleSettings,
  lastRefresh,
}: AppointmentCalendarProps) {
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);

  useEffect(() => {
    // Force re-render when lastRefresh changes
  }, [lastRefresh, appointments]);

  const timeSlots = useMemo(
    () => generateTimeSlots(scheduleSettings),
    [scheduleSettings],
  );

  const weekDays = useMemo(() => getWeekDays(currentDate), [currentDate]);

  const monthDays = useMemo(() => getMonthDays(currentDate), [currentDate]);

  if (view === "day") {
    return (
      <CalendarDayView
        appointments={appointments}
        currentDate={currentDate}
        lastRefresh={lastRefresh}
        scheduleSettings={scheduleSettings}
        timeSlots={timeSlots}
        onAppointmentClick={onAppointmentClick}
        onSlotClick={onSlotClick}
      />
    );
  }

  if (view === "week") {
    return (
      <CalendarWeekView
        appointments={appointments}
        currentDate={currentDate}
        lastRefresh={lastRefresh}
        scheduleSettings={scheduleSettings}
        timeSlots={timeSlots}
        weekDays={weekDays}
        onAppointmentClick={onAppointmentClick}
        onSlotClick={onSlotClick}
      />
    );
  }

  return (
    <CalendarMonthView
      appointments={appointments}
      currentDate={currentDate}
      monthDays={monthDays}
      onAppointmentClick={onAppointmentClick}
      onDateChange={onDateChange}
    />
  );
}

"use client";

import { Building2, Crown, Globe, Loader2, Plus, X } from "lucide-react";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import {  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { appLogger } from '@/lib/logger';

interface Branch {
  id: string;
  name: string;
  code: string;
}

interface BranchAccess {
  id: string;
  branch_id: string | null;
  role: string;
  is_primary: boolean;
  branches?: Branch | null;
}

interface BranchAccessManagerProps {
  adminUserId: string;
  isSuperAdmin: boolean;
  canEdit: boolean;
}

export default function BranchAccessManager({
  adminUserId,
  isSuperAdmin: initialIsSuperAdmin,
  canEdit,
}: BranchAccessManagerProps) {
  const [branchAccess, setBranchAccess] = useState<BranchAccess[]>([]);

  const [availableBranches, setAvailableBranches] = useState<Branch[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [isSuperAdmin, setIsSuperAdmin] = useState(initialIsSuperAdmin);
  const [selectedBranchId, setSelectedBranchId] = useState<string>("");

  useEffect(() => {
    fetchBranchAccess();
    fetchAvailableBranches();
  }, [adminUserId]);

  const fetchBranchAccess = async () => {
    try {
      setLoading(true);
      const response = await fetch(
        `/api/admin/admin-users/${adminUserId}/branch-access`,
      );
      if (response.ok) {
        const data = await response.json();
        setBranchAccess(data.branchAccess || []);
        const hasSuperAdmin = data.branchAccess?.some(
          (access: BranchAccess) => access.branch_id === null,
        );
        setIsSuperAdmin(hasSuperAdmin);
      }
    } catch (error) {
      appLogger.error("Error fetching branch access:", error);
      toast.error("Error al cargar acceso a sucursales");
    } finally {
      setLoading(false);
    }
  };

  const fetchAvailableBranches = async () => {
    try {
      const response = await fetch("/api/admin/branches");
      if (response.ok) {
        const data = await response.json();
        setAvailableBranches(data.branches || []);
      }
    } catch (error) {
      appLogger.error("Error fetching branches:", error);
    }
  };

  const handleAssignSuperAdmin = async () => {
    if (!canEdit) {
      toast.error("No tienes permisos para realizar esta acción");
      return;
    }

    try {
      setSaving(true);
      const response = await fetch(
        `/api/admin/admin-users/${adminUserId}/branch-access`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            branch_id: null,
            role: "manager",
            is_primary: true,
          }),
        },
      );

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(
          errorData.error || "Error al asignar super administrador",
        );
      }

      toast.success("Super administrador asignado exitosamente");
      fetchBranchAccess();
    } catch (error) {
      appLogger.error("Error assigning super admin:", error);
      toast.error(
        error instanceof Error
          ? error.message
          : "Error al asignar super administrador",
      );
    } finally {
      setSaving(false);
    }
  };

  const handleAssignBranch = async () => {
    if (!canEdit || !selectedBranchId) {
      return;
    }

    try {
      setSaving(true);
      const response = await fetch(
        `/api/admin/admin-users/${adminUserId}/branch-access`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            branch_id: selectedBranchId,
            role: "manager",
            is_primary: branchAccess.length === 0,
          }),
        },
      );

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || "Error al asignar sucursal");
      }

      toast.success("Sucursal asignada exitosamente");
      setSelectedBranchId("");
      fetchBranchAccess();
    } catch (error) {
      appLogger.error("Error assigning branch:", error);
      toast.error(
        error instanceof Error ? error.message : "Error al asignar sucursal",
      );
    } finally {
      setSaving(false);
    }
  };

  const handleRemoveBranch = async (branchId: string | null) => {
    if (!canEdit) {
      toast.error("No tienes permisos para realizar esta acción");
      return;
    }

    if (!confirm("¿Estás seguro de que quieres remover este acceso?")) {
      return;
    }

    try {
      setSaving(true);
      const url = branchId
        ? `/api/admin/admin-users/${adminUserId}/branch-access?branch_id=${branchId}`
        : `/api/admin/admin-users/${adminUserId}/branch-access?branch_id=null`;

      const response = await fetch(url, {
        method: "DELETE",
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || "Error al remover acceso");
      }

      toast.success("Acceso removido exitosamente");
      fetchBranchAccess();
    } catch (error) {
      appLogger.error("Error removing branch access:", error);
      toast.error(
        error instanceof Error ? error.message : "Error al remover acceso",
      );
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <Card className="bg-admin-bg-tertiary">
        <CardContent className="p-6">
          <div className="flex items-center justify-center py-8">
            <Loader2 className="h-6 w-6 animate-spin text-admin-accent-tertiary" />
          </div>
        </CardContent>
      </Card>
    );
  }

  const assignedBranchIds = branchAccess
    .filter((access) => access.branch_id !== null)
    .map((access) => access.branch_id);

  const unassignedBranches = availableBranches.filter(
    (branch) => !assignedBranchIds.includes(branch.id),
  );

  return (
    <Card className="bg-admin-bg-tertiary shadow-[0_1px_3px_rgba(0,0,0,0.3)]">
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Building2 className="h-5 w-5" />
          Acceso a Sucursales
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Super Admin Status */}
        {isSuperAdmin ? (
          <div className="p-4 bg-dorado/10 border border-dorado/30 rounded-md">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Globe className="h-5 w-5 text-dorado" />
                <div>
                  <div className="font-medium text-dorado">
                    Super Administrador
                  </div>
                  <div className="text-sm text-tierra-media">
                    Acceso a todas las sucursales
                  </div>
                </div>
              </div>
              {canEdit && (
                <Button
                  disabled={saving}
                  size="sm"
                  variant="outline"
                  onClick={() => handleRemoveBranch(null)}
                >
                  <X className="h-4 w-4 mr-2" />
                  Remover
                </Button>
              )}
            </div>
          </div>
        ) : (
          canEdit && (
            <div className="p-4 border rounded-md">
              <div className="flex items-center justify-between">
                <div>
                  <div className="font-medium mb-1">
                    Asignar Super Administrador
                  </div>
                  <div className="text-sm text-tierra-media">
                    Otorga acceso a todas las sucursales
                  </div>
                </div>
                <Button
                  disabled={saving}
                  size="sm"
                  variant="outline"
                  onClick={handleAssignSuperAdmin}
                >
                  <Crown className="h-4 w-4 mr-2" />
                  Asignar
                </Button>
              </div>
            </div>
          )
        )}

        {/* Branch Access List */}
        {!isSuperAdmin && (
          <>
            <div className="space-y-2">
              <Label>Sucursales Asignadas</Label>
              {branchAccess.filter((access) => access.branch_id !== null)
                .length === 0 ? (
                <div className="p-4 text-center text-tierra-media border rounded-md">
                  No hay sucursales asignadas
                </div>
              ) : (
                <div className="space-y-2">
                  {branchAccess
                    .filter((access) => access.branch_id !== null)
                    .map((access) => (
                      <div
                        className="flex items-center justify-between p-3 border rounded-md bg-admin-bg-secondary"
                        key={access.id}
                      >
                        <div className="flex items-center gap-2">
                          <Building2 className="h-4 w-4 text-admin-accent-tertiary" />
                          <span className="font-medium">
                            {access.branches?.name || "N/A"} (
                            {access.branches?.code || "N/A"})
                          </span>
                          {access.is_primary && (
                            <Badge className="text-xs" variant="outline">
                              Principal
                            </Badge>
                          )}
                        </div>
                        {canEdit && (
                          <Button
                            disabled={saving}
                            size="sm"
                            variant="ghost"
                            onClick={() => handleRemoveBranch(access.branch_id)}
                          >
                            <X className="h-4 w-4" />
                          </Button>
                        )}
                      </div>
                    ))}
                </div>
              )}
            </div>

            {/* Add Branch */}
            {canEdit && unassignedBranches.length > 0 && (
              <div className="space-y-2">
                <Label>Asignar Nueva Sucursal</Label>
                <div className="flex gap-2">
                  <Select
                    value={selectedBranchId}
                    onValueChange={setSelectedBranchId}
                  >
                    <SelectTrigger className="flex-1">
                      <SelectValue placeholder="Seleccionar sucursal" />
                    </SelectTrigger>
                    <SelectContent>
                      {unassignedBranches.map((branch) => (
                        <SelectItem key={branch.id} value={branch.id}>
                          {branch.name} ({branch.code})
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  <Button
                    disabled={!selectedBranchId || saving}
                    onClick={handleAssignBranch}
                  >
                    <Plus className="h-4 w-4 mr-2" />
                    Agregar
                  </Button>
                </div>
              </div>
            )}
          </>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import { Building2, Globe } from "lucide-react";
import { useState } from "react";

import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useBranch } from "@/hooks/useBranch";
import { appLogger } from '@/lib/logger';
import { cn } from "@/lib/utils";

export function BranchSelector() {
  const {
    branches,
    currentBranch,
    isGlobalView,
    isSuperAdmin,
    isLoading,
    setCurrentBranch,
  } = useBranch();

  const [isChanging, setIsChanging] = useState(false);

  const handleBranchChange = async (value: string) => {
    setIsChanging(true);
    try {
      await setCurrentBranch(value === "global" ? "global" : value);
    } catch (error) {
      appLogger.error("Error changing branch:", error);
    } finally {
      setIsChanging(false);
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center space-x-2 px-2 py-2 max-md:px-1">
        <div className="h-4 w-4 animate-spin rounded-full border-2 border-current border-t-transparent" />
        <span className="text-sm text-muted-foreground max-md:hidden">
          Cargando...
        </span>
      </div>
    );
  }

  if (branches.length === 0) {
    return null;
  }

  const currentValue = isGlobalView ? "global" : currentBranch?.id || "";

  return (
    <div className="flex items-center space-x-2">
      <Select
        disabled={isChanging}
        value={currentValue}
        onValueChange={handleBranchChange}
      >
        <SelectTrigger
          className={cn(
            "min-w-0 flex-shrink border-border/50 bg-background/50",
            "w-[200px] md:min-w-[140px]",
            "max-md:w-10 max-md:px-2 max-md:justify-center max-md:[&>:last-child]:hidden",
            "rounded-xl transition-all duration-200",
            "hover:border-epoch-accent/30 hover:bg-background/80",
            "focus:border-epoch-accent focus:ring-1 focus:ring-epoch-accent/20",
            isChanging && "opacity-50",
          )}
        >
          <SelectValue placeholder="Seleccionar sucursal">
            <div className="flex items-center space-x-2">
              {isGlobalView ? (
                <>
                  <Globe className="h-4 w-4 flex-shrink-0 text-epoch-accent" />
                  <span className="max-md:sr-only">Vista Global</span>
                </>
              ) : (
                <>
                  <Building2 className="h-4 w-4 flex-shrink-0 text-epoch-accent" />
                  <span className="max-md:sr-only">
                    {currentBranch?.name || "Sin sucursal"}
                  </span>
                </>
              )}
            </div>
          </SelectValue>
        </SelectTrigger>
        <SelectContent className="rounded-xl border-border/50 bg-background/95 backdrop-blur-sm">
          {isSuperAdmin && (
            <SelectItem value="global">
              <div className="flex items-center space-x-2">
                <Globe className="h-4 w-4" />
                <span>Vista Global</span>
              </div>
            </SelectItem>
          )}
          {branches.map((branch) => (
            <SelectItem
              className="rounded-lg"
              key={branch.id}
              value={branch.id}
            >
              <div className="flex items-center space-x-2">
                <Building2 className="h-4 w-4 text-epoch-accent" />
                <span>{branch.name}</span>
                {branch.is_primary && (
                  <span className="text-xs text-muted-foreground">
                    (Principal)
                  </span>
                )}
              </div>
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </div>
  );
}

"use client";

import { MessageSquare, X } from "lucide-react";
import { usePathname } from "next/navigation";
import { useEffect, useState } from "react";

import { Button } from "@/components/ui/button";
import { Sheet, SheetContent, SheetTitle } from "@/components/ui/sheet";
import type { InsightSection } from "@/lib/ai/insights/schemas";
import { cn } from "@/lib/utils";

import { ChatbotContent } from "./ChatbotContent";

const STORAGE_KEY = "opttius-chat-expanded";

interface ChatbotProps {
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
}

// Map pathname to section
function getSectionFromPathname(pathname: string): InsightSection | null {
  if (pathname === "/admin" || pathname === "/admin/") return "dashboard";
  if (pathname.startsWith("/admin/pos")) return "pos";
  if (pathname.startsWith("/admin/products")) return "inventory";
  if (pathname.startsWith("/admin/customers")) return "clients";
  if (pathname.startsWith("/admin/analytics")) return "analytics";
  return null;
}

function getStoredExpanded(): boolean {
  if (typeof window === "undefined") return false;
  try {
    return localStorage.getItem(STORAGE_KEY) === "true";
  } catch {
    return false;
  }
}

export default function Chatbot(
  {
    open: controlledOpen,
    onOpenChange: controlledOnOpenChange,
  }: ChatbotProps = {} as ChatbotProps,
) {
  const [internalOpen, setInternalOpen] = useState(false);
  const [isExpanded, setIsExpanded] = useState(getStoredExpanded);
  const pathname = usePathname();
  const currentSection = getSectionFromPathname(pathname);

  const isControlled = controlledOpen !== undefined;
  const isOpen = isControlled ? controlledOpen : internalOpen;
  const setIsOpen = isControlled
    ? (controlledOnOpenChange ?? (() => {}))
    : setInternalOpen;

  useEffect(() => {
    try {
      localStorage.setItem(STORAGE_KEY, String(isExpanded));
    } catch {
      /* ignore */
    }
  }, [isExpanded]);

  const handleExpandClick = () => {
    setIsExpanded(true);
    setIsOpen(true);
  };

  const handleCollapseClick = () => {
    setIsExpanded(false);
    setIsOpen(false);
  };

  // Close on Escape key
  useEffect(() => {
    const handleEsc = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setIsOpen(false);
      }
    };
    window.addEventListener("keydown", handleEsc);
    return () => window.removeEventListener("keydown", handleEsc);
  }, [setIsOpen]);

  const chatContent = (
    <ChatbotContent
      className="h-full"
      currentSection={currentSection}
      isSidebarMode={isExpanded}
      onClose={() => setIsOpen(false)}
      onExpandClick={!isExpanded ? handleExpandClick : undefined}
    />
  );

  // Sheet solo cuando el usuario expandió a sidebar; si no, burbuja flotante
  const useSheet = isExpanded;

  return (
    <div className="relative z-[100] flex flex-col items-end justify-end w-fit">
      {useSheet ? (
        <Sheet open={isOpen} onOpenChange={setIsOpen}>
          <SheetContent
            elevateZIndex
            hideDefaultClose
            aria-describedby={undefined}
            className="w-full max-w-full sm:w-[420px] p-0 flex flex-col overflow-hidden"
            side="right"
          >
            <SheetTitle className="sr-only">
              Asistente de Inteligencia Opttius
            </SheetTitle>
            <div className="flex-1 overflow-hidden min-h-0 flex flex-col">
              {chatContent}
            </div>
          </SheetContent>
        </Sheet>
      ) : (
        <div
          className={cn(
            "absolute right-0 bottom-full mb-2 w-[90vw] sm:w-[400px] h-[600px] max-h-[80vh] bg-white dark:bg-slate-950 rounded-xl shadow-2xl border border-border overflow-hidden flex flex-col transition-all duration-300 origin-bottom-right",
            isOpen
              ? "scale-100 opacity-100 translate-y-0 pointer-events-auto"
              : "scale-95 opacity-0 translate-y-4 pointer-events-none invisible",
          )}
        >
          {chatContent}
        </div>
      )}

      {/* Trigger Bubble - desktop only (mobile uses bottom nav) */}
      <div className="hidden lg:flex">
        <Button
          className={cn(
            "rounded-full w-14 h-14 shadow-[0_8px_30px_rgb(0,0,0,0.12)] transition-all duration-500 hover:scale-110 active:scale-95",
            isOpen
              ? "bg-slate-100 dark:bg-slate-800 text-slate-500 rotate-90 shadow-none"
              : "bg-gradient-to-tr from-primary via-primary to-primary/80 text-white",
          )}
          size="icon"
          title="Asistente de Inteligencia Opttius"
          variant="default"
          onClick={() => setIsOpen(!isOpen)}
        >
          {isOpen ? (
            <X className="w-6 h-6" />
          ) : (
            <div className="relative">
              <MessageSquare className="w-6 h-6" />
              <div className="absolute -top-1 -right-1 w-3 h-3 bg-green-500 rounded-full border-2 border-primary animate-pulse" />
            </div>
          )}
        </Button>
      </div>
    </div>
  );
}

"use client";

import { Sparkles } from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { toast } from "sonner";

import { useBranch } from "@/hooks/useBranch";
import { useChatConfig } from "@/hooks/useChatConfig";
import { useChatSession } from "@/hooks/useChatSession";
import type { InsightSection } from "@/lib/ai/insights/schemas";
import { appLogger } from '@/lib/logger';
import { cn } from "@/lib/utils";

import { ChatHeader } from "../chat/ChatHeader";
import { ChatHistorySidebar } from "../chat/ChatHistorySidebar";
import { ChatInput } from "../chat/ChatInput";
import { ExportDialog } from "../chat/ExportDialog";
import { MessageList } from "../chat/MessageList";
import { SettingsPanel } from "../chat/SettingsPanel";
import { useChatMessages } from "./hooks/useChatMessages";
import { useKeyboardShortcuts } from "./hooks/useKeyboardShortcuts";

interface ChatbotContentProps {
  className?: string;
  currentSection?: InsightSection | null;
  onClose?: () => void;
  /** When provided, shows expand/collapse button in header */
  onExpandClick?: () => void;
  /** When true, button shows collapse icon; when false, expand icon */
  isSidebarMode?: boolean;
}

// Quick suggestions based on section
const quickSuggestions: Record<InsightSection, string[]> = {
  dashboard: [
    "¿Cómo puedo mejorar mis ventas?",
    "Muéstrame los trabajos atrasados",
    "¿Qué productos tienen stock bajo?",
    "Dame un resumen del día de hoy",
  ],
  pos: [
    "¿Qué material de lente recomiendas para esta dioptría?",
    "¿Cómo calcular el precio con descuento?",
    "¿Qué tratamientos van bien con este tipo de lente?",
    "Muéstrame productos similares",
  ],
  inventory: [
    "¿Qué productos necesitan reposición?",
    "Muéstrame productos sin movimiento",
    "¿Cómo crear una oferta de liquidación?",
    "Dame estadísticas de inventario",
  ],
  clients: [
    "¿Qué clientes necesitan seguimiento?",
    "¿Cómo crear un nuevo cliente?",
    "¿Cómo buscar por RUT?",
    "Muéstrame clientes inactivos",
  ],
  analytics: [
    "Explica las tendencias de ventas",
    "¿Cuál es el producto más vendido?",
    "Muéstrame comparación de períodos",
    "¿Qué categoría genera más ingresos?",
  ],
};

export function ChatbotContent({
  className,
  currentSection,
  onClose,
  onExpandClick,
  isSidebarMode = false,
}: ChatbotContentProps) {
  const { currentBranch, isGlobalView } = useBranch();
  const [showHistory, setShowHistory] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showExport, setShowExport] = useState(false);
  const [historyWidth, setHistoryWidth] = useState(256);

  const handleHistoryWidthChange = useCallback((width: number) => {
    setHistoryWidth(width);
  }, []);

  // Use extracted hooks
  const {
    messages,
    isStreaming,
    currentStreamingContent,
    setMessages,
    sendMessage,
    stopStreaming,
    regenerateMessage,
    clearMessages,
    loadMessagesFromSession,
  } = useChatMessages(currentSection || null);

  const {
    currentSession,
    loading: sessionLoading,
    error: sessionError,
    createSession,
    loadSession,
    updateSessionTitle,
    saveMessage,
    clearSession,
  } = useChatSession();

  // Show session errors to user
  useEffect(() => {
    if (sessionError) {
      appLogger.error("Session error:", sessionError);
    }
  }, [sessionError]);

  // Memoize initial config to prevent infinite loops
  const initialConfig = useMemo(
    () => ({
      provider: "deepseek" as const,
      model: "deepseek-chat",
    }),
    [],
  );

  const {
    config,
    setProvider,
    setModel,
    updateConfig: updateChatConfig,
    getConfigForAPI,
  } = useChatConfig(initialConfig);

  // Load messages when session changes, but only once per session
  const lastLoadedSessionId = useRef<string | null>(null);
  const isLoadingMessages = useRef(false);
  const [isHistoryLoading, setIsHistoryLoading] = useState(false);

  useEffect(() => {
    if (currentSession?.id) {
      // Only load if this is a different session than the last one loaded
      // and we're not already loading
      if (
        lastLoadedSessionId.current !== currentSession.id &&
        !isLoadingMessages.current &&
        !isHistoryLoading
      ) {
        lastLoadedSessionId.current = currentSession.id;
        setIsHistoryLoading(true);
        // Clear messages first to prevent showing old messages
        setMessages([]);

        loadMessagesFromSession(currentSession.id).finally(() => {
          setIsHistoryLoading(false);
          isLoadingMessages.current = false;
        });
      }
    } else {
      lastLoadedSessionId.current = null;
      setIsHistoryLoading(false);
      isLoadingMessages.current = false;
      setMessages([]);
    }
  }, [
    currentSession?.id,
    loadMessagesFromSession,
    isHistoryLoading,
    setMessages,
  ]);

  const handleNewSession = async () => {
    clearSession();
    clearMessages();
    setShowHistory(false);
    // Session will be created automatically on the first message send
  };

  const handleSessionSelect = async (sessionId: string) => {
    // Force a reload by resetting the ref
    lastLoadedSessionId.current = null;
    setMessages([]);
    setShowHistory(false); // Close the history overlay
    await loadSession(sessionId);
  };

  // Use keyboard shortcuts hook
  useKeyboardShortcuts({
    showSettings,
    showHistory,
    setShowSettings,
    setShowHistory,
    handleNewSession,
  });

  const handleExport = () => {
    if (!currentSession) {
      toast.info("Crea o selecciona una conversación para exportar");
      return;
    }
    if (messages.length === 0) {
      toast.info("No hay mensajes para exportar en esta conversación");
      return;
    }
    // Defer to next tick: Radix DropdownMenu closing interferes with Dialog opening
    // (pointer-events stuck on body). See radix-ui/primitives#3317
    setTimeout(() => setShowExport(true), 0);
  };

  const handleClear = () => {
    if (confirm("¿Estás seguro de que deseas limpiar esta conversación?")) {
      clearMessages();
    }
  };

  const handleDelete = async () => {
    if (!currentSession) return;
    if (confirm("¿Estás seguro de que deseas eliminar esta sesión?")) {
      try {
        const response = await fetch(
          `/api/admin/chat/history?sessionId=${currentSession.id}`,
          {
            method: "DELETE",
          },
        );
        if (response.ok) {
          await handleNewSession();
        }
      } catch (error) {
        appLogger.error("Error deleting session:", error);
      }
    }
  };

  const sessionTitle = currentSession?.title || "Nueva conversación";

  return (
    <div className={cn("flex h-full min-h-0 overflow-hidden", className)}>
      {showHistory && (
        <div className="absolute inset-0 z-[60] bg-white dark:bg-slate-950 overflow-y-auto animate-in slide-in-from-left duration-300">
          <ChatHistorySidebar
            currentSessionId={currentSession?.id}
            onClose={() => setShowHistory(false)}
            onNewSession={handleNewSession}
            onSessionSelect={handleSessionSelect}
          />
        </div>
      )}

      <div className="flex-1 flex flex-col min-h-0 overflow-hidden relative">
        {showSettings && (
          <div className="absolute inset-0 z-[60] bg-white dark:bg-slate-950 overflow-y-auto animate-in slide-in-from-right duration-300">
            <SettingsPanel
              config={config}
              onClose={() => setShowSettings(false)}
              onConfigChange={updateChatConfig}
            />
          </div>
        )}
        {/* Fixed Header */}
        <div className="flex-shrink-0 z-20 bg-admin-bg-primary border-b border-admin-border-primary">
          <ChatHeader
            isSidebarMode={isSidebarMode}
            title={sessionTitle}
            onClear={handleClear}
            onClose={onClose}
            onDelete={handleDelete}
            onExpandClick={onExpandClick}
            onExport={handleExport}
            onHistoryClick={() => setShowHistory(!showHistory)}
            onNewConversation={handleNewSession}
            onSettingsClick={() => setShowSettings(!showSettings)}
            onTitleChange={(title) => {
              if (currentSession) {
                updateSessionTitle(currentSession.id, title);
              }
            }}
          />
        </div>

        {/* Scrollable Messages Area */}
        <div className="flex-1 flex min-h-0 relative overflow-hidden">
          <div className="flex-1 flex flex-col min-h-0 overflow-hidden bg-white dark:bg-slate-950">
            <div className="flex-1 overflow-y-auto min-h-0">
              <MessageList
                isStreaming={isStreaming && !currentStreamingContent}
                messages={messages}
                onMessageAction={(messageId, action) => {
                  if (action === "copy") {
                    const message = messages.find((m) => m.id === messageId);
                    if (message) {
                      navigator.clipboard.writeText(message.content);
                    }
                  } else if (action === "delete") {
                    setMessages((prev) =>
                      prev.filter((m) => m.id !== messageId),
                    );
                  } else if (action === "regenerate") {
                    regenerateMessage(messageId);
                  }
                }}
              />
            </div>
          </div>
        </div>

        {/* Fixed Input at Bottom */}
        <div className="flex-shrink-0 z-10 bg-white dark:bg-slate-900 border-t border-slate-100 dark:border-slate-800">
          {/* Quick Suggestions */}
          {currentSection && messages.length === 0 && !isStreaming && (
            <div className="p-4 border-b border-slate-50 dark:border-slate-800/50 animate-in fade-in slide-in-from-bottom-2 duration-300">
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-3 ml-1">
                Sugerencias rápidas
              </p>
              <div className="flex flex-wrap gap-2">
                {quickSuggestions[currentSection].map((suggestion, index) => (
                  <button
                    className="text-xs px-4 py-2.5 rounded-xl bg-slate-50 dark:bg-slate-800 hover:bg-primary hover:text-white border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed shadow-sm active:scale-95 group flex items-center gap-2"
                    disabled={isStreaming}
                    key={index}
                    onClick={() => {
                      if (!isStreaming) {
                        sendMessage(suggestion);
                      }
                    }}
                  >
                    <Sparkles className="w-3 h-3 text-primary group-hover:text-white transition-colors" />
                    {suggestion}
                  </button>
                ))}
              </div>
            </div>
          )}
          <ChatInput
            disabled={isStreaming}
            placeholder={
              currentSection
                ? `Pregunta sobre ${currentSection === "dashboard" ? "el dashboard" : currentSection === "inventory" ? "inventario" : currentSection === "clients" ? "clientes" : currentSection === "pos" ? "ventas" : "analíticas"}...`
                : "Escribe tu mensaje..."
            }
            onSend={(msg, fileId) => sendMessage(msg, fileId)}
            onStop={stopStreaming}
          />
        </div>
      </div>

      {currentSession && (
        <ExportDialog
          messages={messages}
          open={showExport}
          session={currentSession}
          onOpenChange={setShowExport}
        />
      )}
    </div>
  );
}

