  const mockProps = {
    appointmentType: "consultation",
    status: "scheduled",
    reason: "",
    notes: "",
    followUpRequired: false,
    followUpDate: "",
    appointmentTypes: mockAppointmentTypes,
    onTypeChange: vi.fn(),
    onStatusChange: vi.fn(),
    onReasonChange: vi.fn(),
    onNotesChange: vi.fn(),
    onFollowUpToggle: vi.fn(),
