  beforeEach(() => {
    mockUseBranch.mockReturnValue({
      currentBranchId: "test-branch-123",
      currentBranchName: "Test Branch",
      canSwitchBranch: false,
      hasMultipleBranches: false,
      branches: [
        { id: "test-branch-123", name: "Test Branch", code: "TEST001" },
      ],
      currentBranch: {
        id: "test-branch-123",
        name: "Test Branch",
        code: "TEST001",
      },
      organizationId: "test-org-123",
      isGlobalView: false,
      isSuperAdmin: false,
      isLoading: false,
      setCurrentBranch: vi.fn(),
      refreshBranches: vi.fn(),
    });

    mockUseAuthContext.mockReturnValue({
      user: null,
      profile: null,
      session: null,
      loading: false,
      error: null,
      signUp: vi.fn(),
      signIn: vi.fn(),
      signOut: vi.fn(),
      updateProfile: vi.fn(),
      resetPassword: vi.fn(),
      refetchProfile: vi.fn(),
      refetchAdminStatus: vi.fn(),
      isAdmin: false,
      isSuperAdmin: false,
      adminRole: null,
    });

    // Mock fetch globally
    global.fetch = vi.fn();

    // Clear all mocks
    vi.clearAllMocks();
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  it("should initialize with default form data when no initial data provided", () => {
    const { result } = renderHook(() =>
      useAppointmentForm({ scheduleSettings: mockScheduleSettings }),
    );

    const today = new Date().toISOString().split("T")[0];

    expect(result.current.formData).toEqual({
