      appointment_time: "",
      duration_minutes: 30,
      appointment_type: "consultation",
      status: "scheduled",
      assigned_to: null,
      notes: "",
      reason: "",
      follow_up_required: false,
      follow_up_date: "",
      prescription_id: null,
      order_id: null,
