import { useEffect, useState } from "react";

import { useAuthContext } from "@/contexts/AuthContext";
import { useBranch } from "@/hooks/useBranch";
import { appLogger } from '@/lib/logger';
import { getBranchHeader } from "@/lib/utils/branch";

interface AppointmentFormData {
  appointment_date: string;
  appointment_time: string;
  duration_minutes: number;
  appointment_type: string;
  status: string;
  assigned_to: string | null;
  notes: string;
  reason: string;
  follow_up_required: boolean;
  follow_up_date: string;
  prescription_id: string | null;
  order_id: string | null;
}

interface UseAppointmentFormProps {
  initialData?: unknown;
  scheduleSettings: unknown;
  effectiveBranchId?: string | null;
}

export function useAppointmentForm({
  initialData,
  scheduleSettings,
  effectiveBranchId,
}: UseAppointmentFormProps) {
  const { user, loading: authLoading } = useAuthContext();
  const { currentBranchId } = useBranch();
  const branchIdForRequest =
    effectiveBranchId !== undefined ? effectiveBranchId : currentBranchId;
  const [saving, setSaving] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});

  // Form data
  const [formData, setFormData] = useState<AppointmentFormData>({
    appointment_date:
      initialData?.appointment_date ||
      initialData?.date ||
      new Date().toISOString().split("T")[0],
    appointment_time: initialData?.appointment_time || initialData?.time || "",
    duration_minutes:
      initialData?.duration_minutes ||
      scheduleSettings?.default_appointment_duration ||
      30,
    appointment_type: initialData?.appointment_type || "consultation",
    status: initialData?.status || "scheduled",
    assigned_to: initialData?.assigned_to || null,
    notes: initialData?.notes || "",
    reason: initialData?.reason || "",
    follow_up_required: initialData?.follow_up_required || false,
    follow_up_date: initialData?.follow_up_date || "",
    prescription_id: initialData?.prescription_id || null,
    order_id: initialData?.order_id || null,
  });

  // Update form data when initialData changes (for prefilled slots)
  useEffect(() => {
    if (initialData?.date || initialData?.appointment_date) {
      const newDate = initialData.appointment_date || initialData.date;
      const newTime = initialData.appointment_time || initialData.time;

      setFormData((prev) => ({
        ...prev,
        appointment_date: newDate || prev.appointment_date,
        appointment_time: newTime || prev.appointment_time,
      }));
    }
  }, [initialData]);

  // Update duration when schedule settings load
  useEffect(() => {
    if (scheduleSettings && !initialData?.duration_minutes) {
      const defaultDuration =
        scheduleSettings.default_appointment_duration || 30;
      setFormData((prev) => ({
        ...prev,
        duration_minutes: defaultDuration,
      }));
    }
  }, [scheduleSettings, initialData?.duration_minutes]);

  const updateField = (field: keyof AppointmentFormData, value: unknown) => {
    setFormData((prev) => ({ ...prev, [field]: value }));
    // Clear error for this field
    if (errors[field]) {
      setErrors((prev) => ({ ...prev, [field]: "" }));
    }
  };

  const updateFormData = (data: Partial<AppointmentFormData>) => {
    setFormData((prev) => ({ ...prev, ...data }));
    // Clear errors for updated fields
    const newErrors = { ...errors };
    Object.keys(data).forEach((field) => {
      if (newErrors[field as keyof AppointmentFormData]) {
        delete newErrors[field as keyof AppointmentFormData];
      }
    });
    setErrors(newErrors);
  };

  const validate = (): boolean => {
    const newErrors: Record<string, string> = {};

    // Validate required fields
    if (!formData.appointment_date) {
      newErrors.appointment_date = "La fecha es obligatoria";
    }

    if (!formData.appointment_time) {
      newErrors.appointment_time = "La hora es obligatoria";
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const resetForm = () => {
    setFormData({
      appointment_date: new Date().toISOString().split("T")[0],
      appointment_time: "",
      duration_minutes: scheduleSettings?.default_appointment_duration || 30,
      appointment_type: "consultation",
      status: "scheduled",
      assigned_to: null,
      notes: "",
      reason: "",
      follow_up_required: false,
      follow_up_date: "",
      prescription_id: null,
      order_id: null,
    });
    setErrors({});
  };

  const handleSubmit = async (
    e: React.FormEvent,
    selectedCustomer: unknown,
    isGuestCustomer: boolean,
    guestCustomerData: unknown,
    onSuccess: () => void,
    lockDateTime: boolean = false,
  ) => {
    e.preventDefault();

    // Validate form
    if (!validate()) {
      return false;
    }

    // Validate customer selection or guest customer data
    if (isGuestCustomer) {
      // Validate guest customer data
      if (!guestCustomerData.first_name?.trim()) {
        setErrors((prev) => ({
          ...prev,
          guest_first_name: "El nombre es obligatorio",
        }));
        return false;
      }
      if (!guestCustomerData.last_name?.trim()) {
        setErrors((prev) => ({
          ...prev,
          guest_last_name: "El apellido es obligatorio",
        }));
        return false;
      }
      if (!guestCustomerData.rut?.trim()) {
        setErrors((prev) => ({ ...prev, guest_rut: "El RUT es obligatorio" }));
        return false;
      }
    } else {
      // Validate registered customer
      if (!selectedCustomer) {
        setErrors((prev) => ({
          ...prev,
          customer: "Selecciona un cliente registrado",
        }));
        return false;
      }
    }

    setSaving(true);
    try {
      const url = initialData?.id
        ? `/api/admin/appointments/${initialData.id}`
        : "/api/admin/appointments";

      const method = initialData?.id ? "PUT" : "POST";

      // Ensure time format is correct (HH:MM:SS)
      let appointmentTime = formData.appointment_time;
      if (appointmentTime && appointmentTime.includes(":")) {
        const parts = appointmentTime.split(":");
        if (parts.length === 2) {
          // If format is HH:MM, add :00 seconds
          appointmentTime = appointmentTime + ":00";
        } else if (parts.length === 3 && parts[2] === "") {
          // If format is HH:MM:, add 00
          appointmentTime = appointmentTime + "00";
        }
      }

      const requestBody: unknown = {
        appointment_date: formData.appointment_date,
        appointment_time: appointmentTime,
        duration_minutes: formData.duration_minutes,
        appointment_type: formData.appointment_type,
        status: formData.status,
        assigned_to: formData.assigned_to || null,
        notes: formData.notes || null,
        reason: formData.reason || null,
        follow_up_required: formData.follow_up_required,
        follow_up_date: formData.follow_up_date || null,
        prescription_id: formData.prescription_id || null,
        order_id: formData.order_id || null,
        cancellation_reason: null,
      };

      // If guest customer, send guest data to store in appointment
      if (isGuestCustomer) {
        // Import formatRUT here or pass it as dependency
        const formattedRUT = guestCustomerData.rut?.trim() || "";
        requestBody.guest_customer = {
          first_name: guestCustomerData.first_name?.trim(),
          last_name: guestCustomerData.last_name?.trim(),
          rut: formattedRUT,
          email: guestCustomerData.email?.trim() || null,
          phone: guestCustomerData.phone?.trim() || null,
        };
      } else {
        requestBody.customer_id = selectedCustomer.id;
      }

      const headers = {
        "Content-Type": "application/json",
        ...getBranchHeader(branchIdForRequest),
      };

      // Super admin in global view: send branch_id in body so API can create appointment
      if (branchIdForRequest) {
        requestBody.branch_id = branchIdForRequest;
      }

      const response = await fetch(url, {
        method,
        headers,
        body: JSON.stringify(requestBody),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || "Error al guardar cita");
      }

      return true;
    } catch (error: unknown) {
      appLogger.error("Error saving appointment:", error);
      throw error;
    } finally {
      setSaving(false);
    }
  };

  return {
    formData,
    updateField,
    updateFormData,
    validate,
    errors,
    saving,
    setSaving,
    resetForm,
    handleSubmit,
  };
}

import { useState } from "react";
import { toast } from "sonner";

import { useBranch } from "@/hooks/useBranch";
import { appLogger } from '@/lib/logger';
import { getBranchHeader } from "@/lib/utils/branch";

interface TimeSlot {
  time_slot: string;
  available: boolean;
}

interface UseAvailabilityReturn {
  availableSlots: TimeSlot[];
  loading: boolean;
  fetchAvailability: (date: string, duration: number) => Promise<void>;
  isSlotAvailable: (timeSlot: string) => boolean;
  clearSlots: () => void;
}

interface UseAvailabilityProps {
  scheduleSettings: unknown;
  effectiveBranchId?: string | null;
}

export function useAvailability({
  scheduleSettings,
  effectiveBranchId,
}: UseAvailabilityProps): UseAvailabilityReturn {
  const { currentBranchId } = useBranch();
  const branchIdForRequest =
    effectiveBranchId !== undefined ? effectiveBranchId : currentBranchId;
  const [availableSlots, setAvailableSlots] = useState<TimeSlot[]>([]);
  const [loading, setLoading] = useState(false);

  const fetchAvailability = async (date: string, duration: number) => {
    if (!date) {
      appLogger.info("No date selected, clearing availability");
      setAvailableSlots([]);
      return;
    }

    if (!scheduleSettings) {
      appLogger.info(
        "Schedule settings not loaded yet, skipping availability fetch",
      );
      return;
    }

    const selectedDate = new Date(date + "T00:00:00");
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const isToday = selectedDate.getTime() === today.getTime();

    appLogger.info("🔍 Fetching availability for:", {
      date,
      duration,
      isToday,
      scheduleSettings: scheduleSettings ? "loaded" : "not loaded",
      minAdvanceHours: scheduleSettings?.min_advance_booking_hours || 0,
    });

    setLoading(true);
    try {
      const params = new URLSearchParams({
        date,
        duration: duration.toString(),
      });

      const headers = {
        "Content-Type": "application/json",
        ...getBranchHeader(branchIdForRequest),
      };

      const response = await fetch(
        `/api/admin/appointments/availability?${params}`,
        { headers },
      );

      if (response.ok) {
        const data = await response.json();
        appLogger.info("✅ Available slots response:", data);
        appLogger.info("📊 Total slots:", data.slots?.length || 0);
        const availableCount =
          data.slots?.filter((s: unknown) => s.available === true).length || 0;
        appLogger.info("📊 Available slots:", availableCount);
        appLogger.info("📋 First few slots:", data.slots?.slice(0, 5));

        if (data.slots && data.slots.length > 0) {
          appLogger.info(
            "✅ Setting available slots:",
            data.slots.length,
            "total,",
            availableCount,
            "available",
          );
          setAvailableSlots(data.slots);
        } else {
          appLogger.warn("⚠️ No slots returned from API - empty array");
          setAvailableSlots([]);
        }
      } else {
        const errorData = await response.json();
        appLogger.error("Error fetching availability:", errorData);
        toast.error(errorData.error || "Error al cargar disponibilidad");
        setAvailableSlots([]);
      }
    } catch (error) {
      appLogger.error("Error fetching availability:", error);
      toast.error("Error al cargar disponibilidad");
      setAvailableSlots([]);
    } finally {
      setLoading(false);
    }
  };

  const isSlotAvailable = (timeSlot: string) => {
    const slot = availableSlots.find((s) => s.time_slot === timeSlot);
    return slot?.available || false;
  };

  const clearSlots = () => {
    setAvailableSlots([]);
  };

  return {
    availableSlots,
    loading,
    fetchAvailability,
    isSlotAvailable,
    clearSlots,
  };
}

import { useEffect, useState } from "react";

import { appLogger } from '@/lib/logger';
import { getBranchHeader } from "@/lib/utils/branch";

interface Customer {
  id: string;
  first_name?: string;
  last_name?: string;
  email?: string;
  phone?: string;
  rut?: string;
}

interface GuestCustomerData {
  first_name: string;
  last_name: string;
  rut: string;
  email: string;
  phone: string;
}

interface UseCustomerSearchReturn {
  // Registered customer search
  customerSearch: string;
  setCustomerSearch: (search: string) => void;
  customerResults: Customer[];
  searchingCustomers: boolean;
  selectedCustomer: Customer | null;
  setSelectedCustomer: (customer: Customer | null) => void;
  clearCustomerSearch: () => void;

  // Guest customer mode
  isGuestCustomer: boolean;
  setIsGuestCustomer: (isGuest: boolean) => void;
  guestCustomerData: GuestCustomerData;
  updateGuestCustomerData: (data: Partial<GuestCustomerData>) => void;
  resetGuestCustomerData: () => void;

  // Validation
  validateCustomer: () => { isValid: boolean; errors: Record<string, string> };
}

interface UseCustomerSearchProps {
  initialData?: unknown;
  initialCustomerId?: string;
  /** Sucursal actual para filtrar clientes. Obligatorio para admins no super. */
  currentBranchId?: string | null;
}

export function useCustomerSearch({
  initialData,
  initialCustomerId,
  currentBranchId,
}: UseCustomerSearchProps = {}): UseCustomerSearchReturn {
  // Registered customer search
  const [customerSearch, setCustomerSearch] = useState("");
  const [customerResults, setCustomerResults] = useState<Customer[]>([]);
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(
    initialData?.customer || null,
  );
  const [searchingCustomers, setSearchingCustomers] = useState(false);

  // Guest customer mode
  const [isGuestCustomer, setIsGuestCustomer] = useState(
    !initialData?.customer && !initialCustomerId,
  );
  const [guestCustomerData, setGuestCustomerData] = useState<GuestCustomerData>(
    {
      first_name: "",
      last_name: "",
      rut: "",
      email: "",
      phone: "",
    },
  );

  // Search customers with debounce (filtered by branch)
  useEffect(() => {
    const searchCustomers = async () => {
      if (customerSearch.length < 1) {
        setCustomerResults([]);
        return;
      }

      setSearchingCustomers(true);
      try {
        const headers = getBranchHeader(currentBranchId ?? null);
        const response = await fetch(
          `/api/admin/customers/search?q=${encodeURIComponent(customerSearch)}`,
          { headers },
        );
        if (response.ok) {
          const data = await response.json();
          // API returns { success: true, data: [...] }
          setCustomerResults(data.data ?? data.customers ?? []);
        }
      } catch (error) {
        appLogger.error("Error searching customers:", error);
      } finally {
        setSearchingCustomers(false);
      }
    };

    const debounceTimer = setTimeout(searchCustomers, 300);
    return () => clearTimeout(debounceTimer);
  }, [customerSearch, currentBranchId]);

  // Load customer if initialCustomerId provided
  useEffect(() => {
    const fetchCustomer = async (customerId: string) => {
      try {
        const response = await fetch(`/api/admin/customers/${customerId}`);
        if (response.ok) {
          const data = await response.json();
          setSelectedCustomer(data.data);
        }
      } catch (error) {
        appLogger.error("Error fetching customer:", error);
      }
    };

    if (initialCustomerId && !selectedCustomer) {
      fetchCustomer(initialCustomerId);
    }
  }, [initialCustomerId, selectedCustomer]);

  const clearCustomerSearch = () => {
    setCustomerSearch("");
    setCustomerResults([]);
  };

  const updateGuestCustomerData = (data: Partial<GuestCustomerData>) => {
    setGuestCustomerData((prev) => ({ ...prev, ...data }));
  };

  const resetGuestCustomerData = () => {
    setGuestCustomerData({
      first_name: "",
      last_name: "",
      rut: "",
      email: "",
      phone: "",
    });
  };

  const validateCustomer = (): {
    isValid: boolean;
    errors: Record<string, string>;
  } => {
    const errors: Record<string, string> = {};

    if (isGuestCustomer) {
      // Validate guest customer data
      if (!guestCustomerData.first_name?.trim()) {
        errors.guest_first_name = "El nombre es obligatorio";
      }
      if (!guestCustomerData.last_name?.trim()) {
        errors.guest_last_name = "El apellido es obligatorio";
      }
      if (!guestCustomerData.rut?.trim()) {
        errors.guest_rut = "El RUT es obligatorio";
      }
    } else {
      // Validate registered customer
      if (!selectedCustomer) {
        errors.customer = "Selecciona un cliente registrado";
      }
    }

    return {
      isValid: Object.keys(errors).length === 0,
      errors,
    };
  };

  // Handle toggle between guest and registered customer
  const handleCustomerModeToggle = (isGuest: boolean) => {
    setIsGuestCustomer(isGuest);
    if (isGuest) {
      // Switching to guest mode
      setSelectedCustomer(null);
      clearCustomerSearch();
    } else {
      // Switching to registered mode
      resetGuestCustomerData();
    }
  };

  return {
    // Registered customer search
    customerSearch,
    setCustomerSearch,
    customerResults,
    searchingCustomers,
    selectedCustomer,
    setSelectedCustomer,
    clearCustomerSearch,

    // Guest customer mode
    isGuestCustomer,
    setIsGuestCustomer: handleCustomerModeToggle,
    guestCustomerData,
    updateGuestCustomerData,
    resetGuestCustomerData,

    // Validation
    validateCustomer,
  };
}

import { useEffect, useState } from "react";

import { useAuthContext } from "@/contexts/AuthContext";
import { useBranch } from "@/hooks/useBranch";
import { appLogger } from '@/lib/logger';
import { getBranchHeader } from "@/lib/utils/branch";

interface ScheduleSettings {
  id: string;
  organization_id: string;
  branch_id: string;
  working_days: string[];
  start_time: string;
  end_time: string;
  slot_duration_minutes: number;
  default_appointment_duration: number;
  min_advance_booking_hours: number;
  max_advance_booking_days: number;
  created_at: string;
  updated_at: string;
}

interface UseScheduleSettingsReturn {
  settings: ScheduleSettings | null;
  loading: boolean;
  loadSettings: () => Promise<void>;
  getMinDate: () => string;
  getMaxDate: () => string;
}

interface UseScheduleSettingsProps {
  effectiveBranchId?: string | null;
}

export function useScheduleSettings(
  props?: UseScheduleSettingsProps,
): UseScheduleSettingsReturn {
  const { user, loading: authLoading } = useAuthContext();
  const { currentBranchId } = useBranch();
  const effectiveBranchId = props?.effectiveBranchId;
  const branchIdForRequest =
    effectiveBranchId !== undefined ? effectiveBranchId : currentBranchId;
  const [settings, setSettings] = useState<ScheduleSettings | null>(null);
  const [loading, setLoading] = useState(false);

  const loadSettings = async () => {
    if (!user || authLoading) return;

    setLoading(true);
    try {
      const headers: HeadersInit = {
        "Content-Type": "application/json",
        ...getBranchHeader(branchIdForRequest),
      };

      const response = await fetch("/api/admin/schedule-settings", { headers });
      if (response.ok) {
        const data = await response.json();
        setSettings(data.data ?? data.settings);
      }
    } catch (error) {
      appLogger.error("Error fetching schedule settings:", error);
    } finally {
      setLoading(false);
    }
  };

  // Load schedule settings when branch or auth changes
  useEffect(() => {
    if (!authLoading && user) {
      loadSettings();
    }
  }, [branchIdForRequest, authLoading, user]);

  const getMinDate = (): string => {
    if (!settings) return new Date().toISOString().split("T")[0];
    const minHours = settings.min_advance_booking_hours || 2;
    const minDate = new Date();
    minDate.setHours(minDate.getHours() + minHours);
    return minDate.toISOString().split("T")[0];
  };

  const getMaxDate = (): string => {
    if (!settings) {
      const maxDate = new Date();
      maxDate.setDate(maxDate.getDate() + 90);
      return maxDate.toISOString().split("T")[0];
    }
    const maxDays = settings.max_advance_booking_days || 90;
    const maxDate = new Date();
    maxDate.setDate(maxDate.getDate() + maxDays);
    return maxDate.toISOString().split("T")[0];
  };

  return {
    settings,
    loading,
    loadSettings,
    getMinDate,
    getMaxDate,
  };
}

"use client";

import { CheckCircle, Loader2 } from "lucide-react";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
// Hooks
import { useBranch } from "@/hooks/useBranch";
import { appLogger } from '@/lib/logger';

import AppointmentDetails from "./AppointmentDetails";
import BranchSelectorForm from "./BranchSelector";
// Components (will be created next)
import CustomerSelection from "./CustomerSelection";
import DateTimeSelection from "./DateTimeSelection";
import { useAppointmentForm } from "./hooks/useAppointmentForm";
import { useAvailability } from "./hooks/useAvailability";
import { useCustomerSearch } from "./hooks/useCustomerSearch";
import { useScheduleSettings } from "./hooks/useScheduleSettings";
// Types
import type { CreateAppointmentFormProps } from "./types/appointment.types";
import { APPOINTMENT_TYPES } from "./types/appointment.types";

export default function CreateAppointmentForm({
  onSuccess,
  onCancel,
  initialData,
  initialCustomerId,
  lockDateTime = false,
  effectiveBranchId,
}: CreateAppointmentFormProps) {
  const { currentBranchId, isSuperAdmin, branches } = useBranch();

  // For super_admin: show branch selector. Use form selection or parent's effectiveBranchId.
  const [formBranchId, setFormBranchId] = useState<string | null>(
    effectiveBranchId ?? null,
  );
  useEffect(() => {
    if (effectiveBranchId) setFormBranchId(effectiveBranchId);
  }, [effectiveBranchId]);
  useEffect(() => {
    if (isSuperAdmin && branches.length > 0 && !formBranchId) {
      setFormBranchId(effectiveBranchId ?? branches[0]?.id ?? null);
    }
  }, [isSuperAdmin, branches, effectiveBranchId, formBranchId]);

  const effectiveBranchForForm =
    effectiveBranchId ??
    formBranchId ??
    (isSuperAdmin ? null : currentBranchId);

  const scheduleSettingsHook = useScheduleSettings({
    effectiveBranchId: effectiveBranchForForm,
  });
  const customerSearchHook = useCustomerSearch({
    initialData,
    initialCustomerId,
    currentBranchId: effectiveBranchForForm ?? currentBranchId,
  });
  const availabilityHook = useAvailability({
    scheduleSettings: scheduleSettingsHook.settings,
    effectiveBranchId: effectiveBranchForForm,
  });
  const appointmentFormHook = useAppointmentForm({
    initialData,
    scheduleSettings: scheduleSettingsHook.settings,
    effectiveBranchId: effectiveBranchForForm,
  });

  // Load availability when date or duration changes
  useEffect(() => {
    if (
      appointmentFormHook.formData.appointment_date &&
      scheduleSettingsHook.settings
    ) {
      // Add a small delay to ensure state is ready
      const timer = setTimeout(() => {
        appLogger.info("⏰ Calling fetchAvailability after delay");
        availabilityHook.fetchAvailability(
          appointmentFormHook.formData.appointment_date,
          appointmentFormHook.formData.duration_minutes,
        );
      }, 100);
      return () => clearTimeout(timer);
    }
  }, [
    appointmentFormHook.formData.appointment_date,
    appointmentFormHook.formData.duration_minutes,
    scheduleSettingsHook.settings,
  ]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      // Validate customer first
      const customerValidation = customerSearchHook.validateCustomer();
      if (!customerValidation.isValid) {
        Object.values(customerValidation.errors).forEach((error) =>
          toast.error(error),
        );
        return;
      }

      // Handle form submission
      const success = await appointmentFormHook.handleSubmit(
        e,
        customerSearchHook.selectedCustomer,
        customerSearchHook.isGuestCustomer,
        customerSearchHook.guestCustomerData,
        onSuccess,
        lockDateTime,
      );

      if (success) {
        if (appointmentFormHook.formData.status === "completed") {
          toast.success(
            "Cita completada. El cliente ha sido registrado exitosamente en la base de datos de esta sucursal.",
          );
        } else {
          toast.success(
            initialData?.id
              ? "Cita actualizada exitosamente"
              : "Cita creada exitosamente",
          );
        }
        onSuccess();
      }
    } catch (error: unknown) {
      appLogger.error("Error saving appointment:", error);
      toast.error(error.message || "Error al guardar cita");
    }
  };

  const canSubmit =
    !appointmentFormHook.saving &&
    !!appointmentFormHook.formData.appointment_time &&
    (!isSuperAdmin || !!effectiveBranchForForm);

  return (
    <form className="space-y-8 pb-4" onSubmit={handleSubmit}>
      {isSuperAdmin && (
        <BranchSelectorForm
          branches={branches}
          effectiveBranchForForm={effectiveBranchForForm}
          formBranchId={formBranchId}
          onBranchChange={(v) => setFormBranchId(v || null)}
        />
      )}

      {/* Customer Selection */}
      <CustomerSelection
        customerResults={customerSearchHook.customerResults}
        customerSearch={customerSearchHook.customerSearch}
        guestCustomerData={customerSearchHook.guestCustomerData}
        isGuestCustomer={customerSearchHook.isGuestCustomer}
        searchingCustomers={customerSearchHook.searchingCustomers}
        selectedCustomer={customerSearchHook.selectedCustomer}
        onCustomerClear={() => {
          customerSearchHook.setSelectedCustomer(null);
          appointmentFormHook.updateField("prescription_id", null);
        }}
        onCustomerSearchChange={customerSearchHook.setCustomerSearch}
        onCustomerSearchClear={customerSearchHook.clearCustomerSearch}
        onCustomerSelect={customerSearchHook.setSelectedCustomer}
        onGuestDataChange={customerSearchHook.updateGuestCustomerData}
        onGuestModeToggle={customerSearchHook.setIsGuestCustomer}
      />

      {/* Date and Time Selection */}
      <DateTimeSelection
        availableSlots={availabilityHook.availableSlots}
        date={appointmentFormHook.formData.appointment_date}
        duration={appointmentFormHook.formData.duration_minutes}
        formatTime={(time: string) => {
          const [h, m] = time.split(":");
          return `${h}:${m}`;
        }}
        isSlotAvailable={availabilityHook.isSlotAvailable}
        loadingAvailability={availabilityHook.loading}
        lockDateTime={lockDateTime}
        maxDate={scheduleSettingsHook.getMaxDate()}
        minDate={scheduleSettingsHook.getMinDate()}
        time={appointmentFormHook.formData.appointment_time}
        onDateChange={(date: string) => {
          if (lockDateTime) return;
          const today = new Date().toISOString().split("T")[0];
          if (date < today) {
            toast.error("No se pueden agendar citas en fechas pasadas");
            return;
          }
          appointmentFormHook.updateFormData({
            appointment_date: date,
            appointment_time: "",
          });
          availabilityHook.clearSlots();
        }}
        onDurationChange={(duration: number) => {
          appointmentFormHook.updateFormData({
            duration_minutes: duration,
            appointment_time: "",
          });
          availabilityHook.clearSlots();
        }}
        onLoadAvailability={() => {
          if (
            appointmentFormHook.formData.appointment_date &&
            scheduleSettingsHook.settings
          ) {
            availabilityHook.fetchAvailability(
              appointmentFormHook.formData.appointment_date,
              appointmentFormHook.formData.duration_minutes,
            );
          }
        }}
        onTimeChange={(time: string) =>
          appointmentFormHook.updateField("appointment_time", time)
        }
      />

      {/* Appointment Details */}
      <AppointmentDetails
        appointmentType={appointmentFormHook.formData.appointment_type}
        appointmentTypes={APPOINTMENT_TYPES}
        followUpDate={appointmentFormHook.formData.follow_up_date}
        followUpRequired={appointmentFormHook.formData.follow_up_required}
        notes={appointmentFormHook.formData.notes}
        reason={appointmentFormHook.formData.reason}
        status={appointmentFormHook.formData.status}
        onFollowUpDateChange={(date: string) =>
          appointmentFormHook.updateField("follow_up_date", date)
        }
        onFollowUpToggle={(required: boolean) =>
          appointmentFormHook.updateField("follow_up_required", required)
        }
        onNotesChange={(notes: string) =>
          appointmentFormHook.updateField("notes", notes)
        }
        onReasonChange={(reason: string) =>
          appointmentFormHook.updateField("reason", reason)
        }
        onStatusChange={(status: string) =>
          appointmentFormHook.updateField("status", status)
        }
        onTypeChange={(type: string) =>
          appointmentFormHook.updateField("appointment_type", type)
        }
      />

      {/* Actions */}
      <div className="flex items-center justify-end gap-4 pt-4">
        <Button
          className="h-12 px-8 rounded-xl font-bold text-admin-text-tertiary hover:bg-admin-bg-tertiary/20 uppercase text-[11px] tracking-widest transition-all"
          type="button"
          variant="ghost"
          onClick={onCancel}
        >
          Descartar
        </Button>
        <Button
          className="h-12 px-10 rounded-xl bg-admin-accent-primary hover:bg-admin-accent-primary/90 text-white shadow-premium-md font-bold uppercase text-[11px] tracking-widest transition-all active:scale-[0.98] disabled:opacity-50"
          disabled={!canSubmit}
          type="submit"
        >
          {appointmentFormHook.saving ? (
            <>
              <Loader2 className="h-4 w-4 mr-2 animate-spin" />
              Procesando...
            </>
          ) : (
            <>
              <CheckCircle className="h-4 w-4 mr-2" />
              {initialData?.id ? "Confirmar Cambios" : "Agendar Ahora"}
            </>
          )}
        </Button>
      </div>
    </form>
  );
}

"use client";

import React, { useState } from "react";

import { Button } from "@/components/ui/button";
import { FormFieldActions } from "@/components/ui/FormField";
import { useBranch } from "@/hooks/useBranch";
import { useFormSimple } from "@/hooks/useForm";
import { getUserFriendlyMessage,handleApiError } from "@/lib/api/services/errorService";
import { error as notifyError, success } from "@/lib/api/services/notificationService";

import { CustomerInfoSection, OrderDetailsSection, OrderItemsSection, ShippingSection } from "./_components/ManualOrderFormSections";
import type { OrderFormData } from "./_components/ManualOrderFormTypes";
import { calculateTotal, useClickOutside, useCustomerSearch, useProductSearch } from "./_hooks/useManualOrderForm";

interface CreateManualOrderFormProps {
  onSubmit: (orderData: unknown) => void;
  onCancel: () => void;
}

export default function CreateManualOrderForm({ onSubmit, onCancel }: CreateManualOrderFormProps) {
  const { currentBranchId } = useBranch();
  const form = useFormSimple<OrderFormData>(
    { email: "", status: "pending", payment_status: "paid", payment_method: "transfer", subtotal: 0, total_amount: 0, notes: "", shipping: { first_name: "", last_name: "", address_1: "", city: "", state: "", postal_code: "", phone: "" }, items: [] },
    async (data) => { await onSubmit(data); },
    { onSuccess: () => success("Pedido creado exitosamente"), onError: (err: unknown) => { const e = handleApiError(err, "CreateManualOrderForm"); notifyError(getUserFriendlyMessage(e)); } },
  );

  const [customerSearch, setCustomerSearch] = useState("");
  const [productSearch, setProductSearch] = useState("");
  const { customerResults, searchingCustomers, openCustomerSearch, setOpenCustomerSearch } = useCustomerSearch(customerSearch, currentBranchId);
  const { productResults, searchingProducts, openProductSearch, setOpenProductSearch } = useProductSearch(productSearch);
  useClickOutside(setOpenCustomerSearch, setOpenProductSearch);

  const handleShippingChange = (field: string, value: string) => {
    form.setValue("shipping", { ...form.getValues().shipping, [field]: value });
  };

  const loadCustomerData = (customer: Record<string, unknown>) => {
    form.setFieldValues({
      email: customer.email as string,
      shipping: {
        first_name: ((customer.name as string) || "").split(" ")[0] || "",
        last_name: ((customer.name as string) || "").split(" ").slice(1).join(" ") || "",
        address_1: (customer.shipping_info as Record<string, string>)?.address_1 || "",
        city: (customer.shipping_info as Record<string, string>)?.city || "",
        state: (customer.shipping_info as Record<string, string>)?.state || "",
        postal_code: (customer.shipping_info as Record<string, string>)?.postal_code || "",
        phone: (customer.shipping_info as Record<string, string>)?.phone || (customer.phone as string) || "",
      },
    });
    setCustomerSearch("");
    setOpenCustomerSearch(false);
  };

  const addProductToOrder = (product: Record<string, unknown>) => {
    form.setValue("items", [...form.getValues().items, { product_id: product.id as string, product_name: product.name as string, quantity: 1, unit_price: product.price as number }]);
    setProductSearch("");
    setOpenProductSearch(false);
    form.setFieldValues(calculateTotal(form.getValues().items));
  };

  const items = form.getValues().items;
  const addItem = () => form.setValue("items", [...items, { product_name: "", quantity: 1, unit_price: 0 }]);
  const removeItem = (index: number) => { form.setValue("items", items.filter((_: unknown, i: number) => i !== index)); form.setFieldValues(calculateTotal(form.getValues().items)); };
  const updateItem = (index: number, field: string, value: unknown) => { form.setValue("items", items.map((item: Record<string, unknown>, i: number) => i === index ? { ...item, [field]: value } : item)); form.setFieldValues(calculateTotal(form.getValues().items)); };

  return (
    <form className="space-y-6" onSubmit={form.handleSubmit}>
      <CustomerInfoSection customerResults={customerResults} customerSearch={customerSearch} email={form.values.email} openCustomerSearch={openCustomerSearch} searchingCustomers={searchingCustomers} onCustomerOpenChange={setOpenCustomerSearch} onCustomerSearchChange={setCustomerSearch} onEmailChange={(v) => form.setValue("email", v)} onLoadCustomer={loadCustomerData} />
      <OrderDetailsSection notes={form.values.notes} paymentMethod={form.values.payment_method} paymentStatus={form.values.payment_status} status={form.values.status} onNotesChange={(v) => form.setValue("notes", v)} onPaymentMethodChange={(v) => form.setValue("payment_method", v)} onPaymentStatusChange={(v) => form.setValue("payment_status", v)} onStatusChange={(v) => form.setValue("status", v)} />
      <ShippingSection shipping={form.values.shipping} onShippingChange={handleShippingChange} />
      <OrderItemsSection items={items} openProductSearch={openProductSearch} productResults={productResults} productSearch={productSearch} searchingProducts={searchingProducts} totalAmount={form.values.total_amount} onAddItem={addItem} onAddProduct={addProductToOrder} onCalculateTotal={() => form.setFieldValues(calculateTotal(form.getValues().items))} onProductOpenChange={setOpenProductSearch} onProductSearchChange={setProductSearch} onRemoveItem={removeItem} onUpdateItem={updateItem} />
      <FormFieldActions align="space-between">
        <Button type="button" variant="outline" onClick={onCancel}>Cancelar</Button>
        <Button disabled={form.isSubmitting} type="submit">{form.isSubmitting ? "Creando..." : "Crear Pedido"}</Button>
      </FormFieldActions>
    </form>
  );
}

"use client";

import { useEffect, useState } from "react";
import { toast } from "sonner";

import { useSystemConfig } from "@/app/admin/system/hooks/useSystemConfig";
import { appLogger } from '@/lib/logger';

import { PrescriptionFormGeneralInfo } from "./CreatePrescriptionFormGeneralInfo";
import { PrescriptionFormLeftEye } from "./CreatePrescriptionFormLeftEye";
import { PrescriptionFormNotes } from "./CreatePrescriptionFormNotes";
import { PrescriptionFormPupillaryDistance } from "./CreatePrescriptionFormPupillaryDistance";
import { PrescriptionFormRightEye } from "./CreatePrescriptionFormRightEye";
import { PrescriptionFormStatus } from "./CreatePrescriptionFormStatus";

interface CreatePrescriptionFormProps {
  customerId: string;
  onSuccess: () => void;
  onCancel: () => void;
  initialData?: unknown;
}

/** Add months to a date string (YYYY-MM-DD), returns YYYY-MM-DD */
function addMonthsToDate(dateStr: string, months: number): string {
  const d = new Date(dateStr + "T12:00:00");
  d.setMonth(d.getMonth() + months);
  return d.toISOString().split("T")[0];
}

export default function CreatePrescriptionForm({
  customerId,
  onSuccess,
  onCancel,
  initialData,
}: CreatePrescriptionFormProps) {
  const { configs } = useSystemConfig({ branchId: null });
  const expirationMonths =
    (configs?.find((c) => c.config_key === "prescription_expiration_months")
      ?.config_value as number) ?? 6;

  const [saving, setSaving] = useState(false);
  const [formData, setFormData] = useState({
    prescription_date:
      initialData?.prescription_date || new Date().toISOString().split("T")[0],
    expiration_date: initialData?.expiration_date || "",
    prescription_number: initialData?.prescription_number || "",
    issued_by: initialData?.issued_by || "",
    issued_by_license: initialData?.issued_by_license || "",

    // Right Eye (OD - Oculus Dexter)
    od_sphere: initialData?.od_sphere || "",
    od_cylinder: initialData?.od_cylinder || "",
    od_axis: initialData?.od_axis || "",
    od_add: initialData?.od_add || "",

    // Left Eye (OS - Oculus Sinister)
    os_sphere: initialData?.os_sphere || "",
    os_cylinder: initialData?.os_cylinder || "",
    os_axis: initialData?.os_axis || "",
    os_add: initialData?.os_add || "",

    // Pupillary Distance (Binocular)
    pd:
      initialData?.pd ||
      (initialData?.od_pd && initialData?.os_pd
        ? (
            parseFloat(initialData.od_pd) + parseFloat(initialData.os_pd)
          ).toString()
        : ""),
    near_pd:
      initialData?.near_pd ||
      (initialData?.od_near_pd && initialData?.os_near_pd
        ? (
            parseFloat(initialData.od_near_pd) +
            parseFloat(initialData.os_near_pd)
          ).toString()
        : ""),

    // Additional measurements
    frame_pd: initialData?.frame_pd || "",
    height_segmentation: initialData?.height_segmentation || "",

    // Prescription type
    prescription_type: initialData?.prescription_type || "",
    lens_type: initialData?.lens_type || "",
    lens_material: initialData?.lens_material || "",

    // Special requirements
    prism_od: initialData?.prism_od || "",
    prism_os: initialData?.prism_os || "",
    tint_od: initialData?.tint_od || "",
    tint_os: initialData?.tint_os || "",
    coatings: initialData?.coatings || ([] as string[]),

    // Notes
    notes: initialData?.notes || "",
    observations: initialData?.observations || "",
    recommendations: initialData?.recommendations || "",

    // Status
    is_active:
      initialData?.is_active !== undefined ? initialData.is_active : true,
    is_current:
      initialData?.is_current !== undefined ? initialData.is_current : false,
  });

  // Auto-calculate expiration_date when prescription_date changes (from system config)
  useEffect(() => {
    if (!formData.prescription_date) return;
    const expiration = addMonthsToDate(
      formData.prescription_date,
      expirationMonths,
    );
    setFormData((prev) =>
      prev.expiration_date !== expiration
        ? { ...prev, expiration_date: expiration }
        : prev,
    );
  }, [formData.prescription_date, expirationMonths]);

  const prescriptionTypes = [
    { value: "single_vision", label: "Visión Simple" },
    { value: "bifocal", label: "Bifocal" },
    { value: "trifocal", label: "Trifocal" },
    { value: "progressive", label: "Progresivo" },
    { value: "reading", label: "Lectura" },
    { value: "computer", label: "Computadora" },
    { value: "sports", label: "Deportivo" },
  ];

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Validate that at least one eye has prescription data
    const hasOD = formData.od_sphere || formData.od_cylinder || formData.od_add;
    const hasOS = formData.os_sphere || formData.os_cylinder || formData.os_add;

    if (!hasOD && !hasOS) {
      toast.error("Debe ingresar al menos una receta para OD o OS");
      return;
    }

    setSaving(true);
    try {
      const url = initialData?.id
        ? `/api/admin/customers/${customerId}/prescriptions/${initialData.id}`
        : `/api/admin/customers/${customerId}/prescriptions`;

      const method = initialData?.id ? "PUT" : "POST";

      const response = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          prescription_date: formData.prescription_date,
          expiration_date: formData.expiration_date || null,
          prescription_number: formData.prescription_number || null,
          issued_by: formData.issued_by || null,
          issued_by_license: formData.issued_by_license || null,
          od_sphere: formData.od_sphere ? parseFloat(formData.od_sphere) : null,
          od_cylinder: formData.od_cylinder
            ? parseFloat(formData.od_cylinder)
            : null,
          od_axis: formData.od_axis ? parseInt(formData.od_axis) : null,
          od_add: formData.od_add ? parseFloat(formData.od_add) : null,
          // Calculate monocular PD from binocular PD (divide by 2)
          od_pd: formData.pd ? parseFloat(formData.pd) / 2 : null,
          od_near_pd: formData.near_pd
            ? parseFloat(formData.near_pd) / 2
            : null,
          os_sphere: formData.os_sphere ? parseFloat(formData.os_sphere) : null,
          os_cylinder: formData.os_cylinder
            ? parseFloat(formData.os_cylinder)
            : null,
          os_axis: formData.os_axis ? parseInt(formData.os_axis) : null,
          os_add: formData.os_add ? parseFloat(formData.os_add) : null,
          os_pd: formData.pd ? parseFloat(formData.pd) / 2 : null,
          os_near_pd: formData.near_pd
            ? parseFloat(formData.near_pd) / 2
            : null,
          frame_pd: formData.frame_pd ? parseFloat(formData.frame_pd) : null,
          height_segmentation: formData.height_segmentation
            ? parseFloat(formData.height_segmentation)
            : null,
          prescription_type: formData.prescription_type || null,
          lens_type: formData.lens_type || null,
          lens_material: formData.lens_material || null,
          prism_od: formData.prism_od || null,
          prism_os: formData.prism_os || null,
          tint_od: formData.tint_od || null,
          tint_os: formData.tint_os || null,
          coatings: formData.coatings || [],
          notes: formData.notes || null,
          observations: formData.observations || null,
          recommendations: formData.recommendations || null,
          is_active: formData.is_active,
          is_current: formData.is_current,
        }),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || "Error al guardar receta");
      }

      toast.success(
        initialData?.id
          ? "Receta actualizada exitosamente"
          : "Receta creada exitosamente",
      );
      onSuccess();
    } catch (error: unknown) {
      appLogger.error("Error saving prescription:", error);
      toast.error(error.message || "Error al guardar receta");
    } finally {
      setSaving(false);
    }
  };

  const handleFieldChange = (field: string, value: unknown) => {
    setFormData((prev) => ({ ...prev, [field]: value }));
  };

  return (
    <form
      className="space-y-6 min-w-0 w-full overflow-hidden"
      onSubmit={handleSubmit}
    >
      <PrescriptionFormGeneralInfo
        formData={formData}
        prescriptionTypes={prescriptionTypes}
        onChange={handleFieldChange}
      />
      <PrescriptionFormRightEye
        formData={formData}
        onChange={handleFieldChange}
      />
      <PrescriptionFormLeftEye
        formData={formData}
        onChange={handleFieldChange}
      />
      <PrescriptionFormPupillaryDistance
        formData={formData}
        onChange={handleFieldChange}
      />
      <PrescriptionFormNotes
        formData={formData}
        onChange={handleFieldChange}
      />
      <PrescriptionFormStatus
        formData={formData}
        isEdit={!!initialData?.id}
        saving={saving}
        onCancel={onCancel}
        onChange={handleFieldChange}
      />
    </form>
  );
}

"use client";

import { Loader2, Plus } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";

interface Props {
  formData: Record<string, unknown>;
  onChange: (field: string, value: unknown) => void;
  saving: boolean;
  isEdit: boolean;
  onCancel: () => void;
}

export function PrescriptionFormStatus({
  formData,
  onChange,
  saving,
  isEdit,
  onCancel,
}: Props) {
  return (
    <>
      <Card className="overflow-hidden">
        <CardHeader className="flex-shrink-0">
          <CardTitle className="min-w-0 truncate">Estado</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4 min-w-0">
          <div className="flex items-center justify-between">
            <div>
              <Label>Receta Activa</Label>
              <p className="text-sm text-tierra-media">
                La receta está activa y puede ser usada
              </p>
            </div>
            <Switch
              checked={!!formData.is_active}
              onCheckedChange={(checked) => onChange("is_active", checked)}
            />
          </div>
          <div className="flex items-center justify-between">
            <div>
              <Label>Receta Actual</Label>
              <p className="text-sm text-tierra-media">
                Marcar como receta principal del paciente
              </p>
            </div>
            <Switch
              checked={!!formData.is_current}
              onCheckedChange={(checked) => onChange("is_current", checked)}
            />
          </div>
        </CardContent>
      </Card>

      <div className="flex justify-end gap-4">
        <Button type="button" variant="outline" onClick={onCancel}>
          Cancelar
        </Button>
        <Button disabled={saving} type="submit">
          {saving ? (
            <>
              <Loader2 className="h-4 w-4 mr-2 animate-spin" />
              Guardando...
            </>
          ) : (
            <>
              <Plus className="h-4 w-4 mr-2" />
              {isEdit ? "Actualizar Receta" : "Crear Receta"}
            </>
          )}
        </Button>
      </div>
    </>
  );
}

/**
 * CreateQuoteForm — Complete Quote Creation Form
 *
 * Handles optical quote creation with customer, frame, lens, and pricing sections.
 * State managed via useCreateQuoteForm hook; rendering delegated to 4 section components.
 */
"use client";



import type { CreateQuoteFormProps } from "./CreateQuoteForm/CreateQuoteForm.types";
import { CreateQuoteFormCustomerSection } from "./CreateQuoteForm/CreateQuoteFormCustomerSection";
import { CreateQuoteFormFrameSection } from "./CreateQuoteForm/CreateQuoteFormFrameSection";
import { CreateQuoteFormLensSection } from "./CreateQuoteForm/CreateQuoteFormLensSection";
import { CreateQuoteFormPricingSection } from "./CreateQuoteForm/CreateQuoteFormPricingSection";
import { useCreateQuoteForm } from "./CreateQuoteForm/useCreateQuoteForm";

export default function CreateQuoteForm(props: CreateQuoteFormProps) {
  const {
    formData,
    selectedCustomer,
    selectedPrescription,
    customerSearch,
    customerResults,
    searchingCustomers,
    prescriptions,
    loadingPrescriptions,
    presbyopiaSolution,
    showCreatePrescription,
    frameSearch,
    frameResults,
    selectedFrame,
    searchingFrames,
    nearFrameSearch,
    nearFrameResults,
    selectedNearFrame,
    searchingNearFrames,
    customerOwnFrame,
    customerOwnNearFrame,
    lensType,
    lensFamilies,
    loadingFamilies,
    contactLensFamilies,
    loadingContactLensFamilies,
    farLensFamilyId,
    nearLensFamilyId,
    farLensCost,
    nearLensCost,
    availableTreatments,
    calculatingPrice,
    calculatingContactLensPrice,
    manualLensPrice,
    discountType,
    saving,
    effectiveBranchId,
    loadingSettings,
    setCustomerSearch,
    setSelectedCustomer,
    setSelectedPrescription,
    setShowCreatePrescription,
    setFrameSearch,
    setSelectedFrame,
    setNearFrameSearch,
    setSelectedNearFrame,
    setCustomerOwnFrame,
    setCustomerOwnNearFrame,
    setManualLensPrice,
    setLensType,
    setPresbyopiaSolution,
    setFarLensFamilyId,
    setNearLensFamilyId,
    setDiscountType,
    setFormData,
    handleTreatmentToggle,
    handleFrameSelect,
    handleNearFrameSelect,
    handleSubmit,
    calculateTotal,
    fetchPrescriptions,
  } = useCreateQuoteForm(props);

  return (
    <form className="space-y-6" onSubmit={handleSubmit}>
      <CreateQuoteFormCustomerSection
        customerResults={customerResults}
        customerSearch={customerSearch}
        loadingPrescriptions={loadingPrescriptions}
        loadingSettings={loadingSettings}
        presbyopiaSolution={presbyopiaSolution}
        prescriptions={prescriptions}
        searchingCustomers={searchingCustomers}
        selectedCustomer={selectedCustomer}
        selectedPrescription={selectedPrescription}
        showCreatePrescription={showCreatePrescription}
        onCloseCreatePrescription={() => setShowCreatePrescription(false)}
        onCustomerClear={() => {
          setSelectedCustomer(null);
          setSelectedPrescription(null);
          setPrescriptions([]);
        }}
        onCustomerSearchChange={setCustomerSearch}
        onCustomerSelect={(c) => {
          setSelectedCustomer(c);
          setCustomerSearch("");
          setCustomerResults([]);
        }}
        onOpenCreatePrescription={() => setShowCreatePrescription(true)}
        onPresbyopiaSolutionChange={(v) => {
          setPresbyopiaSolution(v);
          setFormData((prev) => ({ ...prev, presbyopia_solution: v }));
          if (["progressive", "bifocal", "trifocal"].includes(v)) {
            setFormData((prev) => ({ ...prev, lens_type: v }));
          }
          if (v !== "two_separate") {
            setFarLensFamilyId("");
            setNearLensFamilyId("");
            setSelectedNearFrame(null);
            setCustomerOwnNearFrame(false);
            setNearFrameSearch("");
            setNearFrameResults([]);
            setFormData((prev) => ({
              ...prev,
              far_lens_family_id: "",
              near_lens_family_id: "",
              far_lens_cost: 0,
              near_lens_cost: 0,
              near_frame_product_id: "",
              near_frame_name: "",
              near_frame_brand: "",
              near_frame_model: "",
              near_frame_color: "",
              near_frame_size: "",
              near_frame_sku: "",
              near_frame_price: 0,
              near_frame_price_includes_tax: false,
              near_frame_cost: 0,
            }));
          }
        }}
        onPrescriptionCreated={(customerId) => fetchPrescriptions(customerId)}
        onPrescriptionSelect={(p) => {
          setSelectedPrescription(p);
        }}
      />

      <CreateQuoteFormFrameSection
        customerOwnFrame={customerOwnFrame}
        customerOwnNearFrame={customerOwnNearFrame}
        formData={formData}
        frameResults={frameResults}
        frameSearch={frameSearch}
        nearFrameResults={nearFrameResults}
        nearFrameSearch={nearFrameSearch}
        presbyopiaSolution={presbyopiaSolution}
        searchingFrames={searchingFrames}
        searchingNearFrames={searchingNearFrames}
        selectedFrame={selectedFrame}
        selectedNearFrame={selectedNearFrame}
        onCustomerOwnFrameChange={(checked) => {
          setCustomerOwnFrame(checked);
          if (checked) {
            setSelectedFrame(null);
            setFormData((prev) => ({
              ...prev,
              customer_own_frame: true,
              frame_product_id: "",
              frame_price: 0,
              frame_cost: 0,
            }));
          } else {
            setFormData((prev) => ({ ...prev, customer_own_frame: false }));
          }
        }}
        onCustomerOwnNearFrameChange={setCustomerOwnNearFrame}
        onFrameClear={() => {
          setSelectedFrame(null);
          setFormData((prev) => ({
            ...prev,
            frame_product_id: "",
            frame_name: "",
            frame_brand: "",
            frame_model: "",
            frame_color: "",
            frame_size: "",
            frame_sku: "",
            frame_price: 0,
            frame_cost: 0,
          }));
        }}
        onFrameFormDataChange={(field, value) => {
          setFormData((prev) => ({ ...prev, [field]: value }));
        }}
        onFrameSearchChange={setFrameSearch}
        onFrameSelect={(frame) => {
          setSelectedFrame(frame);
          const f = frame as unknown;
          setFormData((prev) => ({
            ...prev,
            frame_product_id: f.id,
            frame_name: f.name,
            frame_brand: f.frame_brand || "",
            frame_model: f.frame_model || "",
            frame_color: f.frame_color || "",
            frame_size: f.frame_size || "",
            frame_sku: f.sku || "",
            frame_price: f.price || 0,
            frame_price_includes_tax: f.price_includes_tax || false,
            frame_cost: f.price || 0,
          }));
          setFrameSearch("");
          setFrameResults([]);
        }}
        onNearFrameClear={() => {
          setSelectedNearFrame(null);
          setFormData((prev) => ({
            ...prev,
            near_frame_product_id: "",
            near_frame_name: "",
            near_frame_brand: "",
            near_frame_model: "",
            near_frame_color: "",
            near_frame_size: "",
            near_frame_sku: "",
            near_frame_price: 0,
            near_frame_cost: 0,
          }));
        }}
        onNearFrameFormDataChange={(field, value) => {
          setFormData((prev) => ({ ...prev, [field]: value }));
        }}
        onNearFrameSearchChange={setNearFrameSearch}
        onNearFrameSelect={(frame) => {
          setSelectedNearFrame(frame);
          const f = frame as unknown;
          setFormData((prev) => ({
            ...prev,
            near_frame_product_id: f.id,
            near_frame_name: f.name,
            near_frame_brand: f.frame_brand || "",
            near_frame_model: f.frame_model || "",
            near_frame_color: f.frame_color || "",
            near_frame_size: f.frame_size || "",
            near_frame_sku: f.sku || "",
            near_frame_price: f.price || 0,
            near_frame_price_includes_tax: f.price_includes_tax || false,
            near_frame_cost: f.price || 0,
          }));
          setNearFrameSearch("");
          setNearFrameResults([]);
        }}
      />

      {selectedPrescription && (
        <CreateQuoteFormLensSection
          availableTreatments={availableTreatments}
          calculatingContactLensPrice={calculatingContactLensPrice}
          calculatingPrice={calculatingPrice}
          contactLensFamilies={contactLensFamilies}
          farLensCost={farLensCost}
          farLensFamilyId={farLensFamilyId}
          formData={formData}
          lensFamilies={lensFamilies}
          lensType={lensType}
          loadingContactLensFamilies={loadingContactLensFamilies}
          loadingFamilies={loadingFamilies}
          manualLensPrice={manualLensPrice}
          nearLensCost={nearLensCost}
          nearLensFamilyId={nearLensFamilyId}
          presbyopiaSolution={presbyopiaSolution}
          selectedPrescription={selectedPrescription}
          onContactLensFamilyChange={(v) => {
            setFormData((prev) => ({
              ...prev,
              contact_lens_family_id: v,
              contact_lens_cost: 0,
              contact_lens_price: 0,
            }));
          }}
          onContactLensPriceChange={(p) => {
            setFormData((prev) => ({ ...prev, contact_lens_price: p }));
          }}
          onContactLensQuantityChange={(q) => {
            setFormData((prev) => ({ ...prev, contact_lens_quantity: q }));
          }}
          onFarLensFamilyChange={(v) => {
            setFarLensFamilyId(v);
            setFormData((prev) => ({ ...prev, far_lens_family_id: v }));
          }}
          onLensCostChange={(v) => {
            setFormData((prev) => ({ ...prev, lens_cost: v }));
          }}
          onLensFamilyChange={(v) => {
            setFormData((prev) => ({
              ...prev,
              lens_family_id: v,
              lens_cost: 0,
            }));
          }}
          onLensFormDataChange={(field, value) => {
            setFormData((prev) => ({ ...prev, [field]: value }));
          }}
          onLensTypeChange={(v) => {
            setLensType(v);
            if (v === "optical") {
              setFormData((prev) => ({
                ...prev,
                contact_lens_family_id: "",
                contact_lens_quantity: 1,
                contact_lens_cost: 0,
                contact_lens_price: 0,
              }));
            } else {
              setFormData((prev) => ({
                ...prev,
                lens_family_id: "",
                lens_cost: 0,
              }));
            }
          }}
          onManualLensPriceToggle={() => setManualLensPrice((v) => !v)}
          onNearLensFamilyChange={(v) => {
            setNearLensFamilyId(v);
            setFormData((prev) => ({ ...prev, near_lens_family_id: v }));
          }}
          onSourcingTypeChange={(v) => {
            setFormData((prev) => ({ ...prev, lens_sourcing_type: v }));
          }}
          onTreatmentToggle={handleTreatmentToggle}
        />
      )}

      <CreateQuoteFormPricingSection
        discountType={discountType}
        formData={formData}
        manualLensPrice={manualLensPrice}
        presbyopiaSolution={presbyopiaSolution}
        saving={saving}
        onCancel={props.onCancel}
        onDiscountChange={(field, value) => {
          setFormData((prev) => ({ ...prev, [field]: value }));
        }}
        onDiscountTypeChange={(v) => {
          setDiscountType(v);
          if (v === "percentage") {
            setFormData((prev) => ({ ...prev, discount_amount: 0 }));
          } else {
            setFormData((prev) => ({ ...prev, discount_percentage: 0 }));
          }
          setTimeout(() => calculateTotal(), 0);
        }}
        onExpirationDaysChange={(v) => {
          setFormData((prev) => ({ ...prev, expiration_days: v }));
        }}
        onFrameCostChange={(v) => {
          setFormData((prev) => ({ ...prev, frame_cost: v }));
        }}
        onLaborCostChange={(v) => {
          setFormData((prev) => ({ ...prev, labor_cost: v }));
        }}
        onLensCostChange={(v) => {
          setFormData((prev) => ({ ...prev, lens_cost: v }));
        }}
        onNotesChange={(notes, customerNotes) => {
          setFormData((prev) => ({
            ...prev,
            notes,
            customer_notes: customerNotes,
          }));
        }}
        onSubmit={handleSubmit}
      />
    </form>
  );
}

export function createCustomerHandlers(
  setSelectedCustomer: (c: unknown) => void,
  setCustomerSearch: (s: string) => void,
  setCustomerResults: (r: unknown[]) => void,
  setSelectedPrescription: (p: unknown) => void,
  setPrescriptions: (p: unknown[]) => void,
) {
  return {
    onCustomerSelect: (c: unknown) => { setSelectedCustomer(c); setCustomerSearch(""); setCustomerResults([]); },
    onCustomerClear: () => { setSelectedCustomer(null); setSelectedPrescription(null); setPrescriptions([]); },
  };
}

export function createFrameHandlers(
  setCustomerOwnFrame: (v: boolean) => void,
  setSelectedFrame: (f: unknown) => void,
  setFormData: React.Dispatch<React.SetStateAction<unknown>>,
  setFrameSearch: (s: string) => void,
  setFrameResults: (r: unknown[]) => void,
) {
  return {
    onCustomerOwnFrameChange: (checked: boolean) => {
      setCustomerOwnFrame(checked);
      setFormData((prev: Record<string, unknown>) => ({
        ...prev,
        customer_own_frame: checked,
        ...(checked ? { frame_product_id: "", frame_price: 0, frame_cost: 0 } : {}),
      }));
      if (checked) setSelectedFrame(null);
    },
    onFrameSelect: (frame: unknown) => {
      setSelectedFrame(frame);
      const f = frame as Record<string, unknown>;
      setFormData((prev: Record<string, unknown>) => ({
        ...prev, frame_product_id: f.id, frame_name: f.name, frame_brand: f.frame_brand || "",
        frame_model: f.frame_model || "", frame_color: f.frame_color || "", frame_size: f.frame_size || "",
        frame_sku: f.sku || "", frame_price: (f.price as number) || 0,
        frame_price_includes_tax: f.price_includes_tax || false, frame_cost: (f.price as number) || 0,
      }));
      setFrameSearch(""); setFrameResults([]);
    },
    onFrameClear: () => {
      setSelectedFrame(null);
      setFormData((prev: Record<string, unknown>) => ({
        ...prev, frame_product_id: "", frame_name: "", frame_brand: "", frame_model: "",
        frame_color: "", frame_size: "", frame_sku: "", frame_price: 0, frame_cost: 0,
      }));
    },
  };
}

/**
 * Customer & Prescription selection section for CreateQuoteForm.
 * Extracted from CreateQuoteForm.tsx.
 */
"use client";

import { Eye, Loader2, Plus, Search, User } from "lucide-react";

import CreatePrescriptionForm from "@/components/admin/CreatePrescriptionForm";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  getMaxAddition,
  hasAddition,
  type PresbyopiaSolution,
} from "@/lib/presbyopia-helpers";
import { translatePrescriptionType } from "@/lib/prescription-helpers";

export interface CreateQuoteFormCustomerSectionProps {
  loadingSettings: boolean;
  customerSearch: string;
  customerResults: unknown[];
  selectedCustomer: unknown;
  searchingCustomers: boolean;
  prescriptions: unknown[];
  selectedPrescription: unknown;
  loadingPrescriptions: boolean;
  presbyopiaSolution: PresbyopiaSolution;
  onCustomerSearchChange: (v: string) => void;
  onCustomerSelect: (customer: unknown) => void;
  onCustomerClear: () => void;
  onPrescriptionSelect: (prescription: unknown) => void;
  onPresbyopiaSolutionChange: (v: PresbyopiaSolution) => void;
  onOpenCreatePrescription: () => void;
  onCloseCreatePrescription: () => void;
  onPrescriptionCreated: (customerId: string) => void;
  showCreatePrescription: boolean;
  availableTreatments?: {
    value: string;
    label: string;
    cost: number;
    enabled: boolean;
  }[];
}

export function CreateQuoteFormCustomerSection({
  customerSearch,
  customerResults,
  selectedCustomer,
  searchingCustomers,
  prescriptions,
  selectedPrescription,
  loadingPrescriptions,
  presbyopiaSolution,
  onCustomerSearchChange,
  onCustomerSelect,
  onCustomerClear,
  onPrescriptionSelect,
  onPresbyopiaSolutionChange,
  onOpenCreatePrescription,
  onCloseCreatePrescription,
  onPrescriptionCreated,
  showCreatePrescription,
}: CreateQuoteFormCustomerSectionProps) {
  return (
    <>
      {/* Customer Selection */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center">
            <User className="h-5 w-5 mr-2" />
            Cliente
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          {selectedCustomer ? (
            <div
              className="flex items-center justify-between p-4 border rounded-lg bg-admin-bg-secondary"
              style={{ backgroundColor: "var(--admin-border-primary)" }}
            >
              <div>
                <div className="font-medium">
                  {(selectedCustomer as unknown).first_name}{" "}
                  {(selectedCustomer as unknown).last_name}
                </div>
                <div className="text-sm text-admin-text-tertiary">
                  {(selectedCustomer as unknown).email}
                </div>
              </div>
              <Button
                size="sm"
                type="button"
                variant="outline"
                onClick={onCustomerClear}
              >
                Cambiar
              </Button>
            </div>
          ) : (
            <div className="relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-admin-text-tertiary" />
              <Input
                className="pl-10"
                placeholder="Buscar cliente por nombre o email..."
                value={customerSearch}
                onChange={(e) => onCustomerSearchChange(e.target.value)}
              />
              {customerSearch.length >= 2 && (
                <div className="absolute z-10 w-full mt-1 bg-white border rounded-lg shadow-lg max-h-60 overflow-y-auto">
                  {searchingCustomers ? (
                    <div className="p-4 text-center">
                      <Loader2 className="h-4 w-4 animate-spin mx-auto" />
                    </div>
                  ) : (customerResults || []).length > 0 ? (
                    customerResults.map((customer: unknown) => (
                      <div
                        className="p-3 hover:bg-gray-100 cursor-pointer border-b"
                        key={customer.id}
                        onClick={() => {
                          onCustomerSelect(customer);
                        }}
                      >
                        <div className="font-medium">
                          {customer.first_name} {customer.last_name}
                        </div>
                        <div className="text-sm text-admin-text-tertiary space-y-1">
                          {customer.email && <div>{customer.email}</div>}
                          {customer.rut && <div>RUT: {customer.rut}</div>}
                        </div>
                      </div>
                    ))
                  ) : (
                    <div className="p-4 text-center text-admin-text-tertiary">
                      No se encontraron clientes
                    </div>
                  )}
                </div>
              )}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Prescription Selection */}
      {selectedCustomer && (
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center">
              <Eye className="h-5 w-5 mr-2" />
              Receta
            </CardTitle>
          </CardHeader>
          <CardContent>
            {loadingPrescriptions ? (
              <div className="text-center py-4">
                <Loader2 className="h-4 w-4 animate-spin mx-auto" />
              </div>
            ) : prescriptions.length === 0 ? (
              <div className="text-center py-4 space-y-3">
                <p className="text-admin-text-tertiary">
                  Este cliente no tiene recetas registradas
                </p>
                <Button
                  type="button"
                  variant="outline"
                  onClick={onOpenCreatePrescription}
                >
                  <Plus className="h-4 w-4 mr-2" />
                  Crear Nueva Receta
                </Button>
              </div>
            ) : (
              <Select
                value={(selectedPrescription as unknown)?.id || ""}
                onValueChange={(value) => {
                  const prescription = prescriptions.find(
                    (p: unknown) => p.id === value,
                  );
                  if (prescription) onPrescriptionSelect(prescription);
                }}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Selecciona una receta" />
                </SelectTrigger>
                <SelectContent>
                  {prescriptions.map((prescription: unknown) => (
                    <SelectItem key={prescription.id} value={prescription.id}>
                      {prescription.prescription_date} -{" "}
                      {translatePrescriptionType(
                        prescription.prescription_type,
                      )}
                      {prescription.is_current && " (Actual)"}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            )}
          </CardContent>
        </Card>
      )}

      {/* Prescription Summary */}
      {selectedPrescription && (
        <>
          <div className="p-4 border rounded-lg bg-blue-50 text-blue-900">
            <p className="font-medium mb-2">Resumen de Receta</p>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-sm">
              <div>
                <span className="font-semibold">OD:</span> Esf{" "}
                {(selectedPrescription as unknown).od_sphere ?? "—"} / Cil{" "}
                {(selectedPrescription as unknown).od_cylinder ?? "—"}
                {(selectedPrescription as unknown).od_add &&
                  (selectedPrescription as unknown).od_add > 0 && (
                    <span className="ml-2 text-orange-600">
                      Add: +{(selectedPrescription as unknown).od_add}
                    </span>
                  )}
              </div>
              <div>
                <span className="font-semibold">OS:</span> Esf{" "}
                {(selectedPrescription as unknown).os_sphere ?? "—"} / Cil{" "}
                {(selectedPrescription as unknown).os_cylinder ?? "—"}
                {(selectedPrescription as unknown).os_add &&
                  (selectedPrescription as unknown).os_add > 0 && (
                    <span className="ml-2 text-orange-600">
                      Add: +{(selectedPrescription as unknown).os_add}
                    </span>
                  )}
              </div>
            </div>
          </div>

          {/* Presbyopia Solution Selector */}
          {hasAddition(selectedPrescription as unknown) && (
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center text-sm">
                  <Eye className="h-4 w-4 mr-2" />
                  Solución para Presbicia
                </CardTitle>
              </CardHeader>
              <CardContent>
                <Alert className="mb-4">
                  <AlertDescription>
                    Esta receta tiene adición (+
                    {getMaxAddition(selectedPrescription as unknown)} D). Selecciona
                    cómo deseas manejar la presbicia.
                  </AlertDescription>
                </Alert>
                <RadioGroup
                  className="space-y-3"
                  value={presbyopiaSolution}
                  onValueChange={(value) => {
                    onPresbyopiaSolutionChange(value as PresbyopiaSolution);
                  }}
                >
                  <div className="flex items-center space-x-2">
                    <RadioGroupItem id="progressive" value="progressive" />
                    <Label className="cursor-pointer" htmlFor="progressive">
                      Progresivo (Recomendado)
                    </Label>
                  </div>
                  <div className="flex items-center space-x-2">
                    <RadioGroupItem id="bifocal" value="bifocal" />
                    <Label className="cursor-pointer" htmlFor="bifocal">
                      Bifocal
                    </Label>
                  </div>
                  <div className="flex items-center space-x-2">
                    <RadioGroupItem id="trifocal" value="trifocal" />
                    <Label className="cursor-pointer" htmlFor="trifocal">
                      Trifocal
                    </Label>
                  </div>
                  <div className="flex items-center space-x-2">
                    <RadioGroupItem id="two_separate" value="two_separate" />
                    <Label className="cursor-pointer" htmlFor="two_separate">
                      Dos lentes separados (Lejos + Cerca)
                    </Label>
                  </div>
                </RadioGroup>
              </CardContent>
            </Card>
          )}
        </>
      )}

      {/* Create Prescription Dialog */}
      {selectedCustomer && (
        <Dialog
          open={showCreatePrescription}
          onOpenChange={(open) => !open && onCloseCreatePrescription()}
        >
          <DialogContent className="max-w-[calc(100vw-2rem)] sm:max-w-7xl max-h-[90vh] overflow-y-auto p-6 sm:p-8">
            <DialogHeader>
              <DialogTitle>Nueva Receta</DialogTitle>
              <DialogDescription>
                Crea una nueva receta oftalmológica para{" "}
                {(selectedCustomer as unknown).first_name}{" "}
                {(selectedCustomer as unknown).last_name}
              </DialogDescription>
            </DialogHeader>
            <CreatePrescriptionForm
              customerId={(selectedCustomer as unknown).id}
              onCancel={onCloseCreatePrescription}
              onSuccess={() => {
                onCloseCreatePrescription();
                onPrescriptionCreated((selectedCustomer as unknown).id);
              }}
            />
          </DialogContent>
        </Dialog>
      )}
    </>
  );
}

/**
 * Frame selection section for CreateQuoteForm.
 * Extracted from CreateQuoteForm.tsx.
 */
"use client";

import { Loader2, Package, Search } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

import { formatPrice } from "./CreateQuoteForm.constants";

export interface CreateQuoteFormFrameSectionProps {
  presbyopiaSolution: string;
  customerOwnFrame: boolean;
  selectedFrame: unknown;
  frameSearch: string;
  frameResults: unknown[];
  searchingFrames: boolean;
  customerOwnNearFrame: boolean;
  selectedNearFrame: unknown;
  nearFrameSearch: string;
  nearFrameResults: unknown[];
  searchingNearFrames: boolean;
  formData: {
    frame_name: string;
    frame_sku: string;
    frame_price: number;
    frame_cost: number;
    frame_brand: string;
    frame_model: string;
    frame_color: string;
    frame_size: string;
    near_frame_name: string;
    near_frame_sku: string;
    near_frame_price: number;
    near_frame_cost: number;
    near_frame_brand: string;
    near_frame_model: string;
    near_frame_color: string;
    near_frame_size: string;
  };
  onCustomerOwnFrameChange: (checked: boolean) => void;
  onFrameSearchChange: (v: string) => void;
  onFrameSelect: (frame: unknown) => void;
  onFrameClear: () => void;
  onFrameFormDataChange: (field: string, value: unknown) => void;
  onCustomerOwnNearFrameChange: (checked: boolean) => void;
  onNearFrameSearchChange: (v: string) => void;
  onNearFrameSelect: (frame: unknown) => void;
  onNearFrameClear: () => void;
  onNearFrameFormDataChange: (field: string, value: unknown) => void;
}

export function CreateQuoteFormFrameSection({
  presbyopiaSolution,
  customerOwnFrame,
  selectedFrame,
  frameSearch,
  frameResults,
  searchingFrames,
  customerOwnNearFrame,
  selectedNearFrame,
  nearFrameSearch,
  nearFrameResults,
  searchingNearFrames,
  formData,
  onCustomerOwnFrameChange,
  onFrameSearchChange,
  onFrameSelect,
  onFrameClear,
  onFrameFormDataChange,
  onCustomerOwnNearFrameChange,
  onNearFrameSearchChange,
  onNearFrameSelect,
  onNearFrameClear,
  onNearFrameFormDataChange,
}: CreateQuoteFormFrameSectionProps) {
  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center">
          <Package className="h-5 w-5 mr-2" />
          {presbyopiaSolution === "two_separate" ? "Marco para Lejos" : "Marco"}
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Customer Own Frame Toggle */}
        <div className="flex items-center gap-2">
          <input
            checked={customerOwnFrame}
            className="h-4 w-4 rounded border-gray-300"
            id="customer_own_frame"
            type="checkbox"
            onChange={(e) => {
              onCustomerOwnFrameChange(e.target.checked);
              if (e.target.checked) {
                onFrameClear();
                onFrameFormDataChange("customer_own_frame", true);
                onFrameFormDataChange("frame_product_id", "");
                onFrameFormDataChange("frame_price", 0);
                onFrameFormDataChange("frame_cost", 0);
              } else {
                onFrameFormDataChange("customer_own_frame", false);
              }
            }}
          />
          <Label className="cursor-pointer" htmlFor="customer_own_frame">
            Cliente trae marco (recambio de cristales)
          </Label>
        </div>

        {customerOwnFrame ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mt-4">
            <div>
              <Label>Nombre del Marco *</Label>
              <Input
                required
                placeholder="Marco del cliente"
                value={formData.frame_name}
                onChange={(e) =>
                  onFrameFormDataChange("frame_name", e.target.value)
                }
              />
            </div>
            <div>
              <Label>Número de Serie</Label>
              <Input
                placeholder="Número de serie del marco"
                value={formData.frame_sku}
                onChange={(e) =>
                  onFrameFormDataChange("frame_sku", e.target.value)
                }
              />
            </div>
          </div>
        ) : selectedFrame ? (
          <div
            className="flex items-center justify-between p-4 border rounded-lg bg-admin-bg-secondary"
            style={{ backgroundColor: "var(--admin-border-primary)" }}
          >
            <div>
              <div className="font-medium">{(selectedFrame as unknown).name}</div>
              <div className="text-sm text-admin-text-tertiary">
                {(selectedFrame as unknown).frame_brand}{" "}
                {(selectedFrame as unknown).frame_model} · Stock:{" "}
                {(selectedFrame as unknown).total_available_quantity !== undefined
                  ? (selectedFrame as unknown).total_available_quantity
                  : (selectedFrame as unknown).total_inventory_quantity !==
                      undefined
                    ? (selectedFrame as unknown).total_inventory_quantity
                    : ((selectedFrame as unknown).available_quantity ??
                      (selectedFrame as unknown).inventory_quantity ??
                      0)}
              </div>
              <div className="text-sm font-semibold text-admin-success">
                {formatPrice((selectedFrame as unknown).price)}
              </div>
            </div>
            <Button
              size="sm"
              type="button"
              variant="outline"
              onClick={onFrameClear}
            >
              Cambiar
            </Button>
          </div>
        ) : (
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-admin-text-tertiary" />
            <Input
              className="pl-10"
              placeholder="Buscar marco por nombre, marca o SKU..."
              value={frameSearch}
              onChange={(e) => onFrameSearchChange(e.target.value)}
            />
            {frameSearch.length >= 2 && (
              <div className="absolute z-10 w-full mt-1 bg-white border rounded-lg shadow-lg max-h-60 overflow-y-auto">
                {searchingFrames ? (
                  <div className="p-4 text-center">
                    <Loader2 className="h-4 w-4 animate-spin mx-auto" />
                  </div>
                ) : (frameResults || []).length > 0 ? (
                  frameResults.map((frame: unknown) => (
                    <div
                      className="p-3 hover:bg-gray-100 cursor-pointer border-b"
                      key={frame.id}
                      onClick={() => onFrameSelect(frame)}
                    >
                      <div className="font-medium">{frame.name}</div>
                      <div className="text-sm text-admin-text-tertiary">
                        {frame.frame_brand} {frame.frame_model} - Stock:{" "}
                        {frame.available_quantity ??
                          frame.inventory_quantity ??
                          0}
                      </div>
                      <div className="text-sm font-semibold text-admin-success">
                        {formatPrice(frame.price)}
                      </div>
                    </div>
                  ))
                ) : (
                  <div className="p-4 text-center text-admin-text-tertiary">
                    No se encontraron marcos
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {/* Manual frame entry */}
        {!selectedFrame && !customerOwnFrame && (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mt-4">
            <div>
              <Label>Nombre del Marco</Label>
              <Input
                placeholder="Ej: Ray-Ban RB2140"
                value={formData.frame_name}
                onChange={(e) =>
                  onFrameFormDataChange("frame_name", e.target.value)
                }
              />
            </div>
            <div>
              <Label>Precio del Marco</Label>
              <Input
                placeholder="0"
                type="number"
                value={formData.frame_price || ""}
                onChange={(e) => {
                  const price = parseFloat(e.target.value) || 0;
                  onFrameFormDataChange("frame_price", price);
                  onFrameFormDataChange("frame_cost", price);
                }}
              />
            </div>
          </div>
        )}

        {/* Second frame for two separate lenses (near vision) */}
        {presbyopiaSolution === "two_separate" && (
          <div className="border-t pt-4 mt-4">
            <Label className="text-base font-semibold mb-2 block">
              Marco para Cerca
            </Label>

            {/* Near frame own frame toggle */}
            <div className="flex items-center gap-2 mb-4">
              <input
                checked={customerOwnNearFrame}
                className="h-4 w-4 rounded border-gray-300"
                id="customer_own_near_frame"
                type="checkbox"
                onChange={(e) => {
                  onCustomerOwnNearFrameChange(e.target.checked);
                  if (e.target.checked) {
                    onNearFrameClear();
                    onNearFrameFormDataChange("near_frame_product_id", "");
                    onNearFrameFormDataChange("near_frame_name", "");
                    onNearFrameFormDataChange("near_frame_brand", "");
                    onNearFrameFormDataChange("near_frame_model", "");
                    onNearFrameFormDataChange("near_frame_color", "");
                    onNearFrameFormDataChange("near_frame_size", "");
                    onNearFrameFormDataChange("near_frame_sku", "");
                    onNearFrameFormDataChange("near_frame_price", 0);
                    onNearFrameFormDataChange("near_frame_cost", 0);
                  }
                }}
              />
              <Label
                className="cursor-pointer"
                htmlFor="customer_own_near_frame"
              >
                Cliente trae marco (recambio de cristales)
              </Label>
            </div>

            {customerOwnNearFrame ? (
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <Label>Nombre del Marco (Cerca) *</Label>
                  <Input
                    required
                    placeholder="Marco del cliente"
                    value={formData.near_frame_name}
                    onChange={(e) =>
                      onNearFrameFormDataChange(
                        "near_frame_name",
                        e.target.value,
                      )
                    }
                  />
                </div>
                <div>
                  <Label>Número de Serie</Label>
                  <Input
                    placeholder="Número de serie del marco"
                    value={formData.near_frame_sku}
                    onChange={(e) =>
                      onNearFrameFormDataChange(
                        "near_frame_sku",
                        e.target.value,
                      )
                    }
                  />
                </div>
              </div>
            ) : selectedNearFrame ? (
              <div
                className="flex items-center justify-between p-4 border rounded-lg bg-admin-bg-secondary"
                style={{ backgroundColor: "var(--admin-border-primary)" }}
              >
                <div>
                  <div className="font-medium">
                    {(selectedNearFrame as unknown).name}
                  </div>
                  <div className="text-sm text-admin-text-tertiary">
                    {(selectedNearFrame as unknown).frame_brand}{" "}
                    {(selectedNearFrame as unknown).frame_model} · Stock:{" "}
                    {(selectedNearFrame as unknown).available_quantity ??
                      (selectedNearFrame as unknown).inventory_quantity ??
                      0}
                  </div>
                  <div className="text-sm font-semibold text-admin-success">
                    {formatPrice((selectedNearFrame as unknown).price)}
                  </div>
                </div>
                <Button
                  size="sm"
                  type="button"
                  variant="outline"
                  onClick={onNearFrameClear}
                >
                  Cambiar
                </Button>
              </div>
            ) : (
              <div className="relative">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-admin-text-tertiary" />
                <Input
                  className="pl-10"
                  placeholder="Buscar marco para cerca por nombre, marca o SKU..."
                  value={nearFrameSearch}
                  onChange={(e) => onNearFrameSearchChange(e.target.value)}
                />
                {nearFrameSearch.length >= 2 && (
                  <div className="absolute z-10 w-full mt-1 bg-white border rounded-lg shadow-lg max-h-60 overflow-y-auto">
                    {searchingNearFrames ? (
                      <div className="p-4 text-center">
                        <Loader2 className="h-4 w-4 animate-spin mx-auto" />
                      </div>
                    ) : (nearFrameResults || []).length > 0 ? (
                      nearFrameResults.map((frame: unknown) => (
                        <div
                          className="p-3 hover:bg-gray-100 cursor-pointer border-b"
