interface CustomerSelectionProps {
  selectedCustomer: Customer | null;
  onCustomerSelect: (customer: Customer) => void;
  onCustomerClear: () => void;
  disabled?: boolean;
  initialCustomerId?: string;
}

export function CustomerSelection({
  selectedCustomer,
  onCustomerSelect,
  onCustomerClear,
  disabled = false,
  initialCustomerId,
}: CustomerSelectionProps) {
  const {
    search,
    setSearch,
    results,
    loading,
    selected,
    selectCustomer,
    clearCustomer,
  } = useCustomerSearch(initialCustomerId);

  // When customer is loaded from initialCustomerId, notify parent
  useEffect(() => {
    if (selected && !selectedCustomer) {
      onCustomerSelect(selected);
    }
  }, [selected, selectedCustomer, onCustomerSelect]);

  const handleSelect = (customer: Customer) => {
    selectCustomer(customer);
    onCustomerSelect(customer);
  };

  const handleClear = () => {
    clearCustomer();
    onCustomerClear();
  };

  if (selectedCustomer && !disabled) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center">
            <User className="h-5 w-5 mr-2" />
            Cliente
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div
            className="flex items-center justify-between p-4 border rounded-lg bg-admin-bg-secondary"
            style={{ backgroundColor: "var(--admin-border-primary)" }}
          >
            <div>
              <div className="font-medium">
                {selectedCustomer.first_name} {selectedCustomer.last_name}
              </div>
              <div className="text-sm text-admin-text-tertiary">
                {selectedCustomer.email}
              </div>
            </div>
            <Button
              size="sm"
              type="button"
              variant="outline"
              onClick={handleClear}
            >
              <X className="h-4 w-4 mr-2" />
              Cambiar
            </Button>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center">
          <User className="h-5 w-5 mr-2" />
          Cliente
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-admin-text-tertiary" />
          <Input
            className="pl-10"
            disabled={disabled}
            placeholder="Buscar cliente por nombre o email..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
          {search.length >= 2 && (
            <div className="absolute z-10 w-full mt-1 bg-white border rounded-lg shadow-lg max-h-60 overflow-y-auto">
              {loading ? (
                <div className="p-4 text-center">
                  <Loader2 className="h-4 w-4 animate-spin mx-auto" />
                </div>
              ) : results.length > 0 ? (
                results.map((customer) => (
                  <div
                    className="p-3 hover:bg-gray-100 cursor-pointer border-b"
                    key={customer.id}
                    onClick={() => handleSelect(customer)}
                  >
                    <div className="font-medium">
                      {customer.first_name} {customer.last_name}
                    </div>
                    <div className="text-sm text-admin-text-tertiary space-y-1">
                      {customer.email && <div>{customer.email}</div>}
                      {customer.rut && <div>RUT: {customer.rut}</div>}
                    </div>
                  </div>
                ))
              ) : (
                <div className="p-4 text-center text-admin-text-tertiary">
                  No se encontraron clientes
                </div>
              )}
            </div>
          )}
        </div>
      </CardContent>
    </Card>
  );
}

import { Loader2, Package, Search, X } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

import { useFrameSearch } from "../hooks";
import { Frame } from "../types/quote.types";

interface FrameSelectionProps {
  presbyopiaSolution: string;
  customerOwnFrame: boolean;
  selectedFrame: Frame | null;
  onCustomerOwnFrameChange: (checked: boolean) => void;
  onFrameSelect: (frame: Frame) => void;
  onFrameClear: () => void;
  onManualFrameDataChange: (field: string, value: unknown) => void;
  frameData: {
    frame_name: string;
    frame_sku: string;
    frame_price: number;
    frame_cost: number;
  };
  disabled?: boolean;
}

export function FrameSelection({
  presbyopiaSolution,
  customerOwnFrame,
  selectedFrame,
  onCustomerOwnFrameChange,
  onFrameSelect,
  onFrameClear,
  onManualFrameDataChange,
  frameData,
  disabled = false,
}: FrameSelectionProps) {
  const {
    search: frameSearch,
    setSearch: setFrameSearch,
    results: frameResults,
    selected: searchedFrame,
    loading: searchingFrames,
    selectFrame,
    clearFrame,
  } = useFrameSearch();

  const handleFrameSelect = (frame: Frame) => {
    selectFrame(frame);
    onFrameSelect(frame);
  };

  const handleFrameClear = () => {
    clearFrame();
    onFrameClear();
  };

  const handleSearchChange = (value: string) => {
    setFrameSearch(value);
  };

  const formatPrice = (price: number) => {
    return new Intl.NumberFormat("es-CL", {
      style: "currency",
      currency: "CLP",
      minimumFractionDigits: 0,
    }).format(price);
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center">
          <Package className="h-5 w-5 mr-2" />
          {presbyopiaSolution === "two_separate" ? "Marco para Lejos" : "Marco"}
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Customer Own Frame Checkbox */}
        <div className="flex items-center gap-2">
          <input
            checked={customerOwnFrame}
            className="h-4 w-4 rounded border-gray-300"
            disabled={disabled}
            id="customer_own_frame"
            type="checkbox"
            onChange={(e) => onCustomerOwnFrameChange(e.target.checked)}
          />
          <Label className="cursor-pointer" htmlFor="customer_own_frame">
            Cliente trae marco (recambio de cristales)
          </Label>
        </div>

        {/* Customer Own Frame Form */}
        {customerOwnFrame ? (
          <div className="grid grid-cols-2 gap-4 mt-4">
            <div>
              <Label>Nombre del Marco *</Label>
              <Input
                required
                disabled={disabled}
                placeholder="Marco del cliente"
                value={frameData.frame_name}
                onChange={(e) =>
                  onManualFrameDataChange("frame_name", e.target.value)
                }
              />
            </div>
            <div>
              <Label>Número de Serie</Label>
              <Input
                disabled={disabled}
                placeholder="Número de serie del marco"
                value={frameData.frame_sku}
                onChange={(e) =>
                  onManualFrameDataChange("frame_sku", e.target.value)
                }
              />
            </div>
          </div>
        ) : selectedFrame ? (
          /* Selected Frame Display */
          <div
            className="flex items-center justify-between p-4 border rounded-lg bg-admin-bg-secondary"
            style={{ backgroundColor: "var(--admin-border-primary)" }}
          >
            <div>
              <div className="font-medium">{selectedFrame.name}</div>
              <div className="text-sm text-tierra-media">
                {selectedFrame.brand} {selectedFrame.model} · Stock:{" "}
                {selectedFrame.quantity || 0}
              </div>
              <div className="text-sm font-semibold text-verde-suave">
                {formatPrice(selectedFrame.price)}
              </div>
            </div>
            <Button
              disabled={disabled}
              size="sm"
              type="button"
              variant="outline"
              onClick={handleFrameClear}
            >
              <X className="h-4 w-4 mr-2" />
              Cambiar
            </Button>
          </div>
        ) : (
          /* Frame Search */
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-tierra-media" />
            <Input
              className="pl-10"
              disabled={disabled}
              placeholder="Buscar marco por nombre, marca o SKU..."
              value={frameSearch}
              onChange={(e) => handleSearchChange(e.target.value)}
            />
            {frameSearch.length >= 2 && (
              <div className="absolute z-10 w-full mt-1 bg-white border rounded-lg shadow-lg max-h-60 overflow-y-auto">
                {searchingFrames ? (
                  <div className="p-4 text-center">
                    <Loader2 className="h-4 w-4 animate-spin mx-auto" />
                  </div>
                ) : frameResults.length > 0 ? (
                  frameResults.map((frame) => (
                    <div
                      className="p-3 hover:bg-gray-100 cursor-pointer border-b"
                      key={frame.id}
                      onClick={() => handleFrameSelect(frame)}
                    >
                      <div className="font-medium">{frame.name}</div>
                      <div className="text-sm text-tierra-media">
                        {frame.brand} {frame.model} - Stock:{" "}
                        {frame.quantity || 0}
                      </div>
                      <div className="text-sm font-semibold text-verde-suave">
                        {formatPrice(frame.price)}
                      </div>
                    </div>
                  ))
                ) : (
                  <div className="p-4 text-center text-tierra-media">
                    No se encontraron marcos
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {/* Manual Frame Entry */}
        {!selectedFrame && !customerOwnFrame && (
          <div className="grid grid-cols-2 gap-4 mt-4">
            <div>
              <Label>Nombre del Marco</Label>
              <Input
                disabled={disabled}
                placeholder="Ej: Ray-Ban RB2140"
                value={frameData.frame_name}
                onChange={(e) =>
                  onManualFrameDataChange("frame_name", e.target.value)
                }
              />
            </div>
            <div>
              <Label>Precio del Marco</Label>
              <Input
                disabled={disabled}
                placeholder="0"
                type="number"
                value={frameData.frame_price || ""}
                onChange={(e) => {
                  const price = parseFloat(e.target.value) || 0;
                  onManualFrameDataChange("frame_price", price);
                  onManualFrameDataChange("frame_cost", price);
                }}
              />
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import { Eye, RefreshCw } from "lucide-react";
import { useEffect, useState } from "react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useBranch } from "@/hooks/useBranch";
import { appLogger } from '@/lib/logger';

import {  ContactLensFamily,
  LensFamily,
  QuoteFormData,
} from "../types/quote.types";

interface LensConfigurationProps {
  formData: QuoteFormData;
  presbyopiaSolution: string;
  lensType: "optical" | "contact";
  manualLensPrice: boolean;
  onUpdateField: (field: keyof QuoteFormData, value: unknown) => void;
  onManualLensPriceToggle: () => void;
  onCalculateLensPrice: () => void;
  disabled?: boolean;
}

export function LensConfiguration({
  formData,
  presbyopiaSolution,
  lensType,
  manualLensPrice,
  onUpdateField,
  onManualLensPriceToggle,
  onCalculateLensPrice,
  disabled = false,
}: LensConfigurationProps) {
  const { currentBranchId } = useBranch();

  const [lensFamilies, setLensFamilies] = useState<LensFamily[]>([]);
  const [contactLensFamilies, setContactLensFamilies] = useState<
    ContactLensFamily[]
  >([]);
  const [loadingFamilies, setLoadingFamilies] = useState(false);
  const [loadingContactLensFamilies, setLoadingContactLensFamilies] =
    useState(false);

  // Fetch lens families
  useEffect(() => {
    const fetchLensFamilies = async () => {
      try {
        setLoadingFamilies(true);
        const res = await fetch("/api/admin/lens-families");
        if (res.ok) {
          const data = await res.json();
          // Standardized API returns data in 'data' field
          if (data.success && Array.isArray(data.data)) {
            setLensFamilies(data.data);
          } else {
            setLensFamilies(data.families || []);
          }
        }
      } catch (error) {
        appLogger.error("Error fetching lens families:", error);
      } finally {
        setLoadingFamilies(false);
      }
    };

    fetchLensFamilies();
  }, []);

  // Fetch contact lens families
  useEffect(() => {
    const fetchContactLensFamilies = async () => {
      try {
        setLoadingContactLensFamilies(true);
        const res = await fetch("/api/admin/contact-lens-families");
        if (res.ok) {
          const data = await res.json();
          // Standardized API returns data in 'data' field
          if (data.success && Array.isArray(data.data)) {
            setContactLensFamilies(data.data);
          } else {
            setContactLensFamilies(data.families || []);
          }
        }
      } catch (error) {
        appLogger.error("Error fetching contact lens families:", error);
      } finally {
        setLoadingContactLensFamilies(false);
      }
    };

    if (lensType === "contact") {
      fetchContactLensFamilies();
    }
  }, [lensType]);

  // Lens treatments options
  const lensTreatments = [
    { value: "anti_reflective", label: "Antireflejo" },
    { value: "blue_light_filter", label: "Filtro de luz azul" },
    { value: "uv_protection", label: "Protección UV" },
    { value: "scratch_resistant", label: "Resistente a rayones" },
    { value: "anti_fog", label: "Antivaho" },
    { value: "photochromic", label: "Fotocromático" },
    { value: "polarized", label: "Polarizado" },
    { value: "tint", label: "Tinte" },
    { value: "prism_extra", label: "Prisma Extra" },
  ];

  // Handle treatment selection
  const handleTreatmentToggle = (treatmentValue: string) => {
    const currentTreatments = [...formData.lens_treatments];
    const index = currentTreatments.indexOf(treatmentValue);

    if (index >= 0) {
      currentTreatments.splice(index, 1);
    } else {
      currentTreatments.push(treatmentValue);
    }

    onUpdateField("lens_treatments", currentTreatments);
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center">
          <Eye className="h-5 w-5 mr-2" />
          {lensType === "contact" ? "Lentes de Contacto" : "Lentes"}
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-6">
        {/* Lens Type Toggle */}
        <div className="flex gap-2">
          <Button
            disabled={disabled}
            variant={lensType === "optical" ? "default" : "outline"}
            onClick={() => onUpdateField("lens_type", "optical")}
          >
            Ópticos
          </Button>
          <Button
            disabled={disabled}
            variant={lensType === "contact" ? "default" : "outline"}
            onClick={() => onUpdateField("lens_type", "contact")}
          >
            Contacto
          </Button>
        </div>

        {/* Contact Lens Family Selection */}
        {lensType === "contact" && (
          <div>
            <Label>Familia de Lentes de Contacto</Label>
            <Select
              disabled={loadingContactLensFamilies || disabled}
              value={formData.contact_lens_family_id || "none"}
              onValueChange={(value) =>
                onUpdateField(
                  "contact_lens_family_id",
                  value === "none" ? "" : value,
                )
              }
            >
              <SelectTrigger>
                <SelectValue
                  placeholder={
                    loadingContactLensFamilies
                      ? "Cargando..."
                      : "Selecciona familia"
                  }
                />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="none">
                  Sin familia (precio manual)
                </SelectItem>
                {contactLensFamilies.map((family) => (
                  <SelectItem key={family.id} value={family.id}>
                    {family.name}
                    {family.brand ? ` (${family.brand})` : ""}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        )}

        {/* Optical Lens Family Selection */}
        {lensType === "optical" && (
          <div>
            <Label>Familia de Lentes</Label>
            <Select
              disabled={loadingFamilies || disabled}
              value={formData.lens_family_id || "none"}
              onValueChange={(value) => {
                onUpdateField("lens_family_id", value === "none" ? "" : value);
                onUpdateField("lens_cost", 0); // Reset cost to trigger recalculation
              }}
            >
              <SelectTrigger>
                <SelectValue
                  placeholder={
                    loadingFamilies ? "Cargando..." : "Selecciona familia"
                  }
                />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="none">
                  Sin familia (precio manual)
                </SelectItem>
                {lensFamilies.map((family) => (
                  <SelectItem key={family.id} value={family.id}>
                    {family.name}
                    {family.brand ? ` (${family.brand})` : ""}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>

            {/* Family Description */}
            {formData.lens_family_id &&
              (() => {
                const selectedFamily = lensFamilies.find(
                  (f) => f.id === formData.lens_family_id,
                );
                return selectedFamily?.description ? (
                  <div className="mt-2 p-2 bg-blue-50 border border-blue-200 rounded text-xs text-blue-800">
                    <p className="font-semibold mb-1">{selectedFamily.name}</p>
                    <p>{selectedFamily.description}</p>
                  </div>
                ) : null;
              })()}

            {/* Lens Properties */}
            <div className="grid grid-cols-2 gap-4 mt-4">
              <div>
                <Label>Tipo de Lente</Label>
                <Input
                  className={formData.lens_family_id ? "bg-gray-50" : ""}
                  disabled={disabled}
                  placeholder="Ej: Progresivo"
                  readOnly={!!formData.lens_family_id}
                  value={formData.lens_type}
                  onChange={(e) => onUpdateField("lens_type", e.target.value)}
                />
              </div>
              <div>
                <Label>Material</Label>
                <Input
                  className={formData.lens_family_id ? "bg-gray-50" : ""}
                  disabled={disabled}
                  placeholder="Ej: Policarbonato"
                  readOnly={!!formData.lens_family_id}
                  value={formData.lens_material}
                  onChange={(e) =>
                    onUpdateField("lens_material", e.target.value)
                  }
                />
              </div>
            </div>

            {/* Lens Index */}
            <div className="mt-4">
              <Label>Índice de Refracción</Label>
              <Input
                className={formData.lens_family_id ? "bg-gray-50" : ""}
                disabled={disabled}
                placeholder={
                  formData.lens_family_id
                    ? formData.lens_index
                      ? formData.lens_index.toString()
                      : "—"
                    : "Ej: 1.67"
                }
                readOnly={!!formData.lens_family_id}
                step="0.01"
                type="number"
                value={formData.lens_index || ""}
                onChange={(e) =>
                  onUpdateField(
                    "lens_index",
                    parseFloat(e.target.value) || null,
                  )
                }
              />
              {formData.lens_family_id && formData.lens_material && (
                <p className="text-xs text-gray-500 mt-1">
                  Índice automático según material: {formData.lens_material}
                </p>
              )}
            </div>

            {/* Lens Treatments */}
            {presbyopiaSolution !== "two_separate" && (
              <div className="mt-6">
                <Label>Tratamientos</Label>
                <div className="grid grid-cols-2 gap-2 mt-2">
                  {lensTreatments
                    .filter((treatment) => {
                      // Some treatments are only available without family
                      if (!formData.lens_family_id) return true;
                      return (
                        treatment.value === "tint" ||
                        treatment.value === "prism_extra"
                      );
                    })
                    .map((treatment) => {
                      const isSelected = formData.lens_treatments.includes(
                        treatment.value,
                      );
                      const isDisabled =
                        !!formData.lens_family_id &&
                        [
                          "anti_reflective",
                          "blue_light_filter",
                          "uv_protection",
                          "scratch_resistant",
                          "anti_fog",
                          "photochromic",
                          "polarized",
                        ].includes(treatment.value);

                      return (
                        <div
                          className="flex items-center"
                          key={treatment.value}
                        >
                          <input
                            checked={isSelected}
                            className="h-4 w-4 rounded border-gray-300"
                            disabled={isDisabled || disabled}
                            id={`treatment-${treatment.value}`}
                            type="checkbox"
                            onChange={() =>
                              handleTreatmentToggle(treatment.value)
                            }
                          />
                          <Label
                            className="ml-2 text-sm cursor-pointer"
                            htmlFor={`treatment-${treatment.value}`}
                          >
                            {treatment.label}
                          </Label>
                        </div>
                      );
                    })}
                </div>
                {!formData.lens_family_id && (
                  <p className="text-xs text-gray-500 mt-1">
                    Sin familia: puedes agregar cualquier tratamiento
                    manualmente.
                  </p>
                )}
              </div>
            )}

            {/* Manual Price Toggle */}
            <div className="flex items-center gap-2 mt-4">
              <Button
                disabled={presbyopiaSolution === "two_separate" || disabled}
                size="sm"
                type="button"
                variant="outline"
                onClick={onManualLensPriceToggle}
              >
                {manualLensPrice ? "Auto" : "Manual"}
              </Button>
              {!manualLensPrice && (
                <Button
                  disabled={disabled}
                  size="sm"
                  type="button"
                  variant="outline"
                  onClick={onCalculateLensPrice}
                >
                  <RefreshCw className="h-4 w-4 mr-2" />
                  Calcular
                </Button>
              )}
            </div>

            {/* Lens Cost Input */}
            <div className="mt-4">
              <Label>Costo del Lente</Label>
              <Input
                className={
                  formData.lens_family_id && !manualLensPrice
                    ? "bg-gray-50"
                    : ""
                }
                disabled={disabled}
                placeholder="0"
                readOnly={
                  presbyopiaSolution === "two_separate" ||
                  (!!formData.lens_family_id && !manualLensPrice)
                }
                type="number"
                value={formData.lens_cost || ""}
                onChange={(e) =>
                  onUpdateField("lens_cost", parseFloat(e.target.value) || 0)
                }
              />
              {presbyopiaSolution === "two_separate" && (
                <p className="text-xs text-gray-500 mt-1">
                  Suma automática: Lejos ($
                  {(formData.far_lens_cost || 0).toLocaleString()}) + Cerca ($
                  {(formData.near_lens_cost || 0).toLocaleString()})
                </p>
              )}
              {formData.lens_family_id && (
                <p className="text-xs text-gray-500 mt-1">
                  {manualLensPrice
                    ? "Precio manual ingresado"
                    : "Precio calculado automáticamente"}
                </p>
              )}
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import { Eye, Loader2, Plus } from "lucide-react";

import { PrescriptionFullDisplay } from "@/components/admin/PrescriptionFullDisplay";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { getMaxAddition, hasAddition } from "@/lib/presbyopia-helpers";
import { translatePrescriptionType } from "@/lib/prescription-helpers";
import { formatDate } from "@/lib/utils";

import { usePrescriptionSearch } from "../hooks";
import { Prescription } from "../types/quote.types";

interface PrescriptionSelectionProps {
  customerId: string | null;
  customerName?: string;
  selectedPrescription: Prescription | null;
  onPrescriptionSelect: (prescription: Prescription) => void;
  onPrescriptionClear: () => void;
  presbyopiaSolution: string;
  onPresbyopiaSolutionChange: (solution: string) => void;
  onCreateNewPrescription: () => void;
  disabled?: boolean;
}

export function PrescriptionSelection({
  customerId,
  customerName,
  selectedPrescription,
  onPrescriptionSelect,
  onPrescriptionClear,
  presbyopiaSolution,
  onPresbyopiaSolutionChange,
  onCreateNewPrescription,
  disabled = false,
}: PrescriptionSelectionProps) {
  const {
    prescriptions,
    selected,
    loading,
    selectPrescription,
    clearPrescription,
    refetch,
  } = usePrescriptionSearch(customerId);

  const handleSelect = (prescription: Prescription) => {
    selectPrescription(prescription);
    onPrescriptionSelect(prescription);
  };

  const handleClear = () => {
    clearPrescription();
    onPrescriptionClear();
  };

  // Show prescription summary when selected
  if (selectedPrescription) {
    return (
      <div className="space-y-4">
        <PrescriptionFullDisplay
          badges={
            <Button
              disabled={disabled}
              size="sm"
              type="button"
              variant="outline"
              onClick={handleClear}
            >
              Cambiar receta
            </Button>
          }
          prescription={selectedPrescription}
          subtitle={
            selectedPrescription.prescription_date && (
              <>
                Fecha:{" "}
                {new Date(
                  selectedPrescription.prescription_date + "T12:00:00",
                ).toLocaleDateString("es-CL")}
                {selectedPrescription.prescription_type && (
                  <>
                    {" "}
                    • Tipo:{" "}
                    {translatePrescriptionType(
                      selectedPrescription.prescription_type,
                    )}
                  </>
                )}
              </>
            )
          }
          title="Receta seleccionada"
        />

        {/* Presbyopia Solution Selector */}
        {hasAddition(selectedPrescription) && (
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center text-sm">
                <Eye className="h-4 w-4 mr-2" />
                Solución para Presbicia
              </CardTitle>
            </CardHeader>
            <CardContent>
              <Alert className="mb-4">
                <AlertDescription>
                  Esta receta tiene adición (+
                  {getMaxAddition(selectedPrescription)} D). Selecciona cómo
                  deseas manejar la presbicia.
                </AlertDescription>
              </Alert>
              <RadioGroup
                className="space-y-3"
                value={presbyopiaSolution}
                onValueChange={onPresbyopiaSolutionChange}
              >
                <div className="flex items-center space-x-2">
                  <RadioGroupItem id="progressive" value="progressive" />
                  <Label className="cursor-pointer" htmlFor="progressive">
                    Progresivo (Recomendado)
                  </Label>
                </div>
                <div className="flex items-center space-x-2">
                  <RadioGroupItem id="bifocal" value="bifocal" />
                  <Label className="cursor-pointer" htmlFor="bifocal">
                    Bifocal
                  </Label>
                </div>
                <div className="flex items-center space-x-2">
                  <RadioGroupItem id="trifocal" value="trifocal" />
                  <Label className="cursor-pointer" htmlFor="trifocal">
                    Trifocal
                  </Label>
                </div>
                <div className="flex items-center space-x-2">
                  <RadioGroupItem id="two_separate" value="two_separate" />
                  <Label className="cursor-pointer" htmlFor="two_separate">
                    Dos lentes separados (Lejos + Cerca)
                  </Label>
                </div>
              </RadioGroup>
            </CardContent>
          </Card>
        )}
      </div>
    );
  }

  // Show prescription selection UI
  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center">
          <Eye className="h-5 w-5 mr-2" />
          Receta
        </CardTitle>
      </CardHeader>
      <CardContent>
        {loading ? (
          <div className="text-center py-4">
            <Loader2 className="h-4 w-4 animate-spin mx-auto" />
          </div>
        ) : prescriptions.length === 0 ? (
          <div className="text-center py-4 space-y-3">
            <p className="text-admin-text-tertiary">
              Este cliente no tiene recetas registradas
            </p>
            <Button
              disabled={disabled}
              type="button"
              variant="outline"
              onClick={onCreateNewPrescription}
            >
              <Plus className="h-4 w-4 mr-2" />
              Crear Nueva Receta
            </Button>
          </div>
        ) : (
          <Select
            value={selected?.id || ""}
            onValueChange={(value) => {
              const prescription = prescriptions.find((p) => p.id === value);
              if (prescription) {
                handleSelect(prescription);
              }
            }}
          >
            <SelectTrigger disabled={disabled}>
              <SelectValue placeholder="Selecciona una receta" />
            </SelectTrigger>
            <SelectContent>
              {prescriptions.map((prescription) => (
                <SelectItem key={prescription.id} value={prescription.id}>
                  {customerName ? `${customerName} · ` : ""}
                  {prescription.prescription_date
                    ? formatDate(prescription.prescription_date)
                    : "Sin fecha"}
                  {" · "}
                  {translatePrescriptionType(prescription.prescription_type)}
                  {prescription.is_current && " (Actual)"}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        )}
      </CardContent>
    </Card>
  );
}

import { Calculator, ChevronDown, ChevronRight } from "lucide-react";
import { useEffect, useState } from "react";

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

import { QuoteFormData } from "../types/quote.types";

interface PricingSummaryProps {
  formData: QuoteFormData;
  presbyopiaSolution: string;
  discountType: "percentage" | "amount";
  taxPercentage: number;
  manualLensPrice: boolean;
  onUpdateField: (field: keyof QuoteFormData, value: unknown) => void;
  onDiscountTypeChange: (type: "percentage" | "amount") => void;
  onCalculateTotal: () => void;
  disabled?: boolean;
}

export function PricingSummary({
  formData,
  presbyopiaSolution,
  discountType,
  taxPercentage,
  manualLensPrice,
  onUpdateField,
  onDiscountTypeChange,
  onCalculateTotal,
  disabled = false,
}: PricingSummaryProps) {
  const [showDetails, setShowDetails] = useState(false);

  // Format price helper
  const formatPrice = (price: number) => {
    return new Intl.NumberFormat("es-CL", {
      style: "currency",
      currency: "CLP",
      minimumFractionDigits: 0,
    }).format(price);
  };

  // Calculate subtotal effect
  useEffect(() => {
    const calculateSubtotal = () => {
      let subtotal = 0;

      // Frame costs
      if (presbyopiaSolution === "two_separate") {
        subtotal +=
          (formData.frame_cost || 0) + (formData.near_frame_cost || 0);
      } else {
        subtotal += formData.frame_cost || 0;
      }

      // Lens costs
      if (presbyopiaSolution === "two_separate") {
        subtotal +=
          (formData.far_lens_cost || 0) + (formData.near_lens_cost || 0);
      } else {
        subtotal += formData.lens_cost || 0;
      }

      // Contact lens cost
      subtotal += formData.contact_lens_cost || 0;

      // Other costs
      subtotal += (formData.treatments_cost || 0) + (formData.labor_cost || 0);

      onUpdateField("subtotal", subtotal);
    };

    calculateSubtotal();
  }, [
    formData.frame_cost,
    formData.near_frame_cost,
    formData.lens_cost,
    formData.far_lens_cost,
    formData.near_lens_cost,
    formData.contact_lens_cost,
    formData.treatments_cost,
    formData.labor_cost,
    presbyopiaSolution,
    onUpdateField,
  ]);

  // Calculate tax amount effect
  useEffect(() => {
    const taxAmount = (formData.subtotal || 0) * (taxPercentage / 100);
    onUpdateField("tax_amount", taxAmount);
  }, [formData.subtotal, taxPercentage, onUpdateField]);

  // Calculate total effect
  useEffect(() => {
    const total =
      (formData.subtotal || 0) +
      (formData.tax_amount || 0) -
      (formData.discount_amount || 0);
    onUpdateField("total_amount", total);
  }, [
    formData.subtotal,
    formData.tax_amount,
    formData.discount_amount,
    onUpdateField,
  ]);

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center">
          <Calculator className="h-5 w-5 mr-2" />
          Precios y Costos
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Summary View */}
        <div className="border-t pt-4">
          <div className="flex justify-between mb-2">
            <span>Subtotal:</span>
            <span className="font-medium">
              {formatPrice(formData.subtotal || 0)}
            </span>
          </div>

          {formData.discount_amount > 0 && (
            <div className="flex justify-between mb-2">
              <span>
                Descuento{" "}
                {discountType === "percentage"
                  ? `(${formData.discount_percentage.toFixed(2)}%)`
                  : "(Valor fijo)"}
                :
              </span>
              <span className="font-medium text-red-500">
                -{formatPrice(formData.discount_amount)}
              </span>
            </div>
          )}

          <div className="flex justify-between mb-2">
            <span>IVA ({taxPercentage}%):</span>
            <span className="font-medium">
              {formatPrice(formData.tax_amount || 0)}
            </span>
          </div>

          <div className="flex justify-between text-lg font-bold pt-2 border-t">
            <span>Total:</span>
            <span className="text-verde-suave">
              {formatPrice(formData.total_amount || 0)}
            </span>
          </div>
        </div>

        {/* Discount Controls */}
        <div className="grid grid-cols-2 gap-4">
          <div>
            <Label>Tipo de Descuento</Label>
            <Select
              disabled={disabled}
              value={discountType}
              onValueChange={(value: "percentage" | "amount") => {
                onDiscountTypeChange(value);
                // Clear the other discount field when switching types
                if (value === "percentage") {
                  onUpdateField("discount_amount", 0);
                } else {
                  onUpdateField("discount_percentage", 0);
                }
                // Recalculate total after clearing
                setTimeout(onCalculateTotal, 0);
              }}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="percentage">Por Porcentaje (%)</SelectItem>
                <SelectItem value="amount">Por Valor ($)</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div>
            <Label>
              {discountType === "percentage"
                ? "Descuento (%)"
                : "Descuento ($)"}
            </Label>
            <Input
              disabled={disabled}
              placeholder={discountType === "percentage" ? "0.00" : "0"}
              step={discountType === "percentage" ? "0.01" : "1"}
              type="number"
              value={
                discountType === "percentage"
                  ? formData.discount_percentage || ""
                  : formData.discount_amount || ""
              }
              onChange={(e) => {
                const value = parseFloat(e.target.value) || 0;
                if (discountType === "percentage") {
                  onUpdateField("discount_percentage", value);
                } else {
                  onUpdateField("discount_amount", value);
                }
              }}
            />
          </div>
        </div>

        {/* Detailed Cost Breakdown */}
        <div>
          <button
            className="flex items-center gap-2 text-sm font-medium text-gray-700 hover:text-gray-900"
            disabled={disabled}
            type="button"
            onClick={() => setShowDetails(!showDetails)}
          >
            {showDetails ? (
              <ChevronDown className="h-4 w-4" />
            ) : (
              <ChevronRight className="h-4 w-4" />
            )}
            Detalles de Costos
          </button>

          {showDetails && (
            <div className="mt-3 space-y-3 pl-6 border-l-2 border-gray-200">
              {/* Frame Costs */}
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>Costo interno de Marco</Label>
                  <Input
                    className={
                      presbyopiaSolution === "two_separate" ? "bg-gray-50" : ""
                    }
                    disabled={disabled}
                    readOnly={presbyopiaSolution === "two_separate"}
                    type="number"
                    value={
                      presbyopiaSolution === "two_separate"
                        ? (formData.frame_cost || 0) +
                          (formData.near_frame_cost || 0)
                        : formData.frame_cost || ""
                    }
                    onChange={(e) => {
                      if (presbyopiaSolution === "two_separate") {
                        // For two_separate, don't allow manual editing - it's calculated from far + near frames
                        return;
                      }
                      const newValue = parseFloat(e.target.value) || 0;
                      onUpdateField("frame_cost", newValue);
                    }}
                  />
                  {presbyopiaSolution === "two_separate" && (
                    <p className="text-xs text-gray-500 mt-1">
                      Suma automática: Marco Lejos ($
                      {(formData.frame_cost || 0).toLocaleString()}) + Marco
                      Cerca (${(formData.near_frame_cost || 0).toLocaleString()}
                      )
                    </p>
                  )}
                </div>

                <div>
                  <Label>Costo interno de Lente</Label>
                  <Input
                    className={
                      presbyopiaSolution === "two_separate" ||
                      (formData.lens_family_id && !manualLensPrice)
                        ? "bg-gray-50"
                        : ""
                    }
                    disabled={disabled}
                    readOnly={
                      presbyopiaSolution === "two_separate" ||
                      (!!formData.lens_family_id && !manualLensPrice)
                    }
                    type="number"
                    value={
                      presbyopiaSolution === "two_separate"
                        ? (formData.far_lens_cost || 0) +
                          (formData.near_lens_cost || 0)
                        : formData.lens_cost || ""
                    }
                    onChange={(e) => {
                      if (presbyopiaSolution === "two_separate") {
                        // For two_separate, don't allow manual editing - it's calculated from far + near
                        return;
                      }
                      const newValue = parseFloat(e.target.value) || 0;
                      onUpdateField("lens_cost", newValue);
                    }}
                  />
                  {presbyopiaSolution === "two_separate" && (
                    <p className="text-xs text-gray-500 mt-1">
                      Suma automática: Lejos ($
                      {(formData.far_lens_cost || 0).toLocaleString()}) + Cerca
                      (${(formData.near_lens_cost || 0).toLocaleString()})
                    </p>
                  )}
                  {formData.lens_family_id && (
                    <p className="text-xs text-gray-500 mt-1">
                      {manualLensPrice
                        ? "Precio manual ingresado"
                        : "Precio calculado automáticamente"}
                    </p>
                  )}
                </div>
              </div>

              {/* Additional Costs */}
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>Costo de Tratamientos</Label>
                  <Input
                    disabled={disabled}
                    placeholder="0"
                    type="number"
                    value={formData.treatments_cost || ""}
                    onChange={(e) => {
                      const newValue = parseFloat(e.target.value) || 0;
                      onUpdateField("treatments_cost", newValue);
                    }}
                  />
                </div>

                <div>
                  <Label>Costo de Mano de Obra</Label>
                  <Input
                    disabled={disabled}
                    placeholder="Ej: 15000"
                    type="number"
                    value={formData.labor_cost || ""}
                    onChange={(e) => {
                      const newValue = parseFloat(e.target.value) || 0;
                      onUpdateField("labor_cost", newValue);
                    }}
                  />
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Quote Validity */}
        <div>
          <Label>Validez del Presupuesto (días)</Label>
          <Input
            disabled={disabled}
            placeholder="30"
            type="number"
            value={formData.expiration_days}
            onChange={(e) =>
              onUpdateField("expiration_days", parseInt(e.target.value) || 30)
            }
          />
        </div>
      </CardContent>
    </Card>
  );
}

/**
 * Custom hook extracted from CreateQuoteForm.tsx.
 * Manages all state, effects, and handlers for the quote creation form.
 *
 * Composed from 7 domain hooks to reduce cognitive load.
 */
"use client";

import { useEffect, useState } from "react";
import { toast } from "sonner";

import { useBranch } from "@/hooks/useBranch";
import { quoteSettingsService } from "@/lib/api/services";
import { appLogger } from '@/lib/logger';
import { type PresbyopiaSolution } from "@/lib/presbyopia-helpers";

import { DEFAULT_QUOTE_SETTINGS } from "./CreateQuoteForm.constants";
import type {
  CreateQuoteFormProps,
  QuoteFormData,
  QuoteSettings,
} from "./CreateQuoteForm.types";
import { useContactLensSelection } from "./useContactLensSelection";
import { useCustomerSelection } from "./useCustomerSelection";
import { useFormPricing } from "./useFormPricing";
import { useFrameSelection } from "./useFrameSelection";
import { useLensConfiguration } from "./useLensConfiguration";
import { usePrescriptionSelection } from "./usePrescriptionSelection";
import { useQuoteSubmit } from "./useQuoteSubmit";

export interface UseCreateQuoteFormReturn {
  // State
  loading: boolean;
  saving: boolean;
  discountType: "percentage" | "amount";
  quoteSettings: unknown;
  loadingSettings: boolean;
  customerSearch: string;
  customerResults: unknown[];
  selectedCustomer: unknown;
  searchingCustomers: boolean;
  prescriptions: unknown[];
  selectedPrescription: unknown;
  loadingPrescriptions: boolean;
  showCreatePrescription: boolean;
  frameSearch: string;
  frameResults: unknown[];
  selectedFrame: unknown;
  searchingFrames: boolean;
  nearFrameSearch: string;
  nearFrameResults: unknown[];
  selectedNearFrame: unknown;
  searchingNearFrames: boolean;
  taxPercentage: number;
  customerOwnFrame: boolean;
  customerOwnNearFrame: boolean;
  manualLensPrice: boolean;
  lensFamilies: unknown[];
  loadingFamilies: boolean;
  contactLensFamilies: unknown[];
  loadingContactLensFamilies: boolean;
  lensType: "optical" | "contact";
  calculatingContactLensPrice: boolean;
  presbyopiaSolution: PresbyopiaSolution;
  farLensFamilyId: string;
  nearLensFamilyId: string;
  farLensCost: number;
  nearLensCost: number;
  formData: QuoteFormData;

  // Brand context
  effectiveBranchId: string | undefined;

  // Computed
  availableTreatments: {
    value: string;
    label: string;
    cost: number;
    enabled: boolean;
  }[];
  calculatingPrice: boolean;

  // Setters
  setCustomerSearch: (v: string) => void;
  setSelectedCustomer: (v: unknown) => void;
  setSelectedPrescription: (v: unknown) => void;
  setShowCreatePrescription: (v: boolean) => void;
  setFrameSearch: (v: string) => void;
  setSelectedFrame: (v: unknown) => void;
  setNearFrameSearch: (v: string) => void;
  setSelectedNearFrame: (v: unknown) => void;
  setCustomerOwnFrame: (v: boolean) => void;
  setCustomerOwnNearFrame: (v: boolean) => void;
  setManualLensPrice: (v: boolean) => void;
  setLensType: (v: "optical" | "contact") => void;
  setPresbyopiaSolution: (v: PresbyopiaSolution) => void;
  setFarLensFamilyId: (v: string) => void;
  setNearLensFamilyId: (v: string) => void;
  setDiscountType: (v: "percentage" | "amount") => void;
  setFormData: React.Dispatch<React.SetStateAction<QuoteFormData>>;

  // Handlers
  handleTreatmentToggle: (treatment: {
    value: string;
    label: string;
    cost: number;
    enabled: boolean;
  }) => void;
  handleFrameSelect: (frame: unknown) => void;
  handleNearFrameSelect: (frame: unknown) => void;
  handleSubmit: (e: React.FormEvent) => Promise<void>;
  calculateTotal: () => void;
  fetchPrescriptions: (customerId: string) => Promise<void>;
}

export function useCreateQuoteForm(
  props: CreateQuoteFormProps,
): UseCreateQuoteFormReturn {
  const {
    onSuccess,
    initialCustomerId,
    initialPrescriptionId,
    initialFieldOperationId,
    initialBranchId,
  } = props;

  // Branch context: use operativo branch when in operativo context
  const { currentBranchId } = useBranch();
  const effectiveBranchId =
    initialFieldOperationId && initialBranchId
      ? initialBranchId
      : (currentBranchId ?? undefined);

  // Quote settings (stays — manages loading/error states during init)
  const [quoteSettings, setQuoteSettings] = useState<unknown>(null);
  const [loadingSettings, setLoadingSettings] = useState(true);

  // Bridge state — values produced by one sub-hook and consumed by another.
  // formPricing needs lensType/presbyopiaSolution from lensConfig and
  // customerOwnFrame/customerOwnNearFrame from frameSelection, but those
  // hooks need formData/setFormData from formPricing. We bridge the cycle
  // via local state + sync effects.
  const [lensType, setLensTypeState] = useState<"optical" | "contact">(
    "optical",
  );
  const [presbyopiaSolution, setPresbyopiaSolutionState] =
    useState<PresbyopiaSolution>("none");
  const [customerOwnFrame, setCustomerOwnFrameState] = useState(false);
  const [customerOwnNearFrame, setCustomerOwnNearFrameState] = useState(false);

  // ── Domain hooks ─────────────────────────────────────────────────

  // formPricing first — produces formData/setFormData consumed by others
  const formPricing = useFormPricing(
    quoteSettings,
    lensType,
    presbyopiaSolution,
    customerOwnFrame,
    customerOwnNearFrame,
  );

  const customerSelection = useCustomerSelection(
    effectiveBranchId,
    initialFieldOperationId,
    initialCustomerId,
  );

  const prescriptionSelection = usePrescriptionSelection(
    customerSelection.selectedCustomer,
    initialPrescriptionId,
  );

  const frameSelection = useFrameSelection(
    effectiveBranchId,
    initialFieldOperationId,
    formPricing.setFormData,
  );

  const contactLensSelection = useContactLensSelection(
    formPricing.setFormData,
  );

  const lensConfig = useLensConfiguration(
    prescriptionSelection.selectedPrescription,
    formPricing.formData,
    formPricing.setFormData,
  );

  // Sync lensConfig/frameSelection values back to bridge state
  useEffect(() => {
    setLensTypeState(lensConfig.lensType);
  }, [lensConfig.lensType]);
  useEffect(() => {
    setPresbyopiaSolutionState(lensConfig.presbyopiaSolution);
  }, [lensConfig.presbyopiaSolution]);
  useEffect(() => {
    setCustomerOwnFrameState(frameSelection.customerOwnFrame);
  }, [frameSelection.customerOwnFrame]);
  useEffect(() => {
    setCustomerOwnNearFrameState(frameSelection.customerOwnNearFrame);
  }, [frameSelection.customerOwnNearFrame]);

  // Quote submit (terminal — no other hook consumes its state)
  const quoteSubmit = useQuoteSubmit(
    customerSelection.selectedCustomer,
    prescriptionSelection.selectedPrescription,
    formPricing.formData,
    frameSelection.selectedFrame,
    frameSelection.selectedNearFrame,
    lensConfig.lensType,
    lensConfig.presbyopiaSolution,
    frameSelection.customerOwnFrame,
    frameSelection.customerOwnNearFrame,
    lensConfig.farLensFamilyId,
    lensConfig.nearLensFamilyId,
    lensConfig.farLensCost,
    lensConfig.nearLensCost,
    effectiveBranchId,
    initialFieldOperationId,
    onSuccess,
  );

  // ── Quote settings effects (stays in main hook) ──────────────────

  const fetchQuoteSettings = async () => {
    try {
      setLoadingSettings(true);
      const settings = await quoteSettingsService.get();
      const newSettings = settings ? ({ ...settings } as unknown) : null;
      setQuoteSettings(newSettings);
      if (newSettings) {
        formPricing.setFormData((prev) => ({
          ...prev,
          labor_cost:
            (newSettings as QuoteSettings).default_labor_cost ?? 15000,
          expiration_days:
            (newSettings as QuoteSettings).validity_days ??
            (newSettings as QuoteSettings).default_expiration_days ??
            30,
        }));
      }
    } catch {
      appLogger.error("Error fetching quote settings");
      setQuoteSettings(DEFAULT_QUOTE_SETTINGS);
    } finally {
      setLoadingSettings(false);
    }
  };

  // Fetch settings on mount and when branch changes
  useEffect(() => {
    fetchQuoteSettings();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentBranchId]);

  // Listen for settings updates from other tabs/windows
  useEffect(() => {
    const handleSettingsUpdate = () => {
      fetchQuoteSettings();
      toast.info("Configuración actualizada", {
        description: "Los valores por defecto se han actualizado",
        duration: 3000,
      });
    };

    window.addEventListener("quote-settings-updated", handleSettingsUpdate);
    const checkStorage = setInterval(() => {
      const lastUpdate = localStorage.getItem("quote-settings-updated");
      if (lastUpdate) {
        const updateTime = parseInt(lastUpdate, 10);
        const now = Date.now();
        if (now - updateTime < 2000) {
          handleSettingsUpdate();
          localStorage.removeItem("quote-settings-updated");
        }
      }
    }, 1000);

    return () => {
      window.removeEventListener(
        "quote-settings-updated",
        handleSettingsUpdate,
      );
      clearInterval(checkStorage);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentBranchId]);

  // Periodic settings refresh fallback
  useEffect(() => {
    if (!loadingSettings) {
      const interval = setInterval(() => {
        fetchQuoteSettings();
      }, 30000);
      return () => clearInterval(interval);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentBranchId, loadingSettings]);

  // Sync quote settings to formData
  useEffect(() => {
    if (quoteSettings) {
      const s = quoteSettings as QuoteSettings;
      const newLaborCost = s.default_labor_cost ?? 15000;
      const newExpirationDays = s.default_expiration_days ?? 30;
      formPricing.setFormData((prev) => {
        const updates: Partial<QuoteFormData> = {};
        if (prev.labor_cost !== newLaborCost) updates.labor_cost = newLaborCost;
        if (prev.expiration_days !== newExpirationDays)
          updates.expiration_days = newExpirationDays;
        return Object.keys(updates).length > 0
          ? { ...prev, ...updates }
          : prev;
      });
    }
  }, [
    (quoteSettings as QuoteSettings)?.default_labor_cost,
    (quoteSettings as QuoteSettings)?.default_expiration_days,
    // eslint-disable-next-line react-hooks/exhaustive-deps
    formPricing.setFormData,
  ]);

  // ── Delegate setters ─────────────────────────────────────────────

  // Setters for bridged values delegate directly to the sub-hook that owns them
  const setLensType = (v: "optical" | "contact") => {
    lensConfig.setLensType(v);
  };
  const setPresbyopiaSolution = (v: PresbyopiaSolution) => {
    lensConfig.setPresbyopiaSolution(v);
  };
  const setCustomerOwnFrame = (v: boolean) => {
    frameSelection.setCustomerOwnFrame(v);
  };
  const setCustomerOwnNearFrame = (v: boolean) => {
    frameSelection.setCustomerOwnNearFrame(v);
  };

  // ── Compose return value ─────────────────────────────────────────

  return {
    // From quote submit
    loading: quoteSubmit.loading,
    saving: quoteSubmit.saving,
    handleSubmit: quoteSubmit.handleSubmit,

    // From form pricing
    discountType: formPricing.discountType,
    setDiscountType: formPricing.setDiscountType,
    formData: formPricing.formData,
    setFormData: formPricing.setFormData,
    taxPercentage: formPricing.taxPercentage,
    availableTreatments: formPricing.availableTreatments,
    handleTreatmentToggle: formPricing.handleTreatmentToggle,
    calculateTotal: formPricing.calculateTotal,

    // From customer selection
    customerSearch: customerSelection.customerSearch,
    setCustomerSearch: customerSelection.setCustomerSearch,
    customerResults: customerSelection.customerResults,
    selectedCustomer: customerSelection.selectedCustomer,
    setSelectedCustomer: customerSelection.setSelectedCustomer,
    searchingCustomers: customerSelection.searchingCustomers,

    // From prescription selection
    prescriptions: prescriptionSelection.prescriptions,
    setSelectedPrescription: prescriptionSelection.setSelectedPrescription,
    selectedPrescription: prescriptionSelection.selectedPrescription,
    loadingPrescriptions: prescriptionSelection.loadingPrescriptions,
    showCreatePrescription: prescriptionSelection.showCreatePrescription,
    setShowCreatePrescription: prescriptionSelection.setShowCreatePrescription,
    fetchPrescriptions: prescriptionSelection.fetchPrescriptions,

    // From frame selection
    frameSearch: frameSelection.frameSearch,
    setFrameSearch: frameSelection.setFrameSearch,
    frameResults: frameSelection.frameResults,
    selectedFrame: frameSelection.selectedFrame,
    setSelectedFrame: frameSelection.setSelectedFrame,
    searchingFrames: frameSelection.searchingFrames,
    nearFrameSearch: frameSelection.nearFrameSearch,
    setNearFrameSearch: frameSelection.setNearFrameSearch,
    nearFrameResults: frameSelection.nearFrameResults,
    selectedNearFrame: frameSelection.selectedNearFrame,
    setSelectedNearFrame: frameSelection.setSelectedNearFrame,
    searchingNearFrames: frameSelection.searchingNearFrames,
    customerOwnFrame: frameSelection.customerOwnFrame,
    setCustomerOwnFrame,
    customerOwnNearFrame: frameSelection.customerOwnNearFrame,
    setCustomerOwnNearFrame,
    handleFrameSelect: frameSelection.handleFrameSelect,
    handleNearFrameSelect: frameSelection.handleNearFrameSelect,

    // From lens configuration
    manualLensPrice: lensConfig.manualLensPrice,
    setManualLensPrice: lensConfig.setManualLensPrice,
    lensFamilies: lensConfig.lensFamilies,
    loadingFamilies: lensConfig.loadingFamilies,
    contactLensFamilies: lensConfig.contactLensFamilies,
    loadingContactLensFamilies: lensConfig.loadingContactLensFamilies,
    lensType: lensConfig.lensType,
    setLensType,
    calculatingContactLensPrice: lensConfig.calculatingContactLensPrice,
    presbyopiaSolution: lensConfig.presbyopiaSolution,
    setPresbyopiaSolution,
    farLensFamilyId: lensConfig.farLensFamilyId,
    setFarLensFamilyId: lensConfig.setFarLensFamilyId,
    nearLensFamilyId: lensConfig.nearLensFamilyId,
    setNearLensFamilyId: lensConfig.setNearLensFamilyId,
    farLensCost: lensConfig.farLensCost,
    nearLensCost: lensConfig.nearLensCost,
    calculatingPrice: lensConfig.calculatingPrice,

    // From main hook (quote settings)
    quoteSettings,
    loadingSettings,
    effectiveBranchId,
  };
}

"use client";

import { useEffect, useState } from "react";

import { customerService } from "@/lib/api/services";
import { appLogger } from '@/lib/logger';

export function useCustomerSelection(
  effectiveBranchId: string | undefined,
  initialFieldOperationId: string | undefined,
  initialCustomerId?: string,
) {
  // Customer selection
  const [customerSearch, setCustomerSearch] = useState("");
  const [customerResults, setCustomerResults] = useState<unknown[]>([]);
  const [selectedCustomer, setSelectedCustomer] = useState<unknown>(null);
  const [searchingCustomers, setSearchingCustomers] = useState(false);

  // Load initial customer
  useEffect(() => {
    if (
      initialCustomerId &&
      (!selectedCustomer ||
        (selectedCustomer as unknown).id !== initialCustomerId)
    ) {
      fetchCustomer(initialCustomerId);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [initialCustomerId]);

  const fetchCustomer = async (customerId: string) => {
    try {
      const customer = await customerService.getCustomer(customerId);
      setSelectedCustomer(customer);
    } catch (error) {
      appLogger.error("Error fetching customer:", error);
    }
  };

  // Search customers
  useEffect(() => {
    const searchCustomers = async () => {
      if (customerSearch.length < 2) {
        setCustomerResults([]);
        return;
      }
      setSearchingCustomers(true);
      try {
        const customers = await customerService.searchCustomers(
          customerSearch,
          effectiveBranchId,
          initialFieldOperationId,
        );
        setCustomerResults(customers || []);
      } catch (error) {
        appLogger.error("Error searching customers:", error);
      } finally {
        setSearchingCustomers(false);
      }
    };
    const debounce = setTimeout(searchCustomers, 300);
    return () => clearTimeout(debounce);
  }, [customerSearch, effectiveBranchId, initialFieldOperationId]);

  return {
    customerSearch,
    setCustomerSearch,
    customerResults,
    setCustomerResults,
    selectedCustomer,
    setSelectedCustomer,
    searchingCustomers,
    fetchCustomer,
  };
}

"use client";

import { useEffect, useState } from "react";

import { calculatePriceWithTax } from "@/lib/utils/tax";
import { getTaxPercentage } from "@/lib/utils/tax-config";

import { roundCurrency } from "./CreateQuoteForm.constants";
import type { QuoteFormData, QuoteSettings } from "./CreateQuoteForm.types";
import { buildAvailableTreatments } from "./quotePricingUtils";

const DEFAULT_FORM_DATA: QuoteFormData = {
  frame_name: "",
  frame_brand: "",
  frame_model: "",
  frame_color: "",
  frame_size: "",
  frame_sku: "",
  frame_price: 0,
  frame_price_includes_tax: false,
  customer_own_frame: false,
  lens_family_id: "",
  lens_type: "",
  lens_material: "",
  lens_index: null,
  lens_treatments: [],
  lens_tint_color: "",
  lens_tint_percentage: 0,
  lens_sourcing_type: "surfaced",
  frame_cost: 0,
  lens_cost: 0,
  treatments_cost: 0,
  labor_cost: 0,
  subtotal: 0,
  tax_amount: 0,
  discount_amount: 0,
  discount_percentage: 0,
  total_amount: 0,
  notes: "",
  customer_notes: "",
  expiration_days: 30,
  presbyopia_solution: "none",
  far_lens_family_id: "",
  near_lens_family_id: "",
  far_lens_cost: 0,
  near_lens_cost: 0,
  contact_lens_family_id: "",
  contact_lens_rx_sphere_od: null,
  contact_lens_rx_cylinder_od: null,
  contact_lens_rx_axis_od: null,
  contact_lens_rx_add_od: null,
  contact_lens_rx_base_curve_od: null,
  contact_lens_rx_diameter_od: null,
  contact_lens_rx_sphere_os: null,
  contact_lens_rx_cylinder_os: null,
  contact_lens_rx_axis_os: null,
  contact_lens_rx_add_os: null,
  contact_lens_rx_base_curve_os: null,
  contact_lens_rx_diameter_os: null,
  contact_lens_quantity: 1,
  contact_lens_cost: 0,
  contact_lens_price: 0,
  near_frame_product_id: "",
  near_frame_name: "",
  near_frame_brand: "",
  near_frame_model: "",
  near_frame_color: "",
  near_frame_size: "",
  near_frame_sku: "",
  near_frame_price: 0,
  near_frame_price_includes_tax: false,
  near_frame_cost: 0,
};

export function useFormPricing(
  quoteSettings: unknown,
  lensType: "optical" | "contact",
  presbyopiaSolution: string,
  customerOwnFrame: boolean,
  customerOwnNearFrame: boolean,
) {
  const [discountType, setDiscountType] = useState<"percentage" | "amount">(
    "amount",
  );
  const [taxPercentage, setTaxPercentage] = useState<number>(19.0);

  // Form data
  const [formData, setFormData] = useState<QuoteFormData>(DEFAULT_FORM_DATA);

  // Initialize tax percentage
  useEffect(() => {
    getTaxPercentage(19.0).then(setTaxPercentage);
  }, []);

  const availableTreatments = buildAvailableTreatments(
    quoteSettings as QuoteSettings,
  );

  const handleTreatmentToggle = (treatment: {
    value: string;
    label: string;
    cost: number;
    enabled: boolean;
  }) => {
    const isSelected = formData.lens_treatments.includes(treatment.value);
    setFormData((prev) => ({
      ...prev,
      lens_treatments: isSelected
        ? prev.lens_treatments.filter((t) => t !== treatment.value)
        : [...prev.lens_treatments, treatment.value],
      treatments_cost: isSelected
        ? prev.treatments_cost - treatment.cost
        : prev.treatments_cost + treatment.cost,
    }));
  };

  // Calculate total
  const calculateTotal = () => {
    const effectiveTaxRate =
      (quoteSettings as QuoteSettings)?.default_tax_percentage || taxPercentage;
    const lensIncludesTax =
      lensType === "contact"
        ? true
        : ((quoteSettings as QuoteSettings)?.lens_cost_includes_tax ?? true);
    const treatmentsIncludeTax =
      (quoteSettings as QuoteSettings)?.treatments_cost_includes_tax ?? true;
    const laborIncludesTax =
      (quoteSettings as QuoteSettings)?.labor_cost_includes_tax ?? true;

    const framePriceForCalculation = customerOwnFrame
      ? 0
      : formData.frame_price || 0;
    const framePriceBreakdown = calculatePriceWithTax(
      framePriceForCalculation,
      formData.frame_price_includes_tax || false,
      effectiveTaxRate,
    );

    const nearFramePriceForCalculation =
      presbyopiaSolution === "two_separate" && !customerOwnNearFrame
        ? formData.near_frame_price || 0
        : 0;
    const nearFramePriceBreakdown = calculatePriceWithTax(
      nearFramePriceForCalculation,
      formData.near_frame_price_includes_tax || false,
      effectiveTaxRate,
    );

    const effectiveLensCost =
      lensType === "contact"
        ? formData.contact_lens_price || formData.contact_lens_cost || 0
        : presbyopiaSolution === "two_separate"
          ? (formData.far_lens_cost || 0) + (formData.near_lens_cost || 0)
          : formData.lens_cost || 0;

    const lensBreakdown = calculatePriceWithTax(
      effectiveLensCost,
      lensIncludesTax,
      effectiveTaxRate,
    );
    const treatmentsBreakdown = calculatePriceWithTax(
      formData.treatments_cost || 0,
      treatmentsIncludeTax,
      effectiveTaxRate,
    );
    const laborBreakdown = calculatePriceWithTax(
      formData.labor_cost || 0,
      laborIncludesTax,
      effectiveTaxRate,
    );

    const subtotal =
      framePriceBreakdown.subtotal +
      nearFramePriceBreakdown.subtotal +
      lensBreakdown.subtotal +
      treatmentsBreakdown.subtotal +
      laborBreakdown.subtotal;

    const taxFromItemsWithTax =
      framePriceBreakdown.tax +
      nearFramePriceBreakdown.tax +
      (lensIncludesTax ? lensBreakdown.tax : 0) +
      (treatmentsIncludeTax ? treatmentsBreakdown.tax : 0) +
      (laborIncludesTax ? laborBreakdown.tax : 0);

    const itemsWithoutTax =
      (lensIncludesTax ? 0 : lensBreakdown.subtotal) +
      (treatmentsIncludeTax ? 0 : treatmentsBreakdown.subtotal) +
      (laborIncludesTax ? 0 : laborBreakdown.subtotal) +
      (formData.frame_price_includes_tax ? 0 : framePriceBreakdown.subtotal) +
      (formData.near_frame_price_includes_tax
        ? 0
        : nearFramePriceBreakdown.subtotal);

    const taxOnItemsWithoutTax = itemsWithoutTax * (effectiveTaxRate / 100);
    const totalTax = taxFromItemsWithTax + taxOnItemsWithoutTax;
    const totalWithTax = subtotal + totalTax;

    let discount = 0;
    let discountPercentage = 0;
    if (discountType === "percentage") {
      discount = totalWithTax * (formData.discount_percentage / 100);
      discountPercentage = formData.discount_percentage;
    } else {
      discount = formData.discount_amount || 0;
      if (totalWithTax > 0)
        discountPercentage = (discount / totalWithTax) * 100;
    }
    if (discount > totalWithTax) {
      discount = totalWithTax;
      if (discountType === "amount") discountPercentage = 100;
    }

    const total = totalWithTax - discount;
    setFormData((prev) => ({
      ...prev,
      subtotal: roundCurrency(subtotal),
      discount_amount: roundCurrency(discount),
      discount_percentage: roundCurrency(discountPercentage),
      tax_amount: roundCurrency(totalTax),
      total_amount: roundCurrency(total),
    }));
  };

  // Recalculate total on any price change
  useEffect(() => {
    calculateTotal();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    formData.frame_price,
    formData.frame_price_includes_tax,
    formData.frame_cost,
    formData.near_frame_price,
    formData.near_frame_price_includes_tax,
    formData.near_frame_cost,
    formData.lens_cost,
    formData.contact_lens_cost,
    formData.contact_lens_price,
    formData.treatments_cost,
    formData.labor_cost,
    formData.discount_percentage,
    formData.discount_amount,
    discountType,
    quoteSettings,
    taxPercentage,
    lensType,
    presbyopiaSolution,
    customerOwnFrame,
    customerOwnNearFrame,
  ]);

  return {
    formData,
    setFormData,
    discountType,
    setDiscountType,
    taxPercentage,
    setTaxPercentage,
    availableTreatments,
    handleTreatmentToggle,
    calculateTotal,
  };
}

"use client";

import type React from "react";
import { useEffect, useState } from "react";

import { productService } from "@/lib/api/services";
import { appLogger } from '@/lib/logger';

import type { QuoteFormData } from "./CreateQuoteForm.types";

export function useFrameSelection(
  effectiveBranchId: string | undefined,
  initialFieldOperationId: string | undefined,
  setFormData: React.Dispatch<React.SetStateAction<QuoteFormData>>,
) {
  // Frame selection
  const [frameSearch, setFrameSearch] = useState("");
  const [frameResults, setFrameResults] = useState<unknown[]>([]);
  const [selectedFrame, setSelectedFrame] = useState<unknown>(null);
  const [searchingFrames, setSearchingFrames] = useState(false);

  // Second frame for two separate lenses (near vision)
  const [nearFrameSearch, setNearFrameSearch] = useState("");
  const [nearFrameResults, setNearFrameResults] = useState<unknown[]>([]);
  const [selectedNearFrame, setSelectedNearFrame] = useState<unknown>(null);
  const [searchingNearFrames, setSearchingNearFrames] = useState(false);
  const [customerOwnFrame, setCustomerOwnFrame] = useState<boolean>(false);
  const [customerOwnNearFrame, setCustomerOwnNearFrame] =
    useState<boolean>(false);

  // Search frames
  useEffect(() => {
    const searchFrames = async () => {
      if (frameSearch.length < 2) {
        setFrameResults([]);
        return;
      }
      setSearchingFrames(true);
      try {
        const frames = await productService.searchProducts(
          frameSearch,
          effectiveBranchId,
          "frame",
          initialFieldOperationId,
        );
        setFrameResults(frames || []);
      } catch (error) {
        appLogger.error("Error searching frames:", error);
      } finally {
        setSearchingFrames(false);
      }
    };
    const debounce = setTimeout(searchFrames, 300);
    return () => clearTimeout(debounce);
  }, [frameSearch, effectiveBranchId, initialFieldOperationId]);

  // Search near frames
  useEffect(() => {
    const searchNearFrames = async () => {
      if (nearFrameSearch.length < 2) {
        setNearFrameResults([]);
        return;
      }
      setSearchingNearFrames(true);
      try {
        const results = await productService.searchProducts(
          nearFrameSearch,
          effectiveBranchId,
          "frame",
          initialFieldOperationId,
        );
        setNearFrameResults(results || []);
      } catch (error) {
        appLogger.error("Error searching near frames:", error);
      } finally {
        setSearchingNearFrames(false);
      }
    };
    const debounce = setTimeout(searchNearFrames, 300);
    return () => clearTimeout(debounce);
  }, [nearFrameSearch, effectiveBranchId, initialFieldOperationId]);

  const handleFrameSelect = (frame: unknown) => {
    setSelectedFrame(frame);
    setFormData((prev) => ({
      ...prev,
      frame_product_id: (frame as Record<string, unknown>).id as string,
      frame_name: (frame as Record<string, unknown>).name as string,
      frame_brand: ((frame as Record<string, unknown>).frame_brand as string) || "",
      frame_model: ((frame as Record<string, unknown>).frame_model as string) || "",
      frame_color: ((frame as Record<string, unknown>).frame_color as string) || "",
      frame_size: ((frame as Record<string, unknown>).frame_size as string) || "",
      frame_sku: ((frame as Record<string, unknown>).sku as string) || "",
      frame_price: ((frame as Record<string, unknown>).price as number) || 0,
      frame_price_includes_tax:
        ((frame as Record<string, unknown>).price_includes_tax as boolean) || false,
      frame_cost: ((frame as Record<string, unknown>).price as number) || 0,
    }));
    setFrameSearch("");
    setFrameResults([]);
  };

  const handleNearFrameSelect = (frame: unknown) => {
    setSelectedNearFrame(frame);
    const nearFrameCost = (frame as Record<string, unknown>).price as number || 0;
    setFormData((prev) => ({
      ...prev,
      near_frame_product_id: (frame as Record<string, unknown>).id as string,
      near_frame_name: (frame as Record<string, unknown>).name as string,
      near_frame_brand: ((frame as Record<string, unknown>).frame_brand as string) || "",
      near_frame_model: ((frame as Record<string, unknown>).frame_model as string) || "",
      near_frame_color: ((frame as Record<string, unknown>).frame_color as string) || "",
      near_frame_size: ((frame as Record<string, unknown>).frame_size as string) || "",
      near_frame_sku: ((frame as Record<string, unknown>).sku as string) || "",
      near_frame_price: ((frame as Record<string, unknown>).price as number) || 0,
      near_frame_price_includes_tax:
        ((frame as Record<string, unknown>).price_includes_tax as boolean) || false,
      near_frame_cost: nearFrameCost,
    }));
    setNearFrameSearch("");
    setNearFrameResults([]);
  };

  return {
    frameSearch,
    setFrameSearch,
    frameResults,
    setFrameResults,
    selectedFrame,
    setSelectedFrame,
    searchingFrames,
    setSearchingFrames,
    nearFrameSearch,
    setNearFrameSearch,
    nearFrameResults,
    setNearFrameResults,
    selectedNearFrame,
    setSelectedNearFrame,
    searchingNearFrames,
    setSearchingNearFrames,
    customerOwnFrame,
    setCustomerOwnFrame,
    customerOwnNearFrame,
    setCustomerOwnNearFrame,
    handleFrameSelect,
    handleNearFrameSelect,
  };
}

"use client";

import type React from "react";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { useLensPriceCalculation } from "@/hooks/useLensPriceCalculation";
import {
  contactLensFamilyService,
  contactLensMatrixService,
  lensFamilyService,
} from "@/lib/api/services";
import { appLogger } from '@/lib/logger';
import {
  getCylinder,
  getDefaultPresbyopiaSolution,
  getFarSphere,
  getMaxAddition,
  getNearSphere,
  hasAddition,
  type PresbyopiaSolution,
} from "@/lib/presbyopia-helpers";

import { MATERIAL_INDICES } from "./CreateQuoteForm.constants";
import type { QuoteFormData } from "./CreateQuoteForm.types";

export function useLensConfiguration(
  selectedPrescription: unknown,
  formData: QuoteFormData,
  setFormData: React.Dispatch<React.SetStateAction<QuoteFormData>>,
) {
  const { calculateLensPrice, loading: calculatingPrice } =
    useLensPriceCalculation();

  // Lens families and price calculation
  const [lensFamilies, setLensFamilies] = useState<unknown[]>([]);
  const [loadingFamilies, setLoadingFamilies] = useState(false);

  // Contact lens families and price calculation
  const [contactLensFamilies, setContactLensFamilies] = useState<unknown[]>([]);
  const [loadingContactLensFamilies, setLoadingContactLensFamilies] =
    useState(false);
  const [lensType, setLensType] = useState<"optical" | "contact">("optical");
  const [calculatingContactLensPrice, setCalculatingContactLensPrice] =
    useState(false);

  // Presbyopia solution
  const [presbyopiaSolution, setPresbyopiaSolution] =
    useState<PresbyopiaSolution>("none");
  const [farLensFamilyId, setFarLensFamilyId] = useState<string>("");
  const [nearLensFamilyId, setNearLensFamilyId] = useState<string>("");
  const [farLensCost, setFarLensCost] = useState<number>(0);
  const [nearLensCost, setNearLensCost] = useState<number>(0);
  const [manualLensPrice, setManualLensPrice] = useState<boolean>(false);

  const fetchLensFamilies = async () => {
    try {
      setLoadingFamilies(true);
      const families = await lensFamilyService.getAll();
      setLensFamilies(families || []);
    } catch (error) {
      appLogger.error("Error fetching lens families:", error);
    } finally {
      setLoadingFamilies(false);
    }
  };

  const fetchContactLensFamilies = async () => {
    try {
      setLoadingContactLensFamilies(true);
      const families = await contactLensFamilyService.getAll();
      setContactLensFamilies(families || []);
    } catch (error) {
      appLogger.error("Error fetching contact lens families:", error);
    } finally {
      setLoadingContactLensFamilies(false);
    }
  };

  // Fetch families on mount
  useEffect(() => {
    fetchLensFamilies();
    fetchContactLensFamilies();
  }, []);

  // Lens family inheritance
  useEffect(() => {
    if (!formData.lens_family_id) return;
    const family = lensFamilies.find(
      (f: unknown) => (f as Record<string, unknown>).id === formData.lens_family_id,
    );
    if (!family) return;
    const materialIndex = (family as Record<string, unknown>).lens_material
      ? MATERIAL_INDICES[
          (family as Record<string, unknown>).lens_material as keyof typeof MATERIAL_INDICES
        ] || null
      : null;

    setFormData((prev) => ({
      ...prev,
      lens_type: ((family as Record<string, unknown>).lens_type as string) || prev.lens_type,
      lens_material: ((family as Record<string, unknown>).lens_material as string) || prev.lens_material,
      lens_index: materialIndex !== null ? materialIndex : prev.lens_index,
      lens_treatments: [],
      treatments_cost: 0,
    }));
  }, [formData.lens_family_id, lensFamilies, setFormData]);

  // Calculate lens price from matrix
  const calculateLensPriceFromMatrix = async () => {
    if (!formData.lens_family_id || !selectedPrescription) return;
    if (presbyopiaSolution === "two_separate") return;

    const uuidRegex =
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    if (!uuidRegex.test(formData.lens_family_id)) return;

    const farSphere = getFarSphere(selectedPrescription as unknown);
    const cylinder = getCylinder(selectedPrescription as unknown);
    let addition: number | undefined;
    if (["progressive", "bifocal", "trifocal"].includes(presbyopiaSolution)) {
      addition = getMaxAddition(selectedPrescription as unknown);
    }

    try {
      await fetch(
        `/api/admin/lens-matrices/debug?lens_family_id=${formData.lens_family_id}&sphere=${farSphere}&cylinder=${cylinder}`,
      );
      const result = await calculateLensPrice({
        lens_family_id: formData.lens_family_id,
        sphere: farSphere,
        cylinder,
        addition,
      });
      if (result && result.price) {
        setFormData((prev) => ({ ...prev, lens_cost: result.price }));
      }
    } catch {
      // Silently fail — manual price entry available
    }
  };

  // Calculate contact lens price from matrix
  const calculateContactLensPriceFromMatrix = async () => {
    if (!formData.contact_lens_family_id || !selectedPrescription) return;
    const uuidRegex =
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    if (!uuidRegex.test(formData.contact_lens_family_id)) return;

    try {
      setCalculatingContactLensPrice(true);
      const sphereOD = (selectedPrescription as unknown).od_sphere || 0;
      const cylinderOD = (selectedPrescription as unknown).od_cylinder || 0;
      const axisOD = (selectedPrescription as unknown).od_axis || null;
      const additionOD = (selectedPrescription as unknown).od_add || null;

      const calculation = await contactLensMatrixService.calculate(
        formData.contact_lens_family_id,
        sphereOD,
        cylinderOD,
        axisOD,
        additionOD,
      );
      if (calculation && calculation.price) {
        const quantity = formData.contact_lens_quantity || 1;
        setFormData((prev) => ({
          ...prev,
          contact_lens_price: calculation.price * quantity,
          contact_lens_cost: calculation.cost * quantity,
        }));
      }
    } catch {
      toast.error("No se pudo calcular el precio del lente de contacto");
    } finally {
      setCalculatingContactLensPrice(false);
    }
  };

  // Detect presbyopia and set default solution
  useEffect(() => {
    if (selectedPrescription) {
      const hasAdd = hasAddition(selectedPrescription as unknown);
      if (hasAdd && presbyopiaSolution === "none") {
        const defaultSolution = getDefaultPresbyopiaSolution(
          selectedPrescription as unknown,
        );
        setPresbyopiaSolution(defaultSolution);
        setFormData((prev) => ({
          ...prev,
          presbyopia_solution: defaultSolution,
        }));
        if (["progressive", "bifocal", "trifocal"].includes(defaultSolution)) {
          setFormData((prev) => ({ ...prev, lens_type: defaultSolution }));
        }
      } else if (!hasAdd) {
        setPresbyopiaSolution("none");
        setFormData((prev) => ({ ...prev, presbyopia_solution: "none" }));
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedPrescription]);

  // Recalculate lens price when params change
  useEffect(() => {
    if (formData.lens_family_id && selectedPrescription) {
      const timer = setTimeout(() => {
        calculateLensPriceFromMatrix();
      }, 50);
      return () => clearTimeout(timer);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    formData.lens_family_id,
    (selectedPrescription as unknown)?.id,
    presbyopiaSolution,
  ]);

  // Recalculate contact lens price
  useEffect(() => {
    if (
      formData.contact_lens_family_id &&
      selectedPrescription &&
      lensType === "contact"
    ) {
      const timer = setTimeout(() => {
        calculateContactLensPriceFromMatrix();
      }, 50);
      return () => clearTimeout(timer);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    formData.contact_lens_family_id,
    formData.contact_lens_quantity,
    (selectedPrescription as unknown)?.id,
    lensType,
  ]);

  // Calculate prices for two separate lenses
  useEffect(() => {
    if (presbyopiaSolution === "two_separate" && selectedPrescription) {
      const calculateTwoLenses = async () => {
        const uuidRegex =
          /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

        if (farLensFamilyId && uuidRegex.test(farLensFamilyId)) {
          const farSphere = getFarSphere(selectedPrescription as unknown);
          const cylinder = getCylinder(selectedPrescription as unknown);
          try {
            const result = await calculateLensPrice({
              lens_family_id: farLensFamilyId,
              sphere: farSphere,
              cylinder,
            });
            if (result && result.price) {
              setFarLensCost(result.price);
              setFormData((prev) => ({ ...prev, far_lens_cost: result.price }));
            }
          } catch {
            /* silent */
          }
        }

        if (nearLensFamilyId && uuidRegex.test(nearLensFamilyId)) {
          const nearSphere = getNearSphere(selectedPrescription as unknown);
          const cylinder = getCylinder(selectedPrescription as unknown);
          try {
            const result = await calculateLensPrice({
              lens_family_id: nearLensFamilyId,
              sphere: nearSphere,
              cylinder,
            });
            if (result && result.price) {
              setNearLensCost(result.price);
              setFormData((prev) => ({
                ...prev,
                near_lens_cost: result.price,
              }));
            }
          } catch {
            /* silent */
          }
        }

        const totalLensCost = (farLensCost || 0) + (nearLensCost || 0);
        setFormData((prev) => ({ ...prev, lens_cost: totalLensCost }));
      };
      calculateTwoLenses();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    farLensFamilyId,
    nearLensFamilyId,
    selectedPrescription,
    presbyopiaSolution,
  ]);

  return {
    lensFamilies,
    setLensFamilies,
    loadingFamilies,
    lensType,
    setLensType,
    contactLensFamilies,
    setContactLensFamilies,
    loadingContactLensFamilies,
    calculatingContactLensPrice,
    setCalculatingContactLensPrice,
    presbyopiaSolution,
    setPresbyopiaSolution,
    farLensFamilyId,
    setFarLensFamilyId,
    nearLensFamilyId,
    setNearLensFamilyId,
    farLensCost,
    setFarLensCost,
    nearLensCost,
    setNearLensCost,
    manualLensPrice,
    setManualLensPrice,
    calculatingPrice,
    calculateLensPriceFromMatrix,
    calculateContactLensPriceFromMatrix,
  };
}

"use client";

import type React from "react";
import { useState } from "react";
import { toast } from "sonner";

import { quoteService } from "@/lib/api/services";
import { appLogger } from '@/lib/logger';
import { getBranchAndOperativoHeaders } from "@/lib/utils/branch";

import type { QuoteFormData } from "./CreateQuoteForm.types";

export function useQuoteSubmit(
  selectedCustomer: unknown,
  selectedPrescription: unknown,
  formData: QuoteFormData,
  selectedFrame: unknown,
  selectedNearFrame: unknown,
  lensType: "optical" | "contact",
  presbyopiaSolution: string,
  customerOwnFrame: boolean,
  customerOwnNearFrame: boolean,
  farLensFamilyId: string,
  nearLensFamilyId: string,
  farLensCost: number,
  nearLensCost: number,
  effectiveBranchId: string | undefined,
  initialFieldOperationId: string | undefined,
  onSuccess: () => void,
) {
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);

  // Submit handler
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!selectedCustomer) {
      toast.error("Selecciona un cliente");
      return;
    }
    if (!selectedPrescription) {
      toast.error("Selecciona una receta");
      return;
    }

    if (lensType === "contact") {
      if (
        !formData.contact_lens_family_id &&
        formData.contact_lens_cost === 0
      ) {
        toast.error(
          "Selecciona una familia de lentes de contacto o ingresa el precio manualmente",
        );
        return;
      }
    } else {
      if (presbyopiaSolution === "two_separate") {
        if (!farLensFamilyId && !nearLensFamilyId && formData.lens_cost === 0) {
          toast.error(
            "Selecciona familias de lentes o ingresa el precio manualmente",
          );
          return;
        }
      } else if (!formData.lens_family_id && formData.lens_cost === 0) {
        toast.error(
          "Selecciona una familia de lentes o ingresa el precio manualmente",
        );
        return;
      }
    }

    setSaving(true);
    try {
      const expirationDate = new Date();
      expirationDate.setDate(
        expirationDate.getDate() + formData.expiration_days,
      );

      const headers: HeadersInit = {
        "Content-Type": "application/json",
        ...getBranchAndOperativoHeaders(
          effectiveBranchId ?? null,
          initialFieldOperationId,
        ),
      };

      const nearFrameDataPayload =
        presbyopiaSolution === "two_separate"
          ? {
              near_frame_product_id:
                (selectedNearFrame as unknown)?.id || null,
              near_frame_name:
                formData.near_frame_name ||
                (selectedNearFrame as unknown)?.name ||
                null,
              near_frame_brand:
                formData.near_frame_brand ||
                (selectedNearFrame as unknown)?.frame_brand ||
                null,
              near_frame_model:
                formData.near_frame_model ||
                (selectedNearFrame as unknown)?.frame_model ||
                null,
              near_frame_color:
                formData.near_frame_color ||
                (selectedNearFrame as unknown)?.frame_color ||
                null,
              near_frame_size:
                formData.near_frame_size ||
                (selectedNearFrame as unknown)?.frame_size ||
                null,
              near_frame_sku:
                formData.near_frame_sku ||
                (selectedNearFrame as unknown)?.sku ||
                null,
              near_frame_price:
                formData.near_frame_price ||
                (selectedNearFrame as unknown)?.price ||
                0,
              near_frame_price_includes_tax:
                formData.near_frame_price_includes_tax ??
                (selectedNearFrame as unknown)?.price_includes_tax ??
                false,
              near_frame_cost:
                formData.near_frame_cost ||
                (selectedNearFrame as unknown)?.price ||
                0,
              customer_own_near_frame: customerOwnNearFrame || false,
            }
          : {
              near_frame_product_id: null,
              near_frame_name: null,
              near_frame_brand: null,
              near_frame_model: null,
              near_frame_color: null,
              near_frame_size: null,
              near_frame_sku: null,
              near_frame_price: 0,
              near_frame_price_includes_tax: false,
              near_frame_cost: 0,
              customer_own_near_frame: false,
            };

      await quoteService.createQuote({
        customer_id: (selectedCustomer as unknown).id,
        status: "draft",
        subtotal: formData.subtotal,
        tax_amount: formData.tax_amount,
        discount_amount: formData.discount_amount,
        total_amount: formData.total_amount,
        valid_until: expirationDate.toISOString().split("T")[0],
        notes: formData.notes,
        branch_id: effectiveBranchId || undefined,
        field_operation_id: initialFieldOperationId || undefined,
        prescription_id: (selectedPrescription as unknown).id,
        frame_product_id: (selectedFrame as unknown)?.id,
        customer_own_frame: customerOwnFrame,
        frame_name: formData.frame_name,
        frame_brand: formData.frame_brand,
        frame_model: formData.frame_model,
        frame_color: formData.frame_color,
        frame_size: formData.frame_size,
        frame_sku: formData.frame_sku,
        frame_price: formData.frame_price,
        ...nearFrameDataPayload,
        lens_family_id:
          presbyopiaSolution === "two_separate"
            ? null
            : formData.lens_family_id || null,
        lens_type:
          lensType === "contact"
            ? "Lentes de contacto"
            : formData.lens_type || null,
        lens_material: formData.lens_material || null,
        lens_index:
          formData.lens_index !== null && formData.lens_index !== undefined
            ? formData.lens_index
            : null,
        lens_treatments: lensType === "contact" ? [] : formData.lens_treatments,
        lens_tint_color: formData.lens_tint_color || null,
        lens_tint_percentage: formData.lens_tint_percentage || null,
        lens_sourcing_type: formData.lens_sourcing_type || "surfaced",
        presbyopia_solution: formData.presbyopia_solution || "none",
        far_lens_family_id:
          presbyopiaSolution === "two_separate"
            ? farLensFamilyId || null
            : null,
        near_lens_family_id:
          presbyopiaSolution === "two_separate"
            ? nearLensFamilyId || null
            : null,
        far_lens_cost:
          presbyopiaSolution === "two_separate" ? farLensCost || 0 : undefined,
        near_lens_cost:
          presbyopiaSolution === "two_separate"
            ? nearLensCost || 0
            : undefined,
        contact_lens_family_id:
          lensType === "contact"
            ? formData.contact_lens_family_id || null
            : null,
        contact_lens_rx_sphere_od:
          lensType === "contact" && selectedPrescription
            ? ((selectedPrescription as unknown).od_sphere ?? null)
            : null,
        contact_lens_rx_cylinder_od:
          lensType === "contact" && selectedPrescription
            ? ((selectedPrescription as unknown).od_cylinder ?? null)
            : null,
        contact_lens_rx_axis_od:
          lensType === "contact" && selectedPrescription
            ? ((selectedPrescription as unknown).od_axis ?? null)
            : null,
        contact_lens_rx_add_od:
          lensType === "contact" && selectedPrescription
            ? ((selectedPrescription as unknown).od_add ?? null)
            : null,
        contact_lens_rx_base_curve_od:
          lensType === "contact"
            ? formData.contact_lens_rx_base_curve_od
            : null,
        contact_lens_rx_diameter_od:
          lensType === "contact" ? formData.contact_lens_rx_diameter_od : null,
        contact_lens_rx_sphere_os:
          lensType === "contact" && selectedPrescription
            ? ((selectedPrescription as unknown).os_sphere ?? null)
            : null,
        contact_lens_rx_cylinder_os:
          lensType === "contact" && selectedPrescription
            ? ((selectedPrescription as unknown).os_cylinder ?? null)
            : null,
        contact_lens_rx_axis_os:
          lensType === "contact" && selectedPrescription
            ? ((selectedPrescription as unknown).os_axis ?? null)
            : null,
        contact_lens_rx_add_os:
          lensType === "contact" && selectedPrescription
            ? ((selectedPrescription as unknown).os_add ?? null)
            : null,
        contact_lens_rx_base_curve_os:
          lensType === "contact"
            ? formData.contact_lens_rx_base_curve_os
            : null,
        contact_lens_rx_diameter_os:
          lensType === "contact" ? formData.contact_lens_rx_diameter_os : null,
        contact_lens_quantity:
          lensType === "contact" ? formData.contact_lens_quantity || 1 : 1,
        contact_lens_cost:
          lensType === "contact" ? formData.contact_lens_cost || 0 : 0,
        contact_lens_price:
          lensType === "contact" ? formData.contact_lens_price || 0 : 0,
        frame_cost: formData.frame_cost,
        lens_cost: lensType === "contact" ? 0 : formData.lens_cost,
        treatments_cost:
          lensType === "contact" ? 0 : formData.treatments_cost,
        labor_cost: formData.labor_cost,
      });

      toast.success("Presupuesto creado exitosamente");
      onSuccess();
    } catch (error: unknown) {
      appLogger.error("Error creating quote:", error);
      toast.error(
        (error as Error).message || "Error al crear presupuesto",
      );
    } finally {
      setSaving(false);
    }
  };

  return {
    loading,
    saving,
    setSaving,
    handleSubmit,
  };
}

import { QuoteFormData } from "../types/quote.types";

export interface ValidationError {
  field: string;
  message: string;
}

export interface ValidationResult {
  isValid: boolean;
  errors: ValidationError[];
}

export class QuoteFormValidator {
  static validate(
    formData: QuoteFormData,
    selectedCustomer: unknown,
    selectedPrescription: unknown,
  ): ValidationResult {
    const errors: ValidationError[] = [];

    // Customer validation
    if (!selectedCustomer) {
      errors.push({
        field: "customer",
        message: "Debe seleccionar un cliente",
      });
    }

    // Prescription validation
    if (!selectedPrescription) {
      errors.push({
        field: "prescription",
        message: "Debe seleccionar una receta",
      });
    }

    // Frame validation
    if (!formData.customer_own_frame && !formData.frame_name) {
      errors.push({
        field: "frame_name",
        message:
          "Debe ingresar el nombre del marco o seleccionar uno existente",
      });
    }

    // Lens validation
    if (
      formData.lens_type === "optical" &&
      !formData.lens_family_id &&
      !formData.lens_cost
    ) {
      errors.push({
        field: "lens_cost",
        message:
          "Debe seleccionar una familia de lentes o ingresar el costo manualmente",
      });
    }

    // Contact lens validation
    if (formData.lens_type === "contact" && !formData.contact_lens_family_id) {
      errors.push({
        field: "contact_lens_family_id",
        message: "Debe seleccionar una familia de lentes de contacto",
      });
    }

    // Price validations
    if (formData.frame_price < 0) {
      errors.push({
        field: "frame_price",
        message: "El precio del marco no puede ser negativo",
      });
    }

    if (formData.lens_cost < 0) {
      errors.push({
        field: "lens_cost",
        message: "El costo del lente no puede ser negativo",
      });
    }

    // Discount validation
    if (
      formData.discount_percentage < 0 ||
      formData.discount_percentage > 100
    ) {
      errors.push({
        field: "discount_percentage",
        message: "El porcentaje de descuento debe estar entre 0 y 100",
      });
    }

    if (formData.discount_amount < 0) {
      errors.push({
        field: "discount_amount",
        message: "El monto de descuento no puede ser negativo",
      });
    }

    // Expiration validation
    if (formData.expiration_days < 1 || formData.expiration_days > 365) {
      errors.push({
        field: "expiration_days",
        message: "La validez debe estar entre 1 y 365 días",
      });
    }

    return {
      isValid: errors.length === 0,
      errors,
    };
  }

  static validateCustomerOwnFrame(formData: QuoteFormData): ValidationResult {
    const errors: ValidationError[] = [];

    if (formData.customer_own_frame) {
      if (!formData.frame_name?.trim()) {
        errors.push({
          field: "frame_name",
          message:
            "Debe ingresar el nombre del marco cuando el cliente lo trae",
        });
      }
    }

    return {
      isValid: errors.length === 0,
      errors,
    };
  }

  static validateTwoSeparateLenses(formData: QuoteFormData): ValidationResult {
    const errors: ValidationError[] = [];

    // Validate near frame for two separate solution
    if (formData.presbyopia_solution === "two_separate") {
      if (!formData.customer_own_near_frame && !formData.near_frame_name) {
        errors.push({
          field: "near_frame_name",
          message: "Debe ingresar el nombre del marco para visión de cerca",
        });
      }

      if (!formData.far_lens_family_id) {
        errors.push({
          field: "far_lens_family_id",
          message:
            "Debe seleccionar una familia de lentes para visión de lejos",
        });
      }

      if (!formData.near_lens_family_id) {
        errors.push({
          field: "near_lens_family_id",
          message:
            "Debe seleccionar una familia de lentes para visión de cerca",
        });
      }
    }

    return {
      isValid: errors.length === 0,
      errors,
    };
  }

  static getErrorMessage(
    errors: ValidationError[],
    field: string,
  ): string | undefined {
    const error = errors.find((e) => e.field === field);
    return error?.message;
  }

  static hasError(errors: ValidationError[], field: string): boolean {
    return errors.some((e) => e.field === field);
  }
}

// Validation hook
export function useQuoteValidation() {
  const validate = (
    formData: QuoteFormData,
    selectedCustomer: unknown,
    selectedPrescription: unknown,
  ) => {
    return QuoteFormValidator.validate(
      formData,
      selectedCustomer,
      selectedPrescription,
    );
  };

  const validateField = (
    field: string,
    value: unknown,
    formData: QuoteFormData,
  ) => {
    const tempData = { ...formData, [field]: value };
    const result = QuoteFormValidator.validate(tempData, {}, {});
    return QuoteFormValidator.getErrorMessage(result.errors, field);
  };

  return {
    validate,
    validateField,
  };
}

"use client";

import { Loader2, Package, Search, User } from "lucide-react";
import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { extractDataFromResponse } from "@/lib/api/response-helpers";
import { appLogger } from '@/lib/logger';

interface SearchResult {
  id: string;
  name: string;
  type: "customer" | "product";
  subtitle?: string;
}

interface DashboardSearchProps {
  type: "customer" | "product";
  placeholder?: string;
}

export function DashboardSearch({ type, placeholder }: DashboardSearchProps) {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState<SearchResult[]>([]);
  const [loading, setLoading] = useState(false);
  const [open, setOpen] = useState(false);
  const router = useRouter();

  useEffect(() => {
    if (!query || query.length < 2) {
      setResults([]);
      return;
    }

    const searchTimeout = setTimeout(() => {
      performSearch();
    }, 300);

    return () => clearTimeout(searchTimeout);
  }, [query]);

  const performSearch = async () => {
    if (!query || query.length < 2) return;

    setLoading(true);
    try {
      const endpoint =
        type === "customer"
          ? `/api/admin/customers/search?q=${encodeURIComponent(query)}`
          : `/api/admin/products/search?q=${encodeURIComponent(query)}&limit=10`;

      const response = await fetch(endpoint);
      const data = await response.json();

      if (response.ok) {
        if (type === "customer") {
          setResults(
            (extractDataFromResponse(data) || []).map((c: unknown) => ({
              id: c.id,
              name:
                `${c.first_name || ""} ${c.last_name || ""}`.trim() ||
                c.email ||
                "Sin nombre",
              type: "customer" as const,
              subtitle: c.email || c.phone || c.rut || "",
            })),
          );
        } else {
          setResults(
            (extractDataFromResponse(data) || []).map((p: unknown) => ({
              id: p.id,
              name: p.name,
              type: "product" as const,
              subtitle:
                p.sku ||
                p.barcode ||
                `Stock: ${p.available_quantity ?? p.inventory_quantity ?? 0}`,
            })),
          );
        }
      }
    } catch (error) {
      appLogger.error("Error searching:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleSelect = (result: SearchResult) => {
    if (result.type === "customer") {
      router.push(`/admin/customers/${result.id}`);
    } else {
      router.push(`/admin/products/edit/${result.id}`);
    }
    setOpen(false);
    setQuery("");
    setResults([]);
  };

  return (
    <>
      <Button
        className="w-full justify-start h-10 hover:bg-[#AE0000]/5 hover:border-[#AE0000] border-gray-300 transition-all duration-300"
        variant="outline"
        onClick={() => setOpen(true)}
      >
        {type === "customer" ? (
          <User className="h-4 w-4 mr-2 flex-shrink-0 text-[var(--admin-accent-secondary)]" />
        ) : (
          <Package className="h-4 w-4 mr-2 flex-shrink-0" />
        )}
        <span className="truncate">
          {placeholder ||
            (type === "customer" ? "Buscar Cliente" : "Buscar Producto")}
        </span>
      </Button>

      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent className="max-w-[calc(100vw-2rem)] sm:max-w-[500px]">
          <DialogHeader>
            <DialogTitle>
              {type === "customer" ? "Buscar Cliente" : "Buscar Producto"}
            </DialogTitle>
            <DialogDescription>
              Escribe al menos 2 caracteres para buscar
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400" />
              <Input
                autoFocus
                className="pl-10"
                placeholder={
                  placeholder ||
                  (type === "customer"
                    ? "Nombre, email o RUT..."
                    : "Nombre, SKU o código de barras...")
                }
                value={query}
                onChange={(e) => setQuery(e.target.value)}
              />
            </div>

            {loading && (
              <div className="flex items-center justify-center py-8">
                <Loader2 className="h-6 w-6 animate-spin text-gray-400" />
              </div>
            )}

            {!loading && query.length >= 2 && results.length === 0 && (
              <div className="text-center py-8 text-gray-500">
                No se encontraron resultados
              </div>
            )}

            {!loading && results.length > 0 && (
              <div className="max-h-[400px] overflow-y-auto space-y-1">
                {results.map((result) => (
                  <button
                    className="w-full text-left p-3 rounded-lg hover:bg-gray-100 transition-colors border border-transparent hover:border-gray-200"
                    key={result.id}
                    onClick={() => handleSelect(result)}
                  >
                    <div className="flex items-center gap-3">
                      {result.type === "customer" ? (
                        <User className="h-5 w-5 text-gray-400 flex-shrink-0" />
                      ) : (
                        <Package className="h-5 w-5 text-gray-400 flex-shrink-0" />
                      )}
                      <div className="flex-1 min-w-0">
                        <p className="font-medium text-gray-900 truncate">
                          {result.name}
                        </p>
                        {result.subtitle && (
                          <p className="text-sm text-gray-500 truncate">
                            {result.subtitle}
                          </p>
                        )}
                      </div>
                    </div>
                  </button>
                ))}
              </div>
            )}
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
}

"use client";

import {
  AlertCircle,
  CheckCircle,
  DollarSign,
  RefreshCw,
  Truck,
} from "lucide-react";
import { useRouter } from "next/navigation";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import type { DeliveryError, WorkOrder } from "@/hooks/useWorkOrder";
import { formatCurrency } from "@/lib/utils";

interface DeliveryDialogProps {
  deliveryDialogOpen: boolean;
  setDeliveryDialogOpen: (open: boolean) => void;
  deliveryError: DeliveryError | null;
  setDeliveryError: (error: DeliveryError | null) => void;
  delivering: boolean;
  workOrder: WorkOrder | null;
  handleDeliver: () => Promise<void>;
}

export function DeliveryDialog({
  deliveryDialogOpen,
  setDeliveryDialogOpen,
  deliveryError,
  setDeliveryError,
  delivering,
  workOrder,
  handleDeliver,
}: DeliveryDialogProps) {
  const router = useRouter();

  return (
    <Dialog open={deliveryDialogOpen} onOpenChange={setDeliveryDialogOpen}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Truck className="h-5 w-5" />
            Entregar Trabajo
          </DialogTitle>
          <DialogDescription>
            {deliveryError?.requiresPayment ? (
              <div className="space-y-4">
                <div className="bg-red-50 border border-red-200 rounded-lg p-4">
                  <div className="flex items-start gap-3">
                    <AlertCircle className="h-5 w-5 text-red-600 mt-0.5" />
                    <div className="flex-1">
                      <p className="font-semibold text-red-800 mb-2">
                        Saldo Pendiente Detectado
                      </p>
                      <p className="text-red-700 mb-3">
                        {deliveryError.message}
                      </p>
                      <div className="bg-white rounded p-3 border border-red-200">
                        <p className="text-sm text-red-600 font-medium mb-1">
                          Saldo Pendiente:
                        </p>
                        <p className="text-2xl font-bold text-red-700">
                          {formatCurrency(deliveryError.balance || 0)}
                        </p>
                      </div>
                    </div>
                  </div>
                </div>
                <p className="text-sm text-gray-600">
                  El cliente debe pagar el saldo pendiente antes de poder
                  entregar el trabajo.
                </p>
              </div>
            ) : (
              <div>
                <p className="mb-4">
                  ¿Está seguro de que desea marcar este trabajo como entregado?
                </p>
                {workOrder && workOrder.pos_order_id && (
                  <div className="bg-blue-50 border border-blue-200 rounded-lg p-3">
                    <p className="text-sm text-blue-800">
                      El sistema verificará automáticamente que no haya saldo
                      pendiente antes de permitir la entrega.
                    </p>
                  </div>
                )}
              </div>
            )}
          </DialogDescription>
        </DialogHeader>
        <DialogFooter>
          <Button
            disabled={delivering}
            variant="outline"
            onClick={() => {
              setDeliveryDialogOpen(false);
              setDeliveryError(null);
            }}
          >
            Cancelar
          </Button>
          {deliveryError?.requiresPayment ? (
            <Button
              onClick={() => {
                setDeliveryDialogOpen(false);
                setDeliveryError(null);
                // Redirect to POS to collect payment
                if (deliveryError.orderId) {
                  router.push(
                    `/admin/pos?orderId=${deliveryError.orderId}&collectPayment=true`,
                  );
                } else {
                  toast.info(
                    "Redirigiendo al POS para cobrar el saldo pendiente...",
                  );
                  router.push("/admin/pos");
                }
              }}
            >
              <DollarSign className="h-4 w-4 mr-2" />
              Cobrar Saldo Pendiente
            </Button>
          ) : (
            <Button
              className="bg-green-600 hover:bg-green-700"
              disabled={delivering}
              onClick={handleDeliver}
            >
              {delivering ? (
                <>
                  <RefreshCw className="h-4 w-4 mr-2 animate-spin" />
                  Entregando...
                </>
              ) : (
                <>
                  <CheckCircle className="h-4 w-4 mr-2" />
                  Confirmar Entrega
                </>
              )}
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
