                            <>
                              <Button className="h-9 w-9 sm:h-9 sm:w-9 p-0 rounded-xl" size="sm" title="Ver plantilla" variant="ghost" onClick={() => { setSelectedTemplate(template); setShowPreviewDialog(true); }}><Eye className="h-4 w-4" /></Button>
                              <Button className="h-9 w-9 sm:h-9 sm:w-9 p-0 rounded-xl" size="sm" title="Editar plantilla" variant="ghost" onClick={() => { setSelectedTemplate(template); setShowEditDialog(true); }}><Edit className="h-4 w-4" /></Button>
                              <Button className="h-9 w-9 sm:h-9 sm:w-9 p-0 rounded-xl" disabled={testing === template.id} size="sm" title="Enviar email de prueba" variant="ghost" onClick={() => handleTestEmail(template)}><Send className={`h-4 w-4 ${testing === template.id ? "animate-spin" : ""}`} /></Button>
                              {!template.is_system && <Button className="text-red-600 h-9 w-9 sm:h-9 sm:w-9 p-0 rounded-xl" size="sm" variant="ghost" onClick={() => handleDeleteClick(template)}><Trash2 className="h-4 w-4" /></Button>}
                            </>
                          ) : (
                            <Button className="rounded-xl min-h-[44px] text-xs sm:text-sm" size="sm" onClick={() => { setCreateInitialType(type); setShowCreateDialog(true); }}>
                              <Plus className="h-4 w-4 mr-1 shrink-0" /><span className="truncate">Crear plantilla</span>
                            </Button>
                          )}
                        </div>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>

      {showEditDialog && selectedTemplate && <EmailTemplateEditor mode={mode} open={showEditDialog} organizationId={organizationId} template={selectedTemplate} onOpenChange={setShowEditDialog} onSave={() => { setShowEditDialog(false); fetchTemplates(); }} />}
      {showCreateDialog && <EmailTemplateEditor initialType={createInitialType} mode={mode} open={showCreateDialog} organizationId={organizationId} onOpenChange={(open) => { if (!open) setCreateInitialType(undefined); setShowCreateDialog(open); }} onSave={() => { setShowCreateDialog(false); setCreateInitialType(undefined); fetchTemplates(); }} />}
      {showPreviewDialog && selectedTemplate && <EmailTemplatePreviewDialog open={showPreviewDialog} template={selectedTemplate} onOpenChange={setShowPreviewDialog} />}
      <EmailTemplateDeleteDialog deleting={deleting} open={showDeleteDialog} template={templateToDelete} onConfirm={confirmDelete} onOpenChange={(open) => { setShowDeleteDialog(open); if (!open) setTemplateToDelete(null); }} />
      {showTestDialog && selectedTemplate && <EmailTemplateTestDialog open={showTestDialog} template={selectedTemplate} testing={testing} onOpenChange={setShowTestDialog} onSend={(id, email) => confirmTestEmailWith(id, email)} />}
    </div>
  );
}

"use client";

import { HelpCircle } from "lucide-react";
import { useState } from "react";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";

interface HelpDialogProps {
  title: string;
  description: string;
  details?: string[];
  formula?: string;
  example?: string;
}

export function HelpDialog({
  title,
  description,
  details,
  formula,
  example,
}: HelpDialogProps) {
  const [open, setOpen] = useState(false);

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button
          className="h-6 w-6 p-0 hover:bg-azul-profundo/10"
          size="sm"
          title={`Ayuda: ${title}`}
          variant="ghost"
        >
          <HelpCircle className="h-4 w-4 text-tierra-media hover:text-azul-profundo transition-colors" />
        </Button>
      </DialogTrigger>
      <DialogContent className="max-w-[calc(100vw-2rem)] sm:max-w-2xl max-h-[80vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="text-xl text-azul-profundo">
            {title}
          </DialogTitle>
          <DialogDescription className="text-base text-gray-700 pt-2">
            {description}
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 pt-4">
          {details && details.length > 0 && (
            <div>
              <h4 className="font-semibold text-azul-profundo mb-2">
                ¿Qué muestra?
              </h4>
              <ul className="list-disc list-inside space-y-1 text-sm text-gray-700">
                {details.map((detail, index) => (
                  <li key={index}>{detail}</li>
                ))}
              </ul>
            </div>
          )}

          {formula && (
            <div className="bg-gray-50 border border-gray-200 rounded-lg p-4">
              <h4 className="font-semibold text-azul-profundo mb-2">Fórmula</h4>
              <code className="text-sm text-gray-800 font-mono bg-white px-2 py-1 rounded border">
                {formula}
              </code>
            </div>
          )}

          {example && (
            <div className="bg-verde-suave/10 border border-verde-suave/30 rounded-lg p-4">
              <h4 className="font-semibold text-azul-profundo mb-2">Ejemplo</h4>
              <p className="text-sm text-gray-700">{example}</p>
            </div>
          )}

          <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
            <h4 className="font-semibold text-azul-profundo mb-2">💡 Nota</h4>
            <p className="text-sm text-gray-700">
              Los datos se calculan en base al período seleccionado (7, 30, 90 o
              365 días). Si no ves datos, puede ser porque aún no hay
              información registrada en el sistema para ese período.
            </p>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { HelpCircle } from "lucide-react";

import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { ANALYTICS_HELP } from "@/lib/analytics-help";

export type AnalyticsHelpKey = keyof typeof ANALYTICS_HELP;

interface MetricTooltipProps {
  metricKey: AnalyticsHelpKey;
  children?: React.ReactNode;
  className?: string;
}

export function MetricTooltip({
  metricKey,
  children,
  className,
}: MetricTooltipProps) {
  const help = ANALYTICS_HELP[metricKey];
  if (!help) return children ?? null;

  return (
    <Tooltip>
      <TooltipTrigger asChild>
        {children ?? (
          <button
            aria-label={`Ayuda: ${help.title}`}
            className={`inline-flex items-center justify-center rounded-full p-0.5 text-admin-text-tertiary hover:text-admin-accent-primary focus:outline-none focus:ring-2 focus:ring-admin-accent-primary/50 ${className ?? ""}`}
            type="button"
          >
            <HelpCircle className="h-3.5 w-3.5" />
          </button>
        )}
      </TooltipTrigger>
      <TooltipContent className="max-w-[280px] p-3 text-left" side="top">
        <div className="space-y-2">
          <p className="font-semibold text-sm">{help.title}</p>
          <p className="text-xs text-muted-foreground">{help.description}</p>
          {help.details && help.details.length > 0 && (
            <ul className="list-disc list-inside text-xs text-muted-foreground space-y-0.5">
              {help.details.map((d, i) => (
                <li key={i}>{d}</li>
              ))}
            </ul>
          )}
          {"formula" in help && help.formula && (
            <p className="text-[10px] font-mono text-muted-foreground/90 pt-1 border-t border-border">
              {help.formula}
            </p>
          )}
        </div>
      </TooltipContent>
    </Tooltip>
  );
}

