  notification_type: string;
  enabled: boolean;
  priority: "low" | "medium" | "high" | "urgent" | null;
  notify_all_admins: boolean;
  notify_specific_roles: string[] | null;
  metadata: unknown;
  created_at: string;
  updated_at: string;
}

interface NotificationSettingsProps {
  branchId?: string | null;
  organizationId?: string | null;
  branchName?: string;
  configScope?: "global" | "branch";
  onConfigScopeChange?: (scope: "global" | "branch") => void;
  hasMultipleBranches?: boolean;
}

/**
 * Configuración de notificaciones por tipo (quote_new, work_order_new, low_stock, etc.).
 * Soporta scope org o branch. Usa /api/admin/notifications/settings.
 *
 * @param props.branchId - Scope branch (opcional)
 * @param props.organizationId - Scope org
 * @param props.configScope - "global" (org) o "branch"
 * @param props.onConfigScopeChange - Callback al cambiar scope
 */
export default function NotificationSettings({
  branchId,
  organizationId,
  branchName,
  configScope = "global",
  onConfigScopeChange,
  hasMultipleBranches = false,
}: NotificationSettingsProps) {
  const {
    settings, loading, saving, hasChanges, tableNotFound,
    migrationSQL, loadingSQL, fetchMigrationSQL, copySQLToClipboard,
    fetchSettings, updateSetting, saveSettings, toggleAll,
  } = useNotificationSettings({ branchId, organizationId });

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <RefreshCw className="h-6 w-6 animate-spin text-epoch-primary/60" />
      </div>
    );
  }

  // Group settings by category
  const opticalSettings = settings.filter((s) =>
    [
      "quote_new",
      "quote_status_change",
      "quote_converted",
      "work_order_new",
      "work_order_status_change",
      "work_order_completed",
      "appointment_new",
      "appointment_cancelled",
    ].includes(s.notification_type),
  );

  const generalSettings = settings.filter((s) =>
    ["new_customer", "sale_new", "order_new", "order_status_change"].includes(
      s.notification_type,
    ),
  );

  const systemSettings = settings.filter((s) =>
    [
      "low_stock",
      "out_of_stock",
      "payment_received",
      "payment_failed",
      "support_ticket_new",
      "support_ticket_update",
      "system_alert",
      "system_update",
      "security_alert",
      "custom",
    ].includes(s.notification_type),
  );

  return (
    <div className="space-y-4 sm:space-y-6">
      <Card className="rounded-xl border border-border overflow-hidden">
        <CardHeader className="p-4 sm:p-6">
          <div className="flex flex-col gap-4 sm:gap-6">
            <div>
              <CardTitle className="flex items-center font-display text-epoch-primary text-base sm:text-lg">
                <Bell className="h-4 w-4 sm:h-5 sm:w-5 mr-2 shrink-0" />
                Configuración de Notificaciones
              </CardTitle>
              <CardDescription className="text-xs sm:text-sm text-epoch-primary/80 mt-1">
                {branchName
                  ? `Configuración para sucursal: ${branchName}`
                  : branchId
                    ? "Configuración para la sucursal seleccionada"
                    : "Configuración global de notificaciones. Activa o desactiva y personaliza prioridad."}
              </CardDescription>
            </div>
            <div className="flex flex-col sm:flex-row sm:items-center gap-3 sm:gap-2 flex-wrap">
              {hasMultipleBranches && onConfigScopeChange && (
                <div className="flex flex-col sm:flex-row sm:items-center gap-2 w-full sm:w-auto">
                  <Label className="text-xs sm:text-sm text-epoch-primary/80">
                    Alcance:
                  </Label>
                  <Select
                    value={configScope}
                    onValueChange={(v) =>
                      onConfigScopeChange(v as "global" | "branch")
                    }
                  >
                    <SelectTrigger className="w-full sm:w-[140px] rounded-xl min-h-[44px]">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="global">Organización</SelectItem>
                      <SelectItem value="branch">Sucursal</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              )}
              <Button
                className="rounded-xl min-h-[44px] w-full sm:w-auto"
                size="sm"
                variant="outline"
                onClick={() => toggleAll(true)}
              >
                Activar Todas
              </Button>
              <Button
                className="rounded-xl min-h-[44px] w-full sm:w-auto"
                size="sm"
                variant="outline"
                onClick={() => toggleAll(false)}
              >
                Desactivar Todas
              </Button>
              <Button
                className="rounded-xl min-h-[44px] w-full sm:w-auto"
                disabled={!hasChanges || saving}
                onClick={saveSettings}
              >
                {saving ? (
                  <>
                    <RefreshCw className="h-4 w-4 mr-2 animate-spin" />
                    Guardando...
                  </>
                ) : (
                  <>
                    <Save className="h-4 w-4 mr-2" />
                    Guardar Cambios
                  </>
                )}
              </Button>
            </div>
          </div>
        </CardHeader>
        <CardContent className="space-y-6">
          {tableNotFound && (
            <div className="bg-yellow-50 dark:bg-yellow-900/20 border border-yellow-200 dark:border-yellow-800 rounded-lg p-4 mb-6">
              <div className="flex items-start gap-3">
                <AlertTriangle className="h-5 w-5 text-yellow-600 dark:text-yellow-400 mt-0.5" />
                <div className="flex-1">
                  <h4 className="font-semibold text-yellow-800 dark:text-yellow-200 mb-1">
                    Tabla de configuración no encontrada
                  </h4>
                  <p className="text-sm text-yellow-700 dark:text-yellow-300 mb-3">
                    La tabla{" "}
                    <code className="bg-yellow-100 dark:bg-yellow-900/40 px-1 rounded">
                      notification_settings
                    </code>{" "}
                    no existe en la base de datos.
                  </p>
                  <p className="text-sm text-yellow-700 dark:text-yellow-300 mb-4">
                    Por favor, ejecuta la migración de base de datos en Supabase
                    Studio.
                  </p>
                  <div className="flex flex-wrap gap-2">
                    <Button
                      disabled={loadingSQL}
                      size="sm"
                      variant="outline"
                      onClick={copySQLToClipboard}
                    >
                      {loadingSQL ? (
                        <>
                          <RefreshCw className="h-4 w-4 mr-2 animate-spin" />
                          Cargando...
                        </>
                      ) : (
                        <>
                          <Copy className="h-4 w-4 mr-2" />
                          Copiar SQL
                        </>
                      )}
                    </Button>
                    <Button
                      disabled={loadingSQL}
                      size="sm"
                      variant="outline"
                      onClick={() => {
                        if (!migrationSQL) {
                          fetchMigrationSQL().then(() => {
                            setTimeout(() => {
                              const sqlTextarea =
                                document.getElementById("migration-sql");
                              if (sqlTextarea) {
                                sqlTextarea.scrollIntoView({
                                  behavior: "smooth",
                                });
                              }
                            }, 100);
                          });
                        } else {
                          const sqlTextarea =
                            document.getElementById("migration-sql");
                          if (sqlTextarea) {
                            sqlTextarea.scrollIntoView({ behavior: "smooth" });
                          }
                        }
                      }}
                    >
                      <ExternalLink className="h-4 w-4 mr-2" />
                      Ver SQL
                    </Button>
                  </div>
                  {migrationSQL && (
                    <div className="mt-4">
                      <Label className="text-sm font-medium mb-2 block">
                        SQL de la migración:
                      </Label>
                      <textarea
                        readOnly
                        className="w-full h-64 p-3 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-md font-mono text-xs overflow-auto"
                        id="migration-sql"
                        value={migrationSQL}
                        onClick={(e) => {
                          (e.target as HTMLTextAreaElement).select();
                          copySQLToClipboard();
                        }}
                      />
                      <p className="text-xs text-yellow-600 dark:text-yellow-400 mt-2">
                        💡 Haz clic en el área de texto para seleccionar todo y
                        copiar. Luego pégalo en Supabase Studio → SQL Editor.
                      </p>
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}

          {settings.length === 0 && !tableNotFound && (
            <div className="text-center py-8 text-muted-foreground">
              No hay configuraciones de notificaciones disponibles.
            </div>
          )}

          {settings.length > 0 && (
            <>
              {/* Optical Shop Settings */}
              <div>
                <h3 className="text-sm sm:text-base font-semibold mb-2 sm:mb-3">
                  Óptica
                </h3>
                <div className="space-y-2">
                  {opticalSettings.map((setting) => (
                    <div
                      className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2 p-2.5 sm:p-3 border border-border rounded-lg overflow-hidden"
                      key={setting.id}
                    >
                      <div className="flex items-center gap-2 min-w-0 flex-1">
                        <Label className="font-medium text-xs sm:text-sm truncate">
                          {NOTIFICATION_TYPE_LABELS[
                            setting.notification_type
                          ] || setting.notification_type}
                        </Label>
                        {setting.enabled ? (
                          <CheckCircle className="h-3.5 w-3.5 text-green-500 shrink-0" />
                        ) : (
                          <XCircle className="h-3.5 w-3.5 text-epoch-primary/40 shrink-0" />
                        )}
                      </div>
                      <div className="flex items-center gap-2 sm:gap-3 shrink-0">
                        <Switch
                          checked={setting.enabled}
                          className="scale-90 sm:scale-100"
                          onCheckedChange={(checked) =>
                            updateSetting(
                              setting.notification_type,
                              "enabled",
                              checked,
                            )
                          }
                        />
                        <Select
                          value={setting.priority || "medium"}
                          onValueChange={(value) =>
                            updateSetting(
                              setting.notification_type,
                              "priority",
                              value,
                            )
                          }
                        >
                          <SelectTrigger className="h-8 w-24 sm:w-28 rounded-lg text-xs">
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="low">Baja</SelectItem>
                            <SelectItem value="medium">Media</SelectItem>
                            <SelectItem value="high">Alta</SelectItem>
                            <SelectItem value="urgent">Urgente</SelectItem>
                          </SelectContent>
                        </Select>
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              {/* General Settings */}
              <div>
                <h3 className="text-sm sm:text-base font-semibold mb-2 sm:mb-3">
                  General
                </h3>
                <div className="space-y-2">
                  {generalSettings.map((setting) => (
                    <div
                      className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2 p-2.5 sm:p-3 border border-border rounded-lg overflow-hidden"
                      key={setting.id}
                    >
                      <div className="flex items-center gap-2 min-w-0 flex-1">
                        <Label className="font-medium text-xs sm:text-sm truncate">
                          {NOTIFICATION_TYPE_LABELS[
                            setting.notification_type
                          ] || setting.notification_type}
                        </Label>
                        {setting.enabled ? (
                          <CheckCircle className="h-3.5 w-3.5 text-green-500 shrink-0" />
                        ) : (
                          <XCircle className="h-3.5 w-3.5 text-epoch-primary/40 shrink-0" />
                        )}
                      </div>
                      <div className="flex items-center gap-2 sm:gap-3 shrink-0">
                        <Switch
                          checked={setting.enabled}
                          className="scale-90 sm:scale-100"
                          onCheckedChange={(checked) =>
                            updateSetting(
                              setting.notification_type,
                              "enabled",
                              checked,
                            )
                          }
                        />
                        <Select
                          value={setting.priority || "medium"}
                          onValueChange={(value) =>
                            updateSetting(
                              setting.notification_type,
                              "priority",
                              value,
                            )
                          }
                        >
                          <SelectTrigger className="h-8 w-24 sm:w-28 rounded-lg text-xs">
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="low">Baja</SelectItem>
                            <SelectItem value="medium">Media</SelectItem>
                            <SelectItem value="high">Alta</SelectItem>
                            <SelectItem value="urgent">Urgente</SelectItem>
                          </SelectContent>
                        </Select>
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              {/* System Settings */}
              <div>
                <h3 className="text-sm sm:text-base font-semibold mb-2 sm:mb-3">
                  Sistema
                </h3>
                <div className="space-y-2">
                  {systemSettings.map((setting) => (
                    <div
                      className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2 p-2.5 sm:p-3 border border-border rounded-lg overflow-hidden"
                      key={setting.id}
                    >
                      <div className="flex items-center gap-2 min-w-0 flex-1">
                        <Label className="font-medium text-xs sm:text-sm truncate">
                          {NOTIFICATION_TYPE_LABELS[
                            setting.notification_type
                          ] || setting.notification_type}
                        </Label>
                        {setting.enabled ? (
                          <CheckCircle className="h-3.5 w-3.5 text-green-500 shrink-0" />
                        ) : (
                          <XCircle className="h-3.5 w-3.5 text-epoch-primary/40 shrink-0" />
                        )}
                      </div>
                      <div className="flex items-center gap-2 sm:gap-3 shrink-0">
                        <Switch
                          checked={setting.enabled}
                          className="scale-90 sm:scale-100"
                          onCheckedChange={(checked) =>
                            updateSetting(
                              setting.notification_type,
                              "enabled",
                              checked,
                            )
                          }
                        />
                        <Select
                          value={setting.priority || "medium"}
                          onValueChange={(value) =>
                            updateSetting(
                              setting.notification_type,
                              "priority",
                              value,
                            )
                          }
                        >
                          <SelectTrigger className="h-8 w-24 sm:w-28 rounded-lg text-xs">
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="low">Baja</SelectItem>
                            <SelectItem value="medium">Media</SelectItem>
                            <SelectItem value="high">Alta</SelectItem>
                            <SelectItem value="urgent">Urgente</SelectItem>
                          </SelectContent>
                        </Select>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { Package, ShoppingBag } from "lucide-react";
import Link from "next/link";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import type { Customer } from "@/lib/api/services";
import { formatCurrency } from "@/lib/utils";

interface OrdersHistoryCardProps {
  customer: Customer;
  expandedOrders: Set<string>;
  toggleOrderExpansion: (orderId: string) => void;
}

function getOrderStatusBadge(status: string) {
  type BadgeVariant =
    | "default"
    | "secondary"
    | "outline"
    | "destructive"
    | "healty"
    | null
    | undefined;
  const config: Record<string, { variant: BadgeVariant; label: string }> = {
    pending: { variant: "outline", label: "Pendiente" },
    processing: { variant: "secondary", label: "Procesando" },
    shipped: { variant: "default", label: "Enviado" },
    delivered: { variant: "default", label: "Entregado" },
    cancelled: { variant: "destructive", label: "Cancelado" },
    refunded: { variant: "destructive", label: "Reembolsado" },
  };

  const statusConfig = config[status] || {
    variant: "outline",
    label: status,
  };
  return <Badge variant={statusConfig.variant}>{statusConfig.label}</Badge>;
}

export function OrdersHistoryCard({
  customer,
  expandedOrders,
  toggleOrderExpansion,
}: OrdersHistoryCardProps) {
  return (
    <>
      {/* Lens Purchases Section */}
      <Card className="bg-admin-bg-tertiary shadow-[0_1px_3px_rgba(0,0,0,0.3)]">
        <CardHeader className="p-4 sm:p-6">
          <CardTitle className="flex items-center text-admin-text-primary">
            <ShoppingBag className="h-5 w-5 mr-2" />
            Lentes y Armazones ({customer.lensPurchases?.length || 0})
          </CardTitle>
        </CardHeader>
        <CardContent className="p-4 sm:p-6 pt-0">
          {customer.lensPurchases && customer.lensPurchases.length > 0 ? (
            <div className="space-y-4">
              {customer.lensPurchases.map((purchase) => {
                const statusColors: Record<string, string> = {
                  ordered: "bg-blue-100 text-blue-800",
                  in_progress: "bg-yellow-100 text-yellow-800",
                  ready: "bg-green-100 text-green-800",
                  delivered: "bg-gray-100 text-gray-800",
                  cancelled: "bg-red-100 text-red-800",
                };

                return (
                  <Card
                    className="bg-admin-bg-primary border border-admin-border-primary/20 shadow-sm"
                    key={purchase.id}
                  >
                    <CardHeader className="p-4 sm:p-6">
                      <div className="flex flex-col sm:flex-row sm:justify-between sm:items-start gap-4">
                        <div className="min-w-0">
                          <CardTitle className="text-base sm:text-lg text-admin-text-primary">
                            {purchase.product_name}
                          </CardTitle>
                          <p className="text-sm text-admin-text-tertiary mt-1">
                            Fecha de compra:{" "}
                            {new Date(
                              purchase.purchase_date,
                            ).toLocaleDateString("es-CL")}
                            {purchase.delivery_date && (
                              <>
                                {" "}
                                • Entregado:{" "}
                                {new Date(
                                  purchase.delivery_date,
                                ).toLocaleDateString("es-CL")}
                              </>
                            )}
                          </p>
                        </div>
                        <Badge
                          className={
                            statusColors[purchase.status] ||
                            "bg-gray-100 text-gray-800"
                          }
                        >
                          {purchase.status === "ordered" && "Ordenado"}
                          {purchase.status === "in_progress" && "En Proceso"}
                          {purchase.status === "ready" && "Listo"}
                          {purchase.status === "delivered" && "Entregado"}
                          {purchase.status === "cancelled" && "Cancelado"}
                        </Badge>
                      </div>
                    </CardHeader>
                    <CardContent className="p-4 sm:p-6 pt-0">
                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 sm:gap-6">
                        <div>
                          <p className="text-sm text-admin-text-tertiary mb-2">
                            Detalles del Producto
                          </p>
                          <div className="space-y-1 text-sm">
                            <p>
                              <span className="text-admin-text-tertiary">
                                Tipo:
                              </span>{" "}
                              <span className="font-medium">
                                {purchase.product_type}
                              </span>
                            </p>
                            <p>
                              <span className="text-admin-text-tertiary">
                                Cantidad:
                              </span>{" "}
                              <span className="font-medium">
                                {purchase.quantity}
                              </span>
                            </p>
                            {purchase.lens_type && (
                              <p>
                                <span className="text-admin-text-tertiary">
                                  Tipo de lente:
                                </span>{" "}
                                <span className="font-medium">
                                  {purchase.lens_type}
                                </span>
                              </p>
                            )}
                            {purchase.frame_brand && (
                              <p>
                                <span className="text-admin-text-tertiary">
                                  Marca:
                                </span>{" "}
                                <span className="font-medium">
                                  {purchase.frame_brand}
                                </span>
                              </p>
                            )}
                          </div>
                        </div>
                        <div>
                          <p className="text-sm text-admin-text-tertiary mb-2">
                            Información de Compra
                          </p>
                          <div className="space-y-1 text-sm">
                            <p>
                              <span className="text-admin-text-tertiary">
                                Precio unitario:
                              </span>{" "}
                              <span className="font-medium">
                                {formatCurrency(purchase.unit_price ?? 0)}
                              </span>
                            </p>
                            <p>
                              <span className="text-admin-text-tertiary">
                                Total:
                              </span>{" "}
                              <span className="font-medium text-admin-success">
                                {formatCurrency(
                                  purchase.total_price ?? purchase.total_amount,
                                )}
                              </span>
                            </p>
                            {purchase.prescription_id && (
                              <p className="text-xs text-admin-text-tertiary">
                                Con receta asociada
                              </p>
                            )}
                          </div>
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                );
              })}
            </div>
          ) : (
            <div className="text-center py-8">
              <ShoppingBag className="h-10 w-10 text-admin-text-tertiary mx-auto mb-3 opacity-50" />
              <p className="text-sm text-admin-text-tertiary">
                Sin compras de lentes o armazones
              </p>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Orders Section */}
      <Card className="bg-admin-bg-tertiary shadow-[0_1px_3px_rgba(0,0,0,0.3)]">
        <CardHeader className="p-4 sm:p-6">
          <CardTitle className="flex items-center text-admin-text-primary">
            <Package className="h-5 w-5 mr-2" />
            Pedidos ({customer.orders?.length || 0})
          </CardTitle>
        </CardHeader>
        <CardContent className="p-4 sm:p-6 pt-0">
          {customer.orders && customer.orders.length > 0 ? (
            <div className="overflow-x-auto -mx-4 px-4 md:mx-0 md:px-0">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Pedido</TableHead>
                    <TableHead>Fecha</TableHead>
                    <TableHead>Estado</TableHead>
                    <TableHead>Pago</TableHead>
                    <TableHead>Total</TableHead>
                    <TableHead>Acciones</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {customer.orders.map((order: unknown) => {
                    const o = order as Record<string, unknown>;
                    const orderItems = o.order_items as unknown[] | undefined;
                    return (
                      <>
                        <TableRow
                          className="hover:bg-[#AE000010]"
                          key={o.id as string}
                        >
                          <TableCell>
                            <div className="flex items-center space-x-2">
                              <Button
                                className="min-h-[44px] min-w-[44px] p-0"
                                size="sm"
                                variant="ghost"
                                onClick={() =>
                                  toggleOrderExpansion(o.id as string)
                                }
                              >
                                {expandedOrders.has(o.id as string) ? "−" : "+"}
                              </Button>
                              <div>
                                <p className="font-medium">
                                  #{o.order_number as string}
                                </p>
                                <p className="text-sm text-admin-text-tertiary">
                                  {orderItems?.length || 0} productos
                                </p>
                              </div>
                            </div>
                          </TableCell>

                          <TableCell>
                            {new Date(
                              o.created_at as string,
                            ).toLocaleDateString("es-CL", {
                              day: "2-digit",
                              month: "short",
                              year: "numeric",
                            })}
                          </TableCell>

                          <TableCell>
                            {getOrderStatusBadge(o.status as string)}
                          </TableCell>

                          <TableCell>
                            <Badge
                              variant={
                                o.payment_status === "paid"
                                  ? "default"
                                  : "outline"
                              }
                            >
                              {o.payment_status === "paid"
                                ? "Pagado"
                                : o.payment_status === "pending"
                                  ? "Pendiente"
                                  : o.payment_status === "failed"
                                    ? "Fallido"
                                    : (o.payment_status as string)}
                            </Badge>
                          </TableCell>

                          <TableCell className="font-medium text-admin-success">
                            {formatCurrency(o.total_amount as number)}
                          </TableCell>

                          <TableCell>
                            <Link href={`/admin/orders/${o.id as string}`}>
                              <Button size="sm" variant="outline">
                                Ver Detalle
                              </Button>
                            </Link>
                          </TableCell>
                        </TableRow>

                        {/* Expanded Order Items */}
                        {expandedOrders.has(o.id as string) &&
                          orderItems &&
                          orderItems.length > 0 && (
                            <TableRow key={`${o.id as string}-items`}>
                              <TableCell
                                className="bg-admin-bg-tertiary/50 p-4"
                                colSpan={6}
                              >
                                <div className="space-y-2">
                                  <p className="text-xs sm:text-sm font-medium text-admin-text-primary mb-3">
                                    Productos del Pedido:
                                  </p>
                                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                                    {orderItems.map(
                                      (item: unknown, idx: number) => {
                                        const i = item as Record<
                                          string,
                                          unknown
                                        >;
                                        const product =
                                          (i.products as Record<
                                            string,
                                            unknown
                                          >) ||
                                          (i.product as Record<
                                            string,
                                            unknown
                                          >);
                                        return (
                                          <div
                                            className="flex items-center justify-between p-2 bg-admin-bg-primary rounded border border-admin-border-primary/20"
                                            key={idx}
                                          >
                                            <div className="flex items-center space-x-3">
                                              {product?.featured_image ? (
                                                <img
                                                  alt={
                                                    (product?.name as string) ||
                                                    (i.product_name as string)
                                                  }
                                                  className="w-10 h-10 object-cover rounded"
                                                  src={
                                                    product?.featured_image as string
                                                  }
                                                />
                                              ) : (
                                                <div className="w-10 h-10 bg-admin-bg-tertiary rounded flex items-center justify-center shrink-0">
                                                  <Package className="h-5 w-5 text-admin-text-tertiary" />
                                                </div>
                                              )}
                                              <div>
                                                <p className="text-sm font-medium">
                                                  {(product?.name as string) ||
                                                    (i.product_name as string) ||
                                                    "Producto"}
                                                </p>
                                                <p className="text-xs text-admin-text-tertiary">
                                                  Cantidad:{" "}
                                                  {i.quantity as number} ×{" "}
                                                  {formatCurrency(
                                                    i.unit_price as number,
                                                  )}
                                                </p>
                                              </div>
                                            </div>
                                            <p className="text-sm font-medium text-admin-success">
                                              {formatCurrency(
                                                i.total_price as number,
                                              )}
                                            </p>
                                          </div>
                                        );
                                      },
                                    )}
                                  </div>
                                </div>
                              </TableCell>
                            </TableRow>
                          )}
                      </>
                    );
                  })}
                </TableBody>
              </Table>
            </div>
          ) : (
            <div className="text-center py-8">
              <Package className="h-10 w-10 text-admin-text-tertiary mx-auto mb-3 opacity-50" />
              <p className="text-sm text-admin-text-tertiary">
                Sin pedidos registrados
              </p>
            </div>
          )}
        </CardContent>
      </Card>
    </>
  );
}

"use client";

import React, { forwardRef } from "react";

import { formatCurrency, formatDate } from "@/lib/utils";

interface POSReceiptProps {
  order: unknown;
  settings: unknown;
  branch: unknown;
  organization: unknown;
  receiptType?: "sale" | "payment";
}

export const POSReceipt = forwardRef<HTMLDivElement, POSReceiptProps>(
  ({ order, settings, branch, organization, receiptType = "sale" }, ref) => {
    if (!order) return null;

    const isThermal = settings?.printer_type === "thermal";
    const width = settings?.printer_width_mm
      ? `${settings.printer_width_mm}mm`
      : isThermal
        ? "80mm"
        : "210mm";

    return (
      <div
        className="bg-white text-black p-4 font-mono text-[12px] leading-tight"
        id="pos-receipt-print"
        ref={ref}
        style={{ width: isThermal ? width : "100%", maxWidth: "100%" }}
      >
        {/* Header Section - Config from /admin/system Boletas y Facturas */}
        {settings?.header_text && (
          <div className="text-center mb-4 text-xs border-b border-black pb-2">
            {settings.header_text}
          </div>
        )}
        <div className="text-center mb-6">
          {settings?.logo_url && (
            <div className="flex justify-center mb-4">
              <img
                alt="Logo"
                className="h-16 w-auto object-contain"
                src={settings.logo_url}
              />
            </div>
          )}
          <h1 className="text-lg font-bold uppercase">
            {settings?.business_name || organization?.name || "Opttius"}
          </h1>
          <p className="text-[10px] mt-1">
            RUT: {settings?.business_rut || organization?.rut || "XX.XXX.XXX-X"}
          </p>
          <p className="text-[10px]">{branch?.name || "Sucursal"}</p>
          <p className="text-[10px]">
            {branch?.address || settings?.business_address}
          </p>
          <p className="text-[10px]">
            {branch?.phone || settings?.business_phone}
          </p>
        </div>

        {/* Info Grid */}
        <div className="border-t border-b border-black py-2 mb-4 space-y-1">
          {receiptType === "payment" && (
            <div className="text-center font-bold text-sm mb-2">
              COMPROBANTE DE PAGO - SALDO PENDIENTE
            </div>
          )}
          <div className="flex justify-between">
            <span className="font-bold">ORDEN:</span>
            <span>#{order.order_number}</span>
          </div>
          {order.sii_invoice_number && (
            <div className="flex justify-between">
              <span className="font-bold">FOLIO:</span>
              <span>{order.sii_invoice_number}</span>
            </div>
          )}
          <div className="flex justify-between">
            <span>FECHA:</span>
            <span>{formatDate(order.created_at || new Date())}</span>
          </div>
          <div className="flex justify-between">
            <span>DOCUMENTO:</span>
            <span className="uppercase">
              {order.sii_invoice_type && order.sii_invoice_type !== "none"
                ? order.sii_invoice_type
                : "Venta Interna"}
            </span>
          </div>
        </div>

        {/* Customer Section */}
        {(order.customer_name ||
          order.billing_first_name ||
          order.customer_rut ||
          order.sii_rut) && (
          <div className="mb-4 text-[11px]">
            <p className="font-bold border-b border-gray-200 mb-1">CLIENTE:</p>
            {order.customer_name ? (
              <p>{order.customer_name}</p>
            ) : order.billing_first_name ? (
              <p>
                {order.billing_first_name} {order.billing_last_name}
              </p>
            ) : null}
            {(order.customer_rut || order.sii_rut) && (
              <p>RUT: {order.customer_rut || order.sii_rut}</p>
            )}
          </div>
        )}

        {/* Items Table */}
        <table className="w-full mb-4 text-[11px]">
          <thead className="border-b border-black">
            <tr>
              <th className="text-left py-1">DETALLE</th>
              <th className="text-right py-1">TOTAL</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
            {(
              order.order_items ||
              order.items ||
              order.order?.order_items ||
              []
            )?.map((item: unknown, idx: number) => (
              <tr key={idx}>
                <td className="py-2">
                  <div className="font-bold">{item.product_name}</div>
                  <div className="text-[10px]">
                    {item.quantity} x {formatCurrency(item.unit_price)}
                  </div>
                </td>
                <td className="text-right py-2 align-top">
                  {formatCurrency(item.total_price)}
                </td>
              </tr>
            ))}
          </tbody>
        </table>

        {/* Totals Section */}
        <div className="border-t border-black pt-2 space-y-1 text-[12px]">
          <div className="flex justify-between">
            <span>SUBTOTAL:</span>
            <span>{formatCurrency(order.subtotal || order.total_amount)}</span>
          </div>
          {Number(order.tax_amount) > 0 && (
            <div className="flex justify-between">
              <span>IVA (19%):</span>
              <span>{formatCurrency(order.tax_amount)}</span>
            </div>
          )}
          <div className="flex justify-between text-base font-bold pt-1 border-t border-gray-100">
            <span>TOTAL:</span>
            <span>{formatCurrency(order.total_amount)}</span>
          </div>
        </div>

        {/* Payments Section */}
        <div className="mt-4 pt-2 border-t border-black space-y-1 text-[11px]">
          <p className="font-bold mb-1">PAGOS:</p>
          {order.order_payments && order.order_payments.length > 0 ? (
            order.order_payments.map((payment: unknown, idx: number) => (
              <div className="flex justify-between" key={idx}>
                <span className="capitalize">{payment.payment_method}:</span>
                <span>{formatCurrency(payment.amount)}</span>
              </div>
            ))
          ) : order.payment_method_type ? (
            <div className="flex justify-between">
              <span className="capitalize">{order.payment_method_type}:</span>
              <span>{formatCurrency(order.total_amount)}</span>
            </div>
          ) : (
            <div className="flex justify-between">
              <span>Pago Registrado:</span>
              <span>{formatCurrency(order.total_amount)}</span>
            </div>
          )}

          {order.payment_status === "partial" && (
            <div className="flex justify-between font-bold text-red-600 mt-1 pt-1 border-t border-gray-100">
              <span>SALDO PENDIENTE:</span>
              <span>
                {formatCurrency(
                  Number(order.total_amount) -
                    (order.order_payments?.reduce(
                      (acc: number, p: unknown) => acc + Number(p.amount),
                      0,
                    ) ||
                      Number(order.deposit_amount) ||
                      0),
                )}
              </span>
            </div>
          )}
        </div>

        {/* Footer Section */}
        <div className="mt-8 text-center text-[10px] space-y-2 italic">
          {settings?.footer_text && <p>{settings.footer_text}</p>}
          <p>*** GRACIAS POR SU COMPRA ***</p>
          <p className="not-italic font-bold">WWW.OPTTIUS.COM</p>
        </div>

        {/* Anti-fraud / Cut line for thermal */}
        {isThermal && (
          <div className="mt-10 border-t border-dashed border-gray-300 pt-2 flex justify-center opacity-30">
            <span>- CORTE AQUÍ -</span>
          </div>
        )}
      </div>
    );
  },
);

POSReceipt.displayName = "POSReceipt";

"use client";

import { useEffect, useRef, useState } from "react";
import { toast } from "sonner";

import { appLogger } from '@/lib/logger';

import PaymentGatewayConfig from "./_components/PaymentGatewayConfig";
import PaymentMethodToggle from "./_components/PaymentMethodToggle";
import PaymentTestSection from "./_components/PaymentTestSection";

interface PaymentConfig {
  mercadopago_access_token?: string;
  mercadopago_public_key?: string;
  mercadopago_webhook_secret?: string;
  mercadopago_test_mode?: boolean;
  mercadopago_payment_methods?: string[];
  mercadopago_max_installments?: number;
  mercadopago_auto_return?: boolean;
  mercadopago_binary_mode?: boolean;
}

interface PaymentConfigProps {
  configs: unknown[];
  onUpdate: (configKey: string, value: unknown) => Promise<void>;
}

export default function PaymentConfig({ configs, onUpdate }: PaymentConfigProps) {
  const [loading, setLoading] = useState(false);
  const [testing, setTesting] = useState(false);
  const [showTokens, setShowTokens] = useState<Record<string, boolean>>({});
  const [webhookUrl, setWebhookUrl] = useState("");
  const [connectionStatus, setConnectionStatus] = useState<{
    status: "idle" | "success" | "error";
    message?: string;
  }>({ status: "idle" });
  const [credentialValues, setCredentialValues] = useState<Record<string, string>>({});
  const debounceTimers = useRef<Record<string, NodeJS.Timeout>>({});

  // Build config map from props
  const configMap: PaymentConfig = {};
  configs.forEach((config) => {
    const configRecord = config as Record<string, unknown>;
    const key = (configRecord.config_key as string).replace("mercadopago_", "");
    (configMap as Record<string, unknown>)[key] = configRecord.config_value;
  });

  useEffect(() => {
    const baseUrl =
      process.env.NEXT_PUBLIC_SITE_URL ||
      process.env.NEXT_PUBLIC_APP_URL ||
      (typeof window !== "undefined" ? window.location.origin : "") ||
      "https://opttius.com";
    setWebhookUrl(`${baseUrl}/api/webhooks/mercadopago`);
  }, []);

  // Initialize credential values from configs
  useEffect(() => {
    const initialValues: Record<string, string> = {};
    ["access_token", "public_key", "webhook_secret"].forEach((key) => {
      const config = configs.find(
        (c) => (c as Record<string, unknown>).config_key === `mercadopago_${key}`,
      );
      const value = (config as Record<string, unknown> | undefined)?.config_value as string | undefined;
      if (value) initialValues[key] = value;
    });
    ["test_access_token", "test_public_key", "test_webhook_secret"].forEach((key) => {
      const config = configs.find(
        (c) => (c as Record<string, unknown>).config_key === `mercadopago_${key}`,
      );
      const value = (config as Record<string, unknown> | undefined)?.config_value as string | undefined;
      if (value) initialValues[key] = value;
    });
    setCredentialValues((prev) => ({ ...prev, ...initialValues }));
  }, [configs]);

  const handleToggleVisibility = (key: string) => {
    setShowTokens((prev) => ({ ...prev, [key]: !prev[key] }));
  };

  const handleCopyWebhookUrl = () => {
    navigator.clipboard.writeText(webhookUrl);
    toast.success("URL del webhook copiada al portapapeles");
  };

  const handleTestConnection = async () => {
    try {
      setTesting(true);
      setConnectionStatus({ status: "idle" });

      const response = await fetch("/api/admin/system/payments/test", {
        method: "POST",
      });

      const data = await response.json();

      if (data.success) {
        setConnectionStatus({
          status: "success",
          message: data.message || "Conexión exitosa",
        });
        toast.success("Conexión con MercadoPago exitosa");
      } else {
        setConnectionStatus({
          status: "error",
          message: data.message || data.error || "Error al conectar",
        });
        toast.error(data.message || data.error || "Error al conectar con MercadoPago");
      }
    } catch (error) {
      appLogger.error("Error testing connection:", error);
      setConnectionStatus({ status: "error", message: "Error al probar la conexión" });
      toast.error("Error al probar la conexión");
    } finally {
      setTesting(false);
    }
  };

  const getConfigValue = (key: string): unknown => {
    const config = configs.find(
      (c) => (c as Record<string, unknown>).config_key === `mercadopago_${key}`,
    );
    return (config as Record<string, unknown> | undefined)?.config_value;
  };

  const handleUpdate = async (key: string, value: unknown) => {
    try {
      setLoading(true);
      await onUpdate(`mercadopago_${key}`, value);
    } catch (error) {
      appLogger.error("Error updating config:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleCredentialChange = (key: string, value: string) => {
    setCredentialValues((prev) => ({ ...prev, [key]: value }));

    if (debounceTimers.current[key]) {
      clearTimeout(debounceTimers.current[key]);
    }
    debounceTimers.current[key] = setTimeout(() => {
      handleUpdate(key, value);
      delete debounceTimers.current[key];
    }, 800);
  };

  const handleCredentialBlur = (key: string) => {
    if (debounceTimers.current[key]) {
      clearTimeout(debounceTimers.current[key]);
      delete debounceTimers.current[key];
    }
    const currentValue = credentialValues[key];
    if (currentValue !== undefined) {
      handleUpdate(key, currentValue);
    }
  };

  useEffect(() => {
    return () => {
      Object.values(debounceTimers.current).forEach((timer) => clearTimeout(timer));
    };
  }, []);

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-bold text-azul-profundo">Configuración de Pagos</h2>
        <p className="text-tierra-media">Gestiona la configuración de pagos con MercadoPago</p>
      </div>

      <PaymentGatewayConfig
        configs={configs}
        connectionStatus={connectionStatus}
        credentialValues={credentialValues}
        getConfigValue={getConfigValue}
        handleCredentialBlur={handleCredentialBlur}
        handleCredentialChange={handleCredentialChange}
        handleTestConnection={handleTestConnection}
        handleToggleVisibility={handleToggleVisibility}
        handleUpdate={handleUpdate}
        loading={loading}
        showTokens={showTokens}
        testing={testing}
      />

      <PaymentMethodToggle
        getConfigValue={getConfigValue}
        handleUpdate={handleUpdate}
        loading={loading}
      />

      <PaymentTestSection
        handleCopyWebhookUrl={handleCopyWebhookUrl}
        webhookUrl={webhookUrl}
      />
    </div>
  );
}

"use client";

import { Save, Shield, X } from "lucide-react";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { ACTION_LABELS, PERMISSION_RESOURCES } from "@/lib/admin/permissions";
import { appLogger } from '@/lib/logger';

interface Permissions {
  [resource: string]: string[];
}

interface PermissionsEditorProps {
  userId: string;
  currentPermissions: Permissions;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSave: () => void;
}

export default function PermissionsEditor({
  userId,
  currentPermissions,
  open,
  onOpenChange,
  onSave,
}: PermissionsEditorProps) {
  const [permissions, setPermissions] = useState<Permissions>({});
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (open) {
      setPermissions(currentPermissions || {});
    }
  }, [open, currentPermissions]);

  const hasPermission = (resource: string, action: string): boolean => {
    return permissions[resource]?.includes(action) || false;
  };

  const togglePermission = (resource: string, action: string) => {
    setPermissions((prev) => {
      const resourcePerms = prev[resource] || [];
      const hasAction = resourcePerms.includes(action);

      return {
        ...prev,
        [resource]: hasAction
          ? resourcePerms.filter((a) => a !== action)
          : [...resourcePerms, action],
      };
    });
  };

  const toggleAllForResource = (
    resource: string,
    actions: readonly string[],
  ) => {
    const allSelected = actions.every((action) =>
      hasPermission(resource, action),
    );

    setPermissions((prev) => ({
      ...prev,
      [resource]: allSelected ? [] : [...actions],
    }));
  };

  const handleSave = async () => {
    try {
      setLoading(true);

      const response = await fetch(`/api/admin/admin-users/${userId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ permissions }),
      });

      if (!response.ok) {
        const data = await response.json();
        throw new Error(data.error || "Error al actualizar permisos");
      }

      toast.success("Permisos actualizados exitosamente");
      onSave();
      onOpenChange(false);
    } catch (error) {
      appLogger.error("Error saving permissions:", error);
      toast.error(
        error instanceof Error ? error.message : "Error al guardar permisos",
      );
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-[calc(100vw-2rem)] sm:max-w-3xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Shield className="h-5 w-5" />
            Editar Permisos
          </DialogTitle>
          <DialogDescription>
            Configura los permisos específicos para este usuario administrador
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-6 py-4">
          {PERMISSION_RESOURCES.map((resource) => {
            const resourcePerms = permissions[resource.key] || [];
            const allSelected = resource.actions.every((action) =>
              hasPermission(resource.key, action),
            );
            const someSelected = resource.actions.some((action) =>
              hasPermission(resource.key, action),
            );

            return (
              <div
                className="border rounded-lg p-4 space-y-3"
                key={resource.key}
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <Label className="font-semibold text-base">
                      {resource.label}
                    </Label>
                    {someSelected && (
                      <Badge className="text-xs" variant="outline">
                        {resourcePerms.length}{" "}
                        {resourcePerms.length === 1 ? "permiso" : "permisos"}
                      </Badge>
                    )}
                  </div>
                  <Button
                    size="sm"
                    type="button"
                    variant="ghost"
                    onClick={() =>
                      toggleAllForResource(resource.key, resource.actions)
                    }
                  >
                    {allSelected ? "Desmarcar todos" : "Marcar todos"}
                  </Button>
                </div>

                <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                  {resource.actions.map((action) => (
                    <div className="flex items-center space-x-2" key={action}>
                      <Checkbox
                        checked={hasPermission(resource.key, action)}
                        id={`${resource.key}-${action}`}
                        onCheckedChange={() =>
                          togglePermission(resource.key, action)
                        }
                      />
                      <Label
                        className="text-sm font-normal cursor-pointer"
                        htmlFor={`${resource.key}-${action}`}
                      >
                        {ACTION_LABELS[action] || action}
                      </Label>
                    </div>
                  ))}
                </div>
              </div>
            );
          })}
        </div>

        <DialogFooter>
          <Button
            disabled={loading}
            type="button"
            variant="outline"
            onClick={() => onOpenChange(false)}
          >
            <X className="h-4 w-4 mr-2" />
            Cancelar
          </Button>
          <Button disabled={loading} onClick={handleSave}>
            <Save className="h-4 w-4 mr-2" />
            {loading ? "Guardando..." : "Guardar Permisos"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

