  subtitle?: React.ReactNode;
  /** Additional badges (e.g. Actual, Activa) */
  badges?: React.ReactNode;
  className?: string;
}

function EyeSection({
  label,
  prefix,
  data,
}: {
  label: string;
  prefix: "od" | "os";
  data: PrescriptionDisplayData;
}) {
  const sphere = prefix === "od" ? data.od_sphere : data.os_sphere;
  const cylinder = prefix === "od" ? data.od_cylinder : data.os_cylinder;
  const axis = prefix === "od" ? data.od_axis : data.os_axis;
  const add = prefix === "od" ? data.od_add : data.os_add;
  const pd = prefix === "od" ? data.od_pd : data.os_pd;
  const nearPd = prefix === "od" ? data.od_near_pd : data.os_near_pd;
  const prism =
    prefix === "od"
      ? (data.od_prism ?? data.prism_od)
      : (data.os_prism ?? data.prism_os);
  const base = prefix === "od" ? data.od_base : data.os_base;

  const fields: Array<{
    label: string;
    value: number | null | undefined;
    format: (v: number) => string;
  }> = [
    {
      label: "Esfera",
      value: sphere,
      format: (v) => `${v > 0 ? "+" : ""}${v} D`,
    },
    {
      label: "Cilindro",
      value: cylinder,
      format: (v) => `${v > 0 ? "+" : ""}${v} D`,
    },
    { label: "Eje", value: axis, format: (v) => `${v}°` },
    { label: "ADD", value: add, format: (v) => `+${v} D` },
    { label: "PD Lejos", value: pd, format: (v) => `${v} mm` },
    { label: "PD Cerca", value: nearPd, format: (v) => `${v} mm` },
    { label: "Prisma", value: prism, format: (v) => `${v}` },
    { label: "Base", value: base, format: (v) => `${v}` },
  ];

  return (
    <div className="space-y-3">
      <h3 className="font-semibold text-admin-text-primary border-b border-admin-border-primary/30 pb-2">
        {label}
      </h3>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
        {fields.map(
          (f) =>
            f.value !== null &&
            f.value !== undefined && (
              <div key={f.label}>
                <p className="text-xs text-admin-text-tertiary">{f.label}</p>
                <p className="font-medium text-admin-text-primary">
                  {f.format(f.value)}
                </p>
              </div>
            ),
        )}
      </div>
    </div>
  );
}

export function PrescriptionFullDisplay({
  prescription,
  compact = false,
  showCard = true,
  title,
  subtitle,
  badges,
  className = "",
}: PrescriptionFullDisplayProps) {
  const content = (
    <div className={compact ? "space-y-2" : "space-y-6"}>
      {(subtitle || badges) && !showCard && (
        <div className="flex flex-wrap items-start justify-between gap-2">
          {subtitle && (
            <p className="text-sm text-admin-text-tertiary">{subtitle}</p>
          )}
          {badges && <div className="flex gap-2">{badges}</div>}
        </div>
      )}

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 sm:gap-6">
        <EyeSection data={prescription} label="Ojo Derecho (OD)" prefix="od" />
        <EyeSection
          data={prescription}
          label="Ojo Izquierdo (OS)"
          prefix="os"
        />
      </div>

      {/* Additional measurements */}
      {(prescription.frame_pd != null ||
        prescription.height_segmentation != null ||
        prescription.pd_distance != null ||
        prescription.pd_near != null ||
        prescription.issued_by) && (
        <div className="pt-4 border-t border-admin-border-primary/30 grid grid-cols-1 md:grid-cols-3 gap-4">
          {prescription.frame_pd != null && (
            <div>
              <p className="text-xs text-admin-text-tertiary">DP del Marco</p>
              <p className="font-medium text-admin-text-primary">
                {prescription.frame_pd} mm
              </p>
            </div>
          )}
          {prescription.height_segmentation != null && (
            <div>
              <p className="text-xs text-admin-text-tertiary">
                Altura de Segmento
              </p>
              <p className="font-medium text-admin-text-primary">
                {prescription.height_segmentation} mm
              </p>
            </div>
          )}
          {prescription.pd_distance != null && (
            <div>
              <p className="text-xs text-admin-text-tertiary">Distancia PD</p>
              <p className="font-medium text-admin-text-primary">
                {prescription.pd_distance} mm
              </p>
            </div>
          )}
          {prescription.pd_near != null && (
            <div>
              <p className="text-xs text-admin-text-tertiary">PD Cerca</p>
              <p className="font-medium text-admin-text-primary">
                {prescription.pd_near} mm
              </p>
            </div>
          )}
          {prescription.issued_by && (
            <div>
              <p className="text-xs text-admin-text-tertiary">Prescrito por</p>
              <p className="font-medium text-admin-text-primary">
                {prescription.issued_by}
                {prescription.issued_by_license &&
                  ` (${prescription.issued_by_license})`}
              </p>
            </div>
          )}
        </div>
      )}

      {prescription.notes && (
        <div className="pt-4 border-t border-admin-border-primary/30">
          <p className="text-xs text-admin-text-tertiary">Notas de la Receta</p>
          <p className="font-medium whitespace-pre-wrap text-sm text-admin-text-primary mt-1">
            {prescription.notes}
          </p>
        </div>
      )}
    </div>
  );

  if (showCard) {
    return (
      <Card
        className={`bg-admin-bg-tertiary shadow-soft border border-admin-border-primary/20 ${className}`}
      >
        <CardHeader>
          <div className="flex flex-wrap items-start justify-between gap-2">
            <CardTitle className="flex items-center gap-2">
              <Eye className="h-5 w-5 text-admin-accent-primary" />
              {title ?? "Detalles de la Receta"}
            </CardTitle>
            {badges && <div className="flex gap-2">{badges}</div>}
          </div>
          {subtitle && (
            <p className="text-sm text-admin-text-tertiary mt-1">{subtitle}</p>
          )}
        </CardHeader>
        <CardContent>{content}</CardContent>
      </Card>
    );
  }

  return <div className={className}>{content}</div>;
}

"use client";

import {
  ArrowLeft,
  Calculator,
  CheckCircle,
  Clock,
  Eye,
  FileText,
  Loader2,
  Printer,
  RefreshCw,
  Send,
  XCircle,
} from "lucide-react";
import Link from "next/link";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import type { Quote } from "@/hooks/useQuote";

interface QuoteActionsCardProps {
  quote: Quote;
  loadingToPos: boolean;
  sending: boolean;
  showSendDialog: boolean;
  sendEmail: string;
  onLoadToPOS: () => void;
  onPrint: () => void;
  onSendQuote: () => void;
  onShowSendDialog: (open: boolean) => void;
  onSendEmailChange: (email: string) => void;
  onBack: () => void;
}

function StatusBadge({ status }: { status: string }) {
  const config: Record<
    string,
    { variant: unknown; label: string; icon: unknown }
  > = {
    draft: { variant: "outline", label: "Borrador", icon: FileText },
    sent: { variant: "secondary", label: "Enviado", icon: Send },
    accepted: { variant: "default", label: "Aceptado", icon: CheckCircle },
    rejected: { variant: "destructive", label: "Rechazado", icon: XCircle },
    expired: { variant: "outline", label: "Expirado", icon: Clock },
    converted_to_work: {
      variant: "default",
      label: "Convertido",
      icon: RefreshCw,
    },
  };

  const statusConfig = config[status] || {
    variant: "outline",
    label: status,
    icon: FileText,
  };
  const Icon = statusConfig.icon as React.ComponentType<{ className?: string }>;

  return (
    <Badge
      className="flex items-center gap-1"
      variant={
        statusConfig.variant as
          | "outline"
          | "default"
          | "secondary"
          | "destructive"
      }
    >
      <Icon className="h-3 w-3" />
      {statusConfig.label}
    </Badge>
  );
}

export function QuoteActionsCard({
  quote,
  loadingToPos,
  sending,
  showSendDialog,
  sendEmail,
  onLoadToPOS,
  onPrint,
  onSendQuote,
  onShowSendDialog,
  onSendEmailChange,
  onBack,
}: QuoteActionsCardProps) {
  const customerName =
    quote.customer?.first_name && quote.customer?.last_name
      ? `${quote.customer.first_name} ${quote.customer.last_name}`
      : "Sin nombre";

  return (
    <>
      {/* Header - multi-row */}
      <div className="flex flex-col gap-2 sm:gap-3">
        <div className="flex items-center gap-2">
          <Button
            aria-label="Volver"
            className="h-9 w-9 shrink-0"
            size="icon"
            variant="outline"
            onClick={onBack}
          >
            <ArrowLeft className="h-4 w-4" />
          </Button>
          <h1 className="text-xl sm:text-2xl lg:text-3xl font-bold text-epoch-primary truncate min-w-0">
            {quote.quote_number}
          </h1>
        </div>
        <p className="text-xs sm:text-sm text-admin-text-tertiary">
          Presupuesto para {customerName}
        </p>
        <div className="flex flex-wrap items-center gap-2">
          <StatusBadge status={quote.status} />
          {!quote.converted_to_work_order_id && (
            <Button
              className="h-9 gap-1.5"
              disabled={loadingToPos}
              size="sm"
              onClick={onLoadToPOS}
            >
              {loadingToPos ? (
                <>
                  <RefreshCw className="h-4 w-4 animate-spin shrink-0" />
                  <span className="text-xs sm:text-sm">Cargando...</span>
                </>
              ) : (
                <>
                  <Calculator className="h-4 w-4 shrink-0" />
                  <span className="text-xs sm:text-sm">Cargar al POS</span>
                </>
              )}
            </Button>
          )}
          {quote.converted_to_work_order_id && (
            <Link
              href={`/admin/work-orders/${quote.converted_to_work_order_id}`}
            >
              <Button className="h-9" size="sm" variant="outline">
                <Eye className="h-4 w-4 sm:mr-2 shrink-0" />
                <span className="hidden sm:inline">Ver Trabajo</span>
              </Button>
            </Link>
          )}
          <Button
            aria-label="Enviar presupuesto"
            className="h-9 w-9 sm:w-auto sm:px-3"
            size="sm"
            variant="outline"
            onClick={() => onShowSendDialog(true)}
          >
            <Send className="h-4 w-4 sm:mr-2 shrink-0" />
            <span className="hidden sm:inline">Enviar Presupuesto</span>
          </Button>
          <Button
            aria-label="Imprimir"
            className="h-9 w-9 sm:w-auto sm:px-3"
            size="sm"
            variant="outline"
            onClick={onPrint}
          >
            <Printer className="h-4 w-4 sm:mr-2 shrink-0" />
            <span className="hidden sm:inline">Imprimir</span>
          </Button>
        </div>
      </div>

      {/* Send Quote Dialog */}
      <Dialog open={showSendDialog} onOpenChange={onShowSendDialog}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Enviar Presupuesto por Email</DialogTitle>
            <DialogDescription>
              {quote?.customer?.email
                ? `El presupuesto será enviado al email del cliente: ${quote.customer.email}`
                : "Ingresa el email al cual enviar el presupuesto"}
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            {quote?.customer?.email ? (
              <div className="p-4 bg-blue-50 border border-blue-200 rounded-lg">
                <Label className="text-sm font-medium text-blue-900">
                  Email del Cliente
                </Label>
                <p className="text-sm text-blue-700 mt-1">
                  {quote.customer.email}
                </p>
                <p className="text-xs text-blue-600 mt-2">
                  El presupuesto se enviará a este email. Si deseas enviarlo a
                  otro email, puedes cambiarlo abajo.
                </p>
              </div>
            ) : (
              <div className="p-4 bg-yellow-50 border border-yellow-200 rounded-lg">
                <p className="text-sm text-yellow-800">
                  El cliente no tiene un email asignado. Por favor, ingresa el
                  email de destino.
                </p>
              </div>
            )}
            <div>
              <Label htmlFor="email">Email de Destino</Label>
              <Input
                className="mt-1"
                id="email"
                placeholder="cliente@ejemplo.com"
                type="email"
                value={sendEmail}
                onChange={(e) => onSendEmailChange(e.target.value)}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => onShowSendDialog(false)}>
              Cancelar
            </Button>
            <Button disabled={sending || !sendEmail} onClick={onSendQuote}>
              {sending ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  Enviando...
                </>
              ) : (
                <>
                  <Send className="h-4 w-4 mr-2" />
                  Enviar
                </>
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

"use client";

