          <p className="text-2xl sm:text-3xl font-black text-slate-900 dark:text-white uppercase tracking-tighter text-emerald-600">
            ${Number(tierPrice).toLocaleString()}{" "}
            <span className="text-xs text-slate-400">CLP</span>
