            <Button
              className="w-full sm:w-auto min-h-[44px] h-12 sm:h-14 rounded-xl sm:rounded-2xl border-2 font-bold px-6 sm:px-10 bg-emerald-50/50 dark:bg-emerald-500/5 border-emerald-200/50 dark:border-emerald-500/20 text-emerald-600 dark:text-emerald-500 hover:bg-emerald-100 transition-all"
              disabled={!!actionLoading}
              size="lg"
              variant="outline"
              onClick={onReactivate}
            >
              {actionLoading === "reactivate" ? (
                <Loader2 className="h-5 w-5 animate-spin mr-2 shrink-0" />
              ) : (
                <RefreshCw className="h-5 w-5 mr-2 shrink-0" />
              )}
              Reactivar Suscripción Premium
            </Button>
          )}
        </div>

        {isCancelled && cancelAt && (
          <div className="p-4 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 rounded-2xl sm:rounded-3xl flex items-start gap-3 sm:gap-4 min-w-0">
            <AlertTriangle className="h-5 w-5 sm:h-6 sm:w-6 text-amber-600 shrink-0 mt-0.5" />
            <div className="min-w-0 flex-1">
              <p className="font-bold text-amber-900 dark:text-amber-200 text-sm sm:text-base break-words">
                Suscripción Programada para Cancelación
              </p>
              <p className="text-xs sm:text-sm text-amber-700 dark:text-amber-400 mt-1 break-words">
                Tu acceso premium expirará el{" "}
                <strong>{formatDate(cancelAt)}</strong>.
              </p>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import { ArrowRight, CreditCard, Loader2 } from "lucide-react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { type SubscriptionTier, TIER_LIMITS } from "@/lib/saas/tier-config";

import {
  SubMgmtBillingCard,
  SubMgmtCancelDialog,
  SubMgmtStats,
} from "./SubscriptionManagementExtras";

interface SubscriptionStatusResult {
  status: string;
  isExpired: boolean;
  isTrialExpired: boolean;
  trialEndsAt: string | null;
  currentPeriodStart: string | null;
  currentPeriodEnd: string | null;
  cancelAt: string | null;
  canceledAt: string | null;
  organizationId: string | null;
}

interface CurrentSubscription {
  hasSubscription: boolean;
  currentTier: SubscriptionTier | null;
  subscription: {
    status: string;
    currentPeriodStart: string | null;
    currentPeriodEnd: string | null;
    cancelAt: string | null;
  } | null;
}

const STATUS_LABELS: Record<string, string> = {
  active: "Activa",
  trialing: "Prueba gratuita",
  expired: "Expirada",
  past_due: "Pago pendiente",
  cancelled: "Cancelada",
  incomplete: "Incompleta",
  none: "Sin suscripción",
};

const TIER_LABELS: Record<SubscriptionTier, string> = {
  basic: "Básico",
  pro: "Pro",
  premium: "Premium",
};

export function SubscriptionManagementSection() {
  const router = useRouter();
  const [status, setStatus] = useState<SubscriptionStatusResult | null>(null);
  const [currentSubscription, setCurrentSubscription] =
    useState<CurrentSubscription | null>(null);
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState<string | null>(null);
  const [showCancelConfirm, setShowCancelConfirm] = useState(false);
  const [dbTiers, setDbTiers] = useState<unknown[]>([]);

  const fetchStatus = async () => {
    setLoading(true);
    try {
      const [statusRes, subscriptionRes, tiersRes] = await Promise.all([
        fetch("/api/admin/subscription-status"),
        fetch("/api/checkout/current-subscription", { credentials: "include" }),
        fetch("/api/checkout/tiers"),
      ]);

      const statusData = await statusRes.json();
      const subscriptionData = await subscriptionRes.json();
      const tiersData = await tiersRes.json();

      if (statusRes.ok) {
        setStatus({
          ...statusData,
          trialEndsAt: statusData.trialEndsAt ?? null,
          currentPeriodStart: statusData.currentPeriodStart ?? null,
          currentPeriodEnd: statusData.currentPeriodEnd ?? null,
          cancelAt: statusData.cancelAt ?? null,
          canceledAt: statusData.canceledAt ?? null,
        });
      } else {
        setStatus(null);
      }

      if (subscriptionRes.ok) {
        setCurrentSubscription(subscriptionData);
      }

      if (tiersRes.ok) {
        setDbTiers(tiersData.tiers || []);
      }
    } catch {
      setStatus(null);
      setCurrentSubscription(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchStatus();
  }, []);

  const handleCancel = async () => {
    setActionLoading("cancel");
    try {
      const res = await fetch("/api/admin/subscription/actions", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action: "cancel" }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Error al cancelar");

      toast.success("Suscripción cancelada", {
        description:
          "Mantendrás el acceso premium hasta el final del periodo actual.",
        duration: 5000,
      });

      setShowCancelConfirm(false);
      await fetchStatus();
    } catch (e) {
      toast.error(e instanceof Error ? e.message : "Error al cancelar");
    } finally {
      setActionLoading(null);
    }
  };

  const handleReactivate = async () => {
    setActionLoading("reactivate");
    try {
      const res = await fetch("/api/admin/subscription/actions", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action: "reactivate" }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Error al reactivar");
      toast.success(data.message || "Suscripción reactivada");
      await fetchStatus();
    } catch (e) {
      toast.error(e instanceof Error ? e.message : "Error al reactivar");
    } finally {
      setActionLoading(null);
    }
  };

  if (loading) {
    return (
      <Card>
        <CardContent className="flex items-center justify-center py-12">
          <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
        </CardContent>
      </Card>
    );
  }

  if (!status || !status.organizationId) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <CreditCard className="h-5 w-5" />
            Suscripción
          </CardTitle>
          <CardDescription>Gestiona tu plan y método de pago</CardDescription>
        </CardHeader>
        <CardContent>
          <Alert>
            <AlertDescription>
              No tienes una organización con suscripción asignada. Si acabas de
              registrarte, completa el onboarding para activar tu plan.
            </AlertDescription>
          </Alert>
          <Button asChild className="mt-4">
            <Link href="/onboarding/choice">
              <ArrowRight className="h-4 w-4 mr-2" />
              Ir a configuración
            </Link>
          </Button>
        </CardContent>
      </Card>
    );
  }

  const statusLabel = STATUS_LABELS[status.status] ?? status.status;
  const isActive = status.status === "active" || status.status === "trialing";
  const isCancelled = status.status === "cancelled";
  const currentTier = currentSubscription?.currentTier || "basic";
  const tierPrice =
    (dbTiers as Array<{ name: string; price_monthly?: number }>).find(
      (t) => t.name === currentTier,
    )?.price_monthly ?? TIER_LIMITS[currentTier].price;

  return (
    <div className="space-y-8 min-w-0 w-full overflow-x-hidden">
      <SubMgmtCancelDialog
        actionLoading={actionLoading}
        open={showCancelConfirm}
        onCancel={handleCancel}
        onClose={() => setShowCancelConfirm(false)}
      />

      <SubMgmtStats
        currentTier={currentTier}
        isActive={isActive}
        statusLabel={statusLabel}
        tierPrice={tierPrice}
      />

      <SubMgmtBillingCard
        actionLoading={actionLoading}
        cancelAt={status.cancelAt}
        currentPeriodEnd={status.currentPeriodEnd}
        currentTier={currentTier}
        hasSubscription={currentSubscription?.hasSubscription ?? false}
        isActive={isActive}
        isCancelled={isCancelled}
        orgId={status.organizationId}
        subStatus={currentSubscription?.subscription?.status ?? null}
        onCancelClick={() => setShowCancelConfirm(true)}
        onCheckout={() => router.push("/checkout")}
        onConfigure={() => router.push("/checkout")}
        onReactivate={handleReactivate}
      />
    </div>
  );
}

"use client";

import { Loader2, RefreshCw, Star } from "lucide-react";
import { useEffect, useState } from "react";

import { useSurveyConfig } from "@/app/admin/system/hooks/useSurveyConfig";
import { useSurveyResponses } from "@/app/admin/system/hooks/useSurveyResponses";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Textarea } from "@/components/ui/textarea";

export default function SurveysConfig() {
  const { config, isLoading, updateConfig, isUpdating } = useSurveyConfig();
  const {
    data: responsesData,
    isLoading: responsesLoading,
    refetch,
  } = useSurveyResponses(1, 20);
  const [localEnabled, setLocalEnabled] = useState(false);
  const [localScale, setLocalScale] = useState<"1-5" | "1-10">("1-5");
  const [localQuestion, setLocalQuestion] = useState("");

  useEffect(() => {
    if (config) {
      setLocalEnabled(config.survey_enabled);
      setLocalScale(config.survey_scale_type);
      setLocalQuestion(config.survey_question);
    }
  }, [config]);

  const handleSave = async () => {
    await updateConfig({
      survey_enabled: localEnabled,
      survey_scale_type: localScale,
      survey_question: localQuestion,
    });
  };

  const hasChanges =
    config &&
    (localEnabled !== config.survey_enabled ||
      localScale !== config.survey_scale_type ||
      localQuestion !== config.survey_question);

  if (isLoading || !config) {
    return (
      <div className="flex items-center justify-center p-12">
        <Loader2 className="h-8 w-8 animate-spin text-epoch-primary" />
      </div>
    );
  }

  const responses = responsesData?.responses ?? [];
  const metrics = responsesData?.metrics;
  const pagination = responsesData?.pagination;

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Star className="h-5 w-5" />
            Configuración de encuestas
          </CardTitle>
          <CardDescription>
            Activa las encuestas de satisfacción que se envían cuando un cliente
            recibe sus lentes. El enlace se incluye en el email de entrega
            completada.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          <div className="flex items-center justify-between rounded-lg border p-4">
            <div>
              <Label className="text-base font-medium" htmlFor="survey-enabled">
                Encuestas activas
              </Label>
              <p className="text-sm text-muted-foreground">
                Enviar encuesta por email cuando se marque un trabajo como
                entregado
              </p>
            </div>
            <Switch
              checked={localEnabled}
              id="survey-enabled"
              onCheckedChange={setLocalEnabled}
            />
          </div>

          <div className="space-y-2">
            <Label>Tipo de escala</Label>
            <Select
              value={localScale}
              onValueChange={(v) => setLocalScale(v as "1-5" | "1-10")}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="1-5">1 a 5 estrellas</SelectItem>
                <SelectItem value="1-10">1 a 10</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-2">
            <Label htmlFor="survey-question">
              Pregunta opcional (personalizada)
            </Label>
            <Textarea
              id="survey-question"
              maxLength={500}
              placeholder="¿Cómo calificarías tu experiencia?"
              rows={2}
              value={localQuestion}
              onChange={(e) => setLocalQuestion(e.target.value)}
            />
          </div>

          {hasChanges && (
            <Button disabled={isUpdating} onClick={handleSave}>
              {isUpdating ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  Guardando...
                </>
              ) : (
                "Guardar configuración"
              )}
            </Button>
          )}
        </CardContent>
      </Card>

      <Card>
        <CardHeader className="flex flex-row items-center justify-between">
          <div>
            <CardTitle>Resumen</CardTitle>
            <CardDescription>Respuestas del último mes</CardDescription>
          </div>
          <Button
            disabled={responsesLoading}
            size="sm"
            variant="outline"
            onClick={() => refetch()}
          >
            <RefreshCw
              className={`h-4 w-4 mr-2 ${responsesLoading ? "animate-spin" : ""}`}
            />
            Actualizar
          </Button>
        </CardHeader>
        <CardContent>
          {responsesLoading ? (
            <div className="flex justify-center py-8">
              <Loader2 className="h-6 w-6 animate-spin text-epoch-primary" />
            </div>
          ) : metrics ? (
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4 mb-6">
              <div className="rounded-lg border p-4">
                <p className="text-sm text-muted-foreground">
                  Total respuestas
                </p>
                <p className="text-2xl font-bold">{metrics.total}</p>
              </div>
              <div className="rounded-lg border p-4">
                <p className="text-sm text-muted-foreground">Promedio</p>
                <p className="text-2xl font-bold">
                  {metrics.average.toFixed(1)}
                </p>
              </div>
              <div className="rounded-lg border p-4 col-span-2">
                <p className="text-sm text-muted-foreground mb-2">
                  Distribución
                </p>
                <div className="flex gap-2 flex-wrap">
                  {[1, 2, 3, 4, 5].map((n) => (
                    <Badge className="font-normal" key={n} variant="secondary">
                      {n}★: {metrics.distribution[n] ?? 0}
                    </Badge>
                  ))}
                </div>
              </div>
            </div>
          ) : null}

          <div>
            <h3 className="font-medium mb-3">Respuestas recientes</h3>
            {responses.length === 0 ? (
              <p className="text-sm text-muted-foreground py-4">
                Aún no hay respuestas. Las encuestas se envían cuando marcas un
                trabajo como entregado.
              </p>
            ) : (
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Fecha</TableHead>
                    <TableHead>Cliente</TableHead>
                    <TableHead>OT</TableHead>
                    <TableHead>Puntuación</TableHead>
                    <TableHead>Comentario</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {responses.map((r) => {
                    const wo = r.lab_work_orders;
                    const cust = r.customers;
                    const name = cust
                      ? [cust.first_name, cust.last_name]
                          .filter(Boolean)
                          .join(" ") ||
                        cust.email ||
                        "—"
                      : "—";
                    return (
                      <TableRow key={r.id}>
                        <TableCell className="text-sm text-muted-foreground">
                          {new Date(r.created_at).toLocaleDateString("es-CL", {
                            day: "2-digit",
                            month: "short",
                            year: "numeric",
                          })}
                        </TableCell>
                        <TableCell>{name}</TableCell>
                        <TableCell>{wo?.work_order_number ?? "—"}</TableCell>
                        <TableCell>
                          <span className="flex items-center gap-1">
                            {r.score}
                            <Star className="h-4 w-4 fill-epoch-accent text-epoch-accent" />
                          </span>
                        </TableCell>
                        <TableCell className="max-w-[200px] truncate">
                          {r.comment || "—"}
                        </TableCell>
                      </TableRow>
                    );
                  })}
                </TableBody>
              </Table>
            )}
            {pagination && pagination.total_count > pagination.limit && (
              <p className="text-sm text-muted-foreground mt-2">
                Mostrando {responses.length} de {pagination.total_count}{" "}
                respuestas
              </p>
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { RefreshCw } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";

import { WebhookDetailsDialog } from "./_components/WebhookDetailsDialog";
import { WebhookLogsTable } from "./_components/WebhookLogsTable";
import { WebhookStatusCards } from "./_components/WebhookStatusCards";
import { useWebhookMonitor } from "./_hooks/useWebhookMonitor";

export default function WebhookMonitor() {
  const {
    logs, status, loading, typeFilter, setTypeFilter, statusFilter, setStatusFilter,
    selectedLog, showDetailsDialog, setShowDetailsDialog,
    fetchData, handleCopyUrl, handleTestWebhook, handleViewDetails,
  } = useWebhookMonitor();

  const mpStats = status?.status?.mercadopago || { total: 0, success: 0, failed: 0, last_delivery: null };
  const sanityStats = status?.status?.sanity || { total: 0, success: 0, failed: 0, last_delivery: null };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-azul-profundo">Monitoreo de Webhooks</h2>
          <p className="text-tierra-media">Monitorea el estado y las entregas de webhooks</p>
        </div>
        <Button disabled={loading} variant="outline" onClick={fetchData}>
          <RefreshCw className={`h-4 w-4 mr-2 ${loading ? "animate-spin" : ""}`} />Actualizar
        </Button>
      </div>

      {status?.urls && (
        <WebhookStatusCards
          mercadopagoStats={mpStats} sanityStats={sanityStats} urls={status.urls}
          onCopyUrl={handleCopyUrl} onTestWebhook={handleTestWebhook}
        />
      )}

      <Card className="bg-admin-bg-secondary shadow-[0_1px_3px_rgba(0,0,0,0.3)] hover:shadow-[0_4px_12px_rgba(0,0,0,0.4)]" style={{ backgroundColor: "var(--admin-border-primary)" }}>
        <CardContent className="p-4">
          <div className="flex gap-4 items-center">
            <div>
              <Label>Tipo:</Label>
              <Select value={typeFilter} onValueChange={setTypeFilter}>
                <SelectTrigger className="w-[200px]"><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Todos</SelectItem><SelectItem value="mercadopago">MercadoPago</SelectItem><SelectItem value="sanity">Sanity</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label>Estado:</Label>
              <Select value={statusFilter} onValueChange={setStatusFilter}>
                <SelectTrigger className="w-[200px]"><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Todos</SelectItem><SelectItem value="success">Exitosos</SelectItem>
                  <SelectItem value="failed">Fallidos</SelectItem><SelectItem value="pending">Pendientes</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardContent>
      </Card>

      <WebhookLogsTable loading={loading} logs={logs} onViewDetails={handleViewDetails} />
      <WebhookDetailsDialog log={selectedLog} open={showDetailsDialog} onOpenChange={setShowDetailsDialog} />
    </div>
  );
}

"use client";

import {
  AlertCircle,
  CheckCircle,
  ExternalLink,
  Loader2,
  MessageCircle,
} from "lucide-react";
import { useSearchParams } from "next/navigation";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

interface WhatsAppNumber {
  id: string;
  phone_number_id: string;
  waba_id: string;
  display_phone_number: string | null;
  created_at: string;
}

const OAUTH_SCOPES = "whatsapp_business_management,whatsapp_business_messaging";

export default function WhatsAppSettingsCard() {
  const searchParams = useSearchParams();
  const [status, setStatus] = useState<{
    connected: boolean;
    numbers: WhatsAppNumber[];
  } | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState({
    waba_id: "",
    phone_number_id: "",
    display_phone_number: "",
  });

  useEffect(() => {
    const success = searchParams.get("whatsapp_success");
    const error = searchParams.get("whatsapp_error");
    if (success === "1") {
      toast.success("WhatsApp conectado correctamente con Meta");
    } else if (error) {
      const messages: Record<string, string> = {
        no_code: "No se recibió código de autorización",
        no_org: "No tienes organización asignada",
        config: "Configuración de Meta incompleta (App ID / Secret)",
        token_exchange: "Error al intercambiar código por token",
        me_failed: "Error al obtener datos de Meta",
        no_waba: "No se encontró cuenta de WhatsApp Business",
        no_phones: "No hay números de teléfono en tu cuenta",
        save_failed: "Error al guardar la configuración",
        internal: "Error interno. Intenta de nuevo.",
      };
      toast.error(messages[error] || `Error: ${error}`);
    }
  }, [searchParams]);

  const fetchStatus = async () => {
    try {
      const res = await fetch("/api/admin/whatsapp/status");
      const data = await res.json();
      if (res.ok) setStatus(data);
    } catch {
      toast.error("Error al cargar estado de WhatsApp");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchStatus();
  }, []);

  const handleConnect = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!form.waba_id.trim() || !form.phone_number_id.trim()) {
      toast.error("WABA ID y Phone Number ID son requeridos");
      return;
    }
    setSaving(true);
    try {
      const res = await fetch("/api/admin/whatsapp/connect", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          waba_id: form.waba_id.trim(),
          phone_number_id: form.phone_number_id.trim(),
          display_phone_number: form.display_phone_number.trim() || null,
        }),
      });
      const data = await res.json();
      if (!res.ok) {
        toast.error(data.error || "Error al conectar");
        return;
      }
      toast.success(data.message);
      setForm({ waba_id: "", phone_number_id: "", display_phone_number: "" });
      fetchStatus();
    } catch {
      toast.error("Error al conectar WhatsApp");
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <Card>
        <CardContent className="p-6">
          <div className="flex items-center gap-2 text-admin-text-secondary">
            <Loader2 className="h-4 w-4 animate-spin" />
            Cargando configuración de WhatsApp...
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-4 sm:space-y-6">
      <Card className="rounded-xl border border-border overflow-hidden">
        <CardHeader className="p-4 sm:p-6">
          <CardTitle className="flex items-center gap-2 font-display text-epoch-primary text-base sm:text-lg">
            <MessageCircle className="h-4 w-4 sm:h-5 sm:w-5 shrink-0" />
            WhatsApp Business
          </CardTitle>
          <p className="text-xs sm:text-sm text-epoch-primary/80 mt-1">
            Conecta tu número de WhatsApp para que tus clientes puedan
            escribirte y recibir respuestas del asistente IA.
          </p>
        </CardHeader>
        <CardContent className="space-y-6">
          {status?.connected ? (
            <div className="space-y-4">
              <div className="flex items-center gap-2">
                <Badge className="gap-1" variant="default">
                  <CheckCircle className="h-3 w-3" />
                  Conectado
                </Badge>
              </div>
              {status.numbers.map((n) => (
                <div
                  className="rounded-lg border p-4 bg-admin-surface-secondary"
                  key={n.id}
                >
                  <p className="font-medium">
                    {n.display_phone_number || `ID: ${n.phone_number_id}`}
                  </p>
                  <p className="text-xs text-admin-text-tertiary mt-1">
                    WABA: {n.waba_id} | Phone ID: {n.phone_number_id}
                  </p>
                </div>
              ))}
            </div>
          ) : (
            <div className="flex items-center gap-2">
              <Badge className="gap-1" variant="secondary">
                <AlertCircle className="h-3 w-3" />
                No conectado
              </Badge>
            </div>
          )}

          <div className="space-y-4">
            {process.env.NEXT_PUBLIC_META_APP_ID && (
              <div>
                <Button
                  className="w-full"
                  type="button"
                  variant="outline"
                  onClick={() => {
                    const base =
                      typeof window !== "undefined"
                        ? window.location.origin
                        : "";
                    const callback = `${base}/api/admin/whatsapp/oauth-callback`;
                    const url = `https://www.facebook.com/v18.0/dialog/oauth?client_id=${process.env.NEXT_PUBLIC_META_APP_ID}&redirect_uri=${encodeURIComponent(callback)}&scope=${encodeURIComponent(OAUTH_SCOPES)}&response_type=code`;
                    window.location.href = url;
                  }}
                >
                  <ExternalLink className="h-4 w-4 mr-2" />
                  Conectar con Meta (Embedded Signup)
                </Button>
                <p className="text-xs text-admin-text-tertiary mt-2">
                  Abre el flujo oficial de Meta para conectar tu número.
                </p>
              </div>
            )}
            <div className="relative">
              <div className="absolute inset-0 flex items-center">
                <span className="w-full border-t" />
              </div>
              <div className="relative flex justify-center text-xs uppercase">
                <span className="bg-admin-surface-primary px-2 text-admin-text-tertiary">
                  O ingresa manualmente
                </span>
              </div>
            </div>
            <form className="space-y-4" onSubmit={handleConnect}>
              <div className="space-y-2">
                <Label htmlFor="waba_id">WABA ID (Business Account ID)</Label>
                <Input
                  id="waba_id"
                  placeholder="Ej: 123456789012345"
                  value={form.waba_id}
                  onChange={(e) =>
                    setForm((f) => ({ ...f, waba_id: e.target.value }))
                  }
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="phone_number_id">Phone Number ID</Label>
                <Input
                  id="phone_number_id"
                  placeholder="Ej: 987654321098765"
                  value={form.phone_number_id}
                  onChange={(e) =>
                    setForm((f) => ({ ...f, phone_number_id: e.target.value }))
                  }
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="display_phone_number">
                  Número mostrado (opcional)
                </Label>
                <Input
                  id="display_phone_number"
                  placeholder="+56912345678"
                  value={form.display_phone_number}
                  onChange={(e) =>
                    setForm((f) => ({
                      ...f,
                      display_phone_number: e.target.value,
                    }))
                  }
                />
              </div>
              <Button disabled={saving} type="submit">
                {saving ? (
                  <Loader2 className="h-4 w-4 animate-spin" />
                ) : status?.connected ? (
                  "Actualizar"
                ) : (
                  "Conectar WhatsApp"
                )}
              </Button>
            </form>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="text-base">Instrucciones</CardTitle>
        </CardHeader>
        <CardContent className="text-sm text-admin-text-secondary space-y-3">
          <p>
            <strong>Paso 1:</strong> Crea una app en{" "}
            <a
              className="text-epoch-primary underline"
              href="https://developers.facebook.com/"
              rel="noopener noreferrer"
              target="_blank"
            >
              Meta for Developers
            </a>{" "}
            y añade el producto WhatsApp Cloud API.
          </p>
          <p className="break-words">
            <strong>Paso 2:</strong> Configura el webhook en Meta:{" "}
            <code className="bg-epoch-background/50 px-1 rounded text-[10px] sm:text-xs break-all">
              {typeof window !== "undefined"
                ? `${window.location.origin}/api/webhooks/whatsapp`
                : "/api/webhooks/whatsapp"}
            </code>
          </p>
          <p className="break-words">
            <strong>Paso 3:</strong>{" "}
            {process.env.NEXT_PUBLIC_META_APP_ID
              ? "Usa el botón «Conectar con Meta» para el flujo oficial, o ingresa manualmente el WABA ID y Phone Number ID desde el panel de Meta (WhatsApp &gt; API Setup)."
              : "Obtén el WABA ID y Phone Number ID desde el panel de Meta (WhatsApp &gt; API Setup) e ingrésalos arriba."}
          </p>
          <p className="break-words">
            <strong>Paso 4:</strong> Configura la facturación en tu Business
            Manager de Meta. Meta te cobrará directamente según el volumen de
            mensajes.
          </p>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import {
  AlertCircle,
  CheckCircle,
  FileText,
  Package,
  Send,
  Truck,
  XCircle,
} from "lucide-react";

import { Badge } from "@/components/ui/badge";

const STATUS_CONFIG: Record<
  string,
  { label: string; icon: React.ComponentType<{ className?: string }> }
> = {
  quote: { label: "Presupuesto", icon: FileText },
  ordered: { label: "Ordenado", icon: Package },
  sent_to_lab: { label: "Enviado al Lab", icon: Send },
  received_from_lab: { label: "Recibido", icon: Truck },
