  const Icon = NOTIFICATION_ICONS[notification.type] || Info;
  const isUnread = !notification.is_read;

  return (
    <div
      className={cn(
        "group p-4 transition-all duration-300 cursor-pointer relative",
        isUnread
          ? "bg-admin-accent-primary/[0.03]"
