      <div className="flex gap-4">
        <div
          className={cn(
            "flex-shrink-0 w-11 h-11 rounded-xl flex items-center justify-center shadow-sm transition-transform",
            compact
              ? ""
              : "group-hover:scale-105",
            isUnread
