import { AlertCircle, Calendar as CalendarIcon, Eye, Package, RefreshCw, Truck, User, Wrench } from "lucide-react";

export interface Appointment {
  id: string;
  appointment_date: string;
  appointment_time: string;
  duration_minutes: number;
  appointment_type: string;
  status: string;
  customer?: {
    id: string;
    first_name?: string;
    last_name?: string;
  } | null;
  guest_first_name?: string;
  guest_last_name?: string;
  guest_rut?: string;
  guest_email?: string;
  guest_phone?: string;
  notes?: string;
}

export interface ScheduleSettings {
  slot_duration_minutes: number;
  working_hours: {
    [key: string]: {
      enabled: boolean;
      start_time: string;
      end_time: string;
      lunch_start?: string | null;
      lunch_end?: string | null;
    };
  };
}

export const CUSTOM_SCROLLBAR_CSS =
  ".custom-scrollbar::-webkit-scrollbar{width:6px}.custom-scrollbar::-webkit-scrollbar-track{background:transparent}.custom-scrollbar::-webkit-scrollbar-thumb{background:rgba(148,163,184,0.3);border-radius:10px}.custom-scrollbar::-webkit-scrollbar-thumb:hover{background:rgba(148,163,184,0.5)}";

export function hasAppointments(apts: Appointment[]) {
  return apts.length > 0;
}

export function getAppointmentTypeColor(type: string) {
  const colors: Record<string, string> = {
    eye_exam: "bg-blue-100 border-blue-300 text-blue-800",
    consultation: "bg-green-100 border-green-300 text-green-800",
    fitting: "bg-purple-100 border-purple-300 text-purple-800",
    delivery: "bg-orange-100 border-orange-300 text-orange-800",
    repair: "bg-yellow-100 border-yellow-300 text-yellow-800",
    follow_up: "bg-indigo-100 border-indigo-300 text-indigo-800",
    emergency: "bg-red-100 border-red-300 text-red-800",
    other: "bg-gray-100 border-gray-300 text-gray-800",
  };
  return colors[type] || colors.other;
}

export function getAppointmentStatusColor(status: string) {
  const colors: Record<string, string> = {
    scheduled:
      "bg-admin-info/5 border-admin-info/30 text-admin-info hover:bg-admin-info/10 shadow-premium-sm",
    confirmed:
      "bg-admin-success/5 border-admin-success/30 text-admin-success hover:bg-admin-success/10 shadow-premium-sm",
    completed:
      "bg-admin-accent-secondary/5 border-admin-accent-secondary/30 text-admin-accent-secondary hover:bg-admin-accent-secondary/10 shadow-premium-sm",
    cancelled:
      "bg-admin-error/5 border-admin-error/30 text-admin-error hover:bg-admin-error/10 shadow-premium-sm",
    no_show:
      "bg-admin-bg-tertiary/20 border-admin-border-secondary text-admin-text-tertiary hover:bg-admin-bg-tertiary/40 shadow-premium-sm",
  };
  return colors[status] || colors.scheduled;
}

export function getAppointmentTypeIcon(type: string) {
  const icons: Record<string, typeof Eye> = {
    eye_exam: Eye,
    consultation: User,
    fitting: Package,
    delivery: Truck,
    repair: Wrench,
    follow_up: RefreshCw,
    emergency: AlertCircle,
    other: CalendarIcon,
  };
  return icons[type] || CalendarIcon;
}

export function getAppointmentsForDate(appointments: Appointment[], date: Date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  const dateStr = `${year}-${month}-${day}`;
  return appointments.filter((apt) => apt.appointment_date === dateStr);
}

export function getAppointmentsForTimeSlot(appointments: Appointment[], date: Date, timeSlot: string) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  const dateStr = `${year}-${month}-${day}`;

  return appointments.filter((apt) => {
    if (apt.appointment_date !== dateStr) return false;
    const aptTime = apt.appointment_time.substring(0, 5);
    return (
      aptTime <= timeSlot &&
      parseInt(aptTime.split(":")[0]) * 60 +
        parseInt(aptTime.split(":")[1]) +
        apt.duration_minutes >
        parseInt(timeSlot.split(":")[0]) * 60 +
          parseInt(timeSlot.split(":")[1])
    );
  });
}

export function isToday(date: Date) {
  const today = new Date();
  return date.toDateString() === today.toDateString();
}

export function isPast(date: Date, time?: string) {
  const now = new Date();
  if (time) {
    const timeOnly = time.substring(0, 5);
    const [hours, minutes] = timeOnly.split(":").map(Number);
    const dateTime = new Date(date);
    dateTime.setHours(hours, minutes, 0, 0);
    return dateTime < now;
  }
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const checkDate = new Date(date);
  checkDate.setHours(0, 0, 0, 0);
  return checkDate < today;
}

export function isSlotAvailableForDate(
  date: Date,
  timeSlot: string,
  scheduleSettings?: ScheduleSettings | null,
): boolean {
  if (!scheduleSettings?.working_hours) return true;

  const dayNames = [
    "sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday",
  ];
  const dayIndex = date.getDay();
  const dayName = dayNames[dayIndex];
  const dayConfig = scheduleSettings.working_hours[dayName];

  if (!dayConfig || !dayConfig.enabled) return false;

  const [slotHour, slotMinute] = timeSlot.split(":").map(Number);
  const slotTimeDecimal = slotHour + slotMinute / 60;

  const [startHour, startMinute] = dayConfig.start_time.split(":").map(Number);
  const startTimeDecimal = startHour + startMinute / 60;

  const [endHour, endMinute] = dayConfig.end_time.split(":").map(Number);
  const endTimeDecimal = endHour + endMinute / 60;

  if (slotTimeDecimal < startTimeDecimal || slotTimeDecimal >= endTimeDecimal) return false;

  if (dayConfig.lunch_start && dayConfig.lunch_end) {
    const [lunchStartHour, lunchStartMinute] = dayConfig.lunch_start.split(":").map(Number);
    const lunchStartDecimal = lunchStartHour + lunchStartMinute / 60;

    const [lunchEndHour, lunchEndMinute] = dayConfig.lunch_end.split(":").map(Number);
    const lunchEndDecimal = lunchEndHour + lunchEndMinute / 60;

    if (slotTimeDecimal >= lunchStartDecimal && slotTimeDecimal < lunchEndDecimal) return false;
  }

  return true;
}

export function generateTimeSlots(scheduleSettings?: ScheduleSettings | null): string[] {
  const slots: string[] = [];

  if (!scheduleSettings?.working_hours) {
    for (let hour = 8; hour < 20; hour++) {
      for (let minute = 0; minute < 60; minute += 15) {
        slots.push(
          `${hour.toString().padStart(2, "0")}:${minute.toString().padStart(2, "0")}`,
        );
      }
    }
    return slots;
  }

  const slotDuration = scheduleSettings.slot_duration_minutes || 15;

  let earliestStart = 24;
  let latestEnd = 0;

  Object.values(scheduleSettings.working_hours).forEach((dayConfig) => {
    if (dayConfig.enabled) {
      const startHour = parseInt(dayConfig.start_time.split(":")[0]);
      const endHour = parseInt(dayConfig.end_time.split(":")[0]);
      const endMinute = parseInt(dayConfig.end_time.split(":")[1]);
      const endTimeDecimal = endHour + endMinute / 60;

      if (startHour < earliestStart) earliestStart = startHour;
      if (endTimeDecimal > latestEnd) latestEnd = endTimeDecimal;
    }
  });

  let currentHour = Math.floor(earliestStart);
  let currentMinute = Math.round((earliestStart - currentHour) * 60);
  const endHour = Math.floor(latestEnd);
  const endMinute = Math.round((latestEnd - endHour) * 60);

  while (
    currentHour < endHour ||
    (currentHour === endHour && currentMinute < endMinute)
  ) {
    slots.push(
      `${currentHour.toString().padStart(2, "0")}:${currentMinute.toString().padStart(2, "0")}`,
    );
    currentMinute += slotDuration;
    if (currentMinute >= 60) {
      currentHour += Math.floor(currentMinute / 60);
      currentMinute = currentMinute % 60;
    }
  }

  return slots;
}

export function getWeekDays(currentDate: Date): Date[] {
  const startOfWeek = new Date(currentDate);
  const day = startOfWeek.getDay();
  const diff = startOfWeek.getDate() - day + (day === 0 ? -6 : 1);
  startOfWeek.setDate(diff);

  const days: Date[] = [];
  for (let i = 0; i < 7; i++) {
    const date = new Date(startOfWeek);
    date.setDate(startOfWeek.getDate() + i);
    days.push(date);
  }
  return days;
}

export function getMonthDays(currentDate: Date): Date[] {
  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();
  const firstDay = new Date(year, month, 1);
  const lastDay = new Date(year, month + 1, 0);
  const startDate = new Date(firstDay);
  startDate.setDate(startDate.getDate() - startDate.getDay() + (startDate.getDay() === 0 ? -6 : 1));

  const days: Date[] = [];
  const current = new Date(startDate);
  while (current <= lastDay || days.length < 35) {
    days.push(new Date(current));
    current.setDate(current.getDate() + 1);
    if (days.length >= 42) break;
  }
  return days;
}

"use client";

import { useCallback, useEffect, useState } from "react";
import { toast } from "sonner";

import { appLogger } from '@/lib/logger';

import type { EmailTemplate } from "../_components/EmailTemplatesConstants";

interface UseEmailTemplatesProps {
  mode: "organization" | "saas";
  organizationId?: string;
}

export function useEmailTemplates({ mode, organizationId }: UseEmailTemplatesProps) {
  const [templates, setTemplates] = useState<EmailTemplate[]>([]);
  const [loading, setLoading] = useState(true);
  const [typeFilter, setTypeFilter] = useState("all");
  const [groupFilter, setGroupFilter] = useState("all");
  const [showCreateDialog, setShowCreateDialog] = useState(false);
  const [showEditDialog, setShowEditDialog] = useState(false);
  const [showPreviewDialog, setShowPreviewDialog] = useState(false);
  const [showTestDialog, setShowTestDialog] = useState(false);
  const [showDeleteDialog, setShowDeleteDialog] = useState(false);
  const [templateToDelete, setTemplateToDelete] = useState<EmailTemplate | null>(null);
  const [deleting, setDeleting] = useState(false);
  const [selectedTemplate, setSelectedTemplate] = useState<EmailTemplate | null>(null);
  const [testing, setTesting] = useState<string | null>(null);
  const [createInitialType, setCreateInitialType] = useState<string | undefined>();

  const templatesApiBase = mode === "saas"
    ? "/api/admin/saas-management/email-templates"
    : "/api/admin/system/email-templates";

  const fetchTemplates = useCallback(async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams();
      if (typeFilter !== "all") params.set("type", typeFilter);
      if (mode === "saas") {
        params.set("category", "saas");
        if (groupFilter !== "all") params.set("template_group", groupFilter);
      }
      const apiUrl = mode === "saas"
        ? `/api/admin/saas-management/email-templates?${params}`
        : `/api/admin/system/email-templates?${params}`;
      const response = await fetch(apiUrl);
      if (!response.ok) throw new Error("Failed to fetch templates");
      const data = await response.json();
      setTemplates(data.templates ?? data.data ?? []);
    } catch (error) {
      appLogger.error("Error fetching templates:", error);
      toast.error("Error al cargar plantillas");
    } finally {
      setLoading(false);
    }
  }, [typeFilter, groupFilter, mode]);

  useEffect(() => { fetchTemplates(); }, [fetchTemplates]);

  const handleToggleActive = async (template: EmailTemplate) => {
    try {
      const response = await fetch(`${templatesApiBase}/${template.id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ is_active: !template.is_active }),
      });
      if (!response.ok) {
        const errBody = await response.json().catch(() => ({}));
        throw new Error(errBody?.details ?? errBody?.error ?? response.statusText);
      }
      toast.success(`Plantilla ${!template.is_active ? "activada" : "desactivada"}`);
      fetchTemplates();
    } catch (error) {
      const msg = error instanceof Error ? error.message : "Error al actualizar plantilla";
      appLogger.error("Error updating template:", error);
      toast.error(msg);
    }
  };

  const handleDeleteClick = (template: EmailTemplate) => {
    if (template.is_system) { toast.error("No se pueden eliminar plantillas del sistema"); return; }
    setTemplateToDelete(template);
    setShowDeleteDialog(true);
  };

  const confirmDelete = async () => {
    if (!templateToDelete) return;
    try {
      setDeleting(true);
      const response = await fetch(`${templatesApiBase}/${templateToDelete.id}`, { method: "DELETE" });
      if (!response.ok) throw new Error("Failed to delete template");
      toast.success("Plantilla eliminada");
      setShowDeleteDialog(false);
      setTemplateToDelete(null);
      fetchTemplates();
    } catch (error) {
      appLogger.error("Error deleting template:", error);
      toast.error("Error al eliminar plantilla");
    } finally { setDeleting(false); }
  };

  const handleTestEmail = (template: EmailTemplate) => {
    setSelectedTemplate(template);
    setShowTestDialog(true);
  };

  const confirmTestEmailWith = async (templateId: string, email: string) => {
    try {
      setTesting(templateId);
      const response = await fetch(`${templatesApiBase}/${templateId}/test`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ testEmail: email }),
      });
      const data = await response.json();
      if (data.success) {
        toast.success(data.message || "Email de prueba enviado");
        setShowTestDialog(false);
      } else {
        toast.error(data.error || "Error al enviar email de prueba");
      }
    } catch (error) {
      appLogger.error("Error testing email:", error);
      toast.error("Error al enviar email de prueba");
    } finally { setTesting(null); }
  };

  return {
    templates, loading, typeFilter, setTypeFilter, groupFilter, setGroupFilter,
    showCreateDialog, setShowCreateDialog, showEditDialog, setShowEditDialog,
    showPreviewDialog, setShowPreviewDialog, showTestDialog, setShowTestDialog,
    showDeleteDialog, setShowDeleteDialog, templateToDelete, setTemplateToDelete,
    deleting, selectedTemplate, setSelectedTemplate, testing,
    createInitialType, setCreateInitialType,
    fetchTemplates, handleToggleActive, handleDeleteClick, confirmDelete,
    handleTestEmail, confirmTestEmailWith, templatesApiBase,
  };
}

"use client";

import { useRouter } from "next/navigation";
import { useEffect, useRef, useState } from "react";
import { toast } from "sonner";

import { useAuthContext } from "@/contexts/AuthContext";
import { useBranch } from "@/hooks/useBranch";
import { useRoot } from "@/hooks/useRoot";
import { appLogger } from '@/lib/logger';
import { createClient } from "@/utils/supabase/client";

export interface AdminNotification {
  id: string;
  type: string;
  priority: "low" | "medium" | "high" | "urgent";
  title: string;
  message: string;
  related_entity_type?: string;
  related_entity_id?: string;
  action_url?: string;
  action_label?: string;
  metadata?: unknown;
  is_read: boolean;
  created_at: string;
}

export function useNotificationDropdown() {
  const router = useRouter();
  const { user, loading: authLoading } = useAuthContext();
  const { currentBranchId, isGlobalView } = useBranch();
  const { isRoot } = useRoot();
  const [notifications, setNotifications] = useState<AdminNotification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [loading, setLoading] = useState(false);
  const [isOpen, setIsOpen] = useState(false);
  const intervalRef = useRef<NodeJS.Timeout | null>(null);

  const fetchNotifications = async () => {
    if (!user || authLoading) return;
    try {
      const params = new URLSearchParams({ limit: "10" });
      if (!isRoot && currentBranchId && !isGlobalView) {
        params.set("branch_id", currentBranchId);
      }
      const response = await fetch(`/api/admin/notifications?${params}`, {
        credentials: "include",
      });
      if (!response.ok) {
        if (response.status === 401) return;
        throw new Error("Failed to fetch notifications");
      }
      const data = await response.json();
      setNotifications(data.notifications || []);
      setUnreadCount(data.unreadCount || 0);
    } catch (error) {
      if (error instanceof Error && !error.message.includes("401")) {
        appLogger.error("Error fetching notifications:", error);
      }
    }
  };

  useEffect(() => {
    if (!authLoading && user) {
      fetchNotifications();
      intervalRef.current = setInterval(fetchNotifications, 60000);
      const supabase = createClient();
      const channel = supabase
        .channel("admin-notifications")
        .on(
          "postgres_changes",
          {
            event: "INSERT",
            schema: "public",
            table: "admin_notifications",
            ...(currentBranchId && !isGlobalView && !isRoot
              ? { filter: `branch_id=eq.${currentBranchId}` }
              : {}),
          },
          () => fetchNotifications(),
        )
        .subscribe();
      return () => {
        if (intervalRef.current) clearInterval(intervalRef.current);
        supabase.removeChannel(channel);
      };
    }
  }, [user, authLoading, currentBranchId, isGlobalView, isRoot]);

  const markAsRead = async (notificationId: string, actionUrl?: string) => {
    try {
      const response = await fetch("/api/admin/notifications", {
        credentials: "include",
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ notificationId }),
      });
      if (!response.ok) throw new Error("Failed to mark notification as read");
      setNotifications(
        notifications.map((n) =>
          n.id === notificationId ? { ...n, is_read: true } : n,
        ),
      );
      setUnreadCount(Math.max(0, unreadCount - 1));
      if (actionUrl) {
        setIsOpen(false);
        router.push(actionUrl);
      }
    } catch (error) {
      appLogger.error("Error marking notification as read:", error);
      toast.error("Error al marcar la notificación");
    }
  };

  const markAllAsRead = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/admin/notifications", {
        credentials: "include",
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ markAllRead: true }),
      });
      if (!response.ok) throw new Error("Failed to mark all as read");
      setNotifications(notifications.map((n) => ({ ...n, is_read: true })));
      setUnreadCount(0);
      toast.success("Todas las notificaciones marcadas como leídas");
    } catch (error) {
      appLogger.error("Error marking all as read:", error);
      toast.error("Error al marcar todas como leídas");
    } finally {
      setLoading(false);
    }
  };

  return {
    notifications,
    unreadCount,
    loading,
    isOpen,
    setIsOpen,
    fetchNotifications,
    markAsRead,
    markAllAsRead,
  };
}

"use client";

import { useCallback, useEffect, useState } from "react";
import { toast } from "sonner";

import { appLogger } from '@/lib/logger';


interface NotificationSetting {
  id: string;
  notification_type: string;
  enabled: boolean;
  priority: string | null;
  notify_all_admins: boolean;
  notify_specific_roles: string[] | null;
  organization_id: string | null;
  branch_id: string | null;
  [key: string]: unknown;
}

interface NotificationSettingsProps {
  branchId?: string | null;
  organizationId?: string | null;
}

export function useNotificationSettings({
  branchId,
  organizationId,
}: NotificationSettingsProps) {
  const [settings, setSettings] = useState<NotificationSetting[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [hasChanges, setHasChanges] = useState(false);
  const [tableNotFound, setTableNotFound] = useState(false);
  const [migrationSQL, setMigrationSQL] = useState<string | null>(null);
  const [loadingSQL, setLoadingSQL] = useState(false);

  useEffect(() => {
    fetchSettings();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [branchId, organizationId]);

  const fetchSettings = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams();
      if (organizationId) params.set("organization_id", organizationId);
      if (branchId) params.set("branch_id", branchId);
      const url = `/api/admin/notifications/settings${params.toString() ? `?${params}` : ""}`;
      const response = await fetch(url);
      const data = await response.json();

      if (!response.ok) {
        if (data.message?.includes("does not exist")) {
          setTableNotFound(true);
          toast.error(
            "La tabla de configuración de notificaciones no existe. Por favor, ejecuta la migración de base de datos.",
            { duration: 8000 },
          );
          setSettings([]);
          return;
        }
        throw new Error(data.error || "Error al cargar configuración");
      }
      setTableNotFound(false);
      setSettings(data.settings || []);
      setHasChanges(false);
    } catch (error) {
      appLogger.error("Error fetching notification settings:", error);
      toast.error("Error al cargar la configuración de notificaciones");
      setSettings([]);
    } finally {
      setLoading(false);
    }
  };

  const updateSetting = useCallback(
    (type: string, field: string, value: unknown) => {
      setSettings((prev) => {
        const updated = prev.map((setting) => {
          if (setting.notification_type === type) {
            return { ...setting, [field]: value };
          }
          return setting;
        });
        setHasChanges(true);
        return updated;
      });
    },
    [],
  );

  const saveSettings = async () => {
    try {
      setSaving(true);
      const updates = settings.map((s) => ({
        notification_type: s.notification_type,
        enabled: s.enabled,
        priority: s.priority,
        notify_all_admins: s.notify_all_admins,
        notify_specific_roles: s.notify_specific_roles,
      }));

      const response = await fetch("/api/admin/notifications/settings", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          updates,
          organization_id: organizationId,
          branch_id: branchId,
        }),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || "Error al guardar");
      }

      toast.success("Configuración guardada exitosamente");
      setHasChanges(false);
    } catch (error) {
      appLogger.error("Error saving notification settings:", error);
      toast.error("Error al guardar la configuración de notificaciones");
    } finally {
      setSaving(false);
    }
  };

  const toggleAll = useCallback((enabled: boolean) => {
    setSettings((prev) => prev.map((s) => ({ ...s, enabled })));
    setHasChanges(true);
  }, []);

  const fetchMigrationSQL = async () => {
    try {
      setLoadingSQL(true);
      const response = await fetch("/api/admin/system/migrate-notifications", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ dryRun: true }),
      });
      const data = await response.json();
      if (data.success) {
        setMigrationSQL(data.migrationSQL || data.sql || "No SQL generated");
      }
    } catch (err) {
      appLogger.error("Error fetching migration SQL:", err);
    } finally {
      setLoadingSQL(false);
    }
  };

  const copySQLToClipboard = async () => {
    if (migrationSQL) {
      try {
        await navigator.clipboard.writeText(migrationSQL);
        toast.success("SQL copiado al portapapeles");
      } catch {
        toast.error("Error al copiar SQL");
      }
    }
  };

  return {
    settings,
    loading,
    saving,
    hasChanges,
    tableNotFound,
    migrationSQL,
    loadingSQL,
    fetchMigrationSQL,
    copySQLToClipboard,
    fetchSettings,
    updateSetting,
    saveSettings,
    toggleAll,
    setTableNotFound,
  };
}

"use client";

import { useCallback, useEffect, useState } from "react";
import { toast } from "sonner";

interface WebhookLog {
  id: string; webhook_type: string; event_type: string; status: string;
  response_code: number; error_message?: string; payload?: unknown; created_at: string; processed_at?: string;
}
interface WebhookStats { total: number; success: number; failed: number; last_delivery: string | null; }
interface WebhookStatus {
  status: { mercadopago: WebhookStats; sanity: WebhookStats };
  urls: { mercadopago: string; sanity: string };
}

export function useWebhookMonitor() {
  const [logs, setLogs] = useState<WebhookLog[]>([]);
  const [status, setStatus] = useState<WebhookStatus | null>(null);
  const [loading, setLoading] = useState(true);
  const [typeFilter, setTypeFilter] = useState("all");
  const [statusFilter, setStatusFilter] = useState("all");
  const [selectedLog, setSelectedLog] = useState<WebhookLog | null>(null);
  const [showDetailsDialog, setShowDetailsDialog] = useState(false);

  const fetchData = useCallback(async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams();
      if (typeFilter !== "all") params.set("type", typeFilter);
      if (statusFilter !== "all") params.set("status", statusFilter);
      const [logsRes, statusRes] = await Promise.all([
        fetch(`/api/admin/system/webhooks/logs?${params}`).catch(() => ({ ok: false } as Response)),
        fetch("/api/admin/system/webhooks/status").catch(() => ({ ok: false } as Response)),
      ]);
      if (logsRes.ok) { try { const d = await (logsRes as Response).json(); setLogs(d.logs || []); } catch { setLogs([]); } }
      else { setLogs([]); }
      if (statusRes.ok) { try { const d = await (statusRes as Response).json(); setStatus(d); } catch { setStatus(null); } }
      else { setStatus(null); }
    } catch { toast.error("Error al cargar datos de webhooks"); setLogs([]); setStatus(null); }
    finally { setLoading(false); }
  }, [typeFilter, statusFilter]);

  useEffect(() => { fetchData(); const i = setInterval(fetchData, 30000); return () => clearInterval(i); }, [fetchData]);

  const handleCopyUrl = (url: string, type: string) => { navigator.clipboard.writeText(url); toast.success(`URL de ${type} copiada al portapapeles`); };
  const handleTestWebhook = async (type: string) => {
    try {
      const response = await fetch("/api/admin/system/webhooks/test", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ webhook_type: type }) });
      const data = await response.json();
      if (data.success) { toast.success(data.message); fetchData(); } else { toast.error(data.error || "Error al probar webhook"); }
    } catch { toast.error("Error al probar webhook"); }
  };
  const handleViewDetails = (log: WebhookLog) => { setSelectedLog(log); setShowDetailsDialog(true); };

  return {
    logs, status, loading, typeFilter, setTypeFilter, statusFilter, setStatusFilter,
    selectedLog, setSelectedLog, showDetailsDialog, setShowDetailsDialog,
    fetchData, handleCopyUrl, handleTestWebhook, handleViewDetails,
  };
}

