        </div>
        <div className="text-center p-2 bg-verde-suave/10 rounded">
          <p className="text-xs text-tierra-media mb-1">Total</p>
          <p className="font-bold text-sm text-verde-suave">
            {formatValue(
              aggregatedData.reduce((sum, item) => sum + item.value, 0),
