        </div>
        <div className="text-center p-2 bg-blue-50 rounded">
          <p className="text-xs text-tierra-media mb-1">Períodos</p>
          <p className="font-bold text-sm text-azul-profundo">
            {aggregatedData.length}
          </p>
        </div>
      </div>
    </div>
  );
}

