              // Format large numbers
              if (value >= 1000000) return `${(value / 1000000).toFixed(1)}M`;
              if (value >= 1000) return `${(value / 1000).toFixed(1)}K`;
              return formatValue(value);
            }}
            tickLine={false}
          />
          <Tooltip content={<CustomTooltip />} />
          <Line
            activeDot={{ r: 6, fill: color }}
            animationDuration={1000}
            animationEasing="ease-out"
            dataKey="displayValue"
            dot={{ fill: color, r: 4 }}
            stroke={color}
            strokeWidth={2}
            type="monotone"
          />
        </RechartsLineChart>
      </ResponsiveContainer>

      {/* Summary stats */}
      <div className="grid grid-cols-3 gap-3 pt-3 border-t border-gray-200 dark:border-gray-700">
        <div className="text-center p-2 bg-gray-50 dark:bg-gray-800 rounded-lg">
          <p className="text-xs text-admin-text-tertiary dark:text-gray-400 mb-1">
            Promedio
          </p>
          <p className="font-bold text-sm text-epoch-primary dark:text-admin-text-primary">
            {formatValue(
              data.reduce((sum, item) => sum + item.value, 0) / data.length,
            )}
          </p>
        </div>
        <div
          className="text-center p-2 rounded-lg"
          style={{ backgroundColor: `${color}15` }}
        >
          <p className="text-xs text-admin-text-tertiary dark:text-gray-400 mb-1">
            Máximo
          </p>
          <p className="font-bold text-sm" style={{ color }}>
            {formatValue(Math.max(...data.map((d) => d.value)))}
          </p>
        </div>
        <div className="text-center p-2 bg-red-50 dark:bg-red-900/20 rounded-lg">
          <p className="text-xs text-admin-text-tertiary dark:text-gray-400 mb-1">
            Mínimo
          </p>
          <p className="font-bold text-sm text-red-500 dark:text-red-400">
            {formatValue(Math.min(...data.map((d) => d.value)))}
          </p>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useMemo } from "react";
import {
  Cell,
  Pie,
  PieChart as RechartsPieChart,
  ResponsiveContainer,
  Tooltip,
} from "recharts";

interface EnhancedPieChartProps {
  data: Array<{ label: string; value: number; color?: string }>;
  title?: string;
  showLegend?: boolean;
  showPercentage?: boolean;
  formatValue?: (value: number) => string;
  height?: number;
}

const DEFAULT_COLORS = [
  "#9DC65D", // verde-suave
  "#1E3A8A", // azul-profundo
  "#D4A853", // dorado
  "#8B4513", // tierra-media
  "#AE0000", // rojo OPTTIUS
  "#4A7C59", // verde oscuro
  "#60A5FA", // azul claro
  "#F59E0B", // amarillo
  "#EC4899", // rosa
  "#8B5CF6", // púrpura
];

const RADIAN = Math.PI / 180;

const renderCustomizedLabel = ({
  cx,
  cy,
  midAngle,
  innerRadius,
  outerRadius,
  percent,
}: unknown) => {
  const radius = innerRadius + (outerRadius - innerRadius) * 0.5;
  const x = cx + radius * Math.cos(-midAngle * RADIAN);
  const y = cy + radius * Math.sin(-midAngle * RADIAN);

  return (
    <text
      dominantBaseline="central"
      fill="white"
      fontSize={12}
      fontWeight="bold"
      textAnchor={x > cx ? "start" : "end"}
      x={x}
      y={y}
    >
      {`${(percent * 100).toFixed(0)}%`}
    </text>
  );
};

export function EnhancedPieChart({
  data,
  title,
  showLegend = true,
  showPercentage = true,
  formatValue = (val) => val.toString(),
  height = 400,
}: EnhancedPieChartProps) {
  const chartData = useMemo(() => {
    const total = data.reduce((sum, item) => sum + item.value, 0);
    return data.map((item, index) => ({
      ...item,
      name: item.label,
      value: item.value,
      percentage: total > 0 ? (item.value / total) * 100 : 0,
      color: item.color || DEFAULT_COLORS[index % DEFAULT_COLORS.length],
    }));
  }, [data]);

  if (!data || data.length === 0) {
    return (
      <div className="flex items-center justify-center h-64 text-admin-text-tertiary">
        <p className="text-lg font-medium">No hay datos para mostrar</p>
      </div>
    );
  }

  const CustomTooltip = ({ active, payload }: unknown) => {
    if (active && payload && payload.length) {
      const data = payload[0].payload;
      return (
        <div className="bg-white dark:bg-gray-800 p-3 rounded-lg shadow-lg border border-gray-200 dark:border-gray-700">
          <p className="text-sm font-semibold text-gray-900 dark:text-gray-100 mb-1">
            {data.name}
          </p>
          <p className="text-sm" style={{ color: data.color }}>
            <span className="font-medium">Valor: </span>
            {formatValue(data.value)}
          </p>
          {showPercentage && (
            <p className="text-xs text-gray-600 dark:text-gray-400 mt-1">
              {data.percentage.toFixed(1)}% del total
            </p>
          )}
        </div>
      );
    }
    return null;
  };

  const pieHeight = Math.min(height * 0.6, 220);
  const outerRadius = Math.min(90, pieHeight / 2 - 10);

  return (
    <div className="flex flex-col w-full min-h-0">
      {title && (
        <h4 className="font-semibold text-sm sm:text-base text-epoch-primary dark:text-admin-text-primary text-center mb-2 shrink-0">
          {title}
        </h4>
      )}

      <div className="shrink-0" style={{ height: pieHeight }}>
        <ResponsiveContainer height="100%" width="100%">
          <RechartsPieChart
            id="enhanced-pie-chart"
            margin={{ top: 4, right: 4, bottom: 4, left: 4 }}
          >
            <Pie
              animationDuration={1000}
              animationEasing="ease-out"
              cx="50%"
              cy="50%"
              data={chartData}
              dataKey="value"
              fill="#8884d8"
              label={showPercentage ? renderCustomizedLabel : false}
              labelLine={false}
              outerRadius={outerRadius}
            >
              {chartData.map((entry, index) => (
                <Cell fill={entry.color} key={`cell-${index}`} />
              ))}
            </Pie>
            <Tooltip content={<CustomTooltip />} />
          </RechartsPieChart>
        </ResponsiveContainer>
      </div>

      {showLegend && (
        <div className="flex flex-wrap justify-center gap-x-4 gap-y-2 mt-3 shrink-0">
          {chartData.map((entry, index) => (
            <div
              className="flex items-center gap-2 text-xs sm:text-sm"
              key={`legend-${index}`}
            >
              <div
                className="w-3 h-3 sm:w-4 sm:h-4 rounded-full shrink-0"
                style={{ backgroundColor: entry.color }}
              />
              <span className="text-gray-700 dark:text-gray-300 truncate max-w-[120px] sm:max-w-none">
                {entry.label}
              </span>
              {showPercentage && (
                <span className="text-gray-500 dark:text-gray-400 font-semibold shrink-0">
                  ({entry.percentage.toFixed(1)}%)
                </span>
              )}
            </div>
          ))}
        </div>
      )}

      <div className="text-center pt-3 mt-3 border-t border-gray-200 dark:border-gray-700 shrink-0">
        <p className="text-xs text-admin-text-tertiary dark:text-gray-400 mb-0.5">
          Total
        </p>
        <p className="font-bold text-base sm:text-lg text-epoch-primary dark:text-admin-text-primary">
          {formatValue(chartData.reduce((sum, item) => sum + item.value, 0))}
        </p>
      </div>
    </div>
  );
}

"use client";

import { memo, useMemo } from "react";

interface LineChartProps {
  data: Array<{ date: string; value: number; count?: number }>;
  title?: string;
  color?: string;
  formatValue?: (value: number) => string;
  showGrid?: boolean;
  showPoints?: boolean;
}

function LineChartComponent({
  data,
  title,
  color = "#9DC65D",
  formatValue = (val) => val.toString(),
  showGrid = true,
  showPoints = true,
}: LineChartProps) {
  const { maxValue, minValue, points, hasData } = useMemo(() => {
    if (!data || data.length === 0) {
      return { maxValue: 0, minValue: 0, points: [], hasData: false };
    }

    const values = data.map((item) => item.value);
    const max = Math.max(...values);
    const min = Math.min(...values);
    const range = max - min || 1;

    // Add 10% padding to top and bottom
    const padding = range * 0.1;
    const paddedMax = max + padding;
    const paddedMin = Math.max(0, min - padding);
    const paddedRange = paddedMax - paddedMin || 1;

    const chartPoints = data.map((item, index) => {
      const x = (index / (data.length - 1)) * 100;
      const y = 100 - ((item.value - paddedMin) / paddedRange) * 100;
      return { x, y, value: item.value, date: item.date, count: item.count };
    });

    return {
      maxValue: paddedMax,
      minValue: paddedMin,
      points: chartPoints,
      hasData: max > 0 || min > 0,
    };
  }, [data]);

  if (!hasData) {
    return (
      <div className="flex flex-col items-center justify-center h-64 text-tierra-media space-y-2">
        <p className="text-lg font-medium">No hay datos para mostrar</p>
        <p className="text-sm text-center max-w-md">
          No se encontraron datos para el período seleccionado. Los datos
          aparecerán cuando haya actividad registrada en el sistema.
        </p>
      </div>
    );
  }

  // Generate grid lines (5 horizontal lines)
  const gridLines = showGrid ? [0, 25, 50, 75, 100] : [];

  // Calculate Y-axis labels
  const yAxisLabels = gridLines.map((y) => {
    const value = minValue + ((100 - y) / 100) * (maxValue - minValue);
    return { y, label: formatValue(value) };
  });

  return (
    <div className="space-y-4">
      {title && (
        <h4 className="font-medium text-azul-profundo text-center">{title}</h4>
      )}

      <div className="relative">
        {/* Chart container */}
        <div className="flex">
          {/* Y-axis labels */}
          <div className="flex flex-col justify-between h-64 pr-3 text-xs text-tierra-media">
            {yAxisLabels.reverse().map((label, idx) => (
              <div className="text-right" key={idx}>
                {label.label}
              </div>
            ))}
          </div>

          {/* Chart area */}
          <div className="flex-1 relative">
            <svg className="overflow-visible" height="256" width="100%">
              {/* Grid lines */}
              {showGrid &&
                gridLines.map((y, idx) => (
                  <line
                    key={idx}
                    stroke="#E5E7EB"
                    strokeDasharray="4 4"
                    strokeWidth="1"
                    x1="0"
                    x2="100%"
                    y1={`${y}%`}
                    y2={`${y}%`}
                  />
                ))}

              {/* Area fill */}
              <defs>
                <linearGradient
                  id={`gradient-${title}`}
                  x1="0%"
                  x2="0%"
                  y1="0%"
                  y2="100%"
                >
                  <stop offset="0%" stopColor={color} stopOpacity="0.3" />
                  <stop offset="100%" stopColor={color} stopOpacity="0.05" />
                </linearGradient>
              </defs>

              <path
                d={`
                  M 0,${points[0].y}
                  ${points.map((p, i) => `L ${p.x},${p.y}`).join(" ")}
                  L ${points[points.length - 1].x},100
                  L 0,100
                  Z
                `}
                fill={`url(#gradient-${title})`}
              />

              {/* Line */}
              <polyline
                fill="none"
                points={points.map((p) => `${p.x},${p.y}`).join(" ")}
                stroke={color}
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth="3"
              />

              {/* Points */}
              {showPoints &&
                points.map((point, index) => (
                  <g key={index}>
                    <circle
                      className="cursor-pointer hover:r-6 transition-all"
                      cx={`${point.x}%`}
                      cy={`${point.y}%`}
                      fill="white"
                      r="5"
                      stroke={color}
                      strokeWidth="2"
                    />
                    <title>
                      {point.date}: {formatValue(point.value)}
                      {point.count !== undefined && ` (${point.count} items)`}
                    </title>
                  </g>
                ))}
            </svg>
          </div>
        </div>

        {/* X-axis labels */}
        <div className="flex justify-between mt-2 text-xs text-tierra-media pl-12">
          <span>{data[0]?.date}</span>
          {data.length > 2 && (
            <span>{data[Math.floor(data.length / 2)]?.date}</span>
          )}
          <span>{data[data.length - 1]?.date}</span>
        </div>
      </div>

      {/* Summary stats */}
      <div className="grid grid-cols-3 gap-4 pt-4 border-t">
        <div className="text-center">
          <p className="text-xs text-tierra-media">Promedio</p>
          <p className="font-bold text-azul-profundo">
            {formatValue(
              data.reduce((sum, item) => sum + item.value, 0) / data.length,
            )}
          </p>
        </div>
        <div className="text-center">
          <p className="text-xs text-tierra-media">Máximo</p>
          <p className="font-bold text-verde-suave">
            {formatValue(Math.max(...data.map((d) => d.value)))}
          </p>
        </div>
        <div className="text-center">
          <p className="text-xs text-tierra-media">Mínimo</p>
          <p className="font-bold text-red-500">
            {formatValue(Math.min(...data.map((d) => d.value)))}
          </p>
        </div>
      </div>
    </div>
  );
}

// Memoize LineChart to prevent unnecessary re-renders
export const LineChart = memo(LineChartComponent);

"use client";

import { memo, useMemo } from "react";

interface PieChartProps {
  data: Array<{ label: string; value: number; color?: string }>;
  title?: string;
  showLegend?: boolean;
  showPercentage?: boolean;
}

const DEFAULT_COLORS = [
  "#9DC65D", // verde-suave
  "#1E3A8A", // azul-profundo
  "#D4A853", // dorado
  "#8B4513", // tierra-media
  "#AE0000", // rojo OPTTIUS
  "#4A7C59", // verde oscuro
  "#F6FBD6", // verde claro
  "#E5E7EB", // gris
];

function PieChartComponent({
  data,
  title,
  showLegend = true,
  showPercentage = true,
}: PieChartProps) {
  const total = useMemo(
    () => data.reduce((sum, item) => sum + item.value, 0),
    [data],
  );

  const chartData = useMemo(() => {
    let currentAngle = -90; // Start from top

    return data.map((item, index) => {
      const percentage = total > 0 ? (item.value / total) * 100 : 0;
      const angle = (percentage / 100) * 360;
      const startAngle = currentAngle;
      const endAngle = currentAngle + angle;

      currentAngle = endAngle;

      return {
        ...item,
        percentage,
        startAngle,
        endAngle,
        color: item.color || DEFAULT_COLORS[index % DEFAULT_COLORS.length],
      };
    });
  }, [data, total]);

  const createArc = (startAngle: number, endAngle: number, radius: number) => {
    const start = polarToCartesian(50, 50, radius, endAngle);
    const end = polarToCartesian(50, 50, radius, startAngle);
    const largeArcFlag = endAngle - startAngle <= 180 ? "0" : "1";

    return [
      "M",
      50,
      50,
      "L",
      start.x,
      start.y,
      "A",
      radius,
      radius,
      0,
      largeArcFlag,
      0,
      end.x,
      end.y,
      "Z",
    ].join(" ");
  };

  const polarToCartesian = (
    centerX: number,
    centerY: number,
    radius: number,
    angleInDegrees: number,
  ) => {
    const angleInRadians = (angleInDegrees * Math.PI) / 180.0;
    return {
      x: centerX + radius * Math.cos(angleInRadians),
      y: centerY + radius * Math.sin(angleInRadians),
    };
  };

  if (data.length === 0 || total === 0) {
    return (
      <div className="flex items-center justify-center h-64 text-tierra-media">
        No hay datos para mostrar
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {title && (
        <h4 className="font-medium text-azul-profundo text-center">{title}</h4>
      )}

      <div className="flex flex-col lg:flex-row items-center gap-6">
        {/* Pie Chart SVG */}
        <div className="relative w-64 h-64">
          <svg
            className="w-full h-full transform -rotate-90"
            viewBox="0 0 100 100"
          >
            {chartData.map((item, index) => (
              <path
                className="transition-all hover:opacity-80 cursor-pointer"
                d={createArc(item.startAngle, item.endAngle, 45)}
                fill={item.color}
                key={index}
                style={{ transformOrigin: "50% 50%" }}
              />
            ))}
            {/* Center circle for donut effect */}
            <circle cx="50" cy="50" fill="white" r="25" />
          </svg>

          {/* Center text */}
          <div className="absolute inset-0 flex flex-col items-center justify-center">
            <span className="text-2xl font-bold text-azul-profundo">
              {total}
            </span>
            <span className="text-xs text-tierra-media">Total</span>
          </div>
        </div>

        {/* Legend */}
        {showLegend && (
          <div className="flex-1 space-y-2">
            {chartData.map((item, index) => (
              <div
                className="flex items-center justify-between p-2 hover:bg-gray-50 rounded transition-colors"
                key={index}
              >
                <div className="flex items-center space-x-3">
                  <div
                    className="w-4 h-4 rounded-full flex-shrink-0"
                    style={{ backgroundColor: item.color }}
                  />
                  <span className="text-sm font-medium truncate">
                    {item.label}
                  </span>
                </div>
                <div className="flex items-center space-x-2 ml-4">
                  <span className="text-sm font-bold text-azul-profundo">
                    {item.value}
                  </span>
                  {showPercentage && (
                    <span className="text-xs text-tierra-media">
                      ({item.percentage.toFixed(1)}%)
                    </span>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

// Memoize PieChart to prevent unnecessary re-renders
export const PieChart = memo(PieChartComponent);

"use client";

import {
  Bot,
  Download,
  Edit2,
  History,
  MoreVertical,
  PanelRightClose,
  PanelRightOpen,
  Plus,
  Settings,
  Trash2,
  X,
} from "lucide-react";
