import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Input } from "@/components/ui/input";

interface ChatHeaderProps {
  title: string;
  onTitleChange: (title: string) => void;
  onSettingsClick: () => void;
  onHistoryClick: () => void;
  onNewConversation: () => void;
  onExport: () => void;
  onClear: () => void;
  onDelete: () => void;
  onDuplicate?: () => void;
  onClose?: () => void;
  /** When provided, shows expand/collapse sidebar button */
  onExpandClick?: () => void;
  /** When true, shows collapse icon; when false, expand icon */
  isSidebarMode?: boolean;
}

export function ChatHeader({
  title,
  onTitleChange,
  onSettingsClick,
  onHistoryClick,
  onNewConversation,
  onExport,
  onClear,
  onDelete,
  onDuplicate,
  onClose,
  onExpandClick,
  isSidebarMode = false,
}: ChatHeaderProps) {
  const [isEditing, setIsEditing] = useState(false);
  const [editTitle, setEditTitle] = useState(title);

  useEffect(() => {
    setEditTitle(title);
  }, [title]);

  const handleTitleSubmit = () => {
    if (editTitle.trim()) {
      onTitleChange(editTitle.trim());
    }
    setIsEditing(false);
  };

  const handleTitleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter") {
      handleTitleSubmit();
    } else if (e.key === "Escape") {
      setEditTitle(title);
      setIsEditing(false);
    }
  };

  return (
    <div className="bg-primary px-3 sm:px-5 py-2 flex items-center justify-between gap-2 text-white shadow-md relative group min-h-0 shrink-0">
