              <Trash2 className="w-4 h-4" /> Eliminar sesión
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>

        {onExpandClick && (
          <Button
            className="text-white hover:bg-white/10 rounded-xl h-9 w-9"
            size="icon"
            title={
              isSidebarMode
                ? "Volver a ventana flotante"
                : "Expandir como panel lateral"
            }
            variant="ghost"
            onClick={onExpandClick}
          >
            {isSidebarMode ? (
              <PanelRightClose className="w-5 h-5" />
            ) : (
              <PanelRightOpen className="w-5 h-5" />
            )}
          </Button>
        )}

        {onClose && (
          <Button
            className="text-white hover:bg-white/10 rounded-full h-9 w-9"
            size="icon"
            variant="ghost"
            onClick={onClose}
          >
            <X className="w-6 h-6" />
          </Button>
        )}
      </div>
    </div>
  );
}

"use client";

import {
  Calendar,
  History,
  Loader2,
  MessageSquare,
  Plus,
  Search,
  Trash2,
  X,
} from "lucide-react";
import { useEffect, useState } from "react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { ScrollArea } from "@/components/ui/scroll-area";
import { appLogger } from '@/lib/logger';
import { cn } from "@/lib/utils";

interface ChatSession {
  id: string;
  title: string | null;
  provider: string;
  model: string | null;
  created_at: string;
  updated_at: string;
  last_message_preview?: string | null;
  message_count?: number | null;
}

interface ChatHistorySidebarProps {
  currentSessionId?: string | null;
  onSessionSelect: (sessionId: string) => void;
  onNewSession: () => void;
  onClose?: () => void;
  className?: string;
}

export function ChatHistorySidebar({
  currentSessionId,
  onSessionSelect,
  onNewSession,
  onClose,
  className,
}: ChatHistorySidebarProps) {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [filteredSessions, setFilteredSessions] = useState<ChatSession[]>([]);
  const [searchQuery, setSearchQuery] = useState("");
  const [loading, setLoading] = useState(true);
  const [deletingId, setDeletingId] = useState<string | null>(null);

  useEffect(() => {
    loadSessions();
  }, []);

  useEffect(() => {
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase();
      setFilteredSessions(
        sessions.filter(
          (session) =>
            session.title?.toLowerCase().includes(query) ||
            session.last_message_preview?.toLowerCase().includes(query),
        ),
      );
    } else {
      setFilteredSessions(sessions);
    }
  }, [searchQuery, sessions]);

  const loadSessions = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/admin/chat/history?limit=50");
      if (response.ok) {
        const data = await response.json();
        setSessions(data.sessions || []);
      }
    } catch (error) {
      appLogger.error("Error loading sessions:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (sessionId: string, e: React.MouseEvent) => {
    e.stopPropagation();

    if (!confirm("¿Estás seguro de que deseas eliminar esta conversación?")) {
      return;
    }

    try {
      setDeletingId(sessionId);
      const response = await fetch(
        `/api/admin/chat/history?sessionId=${sessionId}`,
        {
          method: "DELETE",
        },
      );

      if (response.ok) {
        setSessions((prev) => prev.filter((s) => s.id !== sessionId));
        if (currentSessionId === sessionId) {
          onNewSession();
        }
      }
    } catch (error) {
      appLogger.error("Error deleting session:", error);
    } finally {
      setDeletingId(null);
    }
  };

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);

    if (diffMins < 1) return "Ahora";
    if (diffMins < 60) return `Hace ${diffMins}m`;
    if (diffHours < 24) return `Hace ${diffHours}h`;
    if (diffDays < 7) return `Hace ${diffDays}d`;

    return date.toLocaleDateString("es-ES", {
      day: "numeric",
      month: "short",
    });
  };

  const getSessionTitle = (session: ChatSession) => {
    return session.title || "Nueva conversación";
  };

  return (
    <div
      className={cn(
        "flex flex-col h-full bg-white dark:bg-slate-950 shadow-2xl transition-all duration-300",
        className,
      )}
    >
      <div className="p-5 border-b border-slate-100 dark:border-slate-800/50 flex items-center justify-between bg-white/50 dark:bg-slate-950/50 backdrop-blur-xl sticky top-0 z-10">
        <div className="flex items-center gap-2.5">
          <div className="p-2 rounded-lg bg-primary/10 text-primary">
            <History className="w-5 h-5" />
          </div>
          <h2 className="text-base font-bold text-slate-800 dark:text-slate-100">
            Historial de Consultas
          </h2>
        </div>
        <Button
          className="rounded-full hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
          size="icon"
          variant="ghost"
          onClick={onClose}
        >
          <X className="w-5 h-5 text-slate-500" />
        </Button>
      </div>

      <div className="p-4 space-y-4">
        <div className="flex items-center gap-2">
          <Button
            className="flex-1 rounded-xl h-10 font-bold tracking-tight shadow-md hover:shadow-primary/20 transition-all font-sans"
            size="sm"
            onClick={onNewSession}
          >
            <Plus className="w-4 h-4 mr-2" />
            Nueva conversación
          </Button>
        </div>

        <div className="relative group">
          <Search className="absolute left-3.5 top-1/2 transform -translate-y-1/2 w-4 h-4 text-slate-400 group-focus-within:text-primary transition-colors" />
          <Input
            className="pl-10 h-10 rounded-xl bg-slate-50 dark:bg-slate-900 border-slate-200 dark:border-slate-800 focus:ring-primary/10 transition-all text-sm"
            placeholder="Buscar en el historial..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
      </div>

      <ScrollArea className="flex-1 px-4 pb-4">
        {loading ? (
          <div className="flex flex-col items-center justify-center py-20 gap-3">
            <Loader2 className="w-8 h-8 animate-spin text-primary/40" />
            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">
              Cargando sesiones...
            </p>
          </div>
        ) : filteredSessions.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 text-center animate-in fade-in zoom-in duration-500">
            <div className="w-16 h-16 rounded-3xl bg-slate-50 dark:bg-slate-900 flex items-center justify-center mb-4">
              <MessageSquare className="w-8 h-8 text-slate-300 dark:text-slate-700" />
            </div>
            <p className="text-sm font-bold text-slate-800 dark:text-slate-200">
              {searchQuery ? "Sin resultados" : "Historial vacío"}
            </p>
            <p className="text-xs text-slate-500 dark:text-slate-500 mt-2 max-w-[200px] leading-relaxed">
              {searchQuery
                ? `No encontramos nada parecido a "${searchQuery}"`
                : "Tus conversaciones con el Experto IA aparecerán aquí."}
            </p>
          </div>
        ) : (
          <div className="space-y-2.5">
            {filteredSessions.map((session) => (
              <div
                className={cn(
                  "group relative p-4 rounded-2xl cursor-pointer transition-all border duration-200 animate-in fade-in slide-in-from-bottom-1",
                  currentSessionId === session.id
                    ? "bg-primary/5 border-primary/20 shadow-sm"
                    : "bg-white dark:bg-slate-900/40 border-slate-100 dark:border-slate-800 hover:border-primary/20 hover:shadow-md hover:shadow-slate-200/20 dark:hover:shadow-none hover:-translate-y-0.5",
                )}
                key={session.id}
                onClick={() => onSessionSelect(session.id)}
              >
                <div className="flex items-start justify-between gap-3">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1.5">
                      <div
                        className={cn(
                          "w-2 h-2 rounded-full",
                          currentSessionId === session.id
                            ? "bg-primary animate-pulse"
                            : "bg-slate-300 dark:bg-slate-600",
                        )}
                      />
                      <h3
                        className={cn(
                          "text-sm font-bold truncate tracking-tight",
                          currentSessionId === session.id
                            ? "text-primary"
                            : "text-slate-800 dark:text-slate-200",
                        )}
                      >
                        {getSessionTitle(session)}
                      </h3>
                    </div>

                    {session.last_message_preview && (
                      <p className="text-xs text-slate-500 dark:text-slate-400 line-clamp-2 leading-relaxed mb-3">
                        {session.last_message_preview}
                      </p>
                    )}

                    <div className="flex items-center gap-4 text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider">
                      <div className="flex items-center gap-1.5">
                        <Calendar className="w-3.5 h-3.5" />
                        <span>{formatDate(session.updated_at)}</span>
                      </div>
                      {session.message_count !== null &&
                        session.message_count !== undefined && (
                          <div className="flex items-center gap-1.5">
                            <MessageSquare className="w-3.5 h-3.5" />
                            <span>{session.message_count} msgs</span>
                          </div>
                        )}
                    </div>
                  </div>

                  <Button
                    className={cn(
                      "h-8 w-8 rounded-xl opacity-0 group-hover:opacity-100 transition-all",
                      "hover:bg-destructive/10 hover:text-destructive",
                    )}
                    disabled={deletingId === session.id}
                    size="icon"
                    variant="ghost"
                    onClick={(e) => handleDelete(session.id, e)}
                  >
                    {deletingId === session.id ? (
                      <Loader2 className="w-4 h-4 animate-spin" />
                    ) : (
                      <Trash2 className="w-4 h-4" />
                    )}
                  </Button>
                </div>
              </div>
            ))}
          </div>
        )}
      </ScrollArea>
    </div>
  );
}

"use client";

import {
  Command,
  Paperclip,
  SendHorizonal,
  Sparkles,
  Square,
  X,
} from "lucide-react";
import { KeyboardEvent, useEffect, useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";

interface ChatInputProps {
  onSend: (message: string, fileId?: string) => void;
  onStop?: () => void;
  disabled?: boolean;
  placeholder?: string;
}

export function ChatInput({
  onSend,
  onStop,
  disabled,
  placeholder = "Pregunta sobre Opttius...",
}: ChatInputProps) {
  const [message, setMessage] = useState("");
  const [attachedFile, setAttachedFile] = useState<{
    fileId: string;
    filename: string;
    rowCount: number;
  } | null>(null);
  const [uploading, setUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || disabled || uploading) return;

    const isCSV = file.name.toLowerCase().endsWith(".csv");
    const isExcel =
      file.name.toLowerCase().endsWith(".xlsx") ||
      file.name.toLowerCase().endsWith(".xls");
    if (!isCSV && !isExcel) {
      alert("Solo se permiten archivos CSV o Excel (.xlsx, .xls)");
      return;
    }
    if (file.size > 5 * 1024 * 1024) {
      alert("El archivo no puede superar 5MB");
      return;
    }

    setUploading(true);
    try {
      const formData = new FormData();
      formData.append("file", file);
      const res = await fetch("/api/admin/chat/upload-import-file", {
        method: "POST",
        body: formData,
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err.error || "Error al subir");
      }
      const data = await res.json();
      setAttachedFile({
        fileId: data.fileId,
        filename: data.filename,
        rowCount: data.rowCount ?? 0,
      });
    } catch (err: unknown) {
      alert(err?.message || "Error al subir el archivo");
    } finally {
      setUploading(false);
      e.target.value = "";
    }
  };

  const handleSend = () => {
    if ((message.trim() || attachedFile) && !disabled) {
      const text = message.trim() || "Importa los datos de este archivo";
      onSend(text, attachedFile?.fileId);
      setMessage("");
      setAttachedFile(null);
      if (textareaRef.current) {
        textareaRef.current.style.height = "auto";
      }
    }
  };

  const handleKeyDown = (e: KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  // Auto-resize textarea
  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = "auto";
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 200)}px`;
    }
  }, [message]);

  return (
    <div className="p-4 bg-white dark:bg-slate-950/20 backdrop-blur-xl border-t border-slate-100 dark:border-slate-800/50">
      <input
        accept=".csv,.xlsx,.xls"
        className="hidden"
        ref={fileInputRef}
        type="file"
        onChange={handleFileSelect}
      />
      <div className="max-w-4xl mx-auto">
        {attachedFile && (
          <div className="mb-2 flex items-center gap-2 px-2 py-1.5 rounded-lg bg-primary/10 border border-primary/20 text-sm">
            <Paperclip className="h-4 w-4 text-primary" />
            <span className="truncate flex-1">{attachedFile.filename}</span>
            <span className="text-muted-foreground text-xs">
              {attachedFile.rowCount} filas
            </span>
            <button
              className="p-1 hover:bg-primary/20 rounded"
              type="button"
              onClick={() => setAttachedFile(null)}
            >
              <X className="h-4 w-4" />
            </button>
          </div>
        )}
        <div className="relative flex items-end gap-2 bg-white dark:bg-slate-900 rounded-[24px] p-2 pr-2.5 border border-slate-200 dark:border-slate-800 shadow-lg shadow-slate-200/20 dark:shadow-none focus-within:border-primary/50 focus-within:ring-4 focus-within:ring-primary/5 transition-all">
          <Button
            className="shrink-0 rounded-xl w-10 h-10"
            disabled={disabled || uploading}
            size="icon"
            title="Adjuntar CSV o Excel para importar"
            type="button"
            variant="ghost"
            onClick={() => fileInputRef.current?.click()}
          >
            <Paperclip className="w-5 h-5" />
          </Button>
          <Textarea
            className="resize-none min-h-[44px] max-h-48 bg-transparent border-0 focus-visible:ring-0 focus-visible:ring-offset-0 px-4 py-3 text-[14.5px] leading-relaxed placeholder:text-slate-400 dark:placeholder:text-slate-500"
            disabled={disabled}
            placeholder={placeholder}
            ref={textareaRef}
            rows={1}
            value={message}
            onChange={(e) => setMessage(e.target.value)}
            onKeyDown={handleKeyDown}
          />
          {disabled && onStop ? (
            <Button
              className="shrink-0 rounded-xl w-10 h-10"
              size="icon"
              title="Detener respuesta"
              variant="destructive"
              onClick={onStop}
            >
              <Square className="w-5 h-5 fill-current" />
            </Button>
          ) : (
            <Button
              className={cn(
                "shrink-0 rounded-xl w-10 h-10 transition-all duration-300",
                message.trim()
                  ? "bg-primary text-white shadow-md shadow-primary/20 scale-100 opacity-100"
                  : "bg-slate-100 dark:bg-slate-800 text-slate-400 scale-90 opacity-50",
              )}
              disabled={disabled || (!message.trim() && !attachedFile)}
              size="icon"
              onClick={handleSend}
            >
              <SendHorizonal className="w-5 h-5" />
            </Button>
          )}
        </div>

        <div className="flex items-center justify-between px-4 mt-2.5">
          <div className="flex items-center gap-3">
            <div className="flex items-center gap-1 text-[10px] text-slate-400 font-bold uppercase tracking-tight">
              <Command className="w-3 h-3" />
              <span>Enter para enviar</span>
            </div>
            <span className="text-slate-200 dark:text-slate-800 text-[10px]">
              |
            </span>
            <div className="flex items-center gap-1 text-[10px] text-slate-400 font-bold uppercase tracking-tight">
              <span>Shift+Enter para nueva línea</span>
            </div>
          </div>

          <div className="flex items-center gap-1.5 text-[10px] text-primary/70 font-black uppercase tracking-widest">
            <Sparkles className="w-3.5 h-3.5" />
            Opttius Intelligence
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import {
  Check,
  Copy,
  FileCode,
  FileJson,
  FileSpreadsheet,
  FileText,
} from "lucide-react";
import { useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { copyToClipboard, exportConversation } from "@/lib/utils/chatExport";

interface ExportDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  session: unknown;
  messages: unknown[];
}

export function ExportDialog({
  open,
  onOpenChange,
  session,
  messages,
}: ExportDialogProps) {
  const [format, setFormat] = useState<"json" | "markdown" | "txt" | "csv">(
    "markdown",
  );
  const [copied, setCopied] = useState(false);

  const handleExport = () => {
    if (!session || !messages) return;

    exportConversation(
      {
        session,
        messages,
      },
      format,
    );
    onOpenChange(false);
  };

  const handleCopyToClipboard = async () => {
    if (!session || !messages) return;

    const success = await copyToClipboard(
      {
        session,
        messages,
      },
      format,
    );

    if (success) {
      setCopied(true);
      toast.success("Copiado al portapapeles");
      setTimeout(() => {
        setCopied(false);
        onOpenChange(false);
      }, 1500);
    } else {
      toast.error("Error al copiar al portapapeles");
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent elevateZIndex>
        <DialogHeader>
          <DialogTitle>Exportar Conversación</DialogTitle>
          <DialogDescription>
            Selecciona el formato en el que deseas exportar esta conversación.
          </DialogDescription>
        </DialogHeader>

        <RadioGroup
          value={format}
          onValueChange={(value) => setFormat(value as unknown)}
        >
          <div className="flex items-center space-x-2 p-3 rounded-lg border border-border hover:bg-muted/60 cursor-pointer transition-colors">
            <RadioGroupItem id="json" value="json" />
            <Label
              className="flex-1 cursor-pointer flex items-center gap-2 text-foreground"
              htmlFor="json"
            >
              <FileJson className="w-4 h-4 text-muted-foreground" />
              <div>
                <div className="font-medium">JSON</div>
                <div className="text-xs text-muted-foreground">
                  Export completo con metadata
                </div>
              </div>
            </Label>
          </div>

          <div className="flex items-center space-x-2 p-3 rounded-lg border border-border hover:bg-muted/60 cursor-pointer transition-colors">
            <RadioGroupItem id="markdown" value="markdown" />
            <Label
              className="flex-1 cursor-pointer flex items-center gap-2 text-foreground"
              htmlFor="markdown"
            >
              <FileCode className="w-4 h-4 text-muted-foreground" />
              <div>
                <div className="font-medium">Markdown</div>
                <div className="text-xs text-muted-foreground">
                  Formato legible con timestamps
                </div>
              </div>
            </Label>
          </div>

          <div className="flex items-center space-x-2 p-3 rounded-lg border border-border hover:bg-muted/60 cursor-pointer transition-colors">
            <RadioGroupItem id="txt" value="txt" />
            <Label
              className="flex-1 cursor-pointer flex items-center gap-2 text-foreground"
              htmlFor="txt"
            >
              <FileText className="w-4 h-4 text-muted-foreground" />
              <div>
                <div className="font-medium">Texto Plano</div>
                <div className="text-xs text-muted-foreground">
                  Formato simple de texto
                </div>
              </div>
            </Label>
          </div>

          <div className="flex items-center space-x-2 p-3 rounded-lg border border-border hover:bg-muted/60 cursor-pointer transition-colors">
            <RadioGroupItem id="csv" value="csv" />
            <Label
              className="flex-1 cursor-pointer flex items-center gap-2 text-foreground"
              htmlFor="csv"
            >
              <FileSpreadsheet className="w-4 h-4 text-muted-foreground" />
              <div>
                <div className="font-medium">CSV</div>
                <div className="text-xs text-muted-foreground">
                  Para análisis (solo mensajes)
                </div>
              </div>
            </Label>
          </div>
        </RadioGroup>

        <DialogFooter className="flex gap-2">
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancelar
          </Button>
          <Button
            className="flex items-center gap-2"
            variant="outline"
            onClick={handleCopyToClipboard}
          >
            {copied ? (
              <>
                <Check className="w-4 h-4" />
                Copiado
              </>
            ) : (
              <>
                <Copy className="w-4 h-4" />
                Copiar al Portapapeles
              </>
            )}
          </Button>
          <Button onClick={handleExport}>Descargar</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import {
  Bot,
  Check,
  Copy,
  Edit2,
  RotateCw,
  Sparkles,
  Trash2,
  User,
} from "lucide-react";
import { useState } from "react";

import { Button } from "@/components/ui/button";
import { appLogger } from '@/lib/logger';
import { cn } from "@/lib/utils";

interface MessageBubbleProps {
  role: "user" | "assistant" | "system" | "tool";
  content: string;
  timestamp?: string;
  toolCalls?: unknown;
  toolResults?: unknown;
  metadata?: unknown;
  onCopy?: () => void;
  onEdit?: () => void;
  onDelete?: () => void;
  onRegenerate?: () => void;
}

function renderInlineMarkdown(
  text: string,
  keyPrefix: string = "",
): React.ReactNode[] {
  const parts: React.ReactNode[] = [];

  // Process inline elements: bold, italic, inline code, links
  const inlineRegex =
    /(`[^`]+`)|(\*\*[^*]+\*\*)|(\*[^*]+\*)|(\[[^\]]+\]\([^)]+\))/g;
  let lastIndex = 0;
  let match;
  let matchIndex = 0;

  while ((match = inlineRegex.exec(text)) !== null) {
    // Add text before match
    if (match.index > lastIndex) {
      parts.push(
        <span key={`${keyPrefix}text-${matchIndex}`}>
          {text.substring(lastIndex, match.index)}
        </span>,
      );
    }

    const fullMatch = match[0];

    if (match[1]) {
      // Inline code: `code`
      parts.push(
        <code
          className="bg-slate-100 dark:bg-slate-800 px-1.5 py-0.5 rounded text-[11px] font-mono text-primary font-bold"
          key={`${keyPrefix}code-${matchIndex}`}
        >
          {fullMatch.slice(1, -1)}
        </code>,
      );
    } else if (match[2]) {
      // Bold: **text**
      parts.push(
        <strong
          className="font-extrabold text-slate-900 dark:text-white"
          key={`${keyPrefix}bold-${matchIndex}`}
        >
          {fullMatch.slice(2, -2)}
        </strong>,
      );
    } else if (match[3]) {
      // Italic: *text*
      parts.push(
        <em
          className="italic opacity-90"
          key={`${keyPrefix}italic-${matchIndex}`}
        >
          {fullMatch.slice(1, -1)}
        </em>,
      );
    } else if (match[4]) {
      // Link: [text](url)
      const linkMatch = fullMatch.match(/\[([^\]]+)\]\(([^)]+)\)/);
      if (linkMatch) {
        parts.push(
          <a
            className="text-primary hover:underline font-bold decoration-primary/30"
            href={linkMatch[2]}
            key={`${keyPrefix}link-${matchIndex}`}
            rel="noopener noreferrer"
            target="_blank"
          >
            {linkMatch[1]}
          </a>,
        );
      }
    }

    lastIndex = match.index + fullMatch.length;
    matchIndex++;
  }

  // Add remaining text
  if (lastIndex < text.length) {
    parts.push(
      <span key={`${keyPrefix}text-end`}>{text.substring(lastIndex)}</span>,
    );
  }

  return parts.length > 0
    ? parts
    : [<span key={`${keyPrefix}empty`}>{text}</span>];
}

function renderMarkdown(content: string) {
  const parts: React.ReactNode[] = [];

  // First, extract code blocks to protect them from other processing
  const codeBlockRegex = /```(\w+)?\n?([\s\S]*?)```/g;
  const segments: Array<{
    type: "text" | "codeBlock";
    content: string;
    lang?: string;
  }> = [];
  let lastIndex = 0;
  let match;

  while ((match = codeBlockRegex.exec(content)) !== null) {
    if (match.index > lastIndex) {
      segments.push({
        type: "text",
        content: content.substring(lastIndex, match.index),
      });
    }
    segments.push({ type: "codeBlock", content: match[2], lang: match[1] });
    lastIndex = match.index + match[0].length;
  }

  if (lastIndex < content.length) {
    segments.push({ type: "text", content: content.substring(lastIndex) });
  }

  if (segments.length === 0) {
    segments.push({ type: "text", content });
  }

  segments.forEach((segment, segIndex) => {
    if (segment.type === "codeBlock") {
      parts.push(
        <pre
          className="bg-slate-950 text-slate-100 p-4 rounded-xl overflow-x-auto my-3 text-[13px] font-mono shadow-2xl border border-white/5"
          key={`codeblock-${segIndex}`}
        >
          <div className="flex items-center justify-between mb-2 pb-2 border-b border-white/10 opacity-50 uppercase text-[10px] font-bold tracking-widest">
            <span>{segment.lang || "code"}</span>
          </div>
          <code>{segment.content}</code>
        </pre>,
      );
    } else {
      // Process text line by line
      const lines = segment.content.split("\n");

      lines.forEach((line, lineIndex) => {
        const trimmedLine = line.trim();
        const lineKey = `${segIndex}-${lineIndex}`;

        // Heading 2: ## text
        if (trimmedLine.startsWith("## ")) {
          const headingContent = trimmedLine.substring(3);
          parts.push(
            <h2
              className="text-lg font-bold mt-5 mb-2.5 text-slate-900 dark:text-white"
              key={`h2-${lineKey}`}
            >
              {renderInlineMarkdown(headingContent, `h2-${lineKey}-`)}
            </h2>,
          );
        }
        // Heading 3: ### text
        else if (trimmedLine.startsWith("### ")) {
          const headingContent = trimmedLine.substring(4);
          parts.push(
            <h3
              className="text-base font-bold mt-4 mb-2 text-slate-800 dark:text-slate-100"
              key={`h3-${lineKey}`}
            >
              {renderInlineMarkdown(headingContent, `h3-${lineKey}-`)}
            </h3>,
          );
        }
        // Heading 1: # text
        else if (trimmedLine.startsWith("# ")) {
          const headingContent = trimmedLine.substring(2);
          parts.push(
            <h1
              className="text-xl font-black mt-6 mb-3 text-slate-950 dark:text-white underline decoration-primary/20 underline-offset-4"
              key={`h1-${lineKey}`}
            >
              {renderInlineMarkdown(headingContent, `h1-${lineKey}-`)}
            </h1>,
          );
        }
        // Unordered list: - text or * text
        else if (trimmedLine.match(/^[-*]\s+/)) {
          const listContent = trimmedLine.replace(/^[-*]\s+/, "");
          parts.push(
            <div
              className="flex items-start gap-3 ml-2 my-1.5"
              key={`ul-${lineKey}`}
            >
              <span className="text-primary font-black mt-0.5">•</span>
              <span className="text-slate-700 dark:text-slate-300">
                {renderInlineMarkdown(listContent, `ul-${lineKey}-`)}
              </span>
            </div>,
          );
        }
        // Ordered list: 1. text
        else if (trimmedLine.match(/^\d+\.\s+/)) {
          const numMatch = trimmedLine.match(/^(\d+)\.\s+(.*)/);
          if (numMatch) {
            parts.push(
              <div
                className="flex items-start gap-3 ml-2 my-1.5"
                key={`ol-${lineKey}`}
              >
                <span className="text-primary font-bold min-w-[1.2em]">
                  {numMatch[1]}.
                </span>
                <span className="text-slate-700 dark:text-slate-300">
                  {renderInlineMarkdown(numMatch[2], `ol-${lineKey}-`)}
                </span>
              </div>,
            );
          }
        }
        // Empty line
        else if (trimmedLine === "") {
          parts.push(<div className="h-3" key={`br-${lineKey}`} />);
        }
        // Regular paragraph
        else {
          parts.push(
            <p
              className="my-1.5 leading-relaxed text-slate-700 dark:text-slate-300"
              key={`p-${lineKey}`}
            >
              {renderInlineMarkdown(line, `p-${lineKey}-`)}
            </p>,
          );
        }
      });
    }
  });

  return parts.length > 0 ? parts : <span>{content}</span>;
}

export function MessageBubble({
  role,
  content,
  timestamp,
  toolCalls,
  toolResults,
  metadata,
  onCopy,
  onEdit,
  onDelete,
  onRegenerate,
}: MessageBubbleProps) {
  const [copied, setCopied] = useState(false);
  const isUser = role === "user";
  const isSystem = role === "system";
  const isTool = role === "tool";

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(content);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
      onCopy?.();
    } catch (err) {
      appLogger.error("Failed to copy:", err);
    }
  };

  if (isSystem) {
    return null;
  }

  const toolCallsData = toolCalls || metadata?.toolCalls;
  const toolResultsData = toolResults || metadata?.toolResults;

  return (
    <div
      className={cn(
        "flex flex-col mb-8 group animate-in fade-in slide-in-from-bottom-2 duration-500",
        isUser ? "items-end" : "items-start",
      )}
    >
      <div
        className={cn(
          "flex gap-3 max-w-[90%]",
          isUser ? "flex-row-reverse" : "flex-row",
        )}
      >
        {/* Avatar */}
        <div
          className={cn(
            "flex-shrink-0 w-9 h-9 rounded-2xl flex items-center justify-center shadow-lg transition-transform group-hover:scale-110",
            isUser
              ? "bg-primary text-white"
              : "bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-primary shadow-slate-200/50 dark:shadow-none",
          )}
        >
          {isUser ? <User className="w-5 h-5" /> : <Bot className="w-5 h-5" />}
        </div>

        {/* Bubble */}
        <div className="flex flex-col gap-1.5 min-w-0">
          <div
            className={cn(
              "rounded-2xl px-5 py-3.5 relative shadow-sm transition-all shadow-slate-200/50 dark:shadow-none",
              isUser
                ? "bg-primary text-white rounded-tr-none font-medium ml-4"
                : isTool
                  ? "bg-slate-50 dark:bg-slate-900 text-slate-600 dark:text-slate-400 border border-slate-200 dark:border-slate-800 font-mono text-xs rounded-tl-none mr-4"
                  : "bg-white dark:bg-slate-900 text-slate-800 dark:text-slate-100 border border-slate-100 dark:border-slate-800 rounded-tl-none mr-4 backdrop-blur-sm",
            )}
          >
            <div
              className={cn(
                "text-[14.5px] whitespace-pre-wrap break-words",
                isUser
                  ? "selection:bg-white/30 [&_span]:text-[var(--accent)]"
                  : "selection:bg-primary/20",
              )}
            >
              {renderMarkdown(content)}
            </div>

            {(() => {
              // Tool calls and reasoning are hidden from the user - only show final response.
              // Log errors to console for debugging.
              const toolCallsArray = Array.isArray(toolCallsData)
                ? toolCallsData
                : toolCallsData
                  ? [toolCallsData]
                  : [];
              toolCallsArray.forEach((tc: unknown, index: number) => {
                const result =
                  toolResultsData?.[tc.id] || toolResultsData?.[index];
                if (result && result.success === false) {
                  appLogger.error(
                    `Tool Execution Error [${tc.name}]:`,
                    result.error || "Unknown error",
                    result,
                  );
                }
              });
              return null;
            })()}
          </div>

          {/* Footer actions & Timestamp */}
          <div
            className={cn(
              "flex items-center gap-3 px-1.5 transition-all duration-300",
              isUser ? "flex-row-reverse" : "flex-row",
              "opacity-0 group-hover:opacity-100",
            )}
          >
            {timestamp && (
              <span className="text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-tighter">
                {new Date(timestamp).toLocaleTimeString("es-ES", {
                  hour: "2-digit",
                  minute: "2-digit",
                })}
              </span>
            )}

            <div className="flex items-center gap-0.5">
              <Button
                className="h-7 w-7 rounded-lg text-slate-400 hover:text-primary hover:bg-primary/5 transition-colors"
                size="icon"
                title="Copiar texto"
                variant="ghost"
                onClick={handleCopy}
              >
                {copied ? (
                  <Check className="w-3.5 h-3.5" />
                ) : (
                  <Copy className="w-3.5 h-3.5" />
                )}
              </Button>

              {isUser && onEdit && (
                <Button
                  className="h-7 w-7 rounded-lg text-slate-400 hover:text-primary hover:bg-primary/5 transition-colors"
                  size="icon"
                  title="Editar mensaje"
                  variant="ghost"
                  onClick={onEdit}
                >
                  <Edit2 className="w-3.5 h-3.5" />
                </Button>
              )}

              {!isUser && onRegenerate && (
                <Button
                  className="h-7 w-7 rounded-lg text-slate-400 hover:text-primary hover:bg-primary/5 transition-colors"
                  size="icon"
                  title="Regenerar respuesta"
                  variant="ghost"
                  onClick={onRegenerate}
                >
                  <RotateCw className="w-3.5 h-3.5" />
                </Button>
              )}

              {onDelete && (
                <Button
                  className="h-7 w-7 rounded-lg text-slate-400 hover:text-destructive hover:bg-destructive/5 transition-colors"
                  size="icon"
                  title="Eliminar mensaje"
                  variant="ghost"
                  onClick={onDelete}
                >
                  <Trash2 className="w-3.5 h-3.5" />
                </Button>
              )}
            </div>

            {!isUser && !isTool && (
              <div className="flex items-center gap-1 text-[10px] font-bold text-primary/50 uppercase tracking-widest ml-1">
                <Sparkles className="w-3 h-3" />
                Experto Óptico
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useMemo, useRef } from "react";

import { Separator } from "@/components/ui/separator";

import { MessageBubble } from "./MessageBubble";
import { TypingIndicator } from "./TypingIndicator";

interface Message {
  id: string;
  role: "user" | "assistant" | "system" | "tool";
  content: string;
  timestamp?: string;
  toolCalls?: unknown;
  toolResults?: unknown;
  metadata?: unknown;
}

interface MessageListProps {
  messages: Message[];
  isStreaming?: boolean;
  onMessageAction?: (
    messageId: string,
    action: "copy" | "edit" | "delete" | "regenerate",
  ) => void;
}

import { formatRelativeDate } from "@/lib/utils";

function groupMessagesByDate(
  messages: Message[],
): Array<{ date: string; messages: Message[] }> {
  const groups: Record<string, Message[]> = {};

  messages.forEach((message) => {
    if (!message.timestamp) {
      if (!groups["Sin fecha"]) {
        groups["Sin fecha"] = [];
      }
      groups["Sin fecha"].push(message);
      return;
    }

    const date = formatRelativeDate(message.timestamp);
    if (!groups[date]) {
      groups[date] = [];
    }
    groups[date].push(message);
  });

  return Object.entries(groups).map(([date, messages]) => ({
    date,
    messages,
  }));
}

export function MessageList({
  messages,
  isStreaming,
  onMessageAction,
}: MessageListProps) {
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const groupedMessages = useMemo(
    () => groupMessagesByDate(messages),
    [messages],
  );

  useEffect(() => {
    // Use setTimeout to avoid infinite loops
    const timeoutId = setTimeout(() => {
      if (messagesEndRef.current) {
        messagesEndRef.current.scrollIntoView({
          behavior: "smooth",
          block: "end",
        });
      }
    }, 100);

    return () => clearTimeout(timeoutId);
  }, [messages.length, isStreaming]);

  return (
    <div className="min-h-full">
      <div className="p-4 space-y-4">
        {messages.length === 0 && (
          <div className="text-center text-admin-text-secondary py-12">
            <p className="text-sm font-medium">
              Inicia una conversación con el asistente
            </p>
            <p className="text-xs mt-2 opacity-70">
              Puedes preguntar sobre productos, pedidos, clientes y más
            </p>
          </div>
        )}

        {groupedMessages.map((group, groupIndex) => (
          <div className="space-y-2" key={group.date}>
            {groupIndex > 0 && <Separator className="my-4" />}

            <div className="sticky top-0 z-10 flex items-center gap-2 mb-2">
              <Separator className="flex-1" />
              <span className="text-xs text-admin-text-secondary bg-admin-bg-primary px-2 py-1 rounded">
                {group.date}
              </span>
              <Separator className="flex-1" />
            </div>

            {group.messages.map((message) => (
              <MessageBubble
                content={message.content}
                key={message.id}
                metadata={message.metadata}
                role={message.role}
                timestamp={message.timestamp}
                toolCalls={message.toolCalls}
                toolResults={message.toolResults}
                onCopy={() => onMessageAction?.(message.id, "copy")}
                onDelete={() => onMessageAction?.(message.id, "delete")}
                onEdit={() => onMessageAction?.(message.id, "edit")}
                onRegenerate={() => onMessageAction?.(message.id, "regenerate")}
              />
            ))}
          </div>
        ))}

        {isStreaming && <TypingIndicator />}

        <div ref={messagesEndRef} />
      </div>
    </div>
  );
}

"use client";

import { Check, ChevronDown } from "lucide-react";
import { useEffect, useState } from "react";

import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import type { LLMProvider } from "@/lib/ai/types";
import { appLogger } from '@/lib/logger';

interface ProviderSelectorProps {
  selectedProvider?: LLMProvider;
  onProviderChange: (provider: LLMProvider) => void;
}

export function ProviderSelector({
  selectedProvider,
  onProviderChange,
}: ProviderSelectorProps) {
  const [providers, setProviders] = useState<
    { id: LLMProvider; name: string; enabled: boolean }[]
  >([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchProviders = async () => {
      try {
        const response = await fetch("/api/admin/chat/providers");
        if (response.ok) {
          const data = await response.json();
          setProviders(data.providers || []);
        }
      } catch (error) {
        appLogger.error("Error fetching providers:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchProviders();
  }, []);

  const providerNames: Record<LLMProvider, string> = {
    openai: "OpenAI",
    anthropic: "Anthropic",
    google: "Google",
    deepseek: "DeepSeek",
    openrouter: "OpenRouter",
    kilocode: "Kilocode",
    minimax: "Minimax",
    nvidia: "NVIDIA",
    opencodezen: "OpenCodeZen",
    custom: "Custom",
  };

  const enabledProviders = providers.filter((p) => p.enabled);
  const currentProvider =
    providers.find((p) => p.id === selectedProvider) || enabledProviders[0];

  if (loading) {
    return <div className="text-sm text-admin-text-secondary">Cargando...</div>;
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button className="gap-2" size="sm" variant="outline">
          {currentProvider ? providerNames[currentProvider.id] : "Seleccionar"}
          <ChevronDown className="w-4 h-4" />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end">
        <DropdownMenuLabel>Proveedor de IA</DropdownMenuLabel>
        <DropdownMenuSeparator />
        {enabledProviders.map((provider) => (
          <DropdownMenuItem
            className="flex items-center justify-between"
            key={provider.id}
            onClick={() => onProviderChange(provider.id)}
          >
            <span>{providerNames[provider.id]}</span>
            {selectedProvider === provider.id && <Check className="w-4 h-4" />}
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

"use client";

import { CheckCircle2, Search, Wrench, X } from "lucide-react";
import { useEffect, useState } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { ScrollArea } from "@/components/ui/scroll-area";
import { appLogger } from '@/lib/logger';
import { cn } from "@/lib/utils";

interface Tool {
  name: string;
  description: string;
  category: string;
  parameters: unknown;
  requiresConfirmation?: boolean;
}

interface ToolBrowserProps {
  enabledTools: string[];
  onToolsChange: (tools: string[]) => void;
  onClose: () => void;
}

export function ToolBrowser({
  enabledTools,
  onToolsChange,
  onClose,
}: ToolBrowserProps) {
  const [tools, setTools] = useState<Tool[]>([]);
  const [toolsByCategory, setToolsByCategory] = useState<
    Record<string, Tool[]>
  >({});
  const [searchQuery, setSearchQuery] = useState("");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadTools();
  }, []);

  const loadTools = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/admin/chat/tools");
      if (response.ok) {
        const data = await response.json();
        setTools(data.tools || []);
        setToolsByCategory(data.toolsByCategory || {});
      }
    } catch (error) {
      appLogger.error("Error loading tools:", error);
    } finally {
      setLoading(false);
    }
  };

  const toggleTool = (toolName: string) => {
    const newTools = enabledTools.includes(toolName)
      ? enabledTools.filter((t) => t !== toolName)
      : [...enabledTools, toolName];
    onToolsChange(newTools);
  };

  const filteredCategories = searchQuery
    ? Object.entries(toolsByCategory).filter(([category, categoryTools]) =>
        categoryTools.some(
          (tool) =>
            tool.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
            tool.description.toLowerCase().includes(searchQuery.toLowerCase()),
        ),
      )
    : Object.entries(toolsByCategory);

  return (
    <div className="flex flex-col h-full bg-admin-bg-primary">
      <div className="p-4 border-b border-admin-border-primary flex items-center justify-between">
        <div>
          <h2 className="text-lg font-semibold text-admin-text-primary">
            Herramientas
          </h2>
          <p className="text-xs text-admin-text-secondary mt-1">
            {enabledTools.length} de {tools.length} habilitadas
          </p>
        </div>
        <Button size="icon" variant="ghost" onClick={onClose}>
          <X className="w-4 h-4" />
        </Button>
      </div>

      <div className="p-4 border-b border-admin-border-primary">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-admin-text-secondary" />
          <Input
            className="pl-9"
            placeholder="Buscar herramientas..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
      </div>

      <ScrollArea className="flex-1">
        <div className="p-4 space-y-6">
          {loading ? (
            <div className="text-center py-8 text-admin-text-secondary">
              Cargando...
            </div>
          ) : filteredCategories.length === 0 ? (
            <div className="text-center py-8 text-admin-text-secondary">
              No se encontraron herramientas
            </div>
          ) : (
            filteredCategories.map(([category, categoryTools]) => {
              const filtered = searchQuery
                ? categoryTools.filter(
                    (tool) =>
                      tool.name
                        .toLowerCase()
                        .includes(searchQuery.toLowerCase()) ||
                      tool.description
                        .toLowerCase()
                        .includes(searchQuery.toLowerCase()),
                  )
                : categoryTools;

              if (filtered.length === 0) return null;

              return (
                <div className="space-y-3" key={category}>
                  <h3 className="font-semibold text-admin-text-primary flex items-center gap-2">
                    <Wrench className="w-4 h-4" />
                    {category}
                    <Badge className="ml-2" variant="outline">
                      {filtered.length}
                    </Badge>
                  </h3>

                  <div className="space-y-2">
                    {filtered.map((tool) => {
                      const isEnabled = enabledTools.includes(tool.name);
                      return (
                        <div
                          className={cn(
                            "p-3 rounded-lg border transition-colors cursor-pointer",
                            isEnabled
                              ? "bg-admin-bg-secondary border-admin-accent-primary"
                              : "bg-admin-bg-primary border-admin-border-primary hover:bg-admin-bg-secondary",
                          )}
                          key={tool.name}
                          onClick={() => toggleTool(tool.name)}
                        >
                          <div className="flex items-start justify-between gap-2">
                            <div className="flex-1">
                              <div className="flex items-center gap-2">
                                <h4 className="font-medium text-sm text-admin-text-primary">
                                  {tool.name}
                                </h4>
                                {isEnabled && (
                                  <CheckCircle2 className="w-4 h-4 text-green-500" />
                                )}
                                {tool.requiresConfirmation && (
                                  <Badge className="text-xs" variant="outline">
                                    Requiere confirmación
                                  </Badge>
                                )}
                              </div>
                              <p className="text-xs text-admin-text-secondary mt-1">
                                {tool.description}
                              </p>
                              {tool.parameters && (
                                <details className="mt-2">
                                  <summary className="text-xs text-admin-text-secondary cursor-pointer hover:text-admin-text-primary">
                                    Ver parámetros
                                  </summary>
                                  <pre className="mt-2 p-2 bg-admin-bg-primary rounded text-xs overflow-x-auto">
                                    {JSON.stringify(tool.parameters, null, 2)}
                                  </pre>
                                </details>
                              )}
                            </div>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              );
            })
          )}
        </div>
      </ScrollArea>
    </div>
  );
}

"use client";

import { CheckCircle2, Loader2, Wrench, XCircle } from "lucide-react";

import { cn } from "@/lib/utils";

interface ToolCall {
  id: string;
  name: string;
  arguments: unknown;
}

interface ToolCallDisplayProps {
  toolCalls?: ToolCall[];
  toolResults?: unknown;
  isExecuting?: boolean;
  className?: string;
}

export function ToolCallDisplay({
  toolCalls,
  toolResults,
  isExecuting = false,
  className,
}: ToolCallDisplayProps) {
  if (!toolCalls || toolCalls.length === 0) {
    return null;
  }

  return (
    <div className={cn("space-y-2 mt-2", className)}>
      {toolCalls.map((toolCall, index) => {
        const result = toolResults?.[toolCall.id] || toolResults?.[index];
        const hasResult = result !== undefined;
        const isSuccess = result?.success !== false;

        return (
          <div
            className={cn(
              "flex items-start gap-2 p-2 rounded-md text-sm",
              "bg-admin-bg-secondary border border-admin-border-primary",
            )}
            key={toolCall.id || index}
          >
            {isExecuting && !hasResult ? (
              <Loader2 className="w-4 h-4 animate-spin text-admin-text-secondary mt-0.5" />
            ) : isSuccess ? (
              <CheckCircle2 className="w-4 h-4 text-green-500 mt-0.5" />
            ) : (
              <XCircle className="w-4 h-4 text-red-500 mt-0.5" />
            )}

            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2">
                <Wrench className="w-3 h-3 text-admin-text-secondary" />
                <span className="font-medium text-admin-text-primary">
                  {toolCall.name}
                </span>
              </div>

              {toolCall.arguments &&
                Object.keys(toolCall.arguments).length > 0 && (
                  <div className="mt-1 text-xs text-admin-text-secondary">
                    <details className="cursor-pointer">
                      <summary className="hover:text-admin-text-primary">
                        Ver parámetros
                      </summary>
                      <pre className="mt-1 p-2 bg-admin-bg-primary rounded text-xs overflow-x-auto">
                        {JSON.stringify(toolCall.arguments, null, 2)}
                      </pre>
                    </details>
                  </div>
                )}

              {hasResult && (
                <div className="mt-2 text-xs">
                  {isSuccess ? (
                    <div className="text-green-600 dark:text-green-400">
                      ✓ Ejecutado correctamente
                    </div>
                  ) : (
                    <div className="text-red-600 dark:text-red-400">
                      ✗ Error: {result?.error || "Error desconocido"}
                    </div>
                  )}

                  {result?.data && (
                    <details className="mt-1 cursor-pointer">
                      <summary className="hover:text-admin-text-primary text-admin-text-secondary">
                        Ver resultado
                      </summary>
                      <pre className="mt-1 p-2 bg-admin-bg-primary rounded text-xs overflow-x-auto max-h-40 overflow-y-auto">
                        {typeof result.data === "string"
                          ? result.data
                          : JSON.stringify(result.data, null, 2)}
                      </pre>
                    </details>
                  )}
                </div>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}

