"use client";

import { useCallback, useEffect, useState } from "react";
import { toast } from "sonner";

import { appLogger } from '@/lib/logger';

import type { Branch, Driver, InternalOrder, Vehicle } from "../_components/types";

export function useInternalOrders() {
  const [orders, setOrders] = useState<InternalOrder[]>([]);
  const [branches, setBranches] = useState<Branch[]>([]);
  const [drivers, setDrivers] = useState<Driver[]>([]);
  const [vehicles, setVehicles] = useState<Vehicle[]>([]);
  const [loading, setLoading] = useState(true);
  const [showOrderDialog, setShowOrderDialog] = useState(false);
  const [showDeleteDialog, setShowDeleteDialog] = useState(false);
  const [editingOrder, setEditingOrder] = useState<InternalOrder | null>(null);
  const [deletingItem, setDeletingItem] = useState<{ type: "order"; id: string; orderNumber: string } | null>(null);
  const [orderForm, setOrderForm] = useState({
    origin_branch_id: "",
    destination_branch_id: "",
    priority: "medium" as "low" | "medium" | "high" | "urgent",
    scheduled_pickup_date: "",
    estimated_delivery_date: "",
    notes: "",
    driver_id: "",
    vehicle_id: "",
  });

  const fetchData = useCallback(async () => {
    try {
      setLoading(true);
      const [branchesRes, driversRes, vehiclesRes, ordersRes] = await Promise.all([
        fetch("/api/admin/branches"),
        fetch("/api/admin/drivers"),
        fetch("/api/admin/vehicles"),
        fetch("/api/admin/internal-orders"),
      ]);
      if (branchesRes.ok) {
        const d = await branchesRes.json();
        setBranches(d.branches || []);
      }
      if (driversRes.ok) {
        const d = await driversRes.json();
        setDrivers(d.drivers || []);
      }
      if (vehiclesRes.ok) {
        const d = await vehiclesRes.json();
        setVehicles(d.vehicles || []);
      }
      if (ordersRes.ok) {
        const d = await ordersRes.json();
        setOrders(d.orders || []);
      }
    } catch (error) {
      appLogger.error("Error fetching data:", error);
      toast.error("Error al cargar los datos");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { fetchData(); }, [fetchData]);

  const handleCreateOrder = () => {
    setEditingOrder(null);
    setOrderForm({ origin_branch_id: "", destination_branch_id: "", priority: "medium", scheduled_pickup_date: "", estimated_delivery_date: "", notes: "", driver_id: "", vehicle_id: "" });
    setShowOrderDialog(true);
  };

  const handleEditOrder = (order: InternalOrder) => {
    setEditingOrder(order);
    setOrderForm({
      origin_branch_id: order.origin_branch_id,
      destination_branch_id: order.destination_branch_id,
      priority: order.priority,
      scheduled_pickup_date: order.scheduled_pickup_date || "",
      estimated_delivery_date: order.estimated_delivery_date || "",
      notes: order.notes || "",
      driver_id: order.driver_id || "",
      vehicle_id: order.vehicle_id || "",
    });
    setShowOrderDialog(true);
  };

  const handleDeleteOrder = (order: InternalOrder) => {
    setDeletingItem({ type: "order", id: order.id, orderNumber: order.order_number });
    setShowDeleteDialog(true);
  };

  const handleSaveOrder = async () => {
    try {
      const url = editingOrder ? `/api/admin/internal-orders/${editingOrder.id}` : "/api/admin/internal-orders";
      const method = editingOrder ? "PUT" : "POST";
      const response = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ...orderForm, status: editingOrder ? editingOrder.status : "pending" }),
      });
      if (!response.ok) throw new Error("Error al guardar orden");
      toast.success(editingOrder ? "Orden actualizada" : "Orden creada");
      setShowOrderDialog(false);
      fetchData();
    } catch { toast.error("Error al guardar orden"); }
  };

  const handleConfirmDelete = async () => {
    if (!deletingItem) return;
    try {
      const response = await fetch(`/api/admin/internal-orders/${deletingItem.id}`, { method: "DELETE" });
      if (!response.ok) throw new Error("Error al eliminar orden");
      toast.success("Orden eliminada");
      setShowDeleteDialog(false);
      setDeletingItem(null);
      fetchData();
    } catch { toast.error("Error al eliminar orden"); }
  };

  return {
    orders, branches, drivers, vehicles, loading,
    showOrderDialog, setShowOrderDialog,
    showDeleteDialog, setShowDeleteDialog,
    editingOrder, deletingItem,
    orderForm, setOrderForm,
    handleCreateOrder, handleEditOrder, handleDeleteOrder,
    handleSaveOrder, handleConfirmDelete, fetchData,
  };
}

"use client";
import { Edit, Eye, EyeOff, RefreshCw, Search, Trash2 } from "lucide-react";
import { useRouter } from "next/navigation";
import React, { useEffect, useState } from "react";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Pagination } from "@/components/ui/pagination";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { appLogger } from '@/lib/logger';

interface ContactLensFamily {
  id: string;
  name: string;
  brand: string | null;
  use_type: string;
  modality: string;
  material: string | null;
  packaging: string;
  base_curve: number | null;
  diameter: number | null;
  description: string | null;
  is_active: boolean;
  created_at: string;
  updated_at: string;
}

const USE_TYPES = [
  { value: "daily", label: "Diario" },
  { value: "bi_weekly", label: "Quincenal" },
  { value: "monthly", label: "Mensual" },
  { value: "extended_wear", label: "Uso Prolongado" },
];

const MODALITIES = [
  { value: "spherical", label: "Esférico" },
  { value: "toric", label: "Tórico" },
  { value: "multifocal", label: "Multifocal" },
  { value: "cosmetic", label: "Cosmético" },
];

export default function ContactLensFamiliesList() {
  const router = useRouter();

  const [families, setFamilies] = useState<ContactLensFamily[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [modalityFilter, setModalityFilter] = useState<string>("all");
  const [includeInactive, setIncludeInactive] = useState(false);

  // Pagination state
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage, setItemsPerPage] = useState(20);

  useEffect(() => {
    fetchFamilies();
  }, [includeInactive, modalityFilter]);

  const fetchFamilies = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams();
      if (includeInactive) {
        params.append("include_inactive", "true");
      }
      if (modalityFilter && modalityFilter !== "all") {
        params.append("modality", modalityFilter);
      }
      const response = await fetch(
        `/api/admin/contact-lens-families?${params.toString()}`,
      );
      if (response.ok) {
        const result = await response.json();
        setFamilies(result.data ?? result.families ?? []);
      } else {
        toast.error("Error al cargar familias de lentes de contacto");
      }
    } catch (error) {
      appLogger.error("Error fetching families:", error);
      toast.error("Error al cargar familias de lentes de contacto");
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("¿Estás seguro de que deseas eliminar esta familia?")) {
      return;
    }

    try {
      const response = await fetch(`/api/admin/contact-lens-families/${id}`, {
        method: "DELETE",
      });

      if (!response.ok) {
        throw new Error("Error al eliminar familia");
      }

      toast.success("Familia eliminada exitosamente");
      fetchFamilies();
    } catch (error) {
      toast.error("Error al eliminar familia");
    }
  };

  const filteredFamilies = families.filter((family) => {
    const searchLower = searchTerm.toLowerCase();
    return (
      family.name.toLowerCase().includes(searchLower) ||
      (family.brand || "").toLowerCase().includes(searchLower) ||
      family.use_type.toLowerCase().includes(searchLower) ||
      family.modality.toLowerCase().includes(searchLower)
    );
  });

  // Pagination calculations
  const totalFamilies = filteredFamilies.length;
  const startIndex = (currentPage - 1) * itemsPerPage;
  const endIndex = startIndex + itemsPerPage;
  const paginatedFamilies = filteredFamilies.slice(startIndex, endIndex);
  const totalPages = Math.ceil(totalFamilies / itemsPerPage);

  // Reset to page 1 when filters change
  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, includeInactive, modalityFilter]);

  return (
    <div className="py-6 space-y-8">
      <div className="border-b border-admin-border-primary/10 pb-6">
        <div className="space-y-1">
          <h2 className="text-sm font-display font-bold text-admin-text-primary uppercase tracking-[0.2em] flex items-center">
            Matriz de Lentes de Contacto
          </h2>
          <p className="text-[10px] font-serif italic text-admin-text-tertiary uppercase tracking-widest">
            Registro Técnico de Modalidades y Parámetros Biométricos
          </p>
        </div>
      </div>

      <Card className="border border-admin-border-primary/20 bg-admin-bg-tertiary rounded-xl shadow-none overflow-hidden">
        <CardHeader className="bg-admin-bg-tertiary/50 border-b border-admin-border-primary/10 py-4 sm:py-6 px-4 sm:px-6">
          <div className="flex flex-col sm:flex-row justify-between items-stretch sm:items-center gap-3">
            <div className="flex items-center gap-2">
              <RefreshCw className="h-4 w-4 text-epoch-primary opacity-50" />
              <h3 className="text-[11px] font-display font-bold text-admin-text-primary uppercase tracking-[0.2em]">
                Registro de Familias de Lentes de Contacto (
                {filteredFamilies.length})
              </h3>
            </div>
            <div className="flex flex-wrap gap-2">
              <Button
                className={`rounded-xl text-[9px] font-display font-bold tracking-widest uppercase h-auto py-2 border-none ${
                  includeInactive
                    ? "bg-admin-error/10 text-admin-error"
                    : "hover:bg-admin-bg-tertiary text-admin-text-tertiary"
                }`}
                size="sm"
                variant="ghost"
                onClick={() => setIncludeInactive(!includeInactive)}
              >
                {includeInactive ? (
                  <>
                    <EyeOff className="h-3 w-3 mr-2" />
                    OCULTAR INACTIVAS
                  </>
                ) : (
                  <>
                    <Eye className="h-3 w-3 mr-2" />
                    MOSTRAR INACTIVAS
                  </>
                )}
              </Button>
              <Button
                className="h-8 w-8 p-0 border-none hover:bg-admin-bg-tertiary text-epoch-primary"
                size="sm"
                variant="ghost"
                onClick={fetchFamilies}
              >
                <RefreshCw
                  className={`h-4 w-4 ${loading ? "animate-spin" : ""}`}
                />
              </Button>
            </div>
          </div>
        </CardHeader>
        <CardContent className="p-0">
          <div className="p-3 sm:p-6 border-b border-admin-border-primary/10 bg-admin-bg-tertiary/20">
            <div className="flex flex-col sm:flex-row gap-3">
              <div className="relative flex-1">
                <Search className="absolute left-3 sm:left-4 top-1/2 transform -translate-y-1/2 h-4 w-4 text-admin-text-tertiary opacity-40" />
                <Input
                  className="pl-10 sm:pl-12 rounded-xl border-admin-border-primary/10 focus:border-epoch-primary focus:ring-0 bg-white p-3 sm:p-6 text-[9px] sm:text-[10px] font-display font-bold tracking-widest uppercase"
                  placeholder="Buscar por nombre, tipo o modalidad..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
              </div>
              <div className="w-full sm:w-48">
                <Select
                  value={modalityFilter}
                  onValueChange={setModalityFilter}
                >
                  <SelectTrigger className="rounded-xl border-admin-border-primary/10 h-auto p-3 sm:p-6 text-[9px] sm:text-[10px] font-display font-bold tracking-widest uppercase">
                    <SelectValue placeholder="Modalidad" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">Todas las modalidades</SelectItem>
                    {MODALITIES.map((m) => (
                      <SelectItem key={m.value} value={m.value}>
                        {m.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
          </div>

          {loading ? (
            <div className="text-center py-24 bg-admin-bg-tertiary/10">
              <RefreshCw className="h-8 w-8 text-epoch-primary animate-spin mx-auto mb-4 opacity-30" />
              <p className="text-[10px] font-display font-bold text-admin-text-tertiary uppercase tracking-widest">
                SINCRONIZANDO MATRIZ CLINICA...
              </p>
            </div>
          ) : paginatedFamilies.length === 0 ? (
            <div className="text-center py-24 bg-admin-bg-tertiary/10 border-2 border-dashed border-admin-border-primary/5 m-6">
              <EyeOff className="h-12 w-12 text-admin-text-tertiary mx-auto mb-4 opacity-20" />
              <h3 className="text-xs font-display font-bold text-admin-text-primary uppercase tracking-[0.2em]">
                MATRIZ SIN REGISTROS
              </h3>
              <p className="text-[10px] font-serif italic text-admin-text-tertiary uppercase tracking-widest mt-2">
                No se han detectado familias de contacto en la base de datos
              </p>
            </div>
          ) : (
            <div className="overflow-x-auto min-w-0 -mx-2 sm:mx-0 px-2 sm:px-0">
              <Table className="min-w-[600px]">
                <TableHeader className="bg-admin-bg-tertiary/30">
                  <TableRow className="hover:bg-transparent border-admin-border-primary/10">
                    <TableHead className="text-[9px] sm:text-[10px] font-display font-bold text-admin-text-primary uppercase tracking-[0.2em] p-3 sm:p-6 whitespace-nowrap">
                      FAMILIA / FABRICANTE
                    </TableHead>
                    <TableHead className="text-[9px] sm:text-[10px] font-display font-bold text-admin-text-primary uppercase tracking-[0.2em] p-3 sm:p-6 whitespace-nowrap">
                      FRECUENCIA
                    </TableHead>
                    <TableHead className="text-[9px] sm:text-[10px] font-display font-bold text-admin-text-primary uppercase tracking-[0.2em] p-3 sm:p-6 whitespace-nowrap">
                      MODALIDAD
                    </TableHead>
                    <TableHead className="text-[9px] sm:text-[10px] font-display font-bold text-admin-text-primary uppercase tracking-[0.2em] p-3 sm:p-6 whitespace-nowrap">
                      MATERIAL
                    </TableHead>
                    <TableHead className="text-[9px] sm:text-[10px] font-display font-bold text-admin-text-primary uppercase tracking-[0.2em] p-3 sm:p-6 whitespace-nowrap">
                      ESTADO
                    </TableHead>
                    <TableHead className="text-[10px] font-display font-bold text-admin-text-primary uppercase tracking-[0.2em] p-6 text-right">
                      ACCIONES
                    </TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {paginatedFamilies.map((family, idx) => {
                    const prevModality =
                      idx > 0 ? paginatedFamilies[idx - 1].modality : null;
                    const showGroupHeader = prevModality !== family.modality;
                    return (
                      <React.Fragment key={family.id}>
                        {showGroupHeader && (
                          <TableRow
                            className="bg-admin-bg-tertiary/40 hover:bg-transparent"
                            key={`group-${family.modality}-${idx}`}
                          >
                            <TableCell
                              className="p-2 sm:p-3 text-[9px] font-display font-bold text-admin-text-tertiary uppercase tracking-[0.2em]"
                              colSpan={6}
                            >
                              {MODALITIES.find(
                                (m) => m.value === family.modality,
                              )?.label || family.modality}
                            </TableCell>
                          </TableRow>
                        )}
                        <TableRow className="border-admin-border-primary/10 hover:bg-admin-bg-tertiary/50 transition-colors">
                          <TableCell className="p-3 sm:p-6">
                            <div className="space-y-1">
                              <div className="flex flex-wrap items-center gap-2">
                                <p className="text-sm font-display font-bold text-admin-text-primary uppercase tracking-tight">
                                  {family.name}
                                </p>
                                <Badge
                                  className="text-[8px] font-display font-bold tracking-widest uppercase border-admin-border-primary/20"
                                  variant="outline"
                                >
                                  {MODALITIES.find(
                                    (m) => m.value === family.modality,
                                  )?.label || family.modality}{" "}
                                  ·{" "}
                                  {USE_TYPES.find(
                                    (t) => t.value === family.use_type,
                                  )?.label || family.use_type}
                                </Badge>
                              </div>
                              <span className="text-[9px] font-display font-bold text-admin-text-tertiary tracking-widest uppercase bg-admin-bg-tertiary px-2 py-0.5 border border-admin-border-primary/5">
                                {family.brand || "FABRICANTE NO ASIGNADO"}
                              </span>
                            </div>
                          </TableCell>
                          <TableCell className="p-3 sm:p-6">
                            <span className="text-[10px] font-serif italic text-admin-text-primary uppercase tracking-wider">
                              {USE_TYPES.find(
                                (t) => t.value === family.use_type,
                              )?.label || family.use_type}
                            </span>
                          </TableCell>
                          <TableCell className="p-3 sm:p-6">
                            <span className="text-[10px] font-display font-bold text-admin-text-tertiary uppercase tracking-widest">
                              {MODALITIES.find(
                                (m) => m.value === family.modality,
                              )?.label || family.modality}
                            </span>
                          </TableCell>
                          <TableCell className="p-3 sm:p-6">
                            <span className="text-[10px] font-serif italic text-admin-text-tertiary">
                              {family.material || "Material Estándar"}
                            </span>
                          </TableCell>
                          <TableCell className="p-3 sm:p-6">
                            <div
                              className={`px-2 py-1 text-[8px] font-display font-bold tracking-widest uppercase inline-block border ${
                                family.is_active
                                  ? "bg-epoch-primary/5 text-epoch-primary border-epoch-primary/20"
                                  : "bg-admin-error/5 text-admin-error border-admin-error/20"
                              }`}
                            >
                              {family.is_active ? "ACTIVA" : "INACTIVA"}
                            </div>
                          </TableCell>
                          <TableCell className="p-3 sm:p-6 text-right">
                            <div className="flex justify-end gap-1">
                              <Button
                                className="h-8 w-8 p-0 rounded-xl hover:bg-admin-bg-tertiary text-epoch-primary"
                                size="sm"
                                variant="ghost"
                                onClick={() =>
                                  router.push(
                                    `/admin/contact-lens-families/${family.id}`,
                                  )
                                }
                              >
                                <Edit className="h-3.5 w-3.5" />
                              </Button>
                              <Button
                                className="h-8 w-8 p-0 rounded-xl hover:bg-admin-error/5 text-admin-error"
                                size="sm"
                                variant="ghost"
                                onClick={() => handleDelete(family.id)}
                              >
                                <Trash2 className="h-3.5 w-3.5" />
                              </Button>
                            </div>
                          </TableCell>
                        </TableRow>
                      </React.Fragment>
                    );
                  })}
                </TableBody>
              </Table>
            </div>
          )}

          {/* Pagination */}
          {!loading && filteredFamilies.length > 0 && (
            <div className="mt-4 px-4 sm:px-6 pb-4 sm:pb-6 overflow-x-auto min-w-0">
              <Pagination
                currentPage={currentPage}
                itemsPerPage={itemsPerPage}
                itemsPerPageOptions={[10, 20, 50, 100]}
                totalItems={totalFamilies}
                totalPages={totalPages}
                onItemsPerPageChange={setItemsPerPage}
                onPageChange={setCurrentPage}
              />
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { Check, ChevronsUpDown } from "lucide-react";
import { useCallback, useEffect, useState } from "react";

import { Button } from "@/components/ui/button";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { extractDataFromResponse } from "@/lib/api/response-helpers";
import { appLogger } from '@/lib/logger';
import { cn } from "@/lib/utils";

export interface ContactLensFamilyOption {
  id: string;
  name: string;
  brand?: string | null;
  use_type?: string;
  modality?: string;
}

interface ContactLensFamilyComboboxProps {
  value: string;
  onChange: (value: string) => void;
  /** Optional category slug filter (e.g. "lentes-contacto") */
  categorySlug?: string | null;
  /** Optional: use pre-fetched families. When not provided, fetches from API. */
  families?: ContactLensFamilyOption[];
  loading?: boolean;
  placeholder?: string;
  disabled?: boolean;
  className?: string;
}

export function ContactLensFamilyCombobox({
  value,
  onChange,
  categorySlug = null,
  families: familiesProp,
  loading: loadingProp,
  placeholder = "Selecciona familia (opcional)",
  disabled = false,
  className,
}: ContactLensFamilyComboboxProps) {
  const [open, setOpen] = useState(false);
  const [fetchedFamilies, setFetchedFamilies] = useState<
    ContactLensFamilyOption[]
  >([]);
  const [fetchLoading, setFetchLoading] = useState(false);
  const [search, setSearch] = useState("");

  const fetchFamilies = useCallback(
    async (searchTerm?: string) => {
      if (familiesProp != null) return;
      setFetchLoading(true);
      try {
        const params = new URLSearchParams();
        if (categorySlug) {
          params.set("category_slug", categorySlug);
        }
        if (searchTerm?.trim()) {
          params.set("search", searchTerm.trim());
        }
        const res = await fetch(
          `/api/admin/contact-lens-families?${params.toString()}`,
        );
        const json = await res.json();
        const data = extractDataFromResponse<ContactLensFamilyOption>(json);
        if (Array.isArray(json?.data)) {
          setFetchedFamilies(json.data);
        } else {
          setFetchedFamilies(Array.isArray(data) ? data : []);
        }
      } catch (err) {
        appLogger.error("Error fetching contact lens families:", err);
        setFetchedFamilies([]);
      } finally {
        setFetchLoading(false);
      }
    },
    [categorySlug, familiesProp],
  );

  useEffect(() => {
    fetchFamilies(search);
  }, [fetchFamilies, search]);

  const baseList = (familiesProp ?? fetchedFamilies).filter(
    (f) => (f as { is_active?: boolean }).is_active !== false,
  );
  const families = search.trim()
    ? baseList.filter(
        (f) =>
          f.name.toLowerCase().includes(search.toLowerCase()) ||
          (f.brand && f.brand.toLowerCase().includes(search.toLowerCase())),
      )
    : baseList;
  const loading = loadingProp ?? fetchLoading;

  const allForDisplay = familiesProp ?? fetchedFamilies;
  const displayValue = !value
    ? "Sin familia (manual)"
    : (() => {
        const f = allForDisplay.find((x) => x.id === value);
        return f ? `${f.name}${f.brand ? ` (${f.brand})` : ""}` : value;
      })();

  const handleSelect = (val: string) => {
    onChange(val || "");
    setOpen(false);
  };

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          aria-expanded={open}
          className={cn("w-full justify-between font-normal", className)}
          disabled={disabled || loading}
          role="combobox"
          variant="outline"
        >
          {loading ? "Cargando..." : displayValue || placeholder}
          <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent
        align="start"
        className="w-[var(--radix-popover-trigger-width)] p-0"
      >
        <Command shouldFilter={false}>
          <CommandInput
            placeholder="Buscar por nombre o marca..."
            value={search}
            onValueChange={setSearch}
          />
          <CommandList>
            <CommandEmpty>No se encontraron familias.</CommandEmpty>
            <CommandGroup>
              <CommandItem value="__manual__" onSelect={() => handleSelect("")}>
                <Check
                  className={cn(
                    "mr-2 h-4 w-4",
                    !value ? "opacity-100" : "opacity-0",
                  )}
                />
                Sin familia (manual)
              </CommandItem>
              {families.map((f) => (
                <CommandItem
                  key={f.id}
                  value={f.id}
                  onSelect={() => handleSelect(f.id)}
                >
                  <Check
                    className={cn(
                      "mr-2 h-4 w-4",
                      value === f.id ? "opacity-100" : "opacity-0",
                    )}
                  />
                  {f.name}
                  {f.brand ? ` (${f.brand})` : ""}
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}

"use client";

import { ArrowLeft, ArrowRight, Save } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";

import { FamilyInfoStep } from "./_components/FamilyInfoStep";
import { useContactLensFamilyWizard } from "./_hooks/useContactLensFamilyWizard";
import { ContactLensMatrixManager } from "./ContactLensMatrixManager";

interface ContactLensFamilyWizardProps { familyId?: string; }

export function ContactLensFamilyWizard({ familyId }: ContactLensFamilyWizardProps) {
  const { step, loading, initialLoading, categories, data, setData, errors, handleNext, handleBack, handleSubmit } = useContactLensFamilyWizard(familyId);

  if (initialLoading) {
    return <div className="max-w-4xl mx-auto flex items-center justify-center py-12">Cargando...</div>;
  }

  return (
    <div className="max-w-4xl mx-auto">
      <div className="flex items-center justify-center mb-8">
        <div className="flex items-center">
          <div className={`flex items-center justify-center w-10 h-10 rounded-full border-2 ${step >= 1 ? "bg-primary text-primary-foreground border-primary" : "border-gray-300 text-gray-500"}`}>1</div>
          <div className="ml-2 font-medium text-sm">Información</div>
        </div>
        <div className={`w-24 h-1 mx-4 ${step >= 2 ? "bg-primary" : "bg-gray-200"}`} />
        <div className="flex items-center">
          <div className={`flex items-center justify-center w-10 h-10 rounded-full border-2 ${step >= 2 ? "bg-primary text-primary-foreground border-primary" : "border-gray-300 text-gray-500"}`}>2</div>
          <div className="ml-2 font-medium text-sm">Matrices de Precios</div>
        </div>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>{step === 1 ? "Información de la Familia" : "Configuración de Matrices"}</CardTitle>
        </CardHeader>
        <CardContent className="space-y-6">
          {step === 1 && <FamilyInfoStep categories={categories} data={data} errors={errors} onChange={(d) => setData((prev) => ({ ...prev, ...d }))} />}
          {step === 2 && <ContactLensMatrixManager matrices={data.matrices} onChange={(matrices) => setData((prev) => ({ ...prev, matrices }))} />}
          <div className="flex justify-between pt-4">
            <Button type="button" variant="outline" onClick={step === 1 ? () => window.history.back() : handleBack}>
              <ArrowLeft className="h-4 w-4 mr-2" />{step === 1 ? "Volver" : "Atrás"}
            </Button>
            {step === 1 ? (
              <Button onClick={handleNext}>Siguiente<ArrowRight className="h-4 w-4 ml-2" /></Button>
            ) : (
              <Button disabled={loading} onClick={handleSubmit}>
                {loading ? "Guardando..." : <><Save className="h-4 w-4 mr-2" />{familyId ? "Actualizar Familia" : "Crear Familia"}</>}
              </Button>
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

/**
 * ContactLensInventoryManager - Componente para gestionar inventario de LC
 * Se integra dentro de la pestaña Contactología
 */

"use client";

import { useEffect,useState } from "react";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {  type ContactLensInventory,
  contactLensInventoryService,
} from "@/lib/api/services/contactLensInventoryService";
import { appLogger } from '@/lib/logger';

interface ContactLensFamily {
  id: string;
  name: string;
  brand: string | null;
}

interface ContactLensInventoryManagerProps {
  families: ContactLensFamily[];
  branchId: string | null;
}

export default function ContactLensInventoryManager({
  families,
  branchId,
}: ContactLensInventoryManagerProps) {
  const [selectedFamilyId, setSelectedFamilyId] = useState<string>("");

  const [inventory, setInventory] = useState<ContactLensInventory[]>([]);
  const [loading, setLoading] = useState(false);

  // Dialog state
  const [showAddDialog, setShowAddDialog] = useState(false);
  const [editingItem, setEditingItem] = useState<ContactLensInventory | null>(
    null,
  );

  // Form state
  const [formData, setFormData] = useState({
    sphereMin: "",
    sphereMax: "",
    cylinderMin: "0",
    cylinderMax: "0",
    quantity: "",
    minStockThreshold: "3",
  });

  // Load inventory when family or branch changes
  useEffect(() => {
    if (selectedFamilyId && branchId) {
      loadInventory();
    }
  }, [selectedFamilyId, branchId]);

  const loadInventory = async () => {
    if (!selectedFamilyId || !branchId) return;
    setLoading(true);
    try {
      const data = await contactLensInventoryService.getInventory(
        selectedFamilyId,
        branchId,
      );
      setInventory(data);
    } catch (error) {
      appLogger.error("Error loading inventory:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleAddNew = () => {
    setEditingItem(null);
    setFormData({
      sphereMin: "",
      sphereMax: "",
      cylinderMin: "0",
      cylinderMax: "0",
      quantity: "",
      minStockThreshold: "3",
    });
    setShowAddDialog(true);
  };

  const handleEdit = (item: ContactLensInventory) => {
    setEditingItem(item);
    setFormData({
      sphereMin: item.sphere_min.toString(),
      sphereMax: item.sphere_max.toString(),
      cylinderMin: item.cylinder_min.toString(),
      cylinderMax: item.cylinder_max.toString(),
      quantity: item.quantity.toString(),
      minStockThreshold: item.min_stock_threshold.toString(),
    });
    setShowAddDialog(true);
  };

  const handleSave = async () => {
    if (!selectedFamilyId || !branchId) return;

    const data = {
      contact_lens_family_id: selectedFamilyId,
      branch_id: branchId,
      sphere_min: parseFloat(formData.sphereMin),
      sphere_max: parseFloat(formData.sphereMax),
      cylinder_min: parseFloat(formData.cylinderMin),
      cylinder_max: parseFloat(formData.cylinderMax),
      quantity: parseInt(formData.quantity),
      min_stock_threshold: parseInt(formData.minStockThreshold),
    };

    try {
      await contactLensInventoryService.createInventory(data);
      toast.success("Inventario actualizado correctamente");
      setShowAddDialog(false);
      loadInventory();
    } catch (error) {
      appLogger.error("Error saving inventory:", error);
      toast.error("Error al guardar inventario");
    }
  };

  const selectedFamily = families.find((f) => f.id === selectedFamilyId);

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h3 className="text-sm font-display font-bold text-admin-text-primary uppercase tracking-[0.2em]">
            Inventario por Graduación
          </h3>
          <p className="text-[10px] font-serif italic text-admin-text-tertiary uppercase tracking-widest">
            Control de stock disponible por esfera y cilindro
          </p>
        </div>
        <div className="flex gap-2">
          <Select value={selectedFamilyId} onValueChange={setSelectedFamilyId}>
            <SelectTrigger className="w-64">
              <SelectValue placeholder="Selecciona una familia" />
            </SelectTrigger>
            <SelectContent>
              {families.map((family) => (
                <SelectItem key={family.id} value={family.id}>
                  {family.name} ({family.brand})
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          {selectedFamilyId && branchId && (
            <Button size="sm" onClick={handleAddNew}>
              Agregar Stock
            </Button>
          )}
        </div>
      </div>

      {/* Inventory Table */}
      {selectedFamilyId && branchId ? (
        loading ? (
          <div className="text-center py-8 text-muted-foreground">
            Cargando inventario...
          </div>
        ) : inventory.length === 0 ? (
          <Card className="bg-admin-bg-tertiary">
            <CardContent className="p-8 text-center">
              <p className="text-muted-foreground">
                No hay inventario registrado para esta familia
              </p>
              <Button className="mt-4" variant="outline" onClick={handleAddNew}>
                Agregar primera entrada de inventario
              </Button>
            </CardContent>
          </Card>
        ) : (
          <Card className="bg-admin-bg-tertiary">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Esfera</TableHead>
                  <TableHead>Cilindro</TableHead>
                  <TableHead>Cantidad</TableHead>
                  <TableHead>Stock Mínimo</TableHead>
                  <TableHead>Estado</TableHead>
                  <TableHead className="text-right">Acciones</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {inventory.map((item) => (
                  <TableRow key={item.id}>
                    <TableCell>
                      {item.sphere_min === item.sphere_max
                        ? `${item.sphere_min.toFixed(2)}`
                        : `${item.sphere_min.toFixed(2)} a ${item.sphere_max.toFixed(2)}`}
                    </TableCell>
                    <TableCell>
                      {item.cylinder_min === 0 && item.cylinder_max === 0
                        ? "Esférico"
                        : `${item.cylinder_min.toFixed(2)} a ${item.cylinder_max.toFixed(2)}`}
                    </TableCell>
                    <TableCell className="font-bold">{item.quantity}</TableCell>
                    <TableCell>{item.min_stock_threshold}</TableCell>
                    <TableCell>
                      {item.quantity > item.min_stock_threshold ? (
                        <Badge className="bg-green-100 text-green-700">
                          Disponible
                        </Badge>
                      ) : item.quantity > 0 ? (
                        <Badge className="bg-yellow-100 text-yellow-700">
                          Bajo
                        </Badge>
                      ) : (
                        <Badge className="bg-red-100 text-red-700">
                          Sin Stock
                        </Badge>
                      )}
                    </TableCell>
                    <TableCell className="text-right">
                      <Button
                        size="sm"
                        variant="ghost"
                        onClick={() => handleEdit(item)}
                      >
                        Editar
                      </Button>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </Card>
        )
      ) : (
        <Card className="bg-admin-bg-tertiary">
          <CardContent className="p-8 text-center">
            <p className="text-muted-foreground">
              Selecciona una familia de lentes de contacto para ver su
              inventario
            </p>
          </CardContent>
        </Card>
      )}

      {/* Add/Edit Dialog */}
      <Dialog open={showAddDialog} onOpenChange={setShowAddDialog}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>
              {editingItem ? "Editar Inventario" : "Agregar Inventario"}
            </DialogTitle>
            <DialogDescription>
              Configura el stock disponible para un rango de graduación
            </DialogDescription>
          </DialogHeader>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label>Esfera Mínima</Label>
              <Input
                placeholder="-6.00"
                step="0.25"
                type="number"
                value={formData.sphereMin}
                onChange={(e) =>
                  setFormData({ ...formData, sphereMin: e.target.value })
                }
              />
            </div>
            <div>
              <Label>Esfera Máxima</Label>
              <Input
                placeholder="-0.50"
                step="0.25"
                type="number"
                value={formData.sphereMax}
                onChange={(e) =>
                  setFormData({ ...formData, sphereMax: e.target.value })
                }
              />
            </div>
            <div>
              <Label>Cilindro Mínimo</Label>
              <Input
                placeholder="0"
                step="0.25"
                type="number"
                value={formData.cylinderMin}
                onChange={(e) =>
                  setFormData({ ...formData, cylinderMin: e.target.value })
                }
              />
            </div>
            <div>
              <Label>Cilindro Máximo</Label>
              <Input
                placeholder="0"
                step="0.25"
                type="number"
                value={formData.cylinderMax}
                onChange={(e) =>
                  setFormData({ ...formData, cylinderMax: e.target.value })
                }
              />
            </div>
            <div>
              <Label>Cantidad (Cajas)</Label>
              <Input
                placeholder="10"
                type="number"
                value={formData.quantity}
                onChange={(e) =>
                  setFormData({ ...formData, quantity: e.target.value })
                }
              />
            </div>
            <div>
              <Label>Stock Mínimo</Label>
              <Input
                placeholder="3"
                type="number"
                value={formData.minStockThreshold}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    minStockThreshold: e.target.value,
                  })
                }
              />
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setShowAddDialog(false)}>
              Cancelar
            </Button>
            <Button onClick={handleSave}>Guardar</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

import { Edit, Eye, EyeOff, Plus, RefreshCw, Search, Trash2 } from "lucide-react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Pagination } from "@/components/ui/pagination";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { formatCurrency } from "@/lib/utils";

import { ContactLensMatrixDialog } from "./_components/ContactLensMatrixDialog";
import { useContactLensMatrices } from "./_hooks/useContactLensMatrices";

export default function ContactLensMatricesList() {
  const {
    matrices, families, loading, searchTerm, setSearchTerm,
    selectedFamilyId, setSelectedFamilyId, includeInactive, setIncludeInactive,
    showDialog, setShowDialog, editingMatrix, formData, setFormData,
    currentPage, setCurrentPage, itemsPerPage, setItemsPerPage,
    totalMatrices, totalPages, fetchMatrices,
    handleSubmit, handleDelete, openEditDialog, openCreateDialog,
  } = useContactLensMatrices();

  return (
    <Card>
      <CardHeader>
        <div className="flex justify-between items-center">
          <CardTitle>Matrices de Precios de Lentes de Contacto</CardTitle>
          <div className="flex gap-2">
            <Button size="sm" variant="outline" onClick={() => setIncludeInactive(!includeInactive)}>
              {includeInactive ? <><EyeOff className="h-4 w-4 mr-2" />Ocultar Inactivas</> : <><Eye className="h-4 w-4 mr-2" />Mostrar Inactivas</>}
            </Button>
            <Button size="sm" variant="outline" onClick={fetchMatrices}><RefreshCw className="h-4 w-4" /></Button>
            <Button onClick={openCreateDialog}><Plus className="h-4 w-4 mr-2" />Nueva Matriz</Button>
          </div>
        </div>
      </CardHeader>
      <CardContent>
        <div className="mb-4 flex flex-col sm:flex-row gap-4">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input className="pl-10" placeholder="Buscar por familia, marca o rango de esfera..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
          </div>
          <div className="w-full sm:w-64">
            <Select value={selectedFamilyId} onValueChange={setSelectedFamilyId}>
              <SelectTrigger><SelectValue placeholder="Todas las familias" /></SelectTrigger>
              <SelectContent><SelectItem value="all">Todas las familias</SelectItem>{families.map((f) => <SelectItem key={f.id} value={f.id}>{f.name}</SelectItem>)}</SelectContent>
            </Select>
          </div>
        </div>

        {loading ? (
          <div className="text-center py-8">Cargando...</div>
        ) : matrices.length === 0 ? (
          <div className="text-center py-8 text-muted-foreground">No se encontraron matrices de precios</div>
        ) : (
          <div className="overflow-x-auto">
            <Table>
              <TableHeader>
                <TableRow><TableHead>Familia</TableHead><TableHead>Marca</TableHead><TableHead>Rango Esfera</TableHead><TableHead>Rango Cilindro</TableHead><TableHead>Precio Base</TableHead><TableHead>Costo</TableHead><TableHead>Estado</TableHead><TableHead className="text-right">Acciones</TableHead></TableRow>
              </TableHeader>
              <TableBody>
                {matrices.map((matrix) => {
                  const family = matrix.contact_lens_families;
                  return (
                    <TableRow key={matrix.id}>
                      <TableCell className="font-medium">{family.name}</TableCell>
                      <TableCell>{family.brand || "-"}</TableCell>
                      <TableCell>{matrix.sphere_min} a {matrix.sphere_max}</TableCell>
                      <TableCell>{matrix.cylinder_min != null && matrix.cylinder_max != null ? `${matrix.cylinder_min} a ${matrix.cylinder_max}` : "N/A"}</TableCell>
                      <TableCell>{formatCurrency(matrix.base_price)}</TableCell>
                      <TableCell>{formatCurrency(matrix.cost)}</TableCell>
                      <TableCell><Badge variant={matrix.is_active ? "default" : "secondary"}>{matrix.is_active ? "Activa" : "Inactiva"}</Badge></TableCell>
                      <TableCell className="text-right">
                        <div className="flex justify-end gap-2">
                          <Button size="sm" variant="ghost" onClick={() => openEditDialog(matrix)}><Edit className="h-4 w-4" /></Button>
                          <Button size="sm" variant="ghost" onClick={() => handleDelete(matrix.id)}><Trash2 className="h-4 w-4" /></Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          </div>
        )}

        {!loading && totalMatrices > 0 && (
          <div className="mt-4">
            <Pagination currentPage={currentPage} itemsPerPage={itemsPerPage} itemsPerPageOptions={[10, 20, 50, 100]} totalItems={totalMatrices} totalPages={totalPages} onItemsPerPageChange={setItemsPerPage} onPageChange={setCurrentPage} />
          </div>
        )}

        <ContactLensMatrixDialog editingMatrix={editingMatrix} families={families} formData={formData} open={showDialog} onFormChange={setFormData} onOpenChange={setShowDialog} onSubmit={handleSubmit} />
      </CardContent>
    </Card>
  );
}

"use client";

import { Edit, Plus, Trash2 } from "lucide-react";
import { useState } from "react";

import { Button } from "@/components/ui/button";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { CONTACT_LENS_DEFAULT_MATRICES } from "@/lib/lens-matrices/constants";
import { formatCurrency } from "@/lib/utils";

import { MatrixEditDialog } from "./_components/MatrixEditDialog";
import { MatrixSuggestionSection } from "./_components/MatrixSuggestionSection";

export interface ContactLensMatrixFormData {
  id: string; name?: string | null; sphere_min: number; sphere_max: number;
  cylinder_min: number; cylinder_max: number; axis_min: number; axis_max: number;
  addition_min: number; addition_max: number; base_price: number; cost: number; is_active: boolean;
}

interface ContactLensMatrixManagerProps {
  matrices: ContactLensMatrixFormData[];
  onChange: (matrices: ContactLensMatrixFormData[]) => void;
  readOnly?: boolean;
}

export function ContactLensMatrixManager({ matrices, onChange, readOnly = false }: ContactLensMatrixManagerProps) {
  const [showDialog, setShowDialog] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [suggestionOpen, setSuggestionOpen] = useState(matrices.length === 0);
  const [formData, setFormData] = useState({
    name: "", sphere_min: "-6.00", sphere_max: "6.00", cylinder_min: "-2.00", cylinder_max: "2.00",
    axis_min: "0", axis_max: "180", addition_min: "0.00", addition_max: "4.00", base_price: "0", cost: "0", is_active: true,
  });

  const handleApplyTemplate = () => {
    const newMatrices = CONTACT_LENS_DEFAULT_MATRICES.map((r, i) => ({
      id: `temp-${Date.now()}-${i}`, name: r.name, sphere_min: r.sphere_min, sphere_max: r.sphere_max,
      cylinder_min: r.cylinder_min, cylinder_max: r.cylinder_max, axis_min: r.axis_min, axis_max: r.axis_max,
      addition_min: r.addition_min, addition_max: r.addition_max, base_price: r.base_price, cost: r.cost, is_active: true,
    }));
    onChange([...matrices, ...newMatrices]);
  };

  const handleOpenDialog = (matrix?: ContactLensMatrixFormData) => {
    if (matrix) {
      setEditingId(matrix.id);
      setFormData({
        name: matrix.name ?? "", sphere_min: matrix.sphere_min.toString(), sphere_max: matrix.sphere_max.toString(),
        cylinder_min: matrix.cylinder_min.toString(), cylinder_max: matrix.cylinder_max.toString(),
        axis_min: matrix.axis_min.toString(), axis_max: matrix.axis_max.toString(),
        addition_min: matrix.addition_min.toString(), addition_max: matrix.addition_max.toString(),
        base_price: matrix.base_price.toString(), cost: matrix.cost.toString(), is_active: matrix.is_active,
      });
    } else {
      setEditingId(null);
      setFormData({ name: "", sphere_min: "-6.00", sphere_max: "6.00", cylinder_min: "-2.00", cylinder_max: "2.00", axis_min: "0", axis_max: "180", addition_min: "0.00", addition_max: "4.00", base_price: "0", cost: "0", is_active: true });
    }
    setShowDialog(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newMatrix: ContactLensMatrixFormData = {
      id: editingId || `temp-${Date.now()}`, name: formData.name?.trim() || undefined,
      sphere_min: parseFloat(formData.sphere_min), sphere_max: parseFloat(formData.sphere_max),
      cylinder_min: parseFloat(formData.cylinder_min), cylinder_max: parseFloat(formData.cylinder_max),
      axis_min: parseInt(formData.axis_min, 10), axis_max: parseInt(formData.axis_max, 10),
      addition_min: parseFloat(formData.addition_min), addition_max: parseFloat(formData.addition_max),
      base_price: parseFloat(formData.base_price), cost: parseFloat(formData.cost), is_active: formData.is_active,
    };
    onChange(editingId ? matrices.map((m) => m.id === editingId ? newMatrix : m) : [...matrices, newMatrix]);
    setShowDialog(false);
  };

  const handleDelete = (id: string) => { if (confirm("¿Estás seguro de eliminar esta matriz?")) onChange(matrices.filter((m) => m.id !== id)); };

  return (
    <div className="space-y-4">
      {!readOnly && <MatrixSuggestionSection open={suggestionOpen} onApplyTemplate={handleApplyTemplate} onToggle={() => setSuggestionOpen(!suggestionOpen)} />}
      <div className="flex justify-between items-center">
        <h3 className="text-lg font-medium">Matrices de Precios</h3>
        {!readOnly && <Button size="sm" variant="outline" onClick={() => handleOpenDialog()}><Plus className="h-4 w-4 mr-2" />Agregar Matriz</Button>}
      </div>

      {matrices.length === 0 ? (
        <div className="text-center p-8 border rounded-lg bg-gray-50 text-gray-500">No hay matrices de precios definidas. Agrega al menos una.</div>
      ) : (
        <div className="border rounded-lg overflow-x-auto">
          <Table>
            <TableHeader>
              <TableRow><TableHead>Nombre</TableHead><TableHead>Esfera</TableHead><TableHead>Cilindro</TableHead><TableHead>Eje</TableHead><TableHead>Adición</TableHead><TableHead>Precio</TableHead><TableHead>Costo</TableHead>{!readOnly && <TableHead className="text-right">Acciones</TableHead>}</TableRow>
            </TableHeader>
            <TableBody>
              {matrices.map((matrix) => (
                <TableRow key={matrix.id}>
                  <TableCell>{matrix.name || `${matrix.sphere_min} a ${matrix.sphere_max}`}</TableCell>
                  <TableCell>{matrix.sphere_min} a {matrix.sphere_max}</TableCell>
                  <TableCell>{matrix.cylinder_min} a {matrix.cylinder_max}</TableCell>
                  <TableCell>{matrix.axis_min} a {matrix.axis_max}</TableCell>
                  <TableCell>{matrix.addition_min} a {matrix.addition_max}</TableCell>
                  <TableCell>{formatCurrency(matrix.base_price)}</TableCell>
                  <TableCell>{formatCurrency(matrix.cost)}</TableCell>
                  {!readOnly && <TableCell className="text-right"><div className="flex justify-end gap-2"><Button size="sm" variant="ghost" onClick={() => handleOpenDialog(matrix)}><Edit className="h-4 w-4" /></Button><Button size="sm" variant="ghost" onClick={() => handleDelete(matrix.id)}><Trash2 className="h-4 w-4" /></Button></div></TableCell>}
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>
      )}

      <MatrixEditDialog editingId={editingId} formData={formData} open={showDialog} onFormChange={setFormData} onOpenChange={setShowDialog} onSubmit={handleSubmit} />
    </div>
  );
}

"use client";

import { Edit, Eye, EyeOff, RefreshCw, Search, Trash2 } from "lucide-react";
import { useRouter } from "next/navigation";
import React, { useEffect, useState } from "react";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Pagination } from "@/components/ui/pagination";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { appLogger } from '@/lib/logger';

interface LensFamily {
  id: string;
  name: string;
  brand: string | null;
  lens_type: string;
  lens_material: string;
  description: string | null;
  is_active: boolean;
  created_at: string;
  updated_at: string;
}

const LENS_TYPES = [
  { value: "single_vision", label: "Monofocal" },
  { value: "bifocal", label: "Bifocal" },
  { value: "trifocal", label: "Trifocal" },
  { value: "progressive", label: "Progresivo" },
  { value: "reading", label: "Lectura" },
  { value: "computer", label: "Computadora" },
  { value: "sports", label: "Deportivo" },
];

const LENS_MATERIALS = [
  { value: "cr39", label: "CR-39" },
  { value: "polycarbonate", label: "Policarbonato" },
  { value: "high_index_1_67", label: "Alto Índice 1.67" },
  { value: "high_index_1_74", label: "Alto Índice 1.74" },
  { value: "trivex", label: "Trivex" },
  { value: "glass", label: "Vidrio" },
];

export default function LensFamiliesList() {
  const router = useRouter();

  const [families, setFamilies] = useState<LensFamily[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [lensTypeFilter, setLensTypeFilter] = useState<string>("all");
  const [includeInactive, setIncludeInactive] = useState(false);

  // Pagination state
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage, setItemsPerPage] = useState(20);

  useEffect(() => {
    fetchFamilies();
  }, [includeInactive, lensTypeFilter]);

  const fetchFamilies = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams();
      if (includeInactive) {
        params.append("include_inactive", "true");
      }
      if (lensTypeFilter && lensTypeFilter !== "all") {
        params.append("lens_type", lensTypeFilter);
      }
      const response = await fetch(
        `/api/admin/lens-families?${params.toString()}`,
      );
      if (response.ok) {
        const result = await response.json();
        setFamilies(result.data ?? result.families ?? []);
      } else {
        toast.error("Error al cargar familias de lentes");
      }
    } catch (error) {
      appLogger.error("Error fetching families:", error);
      toast.error("Error al cargar familias de lentes");
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("¿Estás seguro de que deseas eliminar esta familia?")) {
      return;
    }

    try {
      const response = await fetch(`/api/admin/lens-families/${id}`, {
        method: "DELETE",
      });

      if (!response.ok) {
        throw new Error("Error al eliminar familia");
      }

      toast.success("Familia eliminada exitosamente");
      fetchFamilies();
    } catch (error) {
      toast.error("Error al eliminar familia");
    }
  };

  const filteredFamilies = families.filter((family) => {
    const searchLower = searchTerm.toLowerCase();
    return (
      family.name.toLowerCase().includes(searchLower) ||
      (family.brand || "").toLowerCase().includes(searchLower) ||
      family.lens_type.toLowerCase().includes(searchLower) ||
      family.lens_material.toLowerCase().includes(searchLower)
    );
  });

  // Pagination calculations
  const totalFamilies = filteredFamilies.length;
  const startIndex = (currentPage - 1) * itemsPerPage;
  const endIndex = startIndex + itemsPerPage;
  const paginatedFamilies = filteredFamilies.slice(startIndex, endIndex);
  const totalPages = Math.ceil(totalFamilies / itemsPerPage);

  // Reset to page 1 when filters change
  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, includeInactive, lensTypeFilter]);

  return (
    <div className="py-6 space-y-8">
      <div className="border-b border-admin-border-primary/10 pb-6">
        <div className="space-y-1">
          <h2 className="text-sm font-display font-bold text-admin-text-primary uppercase tracking-[0.2em] flex items-center">
            Matriz de Familias de Lentes
          </h2>
          <p className="text-[10px] font-serif italic text-admin-text-tertiary uppercase tracking-widest">
            Protocolos de Materiales y Tratamientos por Marca
          </p>
        </div>
      </div>

      <Card className="border border-admin-border-primary/20 bg-admin-bg-tertiary rounded-xl shadow-none overflow-hidden">
        <CardHeader className="bg-admin-bg-tertiary/50 border-b border-admin-border-primary/10 py-4 sm:py-6 px-4 sm:px-6">
          <div className="flex flex-col sm:flex-row justify-between items-stretch sm:items-center gap-3">
            <div className="flex items-center gap-2">
              <RefreshCw className="h-4 w-4 text-epoch-primary opacity-50" />
              <h3 className="text-[11px] font-display font-bold text-admin-text-primary uppercase tracking-[0.2em]">
                Registro de Familias de Lentes Oftálmicos (
                {filteredFamilies.length})
              </h3>
            </div>
            <div className="flex flex-wrap gap-2">
              <Button
                className={`rounded-xl text-[9px] font-display font-bold tracking-widest uppercase h-auto py-2 border-none ${
                  includeInactive
                    ? "bg-admin-error/10 text-admin-error"
                    : "hover:bg-admin-bg-tertiary text-admin-text-tertiary"
                }`}
                size="sm"
                variant="ghost"
                onClick={() => setIncludeInactive(!includeInactive)}
              >
                {includeInactive ? (
                  <>
                    <EyeOff className="h-3 w-3 mr-2" />
                    OCULTAR INACTIVAS
                  </>
                ) : (
                  <>
                    <Eye className="h-3 w-3 mr-2" />
                    MOSTRAR INACTIVAS
                  </>
                )}
              </Button>
              <Button
                className="h-8 w-8 p-0 border-none hover:bg-admin-bg-tertiary text-epoch-primary"
                size="sm"
                variant="ghost"
                onClick={fetchFamilies}
              >
                <RefreshCw
                  className={`h-4 w-4 ${loading ? "animate-spin" : ""}`}
                />
              </Button>
            </div>
          </div>
        </CardHeader>
        <CardContent className="p-0">
          <div className="p-3 sm:p-6 border-b border-admin-border-primary/10 bg-admin-bg-tertiary/20">
            <div className="flex flex-col sm:flex-row gap-3">
              <div className="relative flex-1">
                <Search className="absolute left-3 sm:left-4 top-1/2 transform -translate-y-1/2 h-4 w-4 text-admin-text-tertiary opacity-40" />
                <Input
                  className="pl-10 sm:pl-12 rounded-xl border-admin-border-primary/10 focus:border-epoch-primary focus:ring-0 bg-white p-3 sm:p-6 text-[9px] sm:text-[10px] font-display font-bold tracking-widest uppercase"
                  placeholder="Buscar por nombre, marca o material..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
              </div>
              <div className="w-full sm:w-48">
                <Select
                  value={lensTypeFilter}
                  onValueChange={setLensTypeFilter}
                >
                  <SelectTrigger className="rounded-xl border-admin-border-primary/10 h-auto p-3 sm:p-6 text-[9px] sm:text-[10px] font-display font-bold tracking-widest uppercase">
                    <SelectValue placeholder="Tipo de lente" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">Todos los tipos</SelectItem>
                    {LENS_TYPES.map((t) => (
                      <SelectItem key={t.value} value={t.value}>
                        {t.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
          </div>

          {loading ? (
            <div className="text-center py-24 bg-admin-bg-tertiary/10">
              <RefreshCw className="h-8 w-8 text-epoch-primary animate-spin mx-auto mb-4 opacity-30" />
              <p className="text-[10px] font-display font-bold text-admin-text-tertiary uppercase tracking-widest">
                SINCRONIZANDO MATRIZ...
              </p>
            </div>
          ) : paginatedFamilies.length === 0 ? (
            <div className="text-center py-24 bg-admin-bg-tertiary/10 border-2 border-dashed border-admin-border-primary/5 m-6">
              <EyeOff className="h-12 w-12 text-admin-text-tertiary mx-auto mb-4 opacity-20" />
              <h3 className="text-xs font-display font-bold text-admin-text-primary uppercase tracking-[0.2em]">
                REGISTRO NO ENCONTRADO
              </h3>
              <p className="text-[10px] font-serif italic text-admin-text-tertiary uppercase tracking-widest mt-2">
                No existen familias vinculadas bajo los criterios actuales
              </p>
            </div>
          ) : (
            <div className="overflow-x-auto min-w-0 -mx-2 sm:mx-0 px-2 sm:px-0">
              <Table className="min-w-[600px]">
                <TableHeader className="bg-admin-bg-tertiary/30">
                  <TableRow className="hover:bg-transparent border-admin-border-primary/10">
                    <TableHead className="text-[9px] sm:text-[10px] font-display font-bold text-admin-text-primary uppercase tracking-[0.2em] p-3 sm:p-6 whitespace-nowrap">
                      MARCA / FAMILIA
                    </TableHead>
                    <TableHead className="text-[9px] sm:text-[10px] font-display font-bold text-admin-text-primary uppercase tracking-[0.2em] p-3 sm:p-6 whitespace-nowrap">
                      TIPO DE LENTE
                    </TableHead>
                    <TableHead className="text-[9px] sm:text-[10px] font-display font-bold text-admin-text-primary uppercase tracking-[0.2em] p-3 sm:p-6 whitespace-nowrap">
                      MATERIAL BASE
                    </TableHead>
                    <TableHead className="text-[9px] sm:text-[10px] font-display font-bold text-admin-text-primary uppercase tracking-[0.2em] p-3 sm:p-6 whitespace-nowrap">
                      COMENTARIOS
                    </TableHead>
                    <TableHead className="text-[9px] sm:text-[10px] font-display font-bold text-admin-text-primary uppercase tracking-[0.2em] p-3 sm:p-6 whitespace-nowrap">
                      ESTADO
                    </TableHead>
                    <TableHead className="text-[10px] font-display font-bold text-admin-text-primary uppercase tracking-[0.2em] p-6 text-right">
                      ACCIONES
                    </TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {paginatedFamilies.map((family, idx) => {
                    const prevType =
                      idx > 0 ? paginatedFamilies[idx - 1].lens_type : null;
                    const showGroupHeader = prevType !== family.lens_type;
                    return (
                      <React.Fragment key={family.id}>
                        {showGroupHeader && (
                          <TableRow
                            className="bg-admin-bg-tertiary/40 hover:bg-transparent"
                            key={`group-${family.lens_type}-${idx}`}
                          >
                            <TableCell
                              className="p-2 sm:p-3 text-[9px] font-display font-bold text-admin-text-tertiary uppercase tracking-[0.2em]"
                              colSpan={6}
                            >
                              {LENS_TYPES.find(
                                (t) => t.value === family.lens_type,
                              )?.label || family.lens_type}
                            </TableCell>
                          </TableRow>
                        )}
                        <TableRow
                          className="border-admin-border-primary/10 hover:bg-admin-bg-tertiary/50 transition-colors"
                          key={family.id}
                        >
                          <TableCell className="p-3 sm:p-6">
                            <div className="space-y-1">
                              <div className="flex flex-wrap items-center gap-2">
                                <p className="text-sm font-display font-bold text-admin-text-primary uppercase tracking-tight">
                                  {family.name}
                                </p>
                                <Badge
                                  className="text-[8px] font-display font-bold tracking-widest uppercase border-admin-border-primary/20"
                                  variant="outline"
                                >
                                  {LENS_TYPES.find(
                                    (t) => t.value === family.lens_type,
                                  )?.label || family.lens_type}{" "}
                                  ·{" "}
                                  {LENS_MATERIALS.find(
                                    (m) => m.value === family.lens_material,
                                  )?.label || family.lens_material}
                                </Badge>
                              </div>
                              <span className="text-[9px] font-display font-bold text-admin-text-tertiary tracking-widest uppercase bg-admin-bg-tertiary px-2 py-0.5 border border-admin-border-primary/5">
                                {family.brand || "MARCA GENÉRICA"}
                              </span>
                            </div>
                          </TableCell>
                          <TableCell className="p-3 sm:p-6">
                            <span className="text-[10px] font-serif italic text-admin-text-primary uppercase tracking-wider">
                              {
                                LENS_TYPES.find(
                                  (t) => t.value === family.lens_type,
                                )?.label
                              }
                            </span>
                          </TableCell>
                          <TableCell className="p-3 sm:p-6">
                            <span className="text-[10px] font-display font-bold text-admin-text-tertiary uppercase tracking-widest">
                              {
                                LENS_MATERIALS.find(
                                  (m) => m.value === family.lens_material,
                                )?.label
                              }
                            </span>
                          </TableCell>
                          <TableCell className="p-3 sm:p-6">
                            <p className="text-[10px] font-serif italic text-admin-text-tertiary max-w-[200px] truncate">
                              {family.description || "Sin anotaciones técnicas"}
                            </p>
                          </TableCell>
                          <TableCell className="p-3 sm:p-6">
                            <div
                              className={`px-2 py-1 text-[8px] font-display font-bold tracking-widest uppercase inline-block border ${
                                family.is_active
                                  ? "bg-epoch-primary/5 text-epoch-primary border-epoch-primary/20"
                                  : "bg-admin-error/5 text-admin-error border-admin-error/20"
                              }`}
                            >
                              {family.is_active ? "ACTIVA" : "INACTIVA"}
                            </div>
                          </TableCell>
                          <TableCell className="p-3 sm:p-6 text-right">
                            <div className="flex justify-end gap-1">
                              <Button
                                className="h-8 w-8 p-0 rounded-xl hover:bg-admin-bg-tertiary text-epoch-primary"
                                size="sm"
                                variant="ghost"
                                onClick={() =>
                                  router.push(
                                    `/admin/lens-families/${family.id}`,
                                  )
                                }
                              >
                                <Edit className="h-3.5 w-3.5" />
                              </Button>
                              <Button
                                className="h-8 w-8 p-0 rounded-xl hover:bg-admin-error/5 text-admin-error"
                                size="sm"
                                variant="ghost"
                                onClick={() => handleDelete(family.id)}
                              >
                                <Trash2 className="h-3.5 w-3.5" />
                              </Button>
                            </div>
                          </TableCell>
                        </TableRow>
                      </React.Fragment>
                    );
                  })}
                </TableBody>
              </Table>
            </div>
          )}

          {/* Pagination */}
          {!loading && filteredFamilies.length > 0 && (
            <div className="mt-4 px-4 sm:px-6 pb-4 sm:pb-6 overflow-x-auto min-w-0">
              <Pagination
                currentPage={currentPage}
                itemsPerPage={itemsPerPage}
                itemsPerPageOptions={[10, 20, 50, 100]}
                totalItems={totalFamilies}
                totalPages={totalPages}
                onItemsPerPageChange={setItemsPerPage}
                onPageChange={setCurrentPage}
              />
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";

import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";

export interface LensFamilyFormData {
  name: string;
  brand: string;
  category_id: string | null;
  lens_type: string;
  lens_material: string;
  description: string;
  is_active: boolean;
}

interface LensFamilyBasicFormProps {
  data: LensFamilyFormData;
  onChange: (data: LensFamilyFormData) => void;
  errors?: Record<string, string>;
}

export const LENS_TYPES = [
  { value: "single_vision", label: "Monofocal" },
  { value: "bifocal", label: "Bifocal" },
  { value: "trifocal", label: "Trifocal" },
  { value: "progressive", label: "Progresivo" },
  { value: "reading", label: "Lectura" },
  { value: "computer", label: "Computadora" },
  { value: "sports", label: "Deportivo" },
];

export const LENS_MATERIALS = [
  { value: "cr39", label: "CR-39" },
  { value: "polycarbonate", label: "Policarbonato" },
  { value: "high_index_1_67", label: "Alto Índice 1.67" },
  { value: "high_index_1_74", label: "Alto Índice 1.74" },
  { value: "trivex", label: "Trivex" },
  { value: "glass", label: "Vidrio" },
];

const CATEGORY_NONE_VALUE = "__none__";

const LENS_CATEGORY_SLUGS = [
  "lectura",
  "ocupacional",
  "deportivo",
  "lentes-contacto",
];

export function LensFamilyBasicForm({
  data,
  onChange,
  errors = {},
}: LensFamilyBasicFormProps) {
  const [categories, setCategories] = useState<
    { id: string; name: string; slug: string }[]
  >([]);

  useEffect(() => {
    fetch("/api/categories")
      .then((r) => r.json())
      .then((json) => {
        const cats = json.categories || json.data || [];
        setCategories(
          cats.filter((c: { slug?: string }) =>
            LENS_CATEGORY_SLUGS.includes(c.slug ?? ""),
          ),
        );
      })
      .catch(() => setCategories([]));
  }, []);

  const handleChange = (field: keyof LensFamilyFormData, value: unknown) => {
    onChange({ ...data, [field]: value });
  };

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label htmlFor="name">Nombre de la Familia *</Label>
          <Input
            className={errors.name ? "border-red-500" : ""}
            id="name"
            placeholder="Ej: Varilux Comfort"
            value={data.name}
            onChange={(e) => handleChange("name", e.target.value)}
          />
          {errors.name && <p className="text-xs text-red-500">{errors.name}</p>}
        </div>

        <div className="space-y-2">
          <Label htmlFor="brand">Marca</Label>
          <Input
            id="brand"
            placeholder="Ej: Essilor"
            value={data.brand}
            onChange={(e) => handleChange("brand", e.target.value)}
          />
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {/* Categoría deprecada: oculta por defecto, priorizar lens_type como selector de tipo */}
        <div className="space-y-2 hidden">
          <Label htmlFor="category_id">Categoría</Label>
          <Select
            value={data.category_id ?? CATEGORY_NONE_VALUE}
            onValueChange={(value) =>
              handleChange(
                "category_id",
                value === CATEGORY_NONE_VALUE ? null : value,
              )
            }
          >
            <SelectTrigger>
              <SelectValue placeholder="Seleccionar categoría (opcional)" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value={CATEGORY_NONE_VALUE}>Sin categoría</SelectItem>
              {categories.map((cat) => (
                <SelectItem key={cat.id} value={cat.id}>
                  {cat.name}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
        <div className="space-y-2 md:col-span-2">
          <Label htmlFor="lens_type">Tipo de Lente *</Label>
          <p className="text-xs text-muted-foreground">
            Clasificación técnica del diseño óptico: monofocal, bifocal,
            progresivo, lectura, etc. Usado para sugerir familias en
            presupuestos.
          </p>
          <Select
            value={data.lens_type}
            onValueChange={(value) => handleChange("lens_type", value)}
          >
            <SelectTrigger>
              <SelectValue placeholder="Seleccionar tipo" />
            </SelectTrigger>
            <SelectContent>
              {LENS_TYPES.map((type) => (
                <SelectItem key={type.value} value={type.value}>
                  {type.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        <div className="space-y-2">
          <Label htmlFor="lens_material">Material *</Label>
          <Select
            value={data.lens_material}
            onValueChange={(value) => handleChange("lens_material", value)}
          >
            <SelectTrigger>
              <SelectValue placeholder="Seleccionar material" />
            </SelectTrigger>
            <SelectContent>
              {LENS_MATERIALS.map((material) => (
                <SelectItem key={material.value} value={material.value}>
                  {material.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </div>

      <div className="space-y-2">
        <Label htmlFor="description">Descripción</Label>
        <Textarea
          id="description"
          placeholder="Descripción detallada de la familia de lentes..."
          rows={3}
          value={data.description}
          onChange={(e) => handleChange("description", e.target.value)}
        />
      </div>

      <div className="flex items-center space-x-2">
        <input
          checked={data.is_active}
          className="h-4 w-4 rounded border-gray-300"
          id="is_active_family"
          type="checkbox"
          onChange={(e) => handleChange("is_active", e.target.checked)}
        />
        <Label className="cursor-pointer" htmlFor="is_active_family">
          Familia Activa
        </Label>
      </div>
    </div>
  );
}

"use client";

import { Check, ChevronsUpDown } from "lucide-react";
import { useCallback, useEffect, useState } from "react";

import { Button } from "@/components/ui/button";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { extractDataFromResponse } from "@/lib/api/response-helpers";
import { appLogger } from '@/lib/logger';
import {
  getCategorySlugsForPresbyopia,
  getLensTypesForPresbyopia,
  getRecommendedLensTypes,
  type PresbyopiaSolution,
} from "@/lib/presbyopia-helpers";
import { cn } from "@/lib/utils";

export interface LensFamilyOption {
  id: string;
  name: string;
  brand?: string | null;
  lens_type?: string;
  lens_material?: string;
}

/** prescription_type values that map 1:1 to lens_type for filtering when presbyopiaSolution is "none" */
const PRESCRIPTION_TYPE_TO_LENS_FILTER = [
  "reading",
  "computer",
  "sports",
] as const;

interface LensFamilyComboboxProps {
  value: string;
  onChange: (value: string) => void;
  presbyopiaSolution?: PresbyopiaSolution | null;
  /** When presbyopiaSolution is "none", use prescription_type to filter (reading/computer/sports → only that type) */
  prescriptionType?: string | null;
  /** Optional: use pre-fetched families (filtered client-side). When not provided, fetches from API. */
  families?: LensFamilyOption[];
  loading?: boolean;
  placeholder?: string;
  disabled?: boolean;
  className?: string;
}

const MANUAL_OPTION_VALUE = "__manual__";

export function LensFamilyCombobox({
  value,
  onChange,
  presbyopiaSolution = null,
  prescriptionType = null,
  families: familiesProp,
  loading: loadingProp,
  placeholder = "Selecciona familia (opcional)",
  disabled = false,
  className,
}: LensFamilyComboboxProps) {
  const [open, setOpen] = useState(false);
  const [fetchedFamilies, setFetchedFamilies] = useState<LensFamilyOption[]>(
    [],
  );
  const [fetchLoading, setFetchLoading] = useState(false);
  const [search, setSearch] = useState("");

  // When presbyopiaSolution is "none" and prescriptionType is reading/computer/sports, filter by that type only
  const effectiveLensTypes = (() => {
    const fromPresbyopia = getLensTypesForPresbyopia(
      presbyopiaSolution ?? undefined,
    );
    if (presbyopiaSolution && presbyopiaSolution !== "none") {
      return fromPresbyopia;
    }
    const pt = prescriptionType?.toLowerCase().trim();
    if (
      pt &&
      (PRESCRIPTION_TYPE_TO_LENS_FILTER as readonly string[]).includes(pt)
    ) {
      return [pt];
    }
    return fromPresbyopia;
  })();

  const fetchFamilies = useCallback(
    async (searchTerm?: string) => {
      if (familiesProp != null) return;
      setFetchLoading(true);
      try {
        const lensTypes = (() => {
          const fromPresbyopia = getLensTypesForPresbyopia(
            presbyopiaSolution ?? undefined,
          );
          if (presbyopiaSolution && presbyopiaSolution !== "none") {
            return fromPresbyopia;
          }
          const pt = prescriptionType?.toLowerCase().trim();
          if (
            pt &&
            (PRESCRIPTION_TYPE_TO_LENS_FILTER as readonly string[]).includes(pt)
          ) {
            return [pt];
          }
          return fromPresbyopia;
        })();
        const slugs =
          lensTypes.length === 0
            ? getCategorySlugsForPresbyopia(presbyopiaSolution ?? undefined)
            : [];
        const params = new URLSearchParams();
        if (lensTypes.length > 0) {
          params.set("lens_type", lensTypes.join(","));
        } else if (slugs.length > 0) {
          params.set("category_slug", slugs.join(","));
        }
        if (searchTerm?.trim()) {
          params.set("search", searchTerm.trim());
        }
        const res = await fetch(
          `/api/admin/lens-families?${params.toString()}`,
        );
        const json = await res.json();
        const data = extractDataFromResponse<LensFamilyOption>(json);
        if (Array.isArray(json?.data)) {
          setFetchedFamilies(json.data);
        } else {
          setFetchedFamilies(Array.isArray(data) ? data : []);
        }
      } catch (err) {
        appLogger.error("Error fetching lens families:", err);
        setFetchedFamilies([]);
      } finally {
        setFetchLoading(false);
      }
    },
    [presbyopiaSolution, prescriptionType, familiesProp],
  );

  useEffect(() => {
    fetchFamilies(search);
  }, [fetchFamilies, search]);

  const lensTypes = effectiveLensTypes;
  const slugs =
    lensTypes.length === 0
      ? getCategorySlugsForPresbyopia(presbyopiaSolution ?? undefined)
      : [];
  const recommendedTypes =
    lensTypes.length > 0
      ? lensTypes
      : getRecommendedLensTypes(presbyopiaSolution ?? "none");
  const baseList = familiesProp ?? fetchedFamilies;
  const filteredList =
    baseList.length > 0 &&
    (lensTypes.length > 0 || slugs.length > 0 || recommendedTypes.length > 0)
      ? baseList.filter((f) => {
          const familyType = (f as unknown).lens_type || "";
          const cat =
            (f as unknown).categories ??
            (f as unknown).category ??
            (typeof (f as unknown).category_id === "object"
              ? (f as unknown).category_id
              : null);
          const catSlug =
            typeof cat === "object" && cat?.slug ? cat.slug : null;

          // Prefer lens_type when available
          if (lensTypes.length > 0) {
            return familyType ? lensTypes.includes(familyType) : false;
          }

          // Fallback to category-based filtering
          if (catSlug && slugs.length > 0 && slugs.includes(catSlug)) {
            return true;
          }
          if (recommendedTypes.length > 0 && familyType) {
            const normalizedType = familyType
              .toLowerCase()
              .replace(/[^a-z]/g, "");
            const hasMatch = recommendedTypes.some((rt) => {
              const normalizedRT = rt.toLowerCase().replace(/[^a-z]/g, "");
              return (
                normalizedRT === normalizedType ||
                (normalizedRT === "singlevision" &&
                  (normalizedType === "monofocal" ||
                    normalizedType === "visionsencilla"))
              );
            });
            if (hasMatch) return true;
          }
          if (!catSlug && slugs.length > 0) return true;
          if (catSlug && slugs.length > 0 && !slugs.includes(catSlug)) {
            return false;
          }
          return true;
        })
      : baseList;
  const families = search.trim()
    ? filteredList.filter(
        (f) =>
          f.name.toLowerCase().includes(search.toLowerCase()) ||
          (f.brand && f.brand.toLowerCase().includes(search.toLowerCase())),
      )
    : filteredList;
  const loading = loadingProp ?? fetchLoading;

  const allFamiliesForDisplay = familiesProp ?? fetchedFamilies;
  const displayValue = !value
    ? "Sin familia (manual)"
    : (() => {
        const f = allFamiliesForDisplay.find((x) => x.id === value);
        return f ? `${f.name}${f.brand ? ` (${f.brand})` : ""}` : value;
      })();

  const handleSelect = (val: string) => {
    const newVal = val === MANUAL_OPTION_VALUE ? "" : val;
    onChange(newVal);
    setOpen(false);
  };

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          aria-expanded={open}
          className={cn("w-full justify-between font-normal", className)}
          disabled={disabled || loading}
          role="combobox"
          variant="outline"
        >
          {loading ? "Cargando..." : displayValue || placeholder}
          <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent
        align="start"
        className="w-[var(--radix-popover-trigger-width)] p-0"
      >
        <Command shouldFilter={false}>
          <CommandInput
            placeholder="Buscar por nombre o marca..."
            value={search}
            onValueChange={setSearch}
          />
          <CommandList>
            <CommandEmpty>No se encontraron familias.</CommandEmpty>
            <CommandGroup>
              <CommandItem value="__manual__" onSelect={() => handleSelect("")}>
                <Check
                  className={cn(
                    "mr-2 h-4 w-4",
                    !value ? "opacity-100" : "opacity-0",
                  )}
                />
                Sin familia (manual)
              </CommandItem>
              {families.map((f) => (
                <CommandItem
                  key={f.id}
                  value={f.id}
                  onSelect={() => handleSelect(f.id)}
                >
                  <Check
                    className={cn(
                      "mr-2 h-4 w-4",
                      value === f.id ? "opacity-100" : "opacity-0",
                    )}
                  />
                  {f.name}
                  {f.brand ? ` (${f.brand})` : ""}
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}

"use client";

import { ArrowLeft, Loader2, Save } from "lucide-react";
import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { appLogger } from '@/lib/logger';

import { LensFamilyBasicForm, LensFamilyFormData } from "./LensFamilyBasicForm";
import { LensMatrixFormData, LensMatrixManager } from "./LensMatrixManager";

interface LensFamilyEditorProps {
  familyId: string;
}

export function LensFamilyEditor({ familyId }: LensFamilyEditorProps) {
  const router = useRouter();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [activeTab, setActiveTab] = useState("info");

  const [familyData, setFamilyData] = useState<LensFamilyFormData | null>(null);
  const [matrices, setMatrices] = useState<LensMatrixFormData[]>([]);

  useEffect(() => {
    if (familyId) {
      fetchData();
    }
  }, [familyId]);

  const fetchData = async () => {
    try {
      setLoading(true);
      // Fetch Family
      const familyRes = await fetch(`/api/admin/lens-families/${familyId}`);
      if (!familyRes.ok) throw new Error("Error fetching family");
      const familyJson = await familyRes.json();
      const f = familyJson.family;
      setFamilyData({
        name: f.name,
        brand: f.brand || "",
        category_id: f.category_id || null,
        lens_type: f.lens_type,
        lens_material: f.lens_material,
        description: f.description || "",
        is_active: f.is_active,
      });

      // Fetch Matrices
      const matricesRes = await fetch(
        `/api/admin/lens-matrices?family_id=${familyId}&include_inactive=true`,
      );
      if (!matricesRes.ok) throw new Error("Error fetching matrices");
      const matricesJson = await matricesRes.json();
      setMatrices(matricesJson.matrices || []);
    } catch (error) {
      appLogger.error(error);
      toast.error("Error al cargar datos");
    } finally {
      setLoading(false);
    }
  };

  const handleInfoSave = async () => {
    if (!familyData) return;
    try {
      setSaving(true);
      const response = await fetch(`/api/admin/lens-families/${familyId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(familyData),
      });

      if (!response.ok) throw new Error("Error updating family");

      toast.success("Información actualizada");
    } catch (error) {
      appLogger.error(error);
      toast.error("Error al actualizar familia");
    } finally {
      setSaving(false);
    }
  };

  const handleMatrixCreate = async (matrix: LensMatrixFormData) => {
    try {
      const response = await fetch("/api/admin/lens-matrices", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...matrix,
          lens_family_id: familyId,
        }),
      });

      if (!response.ok) {
        const err = await response.json();
        throw new Error(err.error || "Error al crear matriz");
      }

      toast.success("Matriz creada");
      fetchData(); // Reload to get ID and sort
    } catch (error: unknown) {
      toast.error(error.message);
    }
  };

  const handleMatrixUpdate = async (matrix: LensMatrixFormData) => {
    try {
      // Ensure we don't send temp-ids to the server if it happens somehow, but matrix.id should be real here
      const response = await fetch(`/api/admin/lens-matrices/${matrix.id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...matrix,
          lens_family_id: familyId,
        }),
      });

      if (!response.ok) {
        const err = await response.json();
        throw new Error(err.error || "Error al actualizar matriz");
      }

      toast.success("Matriz actualizada");
      fetchData();
    } catch (error: unknown) {
      toast.error(error.message);
    }
  };

  const handleMatrixDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/admin/lens-matrices/${id}`, {
        method: "DELETE",
      });

      if (!response.ok) throw new Error("Error al eliminar matriz");

      toast.success("Matriz eliminada");
      fetchData();
    } catch (error: unknown) {
      toast.error(error.message);
    }
  };

  if (loading) {
    return (
      <div className="flex justify-center p-12">
        <Loader2 className="h-8 w-8 animate-spin text-gray-400" />
      </div>
    );
  }

  if (!familyData) return <div>No se encontró la familia</div>;

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-4">
          <Button
            size="sm"
            variant="outline"
            onClick={() => router.push("/admin/products?tab=lens-families")}
          >
            <ArrowLeft className="h-4 w-4" />
          </Button>
          <div>
            <h2 className="text-2xl font-bold tracking-tight">
              {familyData.name}
            </h2>
            <p className="text-muted-foreground">
              {familyData.brand} • {familyData.lens_type}
            </p>
          </div>
        </div>
      </div>

      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList>
          <TabsTrigger value="info">Información General</TabsTrigger>
          <TabsTrigger value="matrices">Matrices de Precios</TabsTrigger>
        </TabsList>

        <TabsContent value="info">
          <Card>
            <CardContent className="pt-6">
              <LensFamilyBasicForm data={familyData} onChange={setFamilyData} />
              <div className="mt-6 flex justify-end">
                <Button disabled={saving} onClick={handleInfoSave}>
                  <Save className="h-4 w-4 mr-2" />
                  {saving ? "Guardando..." : "Guardar Cambios"}
                </Button>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="matrices">
          <Card>
            <CardContent className="pt-6">
              <LensMatrixManager
                matrices={matrices}
                onMatrixCreate={handleMatrixCreate}
                onMatrixDelete={handleMatrixDelete}
                onMatrixUpdate={handleMatrixUpdate}
              />
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

"use client";

import { ArrowLeft, ArrowRight, Save } from "lucide-react";
import { useRouter } from "next/navigation";
import { useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { appLogger } from '@/lib/logger';

import {
  LensFamilyBasicForm,
  LensFamilyFormData as BasicFormData,
} from "./LensFamilyBasicForm";
import { LensMatrixFormData, LensMatrixManager } from "./LensMatrixManager";

interface FullLensFamilyData extends BasicFormData {
  matrices: LensMatrixFormData[];
}

export function LensFamilyWizard() {
  const router = useRouter();
  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [data, setData] = useState<FullLensFamilyData>({
    name: "",
    brand: "",
    category_id: null,
    lens_type: "single_vision",
    lens_material: "cr39",
    description: "",
    is_active: true,
    matrices: [],
  });

  const [errors, setErrors] = useState<Record<string, string>>({});

  const handleBasicInfoChange = (basicData: BasicFormData) => {
    setData((prev) => ({ ...prev, ...basicData }));
    // Clear errors when user types
    if (errors.name && basicData.name) {
      setErrors((prev) => ({ ...prev, name: "" }));
    }
  };

  const handleMatricesChange = (matrices: LensMatrixFormData[]) => {
    setData((prev) => ({ ...prev, matrices }));
  };

  const validateStep1 = () => {
    const newErrors: Record<string, string> = {};
    if (!data.name.trim()) newErrors.name = "El nombre es requerido";

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleNext = () => {
    if (step === 1) {
      if (validateStep1()) {
        setStep(2);
      }
    }
  };

  const handleBack = () => {
    if (step === 2) {
      setStep(1);
    }
  };

  const handleSubmit = async () => {
    try {
      setLoading(true);
      const matricesPayload =
        data.matrices.length > 0
          ? data.matrices.map(({ id: _id, ...m }) => m)
          : [];
      const payload =
        matricesPayload.length > 0
          ? { ...data, matrices: matricesPayload }
          : { ...data, matrices: [], create_with_defaults: true };
      const response = await fetch("/api/admin/lens-families", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || "Error al crear familia de lentes");
      }

      toast.success("Familia de lentes creada exitosamente");
      router.push("/admin/products?tab=lens-families");
    } catch (error: unknown) {
      appLogger.error(error);
      toast.error(error.message || "Error al guardar");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto">
      {/* Stepper Header */}
      <div className="flex items-center justify-center mb-8">
        <div className="flex items-center">
          <div
            className={`flex items-center justify-center w-10 h-10 rounded-full border-2 ${
              step >= 1
                ? "bg-primary text-primary-foreground border-primary"
                : "border-gray-300 text-gray-500"
            }`}
          >
            1
          </div>
          <div className="ml-2 font-medium text-sm">Información</div>
        </div>
        <div
          className={`w-24 h-1 mx-4 ${
            step >= 2 ? "bg-primary" : "bg-gray-200"
          }`}
        />
        <div className="flex items-center">
          <div
            className={`flex items-center justify-center w-10 h-10 rounded-full border-2 ${
              step >= 2
                ? "bg-primary text-primary-foreground border-primary"
                : "border-gray-300 text-gray-500"
            }`}
          >
            2
          </div>
          <div className="ml-2 font-medium text-sm">Matrices de Precios</div>
        </div>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>
            {step === 1
              ? "Información de la Familia"
              : "Configuración de Matrices"}
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-6">
          {step === 1 && (
            <LensFamilyBasicForm
              data={data}
              errors={errors}
              onChange={handleBasicInfoChange}
            />
          )}

          {step === 2 && (
            <div className="space-y-4">
              <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 mb-4">
                <h4 className="text-sm font-semibold text-blue-900">
                  Resumen de Familia
                </h4>
                <p className="text-sm text-blue-800">
                  {data.name} ({data.brand}) - {data.lens_type} -{" "}
                  {data.lens_material}
                </p>
              </div>
              <LensMatrixManager
                lensType={data.lens_type}
                matrices={data.matrices}
                onChange={handleMatricesChange}
              />
            </div>
          )}

          <div className="flex justify-between pt-6 border-t mt-6">
            {step === 1 ? (
              <Button
                variant="outline"
                onClick={() => router.push("/admin/products?tab=lens-families")}
              >
                Cancelar
              </Button>
            ) : (
              <Button variant="outline" onClick={handleBack}>
                <ArrowLeft className="h-4 w-4 mr-2" />
                Atrás
              </Button>
            )}

            {step === 1 ? (
              <Button onClick={handleNext}>
                Siguiente
                <ArrowRight className="h-4 w-4 ml-2" />
              </Button>
            ) : (
              <Button disabled={loading} onClick={handleSubmit}>
                <Save className="h-4 w-4 mr-2" />
                {loading ? "Creando..." : "Crear Familia Completa"}
              </Button>
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { Plus, RefreshCw } from "lucide-react";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { supabase } from "@/lib/supabase/client";

import { MatricesTable, SearchBar } from "./_components/LensMatricesListComponents";
import type { MatrixFormData } from "./_components/MatrixDialog";
import { MatrixDialog } from "./_components/MatrixDialog";
import type { LensFamily,LensPriceMatrix } from "./types";

export default function LensMatricesList() {
  const [matrices, setMatrices] = useState<LensPriceMatrix[]>([]);
  const [families, setFamilies] = useState<LensFamily[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [familyFilter, setFamilyFilter] = useState("all");
  const [showDialog, setShowDialog] = useState(false);

  const [editingMatrix, setEditingMatrix] = useState<LensPriceMatrix | null>(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage, setItemsPerPage] = useState(10);

  const emptyForm: MatrixFormData = {
    lens_family_id: "", name: "", sphere_min: "", sphere_max: "",
    cylinder_min: "", cylinder_max: "", base_price: "", cost: "", is_active: true,
  };
  const [formData, setFormData] = useState<MatrixFormData>(emptyForm);

  const fetchFamilies = async () => {
    const { data } = await supabase.from("lens_families").select("id, name, brand, lens_type, lens_material").eq("is_active", true).order("name");
    if (data) setFamilies(data);
  };

  const fetchMatrices = async () => {
    setLoading(true);
    const { data } = await supabase.from("lens_price_matrices").select("*, lens_families(*)").order("lens_families(name)");
    if (data) setMatrices(data);
    setLoading(false);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingMatrix) {
      const { error } = await supabase.from("lens_price_matrices").update(formData).eq("id", editingMatrix.id);
      if (error) { toast.error("Error al actualizar"); return; }
      toast.success("Matriz actualizada");
    } else {
      const { error } = await supabase.from("lens_price_matrices").insert(formData);
      if (error) { toast.error("Error al crear"); return; }
      toast.success("Matriz creada");
    }
    setShowDialog(false);
    fetchMatrices();
  };

  const handleDelete = async (id: string) => {
    if (!confirm("¿Eliminar esta matriz?")) return;
    const { error } = await supabase.from("lens_price_matrices").delete().eq("id", id);
    if (error) { toast.error("Error al eliminar"); return; }
    toast.success("Matriz eliminada");
    fetchMatrices();
  };

  const handleToggleActive = async (matrix: LensPriceMatrix) => {
    const { error } = await supabase.from("lens_price_matrices").update({ is_active: !matrix.is_active }).eq("id", matrix.id);
    if (error) { toast.error("Error al cambiar estado"); return; }
    toast.success(`Matriz ${matrix.is_active ? "desactivada" : "activada"}`);
    fetchMatrices();
  };

  const resetForm = () => { setFormData(emptyForm); setEditingMatrix(null); };

  const openEditDialog = (matrix: LensPriceMatrix) => {
    setEditingMatrix(matrix);
    setFormData({
      lens_family_id: matrix.lens_family_id, name: matrix.name || "",
      sphere_min: String(matrix.sphere_min), sphere_max: String(matrix.sphere_max),
      cylinder_min: String(matrix.cylinder_min), cylinder_max: String(matrix.cylinder_max),
      base_price: String(matrix.base_price), cost: String(matrix.cost), is_active: matrix.is_active,
    });
    setShowDialog(true);
  };

  const openCreateDialog = () => { resetForm(); setShowDialog(true); };

  const filteredMatrices = matrices.filter((m) => {
    const matchesSearch = !searchTerm || m.lens_families?.name?.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesFamily = familyFilter === "all" || m.lens_family_id === familyFilter;
    return matchesSearch && matchesFamily;
  });

  useEffect(() => { fetchFamilies(); fetchMatrices(); }, []);

  return (
    <Card>
      <CardHeader>
        <div className="flex justify-between items-center">
          <CardTitle>Matrices de Precios de Lentes Ópticos</CardTitle>
          <div className="flex gap-2">
            <Button size="sm" variant="outline" onClick={fetchMatrices}><RefreshCw className="h-4 w-4 mr-2" />Actualizar</Button>
            <Button size="sm" onClick={openCreateDialog}><Plus className="h-4 w-4 mr-2" />Nueva Matriz</Button>
          </div>
        </div>
      </CardHeader>
      <CardContent>
        <SearchBar
          families={families} familyFilter={familyFilter}
          searchTerm={searchTerm} onFamilyFilterChange={setFamilyFilter} onSearchChange={setSearchTerm}
        />

        <MatricesTable
          currentPage={currentPage} itemsPerPage={itemsPerPage}
          loading={loading} matrices={filteredMatrices}
          totalCount={filteredMatrices.length}
          onDelete={handleDelete} onEdit={openEditDialog} onItemsPerPageChange={setItemsPerPage}
          onPageChange={setCurrentPage} onToggleActive={handleToggleActive}
        />

        <MatrixDialog
          editingMatrix={!!editingMatrix} families={families}
          formData={formData} open={showDialog}
          onChange={(d) => setFormData({ ...formData, ...d })}
          onClose={() => { setShowDialog(false); resetForm(); }} onSubmit={handleSubmit}
        />
      </CardContent>
    </Card>
  );
}

"use client";

import { useState } from "react";

import {
  getOpticalDefaultMatrices,
  OPTICAL_MATRIX_TEMPLATE,
} from "@/lib/lens-matrices/constants";

import { LensMatrixDialog } from "./_components/LensMatrixDialog";
import { MatrixSuggestionPanel } from "./_components/MatrixSuggestionPanel";
import { MatrixTable } from "./_components/MatrixTable";
import type { LensMatrixFormData } from "./types";

interface LensMatrixManagerProps {
  matrices: LensMatrixFormData[];
  onChange?: (matrices: LensMatrixFormData[]) => void;
  readOnly?: boolean;
  lensType?: string;
  onMatrixCreate?: (matrix: LensMatrixFormData) => Promise<void>;
  onMatrixUpdate?: (matrix: LensMatrixFormData) => Promise<void>;
  onMatrixDelete?: (id: string) => Promise<void>;
}

export function LensMatrixManager({
  matrices,
  onChange,
  readOnly = false,
  lensType = "single_vision",
  onMatrixCreate,
  onMatrixUpdate,
  onMatrixDelete,
}: LensMatrixManagerProps) {
  const [showDialog, setShowDialog] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [suggestionOpen, setSuggestionOpen] = useState(matrices.length === 0);
  const isMonofocal = lensType === "single_vision";

  const [formData, setFormData] = useState({
    name: "",
    sphere_min: "-6.00",
    sphere_max: "6.00",
    cylinder_min: "-2.00",
    cylinder_max: "2.00",
    addition_min: "0.00",
    addition_max: "4.00",
    base_price: "0",
    cost: "0",
    sourcing_type: "surfaced" as "stock" | "surfaced",
    is_active: true,
  });

  const handleOpenDialog = (matrix?: LensMatrixFormData) => {
    if (matrix) {
      setEditingId(matrix.id);
      setFormData({
        name: matrix.name ?? "", sphere_min: matrix.sphere_min.toString(),
        sphere_max: matrix.sphere_max.toString(), cylinder_min: matrix.cylinder_min.toString(),
        cylinder_max: matrix.cylinder_max.toString(), addition_min: matrix.addition_min.toString(),
        addition_max: matrix.addition_max.toString(), base_price: matrix.base_price.toString(),
        cost: matrix.cost.toString(), sourcing_type: matrix.sourcing_type, is_active: matrix.is_active,
      });
    } else {
      setEditingId(null);
      setFormData({
        name: "", sphere_min: "-6.00", sphere_max: "6.00", cylinder_min: "-2.00", cylinder_max: "2.00",
        addition_min: "0.00", addition_max: isMonofocal ? "0.00" : "4.00",
        base_price: "0", cost: "0", sourcing_type: "surfaced", is_active: true,
      });
    }
    setShowDialog(true);
  };

  const handleApplyTemplate = (template: "defaults" | "full") => {
    const rows = template === "defaults" ? getOpticalDefaultMatrices(lensType) : OPTICAL_MATRIX_TEMPLATE;
    const newMatrices: LensMatrixFormData[] = rows.map((r, i) => ({
      id: `temp-${Date.now()}-${i}`, name: r.name, sphere_min: r.sphere_min, sphere_max: r.sphere_max,
      cylinder_min: r.cylinder_min, cylinder_max: r.cylinder_max, addition_min: r.addition_min,
      addition_max: r.addition_max, base_price: r.base_price, cost: r.cost,
      sourcing_type: r.sourcing_type, is_active: true,
    }));
    if (onChange) onChange([...matrices, ...newMatrices]);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newMatrix: LensMatrixFormData = {
      id: editingId || `temp-${Date.now()}`, name: formData.name?.trim() || undefined,
      sphere_min: parseFloat(formData.sphere_min), sphere_max: parseFloat(formData.sphere_max),
      cylinder_min: parseFloat(formData.cylinder_min), cylinder_max: parseFloat(formData.cylinder_max),
      addition_min: isMonofocal ? 0 : parseFloat(formData.addition_min),
      addition_max: isMonofocal ? 0 : parseFloat(formData.addition_max),
      base_price: parseFloat(formData.base_price), cost: parseFloat(formData.cost),
      sourcing_type: formData.sourcing_type, is_active: formData.is_active,
    };
    if (editingId) {
      if (onMatrixUpdate) { onMatrixUpdate(newMatrix).then(() => setShowDialog(false)); }
      else if (onChange) { onChange(matrices.map((m) => (m.id === editingId ? newMatrix : m))); setShowDialog(false); }
    } else {
      if (onMatrixCreate) { onMatrixCreate(newMatrix).then(() => setShowDialog(false)); }
      else if (onChange) { onChange([...matrices, newMatrix]); setShowDialog(false); }
    }
  };

  const handleDelete = (id: string) => {
    if (confirm("¿Estás seguro de eliminar esta matriz?")) {
      if (onMatrixDelete) { onMatrixDelete(id); }
      else if (onChange) { onChange(matrices.filter((m) => m.id !== id)); }
    }
  };

  return (
    <div className="space-y-4">
      {!readOnly && (
        <MatrixSuggestionPanel
          open={suggestionOpen}
          onApplyTemplate={handleApplyTemplate}
          onToggle={() => setSuggestionOpen(!suggestionOpen)}
        />
      )}

      <MatrixTable
        matrices={matrices}
        readOnly={readOnly}
        onAdd={() => handleOpenDialog()}
        onDelete={handleDelete}
        onEdit={handleOpenDialog}
      />

      <LensMatrixDialog
        editingId={editingId}
        formData={formData}
        isMonofocal={isMonofocal}
        open={showDialog}
        onChange={(d) => setFormData((prev) => ({ ...prev, ...d }))}
        onClose={() => setShowDialog(false)}
        onSubmit={handleSubmit}
      />
    </div>
  );
}

"use client";

