import type { LensPriceMatrix } from "../types";

// ─── Search / Filter Bar ─────────────────────────────────────────────────────

interface SearchBarProps {
  searchTerm: string;
  familyFilter: string;
  families: { id: string; name: string }[];
  onSearchChange: (v: string) => void;
  onFamilyFilterChange: (v: string) => void;
