                <Label htmlFor="cost">Costo Compra</Label>
                <Input required id="cost" min="0" step="0.01" type="number" value={formData.cost}
                  onChange={(e) => onChange({ cost: e.target.value })} />
              </div>
              <div>
                <Label htmlFor="sourcing_type">Tipo de Sourcing</Label>
                <Select value={formData.sourcing_type}
                  onValueChange={(v: "stock" | "surfaced") => onChange({ sourcing_type: v })}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="stock">Stock (Inventario)</SelectItem>
                    <SelectItem value="surfaced">Surfaced (Laboratorio)</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="flex items-center space-x-2 pt-4">
                <input checked={formData.is_active} className="h-4 w-4 rounded border-gray-300" id="is_active_matrix"
                  type="checkbox"
                  onChange={(e) => onChange({ is_active: e.target.checked })} />
                <Label className="cursor-pointer" htmlFor="is_active_matrix">Matriz Activa</Label>
              </div>
            </div>
          </div>
          <DialogFooter>
            <Button type="button" variant="outline" onClick={onClose}>Cancelar</Button>
            <Button type="submit">{editingId ? "Actualizar Matriz" : "Agregar Matriz"}</Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";


import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

export interface MatrixFormData {
  lens_family_id: string;
  name: string;
  sphere_min: string;
  sphere_max: string;
  cylinder_min: string;
  cylinder_max: string;
  base_price: string;
  cost: string;
  is_active: boolean;
}

export interface LensFamily {
  id: string;
  name: string;
  brand?: string;
}

interface MatrixDialogProps {
  open: boolean;
  editingMatrix: boolean;
  formData: MatrixFormData;
  families: LensFamily[];
  onClose: () => void;
  onSubmit: (e: React.FormEvent) => void;
  onChange: (data: Partial<MatrixFormData>) => void;
}

export function MatrixDialog({
  open,
  editingMatrix,
  formData,
  families,
  onClose,
  onSubmit,
  onChange,
}: MatrixDialogProps) {
