"use client";

import { useRouter } from "next/navigation";
import { useCallback, useEffect, useState } from "react";
import { toast } from "sonner";

import { appLogger } from '@/lib/logger';
import type { ContactLensModality, ContactLensPackaging, ContactLensUseType } from "@/types/contact-lens";

import type { ContactLensMatrixFormData } from "./ContactLensMatrixManager";

interface FullFamilyData {
  name: string; brand: string; category_id: string | null;
  use_type: ContactLensUseType; modality: ContactLensModality; material: string | undefined;
  packaging: ContactLensPackaging; base_curve: string; diameter: string;
  description: string; is_active: boolean; matrices: ContactLensMatrixFormData[];
}

export function useContactLensFamilyWizard(familyId?: string) {
  const router = useRouter();
  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [initialLoading, setInitialLoading] = useState(!!familyId);
  const [categories, setCategories] = useState<{ id: string; name: string; slug: string }[]>([]);
  const [data, setData] = useState<FullFamilyData>({
    name: "", brand: "", category_id: null, use_type: "monthly", modality: "spherical",
    material: undefined, packaging: "box_6", base_curve: "", diameter: "",
    description: "", is_active: true, matrices: [],
  });
  const [errors, setErrors] = useState<Record<string, string>>({});

  useEffect(() => {
    fetch("/api/categories").then((r) => r.json()).then((json) => {
      const cats = json.categories || json.data || [];
      setCategories(cats.filter((c: { slug?: string }) => ["lentes-contacto", "lectura", "ocupacional", "deportivo"].includes(c.slug ?? "")));
    }).catch(() => setCategories([]));
  }, []);

  useEffect(() => {
    if (familyId) {
      fetch(`/api/admin/contact-lens-families/${familyId}?include_matrices=true`)
        .then((r) => { if (!r.ok) throw new Error("Error al cargar familia"); return r.json(); })
        .then((json) => {
          const f = json.family;
          setData({
            name: f.name || "", brand: f.brand || "", category_id: f.category_id || null,
            use_type: f.use_type || "monthly", modality: f.modality || "spherical",
            material: f.material || undefined, packaging: f.packaging || "box_6",
            base_curve: f.base_curve != null ? String(f.base_curve) : "",
            diameter: f.diameter != null ? String(f.diameter) : "",
            description: f.description || "", is_active: f.is_active ?? true,
            matrices: (f.contact_lens_price_matrices || []).map((m: Record<string, unknown>) => ({
              id: m.id as string, sphere_min: m.sphere_min as number, sphere_max: m.sphere_max as number,
              cylinder_min: m.cylinder_min as number, cylinder_max: m.cylinder_max as number,
              axis_min: m.axis_min as number, axis_max: m.axis_max as number,
              addition_min: m.addition_min as number, addition_max: m.addition_max as number,
              base_price: m.base_price as number, cost: m.cost as number, is_active: m.is_active as boolean,
            })),
          });
        })
        .catch((err) => { appLogger.error(err); toast.error("Error al cargar familia"); })
        .finally(() => setInitialLoading(false));
    }
  }, [familyId]);

  const validateStep1 = useCallback(() => {
    const newErrors: Record<string, string> = {};
    if (!data.name.trim()) newErrors.name = "El nombre es requerido";
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  }, [data.name]);

  const handleNext = () => { if (step === 1 && validateStep1()) setStep(2); };
  const handleBack = () => { if (step === 2) setStep(1); };

  const handleSubmit = async () => {
    try {
      setLoading(true);
      const body = { name: data.name.trim(), brand: data.brand || null, category_id: data.category_id || null, use_type: data.use_type, modality: data.modality, material: data.material || null, packaging: data.packaging, base_curve: data.base_curve ? parseFloat(data.base_curve) : null, diameter: data.diameter ? parseFloat(data.diameter) : null, description: data.description || null, is_active: data.is_active, matrices: data.matrices.map((m) => ({ name: m.name ?? null, sphere_min: m.sphere_min, sphere_max: m.sphere_max, cylinder_min: m.cylinder_min, cylinder_max: m.cylinder_max, axis_min: m.axis_min, axis_max: m.axis_max, addition_min: m.addition_min, addition_max: m.addition_max, base_price: m.base_price, cost: m.cost, is_active: m.is_active })) };
      const url = familyId ? `/api/admin/contact-lens-families/${familyId}` : "/api/admin/contact-lens-families";
      const method = familyId ? "PUT" : "POST";
      const response = await fetch(url, { method, headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
      if (!response.ok) { const err = await response.json(); throw new Error(err.error || (familyId ? "Error al actualizar familia" : "Error al crear familia")); }
      toast.success(familyId ? "Familia actualizada exitosamente" : "Familia de lentes de contacto creada exitosamente");
      router.push("/admin/products?tab=contact-lens-families");
    } catch (error: unknown) { appLogger.error(error); toast.error(error instanceof Error ? error.message : "Error al guardar"); }
    finally { setLoading(false); }
  };

  return { step, loading, initialLoading, categories, data, setData, errors, handleNext, handleBack, handleSubmit, setStep };
}

"use client";

import { useCallback, useEffect, useState } from "react";
import { toast } from "sonner";

import { appLogger } from '@/lib/logger';
import type { ContactLensFamily, ContactLensPriceMatrix } from "@/types/contact-lens";

interface MatrixWithFamily extends ContactLensPriceMatrix {
  contact_lens_families: ContactLensFamily;
}

export function useContactLensMatrices() {
  const [matrices, setMatrices] = useState<MatrixWithFamily[]>([]);
  const [families, setFamilies] = useState<ContactLensFamily[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedFamilyId, setSelectedFamilyId] = useState("all");
  const [showDialog, setShowDialog] = useState(false);
  const [editingMatrix, setEditingMatrix] = useState<MatrixWithFamily | null>(null);
  const [includeInactive, setIncludeInactive] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage, setItemsPerPage] = useState(20);
  const [formData, setFormData] = useState({
    contact_lens_family_id: "", sphere_min: "", sphere_max: "", cylinder_min: "0", cylinder_max: "0",
    axis_min: "0", axis_max: "180", addition_min: "0", addition_max: "4.0", base_price: "", cost: "", is_active: true,
  });

  const fetchFamilies = useCallback(async () => {
    try {
      const params = new URLSearchParams();
      if (includeInactive) params.append("include_inactive", "true");
      const response = await fetch(`/api/admin/contact-lens-families?${params}`);
      if (response.ok) { const data = await response.json(); setFamilies(data.families || []); }
    } catch (error) { appLogger.error("Error fetching families:", error); }
  }, [includeInactive]);

  const fetchMatrices = useCallback(async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams();
      if (includeInactive) params.append("include_inactive", "true");
      if (selectedFamilyId !== "all") params.append("family_id", selectedFamilyId);
      const response = await fetch(`/api/admin/contact-lens-matrices?${params}`);
      if (response.ok) { const data = await response.json(); setMatrices(data.matrices || []); }
      else { toast.error("Error al cargar matrices de lentes de contacto"); }
    } catch { toast.error("Error al cargar matrices de lentes de contacto"); }
    finally { setLoading(false); }
  }, [includeInactive, selectedFamilyId]);

  useEffect(() => { fetchFamilies(); }, [fetchFamilies]);
  useEffect(() => { fetchMatrices(); }, [fetchMatrices]);

  useEffect(() => { setCurrentPage(1); }, [searchTerm, selectedFamilyId, includeInactive]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const url = editingMatrix ? `/api/admin/contact-lens-matrices/${editingMatrix.id}` : "/api/admin/contact-lens-matrices";
      const method = editingMatrix ? "PUT" : "POST";
      const response = await fetch(url, { method, headers: { "Content-Type": "application/json" }, body: JSON.stringify(formData) });
      if (!response.ok) { const err = await response.json(); throw new Error(err.error || "Error al guardar matriz"); }
      toast.success(editingMatrix ? "Matriz actualizada" : "Matriz creada");
      setShowDialog(false); resetForm(); fetchMatrices();
    } catch (error: unknown) { toast.error((error as Error).message || "Error al guardar matriz"); }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("¿Estás seguro de que deseas eliminar esta matriz?")) return;
    try {
      const response = await fetch(`/api/admin/contact-lens-matrices/${id}`, { method: "DELETE" });
      if (!response.ok) throw new Error("Error al eliminar matriz");
      toast.success("Matriz eliminada exitosamente"); fetchMatrices();
    } catch { toast.error("Error al eliminar matriz"); }
  };

  const resetForm = () => {
    setFormData({ contact_lens_family_id: "", sphere_min: "", sphere_max: "", cylinder_min: "0", cylinder_max: "0", axis_min: "0", axis_max: "180", addition_min: "0", addition_max: "4.0", base_price: "", cost: "", is_active: true });
    setEditingMatrix(null);
  };

  const openEditDialog = (matrix: MatrixWithFamily) => {
    setEditingMatrix(matrix);
    setFormData({
      contact_lens_family_id: matrix.contact_lens_family_id, sphere_min: matrix.sphere_min.toString(), sphere_max: matrix.sphere_max.toString(),
      cylinder_min: matrix.cylinder_min?.toString() || "0", cylinder_max: matrix.cylinder_max?.toString() || "0",
      axis_min: matrix.axis_min?.toString() || "0", axis_max: matrix.axis_max?.toString() || "180",
      addition_min: matrix.addition_min?.toString() || "0", addition_max: matrix.addition_max?.toString() || "4.0",
      base_price: matrix.base_price.toString(), cost: matrix.cost.toString(), is_active: matrix.is_active || true,
    });
    setShowDialog(true);
  };

  const openCreateDialog = () => { resetForm(); setShowDialog(true); };

  const filteredMatrices = matrices.filter((m) => {
    const s = searchTerm.toLowerCase();
    const f = m.contact_lens_families;
    return f.name.toLowerCase().includes(s) || (f.brand || "").toLowerCase().includes(s) || m.sphere_min.toString().includes(s) || m.sphere_max.toString().includes(s);
  });

  const totalMatrices = filteredMatrices.length;
  const startIndex = (currentPage - 1) * itemsPerPage;
  const paginatedMatrices = filteredMatrices.slice(startIndex, startIndex + itemsPerPage);
  const totalPages = Math.ceil(totalMatrices / itemsPerPage);

  return {
    matrices: paginatedMatrices, families, loading, searchTerm, setSearchTerm,
    selectedFamilyId, setSelectedFamilyId, includeInactive, setIncludeInactive,
    showDialog, setShowDialog, editingMatrix, formData, setFormData,
    currentPage, setCurrentPage, itemsPerPage, setItemsPerPage,
    totalMatrices, totalPages, fetchMatrices,
    handleSubmit, handleDelete, openEditDialog, openCreateDialog,
  };
}

"use client";

import { Menu } from "lucide-react";
import { usePathname, useRouter } from "next/navigation";
import { useEffect, useState } from "react";

import { Button } from "@/components/ui/button";
import { Sheet, SheetContent, SheetTrigger } from "@/components/ui/sheet";
import { useAuthContext } from "@/contexts/AuthContext";
import { appLogger } from '@/lib/logger';

import { SidebarFooter } from "./SidebarFooter";
import { SidebarHeader } from "./SidebarHeader";
import { SidebarNav } from "./SidebarNav";
import { createSaaSNavigationGroups } from "./SidebarNavConfig";

interface SaasManagementSidebarProps {
  onNavigate?: () => void;
}

export function SaasManagementSidebar({
  onNavigate,
}: SaasManagementSidebarProps) {
  const pathname = usePathname();
  const router = useRouter();
  const { user, signOut } = useAuthContext();
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState<{
    totalOrganizations: number;
    activeOrganizations: number;
    openTickets: number;
    pendingDemos: number;
  }>({
    totalOrganizations: 0,
    activeOrganizations: 0,
    openTickets: 0,
    pendingDemos: 0,
  });
  const [expandedGroups, setExpandedGroups] = useState<Record<string, boolean>>(
    {
      principal: true,
    },
  );

  // Load from localStorage after mount to avoid hydration mismatch
  useEffect(() => {
    try {
      const saved = localStorage.getItem("saas-sidebar-groups");
      if (saved) {
        setExpandedGroups({ principal: true, ...JSON.parse(saved) });
      }
    } catch {
      // Ignorar
    }
  }, []);

  // Persistir estado de grupos
  useEffect(() => {
    try {
      localStorage.setItem(
        "saas-sidebar-groups",
        JSON.stringify(expandedGroups),
      );
    } catch {
      // Ignorar
    }
  }, [expandedGroups]);

  // Cargar stats iniciales
  useEffect(() => {
    const fetchStats = async () => {
      try {
        const response = await fetch("/api/admin/saas-management/analytics");
        if (response.ok) {
          const data = await response.json();
          setStats({
            totalOrganizations: data.totalOrganizations || 0,
            activeOrganizations: data.activeOrganizations || 0,
            openTickets: data.openTickets || 0,
            pendingDemos: data.pendingDemos || 0,
          });
        }
      } catch (error) {
        appLogger.error("Error fetching stats:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchStats();
  }, []);

  const handleSignOut = async () => {
    await signOut();
    router.push("/");
  };

  const groups = createSaaSNavigationGroups(stats);

  return (
    <div className="saas-sidebar flex flex-col h-full w-full overflow-y-auto overflow-x-hidden relative min-h-0 bg-[#0D1117]">
      {/* Texture Overlay */}
      <div className="absolute inset-0 opacity-[0.02] pointer-events-none" />

      <SidebarHeader
        loading={loading}
        stats={{
          totalOrganizations: stats.totalOrganizations,
          activeOrganizations: stats.activeOrganizations,
        }}
        onNavigate={onNavigate}
      />

      <SidebarNav
        expandedGroups={expandedGroups}
        groups={groups}
        pathname={pathname}
        onNavigate={onNavigate}
        onToggleGroup={(id) =>
          setExpandedGroups((prev) => ({ ...prev, [id]: !prev[id] }))
        }
      />

      <SidebarFooter onNavigate={onNavigate} onSignOut={handleSignOut} />
    </div>
  );
}

