"use client";

import { useState } from "react";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Textarea } from "@/components/ui/textarea";

import { GENERATION_TYPES } from "./leadGeneratorConstants";
import type { LeadAIGeneratorLead } from "./types";

export interface LeadAIGeneratorModalProps {
  lead: LeadAIGeneratorLead | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onGenerate: (
    leadId: string,
    prompt: string,
  ) => Promise<{ subject: string; body: string }>;
  onSend: (leadId: string, subject: string, body: string) => Promise<void>;
}

export function LeadAIGeneratorModal({
  lead,
  open,
  onOpenChange,
  onGenerate,
  onSend,
}: LeadAIGeneratorModalProps) {
  const [generating, setGenerating] = useState(false);
  const [sending, setSending] = useState(false);
  const [selectedType, setSelectedType] = useState<string | null>(null);
  const [customPrompt, setCustomPrompt] = useState("");
  const [generatedSubject, setGeneratedSubject] = useState("");
  const [generatedBody, setGeneratedBody] = useState("");
  const [showCustomPrompt, setShowCustomPrompt] = useState(false);

  const handleGenerate = async () => {
    if (!lead) return;
    setGenerating(true);
    try {
      let prompt = "";
      switch (selectedType) {
        case "followup":
          prompt = `Genera un email de seguimiento profesional para un lead llamado "${lead.full_name || "Cliente"}" de la óptica "${lead.optica_name || "una óptica"}" que está en la etapa "${lead.funnel_stage || "pendiente"}" del funnel de ventas. El lead tiene un score de ${lead.lead_score || 0}. El tono debe ser profesional pero cercano.`;
          break;
        case "proposal":
          prompt = `Genera un email de envío de propuesta comercial para un lead llamado "${lead.full_name || "Cliente"}" de la óptica "${lead.optica_name || "una óptica"}" que está en etapa de negociación. Incluye información sobre beneficios de Opttius para ópticas.`;
          break;
        case "case_story":
          prompt = `Genera un email que presente un caso de éxito relevante para una óptica llamada "${lead.optica_name || "una óptica"}". El tono debe ser profesional y convincente, destacando resultados measurable.`;
          break;
        case "reactivation":
          prompt = `Genera un email de reactivación para reconectar con un lead de "${lead.optica_name || "una óptica"}" que ha estado sin actividad. El tono debe ser cálido, no invasivo, ofreciendo valor.`;
          break;
        case "custom":
          prompt = customPrompt;
          break;
        default:
          toast.error("Por favor selecciona un tipo de generación");
          return;
      }
      const result = await onGenerate(lead.id, prompt);
      setGeneratedSubject(result.subject);
      setGeneratedBody(result.body);
    } catch {
      toast.error("Error al generar email");
    } finally {
      setGenerating(false);
    }
  };

  const handleSend = async () => {
    if (!lead || !generatedSubject.trim() || !generatedBody.trim()) return;
    setSending(true);
    try {
      await onSend(lead.id, generatedSubject, generatedBody);
      onOpenChange(false);
      resetForm();
    } catch {
      toast.error("Error al enviar email");
    } finally {
      setSending(false);
    }
  };

  const resetForm = () => {
    setSelectedType(null);
    setCustomPrompt("");
    setGeneratedSubject("");
    setGeneratedBody("");
    setShowCustomPrompt(false);
  };

  const handleClose = () => {
    onOpenChange(false);
    resetForm();
  };

  if (!lead) return null;

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="max-w-2xl bg-[#0D1117] border-white/20 text-white">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2 text-white">
            <span>🤖</span>
            Generar Email con IA
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          <div className="flex items-center gap-3 p-3 bg-white/5 rounded-lg border border-white/10">
            <div className="flex-1">
              <p className="text-sm font-medium text-white">
                {lead.full_name || lead.email}
              </p>
              <p className="text-xs text-white/50">
                {lead.optica_name || "Sin óptica"}
              </p>
            </div>
            {lead.priority_level && (
              <Badge className="text-white border-white/30" variant="outline">
                {lead.priority_level}
              </Badge>
            )}
            {lead.lead_score !== undefined && lead.lead_score > 0 && (
              <Badge className="text-white border-white/30" variant="outline">
                Score: {lead.lead_score}
              </Badge>
            )}
          </div>

          {!generatedSubject && (
            <>
              <div>
                <label className="text-sm font-medium text-white/70 mb-2 block">
                  ¿Qué tipo de email necesitas?
                </label>
                <div className="grid grid-cols-2 gap-2">
                  {GENERATION_TYPES.map((type) => (
                    <button
                      className={`p-3 rounded-lg border text-left transition-colors ${
                        selectedType === type.id
                          ? "border-amber-500 bg-amber-500/10"
                          : "border-white/10 hover:border-white/20"
                      }`}
                      key={type.id}
                      onClick={() => {
                        setSelectedType(type.id);
                        setShowCustomPrompt(type.id === "custom");
                      }}
                    >
                      <div className="flex items-center gap-2 mb-1">
                        <span>{type.icon}</span>
                        <span className="text-sm font-medium text-white">
                          {type.label}
                        </span>
                      </div>
                      <p className="text-xs text-white/50">
                        {type.description}
                      </p>
                    </button>
                  ))}
                </div>
              </div>

              {showCustomPrompt && (
                <div>
                  <label className="text-sm font-medium text-white/70 mb-1 block">
                    Describe qué necesitas
                  </label>
                  <Textarea
                    className="min-h-[100px] bg-white/5 border-white/10 text-white placeholder:text-white/30"
                    placeholder="Ej: Genera un email para..."
                    value={customPrompt}
                    onChange={(e) => setCustomPrompt(e.target.value)}
                  />
                </div>
              )}

              <div className="flex justify-end">
                <Button
                  disabled={
                    !selectedType ||
                    generating ||
                    (selectedType === "custom" && !customPrompt.trim())
                  }
                  onClick={handleGenerate}
                >
                  {generating ? (
                    <>
                      <span className="animate-spin mr-2">⏳</span>Generando...
                    </>
                  ) : (
                    <>
                      <span className="mr-2">🤖</span>Generar con IA
                    </>
                  )}
                </Button>
              </div>
            </>
          )}

          {generatedSubject && (
            <div className="space-y-4">
              <div className="p-3 bg-emerald-500/10 border border-emerald-500/30 rounded-lg">
                <p className="text-sm text-emerald-400">
                  ✓ Email generado correctamente
                </p>
              </div>

              <div>
                <label className="text-sm font-medium text-white/70 mb-1 block">
                  Asunto
                </label>
                <input
                  className="w-full px-3 py-2 bg-white/5 border border-white/10 rounded-md text-sm text-white"
                  value={generatedSubject}
                  onChange={(e) => setGeneratedSubject(e.target.value)}
                />
              </div>

              <div>
                <label className="text-sm font-medium text-white/70 mb-1 block">
                  Cuerpo del email
                </label>
                <Textarea
                  className="min-h-[200px] bg-white/5 border-white/10 text-white"
                  value={generatedBody}
                  onChange={(e) => setGeneratedBody(e.target.value)}
                />
              </div>

              <div className="flex gap-2">
                <Button
                  variant="outline"
                  onClick={() => {
                    setGeneratedSubject("");
                    setGeneratedBody("");
                  }}
                >
                  Regenerar
                </Button>
                <div className="flex-1" />
                <Button variant="ghost" onClick={handleClose}>
                  Cancelar
                </Button>
                <Button
                  disabled={
                    sending || !generatedSubject.trim() || !generatedBody.trim()
                  }
                  onClick={handleSend}
                >
                  {sending ? "Enviando..." : "Enviar Email"}
                </Button>
              </div>
            </div>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { ArrowRight, Clock, MoreHorizontal, Phone, Star } from "lucide-react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

import { PRIORITY_COLORS, STAGE_LABELS } from "./leadConstants";
import type { FunnelStage, Lead } from "./types";

function getNextStages(currentStage: FunnelStage): FunnelStage[] {
  const flow: Record<FunnelStage, FunnelStage[]> = {
    pending: ["approved", "rejected"],
    approved: ["demo_expiring", "meeting_scheduled", "demo_expired"],
    demo_expiring: ["demo_expired", "meeting_scheduled"],
    demo_expired: ["meeting_scheduled", "lost"],
    meeting_scheduled: ["post_meeting", "lost"],
    post_meeting: ["negotiation", "lost"],
    negotiation: ["migration", "lost"],
    migration: ["converted", "lost"],
    converted: [],
    rejected: [],
    lost: [],
  };
  return flow[currentStage] || [];
}

export function LeadCard({
  lead,
  onClick,
  onMoveToStage,
}: {
  lead: Lead;
  onClick: () => void;
  onMoveToStage: (stage: FunnelStage) => void;
}) {
  const nextStages = getNextStages(lead.funnel_stage || "pending");

  const daysUntilExpiry = lead.demo_expires_at
    ? Math.ceil(
        (new Date(lead.demo_expires_at).getTime() - Date.now()) /
          (1000 * 60 * 60 * 24),
      )
    : null;

  return (
    <div
      className="bg-white/5 border border-white/10 rounded-lg p-3 cursor-pointer hover:bg-white/10 transition-colors group relative"
      onClick={onClick}
    >
      <div className="flex items-start justify-between mb-2">
        <div className="flex-1 min-w-0">
          <p className="text-sm font-medium text-white truncate">
            {lead.full_name || lead.email}
          </p>
          {lead.optica_name && (
            <p className="text-xs text-white/50 truncate">{lead.optica_name}</p>
          )}
        </div>
        {lead.priority_level && lead.priority_level !== "cold" && (
          <div
            className={`w-2 h-2 rounded-full flex-shrink-0 ${
              PRIORITY_COLORS[lead.priority_level] || "bg-gray-500"
            }`}
            title={`Prioridad: ${lead.priority_level}`}
          />
        )}
      </div>

      <div className="flex items-center gap-2 mb-2">
        {lead.lead_score !== undefined && lead.lead_score > 0 && (
          <div className="flex items-center gap-1 text-xs text-white/50">
            <Star className="h-3 w-3 text-amber-400" />
            <span>{lead.lead_score}</span>
          </div>
        )}
        {lead.phone && (
          <div className="flex items-center gap-1 text-xs text-white/50">
            <Phone className="h-3 w-3" />
            <span className="truncate">{lead.phone}</span>
          </div>
        )}
      </div>

      <div className="flex items-center justify-between text-xs text-white/40">
        <div className="flex items-center gap-1">
          <Clock className="h-3 w-3" />
          <span suppressHydrationWarning>
            {lead.last_contact_at
              ? new Date(lead.last_contact_at).toLocaleDateString("es-CL", {
                  day: "numeric",
                  month: "short",
                })
              : "Sin contacto"}
          </span>
        </div>
        {daysUntilExpiry !== null &&
          daysUntilExpiry <= 3 &&
          daysUntilExpiry > 0 && (
            <Badge
              className="text-xs text-orange-400 border-orange-400/30"
              variant="outline"
            >
              <Clock className="h-3 w-3 mr-1" />
              {daysUntilExpiry}d
            </Badge>
          )}
      </div>

      {nextStages.length > 0 && (
        <div className="absolute top-2 right-2 z-10">
          <DropdownMenu>
            <DropdownMenuTrigger asChild onClick={(e) => e.stopPropagation()}>
              <Button
                className="h-6 w-6 text-white/70 hover:text-white hover:bg-white/10"
                size="icon"
                variant="ghost"
              >
                <MoreHorizontal className="h-4 w-4" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent
              align="end"
              className="bg-[#0D1117] border-white/20 text-white min-w-[160px]"
            >
              {nextStages.map((stage) => (
                <DropdownMenuItem
                  className="text-white hover:bg-white/10 cursor-pointer"
                  key={stage}
                  onClick={(e) => {
                    e.stopPropagation();
                    onMoveToStage(stage);
                  }}
                >
                  <ArrowRight className="h-4 w-4 mr-2" />
                  Mover a {STAGE_LABELS[stage]}
                </DropdownMenuItem>
              ))}
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { toast } from "sonner";

import { LeadActivityTimeline } from "@/components/admin/saas-management/leads/LeadActivityTimeline";
import { LeadInfoTab } from "@/components/admin/saas-management/leads/LeadInfoTab";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";

type FunnelStage =
  | "pending"
  | "approved"
  | "rejected"
  | "demo_expiring"
  | "demo_expired"
  | "meeting_scheduled"
  | "post_meeting"
  | "negotiation"
  | "migration"
  | "converted"
  | "lost";

interface Activity {
  id: string;
  activity_type: string;
  description: string | null;
  metadata: Record<string, unknown>;
  created_at: string;
  created_by_user?: {
    id: string;
    full_name: string | null;
    email: string;
  } | null;
}

export interface LeadDetail {
  id: string;
  email: string;
  full_name: string | null;
  optica_name: string | null;
  phone: string | null;
  source: string;
  funnel_stage: FunnelStage | null;
  lead_score?: number;
  priority_level?: string;
  score_last_calculated_at?: string;
  created_at: string;
  last_contact_at?: string;
  next_followup_at?: string;
  demo_started_at?: string;
  demo_expires_at?: string;
  meeting_scheduled_at?: string;
  meeting_url?: string;
  notes?: string;
  lost_reason?: string;
  utm_source?: string;
  utm_medium?: string;
  utm_campaign?: string;
}

export interface LeadDetailPanelProps {
  lead: LeadDetail | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onUpdateStage: (
    id: string,
    stage: FunnelStage,
    extra?: Record<string, unknown>,
  ) => Promise<void>;
  onApprove?: (id: string) => Promise<void>;
  onReject?: (id: string) => Promise<void>;
  onSendEmail: (lead: LeadDetail) => void;
  onGenerateAIEmail: (lead: LeadDetail) => void;
  actioning?: string | null;
}

const STAGE_LABELS: Record<FunnelStage, string> = {
  pending: "Pendiente",
  approved: "Demo activa",
  demo_expiring: "Por vencer",
  demo_expired: "Expirada",
  meeting_scheduled: "Reunión agendada",
  post_meeting: "Post-reunión",
  negotiation: "Negociación",
  migration: "Migración",
  converted: "Convertido",
  rejected: "Rechazada",
  lost: "Perdido",
};

const STAGE_COLORS: Record<FunnelStage, string> = {
  pending: "bg-amber-500/20 text-amber-400 border-amber-500/30",
  approved: "bg-emerald-500/20 text-emerald-400 border-emerald-500/30",
  demo_expiring: "bg-orange-500/20 text-orange-400 border-orange-500/30",
  demo_expired: "bg-slate-500/20 text-slate-400 border-slate-500/30",
  meeting_scheduled: "bg-blue-500/20 text-blue-400 border-blue-500/30",
  post_meeting: "bg-indigo-500/20 text-indigo-400 border-indigo-500/30",
  negotiation: "bg-violet-500/20 text-violet-400 border-violet-500/30",
  migration: "bg-cyan-500/20 text-cyan-400 border-cyan-500/30",
  converted: "bg-green-500/20 text-green-400 border-green-500/30",
  rejected: "bg-red-500/20 text-red-400 border-red-500/30",
  lost: "bg-gray-500/20 text-gray-400 border-gray-500/30",
};

const PRIORITY_CONFIG: Record<
  string,
  { label: string; color: string; bg: string }
> = {
  hot: { label: "Hot", color: "text-red-400", bg: "bg-red-500/20" },
  warm: { label: "Warm", color: "text-amber-400", bg: "bg-amber-500/20" },
  cold: { label: "Cold", color: "text-blue-400", bg: "bg-blue-500/20" },
  at_risk: { label: "At Risk", color: "text-gray-400", bg: "bg-gray-500/20" },
};

export function LeadDetailPanel({
  lead,
  open,
  onOpenChange,
  onUpdateStage,
  onApprove,
  onReject,
  onSendEmail,
  onGenerateAIEmail,
  actioning,
}: LeadDetailPanelProps) {
  const [activities, setActivities] = useState<Activity[]>([]);
  const [activitiesLoading, setActivitiesLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<"info" | "activity">("info");

  useEffect(() => {
    if (lead && open) {
      setActivitiesLoading(true);
      fetch(`/api/admin/saas-management/leads/${lead.id}/activities?limit=20`)
        .then((res) => res.json())
        .then((data) => {
          setActivities(data.activities || []);
        })
        .catch(() => {
          toast.error("Error al cargar actividades");
        })
        .finally(() => {
          setActivitiesLoading(false);
        });
    }
  }, [lead, open]);

  if (!lead) return null;

  const priorityConfig = lead.priority_level
    ? PRIORITY_CONFIG[lead.priority_level]
    : null;

  const formatDate = (date: string | undefined) => {
    if (!date) return "—";
    return new Date(date).toLocaleDateString("es-CL", {
      day: "numeric",
      month: "short",
      year: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    });
  };

  const daysUntilExpiry = lead.demo_expires_at
    ? Math.ceil(
        (new Date(lead.demo_expires_at).getTime() - Date.now()) /
          (1000 * 60 * 60 * 24),
      )
    : null;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-hidden flex flex-col bg-[#0D1117] border-white/20 text-white">
        <DialogHeader className="flex-shrink-0">
          <DialogTitle className="flex items-center gap-3 text-white">
            <span>Detalle del Lead</span>
            {priorityConfig && (
              <Badge
                className={`${priorityConfig.bg} ${priorityConfig.color} border-0`}
              >
                {priorityConfig.label}
              </Badge>
            )}
          </DialogTitle>
        </DialogHeader>

        {/* Tabs */}
        <div className="flex gap-2 border-b border-white/10 pb-2 flex-shrink-0">
          <Button
            size="sm"
            variant={activeTab === "info" ? "default" : "ghost"}
            onClick={() => setActiveTab("info")}
          >
            Información
          </Button>
          <Button
            size="sm"
            variant={activeTab === "activity" ? "default" : "ghost"}
            onClick={() => setActiveTab("activity")}
          >
            Actividad ({activities.length})
          </Button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto">
          {activeTab === "info" ? (
            <LeadInfoTab lead={lead} />
          ) : (
            <div className="py-2">
              <LeadActivityTimeline
                activities={activities}
                loading={activitiesLoading}
              />
            </div>
          )}
        </div>

        {/* Actions */}
        <div className="flex gap-2 pt-4 border-t border-white/10 flex-shrink-0">
          {/* Botones de aprobar/rechazar para leads pendientes */}
          {lead.funnel_stage === "pending" && (
            <>
              {onApprove && (
                <Button
                  disabled={actioning === lead.id}
                  size="sm"
                  variant="default"
                  onClick={() => onApprove(lead.id)}
                >
                  Aprobar Demo
                </Button>
              )}
              {onReject && (
                <Button
                  disabled={actioning === lead.id}
                  size="sm"
                  variant="destructive"
                  onClick={() => onReject(lead.id)}
                >
                  Rechazar
                </Button>
              )}
            </>
          )}
          <Button size="sm" variant="outline" onClick={() => onSendEmail(lead)}>
            Enviar Email
          </Button>
          <Button
            size="sm"
            variant="outline"
            onClick={() => onGenerateAIEmail(lead)}
          >
            Generar con IA
          </Button>
          <div className="flex-1" />
          <Button variant="ghost" onClick={() => onOpenChange(false)}>
            Cerrar
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState } from "react";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Textarea } from "@/components/ui/textarea";

export interface LeadEmailModalProps {
  lead: {
    id: string;
    email: string;
    full_name?: string | null;
    optica_name?: string | null;
    funnel_stage?: string | null;
  } | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSend: (leadId: string, subject: string, body: string) => Promise<void>;
}

const EMAIL_TEMPLATES = [
  {
    id: "followup",
    label: "Follow-up",
    subject: "Seguimiento - {{optica_name}}",
    body: `Hola {{first_name}},

Espero que estés bien. Me contacto contigo para hacer seguimiento a tu interés en Opttius.

¿Tienes alguna duda sobre la plataforma? ¿Te gustaría agendar una demostración personalizada?

Quedo atento a tu respuesta.

Saludos`,
  },
  {
    id: "proposal",
    label: "Propuesta",
    subject: "Propuesta comercial - {{optica_name}}",
    body: `Hola {{first_name}},

Gracias por tu interés en Opttius. Adjuntamos la propuesta comercial para {{optica_name}}.

La propuesta incluye:
- Acceso completo a la plataforma
- Capacitación personalizada
- Soporte técnico dedicado

¿Tienes alguna consulta sobre los términos?

Saludos`,
  },
  {
    id: "meeting",
    label: "Agendar reunión",
    subject: "Agendemos una reunión - {{optica_name}}",
    body: `Hola {{first_name}},

Nos encantaría mostrarte cómo Opttius puede transformar la gestión de tu óptica.

Tengo disponible los siguientes horarios esta semana:
- Lunes a viernes: 10:00 - 18:00 hrs

¿Cuál te funciona mejor?

Saludos`,
  },
  {
    id: "reminder",
    label: "Recordatorio demo",
    subject: "Tu demo de Opttius está lista",
    body: `Hola {{first_name}},

Tu período de prueba de Opttius está activo. Aquí tienes algunos recursos para comenzar:

📚 [Guía de inicio]
🎥 [Videos tutoriales]
💬 [Soporte en vivo]

¿Necesitas ayuda con algo específico?

Saludos`,
  },
];

export function LeadEmailModal({
  lead,
  open,
  onOpenChange,
  onSend,
}: LeadEmailModalProps) {
  const [sending, setSending] = useState(false);
  const [selectedTemplate, setSelectedTemplate] = useState<string | null>(null);
  const [subject, setSubject] = useState("");
  const [body, setBody] = useState("");

  const handleTemplateSelect = (templateId: string) => {
    const template = EMAIL_TEMPLATES.find((t) => t.id === templateId);
    if (template) {
      setSelectedTemplate(templateId);
      const firstName = lead?.full_name?.split(" ")[0] || "";
      setSubject(
        template.subject
          .replace("{{first_name}}", firstName)
          .replace("{{optica_name}}", lead?.optica_name || ""),
      );
      setBody(
        template.body
          .replace("{{first_name}}", firstName)
          .replace("{{optica_name}}", lead?.optica_name || ""),
      );
    }
  };

  const handleSend = async () => {
    if (!lead || !subject.trim() || !body.trim()) {
      toast.error("Por favor completa el asunto y el cuerpo del email");
      return;
    }

    setSending(true);
    try {
      await onSend(lead.id, subject, body);
      onOpenChange(false);
      setSubject("");
      setBody("");
      setSelectedTemplate(null);
    } catch (error) {
      toast.error("Error al enviar email");
    } finally {
      setSending(false);
    }
  };

  if (!lead) return null;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl bg-[#0D1117] border-white/20 text-white">
        <DialogHeader>
          <DialogTitle className="text-white">
            Enviar Email a {lead.full_name || lead.email}
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          {/* Template Selector */}
          <div>
            <label className="text-sm font-medium text-white/70 mb-2 block">
              Plantilla
            </label>
            <div className="flex flex-wrap gap-2">
              {EMAIL_TEMPLATES.map((template) => (
                <Button
                  key={template.id}
                  size="sm"
                  variant={
                    selectedTemplate === template.id ? "default" : "outline"
                  }
                  onClick={() => handleTemplateSelect(template.id)}
                >
                  {template.label}
                </Button>
              ))}
            </div>
          </div>

          {/* To */}
          <div>
            <label className="text-sm font-medium text-white/70 mb-1 block">
              Para
            </label>
            <div className="flex items-center gap-2">
              <input
                disabled
                className="flex-1 px-3 py-2 bg-white/5 border border-white/10 rounded-md text-sm text-white disabled:opacity-50"
                value={lead.email}
              />
              {lead.funnel_stage && (
                <Badge className="text-white border-white/30" variant="outline">
                  {lead.funnel_stage}
                </Badge>
              )}
            </div>
          </div>

          {/* Subject */}
          <div>
            <label className="text-sm font-medium text-white/70 mb-1 block">
              Asunto
            </label>
            <input
              className="w-full px-3 py-2 bg-white/5 border border-white/10 rounded-md text-sm text-white placeholder:text-white/30"
              placeholder="Asunto del email..."
              value={subject}
              onChange={(e) => setSubject(e.target.value)}
            />
          </div>

          {/* Body */}
          <div>
            <label className="text-sm font-medium text-white/70 mb-1 block">
              Cuerpo del email
            </label>
            <Textarea
              className="min-h-[200px] bg-white/5 border-white/10 text-white placeholder:text-white/30"
              placeholder="Escribe el cuerpo del email..."
              value={body}
              onChange={(e) => setBody(e.target.value)}
            />
          </div>

          {/* Actions */}
          <div className="flex justify-end gap-2 pt-4">
            <Button variant="outline" onClick={() => onOpenChange(false)}>
              Cancelar
            </Button>
            <Button
              disabled={sending || !subject.trim() || !body.trim()}
              onClick={handleSend}
            >
              {sending ? "Enviando..." : "Enviar Email"}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { Badge } from "@/components/ui/badge";
import { ScrollArea, ScrollBar } from "@/components/ui/scroll-area";

import { LeadCard } from "./LeadCard";
import { KANBAN_COLUMNS, STAGE_COLORS } from "./leadConstants";
import type { FunnelStage, Lead } from "./types";

interface LeadKanbanBoardProps {
  leads: Lead[];
  onLeadClick: (lead: Lead) => void;
  onStageChange: (leadId: string, newStage: FunnelStage) => void;
  loading?: boolean;
}

function KanbanColumn({
  stage,
  label,
  leads,
  onLeadClick,
  onMoveToStage,
}: {
  stage: FunnelStage;
  label: string;
  leads: Lead[];
  onLeadClick: (lead: Lead) => void;
  onMoveToStage: (leadId: string, newStage: FunnelStage) => void;
}) {
  return (
    <div className="flex-shrink-0 w-72">
      <div className="flex items-center justify-between mb-3 px-1">
        <div className="flex items-center gap-2">
          <span className={`w-3 h-3 rounded-full ${STAGE_COLORS[stage]}`} />
          <h3 className="font-medium text-white text-sm">{label}</h3>
        </div>
        <Badge className="bg-white/10 text-white text-xs" variant="secondary">
          {leads.length}
        </Badge>
      </div>
      <div className="space-y-2 min-h-[200px] max-h-[calc(100vh-300px)] overflow-y-auto pr-2">
        {leads.map((lead) => (
          <div className="relative" key={lead.id}>
            <LeadCard
              lead={lead}
              onClick={() => onLeadClick(lead)}
              onMoveToStage={(stage) => onMoveToStage(lead.id, stage)}
            />
          </div>
        ))}
        {leads.length === 0 && (
          <div className="border border-dashed border-white/10 rounded-lg p-4 text-center text-white/30 text-sm">
            Sin leads
          </div>
        )}
      </div>
    </div>
  );
}

export function LeadKanbanBoard({
  leads,
  onLeadClick,
  onStageChange,
  loading,
}: LeadKanbanBoardProps) {
  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-white/50">Cargando pipeline...</div>
      </div>
    );
  }

  const leadsByStage = KANBAN_COLUMNS.reduce(
    (acc, col) => {
      acc[col.stage] = leads.filter(
        (l) => (l.funnel_stage as FunnelStage) === col.stage,
      );
      return acc;
    },
    {} as Record<FunnelStage, Lead[]>,
  );

  return (
    <div className="relative">
      <ScrollArea className="w-full">
        <div className="flex gap-4 pb-4">
          {KANBAN_COLUMNS.map(({ stage, label }) => (
            <KanbanColumn
              key={stage}
              label={label}
              leads={leadsByStage[stage] || []}
              stage={stage}
              onLeadClick={onLeadClick}
              onMoveToStage={onStageChange}
            />
          ))}
        </div>
        <ScrollBar orientation="horizontal" />
      </ScrollArea>
    </div>
  );
}

"use client";

import { useMemo } from "react";

interface SupportMetrics {
  totalTickets: number;
  statusCounts: Record<string, number>;
  priorityCounts: Record<string, number>;
  categoryCounts: Record<string, number>;
  averageResponseTimeMinutes: number | null;
  averageResolutionTimeMinutes: number | null;
  averageSatisfactionRating: number | null;
  ticketsPerDay: Record<string, number>;
  topOrganizations: Array<{ id: string; name: string; count: number }>;
}

export function useSupportMetricsData(metrics: SupportMetrics) {
  const openTickets =
    (metrics.statusCounts.open || 0) +
    (metrics.statusCounts.assigned || 0) +
    (metrics.statusCounts.in_progress || 0) +
    (metrics.statusCounts.waiting_customer || 0);

  const resolvedTickets =
    (metrics.statusCounts.resolved || 0) + (metrics.statusCounts.closed || 0);

  const ticketsPerDayChartData = useMemo(() => {
    const entries = Object.entries(metrics.ticketsPerDay)
      .sort(([a], [b]) => a.localeCompare(b))
      .slice(-30);
    return entries.map(([date, value]) => ({ date, value, count: value }));
  }, [metrics.ticketsPerDay]);

  const statusPieData = useMemo(
    () =>
      Object.entries(metrics.statusCounts)
        .filter(([, v]) => v > 0)
        .map(([label, value]) => ({ label: label.replace("_", " "), value })),
    [metrics.statusCounts],
  );

  const priorityPieData = useMemo(
    () =>
      Object.entries(metrics.priorityCounts)
        .filter(([, v]) => v > 0)
        .map(([label, value]) => ({ label: label.replace("_", " "), value })),
    [metrics.priorityCounts],
  );

  const topOrgsBarData = useMemo(
    () =>
      metrics.topOrganizations.slice(0, 8).map((org) => ({
        label: org.name.length > 25 ? org.name.slice(0, 22) + "…" : org.name,
        value: org.count,
      })),
    [metrics.topOrganizations],
  );

  const handleExportCsv = () => {
    const params = new URLSearchParams({ format: "csv", limit: "5000" });
    window.open(
      `/api/admin/saas-management/support/export?${params.toString()}`,
      "_blank",
      "noopener,noreferrer",
    );
  };

  return {
    openTickets,
    resolvedTickets,
    ticketsPerDayChartData,
    statusPieData,
    priorityPieData,
    topOrgsBarData,
    handleExportCsv,
  };
}

"use client";

import { useCallback, useMemo, useRef, useState } from "react";

import type { Block, BubbleState } from "@/lib/ai/types";

import { useAgentContext } from "./AgentContextProvider";
import { AgentPreferencesPanel, useAgentPreferences } from "./AgentPreferences";
import { BubbleFloatingButton } from "./BubbleFloatingButton";
import { BubblePanel } from "./BubblePanel";

// ponytail: per-route suggestions — static for now, replace with
// agent.getScreenSuggestions() when the agent can suggest actions.
function getSuggestions(
  route: string,
  onAsk: (q: string) => void,
): Array<{ label: string; onClick: () => void }> {
  const common = [
    {
      label: "📊 Resumen del día",
      onClick: () => onAsk("¿Cuál es el resumen del día?"),
    },
    {
      label: "📋 Clientes recientes",
      onClick: () => onAsk("Muéstrame los clientes recientes"),
    },
  ];
  if (route.includes("/admin/customers"))
    return [
      {
        label: "🔍 Buscar cliente",
        onClick: () => onAsk("Ayúdame a buscar un cliente"),
      },
      ...common,
    ];
  if (route.includes("/admin/pos"))
    return [
      { label: "🛒 Abrir caja", onClick: () => onAsk("¿Cómo abro la caja?") },
      {
        label: "📦 Más vendidos",
        onClick: () => onAsk("¿Cuáles son los productos más vendidos hoy?"),
      },
      ...common,
    ];
  if (route.includes("/admin/work-orders"))
    return [
      {
        label: "👓 Trabajos pendientes",
        onClick: () => onAsk("¿Cuántos trabajos hay pendientes?"),
      },
      ...common,
    ];
  if (route.includes("/admin/appointments"))
    return [
      {
        label: "📅 Citas de hoy",
        onClick: () => onAsk("¿Qué citas tengo hoy?"),
      },
      ...common,
    ];
  return common;
}

function getGreeting(route: string, branchName: string): string {
  if (route.includes("/admin/pos")) return `💰 Punto de Venta — ${branchName}`;
  if (route.includes("/admin/customers"))
    return `👥 Gestión de Clientes — ${branchName}`;
  if (route.includes("/admin/work-orders"))
    return `👓 Trabajos de Laboratorio — ${branchName}`;
  if (route.includes("/admin/appointments"))
    return `📅 Agenda y Citas — ${branchName}`;
  if (route.includes("/admin/products")) return `📦 Inventario — ${branchName}`;
  return `🤖 Agente Opttius — ${branchName}`;
}

interface AgentBubbleProps {
  route?: string;
  branchName?: string;
}

/**
 * AgentBubble — state machine container for the Agent copilot.
 *
 * Phase 2: sends messages to POST /api/agent/chat and renders
 * SSE stream responses as structured blocks.
 * Phase 4: integrates preferences, auto-mode triggers, SSE reconnection.
 */
export function AgentBubble({
  route: routeProp = "/admin",
  branchName: branchNameProp = "Sucursal",
}: AgentBubbleProps) {
  const [state, setState] = useState<BubbleState>("collapsed");
  const [badgeCount, setBadgeCount] = useState(0);
  const [inputValue, setInputValue] = useState("");
  const [messages, setMessages] = useState<Block[][]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [showPreferences, setShowPreferences] = useState(false);
  const [attachedFile, setAttachedFile] = useState<{
    name: string;
    content: string;
  } | null>(null);
  const sessionIdRef = useRef<string | undefined>(undefined);
  const abortRef = useRef<AbortController | null>(null);

  // Read screen context from the AgentContextProvider
  const agentCtx = useAgentContext();

  // Phase 4: Agent preferences from localStorage
  const {
    prefs,
    update: updatePrefs,
    reset: resetPrefs,
  } = useAgentPreferences(agentCtx.userId);

  // Derived route/branch — props take precedence, fall back to context
  const route = routeProp !== "/admin" ? routeProp : agentCtx.route;
  const branchName =
    branchNameProp !== "Sucursal" ? branchNameProp : agentCtx.branchName;

  // ——— State transitions ———

  const handleOpen = useCallback(() => {
    if (state === "notification") setBadgeCount(0);
    setState("repose");
  }, [state]);

  const handleClose = useCallback(() => {
    setState("collapsed");
  }, []);

  const handleToggleDock = useCallback(() => {
    setState((prev) => (prev === "docked" ? "conversation" : "docked"));
  }, []);

  // ——— SSE Fetch with reconnection ———

  const fetchAgent = useCallback(
    async (text: string, retries = 1): Promise<void> => {
      const body = {
        message: text,
        session_id: sessionIdRef.current,
        context: {
          route: agentCtx.route,
          branch_id: agentCtx.branchId,
          branch_name: agentCtx.branchName,
          role: agentCtx.role,
          org_id: agentCtx.orgId,
        },
      };

      const res = await fetch("/api/agent/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
        signal: abortRef.current?.signal,
      });

      if (!res.ok) {
        const errBody = await res
          .json()
          .catch(() => ({ error: "Error de conexión" }));
        const errorBlock: Block = {
          type: "error",
          content:
            errBody.error ||
            `Error ${res.status}: no se pudo procesar tu mensaje.`,
        };
        setMessages((prev) => [...prev, [errorBlock]]);
        setIsLoading(false);
        return;
      }

      const reader = res.body?.getReader();
      if (!reader) throw new Error("No response body");

      const decoder = new TextDecoder();
      let buffer = "";
      const responseBlocks: Block[] = [];
      let currentEvent = "";

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split("\n");
        buffer = lines.pop() || "";

        for (const line of lines) {
          if (line.startsWith("event: ")) {
            currentEvent = line.slice(7).trim();
            continue;
          }
          if (line.startsWith("data: ")) {
            const data = line.slice(6);
            if (currentEvent === "done") continue;
            if (currentEvent === "block") {
              try {
                const parsed = JSON.parse(data) as Block;
                responseBlocks.push(parsed);
              } catch {
                // Ignore parse errors on incomplete chunks
              }
            }
          }
        }
      }

      if (responseBlocks.length > 0) {
        setMessages((prev) => [...prev, responseBlocks]);
      }
    },
    [agentCtx],
  );

  const sendToAgent = useCallback(
    async (text: string) => {
      if (isLoading) return;
      setIsLoading(true);

      // Prepend file context if a file was attached
      const fileCtx = attachedFile;
      let messageText = text;
      if (fileCtx) {
        messageText = `[Archivo adjunto: ${fileCtx.name}]\n\`\`\`\n${fileCtx.content.slice(0, 10000)}\n\`\`\`\n\n${text}`;
        setAttachedFile(null);
      }

      // Add user message block
      const userBlock: Block = { type: "text", content: text };
      setMessages((prev) => [...prev, [userBlock]]);

      // Abort previous request if any
      if (abortRef.current) abortRef.current.abort();
      const controller = new AbortController();
      abortRef.current = controller;

      try {
        await fetchAgent(messageText);
      } catch (err: unknown) {
        if (err instanceof Error && err.name === "AbortError") return;
        // ponytail: simple error block — add retry UI if users report connection drops
        const errorBlock: Block = {
          type: "error",
          content:
            "Ocurrió un error al procesar tu solicitud. Intenta de nuevo.",
        };
        setMessages((prev) => [...prev, [errorBlock]]);
      } finally {
        setIsLoading(false);
        abortRef.current = null;
      }
    },
    [agentCtx, isLoading, fetchAgent, attachedFile],
  );

  const handleSend = useCallback(() => {
    const text = inputValue.trim();
    if (!text || isLoading) return;

    if (state === "repose") setState("conversation");
    setInputValue("");
    sendToAgent(text);
  }, [inputValue, state, isLoading, sendToAgent]);

  const handleAction = useCallback(
    (_action: string, _params?: Record<string, unknown>) => {
      // ponytail: action blocks handled when tool confirmations are wired
    },
    [],
  );

  const handleAsk = useCallback((question: string) => {
    setInputValue(question);
  }, []);

  const handleAttach = useCallback(
    (file: { name: string; content: string }) => {
      setAttachedFile(file);
      if (state === "repose") setState("conversation");
      // Show a system notice that a file was attached
      const notice: Block = {
        type: "success",
        content: `📎 Archivo adjunto: ${file.name} (${file.content.length} caracteres)`,
      };
      setMessages((prev) => [...prev, [notice]]);
    },
    [state],
  );

  const handlePreferencesToggle = useCallback(() => {
    setShowPreferences((prev) => !prev);
  }, []);

  // ——— Derived state ———

  const title = useMemo(() => {
    if (state === "repose" || state === "conversation" || state === "docked") {
      return getGreeting(route, branchName);
    }
    return "Agente Opttius";
  }, [state, route, branchName]);

  const suggestions = useMemo(
    () => (state === "repose" ? getSuggestions(route, handleAsk) : undefined),
    [state, route, handleAsk],
  );

  const isOpen =
    state === "repose" || state === "conversation" || state === "docked";

  return (
    <>
      {isOpen ? (
        <div className="relative">
          <BubblePanel
            inputDisabled={isLoading}
            inputValue={inputValue}
            messages={messages}
            state={
              state === "docked"
                ? "docked"
                : state === "repose"
                  ? "repose"
                  : "conversation"
            }
            suggestions={suggestions}
            title={title}
            onAction={handleAction}
            onAttach={handleAttach}
            onClose={handleClose}
            onInputChange={setInputValue}
            onPreferences={handlePreferencesToggle}
            onSend={handleSend}
            onToggleDock={handleToggleDock}
          />
          {/* Preferences overlay */}
          {showPreferences && (
            <div className="absolute inset-0 z-10 rounded-xl bg-white">
              <AgentPreferencesPanel
                prefs={prefs}
                userId={agentCtx.userId}
                onClose={handlePreferencesToggle}
                onReset={resetPrefs}
                onUpdate={updatePrefs}
              />
            </div>
          )}
        </div>
      ) : (
        <BubbleFloatingButton
          badgeCount={badgeCount}
          state={state}
          onClick={handleOpen}
        />
      )}
    </>
  );
}

"use client";

import { useCallback, useEffect, useState } from "react";

// ─── Types ──────────────────────────────────────────────────────────────────

export type BubblePosition = "floating" | "docked";
export type AgentTone = "professional" | "casual" | "concise";

export interface AgentPreferences {
  auto_mode: boolean;
  bubble_position: BubblePosition;
  agent_tone: AgentTone;
}

const DEFAULTS: AgentPreferences = {
  auto_mode: false,
  bubble_position: "floating",
  agent_tone: "professional",
};

// ─── Storage helpers ────────────────────────────────────────────────────────

function storageKey(userId: string): string {
  return `agent:preferences:${userId}`;
}

function loadPreferences(userId: string): AgentPreferences {
  if (typeof window === "undefined") return DEFAULTS;
  try {
    const raw = localStorage.getItem(storageKey(userId));
    if (!raw) return DEFAULTS;
    return { ...DEFAULTS, ...(JSON.parse(raw) as Partial<AgentPreferences>) };
  } catch {
    return DEFAULTS;
  }
}

function savePreferences(userId: string, prefs: AgentPreferences): void {
  if (typeof window === "undefined") return;
  try {
    localStorage.setItem(storageKey(userId), JSON.stringify(prefs));
  } catch {
    // localStorage full or unavailable — skip
  }
}

// ─── Hook ───────────────────────────────────────────────────────────────────

export function useAgentPreferences(userId: string) {
  const [prefs, setPrefs] = useState<AgentPreferences>(() =>
    loadPreferences(userId),
  );

  useEffect(() => {
    savePreferences(userId, prefs);
  }, [userId, prefs]);

  const update = useCallback(
    <K extends keyof AgentPreferences>(key: K, value: AgentPreferences[K]) => {
      setPrefs((prev) => ({ ...prev, [key]: value }));
    },
    [],
  );

  const reset = useCallback(() => {
    setPrefs(DEFAULTS);
  }, []);

  return { prefs, update, reset };
}

// ─── Component ──────────────────────────────────────────────────────────────

interface AgentPreferencesProps {
  userId: string;
  prefs: AgentPreferences;
  onUpdate: <K extends keyof AgentPreferences>(
    key: K,
    value: AgentPreferences[K],
  ) => void;
  onClose: () => void;
  onReset: () => void;
}

/**
 * Agent preferences panel — rendered inside BubblePanel or as a modal.
 * Persists to localStorage scoped by userId.
 */
export function AgentPreferencesPanel({
  prefs,
  onUpdate,
  onClose,
  onReset,
}: AgentPreferencesProps) {
  return (
    <div className="flex flex-col gap-4 p-4 text-sm">
      <div className="flex items-center justify-between">
        <h4 className="font-semibold text-gray-800">Preferencias del Agente</h4>
        <button
          aria-label="Cerrar preferencias"
          className="rounded p-1 text-gray-400 hover:text-gray-600"
          type="button"
          onClick={onClose}
        >
          <svg
            className="h-4 w-4"
            fill="none"
            stroke="currentColor"
            strokeWidth={2}
            viewBox="0 0 24 24"
          >
            <path
              d="M6 18L18 6M6 6l12 12"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </button>
      </div>

      {/* Auto-mode toggle */}
      <label className="flex items-center justify-between gap-3 rounded-lg border border-gray-200 p-3">
        <div>
          <div className="font-medium text-gray-700">Modo automático</div>
          <div className="text-xs text-gray-500">
            Notificaciones proactivas de stock bajo, citas y OT vencidas
          </div>
        </div>
        <button
          aria-checked={prefs.auto_mode}
          className={`relative h-5 w-9 rounded-full transition-colors ${
            prefs.auto_mode ? "bg-epoch-primary" : "bg-gray-300"
          }`}
          role="switch"
          type="button"
          onClick={() => onUpdate("auto_mode", !prefs.auto_mode)}
        >
          <span
            className={`absolute left-0.5 top-0.5 h-4 w-4 rounded-full bg-white shadow transition-transform ${
              prefs.auto_mode ? "translate-x-4" : "translate-x-0"
            }`}
          />
        </button>
      </label>

      {/* Bubble position */}
      <label className="flex items-center justify-between gap-3 rounded-lg border border-gray-200 p-3">
        <div>
          <div className="font-medium text-gray-700">
            Posición de la burbuja
          </div>
          <div className="text-xs text-gray-500">
            Flotante o panel fijo lateral
          </div>
        </div>
        <select
          className="rounded-lg border border-gray-300 px-2 py-1 text-sm focus:outline-none focus:ring-2 focus:ring-epoch-accent"
          value={prefs.bubble_position}
          onChange={(e) =>
            onUpdate("bubble_position", e.target.value as BubblePosition)
          }
        >
          <option value="floating">Flotante</option>
          <option value="docked">Fijo</option>
        </select>
      </label>

      {/* Agent tone */}
      <label className="flex items-center justify-between gap-3 rounded-lg border border-gray-200 p-3">
        <div>
          <div className="font-medium text-gray-700">Tono del agente</div>
          <div className="text-xs text-gray-500">
            Cómo se comunica el asistente
          </div>
        </div>
        <select
          className="rounded-lg border border-gray-300 px-2 py-1 text-sm focus:outline-none focus:ring-2 focus:ring-epoch-accent"
          value={prefs.agent_tone}
          onChange={(e) => onUpdate("agent_tone", e.target.value as AgentTone)}
        >
          <option value="professional">Profesional</option>
          <option value="casual">Casual</option>
          <option value="concise">Conciso</option>
        </select>
      </label>

      {/* Reset */}
      <button
        className="self-start rounded-lg px-3 py-1.5 text-xs text-gray-500 transition-colors hover:bg-gray-100 hover:text-gray-700"
        type="button"
        onClick={onReset}
      >
        Restablecer valores predeterminados
      </button>
    </div>
  );
}

