"use client";

import { useRef } from "react";

interface BubbleInputProps {
  value: string;
  onChange: (value: string) => void;
  onSend: () => void;
  onAttach?: (file: { name: string; content: string }) => void;
  disabled?: boolean;
  placeholder?: string;
}

/**
 * Auto-resizing textarea with a send button and file attach button.
 */
export function BubbleInput({
  value,
  onChange,
  onSend,
  onAttach,
  disabled = false,
  placeholder = "Escribe un mensaje...",
}: BubbleInputProps) {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      if (value.trim() && !disabled) onSend();
    }
  };

  const handleChange = (val: string) => {
    onChange(val);
    if (textareaRef.current) {
      textareaRef.current.style.height = "auto";
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 96)}px`;
    }
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !onAttach) return;

    try {
      const text = await file.text();
      onAttach({ name: file.name, content: text });
    } catch {
      // ignore binary files
    }

    // Reset so the same file can be re-selected
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  return (
    <div className="flex items-end gap-2 border-t border-gray-100 p-3">
      {/* Attach file button */}
      {onAttach && (
        <>
          <button
            aria-label="Adjuntar archivo"
            className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl text-gray-400 transition-colors hover:bg-gray-100 hover:text-gray-600"
            type="button"
            onClick={() => fileInputRef.current?.click()}
          >
            <svg
              className="h-5 w-5"
              fill="none"
              stroke="currentColor"
              strokeWidth={2}
              viewBox="0 0 24 24"
            >
              <path
                d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </button>
          <input
            accept=".txt,.csv,.json,.md,.log,.env"
            className="hidden"
            ref={fileInputRef}
            type="file"
            onChange={handleFileSelect}
          />
        </>
      )}

      <textarea
        className="max-h-24 min-h-[36px] flex-1 resize-none rounded-xl border border-gray-200 bg-gray-50 px-3 py-2 text-sm text-gray-800 placeholder-gray-400 outline-none transition-colors focus:border-epoch-accent focus:bg-white focus:ring-1 focus:ring-epoch-accent disabled:opacity-50"
        disabled={disabled}
        placeholder={placeholder}
        ref={textareaRef}
        rows={1}
        value={value}
        onChange={(e) => handleChange(e.target.value)}
        onKeyDown={handleKeyDown}
      />
      <button
        aria-label="Enviar mensaje"
        className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-epoch-accent text-epoch-surface transition-colors hover:bg-epoch-accent/90 disabled:opacity-40"
        disabled={!value.trim() || disabled}
        type="button"
        onClick={onSend}
      >
        <svg
          className="h-4 w-4"
          fill="none"
          stroke="currentColor"
          strokeWidth={2}
          viewBox="0 0 24 24"
        >
          <path
            d="M6 12L3.269 3.126A59.768 59.768 0 0121.485 12 59.77 59.77 0 013.27 20.876L5.999 12zm0 0h7.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
      </button>
    </div>
  );
}

"use client";

import type { Block, BubbleState } from "@/lib/ai/types";
import { cn } from "@/lib/utils";

import { BubbleHeader } from "./BubbleHeader";
import { BubbleInput } from "./BubbleInput";
import { BubbleMessages } from "./BubbleMessages";
import { BubbleSuggestions } from "./BubbleSuggestions";

interface Suggestion {
  label: string;
  onClick: () => void;
}

interface BubblePanelProps {
  state: Extract<BubbleState, "repose" | "conversation" | "docked">;
  title: string;
  messages: Block[][];
  inputValue: string;
  onInputChange: (value: string) => void;
  onSend: () => void;
  onClose: () => void;
  onToggleDock: () => void;
  onAction?: (action: string, params?: Record<string, unknown>) => void;
  onPreferences?: () => void;
  onAttach?: (file: { name: string; content: string }) => void;
  suggestions?: Suggestion[];
  inputDisabled?: boolean;
}

/**
 * Agent Bubble expanded panel. Two visual modes:
 * - `floating`: 480px overlay panel, max-h-[720px]
 * - `docked`: fixed side panel 460px, full viewport height
 */
export function BubblePanel({
  state,
  title,
  messages,
  inputValue,
  onInputChange,
  onSend,
  onClose,
  onToggleDock,
  onAction,
  onPreferences,
  onAttach,
  suggestions,
  inputDisabled = false,
}: BubblePanelProps) {
  const isDocked = state === "docked";

  return (
    <div
      className={cn(
        "flex flex-col overflow-hidden rounded-xl bg-white shadow-2xl transition-all duration-300",
        isDocked
          ? "fixed right-0 top-0 z-40 h-full w-[460px] rounded-none border-l border-gray-200"
          : "fixed bottom-24 right-6 z-50 w-[480px] max-h-[720px]",
      )}
    >
      <BubbleHeader
        state={state}
        title={title}
        onClose={onClose}
        onPreferences={onPreferences}
        onToggleDock={onToggleDock}
      />

      <BubbleMessages messages={messages} onAction={onAction} />

      {/* Suggestions shown in repose state */}
      {state === "repose" && suggestions && suggestions.length > 0 && (
        <BubbleSuggestions suggestions={suggestions} />
      )}

      <BubbleInput
        disabled={inputDisabled}
        placeholder={
          state === "repose"
            ? "Haz una pregunta o selecciona una opción..."
            : "Escribe un mensaje..."
        }
        value={inputValue}
        onAttach={onAttach}
        onChange={onInputChange}
        onSend={onSend}
      />
    </div>
  );
}

