function FeatureCard({
  feature,
  index,
  onOpenSlides,
}: {
  feature: (typeof features)[number];
  index: number;
  onOpenSlides?: () => void;
}) {
  const [imageError, setImageError] = useState(false);
  const showImage = feature.image && !imageError;

  const isComingSoon = "comingSoon" in feature && feature.comingSoon;
  const hasSlides = "slidesFolder" in feature && feature.slidesFolder;

  const handleClick = () => {
    if (hasSlides && onOpenSlides) onOpenSlides();
  };

  return (
    <div
      className={`group relative overflow-hidden rounded-xl p-6 sm:p-8 border border-epoch-primary/5 transition-all duration-700 flex flex-col justify-between hover:shadow-2xl hover:-translate-y-1 ${feature.className} ${isComingSoon ? "opacity-90" : ""} ${hasSlides ? "cursor-pointer focus:outline-none focus:ring-2 focus:ring-epoch-accent focus:ring-offset-2" : ""}`}
      role={hasSlides ? "button" : undefined}
      tabIndex={hasSlides ? 0 : undefined}
      onClick={hasSlides ? handleClick : undefined}
      onKeyDown={
        hasSlides
          ? (e) => {
              if (e.key === "Enter" || e.key === " ") {
                e.preventDefault();
                handleClick();
              }
            }
          : undefined
      }
    >
      {isComingSoon && (
        <div className="absolute top-4 right-4 z-20">
          <span className="inline-flex px-3 py-1 rounded-full text-[9px] font-sans font-semibold tracking-wider uppercase bg-epoch-accent/20 text-epoch-accent border border-epoch-accent/40">
            En construcción
          </span>
        </div>
      )}
      {showImage && (
        <div className="absolute inset-0 z-0">
          <Image
            fill
            alt={feature.title}
            className="object-cover opacity-10 grayscale group-hover:grayscale-0 group-hover:opacity-20 transition-all duration-700"
            src={feature.image!}
            onError={() => setImageError(true)}
          />
          <div
            className={`absolute inset-0 bg-gradient-to-t ${
              feature.className.includes("bg-epoch-primary")
                ? "from-epoch-primary via-epoch-primary/40"
                : "from-white via-white/40"
            } to-transparent`}
          />
        </div>
      )}

      <div className="relative z-10">
        <div
          className={`mb-6 p-3 inline-block rounded-xl border ${
            feature.className.includes("text-white")
              ? "border-white/20 text-epoch-accent"
              : "border-epoch-primary/10 text-epoch-primary group-hover:bg-epoch-primary group-hover:text-white"
          } transition-all duration-500`}
