"use client";

import { Check, ChevronLeft, ChevronRight, X } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { TourStep } from "@/lib/onboarding/tour-config";

interface TourCardProps {
  step: TourStep;
  currentStep: number;
  totalSteps: number;
  onNext: () => void;
  onPrevious: () => void;
  onSkip: () => void;
  onComplete: () => void;
  position?: "top" | "bottom" | "left" | "right" | "center";
  elementBounds: DOMRect | null;
}

export function TourCard({
  step,
  currentStep,
  totalSteps,
  onNext,
  onPrevious,
  onSkip,
  onComplete,
  position = "bottom",
  elementBounds,
}: TourCardProps) {
  const isLastStep = currentStep === totalSteps - 1;
  const isFirstStep = currentStep === 0;

  // Calcular posición de la tarjeta relativa al elemento destacado
  const cardStyle: React.CSSProperties = {
    position: "fixed",
    zIndex: 9999,
    pointerEvents: "auto",
    maxWidth: "400px",
    width: "90%",
  };

  if (elementBounds) {
    const padding = 20;
    const cardHeight = 400; // Estimación aproximada
    const cardWidth = 400;

    switch (position) {
      case "top":
        cardStyle.bottom = `${window.innerHeight - elementBounds.top + padding}px`;
        cardStyle.left = `${Math.max(padding, Math.min(elementBounds.left, window.innerWidth - cardWidth - padding))}px`;
        break;
      case "bottom":
        cardStyle.top = `${elementBounds.bottom + padding}px`;
        cardStyle.left = `${Math.max(padding, Math.min(elementBounds.left, window.innerWidth - cardWidth - padding))}px`;
        break;
      case "left":
        cardStyle.top = `${Math.max(padding, elementBounds.top)}px`;
        cardStyle.right = `${window.innerWidth - elementBounds.left + padding}px`;
        break;
      case "right":
        cardStyle.top = `${Math.max(padding, elementBounds.top)}px`;
        cardStyle.left = `${elementBounds.right + padding}px`;
        break;
      case "center":
        cardStyle.top = "50%";
        cardStyle.left = "50%";
        cardStyle.transform = "translate(-50%, -50%)";
        break;
    }

    // Asegurar que la tarjeta no se salga de la pantalla
    if (cardStyle.top && typeof cardStyle.top === "string") {
      const topValue = parseInt(cardStyle.top);
      if (topValue + cardHeight > window.innerHeight) {
        cardStyle.top = `${window.innerHeight - cardHeight - padding}px`;
      }
    }
    if (cardStyle.bottom && typeof cardStyle.bottom === "string") {
      const bottomValue = parseInt(cardStyle.bottom);
      if (bottomValue + cardHeight > window.innerHeight) {
        cardStyle.bottom = `${padding}px`;
      }
    }
  } else {
    // Fallback si no hay bounds - mostrar en el centro de la pantalla
    cardStyle.top = "50%";
    cardStyle.left = "50%";
    cardStyle.transform = "translate(-50%, -50%)";
    cardStyle.width = "90%";
    cardStyle.maxWidth = "500px";
  }

  return (
    <Card
      className="shadow-2xl border-2 border-primary/20 bg-background animate-in fade-in-0 zoom-in-95 duration-200"
      style={cardStyle}
    >
      <CardHeader className="pb-3">
        <div className="flex items-start justify-between">
          <div className="flex-1">
            <CardTitle className="text-lg">{step.title}</CardTitle>
            <p className="text-xs text-muted-foreground mt-1">
              Paso {currentStep + 1} de {totalSteps}
            </p>
          </div>
          <Button
            className="h-6 w-6"
            size="icon"
            title="Cerrar tour"
            variant="ghost"
            onClick={onSkip}
          >
            <X className="h-4 w-4" />
          </Button>
        </div>
      </CardHeader>
      <CardContent className="space-y-4">
        <p className="text-sm text-foreground">{step.description}</p>

        {step.keyActions.length > 0 && (
          <ul className="space-y-2">
            {step.keyActions.map((action, index) => (
              <li className="flex items-start gap-2 text-sm" key={index}>
                <Check className="h-4 w-4 text-green-600 mt-0.5 shrink-0" />
                <span className="text-muted-foreground">{action}</span>
              </li>
            ))}
          </ul>
        )}

        {step.actionUrl && step.actionLabel && (
          <Button
            className="w-full"
            variant="outline"
            onClick={() => {
              window.location.href = step.actionUrl!;
            }}
          >
            {step.actionLabel}
          </Button>
        )}

        <div className="flex items-center justify-between pt-2 border-t">
          <Button
            disabled={isFirstStep}
            size="sm"
            variant="ghost"
            onClick={onPrevious}
          >
            <ChevronLeft className="h-4 w-4 mr-1" />
            Anterior
          </Button>

          <div className="flex items-center gap-2">
            <Button size="sm" variant="ghost" onClick={onSkip}>
              Saltar Tour
            </Button>
            {isLastStep ? (
              <Button size="sm" onClick={onComplete}>
                Finalizar
                <Check className="h-4 w-4 ml-1" />
              </Button>
            ) : (
              <Button size="sm" onClick={onNext}>
                Siguiente
                <ChevronRight className="h-4 w-4 ml-1" />
              </Button>
            )}
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import { useEffect, useState } from "react";
import { createPortal } from "react-dom";

interface TourOverlayProps {
  selector: string;
  isActive: boolean;
  children: React.ReactNode;
}

export function TourOverlay({
  selector,
  isActive,
  children,
}: TourOverlayProps) {
  const [elementBounds, setElementBounds] = useState<DOMRect | null>(null);
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  useEffect(() => {
    if (!isActive || !mounted) {
      setElementBounds(null);
      return;
    }

    let cleanup: (() => void) | null = null;
    let timeoutId: NodeJS.Timeout | null = null;

    // Función para actualizar bounds
    const updateBounds = () => {
      const element = document.querySelector(selector);
      if (element) {
        const rect = element.getBoundingClientRect();
        if (rect.width > 0 && rect.height > 0) {
          setElementBounds(rect);
        }
      }
    };

    // Función para buscar el elemento con múltiples intentos
    let attempts = 0;
    const maxAttempts = 10;

    const tryFind = () => {
      attempts++;
      const element = document.querySelector(selector);

      if (element) {
        const rect = element.getBoundingClientRect();
        // Verificar que el elemento sea visible
        if (rect.width > 0 && rect.height > 0) {
          setElementBounds(rect);

          // Configurar listeners para actualizar bounds
          window.addEventListener("scroll", updateBounds, true);
          window.addEventListener("resize", updateBounds);

          const observer = new MutationObserver(updateBounds);
          observer.observe(document.body, {
            childList: true,
            subtree: true,
            attributes: true,
            attributeFilter: ["style", "class"],
          });

          cleanup = () => {
            window.removeEventListener("scroll", updateBounds, true);
            window.removeEventListener("resize", updateBounds);
            observer.disconnect();
          };
          return;
        }
      }

      if (attempts < maxAttempts) {
        timeoutId = setTimeout(tryFind, 200);
      } else {
        // Solo loguear una vez para evitar spam
        if (attempts === maxAttempts) {
          // Silenciar logs en producción - el tour funcionará sin el elemento
        }
        setElementBounds(null);
      }
    };

    // Esperar un poco antes de empezar a buscar
    timeoutId = setTimeout(tryFind, 100);

    return () => {
      if (timeoutId) clearTimeout(timeoutId);
      if (cleanup) cleanup();
    };
  }, [selector, isActive, mounted]);

  if (!isActive || !mounted) return null;

  // Create spotlight effect using radial gradient solo si hay bounds
  const spotlightStyle: React.CSSProperties = elementBounds
    ? {
        position: "fixed",
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        pointerEvents: "none",
        zIndex: 9998,
        background: `radial-gradient(
      ellipse ${elementBounds.width + 40}px ${elementBounds.height + 40}px at 
      ${elementBounds.left + elementBounds.width / 2}px 
      ${elementBounds.top + elementBounds.height / 2}px,
      transparent 0%,
      transparent 50%,
      rgba(0, 0, 0, 0.6) 100%
    )`,
      }
    : {
        position: "fixed",
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        pointerEvents: "none",
        zIndex: 9998,
        background: "rgba(0, 0, 0, 0.5)",
      };

  // Siempre renderizar children - el tour debe funcionar incluso sin encontrar el elemento
  return createPortal(
    <>
      <div style={spotlightStyle} />
      {children}
    </>,
    document.body,
  );
}

"use client";

import { usePathname, useRouter } from "next/navigation";
import { useCallback, useEffect, useRef, useState } from "react";

import { useRoot } from "@/hooks/useRoot";
import { useTour } from "@/hooks/useTour";
import { TOUR_CONFIG, TOUR_STEPS } from "@/lib/onboarding/tour-config";

import { TourCard } from "./TourCard";
import { TourOverlay } from "./TourOverlay";
import { TourProgress } from "./TourProgress";

interface TourProviderProps {
  children: React.ReactNode;
}

export function TourProvider({ children }: TourProviderProps) {
  const {
    progress,
    isLoading,
    currentStep,
    totalSteps,
    isActive,
    isNotStarted,
    startTour,
    completeStep,
    completeTour,
    skipTour,
    isStarting,
    goToStep,
  } = useTour();

  const { isRoot } = useRoot();

  const pathname = usePathname();
  const router = useRouter();
  const [elementBounds, setElementBounds] = useState<DOMRect | null>(null);
  const [mounted, setMounted] = useState(false);
  const [isNavigating, setIsNavigating] = useState(false);
  const [forceDisabled, setForceDisabled] = useState(false);
  const [hasCompletedInvalidStep, setHasCompletedInvalidStep] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  // Deshabilitar tour cuando está desactivado por configuración (feature flag)
  useEffect(() => {
    if (!TOUR_CONFIG.enabled) {
      setForceDisabled(true);
    }
  }, []);

  // Deshabilitar tour para usuarios root/dev
  useEffect(() => {
    if (isRoot) {
      setForceDisabled(true);
    }
  }, [isRoot]);

  // Auto-iniciar tour en primera visita - optimizado para evitar múltiples renders
  const hasAutoStartedRef = useRef(false);
  useEffect(() => {
    // No iniciar tour si es usuario root/dev o ya se inició
    if (isRoot || forceDisabled || hasAutoStartedRef.current) {
      return;
    }

    if (
      !isLoading &&
      isNotStarted &&
      TOUR_CONFIG.autoStart &&
      !isStarting &&
      mounted &&
      !forceDisabled &&
      pathname.startsWith("/admin")
    ) {
      // Marcar como iniciado inmediatamente para evitar múltiples llamadas
      hasAutoStartedRef.current = true;

      // Esperar un tiempo reducido ya que usamos páginas mockup (más rápidas)
      const timer = setTimeout(
        () => {
          startTour();
        },
        TOUR_CONFIG.useMockupPages ? 500 : 1500,
      );
      return () => clearTimeout(timer);
    }
  }, [
    isLoading,
    isNotStarted,
    startTour,
    isStarting,
    mounted,
    pathname,
    forceDisabled,
    isRoot,
  ]);

  // Navegar a la página correcta si el paso requiere una página específica
  useEffect(() => {
    if (!isActive || !mounted || isNavigating) return;

    const currentStepData = TOUR_STEPS[currentStep];
    if (!currentStepData) return;

    // Usar páginas mockup si está habilitado para mejor performance
    const useMockup = TOUR_CONFIG.useMockupPages;
    const basePath = useMockup ? TOUR_CONFIG.mockupBasePath : "/admin";

    // Mapear secciones a rutas
    const sectionToRoute: Record<string, string> = {
      dashboard: useMockup ? `${basePath}?section=dashboard` : "/admin",
      customers: useMockup
        ? `${basePath}?section=customers`
        : "/admin/customers",
      products: useMockup ? `${basePath}?section=products` : "/admin/products",
      quotes: useMockup ? `${basePath}?section=quotes` : "/admin/quotes",
      "work-orders": useMockup
        ? `${basePath}?section=work-orders`
        : "/admin/work-orders",
      appointments: useMockup
        ? `${basePath}?section=appointments`
        : "/admin/appointments",
      pos: useMockup ? `${basePath}?section=pos` : "/admin/pos",
      analytics: useMockup
        ? `${basePath}?section=analytics`
        : "/admin/analytics",
      system: useMockup ? `${basePath}?section=system` : "/admin/system",
    };

    const requiredRoute = sectionToRoute[currentStepData.section];
    if (!requiredRoute) return;

    // Para páginas mockup, comparar también los query params
    if (useMockup) {
      // Leer query params del URL actual
      const currentSection =
        typeof window !== "undefined"
          ? new URLSearchParams(window.location.search).get("section")
          : null;
      const requiredSection = currentStepData.section;

      // Si estamos en la ruta base pero con una sección diferente, navegar
      if (pathname === basePath) {
        if (currentSection !== requiredSection) {
          setIsNavigating(true);
          router.push(requiredRoute);
          setTimeout(() => setIsNavigating(false), 50);
          return;
        }
      } else {
        // Si no estamos en la ruta base, navegar a ella
        setIsNavigating(true);
        router.push(requiredRoute);
        setTimeout(() => setIsNavigating(false), 50);
        return;
      }
    } else {
      // Para páginas reales, comparar solo el pathname
      const requiredPath = requiredRoute.split("?")[0];
      if (pathname !== requiredPath) {
        setIsNavigating(true);
        router.push(requiredRoute);
        setTimeout(() => setIsNavigating(false), 100);
        return;
      }
    }
  }, [currentStep, isActive, pathname, mounted, router, isNavigating]);

  // Función para buscar el elemento con múltiples intentos - optimizada
  const findElement = useCallback(
    (
      selector: string,
      maxAttempts = 8,
      delay = 200,
    ): Promise<DOMRect | null> => {
      return new Promise((resolve) => {
        let attempts = 0;
        const warned = false; // Solo loguear una vez

        const tryFind = () => {
          attempts++;
          const element = document.querySelector(selector);

          if (element) {
            const rect = element.getBoundingClientRect();
            // Verificar que el elemento sea visible
            if (rect.width > 0 && rect.height > 0) {
              resolve(rect);
              return;
            }
          }

          if (attempts < maxAttempts) {
            setTimeout(tryFind, delay);
          } else {
            // No loguear - el tour funcionará sin el elemento (mostrando la tarjeta centrada)
            resolve(null);
          }
        };

        tryFind();
      });
    },
    [],
  );

  // Actualizar bounds del elemento cuando cambia el paso o la ruta
  useEffect(() => {
    if (!isActive || !mounted || isNavigating) {
      setElementBounds(null);
      return;
    }

    const currentStepData = TOUR_STEPS[currentStep];
    if (!currentStepData) {
      setElementBounds(null);
      return;
    }

    // Buscar el elemento con múltiples intentos - optimizado para páginas mockup
    const findElementAsync = async () => {
      // Reducir delay para páginas mockup (carga más rápida)
      const delay = TOUR_CONFIG.useMockupPages ? 100 : 300;
      await new Promise((resolve) => setTimeout(resolve, delay));

      // Reducir intentos para páginas mockup (elementos siempre presentes)
      const maxAttempts = TOUR_CONFIG.useMockupPages ? 3 : 8;
      const attemptDelay = TOUR_CONFIG.useMockupPages ? 50 : 200;

      const bounds = await findElement(
        currentStepData.selector,
        maxAttempts,
        attemptDelay,
      );
      setElementBounds(bounds);
    };

    findElementAsync();
  }, [currentStep, isActive, pathname, mounted, isNavigating, findElement]);

  // Si no hay datos del paso, completar el tour automáticamente en un efecto
  // DEBE estar antes de cualquier return condicional
  const currentStepData = TOUR_STEPS[currentStep];
  useEffect(() => {
    if (isActive && !currentStepData && !hasCompletedInvalidStep) {
      setHasCompletedInvalidStep(true);
      completeTour();
    }
  }, [isActive, currentStepData, completeTour, hasCompletedInvalidStep]);

  // Handlers - deben estar antes de cualquier return para cumplir con las reglas de hooks
  const handleSkip = useCallback(() => {
    // Deshabilitar inmediatamente el tour localmente
    setForceDisabled(true);
    // Llamar a skipTour para actualizar el servidor
    skipTour();
  }, [skipTour]);

  const handleNext = useCallback(() => {
    if (currentStep < totalSteps - 1) {
      completeStep(currentStep);
    } else {
      completeTour();
    }
  }, [currentStep, totalSteps, completeStep, completeTour]);

  const handlePrevious = useCallback(() => {
    if (currentStep > 0 && goToStep) {
      // Retroceder al paso anterior usando goToStep
      goToStep(currentStep - 1);
    }
  }, [currentStep, goToStep]);

  // Si el tour está desactivado por config, no está activo, fue forzado a deshabilitarse, o es usuario root/dev, solo renderizar children
  if (
    !TOUR_CONFIG.enabled ||
    !isActive ||
    !mounted ||
    forceDisabled ||
    isRoot
  ) {
    return <>{children}</>;
  }

  if (!currentStepData) {
    return <>{children}</>;
  }

  return (
    <>
      {children}
      {TOUR_CONFIG.showProgress && (
        <TourProgress
          currentStep={currentStep}
          totalSteps={totalSteps}
          onSkip={handleSkip}
        />
      )}
      {/* Mostrar overlay y tarjeta incluso si no se encuentra el elemento */}
      <TourOverlay isActive={isActive} selector={currentStepData.selector}>
        <TourCard
          currentStep={currentStep}
          elementBounds={elementBounds}
          position={currentStepData.position}
          step={currentStepData}
          totalSteps={totalSteps}
          onComplete={completeTour}
          onNext={handleNext}
          onPrevious={handlePrevious}
          onSkip={handleSkip}
        />
      </TourOverlay>
    </>
  );
}

