"use client";

import React, { useEffect } from "react";

import { appLogger } from '@/lib/logger';
import { useTelemetry } from "@/lib/telemetry/hooks/use-telemetry";

interface TelemetryProviderProps {
  children: React.ReactNode;
  userId?: string;
  organizationId?: string;
  appName?: string;
}

export function TelemetryProvider({
  children,
  userId,
  organizationId,
  appName = "Opttius",
}: TelemetryProviderProps) {
  const { trackFeatureUsage, telemetryCollector } =
    useTelemetry("telemetry-provider");

  useEffect(() => {
    // Check if telemetry is enabled globally using the public endpoint
    fetch("/api/telemetry/config")
      .then((res) => res.json())
      .then((data) => {
        if (data.enabled !== undefined) {
          telemetryCollector.setEnabled(data.enabled);
        }
      })
      .catch((err) => {
        appLogger.warn("Could not fetch global telemetry status");
      });

    // Track app initialization
    if (typeof window !== "undefined") {
      trackFeatureUsage("app_initialized", {
        userId,
        organizationId,
        appName,
        timestamp: new Date().toISOString(),
      });
    }

    // Track initial page view
    if (typeof window !== "undefined") {
      trackFeatureUsage("page_view", {
        pageUrl: window.location.href,
        pageTitle: document.title,
        timestamp: new Date().toISOString(),
      });
    }

    // Simple page visibility tracking
    const handleVisibilityChange = () => {
      if (document.hidden) {
        trackFeatureUsage("page_hidden", {
          timestamp: new Date().toISOString(),
        });
      } else {
        trackFeatureUsage("page_visible", {
          timestamp: new Date().toISOString(),
        });
      }
    };

    document.addEventListener("visibilitychange", handleVisibilityChange);

    return () => {
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, [trackFeatureUsage, userId, organizationId, appName]);

  return <>{children}</>;
}

"use client";

import {
  ThemeProvider as NextThemesProvider,
  useTheme as useNextTheme,
} from "next-themes";
import { type ThemeProviderProps } from "next-themes/dist/types";
import * as React from "react";

import { getTheme, ThemeId, themes } from "@/config/themes";
import { appLogger } from '@/lib/logger';

export function ThemeProvider({ children, ...props }: ThemeProviderProps) {
  return (
    <NextThemesProvider
      {...props}
      attribute="data-theme"
      defaultTheme="light"
      disableTransitionOnChange={false}
      enableSystem={false}
      storageKey="theme"
      themes={themes.map((t) => t.id)}
    >
      <ThemeClassManager>{children}</ThemeClassManager>
    </NextThemesProvider>
  );
}

// Component to manage theme class application
function ThemeClassManager({ children }: { children: React.ReactNode }) {
  const { theme, setTheme } = useNextTheme();
  const [mounted, setMounted] = React.useState(false);

  React.useEffect(() => {
    setMounted(true);
  }, []);

  React.useEffect(() => {
    if (!mounted || !theme) return;

    const root = document.documentElement;
    const validThemes: ThemeId[] = ["light", "dark", "blue", "green", "red"];

    // Remove all theme classes and dark class
    validThemes.forEach((t) => {
      root.classList.remove(`theme-${t}`);
    });
    root.classList.remove("dark");

    // Also remove data-theme attribute that next-themes might set
    root.removeAttribute("data-theme");

    // Apply current theme class - CSS variables are already defined in globals.css
    // We use "theme-{name}" format for our CSS selectors
    if (theme === "dark") {
      root.classList.add("dark", "theme-dark");
    } else if (theme === "light") {
      root.classList.add("theme-light");
    } else if (theme === "blue") {
      root.classList.add("theme-blue");
    } else if (theme === "green") {
      root.classList.add("theme-green");
    } else if (theme === "red") {
      root.classList.add("theme-red");
    }

    // Force a reflow to ensure styles are applied
    void root.offsetHeight;

    // Debug logging (only in development)
    if (process.env.NODE_ENV === "development") {
      appLogger.info("🎨 Theme applied:", theme);
      appLogger.info("🎨 Classes on <html>:", root.className);
    }
  }, [theme, mounted]);

  // Prevent flash of unstyled content
  if (!mounted) {
    return <>{children}</>;
  }

  return <>{children}</>;
}

// Custom hook to use theme with our custom theme IDs
export function useTheme() {
  const { theme, setTheme, themes: availableThemes } = useNextTheme();
  const [mounted, setMounted] = React.useState(false);

  React.useEffect(() => {
    setMounted(true);
  }, []);

  const currentTheme = React.useMemo(() => {
    if (!theme) return getTheme("light");
    return getTheme(theme as ThemeId);
  }, [theme]);

  return {
    theme: theme as ThemeId | undefined,
    setTheme: (newTheme: ThemeId) => setTheme(newTheme),
    currentTheme,
    themes: availableThemes as ThemeId[],
    mounted,
  };
}

