  isEditing?: boolean;
  size?: "sm" | "md" | "lg";
  className?: string;
}

export default function AvatarUpload({
  currentAvatarUrl,
  onUploadSuccess,
  onUploadError,
  isEditing = false,
  size = "md",
  className = "",
}: AvatarUploadProps) {
  const [isDragOver, setIsDragOver] = useState(false);
  const [preview, setPreview] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const { uploadState, uploadAvatar, resetUploadState } = useFileUpload();

  // Size configurations
  const sizeConfig = {
    sm: { container: "w-16 h-16", button: "h-6 w-6 p-0", icon: "h-3 w-3" },
    md: { container: "w-24 h-24", button: "h-8 w-8 p-0", icon: "h-4 w-4" },
    lg: { container: "w-32 h-32", button: "h-10 w-10 p-0", icon: "h-5 w-5" },
  };

  const config = sizeConfig[size];

  const handleFileSelect = useCallback(
    async (file: File) => {
      // Create preview
      const previewUrl = URL.createObjectURL(file);
      setPreview(previewUrl);

      try {
        // Upload to Supabase
        const uploadedUrl = await uploadAvatar(file);

        if (uploadedUrl) {
          await onUploadSuccess(uploadedUrl);
          setPreview(null);
          URL.revokeObjectURL(previewUrl); // Clean up
        } else {
          setPreview(null);
          URL.revokeObjectURL(previewUrl);
          onUploadError?.("Error al subir la imagen");
        }
      } catch (error) {
        setPreview(null);
        URL.revokeObjectURL(previewUrl);
        const errorMessage =
          error instanceof Error ? error.message : "Error desconocido";
        onUploadError?.(errorMessage);
      }
    },
    [uploadAvatar, onUploadSuccess, onUploadError],
  );

  const handleDrop = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault();
      setIsDragOver(false);

      const file = e.dataTransfer.files[0];
      if (file && file.type.startsWith("image/")) {
        handleFileSelect(file);
      }
    },
    [handleFileSelect],
  );

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragOver(true);
  }, []);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragOver(false);
  }, []);

  const handleInputChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
        handleFileSelect(file);
      }
    },
    [handleFileSelect],
  );

  const triggerFileInput = () => {
    fileInputRef.current?.click();
  };

  const currentImage = preview || currentAvatarUrl;
  const isUploading = uploadState.status === "uploading";
  const hasError = uploadState.status === "error";
  const isSuccess = uploadState.status === "success";

  return (
    <div
      className={`relative flex flex-col items-center w-full max-w-[180px] sm:max-w-[200px] ${className}`}
    >
      {/* Main Avatar Container - clickable/droppable when editing */}
      <div
        className={`
          ${config.container} rounded-full bg-epoch-accent/20 flex items-center justify-center mx-auto relative overflow-hidden shrink-0
          ${isEditing ? "cursor-pointer border-2 border-dashed ring-2 ring-transparent" : ""}
          ${isDragOver ? "border-epoch-accent bg-epoch-accent/10 ring-epoch-accent/30" : "border-transparent"}
          ${hasError ? "border-red-500" : ""}
          ${isSuccess ? "border-admin-success" : ""}
        `}
        onClick={isEditing ? triggerFileInput : undefined}
        onDragLeave={isEditing ? handleDragLeave : undefined}
        onDragOver={isEditing ? handleDragOver : undefined}
        onDrop={isEditing ? handleDrop : undefined}
      >
        {/* Background overlay during upload */}
        {isUploading && (
          <div className="absolute inset-0 bg-black/50 flex items-center justify-center z-10">
            <Loader2 className="h-6 w-6 text-white animate-spin" />
          </div>
        )}

        {/* Success overlay */}
        {isSuccess && (
          <div className="absolute inset-0 bg-admin-success/80 flex items-center justify-center z-10 animate-pulse">
            <Check className="h-6 w-6 text-white" />
          </div>
        )}

        {/* Avatar Image or Placeholder */}
        {currentImage ? (
          <img
            alt="Avatar"
            className="w-full h-full rounded-full object-cover"
            src={currentImage}
          />
        ) : (
          <User
            className={`${size === "sm" ? "h-8 w-8" : size === "md" ? "h-12 w-12" : "h-16 w-16"} text-epoch-primary`}
          />
        )}

        {/* Upload hint for drag and drop */}
        {isEditing && isDragOver && (
          <div className="absolute inset-0 bg-epoch-accent/20 flex items-center justify-center z-[5]">
            <Upload className="h-6 w-6 text-epoch-primary" />
          </div>
        )}
      </div>

      {/* Upload Button - always visible when editing, below avatar */}
      {isEditing && (
        <Button
          className="mt-3 w-full max-w-[140px] sm:max-w-[160px] h-9 sm:h-10 rounded-xl bg-epoch-accent hover:bg-epoch-accent/90 text-[#1A2B23] font-semibold text-xs sm:text-sm disabled:opacity-50 shrink-0"
          disabled={isUploading}
          size="sm"
          type="button"
          variant="secondary"
          onClick={(e) => {
            e.stopPropagation();
            triggerFileInput();
          }}
        >
          {isUploading ? (
            <Loader2
              className={`${config.icon} animate-spin mr-2 shrink-0 text-[#1A2B23]`}
            />
          ) : (
            <Camera className={`${config.icon} mr-2 shrink-0 text-[#1A2B23]`} />
          )}
          <span className="truncate">
            {currentImage ? "Cambiar foto" : "Agregar foto"}
          </span>
        </Button>
      )}

      {/* Hidden File Input */}
      <Input
        accept="image/jpeg,image/png,image/gif,image/webp"
        className="hidden"
        ref={fileInputRef}
        type="file"
        onChange={handleInputChange}
      />

      {/* Upload Instructions - always visible when editing */}
      {isEditing && !isUploading && !hasError && (
        <div className="text-center mt-2 w-full px-1">
          <p className="text-[11px] sm:text-xs text-slate-600 dark:text-slate-400 font-medium">
            Haz clic o arrastra una imagen
          </p>
          <p className="text-[10px] sm:text-[11px] text-slate-500 dark:text-slate-500/80 mt-0.5">
            JPG, PNG, GIF, WebP (máx. 5MB)
          </p>
        </div>
      )}

      {/* Upload Progress */}
      {isUploading && (
        <div className="mt-2 w-full">
          <Progress className="h-2" value={uploadState.progress} />
          <p className="text-xs text-muted-foreground text-center mt-1">
            Subiendo... {uploadState.progress}%
          </p>
        </div>
      )}

      {/* Error Display */}
      {hasError && uploadState.error && (
        <Alert className="mt-2 w-full border-red-500 bg-red-50 dark:bg-red-950/30">
          <AlertDescription className="text-red-600 dark:text-red-400 text-sm">
            {uploadState.error}
          </AlertDescription>
        </Alert>
      )}
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

type BlurTextProps = {
  text?: string;
  delay?: number;
  className?: string;
  animateBy?: "words" | "letters";
  direction?: "top" | "bottom";
  threshold?: number;
  rootMargin?: string;
  onAnimationComplete?: () => void;
  stepDuration?: number;
  as?: keyof JSX.IntrinsicElements;
  style?: React.CSSProperties;
};

const BlurText: React.FC<BlurTextProps> = ({
  text = "",
  delay = 200,
  className = "",
  animateBy = "words",
  direction = "top",
  threshold = 0.1,
  rootMargin = "0px",
  onAnimationComplete,
  stepDuration = 0.35,
  as = "p",
  style,
}) => {
  const elements = animateBy === "words" ? text.split(" ") : text.split("");
  const ref = useRef<HTMLElement>(null);
  const animateRef = useRef(false);

  useEffect(() => {
    if (!ref.current) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          animateRef.current = true;
          ref.current?.classList.add("blur-text--animate");
          observer.unobserve(ref.current as Element);
        }
      },
      { threshold, rootMargin },
    );
    observer.observe(ref.current);
    return () => observer.disconnect();
  }, [threshold, rootMargin]);

  const tagName = as as keyof JSX.IntrinsicElements;
  const Component = tagName;

  const totalDuration = stepDuration * 2;

  return (
    <>
      <style>{`
        @keyframes blurReveal-top {
          0%   { filter: blur(10px); opacity: 0; transform: translateY(-50px); }
          50%  { filter: blur(5px);  opacity: 0.5; transform: translateY(5px); }
          100% { filter: blur(0px);  opacity: 1; transform: translateY(0); }
        }
        @keyframes blurReveal-bottom {
          0%   { filter: blur(10px); opacity: 0; transform: translateY(50px); }
          50%  { filter: blur(5px);  opacity: 0.5; transform: translateY(-5px); }
          100% { filter: blur(0px);  opacity: 1; transform: translateY(0); }
        }
        .blur-text--animate > span {
          animation: blurReveal-${direction} ${totalDuration}s linear both;
        }
      `}</style>
      <Component
        className={`blur-text ${className} flex flex-wrap justify-center text-center`}
        ref={ref}
        style={style}
      >
        {elements.map((segment, index) => (
          <span
            key={index}
            style={{
              display: "inline-block",
              willChange: "transform, filter, opacity",
              fontFamily: style?.fontFamily || "inherit",
              fontWeight: style?.fontWeight || "inherit",
              fontStyle: style?.fontStyle || "inherit",
              fontSize: "inherit",
              lineHeight: "inherit",
              letterSpacing: "inherit",
              animationDelay: `${(index * delay) / 1000}s`,
            }}
            onAnimationEnd={
              index === elements.length - 1 ? onAnimationComplete : undefined
            }
          >
            {segment === " " ? "\u00A0" : segment}
            {animateBy === "words" && index < elements.length - 1 && "\u00A0"}
          </span>
        ))}
      </Component>
    </>
  );
};

export default BlurText;

/**
 * Form Field Component
 *
 * Componente reutilizable para campos de formulario con label, error y descripción.
 * Proporciona una interfaz consistente para todos los campos de formulario.
 *
 * @module components/ui/FormField
 */

import * as React from "react";
import { FieldError } from "react-hook-form";

import { Label } from "@/components/ui/label";
import { cn } from "@/lib/utils";

/**
 * Props del componente FormField
 */
export interface FormFieldProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Etiqueta del campo */
  label?: string;
  /** Mensaje de error - puede ser string o FieldError */
  error?: string | FieldError | null | undefined;
  /** Descripción del campo */
  description?: string;
  /** Si el campo es requerido */
  required?: boolean;
  /** Si el campo está deshabilitado */
  disabled?: boolean;
  /** Contenido del campo (input, select, etc.) */
  children: React.ReactNode;
  /** Posición del label */
  labelPosition?: "top" | "left";
  /** Clases adicionales para el contenedor */
  containerClassName?: string;
  /** Clases adicionales para el label */
  labelClassName?: string;
  /** Clases adicionales para el error */
  errorClassName?: string;
}

/**
 * Función para obtener el mensaje de error de un FieldError o string
 */
function getErrorMessage(
  error: string | FieldError | null | undefined,
): string | undefined {
  if (!error) return undefined;
  if (typeof error === "string") return error;
  if (error && typeof error === "object" && "message" in error) {
    return error.message;
  }
  return undefined;
}

/**
 * Componente FormField
 *
 * @example
 * <FormField label="Nombre" error={errors.name?.message} required>
 *   <Input {...register("name")} />
 * </FormField>
 *
 * @example
 * <FormField
 *   label="Email"
 *   error={errors.email?.message}
 *   description="Usaremos este email para contactarte"
 *   required
 * >
 *   <Input type="email" {...register("email")} />
 * </FormField>
 */
// Exportar componentes
export default function FormField({
  label,
  error,
  description,
  required = false,
  disabled = false,
  children,
  labelPosition = "top",
  containerClassName,
  labelClassName,
  errorClassName,
  className,
  ...props
}: FormFieldProps) {
  const labelId = React.useId();
  const errorId = React.useId();
  const descriptionId = React.useId();

  const errorMessage = getErrorMessage(error);

  return (
    <div
      className={cn(
        "space-y-2",
        labelPosition === "left" && "flex items-start gap-4 space-y-0",
        containerClassName,
      )}
      {...props}
    >
      {label && (
        <Label
          className={cn(
            "text-sm font-medium",
            labelPosition === "left" && "min-w-[120px] pt-2",
            disabled && "opacity-50",
            labelClassName,
          )}
          htmlFor={labelId}
        >
          {label}
          {required && <span className="text-destructive ml-1">*</span>}
        </Label>
      )}

      <div className={cn("flex-1", className)}>
        {React.cloneElement(children as React.ReactElement<unknown>, {
          id: labelId,
          "aria-describedby": cn(
            description && descriptionId,
            errorMessage && errorId,
          ),
          "aria-invalid": !!errorMessage,
          disabled,
        })}

        {description && !errorMessage && (
          <p className="text-xs text-muted-foreground mt-1" id={descriptionId}>
            {description}
          </p>
        )}

        {errorMessage && (
          <p
            className={cn(
              "text-xs text-destructive mt-1 flex items-center gap-1",
              errorClassName,
            )}
            id={errorId}
            role="alert"
          >
            <svg
              fill="none"
              height="12"
              stroke="currentColor"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth="2"
              viewBox="0 0 24 24"
              width="12"
              xmlns="http://www.w3.org/2000/svg"
            >
              <circle cx="12" cy="12" r="10" />
              <line x1="12" x2="12" y1="8" y2="12" />
              <line x1="12" x2="12.01" y1="16" y2="16" />
            </svg>
            {errorMessage}
          </p>
        )}
      </div>
    </div>
  );
}

