      )}
    </div>
  );
}

"use client";

import {
  AlignCenter,
  AlignLeft,
  AlignRight,
  Bold,
  Italic,
  Type,
  Underline,
} from "lucide-react";
import { useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";

interface RichTextEditorProps {
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  rows?: number;
  className?: string;
}

export default function RichTextEditor({
  value,
  onChange,
  placeholder = "",
  rows = 4,
  className = "",
}: RichTextEditorProps) {
  const [isRichMode, setIsRichMode] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const applyFormat = (format: string) => {
    const textarea = textareaRef.current;
    if (!textarea) return;

    const start = textarea.selectionStart;
    const end = textarea.selectionEnd;
    const selectedText = value.substring(start, end);

    if (!selectedText) {
      // If no text is selected, just insert the format tags
      const newValue =
        value.substring(0, start) + format + format + value.substring(end);
      onChange(newValue);

      // Set cursor position between the tags
      setTimeout(() => {
        textarea.focus();
        textarea.setSelectionRange(
          start + format.length,
          start + format.length,
        );
      }, 0);
    } else {
      // If text is selected, wrap it with the format tags
      const newValue =
        value.substring(0, start) +
        format +
        selectedText +
        format +
        value.substring(end);
      onChange(newValue);

      // Set cursor position after the formatted text
      setTimeout(() => {
        textarea.focus();
        textarea.setSelectionRange(start + format.length, end + format.length);
      }, 0);
    }
  };

  const formatButtons = [
    { icon: Bold, format: "**", tooltip: "Negrita" },
    { icon: Italic, format: "*", tooltip: "Cursiva" },
    { icon: Underline, format: "__", tooltip: "Subrayado" },
  ];

  const alignmentButtons = [
    { icon: AlignLeft, format: "left", tooltip: "Alineación izquierda" },
    { icon: AlignCenter, format: "center", tooltip: "Centrado" },
    { icon: AlignRight, format: "right", tooltip: "Alineación derecha" },
  ];

  const applyAlignment = (alignment: string) => {
    const textarea = textareaRef.current;
    if (!textarea) return;

    const start = textarea.selectionStart;
    const end = textarea.selectionEnd;
    const selectedText = value.substring(start, end);

    if (selectedText) {
      const newValue =
        value.substring(0, start) +
        `<div style="text-align: ${alignment}">${selectedText}</div>` +
        value.substring(end);
      onChange(newValue);
    }
  };

  return (
    <div className={`space-y-2 ${className}`}>
      {/* Toolbar */}
      <div className="flex items-center gap-1 p-2 rounded-md">
        <Button
          className="mr-2"
          size="sm"
          type="button"
          variant={isRichMode ? "default" : "outline"}
          onClick={() => setIsRichMode(!isRichMode)}
        >
          <Type className="h-4 w-4 mr-1" />
          {isRichMode ? "Modo Simple" : "Formato"}
        </Button>

        {isRichMode && (
          <>
            <div className="flex items-center gap-1 border-r pr-2 mr-2">
              {formatButtons.map((button, index) => (
                <Button
                  key={index}
                  size="sm"
                  title={button.tooltip}
                  type="button"
                  variant="outline"
                  onClick={() => applyFormat(button.format)}
                >
                  <button.icon className="h-4 w-4" />
                </Button>
              ))}
            </div>

            <div className="flex items-center gap-1">
              {alignmentButtons.map((button, index) => (
                <Button
                  key={index}
                  size="sm"
                  title={button.tooltip}
                  type="button"
                  variant="outline"
                  onClick={() => applyAlignment(button.format)}
                >
                  <button.icon className="h-4 w-4" />
                </Button>
              ))}
            </div>
          </>
        )}
      </div>

      {/* Text Area */}
      <Textarea
        className="min-h-[100px]"
        placeholder={placeholder}
        ref={textareaRef}
        rows={rows}
        value={value}
        onChange={(e) => onChange(e.target.value)}
      />

      {isRichMode && (
        <div className="text-xs text-gray-500">
          <p>
            <strong>Formato:</strong> **negrita**, *cursiva*, __subrayado__
          </p>
          <p>
            <strong>HTML:</strong> También puedes usar etiquetas HTML básicas
            como &lt;strong&gt;, &lt;em&gt;, &lt;u&gt;
          </p>
        </div>
      )}
    </div>
  );
}

"use client";

import {
  ArrowRight,
  BookOpen,
  Calendar,
  Clock,
  Heart,
  Share2,
  User,
} from "lucide-react";
import Image from "next/image";
import Link from "next/link";
import { useState } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { appLogger } from '@/lib/logger';

interface BlogCardProps {
  id: string;
  title: string;
  excerpt: string;
  slug: string;
  publishedAt: string;
  mainImage?: {
    asset: {
      url: string;
    };
    alt?: string;
  };
  author: {
    name: string;
    image?: {
      asset: {
        url: string;
      };
    };
  };
  categories?: Array<{
    title: string;
    color?: string;
  }>;
  estimatedReadingTime?: number;
  featured?: boolean;
  className?: string;
  onToggleFavorite?: (postId: string) => void;
  onShare?: (postId: string) => void;
  isFavorite?: boolean;
}

export default function BlogCard({
  id,
  title,
  excerpt,
  slug,
  publishedAt,
  mainImage,
  author,
  categories = [],
  estimatedReadingTime = 5,
  featured = false,
  className = "",
  onToggleFavorite,
  onShare,
  isFavorite = false,
}: BlogCardProps) {
  const [isHovered, setIsHovered] = useState(false);

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString("es-AR", {
      year: "numeric",
      month: "long",
      day: "numeric",
    });
  };

  const handleToggleFavorite = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    onToggleFavorite?.(id);
  };

  const handleShare = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    onShare?.(id);
  };

  const getImageUrl = () => {
    if (mainImage?.asset?.url) {
      return mainImage.asset.url;
    }
    // Using a placeholder from a reliable service
    return "https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=800&h=600&fit=crop&crop=center";
  };

  const hasValidImage = () => {
    return mainImage?.asset?.url && mainImage.asset.url.trim() !== "";
  };

  const getAuthorImageUrl = () => {
    if (author?.image?.asset?.url) {
      return author.image.asset.url;
    }
    // Using a placeholder for author
    return "https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=100&h=100&fit=crop&crop=face";
  };

  const hasValidAuthorImage = () => {
    return author?.image?.asset?.url && author.image.asset.url.trim() !== "";
  };

  return (
    <Card
      className={`group relative overflow-hidden transition-all duration-300 hover:shadow-lg hover:-translate-y-1 ${className}`}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      <Link href={`/blog/${slug}`}>
        <div className="relative">
          {/* Blog Image */}
          <div className="relative aspect-[16/10] overflow-hidden bg-verde-suave/10">
            {hasValidImage() ? (
              <Image
                fill
                alt={mainImage?.alt || title}
                className="object-cover transition-transform duration-300 group-hover:scale-105"
                src={getImageUrl()}
                onError={(e) => {
                  appLogger.error(
                    "Error loading blog image:",
                    mainImage?.asset?.url,
                  );
                }}
              />
            ) : (
              <div className="w-full h-full bg-gradient-to-br from-verde-suave/20 to-turquesa-claro/20 flex items-center justify-center">
                <div className="text-center text-tierra-media/60">
                  <BookOpen className="w-12 h-12 mx-auto mb-2 opacity-50" />
                  <span className="text-sm font-medium">Sin imagen</span>
                </div>
              </div>
            )}

            {/* Featured Badge */}
            {featured && (
              <div className="absolute top-4 left-4">
                <Badge className="bg-dorado text-azul-profundo font-semibold">
                  <BookOpen className="h-3 w-3 mr-1" />
                  Destacado
                </Badge>
              </div>
            )}

            {/* Categories */}
            {categories && categories.length > 0 && (
              <div className="absolute top-4 right-4 flex flex-wrap gap-1">
                {categories.slice(0, 2).map((category, index) => (
                  <Badge
                    className="bg-white/90 text-azul-profundo text-xs"
                    key={index}
                    style={{
                      backgroundColor: category.color
                        ? `${category.color}20`
                        : undefined,
                      color: category.color || undefined,
                    }}
                    variant="secondary"
                  >
                    {category.title}
                  </Badge>
                ))}
              </div>
            )}

            {/* Quick Actions */}
            <div
              className={`absolute bottom-4 right-4 flex gap-2 transition-opacity duration-300 ${
                isHovered ? "opacity-100" : "opacity-0"
              }`}
            >
              {onToggleFavorite && (
                <Button
                  className="h-8 w-8 p-0 bg-white/90 hover:bg-white"
                  size="sm"
                  variant="secondary"
                  onClick={handleToggleFavorite}
                >
                  <Heart
                    className={`h-4 w-4 ${
                      isFavorite
                        ? "fill-coral-suave text-coral-suave"
                        : "text-tierra-media"
                    }`}
                  />
                </Button>
              )}
              {onShare && (
                <Button
                  className="h-8 w-8 p-0 bg-white/90 hover:bg-white"
                  size="sm"
                  variant="secondary"
                  onClick={handleShare}
                >
                  <Share2 className="h-4 w-4 text-tierra-media" />
                </Button>
              )}
            </div>

            {/* Reading Time */}
            <div className="absolute bottom-4 left-4">
              <div className="bg-white/90 backdrop-blur-sm rounded-full px-3 py-1 flex items-center gap-1">
                <Clock className="h-3 w-3 text-tierra-media" />
                <span className="text-xs text-tierra-media font-medium">
                  {estimatedReadingTime || 5} min
                </span>
              </div>
            </div>
          </div>

          {/* Blog Content */}
          <CardContent className="p-6">
            {/* Publication Date */}
            <div className="flex items-center gap-2 text-sm text-tierra-media mb-3">
              <Calendar className="h-4 w-4" />
              <span>{formatDate(publishedAt)}</span>
            </div>

            {/* Title */}
            <h3 className="text-xl font-semibold text-azul-profundo line-clamp-2 mb-3 hover:text-azul-profundo/80 transition-colors">
              {title}
            </h3>

            {/* Excerpt */}
            <p className="text-tierra-media line-clamp-3 mb-4 leading-relaxed">
              {excerpt}
            </p>

            {/* Author */}
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="relative h-8 w-8 rounded-full overflow-hidden bg-verde-suave/20">
                  {hasValidAuthorImage() ? (
                    <Image
                      fill
                      alt={author?.name || "Author"}
                      className="object-cover"
                      src={getAuthorImageUrl()}
                      onError={(e) => {
                        appLogger.error(
                          "Error loading author image:",
                          author?.image?.asset?.url,
                        );
                      }}
                    />
                  ) : (
                    <div className="w-full h-full bg-gradient-to-br from-azul-profundo/20 to-verde-suave/20 flex items-center justify-center">
                      <User className="w-4 h-4 text-tierra-media/60" />
                    </div>
                  )}
                </div>
                <div>
                  <div className="text-sm font-medium text-azul-profundo">
                    {author?.name || "Autor desconocido"}
                  </div>
                </div>
              </div>

              {/* Read More */}
              <div className="flex items-center gap-1 text-sm text-azul-profundo group-hover:text-dorado transition-colors">
                <span className="font-medium">Leer más</span>
                <ArrowRight className="h-4 w-4 transition-transform group-hover:translate-x-1" />
              </div>
            </div>
          </CardContent>
        </div>
      </Link>
    </Card>
  );
}

import { cva, type VariantProps } from "class-variance-authority";
import React from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

const contentSectionVariants = cva(
  "relative w-full transition-all duration-300",
  {
    variants: {
      variant: {
        default: "py-16 px-6",
        hero: "py-24 px-6 min-h-[60vh] flex items-center",
        compact: "py-12 px-6",
        full: "py-20 px-8",
        minimal: "py-8 px-4",
      },
      background: {
        transparent: "bg-transparent",
        white: "bg-white",
        cream: "bg-bg-cream",
        light: "bg-bg-light",
        primary: "bg-line-primary text-white",
        gradient:
          "bg-gradient-to-br from-line-primary to-line-secondary text-white",
        overlay: "relative bg-cover bg-center",
      },
      textAlign: {
        left: "text-left",
        center: "text-center",
        right: "text-right",
      },
      spacing: {
        tight: "space-y-4",
        normal: "space-y-6",
        relaxed: "space-y-8",
        loose: "space-y-12",
      },
    },
    defaultVariants: {
      variant: "default",
      background: "transparent",
      textAlign: "left",
      spacing: "normal",
    },
  },
);

const contentContainerVariants = cva("mx-auto max-w-7xl relative z-10", {
  variants: {
    width: {
      narrow: "max-w-3xl",
      normal: "max-w-7xl",
      wide: "max-w-8xl",
      full: "max-w-none",
    },
  },
  defaultVariants: {
    width: "normal",
  },
});

interface ContentSectionProps
  extends VariantProps<typeof contentSectionVariants> {
  children: React.ReactNode;
  className?: string;
  backgroundImage?: string;
  overlayOpacity?: number;
  width?: VariantProps<typeof contentContainerVariants>["width"];
  id?: string;
}

interface ContentHeaderProps {
  badge?: {
    text: string;
    variant?: "default" | "secondary" | "destructive" | "outline";
  };
  title: string;
  subtitle?: string;
  description?: string;
  className?: string;
}

interface ContentBodyProps {
  children: React.ReactNode;
  className?: string;
  columns?: 1 | 2 | 3;
}

interface ContentActionsProps {
  primaryAction?: {
    text: string;
    href?: string;
    onClick?: () => void;
    variant?: "brand" | "line-primary" | "outline";
  };
  secondaryAction?: {
    text: string;
    href?: string;
    onClick?: () => void;
    variant?: "ghost" | "outline" | "line-outline";
  };
  className?: string;
}

export function ContentSection({
  children,
  className,
  backgroundImage,
  overlayOpacity = 0.6,
  width,
  variant,
  background,
  textAlign,
  spacing,
  id,
  ...props
}: ContentSectionProps) {
  const sectionStyle = backgroundImage
    ? {
        backgroundImage: `url(${backgroundImage})`,
      }
    : {};

  return (
    <section
      className={cn(
        contentSectionVariants({ variant, background, textAlign, spacing }),
        className,
      )}
      id={id}
      style={sectionStyle}
      {...props}
    >
      {backgroundImage && background === "overlay" && (
        <div
          className="absolute inset-0 bg-line-primary"
          style={{ opacity: overlayOpacity }}
        />
      )}

      <div className={cn(contentContainerVariants({ width }), spacing)}>
        {children}
      </div>
    </section>
  );
}

