"use client";

import {
  ArrowRight,
  Award,
  CheckCircle,
  Heart,
  Leaf,
  Shield,
  Sparkles,
} from "lucide-react";
import { ReactNode } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";

interface FeatureHighlightProps {
  icon?: ReactNode;
  title: string;
  description: string;
  benefits?: string[];
  isNew?: boolean;
  isPremium?: boolean;
  category?: "natural" | "certified" | "handmade" | "premium";
  actionLabel?: string;
  onAction?: () => void;
  className?: string;
  variant?: "default" | "card" | "banner";
  size?: "sm" | "md" | "lg";
}

export default function FeatureHighlight({
  icon,
  title,
  description,
  benefits = [],
  isNew = false,
  isPremium = false,
  category,
  actionLabel,
  onAction,
  className = "",
  variant = "default",
  size = "md",
}: FeatureHighlightProps) {
  const getDefaultIcon = () => {
    if (icon) return icon;

    switch (category) {
      case "natural":
        return <Leaf className="h-8 w-8 text-verde-suave" />;
      case "certified":
        return <Shield className="h-8 w-8 text-azul-profundo" />;
      case "handmade":
        return <Heart className="h-8 w-8 text-coral-suave" />;
      case "premium":
        return <Award className="h-8 w-8 text-dorado" />;
      default:
        return <Sparkles className="h-8 w-8 text-dorado" />;
    }
  };

  const getCategoryBadge = () => {
    if (!category) return null;

    switch (category) {
      case "natural":
        return (
          <Badge
            className="bg-verde-suave text-white"
            style={{ color: "var(--admin-accent-secondary)" }}
          >
            <Leaf className="h-3 w-3 mr-1" />
            100% Natural
          </Badge>
        );
      case "certified":
        return (
          <Badge className="bg-azul-profundo text-white">
            <Shield className="h-3 w-3 mr-1" />
            Certificado
          </Badge>
        );
      case "handmade":
        return (
          <Badge className="bg-coral-suave text-white">
            <Heart className="h-3 w-3 mr-1" />
            Artesanal
          </Badge>
        );
      case "premium":
        return (
          <Badge className="bg-dorado text-azul-profundo">
            <Award className="h-3 w-3 mr-1" />
            Premium
          </Badge>
        );
    }
  };

  const getSizeClasses = () => {
    switch (size) {
      case "sm":
        return {
          container: "p-4",
          icon: "h-6 w-6",
          title: "text-lg",
          description: "text-sm",
          spacing: "space-y-2",
        };
      case "lg":
        return {
          container: "p-8",
          icon: "h-12 w-12",
          title: "text-2xl",
          description: "text-lg",
          spacing: "space-y-6",
        };
      default: // md
        return {
          container: "p-6",
          icon: "h-8 w-8",
          title: "text-xl",
          description: "text-base",
          spacing: "space-y-4",
        };
    }
  };

  const sizeClasses = getSizeClasses();

  if (variant === "banner") {
    return (
      <div
        className={`relative overflow-hidden rounded-lg bg-gradient-to-r from-verde-suave/20 via-turquesa-claro/20 to-dorado/20 border border-dorado/30 ${className}`}
      >
        <div className={`${sizeClasses.container} ${sizeClasses.spacing}`}>
          <div className="flex items-start justify-between">
            <div className="flex items-start gap-4">
              <div className="p-3 bg-white/80 rounded-full">
                {getDefaultIcon()}
              </div>

              <div className="flex-1">
                <div className="flex items-center gap-2 mb-2">
                  <h3
                    className={`font-bold text-azul-profundo ${sizeClasses.title}`}
                  >
                    {title}
                  </h3>
                  {isNew && (
                    <Badge className="bg-dorado text-azul-profundo">
                      Nuevo
                    </Badge>
                  )}
                  {isPremium && (
                    <Badge className="bg-azul-profundo text-white">
                      Premium
                    </Badge>
                  )}
                  {getCategoryBadge()}
                </div>

                <p
                  className={`text-tierra-media ${sizeClasses.description} mb-4`}
                >
                  {description}
                </p>

                {benefits.length > 0 && (
                  <ul className="space-y-2 mb-4">
                    {benefits.map((benefit, index) => (
                      <li
                        className="flex items-center gap-2 text-sm text-tierra-media"
                        key={index}
                      >
                        <CheckCircle className="h-4 w-4 text-verde-suave flex-shrink-0" />
                        <span>{benefit}</span>
                      </li>
                    ))}
                  </ul>
                )}
              </div>
            </div>

            {actionLabel && onAction && (
              <Button
                className="bg-dorado hover:bg-dorado/90 text-azul-profundo font-semibold"
                onClick={onAction}
              >
                {actionLabel}
                <ArrowRight className="h-4 w-4 ml-2" />
              </Button>
            )}
          </div>
        </div>
      </div>
    );
  }

  if (variant === "card") {
    return (
      <Card
        className={`group transition-all duration-300 hover:shadow-lg hover:-translate-y-1 ${className}`}
      >
        <CardContent
          className={`${sizeClasses.container} ${sizeClasses.spacing}`}
        >
          <div className="text-center">
            <div className="flex justify-center mb-4">
              <div className="p-4 bg-dorado/10 rounded-full group-hover:bg-dorado/20 transition-colors">
                {getDefaultIcon()}
              </div>
            </div>

            <div className="flex items-center justify-center gap-2 mb-3">
              <h3
                className={`font-bold text-azul-profundo ${sizeClasses.title}`}
              >
                {title}
              </h3>
              {isNew && (
                <Badge className="bg-dorado text-azul-profundo">Nuevo</Badge>
              )}
            </div>

            {getCategoryBadge() && (
              <div className="flex justify-center mb-3">
                {getCategoryBadge()}
              </div>
            )}

            <p className={`text-tierra-media ${sizeClasses.description} mb-4`}>
              {description}
            </p>

            {benefits.length > 0 && (
              <ul className="space-y-2 mb-6 text-left">
                {benefits.map((benefit, index) => (
                  <li
                    className="flex items-center gap-2 text-sm text-tierra-media"
                    key={index}
                  >
                    <CheckCircle className="h-4 w-4 text-verde-suave flex-shrink-0" />
                    <span>{benefit}</span>
                  </li>
                ))}
              </ul>
            )}

            {actionLabel && onAction && (
              <Button
                className="w-full bg-dorado hover:bg-dorado/90 text-azul-profundo font-semibold"
                onClick={onAction}
              >
                {actionLabel}
                <ArrowRight className="h-4 w-4 ml-2" />
              </Button>
            )}
          </div>
        </CardContent>
      </Card>
    );
  }

  // Default variant
  return (
    <div className={`${sizeClasses.spacing} ${className}`}>
      <div className="flex items-start gap-4">
        <div className="p-2 bg-dorado/10 rounded-lg">{getDefaultIcon()}</div>

        <div className="flex-1">
          <div className="flex items-center gap-2 mb-2">
            <h3
              className={`font-semibold text-azul-profundo ${sizeClasses.title}`}
            >
              {title}
            </h3>
            {isNew && (
              <Badge className="bg-dorado text-azul-profundo">Nuevo</Badge>
            )}
            {getCategoryBadge()}
          </div>

          <p className={`text-tierra-media ${sizeClasses.description} mb-3`}>
            {description}
          </p>

          {benefits.length > 0 && (
            <ul className="space-y-1 mb-3">
              {benefits.map((benefit, index) => (
                <li
                  className="flex items-center gap-2 text-sm text-tierra-media"
                  key={index}
                >
                  <div className="h-1.5 w-1.5 rounded-full bg-dorado" />
                  <span>{benefit}</span>
                </li>
              ))}
            </ul>
          )}

          {actionLabel && onAction && (
            <Button
              className="border-azul-profundo text-azul-profundo hover:bg-azul-profundo hover:text-white"
              size="sm"
              variant="outline"
              onClick={onAction}
            >
              {actionLabel}
              <ArrowRight className="h-4 w-4 ml-2" />
            </Button>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import { cva, type VariantProps } from "class-variance-authority";
import { AlertCircle, Check } from "lucide-react";
import React, { useState } from "react";

import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

const formContainerVariants = cva("w-full max-w-2xl mx-auto space-y-6", {
  variants: {
    variant: { default: "p-6 bg-white rounded-lg border", elegant: "p-8 bg-gradient-to-br from-white to-line-lightest/30 rounded-xl shadow-lg border border-line-primary/10", minimal: "p-4 bg-transparent", card: "p-6 bg-card rounded-lg shadow-soft border" },
    spacing: { compact: "space-y-4", normal: "space-y-6", relaxed: "space-y-8" },
  },
  defaultVariants: { variant: "default", spacing: "normal" },
});

interface FormContainerProps extends VariantProps<typeof formContainerVariants> {
  children: React.ReactNode; className?: string; title?: string; subtitle?: string; badge?: string;
}

interface FormFieldProps {
  label: string; name: string; type?: "text" | "email" | "tel" | "textarea" | "select";
  placeholder?: string; required?: boolean; error?: string; success?: string; helper?: string;
  icon?: React.ReactNode; options?: { value: string; label: string }[]; rows?: number; className?: string;
}

export function FormContainer({ children, className, title, subtitle, badge, variant, spacing }: FormContainerProps) {
  return (
    <div className={cn(formContainerVariants({ variant, spacing }), className)}>
      {(title || subtitle || badge) && <div className="mb-6 text-center">{badge && <Badge className="mb-3" variant="secondary">{badge}</Badge>}{title && <h2 className="text-2xl font-heading font-bold text-foreground mb-2">{title}</h2>}{subtitle && <p className="text-muted-foreground">{subtitle}</p>}</div>}
      {children}
    </div>
  );
}

export function FormField({ label, name, type = "text", placeholder, required, error, success, helper, icon, options, rows = 4, className }: FormFieldProps) {
  const [focused, setFocused] = useState(false);
  const fieldId = `field-${name}`;
  const hasError = !!error;
  const hasSuccess = !!success;

  const baseProps = {
    id: fieldId, name, placeholder, required,
    onFocus: () => setFocused(true), onBlur: () => setFocused(false),
    className: cn("transition-all duration-200", hasError && "border-red-500 focus:border-red-500 focus:ring-red-500/20", hasSuccess && "border-green-500 focus:border-green-500 focus:ring-green-500/20", !hasError && !hasSuccess && focused && "border-line-primary focus:ring-line-primary/20"),
  };

  return (
    <div className={cn("space-y-2", className)}>
      <label className={cn("block text-sm font-medium transition-colors duration-200", hasError ? "text-red-600" : hasSuccess ? "text-green-600" : "text-foreground", focused && !hasError && !hasSuccess && "text-line-primary")} htmlFor={fieldId}>{label}{required && <span className="text-red-500 ml-1">*</span>}</label>
      <div className="relative">
        {type === "textarea" ? (
          <textarea {...baseProps} className={cn("flex min-h-[80px] w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 resize-none", baseProps.className)} rows={rows} />
        ) : type === "select" && options ? (
          <select {...baseProps} className={cn("flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background file:border-0 file:bg-transparent file:text-sm file:font-medium placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50", baseProps.className)}><option value="">{placeholder}</option>{options.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}</select>
        ) : (
          <Input {...baseProps} leftIcon={icon} type={type} variant={hasError ? "error" : hasSuccess ? "success" : "default"} />
        )}
        {(hasError || hasSuccess) && <div className="absolute right-3 top-1/2 -translate-y-1/2">{hasError && <AlertCircle className="w-4 h-4 text-red-500" />}{hasSuccess && <Check className="w-4 h-4 text-green-500" />}</div>}
      </div>
      {(error || success || helper) && <div className="text-sm">{error && <p className="text-red-600 flex items-center gap-1"><AlertCircle className="w-3 h-3" />{error}</p>}{success && <p className="text-green-600 flex items-center gap-1"><Check className="w-3 h-3" />{success}</p>}{helper && !error && !success && <p className="text-muted-foreground">{helper}</p>}</div>}
    </div>
  );
}

export { ContactForm, NewsletterForm } from "./_components/ContactForm";

"use client";

import { ArrowRight, ChevronDown } from "lucide-react";
import Image from "next/image";
import Link from "next/link";
import { useEffect, useState } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

interface HeroSectionProps {
  title: string;
  subtitle?: string;
  description: string;
  backgroundImage: string;
  overlayOpacity?: number;
  textPosition?: "left" | "center" | "right";
  lineTheme?:
    | "alma-terra"
    | "ecos"
    | "jade-ritual"
    | "umbral"
    | "utopica"
    | "default";
  variant?: "default" | "elegant" | "artisanal" | "minimal";
  primaryAction?: {
    text: string;
    href: string;
  };
  secondaryAction?: {
    text: string;
    href: string;
  };
  badges?: Array<{
    text: string;
    icon?: React.ReactNode;
    variant?: "default" | "natural" | "premium" | "new";
  }>;
  height?: "sm" | "md" | "lg" | "xl" | "screen";
  showScrollIndicator?: boolean;
  className?: string;
}

const heightClasses = {
  sm: "min-h-[400px]",
  md: "min-h-[500px]",
  lg: "min-h-[600px]",
  xl: "min-h-[700px]",
  screen: "min-h-screen",
};

const textPositionClasses = {
  left: "text-left items-start",
  center: "text-center items-center",
  right: "text-right items-end",
};

const lineThemeClasses = {
  "alma-terra": {
    primary: "bg-alma-primary hover:bg-alma-primary/90",
    accent: "text-alma-secondary",
    overlay: "bg-gradient-to-r from-alma-primary/80 to-alma-secondary/60",
  },
  ecos: {
    primary: "bg-ecos-primary hover:bg-ecos-primary/90",
    accent: "text-ecos-secondary",
    overlay: "bg-gradient-to-r from-ecos-primary/80 to-ecos-secondary/60",
  },
  "jade-ritual": {
    primary: "bg-jade-primary hover:bg-jade-primary/90",
    accent: "text-jade-secondary",
    overlay: "bg-gradient-to-r from-jade-primary/80 to-jade-secondary/60",
  },
  umbral: {
    primary: "bg-umbral-primary hover:bg-umbral-primary/90",
    accent: "text-umbral-secondary",
    overlay: "bg-gradient-to-r from-umbral-primary/80 to-umbral-secondary/60",
  },
  utopica: {
    primary: "bg-utopica-primary hover:bg-utopica-primary/90",
    accent: "text-utopica-secondary",
    overlay: "bg-gradient-to-r from-utopica-primary/80 to-utopica-secondary/60",
  },
  default: {
    primary: "bg-brand-primary hover:bg-brand-primary/90",
    accent: "text-gold-500",
    overlay: "bg-gradient-to-r from-brand-primary/80 to-brand-secondary/60",
  },
};

const badgeVariants = {
  default: "bg-white/20 text-white border-white/30 backdrop-blur-sm",
  natural:
    "bg-green-500/20 text-green-100 border-green-300/30 backdrop-blur-sm",
  premium: "bg-gold-500/20 text-gold-100 border-gold-300/30 backdrop-blur-sm",
  new: "bg-purple-500/20 text-purple-100 border-purple-300/30 backdrop-blur-sm animate-pulse-gentle",
};

export default function HeroSection({
  title,
  subtitle,
  description,
  backgroundImage,
  overlayOpacity = 0.6,
  textPosition = "left",
  lineTheme = "default",
  variant = "default",
  primaryAction,
  secondaryAction,
  badges = [],
  height = "lg",
  showScrollIndicator = false,
  className = "",
}: HeroSectionProps) {
  const [imageLoaded, setImageLoaded] = useState(false);
  const [isVisible, setIsVisible] = useState(false);

  const theme = lineThemeClasses[lineTheme];

  useEffect(() => {
    setIsVisible(true);
  }, []);

  return (
    <section
      className={cn(
        "relative overflow-hidden",
        heightClasses[height],
        className,
      )}
    >
      {/* Background Image */}
      <div className="absolute inset-0 z-0">
        {!imageLoaded && (
          <div className="absolute inset-0 bg-gradient-to-br from-gray-200 to-gray-400 animate-pulse" />
        )}
        <Image
          fill
          priority
          alt={title}
          className={cn(
            "object-cover transition-all duration-1000",
            imageLoaded ? "opacity-100 scale-100" : "opacity-0 scale-105",
          )}
          src={backgroundImage}
          onLoad={() => setImageLoaded(true)}
        />

        {/* Dynamic Overlay */}
        <div
          className={cn(
            "absolute inset-0 transition-opacity duration-1000",
            theme.overlay,
          )}
          style={{ opacity: overlayOpacity }}
        />

        {/* Artistic overlay pattern */}
        <div className="absolute inset-0 bg-gradient-to-t from-black/40 via-transparent to-transparent" />
        <div className="absolute inset-0 bg-gradient-to-r from-black/20 via-transparent to-transparent" />
      </div>

      {/* Content */}
      <div className="relative z-10 h-full">
        <div className="container mx-auto px-4 h-full">
          <div
            className={cn(
              "flex flex-col justify-center h-full max-w-4xl",
              textPositionClasses[textPosition],
              textPosition === "center" && "mx-auto",
              textPosition === "right" && "ml-auto",
            )}
          >
            {/* Badges */}
            {badges.length > 0 && (
              <div
                className={cn(
                  "flex flex-wrap gap-2 mb-6 transition-all duration-1000 delay-200",
                  isVisible
                    ? "opacity-100 translate-y-0"
                    : "opacity-0 translate-y-4",
                )}
              >
                {badges.map((badge, index) => (
                  <Badge
                    className={badgeVariants[badge.variant || "default"]}
                    key={index}
                  >
                    {badge.icon && <span className="mr-2">{badge.icon}</span>}
                    {badge.text}
                  </Badge>
                ))}
              </div>
            )}

            {/* Subtitle */}
            {subtitle && (
              <p
                className={cn(
                  "text-lg text-white/90 mb-4 font-medium transition-all duration-1000 delay-300",
                  theme.accent,
                  isVisible
                    ? "opacity-100 translate-y-0"
                    : "opacity-0 translate-y-4",
                )}
              >
                {subtitle}
              </p>
            )}

            {/* Title */}
            <h1
              className={cn(
                "text-4xl md:text-5xl lg:text-6xl font-bold text-white mb-6",
                "leading-tight tracking-tight transition-all duration-1000 delay-400",
                variant === "elegant" &&
                  "font-serif text-5xl md:text-6xl lg:text-7xl",
                variant === "artisanal" &&
                  "font-bold text-3xl md:text-4xl lg:text-5xl",
                isVisible
                  ? "opacity-100 translate-y-0"
                  : "opacity-0 translate-y-8",
              )}
            >
              {title}
            </h1>

            {/* Description */}
            <p
              className={cn(
                "text-lg md:text-xl text-white/90 mb-8 max-w-2xl leading-relaxed",
                "transition-all duration-1000 delay-500",
                isVisible
                  ? "opacity-100 translate-y-0"
                  : "opacity-0 translate-y-4",
              )}
            >
              {description}
            </p>

            {/* Actions */}
            {(primaryAction || secondaryAction) && (
              <div
                className={cn(
                  "flex flex-col sm:flex-row gap-4 transition-all duration-1000 delay-600",
                  textPosition === "center" && "justify-center",
                  textPosition === "right" && "justify-end",
                  isVisible
                    ? "opacity-100 translate-y-0"
                    : "opacity-0 translate-y-4",
                )}
              >
                {primaryAction && (
                  <Button
                    asChild
                    className={cn(
                      "text-white font-semibold shadow-2xl",
                      "transition-all duration-300 hover:scale-105 active:scale-95",
                      "hover:shadow-2xl",
                      theme.primary,
                    )}
                    size="lg"
                  >
                    <Link href={primaryAction.href}>
                      {primaryAction.text}
                      <ArrowRight className="ml-2 h-5 w-5" />
                    </Link>
                  </Button>
                )}

                {secondaryAction && (
                  <Button
                    asChild
                    className="text-white border-white/30 bg-white/10 backdrop-blur-sm hover:bg-white/20 font-semibold shadow-xl transition-all duration-300 hover:scale-105"
                    size="lg"
                    variant="outline"
                  >
                    <Link href={secondaryAction.href}>
                      {secondaryAction.text}
                    </Link>
                  </Button>
                )}
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Scroll Indicator */}
      {showScrollIndicator && (
        <div className="absolute bottom-8 left-1/2 transform -translate-x-1/2 z-10">
          <div className="flex flex-col items-center text-white/70 animate-bounce">
            <span className="text-sm mb-2 font-medium">Descubre más</span>
            <ChevronDown className="h-6 w-6" />
          </div>
        </div>
      )}

      {/* Decorative Elements */}
      <div className="absolute top-0 left-0 w-full h-px bg-gradient-to-r from-transparent via-white/20 to-transparent" />
      <div className="absolute bottom-0 left-0 w-full h-px bg-gradient-to-r from-transparent via-white/20 to-transparent" />
    </section>
  );
}

"use client";

import { cva, type VariantProps } from "class-variance-authority";
import {
  ChevronDown,
  ChevronRight,
  Home,
  Leaf,
  ShoppingBag,
