"use client";

import { Heart } from "lucide-react";
import Image from "next/image";
import Link from "next/link";
import { memo, useState } from "react";

import { Badge } from "@/components/ui/badge";
import { Card, CardContent } from "@/components/ui/card";
import { useLike } from "@/contexts/LikeContext";
import { cn } from "@/lib/utils";

import { ProductCardDesktopContent, ProductCardMobileContent } from "./_components/ProductCardContent";
import { cardVariants, lineThemeClasses } from "./_components/ProductCardTheme";

interface ProductCardProps {
  id: string; name: string; description: string; price: number; originalPrice?: number;
  category: string; imageUrl: string; rating: number; isNatural?: boolean; isNew?: boolean;
  isOnSale?: boolean; stock: number; size?: string; className?: string;
  variant?: "default" | "elegant" | "artisanal" | "glass";
  lineTheme?: "alma-terra" | "ecos" | "jade-ritual" | "umbral" | "utopica" | "default";
  onAddToCart?: (productId: string, quantity: number) => void;
}

function ProductCard({ id, name, description, price, originalPrice, category, imageUrl, rating, isNatural = true, isNew = false, isOnSale = false, stock, size, className = "", variant = "default", lineTheme = "default", onAddToCart }: ProductCardProps) {
  const [quantity, setQuantity] = useState(1);
  const [isHovered, setIsHovered] = useState(false);
  const [imageLoaded, setImageLoaded] = useState(false);
  const { toggleLike, isLiked, isLoading: likeLoading } = useLike();
  const theme = lineThemeClasses[lineTheme];

  return (
    <Card className={cn("group relative overflow-hidden transition-all duration-500 h-full flex flex-col hover:shadow-xl", cardVariants[variant], className)} style={{ pointerEvents: "auto" }} onMouseEnter={() => setIsHovered(true)} onMouseLeave={() => setIsHovered(false)}>
      <div className="relative flex-1 flex flex-col">
        <div className="relative aspect-square overflow-hidden bg-gradient-to-br from-bg-light to-bg-cream">
          {!imageLoaded && <div className="absolute inset-0 bg-gradient-to-br from-gray-200 to-gray-300 animate-pulse" />}
          <Image fill alt={name} className={cn("object-cover transition-all duration-700 group-hover:scale-110 group-hover:brightness-105", imageLoaded ? "opacity-100" : "opacity-0")} src={imageUrl && !imageUrl.startsWith("file://") ? imageUrl : "/images/placeholder-product.jpg"} onError={() => setImageLoaded(true)} onLoad={() => setImageLoaded(true)} />
          <div className="absolute top-2 right-2 z-20"><Heart className={cn("h-4 w-4 lg:h-5 lg:w-5 cursor-pointer transition-all duration-300 hover:scale-110", isLiked(id) ? "fill-red-500 text-red-500" : "text-white/80 hover:text-red-500 hover:fill-red-500", likeLoading && "opacity-50")} onClick={async () => await toggleLike(id)} /></div>
          <div className={cn("absolute inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center transition-all duration-300 z-10", isHovered ? "opacity-100" : "opacity-0")}>
            <Link className="block" href={`/productos/${id}`}><div className="bg-white/90 text-gray-800 px-3 py-2 lg:px-6 lg:py-3 rounded-lg font-semibold shadow-lg hover:bg-white hover:scale-105 transition-all duration-300 text-xs lg:text-sm">Ver producto</div></Link>
          </div>
          {stock <= 5 && stock > 0 && <div className="hidden lg:block absolute bottom-2 left-2 lg:bottom-3 lg:left-3"><Badge className="bg-white/95 text-orange-600 border-orange-300 shadow-md backdrop-blur-sm animate-pulse-gentle text-xs px-1.5 py-0.5 lg:text-sm lg:px-2 lg:py-1" variant="outline">¡Solo {stock} disponibles!</Badge></div>}
          {stock === 0 && <div className="absolute inset-0 bg-black/60 flex items-center justify-center backdrop-blur-sm pointer-events-none"><Badge className="bg-white text-gray-800 shadow-xl px-4 py-2 text-base" variant="secondary">Sin Stock</Badge></div>}
        </div>
        <CardContent className="p-2 flex-1 flex flex-col" padding="none">
          <ProductCardDesktopContent description={description} id={id} isNatural={isNatural} isNew={isNew} isOnSale={isOnSale} name={name} originalPrice={originalPrice} price={price} quantity={quantity} rating={rating} size={size} stock={stock} theme={theme} onAddToCart={() => { if (onAddToCart && stock > 0) { onAddToCart(id, quantity); setQuantity(1); }}} onQuantityChange={setQuantity} />
          <ProductCardMobileContent description={description} id={id} isNatural={isNatural} isNew={isNew} isOnSale={isOnSale} name={name} originalPrice={originalPrice} price={price} quantity={quantity} rating={rating} size={size} stock={stock} theme={theme} onAddToCart={() => { if (onAddToCart && stock > 0) { onAddToCart(id, quantity); setQuantity(1); }}} onQuantityChange={setQuantity} />
        </CardContent>
      </div>
    </Card>
  );
}

export default memo(ProductCard, (prevProps, nextProps) =>
  prevProps.id === nextProps.id && prevProps.name === nextProps.name && prevProps.description === nextProps.description &&
  prevProps.price === nextProps.price && prevProps.originalPrice === nextProps.originalPrice && prevProps.category === nextProps.category &&
  prevProps.imageUrl === nextProps.imageUrl && prevProps.rating === nextProps.rating && prevProps.isNatural === nextProps.isNatural &&
  prevProps.isNew === nextProps.isNew && prevProps.isOnSale === nextProps.isOnSale && prevProps.stock === nextProps.stock &&
  prevProps.size === nextProps.size && prevProps.className === nextProps.className && prevProps.variant === nextProps.variant &&
  prevProps.lineTheme === nextProps.lineTheme && prevProps.onAddToCart === nextProps.onAddToCart,
);

"use client";

import {
  ArrowUpDown,
  Grid2X2,
  Grid3X3,
  Search,
  SlidersHorizontal,
  Star,
  TrendingUp,
  X,
} from "lucide-react";
import { useMemo, useState } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { cn } from "@/lib/utils";

import ProductCard from "./ProductCard";

interface Product {
  id: string;
  name: string;
  description: string;
  price: number;
  originalPrice?: number;
  category: string;
  imageUrl: string;
  rating: number;
  isNatural?: boolean;
  isNew?: boolean;
  isOnSale?: boolean;
  stock: number;
  size?: string;
  tags?: string[];
  lineTheme?:
    | "alma-terra"
    | "ecos"
    | "jade-ritual"
    | "umbral"
    | "utopica"
    | "default";
}

interface ProductGridProps {
  products: Product[];
  title?: string;
  subtitle?: string;
  variant?: "default" | "elegant" | "artisanal" | "glass";
  lineTheme?:
    | "alma-terra"
    | "ecos"
    | "jade-ritual"
    | "umbral"
    | "utopica"
    | "default";
  showFilters?: boolean;
  showSearch?: boolean;
  showSorting?: boolean;
  showGridToggle?: boolean;
  initialGridCols?: 2 | 3 | 4;
  onAddToCart?: (productId: string, quantity: number) => void;
  onToggleFavorite?: (productId: string) => void;
  favoriteProducts?: string[];
  className?: string;
}

const sortOptions = [
  { value: "featured", label: "Destacados", icon: Star },
  { value: "name-asc", label: "Nombre A-Z", icon: ArrowUpDown },
  { value: "name-desc", label: "Nombre Z-A", icon: ArrowUpDown },
  { value: "price-asc", label: "Precio: Menor a Mayor", icon: TrendingUp },
  { value: "price-desc", label: "Precio: Mayor a Menor", icon: TrendingUp },
  { value: "rating", label: "Mejor Valorados", icon: Star },
  { value: "newest", label: "Más Nuevos", icon: Star },
];

const gridColsClasses = {
  2: "grid-cols-1 md:grid-cols-2",
  3: "grid-cols-1 md:grid-cols-2 lg:grid-cols-3",
  4: "grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4",
};

export default function ProductGrid({
  products,
  title,
  subtitle,
  variant = "default",
  lineTheme = "default",
  showFilters = true,
  showSearch = true,
  showSorting = true,
  showGridToggle = true,
  initialGridCols = 3,
  onAddToCart,
  onToggleFavorite,
  favoriteProducts = [],
  className = "",
}: ProductGridProps) {
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedCategory, setSelectedCategory] = useState<string>("all");
  const [selectedPriceRange, setSelectedPriceRange] = useState<string>("all");
  const [sortBy, setSortBy] = useState("featured");
  const [gridCols, setGridCols] = useState(initialGridCols);
  const [showFiltersPanel, setShowFiltersPanel] = useState(false);

  // Get unique categories from products
  const categories = useMemo(() => {
    const cats = Array.from(new Set(products.map((p) => p.category)));
    return cats.filter(Boolean);
  }, [products]);

  // Filter and sort products
  const filteredAndSortedProducts = useMemo(() => {
    const filtered = products.filter((product) => {
      // Search filter
      if (searchQuery) {
        const query = searchQuery.toLowerCase();
        const searchableText =
          `${product.name} ${product.description} ${product.category}`.toLowerCase();
        if (!searchableText.includes(query)) return false;
      }

      // Category filter
      if (selectedCategory !== "all" && product.category !== selectedCategory) {
        return false;
      }

      // Price range filter
      if (selectedPriceRange !== "all") {
        const price = product.price;
        switch (selectedPriceRange) {
          case "0-1000":
            if (price > 1000) return false;
            break;
          case "1000-5000":
            if (price < 1000 || price > 5000) return false;
            break;
          case "5000-10000":
            if (price < 5000 || price > 10000) return false;
            break;
          case "10000+":
            if (price < 10000) return false;
            break;
        }
      }

      return true;
    });

    // Sort products
    filtered.sort((a, b) => {
      switch (sortBy) {
        case "name-asc":
          return a.name.localeCompare(b.name);
        case "name-desc":
          return b.name.localeCompare(a.name);
        case "price-asc":
          return a.price - b.price;
        case "price-desc":
          return b.price - a.price;
        case "rating":
          return b.rating - a.rating;
        case "newest":
          return (b.isNew ? 1 : 0) - (a.isNew ? 1 : 0);
        default:
          // Featured - prioritize new, on sale, high rating
          const aScore = (a.isNew ? 3 : 0) + (a.isOnSale ? 2 : 0) + a.rating;
          const bScore = (b.isNew ? 3 : 0) + (b.isOnSale ? 2 : 0) + b.rating;
          return bScore - aScore;
      }
    });

    return filtered;
  }, [products, searchQuery, selectedCategory, selectedPriceRange, sortBy]);

  const clearFilters = () => {
    setSearchQuery("");
    setSelectedCategory("all");
    setSelectedPriceRange("all");
    setSortBy("featured");
  };

  const hasActiveFilters =
    searchQuery ||
    selectedCategory !== "all" ||
    selectedPriceRange !== "all" ||
    sortBy !== "featured";

  return (
    <div className={cn("w-full", className)}>
      {/* Header */}
      {(title || subtitle) && (
        <div className="text-center mb-8">
          {subtitle && (
            <p className="text-text-secondary text-lg mb-2">{subtitle}</p>
          )}
          {title && (
            <h2 className="text-3xl md:text-4xl font-bold text-text-primary mb-4">
              {title}
            </h2>
          )}
        </div>
      )}

      {/* Controls */}
      <div className="flex flex-col lg:flex-row gap-4 mb-8">
        {/* Search */}
        {showSearch && (
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-text-secondary h-4 w-4" />
            <Input
              className="pl-10"
              placeholder="Buscar productos..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
        )}

        {/* Controls Row */}
        <div className="flex flex-wrap gap-4 items-center">
          {/* Filters Toggle */}
          {showFilters && (
            <Button
              className={cn(
                "transition-all duration-300",
                showFiltersPanel &&
                  "bg-brand-primary/10 border-brand-primary text-brand-primary",
              )}
              size="sm"
              variant="outline"
              onClick={() => setShowFiltersPanel(!showFiltersPanel)}
            >
              <SlidersHorizontal className="h-4 w-4 mr-2" />
              Filtros
              {hasActiveFilters && (
                <Badge className="ml-2 bg-brand-primary text-white text-xs">
                  •
                </Badge>
              )}
            </Button>
          )}

          {/* Sorting */}
          {showSorting && (
            <Select value={sortBy} onValueChange={setSortBy}>
              <SelectTrigger className="w-[200px]">
                <SelectValue placeholder="Ordenar por" />
              </SelectTrigger>
              <SelectContent>
                {sortOptions.map((option) => (
                  <SelectItem key={option.value} value={option.value}>
                    <div className="flex items-center">
                      <option.icon className="h-4 w-4 mr-2" />
                      {option.label}
                    </div>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          )}

          {/* Grid Toggle */}
          {showGridToggle && (
            <div className="flex gap-1 border rounded-lg p-1">
              <Button
                className="h-8 w-8 p-0"
                size="sm"
                variant={gridCols === 2 ? "default" : "ghost"}
                onClick={() => setGridCols(2)}
              >
                <Grid2X2 className="h-4 w-4" />
              </Button>
              <Button
                className="h-8 w-8 p-0"
                size="sm"
                variant={gridCols === 3 ? "default" : "ghost"}
                onClick={() => setGridCols(3)}
              >
                <Grid3X3 className="h-4 w-4" />
              </Button>
              <Button
                className="h-8 w-8 p-0"
                size="sm"
                variant={gridCols === 4 ? "default" : "ghost"}
                onClick={() => setGridCols(4)}
              >
                <div className="grid grid-cols-2 gap-0.5 h-4 w-4">
                  <div className="bg-current rounded-sm" />
                  <div className="bg-current rounded-sm" />
                  <div className="bg-current rounded-sm" />
                  <div className="bg-current rounded-sm" />
                </div>
              </Button>
            </div>
          )}
        </div>
      </div>

      {/* Filters Panel */}
      {showFilters && showFiltersPanel && (
        <div className="bg-white border border-border rounded-lg p-6 mb-8 transition-all duration-300">
          <div className="flex flex-wrap gap-6">
            {/* Category Filter */}
            <div className="space-y-2">
              <label className="text-sm font-medium text-text-primary">
                Categoría
              </label>
              <Select
                value={selectedCategory}
                onValueChange={setSelectedCategory}
              >
                <SelectTrigger className="w-[180px]">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Todas las categorías</SelectItem>
                  {categories.map((category) => (
                    <SelectItem key={category} value={category}>
                      {category}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Price Range Filter */}
            <div className="space-y-2">
              <label className="text-sm font-medium text-text-primary">
                Rango de Precio
              </label>
              <Select
                value={selectedPriceRange}
                onValueChange={setSelectedPriceRange}
              >
                <SelectTrigger className="w-[180px]">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Todos los precios</SelectItem>
                  <SelectItem value="0-1000">Hasta $1,000</SelectItem>
                  <SelectItem value="1000-5000">$1,000 - $5,000</SelectItem>
                  <SelectItem value="5000-10000">$5,000 - $10,000</SelectItem>
                  <SelectItem value="10000+">Más de $10,000</SelectItem>
                </SelectContent>
              </Select>
            </div>

            {/* Clear Filters */}
            {hasActiveFilters && (
              <div className="flex items-end">
                <Button
                  className="text-brand-primary hover:text-brand-primary/80"
                  size="sm"
                  variant="ghost"
                  onClick={clearFilters}
                >
                  <X className="h-4 w-4 mr-2" />
                  Limpiar filtros
                </Button>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Results Info */}
      <div className="flex justify-between items-center mb-6">
        <p className="text-text-secondary">
          {filteredAndSortedProducts.length} producto
          {filteredAndSortedProducts.length !== 1 ? "s" : ""} encontrado
          {filteredAndSortedProducts.length !== 1 ? "s" : ""}
        </p>

        {hasActiveFilters && (
          <div className="flex items-center gap-2">
            <span className="text-sm text-text-secondary">
              Filtros activos:
            </span>
            <div className="flex gap-2">
              {searchQuery && (
                <Badge className="text-xs" variant="secondary">
                  Búsqueda: &quot;{searchQuery}&quot;
                </Badge>
              )}
              {selectedCategory !== "all" && (
                <Badge className="text-xs" variant="secondary">
                  {selectedCategory}
                </Badge>
              )}
              {selectedPriceRange !== "all" && (
                <Badge className="text-xs" variant="secondary">
                  Precio: {selectedPriceRange}
                </Badge>
              )}
            </div>
          </div>
        )}
      </div>

      {/* Products Grid */}
      {filteredAndSortedProducts.length === 0 ? (
        <div className="text-center py-16">
          <div className="text-6xl mb-4">🔍</div>
          <h3 className="text-xl font-semibold text-text-primary mb-2">
            No se encontraron productos
          </h3>
          <p className="text-text-secondary mb-6">
            Intenta ajustar tus filtros de búsqueda
          </p>
          {hasActiveFilters && (
            <Button variant="outline" onClick={clearFilters}>
              Limpiar filtros
            </Button>
          )}
        </div>
      ) : (
        <div
          className={cn(
            "grid gap-6 transition-all duration-300",
            gridColsClasses[gridCols],
          )}
        >
          {filteredAndSortedProducts.map((product) => (
            <ProductCard
              category={product.category}
              description={product.description}
              id={product.id}
              imageUrl={product.imageUrl}
              isNatural={product.isNatural}
              isNew={product.isNew}
              isOnSale={product.isOnSale}
              key={product.id}
              lineTheme={product.lineTheme || lineTheme}
              name={product.name}
              originalPrice={product.originalPrice}
              price={product.price}
              rating={product.rating}
              size={product.size}
              stock={product.stock}
              variant={variant}
              onAddToCart={onAddToCart}
            />
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import {
  Award,
  BookOpen,
  Calendar,
  CheckCircle,
  Circle,
  Lock,
  Star,
  Target,
} from "lucide-react";

import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Progress } from "@/components/ui/progress";

interface ProgressStep {
  id: string;
  title: string;
  description: string;
  status: "completed" | "current" | "locked" | "available";
  week: number;
  completionPercentage?: number;
  dueDate?: string;
  estimatedTime?: string;
}

interface ProgressIndicatorProps {
  title: string;
  description?: string;
  currentWeek: number;
  totalWeeks: number;
  overallProgress: number;
  steps: ProgressStep[];
  className?: string;
  showDetailed?: boolean;
  compact?: boolean;
}

export default function ProgressIndicator({
  title,
  description,
  currentWeek,
  totalWeeks,
  overallProgress,
  steps,
  className = "",
  showDetailed = false,
  compact = false,
}: ProgressIndicatorProps) {
  const getStepIcon = (status: ProgressStep["status"]) => {
    switch (status) {
      case "completed":
        return <CheckCircle className="h-5 w-5 text-verde-suave" />;
      case "current":
        return <Circle className="h-5 w-5 text-dorado animate-pulse" />;
      case "locked":
        return <Lock className="h-5 w-5 text-gray-400" />;
      case "available":
        return <Circle className="h-5 w-5 text-azul-profundo" />;
      default:
        return <Circle className="h-5 w-5 text-gray-400" />;
    }
  };

  const getStepBadge = (status: ProgressStep["status"]) => {
    switch (status) {
      case "completed":
        return (
          <Badge
            className="bg-verde-suave text-white"
            style={{ color: "var(--admin-accent-secondary)" }}
          >
            Completado
          </Badge>
        );
      case "current":
        return (
          <Badge className="bg-dorado text-azul-profundo">En Progreso</Badge>
        );
      case "locked":
        return (
          <Badge className="text-gray-500" variant="secondary">
            Bloqueado
          </Badge>
        );
      case "available":
        return (
          <Badge
            className="border-azul-profundo text-azul-profundo"
            variant="outline"
          >
            Disponible
          </Badge>
        );
    }
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString("es-AR", {
      month: "short",
      day: "numeric",
    });
  };

  const completedSteps = steps.filter(
    (step) => step.status === "completed",
  ).length;

  if (compact) {
    return (
      <Card className={`${className}`}>
        <CardContent className="p-4">
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <h4 className="font-semibold text-azul-profundo">{title}</h4>
              <Badge
                className="bg-dorado/20 text-azul-profundo"
                variant="secondary"
              >
                Semana {currentWeek}/{totalWeeks}
              </Badge>
            </div>

            <div className="space-y-2">
              <div className="flex items-center justify-between text-sm">
                <span className="text-tierra-media">Progreso general</span>
                <span className="font-semibold text-azul-profundo">
                  {overallProgress}%
                </span>
              </div>
              <Progress className="h-2" value={overallProgress} />
            </div>

            <div className="flex items-center justify-between text-sm text-tierra-media">
              <div className="flex items-center gap-1">
                <CheckCircle className="h-4 w-4 text-verde-suave" />
                <span>
                  {completedSteps} de {steps.length} completados
                </span>
              </div>
              <div className="flex items-center gap-1">
                <Target className="h-4 w-4 text-dorado" />
                <span>Meta: 100%</span>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className={`${className}`}>
      <CardHeader className="pb-4">
        <div className="flex items-center justify-between">
          <div>
            <CardTitle className="text-azul-profundo">{title}</CardTitle>
            {description && (
              <p className="text-sm text-tierra-media mt-1">{description}</p>
            )}
          </div>
          <div className="text-right">
            <Badge
              className="bg-dorado/20 text-azul-profundo mb-2"
              variant="secondary"
            >
              Semana {currentWeek}/{totalWeeks}
            </Badge>
            <div className="text-2xl font-bold text-azul-profundo">
              {overallProgress}%
            </div>
          </div>
        </div>

        {/* Overall Progress */}
        <div className="space-y-2">
          <div className="flex items-center justify-between text-sm">
            <span className="text-tierra-media">Progreso del programa</span>
            <div className="flex items-center gap-1">
              <Award className="h-4 w-4 text-dorado" />
              <span className="text-azul-profundo font-semibold">
                {completedSteps}/{steps.length} módulos
              </span>
            </div>
          </div>
          <Progress className="h-3" value={overallProgress} />
        </div>
      </CardHeader>

      <CardContent className="space-y-4">
        {/* Steps List */}
        <div className="space-y-3">
          {steps.map((step, index) => (
            <div
              className={`flex items-start gap-3 p-4 rounded-lg transition-colors ${
                step.status === "current"
                  ? "bg-dorado/10 border border-dorado/20"
                  : step.status === "completed"
                    ? "bg-verde-suave/10 border border-verde-suave/20"
                    : "bg-gray-50 border border-gray-200"
              }`}
              key={step.id}
            >
              {/* Step Icon */}
              <div className="mt-0.5">{getStepIcon(step.status)}</div>

              {/* Step Content */}
              <div className="flex-1 min-w-0">
                <div className="flex items-start justify-between">
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-1">
                      <h5
                        className={`font-semibold ${
                          step.status === "locked"
                            ? "text-gray-500"
                            : "text-azul-profundo"
                        }`}
                      >
                        {step.title}
                      </h5>
                      <Badge className="text-xs" variant="outline">
                        Semana {step.week}
                      </Badge>
                    </div>
                    <p
                      className={`text-sm ${
                        step.status === "locked"
                          ? "text-gray-400"
                          : "text-tierra-media"
                      }`}
                    >
                      {step.description}
                    </p>

                    {/* Step Details */}
                    <div className="flex items-center gap-4 mt-2 text-xs text-tierra-media">
                      {step.estimatedTime && (
                        <div className="flex items-center gap-1">
                          <BookOpen className="h-3 w-3" />
                          <span>{step.estimatedTime}</span>
                        </div>
                      )}
                      {step.dueDate && (
                        <div className="flex items-center gap-1">
                          <Calendar className="h-3 w-3" />
                          <span>Hasta {formatDate(step.dueDate)}</span>
                        </div>
                      )}
                    </div>

                    {/* Individual Progress */}
                    {step.status === "current" &&
                      step.completionPercentage !== undefined && (
                        <div className="mt-3 space-y-1">
                          <div className="flex items-center justify-between text-xs">
                            <span className="text-tierra-media">
                              Progreso del módulo
                            </span>
                            <span className="font-semibold text-azul-profundo">
                              {step.completionPercentage}%
                            </span>
                          </div>
                          <Progress
                            className="h-1.5"
                            value={step.completionPercentage}
                          />
                        </div>
                      )}
                  </div>

                  {/* Status Badge */}
                  <div className="ml-2">{getStepBadge(step.status)}</div>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Achievement Badge */}
        {overallProgress >= 80 && (
          <div className="mt-6 p-4 bg-gradient-to-r from-dorado/20 to-verde-suave/20 rounded-lg border border-dorado/30">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-dorado rounded-full">
                <Star className="h-5 w-5 text-azul-profundo" />
              </div>
              <div>
                <h6 className="font-semibold text-azul-profundo">
                  ¡Excelente progreso!
                </h6>
                <p className="text-sm text-tierra-media">
                  Estás muy cerca de completar tu transformación. ¡Sigue así!
                </p>
              </div>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import {
  ArrowRight,
  Calendar,
  Clock,
  Heart,
  MapPin,
  Star,
  Users,
  Video,
} from "lucide-react";
import Image from "next/image";
import Link from "next/link";
import { useState } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";

interface ServiceCardProps {
  id: string;
  title: string;
  description: string;
  price: number;
  duration: string;
  category: string;
  imageUrl: string;
  rating: number;
  location: "online" | "presencial" | "ambos";
  groupSize: "individual" | "grupal" | "ambos";
  features: string[];
  isPopular?: boolean;
  nextAvailableDate?: string;
  therapistName?: string;
  className?: string;
  onBookSession?: (serviceId: string) => void;
}

export default function ServiceCard({
  id,
  title,
  description,
  price,
  duration,
  category,
  imageUrl,
  rating,
  location,
  groupSize,
  features,
  isPopular = false,
  nextAvailableDate,
  therapistName,
  className = "",
  onBookSession,
}: ServiceCardProps) {
  const [isHovered, setIsHovered] = useState(false);

  const handleBookSession = () => {
    if (onBookSession) {
      onBookSession(id);
    }
  };

  const formatPrice = (amount: number) => {
    return new Intl.NumberFormat("es-AR", {
      style: "currency",
      currency: "ARS",
    }).format(amount);
  };

  const renderStars = (rating: number) => {
    return Array.from({ length: 5 }, (_, index) => (
      <Star
        className={`h-4 w-4 ${
          index < Math.floor(rating)
            ? "fill-dorado text-dorado"
            : "text-gray-300"
        }`}
        key={index}
      />
    ));
  };

  const getLocationIcon = () => {
    switch (location) {
      case "online":
        return <Video className="h-4 w-4 text-turquesa-claro" />;
      case "presencial":
        return <MapPin className="h-4 w-4 text-verde-suave" />;
      case "ambos":
        return <Users className="h-4 w-4 text-azul-profundo" />;
      default:
        return <MapPin className="h-4 w-4 text-verde-suave" />;
    }
  };

  const getLocationText = () => {
    switch (location) {
      case "online":
        return "Online";
      case "presencial":
        return "Presencial";
      case "ambos":
        return "Online & Presencial";
      default:
        return "Presencial";
    }
  };

  return (
    <Card
      className={`group relative overflow-hidden transition-all duration-300 hover:shadow-lg hover:-translate-y-1 ${className}`}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      <div className="relative">
        {/* Service Image */}
        <div className="relative h-48 overflow-hidden bg-verde-suave/10">
          <Image
            fill
            alt={title}
            className="object-cover transition-transform duration-300 group-hover:scale-105"
            src={imageUrl}
          />

          {/* Popular Badge */}
          {isPopular && (
            <div className="absolute top-4 left-4">
              <Badge className="bg-dorado text-azul-profundo font-semibold">
                <Heart className="h-3 w-3 mr-1" />
                Más Popular
              </Badge>
            </div>
          )}

          {/* Service Details Overlay */}
          <div className="absolute bottom-4 left-4 right-4">
            <div className="bg-white/95 backdrop-blur-sm rounded-lg p-3">
              <div className="flex items-center justify-between text-sm">
                <div className="flex items-center gap-4">
                  <div className="flex items-center gap-1 text-tierra-media">
                    <Clock className="h-4 w-4" />
                    <span>{duration}</span>
                  </div>
                  <div className="flex items-center gap-1 text-tierra-media">
                    {getLocationIcon()}
                    <span>{getLocationText()}</span>
                  </div>
                </div>
                <div className="text-lg font-bold text-azul-profundo">
                  {formatPrice(price)}
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Service Content */}
        <CardContent className="p-6 space-y-4">
          {/* Category and Rating */}
          <div className="flex items-center justify-between">
            <div className="text-xs text-tierra-media uppercase tracking-wide">
              {category}
            </div>
            <div className="flex items-center gap-1">
              <div className="flex items-center">{renderStars(rating)}</div>
            </div>
          </div>

          {/* Title */}
          <Link href={`/servicios/${id}` as unknown}>
            <h3 className="text-xl font-semibold text-azul-profundo line-clamp-2 hover:text-azul-profundo/80 transition-colors">
              {title}
            </h3>
          </Link>

          {/* Description */}
          <p className="text-tierra-media line-clamp-3">{description}</p>

          {/* Features */}
          <div className="space-y-2">
            <h4 className="text-sm font-semibold text-azul-profundo">
              ¿Qué incluye?
            </h4>
            <ul className="space-y-1">
              {features.slice(0, 3).map((feature, index) => (
                <li
                  className="text-sm text-tierra-media flex items-center gap-2"
                  key={index}
                >
                  <div className="h-1.5 w-1.5 rounded-full bg-dorado" />
                  {feature}
                </li>
              ))}
              {features.length > 3 && (
                <li className="text-sm text-azul-profundo font-medium">
                  + {features.length - 3} beneficios más
                </li>
              )}
            </ul>
          </div>

          {/* Therapist */}
          {therapistName && (
            <div className="flex items-center gap-2 text-sm text-tierra-media">
              <div className="h-8 w-8 rounded-full bg-dorado/20 flex items-center justify-center">
                <Heart className="h-4 w-4 text-azul-profundo" />
              </div>
              <span>Con {therapistName}</span>
            </div>
          )}

          {/* Group Size */}
          <div className="flex items-center gap-2 text-sm text-tierra-media">
            <Users className="h-4 w-4" />
            <span>
              {groupSize === "individual" && "Sesión Individual"}
              {groupSize === "grupal" && "Sesión Grupal"}
              {groupSize === "ambos" && "Individual o Grupal"}
            </span>
          </div>

          {/* Next Available Date */}
          {nextAvailableDate && (
            <div className="flex items-center gap-2 text-sm">
              <Calendar className="h-4 w-4 text-verde-suave" />
              <span className="text-tierra-media">
                Próxima fecha:{" "}
                <span className="font-semibold text-azul-profundo">
                  {nextAvailableDate}
                </span>
              </span>
            </div>
          )}

          {/* Action Buttons */}
          <div className="flex gap-2 pt-2">
            <Button
              asChild
              className="flex-1 border-azul-profundo text-azul-profundo hover:bg-azul-profundo hover:text-white"
              variant="outline"
            >
              <Link href={`/servicios/${id}` as unknown}>Más Info</Link>
            </Button>
            <Button
              className="flex-1 bg-dorado hover:bg-dorado/90 text-azul-profundo font-semibold"
              onClick={handleBookSession}
            >
              Reservar
              <ArrowRight className="h-4 w-4 ml-2" />
            </Button>
          </div>
        </CardContent>
      </div>
    </Card>
  );
}

"use client";

import {
  Award,
  ChevronLeft,
  ChevronRight,
  Heart,
  Quote,
  Star,
} from "lucide-react";
import Image from "next/image";
import { useState } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";

interface TestimonialCardProps {
  id: string;
  name: string;
  location?: string;
  avatar?: string;
  rating: number;
  testimonial: string;
  productOrService?: string;
  category: "producto" | "servicio" | "membresia";
  date: string;
  isVerified?: boolean;
  images?: string[];
  className?: string;
}

export default function TestimonialCard({
  id,
  name,
  location,
  avatar,
  rating,
  testimonial,
  productOrService,
  category,
  date,
  isVerified = false,
  images = [],
  className = "",
}: TestimonialCardProps) {
  const [currentImageIndex, setCurrentImageIndex] = useState(0);

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString("es-AR", {
      year: "numeric",
      month: "long",
      day: "numeric",
    });
  };

  const renderStars = (rating: number) => {
    return Array.from({ length: 5 }, (_, index) => (
      <Star
        className={`h-4 w-4 ${
          index < Math.floor(rating)
            ? "fill-dorado text-dorado"
            : "text-gray-300"
        }`}
        key={index}
      />
    ));
  };

  const getCategoryBadge = () => {
    switch (category) {
      case "producto":
        return (
          <Badge
            className="bg-verde-suave/20 text-verde-suave"
            variant="secondary"
          >
            Producto
          </Badge>
        );
      case "servicio":
        return (
          <Badge
            className="bg-turquesa-claro/20 text-turquesa-claro"
            variant="secondary"
          >
            Servicio
          </Badge>
        );
      case "membresia":
        return (
          <Badge
            className="bg-dorado/20 text-azul-profundo"
            variant="secondary"
          >
            Membresía
          </Badge>
        );
    }
  };

  const nextImage = () => {
    setCurrentImageIndex((prev) => (prev + 1) % images.length);
  };

  const prevImage = () => {
    setCurrentImageIndex((prev) => (prev - 1 + images.length) % images.length);
  };

  return (
    <Card
      className={`relative overflow-hidden transition-all duration-300 hover:shadow-lg ${className}`}
    >
      <CardContent className="p-6">
        {/* Header */}
        <div className="flex items-start justify-between mb-4">
          <div className="flex items-center gap-3">
            {/* Avatar */}
            <div className="relative">
              {avatar ? (
                <Image
                  alt={name}
                  className="rounded-full object-cover"
                  height={48}
                  src={avatar}
                  width={48}
                />
              ) : (
                <div className="h-12 w-12 rounded-full bg-dorado/20 flex items-center justify-center">
                  <span className="text-azul-profundo font-semibold text-lg">
                    {name.charAt(0).toUpperCase()}
                  </span>
                </div>
              )}
              {isVerified && (
                <div className="absolute -top-1 -right-1 bg-verde-suave rounded-full p-1">
                  <Award className="h-3 w-3 text-white" />
                </div>
              )}
            </div>

            {/* User Info */}
            <div>
              <div className="flex items-center gap-2">
                <h4 className="font-semibold text-azul-profundo">{name}</h4>
                {isVerified && (
                  <Badge
                    className="text-xs bg-verde-suave/20 text-verde-suave"
                    variant="secondary"
                  >
                    Verificado
                  </Badge>
                )}
              </div>
              {location && (
                <p className="text-sm text-tierra-media">{location}</p>
              )}
            </div>
          </div>

          {/* Category Badge */}
          {getCategoryBadge()}
        </div>

        {/* Rating */}
        <div className="flex items-center gap-2 mb-4">
          <div className="flex items-center">{renderStars(rating)}</div>
          <span className="text-sm font-medium text-azul-profundo">
            {rating}/5
          </span>
        </div>

        {/* Quote Icon */}
        <div className="mb-4">
          <Quote className="h-8 w-8 text-dorado/30" />
        </div>

        {/* Testimonial Text */}
        <blockquote className="text-tierra-media mb-4 leading-relaxed">
          &quot;{testimonial}&quot;
        </blockquote>

        {/* Product/Service Reference */}
        {productOrService && (
          <div className="mb-4 p-3 bg-verde-suave/10 rounded-lg">
