  const [organizationId, setOrganizationId] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isInitialized, setIsInitialized] = useState(false);
  const lastOrganizationIdRef = useRef<string | null>(null);

  // Función optimizada para inicializar desde localStorage (solo para super admins)
  const initializeFromStorage = (availableBranches: Branch[]) => {
    const savedBranchId = localStorage.getItem(STORAGE_KEY);

    if (savedBranchId === "global") {
      setCurrentBranchState(null);
      setIsGlobalView(true);
    } else if (savedBranchId) {
      const branch = availableBranches.find((b) => b.id === savedBranchId);
      if (branch) {
        setCurrentBranchState(branch);
        setIsGlobalView(false);
      } else {
        // Saved branch no longer exists, default to global view
        setCurrentBranchState(null);
        setIsGlobalView(true);
        localStorage.setItem(STORAGE_KEY, "global");
      }
    } else {
      // No saved selection, default to global view
      setCurrentBranchState(null);
      setIsGlobalView(true);
      localStorage.setItem(STORAGE_KEY, "global");
    }
  };

  const fetchBranches = async (forceRefresh: boolean = false) => {
    if (!user) {
      setIsLoading(false);
      return;
    }

    // Para super admins: si ya está inicializado y no es un refresh forzado,
    // solo validar que la sucursal guardada aún existe (sin hacer petición al servidor).
    // Si organizationId cambió (ej. usuario activó su óptica real), NO saltar: forzar re-fetch.
    if (isSuperAdmin && isInitialized && !forceRefresh) {
      const savedBranchId = localStorage.getItem(STORAGE_KEY);

      // Si hay una sucursal guardada, verificar que aún existe en la lista actual
      if (savedBranchId && savedBranchId !== "global") {
        const branchExists = branches.some((b) => b.id === savedBranchId);
        if (!branchExists) {
          // La sucursal ya no existe, actualizar a global view
          setCurrentBranchState(null);
          setIsGlobalView(true);
          localStorage.setItem(STORAGE_KEY, "global");
        }
      }
      // No hacer petición al servidor - usar datos en memoria
      return;
    }

    try {
      setIsLoading(true);
      const response = await fetch("/api/admin/branches");

      if (!response.ok) {
        throw new Error("Failed to fetch branches");
      }

      const data = await response.json();
      const serverIsSuperAdmin = data.isSuperAdmin || false;
      const responseOrgId = data.organizationId ?? null;
      setBranches(data.branches || []);
      setIsSuperAdmin(serverIsSuperAdmin);
      setOrganizationId(responseOrgId);

      // Track organizationId for change detection (e.g. user activated real org)
      lastOrganizationIdRef.current = responseOrgId;

      // For super admins, prioritize localStorage to maintain selection across page reloads
      // For regular admins, use server values (they have assigned branches)
      if (serverIsSuperAdmin) {
        // Para super admins, usar localStorage como fuente de verdad
        initializeFromStorage(data.branches || []);
      } else {
        // Regular admin: use server values (they have assigned branches)
        setIsGlobalView(data.isGlobalView || false);

        // Check localStorage first, but validate it exists in available branches
        const savedBranchId = localStorage.getItem(STORAGE_KEY);
        let branchToUse: Branch | undefined;

        if (savedBranchId && savedBranchId !== "global") {
          // Validate saved branch still exists and user has access
          branchToUse = data.branches?.find(
            (b: Branch) => b.id === savedBranchId,
          );
        }

        // If no valid saved branch, use primary branch or first available
        if (!branchToUse) {
          branchToUse =
            data.branches?.find((b: Branch) => b.is_primary) ||
            data.branches?.[0];
        }

        if (branchToUse) {
          setCurrentBranchState(branchToUse);
          localStorage.setItem(STORAGE_KEY, branchToUse.id);
        } else if (data.branches && data.branches.length > 0) {
          // Fallback: use first branch if no primary found
          const firstBranch = data.branches[0];
          setCurrentBranchState(firstBranch);
          localStorage.setItem(STORAGE_KEY, firstBranch.id);
        }
      }

      setIsInitialized(true);
    } catch (error) {
      appLogger.error("Error fetching branches:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const setCurrentBranch = async (branchId: string | "global" | null) => {
    if (branchId === "global") {
      if (!isSuperAdmin) {
        appLogger.error("Only super admins can use global view");
        return;
      }
      setCurrentBranchState(null);
      setIsGlobalView(true);
      localStorage.setItem(STORAGE_KEY, "global");
      // No need to notify server - localStorage is source of truth for super admins
    } else if (branchId) {
      const branch = branches.find((b) => b.id === branchId);
      if (branch) {
        setCurrentBranchState(branch);
        setIsGlobalView(false);
        localStorage.setItem(STORAGE_KEY, branch.id);
        // No need to notify server - localStorage is source of truth for super admins
      }
    }
  };

  // Fetch organizationId to detect org changes (e.g. user activated real optica from demo)
  useEffect(() => {
    if (!user || authLoading) return;

    let cancelled = false;
    const loadOrgId = async () => {
      try {
        const res = await fetch("/api/admin/check-status");
        if (!res.ok || cancelled) return;
        const data = await res.json();
        const orgId = data.organization?.organizationId ?? null;

        if (cancelled) return;

        // Reset when organization changed (e.g. demo -> real optica)
        if (
          lastOrganizationIdRef.current !== null &&
          lastOrganizationIdRef.current !== orgId
        ) {
          setIsInitialized(false);
          setBranches([]);
          setCurrentBranchState(null);
          setIsGlobalView(false);
          localStorage.removeItem(STORAGE_KEY);
        }
        lastOrganizationIdRef.current = orgId;
      } catch {
        // Ignore - check-status may fail if not admin
      }
    };
    loadOrgId();
    return () => {
      cancelled = true;
    };
  }, [user, authLoading, pathname]);

  // Inicializar cuando el usuario se autentica o cuando se resetea por cambio de org
  useEffect(() => {
    if (!authLoading && user && !isInitialized) {
      fetchBranches();
    } else if (!authLoading && !user) {
      setIsLoading(false);
      setBranches([]);
      setCurrentBranchState(null);
      setOrganizationId(null);
      setIsInitialized(false);
      lastOrganizationIdRef.current = null;
      localStorage.removeItem(STORAGE_KEY);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user, authLoading, isInitialized]);

  return (
    <BranchContext.Provider
      value={{
        branches,
        currentBranch,
        isGlobalView,
        isSuperAdmin,
        isLoading,
        organizationId,
        setCurrentBranch,
        refreshBranches: () => fetchBranches(true),
      }}
    >
      {children}
    </BranchContext.Provider>
  );
}

export function useBranchContext() {
  const context = useContext(BranchContext);
  if (context === undefined) {
    throw new Error("useBranchContext must be used within a BranchProvider");
  }
  return context;
}

"use client";

import type { AuthError, Session, User } from "@supabase/supabase-js";
import { useEffect, useState } from "react";

import { appLogger } from '@/lib/logger';
import { createClient } from "@/utils/supabase/client";

import { fetchProfile } from "./useAuthFetchProfile";
import type { AuthState, Profile } from "./useAuthTypes";
export type { AuthState } from "./useAuthTypes";

/**
 * @param initialUser - Usuario validado en servidor (getUser).
 */
export function useAuth(initialUser?: User | null) {
  const [authState, setAuthState] = useState<AuthState>({
    user: initialUser ?? null,
    profile: null,
    session: null,
    loading: !initialUser,
    error: null,
  });

  useEffect(() => {
    let mounted = true;
    let initialized = false;
    const supabase = createClient();

    const applyAuthState = (
      user: User | null,
      profile: Profile | null,
      session: Session | null,
    ) => {
      if (!mounted || initialized) return;
      initialized = true;
      setAuthState({
        user,
        profile,
        session,
        loading: false,
        error: null,
      });
    };

    // Si tenemos initialUser del servidor: confiar en él, cargar perfil y no ejecutar getSession
    // (evita race entre getSession e INITIAL_SESSION que causa loop en reload)
    if (initialUser) {
      fetchProfile(initialUser.id)
        .then((profile) => {
          if (!mounted) return;
          applyAuthState(initialUser, profile, null);
        })
        .catch(() => {
          if (!mounted) return;
          applyAuthState(initialUser, null, null);
        });
    } else {
      // Sin initialUser: usar getSession como fuente única inicial
      supabase.auth.getSession().then(({ data: { session }, error }) => {
        if (!mounted) return;
        if (error) {
          setAuthState((prev) => ({ ...prev, error, loading: false }));
          return;
        }
        if (session?.user) {
          fetchProfile(session.user.id)
            .then((profile) => {
              if (!mounted) return;
              applyAuthState(session.user, profile, session);
            })
            .catch(() => {
              if (!mounted) return;
              applyAuthState(session.user, null, session);
            });
        } else {
          applyAuthState(null, null, null);
        }
      });
    }

    // Timeout de seguridad (5s)
    const timeoutId = setTimeout(() => {
      if (mounted && !initialized) {
        initialized = true;
        setAuthState((prev) => ({ ...prev, loading: false }));
      }
    }, 5000);

    // Solo para eventos posteriores (SIGNED_IN, SIGNED_OUT, TOKEN_REFRESHED)
    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange(async (event, session) => {
      if (!mounted) return;
      // Ignorar INITIAL_SESSION: ya manejado por initialUser o getSession
      if (event === "INITIAL_SESSION") return;

      if (event === "SIGNED_IN" && session?.user) {
        const profile = await fetchProfile(session.user.id);
        if (!mounted) return;
        setAuthState({
          user: session.user,
          profile,
          session,
          loading: false,
          error: null,
        });
      } else if (event === "SIGNED_OUT") {
        setAuthState({
          user: null,
          profile: null,
          session: null,
          loading: false,
          error: null,
        });
      } else if (event === "TOKEN_REFRESHED" && session) {
        setAuthState((prev) => ({
          ...prev,
          session,
          user: session.user,
        }));
      }
    });

    return () => {
      mounted = false;
      clearTimeout(timeoutId);
      subscription.unsubscribe();
    };
  }, []);

  const signUp = async (
    email: string,
    password: string,
    userData?: { firstName?: string; lastName?: string; phone?: string },
  ) => {
    const supabase = createClient();
    setAuthState((prev) => ({ ...prev, loading: true, error: null }));

    try {
      const redirectUrl =
        typeof window !== "undefined"
          ? `${window.location.origin}/login`
          : `${process.env.NEXT_PUBLIC_APP_URL || "https://www.opttius.cl"}/login`;

      const { data: authData, error: authError } = await supabase.auth.signUp({
        email,
        password,
        options: {
          data: {
            first_name: userData?.firstName,
            last_name: userData?.lastName,
            phone: userData?.phone,
          },
          emailRedirectTo: redirectUrl,
        },
      });

      if (authError) {
        setAuthState((prev) => ({ ...prev, error: authError, loading: false }));
        throw authError;
      }

      setAuthState((prev) => ({ ...prev, loading: false }));
      return { data: authData, error: null };
    } catch (error) {
      const authError =
        error instanceof Error ? error : new Error("Unknown error");
      setAuthState((prev) => ({
        ...prev,
        error: authError as AuthError,
        loading: false,
      }));
      throw error;
    }
  };

  const signIn = async (email: string, password: string) => {
    const supabase = createClient();
    setAuthState((prev) => ({ ...prev, loading: true, error: null }));

    try {
      const { data, error } = await supabase.auth.signInWithPassword({
        email,
        password,
      });
      if (error) {
        setAuthState((prev) => ({ ...prev, error, loading: false }));
        return { data: null, error };
      }
      return { data, error: null };
    } catch (error) {
      appLogger.error("SignIn error:", error);
      const authError =
        error instanceof Error ? error : new Error("Unknown error");
      setAuthState((prev) => ({
        ...prev,
        error: authError as AuthError,
        loading: false,
      }));
      return { data: null, error: authError as AuthError };
    }
  };

  const signOut = async () => {
    const supabase = createClient();
    setAuthState((prev) => ({ ...prev, loading: true, error: null }));
    const { error } = await supabase.auth.signOut();
    if (error) {
      setAuthState((prev) => ({ ...prev, error, loading: false }));
      return { error };
    }
    return { error: null };
  };

  const updateProfile = async (updates: Partial<Profile>) => {
    const supabase = createClient();
    if (!authState.user) {
      throw new Error("No user logged in");
    }

    const previousProfile = authState.profile;
    const optimisticProfile = previousProfile
      ? { ...previousProfile, ...updates }
      : null;

    // Optimistic UI: update local state immediately
    if (optimisticProfile) {
      setAuthState((prev) => ({
        ...prev,
        profile: optimisticProfile as Profile,
      }));
    }

    const { data, error } = await supabase
      .from("profiles")
      .update(updates)
      .eq("id", authState.user.id)
      .select()
      .single();

    if (error) {
      // Revert on failure
      setAuthState((prev) => ({
        ...prev,
        profile: previousProfile,
      }));
      throw error;
    }

    setAuthState((prev) => ({
      ...prev,
      profile: data,
    }));

    return data;
  };

  const resetPassword = async (email: string) => {
    const supabase = createClient();
    setAuthState((prev) => ({ ...prev, loading: true, error: null }));

    try {
      const { error } = await supabase.auth.resetPasswordForEmail(email, {
        redirectTo: `${window.location.origin}/reset-password`,
      });

      if (error) {
        setAuthState((prev) => ({ ...prev, error, loading: false }));
        throw error;
      }

      setAuthState((prev) => ({ ...prev, loading: false }));
      return { error: null };
    } catch (error) {
      const authError =
        error instanceof Error ? error : new Error("Unknown error");
      setAuthState((prev) => ({
        ...prev,
        error: authError as AuthError,
        loading: false,
      }));
      throw error;
    }
  };

  const refetchProfile = async (): Promise<Profile | null> => {
    if (!authState.user) return null;
    const profile = await fetchProfile(authState.user.id);
    setAuthState((prev) => ({ ...prev, profile }));
    return profile;
  };

  return {
    ...authState,
    signUp,
    signIn,
    signOut,
    updateProfile,
    resetPassword,
    refetchProfile,
  };
}

import { useCallback, useState } from "react";

import { SYSTEM_PROMPTS } from "@/lib/ai/agent/config";
import type { LLMProvider } from "@/lib/ai/types";

export interface ChatConfig {
  provider: LLMProvider | undefined;
  model: string;
  temperature: number;
  maxTokens: number;
  maxSteps: number;
  enableToolCalling: boolean;
  enabledTools: string[];
  systemPrompt: string;
  systemPromptPreset: keyof typeof SYSTEM_PROMPTS | "custom";
  requireConfirmation: boolean;
}

const DEFAULT_CONFIG: ChatConfig = {
  provider: undefined,
  model: "",
  temperature: 0.7,
  maxTokens: 2000,
  maxSteps: 5,
  enableToolCalling: true,
  enabledTools: [],
  systemPrompt: SYSTEM_PROMPTS.default,
  systemPromptPreset: "default",
  requireConfirmation: true,
};

/**
 * Hook para gestionar la configuración del chat AI
 *
 * Proporciona estado y funciones para configurar el comportamiento del chat,
 * incluyendo proveedor, modelo, temperatura, herramientas, y prompts.
 *
 * @param initialConfig - Configuración inicial (opcional, se mergea con defaults)
 * @returns Objeto con:
 * - `config`: Configuración actual
 * - `updateConfig()`: Función para actualizar la configuración
 * - `resetConfig()`: Función para resetear a valores por defecto
 * - `setSystemPromptPreset()`: Función para cambiar el preset de prompt
 *
 * @example
 * ```typescript
 * function ChatSettings() {
 *   const { config, updateConfig, resetConfig } = useChatConfig({
 *     temperature: 0.9,
 *     maxTokens: 4000
 *   })
 *
 *   return (
 *     <div>
 *       <input
 *         type="range"
 *         value={config.temperature}
 *         onChange={(e) => updateConfig({ temperature: Number(e.target.value) })}
 *       />
 *     </div>
 *   )
 * }
 * ```
 */
export function useChatConfig(initialConfig?: Partial<ChatConfig>) {
  // Use useMemo to create initial state only once
  const initialState = useState(() => ({
    ...DEFAULT_CONFIG,
    ...initialConfig,
  }))[0];

  const [config, setConfig] = useState<ChatConfig>(initialState);

  const updateConfig = useCallback((updates: Partial<ChatConfig>) => {
    setConfig((prev) => {
      const newConfig = { ...prev, ...updates };

      if (
        updates.systemPromptPreset &&
        updates.systemPromptPreset !== "custom"
      ) {
        newConfig.systemPrompt = SYSTEM_PROMPTS[updates.systemPromptPreset];
      }

      return newConfig;
    });
  }, []);

  const setProvider = useCallback((provider: LLMProvider | undefined) => {
    setConfig((prev) => ({ ...prev, provider }));
  }, []);

  const setModel = useCallback((model: string) => {
    setConfig((prev) => ({ ...prev, model }));
  }, []);

  const setTemperature = useCallback((temperature: number) => {
    setConfig((prev) => ({
      ...prev,
      temperature: Math.max(0, Math.min(2, temperature)),
    }));
  }, []);

  const setMaxTokens = useCallback((maxTokens: number) => {
    setConfig((prev) => ({
      ...prev,
      maxTokens: Math.max(100, Math.min(32000, maxTokens)),
    }));
  }, []);

  const setMaxSteps = useCallback((maxSteps: number) => {
    setConfig((prev) => ({
      ...prev,
      maxSteps: Math.max(1, Math.min(10, maxSteps)),
    }));
  }, []);

  const setEnableToolCalling = useCallback((enable: boolean) => {
    setConfig((prev) => ({ ...prev, enableToolCalling: enable }));
  }, []);

  const toggleTool = useCallback((toolName: string) => {
    setConfig((prev) => {
      const enabledTools = prev.enabledTools.includes(toolName)
        ? prev.enabledTools.filter((t) => t !== toolName)
        : [...prev.enabledTools, toolName];
      return { ...prev, enabledTools };
    });
  }, []);

  const setEnabledTools = useCallback((tools: string[]) => {
    setConfig((prev) => ({ ...prev, enabledTools: tools }));
  }, []);

  const setSystemPrompt = useCallback((prompt: string) => {
    setConfig((prev) => ({
      ...prev,
      systemPrompt: prompt,
      systemPromptPreset: "custom",
    }));
  }, []);

  const setSystemPromptPreset = useCallback(
    (preset: keyof typeof SYSTEM_PROMPTS | "custom") => {
      setConfig((prev) => ({
        ...prev,
        systemPromptPreset: preset,
        systemPrompt:
          preset === "custom" ? prev.systemPrompt : SYSTEM_PROMPTS[preset],
      }));
    },
    [],
  );

  const setRequireConfirmation = useCallback((require: boolean) => {
    setConfig((prev) => ({ ...prev, requireConfirmation: require }));
  }, []);

  const resetConfig = useCallback(() => {
    setConfig(DEFAULT_CONFIG);
  }, []);

  const getConfigForAPI = useCallback(() => {
    // Build a clean config object, filtering out undefined/null values
    const apiConfig: {
      temperature?: number;
      maxTokens?: number;
      maxSteps?: number;
      enableToolCalling?: boolean;
      enabledTools?: string[];
      systemPrompt?: string;
      requireConfirmation?: boolean;
      provider?: string;
      model?: string;
    } = {};

    // Only include valid values
    if (typeof config.temperature === "number" && !isNaN(config.temperature)) {
      apiConfig.temperature = config.temperature;
    }
    if (
      typeof config.maxTokens === "number" &&
      !isNaN(config.maxTokens) &&
      config.maxTokens > 0
    ) {
      apiConfig.maxTokens = config.maxTokens;
    }
    if (
      typeof config.maxSteps === "number" &&
      !isNaN(config.maxSteps) &&
      config.maxSteps > 0
    ) {
      apiConfig.maxSteps = config.maxSteps;
    }
    if (typeof config.enableToolCalling === "boolean") {
      apiConfig.enableToolCalling = config.enableToolCalling;
    }
    if (Array.isArray(config.enabledTools)) {
      apiConfig.enabledTools = config.enabledTools.filter(
        (t) => typeof t === "string",
      );
    }
    if (typeof config.systemPrompt === "string" && config.systemPrompt.trim()) {
      apiConfig.systemPrompt = config.systemPrompt;
    }
    if (typeof config.requireConfirmation === "boolean") {
      apiConfig.requireConfirmation = config.requireConfirmation;
    }

    // Only include provider and model if they have values
    if (config.provider && typeof config.provider === "string") {
      apiConfig.provider = config.provider;
    }
    if (
      config.model &&
      typeof config.model === "string" &&
      config.model.trim()
    ) {
      apiConfig.model = config.model;
    }

    // Return empty object if nothing valid, or the cleaned config
    return Object.keys(apiConfig).length > 0 ? apiConfig : null;
  }, [config]);

  return {
    config,
    updateConfig,
    setProvider,
    setModel,
    setTemperature,
    setMaxTokens,
    setMaxSteps,
    setEnableToolCalling,
    toggleTool,
    setEnabledTools,
    setSystemPrompt,
    setSystemPromptPreset,
    setRequireConfirmation,
    resetConfig,
    getConfigForAPI,
  };
}

import { useCallback, useState } from "react";

import type { ToolCall } from "@/lib/ai/types";
import { appLogger } from '@/lib/logger';

interface ChatSessionConfig {
  temperature?: number;
  maxTokens?: number;
  maxSteps?: number;
  enableToolCalling?: boolean;
  enabledTools?: string[];
  systemPrompt?: string;
  requireConfirmation?: boolean;
  [key: string]: unknown;
}

interface ChatSession {
  id: string;
  title: string | null;
  provider: string;
  model: string | null;
  created_at: string;
  updated_at: string;
  config?: ChatSessionConfig | null;
  message_count?: number;
  last_message_preview?: string | null;
}

interface ChatMessage {
  id: string;
  session_id: string;
  role: "system" | "user" | "assistant" | "tool";
  content: string;
  tool_calls?: ToolCall[] | null;
  tool_results?: Array<{
    tool_call_id: string;
    result: unknown;
  }> | null;
  metadata?: Record<string, unknown> | null;
  created_at: string;
}

interface UseChatSessionReturn {
  currentSession: ChatSession | null;
  messages: ChatMessage[];
  loading: boolean;
  error: string | null;
  createSession: (
    provider: string,
    model: string,
    title?: string,
    config?: ChatSessionConfig,
  ) => Promise<ChatSession | null>;
  loadSession: (sessionId: string) => Promise<void>;
  updateSessionTitle: (sessionId: string, title: string) => Promise<void>;
  saveMessage: (
    sessionId: string,
    role: ChatMessage["role"],
    content: string,
    metadata?: Record<string, unknown>,
  ) => Promise<void>;
  clearSession: () => void;
}

export function useChatSession(): UseChatSessionReturn {
  const [currentSession, setCurrentSession] = useState<ChatSession | null>(
    null,
  );
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const createSession = useCallback(
    async (
      provider: string,
      model: string,
      title?: string,
      config?: ChatSessionConfig,
    ): Promise<ChatSession | null> => {
      try {
        setLoading(true);
        setError(null);

        // Validate inputs
        if (!provider || !model) {
          throw new Error("Provider and model are required");
        }

        const requestBody: {
          provider: string;
          model: string;
          title: string | null;
          config?: ChatSessionConfig;
        } = {
          provider: String(provider).trim(),
          model: String(model).trim(),
          title: title ? String(title).trim() : null,
        };

        // Only include config if it's valid and not null
        if (config && typeof config === "object" && config !== null) {
          try {
            // Remove any undefined values
            const cleanConfig = JSON.parse(JSON.stringify(config));
            if (Object.keys(cleanConfig).length > 0) {
              requestBody.config = cleanConfig;
            }
          } catch (e) {
            appLogger.warn("Config is not serializable, skipping:", e);
          }
        }

        const response = await fetch("/api/admin/chat/sessions", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(requestBody),
        });

        if (!response.ok) {
          const data = await response
            .json()
            .catch(() => ({ error: "Unknown error" }));
          const errorMessage =
            data.error ||
            data.details ||
            `HTTP ${response.status}: Failed to create session`;
          appLogger.error("Session creation failed:", errorMessage, data);
          throw new Error(errorMessage);
        }

        const data = await response.json();
        if (!data.session) {
          throw new Error("No session data returned from server");
        }

        const session = data.session;
        setCurrentSession(session);
        setMessages([]);
        return session;
      } catch (err) {
        const errorMessage =
          err instanceof Error ? err.message : "Failed to create session";
        appLogger.error("Error in createSession:", errorMessage, err);
        setError(errorMessage);
        return null;
      } finally {
        setLoading(false);
      }
    },
    [],
  );

  const loadSession = useCallback(async (sessionId: string) => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetch(
        `/api/admin/chat/sessions?sessionId=${sessionId}`,
      );

      if (!response.ok) {
        const data = await response.json();
        throw new Error(data.error || "Failed to load session");
      }

      const data = await response.json();
      setCurrentSession(data.session);
      setMessages(data.messages || []);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load session");
    } finally {
      setLoading(false);
    }
  }, []);

  const updateSessionTitle = useCallback(
    async (sessionId: string, title: string) => {
      try {
        setError(null);

        const response = await fetch("/api/admin/chat/sessions", {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ sessionId, title }),
        });

        if (!response.ok) {
          const data = await response.json();
          throw new Error(data.error || "Failed to update session");
        }

        const data = await response.json();
        setCurrentSession(data.session);
      } catch (err) {
        setError(
          err instanceof Error ? err.message : "Failed to update session",
        );
      }
    },
    [],
  );

  const saveMessage = useCallback(
    async (
      sessionId: string,
      role: ChatMessage["role"],
      content: string,
      metadata?: Record<string, unknown>,
    ) => {
      try {
        const response = await fetch("/api/admin/chat/messages", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            sessionId,
            role,
            content,
            metadata,
          }),
        });

        if (!response.ok) {
          const data = await response.json();
          throw new Error(data.error || "Failed to save message");
        }

        const data = await response.json();
        setMessages((prev) => [...prev, data.message]);
      } catch (err) {
        appLogger.error("Error saving message:", err);
      }
    },
    [],
  );

  const clearSession = useCallback(() => {
    setCurrentSession(null);
    setMessages([]);
    setError(null);
  }, []);

  return {
    currentSession,
    messages,
    loading,
    error,
    createSession,
    loadSession,
    updateSessionTitle,
    saveMessage,
    clearSession,
  };
}

"use client";

import { useParams, useRouter } from "next/navigation";
import { useEffect, useState } from "react";

import type { Appointment, Customer, Prescription } from "@/lib/api/services";
import { customerService } from "@/lib/api/services";
import { appLogger } from '@/lib/logger';

// Local Customer interface for the form state - extended with additional fields
export interface CustomerFormData extends Partial<Customer> {
  address_line_1?: string;
  address_line_2?: string;
  city?: string;
  state?: string;
  postal_code?: string;
  country?: string;
  date_of_birth?: string;
  gender?: string;
  medical_conditions?: string[];
  allergies?: string[];
  medications?: string[];
  medical_notes?: string;
  last_eye_exam_date?: string;
  next_eye_exam_due?: string;
  preferred_contact_method?: string;
  emergency_contact_name?: string;
  emergency_contact_phone?: string;
  insurance_provider?: string;
  insurance_policy_number?: string;
  is_active_customer?: boolean;
}

export function useCustomerDetail() {
  const router = useRouter();
  const params = useParams();
  const customerId = params.id as string;

  const [customer, setCustomer] = useState<Customer | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [expandedOrders, setExpandedOrders] = useState<Set<string>>(new Set());
  const [showCreatePrescription, setShowCreatePrescription] = useState(false);
  const [editingPrescription, setEditingPrescription] =
    useState<Prescription | null>(null);
  const [showCreateAppointment, setShowCreateAppointment] = useState(false);
  const [editingAppointment, setEditingAppointment] =
    useState<Appointment | null>(null);
  const [showCreateQuote, setShowCreateQuote] = useState(false);

  useEffect(() => {
    if (customerId) {
      fetchCustomer();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [customerId]);

  const fetchCustomer = async () => {
    try {
      setLoading(true);
      const customerData = await customerService.getCustomer(customerId);
      setCustomer(customerData);
      setError(null);
    } catch (err) {
      appLogger.error("Error fetching customer:", err);
      setError(err instanceof Error ? err.message : "Unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const toggleOrderExpansion = (orderId: string) => {
    setExpandedOrders((prev) => {
      const newSet = new Set(prev);
      if (newSet.has(orderId)) {
        newSet.delete(orderId);
      } else {
        newSet.add(orderId);
      }
      return newSet;
    });
  };

  return {
    customerId,
    customer,
    loading,
    error,
    expandedOrders,
    showCreatePrescription,
    editingPrescription,
    showCreateAppointment,
    editingAppointment,
    showCreateQuote,
    fetchCustomer,
    toggleOrderExpansion,
    setShowCreatePrescription,
    setEditingPrescription,
    setShowCreateAppointment,
    setEditingAppointment,
    setShowCreateQuote,
  };
}

import { useState } from "react";

interface UploadOptions {
  bucket: string;
  path?: string;
  maxSize?: number; // in bytes
  allowedTypes?: string[];
}

export interface UploadProgress {
  progress: number;
  status: "idle" | "uploading" | "success" | "error";
  error?: string;
  url?: string;
}

export function useFileUpload() {
  const [uploadState, setUploadState] = useState<UploadProgress>({
    progress: 0,
    status: "idle",
  });

  const uploadFile = async (
    file: File,
    options: UploadOptions,
  ): Promise<string | null> => {
    const {
      bucket,
      path,
      maxSize = 5 * 1024 * 1024, // 5MB default
      allowedTypes = ["image/jpeg", "image/png", "image/gif", "image/webp"],
    } = options;

    try {
      setUploadState({ progress: 0, status: "uploading" });

      // Validate file size
      if (file.size > maxSize) {
        throw new Error(
          `El archivo es muy grande. Tamaño máximo: ${maxSize / 1024 / 1024}MB`,
        );
      }

      // Validate file type
      if (!allowedTypes.includes(file.type)) {
        throw new Error(
          `Tipo de archivo no permitido. Tipos permitidos: ${allowedTypes.join(", ")}`,
        );
      }

      setUploadState({ progress: 10, status: "uploading" });

      // Build FormData for our API
      const formData = new FormData();
      formData.append("file", file);
      formData.append("folder", options.bucket); // Mapping bucket to folder for the API

      // Call our centralized upload API
      const response = await fetch("/api/upload", {
        method: "POST",
        body: formData,
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error || "Error al subir el archivo");
      }

      const data = await response.json();

      if (!data.url) {
        throw new Error("No se recibió la URL del archivo subido");
      }

      setUploadState({
        progress: 100,
        status: "success",
        url: data.url,
      });

      return data.url;
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : "Error desconocido";
      setUploadState({
        progress: 0,
        status: "error",
        error: errorMessage,
      });
      return null;
    }
  };

  const uploadAvatar = async (file: File): Promise<string | null> => {
    return uploadFile(file, {
      bucket: "avatars",
      path: "avatar",
      maxSize: 5 * 1024 * 1024, // 5MB
      allowedTypes: ["image/jpeg", "image/png", "image/gif", "image/webp"],
    });
  };

  const resetUploadState = () => {
    setUploadState({ progress: 0, status: "idle" });
  };

  return {
    uploadState,
    uploadFile,
    uploadAvatar,
    resetUploadState,
  };
}

// Utility function to create optimized image URLs
export function getOptimizedImageUrl(
  url: string,
  width?: number,
  height?: number,
): string {
  if (!url) return url;

  // If it's a Supabase storage URL, we can add transformation parameters
  if (url.includes("supabase.co/storage")) {
    const transformParams = new URLSearchParams();
    if (width) transformParams.set("width", width.toString());
    if (height) transformParams.set("height", height.toString());
    transformParams.set("quality", "80");
    transformParams.set("format", "webp");

    return transformParams.toString()
      ? `${url}?${transformParams.toString()}`
      : url;
  }

  return url;
}

/**
 * Generic Form Hook
 *
 * Hook genérico para manejo estandarizado de formularios usando react-hook-form y zod.
 * Proporciona una interfaz consistente para manejar estado, validación y submission de formularios.
 *
 * @module hooks/useForm
 */

import { zodResolver } from "@hookform/resolvers/zod";
import { useState } from "react";
import {
  FieldErrors,
  Path,
  useForm as useReactHookForm,
  UseFormReturn,
} from "react-hook-form";
import { z } from "zod";

import { handleApiError } from "@/lib/api/services";

/**
 * Opciones para el hook useForm
 */
export interface UseFormOptions<
  T extends z.ZodType<unknown, unknown, unknown>,
  R = void,
> {
  /** Valores iniciales del formulario */
  defaultValues: z.infer<T>;
  /** Esquema de validación Zod */
  validationSchema?: T;
  /** Función de submit del formulario */
  onSubmit: (values: z.infer<T>) => Promise<R>;
  /** Callback cuando el submit es exitoso */
  onSuccess?: (result: R) => void;
  /** Callback cuando hay un error */
  onError?: (error: Error) => void;
  /** Contexto para manejo de errores */
  errorContext?: string;
  /** Si debe mostrar notificaciones de error automáticamente */
  showErrors?: boolean;
  /** Si debe mostrar notificaciones de éxito automáticamente */
  showSuccess?: boolean;
  /** Mensaje de éxito personalizado */
  successMessage?: string | ((values: z.infer<T>) => string);
}

/**
 * Return type del hook useForm
 */
export interface UseFormReturnExtended<
  T extends z.ZodType<unknown, unknown, unknown>,
  R = void,
> {
  /** Si el formulario está siendo enviado */
  isSubmitting: boolean;
  /** Error general del formulario */
  formError: string | null;
  /** Función para manejar el submit del formulario */
  handleSubmit: (e?: React.FormEvent) => Promise<void>;
  /** Función para resetear el formulario */
  resetForm: () => void;
  /** Función para setear valores específicos */
  setFieldValue: (field: keyof z.infer<T>, value: unknown) => void;
  /** Función para setear múltiples valores */
  setFieldValues: (values: Partial<z.infer<T>>) => void;
  /** Valores actuales del formulario */
  values: z.infer<T>;
  /** Errores del formulario */
  errors: FieldErrors<z.infer<T>>;
  /** Función register de react-hook-form */
  register: UseFormReturn<z.infer<T>>["register"];
  /** Función setValue de react-hook-form */
  setValue: UseFormReturn<z.infer<T>>["setValue"];
  /** Función getValues de react-hook-form */
  getValues: UseFormReturn<z.infer<T>>["getValues"];
  /** Función trigger de react-hook-form */
  trigger: UseFormReturn<z.infer<T>>["trigger"];
  /** Estado del formulario */
  formState: UseFormReturn<z.infer<T>>["formState"];
  /** Función reset de react-hook-form */
  reset: UseFormReturn<z.infer<T>>["reset"];
  /** Función clearErrors de react-hook-form */
  clearErrors: UseFormReturn<z.infer<T>>["clearErrors"];
  /** Función setError de react-hook-form */
  setError: UseFormReturn<z.infer<T>>["setError"];
  /** Función watch de react-hook-form */
  watch: UseFormReturn<z.infer<T>>["watch"];
  /** Función control de react-hook-form */
  control: UseFormReturn<z.infer<T>>["control"];
}

/** Generic form hook using react-hook-form + zod */
export function useForm<
  T extends z.ZodType<unknown, unknown, unknown>,
  R = void,
>(options: UseFormOptions<T, R>): UseFormReturnExtended<T, R> {
  const {
    defaultValues,
    validationSchema,
    onSubmit,
    onSuccess,
    onError,
    errorContext = "Form",
    showErrors = true,
    showSuccess = false,
    successMessage,
  } = options;

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);

  // Configurar react-hook-form
  const reactHookForm = useReactHookForm<z.infer<T>>({
    defaultValues,
    resolver: validationSchema ? zodResolver(validationSchema) : undefined,
    mode: "onBlur", // Validar cuando el campo pierde el foco
    reValidateMode: "onBlur",
  });

  /**
   * Maneja el submit del formulario
   */
  const handleSubmit = async (e?: React.FormEvent) => {
    if (e) {
      e.preventDefault();
    }

    setFormError(null);

    // Validar el formulario
    const isValid = await reactHookForm.trigger();
    if (!isValid) {
      const errors = reactHookForm.formState.errors;
      const firstErrorKey = Object.keys(errors)[0] as keyof typeof errors;
      const firstError = errors[firstErrorKey];
      const message =
        firstError && typeof firstError === "object" && "message" in firstError
          ? String(firstError.message)
          : "Por favor corrige los errores del formulario";
      const { error: notifyError } = await import("@/lib/api/services");
      notifyError(message);
      return;
    }

    setIsSubmitting(true);

    try {
      const values = reactHookForm.getValues();
      const result = await onSubmit(values);

      // Resetear el formulario después de submit exitoso
      reactHookForm.reset(defaultValues);

      // Mostrar mensaje de éxito si está configurado
      if (showSuccess && successMessage) {
        const message =
          typeof successMessage === "function"
            ? successMessage(values)
            : successMessage;
        // Importar notificationService dinámicamente para evitar dependencia circular
        const { success } = await import("@/lib/api/services");
        success(message);
      }

      // Callback de éxito
      if (onSuccess) {
        onSuccess(result);
      }
    } catch (error) {
      // Manejar el error
      if (showErrors) {
        handleApiError(error, errorContext);
      }

      // Setear error del formulario
      const errorMessage =
        error instanceof Error ? error.message : "Error desconocido";
      setFormError(errorMessage);

      // Callback de error
      if (onError && error instanceof Error) {
        onError(error);
      }
    } finally {
      setIsSubmitting(false);
    }
  };

  /**
   * Resetea el formulario a los valores iniciales
   */
  const resetForm = () => {
    reactHookForm.reset(defaultValues);
    setFormError(null);
  };

  /**
   * Setea el valor de un campo específico
   */
  const setFieldValue = (field: keyof z.infer<T>, value: unknown) => {
    reactHookForm.setValue(field as Path<z.infer<T>>, value);
    // Limpiar error del campo
    reactHookForm.clearErrors(field as Path<z.infer<T>>);
  };

  /**
   * Setea múltiples valores del formulario
   */
  const setFieldValues = (values: Partial<z.infer<T>>) => {
    Object.entries(values).forEach(([field, value]) => {
      reactHookForm.setValue(field as Path<z.infer<T>>, value);
      reactHookForm.clearErrors(field as Path<z.infer<T>>);
    });
  };

  return {
    isSubmitting,
    formError,
    handleSubmit,
    resetForm,
    setFieldValue,
    setFieldValues,
    values: reactHookForm.watch(),
    errors: reactHookForm.formState.errors,
    register: reactHookForm.register,
    setValue: reactHookForm.setValue,
    getValues: reactHookForm.getValues,
    trigger: reactHookForm.trigger,
    formState: reactHookForm.formState,
    reset: reactHookForm.reset,
    clearErrors: reactHookForm.clearErrors,
    setError: reactHookForm.setError,
    watch: reactHookForm.watch,
    control: reactHookForm.control,
  };
}

export type {
  UseFormOptions as UseFormOptionsBase,
  UseFormReturnExtended as UseFormReturnExtendedBase,
};

// ponytail: convenience wrapper, keeps 3 consumers from breaking
export function useFormSimple<T extends Record<string, unknown>, R = void>(
  defaultValues: T,
  onSubmit: (values: T) => Promise<R>,
  options?: Partial<
    Omit<
      UseFormOptions<z.ZodType<unknown, unknown, unknown>, R>,
      "defaultValues" | "onSubmit" | "validationSchema"
    >
  >,
) {
  return useForm({ defaultValues, onSubmit, ...options });
}

"use client";

import { useRouter } from "next/navigation";
import { useEffect, useRef, useState } from "react";

/**
 * Opciones para el hook useFormProtection
 *
 * @property {boolean} [enabled=true] - Si la protección está habilitada
 * @property {string} [message] - Mensaje a mostrar en la confirmación
 * @property {() => void} [onBeforeUnload] - Callback antes de cerrar/refrescar la página
 */
interface UseFormProtectionOptions {
  enabled?: boolean;
  message?: string;
  onBeforeUnload?: () => void;
}

/**
 * Hook para proteger formularios contra navegación accidental o refresh de página
 * cuando hay cambios sin guardar
 *
 * Este hook intercepta:
 * - Cierre/refresh del navegador (beforeunload)
 * - Navegación programática (router.push/replace)
 * - Navegación por Link de Next.js
 *
 * @param hasUnsavedChanges - Si hay cambios sin guardar en el formulario
 * @param options - Opciones de configuración
 * @returns Objeto con estado y funciones de control:
 * - `isNavigating`: Si se está navegando actualmente
 * - `allowNavigation()`: Función para permitir navegación programáticamente
 *
 * @example
 * ```typescript
 * function MyForm() {
 *   const [hasChanges, setHasChanges] = useState(false)
 *   const { allowNavigation } = useFormProtection(hasChanges)
 *
 *   const handleSave = async () => {
 *     await saveData()
 *     allowNavigation() // Permitir navegación después de guardar
 *     router.push('/success')
 *   }
 * }
 * ```
 */
export function useFormProtection(
  hasUnsavedChanges: boolean,
  options: UseFormProtectionOptions = {},
) {
  const {
    enabled = true,
    message = "Tienes cambios sin guardar. ¿Estás seguro de que quieres salir?",
    onBeforeUnload,
  } = options;

  const router = useRouter();
  const [isNavigating, setIsNavigating] = useState(false);
  const originalPush = useRef(router.push);
  const originalReplace = useRef(router.replace);

  useEffect(() => {
    if (!enabled || !hasUnsavedChanges) {
      return;
    }

    // Prevent browser refresh/close with unsaved changes
    const handleBeforeUnload = (e: BeforeUnloadEvent) => {
      e.preventDefault();
      e.returnValue = message;
      onBeforeUnload?.();
      return message;
    };

    // Prevent programmatic navigation with unsaved changes
    const preventNavigation = (url: string) => {
      if (hasUnsavedChanges && !isNavigating) {
        const confirmLeave = window.confirm(message);
        if (!confirmLeave) {
          return false;
        }
      }
      setIsNavigating(true);
      return true;
    };

    // Override router methods to add confirmation
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    router.push = ((url: string, ...args: any[]) => {
      if (preventNavigation(url)) {
        return originalPush.current.call(router, url, ...args);
      }
      return Promise.resolve(false);
    }) as typeof router.push;

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    router.replace = ((url: string, ...args: any[]) => {
      if (preventNavigation(url)) {
        return originalReplace.current.call(router, url, ...args);
      }
      return Promise.resolve(false);
    }) as typeof router.replace;

    // Add event listener for browser navigation
    window.addEventListener("beforeunload", handleBeforeUnload);

    // Cleanup function
    return () => {
      window.removeEventListener("beforeunload", handleBeforeUnload);
      // Restore original router methods
      router.push = originalPush.current;
      router.replace = originalReplace.current;
      setIsNavigating(false);
    };
  }, [
    enabled,
    hasUnsavedChanges,
    message,
    onBeforeUnload,
    router,
    isNavigating,
  ]);

  // Method to manually allow navigation (e.g., after successful save)
  const allowNavigation = () => {
    setIsNavigating(true);
  };

  // Method to block navigation again
  const blockNavigation = () => {
    setIsNavigating(false);
  };

  return {
    allowNavigation,
    blockNavigation,
    isNavigating,
  };
}

/**
 * Simple hook for form state tracking with automatic protection
 */
export function useProtectedForm<T extends Record<string, unknown>>(
  initialData: T,
) {
  const [formData, setFormData] = useState<T>(initialData);
  const [originalData] = useState<T>(initialData);
  const [isSaving, setIsSaving] = useState(false);

  // Check if form has changes
  const hasChanges = JSON.stringify(formData) !== JSON.stringify(originalData);

  // Form protection
  const { allowNavigation, blockNavigation } = useFormProtection(
    hasChanges && !isSaving,
    {
      message:
        "Tienes cambios sin guardar en este formulario. ¿Estás seguro de que quieres salir?",
    },
  );

  // Update form data
  const updateFormData = (updates: Partial<T>) => {
    setFormData((prev) => ({ ...prev, ...updates }));
  };

  // Reset form to original state
  const resetForm = () => {
    setFormData(originalData);
    blockNavigation();
  };

  // Mark form as saved (allows navigation)
  const markAsSaved = () => {
    setIsSaving(false);
    allowNavigation();
  };

  // Mark form as saving
  const markAsSaving = () => {
    setIsSaving(true);
    allowNavigation(); // Allow navigation during save
  };

  return {
    formData,
    setFormData,
    updateFormData,
    resetForm,
    hasChanges,
    isSaving,
    markAsSaved,
    markAsSaving,
  };
}

"use client";

import { useEffect, useState } from "react";

/**
 * Hook para detectar el breakpoint actual y tipo de dispositivo
 *
 * Proporciona estado reactivo para responsive design:
 * - isMobile: < 1024px (para lógica de navegación móvil)
 * - isTablet: 640px - 1023px
 * - isDesktop: >= 1024px
 * - isTouch: dispositivo táctil
 * - breakpoint: breakpoint actual
 *
 * @returns Objeto con estados de viewport
 *
 * @example
 * ```typescript
 * function MyComponent() {
 *   const { isMobile, isDesktop, breakpoint } = useMobileView()
 *
 *   if (isMobile) {
 *     // Mostrar bottom nav
 *   }
 * }
 * ```
 */
export function useMobileView() {
  const [viewportState, setViewportState] = useState({
    isMobile: false,
    isTablet: false,
    isDesktop: true,
    isTouch: false,
    breakpoint: "xl" as "xs" | "sm" | "md" | "lg" | "xl" | "2xl",
    width: 0,
  });

  useEffect(() => {
    // Función para determinar el breakpoint actual
    const getBreakpoint = (width: number): typeof viewportState.breakpoint => {
      if (width < 640) return "xs";
      if (width < 768) return "sm";
      if (width < 1024) return "md";
      if (width < 1280) return "lg";
      if (width < 1536) return "xl";
      return "2xl";
    };

    // Función para detectar si es dispositivo táctil
    const detectTouch = (): boolean => {
      if (typeof window === "undefined") return false;
      return (
        "ontouchstart" in window ||
        navigator.maxTouchPoints > 0 ||
        (navigator as Navigator & { msMaxTouchPoints?: number })
          .msMaxTouchPoints > 0
      );
    };

    // Actualizar estado
    const updateViewport = () => {
      const width = window.innerWidth;
      const breakpoint = getBreakpoint(width);

      setViewportState({
        isMobile: width < 1024, // lg breakpoint de Tailwind
        isTablet: width >= 640 && width < 1024,
        isDesktop: width >= 1024,
        isTouch: detectTouch(),
        breakpoint,
        width,
      });
    };

    // Ejecutar inicial
    updateViewport();

    // Listener para resize
    window.addEventListener("resize", updateViewport);

    // Cleanup
    return () => window.removeEventListener("resize", updateViewport);
  }, []);

  return viewportState;
}

/**
 * Hook para detectar si el viewport es menor que un breakpoint específico
 *
 * @param maxBreakpoint - Breakpoint máximo (exclusivo)
 * @returns true si el viewport es menor que el breakpoint especificado
 *
 * @example
 * ```typescript
 * function MyComponent() {
 *   const isSmall = useBreakpoint("md") // true si < 768px
 * }
 * ```
 */
export function useBreakpoint(
  maxBreakpoint: "xs" | "sm" | "md" | "lg" | "xl" | "2xl",
) {
  const { isMobile, width } = useMobileView();

  const breakpointValues: Record<string, number> = {
    xs: 640,
    sm: 768,
    md: 1024,
    lg: 1280,
    xl: 1536,
    "2xl": 9999,
  };

  return width < breakpointValues[maxBreakpoint];
}

/**
 * Hook para detectar cambio de orientación en dispositivos móviles
 *
 * @returns "portrait" | "landscape"
 *
 * @example
 * ```typescript
 * function MyComponent() {
 *   const orientation = useOrientation()
 *   // Ajustar layout según orientación
 * }
 * ```
 */
export function useOrientation() {
  const [orientation, setOrientation] = useState<"portrait" | "landscape">(
    "portrait",
  );

  useEffect(() => {
    if (typeof window === "undefined") return;

    const checkOrientation = () => {
      setOrientation(
        window.innerHeight > window.innerWidth ? "portrait" : "landscape",
      );
    };

    checkOrientation();
    window.addEventListener("resize", checkOrientation);

    return () => window.removeEventListener("resize", checkOrientation);
  }, []);

  return orientation;
}

"use client";

import { useQueryClient } from "@tanstack/react-query";
import { useEffect, useRef } from "react";

/** Minimal shape for prescription/customer used by POS insights refresh */
type PrescriptionLike = { id?: unknown };
type CustomerLike = { id?: unknown; name?: unknown; rut?: unknown };

/**
 * Hook to trigger POS insights refresh when prescription or customer changes.
 * Used in POS page to generate contextual insights (e.g. lens recommendations).
 */
export function usePosInsightsRefresh(
  selectedPrescription: PrescriptionLike | null,
  selectedCustomer: CustomerLike | null,
  options?: { debounceMs?: number; enabled?: boolean },
) {
  const queryClient = useQueryClient();
  const debounceMs = options?.debounceMs ?? 1500;
  const enabled = options?.enabled ?? true;
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const prescriptionIdRef = useRef<string | null>(null);
  const customerIdRef = useRef<string | null>(null);

  useEffect(() => {
    if (!enabled) return;

    const presId =
      selectedPrescription && "id" in selectedPrescription
        ? String(selectedPrescription.id)
        : null;
    const custId =
      selectedCustomer && "id" in selectedCustomer
        ? String(selectedCustomer.id)
        : null;

    if (!presId && !custId) return;

    if (
      prescriptionIdRef.current === presId &&
      customerIdRef.current === custId
    ) {
      return;
    }
    prescriptionIdRef.current = presId;
    customerIdRef.current = custId;

    timeoutRef.current = setTimeout(async () => {
      try {
        const posContext = {
          prescription: selectedPrescription
            ? { ...selectedPrescription }
            : undefined,
          customerHistory: selectedCustomer
            ? {
                id: selectedCustomer.id,
                name: selectedCustomer.name,
                rut: selectedCustomer.rut,
              }
            : undefined,
        };

        const prepareRes = await fetch("/api/ai/insights/prepare-data", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            section: "pos",
            posContext,
          }),
        });

        if (!prepareRes.ok) return;

        const { data } = await prepareRes.json();

        const generateRes = await fetch("/api/ai/insights/generate", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            section: "pos",
            data,
            forceRegenerate: true,
          }),
        });

        if (generateRes.ok) {
          queryClient.invalidateQueries({ queryKey: ["ai-insights", "pos"] });
        }
      } catch {
        // Silently ignore - insights refresh is non-critical
      }
    }, debounceMs);

    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, [
    selectedPrescription,
    selectedCustomer,
    enabled,
    debounceMs,
    queryClient,
  ]);
}

"use client";

import { useParams, useRouter } from "next/navigation";
import { useCallback, useEffect, useRef, useState } from "react";
import { toast } from "sonner";

import { useBranch } from "@/hooks/useBranch";
import { quoteService } from "@/lib/api/services";
import { appLogger } from '@/lib/logger';

import { buildQuotePrintContent } from "./printTemplate";
import type { Quote } from "./types";

export type { Quote };

export function useQuote() {
  const router = useRouter();
  const params = useParams();
  const quoteId = params.id as string;
  const { currentBranchId, isSuperAdmin } = useBranch();

  const [quote, setQuote] = useState<Quote | null>(null);
  const [loading, setLoading] = useState(true);
  const [loadingToPos, setLoadingToPos] = useState(false);
  const [sending, setSending] = useState(false);
  const [showSendDialog, setShowSendDialog] = useState(false);
  const [sendEmail, setSendEmail] = useState("");
  const printRef = useRef<HTMLDivElement>(null);

  const getCustomerId = (q: Quote | null): string => {
    if (!q) return "N/A";
    if (typeof q.customer === "object" && q.customer !== null)
      return q.customer.id ?? "N/A";
    return "N/A";
  };

  const fetchQuote = async () => {
    try {
      setLoading(true);
      const headers: HeadersInit = { "Content-Type": "application/json" };
      if (currentBranchId) {
        headers["x-branch-id"] = currentBranchId;
      } else if (isSuperAdmin) {
        headers["x-branch-id"] = "global";
      }
      const quoteResult = await quoteService.getQuote(quoteId);
      setQuote(quoteResult as unknown as Quote | null);
    } catch (error) {
      appLogger.error("Error fetching quote:", error);
      toast.error("Error al cargar el presupuesto");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (quoteId) fetchQuote();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [quoteId, currentBranchId]);

  const handleLoadToPOS = async () => {
    if (!quote) return;
    setLoadingToPos(true);
    try {
      router.push(`/admin/pos?quoteId=${quoteId}`);
    } catch (error: unknown) {
      appLogger.error("Error loading quote to POS:", error);
      toast.error("Error al cargar presupuesto al POS");
    } finally {
      setLoadingToPos(false);
    }
  };

  const handlePrint = useCallback(() => {
    if (!quote) return;
    const printWindow = window.open("", "_blank");
    if (!printWindow) {
      toast.error("Por favor, permite ventanas emergentes para imprimir");
      return;
    }
    printWindow.document.write(buildQuotePrintContent(quote));
    printWindow.document.close();
    setTimeout(() => {
      printWindow.print();
      printWindow.onafterprint = () => printWindow.close();
    }, 250);
  }, [quote]);

  const handleSendQuote = async () => {
    if (!quote) return;
    const emailToSend = quote.customer?.email || sendEmail;
    if (!emailToSend || !emailToSend.includes("@")) {
      toast.error("Por favor, ingresa un email válido");
      return;
    }
    setSending(true);
    try {
      await quoteService.sendQuote(quoteId, emailToSend);
      toast.success(`Presupuesto enviado exitosamente a ${emailToSend}`);
      setShowSendDialog(false);
      setSendEmail("");
      fetchQuote();
    } catch (error: unknown) {
      const err = error as { message?: string };
      toast.error(err.message || "Error al enviar presupuesto");
    } finally {
      setSending(false);
    }
  };

  useEffect(() => {
    if (quote?.customer?.email && !sendEmail)
      setSendEmail(quote.customer.email);
  }, [quote, sendEmail]);

  return {
    quote,
    loading,
    loadingToPos,
    sending,
    showSendDialog,
    sendEmail,
    printRef,
    getCustomerId,
    fetchQuote,
    handleLoadToPOS,
    handlePrint,
    handleSendQuote,
    setShowSendDialog,
    setSendEmail,
    router,
  };
}

