import { useEffect, useState } from "react";

import { useAuthContext } from "@/contexts/AuthContext";
import { appLogger } from '@/lib/logger';

/**
 * Hook para verificar si el usuario actual tiene rol root o dev
 * Útil para mostrar/ocultar funcionalidades de gestión SaaS
 * Usa el API de check-status para evitar problemas con RLS
 */
export function useRoot() {
  const { user } = useAuthContext();
  const [isRoot, setIsRoot] = useState<boolean>(false);
  const [isLoading, setIsLoading] = useState<boolean>(true);

  useEffect(() => {
    const checkRootStatus = async () => {
      if (!user) {
        setIsRoot(false);
        setIsLoading(false);
        return;
      }

      try {
        // Usar el API de check-status que ya maneja RLS correctamente
        const response = await fetch("/api/admin/check-status");

        if (!response.ok) {
          setIsRoot(false);
          setIsLoading(false);
          return;
        }

        const data = await response.json();

        // Verificar si el usuario es root/dev desde la respuesta del API
        const isRootUser = data.organization?.isRootUser || false;
        setIsRoot(isRootUser);
      } catch (error) {
        appLogger.error("Error checking root status:", error);
        setIsRoot(false);
      } finally {
        setIsLoading(false);
      }
    };

    checkRootStatus();
  }, [user?.id]);

  return { isRoot, isLoading };
}

import { useCallback, useEffect, useState } from "react";

import { useDebounce } from "./useDebounce";

export type SlugValidationState = {
  isValidating: boolean;
  isAvailable: boolean | null;
  error: string | null;
};

/**
 * Hook para validar disponibilidad de slug en tiempo real
 *
 * @param slug - El slug a validar
 * @param debounceMs - Tiempo de espera antes de validar (default: 500ms)
 * @returns Estado de validación del slug
 */
export function useSlugValidation(
  slug: string,
  debounceMs: number = 500,
): SlugValidationState {
  const [isValidating, setIsValidating] = useState(false);
  const [isAvailable, setIsAvailable] = useState<boolean | null>(null);
  const [error, setError] = useState<string | null>(null);

  const debouncedSlug = useDebounce(slug, debounceMs);

  const validateSlug = useCallback(async (slugToValidate: string) => {
    // No validar si el slug está vacío o es muy corto
    if (!slugToValidate || slugToValidate.length < 2) {
      setIsAvailable(null);
      setIsValidating(false);
      setError(null);
      return;
    }

    setIsValidating(true);
    setError(null);

    try {
      const response = await fetch(
        `/api/admin/organizations/check-slug?slug=${encodeURIComponent(slugToValidate)}`,
      );

      const data = await response.json();

      if (!response.ok) {
        // Si hay un error de validación (400), el slug no es válido
        if (response.status === 400) {
          setIsAvailable(false);
          setError(data.error || "Formato de slug inválido");
        } else {
          setError("Error al verificar disponibilidad");
          setIsAvailable(null);
        }
      } else {
        setIsAvailable(data.available);
        if (!data.available) {
          setError("Ese identificador ya está en uso. Elige otro.");
        } else {
          setError(null);
        }
      }
    } catch (err) {
      setError("Error al verificar disponibilidad");
      setIsAvailable(null);
    } finally {
      setIsValidating(false);
    }
  }, []);

  useEffect(() => {
    validateSlug(debouncedSlug);
  }, [debouncedSlug, validateSlug]);

  return {
    isValidating,
    isAvailable,
    error,
  };
}

"use client";

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useCallback } from "react";

import { TOUR_STEPS } from "@/lib/onboarding/tour-config";

export interface TourProgress {
  status: "not_started" | "in_progress" | "completed" | "disabled";
  current_step: number;
  completed_steps: number[];
  skip_on_next_login: boolean;
  started_at?: string;
  completed_at?: string;
  last_accessed_at?: string;
}

export function useTour() {
  const queryClient = useQueryClient();

  // Obtener progreso del tour - optimizado para carga rápida
  const { data: progress, isLoading } = useQuery<TourProgress>({
    queryKey: ["tour-progress"],
    queryFn: async () => {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 2000); // Timeout reducido a 2 segundos

      try {
        const res = await fetch("/api/onboarding/tour", {
          signal: controller.signal,
        });
        clearTimeout(timeoutId);

        if (!res.ok) {
          // Si no hay progreso, retornar estado inicial
          if (res.status === 404 || res.status === 401) {
            return {
              status: "not_started" as const,
              current_step: 0,
              completed_steps: [],
              skip_on_next_login: false,
            };
          }
          throw new Error("Failed to fetch tour progress");
        }
        return res.json();
      } catch (error) {
        clearTimeout(timeoutId);
        // En caso de error, retornar estado inicial para no bloquear (sin logs en producción)
        return {
          status: "not_started" as const,
          current_step: 0,
          completed_steps: [],
          skip_on_next_login: false,
        };
      }
    },
    staleTime: 1000 * 60 * 5, // 5 minutes
    retry: 0, // No reintentar para evitar delays
    refetchOnWindowFocus: false,
    refetchOnMount: false,
    refetchOnReconnect: false, // No refetch al reconectar
    gcTime: 1000 * 60 * 10, // Mantener en cache por 10 minutos
  });

  const startTour = useMutation({
    mutationFn: async () => {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 2000);
      try {
        const res = await fetch("/api/onboarding/tour", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          signal: controller.signal,
          body: JSON.stringify({ action: "start" }),
        });
        clearTimeout(timeoutId);
        if (!res.ok) {
          const err = await res
            .json()
            .catch(() => ({ error: "Failed to start tour" }));
          throw new Error(err.error || "Failed to start tour");
        }
        return res.json();
      } catch (error) {
        clearTimeout(timeoutId);
        if (error instanceof Error && error.name === "AbortError") {
          const state = {
            status: "in_progress" as const,
            current_step: 0,
            completed_steps: [],
            skip_on_next_login: false,
          };
          queryClient.setQueryData(["tour-progress"], state);
          return state;
        }
        throw error;
      }
    },
    onSuccess: () =>
      queryClient.invalidateQueries({ queryKey: ["tour-progress"] }),
  });

  // Completar paso - optimizado con actualización optimista
  const completeStep = useMutation({
    mutationFn: async (stepIndex: number) => {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 2000);

      try {
        const res = await fetch(`/api/onboarding/tour/${stepIndex}`, {
          method: "POST",
          signal: controller.signal,
        });
        clearTimeout(timeoutId);

        if (!res.ok) {
          const error = await res
            .json()
            .catch(() => ({ error: "Failed to complete step" }));
          throw new Error(error.error || "Failed to complete step");
        }
        return res.json();
      } catch (error) {
        clearTimeout(timeoutId);
        // Actualización optimista: avanzar el paso localmente incluso si falla la API
        if (error instanceof Error && error.name === "AbortError") {
          const currentProgress = queryClient.getQueryData<TourProgress>([
            "tour-progress",
          ]);
          if (currentProgress) {
            const newProgress: TourProgress = {
              ...currentProgress,
              current_step: stepIndex + 1,
              completed_steps: [
                ...(currentProgress.completed_steps || []),
                stepIndex,
              ],
            };
            queryClient.setQueryData(["tour-progress"], newProgress);
            return newProgress;
          }
        }
        throw error;
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["tour-progress"] });
    },
  });

  const completeTour = useMutation({
    mutationFn: () => tourApiCall("complete"),
    onSuccess: () =>
      queryClient.invalidateQueries({ queryKey: ["tour-progress"] }),
  });

  const tourApiCall = useCallback(
    async (action: string, body?: Record<string, unknown>) => {
      const res = await fetch("/api/onboarding/tour", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body ?? { action }),
      });
      if (!res.ok) {
        const err = await res
          .json()
          .catch(() => ({ error: `Failed to ${action} tour` }));
        throw new Error(err.error || `Failed to ${action} tour`);
      }
      return res.json();
    },
    [],
  );

  // Saltar tour - actualización inmediata sin esperar API
  const skipTour = useMutation({
    mutationFn: async () => {
      const disabledState = {
        status: "disabled" as const,
        current_step: 0,
        completed_steps: [],
        skip_on_next_login: true,
      };
      queryClient.setQueryData(["tour-progress"], disabledState);
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 1000);
      try {
        const res = await fetch("/api/onboarding/tour", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          signal: controller.signal,
          body: JSON.stringify({ action: "skip" }),
        });
        clearTimeout(timeoutId);
        if (res.ok) {
          const data = await res.json();
          queryClient.setQueryData(["tour-progress"], {
            ...data,
            status: "disabled" as const,
          });
        }
      } catch {
        clearTimeout(timeoutId);
      }
      return disabledState;
    },
  });

  const restartTour = useMutation({
    mutationFn: () => tourApiCall("restart"),
    onSuccess: () =>
      queryClient.invalidateQueries({ queryKey: ["tour-progress"] }),
  });

  const skipTourImmediate = useCallback(() => {
    const disabledState = {
      status: "disabled" as const,
      current_step: 0,
      completed_steps: [],
      skip_on_next_login: true,
    };
    queryClient.setQueryData(["tour-progress"], disabledState);
    queryClient.cancelQueries({ queryKey: ["tour-progress"] });
    skipTour.mutate(undefined, {
      onSuccess: (data) =>
        queryClient.setQueryData(["tour-progress"], {
          ...data,
          status: "disabled" as const,
        }),
    });
  }, [skipTour, queryClient]);

  const goToStep = useCallback(
    (stepIndex: number) => {
      if (stepIndex < 0 || stepIndex >= TOUR_STEPS.length) return;
      const currentProgress = queryClient.getQueryData<TourProgress>([
        "tour-progress",
      ]);
      if (currentProgress?.status === "in_progress") {
        queryClient.setQueryData(["tour-progress"], {
          ...currentProgress,
          current_step: stepIndex,
        });
      }
    },
    [queryClient],
  );

  const currentStep = progress?.current_step ?? 0;
  const totalSteps = TOUR_STEPS.length;
  const isActive = progress?.status === "in_progress";
  const isCompleted = progress?.status === "completed";
  const isDisabled = progress?.status === "disabled";
  const isNotStarted = progress?.status === "not_started" || !progress;

  return {
    progress,
    isLoading,
    currentStep,
    totalSteps,
    isActive,
    isCompleted,
    isDisabled,
    isNotStarted,
    startTour: startTour.mutate,
    completeStep: completeStep.mutate,
    completeTour: completeTour.mutate,
    skipTour: skipTourImmediate,
    restartTour: restartTour.mutate,
    goToStep,
    isStarting: startTour.isPending,
    isCompleting: completeTour.isPending,
    isSkipping: skipTour.isPending,
    isRestarting: restartTour.isPending,
  };
}

"use client";

import { useParams, useRouter } from "next/navigation";
import { useCallback, useEffect, useState } from "react";
import { toast } from "sonner";

import { appLogger } from '@/lib/logger';

import { buildPrintContent } from "./printTemplate";
import type { DeliveryError, LabInfo, StatusHistory, WorkOrder } from "./types";

export type { DeliveryError, LabInfo, StatusHistory, WorkOrder };

export function useWorkOrder() {
  const router = useRouter();
  const params = useParams();
  const workOrderId = params.id as string;

  const [workOrder, setWorkOrder] = useState<WorkOrder | null>(null);
  const [statusHistory, setStatusHistory] = useState<StatusHistory[]>([]);
  const [loading, setLoading] = useState(true);
  const [updatingStatus, setUpdatingStatus] = useState(false);
  const [showStatusDialog, setShowStatusDialog] = useState(false);
  const [newStatus, setNewStatus] = useState("");
  const [statusDialogOpenedFromTimeline, setStatusDialogOpenedFromTimeline] =
    useState(false);
  const [statusNotes, setStatusNotes] = useState("");
  const [labInfo, setLabInfo] = useState<LabInfo>({
    lab_name: "",
    lab_contact: "",
    lab_order_number: "",
    lab_estimated_delivery_date: "",
  });
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [deliveryDialogOpen, setDeliveryDialogOpen] = useState(false);
  const [delivering, setDelivering] = useState(false);
  const [deliveryError, setDeliveryError] = useState<DeliveryError | null>(
    null,
  );
  const [orgName, setOrgName] = useState<string>("Opttius");

  useEffect(() => {
    if (workOrderId) fetchWorkOrder();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [workOrderId]);

  useEffect(() => {
    fetch("/api/admin/organizations/current")
      .then((r) => (r.ok ? r.json() : null))
      .then((data) => {
        if (data?.organization?.name) setOrgName(data.organization.name);
      })
      .catch(() => {});
  }, []);

  const fetchWorkOrder = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/admin/work-orders/${workOrderId}`);
      if (!response.ok) throw new Error("Failed to fetch work order");
      const data = await response.json();
      setWorkOrder(data.workOrder);
      setStatusHistory(data.statusHistory || []);
      if (data.workOrder) {
        setLabInfo({
          lab_name: data.workOrder.lab_name || "",
          lab_contact: data.workOrder.lab_contact || "",
          lab_order_number: data.workOrder.lab_order_number || "",
          lab_estimated_delivery_date:
            data.workOrder.lab_estimated_delivery_date || "",
        });
      }
    } catch (error) {
      appLogger.error("Error fetching work order:", error);
      toast.error("Error al cargar el trabajo");
    } finally {
      setLoading(false);
    }
  };

  const handleStatusUpdate = async () => {
    if (!workOrder || !newStatus) return;
    if (newStatus === "delivered") {
      setShowStatusDialog(false);
      setDeliveryDialogOpen(true);
      return;
    }
    setUpdatingStatus(true);
    try {
      const updateData: Record<string, unknown> = {
        status: newStatus,
        notes: statusNotes,
      };
      if (newStatus === "sent_to_lab") {
        updateData.lab_name = labInfo.lab_name;
        updateData.lab_contact = labInfo.lab_contact;
        updateData.lab_order_number = labInfo.lab_order_number;
        updateData.lab_estimated_delivery_date =
          labInfo.lab_estimated_delivery_date;
      }
      const response = await fetch(
        `/api/admin/work-orders/${workOrderId}/status`,
        {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(updateData),
        },
      );
      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || "Error al actualizar estado");
      }
      toast.success("Estado actualizado exitosamente");
      setShowStatusDialog(false);
      setNewStatus("");
      setStatusNotes("");
      fetchWorkOrder();
    } catch (error: unknown) {
      appLogger.error("Error updating status:", error);
      toast.error(
        (error as { message?: string }).message || "Error al actualizar estado",
      );
    } finally {
      setUpdatingStatus(false);
    }
  };

  const handleDeliver = async () => {
    if (!workOrder) return;
    setDelivering(true);
    setDeliveryError(null);
    try {
      const response = await fetch(
        `/api/admin/work-orders/${workOrderId}/deliver`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          credentials: "include",
        },
      );
      const data = await response.json();
      if (!response.ok) {
        if (data.requiresPayment) {
          setDeliveryError({
            requiresPayment: true,
            balance: data.balance,
            orderId: data.orderId,
            message: data.message,
          });
          return;
        }
        throw new Error(
          data.error || data.message || "Error al entregar trabajo",
        );
      }
      toast.success(data.message || "Trabajo entregado exitosamente");
      setDeliveryDialogOpen(false);
      setDeliveryError(null);
      if (data.workOrder) {
        setWorkOrder(data.workOrder);
      } else {
        await fetchWorkOrder();
      }
    } catch (error: unknown) {
      appLogger.error("Error delivering work order:", error);
      toast.error(
        (error as { message?: string }).message || "Error al entregar trabajo",
      );
    } finally {
      setDelivering(false);
    }
  };

  const handleDelete = async () => {
    if (!workOrder) return;
    setDeleting(true);
    try {
      const response = await fetch(`/api/admin/work-orders/${workOrderId}`, {
        method: "DELETE",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ allowDelivered: true }),
      });
      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || "Error al eliminar trabajo");
      }
      toast.success("Trabajo eliminado exitosamente");
      router.push("/admin/work-orders");
    } catch (error: unknown) {
      appLogger.error("Error deleting work order:", error);
      toast.error(
        (error as { message?: string }).message || "Error al eliminar trabajo",
      );
      setDeleteDialogOpen(false);
    } finally {
      setDeleting(false);
    }
  };

  const handlePrint = useCallback(() => {
    if (!workOrder) return;
    const printWindow = window.open("", "_blank");
    if (!printWindow) {
      toast.error("Por favor, permite ventanas emergentes para imprimir");
      return;
    }
    printWindow.document.write(buildPrintContent(workOrder, orgName));
    printWindow.document.close();
    setTimeout(() => {
      printWindow.print();
      printWindow.onafterprint = () => printWindow.close();
    }, 250);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [workOrder, orgName]);

  const getAllStatuses = (): Array<{ value: string; label: string }> => [
    { value: "quote", label: "Presupuesto" },
    { value: "ordered", label: "Ordenado" },
    { value: "sent_to_lab", label: "Enviado al Lab" },
    { value: "received_from_lab", label: "Recibido del Lab" },
    { value: "mounted", label: "Montado" },
    { value: "quality_check", label: "Control de Calidad" },
    { value: "ready_for_pickup", label: "Listo para Retiro" },
    { value: "delivered", label: "Entregado" },
    { value: "cancelled", label: "Cancelado" },
    { value: "returned", label: "Devuelto" },
  ];

  const getStatusLabel = (status: string): string => {
    const labels: Record<string, string> = {
      quote: "Presupuesto",
      ordered: "Ordenado",
      sent_to_lab: "Enviado al Lab",
      received_from_lab: "Recibido del Lab",
      mounted: "Montado",
      quality_check: "Control de Calidad",
      ready_for_pickup: "Listo para Retiro",
      delivered: "Entregado",
      cancelled: "Cancelado",
      returned: "Devuelto",
    };
    return labels[status] || status;
  };

  return {
    workOrder,
    statusHistory,
    loading,
    updatingStatus,
    showStatusDialog,
    newStatus,
    statusDialogOpenedFromTimeline,
    statusNotes,
    labInfo,
    deleteDialogOpen,
    deleting,
    deliveryDialogOpen,
    delivering,
    deliveryError,
    orgName,
    setWorkOrder,
    setShowStatusDialog,
    setNewStatus,
    setStatusDialogOpenedFromTimeline,
    setStatusNotes,
    setLabInfo,
    setDeleteDialogOpen,
    setDeliveryDialogOpen,
    setDeliveryError,
    workOrderId,
    fetchWorkOrder,
    handleStatusUpdate,
    handleDeliver,
    handleDelete,
    handlePrint,
    getAllStatuses,
    getStatusLabel,
  };
}

import { formatCurrency, formatDate } from "@/lib/utils";

import type { WorkOrder } from "./types";

export function buildPrintContent(
  workOrder: WorkOrder,
  orgName: string,
): string {
  const customerName =
    workOrder.customer?.first_name && workOrder.customer?.last_name
      ? `${workOrder.customer.first_name} ${workOrder.customer.last_name}`
      : "Sin nombre";

  const statusLabels: Record<string, string> = {
    quote: "Presupuesto",
    ordered: "Ordenado",
    sent_to_lab: "Enviado al Lab",
    received_from_lab: "Recibido del Lab",
    mounted: "Montado",
    quality_check: "Control de Calidad",
    ready_for_pickup: "Listo para Retiro",
    delivered: "Entregado",
    cancelled: "Cancelado",
    returned: "Devuelto",
  };

  const rx = (v: number | null | undefined) =>
    v !== null && v !== undefined ? `${v > 0 ? "+" : ""}${v}` : "-";

  const p = workOrder.prescription as Record<string, unknown> | null;
  const rxSection = p
    ? `
    <div class="section">
      <h2>Receta (Para Laboratorio)</h2>
      <div class="rx-grid">
        <div>
          <strong>OD:</strong> Esf ${rx(p.od_sphere as number | null)} | Cil ${rx(p.od_cylinder as number | null)} | Eje ${(p.od_axis as string) ?? "-"}° | Add ${(p.od_add as string) ?? "-"} | PD ${(p.od_pd as string) ?? "-"} mm${(p.od_near_pd as number | null) != null ? ` | PD Cerca ${p.od_near_pd} mm` : ""}${((p.od_prism as number | null) ?? (p.prism_od as number | null)) != null ? ` | Prisma ${(p.od_prism as number | null) ?? (p.prism_od as number | null)}` : ""}${(p.od_base as string | null) != null ? ` | Base ${p.od_base}` : ""}
        </div>
        <div>
          <strong>OS:</strong> Esf ${rx(p.os_sphere as number | null)} | Cil ${rx(p.os_cylinder as number | null)} | Eje ${(p.os_axis as string) ?? "-"}° | Add ${(p.os_add as string) ?? "-"} | PD ${(p.os_pd as string) ?? "-"} mm${(p.os_near_pd as number | null) != null ? ` | PD Cerca ${p.os_near_pd} mm` : ""}${((p.os_prism as number | null) ?? (p.prism_os as number | null)) != null ? ` | Prisma ${(p.os_prism as number | null) ?? (p.prism_os as number | null)}` : ""}${(p.os_base as string | null) != null ? ` | Base ${p.os_base}` : ""}
        </div>
      </div>
      ${
        p.frame_pd != null || p.height_segmentation != null || p.issued_by
          ? `
      <div class="rx-extra mt-2">
        ${p.frame_pd != null ? `<span>DP Marco: ${p.frame_pd} mm</span>` : ""}
        ${p.height_segmentation != null ? `<span>Altura Segmento: ${p.height_segmentation} mm</span>` : ""}
        ${p.issued_by ? `<span>Prescrito por: ${p.issued_by}${p.issued_by_license ? ` (${p.issued_by_license})` : ""}</span>` : ""}
      </div>`
          : ""
      }
      ${p.notes ? `<p class="mt-2"><em>Notas:</em> ${String(p.notes).replace(/\n/g, "<br>")}</p>` : ""}
    </div>`
    : "";

  const labSection = workOrder.lab_name
    ? `
    <div class="section">
      <h2>Laboratorio</h2>
      <p><strong>${workOrder.lab_name}</strong></p>
      ${workOrder.lab_order_number ? `<p>Orden Lab: ${workOrder.lab_order_number}</p>` : ""}
    </div>`
    : "";

  const notesSection =
    workOrder.internal_notes || workOrder.lab_notes
      ? `
    <div class="section">
      <h2>Notas</h2>
      ${workOrder.internal_notes ? `<p>${String(workOrder.internal_notes).replace(/\n/g, "<br>")}</p>` : ""}
      ${workOrder.lab_notes ? `<p><em>Lab:</em> ${String(workOrder.lab_notes).replace(/\n/g, "<br>")}</p>` : ""}
    </div>`
      : "";

  const treatmentsList = workOrder.lens_treatments?.length
    ? workOrder.lens_treatments.join(", ")
    : "Ninguno";

  return `
    <!DOCTYPE html>
    <html>
      <head>
        <title>Orden de Trabajo ${workOrder.work_order_number}</title>
        <style>
          body { font-family: Arial, sans-serif; max-width: 210mm; margin: 0 auto; padding: 20px; color: #333; }
          .header { text-align: center; border-bottom: 2px solid #333; padding-bottom: 16px; margin-bottom: 24px; }
          .header h1 { margin: 0; font-size: 20px; }
          .meta { display: flex; justify-content: space-between; align-items: center; margin-bottom: 20px; }
          .badge { display: inline-block; padding: 4px 8px; background: #e5e7eb; border-radius: 4px; font-size: 12px; margin-right: 8px; }
          .section { margin-bottom: 20px; padding: 12px; background: #f9fafb; border-radius: 6px; border: 1px solid #e5e7eb; }
          .section h2 { margin: 0 0 12px 0; font-size: 14px; color: #6b7280; text-transform: uppercase; }
          .info-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
          .rx-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; font-size: 12px; }
          .total-row { font-weight: bold; font-size: 18px; border-top: 2px solid #333; padding-top: 12px; margin-top: 12px; }
          .footer { margin-top: 24px; text-align: center; font-size: 11px; color: #6b7280; }
        </style>
      </head>
      <body>
        <div class="header">
          <h1>${orgName}</h1>
          <p style="margin: 8px 0 0 0; font-size: 14px;">Orden de Trabajo #${workOrder.work_order_number}</p>
        </div>
        <div class="meta">
          <span>${formatDate(workOrder.work_order_date, { format: "long", locale: "es-CL" })}</span>
          <span><span class="badge">${statusLabels[workOrder.status] || workOrder.status}</span><span class="badge">Pago: ${workOrder.payment_status}</span></span>
        </div>
        <div class="section">
          <h2>Cliente</h2>
          <p><strong>${customerName}</strong></p>
          ${workOrder.customer?.email ? `<p>${workOrder.customer.email}</p>` : ""}
          ${workOrder.customer?.phone ? `<p>${workOrder.customer.phone}</p>` : ""}
        </div>
        <div class="info-grid">
          <div class="section">
            <h2>Marco</h2>
            <p><strong>${workOrder.frame_name}</strong></p>
            ${workOrder.frame_brand ? `<p>Marca: ${workOrder.frame_brand}</p>` : ""}
            ${workOrder.frame_model ? `<p>Modelo: ${workOrder.frame_model}</p>` : ""}
            ${workOrder.frame_serial_number ? `<p>Serie: ${workOrder.frame_serial_number}</p>` : ""}
          </div>
          <div class="section">
            <h2>Lente</h2>
            <p><strong>${workOrder.lens_type}</strong></p>
            <p>Material: ${workOrder.lens_material}</p>
            ${workOrder.lens_index ? `<p>Índice: ${workOrder.lens_index}</p>` : ""}
            <p>Tratamientos: ${treatmentsList}</p>
          </div>
        </div>
        ${rxSection}
        ${labSection}
        ${notesSection}
        <div class="section">
          <h2>Total</h2>
          <div class="total-row">${formatCurrency(workOrder.total_amount)}</div>
          ${
            workOrder.deposit_amount > 0
              ? `
          <p>Depósito: ${formatCurrency(workOrder.deposit_amount)}</p>
          ${workOrder.balance_amount > 0 ? `<p style="color: #ea580c; font-weight: 600;">Saldo Pendiente: ${formatCurrency(workOrder.balance_amount)}</p>` : ""}
          `
              : ""
          }
        </div>
        <div class="footer">Documento generado el ${formatDate(new Date(), { locale: "es-CL" })}</div>
      </body>
    </html>`;
}

