 * Auto-mode trigger engine — monitors stock, appointments, and work orders.
 *
 * Each trigger produces a structured event with type, severity, entity, and
 * proposed action. Does NOT execute anything irreversible — the UI decides.
 * Rate-limited per type per org to avoid notification spam.
 *
 * @module lib/ai/agent/auto-trigger
 */

import type { SupabaseClient } from "@supabase/supabase-js";

export type TriggerType =
  | "low_stock"
  | "upcoming_appointment"
  | "overdue_work_order";
export type Severity = "info" | "warning" | "critical";

export interface TriggerEvent {
  type: TriggerType;
  severity: Severity;
  entity: { id: string; name: string; type: string };
  action: {
    label: string;
    type: "navigation" | "action" | "confirm";
    payload?: Record<string, unknown>;
  };
  message: string;
}

export interface AutoTriggerOptions {
  supabase: SupabaseClient;
  orgId: string;
  branchId: string | null;
  lowStockThreshold?: number;
}

// ponytail: in-memory cooldown map — per-org Redis TTL if multi-instance needed
const COOLDOWNS: Record<TriggerType, number> = {
  low_stock: 2 * 60 * 1000,
  upcoming_appointment: 5 * 60 * 1000,
  overdue_work_order: 10 * 60 * 1000,
};

const lastTriggered = new Map<string, number>();

function isOnCooldown(type: TriggerType, orgId: string): boolean {
  const key = `${type}:${orgId}`;
  const last = lastTriggered.get(key);
  if (!last) return false;
  return Date.now() - last < COOLDOWNS[type];
}

function setCooldown(type: TriggerType, orgId: string) {
  lastTriggered.set(`${type}:${orgId}`, Date.now());
}

/**
 * Check for trigger events across all monitored categories.
 * Returns an array of TriggerEvent — empty if nothing found or all on cooldown.
 * Safe to call on every bubble open; cooldown prevents spam.
 */
export async function checkTriggers(
  options: AutoTriggerOptions,
): Promise<TriggerEvent[]> {
  const { supabase, orgId, branchId, lowStockThreshold = 5 } = options;
  const events: TriggerEvent[] = [];

  // — 1. Low stock —
  if (!isOnCooldown("low_stock", orgId)) {
    let query = supabase
      .from("product_branch_stock")
      .select(
        `
        product_id,
        quantity,
        low_stock_threshold,
        products!inner(name)
      `,
      )
      .lt("quantity", lowStockThreshold);

    if (branchId) {
      query = query.eq("branch_id", branchId);
    }

    const { data: lowStockItems } = await query.limit(10);

    if (lowStockItems && lowStockItems.length > 0) {
      setCooldown("low_stock", orgId);
      for (const item of lowStockItems.slice(0, 3)) {
        const name = (item as unknown).products?.name || "Producto";
        const qty = (item as unknown).quantity ?? 0;
        events.push({
          type: "low_stock",
          severity: qty === 0 ? "critical" : "warning",
          entity: { id: (item as unknown).product_id, name, type: "product" },
          action: {
            label: "Ver producto",
            type: "navigation",
            payload: { path: `/admin/products/${(item as unknown).product_id}` },
          },
          message: `Stock bajo: "${name}" tiene ${qty} unidades.`,
        });
      }
    }
  }

  // — 2. Upcoming appointments within 24h —
  if (!isOnCooldown("upcoming_appointment", orgId)) {
    const now = new Date();
    const in24h = new Date(now.getTime() + 24 * 60 * 60 * 1000);

    let query = supabase
      .from("appointments")
      .select("id, customer_name, scheduled_at")
      .eq("organization_id", orgId)
      .gte("scheduled_at", now.toISOString())
      .lte("scheduled_at", in24h.toISOString())
      .in("status", ["pending", "confirmed"]);

    if (branchId) {
      query = query.eq("branch_id", branchId);
    }

    const { data: upcoming } = await query.limit(10);

    if (upcoming && upcoming.length > 0) {
      setCooldown("upcoming_appointment", orgId);
      for (const apt of upcoming.slice(0, 3)) {
        const time = new Date(apt.scheduled_at).toLocaleTimeString("es-CL", {
          hour: "2-digit",
          minute: "2-digit",
        });
        events.push({
          type: "upcoming_appointment",
          severity: "info",
          entity: {
            id: apt.id,
            name: apt.customer_name || "Cliente",
            type: "appointment",
          },
          action: {
            label: "Ver cita",
            type: "navigation",
            payload: { path: `/admin/appointments/${apt.id}` },
          },
          message: `Cita próxima: "${apt.customer_name || "Cliente"}" a las ${time}.`,
        });
      }
    }
  }

  // — 3. Overdue work orders —
  if (!isOnCooldown("overdue_work_order", orgId)) {
    const now = new Date();

    let query = supabase
      .from("lab_work_orders")
      .select("id, title, deadline")
      .eq("organization_id", orgId)
      .lt("deadline", now.toISOString())
      .in("status", ["pending", "in_progress"]);

    if (branchId) {
      query = query.eq("branch_id", branchId);
    }

    const { data: overdue } = await query.limit(10);

    if (overdue && overdue.length > 0) {
      setCooldown("overdue_work_order", orgId);
      for (const wo of overdue.slice(0, 3)) {
        events.push({
          type: "overdue_work_order",
          severity: "warning",
          entity: { id: wo.id, name: wo.title || "OT", type: "work_order" },
          action: {
            label: "Ver OT",
            type: "navigation",
            payload: { path: `/admin/work-orders/${wo.id}` },
          },
          message: `OT vencida: "${wo.title || "Trabajo"}" pasó su fecha límite.`,
        });
      }
    }
  }

  return events;
}

import type { SupabaseClient } from "@supabase/supabase-js";

import { appLogger } from '@/lib/logger';

import type { OrganizationalMemory } from "../memory/organizational";
import type { LLMMessage } from "../types";
import { getAgentConfig } from "./config";
import type { AgentConfig } from "./core";
/**
 * Load conversation history from database for session continuity.
 * Returns the messages array (including system prompt) or empty array on failure.
 */
export async function loadSessionHistory(
  supabase: SupabaseClient | undefined,
  sessionId: string,
  context: string | undefined,
  customConfig: AgentConfig | undefined,
  knowledgeBaseEnabled: boolean,
  getKnowledgeBaseContext: () => Promise<string | null>,
  limit: number = 50,
): Promise<LLMMessage[]> {
  try {
    if (!supabase) return [];

    const { data: messages, error } = await supabase
      .from("chat_messages")
      .select("role, content, tool_calls, metadata, created_at")
      .eq("session_id", sessionId)
      .order("created_at", { ascending: true })
      .limit(limit);

    if (error) {
      appLogger.error("Error loading session history:", error);
      return [];
    }

    if (!messages || messages.length === 0) {
      appLogger.info("No previous messages found for session:", sessionId);
      return [];
    }

    appLogger.info(`Loading ${messages.length} messages from session history`);

    // Get the system prompt from config
    const baseConfig = getAgentConfig(context);
    let systemPrompt =
      customConfig?.systemPrompt ?? baseConfig.systemPrompt;

    // Add knowledge base context if enabled
    if (knowledgeBaseEnabled) {
      const knowledgeContext = await getKnowledgeBaseContext();
      if (knowledgeContext) {
        systemPrompt = `${systemPrompt}

${knowledgeContext}`;
      }
    }

    // Initialize messages array with system prompt
    const result: LLMMessage[] = [
      {
        role: "system",
        content: systemPrompt,
      },
    ];

    // Add historical messages
    for (const msg of messages) {
      // Skip system messages as we already added our own
      if (msg.role === "system") continue;

      const llmMessage: LLMMessage = {
        role: msg.role as "user" | "assistant" | "tool",
        content: msg.content || "",
      };

      // Restore tool calls if present
      if (msg.tool_calls) {
        llmMessage.toolCalls = msg.tool_calls;
      }

      // Handle metadata that might contain tool calls
      if (msg.metadata?.toolCalls) {
        llmMessage.toolCalls = msg.metadata.toolCalls;
      }

      result.push(llmMessage);
    }

    appLogger.info(
      `Session history loaded: ${result.length} total messages (including system prompt)`,
    );

    return result;
  } catch (error) {
    appLogger.error("Failed to load session history:", error);
    return [];
  }
}

/**
 * Load organizational context into the agent's system prompt.
 * Modifies messages[0].content in-place with organizational context.
 */
export async function loadOrganizationalContext(
  context: string | undefined,
  customConfig: AgentConfig | undefined,
  initializeOrganizationalMemory: () => Promise<OrganizationalMemory | null>,
  messages: LLMMessage[],
): Promise<void> {
  try {
    const orgMemory = await initializeOrganizationalMemory();
    if (!orgMemory) {
      appLogger.info("Organizational memory not available");
