/**
 * 4-Layer System Prompt builder for the AI Agent.
 *
 * Each layer is a separate function for testability.
 * Layers are assembled in order: identity → role personality →
 * dynamic context → retrieved memory.
 *
 * @module lib/ai/agent/prompt-builder
 */

import type { ToolDefinition } from "../tools/types";
import type { AgentRole } from "../types";
import type { AgentSession } from "./session";

// ─── Memory context shape returned by the memory loop ───

export interface MemoryContext {
  recentFacts: Array<{ content: string; category?: string }>;
  semanticMatches: Array<{ content: string; similarity: number }>;
}

// ─── Layer builders ───

/**
 * Layer 1 — Base identity + behavioral constraints.
 * This is the immutable core of the agent's personality.
 */
function layer1Identity(): string {
  return [
    "Eres el Agente Inteligente de Opttius, el asistente copiloto del sistema de gestión para ópticas.",
    "",
    "COMPORTAMIENTO:",
    "- Responde SIEMPRE en español profesional, directo y sin rodeos.",
    "- Usa los datos disponibles para dar respuestas precisas y accionables.",
    "- No inventes información — si no sabes algo, usa las herramientas disponibles o admítelo.",
    "- Sé breve. Prefiere una oración clara sobre un párrafo vago.",
    "- Nunca muestres UUIDs, IDs internos, o slugs al usuario.",
    "- Cuando ejecutes herramientas, no expliques lo que vas a hacer antes de hacerlo.",
    "- Después de ejecutar herramientas, SIEMPRE produce una respuesta en texto.",
    "",
    "FORMATO DE RESPUESTA:",
    "- Tus respuestas se renderizan como bloques estructurados (texto, previews, acciones, navegación).",
    "- Si necesitas mostrar una lista, usa viñetas simples.",
    "- Si necesitas que el usuario navegue, usa NavigationBlock.",
    "- Si necesitas confirmación para una acción destructiva, usa ActionBlock con variant: danger.",
  ].join("\n");
}

/**
 * Layer 2 — Role-specific personality.
 */
function layer2Role(role: AgentRole): string {
  const profiles: Record<AgentRole, string> = {
    vendedor: [
      "Tu rol es VENDEDOR — tienes acceso operativo al sistema.",
      "- Puedes buscar clientes, productos, órdenes, y consultar información.",
      "- No puedes eliminar registros ni modificar configuraciones del sistema.",
      "- Enfócate en ayudar con ventas, atención al cliente, y consultas rápidas.",
      "- Si el usuario pide algo que requiere permisos de admin, indícale amablemente que debe consultar a su supervisor.",
    ].join("\n"),
    admin: [
      "Tu rol es ADMINISTRADOR — tienes control total sobre la operación diaria.",
      "- Puedes crear, modificar y eliminar la mayoría de los registros.",
      "- Puedes gestionar usuarios y permisos básicos.",
      "- No puedes modificar configuraciones globales del sistema ni del plan.",
      "- Usa tu criterio para acciones destructivas — siempre pide confirmación antes de eliminar.",
    ].join("\n"),
    dueño: [
      "Tu rol es DUEÑO — tienes acceso completo y sin restricciones.",
      "- Puedes realizar cualquier operación en el sistema.",
      "- Puedes modificar configuraciones de la organización y del plan.",
      "- Con gran poder viene gran responsabilidad — siempre confirma acciones destructivas.",
      "- Puedes acceder a reportes financieros y datos sensibles.",
    ].join("\n"),
  };

  return `## Capa 2 — Personalidad según Rol\n\n${profiles[role] || profiles.vendedor}`;
}

/**
 * Layer 3 — Dynamic screen context (route, branch, alerts).
 */
function layer3Context(session: AgentSession): string {
  const parts: string[] = ["## Capa 3 — Contexto de Pantalla"];

  if (session.context.route) {
    parts.push(`- Ruta actual: ${session.context.route}`);
  }
  if (session.context.section) {
    parts.push(`- Sección: ${session.context.section}`);
  }
  if (session.context.branchName) {
    parts.push(`- Sucursal activa: ${session.context.branchName}`);
  } else if (session.context.branchId) {
    parts.push(`- Sucursal activa ID: ${session.context.branchId}`);
  }

  return parts.join("\n");
}

/**
 * Layer 4 — Retrieved memory (output of memory loop).
 */
function layer4Memory(memory?: MemoryContext | null): string {
  if (!memory) return "";

  const parts: string[] = ["## Capa 4 — Memoria Recuperada"];

  if (memory.recentFacts.length > 0) {
    parts.push("");
    parts.push("Contexto reciente de la organización:");
    for (const fact of memory.recentFacts.slice(0, 5)) {
      const label = fact.category ? `[${fact.category}]` : "";
      parts.push(`- ${label} ${fact.content}`);
    }
  }

  if (memory.semanticMatches.length > 0) {
    parts.push("");
    parts.push("Búsqueda semántica relevante:");
    for (const match of memory.semanticMatches.slice(0, 5)) {
      parts.push(
        `- [${(match.similarity * 100).toFixed(0)}%] ${match.content}`,
      );
    }
  }

  return parts.length > 1 ? parts.join("\n") : "";
}

// ─── Tools section ───

function toolsSection(tools: ToolDefinition[]): string {
  if (tools.length === 0) return "";

  const list = tools
    .map((t) => `- ${t.name}: ${t.description.split("\n")[0]}`)
    .join("\n");

  return [
    "## Herramientas Disponibles",
    "",
    "Tienes las siguientes herramientas a tu disposición. Úsalas cuando necesites datos actualizados:",
    "",
    list,
  ].join("\n");
}

// ─── Public API ───

export interface BuildPromptOptions {
  session: AgentSession;
  memoryContext?: MemoryContext | null;
  tools: ToolDefinition[];
}

/**
 * Build the complete 4-layer system prompt.
 * Each layer is separated by a clear delimiter.
 * Layers without content are omitted.
 */
export function buildSystemPrompt({
  session,
  memoryContext,
  tools,
}: BuildPromptOptions): string {
  const layers: string[] = [];

  layers.push(layer1Identity());
  layers.push(layer2Role(session.role));

  const ctx = layer3Context(session);
  if (ctx) layers.push(ctx);

  const mem = layer4Memory(memoryContext);
  if (mem) layers.push(mem);

  layers.push(toolsSection(tools));

  return layers.join("\n\n---\n\n");
}

// Exported for testing individual layers
export { layer1Identity, layer2Role, layer3Context, layer4Memory };

/**
 * AgentSession builder — pure function that constructs an AgentSession
 * from the incoming request body.
 *
 * @module lib/ai/agent/session
 */

import { v4 as uuidv4 } from "uuid";

import type { AgentRole,AgentScreenContext } from "../types";

export interface AgentSession {
  /** The user's message text */
  message: string;
  /** Session UUID (new or reused from chat_sessions) */
  sessionId: string;
  /** Screen context metadata */
  context: AgentScreenContext;
  /** Resolved user role */
  role: AgentRole;
}

export interface SessionValidationError {
  status: 400;
  error: string;
  missingFields: string[];
}

/**
 * Build an AgentSession from an unvalidated request body.
 * Returns a SessionValidationError instead of throwing, so the
 * route handler can short-circuit to a 400 response.
 */
export function buildSession(
  body: Record<string, unknown>,
): AgentSession | SessionValidationError {
  const missingFields: string[] = [];

  const message = body.message;
  if (!message || typeof message !== "string") {
    missingFields.push("message");
  }

  const ctx = body.context as Record<string, unknown> | undefined;
  if (!ctx || typeof ctx !== "object") {
    missingFields.push("context");
  }

  const role = ctx?.role as string | undefined;
  if (!role || typeof role !== "string") {
    missingFields.push("context.role");
  }

  const orgId = ctx?.org_id as string | undefined;
  if (!orgId || typeof orgId !== "string") {
    missingFields.push("context.org_id");
  }

  if (missingFields.length > 0) {
    return {
      status: 400,
      error: `Missing required fields: ${missingFields.join(", ")}`,
      missingFields,
    };
  }

  // ponytail: uuid v4 — deterministic IDs if session_id reuse is needed later
  const sessionId = (body.session_id as string) || uuidv4();

  return {
    message: message as string,
    sessionId,
    role: role as AgentRole,
    context: {
      route: (ctx!.route as string) || "/admin",
      section: ctx!.section as string | undefined,
      branchId: (ctx!.branch_id as string) || null,
      branchName: ctx!.branch_name as string | undefined,
      role: role as AgentRole,
      orgId: orgId as string,
    },
  };
}

import type { SupabaseClient } from "@supabase/supabase-js";

import { appLogger } from '@/lib/logger';

import { LLMFactory } from "../factory";
import type { MemoryManager } from "../memory";
import { convertToolsToLLMTools, getAllTools } from "../tools";
import type {
  LLMMessage,
  LLMProvider,
  LLMStreamChunk,
  ToolCall,
} from "../types";
import { logAIUsage } from "../usage-logger";
import { getAgentConfig } from "./config";
import type { AgentConfig } from "./core";
import type { ToolExecutor } from "./tool-executor";

export interface StreamChatParams {
  userMessage: string;
  provider: LLMProvider | undefined;
  model: string | undefined;
  context: string | undefined;
  sessionId: string | undefined;
  customConfig: AgentConfig | undefined;
  organizationId: string;
  currentBranchId: string | undefined | null;
  userData:
    | {
        role?: string;
        isSuperAdmin?: boolean;
        name?: string;
      }
    | undefined;
  supabaseForUsageLog: SupabaseClient | undefined;
  skipAdminActivityLog: boolean;
  customerId: string | null | undefined;
  knowledgeBaseEnabled: boolean;
  userId: string;
  messages: LLMMessage[];
}

export interface StreamChatDeps {
  initializeToolExecutor: () => Promise<ToolExecutor>;
  initializeMemoryManager: () => Promise<MemoryManager | null>;
  executeToolCalls: (
    toolCalls: ToolCall[],
    executor: ToolExecutor,
    config: { requireConfirmationForDestructiveActions: boolean },
  ) => Promise<void>;
}

export async function* streamChatImpl(
  params: StreamChatParams,
  deps: StreamChatDeps,
): AsyncGenerator<LLMStreamChunk> {
  try {
    const executor = await deps.initializeToolExecutor();
    const baseConfig = getAgentConfig(params.context);
    const config = {
      systemPrompt:
        params.customConfig?.systemPrompt ?? baseConfig.systemPrompt,
      maxSteps: params.customConfig?.maxSteps ?? baseConfig.maxSteps,
      temperature:
        params.customConfig?.temperature ?? baseConfig.temperature,
      maxTokens: params.customConfig?.maxTokens,
      enableToolCalling:
        params.customConfig?.enableToolCalling ??
        baseConfig.enableToolCalling,
      requireConfirmationForDestructiveActions:
        params.customConfig?.requireConfirmationForDestructiveActions ??
        baseConfig.requireConfirmationForDestructiveActions,
    };

    const factory = LLMFactory.getInstance();

    let providerInstance: unknown;
    let llmConfig: unknown;

    try {
      const result = await factory.createProviderWithFallback(params.provider);
      providerInstance = result.provider;
      llmConfig = {
        ...result.config,
        model: params.model || result.config.model,
        temperature: config.temperature,
        maxTokens: config.maxTokens,
        timeout: params.customConfig?.timeout ?? 30000,
      };
    } catch (error: unknown) {
      yield {
        content: `Error: No hay proveedores de IA configurados. Por favor, configura al menos un proveedor en las variables de entorno.`,
        done: true,
      };
      return;
    }

    let tools = getAllTools();
    if (
      params.customConfig?.enabledTools &&
      params.customConfig.enabledTools.length > 0
    ) {
      tools = tools.filter((tool) =>
        params.customConfig!.enabledTools!.includes(tool.name),
      );
    }
    const llmTools = config.enableToolCalling
      ? convertToolsToLLMTools(tools)
      : undefined;

    // Get semantic context if enabled
    // NOTE: Disabled by default until migrations are run and embeddings table exists
    let semanticContext = "";
    const enableSemanticContext =
      params.customConfig?.enableSemanticContext ?? false;

    if (enableSemanticContext) {
      try {
        const memoryManager = await deps.initializeMemoryManager();
        if (memoryManager) {
          const context = await memoryManager.getRelevantContext(
            params.userMessage,
          );
          semanticContext = context.formattedContext;
          if (semanticContext) {
            appLogger.info(
              "Semantic context loaded, length:",
              semanticContext.length,
            );
          }
        }
      } catch (error) {
        appLogger.error("Failed to load semantic context:", error);
      }
    }

    // Build enhanced system prompt with semantic context
    let enhancedSystemPrompt = config.systemPrompt;
    if (semanticContext) {
      enhancedSystemPrompt = `${config.systemPrompt}\n\n${semanticContext}`;
    }

    // Only add system prompt if messages array is empty
    // (if loadSessionHistory was called, it already added the system prompt)
    if (params.messages.length === 0) {
      params.messages.push({
        role: "system",
        content: enhancedSystemPrompt,
      });
    } else if (semanticContext && params.messages[0]?.role === "system") {
      // Update existing system prompt with semantic context
      params.messages[0].content = enhancedSystemPrompt;
    }

    // Check if the last message is already this user message (avoid duplicates)
    const lastMessage = params.messages[params.messages.length - 1];
    const isUserMessageDuplicate =
      lastMessage?.role === "user" && lastMessage?.content === params.userMessage;

    if (!isUserMessageDuplicate) {
      params.messages.push({
        role: "user",
        content: params.userMessage,
      });
    }

    let stepCount = 0;
    let fullResponse = "";
    let userReceivedContent = false;

    while (stepCount < config.maxSteps) {
      try {
        const stream = providerInstance.streamText(
          params.messages,
          llmTools,
          llmConfig,
        );

        let assistantMessage = "";
        const collectedToolCallsMap = new Map<string, ToolCall>();
        let lastChunk: LLMStreamChunk | null = null;

        // Buffer content - only emit to user when there are NO tool calls (final response).
        // When there are tool calls, the buffered content is reasoning and should be hidden.
        for await (const chunk of stream) {
          lastChunk = chunk;
          if (chunk.content) {
            assistantMessage += chunk.content;
            // Do NOT yield here - we'll decide after the loop based on tool calls
          }
          if (chunk.toolCalls && chunk.toolCalls.length > 0) {
            appLogger.info(
              "Agent received tool calls from stream:",
              chunk.toolCalls.map((tc) => ({ name: tc.name, id: tc.id })),
            );
            // Accumulate tool calls by ID to handle incremental updates
            for (const tc of chunk.toolCalls) {
              if (tc.name && tc.name.trim()) {
                const toolId =
                  tc.id ||
                  `generated-${Date.now()}-${collectedToolCallsMap.size}`;
                // If we already have this tool call, merge arguments
                if (collectedToolCallsMap.has(toolId)) {
                  const existing = collectedToolCallsMap.get(toolId)!;
                  // Merge arguments (prefer new ones if they're more complete)
                  if (
                    tc.arguments &&
                    typeof tc.arguments === "object" &&
                    Object.keys(tc.arguments).length > 0
                  ) {
                    existing.arguments = {
                      ...existing.arguments,
                      ...tc.arguments,
                    };
                  }
                } else {
                  collectedToolCallsMap.set(toolId, {
                    id: toolId,
                    name: tc.name.trim(),
                    arguments: tc.arguments || {},
                  });
                }
              }
            }
          }
          if (chunk.done) break;
        }

        if (
          params.supabaseForUsageLog &&
          params.organizationId &&
          lastChunk?.usage &&
          (lastChunk.usage.promptTokens > 0 ||
            lastChunk.usage.completionTokens > 0)
        ) {
          logAIUsage(params.supabaseForUsageLog, {
            organizationId: params.organizationId,
            provider: providerInstance.name,
            model: (llmConfig.model as string) || "unknown",
            promptTokens: lastChunk.usage.promptTokens,
            completionTokens: lastChunk.usage.completionTokens,
            endpoint: "chat",
          });
        }

        // Convert map to array
        const collectedToolCalls = Array.from(collectedToolCallsMap.values());

        appLogger.info(
          "Agent step",
          stepCount,
          "- collected tool calls:",
          collectedToolCalls.length,
          collectedToolCalls.map((tc) => ({
            name: tc.name,
            args: tc.arguments,
          })),
        );
        appLogger.info(
          "Agent step",
          stepCount,
          "- assistant message length:",
          assistantMessage.length,
        );

        fullResponse += assistantMessage;

        // Add assistant message with tool calls if any
        if (assistantMessage.trim() || collectedToolCalls.length > 0) {
          const assistantMsg: LLMMessage = {
            role: "assistant",
            content: assistantMessage || "",
          };

          // Add tool calls to the message if available
          if (collectedToolCalls.length > 0) {
            assistantMsg.toolCalls = collectedToolCalls;
          }

          params.messages.push(assistantMsg);
        }

        // Only emit content to user when there are NO tool calls (final response).
        // When there are tool calls, the content is reasoning - hide it.
        if (collectedToolCalls.length === 0 && assistantMessage) {
          userReceivedContent = true;
          yield { content: assistantMessage, done: false };
        }

        if (collectedToolCalls.length === 0 || !config.enableToolCalling) {
          break;
        }

        await deps.executeToolCalls(collectedToolCalls, executor, config);

        stepCount++;
      } catch (streamError: unknown) {
        appLogger.error("Stream error in agent:", streamError);
        const errorMessage =
          (streamError as Error).message || "Error procesando la solicitud";
        yield {
          content: `\n\n❌ Error: ${errorMessage}`,
          done: false,
        };
        // Don't break immediately, let the error propagate so fallback can catch it
        throw streamError;
      }
    }

    // If the user never received any content (LLM stuck in tool calls or empty response),
    // yield a fallback so the chat is not silent
    if (!userReceivedContent) {
      const fallbackMsg =
        stepCount >= config.maxSteps
          ? "Llegué al límite de pasos sin poder completar tu solicitud. Por favor, sé más específico: indica los nombres o IDs de los productos, o la sucursal si aplica."
          : "No pude generar una respuesta. ¿Puedes reformular tu pregunta de forma más específica?";
      yield { content: fallbackMsg, done: false };
    }

    yield { content: "", done: true };
  } catch (error: unknown) {
    yield {
      content: `Error: ${(error as Error).message || "Error desconocido"}`,
      done: true,
    };
  }
}

import type {
  AgentScreenContext,
  Block,
  LLMMessage,
  LLMStreamChunk,
  ToolCall,
} from "../types";

/**
 * Build a screen-context string from AgentScreenContext for Layer 3 injection.
 * Extracted from agent.ts private method.
 */
export function screenContextToPrompt(ctx: AgentScreenContext): string {
  const parts: string[] = ["## Contexto de Pantalla"];
  if (ctx.route) parts.push(`- Ruta actual: ${ctx.route}`);
  if (ctx.section) parts.push(`- Sección: ${ctx.section}`);
  if (ctx.branchName) parts.push(`- Sucursal activa: ${ctx.branchName}`);
  else if (ctx.branchId) parts.push(`- Sucursal ID: ${ctx.branchId}`);
  return parts.join("\n");
}

/**
 * streamChatStructured — wraps streamChat() and post-processes the response into Block[].
 *
 * Accepts an optional screenContext injected into Layer 3 of the prompt.
 * Tool calls in the stream are converted to loading → action/success blocks.
 * Returns an AsyncGenerator that yields { blocks, done } for SSE consumption.
 *
 * Does NOT modify the existing streamChat() method.
 */
export async function* streamChatStructuredImpl(
  userMessage: string,
  screenContext: AgentScreenContext | undefined,
  messages: LLMMessage[],
  sessionId: string | undefined,
  deps: {
    streamChat: (
      userMessage: string,
    ) => AsyncGenerator<LLMStreamChunk>;
    screenContextToPrompt: (ctx: AgentScreenContext) => string;
  },
): AsyncGenerator<{
  blocks?: Block[];
  sessionId?: string;
  toolCalls?: ToolCall[];
  done: boolean;
}> {
  // 1. If screenContext provided, inject into Layer 3 of the system prompt
  if (screenContext) {
    const ctxText = deps.screenContextToPrompt(screenContext);
    if (messages.length > 0 && messages[0]?.role === "system") {
      messages[0].content += `\n\n${ctxText}`;
    }
  }

  // 2. Call existing streamChat and collect output
  // ponytail: collects full response then post-processes — incremental yield
  // would need LLM prompt changes to emit blocks during generation.
  let fullContent = "";
  const seenToolCalls = new Map<string, ToolCall>();

  for await (const chunk of deps.streamChat(userMessage)) {
    if (chunk.content) {
      fullContent += chunk.content;
    }
    if (chunk.toolCalls) {
      for (const tc of chunk.toolCalls) {
        if (tc.name && !seenToolCalls.has(tc.id)) {
          seenToolCalls.set(tc.id, tc);
        }
      }
    }
    if (chunk.done) {
      // 3. Post-process: tool_calls → loading/action/success blocks
      const toolBlocks: Block[] = [];
      for (const tc of seenToolCalls.values()) {
        toolBlocks.push({
          type: "loading",
          label: `Ejecutando ${tc.name}...`,
        });
        // ponytail: success blocks when tool results are reported; currently
        // tool results are fed back to LLM, not surfaced as blocks.
        // Add success block parsing from tool results if needed.
      }

      // 4. Parse text content into text blocks (split by double-newline for readability)
      const textBlocks: Block[] = [];
      if (fullContent.trim()) {
        // Split non-tool text responses
        const segments = fullContent.trim().split(/\n\n+/);
        for (const seg of segments) {
          const trimmed = seg.trim();
          if (trimmed) {
            textBlocks.push({ type: "text", content: trimmed });
          }
        }
      }

      const allBlocks = [...toolBlocks, ...textBlocks];

      yield {
        blocks:
          allBlocks.length > 0
            ? allBlocks
            : [{ type: "text", content: fullContent || "Procesado." }],
        sessionId,
        toolCalls:
          seenToolCalls.size > 0
            ? Array.from(seenToolCalls.values())
            : undefined,
        done: false,
      };

      yield {
        sessionId,
        done: true,
      };
    }
  }
}

import type { SupabaseClient } from "@supabase/supabase-js";

import { logAdminActivity } from "@/lib/api/middleware";
import { appLogger } from '@/lib/logger';

import { getToolByName } from "../tools";
import type { ToolExecutionContext, ToolResult } from "../tools/types";
import type { LLMMessage, ToolCall } from "../types";
import { initializeOrganizationalMemory } from "./memory-init";

export class ToolExecutor {
  private context: ToolExecutionContext;

  constructor(context: ToolExecutionContext) {
    this.context = context;
  }

  async executeTool(toolName: string, params: unknown): Promise<ToolResult> {
    const tool = getToolByName(toolName);

    if (!tool) {
      return {
        success: false,
        error: `Tool ${toolName} not found`,
      };
    }

    try {
      if (!this.context.skipAdminActivityLog) {
        if (tool.requiresConfirmation) {
          await logAdminActivity(
            this.context.userId,
            `tool_call_${toolName}`,
            "ai_agent",
            undefined,
            { tool: toolName, params, requiresConfirmation: true },
          );
        }
      }

      const result = await tool.execute(params, this.context);

      if (!this.context.skipAdminActivityLog) {
        await logAdminActivity(
          this.context.userId,
          `tool_executed_${toolName}`,
          "ai_agent",
          undefined,
          {
            tool: toolName,
            params,
            success: result.success,
            error: result.error,
          },
        );
      }

      return result;
    } catch (error: unknown) {
      if (!this.context.skipAdminActivityLog) {
        await logAdminActivity(
          this.context.userId,
          `tool_error_${toolName}`,
          "ai_agent",
          undefined,
          { tool: toolName, params, error: error.message },
        );
      }

      return {
        success: false,
        error: error.message || "Tool execution failed",
      };
    }
  }

  validateToolCall(
    toolName: string,
    params: unknown,
  ): { valid: boolean; error?: string } {
    const tool = getToolByName(toolName);
    if (!tool) {
      return { valid: false, error: `Tool ${toolName} not found` };
    }

    if (!params || typeof params !== "object") {
      return { valid: false, error: "Invalid parameters" };
    }

    return { valid: true };
  }

  requiresConfirmation(toolName: string): boolean {
    const tool = getToolByName(toolName);
    return tool?.requiresConfirmation || false;
  }
}

// ─── Factory ────────────────────────────────────────────────────────────────

export interface CreateToolExecutorOptions {
  userId: string;
  organizationId: string;
  currentBranchId?: string | null;
  userData?: { role?: string; isSuperAdmin?: boolean; name?: string };
  skipAdminActivityLog?: boolean;
  customerId?: string | null;
  /** Authenticated supabase client. If provided, service_role creation is skipped. */
  supabase?: SupabaseClient;
}

/**
 * Create a ToolExecutor with resolved organization and currency context.
 * Extracted from agent.ts initializeToolExecutor().
 */
export async function createToolExecutor(
  options: CreateToolExecutorOptions,
): Promise<ToolExecutor> {
  // ponytail: fallback to service_role if no auth'd client provided
  const supabase: SupabaseClient =
    options.supabase ?? (await import("@/utils/supabase/server")).createServiceRoleClient();

  // Try to resolve organizationId from profile to be sure
  let resolvedOrgId = options.organizationId;
  if (options.userId) {
    try {
      const { data: profile } = await supabase
        .from("profiles")
        .select("organization_id")
        .eq("id", options.userId)
        .single();

      if (profile?.organization_id) {
        resolvedOrgId = profile.organization_id;
      }
    } catch (e) {
      appLogger.error("Failed to resolve organization ID from profile:", e);
    }
  }

  let currency = "USD";
  try {
    const orgMemory = await initializeOrganizationalMemory(resolvedOrgId);
    if (orgMemory) {
      const orgContext = await orgMemory.getContextForAgent();
      currency = orgContext.organization.currency;
    }
  } catch (e) {
    appLogger.error("Failed to fetch currency for tool executor:", e);
  }

  const context: ToolExecutionContext = {
    userId: options.userId,
    organizationId: resolvedOrgId,
    supabase,
    currency,
    userData: options.userData,
    currentBranchId: options.currentBranchId,
    skipAdminActivityLog: options.skipAdminActivityLog,
    customerId: options.customerId,
  };
  return new ToolExecutor(context);
}

/**
 * Execute collected tool calls with validation, single retry, and error reporting.
 * Results are pushed to messages as tool-role entries for the LLM to consume.
 * Extracted from agent.ts #executeToolCalls.
 */
export async function executeToolCalls(
  toolCalls: ToolCall[],
  executor: ToolExecutor,
  config: { requireConfirmationForDestructiveActions: boolean },
  messages: LLMMessage[],
): Promise<void> {
  for (const toolCall of toolCalls) {
    if (!toolCall.name || !toolCall.name.trim()) {
      const errorMsg = `Error: Nombre de herramienta inválido o vacío`;
      appLogger.error("Tool validation:", errorMsg);
      messages.push({
        role: "tool",
        content: errorMsg,
        toolCallId: toolCall.id,
        name: "unknown",
      });
      continue;
    }

    const toolName = toolCall.name.trim();

    appLogger.info(`[Agent] Executing tool: ${toolName}`);
    appLogger.info("=== TOOL EXECUTION DEBUG ===");
    appLogger.info("Tool name:", toolName);
    appLogger.info("Tool arguments:", JSON.stringify(toolCall.arguments, null, 2));
    appLogger.info("Arguments type:", typeof toolCall.arguments);
    appLogger.info("Arguments keys:", toolCall.arguments ? Object.keys(toolCall.arguments) : []);
    appLogger.info("Arguments values:", toolCall.arguments ? Object.values(toolCall.arguments) : []);
    appLogger.info("===========================");

    const validation = executor.validateToolCall(toolName, toolCall.arguments);
    if (!validation.valid) {
      const errorMsg = `Error validando herramienta: ${validation.error}`;
      appLogger.error("Tool validation failed:", { toolName, arguments: toolCall.arguments, error: validation.error });
      messages.push({ role: "tool", content: errorMsg, toolCallId: toolCall.id, name: toolName });
      continue;
    }

    if (executor.requiresConfirmation(toolName) && config.requireConfirmationForDestructiveActions) {
      appLogger.info(`[Agent] Tool ${toolName} requires confirmation, executing anyway`);
    }

    // ponytail: simple retry-once — exponential backoff if retries > 1 needed
    let lastError: string | undefined;
    for (let attempt = 0; attempt < 2; attempt++) {
      try {
        const result = await executor.executeTool(toolName, toolCall.arguments);

        if (result.success) {
          messages.push({
            role: "tool",
            content: JSON.stringify(result.data || result.message || "Success"),
            toolCallId: toolCall.id,
            name: toolName,
          });
          appLogger.info(`[Agent] Tool ${toolName} completed successfully`);
          break;
        }

        lastError = result.error || "Unknown error";
        appLogger.error(`[Agent] Tool ${toolName} failed (attempt ${attempt + 1}):`, lastError);

        if (attempt === 0) {
          appLogger.info(`[Agent] Retrying tool ${toolName}...`);
          continue;
        }
      } catch (innerError: unknown) {
        lastError = (innerError as Error).message || "Error desconocido";
        appLogger.error(`[Agent] Tool ${toolName} threw (attempt ${attempt + 1}):`, lastError);

        if (attempt === 0) {
          continue;
        }
        break;
      }
    }

    const finalMsg = lastError
      ? `Error ejecutando ${toolName}: ${lastError}`
      : `Ejecutado: ${toolName}`;
    messages.push({
      role: "tool",
      content: finalMsg,
      toolCallId: toolCall.id,
      name: toolName,
    });
  }
}

