export function getProviderConfig(provider: LLMProvider): LLMConfig | null {
  const aiConfig = getAIConfig();
  const providerConfig = aiConfig.providers[provider];

  if (!providerConfig || !providerConfig.enabled || !providerConfig.apiKey) {
    return null;
  }

  return {
    provider,
    model: providerConfig.defaultModel || aiConfig.defaultModel,
    apiKey: providerConfig.apiKey,
    baseURL: providerConfig.baseURL,
    groupId: providerConfig.groupId,
    temperature: 0.7,
    maxTokens: 4096,
  };
}

/**
 * Embedding Factory
 *
 * Provides a unified interface for embedding generation with automatic fallback.
 * Primary: Google Embeddings (fast, cloud-based)
 * Fallback: Transformers.js (local, offline-capable)
 */

import { appLogger } from '@/lib/logger';

import { GoogleEmbeddingProvider } from "./google";
import { TransformersEmbeddingProvider } from "./transformers";
import type {
  EmbeddingBatchResult,
  EmbeddingFactoryConfig,
  EmbeddingProvider,
  EmbeddingResult,
} from "./types";

export class EmbeddingFactory {
  private static instance: EmbeddingFactory | null = null;

  private googleProvider: GoogleEmbeddingProvider;
  private transformersProvider: TransformersEmbeddingProvider;
  private config: EmbeddingFactoryConfig;

  constructor(config?: Partial<EmbeddingFactoryConfig>) {
    this.config = {
      primaryProvider: config?.primaryProvider || "google",
      fallbackProvider: config?.fallbackProvider || "transformers",
      forceProvider: config?.forceProvider,
      offlineMode: config?.offlineMode || false,
    };

    this.googleProvider = new GoogleEmbeddingProvider();
    this.transformersProvider = new TransformersEmbeddingProvider();
  }

  static getInstance(
    config?: Partial<EmbeddingFactoryConfig>,
  ): EmbeddingFactory {
    if (!EmbeddingFactory.instance) {
      EmbeddingFactory.instance = new EmbeddingFactory(config);
    }
    return EmbeddingFactory.instance;
  }

  static resetInstance(): void {
    EmbeddingFactory.instance = null;
  }

  /**
   * Get the primary provider based on config
   */
  private getPrimaryProvider(): EmbeddingProvider {
    if (this.config.forceProvider) {
      return this.config.forceProvider === "google"
        ? this.googleProvider
        : this.transformersProvider;
    }

    if (this.config.offlineMode) {
      return this.transformersProvider;
    }

    return this.config.primaryProvider === "google"
      ? this.googleProvider
      : this.transformersProvider;
  }

  /**
   * Get the fallback provider
   */
  private getFallbackProvider(): EmbeddingProvider | null {
    if (this.config.forceProvider || this.config.offlineMode) {
      return null; // No fallback when forcing a provider or in offline mode
    }

    return this.config.fallbackProvider === "google"
      ? this.googleProvider
      : this.transformersProvider;
  }

  /**
   * Check which providers are available
   */
  getAvailableProviders(): { google: boolean; transformers: boolean } {
    return {
      google: this.googleProvider.isAvailable(),
      transformers: this.transformersProvider.isAvailable(),
    };
  }

  /**
   * Get the dimensions of the current primary provider
   */
  getDimensions(): number {
    return this.getPrimaryProvider().dimensions;
  }

  /**
   * Get the name of the current primary provider
   */
  getProviderName(): string {
    return this.getPrimaryProvider().name;
  }

  /**
   * Generate embedding for a single text with automatic fallback
   */
  async embed(text: string): Promise<EmbeddingResult> {
    const primary = this.getPrimaryProvider();
    const fallback = this.getFallbackProvider();

    // Try primary provider
    if (primary.isAvailable()) {
      try {
        const result = await primary.embed(text);
        return result;
      } catch (error: unknown) {
        appLogger.warn(
          `Primary embedding provider (${primary.name}) failed:`,
          error.message,
        );

        // Try fallback if available (and it's not the same as primary)
        if (fallback && fallback.name !== primary.name) {
          try {
            // Check availability again as it might have changed
            if (fallback.isAvailable()) {
              appLogger.info(`Falling back to ${fallback.name} for embeddings`);
              return await fallback.embed(text);
            }
          } catch (fallbackError: unknown) {
            appLogger.warn(
              `Fallback provider (${fallback.name}) also failed:`,
              fallbackError.message,
            );
            // Continue to throw the original error
          }
        }

        throw error;
      }
    }

    // Primary not available, try fallback directly
    if (fallback && fallback.name !== primary.name) {
      try {
        if (fallback.isAvailable()) {
          appLogger.info(
            `Primary provider (${primary.name}) not available, using ${fallback.name}`,
          );
          return await fallback.embed(text);
        }
      } catch (error: unknown) {
        appLogger.warn(
          `Fallback provider (${fallback.name}) failed:`,
          error.message,
        );
        throw error;
      }
    }

    throw new Error(
      `No embedding providers available. Primary: ${primary.name}, Fallback: ${fallback?.name || "none"}`,
    );
  }

  /**
   * Generate embeddings for multiple texts with automatic fallback
   */
  async embedBatch(texts: string[]): Promise<EmbeddingBatchResult> {
    if (texts.length === 0) {
      return {
        embeddings: [],
        provider: this.getProviderName(),
      };
    }

    const primary = this.getPrimaryProvider();
    const fallback = this.getFallbackProvider();

    // Try primary provider
    if (primary.isAvailable()) {
      try {
        return await primary.embedBatch(texts);
      } catch (error: unknown) {
        appLogger.warn(
          `Primary embedding provider (${primary.name}) failed:`,
          error.message,
        );

        // Try fallback if available (and it's not the same as primary)
        if (fallback && fallback.name !== primary.name) {
          try {
            if (fallback.isAvailable()) {
              appLogger.info(
                `Falling back to ${fallback.name} for batch embeddings`,
              );
              return await fallback.embedBatch(texts);
            }
          } catch (fallbackError: unknown) {
            appLogger.warn(
              `Fallback provider (${fallback.name}) also failed:`,
              fallbackError.message,
            );
          }
        }

        throw error;
      }
    }

    // Primary not available, try fallback directly
    if (fallback && fallback.name !== primary.name) {
      try {
        if (fallback.isAvailable()) {
          appLogger.info(
            `Primary provider (${primary.name}) not available, using ${fallback.name}`,
          );
          return await fallback.embedBatch(texts);
        }
      } catch (error: unknown) {
        appLogger.warn(
          `Fallback provider (${fallback.name}) failed:`,
          error.message,
        );
        throw error;
      }
    }

    throw new Error(
      `No embedding providers available. Primary: ${primary.name}, Fallback: ${fallback?.name || "none"}`,
    );
  }

  /**
   * Set offline mode (only use local Transformers.js)
   */
  setOfflineMode(enabled: boolean): void {
    this.config.offlineMode = enabled;
  }

  /**
   * Force a specific provider (no fallback)
   */
  setForceProvider(provider: "google" | "transformers" | undefined): void {
    this.config.forceProvider = provider;
  }
}

// Export singleton getter for convenience
export function getEmbeddingFactory(
  config?: Partial<EmbeddingFactoryConfig>,
): EmbeddingFactory {
  return EmbeddingFactory.getInstance(config);
}

/**
 * Google Embeddings Provider
 *
 * Uses Google's text-embedding-004 model for generating embeddings.
 * Dimensions: 768
 * Rate limit: 1500 requests/minute (free tier)
 */

import type {
  EmbeddingBatchResult,
  EmbeddingProvider,
  EmbeddingResult,
  GoogleEmbeddingConfig,
} from "./types";

const GOOGLE_EMBEDDING_API =
  "https://generativelanguage.googleapis.com/v1/models";
const DEFAULT_MODEL = "text-embedding-004";
const EMBEDDING_DIMENSIONS = 768;

export class GoogleEmbeddingProvider implements EmbeddingProvider {
  name = "google";
  dimensions = EMBEDDING_DIMENSIONS;
  maxTokens = 2048;

  private apiKey: string;
  private model: string;

  constructor(config?: GoogleEmbeddingConfig) {
    this.apiKey = config?.apiKey || process.env.GOOGLE_API_KEY || "";
    this.model = config?.model || DEFAULT_MODEL;
  }

  isAvailable(): boolean {
    return !!this.apiKey;
  }

  async embed(text: string): Promise<EmbeddingResult> {
    if (!this.isAvailable()) {
      throw new Error("Google Embeddings: API key not configured");
    }

    const url = `${GOOGLE_EMBEDDING_API}/${this.model}:embedContent?key=${this.apiKey}`;

    try {
      const response = await fetch(url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          model: `models/${this.model}`,
          content: {
            parts: [{ text }],
          },
        }),
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(
          `Google Embeddings API error: ${response.status} - ${errorData.error?.message || response.statusText}`,
        );
      }

      const data = await response.json();

      if (!data.embedding?.values) {
        throw new Error(
          "Google Embeddings: Invalid response format - no embedding values",
        );
      }

      return {
        vector: data.embedding.values,
        dimensions: data.embedding.values.length,
        provider: this.name,
        tokenCount: undefined, // Google doesn't return token count for embeddings
      };
    } catch (error: unknown) {
      if (
        error.message?.includes("429") ||
        error.message?.includes("Too Many Requests")
      ) {
        throw new Error("Google Embeddings: Rate limit exceeded");
      }
      throw error;
    }
  }

  async embedBatch(texts: string[]): Promise<EmbeddingBatchResult> {
    if (!this.isAvailable()) {
      throw new Error("Google Embeddings: API key not configured");
    }

    if (texts.length === 0) {
      return {
        embeddings: [],
        provider: this.name,
      };
    }

    const url = `${GOOGLE_EMBEDDING_API}/${this.model}:batchEmbedContents?key=${this.apiKey}`;

    try {
      const response = await fetch(url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          requests: texts.map((text) => ({
            model: `models/${this.model}`,
            content: {
              parts: [{ text }],
            },
          })),
        }),
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(
          `Google Embeddings API error: ${response.status} - ${errorData.error?.message || response.statusText}`,
        );
      }

      const data = await response.json();

      if (!data.embeddings || !Array.isArray(data.embeddings)) {
        throw new Error("Google Embeddings: Invalid batch response format");
      }

      const embeddings: EmbeddingResult[] = data.embeddings.map(
        (emb: unknown) => ({
          vector: emb.values,
          dimensions: emb.values.length,
          provider: this.name,
        }),
      );

      return {
        embeddings,
        provider: this.name,
      };
    } catch (error: unknown) {
      if (
        error.message?.includes("429") ||
        error.message?.includes("Too Many Requests")
      ) {
        throw new Error("Google Embeddings: Rate limit exceeded");
      }
      throw error;
    }
  }
}

import { appLogger } from '@/lib/logger';

import { getAIConfig, getProviderConfig } from "./config";
import { getProvider } from "./providers";
import type { LLMConfig, LLMProvider, LLMProviderInterface } from "./types";

export class LLMFactory {
  private static instance: LLMFactory;
  private config = getAIConfig();

  static getInstance(): LLMFactory {
    if (!LLMFactory.instance) {
      LLMFactory.instance = new LLMFactory();
    }
    return LLMFactory.instance;
  }

  createProvider(provider?: LLMProvider): LLMProviderInterface {
    const targetProvider = provider || this.config.defaultProvider;
    return getProvider(targetProvider);
  }

  createProviderWithConfig(
    provider?: LLMProvider,
    customConfig?: Partial<LLMConfig>,
  ): {
    provider: LLMProviderInterface;
    config: LLMConfig;
  } {
    const targetProvider = provider || this.config.defaultProvider;
    const providerInstance = getProvider(targetProvider);
    const baseConfig = getProviderConfig(targetProvider);

    if (!baseConfig) {
      throw new Error(
        `Provider ${targetProvider} is not configured or enabled`,
      );
    }

    const config: LLMConfig = {
      ...baseConfig,
      ...customConfig,
    };

    if (!providerInstance.validateConfig(config)) {
      throw new Error(`Invalid configuration for provider ${targetProvider}`);
    }

    return { provider: providerInstance, config };
  }

  async createProviderWithFallback(
    preferredProvider?: LLMProvider,
    customConfig?: Partial<LLMConfig>,
  ): Promise<{ provider: LLMProviderInterface; config: LLMConfig }> {
    const providersToTry = [
      preferredProvider || this.config.defaultProvider,
      ...this.config.fallbackProviders,
    ].filter((p, i, arr) => arr.indexOf(p) === i);

    for (const provider of providersToTry) {
      try {
        const providerConfig = getProviderConfig(provider);
        if (providerConfig) {
          const providerInstance = getProvider(provider);
          const config: LLMConfig = {
            ...providerConfig,
            ...customConfig,
          };

          if (providerInstance.validateConfig(config)) {
            return { provider: providerInstance, config };
          }
        }
      } catch (error) {
        appLogger.warn(`Failed to initialize provider ${provider}:`, error);
        continue;
      }
    }

    throw new Error("No available LLM providers configured");
  }

  getAvailableProviders(): LLMProvider[] {
    return Object.entries(this.config.providers)
      .filter(([_, config]) => config?.enabled && config?.apiKey)
      .map(([provider]) => provider as LLMProvider);
  }

  isProviderEnabled(provider: LLMProvider): boolean {
    const providerConfig = this.config.providers[provider];
    return !!(providerConfig?.enabled && providerConfig?.apiKey);
  }
}

/**
 * Evolutionary Insights System
 *
 * Manages the evolution of AI prompts and insights based on organizational maturity
 * and user feedback. This system ensures that the AI's advice grows with the business.
 *
 * @module lib/ai/insights/evolutionary
 */

import { MaturityLevel } from "../memory/organizational";

export type InsightTone =
  | "encouraging"
  | "directive"
  | "analytical"
  | "strategic";
export type InsightDetailLevel = "basic" | "intermediate" | "advanced";

export interface PromptEvolutionConfig {
  tone: InsightTone;
  detailLevel: InsightDetailLevel;
  focusAreas: string[];
  forbiddenTopics: string[];
}

/**
 * Determines the appropriate prompt configuration based on organizational maturity
 */
export function getEvolutionaryConfig(
  maturity: MaturityLevel,
): PromptEvolutionConfig {
  switch (maturity.level) {
    case "new":
      return {
        tone: "encouraging",
        detailLevel: "basic",
        focusAreas: ["setup", "first_steps", "basics"],
        forbiddenTopics: ["advanced_analytics", "optimization", "trends"],
      };

    case "starting":
      return {
        tone: "directive",
        detailLevel: "basic",
        focusAreas: [
          "sales_recording",
          "customer_acquisition",
          "catalog_completion",
        ],
        forbiddenTopics: ["complex_forecasting", "advanced_segmentation"],
      };

    case "growing":
      return {
        tone: "analytical",
        detailLevel: "intermediate",
        focusAreas: ["retention", "efficiency", "inventory_management"],
        forbiddenTopics: [],
      };

    case "established":
      return {
        tone: "strategic",
        detailLevel: "advanced",
        focusAreas: ["profitability", "market_trends", "long_term_strategy"],
        forbiddenTopics: ["basic_setup_reminders"],
      };

    default:
      return {
        tone: "encouraging",
        detailLevel: "basic",
        focusAreas: ["general"],
        forbiddenTopics: [],
      };
  }
}

/**
 * Decorates a base prompt with evolutionary instructions
 */
export function evolvePrompt(
  basePrompt: string,
  config: PromptEvolutionConfig,
): string {
  const toneInstruction = getToneInstruction(config.tone);
  const detailInstruction = getDetailInstruction(config.detailLevel);
  const focusInstruction = `FOCUS AREAS: ${config.focusAreas.join(", ")}. Prioritize insights in these areas.`;
  const forbiddenInstruction =
    config.forbiddenTopics.length > 0
      ? `DO NOT discuss: ${config.forbiddenTopics.join(", ")} as they are not relevant for this stage.`
      : "";

  return `
${basePrompt}

=== EVOLUTIONARY INSTRUCTIONS ===
TONE: ${toneInstruction}
DEPTH: ${detailInstruction}
${focusInstruction}
${forbiddenInstruction}
=================================
`;
}

function getToneInstruction(tone: InsightTone): string {
  const instructions: Record<InsightTone, string> = {
    encouraging:
      "Use a warm, welcoming, and encouraging tone. Celebrate small wins. Be patient and guiding.",
    directive:
      "Be direct and clear. Give specific, step-by-step instructions. Focus on 'how-to'.",
    analytical:
      "Be objective and data-driven. Use numbers and percentages to back up claims. Focus on 'why'.",
    strategic:
      "Be visionary and executive. Focus on long-term impact, ROI, and competitive advantage.",
  };
  return instructions[tone];
}

function getDetailInstruction(level: InsightDetailLevel): string {
  const instructions: Record<InsightDetailLevel, string> = {
    basic:
      "Keep explanations simple. Avoid jargon. Focus on the 'what' and 'how'. Max 1 sentence per insight.",
    intermediate:
      "Provide context. Explain the 'why'. Use industry standard terms where appropriate.",
    advanced:
      "Deep dive into correlations. Connect multiple data points. Use advanced optical industry metrics.",
  };
  return instructions[level];
}

/**
 * Adapts feedback to fine-tune future prompts (Mock implementation)
 * In a real system, this would store preferences in a DB.
 */
export class FeedbackLoop {
  private static userPreferences: Map<string, string[]> = new Map();

  static recordFeedback(
    userId: string,
    insightId: string,
    isPositive: boolean,
    topic: string,
  ) {
    if (!this.userPreferences.has(userId)) {
      this.userPreferences.set(userId, []);
    }

    const prefs = this.userPreferences.get(userId)!;
    if (isPositive) {
      prefs.push(`User likes insights about ${topic}`);
    } else {
      prefs.push(`User dislikes insights about ${topic}`);
    }
  }

  static getPersonalizationContext(userId: string): string {
    const prefs = this.userPreferences.get(userId);
    if (!prefs || prefs.length === 0) return "";

    return `
=== USER PREFERENCES ===
The user has provided the following feedback history:
- ${prefs.join("\n- ")}
Adjust your response accordingly.
========================
`;
  }
}

/**
 * AI Insights Generator
 *
 * Generates contextual insights using LLMs with structured output validation.
 * Handles LLM calls, response parsing, and schema validation.
 * Now enhanced with organizational maturity awareness for adaptive prompts.
 *
 * @module lib/ai/insights/generator
 */

import type { SupabaseClient } from "@supabase/supabase-js";

import { appLogger as logger } from "@/lib/logger";

import { LLMFactory } from "../factory";
import type { MaturityLevel } from "../memory/organizational";
import { logAIUsage } from "../usage-logger";
import { OrganizationalMaturitySystem } from "./maturity";
import {
  getDailySummaryPrompt,
  getSectionPrompt,
  getUserMessage,
} from "./prompts";
import {
  type Insight,
  InsightSchema,
  type InsightSection,
  InsightsResponseSchema,
} from "./schemas";

export interface GenerateInsightsOptions {
  section: InsightSection;
  data: unknown;
  organizationName: string;
  organizationId?: string;
  maturityLevel?: MaturityLevel;
  additionalContext?: Record<string, unknown>;
  temperature?: number;
  maxRetries?: number;
  useMaturityAdaptation?: boolean;
  /** Optional: if provided, AI usage will be logged for cost tracking */
  supabase?: SupabaseClient;
  /** Optional: "daily_summary" uses a specialized prompt for yesterday's executive summary */
  variant?: "daily_summary";
  /** For daily_summary: the date string (YYYY-MM-DD) */
  variantDate?: string;
}

/**
 * Generate insights for a specific section using LLM
 *
 * @param options - Options for insight generation
 * @returns Array of validated insights
 * @throws Error if LLM call fails or validation fails
 */
export async function generateInsights(
  options: GenerateInsightsOptions,
): Promise<Insight[]> {
  const {
    section,
    data,
    organizationName,
    organizationId,
    maturityLevel,
    additionalContext,
    temperature = 0.7,
    maxRetries = 2,
    useMaturityAdaptation = true,
    supabase,
    variant,
    variantDate,
  } = options;

  const factory = LLMFactory.getInstance();

  // Try to get a provider with fallback
  let provider;
  let config;
  try {
    const result = await factory.createProviderWithFallback(undefined, {
      temperature,
      maxTokens: 2000, // Limit tokens for cost control
    });
    provider = result.provider;
    config = result.config;
  } catch (error) {
    logger.error("Failed to initialize LLM provider", { error });
    throw new Error("No available LLM providers configured");
  }

  // Get prompts - with maturity adaptation if available
  let systemPrompt: string;

  if (useMaturityAdaptation && maturityLevel && organizationId) {
    // Use maturity-adapted prompts
    const maturitySystem = new OrganizationalMaturitySystem(organizationId);
    systemPrompt = await maturitySystem.getAdaptivePrompts(
      section,
      maturityLevel,
      data,
      organizationName,
      additionalContext,
    );

    logger.info("Using maturity-adapted prompts", {
      section,
      maturityLevel: maturityLevel.level,
      organizationAge: maturityLevel.daysSinceCreation,
    });
  } else if (variant === "daily_summary" && variantDate) {
    systemPrompt = getDailySummaryPrompt(
      organizationName,
      data,
      variantDate,
      additionalContext,
    );
  } else {
    // Use standard prompts
    systemPrompt = getSectionPrompt(
      section,
      data,
      organizationName,
      additionalContext,
    );
  }

  const userMessage =
    variant === "daily_summary"
      ? `Genera el resumen ejecutivo del día ${variantDate} con los datos proporcionados.`
      : getUserMessage(section, data);

  // Retry logic for LLM calls
  let lastError: Error | null = null;
  let lastResponseContent: string | undefined;
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      // Call LLM
      const response = await provider.generateText(
        [
          { role: "system", content: systemPrompt },
          { role: "user", content: userMessage },
        ],
        undefined, // No tools needed for insights generation
        config,
      );

      lastResponseContent = response.content;

      if (
        supabase &&
        organizationId &&
        response.usage &&
        (response.usage.promptTokens > 0 || response.usage.completionTokens > 0)
      ) {
        logAIUsage(supabase, {
          organizationId,
          provider: provider.name,
          model: config.model || "unknown",
          promptTokens: response.usage.promptTokens,
          completionTokens: response.usage.completionTokens,
          endpoint: "insights",
        });
      }

      // Parse JSON from response
      let parsedResponse: unknown;
      try {
        // Try to parse as JSON first
        parsedResponse = JSON.parse(response.content);
      } catch (parseError) {
        // If parsing fails, try to extract JSON from markdown code blocks
        const jsonMatch = response.content.match(
          /```(?:json)?\s*(\{[\s\S]*\})\s*```/,
        );
        if (jsonMatch) {
          parsedResponse = JSON.parse(jsonMatch[1]);
        } else {
          // Try to find JSON object in the response
          const jsonObjectMatch = response.content.match(/\{[\s\S]*\}/);
          if (jsonObjectMatch) {
            parsedResponse = JSON.parse(jsonObjectMatch[0]);
          } else {
            logger.error("No valid JSON found in LLM response", {
              section,
              provider: provider.name,
              contentPreview: response.content.slice(0, 2000),
            });
            throw new Error("No valid JSON found in LLM response");
          }
        }
      }

      // Validate with Zod schema
      const validated = InsightsResponseSchema.parse(parsedResponse);

      logger.info("Insights generated successfully", {
        section,
        count: validated.insights.length,
        provider: provider.name,
      });

      return validated.insights;
    } catch (error: unknown) {
      lastError = error;
      logger.warn(`Insight generation attempt ${attempt + 1} failed`, {
        section,
        error: error.message,
        attempt: attempt + 1,
      });

      // If it's a validation error, don't retry
      if (error.name === "ZodError") {
        logger.error("Schema validation failed for insights", {
          section,
          provider: provider.name,
          errors: error.errors,
          contentPreview: lastResponseContent?.slice(0, 2000),
        });
        throw new Error(`Invalid insight format: ${error.message}`);
      }

      // If it's the last attempt, throw the error
      if (attempt === maxRetries) {
        throw new Error(
          `Failed to generate insights after ${maxRetries + 1} attempts: ${lastError?.message}`,
        );
      }

      // Wait before retrying (exponential backoff)
      await new Promise((resolve) => setTimeout(resolve, 1000 * (attempt + 1)));
    }
  }

  throw new Error(`Failed to generate insights: ${lastError?.message}`);
}

/**
 * Generate a single insight (for real-time scenarios like POS)
 *
 * @param options - Options for insight generation
 * @returns Single validated insight or null if no insight needed
 */
export async function generateSingleInsight(
  options: GenerateInsightsOptions,
): Promise<Insight | null> {
  const insights = await generateInsights(options);

  // Return the highest priority insight, or null if empty
  if (insights.length === 0) {
    return null;
  }

  // Sort by priority (descending) and return the first one
  return insights.sort((a, b) => b.priority - a.priority)[0];
}

/**
 * Validate insights without generating new ones
 * Useful for testing or re-validation
 */
export function validateInsights(insights: unknown[]): Insight[] {
  return insights.map((insight) => InsightSchema.parse(insight));
}

import { MaturityLevel } from "../memory/organizational";
import { getSectionPrompt } from "./prompts";
import { InsightSection } from "./schemas";

export class OrganizationalMaturitySystem {
  private organizationId: string;

  constructor(organizationId: string) {
    this.organizationId = organizationId;
  }

  /**
   * Generates a maturity-adapted prompt for a specific section
   */
  async getAdaptivePrompts(
    section: InsightSection,
    maturity: MaturityLevel,
    data: unknown,
    organizationName: string,
    additionalContext?: Record<string, unknown>,
  ): Promise<string> {
    // Get the base prompt from the existing system
    // We pass maturity info in additionalContext so the base prompt can use it if it wants
    const contextWithMaturity = {
      ...additionalContext,
      organizationAge: maturity.daysSinceCreation,
      totalOrders: maturity.totalOrders,
      maturityLevel: maturity.level,
    };

    const basePrompt = getSectionPrompt(
      section,
      data,
      organizationName,
      contextWithMaturity,
    );
    const maturityAdjustments = this.getMaturityAdjustments(maturity.level);

    return `${basePrompt}\n\n${maturityAdjustments}`;
  }

  private getMaturityAdjustments(level: MaturityLevel["level"]): string {
    const adjustments = {
      new: `
      INSTRUCCIONES DE MADUREZ (NIVEL: NUEVO):
      Esta óptica es nueva en el sistema.
      - Tu tono debe ser de bienvenida, paciente y educativo.
      - Prioriza insights que ayuden a la configuración inicial y primeros pasos.
      - Evita jerga compleja o análisis avanzados que requieran datos históricos que no existen.
      - Enfócate en: "¿Cómo empezar?" y "Configuración básica".
      `,

      starting: `
      INSTRUCCIONES DE MADUREZ (NIVEL: INICIO):
      Esta óptica está en sus etapas iniciales.
      - Tu tono debe ser de guía y apoyo operativo.
      - Prioriza insights sobre el flujo de trabajo diario y registro de datos.
      - Ayuda a establecer buenos hábitos operativos.
      - Enfócate en: "Registrar ventas correctamente", "Crear base de clientes".
      `,

      growing: `
      INSTRUCCIONES DE MADUREZ (NIVEL: CRECIMIENTO):
      Esta óptica está creciendo.
      - Tu tono debe ser de consultor de negocios.
      - Prioriza insights sobre optimización, retención de clientes y eficiencia.
      - Usa los datos acumulados para mostrar tendencias tempranas.
      - Enfócate en: "Mejorar márgenes", "Retención de clientes", "Optimizar inventario".
      `,

      established: `
      INSTRUCCIONES DE MADUREZ (NIVEL: ESTABLECIDO):
      Esta óptica está consolidada.
      - Tu tono debe ser de analista experto y estratégico.
      - Prioriza insights profundos, detección de anomalías sutiles y oportunidades estratégicas.
      - Sé exigente con las métricas y busca la excelencia operativa.
      - Enfócate en: "Estrategia a largo plazo", "Maximización de rentabilidad", "Análisis de mercado".
      `,
    };

    return adjustments[level] || adjustments["growing"];
  }
}

/**
 * Shared logic for preparing insight data.
 * Used by both the API route (user context) and cron (service role, global view).
 *
 * @module lib/ai/insights/prepare-data
 */

import type { SupabaseClient } from "@supabase/supabase-js";

import type { BranchContext } from "@/lib/api/branch-middleware";
import {
  addBranchFilter,
  addBranchFilterForBranchScopedTable,
} from "@/lib/api/branch-middleware";

import type { InsightSection } from "./schemas";

export interface PrepareDataResult {
  organizationName: string;
  section: InsightSection | "all";
  data: Record<string, unknown>;
}

/**
 * Prepare real system data for insight generation.
 * Can be called with user's branch context (API) or global context (cron).
 */
export async function prepareInsightData(
  supabase: SupabaseClient,
  organizationId: string,
  organizationName: string,
  section: InsightSection | null,
  branchContext: BranchContext,
): Promise<PrepareDataResult> {
  const data: Record<string, unknown> = {};

  if (!section || section === "dashboard") {
    const now = new Date();
    const yesterday = new Date(now);
    yesterday.setDate(yesterday.getDate() - 1);
    yesterday.setHours(0, 0, 0, 0);
    const yesterdayEnd = new Date(yesterday);
    yesterdayEnd.setHours(23, 59, 59, 999);

    const thirtyDaysAgo = new Date(now);
    thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

    let ordersQuery = supabase
      .from("orders")
      .select("total_amount, created_at, status, payment_status")
      .gte("created_at", thirtyDaysAgo.toISOString());

    ordersQuery = addBranchFilter(
      ordersQuery,
      branchContext.branchId,
      branchContext.isSuperAdmin,
      branchContext.organizationId,
    );

    const { data: orders } = await ordersQuery;

    const yesterdayOrders =
      orders?.filter((o: unknown) => {
        const orderDate = new Date(o.created_at);
        return (
          orderDate >= yesterday &&
          orderDate <= yesterdayEnd &&
          (o.status === "completed" || o.payment_status === "paid")
        );
      }) || [];

    const yesterdaySales = yesterdayOrders.reduce(
      (sum: number, o: unknown) => sum + (o.total_amount || 0),
      0,
    );

    const monthlyOrders =
      orders?.filter((o: unknown) => {
        const orderDate = new Date(o.created_at);
        return (
          orderDate >= thirtyDaysAgo &&
          (o.status === "completed" || o.payment_status === "paid")
        );
      }) || [];

    const monthlyRevenue = monthlyOrders.reduce(
      (sum: number, o: unknown) => sum + (o.total_amount || 0),
      0,
    );
    const monthlyAverage = monthlyRevenue / 30;

    let workOrdersQuery = supabase
      .from("lab_work_orders")
      .select("status, lab_estimated_delivery_date")
      .in("status", ["ordered", "sent_to_lab", "in_progress_lab"]);

    workOrdersQuery = addBranchFilter(
      workOrdersQuery,
      branchContext.branchId,
      branchContext.isSuperAdmin,
      branchContext.organizationId,
    );

    const { data: workOrders } = await workOrdersQuery;

    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const overdueWorkOrders =
      workOrders?.filter((wo: unknown) => {
        if (!wo.lab_estimated_delivery_date) return false;
        const deliveryDate = new Date(wo.lab_estimated_delivery_date);
        return deliveryDate < today;
      }).length || 0;

    let quotesQuery = supabase
      .from("quotes")
      .select("status, converted_to_work_order_id")
      .in("status", ["draft", "sent"])
      .is("converted_to_work_order_id", null);

    quotesQuery = addBranchFilter(
      quotesQuery,
      branchContext.branchId,
      branchContext.isSuperAdmin,
      branchContext.organizationId,
    );

    const { data: quotes } = await quotesQuery;
    const pendingQuotes = quotes?.length || 0;

    data.dashboard = {
      yesterdaySales: Math.round(yesterdaySales),
      monthlyAverage: Math.round(monthlyAverage),
      overdueWorkOrders,
      pendingQuotes,
    };
  }

  if (!section || section === "inventory") {
    let productsQuery = supabase
      .from("products")
      .select("id, name, inventory_quantity, cost_price, price, created_at")
      .eq("status", "active");

    productsQuery = addBranchFilter(
      productsQuery,
      branchContext.branchId,
      branchContext.isSuperAdmin,
      branchContext.organizationId,
    );

    const { data: products } = await productsQuery;

    const { data: orderItems } = await supabase
      .from("order_items")
      .select("product_id, created_at, orders!inner(created_at)")
      .order("created_at", { ascending: false })
      .limit(1000);

    const productLastSales = new Map<string, Date>();
    orderItems?.forEach((item: unknown) => {
      const productId = item.product_id;
      const saleDate = new Date(item.orders?.created_at || item.created_at);
      if (
        !productLastSales.has(productId) ||
        saleDate > productLastSales.get(productId)!
      ) {
        productLastSales.set(productId, saleDate);
      }
    });

    const now = new Date();
    const zombieProducts =
      products
        ?.filter((p: unknown) => {
          const lastSale = productLastSales.get(p.id);
          if (!lastSale) {
            const createdDate = new Date(p.created_at);
            const daysSinceCreation =
              (now.getTime() - createdDate.getTime()) / (1000 * 60 * 60 * 24);
            return daysSinceCreation > 90 && p.inventory_quantity > 0;
          }
          const daysSinceLastSale =
            (now.getTime() - lastSale.getTime()) / (1000 * 60 * 60 * 24);
          return daysSinceLastSale > 180 && p.inventory_quantity > 0;
        })
        .map((p: unknown) => {
          const lastSale = productLastSales.get(p.id);
          const daysSinceLastSale = lastSale
            ? Math.floor(
                (now.getTime() - lastSale.getTime()) / (1000 * 60 * 60 * 24),
              )
            : Math.floor(
                (now.getTime() - new Date(p.created_at).getTime()) /
                  (1000 * 60 * 60 * 24),
              );

          return {
            id: p.id,
            name: p.name,
            stock: p.inventory_quantity || 0,
            daysSinceLastSale,
            cost: p.cost_price || 0,
            price: p.price || 0,
          };
        })
        .slice(0, 10) || [];

    const lowStockProducts =
      products?.filter(
        (p: unknown) =>
          (p.inventory_quantity || 0) < 5 && (p.inventory_quantity || 0) > 0,
      ).length || 0;

    data.inventory = {
      zombieProducts,
      lowStockProducts,
    };
  }

  if (!section || section === "clients") {
    let customersQuery = supabase
      .from("customers")
      .select("id, first_name, last_name, email, phone, rut, created_at")
      .eq("is_active", true);

    customersQuery = await addBranchFilterForBranchScopedTable(
      customersQuery,
      branchContext,
      supabase,
    );

    const { data: customers } = await customersQuery;

    const { data: appointments } = await supabase
      .from("appointments")
      .select("customer_id, appointment_date")
      .order("appointment_date", { ascending: false });

    const customerLastVisits = new Map<string, Date>();
    appointments?.forEach((apt: unknown) => {
      if (!apt.customer_id) return;
      const visitDate = new Date(apt.appointment_date);
      if (
        !customerLastVisits.has(apt.customer_id) ||
        visitDate > customerLastVisits.get(apt.customer_id)!
      ) {
        customerLastVisits.set(apt.customer_id, visitDate);
      }
    });

    const now = new Date();
    const inactiveClients =
      customers
        ?.filter((c: unknown) => {
          const lastVisit = customerLastVisits.get(c.id);
          if (!lastVisit) {
            const createdDate = new Date(c.created_at);
            const daysSinceCreation =
              (now.getTime() - createdDate.getTime()) / (1000 * 60 * 60 * 24);
            return daysSinceCreation > 180;
          }
          const daysSinceLastVisit =
            (now.getTime() - lastVisit.getTime()) / (1000 * 60 * 60 * 24);
          return daysSinceLastVisit > 180;
        })
        .map((c: unknown) => {
          const lastVisit = customerLastVisits.get(c.id);
          const daysSinceLastVisit = lastVisit
            ? Math.floor(
                (now.getTime() - lastVisit.getTime()) / (1000 * 60 * 60 * 24),
              )
            : Math.floor(
                (now.getTime() - new Date(c.created_at).getTime()) /
                  (1000 * 60 * 60 * 24),
              );

          return {
            id: c.id,
            name:
              `${c.first_name || ""} ${c.last_name || ""}`.trim() || "Cliente",
            daysSinceLastVisit,
            prescriptionExpired: daysSinceLastVisit > 365,
            contactLensRenewal: daysSinceLastVisit > 180,
          };
        })
        .slice(0, 10) || [];

    data.clients = {
      inactiveClients,
    };
  }

  if (!section || section === "pos") {
    // POS insights use prescription/customerHistory - for bulk regenerate use empty context
    data.pos = data.pos || {
      prescription: {},
      customerHistory: {},
    };
  }

  if (!section || section === "analytics") {
    const now = new Date();
    const currentPeriodStart = new Date(now);
    currentPeriodStart.setDate(currentPeriodStart.getDate() - 30);
    const previousPeriodStart = new Date(currentPeriodStart);
    previousPeriodStart.setDate(previousPeriodStart.getDate() - 30);

    let ordersQuery = supabase
      .from("orders")
      .select(
        "total_amount, created_at, status, payment_status, order_items(product_name, total_price)",
      )
      .gte("created_at", previousPeriodStart.toISOString());

    ordersQuery = addBranchFilter(
      ordersQuery,
      branchContext.branchId,
      branchContext.isSuperAdmin,
      branchContext.organizationId,
    );

    const { data: orders } = await ordersQuery;

    const currentPeriodOrders =
      orders?.filter((o: unknown) => {
        const orderDate = new Date(o.created_at);
        return (
          orderDate >= currentPeriodStart &&
          (o.status === "completed" || o.payment_status === "paid")
        );
      }) || [];

    const previousPeriodOrders =
      orders?.filter((o: unknown) => {
        const orderDate = new Date(o.created_at);
        return (
          orderDate >= previousPeriodStart &&
          orderDate < currentPeriodStart &&
          (o.status === "completed" || o.payment_status === "paid")
        );
      }) || [];

    const currentPeriod = currentPeriodOrders.reduce(
      (sum: number, o: unknown) => sum + (o.total_amount || 0),
      0,
    );

    const previousPeriod = previousPeriodOrders.reduce(
      (sum: number, o: unknown) => sum + (o.total_amount || 0),
      0,
    );

    const changePercent =
      previousPeriod > 0
        ? ((currentPeriod - previousPeriod) / previousPeriod) * 100
        : 0;

    const breakdown = {
      frames: 0,
      lenses: 0,
      contactLenses: 0,
      accessories: 0,
    };

    currentPeriodOrders.forEach((order: unknown) => {
      order.order_items?.forEach((item: unknown) => {
        const productName = (item.product_name || "").toLowerCase();
        if (productName.includes("marco") || productName.includes("armazon")) {
          breakdown.frames += item.total_price || 0;
        } else if (
          productName.includes("lente") ||
          productName.includes("cristal")
        ) {
          breakdown.lenses += item.total_price || 0;
        } else if (productName.includes("contacto")) {
          breakdown.contactLenses += item.total_price || 0;
        } else {
          breakdown.accessories += item.total_price || 0;
        }
      });
    });

    data.analytics = {
      salesData: {
        currentPeriod: Math.round(currentPeriod),
        previousPeriod: Math.round(previousPeriod),
        changePercent: Math.round(changePercent * 10) / 10,
        breakdown: {
          frames: Math.round(breakdown.frames),
          lenses: Math.round(breakdown.lenses),
          contactLenses: Math.round(breakdown.contactLenses),
          accessories: Math.round(breakdown.accessories),
        },
      },
      trends: {
        direction:
          changePercent > 5 ? "up" : changePercent < -5 ? "down" : "stable",
        factor:
          changePercent > 0 ? "Crecimiento en ventas" : "Disminución en ventas",
      },
    };
  }

  return {
    organizationName,
    section: section || "all",
    data,
  };
}

/**
 * System Prompts for AI Insights Generation
 *
 * Contains prompts tailored for each section of the application.
 * These prompts guide the LLM to generate contextual, actionable insights.
 * Usa rutas de routes-reference.ts - NUNCA inventar rutas.
 *
 * @module lib/ai/insights/prompts
 */

import {
  INSIGHT_ROUTES,
  INVALID_ROUTES,
  ROUTES_BY_SECTION,
} from "./routes-reference";
import type { InsightSection } from "./schemas";

/**
 * Base prompt instructions for all insights
 */
const BASE_INSTRUCTIONS = `
Eres un asistente experto de gestión de óptica. Genera insights accionables y específicos basados en los datos proporcionados.
Cada insight debe ser:
- Claro y conciso (máximo 2 líneas para el mensaje)
- Accionable (sugiere qué hacer)
- Priorizado correctamente (1-10, donde 10 es crítico)
- Relevante para el contexto de la sección

Responde SOLO con JSON válido, sin markdown, sin texto extra.
Usa EXACTAMENTE estas claves y valores:
{
  "insights": [
    {
      "type": "warning" | "opportunity" | "info" | "neutral",
      "title": "string (max 100)",
      "message": "string (max 500)",
      "priority": 1-10,
      "action_label": "string (max 50, opcional)",
      "action_url": "/admin/..." o "https://..." (opcional),
      "metadata": { "key": "value" } (opcional)
    }
  ]
}

No uses claves en español. Usa exactamente: type, title, message, priority, action_label, action_url, metadata.
`;

/**
 * Get system prompt for a specific section
 */
export function getSectionPrompt(
  section: InsightSection,
  data: unknown,
  organizationName: string,
  additionalContext?: Record<string, unknown>,
): string {
  const sectionPrompts: Record<InsightSection, string> = {
    dashboard: getDashboardPrompt(organizationName, data, additionalContext),
    inventory: getInventoryPrompt(organizationName, data, additionalContext),
    clients: getClientsPrompt(organizationName, data, additionalContext),
    pos: getPOSPrompt(organizationName, data, additionalContext),
    analytics: getAnalyticsPrompt(organizationName, data, additionalContext),
  };

  return `${BASE_INSTRUCTIONS}\n\n${sectionPrompts[section]}`;
}

/**
 * Daily summary prompt - Resumen ejecutivo del día anterior
 * Used by cron to generate a highlighted "yesterday" summary
 */
export function getDailySummaryPrompt(
  organizationName: string,
  data: {
    yesterdaySales?: number;
    monthlyAverage?: number;
    overdueWorkOrders?: number;
    pendingQuotes?: number;
  },
  dateStr: string,
  additionalContext?: Record<string, unknown>,
): string {
  const organizationAge = additionalContext?.organizationAge || 0;
  const totalOrders = additionalContext?.totalOrders || 0;

  return `
Eres el Gerente General de la óptica "${organizationName}".

Genera un RESUMEN EJECUTIVO del día ${dateStr} (día anterior). El usuario verá este resumen al abrir la app.

Métricas del día ${dateStr}:
- Ventas: ${data.yesterdaySales ?? 0}
- Promedio mensual de referencia: ${data.monthlyAverage ?? 0}
- Trabajos atrasados: ${data.overdueWorkOrders || 0}
- Presupuestos pendientes: ${data.pendingQuotes || 0}
- Edad de la óptica: ${organizationAge} días
- Total órdenes históricas: ${totalOrders}

Genera 1-3 insights que formen un resumen ejecutivo coherente:
1. Resumen de ventas del día (si hubo o no)
2. Alertas si hay trabajos atrasados o presupuestos pendientes
3. Sugerencia para el día de hoy

Prioridad: 6-8
Tipos: 'info', 'opportunity' o 'warning' según corresponda
Rutas válidas: ${ROUTES_BY_SECTION.dashboard.slice(0, 6).join(", ")}
`;
}

/**
 * Dashboard prompt - El Gerente General
 * Trigger: Cron Job diario a las 8:00 AM
 */
function getDashboardPrompt(
  organizationName: string,
  data: {
    yesterdaySales?: number;
    monthlyAverage?: number;
    dailyGoal?: number;
    overdueWorkOrders?: number;
    pendingQuotes?: number;
  },
  additionalContext?: Record<string, unknown>,
): string {
  // Detectar estado de la óptica
  const isNewOrganization = additionalContext?.isNewOrganization || false;
  const hasData =
    (data.yesterdaySales !== undefined && data.yesterdaySales !== null) ||
    (data.monthlyAverage !== undefined && data.monthlyAverage !== null) ||
    (data.overdueWorkOrders !== undefined && data.overdueWorkOrders > 0) ||
    (data.pendingQuotes !== undefined && data.pendingQuotes > 0);
  const organizationAge = additionalContext?.organizationAge || 0; // días desde creación
  const totalCustomers = additionalContext?.totalCustomers || 0;
  const totalProducts = additionalContext?.totalProducts || 0;
  const totalOrders = additionalContext?.totalOrders || 0;

  // Determinar fase de la óptica
  let organizationPhase = "new";
  if (organizationAge > 90 && totalOrders > 50) {
    organizationPhase = "established";
  } else if (organizationAge > 30 && totalOrders > 10) {
    organizationPhase = "growing";
  } else if (organizationAge > 7 || totalOrders > 0) {
    organizationPhase = "starting";
  }

  let phaseInstructions = "";
  if (organizationPhase === "new") {
    phaseInstructions = `
ESTADO: Óptica nueva (menos de 7 días o sin órdenes)
ENFOQUE: Bienvenida y guía de implementación inicial
- Genera insights de bienvenida y ayuda para configurar el sistema
- Sugiere pasos iniciales: agregar productos, crear clientes, configurar sucursales
- Prioridad: 5-7 (importante pero no urgente)
- Tipo: 'info' o 'opportunity'
`;
  } else if (organizationPhase === "starting") {
    phaseInstructions = `
ESTADO: Óptica en fase inicial (${organizationAge} días, ${totalOrders} órdenes)
ENFOQUE: Guía para empezar a usar el sistema efectivamente
- Sugiere completar configuración básica si falta
- Recomienda empezar a registrar ventas y clientes
- Prioridad: 6-8
- Tipo: 'opportunity' o 'info'
`;
  } else if (organizationPhase === "growing") {
    phaseInstructions = `
ESTADO: Óptica en crecimiento (${organizationAge} días, ${totalOrders} órdenes)
ENFOQUE: Optimización y mejores prácticas
- Analiza métricas reales y sugiere mejoras
- Identifica oportunidades de crecimiento
- Prioridad: según métricas reales (5-9)
- Tipo: 'warning', 'opportunity' o 'info' según contexto
`;
  } else {
    phaseInstructions = `
ESTADO: Óptica establecida (${organizationAge} días, ${totalOrders} órdenes)
ENFOQUE: Análisis profundo y optimización continua
- Analiza tendencias y patrones
- Identifica problemas y oportunidades específicas
- Prioridad: según análisis de datos (1-10)
- Tipo: según análisis ('warning', 'opportunity', 'info', 'neutral')
`;
  }

  return `
Eres el Gerente General de la óptica "${organizationName}".

${phaseInstructions}

Analiza las siguientes métricas:
- Ventas de ayer: ${data.yesterdaySales ?? "N/A"} ${data.yesterdaySales === 0 ? "(sin ventas aún)" : ""}
- Promedio mensual: ${data.monthlyAverage ?? "N/A"} ${data.monthlyAverage === 0 ? "(sin datos históricos)" : ""}
- Trabajos pendientes: ${data.overdueWorkOrders || 0}
- Presupuestos pendientes: ${data.pendingQuotes || 0}
- Total de clientes: ${totalCustomers}
- Total de productos: ${totalProducts}
- Total de órdenes: ${totalOrders}

RUTAS VÁLIDAS (usa SOLO estas, NUNCA otras):
${ROUTES_BY_SECTION.dashboard.map((r) => `- ${r}`).join("\n")}

RUTAS PROHIBIDAS (NO usar): ${INVALID_ROUTES.join(", ")}

Tareas según fase:
${
  organizationPhase === "new"
    ? `
1. Genera un mensaje de bienvenida cálido y profesional
2. Sugiere los primeros pasos: agregar productos básicos, crear clientes de prueba
3. Explica cómo usar el sistema para empezar a trabajar
4. Prioridad: 5-7, Tipo: 'info' o 'opportunity'
`
    : organizationPhase === "starting"
      ? `
1. Verifica si hay datos básicos (productos, clientes)
2. Sugiere empezar a registrar ventas si aún no lo han hecho
3. Recomienda completar configuración faltante
4. Prioridad: 6-8, Tipo: 'opportunity' o 'info'
`
      : `
1. Compara las ventas de ayer con el promedio mensual
2. Si hay trabajos pendientes, sugiere revisar ${INSIGHT_ROUTES.workOrdersOrdered}
3. Si hay presupuestos pendientes, sugiere revisar ${INSIGHT_ROUTES.quotesDraft}
4. Analiza tendencias y genera insights específicos basados en datos reales
5. Si no hay problemas, genera un insight de tipo 'neutral' indicando que todo está en orden
6. Asigna prioridad del 1 al 10 según la importancia real (10 = crítico, 1 = informativo)
`
}

IMPORTANTE: Usa SOLO las rutas listadas arriba. NO inventes rutas.
Ejemplos de action_url válidos:
- "${INSIGHT_ROUTES.workOrdersOrdered}"
- "${INSIGHT_ROUTES.quotesDraft}"
- "${INSIGHT_ROUTES.analytics}"
- "${INSIGHT_ROUTES.products}"
- "${INSIGHT_ROUTES.customers}"
- "${INSIGHT_ROUTES.system}"

Ejemplos de insights según fase:
${
  organizationPhase === "new"
    ? `
- Bienvenida: tipo 'info', prioridad 5, action_url: "${INSIGHT_ROUTES.products}"
- Configuración inicial: tipo 'opportunity', prioridad 6, action_url: "${INSIGHT_ROUTES.system}"
- Primeros pasos: tipo 'info', prioridad 5, action_url: "${INSIGHT_ROUTES.customers}"
`
    : `
- Si ventas < promedio: tipo 'warning', prioridad 7-8, action_url: "${INSIGHT_ROUTES.analytics}"
- Si trabajos pendientes > 0: tipo 'warning', prioridad 9-10, action_url: "${INSIGHT_ROUTES.workOrdersOrdered}"
- Si presupuestos pendientes > 0: tipo 'opportunity', prioridad 6-7, action_url: "${INSIGHT_ROUTES.quotesDraft}"
- Si todo está bien: tipo 'neutral', prioridad 1-2
`
}
`;
}

