import { promises as fs } from "fs";
import { join } from "path";

import { EmbeddingFactory } from "@/lib/ai/embeddings/factory";
import { appLogger } from '@/lib/logger';

import { DocumentParser, ParsedDocument } from "../parsers/document-parser";

export interface IndexedDocument {
  id: string;
  documentId: string;
  title: string;
  content: string;
  category: string;
  tags: string[];
  embedding: number[];
  metadata: {
    createdAt: Date;
    updatedAt: Date;
    version: string;
    sectionHeadings: string[];
  };
  lastIndexed: Date;
}

export interface SearchQuery {
  text: string;
  category?: string;
  tags?: string[];
  limit?: number;
  minSimilarity?: number;
}

export interface SearchResult {
  document: IndexedDocument;
  similarity: number;
  matchedSections: string[];
}

export class KnowledgeIndexer {
  private parser: DocumentParser;
  private embeddingFactory: EmbeddingFactory;
  private index: Map<string, IndexedDocument> = new Map();
  private indexPath: string;

  constructor(indexPath: string = "src/lib/ai/knowledge/embeddings/generated") {
    this.parser = new DocumentParser();
    this.embeddingFactory = new EmbeddingFactory();
    this.indexPath = indexPath;
  }

  /**
   * Index all documents in a directory
   */
  async indexDirectory(directoryPath: string): Promise<number> {
    appLogger.info(`Indexing documents from: ${directoryPath}`);

    const documents = await this.parser.parseDirectory(directoryPath, {
      extractMetadata: true,
      extractSections: true,
      extractTags: true,
    });

    let indexedCount = 0;

    for (const doc of documents) {
      try {
        await this.indexDocument(doc);
        indexedCount++;
        appLogger.info(`✓ Indexed: ${doc.title}`);
      } catch (error) {
        appLogger.warn(`✗ Failed to index ${doc.title}:`, error);
      }
    }

    await this.saveIndex();
    appLogger.info(`Successfully indexed ${indexedCount} documents`);

    return indexedCount;
  }

  /**
   * Index a single document
   */
  async indexDocument(parsedDoc: ParsedDocument): Promise<void> {
    try {
      // Generate embedding for the document content
      const embedding = await this.generateEmbedding(parsedDoc.content);

      // Extract section headings for quick reference
      const sectionHeadings = parsedDoc.sections.map(
        (section) => section.heading,
      );

      const indexedDoc: IndexedDocument = {
        id: this.generateIndexedId(parsedDoc.id),
        documentId: parsedDoc.id,
        title: parsedDoc.title,
        content: parsedDoc.content,
        category: parsedDoc.category,
        tags: parsedDoc.tags,
        embedding,
        metadata: {
          createdAt: parsedDoc.metadata.createdAt,
          updatedAt: parsedDoc.metadata.updatedAt,
          version: parsedDoc.metadata.version,
          sectionHeadings,
        },
        lastIndexed: new Date(),
      };

      this.index.set(indexedDoc.id, indexedDoc);
    } catch (error) {
      throw new Error(`Failed to index document ${parsedDoc.title}: ${error}`);
    }
  }

  /**
   * Search indexed documents using semantic similarity
   */
  async search(query: SearchQuery): Promise<SearchResult[]> {
    // Load index if not already loaded
    if (this.index.size === 0) {
      await this.loadIndex();
    }

    // Generate embedding for the query
    const queryEmbedding = await this.generateEmbedding(query.text);

    const results: SearchResult[] = [];

    // Calculate similarity for each document
    for (const [id, doc] of this.index.entries()) {
      // Apply filters
      if (query.category && doc.category !== query.category) continue;
      if (query.tags && !this.matchesTags(doc.tags, query.tags)) continue;

      const similarity = this.cosineSimilarity(queryEmbedding, doc.embedding);

      // Apply minimum similarity threshold
      const minSimilarity = query.minSimilarity || 0.3;
      if (similarity >= minSimilarity) {
        results.push({
          document: doc,
          similarity,
          matchedSections: this.findMatchingSections(query.text, doc),
        });
      }
    }

    // Sort by similarity and apply limit
    results.sort((a, b) => b.similarity - a.similarity);

    const limit = query.limit || 5;
    return results.slice(0, limit);
  }

  /**
   * Get document by ID
   */
  getDocument(documentId: string): IndexedDocument | undefined {
    for (const doc of this.index.values()) {
      if (doc.documentId === documentId) {
        return doc;
      }
    }
    return undefined;
  }

  /**
   * Get documents by category
   */
  getDocumentsByCategory(category: string): IndexedDocument[] {
    return Array.from(this.index.values()).filter(
      (doc) => doc.category === category,
    );
  }

  /**
   * Get documents by tags
   */
  getDocumentsByTags(tags: string[]): IndexedDocument[] {
    return Array.from(this.index.values()).filter((doc) =>
      this.matchesTags(doc.tags, tags),
    );
  }

  /**
   * Save index to disk
   */
  async saveIndex(): Promise<void> {
    try {
      const indexData = {
        documents: Array.from(this.index.values()),
        metadata: {
          lastUpdated: new Date().toISOString(),
          documentCount: this.index.size,
        },
      };

      const indexPath = join(
        process.cwd(),
        this.indexPath,
        "knowledge-index.json",
      );
      await fs.writeFile(indexPath, JSON.stringify(indexData, null, 2));
      appLogger.info(`Index saved to: ${indexPath}`);
    } catch (error) {
      appLogger.error("Failed to save index:", error);
    }
  }

  /**
   * Load index from disk
   */
  async loadIndex(): Promise<void> {
    try {
      const indexPath = join(
        process.cwd(),
        this.indexPath,
        "knowledge-index.json",
      );
      const data = await fs.readFile(indexPath, "utf-8");
      const indexData = JSON.parse(data);

      this.index.clear();
      for (const doc of indexData.documents) {
        // Convert date strings back to Date objects
        doc.metadata.createdAt = new Date(doc.metadata.createdAt);
        doc.metadata.updatedAt = new Date(doc.metadata.updatedAt);
        doc.lastIndexed = new Date(doc.lastIndexed);
        this.index.set(doc.id, doc);
      }

      appLogger.info(`Loaded ${this.index.size} documents from index`);
    } catch (error) {
      appLogger.info("No existing index found, starting fresh");
    }
  }

  /**
   * Clear the index
   */
  clearIndex(): void {
    this.index.clear();
  }

  /**
   * Get index statistics
   */
  getIndexStats(): {
    totalDocuments: number;
    categories: Record<string, number>;
    totalTags: number;
    lastUpdated?: Date;
  } {
    const categories: Record<string, number> = {};
    const allTags = new Set<string>();

    for (const doc of this.index.values()) {
      categories[doc.category] = (categories[doc.category] || 0) + 1;
      doc.tags.forEach((tag) => allTags.add(tag));
    }

    const lastUpdated =
      this.index.size > 0
        ? new Date(
            Math.max(
              ...Array.from(this.index.values()).map((d) =>
                d.lastIndexed.getTime(),
              ),
            ),
          )
        : undefined;

    return {
      totalDocuments: this.index.size,
      categories,
      totalTags: allTags.size,
      lastUpdated,
    };
  }

  /**
   * Generate embedding using the embedding factory
   */
  private async generateEmbedding(text: string): Promise<number[]> {
    try {
      const result = await this.embeddingFactory.embed(text);
      return result.vector;
    } catch (error) {
      appLogger.error("Failed to generate embedding:", error);
      // Fallback to simple token-based representation
      return this.simpleTextEmbedding(text);
    }
  }

  /**
   * Simple fallback embedding for when embedding providers fail
   */
  private simpleTextEmbedding(text: string): number[] {
    // Simple hash-based embedding for fallback
    const hash = this.simpleHash(text);
    const embedding = new Array(384).fill(0);

    // Distribute hash values across embedding dimensions
    for (let i = 0; i < 384; i++) {
      embedding[i] = ((hash >> i % 32) & 1) === 1 ? 1 : -1;
    }

    return embedding;
  }

  /**
   * Simple hash function for fallback embedding
   */
  private simpleHash(str: string): number {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      const char = str.charCodeAt(i);
      hash = (hash << 5) - hash + char;
      hash = hash & hash; // Convert to 32-bit integer
    }
    return Math.abs(hash);
  }

  /**
   * Calculate cosine similarity between two vectors
   */
  private cosineSimilarity(vecA: number[], vecB: number[]): number {
    if (vecA.length !== vecB.length) return 0;

    let dotProduct = 0;
    let magnitudeA = 0;
    let magnitudeB = 0;

    for (let i = 0; i < vecA.length; i++) {
      dotProduct += vecA[i] * vecB[i];
      magnitudeA += vecA[i] * vecA[i];
      magnitudeB += vecB[i] * vecB[i];
    }

    magnitudeA = Math.sqrt(magnitudeA);
    magnitudeB = Math.sqrt(magnitudeB);

    if (magnitudeA === 0 || magnitudeB === 0) return 0;

    return dotProduct / (magnitudeA * magnitudeB);
  }

  /**
   * Check if document tags match query tags
   */
  private matchesTags(documentTags: string[], queryTags: string[]): boolean {
    return queryTags.some((queryTag) =>
      documentTags.some(
        (docTag) =>
          docTag.toLowerCase().includes(queryTag.toLowerCase()) ||
          queryTag.toLowerCase().includes(docTag.toLowerCase()),
      ),
    );
  }

  /**
   * Find sections that match the query
   */
  private findMatchingSections(query: string, doc: IndexedDocument): string[] {
    const queryLower = query.toLowerCase();
    const matchingSections: string[] = [];

    // Check if query terms appear in section headings
    for (const heading of doc.metadata.sectionHeadings) {
      if (heading.toLowerCase().includes(queryLower)) {
        matchingSections.push(heading);
      }
    }

    return matchingSections;
  }

  /**
   * Generate unique ID for indexed document
   */
  private generateIndexedId(documentId: string): string {
    return `idx_${documentId}_${Date.now()}`;
  }
}

import { join } from "path";

import { appLogger } from '@/lib/logger';

import {
  KnowledgeIndexer,
  SearchQuery,
  SearchResult,
} from "./indexers/knowledge-indexer";
import { DocumentParser } from "./parsers/document-parser";

export interface KnowledgeBaseConfig {
  contentPath: string;
  indexPath: string;
  autoIndex: boolean;
  updateInterval?: number; // in minutes
}

export interface KnowledgeContext {
  userId?: string;
  organizationId?: string;
  userRole?: string;
  currentSection?: string;
  recentActions?: string[];
}

export class KnowledgeBaseManager {
  private indexer: KnowledgeIndexer;
  private parser: DocumentParser;
  private config: KnowledgeBaseConfig;
  private isInitialized: boolean = false;
  private updateTimer: NodeJS.Timeout | null = null;

  constructor(config: KnowledgeBaseConfig) {
    this.config = config;
    this.indexer = new KnowledgeIndexer(config.indexPath);
    this.parser = new DocumentParser();
  }

  /**
   * Initialize the knowledge base
   */
  async initialize(): Promise<void> {
    if (this.isInitialized) {
      appLogger.info("Knowledge base already initialized");
      return;
    }

    appLogger.info("Initializing knowledge base...");

    try {
      // Load existing index
      await this.indexer.loadIndex();

      // Index content if auto-indexing is enabled
      if (this.config.autoIndex) {
        await this.indexContent();
      }

      // Set up periodic updates if configured
      if (this.config.updateInterval) {
        this.setupPeriodicUpdates();
      }

      this.isInitialized = true;
      appLogger.info("Knowledge base initialized successfully");
    } catch (error) {
      appLogger.error("Failed to initialize knowledge base:", error);
      throw error;
    }
  }

  /**
   * Index all content in the knowledge base
   */
  async indexContent(): Promise<void> {
    appLogger.info("Indexing knowledge base content...");

    const contentPath = join(process.cwd(), this.config.contentPath);

    // Index each content category
    const categories = [
      "core-system",
      "business-modules",
      "admin-features",
      "integrations",
      "troubleshooting",
    ];

    let totalIndexed = 0;

    for (const category of categories) {
      try {
        const categoryPath = join(contentPath, category);
        const indexed = await this.indexer.indexDirectory(categoryPath);
        totalIndexed += indexed;
        appLogger.info(`Indexed ${indexed} documents from ${category}`);
      } catch (error) {
        appLogger.warn(`Failed to index category ${category}:`, error);
      }
    }

    appLogger.info(`Total documents indexed: ${totalIndexed}`);
  }

  /**
   * Search for relevant knowledge based on query and context
   */
  async searchKnowledge(
    query: string,
    context?: KnowledgeContext,
  ): Promise<SearchResult[]> {
    if (!this.isInitialized) {
      await this.initialize();
    }

    const searchQuery: SearchQuery = {
      text: query,
      limit: 5,
      minSimilarity: 0.3,
    };

    // Apply context-based filtering
    if (context) {
      // Filter by user role for access control
      if (context.userRole === "store_manager") {
        searchQuery.category = "business-modules";
      } else if (context.userRole === "admin") {
        // Admins can access everything
      }

      // Boost relevance for current section
      if (context.currentSection) {
        searchQuery.tags = [context.currentSection];
      }
    }

    const results = await this.indexer.search(searchQuery);

    // Apply additional context-based ranking
    if (context) {
      this.applyContextRanking(results, context);
    }

    return results;
  }

  /**
   * Get specific document by ID
   */
  async getDocument(documentId: string): Promise<unknown> {
    if (!this.isInitialized) {
      await this.initialize();
    }

    return this.indexer.getDocument(documentId);
  }

  /**
   * Get documents by category
   */
  async getDocumentsByCategory(category: string): Promise<unknown[]> {
    if (!this.isInitialized) {
      await this.initialize();
    }

    return this.indexer.getDocumentsByCategory(category);
  }

  /**
   * Get knowledge base statistics
   */
  async getStatistics(): Promise<unknown> {
    if (!this.isInitialized) {
      await this.initialize();
    }

    const stats = this.indexer.getIndexStats();
    return {
      ...stats,
      isInitialized: this.isInitialized,
      config: this.config,
    };
  }

  /**
   * Update specific documents
   */
  async updateDocuments(documentIds: string[]): Promise<void> {
    appLogger.info(`Updating ${documentIds.length} documents...`);

    const contentPath = join(process.cwd(), this.config.contentPath);

    for (const docId of documentIds) {
      try {
        // Find and re-parse the document
        const documents = await this.parser.parseDirectory(contentPath, {
          extractMetadata: true,
          extractSections: true,
          extractTags: true,
        });

        const docToUpdate = documents.find((doc) => doc.id === docId);
        if (docToUpdate) {
          await this.indexer.indexDocument(docToUpdate);
          appLogger.info(`✓ Updated document: ${docToUpdate.title}`);
        }
      } catch (error) {
        appLogger.warn(`✗ Failed to update document ${docId}:`, error);
      }
    }

    await this.indexer.saveIndex();
  }

  /**
   * Shutdown the knowledge base manager
   */
  async shutdown(): Promise<void> {
    appLogger.info("Shutting down knowledge base manager...");

    if (this.updateTimer) {
      clearInterval(this.updateTimer);
      this.updateTimer = null;
    }

    await this.indexer.saveIndex();
    this.isInitialized = false;

    appLogger.info("Knowledge base manager shut down");
  }

  /**
   * Setup periodic updates
   */
  private setupPeriodicUpdates(): void {
    if (!this.config.updateInterval) return;

    const intervalMs = this.config.updateInterval * 60 * 1000; // Convert to milliseconds

    this.updateTimer = setInterval(async () => {
      try {
        appLogger.info("Running periodic knowledge base update...");
        await this.indexContent();
      } catch (error) {
        appLogger.error("Periodic update failed:", error);
      }
    }, intervalMs);

    appLogger.info(
      `Periodic updates scheduled every ${this.config.updateInterval} minutes`,
    );
  }

  /**
   * Apply context-based ranking to search results
   */
  private applyContextRanking(
    results: SearchResult[],
    context: KnowledgeContext,
  ): void {
    // Boost results based on user role relevance
    if (context.userRole) {
      results.forEach((result) => {
        // Higher boost for role-specific content
        if (this.isRoleRelevant(result.document.category, context.userRole!)) {
          result.similarity *= 1.3; // 30% boost
        }
      });
    }

    // Boost results based on recent actions
    if (context.recentActions && context.recentActions.length > 0) {
      results.forEach((result) => {
        const actionMatches = context.recentActions!.filter((action) =>
          result.document.content.toLowerCase().includes(action.toLowerCase()),
        );

        if (actionMatches.length > 0) {
          result.similarity *= 1 + actionMatches.length * 0.1; // Up to 30% boost
        }
      });
    }

    // Re-sort based on adjusted similarities
    results.sort((a, b) => b.similarity - a.similarity);
  }

  /**
   * Check if a document category is relevant to a user role
   */
  private isRoleRelevant(category: string, role: string): boolean {
    const roleCategories: Record<string, string[]> = {
      store_manager: ["business-modules", "core-system"],
      admin: [
        "admin-features",
        "business-modules",
        "core-system",
        "integrations",
      ],
      super_admin: [
        "admin-features",
        "business-modules",
        "core-system",
        "integrations",
        "troubleshooting",
      ],
    };

    const relevantCategories = roleCategories[role] || [];
    return relevantCategories.includes(category);
  }
}

// Singleton instance for easy access
let knowledgeBaseInstance: KnowledgeBaseManager | null = null;

export function getKnowledgeBase(): KnowledgeBaseManager {
  if (!knowledgeBaseInstance) {
    knowledgeBaseInstance = new KnowledgeBaseManager({
      contentPath: "src/lib/ai/knowledge/content",
      indexPath: "src/lib/ai/knowledge/embeddings/generated",
      autoIndex: true,
      updateInterval: 30, // Update every 30 minutes
    });
  }

  return knowledgeBaseInstance;
}

export async function initializeKnowledgeBase(): Promise<KnowledgeBaseManager> {
  const kb = getKnowledgeBase();
  await kb.initialize();
  return kb;
}

import { promises as fs } from 'fs';
import { join } from 'path';

import { appLogger } from '@/lib/logger';


export interface ParsedDocument {
  id: string;
  title: string;
  content: string;
  category: string;
  tags: string[];
  metadata: DocumentMetadata;
  sections: DocumentSection[];
}

export interface DocumentMetadata {
  createdAt: Date;
  updatedAt: Date;
  version: string;
  author: string;
  maintainer: string;
  lastReviewed: Date;
}

export interface DocumentSection {
  heading: string;
  level: number;
  content: string;
  startPosition: number;
  endPosition: number;
}

export interface ParseOptions {
  extractMetadata?: boolean;
  extractSections?: boolean;
  extractTags?: boolean;
}

export class DocumentParser {
  /**
   * Parse a markdown document into structured content
   */
  async parseDocument(filePath: string, options: ParseOptions = {}): Promise<ParsedDocument> {
    const content = await fs.readFile(filePath, 'utf-8');
    const fileName = filePath.split('/').pop()?.replace('.md', '') || '';
    
    const parsed: ParsedDocument = {
      id: this.generateDocumentId(filePath),
      title: this.extractTitle(content),
      content,
      category: this.determineCategory(filePath),
      tags: options.extractTags ? this.extractTags(content) : [],
      metadata: options.extractMetadata ? this.extractMetadata(content) : this.getDefaultMetadata(),
      sections: options.extractSections ? this.extractSections(content) : []
    };

    return parsed;
  }

  /**
   * Parse multiple documents from a directory
   */
  async parseDirectory(directoryPath: string, options: ParseOptions = {}): Promise<ParsedDocument[]> {
    const files = await fs.readdir(directoryPath);
    const markdownFiles = files.filter(file => file.endsWith('.md'));
    
    const documents: ParsedDocument[] = [];
    
    for (const file of markdownFiles) {
      try {
        const filePath = join(directoryPath, file);
        const document = await this.parseDocument(filePath, options);
        documents.push(document);
      } catch (error) {
        appLogger.warn(`Failed to parse document ${file}:`, error);
      }
    }
    
    return documents;
  }

  /**
   * Extract title from markdown content (first # heading)
   */
  private extractTitle(content: string): string {
    const titleMatch = content.match(/^#\s+(.+)$/m);
    return titleMatch ? titleMatch[1].trim() : 'Untitled Document';
  }

  /**
   * Extract sections from markdown content
   */
  private extractSections(content: string): DocumentSection[] {
    const sections: DocumentSection[] = [];
    const headingRegex = /^(#{1,6})\s+(.+)$/gm;
    let match;
    
    const headings: Array<{ level: number; text: string; position: number }> = [];
    
    while ((match = headingRegex.exec(content)) !== null) {
      headings.push({
        level: match[1].length,
        text: match[2].trim(),
        position: match.index
      });
    }
    
    // Create sections between headings
    for (let i = 0; i < headings.length; i++) {
      const current = headings[i];
      const next = headings[i + 1];
      
      const sectionContent = next 
        ? content.substring(current.position, next.position)
        : content.substring(current.position);
      
      sections.push({
        heading: current.text,
        level: current.level,
        content: sectionContent,
        startPosition: current.position,
        endPosition: next ? next.position : content.length
      });
    }
    
    return sections;
  }

  /**
   * Extract tags from content (looking for <!-- tags: tag1, tag2 --> comments)
   */
  private extractTags(content: string): string[] {
    const tagRegex = /<!--\s*tags:\s*([^-->]+)\s*-->/i;
    const match = content.match(tagRegex);
    
    if (match) {
      return match[1]
        .split(',')
        .map(tag => tag.trim().toLowerCase())
        .filter(tag => tag.length > 0);
    }
    
    // Fallback: extract from YAML frontmatter if present
    const yamlRegex = /^---\s*\ntags:\s*\[([^\]]+)\]\s*\n---/m;
    const yamlMatch = content.match(yamlRegex);
    
    if (yamlMatch) {
      return yamlMatch[1]
        .split(',')
        .map(tag => tag.trim().replace(/['"]/g, '').toLowerCase())
        .filter(tag => tag.length > 0);
    }
    
    return [];
  }

  /**
   * Extract metadata from YAML frontmatter
   */
  private extractMetadata(content: string): DocumentMetadata {
    const yamlRegex = /^---\s*\n([\s\S]*?)\n---/;
    const match = content.match(yamlRegex);
    
    if (match) {
      const yamlContent = match[1];
      const metadata: Partial<DocumentMetadata> = {};
      
      // Simple YAML parser for our use case
      const lines = yamlContent.split('\n');
      for (const line of lines) {
        const [key, value] = line.split(':').map(s => s.trim());
        if (key && value) {
          switch (key.toLowerCase()) {
            case 'createdat':
            case 'created':
              metadata.createdAt = new Date(value);
              break;
            case 'updatedat':
            case 'updated':
              metadata.updatedAt = new Date(value);
              break;
            case 'version':
              metadata.version = value.replace(/['"]/g, '');
              break;
            case 'author':
              metadata.author = value.replace(/['"]/g, '');
              break;
            case 'maintainer':
              metadata.maintainer = value.replace(/['"]/g, '');
              break;
            case 'lastreviewed':
              metadata.lastReviewed = new Date(value);
              break;
          }
        }
      }
      
      return {
        createdAt: metadata.createdAt || new Date(),
        updatedAt: metadata.updatedAt || new Date(),
        version: metadata.version || '1.0.0',
        author: metadata.author || 'System',
        maintainer: metadata.maintainer || 'Documentation Team',
        lastReviewed: metadata.lastReviewed || new Date()
      };
    }
    
    return this.getDefaultMetadata();
  }

  /**
   * Determine document category from file path
   */
  private determineCategory(filePath: string): string {
    const pathParts = filePath.toLowerCase().split('/');
    
    // Look for category indicators in path
    if (pathParts.includes('core-system')) return 'core-system';
    if (pathParts.includes('business-modules')) return 'business-modules';
    if (pathParts.includes('admin-features')) return 'admin-features';
    if (pathParts.includes('integrations')) return 'integrations';
    if (pathParts.includes('troubleshooting')) return 'troubleshooting';
    
    return 'general';
  }

  /**
   * Generate unique document ID from file path
   */
  private generateDocumentId(filePath: string): string {
    return filePath
      .toLowerCase()
      .replace(/[^a-z0-9]/g, '-')
      .replace(/-+/g, '-')
      .replace(/^-|-$/g, '');
  }

  /**
   * Get default metadata for documents without explicit metadata
   */
  private getDefaultMetadata(): DocumentMetadata {
    return {
      createdAt: new Date(),
      updatedAt: new Date(),
      version: '1.0.0',
      author: 'Documentation System',
      maintainer: 'Documentation Team',
      lastReviewed: new Date()
    };
  }
}

