/**
 * Products Indexer
 *
 * Indexes product data for semantic search.
 */

import type { SupabaseClient } from "@supabase/supabase-js";

import { appLogger } from '@/lib/logger';

import type { SemanticMemory } from "../semantic";
import type {
  EmbeddingRecord,
  IndexingOptions,
  IndexingResult,
} from "../types";

export function buildProductContent(product: unknown): string {
  const parts = [
    `Producto: ${product.name}`,
    product.description && `Descripción: ${product.description}`,
    product.short_description && `Resumen: ${product.short_description}`,
    `Precio: $${product.price}`,
    product.status && `Estado: ${product.status}`,
    product.benefits?.length && `Beneficios: ${product.benefits.join(", ")}`,
    product.tags?.length && `Tags: ${product.tags.join(", ")}`,
  ].filter(Boolean);

  return parts.join(". ");
}

export async function indexProducts(
  semanticMemory: SemanticMemory,
  supabase: SupabaseClient,
  options: IndexingOptions = {},
): Promise<IndexingResult> {
  const { batchSize = 50, forceReindex = false } = options;
  const result: IndexingResult = {
    sourceType: "product",
    totalRecords: 0,
    indexed: 0,
    failed: 0,
    errors: [],
  };

  try {
    // Get products to index
    const { data: products, error } = await supabase
      .from("products")
      .select(
        "id, name, description, short_description, price, status, category_id, benefits, tags",
      );

    if (error) {
      result.errors.push(`Failed to fetch products: ${error.message}`);
      return result;
    }

    if (!products || products.length === 0) {
      return result;
    }

    result.totalRecords = products.length;
    appLogger.info(`Indexing ${products.length} products...`);

    // Process in batches
    for (let i = 0; i < products.length; i += batchSize) {
      const batch = products.slice(i, i + batchSize);
      const records: EmbeddingRecord[] = [];

      for (const product of batch) {
        // Skip if already indexed (unless force reindex)
        if (!forceReindex) {
          const hasEmb = await semanticMemory.hasEmbedding(
            "product",
            product.id,
          );
          if (hasEmb) {
            result.indexed++; // Count as indexed
            continue;
          }
        }

        // Build content string for embedding
        const content = buildProductContent(product);

        records.push({
          sourceType: "product",
          sourceId: product.id,
          content,
          embeddingProvider: "google" as const,
          metadata: {
            name: product.name,
            price: product.price,
            status: product.status,
            categoryId: product.category_id,
          },
        });
      }

      if (records.length > 0) {
        try {
          const indexed =
            await semanticMemory.storeEmbeddingBatch(records);
          result.indexed += indexed;
        } catch (err: unknown) {
          result.failed += records.length;
          result.errors.push(
            `Batch ${i / batchSize + 1} failed: ${err.message}`,
          );
        }
      }
    }

    appLogger.info(`Products indexed: ${result.indexed}/${result.totalRecords}`);
    return result;
  } catch (error: unknown) {
    result.errors.push(`Indexing failed: ${error.message}`);
    return result;
  }
}

/**
 * Long-term Memory Service
 *
 * Manages persistent facts and preferences learned from conversations.
 * These facts persist across sessions and help personalize the agent's responses.
 */


import { appLogger } from '@/lib/logger';

import { getEmbeddingFactory } from "../embeddings";
import type {
  LongTermMemoryConfig,
  MemoryContext,
  MemoryFact,
  MemoryFactSearchResult,
} from "./types";

export class LongTermMemory {
  private context: MemoryContext;

  constructor(context: MemoryContext) {
    this.context = context;
  }

  /**
   * Store a new fact in long-term memory
   */
  async storeFact(fact: Omit<MemoryFact, "id">): Promise<string | null> {
    try {
      const factory = getEmbeddingFactory();
      const embeddingResult = await factory.embed(fact.content);

      const insertData: unknown = {
        user_id: fact.userId,
        fact_type: fact.factType,
        category: fact.category || null,
        content: fact.content,
        importance: fact.importance,
        embedding_provider: embeddingResult.provider,
        source_session_id: fact.sourceSessionId || null,
        source_message_id: fact.sourceMessageId || null,
        expires_at: fact.expiresAt || null,
      };

      // Store in appropriate column based on provider
      if (embeddingResult.provider === "transformers") {
        insertData.embedding_small = embeddingResult.vector;
      } else {
        insertData.embedding = embeddingResult.vector;
      }

      const { data, error } = await this.context.supabase
        .from("memory_facts")
        .insert(insertData)
        .select("id")
        .single();

      if (error) {
        appLogger.error("Failed to store memory fact:", error);
        return null;
      }

      return data.id;
    } catch (error) {
      appLogger.error("Store fact failed:", error);
      return null;
    }
  }

  /**
   * Search for relevant facts using semantic similarity
   */
  async searchFacts(
    query: string,
    config: LongTermMemoryConfig = {},
  ): Promise<MemoryFactSearchResult[]> {
    const { maxFacts = 10, minImportance = 1 } = config;

    try {
      const factory = getEmbeddingFactory();
      const embeddingResult = await factory.embed(query);

      const { data, error } = await this.context.supabase.rpc(
        "search_memory_facts",
        {
          query_embedding: embeddingResult.vector,
          target_user_id: this.context.userId,
          match_threshold: 0.6,
          match_count: maxFacts,
          min_importance: minImportance,
        },
      );

      if (error) {
        appLogger.error("Search memory facts error:", error);
        return [];
      }

      return (data || []).map((row: unknown) => ({
        id: row.id,
        userId: this.context.userId,
        factType: row.fact_type,
        category: row.category,
        content: row.content,
        importance: row.importance,
        similarity: row.similarity,
        createdAt: new Date(row.created_at),
      }));
    } catch (error) {
      appLogger.error("Search facts failed:", error);
      return [];
    }
  }

  /**
   * Get all facts for the current user
   */
  async getAllFacts(config: LongTermMemoryConfig = {}): Promise<MemoryFact[]> {
    const {
      maxFacts = 100,
      minImportance = 1,
      includeExpired = false,
    } = config;

    try {
      let query = this.context.supabase
        .from("memory_facts")
        .select("*")
        .eq("user_id", this.context.userId)
        .gte("importance", minImportance)
        .order("importance", { ascending: false })
        .limit(maxFacts);

      if (!includeExpired) {
        query = query.or("expires_at.is.null,expires_at.gt.now()");
      }

      const { data, error } = await query;

      if (error) {
        appLogger.error("Get all facts error:", error);
        return [];
      }

      return (data || []).map((row: unknown) => ({
        id: row.id,
        userId: row.user_id,
        factType: row.fact_type,
        category: row.category,
        content: row.content,
        importance: row.importance,
        sourceSessionId: row.source_session_id,
        sourceMessageId: row.source_message_id,
        expiresAt: row.expires_at ? new Date(row.expires_at) : undefined,
      }));
    } catch (error) {
      appLogger.error("Get all facts failed:", error);
      return [];
    }
  }

  /**
   * Get facts by type
   */
  async getFactsByType(
    factType: MemoryFact["factType"],
    limit: number = 20,
  ): Promise<MemoryFact[]> {
    try {
      const { data, error } = await this.context.supabase
        .from("memory_facts")
        .select("*")
        .eq("user_id", this.context.userId)
        .eq("fact_type", factType)
        .or("expires_at.is.null,expires_at.gt.now()")
        .order("importance", { ascending: false })
        .limit(limit);

      if (error) {
        appLogger.error("Get facts by type error:", error);
        return [];
      }

      return (data || []).map((row: unknown) => ({
        id: row.id,
        userId: row.user_id,
        factType: row.fact_type,
        category: row.category,
        content: row.content,
        importance: row.importance,
        sourceSessionId: row.source_session_id,
        sourceMessageId: row.source_message_id,
        expiresAt: row.expires_at ? new Date(row.expires_at) : undefined,
      }));
    } catch (error) {
      appLogger.error("Get facts by type failed:", error);
      return [];
    }
  }

  /**
   * Update a fact's importance
   */
  async updateImportance(factId: string, importance: number): Promise<boolean> {
    try {
      const { error } = await this.context.supabase
        .from("memory_facts")
        .update({ importance: Math.min(10, Math.max(1, importance)) })
        .eq("id", factId)
        .eq("user_id", this.context.userId);

      if (error) {
        appLogger.error("Update importance error:", error);
        return false;
      }

      return true;
    } catch (error) {
      appLogger.error("Update importance failed:", error);
      return false;
    }
  }

  /**
   * Mark a fact as accessed (updates last_accessed_at)
   */
  async markAccessed(factId: string): Promise<void> {
    try {
      await this.context.supabase
        .from("memory_facts")
        .update({ last_accessed_at: new Date().toISOString() })
        .eq("id", factId);
    } catch (error) {
      // Silent fail - not critical
    }
  }

  /**
   * Delete a fact
   */
  async deleteFact(factId: string): Promise<boolean> {
    try {
      const { error } = await this.context.supabase
        .from("memory_facts")
        .delete()
        .eq("id", factId)
        .eq("user_id", this.context.userId);

      if (error) {
        appLogger.error("Delete fact error:", error);
        return false;
      }

      return true;
    } catch (error) {
      appLogger.error("Delete fact failed:", error);
      return false;
    }
  }

  /**
   * Delete all expired facts for the user
   */
  async cleanupExpiredFacts(): Promise<number> {
    try {
      const { data, error } = await this.context.supabase
        .from("memory_facts")
        .delete()
        .eq("user_id", this.context.userId)
        .lt("expires_at", new Date().toISOString())
        .select("id");

      if (error) {
        appLogger.error("Cleanup expired facts error:", error);
        return 0;
      }

      return data?.length || 0;
    } catch (error) {
      appLogger.error("Cleanup expired facts failed:", error);
      return 0;
    }
  }
}

/**
 * Memory Manager
 *
 * Orchestrates all memory types (session, long-term, semantic) to provide
 * relevant context to the agent. This is the main entry point for memory operations.
 */

import { appLogger } from '@/lib/logger';

import { LongTermMemory } from "./long-term";
import { SemanticMemory } from "./semantic";
import { SessionMemory } from "./session";
import type {
  MemoryContext,
  MemoryFact,
  MemoryFactSearchResult,
  MemoryManagerConfig,
  RelevantContext,
  SemanticSearchResult,
} from "./types";

export class MemoryManager {
  private context: MemoryContext;
  private config: MemoryManagerConfig;

  private sessionMemory: SessionMemory;
  private longTermMemory: LongTermMemory;
  private semanticMemory: SemanticMemory;

  constructor(context: MemoryContext, config: MemoryManagerConfig = {}) {
    this.context = context;
    this.config = {
      enableSemanticSearch: config.enableSemanticSearch ?? true,
      enableLongTermMemory: config.enableLongTermMemory ?? true,
      maxContextLength: config.maxContextLength ?? 4000,
      semanticSearchCount: config.semanticSearchCount ?? 5,
    };

    this.sessionMemory = new SessionMemory(context);
    this.longTermMemory = new LongTermMemory(context);
    this.semanticMemory = new SemanticMemory(context);
  }

  /**
   * Get the session memory instance
   */
  getSessionMemory(): SessionMemory {
    return this.sessionMemory;
  }

  /**
   * Get the long-term memory instance
   */
  getLongTermMemory(): LongTermMemory {
    return this.longTermMemory;
  }

  /**
   * Get the semantic memory instance
   */
  getSemanticMemory(): SemanticMemory {
    return this.semanticMemory;
  }

  /**
   * Load session history
   */
  async loadSession(): Promise<void> {
    if (this.context.sessionId) {
      await this.sessionMemory.load();
    }
  }

  /**
   * Get relevant context for a query
   * Combines semantic search results and memory facts
   */
  async getRelevantContext(query: string): Promise<RelevantContext> {
    const semanticResults: SemanticSearchResult[] = [];
    const memoryFacts: MemoryFactSearchResult[] = [];

    // Perform semantic search if enabled
    if (this.config.enableSemanticSearch) {
      try {
        const results = await this.semanticMemory.search(query, {
          matchCount: this.config.semanticSearchCount,
          matchThreshold: 0.65,
        });
        semanticResults.push(...results);
      } catch (error) {
        appLogger.error("Semantic search failed:", error);
      }
    }

    // Search long-term memory if enabled
    if (this.config.enableLongTermMemory) {
      try {
        const facts = await this.longTermMemory.searchFacts(query, {
          maxFacts: 5,
          minImportance: 3,
        });
        memoryFacts.push(...facts);
      } catch (error) {
        appLogger.error("Memory facts search failed:", error);
      }
    }

    // Format context for injection into prompt
    const formattedContext = this.formatContext(semanticResults, memoryFacts);

    return {
      semanticResults,
      memoryFacts,
      formattedContext,
    };
  }

  /**
   * Format context for injection into the system prompt
   */
  private formatContext(
    semanticResults: SemanticSearchResult[],
    memoryFacts: MemoryFactSearchResult[],
  ): string {
    const parts: string[] = [];

    // Add semantic search results
    if (semanticResults.length > 0) {
      parts.push("INFORMACIÓN RELEVANTE DEL SISTEMA:");

      // Group by source type
      const byType = this.groupBySourceType(semanticResults);

      for (const [type, results] of Object.entries(byType)) {
        const typeLabel = this.getSourceTypeLabel(type);
        parts.push(`\n${typeLabel}:`);

        for (const result of results.slice(0, 3)) {
          // Max 3 per type
          parts.push(
            `- ${result.content.substring(0, 200)}${result.content.length > 200 ? "..." : ""}`,
          );
        }
      }
    }

    // Add memory facts
    if (memoryFacts.length > 0) {
      parts.push("\nCONOCIMIENTO PREVIO:");

      for (const fact of memoryFacts) {
        const importance = fact.importance >= 8 ? "⭐" : "";
        parts.push(`- ${importance}${fact.content}`);
      }
    }

    const fullContext = parts.join("\n");

    // Truncate if too long
    if (fullContext.length > this.config.maxContextLength!) {
      return (
        fullContext.substring(0, this.config.maxContextLength! - 3) + "..."
      );
    }

    return fullContext;
  }

  /**
   * Group semantic results by source type
   */
  private groupBySourceType(
    results: SemanticSearchResult[],
  ): Record<string, SemanticSearchResult[]> {
    const grouped: Record<string, SemanticSearchResult[]> = {};

    for (const result of results) {
      if (!grouped[result.sourceType]) {
        grouped[result.sourceType] = [];
      }
      grouped[result.sourceType].push(result);
    }

    return grouped;
  }

  /**
   * Get human-readable label for source type
   */
  private getSourceTypeLabel(type: string): string {
    const labels: Record<string, string> = {
      product: "Productos",
      order: "Pedidos",
      customer: "Clientes",
      category: "Categorías",
      chat_message: "Conversaciones anteriores",
    };
    return labels[type] || type;
  }

  /**
   * Store a new fact in long-term memory
   */
  async rememberFact(
    content: string,
    factType: MemoryFact["factType"] = "context",
    importance: number = 5,
  ): Promise<string | null> {
    return await this.longTermMemory.storeFact({
      userId: this.context.userId,
      factType,
      content,
      importance,
      sourceSessionId: this.context.sessionId,
    });
  }

  /**
   * Index the current session for future semantic search
   */
  async indexCurrentSession(): Promise<void> {
    if (!this.context.sessionId) return;

    try {
      const { MemoryIndexer } = await import("./indexer");
      const indexer = new MemoryIndexer(this.context);
      await indexer.indexChatSession(this.context.sessionId);
    } catch (error) {
      appLogger.error("Failed to index session:", error);
    }
  }

  /**
   * Get a summary of what the agent knows about the user
   */
  async getUserKnowledge(): Promise<{
    factsCount: number;
    facts: MemoryFact[];
    preferences: MemoryFact[];
  }> {
    const allFacts = await this.longTermMemory.getAllFacts({ maxFacts: 50 });
    const preferences = allFacts.filter((f) => f.factType === "preference");

    return {
      factsCount: allFacts.length,
      facts: allFacts,
      preferences,
    };
  }

  /**
   * Clear all memory for the current context
   */
  async clearAll(): Promise<void> {
    this.sessionMemory.clear();

    // Note: Long-term memory and embeddings persist in database
    // and require explicit deletion
  }
}

/**
 * Create a memory manager instance
 */
export function createMemoryManager(
  context: MemoryContext,
  config?: MemoryManagerConfig,
): MemoryManager {
  return new MemoryManager(context, config);
}

/**
 * Location and Currency Resolution
 *
 * Pure functions for resolving location and currency from organization settings.
 * Extracted from OrganizationalMemory to keep the main class thin.
 */

export function countryFromCurrency(code: string): string | null {
  const map: Record<string, string> = {
    CLP: "Chile",
    ARS: "Argentina",
    MXN: "México",
    EUR: "España",
    COP: "Colombia",
    PEN: "Perú",
    USD: "Estados Unidos",
  };
  return map[code] ?? null;
}

export function currencyFromCountry(country: string): string | null {
  const c = country.toLowerCase();
  if (c.includes("chile")) return "CLP";
  if (c.includes("argentina")) return "ARS";
  if (c.includes("méxico") || c.includes("mexico")) return "MXN";
  if (c.includes("españa") || c.includes("espa")) return "EUR";
  if (c.includes("colombia")) return "COP";
  if (c.includes("perú") || c.includes("peru")) return "PEN";
  return null;
}

/**
 * Resolve location and currency from multiple sources (no hardcoding).
 * Priority: 1) organization_settings explicit, 2) system_config, 3) quote_settings, 4) heuristics (phone/address/docType).
 */
export function resolveLocationAndCurrency(settings: Record<string, unknown>): {
  location: string;
  currency: string;
} {
  const phone = String(settings.business_phone || "").trim();
  const address = String(settings.business_address || "").toLowerCase();
  const docType = String(settings.default_document_type || "").toLowerCase();
  const explicitCountry = String(settings.country || "").trim();
  const explicitCurrency = String(settings.currency || "")
    .trim()
    .toUpperCase();

  // 1) Explicit organization_settings (highest priority)
  if (explicitCurrency && explicitCurrency.length >= 3) {
    const country = countryFromCurrency(explicitCurrency);
    return {
      location: explicitCountry || country || "No especificado",
      currency: explicitCurrency,
    };
  }
  if (explicitCountry) {
    const currency = currencyFromCountry(explicitCountry);
    if (currency) {
      return { location: explicitCountry, currency };
    }
  }

  // 2) Heuristics from phone, address, document type
  if (
    phone.startsWith("+56") ||
    address.includes("chile") ||
    docType === "boleta"
  ) {
    return { location: "Chile", currency: "CLP" };
  }
  if (phone.startsWith("+54") || address.includes("argentina")) {
    return { location: "Argentina", currency: "ARS" };
  }
  if (phone.startsWith("+34") || address.includes("españa")) {
    return { location: "España", currency: "EUR" };
  }
  if (
    address.includes("méxico") ||
    address.includes("mexico") ||
    phone.startsWith("+52")
  ) {
    return { location: "México", currency: "MXN" };
  }
  if (phone.startsWith("+57") || address.includes("colombia")) {
    return { location: "Colombia", currency: "COP" };
  }
  if (
    phone.startsWith("+51") ||
    address.includes("perú") ||
    address.includes("peru")
  ) {
    return { location: "Perú", currency: "PEN" };
  }

  return { location: "No especificado", currency: "USD" };
}

/**
 * Organizational Memory System
 *
 * Provides contextual information about each optica to make the AI agent more personalized
 * and knowledgeable about the specific business context.
 *
 * @module lib/ai/memory/organizational
 */

import type { SupabaseClient } from "@supabase/supabase-js";

import { appLogger } from "@/lib/logger";
import type { Database } from "@/types/supabase";

import { resolveLocationAndCurrency } from "./context-resolver";
import {
  getDefaultActivityMetrics,
  getDefaultContext,
  getOrganizationAge,
  getOrganizationData,
  getOrganizationSettings,
  getQuoteSettingsCurrency,
  getRecentOrders,
  getSystemConfigCurrency,
  getTopProducts,
} from "./helpers";

export interface OrganizationalContext {
  name: string;
  specialty: string;
  topProducts: Array<{
    id: string;
    name: string;
    price: number;
    inventory: number;
  }>;
  customerCount: number;
  monthlyOrders: number;
  businessHours: {
    open: string;
    close: string;
  };
  services: string[];
  location: string;
  phone: string;
  email: string;
  website: string;
  currency: string;
  createdAt: string;
}

export interface ActivityMetrics {
  totalOrders: number;
  totalRevenue: number;
  averageOrderValue: number;
  customerRetentionRate: number;
  orderCompletionRate: number;
  monthlyOrders: number;
  weeklyOrders: number;
  dailyOrders: number;
}

export interface MaturityLevel {
  level: "new" | "starting" | "growing" | "established";
  daysSinceCreation: number;
  totalOrders: number;
  totalRevenue: number;
  description: string;
}

export class OrganizationalMemory {
  private organizationId: string;
  private supabase: SupabaseClient<Database>;
  private contextCache: Map<string, OrganizationalContext> = new Map();

  constructor(organizationId: string, supabase: SupabaseClient<Database>) {
    this.organizationId = organizationId;
    this.supabase = supabase;
  }

  /**
   * Get comprehensive organizational context
   */
  async getOrganizationalContext(): Promise<OrganizationalContext> {
    // Check cache first
    const cached = this.contextCache.get(this.organizationId);
    if (cached) {
      return cached;
    }

    try {
      const [
        orgData,
        settingsData,
        productsData,
        ordersData,
        systemCurrency,
        quoteCurrency,
      ] = await Promise.all([
        getOrganizationData(this.supabase, this.organizationId),
        getOrganizationSettings(this.supabase, this.organizationId),
        getTopProducts(this.supabase, this.organizationId),
        getRecentOrders(this.supabase, this.organizationId),
        getSystemConfigCurrency(this.supabase, this.organizationId),
        getQuoteSettingsCurrency(this.supabase, this.organizationId),
      ]);

      const settings = (settingsData || {}) as Record<string, unknown>;

      // Resolve location/currency: explicit settings > system_config > quote_settings > heuristics
      const { location, currency } = resolveLocationAndCurrency(settings);
      if (currency === "USD" && systemCurrency) currency = systemCurrency;
      if (currency === "USD" && quoteCurrency) currency = quoteCurrency;

      const context: OrganizationalContext = {
        // @ts-expect-error: Dynamic LLM response shape
        name: orgData.name,
        specialty: "Óptica General",
        topProducts: productsData,
        customerCount: 0,
        monthlyOrders: ordersData.monthly || 0,
        businessHours: {
          open: "09:00",
          close: "18:00",
        },
        services: [],
        location: location,
        phone:
          (typeof settings.business_phone === "string"
            ? settings.business_phone
            : "") || "No especificado",
        email:
          (typeof settings.business_email === "string"
            ? settings.business_email
            : "") || "No especificado",
        website: "No especificado",
        currency: currency,
        // @ts-expect-error: Dynamic LLM response shape
        createdAt: orgData.created_at || new Date().toISOString(),
      };

      // Cache the result
      this.contextCache.set(this.organizationId, context);

      return context;
    } catch (error) {
      appLogger.error("Error getting organizational context:", error);
      // Return default context on error
      return getDefaultContext();
    }
  }

  /**
   * Get activity metrics for the organization
   */
  async getActivityMetrics(): Promise<ActivityMetrics> {
    try {
      const { data, error } = await this.supabase
        .from("organizations")
        .select(
          `
          id,
          name,
          created_at
        `,
        )
        .eq("id", this.organizationId)
        .single();

      if (error || !data) {
        throw error;
      }

      return {
        totalOrders: 0,
        totalRevenue: 0,
        averageOrderValue: 0,
        customerRetentionRate: 0,
        orderCompletionRate: 0,
        monthlyOrders: 0,
        weeklyOrders: 0,
        dailyOrders: 0,
      };
    } catch (error) {
      appLogger.error("Error getting activity metrics:", error);
      return getDefaultActivityMetrics();
    }
  }

  /**
   * Calculate organizational maturity level
   */
  async getMaturityLevel(): Promise<MaturityLevel> {
    const [age, activity] = await Promise.all([
      getOrganizationAge(this.supabase, this.organizationId),
      this.getActivityMetrics(),
    ]);

    let level: MaturityLevel["level"] = "new";
    let description = "";

    if (age < 7) {
      level = "new";
      description = "Óptica nueva (menos de 7 días o sin órdenes)";
    } else if (age < 30 || activity.totalOrders < 10) {
      level = "starting";
      description = `Óptica en fase inicial (${age} días, ${activity.totalOrders} órdenes)`;
    } else if (age < 90 || activity.totalOrders < 50) {
      level = "growing";
      description = `Óptica en crecimiento (${age} días, ${activity.totalOrders} órdenes)`;
    } else {
      level = "established";
      description = `Óptica establecida (${age} días, ${activity.totalOrders} órdenes)`;
    }

    return {
      level,
      daysSinceCreation: age,
      totalOrders: activity.totalOrders,
      totalRevenue: activity.totalRevenue,
      description,
    };
  }

  /**
   * Get context for AI agent
   */
  async getContextForAgent(): Promise<{
    organization: OrganizationalContext;
    activity: ActivityMetrics;
    maturity: MaturityLevel;
  }> {
    const [organization, activity, maturity] = await Promise.all([
      this.getOrganizationalContext(),
      this.getActivityMetrics(),
      this.getMaturityLevel(),
    ]);

    return {
      organization,
      activity,
      maturity,
    };
  }

  /**
   * Clear cache for a specific organization
   */
  clearCache(): void {
    this.contextCache.delete(this.organizationId);
  }

  /**
   * Clear all cache
   */
  clearAllCache(): void {
    this.contextCache.clear();
  }
}

/**
 * Create organizational memory instance
 */
export function createOrganizationalMemory(
  organizationId: string,
  supabase: SupabaseClient<Database>,
): OrganizationalMemory {
  return new OrganizationalMemory(organizationId, supabase);
}

/**
 * Semantic Memory Service
 *
 * Provides semantic search capabilities using vector embeddings.
 * Searches across all indexed content (products, orders, customers, chat messages).
 */

import { appLogger } from '@/lib/logger';

import { getEmbeddingFactory } from "../embeddings";
import type {
  EmbeddingRecord,
  MemoryContext,
  SemanticSearchOptions,
  SemanticSearchResult,
} from "./types";

export class SemanticMemory {
  private context: MemoryContext;

  constructor(context: MemoryContext) {
    this.context = context;
  }

  /**
   * Search for semantically similar content
   */
  async search(
    query: string,
    options: SemanticSearchOptions = {},
  ): Promise<SemanticSearchResult[]> {
    const {
      sourceTypes,
      matchThreshold = 0.7,
      matchCount = 10,
      userId,
    } = options;

    try {
      const factory = getEmbeddingFactory();
      const embeddingResult = await factory.embed(query);

      // Determine which search function to use based on provider
      const searchFunction =
        embeddingResult.provider === "transformers"
          ? "search_embeddings_small"
          : "search_embeddings";

      const { data, error } = await this.context.supabase.rpc(searchFunction, {
        query_embedding: embeddingResult.vector,
        match_threshold: matchThreshold,
        match_count: matchCount,
        filter_source_types: sourceTypes || null,
        filter_user_id: userId || null,
      });

      if (error) {
        appLogger.error("Semantic search error:", error);
        throw error;
      }

      return (data || []).map((row: unknown) => ({
        id: row.id,
        sourceType: row.source_type,
        sourceId: row.source_id,
        content: row.content,
        similarity: row.similarity,
        metadata: row.metadata,
        createdAt: new Date(row.created_at),
      }));
    } catch (error) {
      appLogger.error("Semantic search failed:", error);
      return [];
    }
  }

  /**
   * Store an embedding for later retrieval
   */
  async storeEmbedding(record: EmbeddingRecord): Promise<string | null> {
    try {
      const factory = getEmbeddingFactory();
      const embeddingResult = await factory.embed(record.content);

      const insertData: unknown = {
        source_type: record.sourceType,
        source_id: record.sourceId,
        content: record.content,
        embedding_provider: embeddingResult.provider,
        user_id: record.userId || null,
        metadata: record.metadata || null,
      };

      // Store in appropriate column based on provider
      if (embeddingResult.provider === "transformers") {
        insertData.embedding_small = embeddingResult.vector;
      } else {
        insertData.embedding = embeddingResult.vector;
      }

      const { data, error } = await this.context.supabase
        .from("embeddings")
        .insert(insertData)
        .select("id")
        .single();

      if (error) {
        appLogger.error("Failed to store embedding:", error);
        return null;
      }

      return data.id;
    } catch (error) {
      appLogger.error("Store embedding failed:", error);
      return null;
    }
  }

  /**
   * Store multiple embeddings efficiently
   */
  async storeEmbeddingBatch(records: EmbeddingRecord[]): Promise<number> {
    if (records.length === 0) return 0;

    try {
      const factory = getEmbeddingFactory();
      const contents = records.map((r) => r.content);
      const batchResult = await factory.embedBatch(contents);

      const insertData = records.map((record, index) => {
        const emb = batchResult.embeddings[index];
        const data: unknown = {
          source_type: record.sourceType,
          source_id: record.sourceId,
          content: record.content,
          embedding_provider: emb.provider,
          user_id: record.userId || null,
          metadata: record.metadata || null,
        };

        if (emb.provider === "transformers") {
          data.embedding_small = emb.vector;
        } else {
          data.embedding = emb.vector;
        }

        return data;
      });

      const { error } = await this.context.supabase
        .from("embeddings")
        .insert(insertData);

      if (error) {
        appLogger.error("Failed to store embedding batch:", error);
        return 0;
      }

      return records.length;
    } catch (error) {
      appLogger.error("Store embedding batch failed:", error);
      return 0;
    }
  }

  /**
   * Update or create embedding for a source
   */
  async upsertEmbedding(record: EmbeddingRecord): Promise<boolean> {
    try {
      // First, delete existing embedding for this source
      await this.context.supabase
        .from("embeddings")
        .delete()
        .eq("source_type", record.sourceType)
        .eq("source_id", record.sourceId);

      // Then insert new one
      const id = await this.storeEmbedding(record);
      return id !== null;
    } catch (error) {
      appLogger.error("Upsert embedding failed:", error);
      return false;
    }
  }

  /**
   * Delete embeddings for a source
   */
  async deleteEmbedding(
    sourceType: string,
    sourceId: string,
  ): Promise<boolean> {
    try {
      const { error } = await this.context.supabase
        .from("embeddings")
        .delete()
        .eq("source_type", sourceType)
        .eq("source_id", sourceId);

      if (error) {
        appLogger.error("Delete embedding failed:", error);
        return false;
      }

      return true;
    } catch (error) {
      appLogger.error("Delete embedding failed:", error);
      return false;
    }
  }

  /**
   * Check if an embedding exists for a source
   */
  async hasEmbedding(sourceType: string, sourceId: string): Promise<boolean> {
    try {
      const { data, error } = await this.context.supabase
        .from("embeddings")
        .select("id")
        .eq("source_type", sourceType)
        .eq("source_id", sourceId)
        .limit(1);

      if (error) {
        appLogger.error("Check embedding failed:", error);
        return false;
      }

      return data && data.length > 0;
    } catch (error) {
      appLogger.error("Check embedding failed:", error);
      return false;
    }
  }
}

/**
 * Session Memory Service
 *
 * Manages the current conversation context.
 * Loads and stores conversation history from the database.
 */

import { appLogger } from '@/lib/logger';

import type {
  MemoryContext,
  SessionMemoryConfig,
  SessionMessage,
} from "./types";

export class SessionMemory {
  private context: MemoryContext;
  private messages: SessionMessage[] = [];
  private loaded = false;

  constructor(context: MemoryContext) {
    this.context = context;
  }

  /**
   * Load conversation history from database
   */
  async load(config: SessionMemoryConfig = {}): Promise<SessionMessage[]> {
    const { maxMessages = 50, includeToolMessages = true } = config;

    if (!this.context.sessionId) {
      appLogger.info("No session ID provided, starting fresh conversation");
      this.loaded = true;
      return [];
    }

    try {
      let query = this.context.supabase
        .from("chat_messages")
        .select("id, role, content, tool_calls, metadata, created_at")
        .eq("session_id", this.context.sessionId)
        .order("created_at", { ascending: true })
        .limit(maxMessages);

      if (!includeToolMessages) {
        query = query.neq("role", "tool");
      }

      const { data, error } = await query;

      if (error) {
        appLogger.error("Failed to load session history:", error);
        this.loaded = true;
        return [];
      }

      this.messages = (data || []).map((row: unknown) => ({
        role: row.role as SessionMessage["role"],
        content: row.content || "",
        toolCalls: row.tool_calls || row.metadata?.toolCalls,
        metadata: row.metadata,
        createdAt: new Date(row.created_at),
      }));

      this.loaded = true;
      appLogger.info(`Loaded ${this.messages.length} messages from session`);

      return this.messages;
    } catch (error) {
      appLogger.error("Load session history failed:", error);
      this.loaded = true;
      return [];
    }
  }

  /**
   * Get all loaded messages
   */
  getMessages(): SessionMessage[] {
    return [...this.messages];
  }

  /**
   * Check if history has been loaded
   */
  isLoaded(): boolean {
    return this.loaded;
  }

  /**
   * Get message count
   */
  getMessageCount(): number {
    return this.messages.length;
  }

  /**
   * Add a message to the in-memory history
   * Note: This doesn't persist to database - that's handled by the API route
   */
  addMessage(message: SessionMessage): void {
    this.messages.push(message);
  }

  /**
   * Get recent messages (last N)
   */
  getRecentMessages(count: number): SessionMessage[] {
    return this.messages.slice(-count);
  }

  /**
   * Get messages by role
   */
  getMessagesByRole(role: SessionMessage["role"]): SessionMessage[] {
    return this.messages.filter((m) => m.role === role);
  }

  /**
   * Clear in-memory messages
   */
  clear(): void {
    this.messages = [];
    this.loaded = false;
  }

  /**
   * Get a summary of the conversation
   * Useful for condensing long conversations
   */
  getSummary(): string {
    const userMessages = this.getMessagesByRole("user");
    const assistantMessages = this.getMessagesByRole("assistant");

    const topics = userMessages
      .map((m) => m.content.substring(0, 100))
      .slice(-5); // Last 5 topics

    return (
      `Conversation with ${this.messages.length} messages. ` +
      `User messages: ${userMessages.length}, Assistant responses: ${assistantMessages.length}. ` +
      `Recent topics: ${topics.join("; ")}`
    );
  }

  /**
   * Check if conversation contains a specific topic/keyword
   */
  hasDiscussed(keyword: string): boolean {
    const lowerKeyword = keyword.toLowerCase();
    return this.messages.some((m) =>
      m.content.toLowerCase().includes(lowerKeyword),
    );
  }

  /**
   * Get the last message
   */
  getLastMessage(): SessionMessage | null {
    return this.messages.length > 0
      ? this.messages[this.messages.length - 1]
      : null;
  }

  /**
   * Get the last user message
   */
  getLastUserMessage(): SessionMessage | null {
    for (let i = this.messages.length - 1; i >= 0; i--) {
      if (this.messages[i].role === "user") {
        return this.messages[i];
      }
    }
    return null;
  }

  /**
   * Get the last assistant message
   */
  getLastAssistantMessage(): SessionMessage | null {
    for (let i = this.messages.length - 1; i >= 0; i--) {
      if (this.messages[i].role === "assistant") {
        return this.messages[i];
      }
    }
    return null;
  }
}

import type {
  LLMConfig,
  LLMMessage,
  LLMModel,
  LLMProvider,
  LLMResponse,
  LLMStreamChunk,
  LLMTool,
} from "../types";
import { BaseLLMProvider } from "./base";

export class AnthropicProvider extends BaseLLMProvider {
  name: LLMProvider = "anthropic";

  private readonly models: LLMModel[] = [
    {
      id: "claude-3-opus-20240229",
      name: "Claude 3 Opus",
      provider: "anthropic",
      maxTokens: 200000,
      supportsStreaming: true,
      supportsFunctionCalling: true,
      costPer1kTokens: { input: 0.015, output: 0.075 },
    },
    {
      id: "claude-3-sonnet-20240229",
      name: "Claude 3 Sonnet",
      provider: "anthropic",
      maxTokens: 200000,
      supportsStreaming: true,
      supportsFunctionCalling: true,
      costPer1kTokens: { input: 0.003, output: 0.015 },
    },
    {
      id: "claude-3-haiku-20240307",
      name: "Claude 3 Haiku",
      provider: "anthropic",
      maxTokens: 200000,
      supportsStreaming: true,
      supportsFunctionCalling: true,
      costPer1kTokens: { input: 0.00025, output: 0.00125 },
    },
  ];

  getAvailableModels(): LLMModel[] {
    return this.models;
  }

  validateConfig(config: LLMConfig): boolean {
    return (
      this.validateApiKey(config.apiKey) &&
      this.models.some((m) => m.id === config.model)
    );
  }

  async *streamText(
    messages: LLMMessage[],
    tools?: LLMTool[],
    config?: Partial<LLMConfig>,
  ): AsyncGenerator<LLMStreamChunk> {
    const apiKey = config?.apiKey || process.env.ANTHROPIC_API_KEY;
    if (!apiKey) {
      throw new Error("Anthropic API key is required");
    }

    const model = config?.model || "claude-3-sonnet-20240229";
    const baseURL = "https://api.anthropic.com/v1/messages";

    const systemMessage = messages.find((m) => m.role === "system");
    const userMessages = messages.filter((m) => m.role !== "system");

    const response = await fetch(baseURL, {
      method: "POST",
      headers: {
        "x-api-key": apiKey,
        "anthropic-version": "2023-06-01",
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model,
        ...(systemMessage && { system: systemMessage.content }),
        messages: userMessages.map((m) => ({
          role: m.role === "assistant" ? "assistant" : "user",
          content: m.content,
        })),
        ...(tools && {
          tools: tools.map((t) => ({
            name: t.function.name,
            description: t.function.description,
            input_schema: t.function.parameters,
          })),
        }),
        temperature: config?.temperature ?? 0.7,
        max_tokens: config?.maxTokens ?? 4096,
        stream: true,
      }),
    });

    if (!response.ok) {
      const error = await response
        .json()
        .catch(() => ({ error: { message: response.statusText } }));
      throw new Error(
        `Anthropic API error: ${error.error?.message || response.statusText}`,
      );
    }

    const reader = response.body?.getReader();
    if (!reader) {
      throw new Error("Failed to get response stream");
    }

    const decoder = new TextDecoder();
    let buffer = "";

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split("\n");
      buffer = lines.pop() || "";

      for (const line of lines) {
        if (line.startsWith("data: ")) {
          const data = line.slice(6).trim();
          if (data === "[DONE]") {
            yield { content: "", done: true };
            return;
          }

          try {
            const parsed = JSON.parse(data);
            if (parsed.type === "content_block_delta") {
              const text = parsed.delta?.text;
              if (text) {
                yield {
                  content: text,
                  done: false,
                };
              }
            }
          } catch (e) {
            // Skip invalid JSON
          }
        }
      }
    }

    yield { content: "", done: true };
  }

  async generateText(
    messages: LLMMessage[],
    tools?: LLMTool[],
    config?: Partial<LLMConfig>,
  ): Promise<LLMResponse> {
    const apiKey = config?.apiKey || process.env.ANTHROPIC_API_KEY;
    if (!apiKey) {
      throw new Error("Anthropic API key is required");
    }

    const model = config?.model || "claude-3-sonnet-20240229";
    const baseURL = "https://api.anthropic.com/v1/messages";

    const systemMessage = messages.find((m) => m.role === "system");
    const userMessages = messages.filter((m) => m.role !== "system");

    const response = await fetch(baseURL, {
      method: "POST",
      headers: {
        "x-api-key": apiKey,
        "anthropic-version": "2023-06-01",
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model,
        ...(systemMessage && { system: systemMessage.content }),
        messages: userMessages.map((m) => ({
          role: m.role === "assistant" ? "assistant" : "user",
          content: m.content,
        })),
        ...(tools && {
          tools: tools.map((t) => ({
            name: t.function.name,
            description: t.function.description,
            input_schema: t.function.parameters,
          })),
        }),
        temperature: config?.temperature ?? 0.7,
        max_tokens: config?.maxTokens ?? 4096,
      }),
    });

    if (!response.ok) {
      const error = await response
        .json()
        .catch(() => ({ error: { message: response.statusText } }));
      throw new Error(
        `Anthropic API error: ${error.error?.message || response.statusText}`,
      );
    }

    const data = await response.json();
    const content = data.content?.[0]?.text || "";

    return {
      content,
      usage: data.usage
        ? {
            promptTokens: data.usage.input_tokens,
            completionTokens: data.usage.output_tokens,
            totalTokens: data.usage.input_tokens + data.usage.output_tokens,
          }
        : undefined,
      finishReason: data.stop_reason,
      model: data.model,
    };
  }
}

import { appLogger } from '@/lib/logger';

import type {
  LLMConfig,
  LLMMessage,
  LLMStreamChunk,
  LLMTool,
  ToolCall,
} from "../../types";
import { formatMessages } from "./helpers";

export async function* streamText(
  messages: LLMMessage[],
  tools?: LLMTool[],
  config?: Partial<LLMConfig>,
): AsyncGenerator<LLMStreamChunk> {
  const apiKey = config?.apiKey || process.env.DEEPSEEK_API_KEY;
  if (!apiKey) {
    throw new Error("DeepSeek API key is required");
  }

  const baseURL = config?.baseURL || "https://api.deepseek.com/v1";
  const model = config?.model || "deepseek-chat";

  const requestBody = {
    model,
    messages: formatMessages(messages),
    ...(tools && { tools }),
    temperature: config?.temperature ?? 0.7,
    max_tokens: config?.maxTokens,
    stream: true,
  };

  // Log the tools being sent to DeepSeek
  if (tools) {
    appLogger.info("DeepSeek request - tools count:", tools.length);
    appLogger.info(
      "DeepSeek request - tool names:",
      tools.map((t) => t.function?.name).join(", "),
    );
    // Log first tool schema as example
    if (tools[0]) {
      appLogger.info(
        "DeepSeek request - sample tool:",
        JSON.stringify(tools[0], null, 2).substring(0, 500),
      );
    }
  }

  const response = await fetch(`${baseURL}/chat/completions`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${apiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify(requestBody),
  });

  if (!response.ok) {
    const error = await response
      .json()
      .catch(() => ({ error: { message: response.statusText } }));
    throw new Error(
      `DeepSeek API error: ${error.error?.message || response.statusText}`,
    );
  }

  const reader = response.body?.getReader();
  if (!reader) {
    throw new Error("Failed to get response stream");
  }

  const decoder = new TextDecoder();
  let buffer = "";

  // Accumulate tool calls by ID to handle incremental streaming
  const accumulatedToolCalls = new Map<
    string,
    { id: string; name: string; argumentsBuffer: string }
  >();

  while (true) {
    const { done, value } = await reader.read();
    if (done) {
      appLogger.info("=== DEEPSEEK STREAM ENDED (reader.done) ===");
      // Process any remaining accumulated tool calls
      const finalToolCalls: ToolCall[] = [];
      appLogger.info(
        "Accumulated tool calls at stream end:",
        accumulatedToolCalls.size,
      );

      for (const [id, acc] of accumulatedToolCalls.entries()) {
        appLogger.info("Processing at stream end:", {
          id,
          name: acc.name,
          bufferLength: acc.argumentsBuffer.length,
          bufferContent: acc.argumentsBuffer,
        });

        // Only require name - arguments can be empty for some tools
        if (acc.name && acc.name.trim()) {
          let args = {};
          if (acc.argumentsBuffer && acc.argumentsBuffer.trim()) {
            try {
              args = JSON.parse(acc.argumentsBuffer);
              appLogger.info("Parsed args at stream end:", args);
            } catch (e) {
              appLogger.warn(
                "Failed to parse tool arguments:",
                acc.argumentsBuffer,
              );
              // Keep as empty object
            }
          }
          finalToolCalls.push({
            id: acc.id,
            name: acc.name.trim(),
            arguments: args,
          });
        }
      }

      if (finalToolCalls.length > 0) {
        appLogger.info(
          "Yielding stream end tool calls:",
          finalToolCalls.map((tc) => ({
            name: tc.name,
            args: tc.arguments,
          })),
        );
        yield {
          content: "",
          done: false,
          toolCalls: finalToolCalls,
        };
      }

      yield { content: "", done: true };
      return;
    }

    buffer += decoder.decode(value, { stream: true });
    const lines = buffer.split("\n");
    buffer = lines.pop() || "";

    for (const line of lines) {
      if (line.startsWith("data: ")) {
        const data = line.slice(6).trim();
        if (data === "[DONE]") {
          // Process accumulated tool calls before finishing
          const finalToolCalls: ToolCall[] = [];
          appLogger.info("=== DEEPSEEK [DONE] PROCESSING ===");
          appLogger.info(
            "Accumulated tool calls map size:",
            accumulatedToolCalls.size,
          );

          for (const [id, acc] of accumulatedToolCalls.entries()) {
            appLogger.info("Processing accumulated:", {
              id,
              name: acc.name,
              argumentsBufferLength: acc.argumentsBuffer.length,
              argumentsBufferRaw: acc.argumentsBuffer,
            });

            // Only require name - arguments can be empty for some tools
            if (acc.name && acc.name.trim()) {
              let args = {};
              if (acc.argumentsBuffer && acc.argumentsBuffer.trim()) {
                try {
                  args = JSON.parse(acc.argumentsBuffer);
                  appLogger.info("Parsed arguments successfully:", args);
                } catch (e) {
                  appLogger.warn(
                    "Failed to parse tool arguments on [DONE]:",
                    acc.argumentsBuffer,
                  );
                  // Try to extract key-value pairs manually if JSON parse fails
                  try {
                    // Sometimes LLMs send malformed JSON, try to fix common issues
                    const cleaned = acc.argumentsBuffer.trim();
                    if (cleaned.startsWith("{") && !cleaned.endsWith("}")) {
                      args = JSON.parse(cleaned + "}");
                      appLogger.info("Parsed with added closing brace:", args);
                    }
                  } catch (e2) {
                    appLogger.warn("Could not recover arguments:", e2);
                  }
                }
              }
              appLogger.info("Final tool call:", { name: acc.name, args });
              finalToolCalls.push({
                id: acc.id,
                name: acc.name.trim(),
                arguments: args,
              });
            }
          }
          appLogger.info("=================================");

          if (finalToolCalls.length > 0) {
            appLogger.info("=== DEEPSEEK FINAL TOOL CALLS ===");
            for (const tc of finalToolCalls) {
              appLogger.info("Tool call:", tc.name);
              appLogger.info(
                "Tool arguments:",
                JSON.stringify(tc.arguments, null, 2),
              );
            }
            appLogger.info("================================");
            yield {
              content: "",
              done: false,
              toolCalls: finalToolCalls,
            };
          }

          yield { content: "", done: true };
          return;
        }

        try {
          const parsed = JSON.parse(data);
          const choice = parsed.choices?.[0];
          const delta = choice?.delta;
          const finishReason = choice?.finish_reason;

          // Log if this is a finish chunk
          if (finishReason) {
            appLogger.info("DeepSeek finish_reason:", finishReason);
            appLogger.info(
              "DeepSeek accumulated tool calls at finish:",
              Array.from(accumulatedToolCalls.entries()).map(([id, acc]) => ({
                id,
                name: acc.name,
                argsLength: acc.argumentsBuffer.length,
                argsPreview: acc.argumentsBuffer.substring(0, 100),
              })),
            );
          }

          // Log raw chunk for debugging
          if (delta?.tool_calls) {
            appLogger.info("DeepSeek RAW chunk:", data.substring(0, 500));
          }

          if (delta?.content) {
            yield {
              content: delta.content,
              done: false,
            };
          }

          if (delta?.tool_calls) {
            appLogger.info(
              "DeepSeek tool_calls delta:",
              JSON.stringify(delta.tool_calls, null, 2),
            );
            // Accumulate tool calls incrementally
            for (const tc of delta.tool_calls) {
              appLogger.info("DeepSeek processing tc:", JSON.stringify(tc));

              // IMPORTANT: DeepSeek sends id only in the first chunk, subsequent chunks only have index
              // We MUST use index as the primary key to accumulate all chunks together
              const tcIndex = tc.index !== undefined ? tc.index : 0;
              const mapKey = `index-${tcIndex}`; // Always use index as key

              if (!accumulatedToolCalls.has(mapKey)) {
                accumulatedToolCalls.set(mapKey, {
                  id: tc.id || `tool-${tcIndex}`,
                  name: "",
                  argumentsBuffer: "",
                });
                appLogger.info(
                  "DeepSeek created new tool accumulator for index:",
                  tcIndex,
                );
              }

              const acc = accumulatedToolCalls.get(mapKey)!;

              // Update ID if we get a real one (first chunk has the real id)
              if (tc.id) {
                acc.id = tc.id;
                appLogger.info("DeepSeek set tool call ID to:", tc.id);
              }

              // Accumulate name (comes in first chunk)
              if (tc.function?.name) {
                acc.name = tc.function.name.trim();
                appLogger.info("DeepSeek tool name received:", acc.name);
              }

              // Accumulate arguments (may come in multiple chunks as string)
              if (
                tc.function?.arguments !== undefined &&
                tc.function?.arguments !== null
              ) {
                const argValue = tc.function.arguments;
                appLogger.info(
                  "DeepSeek raw arguments value:",
                  JSON.stringify(argValue),
                  "type:",
                  typeof argValue,
                );

                if (typeof argValue === "string") {
                  acc.argumentsBuffer += argValue;
                } else if (typeof argValue === "object") {
                  // If it's already an object, convert to string and append
                  acc.argumentsBuffer += JSON.stringify(argValue);
                }
                appLogger.info(
                  "DeepSeek arguments buffer now:",
                  acc.argumentsBuffer,
                );
              }

              appLogger.info("DeepSeek accumulator state:", {
                key: mapKey,
                id: acc.id,
                name: acc.name,
                argsLen: acc.argumentsBuffer.length,
              });
            }
          }
        } catch (e) {
          appLogger.warn("DeepSeek JSON parse error:", e);
          // Skip invalid JSON
        }
      }
    }
  }
}

import type {
  LLMConfig,
  LLMMessage,
  LLMResponse,
  LLMTool,
  ToolCall,
} from "../../types";
import { formatMessages } from "./helpers";

export async function generateText(
  messages: LLMMessage[],
  tools?: LLMTool[],
  config?: Partial<LLMConfig>,
): Promise<LLMResponse> {
  const apiKey = config?.apiKey || process.env.DEEPSEEK_API_KEY;
  if (!apiKey) {
    throw new Error("DeepSeek API key is required");
  }

  const baseURL = config?.baseURL || "https://api.deepseek.com/v1";
  const model = config?.model || "deepseek-chat";

  const response = await fetch(`${baseURL}/chat/completions`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${apiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      model,
      messages: formatMessages(messages),
      ...(tools && { tools }),
      temperature: config?.temperature ?? 0.7,
      max_tokens: config?.maxTokens,
    }),
  });

  if (!response.ok) {
    const error = await response
      .json()
      .catch(() => ({ error: { message: response.statusText } }));
    throw new Error(
      `DeepSeek API error: ${error.error?.message || response.statusText}`,
    );
  }

  const data = await response.json();
  const choice = data.choices[0];
  const message = choice.message;

  const toolCalls: ToolCall[] = [];
  if (message.tool_calls) {
    for (const tc of message.tool_calls) {
      let args = {};
      try {
        // Handle both string and object arguments
        const argValue = tc.function?.arguments;
        if (typeof argValue === "string") {
          args = argValue ? JSON.parse(argValue) : {};
        } else if (argValue) {
          args = argValue;
        }
      } catch (e) {
        // If parsing fails, use empty object
      }

      const toolName = tc.function?.name?.trim() || "";

      // Only include tool calls with valid names
      if (toolName) {
        toolCalls.push({
          id: tc.id || crypto.randomUUID(),
          name: toolName,
          arguments: args,
        });
      }
    }
  }

  return {
    content: message.content || "",
    usage: data.usage
      ? {
          promptTokens: data.usage.prompt_tokens,
          completionTokens: data.usage.completion_tokens,
          totalTokens: data.usage.total_tokens,
        }
      : undefined,
    finishReason: choice.finish_reason,
    model: data.model,
    toolCalls: toolCalls.length > 0 ? toolCalls : undefined,
  };
}

import { appLogger } from '@/lib/logger';

import type {
  LLMConfig,
  LLMMessage,
  LLMModel,
  LLMProvider,
  LLMResponse,
  LLMStreamChunk,
  LLMTool,
  ToolCall,
} from "../types";
import { BaseLLMProvider } from "./base";

export class GoogleProvider extends BaseLLMProvider {
  name: LLMProvider = "google";

  private readonly models: LLMModel[] = [
    {
      id: "gemini-2.5-flash",
      name: "Gemini 2.5 Flash",
      provider: "google",
      maxTokens: 32768,
      supportsStreaming: true,
      supportsFunctionCalling: true,
      costPer1kTokens: { input: 0.0005, output: 0.0015 },
    },
    {
      id: "gemini-pro",
      name: "Gemini Pro",
      provider: "google",
      maxTokens: 32768,
      supportsStreaming: true,
      supportsFunctionCalling: true,
      costPer1kTokens: { input: 0.0005, output: 0.0015 },
    },
    {
      id: "gemini-pro-vision",
      name: "Gemini Pro Vision",
      provider: "google",
      maxTokens: 16384,
      supportsStreaming: true,
      supportsFunctionCalling: false,
      costPer1kTokens: { input: 0.0005, output: 0.0015 },
    },
  ];

  getAvailableModels(): LLMModel[] {
    return this.models;
  }

  validateConfig(config: LLMConfig): boolean {
    return (
      this.validateApiKey(config.apiKey) &&
      this.models.some((m) => m.id === config.model)
    );
  }

  private formatMessagesForGemini(messages: LLMMessage[]): unknown[] {
    return messages.map((msg) => {
      if (msg.role === "tool") {
        // Tool responses in Gemini format
        return {
          role: "function",
          parts: [
            {
              functionResponse: {
                name: msg.name || "",
                response: msg.content,
              },
            },
          ],
        };
      }

      const role =
        msg.role === "assistant"
          ? "model"
          : msg.role === "system"
            ? "user"
            : msg.role;
      return {
        role,
        parts: [{ text: msg.content }],
      };
    });
  }

  async *streamText(
    messages: LLMMessage[],
    tools?: LLMTool[],
    config?: Partial<LLMConfig>,
  ): AsyncGenerator<LLMStreamChunk> {
    const apiKey = config?.apiKey || process.env.GOOGLE_API_KEY;
    if (!apiKey) {
      throw new Error("Google API key is required");
    }

    const model = config?.model || "gemini-2.5-flash";
    // Use v1beta for all Gemini models including 2.5-flash
    const baseURL = `https://generativelanguage.googleapis.com/v1beta/models/${model}:streamGenerateContent`;

    const systemMessage = messages.find((m) => m.role === "system");
    const userMessages = messages.filter((m) => m.role !== "system");

    const functionDeclarations = tools
      ? tools.map((t) => ({
          name: t.function.name,
          description: t.function.description,
          parameters: t.function.parameters,
        }))
      : undefined;

    const response = await fetch(`${baseURL}?key=${apiKey}`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        contents: this.formatMessagesForGemini(userMessages),
        ...(systemMessage && {
          systemInstruction: { parts: [{ text: systemMessage.content }] },
        }),
        ...(functionDeclarations &&
          functionDeclarations.length > 0 && {
            tools: [{ functionDeclarations }],
          }),
      }),
    });

    if (!response.ok) {
      const error = await response
        .json()
        .catch(() => ({ error: { message: response.statusText } }));
      throw new Error(
        `Google API error: ${error.error?.message || response.statusText}`,
      );
    }

    const reader = response.body?.getReader();
    if (!reader) {
      throw new Error("Failed to get response stream");
    }

    const decoder = new TextDecoder();
    let buffer = "";
    let jsonBuffer = "";
    let braceCount = 0;
    let inString = false;
    let escapeNext = false;

    const processCompleteJSON = (jsonStr: string) => {
      try {
        const parsed = JSON.parse(jsonStr);

        // Check for errors first
        if (parsed.error) {
          appLogger.error("Gemini API error:", parsed.error);
          throw new Error(
            `Gemini API error: ${parsed.error.message || JSON.stringify(parsed.error)}`,
          );
        }

        // Handle different response formats
        const candidate = parsed.candidates?.[0] || parsed.candidate;
        const content = candidate?.content;
        const finishReason = candidate?.finishReason;

        // Process content first, even if finishReason is present
        // (the finishReason might be in the same chunk as the last text)
        let textContent = "";
        const toolCalls: ToolCall[] = [];

        if (content?.parts) {
          for (const part of content.parts) {
            if (part.text) {
              textContent += part.text;
            }
            if (part.functionCall) {
              toolCalls.push({
                id: crypto.randomUUID(),
                name: part.functionCall.name,
                arguments: part.functionCall.args || {},
              });
            }
          }
        }

        // Check if stream is done AFTER processing content
        // Only mark as done if finishReason is STOP, MAX_TOKENS, or SAFETY
        if (
          finishReason &&
          (finishReason === "STOP" ||
            finishReason === "MAX_TOKENS" ||
            finishReason === "SAFETY")
        ) {
          appLogger.info(
            "Stream finished with reason:",
            finishReason,
            "Final text length:",
            textContent.length,
          );
          return { done: true, text: textContent, toolCalls };
        }

        // Return content if we have any
        if (textContent || toolCalls.length > 0) {
          return { done: false, text: textContent, toolCalls };
        }

        return null;
      } catch (e) {
        // If it's an error we threw, re-throw it
        if (e instanceof Error && e.message.includes("Gemini API error")) {
          throw e;
        }
        // Otherwise, ignore parse errors
        return null;
      }
    };

    while (true) {
      const { done, value } = await reader.read();
      if (done) {
        // Try to parse any remaining buffer
        if (jsonBuffer.trim()) {
          const result = processCompleteJSON(jsonBuffer);
          if (result) {
            if (result.text) {
              yield { content: result.text, done: false };
            }
            if (result.toolCalls && result.toolCalls.length > 0) {
              appLogger.info(
                "Yielding remaining tool calls:",
                result.toolCalls.map((tc) => tc.name).join(", "),
              );
              yield { content: "", done: false, toolCalls: result.toolCalls };
            }
          }
        }
        yield { content: "", done: true };
        break;
      }

      buffer += decoder.decode(value, { stream: true });

      // Process character by character to build complete JSON objects
      for (let i = 0; i < buffer.length; i++) {
        const char = buffer[i];

        if (escapeNext) {
          jsonBuffer += char;
          escapeNext = false;
          continue;
        }

        if (char === "\\") {
          escapeNext = true;
          jsonBuffer += char;
          continue;
        }

        if (char === '"') {
          inString = !inString;
          jsonBuffer += char;
          continue;
        }

        if (!inString) {
          if (char === "{") {
            if (braceCount === 0) {
              jsonBuffer = "{";
            } else {
              jsonBuffer += char;
            }
            braceCount++;
          } else if (char === "}") {
            jsonBuffer += char;
            braceCount--;

            if (braceCount === 0) {
              // We have a complete JSON object
              const result = processCompleteJSON(jsonBuffer);
              if (result) {
                // First yield any text content
                if (result.text) {
                  appLogger.info(
                    "Yielding text chunk:",
                    result.text.substring(0, 50) + "...",
                  );
                  yield { content: result.text, done: false };
                }

                // Then yield tool calls if any (BEFORE marking done)
                if (result.toolCalls && result.toolCalls.length > 0) {
                  appLogger.info(
                    "Yielding tool calls:",
                    result.toolCalls.map((tc) => tc.name).join(", "),
                  );
                  yield {
                    content: "",
                    done: false,
                    toolCalls: result.toolCalls,
                  };
                }

                // Finally, if done, mark as done
                if (result.done) {
                  appLogger.info("Gemini stream finished");
                  yield { content: "", done: true };
                  return;
                }
              }
              jsonBuffer = "";
            }
          } else {
            if (braceCount > 0) {
              jsonBuffer += char;
            }
          }
        } else {
          jsonBuffer += char;
        }
      }

      buffer = "";
    }

    yield { content: "", done: true };
  }

  async generateText(
    messages: LLMMessage[],
    tools?: LLMTool[],
    config?: Partial<LLMConfig>,
  ): Promise<LLMResponse> {
    const apiKey = config?.apiKey || process.env.GOOGLE_API_KEY;
    if (!apiKey) {
      throw new Error("Google API key is required");
    }

    const model = config?.model || "gemini-2.5-flash";
    // Use v1beta for all Gemini models including 2.5-flash
    const baseURL = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`;

    const systemMessage = messages.find((m) => m.role === "system");
    const userMessages = messages.filter((m) => m.role !== "system");

    const functionDeclarations = tools
      ? tools.map((t) => ({
          name: t.function.name,
          description: t.function.description,
          parameters: t.function.parameters,
        }))
      : undefined;

    const response = await fetch(`${baseURL}?key=${apiKey}`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        contents: this.formatMessagesForGemini(userMessages),
        ...(systemMessage && {
          systemInstruction: { parts: [{ text: systemMessage.content }] },
        }),
        ...(functionDeclarations &&
          functionDeclarations.length > 0 && {
            tools: [{ functionDeclarations }],
          }),
        generationConfig: {
          temperature: config?.temperature ?? 0.7,
          maxOutputTokens: config?.maxTokens,
        },
      }),
    });

    if (!response.ok) {
      const error = await response
        .json()
        .catch(() => ({ error: { message: response.statusText } }));
      throw new Error(
        `Google API error: ${error.error?.message || response.statusText}`,
      );
    }

    const data = await response.json();
    const candidate = data.candidates?.[0];
    const contentParts = candidate?.content?.parts || [];

    let textContent = "";
    const toolCalls: ToolCall[] = [];

    for (const part of contentParts) {
      if (part.text) {
        textContent += part.text;
      }
      if (part.functionCall) {
        toolCalls.push({
          id: crypto.randomUUID(),
          name: part.functionCall.name,
          arguments: part.functionCall.args || {},
        });
      }
    }

    return {
      content: textContent,
      usage: data.usageMetadata
        ? {
            promptTokens: data.usageMetadata.promptTokenCount,
            completionTokens: data.usageMetadata.candidatesTokenCount,
            totalTokens: data.usageMetadata.totalTokenCount,
          }
        : undefined,
      finishReason: candidate?.finishReason,
      model: model,
      toolCalls: toolCalls.length > 0 ? toolCalls : undefined,
    };
  }
}

import type { LLMProvider, LLMProviderInterface } from "../types";
import { AnthropicProvider } from "./anthropic";
import { DeepSeekProvider } from "./deepseek";
import { GoogleProvider } from "./google";
import { KilocodeProvider } from "./kilocode";
import { MinimaxProvider } from "./minimax";
import { NvidiaProvider } from "./nvidia";
import { OpenAIProvider } from "./openai";
import { OpenCodeZenProvider } from "./opencodezen";
import { OpenRouterProvider } from "./openrouter";

export const providers: Record<LLMProvider, () => LLMProviderInterface> = {
  openai: () => new OpenAIProvider(),
  anthropic: () => new AnthropicProvider(),
  google: () => new GoogleProvider(),
  deepseek: () => new DeepSeekProvider(),
  openrouter: () => new OpenRouterProvider(),
  kilocode: () => new KilocodeProvider(),
  minimax: () => new MinimaxProvider(),
  nvidia: () => new NvidiaProvider(),
  opencodezen: () => new OpenCodeZenProvider(),
  custom: () => {
    throw new Error("Custom provider not implemented");
  },
};

export function getProvider(provider: LLMProvider): LLMProviderInterface {
  const factory = providers[provider];
  if (!factory) {
    throw new Error(`Provider ${provider} not found`);
  }
  return factory();
}

export function getAvailableProviders(): LLMProvider[] {
  return Object.keys(providers).filter((p) => p !== "custom") as LLMProvider[];
}

