    .describe("Número de días a analizar (default: 30)"),
  includeDetails: z
    .boolean()
    .default(true)
    .describe("Incluir detalles de cada etapa del proceso"),
});

export const analyzeBusinessFlowTool: ToolDefinition = {
  name: "analyzeBusinessFlow",
  description:
    "Analizar el flujo de trabajo completo de la óptica para identificar cuellos de botella y oportunidades de mejora.",
  category: "business_flow",
  parameters: {
    type: "object",
    properties: {
      days: {
        type: "number",
        default: 30,
        description: "Número de días a analizar para el flujo de trabajo",
      },
      includeDetails: {
        type: "boolean",
        default: true,
        description:
          "Incluir detalles de cada etapa del proceso y órdenes específicas",
      },
    },
  },
  zodSchema: analyzeBusinessFlowSchema,
  execute: async (params, context): Promise<ToolResult> => {
    try {
      const validated = analyzeBusinessFlowSchema.parse(params);
      const { supabase, organizationId } = context;

      if (!organizationId) {
        return {
          success: false,
          error: "Organization ID is missing in context",
        };
      }

      const startDate = new Date();
      startDate.setDate(startDate.getDate() - validated.days);

      // Obtener órdenes con timestamps de cada etapa
      const { data: orders, error } = await supabase
        .from("orders")
        .select(
          `
            id,
            order_number,
            created_at,
            status,
            payment_status,
            total_amount,
            shipped_at,
            delivered_at,
            updated_at,
            order_items (
              id,
              product_name,
              quantity,
              total_price
            )
          `,
        )
        .eq("organization_id", organizationId)
        .gte("created_at", startDate.toISOString())
        .order("created_at", { ascending: true });

      if (error) {
        return { success: false, error: error.message };
      }

      if (!orders || orders.length === 0) {
        return {
          success: true,
          data: {
            analysis: {
              totalOrders: 0,
              averageProcessingTime: 0,
              bottleneckStage: null,
              efficiency: 0,
              recommendations: [
                "No hay datos suficientes para análisis. Requiere más órdenes históricas.",
              ],
            },
            summary: "No se encontraron órdenes en el período especificado",
          },
          message: "Análisis de flujo de completado sin datos",
        };
      }

      // Analizar cada orden para calcular tiempos por etapa
      const orderProcessingTimes = (orders as unknown[])
        .map((order: unknown) => {
          const created = new Date(order.created_at);
          let processingTime = 0;
          let bottleneckStage = null;

          // Calcular tiempos por etapa
          const stages = [];

          // Tiempo hasta procesamiento (usamos created_at como inicio si no hay más)
          const processingTimeFallback = order.shipped_at || order.updated_at;
          if (processingTimeFallback) {
            const processing = new Date(processingTimeFallback);
            const timeToProcessing =
              (processing.getTime() - created.getTime()) /
              (1000 * 60 * 60 * 24); // días
            stages.push({
              name: "Recepción",
              duration: timeToProcessing > 0 ? timeToProcessing : 0.1,
              timestamp: processingTimeFallback,
            });
            processingTime += timeToProcessing;
          }

          // Tiempo hasta envío
          if (order.shipped_at) {
            const shipped = new Date(order.shipped_at);
            const timeToShipping =
              (shipped.getTime() - created.getTime()) / (1000 * 60 * 60 * 24);
            stages.push({
              name: "Producción/Preparación",
              duration: timeToShipping,
              timestamp: order.shipped_at,
            });
            processingTime = timeToShipping; // Update cumulative processing time

            if (timeToShipping > 3) bottleneckStage = "Producción/Preparación";
          }

          // Tiempo hasta entrega
          if (order.delivered_at) {
            const delivered = new Date(order.delivered_at);
            const timeToDelivery =
              (delivered.getTime() -
                (order.shipped_at
                  ? new Date(order.shipped_at).getTime()
                  : created.getTime())) /
              (1000 * 60 * 60 * 24);
            stages.push({
              name: "Envío/Entrega",
              duration: timeToDelivery,
              timestamp: order.delivered_at,
            });
            processingTime =
              (delivered.getTime() - created.getTime()) / (1000 * 60 * 60 * 24);

            if (timeToDelivery > 5) bottleneckStage = "Envío/Entrega";
          }

          // Tiempo hasta completación Final
          if (order.status === "completed") {
            const completed = new Date(order.updated_at);
            const timeToCompletion =
              (completed.getTime() - created.getTime()) / (1000 * 60 * 60 * 24);
            stages.push({
              name: "Completación Final",
              duration:
                timeToCompletion > processingTime
                  ? timeToCompletion - processingTime
                  : 0.1,
              timestamp: order.updated_at,
            });

            if (timeToCompletion > processingTime + 1 && processingTime > 0)
              bottleneckStage = "Completación Final";

            processingTime = timeToCompletion;
          }

          return {
            orderNumber: order.order_number,
            totalProcessingTime: processingTime,
            stages,
            bottleneckStage,
            status: order.status,
            paymentStatus: order.payment_status,
            totalAmount: order.total_amount,
            itemCount: order.order_items?.length || 0,
          };
        })
        .filter((order: unknown) => order.totalProcessingTime > 0);

      // Calcular métricas generales
      const totalOrders = orderProcessingTimes.length;
      const averageProcessingTime =
        orderProcessingTimes.reduce(
          (sum, order) => sum + order.totalProcessingTime,
          0,
        ) / totalOrders;

      // Identificar cuellos de botella por etapa
      const bottleneckCounts = orderProcessingTimes
        .filter((order) => order.bottleneckStage)
        .reduce(
          (acc, order) => {
            if (order.bottleneckStage) {
              acc[order.bottleneckStage] =
                (acc[order.bottleneckStage] || 0) + 1;
            }
            return acc;
          },
          {} as Record<string, number>,
        );

      const bottleneckStage =
        Object.entries(bottleneckCounts).sort(
          ([, a], [, b]) => b - a,
        )[0]?.[0] || null;

      // Calcular eficiencia (comparar con estándares del sector)
      const industryStandard = 7; // días estándar en óptica
      const efficiency = Math.max(
        0,
        Math.min(
          100,
          ((industryStandard - averageProcessingTime) / industryStandard) * 100,
        ),
      );

      // Generar recomendaciones específicas
      const recommendations = [];

      if (bottleneckStage) {
        recommendations.push(
          `Cuello de botleneck identificado en etapa: ${bottleneckStage}. Se recomienda revisar procesos en esta área.`,
        );
      }

      if (averageProcessingTime > industryStandard) {
        recommendations.push(
          `Tiempo promedio de procesamiento (${averageProcessingTime.toFixed(1)} días) supera el estándar del sector (${industryStandard} días). Se recomienda optimizar el flujo de trabajo.`,
        );
      }

      if (efficiency < 70) {
        recommendations.push(
          `Eficiencia del flujo de trabajo es baja (${efficiency.toFixed(1)}%). Se recomienda revisar asignación de recursos y automatización.`,
        );
      }

      // Análisis por categoría de producto
      const categoryAnalysis = orderProcessingTimes.reduce(
        (acc, order) => {
          const category = order.itemCount > 5 ? "Multi-producto" : "Simple";
          if (!acc[category]) {
            acc[category] = { count: 0, totalTime: 0, avgTime: 0 };
          }
          acc[category].count++;
          acc[category].totalTime += order.totalProcessingTime;
          acc[category].avgTime = acc[category].totalTime / acc[category].count;
          return acc;
        },
        {} as Record<
          string,
          { count: number; totalTime: number; avgTime: number }
        >,
      );

      // Detalles específicos si se solicitan
      let detailedAnalysis = null;
      if (validated.includeDetails) {
        detailedAnalysis = {
          slowestOrders: orderProcessingTimes
            .sort((a, b) => b.totalProcessingTime - a.totalProcessingTime)
            .slice(0, 5)
            .map((order) => ({
              orderNumber: order.orderNumber,
              totalTime: order.totalProcessingTime,
              bottleneck: order.bottleneckStage,
              stages: order.stages,
              status: order.status,
            })),
          stageAnalysis: Object.entries(
            orderProcessingTimes.reduce(
              (acc, order) => {
                order.stages.forEach((stage) => {
                  if (!acc[stage.name]) {
                    acc[stage.name] = { totalTime: 0, count: 0, avgTime: 0 };
                  }
                  acc[stage.name].totalTime += stage.duration;
                  acc[stage.name].count++;
                  acc[stage.name].avgTime =
                    acc[stage.name].totalTime / acc[stage.name].count;
                });
                return acc;
              },
              {} as Record<
                string,
                { totalTime: number; count: number; avgTime: number }
              >,
            ),
          ),
        };
      }

      const analysis = {
        totalOrders,
        averageProcessingTime: parseFloat(averageProcessingTime.toFixed(2)),
        bottleneckStage,
        efficiency: parseFloat(efficiency.toFixed(2)),
        recommendations,
        categoryAnalysis,
        detailedAnalysis,
      };

      return {
        success: true,
        data: { analysis },
        message: `Análisis de flujo de trabajo completado para ${totalOrders} órdenes en los últimos ${validated.days} días`,
      };
    } catch (error: unknown) {
      return {
        success: false,
        // @ts-expect-error: Dynamic LLM response shape
        error: error.message || "Failed to analyze business flow",
      };
    }
  },
};

import { z } from "zod";

import type { ToolDefinition, ToolResult } from "./types";

const analyzeMarketTrendsSchema = z.object({
  months: z
    .number()
    .default(6)
    .describe("Número de meses a analizar (default: 6)"),
  category: z
    .string()
    .optional()
    .describe("Filtrar por categoría específica (opcional)"),
});

export const marketTrendsTools: ToolDefinition[] = [
  {
    name: "analyzeMarketTrends",
    description:
      "Analizar tendencias del mercado basándose en datos históricos de ventas y productos populares.",
    category: "market_analysis",
    parameters: {
      type: "object",
      properties: {
        months: {
          type: "number",
          default: 6,
          description: "Número de meses de historia a analizar",
        },
        category: {
          type: "string",
          description: "Categoría de producto específica para filtrar análisis",
        },
      },
    },
    zodSchema: analyzeMarketTrendsSchema,
    execute: async (params, context): Promise<ToolResult> => {
      try {
        const validated = analyzeMarketTrendsSchema.parse(params);
        const { supabase, organizationId } = context;

        if (!organizationId) {
          return {
            success: false,
            error: "Organization ID is missing in context",
          };
        }

        const startDate = new Date();
        startDate.setMonth(startDate.getMonth() - validated.months);

        // Consultar items de órdenes vendidos en el período
        const query = supabase
          .from("order_items")
          .select(
            `
            quantity,
            total_price,
            created_at,
            products (
              id,
              name,
              price,
              category:category_id (
                name
              )
            ),
            orders (
              created_at
            )
          `,
          )
          .gte("created_at", startDate.toISOString())
          .order("created_at", { ascending: true });

        const { data: sales, error } = await query;

        if (error) {
          return { success: false, error: error.message };
        }

        if (!sales || sales.length === 0) {
          return {
            success: true,
            data: {
              trends: [],
              topProducts: [],
              topBrands: [],
              summary:
                "No hay datos suficientes para analizar tendencias en el período seleccionado.",
            },
            message: "Análisis de tendencias completado sin datos.",
          };
        }

        // Procesar datos
        const productsMap = new Map();
        const brandsMap = new Map();
        const categoriesMap = new Map();

        // Agrupar por mes para ver evolución
        const monthlyData = new Map();

        sales.forEach((sale) => {
          // Filtrar por categoría si se especificó
          const product = sale.products as {
            category?: { name?: string };
            id?: string;
          };
          const categoryName = product?.category?.name;
          if (validated.category && categoryName !== validated.category) return;

          const productKey = product?.id || "unknown";
          const brandKey = "Generic"; // Brand column doesn't exist yet
          const categoryKey = categoryName || "Uncategorized";

          const orderObj: unknown = sale.orders;
          const orderDateStr = Array.isArray(orderObj)
            ? orderObj[0]?.created_at
            : orderObj?.created_at;
          const orderDate = orderDateStr
            ? new Date(orderDateStr)
            : new Date(sale.created_at);
          const monthKey = `${orderDate.getFullYear()}-${orderDate.getMonth() + 1}`;

          // Totales por producto
          if (!productsMap.has(productKey)) {
            productsMap.set(productKey, {
              name: product?.name || "Desconocido",
              category: categoryKey,
              brand: brandKey,
              totalSold: 0,
              revenue: 0,
              monthlySales: {},
            });
          }
          const pData = productsMap.get(productKey);
          pData.totalSold += sale.quantity;
          pData.revenue += sale.total_price;
          pData.monthlySales[monthKey] =
            (pData.monthlySales[monthKey] || 0) + sale.quantity;

          // Totales por marca
          if (!brandsMap.has(brandKey)) {
            brandsMap.set(brandKey, {
              name: brandKey,
              totalSold: 0,
              revenue: 0,
            });
          }
          const bData = brandsMap.get(brandKey);
          bData.totalSold += sale.quantity;
          bData.revenue += sale.total_price;

          // Totales por categoría
          if (!categoriesMap.has(categoryKey)) {
            categoriesMap.set(categoryKey, {
              name: categoryKey,
              totalSold: 0,
              revenue: 0,
            });
          }
          const cData = categoriesMap.get(categoryKey);
          cData.totalSold += sale.quantity;
          cData.revenue += sale.total_price;
        });

        // Calcular tendencias (Crecimiento)
        const productsList = Array.from(productsMap.values());
        const productsWithTrend = productsList.map((p) => {
          const months = Object.keys(p.monthlySales).sort();
          const lastMonth = months[months.length - 1];
          const prevMonth = months[months.length - 2];

          const lastMonthSales = p.monthlySales[lastMonth] || 0;
          const prevMonthSales = p.monthlySales[prevMonth] || 0;

          let growth = 0;
          if (prevMonthSales > 0) {
            growth = ((lastMonthSales - prevMonthSales) / prevMonthSales) * 100;
          } else if (lastMonthSales > 0) {
            growth = 100; // Nuevo bestseller
          }

          return {
            ...p,
            growth,
            trend:
              growth > 20 ? "rising" : growth < -20 ? "declining" : "stable",
          };
        });

        // Identificar Top Products
        const topProducts = productsWithTrend
          .sort((a, b) => b.totalSold - a.totalSold)
          .slice(0, 10);

        // Identificar Trending Products (Alto crecimiento)
        const trendingProducts = productsWithTrend
          .filter((p) => p.trend === "rising" && p.totalSold > 5) // Mínimo de ventas para ser tendencia
          .sort((a, b) => b.growth - a.growth)
          .slice(0, 5);

        // Brands
        const topBrands = Array.from(brandsMap.values())
          .sort((a, b) => b.totalSold - a.totalSold)
          .slice(0, 5);

        // Generar recomendaciones de inventario basadas en tendencias
        const inventoryRecommendations: string[] = [];
        trendingProducts.forEach((p) => {
          inventoryRecommendations.push(
            `Aumentar stock de "${p.name}" debido a tendencia creciente (+${p.growth.toFixed(1)}%).`,
          );
        });

        productsWithTrend
          .filter((p) => p.trend === "declining" && p.totalSold > 10)
          .slice(0, 3)
          .forEach((p) => {
            inventoryRecommendations.push(
              `Evaluar reducción de stock o promoción para "${p.name}" (tendencia a la baja).`,
            );
          });

        return {
          success: true,
          data: {
            period: `${validated.months} meses`,
            topProducts: topProducts.map((p) => ({
              name: p.name,
              sold: p.totalSold,
              revenue: p.revenue,
              trend: p.trend,
            })),
            trendingProducts: trendingProducts.map((p) => ({
              name: p.name,
              growth: `${p.growth.toFixed(1)}%`,
            })),
            topBrands: topBrands,
            categoryDistribution: Array.from(categoriesMap.values()),
            recommendations: inventoryRecommendations,
          },
          message: `Análisis de tendencias de mercado completado.`,
        };
      } catch (error: unknown) {
        return {
          success: false,
          error: error.message || "Failed to analyze market trends",
        };
      }
    },
  },
];

