      const { supabase, organizationId, currentBranchId } = context;

      if (!organizationId) {
        return {
          success: false,
          error: "Organization ID is missing in context",
        };
      }

      let branchId = validated.branchId ?? currentBranchId ?? null;
      if (!branchId && validated.branchName) {
