import { z } from "zod";

import type { ToolDefinition, ToolResult } from "../types";

const getCategoryTreeSchema = z.object({
  activeOnly: z.boolean().default(false),
});

export const getCategoryTreeTool: ToolDefinition = {
  name: "getCategoryTree",
  description: "Get all categories organized as a hierarchical tree structure.",
  category: "categories",
  parameters: {
    type: "object",
    properties: {
      activeOnly: {
        type: "boolean",
        description: "Only include active categories",
        default: false,
      },
    },
  },
  zodSchema: getCategoryTreeSchema,
  execute: async (params, context): Promise<ToolResult> => {
    try {
      const validated = getCategoryTreeSchema.parse(params);
      const { supabase, organizationId } = context;
      const activeOnly = validated.activeOnly;

      if (!organizationId) {
        return {
          success: false,
          error: "Organization ID is missing in context",
        };
      }

      let query = supabase
        .from("categories")
        .select("*")
        .order("sort_order", { ascending: true })
        .order("name", { ascending: true });

      if (activeOnly) {
        query = query.eq("is_active", true);
      }

      const { data: categories, error } = await query;

      if (error) {
        return { success: false, error: error.message };
      }

      // Build tree structure
      const cats = (categories as unknown[]) || [];
      const categoryMap = new Map<string, unknown>();
      const rootCategories: unknown[] = [];

      // First pass: create map
      for (const cat of cats) {
        categoryMap.set(cat.id, { ...cat, children: [] });
      }

      // Second pass: build tree
      for (const cat of cats) {
        const node = categoryMap.get(cat.id);
        if (cat.parent_id && categoryMap.has(cat.parent_id)) {
          categoryMap.get(cat.parent_id).children.push(node);
        } else {
          rootCategories.push(node);
        }
      }

      return {
        success: true,
        data: {
          tree: rootCategories,
          total: categories?.length || 0,
        },
        message: `Retrieved ${categories?.length || 0} categories in tree structure`,
      };
    } catch (error: unknown) {
      return {
        success: false,
        // @ts-expect-error: Dynamic LLM response shape
        error: error.message || "Failed to get category tree",
      };
    }
  },
};

import { z } from "zod";

import type { ToolDefinition, ToolResult } from "../types";

const confirmAppointmentSchema = z.object({
  appointmentId: z.string().uuid(),
});

export const confirmAppointmentTool: ToolDefinition = {
  name: "confirmAppointment",
  description:
    "Confirma una cita del cliente. El cliente debe ser el dueño de la cita. Requiere appointmentId (UUID de la cita).",
  category: "appointments",
  parameters: {
    type: "object",
    properties: {
      appointmentId: {
        type: "string",
        description: "ID (UUID) de la cita a confirmar",
      },
    },
    required: ["appointmentId"],
  },
  zodSchema: confirmAppointmentSchema,
  execute: async (params, context): Promise<ToolResult> => {
    const customerId = context.customerId;
    if (!customerId) {
      return {
        success: false,
        error: "No se pudo identificar al cliente. Contacta a la sucursal.",
      };
    }

    const { appointmentId } = params as { appointmentId: string };

    try {
      const { supabase, organizationId } = context;

      const { data: appointment, error: fetchError }: unknown = await supabase
        .from("appointments")
        .select(
          "id, customer_id, status, appointment_date, appointment_time, branch:branches(name)",
        )
        .eq("id", appointmentId)
        .eq("organization_id", organizationId)
        .single();

      if (fetchError || !appointment) {
        return {
          success: false,
          error: "No se encontró la cita.",
        };
      }

      if (appointment.customer_id !== customerId) {
        return {
          success: false,
          error: "No tienes permiso para confirmar esta cita.",
        };
      }

      if (appointment.status === "confirmed") {
        return {
          success: true,
          data: {
            message: "Tu cita ya estaba confirmada. Te esperamos.",
          },
        };
      }

      if (!["scheduled"].includes(appointment.status)) {
        return {
          success: false,
          error: `Esta cita no puede confirmarse (estado: ${appointment.status}).`,
        };
      }

