import type { ToolDefinition, ToolResult } from "../types";

const getCustomerStatsSchema = z.object({
  customerId: z.string().uuid(),
});

export const getCustomerStatsTool: ToolDefinition = {
  name: "getCustomerStats",
  description: "Get analytics and statistics for a specific customer.",
  category: "customers",
  parameters: {
    type: "object",
    properties: {
      customerId: { type: "string", description: "Customer UUID" },
    },
    required: ["customerId"],
  },
  zodSchema: getCustomerStatsSchema,
  execute: async (params, context): Promise<ToolResult> => {
    try {
      const validated = getCustomerStatsSchema.parse(params);
      const { supabase, organizationId } = context;

      if (!organizationId) {
        return {
          success: false,
          error: "Organization ID is missing in context",
        };
      }

      const { data: orders, error }: unknown = await supabase
        .from("orders")
        .select("total_amount, status, payment_status, created_at")
        .eq("customer_id", validated.customerId)
        .eq("organization_id", organizationId);

      if (error) {
        return { success: false, error: error.message };
      }

      const paidOrders =
        (orders as unknown[])?.filter(
          (o: unknown) =>
            o.payment_status === "paid" || o.status === "completed",
        ) || [];
      const totalSpent = paidOrders.reduce(
        (sum: number, o: unknown) => sum + (o.total_amount || 0),
        0,
      );
      const orderCount = orders?.length || 0;
      const avgOrderValue = orderCount > 0 ? totalSpent / orderCount : 0;

      const stats = {
        totalOrders: orderCount,
        totalSpent,
        averageOrderValue: avgOrderValue,
        lastOrderDate:
          orders && orders.length > 0
            ? (orders as unknown[]).sort(
                (a: unknown, b: unknown) =>
                  new Date(b.created_at).getTime() -
                  new Date(a.created_at).getTime(),
              )[0].created_at
            : null,
      };

      return {
        success: true,
        data: stats,
        message: `Customer statistics calculated`,
      };
    } catch (error: unknown) {
      return {
        success: false,
        // @ts-expect-error: Dynamic LLM response shape
        error: error.message || "Failed to get customer stats",
      };
    }
  },
};

import { z } from "zod";

import type { ToolDefinition, ToolResult } from "../types";

const getCustomersSchema = z.object({
  search: z.string().optional(),
  limit: z.number().max(100).default(20),
  page: z.number().default(1),
});

export const getCustomersTool: ToolDefinition = {
  name: "getCustomers",
  description:
    "Search and filter customers by name, email, or membership tier.",
  category: "customers",
  parameters: {
    type: "object",
    properties: {
      search: {
        type: "string",
        description: "Search term for name, email or RUT",
      },
      limit: { type: "number", default: 20, maximum: 100 },
      page: { type: "number", default: 1 },
    },
  },
  zodSchema: getCustomersSchema,
  execute: async (params, context): Promise<ToolResult> => {
    try {
      const validated = getCustomersSchema.parse(params);
      const { supabase, organizationId, currentBranchId } = context;

      if (!organizationId) {
        return {
          success: false,
          error: "Organization ID is missing in context",
        };
      }

      let query = supabase
        .from("customers")
        .select("*", { count: "exact" })
        .eq("is_active", true);

      if (currentBranchId) {
        query = query.eq("branch_id", currentBranchId);
      } else {
        const { data: branches } = await supabase
          .from("branches")
          .select("id")
          .eq("organization_id", organizationId);
        const branchIds = branches?.map((b: { id: string }) => b.id) || [];
        if (branchIds.length > 0) {
          query = query.in("branch_id", branchIds);
        } else {
          return {
            success: true,
            data: {
              customers: [],
              total: 0,
              page: validated.page,
              limit: validated.limit,
            },
            message: "No customers found",
          };
        }
      }

      if (validated.search) {
        query = query.or(
          `first_name.ilike.%${validated.search}%,last_name.ilike.%${validated.search}%,email.ilike.%${validated.search}%,rut.ilike.%${validated.search}%`,
        );
      }

      const offset = (validated.page - 1) * validated.limit;
      const { data, error, count } = await query
        .order("created_at", { ascending: false })
        .range(offset, offset + validated.limit - 1);

      if (error) {
        return { success: false, error: error.message };
      }

      return {
        success: true,
        data: {
          customers: data || [],
          total: count || 0,
          page: validated.page,
          limit: validated.limit,
        },
        message: `Found ${count || 0} customers`,
      };
    } catch (error: unknown) {
      return {
        success: false,
        // @ts-expect-error: Dynamic LLM response shape
        error: error.message || "Failed to get customers",
      };
    }
  },
};

import type { SupabaseClient } from "@supabase/supabase-js";

import type { Database } from "@/types/supabase";

export async function analyzeOrdersHealth(supabase: SupabaseClient<Database>, startDate: Date, severity: string, organizationId: string) {
  const { data: orders, error } = await supabase.from("orders").select("id, status, payment_status, total_amount, created_at, updated_at").eq("organization_id", organizationId).gte("created_at", startDate.toISOString()).order("created_at", { ascending: false });
  if (error) return { health: "unknown", issues: [], metrics: {} };
  const total = orders?.length || 0;
  const paid = orders?.filter((o: unknown) => o.payment_status === "paid").length || 0;
  const completed = orders?.filter((o: unknown) => o.status === "completed").length || 0;
  const pending = orders?.filter((o: unknown) => o.status === "pending").length || 0;
  const failed = orders?.filter((o: unknown) => o.payment_status === "failed").length || 0;
  const paymentSuccessRate = total > 0 ? (paid / total) * 100 : 0;
  const pendingRate = total > 0 ? (pending / total) * 100 : 0;
  const failedPaymentRate = total > 0 ? (failed / total) * 100 : 0;
  const completionRate = total > 0 ? (completed / total) * 100 : 0;
  const issues: unknown[] = [];
  if (paymentSuccessRate < 80) issues.push({ type: "payment", severity: paymentSuccessRate < 50 ? "critical" : "high", message: `Tasa de éxito de pagos baja (${paymentSuccessRate.toFixed(1)}%)`, impact: "Pérdida de ingresos significativa" });
  if (pendingRate > 20) issues.push({ type: "process", severity: pendingRate > 40 ? "high" : "medium", message: `Alta tasa de órdenes pendientes (${pendingRate.toFixed(1)}%)`, impact: "Ineficiencia operativa" });
  if (failedPaymentRate > 5) issues.push({ type: "payment", severity: failedPaymentRate > 10 ? "critical" : "high", message: `Alta tasa de pagos fallidos (${failedPaymentRate.toFixed(1)}%)`, impact: "Pérdida de ventas potenciales" });
  return { health: calculateHealthScore([paymentSuccessRate, completionRate, 100 - pendingRate, 100 - failedPaymentRate]), issues: filterIssuesBySeverity(issues, severity), metrics: { totalOrders: total, paidOrders: paid, completedOrders: completed, pendingOrders: pending, failedPayments: failed, paymentSuccessRate: parseFloat(paymentSuccessRate.toFixed(2)), completionRate: parseFloat(completionRate.toFixed(2)), pendingRate: parseFloat(pendingRate.toFixed(2)), failedPaymentRate: parseFloat(failedPaymentRate.toFixed(2)) } };
}

export async function analyzeInventoryHealth(supabase: SupabaseClient<Database>, _startDate: Date, severity: string, organizationId: string) {
  const { data: products, error } = await supabase.from("products").select("id, name, inventory_quantity, status, cost_price, price").eq("organization_id", organizationId).eq("status", "active");
  if (error) return { health: "unknown", issues: [], metrics: {} };
  const total = products?.length || 0;
  const low = products?.filter((p: unknown) => (p.inventory_quantity || 0) <= 5).length || 0;
  const out = products?.filter((p: unknown) => (p.inventory_quantity || 0) === 0).length || 0;
  const over = products?.filter((p: unknown) => (p.inventory_quantity || 0) > 100).length || 0;
  const outRate = total > 0 ? (out / total) * 100 : 0;
  const lowRate = total > 0 ? (low / total) * 100 : 0;
  const overRate = total > 0 ? (over / total) * 100 : 0;
  const issues: unknown[] = [];
  if (outRate > 5) issues.push({ type: "inventory", severity: outRate > 15 ? "critical" : "high", message: `Alta tasa de productos sin stock (${outRate.toFixed(1)}%)`, impact: "Pérdida de ventas inmediata" });
  if (lowRate > 20) issues.push({ type: "inventory", severity: lowRate > 40 ? "high" : "medium", message: `Alta tasa de productos con stock bajo (${lowRate.toFixed(1)}%)`, impact: "Riesgo de interrupción de ventas" });
  if (overRate > 10) issues.push({ type: "inventory", severity: overRate > 20 ? "medium" : "low", message: `Alta tasa de productos con stock excesivo (${overRate.toFixed(1)}%)`, impact: "Inversión de capital ineficiente" });
  return { health: calculateHealthScore([100 - outRate, 100 - lowRate, 100 - overRate]), issues: filterIssuesBySeverity(issues, severity), metrics: { totalProducts: total, lowStock: low, outOfStock: out, overStock: over, lowStockRate: parseFloat(lowRate.toFixed(2)), outOfStockRate: parseFloat(outRate.toFixed(2)), overStockRate: parseFloat(overRate.toFixed(2)) } };
}

export async function analyzeCustomerHealth(supabase: SupabaseClient<Database>, _startDate: Date, severity: string, _organizationId: string) {
  const { data: customers, error } = await supabase.from("profiles").select("id, created_at");
  if (error) return { health: "unknown", issues: [], metrics: {} };
  const total = customers?.length || 0;
  const newCustomers = customers?.filter((c: unknown) => (new Date().getTime() - new Date(c.created_at).getTime()) / (1000 * 60 * 60 * 24) <= 30).length || 0;
  const newRate = total > 0 ? (newCustomers / total) * 100 : 0;
  const issues: unknown[] = [];
  if (total > 20 && newRate < 10) issues.push({ type: "growth", severity: newRate < 5 ? "critical" : "high", message: `Baja tasa de nuevos clientes (${newRate.toFixed(1)}%)`, impact: "Riesgo de estancamiento del negocio" });
  return { health: calculateHealthScore([newRate]), issues: filterIssuesBySeverity(issues, severity), metrics: { totalCustomers: total, newCustomers, newCustomerRate: parseFloat(newRate.toFixed(2)) } };
}

export async function analyzeSystemPerformance(supabase: SupabaseClient<Database>, _startDate: Date, severity: string, organizationId: string) {
  const { data: orgData, error } = await supabase.from("organizations").select("total_orders, total_revenue, average_order_value, customer_retention_rate, order_completion_rate").eq("id", organizationId).limit(1);
  if (error || !orgData || orgData.length === 0) return { health: "unknown", issues: [], metrics: {} };
  const org = orgData[0];
  const retentionRate = org.customer_retention_rate || 0;
  const completionRate = org.order_completion_rate || 0;
  const issues: unknown[] = [];
  if (retentionRate < 60) issues.push({ type: "retention", severity: retentionRate < 40 ? "critical" : "high", message: `Baja tasa de retención de clientes (${retentionRate.toFixed(1)}%)`, impact: "Pérdida de ingresos recurrentes" });
  if (completionRate < 80) issues.push({ type: "process", severity: completionRate < 60 ? "high" : "medium", message: `Baja tasa de completación de órdenes (${completionRate.toFixed(1)}%)`, impact: "Ineficiencia operativa" });
  return { health: calculateHealthScore([retentionRate, completionRate]), issues: filterIssuesBySeverity(issues, severity), metrics: { totalOrders: org.total_orders || 0, totalRevenue: org.total_revenue || 0, averageOrderValue: org.average_order_value || 0, customerRetentionRate: parseFloat(retentionRate.toFixed(2)), orderCompletionRate: parseFloat(completionRate.toFixed(2)) } };
}

export function filterIssuesBySeverity(issues: unknown[], severity: string) {
  if (severity === "low") return issues.filter((i: unknown) => i.severity === "low");
  if (severity === "medium") return issues.filter((i: unknown) => ["medium", "low"].includes(i.severity));
  if (severity === "high") return issues.filter((i: unknown) => ["high", "critical"].includes(i.severity));
  return issues;
}

export function calculateHealthScore(scores: number[]): string {
  if (scores.length === 0) return "unknown";
  const avg = scores.reduce((a, b) => a + b, 0) / scores.length;
  if (avg >= 80) return "excellent"; if (avg >= 60) return "good"; if (avg >= 40) return "fair"; if (avg >= 20) return "poor";
  return "critical";
}

export function calculateOverallHealth(results: unknown[]): string {
  const scores = results.map((r: unknown) => { switch (r.health) { case "excellent": return 100; case "good": return 80; case "fair": return 60; case "poor": return 40; case "critical": return 20; default: return 50; } });
  const avg = scores.reduce((a, b) => a + b, 0) / scores.length;
  return calculateHealthScore([avg]);
}

export function getCriticalIssues(results: unknown[]): unknown[] { return results.flatMap((r: unknown) => r.issues || []).filter((i: unknown) => i.severity === "critical"); }

export function generateComprehensiveRecommendations(results: unknown[]): string[] {
  const recs: string[] = [];
  if (results[0]?.issues) results[0].issues.forEach((i: unknown) => { if (i.severity === "critical" || i.severity === "high") recs.push(`Revisar ${i.type}: ${i.message} (${i.impact})`); });
  if (results[1]?.issues) results[1].issues.forEach((i: unknown) => { if (i.severity === "critical" || i.severity === "high") recs.push(`Inventario: ${i.message}`); });
  if (results[2]?.issues) results[2].issues.forEach((i: unknown) => recs.push(`Cliente: ${i.message}`));
  if (recs.length === 0) recs.push("El sistema se encuentra en buen estado. Continuar monitoreo regular.");
  return recs;
}

export function generateSummary(results: unknown[]): string {
  const health = calculateOverallHealth(results);
  const critical = getCriticalIssues(results);
  const messages: Record<string, string> = { excellent: "El sistema se encuentra en excelente estado", good: "El sistema se encuentra en buen estado", fair: "El sistema requiere atención", poor: "El sistema requiere atención inmediata", critical: "El sistema requiere atención crítica" };
  let summary = messages[health] || "Estado desconocido";
  if (critical.length > 0) summary += `. Se identificaron ${critical.length} problemas críticos que requieren atención inmediata.`;
  else { const totalIssues = results.reduce((sum, r: unknown) => sum + (r.issues?.length || 0), 0); if (totalIssues > 0) summary += `. Se identificaron ${totalIssues} problemas leves/moderados.`; }
  return summary;
}

import { z } from "zod";

import { createOrganizationalMemory } from "../memory/organizational";
import type { ToolDefinition, ToolResult } from "./types";

const generateRecommendationsSchema = z.object({
  focus: z
    .enum(["growth", "efficiency", "inventory", "customer", "general"])
    .default("general")
    .describe("Área de enfoque para las recomendaciones"),
});

export const recommendationTools: ToolDefinition[] = [
  {
    name: "generateRecommendations",
    description:
      "Generar recomendaciones estratégicas personalizadas basadas en la madurez organizacional y métricas actuales.",
    category: "strategy",
    parameters: {
      type: "object",
      properties: {
        focus: {
          type: "string",
          enum: ["growth", "efficiency", "inventory", "customer", "general"],
          default: "general",
          description: "Área principal de enfoque para las recomendaciones",
        },
      },
    },
    zodSchema: generateRecommendationsSchema,
    execute: async (params, context): Promise<ToolResult> => {
      try {
        const validated = generateRecommendationsSchema.parse(params);
        const { supabase, organizationId } = context;

        if (!organizationId) {
          return {
            success: false,
            error: "Contexto de organización no disponible.",
          };
        }

        const orgId = organizationId;
        const memory = createOrganizationalMemory(orgId, supabase);

        // 2. Obtener contexto organizacional
        const [maturity, contextData, metrics] = await Promise.all([
          memory.getMaturityLevel(),
          memory.getOrganizationalContext(),
          memory.getActivityMetrics(),
        ]);

        // 3. Generar recomendaciones basadas en Madurez y Enfoque
        const recommendations: string[] = [];
        const insights: string[] = [];

        // Estrategia según Fase de Madurez
        switch (maturity.level) {
          case "new":
          case "starting":
            insights.push(
              `Fase actual: ${maturity.description}. El objetivo es establecer operaciones base.`,
            );
            if (metrics.totalOrders < 10) {
              recommendations.push(
                "Prioridad: Completar configuración de catálogo de productos.",
              );
              recommendations.push(
                "Acción: Registrar primera venta o pedido de prueba para verificar flujo.",
              );
            } else {
              recommendations.push(
                "Foco: Adquisición de primeros clientes recurrentes.",
              );
              recommendations.push(
                "Sugerencia: Configurar recordatorios automáticos para citas.",
              );
            }
            break;

          case "growing":
            insights.push(
              `Fase actual: Crecimiento. Foco en retención y eficiencia.`,
            );
            if (metrics.customerRetentionRate < 40) {
              recommendations.push(
                "Alerta: Baja tasa de retención. Implementar seguimiento post-venta.",
              );
            }
            recommendations.push(
              "Oportunidad: Analizar productos más vendidos para asegurar stock.",
            );
            break;

          case "established":
            insights.push(
              `Fase actual: Establecida. Foco en optimización y rentabilidad.`,
            );
            recommendations.push(
              "Estrategia: Analizar rentabilidad por categoría (no solo volumen).",
            );
            recommendations.push(
              "Optimización: Revisar cuellos de botella en tiempos de entrega.",
            );
            break;
        }

        // Recomendaciones específicas por área (Focus)
        if (validated.focus === "inventory" || validated.focus === "general") {
          // Lógica simple de inventario sin re-consultar todo
          if (contextData.topProducts.length > 0) {
            recommendations.push(
              `Inventario: Asegurar disponibilidad de top seller "${contextData.topProducts[0].name}".`,
            );
          }
        }

        if (validated.focus === "customer" || validated.focus === "general") {
          if (contextData.customerCount > 0 && metrics.monthlyOrders > 0) {
            const ordersPerCustomer =
              metrics.monthlyOrders / contextData.customerCount;
            if (ordersPerCustomer < 0.5) {
              recommendations.push(
                "Clientes: Activar campañas de reactivación para clientes inactivos.",
              );
            }
          }
        }

        return {
          success: true,
          data: {
            organization: contextData.name,
            maturityLevel: maturity.level,
            focusArea: validated.focus,
            insights,
            recommendations,
            contextSummary: {
              totalOrders: metrics.totalOrders,
              customerCount: contextData.customerCount,
            },
          },
          message: `Recomendaciones generadas para fase ${maturity.level}`,
        };
      } catch (error: unknown) {
        return {
          success: false,
          error: error.message || "Failed to generate recommendations",
        };
      }
    },
  },
];

import { z } from "zod";

import { parseImportFile } from "../../utils/file-parser";
import type { ToolDefinition, ToolResult } from "../types";

const analyzeImportFileSchema = z.object({
  fileId: z
    .string()
    .describe("Storage path of the uploaded file (e.g. org_id/uuid.csv)"),
  entityType: z
    .enum(["customers", "products"])
    .describe("Type of entities to import"),
});

export async function downloadFile(
  fileId: string,
  supabase: unknown,
): Promise<ArrayBuffer> {
  const { data, error } = await supabase.storage
    .from("import-temp")
    .download(fileId);

  if (error) {
    throw new Error(`Failed to download file: ${error.message}`);
  }
  if (!data) {
    throw new Error("File not found");
  }
  return await data.arrayBuffer();
}

function suggestionsFromHeaders(
  headers: string[],
  mapping: Record<string, string>,
  targetField: string,
  possibleNames: string[],
) {
  for (const h of headers) {
    const lower = h.toLowerCase();
    if (possibleNames.some((n) => lower.includes(n))) {
      mapping[h] = targetField;
      break;
    }
  }
}

export const analyzeImportFileTool: ToolDefinition = {
  name: "analyzeImportFile",
  description:
    "Analyze an uploaded CSV or Excel file to suggest column mapping for bulk import. Use when the user has attached a file for importing customers or products. Returns suggested mapping, sample rows, and warnings.",
  category: "import",
  parameters: {
    type: "object",
    properties: {
      fileId: {
        type: "string",
        description: "Storage path of the file (from the user's message)",
      },
      entityType: {
        type: "string",
        enum: ["customers", "products"],
        description: "Type of entities to import",
      },
    },
    required: ["fileId", "entityType"],
  },
  zodSchema: analyzeImportFileSchema,
  execute: async (params, context): Promise<ToolResult> => {
    try {
      const validated = analyzeImportFileSchema.parse(params);
      const { supabase } = context;

      const buffer = await downloadFile(validated.fileId, supabase);
      const ext = validated.fileId.includes(".xlsx")
        ? "xlsx"
        : validated.fileId.includes(".xls")
          ? "xls"
          : "csv";
      const { headers, rows } = await parseImportFile(buffer, `file.${ext}`);

      const sampleRows = rows.slice(0, 5);

      const customerFields = [
        "first_name",
        "last_name",
        "email",
        "phone",
        "rut",
        "address_line_1",
        "city",
        "country",
      ];
      const productFields = [
        "name",
        "price",
        "description",
        "sku",
        "inventory_quantity",
      ];

      const targetFields =
        validated.entityType === "customers" ? customerFields : productFields;

      const suggestedMapping: Record<string, string> = {};
      const warnings: string[] = [];

      const headerLower = headers.map((h) => h.toLowerCase());
      for (const field of targetFields) {
        const idx = headerLower.findIndex(
          (h) =>
            h.includes(field) ||
            h.includes(field.replace("_", " ")) ||
            field.includes(h.replace(" ", "_")),
        );
        if (idx >= 0) {
          suggestedMapping[headers[idx]] = field;
        }
      }

      if (validated.entityType === "customers") {
        const hasFirst =
          headers.some((h) =>
            /nombre|first|nombre_pila|nombre_pila/i.test(h),
          ) || headerLower.some((h) => h.includes("first"));
        const hasLast =
          headers.some((h) =>
            /apellido|last|nombre_familia|apellido/i.test(h),
          ) || headerLower.some((h) => h.includes("last"));
        if (!hasFirst || !hasLast) {
          suggestionsFromHeaders(headers, suggestedMapping, "first_name", [
            "nombre",
            "first_name",
            "nombre_pila",
            "name",
          ]);
          suggestionsFromHeaders(headers, suggestedMapping, "last_name", [
            "apellido",
            "last_name",
            "nombre_familia",
          ]);
        }
        if (!Object.values(suggestedMapping).includes("first_name")) {
          warnings.push("first_name is required for customers");
        }
        if (!Object.values(suggestedMapping).includes("last_name")) {
          warnings.push("last_name is required for customers");
        }
      } else {
        suggestionsFromHeaders(headers, suggestedMapping, "name", [
          "nombre",
          "name",
          "producto",
        ]);
        suggestionsFromHeaders(headers, suggestedMapping, "price", [
          "precio",
          "price",
        ]);
      }

      return {
        success: true,
        data: {
          suggestedMapping,
          sampleRows,
          headers,
          rowCount: rows.length,
          confidence:
            Object.keys(suggestedMapping).length / targetFields.length,
          warnings,
        },
        message: `Analyzed ${rows.length} rows. Suggested mapping for ${validated.entityType}.`,
      };
    } catch (error: unknown) {
      return {
        success: false,
        error: error.message || "Failed to analyze file",
      };
    }
  },
};

import type { ToolResult } from "../types";

export async function executeCustomerImport(
  supabase: unknown,
  organizationId: string,
  branchId: string,
  headers: string[],
  rows: Record<string, string | number | null>[],
  columnMapping: Record<string, string>,
): Promise<ToolResult> {
  let imported = 0;
  const failed: Array<{ row: number; error: string }> = [];

  // Resolve column key: mapping key may differ by case/trim from actual header
  const resolveVal = (
    row: Record<string, string | number | null>,
    fileCol: string,
  ): string | number | null => {
    const normalized = String(fileCol || "")
      .trim()
      .toLowerCase();
    const match = headers.find(
      (h) =>
        String(h || "")
          .trim()
          .toLowerCase() === normalized,
    );
    return match != null ? (row[match] ?? null) : null;
  };

  for (let i = 0; i < rows.length; i++) {
    try {
      const row = rows[i];
      const mapped: Record<string, unknown> = {};
      for (const [fileCol, opttiusField] of Object.entries(columnMapping)) {
        const val = resolveVal(row, fileCol);
        if (val !== null && val !== undefined && String(val).trim()) {
          mapped[opttiusField] = String(val).trim();
        }
      }

      const firstName =
        mapped.first_name || mapped.name?.split(" ")[0] || "Cliente";
      const lastName =
        mapped.last_name ||
        mapped.name?.split(" ").slice(1).join(" ") ||
        "Sin apellido";

      const { error } = await supabase.from("customers").insert({
        branch_id: branchId,
        organization_id: organizationId,
        first_name: firstName,
        last_name: lastName,
        email: mapped.email || null,
        phone: mapped.phone || null,
        rut: mapped.rut || null,
        address_line_1: mapped.address_line_1 || null,
        city: mapped.city || null,
        country: mapped.country || null,
        is_active: true,
      });

      if (error) {
        failed.push({ row: i + 2, error: error.message });
      } else {
        imported++;
      }
    } catch (e: unknown) {
      failed.push({
        row: i + 2,
        error: e?.message || "Validation error",
      });
    }
  }

  return {
    success: true,
    data: {
      imported,
      failed: failed.length,
      errors: failed.slice(0, 10),
    },
    message: `Imported ${imported} customers. ${failed.length} failed.`,
  };
}

import type { ToolResult } from "../types";

export async function executeProductImport(
  supabase: unknown,
  organizationId: string,
  branchId: string | null,
  headers: string[],
  rows: Record<string, string | number | null>[],
  columnMapping: Record<string, string>,
  currency: string,
): Promise<ToolResult> {
  let imported = 0;
  const failed: Array<{ row: number; error: string }> = [];

  // Resolve column key: mapping key may differ by case/trim from actual header
  const resolveVal = (
    row: Record<string, string | number | null>,
    fileCol: string,
  ): string | number | null => {
    const normalized = String(fileCol || "")
      .trim()
      .toLowerCase();
    const match = headers.find(
      (h) =>
        String(h || "")
          .trim()
          .toLowerCase() === normalized,
    );
    return match != null ? (row[match] ?? null) : null;
  };

  for (let i = 0; i < rows.length; i++) {
    try {
      const row = rows[i];
      const mapped: Record<string, unknown> = {};
      for (const [fileCol, opttiusField] of Object.entries(columnMapping)) {
        const val = resolveVal(row, fileCol);
        if (val !== null && val !== undefined && String(val).trim()) {
          mapped[opttiusField] = String(val).trim();
        }
      }

      const name = mapped.name || mapped.nombre || "Producto";
      const price = parseFloat(mapped.price || mapped.precio || "0") || 0;

      const slug =
        (name as string)
          .toLowerCase()
          .normalize("NFD")
          .replace(/[\u0300-\u036f]/g, "")
          .replace(/[^a-z0-9]+/g, "-")
          .replace(/(^-|-$)/g, "") || `product-${Date.now()}`;

      const { data: insertedProduct, error } = await supabase
        .from("products")
        .insert({
          organization_id: organizationId,
          branch_id: branchId || null,
          name,
          price,
          currency: currency || "CLP",
          description: mapped.description || null,
          slug,
          status: "draft",
          inventory_quantity:
            parseInt(mapped.inventory_quantity || "0", 10) || 0,
        })
        .select("id")
        .single();

      if (error) {
        failed.push({ row: i + 2, error: error.message });
      } else {
        imported++;
        // Create product_branch_stock when branch is specified
        const qty = parseInt(mapped.inventory_quantity || "0", 10) || 0;
        if (branchId && insertedProduct?.id) {
          const now = new Date().toISOString();
          await supabase.from("product_branch_stock").upsert(
            {
              product_id: insertedProduct.id,
              branch_id: branchId,
              quantity: qty,
              reserved_quantity: 0,
              low_stock_threshold: 5,
              created_at: now,
              updated_at: now,
            },
            { onConflict: "product_id, branch_id" },
          );
        }
      }
    } catch (e: unknown) {
      failed.push({
        row: i + 2,
        error: e?.message || "Validation error",
      });
    }
  }

  return {
    success: true,
    data: {
      imported,
      failed: failed.length,
      errors: failed.slice(0, 10),
    },
    message: `Imported ${imported} products. ${failed.length} failed.`,
  };
}

import { z } from "zod";

import { parseImportFile } from "../../utils/file-parser";
import { resolveBranchByName } from "../resolvers";
import type { ToolDefinition, ToolResult } from "../types";
import { analyzeImportFileTool, downloadFile } from "./analyzeFile";
import { executeCustomerImport } from "./importCustomers";
import { executeProductImport } from "./importProducts";

const executeBulkImportSchema = z.object({
  fileId: z.string(),
  entityType: z.enum(["customers", "products"]),
  columnMapping: z
    .record(z.string())
    .describe(
      "Map of file column names to Opttius field names. Keys MUST be exact column headers from the file.",
    ),
  branchId: z
    .string()
    .uuid()
    .optional()
    .describe(
      "Branch ID where to import. Required for customers. If omitted, uses context.currentBranchId when available.",
    ),
  branchName: z
    .string()
    .optional()
    .describe("Branch name (alternative to branchId, e.g. 'Sucursal Centro')"),
});

export const executeBulkImportTool: ToolDefinition = {
  name: "executeBulkImport",
  description:
    "Execute bulk import of customers or products from an uploaded file. Requires column mapping from analyzeImportFile. Use requiresConfirmation - ask user to confirm before proceeding.",
  category: "import",
  requiresConfirmation: true,
  minRole: "admin",
  parameters: {
    type: "object",
    properties: {
      fileId: { type: "string" },
      entityType: {
        type: "string",
        enum: ["customers", "products"],
      },
      columnMapping: {
        type: "object",
        description: "Map file column names to Opttius field names",
      },
      branchId: {
        type: "string",
        description:
          "Branch UUID (required for customers). Use context.currentBranchId if user has a branch selected.",
      },
      branchName: {
        type: "string",
        description: "Branch name (alternative to branchId)",
      },
    },
    required: ["fileId", "entityType", "columnMapping"],
  },
  zodSchema: executeBulkImportSchema,
  execute: async (params, context): Promise<ToolResult> => {
    try {
      const validated = executeBulkImportSchema.parse(params);
      const { supabase, organizationId, currentBranchId, userData, currency } =
        context;

      if (!organizationId) {
        return {
          success: false,
          error: "Organization ID is missing",
        };
      }

      // Resolve branchId: params > branchName > context.currentBranchId
      let resolvedBranchId = validated.branchId;
      if (!resolvedBranchId && validated.branchName) {
        resolvedBranchId =
          (await resolveBranchByName(
            supabase,
            organizationId,
            validated.branchName,
          )) ?? undefined;
      }
      if (!resolvedBranchId || resolvedBranchId === "global") {
        if (currentBranchId && currentBranchId !== "global") {
          resolvedBranchId = currentBranchId;
        } else if (userData?.isSuperAdmin) {
          return {
            success: false,
            error:
              "Vista global activa. Por favor, selecciona una sucursal específica en el selector de sucursales antes de ejecutar la importación, o indica el ID de la sucursal en tu mensaje.",
          };
        } else {
          return {
            success: false,
            error:
              "Se requiere branchId para la importación. Selecciona una sucursal en el selector o indica la sucursal de destino.",
          };
        }
      }

      if (validated.entityType === "customers" && !resolvedBranchId) {
        return {
          success: false,
          error: "branchId es obligatorio para importar clientes.",
        };
      }

      const buffer = await downloadFile(validated.fileId, supabase);
      const ext = validated.fileId.includes(".xlsx")
        ? "xlsx"
        : validated.fileId.includes(".xls")
          ? "xls"
          : "csv";
      const { headers, rows } = await parseImportFile(buffer, `file.${ext}`);

      // Validate columnMapping keys match file headers (case-insensitive, trim)
      const headerSet = new Set(
        headers.map((h) =>
          String(h || "")
            .trim()
            .toLowerCase(),
        ),
      );
      const invalidKeys: string[] = [];
      for (const fileCol of Object.keys(validated.columnMapping)) {
        const normalized = String(fileCol || "")
          .trim()
          .toLowerCase();
        const matchingHeader = headers.find(
          (h) =>
            String(h || "")
              .trim()
              .toLowerCase() === normalized,
        );
        if (!matchingHeader && !headerSet.has(normalized)) {
          invalidKeys.push(fileCol);
        }
      }
      if (invalidKeys.length > 0) {
        return {
          success: false,
          error: `Columnas del mapping no encontradas en el archivo: ${invalidKeys.join(", ")}. Headers del archivo: ${headers.join(", ")}. El columnMapping debe ser { "Header del archivo": "campo_opttius" } (clave = nombre exacto de la columna en el archivo).`,
        };
      }

      if (validated.entityType === "customers") {
        if (!resolvedBranchId) {
          return {
            success: false,
            error: "branchId es obligatorio para importar clientes.",
          };
        }
        return executeCustomerImport(
          supabase,
          organizationId,
          resolvedBranchId,
          headers,
          rows,
          validated.columnMapping,
        );
      }

      return executeProductImport(
        supabase,
        organizationId,
        resolvedBranchId || null,
        headers,
        rows,
        validated.columnMapping,
        currency || "CLP",
      );
    } catch (error: unknown) {
      return {
        success: false,
        error: error.message || "Failed to execute import",
      };
    }
  },
};

export const importBulkTools: ToolDefinition[] = [
  analyzeImportFileTool,
  executeBulkImportTool,
];

