const ROLE_HIERARCHY: Record<AgentRole, number> = {
  vendedor: 0,
  admin: 1,
  dueño: 2,
};

/**
 * Returns all tools, optionally filtered by the user's role.
 * Tools without `minRole` are visible to everyone (default: vendedor).
 * When `role` is undefined, returns all tools (backward-compatible).
 */
export function getAllTools(role?: AgentRole): ToolDefinition[] {
  if (!role) return allTools;

  const userLevel = ROLE_HIERARCHY[role] ?? 0;

  return allTools.filter((tool) => {
    if (!tool.minRole) return true; // no restriction — everyone can use
    return ROLE_HIERARCHY[tool.minRole] <= userLevel;
  });
}

export function getToolsByCategory(category: string): ToolDefinition[] {
  return allTools.filter((tool) => tool.category === category);
}

export function getToolByName(name: string): ToolDefinition | undefined {
  return allTools.find((tool) => tool.name === name);
}

export function convertToolsToLLMTools(tools: ToolDefinition[]): LLMTool[] {
  return tools.map((tool) => ({
    type: "function",
    function: {
      name: tool.name,
      description: tool.description,
      parameters: tool.parameters,
    },
  }));
}

export function validateToolCall(
  toolName: string,
  params: unknown,
): { valid: boolean; error?: string } {
  const tool = getToolByName(toolName);
  if (!tool) {
    return { valid: false, error: `Tool ${toolName} not found` };
  }

  try {
    const zodSchema = getZodSchemaForTool(toolName);
    if (zodSchema) {
      zodSchema.parse(params);
    }
    return { valid: true };
  } catch (error: unknown) {
    return { valid: false, error: error.message };
  }
}

function getZodSchemaForTool(
  toolName: string,
): import("zod").ZodTypeAny | null {
  const tool = getToolByName(toolName);
  return tool?.zodSchema ?? null;
}

import type { ToolDefinition, ToolResult } from "../types";

export const saveMemoryTool: ToolDefinition = {
  name: "saveMemory",
  description:
    "Save a fact, decision, or pattern to organizational memory. Vendedor role can only read memory (writes are silently dropped). Admin and dueño can persist new facts. Use when the user says 'remember that X' or 'save this for later'.",
  type: "memory",
  minRole: "vendedor",
  category: "memory",
  parameters: {
    type: "object",
    properties: {
      content: {
        type: "string",
        description: "The fact or information to remember",
      },
      category: {
        type: "string",
        enum: ["preference", "decision", "context", "workflow", "insight"],
        description: "Category of the memory fact",
      },
      importance: {
        type: "number",
        default: 1,
        description: "Importance level 1-5 (default 1)",
      },
    },
    required: ["content"],
  },
  execute: async (params, context): Promise<ToolResult> => {
    try {
      const {
        content,
        category = "fact",
        importance = 1,
      } = params as {
        content: string;
        category?: string;
        importance?: number;
      };
      const { supabase, organizationId, userId, userData } = context;

      // Vendedor: read-only for memory writes
      if (
        userData?.role === "vendedor" ||
        (context as Record<string, unknown>).role === "vendedor"
      ) {
        return {
          success: false,
          error:
            "Tu rol no tiene permisos para guardar información. Consulta a un administrador o dueño.",
        };
      }

      if (!organizationId) {
        return {
          success: false,
          error: "Organization ID is missing in context",
        };
      }

      const { data, error } = await supabase
        .from("memory_facts")
        .insert({
          organization_id: organizationId,
          user_id: userId,
          content,
          category,
          importance,
          fact_type: category === "insight" ? "insight" : "fact",
          source_session_id: null,
        })
        .select()
        .single();

      if (error) {
        return { success: false, error: error.message };
      }

      return {
        success: true,
        data,
        message: "Recorded successfully",
      };
    } catch (error: unknown) {
      return {
        success: false,
        error: error instanceof Error ? error.message : "Failed to save memory",
      };
    }
  },
};

import type { ToolDefinition, ToolResult } from "../types";

export const saveSessionSummaryTool: ToolDefinition = {
  name: "saveSessionSummary",
  description:
    "Save a summary of the current interaction session to organizational memory. Typically called when the agent session ends. Persists as an insight-type memory fact.",
  type: "memory",
  minRole: "admin",
  category: "memory",
  parameters: {
    type: "object",
    properties: {
      summary: {
        type: "string",
        description: "Summary of the session's key points",
      },
      messageCount: {
        type: "number",
        description: "Number of messages exchanged in the session",
      },
      tokenCount: {
        type: "number",
        description: "Total tokens consumed in the session",
      },
      screenRoute: {
        type: "string",
        description: "The main screen route where the session occurred",
      },
      sessionId: {
        type: "string",
        description: "ID of the current session",
      },
    },
    required: ["summary"],
  },
  execute: async (params, context): Promise<ToolResult> => {
    try {
      const {
        summary,
        messageCount = 0,
        tokenCount = 0,
        screenRoute,
        sessionId,
      } = params as {
        summary: string;
        messageCount?: number;
        tokenCount?: number;
        screenRoute?: string;
        sessionId?: string;
      };
      const { supabase, organizationId, userId } = context;

      if (!organizationId) {
        return {
          success: false,
          error: "Organization ID is missing in context",
        };
      }

      const { data, error } = await supabase
        .from("memory_facts")
        .insert({
          organization_id: organizationId,
          user_id: userId,
          content: summary,
          category: "insight",
          importance: 3,
          fact_type: "insight",
          source_session_id: sessionId || null,
          metadata: {
            message_count: messageCount,
            token_count: tokenCount,
            screen_route: screenRoute || null,
          },
        })
        .select()
        .single();

      if (error) {
        return { success: false, error: error.message };
      }

      // Also update chat_sessions metadata if sessionId provided
      if (sessionId) {
        await supabase
          .from("chat_sessions")
          .update({
            metadata: {
              summary,
              message_count: messageCount,
              token_count: tokenCount,
            },
          })
          .eq("id", sessionId);
      }

      return {
        success: true,
        data,
        message: "Session summary saved",
      };
    } catch (error: unknown) {
      return {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to save session summary",
      };
    }
  },
};

import type { ToolDefinition, ToolResult } from "../types";

// ponytail: threshold 0.7 hardcoded — make configurable if multiple orgs need different values
const SEARCH_THRESHOLD = 0.7;
const DEFAULT_LIMIT = 10;

export const searchOrgMemoryTool: ToolDefinition = {
  name: "searchOrgMemory",
  description:
    'Search organizational memory for facts matching the query. Performs semantic search on memory_facts with relevance threshold. Returns matching facts with similarity scores. Use when the user asks "what do we know about X" or "have we dealt with X before".',
  type: "memory",
  minRole: "vendedor",
  category: "memory",
  parameters: {
    type: "object",
    properties: {
      query: {
        type: "string",
        description: "Search query to find relevant memories",
      },
      limit: {
        type: "number",
        default: DEFAULT_LIMIT,
        description: "Maximum number of results (default 10)",
      },
    },
    required: ["query"],
  },
  execute: async (params, context): Promise<ToolResult> => {
    try {
      const { query, limit = DEFAULT_LIMIT } = params as {
        query: string;
        limit?: number;
      };
      const { supabase, organizationId } = context;

      if (!organizationId) {
        return {
          success: false,
          error: "Organization ID is missing in context",
        };
      }

      // ponytail: pgvector match_memory_facts RPC — falls back to ILIKE if RPC not available
      const { data, error } = await supabase.rpc("match_memory_facts", {
        query_embedding: null, // ponytail: embedding generated externally; pass null to use ILIKE fallback
        match_threshold: SEARCH_THRESHOLD,
        match_count: limit,
        p_org_id: organizationId,
      });

      if (error) {
        // fallback to ILIKE search
        const { data: fallback, error: fallbackError } = await supabase
          .from("memory_facts")
          .select("*")
          .eq("organization_id", organizationId)
          .ilike("content", `%${query}%`)
          .order("created_at", { ascending: false })
          .limit(limit);

        if (fallbackError) {
          return { success: false, error: fallbackError.message };
        }

        return {
          success: true,
          data: { facts: fallback || [], method: "ilike_fallback" },
          message: `Found ${fallback?.length || 0} memory facts matching "${query}"`,
        };
      }

      return {
        success: true,
        data: { facts: data || [], method: "semantic" },
        message: `Found ${data?.length || 0} memory facts matching "${query}"`,
      };
    } catch (error: unknown) {
      return {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to search organizational memory",
      };
    }
  },
};

/**
 * Navigation tools for the AI Agent.
 *
 * IMPORTANT: None of these tools execute server-side redirects.
 * They all return a NavigationBlock that the frontend processes
 * via next/navigation useRouter().push().
 */
import type { ToolDefinition, ToolResult } from "./types";

const entityRoutes: Record<string, string> = {
  customer: "/admin/customers",
  product: "/admin/products",
  order: "/admin/orders",
  workOrder: "/admin/work-orders",
  appointment: "/admin/appointments",
  quote: "/admin/quotes",
  prescription: "/admin/prescriptions",
  category: "/admin/categories",
  ticket: "/admin/support",
};

export const navigationTools: ToolDefinition[] = [
  {
    name: "navigateTo",
    description:
      "Navigate the user to a specific admin route. Returns a navigation block that the frontend resolves via router.push().",
    type: "navigation",
    minRole: "vendedor",
    category: "navigation",
    parameters: {
      type: "object",
      properties: {
        path: {
          type: "string",
          description: "Admin route path, e.g. /admin/customers",
        },
        label: {
          type: "string",
          description: "Human-readable label for the link",
        },
      },
      required: ["path", "label"],
    },
    execute: async (params): Promise<ToolResult> => {
      const { path, label } = params as { path: string; label: string };
      return {
        success: true,
        data: { type: "navigation", label, path },
      };
    },
  },
  {
    name: "openEntity",
    description:
      "Navigate to a specific entity's detail page. Supported entities: customer, product, order, workOrder, appointment, quote, prescription, category, ticket.",
    type: "navigation",
    minRole: "vendedor",
    category: "navigation",
    parameters: {
      type: "object",
      properties: {
        entity: {
          type: "string",
          enum: Object.keys(entityRoutes),
          description: "Entity type to navigate to",
        },
        id: {
          type: "string",
          description: "Entity UUID",
        },
      },
      required: ["entity", "id"],
    },
    execute: async (params): Promise<ToolResult> => {
      const { entity, id } = params as { entity: string; id: string };
      const basePath = entityRoutes[entity];
      if (!basePath) {
        return {
          success: false,
          error: `Unknown entity type: ${entity}. Supported: ${Object.keys(entityRoutes).join(", ")}`,
        };
      }
      return {
        success: true,
        data: {
          type: "navigation",
          label: `View ${entity}`,
          path: `${basePath}/${id}`,
        },
      };
    },
  },
  {
    name: "reopenLastScreen",
    description:
      "Navigate the user back to their previous screen. Returns a navigation block that triggers router.back() on the frontend. If no previous route exists, stays on current page.",
    type: "navigation",
    minRole: "vendedor",
    category: "navigation",
    parameters: {
      type: "object",
      properties: {},
    },
    execute: async (): Promise<ToolResult> => {
      return {
        success: true,
        data: {
          type: "navigation",
          label: "Go back",
          path: "__back__", // ponytail: frontend interprets __back__ as router.back()
        },
      };
    },
  },
];

import { z } from "zod";

import type { ToolDefinition, ToolResult } from "./types";

const optimizeInventorySchema = z.object({
  category: z
    .string()
    .optional()
    .describe("Categoría de productos a optimizar (opcional)"),
  lowStockThreshold: z
    .number()
    .default(5)
    .describe("Umbral para considerar stock bajo (cantidad física)"),
});

export const inventoryTools: ToolDefinition[] = [
  {
    name: "optimizeInventory",
    description:
      "Optimizar inventario analizando stock actual frente a velocidad de ventas para recomendar reordenamiento.",
    category: "inventory_optimization",
    parameters: {
      type: "object",
      properties: {
        category: {
          type: "string",
          description: "Categoría específica a optimizar",
        },
        lowStockThreshold: {
          type: "number",
          default: 5,
          description:
            "Cantidad mínima de seguridad para alertas de stock bajo",
        },
      },
    },
    zodSchema: optimizeInventorySchema,
    execute: async (params, context): Promise<ToolResult> => {
      try {
        const validated = optimizeInventorySchema.parse(params);
        const { supabase, organizationId } = context;

        if (!organizationId) {
          return {
            success: false,
            error: "Organization ID is missing in context",
          };
        }

        // 1. Obtener productos e inventario actual
        let productsQuery = supabase
          .from("products")
          .select(
            "id, name, inventory_quantity, low_stock_threshold, category_id, cost_price, price",
          )
          .eq("organization_id", organizationId)
          .eq("status", "active");

        if (validated.category) {
          productsQuery = productsQuery.eq("category_id", validated.category);
        }

        const { data: products, error: productsError } = await productsQuery;

        if (productsError)
          return { success: false, error: productsError.message };
        if (!products || products.length === 0)
          return {
            success: true,
            data: { message: "No se encontraron productos." },
          };

        // 2. Calcular velocidad de ventas (últimos 30 días)
        const thirtyDaysAgo = new Date();
        thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

        const { data: sales, error: salesError } = await supabase
          .from("order_items")
          .select("product_id, quantity, created_at")
          .gte("created_at", thirtyDaysAgo.toISOString());

        if (salesError) return { success: false, error: salesError.message };

        // Mapa de ventas por producto
        const salesVelocity = new Map<string, number>(); // Unidades por día
        sales?.forEach((sale) => {
          const current = salesVelocity.get(sale.product_id) || 0;
          salesVelocity.set(sale.product_id, current + sale.quantity);
        });

        // 3. Analizar cada producto
        const analysis = products.map((product) => {
          const soldLast30Days = salesVelocity.get(product.id) || 0;
          const dailyRunRate = soldLast30Days / 30;
          const currentStock = product.inventory_quantity || 0;

          let daysOfSupply = 999; // Infinito si no hay ventas
          if (dailyRunRate > 0) {
            daysOfSupply = currentStock / dailyRunRate;
          }

          const minThreshold =
            product.low_stock_threshold || validated.lowStockThreshold;

          // Determinar estado
          let status = "healthy";
          let recommendation = "Mantener niveles actuales";

          if (currentStock === 0) {
            status = "out_of_stock";
            recommendation = "⚠️ REORDER INMEDIATO: Producto agotado.";
          } else if (currentStock <= minThreshold) {
            status = "critical_low";
            recommendation = `⚠️ REORDER: Stock (${currentStock}) por debajo del mínimo (${minThreshold}).`;
          } else if (daysOfSupply < 14) {
            // Menos de 2 semanas de stock
            status = "low_supply";
            recommendation = `Planificar Reorder: Stock para ${daysOfSupply.toFixed(1)} días basados en ventas recientes.`;
          } else if (daysOfSupply > 180 && currentStock > 20) {
            // Más de 6 meses de stock
            status = "overstock";
            recommendation =
              "Evaluar promoción: Posible exceso de inventario (baja rotación).";
          }

          return {
            id: product.id,
            name: product.name,
            category: product.category_id,
            currentStock,
            soldLast30Days,
            dailyRunRate: parseFloat(dailyRunRate.toFixed(2)),
            daysOfSupply:
              daysOfSupply === 999
                ? "> 1 año"
                : parseFloat(daysOfSupply.toFixed(1)),
            status,
            recommendation,
          };
        });

        // Filtrar aquellos que requieren acción
        const actionableItems = analysis
          .filter((a) => a.status !== "healthy")
          .sort((a, b) => {
            // Prioridad: out_of_stock > critical_low > low_supply > overstock
            const priorities: unknown = {
              out_of_stock: 0,
              critical_low: 1,
              low_supply: 2,
              overstock: 3,
            };
            return priorities[a.status] - priorities[b.status];
          });

        // Resumen
        const summary = {
          totalProducts: products.length,
          outOfStock: analysis.filter((a) => a.status === "out_of_stock")
            .length,
          criticalLow: analysis.filter((a) => a.status === "critical_low")
            .length,
          overstock: analysis.filter((a) => a.status === "overstock").length,
          recommendedActions: actionableItems.length,
        };

        return {
          success: true,
          data: {
            summary,
            actionableItems: actionableItems.slice(0, 20), // Top 20 items requiring action
            stockValuation: products.reduce(
              (acc, p) => acc + (p.inventory_quantity || 0) * p.cost_price,
              0,
            ),
          },
          message: `Optimización de inventario completada. ${actionableItems.length} productos requieren atención.`,
        };
      } catch (error: unknown) {
        return {
          success: false,
          error: error.message || "Failed to optimize inventory",
        };
      }
    },
  },
];

import { z } from "zod";

import { resolveOrderByNumber } from "../resolvers";
import type { ToolDefinition, ToolResult } from "../types";

const getOrderByIdSchema = z
  .object({
    orderId: z.string().uuid().optional(),
    orderNumber: z.string().optional(),
  })
  .refine((d) => d.orderId || d.orderNumber, {
    message: "Provide orderId or orderNumber",
  });

export const getOrderByIdTool: ToolDefinition = {
  name: "getOrderById",
  description:
    "Get detailed information about a specific order by ID or order_number (visible in UI).",
  category: "orders",
  parameters: {
    type: "object",
    properties: {
      orderId: {
        type: "string",
        description: "Order UUID (optional if orderNumber provided)",
      },
      orderNumber: {
        type: "string",
        description: "Order number visible in UI (e.g. ORD-2025-001)",
      },
    },
  },
  zodSchema: getOrderByIdSchema,
  execute: async (params, context): Promise<ToolResult> => {
    try {
      const validated = getOrderByIdSchema.parse(params);
      const { supabase, organizationId } = context;

      if (!organizationId) {
        return {
          success: false,
          error: "Organization ID is missing in context",
        };
      }

      let orderId = validated.orderId;
      if (!orderId && validated.orderNumber) {
        orderId =
          (await resolveOrderByNumber(
            supabase,
            organizationId,
            validated.orderNumber,
          )) ?? undefined;
        if (!orderId) {
          return {
            success: false,
            error: `Orden con número "${validated.orderNumber}" no encontrada`,
          };
        }
      } else if (!orderId) {
        return {
          success: false,
          error: "Proporciona orderId o orderNumber",
        };
      }

      const { data, error } = await supabase
        .from("orders")
        .select(
          `
            *,
            order_items (
              id,
              product_id,
              product_name,
              variant_title,
              quantity,
              unit_price,
              total_price
            )

          `,
        )
        .eq("id", orderId)
        .eq("organization_id", organizationId)
        .single();

      if (error) {
        return { success: false, error: error.message };
      }

      if (!data) {
        return { success: false, error: "Order not found" };
      }

      return {
        success: true,
        data,
        message: `Retrieved order ${data.order_number}`,
      };
    } catch (error: unknown) {
      return {
        success: false,
        error: error.message || "Failed to get order",
      };
    }
  },
};

import { z } from "zod";

import type { ToolDefinition, ToolResult } from "../types";

const getOrderStatsSchema = z.object({
  days: z.number().default(30),
});

export const getOrderStatsTool: ToolDefinition = {
  name: "getOrderStats",
  description: "Get order statistics for a specified number of days.",
  category: "orders",
  parameters: {
    type: "object",
    properties: {
      days: {
        type: "number",
        default: 30,
        description: "Number of days to analyze",
      },
    },
  },
  zodSchema: getOrderStatsSchema,
  execute: async (params, context): Promise<ToolResult> => {
    try {
      const validated = getOrderStatsSchema.parse(params);
      const { supabase, organizationId } = context;

      if (!organizationId) {
        return {
          success: false,
          error: "Organization ID is missing in context",
        };
      }

      const startDate = new Date();
      startDate.setDate(startDate.getDate() - validated.days);

      const { data: orders, error } = await supabase
        .from("orders")
        .select("status, payment_status, total_amount, created_at")
        .eq("organization_id", organizationId)
        .gte("created_at", startDate.toISOString());

      if (error) {
        return { success: false, error: error.message };
      }

      const stats = {
        total: orders?.length || 0,
        byStatus: {} as Record<string, number>,
        byPaymentStatus: {} as Record<string, number>,
        totalRevenue: 0,
        averageOrderValue: 0,
      };

      orders?.forEach((order) => {
        stats.byStatus[order.status] = (stats.byStatus[order.status] || 0) + 1;
        stats.byPaymentStatus[order.payment_status] =
          (stats.byPaymentStatus[order.payment_status] || 0) + 1;
        if (order.payment_status === "paid" || order.status === "completed") {
          stats.totalRevenue += order.total_amount || 0;
        }
      });

      stats.averageOrderValue =
        stats.total > 0 ? stats.totalRevenue / stats.total : 0;

      return {
        success: true,
        data: {
          ...stats,
          currency: context.currency || "USD",
        },
        message: `Order statistics for last ${validated.days} days`,
      };
    } catch (error: unknown) {
      return {
        success: false,
        error: error.message || "Failed to get order stats",
      };
    }
  },
};

