import { z } from "zod";

import type { ToolDefinition, ToolResult } from "../types";

const getProductsSchema = z.object({
  search: z.string().optional(),
  category: z.string().optional(),
  status: z.enum(["draft", "active", "archived"]).optional(),
  minPrice: z.number().optional(),
  maxPrice: z.number().optional(),
  featured: z.boolean().optional(),
  inStock: z.boolean().optional(),
  limit: z.number().max(100).default(20),
  page: z.number().default(1),
});

export const getProductsTool: ToolDefinition = {
  name: "getProducts",
  description:
    "Search and filter products. Returns a list of products matching the criteria.",
  category: "products",
  parameters: {
    type: "object",
    properties: {
      search: {
        type: "string",
        description: "Search term for product name or description",
      },
      category: { type: "string", description: "Category ID to filter by" },
      status: {
        type: "string",
        enum: ["draft", "active", "archived"],
        description: "Product status",
      },
      minPrice: { type: "number", description: "Minimum price filter" },
      maxPrice: { type: "number", description: "Maximum price filter" },
      featured: { type: "boolean", description: "Filter featured products" },
      inStock: { type: "boolean", description: "Filter products in stock" },
      limit: {
        type: "number",
        description: "Number of results (max 100)",
        default: 20,
      },
      page: { type: "number", description: "Page number", default: 1 },
    },
  },
  zodSchema: getProductsSchema,
  execute: async (params, context): Promise<ToolResult> => {
    try {
      const validated = getProductsSchema.parse(params);
      const { supabase, organizationId } = context;

      if (!organizationId) {
        return {
          success: false,
          error: "Organization ID is missing in context",
        };
      }

      let query = supabase
        .from("products")
        .select(
          `
            *,
            categories:category_id (
              id,
              name,
              slug
            )
          `,
          { count: "exact" },
        )
        .eq("organization_id", organizationId);

      if (validated.search) {
        query = query.or(
          `name.ilike.%${validated.search}%,description.ilike.%${validated.search}%`,
        );
      }

      if (validated.category) {
        query = query.eq("category_id", validated.category);
      }

      if (validated.status) {
        query = query.eq("status", validated.status);
      }

      if (validated.minPrice !== undefined) {
        query = query.gte("price", validated.minPrice);
      }

      if (validated.maxPrice !== undefined) {
        query = query.lte("price", validated.maxPrice);
      }

      if (validated.featured !== undefined) {
        query = query.eq("is_featured", validated.featured);
      }

      if (validated.inStock) {
        query = query.gt("inventory_quantity", 0);
      }

      const offset = (validated.page - 1) * validated.limit;
      const { data, error, count } = await query
        .order("created_at", { ascending: false })
        .range(offset, offset + validated.limit - 1);

      if (error) {
        return { success: false, error: error.message };
      }

      const products =
        data?.map((product) => ({
          ...product,
          currency: context.currency || "USD",
        })) || [];

      return {
        success: true,
        data: {
          products,
          total: count || 0,
          page: validated.page,
          limit: validated.limit,
          currency: context.currency || "USD",
        },
        message: `Found ${count || 0} products`,
      };
    } catch (error: unknown) {
      return {
        success: false,
        error: error.message || "Failed to get products",
      };
    }
  },
};

import { z } from "zod";

import { appLogger } from '@/lib/logger';

import { resolveBranchByName } from "../resolvers";
import type { ToolDefinition, ToolResult } from "../types";
const updateInventorySchema = z.object({
  productId: z.string().uuid(),
  quantity: z.number().min(0),
  adjustmentType: z.enum(["set", "add", "subtract"]).default("add"),
  branchId: z.string().uuid().optional(),
  branchName: z.string().optional(),
});

export const updateInventoryTool: ToolDefinition = {
  name: "updateInventory",
  description:
    "Update product inventory quantity in a specific branch. Can set, add, or subtract from current stock. IMPORTANT: Before calling, use getProductById to check product_branch_stock. If product is in multiple branches and user is in global view, you MUST ask which branch or use branchName. Never assume a branch when in global mode.",
  category: "products",
  parameters: {
    type: "object",
    properties: {
      productId: { type: "string", description: "Product UUID" },
      quantity: { type: "number", description: "Quantity value" },
      adjustmentType: {
        type: "string",
        enum: ["set", "add", "subtract"],
        default: "add",
        description:
          "How to adjust inventory (add = add to current, set = replace, subtract = remove)",
      },
      branchId: {
        type: "string",
        description:
          "Branch UUID where to update stock (required when user is in global view)",
      },
      branchName: {
        type: "string",
        description:
          "Branch name (alternative to branchId, e.g. 'Sucursal Centro')",
      },
    },
    required: ["productId", "quantity"],
  },
  zodSchema: updateInventorySchema,
  execute: async (params, context): Promise<ToolResult> => {
    try {
      const validated = updateInventorySchema.parse(params);
      const { supabase, organizationId } = context;

      if (!organizationId) {
        return {
          success: false,
          error: "Organization ID is missing in context",
        };
      }

      // Check for organization_id
      const { data: productData, error: productError } = await supabase
        .from("products")
        .select("id, organization_id")
        .eq("id", validated.productId)
        .eq("organization_id", organizationId)
        .single();

      if (productError || !productData) {
        return {
          success: false,
          error: "Product not found or access denied",
        };
      }

      let branchId = validated.branchId ?? context.currentBranchId ?? null;

      if (validated.branchName && !branchId) {
        branchId = await resolveBranchByName(
          supabase,
          organizationId,
          validated.branchName,
        );
      }

      if (!branchId || branchId === "global") {
        return {
          success: false,
          error:
            "Vista global activa: debes indicar en qué sucursal agregar las unidades. Usa branchName (ej. 'Sucursal Centro') o branchId. Primero consulta getProductById para ver en qué sucursales está el producto.",
        };
      }
      let newQuantity = 0;

      if (branchId) {
        // Get current stock
        const { data: currentStock } = await supabase
          .from("product_branch_stock")
          .select("quantity")
          .eq("product_id", validated.productId)
          .eq("branch_id", branchId)
          .single();

        const currentQty = currentStock?.quantity || 0;

        if (validated.adjustmentType === "set") {
          newQuantity = validated.quantity;
        } else if (validated.adjustmentType === "add") {
          newQuantity = currentQty + validated.quantity;
        } else if (validated.adjustmentType === "subtract") {
          newQuantity = Math.max(0, currentQty - validated.quantity);
        }

        // Upsert stock
        const { error: stockError } = await supabase
          .from("product_branch_stock")
          .upsert(
            {
              product_id: validated.productId,
              branch_id: branchId,
              quantity: newQuantity,
              low_stock_threshold: 5,
              updated_at: new Date().toISOString(),
            },
            { onConflict: "product_id, branch_id" },
          );

        if (stockError) {
          appLogger.error("Stock update error:", stockError);
          return {
            success: false,
            error: "Failed to update branch stock: " + stockError.message,
          };
        }
      }

      // Stock lives ONLY in product_branch_stock. Do NOT update products.inventory_quantity
      // (legacy column) - it would leak one branch's stock to global view and other branches.
      return {
        success: true,
        data: {
          product_id: validated.productId,
          branch_id: branchId,
          quantity: newQuantity,
        },
        message: `Inventario actualizado a ${newQuantity} unidades en la sucursal indicada`,
      };
    } catch (error: unknown) {
      return {
        success: false,
        error: error.message || "Failed to update inventory",
      };
    }
  },
};

/**
 * AI Agent tools for quotes
 */
import { z } from "zod";

import { sendQuoteEmailToClient } from "@/lib/email/send-quote-email";

import { resolveQuoteByNumber } from "./resolvers";
import type { ToolDefinition, ToolResult } from "./types";

const sendQuoteByEmailSchema = z
  .object({
    quoteId: z.string().uuid().optional(),
    quoteNumber: z.string().optional(),
    email: z.string().email("Email válido requerido"),
  })
  .refine((d) => d.quoteId || d.quoteNumber, {
    message: "Provide quoteId or quoteNumber",
  });

export const quoteTools: ToolDefinition[] = [
  {
    name: "sendQuoteByEmail",
    description:
      "Send a quote (presupuesto) by email to a client. Use quoteNumber (e.g. COT-2025-010) - visible in UI - or quoteId.",
    category: "quotes",
    parameters: {
      type: "object",
      properties: {
        quoteId: {
          type: "string",
          description: "Quote UUID (optional if quoteNumber provided)",
        },
        quoteNumber: {
          type: "string",
          description: "Quote number visible in UI (e.g. COT-2025-010)",
        },
        email: { type: "string", description: "Recipient email address" },
      },
      required: ["email"],
    },
    zodSchema: sendQuoteByEmailSchema,
    execute: async (params, context): Promise<ToolResult> => {
      try {
        const validated = sendQuoteByEmailSchema.parse(params);
        const { supabase, organizationId } = context;

        if (!organizationId) {
          return {
            success: false,
            error: "Organization ID is missing in context",
          };
        }

        let quoteId = validated.quoteId;
        if (!quoteId && validated.quoteNumber) {
          quoteId =
            (await resolveQuoteByNumber(
              supabase,
              organizationId,
              validated.quoteNumber,
            )) ?? undefined;
          if (!quoteId) {
            return {
              success: false,
              error: `Presupuesto con número "${validated.quoteNumber}" no encontrado`,
            };
          }
        } else if (!quoteId) {
          return {
            success: false,
            error: "Proporciona quoteId o quoteNumber",
          };
        }

        const result = await sendQuoteEmailToClient(quoteId, validated.email, {
          organizationId,
        });

        if (!result.success) {
          return {
            success: false,
            error: result.error || "Error al enviar el presupuesto",
          };
        }

        return {
          success: true,
          data: { emailId: result.emailId },
          message: `Presupuesto enviado correctamente a ${validated.email}`,
        };
      } catch (error: unknown) {
        return {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Failed to send quote by email",
        };
      }
    },
  },
];

import { z } from "zod";

import { resolveOpticalTicketByNumber } from "../resolvers";
import type { ToolDefinition, ToolResult } from "../types";

const createTicketResponseSchema = z
  .object({
    ticketId: z.string().uuid().optional(),
    ticketNumber: z.string().optional(),
    message: z.string().min(1),
    isInternal: z.boolean().default(false),
  })
  .refine((d) => d.ticketId || d.ticketNumber, {
    message: "Provide ticketId or ticketNumber",
  });

export const createTicketResponseTool: ToolDefinition = {
  name: "createTicketResponse",
  description:
    "Agregar respuesta o nota a un ticket de incidentes. Usar ticketNumber (visible en UI) o ticketId. Respeta la sucursal del contexto.",
  category: "support",
  parameters: {
    type: "object",
    properties: {
      ticketId: {
        type: "string",
        description: "Ticket UUID (opcional si se proporciona ticketNumber)",
      },
      ticketNumber: {
        type: "string",
        description: "Número de ticket visible en UI",
      },
      message: { type: "string", description: "Mensaje de respuesta" },
      isInternal: {
        type: "boolean",
        default: false,
        description: "Marcar como nota interna",
      },
    },
    required: ["message"],
  },
  zodSchema: createTicketResponseSchema,
  execute: async (params, context): Promise<ToolResult> => {
    try {
      const validated = createTicketResponseSchema.parse(params);
      const { supabase, organizationId, currentBranchId } = context;

      if (!organizationId) {
        return {
          success: false,
          error: "Organization ID is missing in context",
        };
      }

      let ticketId = validated.ticketId;
      if (!ticketId && validated.ticketNumber) {
        const branchId =
          currentBranchId && currentBranchId !== "global"
            ? currentBranchId
            : undefined;
        ticketId =
          (await resolveOpticalTicketByNumber(
            supabase,
            validated.ticketNumber,
            organizationId,
            branchId,
          )) ?? undefined;
        if (!ticketId) {
          return {
            success: false,
            error: `Ticket con número "${validated.ticketNumber}" no encontrado`,
          };
        }
      } else if (!ticketId) {
        return {
          success: false,
          error: "Proporciona ticketId o ticketNumber",
        };
      }

      const { data: ticket } = await supabase
        .from("optical_internal_support_tickets")
        .select("id")
        .eq("id", ticketId)
        .eq("organization_id", organizationId)
        .single();

      if (!ticket) {
        return {
          success: false,
          error: "Ticket no encontrado o sin acceso",
        };
      }

      const { data: adminUser }: unknown = await supabase
        .from("admin_users")
        .select("email, role")
        .eq("id", context.userId)
        .single();

      const senderName = adminUser?.email?.split("@")[0] || "Usuario";
      const senderEmail = adminUser?.email || "";
      const senderRole = adminUser?.role || "admin";

      const { data: newMessage, error: messageError }: unknown = await supabase
        .from("optical_internal_support_messages")
        .insert({
          ticket_id: ticketId,
          message: validated.message,
          is_internal: validated.isInternal,
          sender_id: context.userId,
          sender_name: senderName,
          sender_email: senderEmail,
          sender_role: senderRole,
          message_type: validated.isInternal ? "note" : "message",
        })
        .select()
        .single();

      if (messageError) {
        return { success: false, error: messageError.message };
      }

      await supabase
        .from("optical_internal_support_tickets")
        .update({
          last_response_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        })
        .eq("id", ticketId);

      return {
        success: true,
        data: newMessage,
        message: "Respuesta agregada al ticket",
      };
    } catch (error: unknown) {
      return {
        success: false,
        // @ts-expect-error: Dynamic LLM response shape
        error: error.message || "Failed to create ticket response",
      };
    }
  },
};

