};

import { z } from "zod";

import { resolveBranchByName } from "./resolvers";
import type { ToolDefinition, ToolResult } from "./types";

const WORK_ORDER_STATUSES = [
  "quote",
  "ordered",
  "on_hold_payment",
  "sent_to_lab",
  "in_progress_lab",
  "ready_at_lab",
  "received_from_lab",
  "mounted",
  "quality_check",
  "ready_for_pickup",
  "delivered",
  "cancelled",
  "returned",
] as const;

const getWorkOrdersSchema = z.object({
  status: z.enum(WORK_ORDER_STATUSES).optional(),
  statuses: z.array(z.enum(WORK_ORDER_STATUSES)).optional(),
  branchId: z.string().uuid().optional().nullable(),
  branchName: z.string().optional(),
  startDate: z
    .string()
    .regex(/^\d{4}-\d{2}-\d{2}$/, "Date must be YYYY-MM-DD")
    .optional(),
  endDate: z
    .string()
    .regex(/^\d{4}-\d{2}-\d{2}$/, "Date must be YYYY-MM-DD")
    .optional(),
  limit: z.number().max(100).default(50),
  offset: z.number().default(0),
});

const getWorkOrderByIdSchema = z.object({
  workOrderId: z.string().uuid(),
});

export const workOrderTools: ToolDefinition[] = [
  {
    name: "getWorkOrders",
    description:
      "Lista órdenes de trabajo (trabajos de laboratorio) con filtros opcionales por estado, sucursal y fechas. Usar para consultar trabajos pendientes, en lab, listos para retiro, etc.",
    category: "work_orders",
    parameters: {
      type: "object",
      properties: {
        status: {
          type: "string",
          enum: [...WORK_ORDER_STATUSES],
          description: "Filtrar por un estado del trabajo",
        },
        statuses: {
          type: "array",
          items: { type: "string", enum: [...WORK_ORDER_STATUSES] },
          description:
            "Filtrar por varios estados (ej. ['sent_to_lab','in_progress_lab','ready_at_lab'] para 'en laboratorio')",
        },
        branchId: {
          type: "string",
          description:
            "UUID de sucursal (requerido para Super Admin con vista global)",
        },
        branchName: {
          type: "string",
          description: "Nombre de sucursal (alternativa a branchId)",
        },
        startDate: {
          type: "string",
          description: "Fecha inicio YYYY-MM-DD",
        },
        endDate: {
          type: "string",
          description: "Fecha fin YYYY-MM-DD",
        },
        limit: { type: "number", default: 50, maximum: 100 },
        offset: { type: "number", default: 0 },
      },
    },
    zodSchema: getWorkOrdersSchema,
    execute: async (params, context): Promise<ToolResult> => {
      try {
        const validated = getWorkOrdersSchema.parse(params);
        const { supabase, organizationId, currentBranchId, userData } = context;

        if (!organizationId) {
          return {
            success: false,
            error: "Organization ID is missing in context",
          };
        }

        // "global" means no branch selected - treat as null (do NOT use as branch_id)
        const effectiveBranchContext =
          currentBranchId && currentBranchId !== "global"
            ? currentBranchId
            : null;

        let branchId = validated.branchId ?? effectiveBranchContext ?? null;
        if (!branchId && validated.branchName) {
          branchId = await resolveBranchByName(
            supabase,
            organizationId,
            validated.branchName,
          );
        }

        const isSuperAdmin = userData?.isSuperAdmin === true;
        const isGlobalView = !effectiveBranchContext;

        if (!branchId && !(isSuperAdmin && isGlobalView)) {
          return {
            success: false,
            error:
              "Selecciona una sucursal para consultar órdenes de trabajo. Si eres Super Admin con vista global, indica branchName (ej. 'Casa Matriz') para ver órdenes de esa sucursal.",
          };
        }

        // Resolve branch IDs to filter: demo data may have organization_id NULL, so filter by branch_id
        // (branch belongs to org). When Super Admin all-branches: get org branch IDs.
        let branchIdsToFilter: string[] | null = null;
        if (branchId) {
          branchIdsToFilter = [branchId];
        } else if (isSuperAdmin && isGlobalView) {
          const { data: orgBranches } = await supabase
            .from("branches")
            .select("id")
            .eq("organization_id", organizationId);
          branchIdsToFilter = (orgBranches as unknown[])?.map((b: unknown) => b.id) || [];
        }

        let query = supabase
          .from("lab_work_orders")
          .select(
            `
            id,
            work_order_number,
            work_order_date,
            status,
            payment_status,
            total_amount,
            currency,
            customer_id,
            frame_name,
            lens_type,
            branch_id,
            branch:branches(name),
            customers(first_name, last_name)
          `,
            { count: "exact" },
          )
          .order("work_order_date", { ascending: false });

        if (branchIdsToFilter && branchIdsToFilter.length > 0) {
          query = query.in("branch_id", branchIdsToFilter);
        } else if (
          Array.isArray(branchIdsToFilter) &&
          branchIdsToFilter.length === 0
        ) {
          query = query.eq("branch_id", "00000000-0000-0000-0000-000000000000");
        }

        if (validated.status) {
          query = query.eq("status", validated.status);
        } else if (
          validated.statuses &&
          Array.isArray(validated.statuses) &&
          validated.statuses.length > 0
        ) {
          query = query.in("status", validated.statuses);
        }

        if (validated.startDate) {
          query = query.gte("work_order_date", validated.startDate);
        }

        if (validated.endDate) {
          query = query.lte("work_order_date", validated.endDate);
        }

        const { data, error, count } = await query.range(
          validated.offset,
          validated.offset + validated.limit - 1,
        );

        if (error) {
          return { success: false, error: error.message };
        }

        return {
          success: true,
          data: {
            workOrders: data || [],
            total: count || 0,
          },
          message: `Encontradas ${count || 0} órdenes de trabajo`,
        };
      } catch (error: unknown) {
        return {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Failed to get work orders",
        };
      }
    },
  },
  {
    name: "getWorkOrderById",
    description:
      "Obtiene el detalle completo de una orden de trabajo por ID. Incluye cliente, sucursal, marco, lentes y montos.",
    category: "work_orders",
    parameters: {
      type: "object",
      properties: {
        workOrderId: {
          type: "string",
          description: "UUID de la orden de trabajo",
        },
      },
      required: ["workOrderId"],
    },
    zodSchema: getWorkOrderByIdSchema,
    execute: async (params, context): Promise<ToolResult> => {
      try {
        const validated = getWorkOrderByIdSchema.parse(params);
        const { supabase, organizationId } = context;

        if (!organizationId) {
          return {
            success: false,
            error: "Organization ID is missing in context",
          };
        }

        const { data, error } = await supabase
          .from("lab_work_orders")
          .select(
            `
            id,
            work_order_number,
            work_order_date,
            status,
            payment_status,
            total_amount,
            currency,
            subtotal,
            tax_amount,
            discount_amount,
            frame_name,
            frame_brand,
            frame_model,
            frame_color,
            lens_type,
            lens_material,
            lens_treatments,
            presbyopia_solution,
            frame_cost,
            lens_cost,
            labor_cost,
            treatments_cost,
            customer_id,
            branch_id,
            prescription_id,
            branch:branches(name),
            customers(first_name, last_name, phone, email),
            ready_at,
            delivered_at,
            ordered_at,
            sent_to_lab_at,
            internal_notes
          `,
          )
          .eq("id", validated.workOrderId)
          .eq("organization_id", organizationId)
          .single();

        if (error) {
          return { success: false, error: error.message };
        }

        if (!data) {
          return { success: false, error: "Orden de trabajo no encontrada" };
        }

        return {
          success: true,
          data,
          // @ts-expect-error: Supabase query returns dynamic shape
          message: `Orden de trabajo ${data.work_order_number}`,
        };
      } catch (error: unknown) {
        return {
          success: false,
          error:
            error instanceof Error ? error.message : "Failed to get work order",
        };
      }
    },
  },
];

/**
 * AI Usage Logger — logs LLM token usage for cost tracking.
 *
 * Two persistence paths:
 * 1. `logAIUsage()` → `ai_usage_log` table (org-level cost aggregation, existing)
 * 2. `logTokenUsage()` → `chat_messages.metadata.token_count` per message +
 *    `chat_sessions.metadata.token_count` accumulated per session (Phase 4)
 *
 * @module lib/ai/usage-logger
 */

import type { SupabaseClient } from "@supabase/supabase-js";

import { appLogger as logger } from "@/lib/logger";

export interface UsageLogEntry {
  organizationId: string;
  provider: string;
  model: string;
  promptTokens: number;
  completionTokens: number;
  endpoint?: string;
}

/**
 * Log AI usage to ai_usage_log. Fire-and-forget — does not throw.
 * Use when you have a Supabase client (user or service role) and usage info.
 */
export async function logAIUsage(
  supabase: SupabaseClient,
  entry: UsageLogEntry,
): Promise<void> {
  try {
    const { error } = await supabase.from("ai_usage_log").insert({
      organization_id: entry.organizationId,
      provider: entry.provider,
      model: entry.model,
      prompt_tokens: entry.promptTokens,
      completion_tokens: entry.completionTokens,
      endpoint: entry.endpoint ?? null,
    });

    if (error) {
      logger.warn("Failed to log AI usage", { error: error.message, entry });
    }
  } catch (err) {
    logger.warn("AI usage logging error", { err, entry });
  }
}

/**
 * Log token usage per message and accumulate per session.
 * Persists in chat_messages.metadata.token_count and chat_sessions.metadata.
 * Fire-and-forget — does not throw.
 */
export async function logTokenUsage(
  supabase: SupabaseClient,
  params: {
    sessionId: string;
    messageId: string;
    promptTokens: number;
    completionTokens: number;
  },
): Promise<void> {
  const { sessionId, messageId, promptTokens, completionTokens } = params;
  const tokenCount = {
    prompt: promptTokens,
    completion: completionTokens,
    total: promptTokens + completionTokens,
  };

  try {
    // 1. Persist per-message token_count in chat_messages.metadata
    const { error: msgError } = await supabase
      .from("chat_messages")
      .update({ metadata: { token_count: tokenCount } })
      .eq("id", messageId);

    if (msgError) {
      logger.warn("Failed to log per-message token usage", {
        error: msgError.message,
        sessionId,
        messageId,
      });
    }

    // 2. Accumulate in chat_sessions.metadata.token_count
    const { data: session } = await supabase
      .from("chat_sessions")
      .select("metadata")
      .eq("id", sessionId)
      .single();

    if (session) {
      const currentMeta = (session.metadata as Record<string, unknown>) || {};
      const existingTokens = (currentMeta.token_count as {
        prompt: number;
        completion: number;
        total: number;
      }) || { prompt: 0, completion: 0, total: 0 };
      const accumulated = {
        prompt: (existingTokens.prompt || 0) + promptTokens,
        completion: (existingTokens.completion || 0) + completionTokens,
        total: (existingTokens.total || 0) + promptTokens + completionTokens,
      };

      await supabase
        .from("chat_sessions")
        .update({ metadata: { ...currentMeta, token_count: accumulated } })
        .eq("id", sessionId);
    }
  } catch (err) {
    logger.warn("Token usage logging error", { err, sessionId, messageId });
  }
}

/**
 * Parse CSV and Excel files for bulk import.
 * @module lib/ai/utils/file-parser
 */

export interface ParsedRow {
  [key: string]: string | number | null;
}

export interface ParseResult {
  headers: string[];
  rows: ParsedRow[];
  rowCount: number;
}

export async function parseCSV(buffer: ArrayBuffer): Promise<ParseResult> {
  const text = new TextDecoder().decode(buffer);
  const lines = text.split(/\r?\n/).filter((l) => l.trim());

  if (lines.length === 0) {
    return { headers: [], rows: [], rowCount: 0 };
  }

  const parseLine = (line: string): string[] => {
    const result: string[] = [];
    let current = "";
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
      const c = line[i];
      if (c === '"') {
        inQuotes = !inQuotes;
      } else if ((c === "," && !inQuotes) || (c === ";" && !inQuotes)) {
        result.push(current.trim());
        current = "";
      } else {
        current += c;
      }
    }
    result.push(current.trim());
    return result;
  };

  const headers = parseLine(lines[0]);
  const rows: ParsedRow[] = [];

  for (let i = 1; i < lines.length; i++) {
    const values = parseLine(lines[i]);
    const row: ParsedRow = {};
    headers.forEach((h, idx) => {
      const val = values[idx];
      row[h] = val === undefined || val === "" ? null : val;
    });
    rows.push(row);
  }

  return {
    headers,
    rows,
    rowCount: rows.length,
  };
}

export async function parseExcel(buffer: ArrayBuffer): Promise<ParseResult> {
  const XLSX = await import("xlsx");
  const workbook = XLSX.read(new Uint8Array(buffer), { type: "array" });
  const sheet = workbook.Sheets[workbook.SheetNames[0]];
  const data = XLSX.utils.sheet_to_json<string[]>(sheet, {
    header: 1,
    defval: "",
  });

  if (data.length === 0) {
    return { headers: [], rows: [], rowCount: 0 };
  }

  const headerRow = data[0] as string[];
  const headers = headerRow.map((h) => String(h || "").trim());

  const rows: ParsedRow[] = [];
  for (let i = 1; i < data.length; i++) {
    const values = data[i] as (string | number)[];
    const row: ParsedRow = {};
    headers.forEach((h, idx) => {
      const val = values[idx];
      row[h] =
        val === undefined || val === null || String(val).trim() === ""
          ? null
          : val;
    });
    rows.push(row);
  }

  return {
    headers,
    rows,
    rowCount: rows.length,
  };
}

export async function parseImportFile(
  buffer: ArrayBuffer,
  filename: string,
): Promise<ParseResult> {
  const isCSV =
    filename.toLowerCase().endsWith(".csv") ||
    filename.toLowerCase().endsWith(".txt");
  const isExcel =
    filename.toLowerCase().endsWith(".xlsx") ||
    filename.toLowerCase().endsWith(".xls");

  if (isCSV) {
    return parseCSV(buffer);
  }
  if (isExcel) {
    return parseExcel(buffer);
  }

  throw new Error("Unsupported file format. Use CSV or Excel.");
}

export function sanitizeInput(input: string): string {
  if (typeof input !== "string") {
    return "";
  }

  return input.trim().replace(/[<>]/g, "").slice(0, 10000);
}

export function validateUUID(id: string): boolean {
  const uuidRegex =
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  return uuidRegex.test(id);
}

export function validateEmail(email: string): boolean {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
}

export function sanitizeToolParams(params: unknown): unknown {
  if (typeof params !== "object" || params === null) {
    return {};
  }

  const sanitized: unknown = {};

  for (const [key, value] of Object.entries(params)) {
    if (typeof value === "string") {
      sanitized[key] = sanitizeInput(value);
    } else if (typeof value === "number" && !isNaN(value) && isFinite(value)) {
      sanitized[key] = value;
    } else if (typeof value === "boolean") {
      sanitized[key] = value;
    } else if (Array.isArray(value)) {
      sanitized[key] = value.map((item) =>
        typeof item === "string" ? sanitizeInput(item) : item,
      );
    } else if (typeof value === "object" && value !== null) {
      sanitized[key] = sanitizeToolParams(value);
    }
  }

  return sanitized;
}

import { analyticsDashboardParamsSchema } from "@/lib/api/validation/zod-schemas";

export interface ProductBranchStockRecord {
  product_id: string;
  branch_id: string;
  quantity: number;
  low_stock_threshold?: number | null;
}

export interface ProductForInventory {
  id: string;
  name: string;
  slug?: string;
}

export interface InventoryMetricsResult {
  lowStock: number;
  outOfStock: number;
  lowStockProductsList?: Array<{
    id: string;
    name: string;
    currentStock: number;
    threshold: number;
    slug: string;
  }>;
}

/**
 * Compute inventory metrics from product_branch_stock records.
 * Replaces deprecated products.inventory_quantity logic.
 *
 * @param productBranchStock - Records from product_branch_stock (already filtered by branch)
 * @param productIdsInCatalog - Set of product IDs in the organization catalog
 * @param options - Optional: include list of low-stock products for dashboard display
 */
export function computeInventoryMetrics(
  productBranchStock: ProductBranchStockRecord[],
  productIdsInCatalog: Set<string>,
  options?: {
    products?: ProductForInventory[];
    maxLowStockList?: number;
  },
): InventoryMetricsResult {
  const lowStockProductIds = new Set<string>();
  const stockByProduct = new Map<
    string,
    { quantity: number; threshold: number }
  >();

  for (const record of productBranchStock) {
    const threshold = record.low_stock_threshold ?? 5;
    const qty = record.quantity ?? 0;

    if (!productIdsInCatalog.has(record.product_id)) continue;

    const key = record.product_id;

    if (qty > 0 && qty <= threshold) {
      lowStockProductIds.add(key);
    }

    const existing = stockByProduct.get(key);
    if (!existing || qty < existing.quantity) {
      stockByProduct.set(key, { quantity: qty, threshold });
    }
  }

  const outOfStockProductIds = new Set<string>();
  for (const productId of productIdsInCatalog) {
    const stock = stockByProduct.get(productId);
    const hasStock = stock && stock.quantity > 0;
    if (!hasStock) {
      outOfStockProductIds.add(productId);
    }
  }

  const result: InventoryMetricsResult = {
    lowStock: lowStockProductIds.size,
    outOfStock: outOfStockProductIds.size,
  };

  if (options?.products && options.maxLowStockList !== undefined) {
    const products = options.products;
    const lowStockList = products
      .filter((p) => lowStockProductIds.has(p.id))
      .map((p) => {
        const stock = stockByProduct.get(p.id);
        const qty = stock?.quantity ?? 0;
        const threshold = stock?.threshold ?? 5;
        return {
          id: p.id,
          name: p.name,
          currentStock: qty,
          threshold,
          slug: p.slug ?? p.id,
        };
      })
      .sort((a, b) => a.currentStock - b.currentStock)
      .slice(0, options.maxLowStockList);
    result.lowStockProductsList = lowStockList;
  }

  return result;
}

/**
 * Parse and validate the period parameter from analytics dashboard request.
 */
export function parseAnalyticsPeriod(searchParams: URLSearchParams): number {
  const { period } = analyticsDashboardParamsSchema.parse({
