const IN_PROGRESS_STATUSES = new Set([
  "sent_to_lab",
  "in_progress_lab",
  "ready_at_lab",
  "received_from_lab",
  "mounted",
  "quality_check",
]);

const PENDING_WO_STATUSES = new Set(["ordered", "quote"]);

const COMPLETED_WO_STATUSES = new Set(["delivered"]);

/**
 * Compute dashboard KPIs from mv_daily_kpis rows.
 *
 * @param mvRows — MV rows already filtered by org/branch
 * @param now — current date for period calculation
 */
export function computeDashboardKpis(
  mvRows: MvKpiRow[],
  now: Date,
): DashboardKpisResult {
  const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
  const lastMonthStart = new Date(now.getFullYear(), now.getMonth() - 1, 1);
  const lastMonthEnd = new Date(now.getFullYear(), now.getMonth(), 0);

  // Split rows by period
  const currentMonthRows = mvRows.filter((r) => {
    const d = new Date(r.day + "T00:00:00");
    return d >= monthStart && d <= now;
  });

  const lastMonthRows = mvRows.filter((r) => {
    const d = new Date(r.day + "T00:00:00");
    return d >= lastMonthStart && d <= lastMonthEnd;
  });

  // Revenue
  const currentRevenue = sumProp(currentMonthRows, "revenue");
  const previousRevenue = sumProp(lastMonthRows, "revenue");
  const revenueChange =
    previousRevenue > 0
      ? ((currentRevenue - previousRevenue) / previousRevenue) * 100
      : 0;

  // Orders total
  const totalOrders = sumProp(mvRows, "orders_count");

  // Quotes total
  const totalQuotes = sumProp(mvRows, "quotes_count");

  // Work orders — merge JSONB status distributions across all rows
  const allStatuses: Record<string, number> = {};
  for (const row of mvRows) {
    for (const [status, count] of Object.entries(
      row.work_orders_by_status ?? {},
    )) {
      allStatuses[status] = (allStatuses[status] ?? 0) + count;
    }
  }

  const workOrdersTotal = Object.values(allStatuses).reduce(
    (s, c) => s + c,
    0,
  );
  const inProgress = sumStatuses(allStatuses, IN_PROGRESS_STATUSES);
  const pendingWO = sumStatuses(allStatuses, PENDING_WO_STATUSES);
  const completedWO = sumStatuses(allStatuses, COMPLETED_WO_STATUSES);

  // Revenue trend
  const sorted = [...mvRows].sort((a, b) => a.day.localeCompare(b.day));
  const revenueTrend: RevenueTrendEntry[] = sorted.map((r) => ({
    date: r.day,
    revenue: Number(r.revenue),
    orders: Number(r.orders_count),
  }));

  return {
    revenue: {
      current: currentRevenue,
      previous: previousRevenue,
      change: revenueChange,
      currency: "CLP",
    },
    orders: { total: totalOrders },
    workOrders: {
      total: workOrdersTotal,
      inProgress,
      pending: pendingWO,
      completed: completedWO,
    },
    quotes: { total: totalQuotes },
    charts: { revenueTrend },
  };
}

function sumProp(rows: MvKpiRow[], key: "revenue" | "orders_count" | "quotes_count"): number {
  return rows.reduce((s, r) => s + Number(r[key]), 0);
}

function sumStatuses(
  statusMap: Record<string, number>,
  filter: Set<string>,
): number {
  let total = 0;
  for (const status of filter) {
    total += statusMap[status] ?? 0;
  }
  return total;
}

import type { SupabaseClient } from "@supabase/supabase-js";
import { NextRequest } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import { createClient } from "@/utils/supabase/server";

export interface BranchContext {
  branchId: string | null;
  isGlobalView: boolean;
  isSuperAdmin: boolean;
  /** User's organization_id from admin_users. Vision Global must be scoped to this org only. */
  organizationId: string | null;
  accessibleBranches: Array<{
    id: string;
    name: string;
    code: string;
    role: string;
    isPrimary: boolean;
  }>;
}

export interface OperativoContext {
  fieldOperationId: string | null;
}

/**
 * Extract field_operation_id from request (header or query param)
 */
export function getFieldOperationFromRequest(
  request: NextRequest,
): string | null {
  const headerId = request.headers.get("x-field-operation-id");
  if (headerId) return headerId;
  const { searchParams } = new URL(request.url);
  const queryId = searchParams.get("field_operation_id");
  return queryId || null;
}

/**
 * Get operativo context from request (field_operation_id if present)
 */
export function getOperativoContext(request: NextRequest): OperativoContext {
  const fieldOperationId = getFieldOperationFromRequest(request);
  return { fieldOperationId };
}

/**
 * Extract branch_id from request (header, query param, or user context)
 */
export async function getBranchFromRequest(
  request: NextRequest,
): Promise<string | null> {
  // Try header first
  const headerBranchId = request.headers.get("x-branch-id");
  if (headerBranchId) {
    return headerBranchId;
  }

  // Try query parameter
  const { searchParams } = new URL(request.url);
  const queryBranchId = searchParams.get("branch_id");
  if (queryBranchId) {
    return queryBranchId;
  }

  return null;
}

/**
 * Get branch context for the current user
 * @param request - NextRequest object
 * @param userId - User ID
 * @param supabaseClient - Optional Supabase client (if not provided, will use createClient())
 */
export async function getBranchContext(
  request: NextRequest,
  userId: string,
  supabaseClient?: SupabaseClient<unknown>,
): Promise<BranchContext> {
  let supabase: SupabaseClient<unknown>;
  try {
    supabase = supabaseClient || (await createClient());
  } catch (clientError: unknown) {
    logger.error(
      "Error creating Supabase client in getBranchContext:",
      clientError,
    );
    // Return default values if client creation fails
    return {
      branchId: null,
      isGlobalView: false,
      isSuperAdmin: false,
      organizationId: null,
      accessibleBranches: [],
    };
  }

  // User's organization_id (Vision Global must be scoped to this org only)
  let organizationId: string | null = null;
  try {
    const { data: adminUser } = await supabase
      .from("admin_users")
      .select("organization_id")
      .eq("id", userId)
      .single();
    organizationId =
      (adminUser as { organization_id?: string } | null)?.organization_id ??
      null;
  } catch (_) {}

  // Check if user is super admin: RPC (admin_branch_access.branch_id = null) OR role in admin_users
  let isSuperAdmin = false;
  try {
    const { data: superAdminData, error: superAdminError } = await supabase.rpc(
      "is_super_admin",
      {
        user_id: userId,
      },
    );
    if (superAdminError) {
      logger.error("Error checking super admin status:", superAdminError);
    } else {
      isSuperAdmin = superAdminData || false;
    }
    // Fallback: if RPC says no but user has super_admin/root/dev role, treat as super admin
    if (!isSuperAdmin) {
      const { data: adminUser } = await supabase
        .from("admin_users")
        .select("role")
        .eq("id", userId)
        .single();
      const role = (adminUser as { role?: string } | null)?.role;
      if (role === "super_admin" || role === "root" || role === "dev") {
        isSuperAdmin = true;
      }
    }
  } catch (err) {
    logger.error("Exception checking super admin status:", err);
    // Continue with isSuperAdmin = false
  }

  // Get user's accessible branches
  let branches: unknown[] = [];
  try {
    const { data: branchesData, error: branchesError } = await supabase.rpc(
      "get_user_branches",
      {
        user_id: userId,
      },
    );

    if (branchesError) {
      logger.error("Error fetching user branches:", branchesError);
      // Return default values if error occurs
      return {
        branchId: null,
        isGlobalView: false,
        isSuperAdmin: false,
        organizationId,
        accessibleBranches: [],
      };
    }

    branches = branchesData || [];
  } catch (err) {
    logger.error("Exception fetching user branches:", err);
    // Return default values if exception occurs
    return {
      branchId: null,
      isGlobalView: false,
      isSuperAdmin: false,
      organizationId,
      accessibleBranches: [],
    };
  }

  const accessibleBranches = (branches || []).map((b: unknown) => ({
    id: b.branch_id,
    name: b.branch_name,
    code: b.branch_code,
    role: b.role,
    isPrimary: b.is_primary,
  }));

  // Get requested branch from request
  const requestedBranchId = await getBranchFromRequest(request);

  // Determine current branch
  let branchId: string | null = null;
  let isGlobalView = false;

  if (isSuperAdmin) {
    // Super admin can use global view or specific branch
    if (requestedBranchId === "global" || requestedBranchId === null) {
      isGlobalView = true;
      branchId = null;
    } else if (requestedBranchId) {
      branchId = requestedBranchId;
      isGlobalView = false;
    } else {
      // Default to global view for super admin
      isGlobalView = true;
      branchId = null;
    }
  } else {
    // Regular admin must use a specific branch
    if (requestedBranchId) {
      // Validate access
      const hasAccess = accessibleBranches.some(
        (b: { id: string }) => b.id === requestedBranchId,
      );
      if (hasAccess) {
        branchId = requestedBranchId;
      } else {
        // Use primary branch if access denied
        const primaryBranch = accessibleBranches.find(
          (b: { isPrimary?: boolean }) => b.isPrimary,
        );
        branchId = primaryBranch?.id || accessibleBranches[0]?.id || null;
      }
    } else {
      // Use primary branch or first available
      const primaryBranch = accessibleBranches.find(
        (b: { isPrimary?: boolean }) => b.isPrimary,
      );
      branchId = primaryBranch?.id || accessibleBranches[0]?.id || null;
    }
  }

  return {
    branchId,
    isGlobalView,
    isSuperAdmin: isSuperAdmin || false,
    organizationId,
    accessibleBranches,
  };
}

/**
 * Validate that user can access a specific branch
 */
export async function validateBranchAccess(
  userId: string,
  branchId: string | null,
): Promise<boolean> {
  if (branchId === null) {
    // Only super admin can access global view
    const supabase = await createClient();
    const { data: isSuperAdmin } = await supabase.rpc("is_super_admin", {
      user_id: userId,
    });
    return isSuperAdmin || false;
  }

  const supabase = await createClient();
  const { data: canAccess } = await supabase.rpc("can_access_branch", {
    user_id: userId,
    p_branch_id: branchId,
  });

  return canAccess || false;
}

/**
 * Add branch filter to a Supabase query.
 * When in global view (isSuperAdmin && !branchId), scope by organizationId so Vision Global
 * never shows data from other organizations.
 */
export function addBranchFilter(
  query: unknown,
  branchId: string | null,
  isSuperAdmin: boolean,
  organizationId?: string | null,
) {
  if (isSuperAdmin && branchId === null) {
    // Vision Global: only show data from the user's organization
    if (organizationId) {
      return query.eq("organization_id", organizationId);
    }
    // No organization (e.g. platform admin): return no rows to avoid leaking other orgs
    return query.eq("organization_id", "00000000-0000-0000-0000-000000000000");
  }

  if (branchId) {
    return query.eq("branch_id", branchId);
  }

  return query.eq("branch_id", "00000000-0000-0000-0000-000000000000");
}

/**
 * Add branch filter for tables that only have branch_id (no organization_id).
 * Use for: customers, etc.
 * When in global view, fetches branch IDs for the org and filters by .in("branch_id", ids).
 */
export async function addBranchFilterForBranchScopedTable(
  query: unknown,
  branchContext: BranchContext,
  supabase: SupabaseClient<unknown>,
) {
  const { branchId, isSuperAdmin, organizationId, accessibleBranches } =
    branchContext;

  if (branchId) {
    return query.eq("branch_id", branchId);
  }

  if (isSuperAdmin && organizationId) {
    const { data: branches } = await supabase
      .from("branches")
      .select("id")
      .eq("organization_id", organizationId);
    const branchIds = branches?.map((b: { id: string }) => b.id) || [];
    if (branchIds.length > 0) {
      return query.in("branch_id", branchIds);
    }
    return query.eq("branch_id", "00000000-0000-0000-0000-000000000000");
  }

  const primaryBranchId =
    accessibleBranches.find((b: { isPrimary?: boolean }) => b.isPrimary)?.id ||
    accessibleBranches[0]?.id;
  return primaryBranchId
    ? query.eq("branch_id", primaryBranchId)
    : query.eq("branch_id", "00000000-0000-0000-0000-000000000000");
}

import { NextRequest, NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import type {
  GetAdminRoleParams,
  GetAdminRoleResult,
  IsAdminParams,
  IsAdminResult,
  LogAdminActivityParams,
} from "@/types/supabase-rpc";
import { createServiceRoleClient } from "@/utils/supabase/server";

import { AuthenticationError, AuthorizationError } from "./errors";

// Authentication middleware
export async function requireAuth(request: NextRequest): Promise<{
  userId: string;
  user: { id: string; email?: string; [key: string]: unknown };
}> {
  const authorization = request.headers.get("authorization");

  if (!authorization?.startsWith("Bearer ")) {
    throw new AuthenticationError("Authorization header required");
  }

  const token = authorization.slice(7);

  try {
    const supabase = createServiceRoleClient();
    const {
      data: { user },
      error,
    } = await supabase.auth.getUser(token);

    if (error || !user) {
      throw new AuthenticationError("Invalid or expired token");
    }

    return { userId: user.id, user: { email: user.email, ...user } };
  } catch (error) {
    throw new AuthenticationError("Authentication failed");
  }
}

// Role-based authorization middleware using admin_users table
export async function requireRole(
  userId: string,
  requiredRole: string = "admin",
): Promise<void> {
  const supabase = createServiceRoleClient();

  try {
    // Check if user is in admin_users table
    const { data: isAdmin, error: adminError } = (await supabase.rpc(
      "is_admin",
      { user_id: userId } as IsAdminParams,
    )) as { data: IsAdminResult | null; error: Error | null };

    if (adminError) {
      logger.error("Error checking admin status:", {
        error: adminError,
        userId,
      });
      throw new AuthorizationError("Unable to verify admin status");
    }

    if (!isAdmin) {
      throw new AuthorizationError(
        "Insufficient permissions - admin access required",
      );
    }

    // If specific role is required, check that too
    if (requiredRole !== "admin") {
      const { data: userRole, error: roleError } = (await supabase.rpc(
        "get_admin_role",
        { user_id: userId } as GetAdminRoleParams,
      )) as { data: GetAdminRoleResult | null; error: Error | null };

      if (roleError) {
        logger.error("Error getting admin role:", { error: roleError, userId });
        throw new AuthorizationError("Unable to verify admin role");
      }

      // Simplified role system - only 'admin' role
      if (userRole !== "admin") {
        throw new AuthorizationError("Admin role required");
      }

      // Check if required role is also admin
      if (requiredRole && requiredRole !== "admin") {
        throw new AuthorizationError(
          `Invalid role requirement - only 'admin' role exists`,
        );
      }
    }

    logger.debug(
      `Admin access verified for user ${userId} with role check: ${requiredRole}`,
    );
  } catch (error) {
    if (error instanceof AuthorizationError) {
      throw error;
    }
    logger.error("Unexpected error in role check:", { error, userId });
    throw new AuthorizationError("Authentication system error");
  }
}

// Log admin activity for audit trail
export async function logAdminActivity(
  userId: string,
  action: string,
  resourceType: string,
  resourceId?: string,
  details?: Record<string, unknown> | string,
): Promise<void> {
  try {
    const supabase = createServiceRoleClient();

    const params: LogAdminActivityParams = {
      p_action: action,
      p_resource_type: resourceType,
      p_resource_id: resourceId || null,
      p_details: details
        ? typeof details === "string"
          ? details
          : JSON.stringify(details)
        : null,
    };

    await supabase.rpc("log_admin_activity", params);
  } catch (error) {
    logger.error("Error logging admin activity:", {
      error,
      userId,
      action,
      resourceType,
    });
    // Don't throw here - logging failures shouldn't break the main operation
  }
}

// CORS middleware
export function withCORS(
  response: NextResponse,
  origin?: string,
  methods: string[] = ["GET", "POST", "PUT", "DELETE", "OPTIONS"],
): NextResponse {
  const allowedOrigins = [
    process.env.NEXT_PUBLIC_APP_URL,
    "http://localhost:3000",
    "https://opttius.com",
    "https://www.opttius.com",
  ].filter(Boolean);

  if (origin && allowedOrigins.includes(origin)) {
    response.headers.set("Access-Control-Allow-Origin", origin);
  }

  response.headers.set("Access-Control-Allow-Methods", methods.join(", "));
  response.headers.set(
    "Access-Control-Allow-Headers",
    "Content-Type, Authorization",
  );
  response.headers.set("Access-Control-Max-Age", "86400"); // 24 hours

  return response;
}

// Get client identifier for request logging
function getClientIdentifier(request: NextRequest): string {
  const xForwardedFor = request.headers.get("x-forwarded-for");
  const xRealIp = request.headers.get("x-real-ip");
  const clientIp =
    xForwardedFor?.split(",")[0] || xRealIp || request.ip || "unknown";
  const userAgent = request.headers.get("user-agent") || "unknown";
  return `${clientIp}:${userAgent.substring(0, 50)}`;
}

// Request logging middleware
export function logRequest(
  request: NextRequest,
  startTime: number = Date.now(),
) {
  const method = request.method;
  const url = request.url;
  const userAgent = request.headers.get("user-agent") || "unknown";
  const clientIp = getClientIdentifier(request).split(":")[0];

  logger.debug("Request received", { method, url, clientIp, userAgent });

  // Return a function to log the response
  return (response: NextResponse) => {
    const duration = Date.now() - startTime;
    const status = response.status;

    logger.debug("Request completed", { method, url, status, duration });
  };
}

// Middleware composer to chain multiple middlewares
export function composeMiddleware(
  ...middlewares: Array<
    (
      request: NextRequest,
      handler: () => Promise<NextResponse>,
    ) => Promise<NextResponse>
  >
) {
  return async (
    request: NextRequest,
    baseHandler: () => Promise<NextResponse>,
  ) => {
    let handler = baseHandler;

    // Apply middlewares in reverse order
    for (let i = middlewares.length - 1; i >= 0; i--) {
      const middleware = middlewares[i];
      const currentHandler = handler;
      handler = () => middleware(request, currentHandler);
    }

    return handler();
  };
}

// Request ID middleware
export function withRequestId(response: NextResponse): NextResponse {
  const requestId = crypto.randomUUID();
  response.headers.set("X-Request-ID", requestId);
  return response;
}

// Health check bypass (skip rate limiting for health checks)
export function isHealthCheck(request: NextRequest): boolean {
  const url = new URL(request.url);
  return url.pathname === "/api/health" || url.pathname === "/health";
}

/**
 * API Response Helpers
 *
 * Helper functions to extract data from API responses that may be in either
 * legacy format or standardized format.
 *
 * Legacy format: { customers: [...], pagination: {...} }
 * Standardized format: { success: true, data: [...], meta: { pagination: {...} } }
 */

/**
 * Extract data from API response (handles both legacy and standardized formats)
 *
 * @param response - The API response object
 * @returns Array of data items
 *
 * @example
 * // Standardized format
 * const response = { success: true, data: [{ id: 1 }], meta: {...} };
 * const data = extractDataFromResponse(response); // [{ id: 1 }]
 *
 * // Legacy format
 * const legacyResponse = { customers: [{ id: 1 }], pagination: {...} };
 * const data = extractDataFromResponse(legacyResponse); // [{ id: 1 }]
 */
export function extractDataFromResponse<T>(response: unknown): T[] {
  // Handle null/undefined
  if (!response) {
    return [];
  }

  // Standardized format: { success: true, data: [...], meta: {...} }
  if (response.success === true && Array.isArray(response.data)) {
    return response.data;
  }

  // Legacy format: { customers: [...] } or { products: [...] } etc.
  const dataKeys = [
    "customers",
    "products",
    "orders",
    "quotes",
    "workOrders",
    "work_orders",
    "prescriptions",
    "appointments",
    "users",
    "tickets",
    "messages",
    "adminUsers",
    "branches",
    "inventory",
    "categories",
    "families",
  ];
  for (const key of dataKeys) {
    if (Array.isArray(response[key])) {
      return response[key];
    }
  }

  // Fallback: return empty array
  return [];
}

/**
 * Extract pagination from API response (handles both legacy and standardized formats)
 *
 * @param response - The API response object
 * @returns Pagination metadata
 *
 * @example
 * // Standardized format
 * const response = { success: true, data: [...], meta: { pagination: {...} } };
 * const pagination = extractPaginationFromResponse(response);
 *
 * // Legacy format
 * const legacyResponse = { customers: [...], pagination: {...} };
 * const pagination = extractPaginationFromResponse(legacyResponse);
 */
export function extractPaginationFromResponse(response: unknown): {
  page: number;
  limit: number;
  total: number;
  totalPages: number;
  hasNextPage?: boolean;
  hasPreviousPage?: boolean;
} {
  // Handle null/undefined
  if (!response) {
    return {
      page: 1,
      limit: 10,
      total: 0,
      totalPages: 0,
    };
  }

  // Standardized format: { success: true, data: [...], meta: { pagination: {...} } }
  if (response.success === true && response.meta?.pagination) {
    return response.meta.pagination;
  }

  // Legacy format: { pagination: {...} }
  if (response.pagination) {
    return response.pagination;
  }

  // Fallback: return default pagination
  return {
    page: 1,
    limit: 10,
    total: 0,
    totalPages: 0,
  };
}

/**
 * Extract total count from API response (handles both legacy and standardized formats)
 *
 * @param response - The API response object
 * @returns Total count of items
 *
 * @example
 * // Standardized format
 * const response = { success: true, data: [...], meta: { pagination: { total: 100 } } };
 * const total = extractTotalFromResponse(response); // 100
 *
 * // Legacy format
 * const legacyResponse = { customers: [...], total: 100 };
 * const total = extractTotalFromResponse(legacyResponse); // 100
 */
export function extractTotalFromResponse(response: unknown): number {
  // Handle null/undefined
  if (!response) {
    return 0;
  }

  // Standardized format: { success: true, data: [...], meta: { pagination: { total: ... } } }
  if (
    response.success === true &&
    response.meta?.pagination?.total !== undefined
  ) {
    return response.meta.pagination.total;
  }

  // Legacy format: { total: ... }
  if (response.total !== undefined) {
    return response.total;
  }

  // Legacy format: { pagination: { total: ... } }
  if (response.pagination?.total !== undefined) {
    return response.pagination.total;
  }

  // Fallback: return 0
  return 0;
}

/**
 * Check if response is successful (handles both legacy and standardized formats)
 *
 * @param response - The API response object
 * @returns True if response is successful
 *
 * @example
 * // Standardized format
 * const response = { success: true, data: [...], meta: {...} };
 * const isSuccess = isResponseSuccessful(response); // true
 *
 * // Legacy format (no success field, assume successful if no error)
 * const legacyResponse = { customers: [...], pagination: {...} };
 * const isSuccess = isResponseSuccessful(legacyResponse); // true
 */
export function isResponseSuccessful(response: unknown): boolean {
  // Handle null/undefined
  if (!response) {
    return false;
  }

  // Standardized format: { success: true/false }
  if (response.success !== undefined) {
    return response.success === true;
  }

  // Legacy format: assume successful if no error field
  return !response.error;
}

/**
 * Extract error from API response (handles both legacy and standardized formats)
 *
 * @param response - The API response object
 * @returns Error message or null if no error
 *
 * @example
 * // Standardized format
 * const response = { success: false, error: { code: 'ERROR', message: 'Something went wrong' } };
 * const error = extractErrorFromResponse(response); // 'Something went wrong'
 *
 * // Legacy format
 * const legacyResponse = { error: 'Something went wrong' };
 * const error = extractErrorFromResponse(legacyResponse); // 'Something went wrong'
 */
export function extractErrorFromResponse(response: unknown): string | null {
  // Handle null/undefined
  if (!response) {
    return null;
  }

  // Standardized format: { success: false, error: { message: '...' } }
  if (response.success === false && response.error?.message) {
    return response.error.message;
  }

  // Legacy format: { error: '...' }
  if (response.error) {
    return typeof response.error === "string"
      ? response.error
      : response.error.message || "Unknown error";
  }

  // No error
  return null;
}

import { NextResponse } from "next/server";

import { appLogger as logger } from "@/lib/logger";

import { APIError } from "./errors";

/**
 * Standardized API Response Types
 * Following the API Response Standardization plan from TECHNICAL_RECOMMENDATIONS.md
 */

// Pagination metadata
export interface PaginationMeta {
  page: number;
  limit: number;
  total: number;
  totalPages: number;
  hasNextPage?: boolean;
  hasPreviousPage?: boolean;
}

// Standard success response
export interface ApiSuccessResponse<T = unknown> {
  success: true;
  data: T;
  meta?: {
    pagination?: PaginationMeta;
    timestamp: string;
    requestId?: string;
    [key: string]: unknown;
  };
}

// Standard error response
export interface ApiErrorResponse {
  success: false;
  error: {
    code: string;
    message: string;
    details?:
      | Record<string, unknown>
      | Array<{ field: string; message: string }>;
    timestamp: string;
    requestId?: string;
    stack?: string; // Only in development
  };
}

// Union type for all API responses
export type ApiResponse<T = unknown> = ApiSuccessResponse<T> | ApiErrorResponse;

/**
 * Create a standardized success response
 */
export function createApiSuccessResponse<T>(
  data: T,
  options?: {
    statusCode?: number;
    requestId?: string;
    pagination?: PaginationMeta;
    meta?: Record<string, unknown>;
  },
): NextResponse<ApiSuccessResponse<T>> {
  const { statusCode = 200, requestId, pagination, meta = {} } = options || {};

  const response: ApiSuccessResponse<T> = {
    success: true,
    data,
    meta: {
      ...meta,
      timestamp: new Date().toISOString(),
      ...(requestId && { requestId }),
      ...(pagination && { pagination }),
    },
  };

  return NextResponse.json(response, { status: statusCode });
}

/**
 * Create a standardized error response
 */
export function createApiErrorResponse(
  error: APIError | Error,
  options?: {
    requestId?: string;
    details?:
      | Record<string, unknown>
      | Array<{ field: string; message: string }>;
  },
): NextResponse<ApiErrorResponse> {
  const { requestId, details } = options || {};

  const isAPIError = error instanceof APIError;
  const statusCode = isAPIError ? error.statusCode : 500;
  const code = isAPIError ? error.code : "INTERNAL_ERROR";

  // Don't expose internal errors in production
  const message =
    process.env.NODE_ENV === "production" && !isAPIError
      ? "Internal server error"
      : error.message;

  const errorResponse: ApiErrorResponse = {
    success: false,
    error: {
      code,
      message,
      timestamp: new Date().toISOString(),
      ...(requestId && { requestId }),
      ...(details && { details }),
      ...(process.env.NODE_ENV === "development" &&
        error.stack && { stack: error.stack }),
    },
  };

  // Log error for monitoring
  logger.error("API Error Response", {
    code,
    message: error.message,
    statusCode,
    requestId,
    stack: error.stack,
  });

  return NextResponse.json(errorResponse, { status: statusCode });
}

/**
 * Create a paginated success response
 */
export function createPaginatedResponse<T>(
  data: T[],
  pagination: {
    page: number;
    limit: number;
    total: number;
  },
  options?: {
    requestId?: string;
    meta?: Record<string, unknown>;
  },
): NextResponse<ApiSuccessResponse<T[]>> {
  const { page, limit, total } = pagination;
  const totalPages = Math.ceil(total / limit);
  const hasNextPage = page < totalPages;
  const hasPreviousPage = page > 1;

  const paginationMeta: PaginationMeta = {
    page,
    limit,
    total,
    totalPages,
    hasNextPage,
    hasPreviousPage,
  };

  return createApiSuccessResponse(data, {
    ...options,
    pagination: paginationMeta,
  });
}

/**
 * API Response wrapper for consistent handling
 */
export class ApiResponseBuilder<T = unknown> {
  private data?: T;
  private error?: APIError | Error;
  private statusCode: number = 200;
  private requestId?: string;
  private pagination?: PaginationMeta;
  private meta: Record<string, unknown> = {};

  /**
   * Set success data
   */
  setData(data: T): this {
    this.data = data;
    return this;
  }

  /**
   * Set error
   */
  setError(error: APIError | Error, statusCode?: number): this {
    this.error = error;
    if (statusCode) {
      this.statusCode = statusCode;
    } else if (error instanceof APIError) {
      this.statusCode = error.statusCode;
    }
    return this;
  }

  /**
   * Set status code
   */
  setStatusCode(statusCode: number): this {
    this.statusCode = statusCode;
    return this;
  }

  /**
   * Set request ID
   */
  setRequestId(requestId: string): this {
    this.requestId = requestId;
    return this;
  }

  /**
   * Set pagination metadata
   */
  setPagination(pagination: PaginationMeta): this {
    this.pagination = pagination;
    return this;
  }

  /**
   * Add custom metadata
   */
  addMeta(key: string, value: unknown): this {
    this.meta[key] = value;
    return this;
  }

  /**
   * Build the response
   */
  build(): NextResponse<ApiResponse<T>> {
    if (this.error) {
      return createApiErrorResponse(this.error, {
        requestId: this.requestId,
      });
    }

    return createApiSuccessResponse(this.data!, {
      statusCode: this.statusCode,
      requestId: this.requestId,
      pagination: this.pagination,
      meta: this.meta,
    });
  }
}

/**
 * Async handler with standardized response format
 */
export function withApiResponse<T = unknown>(
  handler: (request: Request, context?: unknown) => Promise<T>,
): (
  request: Request,
  context?: unknown,
) => Promise<NextResponse<ApiResponse<T>>> {
  return async (
    request: Request,
    context?: unknown,
  ): Promise<NextResponse<ApiResponse<T>>> => {
    const requestId = crypto.randomUUID();

    try {
      const data = await handler(request, context);
      return createApiSuccessResponse(data, { requestId });
    } catch (error) {
      return createApiErrorResponse(
        error instanceof Error ? error : new Error("Unknown error"),
        { requestId },
      );
    }
  };
}

/**
 * Helper function to extract pagination params from URL
 */
export function extractPaginationParams(url: string): {
  page: number;
  limit: number;
} {
  const searchParams = new URL(url).searchParams;
  const page = parseInt(searchParams.get("page") || "1", 10);
  const limit = parseInt(searchParams.get("limit") || "10", 10);

  // Validate and sanitize
  return {
    page: Math.max(1, page),
    limit: Math.min(Math.max(1, limit), 100), // Max 100 items per page
  };
}

/**
 * Helper to check if response is successful
 */
export function isSuccessResponse<T>(
  response: ApiResponse<T>,
): response is ApiSuccessResponse<T> {
  return response.success === true;
}

/**
 * Helper to check if response is an error
 */
export function isErrorResponse(
  response: ApiResponse<unknown>,
): response is ApiErrorResponse {
  return response.success === false;
}

import { NextRequest } from "next/server";

import { AuthorizationError } from "@/lib/api/errors";
import { appLogger as logger } from "@/lib/logger";
import { createRootAdminClient } from "@/utils/supabase/root-admin";
import { createClient } from "@/utils/supabase/server";

/**
 * Require root or dev role for access
 * Throws AuthorizationError if user is not root/dev
 *
 * Performance: Uses service role client to bypass RLS for verification
 * Consider caching result with short TTL if called frequently
 *
 * @param request - NextRequest object
 * @returns Object with userId and user info if authorized
 * @throws AuthorizationError if user is not root/dev
 */
export async function requireRoot(request: NextRequest): Promise<{
  userId: string;
  user: { id: string; email?: string };
}> {
  const supabase = await createClient();
  const supabaseServiceRole = createRootAdminClient();

  // Get current user
  const {
    data: { user },
    error: userError,
  } = await supabase.auth.getUser();

  if (userError || !user) {
    throw new AuthorizationError("Unauthorized");
  }

  // Check if user is root/dev using service role to bypass RLS
  const { data: adminUser, error: adminError } = await supabaseServiceRole
    .from("admin_users")
    .select("role")
    .eq("id", user.id)
    .single();

  if (adminError) {
    logger.error("Error checking root status", adminError);
    throw new AuthorizationError("Unable to verify root status");
  }

  const isRoot = adminUser?.role === "root" || adminUser?.role === "dev";

  if (!isRoot) {
    throw new AuthorizationError("Root access required");
  }

  logger.debug(`Root access verified for user ${user.id}`);

  return {
    userId: user.id,
    user: {
      id: user.id,
      email: user.email,
    },
  };
}

/**
 * Check if user is root/dev (non-throwing version)
 * Useful for conditional logic without throwing errors
 *
 * @param userId - User ID to check
 * @returns true if user is root/dev, false otherwise
 */
export async function isRootUser(userId: string): Promise<boolean> {
  try {
    const supabaseServiceRole = createRootAdminClient();

    const { data: adminUser, error } = await supabaseServiceRole
      .from("admin_users")
      .select("role")
      .eq("id", userId)
      .single();

    if (error || !adminUser) {
      return false;
    }

    return adminUser.role === "root" || adminUser.role === "dev";
  } catch (error) {
    logger.error("Error checking if user is root", error);
    return false;
  }
}

import type { createClient, createServiceRoleClient } from "@/utils/supabase/server";

export interface ConfigRow {
  config_key: string; config_value?: unknown; organization_id?: string | null; branch_id?: string | null;
  [k: string]: unknown;
}

export function isLegacySchemaError(error: { message?: string; code?: string } | null): boolean {
  if (!error) return false;
  const msg = (error.message || "").toLowerCase();
  return error.code === "42703" || msg.includes("organization_id") || msg.includes("branch_id") || msg.includes("does not exist");
}

export function parseConfigValue(value: unknown): unknown {
  if (typeof value === "string") { try { return JSON.parse(value); } catch { return value; } }
  return value;
}

export async function fetchLegacyConfigs(
  supabaseAdmin: ReturnType<typeof createServiceRoleClient>,
  publicOnly: boolean, category: string,
): Promise<ConfigRow[]> {
  let q = supabaseAdmin.from("system_config").select("*").order("category", { ascending: true }).order("config_key", { ascending: true });
  if (publicOnly) q = q.eq("is_public", true);
  if (category && category !== "all") q = q.eq("category", category);
  const res = await q;
  return (res.data ?? []) as ConfigRow[];
}

export async function getAdminAuth(supabase: Awaited<ReturnType<typeof createClient>>): Promise<{ user: { id: string }; orgId: string | null; isSuperAdmin: boolean }> {
  const { data: { user }, error: userError } = await supabase.auth.getUser();
  if (userError || !user) throw new Error("Unauthorized");
  const { data: adminUser } = await supabase.from("admin_users").select("organization_id, role").eq("id", user.id).eq("is_active", true).maybeSingle();
  if (!adminUser) throw new Error("Admin access required");
  return { user, orgId: adminUser.organization_id, isSuperAdmin: adminUser.role === "super_admin" };
}

export async function resolveScope(
  supabase: Awaited<ReturnType<typeof createClient>>,
  branchId: string | null, orgId: string | null, isSuperAdmin: boolean,
): Promise<{ targetOrgId: string | null; targetBranchId: string | null }> {
  if (isSuperAdmin) {
    if (branchId && orgId) {
      const { data: branch } = await supabase.from("branches").select("id, organization_id").eq("id", branchId).maybeSingle();
      if (!branch || branch.organization_id !== orgId) throw new Error("Sucursal no válida o no pertenece a tu organización. Selecciona una sucursal válida.");
      return { targetOrgId: orgId, targetBranchId: branchId };
    }
    return { targetOrgId: null, targetBranchId: null };
  }
  if (branchId && orgId) {
    const { data: branch } = await supabase.from("branches").select("id, organization_id").eq("id", branchId).maybeSingle();
    if (!branch || branch.organization_id !== orgId) throw new Error("Sucursal no válida o no pertenece a tu organización.");
  }
  return { targetOrgId: orgId, targetBranchId: branchId || null };
}

/**
 * Admin Appointment Service
 * Server-side business logic for appointment operations
 */
import { NextRequest, NextResponse } from "next/server";

import { addBranchFilter, getBranchContext } from "@/lib/api/branch-middleware";
import { AuthenticationError, AuthorizationError, ValidationError } from "@/lib/api/errors";
import { createApiSuccessResponse } from "@/lib/api/response";
import { validateBody, validationErrorResponse } from "@/lib/api/validation/zod-helpers";
import { createAppointmentSchema } from "@/lib/api/validation/zod-schemas";
import { sendAppointmentConfirmation } from "@/lib/email/notifications";
import { appLogger as logger } from "@/lib/logger";
import { NotificationService } from "@/lib/notifications/notification-service";
import { formatRUT } from "@/lib/utils/rut";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient, createServiceRoleClient } from "@/utils/supabase/server";

async function getAdminAuth(supabase: unknown) {
  const { data: { user }, error: userError } = await supabase.auth.getUser();
  if (userError || !user) throw new AuthenticationError("Unauthorized");
  const { data: isAdmin } = (await supabase.rpc("is_admin", {
    user_id: user.id,
  } as IsAdminParams)) as { data: IsAdminResult | null };
  if (!isAdmin) throw new AuthorizationError("Admin access required");
  return user;
}

export async function listAppointments(request: NextRequest) {
  const requestId = crypto.randomUUID();
  logger.info("Appointments API GET called", { requestId });

  const supabase = await createClient();
  const user = await getAdminAuth(supabase);
  const branchContext = await getBranchContext(request, user.id);

  const searchParams = request.nextUrl.searchParams;
  const startDate = searchParams.get("start_date") ?? searchParams.get("date_from");
  const endDate = searchParams.get("end_date") ?? searchParams.get("date_to");
  const status = searchParams.get("status");
  const customerId = searchParams.get("customer_id");
  const staffId = searchParams.get("staff_id");
  const requestedBranchId = searchParams.get("branch_id");
  const branchIdToFilter = requestedBranchId || branchContext.branchId;

  let query = supabase
    .from("appointments")
    .select("*, guest_first_name, guest_last_name, guest_rut, guest_email, guest_phone")
    .order("appointment_date", { ascending: true })
    .order("appointment_time", { ascending: true });

  if (requestedBranchId) {
    query = query.eq("branch_id", requestedBranchId);
  } else {
    query = addBranchFilter(query, branchContext.branchId, branchContext.isSuperAdmin, branchContext.organizationId);
  }

  if (startDate) query = query.gte("appointment_date", startDate);
  if (endDate) query = query.lte("appointment_date", endDate);
  if (status) query = query.eq("status", status);
  if (customerId) query = query.eq("customer_id", customerId);
  if (staffId) query = query.eq("assigned_to", staffId);

  const { data: appointments, error } = await query;
  if (error) {
    logger.error("Error fetching appointments", error);
    throw new Error(error.message || "Failed to fetch appointments");
  }

  if (!appointments || appointments.length === 0) {
    return createApiSuccessResponse([], { requestId });
  }

  // Batch fetch related data
  const customerIds = [...new Set(appointments.map((a: unknown) => a.customer_id).filter(Boolean))];
  const staffIds = [...new Set(appointments.map((a: unknown) => a.assigned_to).filter(Boolean))];
  const prescriptionIds = [...new Set(appointments.map((a: unknown) => a.prescription_id).filter(Boolean))];
  const orderIds = [...new Set(appointments.map((a: unknown) => a.order_id).filter(Boolean))];

  const [{ data: customers }, { data: staff }, { data: prescriptions }, { data: orders }] = await Promise.all([
    customerIds.length > 0 ? supabase.from("customers").select("id, first_name, last_name, email, phone").in("id", customerIds) : Promise.resolve({ data: [] }),
    staffIds.length > 0 ? supabase.from("profiles").select("id, first_name, last_name").in("id", staffIds) : Promise.resolve({ data: [] }),
    prescriptionIds.length > 0 ? supabase.from("prescriptions").select("id, prescription_date, prescription_type").in("id", prescriptionIds) : Promise.resolve({ data: [] }),
    orderIds.length > 0 ? supabase.from("orders").select("id, order_number").in("id", orderIds) : Promise.resolve({ data: [] }),
  ]);

  const appointmentsWithRelations = (appointments as unknown[]).map((appointment) => ({
    ...appointment,
    customer: (customers as unknown[])?.find((c) => c.id === appointment.customer_id) || null,
    assigned_staff: (staff as unknown[])?.find((s) => s.id === appointment.assigned_to) || null,
    prescription: (prescriptions as unknown[])?.find((p) => p.id === appointment.prescription_id) || null,
    order: (orders as unknown[])?.find((o) => o.id === appointment.order_id) || null,
  }));

  return createApiSuccessResponse(appointmentsWithRelations, { requestId });
}

export async function createAppointment(request: NextRequest) {
  const supabase = await createClient();
  const supabaseServiceRole = createServiceRoleClient();
  const user = await getAdminAuth(supabase);
  const branchContext = await getBranchContext(request, user.id);

  const defaultBranchForNonSuperAdmin =
    !branchContext.isSuperAdmin && branchContext.accessibleBranches.length > 0
      ? branchContext.accessibleBranches.find((b: unknown) => b.isPrimary)?.id || branchContext.accessibleBranches[0]?.id
      : null;
  const effectiveBranchId = branchContext.branchId || defaultBranchForNonSuperAdmin;

  if (!branchContext.isSuperAdmin && !effectiveBranchId) {
    return NextResponse.json({ error: "Debe seleccionar una sucursal para crear citas" }, { status: 400 });
  }

  let body: unknown;
  try { body = await request.json(); } catch {
    return NextResponse.json({ error: "Invalid JSON in request body" }, { status: 400 });
  }

  let validatedBody: unknown;
  try { validatedBody = validateBody(body, createAppointmentSchema); } catch (error) {
    if (error instanceof ValidationError) return validationErrorResponse(error);
    throw error;
  }

  const finalBranchId = validatedBody.branch_id || branchContext.branchId || defaultBranchForNonSuperAdmin;
  if (!finalBranchId) {
    return NextResponse.json({ error: "Debe especificar una sucursal para crear la cita" }, { status: 400 });
  }

  const normalizedTime = validatedBody.appointment_time;
  const timeForRPC = normalizedTime.substring(0, 8);
  const forceCreate = body.force_create === true;

  // Check availability
  if (!forceCreate) {
    const durationMinutes = body.duration_minutes || validatedBody.duration_minutes || 30;
    const { data: slots, error: slotsError } = (await supabaseServiceRole.rpc("get_available_time_slots", {
      p_date: validatedBody.appointment_date,
      p_duration_minutes: durationMinutes,
      p_staff_id: body.assigned_to || null,
      p_branch_id: finalBranchId,
    })) as unknown;

    if (slotsError) {
      return NextResponse.json({ error: "Error checking availability", details: slotsError.message }, { status: 500 });
    }

    const normalizedTimeForCompare = timeForRPC.substring(0, 5);
    const matchingSlot = (slots || []).find((slot: unknown) => {
      let slotTime = slot.time_slot;
      if (typeof slotTime === "object" && slotTime !== null) {
        if ("hours" in slotTime && "minutes" in slotTime) {
          slotTime = `${String(slotTime.hours).padStart(2, "0")}:${String(slotTime.minutes).padStart(2, "0")}`;
        }
      }
      if (slotTime?.includes(":")) slotTime = slotTime.substring(0, 5);
      return slotTime === normalizedTimeForCompare;
    });

    const isAvailable = matchingSlot
      ? (matchingSlot.available === true || matchingSlot.available === "t" || matchingSlot.available === "true")
      : false;

    if (!isAvailable) {
      return NextResponse.json({
        error: "El horario seleccionado no está disponible",
        code: "SLOT_NOT_AVAILABLE",
        details: { date: validatedBody.appointment_date, time: normalizedTime, duration: validatedBody.duration_minutes, rawAvailabilityResult: matchingSlot?.available },
      }, { status: 400 });
    }
  }

  const customerId = validatedBody.customer_id || null;
  let guestData = null;

  // Validate customer belongs to branch
  if (customerId) {
    const { data: customer } = await supabaseServiceRole
      .from("customers").select("branch_id").eq("id", customerId).single();
    if (!customer) return NextResponse.json({ error: "Cliente no encontrado" }, { status: 404 });
    if (customer.branch_id !== finalBranchId) {
      return NextResponse.json({ error: "El cliente no pertenece a esta sucursal. Seleccione un cliente de la sucursal actual." }, { status: 400 });
    }
  }

  // Guest customer data
  if (body?.guest_customer) {
    const guest = body.guest_customer;
    if (!guest.first_name || !guest.last_name || !guest.rut) {
      return NextResponse.json({ error: "Nombre, apellido y RUT son obligatorios para clientes no registrados" }, { status: 400 });
    }
    guestData = {
      guest_first_name: guest.first_name.trim(),
      guest_last_name: guest.last_name.trim(),
      guest_rut: formatRUT(guest.rut),
      guest_email: guest.email?.trim() || null,
      guest_phone: guest.phone?.trim() || null,
    };
  }

  // Field operation inheritance
  let fieldOperationId: string | null = null;
  if (customerId) {
    const { data: cust } = await supabaseServiceRole
      .from("customers").select("field_operation_id").eq("id", customerId).single();
    fieldOperationId = cust?.field_operation_id ?? null;
  }

  // Build appointment data
  const appointmentData: Record<string, unknown> = {
    customer_id: customerId,
    appointment_date: validatedBody.appointment_date,
    appointment_time: normalizedTime,
    duration_minutes: validatedBody.duration_minutes || 30,
    appointment_type: validatedBody.appointment_type,
    status: body?.status || "scheduled",
    assigned_to: body?.assigned_to || null,
    notes: validatedBody.notes || null,
    reason: body?.reason || null,
    prescription_id: body?.prescription_id || null,
    order_id: body?.order_id || null,
    follow_up_required: body?.follow_up_required || false,
    follow_up_date: body?.follow_up_date || null,
    created_by: user.id,
    branch_id: finalBranchId,
    organization_id: branchContext.organizationId,
    field_operation_id: fieldOperationId,
  };

  if (guestData) Object.assign(appointmentData, guestData);

  const { data: appointment, error: appointmentError } = await supabaseServiceRole
    .from("appointments").insert(appointmentData).select("*").single();

  if (appointmentError) {
    logger.error("Error creating appointment", appointmentError);
    return NextResponse.json({ error: "Failed to create appointment", details: appointmentError.message, code: appointmentError.code, hint: appointmentError.hint }, { status: 500 });
  }

  // Fetch customer separately
  let customer = null;
  if (appointment.customer_id) {
    const { data: customerData } = await supabaseServiceRole
      .from("customers").select("id, first_name, last_name, email, phone").eq("id", appointment.customer_id).maybeSingle();
    customer = customerData;
  }

  const appointmentWithCustomer = { ...appointment, customer };

  // Non-blocking notification
  let customerName = "Cliente";
  if (appointmentWithCustomer.customer) {
    customerName = `${appointmentWithCustomer.customer.first_name || ""} ${appointmentWithCustomer.customer.last_name || ""}`.trim() || appointmentWithCustomer.customer.email || "Cliente";
  } else if (appointmentWithCustomer.guest_first_name && appointmentWithCustomer.guest_last_name) {
    customerName = `${appointmentWithCustomer.guest_first_name} ${appointmentWithCustomer.guest_last_name}`.trim();
  }

  NotificationService.notifyNewAppointment(
    appointmentWithCustomer.id, customerName, appointmentWithCustomer.appointment_date,
    appointmentWithCustomer.appointment_time, appointmentWithCustomer.branch_id ?? branchContext.branchId ?? undefined,
  ).catch((err: Error) => logger.error("Error creating notification", err));

  // Non-blocking email
  const customerEmail = appointmentWithCustomer.customer?.email || appointmentWithCustomer.guest_email;
  if (customerEmail) {
    (async () => {
      try {
        const { data: branch } = await supabaseServiceRole.from("branches").select("name").eq("id", appointmentWithCustomer.branch_id).single();
        let professionalName = "Especialista";
        if (appointmentWithCustomer.assigned_to) {
          const { data: staff } = await supabaseServiceRole.from("profiles").select("first_name, last_name").eq("id", appointmentWithCustomer.assigned_to).single();
          if (staff) professionalName = `${staff.first_name} ${staff.last_name}`;
        }
        await sendAppointmentConfirmation({
          customer_name: customerName,
          customer_email: customerEmail,
          date: new Date(appointmentWithCustomer.appointment_date).toLocaleDateString("es-AR", { day: "numeric", month: "long", year: "numeric" }),
          time: appointmentWithCustomer.appointment_time.substring(0, 5),
          professional_name: professionalName,
          type: appointmentWithCustomer.appointment_type,
          branch_name: branch?.name || "",
        }, branchContext.organizationId || undefined);
      } catch (err) {
        logger.error("Error sending appointment email", err);
      }
    })();
  }

  return NextResponse.json({ success: true, appointment: appointmentWithCustomer }, { status: 201 });
}

