import { appLogger as logger } from "@/lib/logger";
import { rateLimitConfigs, withRateLimit } from "@/lib/rate-limiting";
import { getLocalDateBoundsUTC } from "@/lib/utils/date-timezone";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClientFromRequest } from "@/utils/supabase/server";

export async function listOrders(request: NextRequest) {
  const requestId = crypto.randomUUID();
  logger.info("Admin Orders API GET called", { requestId });

  const { client: supabase, getUser } = await createClientFromRequest(request);

  const { data, error: userError } = await getUser();
  const user = (data?.user as { id: string; email?: string } | null) ?? null;
  if (userError || !user) throw new AuthenticationError("Unauthorized");

  const { data: isAdmin } = (await supabase.rpc("is_admin", {
    user_id: user.id,
  } as IsAdminParams)) as { data: IsAdminResult | null };
  if (!isAdmin) throw new AuthorizationError("Admin access required");

  const branchContext = await getBranchContext(request, user.id, supabase as never);
  const fieldOperationId = getFieldOperationFromRequest(request);

  const { data: adminUser } = await supabase
    .from("admin_users")
    .select("organization_id")
    .eq("id", user.id)
    .single();
  const userOrganizationId = (adminUser as { organization_id?: string })?.organization_id;

  const url = new URL(request.url);
  const status = url.searchParams.get("status");
  const paymentStatus = url.searchParams.get("payment_status");
  const dateFrom = url.searchParams.get("date_from");
  const dateTo = url.searchParams.get("date_to");
  const limit = parseInt(url.searchParams.get("limit") || "50");
  const offset = parseInt(url.searchParams.get("offset") || "0");

  let query = supabase
    .from("orders")
    .select(
      `id, order_number, email, customer_name, status, payment_status, total_amount, currency, created_at, updated_at, mp_payment_id, mp_payment_method, mp_payment_type, organization_id, branch_id, order_items ( id, product_name, variant_title, quantity, unit_price, total_price ), order_payments ( id, amount, payment_method, paid_at )`,
      { count: "exact" },
    )
    .order("created_at", { ascending: false })
    .range(offset, offset + limit - 1);

  if (userOrganizationId && !branchContext.isSuperAdmin) {
    query = query.eq("organization_id", userOrganizationId);
    if (branchContext.branchId) {
      query = query.eq("branch_id", branchContext.branchId);
      if (fieldOperationId) {
        query = query.eq("field_operation_id", fieldOperationId);
      } else {
        query = query.is("field_operation_id", null);
      }
    }
  } else if (branchContext.isSuperAdmin) {
    if (branchContext.branchId) {
      query = query.eq("branch_id", branchContext.branchId);
      if (fieldOperationId) {
        query = query.eq("field_operation_id", fieldOperationId);
      } else {
        query = query.is("field_operation_id", null);
      }
    } else if (branchContext.organizationId) {
      query = query.eq("organization_id", branchContext.organizationId);
    }
  }

  if (status && status !== "all") query = query.eq("status", status);
  if (paymentStatus && paymentStatus !== "all") query = query.eq("payment_status", paymentStatus);
  if (dateFrom) {
    const { start } = getLocalDateBoundsUTC(dateFrom);
    query = query.gte("created_at", start);
  }
  if (dateTo) {
    const { end } = getLocalDateBoundsUTC(dateTo);
    query = query.lte("created_at", end);
  }

  const { data: orders, error: ordersError, count } = await query;
  if (ordersError) throw new Error(`Failed to fetch orders: ${ordersError.message}`);

  const transformedOrders = (orders || []).map((order) => ({
    id: order.id,
    order_number: order.order_number,
    customer_name: (order as unknown as Record<string, unknown>).customer_name || "Cliente",
    customer_email: order.email,
    total_amount: order.total_amount,
    status: order.status,
    payment_status: order.payment_status,
    created_at: order.created_at,
    updated_at: order.updated_at,
    mp_payment_id: order.mp_payment_id,
    mp_payment_method: order.mp_payment_method,
    mp_payment_type: order.mp_payment_type,
    order_items: order.order_items || [],
    order_payments: (order as unknown as Record<string, unknown>).order_payments || [],
  }));

  return createPaginatedResponse(
    transformedOrders,
    { page: Math.floor(offset / limit) + 1, limit, total: count || 0 },
    { requestId },
  );
}

async function getOrderStats(
  supabase: unknown,
  userOrganizationId: string | undefined,
  branchContext: Awaited<ReturnType<typeof getBranchContext>>,
) {
  if (!userOrganizationId && !branchContext.isSuperAdmin) {
    return { orderCounts: {}, totalRevenue: 0, recentOrders: [] };
  }

  let baseQuery = supabase.from("orders").select("status");
  if (userOrganizationId && !branchContext.isSuperAdmin) {
    baseQuery = baseQuery.eq("organization_id", userOrganizationId);
    if (branchContext.branchId) baseQuery = baseQuery.eq("branch_id", branchContext.branchId);
  } else if (branchContext.isSuperAdmin && branchContext.branchId) {
    baseQuery = baseQuery.eq("branch_id", branchContext.branchId);
  }

  const { data: allOrders, error: statusError } = await baseQuery;
  if (statusError) throw new Error(`Failed to get order statistics: ${statusError.message}`);

  const statusCounts = (allOrders || []).reduce(
    (acc: Record<string, number>, order: { status: string }) => {
      acc[order.status] = (acc[order.status] || 0) + 1;
      return acc;
    },
    {} as Record<string, number>,
  );

  const startOfMonth = new Date();
  startOfMonth.setDate(1);
  startOfMonth.setHours(0, 0, 0, 0);

  let revenueQuery = supabase.from("orders").select("total_amount");
  if (userOrganizationId && !branchContext.isSuperAdmin) {
    revenueQuery = revenueQuery.eq("organization_id", userOrganizationId);
    if (branchContext.branchId) revenueQuery = revenueQuery.eq("branch_id", branchContext.branchId);
  } else if (branchContext.isSuperAdmin && branchContext.branchId) {
    revenueQuery = revenueQuery.eq("branch_id", branchContext.branchId);
  }

  const { data: revenueData, error: revenueError } = await revenueQuery
    .eq("payment_status", "paid")
    .gte("created_at", startOfMonth.toISOString());
  if (revenueError) throw new Error(`Failed to get revenue statistics: ${revenueError.message}`);

  const totalRevenue = (revenueData || []).reduce(
    (sum: number, order: { total_amount?: number | null }) => sum + (order.total_amount || 0), 0,
  );

  let recentOrdersQuery = supabase
    .from("orders")
    .select("id, order_number, email, status, total_amount, created_at");
  if (userOrganizationId && !branchContext.isSuperAdmin) {
    recentOrdersQuery = recentOrdersQuery.eq("organization_id", userOrganizationId);
    if (branchContext.branchId) recentOrdersQuery = recentOrdersQuery.eq("branch_id", branchContext.branchId);
  } else if (branchContext.isSuperAdmin && branchContext.branchId) {
    recentOrdersQuery = recentOrdersQuery.eq("branch_id", branchContext.branchId);
  }

  const { data: recentOrders, error: recentError } = await recentOrdersQuery
    .order("created_at", { ascending: false })
    .limit(10);
  if (recentError) throw new Error(`Failed to get recent orders: ${recentError.message}`);

  return {
    orderCounts: statusCounts,
    totalRevenue,
    recentOrders: (recentOrders || []).map((order: never) => ({
      id: (order as { id: string }).id,
      order_number: (order as { order_number: string }).order_number,
      customer_name: "Cliente",
      customer_email: (order as { email: string }).email,
      status: (order as { status: string }).status,
      total_amount: (order as { total_amount?: number }).total_amount,
      created_at: (order as { created_at: string }).created_at,
    })),
  };
}

async function createManualOrder(
  supabase: unknown,
  user: { id: string },
  body: { orderData?: Record<string, unknown> },
): Promise<{ success: boolean; order: unknown }> {
  const { orderData } = body;
  if (!orderData) throw new Error("Order data is required");
  if (!orderData.email) throw new Error("Email is required");
  if (!orderData.total_amount || Number(orderData.total_amount) <= 0) {
    throw new Error("Total amount must be greater than 0");
  }

  const orderNumber = `DL-${Date.now()}`;
  let dbStatus = (orderData.status as string) || "pending";
  if (dbStatus === "completed") dbStatus = "delivered";

  const { data: newOrder, error: orderError } = await (supabase as unknown)
    .from("orders")
    .insert({
      order_number: orderNumber,
      email: orderData.email as string,
      status: dbStatus,
      payment_status: (orderData.payment_status as string) || "paid",
      subtotal: (orderData.subtotal as number) || (orderData.total_amount as number),
      total_amount: orderData.total_amount as number,
      currency: "ARS",
      mp_payment_method: (orderData.payment_method as string) || "manual",
      customer_notes: (orderData.notes as string) || null,
      shipping_first_name: (orderData.shipping as Record<string, unknown>)?.first_name as string,
      shipping_last_name: (orderData.shipping as Record<string, unknown>)?.last_name as string,
      shipping_address_1: (orderData.shipping as Record<string, unknown>)?.address_1 as string,
      shipping_city: (orderData.shipping as Record<string, unknown>)?.city as string,
      shipping_state: (orderData.shipping as Record<string, unknown>)?.state as string,
      shipping_postal_code: (orderData.shipping as Record<string, unknown>)?.postal_code as string,
      shipping_phone: (orderData.shipping as Record<string, unknown>)?.phone as string,
    })
    .select()
    .single();

  if (orderError) throw new Error(`Failed to create order: ${orderError.message}`);

  if ((orderData.items as Array<unknown>)?.length > 0) {
    const orderItems = (orderData.items as Array<Record<string, unknown>>).map((item) => ({
      order_id: newOrder.id,
      product_id: item.product_id as string,
      quantity: item.quantity as number,
      unit_price: item.unit_price as number,
      total_price: (item.unit_price as number) * (item.quantity as number),
      product_name: item.product_name as string,
      variant_title: (item.variant_title as string) || null,
    }));

    const { error: itemsError } = await supabase.from("order_items").insert(orderItems);
    if (itemsError) logger.error("Error creating order items", itemsError);
  }

  // Non-blocking notification
  const { NotificationService } = await import("@/lib/notifications/notification-service");
  NotificationService.notifyNewSale(
    (newOrder as unknown as Record<string, unknown>).id as string,
    newOrder.order_number,
    newOrder.email,
    newOrder.total_amount,
    (newOrder as unknown as Record<string, unknown>).branch_id as string ?? undefined,
  ).catch((err) => logger.error("Error creating notification", err));

  // Non-blocking email
  if (newOrder.email) {
    (async () => {
      try {
        const no = newOrder as unknown as Record<string, unknown>;
        await sendOrderConfirmation({
          ...no,
          user_email: newOrder.email,
          email: newOrder.email,
          currency: (no.currency as string) || (orderData.currency as string) || "CLP",
          customer_name: (no.customer_name as string) || ((orderData.shipping as Record<string, unknown>)?.first_name
            ? `${(orderData.shipping as Record<string, unknown>).first_name} ${(orderData.shipping as Record<string, unknown>).last_name}`.trim()
            : "Cliente"),
          items: ((orderData.items as Array<Record<string, unknown>>) || []).map((item) => ({
            id: item.product_id,
            name: item.product_name,
            quantity: item.quantity,
            price: item.unit_price,
            variant_title: item.variant_title,
          })),
          payment_method: (no.mp_payment_method as string) || (orderData.payment_method as string) || "manual",
          organization_id: no.organization_id,
        } as never);
      } catch (err) {
        logger.error("Error sending order confirmation email", err);
      }
    })();
  }

  return { success: true, order: newOrder };
}

export async function handleOrderPost(request: NextRequest): Promise<NextResponse> {
  return (withRateLimit(rateLimitConfigs.modification) as unknown)(
    request,
    async () => {
  const { client: supabaseRaw, getUser } = await createClientFromRequest(request);
  const supabase = supabaseRaw as unknown;

      const authResult2 = await getUser() as unknown;
      const user2 = authResult2?.data?.user ?? null;
      if (!user2) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

      const { data: isAdmin } = await supabase.rpc("is_admin", { user_id: user2.id });
      if (!isAdmin) return NextResponse.json({ error: "Admin access required" }, { status: 403 });

      let branchContext;
      try {
        branchContext = await getBranchContext(request, user2.id, supabase);
      } catch (branchError: unknown) {
        logger.error("Error getting branch context", branchError);
        return NextResponse.json(
          { error: "Failed to get branch context", details: (branchError as Error)?.message || "Unknown error" },
          { status: 500 },
        );
      }

      const { data: adminUser } = await supabase
        .from("admin_users")
        .select("organization_id")
        .eq("id", user2.id)
        .single();
      const userOrganizationId = (adminUser as { organization_id?: string })?.organization_id;

      let body: Record<string, unknown>;
      try {
        body = await request.json();
      } catch {
        return NextResponse.json({ error: "Invalid request body" }, { status: 400 });
      }

      if (!body.action) return NextResponse.json({ error: "Action is required" }, { status: 400 });

      if (body.action === "get_stats") {
        const stats = await getOrderStats(supabase, userOrganizationId, branchContext);
        return NextResponse.json({ success: true, stats });
      }

      if (body.action === "create_manual_order") {
        const result = await createManualOrder(supabase, user2, body);
        return NextResponse.json(result);
      }

      return NextResponse.json({ error: "Invalid action" }, { status: 400 });
    },
  );
}

export async function deleteAllOrders(request: NextRequest): Promise<NextResponse> {
  const requestId = crypto.randomUUID();
  logger.warn("Admin Orders API DELETE called - Deleting all orders");

  const { client: supabaseRaw, getUser } = await createClientFromRequest(request);
  const supabase = supabaseRaw as unknown;

  const authResult3 = await getUser() as unknown;
  const user3 = authResult3?.data?.user ?? null;
  if (!user3) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const { data: isAdmin } = (await supabase.rpc("is_admin", {
    user_id: user3.id,
  } as IsAdminParams)) as { data: IsAdminResult | null };
  if (!isAdmin) return NextResponse.json({ error: "Admin access required" }, { status: 403 });

  const { error: itemsError } = await supabase
    .from("order_items")
    .delete()
    .neq("id", "00000000-0000-0000-0000-000000000000");
  if (itemsError) return NextResponse.json({ error: "Failed to delete order items", details: itemsError.message }, { status: 500 });

  const { error: ordersError } = await supabase
    .from("orders")
    .delete()
    .neq("id", "00000000-0000-0000-0000-000000000000");
  if (ordersError) return NextResponse.json({ error: "Failed to delete orders", details: ordersError.message }, { status: 500 });

  return NextResponse.json({ success: true, message: "All orders have been deleted successfully" });
}

/**
 * Admin Product Service
 * Server-side business logic for product operations by ID
 */
import { NextRequest, NextResponse } from "next/server";

import { getBranchContext } from "@/lib/api/branch-middleware";
import { DEFAULT_LOW_STOCK_THRESHOLD, getProductStock, updateProductStock } from "@/lib/inventory/stock-helpers";
import { createClientFromRequest, createServiceRoleClient } from "@/utils/supabase/server";

function generateSlug(name: string): string {
  const slug = name.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
  return slug || `product-${Date.now()}`;
}

function buildProductData(body: unknown, slug: string): Record<string, unknown> {
  return {
    name: body.name.trim(),
    slug,
    description: body.description || null,
    short_description: body.short_description || null,
    price: parseFloat(body.price),
    price_includes_tax: body.price_includes_tax === true || body.price_includes_tax === "true",
    compare_at_price: body.compare_at_price ? parseFloat(body.compare_at_price) : null,
    cost_price: body.cost_price ? parseFloat(body.cost_price) : null,
    category_id: body.category_id || null,
    status: body.status || "draft",
    featured_image: body.featured_image || null,
    gallery: body.gallery || [],
    tags: body.tags || [],
    product_type: body.product_type || "frame",
    optical_category: body.optical_category || null,
    sku: body.sku || null,
    barcode: body.barcode || null,
    brand: body.brand || null,
    manufacturer: body.manufacturer || null,
    model_number: body.model_number || null,
    frame_type: body.frame_type || null,
    frame_material: body.frame_material || null,
    frame_shape: body.frame_shape || null,
    frame_color: body.frame_color || null,
    frame_colors: body.frame_colors || [],
    frame_brand: body.frame_brand || null,
    frame_model: body.frame_model || null,
    frame_sku: body.frame_sku || null,
    frame_gender: body.frame_gender || null,
    frame_age_group: body.frame_age_group || null,
    frame_size: body.frame_size || null,
    frame_features: body.frame_features || [],
    frame_measurements: body.frame_measurements || null,
    lens_type: body.lens_type || null,
    lens_material: body.lens_material || null,
    lens_index: body.lens_index ? parseFloat(body.lens_index) : null,
    lens_coatings: body.lens_coatings || [],
    lens_tint_options: body.lens_tint_options || [],
    uv_protection: body.uv_protection || null,
    blue_light_filter: body.blue_light_filter || false,
    blue_light_filter_percentage: body.blue_light_filter_percentage ? parseInt(body.blue_light_filter_percentage) : null,
    photochromic: body.photochromic || false,
    prescription_available: body.prescription_available || false,
    prescription_range: body.prescription_range || null,
    requires_prescription: body.requires_prescription || false,
    is_customizable: body.is_customizable || false,
    warranty_months: body.warranty_months ? parseInt(body.warranty_months) : null,
    warranty_details: body.warranty_details || null,
    is_featured: body.is_featured || false,
    updated_at: new Date().toISOString(),
    weight: body.weight !== undefined && body.weight !== null && body.weight !== "" ? parseFloat(body.weight) || undefined : undefined,
    dimensions: body.dimensions !== undefined && body.dimensions !== null && typeof body.dimensions === "object" ? body.dimensions : undefined,
    package_characteristics: body.package_characteristics || undefined,
    usage_instructions: body.usage_instructions || undefined,
    precautions: body.precautions || undefined,
    certifications: body.certifications || undefined,
    published_at: body.published_at !== undefined ? body.published_at : undefined,
  };
}

export async function getProduct(request: NextRequest, id: string) {
  const { client: supabase, getUser } = await createClientFromRequest(request);
  const authResult = await getUser() as unknown;
  const user = authResult?.data?.user ?? null;
  if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const adminUserRes = await supabase.from("admin_users").select("organization_id").eq("id", user.id).single() as unknown;
  const userOrganizationId = adminUserRes.data?.organization_id;
  const branchContext = await getBranchContext(request, user.id, supabase as unknown);
  const includeArchived = new URL(request.url).searchParams.get("include_archived") === "true";
  const currentBranchId = branchContext?.branchId;

  let query = supabase
    .from("products")
    .select(currentBranchId ? `*, product_branch_stock ( quantity, reserved_quantity, low_stock_threshold, branch_id )` : "*")
    .eq("id", id);

  if (userOrganizationId && !branchContext.isSuperAdmin) query = query.eq("organization_id", userOrganizationId);
  if (!includeArchived) query = query.neq("status", "archived");

  const { data: product, error } = await query.single();
  if (error || !product) {
    const status = error?.code === "PGRST116" ? 404 : 404;
    return NextResponse.json({ error: "Product not found" }, { status });
  }

  // Multi-tenancy safety check
  const p = product as unknown;
  if (userOrganizationId && !branchContext.isSuperAdmin && p.organization_id !== userOrganizationId) {
    return NextResponse.json({ error: "Forbidden: You don't have access to this product" }, { status: 403 });
  }

  // Filter stock by branch
  if (currentBranchId && p.product_branch_stock) {
    if (Array.isArray(p.product_branch_stock)) {
      const filteredStock = p.product_branch_stock.filter((s: unknown) => s?.branch_id === currentBranchId);
      p.product_branch_stock = filteredStock.length > 0 ? filteredStock : null;
    } else if (p.product_branch_stock.branch_id !== currentBranchId) {
      p.product_branch_stock = null;
    }
  }

  // Fetch default stock if missing
  if (currentBranchId && !p.product_branch_stock) {
    const stock = await getProductStock(id, currentBranchId, supabase);
    p.product_branch_stock = stock
      ? [stock]
      : [{ quantity: 0, reserved_quantity: 0, low_stock_threshold: DEFAULT_LOW_STOCK_THRESHOLD, branch_id: currentBranchId }];
  }

  return NextResponse.json({ product: p });
}

export async function updateProduct(request: NextRequest, id: string) {
  const { client: supabase, getUser } = await createClientFromRequest(request);
  const { data, error: userError } = await getUser();
  const user = data?.user as { id: string } | null;
  if (userError || !user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const { data: isAdmin } = await supabase.rpc("is_admin", { user_id: user.id } as unknown);
  if (!isAdmin) return NextResponse.json({ error: "Admin access required" }, { status: 403 });

  const adminUserRes = await supabase.from("admin_users").select("organization_id").eq("id", user.id).single() as unknown;
  const userOrganizationId = adminUserRes.data?.organization_id;
  const body = await request.json();

  // Validation
  if (!body.name?.trim()) return NextResponse.json({ error: "Product name is required" }, { status: 400 });
  if (body.price === undefined || body.price === null || isNaN(parseFloat(body.price))) {
    return NextResponse.json({ error: "Valid price is required" }, { status: 400 });
  }

  // Stock requires branch
  if (body.stock_quantity !== undefined || body.low_stock_threshold !== undefined) {
    const branchContext = await getBranchContext(request, user.id);
    const branchId = branchContext.branchId || body.branch_id;
    if (!branchId) {
      return NextResponse.json({ error: "No se puede modificar el stock en vista global. Selecciona una sucursal para actualizar el inventario de esa sucursal.", code: "STOCK_REQUIRES_BRANCH" }, { status: 400 });
    }
  }

  // Generate slug
  let slug = body.slug?.trim();
  if (!slug) slug = generateSlug(body.name);
  const { data: existing } = await supabase.from("products").select("id").eq("slug", slug).neq("id", id).limit(1);
  if (existing && existing.length > 0) slug = `${slug}-${Date.now()}`;

  const productData = buildProductData(body, slug);

  // Verify access
  let checkQuery: unknown = supabase.from("products").select("id, organization_id").eq("id", id).single();
  if (userOrganizationId) {
    const { data: isSuperAdmin } = await supabase.rpc("is_super_admin", { user_id: user.id }) as unknown;
    if (!isSuperAdmin) checkQuery = checkQuery.eq("organization_id", userOrganizationId);
  }
  const { data: existingProduct, error: checkError } = await checkQuery as unknown;
  if (checkError || !existingProduct) {
    return NextResponse.json({ error: checkError?.code === "PGRST116" ? "Product not found" : "Forbidden: You don't have access to this product" }, { status: checkError?.code === "PGRST116" ? 404 : 403 });
  }

  // Update
  let updateQuery = supabase.from("products").update(productData).eq("id", id);
  if (userOrganizationId) {
    const { data: isSuperAdmin } = await supabase.rpc("is_super_admin", { user_id: user.id }) as unknown;
    if (!isSuperAdmin) updateQuery = updateQuery.eq("organization_id", userOrganizationId);
  }
  let { data: updatedProduct, error } = await updateQuery.select().single() as unknown;

  if (error && error.code === "42501") {
    const serviceSupabase = createServiceRoleClient();
    let serviceQuery = serviceSupabase.from("products").update(productData).eq("id", id);
    if (userOrganizationId) {
      const { data: isSuperAdmin } = await supabase.rpc("is_super_admin", { user_id: user.id }) as unknown;
      if (!isSuperAdmin) serviceQuery = serviceQuery.eq("organization_id", userOrganizationId);
    }
    const serviceResult = await serviceQuery.select().single() as unknown;
    updatedProduct = serviceResult.data;
    error = serviceResult.error;
  }
  if (error) return NextResponse.json({ error: error.message || "Failed to update product" }, { status: 500 });

  // Handle stock update
  if ((body.stock_quantity !== undefined || body.low_stock_threshold !== undefined) && updatedProduct) {
    const branchContext = await getBranchContext(request, user.id);
    const branchId = branchContext.branchId || body.branch_id;
    if (!branchId) {
      return NextResponse.json({ error: "No se puede modificar el stock en vista global.", code: "STOCK_REQUIRES_BRANCH" }, { status: 400 });
    }
    const serviceSupabase = createServiceRoleClient();

    if (body.stock_quantity !== undefined) {
      const stockQty = parseInt(String(body.stock_quantity)) || 0;
      const currentStock = await getProductStock(id, branchId, serviceSupabase);
      const qtyChange = stockQty - (currentStock?.quantity || 0);
      if (qtyChange !== 0) {
        const stockResult = await updateProductStock(id, branchId, qtyChange, false, serviceSupabase);
        if (!stockResult.success) {
          return NextResponse.json({ product: updatedProduct, warning: "El producto se actualizó, pero hubo un error al actualizar el stock" });
        }
      }
    }

    if (body.low_stock_threshold !== undefined) {
      const threshold = parseInt(String(body.low_stock_threshold)) || 5;
      const currentStock = await getProductStock(id, branchId, serviceSupabase);
      if (currentStock) {
        await serviceSupabase.from("product_branch_stock").update({ low_stock_threshold: threshold }).eq("product_id", id).eq("branch_id", branchId);
      } else {
        await serviceSupabase.from("product_branch_stock").insert({ product_id: id, branch_id: branchId, quantity: 0, reserved_quantity: 0, low_stock_threshold: threshold });
      }
    }
  }

  return NextResponse.json({ product: updatedProduct });
}

export async function deleteProduct(request: NextRequest, id: string) {
  const { client: supabase, getUser } = await createClientFromRequest(request);
  const { data, error: userError } = await getUser();
  const user = data?.user as { id: string } | null;
  if (userError || !user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const { data: isAdmin } = await supabase.rpc("is_admin", { user_id: user.id } as unknown);
  if (!isAdmin) return NextResponse.json({ error: "Admin access required" }, { status: 403 });

  const adminUserRes = await supabase.from("admin_users").select("organization_id").eq("id", user.id).single() as unknown;
  const userOrganizationId = adminUserRes.data?.organization_id;

  let deleteQuery = supabase.from("products").delete().eq("id", id);
  if (userOrganizationId) {
    const { data: isSuperAdmin } = await supabase.rpc("is_super_admin", { user_id: user.id }) as unknown;
    if (!isSuperAdmin) deleteQuery = deleteQuery.eq("organization_id", userOrganizationId);
  }
  let { error } = await deleteQuery as unknown;

  if (error && error.code === "42501") {
    const serviceSupabase = createServiceRoleClient();
    ({ error } = await serviceSupabase.from("products").delete().eq("id", id) as unknown);
  }
  if (error) return NextResponse.json({ error: error.message || "Failed to delete product" }, { status: 500 });

  return NextResponse.json({ success: true });
}

/**
 * Admin Quote Service
 * Server-side business logic for quote operations
 */
import { NextRequest, NextResponse } from "next/server";

import { addBranchFilter, getBranchContext } from "@/lib/api/branch-middleware";
import { AuthenticationError, AuthorizationError } from "@/lib/api/errors";
import { createApiErrorResponse, createApiSuccessResponse } from "@/lib/api/response";
import { sendQuoteSent } from "@/lib/email/notifications";
import { appLogger as logger } from "@/lib/logger";
import type { IsAdminParams, IsAdminResult } from "@/types/supabase-rpc";
import { createClient, createServiceRoleClient } from "@/utils/supabase/server";

async function getAdminAuth(supabase: unknown) {
  const { data: { user }, error: userError } = await supabase.auth.getUser();
  if (userError || !user) throw new AuthenticationError("No autorizado");
  const { data: isAdmin } = (await supabase.rpc("is_admin", { user_id: user.id } as IsAdminParams)) as { data: IsAdminResult | null };
  if (!isAdmin) throw new AuthorizationError("Acceso denegado");
  return user;
}

export async function getQuote(request: NextRequest, id: string) {
  const supabase = await createClient();
  const user = await getAdminAuth(supabase);

  const adminUser = await supabase.from("admin_users").select("organization_id").eq("id", user.id).single() as unknown;
  const userOrganizationId = adminUser?.data?.organization_id ?? null;
  const branchContext = await getBranchContext(request, user.id);
  const supabaseServiceRole = createServiceRoleClient();

  // Expire quotes
  await supabaseServiceRole.rpc("check_and_expire_quotes");

  // Check exists
  const { data: quoteCheck, error: checkError } = await supabaseServiceRole
    .from("quotes").select("id, branch_id, organization_id, quote_number").eq("id", id).single() as unknown;
  if (checkError || !quoteCheck) {
    return NextResponse.json({ error: "Quote not found", details: checkError?.message || "Quote does not exist" }, { status: 404 });
  }

  // Access: allow if same org
  const quoteOrgId = quoteCheck.organization_id ?? null;
  if (quoteOrgId !== null && userOrganizationId !== null && quoteOrgId !== userOrganizationId) {
    return NextResponse.json({ error: "Access denied to this quote" }, { status: 403 });
  }

  // Fetch full quote
  const { data: quoteData, error: quoteError } = await supabaseServiceRole
    .from("quotes").select("*").eq("id", id).single() as unknown;
  if (quoteError || !quoteData) {
    return createApiErrorResponse(new Error(quoteError?.message || "Failed to fetch quote"));
  }

  // Fetch relations
  const relations: Record<string, unknown> = {};
  if (quoteData.customer_id) {
    const { data: customerData } = await supabaseServiceRole
      .from("customers").select("id, first_name, last_name, email, phone, rut").eq("id", quoteData.customer_id) as unknown;
    relations.customer = (customerData && customerData.length > 0) ? customerData[0] : null;
  } else {
    relations.customer = null;
  }
  if (quoteData.prescription_id) {
    const { data: prescription } = await supabaseServiceRole.from("prescriptions").select("*").eq("id", quoteData.prescription_id).single() as unknown;
    relations.prescription = prescription || null;
  }
  if (quoteData.frame_product_id) {
    const { data: frameProduct } = await supabaseServiceRole.from("products").select("id, name, price, frame_brand, frame_model").eq("id", quoteData.frame_product_id).single() as unknown;
    relations.frame_product = frameProduct || null;
  }
  if (quoteData.far_lens_family_id) {
    const { data: farLensFamily } = await supabaseServiceRole.from("lens_families").select("id, name").eq("id", quoteData.far_lens_family_id).single() as unknown;
    relations.far_lens_family = farLensFamily || null;
  }
  if (quoteData.near_lens_family_id) {
    const { data: nearLensFamily } = await supabaseServiceRole.from("lens_families").select("id, name").eq("id", quoteData.near_lens_family_id).single() as unknown;
    relations.near_lens_family = nearLensFamily || null;
  }
  if (quoteData.lens_family_id) {
    const { data: lensFamily } = await supabaseServiceRole.from("lens_families").select("id, name").eq("id", quoteData.lens_family_id).single() as unknown;
    relations.lens_family = lensFamily || null;
  }

  const quote = {
    ...quoteData,
    customer: relations.customer || null,
    prescription: relations.prescription || null,
    frame_product: relations.frame_product || null,
    far_lens_family: relations.far_lens_family || null,
    near_lens_family: relations.near_lens_family || null,
    lens_family: relations.lens_family || null,
  };

  return createApiSuccessResponse(quote);
}

export async function updateQuote(request: NextRequest, id: string) {
  const supabase = await createClient();
  const supabaseServiceRole = createServiceRoleClient();
  const user = await getAdminAuth(supabase);
  const branchContext = await getBranchContext(request, user.id);

  // Verify access
  const applyBranchFilter = (query: unknown) => addBranchFilter(query, branchContext.branchId, branchContext.isSuperAdmin, branchContext.organizationId);
  const { data: existingQuote, error: fetchError } = await applyBranchFilter(
    supabase.from("quotes").select("id, branch_id, customer_id") as unknown,
  ).eq("id", id).single() as unknown;

  if (fetchError || !existingQuote) {
    return NextResponse.json({ error: "Presupuesto no encontrado o sin acceso" }, { status: 404 });
  }

  const body = await request.json();

  // Validate prescription belongs to customer
  const prescriptionId = body.prescription_id || null;
  if (prescriptionId) {
    const { data: prescription } = await supabaseServiceRole.from("prescriptions").select("customer_id").eq("id", prescriptionId).single() as unknown;
    if (prescription && existingQuote.customer_id && prescription.customer_id !== existingQuote.customer_id) {
      return NextResponse.json({ error: "La receta no pertenece al cliente del presupuesto" }, { status: 400 });
    }
  }

  // Build update data
  const updateData: Record<string, unknown> = { updated_at: new Date().toISOString() };
  const fields = [
    "frame_name", "frame_brand", "frame_model", "frame_color", "frame_size", "frame_sku",
    "frame_price", "lens_type", "lens_material", "lens_index", "lens_treatments", "lens_tint_color",
    "lens_tint_percentage", "frame_cost", "lens_cost", "treatments_cost", "labor_cost",
    "subtotal", "tax_amount", "discount_amount", "discount_percentage", "total_amount",
    "status", "notes", "customer_notes", "expiration_date",
    "prescription_id", "frame_product_id", "customer_own_frame",
    "lens_family_id",
    "presbyopia_solution", "far_lens_family_id", "near_lens_family_id", "far_lens_cost", "near_lens_cost",
    "near_frame_product_id", "near_frame_name", "near_frame_brand", "near_frame_model",
    "near_frame_color", "near_frame_size", "near_frame_sku", "near_frame_price",
    "near_frame_price_includes_tax", "near_frame_cost", "customer_own_near_frame",
    "contact_lens_family_id",
    "contact_lens_rx_sphere_od", "contact_lens_rx_cylinder_od", "contact_lens_rx_axis_od",
    "contact_lens_rx_add_od", "contact_lens_rx_base_curve_od", "contact_lens_rx_diameter_od",
    "contact_lens_rx_sphere_os", "contact_lens_rx_cylinder_os", "contact_lens_rx_axis_os",
    "contact_lens_rx_add_os", "contact_lens_rx_base_curve_os", "contact_lens_rx_diameter_os",
    "contact_lens_quantity", "contact_lens_cost", "contact_lens_price",
  ];
  for (const field of fields) {
    if (body[field] !== undefined) updateData[field] = body[field];
  }

  const { data: updatedQuote, error } = await supabaseServiceRole
    .from("quotes").update(updateData).eq("id", id)
    .select(`*, customer:customers!quotes_customer_id_fkey(id, first_name, last_name, email, phone), prescription:prescriptions!quotes_prescription_id_fkey(*)`)
    .single() as unknown;

  if (error) {
    logger.error("Error updating quote", error);
    return NextResponse.json({ error: "Failed to update quote" }, { status: 500 });
  }

  // Send email if status changed to 'sent'
  if (body.status === "sent" && updatedQuote.status === "sent" && (updatedQuote.customer?.email || updatedQuote.guest_email)) {
    (async () => {
      try {
        const { data: branch } = await supabaseServiceRole.from("branches").select("name").eq("id", updatedQuote.branch_id).single() as unknown;
        await sendQuoteSent({
          customer_name: `${updatedQuote.customer?.first_name || ""} ${updatedQuote.customer?.last_name || ""}`.trim() || "Cliente",
          customer_email: updatedQuote.customer?.email || updatedQuote.guest_email,
          quote_number: updatedQuote.quote_number,
          total_amount: updatedQuote.total_amount,
          expiration_date: updatedQuote.expiration_date,
          branch_name: branch?.name || "",
          items: [],
        }, branchContext.organizationId ?? undefined);
      } catch (err) {
        logger.error("Error sending quote email on update", err);
      }
    })();
  }

  return createApiSuccessResponse(updatedQuote);
}

export async function deleteQuote(request: NextRequest, id: string) {
  const supabase = await createClient();
  const supabaseServiceRole = createServiceRoleClient();
  await getAdminAuth(supabase);

  const { data: quote, error: fetchError } = await supabaseServiceRole
    .from("quotes").select("id, status, converted_to_work_order_id").eq("id", id).single() as unknown;
  if (fetchError || !quote) return NextResponse.json({ error: "Quote not found" }, { status: 404 });

  if (quote.status === "converted_to_work" || quote.converted_to_work_order_id) {
    return NextResponse.json({ error: "No se puede eliminar un presupuesto que ha sido convertido a trabajo" }, { status: 400 });
  }

  const { error: deleteError } = await supabaseServiceRole.from("quotes").delete().eq("id", id) as unknown;
  if (deleteError) {
    logger.error("Error deleting quote", deleteError);
    return NextResponse.json({ error: "Failed to delete quote" }, { status: 500 });
  }

  return NextResponse.json({ success: true, message: "Presupuesto eliminado exitosamente" });
}

export async function listQuotes(request: NextRequest) {
  const requestId = crypto.randomUUID();
  logger.info("Quotes API GET called", { requestId });
  const supabase = await createClient();
  const user = await getAdminAuth(supabase);
  const supabaseServiceRole = createServiceRoleClient();

  const searchParams = request.nextUrl.searchParams;
  const status = searchParams.get("status") || "all";
  const customerId = searchParams.get("customer_id");
  const customerRut = searchParams.get("customer_rut")?.trim() || null;
  const customerEmail = searchParams.get("customer_email")?.trim() || null;
  const page = parseInt(searchParams.get("page") || "1");
  const limit = parseInt(searchParams.get("limit") || "20");
  const fieldOperationId = searchParams.get("field_operation_id") || null;

  const branchContext = await getBranchContext(request, user.id);
  let effectiveBranchId = branchContext.branchId;
  if (fieldOperationId) {
    const { data: fieldOp } = await supabaseServiceRole.from("field_operations").select("id, branch_id").eq("id", fieldOperationId).single() as unknown;
    if (fieldOp) effectiveBranchId = fieldOp.branch_id;
  }

  const { data: adminUser } = await supabase.from("admin_users").select("organization_id").eq("id", user.id).single() as unknown;
  const userOrganizationId = adminUser?.organization_id;
  const forCustomerQuotesOnly = Boolean(customerId || customerRut || customerEmail);

  // Build branch filter
  const applyBranchFilter = (query: unknown) => {
    if (userOrganizationId && !branchContext.isSuperAdmin) {
      if (forCustomerQuotesOnly) {
        query = query.or(`organization_id.eq.${userOrganizationId},organization_id.is.null`);
      } else {
        query = query.eq("organization_id", userOrganizationId);
      }
      if (!forCustomerQuotesOnly && effectiveBranchId) query = query.eq("branch_id", effectiveBranchId);
      if (fieldOperationId) query = query.eq("field_operation_id", fieldOperationId);
    } else if (branchContext.isSuperAdmin) {
      if (!forCustomerQuotesOnly && effectiveBranchId) query = query.eq("branch_id", effectiveBranchId);
      if (fieldOperationId) query = query.eq("field_operation_id", fieldOperationId);
      else if (branchContext.organizationId) {
        if (forCustomerQuotesOnly) query = query.or(`organization_id.eq.${branchContext.organizationId},organization_id.is.null`);
        else query = query.eq("organization_id", branchContext.organizationId);
      }
    } else {
      query = addBranchFilter(query, forCustomerQuotesOnly ? null : effectiveBranchId, branchContext.isSuperAdmin, branchContext.organizationId);
      if (fieldOperationId) query = query.eq("field_operation_id", fieldOperationId);
    }
    return query;
  };

  // Expire quotes
  await supabaseServiceRole.rpc("check_and_expire_quotes");

  let query = applyBranchFilter(supabase.from("quotes").select("*", { count: "exact" })).order("created_at", { ascending: false });
  if (status !== "all") query = query.eq("status", status);

  // Customer filter
  if (customerId || customerRut || customerEmail) {
    if (userOrganizationId && (customerRut || customerEmail)) {
      const normalizedRut = customerRut ? customerRut.toLowerCase().replace(/[^0-9k]/g, "") : "";
      const normalizedEmail = customerEmail?.toLowerCase() || "";
      const { data: customersInOrg } = await supabaseServiceRole.from("customers").select("id, rut, email").eq("organization_id", userOrganizationId).limit(1000) as unknown;
      const matchingIds = (customersInOrg || []).filter((c: unknown) => {
        const rutMatches = normalizedRut && c.rut && c.rut.toLowerCase().replace(/[^0-9k]/g, "") === normalizedRut;
        const emailMatches = normalizedEmail && c.email && c.email.toLowerCase() === normalizedEmail;
        return rutMatches || emailMatches;
      }).map((c: unknown) => c.id);
      if (matchingIds.length > 0) query = query.in("customer_id", matchingIds);
      else if (customerId) query = query.eq("customer_id", customerId);
      else query = query.eq("customer_id", "00000000-0000-0000-0000-000000000000");
    } else if (customerId) {
      query = query.eq("customer_id", customerId);
    }
  }

  const from = (page - 1) * limit;
  const { data: quotes, error, count } = await query.range(from, from + limit - 1) as unknown;
  if (error) throw new Error(`Failed to fetch quotes: ${error.message}`);

  // Fetch related data
  let quotesWithRelations = quotes || [];
  if (quotesWithRelations.length > 0) {
    const customerIds = [...new Set(quotesWithRelations.map((q: unknown) => q.customer_id).filter(Boolean))];
    const prescriptionIds = [...new Set(quotesWithRelations.map((q: unknown) => q.prescription_id).filter(Boolean))];
    const productIds = [...new Set(quotesWithRelations.map((q: unknown) => q.frame_product_id).filter(Boolean))];

    const [{ data: customers }, { data: prescriptions }, { data: products }] = await Promise.all([
      customerIds.length > 0 ? supabase.from("customers").select("id, first_name, last_name, email, phone, rut").in("id", customerIds) : Promise.resolve({ data: [] }),
      prescriptionIds.length > 0 ? supabase.from("prescriptions").select("*").in("id", prescriptionIds) : Promise.resolve({ data: [] }),
      productIds.length > 0 ? supabase.from("products").select("id, name, price, frame_brand, frame_model").in("id", productIds) : Promise.resolve({ data: [] }),
    ]) as unknown;

    quotesWithRelations = quotesWithRelations.map((quote: unknown) => ({
      ...quote,
      customer: customers?.find((c: unknown) => c.id === quote.customer_id) || null,
      prescription: prescriptions?.find((p: unknown) => p.id === quote.prescription_id) || null,
      frame_product: products?.find((p: unknown) => p.id === quote.frame_product_id) || null,
      original_status: quote.original_status || (quote.status === "converted_to_work" ? "accepted" : quote.status),
    }));
  }

  return {
    quotes: quotesWithRelations,
    pagination: { page, limit, total: count || 0 },
    requestId,
  };
}

export async function createQuote(request: NextRequest) {
  const supabase = await createClient();
  const supabaseServiceRole = createServiceRoleClient();
  const user = await getAdminAuth(supabase);

  const { parseAndValidateBody, validationErrorResponse } = await import("@/lib/api/validation/zod-helpers");
  const { createQuoteSchema } = await import("@/lib/api/validation/zod-schemas");
  const { normalizeRUT } = await import("@/lib/utils/rut");
  const { NotificationService } = await import("@/lib/notifications/notification-service");

  let validatedBody: unknown;
  try {
    validatedBody = await parseAndValidateBody(request, createQuoteSchema);
  } catch (error: unknown) {
    const { ValidationError } = await import("@/lib/api/errors");
    if (error instanceof ValidationError) return (await import("@/lib/api/validation/zod-helpers")).validationErrorResponse(error);
    throw error;
  }

  // Validate prescription belongs to customer
  if (validatedBody.prescription_id) {
    const { data: prescription } = await supabaseServiceRole.from("prescriptions").select("customer_id").eq("id", validatedBody.prescription_id).single() as unknown;
    if (prescription && prescription.customer_id !== validatedBody.customer_id) {
      return NextResponse.json({ error: "La receta no pertenece al cliente seleccionado" }, { status: 400 });
    }
  }

  // Generate quote number
  const { data: quoteNumber, error: quoteNumberError } = await supabaseServiceRole.rpc("generate_quote_number") as unknown;
  if (quoteNumberError || !quoteNumber) return NextResponse.json({ error: "Failed to generate quote number" }, { status: 500 });

  // Get default expiration
  const { data: settings } = await supabaseServiceRole.from("quote_settings").select("default_expiration_days").limit(1).single() as unknown;
  const defaultExpirationDays = settings?.default_expiration_days || 30;
  const branchContext = await getBranchContext(request, user.id);

  // Determine branch
  let quoteBranchId = validatedBody.branch_id || branchContext.branchId;
  if (!quoteBranchId && validatedBody.customer_id) {
    const { data: customer } = await supabaseServiceRole.from("customers").select("branch_id").eq("id", validatedBody.customer_id).single() as unknown;
    quoteBranchId = customer?.branch_id || null;
  }

  if (!branchContext.isSuperAdmin && quoteBranchId) {
    const hasAccess = branchContext.accessibleBranches.some((b: unknown) => b.id === quoteBranchId);
    if (!hasAccess) return NextResponse.json({ error: "No tiene acceso a esta sucursal" }, { status: 403 });
  }
  if (!branchContext.isSuperAdmin && !quoteBranchId) return NextResponse.json({ error: "Debe especificar una sucursal para el presupuesto" }, { status: 400 });

  // Validate customer belongs to branch
  if (validatedBody.customer_id && quoteBranchId) {
    const { data: customer } = await supabaseServiceRole.from("customers").select("branch_id").eq("id", validatedBody.customer_id).single() as unknown;
    if (!customer) return NextResponse.json({ error: "Cliente no encontrado" }, { status: 404 });
    if (customer.branch_id !== quoteBranchId) return NextResponse.json({ error: "El cliente no pertenece a esta sucursal. Seleccione un cliente de la sucursal actual." }, { status: 400 });
  }

  const expirationDate = validatedBody.expiration_date
    ? new Date(validatedBody.expiration_date)
    : new Date(Date.now() + defaultExpirationDays * 24 * 60 * 60 * 1000);

  // Organization ID
  let quoteOrganizationId: string | null = null;
  if (quoteBranchId) {
    const { data: branch } = await supabaseServiceRole.from("branches").select("organization_id").eq("id", quoteBranchId).single() as unknown;
    quoteOrganizationId = branch?.organization_id ?? null;
  }
  if (!quoteOrganizationId) {
    const { data: adminUser } = await supabaseServiceRole.from("admin_users").select("organization_id").eq("id", user.id).single() as unknown;
    quoteOrganizationId = adminUser?.organization_id ?? null;
  }

  // Field operation inheritance
  let quoteFieldOperationId = validatedBody.field_operation_id || null;
  if (!quoteFieldOperationId && validatedBody.customer_id) {
    const { data: cust } = await supabaseServiceRole.from("customers").select("field_operation_id").eq("id", validatedBody.customer_id).single() as unknown;
    quoteFieldOperationId = cust?.field_operation_id ?? null;
  }

  // Insert quote
  const { data: newQuote, error: quoteError } = await supabaseServiceRole.from("quotes").insert({
    quote_number: quoteNumber,
    customer_id: validatedBody.customer_id,
    branch_id: quoteBranchId,
    organization_id: quoteOrganizationId,
    field_operation_id: quoteFieldOperationId,
    prescription_id: validatedBody.prescription_id || null,
    frame_product_id: validatedBody.frame_product_id || null,
    frame_name: validatedBody.frame_name || null,
    frame_brand: validatedBody.frame_brand || null,
    frame_model: validatedBody.frame_model || null,
    frame_color: validatedBody.frame_color || null,
    frame_size: validatedBody.frame_size || null,
    frame_sku: validatedBody.frame_sku || null,
    frame_price: typeof validatedBody.frame_price === "number" ? validatedBody.frame_price : validatedBody.frame_price || 0,
    customer_own_frame: validatedBody.customer_own_frame ?? false,
    lens_family_id: validatedBody.lens_family_id || null,
    lens_type: validatedBody.lens_type || null,
    lens_material: validatedBody.lens_material || null,
    lens_index: validatedBody.lens_index || null,
    lens_treatments: validatedBody.lens_treatments || [],
    lens_tint_color: validatedBody.lens_tint_color || null,
    lens_tint_percentage: validatedBody.lens_tint_percentage || null,
    presbyopia_solution: validatedBody.presbyopia_solution || "none",
    far_lens_family_id: validatedBody.far_lens_family_id || null,
    near_lens_family_id: validatedBody.near_lens_family_id || null,
    far_lens_cost: typeof validatedBody.far_lens_cost === "number" ? validatedBody.far_lens_cost : validatedBody.far_lens_cost ?? null,
    near_lens_cost: typeof validatedBody.near_lens_cost === "number" ? validatedBody.near_lens_cost : validatedBody.near_lens_cost ?? null,
    near_frame_product_id: validatedBody.near_frame_product_id || null,
    near_frame_name: validatedBody.near_frame_name || null,
    near_frame_brand: validatedBody.near_frame_brand || null,
    near_frame_model: validatedBody.near_frame_model || null,
    near_frame_color: validatedBody.near_frame_color || null,
    near_frame_size: validatedBody.near_frame_size || null,
    near_frame_sku: validatedBody.near_frame_sku || null,
    near_frame_price: typeof validatedBody.near_frame_price === "number" ? validatedBody.near_frame_price : validatedBody.near_frame_price ?? 0,
    near_frame_cost: typeof validatedBody.near_frame_cost === "number" ? validatedBody.near_frame_cost : validatedBody.near_frame_cost ?? 0,
    near_frame_price_includes_tax: validatedBody.near_frame_price_includes_tax ?? false,
    customer_own_near_frame: validatedBody.customer_own_near_frame ?? false,
    contact_lens_family_id: validatedBody.contact_lens_family_id || null,
    contact_lens_rx_sphere_od: validatedBody.contact_lens_rx_sphere_od || null,
    contact_lens_rx_cylinder_od: validatedBody.contact_lens_rx_cylinder_od || null,
    contact_lens_rx_axis_od: validatedBody.contact_lens_rx_axis_od || null,
    contact_lens_rx_add_od: validatedBody.contact_lens_rx_add_od || null,
    contact_lens_rx_base_curve_od: validatedBody.contact_lens_rx_base_curve_od || null,
    contact_lens_rx_diameter_od: validatedBody.contact_lens_rx_diameter_od || null,
    contact_lens_rx_sphere_os: validatedBody.contact_lens_rx_sphere_os || null,
    contact_lens_rx_cylinder_os: validatedBody.contact_lens_rx_cylinder_os || null,
    contact_lens_rx_axis_os: validatedBody.contact_lens_rx_axis_os || null,
    contact_lens_rx_add_os: validatedBody.contact_lens_rx_add_os || null,
    contact_lens_rx_base_curve_os: validatedBody.contact_lens_rx_base_curve_os || null,
    contact_lens_rx_diameter_os: validatedBody.contact_lens_rx_diameter_os || null,
    contact_lens_quantity: validatedBody.contact_lens_quantity || 1,
    contact_lens_cost: validatedBody.contact_lens_cost || 0,
    contact_lens_price: validatedBody.contact_lens_price || 0,
    frame_cost: typeof validatedBody.frame_cost === "number" ? validatedBody.frame_cost : validatedBody.frame_cost || 0,
    lens_cost: typeof validatedBody.lens_cost === "number" ? validatedBody.lens_cost : validatedBody.lens_cost || 0,
    treatments_cost: typeof validatedBody.treatments_cost === "number" ? validatedBody.treatments_cost : validatedBody.treatments_cost || 0,
    labor_cost: typeof validatedBody.labor_cost === "number" ? validatedBody.labor_cost : validatedBody.labor_cost || 0,
    subtotal: typeof validatedBody.subtotal === "number" ? validatedBody.subtotal : validatedBody.subtotal || 0,
    tax_amount: typeof validatedBody.tax_amount === "number" ? validatedBody.tax_amount : validatedBody.tax_amount || 0,
    discount_amount: typeof validatedBody.discount_amount === "number" ? validatedBody.discount_amount : validatedBody.discount_amount || 0,
    discount_percentage: validatedBody.discount_percentage || 0,
    total_amount: typeof validatedBody.total_amount === "number" ? validatedBody.total_amount : parseFloat(String(validatedBody.total_amount)),
    currency: validatedBody.currency || "CLP",
    status: validatedBody.status || "draft",
    notes: validatedBody.notes || null,
    customer_notes: validatedBody.customer_notes || null,
    terms_and_conditions: validatedBody.terms_and_conditions || null,
    expiration_date: expirationDate.toISOString().split("T")[0],
    created_by: user.id,
  }).select(`*, customer:customers!quotes_customer_id_fkey(id, first_name, last_name, email, phone), prescription:prescriptions!quotes_prescription_id_fkey(*)`).single() as unknown;

  if (quoteError) return NextResponse.json({ error: "Failed to create quote", details: quoteError.message }, { status: 500 });

  // Non-blocking notification + email
  if (newQuote) {
    const customerName = newQuote.customer
      ? `${newQuote.customer.first_name || ""} ${newQuote.customer.last_name || ""}`.trim() || newQuote.customer.email || "Cliente"
      : "Cliente";

    NotificationService.notifyNewQuote(newQuote.id, newQuote.quote_number, customerName, newQuote.total_amount, newQuote.branch_id ?? undefined)
      .catch((err: Error) => logger.error("Error creating notification", err));

    if (newQuote.status === "sent" && (newQuote.customer?.email || newQuote.guest_email)) {
      (async () => {
        try {
          const { data: branch } = await supabaseServiceRole.from("branches").select("name").eq("id", newQuote.branch_id).single() as unknown;
          await sendQuoteSent({
            customer_name: customerName,
            customer_email: newQuote.customer?.email || newQuote.guest_email,
            quote_number: newQuote.quote_number,
            total_amount: newQuote.total_amount,
            expiration_date: newQuote.expiration_date,
            branch_name: branch?.name || "",
            items: [],
          }, branchContext.organizationId || undefined);
        } catch (err) {
          logger.error("Error sending quote email", err);
        }
      })();
    }
  }

  return createApiSuccessResponse(newQuote, { statusCode: 201 });
}

