/**
 * Dashboard Analytics Service
 * Extracted analytics computation from dashboard API route
 */
import { unstable_cache } from "next/cache";

import {
  computeInventoryMetrics,
} from "@/lib/analytics/analytics-service";
import { computeAnalyticsMvData } from "@/lib/analytics/compute-analytics-kpis";
import type { MvKpiRow } from "@/lib/analytics/compute-dashboard-kpis";
import {
  addBranchFilter,
  addBranchFilterForBranchScopedTable,
} from "@/lib/api/branch-middleware";
import { createServiceRoleClient } from "@/utils/supabase/server";

function getLocalDateString(date: Date): string {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function scopeByBranchIds(query: unknown, branchId: string | null, orgBranchIds: string[]) {
  if (branchId) return query.eq("branch_id", branchId);
  if (orgBranchIds.length > 0) return query.in("branch_id", orgBranchIds);
  return query.limit(0);
}

export interface DashboardAnalyticsParams {
  orgId: string | null;
  branchId: string | null;
  isSuperAdmin: boolean;
  organizationId: string | null;
  orgBranchIds: string[];
  period: number;
  startDate: Date;
  endDate: Date;
  startStr: string;
  endStr: string;
  periodStartStr: string;
  periodEndStr: string;
  prevPeriodStartStr: string;
}

export async function computeDashboardAnalytics(params: DashboardAnalyticsParams) {
  const {
    orgId,
    branchId,
    isSuperAdmin,
    organizationId: orgIdVal,
    orgBranchIds,
    period,
    startDate,
    endDate,
    startStr,
    endStr,
    periodStartStr,
    periodEndStr,
    prevPeriodStartStr,
  } = params;

  const cacheTtl = Number(process.env.ANALYTICS_CACHE_TTL_SECONDS) || 180;
  const cacheKey = [
    "analytics-dashboard",
    orgId ?? "none",
    branchId ?? "global",
    String(period),
  ];

  return unstable_cache(
    async () => {
      const svc = createServiceRoleClient();

      // MV query
      let mvQuery = svc
        .from("mv_daily_kpis")
        .select("*")
        .gte("day", prevPeriodStartStr)
        .lte("day", periodEndStr);
      if (orgId) mvQuery = mvQuery.eq("organization_id", orgId);
      if (branchId) mvQuery = mvQuery.eq("branch_id", branchId);

      // POS revenue
      let posQuery = svc
        .from("orders")
        .select("total_amount")
        .eq("is_pos_sale", true)
        .in("payment_status", ["paid", "completed"])
        .gte("created_at", startStr)
        .lte("created_at", endStr);
      posQuery = addBranchFilter(posQuery, branchId, isSuperAdmin, orgId);

      // Work orders revenue
      let woRevenueQuery = svc
        .from("lab_work_orders")
        .select("total_amount")
        .eq("payment_status", "paid")
        .gte("created_at", startStr)
        .lte("created_at", endStr);
      woRevenueQuery = addBranchFilter(woRevenueQuery, branchId, isSuperAdmin, orgId);

      // Quotes
      let quotesQuery = svc
        .from("quotes")
        .select("status, total_amount")
        .gte("created_at", startStr)
        .lte("created_at", endStr);
      quotesQuery = addBranchFilter(quotesQuery, branchId, isSuperAdmin, orgId);

      // Customers
      const customerScope = await addBranchFilterForBranchScopedTable(
        svc.from("customers").select("id, created_at"),
        { branchId, isSuperAdmin, organizationId: orgIdVal, isGlobalView: false, accessibleBranches: [] },
        svc as unknown,
      );

      // Products
      let productsQuery = svc
        .from("products")
        .select("id, name, slug, category_id, price")
        .eq("status", "active");
      productsQuery = addBranchFilter(productsQuery, branchId, isSuperAdmin, orgId);

      // Stock
      let stockQuery = svc
        .from("product_branch_stock")
        .select("product_id, branch_id, quantity, low_stock_threshold");
      stockQuery = scopeByBranchIds(stockQuery, branchId, orgBranchIds);

      // Categories
      let categoriesQuery = svc.from("categories").select("id, name, slug");
      if (orgId) categoriesQuery = categoriesQuery.eq("organization_id", orgId);

      // Closures
      let closuresQuery = svc
        .from("cash_register_closures")
        .select("total_sales, total_transactions, cash_sales, debit_card_sales, credit_card_sales, installments_sales, other_payment_sales")
        .in("status", ["confirmed", "closed"])
        .gte("closure_date", periodStartStr)
        .lte("closure_date", periodEndStr);
      closuresQuery = scopeByBranchIds(closuresQuery, branchId, orgBranchIds);

      // Top products
      let topProductsQuery = svc
        .from("orders")
        .select(`total_amount, created_at, order_items ( product_id, product_name, quantity, total_price )`)
        .or("status.eq.completed,payment_status.eq.paid")
        .gte("created_at", startStr)
        .lte("created_at", endStr);
      topProductsQuery = addBranchFilter(topProductsQuery, branchId, isSuperAdmin, orgId);

      // Support tickets
      let supportTicketQuery = svc
        .from("optical_internal_support_tickets")
        .select("id, status, category, resolution_time_minutes, created_at")
        .gte("created_at", startStr)
        .lte("created_at", endStr);
      if (orgId) {
        supportTicketQuery = supportTicketQuery.eq("organization_id", orgId);
        if (branchId) {
          supportTicketQuery = supportTicketQuery.eq("branch_id", branchId);
        } else if (orgBranchIds.length > 0) {
          supportTicketQuery = supportTicketQuery.or(
            `branch_id.is.null,branch_id.in.(${orgBranchIds.join(",")})`,
          );
        }
      } else {
        supportTicketQuery = supportTicketQuery.limit(0);
      }

      // Delivery query
      let deliveryQuery = svc
        .from("lab_work_orders")
        .select("ordered_at, delivered_at")
        .eq("status", "delivered")
        .not("ordered_at", "is", null)
        .not("delivered_at", "is", null)
        .gte("created_at", startStr)
        .lte("created_at", endStr);
      deliveryQuery = addBranchFilter(deliveryQuery, branchId, isSuperAdmin, orgId);

      // Execute in parallel
      const [mvResult, posResult, woRevenueResult, quotesResult, customersResult,
        productsResult, stockResult, categoriesResult, closuresResult,
        topProductsResult, supportTicketResult, deliveryResult] = await Promise.all([
        mvQuery, posQuery, woRevenueQuery, quotesQuery, customerScope,
        productsQuery, stockQuery, categoriesQuery, closuresQuery,
        topProductsQuery, supportTicketQuery, deliveryQuery,
      ]);

      // Process MV data
      const mvRows = (mvResult.data || []) as unknown as MvKpiRow[];
      const mvData = computeAnalyticsMvData(mvRows, period, startDate, endDate);

      // Revenue
      const posOrders = posResult.data || [];
      const posRevenue = posOrders.reduce((s: number, o: unknown) => s + Number(o.total_amount || 0), 0);
      const posTransactionCount = posOrders.length;

      const paidWorkOrders = woRevenueResult.data || [];
      const workOrdersRevenue = paidWorkOrders.reduce((s: number, wo: unknown) => s + Number(wo.total_amount || 0), 0);

      const totalRevenue = posRevenue + workOrdersRevenue;
      const avgOrderValue = posTransactionCount > 0 ? posRevenue / posTransactionCount
        : posOrders.length > 0 ? posRevenue / posOrders.length : 0;
      const avgWorkOrderValue = mvData.totalWorkOrders > 0 ? workOrdersRevenue / mvData.totalWorkOrders : 0;

      // Quotes processing
      const quotes = quotesResult.data || [];
      const totalQuotes = quotes.length;
      const quotesByStatus: Record<string, number> = {};
      let acceptedQuotes = 0, rejectedQuotes = 0, expiredQuotes = 0, convertedQuotes = 0, totalQuoteAmount = 0;
      for (const q of quotes) {
        const status = (q as unknown).status || "draft";
        quotesByStatus[status] = (quotesByStatus[status] || 0) + 1;
        if (status === "accepted") acceptedQuotes++;
        if (status === "rejected") rejectedQuotes++;
        if (status === "expired") expiredQuotes++;
        if (status === "converted_to_work") convertedQuotes++;
        if ((q as unknown).total_amount) totalQuoteAmount += Number((q as unknown).total_amount);
      }
      const quoteConversionRate = totalQuotes > 0 ? ((acceptedQuotes + convertedQuotes) / totalQuotes) * 100 : 0;
      const avgQuoteValue = totalQuotes > 0 ? totalQuoteAmount / totalQuotes : 0;

      // Customers
      const customers = customersResult.data || [];
      const totalCustomers = customers.length;
      const customersInPeriod = (customers as unknown[]).filter((c: unknown) => {
        const d = new Date(c.created_at);
        return d >= startDate && d <= endDate;
      });
      const newCustomers = customersInPeriod.length;

      // Recurring customers
      let recurringQuery = svc.from("orders").select("customer_email").not("customer_email", "is", null).gte("created_at", startStr).lte("created_at", endStr);
      recurringQuery = addBranchFilter(recurringQuery, branchId, isSuperAdmin, orgId);
      const { data: orderEmails } = await recurringQuery;
      const emailCounts: Record<string, number> = {};
      ((orderEmails || []) as unknown[]).forEach((o: unknown) => {
        if (o.customer_email) emailCounts[o.customer_email] = (emailCounts[o.customer_email] || 0) + 1;
      });
      const recurringCustomers = Object.values(emailCounts).filter((c) => c > 1).length;

      // Products & inventory
      const products = productsResult.data || [];
      const productBranchStock = stockResult.data || [];
      const categories = categoriesResult.data || [];
      const productIdsInCatalog = new Set((products as unknown[]).map((p: unknown) => p.id));
      const inventoryMetrics = computeInventoryMetrics(
        (productBranchStock || []) as unknown,
        productIdsInCatalog,
      );

      // Top products
      const productStats: Record<string, unknown> = {};
      ((topProductsResult.data || []) as unknown[]).forEach((order: unknown) => {
        (order.order_items || []).forEach((item: unknown) => {
          const pid = item.product_id;
          if (!productStats[pid]) {
            productStats[pid] = { id: pid, name: item.product_name || "Producto Sin Nombre", revenue: 0, quantity: 0, orders: new Set() };
          }
          productStats[pid].revenue += Number(item.total_price || 0);
          productStats[pid].quantity += Number(item.quantity || 0);
        });
      });
      const topProducts = Object.values(productStats)
        .map((stat: unknown) => ({ id: stat.id, name: stat.name, category: "General", revenue: stat.revenue, quantity: stat.quantity, orders: stat.orders.size }))
        .sort((a: unknown, b: unknown) => b.revenue - a.revenue)
        .slice(0, 10);
      topProducts.forEach((product: unknown) => {
        const prod = (products as unknown[]).find((p: unknown) => p.id === product.id);
        if (prod) {
          const cat = (categories as unknown[]).find((c: unknown) => c.id === prod.category_id);
          product.category = cat?.name || "Sin Categoría";
        }
      });

      // Category revenue
      const categoryRevenue: Record<string, number> = {};
      ((topProductsResult.data || []) as unknown[]).forEach((order: unknown) => {
        (order.order_items || []).forEach((item: unknown) => {
          const prod = (products as unknown[]).find((p: unknown) => p.id === item.product_id);
          if (prod && prod.category_id) {
            const cat = (categories as unknown[]).find((c: unknown) => c.id === prod.category_id);
            const catName = cat?.name || "Sin Categoría";
            categoryRevenue[catName] = (categoryRevenue[catName] || 0) + Number(item.total_price || 0);
          }
        });
      });
      const categoryRevenueArray = Object.entries(categoryRevenue)
        .map(([category, revenue]) => ({ category, revenue }))
        .sort((a, b) => b.revenue - a.revenue)
        .slice(0, 8);

      // Payment methods
      const paymentMethods: Record<string, { count: number; revenue: number }> = {};
      const closures = closuresResult.data || [];
      if (closures.length > 0) {
        const totalClosureRevenue = (closures as unknown[]).reduce((s: number, c: unknown) => s + (Number(c.total_sales) || 0), 0);
        const totalClosureTxns = (closures as unknown[]).reduce((s: number, c: unknown) => s + (Number(c.total_transactions) || 0), 0);
        (closures as unknown[]).forEach((c: unknown) => {
          const addPayment = (method: string, amount: number) => {
            if (amount > 0) {
              if (!paymentMethods[method]) paymentMethods[method] = { count: 0, revenue: 0 };
              paymentMethods[method].revenue += amount;
            }
          };
          addPayment("cash", Number(c.cash_sales) || 0);
          addPayment("debit_card", Number(c.debit_card_sales) || 0);
          addPayment("credit_card", Number(c.credit_card_sales) || 0);
          addPayment("installments", Number(c.installments_sales) || 0);
          addPayment("other", Number(c.other_payment_sales) || 0);
        });
        if (totalClosureRevenue > 0 && totalClosureTxns > 0) {
          Object.keys(paymentMethods).forEach((method) => {
            paymentMethods[method].count = Math.round((paymentMethods[method].revenue / totalClosureRevenue) * totalClosureTxns) || 1;
          });
        }
      }

      // Customer trends
      const customerTrends: Array<{ date: string; value: number; count: number }> = [];
      for (let i = 0; i < period; i++) {
        const d = new Date(startDate);
        d.setDate(d.getDate() + i);
        const dateStr = getLocalDateString(d);
        const nextDay = new Date(d);
        nextDay.setDate(nextDay.getDate() + 1);
        const dayCustomers = (customers as unknown[]).filter((c: unknown) => {
          const cd = new Date(c.created_at);
          return cd >= d && cd < nextDay;
        });
        customerTrends.push({ date: dateStr, value: dayCustomers.length, count: dayCustomers.length });
      }

      // Support tickets
      const supportTickets = supportTicketResult.data || [];
      const supportByStatus: Record<string, number> = {};
      const supportByCategory: Record<string, number> = {};
      (supportTickets as unknown[]).forEach((t: unknown) => {
        const status = t.status || "open";
        supportByStatus[status] = (supportByStatus[status] || 0) + 1;
        const cat = t.category || "other";
        supportByCategory[cat] = (supportByCategory[cat] || 0) + 1;
      });
      const openSupportStatuses = ["open", "assigned", "in_progress", "waiting_customer"];
      const openTickets = (supportTickets as unknown[]).filter((t: unknown) => openSupportStatuses.includes(t.status || "")).length;
      const resolvedTickets = (supportTickets as unknown[]).filter((t: unknown) => t.status === "resolved" || t.status === "closed").length;
      const ticketsWithResolution = (supportTickets as unknown[]).filter((t: unknown) => t.resolution_time_minutes != null);
      const avgResolutionMinutes = ticketsWithResolution.length > 0
        ? Math.round(ticketsWithResolution.reduce((s: number, t: unknown) => s + (t.resolution_time_minutes || 0), 0) / ticketsWithResolution.length)
        : null;

      // Support trends
      const supportTrends: Array<{ date: string; value: number; count: number }> = [];
      for (let i = 0; i < period; i++) {
        const d = new Date(startDate);
        d.setDate(d.getDate() + i);
        const dateStr = getLocalDateString(d);
        const nextDay = new Date(d);
        nextDay.setDate(nextDay.getDate() + 1);
        const dayTickets = (supportTickets as unknown[]).filter((t: unknown) => {
          const td = new Date(t.created_at);
          return td >= d && td < nextDay;
        });
        supportTrends.push({ date: dateStr, value: dayTickets.length, count: dayTickets.length });
      }

      // Avg delivery days
      const deliveredWorkOrders = deliveryResult.data || [];
      let avgDeliveryDays = 0;
      if (deliveredWorkOrders.length > 0) {
        const totalDays = (deliveredWorkOrders as unknown[]).reduce((sum: number, wo: unknown) => {
          const ordered = new Date(wo.ordered_at);
          const delivered = new Date(wo.delivered_at);
          return sum + Math.ceil((delivered.getTime() - ordered.getTime()) / (1000 * 60 * 60 * 24));
        }, 0);
        avgDeliveryDays = Math.round(totalDays / deliveredWorkOrders.length);
      }

      return {
        kpis: {
          totalRevenue, posRevenue, posTransactionCount, workOrdersRevenue,
          revenueGrowth: mvData.revenueGrowth, totalOrders: mvData.totalOrders,
          totalWorkOrders: mvData.totalWorkOrders, totalQuotes, totalAppointments: mvData.totalAppointments,
          totalCustomers, newCustomers, recurringCustomers, avgOrderValue, avgWorkOrderValue, avgQuoteValue,
          quoteConversionRate, appointmentCompletionRate: mvData.appointments.completionRate, avgDeliveryDays,
        },
        workOrders: mvData.workOrders,
        quotes: { total: totalQuotes, accepted: acceptedQuotes, rejected: rejectedQuotes, expired: expiredQuotes, converted: convertedQuotes, byStatus: quotesByStatus, conversionRate: quoteConversionRate },
        appointments: mvData.appointments,
        products: {
          total: products.length,
          lowStock: inventoryMetrics.lowStock,
          outOfStock: inventoryMetrics.outOfStock,
          topProducts,
          categoryRevenue: categoryRevenueArray,
        },
        paymentMethods: Object.entries(paymentMethods).map(([method, data]) => ({ method, count: data.count, revenue: data.revenue })),
        trends: {
          sales: mvData.salesTrends,
          customers: customerTrends,
          workOrders: mvData.workOrderTrends,
          quotes: mvData.quoteTrends,
          supportTickets: supportTrends,
        },
        support: { total: supportTickets.length, open: openTickets, resolved: resolvedTickets, avgResolutionMinutes, byStatus: supportByStatus, byCategory: supportByCategory, trends: supportTrends },
        period: { from: periodStartStr, to: periodEndStr, days: period },
      };
    },
    cacheKey,
    { revalidate: cacheTtl },
  )();
}

/**
 * Error Service
 *
 * Servicio centralizado para manejo consistente de errores en toda la aplicación.
 * Proporciona funciones para extraer mensajes de error, manejar errores de API,
 * y mostrar notificaciones de error al usuario.
 *
 * @module lib/api/services/errorService
 */

import { toast } from "sonner";

import { appLogger as logger } from "@/lib/logger";

/**
 * Tipos de error conocidos
 */
export type ErrorType =
  | "network"
  | "authentication"
  | "authorization"
  | "validation"
  | "not_found"
  | "server"
  | "unknown";

/**
 * Interfaz para errores estandarizados
 */
export interface StandardError {
  type: ErrorType;
  message: string;
  userMessage: string;
  code?: string;
  details?: unknown;
  timestamp: string;
}

/**
 * Extrae el mensaje de error de un error desconocido
 *
 * @param error - Error a procesar
 * @returns Mensaje de error extraído
 *
 * @example
 * extractErrorMessage(new Error("Something went wrong")) // "Something went wrong"
 * extractErrorMessage("Custom error message") // "Custom error message"
 * extractErrorMessage({ message: "Error object" }) // "Error object"
 * extractErrorMessage(null) // "An unexpected error occurred"
 */
export function extractErrorMessage(error: unknown): string {
  if (!error) {
    return "An unexpected error occurred";
  }

  // Error de tipo Error
  if (error instanceof Error) {
    return error.message;
  }

  // String
  if (typeof error === "string") {
    return error;
  }

  // Objeto con propiedad message
  if (typeof error === "object" && error !== null) {
    if ("message" in error && typeof error.message === "string") {
      return error.message;
    }
    if ("error" in error && typeof error.error === "string") {
      const details =
        "details" in error && typeof error.details === "string"
          ? `: ${error.details}`
          : "";
      return error.error + details;
    }
    if (
      "error" in error &&
      typeof error.error === "object" &&
      error.error !== null
    ) {
      if ("message" in error.error && typeof error.error.message === "string") {
        return error.error.message;
      }
    }
  }

  // Fallback
  return "An unexpected error occurred";
}

/**
 * Determina el tipo de error basado en el error
 *
 * @param error - Error a clasificar
 * @returns Tipo de error
 */
export function classifyError(error: unknown): ErrorType {
  if (!error) {
    return "unknown";
  }

  const message = extractErrorMessage(error).toLowerCase();

  // Network errors
  if (
    message.includes("network") ||
    message.includes("fetch") ||
    message.includes("connection")
  ) {
    return "network";
  }

  // Authentication errors
  if (
    message.includes("unauthorized") ||
    message.includes("authentication") ||
    message.includes("not authenticated")
  ) {
    return "authentication";
  }

  // Authorization errors
  if (
    message.includes("forbidden") ||
    message.includes("permission") ||
    message.includes("not authorized")
  ) {
    return "authorization";
  }

  // Validation errors
  if (
    message.includes("validation") ||
    message.includes("invalid") ||
    message.includes("required")
  ) {
    return "validation";
  }

  // Not found errors
  if (message.includes("not found") || message.includes("404")) {
    return "not_found";
  }

  // Server errors
  if (
    message.includes("server") ||
    message.includes("500") ||
    message.includes("internal")
  ) {
    return "server";
  }

  return "unknown";
}

/**
 * Crea un error estandarizado
 *
 * @param error - Error original
 * @param context - Contexto adicional del error
 * @returns Error estandarizado
 */
export function createStandardError(
  error: unknown,
  context?: string,
): StandardError {
  const message = extractErrorMessage(error);
  const type = classifyError(error);
  const userMessage = getUserFriendlyMessage({
    type,
    message,
    userMessage: "",
    timestamp: new Date().toISOString(),
  });

  return {
    type,
    message: context ? `[${context}] ${message}` : message,
    userMessage,
    timestamp: new Date().toISOString(),
  };
}

/**
 * Maneja un error de API de manera consistente
 *
 * @param error - Error a manejar
 * @param context - Contexto del error (ej: "Customer API", "Order API")
 * @param showToast - Si debe mostrar notificación toast (default: true)
 * @returns Error estandarizado
 *
 * @example
 * try {
 *   await fetchCustomers();
 * } catch (error) {
 *   handleApiError(error, "Customer API");
 * }
 */
export function handleApiError(
  error: unknown,
  context: string = "API",
  showToast: boolean = true,
): StandardError {
  const standardError = createStandardError(error, context);

  // Log del error para debugging
  logger.error(`[${context}] Error:`, error);

  // Mostrar notificación toast si está habilitado
  if (showToast) {
    const userMessage = getUserFriendlyMessage(standardError);
    toast.error(userMessage, {
      description: standardError.message,
      duration: 5000,
    });
  }

  return standardError;
}

/**
 * Obtiene un mensaje amigable para el usuario basado en el tipo de error
 *
 * @param error - Error estandarizado
 * @returns Mensaje amigable para el usuario
 */
export function getUserFriendlyMessage(error: StandardError): string {
  switch (error.type) {
    case "network":
      return "Error de conexión";
    case "authentication":
      return "Error de autenticación";
    case "authorization":
      return "No tienes permiso para realizar esta acción";
    case "validation":
      return "Error de validación";
    case "not_found":
      return "Recurso no encontrado";
    case "server":
      return "Error del servidor";
    default:
      return "Error inesperado";
  }
}

/**
 * Maneja un error de validación
 *
 * @param error - Error de validación
 * @param context - Contexto del error
 * @returns Error estandarizado
 */
export function handleValidationError(
  error: unknown,
  context: string = "Validation",
): StandardError {
  return handleApiError(error, context, true);
}

/**
 * Maneja un error de red
 *
 * @param error - Error de red
 * @param context - Contexto del error
 * @returns Error estandarizado
 */
export function handleNetworkError(
  error: unknown,
  context: string = "Network",
): StandardError {
  return handleApiError(error, context, true);
}

/**
 * Maneja un error de autenticación
 *
 * @param error - Error de autenticación
 * @param context - Contexto del error
 * @returns Error estandarizado
 */
export function handleAuthenticationError(
  error: unknown,
  context: string = "Authentication",
): StandardError {
  const standardError = handleApiError(error, context, true);

  // Redirigir a login si es un error de autenticación
  if (typeof window !== "undefined") {
    // Opcional: redirigir a login
    // window.location.href = "/login";
  }

  return standardError;
}

/**
 * Maneja un error de autorización
 *
 * @param error - Error de autorización
 * @param context - Contexto del error
 * @returns Error estandarizado
 */
export function handleAuthorizationError(
  error: unknown,
  context: string = "Authorization",
): StandardError {
  return handleApiError(error, context, true);
}

/**
 * Maneja un error de servidor
 *
 * @param error - Error de servidor
 * @param context - Contexto del error
 * @returns Error estandarizado
 */
export function handleServerError(
  error: unknown,
  context: string = "Server",
): StandardError {
  return handleApiError(error, context, true);
}

/**
 * Maneja un error genérico
 *
 * @param error - Error a manejar
 * @param context - Contexto del error
 * @returns Error estandarizado
 */
export function handleGenericError(
  error: unknown,
  context: string = "Error",
): StandardError {
  return handleApiError(error, context, true);
}

/**
 * Wrapper para funciones asíncronas que maneja errores automáticamente
 *
 * @param fn - Función asíncrona a ejecutar
 * @param context - Contexto del error
 * @returns Resultado de la función o null si hay error
 *
 * @example
 * const result = await withErrorHandling(async () => {
 *   return await fetchCustomers();
 * }, "Customer API");
 */
export async function withErrorHandling<T>(
  fn: () => Promise<T>,
  context: string = "Operation",
): Promise<T | null> {
  try {
    return await fn();
  } catch (error) {
    handleApiError(error, context);
    return null;
  }
}

/**
 * Exportar el servicio completo
 */
export const ErrorService = {
  extractErrorMessage,
  classifyError,
  createStandardError,
  handleApiError,
  handleValidationError,
  handleNetworkError,
  handleAuthenticationError,
  handleAuthorizationError,
  handleServerError,
  handleGenericError,
  getUserFriendlyMessage,
  withErrorHandling,
};

/**
 * POS Service - Centralized API operations for Point of Sale
 *
 * This service handles all POS-related API calls including:
 * - Cash register status
 * - Sales processing
 * - Pending balance orders
 * - Payment processing
 */
import { handleApiError } from "@/lib/api/services/errorService";
import { success } from "@/lib/api/services/notificationService";
import { appLogger as logger } from "@/lib/logger";
import { getBranchAndOperativoHeaders } from "@/lib/utils/branch";

import { ApiClient, isError, isSuccess, unwrapData } from "../client-helpers";

// ============================================
// Types
// ============================================

export interface CashRegisterStatus {
  isOpen: boolean;
  session_id?: string;
  branch_id?: string;
  opened_at?: string;
  closing_balance?: number;
  current_balance?: number;
  /** Session details from GET /api/admin/cash-register/open */
  session?: {
    id?: string;
    opening_cash_amount?: number;
    opening_time?: string;
    status?: string;
    [key: string]: unknown;
  };
}

export interface PendingBalanceOrder {
  id: string;
  order_number: string;
  customer_name: string;
  customer_rut?: string;
  total_amount: number;
  paid_amount: number;
  pending_amount: number;
  payment_status: string;
  created_at: string;
}

export interface ProcessSaleRequest {
  // Customer info
  customer_id?: string;
  customer_name?: string;
  customer_rut?: string;
  customer_email?: string;
  customer_phone?: string;

  // Cart items
  items: Array<{
    product_id: string;
    product_name: string;
    quantity: number;
    unit_price: number;
    discount?: number;
    discount_type?: "percentage" | "fixed";
    notes?: string;
  }>;

  // Payment info
  payment_method: string;
  cash_received?: number;
  card_last_four?: string;
  card_brand?: string;
  transfer_reference?: string;

  // Lens data (optional)
  lens_type?: string;
  lens_material?: string;
  lens_index?: number;
  frame_model?: string;

  // Prescription
  prescription_id?: string;

  // Financial
  subtotal: number;
  discount_amount: number;
  tax_amount: number;
  total: number;

  // Branch
  branch_id: string;

  // Agreement (convenio)
  agreement_id?: string;
  purchase_order_id?: string;

  // Notes
  notes?: string;
  internal_notes?: string;
}

export interface ProcessSaleResponse {
  success: boolean;
  order?: {
    id: string;
    order_number: string;
    total_amount: number;
    payment_status: string;
    sii_invoice_number?: string;
  };
  work_order?: {
    id: string;
    work_order_number: string;
    sii_invoice_number?: string;
  };
  message?: string;
}

export interface PendingPaymentRequest {
  order_id: string;
  payment_amount: number;
  payment_method: string;
  notes?: string;
  fiscal_reference?: string;
}

export interface PendingPaymentResponse {
  success: boolean;
  message?: string;
  payment?: {
    id: string;
    amount: number;
    payment_method: string;
  };
}

// ============================================
// Service Class
// ============================================

class POSService {
  private readonly basePath = "/api/admin/pos";
  private client = new ApiClient();

  /**
   * Check if cash register is open
   * @param fieldOperationId - When in operativo mode, checks operativo's independent cash register
   */
  async getCashStatus(
    branchId?: string,
    fieldOperationId?: string | null,
  ): Promise<CashRegisterStatus | null> {
    try {
      const headers = getBranchAndOperativoHeaders(
        branchId ?? null,
        fieldOperationId ?? undefined,
      );
      const response = await this.client.get<CashRegisterStatus>(
        `/api/admin/cash-register/open`,
        {
          headers: Object.keys(headers).length > 0 ? headers : undefined,
        },
      );

      if (isSuccess(response)) {
        return unwrapData(response);
      }

      handleApiError(response);
      return null;
    } catch (error) {
      logger.error("Error fetching cash status:", error);
      handleApiError(error);
      return null;
    }
  }

  /**
   * Get pending balance orders
   */
  async getPendingBalanceOrders(
    searchTerm?: string,
    branchId?: string,
    limit: number = 500,
  ): Promise<PendingBalanceOrder[]> {
    try {
      const params = new URLSearchParams({
        limit: limit.toString(),
      });

      if (searchTerm?.trim()) {
        params.append("search", searchTerm.trim());
      }

      const response = await this.client.get<PendingBalanceOrder[]>(
        `${this.basePath}/pending-balance?${params}`,
        {
          headers: branchId ? { "x-branch-id": branchId } : undefined,
        },
      );

      if (isSuccess(response)) {
        const data = unwrapData(response);
        return Array.isArray(data) ? data : [];
      }

      handleApiError(response);
      return [];
    } catch (error) {
      logger.error("Error fetching pending balance orders:", error);
      handleApiError(error);
      return [];
    }
  }

  /**
   * Process a pending payment
   */
  async processPendingPayment(
    request: PendingPaymentRequest,
    branchId?: string,
  ): Promise<PendingPaymentResponse | null> {
    try {
      const response = await this.client.post<PendingPaymentResponse>(
        `${this.basePath}/pending-balance/pay`,
        request,
        {
          headers: branchId ? { "x-branch-id": branchId } : undefined,
        },
      );

      if (isSuccess(response)) {
        const data = unwrapData(response);
        // Removed success toast from service layer to avoid double toasts
        return data;
      }

      // If response is not success, throw error with message from response
      const errorMessage =
        response.error?.message || "Error processing payment";
      throw new Error(errorMessage);
    } catch (error) {
      logger.error("Error processing pending payment:", error);
      throw error;
    }
  }

  /**
   * Process a complete sale
   */
  async processSale(
    orderData: ProcessSaleRequest,
    branchId?: string,
    fieldOperationId?: string,
  ): Promise<ProcessSaleResponse | null> {
    try {
      const headers = getBranchAndOperativoHeaders(branchId, fieldOperationId);
      const response = await this.client.post<ProcessSaleResponse>(
        `${this.basePath}/process-sale`,
        orderData,
        {
          headers: Object.keys(headers).length > 0 ? headers : undefined,
        },
      );

      if (isSuccess(response)) {
        const data = unwrapData(response);

        const orderNumber =
          data?.work_order?.work_order_number || data?.order?.order_number;
        success(
          orderNumber
            ? `Venta procesada: ${orderNumber}`
            : "Venta procesada correctamente",
        );

        return data;
      }

      // For 5xx/network errors: show specific message (sale may have gone through)
      const errMsg = isError(response) ? (response.error?.message ?? "") : "";
      const errCode = isError(response) ? (response.error?.code ?? "") : "";
      const isServerOrNetwork =
        errCode === "NETWORK_ERROR" ||
        /internal server error|500|timeout|network error|failed to fetch/i.test(
          errMsg,
        );
      if (isServerOrNetwork) {
        const { error: showError } = await import(
          "@/lib/api/services/notificationService"
        );
        showError(
          "La venta puede haberse procesado. Revise en Caja u Órdenes antes de reintentar.",
        );
        return null;
      }

      handleApiError(response);
      return null;
    } catch (error) {
      logger.error("Error processing sale:", error);
      const errMsg = error instanceof Error ? error.message : String(error);
      const isServerOrNetwork = /network|timeout|failed to fetch/i.test(errMsg);
      if (isServerOrNetwork) {
        const { error: showError } = await import(
          "@/lib/api/services/notificationService"
        );
        showError(
          "La venta puede haberse procesado. Revise en Caja u Órdenes antes de reintentar.",
        );
        return null;
      }
      handleApiError(error);
      return null;
    }
  }

  /**
   * Process a refund for an order
   */
  async processRefund(
    request: {
      order_id: string;
      items: Array<{ order_item_id: string; quantity: number }>;
      reason: string;
      refund_type: "full" | "partial";
    },
    branchId?: string,
  ): Promise<{
    success: boolean;
    refund_amount: number;
    items_refunded: number;
  } | null> {
    try {
      const response = await this.client.post<{
        success: boolean;
        refund_amount: number;
        items_refunded: number;
      }>(`${this.basePath}/refund`, request, {
        headers: branchId ? { "x-branch-id": branchId } : undefined,
      });

      if (isSuccess(response)) {
        return unwrapData(response);
      }

      handleApiError(response);
      return null;
    } catch (error) {
      logger.error("Error processing refund:", error);
      handleApiError(error);
      return null;
    }
  }

  /**
   * Get billing settings
   */
  async getBillingSettings(
    branchId?: string,
  ): Promise<Record<string, unknown> | null> {
    try {
      const response = await this.client.get<{
        settings: Record<string, unknown>;
      }>("/api/admin/billing/settings", {
        headers: branchId ? { "x-branch-id": branchId } : undefined,
      });

      if (isSuccess(response)) {
        const data = unwrapData(response);
        // Handle both wrapped {settings: {...}} and direct {...} responses
        if (data && typeof data === "object" && "settings" in data) {
          return (data as { settings: Record<string, unknown> }).settings;
        }
        return data as Record<string, unknown>;
      }

      handleApiError(response);
      return null;
    } catch (error) {
      logger.error("Error fetching billing settings:", error);
      handleApiError(error);
      return null;
    }
  }

  /**
   * Get current organization
   */
  async getCurrentOrganization(branchId?: string) {
    try {
      const response = await this.client.get<{
        organization: Record<string, unknown>;
      }>("/api/admin/organizations/current", {
        headers: branchId ? { "x-branch-id": branchId } : undefined,
      });

      if (isSuccess(response)) {
        const data = unwrapData(response);
        return data?.organization || null;
      }

      handleApiError(response);
      return null;
    } catch (error) {
      logger.error("Error fetching current organization:", error);
      handleApiError(error);
      return null;
    }
  }
}

// Export singleton instance
export const posService = new POSService();

import type { SupabaseClient } from "@supabase/supabase-js";

import type { Database } from "@/types/supabase";

export function buildProductSelectString(branchId?: string): string {
  let s = `*, categories:category_id (id, name, slug), product_variants (id, title, price, inventory_quantity, option1, option2, option3, is_default)`;
  if (branchId) s += `, product_branch_stock (quantity, reserved_quantity, low_stock_threshold, branch_id)`;
  return s;
}

export function applyProductFilters(
  query: ReturnType<SupabaseClient<Database>["from"]>, params: Record<string, unknown>,
): ReturnType<SupabaseClient<Database>["from"]> {
  const { category, skinType, minPrice, maxPrice, featured, status, includeArchived, search, branchId } = params;
  let q = query;
  if (category) q = q.eq("category_id", category);
  if (skinType) q = q.contains("skin_type", [skinType]);
  if (minPrice) q = q.gte("price", parseFloat(minPrice));
  if (maxPrice) q = q.lte("price", parseFloat(maxPrice));
  if (featured) q = q.eq("featured", featured === "true");
  if (status && status !== "all") q = q.eq("status", status);
  if (!includeArchived) q = q.neq("status", "archived");
  if (search) {
    const srch = `%${search}%`;
    q = q.or(`name.ilike.${srch},description.ilike.${srch},sku.ilike.${srch}`);
  }
  return q;
}

export function validateSortColumn(sortBy: string): string {
  const valid = ["created_at", "updated_at", "name", "price", "sku", "status", "featured", "inventory_quantity"];
  return valid.includes(sortBy) ? sortBy : "created_at";
}

export function filterProductsByBranch(products: unknown[], branchId: string): unknown[] {
  return products.filter((p) => !p.branch_id || p.branch_id === branchId);
}

export function filterLowStockProducts(products: unknown[], branchId?: string | null): unknown[] {
  return products.filter((p) => {
    if (branchId && p.product_branch_stock) {
      const bs = p.product_branch_stock.find((s: unknown) => s.branch_id === branchId);
      return bs ? bs.quantity <= bs.low_stock_threshold : false;
    }
    return false;
  });
}

export function filterInStockProducts(products: unknown[], branchId?: string | null): unknown[] {
  return products.filter((p) => {
    if (branchId && p.product_branch_stock) {
      const bs = p.product_branch_stock.find((s: unknown) => s.branch_id === branchId);
      return bs ? bs.quantity > 0 : false;
    }
    return false;
  });
}

export function filterOutOfStockProducts(products: unknown[], branchId?: string | null): unknown[] {
  return products.filter((p) => {
    if (branchId && p.product_branch_stock) {
      const bs = p.product_branch_stock.find((s: unknown) => s.branch_id === branchId);
      return bs ? bs.quantity <= 0 : true;
    }
    return true;
  });
}

export function generateSlug(name: string): string {
  return name.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "") || `product-${Date.now()}`;
}

export async function ensureUniqueSlug(supabase: SupabaseClient<Database>, slug: string, excludeId?: string): Promise<string> {
  let uniqueSlug = slug;
  let counter = 1;
  while (true) {
    let query = supabase.from("products").select("id").eq("slug", uniqueSlug);
    if (excludeId) query = query.neq("id", excludeId);
    const { data: existing } = await query.limit(1);
    if (!existing || existing.length === 0) break;
    uniqueSlug = `${slug}-${counter++}`;
  }
  return uniqueSlug;
}

/**
 * Products Service — Business logic layer for Products operations.
 */
import { SupabaseClient } from "@supabase/supabase-js";

import { NotFoundError, ValidationError } from "@/lib/api/errors";
import { appLogger as logger } from "@/lib/logger";
import { Database } from "@/types/supabase";

import {
  applyProductFilters, buildProductSelectString, ensureUniqueSlug, filterInStockProducts,
  filterLowStockProducts, filterOutOfStockProducts, filterProductsByBranch, generateSlug, validateSortColumn,
} from "./_helpers";
import { ProductInsert, ProductListParams, ProductListResponse, ProductServiceContext, ProductUpdate, ProductWithRelations } from "./types";

export class ProductsService {
  private supabase: SupabaseClient<Database>;
  constructor(supabase: SupabaseClient<Database>) { this.supabase = supabase; }

  async listProducts(params: ProductListParams, context: ProductServiceContext): Promise<ProductListResponse> {
    try {
      const { limit = 12, offset = 0, page = 1, search, branchId, organizationId, isSuperAdmin, sortBy = "created_at", sortOrder = "desc", lowStockOnly, inStock } = params;
      let query = this.supabase.from("products").select(buildProductSelectString(branchId || undefined), { count: "exact" });

      if (organizationId && !isSuperAdmin) {
        query = query.eq("organization_id", organizationId);
        if (branchId && !search) {
          try { query = query.or(`branch_id.is.null,branch_id.eq.${branchId}`); } catch { logger.warn("Error using .or() filter"); }
        }
      } else if (isSuperAdmin) {
        if (branchId) { try { query = query.or(`branch_id.is.null,branch_id.eq.${branchId}`); } catch {} }
        else if (organizationId) query = query.eq("organization_id", organizationId);
      }

      query = applyProductFilters(query, params);
      query = query.order(validateSortColumn(sortBy), { ascending: sortOrder === "asc" });
      query = query.range(offset, offset + limit - 1);

      const { data: products, error, count } = await query;
      if (error) { logger.error("Error fetching products", { error }); throw new Error(`Failed to fetch products: ${error.message}`); }

      let filteredProducts = products || [];
      if (search && branchId) filteredProducts = filterProductsByBranch(filteredProducts, branchId);
      if (lowStockOnly) filteredProducts = filterLowStockProducts(filteredProducts, branchId || null);
      if (inStock === "true") filteredProducts = filterInStockProducts(filteredProducts, branchId || null);
      else if (inStock === "false") filteredProducts = filterOutOfStockProducts(filteredProducts, branchId || null);

      const totalCount = count || 0;
      const totalPages = Math.ceil(totalCount / limit);
      return { products: filteredProducts as ProductWithRelations[], totalCount, currentPage: page, totalPages, hasNextPage: page < totalPages, hasPrevPage: page > 1 };
    } catch (error) { logger.error("Error in listProducts service", { error }); throw error; }
  }

  async getProductById(id: string, context: ProductServiceContext): Promise<ProductWithRelations> {
    try {
      let query = this.supabase.from("products").select(buildProductSelectString()).eq("id", id);
      if (context.organizationId && !context.isSuperAdmin) query = query.eq("organization_id", context.organizationId);
      const { data: product, error } = await query.single();
      if (error) { if (error.code === "PGRST116") throw new NotFoundError("Product not found"); throw new Error(`Failed to fetch product: ${error.message}`); }
      return product as ProductWithRelations;
    } catch (error) { logger.error("Error in getProductById service", { error, productId: id }); throw error; }
  }

  async createProduct(productData: ProductInsert, context: ProductServiceContext): Promise<ProductWithRelations> {
    try {
      if (!productData.name?.trim()) throw new ValidationError("Product name is required");
      if (productData.price === undefined || productData.price === null || isNaN(Number(productData.price))) throw new ValidationError("Valid price is required");
      if (context.organizationId) productData.organization_id = context.organizationId;
      if (!productData.slug?.trim()) productData.slug = generateSlug(productData.name);
      productData.slug = await ensureUniqueSlug(this.supabase, productData.slug);
      const { data: product, error } = await this.supabase.from("products").insert(productData).select(buildProductSelectString()).single();
      if (error) { logger.error("Error creating product", { error }); throw new Error(`Failed to create product: ${error.message}`); }
      return product as ProductWithRelations;
    } catch (error) { logger.error("Error in createProduct service", { error }); throw error; }
  }

  async updateProduct(id: string, productData: ProductUpdate, context: ProductServiceContext): Promise<ProductWithRelations> {
    try {
      const existing = await this.getProductById(id, context);
      if (productData.name && productData.name !== existing.name) {
        productData.slug = await ensureUniqueSlug(this.supabase, productData.slug?.trim() || generateSlug(productData.name), id);
      }
      const { data: product, error } = await this.supabase.from("products").update(productData).eq("id", id).select(buildProductSelectString()).single();
      if (error) { logger.error("Error updating product", { error, productId: id }); throw new Error(`Failed to update product: ${error.message}`); }
      return product as ProductWithRelations;
    } catch (error) { logger.error("Error in updateProduct service", { error, productId: id }); throw error; }
  }

  async deleteProduct(id: string, context: ProductServiceContext): Promise<void> {
    try {
      await this.getProductById(id, context);
      const { error } = await this.supabase.from("products").delete().eq("id", id);
      if (error) { logger.error("Error deleting product", { error, productId: id }); throw new Error(`Failed to delete product: ${error.message}`); }
    } catch (error) { logger.error("Error in deleteProduct service", { error, productId: id }); throw error; }
  }
}

/**
 * System Config Service — Business logic layer for system configuration operations.
 */
import type { SupabaseClient } from "@supabase/supabase-js";

import { mergeConfigsByScope } from "@/lib/admin/system-config-utils";
import { createConfigValueSchema } from "@/lib/api/validation/zod-schemas";
import { appLogger as logger } from "@/lib/logger";
import { createClient, createServiceRoleClient } from "@/utils/supabase/server";

import {
  fetchLegacyConfigs, getAdminAuth, isLegacySchemaError, parseConfigValue, resolveScope,
} from "./_helpers/systemConfigHelpers";

function applyScopeFilters(query: ReturnType<ReturnType<typeof createServiceRoleClient>["from"]>, publicOnly: boolean, category: string, orgId: string | null, branchId: string | null) {
  let q = query.order("category", { ascending: true }).order("config_key", { ascending: true });
  if (publicOnly) q = (q as unknown).eq("is_public", true);
  if (category && category !== "all") q = (q as unknown).eq("category", category);
  if (orgId != null) q = (q as unknown).eq("organization_id", orgId);
  else q = (q as unknown).is("organization_id", null);
  if (branchId != null) q = (q as unknown).eq("branch_id", branchId);
  else q = (q as unknown).is("branch_id", null);
  return q;
}

export async function getSystemConfigs(params: { category: string; publicOnly: boolean; branchId: string | null }, authClient?: SupabaseClient): Promise<{ configs: unknown[] }> {
  const { category, publicOnly, branchId } = params;
  const supabase = authClient ?? await createClient();
  const { orgId, isSuperAdmin } = await getAdminAuth(supabase);
  const hasServiceRole = !!process.env.SUPABASE_SERVICE_ROLE_KEY;
  const supabaseAdmin = hasServiceRole ? createServiceRoleClient() : supabase;

  let configs: unknown[] = [];
  let error: { message: string; code?: string } | null = null;

  if (isSuperAdmin && !branchId) {
    const res = await supabaseAdmin.from("system_config").select("*").is("organization_id", null).is("branch_id", null).order("category", { ascending: true }).order("config_key", { ascending: true });
    configs = (res.data ?? []) as unknown[];
    error = res.error as { message: string; code?: string } | null;
    if (error && isLegacySchemaError(error)) { configs = await fetchLegacyConfigs(supabaseAdmin, publicOnly, category); error = null; }
  } else if (isSuperAdmin && branchId && orgId) {
    const { data: branch } = await supabase.from("branches").select("id, organization_id").eq("id", branchId).maybeSingle();
    if (branch && branch.organization_id === orgId) {
      const [gRes, oRes, bRes] = await Promise.all([
        applyScopeFilters(supabaseAdmin.from("system_config").select("*"), publicOnly, category, null, null),
        applyScopeFilters(supabaseAdmin.from("system_config").select("*"), publicOnly, category, orgId, null),
        applyScopeFilters(supabaseAdmin.from("system_config").select("*"), publicOnly, category, orgId, branchId),
      ]);
      error = gRes.error ?? oRes.error ?? bRes.error ?? null;
      if (error && isLegacySchemaError(error)) { configs = await fetchLegacyConfigs(supabaseAdmin, publicOnly, category); error = null; }
      else if (!error) configs = mergeConfigsByScope([...(gRes.data || []), ...(oRes.data || []), ...(bRes.data || [])]);
    } else {
      const res = await supabaseAdmin.from("system_config").select("*").is("organization_id", null).is("branch_id", null).order("category", { ascending: true }).order("config_key", { ascending: true });
      configs = (res.data ?? []) as unknown[];
    }
  } else {
    const [gRes, oRes] = await Promise.all([
      applyScopeFilters(supabaseAdmin.from("system_config").select("*"), publicOnly, category, null, null),
      applyScopeFilters(supabaseAdmin.from("system_config").select("*"), publicOnly, category, orgId, null),
    ]);
    error = gRes.error ?? oRes.error ?? null;
    if (error && isLegacySchemaError(error)) { configs = await fetchLegacyConfigs(supabaseAdmin, publicOnly, category); error = null; }
    else if (!error) configs = mergeConfigsByScope([...(gRes.data || []), ...(oRes.data || [])]);
    if (branchId && orgId) {
      const bRes = await applyScopeFilters(supabaseAdmin.from("system_config").select("*"), publicOnly, category, orgId, branchId);
      if (!bRes.error) configs = mergeConfigsByScope([...(configs as unknown[]), ...(bRes.data || [])]);
    }
  }

  if ((!configs || configs.length === 0) && !error) {
    const res = await supabaseAdmin.from("system_config").select("*").order("category", { ascending: true }).order("config_key", { ascending: true });
    if (!res.error && res.data?.length) configs = res.data as unknown[];
  }

  if (error) { logger.error("Error fetching system config:", { error }); throw new Error("Failed to fetch system config"); }
  return { configs: (configs || []).map((c: unknown) => ({ ...c, config_value: parseConfigValue(c.config_value) })) };
}

export async function createSystemConfig(body: Record<string, unknown>, authClient?: SupabaseClient): Promise<{ config: Record<string, unknown> }> {
  const supabase = authClient ?? await createClient();
  const { user, orgId, isSuperAdmin } = await getAdminAuth(supabase);
  const { targetOrgId, targetBranchId } = await resolveScope(supabase, (body.branch_id as string | null) ?? null, orgId, isSuperAdmin);
  const { config_key, config_value, description, category = "general", is_public = false, is_sensitive = false, value_type = "string", validation_rules } = body;

  if (!config_key || config_value === undefined) throw new Error("Config key and value are required");
  if (!["string", "number", "boolean", "json", "array"].includes(value_type as string)) throw new Error("Invalid value type");

  const valueParse = createConfigValueSchema(value_type as string).safeParse(config_value);
  if (!valueParse.success) throw new Error(`config_value: ${valueParse.error.errors[0]?.message ?? "Valor inválido"}`);

  const insertPayload: Record<string, unknown> = { config_key, config_value: JSON.stringify(valueParse.data), description, category, is_public, is_sensitive, value_type, validation_rules: validation_rules ? JSON.stringify(validation_rules) : null, last_modified_by: user.id };
  if (targetOrgId != null) insertPayload.organization_id = targetOrgId;
  if (targetBranchId != null) insertPayload.branch_id = targetBranchId;

  const { data: config, error: configError } = await supabase.from("system_config").insert(insertPayload).select().single();
  if (configError) {
    if (isLegacySchemaError(configError)) {
      delete insertPayload.organization_id; delete insertPayload.branch_id;
      const retryRes = await supabase.from("system_config").insert(insertPayload).select().single();
      if (retryRes.error) { logger.error("Error creating system config:", { error: retryRes.error, config_key }); throw new Error("Failed to create system config"); }
      return { config: { ...retryRes.data!, config_value: parseConfigValue((retryRes.data as unknown)?.config_value) } };
    }
    logger.error("Error creating system config:", { error: configError, config_key }); throw new Error("Failed to create system config");
  }
  return { config: { ...config!, config_value: parseConfigValue((config as unknown).config_value) } };
}

export async function updateSystemConfigs(body: Record<string, unknown>, branchIdFromHeaders: string | null, authClient?: SupabaseClient): Promise<{ results: Array<Record<string, unknown>> }> {
  const supabase = authClient ?? await createClient();
  const { user, orgId, isSuperAdmin } = await getAdminAuth(supabase);
  const updates = body.updates as Array<Record<string, unknown>> | undefined;
  const branchId = (body.branch_id as string | null) ?? branchIdFromHeaders;
  if (!Array.isArray(updates)) throw new Error("Updates must be an array");
  const { targetOrgId, targetBranchId } = await resolveScope(supabase, branchId, orgId, isSuperAdmin);

  let useLegacySchema: boolean | null = null;
  const results: Array<Record<string, unknown>> = [];

  for (const update of updates) {
    const { config_key, config_value } = update;
    if (!config_key || config_value === undefined) { results.push({ config_key, error: "Key and value are required" }); continue; }
    try {
      let query = supabase.from("system_config").select("id, is_sensitive, category, value_type").eq("config_key", config_key);
      if (useLegacySchema !== true) {
        if (targetOrgId == null) query = (query as unknown).is("organization_id", null).is("branch_id", null);
        else {
          query = (query as unknown).eq("organization_id", targetOrgId);
          query = targetBranchId ? (query as unknown).eq("branch_id", targetBranchId) : (query as unknown).is("branch_id", null);
        }
      }
      let existingConfig: Record<string, unknown> | null = null;
      let checkError: { message: string; code?: string } | null = null;
      ({ data: existingConfig, error: checkError } = await (query as unknown).maybeSingle());

      if (checkError && isLegacySchemaError(checkError)) {
        useLegacySchema = true;
        const legacyRes = await supabase.from("system_config").select("id, is_sensitive, category, value_type").eq("config_key", config_key).maybeSingle();
        existingConfig = legacyRes.data; checkError = legacyRes.error;
      }
      if (checkError) { results.push({ config_key, error: `Failed to check config: ${checkError.message}` }); continue; }

      let valueTypeToUse = (existingConfig?.value_type as string) ?? "string";
      if (!existingConfig) {
        if (config_key === "signup_enabled" || config_key === "onboarding_stage_mode") valueTypeToUse = "boolean";
        else if ((config_key as string).startsWith("mercadopago_")) {
          const k = config_key as string;
          if (k.includes("test_mode") || k.includes("auto_return") || k.includes("binary_mode")) valueTypeToUse = "boolean";
          else if (k.includes("max_installments")) valueTypeToUse = "number";
          else if (k.includes("payment_methods")) valueTypeToUse = "array";
        }
      }
      const valueParse = createConfigValueSchema(valueTypeToUse).safeParse(config_value);
      if (!valueParse.success) { results.push({ config_key, error: `config_value: ${valueParse.error.errors[0]?.message ?? "Valor inválido"}` }); continue; }
      const validatedValue = valueParse.data;
      const isSensitive = (existingConfig?.is_sensitive as boolean) ?? ((config_key as string).includes("token") || (config_key as string).includes("secret") || (config_key as string).includes("key"));
      const dbClient = isSensitive ? createServiceRoleClient() : supabase;

      if (!existingConfig) {
        let category = "general"; let valueType = "string";
        let configIsSensitive = (config_key as string).includes("token") || (config_key as string).includes("secret") || (config_key as string).includes("key");
        if (config_key === "signup_enabled" || config_key === "onboarding_stage_mode") { category = "onboarding"; valueType = "boolean"; }
        else if ((config_key as string).startsWith("mercadopago_")) {
          category = "payments"; const k = config_key as string;
          if (k.includes("test_mode") || k.includes("auto_return") || k.includes("binary_mode")) { valueType = "boolean"; configIsSensitive = false; }
          else if (k.includes("max_installments")) { valueType = "number"; configIsSensitive = false; }
          else if (k.includes("payment_methods")) { valueType = "array"; configIsSensitive = false; }
          if (k.includes("test_access_token") || k.includes("test_public_key") || k.includes("test_webhook_secret")) configIsSensitive = true;
        }
        const ic = configIsSensitive ? createServiceRoleClient() : supabase;
        const payload: Record<string, unknown> = { config_key, config_value: JSON.stringify(validatedValue), category, value_type: valueType, is_sensitive: configIsSensitive, last_modified_by: user.id };
        if (!useLegacySchema) { if (targetOrgId != null) payload.organization_id = targetOrgId; if (targetBranchId != null) payload.branch_id = targetBranchId; }
        let newCfg: Record<string, unknown> | null = null; let ce: { message: string; code?: string } | null = null;
        ({ data: newCfg, error: ce } = await ic.from("system_config").insert(payload).select().single());
        if (ce && isLegacySchemaError(ce)) { useLegacySchema = true; delete payload.organization_id; delete payload.branch_id; const rr = await ic.from("system_config").insert(payload).select().single(); newCfg = rr.data; ce = rr.error; }
        if (ce || !newCfg) { results.push({ config_key, error: ce ? `Failed to create config: ${ce.message}` : "Failed to create config: no data returned" }); continue; }
        results.push({ config_key, success: true, config: { ...newCfg, config_value: parseConfigValue(newCfg.config_value) } }); continue;
      }
      const { data: updatedConfig, error: updateError } = await dbClient.from("system_config").update({ config_value: JSON.stringify(validatedValue), last_modified_by: user.id, updated_at: new Date().toISOString() }).eq("config_key", config_key).eq("id", existingConfig.id).select().maybeSingle();
      if (updateError) { results.push({ config_key, error: updateError.message }); continue; }
      if (!updatedConfig) { results.push({ config_key, error: "Config not found or could not be updated" }); continue; }
      results.push({ config_key, success: true, config: { ...updatedConfig, config_value: parseConfigValue(updatedConfig.config_value) } });
    } catch (error) { results.push({ config_key, error: `Unexpected error: ${error}` }); }
  }
  logger.info("Config updates completed", { successful: results.filter((r) => r.success).length, total: results.length });
  return { results };
}

export { isLegacySchemaError };

import { ValidationError } from "./errors";

/**
 * Regla de validación para un campo
 *
 * @template T - Tipo de los valores permitidos en el enum
 *
 * @property {boolean} [required] - Si el campo es requerido
 * @property {'string' | 'number' | 'boolean' | 'object' | 'array' | 'email' | 'url'} [type] - Tipo de dato esperado
 * @property {number} [minLength] - Longitud mínima (para strings)
 * @property {number} [maxLength] - Longitud máxima (para strings)
 * @property {number} [min] - Valor mínimo (para números)
 * @property {number} [max] - Valor máximo (para números)
 * @property {RegExp} [pattern] - Patrón regex para validación
 * @property {T[]} [enum] - Lista de valores permitidos
 * @property {(value: any) => boolean | string} [custom] - Función de validación personalizada
 *
 * @example
 * const rule: ValidationRule = {
 *   required: true,
 *   type: 'email',
 *   minLength: 5
 * }
 */
export type ValidationRule<T = unknown> = {
  required?: boolean;
  type?: "string" | "number" | "boolean" | "object" | "array" | "email" | "url";
  minLength?: number;
  maxLength?: number;
  min?: number;
  max?: number;
  pattern?: RegExp;
  enum?: T[];
  custom?: (value: unknown) => boolean | string;
};

/**
 * Esquema de validación que mapea nombres de campos a sus reglas
 *
 * @example
 * const schema: ValidationSchema = {
 *   email: { required: true, type: 'email' },
 *   age: { type: 'number', min: 0, max: 120 }
 * }
 */
export type ValidationSchema = {
  [key: string]: ValidationRule;
};

// Email validation regex
const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

// URL validation regex
const URL_REGEX = /^https?:\/\/.+\..+$/;

// Argentina phone number regex
const ARGENTINA_PHONE_REGEX = /^(\+54)?[0-9]{10,11}$/;

/**
 * Valida un campo individual según una regla de validación
 *
 * @param fieldName - Nombre del campo a validar (para mensajes de error)
 * @param value - Valor a validar
 * @param rule - Regla de validación a aplicar
 * @returns Array de mensajes de error (vacío si no hay errores)
 *
 * @internal
 * Esta función es usada internamente por validateRequestBody y validateQueryParams
 */
function validateField(
  fieldName: string,
  value: unknown,
  rule: ValidationRule,
): string[] {
  const errors: string[] = [];

  // Required validation
  if (
    rule.required &&
    (value === undefined || value === null || value === "")
  ) {
    errors.push(`${fieldName} is required`);
    return errors; // Don't continue if required field is missing
  }

  // Skip other validations if field is not provided and not required
  if (value === undefined || value === null || value === "") {
    return errors;
  }

  // Type validation
  if (rule.type) {
    switch (rule.type) {
      case "string":
        if (typeof value !== "string") {
          errors.push(`${fieldName} must be a string`);
        }
        break;
      case "number":
        if (typeof value !== "number" && !Number.isFinite(Number(value))) {
          errors.push(`${fieldName} must be a number`);
        }
        break;
      case "boolean":
        if (typeof value !== "boolean") {
          errors.push(`${fieldName} must be a boolean`);
        }
        break;
      case "object":
        if (typeof value !== "object" || Array.isArray(value)) {
          errors.push(`${fieldName} must be an object`);
        }
        break;
      case "array":
        if (!Array.isArray(value)) {
          errors.push(`${fieldName} must be an array`);
        }
        break;
      case "email":
        if (typeof value === "string" && !EMAIL_REGEX.test(value)) {
          errors.push(`${fieldName} must be a valid email address`);
        }
        break;
      case "url":
        if (typeof value === "string" && !URL_REGEX.test(value)) {
          errors.push(`${fieldName} must be a valid URL`);
        }
        break;
    }
  }

  // String validations
  if (typeof value === "string") {
    if (rule.minLength && value.length < rule.minLength) {
      errors.push(`${fieldName} must be at least ${rule.minLength} characters`);
    }
    if (rule.maxLength && value.length > rule.maxLength) {
      errors.push(
        `${fieldName} must be no more than ${rule.maxLength} characters`,
      );
    }
  }

  // Number validations
  if (typeof value === "number") {
    if (rule.min !== undefined && value < rule.min) {
      errors.push(`${fieldName} must be at least ${rule.min}`);
    }
    if (rule.max !== undefined && value > rule.max) {
      errors.push(`${fieldName} must be no more than ${rule.max}`);
    }
  }

  // Pattern validation
  if (rule.pattern && typeof value === "string" && !rule.pattern.test(value)) {
    errors.push(`${fieldName} format is invalid`);
  }

  // Enum validation
  if (rule.enum && !rule.enum.includes(value)) {
    errors.push(`${fieldName} must be one of: ${rule.enum.join(", ")}`);
  }

  // Custom validation
  if (rule.custom) {
    const result = rule.custom(value);
    if (result !== true) {
      errors.push(
        typeof result === "string" ? result : `${fieldName} is invalid`,
      );
    }
  }

  return errors;
}

/**
 * Valida el cuerpo de una petición HTTP contra un esquema de validación
 *
 * @param body - Objeto con los datos a validar (típicamente de request.json())
 * @param schema - Esquema de validación que define las reglas para cada campo
 * @throws {ValidationError} Si la validación falla, lanza un error con los detalles
 *
 * @example
 * ```typescript
 * const schema: ValidationSchema = {
 *   email: { required: true, type: 'email' },
 *   password: { required: true, type: 'string', minLength: 8 }
 * }
 *
 * try {
 *   validateRequestBody(requestBody, schema)
 *   // Validación exitosa
 * } catch (error) {
 *   if (error instanceof ValidationError) {
 *     // Manejar error de validación
 *   }
 * }
 * ```
 */
export function validateRequestBody(
  body: unknown,
  schema: ValidationSchema,
): void {
  const errors: string[] = [];

  for (const [fieldName, rule] of Object.entries(schema)) {
    const fieldErrors = validateField(fieldName, body?.[fieldName], rule);
    errors.push(...fieldErrors);
  }

  if (errors.length > 0) {
    throw new ValidationError(`Validation failed: ${errors.join(", ")}`);
  }
}

/**
 * Valida los parámetros de consulta (query parameters) de una URL contra un esquema
 *
 * Convierte automáticamente strings a números o booleanos según el tipo especificado
 * en el esquema.
 *
 * @param searchParams - URLSearchParams de la petición
 * @param schema - Esquema de validación que define las reglas para cada parámetro
 * @throws {ValidationError} Si la validación falla, lanza un error con los detalles
 *
 * @example
 * ```typescript
 * const schema: ValidationSchema = {
 *   page: { type: 'number', min: 1 },
 *   limit: { type: 'number', min: 1, max: 100 },
 *   active: { type: 'boolean' }
 * }
 *
 * const searchParams = new URL(request.url).searchParams
 * validateQueryParams(searchParams, schema)
 * ```
 */
export function validateQueryParams(
  searchParams: URLSearchParams,
  schema: ValidationSchema,
): void {
  const errors: string[] = [];

  for (const [fieldName, rule] of Object.entries(schema)) {
    let value: unknown = searchParams.get(fieldName);

    // Convert string values to appropriate types
    if (value !== null && rule.type) {
      switch (rule.type) {
        case "number":
          value = Number(value);
          break;
        case "boolean":
          value = value === "true";
          break;
      }
    }

    const fieldErrors = validateField(fieldName, value, rule);
    errors.push(...fieldErrors);
  }

  if (errors.length > 0) {
    throw new ValidationError(
      `Query parameter validation failed: ${errors.join(", ")}`,
    );
  }
}

/**
 * Esquemas de validación comunes reutilizables en toda la aplicación
 *
 * Estos esquemas pueden ser usados directamente o extendidos para casos específicos
 *
 * @example
 * ```typescript
 * // Usar directamente
 * validateRequestBody(body, commonSchemas.userLogin)
 *
 * // Extender para casos específicos
 * const customSchema = {
 *   ...commonSchemas.userRegistration,
 *   phone: { required: true, type: 'string', pattern: PHONE_REGEX }
 * }
 * ```
 */
export const commonSchemas = {
  // User registration
  userRegistration: {
    email: { required: true, type: "email" as const },
    password: { required: true, type: "string" as const, minLength: 8 },
    firstName: {
      required: true,
      type: "string" as const,
      minLength: 1,
      maxLength: 50,
    },
    lastName: {
      required: true,
      type: "string" as const,
      minLength: 1,
      maxLength: 50,
    },
    phone: {
      type: "string" as const,
      pattern: ARGENTINA_PHONE_REGEX,
      custom: (value: string) =>
        !value ||
        ARGENTINA_PHONE_REGEX.test(value) ||
        "Phone number must be a valid Argentina number",
    },
  },

  // User login
  userLogin: {
    email: { required: true, type: "email" as const },
    password: { required: true, type: "string" as const, minLength: 1 },
  },

  // Contact form
  contactForm: {
    name: {
      required: true,
      type: "string" as const,
      minLength: 1,
      maxLength: 100,
    },
    email: { required: true, type: "email" as const },
    subject: {
      required: true,
      type: "string" as const,
      minLength: 1,
      maxLength: 200,
    },
    message: {
      required: true,
      type: "string" as const,
      minLength: 10,
      maxLength: 1000,
    },
  },

  // Newsletter subscription
  newsletter: {
    email: { required: true, type: "email" as const },
    name: { type: "string" as const, maxLength: 100 },
  },

  // Checkout request
  checkout: {
    items: { required: true, type: "array" as const },
    payer_info: { required: true, type: "object" as const },
  },

  // Pagination
  pagination: {
    page: { type: "number" as const, min: 1 },
    limit: { type: "number" as const, min: 1, max: 100 },
    sort: { type: "string" as const, enum: ["asc", "desc"] },
  },
};

/**
 * Sanitiza datos de entrada eliminando espacios en blanco y normalizando strings
 *
 * Esta función recursivamente sanitiza strings, arrays y objetos:
 * - Strings: elimina espacios al inicio y final (trim)
 * - Arrays: sanitiza cada elemento
 * - Objetos: sanitiza cada propiedad
 *
 * @param data - Datos a sanitizar (puede ser string, array, objeto o primitivo)
 * @returns Datos sanitizados con el mismo tipo y estructura
 *
 * @example
 * ```typescript
 * sanitizeInput("  hello  ") // "hello"
 * sanitizeInput({ name: "  John  ", age: 30 }) // { name: "John", age: 30 }
 * sanitizeInput(["  a  ", "  b  "]) // ["a", "b"]
 * ```
 */
export function sanitizeInput(data: unknown): unknown {
  if (typeof data === "string") {
    return data.trim();
  }

  if (Array.isArray(data)) {
    return data.map(sanitizeInput);
  }

  if (data && typeof data === "object") {
    const sanitized: unknown = {};
    for (const [key, value] of Object.entries(data)) {
      sanitized[key] = sanitizeInput(value);
    }
    return sanitized;
  }

  return data;
}

/**
 * Parsea y valida el cuerpo de una petición HTTP en un solo paso
 *
 * Esta función combina el parsing del JSON, sanitización y validación.
 * Útil para API routes de Next.js.
 *
 * @param request - Objeto Request de Next.js
 * @param schema - Esquema de validación a aplicar
 * @returns Promise que resuelve con el cuerpo parseado y validado
 * @throws {ValidationError} Si el JSON es inválido o la validación falla
 *
 * @example
 * ```typescript
 * // En un API route
 * export async function POST(request: Request) {
 *   const body = await parseAndValidateBody(request, {
 *     email: { required: true, type: 'email' },
 *     name: { required: true, type: 'string', minLength: 2 }
 *   })
 *
 *   // body está validado y sanitizado
 *   // ...
 * }
 * ```
 */
export async function parseAndValidateBody(
  request: Request,
  schema: ValidationSchema,
): Promise<unknown> {
  try {
    const body = await request.json();
    const sanitizedBody = sanitizeInput(body);
    validateRequestBody(sanitizedBody, schema);
    return sanitizedBody;
  } catch (error) {
    if (error instanceof SyntaxError) {
      throw new ValidationError("Invalid JSON in request body");
    }
    throw error;
  }
}

import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";

import { ValidationError } from "../errors";
export { ValidationError };
import { logger } from "@/lib/logger";

/**
 * Helpers para usar Zod en rutas API de Next.js
 *
 * Este módulo proporciona funciones convenientes para validar
 * request bodies, query parameters y path parameters usando Zod.
 * Todas las funciones incluyen logging automático de errores y
 * manejo consistente de excepciones.
 *
 * @module lib/api/validation/zod-helpers
 *
 * @example
 * ```typescript
 * import { parseAndValidateBody } from '@/lib/api/validation/zod-helpers'
 * import { createProductSchema } from '@/lib/api/validation/zod-schemas'
 *
 * export async function POST(request: NextRequest) {
 *   const data = await parseAndValidateBody(request, createProductSchema)
 *   // data está validado y tipado correctamente
 * }
 * ```
 */

/**
 * Valida un objeto usando un schema Zod (para cuando el body ya fue parseado)
 *
 * Esta función es útil cuando ya tienes el objeto parseado y solo necesitas validarlo.
 * Para validar directamente desde un Request, usa `parseAndValidateBody`.
 *
 * @template T - Tipo del schema Zod (inferido automáticamente)
 * @param body - Objeto ya parseado a validar
 * @param schema - Schema Zod para validar el body
 * @returns Datos validados y parseados con el tipo inferido del schema
 * @throws {ValidationError} Si la validación falla, con detalles de los errores
 *
 * @example
 * ```typescript
 * const body = await request.json()
 * const validated = validateBody(body, createProductSchema)
 * // validated tiene el tipo correcto según createProductSchema
 * ```
 *
 * @see {@link parseAndValidateBody} Para validar directamente desde un Request
 */
export function validateBody<T extends z.ZodTypeAny>(
  body: unknown,
  schema: T,
): z.infer<T> {
  try {
    const validated = schema.parse(body);
    return validated;
  } catch (error) {
    if (error instanceof z.ZodError) {
      const errors = error.errors.map((err) => ({
        field: err.path.join("."),
        message: err.message,
      }));

      logger.warn(
        {
          errors: errors.map((e) => `${e.field}: ${e.message}`).join(", "),
          body: JSON.stringify(body),
        },
        "Validation failed",
      );

      throw new ValidationError(
        `Validation failed: ${errors.map((e) => `${e.field}: ${e.message}`).join(", ")}`,
        errors,
      );
    }

    // Log unexpected errors
    if (error instanceof Error) {
      logger.error(error, "Unexpected error in validateBody", {
        body: JSON.stringify(body),
      });
    } else {
      logger.error(
        new Error(String(error)),
        "Unexpected error in validateBody",
        {
          body: JSON.stringify(body),
        },
      );
    }

    throw error;
  }
}

/**
 * Valida y parsea el body de una request usando un schema Zod
 *
 * Esta es la función más común para validar request bodies en API routes.
 * Combina el parsing del JSON y la validación en un solo paso.
 *
 * @template T - Tipo del schema Zod (inferido automáticamente)
 * @param request - Objeto NextRequest de Next.js
 * @param schema - Schema Zod para validar el body
 * @returns Promise que resuelve con los datos validados y parseados
 * @throws {ValidationError} Si el JSON es inválido o la validación falla
 *
 * @example
 * ```typescript
 * export async function POST(request: NextRequest) {
 *   const data = await parseAndValidateBody(request, createProductSchema)
 *   // data está validado y tipado
 *   await createProduct(data)
 * }
 * ```
 */
export async function parseAndValidateBody<T extends z.ZodTypeAny>(
  request: NextRequest,
  schema: T,
): Promise<z.infer<T>> {
  try {
    const body = await request.json();
    return validateBody(body, schema);
  } catch (error) {
    if (error instanceof ValidationError) {
      throw error;
    }

    if (error instanceof SyntaxError) {
      throw new ValidationError("Invalid JSON in request body");
    }

    throw error;
  }
}

/**
 * Valida query parameters usando un schema Zod
 *
 * Convierte automáticamente los query parameters de strings a sus tipos apropiados
 * según el schema (números, booleanos, etc.).
 *
 * @template T - Tipo del schema Zod (inferido automáticamente)
 * @param request - Objeto NextRequest de Next.js
 * @param schema - Schema Zod para validar los query parameters
 * @returns Query parameters validados y parseados con tipos correctos
 * @throws {ValidationError} Si la validación falla
 *
 * @example
 * ```typescript
 * const query = parseAndValidateQuery(request, z.object({
 *   page: z.coerce.number().min(1),
 *   limit: z.coerce.number().min(1).max(100),
 *   search: z.string().optional()
 * }))
 * // query.page y query.limit son números, no strings
 * ```
 */
export function parseAndValidateQuery<T extends z.ZodTypeAny>(
  request: NextRequest,
  schema: T,
): z.infer<T> {
  try {
    const searchParams = request.nextUrl.searchParams;
    const params: Record<string, string | string[]> = {};

    // Convertir URLSearchParams a objeto
    searchParams.forEach((value, key) => {
      if (params[key]) {
        // Si ya existe, convertir a array
        if (Array.isArray(params[key])) {
          (params[key] as string[]).push(value);
        } else {
          params[key] = [params[key] as string, value];
        }
      } else {
        params[key] = value;
      }
    });

    const validated = schema.parse(params);
    return validated;
  } catch (error) {
    if (error instanceof z.ZodError) {
      const errors = error.errors.map((err) => ({
        field: err.path.join("."),
        message: err.message,
      }));

      logger.warn(
        {
          errors: errors.map((e) => `${e.field}: ${e.message}`).join(", "),
        },
        "Query validation failed",
      );

      throw new ValidationError(
        `Query validation failed: ${errors.map((e) => `${e.field}: ${e.message}`).join(", ")}`,
        errors,
      );
    }

    throw error;
  }
}

/**
 * Valida path parameters usando un schema Zod
 *
 * Útil para validar parámetros de ruta dinámicos (ej: `/api/products/[id]`).
 *
 * @template T - Tipo del schema Zod (inferido automáticamente)
 * @param params - Objeto con los path parameters (típicamente de `params` en route handlers)
 * @param schema - Schema Zod para validar los path parameters
 * @returns Path parameters validados y parseados
 * @throws {ValidationError} Si la validación falla
 *
 * @example
 * ```typescript
 * export async function GET(
 *   request: NextRequest,
 *   { params }: { params: { id: string } }
 * ) {
 *   const { id } = parseAndValidateParams(params, z.object({
 *     id: z.string().uuid()
 *   }))
 *   // id está validado como UUID
 * }
 * ```
 */
export function parseAndValidateParams<T extends z.ZodTypeAny>(
  params: Record<string, string | string[] | undefined>,
  schema: T,
): z.infer<T> {
  try {
    const validated = schema.parse(params);
    return validated;
  } catch (error) {
    if (error instanceof z.ZodError) {
      const errors = error.errors.map((err) => ({
        field: err.path.join("."),
        message: err.message,
      }));

      logger.warn(
        {
          errors: errors.map((e) => `${e.field}: ${e.message}`).join(", "),
        },
        "Path params validation failed",
      );

      throw new ValidationError(
        `Path params validation failed: ${errors.map((e) => `${e.field}: ${e.message}`).join(", ")}`,
        errors,
      );
    }

    throw error;
  }
}

/**
 * Middleware wrapper para manejar errores de validación automáticamente
 *
 * Envuelve un handler de API route con validación automática del body.
 * Si la validación falla, retorna una respuesta 400 con los errores.
 * Si hay un error inesperado, retorna 500.
 *
 * @template T - Tipo del schema Zod
 * @param schema - Schema Zod para validar el body del request
 * @param handler - Función handler que recibe los datos validados y el request
 * @returns Handler envuelto que maneja validación y errores automáticamente
 *
 * @example
 * ```typescript
 * export const POST = withValidation(
 *   createProductSchema,
 *   async (data, request) => {
 *     // data está validado y tipado
 *     const product = await createProduct(data)
 *     return NextResponse.json(product)
 *   }
 * )
 * ```
 */
export function withValidation<T extends z.ZodTypeAny>(
  schema: T,
  handler: (
    validatedData: z.infer<T>,
    request: NextRequest,
  ) => Promise<NextResponse>,
) {
  return async (request: NextRequest): Promise<NextResponse> => {
    try {
      const validatedData = await parseAndValidateBody(request, schema);
      return await handler(validatedData, request);
    } catch (error) {
      if (error instanceof ValidationError) {
        return NextResponse.json(
          {
            error: error.message,
            details: error.details || undefined,
          },
          { status: 400 },
        );
      }

      if (error instanceof Error) {
        logger.error(error, "Unexpected error in validation handler");
      } else {
        logger.error(
          new Error(String(error)),
          "Unexpected error in validation handler",
        );
      }
      return NextResponse.json(
        { error: "Internal server error" },
        { status: 500 },
      );
    }
  };
}

/**
 * Helper para crear respuestas de error de validación consistentes
 *
 * Convierte errores de validación (ValidationError o ZodError) en respuestas
 * HTTP 400 con formato consistente.
 *
 * @param error - Error de validación (ValidationError o ZodError)
 * @returns NextResponse con status 400 y detalles del error
 *
 * @example
 * ```typescript
 * try {
 *   const data = await parseAndValidateBody(request, schema)
 * } catch (error) {
 *   return validationErrorResponse(error)
 * }
 * ```
 */
export function validationErrorResponse(
  error: ValidationError | z.ZodError,
): NextResponse {
  if (error instanceof ValidationError) {
    return NextResponse.json(
      {
        error: error.message,
        details: error.details || undefined,
      },
      { status: 400 },
    );
  }

  if (error instanceof z.ZodError) {
    const errors = error.errors.map((err) => ({
      field: err.path.join("."),
      message: err.message,
    }));

    return NextResponse.json(
      {
        error: "Validation failed",
        details: errors,
      },
      { status: 400 },
    );
  }

  return NextResponse.json({ error: "Validation error" }, { status: 400 });
}

