export class BackupService {
  static async generateBackup(
    organizationId: string,
    userIdOrEmail?: string,
    branchId?: string,
  ): Promise<BackupData> {
    const backupStartTime = new Date();
    const backupId = `backup_${organizationId}_${backupStartTime.toISOString().replace(/[:.]/g, "-")}`;
    const supabaseService = createServiceRoleClient();

    const backupData: BackupData = {
      backup_id: backupId,
      created_at: backupStartTime.toISOString(),
      created_by: userIdOrEmail || "system",
      organization_id: organizationId,
      tables: {},
      version: "1.5",
    };

    const idsCache: Record<string, string[]> = {};
    logger.info("Iniciando backup profundo y relacional", {
      organizationId,
      backupId,
    });

    for (const config of TABLES_CONFIG) {
      try {
        const query = supabaseService.from(config.name).select("*");

        if (config.isGlobal) {
          // Shared tables: backup all rows
          const { data, error } = await query;
          if (error) throw error;
          backupData.tables[config.name] = {
            data: data || [],
            record_count: data?.length || 0,
          };
          if (data && data.length > 0)
            idsCache[config.name] = data
              .map((row: unknown) => row.id ?? row[config.filter])
              .filter(Boolean);
        } else if (config.anchor) {
          const anchorIds = idsCache[config.anchor] || [];
          if (anchorIds.length === 0) {
            backupData.tables[config.name] = {
              data: [],
              record_count: 0,
              skipped: true,
            };
            continue;
          }
          // Dividir anchorIds si son demasiados (PostgREST limit)
          const chunks = [];
          for (let i = 0; i < anchorIds.length; i += 500) {
            chunks.push(anchorIds.slice(i, i + 500));
          }

          let allData: unknown[] = [];
          for (const chunk of chunks) {
            const { data, error } = await supabaseService
              .from(config.name)
              .select("*")
              .in(config.filter, chunk);
            if (error) throw error;
            if (data) allData = [...allData, ...data];
          }

          backupData.tables[config.name] = {
            data: allData,
            record_count: allData.length,
          };
          if (allData.length > 0)
            idsCache[config.name] = allData
              .map((row: unknown) => row.id)
              .filter(Boolean);
        } else {
          let q = query;
          if (config.name === "branches" && branchId) {
            q = q.eq(config.filter, organizationId).eq("id", branchId);
          } else {
            q = q.eq(config.filter, organizationId);
          }
          const { data, error } = await q;
          if (error) throw error;
          backupData.tables[config.name] = {
            data: data || [],
            record_count: data?.length || 0,
          };
          if (data && data.length > 0)
            idsCache[config.name] = data
              .map((row: unknown) => row.id)
              .filter(Boolean);
        }
      } catch (err: unknown) {
        logger.error(`Error en backup de tabla ${config.name}`, {
          error: err.message,
          organizationId,
        });
        backupData.tables[config.name] = {
          data: [],
          record_count: 0,
          error: err.message,
        };
      }
    }

    return backupData;
  }

  static async restoreBackup(
    organizationId: string,
    backupData: BackupData,
  ): Promise<RestoreResult> {
    const restoreStartTime = new Date();
    const supabaseService = createServiceRoleClient();
    const restoreResults: Record<string, unknown> = {};
    let totalRestored = 0;
    let totalErrors = 0;

    if (backupData.organization_id !== organizationId) {
      throw new Error(
        `Seguridad: El backup no pertenece a esta organización (${organizationId})`,
      );
    }

    // --- PASO 1: LIMPIEZA ESTRATEGICA ---
    // Limpiamos las tablas base. El CASCADE se encarga de la mayoria de las dependencias.
    // Skip: anchor tables (cleaned via cascade) and global tables (shared, no delete)
    for (const config of [...TABLES_CONFIG].reverse()) {
      if (config.anchor || config.isGlobal) continue;

      const { error: deleteError } = await supabaseService
        .from(config.name)
        .delete()
        .eq(config.filter, organizationId);

      if (deleteError) {
        logger.warn(`Limpieza fallida o restringida en ${config.name}`, {
          deleteError,
        });
      }
    }

    // --- PASO 2: RESTAURACION EN ORDEN ---
    for (const config of TABLES_CONFIG) {
      const tableEntry = backupData.tables[config.name];
      const tableData = tableEntry?.data;

      if (!tableData || tableData.length === 0) {
        restoreResults[config.name] = { status: "skipped" };
        continue;
      }

      try {
        const batchSize = 100;
        let inserted = 0;
        let insertErrors = 0;

        for (let i = 0; i < tableData.length; i += batchSize) {
          const batch = tableData.slice(i, i + batchSize).map((row) => {
            if (config.isGlobal || config.anchor) return row;
            return { ...row, [config.filter]: organizationId };
          });

          const { error: upsertError } = await supabaseService
            .from(config.name)
            .upsert(batch, { onConflict: "id" });

          if (upsertError) {
            logger.error(`Error en upsert de ${config.name}`, { upsertError });
            insertErrors += batch.length;
          } else {
            inserted += batch.length;
          }
        }

        restoreResults[config.name] = {
          status: insertErrors > 0 ? "partial" : "success",
          restored: inserted,
          errors: insertErrors,
        };
        totalRestored += inserted;
        totalErrors += insertErrors;
      } catch (e: unknown) {
        logger.error(`Excepcion en restauracion de ${config.name}`, {
          error: e.message,
        });
        restoreResults[config.name] = { status: "error", message: e.message };
        totalErrors++;
      }
    }

    const duration = (Date.now() - restoreStartTime.getTime()) / 1000;
    return {
      success: totalErrors === 0,
      message: `Restauración completa: ${totalRestored} registros.`,
      tables_restored: Object.keys(restoreResults).length,
      total_records_restored: totalRestored,
      errors: totalErrors,
      restore_results: restoreResults,
      duration_seconds: duration,
    };
  }
}

/**
 * Billing Factory
 *
 * Factory Pattern para crear el adaptador de facturación correcto
 * según la configuración del sistema.
 */

import { BillingAdapter } from "./adapters/BillingAdapter";
import { InternalBilling } from "./adapters/InternalBilling";
// import { SIIBilling } from './adapters/SIIBilling'; // Futuro: Fase 2

export interface BillingConfig {
  useFiscalBilling: boolean;
  siiCredentials?: {
    apiKey: string;
    apiUrl: string;
    // ... otros credenciales SII
  };
}

export class BillingFactory {
  /**
   * Crea el adaptador de facturación según la configuración
   */
  static createAdapter(config: BillingConfig): BillingAdapter {
    if (config.useFiscalBilling && config.siiCredentials) {
      // TODO: Implementar SIIBilling en Fase 2 (Futuro)
      // return new SIIBilling(config.siiCredentials);
      throw new Error(
        "Facturación fiscal (SII) no implementada aún. Use facturación interna.",
      );
    }

    // Por defecto, usar facturación interna (Shadow Billing)
    return new InternalBilling();
  }

  /**
   * Obtiene la configuración de facturación desde la base de datos
   * Por ahora siempre retorna facturación interna
   */
  static async getBillingConfig(branchId: string): Promise<BillingConfig> {
    // TODO: Leer configuración desde organization_settings o branch_settings
    // Por ahora, siempre usar facturación interna
    return {
      useFiscalBilling: false,
    };
  }
}

/**
 * Internal Billing Adapter (Shadow Billing)
 *
 * Implementación para facturación interna (Fase 1).
 * Genera folios internos y PDFs simples sin conexión al SII.
 */

import type { SupabaseClient } from "@supabase/supabase-js";

import { appLogger as logger } from "@/lib/logger";
import { createServiceRoleClient } from "@/utils/supabase/server";

import {
  BillingAdapter,
  BillingResult,
  DocumentStatus,
  Order,
} from "./BillingAdapter";

export class InternalBilling implements BillingAdapter {
  private supabase: SupabaseClient;

  constructor(supabase?: SupabaseClient) {
    this.supabase = supabase ?? createServiceRoleClient();
  }

  /**
   * Emite un documento interno (ticket/comprobante) o boleta/factura
   */
  async emitDocument(order: Order): Promise<BillingResult> {
    try {
      // Determine document type from order
      const documentType =
        (order as unknown).sii_invoice_type === "factura"
          ? "factura"
          : (order as unknown).sii_invoice_type === "boleta"
            ? "boleta"
            : "internal_ticket";

      // 1. Generar folio interno (secuencial por sucursal y tipo)
      const folio = await this.generateInternalFolio(
        order.branch_id,
        documentType,
      );

      // 2. Get billing settings for customization
      const { data: billingSettings } = await this.supabase
        .from("billing_settings")
        .select("*")
        .eq("branch_id", order.branch_id)
        .single();

      // 3. Create billing document record
      const { data: billingDoc, error: docError } = await this.supabase
        .from("billing_documents")
        .insert({
          document_type: documentType,
          folio: folio,
          order_id: order.id,
          branch_id: order.branch_id,
          purchase_order_reference: (order as unknown).oc_number ?? null,
          customer_id: order.customer_id || null,
          customer_name:
            order.customer?.first_name && order.customer?.last_name
              ? `${order.customer.first_name} ${order.customer.last_name}`
              : order.customer?.business_name || null,
          customer_rut: order.customer?.rut || null,
          customer_email: order.customer?.email || null,
          status: "emitted",
          subtotal: order.subtotal,
          tax_amount: order.tax_amount,
          discount_amount: order.discount_amount || 0,
          total_amount: order.total_amount,
          currency: "CLP",
          pdf_url: `/api/admin/billing/documents/${folio}/pdf`,
          logo_url: billingSettings?.logo_url || null,
          custom_header_text: billingSettings?.header_text || null,
          custom_footer_text: billingSettings?.footer_text || null,
          emitted_at: new Date().toISOString(),
        })
        .select()
        .single();

      if (docError) {
        logger.error("Error creating billing document", docError);
        throw new Error(
          `Failed to create billing document: ${docError.message}`,
        );
      }

      // 4. Create document items
      if (order.items && order.items.length > 0) {
        const documentItems = order.items.map((item, index) => ({
          billing_document_id: billingDoc.id,
          line_number: index + 1,
          product_id: item.product_id || null,
          product_name: item.product_name,
          product_sku: item.sku || null,
          quantity: item.quantity,
          unit_price: item.unit_price,
          discount_amount: 0,
          tax_amount: 0, // Calculate if needed
          total_price: item.total_price,
          description: item.product_name,
        }));

        const { error: itemsError } = await this.supabase
          .from("billing_document_items")
          .insert(documentItems);

        if (itemsError) {
          logger.error("Error creating document items", itemsError);
          // Don't fail, but log the error
        }
      }

      // 5. Update order with document info (for backward compatibility)
      await this.saveDocument(order.id, {
        document_type:
          documentType === "internal_ticket"
            ? "internal_ticket"
            : documentType === "boleta"
              ? "boleta_electronica"
              : "factura_electronica",
        internal_folio: folio,
        pdf_url: `/api/admin/billing/documents/${folio}/pdf`,
      });

      logger.info(
        `Billing document emitted: ${folio} (${documentType}) for order ${order.id}`,
      );

      return {
        folio,
        pdfUrl: `/api/admin/billing/documents/${folio}/pdf`,
        type: "internal",
        timestamp: new Date(),
      };
    } catch (error) {
      logger.error("Error emitting billing document", error);
      throw error;
    }
  }

  /**
   * Genera un folio interno secuencial por sucursal y tipo de documento
   * Usa la función de base de datos para consistencia
   */
  private async generateInternalFolio(
    branchId: string,
    documentType: string,
  ): Promise<string> {
    try {
      const { data: folio, error } = await this.supabase.rpc(
        "generate_billing_folio",
        {
          p_branch_id: branchId,
          p_document_type: documentType,
        },
      );

      if (error || !folio) {
        logger.error("Error generating folio via RPC", error);
        // Fallback: generate manually
        return this.generateFolioFallback(branchId, documentType);
      }

      return folio;
    } catch (error) {
      logger.error("Error generating internal folio", error);
      return this.generateFolioFallback(branchId, documentType);
    }
  }

  /**
   * Fallback method to generate folio if RPC fails
   */
  private async generateFolioFallback(
    branchId: string,
    documentType: string,
  ): Promise<string> {
    const prefix =
      documentType === "boleta"
        ? "BOL"
        : documentType === "factura"
          ? "FAC"
          : "TKT";

    const { data: lastDoc } = await this.supabase
      .from("billing_documents")
      .select("folio")
      .eq("branch_id", branchId)
      .eq("document_type", documentType)
      .like("folio", `${prefix}-%`)
      .order("created_at", { ascending: false })
      .limit(1)
      .single();

    let nextNumber = 1;
    if (lastDoc?.folio) {
      const match = lastDoc.folio.match(/\d+$/);
      if (match) {
        nextNumber = parseInt(match[0], 10) + 1;
      }
    }

    return `${prefix}-${String(nextNumber).padStart(6, "0")}`;
  }

  // PDF generation is now handled by the API endpoint
  // This method is kept for backward compatibility but is no longer used

  /**
   * Guarda la información del documento en la tabla orders
   */
  private async saveDocument(
    orderId: string,
    documentData: {
      document_type: string;
      internal_folio: string;
      pdf_url: string;
    },
  ): Promise<void> {
    const { error } = await this.supabase
      .from("orders")
      .update({
        document_type: documentData.document_type,
        internal_folio: documentData.internal_folio,
        pdf_url: documentData.pdf_url,
        updated_at: new Date().toISOString(),
      })
      .eq("id", orderId);

    if (error) {
      logger.error("Error saving document to order", error);
      throw new Error(`Failed to save document: ${error.message}`);
    }
  }

  /**
   * Para facturación interna, siempre está "aceptada"
   */
  async getDocumentStatus(folio: string): Promise<DocumentStatus> {
    return { status: "accepted" };
  }

  /**
   * Cancela un documento interno
   */
  async cancelDocument(folio: string, reason: string): Promise<boolean> {
    try {
      const { error } = await this.supabase
        .from("orders")
        .update({
          document_type: "internal_ticket_cancelled",
          updated_at: new Date().toISOString(),
        })
        .eq("internal_folio", folio);

      if (error) {
        logger.error("Error cancelling internal document", error);
        return false;
      }

      logger.info(`Internal document ${folio} cancelled: ${reason}`);
      return true;
    } catch (error) {
      logger.error("Error cancelling document", error);
      return false;
    }
  }
}

/**
 * Internal Institutional Billing
 *
 * Emite facturas institucionales agrupadas (sin SII).
 * Usa folio secuencial FAC-INST-XXXXXX por sucursal.
 */

import type { SupabaseClient } from "@supabase/supabase-js";

import { appLogger as logger } from "@/lib/logger";
import { createServiceRoleClient } from "@/utils/supabase/server";

import type {
  InstitutionalInvoice,
  InstitutionalInvoiceAdapter,
  InstitutionalInvoiceBillingResult,
} from "./InstitutionalInvoiceAdapter";

export class InternalInstitutionalBilling
  implements InstitutionalInvoiceAdapter
{
  private supabase: SupabaseClient;

  constructor(supabase?: SupabaseClient) {
    this.supabase = supabase ?? createServiceRoleClient();
  }

  async emitInvoice(
    invoice: InstitutionalInvoice,
  ): Promise<InstitutionalInvoiceBillingResult> {
    const folio = await this.generateFolio(invoice.branch_id);

    const { data: inv, error: invError } = await this.supabase
      .from("agreement_institutional_invoices")
      .insert({
        agreement_id: invoice.agreement_id,
        branch_id: invoice.branch_id,
        organization_id: invoice.organization_id,
        institution_rut: invoice.institution_rut,
        institution_name: invoice.institution_name,
        period_from: invoice.period_from,
        period_to: invoice.period_to,
        subtotal: invoice.subtotal,
        tax_amount: invoice.tax_amount,
        total_amount: invoice.total_amount,
        document_type: "factura",
        folio,
        status: "emitted",
        payment_reference: invoice.payment_reference ?? null,
        paid_at: invoice.paid_at,
        emitted_at: new Date().toISOString(),
        emitted_by: invoice.emitted_by ?? null,
      })
      .select("id")
      .single();

    if (invError || !inv) {
      logger.error("Error creating institutional invoice", invError);
      throw new Error(
        `Failed to create institutional invoice: ${invError?.message ?? "Unknown"}`,
      );
    }

    const invoiceId = inv.id;

    for (const item of invoice.items) {
      const { error: balError } = await this.supabase
        .from("agreement_institutional_invoice_balances")
        .insert({
          invoice_id: invoiceId,
          balance_id: item.balance_id,
          amount: item.amount,
        });

      if (balError) {
        logger.error("Error linking balance to invoice", balError);
        throw new Error(`Failed to link balance: ${balError.message}`);
      }
    }

    const pdfUrl = `/api/admin/agreements/${invoice.agreement_id}/invoices/${invoiceId}/pdf`;

    const { error: updateError } = await this.supabase
      .from("agreement_institutional_invoices")
      .update({ pdf_url: pdfUrl, updated_at: new Date().toISOString() })
      .eq("id", invoiceId);

    if (updateError) {
      logger.warn("Failed to update pdf_url on invoice", updateError);
    }

    const { error: balUpdateError } = await this.supabase
      .from("agreement_institutional_balances")
      .update({ invoice_id: invoiceId })
      .in(
        "id",
        invoice.items.map((i) => i.balance_id),
      );

    if (balUpdateError) {
      logger.warn("Failed to set invoice_id on balances", balUpdateError);
    }

    return {
      folio,
      pdfUrl,
      type: "internal",
      timestamp: new Date(),
      invoice_id: invoiceId,
    };
  }

  private async generateFolio(branchId: string): Promise<string> {
    const { data: folio, error } = await this.supabase.rpc(
      "generate_agreement_institutional_invoice_folio",
      { p_branch_id: branchId },
    );

    if (error || !folio) {
      logger.error("Error generating institutional invoice folio", error);
      return this.fallbackFolio(branchId);
    }

    return folio;
  }

  private async fallbackFolio(branchId: string): Promise<string> {
    const prefix = "FAC-INST-";
    const { data: last } = await this.supabase
      .from("agreement_institutional_invoices")
      .select("folio")
      .eq("branch_id", branchId)
      .like("folio", `${prefix}%`)
      .order("created_at", { ascending: false })
      .limit(1)
      .single();

    let next = 1;
    if (last?.folio) {
      const m = last.folio.match(/\d+$/);
      if (m) next = parseInt(m[0], 10) + 1;
    }
    return `${prefix}${String(next).padStart(6, "0")}`;
  }
}

