// Send low stock alert to admins using DB template
export async function sendLowStockAlert(
  adminEmails: string[],
  products: Array<{ name: string; current_stock: number; min_stock: number }>,
  organizationId?: string,
): Promise<{ success: boolean; error?: string }> {
  try {
    const orgInfo = await getOrganizationInfoWithFallbacks(organizationId);

    const template = await loadEmailTemplate(
      "low_stock_alert",
      true,
      organizationId,
    );

    if (!template) {
      appLogger.warn(
        "⚠️ No active low_stock_alert template found, skipping email",
      );
      return { success: false, error: "No active template found" };
    }

    const productsHTML = products
      .map(
        (p) => `
        <div style="padding: 10px; border-bottom: 1px solid #eee;">
          <strong>${p.name}</strong><br>
          Stock actual: ${p.current_stock} | Stock mínimo: ${p.min_stock}
        </div>
      `,
      )
      .join("");

    const productsText = products
      .map(
        (p) =>
          `${p.name} - Stock actual: ${p.current_stock} | Stock mínimo: ${p.min_stock}`,
      )
      .join("\n");

    const variables = {
      ...getDefaultVariables({
        name: orgInfo?.name ?? undefined,
        support_email: orgInfo?.resolvedSupportEmail ?? undefined,
      }),
      low_stock_products: productsHTML,
      low_stock_products_text: productsText,
      product_count: products.length.toString(),
      organization_name: orgInfo?.name || "Tu Óptica",
    };

    const subject = replaceTemplateVariables(template.subject, variables);
    const html = replaceTemplateVariables(template.content, variables);

    const text = html
      .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, "")
      .replace(/<[^>]+>/g, "")
      .replace(/\n\s*\n/g, "\n")
      .trim();

    // Send to all admin emails
    const results = await Promise.all(
      adminEmails.map((email) =>
        sendEmail({
          to: email,
          subject,
          html,
          text,
          replyTo: orgInfo?.resolvedSupportEmail,
          fromDisplayName: orgInfo?.resolvedDisplayName,
        }),
      ),
    );

    if (results.some((r) => r.success)) {
      await incrementTemplateUsage(template.id);
    }

    return {
      success: results.some((r) => r.success),
      error: results.every((r) => !r.success)
        ? "Failed to send to all recipients"
        : undefined,
    };
  } catch (error) {
    appLogger.error("Error sending low stock alert:", error);
    return {
      success: false,
      error: error instanceof Error ? error.message : "Unknown error",
    };
  }
}

import type { SupabaseClient } from "@supabase/supabase-js";

import { appLogger } from '@/lib/logger';
import { createServiceRoleClient } from "@/utils/supabase/server";

import { sendEmail } from "../client";
import { incrementTemplateUsage } from "../template-loader";
import {  getDefaultVariables,
  replaceTemplateVariables,
} from "../template-utils";

// Send marketing email using DB template
export async function sendMarketingEmail(
  recipients: string[],
  templateId: string,
  variables: Record<string, string>,
  supabase?: SupabaseClient,
): Promise<{
  success: boolean;
  results: Array<{
    email: string;
    success: boolean;
    id?: string;
    error?: string;
  }>;
  errors: Array<{ email: string; error: string }>;
}> {
  try {
    const client = supabase ?? createServiceRoleClient();

    const { data: template, error } = await client
      .from("system_email_templates")
      .select("*")
      .eq("id", templateId)
      .eq("is_active", true)
      .single();

    if (error || !template) {
      return {
        success: false,
        results: [],
        errors: recipients.map((email) => ({
          email,
          error: "Template not found",
        })),
      };
    }

    const allVariables = {
      ...getDefaultVariables(),
      ...variables,
    };

    const subject = replaceTemplateVariables(template.subject, allVariables);
    const html = replaceTemplateVariables(template.content, allVariables);

    const text = html
      .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, "")
      .replace(/<[^>]+>/g, "")
      .replace(/\n\s*\n/g, "\n")
      .trim();

    const results: Array<{
      email: string;
      success: boolean;
      id?: string;
      error?: string;
    }> = [];
    const errors: Array<{ email: string; error: string }> = [];

    // Send emails in batches
    const batchSize = 10;
    for (let i = 0; i < recipients.length; i += batchSize) {
      const batch = recipients.slice(i, i + batchSize);

      const batchPromises = batch.map(async (email) => {
        try {
          const result = await sendEmail({
            to: email,
            subject,
            html,
            text,
          });
          results.push({ email, ...result });

          await new Promise((resolve) => setTimeout(resolve, 50));
        } catch (error) {
          errors.push({
            email,
            error: error instanceof Error ? error.message : "Unknown error",
          });
        }
      });

      await Promise.all(batchPromises);

      if (i + batchSize < recipients.length) {
        await new Promise((resolve) => setTimeout(resolve, 1000));
      }
    }

    if (results.some((r) => r.success)) {
      await incrementTemplateUsage(template.id);
    }

    return {
      success: errors.length === 0,
      results,
      errors,
    };
  } catch (error) {
    appLogger.error("Error sending marketing email:", error);
    return {
      success: false,
      results: [],
      errors: recipients.map((email) => ({
        email,
        error: error instanceof Error ? error.message : "Unknown error",
      })),
    };
  }
}

