/**
 * Organization info for email branding with fallbacks from system_config.
 * - Display Name: metadata.email_display_name || org.name
 * - Reply-To: metadata.support_email || system_config.contact_email
 */

import type { SupabaseClient } from "@supabase/supabase-js";

import { appLogger as logger } from "@/lib/logger";
import { createServiceRoleClient } from "@/utils/supabase/server";

export interface OrgInfoForEmail {
  name: string | null;
  metadata: Record<string, unknown> | null;
  /** Resolved reply-to: metadata.support_email || contact_email from config */
  resolvedSupportEmail: string;
  /** Resolved display name: metadata.email_display_name || org.name */
  resolvedDisplayName: string | undefined;
}

const DEFAULT_REPLY_TO = "contacto@opttius.cl";

export async function getOrganizationInfoWithFallbacks(
  organizationId?: string,
  supabase?: SupabaseClient,
): Promise<OrgInfoForEmail | null> {
  if (!organizationId) return null;

  try {
    const client = supabase ?? createServiceRoleClient();
    const { data: org } = await client
      .from("organizations")
      .select("name, metadata")
      .eq("id", organizationId)
      .single();

    if (!org) return null;

    const meta = (org.metadata as Record<string, unknown>) || {};
    const metaSupportEmail = meta.support_email as string | undefined;
    const metaDisplayName = meta.email_display_name as string | undefined;

    let contactEmailFromConfig = "";
    if (!metaSupportEmail?.trim()) {
      // Fetch contact_email from system_config: org-level first, then global
      const { data: orgConfig } = await client
        .from("system_config")
        .select("config_value")
        .eq("config_key", "contact_email")
        .eq("organization_id", organizationId)
        .maybeSingle();

      const { data: globalConfig } = orgConfig
        ? { data: null }
        : await client
            .from("system_config")
            .select("config_value")
            .eq("config_key", "contact_email")
            .is("organization_id", null)
            .maybeSingle();

      const row = orgConfig ?? globalConfig;
      if (row?.config_value != null) {
        contactEmailFromConfig =
          typeof row.config_value === "string"
            ? row.config_value
            : String(row.config_value);
      }
    }

    const resolvedSupportEmail =
      metaSupportEmail?.trim() ||
      contactEmailFromConfig.trim() ||
      DEFAULT_REPLY_TO;
    const resolvedDisplayName =
      metaDisplayName?.trim() || org.name?.trim() || undefined;

    return {
      name: org.name ?? null,
      metadata: meta,
      resolvedSupportEmail,
      resolvedDisplayName,
    };
  } catch (error) {
    logger.error("Error fetching organization info for email:", error);
    return null;
  }
}

/**
 * Sends delivery completion email with satisfaction survey link when a work order
 * is marked as delivered. Creates survey invitation token and sends work_order_delivered
 * template if survey is enabled for the organization.
 */

import type { SupabaseClient } from "@supabase/supabase-js";
import { randomUUID } from "crypto";

import { appLogger as logger } from "@/lib/logger";
import { createServiceRoleClient } from "@/utils/supabase/server";

import { sendEmail } from "./client";
import { wrapInModernLayout } from "./layout";
import { getOrganizationInfoWithFallbacks } from "./org-utils";
import { incrementTemplateUsage, loadEmailTemplate } from "./template-loader";
import {
  getDefaultVariables,
  replaceTemplateVariables,
} from "./template-utils";

function htmlToText(html: string): string {
  return html
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, "")
    .replace(/<[^>]+>/g, "")
    .replace(/\n\s*\n/g, "\n")
    .trim();
}

const BASE_URL = process.env.NEXT_PUBLIC_APP_URL || "https://opttius.cl";

export interface DeliveryCompletionParams {
  workOrderId: string;
  organizationId: string;
  customerId: string | null;
  customerEmail: string;
  customerName: string;
  workOrderNumber: string;
}

/**
 * Sends delivery completion email with survey link when survey is enabled.
 * Non-blocking: logs errors but does not throw.
 */
export async function sendDeliveryCompletionEmail(
  params: DeliveryCompletionParams,
  supabase?: SupabaseClient,
): Promise<{ success: boolean; error?: string }> {
  try {
    const {
      workOrderId,
      organizationId,
      customerId,
      customerEmail,
      customerName,
      workOrderNumber,
    } = params;

    if (!customerEmail?.trim()) {
      logger.warn("Delivery completion email skipped: no customer email", {
        workOrderId,
        organizationId,
      });
      return { success: false, error: "No customer email" };
    }

    const client = supabase ?? createServiceRoleClient();

    // Check survey_enabled for org
    const { data: surveyConfig } = await client
      .from("system_config")
      .select("config_value")
      .eq("config_key", "survey_enabled")
      .eq("organization_id", organizationId)
      .is("branch_id", null)
      .maybeSingle();

    let surveyEnabled = false;
    if (surveyConfig?.config_value != null) {
      try {
        const val =
          typeof surveyConfig.config_value === "string"
            ? JSON.parse(surveyConfig.config_value)
            : surveyConfig.config_value;
        surveyEnabled = !!val;
      } catch {
        surveyEnabled = false;
      }
    }

    if (!surveyEnabled) {
      logger.warn(
        "Delivery completion email skipped: survey disabled for org",
        {
          workOrderId,
          organizationId,
        },
      );
      return { success: false, error: "Survey disabled for org" };
    }

    // Create survey invitation
    const token = randomUUID();
    const expiresAt = new Date();
    expiresAt.setDate(expiresAt.getDate() + 30);

    const { error: invError } = await client
      .from("survey_invitations")
      .insert({
        token,
        organization_id: organizationId,
        work_order_id: workOrderId,
        customer_id: customerId,
        expires_at: expiresAt.toISOString(),
      });

    if (invError) {
      logger.error(
        "Delivery completion email skipped: failed to create survey invitation",
        {
          workOrderId,
          organizationId,
          error: invError,
        },
      );
      return { success: false, error: "Failed to create survey invitation" };
    }

    const surveyUrl = `${BASE_URL}/encuesta/${token}`;

    // Load template and send
    const template = await loadEmailTemplate(
      "work_order_delivered",
      true,
      organizationId,
      undefined,
      client,
    );

    if (!template) {
      logger.warn(
        "No active work_order_delivered template found, skipping delivery email",
      );
      return { success: false, error: "Template not found" };
    }

    const orgInfo = await getOrganizationInfoWithFallbacks(organizationId, client);
    const variables = {
      ...getDefaultVariables({
        name: orgInfo?.name ?? undefined,
        support_email: orgInfo?.resolvedSupportEmail || "contacto@opttius.cl",
      }),
      customer_name: customerName || "Cliente",
      work_order_number: workOrderNumber,
      organization_name: orgInfo?.name || "Nuestra Óptica",
      survey_url: surveyUrl,
    };

    const subject = replaceTemplateVariables(template.subject, variables);
    let html = replaceTemplateVariables(template.content, variables);
    html = wrapInModernLayout(html, {
      organizationName: orgInfo?.name || "Nuestra Óptica",
      organizationColor:
        (orgInfo?.metadata as { primary_color?: string })?.primary_color ||
        "#1e40af",
      previewText: `Gracias por confiar en ${orgInfo?.name || "nosotros"}`,
    });

    const text = htmlToText(html);

    const result = await sendEmail({
      to: customerEmail,
      subject,
      html,
      text,
      replyTo: orgInfo?.resolvedSupportEmail || "contacto@opttius.cl",
      fromDisplayName: orgInfo?.resolvedDisplayName,
    });

    if (result.success) {
      await incrementTemplateUsage(template.id, client);
    }

    return result;
  } catch (error) {
    logger.error("Error sending delivery completion email", {
      workOrderId: params.workOrderId,
      organizationId: params.organizationId,
      error,
    });
    return {
      success: false,
      error: error instanceof Error ? error.message : "Unknown error",
    };
  }
}

/**
 * Service to send quote by email to a client.
 * Used by the quotes send API route and the AI agent sendQuoteByEmail tool.
 */
import type { SupabaseClient } from "@supabase/supabase-js";

import businessConfig from "@/config/business";
import { sendEmail } from "@/lib/email/client";
import { createServiceRoleClient } from "@/utils/supabase/server";

export interface SendQuoteEmailContext {
  organizationId: string;
}

export interface SendQuoteEmailResult {
  success: boolean;
  error?: string;
  emailId?: string;
}

export async function sendQuoteEmailToClient(
  quoteId: string,
  email: string,
  context: SendQuoteEmailContext,
  supabase?: SupabaseClient,
): Promise<SendQuoteEmailResult> {
  if (!email || !email.includes("@")) {
    return { success: false, error: "Email válido requerido" };
  }

  const client = supabase ?? createServiceRoleClient();

  const { data: quoteData, error: quoteError } = await client
    .from("quotes")
    .select("*")
    .eq("id", quoteId)
    .eq("organization_id", context.organizationId)
    .single();

  if (quoteError || !quoteData) {
    return { success: false, error: "Presupuesto no encontrado" };
  }

  let customer: {
    first_name?: string;
    last_name?: string;
    email?: string;
    phone?: string;
    preferred_contact_method?: string;
  } | null = null;
  if (quoteData.customer_id) {
    const { data } = await client
      .from("customers")
      .select(
        "id, first_name, last_name, email, phone, preferred_contact_method",
      )
      .eq("id", quoteData.customer_id)
      .single();
    customer = data;
  }

  let prescription: Record<string, unknown> | null = null;
  if (quoteData.prescription_id) {
    const { data } = await client
      .from("prescriptions")
      .select("*")
      .eq("id", quoteData.prescription_id)
      .single();
    prescription = data;
  }

  const quote = {
    ...quoteData,
    customer,
    prescription,
  };

  const customerName =
    quote.customer?.first_name && quote.customer?.last_name
      ? `${quote.customer.first_name} ${quote.customer.last_name}`
      : "Cliente";

  const formatPrice = (amount: number) =>
    new Intl.NumberFormat("es-CL", {
      style: "currency",
      currency: quote.currency || "CLP",
      minimumFractionDigits: 0,
    }).format(amount || 0);

