  error: Error,
  context?: {
    userId?: string;
    operation?: string;
    tableName?: string;
    query?: string;
  },
): Promise<void> {
  await reportError({
    error,
    context: {
      operation: context?.operation,
      tableName: context?.tableName,
      query: context?.query,
      ...context,
    },
    severity: "high",
    userId: context?.userId,
    timestamp: new Date(),
  });
}

export async function reportUnhandledError(
  error: Error,
  context?: Record<string, unknown>,
): Promise<void> {
