/**
 * Comprehensive Error Handling System — standardized error handling patterns.
 */
import { appLogger as logger } from "@/lib/logger";

import { ApplicationError, BusinessLogicError, ConflictError, DatabaseError, ValidationError } from "./error-classes";
export { ApplicationError, AuthenticationError, AuthorizationError, BusinessLogicError, ConflictError, DatabaseError, ExternalServiceError, generateRequestId,NotFoundError, PaymentError, RateLimitError, ValidationError } from "./error-classes";

interface ErrorResponse { error: { code: string; message: string; details?: Record<string, unknown>; timestamp: string; requestId?: string }; }

export function formatErrorResponse(error: ApplicationError, requestId?: string): ErrorResponse {
  return { error: { code: error.code, message: error.message, details: error.details, timestamp: new Date().toISOString(), requestId } };
}

export function logError(error: Error, context?: Record<string, unknown>): void {
  if (error instanceof ApplicationError && error.isOperational) logger.warn(`Operational error: ${error.code}`, { message: error.message, code: error.code, statusCode: error.statusCode, details: error.details, ...context });
  else logger.error("Unexpected application error", error, { errorName: error.name, errorMessage: error.message, ...context });
}

export function handleApiError(error: unknown, requestId?: string): { response: ErrorResponse; statusCode: number } {
  let appError: ApplicationError;
  if (error instanceof ApplicationError) appError = error;
  else if (error instanceof Error) appError = new ApplicationError(error.message, { code: "INTERNAL_ERROR", statusCode: 500, isOperational: false, cause: error });
  else appError = new ApplicationError(String(error), { code: "INTERNAL_ERROR", statusCode: 500, isOperational: false });
  logError(appError, { requestId });
  return { response: formatErrorResponse(appError, requestId), statusCode: appError.statusCode };
}

export function withErrorHandling<T>(fn: () => Promise<T>, options?: { suppressLogs?: boolean; defaultValue?: T; transformError?: (error: unknown) => ApplicationError }): Promise<T> {
  return fn().catch((error: unknown) => {
    if (!options?.suppressLogs) logError(error instanceof Error ? error : new Error(String(error)), { context: "async operation" });
    if (options?.defaultValue !== undefined) return options.defaultValue;
    if (options?.transformError) throw options.transformError(error);
    throw error;
  });
}

export function safeExecute<T>(fn: () => T, options?: { suppressLogs?: boolean; defaultValue?: T; transformError?: (error: unknown) => ApplicationError }): T {
  try { return fn(); } catch (error: unknown) {
    if (!options?.suppressLogs) logError(error instanceof Error ? error : new Error(String(error)), { context: "sync operation" });
    if (options?.defaultValue !== undefined) return options.defaultValue;
    if (options?.transformError) throw options.transformError(error);
    throw error;
  }
}

export function handleDatabaseError(error: unknown, context: string, details?: Record<string, unknown>): DatabaseError {
  return new DatabaseError(error.message || "Database operation failed", { context, hint: error.hint, details: error.details, ...details }, error);
}

export function mapPostgresError(error: unknown): ApplicationError {
  switch (error.code) {
    case "23505": return new ConflictError("Resource already exists", { constraint: error.constraint });
    case "23503": return new BusinessLogicError("Referenced resource does not exist", { constraint: error.constraint });
    case "23502": return new ValidationError("Required field is missing", { column: error.column });
    case "23514": return new ValidationError("Data validation failed", { constraint: error.constraint });
    default: return handleDatabaseError(error, "PostgreSQL operation");
  }
}

export function validateRequiredFields(data: Record<string, unknown>, requiredFields: string[]): void {
  const missing = requiredFields.filter((f) => data[f] === undefined || data[f] === null || data[f] === "");
  if (missing.length > 0) throw new ValidationError("Missing required fields", { missingFields: missing });
}

export function validateTypes(data: Record<string, unknown>, typeMap: Record<string, "string" | "number" | "boolean" | "array" | "object">): void {
  const errors: string[] = [];
  for (const [field, expectedType] of Object.entries(typeMap)) {
    const value = data[field];
    const actualType = Array.isArray(value) ? "array" : typeof value;
    if (value !== undefined && actualType !== expectedType) errors.push(`Field '${field}' must be of type ${expectedType}, got ${actualType}`);
  }
  if (errors.length > 0) throw new ValidationError("Type validation failed", { errors });
}

export function sanitizeInput<T extends Record<string, unknown>>(data: T, schema: { required?: string[]; types?: Record<string, "string" | "number" | "boolean" | "array" | "object">; maxLength?: Record<string, number> }): T {
  if (schema.required) validateRequiredFields(data, schema.required);
  if (schema.types) validateTypes(data, schema.types);
  if (schema.maxLength) {
    const errors: string[] = [];
    for (const [field, maxLength] of Object.entries(schema.maxLength)) {
      if (typeof data[field] === "string" && (data[field] as string).length > maxLength) errors.push(`Field '${field}' exceeds maximum length of ${maxLength}`);
    }
    if (errors.length > 0) throw new ValidationError("Input validation failed", { errors });
  }
  return data;
}

/**
 * Unified import mapping utilities.
 * Provides CSV parsing helpers and auto-mapping of column headers
 * for product and customer import workflows.
 */

// ─── CSV Parsing ───────────────────────────────────────────────────────

/**
 * Parse a single CSV line into fields, handling quoted fields,
 * escaped quotes, and trailing commas.
 */
export function parseCSVLine(line: string): string[] {
  const fields: string[] = [];
  let current = "";
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const ch = line[i];

    if (ch === '"') {
      if (inQuotes && i + 1 < line.length && line[i + 1] === '"') {
        current += '"';
        i++; // skip escaped quote
      } else {
        inQuotes = !inQuotes;
      }
    } else if (ch === "," && !inQuotes) {
      fields.push(current.trim());
      current = "";
    } else {
      current += ch;
    }
  }
  fields.push(current.trim());

  return fields;
}

// ─── Boolean Parsing ───────────────────────────────────────────────────

const TRUTHY_VALUES = new Set([
  "true",
  "1",
  "yes",
  "sí",
  "si",
  "y",
  "yeah",
  "on",
]);

/**
 * Parse a string value to boolean.
 * Returns true for truthy values (case-insensitive), false otherwise.
 */
export function parseBoolean(value: string | null | undefined): boolean {
  if (!value) return false;
  return TRUTHY_VALUES.has(value.trim().toLowerCase());
}

// ─── Array Parsing ─────────────────────────────────────────────────────

/**
 * Parse a string value to an array.
 * Handles JSON arrays and semicolon-separated values.
 */
export function parseArray(value: string | null | undefined): string[] {
  if (!value || !value.trim()) return [];

  const trimmed = value.trim();

  // Try JSON array first
  if (trimmed.startsWith("[")) {
    try {
      const parsed = JSON.parse(trimmed);
      if (Array.isArray(parsed)) return parsed.map(String);
    } catch {
      // fall through to semicolon split
    }
  }

  // Fall back to semicolon-separated
  return trimmed
    .split(";")
    .map((s) => s.trim())
    .filter(Boolean);
}

// ─── Slug Generation ───────────────────────────────────────────────────

/**
 * Generate a URL-friendly slug from a product name.
 * Removes accents, lowercases, replaces special chars and spaces with hyphens.
 */
export function generateSlug(name: string): string {
  const normalized = name
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "") // remove combining diacritical marks
    .toLowerCase();

  const cleaned = normalized
    .replace(/[^a-z0-9\s-]/g, "") // keep only letters, digits, spaces, hyphens
    .replace(/[\s-]+/g, "-") // collapse spaces and hyphens
    .trim();

  return cleaned;
}

// ─── Column Mapping ────────────────────────────────────────────────────

/**
 * Bilingual column mapping: Spanish → English (product fields).
 * Key = Spanish header, Value = target field name.
 * Also includes English → English entries for direct matching.
 */
const COLUMN_MAPPINGS: Record<string, string> = {
  nombre: "name",
  name: "name",
  precio: "price",
  price: "price",
  precio_costo: "cost_price",
  cost_price: "cost_price",
  stock: "stock_quantity",
  stock_quantity: "stock_quantity",
  sku: "sku",
  código: "sku",
  descripcion: "description",
  descripción: "description",
  description: "description",
  marca: "brand",
  brand: "brand",
  categoría: "category_id",
  categoria: "category_id",
  category_id: "category_id",
  category: "category_id",
  proveedor: "supplier_id",
  costo: "cost_price",
  iva: "tax_rate",
  impuesto: "tax_rate",
  tax_rate: "tax_rate",
  activo: "status",
  estado: "status",
  status: "status",
  barcode: "barcode",
  código_barra: "barcode",
  codigo_barra: "barcode",
  peso: "weight",
  weight: "weight",
  largo: "length",
  length: "length",
  ancho: "width",
  width: "width",
  alto: "height",
  height: "height",
  imagen: "image_url",
  imágenes: "image_urls",
  imagenes: "image_urls",
  etiquetas: "tags",
  tags: "tags",
  atributos: "attributes",
  tipo_producto: "product_type",
  product_type: "product_type",
};

/**
 * Minimum key length for header→key substring matching in autoMapColumn.
 * Keys shorter than this are exact-match only, preventing false positives
 * like "first_name" matching the short key "name".
 */
const MIN_KEY_SUBSTRING = 5;

/**
 * Minimum header length for key→header substring matching in suggestMappingFromHeaders.
 * Headers shorter than this won't participate in reverse substring matching,
 * preventing false positives while allowing "type" (4 chars) to match "product_type".
 */
const MIN_HEADER_SUBSTRING = 4;

/**
 * Auto-map a single column header to a target field name.
 * - Exact match first (e.g., "nombre" → "name")
 * - Substring fallback: header CONTAINS key (key length ≥ MIN_SUBSTRING_LENGTH)
 *   (e.g., "precio_venta" contains "precio" → "price")
 * When multiple keys match via substring, the LAST match wins.
 * Returns "ignore" if no match found.
 */
export function autoMapColumn(header: string): string {
  const trimmed = header.trim().toLowerCase();
  if (!trimmed) return "ignore";

  let matched: string | null = null;

  // Exact match first
  if (COLUMN_MAPPINGS[trimmed]) {
    matched = COLUMN_MAPPINGS[trimmed];
  }

  // Substring fallback: header contains key (trimmed.includes(key))
  // Only applies to keys at least MIN_KEY_SUBSTRING chars
  // Iterate ALL entries so later matches can overwrite earlier ones
  for (const [key, field] of Object.entries(COLUMN_MAPPINGS)) {
    if (key.length >= MIN_KEY_SUBSTRING && trimmed.includes(key)) {
      matched = field;
    }
  }

  return matched ?? "ignore";
}

/**
 * Auto-map multiple column headers in batch.
 */
export function autoMapAllColumns(headers: string[]): Record<string, string> {
  const result: Record<string, string> = {};
  for (const header of headers) {
    result[header] = autoMapColumn(header);
  }
  return result;
}

// ─── Suggestion Engine ─────────────────────────────────────────────────

/**
 * Target field list for product imports (10 base fields).
 */
const PRODUCT_FIELDS = [
  "name",
  "price",
  "cost_price",
  "stock_quantity",
  "sku",
  "barcode",
  "description",
  "brand",
  "category_id",
  "status",
];

/**
 * Target field list for customer imports (8 base fields).
 */
const CUSTOMER_FIELDS = [
  "first_name",
  "last_name",
  "email",
  "phone",
  "rut",
  "address",
  "city",
  "region",
];

/**
 * Result of suggestMappingFromHeaders.
 */
export interface MappingSuggestion {
  mapping: Record<string, string>;
  confidence: number;
}

/**
 * Suggest a column mapping based on a list of headers and an entity type.
 * Returns a mapping and a confidence score (0–1).
 *
 * Strategy (3 passes):
 * 1. `autoMapColumn` — exact match + header⊇key substring
 * 2. Bidirectional COLUMN_MAPPINGS pass — key⊇header substring (catches "precio" ↔ "precio_costo")
 * 3. Entity field substring pass — field⊇normalizedHeader for remaining "ignore" headers
 */
export function suggestMappingFromHeaders(
  headers: string[],
  entity: "products" | "customers",
): MappingSuggestion {
  const rawMapping = autoMapAllColumns(headers);
  const targetFields = entity === "products" ? PRODUCT_FIELDS : CUSTOMER_FIELDS;

  for (const header of headers) {
    const trimmed = header.trim().toLowerCase();
    if (!trimmed) continue;

    // Pass 2: reverse COLUMN_MAPPINGS — check if any KEY contains HEADER
    // (catches: "precio" header matches "precio_costo" key → "cost_price",
    //  and "type" (≥4) matches "product_type" key)
    if (trimmed.length >= MIN_HEADER_SUBSTRING) {
      for (const [key, field] of Object.entries(COLUMN_MAPPINGS)) {
        if (key.includes(trimmed)) {
          rawMapping[header] = field;
        }
      }
    }

    // Pass 3: entity field fallback — only for headers still unmapped
    if (rawMapping[header] === "ignore" || rawMapping[header] === undefined) {
      const normalizedHeader = trimmed.replace(/_/g, " ");
      for (const field of targetFields) {
        // Check field⊇normalizedHeader (field contains header substring)
        if (field.includes(normalizedHeader)) {
          rawMapping[header] = field;
          break;
        }
      }
    }
  }

  // Remove "ignore" entries from the mapping
  const filteredMapping: Record<string, string> = {};
  for (const [header, field] of Object.entries(rawMapping)) {
    if (field !== "ignore") {
      filteredMapping[header] = field;
    }
  }

  // Count unique target fields matched
  const matchedFields = new Set(Object.values(filteredMapping));
  const confidence =
    targetFields.length > 0 ? matchedFields.size / targetFields.length : 0;

  return { mapping: filteredMapping, confidence };
}

/**
 * Unified import service.
 * Handles product import processing (create/update/upsert) with
 * stock management via the update_product_stock RPC.
 */

import { createRootAdminClient } from "@/utils/supabase/root-admin";

import { generateSlug } from "./import-mapping";

// ─── Types ─────────────────────────────────────────────────────────────

export interface ImportProduct {
  name: string;
  slug?: string;
  price: number;
  cost_price?: number;
  stock_quantity?: number;
  sku?: string;
  barcode?: string;
  description?: string;
  brand?: string;
  category_id?: string;
  category_name?: string;
  supplier_id?: string;
  tax_rate?: number;
  status?: string;
  weight?: number;
  length?: number;
  width?: number;
  height?: number;
  image_url?: string;
  image_urls?: string[];
