/**
 * Validation middleware
 */
export async function validateRequestBody<T>(
  request: NextRequest,
  validator: (data: unknown) => T,
): Promise<T> {
  try {
    const body = await request.json();
    return validator(body);
  } catch (error) {
    if (error instanceof SyntaxError) {
      throw new ApplicationError("Invalid JSON in request body", {
        code: "INVALID_JSON",
        statusCode: 400,
      });
    }
    throw error;
  }
}

/**
 * Query parameter validation
 */
export function validateQueryParams(
  request: NextRequest,
  validators: Record<string, (value: string) => boolean>,
): Record<string, string> {
  const params: Record<string, string> = {};
  const errors: string[] = [];

  const url = new URL(request.url);

  for (const [param, validator] of Object.entries(validators)) {
    const value = url.searchParams.get(param);

    if (value === null) {
      errors.push(`Missing required parameter: ${param}`);
      continue;
    }

    if (!validator(value)) {
      errors.push(`Invalid value for parameter: ${param}`);
      continue;
    }

    params[param] = value;
  }

  if (errors.length > 0) {
    throw new ApplicationError("Invalid query parameters", {
      code: "INVALID_QUERY_PARAMS",
      statusCode: 400,
      details: { errors },
    });
  }

  return params;
}

/**
 * Pagination helper
 */
export interface PaginationOptions {
  page?: number;
  limit?: number;
  maxLimit?: number;
}

export interface PaginationResult {
  page: number;
  limit: number;
  offset: number;
  maxLimit: number;
}

export function parsePagination(
  request: NextRequest,
  options: PaginationOptions = {},
): PaginationResult {
  const url = new URL(request.url);

  const page = parseInt(url.searchParams.get("page") || "1", 10);
  const limit = parseInt(url.searchParams.get("limit") || "10", 10);
  const maxLimit = options.maxLimit || 100;

  if (isNaN(page) || page < 1) {
    throw new ApplicationError("Invalid page number", {
      code: "INVALID_PAGINATION",
      statusCode: 400,
      details: { page },
    });
  }

  if (isNaN(limit) || limit < 1 || limit > maxLimit) {
    throw new ApplicationError(
      `Invalid limit. Must be between 1 and ${maxLimit}`,
      {
        code: "INVALID_PAGINATION",
        statusCode: 400,
        details: { limit, maxLimit },
      },
    );
  }

  return {
    page,
    limit,
    offset: (page - 1) * limit,
    maxLimit,
  };
}

/**
 * Response helpers
 */
export function successResponse<T>(
  data: T,
  options?: {
    message?: string;
    meta?: Record<string, unknown>;
  },
): NextResponse {
  return NextResponse.json({
    success: true,
    data,
    message: options?.message,
    meta: options?.meta,
  });
}

export function paginatedResponse<T>(
  data: T[],
  pagination: PaginationResult,
  totalCount: number,
  options?: {
    message?: string;
  },
): NextResponse {
  return NextResponse.json({
    success: true,
    data,
    message: options?.message,
    pagination: {
      page: pagination.page,
      limit: pagination.limit,
      total: totalCount,
      totalPages: Math.ceil(totalCount / pagination.limit),
    },
  });
}

