export async function createPaymentIntent(
  orderId: string | null,
  amount: number,
  currency: string,
  userId: string,
  organizationId: string,
): Promise<PaymentIntentResponse> {
  const { preference } = getMPClient();
  const baseUrl =
    process.env.NEXT_PUBLIC_BASE_URL ||
    process.env.NEXT_PUBLIC_APP_URL ||
    "http://localhost:3000";
  const successUrl = `${baseUrl.replace(/\/$/, "")}/checkout/result?success=1&orderId=${orderId ?? ""}`;
  const failureUrl = `${baseUrl.replace(/\/$/, "")}/checkout/result?success=0&orderId=${orderId ?? ""}`;
  const pendingUrl = `${baseUrl.replace(/\/$/, "")}/checkout/result?success=pending&orderId=${orderId ?? ""}`;
  // MP requires back_urls.success to be defined and valid when auto_return is set; use HTTPS (e.g. ngrok) in dev
  const useAutoReturn = successUrl.startsWith("https://");

  try {
    // Mercado Pago requires unit_price as integer (whole units; CLP has no decimals)
    const unitPriceInteger = Math.round(Number(amount));
    const result = await preference.create({
      body: {
        items: [
          {
            id: orderId || `direct-payment-${Date.now()}`,
            title: `Order ${orderId || "Direct Payment"}`,
            quantity: 1,
            unit_price: unitPriceInteger,
            currency_id: currency.toUpperCase(),
          },
        ],
        back_urls: {
          success: successUrl,
          failure: failureUrl,
          pending: pendingUrl,
        },
        ...(useAutoReturn ? { auto_return: "approved" as const } : {}),
        external_reference: orderId ?? "",
        notification_url: `${baseUrl.replace(/\/$/, "")}/api/webhooks/mercadopago`,
        metadata: {
          user_id: userId,
          organization_id: organizationId,
          order_id: orderId ?? "",
          integration_version: "1.0",
          environment: process.env.NODE_ENV ?? "development",
        },
        statement_descriptor: "OPTTIUS",
      },
    });

    const body =
      (
        result as {
          body?: {
            id?: string;
            init_point?: string;
            sandbox_init_point?: string;
          };
        }
      ).body ??
      (result as {
        id?: string;
        init_point?: string;
        sandbox_init_point?: string;
      });
    const preferenceId = body.id ?? (result as { id?: string }).id;
    const initPoint =
      body.init_point ??
      body.sandbox_init_point ??
      (result as { init_point?: string; sandbox_init_point?: string })
        .init_point ??
      (result as { init_point?: string; sandbox_init_point?: string })
        .sandbox_init_point;

    if (!preferenceId || !initPoint) {
      throw new Error(
        "Mercado Pago preference creation failed or missing id/init_point.",
      );
    }

    logger.info("Mercado Pago Preference created", {
      preferenceId,
      orderId,
      amount,
    });

    return {
      preferenceId,
      approvalUrl: initPoint,
      gatewayPaymentIntentId: preferenceId,
      status: "pending",
    };
  } catch (error) {
    const errorMessage = getReadableErrorMessage(error);
    logger.error(
      "Error creating Mercado Pago Preference",
      error instanceof Error ? error : new Error(errorMessage),
      { orderId, amount },
    );
    throw new Error(`Mercado Pago error: ${errorMessage}`);
  }
}

/**
 * Mercado Pago Gateway — Pre-approval plans & subscription management.
 *
 * @module lib/payments/mercadopago/gateway/preapproval
 */

import { appLogger as logger } from "@/lib/logger";

import { getMPClient, getReadableErrorMessage } from "./helpers";

/**
 * Creates a Preapproval Plan (recurring plan) in Mercado Pago.
 * @param reason - Plan description
 * @param amount - Monthly amount
 * @param currency - Currency code (e.g. CLP)
 * @param backUrl - Return URL after checkout
 */
export async function createPreApprovalPlan(
  reason: string,
  amount: number,
  currency: string,
  backUrl: string,
): Promise<{ id: string; init_point?: string }> {
  const { preApprovalPlan } = getMPClient();
  try {
    const amountInteger = Math.round(Number(amount));
    const result = await preApprovalPlan.create({
      body: {
        reason,
        back_url: backUrl,
        auto_recurring: {
          frequency: 1,
          frequency_type: "months",
          transaction_amount: amountInteger,
          currency_id: currency.toUpperCase(),
          billing_day: 10,
          billing_day_proportional: false,
        },
        payment_methods_allowed: {
          payment_types: [{ id: "credit_card" }, { id: "debit_card" }],
        },
      },
    });
    const body =
      (result as { body?: { id?: string; init_point?: string } }).body ??
      (result as { id?: string; init_point?: string });
    const id = body.id ?? (result as { id?: string }).id;
    if (!id) {
      throw new Error(
        "Mercado Pago preapproval plan creation returned no id",
      );
    }
    logger.info("Mercado Pago PreApproval Plan created", {
      planId: id,
      reason,
      amount,
    });
    return {
      id: String(id),
      init_point:
        body.init_point ?? (result as { init_point?: string }).init_point,
    };
  } catch (error) {
    const errorMessage = getReadableErrorMessage(error);
    logger.error(
      "Error creating Mercado Pago PreApproval Plan",
      error instanceof Error ? error : new Error(errorMessage),
      { reason, amount },
    );
    throw new Error(`Mercado Pago preapproval plan error: ${errorMessage}`);
  }
}

/**
 * Creates a Preapproval (subscription) linked to a plan and payer.
 * @param preapprovalPlanId - MP plan id
 * @param payerEmail - Payer email
 * @param cardTokenId - Card token from Bricks
 * @param reason - Description
 * @param externalReference - Our organization_id or subscription id
 * @param backUrl - Return URL
 */
export async function createPreApproval(
  preapprovalPlanId: string,
  payerEmail: string,
  cardTokenId: string,
  reason: string,
  externalReference: string,
  backUrl: string,
): Promise<{
  id: string;
  status: string;
  init_point?: string;
}> {
  const { preApproval } = getMPClient();
  try {
    const result = await preApproval.create({
      body: {
        preapproval_plan_id: preapprovalPlanId,
        payer_email: payerEmail,
        card_token_id: cardTokenId,
        reason,
        external_reference: externalReference,
        back_url: backUrl,
      },
    });
    const body =
      (
        result as {
          body?: { id?: string; status?: string; init_point?: string };
        }
      ).body ??
      (result as { id?: string; status?: string; init_point?: string });
    const id = body.id ?? (result as { id?: string }).id;
    const status =
      body.status ?? (result as { status?: string }).status ?? "pending";
    if (!id) {
      throw new Error("Mercado Pago preapproval creation returned no id");
    }
    logger.info("Mercado Pago PreApproval (subscription) created", {
      preapprovalId: id,
      status,
      externalReference,
    });
    return {
      id: String(id),
      status: String(status),
      init_point:
        body.init_point ?? (result as { init_point?: string }).init_point,
    };
  } catch (error) {
    const errorMessage = getReadableErrorMessage(error);
    logger.error(
      "Error creating Mercado Pago PreApproval",
      error instanceof Error ? error : new Error(errorMessage),
      { preapprovalPlanId, externalReference },
    );
    throw new Error(`Mercado Pago preapproval error: ${errorMessage}`);
  }
}

/**
 * Fetches a PreApproval (subscription) by id (for webhook sync).
 */
export async function getPreApproval(preapprovalId: string): Promise<{
  id: string;
  status: string;
  external_reference?: string | null;
  payer_email?: string;
  reason?: string;
} | null> {
  const { preApproval } = getMPClient();
  try {
    const result = await preApproval.get({ id: preapprovalId });
    const body =
      (result as { body?: Record<string, unknown> }).body ??
      (result as unknown as Record<string, unknown>);
    return {
      id: String(body.id ?? preapprovalId),
      status: String(body.status ?? "pending"),
      external_reference:
        (body.external_reference as string | null) ?? undefined,
      payer_email: body.payer_email as string | undefined,
      reason: body.reason as string | undefined,
    };
  } catch (error) {
    logger.error(
      "Error fetching Mercado Pago PreApproval",
      error instanceof Error ? error : new Error(String(error)),
      { preapprovalId },
    );
    return null;
  }
}

/**
 * Mercado Pago Gateway — Token-based payment (Bricks / Checkout API).
 *
 * @module lib/payments/mercadopago/gateway/token-payment
 */

import { appLogger as logger } from "@/lib/logger";
import type { PaymentStatus } from "@/types/payment";

import { getMPClient, getReadableErrorMessage, mapStatus } from "./helpers";

export async function createPaymentWithToken(
  token: string,
  amount: number,
  currency: string,
  userId: string,
  organizationId: string,
  payerEmail: string,
  paymentMethodId: string,
  issuerId?: string,
  description?: string,
  metadata?: Record<string, unknown>,
): Promise<{
  id: string;
  status: PaymentStatus;
  transaction_amount: number;
  currency_id: string;
}> {
  const { payment } = getMPClient();
  const baseUrl =
    process.env.NEXT_PUBLIC_BASE_URL ||
    process.env.NEXT_PUBLIC_APP_URL ||
    "http://localhost:3000";

  if (!paymentMethodId || paymentMethodId.trim() === "") {
    throw new Error("Invalid payment_method_id");
  }

  try {
    // Mercado Pago requires transaction_amount as integer (whole units; CLP has no decimals)
    const amountInteger = Math.round(Number(amount));
    const result = await payment.create({
      body: {
        transaction_amount: amountInteger,
        token: token,
        description: description || `Suscripción Opttius - ${organizationId}`,
        installments: 1,
        payment_method_id: paymentMethodId,
        ...(issuerId ? { issuer_id: Number(issuerId) } : {}),
        payer: {
          email: payerEmail,
        },
        metadata: {
          user_id: userId,
          organization_id: organizationId,
          integration_version: "1.0",
          environment: process.env.NODE_ENV ?? "development",
          ...metadata,
        },
        notification_url: `${baseUrl.replace(/\/$/, "")}/api/webhooks/mercadopago`,
        statement_descriptor: "OPTTIUS",
      },
    });

    const body =
      (result as { body?: Record<string, unknown> }).body ??
      (result as unknown as Record<string, unknown>);

    const paymentId = String(body.id ?? "");
    const mpStatus = String(body.status ?? "pending");
    const status = mapStatus(mpStatus);
    const transaction_amount = Number(body.transaction_amount ?? amount);
    const currency_id = String(body.currency_id ?? currency).toUpperCase();

    logger.info("Mercado Pago Payment created with token", {
      paymentId,
      status,
      mpStatus,
      amount: transaction_amount,
      organizationId,
    });

    return {
      id: paymentId,
      status,
      transaction_amount,
      currency_id,
    };
  } catch (error) {
    const errorMessage = getReadableErrorMessage(error);
    logger.error(
      "Error creating Mercado Pago Payment with token",
      error instanceof Error ? error : new Error(errorMessage),
      { amount, organizationId },
    );
    throw new Error(`Mercado Pago payment error: ${errorMessage}`);
  }
}

/**
 * Mercado Pago Gateway — Webhook processing and merchant order lookup.
 *
 * @module lib/payments/mercadopago/gateway/webhook-handler
 */

import type { NextRequest } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import type { WebhookEvent } from "@/types/payment";

import type { MerchantOrderInfo } from "./helpers";
import { getMPClient, mapStatus } from "./helpers";

export async function processWebhookEvent(
  request: NextRequest,
): Promise<WebhookEvent> {
  const query = request.nextUrl.searchParams;
  const topic = query.get("topic");
  const id = query.get("id");

  if (topic === "payment" && id) {
    const { payment, merchantOrder: _merchantOrder } = getMPClient();
    try {
      const paymentInfo = await payment.get({ id });
      const paymentData: Record<string, unknown> =
        (paymentInfo as { body?: Record<string, unknown> }).body ??
        (paymentInfo as Record<string, unknown>);

      const orderId =
        typeof paymentData.external_reference === "string"
          ? paymentData.external_reference
          : null;
      const organizationId =
        typeof paymentData.metadata === "object" &&
        paymentData.metadata &&
        "organization_id" in paymentData.metadata &&
        typeof paymentData.metadata.organization_id === "string"
          ? paymentData.metadata.organization_id
          : null;
      const amount =
        typeof paymentData.transaction_amount === "number"
          ? paymentData.transaction_amount
          : 0;
      const currency =
        typeof paymentData.currency_id === "string"
          ? paymentData.currency_id
          : "CLP";
      // We store gateway_payment_intent_id = preference_id (from createPaymentIntent).
      // MP payment response often has order.id = merchant_order id but no top-level preference_id.
      let preferenceId =
        (paymentData as { preference_id?: string }).preference_id ?? null;
      if (
        !preferenceId &&
        (paymentData.order as { id?: string } | undefined)?.id
      ) {
        const merchantOrderId = String(
          (paymentData.order as { id?: string }).id,
        );
        const orderInfo = await getMerchantOrder(merchantOrderId);
        preferenceId = orderInfo?.preference_id ?? null;
      }
      if (!preferenceId) {
        preferenceId =
          (paymentData.order as { id?: string } | undefined)?.id ?? null;
      }

      logger.info("Mercado Pago Payment Webhook received", {
        paymentId: id,
        status: paymentData.status,
        organizationId,
        preferenceId,
      });

      return {
        gateway: "mercadopago",
        gatewayEventId: `${topic}-${id}`,
        type: topic ?? "payment",
        status: mapStatus(
          typeof paymentData.status === "string"
            ? paymentData.status
            : "pending",
        ),
        gatewayTransactionId: String(
          typeof paymentData.id === "number" ||
            typeof paymentData.id === "string"
            ? paymentData.id
            : id,
        ),
        gatewayPaymentIntentId: preferenceId ?? String(id),
        amount,
        currency:
          typeof currency === "string" ? currency.toUpperCase() : "CLP",
        orderId: typeof orderId === "string" ? orderId : null,
        organizationId,
        metadata: paymentData as unknown as Record<string, unknown>,
      };
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      logger.error(
        "Error fetching Mercado Pago payment info for webhook",
        error instanceof Error ? error : new Error(errorMessage),
        { id },
      );
      throw new Error(`Mercado Pago Webhook Error: ${errorMessage}`);
    }
  }

  logger.warn(
    "Mercado Pago Webhook received with unhandled topic or missing ID",
    { topic, id },
  );
  throw new Error("Mercado Pago Webhook: Unhandled topic or missing ID");
}

/**
 * Fetches a merchant order by ID (for merchant_order webhook processing).
 * Used to get preference_id and payment statuses without relying on payment-topic webhook.
 */
export async function getMerchantOrder(
  merchantOrderId: string,
): Promise<MerchantOrderInfo | null> {
  try {
    const { merchantOrder } = getMPClient();
    const result = await merchantOrder.get({
      merchantOrderId,
    });
    const body =
      (
        result as {
          body?: {
            preference_id?: string;
            payments?: Array<{ id?: number; status?: string }>;
          };
        }
      ).body ??
      (result as {
        preference_id?: string;
        payments?: Array<{ id?: number; status?: string }>;
      });
    const preference_id =
      typeof body.preference_id === "string" ? body.preference_id : null;
    const payments = Array.isArray(body.payments) ? body.payments : [];
    logger.info("Mercado Pago Merchant Order fetched", {
      merchantOrderId,
      preference_id,
      paymentCount: payments.length,
    });
    return { preference_id, payments };
  } catch (error) {
    logger.error(
      "Error fetching Mercado Pago merchant order",
      error instanceof Error ? error : new Error(String(error)),
      { merchantOrderId },
    );
    return null;
  }
}

/**
 * Parses webhook request body and search params for MercadoPago notifications.
 * Pure function — no side effects, no logger calls.
 *
 * @module lib/payments/mercadopago/webhook-parser
 */

export function parseWebhookBody(
  body: unknown,
  searchParams: URLSearchParams,
): { eventId: string | null; topic: string | null } {
  // Priority cascade for eventId:
  // 1. searchParams "data.id" or "id"
  let eventId = searchParams.get("data.id") ?? searchParams.get("id") ?? null;

  // 2. Attempt body extraction when searchParams yielded nothing
  if (body && typeof body === "object" && !eventId) {
    const bodyRecord = body as Record<string, unknown>;
    const data = bodyRecord.data;

    if (data != null && typeof data === "object" && "id" in data) {
      eventId = String((data as { id: unknown }).id);
    } else if (typeof data === "string") {
      eventId = data;
    } else if (
      typeof bodyRecord.id === "string" ||
      typeof bodyRecord.id === "number"
    ) {
      eventId = String(bodyRecord.id);
    } else if (
      typeof bodyRecord.api_id === "string" ||
      typeof bodyRecord.api_id === "number"
    ) {
      eventId = String(bodyRecord.api_id);
    }
  }

  // Fallback: searchParams "id" again (matches original route behaviour)
  if (!eventId) {
    eventId = searchParams.get("id") ?? null;
  }

  // Topic from body → searchParams → inferred from eventId
  const bodyRecord =
    body && typeof body === "object" ? (body as Record<string, unknown>) : null;
  const topicFromBody =
    (bodyRecord && typeof bodyRecord.type === "string"
      ? bodyRecord.type
      : null) ??
    (bodyRecord && typeof bodyRecord.action === "string"
      ? bodyRecord.action
      : null) ??
    null;
  const topic =
    topicFromBody ?? searchParams.get("topic") ?? (eventId ? "payment" : null);

  return { eventId, topic };
}

/**
 * Validador de webhooks de MercadoPago
 * Verifica la autenticidad de las notificaciones mediante firma HMAC
 *
 * @module lib/payments/mercadopago/webhook-validator
 */

import crypto from "crypto";

import { appLogger as logger } from "@/lib/logger";

export interface WebhookValidationResult {
  isValid: boolean;
  error?: string;
}

export class MercadoPagoWebhookValidator {
  private secret: string;

  constructor(secret?: string) {
    this.secret = secret || process.env.MERCADOPAGO_WEBHOOK_SECRET || "";
    if (!this.secret) {
      logger.warn(
        "MERCADOPAGO_WEBHOOK_SECRET not configured. Webhook validation will be skipped.",
      );
    }
  }

  /**
   * Valida la firma de un webhook de MercadoPago
   * @param xSignature - Header x-signature del webhook
   * @param xRequestId - Header x-request-id del webhook
   * @param dataId - Query param data.id
   * @returns Resultado de la validación
   */
  validate(
    xSignature: string | null,
    xRequestId: string | null,
    dataId: string | null,
  ): WebhookValidationResult {
    // Si no hay secret configurado, permitir (solo en desarrollo)
    if (!this.secret) {
      if (process.env.NODE_ENV === "production") {
        return {
          isValid: false,
          error: "Webhook secret not configured in production",
        };
      }
      logger.warn("Webhook validation skipped (no secret configured)");
      return { isValid: true };
    }

    // Validar que existan los headers necesarios
    if (!xSignature || !xRequestId || !dataId) {
      return {
        isValid: false,
        error: "Missing required headers or query params",
      };
    }

    try {
      // Extraer ts y v1 del header x-signature
      const parts = xSignature.split(",");
      let ts: string | null = null;
      let hash: string | null = null;

      for (const part of parts) {
        const [key, value] = part.split("=");
        if (key?.trim() === "ts") {
          ts = value?.trim() || null;
        } else if (key?.trim() === "v1") {
          hash = value?.trim() || null;
        }
      }

      if (!ts || !hash) {
        return {
          isValid: false,
          error: "Invalid x-signature format",
        };
      }

      // MP doc: "if the data.id_url is alphanumeric, it must be sent in lowercase"
      const manifestId = /^[a-zA-Z0-9]+$/.test(dataId)
        ? dataId.toLowerCase()
        : dataId;
      const manifest = `id:${manifestId};request-id:${xRequestId};ts:${ts};`;

      // Generar HMAC SHA256
      const hmac = crypto.createHmac("sha256", this.secret);
      hmac.update(manifest);
      const computedHash = hmac.digest("hex");

      // Comparar hashes
      if (computedHash !== hash) {
        logger.warn("Webhook signature validation failed", {
          expected: hash,
          computed: computedHash,
          manifest,
        });
        return {
          isValid: false,
          error: "Signature mismatch",
        };
      }

      // Validar timestamp (no más de 5 minutos de diferencia)
      // MP envía ts en segundos (Unix), no en milisegundos
      const tsNumber = parseInt(ts, 10);
      const nowSec = Math.floor(Date.now() / 1000);
      const diff = Math.abs(nowSec - tsNumber);
      const maxDiff = 5 * 60; // 5 minutos en segundos

      if (diff > maxDiff) {
        logger.warn("Webhook timestamp too old", {
          timestamp: tsNumber,
          nowSec,
          diff,
        });
        return {
          isValid: false,
          error: "Timestamp too old",
        };
      }

      return { isValid: true };
    } catch (error) {
      logger.error(
        "Error validating webhook signature",
        error instanceof Error ? error : new Error(String(error)),
      );
      return {
        isValid: false,
        error: "Validation error",
      };
    }
  }
}

/**
 * NOWPayments cryptocurrency payment gateway implementation (IPaymentGateway).
 *
 * @module lib/payments/nowpayments/gateway
 */

import crypto from "crypto";
import type { NextRequest } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import type { PaymentStatus, WebhookEvent } from "@/types/payment";

import type { IPaymentGateway, PaymentIntentResponse } from "../interfaces";

/**
 * Get the NOWPayments API base URL based on sandbox mode
 */
function getNowPaymentsBaseUrl(): string {
  const isSandbox = process.env.NOWPAYMENTS_SANDBOX_MODE === "true";
  logger.debug("NOWPayments Gateway Mode", { isSandbox });
  return isSandbox
    ? "https://api-sandbox.nowpayments.io/v1"
    : "https://api.nowpayments.io/v1";
}

/**
 * Get the appropriate API key based on sandbox mode
 */
function getNowPaymentsApiKey(): string {
  const isSandbox = process.env.NOWPAYMENTS_SANDBOX_MODE === "true";
  const apiKeyRaw = isSandbox
    ? process.env.NOWPAYMENTS_SANDBOX_API_KEY
    : process.env.NOWPAYMENTS_API_KEY;

  const apiKey = apiKeyRaw?.trim();

  if (!apiKey) {
    throw new Error(
      `NOWPAYMENTS_${isSandbox ? "SANDBOX_" : ""}API_KEY is not set or is empty.`,
    );
  }

  return apiKey;
}

/**
 * Verify IPN signature from NOWPayments webhook
 */
function verifyIpnSignature(
  payload: string,
  signature: string,
  secret: string,
): boolean {
  const hmac = crypto.createHmac("sha512", secret);
  hmac.update(payload);
  const calculatedSignature = hmac.digest("hex");
  return calculatedSignature === signature;
}

export class NowPaymentsGateway implements IPaymentGateway {
  /**
   * Creates a payment invoice on NOWPayments and returns the invoice URL
   */
  async createPaymentIntent(
    orderId: string | null,
    amount: number,
    currency: string,
    userId: string,
    organizationId: string,
  ): Promise<PaymentIntentResponse> {
    try {
      const apiKey = getNowPaymentsApiKey();
      const baseUrl = getNowPaymentsBaseUrl();
      const appBaseUrl =
        process.env.NEXT_PUBLIC_BASE_URL || "http://localhost:3000";

      // Create an invoice for better UX (hosted payment page)
      const response = await fetch(`${baseUrl}/invoice`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "x-api-key": apiKey,
        },
        body: JSON.stringify({
          price_amount: amount,
          price_currency: currency.toUpperCase(),
          order_id: orderId ?? `ORG-${organizationId}-${Date.now()}`,
          order_description: "Opttius Pro Subscription",
          ipn_callback_url: `${appBaseUrl}/api/webhooks/nowpayments`,
          success_url: `${appBaseUrl}/checkout/result?success=1&orderId=${orderId ?? ""}`,
          cancel_url: `${appBaseUrl}/checkout/result?success=0&orderId=${orderId ?? ""}`,
          // Optional: specify preferred currency (e.g., btc, eth, usdt)
          // pay_currency: "btc",
        }),
      });

      const data = (await response.json()) as {
        id?: string;
        invoice_url?: string;
        order_id?: string;
        payment_status?: string;
        message?: string;
      };

      if (!response.ok || !data.id) {
        logger.error("Error creating NOWPayments invoice", undefined, {
          orderId,
          status: response.status,
          statusText: response.statusText,
          errorData: data,
        });
        throw new Error(
          `NOWPayments Invoice Creation Error (${response.status}): ${data.message ?? response.statusText}`,
        );
      }

      logger.info("NOWPayments invoice created", {
        invoiceId: data.id,
        amount,
        currency,
        organizationId,
      });

      return {
        invoiceUrl: data.invoice_url,
        gatewayPaymentIntentId: data.id,
        paymentId: data.id,
        status: this.mapStatus(data.payment_status ?? "waiting"),
      };
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      logger.error(
        "Error creating NOWPayments invoice",
        error instanceof Error ? error : new Error(errorMessage),
        { orderId, amount, organizationId },
      );
      throw new Error(`NOWPayments error: ${errorMessage}`);
    }
  }

  /**
   * Process IPN (Instant Payment Notification) webhook from NOWPayments
   */
  async processWebhookEvent(request: NextRequest): Promise<WebhookEvent> {
    const ipnSecret = process.env.NOWPAYMENTS_IPN_SECRET;
    if (!ipnSecret) {
      throw new Error("NOWPAYMENTS_IPN_SECRET is not configured.");
    }

    // Get the raw body for signature verification
    const rawBody = await request.text();
    const signature = request.headers.get("x-nowpayments-sig");

    // Verify signature
    if (signature && !verifyIpnSignature(rawBody, signature, ipnSecret)) {
      logger.error("NOWPayments IPN signature verification failed", undefined, {
        signature,
      });
      throw new Error("Invalid IPN signature");
    }

    const event = JSON.parse(rawBody) as {
      payment_id?: string | number;
      invoice_id?: string | number;
      payment_status?: string;
      pay_address?: string;
      price_amount?: number;
      price_currency?: string;
      pay_amount?: number;
      pay_currency?: string;
      order_id?: string;
      order_description?: string;
      actually_paid?: number;
      outcome_amount?: number;
    };

    logger.info("NOWPayments IPN received", {
      paymentId: event.payment_id,
      invoiceId: event.invoice_id,
      status: event.payment_status,
    });

    // Extract data from the IPN
    const paymentId = String(event.payment_id ?? event.invoice_id ?? "");
    const status = event.payment_status ?? "waiting";
    const orderId = event.order_id ?? null;
    const amount = event.price_amount ?? 0;
    const currency = event.price_currency ?? "USD";

    return {
      gateway: "nowpayments",
      gatewayEventId: paymentId,
      type: `payment.${status}`,
      status: this.mapStatus(status),
      gatewayTransactionId: paymentId,
      gatewayPaymentIntentId: String(event.invoice_id ?? paymentId),
      amount,
      currency: currency.toUpperCase(),
      orderId,
      organizationId: null, // Will be resolved from the payment record
      metadata: {
        pay_currency: event.pay_currency,
        pay_amount: event.pay_amount,
        pay_address: event.pay_address,
        actually_paid: event.actually_paid,
        outcome_amount: event.outcome_amount,
      },
    };
  }

  /**
   * Map NOWPayments status to application PaymentStatus
   */
  mapStatus(nowpaymentsStatus: string): PaymentStatus {
    switch (nowpaymentsStatus.toLowerCase()) {
      case "waiting":
      case "confirming":
      case "sending":
        return "pending";
      case "finished":
      case "confirmed":
        return "succeeded";
      case "failed":
      case "expired":
      case "refunded":
        return "failed";
      case "partially_paid":
        // Treat partially paid as pending until full payment
        logger.warn("NOWPayments payment is partially paid", {
          nowpaymentsStatus,
        });
        return "pending";
      default:
        logger.warn("Unknown NOWPayments status mapped to pending", {
          nowpaymentsStatus,
        });
        return "pending";
    }
  }
}

/**
 * PayPal payment gateway implementation (IPaymentGateway).
 *
 * @module lib/payments/paypal/gateway
 */

import type { NextRequest } from "next/server";

import { appLogger as logger } from "@/lib/logger";
import type { PaymentStatus, WebhookEvent } from "@/types/payment";

import type { IPaymentGateway, PaymentIntentResponse } from "../interfaces";

// ponytail: PayPal verify-webhook-signature API handles cert_url server-side,
// no cert fetching needed. Keep this Map if we ever need local cert pinning.
export interface PayPalWebhookHeaders {
  "paypal-auth-algo": string;
  "paypal-cert-url": string;
  "paypal-transmission-id": string;
  "paypal-transmission-sig": string;
  "paypal-transmission-time": string;
}

function getPayPalBaseUrl(): string {
  const base = process.env.PAYPAL_API_BASE_URL;
  if (!base) {
    throw new Error(
      "PAYPAL_API_BASE_URL is not set. Use https://api-m.sandbox.paypal.com for sandbox or https://api-m.paypal.com for production.",
    );
  }
  return base;
}

async function getPayPalAccessToken(): Promise<string> {
  const clientId = process.env.PAYPAL_CLIENT_ID;
  const clientSecret = process.env.PAYPAL_CLIENT_SECRET;
  if (!clientId || !clientSecret) {
    throw new Error(
      "PAYPAL_CLIENT_ID and PAYPAL_CLIENT_SECRET must be set for PayPal.",
    );
  }
  const auth = Buffer.from(`${clientId}:${clientSecret}`).toString("base64");
  const baseUrl = getPayPalBaseUrl();

  const response = await fetch(`${baseUrl}/v1/oauth2/token`, {
    method: "POST",
    headers: {
      "Content-Type": "application/x-www-form-urlencoded",
      Authorization: `Basic ${auth}`,
    },
    body: "grant_type=client_credentials",
  });

  const data = (await response.json()) as {
    access_token?: string;
    error_description?: string;
  };

  if (!response.ok || !data.access_token) {
    logger.error("Failed to get PayPal Access Token", undefined, {
      error: data,
    });
    throw new Error(
      `PayPal Auth Error: ${data.error_description ?? response.statusText}`,
    );
  }

  return data.access_token;
}

export class PayPalGateway implements IPaymentGateway {
  async createPaymentIntent(
    orderId: string | null,
    amount: number,
    currency: string,
    _userId: string,
    organizationId: string,
  ): Promise<PaymentIntentResponse> {
    try {
      const accessToken = await getPayPalAccessToken();
      const baseUrl =
        process.env.NEXT_PUBLIC_BASE_URL || "http://localhost:3000";
      const apiBase = getPayPalBaseUrl();

      const response = await fetch(`${apiBase}/v2/checkout/orders`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${accessToken}`,
        },
        body: JSON.stringify({
          intent: "CAPTURE",
          purchase_units: [
            {
              reference_id: orderId ?? "",
              amount: {
                currency_code: currency.toUpperCase(),
                value: amount.toFixed(2),
              },
              custom_id: organizationId,
            },
          ],
          application_context: {
            return_url: `${baseUrl}/checkout/result?success=1&orderId=${orderId ?? ""}`,
            cancel_url: `${baseUrl}/checkout/result?success=0&orderId=${orderId ?? ""}`,
            user_action: "PAY_NOW",
          },
        }),
      });

      const orderData = (await response.json()) as {
        id?: string;
        links?: Array<{ rel: string; href: string }>;
        message?: string;
        status?: string;
      };

      if (!response.ok || !orderData.id) {
        logger.error("Error creating PayPal Order", undefined, {
          orderId,
          error: orderData,
        });
        throw new Error(
          `PayPal Order Creation Error: ${orderData.message ?? response.statusText}`,
        );
      }

      const approveLink = orderData.links?.find(
        (link) => link.rel === "approve",
      );
      if (!approveLink) {
        throw new Error("PayPal approval link not found.");
      }

      logger.info("PayPal Order created", {
        orderId: orderData.id,
        amount,
        organizationId,
      });

      return {
        approvalUrl: approveLink.href,
        gatewayPaymentIntentId: orderData.id,
        status: this.mapStatus(orderData.status ?? "CREATED"),
      };
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      logger.error(
        "Error creating PayPal Order",
        error instanceof Error ? error : new Error(errorMessage),
        { orderId, amount, organizationId },
      );
      throw new Error(`PayPal error: ${errorMessage}`);
    }
  }

  async processWebhookEvent(request: NextRequest): Promise<WebhookEvent> {
    // PayPal webhook signature verification should be added for production
    // (PAYPAL_WEBHOOK_ID and certificate validation). See PayPal docs.
    const event = (await request.json()) as {
      id?: string;
      event_type?: string;
      resource?: {
        id?: string;
        status?: string;
        purchase_units?: Array<{
          reference_id?: string;
          amount?: { value?: string; currency_code?: string };
        }>;
        amount?: { value?: string; currency_code?: string };
      };
    };

    logger.info("PayPal Webhook received", {
      eventType: event.event_type,
      eventId: event.id,
    });

    if (
      event.resource &&
      event.resource.id &&
      (event.event_type === "CHECKOUT.ORDER.COMPLETED" ||
        event.event_type === "PAYMENT.CAPTURE.COMPLETED")
    ) {
      const orderId =
        event.resource.purchase_units?.[0]?.reference_id ??
        event.resource.id ??
        null;
      const amount = parseFloat(
        event.resource.purchase_units?.[0]?.amount?.value ??
          event.resource.amount?.value ??
          "0",
      );
      const currency =
        event.resource.purchase_units?.[0]?.amount?.currency_code ??
        event.resource.amount?.currency_code ??
        "USD";
      const customId = event.resource.purchase_units?.[0]?.reference_id ?? null;

      return {
        gateway: "paypal",
        gatewayEventId: event.id ?? "",
        type: event.event_type ?? "",
        status: this.mapStatus(event.resource.status ?? "COMPLETED"),
        gatewayTransactionId: event.resource.id ?? null,
        gatewayPaymentIntentId: event.resource.id ?? null,
        amount,
        currency: currency.toUpperCase(),
        orderId,
        organizationId: customId,
        metadata: event as unknown as Record<string, unknown>,
      };
    }

    logger.warn(
      "PayPal Webhook received with unhandled event type or missing data",
      { eventType: event.event_type, eventId: event.id },
    );
    throw new Error("PayPal Webhook: Unhandled event type or missing data");
  }

  async validateWebhookSignature(
    headers: PayPalWebhookHeaders,
    body: string,
  ): Promise<boolean> {
    if (!process.env.PAYPAL_WEBHOOK_ID) {
      logger.warn("PAYPAL_WEBHOOK_ID not configured, rejecting webhook");
      return false;
    }

    try {
      const accessToken = await getPayPalAccessToken();
      const response = await fetch(
        `${getPayPalBaseUrl()}/v1/notifications/verify-webhook-signature`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${accessToken}`,
          },
          body: JSON.stringify({
            auth_algo: headers["paypal-auth-algo"],
            cert_url: headers["paypal-cert-url"],
            transmission_id: headers["paypal-transmission-id"],
            transmission_sig: headers["paypal-transmission-sig"],
            transmission_time: headers["paypal-transmission-time"],
            webhook_id: process.env.PAYPAL_WEBHOOK_ID,
            webhook_event: JSON.parse(body),
          }),
        },
      );

      if (!response.ok) {
        logger.error("PayPal webhook verification API error", undefined, {
          status: response.status,
        });
        return false;
      }

      const result = (await response.json()) as {
        verification_status?: string;
      };
      return result.verification_status === "SUCCESS";
    } catch (error) {
      logger.error(
        "PayPal webhook signature verification failed",
        error instanceof Error ? error : new Error(String(error)),
      );
      return false; // ponytail: fail-closed — reject on any API error
    }
  }

  mapStatus(paypalStatus: string): PaymentStatus {
    switch (paypalStatus) {
      case "CREATED":
      case "SAVED":
      case "APPROVED":
      case "VOIDED":
        return "pending";
      case "COMPLETED":
      case "CAPTURED":
        return "succeeded";
      case "DECLINED":
      case "FAILED":
        return "failed";
      case "REFUNDED":
        return "refunded";
      default:
        logger.warn("Unknown PayPal status mapped to pending", {
          paypalStatus,
        });
        return "pending";
    }
  }
}

import type { SupabaseClient } from "@supabase/supabase-js";

import { sendSaaSNotification } from "@/lib/email/notifications";
import { appLogger as logger } from "@/lib/logger";
import { recordTierChange } from "@/lib/saas/tier-change-audit";
import type { Payment, PaymentGateway } from "@/types/payment";

export async function fulfillOrder(supabase: SupabaseClient, orderId: string): Promise<void> {
  const { data, error } = await supabase.from("orders").update({ status: "completed", updated_at: new Date().toISOString() }).eq("id", orderId).select().single();
  if (error) { logger.error("Failed to fulfill order", error, { orderId }); throw new Error(`Error fulfilling order: ${error.message}`); }
  logger.info("Order fulfilled successfully", { orderId });
}

export async function recordWebhookEventForIdempotency(supabase: SupabaseClient, gateway: PaymentGateway, gatewayEventId: string, eventType: string, paymentId: string | null, metadata?: Record<string, unknown> | null): Promise<boolean> {
  const { data: existing } = await supabase.from("webhook_events").select("id, processed").eq("gateway", gateway).eq("gateway_event_id", gatewayEventId).single();
  if (existing) return existing.processed as boolean;
  await supabase.from("webhook_events").insert({ gateway, gateway_event_id: gatewayEventId, payment_id: paymentId, event_type: eventType, processed: false, metadata: metadata ?? {} });
  return false;
}

export async function processSubscriptionUpdate(supabase: SupabaseClient, organizationId: string, payment: Payment, gatewayPaymentIntentId: string | null, gatewayTransactionId: string | null): Promise<void> {
  type TierName = "basic" | "pro" | "premium";
  const validTiers: TierName[] = ["basic", "pro", "premium"];
  let tier: TierName = "basic";
  const metaTier = payment.metadata?.subscription_tier as string | undefined;
  if (metaTier && validTiers.includes(metaTier as TierName)) tier = metaTier as TierName;
  else {
    const { data: tiers } = await supabase.from("subscription_tiers").select("name, price_monthly").order("price_monthly", { ascending: false });
    const match = (tiers ?? []).find((t: unknown) => Number(t.price_monthly) === payment.amount);
    if (match && validTiers.includes(match.name as TierName)) tier = match.name as TierName;
  }

  const { data: orgBefore } = await supabase.from("organizations").select("subscription_tier").eq("id", organizationId).single();
  const fromTier = (orgBefore?.subscription_tier as TierName) || "basic";

  await supabase.from("organizations").update({ subscription_tier: tier, updated_at: new Date().toISOString() }).eq("id", organizationId);
  await recordTierChange({ organizationId, fromTier, toTier: tier, changedByUserId: null, source: "checkout" });

  const now = new Date();
  const periodStart = new Date(now); periodStart.setHours(0, 0, 0, 0);
  const periodEnd = new Date(now); periodEnd.setMonth(periodEnd.getMonth() + 1); periodEnd.setHours(23, 59, 59, 999);

  const { data: existing } = await supabase.from("subscriptions").select("id, status").eq("organization_id", organizationId).order("created_at", { ascending: false }).limit(1).maybeSingle();

  if (existing) {
    await supabase.from("subscriptions").update({
      status: "active", current_period_start: periodStart.toISOString().slice(0, 10), current_period_end: periodEnd.toISOString().slice(0, 10),
      gateway: payment.gateway, gateway_subscription_id: gatewayPaymentIntentId ?? gatewayTransactionId ?? undefined,
      cancel_at: null, canceled_at: null, updated_at: now.toISOString(),
    }).eq("id", existing.id);
  } else {
    await supabase.from("subscriptions").insert({
      organization_id: organizationId, gateway: payment.gateway, status: "active",
      current_period_start: periodStart.toISOString().slice(0, 10), current_period_end: periodEnd.toISOString().slice(0, 10),
      gateway_subscription_id: gatewayPaymentIntentId ?? gatewayTransactionId ?? null,
    });
  }

  try {
    const { data: orgData } = await supabase.from("organizations").select("name, owner_id").eq("id", organizationId).single();
    if (orgData?.owner_id) {
      const { data: owner } = await supabase.from("profiles").select("email, first_name").eq("id", orgData.owner_id).single();
      if (owner?.email) await sendSaaSNotification("saas_subscription_success", owner.email, { customer_name: owner.first_name || "Admin", organization_name: orgData.name, plan_name: tier.toUpperCase(), amount: payment.amount.toString(), currency: payment.currency, next_billing_date: periodEnd.toLocaleDateString("es-AR") });
    }
  } catch (e) { logger.error("Failed to send success email", e); }
}

/**
 * Business logic for payments and webhook events (DB operations).
 */
import type { SupabaseClient } from "@supabase/supabase-js";

import { appLogger as logger } from "@/lib/logger";
import type { Payment, PaymentCreationAttributes, PaymentGateway, PaymentStatus, WebhookEvent } from "@/types/payment";

import { fulfillOrder, processSubscriptionUpdate, recordWebhookEventForIdempotency } from "./_helpers/paymentSubHelpers";

export class PaymentService {
  private supabase: SupabaseClient;
  constructor(supabase: SupabaseClient) { this.supabase = supabase; }

  async createPayment(data: PaymentCreationAttributes): Promise<Payment> {
    const { data: payment, error } = await this.supabase.from("payments").insert(data as unknown).select().single();
    if (error) { logger.error("Failed to create payment in DB", error, { data }); throw new Error(`Error creating payment: ${error.message}`); }
    return payment as Payment;
  }

  async updatePaymentStatus(paymentId: string, status: PaymentStatus, gatewayTransactionId?: string | null, metadata?: Record<string, unknown> | null, gatewayPaymentIntentId?: string | null): Promise<Payment> {
    const update: unknown = { status, updated_at: new Date().toISOString() };
    if (gatewayTransactionId != null) update.gateway_transaction_id = gatewayTransactionId;
    if (gatewayPaymentIntentId != null) update.gateway_payment_intent_id = gatewayPaymentIntentId;
    if (metadata != null) update.metadata = metadata;
    const { data: payment, error } = await this.supabase.from("payments").update(update).eq("id", paymentId).select().single();
    if (error) { logger.error("Failed to update payment status in DB", error, { paymentId, status }); throw new Error(`Error updating payment status: ${error.message}`); }
    return payment as Payment;
  }

  async getPaymentById(paymentId: string): Promise<Payment | null> {
    const { data, error } = await this.supabase.from("payments").select("*").eq("id", paymentId).single();
    if (error && error.code !== "PGRST116") { logger.error("Error fetching payment by ID", error, { paymentId }); throw new Error(`Error fetching payment: ${error.message}`); }
    return data as Payment | null;
  }

  async getPaymentByGatewayPaymentIntentId(gatewayPaymentIntentId: string): Promise<Payment | null> {
    const { data, error } = await this.supabase.from("payments").select("*").eq("gateway_payment_intent_id", gatewayPaymentIntentId).single();
    if (error && error.code !== "PGRST116") { logger.error("Error fetching payment by gateway intent ID", error, { gatewayPaymentIntentId }); throw new Error(`Error fetching payment: ${error.message}`); }
    return data as Payment | null;
  }

  async updatePaymentFromWebhook(event: WebhookEvent): Promise<void> {
    const paymentIntentId = event.gatewayPaymentIntentId;
    if (!paymentIntentId) { logger.warn("Webhook event missing payment intent ID", { event }); return; }

    const alreadyProcessed = await recordWebhookEventForIdempotency(this.supabase, event.gateway, event.gatewayEventId, event.type, null, event.metadata);
    if (alreadyProcessed) { logger.info("Webhook event already processed", { gateway: event.gateway, eventId: event.gatewayEventId }); return; }

    const payment = await this.getPaymentByGatewayPaymentIntentId(paymentIntentId);
    if (!payment) { logger.warn("No payment found for gateway intent ID", { paymentIntentId }); await this.markWebhookAsProcessed(event.gateway, event.gatewayEventId); return; }

    await this.updatePaymentStatus(payment.id, event.status, event.gatewayTransactionId, event.metadata);

    if (event.status === "succeeded") {
      if (payment.order_id) await fulfillOrder(this.supabase, payment.order_id);
      if (payment.organization_id) await processSubscriptionUpdate(this.supabase, payment.organization_id, { ...payment, status: "succeeded" }, paymentIntentId, event.gatewayTransactionId ?? null);
    }

    await this.markWebhookAsProcessed(event.gateway, event.gatewayEventId);
    logger.info("Payment updated from webhook successfully", { paymentId: payment.id, status: event.status });
  }

  async updateSubscriptionPaymentMethod(organizationId: string, gatewayCustomerId: string, gatewayPaymentMethodId: string): Promise<void> {
    const { data: existing } = await this.supabase.from("subscriptions").select("id").eq("organization_id", organizationId).order("created_at", { ascending: false }).limit(1).maybeSingle();
    if (!existing) { logger.warn("No subscription found to update payment method", { organizationId }); return; }
    const { error } = await this.supabase.from("subscriptions").update({ gateway_customer_id: gatewayCustomerId, gateway_payment_method_id: gatewayPaymentMethodId, updated_at: new Date().toISOString() }).eq("id", existing.id);
    if (error) { logger.error("Failed to update subscription payment method", error, { organizationId }); throw new Error(`Error updating subscription payment method: ${error.message}`); }
  }

  private async markWebhookAsProcessed(gateway: PaymentGateway, gatewayEventId: string): Promise<void> {
    await this.supabase.from("webhook_events").update({ processed: true, processed_at: new Date().toISOString() }).eq("gateway", gateway).eq("gateway_event_id", gatewayEventId);
  }
}

/**
 * Helper functions for handling presbyopia (addition) in prescriptions
 */

export type PresbyopiaSolution =
  | "none"
  | "two_separate"
  | "bifocal"
  | "trifocal"
  | "progressive";

export interface Prescription {
  od_sphere?: number | null;
  os_sphere?: number | null;
  od_cylinder?: number | null;
  os_cylinder?: number | null;
  od_add?: number | null;
  os_add?: number | null;
  prescription_type?: string | null;
}

/**
 * Check if a prescription has addition (presbyopia)
 */
export function hasAddition(
  prescription: Prescription | null | undefined,
): boolean {
  if (!prescription) return false;
  const odAdd = prescription.od_add ?? 0;
  const osAdd = prescription.os_add ?? 0;
  return odAdd > 0 || osAdd > 0;
}

/**
 * Get the maximum addition value from a prescription
 */
export function getMaxAddition(
  prescription: Prescription | null | undefined,
): number {
  if (!prescription) return 0;
  const odAdd = prescription.od_add ?? 0;
  const osAdd = prescription.os_add ?? 0;
  return Math.max(odAdd, osAdd);
}

/**
 * Get the average addition value from a prescription
 */
export function getAverageAddition(
  prescription: Prescription | null | undefined,
): number {
  if (!prescription) return 0;
  const odAdd = prescription.od_add ?? 0;
  const osAdd = prescription.os_add ?? 0;
  if (odAdd === 0 && osAdd === 0) return 0;
  if (odAdd === 0) return osAdd;
  if (osAdd === 0) return odAdd;
  return (odAdd + osAdd) / 2;
}

/**
 * Get sphere values for far vision (highest absolute value)
 */
export function getFarSphere(
  prescription: Prescription | null | undefined,
): number {
  if (!prescription) return 0;
  const odSphere = prescription.od_sphere ?? 0;
  const osSphere = prescription.os_sphere ?? 0;
  return Math.abs(odSphere) >= Math.abs(osSphere) ? odSphere : osSphere;
}

/**
 * Get cylinder value (highest absolute value)
 */
export function getCylinder(
  prescription: Prescription | null | undefined,
): number {
  if (!prescription) return 0;
  const odCylinder = prescription.od_cylinder ?? 0;
  const osCylinder = prescription.os_cylinder ?? 0;
  return Math.abs(odCylinder) >= Math.abs(osCylinder) ? odCylinder : osCylinder;
}

/**
 * Calculate near sphere (far sphere + addition)
 */
export function getNearSphere(
  prescription: Prescription | null | undefined,
): number {
  const farSphere = getFarSphere(prescription);
  const addition = getMaxAddition(prescription);
  return farSphere + addition;
}

/**
 * Get default presbyopia solution based on prescription type
 */
export function getDefaultPresbyopiaSolution(
  prescription: Prescription | null | undefined,
): PresbyopiaSolution {
  if (!prescription || !hasAddition(prescription)) {
    return "none";
  }

  // If prescription_type is set, use it
  if (prescription.prescription_type) {
    const type = prescription.prescription_type.toLowerCase();
    if (type === "progressive") return "progressive";
    if (type === "bifocal") return "bifocal";
    if (type === "trifocal") return "trifocal";
  }

  // Default to progressive for presbyopia
  return "progressive";
}

/**
 * Check if a lens family type matches the presbyopia solution
 */
export function isLensFamilyCompatible(
  lensFamilyType: string | null | undefined,
  solution: PresbyopiaSolution,
): boolean {
  if (!lensFamilyType) return false;

  switch (solution) {
    case "none":
      return (
        lensFamilyType === "single_vision" ||
        lensFamilyType === "reading" ||
        lensFamilyType === "computer"
      );
    case "progressive":
      return lensFamilyType === "progressive";
    case "bifocal":
      return lensFamilyType === "bifocal";
    case "trifocal":
      return lensFamilyType === "trifocal";
    case "two_separate":
      // For two separate lenses, we need one for far and one for near
      return lensFamilyType === "single_vision" || lensFamilyType === "reading";
    default:
      return false;
  }
}

/**
 * Get recommended lens family types for a presbyopia solution
 */
export function getRecommendedLensTypes(
  solution: PresbyopiaSolution,
): string[] {
  switch (solution) {
    case "none":
      return ["single_vision", "reading", "computer", "sports"];
    case "progressive":
      return ["progressive"];
    case "bifocal":
      return ["bifocal"];
    case "trifocal":
      return ["trifocal"];
    case "two_separate":
      return ["single_vision", "reading"];
    default:
      return [];
  }
}

