import { exec } from "child_process";
import fs from "fs";
import os from "os";
import path from "path";
import { promisify } from "util";

import { appLogger as logger } from "@/lib/logger";
import { createServiceRoleClient } from "@/utils/supabase/server";

const execAsync = promisify(exec);

const BUCKET_NAME = "saas-backups";

export interface SaasBackupResult {
  success: boolean;
  backupId: string;
  fileName: string;
  sizeBytes: number;
  durationSeconds: number;
  error?: string;
}

export interface SaasBackupRecord {
  id: string;
  filename: string;
  storage_path: string;
  size_bytes: number;
  size_mb: string;
  backup_type: string;
  status: string;
  created_at: string;
  source: string;
}

export class SaasBackupService {
  /**
   * Generates a 100% full database dump using pg_dump.
   * - Local: uses docker exec supabase_db_web
   * - Production: uses DIRECT_DATABASE_URL (requires pg_dump in env, e.g. GitHub Actions)
   */
  static async generateFullBackup(
    createdBy?: string,
  ): Promise<SaasBackupResult> {
    const startTime = Date.now();
    const backupId = `full_backup_${new Date().toISOString().replace(/[:.]/g, "-")}`;
    const tempFilePath = path.join(os.tmpdir(), `${backupId}.sql`);
    const supabaseService = createServiceRoleClient();

    try {
      logger.info(
        "Iniciando volcado completo de base de datos (SaaS Full Backup)",
      );

      let dumpCommand: string;

      const directUrl = process.env.DIRECT_DATABASE_URL;
      const hasDocker =
        process.env.RUNNING_IN_DOCKER !== "true" && !process.env.VERCEL;

      if (hasDocker) {
        dumpCommand = `docker exec supabase_db_web pg_dump -U postgres postgres > "${tempFilePath}"`;
      } else if (directUrl) {
        dumpCommand = `pg_dump "${directUrl}" --no-owner --no-privileges -F p > "${tempFilePath}"`;
      } else {
        throw new Error(
          "Backup no disponible: requiere Docker (local) o DIRECT_DATABASE_URL con pg_dump (producción). " +
            "Para producción use el backup diario vía GitHub Actions.",
        );
      }

      await execAsync(dumpCommand);

      const fileStats = fs.statSync(tempFilePath);
      const fileBuffer = fs.readFileSync(tempFilePath);

      const fileName = `${backupId}.sql`;

      const { error: uploadError } = await supabaseService.storage
        .from(BUCKET_NAME)
        .upload(fileName, fileBuffer, {
          contentType: "application/sql",
          upsert: false,
        });

      if (uploadError) throw uploadError;

      const { error: insertError } = await supabaseService
        .from("saas_backups")
        .insert({
          filename: fileName,
          storage_path: fileName,
          size_bytes: fileStats.size,
          backup_type: "full",
          status: "completed",
          created_by: createdBy || null,
          source: hasDocker ? "manual" : "cron",
        });

      if (insertError) {
        logger.warn("No se pudo registrar backup en saas_backups", {
          error: insertError.message,
        });
      }

      fs.unlinkSync(tempFilePath);

      const duration = (Date.now() - startTime) / 1000;

      logger.info("SaaS Full Backup completado exitosamente", {
        backupId,
        sizeBytes: fileStats.size,
        durationSeconds: duration,
      });

      return {
        success: true,
        backupId,
        fileName,
        sizeBytes: fileStats.size,
        durationSeconds: duration,
      };
    } catch (error: unknown) {
      logger.error("Error crítico en SaaS Full Backup", {
        error: error.message,
      });

      if (fs.existsSync(tempFilePath)) fs.unlinkSync(tempFilePath);

      return {
        success: false,
        backupId: "",
        fileName: "",
        sizeBytes: 0,
        durationSeconds: (Date.now() - startTime) / 1000,
        error: error.message,
      };
    }
  }

  /**
   * Registers a backup created externally (e.g. by GitHub Actions).
   * The file must already exist in Storage.
   */
  static async registerExternalBackup(
    filename: string,
    sizeBytes: number,
  ): Promise<{ success: boolean; error?: string }> {
    const supabaseService = createServiceRoleClient();

    const { error } = await supabaseService.from("saas_backups").insert({
      filename,
      storage_path: filename,
      size_bytes: sizeBytes,
      backup_type: "full",
      status: "completed",
      source: "github_actions",
    });

    if (error) {
      logger.error("Error registrando backup externo", {
        error: error.message,
      });
      return { success: false, error: error.message };
    }
    return { success: true };
  }

  /**
   * Lists backups from saas_backups table (primary) with fallback to Storage.
   */
  static async listBackups(): Promise<SaasBackupRecord[]> {
    const supabaseService = createServiceRoleClient();

    const { data: tableData, error: tableError } = await supabaseService
      .from("saas_backups")
      .select(
        "id, filename, storage_path, size_bytes, backup_type, status, created_at, source",
      )
      .order("created_at", { ascending: false })
      .limit(100);

    if (!tableError && tableData && tableData.length > 0) {
      return tableData.map((row) => ({
        id: row.id,
        filename: row.filename,
        storage_path: row.storage_path,
        size_bytes: row.size_bytes,
        size_mb: (row.size_bytes / 1024 / 1024).toFixed(2),
        backup_type: row.backup_type,
        status: row.status,
        created_at: row.created_at,
        source: row.source || "manual",
      }));
    }

    const { data: storageData, error: storageError } =
      await supabaseService.storage.from(BUCKET_NAME).list("", {
        sortBy: { column: "created_at", order: "desc" },
      });

    if (storageError || !storageData) return [];

    return storageData.map((file) => ({
      id: file.id || file.name,
      filename: file.name,
      storage_path: file.name,
      size_bytes: file.metadata?.size || file.metadata?.size_bytes || 0,
      size_mb: (
        (file.metadata?.size || file.metadata?.size_bytes || 0) /
        1024 /
        1024
      ).toFixed(2),
      backup_type: "full",
      status: "completed",
      created_at: file.created_at || new Date().toISOString(),
      source: "legacy",
    }));
  }

  /**
   * Deletes a backup (from Storage and saas_backups table).
   */
  static async deleteBackup(fileName: string) {
    const supabaseService = createServiceRoleClient();

    await supabaseService
      .from("saas_backups")
      .delete()
      .eq("filename", fileName);

    const { error } = await supabaseService.storage
      .from(BUCKET_NAME)
      .remove([fileName]);

    if (error) throw error;
    return true;
  }

  /**
   * Generates a signed URL for downloading a backup.
   */
  static async getDownloadUrl(fileName: string) {
    const supabaseService = createServiceRoleClient();
    const { data, error } = await supabaseService.storage
      .from(BUCKET_NAME)
      .createSignedUrl(fileName, 3600);

    if (error) throw error;
    return data?.signedUrl;
  }
}

/**
 * SaaS Audit Log Module
 *
 * Provides functionality to log actions performed by root/dev users
 * in the SaaS Management Engine.
 *
 * @module lib/saas/audit-log
 */

import { appLogger as logger } from "@/lib/logger";
import { createServiceRoleClient } from "@/utils/supabase/server";

export type AuditAction =
  | "create"
  | "update"
  | "delete"
  | "suspend"
  | "activate"
  | "cancel"
  | "change_tier"
  | "extend"
  | "reactivate";

export type AuditTargetType =
  | "organization"
  | "subscription"
  | "tier"
  | "user"
  | "branch"
  | "config";

export interface AuditLogEntry {
  userId?: string;
  userEmail?: string;
  action: AuditAction;
  targetType: AuditTargetType;
  targetId?: string;
  targetName?: string;
  oldValue?: Record<string, unknown>;
  newValue?: Record<string, unknown>;
  ipAddress?: string;
  userAgent?: string;
  metadata?: Record<string, unknown>;
}

/**
 * Record an audit log entry
 */
export async function recordAuditLog(entry: AuditLogEntry): Promise<void> {
  const supabase = createServiceRoleClient();

  const { error } = await supabase.from("saas_audit_log").insert({
    user_id: entry.userId || null,
    user_email: entry.userEmail || null,
    action: entry.action,
    target_type: entry.targetType,
    target_id: entry.targetId || null,
    target_name: entry.targetName || null,
    old_value: entry.oldValue ? JSON.stringify(entry.oldValue) : null,
    new_value: entry.newValue ? JSON.stringify(entry.newValue) : null,
    ip_address: entry.ipAddress || null,
    user_agent: entry.userAgent || null,
    metadata: entry.metadata || {},
  });

  if (error) {
    // Log but don't throw - audit logging should be non-blocking
    logger.error("Failed to record audit log:", error);
  }
}

/**
 * Get audit logs for a specific target
 */
export async function getAuditLogsForTarget(
  targetType: AuditTargetType,
  targetId: string,
  options?: {
    limit?: number;
    offset?: number;
  },
): Promise<{
  logs: Array<{
    id: string;
    userEmail: string | null;
    action: string;
    targetType: string;
    targetId: string | null;
    targetName: string | null;
    oldValue: Record<string, unknown> | null;
    newValue: Record<string, unknown> | null;
    createdAt: string;
  }>;
  total: number;
}> {
  const supabase = createServiceRoleClient();
  const limit = options?.limit || 20;
  const offset = options?.offset || 0;

  const { data, count, error } = await supabase
    .from("saas_audit_log")
    .select("*", { count: "exact" })
    .eq("target_type", targetType)
    .eq("target_id", targetId)
    .order("created_at", { ascending: false })
    .range(offset, offset + limit - 1);

  if (error) {
    throw new Error(`Failed to fetch audit logs: ${error.message}`);
  }

  return {
    logs: (data || []).map((log) => ({
      id: log.id,
      userEmail: log.user_email,
      action: log.action,
      targetType: log.target_type,
      targetId: log.target_id,
      targetName: log.target_name,
      oldValue: log.old_value ? JSON.parse(log.old_value) : null,
      newValue: log.new_value ? JSON.parse(log.new_value) : null,
      createdAt: log.created_at,
    })),
    total: count || 0,
  };
}

/**
 * Get recent audit logs for the SaaS dashboard
 */
export async function getRecentAuditLogs(limit: number = 50): Promise<
  Array<{
    id: string;
    userEmail: string | null;
    action: string;
    targetType: string;
    targetName: string | null;
    createdAt: string;
  }>
> {
  const supabase = createServiceRoleClient();

  const { data, error } = await supabase
    .from("saas_audit_log")
    .select("id, user_email, action, target_type, target_name, created_at")
    .order("created_at", { ascending: false })
    .limit(limit);

  if (error) {
    throw new Error(`Failed to fetch recent audit logs: ${error.message}`);
  }

  return (data || []).map((log) => ({
    id: log.id,
    userEmail: log.user_email,
    action: log.action,
    targetType: log.target_type,
    targetName: log.target_name,
    createdAt: log.created_at,
  }));
}

/**
 * Extract client info from request headers
 */
export function getClientInfoFromRequest(request: Request): {
  ipAddress: string;
  userAgent: string;
} {
  const xForwardedFor = request.headers.get("x-forwarded-for");
  const xRealIp = request.headers.get("x-real-ip");
  const cfConnectingIp = request.headers.get("cf-connecting-ip");

  const ipAddress =
    cfConnectingIp ||
    xForwardedFor?.split(",")[0]?.trim() ||
    xRealIp ||
    "unknown";

  const userAgent = request.headers.get("user-agent") || "unknown";

  return { ipAddress, userAgent };
}

/**
 * Subscription status utilities for SaaS
 * Checks trial expiry, subscription state, etc.
 */

import { createRootAdminClient } from "@/utils/supabase/root-admin";

export type SubscriptionStatus =
  | "active"
  | "trialing"
  | "expired"
  | "past_due"
  | "cancelled"
  | "incomplete"
  | "none";

export interface SubscriptionStatusResult {
  status: SubscriptionStatus;
  isExpired: boolean;
  isTrialExpired: boolean;
  trialEndsAt: Date | null;
  currentPeriodStart: Date | null;
  currentPeriodEnd: Date | null;
  cancelAt: Date | null;
  canceledAt: Date | null;
  organizationId: string | null;
}

/**
 * Get subscription status for an organization
 * CRITICAL: Demo and Root organizations never expire
 */
export async function getSubscriptionStatus(
  organizationId: string,
): Promise<SubscriptionStatusResult> {
  const supabase = createRootAdminClient();

  // CRITICAL: Demo and Root organizations never expire
  // Demo: 00000000-0000-0000-0000-000000000001
  // Root: 00000000-0000-0000-0000-000000000010
  const DEMO_ORG_ID = "00000000-0000-0000-0000-000000000001";
  const ROOT_ORG_ID = "00000000-0000-0000-0000-000000000010";
  const isDemoOrRoot =
    organizationId === DEMO_ORG_ID || organizationId === ROOT_ORG_ID;

  const { data: sub } = await supabase
    .from("subscriptions")
    .select(
      "id, status, trial_ends_at, current_period_start, current_period_end, cancel_at, canceled_at",
    )
    .eq("organization_id", organizationId)
    .in("status", ["active", "trialing", "past_due", "incomplete", "cancelled"])
    .order("created_at", { ascending: false })
    .limit(1)
    .maybeSingle();

  // For demo/root: always return active status, never expired
  if (isDemoOrRoot) {
    return {
      status: "active",
      isExpired: false,
      isTrialExpired: false,
      trialEndsAt: null,
      currentPeriodStart: sub?.current_period_start
        ? new Date(sub.current_period_start)
        : null,
      currentPeriodEnd: sub?.current_period_end
        ? new Date(sub.current_period_end)
        : null,
      cancelAt: null,
      canceledAt: null,
      organizationId,
    };
  }

  // Check organization status: suspended/cancelled orgs must block access
  const { data: org } = await supabase
    .from("organizations")
    .select("status")
    .eq("id", organizationId)
    .maybeSingle();

  if (org?.status === "suspended" || org?.status === "cancelled") {
    return {
      status: "expired",
      isExpired: true,
      isTrialExpired: true,
      trialEndsAt: null,
      currentPeriodStart: null,
      currentPeriodEnd: null,
      cancelAt: null,
      canceledAt: null,
      organizationId,
    };
  }

  if (!sub) {
    return {
      status: "none",
      isExpired: true,
      isTrialExpired: true,
      trialEndsAt: null,
      currentPeriodStart: null,
      currentPeriodEnd: null,
      cancelAt: null,
      canceledAt: null,
      organizationId,
    };
  }

  const now = new Date();
  const trialEndsAt = sub.trial_ends_at ? new Date(sub.trial_ends_at) : null;
  const currentPeriodStart = sub.current_period_start
    ? new Date(sub.current_period_start)
    : null;
  const currentPeriodEnd = sub.current_period_end
    ? new Date(sub.current_period_end)
    : null;
  const cancelAt = sub.cancel_at ? new Date(sub.cancel_at) : null;
  const canceledAt = sub.canceled_at ? new Date(sub.canceled_at) : null;

  // past_due = payment failed, block access until regularized
  if (sub.status === "past_due") {
    return {
      status: "expired",
      isExpired: true,
      isTrialExpired: false,
      trialEndsAt: null,
      currentPeriodStart,
      currentPeriodEnd,
      cancelAt,
      canceledAt,
      organizationId,
    };
  }

  const isTrialExpired =
    sub.status === "trialing" && trialEndsAt !== null && trialEndsAt < now;

  // Cancelled with canceled_at set = immediate block (admin cancelled from saas-management)
  const cancelledImmediately =
    sub.status === "cancelled" && canceledAt !== null;

  // For cancelled subscriptions: access until cancel_at (or current_period_end)
  // If cancel_at is in the future, subscription is still active until then
  const effectiveEndDate =
    sub.status === "cancelled" && cancelAt && cancelAt > now
      ? cancelAt
      : currentPeriodEnd;

  const isExpired =
    cancelledImmediately ||
    isTrialExpired ||
    (sub.status === "cancelled" && cancelAt !== null && cancelAt <= now) ||
    (effectiveEndDate !== null &&
      effectiveEndDate < now &&
      sub.status !== "cancelled");

  let status: SubscriptionStatus = sub.status as SubscriptionStatus;
  if (isTrialExpired) status = "expired";
  else if (isExpired && sub.status !== "cancelled") status = "expired";

  return {
    status,
    isExpired,
    isTrialExpired,
    trialEndsAt,
    currentPeriodStart,
    currentPeriodEnd,
    cancelAt,
    canceledAt,
    organizationId,
  };
}

/**
 * Check if trial has expired (convenience)
 */
export async function isTrialExpired(organizationId: string): Promise<boolean> {
  const result = await getSubscriptionStatus(organizationId);
  return result.isTrialExpired;
}

/**
 * Tier Configuration for SaaS Multi-Tenancy
 *
 * Defines subscription tiers (Basic, Pro, Premium) with their limits and features.
 * This configuration is synchronized with the subscription_tiers table in the database.
 *
 * @module tier-config
 */

export type SubscriptionTier = "basic" | "pro" | "premium";

export type TierFeature =
  | "pos"
  | "appointments"
  | "quotes"
  | "work_orders"
  | "prescriptions"
  | "custom_branding"
  | "chat_ia"
  | "advanced_analytics"
  | "field_operations"
  | "agreements"
  | "whatsapp"
  | "api_access";

export interface TierLimits {
