/**
 * Get tier configuration by tier name
 */
export function getTierConfig(tier: SubscriptionTier): TierLimits {
  return TIER_LIMITS[tier];
}

/**
 * Get next tier (for upgrade suggestions)
 */
export function getNextTier(
  currentTier: SubscriptionTier,
): SubscriptionTier | null {
  const tierOrder: SubscriptionTier[] = ["basic", "pro", "premium"];
  const currentIndex = tierOrder.indexOf(currentTier);
  return currentIndex < tierOrder.length - 1
    ? tierOrder[currentIndex + 1]
    : null;
}

/**
 * Check if a feature is enabled for a tier
 */
export function hasFeature(
  tier: SubscriptionTier,
  feature: TierFeature,
): boolean {
  return TIER_LIMITS[tier].features[feature];
}

/**
 * Check if a limit is unlimited
 */
export function isUnlimited(value: number | "unlimited"): value is "unlimited" {
  return value === "unlimited";
}

/**
 * Compare two tiers to determine if upgrade is available
 */
export function canUpgrade(
  fromTier: SubscriptionTier,
  toTier: SubscriptionTier,
): boolean {
  const tierOrder: SubscriptionTier[] = ["basic", "pro", "premium"];
  return tierOrder.indexOf(toTier) > tierOrder.indexOf(fromTier);
}

import { createServiceRoleClient } from "@/utils/supabase/server";

import { recordTierChange } from "./tier-change-audit";
import {
  getTierConfig,
  isUnlimited,
  SubscriptionTier,
  type TierFeature,
  type TierLimits,
} from "./tier-config";

export type TierLimitType = "branches" | "users" | "customers" | "products";

export interface TierValidationResult {
  allowed: boolean;
  reason?: string;
  currentCount: number;
  maxAllowed: number | "unlimited";
  tier: SubscriptionTier;
}

const DEFAULT_FEATURES: Record<TierFeature, boolean> = {
  pos: true, appointments: true, quotes: true, work_orders: true,
  prescriptions: true, custom_branding: true, chat_ia: false,
  advanced_analytics: false, field_operations: false, agreements: false,
  whatsapp: false, api_access: false,
};

/** Get tier config from DB, fallback to tier-config on error */
export async function getTierConfigFromDb(
  tierName: string,
): Promise<TierLimits | null> {
  const supabase = createServiceRoleClient();

  const { data, error } = await supabase
    .from("subscription_tiers")
    .select(
      "name, price_monthly, max_branches, max_users, max_customers, max_products, features",
    )
    .eq("name", tierName)
    .single();

  if (error || !data) {
    return null;
  }

  const toLimit = (v: number | null | undefined): number | "unlimited" =>
    v == null ? "unlimited" : v;

  const dbFeatures = (data.features as Record<string, boolean>) || {};
  const features: Record<TierFeature, boolean> = { ...DEFAULT_FEATURES };
  for (const [k, v] of Object.entries(dbFeatures)) {
    if (k in DEFAULT_FEATURES && typeof v === "boolean") {
      features[k as TierFeature] = v;
    }
  }

  return {
    name: data.name || tierName,
    price: Number(data.price_monthly) || 0,
    max_branches: toLimit(data.max_branches),
    max_users: toLimit(data.max_users),
    max_customers: toLimit(data.max_customers),
    max_products: toLimit(data.max_products),
    features,
  };
}

async function getTierConfigForValidation(
  tier: SubscriptionTier,
): Promise<TierLimits> {
  const fromDb = await getTierConfigFromDb(tier);
  if (fromDb) return fromDb;
  return getTierConfig(tier);
}

async function getOrganizationTier(
  organizationId: string,
): Promise<SubscriptionTier | null> {
  const supabase = createServiceRoleClient();

  const { data, error } = await supabase
    .from("organizations")
    .select("subscription_tier, scheduled_tier, scheduled_tier_effective_at")
    .eq("id", organizationId)
    .single();

  if (error || !data) {
    return null;
  }

  const now = new Date();
  const effectiveAt = data.scheduled_tier_effective_at
    ? new Date(data.scheduled_tier_effective_at)
    : null;

  // Apply scheduled downgrade if due
  if (
    data.scheduled_tier &&
    effectiveAt &&
    effectiveAt <= now &&
    ["basic", "pro", "premium"].includes(data.scheduled_tier)
  ) {
    const fromTier = data.subscription_tier || "basic";
    const toTier = data.scheduled_tier;

    await supabase
      .from("organizations")
      .update({
        subscription_tier: toTier,
        scheduled_tier: null,
        scheduled_tier_effective_at: null,
        updated_at: now.toISOString(),
      })
      .eq("id", organizationId);

    await recordTierChange({
      organizationId,
      fromTier,
      toTier,
      changedByUserId: null,
      source: "scheduled_job",
    });

    return toTier as SubscriptionTier;
  }

  return (data.subscription_tier || "basic") as SubscriptionTier;
}

async function getCurrentCount(
  organizationId: string,
  limitType: TierLimitType,
): Promise<number> {
  const supabase = createServiceRoleClient();

  switch (limitType) {
    case "branches":
      const { count: branchesCount } = await supabase
        .from("branches")
        .select("*", { count: "exact", head: true })
        .eq("organization_id", organizationId);
      return branchesCount || 0;

    case "users":
      const { count: usersCount } = await supabase
        .from("admin_users")
        .select("*", { count: "exact", head: true })
        .eq("organization_id", organizationId)
        .eq("is_active", true);
      return usersCount || 0;

    case "customers":
      const { count: customersCount } = await supabase
        .from("customers")
        .select("*", { count: "exact", head: true })
        .eq("organization_id", organizationId);
      return customersCount || 0;

    case "products":
      const { count: productsCount } = await supabase
        .from("products")
        .select("*", { count: "exact", head: true })
        .eq("organization_id", organizationId);
      return productsCount || 0;

    default:
      return 0;
  }
}

export async function validateTierLimit(
  organizationId: string,
  limitType: TierLimitType,
  currentCount?: number,
): Promise<TierValidationResult> {
  // Get organization tier
  const tier = await getOrganizationTier(organizationId);
  if (!tier) {
    return {
      allowed: false,
      reason: "Organization not found",
      currentCount: 0,
      maxAllowed: 0,
      tier: "basic",
    };
  }

  // Get tier config (DB first, fallback to tier-config)
  const tierConfig = await getTierConfigForValidation(tier);

  // Get current count if not provided
  const count =
    currentCount ?? (await getCurrentCount(organizationId, limitType));

  // Get max allowed
  let maxAllowed: number | "unlimited";
  switch (limitType) {
    case "branches":
      maxAllowed = tierConfig.max_branches;
      break;
    case "users":
      maxAllowed = tierConfig.max_users;
      break;
    case "customers":
      maxAllowed = tierConfig.max_customers;
      break;
    case "products":
      maxAllowed = tierConfig.max_products;
      break;
  }

  // Check if limit is reached
  const allowed = isUnlimited(maxAllowed) || count < maxAllowed;

  return {
    allowed,
    reason: allowed
      ? undefined
      : `Límite de ${maxAllowed} ${limitType} alcanzado para el tier ${tierConfig.name}`,
    currentCount: count,
    maxAllowed,
    tier,
  };
}

export async function getOrganizationFeatures(
  organizationId: string,
): Promise<Record<string, boolean>> {
  const tier = await getOrganizationTier(organizationId);
  if (!tier) {
    return { ...DEFAULT_FEATURES };
  }
  const tierConfig = await getTierConfigForValidation(tier);
  return { ...tierConfig.features };
}

export async function validateFeature(
  organizationId: string,
  feature: string,
): Promise<boolean> {
  const tier = await getOrganizationTier(organizationId);
  if (!tier) {
    return false;
  }

  const tierConfig = await getTierConfigForValidation(tier);
  return (
    tierConfig.features[feature as keyof typeof tierConfig.features] ?? false
  );
}

export function getTierUpgradeMessage(
  tier: SubscriptionTier,
  limitType: TierLimitType,
): string {
  const tierConfig = getTierConfig(tier);
  const nextTier =
    tier === "premium" ? null : tier === "basic" ? "pro" : "premium";

  if (!nextTier) {
    return "Ya tienes el tier máximo disponible.";
  }

  const nextTierConfig = getTierConfig(nextTier);
  let nextLimit: number | "unlimited";

  switch (limitType) {
    case "branches":
      nextLimit = nextTierConfig.max_branches;
      break;
    case "users":
      nextLimit = nextTierConfig.max_users;
      break;
    case "customers":
      nextLimit = nextTierConfig.max_customers;
      break;
    case "products":
      nextLimit = nextTierConfig.max_products;
      break;
  }

  const nextLimitText = isUnlimited(nextLimit)
    ? "ilimitado"
    : nextLimit.toString();

  return `Upgrade a ${nextTierConfig.name} para obtener hasta ${nextLimitText} ${limitType}.`;
}

/**
 * Security Alerting — Channel Dispatch
 *
 * Handles sending security alerts to configured notification channels
 * including email, Slack, PagerDuty, and webhooks.
 *
 * @module lib/security/alerting/dispatch
 */

import axios from "axios";

import { appLogger as logger } from "@/lib/logger";

import {
  AlertChannel,
  EmailAlertConfig,
  PagerDutyAlertConfig,
  SecurityAlert,
  SlackAlertConfig,
  WebhookAlertConfig,
} from "../events";

export async function sendToChannel(
  channel: AlertChannel,
  alert: SecurityAlert,
): Promise<void> {
  if (!channel.enabled) return;

  try {
    switch (channel.type) {
      case "email":
        await sendEmailAlert(
          channel as AlertChannel & { config: EmailAlertConfig },
          alert,
        );
        break;
      case "slack":
        await sendSlackAlert(
          channel as AlertChannel & { config: SlackAlertConfig },
          alert,
        );
        break;
      case "pagerduty":
        await sendPagerDutyAlert(
          channel as AlertChannel & { config: PagerDutyAlertConfig },
          alert,
        );
        break;
      case "webhook":
        await sendWebhookAlert(
          channel as AlertChannel & { config: WebhookAlertConfig },
          alert,
        );
        break;
      default:
        logger.warn("Unknown alert channel type", { type: channel.type });
    }
  } catch (error) {
    logger.error(`Failed to send alert to ${channel.type} channel`, error);
  }
}

async function sendEmailAlert(
  channel: AlertChannel & { config: EmailAlertConfig },
  alert: SecurityAlert,
): Promise<void> {
  const mailOptions = {
    from: channel.config.smtp.auth.user,
    to: channel.config.recipients.join(", "),
    subject: `[SECURITY ALERT] ${alert.title}`,
    html: `
      <h2>Security Alert: ${alert.title}</h2>
      <p><strong>Severity:</strong> ${alert.severity.toUpperCase()}</p>
      <p><strong>Description:</strong> ${alert.description}</p>
      <p><strong>Time:</strong> ${new Date(alert.timestamp).toLocaleString()}</p>

      ${
        alert.relatedEvents.length > 0
          ? `
        <h3>Related Events (${alert.relatedEvents.length})</h3>
        <ul>
          ${alert.relatedEvents
            .map(
              (event) => `
            <li>${event.eventType} - ${event.ipAddress || "Unknown IP"}</li>
          `,
            )
            .join("")}
        </ul>
      `
          : ""
      }

      ${
        alert.recommendedActions.length > 0
          ? `
        <h3>Recommended Actions</h3>
        <ul>
          ${alert.recommendedActions.map((action) => `<li>${action}</li>`).join("")}
        </ul>
      `
          : ""
      }

      <hr>
      <p><small>Alert ID: ${alert.id}</small></p>
    `,
  };

  // ponytail: mock transporter, replace with nodemailer when actual SMTP is configured
  const transporter = {
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    sendMail: async (_mailOptions: Record<string, unknown>) => {
      logger.debug("Email alert sent", {
        to: channel.config.recipients.length,
        subject: mailOptions.subject,
      });
      return { messageId: "mock-message-id" };
    },
  };

  await transporter.sendMail(mailOptions);
}

async function sendSlackAlert(
  channel: AlertChannel & { config: SlackAlertConfig },
  alert: SecurityAlert,
): Promise<void> {
  const severityColor: Record<string, string> = {
    low: "#36a64f",
    medium: "#f2c744",
    high: "#ff6600",
    critical: "#e01e5a",
  };

  const payload = {
    channel: channel.config.channel,
    username: channel.config.username || "Security Bot",
    icon_emoji: channel.config.iconEmoji || ":rotating_light:",
    attachments: [
      {
        color: severityColor[alert.severity] || "#cccccc",
        title: `Security Alert: ${alert.title}`,
        fields: [
          {
            title: "Severity",
            value: alert.severity.toUpperCase(),
            short: true,
          },
          {
            title: "Time",
            value: new Date(alert.timestamp).toLocaleString(),
            short: true,
          },
          {
            title: "Description",
            value: alert.description,
            short: false,
          },
        ],
        footer: `Alert ID: ${alert.id}`,
      },
    ],
  };

  await axios.post(channel.config.webhookUrl, payload);
  logger.debug("Slack alert sent", { channelId: channel.id });
}

async function sendPagerDutyAlert(
  channel: AlertChannel & { config: PagerDutyAlertConfig },
  alert: SecurityAlert,
): Promise<void> {
  const payload = {
    payload: {
      summary: `${alert.title} - ${alert.description}`,
      severity: alert.severity,
      source: "opttius-security-monitoring",
      timestamp: alert.timestamp,
      custom_details: {
        alertId: alert.id,
        relatedEvents: alert.relatedEvents.length,
        recommendedActions: alert.recommendedActions,
      },
    },
    routing_key: channel.config.integrationKey,
    event_action: "trigger",
    dedup_key: `security-alert-${alert.id}`,
  };

  await axios.post("https://events.pagerduty.com/v2/enqueue", payload);
  logger.debug("PagerDuty alert sent", { channelId: channel.id });
}

async function sendWebhookAlert(
  channel: AlertChannel & { config: WebhookAlertConfig },
  alert: SecurityAlert,
): Promise<void> {
  const payload = {
    alert: {
      id: alert.id,
      title: alert.title,
      description: alert.description,
      severity: alert.severity,
      timestamp: alert.timestamp,
      status: alert.status,
      relatedEvents: alert.relatedEvents,
      recommendedActions: alert.recommendedActions,
    },
  };

  await axios({
    method: channel.config.method,
    url: channel.config.url,
    data: payload,
    headers: {
      "Content-Type": "application/json",
      ...channel.config.headers,
    },
  });

  logger.debug("Webhook alert sent", { channelId: channel.id });
}

/**
 * Security Alerting System
 *
 * Manages security alert routing and notification delivery across multiple channels.
 * Provides configurable alert thresholds, deduplication, and escalation procedures.
 *
 * @module lib/security/alerting
 */

import { appLogger as logger } from "@/lib/logger";

import {
  AlertChannel,
  SecurityAlert,
  SecurityEvent,
  SecuritySeverity,
} from "../events";
import { sendToChannel } from "./dispatch";
import {
  addToHistory,
  cleanupOldAlerts,
  getChannelsForSeverity,
  shouldDeduplicate,
} from "./rules";

// Re-export dispatch and rules
export { sendToChannel } from "./dispatch";
export {
  addToHistory,
  calculateStringSimilarity,
  cleanupOldAlerts,
  getChannelsForSeverity,
  shouldDeduplicate,
} from "./rules";

export class SecurityAlerting {
  private channels: AlertChannel[] = [];
  private alertHistory: SecurityAlert[] = [];
  private readonly ALERT_HISTORY_LIMIT = 1000;
  private readonly DEDUPLICATION_WINDOW = 5 * 60 * 1000; // 5 minutes

  constructor(channels: AlertChannel[] = []) {
    this.channels = channels;
  }

  /**
   * Send a security alert through configured channels
   */
  async sendAlert(
    title: string,
    description: string,
    severity: SecuritySeverity,
    relatedEvents: SecurityEvent[] = [],
    recommendedActions: string[] = [],
  ): Promise<void> {
    if (
      shouldDeduplicate(
        this.alertHistory,
        title,
        severity,
        this.DEDUPLICATION_WINDOW,
      )
    ) {
      logger.debug("Alert deduplicated", { title, severity });
      return;
    }

    const alert: SecurityAlert = {
      id: `alert_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      title,
      description,
      severity,
      timestamp: new Date().toISOString(),
      relatedEvents,
      recommendedActions,
      status: "active",
    };

    this.alertHistory = addToHistory(
      this.alertHistory,
      alert,
      this.ALERT_HISTORY_LIMIT,
    );

    const eligibleChannels = getChannelsForSeverity(this.channels, severity);

    if (eligibleChannels.length === 0) {
      logger.warn("No alert channels configured for severity", { severity });
      return;
    }

    logger.info("Sending security alert", {
      alertId: alert.id,
      title: alert.title,
      severity: alert.severity,
      channelCount: eligibleChannels.length,
    });

    const sendPromises = eligibleChannels.map((channel) =>
      sendToChannel(channel, alert),
    );

    try {
      await Promise.allSettled(sendPromises);
    } catch (error) {
      logger.error("Error sending security alerts", error);
    }
  }

  /**
   * Add alert channel configuration
   */
  addChannel(channel: AlertChannel): void {
    this.channels.push(channel);
    logger.info("Alert channel added", {
      channelId: channel.id,
      type: channel.type,
      severityThreshold: channel.severityThreshold,
    });
  }

  /**
   * Remove alert channel
   */
  removeChannel(channelId: string): boolean {
    const initialLength = this.channels.length;
    this.channels = this.channels.filter((c) => c.id !== channelId);
    return this.channels.length < initialLength;
  }

  /**
   * Update alert channel configuration
   */
  updateChannel(channelId: string, updates: Partial<AlertChannel>): boolean {
    const channel = this.channels.find((c) => c.id === channelId);
    if (channel) {
      Object.assign(channel, updates);
      logger.info("Alert channel updated", { channelId, updates });
      return true;
    }
    return false;
  }

  /**
   * Get alert history with optional filters
   */
  getAlertHistory(filter?: {
    severity?: SecuritySeverity;
    status?: SecurityAlert["status"];
    timeframe?: number;
  }): SecurityAlert[] {
    let alerts = [...this.alertHistory].reverse();

    if (filter) {
      if (filter.severity) {
        alerts = alerts.filter((a) => a.severity === filter.severity);
      }
      if (filter.status) {
        alerts = alerts.filter((a) => a.status === filter.status);
      }
      if (filter.timeframe) {
        const cutoffTime = Date.now() - filter.timeframe;
        alerts = alerts.filter(
          (a) => new Date(a.timestamp).getTime() > cutoffTime,
        );
      }
    }

    return alerts;
  }

  /**
   * Acknowledge an alert
   */
  acknowledgeAlert(alertId: string, acknowledgedBy: string): boolean {
    const alert = this.alertHistory.find((a) => a.id === alertId);
    if (alert && alert.status === "active") {
      alert.status = "acknowledged";
      alert.acknowledgedBy = acknowledgedBy;
      alert.acknowledgedAt = new Date().toISOString();
      logger.info("Alert acknowledged", { alertId, acknowledgedBy });
      return true;
    }
    return false;
  }

  /**
   * Resolve an alert
   */
  resolveAlert(alertId: string, resolutionNotes?: string): boolean {
    const alert = this.alertHistory.find((a) => a.id === alertId);
    if (
      alert &&
      (alert.status === "active" || alert.status === "acknowledged")
    ) {
      alert.status = "resolved";
      alert.resolutionNotes = resolutionNotes;
      logger.info("Alert resolved", { alertId, resolutionNotes });
      return true;
    }
    return false;
  }

  /**
   * Get alert statistics within a timeframe
   */
  getAlertStats(timeframe: number = 24 * 60 * 60 * 1000): {
    totalAlerts: number;
    alertsBySeverity: Record<SecuritySeverity, number>;
    alertsByStatus: Record<SecurityAlert["status"], number>;
    averageResponseTime: number;
  } {
    const cutoffTime = Date.now() - timeframe;
    const recentAlerts = this.alertHistory.filter(
      (a) => new Date(a.timestamp).getTime() > cutoffTime,
    );

    const stats = {
      totalAlerts: recentAlerts.length,
      alertsBySeverity: {
        low: 0,
        medium: 0,
        high: 0,
        critical: 0,
      } as Record<SecuritySeverity, number>,
      alertsByStatus: {
        active: 0,
        acknowledged: 0,
        resolved: 0,
        dismissed: 0,
      } as Record<SecurityAlert["status"], number>,
      averageResponseTime: 0,
    };

    let totalResponseTime = 0;
    let resolvedCount = 0;

    for (const alert of recentAlerts) {
      stats.alertsBySeverity[alert.severity]++;
      stats.alertsByStatus[alert.status]++;

      if (alert.acknowledgedAt) {
        const createTime = new Date(alert.timestamp).getTime();
        const ackTime = new Date(alert.acknowledgedAt).getTime();
        totalResponseTime += ackTime - createTime;
        resolvedCount++;
      }
    }

    stats.averageResponseTime =
      resolvedCount > 0 ? Math.round(totalResponseTime / resolvedCount) : 0;

    return stats;
  }

  /**
   * Clean up old alerts based on retention policy
   */
  cleanupOldAlerts(retentionDays: number = 90): void {
    const initialLength = this.alertHistory.length;
    this.alertHistory = cleanupOldAlerts(this.alertHistory, retentionDays);

    if (initialLength > this.alertHistory.length) {
      logger.info("Cleaned up old alerts", {
        removedCount: initialLength - this.alertHistory.length,
        retentionDays,
      });
    }
  }
}

// Export singleton instance
let securityAlerting: SecurityAlerting | null = null;

export function getSecurityAlerting(): SecurityAlerting {
  if (!securityAlerting) {
    securityAlerting = new SecurityAlerting();
  }
  return securityAlerting;
}

/**
 * Security Alerting — Rules Engine
 *
 * Alert deduplication, severity routing, and lifecycle management helpers.
 *
 * @module lib/security/alerting/rules
 */

import { AlertChannel, SecurityAlert, SecuritySeverity } from "../events";

/**
 * Get channels eligible for a given severity level
 */
export function getChannelsForSeverity(
  channels: AlertChannel[],
  severity: SecuritySeverity,
): AlertChannel[] {
  const severityLevels: SecuritySeverity[] = [
    "low",
    "medium",
    "high",
    "critical",
  ];
  const severityIndex = severityLevels.indexOf(severity);

  return channels.filter((channel) => {
    const channelSeverityIndex = severityLevels.indexOf(
      channel.severityThreshold,
    );
    return channel.enabled && severityIndex >= channelSeverityIndex;
  });
}

/**
 * Check if an alert should be deduplicated based on recent history
 */
export function shouldDeduplicate(
  alertHistory: SecurityAlert[],
  title: string,
  severity: SecuritySeverity,
  dedupWindowMs: number,
): boolean {
  const now = Date.now();
  const cutoffTime = now - dedupWindowMs;

  return alertHistory.some((alert) => {
    if (new Date(alert.timestamp).getTime() < cutoffTime) return false;

    const similarity = calculateStringSimilarity(alert.title, title);
    return similarity > 0.8 && alert.severity === severity;
  });
}

/**
 * Add alert to history, keeping within the configured limit
 */
export function addToHistory(
  alertHistory: SecurityAlert[],
  alert: SecurityAlert,
  limit: number,
): SecurityAlert[] {
  const updated = [alert, ...alertHistory];
  return updated.length > limit ? updated.slice(0, limit) : updated;
}

/**
 * Remove alerts older than the retention period
 */
export function cleanupOldAlerts(
  alertHistory: SecurityAlert[],
  retentionDays: number,
): SecurityAlert[] {
  const cutoffDate = new Date();
  cutoffDate.setDate(cutoffDate.getDate() - retentionDays);
  const cutoffTimestamp = cutoffDate.getTime();

  return alertHistory.filter(
    (alert) => new Date(alert.timestamp).getTime() > cutoffTimestamp,
  );
}

/**
 * Calculate string similarity (0..1) using Levenshtein distance
 */
export function calculateStringSimilarity(str1: string, str2: string): number {
  const longer = str1.length > str2.length ? str1 : str2;
  const shorter = str1.length > str2.length ? str2 : str1;

  if (longer.length === 0) return 1.0;

  const distance = levenshteinDistance(longer, shorter);
  return (longer.length - distance) / longer.length;
}

/**
 * Calculate Levenshtein distance between two strings
 */
function levenshteinDistance(str1: string, str2: string): number {
  const matrix: number[][] = Array(str2.length + 1)
    .fill(null)
    .map(() => Array(str1.length + 1).fill(null));

  for (let i = 0; i <= str1.length; i++) matrix[0][i] = i;
  for (let j = 0; j <= str2.length; j++) matrix[j][0] = j;

  for (let j = 1; j <= str2.length; j++) {
    for (let i = 1; i <= str1.length; i++) {
      const cost = str1[i - 1] === str2[j - 1] ? 0 : 1;
      matrix[j][i] = Math.min(
        matrix[j][i - 1] + 1,
        matrix[j - 1][i] + 1,
        matrix[j - 1][i - 1] + cost,
      );
    }
  }

  return matrix[str2.length][str1.length];
}

/**
 * Behavioral Analytics Engine
 *
 * Implements user behavior analytics (UBA) for detecting anomalous activities
 * and potential security threats through pattern analysis.
 *
 * @module lib/security/behavioral-analytics
 */

import { appLogger as logger } from "@/lib/logger";
import { getRedisClient } from "@/lib/redis/client";

import { SecurityEvent } from "../events";
import { AnomalyDetector, DeviceFingerprintDetector, FrequencyAnomalyDetector, LocationAnomalyDetector, ResourceAccessAnomalyDetector, TimingAnomalyDetector } from "./analyzers";
import { createInitialBaseline, updateActionPatterns, updateLoginPatterns, updateRiskProfile } from "./baseline";
import {
  ANOMALY_THRESHOLD,
  AnomalyRecord,
  BASELINE_EXPIRY,
  BEHAVIOR_REDIS_PREFIX,
  BehaviorBaseline,
  HIGH_RISK_THRESHOLD,
  ThreatAssessment,
  UserAction,
} from "./types";

// Re-export all types and utilities
export { AnomalyDetector, DeviceFingerprintDetector, FrequencyAnomalyDetector, LocationAnomalyDetector, ResourceAccessAnomalyDetector, TimingAnomalyDetector } from "./analyzers";
export type { AnomalyRecord, BehaviorBaseline, ThreatAssessment, UserAction } from "./types";

/**
 * Behavioral Analytics Engine
 */
export class BehavioralAnalytics {
  private baselines: Map<string, BehaviorBaseline> = new Map();
  private anomalyDetectors: AnomalyDetector[] = [];

  constructor() {
    this.initializeDetectors();
  }

  private initializeDetectors(): void {
    this.anomalyDetectors = [
      new FrequencyAnomalyDetector(),
      new TimingAnomalyDetector(),
      new LocationAnomalyDetector(),
      new ResourceAccessAnomalyDetector(),
      new DeviceFingerprintDetector(),
    ];
  }

  /**
   * Record user action for behavioral analysis
   */
  async recordUserAction(action: UserAction): Promise<void> {
    try {
      const actionKey = `${BEHAVIOR_REDIS_PREFIX}actions:${action.userId}:${Date.now()}`;
      await getRedisClient().setex(
        actionKey,
        60 * 60 * 24,
        JSON.stringify(action),
      );

      await this.updateUserBaseline(action);

      const anomalies = await this.detectAnomalies(action);

      if (anomalies.length > 0) {
        const threatAssessment = await this.assessThreat(
          action.userId,
          anomalies,
        );
        await this.handleAnomalies(threatAssessment);
      }

      logger.debug("User action recorded for behavioral analysis", {
        userId: action.userId,
        actionType: action.actionType,
        anomaliesDetected: anomalies.length,
      });
    } catch (error) {
      logger.error("Failed to record user action", {
        error: error instanceof Error ? error.message : "Unknown error",
        userId: action.userId,
        actionType: action.actionType,
      });
    }
  }

  /**
   * Update user behavior baseline
   */
  private async updateUserBaseline(action: UserAction): Promise<void> {
    const baselineKey = `${BEHAVIOR_REDIS_PREFIX}baseline:${action.userId}`;
    let baseline: BehaviorBaseline;

    try {
      const existingBaseline = await getRedisClient().get(baselineKey);
      if (existingBaseline) {
        baseline = JSON.parse(existingBaseline);
      } else {
        baseline = createInitialBaseline(action.userId);
      }

      updateActionPatterns(baseline, action);

      if (action.actionType === "login") {
        updateLoginPatterns(baseline, action);
      }

      updateRiskProfile(baseline, action);

      await getRedisClient().setex(
        baselineKey,
        BASELINE_EXPIRY,
        JSON.stringify(baseline),
      );

      this.baselines.set(action.userId, baseline);
    } catch (error) {
      logger.error("Failed to update user baseline", {
        error: error instanceof Error ? error.message : "Unknown error",
        userId: action.userId,
      });
    }
  }

  /**
   * Detect anomalies in user behavior
   */
  private async detectAnomalies(action: UserAction): Promise<AnomalyRecord[]> {
    const anomalies: AnomalyRecord[] = [];

    for (const detector of this.anomalyDetectors) {
      const detectorAnomalies = await detector.detect(
        action,
        this.baselines.get(action.userId),
      );
      anomalies.push(...detectorAnomalies);
    }

    return anomalies;
  }

  /**
   * Assess overall threat level for user
   */
  private async assessThreat(
    userId: string,
    anomalies: AnomalyRecord[],
  ): Promise<ThreatAssessment> {
    const baseline =
      this.baselines.get(userId) || createInitialBaseline(userId);

    let riskScore =
      baseline.riskProfile.baselineRisk +
      baseline.riskProfile.recentActivityScore;

    for (const anomaly of anomalies) {
      riskScore +=
        anomaly.confidence * this.getSeverityWeight(anomaly.severity);
    }

    riskScore = Math.min(riskScore, 1.0);

    const recommendedActions: string[] = [];
    const immediateActions: string[] = [];

    if (riskScore > HIGH_RISK_THRESHOLD) {
      immediateActions.push("Require additional authentication");
      immediateActions.push("Temporarily suspend account access");
      immediateActions.push("Notify security team immediately");
      recommendedActions.push("Conduct security interview with user");
    } else if (riskScore > ANOMALY_THRESHOLD) {
      recommendedActions.push("Increase monitoring frequency");
      recommendedActions.push("Send security notification to user");
      recommendedActions.push("Review recent account activity");
    }

    return {
      userId,
      riskScore,
      anomalies,
      recommendedActions,
      immediateActions,
    };
  }

  /**
   * Handle detected anomalies
   */
  private async handleAnomalies(assessment: ThreatAssessment): Promise<void> {
    const securityEvent: SecurityEvent = {
      id: `anomaly_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      timestamp: new Date().toISOString(),
      eventType: "behavior.user_anomaly",
      severity: assessment.riskScore > HIGH_RISK_THRESHOLD ? "high" : "medium",
      source: "behavioral-analytics",
      userId: assessment.userId,
      details: {
        riskScore: assessment.riskScore,
        anomalies: assessment.anomalies,
        recommendedActions: assessment.recommendedActions,
        immediateActions: assessment.immediateActions,
      },
    };

    if (assessment.riskScore > ANOMALY_THRESHOLD) {
      logger.warn("Behavioral anomaly detected", {
        userId: assessment.userId,
        riskScore: assessment.riskScore,
        anomalyCount: assessment.anomalies.length,
      });
    }

    const assessmentKey = `${BEHAVIOR_REDIS_PREFIX}assessments:${assessment.userId}:${Date.now()}`;
    await getRedisClient().setex(
      assessmentKey,
      60 * 60 * 24 * 7,
      JSON.stringify(assessment),
    );
  }

  private getSeverityWeight(severity: string): number {
    const weights: Record<string, number> = {
      low: 0.1,
      medium: 0.3,
      high: 0.6,
      critical: 1.0,
    };
    return weights[severity] || 0.1;
  }

  /**
   * Get user behavior baseline
   */
  async getUserBaseline(userId: string): Promise<BehaviorBaseline | null> {
    if (this.baselines.has(userId)) {
      return this.baselines.get(userId)!;
    }

    const baselineKey = `${BEHAVIOR_REDIS_PREFIX}baseline:${userId}`;
    try {
      const baselineData = await getRedisClient().get(baselineKey);
      if (baselineData) {
        const baseline = JSON.parse(baselineData);
        this.baselines.set(userId, baseline);
        return baseline;
      }
    } catch (error) {
      logger.error("Failed to retrieve user baseline", {
        error: error instanceof Error ? error.message : "Unknown error",
        userId,
      });
    }

    return null;
  }
}

