import { useCallback, useEffect, useState } from "react";

import { appLogger } from '@/lib/logger';

import { useTelemetry } from "./use-telemetry";

interface AnalyticsOverview {
  totalUsers: number;
  activeUsers: number;
  totalEvents: number;
  avgSessionDuration: number;
}

interface FeatureUsage {
  name: string;
  usage: number;
  growth: number;
}

interface AnalyticsData {
  overview: AnalyticsOverview;
  topFeatures: FeatureUsage[];
  error?: string;
}

interface UseAnalyticsDataOptions {
  timeRange?: "7d" | "30d" | "90d";
  autoRefreshInterval?: number; // in milliseconds
  enabled?: boolean;
}

export function useAnalyticsData({
  timeRange = "7d",
  autoRefreshInterval = 30000, // 30 seconds
  enabled = true,
}: UseAnalyticsDataOptions = {}) {
  const [data, setData] = useState<AnalyticsData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const { trackFeatureUsage, trackError } = useTelemetry("use-analytics-data");

  const fetchData = useCallback(async () => {
    if (!enabled) return;

    try {
      setLoading(true);
      setError(null);

      const days = timeRange === "7d" ? 7 : timeRange === "30d" ? 30 : 90;
      const response = await fetch(`/api/telemetry/dashboard?days=${days}`);

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const rawData = await response.json();

      // Transform the raw data to our expected format
      const transformedData: AnalyticsData = {
        overview: {
          totalUsers: rawData.overview?.totalUsers || 0,
          activeUsers: rawData.overview?.activeUsers || 0,
          totalEvents: rawData.overview?.totalEvents || 0,
          avgSessionDuration: rawData.overview?.avgSessionDuration || 0,
        },
        topFeatures: rawData.topFeatures?.slice(0, 5) || [],
      };

      setData(transformedData);

      // Track successful data fetch
      trackFeatureUsage("analytics_data_fetched", {
        timeRange,
        totalUsers: transformedData.overview.totalUsers,
        featureCount: transformedData.topFeatures.length,
      });
    } catch (err) {
      const errorMessage =
        err instanceof Error ? err.message : "Failed to fetch analytics data";
      setError(errorMessage);
      trackError(err as Error, {
        context: "analytics_data_fetch",
        timeRange,
      });
      appLogger.error("Analytics data fetch error:", err);
    } finally {
      setLoading(false);
    }
  }, [timeRange, enabled, trackFeatureUsage, trackError]);

  // Initial data fetch
  useEffect(() => {
    fetchData();
  }, [fetchData]);

  // Auto-refresh functionality
  useEffect(() => {
    if (!enabled || autoRefreshInterval <= 0) return;

    const intervalId = setInterval(() => {
      fetchData();
    }, autoRefreshInterval);

    return () => clearInterval(intervalId);
  }, [fetchData, autoRefreshInterval, enabled]);

  // Manual refresh function
  const refresh = useCallback(() => {
    trackFeatureUsage("analytics_manual_refresh", { timeRange });
    fetchData();
  }, [fetchData, timeRange, trackFeatureUsage]);

  return {
    data,
    loading,
    error,
    refresh,
    timeRange,
  };
}

import { useCallback, useEffect, useRef } from "react";

import { appLogger } from '@/lib/logger';

import { telemetryCollector } from "../collector/browser-collector";

/**
 * Hook for tracking page views automatically
 */
export function usePageTracking() {
  useEffect(() => {
    // Track page view when component mounts
    const pageViewId = telemetryCollector.trackPageView({
      pageUrl: typeof window !== "undefined" ? window.location.pathname : "/",
      pageTitle: typeof document !== "undefined" ? document.title : "",
      referrer: typeof document !== "undefined" ? document.referrer : "",
    });

    // Clean up when component unmounts
    return () => {
      // Could track page leave time here if needed
    };
  }, []); // Empty dependency array means this runs once per page load
}

/**
 * Hook for tracking feature usage
 */
export function useFeatureTracking(featureName: string) {
  const trackInteraction = useCallback(
    (action: string, details?: unknown) => {
      telemetryCollector.trackFeatureUsage(featureName, action, details);
    },
    [featureName],
  );

  // Also provide a direct feature usage tracker
  const trackFeatureUsage = useCallback(
    (action: string, details?: unknown) => {
      telemetryCollector.trackFeatureUsage(featureName, action, details);
    },
    [featureName],
  );

  return { trackInteraction, trackFeatureUsage };
}

/**
 * Hook for tracking user interactions with DOM elements
 */
export function useInteractionTracking() {
  const trackClick = useCallback(
    (elementName: string, target?: string, value?: string) => {
      telemetryCollector.trackUserInteraction({
        element: elementName,
        action: "click",
        target,
        value,
      });
    },
    [],
  );

  const trackInputChange = useCallback(
    (elementName: string, value?: string) => {
      telemetryCollector.trackUserInteraction({
        element: elementName,
        action: "input",
        value,
      });
    },
    [],
  );

  return { trackClick, trackInputChange };
}

/**
 * Hook for performance monitoring
 */
export function usePerformanceMetrics() {
  useEffect(() => {
    // Only run in browser environment
    if (
      typeof window === "undefined" ||
      typeof PerformanceObserver === "undefined"
    ) {
      return;
    }

    // Track Core Web Vitals
    const observer = new PerformanceObserver((list) => {
      list.getEntries().forEach((entry) => {
        switch (entry.entryType) {
          case "navigation":
            telemetryCollector.trackNavigationTiming(entry.toJSON());
            break;

          case "paint":
            if (entry.name === "first-contentful-paint") {
              telemetryCollector.trackUserInteraction({
                element: "performance",
                action: "fcp_measured",
                value: entry.startTime.toString(),
              });
            }
            break;

          case "largest-contentful-paint":
            if (entry.name === "largest-contentful-paint") {
              telemetryCollector.trackUserInteraction({
                element: "performance",
                action: "lcp_measured",
                value: entry.startTime.toString(),
              });
            }
            break;
        }
      });
    });

    try {
      observer.observe({
        entryTypes: ["navigation", "paint", "largest-contentful-paint"],
      });
    } catch (error) {
      appLogger.warn("Performance Observer not supported:", error);
    }

    // Cleanup observer
    return () => {
      observer.disconnect();
    };
  }, []);
}

/**
 * Hook for measuring component render performance
 */
export function useRenderTracking(componentName: string) {
  const renderStartTime = useRef<number | null>(null);

  useEffect(() => {
    renderStartTime.current = performance.now();

    return () => {
      if (renderStartTime.current) {
        const renderTime = performance.now() - renderStartTime.current;
        telemetryCollector.trackUserInteraction({
          element: componentName,
          action: "component_render",
          value: renderTime.toString(),
        });
      }
    };
  }, [componentName]);
}

/**
 * Hook for tracking form submissions
 */
export function useFormTracking(formName: string) {
  const trackFormStart = useCallback(() => {
    telemetryCollector.trackUserInteraction({
      element: formName,
      action: "form_start",
    });
  }, [formName]);

  const trackFormSubmit = useCallback(
    (success: boolean, error?: string) => {
      telemetryCollector.trackUserInteraction({
        element: formName,
        action: success ? "form_submit_success" : "form_submit_error",
        value: error,
      });
    },
    [formName],
  );

  const trackFormField = useCallback(
    (fieldName: string, action: string) => {
      telemetryCollector.trackUserInteraction({
        element: `${formName}_${fieldName}`,
        action: `field_${action}`,
      });
    },
    [formName],
  );

  return { trackFormStart, trackFormSubmit, trackFormField };
}

/**
 * Hook for tracking search functionality
 */
export function useSearchTracking(searchContext: string) {
  const trackSearch = useCallback(
    (query: string, resultCount?: number) => {
      telemetryCollector.trackUserInteraction({
        element: searchContext,
        action: "search_executed",
        value: query,
        target: resultCount?.toString(),
      });
    },
    [searchContext],
  );

  const trackSearchResultClick = useCallback(
    (resultId: string, position: number) => {
      telemetryCollector.trackUserInteraction({
        element: searchContext,
        action: "search_result_click",
        value: resultId,
        target: position.toString(),
      });
    },
    [searchContext],
  );

  return { trackSearch, trackSearchResultClick };
}

/**
 * Hook for tracking navigation between pages/routes
 */
export function useNavigationTracking() {
  const trackNavigation = useCallback(
    (from: string, to: string, method: string) => {
      telemetryCollector.trackUserInteraction({
        element: "navigation",
        action: method,
        target: from,
        value: to,
      });
    },
    [],
  );

  return trackNavigation;
}

/**
 * Hook for tracking error boundaries and caught errors
 */
export function useErrorTracking(componentName: string) {
  const trackError = useCallback(
    (error: Error, errorInfo?: unknown) => {
      telemetryCollector.trackUserInteraction({
        element: componentName,
        action: "error_caught",
        value: error.message,
        target: error.name,
      });
    },
    [componentName],
  );

  return trackError;
}

/**
 * Comprehensive hook that combines multiple tracking capabilities
 */
export function useTelemetry(componentName: string) {
  // Initialize all tracking hooks
  usePageTracking();
  usePerformanceMetrics();
  useRenderTracking(componentName);

  const { trackFeatureUsage: featureTrackUsage } =
    useFeatureTracking(componentName);
  const interactionTracking = useInteractionTracking();
  const formTracking = useFormTracking(componentName);
  const searchTracking = useSearchTracking(componentName);
  const navigationTracking = useNavigationTracking();
  const errorTracking = useErrorTracking(componentName);

  return {
    ...interactionTracking,
    ...formTracking,
    ...searchTracking,
    trackFeatureUsage: featureTrackUsage,
    trackNavigation: navigationTracking,
    trackError: errorTracking,
    telemetryCollector,
  };
}

import { appLogger as logger } from "@/lib/logger";

interface ChatSession {
  id: string;
  title: string | null;
  provider: string;
  model: string | null;
  created_at: string;
  updated_at: string;
  config?: unknown;
}

interface ChatMessage {
  id: string;
  role: "system" | "user" | "assistant" | "tool";
  content: string;
  tool_calls?: unknown;
  tool_results?: unknown;
  metadata?: unknown;
  created_at: string;
}

interface ExportData {
  session: ChatSession;
  messages: ChatMessage[];
}

export function exportToJSON(data: ExportData): string {
  return JSON.stringify(data, null, 2);
}

export function exportToMarkdown(data: ExportData): string {
  const { session, messages } = data;

  let markdown = `# ${session.title || "Conversación"}\n\n`;
  markdown += `**Proveedor:** ${session.provider}\n`;
  markdown += `**Modelo:** ${session.model || "N/A"}\n`;
  markdown += `**Fecha de creación:** ${new Date(session.created_at).toLocaleString("es-ES")}\n`;
  markdown += `**Última actualización:** ${new Date(session.updated_at).toLocaleString("es-ES")}\n\n`;
  markdown += `---\n\n`;

  messages.forEach((message, index) => {
    const timestamp = new Date(message.created_at).toLocaleString("es-ES");
    const roleLabel =
      {
        system: "Sistema",
        user: "Usuario",
        assistant: "Asistente",
        tool: "Herramienta",
      }[message.role] || message.role;

    markdown += `## ${roleLabel} - ${timestamp}\n\n`;

    if (message.tool_calls) {
      markdown += `**Herramientas ejecutadas:**\n`;
      if (Array.isArray(message.tool_calls)) {
        message.tool_calls.forEach((tc: unknown) => {
          markdown += `- ${tc.name || "Unknown"}\n`;
        });
      }
      markdown += `\n`;
    }

    if (message.role === "assistant" || message.role === "user") {
      markdown += `${message.content}\n\n`;
    } else if (message.role === "tool") {
      markdown += `\`\`\`json\n${JSON.stringify(message.content, null, 2)}\n\`\`\`\n\n`;
    }

    if (message.tool_results) {
      markdown += `**Resultados:**\n`;
      markdown += `\`\`\`json\n${JSON.stringify(message.tool_results, null, 2)}\n\`\`\`\n\n`;
    }

    if (index < messages.length - 1) {
      markdown += `---\n\n`;
    }
  });

  return markdown;
}

export function exportToTXT(data: ExportData): string {
  const { session, messages } = data;

  let text = `${session.title || "Conversación"}\n`;
  text += `${"=".repeat(50)}\n\n`;
  text += `Proveedor: ${session.provider}\n`;
  text += `Modelo: ${session.model || "N/A"}\n`;
  text += `Fecha de creación: ${new Date(session.created_at).toLocaleString("es-ES")}\n`;
  text += `Última actualización: ${new Date(session.updated_at).toLocaleString("es-ES")}\n\n`;
  text += `${"=".repeat(50)}\n\n`;

  messages.forEach((message) => {
    const timestamp = new Date(message.created_at).toLocaleString("es-ES");
    const roleLabel =
      {
        system: "[SISTEMA]",
        user: "[USUARIO]",
        assistant: "[ASISTENTE]",
        tool: "[HERRAMIENTA]",
      }[message.role] || `[${message.role.toUpperCase()}]`;

    text += `${roleLabel} - ${timestamp}\n`;
    text += `${"-".repeat(50)}\n`;
    text += `${message.content}\n\n`;

    if (message.tool_calls) {
      text += `Herramientas ejecutadas:\n`;
      if (Array.isArray(message.tool_calls)) {
        message.tool_calls.forEach((tc: unknown) => {
          text += `  - ${tc.name || "Unknown"}\n`;
        });
      }
      text += `\n`;
    }

    if (message.tool_results) {
      text += `Resultados:\n${JSON.stringify(message.tool_results, null, 2)}\n\n`;
    }

    text += `\n`;
  });

  return text;
}

export function exportToCSV(data: ExportData): string {
  const { session, messages } = data;

  let csv = "Rol,Fecha,Hora,Contenido,Herramientas\n";

  messages.forEach((message) => {
    const date = new Date(message.created_at);
    const dateStr = date.toLocaleDateString("es-ES");
    const timeStr = date.toLocaleTimeString("es-ES");

    const roleLabel =
      {
        system: "Sistema",
        user: "Usuario",
        assistant: "Asistente",
        tool: "Herramienta",
      }[message.role] || message.role;

    const content = message.content.replace(/"/g, '""').replace(/\n/g, " ");
    const tools = message.tool_calls
      ? Array.isArray(message.tool_calls)
        ? message.tool_calls
            .map((tc: unknown) => tc.name || "Unknown")
            .join("; ")
        : ""
      : "";

    csv += `"${roleLabel}","${dateStr}","${timeStr}","${content}","${tools}"\n`;
  });

  return csv;
}

export function downloadFile(
  content: string,
  filename: string,
  mimeType: string,
) {
  const blob = new Blob([content], { type: mimeType });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
}

export async function copyToClipboard(
  data: ExportData,
  format: "json" | "markdown" | "txt" | "csv",
): Promise<boolean> {
  let content: string;

  switch (format) {
    case "json":
      content = exportToJSON(data);
      break;
    case "markdown":
      content = exportToMarkdown(data);
      break;
    case "txt":
      content = exportToTXT(data);
      break;
    case "csv":
      content = exportToCSV(data);
      break;
  }

  try {
    await navigator.clipboard.writeText(content);
    return true;
  } catch (error) {
    logger.error("Failed to copy to clipboard:", error);
    // Fallback for older browsers
    try {
      const textArea = document.createElement("textarea");
      textArea.value = content;
      textArea.style.position = "fixed";
      textArea.style.left = "-999999px";
      textArea.style.top = "-999999px";
      document.body.appendChild(textArea);
      textArea.focus();
      textArea.select();
      const successful = document.execCommand("copy");
      document.body.removeChild(textArea);
      return successful;
    } catch (fallbackError) {
      logger.error("Fallback copy failed:", fallbackError);
      return false;
    }
  }
}

export function exportConversation(
  data: ExportData,
  format: "json" | "markdown" | "txt" | "csv",
) {
  const { session } = data;
  const timestamp = new Date().toISOString().split("T")[0];
  const title = (session.title || "conversacion")
    .toLowerCase()
    .replace(/[^a-z0-9]/g, "-");

  let content: string;
  let filename: string;
  let mimeType: string;

  switch (format) {
    case "json":
      content = exportToJSON(data);
      filename = `${title}-${timestamp}.json`;
      mimeType = "application/json";
      break;
    case "markdown":
      content = exportToMarkdown(data);
      filename = `${title}-${timestamp}.md`;
      mimeType = "text/markdown";
      break;
    case "txt":
      content = exportToTXT(data);
      filename = `${title}-${timestamp}.txt`;
      mimeType = "text/plain";
      break;
    case "csv":
      content = exportToCSV(data);
      filename = `${title}-${timestamp}.csv`;
      mimeType = "text/csv";
      break;
  }

  downloadFile(content, filename, mimeType);
}

/**
 * Utilidades compartidas para formateo de datos
 *
 * Este módulo centraliza funciones de formateo que se usan repetidamente
 * en toda la aplicación, reduciendo duplicación de código.
 *
 * @module lib/utils/formatting
 */

/**
 * Opciones de localización para formateo
 */
export type Locale = "es-CL" | "es-AR" | "es-ES";

/** Zona horaria por defecto para ópticas en Chile */
const DEFAULT_TIMEZONE = "America/Santiago";

/**
 * Opciones para formateo de fechas
 */
export interface DateFormatOptions {
  locale?: Locale;
  includeTime?: boolean;
  includeYear?: boolean;
  format?: "short" | "medium" | "long" | "full";
  /** Zona horaria para mostrar la fecha (default: America/Santiago) */
  timeZone?: string;
}

/**
 * Opciones para formateo de moneda
 */
export interface CurrencyFormatOptions {
  locale?: Locale;
  currency?: string;
  minimumFractionDigits?: number;
  maximumFractionDigits?: number;
}

/**
 * Formatea una fecha según las opciones especificadas
 *
 * @param date - Fecha a formatear (string ISO, Date object, o timestamp)
 * @param options - Opciones de formateo
 * @returns Fecha formateada como string
 *
 * @example
 * formatDate('2024-01-15') // '15/1/2024'
 * formatDate('2024-01-15', { includeTime: true }) // '15/1/2024, 10:30'
 * formatDate('2024-01-15', { format: 'long' }) // '15 de enero de 2024'
 */
export function formatDate(
  date: string | Date | number | null | undefined,
  options: DateFormatOptions = {},
): string {
  if (!date) {
    return "Sin fecha";
  }

  try {
    const dateObj =
      typeof date === "string" || typeof date === "number"
        ? new Date(date)
        : date;

    if (isNaN(dateObj.getTime())) {
      return "Sin fecha";
    }

    const {
      locale = "es-CL",
      includeTime = false,
      includeYear = true,
      format = "short",
      timeZone = DEFAULT_TIMEZONE,
    } = options;

    const formatOptions: Intl.DateTimeFormatOptions = {};

    switch (format) {
      case "short":
        formatOptions.day = "numeric";
        formatOptions.month = "numeric";
        if (includeYear) {
          formatOptions.year = "numeric";
        }
        break;
      case "medium":
        formatOptions.day = "numeric";
        formatOptions.month = "short";
        if (includeYear) {
          formatOptions.year = "numeric";
        }
        break;
      case "long":
        formatOptions.day = "numeric";
        formatOptions.month = "long";
        if (includeYear) {
          formatOptions.year = "numeric";
        }
        break;
      case "full":
        formatOptions.weekday = "long";
        formatOptions.day = "numeric";
        formatOptions.month = "long";
        if (includeYear) {
          formatOptions.year = "numeric";
        }
        break;
    }

    if (includeTime) {
      formatOptions.hour = "2-digit";
      formatOptions.minute = "2-digit";
    }
    formatOptions.timeZone = timeZone;

    return dateObj.toLocaleDateString(locale, formatOptions);
  } catch (error) {
    return "Sin fecha";
  }
}

/**
 * Formatea una fecha con formato relativo (Hoy, Ayer, o fecha completa)
 *
 * @param date - Fecha a formatear
 * @param locale - Locale a usar (default: 'es-ES')
 * @returns Fecha formateada con formato relativo
 *
 * @example
 * formatRelativeDate('2024-01-15') // 'Hoy' si es hoy, 'Ayer' si fue ayer, o '15 de enero' si es otra fecha
 */
export function formatRelativeDate(
  date: string | Date | number | null | undefined,
  locale: Locale = "es-ES",
): string {
  if (!date) {
    return "Sin fecha";
  }

  try {
    const dateObj =
      typeof date === "string" || typeof date === "number"
        ? new Date(date)
        : date;

    if (isNaN(dateObj.getTime())) {
      return "Sin fecha";
    }

    const today = new Date();
    const yesterday = new Date(today);
    yesterday.setDate(yesterday.getDate() - 1);

    if (dateObj.toDateString() === today.toDateString()) {
      return "Hoy";
    } else if (dateObj.toDateString() === yesterday.toDateString()) {
      return "Ayer";
    } else {
      return dateObj.toLocaleDateString(locale, {
        day: "numeric",
        month: "long",
        year:
          dateObj.getFullYear() !== today.getFullYear() ? "numeric" : undefined,
      });
    }
  } catch (error) {
    return "Sin fecha";
  }
}

/**
 * Formatea un número como moneda
 *
 * @param amount - Cantidad a formatear
 * @param options - Opciones de formateo
 * @returns Cantidad formateada como moneda
 *
 * @example
 * formatCurrency(10000) // '$10.000' (CLP)
 * formatCurrency(10000, { locale: 'es-AR', currency: 'ARS' }) // '$10.000' (ARS)
 * formatCurrency(10000.50, { maximumFractionDigits: 2 }) // '$10.000,50'
 */
export function formatCurrency(
  amount: number | null | undefined,
  options: CurrencyFormatOptions = {},
): string {
  if (amount === null || amount === undefined || isNaN(amount)) {
    return "$0";
  }

  const {
    locale = "es-CL",
    currency = "CLP",
    minimumFractionDigits = 0,
    maximumFractionDigits = 0,
  } = options;

  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    minimumFractionDigits,
    maximumFractionDigits,
  }).format(amount);
}

/**
 * Formatea un número como precio (sin símbolo de moneda, solo formato numérico)
 *
 * @param price - Precio a formatear
 * @param locale - Locale a usar (default: 'es-CL')
 * @returns Precio formateado
 *
 * @example
 * formatPrice(10000) // '10.000'
 * formatPrice(10000.50) // '10.000,50'
 */
export function formatPrice(
  price: number | null | undefined,
  locale: Locale = "es-CL",
): string {
  if (price === null || price === undefined || isNaN(price)) {
    return "0";
  }

  return new Intl.NumberFormat(locale, {
    minimumFractionDigits: 0,
    maximumFractionDigits: 2,
  }).format(price);
}

/**
 * Formatea un número con separadores de miles
 *
 * @param number - Número a formatear
 * @param locale - Locale a usar (default: 'es-CL')
 * @returns Número formateado
 *
 * @example
 * formatNumber(10000) // '10.000'
 * formatNumber(1000000) // '1.000.000'
 */
export function formatNumber(
  number: number | null | undefined,
  locale: Locale = "es-CL",
): string {
  if (number === null || number === undefined || isNaN(number)) {
    return "0";
  }

  return new Intl.NumberFormat(locale).format(number);
}

/**
 * Formatea una fecha y hora completa
 *
 * @param dateTime - Fecha y hora a formatear
 * @param locale - Locale a usar (default: 'es-CL')
 * @returns Fecha y hora formateada
 *
 * @example
 * formatDateTime('2024-01-15T10:30:00') // '15/1/2024, 10:30'
 */
export function formatDateTime(
  dateTime: string | Date | number | null | undefined,
  locale: Locale = "es-CL",
  timeZone: string = DEFAULT_TIMEZONE,
): string {
  if (!dateTime) {
    return "Sin fecha";
  }

  try {
    const dateObj =
      typeof dateTime === "string" || typeof dateTime === "number"
        ? new Date(dateTime)
        : dateTime;

    if (isNaN(dateObj.getTime())) {
      return "Sin fecha";
    }

    return dateObj.toLocaleString(locale, {
      day: "numeric",
      month: "numeric",
      year: "numeric",
      hour: "2-digit",
      minute: "2-digit",
      timeZone,
    });
  } catch (error) {
    return "Sin fecha";
  }
}

/**
 * Formatea un tiempo relativo (hace X minutos, hace X horas, etc.)
 *
 * @param date - Fecha a comparar
 * @param locale - Locale a usar (default: 'es-ES')
 * @returns Tiempo relativo formateado
 *
 * @example
 * formatTimeAgo(new Date(Date.now() - 30000)) // 'Hace 30 segundos'
 * formatTimeAgo(new Date(Date.now() - 3600000)) // 'Hace 1 hora'
 */
export function formatTimeAgo(
  date: string | Date | number | null | undefined,
  locale: Locale = "es-ES",
): string {
  if (!date) {
    return "Sin fecha";
  }

  try {
    const dateObj =
      typeof date === "string" || typeof date === "number"
        ? new Date(date)
        : date;

    if (isNaN(dateObj.getTime())) {
      return "Sin fecha";
    }

    const now = new Date();
    const diffInSeconds = Math.floor(
      (now.getTime() - dateObj.getTime()) / 1000,
    );

    if (diffInSeconds < 60) {
      return "Hace menos de un minuto";
    }

    const diffInMinutes = Math.floor(diffInSeconds / 60);
    if (diffInMinutes < 60) {
      return `Hace ${diffInMinutes} ${diffInMinutes === 1 ? "minuto" : "minutos"}`;
    }

    const diffInHours = Math.floor(diffInMinutes / 60);
    if (diffInHours < 24) {
      return `Hace ${diffInHours} ${diffInHours === 1 ? "hora" : "horas"}`;
    }

    const diffInDays = Math.floor(diffInHours / 24);
    if (diffInDays < 7) {
      return `Hace ${diffInDays} ${diffInDays === 1 ? "día" : "días"}`;
    }

    const diffInWeeks = Math.floor(diffInDays / 7);
    if (diffInWeeks < 4) {
      return `Hace ${diffInWeeks} ${diffInWeeks === 1 ? "semana" : "semanas"}`;
    }

    const diffInMonths = Math.floor(diffInDays / 30);
    if (diffInMonths < 12) {
      return `Hace ${diffInMonths} ${diffInMonths === 1 ? "mes" : "meses"}`;
    }

    const diffInYears = Math.floor(diffInDays / 365);
    return `Hace ${diffInYears} ${diffInYears === 1 ? "año" : "años"}`;
  } catch (error) {
    return "Sin fecha";
  }
}

