import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";

import { appLogger as logger } from "@/lib/logger";

/**
 * Validation Middleware Utilities
 *
 * Provides middleware wrappers for consistent validation handling in API routes.
 * These utilities automatically handle validation errors and return appropriate
 * HTTP responses.
 *
 * @module lib/validation/middleware
 */

/**
 * Middleware wrapper for validating request bodies
 *
 * Automatically parses and validates request body against provided schema.
 * Handles validation errors and returns appropriate HTTP responses.
 *
 * @template T - Zod schema type
 * @param schema - Zod schema to validate against
 * @param handler - Handler function that receives validated data
 * @returns Next.js API route handler
 *
 * @example
 * ```typescript
 * export const POST = withBodyValidation(
 *   z.object({
 *     email: z.string().email(),
 *     name: z.string().min(1)
 *   }),
 *   async (validatedData, request) => {
 *     // validatedData is typed and guaranteed to match schema
 *     const user = await createUser(validatedData);
 *     return NextResponse.json(user);
 *   }
 * );
 * ```
 */
export function withBodyValidation<T extends z.ZodTypeAny>(
  schema: T,
  handler: (
    validatedData: z.infer<T>,
    request: NextRequest,
  ) => Promise<NextResponse>,
) {
  return async (request: NextRequest): Promise<NextResponse> => {
    try {
      const body = await request.json();
      const validatedData = schema.parse(body);
      return await handler(validatedData, request);
    } catch (error) {
      if (error instanceof z.ZodError) {
        logger.warn("Body validation failed", {
          errors: error.errors.map((e) => ({
            path: e.path.join("."),
            message: e.message,
          })),
        });

        return NextResponse.json(
          {
            error: "Validation failed",
            details: error.errors.map((e) => ({
              field: e.path.join("."),
              message: e.message,
            })),
          },
          { status: 400 },
        );
      }

      // Re-throw non-validation errors
      throw error;
    }
  };
}

/**
 * Middleware wrapper for validating query parameters
 *
 * Automatically validates URL search parameters against provided schema.
 *
 * @template T - Zod schema type
 * @param schema - Zod schema to validate against
 * @param handler - Handler function that receives validated data
 * @returns Next.js API route handler
 *
 * @example
 * ```typescript
 * export const GET = withQueryValidation(
 *   z.object({
 *     page: z.number().min(1).default(1),
 *     limit: z.number().min(1).max(100).default(10)
 *   }),
 *   async (validatedParams, request) => {
 *     const { page, limit } = validatedParams;
 *     const users = await getUsers(page, limit);
 *     return NextResponse.json(users);
 *   }
 * );
 * ```
 */
export function withQueryValidation<T extends z.ZodTypeAny>(
  schema: T,
  handler: (
    validatedParams: z.infer<T>,
    request: NextRequest,
  ) => Promise<NextResponse>,
) {
  return async (request: NextRequest): Promise<NextResponse> => {
    try {
      const url = new URL(request.url);
      const params: Record<string, string> = {};

      // Extract all search parameters
      for (const [key, value] of url.searchParams.entries()) {
        params[key] = value;
      }

      // Convert string values to appropriate types for validation
      const parsedParams = convertSearchParams(params);
      const validatedParams = schema.parse(parsedParams);

      return await handler(validatedParams, request);
    } catch (error) {
      if (error instanceof z.ZodError) {
        logger.warn("Query parameter validation failed", {
          errors: error.errors.map((e) => ({
            path: e.path.join("."),
            message: e.message,
          })),
        });

        return NextResponse.json(
          {
            error: "Invalid query parameters",
            details: error.errors.map((e) => ({
              field: e.path.join("."),
              message: e.message,
            })),
          },
          { status: 400 },
        );
      }

      // Re-throw non-validation errors
      throw error;
    }
  };
}

/**
 * Middleware wrapper for validating path parameters
 *
 * Automatically validates dynamic route parameters against provided schema.
 *
 * @template T - Zod schema type
 * @param schema - Zod schema to validate against
 * @param handler - Handler function that receives validated data
 * @returns Next.js API route handler
 *
 * @example
 * ```typescript
 * export async function GET(
 *   request: NextRequest,
 *   { params }: { params: { id: string } }
 * ) {
 *   return withPathValidation(
 *     z.object({
 *       id: z.string().uuid()
 *     }),
 *     async (validatedParams, request) => {
 *       const { id } = validatedParams;
 *       const user = await getUserById(id);
 *       return NextResponse.json(user);
 *     }
 *   )(request, { params });
 * }
 * ```
 */
export function withPathValidation<T extends z.ZodTypeAny>(
  schema: T,
  handler: (
    validatedParams: z.infer<T>,
    request: NextRequest,
  ) => Promise<NextResponse>,
) {
  return async (
    request: NextRequest,
    context: { params: Record<string, string | string[]> },
  ): Promise<NextResponse> => {
    try {
      const validatedParams = schema.parse(context.params);
      return await handler(validatedParams, request);
    } catch (error) {
      if (error instanceof z.ZodError) {
        logger.warn("Path parameter validation failed", {
          errors: error.errors.map((e) => ({
            path: e.path.join("."),
            message: e.message,
          })),
        });

        return NextResponse.json(
          {
            error: "Invalid path parameters",
            details: error.errors.map((e) => ({
              field: e.path.join("."),
              message: e.message,
            })),
          },
          { status: 400 },
        );
      }

      // Re-throw non-validation errors
      throw error;
    }
  };
}

/**
 * Combined validation middleware
 *
 * Validates body, query parameters, and path parameters in one wrapper.
 *
 * @template B - Body schema type
 * @template Q - Query schema type
 * @template P - Path schema type
 */
export function withValidation<
  B extends z.ZodTypeAny,
  Q extends z.ZodTypeAny,
  P extends z.ZodTypeAny,
>(
  schemas: {
    body?: B;
    query?: Q;
    path?: P;
  },
  handler: (
    validatedData: {
      body?: z.infer<B>;
      query?: z.infer<Q>;
      path?: z.infer<P>;
    },
    request: NextRequest,
  ) => Promise<NextResponse>,
) {
  return async (
    request: NextRequest,
    context?: { params: Record<string, string | string[]> },
  ): Promise<NextResponse> => {
    try {
      const validatedData: unknown = {};

      // Validate body if schema provided
      if (schemas.body) {
        const body = await request.json();
        validatedData.body = schemas.body.parse(body);
      }

      // Validate query if schema provided
      if (schemas.query) {
        const url = new URL(request.url);
        const params: Record<string, string> = {};
        for (const [key, value] of url.searchParams.entries()) {
          params[key] = value;
        }
        const parsedParams = convertSearchParams(params);
        validatedData.query = schemas.query.parse(parsedParams);
      }

      // Validate path if schema provided
      if (schemas.path && context?.params) {
        validatedData.path = schemas.path.parse(context.params);
      }

      return await handler(validatedData, request);
    } catch (error) {
      if (error instanceof z.ZodError) {
        logger.warn("Combined validation failed", {
          errors: error.errors.map((e) => ({
            path: e.path.join("."),
            message: e.message,
          })),
        });

        return NextResponse.json(
          {
            error: "Validation failed",
            details: error.errors.map((e) => ({
              field: e.path.join("."),
              message: e.message,
            })),
          },
          { status: 400 },
        );
      }

      // Re-throw non-validation errors
      throw error;
    }
  };
}

/**
 * Helper function to convert search parameters to appropriate types
 *
 * Attempts to convert string values to numbers, booleans, etc. for better validation
 */
function convertSearchParams(
  params: Record<string, string>,
): Record<string, unknown> {
  const converted: Record<string, unknown> = {};

  for (const [key, value] of Object.entries(params)) {
    // Try to convert to number
    if (/^-?\d+(\.\d+)?$/.test(value)) {
      const num = parseFloat(value);
      converted[key] = Number.isInteger(num) ? parseInt(value, 10) : num;
      continue;
    }

    // Try to convert to boolean
    if (value.toLowerCase() === "true" || value.toLowerCase() === "false") {
      converted[key] = value.toLowerCase() === "true";
      continue;
    }

    // Keep as string
    converted[key] = value;
  }

  return converted;
}

// Export types
export type { z };

import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";

import { ValidationError } from "./errors";
export { ValidationError };
import { logger } from "@/lib/logger";

/**
 * Helpers para usar Zod en rutas API de Next.js
 *
 * Este módulo proporciona funciones convenientes para validar
 * request bodies, query parameters y path parameters usando Zod.
 * Todas las funciones incluyen logging automático de errores y
 * manejo consistente de excepciones.
 *
 * @module lib/api/validation/zod-helpers
 *
 * @example
 * ```typescript
 * import { parseAndValidateBody } from '@/lib/api/validation/zod-helpers'
 * import { createProductSchema } from '@/lib/api/validation/zod-schemas'
 *
 * export async function POST(request: NextRequest) {
 *   const data = await parseAndValidateBody(request, createProductSchema)
 *   // data está validado y tipado correctamente
 * }
 * ```
 */

/**
 * Valida un objeto usando un schema Zod (para cuando el body ya fue parseado)
 *
 * Esta función es útil cuando ya tienes el objeto parseado y solo necesitas validarlo.
 * Para validar directamente desde un Request, usa `parseAndValidateBody`.
 *
 * @template T - Tipo del schema Zod (inferido automáticamente)
 * @param body - Objeto ya parseado a validar
 * @param schema - Schema Zod para validar el body
 * @returns Datos validados y parseados con el tipo inferido del schema
 * @throws {ValidationError} Si la validación falla, con detalles de los errores
 *
 * @example
 * ```typescript
 * const body = await request.json()
 * const validated = validateBody(body, createProductSchema)
 * // validated tiene el tipo correcto según createProductSchema
 * ```
 *
 * @see {@link parseAndValidateBody} Para validar directamente desde un Request
 */
export function validateBody<T extends z.ZodTypeAny>(
  body: unknown,
  schema: T,
): z.infer<T> {
  try {
    const validated = schema.parse(body);
    return validated;
  } catch (error) {
    if (error instanceof z.ZodError) {
      const errors = error.errors.map((err) => ({
        field: err.path.join("."),
        message: err.message,
      }));

      logger.warn(
        {
          errors: errors.map((e) => `${e.field}: ${e.message}`).join(", "),
          body: JSON.stringify(body),
        },
        "Validation failed",
      );

      throw new ValidationError(
        `Validation failed: ${errors.map((e) => `${e.field}: ${e.message}`).join(", ")}`,
        errors,
      );
    }

    // Log unexpected errors
    if (error instanceof Error) {
      logger.error(error, "Unexpected error in validateBody", {
        body: JSON.stringify(body),
      });
    } else {
      logger.error(
        new Error(String(error)),
        "Unexpected error in validateBody",
        {
          body: JSON.stringify(body),
        },
      );
    }

    throw error;
  }
}

/**
 * Valida y parsea el body de una request usando un schema Zod
 *
 * Esta es la función más común para validar request bodies en API routes.
 * Combina el parsing del JSON y la validación en un solo paso.
 *
 * @template T - Tipo del schema Zod (inferido automáticamente)
 * @param request - Objeto NextRequest de Next.js
 * @param schema - Schema Zod para validar el body
 * @returns Promise que resuelve con los datos validados y parseados
 * @throws {ValidationError} Si el JSON es inválido o la validación falla
 *
 * @example
 * ```typescript
 * export async function POST(request: NextRequest) {
 *   const data = await parseAndValidateBody(request, createProductSchema)
 *   // data está validado y tipado
 *   await createProduct(data)
 * }
 * ```
 */
export async function parseAndValidateBody<T extends z.ZodTypeAny>(
  request: NextRequest,
  schema: T,
): Promise<z.infer<T>> {
  try {
    const body = await request.json();
    return validateBody(body, schema);
  } catch (error) {
    if (error instanceof ValidationError) {
      throw error;
    }

    if (error instanceof SyntaxError) {
      throw new ValidationError("Invalid JSON in request body");
    }

    throw error;
  }
}

/**
 * Valida query parameters usando un schema Zod
 *
 * Convierte automáticamente los query parameters de strings a sus tipos apropiados
 * según el schema (números, booleanos, etc.).
 *
 * @template T - Tipo del schema Zod (inferido automáticamente)
 * @param request - Objeto NextRequest de Next.js
 * @param schema - Schema Zod para validar los query parameters
 * @returns Query parameters validados y parseados con tipos correctos
 * @throws {ValidationError} Si la validación falla
 *
 * @example
 * ```typescript
 * const query = parseAndValidateQuery(request, z.object({
 *   page: z.coerce.number().min(1),
 *   limit: z.coerce.number().min(1).max(100),
 *   search: z.string().optional()
 * }))
 * // query.page y query.limit son números, no strings
 * ```
 */
export function parseAndValidateQuery<T extends z.ZodTypeAny>(
  request: NextRequest,
  schema: T,
): z.infer<T> {
  try {
    const searchParams = request.nextUrl.searchParams;
    const params: Record<string, string | string[]> = {};

    // Convertir URLSearchParams a objeto
    searchParams.forEach((value, key) => {
      if (params[key]) {
        // Si ya existe, convertir a array
        if (Array.isArray(params[key])) {
          (params[key] as string[]).push(value);
        } else {
          params[key] = [params[key] as string, value];
        }
      } else {
        params[key] = value;
      }
    });

    const validated = schema.parse(params);
    return validated;
  } catch (error) {
    if (error instanceof z.ZodError) {
      const errors = error.errors.map((err) => ({
        field: err.path.join("."),
        message: err.message,
      }));

      logger.warn(
        {
          errors: errors.map((e) => `${e.field}: ${e.message}`).join(", "),
        },
        "Query validation failed",
      );

      throw new ValidationError(
        `Query validation failed: ${errors.map((e) => `${e.field}: ${e.message}`).join(", ")}`,
        errors,
      );
    }

    throw error;
  }
}

/**
 * Valida path parameters usando un schema Zod
 *
 * Útil para validar parámetros de ruta dinámicos (ej: `/api/products/[id]`).
 *
 * @template T - Tipo del schema Zod (inferido automáticamente)
 * @param params - Objeto con los path parameters (típicamente de `params` en route handlers)
 * @param schema - Schema Zod para validar los path parameters
 * @returns Path parameters validados y parseados
 * @throws {ValidationError} Si la validación falla
 *
 * @example
 * ```typescript
 * export async function GET(
 *   request: NextRequest,
 *   { params }: { params: { id: string } }
 * ) {
 *   const { id } = parseAndValidateParams(params, z.object({
 *     id: z.string().uuid()
 *   }))
 *   // id está validado como UUID
 * }
 * ```
 */
export function parseAndValidateParams<T extends z.ZodTypeAny>(
  params: Record<string, string | string[] | undefined>,
  schema: T,
): z.infer<T> {
  try {
    const validated = schema.parse(params);
    return validated;
  } catch (error) {
    if (error instanceof z.ZodError) {
      const errors = error.errors.map((err) => ({
        field: err.path.join("."),
        message: err.message,
      }));

      logger.warn(
        {
          errors: errors.map((e) => `${e.field}: ${e.message}`).join(", "),
        },
        "Path params validation failed",
      );

      throw new ValidationError(
        `Path params validation failed: ${errors.map((e) => `${e.field}: ${e.message}`).join(", ")}`,
        errors,
      );
    }

    throw error;
  }
}

/**
 * Middleware wrapper para manejar errores de validación automáticamente
 *
 * Envuelve un handler de API route con validación automática del body.
 * Si la validación falla, retorna una respuesta 400 con los errores.
 * Si hay un error inesperado, retorna 500.
 *
 * @template T - Tipo del schema Zod
 * @param schema - Schema Zod para validar el body del request
 * @param handler - Función handler que recibe los datos validados y el request
 * @returns Handler envuelto que maneja validación y errores automáticamente
 *
 * @example
 * ```typescript
 * export const POST = withValidation(
 *   createProductSchema,
 *   async (data, request) => {
 *     // data está validado y tipado
 *     const product = await createProduct(data)
 *     return NextResponse.json(product)
 *   }
 * )
 * ```
 */
export function withValidation<T extends z.ZodTypeAny>(
  schema: T,
  handler: (
    validatedData: z.infer<T>,
    request: NextRequest,
  ) => Promise<NextResponse>,
) {
  return async (request: NextRequest): Promise<NextResponse> => {
    try {
      const validatedData = await parseAndValidateBody(request, schema);
      return await handler(validatedData, request);
    } catch (error) {
      if (error instanceof ValidationError) {
        return NextResponse.json(
          {
            error: error.message,
            details: error.details || undefined,
          },
          { status: 400 },
        );
      }

      if (error instanceof Error) {
        logger.error(error, "Unexpected error in validation handler");
      } else {
        logger.error(
          new Error(String(error)),
          "Unexpected error in validation handler",
        );
      }
      return NextResponse.json(
        { error: "Internal server error" },
        { status: 500 },
      );
    }
  };
}

/**
 * Helper para crear respuestas de error de validación consistentes
 *
 * Convierte errores de validación (ValidationError o ZodError) en respuestas
 * HTTP 400 con formato consistente.
 *
 * @param error - Error de validación (ValidationError o ZodError)
 * @returns NextResponse con status 400 y detalles del error
 *
 * @example
 * ```typescript
 * try {
 *   const data = await parseAndValidateBody(request, schema)
 * } catch (error) {
 *   return validationErrorResponse(error)
 * }
 * ```
 */
export function validationErrorResponse(
  error: ValidationError | z.ZodError,
): NextResponse {
  if (error instanceof ValidationError) {
    return NextResponse.json(
      {
        error: error.message,
        details: error.details || undefined,
      },
      { status: 400 },
    );
  }

  if (error instanceof z.ZodError) {
    const errors = error.errors.map((err) => ({
      field: err.path.join("."),
      message: err.message,
    }));

    return NextResponse.json(
      {
        error: "Validation failed",
        details: errors,
      },
      { status: 400 },
    );
  }

  return NextResponse.json({ error: "Validation error" }, { status: 400 });
}

/**
 * Context Resolver: phone_number_id + wa_id → organization_id, branch_id, role
 * Resuelve quién escribe (admin o customer) y a qué organización pertenece
 */

import type { SupabaseClient } from "@supabase/supabase-js";

import { appLogger as logger } from "@/lib/logger";

export interface WhatsAppContext {
  waId: string;
  organizationId: string;
  branchId: string | null;
  phoneNumberId: string;
  userId?: string;
  customerId?: string;
  role: "admin" | "customer";
}

/**
 * Normaliza wa_id o teléfono para comparación E.164-like
 * Meta wa_id: 56912345678 (sin +)
 * customers.phone puede tener +56, espacios, guiones
 */
export function normalizePhoneForWhatsApp(phone: string): string {
  return phone.replace(/\D/g, "");
}

/**
 * Normaliza para comparación: ambos a dígitos.
 * Chile: si es 9 dígitos empezando en 9, se considera 56+9 dígitos
 */
function normalizeForComparison(phone: string): string {
  const digits = phone.replace(/\D/g, "");
  if (digits.length === 9 && digits.startsWith("9")) {
    return "56" + digits;
  }
  return digits;
}

/**
 * Resuelve el contexto de un mensaje WhatsApp entrante
 * 1. phone_number_id → whatsapp_phone_numbers → organization_id
 * 2. wa_id → customers (phone) o admin_users+profiles (phone) → role, branch_id
 */
export async function resolveWhatsAppContext(
  waId: string,
  phoneNumberId: string,
  supabase: SupabaseClient,
): Promise<WhatsAppContext | null> {
  const normalizedWaId = normalizeForComparison(waId);

  // 1. Resolver organization_id desde phone_number_id
  const { data: wpn, error: wpnError } = await supabase
    .from("whatsapp_phone_numbers")
    .select("organization_id")
    .eq("phone_number_id", phoneNumberId)
    .single();

  if (wpnError || !wpn) {
    logger.warn("WhatsApp context: phone_number_id not found", {
      phoneNumberId,
      error: wpnError?.message,
    });
    return null;
  }

  const organizationId = wpn.organization_id;

  // 2. Buscar si wa_id es un customer (phone en customers de esa org)
  const { data: customers } = await supabase
    .from("customers")
    .select("id, branch_id, phone")
    .eq("organization_id", organizationId)
    .not("phone", "is", null);

  const matchingCustomer = customers?.find((c) => {
    if (!c.phone) return false;
    const normalized = normalizeForComparison(c.phone);
    return normalized === normalizedWaId;
  });

  if (matchingCustomer) {
    return {
      waId,
      organizationId,
      branchId: matchingCustomer.branch_id,
      phoneNumberId,
      customerId: matchingCustomer.id,
      role: "customer",
    };
  }

  // 3. Buscar si wa_id es un admin (profiles.phone + admin_users)
  const { data: profiles } = await supabase
    .from("profiles")
    .select("id, phone")
    .not("phone", "is", null);

  const matchingProfile = profiles?.find((p) => {
    if (!p.phone) return false;
    const normalized = normalizeForComparison(p.phone);
    return normalized === normalizedWaId;
  });

  if (matchingProfile) {
    const { data: adminUser } = await supabase
      .from("admin_users")
      .select("id, organization_id")
      .eq("id", matchingProfile.id)
      .eq("is_active", true)
      .single();

    if (adminUser && adminUser.organization_id === organizationId) {
      const { data: branchAccess } = await supabase
        .from("admin_branch_access")
        .select("branch_id")
        .eq("admin_user_id", adminUser.id)
        .eq("is_primary", true)
        .limit(1)
        .single();

      return {
        waId,
        organizationId,
        branchId: branchAccess?.branch_id ?? null,
        phoneNumberId,
        userId: adminUser.id,
        role: "admin",
      };
    }
  }

  // 4. No encontrado: tratar como customer anónimo (solo org conocida)
  // El adapter puede responder con mensaje "Contacta a la sucursal"
  return {
    waId,
    organizationId,
    branchId: null,
    phoneNumberId,
    role: "customer",
  };
}

/**
 * Validador de firma X-Hub-Signature-256 para webhooks de Meta WhatsApp
 * Meta firma el payload con HMAC-SHA256(rawBody, APP_SECRET)
 *
 * @see https://developers.facebook.com/docs/graph-api/webhooks/getting-started#verification-requests
 */

import crypto from "crypto";

import { appLogger as logger } from "@/lib/logger";

export interface WhatsAppSignatureValidationResult {
  isValid: boolean;
  error?: string;
}

export class WhatsAppSignatureValidator {
  private appSecret: string;

  constructor(appSecret?: string) {
    this.appSecret = appSecret || process.env.WHATSAPP_APP_SECRET || "";
    if (!this.appSecret) {
      logger.warn(
        "WHATSAPP_APP_SECRET not configured. Webhook signature validation will be skipped.",
      );
    }
  }

  /**
   * Valida la firma X-Hub-Signature-256 del webhook de Meta
   * @param rawBody - Body raw del request (string, antes de parsear JSON)
   * @param signatureHeader - Valor del header X-Hub-Signature-256 (sha256=<hex>)
   */
  validate(
    rawBody: string,
    signatureHeader: string | null,
  ): WhatsAppSignatureValidationResult {
    if (!this.appSecret) {
      if (process.env.NODE_ENV === "production") {
        return {
          isValid: false,
          error: "WHATSAPP_APP_SECRET not configured in production",
        };
      }
      logger.warn("WhatsApp webhook signature validation skipped (no secret)");
      return { isValid: true };
    }

    if (!signatureHeader) {
      return {
        isValid: false,
        error: "Missing X-Hub-Signature-256 header",
      };
    }

    try {
      const match = signatureHeader.match(/^sha256=(.+)$/);
      if (!match) {
        return {
          isValid: false,
          error: "Invalid X-Hub-Signature-256 format (expected sha256=<hex>)",
        };
      }

      const expectedSignature = match[1].trim();
      const hmac = crypto.createHmac("sha256", this.appSecret);
      hmac.update(rawBody);
      const computedSignature = hmac.digest("hex");

      if (computedSignature !== expectedSignature) {
        logger.warn("WhatsApp webhook signature mismatch", {
          headerLength: signatureHeader.length,
        });
        return {
          isValid: false,
          error: "Signature mismatch",
        };
      }

      return { isValid: true };
    } catch (error) {
      logger.error(
        "Error validating WhatsApp webhook signature",
        error instanceof Error ? error : new Error(String(error)),
      );
      return {
        isValid: false,
        error: "Validation error",
      };
    }
  }
}

/**
 * Webhook Handler: Parsea payload de Meta y despacha a procesadores
 */

import { processWhatsAppMessage } from "@/lib/ai/agent/whatsapp-adapter";
import { appLogger as logger } from "@/lib/logger";
import { createServiceRoleClient } from "@/utils/supabase/server";

import { WhatsAppClient } from "./client";
import { resolveWhatsAppContext } from "./context-resolver";
import { getOrCreateWhatsAppSession } from "./session-manager";
import type {
  WhatsAppIncomingMessage,
  WhatsAppWebhookPayload,
  WhatsAppWebhookValue,
} from "./types";

export interface ProcessedMessage {
  waId: string;
  phoneNumberId: string;
  messageId: string;
  text: string;
}

/**
 * Procesa el payload del webhook y maneja mensajes entrantes
 */
export async function handleWebhookPayload(
  payload: WhatsAppWebhookPayload,
): Promise<void> {
  if (payload.object !== "whatsapp_business_account") {
    return;
  }

  const entries = payload.entry ?? [];
  for (const entry of entries) {
    const changes = entry.changes ?? [];
    for (const change of changes) {
      if (change.field !== "messages") continue;
      await handleWebhookValue(change.value);
    }
  }
}

async function handleWebhookValue(value: WhatsAppWebhookValue): Promise<void> {
  const messages = value.messages ?? [];
  const phoneNumberId = value.metadata?.phone_number_id;
  if (!phoneNumberId) {
    logger.warn("WhatsApp webhook: missing phone_number_id in metadata");
    return;
  }

  const supabase = createServiceRoleClient();

  for (const msg of messages) {
    const text = extractTextFromMessage(msg);
    if (!text) continue;

    const waId = msg.from;
    const messageId = msg.id;

    const context = await resolveWhatsAppContext(waId, phoneNumberId, supabase);
    if (!context) {
      logger.warn("WhatsApp webhook: could not resolve context", {
        waId,
        phoneNumberId,
      });
      await sendFallbackMessage(phoneNumberId, waId);
      return;
    }

    const sessionId = await getOrCreateWhatsAppSession(
      waId,
      context.organizationId,
      supabase,
    );
    if (!sessionId) {
      logger.error("WhatsApp webhook: could not create session", {
        waId,
        organizationId: context.organizationId,
      });
      await sendFallbackMessage(phoneNumberId, waId);
      return;
    }

    await supabase.from("chat_messages").insert({
      session_id: sessionId,
      role: "user",
      content: text,
      metadata: { channel: "whatsapp", wa_id: waId, message_id: messageId },
    });

    const response = await processWhatsAppMessage(text, context, sessionId);

    await supabase.from("chat_messages").insert({
      session_id: sessionId,
      role: "assistant",
      content: response,
      metadata: { channel: "whatsapp", wa_id: waId },
    });

    const client = WhatsAppClient.forOrganization(phoneNumberId);
    if (client) {
      await client.sendText(waId, response);
    } else {
      logger.error(
        "WhatsApp webhook: could not create client to send response",
        {
          phoneNumberId,
        },
      );
    }
  }
}

function extractTextFromMessage(msg: WhatsAppIncomingMessage): string | null {
  if (msg.type === "text" && msg.text?.body) {
    return msg.text.body.slice(0, 4096);
  }
  const msgAny = msg as { type: string; button?: { text?: string } };
  if (msgAny.type === "button" && msgAny.button?.text) {
    return msgAny.button.text;
  }
  return null;
}

async function sendFallbackMessage(
  phoneNumberId: string,
  waId: string,
): Promise<void> {
  const client = WhatsAppClient.forOrganization(phoneNumberId);
  if (client) {
    await client.sendText(
      waId,
      "Lo siento, no pude identificar tu cuenta. Por favor, contacta directamente a la sucursal.",
    );
  }
}

import { createServerClient } from "@supabase/ssr";
import { createClient } from "@supabase/supabase-js";
import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";

import { CSRF_EXEMPT_PREFIXES, validateCsrfOrigin } from "@/lib/api/csrf";

// ponytail: crypto.randomUUID() ~0.01ms per call, well under 1ms budget
export function buildCspPolicy(
  nonce: string,
  isProduction: boolean,
  supabaseUrl: string,
): string {
  const supabaseDomain = supabaseUrl
    ? new URL(supabaseUrl).origin
    : "https://*.supabase.co";

  const directives = [
    "default-src 'self'",
    `script-src 'self' 'nonce-${nonce}' 'strict-dynamic' https://sdk.mercadopago.com https://http2.mlstatic.com`,
    // ponytail: style-src keeps 'unsafe-inline' because CalendarDayView/CalendarWeekView
    // inject <style> via dangerouslySetInnerHTML. Extract CSS to .module.css before removing.
    `style-src 'self' 'unsafe-inline' https://fonts.googleapis.com`,
    `font-src 'self' https://fonts.gstatic.com https://http2.mlstatic.com data:`,
    `img-src 'self' data: https: blob: ${supabaseDomain}`,
    `connect-src 'self' https: wss: ws: ${supabaseDomain} https://*.supabase.co${supabaseUrl.includes("127.0.0.1") ? " ws://127.0.0.1:54321" : ""}`,
    `frame-src 'self' https://www.mercadopago.com https://www.mercadolibre.com https://http2.mlstatic.com https://secure-fields.mercadopago.com https://www.google.com ${supabaseDomain}`,
    "media-src 'self' https:",
    "object-src 'none'",
    "base-uri 'self'",
    "form-action 'self'",
    "worker-src 'self' blob:",
    "manifest-src 'self'",
  ];

  if (isProduction) directives.push("upgrade-insecure-requests");

  return directives.join("; ");
}

/**
 * Middleware: Refresca la sesión de Supabase y protege rutas /admin
 *
 * IMPORTANTE (docs Supabase): Usar SOLO getUser() para refrescar - getSession() no
 * garantiza revalidar el token. getUser() valida con el servidor y actualiza cookies.
 *
 * 1. getUser() refresca el token si expiró y actualiza cookies vía setAll
 * 2. Para /admin: redirige a login si no hay sesión
 */
export async function middleware(request: NextRequest) {
  const { pathname, searchParams } = request.nextUrl;

  const nonce = crypto.randomUUID();
  // Propagate nonce to server components via request headers
  // Mutate directly so any NextResponse.next({ request }) inherits it (incl. setAll)
  request.headers.set("x-nonce", nonce);

  const isHtmlRoute =
    !pathname.startsWith("/api") &&
    !pathname.startsWith("/_next") &&
    !pathname.match(/\.\w+$/);

  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || "";
  const isProduction = process.env.NODE_ENV === "production";

  // Apply CSP headers to a NextResponse for HTML routes
  function applyCsp(resp: NextResponse): NextResponse {
    if (isHtmlRoute) {
      resp.headers.set(
        "Content-Security-Policy",
        buildCspPolicy(nonce, isProduction, supabaseUrl),
      );
      resp.headers.set("x-nonce", nonce);
    }
    return resp;
  }

  // /acceso-opticas: validar ?token= (DB) o ?key= (DEMO_OPTICAS_ACCESS_KEY fallback)
  if (pathname === "/acceso-opticas") {
    const providedToken = searchParams.get("token");
    const providedKey = searchParams.get("key");

    let valid = false;

    if (providedToken) {
      try {
        const supabase = createClient(
          process.env.NEXT_PUBLIC_SUPABASE_URL!,
          process.env.SUPABASE_SERVICE_ROLE_KEY!,
          { auth: { autoRefreshToken: false, persistSession: false } },
        );
        const { data, error } = await supabase
          .from("opticas_access_tokens")
          .select("id")
          .eq("token", providedToken)
          .gt("expires_at", new Date().toISOString())
          .maybeSingle();
        valid = !error && !!data;
      } catch {
        valid = false;
      }
    }

    if (!valid && providedKey) {
      const secretKey = process.env.DEMO_OPTICAS_ACCESS_KEY;
      valid = !!(
        secretKey &&
        secretKey.length > 0 &&
        providedKey === secretKey
      );
    }

    if (!valid) {
      return NextResponse.redirect(new URL("/", request.url));
    }
  }

  // Rutas excluidas (no requieren verificación de admin)
  const excludedPaths = [
    "/onboarding",
    "/login",
    "/signup",
    "/solicitar-demo",
    "/acceso-opticas",
    "/reset-password",
    "/support",
    "/api",
    "/_next",
    "/favicon.ico",
    "/favicon",
  ];

  if (pathname === "/") {
    return applyCsp(NextResponse.next({ request }));
  }

  const shouldExclude = excludedPaths.some((path) => pathname.startsWith(path));

  // CSRF check — antes de la llamada costosa a Supabase getUser()
  if (!["GET", "HEAD", "OPTIONS"].includes(request.method)) {
    const isExempt = CSRF_EXEMPT_PREFIXES.some((p) => pathname.startsWith(p));
    if (!isExempt) {
      const { valid } = validateCsrfOrigin(request.headers);
      if (!valid) {
        return NextResponse.json(
          { error: "CSRF validation failed" },
          { status: 403 },
        );
      }
    }
  }

  // Crear response y cliente Supabase para refrescar sesión
  let response = NextResponse.next({ request });

  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return request.cookies.getAll();
        },
        setAll(cookiesToSet) {
          // Actualizar request (para downstream) y response (para cliente)
          // Ref: https://supabase.com/docs/guides/auth/server-side/nextjs
          cookiesToSet.forEach(({ name, value }) => {
            request.cookies.set(name, value);
          });
          response = NextResponse.next({ request });
          cookiesToSet.forEach(({ name, value, options }) => {
            response.cookies.set(name, value, options);
          });
        },
      },
    },
  );

  // Refrescar sesión: SOLO getUser() - valida JWT con servidor, refresca si expiró,
  // y dispara setAll para actualizar cookies (persistencia en refresh/nueva pestaña)
  const {
    data: { user },
    error: userError,
  } = await supabase.auth.getUser();

  // Para /admin: redirigir a login si no hay sesión
  if (pathname.startsWith("/admin") && !user) {
    return NextResponse.redirect(new URL("/login", request.url));
  }

  return applyCsp(response);
}

export const config = {
  matcher: ["/((?!_next/static|_next/image|favicon.ico).*)"],
};

import { createBrowserClient } from '@supabase/ssr'

export function createClient() {
  return createBrowserClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
  )
}
